INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Au commencement DIEU créa les cieux et la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Et la terre était sans forme, et vide, et les ténèbres étaient sur la face de l’abîme; et l’Esprit de Dieu se mouvait sur le dessus des eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Et Dieu dit: Que la lumière soit; et la lumière fut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Et Dieu vit que la lumière était bonne; et Dieu sépara la lumière des ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Et Dieu nomma la lumière, jour; et les ténèbres, nuit. Ainsi fut le soir, ainsi fut le matin; ce fut le premier jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Puis Dieu dit: Qu’il y ait une étendue entre les eaux, et qu’elle sépare les eaux d’avec les eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Dieu donc fit l’étendue, et il sépara les eaux qui sont au-dessous de l’étendue, d’avec celles qui sont au-dessus de l’étendue, et il fut ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Et Dieu nomma l’étendue, cieux. Ainsi fut le soir, ainsi fut le matin; ce fut le second jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Puis Dieu dit: Que les eaux qui sont au-dessous des cieux soient rassemblées en un lieu, et que le sec paraisse; et il fut ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Et Dieu nomma le sec, terre; et il nomma l’amas des eaux, mers; et Dieu vit que cela était bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Puis Dieu dit: Que la terre pousse son jet, de l’herbe portant de la semence, et des arbres fruitiers, portant du fruit selon leur espèce, qui aient leur semence en eux-mêmes sur la terre; et il fut ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'La terre donc produisit son jet, savoir de l’herbe portant de la semence selon son espèce; et des arbres portant du fruit, qui avaient leur semence en eux-mêmes, selon leur espèce; et Dieu vit que cela était bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Ainsi fut le soir, ainsi fut le matin; ce fut le troisième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Puis Dieu dit: Qu’il y ait des luminaires dans l’étendue des cieux, pour séparer la nuit d’avec le jour, et qui servent de signes pour les saisons, et pour les jours, et pour les années;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'Et qui soient pour luminaires dans l’étendue des cieux, afin d’éclairer la terre; et il fut ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Dieu donc fit deux grands luminaires, le plus grand luminaire pour dominer sur le jour, et le moindre pour dominer sur la nuit; il fit aussi les étoiles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Et Dieu les mit dans l’étendue des cieux pour éclairer la terre,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'Et pour dominer sur le jour et sur la nuit, et pour séparer la lumière des ténèbres; et Dieu vit que cela était bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Ainsi fut le soir, ainsi fut le matin; ce fut le quatrième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Puis Dieu dit: Que les eaux produisent en toute abondance des reptiles qui aient vie; et qu’il y ait des oiseaux, qui volent sur la terre vers l’étendue des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Dieu donc créa les grandes baleines et tous les animaux se mouvant, lesquels les eaux produisirent en toute abondance, selon leur espèce; il créa aussi tout oiseau ayant des ailes, selon son espèce; et Dieu vit que cela était bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Et Dieu les bénit, en disant: Croissez et multipliez, et remplissez les eaux dans les mers, et que les oiseaux multiplient sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Ainsi fut le soir, ainsi fut le matin; ce fut le cinquième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Puis Dieu dit: Que la terre produise des animaux selon leur espèce, le bétail, les reptiles, et les bêtes de la terre selon leur espèce; et il fut ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Dieu donc fit les bêtes de la terre selon leur espèce, et le bétail selon son espèce, et les reptiles de la terre selon leur espèce; et Dieu vit que cela était bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Puis Dieu dit: Faisons l’homme à notre image, selon notre ressemblance, et qu’il domine sur les poissons de la mer, et sur les oiseaux des cieux, et sur le bétail, et sur toute la terre, et sur tout reptile qui rampe sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Dieu donc créa l’homme à son image, il le créa à l’image de Dieu, il les créa mâle et femelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Et Dieu les bénit, et leur dit: Croissez, et multipliez, et remplissez la terre; et l’assujettissez, et dominez sur les poissons de la mer, et sur les oiseaux des cieux, et sur toute bête qui se meut sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Et Dieu dit: Voici, je vous ai donné toute herbe portant semence qui est sur toute la terre, et tout arbre qui a en soi-même du fruit d’arbre portant semence, et cela vous sera pour nourriture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Mais j’ai donné à toutes les bêtes de la terre, et à tous les oiseaux des cieux et à toute chose qui se meut sur la terre, ayant vie en soi-même, toute herbe verte pour manger; et il fut ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Et Dieu vit tout ce qu’il avait fait, et voilà il était très-bon; ainsi fut le soir, ainsi fut le matin; ce fut le sixième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Les cieux donc et la terre furent achevés, avec toute leur armée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Et Dieu eut achevé au septième jour son oeuvre qu’il avait faite, et il se reposa au septième jour de toute son oeuvre qu’il avait faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Et Dieu bénit le septième jour, et le sanctifia, parce qu’en ce jour-là il s’était reposé de toute son oeuvre qu’il avait créée pour être faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Telles sont les origines des cieux et de la terre, lorsqu’ils furent créés; quand l’Eternel Dieu fit la terre et les cieux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Et toutes les plantes des champs, avant qu’il y en eût en la terre, et toutes les herbes des champs, avant qu’elles eussent poussé; car l’Eternel Dieu n’avait point fait pleuvoir sur la terre, et il n’y avait point d’homme pour labourer la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Et il ne montait point de vapeur de la terre, qui arrosât toute la surface de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Or l’Eternel Dieu avait formé l’homme de la poudre de la terre, et il avait soufflé dans ses narines une respiration de vie; et l’homme fut fait en âme vivante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Aussi l’Eternel Dieu avait planté un jardin en Héden, du coté d’Orient, et y avait mis l’homme qu’il avait formé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Et l’Eternel Dieu avait fait germer de la terre tout arbre désirable à la vue, et bon à manger, et l’arbre de vie au milieu du jardin, et l’arbre de la science du bien et du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Et un fleuve sortait d’Héden pour arroser le jardin; et de là il se divisait en quatre bras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Le nom du premier est Pison; c’est le fleuve qui coule en tournoyant par tout le pays de Havila, où il se trouve de l’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Et l’or de ce pays-là est bon; c’est là aussi que se trouve le Bdellion, et la pierre d’Onyx.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Et le nom du second fleuve est Guihon; c’est celui qui coule en tournoyant par tout le pays de Cus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Et le nom du troisième fleuve est Hiddekel, qui coule vers l’Assyrie; et le quatrième fleuve est l’Euphrate.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'L’Eternel Dieu prit donc l’homme et le mit dans le jardin d’Héden pour le cultiver, et pour le garder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Puis l’Eternel Dieu commanda à l’homme, en disant: Tu mangeras librement de tout arbre du jardin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Mais quant à l’arbre de la science du bien et du mal, tu n’en mangeras point; car dès le jour que tu en mangeras, tu mourras de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Or l’Eternel Dieu avait dit: Il n’est pas bon que l’homme soit seul; je lui ferai une aide semblable à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Car l’Eternel Dieu avait formé de la terre toutes les bêtes des champs et tous les oiseaux des cieux, puis il les avait fait venir vers Adam, afin qu’il vît comment il les nommerait, et afin que le nom qu’Adam donnerait à tout animal, fût son nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Et Adam donna les noms à tout le bétail, et aux oiseaux des cieux, et à toutes les bêtes des champs, mais il ne se trouvait point d’aide pour Adam, qui fût semblable à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Et l’Eternel Dieu fit tomber un profond sommeil sur Adam, et il s’endormit; et Dieu prit une de ses côtes, et resserra la chair dans la place de cette côte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Et l’Eternel Dieu fit une femme de la côte qu’il avait prise d’Adam, et la fit venir vers Adam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Alors Adam dit: A cette fois celle-ci est os de mes os, et chair de ma chair; on la nommera hommesse, parce qu’elle a été prise de l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'C’est pourquoi l’homme laissera son père et sa mère, et se joindra à sa femme, et ils seront une même chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Or Adam et sa femme étaient tous deux nus, et ils ne le prenaient point à honte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Or le serpent était le plus fin de tous les animaux des champs que l’Eternel Dieu avait faits; et il dit à la femme: Quoi! Dieu a dit, vous ne mangerez point de tout arbre du jardin?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Et la femme répondit au serpent: Nous mangeons du fruit des arbres du jardin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Mais quant au fruit de l’arbre qui est au milieu du jardin, Dieu a dit: Vous n’en mangerez point, et vous ne le toucherez point, de peur que vous ne mouriez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Alors le serpent dit à la femme: Vous ne mourrez nullement;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Mais Dieu sait qu’au jour que vous en mangerez, vos yeux seront ouverts, et vous serez comme des Dieux, sachant le bien et le mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'La femme donc voyant que le fruit de l’arbre était bon à manger, et qu’il était agréable à la vue, et que cet arbre était désirable pour donner de la science, en prit du fruit, et en mangea, et elle en donna aussi à son mari qui était avec elle, et il en mangea.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Et les yeux de tous deux furent ouverts; ils connurent qu’ils étaient nus, et ils cousirent ensemble des feuilles de figuier, et s’en firent des ceintures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Alors ils ouïrent au vent du jour la voix de l’Eternel Dieu qui se promenait par le jardin; et Adam et sa femme se cachèrent de devant l’Eternel Dieu, parmi les arbres du jardin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Mais l’Eternel Dieu appela Adam, et lui dit: Où es-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Et il répondit: J’ai entendu ta voix dans le jardin, et j’ai craint, parce que j’étais nu, et je me suis caché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Et Dieu dit: Qui t’a montré que tu étais nu? N’as-tu pas mangé du fruit de l’arbre dont je t’avais défendu de manger?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Et Adam répondit: La femme que tu m’as donnée pour être avec moi, m’a donné du fruit de l’arbre, et j’en ai mangé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Et l’Eternel Dieu dit à la femme: Pourquoi as-tu fait cela? Et la femme répondit: Le serpent m’a séduite, et j’en ai mangé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Alors l’Eternel Dieu dit au serpent: Parce que tu as fait cela, tu seras maudit entre tout le bétail, et entre toutes les bêtes des champs; tu marcheras sur ton ventre, et tu mangeras la poussière tous les jours de ta vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Et je mettrai inimitié entre toi et la femme, et entre ta semence et la semence de la femme; cette semence te brisera la tête, et tu lui briseras le talon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Et il dit à la femme: J’augmenterai beaucoup ton travail et ta grossesse; tu enfanteras en travail les enfants; tes désirs se rapporteront à ton mari, et il dominera sur toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Puis il dit à Adam: Parce que tu as obéi à la parole de ta femme, et que tu as mangé du fruit de l’arbre duquel je t’avais commandé, en disant: Tu n’en mangeras point, la terre sera maudite à cause de toi; tu en mangeras les fruits en travail, tous les jours de ta vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Et elle te produira des épines, et des chardons; et tu mangeras l’herbe des champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Tu mangeras le pain à la sueur de ton visage, jusqu’à ce que tu retournes en la terre, car tu en as été pris; parce que tu es poudre, tu retourneras aussi en poudre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Et Adam appela sa femme Eve; parce qu’elle a été la mère de tous les vivants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Et l’Eternel Dieu fit à Adam et à sa femme des robes de peaux, et les en revêtit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Et l’Eternel Dieu dit: Voici, l’homme est devenu comme l’un de nous, sachant le bien et le mal; mais maintenant il faut prendre garde qu’il n’avance sa main, et aussi qu’il ne prenne de l’arbre de vie, et qu’il n’en mange, et ne vive à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Et l’Eternel Dieu le mit hors du jardin d’Héden, pour labourer la terre, de laquelle il avait été pris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Ainsi il chassa l’homme, et mit des Chérubins vers l’Orient du jardin d’Héden, avec une lame d’épée qui se tournait çà et là, pour garder le chemin de l’arbre de vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Or Adam connut Eve sa femme, laquelle conçut, et enfanta Caïn; et elle dit: J’ai acquis un homme de par l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Elle enfanta encore Abel son frère; et Abel fut berger, et Caïn laboureur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Or il arriva, au bout de quelque temps, que Caïn offrit à l’Eternel une oblation des fruits de la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Et qu’Abel aussi offrit des premiers-nés de son troupeau, et de leur graisse; et l’Eternel eut égard à Abel, et à son oblation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Mais il n’eut point d’égard à Caïn, ni à son oblation; et Caïn fut fort irrité, et son visage fut abattu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Et l’Eternel dit à Caïn: Pourquoi es-tu irrité? et pourquoi ton visage est-il abattu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Si tu fais bien, ne sera-t-il pas reçu? mais si tu ne fais pas bien, le péché est à la porte; or ses désirs se rapportent à toi, et tu as Seigneurie sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Or Caïn parla avec Abel son frère, et comme ils étaient aux champs, Caïn s’éleva contre Abel son frère, et le tua.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Et l’Eternel dit à Caïn: Où est Abel ton frère? Et il lui répondit: Je ne sais, suis-je le gardien de mon frère, moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Et Dieu dit: Qu’as-tu fait? La voix du sang de ton frère crie de la terre à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Maintenant donc tu seras maudit, même de la part de la terre, qui a ouvert sa bouche pour recevoir de ta main le sang de ton frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Quand tu laboureras la terre, elle ne te rendra plus son fruit, et tu seras vagabond et fugitif sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Et Caïn dit à l’Eternel: Ma peine est plus grande que je ne puis porter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Voici, tu m’as chassé aujourd’hui de cette terre-ci, et je serai caché de devant ta face, et serai vagabond et fugitif sur la terre, et il arrivera que quiconque me trouvera, me tuera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Et l’Eternel lui dit: C’est pourquoi quiconque tuera Caïn sera puni sept fois davantage. Ainsi l’Eternel mit une marque sur Caïn, afin que quiconque le trouverait, ne le tuât point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Alors Caïn sortit de devant la face de l’Eternel, et habita au pays de Nod, vers l’Orient d’Héden.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Puis Caïn connut sa femme, qui conçut et enfanta Hénoc; et il bâtit une ville, et appela la ville Hénoc, du nom de son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Puis Hirad naquit à Hénoc, et Hirad engendra Méhujaël, et Méhujaël engendra Méthusaël, et Méthusaël engendra Lémec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Et Lémec prit deux femmes; le nom de l’une était Hada, et le nom de l’autre, Tsilla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Et Hada enfanta Jabal, qui fut père de ceux qui demeurent dans les tentes, et des pasteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Et le nom de son frère fut Jubal, qui fut père de tous ceux qui touchent le violon et les orgues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Et Tsilla aussi enfanta Tubal-Caïn, qui fut forgeur de toute sorte d’instruments d’airain et de fer; et la soeur de Tubal-Caïn fut Nahama.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Et Lémec dit à Hada et à Tsilla ses femmes: Femmes de Lémec, entendez ma voix, écoutez ma parole; je tuerai un homme, moi étant blessé, même un jeune homme, moi étant meurtri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Car si Caïn est vengé sept fois davantage, Lémec le sera soixante-dix sept fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Et Adam connut encore sa femme, qui enfanta un fils, et il appela son nom Seth, car Dieu m’a, dit-il, donné un autre fils au lieu d’Abel, que Caïn a tué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Il naquit aussi un fils à Seth, et il l’appela Enos. Alors on commença d’appeler du nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'C’est ici le dénombrement de la postérité d’Adam, depuis le jour que Dieu créa l’homme, lequel il fit à sa ressemblance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Il les créa mâle et femelle, et les bénit, et il leur donna le nom d’homme, le jour qu’ils furent créés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Et Adam vécut cent trente ans, et engendra un fils à sa ressemblance, selon son image, et le nomma Seth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Et les jours d’Adam, après qu’il eut engendré Seth, furent huit cents ans, et il engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Tout le temps donc qu’Adam vécut, fut neuf cent trente ans; puis il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Seth aussi vécut cent cinq ans, et engendra Enos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Et Seth, après qu’il eut engendré Enos, vécut huit cent sept ans; et il engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Tout le temps donc que Seth vécut, fut neuf cent douze ans; puis il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Et Enos, ayant vécu quatre-vingt-dix ans, engendra Kénan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Et Enos, après qu’il eut engendré Kénan, vécut huit cent quinze ans, et il engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Tout le temps donc qu’Enos vécut, fut neuf cent cinq ans; puis il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Et Kénan ayant vécu soixante-dix ans, engendra Mahalaléel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Et Kénan, après qu’il eut engendré Mahalaléel, vécut huit cent quarante ans; et il engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Tout le temps donc que Kénan vécut, fut neuf cent dix ans; puis il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Et Mahalaléel vécut soixante-cinq ans; et il engendra Jéred.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Et Mahalaléel, après qu’il eut engendré Jéred, vécut huit cent trente ans, et il engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Tout le temps donc que Mahalaléel vécut, fut huit cent quatre- vingt quinze ans; puis il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Et Jéred ayant vécu cent soixante-deux ans, engendra Hénoc.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Et Jéred, après avoir engendré Hénoc, vécut huit cents ans, et il engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Tout le temps donc que Jéred vécut, fut neuf cent soixante-deux ans; puis il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Et Hénoc vécut soixante-cinq ans, et engendra Méthuséla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Et Hénoc, après qu’il eut engendré Méthuséla, marcha avec Dieu trois cents ans; et il engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Tout le temps donc qu’Hénoc vécut, fut trois cent soixante-cinq ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Hénoc marcha avec Dieu; mais il ne parut plus, parce que Dieu le prit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Et Méthuséla ayant vécu cent quatre-vingt sept ans, engendra Lémec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Et Méthuséla, après qu’il eut engendré Lémec, vécut sept cent quatre-vingt-deux ans; et il engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Tout le temps donc que Méthuséla vécut, fut neuf cent soixante- neuf ans; puis il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Lémec aussi vécut cent quatre-vingt deux ans, et il engendra un fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Et il le nomma Noé, en disant: Celui-ci nous soulagera de notre oeuvre, et du travail de nos mains, sur la terre que l’Eternel a maudite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Et Lémec, après qu’il eut engendré Noé, vécut cinq cent quatre- vingt quinze ans; et il engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Tout le temps donc que Lémec vécut, fut sept cent soixante dix- sept ans; puis il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Et Noé, âgé de cinq cents ans, engendra Sem, Cam, et Japheth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Or il arriva que quand les hommes eurent commencé à se multiplier sur la terre, et qu’ils eurent engendré des filles,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Les fils de Dieu voyant que les filles des hommes étaient belles, prirent pour leurs femmes de toutes celles qu’ils choisirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Et l’Eternel dit: Mon Esprit ne plaidera point à toujours avec les hommes, car aussi ils ne sont que chair; mais leurs jours seront six vingts ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Il y avait en ce temps-là des géants sur la terre, lors, dis-je, que les fils de Dieu se furent joints avec les filles des hommes, et qu’elles leur eurent fait des enfants. Ce sont ces puissants hommes qui de tout temps ont été des gens de renom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Et l’Eternel voyant que la malice des hommes était très-grande sur la terre, et que toute l’imagination des pensées de leur coeur n’était que mal en tout temps;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Se repentit d’avoir fait l’homme sur la terre, et en eut du déplaisir dans son coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Et l’Eternel dit: J’exterminerai de dessus la terre les hommes que j’ai créés, depuis les hommes jusqu’au bétail, jusqu’aux reptiles, et même jusqu’aux oiseaux des cieux; car je me repens de les avoir faits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Mais Noé trouva grâce devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Ce sont ici les générations de Noé. Noé fut un homme juste et intègre en son temps, marchant avec Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Et Noé engendra trois fils, Sem, Cam, et Japheth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Et la terre était corrompue devant Dieu, et remplie d’extorsion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Dieu donc regarda la terre, et voici elle était corrompue; car toute chair avait corrompu sa voie sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Et Dieu dit à Noé: La fin de toute chair est venue devant moi; car ils ont rempli la terre d’extorsion, et voici, je les détruirai avec la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Fais-toi une arche de bois de gopher; tu feras l’arche par loges, et la calfeutreras de bitume par dedans et par dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Et tu la feras en cette manière; la longueur de l’arche sera de trois cents coudées; sa largeur de cinquante coudées, et sa hauteur de trente coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Tu donneras du jour à l’arche, et feras son comble d’une coudée de hauteur, et tu mettras la porte de l’arche à son coté, et tu la feras avec un bas, un second, et un troisième étage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Et voici, je ferai venir un déluge d’eau sur la terre, pour détruire toute chair en laquelle il y a esprit de vie sous les cieux; et tout ce qui est sur la terre expirera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Mais j’établirai mon alliance avec toi; et tu entreras dans l’arche toi et tes fils, et ta femme, et les femmes de tes fils avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Et de tout ce qui a vie d’entre toute chair tu en feras entrer deux de chaque espèce dans l’arche, pour les conserver en vie avec toi, savoir le mâle et la femelle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Des oiseaux, selon leur espèce des bêtes à quatre pieds, selon leur espèce, et de tous reptiles, selon leur espèce. Il y entrera de tous par paires avec toi, afin que tu les conserves en vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Prends aussi avec toi de toute chose qu’on mange, et la retire à toi, afin qu’elle serve pour ta nourriture, et pour celle des animaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Et Noé fit selon tout ce que Dieu lui avait commandé; il le fit ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Et l’Eternel dit à Noé: Entre, toi et toute ta maison, dans l’arche; car je t’ai vu juste devant moi en ce temps-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Tu prendras de toutes les bêtes nettes sept de chaque espèce, le mâle et sa femelle; mais des bêtes qui ne sont point nettes, un couple, le mâle et la femelle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Tu prendras aussi des oiseaux des cieux sept de chaque espèce, le mâle et sa femelle; afin d’en conserver la race sur toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Car dans sept jours je ferai pleuvoir sur la terre pendant quarante jours et quarante nuits; et j’exterminerai de dessus la terre toute chose qui subsiste, laquelle j’ai faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Et Noé fit selon tout ce que l’Eternel lui avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Or Noé était âgé de six cents ans quand le déluge des eaux vint sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Noé donc entra, et avec lui ses fils, sa femme, et les femmes de ses fils, dans l’arche, à cause des eaux du déluge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Des bêtes nettes, et des bêtes qui ne sont point nettes, et des oiseaux, et de tout ce qui se meut sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'Elles entrèrent deux à deux vers Noé dans l’arche, le mâle et la femelle, comme Dieu avait commandé à Noé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Et il arriva qu’au septième jour les eaux du déluge furent sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'En l’an six cent de la vie de Noé au second mois, le dix-septième jour du mois, en ce jour-là toutes les fontaines du grand abîme furent rompues, et les bondes des cieux furent ouvertes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Et la pluie tomba sur la terre pendant quarante jours et quarante nuits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'En ce même jour Noé, et Sem, Cam, et Japheth, fils de Noé, entrèrent dans l’arche, avec la femme de Noé, et les trois femmes de ses fils avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Eux, et toutes les bêtes selon leur espèce, et tout bétail selon son espèce, et tous les reptiles qui se meuvent sur la terre, selon leur espèce, et tous les oiseaux, selon leur espèce; et tout petit oiseau ayant des ailes, de quelque sorte que ce soit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Il vint donc de toute chair qui a en soi esprit de vie, par couples à Noé, dans l’arche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Le mâle, dis-je, et la femelle de toute chair y vinrent, comme Dieu lui avait commandé; puis l’Eternel ferma l’arche sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Et le déluge vint pendant quarante jours sur la terre; et les eaux crurent, et élevèrent l’arche, et elle fut élevée au-dessus de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Et les eaux se renforcèrent, et s’accrurent fort sur la terre, et l’arche flottait au-dessus des eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Les eaux donc se renforcèrent extraordinairement sur la terre, et toutes les plus hautes montagnes qui sont sous tous les cieux, en furent couvertes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Les eaux se renforcèrent de quinze coudées par-dessus, et les montagnes en furent couvertes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Et toute chair qui se mouvait sur la terre expira, tant des oiseaux que du bétail, des bêtes à quatre pieds, et de tous les reptiles qui se traînent sur la terre, et tous les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Toutes les choses qui étaient sur le sec, ayant respiration de vie en leurs narines, moururent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Tout ce donc qui subsistait sur la terre fut donc exterminé, depuis les hommes jusques aux bêtes, jusques aux reptiles, et jusques aux oiseaux des cieux; ils furent, dis-je, exterminés de dessus la terre; mais seulement Noé, et ce qui était avec lui dans l’arche, demeura de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Et les eaux se maintinrent sur la terre durant cent cinquante jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Or Dieu se souvint de Noé, et de toutes les bêtes, et de tout le bétail qui était avec lui dans l’arche; et Dieu fit passer un vent sur la terre, et les eaux s’arrêtèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Car les sources de l’abîme, et les bondes des cieux avaient été refermées, et la pluie des cieux avait été retenue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Et au bout de cent cinquante jours les eaux se retirèrent sans interruption de dessus la terre, et diminuèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Et le dix-septième jour du septième mois l’arche s’arrêta sur les montagnes d’Ararat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Et les eaux allèrent en diminuant de plus en plus jusqu’au dixième mois; et au premier jour du dixième mois les sommets des montagnes se montrèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Et il arriva qu’au bout de quarante jours Noé ouvrit la fenêtre de l’arche qu’il avait faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'Et il lâcha le corbeau, qui sortit allant et revenant, jusqu’à ce que les eaux se fussent desséchées sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Il lâcha aussi d’avec soi un pigeon, pour voir si les eaux étaient allégées sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Mais le pigeon ne trouvant pas sur quoi poser la plante de son pied, retourna à lui dans l’arche; car les eaux étaient sur toute la terre; et Noé avançant sa main le reprit, et le retira à soi dans l’arche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Et quand il eut attendu encore sept autres jours, il lâcha encore le pigeon hors de l’arche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Et sur le soir le pigeon revint à lui; et voici il avait dans son bec une feuille d’olivier qu’il avait arrachée; et Noé connut que les eaux étaient diminuées de dessus la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Et il attendit encore sept autres jours, puis il lâcha le pigeon, qui ne retourna plus à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Et il arriva qu’en l’an six cent et un de l’âge de Noé, au premier jour du premier mois les eaux se furent desséchées de dessus la terre; et Noé ôtant la couverture de l’arche, regarda, et voici, la surface de la terre se séchait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Et au vingt-septième jour du second mois la terre fut sèche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Puis Dieu parla à Noé, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Sors de l’arche, toi et ta femme, tes fils, et les femmes de tes fils avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Fais sortir avec toi toutes les bêtes qui sont avec toi, de toute chair, tant des oiseaux que des bêtes à quatre pieds, et tous les reptiles qui rampent sur la terre; qu’ils peuplent en abondance la terre, et qu’ils foisonnent et multiplient sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Noé donc sortit, et avec lui ses fils, sa femme, et les femmes de ses fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Toutes les bêtes à quatre pieds, tous les reptiles, tous les oiseaux, tout ce qui se meut sur la terre, selon leurs espèces, sortirent de l’arche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Et Noé bâtit un autel à l’Eternel, et prit de toute bête nette, et de tout oiseau net, et il en offrit des holocaustes sur l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Et l’Eternel flaira une odeur d’apaisement, et dit en son coeur; je ne maudirai plus la terre à l’occasion des hommes, quoique l’imagination du coeur des hommes soit mauvaise dès leur jeunesse; et je ne frapperai plus toute chose vivante, comme j’ai fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Mais tant que la terre sera, les semailles et les moissons, le froid et le chaud, l’été et l’hiver, le jour et la nuit ne cesseront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Et Dieu bénit Noé, et ses fils, et leur dit: Foisonnez, et multipliez, et remplissez la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Et que toutes les bêtes de la terre, tous les oiseaux des cieux, avec tout ce qui se meut sur la terre, et tous les poissons de la mer vous craignent et vous redoutent; ils sont mis entre vos mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Tout ce qui se meut et qui a vie, vous sera pour viande; je vous ai donné toutes ces choses comme l’herbe verte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Toutefois vous ne mangerez point de chair avec son âme, c’est-à- dire, son sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Et certes je redemanderai votre sang, le sang de vos âmes, je le redemanderai de la main de toutes les bêtes, et de la main de l’homme, même de la main de chacun de ses frères je redemanderai l’âme de l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Celui qui aura répandu le sang de l’homme dans l’homme, son sang sera répandu; car Dieu a fait l’homme à son image.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Vous donc, foisonnez, multipliez, croissez en toute abondance sur la terre, et multipliez sur elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Dieu parla aussi à Noé et à ses fils qui étaient avec lui, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Et quant à moi, voici, j’établis mon alliance avec vous, et avec votre race après vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'Et avec tout animal vivant qui est avec vous, tant des oiseaux, que du bétail, et de toutes les bêtes de la terre qui sont avec vous, de toutes celles qui sont sorties de l’arche, jusqu’à toutes les bêtes de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'J’établis donc mon alliance avec vous, et nulle chair ne sera plus exterminée par les eaux du déluge, et il n’y aura plus de déluge pour détruire la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Puis Dieu dit: C’est ici le signe que je donne de l’alliance entre moi et vous, et entre toute créature vivante qui est avec vous, pour durer à toujours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Je mettrai mon arc en la nuée, et il sera pour signe de l’alliance entre moi et la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Et quand il arrivera que j’aurai couvert la terre de nuées, l’arc paraîtra dans la nuée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'Et je me souviendrai de mon alliance qui est entre moi et vous, entre tout animal qui vit en quelque chair que ce soit; et les eaux ne feront plus de déluge pour détruire toute chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'L’arc donc sera dans la nuée, et je le regarderai, afin qu’il me souvienne de l’alliance perpétuelle entre Dieu et tout animal vivant, en quelque chair qui soit sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Dieu donc dit à Noé: C’est là le signe de l’alliance que j’ai établie entre moi et toute chair qui est sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Et les fils de Noé qui sortirent de l’arche, furent Sem, Cam, et Japheth. Et Cam fut père de Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Ce sont là les trois fils de Noé, desquels toute la terre fut peuplée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Et Noé, laboureur de la terre, commença de planter la vigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Et il en but du vin, et s’enivra, et il se découvrit au milieu de sa tente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Et Cam, le père de Canaan, ayant vu la nudité de son père, le déclara dehors à ses deux frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Et Sem et Japheth prirent un manteau qu’ils mirent sur leurs deux épaules, et marchant en arrière, ils couvrirent la nudité de leur père; et leurs visages étaient tournés en arrière, de sorte qu’ils ne virent point la nudité de leur père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Et Noé réveillé de son vin, sut ce que son fils le plus petit lui avait fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'C’est pourquoi il dit: Maudit soit Canaan; il sera serviteur des serviteurs de ses frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Il dit aussi: Béni soit l’Eternel, Dieu de Sem; et que Canaan leur soit fait serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Que Dieu attire en douceur Japheth, et que Japheth loge dans les tabernacles de Sem; et que Canaan leur soit fait serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Et Noé vécut après le déluge trois cent cinquante ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Tout le temps donc que Noé vécut, fut neuf cent cinquante ans; puis il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Or ce sont ici les générations des enfants de Noé, Sem, Cam et Japheth; auxquels naquirent des enfants après le déluge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Les enfants de Japheth sont Gomer, Magog, Madaï, Javan, Tubal, Mésech, et Tiras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Et les enfants de Gomer, Askénaz, Riphath, et Thogarma.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Et les enfants de Javan, Elisa, Tarsis, Kittim, et Dodanim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'De ceux-là furent divisées les Iles des nations par leurs terres, chacun selon sa langue, selon leurs familles, entre leurs nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Et les enfants de Cam sont Cus, Mitsraïm, Put, et Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Et les enfants de Cus: Séba, Havila, Sabtah, Rahma, et Sebtéca. Et les enfants de Rahma, Séba, et Dédan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Cus engendra aussi Nimrod, qui commença d’être puissant sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Il fut un puissant chasseur devant l’Eternel; c’est pourquoi l’on a dit: Comme Nimrod, le puissant chasseur devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Et le commencement de son règne fut Babel, Erec, Accad, et Calné au pays de Sinhar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'De ce pays-là sortit Assur, et il bâtit Ninive, et les rues de la ville, et Calah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'Et Résen, entre Ninive et Calah, qui est une grande ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Mitsraïm engendra Ludim, Hanamim, Léhabim, Naphtuhim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Pathrusim, Chasluhim, desquels sont issus les Philistins, et Caphtorim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Et Canaan engendra Sidon, son fils aîné, et Heth,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'Les Jébusiens, les Amorrhéens, les Guirgasiens,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Les Héviens, les Harkiens, et les Siniens,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Les Arvadiens, les Tsémariens, et les Hamathiens. Et ensuite les familles des Cananéens se sont dispersées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Et les limites des Cananéens furent depuis Sidon, quand on vient vers Guérar, jusqu’à Gaza, en tirant vers Sodome et Gomorrhe, Adma, et Tséboïm, jusqu’à Lésa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Ce sont là les enfants de Cam selon leurs familles et leurs langues, en leurs pays, et en leurs nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Et il naquit des enfants à Sem, père de tous les enfants d’Héber, et frère de Japheth, qui était le plus grand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Et les enfants de Sem sont Hélam, Assur, Arpacsad, Lud, et Aram.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Et les enfants d’Aram, Hus, Hul, Guéther et Mas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Et Arpacsad engendra Sélah, et Sélah engendra Héber.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Et à Héber naquirent deux fils: le nom de l’un fut Péleg, parce qu’en son temps la terre fut partagée; et le nom de son frère fut Joktan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Et Joktan engendra Almodad, Séleph, Hatsarmaveth, et Jérah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadoram, Uzal, Dikla,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Hobal, Abimaël, Séba,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ophir, Havila, et Jobab. Tous ceux-là sont les enfants de Joktan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Et leur demeure était depuis Mésa, quand on vient en Séphar, montagne d’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Ce sont là les enfants de Sem, selon leurs familles et leurs langues, en leurs pays, et en leurs nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Telles sont les familles des enfants de Noé, selon leurs lignées en leurs nations; et de ceux-là ont été divisées les nations sur la terre après le déluge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Alors toute la terre avait un même langage, et une même parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Mais il arriva qu’étant partis d’Orient, ils trouvèrent une campagne au pays de Sinhar, où ils habitèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Et ils se dirent l’un à l’autre: Or ça, faisons des briques, et les cuisons très bien au feu. Ils eurent donc des briques au lieu de pierres, et le bitume leur fut au lieu de mortier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Puis ils dirent: Or ça, bâtissons-nous une ville, et une tour de laquelle le sommet soit jusqu’aux cieux; et acquérons-nous de la réputation, de peur que nous ne soyons dispersés sur toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Alors l’Eternel descendit pour voir la ville et la tour que les fils des hommes bâtissaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Et l’Eternel dit: Voici, ce n’est qu’un seul et même peuple, ils ont un même langage, et ils commencent à travailler; et maintenant rien ne les empêchera d’exécuter ce qu’ils ont projeté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Or ça, descendons, et confondons là leur langage, afin qu’ils n’entendent point le langage l’un de l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Ainsi l’Eternel les dispersa de là par toute la terre, et ils cessèrent de bâtir la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'C’est pourquoi son nom fut appelé Babel; car l’Eternel y confondit le langage de toute la terre, et de là il les dispersa sur toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'C’est ici la postérité de Sem: Sem âgé de cent ans, engendra Arpacsad, deux ans après le déluge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Et Sem après qu’il eut engendré Arpacsad, vécut cinq cents ans, et engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Et Arpacsad vécut trente-cinq ans, et engendra Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Et Arpacsad après qu’il eut engendré Sélah, vécut quatre cent trois ans, et engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Et Sélah ayant vécu trente ans, engendra Héber.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Et Sélah après qu’il eut engendré Héber, vécut quatre cent trois ans, et engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Et Héber ayant vécu trente-quatre ans, engendra Péleg.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Et Héber après qu’il eut engendré Péleg, vécut quatre cent trente ans, et engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Et Péleg ayant vécu trente ans, engendra Réhu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Et Péleg après qu’il eut engendré Réhu, vécut deux cent neuf ans, et engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Et Réhu ayant vécu trente-deux ans, engendra Sérug.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Et Réhu après qu’il eut engendré Sérug, vécut deux cent sept ans, et engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Et Sérug ayant vécu trente ans, engendra Nacor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Et Sérug après qu’il eut engendré Nacor, vécut deux cents ans, et engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Et Nacor ayant vécu vingt-neuf ans, engendra Taré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Et Nacor après qu’il eut engendré Taré, vécut cent dix-neuf ans, et engendra des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Et Taré ayant vécu soixante-dix ans, engendra Abram, Nacor, et Haran.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Et c’est ici la postérité de Taré: Taré engendra Abram, Nacor, et Haran; et Haran engendra Lot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Et Haran mourut en la présence de son père, au pays de sa naissance, à Ur des Chaldéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Et Abram et Nacor prirent chacun une femme. Le nom de la femme d’Abram fut Saraï; et le nom de la femme de Nacor fut Milca, fille de Haran, père de Milca et de Jisca.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Et Saraï était stérile, et n’avait point d’enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Et Taré prit son fils Abram, et Lot fils de son fils, qui était fils de Haran, et Saraï sa belle-fille, femme d’Abram son fils, et ils sortirent ensemble d’Ur des Chaldéens pour aller au pays de Canaan, et ils vinrent jusqu’à Caran, et y demeurèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Et les jours de Taré furent deux cent cinq ans; puis il mourut à Caran.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Or l’Eternel avait dit à Abram: Sors de ton pays, et d’avec ta parenté, et de la maison de ton père, et viens au pays que je te montrerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Et je te ferai devenir une grande nation, et te bénirai, et je rendrai ton nom grand, et tu seras béni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Je bénirai ceux qui te béniront, et je maudirai ceux qui te maudiront; et toutes les familles de la terre seront bénies en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Abram donc partit, comme l’Eternel lui avait dit, et Lot alla avec lui; et Abram était âgé de soixante et quinze ans, quand il sortit de Caran.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Abram prit aussi Saraï sa femme, et Lot fils de son frère, et tout leur bien, qu’ils avaient acquis, et les personnes qu’ils avaient eues à Caran; et ils partirent pour venir au pays de Canaan, auquel ils entrèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Et Abram passa au travers de ce pays-là jusqu’au lieu de Sichem, et jusqu’en la plaine de Moré; et les Cananéens étaient alors dans ce pays-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Et l’Eternel apparut à Abram, et lui dit: Je donnerai ce pays à ta postérité. Et Abram bâtit là un autel à l’Eternel qui lui était apparu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Et il se transporta de là vers la montagne, qui est à l’Orient de Béthel, et y tendit ses tentes, ayant Béthel à l’Occident, et Haï à l’Orient; et il bâtit là un autel à l’Eternel, et invoqua le nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Puis Abram partit de là, marchant et s’avançant vers le Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Mais la famine étant survenue dans le pays, Abram descendit en Egypte pour s’y retirer; car la famine était grande au pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Et il arriva comme il était près d’entrer en Egypte, qu’il dit à Saraï, sa femme: Voici, je sais que tu es une fort belle femme;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'C’est pourquoi il arrivera que quand les Egyptiens t’auront vue, ils diront: C’est la femme de cet homme, et ils me tueront, mais ils te laisseront vivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Dis donc, je te prie, que tu es ma sœur, afin que je sois bien traité à cause de toi, et que, par ton moyen ma vie soit préservée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Il arriva donc qu’aussitôt qu’Abram fut venu en Egypte, les Egyptiens virent que cette femme était fort belle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Les principaux de la cour de Pharaon la virent aussi, et la louèrent devant lui, et elle fut enlevée pour être menée dans la maison de Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Lequel fit du bien à Abram, à cause d’elle; de sorte qu’il en eut des brebis, des boeufs, des ânes, des serviteurs, des servantes, des ânesses, et des chameaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Mais l’Eternel frappa de grandes plaies Pharaon et sa maison, à cause de Saraï femme d’Abram.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Alors Pharaon appela Abram, et lui dit: Qu’est-ce que tu m’as fait? pourquoi ne m’as-tu pas déclaré que c’était ta femme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Pourquoi as-tu dit, c’est ma soeur? car je l’avais prise pour ma femme; mais maintenant, voici ta femme, prends-la, et t’en va.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Et Pharaon ayant donné ordre à ses gens, ils le conduisirent, lui, sa femme, et tout ce qui était à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Abram donc monta d’Egypte vers le Midi, lui, sa femme, et tout ce qui lui appartenait, et Lot avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Et Abram était très riche en bétail, en argent, et en or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Et il s’en retourna en suivant la route qu’il avait tenue du Midi à Béthel, jusqu’au lieu où il avait dressé ses tentes au commencement, entre Béthel et Haï,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'Au même lieu où était l’autel qu’il y avait bâti au commencement, et Abram invoqua là le nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Lot aussi qui marchait avec Abram, avait des brebis, des boeufs, et des tentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Et la terre ne les pouvait porter pour demeurer ensemble; car leur bien était si grand, qu’ils ne pouvaient demeurer l’un avec l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'De sorte qu’il y eut querelle entre les pasteurs du bétail d’Abram, et les pasteurs du bétail de Lot; or en ce temps-là les Cananéens et les Phérésiens demeuraient au pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Et Abram dit à Lot: Je te prie qu’il n’y ait point de dispute entre moi et toi, ni entre mes pasteurs et les tiens; car nous sommes frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Tout le pays n’est-il pas à ta disposition? sépare-toi, je te prie, d’avec moi. Si tu choisis la gauche, je prendrai la droite; et si tu prends la droite, je m’en irai à la gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Et Lot élevant ses yeux, vit toute la plaine du Jourdain qui, avant que l’Eternel eût détruit Sodome et Gomorrhe, était arrosée partout, jusqu’à ce qu’on vienne à Tsohar, comme le jardin de l’Eternel, et comme le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Et Lot choisit pour lui toute la plaine du Jourdain, et alla du coté d’Orient; ainsi ils se séparèrent l’un de l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram demeura au pays de Canaan, et Lot demeura dans les villes de la plaine, et dressa ses tentes jusqu’à Sodome.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Or les habitants de Sodome étaient méchants, et grands pécheurs contre l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Et l’Eternel dit à Abram, après que Lot se fut séparé de lui: Lève maintenant tes yeux, et regarde du lieu où tu es, vers le Septentrion, le Midi, l’Orient, et l’Occident.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Car je te donnerai, et à ta postérité pour jamais, tout le pays que tu vois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Et je ferai que ta postérité sera comme la poussière de la terre; que si quelqu’un peut compter la poussière de la terre, il comptera aussi ta postérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Lève-toi donc, et te promène dans le pays, en sa longueur et en sa largeur; car je te le donnerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Abram donc ayant transporté ses tentes, alla demeurer dans les plaines de Mamré, qui est en Hébron, et il bâtit là un autel à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Or il arriva du temps d’Amraphel Roi de Sinhar, d’Arjoc Roi d’Ellasar, de Kédor-Lahomer Roi d’Hélam, et de Tidhal Roi des nations;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Qu’ils firent la guerre contre Bérah Roi de Sodome, et contre Birsah Roi de Gomorrhe, et contre Sinab Roi d’Adma, et contre Séméber Roi de Tséboïm, et contre le Roi de Bélah, qui est Tsohar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Tous ceux-ci se joignirent dans la vallée de Siddim, qui est la mer salée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Ils avaient été asservis douze ans à Kédor-Lahomer, mais au treizième ils s’étaient révoltés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'A la quatorzième année donc Kédor-Lahomer vint, et les Rois qui étaient avec lui, et ils battirent les Rephaïms en Hastéroth de Carnaïm, et les Zuzins en Ham, et les Emins dans la plaine de Kirjathajim,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'Et les Horiens dans leur montagne de Séhir, jusqu’aux campagnes de Paran, au-dessus du désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Puis ils retournèrent, et vinrent à Hen de Mispat, qui est Kadès; et ils frappèrent tout le pays des Hamalécites et des Amorrhéens qui habitaient dans Hatsatson-Tamar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Alors le Roi de Sodome, le Roi de Gomorrhe, le Roi d’Adma, le Roi de Tséboïm, et le Roi de Bélah, qui est Tsohar, sortirent, et rangèrent leurs troupes contr’eux dans la vallée de Siddim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'C’est-à-dire contre Kédor-Lahomer Roi d’Hélam, et contre Tidhal Roi des nations, et contre Amraphel Roi de Sinhar, et contre Arjoc Roi d’Ellasar, quatre Rois contre cinq.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Or la vallée de Siddim était pleine de puits de bitume; et les Rois de Sodome et de Gomorrhe s’enfuirent, et y tombèrent, et ceux qui étaient demeurés de reste s’enfuirent en la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Ils prirent donc toutes les richesses de Sodome et de Gomorrhe, et tous leurs vivres; puis ils se retirèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Ils prirent aussi Lot, fils du frère d’Abram, qui demeurait dans Sodome, et tout son bien; puis ils s’en allèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Et quelqu’un qui était échappé en vint avertir Abram Hébreu, qui demeurait dans les plaines de Mamré Amorrhéen, frère d’Escol, et frère de Haner, qui avaient fait alliance avec Abram.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Quand donc Abram eut appris que son frère avait été emmené prisonnier, il arma trois cent dix-huit de ses serviteurs, nés dans sa maison, et il poursuivit ces Rois jusqu’à Dan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Et ayant partagé ses troupes, il se jeta sur eux de nuit, lui et ses serviteurs, et les battit, et les poursuivit jusqu’à Hobar, qui est à la gauche de Damas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Et il ramena tout le bien qu’ils avaient pris; il ramena aussi Lot son frère, ses biens, les femmes et le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Et le Roi de Sodome s’en alla au-devant de lui, comme il s’en retournait après la défaite de Kédor-Lahomer, et des Rois qui étaient avec lui, en la vallée de la plaine, qui est la vallée royale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Melchisédec aussi, Roi de Salem, fit apporter du pain et du vin, (or il était Sacrificateur du Dieu Fort, Souverain.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Et il le bénit, en disant: Béni soit Abram par le Dieu Fort, Souverain, possesseur des cieux et de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Et loué soit le Dieu Fort, Souverain, qui a livré tes ennemis entre tes mains. Et Abram lui donna la dixme de tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Et le Roi de Sodome dit à Abram: Donne-moi les personnes, et prends les biens pour toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Et Abram dit au Roi de Sodome: J’ai levé ma main à l’Eternel, le Dieu Fort, Souverain, possesseur des cieux et de la terre, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Si je prends rien de tout ce qui est à toi, depuis un fil jusqu’à une courroie de soulier, afin que tu ne dises point: J’ai enrichi Abram.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'J’excepte seulement ce que les jeunes gens ont mangé, et la part des hommes qui sont venus avec moi, Haner, Escol, et Mamré, qui prendront leur part.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Après ces choses, la parole de l’Eternel fut adressée à Abram dans une vision, en disant: Abram, ne crains point, je suis ton bouclier, et ta grande récompense.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Et Abram répondit: Seigneur Eternel, que me donneras-tu? je m’en vais sans laisser d’enfants après moi, et celui qui a le maniement de ma maison c’est ce Dammésec Elihézer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Abram dit aussi: Voici, tu ne m’as point donné d’enfants; et voilà, le serviteur né dans ma maison, sera mon héritier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Et voici, la parole de l’Eternel lui fut adressée en disant: Celui-ci ne sera point ton héritier; mais celui qui sortira de tes entrailles sera ton héritier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Puis l’ayant fait sortir dehors, il lui dit: Lève maintenant les yeux au ciel, et compte les étoiles, si tu les peux compter; et il lui dit: Ainsi sera ta postérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Et Abram crut à l’Eternel, qui lui imputa cela à justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Et il lui dit: Je suis l’Eternel qui t’ai fait sortir d’Ur des Caldéens, afin de te donner ce pays-ci pour le posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Et il dit: Seigneur Eternel, à quoi connaîtrai-je que je le posséderai?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Et il lui répondit: Prends une génisse de trois ans, et une chèvre de trois ans, et un bélier de trois ans, une tourterelle, et un pigeon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Il prit donc toutes ces choses, et les partagea par le milieu, et mit chaque moitié vis-à-vis l’une de l’autre; mais il ne partagea point les oiseaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Et une volée d’oiseaux descendit sur ces bêtes mortes; mais Abram les chassa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Et il arriva comme le soleil se couchait, qu’un profond sommeil tomba sur Abram, et voici, une frayeur d’une grande obscurité tomba sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Et l’Eternel dit à Abram: Sache comme une chose certaine que ta postérité habitera quatre cents ans comme étrangère dans un pays qui ne lui appartiendra point, et qu’elle sera asservie aux habitants du pays, et sera affligée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Mais aussi je jugerai la nation, à laquelle ils seront asservis, et après cela ils sortiront avec de grands biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Et toi tu t’en iras vers tes pères en paix, et seras enterré en bonne vieillesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Et en la quatrième génération ils retourneront ici; car l’iniquité des Amorrhéens n’est pas encore venue à son comble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Il arriva aussi que le soleil étant couché, il y eut une obscurité toute noire, et voici un four fumant, et un brandon de feu qui passa entre ces choses qui avaient été partagées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'En ce jour-là l’Eternel traita alliance avec Abram, en disant: J’ai donné ce pays à ta postérité, depuis le fleuve d’Egypte jusqu’au grand fleuve, le fleuve d’Euphrate;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Les Kéniens, les Kéniziens, les Kadmoniens,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'Les Héthiens, les Phérésiens, les Réphaïms,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'Les Amorrhéens, les Cananéens, les Guirgasiens, et les Jébusiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Or Saraï femme d’Abram ne lui avait enfanté aucun enfant, mais elle avait une servante Egyptienne, nommée Agar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Et elle dit à Abram: Voici maintenant, l’Eternel m’a rendue stérile; viens, je te prie, vers ma servante, peut-être aurai-je des enfants par elle. Et Abram acquiesça à la parole de Saraï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Alors Saraï, femme d’Abram, prit Agar sa servante Egyptienne, et la donna pour femme à Abram son mari, après qu’il eut demeuré dix ans au pays de Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Il vint donc vers Agar, et elle conçut. Et Agar voyant qu’elle avait conçu, méprisa sa maîtresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Et Saraï dit à Abram: L’outrage qui m’est fait, revient sur toi; je t’ai donné ma servante en ton sein, mais quand elle a vu qu’elle avait conçu, elle m’a méprisée; que l’Eternel en juge entre moi et toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Alors Abram répondit à Saraï: Voici, ta servante est entre tes mains, traite-la comme il te plaira. Saraï donc la maltraita, et Agar s’enfuit de devant elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Mais l’Ange de l’Eternel la trouva auprès d’une fontaine d’eau au désert, près de la fontaine qui est au chemin de Sur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Et il lui dit: Agar, servante de Saraï, d’où viens-tu? et où vas- tu? et elle répondit: Je m’enfuis de devant Saraï ma maîtresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Et l’Ange de l’Eternel lui dit: Retourne à ta maîtresse, et t’humilie sous elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Davantage l’Ange de l’Eternel lui dit: Je multiplierai beaucoup ta postérité, tellement qu’elle ne se pourra nombrer; tant elle sera grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'L’Ange de l’Eternel lui dit aussi: Voici, tu as conçu, et tu enfanteras un fils, que tu appelleras Ismaël, car l’Eternel a ouï ton affliction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Et ce sera un homme farouche comme un âne sauvage; sa main sera contre tous, et la main de tous contre lui; et il habitera à la vue de tous ses frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Alors elle appela le nom de l’Eternel qui lui parlait à elle, tu es le Dieu Fort de vision; car elle dit, n’ai-je pas aussi vu ici après celui qui me voyait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'C’est pourquoi on a appelé ce puits, le puits du vivant qui me voit; lequel est entre Kadès et Béred.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Agar donc enfanta un fils à Abram; et Abram appela le nom de son fils, qu’Agar lui avait enfanté, Ismaël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Or Abram était âgé de quatre-vingt six ans, quand Agar lui enfanta Ismaël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Puis Abram étant âgé de quatre-vingt dix- neuf ans, l’Eternel lui apparut, et lui dit: Je suis le Dieu Fort, Tout-Puissant; marche devant ma face, et sois intègre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Et je mettrai mon alliance entre moi et toi, et je te multiplierai très- abondamment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Alors Abram tomba sur sa face; et Dieu lui parla, et lui dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Quant à moi, voici, mon alliance est avec toi, et tu deviendras père d’une multitude de nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Et ton nom ne sera plus appelé Abram, mais ton nom sera Abraham; car je t’ai établi père d’une multitude de nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Et je te ferai croître très-abondamment; et je te ferai devenir des nations; même des Rois sortiront de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'J’établirai donc mon alliance entre moi et toi, et entre ta postérité après toi en leurs âges, pour être une alliance perpétuelle; afin que je te sois Dieu, et à ta postérité après toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Et je te donnerai, et à ta postérité après toi, le pays où tu demeures comme étranger, savoir tout le pays de Canaan, en possession perpétuelle, et je leur serai Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Dieu dit encore à Abraham: Tu garderas donc mon alliance, toi et ta postérité après toi en leurs âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Et c’est ici mon alliance entre moi et vous, et entre ta postérité après toi, laquelle vous garderez, savoir que tout mâle d’entre vous sera circoncis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Et vous circoncirez la chair de votre prépuce; et cela sera pour signe de l’alliance entre moi et vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Tout enfant mâle de huit jours sera circoncis parmi vous en vos générations, tant celui qui est né dans la maison, que l’ esclave acheté par argent de tout étranger qui n’est point de ta race.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'On ne manquera donc point de circoncire celui qui est né dans ta maison, et celui qui est acheté de ton argent, et mon alliance sera en votre chair, pour être une alliance perpétuelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Et le mâle incirconcis, la chair du prépuce duquel n’aura point été circoncise, sera retranché du milieu de ses peuples, parce qu’il aura violé mon alliance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Dieu dit aussi à Abraham: Quant à Saraï ta femme, tu n’appelleras plus son nom Saraï, mais son nom sera Sara.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Et je la bénirai, et même je te donnerai un fils d’elle. Je la bénirai, et elle deviendra des nations: Et des Rois Chefs de peuples sortiront d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Alors Abraham se prosterna la face en terre, et sourit, disant en son coeur: Naîtrait-il un fils à un homme âgé de cent ans? et Sara âgée de quatre-vingt-dix ans aurait-elle un enfant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Et Abraham dit à Dieu: Je te prie, qu’Ismaël vive devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Et Dieu dit: Certainement Sara ta femme t’enfantera un fils, et tu appelleras son nom Isaac; et j’établirai mon alliance avec lui pour être une alliance perpétuelle pour sa postérité après lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Je t’ai aussi exaucé touchant Ismaël: voici, je l’ai béni, et je le ferai croître et multiplier très-abondamment. Il engendrera douze Princes, et je le ferai devenir une grande nation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Mais j’établirai mon alliance avec Isaac, que Sara t’enfantera l’année qui vient, en cette même saison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Et Dieu ayant achevé de parler, remonta de devant Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Et Abraham prit son fils Ismaël, avec tous ceux qui étaient nés dans sa maison, et tous ceux qu’il avait achetés de son argent, tous les mâles qui étaient des gens de sa maison, et il circoncit la chair de leur prépuce en ce même jour-là, comme Dieu lui avait dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Et Abraham était âgé de quatre-vingt dix-neuf ans, quand il circoncit la chair de son prépuce;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Et Ismaël son fils, était âgé de treize ans, lorsqu’il fut circoncis en la chair de son prépuce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'En ce même jour-là Abraham fut circoncis, et son fils Ismaël aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Et tous les gens de sa maison, tant ceux qui étaient nés en la maison, que ceux qui avaient été achetés des étrangers par argent, furent circoncis avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Puis l’Eternel lui apparut dans les plaines de Mamré, comme il était assis à la porte de sa tente, pendant la chaleur du jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Car levant ses yeux, il regarda: et voici, trois hommes parurent devant lui, et les ayant aperçus, il courut au-devant d’eux de la porte de sa tente, et se prosterna en terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'Et il dit: Mon Seigneur, je te prie, si j’ai trouvé grâce devant tes yeux, ne passe point outre, je te prie, et arrête-toi chez ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Qu’on prenne, je vous prie, un peu d’eau, et lavez vos pieds, et reposez-vous sous un arbre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Et j’apporterai une bouchée de pain pour fortifier votre coeur, après quoi vous passerez outre; car c’est pour cela que vous êtes venus vers votre serviteur. Et ils dirent: Fais ce que tu as dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Abraham donc s’en alla en hâte dans la tente vers Sara, et lui dit: Hâte- toi, prends trois mesures de fleur de farine, pétris- les, et fais des gâteaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Puis Abraham courut au troupeau, et prit un veau tendre et bon, lequel il donna à un serviteur, qui se hâta de l’apprêter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Ensuite il prit du beurre et du lait, et le veau qu’on avait apprêté, et le mit devant eux; et il se tint auprès d’eux sous l’arbre, et ils mangèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Et ils lui dirent: Où est Sara ta femme? Et il répondit: La voilà dans la tente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Et l’un d’entr’eux dit: Je ne manquerai pas de retourner vers toi en ce même temps où nous sommes, et voici, Sara ta femme aura un fils. Et Sara l’écoutait à la porte de la tente qui était derrière lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Or Abraham et Sara étaient vieux, fort avancés en âge; et Sara n’avait plus ce que les femmes ont accoutumé d’avoir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Et Sara rit en soi-même, et dit: Etant vieille, et mon Seigneur étant fort âgé, aurai-je cette satisfaction?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Et l’Eternel dit à Abraham: Pourquoi Sara a-t-elle ri, en disant: Serait- il vrai que j’aurais un enfant, étant vieille comme je suis?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Y a-t-il quelque chose qui soit difficile à l’Eternel? Je retournerai vers toi en cette saison, en ce même temps où nous sommes, et Sara aura un fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Et Sara le nia, en disant: Je n’ai point ri; car elle eut peur. Mais il dit: Cela n’est pas; car tu as ri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Et ces hommes se levèrent de là, et regardèrent vers Sodome; et Abraham marchait avec eux pour les conduire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Et l’Eternel dit: Cacherai-je à Abraham ce que je m’en vais faire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Puis qu’Abraham doit certainement devenir une nation grande et puissante, et que toutes les nations de la terre seront bénies en lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Car je le connais, et je sais qu’il commandera à ses enfants, et à sa maison après lui, de garder la voie de l’Eternel, pour faire ce qui est juste, et droit; afin que l’Eternel fasse venir sur Abraham tout ce qu’il lui a dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Et l’Eternel dit: Parce que le cri de Sodome et de Gomorrhe est augmenté, et que leur péché est fort aggravé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Je descendrai maintenant, et je verrai s’ils ont fait entièrement selon le cri qui est venu jusqu’à moi; et si cela n’est pas, je le saurai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Ces hommes donc partant de là allaient vers Sodome; mais Abraham se tint encore devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Et Abraham s’approcha, et dit: Feras-tu périr le juste même avec le méchant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Peut-être y a-t-il cinquante justes dans la ville, les feras-tu périr aussi? Ne pardonneras-tu point à la ville, à cause des cinquante justes qui y seront?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Non il n’arrivera pas que tu fasses une telle chose, que tu fasses mourir le juste avec le méchant, et que le juste soit traité comme le méchant! Non tu ne le feras point. Celui qui juge toute la terre ne fera-t-il point justice?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Et l’Eternel dit: Si je trouve en Sodome cinquante justes dans la ville, je pardonnerai à tout le lieu pour l’amour d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Et Abraham répondit, en disant: Voici, j’ai pris maintenant la hardiesse de parler au Seigneur, quoique je ne sois que poudre et que cendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Peut-être en manquera-t-il cinq des cinquante justes; détruiras-tu toute la ville pour ces cinq-là? Et il lui répondit: Je ne la détruirai point, si j’y en trouve quarante-cinq.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Et Abraham continua de lui parler, en disant: Peut-être s’y en trouvera- t-il quarante? Et il dit: Je ne la détruirai point pour l’amour des quarante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Et Abraham dit: Je prie le Seigneur de ne s’irriter pas si je parle encore; peut-être s’en trouvera-t-il trente? Et il dit: Je ne la détruirai point, si j’y en trouve trente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Et Abraham dit: Voici maintenant, j’ai pris la hardiesse de parler au Seigneur: peut-être s’en trouvera-t-il vingt? Et il dit: Je ne la détruirai point pour l’amour des vingt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Et Abraham dit: Je prie le Seigneur de ne s’irriter pas, je parlerai encore une seule fois; peut-être s’y en trouvera-t-il dix. Et il dit: Je ne la détruirai point pour l’amour des dix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Et l’Eternel s’en alla quand il eut achevé de parler avec Abraham; et Abraham s’en retourna en son lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Or, sur le soir les deux Anges vinrent à Sodome, et Lot était assis à la porte de Sodome, et les ayant vus, il se leva pour aller au-devant d’eux, et se prosterna le visage en terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Et il leur dit: Voici, je vous prie, Messieurs, retirez-vous maintenant dans la maison de votre serviteur, et logez-y cette nuit, et lavez vos pieds; puis vous vous lèverez le matin, et continuerez votre chemin; et ils dirent: Non, mais nous passerons cette nuit dans la rue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Mais il les pressa tant, qu’ils se retirèrent chez lui; et quand ils furent entrés dans sa maison, il leur fit un festin, et fit cuire des pains sans levain, et ils mangèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Mais avant qu’ils s’allassent coucher, les hommes de la ville, les hommes de Sodome, environnèrent la maison, depuis le plus jeune jusqu’aux vieillards, tout le peuple depuis un bout jusqu’à l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Et appelant Lot, ils lui dirent: Où sont ces hommes qui sont venus cette nuit chez toi? Fais-les sortir, afin que nous les connaissions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Mais Lot sortit de sa maison pour leur parler à la porte, et ayant fermé la porte après soi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Il leur dit: Je vous prie, mes Frères, ne leur faites point de mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Voici, j’ai deux filles qui n’ont point encore connu d’homme; je vous les amènerai, et vous les traiterez comme il vous plaira, pourvu que vous ne fassiez point de mal à ces hommes; car ils sont venus à l’ombre de mon toit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Et ils lui dirent: Retire-toi de là. Ils dirent aussi: Cet homme seul est venu pour habiter ici comme étranger, et il voudra nous gouverner? Maintenant nous te ferons pis qu’à eux. Et ils faisaient violence à Lot; et ils s’approchèrent pour rompre la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Mais ces hommes avançant leurs mains, retirèrent Lot à eux dans la maison, et fermèrent la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Et ils frappèrent d’éblouissement les hommes qui étaient à la porte de la maison, depuis le plus petit jusqu’au plus grand; de sorte qu’ils se lassèrent à chercher la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Alors ces hommes dirent à Lot: Qui as-tu encore ici qui t’appartienne, soit gendre, soit fils, ou filles, ou quelque autre qui t’appartienne en la ville? Fais-les sortir de ce lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Car nous allons détruire ce lieu, parce que leur cri est devenu grand devant l’Eternel, et il nous a envoyés pour le détruire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Lot sortit donc et parla à ses gendres, qui devaient prendre ses filles, et leur dit: Levez-vous, sortez de ce lieu, car l’Eternel va détruire la ville; mais il semblait à ses gendres qu’il se moquait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Et sitôt que l’aube du jour fut levée, les Anges pressèrent Lot, en disant: Lève-toi, prends ta femme et tes deux filles qui se trouvent ici, de peur que tu ne périsses dans la punition de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Et comme il tardait, ces hommes le prirent par la main, et ils prirent aussi par la main sa femme et ses deux filles, parce que l’Eternel l’épargnait; et ils l’emmenèrent, et le mirent hors de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Or, dès qu’ils les eurent fait sortir, l’ un dit: Sauve ta vie, ne regarde point derrière toi, et ne t’arrête en aucun endroit de la plaine; sauve-toi sur la montagne, de peur que tu ne périsses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Et Lot leur répondit: Non, Seigneur, je te prie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Voici, ton serviteur a maintenant trouvé grâce devant toi, et la gratuité que tu m’as faite de préserver ma vie est merveilleusement grande, mais je ne me pourrai sauver vers la montagne, que le mal ne m’atteigne, et que je ne meure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Voici, je te prie, cette ville-là est proche; je puis m’y enfuir, et elle est petite; je te prie, que je m’y sauve; n’est-elle pas petite? Et mon âme vivra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Et il lui dit: Voici, je t’ai exaucé encore en cela, de ne détruire point la ville dont tu as parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Hâte-toi, sauve-toi là, car je ne pourrai rien faire jusqu’à ce que tu y sois entré; c’est pourquoi cette ville fut appelée Tsohar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Comme le soleil se levait sur la terre, Lot entra dans Tsohar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Alors l’Eternel fit pleuvoir des cieux, sur Sodome et sur Gomorrhe, du soufre et du feu, de la part de l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'et il détruisit ces villes-là, et toute la plaine, et tous les habitants des villes, et le germe de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Mais la femme de Lot regarda en arrière, et elle devint une statue de sel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Et Abraham, se levant de bon matin, vint au lieu où il s’était tenu devant l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'et, regardant vers Sodome et Gomorrhe, et vers toute la terre de cette plaine-là, il vit monter de la terre une fumée comme la fumée d’une fournaise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Mais il était arrivé lors que Dieu détruisit les villes de la plaine, qu’il s’était souvenu d’Abraham, et avait envoyé Lot hors de la subversion, quand il détruisit les villes où Lot habitait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Et Lot monta de Tsohar, et habita sur la montagne avec ses deux filles, car il craignait de demeurer dans Tsohar, et il se retira dans une caverne avec ses deux filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Et l’aînée dit à la plus jeune: Notre père est vieux, et il n’y a personne sur la terre pour venir vers nous, selon la coutume de tous les pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Viens, donnons du vin à notre père, et couchons avec lui; afin que nous conservions la race de notre père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Elles donnèrent donc du vin à boire à leur père cette nuit-là; et l’aînée vint, et coucha avec son père, mais il ne s’aperçut point ni quand elle se coucha, ni quand elle se leva.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Et le lendemain l’aînée dit à la plus jeune: Voici, j’ai couché la nuit passée avec mon père, donnons-lui encore cette nuit du vin à boire, puis va, et couche avec lui, et nous conserverons la race de notre père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'En cette nuit-là donc elles donnèrent encore du vin à boire à leur père, et la plus jeune se leva et coucha avec lui; mais il ne s’aperçut point ni quand elle se coucha, ni quand elle se leva.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Ainsi les deux filles de Lot conçurent de leur père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Et l’aînée enfanta un fils, et appela son nom Moab; c’est le père des Moabites jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Et la plus jeune aussi enfanta un fils, et appela son nom Ben-Hammi; c’est le père des enfants de Hammon jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Et Abraham s’en alla de là au pays de Midi, et demeura entre Kadès et Sur, et il habita comme étranger à Guérar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Or Abraham dit de Sara sa femme: C’est ma sœur; et Abimélec, Roi de Guérar, envoya, et prit Sara.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Mais Dieu apparut la nuit dans un songe à Abimélec, et lui dit: Voici, tu es mort, à cause de la femme que tu as prise, car elle a un mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Or Abimélec ne s’était point approché d’elle. Et il dit: Seigneur, feras-tu donc mourir une nation juste?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Ne m’a-t-il pas dit: C’est ma soeur? Et elle-même aussi n’a-t-elle pas dit: C’est mon frère? J’ai fait ceci dans l’intégrité de mon coeur, et dans la pureté de mes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Et Dieu lui dit en songe: Je sais que tu l’as fait dans l’intégrité de ton coeur, et aussi ai-je empêché que tu ne péchasses contre moi; c’est pourquoi je n’ai pas permis que tu la touchasses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Maintenant donc rends à cet homme-là sa femme, car il est Prophète; et il priera pour toi, et tu vivras. Mais si tu ne la rends pas, sache que tu mourras de mort, avec tout ce qui est à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Et Abimélec se leva de bon matin, et appela tous ses serviteurs, et leur rapporta toutes ces choses, eux l’écoutant; et ils furent saisis de crainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Puis Abimélec appela Abraham, et lui dit: Que nous as-tu fait? Et en quoi t’ai-je offensé, que tu aies fait venir sur moi et sur mon royaume un grand péché? Tu m’as fait des choses qui ne se doivent point faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Abimélec dit aussi à Abraham: Qu’as-tu vu qui t’ait obligé de faire cela?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Et Abraham répondit: C’est parce que je disais: Assurément il n’y a point de crainte de Dieu en ce lieu-ci, et ils me tueront à cause de ma femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Et aussi, à la vérité, elle est ma soeur, fille de mon père; mais elle n’est pas fille de ma mère; et elle m’a été donnée pour femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Et il est arrivé que je lui ai dit, lors que Dieu ma conduit çà et là, hors de la maison de mon père; c’est ici la grâce que tu me feras, dis de moi dans tous les lieux où nous irons: C’est mon frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Alors Abimélec prit des brebis, des boeufs, des serviteurs, et des servantes, et les donna à Abraham, et lui rendit Sara, sa femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Et lui dit: Voici mon pays est à ta disposition, demeure où il te plaira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Et il dit à Sara: Voici, j’ai donné à ton frère mille pièces d’argent; voici, il t’est une couverture d’yeux envers tous ceux qui sont avec toi, et envers tous les autres; et ainsi elle fut reprise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Et Abraham fit requête à Dieu; et Dieu guérit Abimélec, sa femme, et ses servantes; et elles eurent des enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Car l’Eternel avait entièrement resserré toute matrice de la maison d’Abimélec, à cause de Sara femme d’Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Et l’Eternel visita Sara, comme il avait dit; et lui fit ainsi qu’il en avait parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Sara donc conçut, et enfanta un fils à Abraham en sa vieillesse, au temps précis que Dieu lui avait dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Et Abraham appela le nom de son fils, qui lui était né, et que Sara lui avait enfanté, Isaac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Et Abraham circoncit son fils Isaac âgé de huit jours, comme Dieu lui avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Or Abraham était âgé de cent ans quand Isaac son fils lui naquit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Et Sara dit: Dieu m’a donné de quoi rire; tous ceux qui l’apprendront riront avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Elle dit aussi: Qui eût dit à Abraham que Sara allaiterait des enfants? Car je lui ai enfanté un fils en sa vieillesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Et l’enfant crût, et fut sevré; et Abraham fit un grand festin le jour qu’Isaac fut sevré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Et Sara vit le fils d’Agar Egyptienne, qu’elle avait enfanté à Abraham, se moquer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Et elle dit à Abraham: Chasse cette servante et son fils, car le fils de cette servante n’héritera point avec mon fils, avec Isaac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Et cela déplut fort à Abraham, au sujet de son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Mais Dieu dit à Abraham: N’aie point de chagrin au sujet de l’enfant, ni de ta servante; dans toutes les choses que Sara te dira, acquiesce à sa parole; car en Isaac te sera appelée semence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Et toutefois je ferai aussi devenir le fils de la servante une nation, parce qu’il est ta semence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Puis Abraham se leva de bon matin, et prit du pain et une bouteille d’eau, et il les donna à Agar, en les mettant sur son épaule. Il lui donna aussi l’enfant et la renvoya. Elle se mit en chemin, et fut errante au désert de Béer-Sébah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Or quand l’eau de la bouteille eut manqué, elle jeta l’enfant sous un arbrisseau,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Et elle s’en alla environ à la portée d’une flèche, et s’assit vis-à-vis; car elle dit: Que je ne voie point mourir l’enfant. S’étant donc assise vis-à- vis, elle éleva sa voix, et pleura.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Et Dieu entendit la voix de l’enfant, et l’Ange de Dieu appela des cieux Agar, et lui dit: Qu’as-tu, Agar? Ne crains point, car Dieu a ouï la voix de l’enfant, du lieu où il est.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Lève-toi, lève l’enfant, et prends-le par la main; car je le ferai devenir une grande nation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Et Dieu lui ouvrit les yeux, et elle vit un puits d’eau, et, y étant allée, elle remplit d’eau la bouteille, et donna à boire à l’enfant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Et Dieu fut avec l’enfant, qui devint grand, et demeura au désert; et fut tireur d’arc.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Il demeura, dis-je, au désert de Paran; et sa mère lui prit une femme du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Et il arriva en ce temps-là qu’Abimélec, et Picol, chef de son armée, parla à Abraham, en disant: Dieu est avec toi en toutes les choses que tu fais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Maintenant donc, jure-moi ici par le nom de Dieu que tu ne me mentiras point, ni à mes enfants, ni aux enfants de mes enfants, et que selon la faveur que je t’ai faite, tu agiras envers moi, et envers le pays auquel tu as demeuré comme étranger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Et Abraham répondit: Je te le jurerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Mais Abraham se plaignit à Abimélec au sujet d’un puits d’eau, dont les serviteurs d’Abimélec s’étaient emparés par violence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Et Abimélec dit: Je n’ai point su qui a fait cela, et aussi tu ne m’en as point averti, et je n’en ai point encore ouï parler jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Alors Abraham prit des brebis, et des boeufs, et les donna à Abimélec, et ils firent alliance ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Et Abraham mit à part sept jeunes brebis de son troupeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Et Abimélec dit à Abraham: Que veulent dire ces sept jeunes brebis que tu as mises à part?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Et il répondit: C’est que tu prendras ces sept jeunes brebis de ma main, pour me servir de témoignage que j’ai creusé ce puits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'C’est pourquoi on appela ce lieu-là Béer-Sébah, car tous deux y jurèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Ils traitèrent donc alliance en Béer-Sébah, puis Abimélec se leva avec Picol, chef de son armée, et ils s’en retournèrent au pays des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Et Abraham planta un bois de chênes en Béer-Sébah, et invoqua là le nom de l’Eternel, le Dieu Fort d’éternité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Et Abraham demeura comme étranger au pays des Philistins, durant un long temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Or il arriva après ces choses, que Dieu éprouva Abraham, et lui dit: Abraham! Et il répondit: Me voici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Et Dieu lui dit: Prends maintenant ton fils, ton unique, celui que tu aimes, Isaac, et t’en va au pays de Morijah, et l’offre là en holocauste sur l’une des montagnes que je te dirai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Abraham donc s’étant levé de bon matin mit le bât sur son âne, et prit deux de ses serviteurs avec lui, et Isaac son fils; et ayant fendu le bois pour l’holocauste, il se mit en chemin, et s’en alla au lieu que Dieu lui avait dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Le troisième jour Abraham levant ses yeux, vit le lieu de loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Et il dit à ses serviteurs: Demeurez ici avec l’âne; moi et l’enfant marcherons jusque-là, et adorerons, après quoi nous reviendrons à vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Et Abraham prit le bois de l’holocauste, et le mit sur Isaac son fils, et prit le feu en sa main, et un couteau; et ils s’en allèrent tous deux ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Alors Isaac parla à Abraham son père, et dit: Mon père! Abraham répondit: Me voici, mon fils. Et il dit: Voici le feu et le bois, mais où est la bête pour l’holocauste?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Et Abraham répondit: Mon fils, Dieu se pourvoira lui-même de bête pour l’holocauste. Et ils marchaient tous deux ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Et étant arrivés au lieu que Dieu lui avait dit, Abraham bâtit là un autel, et rangea le bois, et ensuite il lia Isaac son fils, et le mit sur l’autel, au- dessus du bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Puis Abraham avançant sa main, se saisit du couteau pour égorger son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Mais l’Ange de l’Eternel lui cria des cieux en disant: Abraham, Abraham! Il répondit: Me voici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Et il lui dit: Ne mets point ta main sur l’enfant, et ne lui fais rien; car maintenant j’ai connu que tu crains Dieu, puisque tu n’as point épargné pour moi ton fils, ton unique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Et Abraham levant ses yeux regarda, et voilà derrière lui un bélier, qui était retenu à un buisson par ses cornes; et Abraham alla prendre le bélier, et l’offrit en holocauste au lieu de son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Et Abraham appela le nom de ce lieu-là, l’Eternel y pourvoira; c’est pourquoi on dit aujourd’hui; en la montagne de l’Eternel il y sera pourvu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Et l’Ange de l’Eternel cria des cieux à Abraham pour la seconde fois,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'En disant: J’ai juré par moi-même, dit l’Eternel; parce que tu as fait cette chose-ci, et que tu n’as point épargné ton fils, ton unique,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'Certainement je te bénirai, et je multiplierai très-abondamment ta postérité comme les étoiles des cieux, et comme le sable qui est sur le bord de la mer; et ta postérité possédera la porte de ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Et toutes les nations de la terre seront bénies en ta semence, parce que tu as obéi à ma voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Ainsi Abraham retourna vers ses serviteurs, et ils se levèrent, et s’en allèrent ensemble en Beer-Sébah; car Abraham demeurait à Béer-Sébah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Or il arriva après ces choses, que quelqu’un apporta des nouvelles à Abraham, en disant: Voici, Milca a aussi enfanté des enfants à Nacor ton frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Savoir Huts son premier-né, et Buz son frère, et Cémuel père d’Aram,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Et Késed, et Hazo, et Pildas, et Jidlaph, et Béthuel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Et Béthuel a engendré Rébecca. Milca enfanta ces huit à Nacor frère d’Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Et sa concubine nommée Réuma, enfanta aussi Tébah, Gaham, Tahas, et Mahaca.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Or Sara vécut cent vingt-sept ans; ce sont là les années de sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Et elle mourut en Kirjath-Arbah, qui est Hébron, au pays de Canaan; et Abraham vint pour plaindre Sara, et pour la pleurer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Et s’étant levé de devant son mort, il parla aux Héthiens, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Je suis étranger et forain parmi vous; donnez-moi une possession de sépulcre parmi vous, afin que j’enterre mon mort, et que je l’ôte de devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Et les Héthiens répondirent à Abraham, et lui dirent:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Mon Seigneur, écoute-nous; tu es parmi nous un Prince excellent, enterre ton mort dans le plus distingué de nos sépulcres; nul de nous ne te refusera son sépulcre, afin que tu y enterres ton mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Alors Abraham se leva, et se prosterna devant le peuple du pays; c’est-à- dire, devant les Héthiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Et il leur parla, et dit: S’il vous plaît que j’enterre mon mort, et que je l’ôte de devant moi, écoutez-moi, et intercédez pour moi envers Héphron, fils de Tsohar;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'Afin qu’il me cède sa caverne de Macpéla, qui est au bout de son champ; qu’il me la cède au milieu de vous, pour le prix qu’elle vaut, et que je la possède pour en faire un sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Or Héphron était assis parmi les Héthiens. Héphron donc Héthien répondit à Abraham, en présence des Héthiens, qui l’écoutaient, savoir de tous ceux qui entraient par la porte de sa ville, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Non, mon Seigneur, écoute-moi: Je te donne le champ, je te donne aussi la caverne qui y est, je te la donne en présence des enfants de mon peuple; enterres-y ton mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Et Abraham se prosterna devant le peuple du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'Et il parla à Héphron, tout le peuple du pays l’entendant, et lui dit: S’il te plaît, je te prie, écoute-moi: Je donnerai l’argent du champ; reçois-le de moi, et j’y enterrerai mon mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Et Héphron répondit à Abraham, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Mon Seigneur, écoute-moi: La terre vaut quatre cents sicles d’argent entre moi et toi; mais qu’est-ce que cela? Enterre donc ton mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Et Abraham ayant entendu Héphron, lui paya l’argent dont il avait parlé, les Héthiens l’entendant, savoir quatre cents sicles d’argent, ayant cours entre les marchands.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Et le champ d’Héphron, qui était en Macpéla au devant de Mamré, tant le champ que la caverne qui y était, et tous les arbres qui étaient dans le champ, et dans tous ses confins tout autour,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Tout fut acquis en propriété à Abraham, en présence des Héthiens, savoir de tous ceux qui entraient par la porte de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Et après cela Abraham enterra Sara sa femme dans la caverne du champ de Macpéla, au devant de Mamré, qui est Hébron, au pays de Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Le champ donc et la caverne qui y est, fut assuré par les Héthiens à Abraham, afin qu’il le possédât pour y faire son sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Or Abraham devint vieux et fort avancé en âge; et l’Eternel avait béni Abraham en toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Et Abraham dit au plus ancien des serviteurs de sa maison, qui avait le gouvernement de tout ce qui lui appartenait: Mets, je te prie, ta main sous ma cuisse:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Et je te ferai jurer par l’Eternel, le Dieu des cieux, et le Dieu de la terre, que tu ne prendras point de femme pour mon fils, d’entre les filles des Cananéens, parmi lesquels j’habite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Mais tu t’en iras en mon pays et vers mes parents, et tu y prendras une femme pour mon fils Isaac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Et ce serviteur lui répondit: Peut-être que la femme ne voudra point me suivre en ce pays; me faudra-t-il nécessairement ramener ton fils au pays d’où tu es sorti?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham lui dit: Garde-toi bien d’y ramener mon fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'L’Eternel, le Dieu des cieux, qui m’a pris de la maison de mon père, et du pays de ma parenté, et qui m’a parlé, et juré, en disant: Je donnerai à ta postérité ce pays-ci, enverra lui-même son Ange devant toi, et tu prendras de là une femme pour mon fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Que si la femme ne veut pas te suivre, tu seras quitte de ce serment que je te fais faire. Quoi qu’il en soit, ne ramène point là mon fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Et le serviteur mit la main sous la cuisse d’Abraham son Seigneur, et lui jura suivant ces choses-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Alors le serviteur prit dix chameaux d’entre les chameaux de son maître, et s’en alla: car il avait tout le bien de son maître en son pouvoir. Il partit donc, et s’en alla en Mésopotamie, à la ville de Nacor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Et il fit reposer les chameaux sur leurs genoux hors de la ville, près d’un puits d’eau, sur le soir, au temps que sortent celles qui vont puiser de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Et il dit: Ô Eternel! Dieu de mon Seigneur Abraham; fais que j’aie une heureuse rencontre aujourd’hui; et sois favorable à mon Seigneur Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Voici, je me tiendrai près de la fontaine d’eau, et les filles des gens de la ville sortiront pour puiser de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Fais donc que la jeune fille à laquelle je dirai: Baisse, je te prie, ta cruche, afin que je boive, et qui me répondra: Bois, et même je donnerai à boire à tes chameaux; soit celle que tu as destinée à ton serviteur Isaac, et je connaîtrai à cela que tu as été favorable à mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Et il arriva qu’avant qu’il eût achevé de parler, voici Rébecca fille de Béthuel, fils de Milca, femme de Nacor, frère d’Abraham, sortait ayant sa cruche sur son épaule.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Et la jeune fille était très-belle à voir, et vierge, et nul homme ne l’avait connue. Elle descendit donc à la fontaine, et comme elle remontait après avoir rempli sa cruche,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Le serviteur courut au-devant d’elle, et lui dit: Donne-moi, je te prie, un peu à boire de l’eau de ta cruche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Et elle lui dit: Mon Seigneur, bois. Et ayant incontinent abaissé sa cruche sur sa main, elle lui donna à boire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Et après qu’elle eut achevé de lui donner à boire, elle dit: J’en puiserai aussi pour tes chameaux, jusqu’à ce qu’ils aient achevé de boire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Et ayant vidé promptement sa cruche dans l’auge, elle courut encore au puits pour puiser de l’eau, et elle en puisa pour tous ses chameaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Et cet homme s’étonnait d’elle, considérant, sans dire mot, pour savoir si l’Eternel aurait fait prospérer son voyage, ou non.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Et quand les chameaux eurent achevé de boire, cet homme prit une bague d’or, du poids d’un demi- sicle, et deux bracelets pour mettre sur les mains de cette fille, pesant dix sicles d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Et il lui dit: De qui es-tu fille? Je te prie, fais-le moi savoir; n’y a- t-il point dans la maison de ton père de lieu pour nous loger?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Et elle lui répondit: Je suis fille de Béthuel, fils de Milca, qu’elle a enfanté à Nacor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Et elle lui dit aussi: Il y a chez nous beaucoup de paille et de fourrage, et de la place pour loger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Et cet homme s’inclina et se prosterna devant l’Eternel:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'Et dit: Béni soit l’Eternel, le Dieu de mon Seigneur Abraham, qui n’a point cessé d’exercer sa gratuité et sa vérité envers mon Seigneur: et lors que j’étais en chemin, l’Eternel m’a conduit en la maison des frères de mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Et la jeune fille courut, et rapporta toutes ces choses en la maison de sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Or Rébecca avait un frère nommé Laban, qui courut dehors vers cet homme près de la fontaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Car aussitôt qu’il eut vu la bague et les bracelets aux mains de sa soeur, et qu’il eut entendu les paroles de Rébecca sa soeur, qui avait dit: Cet homme m’a ainsi parlé, il le vint trouver; et voici, il était près des chameaux vers la fontaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Et il lui dit: Entre, béni de l’Eternel; pourquoi te tiens-tu dehors? J’ai préparé la maison, et un lieu pour tes chameaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'L’homme donc entra dans la maison, et on désharnacha les chameaux, et on leur donna de la paille et du fourrage; et on apporta de l’eau, tant pour laver ses pieds, que les pieds de ceux qui étaient avec lui:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Et on lui présenta à manger. Mais il dit: Je ne mangerai point, que je n’aie dit ce que j’ai à dire. Et Laban dit: Parle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Il dit donc: Je suis serviteur d’Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Or l’Eternel a béni abondamment mon Seigneur, et il est devenu grand; car il lui a donné des brebis, des boeufs, de l’argent, de l’or, des serviteurs, des servantes, des chameaux, et des ânes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Et Sara, femme de mon Seigneur, a enfanté dans sa vieillesse à mon Seigneur un fils, auquel il a donné tout ce qu’il a.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Et mon Seigneur m’a fait jurer, en disant: Tu ne prendras point de femme pour mon fils d’entre les filles des Cananéens au pays desquels je demeure,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Mais tu iras à la maison de mon père, et vers ma parenté, et tu y prendras une femme pour mon fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Et je dis à mon Seigneur: Peut-être que la femme ne me suivra pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Et il me répondit: L’Eternel, devant la face duquel j’ai vécu, enverra son Ange avec toi, et fera prospérer ton voyage, et tu prendras pour mon fils une femme de ma parenté, et de la maison de mon père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Si tu vas vers ma parenté, tu seras alors quitte de l’exécration du serment que je te fais faire: et si on ne te la donne pas, tu seras quitte de l’exécration du serment que je te fais faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Je suis donc venu aujourd’hui à la fontaine, et j’ai dit: Ô Eternel! Dieu de mon Seigneur Abraham, si maintenant tu fais prospérer le voyage que j’ai entrepris:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Voici, je me tiendrai près de la fontaine d’eau. Qu’il arrive donc que la fille qui sortira pour y puiser, et à laquelle je dirai: Donne-moi, je te prie, un peu à boire de l’eau de ta cruche;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'Et qui me répondra: Bois, et même j’ en puiserai pour tes chameaux, que celle-là soit la femme que l’Eternel a destinée au fils de mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Or avant que j’eusse achevé de parler en mon coeur, voici, Rébecca est sortie, ayant sa cruche sur son épaule, et est descendue à la fontaine, et a puisé de l’eau; et je lui ai dit: Donne-moi, je te prie, à boire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Et incontinent elle a abaissé sa cruche de dessus son épaule, et m’a dit: Bois, et même je donnerai à boire à tes chameaux. J’ai donc bu, et elle a aussi donné à boire aux chameaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Puis je l’ai interrogée, en disant: De qui es-tu fille? Elle a répondu: Je suis fille de Béthuel, fils de Nacor, que Milca lui a enfanté. Alors je lui ai mis une bague sur le front, et des bracelets en ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Je me suis incliné et prosterné devant l’Eternel, et j’ai béni l’Eternel, le Dieu de mon Seigneur Abraham, qui m’a conduit par le vrai chemin, afin que je prisse la fille du frère de mon Seigneur pour son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Maintenant donc, si vous voulez user de gratuité et de vérité envers mon Seigneur, déclarez-le-moi; sinon, déclarez-le-moi aussi; et je me tournerai à droite ou à gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Et Laban et Bethuel répondirent, en disant: Cette affaire est procédée de l’Eternel; nous ne te pouvons dire ni bien ni mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Voici Rébecca est entre tes mains, prends-la et t’en va; et qu’elle soit la femme du fils de ton Seigneur, comme l’Eternel en a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Et il arriva qu’aussitôt que le serviteur d’Abraham eut ouï leurs paroles, il se prosterna en terre devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Et le serviteur tira des bagues d’argent et d’or, et des habits, et les donna à Rébecca. Il donna aussi des présents exquis à son frère et à sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Puis ils mangèrent et burent, lui et les gens qui étaient avec lui, et y logèrent cette nuit-là; et quand ils se furent levés de bon matin, il dit: Renvoyez-moi à mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Et le frère et la mère lui dirent: Que la fille demeure avec nous quelques jours, au moins dix jours, après quoi elle s’en ira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Et il leur dit: Ne me retardez point, puisque l’Eternel a fait prospérer mon voyage, renvoyez-moi, afin que je m’en aille à mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Alors ils dirent: Appelons la fille, et demandons-lui une réponse de sa propre bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Ils appelèrent donc Rébecca, et lui dirent: Veux-tu aller avec cet homme? Et elle répondit: J’irai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Ainsi ils laissèrent aller Rébecca leur soeur, et sa nourrice, avec le serviteur d’Abraham, et ses gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Et ils bénirent Rébecca, et lui dirent: Tu es notre soeur; sois fertile par mille millions de générations, et que ta postérité possède la porte de ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Alors Rébecca se leva avec ses servantes, et elles montèrent sur les chameaux, et suivirent cet homme. Ce serviteur donc prit Rébecca, et s’en alla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Or Isaac revenait du puits du Vivant qui me voit, et il demeurait au pays du Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Et Isaac était sorti aux champs sur le soir pour prier; et levant ses yeux il regarda, et voici des chameaux qui venaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Rébecca aussi levant ses yeux vit Isaac, et descendit de dessus le chameau;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Car elle avait dit au serviteur: Qui est cet homme qui marche dans les champs au-devant de nous? Et le serviteur avait répondu: C’ est mon Seigneur; et elle prit un voile, et s’en couvrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Et le serviteur raconta à Isaac toutes les choses qu’il avait faites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Alors Isaac mena Rébecca dans la tente de Sara sa mère, et il la prit pour sa femme, et l’aima. Ainsi Isaac se consola après la mort de sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Or Abraham prit une autre femme, nommée Kétura,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Qui lui enfanta Zimram, Joksan, Médan, Madian, Jisba, et Suah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Et Joksan engendra Séba et Dédan. Et les enfants de Dédan furent Assurim, et Létusim, et Léummim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Et les enfants de Madian furent Hépha, Hépher, Hanoc, Abidah, Eldaha. Tous ceux-là sont enfants de Kétura.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Et Abraham donna tout ce qui lui appartenait à Isaac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Mais il fit des présents aux fils de ses concubines, et les envoya loin de son fils Isaac, vers l’Orient au pays d’Orient, lui étant encore en vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Et les ans que vécut Abraham furent cent soixante et quinze ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Et Abraham défaillant, mourut dans une heureuse vieillesse, fort âgé, et rassasié de jours, et fut recueilli vers ses peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Et Isaac et Ismaël ses fils l’enterrèrent en la caverne de Macpéla, au champ d’Héphron, fils de Tsohar Héthien, qui est vis-à-vis de Mamré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'Le champ qu’Abraham avait acheté des Héthiens: là fut enterré Abraham avec Sara sa femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Or il arriva après la mort d’Abraham, que Dieu bénit Isaac son fils: et Isaac demeurait près du puits du Vivant qui me voit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Ce sont ici les générations d’Ismaël, fils d’Abraham, qu’Agar Egyptienne, servante de Sara, avait enfanté à Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Et ce sont ici les noms des enfants d’Ismaël, desquels ils ont été nommés dans leurs générations. Le premier-né d’Ismaël fut Nébajoth, puis Kédar, Adbéel, Mibsam,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Mismah, Duma, Massa,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadar, Téma, Jétur, Naphis, et Kedma.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Ce sont là les enfants d’Ismaël, et ce sont là leurs noms, selon leurs villages, et selon leurs châteaux: douze Princes de leurs peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Et les ans de la vie d’Ismaël furent cent trente-sept ans; et il défaillit, et mourut, et fut recueilli vers ses peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Et ses Descendants habitèrent depuis Havila jusqu’à Sur, qui est vis-à-vis de l’Egypte, quand on vient vers l’Assyrie; et le pays qui était échu à Ismaël était à la vue de tous ses frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Or ce sont ici les générations d’Isaac, fils d’Abraham. Abraham engendra Isaac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Et Isaac était âgé de quarante ans, quand il se maria avec Rébecca, fille de Béthuel Syrien, de Paddan-Aram, soeur de Laban Syrien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Et Isaac pria instamment l’Eternel au sujet de sa femme, parce qu’elle était stérile; et l’Eternel fut fléchi par ses prières; et Rébecca sa femme conçut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Mais les enfants s’entrepoussaient dans son ventre, et elle dit: S’il est ainsi, pourquoi suis-je? Et elle alla consulter l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Et l’Eternel lui dit: Deux nations sont dans ton ventre, et deux peuples sortiront de tes entrailles; et un peuple sera plus fort que l’autre peuple, et le plus grand sera asservi au moindre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Et quand son temps d’enfanter fut accompli, voici il y avait deux jumeaux en son ventre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Celui qui sortit le premier, était roux, et tout velu, comme un manteau de poil: et ils appelèrent son nom Esaü.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Et ensuite sortit son frère, tenant de sa main le talon d’Esaü; c’est pourquoi il fut appelé Jacob. Or Isaac était âgé de soixante ans quand ils naquirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Depuis, les enfants devinrent grands, et Esaü était un habile chasseur, et homme de campagne; mais Jacob était un homme intègre et se tenant dans les tentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Et Isaac aimait Esaü; car la venaison était sa viande. Mais Rébecca aimait Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Or comme Jacob cuisait du potage, Esaü arriva des champs, et il était las.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Et Esaü dit à Jacob: Donne-moi, je te prie, à manger de ce roux, de ce roux; car je suis las. C’est pourquoi on appela son nom, Edom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Mais Jacob lui dit: Vends-moi aujourd’hui ton droit d’aînesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Et Esaü répondit: Voici je m’en vais mourir; et de quoi me servira le droit d’aînesse?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Et Jacob dit: Jure-moi aujourd’hui; et il lui jura; ainsi il vendit son droit d’aînesse à Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Et Jacob donna à Esaü du pain, et du potage de lentilles; et il mangea, et but; puis il se leva, et s’en alla; ainsi Esaü méprisa son droit d’aînesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Or il y eut une famine au pays, outre la première famine qui avait été du temps d’Abraham; et Isaac s’en alla vers Abimélec Roi des Philistins, à Guérar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Car l’Eternel lui était apparu, et lui avait dit: Ne descends point en Egypte; demeure au pays que je te dirai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Demeure dans ce pays-là, et je serai avec toi, et je te bénirai; car je te donnerai et à ta postérité tous ces pays-ci, et je ratifierai le serment que j’ai fait à ton père Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Je multiplierai ta postérité comme les étoiles des cieux; et je donnerai ces pays-ci à ta postérité; et toutes les nations de la terre seront bénies en ta semence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Parce qu’Abraham a obéi à ma voix, et qu’il a gardé mon ordonnance, mes commandements, mes statuts, et mes lois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Isaac donc demeura à Guérar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Et quand les gens du lieu s’enquirent qui était sa femme, il répondit: C’est ma sœur; car il craignait de dire: C’est ma femme; de peur, disait-il, qu’il n’arrive que les habitants du lieu ne me tuent à cause de Rébecca; car elle est belle à voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Or il arriva après qu’il y eut passé quelques jours qu’Abimélec, Roi des Philistins, regardait par la fenêtre, et voici, il vit Isaac, qui se jouait avec Rébecca sa femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Alors Abimélec appela Isaac, et lui dit: Voici, c’est véritablement ta femme; et comment as-tu dit: C’est ma soeur? Et Isaac lui répondit: C’est parce que j’ai dit: Afin que peut-être je ne meure à cause d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Et Abimélec dit: Que nous as-tu fait? Il s’en est peu fallu que quelqu’un du peuple n’ait couché avec ta femme, et que tu ne nous aies fait tomber dans le crime.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Abimélec donc fit une ordonnance à tout le peuple, en disant: Celui qui touchera cet homme, ou sa femme, sera certainement puni de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Et Isaac sema en cette terre-là, et il recueillit cette année-là le centuple; car l’Eternel le bénit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Cet homme donc accrut, et allait toujours en augmentant, jusqu’à ce qu’il fût merveilleusement accru.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Et il eut du menu et du gros bétail, et un grand nombre de serviteurs; et les Philistins lui portèrent envie:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Tellement qu’ils bouchèrent les puits que les serviteurs de son père avaient creusés du temps de son père Abraham, et les remplirent de terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Abimélec aussi dit à Isaac: Retire-toi d’avec nous; car tu es devenu beaucoup plus puissant que nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Isaac donc partit de là, et alla camper dans la vallée de Guérar, et y demeura.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Et Isaac creusa encore les puits d’eau qu’on avait creusés du temps d’Abraham son père, lesquels les Philistins avaient bouchés après la mort d’Abraham, et les appela des mêmes noms dont son père les avait appelés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Et les serviteurs d’Isaac creusèrent dans cette vallée, et y trouvèrent un puits d’eau vive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Mais les bergers de Guérar eurent un démêlé avec les bergers d’Isaac, disant: L’eau est à nous. Et il appela le puits, Hések; parce qu’ils avaient contesté avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Ensuite ils creusèrent un autre puits, pour lequel ils contestèrent aussi; et il appela son nom, Sitnah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Alors il se retira de là, et creusa un autre puits, pour lequel ils ne contestèrent point, et il le nomma Réhoboth, en disant: C’est parce que l’Eternel nous a maintenant mis au large, et que nous nous sommes agrandis dans ce pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Et de là il monta à Béer-Sébah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Et l’Eternel lui apparut cette même nuit, et lui dit: Je suis le Dieu d’Abraham ton père, ne crains point; car je suis avec toi, je te bénirai, et je multiplierai ta postérité à cause d’Abraham mon serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Et il bâtit là un autel, et invoqua le nom de l’Eternel, et il y dressa ses tentes; et les serviteurs d’Isaac y creusèrent un puits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Et Abimélec vint à lui de Guérar avec Ahuzat son ami, et Picol chef de son armée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Mais Isaac leur dit: Pourquoi venez-vous vers moi, puisque vous me haïssez, et que vous m’avez renvoyé d’auprès de vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Et ils répondirent: Nous avons vu clairement que l’Eternel est avec toi; et nous avons dit: Qu’il y ait maintenant un serment avec exécration entre nous, c’est-à-dire, entre nous et toi; et traitons alliance avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Si tu nous fais du mal, comme nous ne t’avons point touché, et comme nous ne t’avons fait que du bien, et t’avons laissé aller en paix; toi qui es maintenant béni de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Alors il leur fit un festin, et ils mangèrent et burent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Et ils se levèrent de bon matin, et jurèrent l’un à l’autre. Puis Isaac les renvoya, et ils s’en allèrent d’avec lui en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Il arriva en ce même jour, que les serviteurs d’Isaac vinrent, et lui parlèrent touchant ce puits qu’ils avaient creusé, et lui dirent: Nous avons trouvé de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Et il l’appela Sibah; c’est pourquoi le nom de la ville a été Béer-Sébah jusqu’à aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Or Esaü, âgé de quarante ans, prit pour femmes Judith, fille de Béeri Héthien, et Basmath fille d’Elon Héthien;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Lesquelles furent en amertume d’esprit à Isaac et à Rébecca.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Et il arriva que quand Isaac fut devenu vieux, et que ses yeux furent si ternis qu’il ne pouvait plus voir, il appela Esaü son fils aîné, et lui dit: Mon fils! Lequel lui répondit: Me voici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Et il lui dit: Voici maintenant je suis devenu vieux, et je ne sais point le jour de ma mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Maintenant donc, je te prie, prends tes armes, ton carquois, et ton arc, et t’en va aux champs, et prends-moi de la venaison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Et m’apprête des viandes d’appétit comme je les aime, et apporte-les-moi, afin que je mange, et que mon âme te bénisse avant que je meure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Or Rébecca écoutait pendant qu’Isaac parlait à Esaü son fils. Esaü donc s’en alla aux champs pour prendre de la venaison, et l’apporter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Et Rébecca parla à Jacob son fils, et lui dit: Voici, j’ai ouï parler ton père à Esaü ton frère, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Apporte-moi de la venaison, et m’apprête des viandes d’appétit, afin que j’en mange; et je te bénirai devant l’Eternel, avant que de mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Maintenant donc, mon fils, obéis à ma parole, et fais ce que je te vais commander.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Va maintenant à la bergerie, et prends-moi là deux bons chevreaux d’entre les chèvres, et j’en apprêterai des viandes d’appétit pour ton père, comme il les aime.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Et tu les porteras à ton père, afin qu’il les mange, et qu’il te bénisse, avant sa mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Et Jacob répondit à Rébecca sa mère: Voici, Esaü mon frère est un homme velu, et je suis un homme sans poil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Peut-être que mon père me tâtera, et il me regardera comme un homme qui l’a voulu tromper, et j’attirerai sur moi sa malédiction, et non pas sa bénédiction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Et sa mère lui dit: Mon fils, que la malédiction que tu crains soit sur moi! Obéis seulement à ma parole, et me va prendre ce que je t’ai dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Il s’en alla donc, et le prit, et il l’apporta à sa mère; et sa mère en apprêta des viandes d’appétit, comme son père les aimait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Puis Rébecca prit les plus précieux habits d’Esaü son fils aîné, qu’elle avait dans la maison, et elle en vêtit Jacob son plus jeune fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Et elle couvrit ses mains et son cou, qui étaient sans poil, des peaux des chevreaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Puis elle mit entre les mains de son fils Jacob ces viandes d’appétit, et le pain qu’elle avait apprêté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Il vint donc vers son père, et lui dit: Mon père! Il répondit: Me voici; qui es-tu, mon fils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Et Jacob dit à son père: Je suis Esaü, ton fils aîné; j’ai fait ce que tu m’avais commandé; lève-toi, je te prie, assieds-toi, et mange de ma chasse, afin que ton âme me bénisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Et Isaac dit à son fils: Qu’est ceci que tu en aies si-tôt trouvé, mon fils? Et il dit: L’Eternel ton Dieu l’a fait rencontrer devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Et Isaac dit à Jacob: Mon fils, approche-toi, je te prie, et je te tâterai, afin que je sache si tu es toi-même mon fils Esaü, ou non.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Jacob donc s’approcha de son père Isaac, qui le tâta, et dit: Cette voix est la voix de Jacob; mais ces mains sont les mains d’Esaü.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Et il le méconnut; car ses mains étaient velues comme les mains de son frère Esaü; et il le bénit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Il dit donc: Es-tu toi-même mon fils Esaü? Il répondit: Je le suis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Il lui dit aussi: Approche-moi donc la viande, et que je mange de la chasse de mon fils, afin que mon âme te bénisse. Et il l’approcha, et Isaac mangea; il lui apporta aussi du vin, et il but.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Puis Isaac son père lui dit: Approche-toi, je te prie, et me baise, mon fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Et il s’approcha, et le baisa. Et Isaac sentit l’odeur de ses habits, et le bénit, en disant: Voici l’odeur de mon fils, comme l’odeur d’un champ que l’Eternel a béni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Que Dieu te donne de la rosée des cieux, et de la graisse de la terre, et abondance de froment, et de moût!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Que les peuples te servent, et que les nations se prosternent devant toi! Sois le maître de tes frères, et que les fils de ta mère se prosternent devant toi! Quiconque te maudira, soit maudit; et quiconque te bénira, soit béni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Or il arriva qu’aussitôt qu’Isaac eut achevé de bénir Jacob, Jacob étant à peine sorti de devant son père Isaac, son frère Esaü revint de la chasse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Qui apprêta aussi des viandes d’appétit, et les apporta à son père, et lui dit: Que mon père se lève, et qu’il mange de la chasse de son fils, afin que ton âme me bénisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Et Isaac son père lui dit: Qui es-tu? Et il dit: Je suis ton fils, ton fils aîné, Esaü.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Et Isaac fut saisi d’une fort grande émotion, et dit: Qui est, et où est celui qui a pris de la chasse, et m’en a apporté? J’ai mangé de tout, avant que tu vinsses, et je l’ai béni; et aussi il sera béni!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Si-tôt qu’Esaü eut entendu les paroles de son père, il jeta un cri fort grand, et amer; et il dit à son père: Bénis-moi aussi, bénis-moi, mon père!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Mais il dit: Ton frère est venu avec artifice, et a emporté ta bénédiction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Et Esaü dit: N’est-ce pas avec raison qu’on a appelé son nom, Jacob? car il m’a déjà supplanté deux fois; il m’a enlevé mon droit d’aînesse, et voici, maintenant il a emporté ma bénédiction. Puis il dit: Ne m’as-tu point réservé de bénédiction?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Et Isaac répondit à Esaü, en disant: Voici, je l’ai établi ton Seigneur, et lui ai donné tous ses frères pour serviteurs, et je l’ai fourni de froment et de moût; et que ferai-je maintenant pour toi, mon fils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Et Esaü dit à son père: N’as-tu qu’une bénédiction, mon père? Bénis-moi aussi, bénis-moi, mon père! Et Esaü, élevant sa voix, pleura.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Et Isaac son père répondit, et dit: Voici, ton habitation sera en la graisse de la terre, et en la rosée des cieux d’en haut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Et tu vivras par ton épée, et tu seras asservi à ton frère; mais il arrivera qu’étant devenu maître, tu briseras son joug de dessus ton cou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Et Esaü eut en haine Jacob, à cause de la bénédiction dont son père l’avait béni, et il dit en son coeur: Les jours du deuil de mon père approchent, et alors je tuerai Jacob mon frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Et on rapporta à Rébecca les discours d’Esaü, son fils aîné; et elle envoya appeler Jacob son second fils, et lui dit: Voici, Esaü ton frère se console dans l’espérance qu’il a de te tuer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Maintenant donc, mon fils, obéis à ma parole; lève-toi, et t’enfuis à Caran, vers Laban, mon frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Et demeure avec lui quelque temps, jusqu’à ce que la fureur de ton frère soit passée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Et que sa colère soit détournée de toi, et qu’il ait oublié les choses que tu lui as faites. J’enverrai ensuite pour te tirer de là. Pourquoi serais-je privée de vous deux en un même jour?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Et Rébecca dit à Isaac: La vie m’est devenue ennuyeuse, à cause de ces Héthiennes. Si Jacob prend pour femme quelqu’une de ces Héthiennes, comme sont les filles de ce pays, à quoi me sert la vie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Isaac donc appela Jacob, et le bénit, et lui commanda, en disant: Tu ne prendras point de femme d’entre les filles de Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Lève-toi; va en Paddan-Aram, à la maison de Béthuel, père de ta mère, et prends-toi de là une femme des filles de Laban, frère de ta mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Et le Dieu Fort, Tout-Puissant te bénisse, et te fasse croître et multiplier, afin que tu deviennes une assemblée de peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Et qu’il te donne la bénédiction d’Abraham, à toi et à la postérité avec toi, afin que tu obtiennes en héritage le pays où tu as été étranger, lequel Dieu a donné à Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Isaac donc fit partir Jacob, qui s’en alla en Paddan-Aram, vers Laban, fils de Béthuel Syrien, frère de Rébecca, mère de Jacob et d’Esaü.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Et Esaü vit qu’Isaac avait béni Jacob, et qu’il l’avait envoyé en Paddan- Aram, afin qu’il prît femme de ce pays-là pour lui, et qu’il lui avait commandé, quand il le bénissait, disant: Ne prends point de femme d’entre les filles de Canaan;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'Et que Jacob avait obéi à son père et à sa mère, et s’en était allé en Paddan-Aram.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'C’est pourquoi Esaü voyant que les filles de Canaan déplaisaient à Isaac son père,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'S’en alla vers Ismaël, et prit pour femme, outre ses autres femmes, Mahalath, fille d’Ismaël, fils d’Abraham, soeur de Nébajoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Jacob donc partit de Béer-Sébah, et s’en alla à Caran.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Et il se rencontra en un lieu où il passa la nuit, parce que le soleil était couché. Il prit donc des pierres de ce lieu-là, et en fit son chevet, et s’endormit en ce même lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Et il songea; et voici, une échelle dressée sur la terre, dont le bout touchait jusqu’aux cieux; et voici, les Anges de Dieu montaient et descendaient par cette échelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Et voici, l’Eternel se tenait sur l’échelle, et il lui dit: Je suis l’Eternel, le Dieu d’Abraham ton père, et le Dieu d’Isaac; je te donnerai et à ta postérité, la terre sur laquelle tu dors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Et ta postérité sera comme la poussière de la terre, et tu t’étendras à l’Occident, à l’Orient, au Septentrion, et au Midi, et toutes les familles de la terre seront bénies en toi et en ta semence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Et voici, je suis avec toi; et je te garderai partout où tu iras; et je te ramènerai en ce pays; car je ne t’abandonnerai point que je n’aie fait ce que je t’ai dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Et quand Jacob fut réveillé de son sommeil, il dit: Certes! l’Eternel est en ce lieu-ci, et je n’en savais rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Et il eut peur, et dit: Que ce lieu-ci est effrayant! C’est ici la maison de Dieu, et c’est ici la porte des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Et Jacob se leva de bon matin, et prit la pierre dont il avait fait son chevet, et la dressa pour monument; et versa de l’huile sur son sommet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Et il appela le nom de ce lieu-là, Béthel: mais auparavant la ville s’appelait Luz.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Et Jacob fit un voeu, en disant: Si Dieu est avec moi, et s’il me garde dans le voyage que je fais, s’il me donne du pain à manger, et des habits pour me vêtir,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'Et si je retourne en paix à la maison de mon père, certainement l’Eternel me sera Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'Et cette pierre que j’ai dressée pour monument, sera la maison de Dieu; et de tout ce que tu m’auras donné, je t’en donnerai entièrement la dîme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Jacob donc se mit en chemin, et s’en alla au pays des Orientaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Et il regarda, et voici un puits dans un champ, et là-même trois troupeaux de brebis couchées près du puits (car on y abreuvait les troupeaux,) et il y avait une grosse pierre sur l’ouverture du puits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Et quand tous les troupeaux étaient là assemblés, on roulait la pierre de dessus l’ouverture du puits, et on abreuvait les troupeaux; et ensuite on remettait la pierre en son lieu, sur l’ouverture du puits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Et Jacob leur dit: Mes frères, d’où êtes-vous? Ils répondirent: Nous sommes de Caran.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Et il leur dit: Ne connaissez-vous point Laban fils de Nacor? Et ils répondirent: Nous le connaissons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Il leur dit: Se porte-t-il bien? Ils lui répondirent: Il se porte bien; et voilà Rachel sa fille, qui vient avec le troupeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Et il dit: Voilà, il est encore grand jour, il n’est pas temps de retirer les troupeaux; abreuvez les troupeaux, et ramenez-les paître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Ils répondirent: Nous ne le pouvons point jusqu’à ce que tous les troupeaux soient assemblés, et qu’on ait oté la pierre de dessus l’ouverture du puits, afin d’abreuver les troupeaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Et comme il parlait encore avec eux, Rachel arriva avec le troupeau de son père; car elle était bergère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Et il arriva que quand Jacob eut vu Rachel fille de Laban frère de sa mère, et le troupeau de Laban frère de sa mère, il s’approcha et roula la pierre de dessus l’ouverture du puits, et abreuva le troupeau de Laban, frère de sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Et Jacob baisa Rachel, et élevant sa voix, il pleura.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Et Jacob apprit à Rachel qu’il était frére de son père, et qu’il était fils de Rébecca; et elle courut le rapporter à son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Et il arriva qu’aussitôt que Laban eut appris des nouvelles de Jacob fils de sa soeur, il courut au-devant de lui, l’embrassa, et le baisa, et le fit venir dans sa maison; et Jacob récita à Laban tout ce qui lui était arrivé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Et Laban lui dit: Certainement, tu es mon os et ma chair; et il demeura avec lui un mois entier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Après quoi Laban dit à Jacob: Me serviras-tu pour rien, parce que tu es mon frère? Dis-moi quel sera ton salaire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Or Laban avait deux filles, dont l’aînée s’appelait Léa, et la plus jeune, Rachel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Mais Léa avait les yeux tendres, et Rachel était de belle taille, et belle à voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Et Jacob aimait Rachel, et il dit: Je te servirai sept ans pour Rachel, ta plus jeune fille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Et Laban répondit: Il vaut mieux que je te la donne que si je la donnais à un autre; demeure avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Jacob donc servit sept ans pour Rachel, qui lui semblèrent comme peu de jours, parce qu’il l’aimait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Et Jacob dit à Laban: Donne-moi ma femme, car mon temps est accompli, et je viendrai vers elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Laban donc assembla tous les gens du lieu, et fit un festin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Mais quand le soir fut venu, il prit Léa sa fille, et l’amena à Jacob, qui vint vers elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Et Laban donna Zilpa sa servante à Léa, sa fille, pour servante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Mais le matin étant venu, voici, c’était Léa. Et il dit à Laban: Qu’est- ce que tu m’as fait? N’ai-je pas servi chez toi pour Rachel? et pourquoi m’as-tu trompé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Laban répondit: On ne fait pas ainsi en ce lieu, de donner la plus jeune avant l’aînée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Achève la semaine de celle-ci, et nous te donnerons aussi l’autre, pour le service que tu feras encore chez moi sept autres années.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jacob donc fit ainsi, et il acheva la semaine de Léa; et Laban lui donna aussi pour femme Rachel sa fille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Et Laban donna Bilha sa servante à Rachel sa fille, pour servante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Il vint donc aussi vers Rachel, et il aima plus Rachel que Léa; et il servit encore chez lui sept autres années.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Et l’Eternel voyant que Léa était haïe, ouvrit sa matrice; mais Rachel était stérile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Et Léa conçut et enfanta un fils, et elle le nomma Ruben, car elle dit: C’est parce que l’Eternel a regardé mon affliction; c’est pourquoi aussi maintenant mon mari m’aimera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Elle conçut encore, et enfanta un fils, et dit: Parce que l’Eternel a entendu que j’étais haïe, il m’a aussi donné celui-ci; et elle le nomma Siméon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Et elle conçut encore, et enfanta un fils, et dit: Maintenant mon mari s’attachera à moi: car je lui ai enfanté trois fils: C’est pourquoi on appela son nom Lévi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Elle conçut encore, et enfanta un fils, et dit: Cette fois je louerai l’Eternel; c’est pourquoi elle appela son nom Juda; et elle ne continua plus d’avoir des enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Alors Rachel voyant qu elle ne faisait point d’enfants à Jacob, fut jalouse de Léa sa sœur; et dit à Jacob: Donne-moi des enfants, autrement je suis morte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Et Jacob se mit fort en colère contre Rachel, et lui dit: Suis-je au lieu de Dieu, qui t’a empêchée d’avoir des enfants?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Et elle dit: Voilà ma servante Bilha; va vers elle et elle enfantera sur mes genoux, et j’aurai des enfants par elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Elle lui donna donc Bilha sa servante pour femme, et Jacob vint vers elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Et Bilha conçut, et enfanta un fils à Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Et Rachel dit: Dieu a jugé en ma faveur, et il a aussi exaucé ma voix, et m’a donné un fils; c’est pourquoi elle le nomma Dan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Et Bilha, servante de Rachel, conçut encore, et enfanta un second fils à Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Et Rachel dit: J’ai fortement lutté contre ma sœur, aussi j’ai eu la victoire; c’est pourquoi elle le nomma Nephthali.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Alors Léa voyant qu’elle avait cessé de faire des enfants, prit Zilpa sa servante, et la donna à Jacob pour femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Et Zilpa, servante de Léa, enfanta un fils à Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Et Léa dit: Une troupe est arrivée, c’est pourquoi elle le nomma Gad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Et Zilpa, servante de Léa, enfanta un second fils à Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Et Léa dit: C’est pour me rendre heureuse; car les filles me diront bienheureuse; c’est pourquoi elle le nomma Aser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Or Ruben étant sorti au temps de la moisson des blés, trouva des mandragores aux champs, et les apporta à Léa sa mère; et Rachel dit à Léa: Donne-moi, je te prie, des mandragores de ton fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Et elle lui répondit: Est-ce peu de chose de m’avoir oté mon mari, que tu m’otes aussi les mandragores de mon fils? Et Rachel dit: Qu’il couche donc cette nuit avec toi, pour les mandragores de ton fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Et quand Jacob revint des champs au soir, Léa sortit au-devant de lui, et lui dit: Tu viendras vers moi; car je t’ai loué pour les mandragores de mon fils; et il coucha avec elle cette nuit-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Et Dieu exauça Léa, et elle conçut, et enfanta à Jacob un cinquième fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Et elle dit: Dieu m’a récompensée, parce que j’ai donné ma servante à mon mari; c’est pourquoi elle le nomma Issacar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Et Léa conçut encore, et enfanta un sixième fils à Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Et Léa dit: Dieu m’a donné un bon douaire; maintenant mon mari demeurera avec moi: car je lui ai enfanté six enfants; c’est pourquoi elle le nomma Zabulon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Puis elle enfanta une fille, et la nomma Dina.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Et Dieu se souvint de Rachel, et Dieu l’ayant exaucée, ouvrit sa matrice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Alors elle conçut, et enfanta un fils, et dit: Dieu a oté mon opprobre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Et elle le nomma Joseph, en disant: Que l’Eternel m’ajoute un autre fils!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Et il arriva qu’après que Rachel eut enfanté Joseph, Jacob dit à Laban: Donne-moi mon congé, et je m’en retournerai en mon lieu, et en mon pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Donne-moi mes femmes et mes enfants, pour lesquels je t’ai servi, et je m’en irai; car tu sais de quelle manière je t’ai servi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Et Laban lui répondit: Ecoute, je te prie, si j’ai trouvé grâce devant toi; j’ai reconnu que l’Eternel m’a béni à cause de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Il lui dit aussi: Marque-moi quel salaire tu veux, et je te le donnerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Et il lui répondit: Tu sais comment je t’ai servi, et ce qu’est devenu ton bétail avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Car ce que tu avais avant que je vinsse, était peu de chose, mais il est beaucoup accru, et l’Eternel t’a béni à mon arrivée; et maintenant, quand ferai-je aussi quelque chose pour ma maison?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Et Laban lui dit: Que te donnerai-je? Et Jacob répondit: Tu ne me donneras rien; mais je paîtrai encore tes troupeaux, et je les garderai, si tu fais ceci pour moi:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Que je passe aujourd’hui parmi tes troupeaux, et qu’on mette à part toutes les brebis picotées et tachetées, et tous les agneaux roux, et les chèvres tachetées et picotées; et ce sera là mon salaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Et désormais ma justice rendra témoignage pour moi; car elle viendra sur mon salaire, en ta présence; et tout ce qui ne sera point picoté ou tacheté entre les chèvres, et roux entre les agneaux, sera tenu pour un larcin, s’il est trouvé chez moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Et Laban dit: Voici, qu’il te soit fait comme tu l’as dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Et en ce jour-là il sépara les boucs marquetés et picotés, et toutes les chèvres picotées et tachetées, toutes celles où il y avait du blanc, et tous les agneaux roux, et il les mit entre les mains de ses fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Et il mit l’espace de trois journées de chemin entre lui et Jacob; et Jacob paissait le reste des troupeaux de Laban.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Mais Jacob prit des verges fraîches, de peuplier, de coudrier, et de châtaignier, et en ôta les écorces en découvrant le blanc qui était aux verges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Et il mit les verges qu’il avait pelées, au devant des troupeaux, dans les auges, et dans les abreuvoirs où les brebis venaient boire; et elles entraient en chaleur quand elles venaient boire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Les brebis donc entraient en chaleur à la vue des verges, et elles faisaient des brebis marquetées, picotées, et tachetées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Et Jacob partagea les agneaux, et fit que les brebis du troupeau de Laban avaient en vue les brebis marquetées, et tout ce qui était roux; et il mit ses troupeaux à part, et ne les mit point auprès des troupeaux de Laban.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Et il arrivait que toutes les fois que les brebis hâtives entraient en chaleur, Jacob mettait les verges dans les abreuvoirs devant les yeux du troupeau, afin qu’elles entrassent en chaleur en regardant les verges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Mais quand les brebis étaient tardives, il ne les mettait point; et les tardives appartenaient à Laban, et les hâtives à Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Ainsi cet homme s’accrut fort en biens, et eut de grands troupeaux, des servantes, et des serviteurs, des chameaux, et des ânes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Or Jacob entendit les discours des fils de Laban, qui disaient: Jacob a pris tout ce qui était à notre père, et de ce qui était à notre père, il a acquis toute cette gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Et Jacob regarda le visage de Laban, et voici, il n’était point envers lui comme auparavant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Et l’Eternel dit à Jacob: Retourne au pays de tes pères, et vers ta parenté, et je serai avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Jacob donc envoya appeler Rachel et Léa aux champs vers ses troupeaux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Et leur dit: Je connais au visage de votre père qu’il n’est pas envers moi comme il était auparavant; toutefois le Dieu de mon père a été avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Et vous savez que j’ai servi votre père de tout mon pouvoir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Mais votre père s’est moqué de moi, et a changé dix fois mon salaire; mais Dieu n’a pas permis qu’il m’ait fait aucun mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Quand il disait ainsi: Les picotées seront ton salaire, alors toutes les brebis faisaient des agneaux picotés; et quand il disait: Les marquetées seront ton salaire, alors toutes les brebis faisaient des agneaux marquetés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Ainsi Dieu a ôté le bétail à votre père, et me l’a donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Car il arriva au temps que les brebis entraient en chaleur, que je levai mes yeux, et je vis en songe, et voici, les boucs qui couvraient les chèvres, étaient marquetés, picotés, et tachetés,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Et l’Ange de Dieu me dit en songe: Jacob! Et je répondis: Me voici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Et il dit: Lève maintenant tes yeux, et regarde: tous les boucs qui couvrent les chèvres, sont marquetés, picotés, et tachetés; car j’ai vu tout ce que te fait Laban.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Je suis le Dieu Fort de Béthel, où tu oignis la pierre que tu dressas pour monument, quand tu me fis là un vœu; maintenant donc, lève-toi, sors de ce pays, et retourne au pays de ta parenté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Alors Rachel et Léa lui répondirent, et dirent: Avons-nous encore quelque portion et quelque héritage dans la maison de notre père?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Ne nous a-t-il pas traitées comme des étrangères? car il nous a vendues, et même il a entièrement mangé notre argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Car toutes les richesses que Dieu a otées à notre père, nous appartenaient, et à nos enfants. Maintenant donc fais tout ce que Dieu t’a dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Ainsi Jacob se leva, et fit monter ses enfants et ses femmes sur des chameaux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Et il emmena tout son bétail et son bien, qu’il avait acquis, et tout ce qu’il possédait, et qu’il avait acquis en Paddan-Aram, pour aller vers Isaac son père, au pays de Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Or comme Laban était allé tondre ses brebis, Rachel déroba les marmousets qui étaient à son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Et Jacob se déroba de Laban le Syrien, ne lui ayant rien déclaré de son dessein, parce qu’il s’enfuyait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Il s’enfuit donc avec tout ce qui lui appartenait, et partit, et passa le fleuve, et s’avança vers la montagne de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Et au troisième jour on rapporta à Laban, que Jacob s’en était fui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Et il prit avec lui ses frères, et le poursuivit sept journées de chemin, et l’atteignit à la montagne de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Mais Dieu apparut à Laban le Syrien en songe la nuit, et lui dit: Prends garde de ne rien dire à Jacob en bien ni en mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Laban donc atteignit Jacob; et Jacob avait tendu ses tentes en la montagne; et Laban tendit aussi les siennes avec ses frères en la montagne de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Or Laban dit à Jacob: Qu’as-tu fait? Tu t’es dérobé de moi; tu as emmené mes filles comme des prisonnières de guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Pourquoi t’es-tu enfui en cachette, et t’es-tu dérobé de moi, sans m’en donner avis? car je t’eusse conduit avec joie et avec des chansons, au son des tambours, et des violons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Tu ne m’as pas seulement laissé baiser mes fils et mes filles; tu as fait follement en cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'J’ai en main le pouvoir de vous faire du mal, mais le Dieu de votre père m’a parlé la nuit passée, et m’a dit: Prends garde de ne rien dire à Jacob en bien ni en mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Maintenant donc, à la bonne heure, que tu t’en sois ainsi allé en hâte, puisque tu souhaitais si ardemment de retourner en la maison de ton père; mais pourquoi m’as-tu dérobé mes Dieux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Et Jacob répondant dit à Laban: Je m’en suis allé parce que je craignais; car je disais qu’il fallait prendre garde que tu ne me ravisses tes filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Mais que celui en qui tu trouveras tes Dieux, ne vive point. Reconnais devant nos frères s’il y a chez moi quelque chose qui t’appartienne, et le prends; car Jacob ignorait que Rachel les eût dérobés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Alors Laban vint dans la tente de Jacob, et dans celle de Léa, et dans la tente des deux servantes et il ne les trouva point; et étant sorti de la tente de Léa, il entra dans la tente de Rachel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Mais Rachel prit les marmousets, et les ayant mis dans le bât d’un chameau, elle s’assit dessus; et Laban fouilla toute la tente, et ne les trouva point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Et elle dit à son père: Que mon Seigneur ne se fâche point de ce que je ne me puis lever devant lui; car j’ai ce que les femmes ont accoutumé d’avoir; et il fouilla, mais il ne trouva point les marmousets.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Et Jacob se mit en colère, et querella Laban, et prenant la parole, lui dit: Quel est mon crime? quel est mon péché, que tu m’aies poursuivi si ardemment?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Car tu as fouillé tout mon bagage; mais qu’as-tu trouvé de tous les meubles de ta maison? Mets-le ici devant mes frères et les tiens, et qu’ils soient juges entre nous deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'J’ai été avec toi ces vingt ans passés; tes brebis et tes chèvres n’ont point avorté; je n’ai point mangé les moutons de tes troupeaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Je ne t’ai point rapporté en compte ce qui a été déchiré par les bêtes sauvages; j’en ai supporté la perte; et tu redemandais de ma main ce qui avait été dérobé de jour, et ce qui avait été dérobé de nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'De jour le hâle me consumait, et de nuit la gelée; et mon sommeil fuyait de devant mes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Je t’ai servi ces vingt ans passés dans ta maison, quatorze ans pour tes deux filles, et six ans pour tes troupeaux, et tu m’as changé dix fois mon salaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Si le Dieu de mon père, le Dieu d’Abraham, et la frayeur d’Isaac n’eût été pour moi, certes tu m’eusses maintenant renvoyé à vide. Mais Dieu a regardé mon affliction, et le travail de mes mains, et il t’a repris la nuit passée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Et Laban répondit à Jacob, et dit: Ces filles sont mes filles, et ces enfants sont mes enfants, et ces troupeaux sont mes troupeaux, et tout ce que tu vois est à moi; et que ferais-je aujourd’hui à ces miennes filles, ou à leurs enfants qu’elles ont enfantés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Maintenant donc, viens, faisons ensemble une alliance, et elle sera en témoignage entre moi et toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Et Jacob prit une pierre, et la dressa pour monument.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Et dit à ses frères: Amassez des pierres. Et eux ayant apporté des pierres, ils en firent un monceau, et ils mangèrent là sur ce monceau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Et Laban l’appela Jégar-Sahadutha; et Jacob l’appela Gal-hed.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Et Laban dit: Ce monceau sera aujourd’hui témoin entre moi et toi; c’est pourquoi il fut nommé Gal-hed.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'Il fut aussi appelé Mitspa; parce que Laban dit: Que l’Eternel prenne garde à moi et à toi, quand nous nous serons retirés l’un d’avec l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Si tu maltraites mes filles, et si tu prends une autre femme que mes filles, ce ne sera pas un homme qui sera témoin entre nous, prends-y bien garde; c’est Dieu qui est témoin entre moi et toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Et Laban dit encore à Jacob: Regarde ce monceau, et considère le monument que j’ai dressé entre moi et toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Ce monceau sera témoin, et ce monument sera témoin, que lorsque je viendrai vers toi je ne passerai point ce monceau; ni lorsque tu viendras vers moi tu ne passeras point ce monceau et ce monument pour me faire du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Que les Dieux d’Abraham et les Dieux de Nacor, les Dieux de leur père, jugent entre nous; mais Jacob jura par la frayeur d’Isaac son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Et Jacob offrit un sacrifice en la montagne, et invita ses frères pour manger du pain; ils mangèrent donc du pain, et passèrent la nuit sur la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Et Laban se levant de bon matin, baisa ses fils, et ses filles, et les bénit, et s’en alla. Ainsi Laban s’en retourna chez lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Et Jacob continua son chemin, et les Anges de Dieu vinrent au-devant de lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Et quand Jacob les eut vus, il dit: C’est ici le camp de Dieu; et il nomma ce lieu-là Mahanajim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Et Jacob envoya des messagers devant soi vers Esaü son frère, au pays de Séhir, dans le territoire d’Edom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Et leur commanda, en disant: Vous parlerez en cette manière à mon Seigneur Esaü: Ainsi a dit ton serviteur Jacob; j’ai demeuré comme étranger chez Laban, et m’y suis arrêté jusqu’à présent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Et j’ai des boeufs, des ânes, des brebis, des serviteurs, et des servantes; ce que j’envoie annoncer à mon Seigneur, afin de trouver grâce devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Et les messagers retournèrent à Jacob, et lui dirent: Nous sommes venus vers ton frère Esaü, et même il vient au-devant de toi, ayant quatre cents hommes avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Alors Jacob craignit beaucoup, et fut dans une grande angoisse; et ayant partagé le peuple qui était avec lui, et les brebis, et les boeufs, et les chameaux en deux bandes, il dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Si Esaü vient à l’une de ces bandes, et qu’il la frappe, la bande qui demeurera de reste échappera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Jacob dit aussi: Ô Dieu de mon père Abraham, Dieu de mon père Isaac, ô Eternel qui m’as dit: Retourne en ton pays, et vers ta parenté, et je te ferai du bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Je suis trop petit au prix de toutes tes gratuités, et de toute la vérité dont tu as usé envers ton serviteur; car j’ai passé ce Jourdain avec mon bâton, mais maintenant je m’en retourne avec ces deux bandes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Je te prie, délivre-moi de la main de mon frère Esaü; car je crains qu’il ne vienne, et qu’il ne me frappe, et qu’il ne tue la mère avec les enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Or tu as dit: Certes, je te ferai du bien, et je ferai devenir ta postérité comme le sable de la mer, lequel on ne saurait compter à cause de son grand nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Et il passa la nuit en ce lieu-là, et prit de ce qui lui vint en main pour en faire un présent à Esaü son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Savoir deux cents chèvres, vingt boucs, deux cents brebis, vingt moutons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Trente femelles de chameaux qui allaitaient, et leurs petits; quarante jeunes vaches, dix jeunes taureaux, vingt ânesses, et dix ânons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Et il les mit entre les mains de ses serviteurs, chaque troupeau à part, et leur dit: Passez devant moi, et faites qu’il y ait de la distance entre un troupeau et l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Et il commanda au premier, disant: Quand Esaü mon frère te rencontrera, et te demandera, disant: A qui es-tu? et où vas-tu? et à qui sont ces choses qui sont devant toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Alors tu diras: Je suis à ton serviteur Jacob: c’est un présent qu’il envoie à mon Seigneur Esaü; et le voilà lui-même après nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Il fit aussi le même commandement au second, et au troisième, et à tous ceux qui allaient après les troupeaux, disant: Vous parlerez en ces termes-ci à Esaü, quand vous l’aurez trouvé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Et vous lui direz: Voici même ton serviteur Jacob est derrière nous. Car il disait: J’apaiserai sa colère par ce présent qui ira devant moi, et après cela, je verrai sa face; peut-être qu’il me regardera favorablement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Le présent donc alla devant lui; mais pour lui il demeura cette nuit-là avec sa troupe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Et il se leva cette nuit, et prit ses deux femmes, et ses deux servantes, et ses onze enfants, et passa le gué de Jabbok.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Il les prit donc, et leur fit passer le torrent; il fit aussi passer tout ce qu’il avait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Or Jacob étant resté seul, un homme lutta avec lui, jusqu’à ce que l’aube du jour fût levée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Et quand cet homme vit qu’il ne le pouvait pas vaincre, il toucha l’endroit de l’emboîture de sa hanche; ainsi l’emboîture de l’os de la hanche de Jacob fut démise quand l’homme luttait avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Et cet homme lui dit: Laisse-moi, car l’aube du jour est levée. Mais il dit: Je ne te laisserai point que tu ne m’aies béni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Et cet homme lui dit: Quel est ton nom? Il répondit: Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Alors il dit: Ton nom ne sera plus Jacob, mais Israël; car tu as été le maître en luttant avec Dieu et avec les hommes, et tu as été le plus fort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Et Jacob demanda, disant: Je te prie, déclare-moi ton nom. Et il répondit: Pourquoi demandes-tu mon nom? Et il le bénit là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Et Jacob nomma le lieu, Péniel; car j’ai, dit-il, vu Dieu face à face, et mon âme a été délivrée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Et le soleil se leva aussitôt qu’il eut passé Péniel, et il boitait d’une hanche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'C’est pourquoi jusqu’à ce jour les enfants d’Israël ne mangent point du muscle se retirant, qui est à l’endroit de l’emboîture de la hanche; parce que cet homme-là toucha l’endroit de l’emboîture de la hanche de Jacob, à l’endroit du muscle se retirant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Et Jacob levant ses yeux regarda; et voici, Esaü venait, et quatre cents hommes avec lui; et Jacob divisa les enfants en trois bandes, savoir sous Léa, et sous Rachel, et sous les deux servantes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Et il mit à la tête les servantes avec leurs enfants; Léa et ses enfants après; et Rachel et Joseph les derniers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Et il passa devant eux, et se prosterna en terre par sept fois, jusqu’à ce qu’il fût proche de son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Mais Esaü courut au-devant de lui, et l’embrassa, et se jetant sur son cou le baisa; et ils pleurèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Puis levant ses yeux, il vit les femmes et les enfants, et dit: Qui sont ceux-là? sont-ils à toi? Jacob lui répondit: Ce sont les enfants que Dieu, par sa grâce, a donnés à ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Et les servantes s’approchèrent, elles et leurs enfants, et se prosternèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Puis Léa aussi s’approcha avec ses enfants, et ils se prosternèrent, et ensuite Joseph et Rachel s’approchèrent, et se prosternèrent aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Et il dit: Que veux-tu faire avec tout ce camp que j’ai rencontré? Et il répondit: C’est pour trouver grâce devant mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Et Esaü dit: J’en ai abondamment, mon frère; que ce qui est à toi, soit à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Et Jacob répondit: Non, je te prie: si j’ai maintenant trouvé grâce devant toi, reçois ce présent de ma main; parce que j’ai vu ta face, comme si j’avais vu la face de Dieu, et parce que tu as été apaisé envers moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Reçois, je te prie, mon présent qui t’a été amené; car Dieu m’en a donné, par sa grâce, et j’ai de tout. Il le pressa donc tant, qu’il le prit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Et Esaü dit: Partons, et marchons, et je marcherai devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Mais Jacob lui dit: Mon Seigneur sait que ces enfants sont jeunes, et je suis chargé de brebis et de vaches qui allaitent, et si on les presse d’un seul jour, tout le troupeau mourra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Je te prie que mon Seigneur passe devant son serviteur, et je m’en irai tout doucement, au pas de ce bagage qui est devant moi, et au pas de ces enfants, jusqu’à ce que j’arrive chez mon Seigneur en Séhir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Et Esaü dit: Je te prie que je fasse demeurer avec toi quelques-uns de ce peuple qui est avec moi; et il répondit: Pourquoi cela? Je te prie que je trouve grâce envers mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Ainsi Esaü s’en retourna ce jour-là par son chemin en Séhir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Et Jacob s’en alla à Succoth, et bâtit une maison pour soi, et fit des cabanes pour son bétail; c’est pourquoi il nomma le lieu, Succoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Et Jacob arriva sain et sauf à la ville de Sichem, au pays de Canaan, venant de Paddan-Aram, et se campa devant la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Et il acheta une portion du champ dans lequel il avait dressé sa tente, de la main des enfants d’Hémor, père de Sichem, pour cent pièces d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Et il dressa là un autel, qu’il appela, le Dieu Fort, le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Or Dina, la fille que Léa avait enfantée à Jacob, sortit pour voir les filles du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Et Sichem, fils d’Hémor Hévien, Prince du pays, la vit, et l’enleva, et coucha avec elle, et la força.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Et son coeur fut attaché à Dina fille de Jacob, et il aima la jeune fille, et parla selon le coeur de la jeune fille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Sichem aussi parla à Hémor son père, en disant: Prends-moi cette fille pour être ma femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Et Jacob apprit qu’il avait violé Dina sa fille. Or ses fils étaient avec son bétail aux champs; et Jacob se tut jusqu’à ce qu’ils fussent revenus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Et Hémor, père de Sichem vint à Jacob pour parler avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Et les fils de Jacob étant revenus des champs, et ayant appris ce qui était arrivé, ils en eurent une grande douleur, et furent fort irrités de l’infamie que Sichem avait commise contre Israël, en couchant avec la fille de Jacob, ce qui ne se devait point faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Et Hémor leur parla, en disant: Sichem mon fils a mis son affection en votre fille; donnez-la-lui, je vous prie, pour femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Et alliez-vous avec nous, donnez-nous vos filles, et prenez nos filles pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Et habitez avec nous, et le pays sera à votre disposition; demeurez-y, et y trafiquez, et ayez-y des possessions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Sichem dit aussi au père et aux frères de la fille: Que je trouve grâce devant vous, et je donnerai tout ce que vous me direz.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Demandez-moi telle dot, et tel présent que vous voudrez, et je les donnerai comme vous me direz; et donnez-moi la jeune fille pour femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Alors les enfants de Jacob répondirent à Sichem et à Hémor son père; et agissant avec ruse (parce qu’il avait violé Dina leur sœur:)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Ils leur dirent: Nous ne pourrons point faire cela, de donner notre soeur à un homme incirconcis; car ce nous serait un opprobre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Mais nous nous accommoderons avec vous, pourvu que vous deveniez semblables à nous en circoncisant tous les mâles qui sont parmi vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Alors nous vous donnerons nos filles, et nous prendrons vos filles pour nous, et nous demeurerons avec vous, et nous ne serons qu’un seul peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Mais si vous ne consentez pas d’être circoncis, nous prendrons notre fille, et nous nous en irons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Et leurs discours plurent à Hémor et à Sichem, fils d’Hémor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Et le jeune homme ne différa point à faire ce qu’on lui avait proposé; car la fille de Jacob lui agréait beaucoup; et il était le plus considéré de tous ceux de la maison de son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Hémor donc et Sichem son fils vinrent à la porte de leur ville, et parlèrent aux gens de leur ville, en leur disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Ces gens-ci sont paisibles, ils sont avec nous; qu’ils habitent au pays, et qu’ils y trafiquent; car voici, le pays est d’une assez grande étendue pour eux. Nous prendrons leurs filles pour nos femmes, et nous leur donnerons nos filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Et ces gens s’accommoderont à nous en ceci pour habiter avec nous, et pour devenir un même peuple; pourvu que tout mâle qui est parmi nous soit circoncis, comme ils sont circoncis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Leur bétail, et leurs biens, et toutes leurs bêtes, ne seront-ils pas à nous? Seulement accommodons-nous à eux, et qu’ils demeurent avec nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Et tous ceux qui sortaient par la porte de leur ville obéirent à Hémor, et à Sichem son fils; et tout mâle d’entre tous ceux qui sortaient par la porte de leur ville fut circoncis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Mais il arriva au troisième jour, quand ils étaient dans la douleur, que deux des enfants de Jacob, Siméon et Lévi, frères de Dina, ayant pris leurs épées, entrèrent hardiment dans la ville, et tuèrent tous les mâles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Ils passèrent aussi au tranchant de l’épée Hémor et Sichem son fils, et emmenèrent Dina de la maison de Sichem, et sortirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Et ceux-là étant tués, les fils de Jacob vinrent, et pillèrent la ville, parce qu’on avait violé leur soeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Et ils prirent leurs troupeaux, leurs boeufs, leurs ânes, et ce qui était dans la ville, et aux champs:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Et tous leurs biens, et tous leurs petits enfants, et emmenèrent prisonnières leurs femmes; et les pillèrent, avec tout ce qui était dans les maisons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Alors Jacob dit à Siméon et Lévi: Vous m’avez troublé, en me mettant en mauvaise odeur parmi les habitants du pays, tant Cananéens que Phéréziens, et je n’ai que peu de gens; ils s’assembleront donc contre moi, et me frapperont, et me détruiront, moi et ma maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Et ils répondirent: Fera-t-on de notre soeur comme d’une paillarde?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Or Dieu dit à Jacob: Lève-toi, monte à Béthel, et demeure là, et y dresse un autel au Dieu Fort qui t’apparut, quand tu t’enfuyais de devant Esaü ton frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Et Jacob dit à sa famille, et à tous ceux qui étaient avec lui: Otez les Dieux des étrangers qui sont au milieu de vous, et vous purifiez, et changez de vêtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Et levons-nous, et montons à Béthel, et je ferai là un autel au Dieu Fort qui m’a répondu au jour de ma détresse, et qui a été avec moi dans le chemin où j’ai marché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Alors ils donnèrent à Jacob tous les Dieux des étrangers qu’ils avaient en leurs mains, et les bagues qui étaient à leurs oreilles, et il les cacha sous un chêne qui était auprès de Sichem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Puis ils partirent; et la frayeur de Dieu fut sur les villes des environs; tellement qu’ils ne poursuivirent point les enfants de Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Ainsi Jacob, et tout le peuple qui était avec lui, vint à Luz, qui est au pays de Canaan, laquelle est Béthel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Et il y bâtit un autel, et nomma ce lieu-là, le Dieu Fort de Béthel; car Dieu lui était apparu là, quand il s’enfuyait de devant son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Alors mourut Débora, la nourrice de Rébecca, et elle fut ensevelie au-dessous de Béthel sous un chêne, qui fut appelé Allon-bacuth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Dieu apparut encore à Jacob, quand il venait de Paddan-Aram, et le bénit,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Et lui dit: Ton nom est Jacob; mais tu ne seras plus nommé Jacob, car ton nom sera Israël; et il le nomma Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Dieu lui dit aussi: Je suis le Dieu Fort, Tout-Puissant: augmente, et multiplie: une nation, même une multitude de nations naîtra de toi, même des Rois sortiront de tes reins;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Et je te donnerai le pays que j’ai donné à Abraham et à Isaac, et je le donnerai à ta postérité après toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Et Dieu remonta d’avec lui du lieu où il lui avait parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Et Jacob dressa un monument au lieu où Dieu lui avait parlé, savoir une pierre pour monument, et il répandit dessus une aspersion, et y versa de l’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Jacob donc nomma le lieu où Dieu lui avait parlé, Béthel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Puis ils partirent de Béthel, et il y avait encore quelque petit espace de pays pour arriver à Ephrat, lorsque Rachel accoucha, et elle fut dans un grand travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Et comme elle avait beaucoup de peine à accoucher, la sage-femme lui dit: Ne crains point; car tu as encore ici un fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Et comme elle rendait l’âme, (car elle mourut,) elle nomma l’enfant Bénoni; mais son père le nomma Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'C’est ainsi que mourut Rachel, et elle fut ensevelie au chemin d’Ephrat, qui est Bethléhem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Et Jacob dressa un monument sur son sépulcre. C’est le monument du sépulcre de Rachel qui subsiste encore aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Puis Israël partit, et dressa ses tentes au-delà de Migdal-Héder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Et il arriva que quand Israël demeurait en ce pays-là, Ruben vint, et coucha avec Bilha, concubine de son père; et Israël l’apprit. Or Jacob avait douze fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Les fils de Léa étaient Ruben, premier-né de Jacob, Siméon, Lévi, Juda, Issacar, et Zabulon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Les fils de Rachel, Joseph et Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Les fils de Bilha, servante de Rachel, Dan, et Nephthali.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Les fils de Zilpa, servante de Léa, Gad et Aser. Ce sont là les enfants de Jacob, qui lui naquirent en Paddan-Aram.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Et Jacob vint vers Isaac son père en la plaine de Mamré à Kirjath-arbah, qui est Hébron, où Abraham et Isaac avaient demeuré comme étrangers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Et le temps qu’Isaac vécut, fut cent quatre-vingts ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Ainsi Isaac défaillant mourut, et fut recueilli avec ses peuples, âgé et rassasié de jours; et Esaü et Jacob ses fils l’ensevelirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Or ce sont ici les générations d’Esaü, qui est Edom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esaü prit ses femmes d’entre les filles de Canaan: savoir Hada fille d’Elon Héthien, et Aholibama fille de Hana, petite- fille de Tsibhon Hévien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'Il prit aussi Basmath fille d’Ismaël, soeur de Nébajoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Et Hada enfanta à Esaü Eliphaz; et Basmath enfanta Réhuel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Et Aholibama enfanta Jéhus, et Jahlam, et Korah. Ce sont là les enfants d’Esaü, qui lui naquirent au pays de Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Et Esaü prit ses femmes et ses fils, et ses filles, et toutes les personnes de sa maison, tous ses troupeaux, et ses bêtes, et tout le bien qu’il avait acquis au pays de Canaan, et il s’en alla en un autre pays, loin de Jacob son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Car leurs biens étaient si grands, qu’ils n’auraient pas pu demeurer ensemble; et le pays où ils demeuraient comme étrangers, ne les eût pas pu contenir à cause de leurs troupeaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Ainsi Esaü habita en la montagne de Séhir; Esaü est Edom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Et ce sont ici les générations d’Esaü, père d’Edom, en la montagne de Séhir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Ce sont ici les noms des enfants d’Esaü: Eliphaz fils de Hada, femme d’Esaü; Réhuel fils de Basmath, femme d’Esaü.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Et les enfants d’Eliphaz, furent Téman, Omar, Tsépho, Gahtam et Kénaz.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Et Timnaph fut concubine d’Eliphaz, fils d’Esaü, et elle enfanta Hamalec à Eliphaz. Ce sont là les enfants de Hada femme d’Esaü.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Et ce sont ici les enfants de Réhuel: Nahath, Zérah, Samma, et Miza. Ceux- ci furent enfants de Basmath femme d’Esaü.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Et ceux-ci furent les enfants d’Aholibama, fille de Hana, petite- fille de Tsibhon, et femme d’Esaü, qui enfanta à Esaü Jéhus, Jahlam, et Korah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Ce sont ici les Ducs des enfants d’Esaü. Des enfants d’Eliphaz premier-né d’Esaü, le Duc Téman, le Duc Omar, le Duc Tsépho, le Duc Kénaz,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'Le Duc Korah, le Duc Gahtam, le Duc Hamalec. Ce sont là les Ducs d’Eliphaz au pays d’Edom, qui furent enfants de Hada.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Et ce sont ici ceux des enfants de Réhuel fils d’Esaü: le Duc Nahath, le Duc Zérah, le Duc Samma, et le Duc Miza. Ce sont là les Ducs sortis de Réhuel au pays d’Edom, qui furent enfants de Basmath femme d’Esaü.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Et ce sont ici ceux des enfants d’Aholibama femme d’Esaü: le Duc Jéhus, le Duc Jahlam, le Duc Korah; qui sont les Ducs sortis d’Aholibama fille de Hana, femme d’Esaü.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Ce sont là les enfants d’Esaü, qui est Edom, et ce sont là leurs Ducs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Ce sont ici les enfants de Séhir Horien, qui avaient habité au pays, Lotan, Sobal, Tsibhon, et Hana.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Dison, Etser, et Disan; qui sont les Ducs des Horiens, enfants de Séhir au pays d’Edom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Et les enfants de Lotan, furent Hori et Héman; et Timnah était soeur de Lotan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Et ce sont ici les enfants de Sobal: Halvan, Manahath, Hébal, Sépho, et Onam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Et ce sont ici les enfants de Tsibhon: Aja et Hana. Cet Hana est celui qui trouva les mulets au désert, quand il paissait les ânes de Tsibhon son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Et ce sont ici les enfants de Hana: Disan, et Aholibama fille de Hana.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Et ce sont ici les enfants de Disan: Hemdan, Esban, Jithran, et Kéran.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Et ce sont ici les enfants d’Etser: Bilhan, Zahavan, et Hakan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Et ce sont ici les enfants de Disan: Huts et Aran.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Ce sont ici les Ducs des Horiens: le Duc Lotan, le Duc Sobal, le Duc Tsibhon, le Duc Hana.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'Le Duc Dison, le Duc Etser, le Duc Disan. Ce sont là les Ducs des Horiens, selon que leurs Ducs étaient établis au pays de Séhir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Et ce sont ici les Rois qui ont régné au pays d’Edom, avant qu’aucun Roi régnât sur les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bélah, fils de Béhor, régna en Edom, et le nom de sa ville était Dinhaba.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Et Bélah mourut, et Jobab fils de Zérah de Botsra, régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Et Jobab mourut, et Husam du pays des Témanites, régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Et Husam mourut, et Hadad fils de Bédad régna en sa place, qui défit Madian au territoire de Moab; et le nom de sa ville était Havith.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Et Hadad mourut, et Samla de Masréka régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Et Samla mourut, et Saül de Réhoboth du fleuve, régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Et Saül mourut, et Bahal-hanan fils de Hacbor régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Et Bahal-hanan fils de Hacbor mourut, et Hadar régna en sa place; et le nom de sa ville était Pahu; et le nom de sa femme Méhétabéel, fille de Matred, petite- fille de Mézahab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Et ce sont ici les noms des Ducs d’Esaü selon leurs familles, selon leurs lieux, selon leurs noms: le Duc Timnah, le Duc Halva, le Duc Jéteth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'Le Duc Aholibama, le Duc Ela, le Duc Pinon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'Le Duc Kénaz, le Duc Téman, le Duc Mibtsar,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'Le Duc Magdiel, et le Duc Hiram. Ce sont là les Ducs d’Edom selon leurs demeures du pays de leur possession. C’est Esaü le père d’Edom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Or Jacob demeura au pays où son père avait demeuré comme étranger, c’est-à- dire au pays de Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Ce sont ici les générations de Jacob. Joseph âgé de dix-sept ans, paissait avec ses frères les troupeaux, et il était jeune garçon entre les enfants de Bilha, et entre les enfants de Zilpa, femmes de son père. Et Joseph rapporta à leur père leurs méchants discours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Or Israël aimait Joseph plus que tous ses autres fils, parce qu’il l’avait eu en sa vieillesse, et il lui fit une robe bigarrée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Et ses frères voyant que leur père l’aimait plus qu’eux tous, le haïssaient, et ne pouvaient lui parler avec douceur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Or Joseph songea un songe, lequel il récita à ses frères; et ils le haïrent encore davantage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Il leur dit donc: Ecoutez, je vous prie, le songe que j’ai songé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Voici, nous liions des gerbes au milieu d’un champ; et voici, ma gerbe se leva, et se tint droite; et voici, vos gerbes l’environnèrent, et se prosternèrent devant ma gerbe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Alors ses frères lui dirent: Régnerais-tu en effet sur nous? et dominerais- tu en effet sur nous? Et ils le haïrent encore plus pour ses songes, et pour ses paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Il songea encore un autre songe, et il le récita a ses frères, en disant: Voici, j’ai songé encore un songe, et voici, le soleil, et la lune, et onze étoiles se prosternaient devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Et quand il le récita à son père, et à ses frères, son père le reprit, et lui dit: Que veut dire ce songe que tu as songé? Faudra-t-il que nous venions moi, et ta mère, et tes frères nous prosterner en terre devant toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Et ses frères eurent de l’envie contre lui; mais son père retenait ses discours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Or ses frères s’en allèrent paître les troupeaux de leur père en Sichem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Et Israël dit à Joseph: Tes frères ne paissent-ils pas les troupeaux en Sichem? Viens, que je t’envoie vers eux; et il lui répondit: Me voici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Et il lui dit: Va maintenant, vois si tes frères se portent bien, et si les troupeaux sont en bon état, et rapporte-le-moi. Ainsi il l’envoya de la vallée de Hébron, et il vint jusqu’en Sichem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Et un homme le trouva comme il était errant par les champs; et cet homme lui demanda, et lui dit: Que cherches-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Et il répondit: Je cherche mes frères; je te prie, enseigne-moi où ils paissent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Et l’homme dit: Ils sont partis d’ici; et j’ai entendu qu’ils disaient: Allons en Dothaïn. Joseph donc alla après ses frères, et les trouva en Dothaïn.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Et ils le virent de loin; et avant qu’il approchât d’eux, ils complotèrent contre lui, pour le tuer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Et ils se dirent l’un à l’autre: Voici, ce maître songeur vient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Maintenant donc, venez, et tuons-le, et jetons-le dans une de ces fosses; et nous dirons qu’une mauvaise bête l’a dévoré, et nous verrons que deviendront ses songes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Mais Ruben entendit cela, et le délivra de leurs mains, en disant: Ne lui otons point la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Ruben leur dit encore: Ne répandez point le sang; jetez-le dans cette fosse qui est au désert, mais ne mettez point la main sur lui. C’était pour le délivrer de leurs mains, et le renvoyer à son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Aussitôt donc que Joseph fut venu à ses frères, ils le dépouillèrent de sa robe, de cette robe bigarrée qui était sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Et l’ayant pris, ils le jetèrent dans la fosse; mais la fosse était vide, et il n’y avait point d’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Ensuite ils s’assirent pour manger du pain; et levant les yeux ils regardèrent, et voici une troupe d’Ismaélites qui passaient, et qui venaient de Galaad, et leurs chameaux portaient des drogues, du baume, et de la myrrhe; et ils allaient porter ces choses en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Et Juda dit à ses frères: Que gagnerons-nous à tuer notre frère, et à cacher son sang?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Venez, et vendons-le à ces Ismaélites, et ne mettons point notre main sur lui; car notre frère, c’est notre chair; et ses frères y acquiescèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Et comme les marchands Madianites passaient, ils tirèrent et firent remonter Joseph de la fosse, et le vendirent vingt pièces d’argent aux Ismaélites, qui emmenèrent Joseph en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Puis Ruben retourna à la fosse, et voici, Joseph n’était plus dans la fosse; et Ruben déchira ses vêtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Il retourna vers ses frères, et leur dit: L’enfant ne se trouve point; et moi! moi! où irai-je?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Et ils prirent la robe de Joseph, et ayant tué un bouc d’entre les chèvres, ils ensanglantèrent la robe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Puis ils envoyèrent et firent porter à leur père la robe bigarrée, en lui disant: Nous avons trouvé ceci; reconnais maintenant si c’est la robe de ton fils, ou non.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Et il la reconnut, et dit: C’est la robe de mon fils; une mauvaise bête l’a dévoré: certainement Joseph a été déchiré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Et Jacob déchira ses vêtements, et mit un sac sur ses reins, et mena deuil sur son fils durant plusieurs jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Et tous ses fils, et toutes ses filles vinrent pour le consoler. Mais il rejeta toute consolation, et dit: Certainement je descendrai en menant deuil au sépulcre vers mon fils; c’est ainsi que son père le pleurait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Et les Madianites le vendirent en Egypte à Potiphar, Eunuque de Pharaon, Prévôt de l’hôtel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Il arriva qu’en ce temps-là Juda descendit d’auprès de ses frères, et se retira vers un homme Hadullamite, qui avait nom Hira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Et Juda y vit la fille d’un Cananéen, nommé Suah, et il la prit, et vint vers elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Et elle conçut et enfanta un fils, et on le nomma Her.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Et elle conçut encore et enfanta un fils, et elle le nomma Onan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Elle enfanta encore un fils, et elle le nomma Séla. Et Juda était en Késib quand elle accoucha de celui-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Et Juda maria Her, son premier-né, avec une fille qui avait nom Tamar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Mais Her le premier-né de Juda était méchant devant l’Eternel, et l’Eternel le fit mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Alors Juda dit à Onan: Viens vers la femme de ton frère, et prends-la pour femme, comme étant son beau-frère, et suscite des enfants à ton frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Mais Onan sachant que les enfants ne seraient pas à lui, se corrompait contre terre toutes les fois qu’il venait vers la femme de son frère, afin qu’il ne donnât pas des enfants à son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Et ce qu’il faisait déplut à l’Eternel, c’est pourquoi il le fit aussi mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Et Juda dit à Tamar sa belle-fille: Demeure veuve en la maison de ton père, jusqu’à ce que Séla mon fils soit grand; car il dit: Il faut prendre garde qu’il ne meure comme ses frères. Ainsi Tamar s’en alla, et demeura en la maison de son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Et après plusieurs jours la fille de Suah, femme de Juda, mourut; et Juda, s’étant consolé, monta vers les tondeurs de ses brebis à Timnath, avec Hira Hadullamite, son intime ami.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Et on fit savoir à Tamar, et on lui dit: Voici, ton beau-père monte à Timnath, pour tondre ses brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Et elle ôta de dessus soi les habits de son veuvage, et se couvrit d’un voile, et s’en enveloppa, et s’assit en un carrefour qui était sur le chemin tirant vers Timnath; parce qu’elle voyait que Séla était devenu grand, et qu’elle ne lui avait point été donnée pour femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Et quand Juda la vit, il s’imagina que c’était une prostituée; car elle avait couvert son visage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Et il se détourna vers elle au chemin, et lui dit: Permets, je te prie, que je vienne vers toi; car il ne savait pas que ce fût sa belle-fille. Et elle répondit: Que me donneras-tu afin que tu viennes vers moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Et il dit: Je t’enverrai un chevreau d’entre les chèvres du troupeau. Et elle répondit: Me donneras-tu des gages, jusqu’à ce que tu l’envoies?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Et il dit: Quel gage est-ce que je te donnerai? Et elle répondit: Ton cachet, ton mouchoir, et ton bâton que tu as en ta main. Et il les lui donna; et il vint vers elle, et elle conçut de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Puis elle se leva et s’en alla, et ayant quitté son voile elle reprit les habits de son veuvage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Et Juda envoya un chevreau d’entre les chèvres par l’Hadullamite son intime ami; afin qu’il reprît le gage de la main de la femme; mais il ne la trouva point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Et il interrogea les hommes du lieu où elle avait été, en disant: Où est cette prostituée qui était dans le carrefour sur le chemin? Et ils répondirent: Il n’y a point eu ici de prostituée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Et il retourna à Juda, et lui dit: Je ne l’ai point trouvée; et même les gens du lieu m’ont dit: Il n’y a point eu ici de prostituée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Et Juda dit: Qu’elle garde le gage, de peur que nous ne soyons en mépris. Voici, j’ai envoyé ce chevreau, mais tu ne l’as point trouvée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Or il arriva qu’environ trois mois après on fit un rapport à Juda, en disant: Tamar ta belle-fille a commis un adultère, et voici elle est même enceinte. Et Juda dit: Faites-la sortir, et qu’elle soit brûlée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Et comme on la faisait sortir, elle envoya dire à son beau-père: Je suis enceinte de l’homme à qui ces choses appartiennent. Elle dit aussi: Reconnais, je te prie, à qui est ce cachet, ce mouchoir, et ce bâton.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Alors Juda les reconnut, et il dit: Elle est plus juste que moi; parce que je ne l’ai point donnée à Séla, mon fils; et il ne la connut plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Et comme elle fut sur le point d’accoucher, voici, deux jumeaux étaient dans son ventre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Et dans le temps qu’elle enfantait, l’un d’eux donna la main, et la sage- femme la prit, et lia sur sa main un fil d’écarlate, en disant: Celui-ci sort le premier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Mais comme il eut retiré sa main, voici, son frère sortit; et elle dit: Quelle ouverture t’es-tu faite! L’ouverture soit sur toi; et on le nomma Pharez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Ensuite son frère sortit, ayant sur sa main le fil d’écarlate, et on le nomma Zara.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Or quand on eut amené Joseph en Egypte, Potiphar, Eunuque de Pharaon, Prévôt de l’hôtel, Egyptien, l’acheta de la main des Ismaélites, qui l’y avaient amené.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Et l’Eternel était avec Joseph; et il prospéra, et demeura dans la maison de son maître Egyptien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Et son maître vit que l’Eternel était avec lui, et que l’Eternel faisait prospérer entre ses mains tout ce qu’il faisait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'C’est pourquoi Joseph trouva grâce devant son maître, et il le servait. Et son maître l’établit sur sa maison, et lui remit entre les mains tout ce qui lui appartenait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Et il arriva que depuis qu’il l’eut établi sur sa maison, et sur tout ce qu’il avait, l’Eternel bénit la maison de cet Egyptien à cause de Joseph; et la bénédiction de l’Eternel fut sur toutes les choses qui étaient à lui, tant en la maison, qu’aux champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Il remit donc tout ce qui était à lui entre les mains de Joseph, sans entrer avec lui en connaissance d’aucune chose, sinon du pain qu’il mangeait. Or Joseph était de belle taille, et beau à voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Et il arriva après ces choses, que la femme de son maître jeta les yeux sur Joseph, et lui dit: Couche avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Mais il le refusa, et dit à la femme de son maître: Voici, mon maître n’entre en aucune connaissance avec moi des choses qui sont dans sa maison, et il m’a remis entre les mains tout ce qui lui appartient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Il n’y a personne dans cette maison qui soit plus grand que moi, et il ne m’a rien défendu que toi, parce que tu es sa femme; et comment ferais-je un si grand mal, et pécherais-je contre Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Et quoiqu’elle en parlât à Joseph chaque jour, toutefois il ne lui accorda pas de coucher auprès d’elle, ni d’être avec elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Mais il arriva, un jour qu’il était venu à la maison pour faire ce qu’il avait à faire, et qu’il n’y avait aucun des domestiques dans la maison,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Qu’elle le prit par sa robe, et lui dit: Couche avec moi. Mais il lui laissa sa robe entre les mains, s’enfuit, et sortit dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Et lorsqu’elle eut vu qu’il lui avait laissé sa robe entre les mains, et qu’il s’en était fui,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'Elle appela les gens de sa maison, et leur parla, en disant: Voyez, on nous a amené un homme Hébreu pour se moquer de nous, il est venu à moi pour coucher avec moi; mais j’ai crié à haute voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Et sitôt qu’il a ouï que j’ai élevé ma voix, et que j’ai crié, il a laissé son vêtement auprès de moi, il s’est enfui, et est sorti dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Et elle garda le vêtement de Joseph, jusqu’à ce que son maître fût revenu à la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Alors elle lui parla en ces mêmes termes, et dit: Le serviteur Hébreu que tu nous as amené, est venu à moi, pour se moquer de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Mais comme j’ai élevé ma voix, et que j’ai crié, il a laissé son vêtement auprès de moi, et s’en est fui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Et sitôt que le maître de Joseph eut entendu les paroles de sa femme, qui lui disait: Ton serviteur m’a fait ce que je t’ai dit, sa colère s’enflamma.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Et le maître de Joseph le prit, et le mit dans une étroite prison; dans l’endroit où les prisonniers du Roi étaient renfermés, et il fut là en prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Mais l’Eternel fut avec Joseph; il étendit sa gratuité sur lui, et lui fit trouver grâce envers le maître de la prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Et le maître de la prison mit entre les mains de Joseph tous les prisonniers qui étaient dans la prison, et tout ce qu’il y avait à faire, il le faisait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Et le maître de la prison ne revoyait rien de tout ce que Joseph avait entre ses mains; parce que l’Eternel était avec lui, et que l’Eternel faisait prospérer tout ce qu’il faisait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Après ces choses, il arriva que l’Echanson du Roi d’Egypte, et le Panetier offensèrent le Roi d’Egypte, leur Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Et Pharaon fut fort irrité contre ces deux Eunuques, contre le grand Echanson, et contre le grand Panetier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'Et les mit en garde dans la maison du Prévôt de l’hôtel, dans la prison étroite, au même lieu où Joseph était renfermé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Et le Prévôt de l’hôtel les mit entre les mains de Joseph, qui les servait; et ils furent quelques jours en prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Et tous deux songèrent un songe, chacun son songe en une même nuit, et chacun selon l’explication de son songe; tant l’Echanson que le Panetier du Roi d’Egypte, qui étaient renfermés dans la prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Et Joseph vint à eux le matin, et les regarda; et voici ils étaient fort tristes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Et il demanda à ces Eunuques de Pharaon, qui étaient avec lui dans la prison de son maître, et leur dit: D’où vient que vous avez aujourd’hui si mauvais visage?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Et ils lui répondirent: Nous avons songé des songes, et il n’y a personne qui les explique. Et Joseph leur dit: Les explications ne sont-elles pas de Dieu? Je vous prie, contez-moi vos songes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Et le grand Echanson conta son songe à Joseph, et lui dit: Il me semblait en songeant que je voyais un cep devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'Et il y avait en ce cep trois sarments; et il était près de fleurir; sa fleur sortit, et ses grappes firent mûrir les raisins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Et la coupe de Pharaon était en ma main, et je prenais les raisins, et les pressais dans la coupe de Pharaon, et je lui donnais la coupe en sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Et Joseph lui dit: Voici son explication: Les trois sarments sont trois jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Dans trois jours Pharaon élèvera ta tête, et te rétablira en ton premier état, et tu donneras la coupe à Pharaon en sa main, selon ton premier office, lorsque tu étais Echanson.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Mais souviens-toi de moi quand ce bonheur te sera arrivé, et fais-moi, je te prie, cette grâce, que tu fasses mention de moi à Pharaon, et qu’il me fasse sortir de cette maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Car certainement j’ai été dérobé du pays des Hébreux; et même je n’ai rien fait ici pour quoi l’on dût me mettre en cette fosse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Alors le grand Panetier voyant que Joseph avait expliqué ce songe favorablement, lui dit: J’ai aussi songé, et il me semblait qu’ il y avait trois corbeilles blanches sur ma tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Et dans la plus haute corbeille il y avait de toutes sortes de viandes du métier de boulanger, pour Pharaon; et les oiseaux les mangeaient dans la corbeille qui était sur ma tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Et Joseph répondit, et dit: Voici son explication: Les trois corbeilles sont trois jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Dans trois jours Pharaon élèvera ta tête de dessus toi, et te fera pendre à un bois, et les oiseaux mangeront ta chair de dessus toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Et il arriva au troisième jour, qui était le jour de la naissance de Pharaon, qu’il fit un festin à tous ses serviteurs, et il fit sortir de prison le grand Echanson, et le maître Panetier, ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Et il rétablit le grand Echanson dans son office d’Echanson, lequel donna la coupe à Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Mais il fit pendre le grand Panetier, selon que Joseph le leur avait expliqué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Cependant le grand Echanson ne se souvint point de Joseph; mais l’oublia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Mais il arriva qu’au bout de deux ans entiers Pharaon songea, et il lui semblait qu’il était près du fleuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Et voici, sept jeunes vaches belles à voir, grasses et en bon point, montaient hors du fleuve, et paissaient dans des marécages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Et voici sept autres jeunes vaches, laides à voir, et maigres, montaient hors du fleuve après les autres, et se tenaient auprès des autres jeunes vaches sur le bord du fleuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Et les jeunes vaches laides à voir, et maigres, mangèrent les sept jeunes vaches belles à voir, et grasses. Alors Pharaon s’éveilla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Puis il se rendormit, et songea pour la seconde fois, et il lui semblait que sept épis grenus et beaux sortaient d’un même tuyau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Ensuite il lui semblait que sept autres épis minces et flétris par le vent d’Orient, germaient après ceux-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Et les épis minces engloutirent les sept épis grenus et pleins. Alors Pharaon s’éveilla; et voilà le songe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Et il arriva au matin que son esprit fut effrayé, et il envoya appeler tous les magiciens et tous les sages d’Egypte, et leur récita ses songes, mais il n’y avait personne qui les lui interprétât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Alors le grand Echanson parla à Pharaon, en disant: Je rappellerai aujourd’hui le souvenir de mes fautes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Lorsque Pharaon fut irrité contre ses serviteurs, et nous fit mettre, le grand Panetier et moi, en prison, dans la maison du Prévôt de l’hôtel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Alors lui et moi songeâmes un songe en une même nuit, chacun songeant ce qui lui est arrivé selon l’interprétation de son songe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Or il y avait là avec nous un garçon Hébreu, serviteur du Prévôt de l’hôtel, et nous lui contâmes nos songes, et il nous les expliqua, donnant à chacun l’explication selon son songe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Et la chose arriva comme il nous l’avait interprétée; car le Roi me rétablit en mon état, et fit pendre l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Alors Pharaon envoya appeler Joseph, et on le fit sortir en hâte de la prison; et on le rasa, et on lui fit changer de vêtements; puis il vint vers Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Et Pharaon dit à Joseph: J’ai songé un songe, et il n’ y a personne qui l’explique; or j’ai appris que tu sais expliquer les songes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Et Joseph répondit à Pharaon, en disant: Ce sera Dieu, et non pas moi, qui répondra ce qui concerne la prospérité de Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Et Pharaon dit à Joseph: Je songeais que j’étais sur le bord du fleuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Et voici, sept jeunes vaches grasses, et en bon point, et fort belles, sortaient du fleuve, et paissaient dans des marécages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Et voici, sept autres jeunes vaches montaient après celles-là, chétives, si laides, et si maigres, que je n’en ai jamais vu de semblables en laideur dans tout le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Mais les jeunes vaches maigres et laides dévorèrent les sept premières jeunes vaches grasses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Qui entrèrent dans leur ventre, sans qu’il parut qu’elles y fussent entrées; car elles étaient aussi laides à voir qu’au commencement; alors je me réveillai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Je vis aussi en songeant, et il me semblait que sept épis sortaient d’un même tuyau, pleins et beaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Puis voici sept épis petits, minces, et flétris par le vent d’Orient, qui germaient après.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Mais les épis minces engloutirent les sept beaux épis; et j’ai dit ces songes aux magiciens; mais aucun ne me les a expliqués.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Et Joseph répondit à Pharaon: Ce que Pharaon a songé n’est qu’une même chose; Dieu a déclaré à Pharaon ce qu’il s’en va faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Les sept belles jeunes vaches sont sept ans; et les sept beaux épis sont sept ans; c’est un même songe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Et les sept jeunes vaches maigres et laides qui montaient après celles-là, sont sept ans; et les sept épis vides et flétris par le vent d’Orient, seront sept ans de famine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'C’est ce que j’ai dit à Pharaon, savoir que Dieu a fait voir à Pharaon ce qu’il s’en va faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Voici, sept ans viennent auxquels il y aura une grande abondance dans tout le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Mais après ces années-là viendront sept ans de famine; alors on oubliera toute cette abondance au pays d’Egypte, et la famine consumera le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Et on ne reconnaîtra plus cette abondance au pays, à cause de la famine qui viendra après; car elle sera très-grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Et quant à ce que le songe a été réitéré à Pharaon pour la seconde fois, c’est que la chose est arrêtée de Dieu, et que Dieu se hâte de l’exécuter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Or maintenant, que Pharaon choisisse un homme entendu et sage, et qu’il l’établisse sur le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Que Pharaon aussi fasse ceci: Qu’il établisse des Commissaires sur le pays, et qu’il prenne la cinquième partie du revenu du pays d’Egypte durant les sept années d’abondance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Et qu’on amasse tous les vivres de ces bonnes années qui viendront, et que le blé qu’on amassera, demeure sous la puissance de Pharaon pour nourriture dans les villes, et qu’on le garde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Et ces vivres-là seront pour la provision du pays durant les sept années de famine qui seront au pays d’Egypte, afin que le pays ne soit pas consumé par la famine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Et la chose plut à Pharaon, et à tous ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Et Pharaon dit à ses serviteurs: Pourrions-nous trouver un homme semblable à celui-ci, qui eût l’Esprit de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Et Pharaon dit à Joseph: Puisque Dieu t’a fait connaître toutes ces choses, il n’y a personne qui soit si entendu ni si sage que toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Tu seras sur ma maison, et tout mon peuple te baisera la bouche; seulement je serai, plus grand que toi quant au trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Pharaon dit encore à Joseph: Regarde, je t’ai établi sur tout le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Alors Pharaon ôta son anneau de sa main, et le mit en celle de Joseph, et le fit vêtir d’habits de fin lin, et lui mit un collier d’or au cou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Et le fit monter sur le chariot qui était le second après le sien, et on criait devant lui; qu’on s’agenouille; et il l’établit sur tout le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Et Pharaon dit à Joseph: Je suis Pharaon, mais sans toi nul ne lèvera la main ni le pied dans tout le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Et Pharaon appela le nom de Joseph Tsaphenath-Pahanéah, et lui donna pour femme Asenath, fille de Potiphérah, Gouverneur d’On; et Joseph alla visiter le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Or Joseph était âgé de trente ans, quand il se présenta devant Pharaon Roi d’Egypte, et étant sorti de devant Pharaon, il passa par tout le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Et la terre rapporta très-abondamment durant les sept années de fertilité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Et Joseph amassa tous les grains de ces sept années, qui furent recueillis au pays d’Egypte, et mit ces grains dans les villes; en chaque ville les grains des champs d’alentour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Ainsi Joseph amassa une grande quantité de blé, comme le sable de la mer; tellement qu’on cessa de le mesurer, parce qu’il était sans nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Or avant que la première année de la famine vînt, il naquit deux enfants à Joseph, qu’Asenath fille de Potiphérah, Gouverneur d’On, lui enfanta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Et Joseph nomma le premier-né, Manassé; parce que, dit-il, Dieu m’a fait oublier tous mes travaux, et toute la maison de mon père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Et il nomma le second, Ephraïm; parce que, dit-il, Dieu m’a fait fructifier au pays de mon affliction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Alors finirent les sept années de l’abondance qui avait été au pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Et les sept années de la famine commencèrent, comme Joseph l’avait prédit. Et la famine fut dans tous les pays; mais il y avait du pain dans tout le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Puis tout le pays d’Egypte fut affamé, et le peuple cria à Pharaon pour avoir du pain. Et Pharaon répondit à tous les Egyptiens: Allez à Joseph, et faites ce qu’il vous dira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'La famine donc étant dans tout le pays, Joseph ouvrit tous les greniers qui étaient chez les Egyptiens, et leur distribua du blé; et la famine augmentait au pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'On venait aussi de tout pays en Egypte vers Joseph, pour acheter du blé; car la famine était fort grande par toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Et Jacob voyant qu’il y avait du blé à vendre en Egypte, dit à ses fils: Pourquoi vous regardez-vous les uns les autres?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Il leur dit aussi: Voici, j’ai appris qu’il y a du blé à vendre en Egypte, descendez-y, et nous en achetez, afin que nous vivions, et que nous ne mourions point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Alors dix frères de Joseph descendirent pour acheter du blé en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Mais Jacob n’envoya point Benjamin frère de Joseph, avec ses frères; car il disait: Il faut prendre garde que quelque accident mortel ne lui arrive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Ainsi les fils d’Israël allèrent en Egypte pour acheter du blé, avec ceux qui y allaient; car la famine était au pays de Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Or Joseph commandait dans le pays, et il faisait vendre le blé à tous les peuples de la terre. Les frères donc de Joseph vinrent, et se prosternèrent devant lui la face en terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Et Joseph ayant vu ses frères, les reconnut; mais il contrefit l’étranger avec eux, et il leur parla rudement, en leur disant: D’où venez-vous? Et ils répondirent: Du pays de Canaan, pour acheter des vivres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Joseph donc reconnut ses frères; mais eux ne le connurent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Alors Joseph se souvint des songes qu’il avait songés d’eux, et leur dit: Vous êtes des espions, vous êtes venus pour remarquer les lieux faibles du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Et ils lui répon dirent: Non, mon Seigneur, mais tes serviteurs sont venus pour acheter des vivres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Nous sommes tous enfants d’un même homme, nous sommes gens de bien; tes serviteurs ne sont point des espions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Et il leur dit: Cela n’est pas; mais vous êtes venus pour remarquer les lieux faibles du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Et ils répondirent: Nous étions douze frères tes serviteurs, enfants d’un même homme, au pays de Canaan, dont le plus petit est aujourd’hui avec notre père, et l’un n’est plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Et Joseph leur dit: C’est ce que je vous disais, que vous êtes des espions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Vous serez éprouvés par ce moyen: Vive Pharaon, si vous sortez d’ici, que votre jeune frère ne soit venu ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Envoyez-en un d’entre vous qui amène votre frère; mais vous serez prisonniers, et j’éprouverai si vous avez dit la vérité; autrement, vive Pharaon, vous êtes des espions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Et il les fit mettre tous ensemble en prison pour trois jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Et au troisième jour Joseph leur dit: Faites ceci, et vous vivrez; je crains Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Si vous êtes gens de bien, que l’un de vous qui êtes frères, soit lié dans la prison où vous avez été renfermés, et allez-vous-en, et emportez du blé pour pourvoir à la disette de vos familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Puis amenez-moi votre jeune frère et vos paroles se trouveront véritables; et vous ne mourrez point; et ils firent ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Et ils se disaient l’un à l’autre: Vraiment nous sommes coupables à l’égard de notre frère; car nous avons vu l’angoisse de son âme quand il nous demandait grâce, et nous ne l’avons point exaucé; c’est pour cela que cette angoisse nous est arrivée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Et Ruben leur répondit, en disant: Ne vous disais-je pas bien, ne commettez point ce péché contre l’enfant? Et vous ne m’écoutâtes point; c’est pourquoi, voici, son sang vous est redemandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Et ils ne savaient pas que Joseph les entendît; parce qu’il leur parlait par un truchement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Et il se détourna d’auprès d’eux pour pleurer. Puis étant retourné vers eux, il leur parla encore, et fit prendre d’entr’eux Siméon, et le fit lier devant leurs yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Et Joseph commanda qu’on remplît leurs sacs de blé, et qu’on remît l’argent dans le sac de chacun d’eux, et qu’on leur donnât de la provision pour leur chemin; et cela fut fait ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Ils chargèrent donc leur blé sur leurs ânes, et s’en allèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Et l’un d’eux ouvrit son sac pour donner à manger à son âne dans l’hôtellerie; et il vit son argent, et voilà il était à l’ouverture de son sac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Et il dit à ses frères: Mon argent m’a été rendu; et en effet, le voici dans mon sac. Et le coeur leur tressaillit, et ils furent saisis de peur, et se dirent l’un à l’autre: Qu’est-ce que Dieu nous a fait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Et étant arrivés au pays de Canaan, vers Jacob leur père, ils lui racontèrent toutes les choses qui leur étaient arrivées, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'L’homme qui commande dans le pays, nous a parlé rudement, et nous a pris pour des espions du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Mais nous lui ayons répondu: Nous sommes gens de bien, nous ne sommes point des espions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Nous étions douze frères, enfants de notre père; l’un n’est plus, et le plus jeune est aujourd’hui avec notre père au pays de Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Et cet homme, qui commande dans le pays, nous a dit: Je connaîtrai à ceci que vous êtes gens de bien; laissez-moi l’un de vos frères, et prenez du blé pour vos familles contre la famine, et vous en allez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Puis amenez-moi votre jeune frère, et je connaîtrai que vous n’êtes point des espions, mais des gens de bien; je vous rendrai votre frère, et vous trafiquerez au pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Et il arriva que comme ils vidaient leurs sacs, voici, le paquet de l’argent de chacun était dans son sac; et ils virent eux et leur père, les paquets de leur argent, et ils furent tout effrayés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Alors Jacob leur père leur dit: Vous m’ayez privé d’enfants: Joseph n’est plus, et Siméon n’est plus, et vous prendriez Benjamin! Toutes ces choses sont entre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Et Ruben parla à son père, et lui dit: Fais mourir deux de mes fils, si je ne te le ramène; donne-le moi en charge; et je te le ramènerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Et il répondit: Mon fils ne descendra point avec vous, car son frère est mort, et celui-ci est resté seul, et quelque accident mortel lui arriverait dans le chemin par où vous irez, et vous feriez descendre mes cheveux blancs avec douleur au sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Or la famine devint fort grande en la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Et il arriva que comme ils eurent achevé de manger les vivres qu’ils avaient apportés d’Egypte, leur père leur dit: Retournez-vous-en, et achetez-nous un peu de vivres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Et Juda lui répondit, et lui dit: Cet homme-là nous a expressément protesté, disant: Vous ne verrez point ma face que votre frère ne soit avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Si donc tu envoies notre frère avec nous, nous descendrons en Egypte, et t’achèterons des vivres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Mais si tu ne l’envoies, nous n’y descendrons point; car cet homme-là nous a dit: Vous ne verrez point ma face, que votre frère ne soit avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Et Israël dit: Pourquoi m’avez-vous fait ce tort de déclarer à cet homme que vous aviez encore un frère?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Et ils répon dirent: Cet homme s’est soigneusement enquis de nous, et de notre parenté, et nous a dit: Votre père vit-il encore? N’avez-vous point de frère? Et nous lui avons déclaré, selon ce qu’il nous avait demandé; pouvions-nous savoir qu’il dirait: Faites descendre votre frère?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Et Juda dit à Israël son père: Envoie l’enfant avec moi, et nous nous mettrons en chemin, et nous en irons, et nous vivrons, et ne mourrons point, ni nous, ni toi aussi, ni nos petits enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'J’en réponds, redemande-le de ma main; si je ne te le ramène; et si je ne te le représente, je serai toute ma vie sujet à la peine envers toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Que si nous n’eussions pas tant différé, certainement nous serions déjà de retour une seconde fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Alors Israël leur père leur dit: Si cela est ainsi, faites ceci, prenez dans vos vaisseaux des choses les plus renommées du pays, et portez à cet homme un présent, quelque peu de baume, et quelque peu de miel, des drogues, de la myrrhe, des dattes, et des amandes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Et prenez de l’argent au double en vos mains, et rapportez celui qui a été remis à l’ouverture de vos sacs; peut-être cela s’est fait par ignorance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Et prenez votre frère, et vous mettez en chemin, et retournez vers cet homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Or le Dieu Fort, Tout-Puissant vous fasse trouver grâce devant cet homme, afin qu’il vous relâche votre autre frère, et Benjamin; et s’il faut que je sois privé de ces deux fils, que j’en sois privé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Alors ils prirent le présent, et ayant pris de l’argent au double en leurs mains, et Benjamin, ils se mirent en chemin, et descendirent en Egypte; puis ils se présentèrent devant Joseph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Alors Joseph vit Benjamin avec eux, et dit à son maître d’hôtel: Mène ces hommes dans la maison, et tue quelque bête, et l’apprête; car ils mangeront à midi avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Et l’homme fit comme Joseph lui avait dit; et amena ces hommes dans la maison de Joseph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Et ces hommes eurent peur de ce qu’on les menait dans la maison de Joseph, et ils dirent: Nous sommes amenés à cause de l’argent qui fut remis la première fois dans nos sacs, c’est afin qu il se tourne et se jette sur nous, et nous prenne pour esclaves, et qu’il prenne nos ânes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Puis ils s’approchèrent du maître d’hôtel de Joseph, et lui parlèrent à la porte de la maison,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'En disant: Hélas, mon Seigneur! Certes nous descendîmes au commencement pour acheter des vivres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Et lorsque nous fûmes arrivés à l’hôtellerie, et que nous eûmes ouvert nos sacs, voici, l’argent de chacun était à l’ouverture de son sac, notre même argent selon son poids; mais nous l’avons rapporté en nos mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Et nous avons apporté d’autre argent en nos mains pour acheter des vivres; et nous ne savons point qui a remis notre argent dans nos sacs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Et il leur dit: Tout va bien pour vous, ne craignez point; votre Dieu et le Dieu de votre père vous a donné un trésor dans vos sacs, votre argent est parvenu jusqu’à moi; et il leur amena Siméon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Et cet homme les fit entrer dans la maison de Joseph, et leur donna de l’eau, et ils lavèrent leurs pieds; il donna aussi à manger à leurs ânes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Et ils préparèrent le présent en attendant que Joseph revînt à midi; car ils avaient appris qu’ils mangeraient là du pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Et Joseph revint à la maison, et ils lui présentèrent dans la maison le présent qu’ils avaient en leurs mains, et se prosternèrent devant lui jusqu’en terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Et il leur demanda comment ils se portaient, et leur dit: Votre père, ce bon vieillard dont vous m’avez parlé, se porte-t-il bien? vit-il encore?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Et ils répondirent: Ton serviteur notre père se porte bien, il vit encore; et se baissant profondément ils se prosternèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Et lui élevant ses yeux vit Benjamin son frère, fils de sa mère, et il dit: Est-ce là votre jeune frère dont vous m’avez parlé? Et puis il dit: Mon fils, Dieu te fasse grâce!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Et Joseph se retira promptement, car ses entrailles étaient émues à la vue de son frère, et il cherchait un lieu où il pût pleurer, et entrant dans son cabinet, il pleura là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Puis s’étant lavé le visage, il sortit de là, et se faisant violence, il dit: Mettez le pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Et on servit Joseph à part, et eux à part, et les Egyptiens qui mangeaient avec lui, aussi à part, parce que les Egyptiens ne pouvaient manger du pain avec les Hébreux; car c’est une abomination aux Egyptiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Ils s’assirent donc en sa présence; l’aîné selon son droit d’aînesse, et le plus jeune selon son âge; et ces hommes faisaient paraître l’un à l’autre leur étonnement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Et il leur fit porter des mets de devant soi; mais la portion de Benjamin était cinq fois plus grande que toutes les autres, et ils burent, et firent bonne chère avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Et Joseph commanda à son maître d’hôtel, en disant: Remplis de vivres les sacs de ces gens, autant qu’ils en pourront porter, et remets l’argent de chacun à l’ouverture de son sac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Et mets ma coupe, la coupe d’argent à l’ouverture du sac du plus petit avec l’argent de son blé; et il fit comme Joseph lui avait dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Le matin dès qu’il fut jour, on renvoya ces hommes avec leurs ânes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Et lorsqu’ils furent sortis de la ville, avant qu’ils fussent fort loin, Joseph dit à son maître d’hôtel: Va, poursuis ces hommes, et quand tu les auras atteints, dis-leur: Pourquoi avez-vous rendu le mal pour le bien?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'N’est-ce pas la coupe dans laquelle mon Seigneur boit, et par laquelle très- assurément il devinera? C’est mal fait à vous d’avoir fait cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Et il les atteignit, et leur dit ces mêmes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Et ils lui répondirent: Pourquoi mon Seigneur parle-t-il ainsi? A Dieu ne plaise que tes serviteurs aient fait une telle chose!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Voici, nous t’avons rapporté du pays de Canaan l’argent que nous avions trouvé à l’ouverture de nos sacs, et comment déroberions-nous de l’argent ou de l’or de la maison de ton maître?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Que celui de tes serviteurs à qui on trouvera la coupe, meure; et nous serons aussi esclaves de mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Et il leur dit: Qu’il soit fait maintenant selon vos paroles; qu’il soit ainsi; que celui à qui on trouvera la coupe me soit esclave, et vous serez innocents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Et incontinent chacun posa son sac en terre; et chacun ouvrit son sac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Et il fouilla, en commençant depuis le plus grand, et finissant au plus petit; et la coupe fut trouvée dans le sac de Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Alors ils déchirèrent leurs vêtements, et chacun rechargea son âne, et ils retournèrent à la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Et Juda vint avec ses frères en la maison de Joseph, qui était encore là, et ils se jetèrent devant lui en terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Et Joseph leur dit: Quelle action avez-vous faite? Ne savez-vous pas qu’un homme tel que moi ne manque pas de deviner?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Et Juda lui dit: Que dirons-nous à mon Seigneur? Comment parlerons-nous? et comment nous justifierons-nous? Dieu a trouvé l’iniquité de tes serviteurs; voici, nous sommes esclaves de mon Seigneur, tant nous, que celui dans la main auquel la coupe a été trouvée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Mais il dit: A Dieu ne plaise que je fasse cela! l’homme en la main duquel la coupe a été trouvée, me sera esclave; mais vous, remontez en paix vers votre père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Alors Juda s’approcha de lui, en disant: Hélas mon Seigneur! je te prie, que ton serviteur dise un mot, et que mon Seigneur l’écoute, et que ta colère ne s’enflamme point contre ton serviteur; car tu es comme Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mon Seigneur interrogea ses serviteurs, en disant: Avez-vous père, ou frère?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Et nous répondîmes à mon Seigneur: Nous avons notre père qui est âgé, et un enfant qui lui est né en sa vieillesse, et qui est le plus petit d’entre nous; son frère est mort, et celui-ci est resté seul de sa mère; et son père l’aime.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Or tu as dit à tes serviteurs: Faites-le descendre vers moi, et je le verrai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Et nous dîmes à mon Seigneur: Cet enfant ne peut laisser son père; car s’il le laisse, son père mourra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Alors tu dis à tes serviteurs: Si votre petit frère ne descend avec vous, vous ne verrez plus ma face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Or il est arrivé qu’étant de retour vers ton serviteur mon père, nous lui rapportâmes les paroles de mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Depuis, notre père nous dit: Retournez, et nous achetez un peu de vivres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Et nous lui dîmes: Nous ne pouvons y descendre; mais si notre petit frère est avec nous, nous y descendrons, car nous ne saurions voir la face de cet homme, si notre jeune frère n’est avec nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Et ton serviteur mon père nous répondit: Vous savez que ma femme m’a enfanté deux fils,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Dont l’un s’en est allé d’avec moi, et j’ai dit: Certainement il a été déchiré; et je ne l’ai point vu depuis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Et si vous emmenez aussi celui-ci et que quelque accident mortel lui arrive, vous ferez descendre mes cheveux blancs avec douleur au sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Maintenant donc quand je serai venu vers ton serviteur mon père, si l’enfant, dont l’âme est liée étroitement avec la sienne, n’est point avec nous,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'Il arrivera qu’aussitôt qu’il aura vu que l’enfant ne sera point avec nous, il mourra; ainsi tes serviteurs feront descendre avec douleur les cheveux blancs de ton serviteur notre père au sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'De plus, ton serviteur a répondu de l’enfant pour l’emmener d’auprès de mon père, en disant: Si je ne te le ramène, je serai toute ma vie sujet à la peine envers mon père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Ainsi maintenant, je te prie, que ton serviteur soit esclave de mon Seigneur au lieu de l’enfant, et qu’il remonte avec ses frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Car comment remonterai-je vers mon père, si l’enfant n’est avec moi? Que je ne voie point l’affliction qu’en aurait mon père!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Alors Joseph ne put plus se retenir devant tous ceux qui étaient là présents, et il cria: Faites sortir tout le monde; et personne ne demeura avec lui quand il se fit connaître à ses frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Et en pleurant il éleva sa voix, et les Egyptiens l’entendirent, et la maison de Pharaon l’entendit aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Or Joseph dit à ses frères: Je suis Joseph; mon père vit-il encore? Mais ses frères ne lui pouvaient répondre, car ils étaient tout troublés de sa présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Joseph dit encore à ses frères: Je vous prie, approchez-vous de moi; et ils s’approchèrent, et il leur dit: Je suis Joseph votre frère, que vous avez vendu pour être mené en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Mais maintenant ne soyez pas en peine, et n’ayez point de regret de ce que vous m’avez vendu pour être mené ici, car Dieu m’a envoyé devant vous pour la conservation de votre vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Car voici il y a déjà deux ans que la famine est en la terre, et il y aura encore cinq ans, pendant lesquels il n’y aura ni labourage, ni moisson.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Mais Dieu m’a envoyé devant vous, pour vous faire subsister sur la terre, et vous faire vivre par une grande délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Maintenant donc ce n’est pas vous qui m’avez envoyé ici, mais c’est Dieu, lequel m’a établi pour père à Pharaon, et pour Seigneur sur toute sa maison, et pour commander dans tout le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Hâtez-vous d’aller vers mon père, et dites-lui: Ainsi a dit ton fils Joseph: Dieu m’a établi Seigneur sur toute l’Egypte, descends vers moi, ne t’arrête point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Et tu habiteras dans la contrée de Goscen, et tu seras près de moi, toi et tes enfants, et les enfants de tes enfants, et tes troupeaux, et tes boeufs, et tout ce qui est à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Et je t’entretiendrai là, car il y a encore cinq années de famine, de peur que tu ne périsses par la misère, toi et ta maison, et tout ce qui est à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Et voici, vous voyez de vos yeux, et Benjamin mon frère voit aussi de ses yeux, que c’est moi qui vous parle de ma propre bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Rapportez donc à mon père quelle est ma gloire en Egypte, et tout ce que vous avez vu; et hâtez-vous, et faites descendre ici mon père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Alors il se jeta sur le cou de Benjamin son frère, et pleura. Benjamin pleura aussi sur son cou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Puis il baisa tous ses frères, et pleura sur eux; après cela ses frères parlèrent avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Et on en entendit le bruit dans la maison de Pharaon, disant: Les frères de Joseph sont venus; ce qui plut fort à Pharaon et à ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Alors Pharaon dit à Joseph: Dis à tes frères: Faites ceci, chargez vos bêtes, et partez pour vous en retourner au pays de Canaan;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Et prenez votre père et vos familles, et revenez vers moi, et je vous donnerai du meilleur du pays d’Egypte; et vous mangerez la graisse de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Or tu as la puissance de commander: Faites ceci, prenez avec vous du pays d’Egypte des chariots pour vos petits enfants et pour vos femmes; et amenez votre père, et venez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Ne regrettez point vos meubles; car le meilleur de tout le pays d’Egypte sera à vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Et les enfants d’Israël le firent ainsi. Et Joseph leur donna des chariots selon l’ordre de Pharaon; il leur donna aussi de la provision pour le chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Il leur donna à chacun des robes de rechange; et il donna à Benjamin trois cents pièces d’argent, et cinq robes de rechange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Il envoya aussi à son père dix ânes chargés des plus excellentes choses qu’il y eût en Egypte, et dix ânesses portant du blé, du pain, et des vivres à son père pour le chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Il renvoya donc ses frères, et ils partirent; et il leur dit: Ne vous querellez point en chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Ainsi ils remontèrent d’Egypte, et vinrent à Jacob leur père au pays de Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Et ils lui rapportèrent et lui dirent: Joseph vit encore, et même il commande sur tout le pays d’Egypte; et le coeur lui défaillit, quoiqu’il ne les crût pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Et ils lui dirent toutes les paroles que Joseph leur avait dites; puis il vit les chariots que Joseph avait envoyés pour le porter; et l’esprit revint à Jacob leur père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Alors Israël dit: C’est assez, Joseph mon fils vit encore, j’irai, et je le verrai avant que je meure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Israël donc partit avec tout ce qui lui appartenait, et vint à Béer-Sébah, et il offrit des sacrifices au Dieu de son père Isaac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Et Dieu parla à Israël dans les visions de la nuit, en disant: Jacob, Jacob! Et il répondit: Me voici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Et Dieu lui dit: Je suis le Dieu Fort, le Dieu de ton père; ne crains point de descendre en Egypte: car je t’y ferai devenir une grande nation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Je descendrai avec toi en Egypte, et je t’en ferai aussi très-certainement remonter; et Joseph mettra sa main sur tes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Ainsi Jacob partit de Béer-Sébah, et les enfants d’Israël mirent Jacob leur père, et leurs petits enfants, et leurs femmes, sur les chariots que Pharaon avait envoyés pour le porter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Ils emmenèrent aussi leur bétail et leur bien qu’ils avaient acquis dans le pays de Canaan; et Jacob et toute sa famille avec lui vinrent en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Il amena donc avec lui en Egypte ses enfants, et les enfants de ses enfants, ses filles, et les filles de ses fils, et toute sa famille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Or ce sont ici les noms des enfants d’Israël, qui vinrent en Egypte: Jacob et ses enfants. Le premier-né de Jacob, fut Ruben.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Et les enfants de Ruben, Hénoc, Pallu, Hetsron, et Carmi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Et les enfants de Siméon, Jémuel, Jamin, Ohab, Jakin, Tsohar, et Saül, fils d’une Cananéenne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Et les enfants de Lévi, Guerson, Kéhath, et Mérari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Et les enfants de Juda, Her, Onan, Séla, Pharez, et Zara; mais Her et Onan moururent au pays de Canaan. Les enfants de Pharez furent Hetsron et Hamul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Et les enfants d’Issacar, Tolah, Puva, Job, et Simron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Et les enfants de Zabulon, Séred, Elon, et Jahléel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Ce sont là les enfants de Léa, qu’elle enfanta à Jacob en Paddan-Aram, avec Dina sa fille; toutes les personnes de ses fils et de ses filles furent trente-trois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Et les enfants de Gad, Tsiphjon, Haggi, Suni, Etsbon, Héri, Arodi, et Aréli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Et les enfants d’Aser, Jimna, Jisua, Jisui, Bériha, et Sérah, leur soeur. Les enfants de Bériha, Héber et Malkiel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Ce sont là les enfants de Zilpa que Laban donna à Léa sa fille; et elle les enfanta à Jacob, savoir, seize personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Les enfants de Rachel femme de Jacob, furent Joseph et Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Et il naquit à Joseph au pays d’Egypte, Manassé et Ephraïm, qu’Asenath fille de Potiphérah, Gouverneur d’On, lui enfanta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Et les enfants de Benjamin étaient Bélah, Béker, Asbel, Guéra, Nahaman, Ehi, Ros, Muppim, et Huppim, et Ard.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Ce sont là les enfants de Rachel, qu’elle enfanta à Jacob; en tout quatorze personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Et les enfants de Dan, Husim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Et les enfants de Nephthali, Jahtséel, Guni, Jetser, et Sillem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Ce sont là les enfants de Bilha, laquelle Laban donna à Rachel sa fille, et elle les enfanta à Jacob; en tout, sept personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Toutes les personnes appartenant à Jacob qui vinrent en Egypte, et qui étaient sorties de sa hanche, sans les femmes des enfants de Jacob, furent en tout soixante-six.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Et les enfants de Joseph qui lui étaient nés en Egypte, furent deux personnes. Toutes les personnes donc de la maison de Jacob qui vinrent en Egypte, furent soixante-dix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Or Jacob envoya Juda devant lui vers Joseph, pour l’avertir de venir au- devant de lui en Goscen. Ils vinrent donc dans la contrée de Goscen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Et Joseph fit atteler son chariot, et monta pour aller au-devant d’Israël son père en Goscen. Il se fit voir à lui; il se jeta sur son cou, et pleura quelque temps sur son cou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Et Israël dit à Joseph: Que je meure à présent, puisque j’ai vu ton visage, et que tu vis encore.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Puis Joseph dit à ses frères et à la famille de son père: Je remonterai, et ferai savoir à Pharaon, et je lui dirai: Mes frères et la famille de mon père, qui étaient au pays de Canaan, sont venus vers moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Et ces hommes sont bergers, et se sont toujours mêlés de bétail, et ils ont amené leurs brebis et leurs boeufs, et tout ce qui était à eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Or il arrivera que Pharaon vous fera appeler, et vous dira: Quel est votre métier?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Et vous direz: Tes serviteurs se sont toujours mêlés de bétail dès leur jeunesse jusqu’à maintenant, tant nous, que nos pères; afin que vous demeuriez en la contrée de Goscen; car les Egyptiens ont en abomination les bergers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Joseph donc vint et fit entendre à Pharaon, en disant: Mon père, et mes frères, avec leurs troupeaux et leurs boeufs, et tout ce qui est à eux, sont venus du pays de Canaan, et voici, ils sont en la contrée de Goscen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Et il prit une partie de ses frères; savoir cinq; et il les présenta à Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Et Pharaon dit aux frères de Joseph: Quel est votre métier? Ils répondirent à Pharaon: Tes serviteurs sont bergers, comme l’ont été nos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Ils dirent aussi à Pharaon: Nous sommes venus demeurer comme étrangers en ce pays, parce qu’il n’ y a point de pâture pour les troupeaux de tes serviteurs, et qu’il y a une grande famine au pays de Canaan; maintenant donc nous te prions que tes serviteurs demeurent en la contrée de Goscen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Et Pharaon parla à Joseph, en disant: Ton père et tes frères sont venus vers toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Le pays d’Egypte est à ta disposition; fais habiter ton père et tes frères dans le meilleur endroit du pays; qu’ils demeurent dans la terre de Goscen; et si tu connais qu’il y ait parmi eux des hommes habiles tu les établiras gouverneurs sur tous mes troupeaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Alors Joseph amena Jacob son père, et le présenta à Pharaon; et Jacob bénit Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Et Pharaon dit à Jacob: Quel âge as-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jacob répondit à Pharaon: Les jours des années de mes pèlerinages sont cent trente ans; les jours des années de ma vie ont été courts et mauvais, et n’ont point atteint les jours des années de la vie de mes pères, du temps de leurs pèlerinages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Jacob donc bénit Pharaon, et sortit de devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Et Joseph assigna une demeure à son père et à ses frères, et leur donna une possession au pays d’Egypte, au meilleur endroit du pays, en la contrée de Rahmesès, comme Pharaon l’avait ordonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Et Joseph entretint de pain son père, et ses frères, et toute la maison de son père, selon le nombre de leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Or il n’y avait point de pain en toute la terre, car la famine était très- grande; et le pays d’Egypte, et le pays de Canaan, ne savaient que faire à cause de la famine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Et Joseph amassa tout l’argent qui se trouva au pays d’Egypte, et au pays de Canaan, pour le blé qu’on achetait; et il porta l’argent à la maison de Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Et l’argent du pays d’Egypte, et du pays de Canaan manqua; et tous les Egyptiens vinrent à Joseph, en disant: Donne-nous du pain; et pourquoi mourrions-nous devant tes yeux, parce que l’argent a manqué?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Joseph répondit: Donnez votre bétail, et je vous en donnerai pour votre bétail, puisque l’argent a manqué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Alors ils amenèrent à Joseph leur bétail, et Joseph leur donna du pain pour des chevaux, pour des troupeaux de brebis, pour des troupeaux de boeufs, et pour des ânes; ainsi il les sustenta de pain cette année-là, pour tous leurs troupeaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Cette année étant finie, ils revinrent à lui l’année suivante, et lui dirent: Nous ne cacherons point à mon Seigneur, que l’argent étant fini, et les troupeaux de bêtes ayant été amenés à mon Seigneur, il ne nous reste plus rien devant mon Seigneur que nos corps, et nos terres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Pourquoi mourrions-nous devant tes yeux? Achète-nous et nos terres, nous et nos terres, pour du pain; et nous serons esclaves de Pharaon, et nos terres seront à lui; donne-nous aussi de quoi semer, afin que nous vivions, et ne mourions point, et que la terre ne soit point désolée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Ainsi Joseph acquit à Pharaon toutes les terres d’Egypte; car les Egyptiens vendirent chacun son champ, parce que la famine s’était augmentée, et la terre fut à Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Et il fit passer le peuple dans les villes, depuis un bout des confins de l’Egypte, jusques à son autre bout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Seulement il n’acquit point les terres des Sacrificateurs; parce qu’il y avait une portion assignée pour les Sacrificateurs, par l’ordre de Pharaon; et ils mangeaient la portion que Pharaon leur avait donnée, c’est pourquoi ils ne vendirent point leurs terres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Et Joseph dit au peuple: Voici, je vous ai acquis aujourd’hui, vous et vos terres à Pharaon, voilà de la semence pour semer la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Et quand le temps de la récolte viendra, vous en donnerez la cinquième partie à Pharaon, et les quatre autres seront à vous, pour semer les champs, et pour votre nourriture, et pour celle de ceux qui sont dans vos maisons, et pour la nourriture de vos petits enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Et ils dirent: Tu nous as sauvé la vie; que nous trouvions grâce devant les yeux de mon Seigneur, et nous serons esclaves de Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Et Joseph en fit une Loi qui dure jusques à ce jour, à l’égard des terres de l’Egypte, de payer à Pharaon un cinquième du revenu; les terres seules des Sacrificateurs ne furent point à Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Or Israël habita au pays d’Egypte, en la contrée de Goscen; et ils en jouirent, et s’accrurent, et multiplièrent extrêmement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Et Jacob vécut au pays d’Egypte dix-sept ans; et les années de la vie de Jacob furent cent quarante-sept ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Or le temps de la mort d’Israël approchant, il appela Joseph son fils, et lui dit: Je te prie, si j’ai trouvé grâce devant tes yeux, mets présentement ta main sous ma cuisse, et jure-moi que tu useras envers moi de gratuité et de vérité; je te prie, ne m’enterre point en Egypte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Mais que je dorme avec mes pères. Tu me transporteras donc d’Egypte, et m’enterreras dans leur sépulcre. Et il répondit: Je le ferai selon ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Et Jacob lui dit: Jure-le-moi; et il le lui jura. Et Israël se prosterna sur le chevet du lit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Or il arriva après ces choses que l’on vint dire à Joseph: Voici, ton père est malade; et il prit avec lui ses deux fils, Manassé et Ephraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Et on fit savoir à Jacob, et on lui dit: Voici Joseph ton fils qui vient vers toi. Alors Israël s’efforça, et se mit en son séant sur le lit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Puis Jacob dit à Joseph: Le Dieu Fort, Tout-Puissant s’est apparu à moi à Lus au pays de Canaan, et m’a béni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'Et il m’a dit: Voici, je te ferai croître, et multiplier, et je te ferai devenir une assemblée de peuples, et je donnerai ce pays à ta postérité après toi en possession perpétuelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Or maintenant tes deux fils, qui te sont nés au pays d’Egypte, avant que j’y vinsse vers toi, sont miens: Ephraïm et Manassé seront miens comme Ruben et Siméon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Mais les enfants que tu auras après eux, seront à toi, et ils seront appelés selon le nom de leurs frères en leur héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Or, quand je venais de Paddan, Rachel me mourut au pays de Canaan en chemin, n’y ayant plus que quelque petit espace de pays pour arriver à Ephrat; et je l’enterrai là, sur le chemin d’Ephrat, qui est Bethléhem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Puis Israël vit les fils de Joseph, et il dit: Qui sont ceux-ci?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Et Joseph répondit à son père: Ce sont mes fils que Dieu m’a donnés ici; et il dit: Amène-les-moi, je te prie, afin que je les bénisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Or les yeux d’Israël étaient appesantis de vieillesse, et il ne pouvait voir; et il les fit approcher de soi, et les baisa, et les embrassa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Et Israël dit à Joseph: Je ne croyais pas voir jamais ton visage; et voici, Dieu m’a fait voir et toi et tes enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Et Joseph les retira d’entre les genoux de son père, et se prosterna le visage contre terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Joseph donc les prit tous deux, et mit Ephraïm à sa droite, à la gauche d’Israël, et Manassé à sa gauche, à la droite d’Israël; et les fît approcher de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Et Israël avança sa main droite, et la mit sur la tête d’Ephraïm, qui était le puîné; et sa main gauche sur la tête de Manassé, transposant ainsi ses mains de propos délibéré, car Manassé était l’aîné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Et il bénit Joseph, en disant: Que le Dieu, devant la face duquel mes pères Abraham et Isaac ont vécu, le Dieu qui me paît depuis que je suis au monde jusqu’à ce jour;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'Que l’Ange qui m’a garanti de tout mal, bénisse ces enfants; et que mon nom et le nom de mes pères Abraham et Isaac soit réclamé sur eux; et qu’ils croissent en nombre comme les poissons, en multipliant sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Et Joseph voyant que son père mettait sa main droite sur la tête d’Ephraïm, en eut du déplaisir, et il souleva la main de son père, pour la détourner de dessus la tête d’Ephraïm sur la tête de Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Et Joseph dit à son père: Ce n’est pas ainsi, mon père! car celui-ci est l’aîné; mets ta main droite sur sa tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Mais son père le refusa en disant: Je le sais, mon fils, je le sais. Celui- ci deviendra aussi un peuple, et même il sera grand; mais toutefois son frère, qui est plus jeune, sera plus grand que lui, et sa postérité sera une multitude de nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Et en ce jour-là il les bénit, et dit: Israël bénira prenant exemple en toi, et disant: Dieu te fasse tel qu’Ephraïm et Manassé; et il mit Ephraïm devant Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Puis Israël dit à Joseph: Voici, je m’en vais mourir, mais Dieu sera avec vous, et vous fera retourner au pays de vos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Et je te donne une portion plus qu’à tes frères, laquelle j’ai prise avec mon épée et mon arc sur les Amorrhéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Puis Jacob appela ses fils, et leur dit: Assemblez-vous, et je vous déclarerai ce qui vous doit arriver aux derniers jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Assemblez-vous, et écoutez, fils de Jacob; écoutez, dis-je, Israël votre père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'RUBEN, qui es mon premier-né, ma force, et le commencement de ma vigueur; qui excelles en dignité, et qui excelles aussi en force;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Tu t’es précipité comme de l’eau; tu n’auras pas la prééminence, car tu es monté sur la couche de ton père, et tu as souillé mon lit en y montant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'SIMÉON et LÉVI, frères, ont été des instruments de violence dans leurs demeures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Que mon âme n’entre point en leur conseil secret; que ma gloire ne soit point jointe à leur compagnie, car ils ont tué les gens en leur colère, et ont enlevé les boeufs pour leur plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Maudite soit leur colère, car elle a été violente; et leur furie, car elle a été roide; je les diviserai en Jacob, et les disperserai en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'JUDA, quant à toi, tes frères te loueront: ta main sera sur le collet de tes ennemis; les fils de ton père se prosterneront devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Juda est un fan de lion: mon fils, tu es revenu de déchirer; il s’est courbé, et s’est couché comme un lion qui est en sa force, et comme un vieux lion; qui le réveillera?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Le sceptre ne se départira point de Juda, ni le Législateur d’entre ses pieds, jusqu’à ce que le Scilo vienne; et à lui appartient l’assemblée des peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Il attache à la vigne son ânon, et au cep excellent le petit de son ânesse; il lavera son vêtement dans le vin, et son manteau dans le sang des grappes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Il a les yeux vermeils de vin, et les dents blanches de lait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'ZABULON se logera au port des mers, et sera au port des navires; ses cotés s’étendront vers Sidon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'ISSACAR est un âne ossu, couché entre les barres des étables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Il a vu que le repos était bon, et que le pays était beau, et il a baissé son épaule pour porter et s’est assujetti au tribut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'DAN jugera son peuple, aussi bien qu’une autre des tribus d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan sera un serpent sur le chemin, et une couleuvre dans le sentier, mordant les paturons du cheval, et celui qui le monte tombe à la renverse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Ô Eternel! j’ai attendu ton salut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Quant à GAD, des troupes viendront le ravager, mais il ravagera à la fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Le pain excellent viendra d’ASER, et il fournira les délices royales.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'NEPHTHALI est une biche lâchée; il donne des paroles qui ont de la grâce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'JOSEPH est un rameau fertile, un rameau fertile près d’une fontaine; ses branches se sont étendues sur la muraille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'On l’a fâché amèrement; on a tiré contre lui, et les maîtres tireurs de flèches ont été ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Mais son arc est demeuré en sa force, et les bras de ses mains se sont renforcés par la main du Puissant de Jacob, qui l’a aussi fait être le Pasteur, et la Pierre d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Cela est procédé du Dieu Fort de ton père, lequel t’aidera; et du Tout- Puissant, qui te comblera des bénédictions des cieux en haut; des bénédictions de l’abîme d’embas; des bénédictions des mamelles et de la matrice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Les bénédictions de ton père ont surpassé les bénédictions de ceux qui m’ont engendré, jusqu’au bout des coteaux d’éternité; elles seront sur la tête de Joseph, et sur le sommet de la tête du Nazaréen d’entre ses frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'BENJAMIN est un loup qui déchirera; le matin il dévorera la proie, et sur le soir il partagera le butin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Ce sont là les douze tribus d’Israël, et c’ est ce que leur père leur dit en les bénissant; et il bénit chacun d’eux de la bénédiction qui lui était propre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Il leur fit aussi ce commandement, et leur dit: Je m’en vais être recueilli vers mon peuple, enterrez-moi avec mes pères dans la caverne qui est au champ d’Héphron Héthien:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'Dans la caverne, dis-je, qui est au champ de Macpéla, vis-à-vis de Mamré, au pays de Canaan, laquelle Abraham acquit d’Héphron Héthien, avec le champ pour le posséder comme le lieu de son sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'C’est là qu’on a enterré Abraham avec Sara sa femme; c’est là qu’on a enterré Isaac et Rébecca sa femme; et c’est là que j’ai enterré Léa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Le champ a été acquis des Héthiens avec la caverne qui y est.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Et quand Jacob eut achevé de donner ses commandements à ses fils, il retira ses pieds au lit, et expira, et fut recueilli vers ses peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Alors Joseph se jeta sur le visage de son père, et pleura sur lui, et le baisa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Et Joseph commanda à ceux de ses serviteurs qui étaient médecins, d’embaumer son père; et les médecins embaumèrent Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Et on employa quarante jours à l’embaumer: car c’était la coutume d’embaumer les corps pendant quarante jours; et les Egyptiens le pleurèrent soixante et dix jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Or le temps du deuil étant passé, Joseph parla à ceux de la maison de Pharaon, en disant: Je vous prie, si j’ai trouvé grâce envers vous, faites savoir ceci à Pharaon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Que mon père m’a fait jurer, et m’a dit: Voici, je m’en vais mourir; tu m’enterreras dans mon sépulcre, que je me suis creusé au pays de Canaan; maintenant donc, je te prie, que j’y monte, et que j’y enterre mon père: puis je retournerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Et Pharaon répondit: Monte, et enterre ton père, comme il t’a fait jurer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Alors Joseph monta pour enterrer son père, et les serviteurs de Pharaon, les Anciens de la maison de Pharaon, et tous les Anciens du pays d’Egypte montèrent avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'Et toute la maison de Joseph, et ses frères, et la maison de son père y montèrent aussi, laissant seulement leurs familles, et leurs troupeaux, et leurs boeufs dans la contrée de Goscen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Il monta aussi avec lui des chariots, et des gens de cheval; tellement qu’il y eut un fort gros camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Et lorsqu’ils furent venus à l’aire d’Atad, qui est au-delà du Jourdain, ils y firent de grandes et de douloureuses lamentations; et Joseph pleura son père pendant sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Et les Cananéens, habitants du pays, voyant ce deuil dans l’aire d’Atad, dirent: Ce deuil est grand pour les Egyptiens; c’est pourquoi cette aire, qui est au-delà du Jourdain, fut nommée Abel-Mitsraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Les fils donc de Jacob firent à l’égard de son corps ce qu’il leur avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Car ses fils le transportèrent au pays de Canaan, et l’ensevelirent dans la caverne du champ de Macpéla, vis-à-vis de Mamré, laquelle Abraham avait acquise d’Héphron Héthien avec le champ, pour le posséder comme le lieu de son sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Et après que Joseph eut enseveli son père il retourna en Egypte avec ses frères, et tous ceux qui étaient montés avec lui pour enterrer son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Et les frères de Joseph voyant que leur père était mort, dirent entr’eux: Peut-être que Joseph nous aura en haine, et ne manquera pas de nous rendre tout le mal que nous lui avons fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'C’est pourquoi ils envoyèrent dire à Joseph: Ton père avait commandé avant qu’il mourût, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Vous parlerez ainsi à Joseph: Je te prie, pardonne maintenant l’iniquité de tes frères, et leur péché; car ils t’ont fait du mal. Maintenant donc, je te supplie, pardonne cette iniquité aux serviteurs du Dieu de ton père. Et Joseph pleura quand on lui parla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Puis ses frères même y allèrent, et se prosternèrent devant lui, et lui dirent: Voici, nous sommes tes serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Et Joseph leur dit: Ne craignez point; car suis-je en la place de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Ce que vous aviez pensé en mal contre moi, Dieu l’a pensé en bien, pour faire selon ce que ce jour-ci le montre, afin de faire vivre un grand peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Ne craignez donc point maintenant; moi-même je vous entretiendrai, vous et vos familles; et il les consola, et leur parla selon leur coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Joseph donc demeura en Egypte, lui et la maison de son père, et vécut cent et dix ans,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Et Joseph vit des enfants d’Ephraim, jusqu’à la troisième génération. Makir aussi, fils de Manassé, eut des enfants qui furent élevés sur les genoux de Joseph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Et Joseph dit à ses frères: Je m’en vais mourir, et Dieu ne manquera pas de vous visiter, et il vous fera remonter de ce pays au pays dont il a juré à Abraham, Isaac et à Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Et Joseph fit jurer les enfants d’Israël, et leur dit: Dieu ne manquera pas de vous visiter, et alors vous transporterez mes os d’ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Puis Joseph mourut, âgé de cent et dix ans; et on l’embauma, et on le mit dans un cercueil en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Or ce sont ici les noms des enfants d’Israël, qui entrèrent en Egypte, chacun desquels y entra avec Jacob, et leur famille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Siméon, Lévi, et Juda,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issachar, Zabulon, et Benjamin,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan, et Nephtali, Gad, et Aser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Toutes les personnes issues de la hanche de Jacob, étaient soixante et dix, avec Joseph qui était en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Or Joseph mourut, et tous ses frères, et toute cette génération-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Et les enfants d’Israël foisonnèrent, et crûrent en très-grande abondance, et multiplièrent, et devinrent très-puissants, tellement que le pays en fut rempli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Depuis il s’éleva un nouveau Roi sur l’Egypte, lequel n’avait point connu Joseph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Et il dit à son peuple: voici, le peuple des enfants d’Israël est plus grand et plus puissant que nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Agissons donc prudemment avec lui, de peur qu’il ne se multiplie, et que s’il arrivait quelque guerre il ne se joignît à nos ennemis, et ne fît la guerre contre nous, et qu’il ne s’en allât du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Ils établirent donc sur le peuple des Commissaires d’impôts pour l’affliger en le surchargeant; car le peuple bâtit des villes fortes à Pharaon, savoir Pithom et Rahamsès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Mais plus ils l’affligeaient, et plus il multipliait, et croissait en toute abondance: c’est pourquoi ils haïssaient les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Et les Egyptiens faisaient servir les enfants d’Israël avec rigueur:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Tellement qu’ils leur rendirent la vie amère par une rude servitude, en les employant à faire du mortier, des briques, et toute sorte d’ouvrage qui se fait aux champs; tout le service qu’on tirait d’eux était avec rigueur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Le Roi d’Egypte commanda aussi aux sages-femmes Hébreues, dont l’une avait nom Siphra, et l’autre avait nom Puha;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Et leur dit: quand vous recevrez les enfants des femmes des Hébreux, et que vous les verrez sur les siéges, si c’est un fils, mettez-le à mort; mais si c’est une fille, qu’elle vive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Mais les sages-femmes craignirent Dieu, et ne firent pas ainsi que le Roi d’Egypte leur avait dit; car elles laissèrent vivre les fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Alors le Roi d’Egypte appela les sages-femmes, et leur dit: pourquoi avez- vous fait cela, d’avoir laissé vivre les fils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Et les sages-femmes répondirent à Pharaon: parce que les Hébreues ne sont point comme les femmes Egyptiennes; car elles sont vigoureuses, et elles ont accouché avant que la sage-femme soit arrivée chez elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Et Dieu fit du bien aux sages-femmes, et le peuple multiplia, et devint très puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Et parce que les sages-femmes craignirent Dieu, il leur édifia des maisons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Alors Pharaon commanda à tout son peuple, disant: jetez dans le fleuve tous les fils qui naîtront, mais laissez vivre toutes les filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Or un homme de la maison de Lévi s’en alla, et prit une fille de Lévi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Laquelle conçut et enfanta un fils, et voyant qu’il était beau, elle le cacha pendant trois mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Mais ne le pouvant tenir caché plus longtemps, elle prit un coffret de joncs, et l’enduisit de bitume et de poix, et mit l’enfant dedans, et le posa parmi des roseaux sur le bord du fleuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Et la soeur de cet enfant se tenait loin pour savoir ce qu’il en arriverait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Or la fille de Pharaon descendit à la rivière, pour se baigner, et ses filles se promenaient sur le bord de la rivière, et ayant vu le coffret au milieu des roseaux, elle envoya une de ses servantes pour le prendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Et l’ayant ouvert, elle vit l’enfant, et voici, l’enfant pleurait; et elle en fut touchée de compassion, et dit: c’est un des enfants de ces Hébreux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Alors la soeur de l’enfant dit à la fille de Pharaon: irai-je appeler une femme d’entre les Hébreues, qui allaite, et elle t’allaitera cet enfant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Et la fille de Pharaon lui répondit: Va; et la jeune fille s’en alla, et appela la mère de l’enfant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Et la fille de Pharaon lui dit: emporte cet enfant, et me l’allaite, et je te donnerai ton salaire; et la femme prit l’enfant et l’allaita.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Et quand l’enfant fut devenu grand, elle l’amena à la fille de Pharaon; et il lui fut pour fils, et elle le nomma Moïse; parce que, dit-elle, je l’ai tiré des eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Or il arriva, en ce temps-là, que Moïse, étant devenu grand, sortit vers ses frères, et vit leurs travaux; il vit aussi un Egyptien qui frappait un Hébreu d’entre ses frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Et ayant regardé çà et là, et voyant qu’il n’y avait personne, il tua l’Egyptien, et le cacha dans le sable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Il sortit encore le second jour, et voici, deux hommes Hébreux se querellaient; et il dit à celui qui avait tort: pourquoi frappes-tu ton prochain?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Lequel répondit: qui t’a établi Prince et Juge sur nous? veux-tu me tuer, comme tu as tué l’Egyptien? et Moïse craignit, et dit: certainement le fait est connu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Or Pharaon ayant appris ce fait-là, chercha de faire mourir Moïse, mais Moïse s’enfuit de devant Pharaon, et s’arrêta au pays de Madian, et s’assit près d’un puits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Or le Sacrificateur de Madian avait sept filles, qui vinrent puiser de l’eau, et elles emplirent les auges pour abreuver le troupeau de leur père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Mais des bergers survinrent, qui les chassèrent; et Moïse se leva et les secourut, et abreuva leur troupeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Et quand elles furent revenues chez Réhuel leur père, il leur dit: comment êtes-vous revenues sitôt aujourd’hui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Elles répondirent: un homme Egyptien nous a délivrées de la main des bergers; et même il nous a puisé abondamment de l’eau, et a abreuvé le troupeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Et il dit à ses filles: où est-il? pourquoi avez-vous ainsi laissé cet homme? appelez-le, et qu’il mange du pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Et Moïse s’accorda de demeurer avec cet homme-là, qui donna Séphora sa fille à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Et elle enfanta un fils, et il le nomma Guersom; à cause, dit-il, que j’ai séjourné dans un pays étranger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Or il arriva longtemps après, que le Roi d’Egypte mourut, et les enfants d’Israël soupirèrent à cause de la servitude, et ils crièrent; et leur cri monta jusqu’à Dieu, à cause de la servitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Dieu donc ouït leurs sanglots, et Dieu se souvint de l’alliance qu’il avait traitée avec Abraham, Isaac et Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Ainsi Dieu regarda les enfants d’Israël, et il fit attention à leur état.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Or Moïse fut berger du troupeau de Jéthro son beau-père, Sacrificateur de Madian; et menant le troupeau derrière le désert, il vint en la montagne de Dieu jusqu’en Horeb.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Et l’Ange de l’Eternel lui apparut dans une flamme de feu, du milieu d’un buisson, et il regarda, et voici, le buisson était tout en feu, et le buisson ne se consumait point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Alors Moïse dit: je me détournerai maintenant, et je regarderai cette grande vision, pourquoi le buisson ne se consume point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Et l’Eternel vit que Moïse s’était détourné pour regarder; et Dieu l’appela du milieu du buisson, en disant: Moïse, Moïse! et il répondit: me voici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Et Dieu dit: n’approche point d’ici; déchausse tes souliers de tes pieds, car le lieu où tu es arrêté, est une terre sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Il dit aussi: je suis le Dieu de ton père, le Dieu d’Abraham, le Dieu d’Isaac, et le Dieu de Jacob; et Moïse cacha son visage, parce qu’il craignait de regarder vers Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Et l’Eternel dit: j’ai très-bien vu l’affliction de mon peuple qui est en Egypte, et j’ai ouï le cri qu’ils ont jeté à cause de leurs exacteurs, car j’ai connu leurs douleurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'C’est pourquoi je suis descendu pour le délivrer de la main des Egyptiens, et pour le faire remonter de ce pays-là, en un pays bon et spacieux, en un pays découlant de lait et de miel; au lieu où sont les Chananéens, les Héthiens, les Amorrhéens, les Phérésiens, les Héviens, et les Jébusiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Et maintenant voici, le cri des enfants d’Israël est parvenu à moi, et j’ai vu aussi l’oppression dont les Egyptiens les oppriment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Maintenant donc viens, et je t’enverrai vers Pharaon; et tu retireras mon peuple, les enfants d’Israël, hors d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Et Moïse répondit à Dieu: qui suis-je moi, pour aller vers Pharaon, et pour retirer d’Egypte les enfants d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Et Dieu lui dit: va car je serai avec toi; et tu auras ce signe que c’est moi qui t’ai envoyé, c’est que quand tu auras retiré mon peuple d’Egypte, vous servirez Dieu près de cette montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Et Moïse dit à Dieu: voici, quand je serai venu vers les enfants d’Israël, et que je leur aurai dit: le Dieu de vos pères m’a envoyé vers vous, s’ils me disent alors: quel est son nom? que leur dirai-je?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Et Dieu dit à Moïse: JE SUIS CELUI QUI SUIS. Il dit aussi: tu diras ainsi aux enfants d’Israël: celui qui s’appelle JE SUIS, m’a envoyé vers vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Dieu dit encore à Moïse: tu diras ainsi aux enfants d’Israël; l’ETERNEL, le Dieu de vos pères, le Dieu d’Abraham, le Dieu d’Isaac, et le Dieu de Jacob m’a envoyé vers vous: c’est ici mon nom éternellement, et c’est ici le mémorial que vous aurez de moi dans tous les âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Va, et assemble les anciens d’Israël, et leur dis: l’Eternel, le Dieu de vos pères, le Dieu d’Abraham, d’Isaac, et de Jacob, m’est apparu, en disant: certainement je vous ai visités, et j’ai vu ce qu’on vous fait en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Et j’ai dit: je vous ferai remonter de l’Egypte où vous êtes affligés, dans le pays des Chananéens, des Héthiens, des Amorrhéens, des Phérésiens, des Héviens, et des Jébusiens, qui est un pays découlant de lait et de miel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Et ils obéiront à ta parole, et tu iras, toi et les anciens d’Israël, vers le Roi d’Egypte, et vous lui direz: l’Eternel le Dieu des Hébreux nous est venu rencontrer; maintenant donc nous te prions que nous allions le chemin de trois jours au désert, et que nous sacrifiions à l’Eternel notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Or je sais que le Roi d’Egypte ne vous permettra point de vous en aller, qu’il n’y soit forcé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Mais j’étendrai ma main, et je frapperai l’Egypte par toutes les merveilles que je ferai au milieu d’elle; et après cela, il vous laissera aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Et je ferai que ce peuple trouvera grâce envers les Egyptiens, et il arrivera que quand vous partirez, vous ne vous en irez point à vide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Mais chacune demandera à sa voisine, et à l’hôtesse de sa maison, des vaisseaux d’argent, et des vaisseaux d’or, et des vêtements, que vous mettrez sur vos fils et sur vos filles: ainsi vous butinerez les Egyptiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Et Moïse répondit, et dit: mais voici, ils ne me croiront point, et n’obéiront point à ma parole; car ils diront: l’Eternel ne t’est point apparu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Et l’Eternel lui dit: Qu’est-ce que tu as en ta main? Il répondit: une verge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Et Dieu lui dit: jette-la par terre; et il la jeta par terre, et elle devint un serpent. Et Moïse s’enfuyait de devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Et l’Eternel dit à Moïse: étends ta main, et saisis sa queue; et il étendit sa main, et l’empoigna; et il redevint une verge en sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Et cela, afin qu’ils croient que l’Eternel, le Dieu de leurs pères, le Dieu d’Abraham, le Dieu d’Isaac, et le Dieu de Jacob, t’est apparu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'L’Eternel lui dit encore: mets maintenant ta main dans ton sein, et il mit sa main dans son sein; puis il la tira; et voici, sa main était blanche de lèpre comme la neige.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Et Dieu lui dit: remets ta main dans ton sein; et il remit sa main dans son sein; puis il la retira hors de son sein; et voici, elle était redevenue comme son autre chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Mais s’il arrive qu’ils ne te croient point, et qu’ils n’obéissent point à la voix du premier signe, ils croiront à la voix du second signe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Et s’il arrive qu’ils ne croient point à ces deux signes, et qu’ils n’obéissent point à ta parole, tu prendras de l’eau du fleuve, et tu la répandras sur la terre, et les eaux que tu auras prises du fleuve, deviendront du sang sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Et Moïse répondit à l’Eternel: hélas, Seigneur! Je ne suis point un homme qui ait ni d’hier, ni de devant hier, la parole aisée, même depuis que tu as parlé à ton serviteur; car j’ai la bouche et la langue empêchées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Et l’Eternel lui dit: qui est-ce qui a fait la bouche de l’homme? ou qui a fait le muet, ou le sourd, ou le voyant, ou l’aveugle? n’est-ce pas moi, l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Va donc maintenant, et je serai avec ta bouche, et je t’enseignerai ce que tu auras à dire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Et Moïse répondit: hélas! Seigneur, envoie, je te prie, celui que tu dois envoyer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Et la colère de l’Eternel s’embrasa contre Moïse, et il lui dit: Aaron le Lévite n’est-il pas ton frère? je sais qu’il parlera très-bien, et même le voilà qui sort à ta rencontre, et quand il te verra, il se réjouira dans son coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Tu lui parleras donc et tu mettras ces paroles en sa bouche; et je serai avec ta bouche et avec la sienne, et je vous enseignerai ce que vous aurez à faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Et il parlera pour toi au peuple, et ainsi il te sera pour bouche, et tu lui seras pour Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Tu prendras aussi en ta main cette verge, avec laquelle tu feras ces signes- là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Ainsi Moïse s’en alla, et retourna vers Jéthro son beau-père, et lui dit: je te prie, que je m’en aille, et que je retourne vers mes frères qui sont en Egypte, pour voir s’ils vivent encore. Et Jéthro lui dit: Va en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Or l’Eternel dit à Moïse au pays de Madian: Va, et retourne en Egypte; car tous ceux qui cherchaient ta vie sont morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Ainsi Moïse prit sa femme, et ses fils, et les mit sur un âne, et retourna au pays d’Egypte. Moïse prit aussi la verge de Dieu en sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Et L’Eternel avait dit à Moïse: quand tu t’en iras pour retourner en Egypte, tu prendras garde à tous les miracles que j’ai mis en ta main; et tu les feras devant Pharaon; mais j’endurcirai son coeur, et il ne laissera point aller le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Tu diras donc à Pharaon, ainsi a dit L’Eternel: Israël est mon fils, mon premier-né.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Et je t’ai dit: laisse aller mon fils, afin qu’il me serve; mais tu as refusé de le laisser aller. Voici, je m’en vais tuer ton fils, ton premier-né.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Or il arriva que comme Moïse était en chemin dans l’hôtellerie, l’Eternel le rencontra, et chercha de le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Et Séphora prit un couteau tranchant, et en coupa le prépuce de son fils, et le jeta à ses pieds, et dit: certes tu m’ es un époux de sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Alors l’Eternel se retira de lui; et elle dit: époux de sang; à cause de la circoncision.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Et l’Eternel dit à Aaron: va-t’en au devant de Moïse au désert. Il y alla donc, et le rencontra en la montagne de Dieu et le baisa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Et Moïse raconta à Aaron toutes les paroles de l’Eternel qui l’avait envoyé, et tous les signes qu’il lui avait commandés de faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Moïse donc poursuivit son chemin avec Aaron; et ils assemblèrent tous les anciens des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Et Aaron dit toutes les paroles que l’Eternel avait dit à Moïse; et fit les signes devant les yeux du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Et le peuple crut; et ils apprirent que l’Eternel avait visité les enfants d’Israël, et qu’il avait vu leur affliction; et ils s’inclinèrent, et se prosternèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Après cela Moïse et Aaron s’en allèrent et dirent à Pharaon: ainsi a dit l’Eternel, le Dieu d’Israël; laisse aller mon peuple, afin qu’il me célèbre une fête solennelle dans le désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Mais Pharaon dit: qui est l’Eternel, pour que j’obéisse à sa voix et que je laisse aller Israël? Je ne connais point l’Eternel, et je ne laisserai point aller Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Et ils dirent: le Dieu des Hébreux est venu au-devant de nous. Nous te prions que nous allions le chemin de trois jours au désert, et que nous sacrifiions à l’Eternel notre Dieu; de peur qu’il ne se jette sur nous par la mortalité, ou par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Et le Roi d’Egypte leur dit: Moïse et Aaron, pourquoi détournez-vous le peuple de son ouvrage? Allez maintenant à vos charges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Pharaon dit aussi: voici, le peuple de ce pays est maintenant en grand nombre, et vous les faites chômer de leur travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Et Pharaon commanda ce jour-là aux exacteurs établis sur le peuple, et à ses Commissaires, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Vous ne donnerez plus de paille à ce peuple pour faire des briques, comme auparavant; mais qu’ils aillent, et qu’ils s’amassent de la paille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Néanmoins vous leur imposerez la quantité des briques qu’ils faisaient auparavant, sans en rien diminuer; car ils sont gens de loisir, et c’est pour cela qu’ils crient, en disant: allons, et sacrifions à notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Que la servitude soit aggravée sur ces gens-là, et qu’ils s’occupent, et ne s’amusent plus à des paroles de mensonge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Alors les exacteurs du peuple, et ses Commissaires sortirent, et dirent au peuple: ainsi a dit Pharaon: je ne vous donnerai plus de paille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Allez vous-mêmes et prenez de la paille où vous en trouverez; mais il ne sera rien diminué de votre travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Alors le peuple se répandit par tout le pays d’Egypte, pour amasser du chaume au lieu de paille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Et les exacteurs les pressaient, en disant: achevez vos ouvrages, chaque jour sa tâche, comme quand la paille vous était fournie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Même les Commissaires des enfants d’Israël, que les exacteurs de Pharaon avaient établis sur eux, furent battus, et on leur dit: pourquoi n’avez-vous point achevé votre tâche en faisant des briques hier et aujourd’hui, comme auparavant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Alors les Commissaires des enfants d’Israël vinrent crier à Pharaon, en disant: pourquoi fais-tu ainsi à tes serviteurs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'On ne donne point de paille à tes serviteurs, et toutefois on nous dit: faites des briques; et voici, tes serviteurs sont battus, et ton peuple est traité comme coupable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Et il répondit: vous êtes de loisir, vous êtes de loisir; c’est pourquoi vous dites: allons, sacrifions à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Maintenant donc allez, travaillez; car on ne vous donnera point de paille, et vous rendrez la même quantité de briques.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Et les Commissaires des enfants d’Israël virent qu’ils étaient dans un mauvais état, puisqu’on disait: vous ne diminuerez rien de vos briques sur la tâche de chaque jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Et en sortant de devant Pharaon ils rencontrèrent Moïse et Aaron, qui se trouvèrent au-devant d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Et ils leur dirent: que l’Eternel vous regarde, et en juge, vu que vous nous avez mis en mauvaise odeur devant Pharaon et devant ses serviteurs, leur mettant l’épée à la main pour nous tuer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Alors Moïse retourna vers l’Eternel, et dit: Seigneur! pourquoi as-tu fait maltraiter ce peuple? pourquoi m’as-tu envoyé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Car depuis que je suis venu vers Pharaon pour parler en ton nom, il a maltraité ce peuple, et tu n’as point délivré ton peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Et l’Eternel dit à Moïse: tu verras maintenant ce que je ferai à Pharaon; car il les laissera aller, y étant contraint par main forte, étant, dis-je, contraint par main forte, il les chassera de son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Dieu parla encore à Moïse, et lui dit: je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Je suis apparu à Abraham, à Isaac, et à Jacob, comme le Dieu Fort, Tout- puissant, mais je n’ai point été connu d’eux par mon nom d’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'J’ai fait aussi cette alliance avec eux, que je leur donnerai le pays de Chanaan, le pays de leurs pèlerinages, dans lequel ils ont demeuré comme étrangers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Et j’ai entendu les sanglots des enfants d’Israël, que les Egyptiens tiennent esclaves, et je me suis souvenu de mon alliance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'C’est pourquoi dis aux enfants d’Israël: je suis l’Eternel, et je vous retirerai de dessous les charges des Egyptiens, et je vous délivrerai de leur servitude, je vous rachèterai à bras étendu, et par de grands jugements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Et je vous prendrai pour être mon peuple, je vous serai Dieu, et vous connaîtrez que je suis l’Eternel votre Dieu, qui vous retire de dessous les charges des Égyptiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Et je vous ferai entrer au pays touchant lequel j’ai levé ma main, que je le donnerais à Abraham, à Isaac, et à Jacob, et je vous le donnerai en héritage: Je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Moïse donc parla en cette manière aux enfants d’Israël. Mais ils n’écoutèrent point Moïse, à cause de l’angoisse de leur esprit, et à cause de leur dure servitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Va, et dis à Pharaon Roi d’Egypte, qu’il laisse sortir les enfants d’Israël de son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Alors Moïse parla devant l’Eternel, en disant: voici, les enfants d’Israël ne m’ont point écouté, et comment Pharaon m’écoutera-t-il, moi, qui suis incirconcis de lèvres?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Mais l’Eternel parla à Moïse et à Aaron, et leur commanda d’aller trouver les enfants d’Israël, et Pharaon Roi d’Egypte, pour retirer les enfants d’Israël du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Ce sont ici les Chefs des maisons de leurs pères: Les enfants de Ruben, premier-né d’Israël, Hénoc et Pallu, Hetsron et Carmi; ce sont là les familles de Ruben.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Et les enfants de Siméon, Jémuel, Jamin, Ohad, Jakin, Tsohar, et Saül, fils d’une Chananéenne; ce sont là les familles de Siméon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Et ce sont ici les noms des enfants de Lévi selon leur naissance: Guerson, Kéhath et Mérari. Et les années de la vie de Lévi furent cent trente-sept.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Les enfants de Guerson, Libni et Simhi, selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Et les enfants de Kéhath, Hamram, Jitshar, Hébron, et Huziel. Et les années de la vie de Kéhath furent cent trente-trois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Et les enfants de Mérari, Mahli et Musi; ce sont là les familles de Lévi selon leurs générations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Or Hamram prit Jokébed sa tante pour femme, qui lui enfanta Aaron et Moïse; et les années de la vie de Hamram furent cent trente-sept.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Et les enfants de Jitshar, Coré, Népheg, et Zicri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Et les enfants de Huziel, Misaël, Eltsaphan, et Sithri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Et Aaron prit pour femme Elisébah, fille de Hamminadab, soeur de Nahasson, qui lui enfanta Nadab, Abihu, Eléazar, et Ithamar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Et les enfants de Coré, Assir, Elkana, et Abiasaph. Ce sont là les familles des Corites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Mais Eléazar fils d’Aaron prit pour femme une des filles de Puthiel, qui lui enfanta Phinées. Ce sont là les Chefs des pères des Lévites selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Or c’est là cet Aaron et ce Moïse auxquels l’Eternel dit: retirez les enfants d’Israël du pays d’Egypte selon leurs bandes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Ce sont eux qui parlèrent à Pharaon Roi d’Egypte, pour retirer d’Egypte les enfants d’Israël. C’est ce Moïse, et c’est cet Aaron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Il arriva donc le jour que l’Eternel parla à Moïse au pays d’Egypte,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Que l’Eternel parla à Moïse, en disant: je suis l’Eternel; dis à Pharaon Roi d’Egypte toutes les paroles que je t’ai dites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Et Moïse dit devant l’Eternel: voici, je suis incirconcis de lèvres, et comment Pharaon m’écoutera-t-il?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Et l’Eternel dit à Moïse: voici, je t’ai établi pour être Dieu à Pharaon, et Aaron ton frère sera ton Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Tu diras toutes les choses que je t’aurai commandées, et Aaron ton frère dira à Pharaon qu’il laisse aller les enfants d’Israël hors de son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Mais j’endurcirai le coeur de Pharaon, et je multiplierai mes signes et mes miracles au pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Et Pharaon ne vous écoutera point; je mettrai ma main sur l’Egypte, et je retirerai mes armées, mon peuple, les enfants d’Israël, du pays d’Egypte, par de grands jugements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Et les Égyptiens sauront que je suis l’Eternel, quand j’aurai étendu ma main sur l’Egypte, et que j’aurai retiré du milieu d’eux les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Et Moïse et Aaron firent comme l’Eternel leur avait commandé; ils firent ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Or Moïse était âgé de quatre-vingts ans, et Aaron de quatre-vingt-trois, quand ils parlèrent à Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Et l’Eternel parla à Moïse et à Aaron, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Quand Pharaon vous parlera, en disant: faites un miracle; tu diras alors à Aaron: prends ta verge, et la jette devant Pharaon, et elle deviendra un dragon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Moïse donc et Aaron vinrent vers Pharaon, et firent comme l’Eternel avait commandé; et Aaron jeta sa verge devant Pharaon, et devant ses serviteurs, et elle devint un dragon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Mais Pharaon fit venir aussi les sages et les enchanteurs; et les magiciens d’Egypte firent le semblable par leurs enchantements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Ils jetèrent donc chacun leurs verges, et elles devinrent des dragons; mais la verge d’Aaron engloutit leurs verges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Et le coeur de Pharaon s’endurcit, et il ne les écouta point; selon que l’Eternel en avait parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Et l’Eternel dit à Moïse: le coeur de Pharaon est endurci, il a refusé de laisser aller le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Va-t’en dès le matin vers Pharaon; voici, il sortira vers l’eau, tu te présenteras donc devant lui sur le bord du fleuve, et tu prendras en ta main la verge qui a été changée en serpent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Et tu lui diras: l’Eternel, le Dieu des Hébreux m’avait envoyé vers toi, pour te dire: laisse aller mon peuple, afin qu’il me serve au désert; mais voici, tu ne m’as point écouté jusques ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Ainsi a dit l’Éternel: tu sauras à ceci que je suis l’Eternel; voici, je m’en vais frapper de la verge qui est en ma main les eaux du fleuve, et elles seront changées en sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Et le poisson qui est dans le fleuve, mourra, et le fleuve deviendra puant, et les Egyptiens travailleront beaucoup pour trouver à boire des eaux du fleuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'L’Eternel dit aussi à Moïse: dis à Aaron: prends ta verge, et étends ta main sur les eaux des Egyptiens, sur leurs rivières, sur leurs ruisseaux, et sur leurs marais, et sur tous les amas de leurs eaux, et elles deviendront du sang, et il y aura du sang par tout le pays d’Egypte, dans les vaisseaux de bois et de pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Moïse donc et Aaron firent selon que l’Eternel avait commandé. Et Aaron ayant levé la verge, en frappa les eaux du fleuve, Pharaon et ses serviteurs le voyant; et toutes les eaux du fleuve furent changées en sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Et le poisson qui était au fleuve mourut, et le fleuve en devint puant, tellement que les Egyptiens ne pouvaient point boire des eaux du fleuve; et il y eut du sang par tout le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Et les magiciens d’Egypte firent le semblable par leurs enchantements; et le coeur de Pharaon s’endurcit, tellement qu’il ne les écouta point; selon que l’Eternel en avait parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Et Pharaon leur ayant tourné le dos, vint en sa maison, et n’appliqua point encore son coeur aux choses qu’il avait vues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Or tous les Egyptiens creusèrent autour du fleuve pour trouver de l’eau à boire, parce qu’ils ne pouvaient pas boire de l’eau du fleuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Et il se passa sept jours depuis que l’Eternel eut frappé le fleuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Après cela l’Eternel dit à Moïse: va vers Pharaon, et lui dis: ainsi a dit l’Eternel: laisse aller mon peuple, afin qu’ils me servent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Que si tu refuses de le laisser aller, voici, je m’en vais frapper de grenouilles toutes tes contrées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Et le fleuve fourmillera de grenouilles, qui monteront et entreront dans ta maison, et dans la chambre où tu couches, et sur ton lit, et dans la maison de tes serviteurs, et parmi tout ton peuple, dans tes fours, et dans tes maies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Ainsi les grenouilles monteront sur toi, sur ton peuple, et sur tous tes serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'L’Eternel donc dit à Moïse: dis à Aaron: étends ta main avec ta verge sur les fleuves, sur les rivières, et sur les marais, et fais monter les grenouilles sur le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Et Aaron étendit sa main sur les eaux de l’Egypte, et les grenouilles montèrent, et couvrirent le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Mais les magiciens firent de même par leurs enchantements, et firent monter des grenouilles sur le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Alors Pharaon appela Moïse et Aaron, et leur dit: fléchissez l’Eternel par vos prières, afin qu’il retire les grenouilles de dessus moi et de dessus mon peuple; et je laisserai aller le peuple, afin qu’ils sacrifient à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Et Moïse dit à Pharaon: glorifie-toi sur moi. Pour quel temps fléchirai-je par mes prières l’Eternel pour toi et pour tes serviteurs, et pour ton peuple, afin qu’il chasse les grenouilles loin de toi, et de tes maisons? Il en demeurera seulement dans le fleuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Alors il répondit: pour demain. Et Moïse dit: il sera fait selon ta parole, afin que tu saches qu’il n’y a nul Dieu tel que l’Eternel notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Les grenouilles donc se retireront de toi, et de tes maisons, et de tes serviteurs, et de ton peuple; il en demeurera seulement dans le fleuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Alors Moïse et Aaron sortirent d’avec Pharaon; et Moïse cria à l’Eternel au sujet des grenouilles qu’il avait fait venir sur Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Et l’Eternel fit selon la parole de Moïse. Ainsi les grenouilles moururent; et il n’y en eut plus dans les maisons, ni dans les villages, ni à la campagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Et on les amassa par monceaux, et la terre en fut infectée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Mais Pharaon voyant qu’il avait du relâche, endurcit son coeur, et ne les écouta point, selon que l’Eternel en avait parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Et l’Eternel dit à Moïse: dis à Aaron: étends ta verge, et frappe la poussière de la terre, et elle deviendra des poux par tout le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Et ils firent ainsi. Et Aaron étendit sa main avec sa verge, et frappa la poussière de la terre, et elle devint des poux, sur les hommes, et sur les bêtes; toute la poussière du pays devint des poux en tout le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Et les magiciens voulurent faire de même par leurs enchantements, pour produire des poux, mais ils ne purent. Les poux furent donc tant sur les hommes que sur les bêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Alors les magiciens dirent à Pharaon: c’est ici le doigt de Dieu. Toutefois le coeur de Pharaon s’endurcit et il ne les écouta point, selon que l’Eternel en avait parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Puis l’Eternel dit à Moïse: lève-toi de bon matin, et te présente devant Pharaon; voici, il sortira vers l’eau, et tu lui diras: ainsi a dit l’Eternel: laisse aller mon peuple, afin qu’ils me servent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Car si tu ne laisses pas aller mon peuple, voici, je m’en vais envoyer contre toi, contre tes serviteurs, contre ton peuple, et contre tes maisons, un mélange d’insectes; et les maisons des Egyptiens seront remplies de ce mélange, et la terre aussi sur laquelle ils seront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Mais je distinguerai en ce jour-là le pays de Goscen, où se tient mon peuple, tellement qu’il n’y aura nul mélange d’insectes, afin que tu saches que je suis l’Eternel au milieu de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Et je mettrai de la différence entre ton peuple et mon peuple; demain ce signe-là se fera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Et l’Eternel le fit ainsi; et un grand mélange d’insectes entra dans la maison de Pharaon, et dans chaque maison de ses serviteurs, et dans tout le pays d’Egypte, de sorte que la terre fut gâtée par ce mélange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Et Pharaon appela Moïse et Aaron, et leur dit: allez, sacrifiez à votre Dieu dans ce pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Mais Moïse dit: il n’est pas à propos de faire ainsi; car nous sacrifierions à l’Eternel notre Dieu l’abomination des Egyptiens. Voici, si nous sacrifions l’abomination des Égyptiens devant leurs yeux, ne nous lapideraient-ils pas?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Nous irons le chemin de trois jours au désert, et nous sacrifierons à l’Eternel notre Dieu, comme il nous dira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Alors Pharaon dit: je vous laisserai aller pour sacrifier dans le désert à l’Eternel votre Dieu; toutefois vous ne vous éloignerez nullement en vous en allant. Fléchissez l’Eternel pour moi par vos prières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Et Moïse dit: voici, je sors d’avec toi, et je fléchirai par prières l’Eternel, afin que le mélange d’insectes se retire demain de Pharaon, de ses serviteurs, et de son peuple. Mais que Pharaon ne continue point à se moquer, en ne laissant point aller le peuple pour sacrifier à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Alors Moïse sortit d’avec Pharaon, et fléchit l’Eternel par prières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Et l’Eternel fit selon la parole de Moïse; et le mélange d’insectes se retira de Pharaon, et de ses serviteurs, et de son peuple; il ne resta pas un seul insecte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Mais Pharaon endurcit son coeur encore cette fois, et ne laissa point aller le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Alors l’Eternel dit à Moïse: va vers Pharaon, et lui dis: ainsi a dit l’Eternel, le Dieu des Hébreux: laisse aller mon peuple, afin qu’ils me servent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Car si tu refuses de les laisser aller, et si tu les retiens encore,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'Voici, la main de l’Eternel sera sur ton bétail qui est aux champs, tant sur les chevaux, que sur les ânes, sur les chameaux, sur les boeufs, et sur les brebis, et il y aura une très-grande mortalité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Et l’Eternel distinguera le bétail des Israélites du bétail des Egyptiens, afin que rien de ce qui est aux enfants d’Israël ne meure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Et l’Eternel assigna un terme, en disant: demain l’Eternel fera ceci dans le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'L’Eternel donc fit cela dès le lendemain; et tout le bétail des Egyptiens mourut. Mais du bétail des enfants d’Israël, il n’en mourut pas une seule bête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Et Pharaon envoya examiner, et voici, il n’y avait pas une seule bête morte du bétail des enfants d’Israël. Toutefois le coeur de Pharaon s’endurcit; et il ne laissa point aller le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Alors l’Eternel dit à Moïse et à Aaron: prenez plein vos mains de cendres de fournaise; et que Moïse les répande vers les cieux en la présence de Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Et elles deviendront de la poussière sur tout le pays d’Egypte, et il s’en fera des ulcères bourgeonnant en pustules tant sur les hommes que sur les bêtes, dans tout le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Ils prirent donc de la cendre de fournaise, et se tinrent devant Pharaon; et Moïse la répandit vers les cieux; et il s’en forma des ulcères bourgeonnant en pustules, tant aux hommes qu’aux bêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Et les magiciens ne purent se tenir devant Moïse, à cause des ulcères; car les magiciens avaient des ulcères, comme tous les Egyptiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Et l’Eternel endurcit le coeur de Pharaon, et il ne les écouta point selon que l’Eternel en avait parlé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Puis l’Eternel dit à Moïse: lève-toi de bon matin, et te présente devant Pharaon, et lui dit: ainsi a dit l’Eternel, le Dieu des Hébreux: laisse aller mon peuple, afin qu’ils me servent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Car à cette fois je vais faire venir toutes mes plaies dans ton coeur; et sur tes serviteurs, et sur ton peuple; afin que tu saches qu’il n’y a nul Dieu semblable à moi en toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Car maintenant si j’eusse étendu ma main, je t’eusse frappé de mortalité, toi et ton peuple, et tu eusses été effacé de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Mais certainement je t’ai fait subsister pour ceci, afin de faire voir en toi ma puissance, et afin que mon nom soit célébré par toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'T’élèves-tu encore contre mon peuple, pour ne le laisser point aller?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Voici, je m’en vais faire pleuvoir demain à cette même heure une grosse grêle, à laquelle il n’y en a point eu de semblable en Egypte, depuis le jour qu’elle a été fondée jusques à maintenant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Maintenant donc envoie rassembler ton bétail, et tout ce que tu as à la campagne; car la grêle tombera sur tous les hommes, et sur le bétail qui se trouvera à la campagne, et qu’on n’aura pas renfermé, et ils mourront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Celui des serviteurs de Pharaon, qui craignit la parole de l’Eternel, fit promptement retirer dans les maisons ses serviteurs et ses bêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Mais celui qui n’appliqua point son coeur à la parole de l’Eternel, laissa ses serviteurs et ses bêtes à la campagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Et l’Eternel dit à Moïse: étends ta main vers les cieux, et il y aura de la grêle en tout le pays d’Egypte, sur les hommes, et sur les bêtes, et sur toutes les herbes des champs au pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Moïse donc étendit sa verge vers les cieux, et l’Eternel envoya des tonnerres et de la grêle, et le feu se promenait sur la terre. L’Eternel fit donc pleuvoir de la grêle sur le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Il y eut donc de la grêle et du feu entremêlé avec la grêle, laquelle était si grosse qu’il n’y en avait point eu de semblable en toute la terre d’Egypte, depuis qu’elle a été habitée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Et la grêle frappa dans tout le pays d’Egypte tout ce qui était aux champs, depuis les hommes jusqu’aux bêtes. La grêle frappa aussi toutes les herbes des champs, et brisa tous les arbres des champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Il n’y eut que la contrée de Goscen, dans laquelle étaient les enfants d’Israël, où il n’y eut point de grêle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Alors Pharaon envoya appeler Moïse et Aaron, et leur dit: J’ai péché cette fois; l’Eternel est juste, mais moi et mon peuple sommes méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Fléchissez par prières l’Eternel; que ce soit assez; et que Dieu ne fasse plus tonner ni grêler, car je vous laisserai aller, et on ne vous arrêtera plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Alors Moïse dit: aussitôt que je serai sorti de la ville j’étendrai mes mains vers l’Eternel et les tonnerres cesseront, et il n’y aura plus de grêle, afin que tu saches que la terre est à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Mais quant à toi et à tes serviteurs, je sais que vous ne craindrez pas encore l’Eternel Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Or le lin et l’orge avaient été frappés, car l’orge était en épis et le lin était en tuyau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Mais le blé et l’épeautre ne furent point frappés, parce qu’ils étaient cachés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Moïse donc étant sorti d’avec Pharaon hors de la ville étendit ses mains vers l’Eternel, et les tonnerres cessèrent, et la grêle et la pluie ne tombèrent plus sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Et Pharaon voyant que la pluie, la grêle, et les tonnerres avaient cessé, continua encore à pécher, et il endurcit son coeur, lui et ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Le coeur donc de Pharaon s’endurcit, et il ne laissa point aller les enfants d’Israël; selon que l’Eternel en avait parlé par le moyen de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Et l’Éternel dit à Moïse: Va vers Pharaon, car j’ai appesanti son cœur et le cœur de ses serviteurs, afin de mettre au milieu d’eux mes prodiges,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'Et afin que tu racontes à ton fils et au fils de ton fils, les exploits que j’aurai accomplis sur les Égyptiens et les prodiges que j’aurai faits au milieu d’eux, et que vous sachiez que je suis l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Moïse et Aaron vinrent donc vers Pharaon, et lui dirent: Ainsi a dit l’Éternel, le Dieu des Hébreux: Jusqu’à quand refuseras-tu de t’humilier devant moi? Laisse aller mon peuple, afin qu’il me serve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Car si tu refuses de laisser aller mon peuple, voici, je ferai venir demain des sauterelles dans ton territoire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Et elles couvriront la face de la terre, et l’on ne pourra plus voir la terre; et elles dévoreront le reste de ce qui est échappé, ce que la grêle vous a laissé; et elles dévoreront tous les arbres qui poussent dans vos champs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Et elles rempliront tes maisons, et les maisons de tous tes serviteurs, et les maisons de tous les Égyptiens; ce que tes pères n’ont point vu, ni les pères de tes pères, depuis le jour qu’ils ont été sur la terre, jusqu’à ce jour. Puis il se tourna et sortit de chez Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Et les serviteurs de Pharaon lui dirent: Jusqu’à quand celui-ci nous sera-t- il en piège? Laisse aller ces gens, et qu’ils servent l’Éternel leur Dieu. Ne vois-tu pas encore que l’Égypte est perdue?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Alors on fit revenir Moïse et Aaron vers Pharaon, et il leur dit: Allez, servez l’Éternel votre Dieu. Quels sont tous ceux qui iront?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Et Moïse répondit: Nous irons avec nos jeunes gens et nos vieillards, avec nos fils et nos filles; nous irons avec nos brebis et nos bœufs; car c’est pour nous une fête de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Alors il leur dit: Que l’Éternel soit avec vous, comme je vous laisserai aller, vous et vos petits enfants! Prenez garde, car le mal est devant vous!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Il n’en sera pas ainsi; allez, vous les hommes, et servez l’Éternel; car c’est ce que vous demandiez. Et on les chassa de devant Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Alors l’Éternel dit à Moïse: Étends ta main sur le pays d’Égypte, pour faire venir les sauterelles, et qu’elles montent sur le pays d’Égypte, et dévorent toute l’herbe de la terre, tout ce que la grêle a laissé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Moïse étendit donc sa verge sur le pays d’Égypte; et l’Éternel amena sur le pays, tout ce jour-là et toute la nuit, un vent d’Orient; le matin vint, et le vent d’Orient avait apporté les sauterelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Et les sauterelles montèrent sur tout le pays d’Égypte, et s’abattirent dans tout le territoire de l’Égypte, en très grand nombre. Il n’y en avait point eu avant elles de semblables, et il n’y en aura point de semblables après elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Elles couvrirent la face de tout le pays, et le pays en fut obscurci; et elles dévorèrent toute l’herbe de la terre, et tout le fruit des arbres, que la grêle avait laissé; et il ne resta aucune verdure aux arbres, ni aux herbes des champs, dans tout le pays d’Égypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Alors Pharaon se hâta d’appeler Moïse et Aaron, et dit: J’ai péché contre l’Éternel votre Dieu, et contre vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Mais, maintenant, pardonne, je te prie, mon péché, pour cette fois seulement; et intercédez auprès de l’Éternel votre Dieu, pour qu’il éloigne de moi seulement cette mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Il sortit donc de chez Pharaon, et intercéda auprès de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Et l’Éternel ramena un vent d’Occident très fort, qui emporta les sauterelles, et les précipita dans la mer Rouge. Il ne resta pas une seule sauterelle dans tout le territoire de l’Égypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Mais l’Éternel endurcit le cœur de Pharaon, et il ne laissa point aller les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Alors l’Éternel dit à Moïse: Étends ta main vers les cieux, et qu’il y ait des ténèbres sur le pays d’Égypte, telles qu’on puisse les toucher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Moïse étendit donc sa main vers les cieux, et il y eut d’épaisses ténèbres dans tout le pays d’Égypte, pendant trois jours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'On ne se voyait pas l’un l’autre, et nul ne se leva de sa place, pendant trois jours. Mais pour tous les enfants d’Israël il y eut de la lumière dans le lieu de leurs demeures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Alors Pharaon appela Moïse et dit: Allez, servez l’Éternel; que vos brebis et vos bœufs seuls demeurent; vos petits enfants iront aussi avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Mais Moïse répondit: Tu mettras toi-même entre nos mains de quoi faire des sacrifices et des holocaustes, que nous offrirons à l’Éternel notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Et nos troupeaux iront aussi avec nous; il n’en restera pas un ongle. Car nous en prendrons pour servir l’Éternel notre Dieu; et nous ne saurons avec quoi nous devrons servir l’Éternel, que nous ne soyons arrivés là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Mais l’Éternel endurcit le cœur de Pharaon, et il ne voulut point les laisser aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Et Pharaon lui dit: Va-t’en de devant moi! Garde-toi de revoir ma face, car le jour où tu verras ma face, tu mourras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Alors Moïse répondit: Tu as bien dit; je ne reverrai plus ta face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Or l’Eternel avait dit à Moïse, je ferai venir encore une plaie sur Pharaon, et sur l’Egypte, et après cela il vous laissera aller d’ici, il vous laissera entièrement aller, et vous chassera tout à fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Parle maintenant, le peuple l’entendant, et leur dis: que chacun demande à son voisin, et chacune à sa voisine, des vaisseaux d’argent, et des vaisseaux d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Or l’Eternel avait fait trouver grâce au peuple devant les Egyptiens; et même Moïse passait pour un fort grand homme au pays d’Egypte, tant parmi les serviteurs de Pharaon, que parmi le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Et Moïse dit: ainsi a dit l’Eternel: environ sur la minuit je passerai au travers de l’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Et tout premier-né mourra au pays d’Egypte, depuis le premier-né de Pharaon, qui devait être assis sur son trône, jusqu’au premier-né de la servante qui est employée à moudre; même tout premier-né des bêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Et il y aura un si grand cri dans tout le pays d’Egypte, qu’il n’y en eut jamais, ni il n’y en aura jamais de semblable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Mais contre tous les enfants d’Israël un chien même ne remuera point sa langue, depuis l’homme jusques aux bêtes; afin que vous sachiez que Dieu aura mis de la différence entre les Egyptiens et les Israélites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Et tous ces tiens serviteurs viendront vers moi, et se prosterneront devant moi, en disant: sors, toi, et tout le peuple qui est avec toi; et puis je sortirai. Ainsi Moïse sortit d’auprès de Pharaon dans une ardente colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'L’Eternel donc avait dit à Moïse: Pharaon ne vous écoutera point, afin que mes miracles soient multipliés au pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Et Moïse et Aaron firent tous ces miracles-là devant Pharaon. Et l’Eternel endurcit le coeur de Pharaon, tellement qu’il ne laissa point aller les enfants d’Israël hors de son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Or l’Eternel avait parlé à Moïse et à Aaron au pays d’Egypte, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Ce mois-ci vous sera le commencement des mois, il vous sera le premier des mois de l’année.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Parlez à toute l’assemblée d’Israël, en disant: qu’au dixième jour de ce mois, chacun d’eux prenne un petit d’entre les brebis ou d’entre les chèvres, selon les familles des pères, un petit, dis-je, d’entre les brebis ou d’entre les chèvres, par famille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Mais si la famille est moindre qu’il ne faut pour manger un petit d’entre les brebis ou d’entre les chèvres, qu’il prenne son voisin qui est près de sa maison, selon le nombre des personnes; vous compterez combien il en faudra pour manger un petit d’entre les brebis ou d’entre les chèvres, ayant égard à ce que chacun de vous peut manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Or le petit d’entre les brebis ou d’entre les chèvres sera sans tare, et sera un mâle, ayant un an; vous le prendrez d’entre les brebis, ou d’entre les chèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Et vous le tiendrez en garde jusqu’au quatorzième jour de ce mois, et toute la congrégation de l’assemblée d’Israël l’égorgera entre les deux vêpres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Et ils prendront de son sang, et le mettront sur les deux poteaux, et sur le linteau de la porte des maisons où ils le mangeront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Et ils en mangeront la chair rôtie au feu cette nuit-là; et ils la mangeront avec des pains sans levain, et avec des herbes amères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'N’en mangez rien à demi cuit, ni qui ait été bouilli dans l’eau, mais qu’il soit rôti au feu, sa tête, ses jambes, et ses entrailles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Et n’en laissez rien de reste jusques au matin, mais s’il en reste quelque chose jusqu’au matin, vous le brûlerez au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Et vous le mangerez ainsi; vos reins seront ceints, vous aurez vos souliers en vos pieds, et votre bâton en votre main, et vous le mangerez à la hâte. C’est la Pâque de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Car je passerai cette nuit-là par le pays d’Egypte, et je frapperai tout premier-né au pays d’Egypte, depuis les hommes jusques aux bêtes, et j’exercerai des jugements, sur tous les dieux de l’Egypte; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Et le sang vous sera pour signe sur les maisons dans lesquelles vous serez, car je verrai le sang, et je passerai par-dessus vous, et il n’y aura point de plaie à destruction parmi vous, quand je frapperai le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Et ce jour-là vous sera en mémorial, et vous le célébrerez comme une fête solennelle à l’Eternel en vos âges; vous le célébrerez comme une fête solennelle, par ordonnance perpétuelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Vous mangerez pendant sept jours des pains sans levain, et dès le premier jour vous ôterez le levain de vos maisons; car quiconque mangera du pain levé, depuis le premier jour jusques au septième, cette personne-là sera retranchée d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Au premier jour il y aura une sainte convocation, et il y aura de même au septième jour une sainte convocation; il ne se fera aucune oeuvre en ces jours-là; seulement on vous apprêtera à manger ce qu’il faudra pour chaque personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Vous prendrez donc garde aux pains sans levain; parce qu’en ce même jour j’aurai retiré vos bandes du pays d’Egypte; vous observerez donc ce jour-là en vos âges, par ordonnance perpétuelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Au premier mois, le quatorzième jour du mois au soir, vous mangerez des pains sans levain, jusqu’au vingt-unième jour du mois, au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Il ne se trouvera point de levain dans vos maisons pendant sept jours; car quiconque mangera du pain levé, cette personne-là sera retranchée de rassemblée d’Israël, tant celui qui habite comme étranger, que celui qui est né au pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Vous ne mangerez point de pain levé; mais vous mangerez dans tous les lieux où vous demeurerez, des pains sans levain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Moïse donc appela tous les anciens d’Israël, et leur dit: choisissez, et prenez un petit d’entre les brebis, ou d’entre les chèvres, selon vos familles, et égorgez la Pâque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Puis vous prendrez un bouquet d’hysope, et le tremperez dans le sang qui sera dans un bassin, et vous arroserez du sang qui sera dans le bassin, le linteau, et les deux poteaux; et nul de vous ne sortira de la porte de sa maison, jusqu’au matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Car l’Eternel passera pour frapper l’Egypte, et il verra le sang sur le linteau, et sur les deux poteaux, et l’Eternel passera par-dessus la porte, et ne permettra point que le destructeur entre dans vos maisons pour frapper.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Vous garderez ceci comme une ordonnance perpétuelle pour toi et pour tes enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Quand donc vous serez entrés au pays que l’Eternel vous donnera, selon qu’il en a parlé, vous garderez ce service.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Et quand vos enfants vous diront: que vous signifie ce service?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Alors vous répondrez: c’est le sacrifice de la Pâque à l’Eternel, qui passa en Egypte par-dessus les maisons des enfants d’Israël, quand il frappa l’Egypte, et qu’il préserva nos maisons. Alors le peuple s’inclina, et se prosterna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Ainsi les enfants d’Israël s’en allèrent, et firent comme l’Eternel l’avait commandé à Moïse et à Aaron, ils le firent ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Et il arriva qu’à minuit l’Eternel frappa tous les premiers-nés du pays d’Egypte, depuis le premier-né de Pharaon, qui devait être assis sur son trône, jusqu’aux premiers-nés des captifs qui étaient dans la prison, et tous les premiers-nés des bêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Et Pharaon se leva de nuit, lui et ses serviteurs, et tous les Egyptiens; et il y eut un grand cri en Egypte, parce qu’il n’y avait point de maison où il n’y eût un mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Il appela donc Moïse et Aaron de nuit, et leur dit: levez-vous, sortez du milieu de mon peuple, tant vous que les enfants d’Israël, et vous en allez; servez l’Eternel, comme vous en avez parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Prenez aussi votre menu et gros bétail, selon que vous en avez parlé, et vous en allez, et bénissez-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Et les Egyptiens forçaient le peuple, et se hâtaient de les faire sortir du pays; car ils disaient: nous sommes tous morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Le peuple donc prit sa pâte avant qu’elle fût levée, ayant leurs maies liées avec leurs vêtements, sur leurs épaules.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Or les enfants d’Israël avaient fait selon la parole de Moïse, et avaient demandé aux Egyptiens des vaisseaux d’argent et d’or, et des vêtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Et l’Eternel avait fait trouver grâce au peuple envers les Egyptiens, qui les leur avaient prêtés; de sorte qu’ils butinèrent les Egyptiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Ainsi les enfants d’Israël étant partis de Rahmésès, vinrent à Succoth, environ six cent mille hommes de pied, sans les petits enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Il s’en alla aussi avec eux un grand nombre de toutes sortes de gens; et du menu et du gros bétail en fort grands troupeaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Or parce qu’ils avaient été chassés d’Egypte, et qu’ils n’avaient pas pu tarder plus longtemps, et que même ils n’avaient fait aucune provision, ils cuisirent par gâteaux sans levain la pâte qu’ils avaient emportée d’Egypte; car ils ne l’avaient point fait lever.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Or la demeure que les enfants d’Israël avaient faite en Egypte, était de quatre cent et trente ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Il arriva donc, au bout de quatre cent et trente ans, il arriva, dis-je, en ce propre jour-là, que toutes les bandes de l’Eternel sortirent du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'C’est la nuit qui doit être soigneusement observée à l’honneur de l’Eternel, parce qu’ alors il les retira du pays d’Egypte; cette même nuit-là est à observer à l’honneur de l’Eternel, par tous les enfants d’Israël en leurs âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'L’Eternel dit aussi à Moïse et à Aaron: c’est ici l’ordonnance de la Pâque: aucun étranger n’en mangera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Mais tout esclave qu’on aura acheté par argent sera circoncis, et alors il en mangera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'L’étranger et le mercenaire n’en mangeront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'On la mangera dans une même maison, et vous n’emporterez point de sa chair hors de la maison, et vous n’en casserez point les os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Toute l’assemblée d’Israël la fera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Et si quelque étranger qui habite chez toi, veut faire la Pâque à l’Eternel, que tout mâle qui lui appartient soit circoncis, et alors il s’approchera pour la faire, et il sera comme celui qui est né au pays; mais aucun incirconcis n’en mangera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Il y aura une même loi pour celui qui est né au pays et pour l’étranger qui habite parmi vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Tous les enfants d’Israël firent ainsi que l’Eternel avait commandé à Moïse et à Aaron; ils le firent ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Il arriva donc en ce propre jour-là, que l’Eternel retira les enfants d’Israël du pays d’Egypte, selon leurs bandes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Et l’Eternel parla à Moïse, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Sanctifie-moi tout premier-né, tout ce qui ouvre la matrice entre les enfants d’Israël, tant des hommes que des bêtes, car il est à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Moïse donc dit au peuple: souvenez-vous de ce jour, auquel vous êtes sortis d’Egypte, de la maison de servitude; car l’Eternel vous en a retirés par main forte; on ne mangera donc point de pain levé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Vous sortez aujourd’hui au mois que les épis mûrissent:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Quand donc l’Eternel t’aura introduit au pays des Chananéens, des Héthiens, des Amorrhéens, des Héviens et des Jébusiens, lequel il a juré à tes pères de te donner, et qui est un pays découlant de lait et de miel; alors tu feras ce service en ce mois-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Durant sept jours tu mangeras des pains sans levain, et au septième jour il y aura une fête solennelle à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'On mangera durant sept jours des pains sans levain; et il ne sera point vu chez toi de pain levé; et même il ne sera point vu de levain en toutes tes contrées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Et en ce jour-là tu feras entendre ces choses à tes enfants, en disant: c’est à cause de ce que l’Eternel m’a fait en me retirant d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Et ceci te sera pour signe sur ta main, et pour mémorial entre tes yeux, afin que la Loi de l’Eternel soit en ta bouche, parce que l’Eternel t’aura retiré d’Egypte par main forte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Tu garderas donc cette ordonnance en sa saison, d’année en année.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Aussi quand l’Eternel t’aura introduit au pays des Chananéens, selon qu’il a juré à toi et à tes pères, et qu’il te l’aura donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Alors tu présenteras à l’Eternel tout ce qui ouvre la matrice; même tout ce qui en sortant ouvre la portière des bêtes; ce que tu auras de mâles sera à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Mais tu rachèteras avec un petit d’entre les brebis ou d’entre les chèvres, toute première portée des ânesses, et si tu ne le rachètes point, tu lui couperas le cou. Tu rachèteras aussi tout premier-né des hommes entre tes enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Et quand ton fils t’interrogera à l’avenir, en disant: que veut dire ceci? Alors tu lui diras: l’Eternel nous a retirés par main forte hors d’Egypte, de la maison de servitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Car il arriva que quand Pharaon s’opiniâtra à ne nous laisser point aller, l’Eternel tua tous les premiers-nés au pays d’Egypte, depuis les premiers-nés des hommes jusques aux premiers-nés des bêtes; c’est pourquoi je sacrifie à l’Eternel tout mâle qui ouvre la portière, et je rachète tout premier-né de mes enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Ceci te sera donc pour signe sur ta main, et pour fronteaux entre tes yeux, que l’Eternel nous a retirés d’Egypte par main forte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Or quand Pharaon eut laissé aller le peuple, Dieu ne les conduisit point par le chemin du pays des Philistins, quoi qu’il fût le plus court; car Dieu disait: c’est afin qu’il n’arrive que le peuple se repente quand il verra la guerre, et qu’il ne retourne en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Mais Dieu fit tournoyer le peuple par le chemin du désert, vers la mer rouge. Ainsi les enfants d’Israël montèrent en armes du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Et Moïse avait pris avec soi les os de Joseph; parce que Joseph avait expressément fait jurer les enfants d’Israël, en leur disant: Dieu vous visitera très-certainement, vous transporterez donc avec vous mes os d’ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Et ils partirent de Succoth, et se campèrent à Etham, qui est au bout du désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Et l’Eternel allait devant eux, de jour dans une colonne de nuée pour les conduire par le chemin; et de nuit dans une colonne de feu pour les éclairer, afin qu’ils marchassent jour et nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Et il ne retira point la colonne de nuée le jour, ni la colonne de feu la nuit, de devant le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Parle aux enfants d’Israël; et leur dis, qu’ils se détournent, et qu’ils se campent devant Pi-Hahiroth, entre Migdol et la mer, vis-à-vis de Bahal- Tsépnon; vous camperez vis-à-vis de ce lieu-là près de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Alors Pharaon dira des enfants d’Israël: ils sont embarrassés dans le pays, le désert les a enfermés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Et j’endurcirai le coeur de Pharaon, et il vous poursuivra; ainsi je serai glorifié en Pharaon, et en toute son armée, et les Egyptiens sauront que je suis l’Eternel; et ils firent ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Or on avait rapporté au Roi d’Egypte que le peuple s’enfuyait, et le coeur de Pharaon et de ses serviteurs fut changé à l’égard du peuple, et ils dirent: qu’ est-ce que nous avons fait, que nous ayons laissé aller Israël, en sorte qu’il ne nous servira plus?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Alors il fit atteler son chariot, et il prit son peuple avec soi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Il prit donc six cents chariots d’élite, et tous les chariots d’Egypte; et il y avait des Capitaines sur tout cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Et l’Eternel endurcit le coeur de Pharaon Roi d’Egypte, qui poursuivit les enfants d’Israël. Or les enfants d’Israël étaient sortis à main levée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Les Egyptiens donc les poursuivirent; et tous les chevaux des chariots de Pharaon, ses gens de cheval, et son armée les atteignirent comme ils étaient campés près de la mer, vers Pi-Hahiroth vis-à-vis de Bahal-Tséphon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Et lorsque Pharaon se fut approché, les enfants d’Israël levèrent leurs yeux, et voici, les Egyptiens marchaient après eux, et les enfants d’Israël eurent une fort grande peur, et crièrent à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Et dirent à Moïse: est-ce qu’il n’y avait pas de sépulcres en Egypte, que tu nous aies emmenés pour mourir au désert? Qu’est-ce que tu nous as fait de nous avoir fait sortir d’Egypte?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'N’est-ce pas ce que nous te disions en Egypte, disant: retire-toi de nous, et que nous servions les Egyptiens? Car il vaut mieux que nous les servions, que si nous mourions au désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Et Moïse dit au peuple: ne craignez point, arrêtez-vous, et voyez la délivrance de l’Eternel, laquelle il vous donnera aujourd’hui; car pour les Egyptiens que vous avez vus aujourd’hui, vous ne les verrez plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'L’Eternel combattra pour vous, et vous demeurerez tranquilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Or l’Eternel avait dit à Moïse: que cries-tu à moi? Parle aux enfants d’Israël, qu’ils mArchent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Et toi, élève ta verge, et étends ta main sur la mer, et la fends, et que les enfants d’Israël entrent au milieu de la mer à sec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Et quant à moi, voici, je m’en vais endurcir le coeur des Egyptiens, afin qu’ils entrent après eux; et je serai glorifié en Pharaon, et en toute son armée, en ses chariots et en ses gens de cheval.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Et les Egyptiens sauront que je suis l’Eternel, quand j’aurai été glorifié en Pharaon, en ses chariots, et en ses gens de cheval.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Et l’Ange de Dieu qui allait devant le camp d’Israël, partit, et s’en alla derrière eux; et la colonne de nuée partit de devant eux, et se tint derrière eux:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'Et elle vint entre le camp des Egyptiens et le camp d’Israël; et elle était aux uns une nuée et une obscurité, et pour les autres, elle les éclairait la nuit; et l’un des camps n’approcha point de l’autre durant toute la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Or Moïse avait étendu sa main sur la mer; et l’Eternel fit reculer la mer toute la nuit par un vent d’Orient fort véhément, et mit la mer à sec, et les eaux se fendirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Et les enfants d’Israël entrèrent au milieu de la mer au sec, et les eaux leur servaient de mur à droite et à gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Et les Egyptiens les poursuivirent; et ils entrèrent après eux au milieu de la mer, savoir tous les chevaux de Pharaon, ses chariots, et ses gens de cheval.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Mais il arriva que sur la veille du matin, l’Eternel étant dans la colonne de feu et dans la nuée, regarda le camp des Egyptiens, et le mit en déroute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Il ôta les roues de ses chariots, et fit qu’on les menait bien pesamment. Alors les Egyptiens dirent: fuyons de devant les Israélites, car l’Eternel combat pour eux contre les Egyptiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Et l’Eternel dit à Moïse: étends ta main sur la mer, et les eaux retourneront sur les Egyptiens, sur leurs chariots, et sur leurs gens de cheval.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Moïse donc étendit sa main sur la mer, et la mer reprit son impétuosité comme le matin venait; et les Egyptiens s’enfuyant rencontrèrent la mer qui s’était rejointe; et ainsi l’Eternel jeta les Egyptiens au milieu de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Car les eaux retournèrent et couvrirent les chariots et les gens de cheval de toute l’armée de Pharaon, qui étaient entrés après les Israélites dans la mer, et il n’en resta pas un seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Mais les enfants d’Israël marchèrent au milieu de la mer à sec; et les eaux leur servaient de mur à droite et à gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Ainsi l’Eternel délivra en ce jour-là Israël de la main des Egyptiens; et Israël vit sur le bord de la mer les Egyptiens morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Israël vit donc la grande puissance que l’Eternel avait déployée contre les Egyptiens; et le peuple craignit l’Eternel, et ils crurent en l’Eternel, et à Moïse son serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Alors Moïse, et les enfants d’Israël chantèrent ce cantique à l’Eternel, et dirent: je chanterai à l’Eternel, car il s’est hautement élevé; il a jeté dans la mer le cheval et celui qui le monte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'L’Eternel est ma force et ma louange, et il a été mon Sauveur, mon Dieu Fort. Je lui dresserai un Tabernacle; c’est le Dieu de mon père, je l’exalterai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'L’Eternel est un vaillant guerrier, son nom est l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Il a jeté dans la mer les chariots de Pharaon, et son armée; l’élite de ses Capitaines a été submergée dans la mer rouge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Les gouffres les ont couverts, ils sont descendus au fond des eaux comme une pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Ta dextre, ô Eternel! s’est montrée magnifique en force; ta dextre, ô Eternel! a froissé l’ennemi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Tu as ruiné par la grandeur de ta Majesté ceux qui s’élevaient contre toi; tu as lâché ta colère, et elle les a consumés comme du chaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Par le souffle de tes narines les eaux ont été amoncelées; les eaux courantes se sont arrêtées comme un monceau; les gouffres ont été gelés au milieu de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'L’ennemi disait: je poursuivrai, j’atteindrai, je partagerai le butin, mon âme sera assouvie d’eux, je dégainerai mon épée, ma main les détruira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Tu as soufflé de ton vent, la mer les a couverts; ils ont été enfoncés comme du plomb dans les eaux magnifiques.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Qui est comme toi entre les Forts, ô Eternel! Qui est comme toi, magnifique en sainteté, digne d’être révéré et célébré, faisant des choses merveilleuses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Tu as étendu ta dextre, la terre les a engloutis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Tu as conduit par ta miséricorde ce peuple que tu as racheté; tu l’as conduit par ta force à la demeure de ta sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Les peuples l’ont entendu, et ils en ont tremblé; la douleur a saisi les habitants de la Palestine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Alors les Princes d’Edom seront troublés, et le tremblement saisira les forts de Moab, tous les habitants de Chanaan se fondront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'La frayeur et l’épouvante tomberont sur eux; ils seront rendus stupides comme une pierre, par la grandeur de ton bras, jusqu’à ce que ton peuple, ô Eternel! soit passé; jusqu’à ce que ce peuple que tu as acquis, soit passé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Tu les introduiras et les planteras sur la montagne de ton héritage, au lieu que tu as préparé pour ta demeure ô Eternel! au Sanctuaire, ô Seigneur! que tes mains ont établi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'L’Eternel régnera à jamais et à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Car le cheval de Pharaon est entré dans la mer avec son chariot et ses gens de cheval, et l’Eternel a fait retourner sur eux les eaux de la mer, mais les enfants d’Israël ont marché à sec au milieu de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Et Marie la Prophétesse, soeur d’Aaron, prit un tambour en sa main, et toutes les femmes sortirent après elle, avec des tambours et des flûtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Et Marie leur répondait: chantez à l’Eternel, car il s’est hautement élevé; il a jeté dans la mer le cheval et celui qui le montait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Après cela Moïse fit partir les Israélites de la mer rouge, et ils tirèrent vers le désert de Sur, et ayant marché trois jours par le désert, ils ne trouvaient point d’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'De là ils vinrent à Mara, mais ils ne pouvaient point boire des eaux de Mara, parce qu’elles étaient amères; c’est pourquoi ce lieu fut appelé Mara.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Et le peuple murmura contre Moïse, en disant: que boirons-nous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Et Moïse cria à l’Eternel; et l’Eternel lui enseigna un certain bois, qu’il jeta dans les eaux; et les eaux devinrent douces. Il lui proposa là une ordonnance et une loi, et il l’éprouva là;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Et lui dit: Si tu écoutes attentivement la voix de l’Eternel ton Dieu; si tu fais ce qui est droit devant lui; si tu prêtes l’oreille à ses commandements; si tu gardes toutes ses ordonnances; je ne ferai venir sur toi aucune des infirmités que j’ai fait venir sur l’Egypte; car je suis l’Eternel qui te guérit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Puis ils vinrent à Elim, où il y avait douze fontaines d’eau, et soixante et dix palmes; et ils se campèrent là auprès des eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Et toute l’assemblée des enfants d’Israël étant partie d’Elim vint au désert de Sin, qui est entre Elim et Sinaï, le quinzième jour du second mois après qu’ils furent sortis du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Et toute l’assemblée des enfants d’Israël murmura dans ce désert contre Moïse et Aaron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Et les enfants d’Israël leur dirent: ha! que ne sommes-nous morts par la main de l’Eternel au pays d’Egypte, quand nous étions assis près des potées de chair, et que nous mangions notre soûl de pain; car vous nous avez amenés dans ce désert, pour faire mourir de faim toute cette assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Et l’Eternel dit à Moïse: voici, je vais vous faire pleuvoir des cieux du pain, et le peuple sortira, et en recueillera chaque jour la provision d’un jour, afin que je l’éprouve, pour voir s’il observera ma Loi, ou non.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Mais qu’ils apprêtent au sixième jour ce qu’ils auront apporté, et qu’il y ait le double de ce qu’ils recueilleront chaque jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Moïse donc et Aaron dirent à tous les enfants d’Israël: ce soir vous saurez que l’Eternel vous a tirés du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'Et au matin vous verrez la gloire de l’Eternel; parce qu’il a ouï vos murmures, qui sont contre l’Eternel; car que sommes-nous, que vous murmuriez contre nous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Moïse dit donc: ce sera quand l’Eternel vous aura donné ce soir de la chair à manger, et qu’au matin il vous aura rassasiés de pain, parce qu’il a ouï vos murmures, par lesquels vous avez murmuré contre lui; car que sommes-nous? Vos murmures ne sont pas contre nous, mais contre l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Et Moïse dit à Aaron: dis à toute l’assemblée des enfants d’Israël: approchez-vous de la présence de l’Eternel; car il a ouï vos murmures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Or il arriva qu’aussitôt qu’Aaron eut parlé à toute l’assemblée des enfants d’Israël, ils regardèrent vers le désert, et voici, la gloire de l’Eternel se montra dans la nuée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'J’ai ouï les murmures des enfants d’Israël. Parle-leur et leur dis: entre les deux vêpres vous mangerez de la chair, et au matin vous serez rassasiés de pain; et vous saurez que je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Sur le soir donc il monta des cailles, qui couvrirent le camp, et au matin il y eut une couche de rosée à l’entour du camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Et cette couche de rosée étant évanouie, voici sur la superficie du désert quelque chose de menu et de rond, comme du grésil sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Ce que les enfants d’Israël ayant vu, ils se dirent l’un à l’autre: qu’est- ce? car ils ne savaient ce que c’ était. Et Moïse leur dit: c’est le pain que l’Eternel vous a donné à manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Or ce que l’Eternel a commandé, c’est que chacun en recueille autant qu’il lui en faut pour sa nourriture, un Homer par tête, selon le nombre de vos personnes; chacun en prendra pour ceux qui sont dans sa tente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Les enfants d’Israël firent donc ainsi; et les uns en recueillirent plus, les autres moins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Et ils le mesuraient par Homers; et celui qui en avait recueilli beaucoup n’en avait pas plus qu’il ne lui en fallait; ni celui qui en avait recueilli peu, n’en avait pas moins; mais chacun en recueillait selon ce qu’il en pouvait manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Et Moïse leur avait dit: que personne n’en laisse rien de reste jusqu’au matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Mais il y en eut qui n’obéirent point à Moïse; car quelques-uns en réservèrent jusqu’au matin; et il s’y engendra des vers, et elle puait; et Moïse se mit en grande colère contr’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Ainsi chacun en recueillait tous les matins autant qu’il lui en fallait pour se nourrir, et lorsque la chaleur du soleil était venue, elle se fondait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Mais le sixième jour ils recueillirent du pain au double, deux Homers pour chacun; et les principaux de l’assemblée vinrent pour le rapporter à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Et il leur dit: c’est ce que l’Eternel a dit: Demain est le Repos, le Sabbat sanctifié à l’Eternel; faites cuire ce que vous avez à cuire, et faites bouillir ce que vous avez à bouillir, et serrez tout ce qui sera de surplus, pour le garder jusqu’au matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Ils le serrèrent donc jusques au matin, comme Moïse l’avait commandé, et il ne pua point, ni il n’y eut point de vers dedans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Alors Moïse dit: mangez-le aujourd’hui; car c’est aujourd’hui le Repos de l’Eternel; aujourd’hui vous n’en trouverez point aux champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Durant six jours vous le recueillerez; mais le septième est le Sabbat; il n’y en aura point en ce jour-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Et au septième jour quelques-uns du peuple sortirent pour en recueillir; mais ils n’ en trouvèrent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Et l’Eternel dit à Moïse: jusques à quand refuserez-vous de garder mes commandements et mes lois?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Considérez que l’Eternel vous a ordonné le Sabbat, c’est pourquoi il vous donne au sixième jour du pain pour deux jours; que chacun demeure au lieu où il sera, et qu’aucun ne sorte du lieu où il sera le septième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Le peuple donc se reposa le septième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Et la maison d’Israël nomma ce pain Manne; et elle était comme de la semence de coriandre, blanche, et ayant le goût des beignets au miel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Et Moïse dit: voici ce que l’Eternel a commandé: qu’on en remplisse un Homer, pour le garder dans vos âges, afin qu’on voie le pain que je vous ai fait manger au désert, après vous avoir retirés du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Moïse donc dit à Aaron: prends une cruche, et mets-y un plein Homer de Manne, et le pose devant l’Eternel, pour être gardé dans vos âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Et Aaron le posa devant le Témoignage pour y être gardé, selon que le Seigneur l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Et les enfants d’Israël mangèrent la Manne durant quarante ans, jusqu’à ce qu’ils furent parvenus en un pays habité; ils mangèrent, dis-je, la Manne, jusqu’à ce qu’ils furent parvenus aux frontières du pays de Chanaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Or un Homer est la dixième partie d’un Epha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Et toute l’assemblée des enfants d’Israël partit du désert de Sin, selon leurs traites, suivant le mandement de l’Eternel, et ils se campèrent en Réphidim, où il n’y avait point d’eau à boire pour le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Et le peuple se souleva contre Moïse, et ils lui dirent: donnez-nous de l’eau pour boire. Et Moïse leur dit: pourquoi vous soulevez-vous contre moi? Pourquoi tentez-vous l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Le peuple donc eut soif en ce lieu-là, par faute d’eau; et ainsi le peuple murmura contre Moïse, en disant: pourquoi nous as-tu fait monter hors d’Egypte, pour nous faire mourir de soif, nous, et nos enfants, et nos troupeaux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Et Moïse cria à l’Eternel, en disant: que ferai-je à ce peuple? Dans peu ils me lapideront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Et l’Eternel répondit à Moïse: passe devant le peuple, et prends avec toi des Anciens d’Israël, prends aussi en ta main la verge, avec laquelle tu as frappé le fleuve, et viens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Voici, je vais me tenir là devant toi sur le rocher en Horeb, et tu frapperas le rocher, et il en sortira des eaux, et le peuple boira. Moïse donc fit ainsi, les Anciens d’Israël le voyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Et il nomma le lieu Massa et Mériba; à cause du débat des enfants d’Israël, et parce qu’ils avaient tenté l’Eternel, en disant: l’Eternel est-il au milieu de nous, ou non?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Alors Hamalec vint et livra la bataille à Israël en Réphidim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Et Moïse dit à Josué: choisis-nous des hommes, et sors pour combattre contre Hamalec, et je me tiendrai demain au sommet du coteau, et la verge de Dieu sera en ma main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Et Josué fit comme Moïse lui avait commandé, en combattant contre Hamalec; mais Moïse et Aaron et Hur montèrent au sommet du coteau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Et il arrivait que lorsque Moïse élevait sa main, Israël était alors le plus fort; mais quand il reposait sa main, alors Hamalec était le plus fort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Et les mains de Moïse étant devenues pesantes, ils prirent une pierre et la mirent sous lui, et il s’assit dessus; et Aaron et Hur soutenaient ses mains, l’un deçà, et l’autre delà; et ainsi ses mains furent fermes jusqu’au soleil couchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Josué donc défit Hamalec, et son peuple au tranchant de l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Et l’Eternel dit à Moïse: écris ceci pour mémoire dans un livre, et fais entendre à Josué que j’effacerai entièrement la mémoire d’Hamalec de dessous les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Et Moïse bâtit un autel, et le nomma: l’Eternel mon Enseigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Il dit aussi: parce que la main a été levée sur le trône de l’Eternel, l’Eternel aura toujours la guerre contre Hamalec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Or Jéthro, Sacrificateur de Madian, beau-père de Moïse, ayant appris toutes les choses que l’Eternel avait faites à Moïse, et à Israël son peuple, savoir, comment l’Eternel avait retiré Israël de l’Egypte,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Prit Séphora, la femme de Moïse, après que Moïse l’eut renvoyée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'Et les deux fils de cette femme, dont l’un s’appelait Guersom, parce, avait dit, que j’ai été voyageur dans un pays étranger;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'Et l’autre Elihézer; car, avait-il dit, le Dieu de mon père m’a été en aide, et m’a délivré de l’épée de Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Jéthro donc, beau-père de Moïse, vint à Moïse avec ses enfants et sa femme au désert, où il était campé, en la montagne de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Et il fit dire à Moïse: Jéthro ton beau-père, vient à toi, et ta femme, et ses deux fils avec elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Et Moïse sortit au-devant de son beau-père, et s’étant prosterné le baisa; et ils s’enquirent l’un de l’autre touchant leur prospérité; puis ils entrèrent dans la tente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Et Moïse récita à son beau-père toutes les choses que l’Eternel avait faites à Pharaon, et aux Egyptiens en faveur d’Israël, et toute la fatigue qu’ils avaient soufferte par le chemin, et comment l’Eternel les avait délivrés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Et Jéthro se réjouit de tout le bien que l’Eternel avait fait à Israël, parce qu’il les avait délivrés de la main des Egyptiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Puis Jéthro dit: béni soit l’Eternel, qui vous a délivrés de la main des Egyptiens, et de la main de Pharaon, qui a, dis-je, délivré le peuple de la main des Egyptiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Je connais maintenant que l’Eternel est grand par-dessus tous les Dieux, car en cela même en quoi ils se sont enorgueillis, il a eu le dessus sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Jéthro, beau-père de Moïse, prit aussi un holocauste et des sacrifices pour les offrir à Dieu; et Aaron et tous les Anciens d’Israël, vinrent pour manger du pain avec le beau-père de Moïse en la présence de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Et il arriva le lendemain, comme Moïse siégeait pour juger le peuple, et que le peuple se tenait devant Moïse, depuis le matin jusqu’au soir,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Que le beau-père de Moïse vit tout ce qu’il faisait au peuple, et il lui dit: qu’est-ce que tu fais à l’égard de ce peuple? Pourquoi es-tu assis seul, et tout le peuple se tient devant toi, depuis le matin jusqu’au soir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Et Moïse répondit à son beau-père: c’est que le peuple vient à moi pour s’enquérir de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Quand ils ont quelque affaire ils viennent à moi, et je juge entre l’un et l’autre, et leur fais entendre les ordonnances de Dieu, et ses lois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Mais le beau-père de Moïse lui dit: ce que tu fais n’est pas bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Certainement tu succomberas, toi et ce peuple qui est avec toi; car cela est trop pesant pour toi; tu ne saurais faire cela toi seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Ecoute donc mon conseil. Je te conseillerai, et Dieu sera avec toi; sois pour le peuple envers Dieu, et rapporte les causes à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Et instruis-les des ordonnances et des lois; et fais leur entendre la voie par laquelle ils auront à mArcher, et ce qu’ils auront à faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Et choisis-toi, d’entre tout le peuple, des hommes vertueux, craignant Dieu; des hommes véritables, haïssant le gain déshonnête, et les établis chefs de milliers, et chefs de centaines, et chefs de cinquantaines, et chefs de dizaines;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Et qu’ils jugent le peuple en tout temps, mais qu’ils te rapportent toutes les grandes affaires, et qu’ils jugent toutes les petites causes; ainsi ils te soulageront, et porteront une partie de la charge avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Si tu fais cela, et que Dieu te le commande, tu pourras subsister, et tout le peuple arrivera heureusement en son lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Moïse donc obéit à la parole de son beau-père, et fit tout ce qu’il lui avait dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Ainsi Moïse choisit de tout Israël des hommes vertueux, et les établit chefs sur le peuple, chefs de milliers, chefs de centaines, chefs de cinquantaines, et chefs de dizaines;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Lesquels devaient juger le peuple en tout temps, mais ils devaient rapporter à Moïse les choses difficiles, et juger de toutes les petites affaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Puis Moïse laissa partir son beau-père, qui s’en alla en son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Au premier jour du troisième mois, après que les enfants d’Israël furent sortis du pays d’Egypte, en ce même jour-là ils vinrent au désert de Sinaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Etant donc partis de Réphidim, ils vinrent au désert de Sinaï, et campèrent au désert; et Israël campa vis-à-vis de la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Et Moïse monta vers Dieu; car l’Eternel l’avait appelé de la montagne, pour lui dire: tu parleras ainsi à la maison de Jacob, et tu annonceras ceci aux enfants d’Israël:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Vous avez vu ce que j’ai fait aux Egyptiens; comment je vous ai portés comme sur des ailes d’aigle, et vous ai amenés à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Maintenant donc si vous obéissez exactement à ma voix, et si vous gardez mon alliance, vous serez aussi d’entre tous les peuples mon plus précieux joyau, quoique toute la terre m’appartienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Et vous me serez un royaume de Sacrificateurs, et une nation sainte; ce sont là les discours que tu tiendras aux enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Puis Moïse vint et appela les Anciens du peuple, et proposa devant eux toutes ces choses-là que l’Eternel lui avait commandées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Et tout le peuple répondit d’un commun accord, en disant: nous ferons tout ce que l’Eternel a dit. Et Moïse rapporta à l’Eternel toutes les paroles du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Et l’Eternel dit à Moïse: voici, je viendrai à toi dans une nuée épaisse, afin que le peuple entende quand je parlerai avec toi, et qu’il te croie aussi toujours; car Moïse avait rapporté à l’Eternel les paroles du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'L’Eternel dit aussi à Moïse: va-t’en vers le peuple, et sanctifie-les aujourd’hui et demain, et qu’ils lavent leurs vêtements;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Et qu’ils soient tout prêts pour le troisième jour, car au troisième jour l’Eternel descendra sur la montagne de Sinaï, à la vue de tout le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Or tu mettras des bornes pour le peuple tout à l’entour, et tu diras: donnez-vous garde de monter sur la montagne, et de toucher aucune de ses extrémités. Quiconque touchera la montagne, sera puni de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Aucune main ne la touchera; et certainement il sera lapidé, ou percé de flèches; soit bête, soit homme, il ne vivra point. Quand le cor sonnera en long, ils monteront vers la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Et Moïse descendit de la montagne vers le peuple, et sanctifia le peuple, et ils lavèrent leurs vêtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Et il dit au peuple: soyez tout prêts pour le troisième jour, et ne vous approchez point de vos femmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Et le troisième jour au matin, il y eut des tonnerres, et des éclairs, et une grosse nuée sur la montagne, avec un très-fort son de cor, dont tout le peuple dans le camp fut effrayé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Alors Moïse fit sortir le peuple du camp pour aller au-devant de Dieu; et ils s’arrêtèrent au pied de la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Or le mont de Sinaï était tout couvert de fumée, parce que l’Eternel y était descendu en feu; et sa fumée montait comme la fumée d’une fournaise, et toute la montagne tremblait fort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Et comme le son du cor se renforçait de plus en plus, Moïse parla, et Dieu lui répondit par une voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'L’Eternel donc étant descendu sur la montagne de Sinaï, au sommet de la montagne, appela Moïse au sommet de la montagne; et Moïse y monta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Et l’Eternel dit à Moïse: descends, somme le peuple qu’ils ne rompent point les barrières pour monter vers l’Eternel, afin de regarder; de peur qu’un grand nombre d’entre eux ne périsse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Et même que les Sacrificateurs s’approchant de l’Eternel se sanctifient, de peur qu’il n’arrive que l’Eternel se jette sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Et Moïse dit à l’Eternel: le peuple ne pourra pas monter sur la montagne de Sinaï, parce que tu nous as sommés en me disant: mets des bornes en la montagne, et la sanctifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Et l’Eternel lui dit: va, descends; puis tu monteras, toi et Aaron avec toi; mais que les Sacrificateurs et le peuple ne rompent point les bornes pour monter vers l’Eternel, de peur qu’il n’arrive qu’il se jette sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Moïse descendit donc vers le peuple, et le leur dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Alors Dieu prononça toutes ces paroles, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Je suis l’Eternel ton Dieu, qui t’ai retiré du pays d’Egypte, de la maison de servitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Tu n’auras point d’autres dieux devant ma face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Tu ne te feras point d’image taillée, ni aucune ressemblance des choses qui sont là-haut aux cieux, ni ici-bas sur la terre, ni dans les eaux sous la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Tu ne te prosterneras point devant elles, et ne les serviras point; car je suis l’Eternel ton Dieu, le Dieu Fort, qui est jaloux, punissant l’iniquité des pères sur les enfants, jusqu’à la troisième et à la quatrième génération de ceux qui me haïssent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'Et faisant miséricorde en mille générations à ceux qui m’aiment, et qui gardent mes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Tu ne prendras point le Nom de l’Eternel ton Dieu en vain; car l’Eternel ne tiendra point pour innocent, celui qui aura pris son Nom en vain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Souviens-toi du jour du repos, pour le sanctifier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Tu travailleras six jours, et tu feras toute ton oeuvre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Mais le septième jour est le repos de l’Eternel ton Dieu. Tu ne feras aucune oeuvre en ce jour-là, ni toi, ni ton fils, ni ta fille, ni ton serviteur, ni ta servante, ni ton bétail, ni ton étranger qui est dans tes portes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Car l’Eternel a fait en six jours les cieux, la terre, la mer, et tout ce qui est en eux, et s’est reposé le septième jour; c’est pourquoi l’Eternel a béni le jour du repos, et l’a sanctifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Honore ton père et ta mère, afin que tes jours soient prolongés sur la terre que l’Eternel ton Dieu te donne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Tu ne tueras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Tu ne paillarderas point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Tu ne déroberas point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Tu ne diras point faux Témoignage contre ton prochain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Tu ne convoiteras point la maison de ton prochain; tu ne convoiteras point la femme de ton prochain, ni son serviteur, ni sa servante, ni son boeuf, ni son âne, ni aucune chose qui soit à ton prochain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Or tout le peuple apercevait les tonnerres, les éclairs, le son du cor, et la montagne fumante; et le peuple voyant cela tremblait, et se tenait loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Et ils dirent à Moïse: parle, toi, avec nous, et nous écouterons; mais que Dieu ne parle point avec nous, de peur que nous ne mourions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Et Moïse dit au peuple: ne craignez point; car Dieu est venu pour vous éprouver, et afin que sa crainte soit devant vous, et que vous ne péchiez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Le peuple donc se tint loin, mais Moïse s’approcha de l’obscurité dans laquelle Dieu était.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Et l’Eternel dit à Moïse: tu diras ainsi aux enfants d’Israël: vous avez vu que je vous ai parlé des cieux:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Vous ne vous ferez point avec moi de Dieux d’argent, ni de Dieux d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Tu me feras un autel de terre, sur lequel tu sacrifieras tes holocaustes, et tes oblations de prospérités, ton menu et ton gros bétail; en quelque lieu que ce soit que je mettrai la mémoire de mon Nom, je viendrai là à toi, et je te bénirai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Que si tu me fais un autel de pierres, ne les taille point; car si tu fais passer le fer dessus, tu le souilleras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Et tu ne monteras point à mon autel par des degrés, de peur que ta nudité ne soit découverte en y montant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Ce sont ici les lois que tu leur proposeras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Si tu achètes un esclave Hébreu, il te servira six ans, et au septième il sortira pour être libre, sans rien payer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'S’il est venu avec son corps seulement, il sortira avec son corps; s’il avait une femme, sa femme sortira aussi avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Si son maître lui a donné une femme qui lui ait enfanté des fils, ou des filles, sa femme et les enfants qu’il en aura, seront à son maître, mais il sortira avec son corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Que si l’esclave dit positivement: j’aime mon maître, ma femme, et mes enfants, je ne sortirai point pour être libre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'Alors son maître le fera venir devant les Juges, et le fera approcher de la porte, ou du poteau, et son maître lui percera l’oreille avec une alêne; et il le servira à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Si quelqu’un vend sa fille pour être esclave, elle ne sortira point comme les esclaves sortent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Si elle déplaît à son maître, qui ne l’aura point fiancée, il la fera acheter; mais il n’aura pas le pouvoir de la vendre à un peuple étranger, après qu’il lui aura été infidèle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Mais s’il l’a fiancée à son fils, il fera pour elle selon le droit des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Que s’il en prend une autre pour lui, il ne retranchera rien de sa nourriture, de ses habits, et de l’amitié qui lui est due.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'S’il ne fait pas pour elle ces trois choses-là, elle sortira sans payer aucun argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Si quelqu’un frappe un homme, et qu’il en meure, on le fera mourir de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Que s’il ne lui a point dressé d’embûche, mais que Dieu l’ait fait tomber entre ses mains, je t’établirai un lieu où il s’enfuira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Mais si quelqu’un s’est élevé de propos délibéré contre son prochain, pour le tuer par finesse, tu le tireras de mon autel, afin qu’il meure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Celui qui aura frappé son père, ou sa mère, sera puni de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Si quelqu’un dérobe un homme, et le vend, ou s’il est trouvé entre ses mains, on le fera mourir de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Celui qui aura maudit son père, ou sa mère, sera puni de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Si quelques-uns ont eu querelle, et que l’un ait frappé l’autre d’une pierre, ou du poing, dont il ne soit point mort, mais qu’il soit obligé de se mettre au lit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'S’il se lève, et mArche dehors s’appuyant sur son bâton, celui qui l’aura frappé, sera absous; toutefois il le dédommagera de ce qu’il a chômé, et le fera guérir entièrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Si quelqu’un a frappé du bâton son serviteur ou sa servante, et qu’il soit mort sous sa main, on ne manquera point d’en faire punition.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Mais s’il survit un jour ou deux, on n’en fera point de punition, car c’est son argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Si des hommes se querellent, et que l’un d’eux frappe une femme enceinte, et qu’elle en accouche, s’il n’y a pas cas de mort, il sera condamné à l’amende telle que le mari de la femme la lui imposera, et il la donnera selon que les Juges en ordonneront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Mais s’il y a cas de mort, tu donneras vie pour vie,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Oeil pour oeil, dent pour dent, main pour main, pied pour pied,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Brûlure pour brûlure, plaie pour plaie, meurtrissure pour meurtrissure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Si quelqu’un frappe l’oeil de son serviteur, ou l’oeil de sa servante, et lui gâte l’oeil, il le laissera aller libre pour son oeil;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Et s’il fait tomber une dent à son serviteur, ou à sa servante, il le laissera aller libre pour sa dent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Si un boeuf heurte de sa corne un homme ou une femme, et que la personne en meure, le boeuf sera lapidé sans nulle exception, et on ne mangera point de sa chair, mais le maître du boeuf sera absous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Que si le boeuf avait auparavant accoutumé de heurter de sa corne, et que son maître en eût été averti avec protestation, et qu’il ne l’eût point renfermé, s’il tue un homme ou une femme, le boeuf sera lapidé, et on fera aussi mourir son maître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Que si on lui impose un prix pour se racheter, il donnera la rançon de sa vie, selon tout ce qui lui sera imposé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Si le boeuf heurte de sa corne un fils ou une fille, il lui sera fait selon cette même loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Si le boeuf heurte de sa corne un esclave, soit homme, soit femme, celui à qui est le boeuf donnera trente sicles d’argent au maître de l’esclave, et le boeuf sera lapidé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Si quelqu’un découvre une fosse, ou si quelqu’un creuse une fosse, et ne la couvre point, et qu’il y tombe un boeuf ou un âne,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'Le maître de la fosse donnera satisfaction, et rendra l’argent au maître du boeuf, mais la bête morte lui appartiendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Et si le boeuf de quelqu’un blesse le boeuf de son prochain, et qu’il en meure, ils vendront le boeuf vivant, et en partageront l’argent par moitié, et ils partageront aussi par moitié le boeuf mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Mais s’il est connu que le boeuf avait auparavant accoutumé de heurter de sa corne, et que le maître ne l’ait point gardé, il restituera boeuf pour boeuf; mais le boeuf mort sera pour lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Si quelqu’un dérobe un boeuf, ou un chevreau, ou un agneau, et qu’il le tue, ou le vende, il restituera cinq boeufs pour le boeuf, et quatre agneaux ou chevreaux, pour l’agneau ou pour le chevreau');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Que si le larron est trouvé en fracture, et est frappé de sorte qu’il en meure, celui qui l’aura frappé ne sera point coupable de meurtre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Mais si le soleil est levé sur lui, il sera coupable de meurtre. Il fera donc une entière restitution; et s’il n’a de quoi, il sera vendu pour son larcin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Si ce qui a été dérobé est trouvé vivant entre ses mains, soit boeuf, soit âne, soit brebis ou chèvre, il rendra le double.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Si quelqu’un fait manger un champ ou une vigne, en lâchant son bétail, qui aille paître dans le champ d’autrui, il rendra du meilleur de son champ, et du meilleur de sa vigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Si le feu sort, et trouve des épines, et que le blé qui est en tas, ou sur pied, ou le champ, soit consumé, celui qui aura allumé le feu rendra entièrement ce qui en aura été brûlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Si quelqu’un donne à son prochain de l’argent ou des vases à garder, et qu’on le dérobe de sa maison, si l’on trouve le larron, il rendra le double.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Mais si le larron ne se trouve point, on fera venir le maître de la maison devant les Juges pour jurer s’il n’a point mis sa main sur le bien de son prochain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Quand il sera question de quelque chose où il y ait prévarication, touchant un boeuf, ou un âne, ou une brebis, ou une chèvre, ou un vêtement, même touchant toute chose perdue, dont quelqu’un dira qu’elle lui appartient, la cause des deux parties viendra devant les Juges; et celui que les Juges auront condamné, rendra le double à son prochain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Si quelqu’un donne à garder à son prochain un âne, un boeuf, quelque menue ou grosse bête, et qu’elle meure, ou qu’elle se soit cassé quelque membre, ou qu’on l’ait emmenée sans que personne l’ait vu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Le jurement de l’Eternel interviendra entre les deux parties, pour savoir s’il n’a point mis sa main sur le bien de son prochain, et le maître de la bête se contentera du serment, et l’autre ne la rendra point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Mais s’il est vrai qu’elle lui ait été dérobée, il la rendra à son maître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'S’il est vrai qu’elle ait été déchirée par les bêtes sauvages, il lui en apportera des marques, et il ne rendra point ce qui a été déchiré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Si quelqu’un a emprunté de son prochain quelque bête, et qu’elle se casse quelque membre, ou qu’elle meure, son maître n’y étant point présent, il ne manquera pas de la rendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Mais si son maître est avec lui, il ne la rendra point; si elle a été louée, on payera seulement son louage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Si quelqu’un suborne une vierge non fiancée, et couche avec elle, il faut qu’il la dote, la prenant pour femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Mais si le père de la fille refuse absolument de la lui donner, il lui comptera autant d’argent qu’on en donne pour la dot des vierges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Tu ne laisseras point vivre la sorcière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Celui qui aura eu la compagnie d’une bête, sera puni de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Celui qui sacrifie à d’autres Dieux, qu’à l’Eternel seul, sera détruit à la façon de l’interdit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Tu ne fouleras ni n’opprimeras point l’étranger; car vous avez été étrangers au pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Vous n’affligerez point la veuve ni l’orphelin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Si vous les affligez en quoi que ce soit, et qu’ils crient à moi, certainement j’entendrai leur cri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Et ma colère s’embrasera, et je vous ferai mourir par l’épée, et vos femmes seront veuves, et vos enfants orphelins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Si tu prêtes de l’argent à mon peuple, au pauvre qui est avec toi, tu ne te comporteras point avec lui en usurier; vous ne mettrez point sur lui d’usure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Si tu prends en gage le vêtement de ton prochain, tu le lui rendras avant que le soleil soit couché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Car c’est sa seule couverture, c’est son vêtement pour couvrir sa peau; où coucherait-il? S’il arrive donc qu’il crie à moi, je l’entendrai; car je suis miséricordieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Tu ne médiras point des Juges, et tu ne maudiras point le Prince de ton peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Tu ne différeras point à m’offrir de ton abondance, et de tes liqueurs; tu me donneras le premier-né de tes fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Tu feras la même chose de ta vache, de ta brebis, et de ta chèvre. Il sera sept jours avec sa mère, et le huitième jour tu me le donneras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Vous me serez saints; et vous ne mangerez point de la chair déchirée aux champs, mais vous la jetterez aux chiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Tu ne lèveras point de faux bruit, et tu ne te joindras point au méchant pour être témoin, afin que violence soit faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Tu ne suivras point la multitude pour mal faire; et tu ne répondras point dans un procès en sorte que tu te détournes après plusieurs pour pervertir le droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Tu n’honoreras point le pauvre en son procès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Si tu rencontres le boeuf de ton ennemi, ou son âne égaré, tu ne manqueras point de le lui ramener.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Si tu vois l’âne de celui qui te hait, abattu sous sa charge, tu t’arrêteras pour le secourir, et tu ne manqueras pas de l’aider.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Tu ne pervertiras point le droit de l’indigent qui est au milieu de toi, dans son procès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Tu t’éloigneras de toute parole fausse, et tu ne feras point mourir l’innocent et le juste; car je ne justifierai point le méchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Tu ne prendras point de présent; car le présent aveugle les plus éclairés, et pervertit les paroles des justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Tu n’opprimeras point l’étranger; car vous savez ce que c’est que d’être étrangers; parce que vous avez été étrangers au pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Pendant six ans tu sèmeras ta terre, et en recueilleras le revenu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Mais en la septième année tu lui donneras du relâche, et la laisseras reposer, afin que les pauvres de ton peuple en mangent, et que les bêtes des champs mangent ce qui restera; tu en feras de même de ta vigne, et de tes oliviers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Tu travailleras six jours; mais tu te reposeras au septième jour, afin que ton boeuf et ton âne se reposent, et que le fils de ta servante, et l’étranger reprennent courage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Vous prendrez garde à toutes les choses, que je vous ai commandées. Vous ne ferez point mention du nom des Dieux étrangers; on ne l’entendra point de ta bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Trois fois l’an tu me célébreras une fête solennelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Tu garderas la fête solennelle des pains sans levain; tu mangeras des pains sans levain pendant sept jours, comme je t’ai commandé, en la saison et au mois que les épis mûrissent; car en ce mois-là tu es sorti d’Egypte; et nul ne se présentera devant ma face à vide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Et la fête solennelle de la moisson des premiers fruits de ton travail, de ce que tu auras semé au champ; et la fête solennelle de la récolte, après la fin de l’année, quand tu auras recueilli du champ les fruits de ton travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Trois fois l’an tous les mâles d’entre vous se présenteront devant le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Tu ne sacrifieras point le sang de mon sacrifice avec du pain levé; et la graisse de ma fête solennelle ne passera point la nuit jusqu’au matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Tu apporteras en la maison de l’Eternel ton Dieu les prémices des premiers fruits de ta terre. Tu ne feras point cuire le chevreau dans le lait de sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Voici, j’envoie un Ange devant toi, afin qu’il te garde dans le chemin, et qu’il t’introduise au lieu que je t’ai préparé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Donne-toi de garde de provoquer sa colère, et écoute sa voix, et ne l’irrite point; car il ne pardonnera point votre péché; parce que mon Nom est en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Mais si tu écoutes attentivement sa voix, et si tu fais tout ce que je te dirai, je serai l’ennemi de tes ennemis, et j’affligerai ceux qui t’affligeront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Car mon Ange mArchera devant toi, et t’introduira au pays des Amorrhéens, des Héthiens, des Phérésiens, des Chananéens, des Héviens, et des Jébusiens, et je les exterminerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Tu ne te prosterneras point devant leurs Dieux, et tu ne les serviras point, et tu ne feras point selon leurs oeuvres, mais tu les détruiras entièrement, et tu briseras entièrement leurs statues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Vous servirez l’Eternel votre Dieu; et il bénira ton pain et tes eaux; et j’ôterai les maladies du milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Il n’y aura point en ton pays de femelle qui avorte, ou qui soit stérile; j’accomplirai le nombre de tes jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'J’enverrai la terreur de mon Nom devant toi, et j’effrayerai tout peuple vers lequel tu arriveras, et je ferai que tous tes ennemis tourneront le dos devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Et j’enverrai des frelons devant toi, qui chasseront les Héviens, les Chananéens, et les Héthiens, de devant ta face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Je ne les chasserai point de devant ta face en une année, de peur que le pays ne devienne un désert, et que les bêtes des champs ne se multiplie contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Mais je les chasserai peu à peu de devant toi, jusqu’à ce que tu te sois accru, et que tu possèdes le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Et je mettrai des bornes depuis la mer rouge, jusqu’à la mer des Philistins, et depuis le désert jusqu’au fleuve; car je livrerai entre tes mains les habitants du pays, et je les chasserai de devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Tu ne traiteras point d’alliance avec eux, ni avec leurs Dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Ils n’habiteront point en ton pays, de peur qu’ils ne te fassent pécher contre moi; car tu servirais leurs Dieux; et cela te serait en piège.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Puis il dit à Moïse: monte vers l’Eternel, toi et Aaron, Nadab et Abihu, et soixante et dix des Anciens d’Israël; et vous vous prosternerez de loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Et Moïse s’approchera seul de l’Eternel, mais eux ne s’en approcheront point, et le peuple ne montera point avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Alors Moïse vint, et récita au peuple toutes les paroles de l’Eternel, et toutes ses lois, et tout le peuple répondit tout d’une voix, et dit: Nous ferons toutes les choses que l’Eternel a dites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Or Moïse écrivit toutes les paroles de l’Eternel, et s’étant levé de bon matin, il bâtit un autel au bas de la montagne, et dressa pour monument douze pierres pour les douze Tribus d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Et il envoya des jeunes hommes des enfants d’Israël qui offrirent des holocaustes, et qui sacrifièrent des veaux à l’Eternel, en sacrifices de prospérités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Et Moïse prit la moitié du sang, et le mit dans des bassins, et répandit l’autre moitié sur l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Ensuite il prit le livre de l’alliance, et le lut, le peuple l’écoutant, qui dit: Nous ferons tout ce que l’Eternel a dit, et nous obéirons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Moïse donc prit le sang, et le répandit sur le peuple, en disant: Voici le sang de l’alliance que l’Eternel a traitée avec vous, selon toutes ces paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Puis Moïse, Aaron, Nadab, Abihu, et les soixante et dix Anciens d’Israël montèrent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Et ils virent le Dieu d’Israël, et sous ses pieds comme un ouvrage de carreaux de saphir, qui ressemblait au ciel lorsqu’il est serein.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Et il ne mit point sa main sur ceux qui avaient été choisis d’entre les enfants d’Israël; ainsi ils virent Dieu, et ils mangèrent et burent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Et l’Eternel dit à Moïse: monte vers moi sur la montagne, et demeure là; et je te donnerai des tables de pierre, et la loi et les commandements que j’ai écrits, pour les enseigner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Alors Moïse se leva avec Josué qui le servait; et Moïse monta sur la montagne de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Et il dit aux Anciens d’Israël: Demeurez ici en nous attendant; jusqu’à ce que nous retournions vers vous; et voici, Aaron et Hur seront avec vous; quiconque aura quelque affaire, qu’il s’adresse à eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Moïse donc monta sur la montagne, et une nuée couvrit la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Et la gloire de l’Eternel demeura sur la montagne de Sinaï, et la nuée la couvrit pendant six jours; et au septième jour il appela Moïse au milieu de la nuée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Et ce qu’on voyait de la gloire de l’Eternel au sommet de la montagne, était comme un feu consumant, les enfants d’Israël le voyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Et Moïse entra dans la nuée, et monta sur la montagne; et Moïse fut sur la montagne quarante jours et quarante nuits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Parle aux enfants d’Israël, et qu’on prenne une offrande pour moi. Vous prendrez mon offrande de tout homme, dont le coeur me l’offrira volontairement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Et c’est ici l’offrande que vous prendrez d’eux, de l’or, de l’argent, de l’airain,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'De la pourpre, de l’écarlate, du cramoisi, du fin lin, des poils de chèvres,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'Des peaux de moutons teintes en rouge, des peaux de taissons, du bois de Sittim,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'De l’huile pour le luminaire, des odeurs aromatiques pour l’huile de l’onction, des drogues pour le parfum,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Des pierres d’Onyx, et des pierres de remplages pour l’Ephod et pour le Pectoral,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Et ils me feront un Sanctuaire, et j’habiterai au milieu d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Ils le feront conformément à tout ce que je te vais montrer, selon le patron du pavillon, et selon le patron de tous ses ustensiles; vous le ferez donc ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Et ils feront une Arche de bois de Sittim; et sa longueur sera de deux coudées et demie, et sa largeur d’une coudée et demie, et sa hauteur d’une coudée et demie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Et tu la couvriras de pur or, tu l’ en couvriras par dehors et par-dedans; et tu feras sur elle un couronnement d’or tout autour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Et tu fondras pour elle quatre anneaux d’or, que tu mettras à ses quatre coins, deux anneaux à l’un de ses côtés, et deux autres à l’autre côté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Tu feras aussi des barres de bois de Sittim, et tu les couvriras d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Puis tu feras entrer les barres dans les anneaux aux côtés de l’Arche, pour porter l’Arche avec elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Les barres seront dans les anneaux de l’Arche, et on ne les en tirera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Et tu mettras dans l’Arche le Témoignage que je te donnerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Tu feras aussi un Propitiatoire de pur or, dont la longueur sera de deux coudées et demie, et la largeur d’une coudée et demie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Et tu feras deux Chérubins d’or; tu les feras d’ouvrage étendu au marteau, tiré des deux bouts du Propitiatoire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Fais donc un Chérubin tiré du bout de deçà, et l’autre Chérubin du bout de delà: vous ferez les Chérubins tirés du Propitiatoire sur ses deux bouts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Et les Chérubins étendront les ailes en haut, couvrant de leurs ailes le Propitiatoire, et leurs faces seront vis-à-vis l’une de l’autre; et le regard des Chérubins sera vers le Propitiatoire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Et tu poseras le Propitiatoire au-dessus de l’Arche, et tu mettras dans l’Arche le Témoignage que je te donnerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Et je me trouverai là avec toi, et je te dirai de dessus le Propitiatoire, d’entre les deux Chérubins qui seront sur l’Arche du Témoignage, toutes les choses que je te commanderai pour les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Tu feras aussi une table de bois de Sittim: sa longueur sera de deux coudées, et sa largeur d’une coudée, et sa hauteur d’une coudée et demie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Tu la couvriras de pur or, et tu lui feras un couronnement d’or à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Tu lui feras aussi à l’entour une clôture d’une paume, et tout autour de sa clôture tu feras un couronnement d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Tu lui feras aussi quatre anneaux d’or, que tu mettras aux quatre coins, qui seront à ses quatre pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Les anneaux seront à l’endroit de la clôture, afin d’y mettre les barres pour porter la table.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Tu feras les barres de bois de Sittim, et tu les couvriras d’or, et on portera la table avec elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Tu feras aussi ses plats, ses tasses, ses gobelets, et ses bassins, avec lesquels on fera les aspersions; tu les feras de pur or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Et tu mettras sur cette table le pain de proposition, continuellement devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Tu feras aussi un chandelier de pur or; le chandelier sera étendu au marteau; sa tige et ses branches, ses plats, ses pommeaux, et ses fleurs, seront tirés de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Six branches sortiront de ses côtés; trois branches d’un côté du chandelier, et trois autres de l’autre côté du chandelier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Il y aura en une des branches trois petits plats en forme d’amande, un pommeau et une fleur; en l’autre branche trois petits plats en forme d’amande, un pommeau et une fleur; il en sera de même des six branches procédant du chandelier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Il y aura aussi au chandelier quatre petits plats en forme d’amande, ses pommeaux et ses fleurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Un pommeau sous deux branches tirées du chandelier, un pommeau sous deux autres branches tirées de lui, et un pommeau sous deux autres branches tirées de lui; il en sera de même des six branches procédant du chandelier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Leurs pommeaux et leurs branches seront tirés de lui, et tout le chandelier sera un seul ouvrage étendu au marteau, et de pur or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Tu feras aussi ses sept lampes, et on les allumera, afin qu’elles éclairent vis-à-vis du chandelier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Et ses mouchettes, et ses creuseaux seront de pur or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'On le fera avec tous ses ustensiles d’un talent de pur or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Regarde donc, et fais selon le patron qui t’est montré en la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Tu feras aussi le pavillon de dix rouleaux de fin lin retors, de pourpre, d’écarlate, et de cramoisi; et tu les feras semés de Chérubins d’un ouvrage exquis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'La longueur d’un rouleau sera de vingt-huit coudées, et la largeur du même rouleau de quatre coudées; tous les rouleaux auront une même mesure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Cinq de ces rouleaux seront joints l’un à l’autre, et les cinq autres seront aussi joints l’un à l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Fais aussi des lacets de pourpre sur le bord d’un rouleau, au bord du premier assemblage; et tu feras la même chose au bord du dernier rouleau dans l’autre assemblage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Tu feras donc cinquante lacets en un rouleau, et tu feras cinquante lacets au bord du rouleau qui est dans le second assemblage; les lacets seront vis-à- vis l’un de l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Tu feras aussi cinquante crochets d’or, et tu attacheras les rouleaux l’un à l’autre avec les crochets; ainsi sera fait un pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Tu feras aussi des rouleaux de poils de chèvres pour servir de Tabernacle par-dessus le pavillon; tu feras onze de ces rouleaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'La longueur d’un rouleau sera de trente coudées, et la largeur du même rouleau sera de quatre coudées; les onze rouleaux auront une même mesure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Puis tu joindras cinq rouleaux à part, et six rouleaux à part; mais tu redoubleras le sixième rouleau sur le devant du Tabernacle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Tu feras aussi cinquante lacets sur le bord de l’un des rouleaux, savoir au dernier qui est accouplé, et cinquante lacets sur le bord de l’autre rouleau qui est accouplé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Tu feras aussi cinquante crochets d’airain, et tu feras entrer les crochets dans les lacets; et tu assembleras ainsi le Tabernacle, tellement qu’il ne soit qu’un.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Mais ce qu’il y aura de surplus du rouleau du Tabernacle, savoir la moitié du rouleau qui demeurera de reste, flottera sur le derrière du pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Et une coudée deçà, et une coudée delà, de ce qui sera de surplus dans la longueur des rouleaux du Tabernacle, flottera aux côtés du pavillon çà et là, pour le couvrir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Tu feras aussi pour ce Tabernacle une couverture de peaux de moutons teintes en rouge, et une couverture de peaux de taissons par-dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Et tu feras pour le pavillon des ais de bois de Sittim, qu’on fera tenir debout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'La longueur d’un ais sera de dix coudées, et la largeur du même ais d’une coudée et demie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Il y aura deux tenons dans chaque ais, en façon d’échelons l’un après l’autre; et tu feras ainsi de tous les ais du pavillon,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Tu feras donc les ais du pavillon, savoir vingt ais au côté qui regarde vers le Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Et au-dessous des vingt ais tu feras quarante soubassements d’argent; deux soubassements sous un ais pour ses deux tenons, et deux soubassements sous l’autre ais pour ses deux tenons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Et vingt ais à l’autre côté du pavillon, du côté du Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'Et leurs quarante soubassements seront d’argent, deux soubassements sous un ais, et deux soubassements sous l’autre ais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Et pour le fond du pavillon vers l’Occident, tu feras six ais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Tu feras aussi deux ais pour les encoignures du pavillon, aux deux côtés du fond.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Et ils seront égaux par le bas, et ils seront joints et unis par le haut avec un anneau; il en sera de même des deux ais qui seront aux deux encoignures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Il y aura donc huit ais, et seize soubassements d’argent; deux soubassements sous un ais, et deux soubassements sous l’autre ais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Après cela tu feras cinq barres de bois de Sittim, pour les ais d’un des côtés du pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'Pareillement tu feras cinq barres, pour les ais de l’autre côté du pavillon; et cinq barres pour les ais du côté du pavillon, pour le fond, vers le côté de l’Occident.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Et la barre du milieu sera au milieu des ais, courant d’un bout à l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Tu couvriras aussi d’or les ais, et tu feras leurs anneaux d’or, pour mettre les barres, et tu couvriras d’or les barres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Tu dresseras donc le Tabernacle selon la forme qui t’en a été montrée en la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Et tu feras un voile de pourpre, d’écarlate, de cramoisi, et de fin lin retors; on le fera d’ouvrage exquis, semé de Chérubins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Et tu le mettras sur quatre piliers de bois de Sittim couverts d’or, ayant leurs crochets d’or, et ils seront sur quatre soubassements d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Puis tu mettras le voile sous les crochets, et tu feras entrer là dedans, c’est-à-dire, au-dedans du voile, l’Arche du Témoignage, et ce voile vous fera la séparation d’entre le lieu Saint et le lieu Très-saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Et tu poseras le Propitiatoire sur l’Arche du Témoignage, dans le lieu Très- saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Et tu mettras la table au dehors de ce voile, et le chandelier vis-à-vis de la table, au côté du pavillon, vers le Midi; et tu placeras la table au côté du Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Et à l’entrée du Tabernacle tu feras une tapisserie de pourpre, d’écarlate, de cramoisi et de fin lin retors, d’ouvrage de broderie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Tu feras aussi pour cette tapisserie cinq piliers de bois de Sittim, que tu couvriras d’or, et leurs crochets seront d’or; et tu fondras pour eux cinq soubassements d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Tu feras aussi un autel de bois de Sittim, ayant cinq coudées de long, et cinq coudées de large; l’autel sera carré, et sa hauteur sera de trois coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Tu feras ses cornes à ses quatre coins; ses cornes seront tirées de lui, et tu le couvriras d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Tu feras ses chaudrons pour recevoir ses cendres, et ses racloirs, et ses bassins, et ses fourchettes, et ses encensoirs; tu feras tous ses ustensiles d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Tu lui feras une grille d’airain en forme de treillis, et tu feras au treillis quatre anneaux d’airain à ses quatre coins;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Et tu le mettras au-dessous de l’enceinte de l’autel en bas, et le treillis s’étendra jusqu’au milieu de l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Tu feras aussi des barres pour l’autel, des barres de bois de Sittim, et tu les couvriras d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Et on fera passer ses barres dans les anneaux; les barres seront aux deux côtés de l’autel pour le porter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Tu le feras d’ais, et il sera creux; ils le feront ainsi qu’il t’a été montré en la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Tu feras aussi le parvis du pavillon, au côté qui regarde vers le Midi; les courtines du parvis seront de fin lin retors; la longueur de l’un des côtés sera de cent coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Il y aura vingt piliers avec leurs vingt soubassements d’airain; mais les crochets des piliers et leurs filets seront d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Ainsi au côté du Septentrion il y aura en longueur cent coudées de courtines, et ses vingt piliers avec leurs vingt soubassements d’airain; mais les crochets des piliers avec leurs filets seront d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'La largeur du parvis du côté de l’Occident, sera de cinquante coudées de courtines, qui auront dix piliers, avec leurs dix soubassements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Et la largeur du parvis du côté de l’Orient, directement vers le levant, aura cinquante coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'A l’un des côtés il y aura quinze coudées de courtines, avec leurs trois piliers et leurs trois soubassements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Et à l’autre côté, quinze coudées de courtines, avec leurs trois piliers et leurs trois soubassements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Il y aura aussi pour la porte du parvis une tapisserie de vingt coudées, faite de pourpre, d’écarlate, de cramoisi, et de fin lin retors, ouvrage de broderie, à quatre piliers et quatre soubassements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Tous les piliers du parvis seront ceints à l’entour d’un filet d’argent, et leurs crochets seront d’argent, mais leurs soubassements seront d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'La longueur du parvis sera de cent coudées, et la largeur de cinquante, de chaque côté; et la hauteur de cinq coudées. Il sera de fin lin retors, et les soubassements des piliers seront d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Que tous les ustensiles du pavillon, pour tout son service, et tous ses pieux, avec les pieux du parvis, soient d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Tu commanderas aussi aux enfants d’Israël, qu’ils t’apportent de l’huile d’olive vierge pour le luminaire, afin de faire luire les lampes continuellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Aaron avec ses fils les arrangera en la présence de l’Eternel, depuis le soir jusqu’au matin, dans le Tabernacle d’assignation, hors du voile qui est devant le Témoignage; ce sera une ordonnance perpétuelle pour les enfants d’Israël, dans leurs âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Et toi fais approcher de toi Aaron ton frère, et ses fils avec lui, d’entre les enfants d’Israël, pour m’exercer la Sacrificature, savoir Aaron, et Nadab, Abihu, Eléazar et Ithamar, fils d’Aaron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Et tu feras à Aaron ton frère de saints vêtements pour gloire et pour ornement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Et tu parleras à tous les hommes d’esprit, à chacun de ceux que j’ai remplis de l’esprit de science, afin qu’ils fassent des vêtements à Aaron pour le sanctifier, afin qu’il m’exerce la Sacrificature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Et ce sont ici les vêtements qu’ils feront; le Pectoral, l’Ephod, le Rochet, la Tunique, qui tienne serré, la Tiare, et le Baudrier; ils feront donc les saints vêtements à Aaron ton frère, et à ses fils, pour m’exercer la Sacrificature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Et ils prendront de l’or, de la pourpre, de l’écarlate, du cramoisi, et du fin lin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Et ils feront l’Ephod d’or, de pourpre, d’écarlate, de cramoisi, et de fin lin retors, d’un ouvrage exquis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Il aura deux épaulières qui se joindront par les deux bouts, et il sera ainsi joint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Le ceinturon exquis dont il sera ceint, et qui sera par-dessus, sera de même ouvrage, et tiré de lui, étant d’or, de pourpre, d’écarlate, de cramoisi, et de fin lin retors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Et tu prendras deux pierres d’Onyx, et tu graveras sur elles les noms des enfants d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Six de leurs noms sur une pierre et les six noms des autres, sur l’autre pierre, selon leur naissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Tu graveras sur les deux pierres, d’ouvrage de lapidaire, de gravure de cachet, les noms des enfants d’Israël, et tu les enchâsseras dans des chatons d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Et tu mettras les deux pierres sur les épaulières de l’Ephod, afin qu’elles soient des pierres de mémorial pour les enfants d’Israël; car Aaron portera leurs noms sur ses deux épaules devant l’Eternel, pour mémorial.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Tu feras aussi des crampons d’or;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'Et deux chaînettes de fin or à bouts, en façon de cordon, et tu mettras les chaînettes ainsi faites à cordon dans les crampons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Tu feras aussi le Pectoral de jugement d’un ouvrage exquis, comme l’ouvrage de l’Ephod, d’or, de pourpre, d’écarlate, de cramoisi, et de fin lin retors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Il sera carré et double; et sa longueur sera d’une paume, et sa largeur d’une paume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Et tu le rempliras de remplage de pierrerie, à quatre rangées de pierres précieuses. A la première rangée on mettra une Sardoine, une Topaze, et une Emeraude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'Et à la seconde rangée, une Escarboucle, un Saphir, et un Jaspe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'Et à la troisième rangée, un Ligure, une Agathe, et une Améthyste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'Et à la quatrième rangée, un Chrysolithe, un Onyx et un Béryl, qui seront enchâssés dans de l’or, selon leurs remplages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Et ces pierres-là seront selon les noms des enfants d’Israël, douze selon leurs noms, chacune d’elles gravée de gravure de cachet, selon le nom qu’elle en doit porter, et elles seront pour les douze Tribus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Tu feras donc pour le Pectoral des chaînettes à bouts, en façon de cordon, qui seront de pur or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Et tu feras sur le Pectoral deux anneaux d’or, et tu mettras les deux anneaux aux deux bouts du Pectoral.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Et tu mettras les deux chaînettes d’or faites à cordon, dans les deux anneaux à l’extrémité du Pectoral.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Et tu mettras les deux autres bouts des deux chaînettes faites à cordon, aux deux crampons, et tu les mettras sur les épaulières de l’Ephod, sur le devant de l’Ephod.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Tu feras aussi deux autres anneaux d’or, que tu mettras aux deux autres bouts du Pectoral, sur le bord qui sera du côté de l’Ephod en dedans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Et tu feras deux autres anneaux d’or, que tu mettras aux deux épaulières de l’Ephod par le bas, répondant sur le devant, à l’endroit où il se joint, au- dessus du ceinturon exquis de l’Ephod.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Et ils joindront le Pectoral élevé par ses anneaux, aux anneaux de l’Ephod, avec un cordon de pourpre, afin qu’il tienne au-dessus du ceinturon exquis de l’Ephod, et que le Pectoral ne bouge point de dessus l’Ephod.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Ainsi Aaron portera sur son coeur les noms des enfants d’Israël au Pectoral de jugement, quand il entrera dans le lieu Saint, pour mémorial devant l’Eternel, continuellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Et tu mettras sur le Pectoral de jugement l’Urim et le Thummim, qui seront sur le coeur d’Aaron, quand il viendra devant l’Eternel; et Aaron portera le jugement des enfants d’Israël sur son coeur devant l’Eternel, continuellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Tu feras aussi le Rochet de l’Ephod entièrement de pourpre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Et l’ouverture où passe la tête sera au milieu, et il y aura un ourlet à son ouverture tout autour, d’ouvrage tissu, comme l’ouverture d’un corselet, afin qu’il ne se déchire point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Et tu feras à ses bords des grenades de pourpre, d’écarlate, et de cramoisi tout autour, et des clochettes d’or entre elles tout autour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Une clochette d’or, puis une grenade; une clochette d’or, puis une grenade; aux bords du Rochet tout autour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Et Aaron en sera revêtu quand il fera le service, et on en entendra le son lorsqu’il entrera dans le lieu Saint devant l’Eternel, et quand il en sortira, afin qu’il ne meure pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Et tu feras une lame de pur or, sur laquelle tu graveras ces mots, de gravure de cachet: LA SAINTETÉ A L’ETERNEL.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Laquelle tu poseras avec un cordon de pourpre, et elle sera sur la Tiare, répondant sur le devant de la Tiare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Et elle sera sur le front d’Aaron; et Aaron portera l’iniquité des saintes offrandes que les enfants d’Israël auront offertes, dans tous les dons de leurs saintes offrandes, et elle sera continuellement sur son front, pour les rendre agréables devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Tu feras aussi une chemise de fin lin qui s’appliquera sur le corps, et tu feras aussi la Tiare de fin lin; mais tu feras le baudrier d’ouvrage de broderie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Tu feras aussi aux enfants d’Aaron des chemises, des baudriers, et des calottes pour leur gloire et pour leur ornement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Et tu en revêtiras Aaron ton frère, et ses fils avec lui; tu les oindras, tu les consacreras et tu les sanctifieras; puis ils m’exerceront la Sacrificature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Et tu leur feras des caleçons de lin, pour couvrir leur nudité, qui tiendront depuis les reins jusqu’au bas des cuisses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Et Aaron et ses fils seront ainsi habillés quand ils entreront au Tabernacle d’assignation, ou quand ils approcheront de l’autel pour faire le service dans le lieu Saint; et ils ne porteront point la peine d’aucune iniquité, et ne mourront point. Ce sera une ordonnance perpétuelle pour lui et pour sa postérité après lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Or c’est ici ce que tu leur feras, quand tu les sanctifieras pour m’exercer la Sacrificature: prends un veau du troupeau, et deux béliers sans tare;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'Et des pains sans levain, et des gâteaux sans levain pétris à l’huile, et des beignets sans levain, oints d’huile; et tu les feras de fine farine de froment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Tu les mettras dans une corbeille, et tu les présenteras dans la corbeille; tu présenteras aussi le veau et les deux moutons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Puis tu feras approcher Aaron et ses fils à l’entrée du Tabernacle d’assignation, et tu les laveras avec de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Ensuite tu prendras les vêtements, et tu feras vêtir à Aaron la chemise et le Rochet de l’Ephod, l’Ephod, et le Pectoral, et tu le ceindras par-dessus avec le ceinturon exquis de l’Ephod.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Puis tu mettras sur sa tête la Tiare, et la couronne de sainteté sur la Tiare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Et tu prendras l’huile de l’onction, et la répandras sur sa tête; et tu l’oindras ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Puis tu feras approcher ses fils, et tu leur feras vêtir les chemises,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Et tu les ceindras du baudrier, Aaron, dis-je, et ses fils, et tu leur attacheras des calottes; et ils posséderont la Sacrificature par ordonnance perpétuelle; et tu consacreras ainsi Aaron et ses fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Et tu feras approcher le veau devant le Tabernacle d’assignation, et Aaron et ses fils poseront leurs mains sur la tête du veau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Et tu égorgeras le veau devant l’Eternel, à l’entrée du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Puis tu prendras du sang du veau, et le mettras avec ton doigt sur les cornes de l’autel, et tu répandras tout le reste du sang au pied de l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Tu prendras aussi toute la graisse qui couvre les entrailles, et la taie qui est sur le foie, et les deux rognons, et la graisse qui est sur eux, et tu les feras fumer sur l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Mais tu brûleras au feu la chair du veau, sa peau, et sa fiente, hors du camp; c’est un sacrifice pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Puis tu prendras l’un des béliers, et Aaron et ses fils poseront leurs mains sur la tête du bélier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Puis tu égorgeras le bélier, et prenant son sang, tu le répandras sur l’autel tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Après tu couperas le bélier par pièces, et ayant lavé ses entrailles et ses jambes, tu les mettras sur ses pièces et sur sa tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Et tu feras fumer tout le bélier sur l’autel; c’est un holocauste à l’Eternel, c’est une suave odeur; une offrande faite par feu à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Puis tu prendras l’autre bélier, et Aaron et ses fils mettront leurs mains sur sa tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Et tu égorgeras le bélier, et prenant de son sang, tu le mettras sur le mol de l’oreille droite d’Aaron, et sur le mol de l’oreille droite de ses fils, et sur le pouce de leur main droite, et sur le gros orteil de leur pied droit, et tu répandras le reste du sang sur l’autel tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Et tu prendras du sang qui sera sur l’autel, et de l’huile de l’onction, et tu en feras aspersion sur Aaron, et sur ses vêtements, sur ses fils, et sur les vêtements de ses fils avec lui; ainsi et lui, et ses vêtements, et ses fils, et les vêtements de ses fils, seront sanctifiés avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Tu prendras aussi la graisse du bélier, et la queue, et la graisse qui couvre les entrailles, la taie du foie, les deux rognons, et la graisse qui est dessus, et l’épaule droite; car c’est le bélier des consécrations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Tu prendras aussi un pain, un gâteau à l’huile, et un beignet de la corbeille où seront ces choses sans levain, laquelle sera devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Et tu mettras toutes ces choses sur les paumes des mains d’Aaron, et sur les paumes des mains de ses fils, et tu les tournoieras en offrande tournoyée devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Puis les recevant de leurs mains, tu les feras fumer sur l’autel, sur l’holocauste, pour être une odeur agréable devant l’Eternel; c’est un sacrifice fait par feu à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Tu prendras aussi la poitrine du bélier des consécrations, qui est pour Aaron, et tu la tournoieras en offrande tournoyée, devant l’Eternel; et elle sera pour ta part.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Tu sanctifieras donc la poitrine de l’offrande tournoyée, et l’épaule de l’offrande élevée, tant ce qui aura été tournoyé, que ce qui aura été élevé du bélier des consécrations, de ce qui est pour Aaron, et de ce qui est pour ses fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Et ceci sera une ordonnance perpétuelle pour Aaron et pour ses fils, de ce qui sera offert par les enfants d’Israël; car c’est une offrande élevée. Quand il y aura une offrande élevée de celles qui sont faites par les enfants d’Israël, de leurs sacrifices de prospérité, leur offrande élevée sera à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Et les saints vêtements qui seront pour Aaron, seront pour ses fils après lui, afin qu’ils soient oints et consacrés dans ces vêtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Le Sacrificateur qui succédera en sa place d’entre ses fils, et qui viendra au Tabernacle d’assignation, pour faire le service au lieu Saint, en sera revêtu durant sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Or tu prendras le bélier des consécrations, et tu feras bouillir sa chair dans un lieu saint;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Et Aaron et ses fils mangeront à l’entrée du Tabernacle d’assignation, la chair du bélier, et le pain qui sera dans la corbeille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Ils mangeront donc ces choses, par lesquelles la propitiation aura été faite, pour les consacrer et les sanctifier; mais l’étranger n’en mangera point, parce qu’elles sont saintes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Que s’il y a des restes de la chair des consécrations, et du pain jusqu’au matin, tu brûleras ces restes-là au feu; on n’en mangera point, parce que c’est une chose sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Tu feras donc ainsi à Aaron et à ses fils, selon toutes les choses que je t’ai commandées; tu les consacreras durant sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Tu sacrifieras pour le péché tous les jours un veau pour faire la propitiation, et tu offriras pour l’autel un sacrifice pour le péché en faisant propitiation pour lui, et tu l’oindras pour le sanctifier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Pendant sept jours tu feras propitiation pour l’autel, et tu le sanctifieras; et l’autel sera une chose très-sainte; tout ce qui touchera l’autel sera saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Or c’est ici ce que tu feras sur l’autel; tu offriras chaque jour continuellement deux agneaux d’un an.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Tu sacrifieras l’un des agneaux au matin, et l’autre agneau entre les deux vêpres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Avec une dixième de fine farine pétrie dans la quatrième partie d’un Hin d’huile vierge, et avec une aspersion de vin de la quatrième partie d’un Hin pour chaque agneau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Et tu sacrifieras l’autre agneau entre les deux vêpres, avec un gâteau comme au matin, et tu lui feras la même aspersion, en bonne odeur; c’est un sacrifice fait par feu à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Ce sera l’holocauste continuel en vos âges, à l’entrée du Tabernacle d’assignation devant l’Eternel, où je me trouverai avec vous pour te parler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Je me trouverai là pour les enfants d’Israël, et le Tabernacle sera sanctifié par ma gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Je sanctifierai donc le Tabernacle d’assignation et l’autel. Je sanctifierai aussi Aaron et ses fils, afin qu’ils m’exercent la Sacrificature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Et j’habiterai au milieu des enfants d’Israël, et je leur serai Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Et ils sauront que je suis l’Eternel leur Dieu, qui les ai tirés du pays d’Egypte, pour habiter au milieu d’eux. Je suis l’Eternel leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Tu feras aussi un autel pour les parfums, et tu le feras de bois de Sittim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Sa longueur sera d’une coudée, et sa largeur d’une coudée; il sera carré; mais sa hauteur sera de deux coudées, et ses cornes seront tirées de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Tu le couvriras de pur or, tant le dessus, que ses côtés tout à l’entour, et ses cornes; et tu lui feras un couronnement d’or tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Tu lui feras aussi deux anneaux d’or au-dessous de son couronnement, à ses deux côtés, lesquels tu mettras aux deux coins, pour y faire passer les barres qui serviront à le porter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Tu feras les barres de bois de Sittim, et tu les couvriras d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Et tu les mettras devant le voile, qui est au devant de l’Arche du Témoignage, à l’endroit du Propitiatoire qui est sur le Témoignage, où je me trouverai avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Et Aaron fera sur cet autel un parfum de choses aromatiques; il y fera un parfum chaque matin, quand il accommodera les lampes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Et quand Aaron allumera les lampes entre les deux vêpres, il y fera aussi le parfum, savoir le parfum continuel devant l’Eternel en vos âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Vous n’offrirez point sur cet autel aucun parfum étranger, ni d’holocauste, ni d’offrande, et vous n’y ferez aucune aspersion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Mais Aaron fera une fois l’an la propitiation sur les cornes de cet autel; il fera, dis-je, la propitiation une fois l’an sur cet autel en vos âges, avec le sang de l’oblation pour le péché, faite pour les propitiations. C’est une chose très-sainte à l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'L’Eternel parla aussi à Moïse, et lui dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Quand tu feras le dénombrement des enfants d’Israël, selon leur nombre, ils donneront chacun à l’Eternel le rachat de sa personne, quand tu en feras le dénombrement, et il n’y aura point de plaie sur eux quand tu en feras le dénombrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Tous ceux qui passeront par le dénombrement donneront un demi sicle, selon le sicle du Sanctuaire, qui est de vingt oboles; le demi sicle donc sera l’oblation que l’on donnera à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Tous ceux qui passeront par le dénombrement, depuis l’âge de vingt ans et au dessus, donneront cette oblation à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Le riche n’augmentera rien, et le pauvre ne diminuera rien du demi sicle, quand ils donneront à l’Eternel l’oblation pour faire le rachat de vos personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Tu prendras donc des enfants d’Israël l’argent des propitiations, et tu l’appliqueras à l’oeuvre du Tabernacle d’assignation, et il sera pour mémorial aux enfants d’Israël, devant l’Eternel pour faire le rachat de vos personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'L’Eternel parla encore à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Fais aussi une cuve d’airain, avec son soubassement d’airain, pour laver; et tu la mettras entre le Tabernacle d’assignation et l’autel, et tu mettras de l’eau dedans;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Et Aaron et ses fils en laveront leurs mains et leurs pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Quand ils entreront au Tabernacle d’assignation ils se laveront avec de l’eau, afin qu’ils ne meurent point, et quand ils approcheront de l’autel pour faire le service, afin de faire fumer l’offrande faite par feu à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Ils laveront donc leurs pieds et leurs mains, afin qu’ils ne meurent point; ce leur sera une ordonnance perpétuelle, tant pour Aaron que pour sa postérité en leurs âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Prends des choses aromatiques les plus exquises; de la myrrhe franche le poids de cinq cents sicles, du cinnamome odoriférant la moitié autant, c’est-à-dire, le poids de deux cent cinquante sicles, et du roseau aromatique deux cent cinquante sicles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'De la casse le poids de cinq cents sicles, selon le sicle du Sanctuaire, et un Hin d’huile d’olive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Et tu en feras de l’huile pour l’onction sainte, un oignement composé par art de parfumeur, ce sera l’huile de l’onction sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Puis tu en oindras le Tabernacle d’assignation, et l’Arche du Témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'La table et tous ses ustensiles, le chandelier et ses ustensiles, et l’autel du parfum,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'Et l’autel des holocaustes et tous ses ustensiles, la cuve et son soubassement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Ainsi tu les sanctifieras, et ils seront une chose très-sainte; tout ce qui les touchera, sera saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Tu oindras aussi Aaron et ses fils, et les sanctifieras pour m’exercer la Sacrificature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Tu parleras aussi aux enfants d’Israël, en disant: ce me sera une huile de sainte onction en vos âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'On n’en oindra point la chair d’aucun homme, et vous n’en ferez point d’autre de même composition; elle est sainte, elle vous sera sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Quiconque composera un oignement semblable, et qui en mettra sur un autre, sera retranché d’entre ses peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'L’Eternel dit aussi à Moïse: prends des drogues, savoir du Stacte, de l’Onyx, du Galbanum, le tout préparé, et de l’encens pur, le tout à poids égal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Et tu en feras un parfum aromatique selon l’art de parfumeur, et tu y mettras du sel; vous le ferez pur, et ce vous sera une chose sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Et quand tu l’auras pilé bien menu, tu en mettras au Tabernacle d’assignation devant le Témoignage, où je me trouverai avec toi. Ce vous sera une chose très-sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Et quant au parfum que tu feras, vous ne ferez point pour vous de semblable composition; ce te sera une chose sainte, à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Quiconque en aura fait de semblable pour le flairer, sera retranché d’entre ses peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Regarde, j’ai appelé par son nom Betsaléel, fils d’Uri, fils de Hur, de la Tribu de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Et je l’ai rempli de l’Esprit de Dieu, en sagesse, en intelligence, en science, et en toute sorte d’ouvrages,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Afin d’inventer des dessins pour travailler en or, en argent, et en airain;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'Dans la sculpture des pierres précieuses; pour les mettre en œuvre, et dans la menuiserie, pour travailler en toute sorte d’ouvrages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Et voici, je lui ai donné pour compagnon Aholiab fils d’Ahisamac, de la Tribu de Dan; et j’ai mis de la science au coeur de tout homme d’esprit, afin qu’ils fassent toutes les choses que je t’ai commandées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'Savoir le Tabernacle d’assignation, l’Arche du Témoignage, et le Propitiatoire qui doit être au-dessus, et tous les ustensiles du Tabernacle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'Et la table avec tous ses ustensiles; et le chandelier pur avec tous ses ustensiles; et l’autel du parfum;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'Et l’autel de l’holocauste avec tous ses ustensiles, la cuve et son soubassement;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'Et les vêtements du service; les saints vêtements d’Aaron Sacrificateur, et les vêtements de ses fils pour exercer la sacrificature;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'Et l’huile de l’onction, et le parfum des choses aromatiques pour le Sanctuaire, et ils feront toutes les choses que je t’ai commandées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'L’Eternel parla encore à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Toi aussi parle aux enfants d’Israël, en disant: certes, vous garderez mes Sabbats; car c’est un signe entre moi et vous en vos âges, afin que vous sachiez que je suis l’Eternel, qui vous sanctifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Gardez donc le Sabbat, car il vous doit être saint; quiconque le violera, sera puni de mort; quiconque, dis-je, fera aucune œuvre en ce-jour-là, sera retranché du milieu de ses peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'On travaillera six jours; mais le septième jour est le Sabbat du repos, une sainteté à l’Eternel; quiconque fera aucune œuvre au jour du repos sera puni de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Ainsi les enfants d’Israël garderont le Sabbat, pour célébrer le jour du repos en leurs âges, par une alliance perpétuelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'C’est un signe entre moi et les enfants d’Israël à perpétuité; car l’Eternel a fait en six jours les cieux et la terre, et il a cessé au septième, et s’est reposé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Et Dieu donna à Moïse, après qu’il eut achevé de parler avec lui sur la montagne de Sinaï, les deux Tables du Témoignage; Tables de pierre, écrites du doigt de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Mais le peuple voyant que Moïse tardait tant à descendre de la montagne, s’assembla vers Aaron, et ils lui dirent: lève-toi, fais-nous des dieux qui marchent devant nous, car quant à ce Moïse, cet homme qui nous a fait monter du pays d’Egypte, nous ne savons ce qui lui est arrivé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Et Aaron leur répondit: mettez en pièces les bagues d’or qui sont aux oreilles de vos femmes, de vos fils, et de vos filles, et apportez-les-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Et incontinent tout le peuple mit en pièces les bagues d’or, qui étaient à leurs oreilles, et ils les apportèrent à Aaron,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Qui les ayant reçues de leurs mains, forma l’or avec un burin, et il en fit un Veau de fonte. Et ils dirent: ce sont ici tes dieux, ô Israël, qui t’ont fait monter du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Ce qu’Aaron ayant vu, il bâtit un autel devant le Veau; et cria, en disant: demain il y aura une fête solennelle à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Ainsi ils se levèrent le lendemain dès le matin, et ils offrirent des holocaustes, et présentèrent des sacrifices de prospérité; et le peuple s’assit pour manger et pour boire, puis ils se levèrent pour jouer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Alors l’Eternel dit à Moïse: va, descends; car ton peuple que tu as fait monter du pays d’Egypte, s’est corrompu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Ils se sont bien-tôt détournés de la voie que je leur avais commandée, ils se sont fait un Veau de fonte, et se sont prosternés devant lui, et lui ont sacrifié, et ont dit: Ce sont ici tes dieux, ô Israël, qui t’ont fait monter du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'L’Eternel dit encore à Moïse: j’ai regardé ce peuple, et voici, c’est un peuple de col roide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Or maintenant laisse-moi, et ma colère s’embrasera contr’eux, et je les consumerai; mais je te ferai devenir une grande nation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Alors Moïse supplia l’Eternel son Dieu, et dit: ô Eternel, pourquoi ta colère s’embraserait-elle contre ton peuple, que tu as retiré du pays d’Egypte par une grande puissance, et par main forte?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Pourquoi diraient les Egyptiens: il les a retirés dans de mauvaises vues pour les tuer sur les montagnes, et pour les consumer de dessus la terre? Reviens de l’ardeur de ta colère, et te repens de ce mal que tu veux faire à ton peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Souviens-toi d’Abraham, d’Isaac et d’Israël tes serviteurs, auxquels tu as juré par toi-même, en leur disant: je multiplierai votre postérité comme les étoiles des cieux, et je donnerai à votre postérité tout ce pays, dont j’ai parlé, et ils l’hériteront à jamais');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Et l’Eternel se repentit du mal qu’il avait dit qu’il ferait à son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Alors Moïse regarda, et descendit de la montagne, ayant en sa main les deux Tables du Témoignage, et les Tables étaient écrites de leurs deux côtés, écrites deçà et delà.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Et les Tables étaient l’ouvrage de Dieu, et l’écriture était de l’écriture de Dieu, gravée sur les Tables');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Et Josué, entendant la voix du peuple qui faisait un grand bruit, dit à Moïse: il y a un bruit de bataille au camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Et Moïse lui répondit: ce n’est pas une voix ni un cri de gens qui soient les plus forts, ni une voix ni un cri de gens qui soient les plus faibles; mais j’entends une voix de gens qui chantent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Et il arriva que lors que Moïse fut approché du camp, il vit le Veau et les danses; et la colère de Moïse s’embrasa, et il jeta de ses mains les Tables, et les rompit au pied de la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Il prit ensuite le Veau qu’ils avaient fait, et le brûla au feu, et le moulut jusqu’à ce qu’il fût en poudre; puis il répandit cette poudre dans de l’eau, et il en fit boire aux enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Et Moïse dit à Aaron: que t’a fait ce peuple, que tu aies fait venir sur lui un si grand péché?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Et Aaron lui répondit: que la colère de mon Seigneur ne s’embrase point, tu sais que ce peuple est porté au mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Or ils m’ont dit: fais-nous des dieux qui marchent devant nous, car quant à ce Moïse, cet homme qui nous a fait monter du pays d’Egypte, nous ne savons ce qui lui est arrivé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Alors je leur ai dit: que celui qui a de l’or, le mette en pièces; et ils me l’ont donné; et je l’ai jeté au feu, et ce Veau en est sorti.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Or Moïse vit que le peuple était dénué, car Aaron l’avait dénué pour être en opprobre parmi leurs ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Et Moïse se tenant à la porte du camp, dit: qui est pour l’Eternel; qu’il vienne vers moi? Et tous les enfants de Lévi s’assemblèrent vers lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Et il leur dit: ainsi a dit l’Eternel, le Dieu d’Israël: que chacun mette son épée à son côté, passez et repassez de porte en porte par le camp, et que chacun de vous tue son frère, son ami, et son voisin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Et les enfants de Lévi firent selon la parole de Moïse; et en ce jour-là il tomba du peuple environ trois mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Car Moïse avait dit: consacrez aujourd’hui vos mains à l’Eternel, chacun même contre son fils, et contre son frère, afin que vous attiriez aujourd’hui sur vous la bénédiction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Et le lendemain Moïse dit au peuple: vous avez commis un grand péché; mais je monterai maintenant vers l’Eternel; et peut-être, je ferai propitiation pour votre péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Moïse donc retourna vers l’Eternel, et dit: hélas! je te prie, ce peuple a commis un grand péché, en se faisant des dieux d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Mais maintenant pardonne-leur leur péché; sinon, efface-moi maintenant de ton livre, que tu as écrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Et l’Eternel répondit à Moïse: qui aura péché contre moi, je l’effacerai de mon livre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Va maintenant, conduis le peuple au lieu duquel je t’ai parlé; voici, mon Ange ira devant toi; et le jour que je ferai punition, je punirai sur eux leur péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Ainsi l’Eternel frappa le peuple, parce qu’ils avaient été les auteurs du Veau qu’Aaron avait fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'L’Eternel donc dit à Moïse: va, monte d’ici, toi et le peuple que tu as fait monter du pays d’Egypte, au pays duquel j’ai juré à Abraham, Isaac, et Jacob, en disant: je le donnerai à ta postérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Et j’enverrai un Ange devant toi, et je chasserai les Cananéens, les Amorrhéens, les Héthiens; les Phérésiens, les Héviens; et les Jébusiens,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'pour vous conduire au pays découlant de lait et de miel, mais je ne monterai point au milieu de toi, parce que tu es un peuple de col roide, de peur que je ne te consume en chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Et le peuple ouït ces tristes nouvelles, et en mena deuil, et aucun d’eux ne mit ses ornements sur soi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Car l’Eternel avait dit à Moïse: dis aux enfants d’Israël: vous êtes un peuple de col roide; je monterai en un moment au milieu de toi, et je te consumerai. Maintenant donc ôte tes ornements de dessus toi, et je saurai ce que je te ferai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Ainsi les enfants d’Israël se dépouillèrent de leurs ornements, vers la montagne d’Horeb.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Et Moïse prit un pavillon, et le tendit pour soi hors du camp, l’éloignant du camp; et il l’appela le pavillon d’assignation; et tous ceux qui cherchaient l’Eternel, sortaient vers le pavillon d’assignation, qui était hors du camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Et il arrivait qu’aussitôt que Moïse sortait vers le pavillon, tout le peuple se levait, et chacun se tenait à l’entrée de sa tente, et regardait Moïse par derrière, jusqu’à ce qu’il fût entré dans le pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Et sitôt que Moïse était entré dans le pavillon, la colonne de nuée descendait, et s’arrêtait à la porte du pavillon, et l’Eternel parlait avec Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Et tout le peuple voyant la colonne de nuée s’arrêtant à la porte du pavillon, se levait, et chacun se prosternait à la porte de sa tente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Et l’Eternel parlait à Moïse face à face; comme un homme parle avec son intime ami; puis Moïse retournait au camp, mais son serviteur Josué fils de Nun, jeune homme, ne bougeait point du pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Moïse donc dit à l’Eternel: regarde, tu m’as dit: fais monter ce peuple, et tu ne m’as point fait connaître celui que tu dois envoyer avec moi; tu as même dit: je te connais par ton nom, et aussi, tu as trouvé grâce devant mes yeux');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Or maintenant, je te prie, si j’ai trouvé grâce devant tes yeux, fais-moi connaître ton chemin, et je te connaîtrai, afin que je trouve grâce devant tes yeux; considère aussi que cette nation est ton peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Et l’Eternel dit: ma face ira, et je te donnerai du repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Et Moïse lui dit: si ta face ne vient, ne nous fais point monter d’ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Car en quoi connaîtra-t-on que nous ayons trouvé grâce devant tes yeux, moi et ton peuple? Ne sera-ce pas quand tu marcheras avec nous? et alors moi et ton peuple serons en admiration, plus que tous les peuples qui sont sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Et l’Eternel dit à Moïse: je ferai aussi ce que tu dis; car tu as trouvé grâce devant mes yeux, et je t’ai connu par ton nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Moïse dit aussi: je te prie, fais-moi voir ta gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Et Dieu dit: je ferai passer toute ma bonté devant ta face, et je crierai le nom de l’Eternel devant toi; et je ferai grâce à qui je ferai grâce, et j’aurai compassion de celui de qui j’aurai compassion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Puis il dit: tu ne pourras pas voir ma face; car nul homme ne peut me voir, et vivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'L’Eternel dit aussi: voici, il y a un lieu par-devers moi, et tu t’arrêteras sur le rocher;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Et quand ma gloire passera, je te mettrai dans l’ouverture du rocher, et te couvrirai de ma main, jusqu’à ce que je sois passé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Puis je retirerai ma main, et tu me verras par derrière, mais ma face ne se verra point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Et l’Eternel dit à Moïse: aplanis-toi deux Tables de pierre comme les premières, et j’écrirai sur elles les paroles qui étaient sur les premières Tables que tu as rompues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Et sois prêt au matin, et monte au matin en la montagne de Sinaï, et présente-toi là devant moi sur le haut de la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Mais que personne ne monte avec toi, et même que personne ne paraisse sur toute la montagne; et que ni menu ni gros bétail ne paisse contre cette montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Moïse donc aplanit deux Tables de pierre comme les premières, et se leva de bon matin, et monta sur la montagne de Sinaï, comme l’Eternel le lui avait commandé, et il prit en sa main les deux Tables de pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Et l’Eternel descendit dans la nuée, et s’arrêta là avec lui, et cria le nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Comme donc l’Eternel passait par devant lui, il cria: l’Eternel, l’Eternel,le Dieu Fort, pitoyable, miséricordieux, tardif à colère, abondant en gratuité et en vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Gardant la gratuité jusqu’en mille générations, ôtant l’iniquité, le crime, et le péché, qui ne tient point le coupable pour innocent, et qui punit l’iniquité des pères sur les enfants, et sur les enfants des enfants, jusqu’à la troisième et à la quatrième génération;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Et Moïse se hâtant baissa la tête contre terre, et se prosterna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Et dit: ô Seigneur! je te prie, si j’ai trouvé grâce devant tes yeux, que le Seigneur marche maintenant au milieu de nous; car c’est un peuple de col roide; pardonne donc nos iniquités et notre péché, et nous possède.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Et il répondit: voici, moi qui traite alliance devant tout ton peuple, je ferai des merveilles qui n’ont point été faites en toute la terre, ni en aucune nation, et tout le peuple au milieu duquel tu es, verra l’oeuvre de l’Eternel, car ce que je m’en vais faire avec toi, sera une chose terrible.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Garde soigneusement ce que je te commande aujourd’hui. Voici, je m’en vais chasser de devant toi les Amorrhéens, les Cananéens, les Héthiens, les Phérésiens, les Héviens, et les Jébusiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Donne-toi de garde de traiter alliance avec les habitants du pays auquel tu vas entrer, de peur que peut-être ils ne soient un piège au milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Mais vous démolirez leurs autels, vous briserez leurs statues, et vous couperez leurs bocages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Car tu ne te prosterneras point devant un autre Dieu, parce que l’Eternel se nomme le Dieu jaloux; c’est le Dieu Fort qui est jaloux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Afin qu’il n’arrive que tu traites alliance avec les habitants du pays; et que quand ils viendront à paillarder après leurs dieux, et à sacrifier à leurs dieux, quelqu’un ne t’invite, et que tu ne manges de son sacrifice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'Et que tu ne prennes de leurs filles pour tes fils, lesquelles paillardant après leurs dieux, feront paillarder tes fils après leurs dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Tu ne te feras aucun dieu de fonte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Tu garderas la fête solennelle des pains sans levain; tu mangeras les pains sans levain pendant sept jours, comme je t’ai commandé, en la saison du mois auquel les épis mûrissent; car au mois que les épis mûrissent, tu es sorti du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Tout ce qui ouvrira la matrice sera à moi; et même le premier mâle qui naîtra de toutes les bêtes, tant du gros que du menu bétail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Mais tu rachèteras avec un agneau ou un chevreau le premier-né d’un âne. Si tu ne le rachètes, tu lui couperas le cou. Tu rachèteras tout premier-né de tes fils; et nul ne se présentera devant ma face à vide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Tu travailleras six jours, mais au septième tu te reposeras; tu te reposeras au temps du labourage, et de la moisson.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Tu feras la fête solennelle des semaines au temps des premiers fruits de la moisson du froment; et la fête solennelle de la récolte à la fin de l’année.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Trois fois l’an tout mâle d’entre vous comparaîtra devant le Dominateur, l’Eternel, le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Car je déposséderai les nations de devant toi, et j’étendrai tes limites; et nul ne convoitera ton pays lorsque tu monteras pour comparaître trois fois l’an devant l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Tu n’offriras point le sang de mon sacrifice avec du pain levé; on ne gardera rien du sacrifice de la fête solennelle de la Pâque jusqu’au matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Tu apporteras les prémices des premiers fruits de la terre dans la maison de l’Eternel ton Dieu. Tu ne feras point cuire le chevreau au lait de sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'L’Eternel dit aussi à Moïse: écris ces paroles; car suivant la teneur de ces paroles j’ai traité alliance avec toi et avec Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Et Moïse demeura là avec l’Eternel quarante jours et quarante nuits, sans manger de pain, et sans boire d’eau; et l’Eternel écrivit sur les Tables les paroles de l’alliance, c’est-à-dire, les dix paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Or il arriva que lorsque Moïse descendait de la montagne de Sinaï, tenant en sa main les deux Tables du Témoignage, lors, dis-je, qu’il descendait de la montagne, il ne s’aperçut point que la peau de son visage était devenue resplendissante pendant qu’il parlait avec Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Mais Aaron et tous les enfants d’Israël ayant vu Moïse, et s’étant aperçus que la peau de son visage était resplendissante, ils craignirent d’approcher de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Mais Moïse les appela, et Aaron et tous les principaux de l’assemblée retournèrent vers lui; et Moïse parla avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Après quoi tous les enfants d’Israël s’approchèrent, et il leur commanda toutes les choses que l’Eternel lui avait dites sur la montagne de Sinaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Ainsi Moïse acheva de leur parler: or il avait mis un voile sur son visage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Et quand Moïse entrait vers l’Eternel pour parler avec lui, il ôtait le voile jusqu’à ce qu’il sortait; et étant sorti, il disait aux enfants d’Israël ce qui lui avait été commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Or les enfants d’Israël avaient vu que le visage de Moïse, la peau, dis- je, de son visage était resplendissante c’est pourquoi Moïse remettait le voile sur son visage, jusques à ce qu’il retournât pour parler avec l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Moïse donc assembla toute la congrégation des enfants d’Israël, et leur dit: ce sont ici les choses que l’Eternel a commandé de faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'On travaillera six jours, mais le septième jour il y aura sainteté pour vous; car c’est le Sabbat du repos consacré à l’Eternel; quiconque travaillera en ce jour-là, sera puni de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Vous n’allumerez point de feu dans aucune de vos demeures le jour du repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Puis Moïse parla à toute l’assemblée des enfants d’Israël, et leur dit: C’est ici ce que l’Eternel vous a commandé, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Prenez des choses qui sont chez vous, une offrande pour l’Eternel; quiconque sera de bonne volonté, apportera cette offrande pour l’Eternel, savoir de l’or, de l’argent, et de l’airain,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'De la pourpre, de l’écarlate, du cramoisi, et du fin lin, et du poil de chèvres,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'Des peaux de moutons teintes en rouge, et des peaux de taissons, du bois de Sittim,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'De l’huile pour le luminaire, des choses aromatiques pour l’huile de l’onction, et pour le parfum composé de choses aromatiques,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Des pierres d’Onyx, et des pierres de remplages pour l’Ephod, et pour le Pectoral.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Et tous les hommes d’esprit d’entre vous viendront, et feront tout ce que l’Eternel a commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'Savoir, Le pavillon, son Tabernacle, et sa couverture, ses anneaux, ses ais, ses barres, ses piliers, et ses soubassements;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'L’Arche et ses barres, le Propitiatoire, et le voile pour tendre au devant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'La Table et ses barres, et tous ses ustensiles, et le pain de proposition.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'Et le chandelier du luminaire, ses ustensiles, ses lampes, et l’huile du luminaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'Et l’autel du parfum et ses barres; l’huile de l’onction, le parfum des choses aromatiques, et la tapisserie pour tendre à l’entrée, savoir à l’entrée du pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'L’autel de l’holocauste, sa grille d’airain, ses barres et tous ses ustensiles; la cuve, et son soubassement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'Les courtines du parvis, ses piliers, ses soubassements, et la tapisserie pour tendre à la porte du parvis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'Et les pieux du pavillon, et les pieux du parvis, et leur cordage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'Les vêtements du service, pour faire le service dans le Sanctuaire, les saints vêtements d’Aaron Sacrificateur, et les vêtements de ses fils pour exercer la Sacrificature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Alors toute l’assemblée des enfants d’Israël sortit de la présence de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Et quiconque fut ému en son coeur, quiconque, dis-je, se sentit porté à la libéralité, apporta 1’offrande de l’Eternel pour l’ouvrage du Tabernacle d’assignation, et pour tout son service, et pour les saints vêtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Et les hommes vinrent avec les femmes; quiconque fut de coeur volontaire, apporta des boucles, des bagues, des anneaux, des bracelets, et des joyaux d’or, et quiconque offrit quelque offrande d’or à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Tout homme aussi chez qui se trouvait de la pourpre, de l’écarlate, du cramoisi, du fin lin, du poil de chèvres, des peaux de moutons teintes en rouge, et des peaux de taissons, les apporta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Tout homme qui avait de quoi faire une offrande d’argent, et d’airain, l’apporta pour l’offrande de l’Eternel; tout homme aussi chez qui fut trouvé du bois de Sittim pour tout l’ouvrage du service, l’apporta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Toute femme adroite, fila de sa main, et apporta ce qu’elle avait filé, de la pourpre, de l’écarlate, du cramoisi, et du fin lin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Toutes les femmes aussi dont le cœur les porta à travailler de leur industrie, filèrent du poil de chèvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Les principaux aussi de l’assemblée apportèrent des pierres d’Onyx, et des pierres de remplages pour l’Ephod et pour le Pectoral;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'Et des choses aromatiques, et de l’huile, tant pour le luminaire, que pour l’huile de l’onction, et pour le parfum composé de choses aromatiques.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Tout homme donc et toute femme que leur coeur incita à la libéralité, pour apporter de quoi faire l’ouvrage que l’Eternel avait commandé par le moyen de Moïse qu’on fît, tous les enfants, dis-je, d’Israël apportèrent volontairement des présents à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Alors Moïse dit aux enfants d’Israël: voyez, l’Eternel a appelé par son nom Betsaléel, fils d’Uri, fils de Hur, de la Tribu de Juda;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'Et il l’a rempli de l’Esprit de Dieu en sagesse, en intelligence, en science, pour toute sorte d’ouvrages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'Même afin d’inventer des dessins pour travailler en or, en argent, en airain;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'Dans la sculpture des pierres précieuses pour les mettre en œuvre; et dans la menuiserie, pour travailler en tout ouvrage exquis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Et il lui a mis aussi au cœur, tant à lui qu’à Aholiab fils d’Ahisamac, de la Tribu de Dan, de l’enseigner;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Et il les a remplis d’industrie pour faire toute sorte d’ouvrages d’ouvrier, même d’ouvrier en ouvrage exquis, et en broderie, en pourpre, en écarlate, en cramoisi, et en fin lin, et d’ouvrage de tissure, faisant toute sorte d’ouvrages, et inventant toute sorte de dessins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Et Betsaléel, et Aholiab, et tous les hommes d’esprit, auxquels l’Eternel avait donné de la sagesse, et de l’intelligence, pour savoir faire tout l’ouvrage du service du Sanctuaire, firent selon toutes les choses que l’Eternel avait commandées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Moïse donc appela Betsaléel et Aholiab, et tous les hommes d’esprit, dans le cœur desquels l’Eternel avait mis de la sagesse, et tous ceux qui furent émus en leur cœur de se présenter pour faire cet ouvrage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Lesquels emportèrent de devant Moïse toute l’offrande que les enfants d’Israël avaient apportée pour faire l’ouvrage du service du Sanctuaire. Or on apportait encore chaque matin quelque oblation volontaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'C’est pourquoi tous les hommes d’esprit qui faisaient tout l’ouvrage du Sanctuaire, vinrent chacun d’auprès l’ouvrage qu’ils faisaient;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'Et parlèrent à Moïse, en disant: le peuple ne cesse d’apporter plus qu’il ne faut pour le service, et pour l’ouvrage que l’Eternel a commandé de faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Alors par le commandement de Moïse on fit crier dans le camp: que ni homme ni femme ne fasse plus d’ouvrage pour l’offrande du Sanctuaire; et ainsi on empêcha le peuple d’offrir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Car ils avaient de l’étoffe suffisamment pour faire tout l’ouvrage, et il y en avait même de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Tous les hommes donc de plus grand esprit d’entre ceux qui faisaient l’ouvrage, firent le pavillon; savoir dix rouleaux de fin lin retors, de pourpre, d’écarlate, et de cramoisi; et ils les firent semés de Chérubins, d’un ouvrage exquis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'La longueur d’un rouleau était de vingt-huit coudées, et la largeur du même rouleau de quatre coudées; tous les rouleaux avaient une même mesure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Et ils joignirent cinq rouleaux l’un à l’autre, et cinq autres rouleaux l’un à l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Et ils firent des lacets de pourpre sur le bord d’un rouleau, savoir au bord de celui qui était attaché; ils en firent ainsi au bord du dernier rouleau, dans l’assemblage de l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Ils firent cinquante lacets en un rouleau, et cinquante lacets au bord du rouleau qui était dans l’assemblage de l’autre; les lacets étant vis-à-vis l’un de l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Puis on fit cinquante crochets d’or, et on attacha les rouleaux l’un à l’autre avec les crochets; ainsi il fut fait un pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Puis on fit des rouleaux de poils de chèvres, pour servir de Tabernacle au dessus du pavillon; on fit onze de ces rouleaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'La longueur d’un rouleau était de trente coudées, et la largeur du même rouleau, de quatre coudées; et les onze rouleaux étaient d’une même mesure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Et on assembla cinq de ces rouleaux à part, et six rouleaux à part.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'On fit aussi cinquante lacets sur le bord de l’un des rouleaux, savoir au dernier qui était attaché, et cinquante lacets sur le bord de l’autre rouleau, qui était attaché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'On fit aussi cinquante crochets d’airain pour attacher le Tabernacle, afin qu’il n’y en eût qu’un.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Puis on fît pour le Tabernacle une couverture de peaux de moutons teintes en rouge, et une couverture de peaux de taissons par dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Et on fit pour le pavillon des ais de bois de Sittim, qu’on fit tenir debout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'La longueur d’un ais était de dix coudées, et la largeur du même ais d’une coudée et demie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Il y avait deux tenons à chaque ais en façon d’échelons l’un après l’autre; on fit la même chose à tous les ais du pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'On fit donc les ais pour le pavillon; savoir vingt ais au côté qui regardait directement vers le Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Et au-dessous des vingt ais on fit quarante soubassements d’argent, deux soubassements sous un ais, pour ses deux tenons, et deux soubassements sous l’autre ais, pour ses deux tenons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'On fit aussi vingt ais à l’autre côté du pavillon, du côté du Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'Et leurs quarante soubassements, d’argent: deux soubassements sous un ais, et deux soubassements sous l’autre ais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Et pour le fond du pavillon, vers l’Occident, on fit six ais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Et on fit deux ais pour les encoignures du pavillon aux deux côtés du fond;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Qui étaient égaux par le bas, et qui étaient joints et unis par le haut avec un anneau; on fit la même chose aux deux ais qui étaient aux deux encoignures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Il y avait donc huit ais et seize soubassements d’argent; savoir deux soubassements sous chaque ais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Puis on fit cinq barres de bois de Sittim, pour les ais de l’un des côtés du pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'Et cinq barres pour les ais de l’autre côté du pavillon; et cinq barres pour les ais du pavillon pour le fond, vers le côté de l’Occident;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Et on fit que la barre du milieu passait par le milieu des ais depuis un bout jusqu’à l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Et on couvrit d’or les ais, et on fit leurs anneaux d’or pour y faire passer les barres, et on couvrit d’or les barres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'On fit aussi le voile de pourpre, d’écarlate, de cramoisi, et de fin lin retors, on le fit d’ouvrage exquis, semé de Chérubins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Et on lui fit quatre piliers de bois de Sittim, qu’on couvrit d’or, ayant leurs crochets d’or; et on fondit pour eux quatre soubassements d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'On fit aussi à l’entrée du Tabernacle une tapisserie de pourpre, d’écarlate, de cramoisi, et de fin lin retors, d’ouvrage de broderie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'Et ses cinq piliers avec leurs crochets; et on couvrit d’or leurs chapiteaux et leurs filets; mais leurs cinq soubassements étaient d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Puis Betsaléel fit l’arche de bois de Sittim. Sa longueur était de deux coudées et demie, et sa largeur d’une coudée et demie, et sa hauteur d’une coudée et demie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Et il la couvrit par-dedans et par dehors de pur or, et lui fit un couronnement d’or à l’entour;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Et il lui fondit quatre anneaux d’or pour les mettre sur ses quatre coins; savoir deux anneaux à l’un de ses côtés, et deux autres à l’autre côté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Il fit aussi des barres de bois de Sittim, et les couvrit d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Et il fit entrer les barres dans les anneaux aux côtés de l’Arche, pour porter l’Arche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Il fit aussi le Propitiatoire de pur or; sa longueur était de deux coudées et demie, et sa largeur d’une coudée et demie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Et il fit deux Chérubins d’or; il les fit d’ouvrage étendu au marteau, tirés des deux bouts du Propitiatoire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'Savoir un Chérubin tiré du bout de deçà, et l’autre Chérubin du bout de delà; il fit, dis-je, les Chérubins tirés du Propitiatoire; savoir de ses deux bouts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Et les Chérubins étendaient leurs ailes en haut, couvrant de leurs ailes le Propitiatoire; et leurs faces étaient vis-à-vis l’une de l’autre, et les Chérubins regardaient vers le Propitiatoire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Il fit aussi la Table de bois de Sittim; sa longueur était de deux coudées, et sa largeur d’une coudée, et sa hauteur d’une coudée et demie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Et il la couvrit de pur or, et lui fit un couronnement d’or à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Il lui fit aussi à l’environ une clôture large d’une paume, et il fit à l’entour de sa clôture un couronnement d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Et il lui fondit quatre anneaux d’or, et il mit les anneaux aux quatre coins, qui étaient à ses quatre pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Les anneaux étaient à l’endroit de la clôture, pour y mettre les barres, afin de porter la Table avec elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Et il fit les barres de bois de Sittim, et les couvrit d’or pour porter la Table.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Il fit aussi de pur or des vaisseaux pour poser sur la Table, ses plats, ses tasses, ses bassins, et ses gobelets, avec lesquels on devait faire les aspersions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Il fit aussi le chandelier de pur or; il le fit d’ouvrage façonné au marteau; sa tige, ses branches, ses plats, ses pommeaux, et ses fleurs étaient tirés de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Et six branches sortaient de ses côtés, trois branches d’un côté du chandelier, et trois de l’autre côté du chandelier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Il y avait en l’une des branches trois plats en forme d’amande, un pommeau et une fleur; et en l’autre branche trois plats en forme d’amande, un pommeau et une fleur; il fit la même chose aux six branches qui sortaient du chandelier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Et il y avait au chandelier quatre plats en forme d’amande, ses pommeaux et ses fleurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Et un pommeau sous deux branches tirées du chandelier, et un pommeau sous deux autres branches, tirées de lui, et un pommeau sous deux autres branches, tirées de lui, savoir des six branches qui procédaient du chandelier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Leurs pommeaux et leurs branches étaient tirés de lui, et tout le chandelier était un ouvrage d’une seule pièce étendu au marteau, et de pur or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Il fit aussi ses sept lampes, ses mouchettes, et ses creuseaux de pur or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Et il le fit avec toute sa garniture d’un talent de pur or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Il fit aussi de bois de Sittim l’autel du parfum; sa longueur était d’une coudée, et sa largeur d’une coudée; il était carré; mais sa hauteur était de deux coudées, et ses cornes procédaient de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Et il couvrit de pur or le dessus de l’autel, et ses côtés tout à l’entour, et ses cornes; et il lui fit tout à l’entour un couronnement d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Il fit aussi au-dessous de son couronnement deux anneaux d’or à ses deux côtés, lesquels il mit aux deux coins, pour y faire passer les barres, afin de le porter avec elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Et il fit les barres de bois de Sittim, et les couvrit d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Il composa aussi l’huile de l’onction, qui était une chose sainte, et le pur parfum de drogues, d’ouvrage de parfumeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Il fit aussi de bois de Sittim l’autel des holocaustes; et sa longueur était de cinq coudées, et sa largeur de cinq coudées; il était carré; et sa hauteur était de trois coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Et il fit ses cornes à ses quatre coins; ses cornes sortaient de lui, et il le couvrit d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Il fit aussi tous les ustensiles de l’autel, les chaudrons, les racloirs, les bassins, les fourchettes, et les encensoirs; il fit tous ses ustensiles d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Et il fit pour l’autel une grille d’airain, en forme de treillis, au-dessous de l’enceinte de l’autel, depuis le bas jusques au milieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Et il fondit quatre anneaux aux quatre coins de la grille d’airain, pour mettre les barres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Et il fit les barres de bois de Sittim, et les couvrit d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Et il fit passer les barres dans les anneaux, aux côtés de l’autel, pour le porter avec elles, le faisant d’ais, et creux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Il fit aussi la cuve d’airain et son soubassement d’airain des miroirs des femmes qui s’assemblaient par troupes; qui s’assemblaient, dis-je, par troupes à la porte du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Il fit aussi un parvis, pour le côté qui regarde vers le Midi, et des courtines de fin lin retors, de cent coudées, pour le parvis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Et il fit d’airain leurs vingt piliers avec leurs vingt soubassements, mais les crochets des piliers et leurs filets étaient d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Et pour le côté du Septentrion, il fit des courtines de cent coudées, leurs vingt piliers et leurs vingt soubassements étaient d’airain, mais les crochets des piliers et leurs filets étaient d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Et pour le côté de l’Occident, des courtines de cinquante coudées, leurs dix piliers, et leurs dix soubassements; les crochets des piliers et leurs filets étaient d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Et pour le côté de l’Orient droit vers le Levant, des courtines de cinquante coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Il fit pour l’un des côtés quinze coudées de courtines, et leurs trois piliers avec leurs trois soubassements;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Et pour l’autre côté, quinze coudées de courtines, afin qu’il y en eût autant deçà que delà de la porte du parvis, et leurs trois piliers avec leurs trois soubassements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Il fit donc toutes les courtines du parvis qui étaient tout à l’entour, de fin lin retors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Il fit aussi d’airain les soubassements des piliers, mais il fit d’argent les crochets des piliers, et les filets, et leurs chapiteaux furent couverts d’argent, et tous les piliers du parvis furent ceints à l’entour d’un filet d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Et il fit la tapisserie de la porte du parvis de pourpre, d’écarlate, et de cramoisi, et de fin lin retors, d’ouvrage de broderie, de la longueur de vingt coudées, et de la hauteur, qui était la largeur, de cinq coudées; à la correspondance des courtines du parvis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Et ses quatre piliers avec leurs soubassements, d’airain, et leurs crochets, d’argent; la couverture aussi de leurs chapiteaux et leurs filets, d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Et tous les pieux du Tabernacle et du parvis à l’entour, d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'C’est ici le compte des choses qui furent employées au pavillon, savoir au pavillon du Témoignage, selon que le compte en fut fait par le commandement de Moïse, à quoi furent employés les Lévites, sous la conduite d’Ithamar, fils d’Aaron, sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Et Betsaléel, fils d’Uri, fils de Hur, de la Tribu de Juda, fit toutes les choses que l’Eternel avait commandées à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'Et avec lui Aholiab fils d’Ahisamac, de la Tribu de Dan, les ouvriers, et ceux qui travaillaient en ouvrage exquis, et les brodeurs en pourpre, en écarlate, en cramoisi, et en fin lin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Tout l’or qui fut employé pour l’ouvrage, savoir pour tout l’ouvrage du Sanctuaire, qui était de l’or d’oblation, fut de vingt-neuf talents, et de sept cent trente sicles, selon le sicle du Sanctuaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Et l’argent de ceux de l’assemblée qui furent dénombrés, fut de cent talents, et mille sept cent soixante et quinze sicles, selon le sicle du Sanctuaire:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Un demi-sicle par tête, la moitié d’un sicle selon le sicle du Sanctuaire; tous ceux qui passèrent par le dénombrement depuis l’âge de vingt ans et au- dessus, furent six cent trois mille cinq cent cinquante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Il y eut donc cent talents d’argent pour fondre les soubassements du Sanctuaire, et les soubassements du voile, savoir cent soubassements de cent talents, un talent pour chaque soubassement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Mais des mille sept cent soixante et quinze sicles, il fit les crochets pour les piliers, et il couvrit leurs chapiteaux, et en fit des filets à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'L’airain d’oblation fut de soixante et dix talents, et deux mille quatre cents sicles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Dont on fit les soubassements de la porte du Tabernacle d’assignation, et l’autel d’airain avec sa grille d’airain, et tous les ustensiles de l’autel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'Et les soubassements du parvis à l’entour, et les soubassements de la porte du parvis, et tous les pieux du pavillon, et tous les pieux du parvis à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Ils firent aussi de pourpre, d’écarlate, et de cramoisi les vêtements du service, pour faire le service du Sanctuaire; et ils firent les saints vêtements pour Aaron, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'On fit donc l’Ephod, d’or, de pourpre, d’écarlate, de cramoisi, et de fin lin retors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Or on étendit des lames d’or, et on les coupa par filets pour les brocher parmi la pourpre, l’écarlate, le cramoisi et le fin lin, d’ouvrage exquis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'On fit à l’Ephod des épaulières qui s’attachaient, en sorte qu’il était joint par ses deux bouts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Et le ceinturon exquis duquel il était ceint, était tiré de lui, et de même ouvrage, d’or, de pourpre, d’écarlate, de cramoisi, et de fin lin retors, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'On enchâssa aussi les pierres d’Onyx dans leurs chatons d’or, ayant les noms des enfants d’Israël gravés de gravure de cachet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Et on les mit sur les épaulières de l’Ephod, afin qu’elles fussent des pierres de mémorial pour les enfants d’Israël, comme l’Eternel avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'On fit aussi le Pectoral d’ouvrage exquis, comme l’ouvrage de l’Ephod, d’or, de pourpre, d’écarlate, de cramoisi, et de fin lin retors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'On fit le Pectoral carré, et double; sa longueur était d’une paume, et sa largeur d’une paume de part et d’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Et on le remplit de quatre rangs de pierres. A la première rangée on mit une Sardoine, une Topaze et une Emeraude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'A la seconde rangée une Escarboucle, un Saphir, et un Jaspe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'A la troisième rangée, un Ligure, une Agate, et une Améthyste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'Et à la quatrième rangée, un Chrysolithe, un Onyx, et un Béril, environnés de chatons d’or, dans leur remplage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Ainsi il y avait autant de pierres qu’il y avait de noms des enfants d’Israël, douze selon leurs noms, chacune d’elles gravée de gravure de cachet, selon le nom, qu’elle devait porter, et elles étaient pour les douze Tribus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Et on fit sur le Pectoral des chaînettes à bouts, en façon de cordon, de pur or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'On fit aussi deux crampons d’or, et deux anneaux d’or, et on mit les deux anneaux aux deux bouts du Pectoral.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Et on mit les deux chaînettes d’or faites à cordon, dans les deux anneaux, à l’extrémité du Pectoral;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Et on mit les deux autres bouts des deux chaînettes faites à cordon, aux deux crampons, sur les épaulières de l’Ephod, sur le devant de l’Ephod.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'On fit aussi deux autres anneaux d’or, et on les mit aux deux autres bouts du Pectoral sur son bord, qui était du côté de l’Ephod en dedans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'On fit aussi deux autres anneaux d’or, et on les mit aux deux épaulières de l’Ephod par le bas, répondant sur le devant de l’Ephod, à l’endroit où il se joignait au-dessus du ceinturon exquis de l’Ephod.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Et on joignit le Pectoral élevé par ses anneaux aux anneaux de l’Ephod, avec un cordon de pourpre, afin qu’il tînt au-dessus du ceinturon exquis de l’Ephod, et que le Pectoral ne bougeât point de dessus l’Ephod, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'On fit aussi le Rochet de l’Ephod d’ouvrage tissu, et entièrement de pourpre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Et l’ouverture à passer la tête, était au milieu du Rochet, comme l’ouverture d’un corselet; et il y avait un ourlet à l’ouverture du Rochet tout à l’entour, afin qu’il ne se déchirât point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Et aux bords du Rochet on fit des grenades de pourpre, d’écarlate, et de cramoisi, à fil retors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'On fit aussi des clochettes de pur or, et on mit les clochettes entre les grenades aux bords du Rochet tout à l’entour, parmi les grenades.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'Savoir, une clochette, puis une grenade; une clochette, puis une grenade, aux bords du Rochet tout à l’entour, pour faire le service, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'On fit aussi à Aaron et à ses fils des chemises de fin lin d’ouvrage tissu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'Et la tiare de fin lin, et les ornements des calottes de fin lin, et les caleçons de lin, de fin lin retors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'Et le baudrier de fin lin retors, de pourpre, d’écarlate, de cramoisi, d’ouvrage de broderie, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Et la lame du saint couronnement de pur or, sur laquelle on écrivit en écriture de gravure de cachet: LA SAINTETÉ A L’ÉTERNEL.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Et on mit sur elle un cordon de pourpre, pour l’appliquer à la tiare par dessus, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Ainsi fut achevé tout l’ouvrage du pavillon du Tabernacle d’assignation; et les enfants d’Israël firent selon toutes les choses que l’Eternel avait commandées à Moïse; ils les firent ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Et ils apportèrent à Moïse le pavillon, le Tabernacle, et tous ses ustensiles, ses crochets, ses ais, ses barres, ses piliers, et ses soubassements;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'La couverture de peaux de moutons teintes en rouge, et la couverture de peaux de taissons, et le voile pour tendre devant le lieu Très-saint;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'L’Arche du Témoignage, et ses barres, et le Propitiatoire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'La Table, avec tous ses ustensiles, et le pain de proposition;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'Et le chandelier pur, avec toutes ses lampes arrangées, et tous ses ustensiles, et l’huile du luminaire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'Et l’autel d’or, l’huile de l’onction, le parfum de drogues, et la tapisserie de l’entrée du Tabernacle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'Et l’autel d’airain, avec sa grille d’airain, ses barres, et tous ses ustensiles; la cuve, et son soubassement;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'Et les courtines du parvis, ses piliers, ses soubassements, la tapisserie pour la porte du parvis, son cordage, ses pieux, et tous les ustensiles du service du pavillon, pour le Tabernacle d’assignation;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'Les vêtements du service pour faire le service du Sanctuaire, les saints vêtements pour Aaron Sacrificateur, et les vêtements de ses fils pour exercer la Sacrificature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Les enfants d’Israël donc firent tout l’ouvrage; comme l’Eternel l’ avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Et Moïse vit tout l’ouvrage, et voici, on l’avait fait ainsi que l’Eternel l’avait commandé, on l’avait, dis-je, fait ainsi; et Moïse les bénit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Au premier jour du premier mois, tu dresseras le pavillon du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Et tu y mettras l’Arche du Témoignage, au devant de laquelle tu tendras le voile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Puis tu apporteras la Table, et y arrangeras ce qui y doit être arrangé. Tu apporteras aussi le chandelier, et allumeras ses lampes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Tu mettras aussi l’autel d’or pour le parfum au devant de l’Arche du Témoignage; et tu mettras la tapisserie de l’entrée au pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Tu mettras aussi l’autel de l’holocauste vis-à-vis de l’entrée du pavillon du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Tu mettras aussi la cuve entre le Tabernacle d’assignation et l’autel, et y mettras de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Tu mettras aussi le parvis tout à l’entour, et tu mettras la tapisserie à la porte du parvis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Tu prendras aussi l’huile de l’onction, et tu en oindras le pavillon, et tout ce qui y est, et tu le sanctifieras, avec tous ses ustensiles; et il sera saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Tu oindras aussi l’autel de l’holocauste, et tous ses ustensiles, et tu sanctifieras l’autel, et l’autel sera très-saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Tu oindras aussi la cuve et son soubassement, et la sanctifieras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Tu feras aussi approcher Aaron et ses fils à l’entrée du Tabernacle d’assignation, et les laveras avec de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Et tu feras vêtir à Aaron les saints vêtements, tu l’oindras, et le sanctifieras; et il m’exercera la Sacrificature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Tu feras aussi approcher ses fils, lesquels tu revêtiras de chemises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Et tu les oindras comme tu auras oint leur père; et ils m’exerceront la Sacrificature, et leur onction leur sera pour exercer la Sacrificature à toujours, d’âge en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Ce que Moïse fit selon toutes les choses que l’Eternel lui avait commandées; il le fit ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Car au premier jour du premier mois, en la seconde année, le pavillon fut dressé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Moïse donc dressa le pavillon, et mit ses soubassements, et posa ses ais, et mit ses barres, et dressa ses piliers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Et il étendit le Tabernacle sur le pavillon, et mit la couverture du Tabernacle au-dessus du pavillon par le haut, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Puis il prit et posa le Témoignage dans l’Arche, et mit les barres à l’Arche; il mit aussi le Propitiatoire au-dessus de l’Arche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Et il apporta l’Arche dans le pavillon, et posa le voile de tapisserie, et le mit au devant de l’Arche du Témoignage, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Il mit aussi la Table dans le Tabernacle d’assignation, au côté du pavillon, vers le Septentrion, au deçà du voile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Et il arrangea sur elle les rangées de pains devant l’Eternel, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Il mit aussi le chandelier au Tabernacle d’assignation vis-à-vis de la Table au côté du pavillon vers le Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Et il alluma les lampes devant l’Eternel, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Il posa aussi l’autel d’or au Tabernacle d’assignation devant le voile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'Et il fit fumer sur lui le parfum de drogues, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Il mit aussi la tapisserie de l’entrée pour le pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Et il mit l’autel de l’holocauste à l’entrée du pavillon du Tabernacle d’assignation; et offrit sur lui l’holocauste et le gâteau, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Et il posa la cuve entre le Tabernacle d’assignation et l’autel, et y mit de l’eau pour se laver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Et Moïse et Aaron avec ses fils en lavèrent leurs mains et leurs pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Et quand ils entraient au Tabernacle d’assignation, et qu’ils approchaient de l’autel, ils se lavaient, selon que l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Il dressa aussi le parvis tout à l’entour du pavillon et de l’autel, et tendit la tapisserie de la porte du parvis. Ainsi Moïse acheva l’ouvrage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Et la nuée couvrit le Tabernacle d’assignation, et la gloire de l’Eternel remplit le pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Tellement que Moïse ne put entrer au Tabernacle d’assignation, car la nuée se tenait dessus et la gloire de l’Eternel remplissait le pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Or quand la nuée se levait de dessus le Tabernacle, les enfants d’Israël partaient dans toutes leurs traittes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Mais si la nuée ne se levait point, ils ne partaient point jusqu’au jour qu’elle se levait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Car la nuée de l’Eternel était le jour sur le pavillon, et le feu y était la nuit, devant les yeux de toute la maison d’Israël, dans toutes leurs traittes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Or l’Eternel appela Moïse, et lui parla du Tabernacle d’assignation, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Parle aux enfants d’Israël, et leur dis: Quand quelqu’un d’entre vous offrira à l’Eternel une offrande d’une bête à quatre pieds, il fera son offrande de gros ou de menu bétail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Si son offrande pour un holocauste est de gros bétail, il offrira un mâle sans tare; il l’offrira de son bon gré, à l’entrée du Tabernacle d’assignation, devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Et il posera sa main sur la tête de l’holocauste, et il sera agréé pour lui, afin de faire propitiation pour lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Puis on égorgera le veau devant l’Eternel, et les fils d’Aaron Sacrificateurs en offriront le sang, et ils répandront le sang tout autour sur l’autel, qui est à l’entrée du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Et on égorgera l’holocauste, et on le coupera par pièces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Et les fils d’Aaron Sacrificateurs mettront le feu sur l’autel, et arrangeront le bois sur le feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Et les fils d’Aaron Sacrificateurs arrangeront les pièces, la tête, et la fressure au dessus du bois qui sera au feu sur l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Mais il lavera avec de l’eau le ventre et les jambes, et le Sacrificateur fera fumer toutes ces choses sur l’autel; c’est un holocauste, un sacrifice fait par feu, en bonne odeur à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Que si son offrande pour l’holocauste est de menu bétail, d’entre les brebis ou d’entre les chèvres, il offrira un mâle sans tare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Et on l’égorgera à côté de l’autel vers le Septentrion devant l’Eternel, et les fils d’Aaron Sacrificateurs en répandront le sang sur l’autel tout autour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Puis on le coupera par pièces, avec sa tête, et sa fressure; et le Sacrificateur les arrangera sur le bois qui sera au feu qui est sur l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Mais il lavera avec de l’eau le ventre et les jambes. Puis le Sacrificateur offrira toutes ces choses, et les fera fumer sur l’autel; c’est un holocauste, un sacrifice fait par feu d’agréable odeur à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Que si son offrande pour l’holocauste à l’Eternel est d’oiseaux, il fera son offrande de tourterelles, ou de pigeonneaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Et le Sacrificateur l’offrira sur l’autel, et lui entamera la tête avec l’ongle, afin de la faire fumer sur l’autel, et il en épreindra le sang au côté de l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Et il ôtera son jabot avec sa plume, et les jettera près de l’autel vers l’Orient, où seront les cendres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Il l’entamera donc avec ses ailes sans le diviser; et le Sacrificateur le fera fumer sur l’autel, au dessus du bois qui sera au feu; c’est un holocauste, un sacrifice fait par feu d’agréable odeur à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Et quand quelque personne offrira l’offrande du gâteau à l’Eternel, son offrande sera de fleur de farine, et il versera de l’huile sur le gâteau, et mettra de l’encens par dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Et il l’apportera aux fils d’Aaron Sacrificateurs, et le Sacrificateur prendra une poignée de la fleur de farine, et de l’huile dont le gâteau aura été fait, avec tout l’encens qui était sur le gâteau, et il fera fumer son mémorial sur l’autel; c’est une offrande faite par feu en bonne odeur à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Mais ce qui restera du gâteau sera pour Aaron et ses fils; c’est une chose très-sainte d’entre les offrandes faites par feu à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Et quand tu offriras une offrande de gâteaux cuits au four, ce seront des tourteaux sans levain, de fine farine, pétris avec de l’huile, et des beignets sans levain, oints d’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Et si ton offrande est de gâteau cuit sur la plaque, elle sera de fine farine pétrie dans l’huile, sans levain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Tu la mettras par morceaux, et tu verseras de l’huile sur elle; car c’est une offrande de gâteau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Et si ton offrande est un gâteau de poêle, elle sera faite de fine farine avec de l’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Puis tu apporteras à l’Eternel le gâteau qui sera fait de ces choses-là, et on le présentera au Sacrificateur, qui l’apportera vers l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Et le Sacrificateur en lèvera son mémorial, et le fera fumer sur l’autel; c’est une offrande faite par feu en bonne odeur à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Et ce qui restera du gâteau sera pour Aaron et ses fils; c’est une chose très-sainte, d’entre les offrandes faites par feu à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Quelque gâteau que vous offriez à l’Eternel, il ne sera point fait avec du levain; car vous ne ferez point fumer de levain, ni de miel, dans aucune offrande faite par feu à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Vous pourrez bien les offrir à l’Eternel dans l’offrande des prémices, mais ils ne seront point mis sur l’autel pour être une oblation de bonne odeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Tu saleras aussi de sel toute offrande de ton gâteau, et tu ne laisseras point manquer sur ton gâteau le sel de l’alliance de ton Dieu; mais dans toutes tes oblations tu offriras du sel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Et si tu offres à l’Eternel le gâteau des premiers fruits, tu offriras, pour le gâteau de tes premiers fruits, des épis qui commencent à mûrir, rôtis au feu, savoir les grains de quelques épis bien grenés, broyés entre les mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Puis tu mettras de l’huile sur le gâteau, et tu mettras aussi de l’encens par dessus; c’est une offrande de gâteau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Et le Sacrificateur fera fumer son mémorial, pris de ses grains broyés, et de son huile avec tout l’encens; c’est une offrande faite par feu à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Et si l’offrande de quelqu’un est un sacrifice de prospérités, et qu’il l’offre de gros bétail, soit mâle soit femelle, il l’offrira sans tare, devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Et il posera sa main sur la tête de son offrande, et on l’égorgera à l’entrée du Tabernacle d’assignation, et les fils d’Aaron Sacrificateurs répandront le sang sur l’autel à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Puis on offrira, du sacrifice de prospérités une offrande faite par feu à l’Eternel, savoir la graisse qui couvre les entrailles, et toute la graisse qui est sur les entrailles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'Et les deux rognons avec la graisse qui est sur eux, jusque sur les flancs, et on ôtera la taie qui est sur le foie pour la mettre avec les rognons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Et les fils d’Aaron feront fumer tout cela sur l’autel, par dessus l’holocauste qui sera sur le bois qu’on aura mis sur le feu; c’est une offrande faite par feu de bonne odeur à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Que si son offrande est de menu bétail pour le sacrifice de prospérités à l’Eternel, soit mâle soit femelle, il l’offrira sans tare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'S’il offre un agneau pour son offrande, il l’offrira devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'Et il posera sa main sur la tête de son offrande, et on l’égorgera devant le Tabernacle d’assignation, et les fils d’Aaron répandront son sang sur l’autel à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Et il offrira du sacrifice de prospérités une offrande faite par feu à l’Eternel, en ôtant sa graisse, et sa queue entière jusque contre l’échine, avec la graisse qui couvre les entrailles, et toute la graisse qui est sur les entrailles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'Et les deux rognons avec la graisse qui est sur eux, jusque sur les flancs, et il ôtera la taie qui est sur le foie pour la mettre sur les rognons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Et le Sacrificateur fera fumer tout cela sur l’autel; c’est une viande d’offrande faite par feu à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Que si son offrande est d’entre les chèvres, il l’offrira devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'Et il posera sa main sur la tête de son offrande, et on l’égorgera devant le Tabernacle d’assignation; et les enfants d’Aaron répandront son sang sur l’autel à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Puis il offrira son offrande pour sacrifice fait par feu à l’Eternel, savoir, la graisse qui couvre les entrailles, et toute la graisse qui est sur les entrailles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'Et les deux rognons, et la graisse qui est sur eux, jusque sur les flancs, et il ôtera la taie qui est sur le foie pour la mettre sur les rognons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Puis le Sacrificateur fera fumer toutes ces choses-là sur l’autel; c’est une viande d’offrande faite par feu en bonne odeur. Toute graisse appartient à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'C’est une ordonnance perpétuelle en vos âges, et dans toutes vos demeures, que vous ne mangerez aucune graisse, ni aucun sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'L’Eternel parla encore à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Parle aux enfants d’Israël, et leur dis: Quand une personne aura péché par erreur contre quelqu’un des commandements de l’Eternel, en commettant des choses qui ne se doivent point faire, et qu’il aura fait quelqu’une de ces choses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Si c’est le Sacrificateur oint qui ait commis un péché semblable à quelque faute du peuple, il offrira à l’Eternel pour son péché qu’il aura fait, un veau sans tare, pris du troupeau, en offrande pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Il amènera le veau à l’entrée du Tabernacle d’assignation devant l’Eternel, il posera sa main sur la tête du veau, et l’égorgera devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Et le Sacrificateur oint prendra du sang du veau, et l’apportera dans le Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Et le Sacrificateur trempera son doigt dans le sang, et fera aspersion du sang par sept fois devant l’Eternel, au devant du voile du Sanctuaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Le Sacrificateur mettra aussi devant l’Eternel du sang sur les cornes de l’autel du parfum des drogues, qui est dans le Tabernacle d’assignation; mais il répandra tout le reste du sang du veau au pied de l’autel de l’holocauste, qui est à l’entrée du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Et il lèvera toute la graisse du veau de l’offrande pour le péché, savoir, la graisse qui couvre les entrailles, et toute la graisse qui est sur les entrailles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'Et les deux rognons avec la graisse qui est sur eux, jusque sur les flancs, et il ôtera la taie qui est sur le foie pour la mettre sur les rognons;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'Comme on les ôte du boeuf du sacrifice de prospérités, et le Sacrificateur fera fumer toutes ces choses-là sur l’autel de l’holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Mais quant à la peau du veau et toute sa chair, avec sa tête, ses jambes, ses entrailles, et sa fiente,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'Et même tout le veau, il le tirera hors du camp dans un lieu net, où l’on répand les cendres, et il le brûlera sur du bois au feu, il sera brûlé au lieu où l’on répand les cendres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Et si toute l’assemblée d’Israël a péché par erreur, et que la chose n’ait pas été aperçue par l’assemblée, et qu’ils aient violé quelque commandement de l’Eternel, en commettant des choses qui ne se doivent point faire, et se soient rendus coupables;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'Et que le péché qu’ils ont fait vienne en évidence, l’assemblée offrira en offrande pour le péché un veau pris du troupeau, et on l’amènera devant le Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Et les Anciens de l’assemblée poseront leurs mains sur la tête du veau devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Et le Sacrificateur oint portera du sang du veau dans le Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Ensuite le Sacrificateur trempera son doigt dans le sang, et en fera aspersion devant l’Eternel au devant du voile, par sept fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Et il mettra du sang sur les cornes de l’autel qui est devant l’Eternel dans le Tabernacle d’assignation, et il répandra tout le reste du sang au pied de l’autel de l’holocauste, qui est à l’entrée du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Et il lèvera toute sa graisse, et la fera fumer sur l’autel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Et il fera de ce veau, comme il a fait du veau de l’offrande pour son péché. Le Sacrificateur fera ainsi; il fera propitiation pour eux; et il leur sera pardonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Puis il tirera hors du camp le veau, et le brûlera comme il a brûlé le premier veau; car c’est l’offrande pour le péché de l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Que si quelqu’un des principaux a péché, ayant violé par erreur quelqu’un des commandements de l’Eternel son Dieu, en commettant des choses qui ne se doivent point faire, et s’est rendu coupable;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'Et qu’on l’avertisse de son péché, qu’il a commis, il amènera pour sacrifice un jeune bouc mâle sans tare;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Et il posera sa main sur la tête du bouc, et on l’égorgera au lieu où l’on égorge l’holocauste devant l’Eternel; car c’est une offrande pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Puis le Sacrificateur prendra avec son doigt du sang de l’offrande pour le péché, et le mettra sur les cornes de l’autel de l’holocauste, et il répandra le reste de son sang au pied de l’autel de l’holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Et il fera fumer toute sa graisse sur l’autel comme la graisse du sacrifice de prospérités; ainsi le Sacrificateur fera propitiation pour lui de son péché, et il lui sera pardonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Que si quelque personne du commun peuple a péché par erreur, en violant quelqu’un des commandements de l’Eternel, et en commettant des choses qui ne se doivent point faire, et s’est rendu coupable;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'Et qu’on l’avertisse de son péché qu’il a commis, il amènera son offrande d’une jeune chèvre, sans tare, femelle, pour son péché qu’il a commis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Et il posera sa main sur la tête de l’offrande pour le péché, et on égorgera l’offrande pour le péché au lieu où l’on égorge l’holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Puis le Sacrificateur prendra du sang de la chèvre avec son doigt, et le mettra sur les cornes de l’autel de l’holocauste, et il répandra tout le reste de son sang au pied de l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Et il ôtera toute sa graisse comme on ôte la graisse de dessus le sacrifice de prospérités, et le Sacrificateur la fera fumer sur l’autel, en bonne odeur à l’Eternel, il fera propitiation pour lui, et il lui sera pardonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Que s’il amène un agneau pour l’oblation de son péché, ce sera une femelle sans tare qu’il amènera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Et il posera sa main sur la tête de l’offrande pour le péché, et on l’égorgera pour le péché au lieu où l’on égorge l’holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Puis le Sacrificateur prendra avec son doigt du sang de l’offrande pour le péché, et le mettra sur les cornes de l’autel de l’holocauste, et il répandra tout le reste de son sang au pied de l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Et il ôtera toute sa graisse, comme on ôte la graisse de l’agneau du sacrifice de prospérités, et le Sacrificateur les fera fumer sur l’autel par dessus les sacrifices de l’Eternel faits par feu, et il fera propitiation pour lui, touchant son péché qu’il aura commis, et il lui sera pardonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Et quand quelqu’un aura péché lorsqu’il aura ouï quelqu’un proférant quelque parole exécrable, et en aura été témoin, soit qu’il l’ait vu ou qu’il l’ait su, et ne l’aura point déclaré, il portera son iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Ou quand quelqu’un aura touché une chose souillée, soit la charogne des bêtes sauvages immondes, soit la charogne des animaux domestiques immondes, soit la charogne des reptiles, lesquels sont immondes, quoiqu’il ne s’en soit pas aperçu, il est toutefois souillé, et coupable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Ou quand il aura touché à la souillure d’un homme, à quelle que ce soit de ses souillures; soit qu’il ne s’en soit pas aperçu, soit qu’il l’ait connu, il est coupable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Ou quand quelqu’un aura juré en proférant légèrement de ses lèvres de faire du mal ou du bien, selon tout ce que l’homme profère légèrement en jurant, soit qu’il ne s’en soit pas aperçu, soit qu’il l’ait connu, il est coupable dans l’un de ces points.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Quand donc quelqu’un sera coupable en l’un de ces points-là, il confessera en quoi il aura péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'Et il amènera la victime de son péché à l’Eternel pour le péché qu’il aura commis, savoir une femelle du menu bétail, soit une jeune brebis, soit une jeune chèvre, pour le péché; et le Sacrificateur fera propitiation pour lui de son péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Et s’il n’a pas le moyen de trouver une brebis ou une chèvre, il apportera à l’Eternel pour offrande du péché qu’il aura commis, deux tourterelles, ou deux pigeonneaux; l’un en offrande pour le péché; et l’autre, pour l’holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Il les apportera, dis-je, au Sacrificateur, qui offrira premièrement celui qui est pour le péché; et il leur entamera la tête avec l’ongle vers le cou, sans la séparer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Puis il fera aspersion du sang du sacrifice pour le péché sur un côté de l’autel; et ce qui restera du sang on l’épreindra au pied de l’autel; car c’est un sacrifice pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Et de l’autre il en fera un holocauste, selon l’ordonnance, et le Sacrificateur fera pour lui la propitiation pour son péché qu’il aura commis; et il lui sera pardonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Que si celui qui aura péché n’a pas le moyen de trouver deux tourterelles, ou deux pigeonneaux, il apportera pour son offrande la dixième partie d’un Epha de fine farine, mais il ne mettra sur elle ni huile ni encens; car c’est une offrande pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Il l’apportera au Sacrificateur, qui en prendra une poignée pour mémorial de cette offrande, et la fera fumer sur l’autel, sur les sacrifices faits par feu à l’Eternel; car c’est une offrande pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Ainsi le Sacrificateur fera propitiation pour lui, pour son péché qu’il aura commis en l’une de ces choses-là, et il lui sera pardonné; et le reste sera pour le Sacrificateur, comme étant une offrande de gâteau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Quand quelqu’un aura commis un crime et un péché par erreur, en retenant des choses sanctifiées à l’Eternel, il amènera une victime pour son péché à l’Eternel; savoir un bélier sans tare, pris du troupeau, avec l’estimation que tu feras de la chose sainte, la faisant en sicles d’argent, selon le sicle du Sanctuaire, à cause de son péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Il restituera donc ce en quoi il aura péché en retenant de la chose sainte, et il y ajoutera un cinquième par dessus, et le donnera au Sacrificateur; et le Sacrificateur fera propitiation pour lui, par le bélier du sacrifice pour le péché, et il lui sera pardonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Et quand quelqu’un aura péché, et aura violé quelqu’un des commandements de l’Eternel, en commettant des choses qu’on ne doit point faire, et qu’il ne l’aura point su, il sera coupable, et portera son iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Il amènera donc au Sacrificateur un bélier sans tare pris du troupeau, avec l’estimation que tu feras de la faute; et le Sacrificateur fera propitiation pour lui de la faute qu’il aura commise par erreur, et dont il ne se sera point aperçu; et ainsi il lui sera pardonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Il y a du péché; certainement il s’est rendu coupable contre l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Quand quelque personne aura péché, et aura commis un crime contre l’Eternel, en mentant à son prochain pour un dépôt, ou pour une chose qu’on aura mise entre ses mains, soit qu’il l’ait ravie, soit qu’il ait trompé son prochain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Ou s’il a trouvé quelque chose perdue, et qu’il mente à ce sujet; ou s’il jure faussement sur quelqu’une de toutes les choses qu’il arrive à l’homme de faire, en péchant à leur égard;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'S’il arrive donc qu’il ait péché, et qu’il soit trouvé coupable, il rendra la chose qu’il aura ravie, ou ce qu’il aura usurpé par tromperie, ou le dépôt qui lui aura été donné en garde, ou la chose perdue qu’il aura trouvée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Ou tout ce dont il aura juré faussement; il restituera le principal, et il ajoutera un cinquième par dessus à celui-là qui il appartenait; il le donnera le jour qu’il aura été déclaré coupable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Et il amènera pour l’Eternel au Sacrificateur la victime de son péché, savoir un bélier sans tare, pris du troupeau, avec l’estimation que tu feras de la faute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Et le Sacrificateur fera propitiation pour lui devant l’Eternel; et il lui sera pardonné, pour tout ce qu’il aura fait en quoi il se sera rendu coupable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Commande à Aaron et à ses fils, et leur dis: C’est ici la Loi de l’holocauste; l’holocauste demeurera sur le feu qui est sur l’autel, toute la nuit jusqu’au matin, et le feu de l’autel y sera tenu allumé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Et le Sacrificateur, vêtu de sa robe de lin, mettra ses caleçons de lin sur sa chair, et il lèvera les cendres après que le feu aura consumé l’holocauste sur l’autel; puis il les mettra près de l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Alors il dépouillera ses vêtements, et s’étant vêtu d’autres habits, il transportera les cendres hors du camp, en un lieu net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Et quant au feu qui est sur l’autel, on l’y tiendra allumé, et on ne le laissera point éteindre. Le Sacrificateur allumera du bois au feu tous les matins, il arrangera l’holocauste sur le bois, et y fera fumer les graisses des offrandes de prospérités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'On tiendra le feu continuellement allumé sur l’autel, et on ne le laissera point éteindre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Et c’est ici la Loi de l’offrande du gâteau; les fils d’Aaron l’offriront devant l’Eternel sur l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Et on lèvera une poignée de la fleur de farine du gâteau, et de son huile, avec tout l’encens qui est sur le gâteau, et on le fera fumer en bonne odeur sur l’autel pour mémorial à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Et Aaron et ses fils mangeront ce qui en restera; on le mangera sans levain dans un lieu saint, on le mangera dans le parvis du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'On n’en cuira point qui soit fait avec du levain; je leur ai donné cela pour leur portion d’entre mes offrandes faites par feu; c’est une chose très-sainte, comme la victime pour le péché, et la victime pour le délit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Tout mâle d’entre les fils d’Aaron en mangera; c’est une ordonnance perpétuelle en vos âges touchant les offrandes faites par feu à l’Eternel; quiconque les touchera sera sanctifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'C’est ici l’offrande d’Aaron et de ses fils, laquelle ils offriront à l’Eternel le jour qu’il sera oint, savoir la dixième partie d’un Epha de fine farine, pour offrande perpétuelle; une moitié le matin, et l’autre moitié le soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Elle sera apprêtée sur une plaque avec de l’huile, tu l’apporteras ainsi rissolée, et tu offriras les pièces cuites du gâteau en bonne odeur à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Et le Sacrificateur d’entre ses fils qui sera oint en sa place, fera cela par ordonnance perpétuelle; on le fera fumer tout entier à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Et tout le gâteau du Sacrificateur sera consumé, sans en manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Parle à Aaron et à ses fils, et leur dis: C’est ici la Loi de la victime pour le péché; la victime pour le péché sera égorgée devant l’Eternel, dans le même lieu où l’holocauste sera égorgé; car c’est une chose très-sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Le Sacrificateur qui offrira la victime pour le péché, la mangera; elle se mangera dans un lieu saint, dans le parvis du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Quiconque touchera sa chair sera saint, et s’il en rejaillit quelque sang sur le vêtement, ce sur quoi le sang sera tombé sera lavé dans le lieu saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Et le vaisseau de terre dans lequel on l’aura fait bouillir, sera cassé; mais si on l’a fait bouillir dans un vaisseau d’airain, il sera écuré, et lavé dans l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Tout mâle d’entre les Sacrificateurs en mangera; c’est une chose très-sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Nulle victime pour le péché dont on portera du sang dans le Tabernacle d’assignation, pour faire la propitiation dans le Sanctuaire, ne sera mangée, mais elle sera brûlée au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Or c’est ici la loi de l’oblation pour le délit; c’est une chose très-sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Au même lieu où l’on égorgera l’holocauste, on égorgera la victime pour le délit; et on en répandra le sang sur l’autel à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Puis on en offrira toute la graisse, avec sa queue, et toute la graisse qui couvre les entrailles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'Et on en ôtera les deux rognons, et la graisse qui est sur eux jusque sur les flancs, et la taie qui est sur le foie pour la mettre sur les deux rognons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Et le Sacrificateur fera fumer toutes ces choses sur l’autel en offrande faite par feu à l’Eternel; c’est un sacrifice pour le délit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Tout mâle d’entre les sacrificateurs en mangera; il sera mangé dans un lieu saint, car c’est une chose très-sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'L’oblation pour le délit sera semblable à l’oblation pour le péché; il y aura une même loi pour les deux: et la victime appartiendra au Sacrificateur qui aura fait propitiation par elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Et le Sacrificateur qui offre l’holocauste pour quelqu’un, aura la peau de l’holocauste qu’il aura offert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Et tout gâteau cuit au four, et qui sera apprêté en la poêle, ou sur la plaque, appartiendra au Sacrificateur qui l’offre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Mais tout gâteau pétri à l’huile, ou sec, sera également pour tous les fils d’Aaron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Et c’est ici la Loi du Sacrifice de prospérités qu’on offrira à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Si quelqu’un l’offre pour rendre grâce, il offrira avec le Sacrifice d’action de grâces des tourteaux sans levain pétris à l’huile, et des beignets sans levain oints d’huile, et de la fleur de farine rissolée en tourteaux pétris à l’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Il offrira avec ces tourteaux du pain levé pour son offrande avec le sacrifice d’action de grâces pour ses prospérités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Et il en offrira une pièce de toutes les espèces qu’il offrira pour oblation élevée à l’Eternel; et cela appartiendra au Sacrificateur qui répandra le sang du sacrifice de prospérités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Mais la chair du sacrifice d’action de grâces de ses prospérités sera mangée le jour qu’elle sera offerte; on n’en laissera rien jusqu’au matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Que si le sacrifice de son offrande est un voeu, ou une offrande volontaire, il sera mangé le jour qu’on aura offert son sacrifice; et s’il y en a quelque reste, on le mangera le lendemain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Mais ce qui sera demeuré de reste de la chair du sacrifice, sera brûlé au feu le troisième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Que si on mange de la chair du sacrifice de ses prospérités le troisième jour, celui qui l’aura offert ne sera point agréé, et il ne lui sera point imputé comme une bonne action, ce sera une abomination, et la personne qui en aura mangé, portera son iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Et la chair de ce sacrifice qui aura touché quelque chose de souillé, ne se mangera point, elle sera brûlée au feu; mais quiconque sera net, mangera de cette chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Car une personne qui mangera de la chair du sacrifice de prospérités, laquelle appartient à l’Eternel, et qui aura sur soi quelque souillure, cette personne-là sera retranchée d’entre ses peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Si une personne touche quelque chose de souillé, soit souillure d’homme, soit bête souillée, ou telle autre chose souillée, et qu’il mange de la chair du sacrifice de prospérités, laquelle appartient à l’Eternel, cette personne-là sera retranchée d’entre ses peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Parle aux enfants d’Israël, et leur dis: Vous ne mangerez aucune graisse de boeuf ni d’agneau, ni de chèvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'On pourra bien se servir pour tout autre usage de la graisse d’une bête morte, ou de la graisse d’une bête déchirée par les bêtes sauvages, mais vous n’en mangerez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Car quiconque mangera de la graisse d’une bête dont on offre la graisse en sacrifice par feu à l’Eternel, la personne qui en aura mangé, sera retranchée d’entre ses peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Dans aucune de vos demeures vous ne mangerez point de sang, soit d’oiseaux, soit d’autres bêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Toute personne qui aura mangé de quelque sang que ce soit, sera retranchée d’entre ses peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Parle aux enfants d’Israël, et leur dis: Celui qui offrira le sacrifice de ses prospérités à l’Eternel, apportera à l’Eternel son offrande, qu’il prendra du sacrifice de ses prospérités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Ses mains, dis-je, apporteront les offrandes de l’Eternel qui se font par feu, c’est à savoir la graisse, il l’apportera avec la poitrine, offrant la poitrine pour la tournoyer en offrande tournoyée devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Puis le Sacrificateur fera fumer la graisse sur l’autel; mais la poitrine appartiendra à Aaron et à ses fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Vous donnerez aussi au Sacrificateur pour offrande élevée, l’épaule droite de vos sacrifices de prospérités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Celui d’entre les fils d’Aaron qui offrira le sang et la graisse des sacrifices de prospérités, aura pour sa part l’épaule droite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Car j’ai pris des enfants d’Israël la poitrine de tournoiement, et l’épaule d’élévation, de tous les sacrifices de leurs prospérités, et je les ai données à Aaron Sacrificateur, et à ses fils, par ordonnance perpétuelle, les ayant prises des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'C’est là le droit de l’onction d’Aaron et de l’onction de ses fils sur ces offrandes de l’Eternel faites par feu, depuis le jour qu’on les aura présentés pour exercer la sacrificature à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'Et ce que l’Eternel a commandé qui leur fût donné par les enfants d’Israël, depuis le jour qu’on les aura oints, pour être une ordonnance perpétuelle dans leurs âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Telle est donc la loi de l’holocauste, du gâteau, du sacrifice pour le péché, et du sacrifice pour le délit, et des consécrations, et du sacrifice de prospérités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'Laquelle l’Eternel ordonna à Moïse sur la montagne de Sinaï; lorsqu’il commanda aux enfants d’Israël d’offrir leurs offrandes à l’Eternel dans le désert de Sinaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'L’Eternel parla aussi à Moïse en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Prends Aaron et ses fils avec lui, les vêtements, l’huile d’onction, et un veau pour le sacrifice pour le péché, deux béliers, et une corbeille de pains sans levain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'Et convoque toute l’assemblée à l’entrée du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Et Moïse fit comme l’Eternel lui avait commandé; et l’assemblée fut convoquée à l’entrée du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Et Moïse dit à l’assemblée: C’ est ici ce que l’Eternel a commandé de faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Et Moïse fit approcher Aaron et ses fils, et les lava avec de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Et il mit sur Aaron la chemise, et le ceignit du baudrier, et le revêtit du Rochet, et mit sur lui l’Ephod, et le ceignit avec le ceinturon exquis de l’Ephod, dont il le ceignit par dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Puis il mit sur lui le Pectoral, après avoir mis au Pectoral Urim et Thummim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Il lui mit aussi la tiare sur la tête, et il mit sur le devant de la tiare la lame d’or, qui est la couronne de sainteté, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Puis Moïse prit l’huile de l’onction, et oignit le Tabernacle, et toutes les choses qui y étaient, et les sanctifia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Et il en fit aspersion sur l’autel par sept fois, et en oignit l’autel, tous ses ustensiles, la cuve, et son soubassement, pour les sanctifier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Il versa aussi de l’huile de l’onction sur la tête d’Aaron, et l’oignit pour le sanctifier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Puis Moïse ayant fait approcher les fils d’Aaron, les revêtit des chemises, et les ceignit de baudriers, et leur attacha des calottes, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Alors il fit approcher le veau de l’offrande pour le péché, et Aaron et ses fils posèrent leurs mains sur la tête du veau de l’offrande pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Et Moïse l’ayant égorgé prit de son sang, et en mit avec son doigt sur les cornes de l’autel à l’entour, et fit propitiation pour l’autel, et il répandit le reste du sang au pied de l’autel; ainsi il le sanctifia pour faire la propitiation sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Puis il prit toute la graisse qui était sur les entrailles, et la taie du foie, les deux rognons avec leur graisse, et Moïse les fit fumer sur l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Mais il fit brûler au feu hors du camp le veau avec sa peau, sa chair, et sa fiente, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Il fit aussi approcher le bélier de l’holocauste, et Aaron et ses fils posèrent leurs mains sur la tête du bélier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Et Moïse l’ayant égorgé, répandit le sang sur l’autel tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Puis il mit le bélier en pièces, et en fit fumer la tête, les pièces, et la fressure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Et il lava dans l’eau les entrailles et les jambes, et fit fumer tout le bélier sur l’autel; car c’était un holocauste de bonne odeur, c’était une offrande faite par feu à l’Eternel, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Il fit aussi approcher l’autre bélier, savoir le bélier des consécrations; et Aaron et ses fils posèrent les mains sur la tête du bélier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Et Moïse l’ayant égorgé prit de son sang, et le mit sur le mol de l’oreille droite d’Aaron, et sur le pouce de sa main droite, et sur le gros orteil de son pied droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Il fit aussi approcher les fils d’Aaron, et mit du même sang sur le mol de leur oreille droite, et sur le pouce de leur main droite, et sur le gros orteil de leur pied droit, et il répandit le reste du sang sur l’autel tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Après il prit la graisse, la queue, et toute la graisse qui est sur les entrailles, et la taie du foie, et les deux rognons avec leur graisse, et l’épaule droite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Il prit aussi de la corbeille des pains sans levain qui étaient devant l’Eternel, un gâteau sans levain, et un gâteau de pain fait à l’huile, et un beignet, et les mit sur les graisses, et sur l’épaule droite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Puis il mit toutes ces choses sur les paumes des mains d’Aaron, et sur les paumes des mains de ses fils, et les tournoya en offrande tournoyée devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Après Moïse les reçut d’entre leurs mains, et les fit fumer sur l’autel par dessus l’holocauste; car ce sont les consécrations de bonne odeur, c’est un sacrifice fait par feu à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Moïse prit aussi la poitrine du bélier des consécrations, et la tournoya devant l’Eternel, et ce fut la portion de Moïse, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Et Moïse prit de l’huile de l’onction, et du sang qui était sur l’autel, et il en fit aspersion sur Aaron et sur ses vêtements; sur ses fils, et sur les vêtements de ses fils avec lui; ainsi il sanctifia Aaron et ses vêtements; ses fils, et les vêtements de ses fils avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Après cela, Moïse dit à Aaron et à ses fils: Faites bouillir la chair à l’entrée du Tabernacle d’assignation, et vous la mangerez là, avec le pain qui est dans la corbeille des consécrations, comme le Seigneur me l’a commandé, en disant: Aaron et ses fils mangeront ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Mais vous brûlerez au feu ce qui sera demeuré de reste de la chair et du pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Et vous ne sortirez point pendant sept jours de l’entrée du Tabernacle d’assignation, jusqu’au temps que les jours de vos consécrations soient accomplis; car on emploiera sept jours à vous consacrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'L’Eternel a commandé de faire en ces autres jours comme on a fait en celui-ci, pour faire la propitiation en votre faveur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Vous demeurerez donc pendant sept jours à l’entrée du Tabernacle d’assignation, jour et nuit, et vous observerez ce que l’Eternel vous a ordonné d’observer, afin que vous ne mouriez point; car il m’a été ainsi commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Ainsi Aaron et ses fils firent toutes les choses que l’Eternel avait commandées par le moyen de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Et il arriva au huitième jour que Moïse appela Aaron et ses fils, et les Anciens d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Et il dit à Aaron: Prends un veau du troupeau pour l’offrande pour le péché, et un bélier pour l’holocauste, tous deux sans tare, et les amène devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Et tu parleras aux enfants d’Israël, en disant: Prenez un jeune bouc pour l’offrande pour le péché, un veau et un agneau, tous deux d’un an, qui soient sans tare, pour l’holocauste;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'Et un taureau et un bélier pour le sacrifice de prospérités, pour sacrifier devant l’Eternel, et un gâteau pétri à l’huile; car aujourd’hui l’Eternel vous apparaîtra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Ils prirent donc les choses que Moïse avait commandées, et les amenèrent devant le Tabernacle d’assignation; et toute l’assemblée s’approcha, et se tint devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Et Moïse dit: Faites ce que l’Eternel vous a commandé, et la gloire de l’Eternel vous apparaîtra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Et Moïse dit à Aaron: Approche-toi de l’autel, et fais ton offrande pour le péché, et ton holocauste, et fais propitiation pour toi, et pour le peuple; et présente l’offrande pour le peuple; et fais propitiation pour eux, comme l’Eternel l’a commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Alors Aaron s’approcha de l’autel, et égorgea le veau de son offrande pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Et les fils d’Aaron lui présentèrent le sang, et il trempa son doigt dans le sang, et le mit sur les cornes de l’autel; puis il répandit le reste du sang au pied de l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Mais il fit fumer sur l’autel la graisse, et les rognons, et la taie du foie de l’offrande pour le péché, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Et il brûla au feu la chair et la peau hors du camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Il égorgea aussi l’holocauste, et les fils d’Aaron lui présentèrent le sang, lequel il répandit sur l’autel tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Puis ils lui présentèrent l’holocauste coupé par pièces, et la tête, et il fit fumer ces choses-là sur l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Et il lava les entrailles et les jambes, qu’il fit fumer au dessus de l’holocauste sur l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Il offrit l’offrande du peuple, il prit le bouc de l’offrande pour le péché pour le peuple, il l’égorgea, et l’offrit pour le péché, comme la première offrande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Il l’offrit en holocauste, et agit selon l’ordonnance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Ensuite il offrit l’oblation du gâteau, et il en remplit la paume de sa main, et la fit fumer sur l’autel, outre l’holocauste du matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Il égorgea aussi le taureau et le bélier pour le sacrifice de prospérités, qui était pour le peuple; et les fils d’Aaron lui présentèrent le sang, lequel il répandit sur l’autel tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Ils présentèrent les graisses du taureau et du bélier, la queue, et ce qui couvre les entrailles, et les rognons, et la taie du foie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Et ils mirent les graisses sur les poitrines, et on fit fumer les graisses sur l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Et Aaron tournoya en offrande tournoyée devant l’Eternel les poitrines et l’épaule droite, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Aaron éleva aussi ses mains vers le peuple, et les bénit; et il descendit après avoir offert l’offrande pour le péché, l’holocauste, et le sacrifice de prospérités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Moïse donc et Aaron vinrent au Tabernacle d’assignation, et étant sortis ils bénirent le peuple; et la gloire de l’Eternel apparut à tout le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Car le feu sortit de devant l’Eternel, et consuma sur l’autel l’holocauste et les graisses; ce que tout le peuple ayant vu, ils s’écrièrent de joie, et se prosternèrent le visage contre terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Or les enfants d’Aaron, Nadab et Abihu, prirent chacun leur encensoir, et y ayant mis du feu, ils mirent dessus du parfum, et offrirent devant l’Eternel un feu étranger; ce qu’il ne leur avait point commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Et le feu sortit de devant l’Eternel; et les dévora; et ils moururent devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Et Moïse dit à Aaron: C’est ce dont l’Eternel avait parlé, en disant: Je serai sanctifié en ceux qui s’approchent de moi, et je serai glorifié en la présence de tout le peuple; et Aaron se tut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Et Moïse appela Misaël et Eltsaphan les fils de Huziel, oncle d’Aaron, et leur dit: Approchez-vous, emportez vos frères de devant le Sanctuaire hors du camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Alors ils s’approchèrent, et les emportèrent avec leurs chemises hors du camp, comme Moïse en avait parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Puis Moïse dit à Aaron, et à Eléazar et à Ithamar ses fils: Ne découvrez point vos têtes, et ne déchirez point vos vêtements, et vous ne mourrez point, et l’Eternel ne se mettra point en colère contre toute l’assemblée, mais que vos frères, toute la maison d’Israël, pleurent à cause de l’embrasement que l’Eternel a fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Et ne sortez point de l’entrée du Tabernacle d’assignation, de peur que vous ne mouriez; car l’huile de l’onction de l’Eternel est sur vous; et ils firent selon la parole de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Et l’Eternel parla à Aaron, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Vous ne boirez point de vin ni de cervoise, toi, ni tes fils avec toi, quand vous entrerez au Tabernacle d’assignation, de peur que vous ne mouriez; c’est une ordonnance perpétuelle en vos âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Afin que vous puissiez discerner entre ce qui est saint ou profane, entre ce qui est souillé ou net;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'Et afin que vous enseigniez aux enfants d’Israël toutes les ordonnances que l’Eternel leur aura prononcées par le moyen de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Puis Moïse parla à Aaron, et à Eléazar et à Ithamar ses fils, qui étaient demeurés de reste. Prenez, leur dit-il, l’offrande du gâteau qui est demeuré de reste des offrandes de l’Eternel faites par feu, et la mangez en pains sans levain auprès de l’autel; car c’ est une chose très-sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Vous la mangerez dans un lieu saint; parce que c’est la portion qui est assignée à toi, et à tes fils, des offrandes faites par feu à l’Eternel; car il m’a été ainsi commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Vous mangerez aussi la poitrine de tournoiement, et l’épaule d’élévation dans un lieu pur, toi, tes fils, et tes filles avec toi; car ces choses-là t’ont été données des sacrifices de prospérités des enfants d’Israël, pour ta portion, et pour celle de tes enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Ils apporteront l’épaule d’élévation, et la poitrine de tournoiement, avec les offrandes faites par feu, qui sont les graisses pour les faire tourner en offrande tournoyée devant l’Eternel; et cela t’appartiendra et à tes fils avec toi par une ordonnance perpétuelle, comme l’Eternel l’a commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Or Moïse cherchait soigneusement le bouc de l’offrande pour le péché, mais voici il avait été brûlé, et Moïse se mit en grande colère contre Eléazar et Ithamar, les fils d’Aaron qui étaient demeurés de reste, et leur dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Pourquoi n’avez-vous point mangé l’offrande pour le péché dans un lieu saint; car c’est une chose très-sainte; vu qu’elle vous a été donnée pour porter l’iniquité de l’assemblée, afin de faire propitiation pour eux devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Voici, son sang n’a point été porté dans le Sanctuaire; ne manquez donc plus à la manger dans le lieu saint, comme je l’avais commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Alors Aaron répondit à Moise: Voici, ils ont offert aujourd’hui leur offrande pour le péché et leur holocauste devant l’Eternel, et ces choses-ci me sont arrivées. Si j’eusse mangé aujourd’hui l’offrande pour le péché, cela eût-il plu à l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Ce que Moïse ayant entendu, il l’approuva.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Et l’Eternel parla à Moïse et à Aaron, et leur dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Parlez aux enfants d’Israël, et leur dites: Ce sont ici les animaux dont vous mangerez d’entre toutes les bêtes qui sont sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Vous mangerez d’entre les bêtes à quatre pieds de toutes celles qui ont l’ongle divisé, et qui ont le pied fourché, et qui ruminent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Mais vous ne mangerez point de celles qui ruminent seulement, ou qui ont l’ongle divisé seulement; comme le chameau, car il rumine bien, mais il n’a point l’ongle divisé; il vous est souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Et le lapin; car il rumine bien, mais il n’a point l’ongle divisé; il vous est souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Et le lièvre; car il rumine bien, mais il n’a point l’ongle divisé; il vous est souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Et le pourceau; car il a bien l’ongle divisé, et le pied fourché, mais il ne rumine nullement; il vous est souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Vous ne mangerez point de leur chair, même vous ne toucherez point leur chair morte; ils vous sont souillés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Vous mangerez de ceci d’entre tout ce qui est dans les eaux; vous mangerez de tout ce qui a des nageoires et des écailles dans les eaux, soit dans la mer, soit dans les fleuves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Mais vous ne mangerez de rien qui n’ait point de nageoires et d’écailles, soit dans la mer, soit dans les fleuves, tant des reptiles des eaux, que de toute chose vivante qui est dans les eaux; cela vous sera en abomination.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Elles vous seront donc en abomination, vous ne mangerez point de leur chair, et vous tiendrez pour une chose abominable leur chair morte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Tout ce donc qui vit dans les eaux, et qui n’a point de nageoires et d’écailles, vous sera en abomination.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Et d’entre les oiseaux vous tiendrez ceux-ci pour abominables, on n’en mangera point, ils vous seront en abomination: l’Aigle, l’Orfraie, le Faucon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'Le Vautour, et le Milan, selon leur espèce;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'Tout Corbeau selon son espèce;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'Le Chat-huant, la Hulotte, le Coucou, et l’Epervier, selon leur espèce;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'La Chouette, le Plongeon, le Hibou,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'Le Cygne, le Cormoran, le Pélican,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'La Cigogne, et le Héron, selon leur espèce, et la Huppe, et la Chauve- souris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Et tout reptile volant qui marche sur quatre pieds, vous sera en abomination.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Mais vous mangerez de tout reptile volant qui marche à quatre pieds, ayant des jambes sur ses pieds, pour sauter avec elles sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Ce sont donc ici ceux dont vous mangerez; l’Arbé selon son espèce, le Solham selon son espèce, l’Hargol selon son espèce; et le Kabag selon son espèce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Mais tout autre reptile volant qui a quatre pieds, vous sera en abomination.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Vous serez donc souillés par ces bêtes; quiconque touchera leur chair morte, sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Quiconque aussi portera de leur chair morte, lavera ses vêtements, et sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Toute bête qui a l’ongle divisé, et qui n’a point le pied fourché, et ne rumine point, vous sera souillée; quiconque les touchera, sera souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Et tout ce qui marche sur ses pattes, entre tous les animaux qui marchent à quatre pieds, vous sera souillé; quiconque touchera leur chair morte, sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Et celui qui portera de leur chair morte, lavera ses vêtements, et sera souillé jusqu’au soir; elles vous sont souillées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Ceci aussi vous sera souillé entre les reptiles, qui rampent sur la terre, la Belette, la Souris, et la Tortue, selon leur espèce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'Le Hérisson, le Crocodile, le Lézard, la Limace, et la Taupe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Ces choses vous sont souillées entre les reptiles; quiconque les touchera mortes, sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Aussi tout ce sur quoi il en tombera quelque chose, quand elles seront mortes, sera souillé, soit vaisseau de bois, soit vêtement, soit peau, ou sac, quelque vaisseau que ce soit dont on se sert à faire quelque chose, sera mis dans l’eau, et sera souillé jusqu’au soir, puis il sera net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Mais s’il en tombe quelque chose dans quelque vaisseau de terre que ce soit, tout ce qui est dedans sera souillé, et vous casserez le vaisseau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Et toute viande qu’on mange, sur laquelle il y aura eu de l’eau, sera souillée; tout breuvage qu’on boit dans quelque vaisseau que ce soit, en sera souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Et s’il tombe quelque chose de leur chair morte sur quoi que ce soit, cela sera souillé; le four et le foyer seront abattus; ils sont souillés, et ils vous seront souillés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Toutefois la fontaine, ou le puits, ou tel autre amas d’eaux seront nets. Celui donc qui touchera leur chair morte, sera souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Et s’il est tombé de leur chair morte sur quelque semence qui se sème, elle sera nette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Mais si on avait mis de l’eau sur la semence, et que quelque chose de leur chair morte tombe sur elle, elle vous sera souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Et quand quelqu’une des bêtes qui vous sont pour viande, sera morte d’elle- même, celui qui en touchera la chair morte, sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Et celui qui aura mangé de sa chair morte, lavera ses vêtements, et sera souillé jusqu’au soir. Celui aussi qui portera la chair morte de cette bête, lavera ses vêtements, et sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Tout reptile donc qui rampe sur la terre, vous sera en abomination, et on n’en mangera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Vous ne mangerez point de tout ce qui rampe sur la poitrine, ni de tout ce qui marche sur les quatre pieds, ni de tout ce qui a plusieurs pieds entre tous les reptiles qui se traînent sur la terre; car ils sont en abomination.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Ne rendez point vos personnes abominables par aucun reptile qui se traîne, et ne vous souillez point par eux: car vous seriez souillés par eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Parce que je suis l’Eternel votre Dieu. Vous vous sanctifierez donc, et vous serez saints; car je suis saint; ainsi vous ne souillerez point vos personnes par aucun reptile qui se traîne sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Car je suis l’Eternel, qui vous ai fait monter du pays d’Egypte, afin que je sois votre Dieu, et que vous soyez saints; car je suis saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Telle est la Loi touchant les bêtes, et les oiseaux, et tout animal ayant vie, qui se meut dans les eaux, et toute chose ayant vie, qui se traîne sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Afin de discerner entre la chose souillée et la chose nette, et entre les animaux qu’on peut manger, et les animaux dont on ne doit point manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Parle aux enfants d’Israël, et leur dis: Si la femme après avoir conçu, enfante un mâle, elle sera souillée pendant sept jours; elle sera souillée comme au temps de ses mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Et au huitième jour on circoncira la chair du prépuce de l’enfant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Et elle demeurera trente-trois jours au sang de sa purification, et ne touchera aucune chose sainte, et ne viendra point au Sanctuaire, jusqu’à ce que les jours de sa purification soient accomplis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Que si elle enfante une fille, elle sera souillée deux semaines, comme au temps de ses mois, et elle demeurera soixante-six jours au sang de sa purification.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Après que le temps de sa purification sera accompli, soit pour fils, ou pour fille, elle présentera au Sacrificateur un agneau d’un an en holocauste, et un pigeonneau, ou une tourterelle, en offrande pour le péché, à l’entrée du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Et le Sacrificateur offrira ces choses devant l’Eternel, et fera propitiation pour elle, et elle sera nettoyée du flux de son sang. Telle est la Loi de celle qui enfante un fils ou une fille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Que si elle n’a pas le moyen de trouver un agneau, alors elle prendra deux tourterelles, ou deux pigeonneaux, l’un pour l’holocauste, et l’autre en offrande pour le péché, et le Sacrificateur fera propitiation pour elle, et elle sera nettoyée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'L’Eternel parla aussi à Moïse et à Aaron, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'L’homme qui aura dans la peau de sa chair une tumeur, ou gâle, ou bouton, et que cela paraîtra dans la peau de sa chair comme une plaie de lèpre, on l’amènera à Aaron Sacrificateur, ou à un de ses fils Sacrificateurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Et le Sacrificateur regardera la plaie qui est dans la peau de sa chair, et si le poil de la plaie est devenu blanc, et si la plaie, à la voir, est plus enfoncée que la peau de sa chair, c’est une plaie de lèpre; le Sacrificateur donc le regardera, et le jugera souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Mais si le bouton est blanc en la peau de sa chair, et qu’à le voir il ne soit point plus enfoncé que la peau, et si son poil n est pas devenu blanc, le Sacrificateur fera enfermer pendant sept jours celui qui a la plaie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Et le Sacrificateur la regardera le septième jour, et s’il aperçoit que la plaie se soit arrêtée, et qu’elle n’ait point crû dans la peau, le Sacrificateur le fera renfermer pendant sept autres jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Et le Sacrificateur la regardera encore le septième jour suivant, et s’il aperçoit que la plaie s’est retirée, et qu’elle ne s’est point accrue sur la peau, le Sacrificateur le jugera net; c’est de la gâle, et il lavera ses vêtements, et sera net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Mais si la gâle a crû en quelque sorte que ce soit sur la peau, après qu’il aura été examiné par le Sacrificateur pour être jugé net, et qu’il aura été examiné pour la seconde fois par le Sacrificateur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Le Sacrificateur le regardera encore, et s’il aperçoit que la gâle ait crû sur la peau, le Sacrificateur le jugera souillé; c’est de la lèpre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Quand il y aura une plaie de lèpre en un homme; on l’amènera au Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Lequel le regardera; et s’il aperçoit qu’il y ait une tumeur blanche en la peau, et que le poil soit devenu blanc, et qu’il paraisse de la chair vive en la tumeur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'C’est une lèpre invétérée en la peau de sa chair, et le Sacrificateur le jugera souillé, et ne le fera point enfermer; car il est jugé souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Si la lèpre boutonne fort dans la peau, et qu’elle couvre toute la peau de la plaie, depuis la tête de cet homme jusqu’à ses pieds, autant qu’en pourra voir le Sacrificateur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'Le Sacrificateur le regardera, et s’il aperçoit que la lèpre ait couvert toute la chair de cet homme, alors il jugera net celui qui a la plaie; la plaie est devenue toute blanche; il est net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Mais le jour auquel on aura aperçu de la chair vive, il sera souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Alors le Sacrificateur regardera la chair vive, et le jugera souillé; la chair vive est souillée; c’est de la lèpre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Que si la chair vive se change, et devient blanche, alors il viendra vers le Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Et le Sacrificateur le regardera, et s’il aperçoit que la plaie soit devenue blanche, le Sacrificateur jugera net celui qui a la plaie: il est net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Si la chair a eu en sa peau un ulcère, qui soit guéri;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'Et qu’à l’endroit où était l’ulcère il y ait une tumeur blanche, ou une pustule blanche-roussâtre, il sera regardé par le Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Le Sacrificateur donc la regardera, et s’il aperçoit qu’à la voir elle soit plus enfoncée que la peau, et que son poil soit devenu blanc, alors le Sacrificateur le jugera souillé; c’est une plaie de lèpre, la lèpre a boutonné dans l’ulcère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Que si le Sacrificateur la regardant aperçoit que le poil ne soit point devenu blanc, et qu’elle ne soit point plus enfoncée que la peau; mais qu’elle se soit retirée, le Sacrificateur le fera enfermer pendant sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Que si elle s’est étendue en quelque sorte que ce soit sur la peau, le Sacrificateur le jugera souillé; c’est une plaie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Mais si le bouton s’arrête en son lieu, ne croissant point, c’est un feu d’ulcère; ainsi le Sacrificateur le jugera net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Que si la chair a en sa peau une inflammation de feu, et que la chair vive de la partie enflammée soit un bouton blanc-roussâtre, ou blanc seulement;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'Le Sacrificateur le regardera, et s’il aperçoit que le poil soit devenu blanc dans le bouton, et qu’à le voir il soit plus enfoncé que la peau, c’est de la lèpre, elle a boutonné dans l’inflammation; le Sacrificateur donc le jugera souillé; c’est une plaie de lèpre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Mais si le Sacrificateur le regardant aperçoit qu’il n’y a point de poil blanc au bouton, et qu’il n’est point plus bas que la peau, et qu’il s’est retiré, le Sacrificateur le fera enfermer pendant sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Puis le Sacrificateur le regardera le septième jour, et si le bouton a crû en quelque sorte que ce soit dans la peau, le Sacrificateur le jugera souillé; c’est une plaie de lèpre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Que si le bouton s’arrête en son lieu sans croître sur la peau, et s’est retiré, c’est une tumeur d’inflammation; et le Sacrificateur le jugera net; c’est un feu d’inflammation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Si l’homme ou la femme a une plaie en la tête, ou l’homme en la barbe,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'Le Sacrificateur regardera la plaie, et si à la voir elle est plus enfoncée que la peau, ayant en soi du poil jaunâtre délié, le Sacrificateur le jugera souillé; c’est de la teigne, c’est une lèpre de tête, ou de barbe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Et si le Sacrificateur regardant la plaie de la teigne, aperçoit, qu’à la voir elle n’est point plus enfoncée que la peau, et n’a en soi aucun poil noir, le Sacrificateur fera enfermer pendant sept jours celui qui a la plaie de la teigne;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Et le septième jour le Sacrificateur regardera la plaie, et s’il aperçoit que la teigne ne s’est point étendue, et qu’elle n’a aucun poil jaunâtre, et qu’à voir la teigne elle ne soit pas plus enfoncée que la peau;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'Celui qui a la plaie de la teigne se rasera, mais il ne rasera point l’endroit de la teigne, et le Sacrificateur fera enfermer pendant sept autres jours celui qui a la teigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Puis le Sacrificateur regardera la teigne au septième jour, et s’il aperçoit que la teigne ne s’est point étendue sur la peau, et qu’à la voir elle n’est point plus enfoncée que la peau, le Sacrificateur le jugera net, et cet homme lavera ses vêtements, et sera net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Mais si la teigne croît en quelque sorte que ce soit dans la peau, après sa purification,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'Le Sacrificateur la regardera; et s’il aperçoit que la teigne ait crû dans la peau, le Sacrificateur ne cherchera point de poil jaunâtre; il est souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Mais s’il aperçoit que la teigne se soit arrêtée, et qu il y soit venu du poil noir, la teigne est guérie; il est net, et le Sacrificateur le jugera net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Et si l’homme ou la femme ont dans la peau de leur chair des boutons, des boutons, dis-je, qui soient blancs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'Le Sacrificateur les regardera, et s’il aperçoit que dans la peau de leur chair il y ait des boutons retirés et blancs, c’est une tache blanche qui a boutonné dans la peau; il est donc net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Si l’homme a la tête pelée, il est chauve, et néanmoins il est net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Mais si sa tête est pelée du côté de son visage, il est chauve, et néanmoins il est net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Et si dans la partie pelée ou chauve, il y a une plaie blanche-roussâtre, c’est une lèpre qui a bourgeonné dans sa partie pelée ou chauve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Et le Sacrificateur le regardera, et s’il aperçoit que la tumeur de la plaie soit blanche-roussâtre dans sa partie pelée ou chauve, semblable à la lèpre de la peau de la chair;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'L’homme est lépreux, il est souillé; le Sacrificateur ne manquera pas de le juger souillé: sa plaie est en sa tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Or le lépreux en qui sera la plaie, aura ses vêtements déchirés, et sa tête nue, et il sera couvert sur la lèvre de dessus, et il criera: le souillé, le souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Pendant tout le temps qu’il aura cette plaie, il sera jugé souillé; il est souillé, il demeurera seul, et sa demeure sera hors du camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Et si le vêtement est infecté de la plaie de la lèpre, soit vêtement de laine, soit vêtement de lin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'Ou dans la chaîne, ou dans la trame du lin, ou de la laine, ou aussi dans la peau, ou dans quelque ouvrage que ce soit de pelleterie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'Et si cette plaie est verte, ou roussâtre dans le vêtement, ou dans la peau, ou dans la chaîne, ou dans la trame, ou dans quelque chose que ce soit de peau, ce sera une plaie de lèpre, et elle sera montrée au Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Et le Sacrificateur regardera la plaie, et fera enfermer pendant sept jours celui qui a la plaie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Et au septième jour il regardera la plaie; si la plaie est crue au vêtement, ou en la chaîne, ou en la trame, ou en la peau, ou en quelque ouvrage que ce soit de pelleterie, la plaie est une lèpre rongeante, elle est souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Il brûlera donc le vêtement, la chaîne, ou la trame de laine, ou de lin, et toutes les choses de peau, qui auront cette plaie; car c’est une lèpre rongeante, cela sera brûlé au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Mais si le Sacrificateur regarde, et aperçoit que la plaie ne soit point crue au vêtement, ou en la chaîne, ou en la trame, ou en quelque autre chose qui soit faite de peau;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'Le Sacrificateur commandera qu’on lave la chose où est la plaie, et il le fera enfermer pendant sept autres jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Que si le Sacrificateur, après qu’on aura fait laver la plaie, la regarde, et s’il aperçoit que la plaie n’ait point changé sa couleur, et qu’elle ne soit point accrue, c’est une chose souillée, tu la brûleras au feu; c’est une enfonçure en son envers, ou en son endroit pelé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Que si le Sacrificateur regarde, et aperçoit que la plaie se soit retirée après qu’on l’a fait laver, il la déchirera du vêtement, ou de la peau, ou de la chaîne, ou de la trame.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Que si elle paraît encore au vêtement, ou dans la chaîne, ou dans la trame, ou dans quelque chose que ce soit de peau, c’est une lèpre qui a boutonné; vous brûlerez au feu la chose où est la plaie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Mais si tu as lavé le vêtement, ou la chaîne, ou la trame, ou quelque chose de peau, et que la plaie s’en soit allée, il sera encore lavé; puis il sera net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Telle est la loi de la plaie de la lèpre au vêtement de laine, ou de lin, ou en la chaîne, ou en la trame, ou en quelque chose que ce soit de peau, pour la juger nette, ou souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'C’est ici la loi du lépreux pour le jour de la purification; il sera amené au Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'Et le Sacrificateur sortira hors du camp, et le regardera; et s’il aperçoit que la plaie de la lèpre soit guérie au lépreux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'Le Sacrificateur commandera qu’on prenne pour celui qui doit être nettoyé, deux passereaux vivants et nets, avec du bois de cèdre, et du cramoisi, et de l’hysope,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Et le Sacrificateur commandera qu’on coupe la gorge à l’un des passereaux sur un vaisseau de terre, sur de l’eau vive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Puis il prendra le passereau vivant, le bois de cèdre, le cramoisi, et l’hysope; et il trempera toutes ces choses avec le passereau vivant, dans le sang de l’autre passereau qui aura été égorgé sur de l’eau vive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Et il en fera aspersion par sept fois sur celui qui doit être nettoyé de la lèpre, et le nettoiera, et il laissera aller par les champs, le passereau vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Et celui qui doit être nettoyé lavera ses vêtements, et rasera tout son poil, et se lavera dans l’eau, et il sera net, et ensuite il entrera au camp, mais il demeurera sept jours hors de sa tente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Et au septième jour il rasera tout son poil, sa tête, sa barbe, les sourcils de ses yeux, tout son poil; il rasera, dis-je, tout son poil; puis il lavera ses vêtements et sa chair, et il sera net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Et au huitième jour il prendra deux agneaux sans tare, et une brebis d’un an sans tare, et trois dixièmes de fine farine à faire le gâteau, pétrie à l’huile, et un log d’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Et le Sacrificateur qui fait la purification, présentera celui qui doit être nettoyé, et ces choses-là, devant l’Eternel à l’entrée du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Puis le Sacrificateur prendra l’un des agneaux, et l’offrira en offrande pour le délit avec un log d’huile, et tournoiera ces choses devant l’Eternel, en oblation tournoyée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Et il égorgera l’agneau au lieu où l’on égorge l’offrande pour le péché, et l’holocauste, dans le lieu saint; car l’offrande pour le délit appartient au Sacrificateur, comme l’offrande pour le péché; c’est une chose très- sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Et le Sacrificateur prendra du sang de l’offrande pour le délit, et le mettra sur le mol de l’oreille droite de celui qui doit être nettoyé, et sur le pouce de sa main droite, et sur le gros orteil de son pied droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Puis le Sacrificateur prendra de l’huile du log, et en versera dans la paume de sa main gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Et le Sacrificateur trempera le doigt de sa main droite en l’huile qui est dans sa paume gauche, et fera aspersion de l’huile avec son doigt sept fois devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Et du reste de l’huile qui sera dans sa paume, le Sacrificateur en mettra sur le mol de l’oreille droite de celui qui doit être nettoyé, et sur le pouce de sa main droite, et sur le gros orteil de son pied droit, sur le sang pris de l’offrande pour le délit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Mais ce qui restera de l’huile sur la paume du Sacrificateur, il le mettra sur la tête de celui qui doit être nettoyé; et ainsi le Sacrificateur fera propitiation pour lui devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Ensuite le Sacrificateur offrira l’offrande pour le péché, et fera propitiation pour celui qui doit être nettoyé de sa souillure; puis il égorgera l’holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Et le Sacrificateur offrira l’holocauste et le gâteau sur l’autel, et fera propitiation pour celui qui doit être nettoyé; et il sera net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Mais s’il est pauvre, et s’il n’a pas le moyen de fournir ces choses, il prendra un agneau en offrande tournoyée pour le délit, afin de faire propitiation pour soi, et un dixième de fine farine pétrie à l’huile, pour le gâteau, avec un log d’huile;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'Et deux tourterelles ou deux pigeonneaux, selon qu’il pourra fournir, dont l’un sera pour le péché, et l’autre pour l’holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Et le huitième jour de sa purification il les apportera au Sacrificateur à l’entrée du Tabernacle d’assignation, devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Et le Sacrificateur recevra l’agneau de l’offrande pour le délit, et le log d’huile, et les tournoiera devant l’Eternel en offrande tournoyée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Et il égorgera l’agneau de l’offrande pour le délit; puis le Sacrificateur prendra du sang de l’offrande pour le délit, et le mettra sur le mol de l’oreille droite de celui qui doit être nettoyé, et sur le pouce de sa main droite, et sur le gros orteil de son pied droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Puis le Sacrificateur versera de l’huile dans la paume de sa main gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'Et avec le doigt de sa main droite il fera aspersion de l’huile qui est dans sa main gauche, sept fois devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Et il mettra de cette huile qui est dans sa paume, sur le mol de l’oreille droite de celui qui doit être nettoyé, et sur le pouce de sa main droite, et sur le gros orteil de son pied droit, sur le lieu du sang pris de l’offrande pour le délit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Après il mettra le reste de l’huile qui est dans sa paume sur la tête de celui qui doit être nettoyé, afin de faire propitiation pour lui devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Puis il sacrifiera l’une des tourterelles, ou l’un des pigeonneaux, selon ce qu’il aura pu fournir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'De ce donc qu’il aura pu fournir, l’un sera pour le péché, et l’autre pour l’holocauste, avec le gâteau; ainsi le Sacrificateur fera propitiation devant l’Eternel pour celui qui doit être nettoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Telle est la loi de celui auquel il y a une plaie de lèpre, et qui n’a pas le moyen de fournir à sa purification.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Puis l’Eternel parla à Moïse et à Aaron, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Quand vous serez entrés au pays de Canaan, que je vous donne en possession, si j’envoie une plaie de lèpre en quelque maison du pays que vous posséderez;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'Celui à qui la maison appartiendra viendra, et le fera savoir au Sacrificateur, en disant: Il me semble que j’aperçois comme une plaie en ma maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Alors le Sacrificateur commandera qu’on vide la maison avant qu’il y entre pour regarder la plaie; afin que rien de ce qui est dans la maison ne soit souillé, puis le Sacrificateur entrera pour voir la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Et il regardera la plaie, et s’il aperçoit que la plaie qui est aux parois de la maison, ait quelques fossettes tirant sur le vert, ou roussâtres, qui soient, à les voir, plus enfoncées que la paroi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'Le Sacrificateur sortira de la maison, à l’entrée, et fera fermer la maison pendant sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Et au septième jour le Sacrificateur retournera, et la regardera, et s’il aperçoit que la plaie se soit étendue sur les parois de la maison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'Alors il commandera d’arracher les pierres, auxquelles est la plaie, et de les jeter hors de la ville dans un lieu souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Il fera aussi racler l’enduit de la maison par dedans tout à l’entour, et l’enduit qu’on aura raclé, on le jettera hors de la ville en un lieu souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Puis on prendra d’autres pierres, et on les apportera au lieu des premières pierres, et on prendra d’autre mortier pour r’enduire la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Mais si la plaie retourne et boutonne en la maison, après qu’on aura arraché les pierres, et après qu’on l’aura raclée, et r’enduite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'Le Sacrificateur y entrera, et la regardera, et s’il aperçoit que la plaie soit accrue en la maison, c’est une lèpre rongeante en la maison; elle est souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'On démolira donc la maison, ses pierres, et son bois, avec tout son mortier, et on les transportera hors de la ville en un lieu souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Et si quelqu’un est entré dans la maison, pendant tout le temps que le Sacrificateur l’avait faite fermer, il sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Et celui qui dormira dans cette maison lavera ses vêtements; celui aussi qui mangera dans cette maison lavera ses vêtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Mais quand le Sacrificateur y sera entré, et qu’il aura aperçu que la plaie n’a point crû en cette maison, après l’avoir faite r’enduire, il jugera la maison nette; car sa plaie est guérie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Alors il prendra pour purifier la maison, deux passereaux, du bois de cèdre, du cramoisi, et de l’hysope.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Et il coupera la gorge à l’un des passereaux sur un vaisseau de terre, sur de l’eau vive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Et il prendra le bois de cèdre, l’hysope, le cramoisi, et le passereau vivant, et trempera le tout dans le sang du passereau qu’on aura égorgé, et dans l’eau vive; puis il fera aspersion dans la maison par sept fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Il purifiera donc la maison avec le sang du passereau, et avec l’eau vive, et avec le passereau vivant, le bois de cèdre, l’hysope, et le cramoisi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Puis il laissera aller hors de la ville par les champs le passereau vivant, et il fera propitiation pour la maison; et elle sera nette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Telle est la loi de toute plaie de lèpre, et de teigne;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'De lèpre de vêtement, et de maison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'De tumeur, de gâle, et de bouton;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'Pour enseigner en quel temps une chose est souillée, et en quel temps elle est nette; telle est la loi de la lèpre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'L’Eternel parla aussi à Moïse et à Aaron, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Parlez aux enfants d’Israël, et leur dîtes: Tout homme à qui la chair découle, sera souillé à cause de son flux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Et telle sera la souillure de son flux; quand sa chair laissera aller son flux, ou que sa chair retiendra son flux, c’est sa souillure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Tout lit sur lequel aura couché celui qui découle, sera souillé; et toute chose sur laquelle il se sera assis, sera souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Quiconque aussi touchera son lit lavera ses vêtements, et se lavera avec de l’eau; et il sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Et qui s’assiéra sur quelque chose sur laquelle celui qui découle se soit assis, lavera ses vêtements, et se lavera dans l’eau; et il sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Et celui qui touchera la chair de celui qui découle, lavera ses vêtements, et se lavera dans l’eau; et il sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Et si celui qui découle crache sur celui qui est net, celui qui était net lavera ses vêtements, et se lavera dans l’eau; et il sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Toute monture aussi que celui qui découle aura montée, sera souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Quiconque touchera quelque chose qui aura été sous lui, sera souillé jusqu’au soir; et quiconque portera de telle chose lavera ses vêtements, et se lavera dans l’eau; et il sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Quiconque aura été touché par celui qui découle, sans qu’il ait lavé ses mains dans l’eau, lavera ses vêtements; et il se lavera dans l’eau; et il sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Et le vaisseau de terre que celui qui découle aura touché, sera cassé; mais tout vaisseau de bois sera lavé dans l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Or quand celui qui découle sera purifié de son flux, il comptera sept jours pour sa purification, il lavera ses vêtements, et sa chair avec de l’eau vive, et ainsi il sera net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Et au huitième jour il prendra pour soi deux tourterelles, ou deux pigeonneaux, et il viendra devant l’Eternel à l’entrée du Tabernacle d’assignation, et les donnera au Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Et le Sacrificateur les sacrifiera, l’un en offrande pour le péché, et l’autre en holocauste; ainsi le Sacrificateur fera propitiation pour lui devant l’Eternel à cause de son flux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'L’homme aussi duquel sera sortie de la semence, lavera dans l’eau toute sa chair, et il sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Et tout habit, ou toute peau sur laquelle il y aura de la semence, sera lavée dans l’eau, et sera souillée jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Même la femme dont un tel homme aura la compagnie, se lavera dans l’eau avec son mari, et ils seront souillés jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Et quand la femme sera découlante, ayant son flux de sang en sa chair, elle sera séparée sept jours; et quiconque la touchera sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Toute chose sur laquelle elle aura couché, durant sa séparation, sera souillée; toute chose aussi sur laquelle elle aura été assise, sera souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Quiconque aussi touchera le lit de cette femme, lavera ses vêtements, et se lavera dans l’eau; et il sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Et quiconque touchera quelque chose sur laquelle elle se sera assise, lavera ses vêtements, et se lavera dans l’eau; et il sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Même si la chose que quelqu’un aura touchée était sur le lit, ou sur quelque chose sur laquelle elle était assise, quand quelqu’un aura touché cette chose-là; il sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Et si quelqu’un a habité avec elle tellement que ses fleurs soient sur lui, il sera souillé sept jours; et toute couche sur laquelle il dormira, sera souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Quand aussi la femme découle par flux de son sang plusieurs jours, sans que ce soit le temps de ses mois; ou quand elle découlera plus longtemps que le temps de ses mois, tout le temps du flux de sa souillure, elle sera souillée comme au temps de sa séparation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Toute couche sur laquelle elle couchera tous les jours de son flux, lui sera comme la couche de sa séparation; et toute chose sur laquelle elle s’assied sera souillée, comme pour la souillure de sa séparation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Et quiconque aura touché ces choses-là, lavera ses vêtements, et se lavera dans l’eau; et il sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Mais si elle est purifiée de son flux, elle comptera sept jours, et après elle sera nette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Et au huitième jour elle prendra deux tourterelles ou deux pigeonneaux, et les apportera au Sacrificateur à l’entrée du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Et le Sacrificateur en sacrifiera l’un en offrande pour le péché, et l’autre en holocauste; ainsi le Sacrificateur fera propitiation pour elle devant l’Eternel, à cause du flux de sa souillure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Ainsi vous séparerez les enfants d’Israël de leurs souillures, et ils ne mourront point à cause de leurs souillures, en souillant mon pavillon qui est au milieu d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Telle est la loi de celui qui découle, et de celui duquel sort la semence, qui le souille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'Telle est aussi la loi de celle qui est malade de ses mois, et de toute personne qui découle, et qui a son flux, soit mâle, soit femelle, et de celui qui couche avec celle qui est souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Or l’Eternel parla à Moïse après la mort des deux enfants d’Aaron, lorsque s’étant approchés de la présence de l’Eternel, ils moururent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'L’Eternel donc dit à Moïse: Parle à Aaron ton frère, et lui dis qu’il n’entre point en tout temps dans le Sanctuaire au dedans du voile devant le Propitiatoire, qui est sur l’Arche, afin qu’il ne meure point; car je me montrerai dans une nuée sur le Propitiatoire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Aaron entrera en cette manière dans le Sanctuaire, après qu’il aura offert un veau du troupeau pour le péché, et un bélier pour l’holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Il se revêtira de la sainte chemise de lin, ayant mis les caleçons de lin sur sa chair, et il se ceindra du baudrier de lin, et portera la tiare de lin, qui sont les saints vêtements, et il s’en vêtira après avoir lavé sa chair avec de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Et il prendra de l’assemblée des enfants d’Israël deux jeunes boucs en offrande pour le péché, et un bélier pour l’holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Puis Aaron offrira son veau en offrande pour le péché, et fera propitiation tant pour soi que pour sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Et il prendra les deux boucs, et les présentera devant l’Eternel, à l’entrée du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Puis Aaron jettera le sort sur les deux boucs; un sort pour l’Eternel, et un sort pour le bouc qui doit être Hazazel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Et Aaron offrira le bouc sur lequel le sort sera échu pour l’Eternel, et le sacrifiera en offrande pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Mais le bouc sur lequel le sort sera échu pour être Hazazel, sera présenté vivant devant l’Eternel pour faire propitiation par lui, et on l’enverra au désert pour être Hazazel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Aaron donc offrira son veau en offrande pour le péché, et fera propitiation pour soi et pour sa maison, il égorgera, dis-je, son veau qui est l’offrande pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Puis il prendra plein un encensoir de la braise du feu qui est sur l’autel devant l’Eternel, et ses pleines paumes de parfum de drogues pulvérisées, et il l’apportera de la maison dans le voile;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Et il mettra le parfum sur le feu devant l’Eternel; afin que la nuée du parfum couvre le Propitiatoire qui est sur le Témoignage; ainsi il ne mourra point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Il prendra aussi du sang du veau, et il en fera aspersion avec son doigt au devant du Propitiatoire vers l’Orient; il fera, dis-je, aspersion de ce sang-là sept fois avec son doigt devant le Propitiatoire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Il égorgera aussi le bouc du peuple, qui est l’offrande pour le péché, et il apportera son sang au dedans du voile, et fera de son sang comme il a fait du sang du veau, en faisant aspersion vers le Propitiatoire; sur le devant du Propitiatoire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Et il fera expiation pour le Sanctuaire, le nettoyant des souillures des enfants d’Israël, et de leurs fautes, selon tous leurs péchés; et il fera la même chose au Tabernacle d’assignation, qui demeure avec eux au milieu de leurs souillures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Et personne ne sera au Tabernacle d’assignation quand le Sacrificateur y entrera pour faire propitiation dans le Sanctuaire, jusqu’à ce qu’il en sorte, lorsqu’il fera propitiation pour soi et pour sa maison, et pour toute l’assemblée d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Puis il sortira vers l’autel qui est devant l’Eternel, et fera expiation pour lui; et prenant du sang du veau et du sang du bouc, il le mettra sur les cornes de l’autel tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Et il fera par sept fois aspersion du sang avec son doigt sur l’autel, et le nettoiera et le sanctifiera des souillures des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Et quand il aura achevé de faire expiation pour le Sanctuaire, et pour le Tabernacle d’assignation, et pour l’autel, alors il offrira le bouc vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Et Aaron posant ses deux mains sur la tête du bouc vivant, confessera sur lui toutes les iniquités des enfants d’Israël, et toutes leurs fautes, selon tous leurs péchés, et il les mettra sur la tête du bouc, et l’enverra au désert par un homme exprès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Et le bouc portera sur soi toutes leurs iniquités dans une terre inhabitable, puis cet homme laissera aller le bouc par le désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Et Aaron reviendra au Tabernacle d’assignation, et quittera les vêtements de lin dont il s’était vêtu quand il était entré au Sanctuaire, et les posera là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Il lavera aussi sa chair avec de l’eau dans le lieu saint, et se revêtira de ses vêtements; puis étant sorti, il offrira son holocauste, et l’holocauste du peuple, et fera propitiation pour soi, et pour le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Il fera aussi fumer sur l’autel la graisse de l’offrande pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Et celui qui aura conduit le bouc pour être Hazazel, lavera ses vêtements et sa chair avec de l’eau; puis il rentrera au camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Mais on tirera hors du camp le veau et le bouc qui auront été offerts en offrande pour le péché, et desquels le sang aura été porté au Sanctuaire pour y faire propitiation, et on brûlera au feu leur peau, leur chair, et leur fiente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Et celui qui les aura brûlés lavera ses vêtements et sa chair avec de l’eau; après quoi il rentrera au camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Et ceci vous sera pour une ordonnance perpétuelle. Le dixième jour du septième mois vous affligerez vos âmes, et vous ne ferez aucune oeuvre, tant celui qui est du pays, que l’étranger qui fait son séjour parmi vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Car en ce jour-là le Sacrificateur fera propitiation pour vous, afin de vous nettoyer; ainsi vous serez nettoyés de tous vos péchés en la présence de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Ce vous sera donc un Sabbat de repos, et vous affligerez vos âmes; c’est une ordonnance perpétuelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Et le Sacrificateur qu’on aura oint, et qu’on aura consacré pour exercer la sacrificature en la place de son père, fera propitiation, s’étant revêtu des vêtements de lin, qui sont les saints vêtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Et il fera expiation pour le saint Sanctuaire, pour le Tabernacle d’assignation, et pour l’autel, et pour les Sacrificateurs, et pour tout le peuple de l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Ceci donc vous sera pour une ordonnance perpétuelle, afin de faire propitiation pour les enfants d’Israël de tous leurs péchés une fois l’an; et on fit comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Parle à Aaron et à ses fils, et à tous les enfants d’Israël, et leur dis: C’est ici ce que l’Eternel a commandé, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Quiconque de la maison d’Israël aura égorgé un boeuf, ou un agneau, ou une chèvre dans le camp, ou qui l’aura égorgé hors du camp,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'Et ne l’aura point amené à l’entrée du Tabernacle d’assignation pour en faire une offrande à l’Eternel devant le pavillon de l’Eternel, le sang sera imputé à cet homme-là; il a répandu du sang; c’est pourquoi cet homme-là sera retranché du milieu de son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Afin que les enfants d’Israël amènent leurs sacrifices, lesquels ils sacrifient dans les champs, qu’ils les amènent, dis-je, à l’Eternel, à l’entrée du Tabernacle d’assignation, vers le Sacrificateur, et qu’ils les sacrifient en sacrifices de prospérités à l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Et que le Sacrificateur en répande le sang sur l’autel de l’Eternel à l’entrée du Tabernacle d’assignation, et en fasse fumer la graisse en bonne odeur à l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Et qu’ils n’offrent plus leurs sacrifices aux diables, avec lesquels ils ont paillardé. Que ce leur soit une ordonnance perpétuelle en leurs âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Tu leur diras donc: Quiconque des enfants d’Israël, ou des étrangers qui font leur séjour parmi eux, aura offert un holocauste ou un sacrifice,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'Et qui ne l’aura point amené à l’entrée du Tabernacle d’assignation, pour le sacrifier à l’Eternel, cet homme-là sera retranché d’entre ses peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Quiconque de la famille d’Israël ou des étrangers qui font leur séjour parmi eux, aura mangé de quelque sang que ce soit, je mettrai ma face contre cette personne qui aura mangé du sang, et je la retrancherai du milieu de son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Car l’âme de la chair est dans le sang; c’est pourquoi je vous ai ordonné qu’il soit mis sur l’autel afin de faire propitiation pour vos âmes; car c’est le sang qui fera propitiation pour l’âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'C’est pourquoi j’ai dit aux enfants d’Israël: Que personne d’entre vous ne mange du sang; que l’étranger même qui fait son séjour parmi vous, ne mange point de sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Et quiconque des enfants d’Israël, et des étrangers qui font leur séjour parmi eux, aura pris à la chasse une bête sauvage, ou un oiseau que l’on mange, il répandra leur sang, et le couvrira de poussière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Car l’âme de toute chair est dans son sang, c’est son âme; c’est pourquoi j’ai dit aux enfants d’Israël: Vous ne mangerez point le sang d’aucune chair; car l’âme de toute chair est son sang; quiconque en mangera sera retranché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Et toute personne qui aura mangé de la chair de quelque bête morte d’elle- même, ou déchirée par les bêtes sauvages, tant celui qui est né au pays que l’étranger, lavera ses vêtements, et se lavera avec de l’eau, et il sera souillé jusqu’au soir; puis il sera net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Que s’il ne lave pas ses vêtements, et sa chair, il portera son iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'L’Eternel parla encore à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Parle aux enfants d’Israël, et leur dis: Je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Vous ne ferez point ce qui se fait au pays d’Egypte où vous avez habité, ni ce qui se fait au pays de Canaan, auquel je vous amène; et vous ne vivrez point selon leurs statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Mais vous ferez selon mes statuts, et vous garderez mes ordonnances pour marcher en elles; je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Vous garderez donc mes statuts, et mes ordonnances, lesquelles si l’homme accomplit, il vivra par elles; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Que nul ne s’approche de celle qui est sa proche parente pour découvrir sa nudité; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Tu ne découvriras point la nudité de ton père, ni la nudité de ta mère; c’ est ta mère, tu ne découvriras point sa nudité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Tu ne découvriras point la nudité de la femme de ton père; c’est la nudité de ton père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Tu ne découvriras point la nudité de ta soeur, fille de ton père, ou fille de ta mère, née dans la maison, ou hors de la maison; tu ne découvriras point leur nudité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Quant à la nudité de la fille de ton fils, ou de la fille de ta fille, tu ne découvriras point leur nudité, car elles sont ta nudité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Tu ne découvriras point la nudité de la fille de la femme de ton père, née de ton père, c’est ta soeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Tu ne découvriras point la nudité de la soeur de ton père; elle est proche parente de ton père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Tu ne découvriras point la nudité de la soeur de ta mère; car elle est proche parente de ta mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Tu ne découvriras point la nudité du frère de ton père, et ne t’approcheras point de sa femme; elle est ta tante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Tu ne découvriras point la nudité de ta belle-fille; elle est la femme de ton fils, tu ne découvriras point sa nudité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Tu ne découvriras point la nudité de la femme de ton frère, c’est la nudité de ton frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Tu ne découvriras point la nudité d’une femme et de sa fille, et ne prendras point la fille de son fils, ni la fille de sa fille pour découvrir leur nudité, elles sont tes proches parentes; c’est une énormité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Tu ne prendras point aussi une femme avec sa soeur pour l’affliger en découvrant sa nudité sur elle, pendant sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Tu n’approcheras point de la femme durant la séparation de sa souillure, pour découvrir sa nudité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Tu n’auras point aussi la compagnie de la femme de ton prochain, te souillant avec elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Tu ne donneras point de tes enfants pour les faire passer par le feu devant Molec, et tu ne profaneras point le Nom de ton Dieu; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Tu n’auras point aussi la compagnie d’un mâle; c’est une abomination.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Tu ne t’approcheras point aussi d’aucune bête pour te souiller avec elle; et la femme ne se prostituera point à une bête; c’est une confusion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Ne vous souillez point en aucune de ces choses; car les nations que je m’en vais chasser de devant vous, se sont souillées en toutes ces choses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Dont la terre a été souillée, et je m’en vais punir sur elle son iniquité, et la terre vomira ses habitants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Mais quant à vous, vous garderez mes ordonnances et mes jugements, et vous ne ferez aucune de ces abominations, tant celui qui est né au pays, que l’étranger qui fait son séjour parmi vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Car les gens de ce pays-là qui ont été avant vous, ont fait toutes ces abominations, et la terre en a été souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'La terre ne vous vomirait-elle point, si vous la souilliez, comme elle aura vomi les gens qui y ont été avant vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Car quiconque fera aucune de toutes ces abominations, les personnes qui les auront faites seront retranchées du milieu de leur peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Vous garderez donc ce que j’ai ordonné de garder, et vous ne pratiquerez aucune de ces coutumes abominables qui ont été pratiquées avant vous, et vous ne vous souillerez point par elles; je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Parle à toute l’assemblée des enfants d’Israël, et leur dis: Soyez saints; car je suis saint, moi l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Vous craindrez chacun sa mère et son père, et vous garderez mes Sabbats; je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Vous ne vous tournerez point vers les idoles, et ne vous ferez aucuns dieux de fonte; je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Si vous offrez un sacrifice de prospérités à l’Eternel, vous le sacrifierez de votre bon gré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'II se mangera au jour que vous l’aurez sacrifié, et le lendemain, mais ce qui restera jusqu’au troisième jour, sera brûlé au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Que si on en mange au troisième jour, ce sera une abomination; il ne sera point agréé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Quiconque aussi en mangera, portera son iniquité; car il aura profané la chose sainte de l’Eternel; et cette personne-là sera retranchée d’entre ses peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Et quand vous ferez la moisson de votre terre, tu n’achèveras point de moissonner le bout de ton champ, et tu ne glaneras point ce qui restera à cueillir de ta moisson.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Et tu ne grappilleras point ta vigne, ni ne recueilleras point les grains tombés de ta vigne, mais tu les laisseras au pauvre et à l’étranger; je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Vous ne déroberez point, ni ne dénierez point la chose à qui elle appartient; et aucun de vous ne mentira à son prochain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Vous ne jurerez point par mon Nom en mentant; car tu profanerais le Nom de ton Dieu; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Tu n’opprimeras point ton prochain, et tu ne le pilleras point. Le salaire de ton mercenaire ne demeurera point par devers toi jusqu’au matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Tu ne maudiras point le sourd, et tu ne mettras point d’achoppement devant l’aveugle, mais tu craindras ton Dieu; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Vous ne ferez point d’iniquité en jugement; tu n’auras point d’égard à la personne du pauvre, et tu n’honoreras point la personne du grand, mais tu jugeras justement ton prochain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Tu n’iras point médisant parmi ton peuple. Tu ne t’élèveras point contre le sang de ton prochain; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Tu ne haïras point ton frère en ton coeur. Tu reprendras soigneusement ton prochain, et tu ne souffriras point de péché en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Tu n’useras point de vengeance, et tu ne la garderas point aux enfants de ton peuple; mais tu aimeras ton prochain comme toi-même; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Vous garderez mes ordonnances. Tu n’accoupleras point tes bêtes avec d’autres de diverse espèce. Tu ne sèmeras point ton champ de diverses sortes de grains, et tu ne mettras point sur toi de vêtements de diverses espèces, comme de laine et de lin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Si un homme a couché avec une femme, laquelle étant esclave fut fiancée à un homme, et qu’elle n’ait pas été rachetée, et que la liberté ne lui ait pas été donnée, ils auront le fouet; mais on ne les fera point mourir; parce qu’elle n’avait pas été affranchie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Et l’homme amènera son offrande pour le délit à l’Eternel à l’entrée du Tabernacle d’assignation, savoir un bélier pour le délit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Et le Sacrificateur fera propitiation pour lui devant l’Eternel par le bélier de l’offrande pour le délit, à cause de son péché qu’il aura commis; et son péché qu’il aura commis lui sera pardonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Et quand vous serez entrés au pays, et que vous y aurez planté quelque arbre fruitier, vous tiendrez son fruit pour son prépuce; il vous sera incirconcis pendant trois ans, et on n’en mangera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Mais en la quatrième année tout son fruit sera une chose sainte, pour en louer l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Et en la cinquième année vous mangerez son fruit, afin qu’il vous multiplie son rapport; je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Vous ne mangerez rien avec le sang. Vous n’userez point de divinations, et vous ne pronostiquerez point le temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Vous ne tondrez point en rond les coins de votre tête, et vous ne gâterez point les coins de votre barbe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Vous ne ferez point d’incisions dans votre chair pour un mort, et vous n’imprimerez point de caractère sur vous; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Tu ne souilleras point ta fille en la prostituant pour la faire paillarder; afin que la terre ne soit point souillée par la paillardise, et ne soit point remplie d’énormité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Vous garderez mes Sabbats, et vous aurez en révérence mon Sanctuaire; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Ne vous détournez point après ceux qui ont l’esprit de Python, ni après les devins; ne cherchez point de vous souiller par eux; je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Lève-toi devant les cheveux blancs, et honore la personne du vieillard, et crains ton Dieu; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Si quelque étranger habite en votre pays, vous ne lui ferez point de tort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'L’étranger qui habite parmi vous, vous sera comme celui qui est né parmi vous, et vous l’aimerez comme vous-mêmes; car vous avez été étrangers au pays d’Egypte. Je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Vous ne ferez point d’iniquité en jugement, ni en règle, ni en poids, ni en mesure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Vous aurez les balances justes, les pierres à peser justes, l’Epha juste, et le Hin juste. Je suis l’Eternel votre Dieu qui vous ai retirés du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Gardez donc toutes mes ordonnances, et mes jugements, et les faites; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Tu diras aux enfants d’Israël: Quiconque des enfants d’Israël, ou des étrangers qui demeurent en Israël, donnera de sa postérité à Molec, sera puni de mort; le peuple du pays l’assommera de pierres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Et je mettrai ma face contre un tel homme, et je le retrancherai du milieu de son peuple, parce qu’il aura donné de sa postérité à Molec, pour souiller mon Sanctuaire, et profaner le Nom de ma Sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Que si le peuple du pays ferme les yeux en quelque manière que se soit, pour ne point voir quand cet homme-là aura donné de sa postérité à Molec, et ne le point faire mourir;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'Je mettrai ma face contre cet homme-là, et contre sa famille, et je le retrancherai du milieu de mon peuple, avec tous ceux qui paillardent à son exemple, en paillardant après Molec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Quant à la personne qui se détournera après ceux qui ont l’esprit de Python, et après les devins, en paillardant après eux, je mettrai ma face contre cette personne-là, et je la retrancherai du milieu de son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Sanctifiez-vous donc, et soyez saints; car je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Gardez aussi mes ordonnances, et les faites; je suis l’Eternel qui vous sanctifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Quand quelqu’un aura maudit son père ou sa mère, on le fera mourir de mort; il a maudit son père ou sa mère, son sang est sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Quant à l’homme qui aura commis adultère avec la femme d’un autre, parce qu’il a commis adultère avec la femme de son prochain, on fera mourir de mort l’homme et la femme adultères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'L’homme qui aura couché avec la femme de son père, a découvert la nudité de son père; on les fera mourir de mort tous deux, leur sang est sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Et quand un homme aura couché avec sa belle-fille, on les fera mourir de mort tous deux; ils ont fait une confusion; leur sang est sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Quand un homme aura eu la compagnie d’un mâle, ils ont tous deux fait une chose abominable; on les fera mourir de mort, leur sang est sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Et quand un homme aura pris une femme, et la mère de cette femme, c’est une énormité, il sera brûlé au feu avec elles, afin qu’il n’y ait point d’énormité au milieu de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'L’homme qui se sera souillé avec une bête, sera puni de mort; vous tuerez aussi la bête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Et quand quelque femme se sera prostituée à quelque bête, tu tueras cette femme et la bête; on les fera mourir de mort, leur sang est sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Quand un homme aura pris sa soeur, fille de son père, ou fille de sa mère, et aura vu sa nudité, et qu’elle aura vu la nudité de cet homme; c’est une chose infâme; ils seront donc retranchés en la présence des enfants de leur peuple; il a découvert la nudité de sa soeur, il portera son iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Quand un homme aura couché avec une femme qui a ses mois, et qu’il aura découvert la nudité de cette femme, en découvrant son flux, et qu’elle aura découvert le flux de son sang; ils seront tous deux retranchés du milieu de leur peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Tu ne découvriras point la nudité de la soeur de ta mère, ni de la soeur de ton père; parce qu’il aura découvert sa chair, ils porteront tous deux leur iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Et quand un homme aura couché avec sa tante, il a découvert la nudité de son oncle; ils porteront leur péché, et ils mourront sans en laisser d’enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Et quand un homme aura pris la femme de son frère, c’est une ordure; il a découvert la honte de son frère, ils n’ en auront point d’enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Ainsi gardez toutes mes ordonnances, et mes jugements, et observez-les; et le pays auquel je vous fais entrer pour y habiter ne vous vomira point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Vous ne suivrez point aussi les ordonnances des nations que je m’en vais chasser de devant vous; car elles ont fait toutes ces choses-là, et je les ai eues en abomination.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Et je vous ai dit: Vous posséderez leur pays, et je vous le donnerai pour le posséder; c’est un pays découlant de lait et de miel. Je suis l’Eternel votre Dieu, qui vous ai séparés des autres peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'C’est pourquoi séparez la bête nette de la souillée, l’oiseau net d’avec le souillé, et ne rendez point abominables vos personnes en mangeant des bêtes et des oiseaux immondes, ni rien qui rampe sur la terre, rien de ce que je vous ai défendu comme une chose immonde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Vous me serez donc saints; car je suis saint, moi l’Eternel, et je vous ai séparés des autres peuples, afin que vous soyez à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Quand un homme ou une femme aura un esprit de Python, ou sera devin, on les fera mourir de mort; on les assommera de pierres; leur sang est sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'L’Eternel dit aussi à Moïse: Parle aux Sacrificateurs, fils d’Aaron, et leur dis: Qu’aucun d’eux ne se souille entre ses peuples pour un mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Sinon pour son proche parent, qui le touche de près, savoir pour sa mère, pour son père, pour son fils, pour sa fille, et pour son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'Et quant à sa soeur vierge, qui le touche de près, et qui n’aura point eu de mari, il se souillera pour elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'S’il est marié il ne se souillera point pour sa femme parmi son peuple, en se rendant impur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Ils n’arracheront point les cheveux de leur tête pour la rendre chauve, et ils ne raseront point les coins de leur barbe, ni ne feront d’incision en leur chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Ils seront saints à leur Dieu, et ils ne profaneront point le nom de leur Dieu; car ils offrent les sacrifices de l’Eternel faits par feu, qui est la viande de leur Dieu; c’est pourquoi ils seront très-saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Ils ne prendront point une femme paillarde, ou déshonorée; ils ne prendront point aussi une femme répudiée par son mari; car ils sont saints à leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Tu feras donc que chacun d’eux soit saint, parce qu’ils offrent la viande de ton Dieu. Ils te seront donc saints, car je suis saint, moi l’Eternel qui vous sanctifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Si la fille du Sacrificateur se souille en commettant paillardise, elle souille son père; qu’elle soit donc brûlée au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Et le souverain Sacrificateur d’entre ses frères, sur la tête duquel l’huile de l’onction aura été répandue, et qui se sera consacré pour vêtir les saints vêtements, ne découvrira point sa tête, et ne déchirera point ses vêtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Il n’ira point vers aucune personne morte; il ne se rendra point impur pour son père, ni pour sa mère;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Et il ne sortira point du Sanctuaire, et ne souillera point le Sanctuaire de son Dieu; parce que la couronne, et l’huile de l’onction de son Dieu est sur lui. Je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Il prendra pour femme une vierge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Il ne prendra point une veuve; ni une répudiée, ni une femme déshonorée, ni une paillarde; mais il prendra pour femme une vierge d’entre ses peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Il ne souillera point sa postérité entre ses peuples; car je suis l’Eternel qui le sanctifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Parle à Aaron, et lui dis: Si quelqu’un de ta postérité dans ses âges a quelque défaut en son corps, il ne s’approchera point pour offrir la viande de son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Car aucun homme en qui il y aura quelque défaut n’en approchera; savoir l’homme aveugle, ou boiteux, ou camus, ou qui aura quelque superfluité dans ses membres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'Ou l’homme qui aura quelque fracture aux pieds, ou aux mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'Ou qui sera bossu, ou grêle, ou qui aura quelque suffusion en l’oeil, ou qui aura une gâle sèche, ou une gâle d’ulcère, ou qui sera rompu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Nul homme donc de la postérité d’Aaron Sacrificateur en qui il y aura quelque défaut, ne s’approchera pour offrir les offrandes faites par feu à l’Eternel; il y a un défaut en lui, il ne s’approchera donc point pour offrir la viande de son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Il pourra bien manger de la viande de son Dieu, savoir des choses très- saintes; et des choses saintes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Mais il n’entrera point vers le voile, ni ne s’approchera point de l’autel, parce qu’il y a en lui une défectuosité, de peur de souiller mes Sanctuaires; car je suis l’Eternel qui les sanctifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Moïse donc parla ainsi à Aaron et à ses fils, et à tous les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Puis l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Dis à Aaron et à ses fils, quand ils auront à s’abstenir des choses saintes des enfants d’Israël, afin qu’ils ne profanent point le nom de ma sainteté dans les choses qu’eux-mêmes me sanctifient; je suis l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Dis-leur donc: Tout homme de toute votre postérité en vos âges qui étant souillé s’approchera des choses saintes que les enfants d’Israël auront sanctifiées à l’Eternel, cette personne-là sera retranchée de ma présence; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Tout homme de la postérité d’Aaron étant lépreux, ou découlant, ne mangera point des choses saintes jusqu’à ce qu’il soit nettoyé; et celui aussi qui aura touché quelque homme souillé pour avoir touché un mort, et celui qui aura un flux de semence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'Et celui qui aura touché quelque reptile dont il soit souillé, ou quelque homme par lequel il soit souillé, quelque souillure qui puisse être en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'La personne qui aura touché ces choses sera souillée jusqu’au soir, et ne mangera point des choses saintes, si elle n’a lavé sa chair avec de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Ensuite, elle sera nette après le soleil couché; et elle mangera des choses saintes; car c’est sa viande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Il ne mangera point de la chair d’aucune bête morte d’elle-même, ou déchirée par les bêtes sauvages, pour se souiller par elle; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Qu’ils gardent donc ce que j’ai ordonné de garder, et qu’ils ne commettent point de péché au sujet de la viande sainte, afin qu’ils ne meurent point, pour l’avoir souillée; je suis l’Eternel qui les sanctifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Nul étranger aussi ne mangera des choses saintes; le forain logé chez le Sacrificateur, et le mercenaire, ne mangeront point des choses saintes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Mais quand le Sacrificateur aura acheté quelque personne de son argent, elle en mangera; pareillement celui qui sera né dans sa maison; ceux-ci mangeront de sa viande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Que si la fille du Sacrificateur est mariée à un étranger, elle ne mangera point des choses saintes, présentées en offrande élevée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Mais si la fille du Sacrificateur est veuve, ou répudiée, et si elle n’a point d’enfants, étant retournée en la maison de son père, comme elle y demeurait en sa jeunesse, elle mangera de la viande de son père; mais nul étranger n’en mangera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Que si quelqu’un par ignorance mange d’une chose sainte, il ajoutera un cinquième par dessus, et le donnera au Sacrificateur avec la chose sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Et ils ne souilleront point les choses sanctifiées des enfants d’Israël, qu’ils auront offertes à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'Mais on leur fera porter la peine du péché, parce qu’ils auront mangé de leurs choses saintes; car je suis l’Eternel qui les sanctifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'L’Eternel parla encore à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Parle à Aaron et à ses fils, et à tous les enfants d’Israël, et leur dis: Quiconque de la maison d’Israël, ou des étrangers qui sont en Israël, offrira son offrande, selon tous ses voeux, ou selon toutes ses offrandes volontaires, lesquelles on offre en holocauste à l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'Il offrira de son bon gré, un mâle sans tare, d’entre les vaches, ou d’entre les brebis, ou d’entre les chèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Vous n’offrirez aucune chose qui ait quelque tare, car elle ne serait point agréée pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Que si un homme offre à l’Eternel un sacrifice de prospérités en s’acquittant de quelque voeu, ou en faisant quelque offrande volontaire, soit de bœufs, ou de brebis, ce qui sera sans tare sera agréé; il n’y doit avoir aucune tare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Vous n’offrirez point à l’Eternel ce qui sera aveugle, ou rompu, ou mutilé, ou qui aura un porreau, ou une gâle sèche, ou une gâle d’ulcère, et vous n’en donnerez point pour le sacrifice qui se fait par feu sur l’autel à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Tu pourras bien faire une offrande volontaire, d’un boeuf, ou d’une brebis, ou d’une chèvre ayant quelque superfluité, ou quelque défaut dans ses membres, mais ils ne seront point agréés pour le voeu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Vous n’offrirez point à l’Eternel, et ne sacrifierez point en votre pays une bête qui ait les génitoires froissés, ou cassés, ou arrachés, ou taillés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Vous ne prendrez point aussi de la main de l’étranger aucune de toutes ces choses pour les offrir en viande à votre Dieu, car la corruption qui est en eux est une tare en elles; elles ne seront point agréées pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'L’Eternel parla encore à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Quand un veau, ou un agneau, ou une chèvre seront nés, et qu’ils auront été sept jours sous leur mère, depuis le huitième jour et les suivants, ils seront agréables pour l’offrande du sacrifice qui se fait par feu à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Vous n’égorgerez point aussi en un même jour la vache, ou la brebis, ou la chèvre, avec son petit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Quand vous offrirez un sacrifice d’action de grâces à l’Eternel, vous le sacrifierez de votre bon gré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Il sera mangé le jour même, et vous n’en réserverez rien jusqu’au matin; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Gardez donc mes commandements, et les faites.; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Et ne profanez point le nom de ma sainteté, car je serai sanctifié entre les enfants d’Israël; je suis l’Eternel qui vous sanctifie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Et qui vous ai retirés du pays d’Egypte, pour vous être Dieu; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'L’Eternel parla aussi à Moïse en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Parle aux enfants d’Israël, et leur dis: Les fêtes solennelles de l’Eternel, que vous publierez, seront de saintes convocations; et ce sont ici mes fêtes solennelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'On travaillera six jours, mais au septième jour, qui est le Sabbat du repos, il y aura une sainte convocation; vous ne ferez aucune œuvre, car c’est le Sabbat à l’Eternel, dans toutes vos demeures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Et ce sont ici les fêtes solennelles de l’Eternel, qui seront de saintes convocations, que vous publierez en leur saison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Au premier mois, le quatorzième jour du mois entre les deux vêpres, est la Pâque à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Et le quinzième jour de ce même mois est la fête solennelle des pains sans levain à l’Eternel; vous mangerez des pains sans levain pendant sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Le premier jour vous aurez une sainte convocation; vous ne ferez aucune oeuvre servile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Mais vous offrirez à l’Eternel pendant sept jours des offrandes faites par feu, et au septième jour il y aura une sainte convocation; vous ne ferez aucune oeuvre servile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Parle aux enfants d’Israël, et leur dis: Quand vous serez entrés au pays que je vous donne, et que vous en aurez fait la moisson, vous apporterez alors au Sacrificateur une poignée des premiers fruits de votre moisson.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Et il tournoiera cette poignée-là devant l’Eternel, afin qu’elle soit agréée pour vous; le Sacrificateur la tournoiera le lendemain du Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Et le jour que vous ferez tournoyer cette poignée, vous sacrifierez un agneau sans tare, et d’un an en holocauste à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Et le gâteau de cet holocauste sera de deux dixièmes de fine farine, pétrie à l’huile, pour offrande faite par feu à l’Eternel en bonne odeur; et son aspersion de vin sera la quatrième partie d’un Hin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Et vous ne mangerez ni pain, ni grain rôti, ni grain en épi, jusqu’à ce propre jour-là, même jusqu’à ce que vous ayez apporté l’offrande à votre Dieu; c’est une ordonnance perpétuelle en vos âges, dans toutes vos demeures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Vous compterez aussi dès le lendemain du Sabbat, savoir dès le jour que vous aurez apporté la poignée qu’on doit tournoyer, sept semaines entières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Vous compterez donc cinquante jours jusqu’au lendemain de la septième semaine; et vous offrirez à l’Eternel un gâteau nouveau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Vous apporterez de vos demeures deux pains, pour en faire une offrande tournoyée, ils seront de deux dixièmes, et de fine farine, pétris avec du levain; ce sont les premiers fruits à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Vous offrirez aussi avec ce pain-là sept agneaux sans tare, et d’un an, et un veau pris du troupeau, et deux béliers, qui seront un holocauste à l’Eternel, avec leurs gâteaux, et leurs aspersions, des sacrifices faits par feu en bonne odeur à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Vous sacrifierez aussi un jeune bouc en offrande pour le péché, et deux agneaux d’un an pour le sacrifice de prospérités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Et le Sacrificateur les tournoiera avec le pain des premiers fruits, et avec les deux agneaux, en offrande tournoyée devant l’Éternel; ils seront saints à l’Eternel pour le Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Vous publierez donc en ce même jour-là que vous avez une sainte convocation; vous ne ferez aucune oeuvre servile; c’est une ordonnance perpétuelle dans toutes vos demeures en vos âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Et quand vous ferez la moisson de votre terre tu n’achèveras point de moissonner le bout de ton champ, et tu ne glaneras point les épis qui resteront de ta moisson, mais tu les laisseras pour le pauvre, et pour l’étranger; je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Parle aux enfants d’Israël, et leur dis: Au septième mois, le premier jour du mois il y aura repos pour vous, un mémorial de jubilation, et une sainte convocation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Vous ne ferez aucune oeuvre servile, et vous offrirez à l’Eternel des offrandes faites par feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Pareillement en ce même mois, qui est le septième, le dixième jour sera le jour des propitiations; vous aurez une sainte convocation, et vous affligerez vos âmes, et vous offrirez à l’Eternel des sacrifices faits par feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'En ce jour-là vous ne ferez aucune oeuvre; car c’est le jour des propitiations, afin de faire propitiation pour vous devant l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Car toute personne qui n’aura pas été affligée en ce propre jour-là sera retranchée d’entre ses peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Et toute personne qui aura fait quelque oeuvre en ce jour-là, je ferai périr cette personne-là du milieu de son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Vous ne ferez donc aucune oeuvre; c’est une ordonnance perpétuelle en vos âges dans toutes vos demeures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Ce vous est un Sabbat de repos: vous affligerez donc vos âmes. Le neuvième jour du mois, au soir, depuis un soir jusqu’à l’autre soir, vous célébrerez votre repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Parle aux enfants d’Israël, et leur dis: Au quinzième jour de ce septième mois sera la fête solennelle des Tabernacles pendant sept jours, à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Au premier jour il y aura une sainte convocation; vous ne ferez aucune oeuvre servile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Pendant sept jours vous offrirez à l’Eternel des offrandes faites par feu; et au huitième jour vous aurez une sainte convocation, et vous offrirez à l’Eternel des offrandes faites, par feu; c’est une assemblée solennelle; vous ne ferez aucune oeuvre servile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Ce sont là les fêtes solennelles de l’Eternel, que vous publierez, pour être des convocations saintes, afin d’offrir à l’Eternel des offrandes faites par feu; savoir un holocauste, un gâteau, un sacrifice, et une aspersion; chacune de ces choses en son jour;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Outre les Sabbats de l’Eternel, et outre vos dons, et outre tous vos voeux, et outre toutes les offrandes volontaires que vous présenterez à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Et aussi au quinzième jour du septième mois, quand vous aurez recueilli le rapport de la terre, vous célébrerez la fête solennelle de l’Eternel pendant sept jours. Le premier jour sera jour de repos; le huitième aussi sera jour de repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Et au premier jour vous prendrez du fruit d’un bel arbre, des branches de palmier, et des rameaux d’arbres branchus, et des saules de rivière, et vous vous réjouirez pendant sept jours devant l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Et vous célébrerez à l’Eternel cette fête solennelle pendant sept jours en l’année; c’est une ordonnance perpétuelle en vos âges; vous la célébrerez le septième mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Vous demeurerez sept jours dans des tentes; tous ceux qui seront nés entre les Israélites demeureront dans des tentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'Afin que votre postérité sache que j’ai fait demeurer les enfants d’Israël dans des tentes, quand je les retirai du pays d’Egypte; je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Moïse déclara ainsi aux enfants d’Israël les fêtes solennelles de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Commande aux enfants d’Israël qu’ils t’apportent de l’huile vierge pour le luminaire, afin de faire brûler les lampes continuellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Aaron les arrangera devant l’Eternel continuellement, depuis le soir jusqu’au matin hors du voile du Témoignage dans le Tabernacle d’assignation; c’est une ordonnance perpétuelle en vos âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Il arrangera, dis-je, continuellement les lampes sur le chandelier pur, devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Tu prendras aussi de la fine farine, et tu en feras cuire douze gâteaux, chaque gâteau sera de deux dixièmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Et tu les exposeras devant l’Eternel par deux rangées sur la Table pure, six à chaque rangée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Et tu mettras de l’encens pur sur chaque rangée, qui sera un mémorial pour le pain; c’est une offrande faite par feu à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'On les arrangera chaque jour de Sabbat continuellement devant l’Eternel, de la part des enfants d’Israël; c’est une alliance perpétuelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Et ils appartiendront à Aaron, et à ses fils, qui les mangeront dans un lieu saint; car ils lui seront une chose très-sainte d’entre les offrandes de l’Eternel faites par feu; c’ est une ordonnance perpétuelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Or le fils d’une femme israélite, qui aussi était fils d’un homme Egyptien, sortit parmi les enfants d’Israël, et ce fils de la femme Israélite, et un homme Israélite se querellèrent dans le camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Et le fils de la femme Israélite blasphéma le nom de l’Eternel, et le maudit; et on l’amena à Moïse. Or sa mère s’appelait Sélomith, fille de Dibri, de la Tribu de Dan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Et on le mit en garde jusqu’à ce qu’on leur eût déclaré ce qu’ils en devraient faire selon la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Tire hors du camp celui qui a maudit; et que tous ceux qui l’ont entendu mettent les mains sur sa tête, et que toute l’assemblée le lapide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Et parle aux enfants d’Israël, et leur dis: Quiconque aura maudit son Dieu, portera son péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Et celui qui aura blasphémé le Nom de l’Eternel, sera puni de mort; toute l’assemblée ne manquera pas de le lapider, on fera mourir tant l’étranger, que celui qui est né au pays, lequel aura blasphémé le Nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'On punira aussi de mort celui qui aura frappé à mort quelque personne que ce soit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Celui qui aura frappé une bête à mort, la rendra vie pour vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Et quand quelque homme aura fait un outrage à son prochain, on lui fera comme il a fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Fracture pour fracture, oeil pour oeil, dent pour dent; selon le mal qu’il aura fait à un homme, il lui sera aussi fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Celui qui frappera une bête à mort, la rendra; mais on fera mourir celui qui aura frappé un homme à mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Vous rendrez un même jugement. Vous traiterez l’étranger comme celui qui est né au pays; car je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Moïse donc parla aux enfants d’Israël, qui firent sortir hors du camp celui qui avait maudit, et l’assommèrent de pierres; ainsi les enfants d’Israël firent comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'L’Eternel parla aussi à Moïse sur la montagne de Sinaï, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Parle aux enfants d’Israël, et leur dis: Quand vous serez entrés au pays que je vous donne, la terre se reposera; ce sera un Sabbat à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Pendant six ans tu sèmeras ton champ, et pendant six ans tu tailleras ta vigne, et en recueilleras le rapport.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Mais la septième année il y aura un Sabbat de repos pour la terre, ce sera un Sabbat à l’Eternel; tu ne sèmeras point ton champ, et ne tailleras point ta vigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Tu ne moissonneras point ce qui sera provenu de soi-même de ce qui sera tombé en moissonnant, et tu ne vendangeras point les raisins de ta vigne non taillée; ce sera l’année du repos de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Mais ce qui proviendra de la terre l’année du Sabbat vous servira d’aliment, à toi, et à ton serviteur, et à ta servante, à ton mercenaire, et à ton étranger qui demeurent avec toi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'Et à tes bêtes, et aux animaux qui sont en ton pays; tout son rapport sera pour manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Tu compteras aussi sept semaines d’années, savoir sept fois sept ans, et les jours de sept semaines feront quarante-neuf ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Puis tu feras sonner la trompette de jubilation le dixième jour du septième mois, le jour, dis-je, des propitiations, vous ferez sonner la trompette par tout votre pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Et vous sanctifierez l’an cinquantième, et publierez la liberté dans le pays à tous ses habitants; ce vous sera l’année du Jubilé, et vous retournerez chacun en sa possession, et chacun en sa famille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Cette cinquantième année vous sera l’année du Jubilé, vous ne sèmerez point et ne moissonnerez point ce que la terre rapportera d’elle-même, et vous ne vendangerez point les fruits de la vigne non taillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Car c’est l’année du Jubilé, elle vous sera sainte; vous mangerez ce que les champs rapporteront cette année-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'En cette année du Jubilé vous retournerez chacun en sa possession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Et si tu fais quelque vente à ton prochain, ou si tu achètes quelque chose de ton prochain, que nul de vous ne foule son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Mais tu achèteras de ton prochain selon le nombre des années après le Jubilé. Pareillement on te fera les ventes selon le nombre des années du rapport.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Selon qu’il y aura plus d’années, tu augmenteras le prix de ce que tu achètes; et selon qu’il y aura moins d’années, tu le diminueras; car on te vend le nombre des récoltes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Que donc nul de vous ne foule son prochain; mais craignez votre Dieu, car je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Faites selon mes ordonnances, gardez mes jugements, observez-les, et vous habiterez sûrement au pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Et la terre vous donnera ses fruits, vous en mangerez, vous en serez rassasiés, et vous habiterez sûrement en elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Et si vous dites: Que mangerons-nous en la septième année si nous ne semons point, et si nous ne recueillons point notre récolte?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Je commanderai à ma bénédiction de se répandre sur vous en la sixième année, et la terre rapportera pour trois ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Puis vous sèmerez en la huitième année, et vous mangerez du rapport du passé jusqu’à la neuvième année; jusqu’à ce donc que son rapport sera venu, vous mangerez celui du passé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'La terre ne sera point vendue absolument, car la terre est à moi; et vous êtes étrangers et forains chez moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'C’est pourquoi dans tout le pays de votre possession vous donnerez le droit de rachat pour la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Si ton frère est devenu pauvre, et vend quelque chose de ce qu’il possède, celui qui a le droit de rachat, savoir son plus proche parent, viendra et rachètera la chose vendue par son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Que si cet homme n’a personne qui ait le droit de rachat, et qu’il ait trouvé de soi-même suffisamment de quoi faire le rachat de ce qu’il a vendu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'Il comptera les années du temps qu’il a fait la vente, et il restituera le surplus à l’homme auquel il l’avait faite, et ainsi il retournera dans sa possession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Mais s’il n’a pas trouvé suffisamment de quoi lui rendre, la chose qu’il aura vendue sera en la main de celui qui l’aura achetée, jusqu’à l’année du Jubilé; puis l’acheteur en sortira au Jubilé, et le vendeur retournera dans sa possession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Et si quelqu’un a vendu une maison à habiter dans quelque ville fermée de murailles, il aura le droit de rachat jusqu’à la fin de l’année de sa vente; son droit de rachat sera d’une année.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Mais si elle n’est point rachetée dans l’année accomplie, la maison qui est dans la ville fermée de murailles, demeurera à l’acheteur absolument et en ses âges; il n’en sortira point au Jubilé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Mais les maisons des villages, qui ne sont point entourés de murailles, seront réputées comme un fonds de terre; le vendeur aura droit de rachat, et l’acheteur sortira au Jubilé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Et quant aux villes des Lévites, les Lévites auront un droit de rachat perpétuel des maisons des villes de leur possession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Et celui qui aura acheté quelque maison des Lévites, sortira au Jubilé de la maison vendue, qui est en la ville de sa possession; car les maisons des villes des Lévites sont leur possession parmi les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Mais le champ des faubourgs de leurs villes ne sera point vendu; car c’ est leur possession perpétuelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Quand ton frère sera devenu pauvre, et qu’il tendra vers toi ses mains tremblantes, tu le soutiendras, tu soutiendras aussi l’étranger, et le forain, afin qu’il vive avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Tu ne prendras point de lui d’usure, ni d’intérêt, mais tu craindras ton Dieu; et ton frère vivra avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Tu ne lui donneras point ton argent à usure, ni ne lui donneras de tes vivres à surcroît.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Je suis l’Eternel votre Dieu qui vous ai retirés du pays d’Egypte, pour vous donner le pays de Canaan, afin de vous être Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Pareillement quand ton frère sera devenu pauvre auprès de toi, et qu’il se sera vendu à toi, tu ne te serviras point de lui comme on se sert des esclaves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Mais il sera chez toi comme serait le mercenaire, et l’étranger, et il te servira jusqu’à l’année du Jubilé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Alors il sortira de chez toi avec ses enfants, il s’en retournera dans sa famille, et rentrera dans la possession de ses pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Car ils sont mes serviteurs, parce que je les ai retirés du pays d’Egypte; c’est pourquoi ils ne seront point vendus comme on vend les esclaves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Tu ne domineras point sur lui rigoureusement, mais tu craindras ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Et quant à ton esclave et à ta servante qui seront à toi, ils seront d’entre les nations qui sont autour de vous; vous achèterez d’elles le serviteur et la servante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Vous en achèterez aussi d’entre les enfants des étrangers qui demeurent avec vous, même de leurs familles qui seront parmi vous, lesquelles ils auront engendrées en votre pays, et vous les posséderez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Vous les aurez comme un héritage pour les laisser à vos enfants après vous, afin qu’ils en héritent la possession, et vous vous servirez d’eux à perpétuité; mais quant à vos frères, les enfants d’Israël, nul ne dominera rigoureusement sur son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Et lorsque l’étranger ou le forain qui est avec toi se sera enrichi, et que ton frère qui est avec lui sera devenu si pauvre qu’il se soit vendu à l’étranger, ou au forain qui est avec toi, ou à quelqu’un de la postérité de la famille de l’étranger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'Après s’être vendu il y aura droit de rachat pour lui, et un de ses frères le rachètera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Ou son oncle, ou le fils de son oncle, ou quelque autre proche parent de son sang d’entre ceux de sa famille, le rachètera; ou lui-même, s’il en trouve le moyen, se rachètera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Et il comptera avec son acheteur depuis l’année qu’il s’est vendu à lui, jusqu’à l’année du Jubilé; de sorte que l’argent du prix pour lequel il s’est vendu, se comptera à raison du nombre des années; le temps qu’il aura servi lui sera compté comme les journées d’un mercenaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'S’il y a encore plusieurs années, il restituera le prix de son achat à raison de ces années, selon le prix pour lequel il a été acheté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Et s’il reste peu d’années jusqu’à l’an du Jubilé, il comptera avec lui, et restituera le prix de son achat à raison des années qu’il a servi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Il aura été avec lui comme un mercenaire qui se loue d’année en année; et cet étranger ne dominera point sur lui rigoureusement en ta présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Que s’il n’est pas racheté par quelqu’un de ces moyens, il sortira l’année du Jubilé, lui et ses fils avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Car les enfants d’Israël me sont serviteurs; ce sont mes serviteurs que j’ai retirés du pays d’Egypte; je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Vous ne vous ferez point d’idoles, et vous ne vous dresserez point d’image taillée, ni de statue, et vous ne mettrez point de pierre peinte dans votre pays pour vous prosterner devant elles; car je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Vous garderez mes Sabbats, et vous révérerez mon Sanctuaire; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Si vous marchez dans mes ordonnances, et si vous gardez mes commandements et les faites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'Je vous donnerai les pluies qu’il vous faut en leur temps, la terre donnera son fruit, et les arbres des champs donneront leur fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'La foulure des grains atteindra la vendange chez vous, et la vendange atteindra les semailles; vous mangerez votre pain, vous en serez rassasiés, et vous habiterez sûrement en votre pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Je donnerai la paix au pays, vous dormirez sans qu’aucun vous épouvante; je ferai qu’il n’y aura plus de mauvaises bêtes au pays; et l’épée ne passera point par votre pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Mais vous poursuivrez vos ennemis, et ils tomberont par l’épée devant vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Cinq d’entre vous en poursuivront cent, et cent en poursuivront dix mille; et vos ennemis tomberont par l’épée devant vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Et je me tournerai vers vous, je vous ferai croître et multiplier, et j’établirai mon alliance avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Vous mangerez aussi des provisions fort vieilles, et vous tirerez dehors le vieux pour y loger le nouveau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Même je mettrai mon Tabernacle au milieu de vous, et mon âme ne vous aura point à contrecœur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Mais je marcherai au milieu de vous, je vous serai Dieu, et vous serez mon peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Je suis l’Eternel votre Dieu qui vous ai retirés du pays d’Egypte, afin que vous ne fussiez point leurs esclaves; j’ai rompu les bois de votre joug, et vous ai fait marcher la tête levée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Mais si vous ne m’écoutez point, et que vous ne fassiez pas tous ces commandements;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'Et que vous rejetiez mes ordonnances, et que votre âme ait mes jugements à contrecœur, pour ne point faire tous mes commandements, et pour enfreindre mon alliance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'Aussi je vous ferai ceci; je répandrai sur vous la frayeur, la langueur, et l’ardeur, qui vous consumeront les yeux, et vous tourmenteront l’âme; et vous sèmerez en vain votre semence; car vos ennemis la mangeront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Et je mettrai ma face contre vous; vous serez battus devant vos ennemis; ceux qui vous haïssent domineront sur vous; et vous fuirez, sans qu’aucun vous poursuive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Que si encore après ces choses vous ne m’écoutez point, j’en ajouterai sept fois autant pour vous châtier, à cause de vos péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Et j’abattrai l’orgueil de votre force, et je ferai que le ciel sera pour vous comme de fer, et votre terre comme d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Votre force se consumera inutilement, car votre terre ne donnera point son rapport, et les arbres de la terre ne donneront point leur fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Que si vous marchez de front contre moi, et que vous refusiez de m’écouter, j’ajouterai sur vous sept fois autant de plaies, selon vos péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'J’enverrai contre vous les bêtes des champs, qui vous priveront de vos enfants, qui tueront votre bétail, et vous réduiront à un petit nombre, et vos chemins seront déserts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Que si vous ne vous corrigez pas après ces choses pour vous convertir à moi, mais que vous marchiez de front contre moi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'Je marcherai aussi de front contre vous, et je vous frapperai encore sept fois autant, selon vos péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Et je ferai venir sur vous l’épée qui fera la vengeance de mon alliance; et quand vous vous retirerez dans vos villes j’enverrai la mortalité parmi vous, et vous serez livrés entre les mains de l’ennemi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Lorsque je vous aurai rompu le bâton du pain, dix femmes cuiront votre pain dans un four, et vous rendront votre pain au poids; vous en mangerez, et vous n’en serez point rassasiés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Que si avec cela vous ne m’écoutez point, mais que vous marchiez de front contre moi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'Je marcherai de front contre vous en ma fureur, et je vous châtierai aussi sept fois autant selon vos péchés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Et vous mangerez la chair de vos fils, et vous mangerez aussi la chair de vos filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Je détruirai vos hauts lieux; je ruinerai vos Tabernacles; je mettrai vos charognes sur les charognes de vos dieux de fiente, et mon âme vous aura en haine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Je réduirai aussi vos villes en désert, je ruinerai vos Sanctuaires, et je ne flairerai point votre odeur agréable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Et je désolerai le pays, tellement que vos ennemis qui s’y habitueront, en seront étonnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Et je vous disperserai parmi les nations, et je tirerai l’épée après vous, et votre pays sera en désolation, et vos villes en désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Alors la terre prendra plaisir à ses Sabbats, tout le temps qu’elle sera désolée,; et lorsque vous serez au pays de vos ennemis la terre se reposera, et prendra plaisir à ses Sabbats.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Tout le temps qu’elle demeurera désolée, elle se reposera; au lieu qu’elle ne s’était point reposée en vos Sabbats, lorsque vous y habitiez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Et quant à ceux qui demeureront de reste d’entre vous, je rendrai leur coeur lâche lorsqu’ils seront au pays de leurs ennemis, de sorte que le bruit d’une feuille émue les poursuivra, et ils fuiront comme s’ils fuyaient de devant l’épée, et ils tomberont sans qu’aucun les poursuive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Et ils s’entreheurteront l’un l’autre comme s’ils fuyaient de devant l’épée, sans que personne les poursuive; et vous ne pourrez point subsister devant vos ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Et vous périrez entre les nations, et la terre de vos ennemis vous consumera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Et ceux qui demeureront de reste d’entre vous se fondront à cause de leurs iniquités, au pays de vos ennemis; et ils se fondront aussi à cause des iniquités de leurs pères, avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Alors ils confesseront leur iniquité, et l’iniquité de leurs pères, selon les péchés qu’ils auront commis contre moi; et même selon qu’ils auront marché de front contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'J’aurai aussi marché de front contre eux, et je les aurai amenés au pays de leurs ennemis; et alors leur coeur incirconcis s’humiliera, et ils recevront alors avec soumission, la punition de leur iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Et alors je me souviendrai de mon alliance avec Jacob, et de mon alliance avec Isaac, et je me souviendrai aussi de mon alliance avec Abraham, et je me souviendrai de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Quand donc la terre aura été abandonnée par eux, et qu’elle aura pris plaisir à ses Sabbats, ayant demeure désolée à cause d’eux; lors donc qu’ils auront reçu avec soumission la punition de leur iniquité, à cause qu’ils ont rejeté mes jugements, et que leur âme a dédaigné mes ordonnances.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Je m’en souviendrai, dis-je, lorsqu’ils seront au pays de leurs ennemis; parce que je ne les ai point rejetés, ni eus en haine pour les consumer entièrement, et pour rompre l’alliance que j’ai faite avec eux; car je suis l’Eternel leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Et je me souviendrai pour leur bien de l’alliance faite avec leurs ancêtres, lesquels j’ai retirés du pays d’Egypte, à la vue des nations, pour être leur Dieu; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Ce sont là les ordonnances, les jugements, et les lois que l’Eternel établit entre lui et les enfants d’Israël sur la montagne de Sinaï, par le moyen de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Parle aux enfants d’Israël, et leur dis: Quand quelqu’un aura fait un voeu important, les personnes vouées à l’Eternel seront mises à ton estimation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Et l’estimation que tu feras d’un mâle, depuis l’âge de vingt ans jusqu’à l’âge de soixante ans, sera du prix de cinquante sicles d’argent, selon le sicle du Sanctuaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Mais si c’est une femme, alors ton estimation sera de trente sicles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Que si c’est d’une personne de l’âge de cinq ans jusqu’à l’âge de vingt ans, alors l’estimation que tu feras d’un mâle sera de vingt sicles; et quant à la femme, l’estimation sera de dix sicles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Et si c’est d’une personne de l’âge d’un mois jusqu’à l’âge de cinq ans, l’estimation que tu feras d’un mâle sera de cinq sicles d’argent; et l’estimation que tu feras d’une fille, sera de trois sicles d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Et lorsque c’est d’une personne âgée de soixante ans et au-dessus, si c’est un mâle, ton estimation sera de quinze sicles; et si c’est une femme, l’estimation sera de dix sicles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Et s’il est plus pauvre que ne monte ton estimation, il se présentera devant le Sacrificateur qui en fera l’estimation, et le Sacrificateur en fera l’estimation selon ce que pourra fournir celui qui a fait le voeu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Et si c’est d’une de ces sortes de bêtes dont on fait offrande à l’Eternel, tout ce qui aura été donné à l’Eternel de cette sorte de bêtes, sera saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Il ne la changera point, et n’en mettra point une autre en sa place, une bonne pour une mauvaise, ou une mauvaise pour une bonne: et s’il met en quelque sorte que ce soit une bête pour une autre bête, tant celle-là que l’autre qui aura été mise en sa place, sera sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Et si c’est d’une bête souillée, dont on ne fait point offrande à l’Eternel, il présentera la bête devant le Sacrificateur,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'Qui en fera l’estimation selon qu’elle sera bonne ou mauvaise; et il en sera fait ainsi, selon que toi, Sacrificateur, en auras fait l’estimation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Mais s’il la veut racheter en quelque sorte, il ajoutera un cinquième par dessus ton estimation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Et quand quelqu’un aura sanctifié sa maison pour être sainte à l’Eternel, le Sacrificateur l’estimera selon qu’elle sera bonne ou mauvaise; et on se tiendra à l’estimation que le Sacrificateur en aura faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Mais si celui qui l’a sanctifiée veut racheter sa maison, il ajoutera par dessus le cinquième de l’argent de ton estimation, et elle lui demeurera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Et si l’homme sanctifie à l’Eternel quelque partie du champ de sa possession, ton estimation sera selon ce qu’on y sème; le Homer de semence d’orge sera estimé cinquante sicles d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Que s’il a sanctifié son champ dès l’année du Jubilé, on se tiendra à ton estimation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Mais s’il sanctifie son champ après le Jubilé, le Sacrificateur lui mettra en compte l’argent selon le nombre des années qui restent jusqu’à l’année du Jubilé, et cela sera rabattu de ton estimation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Et si celui qui a sanctifié le champ, le veut racheter en quelque sorte que ce soit, il ajoutera par dessus le cinquième de l’argent de ton estimation, et il lui demeurera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Mais s’il ne rachète point le champ, et que le champ se vende à un autre homme, il ne se rachètera plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Et ce champ-là ayant passé le Jubilé, sera saint à l’Eternel, comme un champ d’interdit, la possession en sera au Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Et s’il sanctifie à l’Eternel un champ qu’il ait acheté, n’étant point des champs de sa possession;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'Le Sacrificateur lui comptera la somme de ton estimation jusqu’à l’année du Jubilé, et il donnera en ce jour-là ton estimation, afin que ce soit une chose sainte à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Mais en l’année du Jubilé le champ retournera à celui duquel il l’avait acheté, et auquel était la possession du fond.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Et toute estimation que tu auras faite, sera selon le sicle du Sanctuaire; le sicle est de vingt oboles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Toutefois nul ne pourra sanctifier le premier-né d’entre les bêtes, car il appartient à l’Eternel par droit de primogéniture, soit de vache, soit de brebis, ou de chèvre, il est à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Mais s’il est de bêtes souillées, il le rachètera selon ton estimation, et il ajoutera à ton estimation un cinquième; et s’il n’est point racheté, il sera vendu selon ton estimation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Or nul interdit que quelqu’un aura dévoué à l’Eternel par interdit, de tout ce qui est sien, soit homme, ou bête, ou champ de sa possession, ne se vendra, ni ne se rachètera; tout interdit sera très-saint à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Nul interdit dévoué par interdit d’entre les hommes, ne se rachètera, mais on le fera mourir de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Or toute dîme de la terre, tant du grain de la terre que du fruit des arbres, est à l’Eternel; c’est une sainteté à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Mais si quelqu’un veut racheter en quelque sorte que ce soit quelque chose de sa dîme, il y ajoutera le cinquième par dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Mais toute dîme de boeufs, de brebis et de chèvres, savoir tout ce qui passe sous la verge, qui est le dixième, sera sanctifié à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'On ne choisira point le bon ou le mauvais, et on n’en mettra point d’autre en sa place; que si on le fait en quelque sorte que ce soit, la bête changée et l’autre qui aura été mise en sa place, sera sanctifiée, et ne sera point rachetée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Ce sont là les commandements que l’Eternel donna à Moïse sur la montagne de Sinaï, pour les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Or l’Eternel parla à Moïse au désert de Sinaï, dans le Tabernacle d’assignation, le premier jour du second mois de la seconde année, après qu’ils furent sortis du pays d’Egypte, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Faites le dénombrement de toute l’assemblée des enfants d’Israël, selon leurs familles, selon les maisons de leurs pères, en les comptant nom par nom, savoir tous les mâles, chacun par tête;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Depuis l’âge de vingt ans, et au dessus, tous ceux d’Israël qui peuvent aller à la guerre, vous les compterez suivant leurs troupes, toi et Aaron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Et il y aura avec vous un homme de chaque Tribu, savoir celui qui est le chef de la maison de ses pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Et ce sont ici les noms de ces hommes qui vous assisteront. Pour la Tribu de Ruben, Elitsur fils de Sédéur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Pour celle de Siméon, Sélumiel, fils de Tsurisaddaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Pour celle de Juda, Nahasson, fils de Hamminadab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Pour celle d’Issacar, Nathanaël, fils de Tsuhar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Pour celle de Zabulon, Eliab, fils de Hélon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'des enfants de Joseph, pour la Tribu d’Ephraïm, Elisamah, fils de Hammiud; pour celle de Manassé, Gamaliel fils de Pédatsur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'Pour la Tribu de Benjamin, Abidan, fils de Guidhoni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'Pour celle de Dan, Ahihézer, fils de Hammisaddaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'Pour celle d’Aser, Paghiel, fils de Hocran.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'Pour celle de Gad, Eliasaph, fils de Déhuël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'Pour celle de Nephthali, Ahirah, fils de Hénan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'C’étaient là ceux qu’on appelait pour tenir l’assemblée; ils étaient les principaux des Tribus de leurs pères, chefs des milliers d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Alors Moïse et Aaron prirent ces hommes-là qui avaient été nommés par leurs noms;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'Et ils convoquèrent toute l’assemblée, le premier jour du second mois, et on enregistra chacun selon leurs familles, et selon la maison de leurs pères, les enregistrant, nom par nom, depuis l’âge de vingt ans, et au dessus, chacun par tête;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Comme l’Eternel l’avait commandé à Moïse, il les dénombra au désert de Sinaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Les enfants donc de Ruben, premier-né d’Israël, selon leurs générations, leurs familles, et les maisons de leurs pères, dont on fit le dénombrement par leur nom, et par tête, savoir tous les mâles de l’âge de vingt ans, et au dessus, tous ceux qui pouvaient aller à la guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'Ceux, dis-je, de la Tribu de Ruben, qui furent dénombrés, furent quarante-six mille cinq cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Des enfants de Siméon, selon leurs générations, leurs familles, et les maisons de leurs pères, ceux qui furent dénombrés par leur nom et par tête, savoir tous les mâles de l’âge de vingt ans, et au dessus, tous ceux qui pouvaient aller à la guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Ceux, dis-je, de la Tribu de Siméon, qui furent dénombrés, furent cinquante-neuf mille trois cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Des enfants de Gad, selon leurs générations, leurs familles, et les maisons de leurs pères, dénombrés chacun par leur nom, depuis l’âge de vingt ans, et au dessus, tous ceux qui pouvaient aller à la guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Ceux, dis-je, de la Tribu de Gad, qui furent dénombrés, furent quarante-cinq mille six cent cinquante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Des enfants de Juda, selon leurs générations, leurs familles, et les maisons de leurs pères, dénombrés chacun par leur nom, depuis l’âge de vingt ans, et au dessus, tous ceux qui pouvaient aller à la guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Ceux, dis-je, de la Tribu de Juda, qui furent dénombrés, furent soixante et quatorze mille six cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Des enfants d’Issacar, selon leurs générations, leurs familles, et les maisons de leurs pères, dénombrés chacun par leur nom, depuis l’âge de vingt ans, et au dessus, tous ceux qui pouvaient aller à la guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Ceux, dis-je, de la Tribu d’Issacar, qui furent dénombrés, furent cinquante-quatre mille quatre cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Des enfants de Zabulon, selon leurs générations, leurs familles, et les maisons de leurs pères, dénombrés chacun par leur nom, depuis l’âge de vingt ans, et au dessus, tous ceux qui pouvaient aller à la guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Ceux, dis-je, de la Tribu de Zabulon, qui furent dénombrés, furent cinquante-sept mille quatre cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Quant aux enfants de Joseph; les enfants d’Ephraïm, selon leurs générations, leurs familles, et les maisons de leurs pères, dénombrés chacun par leur nom, depuis l’âge de vingt ans, et au dessus, tous ceux qui pouvaient aller à la guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Ceux, dis-je, de la Tribu d’Ephraïm, qui furent dénombrés, furent quarante mille cinq cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Des enfants de Manassé, selon leurs générations, leurs familles, et les maisons de leurs pères, dénombrés chacun par leur nom, depuis l’âge de vingt ans, et au dessus, tous ceux qui pouvaient aller à la guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Ceux, dis-je, de la Tribu de Manassé, qui furent dénombrés, furent trente-deux mille deux cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Des enfants de Benjamin, selon leurs générations, leurs familles, et les maisons de leurs pères, dénombrés chacun par leur nom, depuis l’âge de vingt ans, et au dessus, tous ceux qui pouvaient aller à la guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Ceux, dis-je, de la Tribu de Benjamin, qui furent dénombrés, furent trente-cinq mille quatre cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Des enfants de Dan, selon leurs générations, leurs familles, et les maisons de leurs pères, dénombrés chacun par leur nom, depuis l’âge de vingt ans, et au dessus, tous ceux qui pouvaient aller à la guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Ceux, dis-je, de la Tribu de Dan,, qui furent dénombrés, furent soixante-deux mille sept cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Des enfants d’Aser, selon leurs générations, leurs familles, et les maisons de leurs pères, dénombrés chacun par leur nom, depuis l’âge de vingt ans, et au dessus, tous ceux qui pouvaient aller à la guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'Ceux, dis-je, de la Tribu d’Aser, qui furent dénombrés, furent quarante et un mille cinq cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Des enfants de Nephthali, selon leurs générations, leurs familles, et les maisons de leurs pères, dénombrés chacun par leur nom, depuis l’âge de vingt ans, et au dessus, tous ceux qui pouvaient aller à la guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Ceux, dis-je, de la Tribu de Nephthali, qui furent dénombrés, furent cinquante-trois mille quatre cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Ce sont là ceux dont Moïse et Aaron firent le dénombrement, les douze principaux d’entre les enfants d’Israël y étant, un pour chaque maison de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Ainsi tous ceux des enfants d’Israël, dont on fit le dénombrement, selon les maisons de leurs pères, depuis l’âge de vingt ans, et au dessus, tous ceux d’entre les Israélites, qui pouvaient aller à la guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Tous ceux, dis-je, dont on fit le dénombrement, furent six cent trois mille cinq cent cinquante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Mais les Lévites ne furent point dénombrés avec eux, selon la Tribu de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Car l’Eternel avait parlé à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Tu ne feras aucun dénombrement de la Tribu de Lévi, et tu n’en lèveras point la somme avec les autres enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Mais tu donneras aux Lévites la charge du pavillon du Témoignage, et de tous ses ustensiles, et de tout ce qui lui appartient; ils porteront le pavillon, et tous ses ustensiles; ils y serviront, et camperont autour du pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Et quand le pavillon partira, les Lévites le désassembleront, et quand le pavillon campera, ils le dresseront. Que si quelque étranger en approche, on le fera mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Or les enfants d’Israël camperont chacun en son quartier, et chacun sous son enseigne, selon leurs troupes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Mais les Lévites camperont autour du pavillon du Témoignage, afin qu’il n’y ait point d’indignation sur l’assemblée des enfants d’Israël, et ils prendront en leur charge le pavillon du Témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Et les enfants d’Israël firent selon toutes les choses que l’Eternel avait commandées à Moïse; ils le firent ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Et l’Eternel parla à Moïse et à Aaron, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Les enfants d’Israël camperont chacun sous sa bannière, avec les enseignes des maisons de leurs pères, tout autour du Tabernacle d’assignation, vis-à-vis de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Ceux de la bannière de la compagnie de Juda camperont droit vers le Levant, par ses troupes; et Nahasson, fils de Hamminadab, sera le chef des enfants de Juda;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Et sa troupe, et ses dénombrés, soixante-quatorze mille six cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Près de lui campera la Tribu d’Issacar, et Nathanaël, fils de Tsuhar, sera le chef des enfants d’Issacar;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Et sa troupe, et ses dénombrés, cinquante-quatre mille quatre cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Puis la Tribu de Zabulon, et Eliab, fils de Hélon, sera le chef des enfants de Zabulon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Et sa troupe, et ses dénombrés, cinquante-sept mille quatre cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Tous les dénombrés de la compagnie de Juda, cent quatre-vingt-six mille quatre cents par leurs troupes, partiront les premiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'La bannière de la compagnie de Ruben, par ses troupes, sera vers le Midi, et Elitsur, fils de Sédéur, sera le chef des enfants de Ruben;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Et sa troupe, et ses dénombrés, quarante-six mille cinq cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Près de lui campera la Tribu de Siméon, et Sélumiel, fils de Tsurisaddaï, sera le chef des enfants de Siméon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Et sa troupe, et ses dénombrés, cinquante-neuf mille trois cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Puis la Tribu de Gad, et Eliasaph, fils de Réhuel, sera le chef des enfants de Gad;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Et sa troupe, et ses dénombrés, quarante-cinq mille six cent cinquante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Tous les dénombrés de la compagnie de Ruben, cent cinquante et un mille quatre cent cinquante, par leurs troupes, partiront les seconds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Ensuite le Tabernacle d’assignation partira avec la compagnie des Lévites, au milieu des compagnies qui partiront selon qu’elles seront campées, chacune en sa place, selon leurs bannières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'La bannière de la compagnie d’Ephraïm, par ses troupes, sera vers l’Occident; et Elisamah, fils de Hammiud, sera le chef des enfants d’Ephraïm;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Et sa troupe, et ses dénombrés, quarante mille cinq cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Près de lui campera la Tribu de Manassé, et Gamaliel, fils de Pédatsur, sera le chef des enfants de Manassé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Et sa troupe, et ses dénombrés, trente-deux mille deux cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Puis la Tribu de Benjamin, et Abidan, fils de Guidhoni, sera le chef des enfants de Benjamin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Et sa troupe, et ses dénombrés, trente-cinq mille et quatre cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Tous les dénombrés de la compagnie d’Ephraïm, cent huit mille et cent, par leurs troupes, partiront les troisièmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'La bannière de la compagnie de Dan, par ses troupes, sera vers le Septentrion, et Ahihézer, fils de Hammisadaaï, sera le chef des enfants de Dan;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Et sa troupe, et ses dénombrés, soixante-deux mille sept cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Près de lui campera la Tribu d’Aser, et Paghiel, fils de Hocran, sera le chef des enfants d’Aser;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Et sa troupe, et ses dénombrés, quarante et un mille cinq cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Puis la Tribu de Nephthali, et Ahirah, fils de Hénan, sera le chef des enfants de Nephthali;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Et sa troupe, et ses dénombrés, cinquante-trois mille quatre cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Tous les dénombrés de la compagnie de Dan, cent cinquante-sept mille six cents, partiront les derniers des bannières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Ce sont là ceux des enfants d’Israël dont on fit le dénombrement selon les maisons de leurs pères. Tous les dénombrés des compagnies selon leurs troupes; furent six cent trois mille cinq cent cinquante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Mais les Lévites ne furent point dénombrés avec les autres enfants d’Israël, comme l’Eternel l’ avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Et les enfants d’Israël firent selon toutes les choses que l’Eternel avait commandées à Moïse, et campèrent ainsi selon leurs bannières, et partirent ainsi, chacun selon leurs familles, et selon la maison de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Or ce sont ici les générations d’Aaron et de Moïse, au temps que l’Eternel parla à Moïse sur la montagne de Sinaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Et ce sont ici les noms des enfants d’Aaron; Nadab, qui était l’aîné, Abihu, Eléazar, et Ithamar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Ce sont là les noms des enfants d’Aaron Sacrificateurs, qui furent oints et consacrés pour exercer la Sacrificature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Mais Nadab et Abihu moururent en la présence de l’Eternel, quand ils offrirent un feu étranger devant l’Eternel au désert de Sinaï, et ils n’eurent point d’enfants; mais Eléazar et Ithamar exercèrent la Sacrificature en la présence d’Aaron leur père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Fais approcher la Tribu de Lévi, et fais qu’elle se tienne devant Aaron Sacrificateur, afin qu’ils le servent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Et qu’ils aient la charge de ce qu’il leur ordonnera de garder, et de ce que toute l’assemblée leur ordonnera de garder, devant le Tabernacle d’assignation, en faisant le service du Tabernacle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Et qu’ils gardent tous les ustensiles du Tabernacle d’assignation, et ce qui leur sera donné en charge par les enfants d’Israël, pour faire le service du Tabernacle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Ainsi tu donneras les Lévites à Aaron et à ses fils; ils lui sont absolument donnés d’entre les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Tu donneras donc la surintendance à Aaron et à ses fils, et ils exerceront leur Sacrificature. Que si quelque étranger en approche, on le fera mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Voici, j’ai pris les Lévites d’entre les enfants d’Israël, au lieu de tout premier-né qui ouvre la matrice entre les enfants d’Israël; c’est pourquoi les Lévites seront à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Car tout premier-né m’appartient, depuis que je frappai tout premier-né au pays d’Egypte; je me suis sanctifié tout premier-né en Israël, depuis les hommes jusqu’aux bêtes; ils seront à moi, je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'L’Eternel parla aussi à Moïse au désert de Sinaï, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Dénombre les enfants de Lévi, par les maisons de leurs pères, et par leurs familles, en comptant tout mâle depuis l’âge d’un mois, et au dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Moïse donc les dénombra selon le commandement de l’Eternel, ainsi qu’il lui avait été commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Or ce sont ici les fils de Lévi selon leurs noms: Guerson, Kéhath, et Mérari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Et ce sont ici les noms des fils de Guerson, selon leurs familles, Libni, et Simhi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Et les fils de Kéhath selon leurs familles, Hamram, Jitshar, Hébron et Huziel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Et les fils de Mérari, selon leurs familles, Mahli et Musi; ce sont là les familles de Lévi, selon les maisons de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'De Guerson est sortie la famille des Libnites, et la famille des Simhites; ce sont les familles des Guersonites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Desquelles ceux dont on fit le dénombrement, après le compte qui fut fait de tous les mâles depuis l’âge d’un mois et au dessus, furent au nombre de sept mille cinq cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Les familles des Guersonites camperont derrière le Tabernacle à l’Occident.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Et Eliasaph, fils de Laël, sera le chef de la maison des pères des Guersonites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Et les enfants de Guerson auront en charge au Tabernacle d’assignation, la tente, le Tabernacle, sa couverture, la tapisserie de l’entrée du Tabernacle d’assignation;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'Et les courtines du parvis avec la tapisserie de l’entrée du parvis, qui servent pour le pavillon et pour l’autel, tout autour, et son cordage, pour tout son service.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Et de Kéhath est sortie la famille des Hamramites, la famille des Jitsharites, la famille des Hébronites, et la famille des Huziélites; ce furent là les familles des Kéhathites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Dont tous les mâles depuis l’âge d’un mois, et au dessus, furent au nombre de huit mille six cents, ayant la charge du Sanctuaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Les familles des enfants de Kéhath camperont du côté du Tabernacle vers le Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Et Elitsaphan, fils de Huziel, sera le chef de la maison des pères des familles des Kéhathites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Et ils auront en charge l’Arche, la Table, le chandelier, les autels, et les ustensiles du Sanctuaire avec lesquels on fait le service, et la tapisserie, avec tout ce qui y sert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Et le chef des chefs des Lévites sera Eléazar, fils d’Aaron Sacrificateur; qui aura la surintendance sur ceux qui auront la charge du Sanctuaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Et de Mérari est sortie la famille des Mahlites, et la famille des Musites; ce furent là les familles de Mérari;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Desquelles ceux dont on fit le dénombrement après le compte qui fut fait de tous les mâles, depuis l’âge d’un mois et au dessus, furent six mille deux cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Et Esuriel, fils d’Abihaïl, sera le chef de la maison des pères des familles des Mérarites; ils camperont du côté du Tabernacle vers l’Aquilon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Et on donnera aux enfants de Mérari la charge des ais du Tabernacle, de ses barres, de ses piliers, de ses soubassements, et de tous ses ustensiles, avec tout ce qui y sera;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'Et des piliers du parvis tout autour, avec leurs soubassements, leurs pieux, et leurs cordes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Et Moïse, et Aaron, et ses fils ayant la charge du Sanctuaire, pour la garde des enfants d’Israël, camperont devant le Tabernacle d’assignation vers l’Orient. Que si quelque étranger en approche, on le fera mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Tous ceux des Lévites dont on fit le dénombrement, lesquels Moïse et Aaron comptèrent par leurs familles, suivant le commandement de l’Eternel, tous les mâles de l’âge d’un mois et au dessus, furent de vingt-deux mille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Et l’Eternel dit à Moïse: Fais le dénombrement de tous les premiers-nés mâles des enfants d’Israël, depuis l’âge d’un mois, et au dessus, et lève le compte de leurs noms.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Et tu prendras pour moi, je suis l’Eternel, les Lévites, au lieu de tous les premiers-nés qui sont entre les enfants d’Israël; tu prendras aussi les bêtes des Lévites, au lieu de tous les premiers- nés des bêtes des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Moïse donc dénombra, comme l’Eternel lui avait commandé, tous les premiers-nés qui étaient entre les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Et tous les premiers-nés des mâles, le compte des noms étant fait, depuis l’âge d’un mois et au dessus, selon qu ils furent dénombrés, furent vingt-deux mille deux cent soixante et treize.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Prends les Lévites au lieu de tous les premiers-nés qui sont entre les enfants d’Israël, et les bêtes des Lévites, au lieu de leurs bêtes; et les Lévites seront à moi; je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Et quant à ceux qu’il faudra racheter des premiers-nés des enfants d’Israël, qui sont deux cent soixante et treize, plus que les Lévites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Tu prendras cinq sicles par tête, tu les prendras selon le sicle du Sanctuaire; le sicle est de vingt oboles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Et tu donneras à Aaron et à ses fils l’argent de ceux qui auront été rachetés, passant le nombre des Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Moïse donc prit l’argent du rachat de ceux qui étaient de plus, outre ceux qui avaient été rachetés par l’échange des Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Et il reçut l’argent des premiers-nés des enfants d’Israël, qui fut mille trois cent soixante-cinq sicles, selon le sicle du Sanctuaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Et Moïse donna l’argent des rachetés à Aaron, et à ses fils, selon le commandement de l’Eternel, ainsi que l’Eternel le lui avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Et l’Eternel parla à Moïse, et à Aaron, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Faites le dénombrement des enfants de Kéhath d’entre les enfants de Lévi par leurs familles, et par les maisons de leurs pères,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'Depuis l’âge de trente ans et au dessus, jusqu’à l’âge de cinquante ans, tous ceux qui entrent en rang, pour s’employer au Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'C’est ici le service des enfants de Kéhath au Tabernacle d’assignation, c’est-à-dire, le lieu très-Saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Quand le camp partira, Aaron et ses fils viendront, et ils détendront le voile de tapisserie, et en couvriront l’Arche du Témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Puis ils mettront au dessus une couverture de peaux de taissons, ils étendront par dessus un drap de pourpre, et ils y mettront ses barres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Et ils étendront un drap de pourpre sur la Table des pains de proposition, et mettront sur elle les plats, les tasses, les bassins, et les gobelets d’aspersion. Le pain continuel sera sur elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Ils étendront au dessus un drap teint de cramoisi, ils le couvriront d’une couverture de peaux de taissons, et ils y mettront ses barres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Et ils prendront un drap de pourpre, et en couvriront le chandelier du luminaire avec ses lampes, ses mouchettes, ses creuseaux, et tous les vaisseaux d’huile, desquels on se sert pour le chandelier;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Et ils le mettront avec tous ses vaisseaux dans une couverture de peaux de taissons, et le mettront sur des leviers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Ils étendront sur l’autel d’or un drap de pourpre, ils le couvriront d’une couverture de peaux de taissons, et ils y mettront ses barres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Ils prendront aussi tous les ustensiles du service dont on se sert au Sanctuaire, ils les mettront dans un drap de pourpre, et ils les couvriront d’une couverture de peaux de taissons, et les mettront sur des leviers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Ils ôteront les cendres de l’autel, et étendront dessus un drap d’écarlate.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Et ils mettront dessus les ustensiles dont on se sert pour l’autel, les encensoirs, les crochets, les racloirs, les bassins, et tous les vaisseaux de l’autel; ils étendront dessus une couverture de peaux de taissons, et ils y mettront ses barres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Le camp partira après qu’Aaron et ses fils auront achevé de couvrir le Sanctuaire et tous ses vaisseaux, et après cela les enfants de Kéhath viendront pour le porter, et ils ne toucheront point les choses saintes, de peur qu’ils ne meurent; c’ est là ce que les enfants de Kéhath porteront du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Et Eléazar fils d’Aaron, Sacrificateur, aura la charge de l’huile du luminaire, du parfum de drogues, du gâteau continuel, et de l’huile de l’onction; la charge de tout le pavillon, et de toutes les choses qui sont dans le Sanctuaire, et de ses ustensiles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Et l’Eternel parla à Moïse et à Aaron, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Ne donnez point occasion que la race des familles de Kéhath soit retranchée d’entre les Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Mais faites ceci pour eux, afin qu’ils vivent et ne meurent point; c’est que quand ils approcheront des choses très-Saintes, Aaron et ses fils viendront, qui les rangeront chacun à son service, et à ce qu’il doit porter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Et ils n’entreront point pour regarder quand on enveloppera les choses saintes, afin qu’ils ne meurent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Fais aussi le dénombrement des enfants de Guerson selon les maisons de leurs pères, et selon leurs familles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Depuis l’âge de trente ans, et au dessus, jusqu’à l’âge de cinquante ans, dénombrant tous ceux qui entrent pour tenir leur rang, afin de s’employer à servir au Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'C’est ici le service des familles des Guersonites, en ce à quoi ils doivent servir, et en ce qu’ils doivent porter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Ils porteront donc les rouleaux du pavillon, et le Tabernacle d’assignation, sa couverture, la couverture de taissons qui est sur lui par dessus, et la tapisserie de l’entrée du Tabernacle d’assignation;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'Les courtines du parvis, et la tapisserie de l’entrée de la porte du parvis, qui servent pour le pavillon et pour l’autel tout autour, leur cordage, et tous les ustensiles de leur service, et tout ce qui est fait pour eux; c’est ce en quoi ils serviront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Tout le service des enfants de Guerson en tout ce qu’ils doivent porter, et en tout ce à quoi ils doivent servir, sera réglé par les ordres d’Aaron et de ses fils, et vous les chargerez d’observer tout ce qu’ils doivent porter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'C’est là le service des familles des enfants des Guersonites au Tabernacle d’assignation; et leur charge sera sous la conduite d’Ithamar, fils d’Aaron Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Tu dénombreras aussi les enfants de Mérari selon leurs familles et selon les maisons de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Tu les dénombreras depuis l’âge de trente ans et au dessus, jusqu’à l’âge de cinquante ans; tous ceux qui entrent en rang pour s’employer au service du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Or c’est ici la charge de ce qu’ils auront à porter, selon tout le service qu’ils auront à faire au Tabernacle d’assignation, savoir les ais du pavillon, ses barres, et ses piliers, avec ses soubassements;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'Et les piliers du parvis tout autour, et leurs soubassements, leurs clous, leurs cordages, tous leurs ustensiles, et tout ce dont on se sert en ces choses-là, et vous leur compterez tous les ustensiles qu’ils auront charge de porter, pièce par pièce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'C’est là le service des familles des enfants de Mérari, pour tout ce à quoi ils doivent servir au Tabernacle d’assignation, sous la conduite d’Ithamar, fils d’Aaron, Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Moïse donc et Aaron, et les principaux de l’assemblée dénombrèrent les enfants des Kéhathites, selon leurs familles, et selon les maisons de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'Depuis l’âge de trente ans, et au dessus, jusqu’à l’âge de cinquante ans, tous ceux qui entraient en rang pour servir au Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Et ceux dont on fit le dénombrement selon leurs familles, étaient deux mille sept cent cinquante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Ce sont là les dénombrés des familles des Kéhathites, tous servant au Tabernacle d’assignation, lesquels Moïse et Aaron dénombrèrent semon le commandement que l’Eternel en avait fait par le moyen de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Or quant aux dénombrés des enfants de Guerson selon leurs familles, et selon les maisons de leurs pères,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'Depuis l’âge de trente ans, et au dessus, jusqu’à l’âge de cinquante ans, tous ceux qui entraient en rang pour servir au Tabernacle d’assignation,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Ceux, dis-je, qui en furent dénombrés selon leurs familles, et selon les maisons de leurs pères, étaient deux mille six cent trente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Ce sont là les dénombrés des familles des enfants de Guerson, tous servant au Tabernacle d’assignation, lesquels Moïse et Aaron dénombrèrent selon le commandement de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Et quant aux dénombrés des familles des enfants de Mérari, selon leurs familles, et selon les maisons de leurs pères,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'Depuis l’âge de trente ans, et au dessus, jusqu’à l’âge de cinquante ans, tous ceux qui entraient en rang, pour servir au Tabernacle d’assignation;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Ceux, dis-je, qui en furent dénombrés selon leurs familles, étaient trois mille deux cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Ce sont là les dénombrés des familles des enfants de Mérari, que Moïse et Aaron dénombrèrent selon le commandement que l’Eternel en avait fait par le moyen de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Ainsi tous ces dénombrés, que Moïse et Aaron et les principaux d’Israël dénombrèrent d’entre les Lévites, selon leurs familles, et selon les maisons de leurs pères;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'Depuis l’âge de trente ans, et au dessus, jusqu’à l’âge de cinquante ans, tous ceux qui entraient en service pour s’employer en ce à quoi il fallait servir, et à ce qu’il fallait porter du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'Tous ceux, dis-je, qui en furent dénombrés, étaient huit mille cinq cent quatre-vingts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'On les dénombra selon le commandement que l’Eternel en avait fait par le moyen de Moïse, chacun selon ce en quoi il avait à servir, et ce qu’il avait à porter, et la charge de chacun fut telle que l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Puis l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Commande aux enfants d’Israël qu’ils mettent hors du camp tout lépreux, tout homme découlant, et tout homme souillé pour un mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Vous les mettrez dehors, tant l’homme que la femme, vous les mettrez, dis- je, hors du camp, afin qu’ils ne souillent point le camp de ceux au milieu desquels j’habite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Et les enfants d’Israël le firent ainsi, et les mirent hors du camp, comme l’Eternel l’avait dit à Moïse; les enfants d’Israël le firent ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Parle aux enfants d’Israël; quand quelque homme ou quelque femme aura commis quelqu’un des péchés que l’homme commet en faisant un crime contre l’Eternel, et qu’une telle personne en sera trouvée coupable;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Alors ils confesseront leur péché, qu’ils auront commis; et le coupable restituera la somme totale de ce en quoi il aura été trouvé coupable, et il y ajoutera un cinquième par-dessus, et le donnera à celui contre lequel il aura commis le délit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Que si cet homme n’a personne à qui appartienne le droit de retrait-lignager pour retirer ce en quoi aura été commis le délit, cette chose-là sera restituée à l’Eternel, et elle appartiendra au Sacrificateur, outre le bélier des propitiations avec lequel on fera propitiation pour lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Pareillement toute offrande élevée d’entre toutes les choses sanctifiées des enfants d’Israël, qu’ils présenteront au Sacrificateur, lui appartiendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Les choses donc que quelqu’un aura sanctifiées appartiendront au Sacrificateur; ce que chacun lui aura donné, lui appartiendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Parle aux enfants d’Israël, et leur dis: Quand la femme de quelqu’un se sera débauchée, et aura commis un crime contre lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'Et que quelqu’un aura couché avec elle, et l’aura connue, sans que son mari en ait rien su; mais qu’elle se soit cachée, et qu’elle se soit souillée, et qu’il n’y ait point de témoin contr’elle, et qu’elle n’ait point été surprise;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'Et que l’esprit de jalousie saisisse son mari, tellement qu’il soit jaloux de sa femme, parce qu’elle s’est souillée; ou que l’esprit de jalousie le saisisse tellement, qu’il soit jaloux de sa femme, encore qu’elle ne se soit point souillée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Cet homme-là fera venir sa femme devant le Sacrificateur, et il apportera l’offrande de cette femme pour elle, savoir la dixième partie d’un Epha de farine d’orge; mais il ne répandra point d’huile dessus; et il n’y mettra point d’encens; car c’est un gâteau de jalousies, un gâteau de mémorial, pour remettre en mémoire l’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Et le Sacrificateur la fera approcher, et la fera tenir debout en la présence de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Puis le Sacrificateur prendra de l’eau sainte dans un vaisseau de terre, et de la poudre qui sera sur le pavé du pavillon, et la mettra dans l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Ensuite le Sacrificateur fera tenir debout la femme en la présence de l’Eternel, il découvrira la tête de cette femme, et il mettra sur les paumes des mains de cette femme le gâteau de mémorial, qui est le gâteau de jalousies; et le Sacrificateur tiendra dans sa main les eaux amères, qui apportent la malédiction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Et le Sacrificateur fera jurer la femme, et lui dira: Si aucun homme n’a couché avec toi, et si étant en la puissance de ton mari tu ne t’es point débauchée et souillée, sois exempte du mal de ces eaux amères qui apportent la malédiction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Mais si étant dans la puissance de ton mari tu t’es débauchée, et tu t’es souillée, et que quelqu’autre que ton mari ait couché avec toi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'Alors le Sacrificateur fera jurer la femme par serment d’exécration, et le Sacrificateur dira à la femme: Que l’Eternel te livre à l’exécration à laquelle tu t’es assujettie par serment, au milieu de ton peuple, l’Eternel faisant tomber ta cuisse, et enfler ton ventre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Et que ces eaux-là qui apportent la malédiction, entrent dans tes entrailles pour te faire enfler le ventre, et faire tomber ta cuisse. Alors la femme répondra, Amen, Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Ensuite le Sacrificateur écrira dans un livre ces exécrations, et les effacera avec les eaux amères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Et il fera boire à la femme les eaux amères qui apportent la malédiction, et les eaux qui apportent la malédiction entreront en elle, pour être des eaux amères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Le Sacrificateur donc prendra de la main de la femme le gâteau de jalousies, et le tournoiera devant l’Eternel, et l’offrira sur l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Le Sacrificateur prendra aussi une pièce du gâteau, pour mémorial de ce gâteau, et le fera fumer sur l’autel; puis il fera boire les eaux à la femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Et après qu’il lui aura fait boire les eaux, s’il est vrai qu’elle se soit souillée et qu’elle ait commis le crime contre son mari, les eaux qui apportent la malédiction entreront en elle, pour être des eaux amères, et son ventre enflera, et sa cuisse tombera; ainsi cette femme-là sera assujettie à l’exécration du serment au milieu de son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Que si la femme ne s’est point souillée, mais qu’elle soit pure, elle ne recevra aucun mal, et elle aura des enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Telle est la Loi des jalousies, quand la femme qui est en la puissance de son mari s’est débauchée, et s’est souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'Ou quand l’esprit de jalousie aura saisi le mari, et qu’étant jaloux de sa femme, il l’aura fait venir devant l’Eternel, et que le Sacrificateur aura fait à l’égard de cette femme tout ce qui est ordonné par cette loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Et l’homme sera exempt de faute; mais cette femme portera son iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'L’Eternel parla aussi a Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Parle aux enfants d’Israël, et leur dis: Quand un homme ou une femme aura fait le voeu de Nazarien, pour se faire Nazarien à l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'Il s’abstiendra de vin et de cervoise, il ne boira d’aucun vinaigre fait de vin ou de cervoise, ni d’aucune liqueur de raisins, et il ne mangera point de raisins frais, ni de raisins secs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Durant tous les jours de son Nazaréat il ne mangera d’aucun fruit de vigne, depuis les pépins jusqu’à la peau du raisin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Le rasoir ne passera point sur sa tête durant tous les jours de son Nazaréat. Il sera saint jusqu’à ce que les jours pour lesquels il s’est fait Nazarien à l’Eternel soient accomplis, et il laissera croître les cheveux de sa tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Durant tous les jours pour lesquels il s’est fait Nazarien à l’Eternel il ne s’approchera d’aucune personne morte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Il ne se souillera point pour son père, ni pour sa mère, ni pour son frère, ni pour sa soeur, quand ils seront morts; car le Nazaréat de son Dieu est sur sa tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Durant tous les jours de son Nazaréat il est saint à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Que si quelqu’un vient à mourir subitement auprès de lui, la tête de son Nazaréat sera souillée, et il rasera sa tête au jour de sa purification, il la rasera le septième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Et le huitième jour il apportera au Sacrificateur deux tourterelles, ou deux pigeonneaux, à l’entrée du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Et le Sacrificateur en sacrifiera l’un pour le péché, et l’autre en holocauste, et il fera propitiation pour lui de ce qu’il a péché à l’occasion du mort; il sanctifiera donc ainsi sa tête en ce jour-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Et il séparera à l’Eternel les jours de son Nazaréat, offrant un agneau d’un an pour le délit, et les premiers jours seront comptés pour rien; car son Nazaréat a été souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Or c’est ici la loi du Nazarien; lorsque les jours de son Nazaréat seront accomplis, on le fera venir à la porte du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Et il fera son offrande l’Eternel d’un agneau d’un an sans tare, en holocauste, et d’une brebis d’un an sans tare, pour le péché, et d’un bélier sans tare, pour le sacrifice de prospérités;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'Et d’une corbeille de pains sans levain de gâteaux de fine farine, pétrie à l’huile, et de beignets sans levain, oints d’huile, avec leur gâteau, et leurs aspersions;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Lesquels le Sacrificateur offrira devant l’Eternel; il sacrifiera aussi sa victime pour le péché, et son holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Et il offrira le bélier en sacrifice de prospérités à l’Eternel, avec la corbeille des pains sans levain; le Sacrificateur offrira aussi son gâteau, et son aspersion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Et le Nazarien rasera la tête de son Nazaréat à l’entrée du Tabernacle d’assignation, et prendra les cheveux de la tête de son Nazaréat, et les mettra sur le feu qui est sous le sacrifice de prospérités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Et le Sacrificateur prendra l’épaule bouillie du bélier, et un gâteau sans levain de la corbeille, et un beignet sans levain, et les mettra sur les paumes des mains du Nazarien, après qu’il se sera fait raser son Nazaréat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Et le Sacrificateur tournoiera ces choses en offrande tournoyée devant l’Eternel; c’est une chose sainte qui appartient au Sacrificateur, avec la poitrine de tournoiement, et l’épaule d’élévation, après quoi le Nazarien pourra boire du vin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Telle est la loi du Nazarien qui aura voué à l’Eternel son offrande pour son Nazaréat, outre ce qu’il aura encore moyen d’offrir; il fera selon son voeu qu’il aura voué, suivant la loi de son Nazaréat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Parle à Aaron et à ses fils, et leur dis: Vous bénirez ainsi les enfants d’Israël, en leur disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'L’Eternel te bénisse, et te garde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'L’Eternel fasse luire sa face sur toi, et te fasse grâce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'L’Eternel tourne sa face vers toi, et te donne la paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Ils mettront donc mon Nom sur les enfants d’Israël, et je les bénirai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Or il arriva le jour que Moïse eut achevé de dresser le pavillon, et qu’il l’eut oint, et l’eut sanctifié avec tous ses ustensiles, et l’autel avec tous ses ustensiles, il arriva, dis-je, après qu’il les eut oints et sanctifiés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Que les principaux d’Israël, et les chefs des familles de leurs pères, qui sont les principaux des Tribus, et qui avaient assisté à faire les dénombrements, firent leur oblation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Et ils amenèrent leur offrande devant l’Eternel, savoir, six chariots couverts, et douze boeufs, chaque chariot pour deux des principaux, et chaque boeuf pour chacun d’eux, et ils les offrirent devant le pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Alors l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Prends ces choses d’eux; et elles seront employées au service du Tabernacle d’assignation; et tu les donneras aux Lévites, à chacun selon son emploi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Moïse donc prit les chariots, et les boeufs, et les donna aux Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Il donna aux enfants de Guerson deux chariots, et quatre boeufs, selon leur emploi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Mais il donna aux enfants de Merari quatre chariots, et huit boeufs, selon leur emploi, sous la conduite d’Ithamar, fils d’Aaron, Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Or il n’en donna point aux enfants de Kéhath, parce que le service du Sanctuaire était de leur charge; ils portaient sur les épaules.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Et les principaux offrirent pour la dédicace de l’autel, le jour qu’il fut oint, les principaux, dis-je, offrirent leur offrande devant l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Et l’Eternel dit à Moïse: Un des principaux offrira un jour, et un autre l’autre jour, son offrande pour la dédicace de l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Le premier jour donc, Nahasson, fils de Hamminadab, offrit son offrande pour la Tribu de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Et son offrande fut un plat d’argent du poids de cent trente sicles, un bassin d’argent de soixante et dix sicles, selon le sicle du Sanctuaire, tous deux pleins de fine farine pétrie à l’huile pour le gâteau;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Une tasse d’or de dix sicles, pleine de parfum;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'Un veau pris du troupeau, un bélier, un agneau d’un an, pour l’holocauste;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'Un jeune bouc pour l’offrande pour le péché;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'Et pour le sacrifice de prospérités, deux taureaux, cinq béliers, cinq boucs, et cinq agneaux d’un an. Telle fut l’offrande de Nahasson, fils de Hamminadab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Le second jour Nathanaël, fils de Tsuhar, chef de la Tribu d’Issacar, offrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Et il offrit pour son offrande un plat d’argent du poids de cent trente sicles, un bassin d’argent de soixante et dix sicles, selon le sicle du Sanctuaire, tous deux pleins de fine farine, pétrie à l’huile pour le gâteau;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Une tasse d’or de dix sicles, pleine de parfum;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'Un veau pris du troupeau, un bélier, un agneau d’un an, pour l’holocauste;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'Un jeune bouc pour l’offrande pour le péché;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'Et pour le sacrifice de prospérités, deux taureaux, cinq béliers, cinq boucs, et cinq agneaux d’un an. Telle fut l’offrande de Nathanaël, fils de Tsuhar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Le troisième jour Eliab, fils de Hélon, chef des enfants de Zabulon, offrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Son offrande fut un plat d’argent, du poids de cent trente sicles, un bassin d’argent de soixante et dix sicles, selon le sicle du Sanctuaire, tous deux pleins de fine farine, pétrie à l’huile pour le gâteau;');
