INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'Le septième jour Elisamah, fils de Hammiud, chef des enfants d’Ephraïm, offrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'Son offrande fut un plat d’argent, du poids de cent trente sicles, un bassin d’argent de soixante et dix sicles, selon le sicle du Sanctuaire, tous deux pleins de fine farine pétrie à l’huile pour le gâteau;');
