INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'Le huitième jour Gamaliel, fils de Pédatsur, chef des enfants de Manassé, offrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'Son offrande fut un plat d’argent, du poids de cent trente sicles, un bassin d’argent de soixante et dix sicles, selon le sicle du Sanctuaire, tous deux pleins de fine farine pétrie à l’huile pour le gâteau;');
