INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Le neuvième jour Abidan, fils de Guidhoni, chef des enfants de Benjamin, offrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Son offrande fut un plat d’argent, du poids de cent trente sicles, un bassin d’argent de soixante et dix sicles, selon le sicle du Sanctuaire, tous deux pleins de fine farine pétrie à l’huile pour le gâteau;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'Une tasse d’or de dix sicles, pleine de parfum;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'Un veau pris du troupeau, un bélier, un agneau d’un an, pour l’holocauste;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'Un jeune bouc pour l’offrande pour le péché;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'Et pour le sacrifice de prospérités, deux taureaux, cinq béliers, cinq boucs, et cinq agneaux d’un an. Telle fut l’offrande d’Abidan, fils de Guidhoni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Le dixième jour Ahihézer, fils de Hammisaddaï, chef des enfants de Dan, offrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Son offrande fut un plat d’argent du poids de cent trente sicles, un bassin d’argent de soixante et dix sicles, selon le sicle au Sanctuaire, tous deux pleins de fine farine pétrie à l’huile pour le gâteau;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'Une tasse d’or de dix sicles, pleine de parfum;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'Un veau pris du troupeau, un bélier, un agneau d’un an, pour l’holocauste;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'Un jeune bouc pour l’offrande pour le péché;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'Et pour le sacrifice de prospérités, deux taureaux, cinq béliers, cinq boucs, et cinq agneaux d’un an. Telle fut l’offrande d’Ahihézer, fils de Hammisaddaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'L’onzième jour Paghiel, fils de Hocran, chef des enfants d’Aser, offrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Son offrande fut un plat d argent, du poids de cent trente sicles, un bassin d’argent de soixante et dix sicles, selon le sicle du Sanctuaire, tous deux pleins de fine farine pétrie à l’huile pour le gâteau;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'Une tasse d’or de dix sicles, pleine de parfum;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'Un veau pris du troupeau, un bélier, un agneau d’un an, pour l’holocauste;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'Un jeune bouc pour l’offrande pour le péché;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'Et pour le sacrifice de prospérités, deux taureaux, cinq béliers, cinq boucs, et cinq agneaux d’un an. Telle fut l’offrande de Paghiel, fils de Hocran.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Le douzième jour Ahirah, fils de Hénan, chef des enfants de Nephthali, offrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Son offrande fut un plat d’argent du poids de cent trente sicles, un bassin d’argent de soixante et dix sicles, selon le sicle du Sanctuaire, tous deux pleins de fine farine pétrie à l’huile pour le gâteau;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'Une tasse d’or de dix sicles, pleine de parfum;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'Un veau pris du troupeau, un bélier, un agneau d’un an, pour l’holocauste;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'Un jeune bouc pour l’offrande pour le péché;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'Et pour le sacrifice de prospérités, deux taureaux, cinq béliers, cinq boucs, et cinq agneaux d’un an. Telle fut l’offrande d’Ahirah, fils de Hénan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Telle fut la dédicace de l’autel, qui fut faite par les principaux d’Israël, lorsqu’il fut oint; Douze plats d’argent, douze bassins d’argent, douze tasses d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Et chaque plat d’argent était de cent trente sicles, et chaque bassin de soixante et dix; tout l’argent des vaisseaux montait à deux mille quatre cents sicles, selon le sicle du Sanctuaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Douze tasses d’or pleines de parfum, chacune de dix sicles, selon le sicle du Sanctuaire; tout l’or donc des tasses montait à six-vingt sicles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Tous les taureaux pour l’holocauste étaient douze veaux, avec douze béliers, et douze agneaux d’un an, avec leurs gâteaux, et douze jeunes boucs pour l’offrande pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Et tous les taureaux du sacrifice de prospérités étaient vingt-quatre veaux, avec soixante béliers, soixante boucs, et soixante agneaux d’un an. Telle fut donc la dédicace de l’autel, après qu’il fut oint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Et quand Moïse entrait au Tabernacle d’assignation, pour parler avec Dieu, il entendait une voix qui lui parlait de dessus le propitiatoire qui était sur l’Arche du Témoignage, d’entre les deux Chérubins, et il lui parlait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Parle à Aaron, et lui dis: Quand tu allumeras les lampes, les sept lampes éclaireront sur le devant du chandelier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Et Aaron le fit ainsi, et il alluma les lampes pour éclairer sur le devant du chandelier, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Or le chandelier était fait de telle manière, qu’il était d’or battu au marteau, d’ouvrage fait au marteau, sa tige aussi, et ses fleurs. On fit ainsi le chandelier selon le modèle que l’Eternel en avait fait voir à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Puis l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Prends les Lévites d’entre les enfants d’Israël, et les purifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Tu leur feras ainsi pour les purifier. Tu feras aspersion sur eux de l’eau de purification; ils feront passer le rasoir sur toute leur chair, ils laveront leurs vêtements, et ils se purifieront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Puis ils prendront un veau pris du troupeau avec son gâteau de fine farine pétrie à l’huile; et tu prendras un second veau pris du troupeau pour l’offrande pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Alors tu feras approcher les Lévites devant le Tabernacle d assignation, et tu convoqueras toute l’assemblée des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Tu feras, dis-je, approcher les Lévites devant l’Eternel, et les enfants d’Israël poseront leurs mains sur les Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Et Aaron présentera les Lévites en offrande devant l’Eternel de la part des enfants d’Israël, et ils seront employés au service de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Et les Lévites poseront leurs mains sur la tête des veaux; puis tu en sacrifieras l’un en offrande pour le péché, et l’autre en holocauste à l’Eternel, afin de faire propitiation pour les Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Après tu feras tenir les Lévites devant Aaron et devant ses fils, et tu les présenteras en offrande à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Ainsi tu sépareras les Lévites d’entre les enfants d’Israël, et les Lévites seront à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Après cela les Lévites viendront pour servir au Tabernacle d’assignation, quand tu les auras purifiés, et présentés en offrande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Car ils me sont entièrement donnés d’entre les enfants d’Israël; je les ai pris pour moi au lieu de tous ceux qui ouvrent la matrice, au lieu de tous les premiers-nés d’entre les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Car tout premier-né d’entre les enfants d’Israël est à moi, tant des hommes que des bêtes; je me les suis sanctifiés le jour que je frappai tout premier- né au pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Or j’ai pris les Lévites au lieu de tous les premiers-nés d’entre les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'Et j’ai entièrement donné d’entre les enfants d’Israël les Lévites à Aaron et à ses fils, pour faire le service des enfants d’Israël dans le Tabernacle d’assignation, et pour servir de rachat pour les enfants d’Israël; afin qu’il n’y ait point de plaie sur les enfants d’Israël, comme il y aurait si les enfants d’Israël s’approchaient du Sanctuaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Moïse et Aaron, et toute l’assemblée des enfants d’Israël firent aux Lévites toutes les choses que l’Eternel avait commandées à Moïse touchant les Lévites; les enfants d’Israël le firent ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Les Lévites donc se purifièrent, et lavèrent leurs vêtements, et Aaron les présenta en offrande devant l’Eternel, et fit propitiation pour eux afin de les purifier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Cela étant fait, les Lévites vinrent pour faire leur service au Tabernacle d’assignation devant Aaron, et devant ses fils; et on leur fit comme l’Eternel l’avait commandé à Moïse touchant les Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Puis l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'C’est ici ce qui concerne les Lévites. Le Lévite depuis l’âge de vingt-cinq ans et au dessus, entrera en service pour être employé au Tabernacle d’assignation;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Mais depuis l’âge de cinquante ans il sortira de service, et ne servira plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Cependant il servira ses frères au Tabernacle d’assignation, pour garder ce qui leur a été commis, mais il ne fera aucun service; tu feras donc ainsi aux Lévites touchant leurs charges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'L’Eternel avait aussi parlé à Moïse dans le désert de Sinaï, le premier mois de la seconde année, après qu’ils furent sortis du pays d’Egypte, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Que les enfants d’Israël fassent la Pâque en sa saison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Vous la ferez en sa saison, le quatorzième jour de ce mois entre les deux vêpres, selon toutes ses ordonnances, et selon tout ce qu’il y faut faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Moïse donc parla aux enfants d’Israël, afin qu’ils fissent la Pâque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Et ils firent la Pâque au premier mois, le quatorzième jour du mois, entre les deux vêpres, au désert de Sinaï; selon tout ce que l’Eternel avait commandé à Moïse, les enfants d’Israël le firent ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Or il y en eut quelques-uns qui étant souillés pour un mort ne purent point faire la Pâque ce jour-là, et ils se présentèrent ce même jour devant Moïse et devant Aaron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'Et ces hommes-là leur dirent: Nous sommes souillés pour un mort, pourquoi serions-nous privés d’offrir l’offrande à l’Eternel en sa saison parmi les enfants d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Et Moïse leur dit: Arrêtez-vous, et j’entendrai ce que l’Eternel commandera sur votre sujet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Alors l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Parle aux enfants d’Israël, et leur dis: Quand quelqu’un d’entre vous, ou de votre postérité, sera souillé pour un mort, ou qu’il sera en voyage dans un lieu éloigné, il fera cependant la Pâque à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Ils la feront le quatorzième jour du second mois entre les deux vêpres; et ils la mangeront avec du pain sans levain, et des herbes amères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Ils n’en laisseront rien jusqu’au matin, et n’en casseront point les os; ils la feront selon toute l’ordonnance de la Pâque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Mais si quelqu’un étant net, ou n’étant point en voyage, s’abstient de faire la Pâque, cette personne-là sera retranchée d’entre ses peuples; cet homme-là portera son péché, parce qu’il n’aura point offert l’offrande de l’Eternel en sa saison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Et quand quelque étranger qui habitera parmi vous fera la Pâque à l’Eternel, il la fera selon l’ordonnance de la Pâque, et selon qu’il la faut faire. II y aura une même ordonnance entre vous, pour l’étranger et pour celui qui est né au pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Or le jour que le pavillon fut dressé la nuée couvrit le pavillon sur le Tabernacle du Témoignage; et le soir elle parut comme un feu sur le Tabernacle, jusques au matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Il en fut ainsi continuellement; la nuée le couvrait, mais elle paraissait la nuit comme du feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Et selon que la nuée se levait de dessus le Tabernacle les enfants d’Israël partaient; et au lieu où la nuée s’arrêtait, les enfants d’Israël y campaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Les enfants d’Israël marchaient au commandement de l’Eternel, et ils campaient au commandement de l’Eternel; pendant tous les jours que la nuée se tenait sur le pavillon ils demeuraient campés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Et quand la nuée continuait à s’arrêter plusieurs jours sur le pavillon, les enfants d’Israël prenaient garde à l’Eternel, et ne partaient point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Et pour peu de jours que la nuée fût sur le pavillon, ils campaient au commandement de l’Eternel, et ils partaient au commandement de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Et quand la nuée y était depuis le soir jusqu’au matin, et que la nuée se levait au matin, ils partaient; fût-ce de jour ou de nuit, quand la nuée se levait, ils partaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Que si la nuée continuait de s’arrêter sur le pavillon, et y demeurait pendant deux jours, ou un mois, ou plus longtemps, les enfants d’Israël demeuraient campés, et ne partaient point; mais quand elle se levait, ils partaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Ils campaient donc au commandement de l’Eternel, et ils partaient au commandement de l’Eternel; et ils prenaient garde à l’Eternel, suivant le commandement de l’Eternel, qu’il leur faisait savoir par Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Puis l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Fais-toi deux trompettes d’argent, fais-les d’ouvrage battu au marteau; et elles te serviront pour convoquer l’assemblée, et pour faire partir les compagnies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Quand on en sonnera, toute l’assemblée s’assemblera vers toi à l’entrée du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Et quand on sonnera d’une seule, les principaux, qui sont les chefs des milliers d’Israël, s’assembleront vers toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Mais quand vous sonnerez avec un retentissement bruyant, les compagnies qui sont campées vers l’Orient partiront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Et quand vous sonnerez la seconde fois avec un retentissement bruyant, les compagnies qui sont campées vers le Midi partiront; on sonnera avec un retentissement bruyant, quand on voudra partir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Et quand vous convoquerez l’assemblée, vous sonnerez, mais non point avec un retentissement bruyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Or les fils d’Aaron Sacrificateurs, sonneront des trompettes; et ceci vous sera une ordonnance perpétuelle en vos âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Et quand vous marcherez en bataille dans votre pays contre votre ennemi, venant vous attaquer; vous sonnerez des trompettes avec un retentissement bruyant, et l’Eternel votre Dieu se souviendra de vous, et vous serez délivrés de vos ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Aussi dans vos jours de joie, dans vos fêtes solennelles, et au commencement de vos mois, vous sonnerez des trompettes sur vos holocaustes, et sur vos sacrifices de prospérités, et elles vous serviront de mémorial devant votre Dieu; je suis l’Eternel, votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Or il arriva le vingtième jour du second mois de la seconde année, que la nuée se leva de dessus le pavillon du Témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Et les enfants d’Israël partirent selon leurs traittes, du désert de Sinaï, et la nuée se posa au désert de Paran.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Ils partirent donc pour la première fois, suivant le commandement de l’Eternel, déclaré par Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Et la bannière des compagnies des enfants de Juda partit la première, selon leurs troupes; et Nahasson, fils de Hamminadab, conduisait la bande de Juda;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Et Nathanaël, fils de Tsuhar, conduisait la bande de la Tribu des enfants d’Issacar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'Et Eliab, fils de Hélon, conduisait la bande de la Tribu des enfants de Zabulon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Et le pavillon fut désassemblé; puis les enfants de Guerson, et les enfants de Mérari, qui portaient le pavillon, partirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Puis la bannière des compagnies de Ruben partit, selon leurs troupes; et Elitsur, fils de Sédéur, conduisait la bande de Ruben.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Et Sélumiel, fils de Tsurisaddaï, conduisait la bande de la Tribu des enfants de Siméon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'Et Eliasaph, fils de Déhuël, conduisait la bande des enfants de Gad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Alors les Kéhathites, qui portaient le Sanctuaire, partirent; cependant on dressait le Tabernacle, tandis que ceux-ci venaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Puis la bannière des compagnies des enfants d’Ephraïm partit, selon leurs troupes; et Elisamah, fils de Hammihud, conduisait la bande d’Ephraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Et Gamaliel, fils de Pédatsur, conduisait la bande de la Tribu des enfants de Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Et Abidan, fils de Guidhoni, conduisait la bande de la Tribu des enfants de Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Enfin la bannière des compagnies des enfants de Dan, qui faisait l’arrière- garde, partit, selon leurs troupes; et Ahihézer, fils de Hammisaddaï, conduisait la bande de Dan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Et Paghiel, fils de Hocran, conduisait la bande de la Tribu des enfants d’Aser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'Et Ahirah, fils de Hénan, conduisait la bande de la Tribu des enfants de Nephthali.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Tels étaient les décampements des enfants d’Israël selon leurs troupes, quand ils partaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Or Moïse dit à Hobab, fils de Réhuel Madianite, son beau-père: Nous allons au lieu duquel l’Eternel a dit, je vous le donnerai. Viens avec nous, et nous te ferons du bien; car l’Eternel a promis de faire du bien à Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Et Hobab lui répondit: Je n’y irai point, mais je m’en irai en mon pays, et vers ma parenté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Et Moïse lui dit: Je te prie, ne nous quitte point; car tu nous serviras de guide, parce que tu connais les lieux où nous aurons à camper dans le désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Et il arrivera que quand tu seras venu avec nous, et que le bien que l’Eternel nous doit faire sera arrivé, nous te ferons aussi du bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Ainsi ils partirent de la montagne de l’Eternel, et ils marchèrent le chemin de trois jours; et l’Arche de l’alliance de l’Eternel alla devant eux pendant le chemin de trois jours pour chercher un lieu où ils se reposassent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Et la nuée de l’Eternel était sur eux le jour, quand ils partaient du lieu où ils avaient campé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Or il arrivait qu’au départ de l’Arche, Moïse disait: Lève-toi, ô Eternel, et tes ennemis seront dispersés, et ceux qui te haïssent s’enfuiront de devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Et quand on la posait, il disait: Retourne, ô Eternel, aux dix mille milliers d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Après il arriva que le peuple se plaignit de la fatigue, et l’Eternel l’ouït, et l’Eternel l’ayant ouï, sa colère s’embrasa, et le feu de l’Eternel s’alluma parmi eux, et en consuma quelques-uns à l’extrémité du camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Alors le peuple cria à Moïse, et Moïse pria l’Eternel, et le feu s’éteignit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Et on nomma ce lieu-là Tabhérah, parce que le feu de l’Eternel s’était allumé parmi eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Et le peuple ramassé qui était parmi eux, fut épris de convoitise, et même les enfants d’Israël se mirent à pleurer, disant: Qui nous fera manger de la chair?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Il nous souvient des poissons que nous mangions en Egypte, sans qu’il nous en coûtât rien, des concombres, des melons, des poireaux, des oignons, et des aulx.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Et maintenant nos âmes sont asséchées; nos yeux ne voient rien que Manne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Or la Manne était comme le grain de coriandre, et sa couleur était comme la couleur du Bdellion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Le peuple se dispersait, et la ramassait, puis il la moulait aux meules, ou la pilait dans un mortier, et la faisait cuire dans un chauderon, et en faisait des gâteaux, dont le goût était semblable à celui d’une liqueur d’huile fraîche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Et quand la rosée était descendue la nuit sur le camp, la Manne descendait dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Moïse donc entendit le peuple pleurant dans leurs familles, chacun à l’entrée de sa tente; et l’Eternel en fut extrêmement irrité, et Moïse en fut affligé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Et Moïse dit à l’Eternel: Pourquoi as-tu affligé ton serviteur? et pourquoi n’ai-je pas trouvé grâce devant toi, que tu aies mis sur moi la charge de tout ce peuple?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Est-ce moi qui ai conçu tout ce peuple; ou l’ai-je engendré, pour me dire: Porte-le dans ton sein, comme le nourricier porte un enfant qui tette, porte- le jusqu’au pays pour lequel tu as juré à ses pères?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'D’où aurais-je de la chair pour en donner à tout ce peuple? car il pleure après moi, en disant: Donne-nous de la chair, afin que nous en mangions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Je ne puis moi seul porter tout ce peuple, car il est trop pesant pour moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Que si tu agis ainsi à mon égard, je te prie, si j’ai trouvé grâce devant toi, de me faire mourir, afin que je ne voie point mon malheur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Alors l’Eternel dit à Moïse: Assemble-moi soixante et dix hommes d’entre les Anciens d’Israël, que tu connais être les Anciens du peuple et ses officiers, et les amène au Tabernacle d’assignation, et qu’ils se présentent là avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Puis je descendrai, et je parlerai là avec toi, et je mettrai à part de l’Esprit qui est sur toi, et je le mettrai sur eux; afin qu’ils portent avec toi la charge du peuple, et que tu ne la portes point toi seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Et tu diras au peuple: Apprêtez-vous pour demain, et vous mangerez de la chair; parce que vous avez pleuré, l’Eternel l’entendant, et que vous avez dit: Qui nous fera manger de la chair? car nous étions bien en Egypte; ainsi l’Eternel vous donnera de la chair, et vous en mangerez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Vous n’en mangerez pas un jour, ni deux jours, ni cinq jours, ni dix jours, ni vingt jours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'Mais jusqu’à un mois entier, jusqu’à ce qu’elle vous sorte par les narines, et que vous la rendiez par la bouche, parce que vous avez rejeté l’Eternel, qui est au milieu de vous, et que vous avez pleuré devant lui, en disant: Pourquoi sommes-nous sortis d’Egypte?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Et Moïse dit: Il y a six cent mille hommes de pied en ce peuple au milieu duquel je suis, et tu as dit: Je leur donnerai de la chair afin qu’ils en mangent un mois entier!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Leur tuera-t-on des brebis ou des boeufs, en sorte qu’il y en ait assez pour eux? ou leur assemblera-t-on tous les poissons de la mer, jusqu’à ce qu’il y en ait assez pour eux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Et l’Eternel répondit à Moïse: La main de l’Eternel est-elle raccourcie? tu verras maintenant si ce que je t’ai dit arrivera, ou non.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Moïse donc s’en alla, et récita au peuple les paroles de l’Eternel, et il assembla soixante-dix hommes d’entre les Anciens du peuple, et les fit tenir à l’entour du Tabernacle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Alors l’Eternel descendit dans la nuée, et parla à Moïse, et ayant mis à part de l’Esprit qui était sur lui, il le mit sur ces soixante-dix hommes Anciens. Et il arriva qu’aussitôt que l’Esprit reposa sur eux, ils prophétisèrent; mais ils ne continuèrent pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Or il en était demeuré deux au camp, dont l’un s’appelait Eldad, et l’autre, Médad, sur lesquels l’Esprit reposa, et ils étaient de ceux dont les noms avaient été écrits, mais ils n’étaient point allés au Tabernacle et ils prophétisaient dans le camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Alors un garçon courut le rapporter à Moïse, en disant: Eldad et Médad prophétisent dans le camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Et Josué, fils de Nun, qui servait Moïse, l’un de ses jeunes gens, répondit, en disant: Mon seigneur Moïse, empêche-les.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Et Moïse lui répondit: Es-tu jaloux pour moi? Plût à Dieu que tout le peuple de l’Eternel fût Prophète, et que l’Eternel mît son Esprit sur eux!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Puis Moïse se retira au camp, lui et les Anciens d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Alors l’Eternel fit lever un vent, qui enleva des cailles de devers la mer, et les répandit sur le camp environ le chemin d’une journée, deçà et delà, tout autour du camp; et il y en avait presque la hauteur de deux coudées sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Et le peuple se leva tout ce jour-là, et toute la nuit, et tout le jour suivant, et amassa des cailles; celui qui en avait amassé le moins en avait dix Chomers; et ils les étendirent soigneusement pour eux tout autour du camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Mais la chair étant encore entre leurs dents, avant qu’elle fût mâchée, la colère de l’Eternel s’embrasa contre le peuple, et il frappa le peuple d’une très-grande plaie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Et on nomma ce lieu-là Kibroth-taava; car on ensevelit là le peuple qui avait convoité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Et de Kibroth-taava le peuple s’en alla en Hatséroth, et ils s’arrêtèrent en Hatséroth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Alors Marie et Aaron parlèrent contre Moïse à l’occasion de la femme Ethiopienne qu’il avait prise, car il avait pris une femme Ethiopienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Et ils dirent: Est-ce que l’Eternel a parlé seulement par Moïse? n’a-t-il point aussi parlé par nous? et l’Eternel ouït cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Or cet homme Moïse était fort doux, et plus que tous les hommes qui étaient sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Et incontinent l’Eternel dit à Moïse, à Aaron, et à Marie: Venez vous trois au Tabernacle d’assignation; et ils y allèrent eux trois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Alors l’Eternel descendit dans la colonne de nuée, et se tint à l’entrée du Tabernacle; puis il appela Aaron et Marie, et ils vinrent eux deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Et il dit: Ecoutez maintenant mes paroles: S’il y a quelque Prophète entre vous, moi qui suis l’Eternel je me ferai bien connaître à lui en vision, et je lui parlerai en songe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Mais il n’en est pas ainsi de mon serviteur Moïse, qui est fidèle en toute ma maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Je parle avec lui bouche à bouche, et il me voit en effet, et non point en obscurité, ni dans aucune représentation de l’Eternel. Pourquoi donc n’avez- vous pas craint de parler contre mon Serviteur, contre Moïse?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Ainsi la colère de l’Eternel s’embrasa contre eux; et il s’en alla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Car la nuée se retira de dessus le Tabernacle; et voici Marie était lépreuse, blanche comme neige; et Aaron regardant Marie, la vit lépreuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Alors Aaron dit à Moïse: Hélas, mon seigneur! je te prie ne mets point sur nous ce péché, car nous avons fait follement, et nous avons péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Je te prie qu’elle ne soit point comme un enfant mort, dont la moitié de la chair est déjà consumée quand il sort du ventre de sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Alors Moïse cria à l’Eternel, en disant: Ô Dieu Fort, je te prie, guéris- la, je t’en prie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Et l’Eternel répondit à Moïse: Si son père lui avait craché en colère au visage, n’en serait-elle pas dans l’ignominie pendant sept jours? Qu’elle demeure donc enfermée sept jours hors du camp, et après elle y sera reçue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Ainsi Marie fut enfermée hors du camp sept jours; et le peuple ne partit point de là jusqu’à ce que Marie fût reçue dans le camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Après cela le peuple partit de Hatséroth, et ils campèrent au désert de Paran.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Envoie des hommes pour reconnaître le pays de Canaan, que je donne aux enfants d’Israël. Vous enverrez un homme de chaque Tribu de leurs pères, tous des principaux d’entr’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Moïse donc les envoya du désert de Paran, selon le commandement de l’Eternel; et tous ces hommes étaient chefs des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Et ce sont ici leurs noms: De la Tribu de Ruben, Sammuah, fils de Zaccur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'De la Tribu de Siméon, Saphat, fils de Hori.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'De la Tribu de Juda, Caleb, fils de Jéphunné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'De la Tribu d’Issacar, Jigueal, fils de Joseph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'De la Tribu d’Ephraïm, Osée, fils de Nun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'De la Tribu de Benjamin, Palti, fils de Raphu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'De la Tribu de Zabulon, Gaddiel, fils de Sodi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'De l’autre Tribu de Joseph, savoir de la Tribu de Manassé, Gaddi, fils de Susi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'De la Tribu de Dan, Hammiel, fils de Guemalli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'De la Tribu d’Aser, Séthur, fils de Micaël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'De la Tribu de Nephthali, Nahbi, fils de Vaphsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'De la Tribu de Gad, Guéuel, fils de Maki.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Ce sont là les noms des hommes que Moïse envoya pour reconnaître le pays. Or Moïse avait nommé Osée, fils de Nun, Josué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'Moïse donc les envoya pour reconnaître le pays de Canaan, et il leur dit: Montez de ce côté vers le Midi, puis vous monterez sur la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'Et vous verrez quel est ce pays-là, et quel est le peuple qui l’habite, s’il est fort, ou faible; s’il est en petit ou en grand nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'Et quel est le pays où il habite, s’il est bon ou mauvais; et quelles sont les villes dans lesquelles il habite, si c’est dans des tentes, ou dans des villes closes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Et quel est le terroir, s’il est gras ou maigre, s’il y a des arbres, ou non. Ayez bon courage, et prenez du fruit du pays. Or c’était alors le temps des premiers raisins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Etant donc partis, ils examinèrent le pays, depuis le désert de Tsin jusqu’à Réhob, à l’entrée de Hamath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Ils montèrent donc vers le Midi, et vinrent jusqu’à Hébron, où étaient Ahiman, Sésaï, et Talmaï, issus de Hanak. Or Hébron avait été bâtie sept ans avant Tsohan d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Et ils vinrent jusqu’au torrent d’Escol, et coupèrent de là un sarment de vigne, avec une grappe de raisins; et ils étaient deux à le porter avec un levier. Ils apportèrent aussi des grenades et des figues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Et on appela ce lieu-là Nahal-Escol; à l’occasion de la grappe que les enfants d’Israël y coupèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Et au bout de quarante jours ils furent de retour du pays qu’ils étaient allés reconnaître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Et étant arrivés, ils vinrent vers Moïse et Aaron, et vers toute l’assemblée des enfants d’Israël, au désert de Padan en Kadès; et leur ayant fait leur rapport, et à toute l’assemblée, ils leur montrèrent du fruit du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Ils firent donc leur rapport à Moïse, et lui dirent: Nous avons été au pays où tu nous avais envoyés; et véritablement c’est un pays découlant de lait et de miel, et c’est ici de son fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Il y a seulement ceci, que le peuple qui habite au pays est robuste, et les villes sont closes, et fort grandes; nous y avons vu aussi les enfants de Hanak.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Les Hamalécites habitent au pays du Midi; et les Héthiens, les Jébusiens, et les Amorrhéens habitent en la montagne; et les Cananéens habitent le long de la mer, et vers le rivage du Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Alors Caleb fit taire le peuple devant Moïse, et dit: Montons hardiment, et possédons ce pays-là, car certainement nous y serons les plus forts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Mais les hommes qui étaient montés avec lui, dirent: Nous ne saurions monter contre ce peuple-là, car il est plus fort que nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Et ils décrièrent devant les enfants d’Israël le pays qu’ils avaient examiné, en disant: Le pays par lequel nous sommes passés pour le reconnaître est un pays qui consume ses habitants, et tous le peuple que nous y avons vus, sont des gens de grande stature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 34, 'Nous y avons vu aussi des géants, des enfants de Hanak, de la race des géants; et nous ne paraissions auprès d’eux que comme des sauterelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Alors toute l’assemblée s’éleva, et se mit à jeter des cris, et le peuple pleura cette nuit-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Et tous les enfants d’Israël murmurèrent contre Moïse et contre Aaron; et toute l’assemblée leur dit: Plût à Dieu que nous fussions morts au pays d’Egypte, ou en ce désert! plût à Dieu que nous fussions morts!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Et pourquoi l’Eternel nous conduit-il vers ce pays-là, pour y tomber par l’épée; nos femmes et nos petits enfants seront en proie. Ne nous vaudrait-il pas mieux retourner en Egypte?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Et ils se dirent l’un à l’autre: Etablissons-nous un chef, et retournons en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Alors Moïse et Aaron tombèrent sur leurs visages devant toute l’assemblée des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Et Josué, fils de Nun, et Caleb, fils de Jéphunné, qui étaient de ceux qui avaient examiné le pays, déchirèrent leurs vêtements;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'Et parlèrent à toute l’assemblée des enfants d’Israël, en disant: Le pays par lequel nous avons passé pour le reconnaître est un fort bon pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Si nous sommes agréables à l’Eternel, il nous fera entrer en ce pays-là, et il nous le donnera. C’est un pays découlant de lait et de miel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Seulement ne soyez point rebelles contre l’Eternel, et ne craignez point le peuple de ce pays-là; car ils seront notre pain; leur protection s’est retirée de dessus eux, et l’Eternel est avec nous; ne les craignez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Alors toute l’assemblée parla de les lapider; mais la gloire de l’Eternel apparut à tous les enfants d’Israël au Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Et l’Eternel dit à Moïse: Jusques-à quand ce peuple-ci m’irritera-t-il par mépris, et jusques-à quand ne croira-t-il point en moi, après tous les signes que j’ai faits au milieu de lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Je le frapperai de mortalité, et je le détruirai; mais je te ferai devenir un peuple plus grand et plus fort qu’il n’est.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Et Moïse dit à l’Eternel: Mais les Egyptiens l’entendront, car tu as fait monter par ta force ce peuple-ci du milieu d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'Et ils diront avec les habitants de ce pays qui auront entendu que tu étais, ô Eternel! au milieu de ce peuple, et que tu apparaissais, ô Eternel! à vue d’oeil, que ta nuée s’arrêtait sur eux, et que tu marchais devant eux le jour dans la colonne de nuée, et la nuit dans la colonne de feu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Quand tu auras fait mourir ce peuple, comme un seul homme, les nations qui auront entendu parler de ton Nom, tiendront ce langage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Parce que l’Eternel ne pouvait faire entrer ce peuple au pays qu il avait juré de leur donner, il les a tués au désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Or maintenant, je te prie, que la puissance du Seigneur soit magnifiée, comme tu as parlé, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'L’Eternel est tardif à colère, et abondant en gratuité, ôtant l’iniquité, et le péché, et qui ne tient nullement le coupable pour innocent, punissant l’iniquité des pères sur les enfants, jusqu’à la troisième et à la quatrième génération.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Pardonne, je te prie, l’iniquité de ce peuple, selon la grandeur de ta gratuité, comme tu as pardonné à ce peuple, depuis l’Egypte jusqu’ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Et l’Eternel dit: J’ai pardonné selon ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Mais certainement je suis vivant, et la gloire de l’Eternel remplira toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Car quant à tous les hommes qui ont vu ma gloire, et les signes que j ai faits en Egypte et au désert qui m’ont déjà tenté par dix fois, et qui n ont point obéi à ma voix;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'S’ils voient jamais le pays que j’avais juré à leurs pères de leur donner, tous ceux, dis-je, qui m’ont irrité par mépris, ne le verront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Mais parce que mon serviteur Caleb a été animé d’un autre esprit, et qu’il a persévéré à me suivre, aussi le ferai-je entrer au pays où il a été, et sa postérité le possédera en héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Or les Hamalécites et les Cananéens habitent en la vallée; retournez demain en arrière, et vous en allez au désert par le chemin de la mer Rouge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'L’Eternel parla aussi à Moïse et à Aaron, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Jusques à quand continuera cette méchante assemblée qui murmure contre moi? J’ai entendu les murmures des enfants d’Israël, par lesquels ils murmurent contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Dis-leur: Je suis vivant, dit l’Eternel, si je ne vous fais ainsi que vous avez parlé, et comme je l’ai ouï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Vos charognes tomberont dans ce désert, et tous ceux d’entre vous qui ont été dénombrés selon tout le compte que vous en avez fait, depuis l’âge de vingt ans, et au dessus, vous tous qui avez murmuré contre moi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Si vous entrez au pays, pour lequel j’avais levé ma main, jurant que je vous y ferais habiter, excepté Caleb, fils de Jéphunné, et Josué, fils de Nun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Et quant à vos petits enfants, dont vous avez dit qu’ils seraient en proie, je les y ferai entrer, et ils sauront quel est ce pays que vous avez méprisé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Mais quant à vous, vos charognes tomberont dans ce désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Mais vos enfants seront paissant dans ce désert quarante ans; et ils porteront la peine de vos paillardises, jusqu’à ce que vos charognes soient consumés au désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Selon le nombre des jours que vous avez mis à reconnaître le pays, qui ont été quarante jours, un jour pour une année, vous porterez la peine de vos iniquités quarante ans, et vous connaîtrez que j’ai rompu le cours de mes bénédictions sur vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Je suis l’Eternel qui ai parlé, si je ne fais ceci à toute cette méchante assemblée, à ceux qui se sont assemblés contre moi; ils seront consumés en ce désert, et ils y mourront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Les hommes donc que Moïse avait envoyés pour épier le pays, et qui étant de retour avaient fait murmurer contre lui toute l’assemblée, en diffamant le pays;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'Ces hommes-là qui avaient décrié le pays, moururent de plaie devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Mais Josué, fils de Nun, et Caleb, fils de Jéphunné, vécurent d’entre ceux qui étaient allés reconnaître le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Or Moïse dit ces choses-là à tous les enfants d’Israël, et le peuple en mena un fort grand deuil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Puis s’étant levés de bon matin, ils montèrent sur le haut de la montagne, en disant: Nous voici, et nous monterons au lieu dont l’Eternel a parlé; car nous avons péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Mais Moïse leur dit: Pourquoi transgressez-vous le commandement de l’Eternel? cela ne réussira point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'N’y montez point; car l’Eternel n’est point au milieu de vous; afin que vous ne soyez pas battus devant vos ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Car les Hamalécites et les Cananéens sont là devant vous, et vous tomberez par l’épée; à cause que vous avez cessé de suivre l’Eternel, l’Eternel aussi ne sera point avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Toutefois ils s’obstinèrent de monter sur le haut de la montagne, mais l’Arche de l’alliance de l’Eternel et Moïse ne bougèrent point du milieu du camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Alors les Hamalécites et les Cananéens qui habitaient en cette montagne-là, descendirent, et les battirent, et les mirent en déroute jusqu’en Horma.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Puis l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Parle aux enfants d’Israël, et leur dis: Quand vous serez entrés au pays où vous devez demeurer, lequel je vous donne;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'Et que vous voudrez faire un sacrifice par feu à l’Eternel, un holocauste, ou un autre sacrifice, pour s’acquitter de quelque voeu, ou volontairement, ou dans vos fêtes solennelles, pour faire une offrande de bonne odeur à l’Eternel, du gros ou du menu bétail;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'Celui qui offrira son offrande à l’Eternel, offrira avec elle un gâteau de fleur de farine d’une dixième, pétrie avec la quatrième partie d’un Hin d’huile;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Et la quatrième partie d’un Hin de vin pour l’aspersion que tu feras sur l’holocauste, ou sur quelque autre sacrifice pour chaque agneau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Que si c’est pour un bélier, tu feras un gâteau de deux dixièmes de fleur de farine, pétrie avec la troisième partie d’un Hin d’huile;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'Et la troisième partie d’un Hin de vin pour l’aspersion, que tu offriras en bonne odeur à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Et si tu sacrifies un veau en holocauste, ou tel autre sacrifice, pour s’acquitter de quelque voeu important, ou pour faire un sacrifice de prospérités à l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'On offrira avec le veau un gâteau de trois dixièmes de fleur de farine, pétrie avec la moitié d’un Hin d’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'Et tu offriras la moitié d’un Hin de vin pour l’aspersion, en offrande faite par feu de bonne odeur à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'On en fera de même pour chaque taureau, chaque bélier, et chaque petit d’entre les brebis et d’entre les chèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Selon le nombre que vous en sacrifierez, vous ferez ainsi à chacun, selon leur nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Tous ceux qui sont nés au pays feront ces choses de cette manière, en offrant un sacrifice fait par feu en bonne odeur à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Que si quelque étranger, ou quelque autre parmi vous, qui faisant son séjour avec vous, en vos âges, fait un sacrifice par feu en bonne odeur à l’Eternel, il fera comme vous ferez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Ô assemblée! il y aura une même ordonnance pour vous et pour l’étranger qui fait son séjour parmi vous, il y aura une même ordonnance perpétuelle en vos âges; il en sera de l’étranger comme de vous en la présence de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Il y aura une même loi et un même droit pour vous et pour l’étranger qui fait son séjour parmi vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Parle aux enfants d’Israël, et leur dis: Quand vous serez entrés au pays où je vous ferai entrer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'Et que vous mangerez du pain du pays, vous en offrirez à l’Eternel une offrande élevée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Vous offrirez en offrande élevée un gâteau pour les prémices de votre pâte; vous l’offrirez à la façon de l’offrande élevée prise de l’aire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Vous donnerez donc en vos âges à l’Eternel une offrande élevée, prise des prémices de votre pâte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Et lorsque vous aurez péché par erreur, et que vous n’aurez pas fait tous ces commandements que l’Eternel a donnés à Moïse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'Tout ce que l’Eternel vous a commandé par le moyen de Moïse, depuis le jour que l’Eternel a commencé de donner ses commandements, et dans la suite en vos âges;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'S’il arrive que la chose ait été faite par erreur, sans que l’assemblée l’ait aperçue, toute l’assemblée sacrifiera en holocauste en bonne odeur à l’Eternel, un veau pris du troupeau, avec son gâteau et son aspersion, selon l’ordonnance, et un jeune bouc en offrande pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Ainsi le Sacrificateur fera propitiation pour toute l’assemblée des enfants d’Israël, et il leur sera pardonné; parce que c’est une chose arrivée par erreur; et ils amèneront devant l’Eternel leur offrande qui doit être un sacrifice fait par feu à l’Eternel, et l’offrande pour leur péché, à cause de leur erreur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Alors il sera pardonné à toute l’assemblée des enfants d’Israël, et à l’étranger qui fait son séjour parmi eux, parce que cela est arrivé à tout le peuple par erreur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Que si une personne seule a péché par erreur, elle offrira en offrande pour le péché une chèvre d’un an.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Et le Sacrificateur fera propitiation pour la personne qui aura péché par erreur, de ce qu’elle aura péché par erreur devant l’Eternel, et faisant propitiation pour elle, il lui sera pardonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Il y aura une même loi pour celui qui aura fait quelque chose par erreur, tant pour celui qui est né au pays des enfants d’Israël, que pour l’étranger qui fait son séjour parmi eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Mais quant à celui qui aura péché par fierté, tant celui qui est né au pays, que l’étranger, il a outragé l’Eternel; cette personne-là sera retranchée du milieu de son peuple;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Parce qu’il a méprisé la parole de l’Eternel, et qu’il a enfreint son commandement. Cette personne donc sera certainement retranchée; son iniquité est sur elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Or les enfants d’Israël étant au désert, trouvèrent un homme qui ramassait du bois le jour du Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Et ceux qui le trouvèrent ramassant du bois, l’amenèrent à Moïse et à Aaron, et à toute l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Et on le mit en garde; car il n’avait pas encore été déclaré ce qu’on lui devait faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Alors l’Eternel dit à Moïse: On punira de mort cet homme-là, et toute l’assemblée le lapidera hors du camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Toute l’assemblée donc le mena hors du camp, et ils le lapidèrent, et il mourut; comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Parle aux enfants d’Israël, et leur dis: Qu’ils se fassent d’âge en âge des bandes aux pans de leurs vêtements, et qu’ils mettent sur les bandes des pans de leurs vêtements un cordon de couleur de pourpre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Ce cordon sera sur la bande, et en le voyant il vous souviendra de tous les commandements de l’Eternel, afin que vous les fassiez, et que vous ne suiviez point les pensées de votre coeur, ni les désirs de vos yeux, en suivant lesquels vous paillardez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Afin que vous vous souveniez de tous mes commandements, et que vous les fassiez, et que vous soyez saints à votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Je suis l’Eternel votre Dieu, qui vous ai retirés du pays d’Egypte, pour être votre Dieu; je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Or Coré, fils de Jitshar, fils de Kéhath, fils de Lévi, fit une entreprise, avec Dathan et Abiram enfants d’Eliab, et On, fils de Péleth, enfants de Ruben;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'Et ils s’élevèrent contre Moïse, avec deux cent cinquante hommes des enfants d’Israël, qui étaient des principaux de l’assemblée, lesquels on appelait pour tenir le conseil, et qui étaient des gens de réputation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Et ils s’assemblèrent contre Moïse et contre Aaron, et leur dirent: Qu’il vous suffise, puisque tous ceux de l’assemblée sont saints, et que l’Eternel est au milieu d’eux, pourquoi vous élevez-vous par dessus l’assemblée de l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Ce que Moïse ayant entendu, il se prosterna le visage contre terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Et il parla à Coré et à tous ceux qui étaient assemblés avec lui, et leur dit: Demain au matin l’Eternel donnera à connaître celui qui lui appartient, et celui qui est le saint, et il le fera approcher de lui; il fera, dis-je, approcher de lui celui qu’il aura choisi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Faites ceci, prenez-vous des encensoirs; que Coré, dis-je, et tous ceux qui sont assemblés avec lui, prennent des encensoirs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'Et demain mettez-y du feu, et mettez-y du parfum devant l’Eternel; et l’homme que l’Eternel aura choisi sera le saint. Enfants de Lévi; qu’il vous suffise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Moïse dit aussi à Coré: Ecoutez maintenant, enfants de Lévi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Est-ce trop peu de chose pour vous que le Dieu d’Israël vous ait séparés de l’assemblée d’Israël, en vous faisant approcher de lui pour être employés au service du pavillon de l’Eternel, et pour assister devant l’assemblée afin de la servir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Et qu’il t’ait fait approcher, toi et tous tes frères, les enfants de Lévi, avec toi, que vous recherchiez encore la Sacrificature?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'C’est pourquoi toi, et tous ceux qui sont assemblés avec toi, vous vous êtes assemblés contre l’Eternel; car qui est Aaron que vous murmuriez contre lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Et Moïse envoya appeler Dathan et Abiram, enfants d’Eliab, qui répondirent: Nous n’y monterons point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Est-ce peu de chose que tu nous aies fait monter hors d’un pays découlant de lait et de miel, pour nous faire mourir dans ce désert, que même tu veuilles dominer sur nous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Nous as-tu fait venir en un pays découlant de lait et de miel; et nous as- tu donné quelque héritage de champs ou de vignes? crèveras-tu les yeux de ces gens-ici? nous n’y monterons point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Alors Moïse fut fort irrité, et dit à l’Eternel: Ne regarde point à leur offrande; je n’ai point pris d’eux un seul âne, et je n’ai point fait de mal à aucun d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Puis Moïse dit à Coré: Toi et tous ceux qui sont assemblés avec toi, trouvez-vous demain devant l’Eternel, toi, dis-je, et ceux-ci; et Aaron aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Et prenez chacun vos encensoirs, et mettez-y du parfum; et que chacun présente devant l’Eternel son encensoir, qui seront deux cent cinquante encensoirs; et toi et Aaron aussi, chacun avec son encensoir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Ils prirent donc chacun son encensoir, et y mirent du feu, et ensuite du parfum, et ils se tinrent à l’entrée du Tabernacle d’assignation, et Moïse et Aaron s’y tinrent aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Et Coré fit assembler contr’eux toute l’assemblée à l’entrée du Tabernacle d’assignation; et la gloire de l’Eternel apparut à toute l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Puis l’Eternel parla à Moïse et à Aaron, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Séparez-vous du milieu de cette assemblée, et je les consumerai en un moment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Mais ils se prosternèrent le visage contre terre, et dirent: Ô Dieu Fort? Dieu des esprits de toute chair? un seul homme aura péché, et te mettras-tu en colère contre toute l’assemblée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Parle à l’assemblée, et lui dis: retirez-vous d’auprès des pavillons de Coré, de Dathan, et d’Abiram.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Moïse donc se leva et s’en alla vers Dathan et Abiram; et les Anciens d’Israël le suivirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Et il parla à l’assemblée, en disant: Retirez-vous, je vous prie, d’auprès des tentes de ces méchants hommes, et ne touchez à rien qui leur appartienne, de peur que vous ne soyez consumés pour tous leurs péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Ils se retirèrent donc d’auprès des pavillons de Coré, de Dathan et d’Abiram. Et Dathan et Abiram sortirent; et se tinrent debout à l’entrée de leurs tentes, avec leurs femmes, leurs enfants, et leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Et Moïse dit: Vous connaîtrez à ceci que l’Eternel m’a envoyé pour faire toutes ces choses-là, et que je n’ai rien fait de moi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Si ceux-là meurent comme tous les hommes meurent, et s’ils sont punis de la punition de tous les hommes, l’Eternel ne m’a point envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Mais si l’Eternel crée un cas tout nouveau, et que la terre ouvre sa bouche, et les engloutisse avec tout ce qui leur appartient, et qu’ils descendent tout vifs dans le gouffre; alors vous saurez que ces hommes-là ont irrité par mépris l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Et il arriva qu’aussitôt qu’il eut achevé de dire toutes ces paroles, la terre qui était sous eux, se fendit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'Et la terre ouvrit sa bouche, et les engloutit, avec leurs tentes, et tous les hommes qui étaient à Coré, et tout leur bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Ils descendirent donc tout vifs dans le gouffre, eux, et tous ceux qui étaient à eux; et la terre les couvrit, et ils périrent au milieu de l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Et tout Israël qui était autour d’eux, s’enfuit à leur cri; car ils disaient: Prenons garde que la terre ne nous engloutisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Et le feu sortit de part de l’Eternel, et consuma les deux cent cinquante hommes qui offraient le parfum.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Puis l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Dis à Eléazar fils d’Aaron, Sacrificateur, qu’il relève les encensoirs du milieu de l’incendie, et qu’on en épande le feu au loin, car ils sont sanctifiés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'Savoir les encensoirs de ceux qui ont péché sur leurs âmes, et qu’on en fasse des plaques larges pour couvrir l’autel; puisqu’ils les ont offerts devant l’Eternel ils seront sanctifiés, et ils seront pour signe aux enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Ainsi Eléazar Sacrificateur prit les encensoirs d’airain, que ces hommes qui furent brûlés avaient présentés, et on en fit des plaques pour couvrir l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'C’est un mémorial pour les enfants d’Israël, afin qu’aucun étranger qui n’est pas de la race d’Aaron, ne s’approche point pour faire le parfum en la présence de l’Eternel, et qu’il ne soit comme Coré, et comme ceux qui ont été assemblés avec lui; ainsi que l’Eternel en a parlé par le moyen de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Or dès le lendemain toute l’assemblée des enfants d’Israël murmura contre Moïse et contre Aaron, en disant: Vous avez fait mourir le peuple de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'Et il arriva comme l’assemblée s’amassait contre Moïse et contre Aaron, qu’ils regardèrent vers le Tabernacle d’assignation, et voici la nuée le couvrit, et la gloire de l’Eternel apparut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'Moïse donc et Aaron vinrent devant le Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Otez-vous du milieu de cette assemblée, et je les consumerai en un moment. Alors ils se prosternèrent le visage contre terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'Puis Moïse dit à Aaron: Prends l’encensoir, et mets-y du feu de dessus l’autel, mets-y aussi du parfum, et va promptement à l’assemblée, et fais propitiation pour eux; car une grande colère est partie de devant l’Eternel; la plaie est commencée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Et Aaron prit l’encensoir, comme Moïse lui avait dit, et il courut au milieu de l’assemblée, et voici la plaie avait déjà commencé sur le peuple. Alors il mit du parfum, et fit propitiation pour le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'Et comme il se tenait entre les morts elles vivants, la plaie fut arrêtée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Et il y en eut quatorze mille sept cents qui moururent de cette plaie, outre ceux qui étaient morts pour le fait de Coré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Et Aaron retourna vers Moïse à l’entrée du Tabernacle d’assignation, après que la plaie fut arrêtée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Après cela l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Parle aux enfants d’Israël, et prends une verge de chacun d’eux selon la maison de leur père, de tous ceux qui sont les principaux d’entr’eux selon la maison de leurs pères, douze verges, puis tu écriras le nom de chacun sur sa verge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Mais tu écriras le nom d’Aaron sur la verge de Lévi; car il y aura une verge pour chaque chef de la maison de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Et tu les poseras au Tabernacle d’assignation devant le Témoignage, où j’ai accoutumé de me trouver avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'Et il arrivera que la verge de l’homme que j’aurai choisi, fleurira; et je ferai cesser de devant moi les murmures des enfants d’Israël, par lesquels ils murmurent contre vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Quand Moïse eut parlé aux enfants d’Israël, tous les principaux d’entr’eux lui donnèrent selon la maison de leurs pères, chacun une verge. Ainsi il y eut douze verges. Or la verge d’Aaron fut mise parmi leurs verges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Et Moïse mit les verges devant l’Eternel au Tabernacle du Témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Et il arriva dès le lendemain, que Moïse étant entré au Tabernacle du Témoignage, voici, la verge d’Aaron avait fleuri pour la maison de Lévi, et elle avait jeté des fleurs, produit des boutons, et mûri des amandes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Alors Moïse tira hors de devant l’Eternel toutes les verges, et les porta à tous les enfants d’Israël, et les ayant vues, ils reprirent chacun leurs verges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Et l’Eternel dit à Moïse: Reporte la verge d’Aaron devant le Témoignage, pour être gardée comme un signe aux enfants de rébellion; et tu feras cesser leurs murmures de devant moi, et ainsi ils ne mourront plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Et Moïse fit comme l’Eternel lui avait commandé; il fit ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Et les enfants d’Israël parlèrent à Moïse, en disant: Voici, nous défaillons, nous sommes perdus, nous sommes tous perdus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Quiconque s’approche du pavillon de l’Eternel, mourra; serons-nous tous entièrement consumés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Alors l’Eternel dit à Aaron: Toi, et tes fils, et la maison de ton père avec toi, vous porterez l’iniquité du Sanctuaire; et toi et tes fils avec toi, vous porterez l’iniquité de votre Sacrificature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Fais aussi approcher de toi tes frères, la Tribu de Lévi, qui est la Tribu de ton père, afin qu’ils te soient adjoints et qu’ils te servent, mais toi et tes fils avec toi, vous servirez devant le Tabernacle du Témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Ils garderont ce que tu leur ordonneras de garder, et ce qu’il faut garder de tout le Tabernacle, mais ils n’approcheront point des vaisseaux du Sanctuaire, ni de l’autel, de peur qu’ils ne meurent, et que vous ne mouriez avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Ils te seront donc adjoints, et ils garderont tout ce qu’il faut garder au Tabernacle d’assignation, selon tout le service du Tabernacle; et nul étranger n’approchera de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Mais vous prendrez garde à ce qu’il faut faire dans le Sanctuaire, et à ce qu’il faut faire à l’autel, afin qu’il n’y ait plus d’indignation sur les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Car quant à moi, voici, j’ai pris vos frères les Lévites du milieu des enfants d’Israël, lesquels vous sont donnés en pur don pour l’Eternel, afin qu’ils soient employés au service du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Mais toi et tes fils avec toi, vous ferez la charge de votre Sacrificature en tout ce qui concerne l’autel et ce qui est au dedans du voile, et vous y ferez le service. J’établis votre Sacrificature en office de pur don; c’est pourquoi si quelque étranger en approche, on le fera mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'L’Eternel dit encore à Aaron: Voici, je t’ai donné la garde de mes offrandes élevées, d’entre toutes les choses sanctifiées des enfants d’Israël; je te les ai données, et à tes enfants, par ordonnance perpétuelle, à cause de l’onction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Ceci t’appartiendra d’entre les choses très-saintes qui ne sont point brûlées, savoir toutes leurs offrandes, soit de tous leurs gâteaux, soit de tous leurs sacrifices pour le péché, soit de tous leurs sacrifices pour le délit, qu’ils m’apporteront; ce sont des choses très-saintes pour toi et pour tes enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Tu les mangeras dans un lieu très-saint; tout mâle en mangera; ce te sera une chose sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Ceci aussi t’appartiendra, savoir les offrandes élevées qu’ils donneront de toutes les offrandes tournoyées des enfants d’Israël, je te les ai données et à tes fils et à tes filles avec toi, par ordonnance perpétuelle; quiconque sera net dans ta maison, en mangera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Je t’ai donné aussi leurs prémices qu’ils offriront à l’Eternel, savoir tout le meilleur de l’huile, et tout le meilleur du moût, et du froment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Les premiers fruits de toutes les choses que leur terre produira, et qu’ils apporteront à l’Eternel t’appartiendront; quiconque sera net dans ta maison, en mangera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Tout interdit en Israël t’appartiendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Tout ce qui ouvre la matrice de toute chair qu’ils offriront à l’Eternel, tant des hommes que des bêtes, t’appartiendra; mais on ne manquera pas de racheter le premier-né de l’homme; on rachètera aussi le premier-né d’une bête immonde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Et on rachètera les premiers-nés des hommes qui doivent être rachetés depuis l’âge d’un mois, selon l’estimation que tu en feras, qui sera de cinq sicles d’argent, selon le sicle du Sanctuaire, qui est de vingt oboles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Mais on ne rachètera point le premier-né de la vache, ni le premier-né de la brebis, ni le premier-né de la chèvre; car ce sont des choses saintes. Tu répandras leur sang sur l’autel, et tu feras fumer leur graisse; c’est un sacrifice fait par feu en bonne odeur à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Mais leur chair t’appartiendra, comme la poitrine de tournoiement, et comme l’épaule droite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Je t’ai donné, à toi et à tes fils, et à tes filles avec toi, par ordonnance perpétuelle, toutes les offrandes élevées des choses sanctifiées, que les enfants d’Israël offriront à l’Eternel, pour être une alliance ferme à toujours devant l’Eternel, pour toi et pour ta postérité avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Puis l’Eternel dit à Aaron: Tu n’auras point d’héritage en leur pays, tu n’auras point de portion parmi eux; je suis ta portion et ton héritage au milieu des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Et quant aux enfants de Lévi, voici, je leur ai donné pour héritage toutes les dîmes d’Israël, pour le service auquel ils sont employés, qui est le service du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Et les enfants d’Israël n’approcheront plus du Tabernacle d’assignation, afin qu’ils ne soient point coupables de péché, et qu’ils ne meurent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Mais les Lévites s’emploieront au service du Tabernacle d’assignation et ils porteront leur iniquité; cette ordonnance sera perpétuelle en vos âges, et ils ne posséderont point d’héritage parmi les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Car j’ai donné pour héritage aux Lévites les dîmes des enfants d’Israël, qu’ils offriront à l’Eternel en offrande élevée; c’est pourquoi j’ai dit d’eux, qu’ils n’auront point d’héritage parmi les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Puis l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Tu parleras aussi aux Lévites, et tu leur diras: Quand vous aurez reçu des enfants d’Israël les dîmes que je vous ai donné à prendre d’eux pour votre héritage, vous offrirez de ces dîmes l’offrande élevée de l’Eternel, savoir la dîme de la dîme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Et votre offrande élevée vous sera imputée comme le froment pris de l’aire, et comme l’abondance prise de la cuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Vous donc aussi vous offrirez l’offrande élevée de l’Eternel de toutes vos dîmes que vous aurez reçues des enfants d’Israël, et vous en donnerez de chacune l’offrande élevée de l’Eternel à Aaron Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Vous offrirez toute l’offrande élevée de l’Eternel, de toutes les choses qui vous sont données de tout ce qu’il y a de meilleur, pour être la sanctification de la dîme prise de la dîme même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Et tu leur diras: Quand vous aurez offert en offrande élevée le meilleur de la dîme, pris de la dîme même, il sera imputé aux Lévites comme le revenu de l’aire, et comme le revenu de la cuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Et vous la mangerez en tout lieu, vous et vos familles; car c’est votre salaire pour le service auquel vous êtes employés dans le Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Vous ne serez point coupables de péché au sujet de la dîme, quand vous en aurez offert en offrande élevée ce qu’il y aura de meilleur, et vous ne souillerez point les choses saintes des enfants d’Israël, et vous ne mourrez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'L’Eternel parla aussi à Moïse et à Aaron, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'C’est ici une ordonnance qui concerne la Loi que l’Eternel a commandée, en disant: Parle aux enfants d’Israël, et leur dis; qu’ils t’amènent une jeune vache rousse, entière, en laquelle il n’y ait point de tare, et qui n’ait point porté le joug.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Puis vous la donnerez à Éléazar Sacrificateur, qui la mènera hors du camp, et on l’égorgera en sa présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Ensuite Eléazar Sacrificateur, prendra de son sang avec son doigt, et fera sept fois aspersion du sang vers le devant du Tabernacle d’assignation;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Et on brûlera la jeune vache en sa présence; on brûlera sa peau, sa chair, et son sang et sa fiente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Et le Sacrificateur prendra du bois de cèdre, de l’hysope, et du cramoisi, et les jettera dans le feu où sera brûlée la jeune vache.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Puis le Sacrificateur lavera ses vêtements et sa chair avec de l’eau, et après cela il rentrera au camp; et le Sacrificateur sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Et celui qui l’aura brûlée lavera ses vêtements avec de l’eau, il lavera aussi dans l’eau sa chair, et il sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Et un homme net ramassera les cendres de la jeune vache, et les mettra hors du camp en un lieu net; et elles seront gardées pour l’assemblée des enfants d’Israël; afin d’en faire l’eau de séparation; c’est une purification pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Et celui qui aura ramassé les cendres de la jeune vache, lavera ses vêtements, et sera souillé jusqu’au soir; et ceci sera une ordonnance perpétuelle aux enfants d’Israël, et à l’étranger qui fait son séjour parmi eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Celui qui touchera un corps mort de quelque personne que ce soit, sera souillé pendant sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Et il se purifiera avec cette eau-là le troisième jour, et le septième jour il sera net; mais s’il ne se purifie pas le troisième jour, il ne sera point net au septième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Quiconque aura touché le corps mort de quelque personne morte, et qui ne se sera point purifié, il a souillé le pavillon de l’Eternel; c’est pourquoi une telle personne sera retranchée d’Israël; car il sera souillé, parce que l’eau de séparation n’aura pas été répandue sur lui; sa souillure demeure donc encore sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'C’est ici la Loi; quand un homme sera mort en quelque tente, quiconque entrera dans la tente, et tout ce qui sera dans la tente, sera souillé durant sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Aussi tout vaisseau découvert, sur lequel il n’y a point de couvercle attaché, sera souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Et quiconque touchera dans les champs un homme qui aura été tué par l’épée, ou quelque autre mort, ou quelque os d’homme, ou un sépulcre, sera souillé durant sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Et on prendra pour celui qui sera souillé, de la poudre de la jeune vache brûlée pour faire la purification, et on la mettra dans un vaisseau, avec de l’eau vive par-dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Puis un homme net prendra de l’hysope, et l’ayant trempée dans l’eau, il en fera aspersion sur la tente, et sur tous les vaisseaux, et sur toutes les personnes qui auront été là, et sur celui qui aura touché l’os ou l’homme tué, ou le mort, ou le sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Un homme donc qui sera net, en fera aspersion le troisième jour et le septième sur celui qui sera souillé, et le purifiera le septième jour; puis il lavera ses vêtements, et se lavera avec de l’eau, et il sera net au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Mais l’homme qui sera souillé, et qui ne se purifiera point, cet homme sera retranché du milieu de l’assemblée, parce qu’il aura souillé le Sanctuaire de l’Eternel; et l’eau de séparation n’ayant pas été répandue sur lui, il est souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Et ceci leur sera une ordonnance perpétuelle; et celui qui aura fait aspersion de l’eau de séparation, lavera ses vêtements; et quiconque aura touché l’eau de séparation, sera souillé jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Et tout ce que l’homme souillé touchera, sera souillé; et la personne qui le touchera, sera souillée jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Or les enfants d’Israël, savoir toute l’assemblée, arrivèrent au désert de Tsin au premier mois; et le peuple demeura à Kadès, et Marie mourut là, et y fut ensevelie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Et n’y ayant point d’eau pour l’assemblée, ils s’attroupèrent contre Moïse, et contre Aaron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Et le peuple disputa contre Moïse, et ils lui dirent: Plût à Dieu que nous fussions morts quand nos frères moururent devant l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Et pourquoi avez-vous fait venir l’assemblée de l’Eternel dans ce désert, pour y mourir, nous et nos bêtes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Et pourquoi nous avez-vous fait monter d’Egypte, pour nous amener en ce méchant lieu, qui n’est point un lieu pour semer, ni un lieu pour des figuiers, ni pour des vignes, ni pour des grenadiers; et où même il n’y a point d’eau pour boire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Alors Moïse et Aaron se retirèrent de devant l’assemblée à l’entrée du Tabernacle d’assignation, et tombèrent sur leurs faces, et la gloire de l’Eternel apparut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Puis l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Prends la verge, et convoque l’assemblée, toi et Aaron ton frère, et parlez en leur présence au rocher, et il donnera son eau; ainsi tu leur feras sortir de l’eau du rocher, et tu donneras à boire à l’assemblée et à leurs bêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Moïse donc prit la verge de devant l’Eternel, comme il lui avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Et Moïse et Aaron convoquèrent l’assemblée devant le rocher, et il leur dit: Vous rebelles, écoutez maintenant, vous ferons-nous sortir de l’eau de ce rocher?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Puis Moïse leva sa main, et frappa de sa verge le rocher par deux fois; et il en sortit des eaux en abondance, et l’assemblée but, et leurs bêtes aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Et l’Eternel dit à Moïse et à Aaron: Parce que vous n’avez point cru en moi,pour me sanctifier en la présence des enfants d’Israël, aussi vous n’introduirez point cette assemblée au pays que je leur ai donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Ce sont là les eaux de dispute, pour lesquelles les enfants d’Israël disputèrent contre l’Eternel; et il se sanctifia en eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Puis Moïse envoya des ambassadeurs de Kadès au roi d’Edom, pour lui dire: Ainsi a dit ton frère Israël: Tu sais tout le travail que nous avons eu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Comment nos pères descendirent en Egypte, où nous avons demeuré longtemps; et comment les Egyptiens nous ont maltraités, nous et nos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Et nous avons crié à l’Eternel, qui ayant entendu nos cris, a envoyé l’Ange, et nous a retirés d’Egypte. Or voici, nous sommes à Kadès, ville qui est au bout de tes frontières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Je te prie que nous passions par ton pays; nous ne passerons point par les champs, ni par les vignes, et nous ne boirons point de l’eau d’aucun puits; nous marcherons par le chemin royal; nous ne nous détournerons ni à droite ni à gauche, jusqu’à ce que nous ayons passé tes limites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Et Edom lui dit: Tu ne passeras point par mon pays, de peur que je ne sorte en armes à ta rencontre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Les enfants d’Israël lui répondirent: Nous monterons par le grand chemin, et si nous buvons de tes eaux, moi et mes bêtes, je t’en payerai le prix; seulement que j’y prenne mon passage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Mais Edom lui dit: Tu n’y passeras point; et sur cela Edom sortit à sa rencontre avec une grande multitude, et à main armée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Ainsi Edom ne voulut point permettre à Israël de passer par ses frontières; c’est pourquoi Israël se détourna de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Et les enfants d’Israël, savoir toute l’assemblée, étant partis de Kadès vinrent en la montagne de Hor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Et l’Eternel parla à Moïse et à Aaron en la montagne de Hor, près des frontières du pays d’Edom, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Aaron sera recueilli vers ses peuples, car il n’entrera point au pays que j’ai donné aux enfants d’Israël, parce que vous avez été rebelles à mon commandement aux eaux de la dispute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Prends donc Aaron et Eléazar son fils, et fais les monter sur la montagne de Hor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'Puis fais dépouiller Aaron de ses vêtements, et fais en revêtir Eléazar son fils; et Aaron sera recueilli, et mourra là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Moïse donc fit ainsi que l’Eternel l’avait commandé; et ils montèrent sur la montagne de Hor, toute l’assemblée le voyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Et Moïse fit dépouiller Aaron de ses vêtements et en fit revêtir Eléazar son fils; puis Aaron mourut là au sommet de la montagne, et Moïse et Eléazar descendirent de la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Et toute l’assemblée, savoir toute la maison d’Israël, voyant qu’Aaron était mort, ils le pleurèrent trente jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Quand le Cananéen Roi de Harad, qui habitait au Midi, eut appris qu’Israël venait par le chemin des espions, il combattit contre Israël, et en emmena des prisonniers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Alors Israël fit un voeu à l’Eternel, en disant: Si tu livres ce peuple entre mes mains, je mettrai ses villes à l’interdit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Et l’Eternel exauça la voix d’Israël, et livra entre ses mains les Cananéens, lesquels il détruisit à la façon de l’interdit, avec leurs villes; et on nomma ce lieu-là Horma.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Puis ils partirent de la montagne de Hor, tirant vers la mer Rouge, pour environner le pays d’Edom, et le coeur manqua au peuple par le chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Le peuple donc parla contre Dieu, et contre Moïse, en disant: Pourquoi nous as-tu fait monter hors de l’Egypte, pour mourir dans ce désert? car il n y a point de pain, ni d’eau, et notre âme est ennuyée de ce pain si léger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Et l’Eternel envoya sur le peuple des serpents brûlants qui mordaient le peuple; tellement qu’il en mourut un grand nombre de ceux d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Alors le peuple vint vers Moïse, et dit: Nous avons péché, car nous avons parlé contre l’Eternel, et contre toi; invoque l’Eternel, et qu’il retire de dessus nous les serpents. Et Moïse pria pour le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Et l’Eternel dit à Moïse: Fais-toi un serpent brûlant, et mets-le sur une perche; et il arrivera que quiconque sera mordu, et le regardera, sera guéri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Moïse donc fit un serpent d’airain, et le mit sur une perche; et il arrivait que quand quelque serpent avait mordu un homme, il regardait le serpent d’airain, et il était guéri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Depuis, les enfants d’Israël partirent, et campèrent en Oboth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Et étant partis d’Oboth, ils campèrent en Hijé-habarim, au désert qui est vis-à-vis de Moab, vers le soleil levant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Puis étant partis de là, ils campèrent vers le torrent de Zéred.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Et étant partis de là, ils campèrent au deçà d’Arnon, qui est au désert, sortant des confins de l’Amorrhéen; car Arnon est la frontière de Moab, entre les Moabites et les Amorrhéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'C’est pourquoi il est dit au Livre des batailles de l’Eternel: Vaheb en Suphah, et les torrents en Arnon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'Et le cours des torrents qui tend vers le lieu où Har est située, et qui se rend aux frontières de Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Et de là ils vinrent en Béer; c’est le puits touchant lequel l’Eternel dit à Moïse: Assemble le peuple, et je leur donnerai de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Alors Israël chanta ce Cantique: Monte, puits; chantez de lui en vous répondant les uns aux autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'C’est le puits que les Seigneurs ont creusé, que les principaux du peuple avec le Législateur ont creusé de leurs bâtons. Et du désert ils vinrent en Mattana.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'Et de Mattana en Nahaliel; et de Nahaliel en Bamoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'Et de Bamoth en la vallée qui est au territoire de Moab, au sommet de Pisga, et qui regarde vers Jésimon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Puis Israël envoya des ambassadeurs à Sihon, Roi des Amorrhéens, pour lui dire:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Que je passe par ton pays; nous ne nous détournerons point dans les champs, ni dans les vignes, et nous ne boirons point des eaux de tes puits; mais nous marcherons par le chemin royal, jusqu’à ce que nous ayons passé tes limites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Mais Sihon ne permit point qu’Israël passât par ses terres; et il assembla tout son peuple, et sortit contre Israël au désert, et vint jusqu’en Jahats, et il combattit contre Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Mais Israël le fit passer au fil de l’épée, et conquit son pays, depuis Arnon jusqu’à Jabbok, et jusqu’aux enfants de Hammon; car la frontière des enfants de Hammon était forte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Et Israël prit toutes les villes qui étaient là, et habita dans toutes les villes des Amorrhéens, à Hesbon, et dans toutes les villes de son ressort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Or Hesbon était la ville de Sihon, Roi des Amorrhéens, qui avait le premier fait la guerre au Roi de Moab, et avait pris sur lui tout son pays jusqu’à Arnon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'C’est pourquoi on dit en proverbe: Venez à Hesbon. Que la ville de Sihon soit bâtie, et réparée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Car le feu est sorti de Hesbon, et la flamme de la cité de Sihon; elle a consumé Har des Moabites, et les Seigneurs de Bamoth à Arnon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Malheur à toi, Moab; peuple de Kémos, tu es perdu; il a livré ses fils qui se sauvaient et ses filles en captivité à Sihon, Roi des Amorrhéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Nous les avons défaits à coups de flèches. Hesbon est périe jusqu’à Dibon; nous les avons mis en déroute jusqu’en Nophah, qui atteint jusqu’à Médéba.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Israël donc habita en la terre des Amorrhéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Puis Moïse ayant envoyé des gens pour reconnaître Jahzer, ils prirent les villes de son ressort, et en dépossédèrent les Amorrhéens qui y étaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Ensuite ils se tournèrent, et montèrent par le chemin de Basan; et Hog, Roi de Basan, sortit lui et tout son peuple en bataille pour les rencontrer en Edréhi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Et l’Eternel dit à Moïse: Ne le crains point; car je l’ai livré entre tes mains, lui, et tout son peuple, et son pays; et tu lui feras comme tu as fait à Sihon, Roi des Amorrhéens, qui habitait à Hesbon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Ils le battirent donc, lui et ses enfants, et tout son peuple, tellement qu’il n’en demeura pas un seul de reste; et ils possédèrent son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Puis les enfants d’Israël partirent, et campèrent dans les campagnes de Moab, au deçà du Jourdain de Jéricho.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Or Balac fils de Tsippor, vit toutes les choses qu’Israël avait faites à l’Amorrhéen;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Et Moab eut une grande frayeur du peuple, parce qu’il était en grand nombre; et il fut extrêmement agité à cause des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Et Moab dit aux Anciens de Madian: Maintenant cette multitude broutera tout ce qui est autour de nous, comme le boeuf broute l’herbe du champ. Or en ce temps-là Balac, fils de Tsippor, était Roi de Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Lequel envoya des messagers à Balaam, fils de Béhor, en Péthor, située sur le fleuve, dans le pays des enfants de son peuple, pour l’appeler, en lui disant: Voici, un peuple est sorti d’Egypte; voici, il couvre le dessus de la terre, et il se tient campé tout proche de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Viens donc maintenant, je te prie, maudis-moi ce peuple, car il est plus puissant que moi; peut-être que je serai le plus fort, et que nous le battrons, et que je le chasserai du pays; car je sais que celui que tu béniras, sera béni; et que celui que tu maudiras sera maudit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Les Anciens donc de Moab s’en allèrent avec les Anciens de Madian, ayant en leurs mains de quoi payer le devin, et ils vinrent à Balaam, et lui rapportèrent les paroles de Balac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Et il leur répondit: Demeurez ici cette nuit, et je vous rendrai réponse selon que l’Eternel m’aura parlé. Et les Seigneurs des Moabites demeurèrent avec Balaam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Et Dieu vint à Balaam, et dit: Qui sont ces hommes-là que tu as chez toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Et Balaam répondit à Dieu: Balac, fils de Tsippor, Roi de Moab, a envoyé vers moi, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Voici un peuple qui est sorti d’Egypte, et qui a couvert le dessus de la terre; viens donc maintenant, maudis-le moi; peut-être que je le pourrai combattre, et que je le chasserai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Et Dieu dit à Balaam: Tu n’iras point avec eux et tu ne maudiras point ce peuple; car il est béni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Et Balaam s’étant levé dès le matin, dit aux Seigneurs qui avaient été envoyés par Balac: Retournez dans votre pays; car l’Eternel a refusé de me laisser aller avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Ainsi les Seigneurs des Moabites se levèrent, et revinrent à Balac, et dirent: Balaam a refusé de venir avec nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Et Balac envoya encore des Seigneurs en plus grand nombre, et plus honorables que les premiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Qui étant venus à Balaam, lui dirent: Ainsi a dit Balac, fils de Tsippor: Je te prie, que rien ne t’empêche de venir vers moi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Car certainement je te récompenserai beaucoup, et je ferai tout ce que tu me diras; je te prie donc viens, maudis moi ce peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Et Balaam répondit et dit aux Serviteurs de Balac: Quand Balac me donnerait sa maison pleine d’or et d’argent, je ne pourrais point transgresser le commandement de l’Eternel mon Dieu, pour faire aucune chose, petite ni grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Toutefois je vous prie demeurez maintenant ici encore cette nuit, et je saurai ce que l’Eternel aura de plus à me dire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Et Dieu vint la nuit à Balaam, et lui dit: Puisque ces hommes sont venus t’appeler, lève-toi, et t’en va avec eux; mais quoi qu’il en soit tu feras ce que je te dirai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Ainsi Balaam se leva le matin, et sella son ânesse, et s’en alla avec les Seigneurs de Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Mais la colère de Dieu s’enflamma parce qu’il s’en allait, et l’Ange de l’Eternel se tint dans le chemin pour s’opposer à lui; or il était monté sur son ânesse, et il avait avec lui deux de ses Serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Et l’ânesse vit l’Ange de l’Eternel qui se tenait dans le chemin, et qui avait son épée nue en sa main, et elle se détourna du chemin, et s’en allait à travers champs; et Balaam frappa l’ânesse pour la faire retourner au chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Mais l’Ange de l’Eternel s’arrêta dans un sentier de vignes, qui avait une cloison deçà, et une cloison delà.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Et l’ânesse ayant vu l’Ange de l’Eternel, se serra contre la muraille, et elle serrait contre la muraille le pied de Balaam; c’est pourquoi il continua à la frapper.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Et l’Ange passa plus avant, et s’arrêta en un lieu étroit, où il n’y avait nul chemin pour tourner à droite ni à gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Et l’ânesse voyant l’Ange de l’Eternel, se coucha sous Balaam; et Balaam s’en mit en grande colère, et frappa l’ânesse avec son bâton.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Alors l’Eternel fit parler l’ânesse, qui dit à Balaam: Que t’ai-je fait, que tu m’aies déjà battue trois fois?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Et Balaam répondit à l’ânesse: Parce que tu t’es moquée de moi; plût à Dieu que j’eusse une épée en ma main, car je te tuerais sur-le-champ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Et l’ânesse dit à Balaam: Ne suis-je pas ton ânesse, sur laquelle tu as monté depuis que je suis à toi jusqu’à aujourd’hui? Ai-je accoutumé de te faire ainsi? Et il répondit: Non.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Alors l’Eternel ouvrit les yeux de Balaam, et il vit l’Ange de l’Eternel qui se tenait dans le chemin, et qui avait en sa main son épée nue; et il s’inclina et se prosterna sur son visage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Et l’Ange de l’Eternel lui dit: Pourquoi as-tu frappé ton ânesse déjà par trois fois? Voici je suis sorti pour m’opposer à toi; parce que ta voie est devant moi une voie détournée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Mais l’ânesse m’a vu et s’est détournée de devant moi déjà par trois fois; autrement si elle ne se fût détournée de devant moi, je t’eusse même déjà tué, et je l’eusse laissée en vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Alors Balaam dit à l’Ange de l’Eternel: J’ai péché, car je ne savais point que tu te tinsses dans le chemin contre moi; et maintenant si cela te déplaît, je m’en retournerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Et l’Ange de l’Eternel dit à Balaam: Va avec ces hommes; mais tu diras seulement ce que je t’aurai dit. Balaam donc s’en alla avec les Seigneurs envoyés par Balac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Quand Balac apprit que Balaam venait, il sortit pour aller au devant de lui, en la cité de Moab, sur la frontière d’Arnon, au bout de la frontière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Et Balac dit à Balaam: N’ai-je pas auparavant envoyé vers toi pour t’appeler? pourquoi n’es-tu pas venu vers moi? est-ce que je ne pourrais pas te récompenser?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Et Balaam répondit à Balac: Voici, je suis venu vers toi; mais pourrais-je maintenant dire quelque chose de moi-même? je ne dirai que ce que Dieu m’aura mis dans la bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Et Balaam s’en alla avec Balac, et ils vinrent en la cité de Hutsoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Et Balac sacrifia des boeufs et des brebis, et il en envoya à Balaam, et aux Seigneurs qui étaient venus avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Et quand le matin fut venu, il prit Balaam, et le fit monter aux hauts lieux de Bahal, et de là il vit une des extrémités du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Et Balaam dit à Balac: Bâtis-moi ici sept autels, et prépare-moi ici sept veaux et sept béliers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Et Balac fit comme Balaam avait dit; et Balac offrit avec Balaam un veau et un bélier sur chaque autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Puis Balaam dit à Balac: Tiens-toi auprès de ton holocauste, et je m’en irai; peut-être que l’Eternel viendra à ma rencontre, et je te rapporterai tout ce qu’il m’aura fait voir; ainsi il se retira à l’écart.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Et Dieu vint au-devant de Balaam, et Balaam lui dit: J’ai dressé sept autels, et j’ai sacrifié un veau et un bélier sur chaque autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Et l’Eternel mit la parole en la bouche de Balaam, et lui dit: Retourne à Balac, et lui parle ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Il s’en retourna donc vers lui; et voici, il se tenait auprès de son holocauste, tant lui que tous les Seigneurs de Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Alors Balaam proféra son discours sentencieux, et dit: Balac, Roi de Moab, m’a fait venir d’Aram, des montagnes d’Orient, en me disant: Viens, maudis- moi Jacob; viens, dis-je, déteste Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Mais comment le maudirai-je? le Dieu Fort ne l’a point maudit; et comment le détesterai-je? l’Eternel ne l’a point détesté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Car je le regarderai du sommet des rochers, et je le contemplerai des coteaux. Voilà, ce peuple habitera à part, et il ne sera point mis entre les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Qui est-ce qui comptera la poudre de Jacob, et le nombre de la quatrième partie d’Israël? Que je meure de la mort des justes, et que ma fin soit semblable à la leur!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Alors Balac dit à Balaam: Que m’as-tu fait? Je t’avais pris pour maudire mes ennemis, et voici, tu les as bénis très-expressément.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Et il répondit, et dit: Ne prendrais-je pas garde de dire ce que l’Eternel aura mis en ma bouche?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Alors Balac lui dit: Viens, je te prie, avec moi en un autre lieu d’où tu le puisses voir, car tu en voyais seulement une extrémité, et tu ne le voyais pas tout entier; maudis-le moi de là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Puis l’ayant conduit au territoire de Tsophim vers le sommet de Pisga, il bâtit sept autels, et offrit un veau et un bélier sur chaque autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Alors Balaam dit à Balac: Tiens-toi ici auprès de ton holocauste, et je m’en irai à la rencontre de Dieu, comme j’ai déjà fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'L’Eternel donc vint au-devant de Balaam, et mit la parole en sa bouche, et lui dit: Retourne à Balac, et lui parle ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Et il vint à Balac, et voici, il se tenait auprès de son holocauste, et les Seigneurs de Moab avec lui. Et Balac lui dit: Qu’est-ce que l’Eternel a prononcé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Alors il proféra à haute voix son discours sentencieux, et dit: Lève-toi, Balac, et écoute; fils de Tsippor, prête-moi l’oreille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Le Dieu Fort n’est point homme pour mentir, ni fils d’homme pour se repentir; il a dit, et ne le fera-t-il point? il a parlé, et ne le ratifiera- t-il point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Voici, j’ai reçu la parole pour bénir; puisqu’il a béni, je ne le révoquerai point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Il n’a point aperçu d’iniquité en Jacob, ni vu de perversité en Israël; l’Eternel son Dieu est avec lui, et il y a en lui un chant de triomphe royal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Le Dieu Fort qui les a tirés d’Egypte, lui est comme les forces de la Licorne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Car il n’y a point d’enchantements contre Jacob, ni de divinations contre Israël. En pareille saison, il sera dit de Jacob et d’Israël: Qu’est-ce que le Dieu Fort a fait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Voici, ce peuple se lèvera comme un vieux lion, et se haussera comme un lion qui est dans sa force; il ne se couchera point qu’il n’ait mangé la proie, et bu le sang des blessés à mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Alors Balac dit à Balaam: Et bien, ne le maudis point, mais au moins ne le bénis pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Et Balaam répondit à Balac, et dit: N’est-ce pas ici ce que je t’ai dit, que tout ce que l’Eternel dirait, je le ferais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Balac dit encore à Balaam: Viens maintenant, je te conduirai en un autre lieu; peut-être que Dieu trouvera bon que tu me le maudisses de là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Balac conduisit donc Balaam au sommet de Péhor, qui regarde du côté de Jésimon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Et Balaam lui dit: Bâtis-moi ici sept autels, et apprête-moi ici sept veaux et sept béliers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Balac fit donc comme Balaam lui avait dit; puis il offrit un veau et un bélier sur chaque autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Or Balaam voyant que l’Eternel voulait bénir Israël, n’alla plus comme les autres fois, à la rencontre des enchantements, mais il tourna son visage vers le désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Et élevant les yeux, il vit Israël qui se tenait rangé selon ses Tribus; et l’Esprit de Dieu fut sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Et il proféra à haute voix son discours sentencieux, et dit: Balaam, fils de Béhor, dit, et l’homme qui a l’oeil ouvert, dit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Celui qui entend les paroles du Dieu Fort; qui voit la vision du Tout- Puissant; qui tombe à terre, et qui a les yeux ouverts, dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Que tes Tabernacles sont beaux, ô Jacob! et tes pavillons, ô Israël!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Ils sont étendus comme des torrents, comme des jardins près d’un fleuve, comme des arbres d’aloé que l’Eternel a plantés, comme des cèdres auprès de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'L’eau distillera de ses seaux, et sa semence sera parmi de grandes eaux, et son Roi sera élevé par-dessus Agag, et son royaume sera haut élevé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Le Dieu Fort qui l’a tiré d’Egypte, lui est comme les forces de la Licorne; il consumera les nations qui lui sont ennemies, il brisera leurs os, et les percera de ses flèches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Il s’est courbé, il s’est couché comme un lion qui est en sa force, et comme un vieux lion; qui l’éveillera? Quiconque te bénit, sera béni, et quiconque te maudit, sera maudit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Alors Balac se mit fort en colère contre Balaam, et frappa des mains; et Balac dit à Balaam, je t’avais appelé pour maudire mes ennemis, et voici, tu les as bénis très-expressément déjà par trois fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Or maintenant fuis t’en en ton pays. J’avais dit que je te donnerais une grande récompense; mais voici, l’Eternel t’a empêché d’être récompensé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Et Balaam répondit à Balac: N’avais-je pas dit à tes ambassadeurs que tu avais envoyés vers moi:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Si Balac me donnait sa maison pleine d’argent et d’or, je ne pourrais transgresser le commandement de l’Eternel, pour faire de moi-même du bien ou du mal; mais ce que l’Eternel dira, je le dirai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Maintenant donc voici, je m’en vais vers mon peuple; viens, je te donnerai un conseil, et je te dirai ce que ce peuple fera à ton peuple, au dernier temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Alors il proféra à haute voix son discours sentencieux, et dit: Balaam, fils de Béhor, dit, et l’homme qui a l’oeil ouvert, dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Celui qui entend les paroles du Dieu Fort, et qui a la science du Souverain, et qui voit la vision du Tout-Puissant, qui tombe à terre, et qui a les yeux ouverts, dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Je le vois, mais non pas maintenant; je le regarde, mais non pas de près. Une étoile est procédée de Jacob, et un sceptre s’est élevé d’Israël: il transpercera les coins de Moab, et détruira tous les enfants de Seth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Edom sera possédé, et Séhir sera possédé par ses ennemis, et Israël se portera vaillamment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Et il y en aura un de Jacob qui dominera, et qui fera périr le résidu de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Il vit aussi Hamalec, et proféra à haute voix son discours sentencieux, et dit: Hamalec est un commencement de nations, mais à la fin il périra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Il vit aussi le Kénien, et il proféra à haute voix son discours sentencieux, et dit: Ta demeure est dans un lieu rude, et tu as mis ton nid dans le rocher;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Toutefois Kaïn sera ravagé, jusqu’à ce qu’Assur te mène en captivité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Il continua encore à proférer à haute voix son discours sentencieux, et il dit: Malheur à celui qui vivra quand le Dieu Fort fera ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Et les navires viendront du quartier de Kittim, et affligeront Assur et Héber, et lui aussi sera détruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Puis Balaam se leva, et s’en alla pour retourner en son pays; et Balac aussi s’en alla son chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Alors Israël demeurait en Sittim, et le peuple commença à paillarder avec les filles de Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Car elles convièrent le peuple aux sacrifices de leurs dieux, et le peuple y mangea, et se prosterna devant leurs dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Et Israël s’accoupla à Bahal-Péhor; c’est pourquoi la colère de l’Eternel s’enflamma contre Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Et l’Eternel dit à Moïse: Prends tous les chefs du peuple, et les fais pendre devant l’Eternel au soleil, et l’ardeur de la colère de l’Eternel se détournera d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Moïse donc dit aux juges d’Israël: Que chacun de vous fasse mourir les hommes qui sont à sa charge, lesquels se sont joints à Bahal-Péhor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Et voici, un homme des enfants d’Israël vint, et amena à ses frères une Madianite, devant Moïse et devant toute l’assemblée des enfants d’Israël, comme ils pleuraient à la porte du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Ce que Phinées, fils d’Eléazar, fils d’Aaron le Sacrificateur ayant vu, il se leva du milieu de l’assemblée, et prit une javeline en sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'Et il entra vers l’homme Israélite dans la tente, et les transperça tous deux par le ventre, l’homme Israélite et la femme; et la plaie fut arrêtée de dessus les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Or il y en eut vingt-quatre mille qui moururent de cette plaie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Phinées, fils d’Eléazar, fils d’Aaron, le Sacrificateur, a détourné ma colère de dessus les enfants d’Israël, parce qu’il a été animé de mon zèle au milieu d’eux, et je n’ai point consumé les enfants d’Israël par mon ardeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'C’est pourquoi, dis-lui: Voici, je lui donne mon alliance de paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'Et l’alliance de Sacrificature perpétuelle sera tant pour lui, que pour sa postérité après lui, parce qu’il a été animé de zèle pour son Dieu, et qu’il a fait propitiation pour les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Et le nom de l’homme Israélite tué, lequel fut tué avec la Madianite, était Zimri, fils de Salu, chef d’une maison de père des Siméonites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Et le nom de la femme Madianite qui fut tuée était Cozbi, fille de Tsur, chef du peuple, et de maison de père en Madian.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Serrez de près les Madianites, et les frappez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Car ils vous ont serrés les premiers par leurs ruses, par lesquelles ils vous ont surpris dans le fait de Péhor, et dans le fait de Cozbi, fille d’un des principaux d’entre les Madianites, leur soeur, qui a été tuée le jour de la plaie arrivée pour le fait de Péhor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Or il arriva après cette plaie-là, que l’Eternel parla à Moïse, et à Eléazar, fils d’Aaron, le Sacrificateur, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Faites le dénombrement de toute l’assemblée des enfants d’Israël, depuis l’âge de vingt ans, et au dessus, selon les maisons de leurs pères, savoir de tous ceux d’Israël qui peuvent aller à la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Moïse donc et Eléazar le Sacrificateur leur parlèrent dans les campagnes de Moab, auprès du Jourdain de Jéricho, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Qu’on fasse le dénombrement depuis l’âge de vingt ans, et au dessus, comme l’Eternel l’avait commandé à Moïse et aux enfants d’Israël, quand ils furent sortis du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben fut le premier-né d’Israël; et les enfants de Ruben furent Hénoc; de lui sortit la famille des Hénokites; de Pallu, la famille des Palluites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'De Hetsron, la famille des Hetsronites; de Carmi, la famille des Carmites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Ce sont là les familles des Rubénites, et ceux qui furent dénombrés étaient quarante-trois mille sept cent trente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Et les enfants de Pallu, Eliab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Et les enfants d’Eliab, Némuel, Dathan et Abiram. Ce Dathan et cet Abiram, qui étaient de ceux qu’on appelait pour tenir l’assemblée, se mutinèrent contre Moïse et contre Aaron en l’assemblée de Coré, lorsqu’on se mutina contre l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'Et lorsque la terre ouvrit sa bouche et les engloutit. Mais Coré fut enveloppé en la mort de ceux qui étaient assemblés avec lui, quand le feu consuma les deux cent cinquante hommes; et ils furent pour signe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Mais les enfants de Coré ne moururent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Les enfants de Siméon selon leurs familles. De Némuel, la famille des Némuélites; de Jamin, la famille des Jaminites; de Jakin, la famille des Jakinites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'De Zérah, la famille des Zarhites; de Saül, la famille des Saülites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Ce sont là les familles des Siméonites; qui furent vingt-deux mille deux cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Les enfants de Gad selon leurs familles. De Tséphon, la famille des Tséphonites; de Haggi, la famille des Haggites; de Suni, la famille des Sunites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'D’Ozni, la famille des Oznites; deHéri, la famille des Hérites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'D’Arod, la famille des Arodites; d’Aréel, la famille des Aréélites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Ce sont là les familles des enfants de Gad, selon leur dénombrement, qui fut de quarante mille cinq cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Les enfants de Juda, Her, et Onan; mais Her et Onan moururent au pays de Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Ainsi les enfants de Juda distingués par leurs familles, furent, de Séla, la famille des Sélanites; de Pharès, la famille des Pharésites; de Zara, la famille des Zarhites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Et les enfants de Pharès furent, de Hetsron, la famille des Hetsronites; et de Hamul, la famille des Hamulites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Ce sont là les familles de Juda, selon leur dénombrement, qui fut de soixante et seize mille cinq cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Les enfants d’Issacar selon leurs familles. De Tolah, la famille des Tolahites; de Puva, la famille des Puvites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'De Jasub, la famille des Jasubites; de Simron, la famille des Simronites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Ce sont là les familles d’Issacar, selon leur dénombrement, qui fut de soixante-quatre mille trois cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Les enfants de Zabulon, selon leurs familles. De Séred, la famille des Sérédites; d’Elon, la famille des Elonites; de Jahléel, la famille des Jahléélites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Ce sont là les familles des Zabulonites, selon leur dénombrement, qui fut de soixante mille cinq cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Les enfants de Joseph, selon leurs familles, furent Manassé et Ephraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Les enfants de Manassé. De Makir, la famille des Makirites; et Makir engendra Galaad; de Galaad, la famille des Galaadites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Ce sont ici les enfants de Galaad; de Ihézer, la famille des Ihézérites; de Hélek, la famille des Hélékites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'D’Asriel, la famille des Asriélites; de Sékem, la famille des Sékémites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'De Semidah, la famille des Semidahites; de Hépher, la famille des Héphrites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Or Tsélophcad, fils de Hépher, n’eut point de fils, mais des filles: et les noms des filles de Tsélophcad sont Mahla, Noha, Hogla, Milca, et Tirtsa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Ce sont là les familles de Manassé, et leur dénombrement fut de cinquante- deux mille sept cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Ce sont ici les enfants d’Ephraïm, selon leurs familles. De Suthélah, la famille des Suthélahites; de Béker, la famille des Bakrites; de Tahan, la famille des Tahanites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Et ce sont ici les enfants de Suthélah; de Héran, la famille des Héranites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Ce sont là les familles des enfants d’Ephraïm, selon leur dénombrement, qui furent trente-deux mille cinq cents. Ce sont là les enfants de Joseph, selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Les enfants de Benjamin, selon leurs familles. De Bélah, la famille des Balhites; d’Asbel, la famille des Asbélites; d’Ahiram, la famille des Ahiramites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'De Séphupham, la famille des Séphuphamites; de Hupham, la famille des Huphamites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Et les enfants de Bélah furent Ard et Nahaman; d’Ard, la famille des Ardites; et de Nahaman, la famille des Nahamanites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Ce sont là les enfants de Benjamin, selon leurs familles; et leur dénombrement fut de quarante-cinq mille six cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Ce sont ici les enfants de Dan, selon leurs familles. De Suham, la famille des Suhamites; ce sont là les familles de Dan, selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Toutes les familles des Suhamites, selon leur dénombrement, furent soixante- quatre mille, et quatre cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Les enfants d’Aser, selon leurs familles. De Jimna, la famille des Jimnaïtes; de Jisui, la famille des Jisuites; de Bériah, la famille des Bériahites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Des enfants de Bériah, de Héber, la famille des Hébrites; de Malkiel, la famille des Malkiélites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Et le nom de la fille d’Aser, fut Sérah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Ce sont là les familles des enfants d’Aser, selon leur dénombrement, qui furent cinquante-trois mille quatre cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Les enfants de Nephthali, selon leurs familles. De Jahtséel, la famille des Jahtséélites; de Guni, la famille des Gunites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'De Jetser la famille des Jitsrites; de Sillem, la famille des Sillémites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Ce sont là les familles de Nephthali, selon leurs familles, et leur dénombrement fut de quarante-cinq mille quatre cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Ce sont là les dénombrés des enfants d’Israël, qui furent six cent et un mille sept cent trente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Le pays sera partagé à ceux-ci par héritage, selon le nombre des noms.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'A ceux qui sont en plus grand nombre tu donneras plus d’héritage, et à ceux qui sont en plus petit nombre tu donneras moins d’héritage; on donnera à chacun son héritage selon le nombre de ses dénombrés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Toutefois que le pays soit divisé par sort, et qu’ils prennent leur héritage selon les noms des Tribus de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'L’héritage de chacun sera selon que le sort le montrera, et on aura égard au plus grand et au plus petit nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Et ce sont ici les dénombrés de Lévi selon leurs familles; de Guerson, la famille des Guersonites; de Kéhath, la famille des Kéhathites; de Mérari, la famille des Mérarites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Ce sont donc ici les familles de Lévi; la famille des Libnites, la famille des Hébronites, la famille des Mahlites, la famille des Musites, la famille des Corhites. Or Kéhath engendra Hamram.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Et le nom de la femme de Hamram, fut Jokébed, fille de Lévi, qui naquit à Lévi en Egypte, et elle enfanta à Hamram, Aaron, Moïse, et Marie leur soeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Et à Aaron naquirent Nadab, Abihu, Eléazar et Ithamar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Et Nadab et Abihu moururent en offrant du feu étranger devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Et tous les dénombrés des Lévites furent vingt-trois mille, tous mâles, depuis l’âge d’un mois, et au dessus, qui ne furent point dénombrés avec les autres enfants d’Israël, car on ne leur donna point d’héritage entre les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Ce sont là ceux qui furent dénombrés par Moïse et Eléazar le Sacrificateur, qui firent le dénombrement des enfants d’Israël aux campagnes de Moab, près du Jourdain de Jéricho.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Entre lesquels il ne s’en trouva aucun de ceux qui avaient été dénombrés par Moïse et Aaron Sacrificateur, quand ils firent le dénombrement des enfants d’Israël au désert de Sinaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Car l’Eternel avait dit d’eux, que certainement ils mourraient au désert; et ainsi il n’en resta pas un, excepté Caleb, fils de Jéphunné, et Josué, fils de Nun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Or les filles de Tsélophcad, fils de Hépher, fils de Galaad, fils de Makir, fils de Manassé, d’entre les familles de Manassé, fils de Joseph, s’approchèrent; et ce sont ici les noms de ces filles, Mahla, Noha, Hogla, Milca, et Tirtsa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'Elles se présentèrent devant Moïse, devant Eléazar Sacrificateur, devant les principaux et devant toute l’assemblée, à l’entrée du Tabernacle d’assignation, et dirent:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Notre père est mort au désert, qui toutefois n était point dans la troupe de ceux qui s’assemblèrent contre l’Eternel, savoir dans l’assemblée de Coré; mais il est mort dans son péché, et il n’a point eu de fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Pourquoi le nom de notre père serait-il retranché de sa famille, parce qu’il n’a point de fils? Donne-nous une possession parmi les frères de notre père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Et Moïse rapporta leur cause devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Les filles de Tsélophcad parlent sagement. Tu ne manqueras pas de leur donner un héritage à posséder parmi les frères de leur père, et tu leur feras passer l’héritage de leur père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Tu parleras aussi aux enfants d’Israël et leur diras: Quand quelqu’un mourra sans avoir des fils, vous ferez passer son héritage à sa fille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Que s’il n’a point de fille, vous donnerez son héritage à ses frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Et s’il n’a point de frères, vous donnerez son héritage aux frères de son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Que si son père n’a point de frère, vous donnerez son héritage à son parent, le plus proche de sa famille, et il le possédera; et ceci sera aux enfants d’Israël une ordonnance selon laquelle ils devront juger, comme l’Eternel l’a commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'L’Eternel dit aussi à Moïse: Monte sur cette montagne d’Abiram, et regarde le pays que j’ai donné aux enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Tu le regarderas donc, et puis tu seras toi aussi recueilli vers tes peuples, comme Aaron ton frère y a été recueilli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Parce que vous avez été rebelles à mon commandement au désert de Tsin, dans la dispute de l’assemblée, et que vous ne m’avez point sanctifié au sujet des eaux devant eux; ce sont les eaux de la dispute de Kadès, au désert de Tsin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Et Moïse parla à l’Eternel, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Que l’Eternel, le Dieu des esprits de toute chair, établisse sur l’assemblée quelque homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'Qui sorte et entre devant eux, et qui les fasse sortir et entrer; et que l’assemblée de l’Eternel ne soit pas comme des brebis qui n’ont point de Pasteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Alors l’Eternel dit à Moïse: Prends Josué, fils de Nun, qui est un homme en qui est l’Esprit, et tu poseras ta main sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'Tu le présenteras devant Eléazar le Sacrificateur, et devant toute l’assemblée; et tu l’instruiras en leur présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'Et tu lui feras part de ton autorité, afin que toute l’assemblée des enfants d’Israël l’écoute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Et il se présentera devant Eléazar le Sacrificateur, qui consultera pour lui par le jugement d’Urim devant l’Eternel; et à sa parole ils sortiront, et à sa parole ils entreront, lui, et les enfants d’Israël, avec lui, et toute l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Moïse donc fit comme l’Eternel lui avait commandé, et prit Josué, et le présenta devant Eléazar le Sacrificateur, et devant toute l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'Puis il posa ses mains sur lui, et l’instruisit, comme l’Eternel l’avait commandé par le moyen de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Commande aux enfants d’Israël, et leur dis: Vous prendrez garde à mes oblations, qui sont ma viande, savoir mes sacrifices faits par feu, qui sont mon odeur agréable, pour me les offrir en leur temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Tu leur diras donc: C’est ici le sacrifice fait par feu que vous offrirez à l’Eternel; deux agneaux d’un an sans tare, chaque jour, en holocauste continuel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Tu sacrifieras l’un des agneaux le matin, et l’autre agneau entre les deux vêpres;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'Et la dixième partie d’Epha de fine farine pour le gâteau, pétrie avec la quatrième partie d’un Hin d’huile vierge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'C’est l’holocauste continuel qui a été fait en la montagne de Sinaï, en bonne odeur, l’offrande faite par feu à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Et son aspersion sera d’une quatrième partie d’un Hin pour chaque agneau, et tu verseras dans le lieu saint l’aspersion de cervoise à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Et tu sacrifieras l’autre agneau entre les deux vêpres; tu feras le même gâteau qu’au matin, et la même aspersion, en sacrifice fait par feu en bonne odeur à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Mais le jour du Sabbat vous offrirez deux agneaux d’un an sans tare, et deux dixièmes de fine farine pétrie à l’huile pour le gâteau, avec son aspersion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'C’est l’holocauste du Sabbat pour chaque Sabbat, outre l’holocauste continuel avec son aspersion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Et au commencement de vos mois vous offrirez en holocauste à l’Eternel deux veaux pris du troupeau, un bélier, et sept agneaux d’un an, sans tare;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'Et trois dixièmes de fine farine pétrie à l’huile, pour le gâteau pour chaque veau, et deux dixièmes de fine farine pétrie à l’huile, pour le gâteau pour le bélier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'Et un dixième de fine farine pétrie à l’huile, pour le gâteau pour chaque agneau, en holocauste, de bonne odeur, et en sacrifice fait par feu à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Et leurs aspersions seront de la moitié d’un Hin de vin pour chaque veau, et de la troisième partie d’un Hin pour le bélier, et de la quatrième partie d’un Hin pour chaque agneau, c’est l’holocauste du commencement de chaque mois, selon tous les mois de l’année.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'On sacrifiera aussi à l’Eternel un jeune bouc en offrande pour le péché, outre l’holocauste continuel, et son aspersion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Et au quatorzième jour du premier mois sera la Pâque à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Et au quinzième jour du même mois sera la fête solennelle; on mangera durant sept jours des pains sans levain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Au premier jour il y aura une sainte convocation, vous ne ferez aucune oeuvre servile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Et vous offrirez un sacrifice fait par feu en holocauste à l’Eternel, savoir deux veaux pris du troupeau, et un bélier, et sept agneaux d’un an, qui seront sans tare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'Leur gâteau sera de fine farine pétrie à l’huile; vous en offrirez trois dixièmes pour chaque veau, et deux dixièmes pour le bélier;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'Tu en offriras aussi un dixième pour chacun des sept agneaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'Et un bouc en offrande pour le péché afin de faire propitiation pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Vous offrirez ces choses-là, outre l’holocauste du matin, qui est l’holocauste continuel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Vous offrirez selon ces choses-là en chacun de ces sept jours la viande du sacrifice fait par feu en bonne odeur à l’Eternel; on offrira cela outre l’holocauste continuel, et son aspersion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Et au septième jour vous aurez une sainte convocation; vous ne ferez aucune oeuvre servile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Et au jour des premiers fruits, quand vous offrirez à l’Eternel le nouveau gâteau, au bout de vos semaines, vous aurez une sainte convocation; vous ne ferez aucune oeuvre servile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Et vous offrirez en holocauste de bonne odeur à l’Eternel, deux veaux pris du troupeau, un bélier, et sept agneaux d’un an.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'Et leur gâteau sera de fine farine pétrie à l’huile, de trois dixièmes pour chaque veau, et de deux dixièmes pour le bélier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'Et d’un dixième pour chacun des sept agneaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'Et un jeune bouc, afin de faire propitiation pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Vous les offrirez outre l’holocauste continuel et son gâteau; ils seront sans tare, avec leurs aspersions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Et le premier jour du septième mois vous aurez une sainte convocation, vous ne ferez aucune oeuvre servile; ce vous sera le jour de jubilation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Et vous offrirez en holocauste de bonne odeur à l’Eternel, un veau pris du troupeau, un bélier, et sept agneaux d’un an sans tare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'Et leur gâteau sera de fine farine pétrie à l’huile, de trois dixièmes pour le veau, de deux dixièmes pour le bélier;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'Et d’un dixième pour chacun des sept agneaux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'Et un jeune bouc en offrande pour le péché, afin de faire propitiation pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Outre l’holocauste du commencement du mois et son gâteau, et l’holocauste continuel et son gâteau, et leurs aspersions, selon leur ordonnance, en bonne odeur de sacrifice fait par feu à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Et au dixième jour de ce septième mois vous aurez une sainte convocation, et vous affligerez vos âmes; vous ne ferez aucune oeuvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Et vous offrirez en holocauste de bonne odeur à l’Eternel, un veau pris du troupeau, un bélier, et sept agneaux d’un an, qui seront sans tare;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'Et leur gâteau sera de fine farine pétrie à l’huile, de trois dixièmes pour le veau, et de deux dixièmes pour le bélier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'Et d’un dixième pour chacun des sept agneaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Un jeune bouc aussi en offrande pour le péché, outre l’offrande pour le péché, laquelle on fait le jour des propitiations, et l’holocauste continuel et son gâteau, avec leurs aspersions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Et au quinzième jour du septième mois vous aurez une sainte convocation, vous ne ferez aucune oeuvre servile, et vous célébrerez à l’Eternel la fête solennelle, pendant sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Et vous offrirez en holocauste, qui sera un sacrifice fait par feu en bonne odeur à l’Eternel, treize veaux pris du troupeau, deux béliers, et quatorze agneaux d’un an, qui seront sans tare;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'Et leur gâteau sera de fine farine pétrie à l’huile, de trois dixièmes pour chacun des treize veaux, de deux dixièmes pour chacun des deux béliers,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'Et d’un dixième pour chacun des quatorze agneaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'Et un jeune bouc en offrande pour le péché, outre l’holocauste continuel, son gâteau, et son aspersion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Et au second jour vous offrirez douze veaux pris du troupeau, deux béliers, et quatorze agneaux d’un an, sans tare;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'Avec les gâteaux et les aspersions pour les veaux, pour les béliers, et pour les agneaux, selon leur nombre, et comme il les faut faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'Et un jeune bouc en offrande pour le péché, outre l’holocauste continuel, et son gâteau, avec leurs aspersions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Et au troisième jour vous offrirez onze veaux, deux béliers, et quatorze agneaux d’un an, sans tare;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'Et les gâteaux et les aspersions pour les veaux, pour les béliers et pour les agneaux, seront selon leur nombre, et comme il les faut faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'Et un bouc en offrande pour le péché, outre l’holocauste continuel, son gâteau, et son aspersion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Et au quatrième jour vous offrirez dix veaux, deux béliers, et quatorze agneaux d’un an, sans tare;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'Les gâteaux et les aspersions pour les veaux, pour les béliers, et pour les agneaux, seront selon leur nombre, et comme il les faut faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'Et un jeune bouc en offrande pour le péché, outre l’holocauste continuel, son gâteau, et son aspersion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Et au cinquième jour vous offrirez neuf veaux, deux béliers, et quatorze agneaux d’un an, sans tare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'Et les gâteaux et les aspersions pour les veaux, pour les béliers, et pour les agneaux, seront selon leur nombre, et comme il les faut faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'Et un bouc en offrande pour le péché, outre l’holocauste continuel, son gâteau, et son aspersion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Et au sixième jour vous offrirez huit veaux, deux béliers et quatorze agneaux d’un an, sans tare;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'Et les gâteaux, et les aspersions pour les veaux, pour les béliers, et pour les agneaux seront selon leur nombre, et comme il les faut faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'Et un bouc en offrande pour le péché, outre l’holocauste continuel, son gâteau, et son aspersion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Et au septième jour vous offrirez sept veaux, deux béliers, et quatorze agneaux d’un an sans tare;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'Et les gâteaux et les aspersions pour les veaux, pour les béliers, et pour les agneaux, seront selon leur nombre, et comme il les faut faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'Et un bouc en offrande pour le péché, outre l’holocauste continuel, son gâteau, et son aspersion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Et au huitième jour vous aurez une assemblée solennelle, vous ne ferez aucune oeuvre servile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Et vous offrirez en holocauste, qui sera un sacrifice fait par feu en bonne odeur à l’Eternel, un veau, un bélier, et sept agneaux d’un an sans tare;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'Les gâteaux et les aspersions pour le veau, pour le bélier, et pour les agneaux, seront selon leur nombre, et comme il les faut faire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'Et un bouc en offrande pour le péché, outre l’holocauste continuel, son gâteau, et son aspersion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Vous offrirez ces choses à l’Eternel dans vos fêtes solennelles, outre vos vœux, et vos offrandes volontaires, selon vos holocaustes, vos gâteaux, vos aspersions, et vos sacrifices de prospérités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Et Moïse parla aux enfants d’Israël selon toutes les choses que l’Eternel lui avait commandées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Moïse parla aussi aux chefs des Tribus des enfants d’Israël, en disant: C’est ici ce que l’Eternel a commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Quand un homme aura fait un voeu à l’Eternel, ou qu’il se sera engagé par serment, s’obligeant expressément sur son âme, il ne violera point sa parole, mais il fera selon toutes les choses qui seront sorties de sa bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Mais quand une femme aura fait un voeu à l’Eternel, et qu’elle se sera obligée expressément en sa jeunesse, étant encore dans la maison de son père;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Et que son père aura entendu son voeu, et son obligation par laquelle elle se sera obligée sur son âme, et que son père ne lui aura rien dit; tous ses voeux seront valables, et toute obligation par laquelle elle se sera obligée sur son âme, sera valable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Mais si son père la désavoue au jour qu’il l’aura entendu, aucun de tous ses voeux et aucune de toutes les obligations par lesquelles elle se sera obligée sur son âme, ne sera valable, et l’Eternel lui pardonnera; parce que son père l’a désavouée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Que si ayant un mari, elle s’est engagée par quelque voeu, ou par quelque chose qu’elle ait proférée légèrement de sa bouche, par laquelle elle se soit obligée sur son âme;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Si son mari l’a entendu, et que le jour même qu’il l’aura entendu il ne lui en ait rien dit, ses voeux seront valables, et les obligations par lesquelles elle se sera obligée sur son âme, seront valables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Mais si au jour que son mari l’aura entendu il l’a désavouée, il aura cassé le voeu par lequel elle s’était engagée, et ce qu’elle avait légèrement proféré de sa bouche, en quoi elle s’était obligée sur son âme; l’Eternel lui pardonnera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Mais le voeu de la veuve, ou de la répudiée, et tout ce à quoi elle se sera obligée sur son âme, sera valable contre elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Que si étant encore en la maison de son mari elle a fait un voeu, ou si elle s’est obligée expressément sur son âme, par serment;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'Et que son mari l’ayant entendu, ne lui en ait rien dit, et ne l’ait point désavouée; tous ses voeux seront valables, et toute obligation dont elle se sera obligée sur son âme, sera valable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Mais si son mari les a expressément cassés au jour qu’il les a entendus, rien qui soit sorti de sa bouche, soit ses voeux, soit obligation faite sur son âme, ne sera valable, parce que son mari les a cassés; et l’Eternel lui pardonnera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Son mari ratifiera ou cassera tout voeu et toute obligation faite par serment, pour affliger l’âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Que si son mari ne lui en a absolument rien dit d’un jour à l’autre, il aura ratifié tous ses voeux, et toutes ses obligations dont elle était tenue, il les aura, dis-je, ratifiés, parce qu’il ne lui en aura rien dit le jour qu’il l’a entendue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Mais s’il les a expressément cassés après gu’il les aura entendus, il portera l’iniquité de sa femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 17, 'Telles sont les ordonnances que l’Eternel donna à Moïse par rapport à l’homme et à sa femme; au père et à sa fille, étant encore dans la maison de son père, en sa jeunesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Fais la vengeance des enfants d’Israël sur les Madianites, puis tu seras recueilli vers tes peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Moïse donc parla au peuple, en disant: Que quelques-uns d’entre vous s’équipent pour aller à la guerre, et qu’ils aillent contre Madian, pour exécuter la vengeance de l’Eternel sur Madian.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Vous enverrez à la guerre mille hommes de chaque Tribu, de toutes les tribus d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'On donna donc d’entre les milliers d’Israël mille hommes de chaque Tribu, qui furent douze mille hommes équipés pour la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Et Moïse les envoya à la guerre, savoir mille de chaque Tribu, et avec eux Phinées, fils d’Eiéazar le Sacrificateur, qui avait les vaisseaux du Sanctuaire, et les trompettes de retentissement en sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Ils marchèrent donc en guerre contre Madian, comme l’Eternel l’avait commandé à Moïse, et ils en tuèrent tous les mâles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Ils tuèrent aussi les Rois de Madian, outre les autres qui y furent tués, savoir Evi, Rékem, Tsur, Hur, et Rébah, cinq Rois de Madian; ils firent aussi passer au fil de l’épée Balaam fils de Béhor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Et les enfants d’Israël emmenèrent prisonniers les femmes de Madian, avec leurs petits enfants, et pillèrent tout leur gros et menu bétail, et tout ce qui était en leur puissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Ils brûlèrent au feu toutes leurs villes, leurs demeures, et tous leurs châteaux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Et ils prirent tout le butin et tout le pillage, tant des hommes que du bétail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'Puis ils amenèrent les prisonniers, le pillage, et le butin, à Moïse et à Eléazar le Sacrificateur, et à l’assemblée des enfants d’Israël, au camp dans les campagnes de Moab, qui sont près du Jourdain de Jéricho.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Alors Moïse et Eléazar le Sacrificateur, et tous les principaux de l’assemblée sortirent au devant d’eux hors du camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Et Moïse se mit en grande colère contre les Capitaines de l’armée, les chefs des milliers, et les chefs des centaines, qui retournaient de cet exploit de guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Et Moïse leur dit: N’avez-vous pas gardé en vie toutes les femmes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Voici ce sont elles qui à la parole de Balaam, ont donné occasion aux enfants d’Israël de pécher contre l’Eternel au fait de Péhor ce qui attira la plaie sur l’assemblée de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Or maintenant tuez tous les mâles d’entre les petits enfants, et tuez toute femme qui aura eu compagnie d’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Mais vous garderez en vie toutes les jeunes filles qui n’ont point eu compagnie d’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Au reste, demeurez sept jours hors du camp. Quiconque tuera quelqu’un, et quiconque touchera quelqu’un qui aura été tué, se purifiera le troisième et le septième jour, tant vous que vos prisonniers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Vous purifierez aussi tous vos vêtements, et tout ce qui sera fait de peau, et tous ouvrages de poil de chèvre, et toute vaisselle de bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Et Eléazar le Sacrificateur dit aux hommes de guerre qui étaient allés à la bataille: Voici l’ordonnance et la Loi que l’Eternel a commandée à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'En général l’or, l’argent, l’airain, le fer, l’étain, le plomb;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'Tout ce qui peut passer par le feu, vous le ferez passer par le feu, et il sera net; seulement on le purifiera avec l’eau d’aspersion; mais vous ferez passer par l’eau toutes les choses qui ne passent point par le feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Vous laverez aussi vos vêtements le septième-jour, et vous serez nets, puis vous entrerez au camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Fais le compte du butin, et de tout ce qu’on a emmené, tant des personnes que des bêtes, toi et Eléazar le Sacrificateur, et les chefs des pères de l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'Et partage par moitié le butin entre les combattants qui sont allés à la guerre, et toute l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Tu lèveras aussi pour l’Eternel un tribut des gens de guerre qui sont allés à la bataille, savoir de cinq cents un, tant des personnes que des boeufs, des ânes et des brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'On le prendra de leur moitié, et tu le donneras à Eléazar le Sacrificateur, en offrande élevée à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Et de l’ autre moitié qui appartient aux enfants d’Israël, tu en prendras à part de cinquante un, tant des personnes que des boeufs, des ânes, des brebis et de tous autres animaux, et tu le donneras aux Lévites qui ont la charge de garder le pavillon de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Et Moïse et Eléazar le Sacrificateur firent comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Or le butin, qui était resté du pillage que le peuple qui était allé à la guerre, avait fait, était de six cent soixante et quinze mille brebis;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'De soixante et douze mille boeufs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'De soixante et un mille ânes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'Et quant aux femmes qui n’avaient point eu compagnie d’homme, elles étaient en tout trente-deux mille âmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Et la moitié du butin, savoir la part de ceux qui étaient allés à la guerre, montait à trois cent trente-sept mille cinq cents brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'Dont le tribut pour l’Eternel, quant aux brebis, fut de six cent soixante et quinze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'Et à trente-six mille bœufs; dont le tribut pour l’Eternel, quant aux boeufs, fut de soixante et douze bœufs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'Et à trente mille cinq cents ânes; dont le tribut pour l’Eternel, quant aux ânes, fut de soixante et un ânes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'Et à seize mille personnes; dont le tribut pour l’Eternel fut de trente-deux personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Et Moïse donna à Eléazar le Sacrificateur le tribut de l’offrande élevée de l’Eternel, comme l’Eternel le lui avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Et de l’autre moitié qui appartenait aux enfants d’Israël, laquelle Moïse avait tirée des hommes qui étaient allés à la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'Or de cette moitié qui fut pour l’assemblée, et qui montait à trois cent trente-sept mille cinq cents brebis;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'A trente-six mille bœufs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'A trente mille cinq cents ânes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'Et à seize mille personnes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'De cette moitié, dis-je, qui appartenait aux enfants d’Israël, Moïse prit à part de cinquante un, tant des personnes que des bêtes, et les donna aux Lévites qui avaient la charge de garder le pavillon de l’Eternel, comme l’Eternel le lui avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Et les capitaines qui avaient charge des milliers de l’armée, tant les chefs des milliers, que les chefs des centaines, s’approchèrent de Moïse,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'Et lui dirent: Tes serviteurs ont fait le compte des gens de guerre qui sont sous notre charge, et il ne s’en manque pas un seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'C’est pourquoi nous offrons l’offrande de l’Eternel, chacun ce qu’il s’est trouvé avoir, des joyaux d’or, des jarretières, des bracelets, des anneaux, des pendants d’oreilles, et des colliers, afin de faire propitiation pour nos personnes devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Et Moïse et Eléazar le Sacrificateur reçurent d’eux l’or, savoir toute pièce d’ouvrage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Et tout l’or de l’offrande élevée qui fut présenté à l’Eternel de la part des chefs de milliers et des chefs de centaines, montait à seize mille sept cent cinquante sicles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Or les gens de guerre retinrent chacun pour soi ce qu’ils avaient pillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Moïse donc et Eléazar le Sacrificateur prirent des chefs de milliers et des chefs de centaines cet or-là, et l’apportèrent au Tabernacle d’assignation, en mémorial pour les enfants d’Israël, devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Or les enfants de Ruben et les enfants de Gad avaient beaucoup de bétail, et en fort grande quantité; et ayant vu le pays de Jahzer, et le pays de Galaad, voici, ils remarquèrent que ce lieu-là était propre à tenir du bétail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Ainsi les enfants de Gad et les enfants de Ruben vinrent, et parlèrent à Moïse et à Eléazar le Sacrificateur, et aux principaux de l’assemblée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Hataroth, et Dibon, et Jahzer, et Nimrah, et Hesbon, et Elhaleh, et Sébam, et Nébo, et Béhon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'Ce pays-là, que l’Eternel a frappé devant l’assemblée d’Israël, est un pays propre à tenir du bétail, et tes serviteurs ont du bétail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Ils dirent donc: Si nous avons trouvé grâce devant toi, que ce pays soit donné à tes serviteurs en possession; et ne nous fais point passer le Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Mais Moïse répondit aux enfants de Gad, et aux enfants de Ruben: Vos frères iront-ils à la guerre, et vous demeurerez-vous ici?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Pourquoi faites-vous perdre courage aux enfants d’Israël, pour ne point passer au pays que l’Eternel leur a donné?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'C’est ainsi que firent vos pères quand je les envoyai de Kadès-barné pour reconnaître le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Car ils montèrent jusqu’à la vallée d’Escol, et virent le pays, puis ils firent perdre courage aux enfants d’Israël, afin qu’ils n’entrassent point au pays que l’Eternel leur avait donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'C’est pourquoi la colère de l’Eternel s’enflamma en ce jour-là, et il jura, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Si les hommes qui sont montés hors d’Egypte, depuis l’âge de vingt ans, et au dessus, voient le pays pour lequel j’ai juré à Abraham, à Isaac, et à Jacob; car ils n’ont point persévéré à me suivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'Excepté Caleb, fils de Jéphunné Kénisien, et Josué fils de Nun; car ils ont persévéré à suivre l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Ainsi la colère de l’Eternel s’enflamma contre Israël, et il les a fait errer par le désert, quarante ans, jusqu’à ce que toute la génération qui avait fait ce qui déplaisait à l’Eternel, ait été consumée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Et voici, vous vous êtes mis en la place de vos pères, comme une race d’hommes pécheurs, pour augmenter encore l’ardeur de la colère de l’Eternel contre Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Que si vous vous détournez de lui, il continuera encore à le laisser au désert, et vous ferez détruire tout ce peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Mais ils s’approchèrent de lui, et lui dirent: Nous bâtirons ici des cloisons pour nos troupeaux, et les villes seront pour nos familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'Et nous nous équiperons pour marcher promptement devant les enfants d’Israël, jusqu’à ce que nous les ayons introduits en leur lieu; mais nos familles demeureront dans les villes murées, à cause des habitants du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Nous ne retournerons point en nos maisons que chacun des enfants d’Israël n’ait pris possession de son héritage;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Et nous ne posséderons rien en héritage avec eux au delà du Jourdain, ni plus avant; parce que notre héritage nous sera échu au deçà du Jourdain vers l’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Et Moïse leur dit: Si vous faites cela, et que vous vous équipiez devant l’Eternel pour aller à la guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'Et que chacun de vous étant équipé passe le Jourdain devant l’Eternel, jusqu’à ce qu’il ait chassé ses ennemis de devant soi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'Et que le pays soit subjugué devant l’Eternel, et qu’ensuite vous vous en retourniez, alors vous serez innocents envers l’Eternel, et envers Israël; et ce pays-ci vous appartiendra pour le posséder devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Mais si vous ne faites point cela, voici, vous aurez péché contre l’Eternel; et sachez que votre péché vous trouvera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Bâtissez donc des villes pour vos familles; et des cloisons pour vos troupeaux, et faites ce que vous avez dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Alors les enfants de Gad, et les enfants de Ruben parlèrent à Moïse, en disant: Tes serviteurs feront comme mon Seigneur l’a commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Nos petits enfants, nos femmes, nos troupeaux, et toutes nos bêtes demeureront ici dans les villes de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'Et tes serviteurs passeront chacun armé pour aller à la guerre devant l’Eternel, prêts à combattre, comme mon Seigneur a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Alors Moïse commanda touchant eux à Eléazar le Sacrificateur, à Josué, fils de Nun, et aux chefs des pères des Tribus des enfants d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'Et leur dit: Si les enfants de Gad et les enfants de Ruben passent avec vous le Jourdain tous armés, prêts à combattre devant l’Eternel, et que le pays vous soit assujetti, vous leur donnerez le pays de Galaad en possession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Mais s’ils ne passent point en armes avec vous, ils auront une possession parmi vous au pays de Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Et les enfants de Gad, et les enfants de Ruben répondirent, en disant: Nous ferons ainsi que l’Eternel a parlé à tes serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Nous passerons en armes devant l’Eternel au pays de Canaan, afin que nous possédions pour notre héritage ce qui est deçà le Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Ainsi Moïse donna aux enfants de Gad, et aux enfants de Ruben, et à la demi- Tribu de Manassé, fils de Joseph, le Royaume de Sihon, Roi des Amorrhéens; et le Royaume de Hog, Roi de Basan, le pays avec ses villes, selon les bornes des villes du pays à l’environ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Alors les enfants de Gad rebâtirent Dibon, Hataroth, Haroher,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Hatroth-Sophan, Jahzer, Jogbéha,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Beth-nimrah, et Beth-haran, villes murées. Ils firent aussi des cloisons pour les troupeaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Et les enfants de Ruben rebâtirent Hesbon, Elhalé, Kirjathajim,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Nébo, et Bahal-méhon, et Sibma; dont ils changèrent les noms, et ils donnèrent des noms aux villes qu’ils rebâtirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Or les enfants de Makir, fils de Manassé, allèrent en Galaad, et le prirent, et dépossédèrent les Amorrhéens qui y étaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Moïse donc donna Galaad à Makir, fils de Manassé, qui y habita.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Jaïr aussi fils de Manassé, s’en alla, et prit leurs bourgs, et les appela bourgs de Jaïr.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Et Nobah s’en alla, et prit Kénath avec les villes de son ressort, et l’appela Nobah de son nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Ce sont ici les traittes des enfants d’Israël, qui sortirent du pays d’Egypte, selon leurs bandes, sous la conduite de Moïse et d’Aaron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Car Moïse écrivit leurs délogements, par leurs traittes, suivant le commandement de l’Eternel; ce sont donc ici leurs traittes selon leurs délogements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Les enfants d’Israël donc partirent de Rahmésès le quinzième jour du premier mois, dès le lendemain de la Pâque, et ils sortirent à main levée, à la vue de tous les Egyptiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'Et les Egyptiens ensevelissaient ceux que l’Eternel avait frappés parmi eux, savoir tous les premiers-nés; même l’Eternel avait exercé ses jugements sur leurs dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Et les enfants d’Israël étant partis de Rahmésès, campèrent à Succoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Et étant partis de Succoth, ils campèrent à Etham, qui est au bout du désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Et étant partis d’Etham, ils se détournèrent contre Pi-hahiroth, qui est vis-à-vis de Bahal-tséphon, et campèrent devant Migdol.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Et étant partis de devant Pi-hahiroth, ils passèrent au travers de la mer vers le désert, et firent trois journées de chemin par le désert d’Etham, et campèrent à Mara.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Et étant partis de Mara, ils vinrent à Elim, où il y avait douze fontaines d’eaux, et soixante et dix palmiers, et ils y campèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Et étant partis d’Elim, ils campèrent près de la mer Rouge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Et étant partis de la mer Rouge, ils campèrent au désert de Sin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Et étant partis du désert de Sin, ils campèrent à Dophka.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Et étant partis de Dophka, ils campèrent à Alus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Et étant partis d’Alus, ils campèrent à Rephidim, où il n’y avait point d’eau à boire pour le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Et étant partis de Rephidim, ils campèrent au désert de Sinaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Et étant partis du désert de Sinaï, ils campèrent à Kibroth-taava.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Et étant partis de Kibroth-taava, ils campèrent à Hatséroth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Et étant partis de Hatséroth, ils campèrent à Rithma.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Et étant partis de Rithma, ils campèrent à Rimmon-pérets.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Et étant partis de Rimmon-pérets, ils campèrent à Libna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Et étant partis de Libna, ils campèrent à Rissa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Et étant partis de Rissa, ils campèrent vers Kehélath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Et étant partis de devers Kehélath, ils campèrent en la montagne de Sépher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Et étant partis de la montagne de Sépher, ils campèrent à Harada.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Et étant partis de Harada, ils campèrent à Makheloth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Et étant partis de Makheloth, ils campèrent à Tahath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Et étant partis de Tahath, ils campèrent à Térah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Et étant partis de Térah, ils campèrent à Mithka.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Et étant partis de Mithka, ils campèrent à Hasmona.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Et étant partis de Hasmona, ils campèrent à Moséroth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Et étant partis de Moséroth, ils campèrent à Béné-jahakan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Et étant partis de Béné-jahakan, ils campèrent à Hor-guidgad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Et étant partis de Hor-guidgad, ils campèrent vers Jotbath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Et étant partis de devant Jotbath, ils campèrent à Habrona.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Et étant partis de Habrona, ils campèrent à Hetsjon-guéber.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Et étant partis de Hetsjon-guéber, ils campèrent au désert de Tsin, qui est Kadès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Et étant partis de Kadès, ils campèrent en la montagne de Hor, qui est au bout du pays d’Edom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Et Aaron le Sacrificateur monta sur la montagne de Hor, suivant le commandement de l’Eternel, et mourut là, en la quarantième année après que les enfants d’Israël furent sortis du pays d’Egypte, le premier jour du cinquième mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Et Aaron était âgé de cent vingt-trois ans, quand il mourut sur la montagne de Hor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Alors le Cananéen, Roi de Harad, qui habitait vers le Midi au pays de Canaan, apprit que les enfants d’Israël venaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Et étant partis de la montagne de Hor, ils campèrent à Tsalmona.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Et étant partis de Tsalmona, ils campèrent à Punon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Et étant partis de Punon, ils campèrent à Oboth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Et étant partis d’Oboth, ils campèrent à Hijé-habarim, sur les frontières de Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Et étant partis de Hijim, ils campèrent à Dibon-gad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Et étant partis de Dibon-gad, ils campèrent à Halmon vers Diblatajim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Et étant partis de Halmon vers Diblatajim, ils campèrent aux montagnes de Habarim contre Nébo.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Et étant partis des montagnes de Habarim, ils campèrent aux campagnes de Moab, près du Jourdain de Jéricho.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Et ils campèrent près du Jourdain, depuis Beth-jésimoth jusqu’à Abel-Sittim, dans les campagnes de Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Et l’Eternel parla à Moïse dans les campagnes de Moab, près du Jourdain de Jéricho, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Parle aux enfants d’Israël, et leur dis: Puisque vous allez passer le Jourdain pour entrer au pays de Canaan;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'Chassez de devant vous tous les habitants du pays, et détruisez toutes leurs peintures, ruinez toutes leurs images de fonte, et démolissez tous leurs hauts lieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'Et rendez-vous maîtres du pays, et y habitez; car je vous ai donné le pays pour le posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Or vous hériterez le pays par sort selon vos familles. A ceux qui sont en plus grand nombre, vous donnerez plus d’héritage; et à ceux qui sont en plus petit nombre, vous donnerez moins d’héritage; chacun aura selon qu’il lui sera échu par sort, et vous hériterez selon les Tribus de vos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Mais si vous ne chassez pas de devant vous les habitants du pays, il arrivera que ceux d’entr’eux que vous aurez laissés de reste, seront comme des épines à vos yeux, et comme des pointes à vos côtés, et ils vous serreront de près dans le pays auquel vous habiterez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Et il arrivera que je vous ferai tout comme j’ai eu dessein de leur faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'L’Eternel parla aussi à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Commande aux enfants d’Israël, et leur dis: Parce que vous allez entrer au pays de Canaan, ce sera ici le pays qui vous écherra en héritage, le pays de Canaan selon ses limites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Votre frontière du côté du Midi sera depuis le désert de Tsin, le long d’Edom; tellement que votre frontière du côté du Midi commencera au bout de la mer Salée vers l’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Et cette frontière tournera du Midi vers la montée de Hakrabbim, et passera jusqu’à Tsin; et elle aboutira du côté du Midi, à Kadès-barné, et sortira aussi en Hatsar-addar, et passera jusqu’à Hatsmon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'Et cette frontière tournera depuis Hatsmon jusqu’au torrent d’Egypte; et elle aboutira à la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Et quant à la frontière d’Occident, vous aurez la grande mer, et ses limites; ce vous sera la frontière Occidentale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Et ce sera ici votre frontière du Septentrion; depuis la grande mer vous marquerez pour vos limites la montagne de Hor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'Et de la montagne de Hor vous marquerez pour vos limites l’entrée de Hamath; et cette frontière se rendra vers Tsédad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'Et cette frontière passera jusqu’à Ziphron, et elle aboutira à Hatsar-hénan; telle sera votre frontière du Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Puis vous marquerez pour vos limites vers l’Orient depuis Hatsar-hénan vers Sepham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'Et cette frontière descendra de Sepham à Riblat, du côté de l’Orient de Hajin; et cette frontière descendra et s’étendra le long de la mer de Kinnereth vers l’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Et cette frontière descendra au Jourdain, et se rendra à la mer salée; tel sera le pays que vous aurez selon ses limites tout autour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Et Moïse commanda aux enfants d’Israël, en disant: C’est là le pays que vous hériterez par sort, lequel l’Eternel a commandé de donner à neuf Tribus, et à la moitié d’une Tribu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Car la Tribu des enfants de Ruben selon les familles de leurs pères, et la Tribu des enfants de Gad, selon les familles de leurs pères, ont pris leur héritage; et la demi-Tribu de Manassé a pris aussi son héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Deux tribus, dis-je, et la moitié d’une Tribu, ont pris leur héritage au deçà du Jourdain de Jéricho, du côté du Levant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Et l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Ce sont ici les noms des hommes qui vous partageront le pays, Eléazar, le Sacrificateur, et Josué, fils de Nun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Vous prendrez aussi un des principaux de chaque Tribu pour faire le partage du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Et ce sont ici les noms de ces hommes-là. Pour la Tribu de Juda, Caleb, fils de Jéphunné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'Pour la Tribu des enfants de Siméon, Samuel, fils de Hammiud.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Pour la Tribu de Benjamin, Elidad, fils de Kislon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'Pour la Tribu des enfants de Dan, celui qui en est le chef, Bukki, fils de Jogli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Des enfants de Joseph, pour la Tribu des enfants de Manassé, celui qui en est le chef, Hanniel, fils d’Ephod.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'Pour la Tribu des enfants d’Ephraïm, celui qui en est le chef, Kémuel, fils de Siphthan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'Pour la Tribu des enfants de Zabulon, celui qui en est le chef, Elitsaphan, fils de Parnac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'Pour la Tribu des enfants d’Issacar, celui qui en est le chef, Paltiel, fils de Hazan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'Pour la Tribu des enfants d’Aser, celui qui en est le chef, Ahihud, fils de Sélomi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'Et pour la Tribu des enfants de Nephthali, celui qui en est le chef, Pédahel, fils de Hammiud.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Ce sont là ceux auxquels l’Eternel commanda de partager l’héritage aux enfants d’Israël dans le pays de Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Et l’Eternel parla à Moïse dans les campagnes de Moab, près du Jourdain de Jéricho, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Commande aux enfants d’Israël qu’ils donnent du partage de leur possession, des villes aux Lévites pour y habiter. Vous leur donnerez aussi les faubourgs qui sont autour de ces villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Ils auront donc les villes pour y habiter; et les faubourgs de ces villes seront pour leurs bêtes, pour leurs biens, et pour tous leurs animaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Les faubourgs des villes que vous donnerez aux Lévites, seront de mille coudées tout autour depuis la muraille de la ville en dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Et vous mesurerez depuis le dehors de la ville du côté d’Orient, deux mille coudées; et du côté du Midi, deux mille coudées; et du côte d’Occident, deux mille coudées; et du côté du Septentrion, deux mille coudées; et la ville sera au milieu: tels seront les faubourgs de leurs villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Et des villes que vous donnerez aux Lévites, il y en aura six de refuge, lesquelles vous établirez afin que le meurtrier s’y enfuie; et outre celles-là vous leur donnerez quarante-deux villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Toutes les villes que vous donnerez aux Lévites seront quarante-huit villes; vous les donnerez avec leurs faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Et quant aux villes que vous donnerez de la possession des enfants d’Israël, vous en donnerez plus de la portion de ceux qui en auront plus, et vous en donnerez moins, de la portion de ceux qui en auront moins, chacun donnera de ses villes aux Lévites à proportion de l’héritage qu’il possédera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Puis l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Parle aux enfants d’Israël, et leur dis: Quand vous aurez passé le Jourdain pour entrer au pays de Canaan;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'Etablissez-vous des villes qui vous soient des villes de refuge, afin que le meurtrier qui aura frappe à mort quelque personne par mégarde, s’y enfuie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Et ces villes vous seront pour refuge de devant celui qui a le droit de venger le sang, et le meurtrier ne mourra point qu’il n’ait comparu en jugement devant l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'De ces villes-là donc que vous aurez données, il y en aura six de refuge pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Desquelles vous en établirez trois au deçà du Jourdain, et vous établirez les trois autres au pays de Canaan, qui seront des villes de refuge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Ces six villes serviront de refuge aux enfants d’Israël, et à l’étranger, et au forain qui séjourne parmi eux, afin que quiconque aura frappé à mort quelque personne par mégarde, s’y enfuie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Mais si un homme en frappe un autre avec un instrument de fer, et qu’il en meure, il est meurtrier; on punira de mort le meurtrier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Et s’il l’a frappé d’une pierre qu’il eût en sa main, dont cet homme puisse mourir, et qu’il en meure, il est meurtrier; on punira de mort le meurtrier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'De même s’il l’a frappé d’un instrument de bois qu’il eût en sa main, dont cet homme puisse mourir, et qu’il meure, il est meurtrier; on punira de mort le meurtrier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Et celui qui a le droit de faire la vengeance du sang, fera mourir le meurtrier; quand il le rencontrera, il le pourra faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Que s’il l’a poussé par haine, ou s’il a jeté quelque chose sur lui de dessein prémédité, et qu’il en meure;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'Ou que par inimitié il l’ait frappé de sa main, et qu’il en meure, on punira de mort celui qui l’a frappé, car il est meurtrier; celui qui a le droit de faire la vengeance du sang le pourra faire mourir quand il le rencontrera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Mais si par hasard, sans inimitié, il l’a poussé, ou s’il a jeté sur lui quelque chose, mais sans dessein;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'Ou quelque pierre sans l’avoir vu, et qu’il en meure, l’ayant fait tomber sur lui, et qu’il en meure, s’il n’était point son ennemi, et s’il n’a point cherché sa perte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'Alors l’assemblée jugera entre celui qui a frappé, et celui qui a le droit de faire la vengeance du sang, selon ces lois-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'Et l’assemblée délivrera le meurtrier de la main de celui qui a le droit de faire la vengeance du sang, et le fera retourner à la ville de son refuge, où il s’en était fui, et il y demeurera jusqu’à la mort du souverain Sacrificateur, qui aura été oint de la sainte huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Mais si le meurtrier sort de quelque manière que ce soit hors des bornes de la ville de son refuge, où il s’était enfui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'Et que celui qui a le droit de faire la vengeance du sang le trouve hors des bornes de la ville de son refuge, et qu’il tue le meurtrier, il ne sera point coupable de meurtre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Car il doit demeurer en la ville de son refuge jusqu’à la mort du souverain Sacrificateur; mais après la mort du souverain Sacrificateur le meurtrier retournera en la terre de sa possession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Et ces choses-ci vous seront pour ordonnances de jugement en vos âges, dans toutes vos demeures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Celui qui fera mourir le meurtrier, le fera mourir sur la parole de deux témoins; mais un seul témoin ne sera point reçu en témoignage contre quelqu’un, pour le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Vous ne prendrez point de prix pour la vie du meurtrier, parce qu’étant méchant il est digne de mort; et on le fera mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Ni vous ne prendrez point de prix pour le laisser enfuir dans la ville de son refuge; ni pour le laisser retourner habiter au pays, jusqu’à la mort du Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Et vous ne souillerez point le pays où vous serez; car le sang souille le pays; et il ne se fera point d’expiation pour le pays, du sang qui y aura été répandu, que par le sang de celui qui l’aura répandu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Vous ne souillerez donc point le pays où vous allez demeurer, et au milieu duquel j’habiterai; car je suis l’Eternel qui habite au milieu des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Or les chefs des pères de la famille des enfants de Galaad, fils de Makir, fils de Manassé, d’entre les familles des enfants de Joseph, s’approchèrent, et parlèrent devant Moïse, et devant les principaux qui étaient les chefs des pères des enfants d’Israël,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'Et dirent: l’Eternel a commandé à mon Seigneur de donner aux enfants d’Israël le pays en héritage par sort; et mon Seigneur a reçu commandement de l’Eternel de donner l’héritage de Tsélophcad notre frère à ses filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Si elles sont mariées à quelqu’un des enfants des autres Tribus d’Israël, leur héritage sera ôté de l’héritage de nos pères, et sera ajouté à l’héritage de la Tribu de laquelle elles seront; ainsi il sera ôté de l’héritage qui nous est échu par le sort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Même quand le temps du Jubilé viendra pour les enfants d’Israël, on ajoutera leur héritage à l’héritage de la Tribu de laquelle elles seront; ainsi leur héritage sera retranché de l’héritage de nos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Et Moïse commanda aux enfants d’Israël, suivant le commandement de la bouche de l’Eternel, en disant: Ce que la Tribu des enfants de Joseph dit, est juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'C’est ici ce que l’Eternel a commandé au sujet des filles de Tsélophcad, en disant: Elles se marieront à qui bon leur semblera, toutefois elles seront mariées dans quelqu’une des familles de la Tribu de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Ainsi l’héritage ne sera point transporté entre les enfants d’Israël de Tribu en Tribu; car chacun des enfants d’Israël se tiendra à l’héritage de la Tribu de ses pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Et toute fille qui sera héritière de quelque possession d’entre les Tribus des enfants d’Israël, sera mariée à quelqu’un de la famille de la Tribu de son père, afin que chacun des enfants d’Israël hérite l’héritage de ses pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'L’héritage donc ne sera point transporté d’une Tribu à l’autre, mais chacun d’entre les Tribus des enfants d’Israël se tiendra à son héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Les filles de Tsélophcad firent ainsi que l’Eternel avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Car Mahla, Tirtsa, Hogla, Milca, et Noha, filles de Tsélophcad, se marièrent aux enfants de leurs oncles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Ainsi elles furent mariées à ceux qui étaient des familles des enfants de Manassé, fils de Joseph; et leur héritage demeura dans la Tribu de la famille de leur père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Ce sont là les commandements et les jugements que l’Eternel ordonna par le moyen de Moïse aux enfants d’Israël, dans les campagnes de Moab, près du');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Ce sont ici les paroles que Moïse dit à tout Israël deçà le Jourdain au désert, dans la campagne, qui est vis à vis de la mer Rouge, entre Paran, et Tophel, et Laban, et Hatséroth, et Dizahab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Il y a onze journées depuis Horeb, par le chemin de la montagne de Séhir, jusqu’à Kadès-Barné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Or il arriva en la quarantième année, au premier jour de l’onzième mois, que Moïse parla aux enfants d’Israël selon tout ce que l’Eternel lui avait commandé de leur dire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Après qu’il eut défait Sihon, Roi des Amorrhéens, qui demeurait à Hesbon; et Hog, Roi de Basan, qui demeurait à Hastaroth et à Edréhi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Moïse donc commença à déclarer cette loi deçà le Jourdain, dans le pays de Moab, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'L’Eternel notre Dieu nous parla en Horeb, en disant: Vous avez assez demeuré en cette montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Tournez, et partez, et allez vers la montagne des Amorrhéens, et dans tous les lieux circonvoisins, en la campagne, à la montagne, et en la plaine, et vers le Midi, et sur le rivage de la mer, au pays des Cananéens, et au Liban jusqu’au grand fleuve, le fleuve d’Euphrate.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Regardez, j’ai mis devant vous le pays, entrez et possédez le pays que l’Eternel a juré à vos pères, Abraham, Isaac et Jacob, de leur donner, et à leur postérité après eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Et je vous parlai en ce temps-là, et vous dis: Je ne puis pas vous porter moi seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'L’Eternel votre Dieu vous a multipliés, et vous voici aujourd’hui comme les étoiles du ciel, par le grand nombre que vous êtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Que l’Eternel le Dieu de vos pères vous fasse croître mille fois au delà de ce que vous êtes, et vous bénisse, comme il vous l’a dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Comment porterais-je moi seul vos chagrins, vos charges, et vos procès?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Prenez-vous de vos Tribus des gens sages et habiles, et connus, et je vous les établirai pour chefs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Et vous me répondîtes et dîtes: Il est bon de faire ce que tu as dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Alors je pris des chefs de vos Tribus, des hommes sages et connus, et je les établis chefs sur vous, gouverneurs sur milliers, et sur centaines, sur cinquantaines et sur dizaines, et officiers selon vos Tribus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Puis je commandai en ce temps-là à vos juges, en disant: Ecoutez les différends qui seront entre vos frères, et jugez droitement entre l’homme et son frère, et entre l’étranger qui est avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Vous n’aurez point d’égard à l’apparence de la personne en jugement; vous entendrez autant le petit que le grand; vous ne craindrez personne, car le jugement est à Dieu; et vous ferez venir devant moi la cause qui sera trop difficile pour vous, et je l’entendrai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Et en ce temps-là je vous ordonnai toutes les choses que vous auriez à faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Puis nous partîmes d’Horeb, et nous marchâmes dans tout ce grand et affreux désert que vous avez vu, par le chemin de la montagne des Amorrhéens, ainsi que l’Eternel notre Dieu nous avait commandé, et nous vînmes jusqu’à Kadès-barné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Alors je vous dis: Vous êtes arrivés jusqu’à la montagne des Amorrhéens, laquelle l’Eternel notre Dieu nous donne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Regarde, l’Eternel ton Dieu met devant toi le pays, monte et le possède, selon que l’Eternel le Dieu de tes pères t’a dit: Ne crains point, et ne t’effraie point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Et vous vîntes tous vers moi, et dîtes: Envoyons devant nous des hommes, pour reconnaître le pays, et qui nous rapportent des nouvelles du chemin par lequel nous devrons monter, et des villes où nous devrons aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Et ce discours me sembla bon, de sorte que je pris douze hommes d’entre vous, savoir un homme de chaque Tribu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Et ils se mirent en chemin, et étant montés en la montagne ils vinrent jusqu’au torrent d’Escol, et reconnurent le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Et ils prirent en leurs mains du fruit du pays, et ils nous l’apportèrent; ils nous donnèrent des nouvelles, et nous dirent: Le pays que l’Eternel, notre Dieu nous donne, est bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Mais vous refusâtes d’y monter, et vous fûtes rebelles au commandement de l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'Et vous murmurâtes dans vos tentes, en disant: Parce que l’Eternel nous haïssait il nous a fait sortir du pays d’Egypte, afin de nous livrer entre les mains des Amorrhéens pour nous exterminer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Où monterions-nous? Nos frères nous ont fait fondre le coeur, en disant: Le peuple est plus grand que nous, et de plus haute taille; les villes sont grandes et closes jusques au ciel; et même nous avons vu là les enfants des Hanakins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Mais je vous dis: N’ayez point de peur, et ne les craignez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'L’Eternel votre Dieu qui marche devant vous, lui-même combattra pour vous, selon tout ce que vous avez vu qu’il a fait pour vous en Egypte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'Et au désert, où tu as vu de quelle manière l’Eternel ton Dieu t’a porté, comme un homme porterait son fils, dans tout le chemin où vous avez marché, jusqu’à ce que vous soyez arrivés en ce lieu-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Mais malgré cela vous ne crûtes point encore en l’Eternel votre Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'Qui marchait devant vous dans le chemin, afin de vous chercher un lieu pour camper, marchant de nuit dans la colonne de feu, pour vous éclairer dans le chemin par lequel vous deviez marcher; et de jour, dans la nuée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Et l’Eternel ouït la voix de vos paroles, et se mit en grande colère, et jura, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Si aucun des hommes de cette méchante génération voit ce bon pays que j’ai juré de donner à vos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'Sinon Caleb, fils de Jéphunné; lui le verra, et je lui donnerai à lui et à ses enfants le pays sur lequel il a marché, parce qu’il a persévéré à suivre l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Même l’Eternel s’est mis en colère contre moi à cause de vous, disant: Et toi aussi tu n’y entreras pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Josué, fils de Nun, qui te sert, y entrera; fortifie-le, car c’est lui qui mettra les enfants d’Israël en possession de ce pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Et vos petits enfants, desquels vous avez dit qu’ils seront en proie; vos enfants, dis-je, qui aujourd’hui ne savent pas ce que c’est que le bien ou le mal; ceux-là y entreront, et je leur donnerai ce pays, et ils le posséderont.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Mais vous, retournez vous-en en arrière, et allez dans le désert par le chemin de la mer Rouge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Et vous répondîtes, et me dîtes: Nous avons péché contre l’Eternel; nous monterons et nous combattrons, comme l’Eternel, notre Dieu nous a commandé; et ayant pris chacun vos armes, vous entreprîtes de monter sur la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Et l’Eternel me dit: Dis-leur: Ne montez point, et ne combattez point (car je ne suis point au milieu de vous) afin que vous ne soyez point battus par vos ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Ce que je vous rapportai, mais vous ne m’écoutâtes point, et vous vous rebellâtes contre le commandement de l’Eternel, et vous fûtes orgueilleux, et montâtes sur la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Et l’Amorrhéen, qui demeurait sur cette montagne, sortit contre vous, et vous poursuivit, comme font les abeilles, et vous battit depuis Séhir jusqu’à Horma.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Et étant retournés vous pleurâtes devant l’Eternel,; mais l’Eternel n’écouta point votre voix, et ne vous prêta point l’oreille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Ainsi vous demeurâtes en Kadès plusieurs jours, selon les jours que vous y aviez demeuré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Alors nous retournâmes en arrière, et nous allâmes, au désert par le chemin de la mer Rouge, comme l’Eternel m’avait dit, et nous tournoyâmes longtemps près de la montagne de Séhir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Et l’Eternel parla à moi, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Vous avez assez tournoyé près de cette montagne, tournez-vous vers le Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Et commande au peuple, en disant: Vous allez passer la frontière de vos frères, les enfants d’Esaü qui demeurent en Séhir, et ils auront peur de vous, mais soyez bien sur vos gardes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'N’ayez point de démêlé avec eux; car je ne vous donnerai rien de leur pays, non pas même pour y pouvoir asseoir la plante du pied, parce que j’ai donné à Esaü la montagne de Séhir en héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Vous achèterez d’eux les vivres à prix d’argent, et vous en mangerez; vous achèterez aussi d’eux l’eau à prix d’argent, et vous en boirez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Car l’Eternel ton Dieu t’a béni dans tout le travail de tes mains; il a connu le chemin que tu as tenu dans ce grand désert, et l’Eternel ton Dieu a été avec toi pendant ces quarante ans, et rien ne t’a manqué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Or nous nous détournâmes de nos frères les enfants d’Esaü, qui demeuraient en Séhir, depuis le chemin de la campagne, depuis Elath, et depuis Hetsjonguéber; et de là nous nous détournâmes et nous passâmes par le chemin du désert de Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Et l’Eternel me dit: Ne traitez point les Moabites en ennemis, et n’entrez point en guerre avec eux; car je ne te donnerai rien de leur pays en héritage; parce que j’ai donné Har en héritage aux enfants de Lot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'Les Emins y habitaient auparavant; c’était un grand peuple, et en grand nombre, et de haute stature comme les Hanakins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Et en effet ils ont été réputés pour Réphaïms comme les Hanakins, et les Moabites les appelaient Emins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Les Horiens demeuraient aussi auparavant en Séhir, mais les enfants d’Esaü les en dépossédèrent, et les détruisirent de devant eux, et ils y habitèrent en leur place, ainsi qu’a fait Israël dans le pays de son héritage que l’Eternel lui a donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Mais maintenant levez-vous, et passez le torrent de Zéred; et nous passâmes le torrent de Zéred.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Or le temps que nous avons marché depuis Kadès-barné, jusqu’à ce que nous avons eu passé le torrent de Zéred, a été de trente et huit ans, jusqu’à ce que toute cette génération-là, savoir les gens de guerre, a été consumée du milieu du camp, comme l’Eternel le leur avait juré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Aussi la main de l’Eternel a été contr’eux pour les détruire du milieu du camp, jusqu’à ce qu’il les ait consumés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Or il est arrivé qu’après que tous les hommes de guerre d’entre le peuple ont été consumés par la mort;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'L’Eternel m’a parlé et m’a dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Tu vas passer aujourd’hui la frontière de Moab, savoir Har.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'Tu approcheras vis à vis des enfants de Hammon; tu ne les traiteras point en ennemis, et tu n’auras point de démêlé avec eux; car je ne te donnerai rien du pays des enfants de Hammon en héritage, parce que je l’ai donné en héritage aux enfants de Lot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, 'Ce pays aussi a été réputé pays des Réphaïms; car les Réphaïms y habitaient auparavant, et les Hammonites les appelaient Zamzummins;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Qui étaient un peuple grand et nombreux, et de haute stature comme les Hanakins, mais l’Eternel les fit détruire de devant eux, et ils les dépossédèrent, et y habitèrent en leur place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Comme il avait fait aux enfants d’Esaü qui demeuraient en Séhir, quand il fit détruire les Horiens de devant eux; et ainsi ils les dépossédèrent, et y habitèrent en leur place jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Or quant aux Hauviens, qui demeuraient en Hatsérim, jusqu’à Gaza, ils furent détruits par les Caphtorins, qui étant sortis de Caphtor, vinrent demeurer en leur place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'L’Eternel dit aussi: Levez-vous, et partez, et passez le torrent d’Arnon; Regarde, j’ai livré entre tes mains Sihon, Roi de Hesbon Amorrhéen, avec son pays, commence d’en prendre possession, et fais-lui la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Je commencerai aujourd’hui à jeter la frayeur et la peur de toi sur les peuples qui sont sous tous les cieux, car ayant ouï parler de toi ils trembleront, et seront en angoisse à cause de ta présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Alors j’envoyai du désert de Kédémoth des messagers à Sihon, Roi de Hesbon, avec des paroles de paix, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Que je passe par ton pays et j’irai par le grand chemin, sans me détourner ni à droite ni à gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Tu me feras distribuer des vivres pour de l’argent, afin que je mange; tu me donneras de l’eau pour de l’argent, afin que je boive; seulement que j’y passe de mes pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'Ainsi que m’ont fait les enfants d’Esaü qui demeurent en Séhir, les Moabites qui demeurent à Har, jusqu’à ce que je passe le Jourdain pour entrer au pays que l’Eternel notre Dieu, nous donne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Mais Sihon, Roi de Hesbon, ne voulut point nous laisser passer par son pays, car l’Eternel ton Dieu avait endurci son esprit, et roidi son coeur, afin de le livrer entre tes mains, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Et l’Eternel me dit: Regarde, j’ai commencé de te livrer Sihon avec son pays; commence à posséder son pays, pour le tenir en héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Sihon donc sortit contre nous, lui et tout son peuple pour combattre en Jahats.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Mais l’Eternel notre Dieu nous le livra, et nous le battîmes, lui, ses enfants, et tout son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Et en ce temps-là nous prîmes toutes ses villes; et nous détruisîmes à la façon de l’interdit toutes les villes où étaient les hommes, les femmes, et les petits enfants, et nous n’y laissâmes personne de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Seulement nous pillâmes les bêtes pour nous, et le butin des villes que nous avions prises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Depuis Haroher, qui est sur le bord du torrent d’Arnon, et la ville qui est dans le torrent, jusqu’en Galaad, il n’y eut pas une ville qui pût se garantir de nous; l’Eternel notre Dieu nous les livra toutes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Seulement tu ne t’es point approché du pays des enfants de Hammon, ni d’aucun endroit qui touche le torrent de Jabbok, ni des villes de la montagne, ni d’aucun lieu que l’Eternel notre Dieu nous eût défendu de conquérir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Alors nous nous tournâmes, et nous montâmes par le chemin de Basan, et Hog le Roi de Basan sortit contre nous, avec tout son peuple pour combattre à Edréhi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Et l’Eternel me dit: Ne le crains point, car je l’ai livré entre tes mains, lui et tout son peuple, et son pays, et tu lui feras comme tu as fait a Sihon, Roi des Amorrhéens qui demeurait à Hesbon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Ainsi l’Eternel notre Dieu livra aussi entre nos mains Hog le Roi de Basan, et tout son peuple, et nous le battîmes tellement que nous ne lui laissâmes personne de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'En ce même temps nous prîmes aussi toutes ses villes; et il n’y eut point de villes que nous ne lui prissions, savoir soixante villes, tout le pays d’Argob du royaume de Hog en Basan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Toutes ces villes-là étaient closes de hautes murailles, de portes et de barres, et outre cela il y avait des villes non murées en fort grand nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Et nous les détruisîmes à la façon de l’interdit, comme nous avions fait à Sihon, Roi de Hesbon, détruisant à la façon de l’interdit, toutes les villes, les hommes, les femmes, et les petits enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Mais nous pillâmes pour nous toutes les bêtes, et le butin des villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Nous prîmes donc en ce temps-là le pays des deux Rois des Amorrhéens, qui étaient au deçà du Jourdain, depuis le torrent d’Arnon jusqu’à la montagne de Hermon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, 'Or les Sidoniens appellent Hermon, Sirjon; mais les Amorrhéens le nomment Sénir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'Toutes les villes du plat pays et tout Galaad, et tout Basan jusqu’à Salca et Edréhi, les villes du Royaume de Hog en Basan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Car Hog Roi de Basan était demeuré seul de reste des Réphaïms. Voici, son lit, qui est un lit de fer, n’est-il pas dans Rabba des enfants de Hammon? sa longueur est de neuf coudées, et sa largeur de quatre coudées, de coudée d’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'En ce temps-là donc nous possédâmes ce pays-là; et je donnai aux Rubénites et aux Gadites ce qui est depuis Haroher, qui est sur le torrent d’Arnon, et la moitié de la montagne de Galaad, avec ses villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Et je donnai à la demi-Tribu de Manassé le reste de Galaad, et tout Basan, qui était le Royaume de Hog; toute la contrée d’Argob par tout Basan, était appelée le pays des Réphaïms.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jaïr fils de Manassé prit toute la contrée d’Argob, jusqu’à la frontière des Guésuriens et des Mahacathiens, et il appela de son Nom ce pays de Basan, bourgs de Jaïr, lequel ils ont eu jusqu’à aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Je donnai aussi Galaad à Makir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Mais je donnai aux Rubénites et aux Gadites, depuis Galaad jusqu’au torrent d’Arnon, ce qui est enfermé par le torrent, et ses limites jusqu’au torrent de Jabbok, qui est la frontière des enfants de Hammon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'Et la campagne, et le Jourdain, et ses confins depuis Kinnéreth jusqu’à la mer de la campagne, qui est la mer salée, au dessous d’Asdoth de Pisgar vers l’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Or en ce temps-là je vous commandai, en disant: L’Eternel votre Dieu vous a donné ce pays pour le posséder, vous tous qui êtes vaillants, passez tous armés devant vos frères les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Que seulement vos femmes, vos petits enfants, et votre bétail, car je sais que vous avez beaucoup de bétail, demeurent dans les villes que je vous ai données.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'Jusqu’à ce que l’Eternel ait donné du repos à vos frères comme à vous, et qu’eux aussi possèdent le pays que l’Eternel votre Dieu leur va donner au delà du Jourdain; puis vous retournerez chacun en sa possession, laquelle je vous ai donnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'En ce temps-là aussi je commandai à Josué, en disant: Tes yeux ont vu tout ce que l’Eternel votre Dieu a fait à ces deux Rois; l’Eternel en fera de même à tous les Royaumes vers lesquels tu vas passer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Ne les craignez point; car l’Eternel votre Dieu combat lui-même pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'En ce même temps aussi je demandai grâce à l’Eternel, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Seigneur Eternel, tu as commencé de montrer à ton serviteur ta grandeur et ta main forte; car qui est le Dieu Fort au ciel et sur la terre qui puisse faire des oeuvres comme les tiennes, et dont la force soit comme tes forces?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Que je passe, je te prie, et que je voie le bon pays qui est au delà du Jourdain, cette bonne montagne, c’est à savoir, le Liban.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Mais l’Eternel était fort irrité contre moi à cause de vous, et ne m’exauça point; mais il me dit: C’est assez, ne me parle plus de cette affaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Monte au sommet de cette colline, et élève tes yeux vers l’Occident, et le Septentrion, vers le Midi, et l’Orient, et regarde de tes yeux; car tu ne passeras point ce Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Mais donnes-en la charge à Josué, et le fortifie, et le renforce; car c’est lui qui passera devant ce peuple, et qui les mettra en possession du pays que tu auras vu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Ainsi nous sommes demeurés en cette vallée vis à viss de Beth-Péhor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Et maintenant Israël, écoute ces statuts et ces droits que je t’enseigne, pour les faire afin que vous viviez, et que vous entriez au pays que l’Eternel le Dieu de vos pères vous donne, et que vous le possédiez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Vous n’ajouterez rien à la parole que je vous commande, et vous n’en diminuerez rien, afin de garder les commandements de l’Eternel votre Dieu lesquels je vous commande de garder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Vos yeux ont vu ce que l’Eternel a fait à cause de Bahal-Péhor; car l’Eternel ton Dieu a détruit du milieu de toi tout homme qui était allé après Bahal-Péhor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Mais vous qui vous êtes attachés à l’Eternel votre Dieu, vous êtes tous vivants aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Regardez, je vous ai enseigné les statuts et les droits, comme l’Eternel mon Dieu me l’a commandé, afin que vous fassiez ainsi au milieu du pays dans lequel vous allez entrer pour le posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Vous les garderez donc et les ferez; car c’est là votre sagesse et votre intelligence devant tous les peuples, qui entendant ces statuts, diront: Cette grande nation est le seul peuple sage et intelligent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Car quelle est la nation si grande, qui ait ses dieux près de soi, comme nous avons l’Eternel notre Dieu en tout ce pour quoi nous l’invoquons?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Et quelle est la nation si grande, qui ait des statuts et des ordonnances justes, comme est toute cette Loi que je mets aujourd’hui devant vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Seulement prends garde à toi, et garde soigneusement ton âme, afin que tu n’oublies point les choses que tes yeux ont vues, et afin que de tous les jours de ta vie elles ne sortent de ton coeur, mais que tu les enseignes à tes enfants, et aux enfants de tes enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'Le jour que tu te tins devant l’Eternel ton Dieu en Horeb, après que l’Eternel m’eut dit: Assemble le peuple, afin que je leur fasse entendre mes paroles, lesquelles ils apprendront pour me craindre tout le temps qu’ils seront vivants sur la terre, et pour les enseigner à leurs enfants;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Et que vous vous approchâtes, et vous tîntes sous la montagne. Or la montagne était toute en feu jusqu’au milieu du ciel, et il y avait des ténèbres, une nuée, et une obscurité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Et que l’Eternel vous parla du milieu du feu; vous entendiez bien une voix qui parlait, mais vous ne voyiez aucune ressemblance, vous entendiez seulement la voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Et il vous fit entendre son alliance, laquelle il vous commanda d’observer, savoir les dix paroles qu’il écrivit dans deux Tables de pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'L’Eternel me commanda aussi en ce temps-là de vous enseigner les statuts et les droits, afin que vous les fassiez au pays dans lequel vous allez passer pour le posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Vous prendrez donc bien garde à vos âmes, car vous n’avez vu aucune ressemblance au jour que l’Eternel votre Dieu vous parla en Horeb du milieu du feu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'De peur que vous ne vous corrompiez, et que vous ne vous fassiez quelque image taillée, ou quelque représentation ayant la forme d’un mâle ou d’une femelle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'Ou l’effigie d’aucune bête qui soit en la terre, ou l’effigie d’aucun oiseau ayant des ailes, qui vole par les cieux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'Ou l’effigie d’aucun reptile qui rampe sur la terre; ou l’effigie d’aucun poisson qui soit dans les eaux au dessous de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'De peur aussi qu’élevant tes yeux vers les cieux, et qu’ayant vu le soleil, la lune, et les étoiles, toute l’armée des cieux, tu ne sois poussé à te prosterner devant elles, et que tu ne les serves; vu que l’Eternel ton Dieu les a donnés en partage à tous les peuples qui sont sous tous les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Et l’Eternel vous a pris, et vous a tirés hors d’Egypte, hors du fourneau de fer; afin que vous lui soyez un peuple héréditaire, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Or l’Eternel a été irrité contre moi, à cause de vos paroles, et il a juré que je ne passerais point le Jourdain, et que je n’entrerais point en ce bon pays que l’Eternel ton Dieu te donne en héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Et de fait je m’en vais mourir en ce pays-ci sans que je passe le Jourdain; mais vous l’allez passer, et vous posséderez ce bon pays-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Donnez-vous de garde que vous n’oubliiez l’alliance de l’Eternel votre Dieu, laquelle il a traitée avec vous, et que vous ne vous fassiez quelque image taillée, ou la ressemblance de quelque chose que ce soit, selon que l’Eternel votre Dieu vous l’a défendu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Car l’Eternel ton Dieu est un feu consumant; c’est le Dieu Fort, qui est jaloux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Quand tu auras engendré des enfants, et que tu auras eu des enfants de tes enfants, et que tu seras habitué dès longtemps au pays, si alors vous vous corrompez, et que vous fassiez quelque image taillée, ou la ressemblance de quelque chose que ce soit, et si vous faites ce qui déplaît à l’Eternel votre Dieu, afin de l’irriter;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'J’appelle aujourd’hui à témoin les cieux et la terre contre vous, que certainement vous périrez aussitôt dans ce pays pour lequel posséder vous allez passer le Jourdain, et vous n’y prolongerez point vos jours; mais vous serez entièrement détruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Et l’Eternel vous dispersera entre les peuples, et il ne restera de vous qu’un petit nombre parmi les nations, chez lesquelles l’Eternel vous fera emmener.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Et vous serez là asservis à des dieux qui sont des oeuvres de main d’homme, du bois, et de la pierre, qui ne voient ni n’entendent, qui ne mangent point, et ne flairent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Mais tu chercheras de là l’Eternel ton Dieu; et tu le trouveras, parce que tu l’auras cherché de tout ton cœur, et de toute ton âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Quand tu seras dans l’angoisse, et que toutes ces choses te seront arrivées, alors, au dernier temps, tu retourneras à l’Eternel ton Dieu, et tu obéiras à sa voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Parce que l’Eternel ton Dieu est le Dieu Fort, et miséricordieux, il ne t’abandonnera point, il ne te détruira point, et il n’oubliera point l’alliance de tes pères qu’il leur a jurée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Car informe-toi des premiers temps, qui ont été avant toi, depuis le jour que Dieu a créé l’homme sur la terre, et depuis un bout des cieux jusqu’à l’autre bout, s’il a jamais été rien fait de semblable à cette grande chose, et s’il a été jamais rien entendu de semblable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Savoir, qu’un peuple ait entendu la voix de Dieu parlant du milieu du feu, comme tu l’as entendue, et qu’il soit demeuré en vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Ou que Dieu ait fait une telle épreuve, que de venir prendre à soi une nation du milieu d’une autre nation, par des épreuves, des signes et des miracles, par des batailles, et à main forte, et à bras étendu, et par des choses grandes et terribles, selon tout ce que l’Eternel notre Dieu a fait pour vous en Egypte, vous le voyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Ce qui t’a été montré, afin que tu connusses que l’Eternel est celui qui est Dieu, et qu’il n’y en a point d’autre que lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Il t’a fait entendre sa voix des cieux pour t’instruire, et il t’a montré son grand feu en la terre, et tu as entendu ses paroles du milieu du feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Et parce qu’il a aimé tes pères il a choisi leur postérité après eux, et t’a retiré d’Egypte devant sa face, par sa grande puissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'Pour chasser de devant toi des nations plus grandes et plus robustes que toi, pour t’introduire en leur pays, et pour te le donner en héritage, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Sache donc aujourd’hui, et rappelle dans ton coeur, que l’Eternel est celui qui est Dieu dans les cieux, et sur la terre, et qu’il n’y en a point d’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Garde donc ses statuts et ses commandements que je te prescris aujourd’hui, afin que tu prospères, toi, et tes enfants après toi, et que tu prolonges tes jours sur la terre que le Seigneur ton Dieu te donne pour toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Alors Moïse sépara trois villes au deçà du Jourdain vers le soleil levant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'Afin que le meurtrier qui aurait tué son prochain par mégarde, et sans l’avoir haï auparavant, s’y retirât; et que fuyant en l’une de ces villes-là, il eût sa vie sauve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Savoir, Betser au désert, en la contrée du plat pays, dans la portion des Rubénites; Ramoth en Galaad, dans la portion des Gadites; et Golan en Basan, dans celle de ceux de Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Or c’est ici la Loi que Moïse proposa aux enfants d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'Les témoignages, les statuts, et les droits que Moïse exposa aux enfants d’Israël, après qu’ils furent sortis d’Egypte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'Au deçà du Jourdain, en la vallée, qui est vis-à-vis de Beth-Péhor, au pays de Sihon, Roi des Amorrhéens, qui demeurait en Hesbon, lequel Moïse et les enfants d’Israël avaient battu après être sortis d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'Et ils possédèrent son pays avec le pays de Hog, Roi de Basan, deux Rois des Amorrhéens qui étaient au deçà du Jourdain, vers le soleil levant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'Depuis Haroher, qui est sur le bord du torrent d’Arnon, jusqu’à la montagne de Sion, qui est Hermon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'Et toute la campagne au deçà du Jourdain vers l’Orient, jusqu’à la mer de la campagne, sous Asdoth de Pisga.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Moïse donc appela tout Israël, et leur dit: Ecoute, Israël, les statuts et les droits que je te prononce aujourd’hui, vous les entendant, afin que vous les appreniez, et que vous les gardiez pour les faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'L’Eternel notre Dieu a traité alliance avec nous en Horeb.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Dieu n’a point traité cette alliance avec nos pères, mais avec nous, qui sommes ici aujourd’hui tous vivants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'L’Eternel vous parla face à face sur la montagne, du milieu du feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Je me tenais en ce temps-là entre l’Eternel et vous, pour vous rapporter la parole de l’Eternel; parce que vous aviez peur de ce feu, vous ne montâtes point sur la montagne, et le Seigneur dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Je suis l’Eternel ton Dieu, qui t’ai tiré du pays d’Egypte, de la maison de servitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Tu n’auras point d’autres dieux devant ma face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Tu ne te feras point d’image taillée, ni aucune ressemblance des choses qui sont là-haut aux cieux, ni ici bas sur la terre, ni dans les eaux qui sont sous la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Tu ne te prosterneras point devant elles, et tu ne les serviras point; car je suis l’Eternel ton Dieu, le Dieu Fort qui est jaloux, et qui punis l’iniquité des pères sur les enfants, jusqu’à la troisième et à la quatrième génération de ceux qui me haïssent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'Et qui fais miséricorde jusqu’à mille générations à ceux qui m’aiment et qui gardent mes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Tu ne prendras point le Nom de l’Eternel ton Dieu en vain; car l’Eternel ne tiendra point pour innocent celui qui aura pris son Nom en vain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Garde le jour du repos pour le sanctifier, ainsi que l’Eternel ton Dieu te l’a commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Tu travailleras six jours, et tu feras toute ton oeuvre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Mais le septième jour est le repos de l’Eternel ton Dieu; tu ne feras aucune oeuvre en ce jour-là, ni toi, ni ton fils, ni ta fille, ni ton serviteur, ni ta servante, ni ton boeuf, ni ton âne, ni aucune de tes bêtes, ni ton étranger qui est dans tes portes, afin que ton serviteur et ta servante se reposent comme toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Et qu’il te souvienne que tu as été esclave au pays d’Egypte, et que l’Eternel ton Dieu t’en a retiré à main forte, et à bras étendu; c’est pourquoi l’Eternel ton Dieu t’a commandé de garder le jour du repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Honore ton père et ta mère, comme l’Eternel ton Dieu te l’a commandé, afin que tes jours soient prolongés, et afin que tu prospères sur la terre que l’Eternel ton Dieu te donne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Tu ne tueras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Et tu ne paillarderas point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Et tu ne déroberas point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Et tu ne diras point de faux témoignage contre ton prochain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Tu ne convoiteras point la femme de ton prochain, tu ne souhaiteras point la maison de ton prochain, ni son champ, ni son serviteur, ni sa servante, ni son boeuf, ni son âne, ni aucune chose qui soit à ton prochain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'L’Eternel prononça ces paroles à toute votre assemblée sur la montagne, du milieu du feu, de la nuée et de l’obscurité, avec une voix forte, et il ne prononça rien davantage; puis il les écrivit dans deux Tables de pierre, qu’il me donna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Or il arriva qu’aussitôt que vous eûtes entendu cette voix du milieu de l’obscurité, parce que la montagne était toute en feu, vous vous approchâtes de moi, savoir tous les chefs de vos Tribus et vos anciens;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'Et vous dîtes: Voici, l’Eternel notre Dieu nous a fait voir sa gloire et sa grandeur, et nous avons entendu sa voix du milieu du feu; aujourd’hui nous avons vu que Dieu a parlé avec l’homme, et que l’homme est demeuré en vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Et maintenant pourquoi mourrions-nous? Car ce grand feu-là nous consumera; si nous entendons encore une fois la voix de l’Eternel notre Dieu, nous mourrons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Car qui est l’homme, quel qu’il soit, qui ait entendu, comme nous, la voix du Dieu vivant, parlant du milieu du feu, et qui soit demeuré en vie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Approche-toi, et écoute tout ce que l’Eternel notre Dieu dira; puis tu nous rediras tout ce que l’Eternel notre Dieu t’aura dit, nous l’entendrons, et nous le ferons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Et l’Eternel ouït la voix de vos paroles pendant que vous me parliez, et l’Eternel me dit: J’ai ouï la voix des discours de ce peuple, lesquels ils t’ont tenu; tout ce qu ils ont dit, ils l’ont bien dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Ô! s’ils avaient toujours ce même coeur pour me craindre, et pour garder tous mes commandements, afin qu’ils prospérassent, eux et leurs enfants à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Va, dis-leur: Retournez-vous-en dans vos tentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Mais toi, demeure ici avec moi, et je te dirai tous les commandements, les statuts, et les droits que tu leur enseigneras, afin qu’ils les fassent au pays que je leur donne pour le posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Vous prendrez donc garde de les faire; comme l’Eternel votre Dieu vous l’a commandé; vous ne vous en détournerez ni à droite ni à gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Vous marcherez dans toute la voie que l’Eternel votre Dieu vous a prescrite, afin que vous viviez, et que vous prospériez, et que vous prolongiez vos jours au pays que vous posséderez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Ce sont donc ici les commandements, les statuts et les droits que l’Eternel votre Dieu m’a commandé de vous enseigner, afin que vous les fassiez au pays dans lequel vous allez passer pour le posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'Afin que tu craignes l’Eternel ton Dieu, en gardant durant tous les jours de ta vie, toi, et ton fils, et le fils de ton fils, tous ces statuts et ces commandements que je te prescris, et afin que tes jours soient prolongés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Tu les écouteras donc, ô Israël! et tu prendras garde de les faire, afin que tu prospères, et que vous soyez fort multipliés au pays découlant de lait et de miel, ainsi que l’Eternel, le Dieu de tes pères, l’a dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Ecoute, Israël, l’Eternel notre Dieu est le seul Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Tu aimeras donc l’Eternel ton Dieu de tout ton coeur, de toute ton âme, et de toutes tes forces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Et ces paroles que je te commande aujourd’hui seront en ton coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Tu les enseigneras soigneusement à tes enfants, et tu t’en entretiendras quand tu demeureras en ta maison, quand tu voyageras, quand tu te coucheras, et quand tu te lèveras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Et tu les lieras pour être un signe sur tes mains, et elles seront comme des fronteaux entre tes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Tu les écriras aussi sur les poteaux de ta maison, et sur tes portes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Et il arrivera que quand l’Eternel ton Dieu t’aura fait entrer au pays qu’il a juré à tes pères, Abraham, Isaac, et Jacob, de te donner; dans les grandes et bonnes villes que tu n’as point bâties;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'Dans les maisons pleines de tous biens que tu n’as point remplies; vers les puits creusés, que tu n’as point creusés; près des vignes et des oliviers que tu n’as point plantés; tu mangeras, et tu seras rassasié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'Mais prends garde à toi, de peur que tu n’oublies l’Eternel qui t’a tiré du pays d’Egypte, de la maison de servitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Tu craindras l’Eternel ton Dieu, tu le serviras, et tu jureras par son Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Vous ne marcherez point après les autres dieux, d’entre les dieux des peuples qui seront autour de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'Car le Dieu Fort et jaloux, qui est l’Eternel ton Dieu, est au milieu de toi; de peur que la colère de l’Eternel ton Dieu ne s’enflamme contre toi, et qu’il ne t’extermine de dessus la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Vous ne tenterez point l’Eternel votre Dieu, comme vous l’avez tenté en Massa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Vous garderez soigneusement les commandements de l’Eternel votre Dieu, et ses témoignages, et ses statuts qu’il vous a commandés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Tu feras donc ce que l’Eternel approuve et trouve droit et bon, afin que tu prospères, et que tu entres au bon pays duquel l’Eternel a juré à tes pères, et que tu le possèdes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'En chassant tous tes ennemis de devant toi, comme l’Eternel en a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Quand ton enfant t’interrogera à l’avenir, en disant: Que veulent dire ces témoignages, et ces statuts, et ces droits que l’Eternel notre Dieu vous a commandés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'Alors tu diras à ton enfant: Nous avons été esclaves de Pharaon en Egypte, et l’Eternel nous a retirés d’Egypte à main forte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'Et l’Eternel a fait des signes et des miracles, grands et nuisibles en Egypte, sur Pharaon, et sur toute sa maison, comme nous l’avons vu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'Et il nous a fait sortir de là, pour nous faire entrer au pays duquel il avait juré à nos pères, de nous le donner;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Ainsi l’Eternel nous a commandé d’observer tous ces statuts, en craignant l’Eternel notre Dieu, afin que nous prospérions toujours, et que notre vie soit préservée, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Et ceci sera notre justice, savoir quand nous aurons pris garde de faire tous ces commandements devant l’Eternel notre Dieu, selon qu’il nous l’a commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Quand l’Eternel ton Dieu t’aura fait entrer au pays où tu vas entrer pour le posséder, et qu’il aura arraché de devant toi beaucoup de nations, savoir, les Héthiens, les Guirgasiens, les Amorrhéens, les Cananéens, les Phérésiens, les Héviens, et les Jébusiens, sept nations plus grandes et plus puissantes que toi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'Et que l’Eternel ton Dieu te les aura livrées: alors tu les frapperas, et tu ne manqueras point de les détruire à la façon de l’interdit; tu ne traiteras point alliance avec eux, et tu ne leur feras point de grâce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Tu ne t’allieras point par mariage avec eux; tu ne donneras point tes filles à leurs fils, et tu ne prendras point leurs filles pour tes fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Car elles détourneraient de moi tes fils, et ils serviraient d’autres dieux; ainsi la colère de l’Eternel s’enflammerait contre vous, et t’exterminerait tout aussitôt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Mais vous les traiterez en cette manière; vous démolirez leurs autels, vous briserez leurs statues, vous couperez leurs bocages, et vous brûlerez au feu leurs images taillées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Car tu es un peuple saint à l’Eternel ton Dieu; l’Eternel ton Dieu t’a choisi, afin que tu lui sois un peuple précieux d’entre tous les peuples qui sont sur l’étendue de la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Ce n’est pas que vous fussiez en plus grand nombre qu’aucun de tous les autres peuples, et qu’à cause de cela l’Eternel vous ait aimés, et vous ait choisis; car vous étiez en plus petit nombre qu’aucun de tous les autres peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'Mais c’est parce que l’Eternel vous aime, et qu’il garde le serment lequel il a fait à vos pères, que l’Eternel vous a retirés à main forte, et qu’il t’a racheté de la maison de servitude, de la main de Pharaon, Roi d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Connais donc que c’est l’Eternel ton Dieu qui est Dieu, le Dieu Fort, le fidèle, qui garde l’alliance et la gratuité jusqu’à mille générations à ceux qui l’aiment et qui gardent ses commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'Et qui rend la pareille à ceux qui le haïssent, qui la rend à chacun en face, pour les faire périr; il ne la gardera pas longtemps à celui qui le hait, il lui rendra la pareille en face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Prends donc garde aux commandements, aux statuts, et aux droits que je te commande aujourd’hui, afin que tu les fasses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Et il arrivera que si après avoir entendu ces ordonnances, vous les gardez et les faites, l’Eternel ton Dieu te gardera l’alliance et la gratuité qu’il a jurées à tes pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'Et il t’aimera, et te bénira, et te multipliera; et il bénira le fruit de ton ventre, et le fruit de ta terre, ton froment, ton moût, et ton huile, et les portées de tes vaches, et des brebis de ton troupeau, sur la terre qu’il a juré à tes pères de te donner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Tu seras béni plus que tous les peuples; et il n’y aura parmi toi ni mâle ni femelle stériles, ni entre tes bêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'L’Eternel détournera de toi toute maladie, et il ne fera point venir sur toi aucune des mauvaises langueurs d’Egypte que tu as connues, mais il les fera venir sur tous ceux qui te haïssent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Tu détruiras donc tous les peuples que l’Eternel ton Dieu te livre; ton oeil ne les épargnera point; et tu ne serviras point leurs dieux, car ce te serait un piège.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Si tu dis en ton coeur: Ces nations-là sont en plus grand nombre que moi, comment les pourrai-je déposséder?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Ne les crains point; mais qu’il te souvienne bien de ce que l’Eternel ton Dieu a fait à Pharaon, et à tous les Egyptiens;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'De ces grandes épreuves que tes yeux ont vues, des signes et des miracles, et de la main forte, et du bras étendu par lequel l’Eternel ton Dieu t’a fait sortir d’Egypte; ainsi fera l’Eternel ton Dieu à tous ces peuples desquels tu aurais peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Même l’Eternel ton Dieu enverra contr’eux des frelons, jusqu’à ce que ceux qui resteront, et ceux qui se seront cachés de devant toi soient péris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Tu ne t’effrayeras point à cause d’eux; car l’Eternel ton Dieu, le Dieu Fort, grand, et terrible, est au milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Or l’Eternel ton Dieu arrachera peu à peu ces nations de devant toi; tu n’en pourras pas d’abord venir à bout, de peur que les bêtes des champs ne se multiplient contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Mais l’Eternel ton Dieu les livrera devant toi, et les effrayera d’un grand effroi, jusqu’à ce qu’il les ait exterminées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Et il livrera leurs Rois entre tes mains, et tu feras périr leur nom de dessous les cieux; et personne ne pourra subsister devant toi, jusqu’à ce que tu les aies exterminés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Tu brûleras au feu les images taillées de leurs dieux; et tu ne convoiteras ni ne prendras pour toi l’argent ou l’or qui sera sur elles, de peur que tu n’en sois enlacé, car c’est une abomination aux yeux de l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Ainsi tu n’introduiras point d’abomination dans ta maison, afin que tu ne sois pas en interdit, comme cela, mais tu l’auras en extrême horreur; et en extrême détestation, car c’ est un interdit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Prenez garde de faire tous les commandements que je vous ordonne aujourd’hui, afin que vous viviez, et que vous soyez multipliés, et que vous entriez au pays dont l’Eternel a juré à vos pères, et que vous le possédiez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Et qu’il te souvienne de tout le chemin par lequel l’Eternel ton Dieu t’a fait marcher durant ces quarante ans dans ce désert, afin de t’humilier et de t’éprouver; pour connaître ce qui était en ton coeur, si tu garderais ses commandements, ou non.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Il t’a donc humilié, et t’a fait avoir faim, mais il t’a repu de Manne, laquelle tu n’avais point connue, ni tes pères aussi; afin de te faire connaître que l’homme ne vivra pas de pain seulement, mais que l’homme vivra de tout ce qui sort de la bouche de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Ton vêtement ne s’est point envieilli sur toi, et ton pied n’a point été foulé durant ces quarante ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Connais donc en ton coeur que l’Eternel ton Dieu te châtie, comme un homme châtie son enfant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Et garde les commandements de l’Eternel ton Dieu, pour marcher dans ses voies, et pour le craindre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Car l’Eternel ton Dieu te va faire entrer dans un bon pays, qui est un pays de torrents d’eaux, de fontaines et d’abîmes, qui naissent dans les campagnes et dans les montagnes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'Un pays de blé, d’orge, de vignes, de figuiers, et de grenadiers; un pays d’oliviers qui portent de l’huile, et un pays de miel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'Un pays où tu ne mangeras point le pain avec disette, et où rien ne te manquera; un pays dont les pierres sont du fer, et des montagnes duquel tu tailleras l’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Tu mangeras donc et tu seras rassasié, et tu béniras l’Eternel ton Dieu, à cause du bon pays qu’il t’aura donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Prends garde à toi de peur que tu n’oublies l’Eternel ton Dieu, en ne gardant point ses commandements, ses droits, et ses statuts que je te commande aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Et de peur que mangeant, et étant rassasié, et bâtissant de belles maisons, et y demeurant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'Et ton gros et menu bétail étant accru, et ton argent et ton or étant multipliés, et tout ce que tu auras étant augmenté;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'Alors ton coeur ne s’élève, et que tu n’oublies l’Eternel ton Dieu, qui ta retiré du pays d’Egypte, de la maison de servitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'Qui t’a fait marcher par ce désert grand et terrible, désert de serpents, même de serpents brûlants, et de scorpions, aride, où il n’y a point d’eau; et qui t’a fait sortir de l’eau d’un rocher qui était un pur caillou,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'Qui te donne à manger dans ce désert la Manne que tes pères n’avaient point connue, afin de t’humilier, et de t’éprouver, pour te faire enfin du bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Et que tu ne dises en ton coeur: Ma puissance et la force de ma main m’ont acquis ces facultés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Mais il te souviendra de l’Eternel ton Dieu, car c’ est lui qui te donne de la force pour acquérir des biens, afin de ratifier son alliance, qu’il a jurée à tes pères, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Mais s’il arrive que tu oublies en aucune manière l’Eternel ton Dieu, et que tu ailles après les autres dieux, que tu les serves, et que tu te prosternes devant eux, je proteste contre vous que vous périrez certainement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Vous périrez comme les nations que l’Eternel fait périr devant vous, parce que vous n’aurez point obéi à la voix de l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Ecoute, Israël, tu vas passer aujourd’hui le Jourdain, pour entrer chez des nations plus grandes et plus fortes que toi, vers des villes grandes et murées jusqu’au ciel, pour les posséder;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'Vers un peuple grand et haut; vers les enfants des Hanakins, que tu connais, et desquels tu as ouï dire: Qui est-ce qui subsistera devant les enfants de Hanak?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Sache donc aujourd’hui que l’Eternel ton Dieu, qui passe devant toi, est un feu consumant. C’est lui qui les détruira, et c’est lui qui les abaissera devant toi; tu les déposséderas, et tu les feras périr subitement comme l’Eternel te l’a dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Ne dis point en ton coeur quand l’Eternel ton Dieu les aura chassés de devant toi: C’est à cause de ma justice que l’Eternel m’a fait entrer en ce pays pour le posséder; car c’est à cause de la méchanceté de ces nations-là que l’Eternel les va chasser de devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Ce n’est point pour ta justice ni pour la droiture de ton coeur, que tu entres en leur pays pour le posséder; mais c’est pour la méchanceté de ces nations-là, que l’Eternel ton Dieu les va chasser de devant toi; et afin de ratifier la parole que l’Eternel a jurée à tes pères, Abraham, Isaac, et Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Sache donc que ce n’est point pour ta justice, que l’Eternel ton Dieu te donne ce bon pays pour le posséder; car tu es un peuple de col roide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Souviens-toi, et n’oublie pas que tu as fort irrité l’Eternel ton Dieu dans ce désert, et que depuis le jour que vous êtes sortis du pays d’Egypte, jusqu’à ce que vous êtes arrivés en ce lieu-ci, vous avez été rebelles contre l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Même en Horeb vous avez fort irrité l’Eternel; aussi l’Eternel se mit en colère contre vous, pour vous détruire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Quand je montai en la montagne pour prendre les Tables de pierre, les Tables de l’alliance que l’Eternel avait traitée avec vous, je demeurai en la montagne quarante jours et quarante nuits, sans manger de pain, et sans boire d’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Et l’Eternel me donna deux Tables de pierre, écrites du doigt de Dieu, et ce qui y était écrit c’étaient les paroles que l’Eternel avait toutes proférées lorsqu’il parlait avec vous sur la montagne, du milieu du feu, au jour de l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Et il arriva qu’au bout de quarante jours et de quarante nuits, l’Eternel me donna les deux Tables de pierre, qui sont les Tables de l’alliance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Puis l’Eternel me dit: Lève-toi, descends en hâte d’ici; car ton peuple que tu as fait sortir d’Egypte, s’est corrompu; ils se sont bien-tôt détournés de la voie que je leur avais commandée, ils se sont fait une image de fonte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'L’Eternel me parla aussi, en disant: J’ai regardé ce peuple, et voici; c’est un peuple de col roide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Laisse-moi, et je les détruirai, et j’effacerai leur nom de dessous les cieux, mais je te ferai devenir une nation plus puissante et plus grande que celle-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Je me retirai donc, et je descendis de la montagne. Or la montagne était toute en feu, et j’avais les deux Tables de l’alliance en mes deux mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Puis je regardai, et voici, vous aviez péché contre l’Eternel votre Dieu, et vous vous étiez fait un veau de fonte; vous vous étiez bien-tôt détournés de la voie que l’Eternel vous avait commandée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Alors je saisis les deux Tables, je les jetai de mes deux mains, et je les rompis devant vos yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Puis je me prosternai devant l’Eternel, durant quarante jours et quarante nuits, comme auparavant, sans manger de pain, et sans boire d’eau, à cause de tout votre péché, que vous aviez commis, en faisant ce qui est déplaisant à l’Eternel, afin de l’irriter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Car je craignais la colère et la fureur dont l’Eternel était enflammé contre vous pour vous détruire; et l’Eternel m’exauça encore cette fois-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'L’Eternel fut aussi fort irrité contre Aaron pour le détruire, mais je priai en ce même temps-là aussi pour Aaron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Puis je pris votre péché que vous aviez fait, savoir le veau, et je le brûlai au feu, je le pilai en le broyant bien, jusqu’à ce qu’il fût réduit en poudre, et j’en jetai la poudre au torrent qui descendait de la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Vous avez aussi fort irrité l’Eternel en Tabhéra et en Massa, et en Kibrothtaava.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Et quand l’Eternel vous envoya de Kadès-barné, en disant: Montez, et possédez le pays que je vous ai donné, alors vous vous rebellâtes contre le commandement de l’Eternel votre Dieu, vous ne le crûtes point, et vous n’obéîtes point à sa voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Vous avez été rebelles à l’Eternel dès le jour que je vous ai connus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Je me prosternai donc devant l’Eternel durant quarante jours et quarante nuits, durant lesquels je me prosternai, parce que l’Eternel avait dit qu’il vous détruirait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Et je priai l’Eternel, et je lui dis: Ô Seigneur Eternel! ne détruis point ton peuple, et ton héritage que tu as racheté par ta grandeur, et que tu as retiré d’Egypte, à main forte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Souviens-toi de tes serviteurs Abraham, Isaac, et Jacob; ne regarde point à la dureté de ce peuple, ni a sa méchanceté, ni à son péché;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'De peur que les habitants du pays, dont tu nous as fait sortir, ne disent: Parce que l’Eternel ne les pouvait pas faire entrer au pays dont il leur avait parlé, et parce qu’il les haïssait, il les a fait sortir d’Egypte pour les faire mourir en ce désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Cependant ils sont ton peuple et ton héritage, que tu as tirés d’Egypte par ta grande puissance, et à bras étendu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'En ce temps-là l’Eternel me dit: Taille-toi deux Tables de pierre comme les premières, et monte vers moi en la montagne, et puis tu te feras une Arche de bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Et j’écrirai sur ces Tables les paroles qui étaient sur les premières Tables que tu as rompues, et tu les mettras dans l’Arche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Ainsi je fis une Arche de bois de Sittim, et je taillai deux Tables de pierre comme les premières; et je montai en la montagne, ayant les deux Tables en ma main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Et il écrivit dans ces Tables, comme il avait écrit la première fois, les dix paroles que l’Eternel vous avait prononcées sur la montagne, du milieu du feu, au jour de l’assemblée; puis l’Eternel me les donna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Je m’en retournai, je descendis de la montagne; je mis les Tables dans l’Arche que j’avais faite, et elles y sont demeurées, comme l’Eternel me l’avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Or les enfants d’Israël partirent de Beéroth Béné-Jahakan pour aller à Moséra. Aaron mourut là, et y fut enseveli, et Eléazar son fils fut Sacrificateur en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'De là ils tirèrent vers Gudgod, et de Gudgod ils allèrent vers Jotbath, qui est un pays de torrents d’eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Or en ce temps-là l’Eternel avait séparé la Tribu de Lévi pour porter l’Arche de l’alliance de l’Eternel, pour se tenir devant la face de l’Eternel, pour le servir, et pour bénir en son Nom, jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'C’est pourquoi Lévi n’a point de portion ni d’héritage avec ses frères; mais l’Eternel est son héritage, ainsi que l’Eternel ton Dieu lui en a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Je me tins donc sur la montagne, comme la première fois; durant quarante jours et quarante nuits; et l’Eternel m’exauça encore cette fois-là; ainsi l’Eternel ne voulut point te détruire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Mais l’Eternel me dit: Lève-toi, va pour marcher devant ce peuple, afin qu’ils entrent au pays que j’ai juré à leurs pères de leur donner, et qu’ils le possèdent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Maintenant donc, ô Israël! qu’est-ce que demande de toi l’Eternel ton Dieu, sinon que tu craignes l’Eternel ton Dieu, que tu marches dans toutes ses voies, que tu l’aimes, et que tu serves l’Eternel ton Dieu de tout ton cœur, et de toute ton âme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'En gardant les commandements de l’Eternel, et ses statuts, que je te commande aujourd’hui, afin que tu prospères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Voici, les cieux, et les cieux des cieux appartiennent à l’Eternel ton Dieu; la terre aussi, et tout ce qui est en elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Mais l’Eternel a pris son bon plaisir en tes pères seulement, pour les aimer, et il vous a choisis, vous qui êtes leur postérité après eux, entre tous les peuples; comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Circoncisez donc le prépuce de votre coeur, et ne roidissez plus votre cou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Car l’Eternel votre Dieu est le Dieu des dieux, et le Seigneur des seigneurs, le Fort, le grand, le puissant, et le terrible; qui n’a point d’égard à l’apparence des personnes, et qui ne prend point de présents;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'Qui fait droit à l’orphelin et à la veuve, qui aime l’étranger, pour lui donner de quoi se nourrir, et de quoi se vêtir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Vous aimerez donc l’étranger; car vous avez été étrangers au pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Tu craindras l’Eternel ton Dieu, tu le serviras, tu t’attacheras à lui, et tu jureras par son Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'C’est lui qui est ta louange, et c’est lui qui est ton Dieu; qui a fait en ta faveur ces choses grandes et terribles que tes yeux ont vues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Tes pères sont descendus en Egypte au nombre de soixante-dix âmes; et maintenant l’Eternel ton Dieu t’a fait devenir comme les étoiles des cieux, tant tu es en grand nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Aime donc l’Eternel ton Dieu, et garde toujours ce qu’il veut que tu gardes, ses statuts, ses lois, et ses commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Et connaissez aujourd’hui que ce ne sont pas vos enfants qui ont connu, et qui ont vu le châtiment de l’Eternel votre Dieu, sa grandeur, sa main forte, et son bras étendu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'Et ses signes, et les oeuvres qu’il a faites au milieu de l’Egypte, contre Pharaon Roi d’Egypte, et contre tout son pays;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'Et ce qu’il a fait à l’armée d’Egypte, à ses chevaux et à ses chariots, quand il a fait que les eaux de la mer Rouge les ont couverts, lorsqu’ils vous poursuivaient; car l’Eternel les a détruits jusqu’à ce jour;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'Et ce qu’il a fait pour vous dans ce désert, jusqu’à ce que vous êtes arrivés en ce lieu-ci;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'Et ce qu’il a fait à Dathan, et à Abiram, enfants d’Eliab, fils de Ruben, et comment la terre ouvrit sa bouche, et les engloutit avec leurs familles et leurs tentes, et tout ce qui était en leur puissance, au milieu de tout Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Mais ce sont vos yeux qui ont vu toutes les grandes oeuvres que l’Eternel a faites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Vous garderez donc tous les commandements que je vous prescris aujourd’hui, afin que vous soyez fortifiés, et que vous entriez en possession du pays, dans lequel vous allez passer pour le posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'Et afin que vous prolongiez vos jours sur la terre que l’Eternel a juré à vos pères de leur donner, et à leur postérité, terre où coulent le lait et le miel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Car le pays où tu vas entrer pour le posséder n’ est pas comme le pays d’Egypte, duquel vous êtes sortis, où tu semais ta semence, et l’arrosais avec ton pied, comme un jardin à herbes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Mais le pays dans lequel vous allez passer pour le posséder, est un pays de montagnes et de campagnes, et il est abreuvé d’eau selon qu’il pleut des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'C’est un pays dont l’Eternel ton Dieu a soin, sur lequel l’Eternel ton Dieu a continuellement ses yeux, depuis le commencement de l’année jusqu’à la fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Il arrivera donc que si vous obéissez exactement à mes commandements, lesquels je vous prescris aujourd’hui, que vous aimiez l’Eternel votre Dieu, et que vous le serviez de tout votre coeur et de toute votre âme,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'Alors je donnerai la pluie telle qu’il faut à votre pays en sa saison, la pluie de la première et de la dernière saison, et tu recueilleras ton froment, ton vin excellent, et ton huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Je ferai croître aussi dans ton champ de l’herbe pour ton bétail; tu mangeras et tu seras rassasié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Prenez garde à vous, de peur que votre coeur ne soit séduit, et que vous ne vous détourniez, et serviez d’autres dieux, et vous prosterniez devant eux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Et que la colère de l’Eternel ne s’enflamme contre vous, et qu’il ne ferme les cieux, tellement qu’il n’y ait point de pluie; et que la terre ne donne point son fruit; et que vous ne périssiez aussitôt sur ce bon pays que l’Eternel vous donne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Mettez donc dans votre coeur et dans votre entendement ces paroles que je vous dis, et liez-les pour signe sur vos mains, et qu’elles soient pour fronteaux entre vos yeux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Et enseignez-les à vos enfants, en vous en entretenant, soit que tu te tiennes dans ta maison, soit que tu voyages, soit que tu te couches, soit que tu te lèves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Tu les écriras aussi sur les poteaux de ta maison, et sur tes portes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'Afin que vos jours et les jours de vos enfants soient multipliés sur la terre que l’Eternel a juré à vos pères de leur donner, qu’ils soient, dis-je, multipliés comme les jours des cieux sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Car si vous gardez soigneusement tous ces commandements que je vous ordonne de faire, aimant l’Eternel votre Dieu, marchant dans toutes ses voies, et vous attachant à lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'Alors l’Eternel chassera toutes ces nations-là de devant vous et vous posséderez le pays des nations qui sont plus grandes et plus puissantes que vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Tout lieu où vous aurez mis la plante de votre pied sera à vous; vos frontières seront du désert au Liban; et depuis le fleuve, qui est le fleuve d’Euphrate, jusqu’à la mer d’Occident.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Nul ne pourra se soutenir devant vous; l’Eternel votre Dieu mettra la frayeur et la terreur qu’on aura de vous, par toute la terre sur laquelle vous marcherez, ainsi qu’il vous en a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Regardez, je vous propose aujourd’hui la bénédiction et la malédiction;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'La bénédiction, si vous obéissez aux commandements de l’Eternel votre Dieu, lesquels je vous prescris aujourd’hui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'La malédiction, si vous n’obéissez point aux commandements de l’Eternel votre Dieu, et si vous vous détournez de la voie que je vous prescris aujourd’hui, pour marcher après d’autres dieux que vous n’avez point connus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Et quand l’Eternel ton Dieu t’aura fait entrer au pays où tu vas pour le posséder, tu prononceras alors les bénédictions, étant sur la montagne de Guérizim, et les malédictions, étant sur la montagne de Hébal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Ces montagnes ne sont-elles pas au delà du Jourdain, sur le chemin qui tire vers le soleil couchant, au pays des Cananéens qui demeurent en la campagne, vis-à-vis de Guilgal, près des plaines de Moré?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Car vous allez passer le Jourdain, pour entrer au pays que l’Eternel votre Dieu vous donne pour le posséder; vous le posséderez, et vous y habiterez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Vous prendrez donc garde de faire tous les statuts et les droits que je vous propose aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Ce sont ici les statuts et les droits auxquels vous prendrez garde, pour les faire, lorsque vous serez au pays que l’Eternel le Dieu de vos pères vous a donné pour le posséder, pendant tout le temps que vous vivrez sur cette terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Vous détruirez entièrement tous les lieux où ces nations, desquelles vous posséderez le pays, auront servi leurs dieux, sur les hautes montagnes, et sur les coteaux, et sous tout arbre verdoyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Vous démolirez aussi leurs autels, vous briserez leurs statues, vous brûlerez au feu leurs bocages, vous mettrez en pièces les images taillées de leurs dieux, et vous ferez périr leur nom de ce lieu-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Vous ne ferez pas ainsi à l’Eternel votre Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Mais vous le chercherez où il habitera, et vous irez au lieu que l’Eternel votre Dieu aura choisi d’entre toutes vos Tribus, pour y mettre son Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Et vous apporterez là vos holocaustes, vos sacrifices, vos dîmes, et l’oblation élevée de vos mains, vos voeux, vos offrandes volontaires, et les premiers-nés de votre gros et de votre menu bétail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Et vous mangerez là devant l’Eternel votre Dieu, et vous vous réjouirez, vous et vos familles, de toutes les choses auxquelles vous aurez mis la main, et dans lesquelles l’Eternel votre Dieu vous aura bénis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Vous ne ferez pas comme nous faisons ici aujourd’hui, chacun selon que bon lui semble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Car vous n’êtes point encore parvenus au repos, et à l’héritage que l’Eternel votre Dieu te donne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Vous passerez donc le Jourdain, et vous habiterez au pays que l’Eternel votre Dieu vous fera posséder en héritage et il vous donnera du repos de tous vos ennemis qui sont à l’environ, et vous y habiterez sûrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'Et il y aura un lieu que l’Eternel votre Dieu choisira pour y faire habiter son Nom; vous apporterez là tout ce que je vous commande, vos holocaustes, vos sacrifices, vos dîmes, l’oblation élevée de vos mains, et tout ce qu’il y aura de plus exquis dans ce que vous aurez voué à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Et vous vous réjouirez en la présence de l’Eternel votre Dieu, vous et vos fils, et vos filles, vos serviteurs, et vos servantes, et le Lévite qui est dans vos portes, car il n’a point de portion ni d’héritage avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Prends garde à toi, pour ne pas sacrifier tes holocaustes dans tous les lieux que tu verras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Mais tu offriras tes holocaustes dans le lieu que l’Eternel choisira en l’une de tes Tribus, et tu y feras tout ce que je te commande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Toutefois tu pourras tuer des bêtes et manger de leur chair selon tous les désirs de ton âme, dans quelque ville que tu demeures, selon la bénédiction de l’Eternel ton Dieu, laquelle il t’aura donnée; celui qui sera souillé et celui qui sera net, en mangeront, comme on mange du daim et du cerf.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Seulement vous ne mangerez point de sang; mais vous le répandrez sur la terre, comme de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Tu ne mangeras point dans aucune ville de ta demeure les dîmes de ton froment, ni de ton vin, ni de ton huile, ni les premiers-nés de ton gros et menu bétail, ni ce que tu auras voué, ni tes offrandes volontaires, ni l’oblation élevée de tes mains;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Mais tu les mangeras devant la face de l’Eternel ton Dieu, au lieu que l’Eternel ton Dieu aura choisi, toi, ton fils, ta fille, ton serviteur, et ta servante, et le Lévite qui est dans tes portes, et tu te réjouiras devant l’Eternel ton Dieu de ce à quoi tu auras mis la main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Garde-toi tout le temps que tu vivras sur la terre, d’abandonner le Lévite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Quand l’Eternel ton Dieu aura étendu tes limites, comme il t’en a parlé, et que tu diras: Je mangerai de la chair, parce que ton âme aura souhaité de manger de la chair, tu en mangeras selon tous les désirs de ton âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Si le lieu que l’Eternel ton Dieu aura choisi pour y mettre son Nom, est loin de toi, alors tu tueras de ton gros et menu bétail, que l’Eternel ton Dieu t’aura donné, comme je te l’ai commandé, et tu en mangeras en quelque ville que tu demeures, selon tous les désirs de ton âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Même tu en mangeras comme l’on mange du daim et du cerf. Celui qui sera souillé, et celui qui sera net en pourront manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Seulement garde-toi de manger du sang; car le sang est l’âme; et tu ne mangeras point l’âme avec la chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Tu n’en mangeras donc point, mais tu le répandras sur la terre, comme de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Tu n’en mangeras point, afin que tu prospères, toi et tes enfants après toi, quand tu auras fait ce que l’Eternel approuve et trouve droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Mais tu prendras les choses que tu auras consacrées, qui seront par devers toi, et ce que tu auras voué, et tu viendras au lieu que l’Eternel aura choisi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'Et tu offriras tes holocaustes, leur chair et leur sang sur l’autel de l’Eternel ton Dieu; mais le sang de tes autres sacrifices sera répandu vers l’autel de l’Eternel ton Dieu, et tu en mangeras la chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Garde, et écoute toutes ces paroles-ci que je te commande, afin que tu prospères, toi et tes enfants après toi à jamais, quand tu auras fait ce que l’Eternel ton Dieu approuve, et qu il trouve bon et droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Quand l’Eternel ton Dieu aura exterminé de devant toi les nations, au pays desquelles tu vas pour le posséder, et que tu l’auras possédé, et seras habitant de leur pays,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'Prends garde à toi, de peur que tu ne sois pris au piège après elles, quand elles auront été détruites de devant toi; et que tu ne recherches leurs dieux, en disant: Comme ces nations-là servaient leurs dieux, je le ferai aussi tout de même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Tu ne feras point ainsi à l’Eternel ton Dieu; car ces nations ont fait à leurs dieux tout ce qui est en abomination à l’Eternel, et qu’il hait; car même ils ont brûlé au feu leurs fils et leurs filles à leurs dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Vous prendrez garde de faire tout ce que je vous commande. Tu n’y ajouteras rien, et tu n’en diminueras rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'S’il s’élève au milieu de toi un prophète ou un songeur de songes, qui fasse devant toi quelque signe ou miracle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'Et que ce signe ou ce miracle dont il t’aura parlé, arrive, s’il te dit: Allons après d’autres dieux que tu n’as point connus, et les servons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'Tu n’écouteras point les paroles de ce prophète, ni de ce songeur de songes, car l’Eternel votre Dieu vous éprouve, pour savoir si vous aimez l’Eternel votre Dieu de tout votre coeur et de toute votre âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Vous marcherez après l’Eternel votre Dieu, vous le craindrez, vous garderez ses commandements, vous obéirez à sa voix, vous le servirez, et vous vous attacherez à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Mais on fera mourir ce prophète-là ou ce songeur de songes; parce qu’il a parlé de révolte contre l’Eternel votre Dieu, qui vous a tirés hors du pays d’Egypte, et vous a rachetés de la maison de servitude, pour vous faire sortir de la voie que l’Eternel votre Dieu vous a prescrite, afin que vous y marchiez; ainsi tu extermineras le méchant du milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Quand ton frère, fils de ta mère, ou ton fils, ou ta fille, ou ta femme bien- aimée, ou ton intime ami, qui t’est comme ton âme, t’incitera, en te disant en secret: Allons, et servons d’autres dieux, que tu n’as point connus, ni tes pères;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'D’entre les dieux des peuples qui sont autour de vous, soit près ou loin de toi, depuis un bout de la terre jusqu’à l’autre:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'N’aie point de complaisance pour lui, ne l’écoute point, que ton oeil ne l’épargne point, ne lui fais point de grâce, et ne le cache point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'Mais tu ne manqueras point de le faire mourir; ta main sera la première sur lui pour le mettre à mort, et ensuite la main de tout le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Et tu l’assommeras de pierres, et il mourra, parce qu’il a cherché, de t’éloigner de l’Eternel ton Dieu, qui t’a tiré hors du pays d’Egypte, de la maison de servitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Afin que tout Israël l’entende, et qu’il craigne, et qu’on ne fasse plus une si méchante action au milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Quand tu entendras que dans l’une de tes villes que l’Eternel ton Dieu te donne pour y habiter, on dira:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Quelques méchants garnements sont sortis du milieu de toi, qui ont incité les habitants de leur ville, en disant: Allons et servons d’autres dieux, que vous n’avez point connus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Alors tu chercheras, tu t’informeras, tu t’enquerras soigneusement; et si tu trouves que ce qu’on a dit soit véritable et certain, et qu’une telle abomination ait été faite au milieu de toi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'Tu ne manqueras pas de faire passer les habitants de cette ville au tranchant de l’épée; et tu la détruiras à la façon de l’interdit, avec tout ce qui y sera, faisant passer même ses bêtes au tranchant de l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'Et tu assembleras au milieu de sa place tout son butin, et tu brûleras entièrement au feu cette ville et tout son butin, devant l’Eternel ton Dieu; et elle sera à perpétuité un monceau de ruines, sans être jamais rebâtie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Et rien de l’interdit ne demeurera en ta main, afin que l’Eternel se départe de l’ardeur de sa colère, et qu’il te fasse miséricorde, et ait pitié de toi, et qu’il te multiplie, comme il a juré à tes pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Parce que tu auras obéi à la voix de l’Eternel ton Dieu, pour garder tous ses commandements que je te prescris aujourd’hui, afin que tu fasses ce que l’Eternel ton Dieu approuve et trouve droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Vous êtes les enfants de l’Eternel votre Dieu. Ne vous faites aucune incision, et ne vous rasez point entre les yeux pour aucun mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Car tu es un peuple saint à l’Eternel ton Dieu, et l’Eternel t’a choisi d’entre tous les peuples qui sont sur la terre, afin que tu lui sois un peuple précieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Tu ne mangeras d’aucune chose abominable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Ce sont ici les bêtes à quatre pieds dont vous mangerez, le boeuf, ce qui naît des brebis et des chèvres;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Le cerf, le daim, le buffle, le chamois, le chevreuil, le boeuf sauvage, et le chameaupard.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Vous mangerez donc d’entre les bêtes à quatre pieds, de toutes celles qui ont l’ongle divisé, le pied fourché, et qui ruminent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Mais vous ne mangerez point de celles qui ruminent seulement, ou qui ont l’ongle divisé et le pied fourché seulement; comme le chameau, le lièvre, et le lapin; car ils ruminent bien, mais ils n’ont pas l’ongle divisé; ils vous seront souillés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Le pourceau aussi, car il a bien l’ongle divisé, mais il ne rumine point; il vous sera souillé. Vous ne mangerez point de leur chair; même vous ne toucherez point à leur chair morte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Vous mangerez de ceci d’entre tout ce qui est dans les eaux; vous mangerez de tout ce qui a des nageoires et des écailles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Mais vous ne mangerez point de ce qui n’a ni nageoires ni écailles; cela vous sera souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Vous mangerez tout oiseau net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Mais ce sont ici ceux dont vous ne mangerez point; l’Aigle, l’Orfraie, le Faucon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'Le Vautour, le Milan, et l’Autour, selon leur espèce;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'Et tout Corbeau, selon son espèce;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'Le Chathuant, la Hulotte, le Coucou, et l’Epervier, selon son espèce;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'La Chouette, le Hibou, le Cygne,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'Le Cormoran, le Pélican, le Plongeon,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'La Cigogne, et le Héron selon leur espèce; et la Huppe, et la Chauvesouris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Et tout reptile qui vole vous sera souillé; on n’en mangera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Mais vous mangerez de tout ce qui vole, et qui est net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Vous ne mangerez d’aucune bête morte d’elle-même, mais tu la donneras à l’étranger qui est dans tes portes, et il la mangera, ou tu la vendras au forain; car tu es un peuple saint à l’Eternel ton Dieu. Tu ne bouilliras point le chevreau au lait de sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Tu ne manqueras point de donner la dîme de tout le rapport de ce que tu auras semé, qui sortira de ton champ, chaque année.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Et tu mangeras devant l’Eternel ton Dieu, au lieu qu’il aura choisi pour y faire habiter son Nom, les dîmes de ton froment, de ton vin, de ton huile, et les premiers-nés de ton gros et menu bétail, afin que tu apprennes à craindre toujours l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Mais quand le chemin sera si long que tu ne les puisses porter, parce que le lieu que l’Eternel ton Dieu aura choisi, pour y mettre son nom, sera trop loin de toi, lorsque l’Eternel ton Dieu t’aura béni;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'Alors tu les convertiras en argent, tu serreras l’argent en ta main; et tu iras au lieu que l’Eternel ton Dieu aura choisi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'Et tu emploieras l’argent en tout ce que ton âme souhaitera, soit gros ou menu bétail, soit vin ou cervoise, et en toute autre chose que ton âme désirera; et tu le mangeras en la présence de l’Eternel ton Dieu, et tu te réjouiras, toi et ta famille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Tu n’abandonneras point le Lévite qui est dans tes portes, parce qu’il n’a point de portion, ni d’héritage avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Au bout de la troisième année tu tireras toutes les dîmes de ton rapport de cette année-là, et tu les mettras dans tes portes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Alors le Lévite qui n’a point de portion ni d’héritage avec toi, et l’étranger, l’orphelin, et la veuve qui sont dans tes portes, viendront, et ils mangeront, et seront rassasiés; afin que l’Eternel ton Dieu te bénisse en tout l’ouvrage de ta main auquel tu t’appliqueras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'De sept en sept ans tu célébreras l’année de relâche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Et c’est ici la manière de célébrer l’année de relâche. Que tout homme ayant droit d’exiger quelque chose que ce soit, qu’il puisse exiger de son prochain, donnera relâche, et ne l’exigera point de son prochain ni de son frère, quand on aura proclamé le relâche, en l’honneur de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Tu pourras exiger de l’étranger; mais quand tu auras à faire avec ton frère, tu lui donneras du relâche;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Afin qu’il n’y ait au milieu de toi aucun pauvre; car l’Eternel te bénira certainement au pays que l’Eternel ton Dieu te donne en héritage pour le posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'Pourvu seulement que tu obéisses à la voix de l’Eternel ton Dieu, et que tu prennes garde à faire ces commandements que je te prescris aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Parce que l’Eternel ton Dieu t’aura béni comme il t’en a parlé, tu prêteras sur gages à plusieurs nations, et tu n’emprunteras point sur gages. Tu domineras sur plusieurs nations, et elles ne domineront point sur toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Quand un de tes frères sera pauvre au milieu de toi, en quelque lieu de ta demeure, dans le pays que l’Eternel ton Dieu te donne, tu n’endurciras point ton coeur, et tu ne resserreras point ta main à ton frère, qui sera pauvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'Mais tu ne manqueras pas de lui ouvrir ta main, et de lui prêter sur gages, autant qu’il en aura besoin pour son indigence, dans laquelle il se trouvera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Prends garde à toi, que tu n’aies dans on coeur quelque méchante intention, et que tu ne dises: La septième année, qui est l’année de relâche, approche; et que ton oeil étant malin contre ton frère pauvre, afin de ne lui rien donner, il ne crie à l’Eternel contre toi, et qu’il n’y ait du péché en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Tu ne manqueras point de lui donner, et ton coeur ne lui donnera point à regret; car à cause de cela l’Eternel ton Dieu te bénira dans toute ton oeuvre, et dans tout ce à quoi tu mettras la main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Car il ne manquera pas de pauvres au pays; c’est pourquoi je te commande, en disant: Ne manque point d’ouvrir ta main à ton frère, savoir, à l’affligé, et au pauvre de ton peuple en ton pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Quand quelqu’un d’entre tes frères, soit Hébreu ou Hébreue, te sera vendu, il te servira six ans; mais en la septième année tu le renverras libre de chez toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Et quand tu le renverras libre de chez toi, tu ne le renverras point vide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Tu ne manqueras pas de le charger de quelque chose de ton troupeau, de ton aire, et de ta cuve; tu lui donneras de ce en quoi l’Eternel ton Dieu t’aura béni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Et qu’il te souvienne que tu as été esclave au pays d’Egypte, et que l’Eternel ton Dieu t’en a racheté; et c’est pour cela que je te commande ceci aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Mais s’il arrive qu’il te dise: Que je ne sorte point de chez toi; parce qu’il t’aime, toi, et ta maison, et qu’il se trouve bien avec toi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'Alors tu prendras une alêne, et tu lui perceras l’oreille contre la porte, et il sera ton serviteur à toujours, tu en feras de même à ta servante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Qu’il ne te soit point fâcheux de le renvoyer libre de chez toi, car il t’a servi six ans, qui est le double du salaire du mercenaire; et l’Eternel ton Dieu te bénira en tout ce que tu feras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Tu sanctifieras à l’Eternel ton Dieu tout premier-né mâle qui naîtra de ton gros ou menu bétail. Tu ne laboureras point avec le premier-né de ta vache; et tu ne tondras point le premier-né de tes brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Tu le mangeras, toi et ta famille, chaque année en la présence de l’Eternel ton Dieu, au lieu que l’Eternel aura choisi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Mais s’il a quelque défaut, tellement qu’il soit boiteux ou aveugle, ou qu’il ait quelque autre mauvais défaut, tu ne le sacrifieras point à l’Eternel ton Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'Mais tu le mangeras au lieu de ta demeure. Celui qui est souillé, et celui qui est net en mangeront, comme on mange du daim, et du cerf.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Seulement tu n’en mangeras point le sang, mais tu le répandras sur la terre, comme de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Prends garde au mois que les épis mûrissent, et fais la Pâque à l’Eternel ton Dieu; car au mois que les épis mûrissent, l’Eternel ton Dieu t’a fait sortir de nuit hors d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Et sacrifie la Pâque à l’Eternel ton Dieu du gros et du menu bétail, au lieu que l’Eternel aura choisi pour y faire habiter son Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Tu ne mangeras point avec elle de pain levé; tu mangeras avec elle pendant sept jours des pains sans levain, pains d’affliction, parce que tu es sorti en hâte du pays d’Egypte, afin que tous les jours de ta vie tu te souviennes du jour que tu es sorti du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Il ne se verra point de levain chez toi dans toute l’étendue de ton pays pendant sept jours, et on ne gardera rien de la chair du sacrifice que tu auras fait le soir du premier jour, jusqu’au matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Tu ne pourras point sacrifier la Pâque dans tous les lieux de ta demeure que l’Eternel ton Dieu te donne;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'Mais seulement au lieu que l’Eternel ton Dieu aura choisi pour y faire habiter son Nom; c’est là que tu sacrifieras la Pâque au soir, sitôt que le soleil sera couché, précisément au temps que tu sortis d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Et l’ayant fait cuire, tu la mangeras au lieu que l’Eternel ton Dieu aura choisi; et le matin tu t’en retourneras et t’en iras dans tes tentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Pendant six jours tu mangeras des pains sans levain, et au septième jour, qui est l’assemblée solennelle à l’Eternel ton Dieu, tu ne feras aucune oeuvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Tu te compteras sept semaines; tu commenceras à compter ces sept semaines, depuis que tu auras commencé à mettre la faucille en la moisson.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Puis tu feras la fête solennelle des semaines à l’Eternel ton Dieu, en présentant l’offrande volontaire de ta main, laquelle tu donneras, selon que l’Eternel ton Dieu t’aura béni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Et tu te réjouiras en la présence de l’Eternel ton Dieu, toi, ton fils, ta fille, ton serviteur, ta servante, et le Lévite qui est dans tes portes; l’étranger, l’orphelin, et la veuve qui sont parmi toi, au lieu que l’Eternel ton Dieu aura choisi pour y faire habiter son Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Et tu te souviendras que tu as été esclave en Egypte, et tu prendras garde à observer ces statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Tu feras la fête solennelle des Tabernacles pendant sept jours, après que tu auras recueilli les revenus de ton aire et de ta cuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Et tu te réjouiras en ta fête solennelle, toi, ton fils, ta fille, ton serviteur et ta servante, le Lévite, l’étranger, l’orphelin, et la veuve qui sont dans tes portes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Tu célébreras pendant sept jours la fête solennelle à l’Eternel ton Dieu, au lieu que l’Eternel aura choisi, quand l’Eternel ton Dieu t’aura béni dans toute ta récolte, et dans tout l’ouvrage de tes mains; et tu seras dans la joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Trois fois l’an tout mâle d’entre vous se présentera devant l’Eternel ton Dieu, au lieu qu’il aura choisi; savoir à la fête solennelle des pains sans levain, et à la fête solennelle des Semaines, et à la fête solennelle des Tabernacles. Mais nul ne se présentera devant la face de l’Eternel à vide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Mais chacun donnera à proportion de ce qu’il aura, selon la bénédiction de l’Eternel ton Dieu, laquelle il t’aura donnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Tu t’établiras des juges et des prévôts dans toutes tes villes, lesquelles l’Eternel ton Dieu te donne, selon tes Tribus; afin qu’ils jugent le peuple par un jugement droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Tu ne te détourneras point de la justice et tu n’auras point égard à l’apparence des personnes. Tu ne prendras aucun présent; car le présent aveugle les yeux des sages, et corrompt les paroles des justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Tu suivras exactement la justice, afin que tu vives, et que tu possèdes le pays que l’Eternel ton Dieu te donne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Tu ne planteras point de bocage, de quelque arbre que ce soit, auprès de l’autel de l’Eternel ton Dieu, lequel tu te seras fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Tu ne te dresseras point non plus de statue; l’Eternel ton Dieu hait ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Tu ne sacrifieras à l’Eternel ton Dieu ni boeuf, ni brebis ou chèvre qui ait en soi quelque tare, ou quelque défaut; car c’est une abomination à l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Quand il se trouvera au milieu de toi dans quelqu’une de tes villes que l’Eternel ton Dieu te donne, soit homme ou femme qui fasse ce qui est odieux à l’Eternel ton Dieu, en transgressant son alliance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'Et qui aille, et serve d’autres dieux, et se prosterne devant eux, soit devant le soleil, ou devant la lune, ou devant toute l’armée du ciel, ce que je n’ai pas commandé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'Et que cela t’aura été rapporté, et que tu l’ auras appris, alors tu t’en enquerras exactement, et si tu trouves que ce qu’on a dit soit véritable, et qu’il soit certain qu’une telle abomination ait été faite en Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'Alors tu feras sortir vers tes portes cet homme ou cette femme, qui auront fait cette méchante action; cet homme, dis-je, ou cette femme, et tu les assommeras de pierres, et ils mourront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'On fera mourir sur la parole de deux ou de trois témoins, celui qui doit être puni de mort, mais on ne le fera pas mourir sur la parole d’un seul témoin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'La main des témoins sera la première sur lui pour le faire mourir, ensuite la main de tout le peuple; et ainsi tu ôteras ce méchant du milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Quand une affaire te paraîtra trop difficile, pour juger entre meurtre et meurtre, entre cause et cause, entre plaie et plaie, qui sont des affaires de procès dans tes portes; alors tu te lèveras, et tu monteras au lieu que l’Eternel ton Dieu aura choisi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'Et tu viendras aux Sacrificateurs qui sont de la race de Lévi, et au juge qui sera en ce temps-là, et tu les interrogeras, et ils te déclareront ce que porte le droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Et tu feras de point en point ce qu’ils t’auront déclaré du lieu que l’Eternel aura choisi, et tu prendras garde à faire tout ce qu’ils t’auront enseigné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Tu feras de point en point ce que dit la loi qu’ils t’auront enseignée, et selon le droit qu’ils t’auront déclaré, et tu ne te détourneras ni à droite ni à gauche, de ce qu’ils t’auront dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Mais l’homme qui agissant fièrement, n’aura point voulu obéir au Sacrificateur qui se tiendra là pour servir l’Eternel ton Dieu, ou au Juge, cet homme-là mourra, et tu ôteras ce méchant d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Afin que tout le peuple l’entende et qu’il craigne, et qu’à l’avenir il n’agisse point fièrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Quand tu seras entré au pays que l’Eternel ton Dieu te donne, et que tu le posséderas, et y demeureras, si tu dis: J’établirai un Roi sur moi, comme toutes les nations qui sont autour de moi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'Tu ne manqueras pas de t’établir pour Roi celui que l’Eternel ton Dieu aura choisi; tu t’établiras pour Roi un homme qui soit d’entre tes frères; et tu ne pourras point établir sur toi un homme, qui ne soit pas ton frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Seulement il ne fera point un amas de chevaux, et il ne ramènera point le peuple en Egypte pour faire un amas de chevaux; car l’Eternel vous a dit: Vous ne retournerez jamais plus dans ce chemin-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Il ne prendra point aussi plusieurs femmes, afin que son coeur ne se corrompe point; et il ne s’amassera point beaucoup d’argent, ni beaucoup d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Et dès qu’il sera assis sur le trône de son Royaume, il écrira pour soi dans un livre un double de cette Loi, laquelle il prendra des Sacrificateurs qui sont de la race de Lévi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Et ce livre demeurera par-devers lui, et il y lira tous les jours de sa vie; afin qu’il apprenne à craindre l’Eternel son Dieu, et à prendre garde à toutes les paroles de cette Loi, et à ces statuts, pour les faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Afin que son coeur ne s’élève point par dessus ses frères, et qu’il ne se détourne point de ce commandement ni à droite ni à gauche; et afin qu’il prolonge ses jours en son règne, lui et ses fils, au milieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Les Sacrificateurs qui sont de la race de Lévi, même toute la Tribu de Lévi, n’auront point de part ni d’héritage avec le reste d’Israël, mais ils mangeront les sacrifices de l’Eternel faits par feu, et son héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Ils n’auront donc point d’héritage entre leurs frères. L’Eternel est leur héritage, comme il leur en a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Or c’est ici le droit que les Sacrificateurs prendront du peuple, c’est-à- dire de ceux qui offriront quelque sacrifice, soit boeuf, ou brebis, ou chèvre, c’est qu’on donnera au Sacrificateur l’épaule, les mâchoires, et le ventre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Tu leur donneras les prémices de ton froment, de ton vin et de ton huile, et les prémices de la toison de tes brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Car l’Eternel ton Dieu l’a choisi d’entre toutes les Tribus, afin qu’il assiste pour faire le service au nom de l’Eternel, lui et ses fils, à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Or quand le Lévite viendra de quelque lieu de ta demeure, de quelque endroit que ce soit d’Israël où il fasse son séjour, et qu’il viendra selon tout le désir de son âme, au lieu que l’Eternel aura choisi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'Il fera le service au nom de l’Eternel son Dieu, comme tous ses frères Lévites, qui assistent en la présence de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'Ils mangeront une égale portion avec les autres, outre ce que chacun pourra avoir de ce qu’il aura vendu aux familles de ses pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Quand tu seras entré au pays que l’Eternel ton Dieu te donne, tu n’apprendras point à faire selon les abominations de ces nations-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Il ne se trouvera personne au milieu de toi qui fasse passer par le feu son fils ou sa fille, ni de devin qui se mêle de deviner, ni de pronostiqueur de temps, ni aucun qui use d’augures, ni aucun sorcier;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'Ni d’enchanteur qui use d’enchantements, ni d’homme qui consulte l’esprit de python, ni de diseur de bonne aventure, ni aucun qui interroge les morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Car quiconque fait ces choses est en abomination à l’Eternel; et à cause de ces abominations l’Eternel ton Dieu chasse ces nations-là de devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Tu agiras en intégrité avec l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Car ces nations-là dont tu vas posséder le pays, écoutent les pronostiqueurs, et les devins; mais quant à toi, l’Eternel ton Dieu ne t’a point permis d’agir de la sorte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'L’Eternel ton Dieu te suscitera un Prophète comme moi d’entre tes frères; vous l’écouterez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Selon tout ce que tu as demandé à l’Eternel ton Dieu en Horeb, au jour de l’assemblée, en disant: Que je n’entende plus la voix de l’Eternel mon Dieu; et que je ne voie plus ce grand feu, de peur que je ne meure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Alors l’Eternel me dit: Ils ont bien dit ce qu’ils ont dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Je leur susciterai un Prophète comme toi d’entre leurs frères, et je mettrai mes paroles en sa bouche, et il leur dira tout ce que je lui aurai commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Et il arrivera que quiconque n’écoutera pas mes paroles, lesquelles il aura dites en mon Nom, je lui en demanderai compte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Mais le Prophète qui aura agi si fièrement que de dire quelque chose en mon Nom, que je ne lui aurai point commandé de dire, ou qui aura parlé au nom des autres dieux, ce Prophète-là mourra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Que si tu dis en ton coeur: Comment connaîtrons-nous la parole que l’Eternel n’aura point dite?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Quand ce Prophète-là aura parlé au Nom de l’Eternel, et que la chose qu’il aura prédite ne sera point, ni n’arrivera point, cette parole sera celle que l’Eternel ne lui a point dite; mais le Prophète l’a dite par fierté; ainsi n’aie point peur de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Quand l’Eternel ton Dieu aura exterminé les nations desquelles l’Eternel ton Dieu te donne le pays, et que tu posséderas leur pays, et demeureras dans leurs villes, et dans leurs maisons;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'Alors tu sépareras trois villes au milieu du pays que l’Eternel ton Dieu te donne pour le posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Tu dresseras le chemin, et tu diviseras en trois parties les contrées de ton pays, que l’Eternel ton Dieu te donnera en héritage; et ce sera afin que tout meurtrier s’y enfuie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Or voici comment on procédera envers le meurtrier qui se sera retiré là, afin qu’il vive. Celui qui aura frappé son prochain par mégarde, et sans l’avoir haï auparavant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'Comme si quelqu’un étant allé avec son prochain dans une forêt pour couper du bois, et avançant sa main avec la cognée pour couper du bois, il arrive que le fer échappe hors du manche, et rencontre tellement son prochain, qu’il en meure; il s’enfuira dans une de ces villes-là, afin qu’il vive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'De peur que celui qui a le droit de venger le sang ne poursuive le meurtrier, pendant que son coeur est échauffé, et qu’il ne l’atteigne, si le chemin est trop long, et ne le frappe à mort, quoiqu’il ne fût pas digne de mort, parce qu’il ne haïssait pas son prochain auparavant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'C’est pourquoi je te commande, en disant: Sépare-toi trois villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Que si l’Eternel ton Dieu étend tes limites, comme il l’a juré à tes pères, et qu’il te donne tout le pays qu’il a promis de donner à tes pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'Pourvu que tu prennes garde à faire tous ces commandements que je te prescris aujourd’hui, afin que tu aimes l’Eternel ton Dieu, et que tu marches toujours dans ses voies; alors tu t’ajouteras encore trois villes, outre ces trois-là;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'Afin que le sang de celui qui est innocent ne soit pas répandu au milieu de ton pays, que l’Eternel ton Dieu te donne en héritage, et que tu ne sois pas coupable de meurtre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Mais quand un homme qui haïra son prochain, lui aura dressé des embûches, et se sera élevé contre lui, et l’aura frappé à mort, et qu’il s’en sera fui dans l’une de ces villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'Alors les Anciens de sa ville enverront et le tireront de là, et le livreront entre les mains de celui qui a le droit de venger le sang, afin qu’il meure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Ton oeil ne l’épargnera point; mais tu vengeras en Israël le sang de l’innocent; et tu prospéreras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Tu ne transporteras point les bornes de ton prochain que les prédécesseurs auront plantées dans l’héritage que tu posséderas, au pays que l’Eternel ton Dieu te donne pour le posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Un témoin seul ne sera point valable contre un homme, en quelque crime et péché que ce soit, en quelque péché qu’on ait commis; mais sur la parole de deux ou de trois témoins la chose sera valable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Quand un faux témoin s’élèvera contre quelqu’un, pour déposer contre lui le crime de révolte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'Alors ces deux hommes-là qui auront contestation entr’eux, comparaîtront devant l’Eternel, en la présence des Sacrificateurs et des Juges qui seront en ce temps-là;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Et les Juges s’informeront exactement; et s’il se trouve que ce témoin soit un faux témoin, qui ait déposé faussement contre son frère;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'Tu lui feras comme il avait dessein de faire à son frère; et ainsi tu ôteras le méchant du milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Et les autres qui entendront cela craindront, et à l’avenir ils ne feront plus de méchante action comme celle-là, au milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Ton oeil ne l’épargnera point; mais il y aura vie pour vie, oeil pour oeil, dent pour dent, main pour main, pied pour pied.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Quand tu iras à la guerre contre tes ennemis, et que tu verras des chevaux et des chariots, et un peuple plus grand que toi, n’aie point peur d’eux, car l’Eternel ton Dieu qui t’a fait monter hors du pays d’Egypte, est avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Et quand il faudra s’approcher pour combattre, le Sacrificateur s’avancera, et parlera au peuple,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'Et leur dira: Ecoute Israël: Vous vous approchez aujourd’hui pour combattre vos ennemis; que votre coeur ne soit point lâche, ne craignez point, ne soyez point épouvantés, ne soyez point effrayés à cause d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Car l’Eternel votre Dieu marche avec vous, pour combattre pour vous contre vos ennemis, et pour vous conserver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Alors les Officiers parleront au peuple, en disant: Qui est celui qui a bâti une maison neuve, et ne l’a point dédiée? qu’il s’en aille, et s’en retourne en sa maison, de peur qu’il ne meure en la bataille, et qu’un autre ne la dédie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Et qui est celui qui a planté une vigne, et n’en a point encore cueilli le fruit? qu’il s’en aille, et s’en retourne en sa maison, de peur qu’il ne meure en la bataille, et qu’un autre n’en cueille le fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Et qui est celui qui a fiancé une femme, et ne l’a point épousée? qu’il s’en aille, et s’en retourne en sa maison, de peur qu’il ne meure en la bataille, et qu’un autre ne l’épouse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Et les officiers continueront à parler au peuple, et diront: Si quelqu’un est timide et lâche, qu’il s’en aille, et s’en retourne en sa maison, de peur que le coeur de ses frères ne se fonde comme le sien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Et aussitôt que les officiers auront achevé de parler au peuple, ils rangeront les chefs des bandes à la tête de chaque troupe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Quand tu t’approcheras d’une ville pour lui faire la guerre, tu lui présenteras la paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Et si elle te fait une réponse de paix, et t’ouvre les portes, tout le peuple qui sera trouvé dedans, te sera tributaire, et sujet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Mais si elle ne traite pas avec toi, et qu’elle fasse la guerre contre toi, alors tu mettras le siège contr’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'Et quand l’Eternel ton Dieu l’aura livrée entre tes mains, tu feras passer au fil de l’épée tous les hommes qui s’y trouveront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Réservant seulement les femmes, et les petits enfants. Et quant aux bêtes, et tout ce qui sera dans la ville, savoir tout son butin, tu le pilleras pour toi; et tu mangeras le butin de tes ennemis, que l’Eternel ton Dieu t’aura donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Tu en feras ainsi à toutes les villes qui sont fort éloignées de toi; lesquelles ne sont point des villes de ces nations-ci;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Mais tu ne laisseras vivre personne qui soit des villes de ces peuples que l’Eternel ton Dieu te donne en héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Car tu ne manqueras point de les détruire à la façon de l’interdit, savoir les Héthiens, les Amorrhéens, les Cananéens, les Phérésiens, les Héviens, les Jébusiens, comme l’Eternel ton Dieu te l’a commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'Afin qu’ils ne vous apprennent point à faire selon toutes les abominations qu’ils ont faites à leurs dieux, et que vous ne péchiez point contre l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Quand tu tiendras une ville assiégée durant plusieurs jours, en la battant pour la prendre, tu ne détruiras point ses arbres à coups de cognée, parce que tu en pourras manger; c’est pourquoi tu ne les couperas point; car l’arbre des champs est-il un homme, pour entrer dans la forteresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Mais seulement tu détruiras et tu couperas les arbres que tu connaîtras n’être point des arbres fruitiers; et tu en bâtiras des forts contre la ville qui te fait la guerre, jusqu’à ce qu’elle soit subjuguée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Quand il se trouvera sur la terre que l’Eternel ton Dieu te donne pour la posséder, un homme qui a été tué, étendu dans un champ, et qu’on ne saura pas qui l’aura tué;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'Alors tes Anciens et tes Juges sortiront, et mesureront depuis l’homme qui aura été tué, jusqu’aux villes qui sont tout autour de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Puis les Anciens de la ville la plus proche de l’homme qui aura été tué, prendront une jeune vache du troupeau, de laquelle on ne se soit point servi, et qui n’ait point tiré étant sous le joug;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'Et les Anciens de cette ville-là feront descendre la jeune vache en une vallée rude, dans laquelle on ne laboure, ni ne sème, et là ils couperont le cou à la jeune vache dans la vallée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Et les Sacrificateurs, fils de Lévi, s’approcheront; car l’Eternel ton Dieu les a choisis pour faire son service, et pour bénir au Nom de l’Eternel; et afin qu’à leur parole toute cause et toute plaie soit définie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Et tous les Anciens de cette ville-là, qui seront les plus près de l’homme qui aura été tué, laveront leurs mains sur la jeune vache, à laquelle on aura coupé le cou dans la vallée,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'Et prenant la parole ils diront: Nos mains n’ont point répandu ce sang; nos yeux aussi ne l’ont point vu répandre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Ô Eternel! Sois propice à ton peuple d’Israël que tu as racheté, et ne lui impute point le sang innocent qui a été répandu au milieu de ton peuple d’Israël; et le meurtre sera expié pour eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Et tu ôteras le sang innocent du milieu de toi, parce que tu auras fait ce que l’Eternel approuve et trouve juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Quand tu seras allé à la guerre contre tes ennemis, et que l’Eternel ton Dieu les aura livrés entre tes mains et que tu en auras emmené des prisonniers;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'Si tu vois entre les prisonniers quelque belle femme, et qu’ayant conçu pour elle de l’affection, tu veuilles la prendre pour ta femme;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'Alors tu la mèneras en ta maison, et elle rasera sa tête, et fera ses ongles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'Et elle ôtera de dessus soi les habits qu’elle portait lorsqu’elle a été faite prisonnière; et elle demeurera en ta maison, et pleurera son père et sa mère un mois durant; puis tu viendras vers elle, et tu seras son mari, et elle sera ta femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'S’il arrive qu’elle ne te plaise plus, tu la renverras selon sa volonté, mais tu ne la pourras point vendre pour de l’argent, ni en faire aucun trafic parce que tu l’auras humiliée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Quand un homme aura deux femmes, l’une aimée, et l’autre haïe, et qu’elles lui auront enfanté des enfants, tant celle qui est aimée, que celle qui est haïe, et que le fils aîné soit de celle qui est haïe;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'Lorsque le jour viendra qu’il partagera à ses enfants ce qu’il aura, alors il ne pourra pas faire aîné le fils de celle qui est aimée, préférablement au fils de celle qui est haïe, lequel est né le premier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Mais il reconnaîtra le fils de celle qui est haïe pour son premier-né, en lui donnant la portion de deux, de tout ce qui se trouvera lui appartenir; car il est le commencement de sa vigueur; le droit d’aînesse lui appartient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Quand un homme aura un enfant méchant et rebelle, n’obéissant point à la voix de son père, ni à la voix de sa mère, et qu’ils l’auront châtié, et que, nonobstant cela, il ne les écoute point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'Alors le père et la mère le prendront, et le mèneront aux Anciens de sa ville, et à la porte de son lieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'Et ils diront aux Anciens de sa ville: C’est ici notre fils qui est méchant et rebelle, il n’obéit point à notre voix, il est gourmand et ivrogne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Et tous les gens de la ville le lapideront, et il mourra; et ainsi tu ôteras le méchant du milieu de toi, afin que tout Israël l’entende, et qu’il craigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Quand un homme aura commis quelque péché, digne de mort, et qu’on le fera mourir, et que tu le pendras à un bois;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'Son corps mort ne demeurera point la nuit sur le bois, mais tu ne manqueras point de l’ensevelir, le même jour, car celui qui est pendu est malédiction de Dieu; c’est pourquoi tu ne souilleras point la terre que l’Eternel ton Dieu te donne en héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Quand tu verras le boeuf ou la brebis ou la chèvre de ton frère égarés tu ne te cacheras point d’eux; et tu ne manqueras point de les ramener à ton frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Que si ton frère ne demeure point près de toi, ou que tu ne le connaisses point, tu les retireras même dans ta maison, et ils seront avec toi, jusqu’à ce que ton frère les cherche, et alors tu les lui rendras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Tu feras la même chose de son âne, et tu feras ainsi de son vêtement, et tu feras ainsi de toute chose que ton frère aura perdue, et que tu auras trouvée, ayant été égarée, tu ne t’en pourras pas cacher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Si tu vois l’âne de ton frère, ou son boeuf tombés dans le chemin, tu ne te cacheras point d’eux, et tu ne manqueras point de les relever conjointement avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'La femme ne portera point l’habit d’un homme, ni l’homme ne se vêtira point d’un habit de femme; car quiconque fait de telles choses est en abomination à l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Quand tu rencontreras dans un chemin, sur quelque arbre, ou sur la terre, un nid d’oiseaux, ayant des petits ou des oeufs, et la mère couvant les petits ou les oeufs, tu ne prendras point la mère avec les petits;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Mais tu ne manqueras point de laisser aller la mère, et tu prendras les petits pour toi; afin que tu prospères, et que tu prolonges tes jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Quand tu bâtiras une maison neuve, tu feras des défenses tout autour de ton toit, afin que tu ne rendes point ta maison coupable de sang, si quelqu’un tombait de là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Tu ne sèmeras point dans ta vigne diverses sortes de grains; de peur que le tout, savoir les grains, que tu auras semés, et le rapport de ta vigne, ne soit souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Tu ne laboureras point avec un âne et un boeuf accouplés ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Tu ne te vêtiras point d’un drap tissu de diverses matières, c’est-à-dire, de laine et de lin ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Tu te feras des bandes aux quatre pans de ta robe, de laquelle tu te couvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Quand quelqu’un aura pris une femme, et qu’après être venu vers elle, il la haïsse,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'Et qu’il lui impute quelque chose qui donne occasion de parler en répandant contr’elle quelque mauvais bruit, et disant: J’ai pris cette femme, et quand je me suis approché d’elle, je n’ai point trouvé en elle sa virginité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'Alors le père et la mère de la jeune fille prendront et produiront les marques de sa virginité devant les Anciens de la ville, à la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'Et le père de la jeune fille dira aux Anciens: J’ai donné ma fille à cet homme pour femme, et il l’a prise en haine;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'Et voici, il lui a imposé une chose qui donne occasion de parler, disant: Je n’ai point trouvé que ta fille fût vierge; cependant voici les marques de la virginité de ma fille, et ils étendront le drap devant les Anciens de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Alors les Anciens de cette ville-là prendront le mari, et le châtieront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'Et parce qu’il aura répandu un mauvais bruit contre une vierge d’Israël, ils le condamneront à cent pièces d’argent, lesquelles ils donneront au père de la jeune fille; et elle sera pour femme à cet homme-là, et il ne la pourra pas renvoyer, tant qu’il vivra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Mais si ce qu’il a dit, que la jeune fille ne se soit point trouvée vierge, est véritable;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'Alors ils feront sortir la jeune fille à la porte de la maison de son père, et les gens de sa ville l’assommeront de pierres et elle mourra; car elle a commis une infamie en Israël, en paillardant dans la maison de son père; et ainsi tu ôteras le mal du milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Quand un homme aura été trouvé couché avec une femme mariée, ils mourront tous deux, l’homme qui a couché avec la femme, et la femme aussi; et tu ôteras le mal d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Quand une jeune fille vierge sera fiancée à un homme, et que quelqu’un l’ayant trouvée dans la ville, aura couché avec elle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'Vous les ferez sortir tous deux à la porte de la ville, et vous les assommerez de pierres, et ils mourront; la jeune fille, parce qu’elle n’a point crié étant dans la ville; et l’homme, parce qu’il a violé la femme de son prochain; et tu ôteras le mal du milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Que si quelqu’un trouve aux champs une jeune fille fiancée, et que lui faisant violence, il couche avec elle, alors l’homme qui aura couché avec elle, mourra lui seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Mais tu ne feras rien à la jeune fille; la jeune fille n’a point commis en cela de péché digne de mort; car il en est de ce cas comme si quelqu’un s’élevait contre son prochain, et lui ôtait la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Parce que l’ayant trouvée aux champs, la jeune fille fiancée a crié, et personne ne l’a délivrée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Quand quelqu’un trouvera une jeune fille vierge non fiancée, et la prendra, et couchera avec elle, et qu’ils soient trouvés sur le fait;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'L’homme qui aura couché avec elle, donnera au père de la jeune fille cinquante pièces d’argent, et elle lui sera pour femme, parce qu’il l’a humiliée; il ne la pourra point laisser, tant qu’il vivra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Nul ne prendra la femme de son père, ni ne découvrira le pan de la robe de son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Celui qui est Eunuque, soit pour avoir été froissé, soit pour avoir été taillé, n’entrera point dans l’assemblée de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Le bâtard n’entrera point dans l’assemblée de l’Eternel, même sa dixième génération n’entrera point dans l’assemblée de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Le Hammonite et le Moabite n’entreront point dans l’assemblée de l’Eternel; même leur dixième génération n’entrera point dans l’assemblée de l’Eternel à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Parce qu’ils ne sont point venus au-devant de vous avec du pain et de l’eau dans le chemin, lorsque vous sortiez d’Egypte; et parce aussi qu’ils ont loué, à prix d’argent contre vous, Balaam fils de Béhor, de la ville de Péthor en Mésopotamie, pour vous maudire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Mais l’Eternel ton Dieu ne voulut point écouter Balaam, mais l’Éternel ton Dieu convertit la malédiction en bénédiction; parce que l’Eternel ton Dieu t’aime.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Tu ne chercheras jamais, tant que tu vivras, leur paix, ni leur bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Tu n’auras point en abomination l’Iduméen, car il est ton frère; tu n’auras point en abomination l’Egyptien, car tu as été étranger en son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Les enfants qui leur naîtront en la troisième génération, entreront dans l’assemblée de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Quand tu marcheras en armes contre tes ennemis, garde-toi de toute chose mauvaise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'S’il y a quelqu’un d’entre vous qui ne soit point net, pour quelque accident qui lui soit arrivé de nuit, alors il sortira du camp, et il n’entrera point dans le camp;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Et sur le soir il se lavera d’eau, et sitôt que le soleil sera couché, il rentrera dans le camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Tu auras quelque endroit hors du camp, et tu sortiras là dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Et tu auras un pic entre tes ustensiles; et, quand tu voudras t’asseoir dehors, tu creuseras avec ce pic, puis tu t’en retourneras après avoir couvert ce qui sera sorti de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Car l’Eternel ton Dieu marche au milieu de ton camp pour te délivrer, et pour livrer tes ennemis devant toi; que tout ton camp donc soit saint, afin qu’il ne voie en toi aucune impureté, et qu’il ne se détourne de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Tu ne livreras point à son maître le serviteur qui se sera sauvé chez toi d’avec son maître;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Mais il demeurera avec toi au milieu de toi, dans le lieu qu’il aura choisi en l’une de tes villes, là où bon lui semblera; tu ne le chagrineras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Qu’il n’y ait point entre les filles d’Israël aucune prostituée, ni entre les fils d’Israël aucun prostitué à paillardise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Tu n’apporteras point dans la maison de l’Eternel ton Dieu pour aucun voeu, le salaire d’une paillarde, ni le prix d’un chien; car ces deux choses sont en abomination devant l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Tu ne prêteras point à usure à ton frère, soit à usure d’argent, soit à usure de vivres, soit à usure de quelque autre chose que ce soit qu’on prête à usure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Tu prêteras bien à usure à l’étranger, mais tu ne prêteras point à usure à ton frère; afin que l’Eternel ton Dieu te bénisse en tout ce à quoi tu mettras la main, dans le pays où tu vas entrer pour le posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Quand tu auras voué un voeu à l’Eternel ton Dieu, tu ne tarderas point à l’accomplir; car l’Eternel ton Dieu ne manquerait point de te le redemander; ainsi il y aurait du péché en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Mais quand tu t’abstiendras de vouer, il n’y aura pas pour cela de péché en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Tu prendras garde de faire ce que tu auras proféré de ta bouche, ainsi que tu l’auras voué de ton bon gré à l’Eternel ton Dieu, ce que tu auras, dis-je, prononcé de ta bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Quand tu entreras dans la vigne de ton prochain, tu pourras bien manger des raisins selon ton appétit, jusqu’à en être rassasié; mais tu n’en mettras point dans ton vaisseau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Quand tu entreras dans les blés de ton prochain, tu pourras bien arracher des épis avec ta main; mais tu ne mettras point la faucille dans les blés de ton prochain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Quand quelqu’un aura pris une femme, et se sera marié avec elle, s’il arrive qu’elle ne trouve pas grâce devant ses yeux, à cause qu’il aura trouvé en elle quelque chose de malhonnête, il lui donnera par écrit la lettre de divorce, et la lui ayant mise entre les mains, il la renverra hors de sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'Et quand elle sera sortie de sa maison, et que s’en étant allée, elle se sera mariée à un autre mari;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'Si ce dernier mari la prend en haine, et lui donne par écrit la lettre de divorce, et la lui met en main, et la renvoie de sa maison, ou que ce dernier mari qui l’avait prise pour sa femme, meure;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'Alors son premier mari qui l’avait renvoyée, ne pourra pas la reprendre pour sa femme, après avoir été cause qu’elle s’est souillée; car c’est une abomination devant l’Eternel; ainsi tu ne chargeras point de péché le pays que l’Eternel ton Dieu te donne en héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Quand quelqu’un se sera nouvellement marié, il n’ira point à la guerre, et on ne lui imposera aucune charge; mais il en sera exempt dans sa maison pendant un an, et sera en joie à la femme qu’il aura prise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'On ne prendra point pour gage les deux meules, non pas même la meule de dessus, parce qu’on prendrait pour gage la vie de son prochain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Quand on trouvera quelqu’un qui aura commis un larcin de la personne de quelqu’un de ses frères des enfants d’Israël, et qui en aura fait trafic, et l’aura vendu; ce larron-là mourra, et tu ôteras le mal du milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Prends garde à la plaie de la lèpre, afin que tu gardes soigneusement et fasses tout ce que les Sacrificateurs qui sont de la race de Lévi, vous enseigneront; vous prendrez garde à faire selon ce que je leur ai commandé..');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Qu’il te souvienne de ce que l’Eternel ton Dieu fit à Marie, en chemin après que vous fûtes sortis d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Quand tu auras droit d’exiger de ton prochain quelque chose qui te sera dû, tu n’entreras point dans sa maison pour prendre son gage;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Mais tu te tiendras dehors, et l’homme duquel tu exiges la dette, t’apportera le gage dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Et si l’homme est pauvre, tu ne te coucheras point ayant encore son gage;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Mais tu ne manqueras point de lui rendre le gage dès que le soleil sera couché, afin qu’il couche dans son vêtement, et qu’il te bénisse; et cela te sera imputé à justice devant l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Tu ne feras point de tort au mercenaire pauvre et indigent d’entre tes frères, ou d’entre les étrangers qui demeurent en ton pays, dans quelqu’une de tes demeures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Tu lui donneras son salaire le jour même qu’il aura travaillé, avant que le soleil se couche, car il est pauvre, et c’est à quoi son âme s’attend; afin qu’il ne crie point contre toi à l’Eternel, et que tu ne pèches point en cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'On ne fera point mourir les pères pour les enfants; on ne fera point aussi mourir les enfants pour les pères; mais on fera mourir chacun pour son péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Tu ne feras point d’injustice à l’étranger ni à l’orphelin, et tu ne prendras point pour gage le vêtement de la veuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Et il te souviendra que tu as été esclave en Egypte; et que l’Eternel ton Dieu t’a racheté de là; c’est pourquoi je te commande de faire ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Quand tu feras ta moisson dans ton champ, et que tu auras oublié dans ton champ quelque poignée d’épis, tu n’y retourneras point pour la prendre; mais cela sera pour l’étranger, pour l’orphelin, et pour la veuve; afin que l’Eternel ton Dieu te bénisse en toutes les oeuvres de tes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Quand tu battras tes oliviers, tu n’y retourneras point pour rechercher branche après branche; mais ce qui sera demeuré sera pour l’étranger, pour l’orphelin, et pour la veuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Quand tu vendangeras ta vigne, tu ne grappilleras point les raisins qui seront demeurés après toi; mais cela sera pour l’étranger, pour l’orphelin, et pour la veuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Et il te souviendra que tu as été esclave au pays d’Egypte; c’est pourquoi je te commande de faire ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Quand il y aura eu un différend entre quelques-uns, et qu’ils viendront en jugement afin qu’on les juge, on justifiera le juste, et on condamnera le méchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Si le méchant a mérité d’être battu, le juge le fera jeter par terre, et battre devant soi par un certain nombre de coups, selon l’exigence de son crime.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Il le fera donc battre de quarante coups, et non de davantage, de peur que s’il continue à le battre au delà de ces coups, la plaie ne soit excessive, et que ton frère ne soit traité trop indignement devant tes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Tu n’emmuselleras point ton boeuf, lorsqu’il foule le grain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Quand il y aura des frères demeurant ensemble, et que l’un d’entr’eux viendra à mourir sans enfants, alors la femme du mort ne se mariera point dehors à un étranger; mais son beau-frère viendra vers elle, et la prendra pour femme, et l’épousera comme étant son beau-frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Et le premier-né qu’elle enfantera succédera en la place du frère mort, et portera son nom, afin que son nom ne soit point effacé d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Que s’il ne plaît pas à cet homme-là de prendre sa belle-soeur, alors sa belle-soeur montera à la porte vers les Anciens, et dira: Mon beau-frère refuse de relever le nom de son frère en Israël, et ne veut point m’épouser par droit de beau-frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Alors les Anciens de sa ville l’appelleront, et lui parleront; et s’il demeure ferme, et qu’il dise: Je ne veux point la prendre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'Alors sa belle-soeur s’approchera de lui devant les Anciens, et lui ôtera son soulier du pied, et lui crachera au visage, et prenant la parole, elle dira: C’est ainsi qu’on fera à l’homme qui n’édifiera point la maison de son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Et son nom sera appelé en Israël, la maison de celui à qui on a déchaussé le soulier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Quand quelques-uns auront querelle ensemble l’un contre l’autre, si la femme de l’un s’approche pour délivrer son mari de celui qui le bat, et qu’avançant sa main elle l’empoigne par ses parties honteuses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'Alors tu lui couperas la main; et ton oeil ne l’épargnera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Tu n’auras point en ton sachet deux sortes de pierres à peser, une grande et une petite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Il n’y aura point aussi dans ta maison deux sortes d’Epha, un grand et un petit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Mais tu auras les pierres à peser exactes et justes; tu auras aussi un Epha exact et juste, afin que tes jours soient prolongés sur la terre que l’Eternel ton Dieu te donne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Car quiconque fait ces choses-là, quiconque mit une injustice, est en abomination à l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Qu’il te souvienne de ce qu’Hamalec t’a fait en chemin, quand vous sortiez d’Egypte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'Comment il est venu te rencontrer en chemin, et a chargé en queue tous les faibles qui te suivaient, quand tu étais las et harassé, et n’a point eu de crainte de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Quand donc l’Eternel ton Dieu t’aura donné du repos de tous tes ennemis tout à l’entour, dans le pays que l’Eternel ton Dieu te donne en héritage pour le posséder, alors tu effaceras la mémoire d’Hamalec de dessous les cieux; ne l’oublie point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Quand tu seras entré au pays que l’Eternel ton Dieu te donne en héritage, et que tu le posséderas et y demeureras;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'Alors tu prendras des prémices de tous les fruits de la terre, et tu les apporteras du pays que l’Eternel ton Dieu te donne, et les ayant mis dans une corbeille, tu iras au lieu que l’Eternel ton Dieu aura choisi pour y faire habiter son Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Et tu viendras vers le Sacrificateur qui sera en ce temps-là, et lui diras: Je déclare aujourd’hui devant l’Eternel ton Dieu, que je suis parvenu au pays que l’Eternel avait juré à nos pères de nous donner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Et le Sacrificateur prendra la corbeille de ta main, et la posera devant l’autel de l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Puis tu prendras la parole, et diras devant l’Eternel ton Dieu: Mon père était un pauvre misérable Syrien; il descendit en Egypte avec un petit nombre de gens; il y séjourna, et y devint une nation grande, puissante, et nombreuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Puis les Egyptiens nous maltraitèrent, nous affligèrent, et nous imposèrent une dure servitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Et nous criâmes à l’Eternel le Dieu de nos pères; et l’Eternel exauça notre voix, et regarda notre affliction, notre travail, et notre oppression,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Et nous tira hors d’Egypte à main forte, et avec un bras étendu, avec une grande frayeur, et avec des signes et des miracles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'Depuis il nous mena en ce lieu-ci, et nous donna ce pays, qui est un pays découlant de lait et de miel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Maintenant donc voici, j’ai apporté les prémices des fruits de la terre que tu m’as donnée, ô Eternel! Ainsi tu poseras la corbeille devant l’Eternel ton Dieu, et te prosterneras devant l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'Et tu te réjouiras de tout le bien que l’Eternel ton Dieu t’aura donné, et à ta maison, toi et le Lévite, et l’étranger qui sera au milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Quand tu auras achevé de lever toutes les dîmes de ton revenu en la troisième année, qui est l’année des dîmes, tu les donneras au Lévite, à l’étranger, à l’orphelin, et à la veuve; ils en mangeront dans les lieux de ta demeure, et ils en seront rassasiés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'Et tu diras en la présence de l’Eternel ton Dieu: J’ai emporté de ma maison ce qui était sacré, et je l’ai donné au Lévite, à l’étranger, à l’orphelin, et à la veuve, selon tous tes commandements que tu m’as prescrits; je n’ai rien transgressé de tes commandements, et je ne les ai point oubliés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Je n’en ai point mangé dans mon affliction, et je n’en ai rien ôté pour l’appliquer à quelque usage souillé, et n’en ai point donné pour un mort; j’ai obéi à la voix de l’Eternel ton Dieu; j’ai fait selon tout ce que tu m’avais commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Regarde de ta sainte demeure, regarde des cieux, et bénis ton peuple d’Israël, et la terre que tu nous as donnée, comme tu avais juré à nos pères, qui est un pays découlant de lait et de miel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Aujourd’hui l’Eternel ton Dieu te commande de faire ces statuts et ces droits. Prends donc garde de les faire de tout ton cœur, et de toute ton âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Tu as aujourd’hui exigé de l’Eternel qu’il te soit Dieu, et tu as promis que tu marcheras dans ses voies, et que tu garderas ses statuts, ses commandements et ses ordonnances, et que tu obéiras à sa voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Aussi l’Eternel a exigé aujourd’hui de toi, que tu lui sois un peuple précieux; comme il t’ en a parlé, et que tu gardes tous ses commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'Et il te rendra haut élevé, par-dessus toutes les nations qu’il a créées, pour être en louange, en renom, et en gloire; et tu seras un peuple saint à l’Eternel ton Dieu, ainsi qu’il en a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Or Moïse et les Anciens d’Israël commandèrent au peuple, en disant: Gardez tous les commandements que je vous prescris aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'C’est qu’au jour que tu auras passé le Jourdain pour entrer au pays que l’Eternel ton Dieu te donne, tu te dresseras de grandes pierres, et tu les enduiras de chaux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'Puis tu écriras sur elles toutes les paroles de cette Loi, quand tu auras passé, afin que tu entres au pays que l’Eternel ton Dieu te donne, qui est un pays découlant de lait et de miel; ainsi que l’Eternel, le Dieu de tes pères, t’ en a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Quand donc vous aurez passé le Jourdain, vous dresserez ces pierres-là sur la montagne de Hébal, selon que je vous le commande aujourd’hui, et vous les enduirez de chaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Tu bâtiras aussi là un autel à l’Eternel ton Dieu, un autel, dis-je, de pierres, sur lesquelles tu ne lèveras point le fer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Tu bâtiras l’autel de l’Eternel ton Dieu de pierres entières, et sur cet autel tu offriras des holocaustes à l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Tu y offriras aussi des sacrifices de prospérités, et tu mangeras là, et te réjouiras devant l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Et tu écriras sur ces pierres-là toutes les paroles de cette loi, en les exprimant bien nettement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Et Moïse et les Sacrificateurs, qui sont de la race de Lévi, parlèrent à tout Israël, en disant: Ecoute et entends, Israël, tu es aujourd’hui devenu le peuple de l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Tu obéiras donc à la voix de l’Eternel ton Dieu et tu feras ces commandements et ces statuts que je te prescris aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Moïse commanda aussi en ce jour-là au peuple, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Ceux-ci se tiendront sur la montagne de Guérizim pour bénir le peuple, quand vous aurez passé le Jourdain, savoir Siméon, Lévi, Juda, Issacar, Joseph, et Benjamin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Et ceux-ci, Ruben, Gad, Aser, Zabulon, Dan, et Nephthali, se tiendront sur la montagne de Hébal, pour maudire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Et les Lévites prendront la parole, et diront à haute voix à tous les hommes d’Israël:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Maudit soit l’homme qui fera une image taillée, ou de fonte, car c’est une abomination à l’Eternel, l’ouvrage des mains d’un ouvrier, et qui la mettra dans un lieu secret; et tout le peuple répondra, et dira: Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Maudit soit celui qui aura méprisé son père, ou sa mère; et tout le peuple dira: Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Maudit soit celui qui transporte les bornes de son prochain; et tout le peuple dira: Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Maudit soit celui qui fait égarer l’aveugle dans le chemin; et tout le peuple dira: Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Maudit soit celui qui fait injustice à l’étranger, à l’orphelin, et à la veuve; et tout le peuple dira: Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Maudit soit celui qui couche avec la femme de son père; car il découvre le pan de la robe de son père; et tout le peuple dira: Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Maudit soit celui qui couche avec une bête; et tout le peuple dira: Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Maudit soit celui qui couche avec sa soeur, fille de son père, ou fille de sa mère; Et tout le peuple dira: Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Maudit soit celui qui couche avec sa belle-mère; et tout le peuple dira: Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Maudit soit celui qui frappe son prochain en secret; et tout le peuple dira: Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Maudit soit celui qui prend quelque présent pour mettre à mort l’homme innocent; et tout le peuple dira: Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Maudit soit celui qui ne persévère point dans les paroles de cette Loi, pour les faire; et tout le peuple dira: Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Or il arrivera que si tu obéis exactement à la voix de l’Eternel ton Dieu, et que tu prennes garde de faire tous ses commandements que je te prescris aujourd’hui, l’Eternel ton Dieu te rendra haut élevé par dessus toutes les nations de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'Et toutes ces bénédictions ici viendront sur toi, et t’atteindront, quand tu obéiras à la voix de l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Tu seras béni dans la ville, tu seras aussi béni aux champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Le fruit de ton ventre sera béni, et le fruit de ta terre, et le fruit de ton bétail; les portées de tes vaches, et les brebis de ton troupeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Ta corbeille sera bénie; et ta maie aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Tu seras béni en ton entrée, et tu seras aussi béni en ta sortie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'L’Eternel fera que tes ennemis qui s’élèveront contre toi, seront battus devant toi; ils sortiront contre toi par un chemin, et ils s’enfuiront devant toi par sept chemins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'L’Eternel commandera à la bénédiction qu’elle soit avec toi, dans tes greniers, et dans tout ce à quoi tu mettras ta main; et il te bénira au pays que l’Eternel ton Dieu te donne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'L’Eternel ton Dieu t’établira pour lui être un peuple saint, selon qu’il te l’a juré, quand tu garderas les commandements de l’Eternel ton Dieu, et que tu marcheras dans ses voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Et tous les peuples de la terre verront que le Nom de l’Eternel est réclamé sur toi, et ils auront peur de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Et l’Eternel ton Dieu te fera abonder en biens, multipliant le fruit de ton ventre, et le fruit de tes bêtes, et le fruit de ta terre, sur la terre que l’Eternel a juré à tes pères de te donner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'L’Eternel t’ouvrira son bon trésor, savoir les cieux, pour donner la pluie, telle qu’il faut à ta terre en sa saison, et pour bénir tout le travail de tes mains; et tu prêteras à beaucoup de nations, et tu n’emprunteras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'L’Eternel te mettra à la tête, et non à la queue, et tu seras seulement au dessus, et non point au dessous; quand tu obéiras aux commandements de l’Eternel ton Dieu que je te prescris aujourd’hui, afin que tu prennes garde de les faire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'Et que tu ne te détournes ni à droite ni à gauche d’aucune des paroles que je te commande aujourd’hui, pour marcher après d’autres dieux, et pour les servir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Mais si tu n’obéis point à la voix de l’Eternel ton Dieu, pour prendre garde de faire tous ses commandements et ses statuts que je te prescris aujourd’hui, il arrivera que toutes ces malédictions-ci viendront sur toi, et t’atteindront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Tu seras maudit dans la ville, et tu seras aussi maudit aux champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Ta corbeille sera maudite, et ta maie aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Le fruit de ton ventre sera maudit, et le fruit de ta terre; les portées de tes vaches, et les brebis de ton troupeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Tu seras maudit en ton entrée, tu seras aussi maudit en ta sortie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'L’Eternel enverra sur toi la malédiction, l’effroi, et la dissipation dans tout ce à quoi tu mettras la main et que tu feras, jusqu’à ce que tu sois détruit, et que tu périsses promptement, à cause de la méchanceté des actions par lesquelles tu m’auras abandonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'L’Eternel fera que la mortalité s’attachera à toi, jusqu’à ce qu’il t’aura consumé de dessus la terre en laquelle tu vas pour la posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'L’Eternel te frappera de langueur, d’ardeur, de fièvre, de chaleur brûlante, d’épée, de sécheresse et de nielle, qui te poursuivront jusqu’à ce que tu périsses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Et tes cieux, qui seront sur ta tête, seront d’airain; et la terre qui sera sous toi, sera de fer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'L’Eternel te donnera au lieu de la pluie telle qu’il faut à ta terre, une poussière menue, et une poudre qui descendra sur toi des cieux, jusqu’à ce que tu sois exterminé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Et l’Eternel fera que tu seras battu devant tes ennemis. Tu sortiras par un chemin contr’eux, et tu t’enfuiras devant eux par sept chemins; et tu seras vagabond par tous les Royaumes de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Et tes corps morts seront en viande à tous les oiseaux des cieux, et aux bêtes de la terre, et il n’y aura personne qui les effarouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'L’Eternel te frappera de l’ulcère d’Egypte, d’hémorroïdes, de gale, et de grattelle, dont tu ne pourras guérir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'L’Eternel te frappera de frénésie, et d’aveuglement, et de stupidité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Tu iras tâtonnant en plein midi, comme un aveugle tâtonne dans les ténèbres; tu n’amèneras point tes entreprises à un heureux succès, tu ne feras autre chose que souffrir des injustices et le pillage; et il n’y aura personne qui te garantisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Tu fianceras une femme, mais un autre couchera avec elle; tu bâtiras des maisons, mais tu n’y demeureras point; tu planteras des vignes, mais tu n’en cueilleras point le fruit pour toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Ton boeuf sera tué devant tes yeux, mais tu n’en mangeras point; ton âne sera ravi de devant toi, et ne te sera point rendu; tes brebis seront livrées à tes ennemis, et tu n’auras personne qui les en retire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Tes fils et tes filles seront livrés à un autre peuple, et tes yeux le verront, et se consumeront tout le jour en regardant vers eux; et tu n’auras aucun pouvoir en ta main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Et le peuple que tu n’auras point connu, mangera le fruit de ta terre, et tout ton travail; et tu ne feras autre chose que souffrir des injustices et des concussions tous les jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Et tu seras hors du sens à cause des choses que tu verras de tes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'L’Eternel te frappera d’un ulcère malin sur les genoux, et sur les cuisses, dont tu ne pourras être guéri; il t’en frappera depuis la plante de ton pied jusqu’au sommet de ta tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'L’Eternel te fera marcher, toi et ton Roi que tu auras établi sur toi, vers une nation que tu n’auras point connue, ni toi, ni tes pères, et tu serviras là d’autres dieux, le bois, et la pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Et tu seras là un sujet d’étonnement, de railleries, et d’invectives parmi tous les peuples vers lesquels l’Eternel t’aura emmené.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Tu jetteras beaucoup de semence dans ton champ, et tu en recueilleras peu; car les sauterelles la consumeront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Tu planteras des vignes, tu les cultiveras, mais tu n’en boiras point le vin, et tu n’ en recueilleras rien; car les vers en mangeront le fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Tu auras des oliviers en tous tes quartiers, mais tu ne t’oindras point d’huile; car tes oliviers perdront leur fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Tu engendreras des fils et des filles, mais ils ne seront pas à toi, car ils iront en captivité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Les hannetons gâteront tous tes arbres, et le fruit de ta terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'L’étranger qui est au milieu de toi, montera au dessus de toi bien haut, et tu descendras bien bas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Il te prêtera, et tu ne lui prêteras point; il sera à la tête, et tu seras à la queue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Et toutes ces malédictions viendront sur toi, et te poursuivront, et t’atteindront, jusqu’à ce que tu sois exterminé; parce que tu n’auras pas obéi à la voix de l’Eternel ton Dieu, pour garder ses commandements et ses statuts qu’il t’a prescrits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Et ces choses seront en toi et en ta postérité, pour signes et pour prodiges à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Et parce que tu n’auras pas servi l’Eternel ton Dieu avec joie, et de bon coeur, malgré l’abondance de toutes choses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'Tu serviras, dans la faim, dans la soif, dans la nudité, et dans la disette de toutes choses, ton ennemi, que l’Eternel enverra contre toi; et il mettra un joug de fer sur ton cou, jusqu’à ce qu’il t’ait exterminé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'L’Eternel fera lever contre toi de loin, du bout de la terre, une nation qui volera comme vole l’aigle; une nation dont tu n’entendras pas la langue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'Une nation impudente, qui n’aura point d’égard à la personne du vieillard, et qui n’aura point pitié de l’enfant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Elle mangera le fruit de tes bêtes, et les fruits de ta terre, jusqu’à ce que tu sois exterminé. Elle ne te laissera rien de reste, soit froment, soit vin, soit huile, ou portée de tes vaches, ou brebis de ton troupeau, jusqu’à ce qu’elle t’ait ruiné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Et elle t’assiégera dans toutes tes villes, jusqu’à ce que tes murailles les plus hautes et les plus fortes, sur lesquelles tu te seras assuré en tout ton pays, tombent par terre. Elle assiégera, dis-je, toutes tes villes dans tout le pays que l’Eternel ton Dieu t’aura donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Tu mangeras le fruit de ton ventre, la chair de tes fils et de tes filles que l’Eternel ton Dieu t’aura donnés, dans le siège et dans la détresse dont ton ennemi te serrera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'L’homme le plus tendre et le plus délicat d’entre vous regardera d’un oeil malin son frère et sa femme bien-aimée, et le reste de ses enfants qu’il aura réservés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'Pour ne donner à aucun d’eux de la chair de ses enfants, laquelle il mangera; parce qu’il ne lui sera rien demeuré du tout, à cause du siège et de la détresse dont ton ennemi te serrera dans toutes tes villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'La femme la plus tendre et la plus délicate d’entre vous, qui n’eût point osé mettre la plante de son pied sur la terre, par délicatesse et par mollesse, regardera d’un oeil malin son mari bien-aimé, son fils, et sa fille;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'Et la taie de son petit enfant qui sortira d’entre ses pieds, et les enfants qu’elle enfantera; car elle les mangera secrètement dans la disette de toutes choses, à cause du siège et de la détresse, dont ton ennemi te serrera dans toutes les villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Si tu ne prends garde de faire toutes les paroles de cette Loi, qui sont écrites dans ce livre, en craignant le Nom glorieux et terrible de l’Eternel ton Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'Alors l’Eternel rendra tes plaies et les plaies de ta postérité des plaies étranges, des plaies grandes et de durée, des maladies malignes et longues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Et il fera retourner sur toi toutes les langueurs d’Egypte, desquelles tu as eu peur, et elles s’attacheront à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Même l’Eternel fera venir sur toi toute autre maladie, et toute autre plaie, qui n’est point écrite au livre de cette Loi, jusqu’à ce que tu sois exterminé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Et vous resterez en petit nombre, après avoir été comme les étoiles des cieux, tant vous étiez en grand nombre; parce que tu n’auras point obéi à la voix de l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Et il arrivera que comme l’Eternel s’est réjoui sur vous, en vous faisant du bien, et en vous multipliant; de même l’Eternel se réjouira sur vous en vous faisant périr, et en vous exterminant; et vous serez arrachés de dessus la terre dans laquelle vous allez pour la posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Et l’Eternel te dispersera parmi tous les peuples, depuis un bout de la terre jusqu’à l’autre; et tu serviras là d’autres dieux, que ni toi ni tes pères n’avez point connus, le bois et la pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Encore n’auras-tu aucun repos parmi ces nations-là; même la plante de ton pied n’aura aucun repos; car l’Eternel te donnera là un coeur tremblant, et défaillance d’yeux, et détresse d’âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Et ta vie sera pendante devant toi; et tu seras dans l’effroi nuit et jour, et ne seras point assuré de ta vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Tu diras le matin: Qui me fera voir le soir? et le soir tu diras: Qui me fera voir le matin? à cause de l’effroi dont ton coeur sera effrayé, et à cause des choses que tu verras de tes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Et l’Eternel te fera retourner en Egypte sur des navires, pour faire le chemin duquel je t’ai dit: Il ne t’arrivera plus de le voir; et vous vous vendrez là à vos ennemis pour être esclaves et servantes, et il n’y aura personne qui vous achète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Ce sont ici les paroles de l’alliance que l’Eternel commanda à Moïse de traiter avec les enfants d’Israël, au pays de Moab, outre l’alliance qu’il avait traitée avec eux en Horeb.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'Moïse donc appela tout Israël, et leur dit: Vous avez vu tout ce que l’Eternel a fait en votre présence dans le pays d’Egypte, à Pharaon et à tous ses serviteurs, et à tout son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Les grandes épreuves que tes yeux ont vues, ces signes, et ces grands miracles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Mais l’Eternel ne vous a point donné un coeur pour entendre, ni des yeux pour voir, ni des oreilles pour entendre, jusqu’à aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Et je vous ai conduits durant quarante ans par le désert, sans que vos vêtements se soient envieillis sur vous, et sans que ton soulier ait été envieilli sur ton pied.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Vous n’avez point mangé de pain, ni bu de vin, ni de cervoise, afin que vous connaissiez que je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Et vous êtes parvenus en ce lieu-ci, et Sihon, Roi de Hesbon, et Hog, Roi de Basan, sont sortis au devant de nous pour nous combattre, et nous les avons battus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'Et avons pris leur pays, et l’avons donné en héritage aux Rubénites, aux Gadites, et à la demi Tribu de Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Vous garderez donc les paroles de cette alliance, et vous les ferez, afin que vous prospériez dans tout ce que vous ferez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Vous comparaissez tous aujourd’hui devant l’Eternel votre Dieu, les chefs de vos Tribus, vos Anciens, vos Officiers, et tout homme d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'Vos petits enfants, vos femmes, et ton étranger qui est au milieu de ton camp, depuis ton coupeur de bois jusqu’à ton puiseur d’eau;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'Afin que tu entres dans l’alliance de l’Eternel ton Dieu, laquelle il traite aujourd’hui avec toi, et dans l’exécration du serment qu’il te fait faire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Afin qu’il t’établisse aujourd’hui pour être son peuple, et qu’il te soit Dieu, ainsi qu’il t’a dit, et ainsi qu’il a juré à tes pères, Abraham, Isaac, et Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Et ce n’est pas seulement avec vous que je traite cette alliance, et cette exécration du serment que vous faites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Mais c’est tant avec celui qui est ici avec nous aujourd’hui devant l’Eternel notre Dieu, qu’avec celui qui n’est point ici avec nous aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Car vous savez comment nous avons demeuré au pays d’Egypte, et comment nous avons passé chez les nations, parmi lesquelles vous avez passé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Et vous avez vu leurs abominations, et leurs dieux de fiente, les dieux de bois et de pierre, d’argent et d’or qui sont parmi eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Prenez garde qu’il n’y ait parmi vous ni homme, ni femme, ni famille, ni Tribu qui détourne aujourd’hui son coeur de l’Eternel notre Dieu, pour aller servir les dieux de ces nations, et qu’il n’y ait parmi vous quelque racine qui produise du fiel et de l’absinthe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Et qu’il n’arrive que quelqu’un entendant les paroles de cette exécration du serment que vous faites, ne se bénisse en son coeur, en disant: J’aurai la paix, quoique je vive selon que je l’ai arrêté en mon coeur; afin d’ajouter l’ivrognerie à l’altération.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'L’Eternel refusera de lui pardonner; la colère de l’Eternel et sa jalousie s’enflammeront alors contre cet homme-là, et toute l’exécration du serment que vous faites, laquelle est écrite dans ce livre, demeurera sur lui, et l’Eternel effacera le nom de cet homme de dessous les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Et l’Eternel le séparera de toutes les Tribus d’Israël pour son malheur, selon toutes les exécrations du serment de l’alliance qui est écrite dans ce livre de la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Et la génération à venir, vos enfants qui viendront après vous, et le forain qui viendra d’un pays éloigné, diront lorsqu’ils verront les plaies de ce pays, et ses maladies, dont l’Eternel l’affligera;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'Et que toute la terre de ce pays-là ne sera que soufre, que sel, et qu’embrasement, qu’elle ne sera point semée, et qu’elle ne fera rien germer, et que nulle herbe n’en sortira, ainsi qu’en la subversion de Sodome, et de Gomorrhe, et d’Adma, et de Tséboïm, lesquelles l’Eternel détruisit en sa colère et en sa fureur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Même toutes les nations diront: Pourquoi l’Eternel a-t-il fait ainsi à ce pays? Quelle est l’ardeur de cette grande colère?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Et on répondra: C’est à cause qu’ils ont abandonné l’alliance de l’Eternel le Dieu de leurs pères, laquelle il avait traitée avec eux quand il les fit sortir du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'Car ils s’en sont allés, et ont servi d’autres dieux, et se sont prosternés devant eux, devant ces dieux qu’ils n’avaient point connus, et aucun desquels ne leur avait rien donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'A cause de cela la colère de l’Eternel s’est embrasée contre ce pays, pour faire venir sur lui toutes les malédictions écrites dans ce livre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Et l’Eternel les a arrachés de leur terre en sa colère, et en sa fureur, et en sa grande indignation, et les a chassés en un autre pays, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Les choses cachées sont pour l’Eternel notre Dieu; mais les choses révélées sont pour nous et pour nos enfants à jamais, afin que nous fassions toutes les paroles de cette Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Or il arrivera que lorsque toutes ces choses seront venues sur toi, soit la bénédiction, soit la malédiction, que je t’ai représentées, et lorsque tu les auras rappelées dans ton coeur, parmi toutes les nations vers lesquelles l’Eternel ton Dieu t’aura chassé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'Et que tu te seras retourné jusqu’à l’Eternel ton Dieu, et que tu auras écouté, toi et tes enfants, de tout ton cœur, et de toute ton âme, sa voix, selon tout ce que je te commande aujourd’hui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'L’Eternel ton Dieu ramènera aussi tes captifs, et aura compassion de toi; et il te rassemblera de nouveau d’entre tous les peuples, parmi lesquels l’Eternel ton Dieu t’avait dispersé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Quand tes dispersés seraient au bout des cieux, l’Eternel ton Dieu te rassemblera de là, et te prendra de là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'L’Eternel ton Dieu, dis-je, te ramènera au pays que tes pères auront possédé, et tu le posséderas; il te fera du bien, et te fera croître plus qu’il n’a fait croître tes pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Et l’Eternel ton Dieu circoncira ton coeur, et le coeur de ta postérité, afin que tu aimes l’Eternel ton Dieu de tout ton cœur, et de toute ton âme, afin que tu vives.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Et l’Eternel ton Dieu mettra toutes ces exécrations-là du serment que vous avez fait, sur tes ennemis et sur ceux qui te haïssent, lesquels t’auront persécuté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Ainsi tu retourneras, et tu obéiras à la voix de l’Eternel, et tu feras tous ses commandements que je te prescris aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Et l’Eternel ton Dieu te fera abonder en biens, provenant de tout le travail de ta main, du fruit de ton ventre, du fruit de tes bêtes, et du fruit de ta terre: car l’Eternel ton Dieu retournera à se réjouir sur toi en bien, ainsi qu’il s’est réjoui sur tes pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'Quand tu obéiras à la voix de l’Eternel ton Dieu, gardant ses commandements, et ses ordonnances écrites dans ce livre de la Loi; quand tu te retourneras à l’Eternel ton Dieu de tout ton coeur et de toute ton âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Car ce commandement que je te prescris aujourd’hui n’est pas trop haut pour toi, et il n’en est point éloigné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Il n’est pas aux cieux, pour dire: Qui est-ce qui montera pour nous aux cieux, et nous l’apportera, afin de nous le faire entendre, et que nous le fassions?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Il n’est point aussi au delà de la mer pour dire: Qui est-ce qui passera au delà de la mer pour nous, et nous l’apportera, afin de nous le faire entendre, et que nous le fassions?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Car cette parole est fort près de toi, dans ta bouche et dans ton coeur pour la faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Regarde, j’ai mis aujourd’hui devant toi tant la vie et le bien, que la mort et le mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Car je te commande aujourd’hui d’aimer l’Eternel ton Dieu, de marcher dans ses voies, de garder ses commandements, ses ordonnances, et ses droits, afin que tu vives, et que tu sois multiplié, et que l’Eternel ton Dieu te bénisse au pays dans lequel tu vas pour le posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Mais si ton coeur se détourne, et que tu n’obéisses point à ces commandements, et que tu t’abandonnes à te prosterner devant d’autres dieux, et à les servir;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'Je vous déclare aujourd’hui que vous périrez certainement, et que vous ne prolongerez point vos jours sur la terre, pour laquelle vous passez le Jourdain, afin d’y entrer et de la posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Je prends aujourd’hui à témoin les cieux et la terre contre vous, que j’ai mis devant toi la vie et la mort, la bénédiction et la malédiction; choisis donc la vie, afin que tu vives, toi et ta postérité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'En aimant l’Eternel ton Dieu, en obéissant à sa voix, et en t’attachant à lui; car c’est lui qui est ta vie, et la longueur de tes jours, afin que tu demeures sur la terre que l’Eternel a juré à tes pères, Abraham, Isaac, et Jacob, de leur donner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Puis Moïse s’en alla, et tint ces discours à tout Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Et leur dit: Je suis aujourd’hui âgé de six vingts ans, je ne pourrai plus aller ni venir; aussi l’Eternel m’a dit: Tu ne passeras point ce Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'L’Eternel ton Dieu passera lui-même devant toi; il exterminera ces nations- là devant toi, et tu posséderas leur pays; et Josué est celui qui doit passer devant toi, comme l’Eternel en a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Et l’Eternel leur fera comme il a fait à Sihon et à Hog, Rois des Amorrhéens, et à leurs pays, lesquels il a exterminés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Et l’Eternel les livrera devant vous, et vous leur ferez entièrement selon le commandement que je vous ai prescrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Fortifiez-vous donc et vous renforcez; ne craignez point, et ne soyez point effrayés à cause d’eux; car c’est l’Eternel ton Dieu qui marche avec toi; il ne te délaissera point, et ne t’abandonnera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Et Moïse appela Josué, et lui dit en la présence de tout Israël: Fortifie- toi, et te renforce, car tu entreras avec ce peuple au pays que l’Eternel a juré à leurs pères de leur donner, et c’est toi qui les en mettras en possession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Car l’Eternel, qui est celui qui marche devant toi, sera lui-même avec toi; il ne te délaissera point, et ne t’abandonnera point; ne crains donc point, et ne sois point effrayé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Or Moïse écrivit cette Loi, et la donna aux Sacrificateurs, enfants de Lévi, qui portaient l’Arche de l’alliance de l’Eternel, et à tous les Anciens d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Et Moïse leur commanda, en disant: De sept ans en sept ans, au temps précis de l’année de relâche, en la fête des Tabernacles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'Quand tout Israël sera venu pour comparaître devant la face de l’Eternel ton Dieu, au lieu qu’il aura choisi, tu liras alors cette Loi devant tout Israël, eux l’entendant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Ayant assemblé le peuple, hommes et femmes, et leurs petits enfants, et ton étranger qui sera dans tes portes, afin qu’ils l’entendent, et qu’ils apprennent à craindre l’Eternel votre Dieu, et qu’ils prennent garde de faire toutes les paroles de cette Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Et que leurs enfants qui n’en auront point eu connaissance, l’entendent, et apprennent à craindre l’Eternel votre Dieu tous les jours que vous serez vivants sur la terre pour laquelle posséder vous passez le Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Alors l’Eternel dit à Moïse: Voici, le jour de ta mort est proche, appelle Josué, et présentez-vous au Tabernacle d’assignation, afin que je l’instruise de sa charge. Moïse donc et Josué allèrent, et se présentèrent au Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Et l’Eternel apparut sur le Tabernacle dans la colonne de nuée; et la colonne de nuée s’arrêta sur l’entrée du Tabernacle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Et l’Eternel dit à Moïse: Voici, tu t’en vas dormir avec tes pères, et ce peuple se lèvera, et paillardera après les dieux des étrangers qui sont au pays où il va, pour être parmi eux, et il m’abandonnera, et enfreindra mon alliance que j’ai traitée avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'En ce jour-là ma colère s’enflammera contre lui; je les abandonnerai, je cacherai ma face d’eux, il sera exposé en proie, plusieurs maux et angoisses le trouveront; et il dira en ce jour-là: N’est-ce pas à cause que mon Dieu n’est point au milieu de moi, que ces maux-ci m’ont trouvé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'En ce jour-là, dis-je, je cacherai entièrement ma face, à cause de tout le mal qu’il aura fait, parce qu’il se sera détourné vers d’autres dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Maintenant donc écrivez ce cantique, et l’enseignez aux enfants d’Israël; mets-le dans leur bouche, afin que ce cantique me serve de témoin contre les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Car je l’introduirai en la terre découlante de lait et de miel, de laquelle j’ai juré à ses pères, et il mangera et sera rassasié, et engraissé; puis il se détournera vers d’autres dieux, et ils les serviront, et ils m’irriteront par mépris, et enfreindront mon alliance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Et il arrivera que quand plusieurs maux et angoisses les auront trouvés, ce cantique déposera contre eux comme témoin; parce qu’il ne sera point oublié pour n’être plus en la bouche de leur postérité; car je connais leur imagination, et ce qu’ils font déjà aujourd’hui, avant que je les introduise au pays duquel j’ai juré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Ainsi Moïse écrivit ce cantique en ce jour-là, et l’enseigna aux enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Et l’Eternel commanda à Josué, fils de Nun, en disant: Fortifie-toi, et te renforce, car c’est toi qui introduiras les enfants d’Israël au pays duquel je leur ai juré; et je serai avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Et il arriva que quand Moïse eut achevé d’écrire les paroles de cette Loi dans un livre, sans qu’il en manquât rien;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'Il commanda aux Lévites qui portaient l’Arche de l’alliance de l’Eternel, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Prenez ce livre de la Loi, et mettez-le à côté de l’Arche de l’alliance de l’Eternel votre Dieu, et il sera là pour témoin contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Car je connais ta rébellion et ton cou roide. Voici, moi étant encore aujourd’hui avec vous, vous avez été rebelles contre l’Eternel, combien plus donc le serez-vous après ma mort?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Faites assembler vers moi tous les Anciens de vos Tribus, et vos officiers, et je dirai ces paroles, eux les entendant, et j’appellerai à témoin contr’eux les cieux et la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Car je sais qu’après ma mort vous ne manquerez point de vous corrompre, et que vous vous détournerez de la voie que je vous ai prescrite; mais à la fin il vous arrivera du mal, parce que vous aurez fait ce qui déplaît à l’Eternel, en l’irritant par les oeuvres de vos mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Ainsi Moïse prononça les paroles de ce cantique-ci sans qu’il s’en manquât rien, toute l’assemblée d’Israël l’entendant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Cieux prêtez l’oreille, et je parlerai, et que la terre écoute les paroles de ma bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Ma doctrine distillera comme la pluie; ma parole dégouttera comme la rosée, comme la pluie menue sur l’herbe naissante, et comme la grosse pluie sur l’herbe avancée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Car j’invoquerai le Nom de l’Eternel; attribuez la grandeur à notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'L’oeuvre du Rocher est parfaite; car toutes ses voies sont jugement. Le Dieu Fort est vérité, et sans iniquité; il est juste et droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Ils se sont corrompus envers lui, leur tache n’est pas une tache de ses enfants; c’est une génération perverse et revêche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Est-ce ainsi que tu récompenses l’Eternel, peuple fou, et qui n’es pas sage? n’est-il pas ton père, qui t’a acquis? il t’a fait, et t’a façonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Souviens-toi du temps d’autrefois, considère les années de chaque génération; interroge ton père, et il te l’apprendra; et tes Anciens, et ils te le diront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Quand le Souverain partageait les nations, quand il séparait les enfants des hommes les uns des autres, il établit les bornes des peuples selon le nombre des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Car la portion de l’Eternel c’est son peuple, et Jacob est le lot de son héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Il l’a trouvé dans un pays de désert, et dans un lieu hideux, où il n’y avait que hurlement de désolation; il l’a conduit par des détours, il l’a dirigé, et l’a gardé comme la prunelle de son oeil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Comme l’aigle émeut sa nichée, couve ses petits, étend ses ailes, les accueille, et les porte sur ses ailes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'L’Eternel seul l’a conduit, et il n’y a point eu avec lui de dieu étranger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Il l’a fait passer comme à cheval par dessus les lieux haut-élevés de la terre, et il a mangé les fruits des champs, et il lui a fait sucer le miel de la roche, et a fait couler l’huile des plus durs rochers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Il lui a fait manger le beurre des vaches, et le lait des brebis, et la graisse des agneaux et des moutons nés en Basan, et la graisse des boucs, et la fleur du froment, et tu as bu le vin qui était le sang de la grappe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Mais le droiturier s’est engraissé, et a regimbé; tu t’es fait gras, gros et épais; et il a quitté Dieu qui l’a fait, et il a déshonoré le rocher de son salut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Ils l’ont ému à jalousie par les dieux étrangers; ils l’ont irrité par des abominations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Ils ont sacrifié aux idoles, qui ne sont point dieux; aux dieux qu’ils n’avaient point connus, dieux nouveaux, venus depuis peu, desquels vos pères n’ont point eu peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Tu as oublié le Rocher qui t’a engendré, et tu as mis en oubli le Dieu Fort qui t’a formé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Et l’Eternel l’a vu, et a été irrité, parce que ses fils et ses filles l’ont provoqué à la colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Et il a dit: Je cacherai ma face d’eux, je verrai quelle sera leur fin; car ils sont une race perverse, des enfants en qui on ne peut se fier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Ils m’ont ému à jalousie par ce qui n’est point le Dieu Fort, et ils ont excité ma colère par leurs vanités; ainsi je les émouvrai à jalousie par un peuple qui n’est point peuple; et je les provoquerai à la colère par une nation folle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Car le feu s’est allumé en ma colère, et a brûlé jusqu’au fond des plus bas lieux, et a dévoré la terre et son fruit, et a embrasé les fondements des montagnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'J’emploierai sur eux toute sorte de maux, et je décocherai sur eux toutes mes flèches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Ils seront consumés par la famine, et rongés par des charbons ardents, et par une destruction amère; et j’enverrai contr’eux les dents des bêtes, et le venin des serpents qui se traînent sur la poussière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'L’épée venant de dehors les privera les uns des autres; et la frayeur, venant des cabinets ravagera le jeune homme et la vierge; l’enfant qui tète, et l’homme décrépit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'J’eusse dit: Je les disperserai dans tous les coins de la terre, et j’abolirai leur mémoire d’entre les hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Si je ne craignais l’indignation de l’ennemi, et que peut-être il n’arrivât que leurs adversaires ne vinssent à se méconnaître, que peut-être ils ne dissent: Notre main s’est exaltée, et l’Eternel n’a point fait tout ceci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Car ils sont une nation qui se perd par ses conseils, et il n’y a en eux aucune intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Ô s’ils eussent été sages! s’ils eussent été avisés en ceci, et s’ils eussent considéré leur dernière fin!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Comment un en poursuivrait-il mille, et deux en mettraient-ils en fuite dix mille, si ce n’était que leur rocher les a vendus, et que l’Eternel les a enserrés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Car leur rocher n’est pas comme notre rocher, et nos ennemis eux-mêmes en seront juges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Car leur vigne est du plant de Sodome, et du terroir de Gomorrhe, et leurs grappes sont des grappes de fiel, ils ont des raisins amers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Leur vin est un venin de dragon, et du fiel cruel d’aspic.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Cela n’est-il pas serré chez moi, et scellé dans mes trésors?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'La vengeance m’appartient, et la rétribution, au temps que leur pied glissera; car le jour de leur calamité est près, et les choses qui leur doivent arriver se hâtent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Mais l’Eternel jugera son peuple, et se repentira en faveur de ses serviteurs, quand il verra que la force s’en sera allée, et qu’il n’y aura rien de reste, rien de serré, ni de délaissé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Et il dira: Où sont leurs dieux, le rocher vers lequel ils se retiraient?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Mangeant la graisse de leurs sacrifices et buvant le vin de leurs aspersions. Qu’ils se lèvent, et qu’ils vous aident, et qu’ils vous servent d’asile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Regardez maintenant que c’est moi, moi-même, et il n’y a point de dieu avec moi; je fais mourir, et je fais vivre; je blesse, et je guéris, et il n’y a personne qui puisse délivrer de ma main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Car je lève ma main au ciel, et je dis: Je suis vivant éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Si j’aiguise la lame de mon épée, et si ma main saisit le jugement, je ferai tourner la vengeance sur mes adversaires, et je le rendrai à ceux qui me haïssent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'J’enivrerai mes flèches de sang, et mon épée dévorera la chair, j’enivrerai, dis-je, mes flèches du sang des tués et des captifs, commençant par le chef, en vengeance d’ennemi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Nations, réjouissez-vous avec son peuple; car il vengera le sang de ses serviteurs, et il fera tourner la vengeance sur ses ennemis, et fera l’expiation de sa terre et de son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Moïse donc vint, et prononça toutes les paroles de ce cantique, le peuple l’écoutant, lui et Josué, fils de Nun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Et quand Moïse eut achevé de prononcer toutes ces paroles à tout Israël,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'Il leur dit: Mettez votre coeur à toutes ces paroles que je vous somme aujourd’hui de commander à vos enfants, afin qu’ils prennent garde de faire toutes les paroles de cette Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Car ce n’est pas une parole qui vous soit proposée en vain, mais c’est votre vie; et par cette parole vous prolongerez vos jours sur la terre pour laquelle posséder vous allez passer le Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'En ce même jour-là l’Eternel parla à Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Monte sur cette montagne de Habarim, en la montagne de Nébo, qui est au pays de Moab, vis-à-vis de Jéricho; ensuite regarde le pays de Canaan, que je donne en possession aux enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Et tu mourras sur la montagne sur laquelle tu montes, et tu seras recueilli vers tes peuples, comme Aaron ton frère est mort sur la montagne de Hor, et a été recueilli vers ses peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Parce que vous avez péché contre moi au milieu des enfants d’Israël aux eaux de la contestation de Kadès dans le désert de Tsin; car vous ne m’avez point sanctifié au milieu des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'C’est pourquoi tu verras vis-à-vis de toi le pays, mais tu n’y entreras point, au pays, dis-je, que je donne aux enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Or c’est ici la bénédiction dont Moïse, homme de Dieu, bénit les enfants d’Israël avant sa mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Il dit donc: L’Eternel est venu de Sinaï, et s’est levé à eux en Séhir; il leur a resplendi de la montagne de Paran, et il est sorti d’entre les dix milliers des Saints, et de sa dextre le feu de la Loi est sorti vers eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Et même il aime les peuples, tous ses Saints sont en ta main; et ils se sont tenus à tes pieds pour recevoir tes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Moïse nous a donné la Loi, qui est l’héritage de l’assemblée de Jacob;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Et il a été Roi entre les hommes droits, quand les chefs du peuple se sont assemblés, avec les Tribus d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Que RUBEN vive, et qu’il ne meure point, encore que ses hommes soient en petit nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Et c’est ici ce que Moïse dit pour JUDA; Ô Eternel! écoute la voix de Juda, et le ramène vers son peuple; que ses mains lui suffisent, et que tu lui sois en aide contre ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Il dit aussi touchant LEVI: Tes Thummims et tes Urims sont à l’homme qui est ton bien-aimé, que tu as éprouvé en Massa, et contre lequel tu t’es querellé aux eaux de Mériba.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'C’est lui qui dit de son père et de sa mère: Je ne l’ai point vu; et qui n’a point connu ses frères, et n’a point aussi connu ses enfants; car ils ont gardé tes paroles, et ils garderont ton alliance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Ils enseigneront tes ordonnances à Jacob, et ta Loi à Israël, ils mettront le parfum en tes narines, et tout Sacrifice qui se consume entièrement par le feu sur ton autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Ô Eternel! bénis ses troupes, et que l’oeuvre de ses mains te soit agréable. Transperce les reins de ceux qui s’élèvent contre lui, et de ceux qui le haïssent, aussitôt qu’ils se seront élevés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Il dit touchant BENJAMIN: Le bien-aimé de l’Eternel habitera sûrement avec lui; il le couvrira tout le jour, et se tiendra entre ses épaules.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Et il dit touchant JOSEPH: Son pays est béni par l’Eternel, de ce qui est le plus exquis aux cieux, de la rosée, et de l’abîme qui est en bas;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'Et de ce qu’il y a de plus exquis entre les choses que le soleil fait produire, et de ce qui est le plus excellent entre les choses que la lune fait produire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'Et du coupeau des montagnes anciennes, et de ce qu’il y a de plus exquis sur les coteaux d’éternité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'Et de ce qu’il y a de plus exquis sur la terre, et de son abondance; et que la bienveillance de celui qui se tenait au buisson vienne sur la tête de Joseph, sur le sommet, dis-je, de la tête du Nazarien d’entre ses frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Sa beauté est comme d’un premier-né de ses taureaux, et ses cornes comme les cornes d’une licorne; il heurtera avec elles tous les peuples jusqu’aux bouts de la terre. Ce sont les dix milliers d’Ephraïm, et ce sont les milliers de Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Il dit aussi touchant ZABULON: Réjouis-toi, Zabulon, en ta sortie; et toi ISSACAR dans tes tentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Ils appelleront les peuples en la montagne, ils offriront là des sacrifices de justice; car ils suceront l’abondance de la mer, et les choses les plus cachées dans le sable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Il dit aussi, touchant GAD: Béni soit celui qui fait élargir Gad; il habite comme un vieux lion, et il déchire bras et tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Il a regardé le commencement du pays pour l’avoir pour soi, parce que c’était là qu’était cachée la portion du Législateur, et il est venu avec les principaux du peuple; il a fait la justice de l’Eternel, et ses jugements avec Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Et il dit touchant DAN: Dan est un jeune lion, il sautera de Basan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Il dit aussi touchant NEPHTHALI: Nephthali rassasié de bienveillance, et rempli de la bénédiction de l’Eternel, possède l’Occident et le Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Il dit aussi touchant ASER: Aser sera béni en enfants; il sera agréable à ses frères; et même il trempera son pied dans l’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Tes verrous seront de fer et d’airain, et ta force durera autant que tes jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Ô Droiturier, il n’y a point de Dieu semblable au Dieu Fort, qui vient à ton aide, porté sur les cieux et sur les nuées en sa Majesté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'C’est une retraite que le Dieu qui est de tout temps, et d’être sous les bras éternels; car il a chassé de devant toi tes ennemis, et il a dit: Extermine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Israël donc habitera seul sûrement, l’oeil de Jacob sera vers un pays de froment et de vin, et ses cieux distilleront la rosée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Ô que tu es heureux, Israël! Qui est le peuple semblable à toi, lequel ait été gardé par l’Eternel, le bouclier de ton secours, et l’épée par laquelle tu as été hautement élevé? tes ennemis seront humiliés, et tu fouleras de tes pieds leurs lieux les plus hauts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Alors Moïse monta des campagnes de Moab sur la montagne de Nébo, au sommet de la colline qui est vis-à-vis de Jéricho, et l’Eternel lui fit voir tout le pays, depuis Galaad jusques à Dan,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'Avec tout le pays de Nephthali, et le pays d’Ephraïm et de Manassé, et tout le pays de Juda, jusqu’à la mer Occidentale;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'Et le Midi, et la campagne de la plaine de Jérico, la ville des palmes; jusqu’à Tsohar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Et l’Eternel lui dit: C’est ici le pays dont j’ai juré à Abraham, à Isaac, et à Jacob, en disant: Je le donnerai à ta postérité; je te l’ai fait voir de tes yeux; mais tu n’y entreras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Ainsi Moïse, serviteur de l’Eternel, mourut là au pays de Moab, selon le commandement de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Et il l’ensevelit dans la vallée, au pays de Moab, vis-à-vis de Beth-Péhor; et personne n’a connu son sépulcre jusqu’à aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Or Moïse était âgé de six vingts ans quand il mourut; sa vue n’était point diminuée, et sa vigueur n’était point passée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Et les enfants d’Israël pleurèrent Moïse trente jours dans les campagnes de Moab, et ainsi les jours des pleurs du deuil de Moïse furent accomplis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Et Josué, fils de Nun, fut rempli de l’Esprit de sagesse, parce que Moïse lui avait imposé les mains; et les enfants d’Israël lui obéirent, et firent ainsi que l’Eternel avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Et il ne s’est jamais levé en Israël de Prophète comme Moïse, qui ait connu l’Eternel face à face;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'Selon tous les signes et les miracles que l’Eternel l’envoya faire au pays d’Egypte, devant Pharaon, et tous ses serviteurs, et tout son pays;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'Selon toute cette main forte, et toutes ces grandes oeuvres redoutables, que Moïse fit à la vue de tout Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Or il arriva après la mort de Moïse, serviteur de l’Eternel, que l’Eternel parla à Josué, fils de Nun, qui avait servi Moïse, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Moïse mon serviteur est mort; maintenant donc lève-toi, passe ce Jourdain, toi et tout ce peuple, pour entrer au pays que je donne aux enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Je vous ai donné tout lieu où vous aurez mis la plante de votre pied, selon que je l’ai dit à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Vos frontières seront depuis ce désert et ce Liban-là, jusqu’à ce grand fleuve, le fleuve d’Euphrate; tout le pays des Héthiens jusqu’à la grande mer, au soleil couchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Nul ne pourra subsister devant toi tous les jours de ta vie; je serai avec toi comme j’ai été avec Moïse; je ne te délaisserai point, et je ne t’abandonnerai point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Fortifie-toi et te renforce; car c’est toi qui mettras ce peuple en possession du pays dont j’ai juré à leurs pères que je le leur donnerais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Seulement fortifie-toi et te renforce de plus en plus, afin que tu prennes garde de faire selon toute la Loi que Moïse mon serviteur t’a ordonnée; ne t’en détourne point ni à droite ni à gauche, afin que tu prospères partout où tu iras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Que ce livre de la Loi ne s’éloigne point de ta bouche, mais médites-y jour et nuit, afin que tu prennes garde de faire tout ce qui y est écrit; car alors tu rendras heureuses tes entreprises, et alors tu prospéreras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Ne t’ai-je pas commandé, et dit, fortifie-toi et te renforce? Ne t’épouvante point, et ne t’effraye de rien; car l’Eternel ton Dieu est avec toi partout où tu iras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Après cela Josué commanda aux officiers du peuple, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Passez par le camp, et commandez au peuple, et lui dites: Apprêtez-vous de la provision; car dans trois jours vous passerez ce Jourdain, pour aller posséder le pays que l’Eternel votre Dieu vous donne, afin que vous le possédiez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Josué parla aussi aux Rubénites, et aux Gadites, et à la demi- Tribu de Manassé, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Souvenez-vous de la parole que Moïse, serviteur de l’Eternel, vous a commandée, en disant: L’Eternel votre Dieu vous met en repos, et vous a donné ce pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Vos femmes donc, vos petits enfants, et vos bêtes demeureront dans le pays que Moïse vous a donné au deçà du Jourdain; mais vous passerez en armes devant vos frères, vous tous qui êtes forts et vaillants, et vous leur serez en secours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'Jusqu’à ce que l’Eternel ait mis vos frères en repos, comme vous, et qu’eux aussi possèdent le pays que l’Eternel votre Dieu leur donne; puis vous retournerez au pays de votre possession, et vous le posséderez; savoir celui que Moïse serviteur de l’Eternel vous a donné au deçà du Jourdain, vers le soleil levant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Et ils répondirent à Josué, en disant: Nous ferons tout ce que tu nous as commandé, et nous irons partout où tu nous enverras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Nous t’obéirons comme nous avons obéi à Moïse; seulement que l’Eternel ton Dieu soit avec toi, comme il a été avec Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Tout homme qui sera rebelle à ton commandement, et qui n’obéira point à tes paroles en tout ce que tu commanderas, sera mis à mort; seulement fortifie-toi, et te renforce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Or Josué, fils de Nun, avait envoyé de Sittim deux hommes, pour épier secrètement le pays, et il leur avait dit: Allez, considérez le pays, et Jérico. Ils partirent donc, et vinrent dans la maison d’une femme paillarde, nommée Rahab, et couchèrent là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Alors on dit au Roi de Jérico: Voilà des hommes qui sont venus ici cette nuit de la part des enfants d’Israël pour reconnaître le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Et le Roi de Jérico envoya vers Rahab, en disant: Fais sortir les hommes qui sont venus chez toi, et qui sont entrés dans ta maison; car ils sont venus pour reconnaître tout le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Or la femme avait pris ces deux hommes, et les avait cachés; et elle dit: Il est vrai que des hommes sont venus chez moi, mais je ne savais pas d’où ils étaient;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'Et comme on fermait la porte sur le soir, ces hommes-là sont sortis. Je ne sais point où ces hommes sont allés; poursuivez-les bien vite, car vous les atteindrez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Or elle les avait fait monter sur le toit, et les avait cachés dans des chènevottes de lin qu’elle avait arrangées sur le toit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Et quelques gens les poursuivirent par le chemin du Jourdain jusqu’aux passages; et on ferma la porte après que ceux qui les poursuivaient furent sortis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Or avant qu’ils se couchassent, elle monta vers eux sur le toit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'Et leur dit: Je connais que l’Eternel vous a donné le pays; et que la terreur de votre nom nous a saisis, et que tous les habitants du pays sont devenus lâches à cause de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Car nous avons entendu que l’Eternel a tari les eaux de la mer Rouge de devant vous, quand vous sortiez du pays d’Egypte; et ce que vous ayez fait aux deux Rois des Amorrhéens qui étaient au delà du Jourdain, à Sihon et à Hog, que vous avez détruits à la façon de l’interdit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Nous l’avons entendu, et notre coeur s’est fondu, et depuis cela aucun homme n’a eu de courage, à cause de vous; car l’Eternel votre Dieu est le Dieu des cieux en haut, et de la terre en bas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Maintenant donc, je vous prie, jurez-moi par l’Eternel, que puisque j’ai usé de gratuité envers vous, vous userez aussi de gratuité envers la maison de mon père, et que vous me donnerez des marques assurées,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'Que vous sauverez la vie à mon père et à ma mère, à mes frères et à mes soeurs, et à tous ceux qui leur appartiennent, et que vous garantirez nos personnes de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Et ces hommes lui répondirent: Nos personnes répondront pour vous jusques à la mort, pourvu que vous ne nous déceliez point en cette affaire; et quand l’Eternel nous aura donné le pays nous userons envers toi de gratuité et de vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Elle les fit donc descendre avec une corde par la fenêtre; car sa maison était sur la muraille de la ville, et elle habitait sur la muraille de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Et elle leur dit: Allez à la montagne, de peur que ceux qui vous poursuivent ne vous rencontrent, et cachez-vous là trois jours jusqu’à ce que ceux qui vous poursuivent soient de retour; et après cela vous irez votre chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Or ces hommes lui avaient dit: Nous serons quittes en cette manière -ci de ce serment que tu nous as fait faire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Voici, quand nous entrerons au pays, tu lieras ce cordon de fil d’écarlate à la fenêtre par laquelle tu nous auras fait descendre, et tu retireras chez toi, dans cette maison ton père et ta mère, tes frères, et toute la famille de ton père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Et quiconque sortira hors de la porte de ta maison, son sang sera sur sa tête, et nous en serons quittes; mais quiconque sera avec toi, dans la maison, son sang sera sur notre tête si quelqu’un met la main sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Que si tu nous décèles en cette affaire, nous serons quittes du serment que tu nous as fait faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Et elle répondit: Que cela soit ainsi que vous l’avez dit. Alors elle les laissa aller, et ils s’en allèrent; et elle lia le cordon de fil d’écarlate à la fenêtre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Et eux marchant arrivèrent à la montagne, et demeurèrent là trois jours, jusqu’à ce que ceux qui les poursuivaient fussent revenus, et ceux qui les poursuivaient cherchèrent dans tout le chemin, mais ils ne les trouvèrent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Ainsi ces deux hommes s’en retournèrent, et descendirent de la montagne, et passèrent, et vinrent à Josué, fils de Nun, et lui récitèrent toutes les choses qui leur étaient arrivées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'Et ils dirent à Josué: Certainement l’Eternel a livré tout le pays entre nos mains; et même tous les habitants du pays ont perdu courage à notre vue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Or Josué se leva de bon matin; ils partirent de Sittim, ils vinrent jusqu’au Jourdain, lui et tous les enfants d’Israël, et ils logèrent là cette nuit, avant qu’ils passassent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Et au bout de trois jours les officiers passèrent par le camp;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'Et ils commandèrent au peuple en disant: Sitôt que vous verrez l’Arche de l’alliance de l’Eternel votre Dieu, et les Sacrificateurs de la race de Lévi qui la porteront, vous partirez de votre quartier, et vous marcherez après elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Et afin que vous n’approchiez point d’elle, il y aura entre vous et elle une distance de la mesure d’environ deux mille coudées, afin que vous connaissiez le chemin par lequel vous devez marcher; car vous n’avez point ci-devant passé par ce chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Josué dit aussi au peuple: Sanctifiez-vous; car l’Eternel fera demain, au milieu de vous des choses merveilleuses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Josué parla aussi aux Sacrificateurs, en disant: Chargez sur vous l’Arche de l’alliance, et passez devant le peuple. Ainsi ils chargèrent sur eux l’Arche de l’alliance, et marchèrent devant le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Or l’Eternel avait dit à Josué: Aujourd’hui je commencerai de t’élever à la vue de tout Israël; afin qu’ils connaissent que comme j’ai été avec Moïse, je serai aussi avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Tu commanderas donc aux Sacrificateurs qui portent l’Arche de l’alliance, en leur disant: Sitôt que vous arriverez au bord de l’eau du Jourdain, vous vous arrêterez au Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Et Josué dit aux enfants d’Israël: Approchez-vous d’ici, et écoutez les paroles de l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Puis Josué dit: Vous reconnaîtrez à ceci que le Dieu Fort, et vivant, est au milieu de vous, et qu’il chassera certainement de devant vous les Cananéens, les Héthiens, les Héviens, les Phérésiens, les Guirgasiens, les Amorrhéens, et les Jébusiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Voici, l’Arche de l’alliance du Dominateur de toute la terre s’en va passer devant vous au travers du Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Maintenant donc choisissez douze hommes des Tribus d’Israël, un homme de chaque Tribu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Et il arrivera qu’aussitôt que les plantes des pieds des Sacrificateurs qui portent l’Arche de l’Eternel, le Dominateur de toute la terre, seront posées dans les eaux du Jourdain, les eaux du Jourdain seront coupées, les eaux, dis-je, qui descendent d’en haut, et elles s’arrêteront en un monceau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Et il arriva que le peuple étant parti de ses tentes pour passer le Jourdain, les Sacrificateurs qui portaient l’Arche de l’alliance, étaient devant le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'Et sitôt que ceux qui portaient l’Arche furent arrivés au Jourdain, et que les pieds des Sacrificateurs qui portaient l’Arche furent mouillés au bord de l’eau, (or le Jourdain regorge par dessus tous ses bords durant tout le temps de la moisson.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'Les eaux qui descendaient d’en-haut, s’arrêtèrent, et s’élevèrent en un monceau fort loin, depuis la ville d’Adam, qui est à côté de Tsartan; et celles d’embas, qui descendaient vers la mer de la campagne, qui est la mer salée, défaillirent et s’écoulèrent, et le peuple passa vis-à-vis de Jérico.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Mais les Sacrificateurs qui portaient l’Arche de l’alliance de l’Eternel, s’arrêtèrent de pied ferme sur le sec au milieu du Jourdain, pendant que tout Israël passa à sec, jusqu’à ce que tout le peuple eût achevé de passer le Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Or il arriva que quand tout le peuple eut achevé de passer le Jourdain, parce que l’Eternel avait parlé à Josué; et lui avait dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Prenez du peuple douze hommes, savoir un homme de chaque Tribu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'Et leur commandez, en disant: Prenez d’ici du milieu du Jourdain, du lieu où les Sacrificateurs s’arrêtent de pied ferme, douze pierres, que vous emporterez avec vous, et vous les poserez au lieu où vous logerez cette nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Josué appela les douze hommes qu’il avait ordonnés d’entre les enfants d’Israël, un homme de chaque Tribu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'Et il leur dit: Passez devant l’Arche de l’Eternel votre Dieu, au milieu du Jourdain, et que chacun de vous lève une pierre sur son épaule, selon le nombre des Tribus des enfants d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Afin que cela soit un signe parmi vous; et quand vos enfants interrogeront à l’avenir leurs pères, en disant: Que signifient ces pierres-ci?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'Alors vous leur répondrez que les eaux du Jourdain ont été suspendues devant l’Arche de l’alliance de l’Eternel, que les eaux, dis-je, du Jourdain ont été arrêtées quand elle passa le Jourdain; c’est pourquoi ces pierres-là serviront de mémorial aux enfants d’Israël à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Les enfants d’Israël donc firent comme Josué avait commandé. Ils prirent douze pierres du milieu du Jourdain, ainsi que l’Eternel l’avait commandé à Josué, selon le nombre des Tribus des enfants d’Israël, ils les emportèrent avec eux au lieu où ils devaient loger, et les posèrent là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Josué aussi dressa douze pierres au milieu du Jourdain, au lieu où les pieds des Sacrificateurs qui portaient l’Arche de l’alliance s’étaient arrêtés; et elles y sont demeurées jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Les Sacrificateurs donc qui portaient l’Arche, se tinrent debout au milieu du Jourdain, jusqu’à ce que tout ce que l’Eternel avait commandé à Josué de dire au peuple fût accompli, suivant toutes les choses que Moïse avait commandées à Josué; et le peuple se hâta de passer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Et quand tout le peuple eut achevé de passer, alors l’Arche de l’Eternel passa, et les Sacrificateurs devant le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Et les enfants de Ruben, et les enfants de Gad, et la moitié de la Tribu de Manassé passèrent en armes devant les enfants d’Israël, comme Moïse leur avait dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Ils passèrent, dis-je, vers les campagnes de Jérico environ quarante mille hommes en équipage de guerre, devant l’Eternel, pour combattre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'En ce jour-là l’Eternel éleva Josué, à la vue de tout Israël, et ils le craignirent comme ils avaient craint Moïse, tous les jours de sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Or l’Eternel avait parlé à Josué, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Commande aux Sacrificateurs, qui portent l’Arche du Témoignage, qu’ils montent hors du Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Et Josué avait commandé aux Sacrificateurs, en disant: Montez hors du Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Or sitôt que les Sacrificateurs, qui portaient l’Arche de l’alliance de l’Eternel, furent montés hors du milieu du Jourdain, et que les Sacrificateurs eurent mis sur le sec les plantes de leurs pieds, les eaux du Jourdain retournèrent en leur lieu, et coulèrent comme auparavant, par dessus tous les rivages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Le peuple donc monta hors du Jourdain le dixième jour du premier mois, et ils se campèrent en Guilgal, à l’Orient de Jérico.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Josué aussi dressa en Guilgal ces douze pierres qu’ils avaient prises du Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Et il parla aux enfants d’Israël, et leur dit: Quand vos enfants interrogeront à l’avenir leurs pères, et leur diront: Que signifient ces pierres-ci?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'Vous l’apprendrez à vos enfants, en leur disant, Israël a passé ce Jourdain à sec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Car l’Eternel votre Dieu fit tarir les eaux du Jourdain devant vous, jusqu’à ce que vous fussiez passés; comme l’Eternel votre Dieu avait fait à la mer Rouge, laquelle il mit à sec devant nous, jusqu’à ce que nous fussions passés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'Afin que tous les peuples de la terre connaissent que la main de l’Eternel est forte; et afin que vous craigniez toujours l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Or il arriva qu’aussitôt que tous les Rois des Amorrhéens qui étaient au deçà du Jourdain vers l’Occident, et tous les Rois des Cananéens qui étaient près de la mer, apprirent que l’Eternel avait fait tarir les eaux du Jourdain devant les enfants d’Israël, jusqu’à ce qu’ils fussent passés, leur coeur se fondit, et il n’y eut plus de courage en eux à cause des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'En ce temps-là l’Eternel dit à Josué: Fais-toi des couteaux tranchants, et circoncis de nouveau pour une seconde fois les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Et Josué se fit des couteaux tranchants, et circoncit les enfants d’Israël au coteau des prépuces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Or la raison pour laquelle Josué les circoncit, c’est que tout le peuple qui était sorti d’Egypte, tous les mâles, dis-je, hommes de guerre étaient morts au désert en chemin, après être sortis d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Et que tout le peuple qui était sorti, avait bien été circoncis, mais ils n’avaient point circoncis aucun du peuple né dans le désert en chemin, après être sortis d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Car les enfants d’Israël avaient marché par le désert quarante ans, jusqu’à ce qu’eut été consumé tout le peuple des gens de guerre qui étaient sortis d’Egypte, et qui n’avaient point obéi à la voix de l’Eternel; auxquels l’Eternel avait juré qu’il ne leur laisserait point voir le pays dont l’Eternel avait juré à leurs pères qu’il nous le donnerait, et qui est un pays découlant de lait et de miel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Et il avait suscité en leur place leurs enfants, lesquels Josué circoncit, parce qu’ils étaient incirconcis; car on ne les avait pas circoncis en chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Et quand on eut achevé de circoncire tout le peuple, ils demeurèrent en leur lieu au camp, jusqu’à ce qu’ils fussent guéris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Et l’Eternel dit à Josué: Aujourd’hui j’ai roulé de dessus vous l’opprobre d’Egypte. Et ce lieu-là a été nommé Guilgal jusqu’à aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Ainsi les enfants d’Israël se campèrent en Guilgal, et célébrèrent la Pâque le quatorzième jour du mois, sur le soir, dans les campagnes de Jérico.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Et dès le lendemain de la Pâque, ils mangèrent du blé du pays, savoir des pains sans levain et du grain rôti, en ce même jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Et la Manne cessa dès le lendemain, après qu’ils eurent mangé du blé du pays; et les enfants d’Israël n’eurent plus de Manne, mais ils mangèrent du crû de la terre de Canaan cette année-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Or il arriva, comme Josué était près de Jérico, qu’il leva les yeux, et regarda; et voici, vis-à-vis de lui, se tenait debout un homme qui avait son épée nue en sa main; et Josué alla vers lui, et lui dit: Es-tu des nôtres, ou de nos ennemis?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Et il dit: Non; mais je suis le chef de l’armée de l’Eternel, qui suis venu maintenant. Et Josué se jeta sur son visage en terre, et se prosterna, et lui dit: Qu’est-ce que mon Seigneur dit à son serviteur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Et le chef de l’armée de l’Eternel dit à Josué: Délie ton soulier de tes pieds; car le lieu sur lequel tu te tiens, est saint; et Josué le fit ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Or Jérico se fermait, et se tenait soigneusement fermée, à cause des enfants d’Israël; il n’y avait personne qui en sortît, ni qui y entrât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Et l’Eternel dit à Josué: Regarde, j’ai livré entre tes mains Jérico et son Roi, et ses hommes forts et vaillants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Vous tous donc, hommes de guerre, vous ferez le tour de la ville, en tournant une fois autour d’elle: tu feras ainsi durant six jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Et sept Sacrificateurs porteront sept cors de bélier devant l’Arche; mais au septième jour vous ferez sept fois le tour de la ville, et les Sacrificateurs sonneront du cor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Et quand ils sonneront en long avec le cor de bélier, aussitôt que vous entendrez le son du cor, tout le peuple jettera un grand cri de joie, et la muraille de la ville tombera sous soi, et le peuple montera chacun vis-à-vis de soi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Josué donc, fils de Nun, appela les Sacrificateurs, et leur dit: Portez l’Arche de l’alliance, et que sept Sacrificateurs prennent sept cors de bélier devant l’Arche de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Il dit aussi au peuple: Passez, et faites le tour de la ville, et que tous ceux qui seront armés passent devant l’Arche de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Et quand Josué eut parlé au peuple, les sept Sacrificateurs qui portaient les sept cors de bélier devant l’Eternel passèrent, et sonnèrent des cors, et l’Arche de l’alliance de l’Eternel les suivait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Et ceux qui étaient armés allaient devant les Sacrificateurs qui sonnaient des cors; mais l’arrière-garde suivait après l’Arche; on sonnait des cors en marchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Or Josué avait commandé au peuple, en disant: Vous ne jetterez point de cris de joie, et vous ne ferez point entendre votre voix, et il ne sortira point un seul mot de votre bouche, jusqu’au jour que je vous dirai: Jetez des cris de joie; alors vous le ferez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Ainsi il fit faire le tour de la ville à l’Arche de l’Eternel, en tournant tout alentour une fois, puis ils revinrent au camp, et y logèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Ensuite Josué se leva de bon matin, et les Sacrificateurs portèrent l’Arche de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Et les sept Sacrificateurs qui portaient les sept cors de bélier devant l’Arche de l’Eternel marchaient, et en allant ils sonnaient des cors; et ceux qui étaient armés allaient devant eux; puis l’arrière-garde suivait l’Arche de l’Eternel; on sonnait des cors en marchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Ainsi ils firent une fois le tour de la ville le second jour, et ils retournèrent au camp. Ils firent de même durant six jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Mais quand le septième jour fut venu, ils se levèrent dès le matin à l’aube du jour, et ils firent sept fois le tour de la ville en la même manière; ce jour-là seulement ils firent sept fois le tour de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Et à la septième fois, comme les Sacrificateurs sonnaient des cors, Josué dit au peuple: Jetez des cris de joie, car l’Eternel vous a donné la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'La ville sera mise en interdit à l’Eternel, elle et toutes les choses qui y sont, seulement Rahab la paillarde vivra, elle et tous ceux qui seront avec elle dans la maison; parce qu’elle a caché soigneusement les messagers que nous avions envoyés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Mais quoi qu’il en soit, donnez-vous garde de l’interdit, de peur que vous ne vous mettiez en interdit, en prenant de l’interdit, et que vous ne mettiez le camp d’Israël en interdit, et que vous ne le troubliez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Mais tout l’argent et l’or, et les vaisseaux d’airain et de fer seront sanctifiés à l’Eternel; ils entreront au trésor de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Le peuple donc jeta des cris de joie, et on sonna des cors. Et quand le peuple eut ouï le son des cors, et eut jeté un grand cri de joie, la muraille tomba sous soi; et le peuple monta dans la ville, chacun vis-à-vis de soi, et ils la prirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Et ils mirent entièrement à la façon de l’interdit et passèrent au fil de l’épée tout ce qui était dans la ville, depuis l’homme jusqu’à la femme; depuis l’enfant jusqu’au vieillard, même jusqu’au boeuf, au menu bétail, et à l’âne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Mais Josué dit aux deux hommes qui avaient reconnu le pays: Entrez dans la maison de cette femme paillarde, et la faites sortir de là, avec tout ce qui lui appartient, selon que vous lui avez juré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Les jeunes hommes donc qui avaient reconnu le pays, entrèrent, et firent sortir Rahab, et son père, et sa mère, et ses frères, avec tout ce qui lui appartenait, et ils firent sortir aussi toutes les familles qui lui appartenaient, et les mirent hors du camp d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Puis ils brûlèrent par feu la ville et tout ce qui y était; seulement ils mirent l’argent et l’or et les vaisseaux d’airain et de fer au trésor de la Maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Ainsi Josué sauva la vie à Rahab la paillarde, et à la maison de son père, et à tous ceux qui lui appartenaient; et elle a habité au milieu d’Israël jusqu’à aujourd’hui, parce qu’elle avait caché les messagers que Josué avait envoyés pour reconnaître Jérico.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Et, en ce temps-là Josué jura, disant: Maudit soit devant l’Eternel l’homme qui se mettra à rebâtir cette ville de Jérico; il la fondera sur son premier-né, et il posera ses portes sur son puîné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Et l’Eternel fut avec Josué; et sa renommée se répandit dans tout le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Mais les enfants d’Israël se rendirent coupables au sujet de l’interdit: car Hacan fils de Carmi, fils de Zabdi, fils de Zara, de la Tribu de Juda, prit de l’interdit, et la colère de l’Eternel s’enflamma contre les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Car Josué envoya de Jérico des hommes vers Haï, qui était près de Bethaven du côté de l’Orient de Béthel, et leur parla, en disant: Montez, et reconnaissez le pays. Ces hommes donc montèrent et reconnurent Haï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Et étant retournés vers Josué, ils lui dirent: Que tout le peuple n’y monte point mais qu’ environ deux mille ou trois mille hommes y montent, et ils battront Haï. Ne fatigue point tout le peuple en l’envoyant là; car ils sont peu de gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Ainsi environ trois mille hommes du peuple y montèrent, mais ils s’enfuirent de devant ceux de Haï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Et ceux de Haï en tuèrent environ trente-six hommes; car ils les poursuivirent depuis le devant de la porte jusqu’à Sébarim, et les battirent en une descente; et le coeur du peuple se fondit, et devint comme de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Alors Josué déchira ses vêtements, et se jeta, le visage contre terre, devant l’Arche de l’Eternel, jusqu’au soir, lui et les Anciens d’Israël, et ils jetèrent de la poudre sur leur tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Et Josué dit: Hélas! Seigneur Eternel, pourquoi as-tu fait si magnifiquement passer le Jourdain à ce peuple, pour nous livrer entre les mains de l’Amorrhéen, et nous faire périr? Ô que n’avons-nous eu dans l’esprit de demeurer, et que ne sommes-nous demeurés au delà du Jourdain!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Hélas! Seigneur, que dirai-je, puisque Israël a tourné le dos devant ses ennemis?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Les Cananéens et tous les habitants du pays l’entendront, et nous envelopperont, et ils retrancheront notre nom de dessus la terre; et que feras-tu à ton grand Nom?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Alors l’Eternel dit à Josué: Lève-toi; pourquoi te jettes-tu ainsi le visage contre terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israël a péché; ils ont transgressé mon alliance que je leur avais commandée, même ils ont pris de l’interdit; même ils en ont dérobé; même ils ont menti, et même ils l’ont mis dans leurs hardes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'C’est pourquoi les enfants d’Israël ne pourront subsister devant leurs ennemis; ils tourneront le dos devant leurs ennemis; car ils sont devenus un interdit. Je ne serai plus avec vous si vous n’exterminez d’entre vous l’interdit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Lève-toi; sanctifie le peuple, et dis: Sanctifiez-vous pour demain; car ainsi a dit l’Eternel le Dieu d’Israël; il y a de l’interdit parmi toi, ô Israël! tu ne pourras subsister devant tes ennemis jusqu’à ce que vous ayez ôté l’interdit d’entre vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Vous vous approcherez donc le matin selon vos Tribus; et la Tribu que l’Eternel aura saisie s’approchera selon les familles; et la famille que l’Eternel aura saisie s’approchera selon les maisons; et la maison que l’Eternel aura saisie, s’approchera selon les têtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Alors celui qui aura été saisi en l’interdit, sera brûlé au feu, lui et tout ce qui est à lui; à cause qu’il a transgressé l’alliance de l’Eternel, et qu’il a commis une infamie en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Josué donc se leva de bon matin, et fit approcher Israël selon ses Tribus; et la Tribu de Juda fut saisie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Puis il fit approcher les familles de Juda, et il saisit la famille de ceux qui étaient descendus de Zara. Puis il fit approcher par têtes la famille de ceux qui étaient descendus de Zara, et Zabdi fut saisi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Et quand il eut fait approcher sa maison par têtes, Hacan fils de Carmi, fils de Zabdi, fils de Zara, de la Tribu de Juda, fut saisi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Alors Josué dit à Hacan: Mon fils, donne, je te prie, gloire à l’Eternel le Dieu d’Israël, et fais-lui confession; et déclare-moi, je te prie, ce que tu as fait; ne me le cache point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Et Hacan répondit à Josué, et dit: J’ai péché, il est vrai, contre l’Eternel le Dieu d’Israël, et j’ai fait telle et telle chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'J’ai vu parmi le butin un beau manteau de Sinhar, deux cents sicles d’argent, et un lingot d’or du poids de cinquante sicles; je les ai convoités, je les ai pris; et voilà ces choses sont cachées en terre au milieu de ma tente, et l’argent est sous le manteau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Alors Josué envoya des messagers qui coururent à cette tente; et voici le manteau était caché dans la tente d’Hacan, et l’argent sous le manteau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Ils les prirent donc du milieu de la tente, et les apportèrent à Josué, et à tous les enfants d’Israël, et ils les déployèrent devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Alors Josué et tout Israël avec lui, prenant Hacan fils de Zara, et l’argent, et le manteau, et le lingot d’or, et ses fils, et ses filles, et ses boeufs, et ses ânes, et ses brebis, et sa tente, et tout ce qui était à lui, les firent venir en la vallée de Hacor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Et Josué dit: Pourquoi nous as-tu troublés? l’Eternel te troublera aujourd’hui. Et tous les Israélites l’assommèrent de pierres, et les brûlèrent au feu, après les avoir assommés de pierres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Et ils dressèrent sur lui un grand monceau de pierres, qui dure jusqu’à ce jour. Et l’Eternel apaisa l’ardeur de sa colère; c’est pourquoi ce lieu-là a été appelé jusqu’à aujourd’hui, la vallée de Hacor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Puis l’Eternel dit à Josué: Ne crains point, et ne t’effraye de rien. Prends avec toi tout le peuple propre à la guerre, et te lève, monte contre Haï; regarde, j’ai livré entre tes mains le Roi de Haï, et son peuple, et sa ville, et son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Et tu feras à Haï, et à son Roi, comme tu as fait à Jérico, et à son Roi: seulement vous en pillerez pour vous le butin, et les bêtes. Mets des gens en embuscade derrière la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Josué donc se leva avec tout le peuple propre à la guerre, pour monter contre Haï, et Josué choisit trente mille hommes forts et vaillants, et les envoya de nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Et il leur commanda, disant: Voyez, vous qui serez en embuscade derrière la ville, ne vous éloignez pas beaucoup de la ville, mais tenez-vous prêts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Et moi, et tout le peuple qui est avec moi, nous nous approcherons de la ville, et quand ils sortiront à notre rencontre, comme ils ont fait la première fois, nous nous enfuirons de devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Ainsi ils sortiront après nous, jusqu’à ce que nous les ayons attirés hors de la ville; car ils diront: Ils fuient devant nous comme la première fois; parce que nous fuirons devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Mais vous vous lèverez de l’embuscade, et vous vous saisirez de la ville; car l’Eternel votre Dieu la livrera entre vos mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Et quand vous l’aurez prise, vous y mettrez le feu; vous ferez selon la parole de l’Eternel. Regardez, je vous l’ai commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Josué donc les envoya, et ils allèrent se mettre en embuscade, et se tinrent entre Béthel et Haï, à l’Occident de Haï; mais Josué demeura cette nuit-là avec le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Puis Josué se leva de bon matin, et dénombra le peuple; et il monta lui et les anciens d’Israël, devant le peuple vers Haï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Et tout le peuple propre à la guerre, qui était avec lui, monta, et s’approcha, et ils vinrent vis-à-vis de la ville, et se campèrent du côté du Septentrion de Haï; et la vallée était entre lui et Haï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Il prit aussi environ cinq mille hommes, lesquels il mit en embuscade entre Béthel et Haï, à l’Occident de Haï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Et le peuple mit tout le camp qui était du côté du Septentrion contre la ville, et l’embuscade, à l’Occident de la ville; et cette nuit-là Josué s’avança dans la vallée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Or il arriva qu’aussitôt que le Roi de Haï l’eut vu, les hommes de la ville se hâtèrent, et se levèrent de bon matin, et au temps marqué le Roi et tout son peuple sortirent à la campagne contre Israël pour le combattre. Or il ne savait pas qu’il y eût des gens en embuscade contre lui derrière la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Alors Josué et tout Israël feignant d’être battus à leur rencontre s’enfuirent par le chemin du désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'C’est pourquoi tout le peuple qui était dans la ville, fut assemblé à grand cri pour les poursuivre; et ils poursuivirent Josué; et ils furent ainsi attirés hors de la ville;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'De sorte qu’il ne resta pas un seul homme dans Haï ni dans Béthel qui ne sortît après Israël; ils laissèrent la ville ouverte, et ils poursuivirent Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Alors l’Eternel dit à Josué: Etends l’étendard qui est en ta main, vers Haï; car je la livrerai entre tes mains, et Josué étendit vers la ville l’étendard qui était en sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Et ceux qui étaient en embuscade se levèrent incontinent du lieu où ils étaient; ils commencèrent à courir aussitôt que Josué eut étendu sa main; ils vinrent dans la ville, la prirent, et ils se hâtèrent de mettre le feu dans la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Et les gens de Haï se tournant derrière eux, regardèrent; et voici, la fumée de la ville montait jusqu’au ciel: et il n’y eut en eux aucune force pour fuir: et le peuple qui fuyait vers le désert, se tourna contre ceux qui le poursuivaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Et Josué et tout Israël voyant que ceux qui étaient en embuscade avaient pris la ville, et que la fumée de la ville montait, se retournèrent, et frappèrent les gens de Haï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Les autres aussi sortirent de la ville contr’eux; ainsi ils furent enveloppés par les Israélites, les uns deçà, et les autres delà; et ils furent tellement battus qu’on n’en laissa aucun qui demeurât en vie, ou qui échappât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Ils prirent aussi vif le Roi de Haï, et le présentèrent à Josué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Et quand les Israélites eurent achevé de tuer tous les habitants de Haï sur les champs, au désert où ils les avaient poursuivis, et que tous furent tombés sous le tranchant de l’épée, jusqu’à être entièrement défaits, tous les Israélites se tournèrent vers Haï, et la frappèrent au tranchant de l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Et tous ceux qui tombèrent ce jour-là, tant des hommes que des femmes, furent au nombre de douze mille, tous gens de Haï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Et Josué ne retira point sa main, laquelle il avait élevée en haut avec l’étendard, qu’on n’eut entièrement défait à la façon de l’interdit, tous les habitants de Haï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Seulement les Israélites pillèrent pour eux les bêtes et le butin de cette ville-là, suivant ce que l’Eternel avait commandé à Josué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Josué donc brûla Haï, et la mit en un monceau perpétuel de ruines, et en un désert, jusqu’à aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Puis il fit pendre le Roi de Haï à une potence, jusqu’au temps du soir: et comme le soleil se couchait, Josué fit commandement, qu’on descendît de la potence son corps mort, lequel on jeta à l’entrée de la porte de la ville, et on dressa sur lui un grand amas de pierres, qui y est demeuré jusqu’à aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Alors Josué bâtit un autel à l’Eternel, le Dieu d’Israël, sur la montagne de Hébal;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'Comme Moïse serviteur de l’Eternel l’avait commandé aux enfants d’Israël, ainsi qu’il est écrit au Livre de la Loi de Moïse. Il fit cet autel de pierres entières sur lesquelles personne n’avait levé le fer; et ils offrirent dessus des holocaustes à l’Eternel, et sacrifièrent des sacrifices de prospérités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Il écrivit aussi là sur des pierres un double de la Loi de Moïse, laquelle Moïse avait mise par écrit devant les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Et tout Israël, et ses anciens, et ses Officiers, et ses juges étaient au deçà et au delà de l’Arche, vis-à-vis des Sacrificateurs qui sont de la race de Lévi, portant l’Arche de l’alliance de l’Eternel, tant les étrangers que les Hébreux naturels; une moitié étant contre la montagne de Guérizim, et l’autre moitié contre la montagne de Hébal, comme Moïse serviteur de l’Eternel l’avait commandé, pour bénir le peuple d’Israël la première fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Et après cela il lut tout haut toutes les paroles de la Loi, tant les bénédictions que les malédictions, selon tout ce qui est écrit au Livre de la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Il n’y eut rien de tout ce que Moïse avait commandé, que Josué ne lût tout haut devant toute l’assemblée d’Israël, des femmes, et des petits enfants, et des étrangers conversant parmi eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Or dès que tous les Rois qui étaient au deçà du Jourdain, en la montagne, et en la plaine, et sur tout le rivage de la grande mer, jusques contre le Liban, savoir les Héthiens, les Amorrhéens, les Cananéens, les Phérésiens, les Héviens, et les Jébusiens, eurent appris ces choses,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'Ils s’assemblèrent tous pour faire la guerre à Josué et à Israël, d’un commun accord.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Mais les habitants de Gabaon ayant entendu ce que Josué avait fait à Jérico, et à Haï;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'Usèrent de finesse, car ils se mirent en chemin, et contrefirent les ambassadeurs, et prirent de vieux sacs sur leurs ânes, et de vieux outres de vin qui avaient été rompus, et qui étaient rapetassés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'Et ils avaient en leurs pieds de vieux souliers raccommodés, et de vieux habits sur eux; et tout le pain de leur provision était sec, et moisi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Et étant venus à Josué au camp en Guilgal, ils lui dirent, et aux principaux d’Israël: Nous sommes venus d’un pays éloigné; maintenant donc traitez alliance avec nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Et les principaux d’Israël répondirent à ces Héviens: Peut-être que vous habitez parmi nous; et comment traiterions-nous alliance avec vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Mais ils dirent à Josué: Nous sommes tes serviteurs. Alors Josué leur dit: Qui êtes-vous? et d’où venez-vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Ils lui répondirent: Tes serviteurs sont venus d’un pays fort éloigné, sur la renommée de l’Eternel ton Dieu; car nous avons entendu sa renommée, et toutes les choses qu’il a faites en Egypte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'Et tout ce qu’il a fait aux deux Rois des Amorrhéens, qui étaient au delà du Jourdain, à Sihon Roi de Hesbon, et à Hog Roi de Basan qui demeurait à Hastaroth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Et nos anciens et tous les habitants de notre pays nous ont dit ces mêmes paroles-ci: Prenez avec vous de la provision pour le chemin, et allez au-devant d’eux, et leur dites: Nous sommes vos serviteurs, et maintenant traitez alliance avec nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'C’est ici notre pain. Nous le prîmes de nos maisons tout chaud pour notre provision, le jour que nous en sortîmes pour venir vers vous; mais maintenant voici, il est devenu sec, et moisi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Et ce sont ici les outres de vin que nous avions remplies tout neufs, et voici ils se sont rompus; et nos habits et nos souliers sont usés à cause du long chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Ces hommes donc avaient pris de la provision; mais on ne consulta point la bouche de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Car Josué fit la paix avec eux, et traita avec eux cette alliance, qu’il les laisserait vivre; et les principaux de l’assemblée leur en firent le serment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Mais il arriva trois jours après l’alliance traitée avec eux, qu’ils apprirent que c’étaient leurs voisins, et qu’ils habitaient parmi eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Car les enfants d’Israël partirent, et vinrent en leurs villes le troisième jour. Or leurs villes étaient Gabaon, Képhira, Beeroth, et Kirjath-jéharim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Et les enfants d’Israël ne les frappèrent point, parce que les principaux de l’assemblée leur avaient fait serment par l’Eternel le Dieu d’Israël; mais toute l’assemblée murmura contre les principaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Alors tous les principaux dirent à toute l’assemblée: Nous leur avons fait serment par l’Eternel le Dieu d’Israël; c’est pourquoi nous ne les pouvons pas maintenant toucher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Faisons leur ceci, et qu’on les laisse vivre, afin qu’il n’y ait point de colère contre nous, à cause du serment que nous leur avons fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Les principaux donc leur dirent qu’ils vivraient; mais ils furent employés à couper le bois, et à puiser l’eau pour toute l’assemblée, comme les principaux le leur dirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Car Josué les appela, et leur parla, en disant: Pourquoi nous avez-vous trompés, en nous disant: Nous sommes fort éloignés de vous; puisque vous habitez parmi nous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Maintenant donc vous êtes maudits, et il y aura toujours des esclaves d’entre vous, et des coupeurs de bois, et des puiseurs d’eau pour la maison de mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Et ils répondirent à Josué, et dirent: Après qu’il a été exactement rapporté à tes serviteurs, que l’Eternel ton Dieu avait commandé à Moïse son serviteur qu’on vous donnât tout le pays, et qu’on exterminât tous les habitants du pays de devant vous, nous avons craint extrêmement pour nos personnes à cause de vous, et nous avons fait ceci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Et maintenant nous voici entre tes mains, fais nous comme il te semblera bon et juste de nous faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Il leur fit donc ainsi, et il les délivra de la main des enfants d’Israël, tellement qu’ils ne les tuèrent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Et en ce jour-là Josué les établit coupeurs de bois et puiseurs d’eau pour l’assemblée, et pour l’autel de l’Eternel, jusqu’à aujourd’hui dans le lieu qu’il choisirait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Or quand Adoni-tsédek, Roi de Jérusalem, eut entendu que Josué avait pris Haï, et qu’il l’avait entièrement détruite à la façon de l’interdit, ayant fait à Haï et à son Roi, comme il avait fait à Jérico et à son Roi, et que les habitants de Gabaon avaient fait la paix avec les Israélites, et étaient parmi eux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'On craignit beaucoup, parce que Gabaon était une grande ville, comme une ville Royale, et elle était plus grande que Haï; et parce que tous ses hommes étaient forts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'C’est pourquoi Adoni-tsédek, Roi de Jérusalem, envoya vers Horam Roi de Hébron, et vers Biréam, Roi de Jarmuth, et vers Japhiah, Roi de Lakis, et vers Débir, Roi de Héglon, pour leur dire:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Montez vers moi, et donnez-moi du secours afin que nous frappions Gabaon; car elle a fait la paix avec Josué, et avec les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Ainsi cinq Rois des Amorrhéens, savoir, le Roi de Jérusalem, le Roi de Hébron, le Roi de Jarmuth, le Roi de Lakis, et le Roi de Héglon, s’assemblèrent et montèrent eux et toutes leurs armées, et se campèrent contre Gabaon, et lui firent la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'C’est pourquoi ceux de Gabaon envoyèrent à Josué au camp à Guilgal, en disant: Ne retire point tes mains de tes serviteurs; monte promptement vers nous, et nous garantis, et donne-nous du secours; car tous les Rois des Amorrhéens qui habitent aux montagnes, se sont assemblés contre nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Josué donc monta de Guilgal, et avec lui tout le peuple qui était propre à la guerre, et tous les hommes forts et vaillants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Et l’Eternel dit à Josué: Ne les crains point; car je les ai livrés entre tes mains, et aucun d’eux ne subsistera devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Josué donc vint promptement à eux; et monta de Guilgal toute la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Et l’Eternel les mit en déroute devant Israël, qui en fit un grand carnage près de Gabaon; et les poursuivit par le chemin de la montagne de Beth-horon, et les battit jusqu’à Hazéka, et jusqu’à Makkéda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Et comme ils s’enfuyaient de devant Israël, et qu’ils étaient à la descente de Beth-horon, l’Eternel jeta des cieux sur eux de grosses pierres jusqu’à Hazéka, dont ils moururent; et il y en eut encore plus de ceux qui moururent des pierres de grêle, que de ceux que les enfants d’Israël tuèrent avec l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Alors Josué parla à l’Eternel, le jour que l’Eternel livra l’Amorrhéen aux enfants d’Israël, et dit en la présence d’Israël: Soleil, arrête-toi sur Gabaon, et toi Lune, sur la vallée d’Ajalon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Et le soleil s’arrêta, et la lune aussi s’arrêta, jusqu’à ce que le peuple se fût vengé de ses ennemis. Ceci n’est-il pas écrit au Livre du Droiturier? Le soleil donc s’arrêta au milieu des cieux et ne se hâta point de se coucher environ un jour entier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Et il n’y a point eu de jour semblable à celui-là, devant ni après, l’Eternel exauçant la voix d’un homme; car l’Eternel combattait pour les Israélites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Et Josué et tout Israël avec lui, s’en retourna au camp à Guilgal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Au reste ces cinq Rois-là s’étaient enfuis, et s’étaient cachés dans une caverne à Makkéda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Et on avait rapporté à Josué, en disant: On a trouvé les cinq Rois cachés dans une caverne à Makkéda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Et Josué avait dit: Roulez de grandes pierres à l’entrée de la caverne, mettez près d’elle quelques hommes pour les garder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Mais vous, ne vous arrêtez point, poursuivez vos ennemis, et les défaites jusqu’au dernier, et ne les laissez point entrer dans leurs villes; car l’Eternel votre Dieu les a livrés en vos mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Et quand Josué avec les enfants d’Israël eut achevé d’en faire une très grande boucherie, jusqu’à les détruire entièrement, et que ceux d’entr’eux qui étaient échappés se furent retirés dans les villes fermées de murailles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Tout le peuple retourna en paix au camp vers Josué à Makkéda; et personne ne remua sa langue contre aucun des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Alors Josué dit: Ouvrez l’entrée de la caverne, et amenez-moi ces cinq Rois hors de la caverne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Et ils le firent ainsi, et ils amenèrent hors de la caverne ces cinq Rois: le Roi de Jérusalem, le Roi de Hébron, le Roi de Jarmuth, le Roi de Lakis et le Roi de Héglon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Et après qu’ils eurent amené à Josué ces cinq Rois hors de la caverne, Josué appela tous les hommes d’Israël, et dit aux Capitaines des gens de guerre qui étaient allés avec lui: Approchez-vous, mettez vos pieds sur le cou de ces Rois; et ils s’approchèrent, et mirent leurs pieds sur leur cou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Alors Josué leur dit: Ne craignez point, et ne soyez point effrayés, fortifiez-vous, et vous renforcez; car l’Eternel fera ainsi à tous vos ennemis contre lesquels vous combattez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Et après cela Josué les frappa, et les fit mourir, et les fit pendre à cinq potences; et ils demeurèrent pendus à ces potences jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Et comme le soleil se couchait Josué fit commandement qu’on les ôtât de ces potences, et on les jeta dans la caverne où ils s’étaient cachés; et on mit à l’entrée de la caverne de grandes pierres qui y sont demeurées jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Josué prit aussi en ce même jour Makkéda, et la frappa au tranchant de l’épée, et défit à la façon de l’interdit son Roi et ses habitants, et ne laissa échapper aucune personne qui fût dans cette ville; et il fit au Roi de Makkéda comme il avait fait au Roi de Jérico.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Après cela Josué et tout Israël avec lui passa de Makkéda à Libna, et fit la guerre à Libna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Et l’Eternel la livra aussi entre les mains d’Israël, avec son Roi, et il la frappa au tranchant de l’épée, et ne laissa échapper aucune personne qui fût dans cette ville; et il fit à son Roi comme il avait fait au Roi de Jérico.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Ensuite Josué et tout Israël avec lui passa de Libna à Lakis, et se campa devant elle, et lui fit la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Et l’Eternel livra Lakis entre les mains d’Israël, qui la prit le deuxième jour, et la frappa au tranchant de l’épée, et toutes les personnes qui étaient dedans, comme il avait fait à Libna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Alors Horam Roi de Guézer monta pour secourir Lakis; et Josué le frappa, lui et son peuple, de sorte qu’il n’en laissa pas échapper un seul homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Après cela Josué et tout Israël avec lui passa de Lakis à Héglon; et ils se campèrent devant elle, et lui firent la guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Et ils la prirent ce jour-là même, et la frappèrent au tranchant de l’épée; et Josué défit à la façon de l’interdit en ce même jour-là toutes les personnes qui y étaient, comme il avait fait à Lakis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Puis Josué et tout Israël avec lui monta d’Héglon à Hébron, et ils lui firent la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'Et ils la prirent, et la frappèrent au tranchant de l’épée, avec son Roi, et toutes ses villes, et toutes les personnes qui y étaient; il n’en laissa échapper aucune, comme il avait fait à Héglon; et il la défit à la façon de l’interdit, et toutes les personnes qui y étaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Ensuite Josué et tout Israël avec lui rebroussa chemin vers Débir, et ils lui firent la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Et il la prit avec son Roi, et toutes ses villes; et ils les frappèrent au tranchant de l’épée, et défirent à la façon de l’interdit toutes les personnes qui y étaient; il n’en laissa échapper aucune. Il fit à Débir et à son Roi comme il avait fait à Hébron, et comme il avait fait à Libna et à son Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Josué donc frappa tout ce pays-là, la montagne, et le Midi, et la plaine, et les pentes des montagnes, et tous leurs Rois; il n’en laissa échapper aucun; et il défit à la façon de l’interdit toutes les personnes vivantes, comme l’Eternel le Dieu d’Israël l’avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Ainsi Josué les battit depuis Kadès-barné jusqu’à Gaza, et tout le pays de Gosen, jusqu’à Gabaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Il prit donc tout à la fois ces Rois-là et leur pays; parce que l’Eternel, le Dieu d’Israël, combattait pour Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Après quoi Josué et tout Israël avec lui s’en retournèrent au camp à Guilgal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Et aussitôt que Jabin, Roi de Hatsor, eut appris ces choses, il envoya à Jobab Roi de Madon, et au Roi de Simron, et au Roi d’Acsaph,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'Et aux Rois qui habitaient vers le Septentrion, aux montagnes et dans la campagne, vers le Midi de Kinnaroth, et dans la plaine, et à Naphoth-Dor vers l’Occident;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'Au Cananéen qui était à l’Orient et à l’Occident, à l’Amorrhéen, à l’Héthien, au Phérésien, au Jébusien dans les montagnes, et a l’Hévien sous Hermon au pays de Mitspa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Ils sortirent donc et toutes leurs armées avec eux, un grand peuple, comme le sable qui est sur le bord de la mer, par leur multitude; il y avait aussi des chevaux et des chariots en fort grand nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Tous ces Rois-là s’étant donnés assignation, vinrent, et se campèrent ensemble près des eaux de Mérom, pour combattre contre Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Et l’Eternel dit à Josué: Ne les crains point; car demain, environ cette même heure, je les livrerai tous, blessés à mort, devant Israël; tu couperas les jarrets à leurs chevaux, et brûleras au feu leurs chariots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Josué donc et tous les gens de guerre avec lui vinrent promptement contr’eux près des eaux de Mérom, et les chargèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Et l’Eternel les livra entre les mains d’Israël, ils les battirent, et les poursuivirent jusqu’à Sidon la grande, et jusqu’aux eaux de Masréphoth, et jusqu’à la campagne de Mitspa, vers l’Orient, et ils les battirent tellement qu’ils n’en laissèrent échapper aucun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Et Josué leur fit comme l’Eternel lui avait dit; il coupa les jarrets de leurs chevaux, et brûla au feu leurs chariots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Et comme Josué s’en retournait en ce même temps, il prit Hatsor, et frappa son Roi avec l’épée; car Hatsor avait été auparavant la capitale de tous ces Royaumes-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Ils passèrent aussi toutes les personnes qui y étaient au tranchant de l’épée, les détruisant à la façon de l’interdit; il n’y resta aucune personne vivante, et on brûla au feu Hatsor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Josué prit aussi toutes les villes de ces Rois-là, et tous leurs Rois, et les passa au tranchant de l’épée, et il les détruisit à la façon de l’interdit, comme Moïse serviteur de l’Eternel l’avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Mais Israël ne brûla aucune des villes, qui étaient demeurées en leur état, excepté Hatsor, que Josué brûla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Et les enfants d’Israël pillèrent pour eux tout le butin de ces villes-là, et les bêtes; seulement ils passèrent au tranchant de l’épée tous les hommes, jusqu’à ce qu’ils les eussent exterminés; ils n’y laissèrent de reste aucune personne vivante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Comme l’Eternel l’avait commandé à Moïse son serviteur, ainsi Moïse l’avait commandé à Josué; et Josué le fit ainsi; de sorte qu’il n’omit rien de tout ce que l’Eternel avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Josué donc prit tout ce pays-là, la montagne, et tout le pays du Midi, avec tout le pays de Gosen, la plaine, et la campagne, la montagne d’Israël, et sa plaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'Depuis la montagne de Halak, qui monte vers Séhir, même jusqu’à Bahal-Gad en la campagne du Liban, sous la montagne de Hermon. Il prit aussi tous leurs Rois, et les battit, et les fit mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Josué fit la guerre plusieurs jours contre tous ces Rois-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Il n’y eut aucune ville qui fît la paix avec les enfants d’Israël, excepté les Héviens qui habitaient à Gabaon; ils les prirent toutes par guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Car cela venait de l’Eternel qu’ils endurcissaient leur coeur pour sortir en bataille contre Israël, afin qu’il les détruisît à la façon de l’interdit, sans qu’il leur fît aucune grâce; mais qu’il les exterminât, comme l’Eternel l’avait commandé à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'En ce temps-là aussi Josué vint et extermina les Hanakins des montagnes, de Hébron, de Débir, de Hanab, et de toute montagne de Juda, et de toute montagne d’Israël; Josué, dis-je, les détruisit à la façon de l’interdit avec leurs villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Il ne resta aucun des Hanakins au pays des enfants d’Israël; il en demeura de reste seulement à Gaza, à Gath, et à Asdod.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Josué donc prit tout le pays, suivant tout ce que l’Eternel avait dit à Moïse, et il le donna en héritage à Israël, selon leurs portions, et leurs Tribus; et le pays fut tranquille, sans avoir guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Or ce sont ici les Rois du pays que les enfants d’Israël frappèrent, et dont ils possédèrent le pays au delà du Jourdain vers le soleil levant, depuis le torrent d’Arnon jusqu’à la montagne de Hermon, et toute la campagne vers l’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Savoir Sihon, Roi des Amorrhéens, qui habitait à Hesbon, et qui dominait depuis Haroher qui est sur le bord du torrent d’Arnon, et depuis le milieu du torrent, et la moitié de Galaad, même jusqu’au torrent de Jabbok, qui est la frontière des enfants de Hammon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'Et depuis la campagne jusqu’à la mer de Kinnaroth vers l’Orient, et jusqu’à la mer de la campagne, qui est la mer salée, vers l’Orient, au chemin de Beth-jesimoth; et depuis le Midi au dessous d’Asdoth de Pisga.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'Et les contrées de Hog, Roi de Basan, qui était du reste des Réphaïms, et qui habitait à Hastaroth et à Edréhi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'Et qui dominait en la montagne de Hermon, et à Salca, et par tout Basan, jusqu’aux limites des Guésuriens et des Mahacathiens, et de la moitié de Galaad, frontière de Sihon, Roi de Hesbon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Moïse serviteur de l’Eternel, et les enfants d’Israël les battirent; et Moïse serviteur de l’Eternel en donna la possession aux Rubénites, et aux Gadites, et à la moitié de la Tribu de Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Et ce sont ici les Rois du pays que Josué et les enfants d’Israël frappèrent au deçà du Jourdain vers l’Occident, depuis Bahal-Gad, en la campagne du Liban, jusqu’à la montagne de Halak qui monte vers Séhir, et que Josué donna aux Tribus d’Israël en possession, selon leurs portions;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'Pays consistant en montagnes, et en plaines, et en campagnes, et en collines, et en pays de désert et de Midi; les Héthiens, les Amorrhéens, les Cananéens, les Phérésiens, les Héviens, et les Jébusiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Un Roi de Jérico; un Roi de Haï, laquelle était à côté de Béthel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'Un Roi de Jérusalem; un Roi de Hébron;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'Un Roi de Jarmuth; un Roi de Lakis;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'Un Roi d’Héglon; un Roi de Guézer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'Un Roi de Débir; un Roi de Guéder;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'Un Roi de Horma; un Roi de Harad;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'Un Roi de Libna; un Roi de Hadullam;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'Un Roi de Makkéda; un Roi de Béthel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'Un Roi de Tappuah; un Roi de Hépher;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'Un Roi d’Aphek; un Roi de Saron;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'Un Roi de Madon; un Roi de Hatsor;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'Un Roi de Simron-Meron; un Roi d’Acsaph;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'Un Roi de Tahanac; un Roi de Meguiddo;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'Un Roi de Kédès; un Roi de Joknéham de Carmel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'Un Roi de Dor, près de Naphoth-Dor; un Roi de Gojim, près de Guilgal;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'Un Roi de Tirtsa; en tout trente et un Rois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Or quand Josué fut devenu vieux, fort avancé en âge, l’Eternel lui dit: Tu es devenu vieux, fort avancé en âge, et il reste encore un fort grand pays à posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'C’est ici le pays qui demeure de reste, toutes les contrées des Philistins, et tout Guésuri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'Depuis Sihor, qui est au devant de l’Egypte, même jusqu’aux frontières de Hekron vers le Septentrion; cela est réputé des Cananéens; savoir les cinq gouvernements des Philistins, qui sont celui de Gaza, celui d’Asdod, celui d’Askélon, celui de Gath, et celui de Hekron, et les Hauviens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'Du côté du Midi tout le pays des Cananéens, et Méhara qui est aux Sidoniens, jusques vers Aphek, jusqu’aux frontières des Amorrhéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'Le pays aussi qui appartient aux Guibliens, et tout le Liban; vers le soleil levant, depuis Bahal-Gad, sous la montagne de Hermon, jusqu’à l’entrée de Hamath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Tous les habitants de la montagne depuis le Liban jusqu’aux eaux de Masréphoth; tous les Sidoniens; je les chasserai moi-même de devant les enfants d’Israël; fais seulement qu’on en jette les lots, afin qu’elle soit à Israël en héritage, comme je te l’ai commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Maintenant donc divise ce pays en héritage aux neuf Tribus, et à la moitié de la Tribu de Manassé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Avec laquelle les Rubénites et les Gadites ont pris leur héritage; lequel Moïse leur a donné au delà du Jourdain vers l’Orient, selon que Moïse serviteur de l’Eternel le leur a donné;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'Depuis Haroher, qui est sur le bord du torrent d’Arnon, et la ville qui est au milieu du torrent, et tout le plat pays de Médéba, jusqu’à Dibon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'Et toutes les villes de Sihon, Roi des Amorrhéens, qui régnait à Hesbon, jusqu’aux limites des enfants de Hammon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'Et Galaad, et les limites des Guésuriens et des Mahacathiens, et toute la montagne de Hermon, et tout Basan jusqu’à Salca;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'Tout le Royaume de Hog en Basan, lequel Hog régnait à Hastaroth, et à Edréhi, et était demeuré de reste des Réphaïms, lesquels Rois Moïse défit, et les déposséda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, '(Or les enfants d’Israël ne dépossédèrent point les Guésuriens et les Mahacathiens; mais les Guésuriens et les Mahacathiens ont habité parmi Israël jusqu’à ce jour.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Seulement il ne donna point d’héritage à la Tribu de Lévi; les sacrifices de l’Eternel, le Dieu d’Israël, faits par feu étant son héritage, comme il lui en avait parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Moïse donc donna un héritage à la Tribu des enfants de Ruben selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Et leurs bornes furent depuis Haroher qui est sur le bord du torrent d’Arnon, et la ville qui est au milieu du torrent, et tout le plat pays qui est près de Médéba.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesbon et toutes ses villes, qui étaient au plat pays; Dibon, et Bamoth-Bahal, et Beth-Bahal-mehon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Et Jahatsa, et Kédémoth, et Méphahath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Et Kirjathajim, et Sibma, et Tseretsahar en la montagne de la vallée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Et Beth-Péhor, et Asdoth de Pisga, et Beth-jesimoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'Et toutes les villes du plat pays, et tout le Royaume de Sihon, Roi des Amorrhéens qui régnait à Hesbon; lequel Moïse défit, avec les principaux de Madian, Evi, Rekem, Tsur, Hur, et Rébah, Princes relevant de Sihon, et habitant au pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Les enfants d’Israël firent passer aussi par l’épée Balaam fils de Béhor, le devin, avec les autres qui y furent tués.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Et les bornes des enfants de Ruben furent le Jourdain, et sa borne. Tel fut l’héritage des enfants de Ruben selon leurs familles, savoir ces villes-là, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Moïse donna aussi un héritage à la Tribu de Gad pour les enfants de Gad, selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Et leur pays fut Jahzer, et toutes les villes de Galaad, et la moitié du pays des enfants de Hammon, jusqu’à Haroher, qui est vis-à- vis de Rabba.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'Et depuis Hesbon jusqu’à Ramath-mitspé, et Bétonim, et depuis Mahanajim jusqu’aux frontières de Débir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'Et dans la vallée, Beth-haram, et Beth-nimra, et Succoth, et Tsaphon; le reste du Royaume de Sihon Roi de Hesbon, le Jourdain, et sa borne, jusqu’au bout de la mer de Kinnereth, au delà du Jourdain, vers l’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Tel fut l’héritage des enfants de Gad, selon leurs familles,; savoir ces villes-là et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Moïse aussi donna à la moitié de la Tribu de Manassé un héritage, qui est demeuré à la moitié de la Tribu des enfants de Manassé, selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Leur pays fut depuis Mahanajim, tout Basan, et tout le Royaume de Hog, Roi de Basan, et tous les bourgs de Jaïr qui sont en Basan, soixante villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'Et la moitié de Galaad, et Hastaroth, et Edréhi, villes du Royaume de Hog en Basan, furent aux enfants de Makir, fils de Manassé, savoir à la moitié des enfants de Makir, selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Ce sont là les pays que Moïse étant dans les campagnes de Moab avait partagés en héritage, de ce qui était au delà du Jourdain de Jérico, vers l’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Or Moïse ne donna point d’héritage à la Tribu de Lévi; car l’Eternel le Dieu d’Israël est leur héritage, comme il leur en a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Ce sont ici les terres que les enfants d’Israël eurent pour héritage au pays de Canaan, qu’Eléazar le Sacrificateur, et Josué, fils de Nun, et les chefs des pères des Tribus des enfants d’Israël leur partagèrent en héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Selon le sort de leur héritage, comme l’Eternel l’avait commandé par le moyen de Moïse, savoir à neuf Tribus, et à la moitié d’une Tribu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Car Moïse avait donné un héritage à deux Tribus, et à la moitié d’une Tribu au delà du Jourdain, mais il n’avait point donné d’héritage parmi eux aux Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Parce que les enfants de Joseph, savoir, Manassé et Ephraïm, faisaient deux Tribus; et on ne donna point de part aux Lévites dans le pays, excepté les villes pour y habiter avec leurs fauxbourgs pour leurs troupeaux, et pour le reste de leur bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Les enfants d’Israël firent comme l’Eternel l’avait commandé à Moïse, et ils partagèrent la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Or les enfants de Juda vinrent à Josué en Guilgal; et Caleb fils de Jéphunné Kénizien, lui dit: Tu sais la parole que l’Eternel a dite de moi, et de toi, à Moïse homme de Dieu, en Kadès-barné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'J’étais âgé de quarante ans quand Moïse serviteur de l’Eternel m’envoya de Kadès-barné pour reconnaître le pays, et je lui rapportai la chose comme elle était en mon coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Et mes frères qui étaient montés avec moi, faisaient fondre le coeur du peuple; mais je persévérai à suivre l’Eternel mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Et Moïse jura en ce jour-là disant: Si la terre sur laquelle ton pied a marché n’est à toi en héritage, et à tes enfants pour jamais; parce que tu as persévéré à suivre l’Eternel mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Or maintenant voici, l’Eternel m’a fait vivre selon qu’il en avait parlé; il y a déjà quarante-cinq ans que l’Eternel prononça cette parole à Moïse, lorsque Israël marchait par le désert, et maintenant voici, je suis aujourd’hui âgé de quatre-vingt et cinq ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Et je suis encore aujourd’hui aussi fort que j’étais le jour que Moïse m’envoya, et j’ai maintenant la même force que j’avais alors pour le combat, et pour aller et venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Maintenant donc donne-moi cette montagne, de laquelle l’Eternel parla en ce jour-là; car tu entendis en ce jour-là que les Hanakins y habitent, et qu’il y a de grandes villes fortes; peut-être que l’Eternel sera avec moi, et je les déposséderai, comme l’Eternel en a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Josué donc le bénit, et donna Hébron en héritage à Caleb, fils de Jéphunné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'C’est pourquoi Hébron fut à Caleb, fils de Jéphunné Kénizien, en héritage jusqu’à ce jour, parce qu’il avait persévéré à suivre l’Eternel, le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Or le nom d’Hébron était auparavant Kirjath-Arbah, et Arbah avait été un fort grand homme entre les Hanakins. Et le pays fut tranquille sans avoir guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Ce fut ici le sort de la Tribu des enfants de Juda selon leurs familles. Aux confins d’Edom, le désert de Tsin vers le Midi, fut le dernier bout de leurs pays vers le Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Tellement que leur frontière du côté du Midi fut le dernier bout de la mer salée, depuis le bras qui regarde vers le Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'Et elle devait sortir vers le Midi de la montée de Hakrabbim, et passer à Tsin; et, montant du Midi de Kadès-barné passer à Hetsron; puis montant vers Addar se tourner vers Karkah;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Puis passant vers Hatsmon, sortir au torrent d’Egypte; tellement que les extrémités, de cette frontière devaient se rendre à la mer. Ce sera là, dit Josué, votre frontière du côté du Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Et la frontière vers l’Orient sera la mer salée jusqu’au bout du Jourdain; et la frontière du côté du Septentrion sera depuis le bras de la mer, qui est au bout du Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Et cette frontière montera jusqu’à Bethhogla, et passera du côté du Septentrion de Bethharaba; et cette frontière montera jusqu’à la pierre de Bohan, fils de Ruben.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Puis cette frontière montera vers Débir, depuis la vallée de Hacor, même vers le Septentrion, regardant Guilgal; laquelle est vis-à-vis de la montée d Adummim, qui est au Midi du torrent; puis cette frontière passera vers les eaux de Hen-semès, et ses extrémités se rendront à Hen-roguel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Puis cette frontière montera par la vallée du fils de Hinnom, jusqu’au côté de Jébusi vers le Midi, qui est Jérusalem; puis cette frontière montera jusqu’au sommet de la montagne, qui est vis-à-vis de la vallée de Hinnom, vers l’Occident, et qui est au bout de la vallée des Réphaïms, vers le Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Et cette frontière s’alignera depuis le sommet de la montagne jusqu’à la fontaine des eaux de Nephtoah, et sortira vers les villes de la montagne de Héphron; puis cette frontière s’alignera à Bahala, qui est Kirjath-jéharim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Et cette frontière se tournera depuis Bahala vers l’Occident, jusqu’à la montagne de Séhir; puis elle passera jusqu’au côté de la montagne de Jeharim vers le Septentrion, qui est Késalon; puis descendant à Beth-semes, elle passera à Timna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Et cette frontière sortira jusqu’au côté de Hekron, vers le Septentrion, et cette frontière s’alignera vers Sikkeron; puis ayant passé la montagne de Bahala, elle sortira à Jabnéël; tellement que les extrémités de cette frontière se rendront à la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Or la frontière du côté de l’Occident sera ce qui est vers la grande mer, et ses limites. Ce furent les frontières des enfants de Juda de tous les côtés, selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Au reste on avait donné à Caleb, fils de Jéphunné, une portion au milieu des enfants de Juda, suivant le commandement de l’Eternel fait à Josué, savoir Kirjath-Arbah, or Arbah était père de Hanak; et Kirjath-Arbah c’est Hébron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Et Caleb déposséda de là les trois fils de Hanak, savoir Sesaï, Ahiman, et Talmaï, enfants de Hanak.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Et de là il monta vers les habitants de Débir, dont le nom était auparavant Kirjath-sépher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Et Caleb dit: Je donnerai ma fille Hacsa pour femme à celui qui battra Kirjath-sépher, et la prendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Et Hothniel fils de Kénaz, frère de Caleb, la prit; et Caleb lui donna sa fille Hacsa pour femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Et il arriva que comme elle s’en allait, elle l’incita à demander à son père un champ; puis elle descendit impétueusement de dessus son âne, et Caleb lui dit: Qu’as-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Et elle répondit: Donne-moi un présent; puisque tu m’as donné une terre sèche, donne-moi aussi des sources d’eau. Et il lui donna les fontaines de dessus et les fontaines de dessous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'C’est ici l’héritage de la Tribu des enfants de Juda selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Les villes de l’extrémité de la Tribu des enfants de Juda près des limites d’Edom, tirant vers le Midi, furent Kabtséel, Héder, Jagur,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Kina, Dimona, Hadhada,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Kedès, Hatsor, Jithnan,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Ziph, Télem, Béhaloth,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Hatsor, Hadatta, Kérijoth, Hetsron qui est Hatsor,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam, Semah, Molada,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Hatsar-gadda, Hesmon, Beth-pelet,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Hatsar-suhal, Béersebah, Bizjotheja,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Bahala, Hijim, Hetsem,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Eltolad, Kesil, Hormah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Tsiklag, Madmanna, Sansanna,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaoth, Silhim, Hajin et Rimmon; en tout vingt-neuf villes, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'Dans la plaine, Estaol, Tsorha, Asna,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Zanoah, Hengannim, Tappuah, Hénam,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmuth, Hadullam, Soco, Hazeka,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Saharajim, Hadithajim, Guedera et Guederothajim; quatorze villes, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Tsénan, Hedasa, Migdal-Gad,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dilhan, Mitspé, Jokthéël,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lakis, Botskath, Héglon,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Cabbon, Lahmas, Kithlis,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Guederoth, Beth-Dahon, Nahama, et Makkéda; seize villes, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Hether, Hasan,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jiphtah, Asna, Netsib,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Kehila, Aczib et Maresa; neuf villes, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Hekron, et les villes de son ressort, et ses villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Depuis Hekron, tirant même vers la mer, toutes celles qui sont joignant le ressort d’Asdod, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdod, les villes de son ressort, et ses villages, Gaza, les villes de son ressort, et ses villages, jusqu’au torrent d’Egypte; et la grande mer, et ses limites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Et dans la montagne, Samir, Jattir, Soco,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Danna, Kirjath-sanna, qui est Débir,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Hanab, Estemo, Hanim,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gosen, Holon, et Guilo; onze villes et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, Duma, Hesehan,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Janum, Beth-tappuah, Apheka,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Humta, Kirjath-Arbah, qui est Hébron, et Tsihor; neuf villes, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Mahon, Carmel, Ziph, Juta,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jizrehel, Jokdeham, Zanoah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kajin, Guibha, et Timna; dix villes, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhul, Beth-tsur, Guédor,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maharath, Beth-hanoth, et Eltekon; six villes, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kirjath-bahal, qui est Kirjath-jéharim, et Rabba; deux villes, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'Au désert, Beth-haraba, Middin, Secaca,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Nibsan, et la ville du sel, et Henguédi: six villes et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Au reste, les enfants de Juda ne purent point déposséder les Jébusiens qui habitaient à Jérusalem; c’est pourquoi le Jébusien a demeuré avec les enfants de Juda à Jérusalem jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Puis le sort échut aux enfants de Joseph, depuis le Jourdain de Jérico aux eaux de Jérico vers l’Orient, qui est le désert; montant de Jérico par la montagne jusqu’à Béthel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Et cette frontière devait sortir de Béthel vers Luz, puis passer sur les confins de l’Arkien jusqu’à Hataroth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Et elle devait descendre tirant vers l’Occident, aux confins du Japhletien, jusqu’aux confins de Beth-horon la basse, et jusqu’à Guézer; de sorte que ses extrémités se devaient rendre à la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Ainsi les enfants de Joseph, savoir Manassé et Ephraïm, prirent leur héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Or la frontière des enfants d’Ephraïm selon leurs familles était telle, que la frontière de leur héritage vers l’Orient fut Hatroth- addar, jusqu’à Beth-horon la haute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Et cette frontière devait sortir vers la mer en Micmethah du côté du Septentrion; et cette frontière devait se tourner vers l’Orient jusqu’à Tahanath-Silo, et passant du côté d’Orient, se rendre à Janoah;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Puis descendre de vers Janoah à Hataroth, et vers Naharath, et se rencontrer à Jérico, et sortir au Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Et cette frontière devait aller de Tappuah tirant vers la mer, jusqu’au torrent de Kana; tellement que ses extrémités se devaient rendre à la mer. Ce fut là l’héritage de la Tribu des enfants d’Ephraïm, selon leurs familles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Avec les villes qui furent séparées pour les enfants d’Ephraïm parmi l’héritage des enfants de Manassé; toutes ces villes, dis- je, avec leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Or ils ne dépossédèrent point les Cananéens qui habitaient à Guézer; c’est pourquoi les Cananéens ont habité parmi Ephraïm jusqu’à ce jour; mais ils ont été tributaires, et asservis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Il y eut aussi un sort pour la Tribu de Manassé qui fut le premier- né de Joseph. Quant à Makir premier-né de Manassé, et père de Galaad, parce qu’il fut un homme belliqueux, il eut Galaad et Basan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Puis le reste des enfants de Manassé eut ce sort, selon ses familles; savoir les enfants d’Abihézer, les enfants de Helek, les enfants d’Asriël, les enfants de Sekem, les enfants de Hépher, et les enfants de Semidah. Ce sont là les enfants mâles de Manassé fils de Joseph, selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Or Tselophcad fils de Hépher fils de Galaad, fils de Makir, fils de Manassé, n’eut point de fils, mais des filles; et ce sont ici leurs noms, Mahla, Noha, Hogla, Milca et Tirtsa;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Lesquelles vinrent se présenter devant Eléazar le Sacrificateur, et devant Josué, fils de Nun, et devant les principaux du peuple, en disant: L’Eternel a commandé à Moïse qu’on nous donnât un héritage parmi nos frères; c’est pourquoi on leur donna un héritage parmi les frères de leur père, selon le commandement de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Et dix portions échurent à Manassé, outre le pays de Galaad et de Basan, qui étaient au delà du Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Car les filles de Manassé eurent un héritage parmi ses enfants; et le pays de Galaad fut pour le reste des enfants de Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Or la frontière de Manassé fut du côté d’Aser, venant à Micmethah, qui était au devant de Sichem; puis cette frontière devait aller à main droite vers les habitants de Hen-Tappuah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Or le pays de Tappuah appartenait à Manassé; mais Tappuah qui était près des confins de Manassé, appartenait aux enfants d’Ephraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'De là cette frontière devait descendre au torrent de Kana, tirant vers le Midi du torrent. Ces villes-là sont à Ephraïm parmi les villes de Manassé. Au reste, la frontière de Manassé était au côté du Septentrion du torrent, et ses extrémités se devaient rendre à la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Ce qui était vers le Midi était à Ephraïm, et ce qui était vers le Septentrion, était à Manassé, et il avait la mer pour sa borne; et, du côté du Septentrion les frontières se rencontraient en Aser, et en Issacar, du côté d’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Car Manassé eut aux quartiers d’Issacar et d’Aser, Beth-séan, et les villes de son ressort; et Jibléham, et les villes de son ressort; et les habitants de Dor, et les villes de son ressort; et les habitants de Hendor, et les villes de son ressort; et les habitants de Tahanac, et les villes de son ressort; et les habitants de Meguiddo, et les villes de son ressort, qui sont trois contrées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Au reste, les enfants de Manassé ne purent point déposséder les habitants de ces villes-là, mais les Cananéens osèrent demeurer dans le même pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Mais depuis que les enfants d’Israël se furent fortifiés, ils rendirent les Cananéens tributaires; toutefois ils ne les dépossédèrent point entièrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Or les enfants de Joseph parlèrent à Josué, en disant: Pourquoi m’as-tu donné en héritage un seul lot, et une seule portion, vu que je suis un grand peuple, tant l’Eternel m’a béni jusqu’à présent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Et Josué leur dit: Si tu es un si grand peuple, monte à la forêt, et coupe-la, pour te faire place au pays des Phéréziens et des Réphaïms, si la montagne d’Ephraïm est trop étroite pour toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Et les enfants de Joseph répondirent: Cette montagne ne sera pas suffisante pour nous, et tous les Cananéens qui habitent au pays de la vallée, ont des chariots de fer, pour ceux qui habitent à Beth- séan, et aux villes de son ressort, et pour ceux qui habitent dans la vallée de Jizrehel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Josué donc parla à la maison de Joseph, savoir à Ephraïm et à Manassé, en disant: Tu es un grand peuple, et tu as de grandes forces, tu n’auras pas une portion seule.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Car tu auras la montagne; et parce que c’est une forêt, tu la couperas, et ses extrémités t’appartiendront; car tu en déposséderas les Cananéens, quoiqu’ils aient des chariots de fer, et qu ils soient puissants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Or toute l’assemblée des enfants d’Israël s’assembla à Silo, et ils posèrent là le Tabernacle d’assignation, après que le pays leur eut été assujetti.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Mais il était resté entre les enfants d’Israël sept Tribus, auxquelles on n’avait point distribué leur héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Et Josué dit aux enfants d’Israël: Jusques à quand vous porterez- vous lâchement à passer plus loin pour posséder le pays que l’Eternel le Dieu de vos pères vous a donné?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Prenez d’entre vous trois hommes de chaque Tribu lesquels j’enverrai; ils se mettront en chemin, ils traverseront le pays, et ils en traceront une figure selon leur héritage, puis ils s’en reviendront auprès de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Ils se la diviseront en sept portions, Juda demeurera dans ses limites du côté du Midi; et la maison de Joseph demeurera dans ses limites du côté du Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Vous donc faites une figure du pays en sept parts, et apportez-la- moi ici; puis je jetterai ici le sort pour vous devant l’Eternel notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Car il n’y a point de portion pour les Lévites parmi vous; parce que la Sacrificature de l’Eternel est leur héritage. Quant à Gad et à Ruben, et à la moitié de la Tribu de Manassé, ils ont pris leur héritage au delà du Jourdain, vers l’Orient, que Moïse, serviteur de l’Eternel, leur a donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Ces hommes-là donc se levèrent, et s’en allèrent; et Josué commanda à ceux qui s’en allaient de faire une figure du pays, en leur disant: Allez et traversez le pays, et faites-en une figure, puis revenez auprès de moi, et je jetterai ici le sort pour vous devant l’Eternel à Silo.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Ces hommes-là donc s’en allèrent, et passèrent par le pays, et en firent une figure dans un livre selon les villes en sept parties; puis ils revinrent à Josué au camp à Silo.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Et Josué jeta le sort pour eux à Silo devant l’Eternel; et Josué partagea là le pays aux enfants d’Israël selon leurs parts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Et le sort de la Tribu des enfants de Benjamin selon leurs familles, sortit, et la contrée de leur sort leur échut entre les enfants de Juda et les enfants de Joseph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Et leur frontière du côté du Septentrion fut depuis le Jourdain; et cette frontière devait monter à côté de Jérico vers le Septentrion, puis monter en la montagne tirant vers l’Occident; de sorte que ses extrémités se devaient rendre au désert de Beth-aven.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Puis cette frontière devait passer de là vers Luz, à côté de Luz, qui est Béthel tirant vers le Midi; et cette frontière devait descendre à Hatroth-addar, près de la montagne qui est du côté du Midi de Beth-horon la basse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Et cette frontière devait s’aligner et tourner au coin Occidental qui regarde vers le Midi, depuis la montagne qui est vis-à-vis de Beth-horon, vers le Midi; tellement que ses extrémités devaient se rendre à Kirjath-bahal, qui est Kirjath-jéharim, ville des enfants de Juda. C’est là le côté d’Occident.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Mais le côté Méridional est depuis le bout de Kirjath-jéharim; et cette frontière devait sortir vers l’Occident, puis elle devait sortir à la fontaine des eaux de Nephtoah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'Et cette frontière devait descendre au bout de la montagne qui est vis-à-vis de la vallée du fils de Hinnom, et laquelle est dans la vallée des Réphaïms, vers le Septentrion; et descendre par la vallée de Hinnom jusqu’au côté de Jébusi vers le Midi, puis descendre à Henroguel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Et elle se devait aligner du côté du Septentrion, et sortir à Hen- sémes, et de là vers Gueliloth, qui est vis-à-vis de la montée d’Adummim, et descendre à la pierre de Bohan, fils de Ruben;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Et passer à côté de ce qui est vis-à-vis de Haraba vers le Septentrion, et descendre à Haraba.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Puis cette frontière devait passer à côté de Beth-hogla vers le Septentrion; de sorte que les extrémités de cette frontière se devaient rendre au bras de la mer salée, vers le Septentrion, au bout du Jourdain vers le Midi. Ce fut là la frontière du Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Et le Jourdain le devait borner du côté de l’Orient. Ce fut là l’héritage des enfants de Benjamin selon ses frontières tout autour, selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Or les villes de la Tribu des enfants de Benjamin, selon leurs familles, devaient être, Jérico, Beth-hogla, Hemekketsis,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Beth-haraba, Tsémarajim, Béthel,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Hauvin, Para, Hophra,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Képhar-hammonaï, Hophni, et Guébah; douze villes, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gabaon, Rama, Beeroth,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Mitspé, Képhira, Motsa,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Jirpeël, Taréala,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Tsélah, Eleph, Jébusi, qui est Jérusalem, Guibhath, et Kirjath; quatorze villes, et leurs villages. Tel fut l’héritage des enfants de Benjamin selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Le deuxième sort échut à Siméon, pour la Tribu des enfants de Siméon selon leurs familles, et leur héritage fut parmi l’héritage des enfants de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Et ils eurent dans leur héritage Béer-sebah, Sebah, Molada,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Hatsar-suhal, Bala, Hetsem,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltolad, Bethul, Horma,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Tsiklag, Beth-marcaboth, Hatsar-susa,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Beth-lebaoth et Saruhen; treize villes et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Hajin, Rimmon, Hether, et Hasan; quatre villes et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'Et tous les villages qui étaient autour de ces villes-là jusqu’à Balath-béer, qui est Rama du Midi. Tel fut l’héritage de la Tribu des enfants de Siméon, selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'L’héritage des enfants de Siméon fut pris du lot des enfants de Juda; car la part des enfants de Juda était trop grande pour eux; c’est pourquoi les enfants de Siméon eurent leur héritage parmi le leur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Le troisième sort monta pour les enfants de Zabulon, selon leurs familles; et la frontière de leur héritage fut jusqu’à Sarid.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Et leur frontière devait monter vers le quartier devers la mer, même jusqu’à Marhala, puis se rencontrer à Dabbeseth, et de là au torrent qui est vis-à-vis de Jokneham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Or cette frontière devait retourner de Sarid vers l’Orient, au soleil levant vers les confins de Kislothtabor, puis sortir vers Dabrath, et monter à Japhiah;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Puis de là passer vers l’Orient, au Levant, à Guitta-hépher qui est Hittakatsin, puis sortir, à Rimmon-Methoar, qui est Neha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Puis cette frontière devait tourner du côté du Septentrion à Hannathon; et ses extrémités devaient se rendre en la vallée de Jiphtahel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Avec Kattath, Nahalal, Simron, Jidéala, et Beth-lehem; il y avait douze villes, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Tel fut l’héritage des enfants de Zabulon selon leurs familles; ces villes-là, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Le quatrième sort échut à Issacar, pour les enfants d’Issacar, selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Et leur contrée fut ce qui est vers Jizrehel, Kesulloth, Sunem,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Hapharjim, Sion, Anaharath,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Rabbith, Kisjon, Ebets,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Remeth, Hen-gannim, Hen-hadda et Beth-patsets.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Et la frontière se devait rencontrer à Tabor et vers Sabatsim, et à Beth-semes; tellement que les extrémités de leur frontière se devaient rendre au Jourdain; seize villes, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Tel fut l’héritage de la Tribu des enfants d’Issacar, selon leurs familles, ces villes-là, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Le cinquième sort échut à la Tribu des enfants d’Aser, selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Et leur frontière fut Helkath, Hali, Beten, Acsaph,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Alammélec, Hamhad et Miséal; et elle se devait rencontrer à Carmel, au quartier vers la mer, et à Sihor vers Benath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Puis elle devait retourner vers le soleil levant, à Beth-dagon, et se rencontrer en Zabulon, et à la vallée de Jiphtahel vers le Septentrion, et à Beth-hemek et Nehiel; puis sortir à main gauche vers Cabul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'Et Hébron, et Rehob, et Hammon, et Cana, jusqu’à Sidon la grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Puis la frontière devait retourner à Rama, même jusqu’à Tsor, ville forte; puis cette frontière devait retourner à Hosa; tellement que ses extrémités, se devaient rendre au quartier qui est vers la mer, depuis la portion tirant vers Aczib;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Avec Hummah, et Aphek, et Rehob; vingt-deux villes, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Tel fut l’héritage de la Tribu des enfants d’Aser, selon leurs familles; ces villes-là et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Le sixième sort échut aux enfants de Nephthali, pour les enfants de Nephthali, selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Et leur frontière fut depuis Heleph, et depuis Allon à Tsahannim, et Adami-nekeb, et Jabnéel jusqu’à Lakkum, tellement que ses extrémités se devaient rendre au Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Puis cette frontière devait retourner du côté d’Occident, vers Aznoth-Tabor, et sortir de là à Hukkok; tellement que du côté du Midi elle devait se rencontrer en Zabulon, et du côté d’Occident elle devait se rencontrer en Aser. Or jusqu’en Juda le Jourdain était au soleil levant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Au reste, les villes closes étaient Tsiddim, Tser, Hammath, Rakkath, Kinnereth,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adama, Rama, Hatsor,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kédès, Edréhi, Hen-Hatsor,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Jireon, Migdal-el, Harem, Beth-hanath et Beth-semes; dix-neuf villes et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Tel fut l’héritage de la Tribu des enfants de Nephthali, selon leurs familles; ces villes-là, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Le septième sort échut à la Tribu des enfants de Dan selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Et la contrée de leur héritage fut, Tsorah, Estaol, Hir-semes,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Sahalabim, Ajalon, Jithla,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Elon, Timnatha, Hekron,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Elteké, Guibbethon, Bahalath,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehud, Bené-berak, Gath-rimmon,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Me-jarkon, et Rakkon, avec les limites qui sont vis-à-vis de Japho.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Or la contrée qui était échue aux enfants de Dan, était trop petite pour eux; c’est pourquoi les enfants de Dan montèrent, et combattirent contre Lesem, et la prirent, et la frappèrent au tranchant de l’épée, et la possédèrent, et y habitèrent; et ils appelèrent Lesem, Dan, du nom de Dan leur père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Tel fut l’héritage de la Tribu des enfants de Dan selon leurs familles; ces villes-là, et leurs villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Au reste après qu’on eut achevé de partager le pays selon ses confins, les enfants d’Israël donnèrent un héritage parmi eux à Josué fils de Nun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Selon le commandement de l’Eternel; ils lui donnèrent la ville qu’il demanda; savoir Timnath-sérah en la montagne d’Ephraïm; et il bâtit la ville, et y habita.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Ce sont là les héritages qu’Eléazar le Sacrificateur, et Josué, fils de Nun, et les chefs des pères des Tribus des enfants d’Israël partagèrent par sort en Silo, devant l’Eternel, à l’entrée du Tabernacle d’assignation, et ils achevèrent ainsi de partager le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Puis l’Eternel parla à Josué en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Parle aux enfants d’Israël, et leur dis: Etablissez-vous les villes de refuge desquelles je vous ai parlé par le moyen de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'Afin que le meurtrier qui aura tué quelqu’un par ignorance, sans y penser, s’y enfuie, et elles vous seront pour refuge devant celui qui a le droit de venger le sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Et le meurtrier s’enfuira dans l’une de ces villes-là, et s’arrêtera à l’entrée de la porte de la ville, et il dira ses raisons aux Anciens de cette ville-là, lesquels l’écouteront, et le recevront chez eux dans la ville, et lui donneront un lieu, afin qu’il demeure avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Et quand celui qui a le droit de venger le sang le poursuivra, ils ne le livreront point en sa main; puisque c’est sans y penser qu’il a tué son prochain, et qu’il ne le haïssait point auparavant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Mais il demeurera dans cette ville-là, jusqu’à ce qu’il comparaisse devant l’assemblée en jugement, même jusqu’à la mort du souverain Sacrificateur qui sera en ce temps-là; alors le meurtrier retournera, et viendra dans sa ville et dans sa maison, à la ville dont il s’en sera fui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Ils consacrèrent donc Kédès dans la Galilée en la montagne de Nephthali; et Sichem en la montagne d’Ephraïm, et Kirjath-Arbah, qui est Hébron, en la montagne de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Et au delà du Jourdain de Jérico vers le Levant ils ordonnèrent de la Tribu de Ruben, Betser au désert dans le plat pays, et Ramoth en Galaad, de la Tribu de Gad, et Golan en Basan, de la Tribu de Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Ce furent là les villes assignées à tous les enfants d’Israël, et à l’étranger demeurant parmi eux, afin que quiconque aurait tué quelqu’un par ignorance s’enfuît là, et ne mourût point de la main de celui qui a le droit de venger le sang, jusqu’à ce qu’il comparût devant l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Or les chefs des pères des Lévites vinrent à Eléazar le Sacrificateur, et à Josué, fils de Nun, et aux chefs des pères des Tribus des enfants d’Israël,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'Et leur parlèrent, à Silo dans le pays de Canaan, en disant: L’Eternel a commandé par le moyen de Moïse qu’on nous donnât des villes pour habiter, et leurs faubourgs pour nos bêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Et ainsi les enfants d’Israël donnèrent de leur héritage aux Lévites, suivant le commandement de l’Eternel, ces villes-ci avec leurs faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Et on tira au sort pour les familles des Kéhathites. Or il échut par sort aux enfants d’Aaron le Sacrificateur qui étaient d’entre les Lévites, treize villes, de la Tribu de Juda, et de la Tribu des Siméonites, et de la Tribu de Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Et il échut par sort au reste des enfants de Kéhath dix villes des familles de la Tribu d’Ephraïm, et de la Tribu de Dan, et de la moitié de la Tribu de Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Et les enfants de Guerson eurent par sort treize villes, des familles de la Tribu d’Issacar, et de la Tribu d’Aser, et de la Tribu de Nephthali, et de la demi-Tribu de Manassé en Basan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Et les enfants de Mérari selon leurs familles, eurent douze villes, de la Tribu de Ruben, et de la Tribu de Gad, et de la Tribu de Zabulon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Les enfants donc d’Israël donnèrent donc par sort aux Lévites ces villes-là avec leurs faubourgs, selon que l’Eternel l’avait commandé par le moyen de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Ils donnèrent donc de la Tribu des enfants de Juda, et de la Tribu des enfants de Siméon, ces villes, qui vont être nommées par leurs noms.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'Et elles furent pour ceux des enfants d’Aaron, qui étaient des familles des Kéhathites, enfants de Lévi, car le premier sort fut pour eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'On leur donna donc Kirjath-Arbah; or Arbah était père de Hanak, et Kirjath-Arbah est Hébron, en la montagne de Juda, avec ses faubourgs tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Mais quant au territoire de la ville, et à ses villages, on les donna à Caleb, fils de Jéphunné, pour sa possession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'On donna donc aux enfants d’Aaron le Sacrificateur pour villes de refuge au meurtrier, Hébron, avec ses faubourgs, et Libna, avec ses faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Et Jattir, avec ses faubourgs, et Estemoab, avec ses faubourgs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Et Holon, avec ses faubourgs, et Débir, avec ses faubourgs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Et Hajin, avec ses faubourgs, et Jutta, avec ses faubourgs; et Beth-semes, avec ses faubourgs; neuf villes de ces deux Tribus-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Et de la Tribu de Benjamin, Gabaon, avec ses faubourgs, et Guebah, avec ses faubourgs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Hanathoth, avec ses faubourgs, et Halmon, avec ses faubourgs; quatre villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Toutes les villes des enfants d’Aaron Sacrificateurs, furent treize villes, avec leurs faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Or quant aux familles des enfants de Kéhath Lévites, qui étaient le reste des enfants de Kéhath, il y eut dans leur sort des villes de la Tribu d’Ephraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'On leur donna donc pour villes de refuge au meurtrier, Sichem, avec ses faubourgs, en la montagne d’Ephraïm, et Guézer avec ses faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Et Kibtsajim, avec ses faubourgs, et Beth-horon, avec ses faubourgs; quatre villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Et de la Tribu de Dan, Elteké, avec ses faubourgs; Guibbethon, avec ses faubourgs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajalon, avec ses faubourgs, Gath-rimmon, avec ses faubourgs; quatre villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Et de la demi-Tribu de Manassé, Tahanac, avec ses faubourgs; et Gath-rimmon, avec ses faubourgs, deux villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Ainsi dix villes en tout avec leurs faubourgs, furent pour les familles des enfants de Kéhath, qui étaient de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'On donna aussi de la demi-Tribu de Manassé aux enfants de Guerson, qui étaient des familles des Lévites, pour villes de refuge au meurtrier, Golan en Basan, avec ses faubourgs, et Behestera, avec ses faubourgs; deux villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Et de la Tribu d’Issacar, Kisjon, avec ses faubourgs, Dobrath, avec ses faubourgs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmuth, avec ses faubourgs, Hengannim, avec ses faubourgs; quatre villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Et de la Tribu d’Aser, Miséal, avec ses faubourgs, Habdon, avec ses faubourgs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkath, avec ses faubourgs, et Rehob, avec ses faubourgs; quatre villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Et de la Tribu de Nephthali, pour villes de refuge au meurtrier, Kédès en Galilée avec ses faubourgs, Hammoth-Dor, avec ses faubourgs, et Kartan, avec ses faubourgs; trois villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Toutes les villes donc des Guersonites selon leurs familles, furent treize villes, et leurs faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'On donna aussi de la Tribu de Zabulon aux familles des enfants de Mérari, qui étaient les Lévites qui restaient, Jokneham, avec ses faubourgs, Karta, avec ses faubourgs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimnah, avec ses faubourgs, et Nahalal, avec ses faubourgs; quatre villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Et de la Tribu de Ruben, Betser, avec ses faubourgs, et Jahasa, avec ses faubourgs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kédémoth, avec ses faubourgs, et Méphahat, avec ses faubourgs; quatre villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Et de la Tribu de Gad, pour villes de refuge au meurtrier, Ramoth en Galaad, avec ses faubourgs, et Mahanajim, avec ses faubourgs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Hesbon, avec ses faubourgs, et Jahzer, avec ses faubourgs; en tout quatre villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Toutes ces villes-là furent données aux enfants de Mérari, selon leurs familles, qui étaient le reste des familles des Lévites; et leur sort fut de douze villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Toutes les villes des Lévites qui étaient parmi la possession des enfants d’Israël, furent quarante-huit, et leurs faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Chacune de ces villes avait ses faubourgs autour d’elle; il en devait être ainsi de toutes ces villes-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'L’Eternel donc donna à Israël tout le pays qu’il avait juré de donner à leurs pères; et ils le possédèrent, et y habitèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Et l’Eternel leur donna un parfait repos tout alentour, selon tout ce qu’il avait juré à leurs pères; et il n’y eut aucun de tous leurs ennemis qui subsistât devant eux; mais l’Eternel livra tous leurs ennemis en leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Il ne tomba pas un seul mot de toutes les bonnes paroles que l’Eternel avait dites à la maison d’Israël; tout arriva.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Alors Josué appela les Rubénites, et les Gadites, et la demi-Tribu de Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'Et leur dit: Vous avez gardé tout ce que Moïse serviteur de l’Eternel vous avait commandé, et vous avez obéi à ma parole, en tout ce que je vous ai commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Vous n’avez pas abandonné vos frères, quoiqu’il y ait longtemps que vous êtes avec eux, jusqu’à ce jour; mais vous avez pris garde à observer le commandement de l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Or maintenant l’Eternel votre Dieu a donné du repos à vos frères, selon qu’il leur en avait parlé. Maintenant donc retournez, et allez- vous-en dans vos demeures, en la terre de votre possession, laquelle Moïse, serviteur de l’Eternel, vous a donnée au delà du Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Prenez seulement bien garde de faire le commandement de la Loi que Moïse serviteur de l’Eternel vous a prescrite, qui est, que vous aimiez l’Eternel votre Dieu, et que vous marchiez dans toutes ses voies, et que vous gardiez ses commandements, et que vous vous attachiez à lui, et le serviez de tout votre coeur et de toute votre âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Puis Josué les bénit, et les renvoya; et ils s’en allèrent en leurs demeures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Or Moïse avait donné à la moitié de la Tribu de Manassé son héritage en Basan; et Josué donna à l’autre moitié son héritage avec leurs frères au deçà du Jourdain vers l’Occident. Au reste, Josué les renvoyant en leurs demeures, et les bénissant,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'Leur parla, en disant: Vous retournez en vos demeures avec de grandes richesses, et avec une fort grande quantité de bétail, avec argent, or, airain, fer, et vêtements, en fort grande abondance; partagez le butin de vos ennemis avec vos frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Ainsi donc les enfants de Ruben, et les enfants de Gad, et la demi- Tribu de Manassé s’en retournèrent, et partirent de Silo, qui est au pays de Canaan, d’avec les enfants d’Israël, pour s’en aller au pays de Galaad, en la terre de leur possession, de laquelle on les avait fait jouir, suivant ce que l’Eternel avait commandé par le moyen de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Or ils vinrent aux limites du Jourdain, qui étaient au pays de Canaan; et les enfants de Ruben, et les enfants de Gad, et la demi- Tribu de Manassé bâtirent là un autel, joignant le Jourdain, qui était un autel de grande apparence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Et les enfants d’Israël ouïrent dire: Voilà, les enfants de Ruben, et les enfants de Gad, et la demi-Tribu de Manassé ont bâti un autel regardant vers le pays de Canaan, sur les limites du Jourdain, du côté des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Les enfants donc d’Israël entendirent cela; et toute l’assemblée des enfants d’Israël s’assembla à Silo, pour monter en bataille contr’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Cependant les enfants d’Israël envoyèrent vers les enfants de Ruben, et vers les enfants de Gad, et vers la demi-Tribu de Manassé, au pays de Galaad, Phinées, fils d’Eléazar, le Sacrificateur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'Et avec lui dix Seigneurs; savoir un Seigneur de chaque maison des pères de toutes les Tribus d’Israël; car il y avait dans tous les milliers d’Israël un chef de chaque maison de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Ceux-ci donc vinrent vers les enfants de Ruben et vers les enfants de Gad, et vers la demi-Tribu de Manassé au pays de Galaad, et leur parlèrent, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Ainsi a dit toute l’assemblée de l’Eternel: Quel est ce crime que vous avez commis contre le Dieu d’Israël, vous détournant aujourd’hui de l’Eternel, en vous bâtissant un autel, pour vous révolter aujourd’hui contre l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Nous fut-ce peu de chose que l’iniquité de Péhor, de laquelle nous ne nous sommes pas encore bien nettoyés jusqu’à aujourd’hui, quoiqu’il en soit venu une plaie sur l’assemblée de l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Que vous vous détourniez aujourd’hui de l’Eternel, et que vous vous révoltiez aujourd’hui contre l’Eternel, afin que demain sa colère s’allume contre toute l’assemblée d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Toutefois si la terre de votre possession est souillée, passez en la terre de la possession de l’Eternel, dans laquelle est placé le pavillon de l’Eternel, et ayez votre possession parmi nous, et ne vous révoltez point contre l’Eternel, et ne soyez point rebelles contre nous, en vous bâtissant un autel, outre l’autel de l’Eternel notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Hacan, fils de Zara, ne commit-il pas un crime en prenant de l’interdit, et la colère de l’Eternel ne s’alluma-t-elle pas contre toute l’assemblée d’Israël? et cependant cet homme ne mourut pas seul pour son iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Mais les enfants de Ruben, et les enfants de Gad, et la demi-Tribu de Manassé répondirent, et dirent aux chefs des milliers d’Israël:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Le Fort, le Dieu, l’Eternel, le Fort, le Dieu, l’Eternel, sait lui-même, et Israël lui-même connaîtra si c’est par révolte, et si c’est pour commettre un crime contre l’Eternel; en ce cas-là ne nous protége point aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Si nous nous sommes bâti un autel pour nous détourner de l’Eternel, et si ç’a été pour y offrir holocauste, ou gâteau, ou si ç’a été pour y faire des sacrifices de prospérités, que l’Eternel lui-même nous en demande compte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Et si plutôt nous ne l’avons pas fait, pour crainte de ceci, savoir que vos enfants pourraient un jour parler ainsi à nos enfants, et leur dire: Qu’avez-vous à faire avec l’Eternel le Dieu d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Puisque l’Eternel a mis le Jourdain pour bornes entre nous et vous, enfants de Ruben, et enfants de Gad; vous n’avez point de part à l’Eternel. Et ainsi vos enfants feraient qu’un jour nos enfants cesseraient de craindre l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'C’est pourquoi nous avons dit: Mettons-nous maintenant à bâtir un autel, non pour holocauste, ni pour sacrifice;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'Mais afin qu’il serve de témoignage entre nous et vous, et entre nos générations après nous, pour faire le service de l’Eternel devant lui en nos holocaustes et nos sacrifices, et en nos sacrifices de prospérités; et afin qu’à l’avenir vos enfants ne disent point à nos enfants: Vous n’avez point de part à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'C’est pourquoi nous avons dit: Lorsqu’ils nous tiendront ce discours, ou à nos générations à l’avenir, nous leur dirons: Voyez la ressemblance de l’autel de l’Eternel que nos pères ont faite, non pour holocauste, ni pour sacrifice, mais afin qu’il soit témoin entre nous et vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'A Dieu ne plaise que nous nous révoltions contre l’Eternel, et que nous nous détournions aujourd’hui de l’Eternel, en bâtissant un autel pour l’holocauste, pour le gâteau, et pour le sacrifice, outre l’autel de l’Eternel notre Dieu, qui est devant son pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Or après que Phinées le Sacrificateur, et les principaux de l’assemblée, les chefs des milliers d’Israël qui étaient avec lui, eurent entendu les paroles que les enfants de Ruben, et les enfants de Gad, et les enfants de Manassé leur dirent, ils furent satisfaits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Et Phinées, fils d’Eléazar, le Sacrificateur dit aux enfants de Ruben, et aux enfants de Gad, et aux enfants de Manassé: Nous connaissons aujourd’hui que l’Eternel est parmi nous, puisque vous n’avez point commis ce crime contre l’Eternel; car dès lors vous avez délivré les enfants d’Israël de la main de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Ainsi Phinées, fils d’Eléazar, le Sacrificateur, et ces Seigneurs- là, s’en retournèrent d’avec les enfants de Ruben, et d’avec les enfants de Gad; du pays de Galaad au pays de Canaan, vers les enfants d’Israël, et leur rapportèrent le fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Et la chose plut aux enfants d’Israël; et les enfants d’Israël en bénirent Dieu, et ne parlèrent plus de monter en bataille contr’eux pour ruiner le pays où habitaient les enfants de Ruben, et les enfants de Gad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Et les enfants de Ruben, et les enfants de Gad appelèrent l’autel, Hed; car, dirent-ils, il est témoin entre nous que l’Eternel est le Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Or il arriva plusieurs jours après, que l’Eternel ayant donné du repos à Israël de tous leurs ennemis à l’environ, Josué était vieux, fort avancé en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Et Josué appela tout Israël, ses Anciens, et ses chefs, et ses juges, et ses officiers, et leur dit: Je suis devenu vieux, fort avancé en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Vous avez vu aussi tout ce que l’Eternel votre Dieu a fait à toutes ces nations, à cause de vous; car l’Eternel votre Dieu est celui qui combat pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Voyez, je vous ai partagé par sort en héritage selon vos Tribus, le pays de ces nations qui sont restées, depuis le Jourdain, et le pays de toutes les nations que j’ai exterminées, jusqu’à la grande mer, vers le soleil couchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Et l’Eternel votre Dieu les chassera de devant vous, et les dépossédera; et vous posséderez leur pays en héritage, comme l’Eternel votre Dieu vous en a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Fortifiez-vous donc de plus en plus, pour garder et faire tout ce qui est écrit au livre de la Loi de Moïse; afin que vous ne vous en détourniez ni à droite ni à gauche;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Et que vous ne vous mêliez point avec ces nations qui sont restées parmi vous; que vous ne fassiez point mention du nom de leurs dieux; et que vous ne fassiez jurer personne par eux, et que vous ne les serviez point, et ne vous prosterniez point devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Mais attachez-vous à l’Eternel votre Dieu, comme vous avez fait jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'C’est pour cela que l’Eternel a dépossédé de devant vous des nations grandes et fortes; et quant à vous, nul n’a subsisté devant vous jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Un seul homme d’entre vous en poursuivra mille; car l’Eternel votre Dieu est celui qui combat pour vous, comme il vous en a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Prenez donc garde soigneusement sur vos âmes, que vous aimiez l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Autrement si vous vous en détournez en aucune manière et que vous vous attachiez au reste de ces nations, savoir à ceux qui sont demeurés de reste avec vous, et que vous fassiez alliance avec eux, et que vous vous mêliez avec eux, et eux avec vous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'Sachez certainement que l’Eternel votre Dieu ne continuera plus à déposséder ces nations devant vous; mais elles vous seront en pièges, et en filet, et comme un fléau à vos côtés, et comme des épines à vos yeux, jusqu’à ce que vous périssiez de dessus cette bonne terre que l’Eternel votre Dieu vous a donnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Or voici, je m’en vais aujourd’hui par le chemin de toute la terre; et vous connaîtrez dans tout votre cœur, et dans toute votre âme qu’il n’est point tombé un seul mot de toutes les bonnes paroles que l’Eternel votre Dieu a dites de vous; tout vous est arrivé, il n’en est pas tombé un seul mot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Et il arrivera que comme toutes les bonnes paroles que l’Eternel votre Dieu vous avait dites vous sont arrivées; ainsi l’Eternel fera venir sur vous toutes les mauvaises paroles, jusqu’à ce qu’il vous ait exterminés de dessus cette bonne terre que l’Eternel votre Dieu vous a donnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Quand vous aurez transgressé l’alliance de l’Eternel votre Dieu, qu’il vous a commandée, et que vous serez allés servir d’autres dieux, et vous serez prosternés devant eux, la colère de l’Eternel s’enflammera contre vous, et vous périrez incontinent de dessus cette bonne terre qu’il vous a donnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Josué assembla aussi toutes les Tribus d’Israël en Sichem, et appela les Anciens d’Israël, et ses chefs, et ses juges, et ses officiers, qui se présentèrent devant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Et Josué dit à tout le peuple: Ainsi a dit l’Eternel le Dieu d’Israël: Vos pères, Taré père d’Abraham, et père de Nacor, ont anciennement habité au delà du fleuve, et ont servi d’autres dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Mais j’ai pris votre père Abraham de delà le fleuve, et je l’ai fait aller par tout le pays de Canaan, et j’ai multiplié sa postérité, et lui ai donné Isaac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Et j’ai donné à Isaac, Jacob et Esaü; et j’ai donné à Esaü le mont de Séhir, pour le posséder; mais Jacob et ses enfants sont descendus en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Puis j’ai envoyé Moïse et Aaron, et j’ai frappé l’Egypte, selon ce que j’ai fait au milieu d’elle; puis je vous en ai fait sortir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'J’ai donc fait sortir vos pères hors d’Egypte, et vous êtes venus aux quartiers qui sont vers la mer; et les Egyptiens ont poursuivi vos pères avec des chariots et des gens de cheval, jusqu’à la mer rouge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Alors ils crièrent à l’Eternel, et il mit une obscurité entre vous et les Egyptiens, et fit revenir sur eux la mer, qui les couvrit; et vos yeux virent ce que je fis contre les Egyptiens; puis vous avez demeuré longtemps au désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Ensuite je vous ai amenés au pays des Amorrhéens, qui habitaient au delà du Jourdain; et ils combattirent contre vous, mais je les livrai en vos mains, et vous avez pris possession de leur pays, et je les ai exterminés de devant vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Balak aussi, fils de Tsippor, Roi de Moab, s’éleva, et fit la guerre à Israël; et envoya appeler Balaam, fils de Béhor, pour vous maudire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Mais je ne voulus point écouter Balaam; il vous bénit très- expressément, et je vous délivrai de la main de Balak.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Et vous passâtes le Jourdain, et vîntes près de Jérico, et les Seigneurs de Jérico, et les Amorrhéens, les Phérésiens, les Cananéens, les Héthiens, les Guirgasiens, les Héviens, et les Jébusiens vous firent la guerre, et je les livrai en vos mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Et j’envoyai devant vous des frelons qui les chassèrent de devant vous, comme les deux Rois de ces Amorrhéens-là. Ce n’a point été par ton épée ou par ton arc.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Et je vous ai donné une terre que vous n’aviez point labourée, et des villes, que vous n’aviez point bâties, et vous y habitez; et vous mangez les fruits des vignes et des oliviers que vous n’avez point plantés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Maintenant donc craignez l’Eternel, et servez-le en intégrité, et en vérité; et ôtez les dieux que vos pères ont servis au delà du fleuve, et en Egypte; et servez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Que s’il vous déplaît de servir l’Eternel, choisissez-vous aujourd’hui qui vous voulez servir, ou les dieux que vos pères qui étaient au delà du fleuve, ont servis, ou les dieux des Amorrhéens, au pays desquels vous habitez; mais pour moi et ma maison, nous servirons l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Alors le peuple répondit, et dit: A Dieu ne plaise que nous abandonnions l’Eternel pour servir d’autres dieux!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Car l’Eternel notre Dieu est celui qui nous a fait monter, nous et nos pères, hors du pays d’Egypte, de la maison de servitude, et qui a fait devant nos yeux ces grands signes, et qui nous a gardés dans tout le chemin par lequel nous avons marché, et entre tous les peuples parmi lesquels nous avons passé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Et l’Eternel a chassé devant nous tous les peuples, et même les Amorrhéens qui habitaient en ce pays; nous servirons donc l’Eternel, car il est notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Et Josué dit au peuple: Vous ne pourrez pas servir l’Eternel, car c’est le Dieu saint, c’est le Dieu Fort, qui est jaloux, il ne pardonnera point votre révolte, ni vos péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Quand vous aurez abandonné l’Eternel, et que vous aurez servi les dieux des étrangers, il se retournera, et vous fera du mal, et il vous consumera après vous avoir fait du bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Et le peuple dit à Josué: Non; mais nous servirons l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Et Josué dit au peuple: Vous êtes témoins contre vous-mêmes que vous avez vous-mêmes choisi l’Eternel pour le servir. Et ils répondirent: Nous en sommes témoins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Maintenant donc ôtez les dieux des étrangers qui sont parmi vous, et tournez votre coeur vers l’Eternel le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Et le peuple répondit à Josué: Nous servirons l’Eternel notre Dieu, et nous obéirons à sa voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Josué donc traita alliance en ce jour-là avec le peuple; et il lui proposa des statuts et des ordonnances en Sichem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Et Josué écrivit ces paroles au livre de la Loi de Dieu. Il prit aussi une grande pierre, et l’éleva là sous un chêne qui était au Sanctuaire de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Et Josué dit à tout le peuple: Voici, cette pierre nous sera en témoignage; car elle a ouï toutes les paroles de l’Eternel lesquelles il nous a dites; et elle sera en témoignage contre vous, de peur qu’il n’arrive que vous mentiez contre votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Puis Josué renvoya le peuple, chacun en son héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Or il arriva après ces choses, que Josué, fils de Nun, serviteur de l’Eternel, mourut, âgé de cent dix ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Et on l’ensevelit dans les bornes de son héritage, à Timnath- sérah, qui est en la montagne d’Ephraïm, du côté du Septentrion de la montagne de Gahas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Et Israël servit l’Eternel tout le temps de Josué, et tout le temps des Anciens qui survécurent à Josué, qui avaient connu toutes les oeuvres de l’Eternel, qu’il avait faites pour Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'On ensevelit aussi à Sichem les os de Joseph, que les enfants d’Israël avaient apportés d’Egypte, en un endroit du champ que Jacob avait acheté cent pièces d’argent des enfants d’Hémor, père de Sichem; et ils furent en héritage aux enfants de Joseph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Et Eléazar, fils d’Aaron mourut, et on l’ensevelit au coteau de Phinées son fils, qui lui avait été donné en la montagne d’Ephraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Or il arriva qu’après la mort de Josué les enfants d’Israël consultèrent l’Eternel, en disant: Qui de nous montera le premier contre les Cananéens pour leur faire la guerre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Et l’Eternel répondit: Juda montera; voici, j’ai livré le pays entre ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Et Juda dit à Siméon son frère: Monte avec moi en mon partage, et nous ferons la guerre aux Cananéens; et j’irai aussi avec toi en ton partage. Ainsi Siméon alla avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Juda donc monta, et l’Eternel livra les Cananéens et les Phérésiens entre leurs mains; et ils battirent en Bézec dix mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Or ayant trouvé Adoni-bézec en Bézec, ils combattirent contre lui, et frappèrent les Cananéens et les Phérésiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Et Adoni-bézec s’enfuit, mais ils le poursuivirent; et l’ayant pris, ils lui coupèrent les pouces de ses mains et de ses pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Alors Adoni-bézec dit: Soixante et dix Rois, dont les pouces des mains et des pieds avaient été coupés, ont recueilli du pain sous ma table; comme j’ai fait, Dieu m’a ainsi rendu; et ayant été amené à Jérusalem, il y mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Or les enfants de Juda avaient fait la guerre contre Jérusalem, et l’avaient prise, et ils avaient fait passer ses habitants au tranchant de l’épée, et mis la ville en feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Puis les enfants de Juda étaient descendus pour faire la guerre aux Cananéens, qui habitaient dans les montagnes, et au Midi, et dans la plaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Juda donc s’en était allé contre les Cananéens qui habitaient à Hébron; or le nom d’Hébron était auparavant Kirjath-Arbah; et il avait frappé Sesaï, Ahiman et Talmaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Et de là il était allé contre les habitants de Débir, le nom de laquelle était auparavant Kirjath-sépher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Et Caleb avait dit: Qui frappera Kirjath-sépher et la prendra, je lui donnerai ma fille Hacsa pour femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Et Hothniël, fils de Kénas, frère puîné de Caleb, la prit; et Caleb lui donna sa fille Hacsa pour femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Et il arriva que comme elle s’en allait, elle l’incita à demander à son père un champ; puis elle descendit impétueusement de dessus son âne; et Caleb lui dit: Qu’as-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Et elle lui répondit: Donne-moi un présent; puisque tu m’as donné une terre sèche, donne-moi aussi des sources d’eaux. Et Caleb lui donna les fontaines du quartier de dessus, et les fontaines du quartier de dessous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Or les enfants du Kénien, beau-père de Moïse, étaient montés de la ville des palmes avec les enfants de Juda, au désert de Juda, qui est au Midi de Harad; parce qu’ils avaient marché et demeuré avec le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Puis Juda s’en alla avec Siméon son frère, et ils frappèrent les Cananéens qui habitaient à Tsephath, et la détruisirent à la façon de l’interdit, c’est pourquoi on appela la ville du nom de Horma.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Juda prit aussi Gaza avec ses confins; Askelon avec ses confins; et Hékron avec ses confins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Et l’Eternel fut avec Juda, et ils dépossédèrent les habitants de la montagne: mais ils ne dépossédèrent point les habitants de la vallée, parce qu’ils avaient des chariots de fer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Et on donna, selon que Moïse l’avait dit, Hébron à Caleb; qui en déposséda les trois fils de Hanak.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Quant aux enfants de Benjamin, ils ne dépossédèrent point le Jébusien qui habitait à Jérusalem; c’est pourquoi le Jébusien a habité avec les enfants de Benjamin à Jérusalem jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Ceux aussi de la maison de Joseph montèrent contre Bethel, et l’Eternel fut avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Et ceux de la maison de Joseph firent reconnaître Bethel, dont le nom était auparavant, Luz.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Et les espions virent un homme qui sortait de la ville, auquel ils dirent: Nous te prions de nous montrer un endroit par où l’on puisse entrer dans la ville, et nous te ferons grâce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Il leur montra donc un endroit par où l’on pouvait entrer dans la ville, et ils la firent passer au tranchant de l’épée; mais ils laissèrent aller cet homme-là, et toute sa famille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Puis cet homme s’en étant allé au pays des Héthiens, y bâtit une ville, et l’appela Luz, qui est son nom jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Manassé aussi ne déposséda point les habitants de Beth-séan, ni des villes de son ressort, ni les habitants de Tahanac, ni des villes de son ressort; ni les habitants de Dor, ni des villes de son ressort; ni les habitants de Jibléham, ni des villes de son ressort, ni les habitants de Meguiddo, ni des villes de son ressort; et les Cananéens osèrent encore habiter en ce pays-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Il est vrai qu’il arriva que quand Israël fut devenu plus fort, il rendît les Cananéens tributaires; mais il ne les déposséda pas entièrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Ephraïm aussi ne déposséda point les Cananéens qui habitaient à Guézer; mais les Cananéens habitèrent avec lui à Guézer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Zabulon ne déposséda point les habitants de Kitron, ni les habitants de Nahalol; mais les Cananéens habitèrent avec lui, et lui furent tributaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Aser ne déposséda point les habitants de Hacco, ni les habitants de Sidon, ni d’Ahlab, ni d’Aczib, ni d’Helba, ni d’Aphik, ni de Rehob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'Mais ceux d’Aser habitèrent parmi les Cananéens habitants du pays; car ils ne les dépossédèrent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Nephthali ne déposséda point les habitants de Beth-sémes, ni les habitants de Beth-hanath, mais il habita parmi les Cananéens habitants du pays; et les habitants de Beth-sémes, et de Beth-hanath lui furent tributaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Et les Amorrhéens tinrent les enfants de Dan fort resserrés dans la montagne, et ils ne souffraient point qu’ils descendissent dans la vallée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Et ces Amorrhéens-là osèrent encore habiter à Har-Hérés, à Ajalon, et à Sahalbim; mais la main de la maison de Joseph étant devenue plus forte, ils furent rendus tributaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Or la contrée des Amorrhéens était depuis la montée de Hakrabbim, depuis la roche, et au-dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Or l’Ange de l’Eternel monta de Guilgal à Bokim, et dit: Je vous ai fait monter hors d’Egypte, et je vous ai fait entrer au pays dont j’avais juré à vos pères, et j’ai dit: Je n’enfreindrai jamais mon alliance que j’ai traitée avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Et vous aussi vous ne traiterez point alliance avec les habitants de ce pays; vous démolirez leurs autels; mais vous n’avez point obéi à ma voix; qu’est-ce que vous avez fait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Et j’ai dit aussi: Je ne les chasserai point de devant vous, mais ils seront à vos côtés, et leurs dieux vous seront en piège.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Et il arriva qu’aussitôt que l’Ange de l’Eternel eut dit ces paroles à tous les enfants d’Israël, le peuple éleva sa voix, et pleura.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'C’est pourquoi ils appelèrent ce lieu-là Bokim; et ils sacrifièrent là à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Or Josué avait renvoyé le peuple, et les enfants d’Israël s’en étaient allés chacun à son héritage, pour posséder le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Et le peuple avait servi l’Eternel tout le temps de Josué, et tout le temps des Anciens qui avaient survécu à Josué, et qui avaient vu toutes les grandes oeuvres de l’Eternel, lesquelles il avait faites pour Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Puis Josué, fils de Nun, serviteur de l’Eternel, était mort, âgé de cent dix ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Et on l’avait enseveli dans les bornes de son héritage à Timnath- Hérés, en la montagne d’Ephraïm, du côté du Septentrion de la montagne de Gahas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Et toute cette génération aussi avait été recueillie avec ses pères; puis une autre génération s’était levée après eux, laquelle n’avait point connu l’Eternel, ni les oeuvres qu’il avait faites pour Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Les enfants d’Israël donc firent ce qui déplaît à l’Eternel, et servirent les Bahalins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Et ayant abandonné l’Eternel, le Dieu de leurs pères, qui les avait fait sortir du pays d’Egypte, ils allèrent après d’autres dieux, d’entre les dieux des peuples qui étaient autour d’eux, et ils se prosternèrent devant eux; ainsi ils irritèrent l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Ils abandonnèrent donc l’Eternel, et servirent Bahal et Hastaroth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Et la colère de l’Eternel s’enflamma contre Israël, et il les livra entre les mains de gens qui les pillèrent; et il les vendit en la main de leurs ennemis d’alentour, de sorte qu’ils ne purent plus se maintenir devant leurs ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Partout où ils allaient, la main de l’Eternel était contr’eux en mal, comme l’Eternel en avait parlé, et comme l’Eternel le leur avait juré, et ils furent dans de grandes angoisses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Et l’Eternel leur suscitait des Juges, qui les délivraient de la main de ceux qui les pillaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Mais ils ne voulaient pas même écouter leurs Juges, ils paillardaient après d’autres dieux; ils se prosternaient devant eux; ils se détournaient aussitôt du chemin par lequel leurs pères avaient marché, obéissant aux commandements de l’Eternel; mais eux ne faisaient pas ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Or quand l’Eternel leur suscitait des Juges, l’Eternel était aussi avec le Juge, et il les délivrait de la main de leurs ennemis pendant tout le temps du Juge; car l’Eternel se repentait pour les sanglots qu’ils jetaient à cause de ceux qui les opprimaient et qui les accablaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Puis il arrivait que quand le Juge mourait, ils se corrompaient de nouveau plus que leurs pères, allant après d’autres dieux pour les servir, et se prosterner devant eux; ils ne diminuaient rien de leur mauvaise conduite ni de leur train obstiné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'C’est pourquoi la colère de l’Eternel s’enflamma contre Israël, et il dit: Parce que cette nation a transgressé mon alliance que j’avais commandée à leurs pères, et qu’ils n ont point obéi à ma voix;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'Aussi je ne déposséderai plus de devant eux aucune des nations que Josué laissa quand il mourut;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'Afin d’éprouver par elles Israël, et voir s’ils garderont la voie de l’Eternel pour y marcher, comme leurs pères l’ont gardée, ou non.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'L’Eternel donc laissa ces nations-là sans les déposséder sitôt, et il ne les livra point entre les mains de Josué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Or ce sont ici les nations que l’Eternel laissa pour éprouver par elles Israël, savoir tous ceux qui n’avaient point eu connaissance de toutes les guerres de Canaan;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'Afin qu’au moins les générations des enfants d’Israël sussent et apprissent ce que c’est que la guerre; au moins ceux qui auparavant n’en avaient rien connu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'Ces nations donc furent les cinq Gouvernements des Philistins, et tous les Cananéens, les Sidoniens, et les Héviens, qui habitaient en la montagne du Liban, depuis la montagne de Bahal-hermon, jusqu’à l’entrée de Hamath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Ces nations, dis-je, servirent à éprouver Israël, pour voir s’ils obéiraient aux commandements de l’Eternel, lesquels il avait donnés à leurs pères par le moyen de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Ainsi les enfants d’Israël habitèrent parmi les Cananéens, les Héthiens, les Amorrhéens, les Phérésiens, les Héviens, et les Jébusiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'Et ils prirent leurs filles pour femmes, et ils donnèrent leurs filles à leurs fils, et servirent leurs dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Les enfants d’Israël firent donc ce qui déplaît à l’Eternel; ils oublièrent l’Eternel leur Dieu, et servirent les Bahalins, et les bocages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'C’est pourquoi la colère de l’Eternel s’enflamma contre Israël, et il les vendit en la main de Cusan-rischathajim, Roi de Mésopotamie. Et les enfants d’Israël furent asservis à Cusan-rischathajim huit ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Puis les enfants d’Israël crièrent à l’Eternel, et l’Eternel leur suscita un Libérateur qui les délivra, savoir Hothniël, fils de Kénas, frère puîné de Caleb.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Et l’Esprit de l’Eternel fut sur lui, et il jugea Israël, et sortit en bataille, et l’Eternel livra entre ses mains Cusan- rischathajim, Roi d’Aram; et sa main fut fortifiée contre Cusan- rischathajim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Et le pays fut en repos quarante ans. Puis Hothniel, fils de Kénas, mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Et les enfants d’Israël se mirent encore à faire ce qui déplaît à l’Eternel; et l’Eternel fortifia Héglon, Roi de Moab, contre Israël, parce qu’ils avaient fait ce qui déplaît à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Et Héglon assembla auprès de lui les enfants d’Hammon et d’Hamalec, et il alla, et frappa Israël, et ils s’emparèrent de la ville des palmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Et les enfants d’Israël furent asservis à Héglon, Roi de Moab, dix-huit ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Puis les enfants d’Israël crièrent à l’Eternel, et l’Eternel leur suscita un Libérateur, savoir Ehud, fils de Guéra Benjamite, duquel la main droite était serrée. Et les enfants d’Israël envoyèrent par lui un présent à Héglon, Roi de Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Or Ehud s’était fait une épée à deux tranchants, de la longueur d’une coudée, qu’il avait ceinte sous ses vêtements sur sa cuisse droite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'Et il présenta le don à Héglon, Roi de Moab; et Héglon était un homme fort gras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Or il arriva que quand il eut achevé de présenter le don, il reconduisit le peuple qui avait apporté le don.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Mais Ehud s’en étant retourné depuis les carrières de pierre, qui étaient vers Guilgal, il dit: Ô Roi! j’ai à te dire quelque chose en secret. Et il lui répondit: Tais-toi, et tous ceux qui étaient auprès de lui, sortirent de là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Et Ehud s’approchant de lui, qui était assis seul dans sa chambre d’Eté, il lui dit: J’ai un mot à te dire de la part de Dieu. Alors le Roi se leva du trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Et Ehud avançant sa main gauche, prit l’épée de dessus sa cuisse droite, et la lui enfonça dans le ventre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'Et la poignée entra après la lame, et la graisse serra tellement la lame, qu’il ne pouvait tirer l’épée du ventre; et il en sortit de la fiente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Après cela Ehud sortit par le porche, fermant après soi les portes de la chambre, laquelle il ferma à la clef.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Ainsi il sortit; et les serviteurs d’Héglon vinrent, et regardèrent, et voilà, les portes de la chambre étaient fermées à la clef; et ils dirent: Sans doute il est à ses affaires dans sa chambre d’Eté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Et ils attendirent tant qu’ils en furent honteux; et voyant qu’il n’ouvrait point les portes de la chambre, ils prirent la clef, et l’ouvrirent; et voici, leur Seigneur était étendu mort à terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Mais Ehud échappa tandis qu’ils s’amusaient, et passa les carrières de pierre, et se sauva à Séhira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Et quand il y fut entré, il sonna de la trompette en la montagne d’Ephraïm, et les enfants d’Israël descendirent avec lui en la montagne; et il marchait devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Et il leur dit: Suivez-moi, car l’Eternel a livré entre vos mains les Moabites vos ennemis. Ainsi ils descendirent après lui, et se saisissant des passages du Jourdain contre les Moabites, ils ne laissèrent passer personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Et en ce temps-là ils frappèrent des Moabites environ dix mille hommes, tous en bon état, et tous vaillants, et il n’en échappa aucun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'En ce jour-là donc Moab fut humilié sous la main d’Israël; et le pays fut en repos quatre-vingts ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Et après lui fut en sa place Samgar, fils d’Hanath, qui frappa six cents Philistins avec un aiguillon à boeufs, et qui délivra Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Mais les enfants d’Israël se mirent encore à faire ce qui déplaît à l’Eternel, après qu’Ehud fut mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'C’est pourquoi l’Eternel les vendit en la main de Jabin, Roi de Canaan, qui régnait en Hatsor, et de l’armée duquel Sisera était le chef, qui demeurait à Haroseth des Nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Et les enfants d’Israël crièrent à l’Eternel; car Jabin avait neuf cents chariots de fer, et il avait violemment opprimé les enfants d’Israël durant vingt ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'En ce temps-là Débora Prophétesse, femme de Lappidoth, jugeait Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Et Débora se tenait sous un palmier entre Rama et Bethel, en la montagne d’Ephraïm; et les enfants d’Israël montaient vers elle pour être jugés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Or elle envoya appeler Barac, fils d’Abinoham de Kédés de Nephthali, et lui dit: L’Eternel le Dieu d’Israël n’a-t-il pas commandé, et dit? Va, et fais amas de gens en la montagne de Tabor, et prends avec toi dix mille hommes des enfants de Nephthali, et des enfants de Zabulon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Et j’attirerai à toi au torrent de Kison, Sisera, chef de l’armée de Jabin, avec ses chariots et la multitude de ses gens, et je le livrerai entre tes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Et Barac lui dit: Si tu viens avec moi, j’y irai; mais si tu ne viens pas avec moi, je n’y irai point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Et elle répondit: Je ne manquerai pas d’aller avec toi; mais tu n’auras pas d’honneur dans le chemin dans lequel tu iras; car l’Eternel vendra Sisera en la main d’une femme. Débora donc se levant, s’en alla avec Barac à Kédés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Et Barac ayant assemblé Zabulon et Nephthali en Kédés, fit monter après soi dix mille hommes; et Débora monta avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Or Héber Kénien, des enfants de Hobab, beau-père de Moïse, s’étant séparé de Kaïn, avait tendu ses tentes jusques au bois de chênes de Tsahanajim, qui est près de Kédés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Et on rapporta à Sisera que Barac, fils d’Abinoham, était monté en la montagne de Tabor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Et Sisera assembla tous ses chariots, savoir neuf cents chariots de fer, et tout le peuple qui était avec lui, depuis Haroseth des Nations, jusqu’au torrent de Kison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Et Débora dit à Barac: Lève-toi, car c’est ici le jour auquel l’Eternel a livré Sisera en ta main. L’Eternel n’est-il pas sorti devant toi? Barac donc descendit de la montagne de Tabor, et dix mille hommes après lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Et l’Eternel frappa Sisera, et tous ses chariots, et toute l’armée, au tranchant de l’épée, devant Barac; et Sisera descendit du chariot, et s’enfuit à pied.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Et Barac poursuivit les chariots et l’armée jusqu’à Haroseth des Nations; et toute l’armée de Sisera fut passée au fil de l’épée; il n’en demeura pas un seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Et Sisera s’enfuit à pied dans la tente de Jahel, femme de Héber Kénien; car il y avait paix entre Jabin, Roi de Hatsor, et la maison de Héber Kénien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Et Jahel étant sortie au-devant de Sisera, lui dit: Mon seigneur! retire-toi, retire-toi chez moi, ne crains point. Il se retira donc chez elle dans la tente, et elle le couvrit d’une couverture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Puis il lui dit: Je te prie, donne-moi un peu d’eau à boire, car j’ai soif. Et elle ouvrant un baril de lait lui donna à boire, et le couvrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Il lui dit aussi: Demeure à l’entrée de la tente, et au cas que quelqu’un vienne, et t’interroge, disant: Y a-t-il ici quelqu’un? alors tu répondras: Non.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Et Jahel, femme de Héber, prit un clou de la tente, et prenant un marteau en sa main, elle vint à lui doucement; et lui enfonça un clou dans sa tempe, lequel entra dans la terre pendant qu’il dormait profondément, car il était fort las; et ainsi il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Et voici, Barac poursuivait Sisera, et Jahel sortit au-devant de lui, et lui dit: Viens, et je te montrerai l’homme que tu cherches. Et Barac entra chez elle, et voici, Sisera était étendu mort, et le clou était dans sa tempe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'En ce jour-là donc Dieu humilia Jabin, Roi de Canaan, devant les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Et la puissance des enfants d’Israël s’avançait et se renforçait de plus en plus contre Jabin, Roi de Canaan, jusqu’à ce qu’ils l’eurent exterminé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'En ce jour-là Débora, avec Barac fils d’Abinoham, chanta en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Bénissez l’Eternel de ce qu’il a fait de telles vengeances en Israël, et de ce que le peuple a été porté de bonne volonté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Vous Rois écoutez, vous Princes prêtez l’oreille; moi, moi, je chanterai à l’Eternel, je psalmodierai à l’Eternel le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Ô Eternel! quand tu sortis de Séhir, quand tu marchas du territoire d’Edom, la terre fut ébranlée, même les cieux fondirent, les nuées, dis-je, fondirent en eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Les montagnes s’écoulèrent de devant l’Eternel, ce Sinaï s’écoula de devant l’Eternel le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Aux jours de Samgar, fils de Hanath, aux jours de Jahel, les grands chemins n’étaient plus battus, et ceux qui allaient par les chemins allaient par des routes détournées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Les villes non murées n’étaient plus habitées en Israël, elles n’étaient point habitées, jusqu’à ce que je me suis levée, moi Débora, jusqu’à ce que je me suis levée pour être mère en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Israël choisissait-il des dieux nouveaux? alors la guerre était aux portes. A-t-il été vu bouclier ou lance en quarante mille d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'J’ai mon coeur vers les Gouverneurs d’Israël, qui se sont portés volontairement d’entre le peuple. Bénissez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Vous qui montez sur les ânesses blanches, et qui êtes assis dans le siège de la justice, et vous qui allez dans les chemins, parlez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Le bruit des archers ayant cessé dans les lieux où l’on puisait l’eau, qu’on s’y entretienne des justices de l’Eternel, et des justices de ses villes non murées en Israël; alors le peuple de Dieu descendra aux portes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Réveille-toi, réveille-toi, Débora; réveille-toi, réveille-toi, dit le Cantique, lève-toi Barac, et emmène en captivité ceux que tu as faits captifs, toi fils d’Abinoham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'L’Eternel a fait alors dominer le réchappé, le peuple sur les magnifiques; l’Eternel m’a fait dominer sur les forts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Leur racine est depuis Ephraïm jusqu’à Hamalek; Benjamin a été après toi parmi tes peuples; de Makir sont descendus les Gouverneurs; et de Zabulon ceux qui manient la plume du Scribe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Et les principaux d’Issacar ont été avec Débora, et Issacar ainsi que Barac; il a été envoyé avec sa suite dans la vallée; il y a eu aux séparations de Ruben, de grandes considérations dans leur coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Pourquoi t’es-tu tenu entre les barres des étables, afin d’entendre les cris des troupeaux? Il y a eu aux séparations de Ruben de grandes consultations dans leur coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Galaad est demeuré au delà du Jourdain; et pourquoi Dan s’est-il tenu aux navires? Aser s’est tenu aux ports de la mer, et il est demeuré dans ses havres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Mais pour Zabulon, c’est un peuple qui a exposé son âme à la mort; et Nephthali aussi, sur les hauteurs de la campagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Les Rois sont venus, ils ont combattu; les Rois de Canaan ont alors combattu à Tahanac, près des eaux de Méguiddo; mais ils n’ont point fait de gain d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'On a combattu des cieux, les étoiles, dis-je, ont combattu du lieu de leur cours contre Sisera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Le torrent de Kison les a emportés, le torrent de Kédummim, le torrent de Kison; mon âme tu as foulé aux pieds la force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Alors a été rompue la corne des pieds des chevaux par le battement des pieds, par le battement, dis-je, des pieds de ses puissants chevaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Maudissez Meroz, a dit l’Ange de l’Eternel; maudissez, maudissez ses habitants, car ils ne sont point venus au secours de l’Eternel, au secours de l’Eternel, avec les forts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Bénie soit par-dessus toutes les femmes Jahel, femme de Héber Kénien, qu’elle soit bénie par-dessus les femmes qui se tiennent dans les tentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Il a demandé de l’eau, elle lui a donné du lait; elle lui a présenté de la crème dans la coupe des magnifiques.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Elle a avancé sa main gauche au clou et sa main droite au marteau des ouvriers; elle a frappé Sisera, et lui a fendu la tête; elle a transpercé et traversé ses tempes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Il s’est courbé entre les pieds de Jahel, il est tombé, il a été étendu entre les pieds de Jahel, il s’est courbé, il est tombé; et au lieu où il s’est courbé, il est tombé là tout défiguré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'La mère de Sisera regardait par la fenêtre, et s’écriait en regardant par les treillis: Pourquoi son char tarde-t-il à venir? Pourquoi ses chariots vont-ils si lentement?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Et les plus sages de ses dames lui ont répondu; et elle aussi se répondait à soi-même:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'N’ont-ils pas trouvé? ils partagent le butin; une fille, deux filles à chacun par tête. Le butin des vêtements de couleurs est à Sisera, le butin de couleurs de broderie; couleur de broderie à deux endroits, autour du cou de ceux du butin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Qu’ainsi périssent, ô Eternel! tous tes ennemis; et que ceux qui t’aiment soient comme le soleil quand il sort en sa force. Or le pays fut en repos quarante ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Or les enfants d’Israël firent ce qui déplaît à l’Eternel; et l’Eternel les livra entre les mains de Madian pendant sept ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Et la main de Madian se renforça contre Israël, et à cause des Madianites les enfants d’Israël se firent des creux qui sont dans les montagnes, et des cavernes, et des forts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Car il arrivait que quand Israël avait semé, Madian montait avec Hamalec et les Orientaux, et ils montaient contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'Et faisant un camp contr’eux ils ravageaient les fruits du pays jusqu’à Gaza, et ne laissaient rien de reste en Israël, ni vivres, ni menu bétail, ni boeufs, ni ânes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Car eux et leurs troupeaux montaient, et ils venaient avec leurs tentes en aussi grand nombre que des sauterelles, tellement qu’eux et leurs chameaux étaient sans nombre; et ils venaient au pays pour le ravager.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Israël donc fut fort appauvri par Madian, et les enfants d’Israël crièrent à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Et il arriva que quand les enfants d’Israël eurent crié à l’Eternel à l’occasion de Madian,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'L’Eternel envoya un Prophète vers les enfants d’Israël, qui leur dit: Ainsi a dit l’Eternel le Dieu d’Israël: Je vous ai fait monter hors d’Egypte, et je vous ai retirés de la maison de servitude;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'Et vous ai délivrés de la main des Egyptiens, et de la main de tous ceux qui vous opprimaient, et les ai chassés de devant vous, et vous ai donné leur pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Je vous ai dit aussi: Je suis l’Eternel votre Dieu, vous ne craindrez point les dieux des Amorrhéens, au pays desquels vous habitez; mais vous n’avez point obéi à ma voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Puis l’Ange de l’Eternel vint, et s’assit sous un chêne qui était à Hophra, appartenant à Joas Abihézérite. Et Gédeon son fils battait le froment dans le pressoir, pour le sauver de devant Madian.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Alors l’Ange de l’Eternel lui apparut, et lui dit: Très-fort et vaillant homme, l’Eternel est avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Et Gédeon lui répondit: Hélas mon Seigneur! est-il possible que l’Eternel soit avec nous? et pourquoi donc toutes ces choses nous sont-elles arrivées? Et où sont toutes ces merveilles que nos pères nous ont récitées, en disant: L’Eternel ne nous a-t-il pas fait monter hors d’Egypte? car maintenant l’Eternel nous a abandonnés, et nous a livrés entre les mains des Madianites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Et l’Eternel le regardant lui dit: Va avec cette force que tu as, et tu délivreras Israël de la main des Madianites; ne t’ai-je pas envoyé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Et il lui répondit: Hélas, mon Seigneur! par quel moyen délivrerai-je Israël? Voici, mon millier est le plus pauvre qui soit en Manassé, et je suis le plus petit de la maison de mon père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Et l’Eternel lui dit: Parce que je serai avec toi, tu frapperas les Madianites comme s’ils n’étaient qu’un seul homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Et il lui répondit: Je te prie, si j’ai trouvé grâce devant toi, de me donner un signe pour montrer que c’est toi qui parles avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Je te prie, ne t’en va point d’ici jusqu’à ce que je revienne à toi, et que j’apporte mon présent, et que je le mette devant toi. Et il dit: J’y demeurerai jusqu’à ce que tu reviennes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Alors Gédeon rentra, et apprêta un chevreau de lait, et des gâteaux sans levain d’un Epha de farine; mit la chair dans un panier, le bouillon dans un pot, et il les lui apporta sous le chêne, et les lui présenta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Et l’Ange de Dieu lui dit: Prends cette chair et ces gâteaux sans levain, et mets-les sur ce rocher, et répands le bouillon; et il le fit ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Alors l’Ange de l’Eternel ayant étendu le bâton qu’il avait en sa main, toucha la chair et les gâteaux sans levain, et le feu monta du rocher, et consuma la chair et les gâteaux sans levain; puis l’Ange de l’Eternel s’en alla de devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Et Gédeon vit que c’était l’Ange de l’Eternel, et il dit: ha, Seigneur Eternel; est-ce pour cela que j’ai vu l’Ange de l’Eternel face à face?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Et l’Eternel lui dit: Il va bien pour toi; ne crains point, tu ne mourras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Et Gédeon bâtit là un autel à l’Eternel, et l’appela L’ETERNEL DE PAIX. Et cet autel est demeuré jusqu’à aujourd’hui à Hophra des Abihézérites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Or il arriva en cette nuit-là que l’Eternel lui dit: Prends un taureau d’entre les boeufs qui sont à ton père, savoir le deuxième taureau, de sept ans; et démolis l’autel de Bahal qui est à ton père, et coupe le bocage qui est auprès;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Et bâtis un autel à l’Eternel ton Dieu sur le haut de ce fort, en un lieu convenable. Tu prendras ce deuxième taureau, et tu l’offriras en holocauste avec les arbres du bocage que tu couperas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Gédeon donc ayant pris dix hommes d’entre ses serviteurs, fit comme l’Eternel lui avait dit; et parce qu’il craignait la maison de son père et les gens de la ville, s’il l’eût fait de jour, il le fit de nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Et les gens de la ville se levèrent de bon matin, et voici, l’autel de Bahal avait été démoli, et le bocage qui était auprès, était coupé, et le deuxième taureau était offert en holocauste sur l’autel qu’on avait bâti.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Et ils se disaient les uns aux autres: Qui a fait ceci? Et s’en étant informés, et ayant cherché, ils dirent: Gédeon le fils de Joas a fait ceci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Puis les gens de la ville dirent à Joas: Fais sortir ton fils, et qu’il meure; car il a démoli l’autel de Bahal, et a coupé le bocage qui était auprès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Et Joas répondit à tous ceux qui s’adressèrent à lui: Est-ce vous qui prendrez la cause de Bahal? Est-ce vous qui le sauverez? Quiconque aura pris sa cause, sera mis à mort d’ici au matin. S’il est Dieu, qu’il défende sa cause, de ce qu’on a démoli son autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Et en ce jour-là il appela Gédeon Jérubbahal, et dit: Que Bahal défende sa cause de ce que Gédeon a démoli son autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Or tous les Madianites, les Hamalécites, et les Orientaux s’assemblèrent tous, et ayant passé le Jourdain ils se campèrent en la vallée de Jizréhel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Et l’Esprit de l’Eternel revêtit Gédeon; lequel sonna de la trompette, et les Abihézérites s’assemblèrent auprès de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Il envoya aussi des messagers par toute la Tribu de Manassé, qui s’assembla aussi auprès de lui; puis il envoya des messagers en Aser, en Zabulon, et en Nephthali, lesquels montèrent pour aller au- devant d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Et Gédeon dit à Dieu: Si tu dois délivrer Israël par mon moyen, comme tu l’as dit,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'Voici, je m’en vais mettre une toison dans l’aire; si la rosée est sur la toison seule, et que le sec soit dans toute la place, je connaîtrai que tu délivreras Israël par mon moyen, selon que tu m’en as parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Et la chose arriva ainsi, car s’étant levé de bon matin le lendemain, et ayant pressé cette toison, il en fit sortir pleine une tasse d’eau de rosée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Gédeon dit encore à Dieu: Que ta colère ne s’enflamme point contre moi, et je parlerai seulement cette fois; je te prie, que je fasse un essai en la toison encore cette fois seulement; je te prie qu’il n’y ait rien de sec que la toison, et fais que la rosée soit sur toute la place de l’aire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Et Dieu fit ainsi cette nuit-là; car il n’y eut rien de sec que la toison, et la rosée fut sur toute la place de l’aire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Jérubbahal donc, qui est Gédeon, se levant dès le matin, et tout le peuple qui était avec lui, ils se campèrent près de la fontaine de Harod, et ils avaient le camp de Madian du côté du Septentrion, vers le coteau de Moreh dans la vallée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Or l’Eternel dit à Gédeon: Le peuple qui est avec toi est en trop grand nombre, pour que je livre Madian en leur main, de peur qu’Israël ne se glorifie contre moi, en disant: Ma main m’a délivré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Maintenant donc fais publier, le peuple l’entendant, et qu’on dise: Quiconque est timide et a peur, qu’il s’en retourne, et s’en aille dès le matin du côté de la montagne de Galaad; et vingt-deux mille du peuple s’en retournèrent; et il en resta dix mille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Et l’Eternel dit à Gédeon: Il y a encore du peuple en trop grand nombre; fais-les descendre vers l’eau, et là je te les choisirai; et celui dont je te dirai, celui-ci ira avec toi, il ira avec toi; et celui duquel je te dirai, celui-ci n’ira point avec toi; il n’y ira point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Il fit donc descendre le peuple vers l’eau; et l’Eternel dit à Gédeon: Quiconque lapera l’eau de sa langue, comme le chien lape, tu le mettras à part; et tu mettras aussi à part tous ceux qui se courberont sur leurs genoux pour boire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Et le nombre de ceux qui lapaient l’eau dans leur main, la portant à leur bouche, fut de trois cents hommes; mais tout le reste du peuple se courba sur ses genoux, pour boire de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Alors l’Eternel dit à Gédeon: Je vous délivrerai par le moyen de ces trois cents hommes qui ont lapé l’eau, et je livrerai Madian en ta main. Que tout le peuple donc s’en aille, chacun en son lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Ainsi le peuple prit en sa main des provisions, et leurs trompettes. Et Gédeon renvoya tous les hommes d’Israël chacun en sa tente, et retint les trois cents hommes. Or le camp de Madian était au-dessous, dans la vallée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Et il arriva cette nuit-là, que l’Eternel lui dit: Lève-toi, descends au camp, car je l’ai livré en ta main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Et si tu crains d’y descendre, descends vers le camp toi et Purah ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'Et tu entendras ce qu’ils diront, et tes mains seront fortifiées, puis tu descendras au camp. Il descendit donc avec Purah son serviteur, jusqu’au premier corps de garde du camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Or Madian, et Hamalec, et tous les Orientaux, étaient répandus dans la vallée comme des sauterelles, tant il y en avait, et leurs chameaux étaient sans nombre, comme le sable qui est sur le bord de la mer, tant il y en avait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Gédeon donc y étant arrivé, voilà, un homme récitait à son compagnon un songe, et lui disait: Voici, j’ai songé un songe; il me semblait qu’un gâteau de pain d’orge se roulait vers le camp de Madian, et qu’étant venu jusqu’aux tentes, il les a frappées, de sorte qu’elles en sont tombées, et il les a renversées, en roulant du haut de la montagne, et elles sont tombées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Alors son compagnon répondit, et dit: Cela n’est autre chose que l’épée de Gédeon, fils de Joas, homme d’Israël. Dieu a livré Madian et tout ce camp en sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Et quand Gédeon eut entendu le récit du songe, et son interprétation, il se prosterna; et étant retourné au camp d’Israël, il dit: Levez-vous, car l’Eternel a livré le camp de Madian en vos mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Puis il divisa les trois cents hommes en trois bandes, et leur donna à chacun des trompettes à la main, et des cruches vides, et des flambeaux dans les cruches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Et il leur dit: Prenez garde à moi et faites comme je ferai; lorsque je serai arrivé au bout du camp, vous ferez comme je ferai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Quand donc je sonnerai de la trompette, et tous ceux aussi qui sont avec moi, alors vous sonnerez aussi des trompettes autour de tout le camp, et vous direz: L’EPEE DE L’ETERNEL, ET DE GEDEON.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Gédeon donc, et les cent hommes qui étaient avec lui, arrivèrent au bout du camp, comme on venait de poser la seconde garde; on ne faisait que poser les gardes lorsqu’ils sonnèrent des trompettes; et qu’ils cassèrent les cruches qu’ils avaient en leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Ainsi les trois bandes sonnèrent des trompettes, et cassèrent les cruches, tenant en leur main gauche les flambeaux, et en leur main droite les trompettes pour sonner, et ils criaient: L’EPEE DE L’ETERNEL, ET DE GEDEON.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Et ils se tinrent chacun en sa place autour du camp; et toute l’armée courait ça et là, s’écriant et fuyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Car comme les trois cents hommes sonnaient des trompettes, l’Eternel tourna l’épée d’un chacun contre son compagnon, même par tout le camp. Et l’armée s’enfuit jusqu’à Beth-sittah, vers Tserera, jusqu’au bord d’Abelmeholah, vers Tabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Et les hommes d’Israël, savoir de Nephthali et d’Aser, et de tout Manassé s’assemblèrent, et poursuivirent Madian.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Alors Gédeon envoya des messagers par toute la montagne d’Ephraïm, pour leur dire: Descendez pour aller à la rencontre de Madian, et saisissez-vous les premiers des eaux du Jourdain jusqu’à Beth-bara. Les hommes d’Ephraïm donc s’étant assemblés, se saisirent des eaux du Jourdain jusqu’à Beth-bara.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Et ils prirent deux des chefs de Madian, Horeb et Zééb, et ils tuèrent Horeb au rocher de Horeb; mais ils tuèrent Zééb au pressoir de Zééb; et ils poursuivirent Madian, et apportèrent les têtes de Horeb et de Zééb à Gédeon, au deçà du Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Alors les hommes d’Ephraïm lui dirent: Que veut dire ce que tu nous as fait, de ne nous avoir pas appelés quand tu es allé à la guerre contre Madian; et ils s’emportèrent fortement contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Et il leur répondit: Qu’ai-je fait maintenant au prix de ce que vous avez fait? Les grappillages d’Ephraïm ne sont-ils pas meilleurs que la vendange d’Abihézer?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Dieu a livré entra vos mains les chefs de Madian, Horeb et Zééb; or qu’ai-je pu faire au prix de ce que vous avez fait? et leur esprit fut apaisé envers lui quand il leur eut ainsi parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Or Gédeon étant arrivé au Jourdain le passa, lui et les trois cents hommes qui étaient avec lui, lesquels tout las qu’ils étaient, poursuivaient l’ennemi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'C’est pourquoi il dit aux gens de Succoth: Donnez, je vous prie, au peuple qui me suit, quelques pains car ils sont las; et ainsi je poursuivrai Zébah et Tsalmunah, Rois de Madian.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Mais les principaux de Succoth répondirent: La paume de Zébah et celle de Tsalmunah sont-elles maintenant en ta main, que nous donnions du pain à ton armée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Et Gédeon dit: Quand donc l’Eternel aura livré Zébah et Tsalmunah en ma main, je froisserai alors votre chair avec des épines du désert, et avec des chardons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Puis de là il monta à Pénuël, et il tint les mêmes discours à ceux de Pénuël. Et les gens de Pénuël lui répondirent comme les gens de Succoth avaient répondu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Il parla donc aussi aux hommes de Pénuël, en disant: Quand je retournerai en paix, je démolirai cette tour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Or Zébah et Tsalmunah étaient à Karkor, et leurs armées avec eux, environ quinze mille hommes, qui étaient tous ceux qui étaient restés de toute l’armée des Orientaux; car il en était tombé morts six vingt mille hommes tirant l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Et Gédeon monta par le chemin de ceux qui habitent dans les tentes, du côté oriental de Nobah et de Jogbeha, et défit l’armée, qui se croyait assurée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Et comme Zébah et Tsalmunah s’enfuyaient, il les poursuivit, et prit les deux Rois de Madian, Zébah et Tsalmunah, et mit en déroute toute l’armée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Puis Gédeon fils de Joas retourna de la bataille de la montée de Hèrés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Et prenant un garçon de Succoth, il l’interrogea; et ce garçon lui donna par écrit les principaux de Succoth, et ses Anciens, au nombre de soixante dix-sept hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Et il s’en vint aux gens de Succoth, et leur dit: Voici Zébah et Tsalmunah, au sujet desquels vous m’avez insulté, en disant: La paume de Zébah et celle de Tsalmunah sont-elles maintenant en ta main, que nous donnions du pain à tes gens fatigués?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Il prit donc les Anciens de la ville, et des épines du désert, et des chardons, et il en froissa les hommes de Succoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Or il avait démoli la tour de Pénuël, et mis à mort les gens de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Puis il dit à Zébah et à Tsalmunah: Comment étaient faits ces hommes que vous avez tués sur le Tabor? Ils répondirent: Ils étaient entièrement comme toi; chacun d’eux avait l’air d’un fils de Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Et il leur dit: C’étaient mes frères, enfants de ma mère; l’Eternel est vivant, si vous leur eussiez sauvé la vie, je ne vous tuerais pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Puis il dit à Jéther son premier-né: Lève-toi, tue-les; mais le jeune garçon ne tira point son épée, car il avait peur, parce qu’il était encore jeune garçon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Et Zébah et Tsalmunah dirent: Lève-toi toi-même, et te jette sur nous; car tel qu’est l’homme, telle est sa force. Et Gédeon se leva, et tua Zébah et Tsalmunah, et prit les colliers qui étaient aux cous de leurs chameaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Et ceux d’Israël dirent tous d’un accord à Gédeon: Domine sur nous, tant toi que ton fils, et le fils de ton fils; car tu nous as délivrés de la main de Madian.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Et Gédeon leur répondit: Je ne dominerai point sur vous, ni mon fils ne dominera point sur vous; l’Eternel dominera sur vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Mais Gédeon leur dit: Je vous ferai une prière, qui est que vous me donniez chacun de vous les bagues qu’il a eues du butin; car les ennemis avaient des bagues d’or, parce qu’ils étaient Ismaélites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Et ils répondirent: Nous les donnerons très-volontiers; et étendant un manteau ils y jetèrent chacun les bagues qu’ils avaient eues du butin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Et le poids des bagues d’or qu’il avait demandées, fut de mille sept cents sicles d’or, sans les colliers, les boettes de senteur, et les vêtements d’écarlate qui étaient sur les Rois de Madian, et sans les chaînes qui étaient aux cous de leurs chameaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Puis Gédeon en fit un Ephod; et le mit en sa ville, qui était Hophra; et tout Israël paillarda après lui en ce lieu-là; ce qui tourna en piège à Gédeon, et à sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Ainsi Madian fut humilié devant les enfants d’Israël, et n’éleva plus sa tête; et le pays fut en repos quarante ans aux jours de Gédeon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Jérubbahal donc fils de Joas s’en vint en sa ville, et se tint en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Or Gédeon eut soixante et dix fils, sortis de sa hanche, parce qu’il eut plusieurs femmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Et sa concubine, qui était à Sichem, lui enfanta aussi un fils, et il le nomma Abimélec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Puis Gédeon, fils de Joas, mourut en bonne vieillesse, et fut enseveli au sépulcre de Joas son père à Hophra des Abihézérites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Et il arriva après que Gédeon fut mort, que les enfants d’Israël se détournèrent, et paillardèrent après les Bahalins, et s’établirent Bahal-bérith pour Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Ainsi les enfants d’Israël ne se souvinrent point de l’Eternel leur Dieu, qui les avait délivrés de la main de tous leurs ennemis qui les environnaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Et ils n’usèrent d’aucune gratuité envers la maison de Jérubbahal Gédeon, selon tout le bien qu’il avait fait à Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Et Abimélec, fils de Jérubbahal, s’en alla à Sichem vers les frères de sa mère, et leur parla, et à toute la famille de la maison du père de sa mère, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Je vous prie, faites entendre ces paroles à tous les Seigneurs de Sichem; Lequel vous semble le meilleur, ou que soixante-dix hommes, tous enfants de Jérubbahal, dominent sur vous; ou qu’un seul homme domine sur vous? et souvenez-vous que je suis votre os et votre chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Les frères donc de sa mère dirent de sa part toutes ces paroles, les Seigneurs de Sichem l’entendant; et leur coeur fut incliné vers Abimélec; car ils dirent, c’est notre frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Et ils lui donnèrent soixante-dix pièces d’argent prises de la maison de Bahal-bérith, avec lesquelles Abimélec leva des hommes n’ayant rien, et vagabonds, qui le suivirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Et il vint en la maison de son père à Hophra, et tua sur une même pierre ses frères, enfants de Jérubbahal, qui étaient soixante-dix hommes; mais Jotham, le plus petit fils de Jérubbahal, demeura de reste, parce qu’il s’était caché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Et tous les Seigneurs de Sichem s’assemblèrent, avec toute la maison de Millo, et ils vinrent, et établirent Abimélec pour Roi auprès du bois de chênes qui est en Sichem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Et on le rapporta à Jotham, qui s’en alla, et se tint au sommet de la montagne de Guérizim, et élevant sa voix, il cria, et leur dit: Ecoutez-moi, Seigneurs de Sichem, et que Dieu vous entende.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Les arbres allèrent un jour en toute diligence pour oindre sur eux un Roi, et ils dirent à l’olivier: Règne sur nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Mais l’olivier leur répondit: Me ferait-on quitter ma graisse, par laquelle Dieu et les hommes sont honorés, afin que j’aille m’agiter pour les autres arbres?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Puis les arbres dirent au figuier: Viens toi, et règne sur nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Et le figuier leur répondit: Me ferait-on quitter ma douceur, et mon bon fruit, afin que j’aille m’agiter pour les autres arbres?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Puis les arbres dirent à la vigne: Viens toi, et règne sur nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Et la vigne répondit: Me ferait-on quitter mon bon vin, qui réjouit Dieu et les hommes, afin que j’aille m’agiter pour les autres arbres?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Alors tous les arbres dirent à l’épine: Viens toi, et règne sur nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Et l’épine répondit aux arbres: Si c’est en sincérité que vous m’oignez pour Roi sur vous, venez, et retirez-vous sous mon ombre; sinon, que le feu sorte de l’épine, et qu’il dévore les cèdres du Liban.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Maintenant donc, si vous avez agi avec sincérité et avec intégrité, en établissant Abimélec pour Roi, et si vous en avez bien usé envers Jérubbahal et sa maison, et si vous lui avez fait selon qu’il vous y a obligés par ses actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, '(Car mon père a combattu pour vous, et a exposé sa vie, et vous a délivrés de la main de Madian.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'Mais vous vous êtes élevés aujourd’hui contre la maison de mon père, et avez tué sur une pierre ses enfants, qui étaient soixante- dix hommes, et avez établi pour Roi Abimélec fils de sa servante, sur les Seigneurs de Sichem, parce qu’il est votre frère.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Si, dis-je, vous avez agi aujourd’hui avec sincérité et avec intégrité envers Jérubbahal, et envers sa maison, réjouissez-vous d’Abimélec, et qu’il se réjouisse aussi de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Sinon, que le feu sorte d’Abimélec, et qu’il dévore les Seigneurs de Sichem, et la maison de Millo; et que le feu sorte des Seigneurs de Sichem, et de la maison de Millo, et qu’il dévore Abimélec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Puis Jotham s’enfuit en diligence, et s’en alla à Béer, et y demeura, à cause d’Abimélec son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Et Abimélec domina sur Israël trois ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Mais Dieu envoya un mauvais esprit entre Abimélec et les Seigneurs de Sichem; et les Seigneurs de Sichem furent infidèles à Abimélec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'Afin que la violence faite aux soixante-dix fils de Jérubbahal, et leur sang, retournât sur Abimélec leur frère, qui les avait tués; et sur les Seigneurs de Sichem qui lui avaient tenu la main pour tuer ses frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Les Seigneurs de Sichem donc lui mirent des embûches sur le sommet des montagnes, et ils pillaient tous ceux qui passaient près d’eux par le chemin. Ce qui fut rapporté à Abimélec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Alors Gahal, fils de Hébed, vint avec ses frères, et ils entrèrent dans Sichem; et les Seigneurs de Sichem eurent confiance en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Puis étant sortis aux champs ils vendangèrent leurs vignes, et en foulèrent les raisins, et firent bonne chère; et ils entrèrent dans la maison de leur Dieu, et ils mangèrent, et burent, et maudirent Abimélec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Alors Gahal, fils de Hébed, dit: Qui est Abimélec, et quelle est Sichem, que nous servions Abimélec? N’est-il pas fils de Jérubbahal? Et Zébul n’est-il pas son prévôt? Servez plutôt les hommes de Hémor, père de Sichem. Mais pour quelle raison servirions- nous celui-ci?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Plût à Dieu qu’on me donnât ce peuple sous ma conduite, et je chasserais Abimélec. Et il dit à Abimélec: Multiplie ton armée, et sors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Et Zébul, capitaine de la ville, entendit les paroles de Gahal, fils de Hébed, et sa colère s’enflamma.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'Puis il envoya adroitement des messagers vers Abimélec, pour lui dire: Voici, Gahal fils de Hébed, et ses frères, sont entrés dans Sichem; et voici, ils arment la ville contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Maintenant donc lève-toi de nuit, toi, et le peuple qui est avec toi, et mets des embûches aux champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Et au matin, environ le soleil levant, tu te lèveras de matin, et te jetteras sur la ville; et voici, Gahal et le peuple qui est avec lui, sortiront contre toi, et tu lui feras selon que tu en trouveras le moyen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Abimélec donc se leva de nuit, et tout le peuple qui était avec lui, et ils mirent des embûches contre Sichem, et les partagèrent en quatre bandes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Alors Gahal, fils de Hébed, sortit, et s’arrêta à l’entrée de la porte de la ville; et Abimélec, et tout le peuple qui était avec lui se levèrent de l’embuscade.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Et Gahal ayant aperçu ce peuple-là, dit à Zébul: Voici du peuple qui descend du sommet des montagnes. Et Zébul lui dit: Tu vois l’ombre des montagnes, comme si c’étaient des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Et Gahal parla encore, et dit: Voilà du peuple qui descend du milieu du pays, et une bande vient du chemin du bois de chênes des devins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Et Zébul lui dit: Où est maintenant ta vanterie, quand tu disais: Qui est Abimélec, que nous le servions? N’est-ce pas ici ce peuple que tu as méprisé? Sors maintenant, je te prie, et combats contr’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Alors Gahal sortit conduisant les Seigneurs de Sichem, et combattit contre Abimélec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Et Abimélec le poursuivit, comme il s’enfuyait de devant lui, et plusieurs tombèrent morts jusqu’à l’entrée de la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Et Abimélec s’arrêta à Aruma; et Zébul repoussa Gahal et ses frères, afin qu’ils ne demeurassent plus dans Sichem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Et il arriva dès le lendemain que le peuple sortit aux champs; ce qui fut rapporté à Abimélec;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Lequel prit du peuple, et le divisa en trois bandes, et les mit en embuscade dans les champs, et ayant aperçu que le peuple sortait de la ville, il se leva contr’eux, et les défit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'car Abimélec, et la bande qui était avec lui se répandirent, et se tinrent à l’entrée de la porte de la ville, mais les deux autres bandes se jetèrent sur tous ceux qui étaient aux champs, et les défirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Ainsi Abimélec combattit tout ce jour-là contre la ville, et prit la ville, et tua le peuple qui y était, et ayant rasé la ville, y sema du sel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Et tous les Seigneurs de la Tour de Sichem, ayant appris cela, se retirèrent dans le fort, qui était la maison du Dieu Bérith.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Et on rapporta à Abimélec que tous les Seigneurs de la Tour de Sichem s’étaient assemblés dans le fort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Alors Abimélec monta sur le mont Tsalmon, lui et tout le peuple qui était avec lui; et Abimélec prit une hache et coupa une branche d’arbre, et l’ayant mise sur son épaule, la porta, et dit au peuple qui était avec lui: Avez-vous vu ce que j’ai fait? dépêchez-vous, faites comme moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Chacun donc de tout le peuple coupa une branche, et ils suivirent Abimélec, et mirent ces branches tout autour du fort, et y ayant mis le feu, ils brûlèrent le fort. Et toutes les personnes de la Tour de Sichem moururent, au nombre d’environ mille, tant hommes que femmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Puis Abimélec s’en allant à Tébets, y mit son camp, et la prit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Or il y avait au milieu de la ville une Tour forte, où s’enfuirent tous les hommes et toutes les femmes, et tous les Seigneurs de la ville, et ayant fermé les portes après eux, ils montèrent sur le toit de la Tour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Alors Abimélec venant jusqu’à la Tour, l’attaqua, et s’approcha jusqu’à la porte de la Tour pour la brûler par feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Mais une femme jeta une pièce de meule sur la tête d’Abimélec, et lui cassa le crâne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Lequel ayant appelé incessamment le garçon qui portait ses armes, lui dit: Tire ton épée, et me tue, de peur qu’on ne dise de moi, une femme l’a tué. Son garçon donc le transperça, et il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Et ceux d’Israël voyant qu’Abimélec était mort, s’en allèrent chacun en son lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Ainsi Dieu rendit à Abimélec le mal qu’il avait commis contre son père, en tuant ses soixante-dix frères;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Et toute la méchanceté des hommes de Sichem; Dieu, dis-je, la fit retourner sur leurs têtes; et ainsi la malédiction de Jotham, fils de Jérubbahal, vint sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Après Abimélec, Tolah fils de Puah, fils de Dodo, homme d’Issacar, fut suscité pour délivrer Israël, et il habitait à Samir en la montagne d’Ephraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Et il jugea Israël vingt-trois ans, puis il mourut, et fut enseveli à Samir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Après lui fut suscité Jaïr Galaadite, qui jugea Israël vingt-deux ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Et il eut trente fils, qui montaient sur trente ânons, et qui avaient trente villes, qu’on appelle les villes de Jaïr jusqu’à ce jour, lesquelles sont au pays de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Et Jaïr mourut, et fut enseveli à Kamon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Puis les enfants d’Israël recommencèrent à faire ce qui déplaît à l’Eternel, et servirent les Bahalins, et Hastaroth, savoir, les dieux de Syrie, les dieux de Sidon, les dieux de Moab, les dieux des enfants de Hammon, et les dieux des Philistins; et ils abandonnèrent l’Eternel, et ne le servaient plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Alors la colère de l’Eternel s’enflamma contre Israël, et il les vendit en la main des Philistins, et en la main des enfants de Hammon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Qui opprimèrent et foulèrent les enfants d’Israël cette année-là, qui était la dix-huitième; savoir tous les enfants d’Israël, qui étaient au-delà du Jourdain au pays des Amorrhéens, qui est en Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Même les enfants de Hammon passèrent le Jourdain pour combattre aussi contre Juda, et contre Benjamin, et contre la maison d’Ephraïm; et Israël fut fort serré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Alors les enfants d’Israël crièrent à l’Eternel, en disant: Nous avons péché contre toi, et certes nous avons abandonné notre Dieu, et nous avons servi les Bahalins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Mais l’Eternel répondit aux enfants d’Israël: N’avez-vous pas été opprimés par les Egyptiens, les Amorrhéens, les enfants de Hammon, les Philistins,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Les Sidoniens, les Hamalécites, et les Mahonites? cependant quand vous avez crié vers moi, je vous ai délivrés de leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Mais vous m’avez abandonné, et vous avez servi d’autres dieux; c’est pourquoi je ne vous délivrerai plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Allez, et criez aux dieux que vous avez choisis; qu’ils vous délivrent au temps de votre détresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Mais les enfants d’Israël répondirent à l’Eternel: Nous avons péché, fais-nous, comme il te semblera bon; nous te prions seulement que tu nous délivres aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Alors ils ôtèrent du milieu d’eux les dieux des étrangers, et servirent l’Eternel, qui fut touché en son coeur de l’affliction d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Or les enfants de Hammon s’assemblèrent, et se campèrent en Galaad; et les enfants d’Israël aussi s’assemblèrent, et se campèrent à Mitspa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Et le peuple, et les principaux de Galaad dirent l’un à l’autre: Qui sera l’homme qui commencera à combattre contre les enfants de Hammon? il sera pour chef à tous les habitants de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Or Jephthé Galaadite était un fort et vaillant homme, mais fils d’une paillarde, toutefois Galaad l’avait engendré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Et la femme de Galaad lui avait enfanté des fils; et quand les fils de cette femme-là furent grands, ils chassèrent Jephthé, en lui disant: Tu n’auras point d’héritage dans la maison de notre père; car tu es fils d’une femme étrangère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Jephthé donc s’enfuit de devant ses frères, et habita au pays de Tob; et des gens qui n’avaient rien se ramassèrent auprès de Jephthé, et ils allaient et venaient avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Or il arriva, quelque temps après, que les enfants de Hammon firent la guerre à Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Et comme les enfants de Hammon faisaient la guerre à Israël, les Anciens de Galaad s’en allèrent pour ramener Jephthé du pays de Tob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Et ils dirent à Jephthé: Viens, et sois notre capitaine, afin que nous combattions contre les enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Et Jephthé répondit aux Anciens de Galaad: N’est-ce pas vous qui m’avez haï, et chassé de la maison de mon père? et pourquoi êtes vous venus à moi maintenant que vous êtes dans l’affliction?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Alors les Anciens de Galaad dirent à Jephthé: La raison pourquoi nous sommes maintenant retournés à toi, c’est afin que tu viennes avec nous, et que tu combattes contre les enfants de Hammon, et que tu sois notre chef, savoir de nous tous qui habitons à Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Et Jephthé répondit aux Anciens de Galaad: Si vous me ramenez pour combattre contre les enfants de Hammon, et que l’Eternel les livre entre mes mains, je serai votre chef.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Et les Anciens de Galaad dirent à Jephthé: Que l’Eternel écoute entre nous, si nous ne faisons selon tout ce que tu as dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Jephthé donc s’en alla avec les Anciens de Galaad, et le peuple l’établit sur soi pour chef, et pour capitaine; et Jephthé prononça devant l’Eternel à Mitspa toutes les paroles qu’il avait dites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Puis Jephthé envoya des messagers au Roi des enfants de Hammon pour lui dire: Qu’y a-t-il entre toi et moi, que tu sois venu contre moi pour faire la guerre en mon pays?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Et le Roi des enfants de Hammon répondit aux messagers de Jephthé: C’est parce qu’Israël a pris mon pays quand il montait d’Egypte, depuis Arnon jusqu’à Jabbok, même jusqu’au Jourdain; maintenant donc rends-moi ces contrées-là à l’amiable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Mais Jephthé envoya encore des messagers au Roi des enfants de Hammon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'Qui lui dirent: Ainsi a dit Jephthé: Israël n’a rien pris du pays de Moab, ni du pays des enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Mais après qu’Israël, étant monté d’Egypte, fut venu par le désert jusqu’à la mer Rouge et fut parvenu à Kadès;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Et qu’il eut envoyé des messagers au Roi d’Edom, pour lui dire: Que je passe, je te prie, par ton pays; à quoi le Roi d’Edom ne voulut point entendre; et qu’il eut aussi envoyé au Roi de Moab, qui ne le voulut point non plus entendre; et après qu’Israël ayant demeuré à Kadès,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Et ayant marché par le désert, eut fait le tour du pays d’Edom, et du pays de Moab, et fut arrivé au pays de Moab du côté d’Orient, il se campa au delà d’Arnon, et n’entra point dans les frontières de Moab; parce qu’Arnon était la frontière de Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Mais Israël envoya des messagers à Sihon, Roi des Amorrhéens, qui était Roi de Hesbon, auquel Israël fit dire: Nous te prions, que nous passions par ton pays, jusqu’à notre lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Mais Sihon ne se fiant point à Israël pour le laisser passer par son pays, assembla tout son peuple, et ils campèrent vers Jahats, et combattirent contre Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Et l’Eternel le Dieu d’Israël livra Sihon et tout son peuple entre les mains d’Israël, et Israël les défit, et conquit tout le pays des Amorrhéens qui habitaient en ce pays-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Ils conquirent donc tout le pays des Amorrhéens depuis Arnon jusqu’à Jabbok, et depuis le désert jusqu’au Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Or maintenant que l’Eternel le Dieu d’Israël a dépossédé les Amorrhéens de devant son peuple d’Israël, en aurais-tu la possession?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'N’aurais-tu pas la possession de ce que Kémos ton dieu t’aurait donné à posséder? Ainsi nous posséderons le pays de tous ceux que l’Eternel notre Dieu aura chassés de devant nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Or maintenant vaux-tu mieux en quelque sorte que ce soit que Balac, fils de Tsippor, Roi de Moab? Et lui n’a-t-il pas contesté et combattu autant qu’il a pu contre Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Pendant qu’Israël a demeuré à Hesbon, et dans les villes de son ressort, et à Haroher, et dans les villes de son ressort, et dans toutes les villes qui sont le long d’Arnon, l’espace de trois cents ans, pourquoi ne les avez-vous pas recouvrées pendant ce temps-là?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Je ne t’ai donc point offensé, mais tu fais une méchante action de me faire la guerre. Que l’Eternel, qui est le Juge, juge aujourd’hui entre les enfants d’Israël et les enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Mais le Roi des enfants de Hammon ne voulut point écouter les paroles que Jephthé lui avait fait dire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'L’Esprit de l’Eternel fut donc sur Jephthé, qui passa au travers de Galaad et de Manassé; et il passa jusqu’à Mitspé de Galaad, et de Mitspé de Galaad il passa jusqu’aux enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Et Jephthé voua un voeu à l’Eternel, et dit: Si tu livres les enfants de Hammon en ma main;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'Alors tout ce qui sortira des portes de ma maison au devant de moi, quand je retournerai en paix du pays des enfants de Hammon, sera à l’Eternel, et je l’offrirai en holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Jephthé donc passa jusques où étaient les enfants de Hammon pour combattre contr’eux; et l’Eternel les livra en sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Et il en fit un très-grand carnage, depuis Haroher jusqu’à Minnith, en vingt villes, et jusqu’à la plaine des vignes; et les enfants de Hammon furent humiliés devant les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Puis comme Jephthé venait à Mitspa en sa maison, voici sa fille, qui était seule et unique, sans qu’il eût d’autre fils, ou fille, sortit au devant de lui avec tambours et flûtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Et il arriva qu’aussitôt qu’il l’eut aperçue, il déchira ses vêtements, et dit: Ha! ma fille, tu m’as entièrement abaissé, et tu es du nombre de ceux qui me troublent; car j’ai ouvert ma bouche à l’Eternel, et je ne m’en pourrai point rétracter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Et elle répondit: Mon père, as-tu ouvert ta bouche à l’Eternel, fais-moi selon ce qui est sorti de ta bouche, puisque l’Eternel t’a vengé de tes ennemis, les enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Toutefois elle dit à son père: Que ceci me soit accordé; laisse- moi pour deux mois, afin que je m’en aille, et que je descende par les montagnes, et que je pleure ma virginité, moi et mes compagnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Et il dit: Va, et il la laissa aller pour deux mois. Elle s’en alla donc avec ses compagnes, et pleura sa virginité dans les montagnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Et au bout de deux mois elle retourna vers son père; et il lui fit selon le voeu qu’il avait voué. Or elle n’avait point connu d’homme. Et ce fut une coutume en Israël,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'Que d’an en an les filles d’Israël allaient pour lamenter la fille de Jephthé Galaadite, quatre jours en l’année.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Or les hommes d’Ephraïm s’étant assemblés, passèrent vers le Septentrion, et dirent à Jephthé: Pourquoi es-tu passé pour combattre contre les enfants de Hammon, et que tu ne nous as point appelés pour aller avec toi? Nous brûlerons au feu ta maison, et te brûlerons aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Et Jephthé leur dit: J’ai eu un grand différend avec les enfants de Hammon, moi et mon peuple, et quand je vous ai appelés, vous ne m’avez point délivré de leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Et voyant que vous ne me délivriez pas, j’ai exposé ma vie, et je suis passé jusqu’où étaient les enfants de Hammon, et l’Eternel les a livrés en ma main; pourquoi donc êtes-vous montés aujourd’hui vers moi pour me faire la guerre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Puis Jephthé ayant assemblé tous les gens de Galaad, combattit contre Ephraïm; et ceux de Galaad battirent Ephraïm, parce qu’ils avaient dit: Vous êtes des échappés d’Ephraïm, Galaad est au milieu d’Ephraïm, au milieu de Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Et les Galaadites se saisirent des passages du Jourdain avant que ceux d’Ephraïm y arrivassent; et quand quelqu’un de ceux d’Ephraïm qui étaient échappés, disait: Que je passe; les gens de Galaad lui disaient: Es-tu Ephratien? et il répondait: Non.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Alors ils lui disaient: Dis un peu Schibboleth, et il disait Sibboleth, et ne pouvait point prononcer Schibboleth; sur quoi se saisissant de lui ils le mettaient à mort au passage du Jourdain. Et en ce temps-là il y eut quarante-deux mille hommes d’Ephraïm qui furent tués.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Et Jephthé jugea Israël six ans; puis Jephthé Galaadite mourut, et fut enseveli en une des villes de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Après lui Ibtsan de Bethléhem jugea Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Et il eut trente fils et trente filles, lesquelles il mit hors de sa maison, en les mariant, et il prit de dehors trente filles pour ses fils; et il jugea Israël sept ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Puis Ibtsan mourut, et fut enseveli à Bethléhem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Après lui Elon Zabulonite jugea Israël, dix ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Puis Elon Zabulonite mourut et fut enseveli à Ajalon, dans la terre de Zabulon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Après lui Habdon, fils d’Hillel, Pirhathonite jugea Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Il eut quarante fils, et trente petits-fils, qui montaient sur soixante-dix ânons; et il jugea Israël huit ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Puis Habdon, fils d’Hillel, Pirhathonite mourut, et fut enseveli à Pirhathon, en la terre d’Ephraïm, sur la montagne de l’Hamalécite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Et les enfants d’Israël recommencèrent à faire ce qui déplaît à l’Eternel, et l’Eternel les livra entre les mains des Philistins pendant quarante ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Or il y avait un homme de Tsorah, d’une famille de ceux de Dan, dont le nom était Manoah, et sa femme était stérile, et n’avait jamais eu d’enfant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Et l’Ange de l’Eternel apparut à cette femme-là, et lui dit: Voici, tu es stérile, et tu n’as jamais eu d’enfant; mais tu concevras, et enfanteras un fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Prends donc bien garde dès maintenant de ne point boire de vin ni de cervoise, et de ne manger aucune chose souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Car voici, tu vas être enceinte, et tu enfanteras un fils, et le rasoir ne passera point sur sa tête; parce que l’enfant sera Nazarien de Dieu dès le ventre de sa mère; et ce sera lui qui commencera à délivrer Israël de la main des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Et la femme vint, et parla à son mari, en disant: Il est venu auprès de moi un homme de Dieu, dont la face est semblable à la face d’un Ange de Dieu, fort vénérable, mais je ne l’ai point interrogé d’où il était et il ne m’a point déclaré son nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Mais il m’a dit: Voici, tu vas être enceinte, et tu enfanteras un fils. Maintenant donc ne bois point de vin ni de cervoise, et ne mange aucune chose souillée; car cet enfant sera Nazarien de Dieu dès le ventre de sa mère jusqu’au jour de sa mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Et Manoah pria instamment l’Eternel, et dit: Hélas, Seigneur! que l’homme de Dieu que tu as envoyé, vienne encore, je te prie, vers nous, et qu’il nous enseigne ce que nous devons faire à l’enfant, quand il sera né.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Et Dieu exauça la prière de Manoah. Ainsi l’Ange de Dieu vint encore à la femme comme elle était assise dans un champ; mais Manoah son mari n’était point avec elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Et la femme courut vite le rapporter à son mari, en lui disant: Voici, l’homme qui était venu l’autre jour vers moi, m’est apparu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Et Manoah se leva, et suivit sa femme; et venant vers l’homme, il lui dit: Es-tu cet homme qui a parlé à cette femme-ci? Et il répondit: C’est moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Et Manoah dit: Tout ce que tu as dit arrivera; mais quel ordre faudra-t-il tenir envers l’enfant, et que lui faudra-t-il faire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Et l’Ange de l’Eternel répondit à Manoah: La femme se gardera de toutes les choses dont je l’ai avertie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Elle ne mangera rien qui sorte de la vigne, rien en quoi il y ait du vin; et elle ne boira ni vin ni cervoise, et ne mangera aucune chose souillée. Elle prendra garde à tout ce que je lui ai commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Alors Manoah dit à l’Ange de l’Eternel: Je te prie, que nous te retenions, et nous t’apprêterons un chevreau de lait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Et l’Ange de l’Eternel répondit à Manoah: Quand tu me retiendrais je ne mangerais point de ton pain; mais si tu fais un holocauste, tu l’offriras à l’Eternel. Or Manoah ne savait point que ce fût l’Ange de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Et Manoah dit à l’Ange de l’Eternel: Quel est ton nom, afin que nous te fessions un présent lorsque ce que tu as dit sera arrivé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Et l’Ange de l’Eternel lui dit: Pourquoi t’enquiers-tu ainsi de mon nom? car il est admirable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Alors Manoah prit un chevreau de lait, et un gâteau, et les offrit à l’Eternel sur le rocher. Et l’Ange fit une chose merveilleuse à la vue de Manoah et de sa femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'C’est, que la flamme montant de dessus l’autel vers les cieux, l’Ange de l’Eternel monta aussi avec la flamme de l’autel; ce que Manoah et sa femme ayant vu ils se prosternèrent le visage contre terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Et l’Ange de l’Eternel n’apparut plus à Manoah ni à sa femme. Alors Manoah connut que c’était l’Ange de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Et Manoah dit à sa femme: Certainement nous mourrons, parce que nous avons vu Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Mais sa femme lui répondit: Si l’Eternel nous eût voulu faire mourir, il n’aurait pas pris de notre main l’holocauste ni le gâteau, et il ne nous aurait pas fait voir toutes ces choses, en un temps comme celui-ci, ni fait entendre les choses que nous avons entendues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Puis cette femme enfanta un fils, et elle l’appela Samson; et l’enfant devint grand, et l’Eternel le bénit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Et l’Esprit de l’Eternel commença de le saisir à Mahané-dan, entre Tsorah et Estaol.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Or Samson étant descendu à Timna, y vit une femme d’entre les filles des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Et étant remonté en sa maison il le déclara à son père et à sa mère, en disant: J’ai vu une femme à Timna d’entre les filles des Philistins; maintenant donc prenez-la, afin qu’elle soit ma femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Et son père et sa mère lui dirent: N’y a-t-il point de femme parmi les filles de tes frères, et parmi tout mon peuple, que tu ailles prendre une femme d’entre les Philistins, ces incirconcis? Et Samson dit à son père: Prenez-la moi, car elle plaît à mes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Mais son père et sa mère ne savaient pas que cela venait de l’Eternel; car Samson cherchait que les Philistins lui donnassent quelque occasion. Or en ce temps-là les Philistins dominaient sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Samson donc descendit avec son père et sa mère à Timna, et ils vinrent jusqu’aux vignes de Timna, et voici, un jeune lion rugissant venait contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Et l’Esprit de l’Eternel ayant saisi Samson, il déchira le lion comme s’il eût déchiré un chevreau, sans avoir rien en sa main; mais il ne déclara point à son père ni à sa mère ce qu’il avait fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Il descendit donc, et parla à la femme, et elle lui plut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Puis retournant quelques jours après pour la prendre, il se détourna pour voir la charogne du lion, et voici il y avait dans la charogne du lion un essaim d’abeilles, et du miel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Et il en prit en sa main, et s’en alla son chemin, en mangeant; et étant arrivé vers son père, et vers sa mère, il leur en donna, et ils en mangèrent; mais il ne leur déclara pas qu’il avait pris ce miel dans la charogne du lion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Son père donc descendit vers cette femme, et Samson fit là un festin; car c’est ainsi que les jeunes gens avaient accoutumé de faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Et sitôt qu’on l’eut vu, on prit trente compagnons, qui furent avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Et Samson leur dit: Je vous proposerai maintenant une énigme; et si vous me l’expliquez pendant les sept jours du festin, et la trouvez, je vous donnerai trente linges, savoir trente robes de rechange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Mais si vous ne me l’expliquez pas, vous me donnerez trente linges, savoir trente robes de rechange. Et ils lui répondirent: Propose ton énigme, et nous l’entendrons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Et il leur dit: De celui qui dévorait est procédée la viande, et du fort est procédée la douceur. Mais ils ne purent en trois jours expliquer l’énigme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Et au septième jour, ils dirent à la femme de Samson: Persuade à ton mari de nous déclarer l’énigme, de peur que nous ne te brûlions au feu, toi et la maison de ton père. Nous avez-vous appelés ici pour avoir notre bien n’ est-il pas ainsi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'La femme de Samson donc pleura auprès de lui, et dit: Certainement tu me hais, et tu ne m’aimes point; n’as-tu pas proposé une énigme aux enfants de mon peuple, et tu ne me l’as point déclarée? Et il lui répondit: Voici, je ne l’ai point déclarée à mon père ni à ma mère, et te la déclarerais-je?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Elle pleurait ainsi auprès de lui durant les sept jours du festin, mais au septième jour il la lui déclara, parce qu’elle le tourmentait; puis elle la déclara aux enfants de son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Les gens de la ville donc lui dirent au septième jour, avant que le soleil se couchât: Qu y a-t-il de plus doux que le miel, et qu’y a-t-il de plus fort que le lion? Et il leur dit: Si vous n’eussiez point labouré avec ma génisse vous n’eussiez point trouvé mon énigme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Et l’Esprit de l’Eternel le saisit, et il descendit à Askelon, et ayant tué trente hommes de ceux d’Askelon, il prit leurs dépouilles, et donna les robes de rechange à ceux qui avaient expliqué l’énigme; et sa colère s’enflamma, et il monta en la maison de son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Et la femme de Samson fut mariée à son compagnon, qui était son intime ami.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Or il arriva quelques jours après, au temps de la moisson des bleds, que Samson alla visiter sa femme, lui portant un chevreau de lait, et il dit: J’entrerai vers ma femme en sa chambre; mais son père ne lui permit point d’y entrer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Car il lui dit: J’ai cru que tu avais certainement de l’aversion pour elle, c’est pourquoi je l’ai donnée à ton compagnon. Sa soeur puînée n’est-elle pas plus belle qu’elle? je te prie donc qu’elle soit ta femme au lieu d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Et Samson leur dit: A présent je serai innocent à l’égard des Philistins quand je leur ferai du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Samson donc s’en alla, et prit trois cents renards; il prit aussi des flambeaux, et il tourna les renards queue contre queue, et mit un flambeau entre les deux queues, tout au milieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Puis il mit le feu aux flambeaux, et lâcha les renards aux bleds des Philistins qui étaient sur le pied; et il brûla tant le bled qui était en gerbes, que celui qui était sur le pied, même jusqu’aux vignes et aux oliviers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Et les Philistins dirent: Qui a fait cela? Et on répondit: Samson, le beau-fils du Timnien, parce qu’il lui a pris sa femme, et qu’il l’a donnée à son compagnon. Les Philistins donc montèrent, et la brûlèrent au feu, avec son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Alors Samson leur dit: Est-ce donc ainsi que vous faites? Cependant je me vengerai de vous avant que je cesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Et il les battit entièrement, et en fit un grand carnage; puis il descendit, et s’arrêta dans un quartier du rocher de Hétam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Alors les Philistins montèrent, et se campèrent en Juda, et se répandirent en Léhi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Et les hommes de Juda dirent: Pourquoi êtes-vous montés contre nous? Ils répondirent: Nous sommes montés pour lier Samson, afin que nous lui fassions comme il nous a fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Alors trois mille hommes de Juda descendirent vers le quartier du rocher de Hétam, et dirent à Samson: Ne sais-tu pas que les Philistins dominent sur nous; pourquoi donc nous as-tu fait ceci? Il leur répondit: Je leur ai fait comme ils m’ont fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Ils lui dirent encore: Nous sommes descendus pour te lier, afin de te livrer entre les mains des Philistins. Et Samson leur dit: Jurez-moi que vous ne vous jetterez point sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Et ils répondirent, et dirent: Non, mais nous te lierons très- bien, afin de te livrer entre leurs mains; mais nous ne te tuerons point. Ils le lièrent donc de deux cordes neuves, et le firent monter hors du rocher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Or quand il fut venu jusqu’à Léhi, les Philistins jetèrent des cris de joie à sa rencontre, et l’esprit de l’Eternel le saisit, et les cordes qui étaient sur ses bras, devinrent comme du lin où l’on a mis le feu, et ses liens s’écoulèrent de dessus ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Et ayant trouvé une mâchoire d’âne qui n’était pas encore desséchée, il avança sa main, la prit, et il en tua mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Puis Samson dit: Avec une mâchoire d’âne, un monceau, deux monceaux; avec une mâchoire d’âne j’ai tué mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Et quand il eut achevé de parler, il jeta de sa main la mâchoire, et nomma ce lieu-là Ramath-léhi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Et il eut une fort grande soif, et il cria à l’Eternel en disant: Tu as mis en la main de ton serviteur cette grande délivrance, et maintenant mourrais-je de soif, et tomberais-je entre les mains des incirconcis?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Alors Dieu fendit une des grosses dents de cette mâchoire d’âne, et il en sortit de l’eau; et quand Samson eut bu, l’esprit lui revint, et il reprit ses forces;: c’est pourquoi ce lieu-là a été appelé jusqu’à ce jour Hen-hakkoré, qui est à Léhi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Or Samson jugea Israël au temps des Philistins, vingt ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Or Samson s’en alla à Gaza, et vit là une femme paillarde, et alla vers elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Et on dit à ceux de Gaza: Samson est venu ici; ils l’environnèrent, et lui dressèrent une embuscade toute la nuit à la porte de la ville, et ils se tinrent tranquilles toute la nuit, en disant: Qu’on ne bouge point jusqu’au point du jour, et nous le tuerons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Mais Samson après avoir dormi jusqu’à la minuit, se leva, et se saisit des portes de la ville, et des deux poteaux, et les ayant enlevés avec la barre, il les mit sur ses épaules, et les porta sur le sommet de la montagne qui est vis-à-vis de Hébron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Après cela il aima une femme qui se tenait près du torrent de Sorek, le nom de laquelle était Délila.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Et les Gouverneurs des Philistins montèrent vers elle, et lui dirent: Persuade-le jusqu’à ce que tu saches de lui en quoi consiste sa grande force, et comment nous le surmonterions, afin que nous le liions pour l’abattre; et nous te donnerons chacun onze cents pièces d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Délila donc dit à Samson: Déclare-moi, je te prie, en quoi consiste ta grande force, et avec quoi tu serais bien lié, pour t’abattre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Et Samson lui répondit: Si on me liait de sept cordes fraîches, qui ne fussent point encore sèches, je deviendrais sans force, et je serais comme un autre homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Les Gouverneurs donc des Philistins lui envoyèrent sept cordes fraîches qui n’étaient point encore sèches, et elle l’en lia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Or il y avait chez elle dans une chambre des gens qui étaient en embûches, et elle lui dit: Les Philistins sont sur toi, Samson. Alors il rompit les cordes, comme se romprait un filet d’étoupes dès qu’il sent le feu, et sa force ne fut point connue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Puis Délila dit à Samson: Voici tu t’es moqué de moi, car tu m’as dit des mensonges; je te prie, déclare-moi maintenant avec quoi tu pourrais être bien lié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Et il lui répondit: Si on me liait serré de courroies neuves, dont on ne se serait jamais servi, je deviendrais sans force, et je serais comme un autre homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Délila donc prit des courroies neuves, et elle l’en lia; puis elle lui dit: Les Philistins sont sur toi, Samson. Or il y avait des gens en embûches dans la chambre: et il rompit les courroies de dessus ses bras comme un filet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Puis Délila dit à Samson: Tu t’es moqué de moi jusqu’ici, et tu m’as dit des mensonges; déclare-moi avec quoi tu serais bien lié. Et il dit: Ce serait si tu avais tissu sept tresses de ma tête autour d’une ensuble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Et elle les mit dans l’ensuble avec l’attache, puis elle dit: Les Philistins sont sur toi, Samson. Alors il se réveilla de son sommeil, et enleva l’attache de la tissure avec l’ensuble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Alors elle lui dit: Comment dis-tu: Je t’aime, puisque ton coeur n’est point avec moi? Tu t’es moqué de moi trois fois, et tu ne m’as point déclaré en quoi consiste ta grande force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Et elle le tourmentait tous les jours par ses paroles, et le pressait vivement, tellement que son âme en fut affligée jusqu’à la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Alors il lui ouvrit tout son coeur, et lui dit: Le rasoir n’a jamais passé sur ma tête; car je suis Nazarien de Dieu dès le ventre de ma mère; si je suis rasé, ma force m’abandonnera, je me trouverai sans force, et je serai comme tous les autres hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Délila donc voyant qu’il lui avait ouvert tout son coeur, envoya appeler les Gouverneurs des Philistins, et leur dit: Montez à cette fois; car il m’a ouvert tout son coeur. Les Gouverneurs donc des Philistins montèrent vers elle, portant l’argent en leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Et elle l’endormit sur ses genoux, et ayant appelé un homme, elle lui fit raser sept tresses des cheveux de sa tête, et commença à l’abattre, et sa force l’abandonna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Alors elle dit: Les Philistins sont sur toi, Samson. Et il s’éveilla de son sommeil, disant en lui-même: J’en sortirai comme les autres fois, et je me tirerai de leurs mains; mais il ne savait pas que l’Eternel s’était retiré de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Les Philistins donc le saisirent, et lui crevèrent les yeux, et le menèrent à Gaza, et le lièrent de deux chaînes d’airain; et il tournait la meule dans la prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Et les cheveux de sa tête commencèrent à revenir comme ils étaient lorsqu’il fut rasé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Or les Gouverneurs des Philistins s’assemblèrent pour offrir un grand sacrifice à Dagon leur dieu, et pour se réjouir, et ils dirent: Notre dieu a livré en nos mains Samson notre ennemi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Le peuple aussi l’ayant vu, loua son dieu, en disant: Notre dieu a livré entre nos mains notre ennemi, et le destructeur de notre pays, et celui qui en a tant tué d’entre nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Or comme ils avaient le coeur joyeux, ils dirent: Faites venir Samson, afin qu’il nous fasse rire. Ils appelèrent donc Samson, et ils le tirèrent de la prison; il se jouait devant eux; et ils le firent tenir entre les piliers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Alors Samson dit au garçon qui le tenait par la main: Mets-moi en une telle place que je puisse toucher les piliers sur lesquels la maison est appuyée, afin que je m’y appuie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Or la maison était pleine d’hommes et de femmes, et tous les Gouverneurs des Philistins y étaient. Il y avait même sur le toit près de trois mille personnes tant d’hommes, que de femmes, qui regardaient Samson se jouer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Alors Samson invoqua l’Eternel, et dit: Seigneur Eternel, je te prie, souviens-toi de moi; ô Dieu! je te prie, fortifie-moi seulement cette fois, et que pour un coup je me venge des Philistins pour mes deux yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Samson donc embrassa les deux piliers du milieu, sur lesquels la maison était appuyée, et se tint à eux, l’un desquels était à sa main droite, et l’autre à sa gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Et il dit: Que je meure avec les Philistins. Il s’étendit donc de toute sa force; et la maison tomba sur les Gouverneurs et sur tout le peuple qui y était. Et il fit mourir beaucoup plus de gens en sa mort, qu’il n’en avait fait mourir en sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Ensuite ses frères, et toute la maison de son père, descendirent, et l’emportèrent; et étant remontés ils l’ensevelirent entre Tsorah et Estaol, dans le sépulcre de Manoah son père. Or il jugea Israël vingt ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Or il y avait un homme de la montagne d’Ephraïm, duquel le nom était Mica;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Qui dit à sa mère: Les onze cents pièces d’argent qui te furent prises, pour lesquelles tu fis des imprécations, en ma présence, voici, j’ai cet argent-là par-devers moi; je l’avais pris. Alors sa mère dit: Béni soit mon fils par l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Et quand il rendit à sa mère les onze cents pièces d’argent, sa mère dit: J’avais entièrement dédié de ma main cet argent à l’Eternel pour mon fils, afin d’en faire une image taillée, et une de fonte, ainsi je te le rendrai maintenant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Après donc qu’il eut rendu cet argent à sa mère, elle en prit deux cents pièces, et les donna au fondeur, qui en fit une image taillée, et une de fonte; et elles furent dans la maison de Mica.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Ainsi cet homme, savoir Mica, eut une maison de dieux, et fit un Ephod et des Théraphims, et consacra l’un de ses fils, qui lui servit de Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'En ce temps-là il n’y avait point de Roi en Israël; chacun faisait ce qui lui semblait être droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Or il y eut un jeune homme de Bethléhem de Juda, ville de la famille de Juda, qui était Lévite, et qui avait fait là son séjour;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Lequel partit de cette ville-là, savoir de Bethléhem de Juda, pour aller demeurer où il trouverait sa commodité, et continuant son chemin, il vint en la montagne d’Ephraïm jusqu’à la maison de Mica.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Et Mica lui dit: D’où viens-tu? Le Lévite lui répondit: Je suis de Bethléhem de Juda, et je m’en vais pour demeurer où je trouverai ma commodité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Et Mica lui dit: Demeure avec moi, et sois-moi pour père et pour Sacrificateur, et je te donnerai dix pièces d’argent par an, et ce que tes habits coûteront, et ta nourriture. Et le Lévite y alla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Ainsi le Lévite convint de demeurer avec cet homme-là, et ce jeune homme lui fut comme l’un de ses enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Et Mica consacra le Lévite, et ce jeune homme lui servit de Sacrificateur, et demeura en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Alors Mica dit: Maintenant je connais que l’Eternel me fera du bien, parce que j’ai un Lévite pour Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'En ce temps-là il n’y avait point de Roi en Israël, et en ce même temps la tribu de Dan cherchait un héritage pour soi afin d’y demeurer; car jusqu’à ce temps-là il ne lui en était point échu entre les Tribus d’Israël pour le posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'C’est pourquoi les enfants de Dan envoyèrent de leur famille cinq hommes, d’une et d’autre qualité, gens vaillants, de Tsorah et d’Estaol, pour reconnaître le pays, et le reconnaître exactement; et leur dirent: Allez et reconnaissez exactement le pays. Ils vinrent donc en la montagne d’Ephraïm jusqu’à la maison de Mica, et y passèrent la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Et quand ils furent auprès de la maison de Mica, ils reconnurent la voix du jeune homme Lévite; et s’étant détournés vers cette maison- là, ils lui dirent: Qui t’a amené ici, qu’y fais-tu? et qu’as-tu ici?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Et il répondit: Mica a fait pour moi telle et telle chose; il m’a donné des gages et je lui sers de Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Ils dirent encore: Nous te prions de consulter Dieu, afin que nous sachions si le voyage que nous entreprenons prospérera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Et le Sacrificateur leur dit: Allez en paix; l’Eternel a devant ses yeux le voyage que vous entreprenez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Ces cinq hommes donc s’en allèrent, et arrivèrent à Laïs, et ils virent que le peuple de cette ville habitait en assurance, et vivait en repos, et se croyait en sûreté, à la façon des Sidoniens; et qu’il n’y avait personne au pays qui leur fît de la peine en aucune chose, parce qu’ils étaient libres de toute ancienneté; et aussi ils étaient éloignés des Sidoniens, et n’avaient commerce avec personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Puis étant revenus à leurs frères à Tsorah et à Estaol, leurs frères leur dirent: Que rapportez -vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Et ils répondirent: Allons, montons contr’eux; car nous avons vu le pays, et nous l’avons trouvé très-bon; et vous êtes sans rien faire? ne soyez point paresseux à partir pour aller posséder le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Quand vous y entrerez, vous viendrez vers un peuple qui se tient assuré, et en un pays de grande étendue, car Dieu l’a livré entre vos mains; c’est un lieu où il ne manque rien de tout ce qui est sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Il partit donc de là, savoir de Tsorah et d’Estaol, six cents hommes armés de la famille de Dan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Et montant, ils campèrent à Kirjath-jéharim, qui est en Juda; c’est pourquoi on a appelé ce lieu-là Mahané-dan, jusqu’à ce jour, et il est derrière Kirjath-jéharim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Puis de là ils passèrent à la montagne d’Ephraïm, et arrivèrent à la maison de Mica.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Alors les cinq hommes qui étaient allés pour reconnaître le pays de Laïs, prenant la parole, dirent à leurs frères: Savez-vous bien qu’en ces maisons il y a un Ephod et des Théraphims, une image de taille et une de fonte? Voyez donc maintenant ce que vous aurez à faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Alors ils se détournèrent vers ce lieu-là, et vinrent en la maison où était le jeune homme Lévite, savoir en la maison de Mica, et le saluèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Or les six cents hommes des enfants de Dan, qui étaient sous les armes, s’arrêtèrent à l’entrée de la porte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Mais les cinq hommes qui étaient allés pour reconnaître le pays, montèrent et entrèrent dans la maison, et prirent l’imagé taillée, l’Ephod, les Théraphims, et l’image de fonte, pendant que le Sacrificateur était à l’entrée de la porte, avec les six cents hommes armés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Etant donc entrés dans la maison de Mica, ils prirent l’image taillée, l’Ephod, les Théraphims, et l’image de fonte. Et le Sacrificateur leur dit: Que faites-vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Et ils lui dirent: Tais-toi, et mets ta main sur ta bouche, et viens avec nous, et sois-nous pour père et pour Sacrificateur. Lequel te vaut-il mieux, d’être Sacrificateur de la maison d’un homme seul, ou d’être Sacrificateur d’une Tribu et d’une famille en Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Et le Sacrificateur en eut de la joie en son cœur, et ayant pris l’Ephod, les Théraphims, et l’image taillée, il se mit au milieu du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Après quoi ils retournèrent et reprirent leur chemin, et mirent devant eux les petits enfants, le bétail, et le bagage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Et quand ils furent loin de la maison de Mica, ceux qui demeuraient dans les maisons voisines de celle de Mica furent assemblés à grand cri; et ils atteignirent les enfants de Dan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Et ils crièrent après eux; mais eux tournant visage dirent à Mica: Qu’as-tu, que tu te sois ainsi écrié pour amasser des gens?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Il répondit: Vous avez enlevé mes dieux que j’avais faits, vous avez pris le Sacrificateur, et vous en êtes allés. Et que me reste- t-il? Comment donc me dites-vous: Qu’as-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Et les enfants de Dan lui dirent: Ne fais point entendre ta voix après nous, de peur que ces gens en colère ne se jettent sur vous, et que vous n’y laissiez la vie, toi, et tous ceux de ta famille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Les enfants donc de Dan continuèrent leur chemin, mais Mica ayant vu qu’ils étaient plus forts que lui, tourna visage, et s’en revint en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Ainsi ayant pris les choses que Mica avait faites, et le Sacrificateur qu’il avait, ils arrivèrent à Laïs, vers un peuple qui était en repos, et qui se tenait assuré, et ils les firent passer au fil de l’épée, et ayant mis le feu dans la ville, ils la brûlèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Et il n’y eut personne qui la délivrât; car elle était loin de Sidon, et n’avait commerce avec personne, et elle était située en la vallée qui appartenait au pays de Beth-réhob: puis ils bâtirent là une ville, et y habitèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Et ils nommèrent cette ville-là, Dan; selon le nom de Dan leur père qui était né à Israël, au lieu que la ville avait nom auparavant Laïs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Et les enfants de Dan se dressèrent cette image taillée, et Jonathan fils de Guerson, fils de Manassé, lui et ses enfants furent Sacrificateurs pour la Tribu de Dan jusqu’au jour qu’elle partit du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Ils y dressèrent donc l’image taillée que Mica avait faite, tout le temps que la maison de Dieu fut à Silo.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Il arriva aussi en ce temps-là, n’y ayant point de Roi en Israël, qu’il y eut un Lévite, demeurant aux côtés de la montagne d’Ephraïm, qui prit une femme concubine de Bethléhem de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Mais sa concubine paillarda chez lui, et s’en alla d’avec lui en la maison de son père en Bethléhem de Juda, et elle y fut quelques jours, savoir l’espace de quatre mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Puis son mari se leva, et s’en alla après elle, pour lui parler selon son coeur, et pour la ramener. Il avait aussi avec soi son serviteur, et deux ânes; et elle le fit entrer dans la maison de son père; et le père de la jeune femme le voyant se réjouit de son arrivée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Son beau-père donc, père de la jeune femme, le retint à grande instance; de sorte qu’il demeura avec lui trois jours; et ils mangèrent et burent, et logèrent là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Et au quatrième jour s’étant levé de bon matin, il se mit en chemin pour s’en aller; mais le père de la jeune femme dit à son beau- fils: Fortifie ton coeur avec une bouchée de pain, et puis vous vous en irez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Ils s’assirent donc, et mangèrent et burent eux deux ensemble; et le père de la jeune femme dit au mari: Je te prie qu’il te plaise de passer encore ici cette nuit, et que ton coeur se réjouisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Et comme le mari se fut mis en chemin pour s’en aller, son beau- père le pressa tellement, qu’il s’en retourna; et il y passa encore la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Et au cinquième jour il se leva de bon matin pour s’en aller, et le père de la jeune femme dit: Je te prie, fortifie ton cœur; et ils tardèrent tant, que le jour baissa pendant qu’ils mangeaient eux deux ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Puis le mari se mit en chemin pour s’en aller, lui et sa concubine, avec son serviteur. Et son beau-père le père de la jeune femme, lui dit: Voici maintenant le jour baisse, il se fait tard, je vous prie passez ici la nuit, voici le jour finit, passe ici la nuit, et que ton coeur se réjouisse; et demain au matin vous vous lèverez pour aller votre chemin, et tu t’en iras en ta maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Mais le mari ne voulut point y passer la nuit; mais il se leva, et s’en alla et vint jusque vis-à-vis de Jébus, qui est Jérusalem, ayant avec soi ses deux ânes embâtés, et sa concubine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Or comme ils étaient près de Jébus, et que le jour était fort avancé, le serviteur dit à son maître: Marchez, je vous prie, et détournons-nous vers cette ville des Jébusiens, afin que nous y passions la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Et son maître lui répondit: Nous ne nous détournerons point vers aucune ville des étrangers, où il n’y a point d’enfants d’Israël; mais nous passerons jusqu’à Guibha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Il dit aussi à son serviteur: Marche, et nous gagnerons l’un de ces lieux-là, et nous passerons la nuit à Guibha, ou à Rama.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Ils passèrent donc plus avant et marchèrent, et le soleil se coucha comme ils furent près de Guibha, qui appartient à Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Alors ils se détournèrent vers Guibha pour y entrer et y passer la nuit; et y étant entrés, ils demeurèrent en la place de la ville, car il n’y avait personne qui les retirât chez soi afin qu’ils y passassent la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Et voici sur le soir un vieux homme venait des champs de son travail, et cet homme était de la montagne d’Ephraïm, mais il demeurait à Guibha, dont les habitants étaient enfants de Jémini.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Et levant ses yeux il vit dans la place de la ville ce passant; et cet homme vieux lui dit: Où vas-tu, et d’où viens-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Et il lui répondit: Nous passons de Bethléhem de Juda vers les côtés de la montagne d’Ephraïm, d’où je suis, parce que j’étais allé jusqu’à Bethléhem de Juda, mais maintenant je m’en vais à la maison de l’Eternel, et il n’y a ici personne qui me retire chez lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Nous avons pourtant de la paille et du fourrage pour nos ânes, et du pain et du vin pour moi et pour ta servante, et pour le garçon qui est avec tes serviteurs; nous n’avons besoin d’aucune chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Et le vieillard lui dit: Paix te soit, quoi qu’il en soit je me charge de tout ce dont tu as besoin; je te prie seulement de ne passer point la nuit dans la place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Alors il le fit entrer en sa maison, et il donna du fourrage aux ânes; ils lavèrent leurs pieds, mangèrent et burent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Comme ils faisaient bonne chère, voici les gens de la ville, hommes fort corrompus, environnèrent la maison, heurtant à la porte, et ils parlèrent au vieux homme, maître de la maison, en disant: Fais sortir cet homme qui est entré en ta maison, afin que nous le connaissions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Mais cet homme, savoir le maître de la maison, sortit vers eux, et leur dit: Non, mes frères, ne lui faites point de mal, je vous prie: puisque cet homme est entré en ma maison, ne faites point une telle infamie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Voici, j’ai une fille vierge, et cet homme a sa concubine, je vous les amènerai dehors maintenant, et vous les violerez, et vous ferez d’elles comme il vous semblera bon; mais ne commettez point cette action infâme à l’égard de cet homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Mais ces gens-là ne voulurent point l’écouter; c’est pourquoi cet homme prit sa concubine, et la leur amena dehors; et ils la connurent, et abusèrent d’elle toute la nuit jusques au matin, puis ils la renvoyèrent comme l’aube du jour se levait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Cette femme donc, comme le jour approchait, s’en revint, et étant tombée à la porte de la maison de l’homme où était son Seigneur, elle y demeura jusqu’au jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Et son Seigneur se leva de bon matin, et ayant ouvert la porte il sortait pour continuer son chemin; mais voici, sa femme concubine était tombée à la porte de la maison, et avait les mains sur le seuil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Et il lui dit: Lève-toi, et allons-nous-en; mais elle ne répondait point. Alors il la chargea sur un âne, et se mit en chemin, et s’en alla en son lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Et étant venu en sa maison, il prit un couteau, et empoignant sa concubine il la partagea avec ses os en douze parts, et en envoya dans tous les Cantons d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Et il arriva que tous ceux qui virent cela dirent: Une telle chose n’a été faite ni vue depuis le jour que les enfants d’Israël sont montés hors du pays d’Egypte, jusqu’à ce jour. Pensez à cela, consultez, et prononcez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Alors tous les enfants d’Israël sortirent, et tout le peuple fut assemblé comme si ce n’eût été qu’un seul homme, depuis Dan jusqu’à Beersebah, et jusqu’au pays de Galaad, vers l’Eternel, en Mitspa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Et les Cantons de tout le peuple, toutes les Tribus d’Israël, se trouvèrent à l’assemblée du peuple de Dieu, au nombre de quatre cent mille hommes de pied dégainant l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, '(Or les enfants de Benjamin apprirent que les enfants d’Israël étaient montés en Mitspa.) Les enfants donc d’Israël dirent: Qu’on nous récite comment ce mal est arrivé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Et le Lévite, mari de la femme tuée, répondit et dit: Etant arrivés à Guibha, qui est de Benjamin, moi et ma concubine, pour y passer la nuit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Les Seigneurs de Guibha se sont élevés contre moi, et ont environné de nuit la maison contre moi, prétendant me tuer; et ils ont tellement violé ma concubine qu’elle en est morte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'C’est pourquoi ayant pris ma concubine, je l’ai mise en pièces, et je les ai envoyées par tous les quartiers de l’héritage d’Israël; car ils ont fait un crime énorme, et une action infâme en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Vous voici tous, enfants d’Israël, délibérez-en ici entre vous, et donnez-en votre avis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Et tout le peuple se leva, comme si ce n’eût été qu’un seul homme, et ils dirent: Aucun de nous n’ira en sa tente, ni aucun de nous ne se retirera dans sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Mais maintenant voici ce que nous ferons à Guibha, en procédant contr’elle par sort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Nous prendrons dix hommes de cent dans toutes les Tribus d’Israël, et cent de mille, et mille de dix mille, qui prendront de la provision pour le peuple, afin qu’étant entrés à Guibha de Benjamin, ils la traitent selon toute la turpitude qu’elle a commise en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Ainsi tous ceux d’Israël furent assemblés contre cette ville-là, étant unis comme s’ils n’eussent été qu’un seul homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Alors les Tribus d’Israël envoyèrent des hommes par toute la tribu de Benjamin pour lui dire: Quelle méchante action a-t-on commise parmi vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Maintenant donc livrez-nous ces méchants hommes qui sont à Guibha, afin que nous les fassions mourir, et que nous ôtions le mal du milieu d’Israël. Mais les Benjamites ne voulurent point écouter la voix de leurs frères les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Mais les Benjamites sortant de leurs villes s’assemblèrent à Guibha, pour sortir en bataille contre les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Et en ce jour-là on fit le dénombrement des enfants de Benjamin qui étaient dans ces villes, et il se trouva vingt-six mille hommes, tirant l’épée, sans les habitants de Guibha, dont on fit aussi le dénombrement, qui furent sept cents hommes d’élite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'De tout ce peuple-là il y avait sept cents hommes d’élite, desquels la main droite était serrée, tous tirant la pierre avec la fronde à un cheveu près, et ils n’y manquaient point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Et les hommes d’Israël furent tous dénombrés, excepté ceux de Benjamin, et il s’en trouva quatre cent mille hommes tirant l’épée, tous gens de guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Or ils partirent, et montèrent à la maison du Dieu Fort, et consultèrent Dieu. Les enfants donc d’Israël dirent: Qui est-ce d’entre nous qui montera le premier pour faire la guerre aux enfants de Benjamin? Et l’Eternel répondit: Juda montera le premier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Puis les enfants d’Israël se levèrent de bon matin, et campèrent près de Guibha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Et ceux d’Israël sortirent en bataille contre Benjamin, et rangèrent contr’eux leur armée près de Guibha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Et les enfants de Benjamin sortirent de Guibha, et en ce jour-là ils mirent par terre de ceux d’Israël vingt-deux mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Toutefois le peuple de ceux d’Israël reprit courage, et se rangea de nouveau en bataille au lieu où il s’était rangé le premier jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Parce que les enfants d’Israël étaient montés, et avaient pleuré devant l’Eternel jusqu’au soir, et avaient consulté l’Eternel en disant: M’approcherai-je encore pour combattre contre les enfants de Benjamin, mon frère? Et l’Eternel avait répondu: Montez contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Les enfants d’Israël s’approchèrent des enfants de Benjamin pour la seconde journée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'Benjamin aussi sortit de Guibha contr’eux en cette seconde journée, et ils mirent encore par terre dix-huit mille hommes des enfants d’Israël, tous tirant l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Alors tous les enfants d’Israël, et tout le peuple montèrent, et vinrent à la maison du Dieu Fort, et y pleurèrent, et se tinrent là devant l’Eternel, et jeûnèrent ce jour-là jusqu’au soir, et offrirent des holocaustes, et des sacrifices de prospérités devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Ensuite les enfants d’Israël consultèrent l’Eternel, (or là était l’Arche de l’alliance de Dieu en ces jours-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'Et Phinées fils d’Eléazar, fils d’Aaron, se tenait devant l’Eternel en ces jours-là:) ils consultèrent donc l’Eternel en disant: Sortirai-je encore une autre fois en bataille contre les enfants de Benjamin, mon frère, ou m’en désisterai-je? Et l’Eternel répondit: Montez, car demain je les livrerai entre vos mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Et Israël mit une embuscade à l’entour de Guibha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Et les enfants d’Israël montèrent pour la troisième journée contre les enfants de Benjamin, et ils se rangèrent contre Guibha, comme les autres fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Alors les enfants de Benjamin étant sortis à la rencontre du peuple, furent attirés hors de la ville, et commencèrent à frapper quelques-uns du peuple, environ trente hommes d’Israël qui furent blessés à mort comme les autres fois, dans les chemins, dont l’un monte à la maison du Dieu Fort; et l’autre à Guibha, parmi les champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Et les enfants de Benjamin dirent: Ils tombent battus devant nous, comme la première fois. Mais les enfants d’Israël disaient: Fuyons, attirons-les hors de la ville, dans les chemins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Tous ceux d’Israël donc se levant de leur lieu, se rangèrent à Bahal-tamar; et les gens de l’embuscade aussi sortirent de leur lieu, savoir de la prairie de Guibha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Et dix mille hommes d’élite de tout Israël vinrent contre Guibha, et la mêlée fut rude; et ceux de Benjamin ne s’aperçurent point que le mal les atteignait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'L’Eternel donc battit Benjamin devant les Israélites; et les enfants d’Israël mirent ce jour-là par terre vingt-cinq mille et cent hommes de Benjamin, tous tirant l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Les enfants de Benjamin donc virent qu’ils étaient battus. Or ceux d’Israël avaient fait place à ceux de Benjamin; car ils s’assuraient sur l’embuscade qu’ils avaient mise près de Guibha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Et ceux qui étaient en embuscade se jetèrent incontinent sur Guibha; ainsi ceux qui étaient en embuscade marchèrent à la file, et frappèrent toute la ville au tranchant de l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Or ceux d’Israël avaient donné pour signal à ceux qui étaient en embuscade, qu’ils fissent monter beaucoup de fumée de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Ceux d’Israël donc avaient tourné le dos en la bataille, et Benjamin avait commencé de frapper et de blesser à mort environ trente hommes de ceux d’Israël; car ils disaient: Quoi qu’il en soit, certainement ils tombent battus devant nous, comme à la première bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Mais quand la fumée qui avait été élevée, commença à monter de la ville comme une colonne de fumée, Benjamin regarda derrière soi, et voici toute la ville montait en feu vers le ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Alors ceux d’Israël tournèrent visage et ceux de Benjamin furent épouvantés; car ils virent que le mal les avait atteints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Et ils tournèrent le dos devant ceux d’Israël vers le chemin du désert; mais l’armée d’Israël les serra de près. Et quant à ceux des villes, ils les mirent par terre, les ayant enfermés au milieu d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Ils environnèrent donc ceux de Benjamin, et les poursuivirent, et les foulèrent aux pieds depuis Menuha jusqu’à l’opposite de Guibha, vers le soleil levant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Et il y eut de Benjamin dix-huit mille hommes tués, tous vaillants hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Alors ceux de Benjamin tournant le dos fuirent vers le désert au rocher de Rimmon, et ceux d’Israël en grappillèrent par les chemins cinq mille hommes, et les poursuivant de près jusqu’à Guidhom, ils en frappèrent deux mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Tous ceux donc qui tombèrent morts en ce jour-là de Benjamin, furent vingt-cinq mille hommes, tirant l’épée, et tous vaillants hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Et il y eut six cents hommes de ceux qui avaient tourné le dos, qui échappèrent vers le désert au rocher de Rimmon, et qui demeurèrent au rocher de Rimmon quatre mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Et ceux d’Israël retournèrent vers les enfants de Benjamin, et les frappèrent au tranchant de l’épée, tant les hommes de chaque ville que les bêtes, et tout ce qui s’y trouva. Ils brûlèrent aussi toutes les villes qui s’y trouvèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Or ceux d’Israël avaient juré en Mitspa, en disant: Nul de nous ne donnera sa fille pour femme aux Benjamites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Puis le peuple vint à la maison du Dieu Fort, et ils demeurèrent là jusqu’au soir en la présence de Dieu; et ils élevèrent leurs voix, et pleurèrent amèrement,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'Et dirent: Ô Eternel, Dieu d’Israël! pourquoi ceci est-il arrivé en Israël, qu’une Tribu d’Israël ait été aujourd’hui retranchée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Et le lendemain le peuple se leva de bon matin, et bâtit là un autel, et ils offrirent des holocaustes, et des sacrifices de prospérités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Alors les enfants d’Israël dirent: Qui est celui d’entre toutes les Tribus d’Israël qui n’est point monté à l’assemblée vers l’Eternel? Car on avait fait un grand serment contre tout homme qui ne monterait point vers l’Eternel à Mitspa, en disant: Un tel sera puni de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Car les enfants d’Israël se repentaient de ce qui était arrivé à Benjamin leur frère, et disaient aujourd’hui une Tribu a été retranchée d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Comment ferons-nous pour donner des femmes à ceux qui sont demeurés de reste, puisque nous avons juré par l’Eternel que nous ne leur donnerions point de nos filles pour femmes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Ils dirent donc: Y a-t-il quelqu’un d’entre les Tribus d’Israël qui ne soit point monté vers l’Eternel à Mitspa? Or voici, aucun homme de Jabès de Galaad n’était venu au camp, à l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Car quand on fit le dénombrement du peuple, voici, il ne s’était trouvé aucun des habitants de Jabès de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'C’est pourquoi l’assemblée y envoya douze mille hommes des plus vaillants, et leur commanda en disant: Allez, et frappez les habitants de Jabès de Galaad au tranchant de l’épée, tant les femmes que les petits enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Voici donc ce que vous ferez: Vous exterminerez à la façon de l’interdit tout mâle, et toute femme qui aura eu compagnie d’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Et ils trouvèrent entre les habitants de Jabès de Galaad quatre cents filles vierges, qui n’avaient point eu compagnie d’homme; et ils les amenèrent au camp à Silo, qui est au pays de Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Alors toute l’assemblée envoya pour parler aux enfants de Benjamin qui étaient au rocher de Rimmon, et pour leur offrir la paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'En ce temps-là donc les Benjamites retournèrent, et on leur donna pour femmes celles qui avaient été conservées en vie d’entre les femmes de Jabès de Galaad; mais il ne s’en trouva pas assez pour eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Et le peuple se repentit de ce qui avait été fait à Benjamin; car l’Eternel avait fait une brèche aux Tribus d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Et les Anciens de l’assemblée dirent: Comment ferons-nous pour donner des femmes à ceux qui sont demeurés de reste; car les femmes ont été exterminées d’entre les Benjamites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Puis ils dirent: Ceux qui sont réchappés posséderont ce qui appartenait à Benjamin, afin qu’une Tribu d’Israël ne soit point effacée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Cependant nous ne leur pourrons point donner des femmes d’entre nos filles; car les enfants d’Israël ont juré, en disant: Maudit soit celui qui donnera une femme à ceux de Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Et ils dirent: Voici la solennité ordinaire de l’Eternel est à Silo, qui est vers l’Aquilon de Bethel, et au soleil levant du chemin qui monte de Bethel à Sichem, et au midi de Lebona.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Et ils commandèrent aux enfants de Benjamin, en disant: Allez, et mettez des gens en embuscade aux vignes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Et quand vous verrez que les filles de Silo sortiront pour danser avec des flûtes, alors vous sortirez des vignes, et vous ravirez pour vous chacun sa femme d’entre les filles de Silo, et vous en irez au pays de Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Et quand leurs pères, ou leurs frères viendront vers nous pour plaider, nous leur dirons: Ayez pitié d’eux pour l’amour de nous, puisque nous n’avons point pris femme pour chacun d’eux en cette guerre, et vous serez coupables si vous ne leur en donnez point en un temps comme celui-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Les enfants de Benjamin firent ainsi, et enlevèrent des femmes selon leur nombre, d’entre celles qui dansaient, lesquelles ils ravirent; puis s’en allant ils retournèrent à leur héritage, et rebâtirent des villes, et y habitèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Ainsi en ce temps-là chacun des enfants d’Israël s’en alla de là en sa Tribu, et dans sa famille, et ils se retirèrent de là chacun dans son héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'En ces jours-là il n’y avait point de Roi en Israël; mais chacun faisait ce qui lui semblait être droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Or il arriva du temps que les Juges jugeaient, qu’il y eut une famine au pays; et un homme de Bethléhem de Juda s’en alla, pour demeurer en quelque lieu du pays de Moab, lui et sa femme, et ses deux fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Et le nom de cet homme était Eli-mélec, et le nom de sa femme Nahomi, et les noms de ses deux fils Mahlon et Kiljon, Ephratiens, de Bethléhem de Juda; et ils vinrent au pays de Moab, et y demeurèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Or Eli-mélec, mari de Nahomi, mourut et elle resta avec ses deux fils;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Qui prirent pour eux des femmes Moabites, dont l’une s’appelait Horpa, et l’autre Ruth; et ils demeurèrent là environ dix ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Puis ses deux fils Mahlon et Kiljon moururent; ainsi cette femme demeura là, privée de ses deux fils et de son mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Depuis elle se leva avec ses belles-filles pour s’en retourner du pays de Moab; car elle apprit au pays de Moab, que l’Eternel avait visité son peuple, en leur donnant du pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Ainsi elle partit du lieu où elle avait demeuré, et ses deux belles-filles avec elle, et elles se mirent en chemin pour retourner au pays de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Et Nahomi dit à ses deux belles-filles: Allez, retournez chacune en la maison de sa mère; l’Eternel vous fasse du bien, comme vous en avez fait à ceux qui sont morts, et à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'L’Eternel vous fasse trouver du repos à chacune dans la maison de son mari; et elle les baisa; mais elles élevèrent leur voix, et pleurèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'Et lui dirent: Mais plutôt nous retournerons avec toi vers ton peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Et Nahomi répondit: Retournez-vous-en, mes filles; pourquoi viendriez-vous avec moi? Ai-je encore des fils en mon ventre, afin que vous les ayez pour maris?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Retournez-vous-en, mes filles, allez-vous-en; car je suis trop âgée pour être remariée; et quand je dirais que j’en aurais quelque espérance, quand même dès cette nuit je serais avec un mari, et quand même j’aurais enfanté des fils;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'Les attendriez-vous jusqu’à ce qu’ils fussent grands? Différeriez-vous pour eux d’être remariées? Non, mes filles; certes je suis dans une plus grande amertume que vous, parce que la main de l’Eternel s’est déployée contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Alors elles élevèrent leur voix, et pleurèrent encore; et Horpa baisa sa belle-mère; mais Ruth resta avec elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Et Nahomi lui dit: Voici, ta belle-soeur s’en est retournée à son peuple et à ses dieux; retourne-t’en après ta belle-soeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Mais Ruth répondit: Ne me prie point de te laisser, pour m’éloigner de toi; car où tu iras, j’irai; et où tu demeureras, je demeurerai; ton peuple sera mon peuple, et ton Dieu sera mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Là où tu mourras, je mourrai, et j’y serai ensevelie. Ainsi me fasse l’Eternel et ainsi y ajoute, qu’il n’y aura que la mort qui me sépare de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Nahomi donc voyant qu’elle était résolue d’aller avec elle, cessa de lui en parler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Et elles marchèrent toutes deux jusqu’à ce qu’elles vinrent à Bethléhem; et comme elles furent entrées dans Bethléhem, toute la ville se mit à parler sur son sujet; et les femmes dirent: N’est-ce pas ici Nahomi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Et elle leur répondit: Ne m’appelez point Nahomi, appelez-moi Mara. Car le Tout-Puissant m’a remplie d’amertume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Je m’en allai pleine de biens, et l’Eternel me ramène vide. Pourquoi m’appelleriez-vous Nahomi, puisque l’Eternel m’a abattue, et que le Tout-Puissant m’a affligée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'C’est ainsi que s’en retourna Nahomi, et avec elle Ruth la Moabite, sa belle-fille, qui était venue du pays de Moab; et elles entrèrent dans Bethléhem au commencement de la moisson des orges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Or le mari de Nahomi avait là un parent, homme fort et vaillant, de la famille d’Eli-mélec, qui avait nom Booz.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Et Ruth la Moabite dit à Nahomi: Je te prie que j’aille aux champs, et je glanerai quelques épis après celui devant lequel j’aurai trouvé grâce. Et elle lui répondit: Va, ma fille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Elle s’en alla donc et entra dans un champ, et glana après les moissonneurs; et il arriva qu’elle se rencontra dans un champ qui appartenait à Booz, lequel était de la famille d’Eli-mélec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Or voici, Booz vint de Bethléhem, et il dit aux moissonneurs: L’Eternel soit avec vous; et ils lui répondirent: L’Eternel te bénisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Puis Booz dit à son serviteur qui avait charge sur les moissonneurs: A qui est cette jeune fille?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Et le serviteur qui avait charge sur les moissonneurs, répondit, et dit: C’est une jeune femme Moabite, qui est venue avec Nahomi du pays de Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Et elle nous a dit: Je vous prie que je glane, et que j’amasse quelques poignées après les moissonneurs; étant donc entrée elle est demeurée depuis le matin jusqu’à cette heure. C’est là le peu de temps qu’elle a demeuré en la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Alors Booz dit à Ruth: Ecoute, ma fille,: ne va point glaner dans un autre champ, et même ne sors point d’ici; et ne bouge point d’ici d’auprès de mes jeunes filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Regarde le champ où l’on moissonnera, et va après elles; n’ai-je pas défendu à mes garçons de te toucher? et si tu as soif, va aux vaisseaux, et bois de ce que les garçons auront puisé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Alors elle tomba le visage contre terre, et se prosterna, et lui dit: Comment ai-je trouvé grâce devant toi, que tu me connaisses, vu que je suis étrangère?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Booz répondit, et lui dit: Tout ce que tu as fait à ta belle-mère, depuis que ton mari est mort, m’a été exactement rapporté; et comment tu as laissé ton père, et ta mère, et le pays de ta naissance, et tu es venue vers un peuple que tu n’avais point connu auparavant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'L’Eternel récompense ton oeuvre, et que ton salaire soit entier de la part de l’Eternel le Dieu d’Israël, sous les ailes duquel tu t’es venue retirer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Et elle dit: Monseigneur, je trouve grâce devant toi, car tu m’as consolée, et tu as parlé selon le coeur de ta servante; et cependant je ne suis point autant que l’une de tes servantes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Booz lui dit encore à l’heure du repas: Approche-toi d’ici, et mange du pain, et trempe ton morceau dans le vinaigre; et elle s’assit à côté des moissonneurs, et il lui donna du grain rôti, et elle en mangea, et fut rassasiée, et serra le reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Puis elle se leva pour glaner; et Booz commanda à ses garçons, en disant: Qu’elle glane même entre les javelles, et ne lui faites point de honte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Et même vous lui laisserez, comme par mégarde, quelques poignées; vous les lui laisserez, et elle les recueillera, et vous ne l’en censurerez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Elle glana donc au champ jusqu’au soir, et elle battit ce quelle avait recueilli, et il y eut environ un Epha d’orge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Et elle l’emporta, et vint en la ville; et sa belle- mère vit ce qu’elle avait glané. Elle tira aussi ce qu’elle avait serré de ce qu’elle avait eu de reste après qu’elle eut été rassasiée, et elle le lui donna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Alors sa belle-mère lui dit: Où as-tu glané aujourd’hui, et où as-tu fait ceci? Béni soit celui qui t’a reconnue. Et elle déclara à sa belle-mère chez qui elle avait fait cela, et dit: L’homme chez qui j’ai fait ceci aujourd’hui, s’appelle Booz.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Et Nahomi dit à sa belle-fille: Béni soit-il de l’Eternel, puisqu’il a la même bonté pour les vivants qu’il avait eue pour les morts. Et Nahomi lui dit: Cet homme nous est proche parent, et il est un de ceux qui ont le droit de retrait lignager.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Et Ruth la Moabite dit: Et même il m’a dit: Ne bouge point d’avec les garçons qui m’appartiennent, jusqu’à ce qu’ils aient achevé toute la moisson qui m’appartient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Et Nahomi dit à Ruth sa belle-fille: Ma fille, il est bon que tu sortes avec ses jeunes filles, et qu’on ne te rencontre point dans un autre champ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Elle ne bougea donc point d’avec les jeunes filles de Booz, afin de glaner, jusqu’à ce que la moisson des orges et la moisson des froments fût achevée, puis elle se tint avec sa belle-mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Et Nahomi sa belle-mère lui dit: Ma fille, ne te chercherai-je pas du repos, afin que tu sois heureuse?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Maintenant donc Booz, avec les jeunes filles duquel tu as été, n’ est-il pas de notre parenté? Voici, il vanne cette nuit les orges qui ont été foulées dans l’aire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'C’est pourquoi lave-toi, et oins-toi, et mets sur toi tes plus beaux habits, et descends dans l’aire; mais ne te fais point connaître à lui jusqu’à ce qu’il ait achevé de manger et de boire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Puis quand il se couchera, sache le lieu où il couchera; et entre, et découvre ses pieds, et te couche, et il te dira ce que tu auras à faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Et elle lui répondit: Je ferai tout ce que tu me dis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Elle descendit donc à l’aire, et fit tout ce que sa belle-mère lui avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Et Booz mangea et but, et étant devenu plus gai, il se vint coucher au bout d’un tas de javelles; et elle vint tout doucement, et découvrit ses pieds, et se coucha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Et sur le minuit cet homme s’épouvanta, et retira ses pieds; car voici une femme était couchée à ses pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Et il lui dit: Qui es-tu? Et elle répondit: Je suis Ruth ta servante; étends le pan de ta robe sur ta servante, car tu as droit de retrait lignager.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Et il dit: Ma fille, que l’Eternel te bénisse; Cette dernière gratuité que tu témoignes, est plus grande que la première, de n’être point allée après les jeunes gens, pauvres ou riches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Or maintenant, ma fille, ne crains point, je te ferai tout ce que tu me diras, car toute la porte de mon peuple sait que tu es une femme vertueuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Or maintenant il est très-vrai que j’ai droit de retrait lignager; mais aussi il y en a un autre, plus proche que moi, qui a le droit de retrait lignager.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Passe ici cette nuit, et quand le matin sera venu, si cet homme-là veut user envers toi du droit de retrait lignager, à la bonne heure, qu’il en use; mais s’il ne lui plaît pas d’user envers toi du droit de retrait lignager, j’en userai envers toi; l’Eternel est vivant; demeure ici couchée jusqu’au matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Elle demeura donc couchée à ses pieds jusqu’au matin, puis elle se leva avant qu’on se put reconnaître l’un l’autre; car il dit: Qu’on ne sache point qu’aucune femme soit entrée dans l’aire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Puis il dit: Donne-moi le linge qui est sur toi, et tiens-le de ta main; et elle le tint, et il mesura six mesures d’orge, et les mit sur elle; puis il rentra dans la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Et elle vint vers sa belle-mère; laquelle lui dit: Qui es-tu, ma fille? et elle lui déclara tout ce qui s’était passé entre cet homme et elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Et elle dit: Il m’a donné ces six mesures d’orge; car il m’a dit: Tu ne retourneras point à vide vers ta belle- mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Et Nahomi dit: Ma fille, demeure ici jusqu’à ce que tu saches comment l’affaire se terminera; car cet homme-là ne se donnera point de repos qu’il n’ait achevé l’affaire aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Booz donc monta à la porte, et s’y assit. Et voici, celui qui avait le droit de retrait lignager, et duquel Booz avait parlé, passait; et Booz lui dit: Toi un tel, détourne-toi, et assieds-toi ici. Et il se détourna, et s’assit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Et Booz prit dix hommes d’entre les Anciens de la ville, et leur dit: Asseyez-vous ici; et ils s’assirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Puis il dit à celui qui avait le droit de retrait lignager: Nahomi qui est retournée du pays de Moab, a vendu la portion du champ qui appartenait à notre frère Eli-mélec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Et j’ai pensé qu’il fallait te le faire savoir, et te dire: Acquiers-la en la présence de ceux qui sont ici assis, et en la présence des Anciens de mon peuple; si tu la veux racheter par droit de retrait lignager, rachète- la; mais si tu ne la veux pas racheter, déclare-le-moi, afin que je le sache: car il n’y en a point d’autre que toi qui la puisse racheter par droit de retrait lignager, et je suis après toi. Il répondit: Je la rachèterai par droit de retrait lignager.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Et Booz dit: Au jour que tu acquerras le champ de la main de Nahomi, tu l’acquerras aussi de Ruth la Moabite, femme au défunt, pour susciter le nom du défunt dans son héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Et celui qui avait le droit de retrait lignager dit: Je ne saurais le racheter, de peur que je ne dissipe mon héritage; toi, prends pour toi le droit de retrait lignager que j’y ai; car je ne saurais le racheter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Or c’était une ancienne coutume en Israël, qu’au cas de droit de retrait lignager et de subrogation, pour confirmer la chose l’homme déchaussait son soulier, et le donnait à son prochain, et c’était là un témoignage en Israël qu’on cédait son droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Quand donc celui qui avait le droit de retrait lignager eut dit à Booz: Acquiers-le pour toi; il déchaussa son soulier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Et Booz dit aux Anciens et à tout le peuple: Vous êtes aujourd’hui témoins que j’ai acquis de la main de Nahomi, tout ce qui appartenait à Eli-mélec, et tout ce qui était à Kiljon, et à Mahlon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Et que je me suis aussi acquis pour femme Ruth la Moabite, femme de Mahlon, pour susciter le nom du défunt dans son héritage, afin que le nom du défunt ne soit point retranché d’entre ses frères, et de la ville de son habitation; vous en êtes témoins aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Et tout le peuple qui était à la porte, et les Anciens dirent: Nous en sommes témoins. L’Eternel fasse que la femme qui entre dans ta maison, soit comme Rachel, et comme Léa, qui toutes deux ont édifié la maison d’Israël; et porte-toi vertueusement en Ephrat, et rends ton nom célèbre dans Bethléhem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Et que de la postérité que l’Eternel te donnera de cette jeune femme, ta maison soit comme la maison de Phares, que Tamar enfanta à Juda!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Ainsi Booz prit Ruth, et elle lui fut pour femme; et il vint vers elle; et l’Eternel lui fit la grâce de concevoir, et elle enfanta un fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Et les femmes dirent à Nahomi: Béni soit l’Eternel qui n’a pas voulu te laisser manquer aujourd’hui d’un homme qui eût le droit de retrait lignager; et que son nom soit réclamé en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Et qu’il te soit pour te faire revenir l’âme, et pour soutenir ta vieillesse; car ta belle-fille, qui t’aime, a enfanté cet enfant, et elle te vaut mieux que sept fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Alors Nahomi prit l’enfant, et le mit dans son sein, et elle lui tenait lieu de nourrice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Et les voisines lui donnèrent un nom, en disant: Un fils est né à Nahomi; et l’appelèrent Obed. Ce fut le père d’Isaï, père de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Or ce sont ici les générations de Pharez. Pharez engendra Hetsron;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Hetsron engendra Ram; et Ram engendra Hamminadab;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Et Hamminadab engendra Nahasson; et Nahasson engendra Salmon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Et Salmon engendra Booz; et Booz engendra Obed;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Et Obed engendra Isaï, et Isaï engendra David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Il y avait un homme de Ramathajim Tsophim, de la montagne d’Ephraïm, le nom duquel était Elkana, fils de Jéroham, fils d’Elihu, fils de Tohu, fils de Tsuph Ephratien;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Qui avait deux femmes, dont l’une s’appelait Anne, et l’autre Pennina. Et Pennina avait des enfants, mais Anne n’en avait point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Or cet homme-là montait tous les ans, de sa ville pour adorer l’Eternel des armées, et lui sacrifier à Silo; et là étaient les deux fils d’Héli, Hophni et Phinées, Sacrificateurs de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Et le jour qu’Elkana sacrifiait il donnait des portions à Pennina sa femme, et à tous les fils et filles qu’il avait d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Mais il donnait à Anne une portion honorable; car il aimait Anne; mais l’Eternel l’avait rendue stérile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Et Pennina qui lui portait envie, la piquait, même fort aigrement, car elle faisait un grand bruit de ce que l’Eternel l’avait rendue stérile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Elkana faisait donc ainsi tous les ans. Mais quand Anne montait en la maison de l’Eternel, Pennina la chagrinait en cette même manière, et Anne pleurait, et ne mangeait point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Et Elkana son mari lui dit: Anne, pourquoi pleures-tu? et pourquoi ne manges-tu point? et pourquoi ton cœur est-il triste? Ne te vaux-je pas mieux que dix fils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Et Anne se leva, après avoir mangé et bu à Silo, et Héli le Sacrificateur était assis sur un siège auprès d’un des poteaux du Tabernacle de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Elle donc ayant le coeur plein d’amertume, pria l’Eternel en pleurant abondamment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Et elle fit un voeu, en disant: Eternel des armées, si tu regardes attentivement l’affliction de ta servante, et si tu te souviens de moi, et n’oublies point ta servante, et que tu donnes à ta servante un enfant mâle, je le donnerai à l’Eternel pour tous les jours de sa vie; et aucun rasoir ne passera sur sa tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Et il arriva comme elle continuait de faire sa prière devant l’Eternel, qu’Héli prenait garde à sa bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Or Anne parlait en son cœur; elle ne faisait que remuer ses lèvres, et on n’entendait point sa voix; c’est pourquoi Héli estima qu’elle était ivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Et Héli lui dit: Jusqu’à quand seras-tu ivre? va reposer ton vin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Mais Anne répondit, et dit: Je ne suis point ivre, Monseigneur; je suis une femme affligée d’esprit; je n’ai bu ni vin ni cervoise, mais j’ai épandu mon âme devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Ne mets point ta servante au rang d’une femme qui ne vaille rien; car c’est dans la grandeur de ma douleur et de mon affliction que j’ai parlé jusqu’à présent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Alors Héli répondit, et dit: Va en paix; et le Dieu d’Israël te veuille accorder la demande que tu lui as faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Et elle dit: Que ta servante trouve grâce devant tes yeux. Puis cette femme s’en alla son chemin, et elle mangea, et son visage ne fut plus tel qu’auparavant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Après cela ils se levèrent de bon matin, et se prosternèrent devant l’Eternel; puis ils s’en retournèrent, et vinrent en leur maison à Rama. Et Elkana connut Anne sa femme; et l’Eternel se souvint d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Il arriva donc quelque temps après, qu’Anne conçut, et qu’elle enfanta un fils; et elle le nomma Samuel, parce, dit-elle, que je l’ai demandé à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Puis Elkana son mari monta avec toute sa maison, pour offrir à l’Eternel le sacrifice solennel et son voeu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Mais Anne n’y monta pas; car elle dit à son mari: Je n’y irai point jusqu’à ce que le petit enfant soit sevré; et alors je le mènerai, afin qu’il soit présenté devant l’Eternel, et qu’il demeure toujours-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Et Elkana son mari lui dit: Fais ce qui te semblera bon; demeure jusqu’à ce que tu l’aies sevré; seulement que l’Eternel accomplisse sa parole. Ainsi cette femme demeura, et allaita son fils, jusqu’à ce qu’elle l’eut sevré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Et sitôt qu’elle l’eut sevré elle le fit monter avec elle, et ayant pris trois veaux, et un Epha de farine, et un baril de vin, elle le mena dans la maison de l’Eternel à Silo; et l’enfant était fort petit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Puis ils égorgèrent un veau, et ils amenèrent l’enfant à Héli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Et elle dit: Hélas, Monseigneur! aussi vrai que ton âme vit, Monseigneur, je suis cette femme qui me tenais en ta présence pour prier l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'J’ai prié pour avoir cet enfant; et l’Eternel m’a accordé la demande que je lui ai faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'C’est pourquoi je l’ai prêté à l’Eternel; il sera prêté à l’Eternel pour tous les jours de sa vie. Et il se prosterna là devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Alors Anne pria, et dit: Mon cœur s’est réjoui en l’Eternel; ma corne a été élevée par l’Eternel; ma bouche s’est ouverte sur mes ennemis, parce que je me suis réjouie de ton salut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Il n’y a nul saint comme l’Eternel; car il n’y en a point d’autre que toi, et il n’y a point de Rocher tel que notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Ne proférez point tant de paroles hautaines, hautaines; qu’il ne sorte point de votre bouche des paroles rudes; car l’Eternel est le Dieu Fort des sciences; c’est à lui à peser les entreprises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'L’arc des forts a été brisé; mais ceux qui ne faisaient que chanceler, ont été ceints de force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Ceux qui avaient accoutumé d’être rassasiés, se sont loués pour du pain; mais les affamés ont cessé de l’être, et même la stérile en a enfanté sept; et celle qui avait beaucoup de fils est devenue languissante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'L’Eternel est celui qui fait mourir, et qui fait vivre; qui fait descendre au sépulcre, et qui en fait remonter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'L’Eternel appauvrit, et enrichit; il abaisse et il élève.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Il élève le pauvre de la poudre, et il tire le misérable de dessus le fumier, pour le faire asseoir avec les principaux, et il leur donne en héritage un trône de gloire; car les fondements de la terre sont à l’Eternel, et il a posé sur eux la terre habitable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Il gardera les pieds de ses bien-aimés, et les méchants se tairont dans les ténèbres; car l’homme ne sera point le plus fort par sa force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Ceux qui contestent contre l’Eternel seront froissés; il tonnera des cieux sur chacun d’eux; l’Eternel jugera les bouts de la terre; et il donnera la force à son Roi, et élèvera la corne de son oint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Puis Elkana s’en alla à Rama en sa maison, et le jeune garçon vaquait au service de l’Eternel, en la présence d’Héli le Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Or les fils d’Héli étaient de méchants hommes; ils ne connaissaient point l’Eternel,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'Car le train ordinaire de ces Sacrificateurs-là envers le peuple, était, que quand quelqu’un faisait quelque sacrifice, le garçon du Sacrificateur venait lorsqu’on faisait bouillir la chair, ayant en sa main une fourchette à trois dents,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'Avec laquelle il frappait dans la chaudière, ou dans le chauderon, ou dans la marmite, ou dans le pot; et le Sacrificateur prenait pour soi tout ce que la fourchette enlevait; ils en faisaient ainsi à tous ceux d’Israël qui venaient là à Silo.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Même avant qu’on fît fumer la graisse, le garçon du Sacrificateur venait, et disait à l’homme qui sacrifiait: Donne-moi de la chair à rôtir pour le Sacrificateur; car il ne prendra point de toi de chair bouillie, mais de la chair crue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Que si l’homme lui répondait: Qu’on ne manque pas de faire fumer tout présentement la graisse; et après cela prends ce que ton âme souhaitera; alors il lui disait: Quoi qu’il en soit, tu en donneras maintenant; et si tu ne m’en donnes, j’en prendrai par force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Et le péché de ces jeunes hommes fut très-grand devant l’Eternel; car les gens en méprisaient l’oblation de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Or Samuel servait en la présence de l’Eternel, étant jeune garçon, vêtu d’un Ephod de lin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Sa mère lui faisait un petit roquet, qu’elle lui apportait tous les ans, quand elle montait avec son mari pour offrir le sacrifice solennel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Et Héli bénit Elkana et sa femme, et dit: L’Eternel te fasse avoir des enfants de cette femme, pour le prêt qui a été fait à l’Eternel. Et ils s’en retournèrent chez eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Et l’Eternel visita Anne, laquelle conçut et enfanta trois fils et deux filles; et le jeune garçon Samuel devint grand en la présence de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Or Héli était fort vieux, et il apprit tout ce que faisaient ses fils à tout Israël, et qu’ils couchaient avec les femmes qui s’assemblaient par troupes à la porte du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Et il leur dit: Pourquoi faites-vous ces actions-là? car j’apprends vos méchantes actions; ces choses me viennent de tout le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Ne faites pas ainsi, mes fils; car ce que j’entends dire de vous n’est pas bon; vous faites pécher le peuple de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Si un homme a péché contre un autre homme, le Juge en jugera; mais si quelqu’un pèche contre l’Eternel, qui est-ce qui priera pour lui? Mais ils n’obéirent point à la voix de leur père, parce que l’Eternel voulait les faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Cependant le jeune garçon Samuel croissait et il était agréable à l’Eternel et aux hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Or un homme de Dieu vint à Héli, et lui dit: Ainsi a dit l’Eternel: Ne me suis-je pas clairement manifesté à la maison de ton père, quand ils étaient en Egypte, en la maison de Pharaon?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'Je l’ai aussi choisi d’entre toutes les Tribus d’Israël pour être mon Sacrificateur, afin d’offrir sur mon autel, et faire fumer les parfums, et porter l’Ephod devant moi; et j’ai donné à la maison de ton père toutes les oblations des enfants d’Israël faites par le feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Pourquoi avez-vous regimbé contre mon sacrifice, et contre mon oblation que j’ai commandé de faire dans le Tabernacle? et pourquoi as-tu honoré tes fils plus que moi, pour vous engraisser du meilleur de toutes les offrandes d’Israël mon peuple?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'C’est pourquoi l’Eternel le Dieu d’Israël dit: J’avais dit certainement que ta maison et la maison de ton père marcheraient devant moi éternellement; mais maintenant l’Eternel dit: Il ne sera pas dit que je fasse cela; car j’honorerai ceux qui m’honorent, mais ceux qui me méprisent seront traités avec le dernier mépris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Voici les jours viennent que je couperai ton bras, et le bras de la maison de ton père, tellement qu’il n’y aura aucun homme en ta maison qui devienne vieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Et tu verras un adversaire établi dans le Tabernacle, au temps que Dieu enverra toute sorte de biens à Israël; et il n’y aura jamais en ta maison aucun homme qui devienne vieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Et celui de tes descendants que je n’aurai point retranché d’auprès de mon autel, sera pour faire défaillir tes yeux, et affliger ton âme; et tous les enfants de ta maison mourront en la fleur de l’âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Et ceci t’en sera le signe, savoir ce qui arrivera à tes deux fils, Hophni et Phinées, c’est qu’ils mourront tous deux en un même jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Et je m’établirai un Sacrificateur assuré; il fera selon ce qui est en mon cœur, et selon mon âme; et je lui édifierai une maison assurée, et il marchera à toujours devant mon Oint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Et il arrivera que quiconque sera resté de ta maison, viendra se prosterner devant lui pour avoir une pièce d’argent, et quelque pain, et dira: Donne-moi une place, je te prie, dans quelqu’une des charges de la Sacrificature, pour manger un morceau de pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Or le jeune garçon Samuel servait l’Eternel en la présence d’Héli; et la parole de l’Eternel était rare en ces jours-là, et il n’y avait point d’apparition de visions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Et il arriva un jour, qu’Héli étant couché en son lieu, (or ses yeux commençaient à se ternir, et il ne pouvait voir.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'Et avant que les lampes de Dieu fussent éteintes, Samuel étant aussi couché au Tabernacle de l’Eternel, dans lequel était l’Arche de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'L’Eternel appela Samuel; et il répondit: Me voici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Et il courut vers Héli, et lui dit: Me voici, car tu m’as appelé; mais Héli dit: Je ne t’ai point appelé, retourne -t’en, et te couche; et il s’en retourna, et se coucha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Et l’Eternel appela encore Samuel; et Samuel se leva, et s’en alla vers Héli, et lui dit: Me voici, car tu m’as appelé. Et Héli dit: Mon fils, je ne t’ai point appelé, retourne -t’en, et te couche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Or Samuel ne connaissait point encore l’Eternel, et la parole de l’Eternel ne lui avait point encore été révélée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Et l’Eternel appela encore Samuel pour la troisième fois; et Samuel se leva, et s’en alla vers Héli, et dit: Me voici, car tu m’as appelé; et Héli reconnut que l’Eternel appelait ce jeune garçon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Alors Héli dit à Samuel: Va-t’en, et te couche; et si on t’appelle, tu diras: Eternel parle, car ton serviteur écoute. Samuel donc s’en alla, et se coucha en son lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'L’Eternel donc vint, et se tint là; et appela comme les autres fois: Samuel, Samuel; et Samuel dit: Parle, car ton serviteur écoute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Alors l’Eternel dit à Samuel: Voici, je m’en vais faire une chose en Israël, laquelle quiconque entendra, ses deux oreilles lui corneront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'En ce jour-là j’effectuerai contre Héli tout ce que j ai dit touchant sa maison; en commençant, et en achevant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Car je l’ai averti que je m’en allais punir sa maison pour jamais, à cause de l’iniquité laquelle il a bien connue, qui est que ses fils se sont rendus infâmes, et il ne les a point réprimés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'C’est pourquoi j’ai juré contre la maison d’Héli; si jamais il se fait propitiation pour l’iniquité de la maison d’Héli, par sacrifice ou par oblation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Et Samuel demeura couché jusqu’au matin, puis il ouvrit les portes de la maison de l’Eternel. Or Samuel craignait de déclarer cette vision à Héli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Mais Héli appela Samuel, et lui dit: Samuel mon fils, et il répondit: Me voici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Et Héli dit: Quelle est la parole qui t’a été dite? Je te prie ne me la cache point. Ainsi Dieu te fasse, et ainsi il y ajoute, si tu me caches un seul mot de tout ce qui t’a été dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Samuel donc lui déclara tout ce qui lui avait été dit, et ne lui en cacha rien. Et Héli répondit: C’est l’Eternel; qu’il fasse ce qui lui semblera bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Or Samuel devenait grand, et l’Eternel était avec lui, qui ne laissa point tomber à terre une seule de ses paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Et tout Israël, depuis Dan jusqu’à Béersebah, connut que c’était une chose assurée que Samuel serait Prophète de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Et l’Eternel continua de se manifester dans Silo; car l’Eternel se manifestait à Samuel dans Silo par la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Or ce que Samuel avait dit, arriva à tout Israël; car Israël sortit en bataille pour aller à la rencontre des Philistins, et se campa près d’Eben-hézer, et les Philistins se campèrent en Aphek.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Et les Philistins se rangèrent en bataille pour aller à la rencontre d’Israël, et quand on fut dans la mêlée, Israël fut battu devant les Philistins, qui en tuèrent environ quatre mille hommes en la bataille par la campagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Et le peuple étant revenu au camp, les Anciens d’Israël dirent: Pourquoi l’Eternel nous a-t-il battus aujourd’hui devant les Philistins; faisons-nous amener de Silo l’Arche de l’alliance de l’Eternel, et qu’il vienne au milieu de nous, et nous délivre de la main de nos ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Le peuple donc envoya à Silo, et on apporta de là l’Arche de l’alliance de l’Eternel des armées, qui habite entre les Chérubins; et là étaient les deux fils d’Héli, Hophni, et Phinées, avec l’Arche de l’alliance de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Et il arriva que comme l’Arche de l’Eternel entrait au camp, tout Israël se mit à jeter de si grands cris de joie, que la terre en retentissait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Et les Philistins entendant le bruit de ces cris de joie, dirent: Que veut dire ce bruit, et que signifient ces grands cris de joie au camp de ces Hébreux? et ils surent que l’Arche de l’Eternel était venue au camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Et les Philistins eurent peur, parce qu’on disait: Dieu est venu au camp; et ils dirent: Malheur à nous! car ceci n’a pas été aux jours passés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Malheur à nous! Qui nous délivrera de la main de ces Dieux-là si glorieux? Ce sont ces Dieux qui ont frappé les Egyptiens au désert, outre toutes les autres plaies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Philistins renforcez-vous, et soyez hommes, de peur que vous ne soyez asservis aux Hébreux, comme ils vous ont été asservis; soyez donc hommes, et combattez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Les Philistins donc combattirent, et les Israëlites furent battus, et s’enfuirent chacun en sa tente; et il y eut une fort grande défaite, car il y demeura d’Israël trente mille hommes de pied.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Et l’Arche de Dieu fut prise, et les deux fils d’Héli, Hophni et Phinées, moururent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Or un homme de Benjamin s’enfuit de la bataille, et arriva à Silo ce même jour-là, ayant ses vêtements déchirés, et de la terre sur sa tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Et comme il arrivait, voici, Héli était assis sur un siège à côté du chemin, étant attentif; car son cœur tremblait à cause de l’Arche de Dieu. Cet homme-là donc vint portant les nouvelles dans la ville, et toute la ville se mit à crier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Et Héli entendant le bruit de ce cri, dit: Que veut dire ce grand tumulte? et cet homme se hâtant vint à Héli, et lui raconta tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Or Héli était âgé de quatre vingt dix-huit ans; et ses yeux étaient tout ternis, et il ne pouvait voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Cet homme-là donc dit à Héli: Je suis celui qui viens de la bataille, car je me suis aujourd’hui échappé de la bataille. Et Héli dit: Qu’y est-il arrivé, mon fils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Et celui qui portait les nouvelles répondit, et dit: Israël a fui devant les Philistins, et même il y a eu une grande défaite du peuple; et tes deux fils, Hophni et Phinées, sont morts, et l’Arche de Dieu a été prise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Et il arriva qu’aussitôt qu’il eut fait mention de l’Arche de Dieu, Héli tomba à la renverse de dessus son siège à côté de la porte, et se rompit la nuque du cou, et mourut; car cet homme était vieux et pesant. Or il avait jugé Israël quarante ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Et sa belle-fille, femme de Phinées, qui était grosse, et sur le point d’accoucher, ayant appris la nouvelle que l’Arche de Dieu était prise, et que son beau-père et son mari étaient morts, se courba et enfanta; car ses douleurs lui étaient survenues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Et comme elle mourait, celles qui l’assistaient, lui dirent: Ne crains point; car tu as enfanté un fils; mais elle ne répondit rien, et n’en tint point de compte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Mais elle nomma l’enfant I-Cabod, en disant: La gloire de l’Eternel est transportée d’Israël; parce que l’Arche de l’Eternel était prise, et à cause de son beau-père et de son mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Elle dit donc: La gloire est transportée d’Israël; car l’Arche de Dieu est prise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Or les Philistins prirent l’Arche de Dieu, et l’emmenèrent d’Eben- hézer à Asdod.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Les Philistins donc prirent l’Arche de Dieu, et l’emmenèrent dans la maison de Dagon, et la posèrent auprès de Dagon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Et le lendemain les Asdodiens s’étant levés de bon matin, voici, Dagon était tombé le visage contre terre, devant l’Arche de l’Eternel; mais ils prirent Dagon, et le remirent à sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Ils se levèrent encore le lendemain de bon matin, et voici, Dagon était tombé le visage contre terre, devant l’Arche de l’Eternel; sa tête et les deux paumes de ses mains coupées, étaient sur le seuil, et le tronc seul de Dagon était demeuré auprès de l’Arche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'C’est pour cela que les Sacrificateurs de Dagon, et tous ceux qui entrent en sa maison, ne marchent point sur le seuil de Dagon à Asdod, jusqu’à aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Puis la main de l’Eternel s’appesantit sur le Asdodiens, et les rendit tout désolés, et les frappa au dedans du fondement dans Asdod, et dans tout son territoire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Ceux donc d’Asdod voyant qu’il en allait ainsi, dirent: L’Arche du Dieu d’Israël ne demeurera point avec nous; car sa main est appesantie sur nous, et sur Dagon notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Et ils envoyèrent, et assemblèrent vers eux tous les Gouverneurs des Philistins, et dirent: Que ferons-nous de l’Arche du Dieu d’Israël? Et ils répondirent: Qu’on transporte à Gath l’Arche du Dieu d’Israël. Ainsi on transporta l’Arche du Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Mais il arriva qu’après qu’on l’eut transportée, la main de l’Eternel fut sur la ville de Gath avec un fort grand effroi; et il frappa les gens de la ville depuis le plus petit jusqu’au plus grand, tellement que leur fondement était couvert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Ils envoyèrent donc l’Arche de Dieu à Hékron. Or comme l’Arche de Dieu entrait à Hékron, ceux de Hékron s’écrièrent, en disant: Ils ont fait détourner vers nous l’Arche du Dieu d’Israël, pour nous faire mourir, nous et notre peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'C’est pourquoi ils envoyèrent, et assemblèrent tous les Gouverneurs des Philistins, en disant: Laissez aller l’Arche du Dieu d’Israël, et qu’elle s’en retourne en son lieu; afin qu’elle ne nous fasse point mourir, nous et notre peuple; car il y avait une frayeur mortelle par toute la ville, et la main de Dieu y était fort appesantie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Et les hommes qui n’en mouraient point, étaient frappés au dedans du fondement, de sorte que le cri de la ville montait jusqu’au ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'L’Arche donc de l’Eternel ayant été pendant sept mois au pays des Philistins,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Les Philistins appelèrent les Sacrificateurs et les devins, et leur dirent: Que ferons-nous de l’Arche de l’Eternel? Déclarez-nous comment nous la renverrons en son lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Et ils répondirent: Si vous renvoyez l’Arche du Dieu d’Israël, ne la renvoyez point à vide, et ne manquez pas à lui payer l’oblation pour le péché; alors vous serez guéris, ou vous saurez pourquoi sa main ne se sera point retirée de dessus vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Et ils dirent: Quelle est l’oblation que nous lui payerons pour le péché? Et ils répondirent: Selon le nombre des Gouvernements des Philistins vous donnerez cinq fondements d’or, et cinq souris d’or; car une même plaie a été sur vous tous, et sur vos Gouvernements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Vous ferez donc des figures de vos fondements, et des figures des souris qui gâtent le pays, et vous donnerez gloire au Dieu d’Israël. Peut-être retirera-t-il sa main de dessus vous, et de dessus vos dieux, et de dessus votre pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Et pourquoi endurciriez-vous votre cœur, comme l’Egypte et Pharaon ont endurci leur cœur? Après qu’il eut fait de merveilleux exploits parmi eux ne les laissèrent-ils pas aller, et ils s’en allèrent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Maintenant donc prenez de quoi faire un chariot tout neuf, et prenez deux jeunes vaches qui allaitent leurs veaux, sur lesquelles on n’ait point encore mis de joug, et attelez au chariot les deux jeunes vaches, et faites ramener leurs petits en la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Puis prenez l’Arche de l’Eternel et mettez-la sur le chariot, et mettez les ouvrages d’or que vous lui aurez payés pour l’oblation du péché, dans un petit coffre à côté de l’Arche, puis renvoyez-la, et elle s’en ira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Et vous prendrez garde à elle; si l’Arche monte vers Beth-sémes, par le chemin de sa contrée, c’est l’Eternel qui nous a fait tout ce grand mal; si elle n’y va pas, nous saurons alors que sa main ne nous a point touchés, mais que ceci nous est arrivé par hasard.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Et ces gens-là firent ainsi; ils prirent donc deux jeunes vaches qui allaitaient, ils les attelèrent au chariot, et ils enfermèrent leurs petits dans l’étable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Et mirent sur le chariot l’Arche de l’Eternel, et le petit coffre avec les souris d’or, et les figures de leurs fondements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Alors les jeunes vaches prirent tout droit le chemin de Beth- sémes, tenant toujours le même chemin en marchant et en mugissant; et elles ne se détournèrent ni à droite ni à gauche,; et les Gouverneurs des Philistins allèrent après elles jusqu’à la frontière de Beth-sémes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Or ceux de Beth-sémes moissonnaient les blés en la vallée; et ayant élevé leurs yeux, ils virent l’Arche, et furent fort réjouis quand ils la virent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Et le chariot vint au champ de Josué Beth-sémite, et s’arrêta-là. Or il y avait là une grande pierre, et on fendit le bois du chariot, et on offrit les jeunes vaches en holocauste à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Car les Lévites descendirent l’Arche de l’Eternel, et le petit coffre qui était auprès, dans lequel étaient les ouvrages d’or, et les mirent sur cette grande pierre. En ce même jour ceux de Beth- sémes offrirent des holocaustes et sacrifièrent des sacrifices à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Et les cinq Gouverneurs des Philistins ayant vu cela, retournèrent le même jour à Hékron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Et c’est ici le nombre des fondements d’or que les Philistins donnèrent à l’Eternel en offrande pour le péché; un pour Asdod; un pour Gaza; un pour Askelon; un pour Gath; un pour Hékron;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Et les souris d or, selon le nombre de toutes les villes des Philistins, savoir des cinq Gouvernements, de la part tant des villes fermées, que des villes non murées; et ils les amenèrent jusqu’à la grande pierre sur laquelle on posa l’Arche de l’Eternel; et qui jusqu’à ce jour est dans le champ de Josué Beth-sémite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Or l’Eternel frappa des gens de Beth-sémes, parce qu’ils avaient regardé dans l’Arche de l’Eternel, il frappa, dis-je, du peuple cinquante mille et soixante et dix hommes; et le peuple mena deuil, parce que l’Eternel l’avait frappé d’une grande plaie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Alors ceux de Beth-sémes dirent: Qui pourrait subsister en la présence de l’Eternel, ce Dieu Saint? Et vers qui montera-t-il en s’éloignant de nous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Et ils envoyèrent des messagers aux habitants de Kirjath-jéharim, en disant: Les Philistins ont ramené l’Arche de l’Eternel; descendez, et faites-la monter vers vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Ceux donc de Kirjath-jéharim vinrent et firent monter l’Arche de l’Eternel, et la mirent dans la maison d’Abinadab au coteau; et ils consacrèrent Eléazar son fils pour garder l’Arche de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Or il arriva que depuis le jour que l’Arche de l’Eternel fut posée à Kirjath-jéharim, il se passa un long temps, savoir vingt années, et toute la maison d’Israël soupira après l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Et Samuel parla à toute la maison d’Israël, en disant: Si vous vous retournez de tout votre cœur à l’Eternel, ôtez du milieu de vous les dieux des étrangers, et Hastaroth, et rangez votre cœur à l’Eternel, et le servez lui seul; et il vous délivrera de la main des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Alors les enfants d’Israël ôtèrent les Bahalins, et Hastaroth, et ils servirent l’Eternel seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Et Samuel dit: Assemblez tout Israël à Mitspa, et je prierai l’Eternel pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Ils s’assemblèrent donc à Mitspa; et ils y puisèrent de l’eau, qu’ils répandirent devant l’Eternel, et ils jeûnèrent ce jour-là; et dirent: Nous avons péché contre l’Eternel. Et Samuel jugea les enfants d’Israël à Mitspa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Or quand les Philistins eurent appris que les enfants d’Israël étaient assemblés à Mitspa, les Gouverneurs des Philistins montèrent contre Israël; ce que les enfants d’Israël ayant appris, ils eurent peur des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Et les enfants d’Israël dirent à Samuel: Ne cesse point de crier pour nous à l’Eternel notre Dieu, afin qu’il nous délivre de la main des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Alors Samuel prit un agneau de lait, et l’offrit tout entier à l’Eternel en holocauste; et Samuel cria à l’Eternel pour Israël, et l’Eternel l’exauça.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Il arriva donc comme Samuel offrait l’holocauste, que les Philistins s’approchèrent pour combattre contre Israël, mais l’Eternel fit gronder en ce jour-là un grand tonnerre sur les Philistins, et les mit en déroute, et ils furent battus devant Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Et ceux d’Israël sortirent de Mitspa, et poursuivirent les Philistins, et les frappèrent jusqu’au-dessous de Bethcar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Alors Samuel prit une pierre, et la mit entre Mitspa et le rocher; et il appela le nom de ce lieu-là Ebenhézer, et dit: L’Eternel nous a secourus jusqu’en ce lieu-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Et les Philistins furent abaissés, et ils ne vinrent plus depuis ce temps-là au pays d’Israël; et la main de l’Eternel fut sur les Philistins tout le temps de Samuel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Et les villes que les Philistins avaient prises sur Israël, retournèrent à Israël, depuis Hékron, jusqu’à Gath, avec leurs confins. Samuel donc délivra Israël de la main des Philistins, et il y eut paix entre Israël et les Amorrhéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Et Samuel jugea Israël tous les jours de sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Et il allait tous les ans faire le tour à Bethel, et à Guilgal, et à Mitspa, et il jugeait Israël en tous ces lieux-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Puis il s’en retournait à Rama, parce que sa maison était là, et il jugeait là Israël; et il y bâtit un autel à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Et il arriva que quand Samuel fut devenu vieux, il établit ses fils pour Juges sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Son fils premier-né avait nom Joël; et le second avait nom Abija; et ils jugeaient à Beersébah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Mais ses fils ne suivaient point son exemple, car ils se détournaient après le gain déshonnête; ils prenaient des présents, et ils s’éloignaient de la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'C’est pourquoi tous les Anciens d’Israël s’assemblèrent, et vinrent vers Samuel à Rama;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'Et lui dirent: Voici, tu es devenu vieux, et tes fils ne suivent point tes voies; maintenant établis sur nous un Roi pour nous juger comme en ont toutes les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Et Samuel fut affligé de ce qu’ils lui avaient dit: Etablis sur nous un Roi pour nous juger; et Samuel fit requête à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Et l’Eternel dit à Samuel: Obéis à la voix du peuple en tout ce qu’ils te diront: car ce n’est pas toi qu’ils ont rejeté, mais c’est moi qu’ils ont rejeté, afin que je ne règne point sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Selon toutes les actions qu’ils ont faites depuis le jour que je les ai fait monter hors d’Egypte jusques à ce jour, et qu’ils m’ont abandonné, et ont servi d’autres dieux; ainsi en font-ils aussi à ton égard.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Maintenant donc obéis à leur voix; mais ne manque point de leur protester, et de leur déclarer comment le Roi qui régnera sur eux, les traitera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Ainsi Samuel dit toutes les paroles de l’Eternel, au peuple qui lui avait demandé un Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Il leur dit donc: Ce sera ici la manière en laquelle vous traitera le Roi qui régnera sur vous. Il prendra vos fils et les mettra sur ses chariots, et parmi ses gens de cheval, et ils courront devant son chariot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'Il les prendra aussi pour les établir Gouverneurs sur milliers, et Gouverneurs sur cinquantaines, pour faire son labourage, pour faire sa moisson, et pour faire ses instruments de guerre, et tout l’attirail de ses chariots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Il prendra aussi vos filles pour en faire des parfumeuses, des cuisinières, et des boulangères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Il prendra aussi vos champs, vos vignes; et les terres où sont vos bons oliviers, et il les donnera à ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Il dîmera ce que vous aurez semé et ce que vous aurez vendangé, et il le donnera à ses Eunuques, et à ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Il prendra vos serviteurs, et vos servantes, et l’élite de vos jeunes gens, et vos ânes, et les emploiera à ses ouvrages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Il dîmera vos troupeaux, et vous serez ses esclaves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'En ce jour-là vous crierez à cause de votre Roi que vous vous serez choisi, mais l’Eternel ne vous exaucera point en ce jour-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Mais le peuple ne voulut point acquiescer au discours de Samuel, et ils dirent: Non; mais il y aura un Roi sur nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Nous serons aussi comme toutes les nations; et notre Roi nous jugera, il sortira devant nous, et il conduira nos guerres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Samuel donc entendit toutes les paroles du peuple, et les rapporta à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Et l’Eternel dit à Samuel: Obéis à leur voix, et établis leur un Roi. Et Samuel dit à ceux d’Israël: Allez-vous-en chacun en sa ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Or il y avait un homme de Benjamin, qui avait nom Kis, fort et vaillant; fils d Abiël, fils de Tséror, fils de Becorad, fils d’Aphiah, fils d’un Benjamite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Lequel avait un fils nommé Saül, jeune homme d’élite, et beau, en sorte qu’il n’y avait aucun des enfants d’Israël qui fût plus beau que lui, et depuis les épaules en haut il était plus grand qu’aucun du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Or les ânesses de Kis, père de Saül s’étaient perdues; et Kis dit à Saül son fils: Prends maintenant avec toi un des serviteurs et te lève, et va chercher les ânesses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Il passa donc par la montagne d’Ephraïm, et traversa le pays de Salisa; mais ils ne les trouvèrent point. Puis ils passèrent par le pays de Sehalim, mais elles n’y furent point; ils passèrent ensuite par le pays de Jémini, mais ils ne les trouvèrent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Quand ils furent venus au pays de Tsuph, Saül dit à son serviteur qui était avec lui: Viens, et retournons-nous-en, de peur que mon père n’ait cessé d’être en peine des ânesses, et qu’il ne soit en peine de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Et le serviteur lui dit: Voici, je te prie, il y a en cette ville un homme de Dieu, qui est un personnage fort vénérable; tout ce qu’il dit arrive infailliblement; allons y maintenant, peut-être qu’il nous enseignera le chemin que nous devons prendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Et Saül dit à son serviteur: Mais si nous y allons, que porterons- nous à l’homme de Dieu, car la provision nous a manqué, et nous n’avons aucun présent pour porter à l’homme de Dieu? qu’avons-nous avec nous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Et le serviteur répondit encore à Saül, et dit: Voici j’ai encore entre mes mains le quart d’un sicle d’argent, et je le donnerai à l’homme de Dieu, et il nous enseignera notre chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '0r c’était anciennement la coutume en Israël quand on allait consulter Dieu, qu’on se disait l’un à l’autre: Venez, allons au Voyant; car celui qu’on appelle aujourd’hui Prophète, s’appelait autrefois le Voyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Et Saül dit à son serviteur: Tu dis bien; viens; allons. Et ils s’en allèrent dans la ville où était l’homme de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Et comme ils montaient par la montée de la ville, ils trouvèrent de jeunes filles qui sortaient pour puiser de l’eau, et ils leur dirent: Le Voyant n’est-il pas ici?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Et elles leur répondirent, et dirent: Il y est, le voilà devant toi; hâte-toi maintenant, car il est venu aujourd’hui en la ville, parce qu’il y a aujourd’hui un sacrifice pour le peuple dans le haut lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Comme vous entrerez dans la ville, vous le trouverez avant qu’il monte au haut lieu pour manger; car le peuple ne mangera point jusqu’à ce qu’il soit venu, parce qu’il doit bénir le sacrifice; et après cela ceux qui sont conviés en mangeront; montez donc maintenant; car vous le trouverez aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Ils montèrent donc à la ville; et comme ils entraient dans la ville, voici, Samuel, qui sortait pour monter au haut lieu, les rencontra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Or l’Eternel avait fait entendre et avait dit à Samuel, un jour avant que Saül vînt:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'Demain à cette même heure je t’enverrai un homme du pays de Benjamin, et tu l’oindras pour être le conducteur de mon peuple d’Israël, et il délivrera mon peuple de la main des Philistins; car j’ai regardé mon peuple, parce que son cri est parvenu jusqu’à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Et dès que Samuel eut aperçu Saül, l’Eternel lui dit: Voilà l’homme dont je t’ai parlé; c’est celui qui dominera sur mon peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Et Saül s’approcha de Samuel au dedans de la porte, et lui dit: Je te prie enseigne-moi où est la maison du Voyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Et Samuel répondit à Saül, et dit: Je suis le Voyant; monte devant moi au haut lieu, et vous mangerez aujourd’hui avec moi; et je te laisserai aller au matin, et je te déclarerai tout ce que tu as sur le cœur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Car quant aux ânesses que tu as perdues il y a aujourd’hui trois jours, ne t’en mets point en peine, parce qu’elles ont été trouvées. Et vers qui tend tout le désir d’Israël? n’est ce point vers toi, et vers toute la maison de ton père?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Et Saül répondit et dit: Ne suis-je pas Benjamite, de la moindre Tribu d’Israël, et ma famille n’est-elle pas la plus petite de toutes les familles de la Tribu de Benjamin? et pourquoi m’as-tu tenu de tels discours?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Samuel donc prit Saül et son serviteur, et les fit entrer dans la salle, et les plaça au plus haut bout, entre les conviés, qui étaient environ trente hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Et Samuel dit au cuisinier: Apporte la portion que je t’ai donnée, et de laquelle je t’ai dit de la serrer par devers toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Or le cuisinier avait levé une épaule, et ce qui était au dessus, et il la mit devant Saül. Et Samuel dit: Voici ce qui a été réservé, mets-le devant toi, et mange; car il t’a été gardé expressément pour cette heure, lorsque j’ai dit de convier le peuple; et Saül mangea avec Samuel ce jour-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Puis ils descendirent du haut lieu dans la ville, et Samuel parla avec Saül sur le toit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Puis s’étant levé le matin, à la pointe du jour, Samuel appela Saül sur le toit, et lui dit: Lève-toi, et je te laisserai aller. Saül donc se leva, et ils sortirent eux deux dehors, lui et Samuel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Et comme ils descendaient au bas de la ville, Samuel dit à Saül: Dis au serviteur qu’il passe devant nous; lequel passa, mais toi arrête-toi maintenant, afin que je te fasse entendre la parole de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Or Samuel avait pris une fiole d’huile, laquelle il répandit sur la tête de Saül, puis il le baisa, et lui dit: L’Eternel ne t’a-t-il pas oint sur son héritage, pour en être le conducteur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Quand tu seras aujourd’hui parti d’avec moi, tu trouveras deux hommes près du sépulcre de Rachel, sur la frontière de Benjamin à Tseltsah, qui te diront: Les ânesses que tu étais allé chercher ont été trouvées; et voici, ton père ne pense plus aux ânesses, et il est en peine de vous, disant: Que ferai-je au sujet de mon fils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Et lorsque étant parti de là tu auras passé outre, et que tu seras venu jusqu’au bois de chênes de Tabor; tu seras rencontré par trois hommes qui montent vers Dieu, en la maison du Dieu Fort; l’un desquels porte trois chevreaux, l’autre trois pains, et l’autre un baril de vin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Et ils te demanderont comment tu te portes, et ils te donneront deux pains, que tu recevras de leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Après cela tu viendras au coteau de Dieu, où est la garnison des Philistins; et il arrivera que sitôt que tu seras entré dans la ville, tu rencontreras une compagnie de Prophètes descendant du haut lieu, ayant devant eux une musette, un tambour, une flûte, et un violon, et qui prophétisent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Alors l’Esprit de l’Eternel te saisira, et tu prophétiseras avec eux, et tu seras changé en un autre homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Et quand ces signes-là te seront arrivés, fais tout ce qui se présentera à faire; car Dieu est avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Puis tu descendras devant moi à Guilgal, et voici, je descendrai vers toi pour offrir des holocaustes, et sacrifier des sacrifices de prospérités, tu m’attendras là sept jours, jusqu’à ce que je sois arrivé vers toi, et je te déclarerai ce que tu devras faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Il arriva donc qu’aussitôt que Saül eut tourné le dos pour s’en aller d’avec Samuel, Dieu changea son coeur en un autre, et tous ces signes-là lui arrivèrent en ce même jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Car quand ils furent venus au coteau, voici une troupe de Prophètes vint au devant de lui; et l’Esprit de Dieu le saisit, et il prophétisa au milieu d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Et il arriva que quand tous ceux qui l’avaient connu auparavant, eurent vu qu’il était avec les Prophètes, et qu’il prophétisait, ceux du peuple se dirent l’un à l’autre: Qu’est-il arrivé au fils de Kis? Saül aussi est-il entre les Prophètes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Et quelqu’un répondit, et dit: Et qui est leur père? C’est pourquoi cela passa en proverbe: Saül aussi est-il entre les Prophètes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Or Saül ayant cessé de prophétiser, vint au haut lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Et l’oncle de Saül dit à Saül et à son garçon: Où êtes-vous allés? Et il répondit: Nous sommes allés chercher les ânesses, mais voyant qu’elles ne se trouvaient point, nous sommes venus vers Samuel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Et son oncle lui dit: Déclare-moi, je te prie, ce que vous a dit Samuel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Et Saül dit à son oncle: Il nous a assuré que les ânesses étaient trouvées; mais il ne lui déclara point le discours que Samuel lui avait tenu touchant la Royauté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Or Samuel assembla le peuple devant l’Eternel à Mitspa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Et il dit aux enfants d’Israël: Ainsi a dit l’Eternel le Dieu d’Israël: J’ai fait monter Israël hors d’Egypte, et je vous ai délivrés de la main des Egyptiens, et de la main de tous les Royaumes qui vous opprimaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Mais aujourd’hui vous avez rejeté votre Dieu, lequel est celui qui vous a délivrés de tous vos maux, et de vos afflictions, et vous avez dit: Non; mais établis-nous un Roi. Présentez-vous donc maintenant devant l’Eternel, selon vos Tribus, et selon vos milliers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Ainsi Samuel fit approcher toutes les Tribus d’Israël; et la Tribu de Benjamin fut saisie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Après il fit approcher la Tribu de Benjamin selon ses familles; et la famille de Matri fut saisie; puis Saül fils de Kis fut saisi, lequel ils cherchèrent, mais il ne se trouva point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Et ils consultèrent encore l’Eternel, en disant: L’homme n’est- il pas encore venu ici? Et l’Eternel dit: Le voilà caché parmi le bagage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Ils coururent donc, et le tirèrent de là, et il se présenta au milieu du peuple, et il était plus haut que tout le peuple depuis les épaules en haut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Et Samuel dit à tout le peuple: Ne voyez-vous pas qu’il n’y en a point en tout le peuple qui soit semblable à celui que l’Eternel a choisi? Et le peuple jeta des cris de joie, et dit: Vive le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Alors Samuel prononça au peuple le droit du Royaume, et l’écrivit dans un livre, lequel il mit devant l’Eternel. Puis Samuel renvoya le peuple, chacun en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Saül aussi s’en alla en sa maison à Guébah, et les gens de guerre dont Dieu avait touché le coeur, s’en allèrent avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Mais il y eut de méchants hommes qui dirent: Comment celui-ci nous délivrerait-il? et ils le méprisèrent, et ne lui apportèrent point de présent; mais il fit le sourd.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Or Nahas Hammonite monta, et se campa contre Jabés de Galaad. Et tous ceux de Jabés dirent à Nahas: Traite alliance avec nous, et nous te servirons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Mais Nahas Hammonite leur répondit: Je traiterai alliance avec vous à cette condition, que je vous crève à tous l’oeil droit, et que je mette cela pour opprobre sur tout Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Et les Anciens de Jabés lui dirent: Donne-nous sept jours de trêve, et nous enverrons des messagers par tous les quartiers d’Israël, et s’il n’y a personne qui nous délivre, nous nous rendrons à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Les messagers donc vinrent en Guib-ha-Saül, et dirent ces paroles devant le peuple; et tout le peuple éleva sa voix, et pleura.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Et voici Saül revenait des champs derrière ses boeufs; et il dit: Qu’est-ce qu’a ce peuple pour pleurer ainsi? Et on lui récita ce qu’avaient dit ceux de Jabés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Or l’Esprit de Dieu saisit Saül, lorsqu’il entendit ces paroles, et il fut embrasé de colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Et il prit une couple de boeufs, et les coupa en morceaux, et en envoya dans tous les quartiers d’Israël par des messagers exprès, en disant: On en fera de même aux boeufs de tous ceux qui ne sortiront point, et qui ne suivront point Saül et Samuel. Et la frayeur de l’Eternel tomba sur le peuple, et ils sortirent comme si ce n’eût été qu’un seul homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Et Saül les dénombra en Bézec; et il y eut trois cent mille hommes des enfants d’Israël, et trente mille des gens de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Après ils dirent aux messagers qui étaient venus: Vous parlerez ainsi à ceux de Jabés de Galaad: Vous serez délivrés demain quand le soleil sera en sa force. Les messagers donc s’en revinrent, et rapportèrent cela à ceux de Jabés, qui s’en réjouirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Et ceux de Jabés dirent aux Hammonites: Demain nous nous rendrons à vous, et vous nous ferez tout ce qui vous semblera bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Et dès le lendemain Saül mit le peuple en trois bandes, et ils entrèrent dans le camp sur la veille du matin, et ils frappèrent les Hammonites jusques vers la chaleur du jour; et ceux qui demeurèrent de reste furent tellement dispersés çà et là, qu’il n’en demeura pas deux ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Et le peuple dit à Samuel: Qui est-ce qui dit: Saül régnera-t-il sur nous? Donnez-nous ces hommes-là, et nous les ferons mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Alors Saül dit: 0n ne fera mourir personne en ce jour, parce que l’Eternel a délivré aujourd’hui Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Et Samuel dit au peuple: Venez, et allons à Guilgal, et nous y renouvellerons la Royauté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Et tout le peuple s’en alla à Guilgal; et là ils établirent Saül pour Roi devant l’Eternel à Guilgal, et ils offrirent là des sacrifices de prospérité devant l’Eternel; et là, Saül et tous ceux d’Israël se réjouirent beaucoup.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Alors Samuel dit à tout Israël: Voici, j’ai obéi à votre parole en tout ce que vous m’avez dit, et j’ai établi un Roi sur vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Et maintenant, voici le Roi qui marche devant vous, car pour moi je suis vieux, et tout blanc de vieillesse, et voici, mes fils aussi sont avec vous; et pour moi j’ai marché devant vous, depuis ma jeunesse jusques à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Me voici, répondez-moi, devant l’Eternel, et devant son oint. De qui ai-je pris le boeuf? et de qui ai-je pris l’âne? et à qui ai-je fait tort? qui ai-je foulé? et de la main de qui ai-je pris des récompenses, afin d’user de connivence à son égard, et je vous en ferai restitution?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Et ils répondirent: Tu ne nous as point opprimés, et tu ne nous as point foulés, et tu n’as rien pris de personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Il leur dit encore: L’Eternel est témoin contre vous; son oint aussi est témoin aujourd’hui, que vous n’avez trouvé aucune chose entre mes mains. Et ils répondirent: Il en est témoin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Alors Samuel dit au peuple: L’Eternel est celui qui a fait Moïse et Aaron, et qui a fait monter vos pères hors du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Maintenant donc présentez-vous ici, et j’entrerai en procès contre vous devant l’Eternel, pour tous les bienfaits de l’Eternel, qu’il a faits à vous et à vos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Après que Jacob fut entré en Egypte, vos pères crièrent à l’Eternel, et l’Eternel envoya Moïse et Aaron qui tirèrent vos pères hors d’Egypte, et qui les ont fait habiter en ce lieu-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Mais ils oublièrent l’Eternel leur Dieu, et il les livra entre les mains de Siséra, chef de l’armée de Hatsor, et entre les mains des Philistins, et entre les mains du Roi de Moab, qui leur firent la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Après ils crièrent à l’Eternel, et dirent: Nous avons péché; car nous avons abandonné l’Eternel, et nous avons servi les Bahalins, et Hastaroth. Maintenant donc délivre-nous des mains de nos ennemis, et nous te servirons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Et l’Eternel a envoyé Jerubbahal, et Bedan, et Jephthé, et Samuel, et il vous a délivrés de la main de tous vos ennemis d’alentour, et vous avez habité en pleine assurance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Mais quand vous avez vu que Nahas Roi des enfants de Hammon venait contre vous, vous m’avez dit: Non, mais un Roi régnera sur nous; quoique l’Eternel votre Dieu fût votre Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Maintenant donc voici le Roi que vous avez choisi, que vous avez demandé, et voici l’Eternel l’a établi Roi sur vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Si vous craignez l’Eternel, et que vous le serviez, et obéissiez à sa voix, et que vous ne soyez point rebelles au commandement de l’Eternel, alors et vous, et votre Roi qui règne sur vous, vous serez sous la conduite de l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Mais si vous n’obéissez pas à la voix de l’Eternel, et si vous êtes rebelles au commandement de l’Eternel, la main de l’Eternel sera aussi contre vous, comme elle a été contre vos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Or maintenant arrêtez-vous, et voyez cette grande chose que l’Eternel va faire devant vos yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'N’est-ce pas aujourd’hui la moisson des blés? Je crierai à l’Eternel, et il fera tonner et pleuvoir; afin que vous sachiez et que vous voyiez, combien le mal que vous avez fait en la présence de l’Eternel est grand, d’avoir demandé un Roi pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Alors Samuel cria à l’Eternel, et l’Eternel fit tonner et pleuvoir en ce jour-là; et tout le peuple craignit fort l’Eternel et Samuel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Et tout le peuple dit à Samuel: Prie pour tes serviteurs l’Eternel ton Dieu, afin que nous ne mourions point; car nous avons ajouté ce mal à tous nos autres péchés, d’avoir demandé un Roi pour nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Alors Samuel dit au peuple: Ne craignez point; vous avez fait tout ce mal-ci, néanmoins ne vous détournez point d’après l’Eternel, mais servez l’Eternel de tout votre coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Ne vous en détournez donc point, car ce serait vous détourner après des choses de néant, qui ne vous apporteraient aucun profit, et qui ne vous délivreraient point; puisque ce sont des choses de néant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Car l’Eternel pour l’amour de son grand Nom n’abandonnera point son peuple; parce que l’Eternel a voulu vous faire son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Et pour moi, Dieu me garde que je pèche contre l’Eternel, et que je cesse de prier pour vous; mais je vous enseignerai le bon et le droit chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Seulement craignez l’Eternel, et servez-le en vérité, de tout votre coeur; car vous avez vu les choses magnifiques qu’il a faites pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Mais si vous persévérez à mal faire, vous serez consumés vous et votre Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saül avait régné un an, et il régna deux ans sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Et Saül choisit trois mille hommes d’Israël, dont il y en avait deux mille avec lui à Micmas, et sur la montagne de Béthel, et mille étaient avec Jonathan à Guébah de Benjamin; et il renvoya le reste du peuple, chacun en sa tente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Et Jonathan frappa la garnison des Philistins qui était au coteau, et cela fut su des Philistins; et Saül le fit publier au son de la trompette par tout le pays, en disant: Que les Hébreux écoutent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Ainsi tout Israël entendit dire: Saül a frappé la garnison des Philistins, et Israël est en mauvaise odeur parmi les Philistins. Et le peuple s’assembla auprès de Saül à Guilgal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Les Philistins aussi s’assemblèrent pour faire la guerre à Israël, ayant trente mille chariots, et six mille hommes de cheval; et le peuple était comme le sable qui est sur le bord de la mer, tant il était en grand nombre; ils montèrent donc et se campèrent à Micmas, vers l’Orient de Beth-aven.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Mais ceux d’Israël se virent dans une grande angoisse; car le peuple était fort abattu, c’est pourquoi le peuple se cacha dans les cavernes, dans les buissons épais, dans les rochers, dans les forts, et dans des fosses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Et les Hébreux passèrent le Jourdain pour aller au pays de Gad, et de Galaad. Or comme Saül était encore à Guilgal, tout le peuple effrayé se rangea vers lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Et Saül attendit sept jours selon l’assignation de Samuel; mais Samuel ne venait point à Guilgal, et le peuple s’écartait d’auprès de Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Et Saül dit: Amenez-moi un holocauste, et des sacrifices de prospérités; et il offrit l’holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Or il arriva qu’aussitôt qu’il eut achevé d’offrir l’holocauste, voici, Samuel arriva, et Saül sortit au-devant de lui pour le saluer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Et Samuel lui dit: Qu’as-tu fait? Saül répondit: Parce que je voyais que le peuple s’écartait d’avec moi, et que tu ne venais point au jour assigné, et que les Philistins étaient assemblés à Micmas;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'J’ai dit: Les Philistins descendront maintenant contre moi à Guilgal, et je n’ai point supplié l’Eternel; et après m’être retenu, quelque temps, j’ai enfin offert l’holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Alors Samuel dit à Saül: Tu as agi follement, en ce que tu n’as point gardé le commandement que l’Eternel ton Dieu t’avait ordonné; car l’Eternel aurait maintenant affermi ton règne sur Israël à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Mais maintenant ton règne ne sera point affermi; l’Eternel s’est cherché un homme selon son coeur, et l’Eternel lui a commandé d’être le Conducteur de son peuple, parce que tu n’as point gardé ce que l’Eternel t’avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Puis Samuel se leva, et monta de Guilgal à Guébah de Benjamin. Et Saül dénombra le peuple qui se trouva avec lui, qui fut d’environ six cents hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Or Saül et son fils Jonathan, et le peuple qui se trouva avec eux, se tenaient à Guébah de Benjamin, et les Philistins étaient campés à Micmas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Et il sortit trois bandes du camp des Philistins pour faire du dégât; l’une de ces bandes prit le chemin de Hophra, vers le pays de Suhal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'L’autre bande prit le chemin de Beth-oron; et la troisième prit le chemin de la frontière qui regarde vers la vallée de Tsébohim, du côté du désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Or dans tout le pays d’Israël il ne se trouvait aucun forgeron; car les Philistins avaient dit: Il faut empêcher que les Hébreux ne fassent des épées ou des hallebardes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'C’est pourquoi tout Israël descendait vers les Philistins, chacun pour aiguiser son soc, son coutre, sa cognée, et son hoyau;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'Lorsque leurs hoyaux, leurs coutres, leurs fourches à trois dents, et leurs cognées avaient la pointe gâtée, même pour raccommoder un aiguillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'C’est pourquoi il arriva que le jour du combat il ne se trouva ni épée, ni hallebarde, en la main d’aucun du peuple qui était avec Saül et Jonathan, et il n’y eut que Saül et Jonathan en qui il s’en trouvât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Et le corps de garde des Philistins sortit au passage de Micmas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Or il arriva que Jonathan, fils de Saül, dit un jour au garçon qui portait ses armes: Viens et passons vers le corps de garde des Philistins qui est au delà de ce lieu-là; mais il ne le déclara point à son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Et Saül se tenait à l’extrémité du coteau sous un grenadier, à Migron, et le peuple qui était avec lui était d’environ six cents hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Et Ahija, fils d’Ahitub, frère d’I-cabod, fils de Phinées, fils d’Héli, Sacrificateur de l’Eternel à Silo, portait l’Ephod; et le peuple ne savait point que Jonathan s’en fût allé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Or entre les passages par lesquels Jonathan cherchait de passer jusqu’au corps de garde des Philistins, il y avait un rocher du côté de deçà, et un autre rocher du côté de delà; l’un avait nom Botsets, et l’autre Séné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'L’un de ces rochers était situé du côté de l’Aquilon vis-à-vis de Micmas; et l’autre, du côté du Midi vis-à-vis de Guébah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Et Jonathan dit au garçon qui portait ses armes: Viens, passons au corps de garde de ces incirconcis; peut-être que l’Eternel opérera pour nous: car on ne saurait empêcher l’Eternel de délivrer avec beaucoup ou avec peu de gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Et celui qui portait ses armes lui dit: Fais tout ce que tu as au coeur, vas-y; voici je serai avec toi où tu voudras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Et Jonathan lui dit: Voici nous allons passer vers ces gens, et nous nous montrerons à eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'S’ils nous disent ainsi: Attendez jusqu’à ce que nous soyons venus à vous, alors nous nous arrêterons à notre place, et nous ne monterons point vers eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Mais s’ils disent ainsi: Montez vers nous, alors nous monterons; car l’Eternel les aura livrés entre nos mains. Que cela nous soit pour signe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Ils se montrèrent donc tous deux au corps de garde des Philistins, et les Philistins dirent: Voilà, les Hébreux sortent des trous où ils s’étaient cachés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Et ceux du corps de garde dirent à Jonathan, et à celui qui portait ses armes: Montez vers nous, et nous vous montrerons quelque chose. Et Jonathan dit à celui qui portait ses armes: Monte après moi; car l’Eternel les a livrés entre les mains d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Et Jonathan monta en grimpant de ses mains et de ses pieds, avec celui qui portait ses armes; puis ceux du corps de garde tombèrent devant Jonathan, et celui qui portait ses armes les tuait après lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Et cette première défaite que fit Jonathan et celui qui portait ses armes, fut d’environ vingt hommes, qui furent tués dans l’espace d’environ la moitié d’un arpent de terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Et il y eut un grand effroi au camp, à la campagne, et parmi tout le peuple; le corps de garde aussi, et ceux qui étaient allés ravager, furent effrayés, et le pays fut en trouble, tellement que ce fut comme une frayeur envoyée de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Et les sentinelles de Saül qui étaient à Guibha de Benjamin regardèrent; et voici, la multitude était en un si grand désordre qu’elle se foulait en s’en allant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Alors Saül dit au peuple qui était avec lui: Faites maintenant la revue, et voyez qui s’en est allé d’entre nous. Ils firent donc la revue, et voici Jonathan n’y était point, ni celui qui portait ses armes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Et Saül dit à Ahija: Approche l’Arche de Dieu; (car l’Arche de Dieu était en ce jour-là avec les enfants d’Israël)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Mais il arriva que pendant que Saül parlait au Sacrificateur, le tumulte qui était au camp des Philistins s’augmentait de plus en plus; et Saül dit au Sacrificateur: Retire ta main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Et Saül et tout le peuple qui était avec lui, fut assemblé à grand cri; et ils vinrent jusqu’à la bataille, et voici, les Philistins avaient les épées tirées les uns contre les autres, et il y avait un fort grand effroi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Or les Philistins avaient avec eux des Hébreux comme ils avaient eu auparavant, qui étaient montés du pays d’alentour avec eux en leur camp, et qui se joignirent incontinent aux Israëlites qui étaient avec Saül et Jonathan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Et tous les Israëlites qui s’étaient cachés dans la montagne d’Ephraïm, ayant appris que les Philistins s’enfuyaient, les poursuivirent aussi pour les combattre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Et ce jour-là l’Eternel délivra Israël, et ils allèrent en combattant jusqu’à Beth-aven.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Mais ceux d’Israël se trouvèrent fort fatigués en ce jour-là; et Saül avait fait faire au peuple ce serment, disant: Maudit soit l’homme qui mangera d’aucune chose jusqu’au soir, afin que je me venge de mes ennemis; de sorte que tout le peuple ne goûta d’aucune chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Et tout le peuple du pays vint en une forêt, où il y avait du miel qui découlait sur le dessus d’un champ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Le peuple donc entra dans la forêt, et voici du miel qui découlait; et il n’y en eut aucun qui portât sa main à sa bouche; car le peuple avait peur du serment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Or Jonathan n’avait point entendu son père lorsqu’il avait fait jurer le peuple, et il étendit le bout de la verge qu’il avait en sa main, et la trempa dans un rayon de miel; et il porta sa main à sa bouche, et ses yeux furent éclaircis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Alors quelqu’un du peuple prenant la parole, lui dit: Ton père a fait expressément jurer le peuple en disant: Maudit soit l’homme qui mangera aujourd’hui aucune chose; quoique le peuple fût fort fatigué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Et Jonathan dit: Mon père a troublé le peuple du pays. Voyez, je vous prie, comment mes yeux sont éclaircis, pour avoir un peu goûté de ce miel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'combien plus si le peuple avait aujourd’hui mangé abondamment de la dépouille de ses ennemis, qu’il a trouvée; car la défaite des Philistins n’en aurait-elle pas été plus grande?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'En ce jour-là donc ils frappèrent les Philistins depuis Micmas jusqu’à Ajalon, et le peuple fut fort las.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Puis il se jeta sur le butin, et ils prirent des brebis, des bœufs, et des veaux, et les égorgèrent sur la terre; et le peuple les mangeait avec le sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Et on en fit rapport à Saül, en disant: Voici, le peuple pèche contre l’Eternel, en mangeant, avec le sang; et il dit: Vous avez péché, roulez aujourd’hui une grande pierre sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Et Saül dit: Allez partout parmi le peuple, et dites-leur que chacun amène vers moi son boeuf, et chacun ses brebis; vous les égorgerez ici, vous les mangerez, et vous ne pécherez point contre l’Eternel, en mangeant avec le sang. Et chacun du peuple amena cette nuit-là son boeuf à la main, et ils les égorgèrent là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Et Saül bâtit un autel à l’Eternel; ce fut le premier autel qu’il bâtit à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Puis Saül dit: Descendons et poursuivons de nuit les Philistins, et les pillons jusqu’à ce que le matin soit venu, et n’en laissons pas un de reste. Et ils dirent: Fais tout ce qui te semble bon; mais le Sacrificateur dit: Approchons-nous ici vers Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Alors Saül consulta Dieu, en disant: Descendrai-je pour poursuivre les Philistins? les livreras-tu entre les mains d’Israël? et il ne lui donna point de réponse en ce jour-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Et Saül dit: Toutes les Tribus du peuple approchez-vous; et sachez, et voyez par qui ce péché est aujourd’hui arrivé:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Car l’Eternel qui délivre Israël est vivant, qu’encore que cela eût été fait par mon fils Jonathan, il en mourra certainement. Et aucun de tout le peuple ne lui répondit rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Puis il dit à tout Israël: Mettez-vous d’un côté, et nous serons de l’autre côté moi et Jonathan mon fils. Le peuple répondit à Saül: Fais ce qui te semble bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Et Saül dit à l’Eternel le Dieu d’Israël: Fais connaître celui qui est innocent. Et Jonathan et Saül furent saisis; et le peuple échappa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Et Saül dit: Jetez le sort entre moi et Jonathan mon fils. Et Jonathan fut saisi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Alors Saül dit à Jonathan: Déclare-moi ce que tu as fait. Et Jonathan lui déclara et dit: Il est vrai que j’ai goûté avec le bout de ma verge que j’avais en ma main un peu de miel; me voici, je mourrai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Et Saül dit: Que Dieu me fasse ainsi, et ainsi y ajoute, si tu ne meurs certainement, Jonathan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Mais le peuple dit à Saül: Jonathan qui a fait cette grande délivrance en Israël, mourrait-il? A Dieu ne plaise! l’Eternel est vivant, si un seul des cheveux de sa tête tombe à terre; car il a aujourd’hui opéré avec Dieu. Ainsi le peuple délivra Jonathan, et il ne mourut point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Puis Saül s’en retourna de la poursuite des Philistins, et les Philistins s’en allèrent en leur lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Saül donc prit possession du Royaume d’Israël, et fit la guerre de tous côtes contre ses ennemis, contre Moab, et contre les enfants de Hammon, et contre Edom, et contre les Rois de Tsoba, et contre les Philistins; partout où il se tournait, il mettait tout en trouble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Il assembla aussi une armée, et frappa Hamalec, et délivra Israël de la main de ceux qui le pillaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Or les fils de Saül étaient Jonathan, Jisui, et Malkisuah; et quant aux noms de ses deux filles, le nom de l’aînée était Mérab, et le nom de la plus jeune, Mical.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Et le nom de la femme de Saül était Ahinoham, fille d’Ahimahats; et le nom du Chef de son armée était Abner, fils de Ner, oncle de Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Et Kis père de Saül, et Ner père d’Abner étaient fils d’Abiël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Et il y eut une forte guerre contre les Philistins durant tout le temps de Saül; et aussitôt que Saül voyait quelque homme fort, et quelque homme vaillant, il le prenait auprès de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Or Samuel dit à Saül: L’Eternel m’a envoyé pour t’oindre afin que tu sois Roi sur mon peuple, sur Israël; maintenant donc écoute les paroles de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Ainsi a dit l’Eternel des armées: J’ai rappelé en ma mémoire ce qu’Hamalec a fait à Israël, et comment il s’opposa à lui sur le chemin, quand il montait d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Va maintenant, et frappe Hamalec, et détruisez à la façon de l’interdit tout ce qu’il a, et ne l’épargne point; mais fais mourir tant les hommes que les femmes; tant les grands que ceux qui tètent, tant les boeufs que le menu bétail, tant les chameaux que les ânes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Saül donc assembla le peuple à cri public, et en fit le dénombrement à Télaïm, qui fut de deux cent mille hommes de pied, et de dix mille hommes de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Et Saül vint jusqu’à la ville de Hamalec, et mit des embuscades en la vallée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Et Saül dit aux Kéniens: Allez retirez-vous, descendez du milieu des Hamalécites, de peur que je ne vous enveloppe avec eux; car vous usâtes de gratuité envers tous les enfants d’Israël, quand ils montèrent d’Egypte. Et les Kéniens se retirèrent d’entre les Hamalécites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Et Saül frappa les Hamalécites depuis Havila jusqu’en Sur, qui est vis-à-vis d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Et il prit vif Agag, Roi d’Hamalec; mais il fît passer tout le peuple au fil de l’épée à la façon de l’interdit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Saül donc et le peuple épargnèrent Agag, et les meilleures brebis, les meilleurs boeufs, les bêtes grasses, les agneaux, et tout ce qui était bon; et ils ne voulurent point les détruire à la façon de l’interdit; ils détruisirent seulement à la façon de l’interdit tout ce qui n’était d’aucun prix, et méprisable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Alors la parole de l’Eternel fut adressée à Samuel en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Je me repens d’avoir établi Saül pour Roi, car il s’est détourné de moi, et n’a point exécuté mes paroles. Et Samuel en fut fort attristé, et cria à l’Eternel toute cette nuit-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Puis Samuel se leva de bon matin pour aller au-devant de Saül. Et on fit rapport à Samuel, en disant: Saül est venu à Carmel, et voici il s’est fait là dresser une place, mais il s’en est retourné, et passant au delà il est descendu à Guilgal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Quand Samuel fut venu à Saül, Saül lui dit: Tu sois béni de l’Eternel; j’ai exécuté la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Et Samuel dit: Quel est donc ce bêlement de brebis à mes oreilles, et ce meuglement de boeufs que j’entends?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Et Saül répondit: Ils les ont amenés des Hamalécites; car le peuple a épargné les meilleures brebis et les meilleurs boeufs, pour les sacrifier à l’Eternel ton Dieu; et nous avons détruit le reste à la façon de l’interdit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Et Samuel dit à Saül: Arrête, et je te déclarerai ce que l’Eternel m’a dit cette nuit; et il lui répondit: Parle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Samuel donc dit: N’est-il pas vrai que, quand tu étais petit à tes yeux, tu as été fait Chef des Tribus d’Israël, et l’Eternel t’a oint pour Roi sur Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Or l’Eternel t’avait envoyé en cette expédition, et t’avait dit: Va, et détruis à la façon de l’interdit ces pécheurs, les Hamalécites, et fais-leur la guerre, jusqu’à ce qu’ils soient consumés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Et pourquoi n’as-tu pas obéi à la voix de l’Eternel, mais tu t’es jeté sur le butin, et as fait ce qui déplaît à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Et Saül répondit à Samuel: J’ai pourtant obéi à la voix de l’Eternel, et je suis allé par le chemin par lequel l’Eternel m’a envoyé, et j’ai amené Agag Roi des Hamalécites, et j’ai détruit à la façon de l’interdit les Hamalécites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Mais le peuple a pris des brebis et des boeufs du butin, comme des prémices de l’interdit, pour sacrifier à l’Eternel ton Dieu à Guilgal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Alors Samuel dit: L’Eternel prend-il plaisir aux holocaustes et aux sacrifices, comme qu’on obéisse à sa voix? Voici, l’obéissance vaut mieux que le sacrifice, et se rendre attentif vaut mieux que la graisse des moutons;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Car la rébellion est autant que le péché de divination, et c’est une idole et un Théraphim que la transgression. Parce donc que tu as rejeté la parole de l’Eternel, il t’a aussi rejeté, afin que tu ne sois plus Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Et Saül répondit à Samuel: J’ai péché parce que j’ai transgressé le commandement de l’Eternel, et tes paroles; car je craignais le peuple, et j’ai acquiescé à sa voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Mais maintenant, je te prie, pardonne-moi mon péché, et retourne- t’en avec moi, et je me prosternerai devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Et Samuel dit à Saül: Je ne retournerai point avec toi; parce que tu as rejeté la parole de l’Eternel, et que l’Eternel t’a rejeté, afin que tu ne sois plus Roi sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Et comme Samuel se tournait pour s’en aller, Saül lui prit le pan de son manteau, qui se déchira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Alors Samuel lui dit: L’Eternel a aujourd’hui déchiré le Royaume d’Israël de dessus toi, et l’a donné à ton prochain, qui est meilleur que toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Et en effet; la force d’Israël ne mentira point, elle ne se repentira point; car il n’est pas un homme, pour se repentir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Et Saül répondit: J’ai péché; mais honore moi maintenant, je te prie, en la présence des Anciens de mon peuple, et en la présence d’Israël, et retourne-t’en avec moi, et je me prosternerai devant l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Samuel donc s’en retourna et suivit Saül; et Saül se prosterna devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Puis Samuel dit: Amenez-moi Agag Roi d’Hamalec. Et Agag vint à lui, faisant le gracieux; car Agag disait: Certainement l’amertume de la mort est passée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Mais Samuel dit: Comme ton épée a privé les femmes de leurs enfants, ainsi ta mère sera privée d’enfants entre les femmes. Et Samuel mit Agag en pièces devant l’Eternel à Guilgal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Puis il s’en alla à Rama; et Saül monta en sa maison à Guibbath- Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Et Samuel n’alla plus voir Saül jusqu’au jour de sa mort; quoique Samuel eût mené deuil sur Saül, de ce que l’Eternel s’était repenti d’avoir établi Saül pour Roi sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Et l’Eternel dit à Samuel: Jusqu’à quand mèneras-tu deuil sur Saül, vu que je l’ai rejeté, afin qu’il ne règne plus sur Israël? Emplis ta corne d’huile, et viens, je t’enverrai vers Isaï Bethléhémite; car je me suis pourvu d’un de ses fils pour Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Et Samuel dit: Comment y irai-je? car Saül l’ayant appris me tuera. Et l’Eternel répondit: Tu emmèneras avec toi une jeune vache du troupeau; et tu diras: Je suis venu pour sacrifier à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Et tu inviteras Isaï au sacrifice, et là je te ferai savoir ce que tu auras à faire, et tu m’oindras celui que je te dirai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Samuel donc fit comme l’Eternel lui avait dit, et vint à Bethléhem, et les Anciens de la ville tout effrayés accoururent au-devant de lui, et dirent: Ne viens-tu que pour notre bien?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Et il répondit: Je ne viens que pour votre bien; je suis venu pour sacrifier à l’Eternel, sanctifiez-vous, et venez avec moi au sacrifice. Il fit sanctifier aussi Isaï et ses fils, et les invita au sacrifice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Et il arriva que comme ils entraient, ayant vu Eliab, il dit: Certes l’oint de l’Eternel est devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Mais l’Eternel dit à Samuel: Ne prends point garde à son visage, ni à la grandeur de sa taille, car je l’ai rejeté; parce que l’Eternel n’a point égard à ce à quoi l’homme a égard; car l’homme a égard à ce qui est devant les yeux; mais l’Eternel a égard au coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Puis Isaï appela Abinadab, et le fit passer devant Samuel, lequel dit: L’Eternel n’a pas choisi non plus celui-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Et Isaï fit passer Samma, et Samuel dit: L’Eternel n’a pas choisi non plus celui-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Ainsi Isaï fit passer ses sept fils devant Samuel; et Samuel dit à Isaï: L’Eternel n’a point choisi ceux-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Puis Samuel dit à Isaï: Sont-ce là tous tes enfants? Et il dit: Il reste encore le plus petit; mais voici, il paît les brebis. Alors Samuel dit à Isaï: Envoie-le chercher; car nous ne nous mettrons point à table jusqu’à ce qu’il soit venu ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Il envoya donc, et le fit venir. Or il était blond, de bonne mine, et beau de visage. Et l’Éternel dit à Samuel: Lève-toi, et oins- le; car c’est celui que j’ai choisi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Alors Samuel prit la corne d’huile, et l’oignit au milieu de ses frères; et depuis ce jour-là l’Esprit de l’Eternel saisit David. Et Samuel se leva, et s’en alla à Rama.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Et l’Esprit de l’Eternel se retira de Saül; et le malin esprit envoyé par l’Eternel le troublait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Et les serviteurs de Saül lui dirent: Voici maintenant, le malin esprit envoyé de Dieu te trouble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Que le Roi notre Seigneur dise à ses serviteurs qui sont devant toi, qu’ils cherchent un homme qui sache jouer du violon; et quand le malin esprit envoyé de Dieu sera sur toi, il jouera de sa main, et tu en seras soulagé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Saül donc dit à ses serviteurs: Je vous prie, trouvez-moi un homme qui sache bien jouer des instruments, et amenez-le-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Et l’un de ses serviteurs répondit, et dit: Voici, j’ai vu un fils d’Isaï Bethléhémite qui sait jouer des instruments, et qui est fort, vaillant, et guerrier, qui parle bien, bel homme, et l’Eternel est avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Alors Saül envoya des messagers à Isaï, pour lui dire: Envoie-moi David ton fils, qui est avec les brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Et Isaï prit un âne chargé de pain, et un baril de vin, et un chevreau de lait, et les envoya par David son fils, à Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Et David vint vers Saül, et se présenta devant lui; et Saül l’aima fort, et il lui servit à porter ses armes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Et Saül envoya dire à Isaï: Je te prie que David demeure à mon service; car il a trouvé grâce devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Il arrivait donc que quand le malin esprit envoyé de Dieu, était sur Saül, David prenait le violon, et en jouait de sa main; et Saül en était soulagé, et s’en trouvait bien, parce que le malin esprit se retirait de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Or les Philistins assemblèrent leurs armées pour faire la guerre, et ils s’assemblèrent à Soco, qui est de Juda, et se campèrent entre Soco et Hazéka, sur la frontière de Dammim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Saül aussi et ceux d’Israël s’assemblèrent, et se campèrent en la vallée du chêne, et rangèrent leur bataille pour aller à la rencontre des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Or les Philistins étaient sur une montagne du côté de deçà, et les Israëlites étaient sur une autre montagne du côté de delà; de sorte que la vallée était entre deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Et il sortit du camp des Philistins un homme qui se présentait entre les deux armées, et qui avait nom Goliath, de la ville de Gath, haut de six coudées et d’une paume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Et il avait un casque d’airain sur sa tête, et était armé d’une cuirasse à écailles; et sa cuirasse pesait cinq mille sicles d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Il avait aussi des jambières d’airain sur ses jambes, et un écu d’airain entre ses épaules.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'La hampe de sa hallebarde était comme l’ensuble d’un tisserand, et le fer de cette hallebarde pesait six cents sicles de fer; et celui qui portait son bouclier marchait devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Il se présentait donc, et criait aux troupes rangées d’Israël, et leur disait: Pourquoi sortiriez-vous pour vous ranger en bataille? Ne suis-je pas Philistin, et vous n’êtes-vous pas serviteurs de Saül? Choisissez l’un d’entre vous, et qu’il descende vers moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Que s’il est le plus fort en combattant avec moi, et qu’il me tue, nous serons vos serviteurs; mais si j’ai l’avantage sur lui, et que je le tue, vous serez nos serviteurs, et vous nous serez asservis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Et le Philistin disait: J’ai déshonoré aujourd’hui les troupes rangées d’Israël, en leur disant: Donnez-moi un homme, et nous combattrons ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Mais Saül et tous les Israëlites ayant entendu les paroles du Philistin, furent étonnés, et eurent une grande peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'Or il y avait David, fils d’un homme Ephratien de Bethléhem de Juda, nommé Isaï, qui avait huit fils; il était vieux, et il était mis au rang des personnes de qualité du temps de Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Et les trois plus grands fils d’Isaï s’en étaient allés, et avaient suivi Saül en cette guerre. Les noms de ses trois fils qui s’en étaient allés à la guerre, étaient Eliab, le premier-né; Abinadab, le second; et Samma, le troisième.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'Et David était le plus jeune, et les trois plus grands suivaient Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Et David allait et revenait d’auprès de Saül, pour paître les brebis de son père en Bethléhem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Et le Philistin s’approchant le matin et le soir, se présenta quarante jours durant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Et Isaï dit à David son fils: Prends maintenant pour tes frères un Epha de ce froment rôti, et ces dix pains, et porte les en diligence au camp à tes frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Tu porteras aussi ces dix fromages de lait au capitaine de leur millier, et tu visiteras tes frères pour savoir s’ils se portent bien, et tu m’en apporteras des marques.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Or Saül, et eux, et tous ceux d’Israël étaient en la vallée du chêne, combattant contre les Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'David donc se leva de bon matin, et laissa les brebis en garde au berger, puis ayant pris sa charge, s’en alla, comme son père Isaï le lui avait commandé, et il arriva au lieu où était le camp; et l’armée était sortie là où elle se rangeait en bataille, et on jetait de grands cris à cause de la bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Car les Israëlites et les Philistins avaient rangé armée contre armée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Alors David se déchargea de son bagage, le laissant entre les mains de celui qui gardait le bagage, et courut au lieu où était la bataille rangée, et y étant arrivé, il demanda à ses frères s’ils se portaient bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Et comme il parlait avec eux, voici monter cet homme qui se présentait entre les deux armées, lequel avait nom Goliath, Philistin de la ville de Gath, qui s’avançant hors de l’armée des Philistins proféra les mêmes paroles qu’il avait proférées auparavant, et David les entendit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Et tous ceux d’Israël voyant cet homme-là, s’enfuyaient de devant lui, et avaient une grande peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Et chacun d’Israël disait: N’avez-vous point vu cet homme-là qui est monté? Il est monté pour déshonorer Israël; et s’il se trouve quelqu’un qui le frappe, le Roi le comblera de richesses, et lui donnera sa fille, et affranchira la maison de son père de toutes charges en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Alors David parla aux gens qui étaient là avec lui, en disant: Quel bien fera-t-on à l’homme qui aura frappé ce Philistin, et qui aura ôté l’opprobre de dessus Israël? Car qui est ce Philistin, cet incirconcis, pour déshonorer ainsi les batailles rangées du Dieu vivant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Et le peuple lui répéta ces mêmes paroles-là; et lui dit: C’est là le bien qu’on fera à l’homme qui l’aura frappé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Et quand Eliab son frère aîné eut entendu qu’il parlait à ces gens-là, sa colère s’enflamma contre David, et il lui dit: Pourquoi es-tu descendu? et à qui as-tu laissé ce peu de brebis au désert? Je connais ton orgueil, et la malignité de ton cœur, car tu es descendu pour voir la bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'Et David répondit: Qu’ai-je fait maintenant? N’y a-t-il pas de quoi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Puis il se détourna de celui-là vers un autre, et lui dit les mêmes paroles; et le peuple lui répondit de la même manière comme la première fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Et les paroles que David avait dites ayant été entendues, furent rapportées devant Saül; et il le fit venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Et David dit à Saül: Que le coeur ne défaille à personne à cause de celui-là; ton serviteur ira, et combattra contre ce Philistin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Mais Saül dit à David: Tu ne saurais aller contre ce Philistin pour combattre contre lui; car tu n’es qu’un jeune garçon, et lui, il est homme de guerre dès sa jeunesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Et David répondit à Saül: Ton serviteur paissait les brebis de son père; et un lion vint, et un ours, et ils emportaient une brebis du troupeau:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'Mais je sortis après eux, je les frappai, et j’arrachai la brebis de leur gueule; et comme ils se levaient contre moi, je les pris par la mâchoire, je les frappai, et je les tuai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Ton serviteur donc a tué et un lion, et un ours; et ce Philistin, cet incirconcis, sera comme l’un d’eux; car il a déshonoré les troupes rangées du Dieu vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'David dit encore: L’Eternel qui m’a délivré de la griffe du lion, et de la patte de l’ours, lui-même me délivrera de la main de ce Philistin. Alors Saül dit à David: Va, et l’Eternel soit avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Et Saül fit armer David de ses armes, et lui mit son casque d’airain sur sa tête, et le fit armer d’une cuirasse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Puis David ceignit l’épée de Saül sur ses armes, et se mit à marcher; car jamais il ne l’avait essayé. Et David dit à Saül: Je ne saurais marcher avec ces armes; car je ne l’ai jamais essayé. Et David les ôta de dessus soi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Mais il prit son bâton en sa main, et se choisit du torrent cinq cailloux bien unis, et les mit dans sa mallette de berger qu’il avait, et dans sa poche, et il avait sa fronde en sa main; et il s’approcha du Philistin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Le Philistin aussi s’en vint, et s’avança, et s’approcha de David, et l’homme qui portait son bouclier marchait devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Et le Philistin regarda, et vit David, et le méprisa; car ce n’était qu’un jeune garçon, blond, et beau de visage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Et le Philistin dit à David: Suis- je un chien, que tu viennes contre moi avec des bâtons? et le Philistin maudit David par ses dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Le Philistin dit encore à David: Viens vers moi, et je donnerai ta chair aux oiseaux du ciel, et aux bêtes des champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Et David dit au Philistin: Tu viens contre moi avec l’épée, la hallebarde, et l’écu; mais moi, je viens contre toi au nom de l’Eternel des armées, du Dieu des batailles rangées d’Israël, lequel tu as déshonoré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Aujourd’hui l’Eternel te livrera entre mes mains, je te frapperai, je t’ôterai la tête de dessus toi, et je donnerai aujourd’hui les charognes du camp des Philistins aux oiseaux des cieux, et aux animaux de la terre; et toute la terre saura qu’Israël a un Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'Et toute cette assemblée saura que l’Eternel ne délivre point par l’épée ni par la hallebarde; car cette bataille est à l’Eternel, qui vous livrera entre nos mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Et il arriva que comme le Philistin se fut levé, et qu’il s’approchait pour rencontrer David, David se hâta, et courut au lieu du combat pour rencontrer le Philistin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'Alors David mit la main à sa mallette, et en prit une pierre, la jeta avec sa fronde, et il en frappa le Philistin au front, tellement que la pierre s’enfonça dans son front; et il tomba le visage contre terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Ainsi David avec une fronde et une pierre fut plus fort que le Philistin, et frappa le Philistin, et le tua; or David n’avait point d’épée en sa main,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Mais David courut, se jeta sur le Philistin, prit son épée, la tira de son fourreau, le tua, et lui coupa la tête. Et les Philistins ayant vu que leur homme fort était mort, s’enfuirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Alors ceux d’Israël et de Juda se levèrent, et jetèrent des cris de joie, et poursuivirent les Philistins, jusqu’à la vallée, et jusqu’aux portes de Hékron; et les Philistins blessés à mort tombèrent par le chemin de Saharajim, jusqu’à Gath, et jusqu’à Hékron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Et les enfants d’Israël s’en retournèrent de la poursuite des Philistins, et pillèrent leurs camps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Et David prit la tête du Philistin, laquelle il porta depuis à Jérusalem; il mit aussi dans sa tente les armes du Philistin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Or comme Saül vit David sortant pour rencontrer le Philistin, il dit à Abner Chef de l’armée: Abner, de qui est fils ce jeune garçon? Et Abner répondit: Comme ton âme vit, ô Roi! je n’en sais rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Le Roi lui dit: Enquiers-toi de qui est fils ce jeune garçon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Sitôt donc que David fut revenu de tuer le Philistin, Abner le prit, et le mena devant Saül, ayant la tête du Philistin en sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Et Saül lui dit: Jeune garçon, de qui es-tu fils? David répondit: Je suis fils d’Isaï Bethléhémite, ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Or il arriva qu’aussitôt que David eut achevé de parler à Saül, l’âme de Jonathan fut liée à l’âme de David, tellement que Jonathan l’aima comme son âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Ce jour-là donc Saül le prit, et ne lui permit plus de retourner en la maison de son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Et Jonathan fit alliance avec David, parce qu’il l’aimait comme son âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Et Jonathan se dépouilla du manteau qu’il portait, et le donna à David, avec ses vêtements, même jusqu’à son épée, son arc, et son baudrier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Et David était employé aux affaires; et partout où Saül l’envoyait, il réussissait; de sorte que Saül l’établit sur des gens de guerre, et il fut agréable à tout le peuple, et même aux serviteurs de Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Or il arriva que comme ils revenaient, et que David retournait de la défaite du Philistin, il sortit des femmes de toutes les villes d’Israël, en chantant et dansant au devant du Roi Saül, avec des tambours, avec joie, et avec des cymbales.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Et les femmes qui jouaient des instruments s’entre répondaient, et disaient: Saül a frappé ses mille, et David ses dix mille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Et Saül fut fort irrité, et cette parole lui déplut, et il dit: Elles en ont donné dix mille à David, et à moi, mille; il ne lui manque donc plus que le Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Depuis ce jour-là Saül avait l’oeil sur David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Et il arriva, dès le lendemain que l’esprit malin envoyé de Dieu saisit Saül, et il faisait le Prophète au milieu de la maison, et David joua de sa main, comme les autres jours, et Saül avait une hallebarde en sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Et Saül lança la hallebarde, disant en soi-même: Je frapperai David, et la muraille; mais David se détourna de devant lui par deux fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Saül donc avait peur de la présence de David, parce que l’Eternel était avec David, et qu’il s’était rétiré d’avec Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'C’est pourquoi Saül éloigna David de lui, et l’établit capitaine de mille hommes; et David allait et venait devant le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'Et David réussissait en tout ce qu’il entreprenait, car l’Eternel était avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Saül donc voyant que David prospérait beaucoup, le craignit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Mais tout Israël et Juda aimaient David, parce qu’il allait et venait devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Et Saül dit à David: Voici, je te donnerai Mérab ma fille aînée pour femme; sois-moi seulement un fils vertueux, et conduis les batailles de l’Eternel; car Saül disait: Que ma main ne soit point sur lui, mais que la main des Philistins soit sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Et David répondit à Saül: Qui suis-je, et quelle est ma vie, et la famille de mon père en Israël, que je sois gendre du Roi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Or il arriva qu’au temps qu’on devait donner Mérab fille de Saül à David, on la donna pour femme à Hadrièl Méholathite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Mais Mical l’autre fille de Saül aima David; ce qu’on rapporta à Saül, et la chose lui plut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Et Saül dit: Je la lui donnerai afin qu’elle lui soit en piège, et que par ce moyen la main des Philistins soit sur lui. Saül donc dit à David: Tu seras aujourd’hui mon gendre par l’une de mes deux filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Et Saül commanda à ses serviteurs de parler à David en secret, et de lui dire: Voici, le Roi prend plaisir en toi, et tous ses serviteurs t’aiment; sois donc maintenant gendre du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Les serviteurs donc de Saül redirent toutes ces paroles à David, et David dit: Pensez-vous que ce soit peu de chose d’être gendre du Roi, vu que je suis un pauvre homme, et de nulle estime?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Et les serviteurs de Saül lui rapportèrent cela, et lui dirent: David a tenu de tels discours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Et Saül dit: Vous parlerez ainsi à David: Le Roi ne demande d’autre douaire, que cent prépuces de Philistins, afin que le Roi soit vengé de ses ennemis. Or Saül avait dessein de faire tomber David entre les mains des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Et les serviteurs de Saül rapportèrent tous ces discours à David; et la chose lui plut, pour être gendre du Roi. Et avant que les jours fussent accomplis,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'David se leva, et s’en alla, lui et ses gens, et frappa deux cents hommes des Philistins; et David apporta leurs prépuces, et on les livra bien comptés au Roi, afin qu’il fût gendre du Roi. Et Saül lui donna pour femme Mical sa fille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Alors Saül aperçut et connut que l’Eternel était avec David; et Mical fille de Saül l’aimait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Et Saül continua de craindre David, encore plus qu’auparavant, tellement que Saül fut toujours ennemi de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Or les capitaines des Philistins sortirent en campagne, et dès qu’ils furent sortis, David réussit mieux que tous les serviteurs de Saül; et son nom fut en fort grande estime.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Et Saül parla à Jonathan son fils et à tous ses serviteurs de faire mourir David; mais Jonathan fils de Saül était fort affectionné à David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'C’est pourquoi Jonathan le fit savoir à David, et lui dit: Saül mon père cherche de te faire mourir; maintenant donc tiens-toi sur tes gardes, je te prie, jusqu’au matin, et demeure en quelque lieu secret, et te cache.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Et quand je me serai tenu auprès de mon père, je sortirai au champ où tu seras; car je parlerai de toi à mon père; et je verrai ce qu’il en sera, et te le ferai savoir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Jonathan donc parla favorablement de David à Saül son père, et lui dit: Que le Roi ne pèche point contre son serviteur David, car il n’a point péché contre toi; et même ce qu’il a fait t’est fort avantageux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Car il a exposé sa vie, et a frappé le Philistin, et l’Eternel a donné une grande délivrance à tout Israël, tu l’as vu, et tu t’en es réjoui; pourquoi donc pécherais-tu contre le sang innocent, en faisant mourir David sans cause?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Et Saül prêta l’oreille à la voix de Jonathan et jura: L’Eternel et vivant, si on le fait mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Alors Jonathan appela David, et lui récita toutes ces choses. Et Jonathan amena David à Saül, et il fut à son service comme auparavant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Et la guerre recommença, et David sortit et combattit contre les Philistins, et en fit un grand carnage, de sorte qu’ils s’enfuirent de devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Or l’esprit malin envoyé de l’Eternel fut sur Saül, comme il était assis dans sa maison, ayant sa hallebarde en sa main, et David jouait de sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Et Saül cherchait de frapper David avec la hallebarde jusqu’à la paroi; mais il se glissa de devant Saül, qui frappa la paroi de la hallebarde: et David s’enfuit, et échappa cette nuit-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Mais Saül envoya des messagers en la maison de David, pour le garder, et le faire mourir au matin. Ce que Mical, femme de David lui apprit, en disant: Si tu ne te sauves, demain on te va faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Et Mical fit descendre David par une fenêtre; et ainsi il s’en alla, et s’enfuit, et échappa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Ensuite Mical prit un simulacre, et le mit au lit, et mit à son chevet une hure de poil de chèvre, et le couvrit d’un vêtement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Et quand Saül envoya des gens pour prendre David, elle dit: Il est malade.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Saül envoya encore des gens pour prendre David, en leur disant: Apportez-le-moi dans son lit, afin que je le fasse mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Ces gens donc vinrent, et voici, un simulacre était au lit, et la hure de poil de chèvre à son chevet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Et Saül dit à Mical: Pourquoi m’as-tu ainsi trompé, et as-tu laissé aller mon ennemi, de sorte qu’il est échappé? Et Mical répondit à Saül: Il m’a dit: Laisse-moi aller; pourquoi te tuerais-je?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Ainsi David s’enfuit, et échappa, et s’en vint vers Samuel à Rama, et lui raconta tout ce que Saül lui avait fait. Puis il s’en alla avec Samuel, et ils demeurèrent à Najoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Et on le rapporta à Saül, en lui disant: Voilà, David est à Najoth en Rama.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Alors Saül envoya des gens pour prendre David, lesquels virent une assemblée de Prophètes qui prophétisaient, et Samuel, qui présidait sur eux, se tenait là; et l’esprit de Dieu vint sur les hommes envoyés par Saül, et eux aussi firent les prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Et quand on l’eut rapporté à Saül, il envoya d’autres gens, qui firent aussi les prophètes. Et Saül continua d’envoyer des gens pour la troisième fois, et ils firent aussi les prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Puis lui-même aussi alla à Rama, et vint jusqu’à la grande fosse qui est à Secu, et s’informa disant: Où sont Samuel et David? et on lui répondit: Les voilà à Najoth en Rama.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Et il s’en alla à Najoth en Rama; et l’esprit de Dieu fut aussi sur lui, et continuant son chemin il fit le prophète, jusqu’à ce qu’il fût venu à Najoth en Rama.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Il se dépouilla aussi de ses vêtements, et fit le prophète lui- même en la présence de Samuel; et se jeta par terre nu, tout ce jour-là, et toute la nuit. C’est pourquoi on dit: Saül aussi est- il entre les Prophètes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Et David s’enfuyant de Najoth qui est en Rama, s’en vint, et dit devant Jonathan: Qu’ai-je fait? Quelle est mon iniquité, et quel est mon péché devant ton père, qu’il recherche ma vie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Et Jonathan lui dit: A Dieu ne plaise! tu ne mourras point. Voici, mon père ne fait aucune chose, ni grande, ni petite, qu’il ne me la découvre; et pourquoi mon père me cacherait-il cette chose- là? il n’en est rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Alors David jurant, dit encore: Ton père sait certainement que je suis dans tes bonnes grâces, et il aura dit: que Jonathan ne sache rien de ceci, de peur qu’il n’en soit attristé; mais l’Eternel est vivant, et ton âme vit, qu’il n’y a qu’un pas entre moi et la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Alors Jonathan dit à David: Que désires-tu que je fasse? Et je le ferai pour toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Et David dit à Jonathan: Voici, c’est demain la nouvelle lune, et j’ai accoutumé de m’asseoir auprès du Roi pour manger, laisse-moi donc aller et je me cacherai aux champs, jusqu’au troisième soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Si ton père vient à s’informer de moi, tu lui répondras: On m’a demandé instamment que David allât en diligence à Bethléhem sa ville, parce que toute sa famille fait un sacrifice solennel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'S’il dit ainsi: A la bonne heure; cela va bien pour ton serviteur. Mais s’il se met fort en colère, sache que sa malice est venue à son comble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Use donc de gratuité envers ton serviteur, puisque tu as fait entrer ton serviteur en alliance avec toi, le nom de l’Eternel y étant intervenu; que s’il y a quelque iniquité en moi, fais-moi mourir toi-même; car pourquoi me mènerais-tu à ton père?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Et Jonathan lui dit: A Dieu ne plaise que cela t’arrive; car si je puis connaître en quelque sorte que la malice de mon père soit venue à son comble pour se décharger sur toi, ne te le ferai-je point savoir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Et David répondit à Jonathan: Qui me fera entendre quelle réponse fâcheuse t’aura faite ton père?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Et Jonathan dit à David: Viens et sortons aux champs. Ils sortirent donc eux deux aux champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Alors Jonathan dit à David: Ô Eternel! Dieu d’Israël, quand j’aurai sondé mon père demain, environ cette heure ou après demain, et qu’il y aura du bien pour David, si alors je n’envoie vers toi, et si je ne te le découvre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Que l’Eternel fasse ainsi à Jonathan, et ainsi y ajoute; que si mon père a résolu de te faire du mal, je te le ferai savoir, et je te laisserai aller, et tu t’en iras en paix, et l’Eternel sera avec toi comme il a été avec mon père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Mais n’est-il pas ainsi, que si je suis encore vivant, n’est-il pas, dis-je ainsi, que tu useras envers moi de la gratuité de l’Eternel, en sorte que je ne meure point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Et que tu ne retireras point ta gratuité de ma maison à jamais, non pas même quand l’Eternel retranchera tous les ennemis de David de dessus la terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Et Jonathan traita alliance avec la maison de David, en disant: Que l’Eternel le redemande de la main des ennemis de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Jonathan fit encore jurer David par l’amour qu’il lui portait; car il l’aimait autant que son âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Puis Jonathan lui dit: C’est demain la nouvelle lune, et on s’informera de toi; car ta place sera vide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Or ayant attendu jusqu’au troisième soir, tu descendras en diligence, et tu viendras au lieu où tu t’étais caché le jour de cette affaire, et tu demeureras auprès de la pierre d’Ezel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Et je tirerai trois flèches à côté de cette pierre, comme si je tirais à quelque but.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Et voici, j’enverrai un garçon, et je lui dirai: Va, trouve les flèches. Et si je dis au garçon en termes exprès: Voilà, les flèches sont au deçà de toi, prends-les, et t’en viens; alors il va bien pour toi; et il n’y aura rien; l’Eternel est vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Mais si je dis ainsi au jeune garçon: Voilà, les flèches sont au delà de toi; va-t’en, car l’Eternel te renvoie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Et quant à la parole que nous nous sommes donnée toi et moi; voici, l’Eternel est entre moi et toi à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'David donc se cacha au champ; et la nouvelle lune étant venue, le Roi s’assit pour prendre son repas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Et le Roi s’étant assis en son siège, comme les autres fois, au siège qui était près de la paroi, Jonathan se leva, et Abner s’assit à côté de Saül; mais la place de David était vide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Et Saül n’en dit rien ce jour-là, car il disait en soi-même: Il lui est arrivé quelque chose; il n’est point net, certainement il n’est point net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Mais le lendemain de la nouvelle lune, qui était le second jour du mois, la place de David fut encore vide; et Saül dit à Jonathan son fils: Pourquoi le fils d’Isaï n’a-t-il été ni hier ni aujourd’hui au repas?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Et Jonathan répondit à Saül: On m’a instamment prié que David allât jusqu’à Bethléhem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'Même il m’a dit: Je te prie, laisse-moi aller; car notre famille fait un sacrifice en la ville, et mon frère m’a commandé de m’y trouver; maintenant donc si je suis dans tes bonnes grâces, je te prie que j’y aille, afin que je voie mes frères. C’est pour cela qu’il n’est point venu à la table du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Alors la colère de Saül s’enflamma contre Jonathan, et il lui dit: Fils de la méchante rebelle, ne sais-je pas bien que tu as choisi le fils d’Isaï à ta honte; et à la honte de la turpitude de ta mère?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Car tout le temps que le fils d’Isaï vivra sur la terre tu ne seras point établi, ni toi, ni ton Royaume; c’est pourquoi envoie sur l’heure, et amène-le moi, car il est digne de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Et Jonathan répondit à Saül son père, et lui dit: Pourquoi le ferait-on mourir? qu’a-t-il fait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Et Saül lança une hallebarde contre lui pour le frapper. Alors Jonathan connut que son père avait conclu de faire mourir David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Et Jonathan se leva de table tout en colère, et ne prit point son repas le second jour de la nouvelle lune; car il était affligé à cause de David, parce que son père l’avait déshonoré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Et le lendemain matin Jonathan sortit aux champs, selon l’assignation qu’il avait donnée à David, et il amena avec lui un petit garçon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Et il dit à son garçon: Cours, trouve maintenant les flèches que je m’en vais tirer. Et le garçon courut, et Jonathan tira une flèche au delà de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Et le garçon étant venu jusqu’au lieu où était la flèche que Jonathan avait tirée, Jonathan cria après lui, et lui dit: La flèche n’ est- elle pas au delà de toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Et Jonathan criait après le garçon: Hâte-toi, ne t’arrête point; et le garçon amassa les flèches, et vint à son Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Mais le garçon ne savait rien de cette affaire; il n’y avait que David et Jonathan qui le sussent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Et Jonathan donna son arc et ses flèches au garçon qu’il avait, et lui dit: Va, porte-les dans la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Et le garçon s’en étant allé, David se leva du côté du Midi, et se jeta le visage contre terre, et se prosterna par trois fois, et ils se baisèrent l’un l’autre, et pleurèrent tous deux; jusques-là que David pleura extraordinairement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Et Jonathan dit à David: Va-t’en en paix; selon que nous avons juré tous deux au Nom de l’Eternel, en disant: L’Eternel soit entre moi et toi, et entre ma postérité et ta postérité à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 43, 'David donc se leva, et s’en alla; et Jonathan rentra dans la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'David donc s’en alla à Nob, vers Ahimélec le Sacrificateur; et Ahimélec tout effrayé courut au devant de David, et lui dit: D’où vient que tu es seul, et qu’il n’y a personne avec toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'Et David dit à Ahimélec le Sacrificateur: Le Roi m’a commandé quelque chose, et m’a dit: Que personne ne sache rien de l’affaire pour laquelle je t’envoie, ni de ce que je t’ai commandé; et j’ai assigné à mes gens un certain lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Maintenant donc qu’as-tu en main? donne-moi cinq pains, ou ce qui se trouvera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Et le Sacrificateur répondit à David, et dit: Je n’ai point en main de pain commun, mais du pain sacré; mais tes gens se sont-ils au moins gardés des femmes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Et David répondit au Sacrificateur, et lui dit: Qui plus est, depuis que je suis parti, il y a déjà quatre jours, les femmes ont été éloignées de nous, et les vaisseaux de mes gens ont été saints, et ce pain est tenu pour commun, vu qu’aujourd’hui on en consacre de nouveau pour le mettre dans les vaisseaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Le Sacrificateur donc lui donna le pain sacré; car il n’y avait point là d’autre pain que les pains de proposition qui avaient été ôtés de devant l’Eternel, pour remettre du pain chaud le jour qu’on avait levé l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Or il y avait là un homme d’entre les serviteurs de Saül, retenu en ce jour-là devant l’Eternel; cet homme avait nom Doëg, Iduméen le plus puissant de tous les pasteurs de Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Et David dit à Ahimélec: Mais n’as-tu point ici en main quelque hallebarde, ou quelque épée? car je n ai point pris mon épée ni mes armes sur moi, parce que l’affaire du Roi était pressée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Et le Sacrificateur dit: Voici l’épée de Goliath le Philistin, que tu tuas en la vallée du chêne, elle est enveloppée d’un drap, derrière l’Ephod; si tu la veux prendre pour toi, prends-la; car il n’y en a point ici d’autre que celle-là. Et David dit: Il n’y en a point de pareille; donne-la-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Alors David se leva, et s’enfuit ce jour-là de devant Saül, et s’en alla vers Akis, Roi de Gath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Et les serviteurs d’Akis lui dirent: N’est-ce pas ici ce David, qui est comme le Roi du pays? n’est-ce pas celui duquel on s’entrerépondait aux danses, en disant: Saül en a tué ses mille, et David ses dix mille?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Et David mit ces paroles en son coeur, et eut une fort grande peur à cause d’Akis, Roi de Gath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Et il changea sa contenance devant eux, et contrefit le fou entre leurs mains; et il marquait les poteaux des portes, et faisait couler sa salive sur sa barbe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Et Akis dit à ses serviteurs: Voici, ne voyez-vous pas que c’est un homme insensé? pourquoi me l’avez-vous amené?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Manqué-je d’hommes insensés, que vous m’ayez amené celui-ci pour faire l’insensé devant moi? celui-ci entrerait-il en ma maison!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Or David partit de là, et se sauva dans la caverne d’Hadullam; ce que ses frères et toute la maison de son père ayant appris, ils descendirent là vers lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Tous ceux aussi qui étaient mal dans leurs affaires, et qui avaient des créanciers dont ils étaient tourmentés, et qui avaient le coeur plein d’amertume, s’assemblèrent vers lui, et il fut leur chef; et il y eut avec lui environ quatre cents hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Et David s’en alla de là à Mitspé de Moab; et il dit au Roi de Moab: Je te prie que mon père et ma mère se retirent vers vous jusqu’à ce que je sache ce que Dieu fera de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Et il les amena devant le Roi de Moab, et ils demeurèrent avec lui, tout le temps que David fut dans cette forteresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Or Gad le prophète dit à David: Ne demeure point dans cette forteresse, mais va-t’en, et entre dans le pays de Juda. David donc s’en alla, et vint en la forêt de Hérets.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Et Saül apprit qu’on avait découvert David et les gens qui étaient avec lui. Or Saül était assis au coteau sous un chêne à Rama, ayant sa hallebarde en sa main, et tous ses serviteurs se tenaient devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Et Saül dit à ses serviteurs qui se tenaient devant lui: Ecoutez maintenant, Benjamites: Le fils d’Isaï vous donnera-t-il à vous tous des champs et des vignes? Vous établira-t-il tous gouverneurs sur milliers, et sur centaines?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Que vous ayez tous conspiré contre moi, et qu’il n’y ait personne qui m’avertisse que mon fils a fait alliance avec le fils d’Isaï, et qu’il n’y ait aucun de vous qui ait pitié de moi, et qui m’avertisse; car mon fils a suscité mon serviteur contre moi pour me dresser des embûches, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Alors Doëg Iduméen, qui était établi sur les serviteurs de Saül, répondit, et dit: J’ai vu le fils d’Isaï venir à Nob vers Ahimélec fils d’Ahitub;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Qui a consulté l’Eternel pour lui, et lui a donné des vivres, et l’épée de Goliath le Philistin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Alors le Roi envoya appeler Ahimélec le Sacrificateur fils d’Ahitub, et toute la famille de son père, savoir les Sacrificateurs qui étaient à Nob; et ils vinrent tous vers le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Et Saül dit: Ecoute maintenant, fils d’Ahitub; et il répondit: Me voici, mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Alors Saül lui dit: Pourquoi avez-vous conspiré contre moi, toi et le fils d’Isaï, vu que tu lui as donné du pain, et une épée, et que tu as consulté Dieu pour lui, afin qu’il s’élevât contre moi pour me dresser des embûches, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Et Ahimélec répondit au Roi, et dit: Entre tous tes serviteurs y en a-t-il un comme David, qui est fidèle, et gendre du Roi, et qui est parti par ton commandement, et qui est si honoré en ta maison?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Ai-je commencé aujourd’hui à consulter Dieu pour lui? A Dieu ne plaise! Que le Roi ne charge donc d’aucune chose son serviteur, ni toute la maison de mon père; car ton serviteur ne sait chose ni petite ni grande de tout ceci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Et le Roi lui dit: Certainement tu mourras, Ahimélec, et toute la famille de ton père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Alors le Roi dit aux archers qui se tenaient devant lui: Tournez- vous, et faites mourir les Sacrificateurs de l’Eternel; car ils sont aussi de la faction de David parce qu’ils ont bien su qu’il s’enfuyait, et qu’ils ne m’en ont point averti. Mais les serviteurs du Roi ne voulurent point étendre leurs mains, pour se jeter sur les Sacrificateurs de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Alors le Roi dit à Doëg: Tourne-toi, et te jette sur les Sacrificateurs; et Doëg Iduméen se tourna, et se jeta sur les Sacrificateurs; et il tua en ce jour-là quatre vingt cinq hommes qui portaient l’Ephod de lin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Et il fit passer Nob, ville des Sacrificateurs, au fil de l’épée, les hommes et les femmes, les grands et ceux qui tètent, même il fit passer les boeufs, les ânes, et le menu bétail au fil de l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Toutefois un des fils d’Ahimélec, fils d’Ahitub, qui avait nom Abiathar, se sauva, et s’enfuit auprès de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Et Abiathar rapporta à David, que Saül avait tué les Sacrificateurs de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Et David dit à Abiathar: Je connus bien en ce jour-là, puisque Doëg Iduméen était là, qu’il ne manquerait pas de le rapporter à Saül; je suis cause de ce qui est arrivé à toutes les personnes de la famille de ton père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Demeure avec moi, ne crains point; car celui qui cherche ma vie, cherche la tienne; certainement tu seras gardé avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Or on avait fait ce rapport à David, en disant: Voilà, les Philistins font la guerre à Kéhila, et pillent les aires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Et David consulta l’Eternel en disant: Irai-je, et frapperai-je ces Philistins-là? et l’Eternel répondit à David: Va, et tu frapperas les Philistins, et tu délivreras Kéhila.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Et les gens de David lui dirent: Voici, nous étant ici en Juda avons peur; que sera-ce donc quand nous serons allés à Kéhila contre les troupes rangées des Philistins?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'C’est pourquoi David consulta encore l’Eternel, et l’Eternel lui répondit, et dit: Lève-toi, descends à Kéhila, car je m’en vais livrer les Philistins entre tes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Alors David s’en alla avec ses gens à Kéhila, et combattit contre les Philistins, et emmena leur bétail, et fit un grand carnage des Philistins; ainsi David délivra les habitants de Kéhila.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Or il était arrivé que quand Abiathar fils d’Ahimélec s’était enfui vers David à Kéhila, l’Ephod lui était tombé entre les mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Et on rapporta à Saül que David était venu à Kéhila; et Saül dit: Dieu l’a livré entre mes mains; car il s’est enfermé en entrant dans une ville qui a des portes et des barres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Et Saül assembla à cri public tout le peuple pour aller à la guerre, et descendre à Kéhila, afin d’assiéger David et ses gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Mais David ayant su que Saül lui machinait ce mal, dit au Sacrificateur Abiathar: Mets l’Ephod.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Puis David dit: Ô Eternel! Dieu d’Israël! ton serviteur a appris comme une chose certaine, que Saül cherche d’entrer dans Kéhila, pour détruire la ville à cause de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Les Seigneurs de Kéhila me livreront-ils entre ses mains? Saül descendra-t-il, comme ton serviteur l’a ouï dire? Ô Eternel! Dieu d’Israël! je te prie, enseigne-le à ton serviteur. Et l’Eternel répondit: Il descendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'David dit encore: Les Seigneurs de Kéhila me livreront-ils, moi et mes gens, entre les mains de Saül? Et l’Eternel répondit: Ils t’y livreront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Alors David se leva, et environ six cents hommes avec lui, et ils sortirent de Kéhila, et s’en allèrent où ils purent; et on rapporta à Saül que David s’était sauvé de Kéhila: c’est pourquoi il cessa de marcher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Et David demeura au désert dans des lieux forts, et il se tint en une montagne au désert de Ziph. Et Saül le cherchait tous les jours, mais Dieu ne le livra point entre ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'David donc ayant vu que Saül était sorti pour chercher sa vie, se tint au désert de Ziph en la forêt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Alors Jonathan fils de Saül se leva, et s’en alla en la forêt vers David, et fortifia ses mains en Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Et lui dit: Ne crains point; car Saül mon père ne t’attrapera point, mais tu régneras sur Israël, et moi je serai le second après toi; et même Saül mon père le sait bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Ils traitèrent donc eux deux alliance devant l’Eternel; et David demeura dans la forêt, mais Jonathan retourna en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Or les Ziphiens montèrent vers Saül à Guibha, et lui dirent: David ne se tient-il pas caché parmi nous, dans des lieux forts, dans la forêt, au coteau de Hakila, qui est à main droite de Jésimon?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Maintenant donc, ô Roi! si tu souhaites de descendre, descends, et ce sera à nous à le livrer entre les mains du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Et Saül dit: Bénis soyez-vous de par l’Eternel, de ce que vous avez eu pitié de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Allez donc, je vous prie, et préparez toutes choses, et sachez, et reconnaissez le lieu, où il fait sa retraite, et qui l’aura vu là; car on m’a dit, qu’il est fort rusé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Reconnaissez donc et sachez dans laquelle de toutes ces retraites il se tient caché, puis retournez vers moi quand vous en serez assurés, et j’irai avec vous; et s’il est au pays, je le chercherai soigneusement parmi tous les milliers de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Ils se levèrent donc et s’en allèrent à Ziph devant Saül; mais David et ses gens étaient au désert de Mahon, en la campagne, à main droite de Jésimon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Ainsi Saül et ses gens s’en allèrent le chercher; et on le rapporta à David: et il descendit dans la roche, et demeura au désert de Mahon: ce que Saül ayant appris, il poursuivit David au désert de Mahon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Et Saül allait de deçà le côté de la montagne, et David et ses gens allaient de delà, à l’autre côté de la montagne; et David se hâtait autant qu’il pouvait de s’en aller de devant Saül, mais Saül et ses gens environnèrent David et ses gens pour les prendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Sur cela un messager vint à Saül, en disant: Hâte-toi, et viens, car les Philistins se sont jetés sur le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Ainsi Saül s’en retourna de la poursuite de David, et s’en alla au devant des Philistins: c’est pourquoi on a appelé ce lieu-là Sélah- hammahlekoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'Puis David monta de là, et demeura dans les lieux forts de Hen- guédi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Et quand Saül fut revenu de la poursuite des Philistins, on lui fit ce rapport, disant: Voilà David au désert de Hen-guédi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Alors Saül prit trois mille hommes d’élite de tout Israël, et il s’en alla chercher David et ses gens, jusques sur le haut des rochers des chamois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Et Saül vint aux parcs des brebis auprès du chemin, où il y avait une caverne en laquelle il entra pour ses nécessités; et David et ses gens se tenaient au fond de la caverne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Et les gens de David lui dirent: Voici le jour dont l’Eternel t’a dit: Voici, je te livre ton ennemi entre tes mains, afin que tu lui fasses selon qu’il te semblera bon. Et David se leva, et coupa tout doucement le pan du manteau de Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Après cela David fut touché en son coeur de ce qu’il avait coupé le pan du manteau de Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Et il dit à ses gens: Que l’Eternel me garde de commettre une telle action contre mon Seigneur, l’Oint de l’Eternel, en mettant ma main sur lui; car il est l’Oint de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Ainsi David détourna ses gens par ses paroles, et il ne leur permit point de s’élever contre Saül. Puis Saül se leva de la caverne, et s’en alla son chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Après cela David se leva, et sortit de la caverne, et cria après Saül, en disant: Mon Seigneur le Roi! et Saül regarda derrière lui, et David s’inclina le visage contre terre, et se prosterna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Et David dit à Saül: Pourquoi écouterais-tu les paroles des gens qui disent: Voilà, David cherche ton mal?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Voici, aujourd’hui tes yeux ont vu que l’Eternel t’avait livré aujourd’hui en ma main dans la caverne, et on m’a dit que je te tuasse; mais je t’ai épargné, et j’ai dit: Je ne porterai point ma main sur mon Seigneur; car il est l’Oint de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Regarde donc, mon père, regarde, dis-je, le pan de ton manteau qui est en ma main; car quand je coupais le pan de ton manteau, je ne t’ai point tué. Sache et connais qu’il n’y a point de mal ni d’injustice en ma main; et que je n’ai point péché contre toi; et cependant tu épies ma vie pour me l’ôter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'L’Eternel sera juge entre moi et toi, et l’Eternel me vengera de toi, mais ma main ne sera point sur toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'C’est des méchants que vient la méchanceté, comme dit le proverbe des anciens; c’est pourquoi ma main ne sera point sur toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Après qui est sorti un Roi d’Israël? qui poursuis-tu? un chien mort, une puce?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'L’Eternel donc sera juge, et jugera entre moi et toi; et il regardera et plaidera ma cause, et me garantira de ta main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Or il arriva qu’aussitôt que David eut achevé de dire ces paroles à Saül, Saül dit: N’est-ce pas là ta voix, mon fils David? et Saül éleva sa voix, et pleura.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Et il dit à David: Tu es plus juste que moi; car tu m’as rendu le bien pour le mal que je t’ai fait,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Et tu m’as fait connaître aujourd’hui comment tu as usé de gratuité envers moi, car l’Eternel m’avait livré entre tes mains, et cependant tu ne m’as point tué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Or qui est-ce qui ayant trouvé son ennemi, le laisserait aller sans lui faire du mal? que l’Eternel donc te rende du bien, pour ce que tu m’as fait aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Et maintenant voici, je connais que certainement tu régneras et que le Royaume d’Israël sera ferme entre tes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'C’est pourquoi maintenant jure-moi, par l’Eternel, que tu ne détruiras point ma race après moi, et que tu n’extermineras point mon nom de la maison de mon père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 23, 'Et David le jura à Saül, et Saül s’en alla en sa maison; et David et ses gens montèrent dans le lieu fort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Or Samuel mourut, et tout Israël s’assembla, et le pleura, et on l’ensevelit en sa maison à Rama. Et David se leva, et descendit au désert de Paran.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Or il y avait à Mahon un homme qui avait ses troupeaux en Carmel, et cet homme-là était fort puissant; car il avait trois mille brebis, et mille chèvres; et il était en Carmel quand on tondait ses brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Et cet homme-là avait nom Nabal, et sa femme avait nom Abigaïl, qui était une femme de bon sens, et belle de visage; mais lui, il était un homme grossier, et avec qui il faisait mauvais avoir affaire; et il était de la race de Caleb.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Or David ouït dire dans le désert, que Nabal tondait ses brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Et il envoya dix de ses gens, et leur dit: Montez en Carmel, et allez-vous-en vers Nabal, et saluez-le en mon nom,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'Et lui dites: Autant en puisses-tu faire l’année prochaine en la même saison, et que tu te portes bien, toi, ta maison, et tout ce qui est à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Et maintenant j’ai appris que tu as les tondeurs; or tes bergers ont été avec nous, et nous ne leur avons fait aucune injure, et rien du leur ne s’est perdu pendant tout le temps qu’ils ont été en Carmel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Demande le leur, et ils te le diront; Que ces gens donc soient dans tes bonnes grâces, puisque nous sommes venus en un bon jour. Nous te prions de donner à tes serviteurs, et à David ton fils, ce qui te viendra en main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Les gens donc de David vinrent, et dirent à Nabal au nom de David toutes ces paroles; puis ils se tinrent tranquilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Et Nabal répondit aux serviteurs de David, et dit: Qui est David, et qui est le fils d’Isaï? Aujourd’hui est multiplié le nombre des serviteurs qui se débandent d’avec leurs maîtres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Et prendrais-je mon pain, et mon eau, et la viande que j’ai apprêtée pour mes tondeurs, afin de la donner à des gens que je ne sais d’où ils sont?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Ainsi les gens de David s’en retournèrent par leur chemin. Ils s’en retournèrent donc, et étant venus ils lui firent leur rapport selon toutes ces paroles-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Et David dit à ses gens: Que chacun de vous ceigne son épée; et ils ceignirent chacun leur épée. David aussi ceignit son épée: et il monta avec David environ quatre cents hommes; mais deux cents demeurèrent près du bagage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Or un des serviteurs d’Abigaïl femme de Nabal lui fit rapport, et lui dit: Voici, David a envoyé du désert des messagers pour saluer notre maître, qui les a traités rudement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Et cependant ces hommes-là nous ont été fort bonnes gens, et nous n’en avons reçu aucun outrage, et rien de ce qui est à nous ne s’est perdu, pendant tout le temps que nous avons été avec eux, quand nous étions aux champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Ils nous ont servi de muraille nuit et jour, tout le temps que nous avons été avec eux, paissant les troupeaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'C’est pourquoi maintenant, avise et prends garde à ce que tu auras à faire; car le mal est arrêté contre notre maître, et contre toute sa maison; mais c’est un homme si grossier qu’on n’oserait lui parler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Abigaïl donc se hâta, et prit deux cents pains, et deux outres de vin, et cinq moutons tout prêts, et cinq mesures de grain rôti, et cent paquets de raisins secs, et deux cents cabas de figues sèches, et les mit sur des ânes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Puis elle dit à ses gens: Passez devant moi, voici, je m’en vais après vous; et elle n’en déclara rien à Nabal son mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Et étant montée sur un âne, comme elle descendait à couvert de la montagne, voici David et ses gens descendant la rencontrèrent, et elle se trouva devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Or David avait dit: Certainement c’est en vain que j’ai gardé tout ce que celui-ci avait au désert, en sorte qu’il ne s’est rien perdu de tout ce qui était à lui; car il m’a rendu le mal pour le bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Dieu fasse ainsi aux ennemis de David, et ainsi il y ajoute, si d’ici au matin je laisse rien de tout ce qui appartient à Nabal, depuis l’homme jusqu’à un chien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Quand donc Abigaïl eut aperçu David, elle se hâta de descendre de dessus son âne, et se jeta sur son visage devant David, et se prosterna en terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'Elle se jeta donc à ses pieds et lui dit: Que l’iniquité soit sur moi, sur moi, mon Seigneur; et je te prie que ta servante parle devant toi, et écoute les paroles de ta servante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Je te supplie que mon Seigneur ne prenne point garde à cet homme de néant, à Nabal, car il est tel que son nom; il a nom Nabal, et il y a de la folie en lui; et moi, ta servante, je n’ai point vu les gens que mon Seigneur a envoyés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Maintenant donc, mon Seigneur, aussi vrai que l’Eternel est vivant, et que ton âme vit, l’Eternel t’a empêché d’en venir au sang, et il en a préservé ta main. Or que tes ennemis, et ceux qui cherchent de nuire à mon Seigneur, soient comme Nabal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Mais maintenant voici un présent que ta servante a apporté à mon Seigneur, afin qu’on le donne aux gens qui sont à la suite de mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Pardonne, je te prie, le crime de ta servante; vu que l’Eternel ne manquera point d’établir une maison ferme à mon Seigneur; car mon Seigneur conduit les batailles de l’Eternel, et il ne s’est trouvé en toi aucun mal pendant toute ta vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Que si les hommes se lèvent pour te persécuter, et pour chercher ton âme, l’âme de mon Seigneur sera liée dans le faisseau de la vie par devers l’Eternel ton Dieu; mais il jettera au loin, comme avec une fronde, l’âme de tes ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Et il arrivera que l’Eternel fera à mon Seigneur selon tout le bien qu’il t’a prédit, et il t’établira Conducteur d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'Que ceci donc ne soit point en obstacle, ni un sujet de regret dans l’âme de mon Seigneur, d’avoir répandu du sang sans cause, et de s’être vengé lui-même; et quand l’Eternel aura fait du bien à mon Seigneur, tu te souviendras de ta servante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Alors David dit à Abigaïl: Béni soit l’Eternel le Dieu d’Israël, qui t’a aujourd’hui envoyée au devant de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Et béni soit ton conseil, et bénie sois-tu qui m’as aujourd’hui empêché d’en venir au sang, et qui en as préservé ma main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Car certainement l’Eternel le Dieu d’Israël qui m’a empêché de te faire du mal, est vivant, que si tu ne te fusses hâtée, et ne fusses venue au devant de moi, il ne fût rien demeuré de reste à Nabal d’ici au matin, soit homme soit bête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'David donc prit de sa main ce qu’elle lui avait apporté, et lui dit: Remonte en paix dans ta maison; regarde, j’ai écouté ta voix, et je t’ai accordé ta demande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Puis Abigaïl revint vers Nabal; et voici, il faisait un festin en sa maison, comme un festin de Roi; et Nabal avait le coeur joyeux, et était entièrement ivre; c’est pourquoi elle ne lui dit aucune chose ni petite ni grande de cette affaire, jusqu’au matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Il arriva donc au matin, après que Nabal fut désenivré, que sa femme lui déclara toutes ces choses, et son coeur s’amortit en lui, de sorte qu’il devint comme une pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Or il arriva qu’environ dix jours après l’Eternel frappa Nabal, et il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Et quand David eut appris que Nabal était mort, il dit: Béni soit l’Eternel qui m’a vengé de l’outrage que j’avais reçu de la main de Nabal, et qui a préservé son serviteur de faire du mal, et a fait retomber le mal de Nabal sur sa tête. Puis David envoya des gens pour parler à Abigaïl, afin de la prendre pour sa femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Les serviteurs donc de David vinrent vers Abigaïl en Carmel, et lui parlèrent, en disant: David nous a envoyés vers toi, afin de te prendre pour sa femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Alors elle se leva, et se prosterna le visage contre terre, et dit: voici, ta servante sera pour servante à laver les pieds des serviteurs de mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Puis Abigaïl se leva promptement et monta sur un âne, et cinq de ses servantes la suivaient; et elle s’en alla après les messagers de David, et fut sa femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Or David avait pris aussi Ahinoham de Jizréhel, et toutes deux ensemble furent ses femmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Car Saül avait donné Mical sa fille femme de David, à Palti, fils de Laïs, qui était de Gallim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Les Ziphiens, vinrent encore vers Saül à Guibha, en disant: David ne se tient-il pas caché au coteau de Hakila, qui est vis-a-vis de Jésimon?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Et Saül se leva, et descendit au désert de Ziph, ayant avec lui trois mille hommes d’élite d’Israël, pour chercher David au désert de Ziph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Et Saül se campa au coteau de Hakila, qui est vis-à-vis de Jésimon, près du chemin. Or David se tenait au désert, et il aperçut venir Saül au désert pour le poursuivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Et il envoya des espions par lesquels il sut très-certainement que Saül était venu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Alors David se leva, et vint au lieu où Saul s’était campé; et David vit le lieu où Saül était couché, et Abner aussi, fils de Ner, chef de son armée; or Saül était couché dans le rond du camp, et le peuple était campé autour de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Et David s’en entretint et en parla à Ahimélec, Héthien, et à Abisaï fils de Tseruja, et frère de Joab, en disant: Qui descendra avec moi vers Saül au camp? Et Abisaï répondit: J’y descendrai avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'David donc et Abisaï vinrent de nuit vers le peuple, et voici, Saül dormait étant couché dans le rond du camp, et sa hallebarde était fichée en terre à son chevet; et Abner, et le peuple étaient couchés autour de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Alors Abisaï dit à David: Aujourd’hui Dieu a livré ton ennemi entre tes mains; maintenant donc que je le frappe, je te prie, de la hallebarde, jusqu’en terre d’un seul coup, et je n’y retournerai pas une seconde fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Et David dit à Abisaï: Ne le mets point à mort; car qui est-ce qui mettra sa main sur l’Oint de l’Eternel, et sera innocent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'David dit encore: L’Eternel est vivant, si ce n’est que l’Eternel le frappe, ou que son jour vienne, ou qu’il descende dans une bataille, et qu’il y demeure;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Que l’Eternel me garde de mettre ma main sur l’Oint de l’Eternel; mais je te prie, prends maintenant la hallebarde qui est à son chevet, et le pot à eau, et allons-nous-en.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'David donc prit la hallebarde et le pot à eau qui étaient au chevet de Saül, puis ils s’en allèrent; et il n’y eut personne qui les vît, ni qui les aperçût, ni qui s’éveillât; car ils dormaient tous; à cause que l’Eternel avait fait tomber sur eux un profond sommeil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Et David passa de l’autre côté, et s’arrêta sur le haut de la montagne, loin de là; car il y avait une grande distance entr’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Et il cria au peuple, et à Abner fils de Ner, en disant: Ne répondras-tu pas, Abner? Et Abner répondit, et dit: Qui es-tu qui cries au Roi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Alors David dit à Abner: N’es-tu pas un vaillant homme? et qui est semblable à toi en Israël? pourquoi donc n’as-tu pas gardé le Roi ton Seigneur? car quelqu’un du peuple est venu pour tuer le Roi ton Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Ce n’est pas bien fait à toi; l’Eternel est vivant, que vous êtes dignes de mort, pour avoir si mal gardé votre Seigneur, l’Oint de l’Eternel; et maintenant regarde où est la hallebarde du Roi, et le pot à eau qui était à son chevet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Alors Saül reconnut la voix de David, et dit: N’est-ce pas là ta voix, mon fils David? Et David dit: C’est ma voix, ô Roi mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Il dit encore: Pourquoi mon Seigneur poursuit-il son serviteur? car qu’ai-je fait, et quel mal y a-t-il en ma main?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Maintenant donc je te prie, que le Roi mon Seigneur écoute les paroles de son serviteur. Si c’est l’Eternel qui te pousse contre moi, que ton oblation lui soit agréable; mais si ce sont les hommes, ils sont maudits devant l’Eternel; car aujourd’hui ils m’ont chassé, afin que je ne me tienne point joint à l’héritage de l’Eternel, et ils m’ont dit: Va, sers les dieux étrangers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Et maintenant, que mon sang ne tombe point en terre devant l’Eternel; car le Roi d’Israël est sorti pour chercher une puce, et comme qui poursuivrait une perdrix dans les montagnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Alors Saül dit: J’ai péché, retourne-t’en, mon fils David; car je ne te ferai plus de mal, parce qu’aujourd’hui ma vie t’a été précieuse. Voici, j’ai agi follement, et j’ai fait une très-grande faute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'Et David répondit, et dit: Voici la hallebarde du Roi; que quelqu’un des vôtres passe ici, et la prenne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Or que l’Eternel rende à chacun selon sa justice, et selon sa fidélité; car il t’avait livré aujourd’hui entre mes mains, mais je n’ai point voulu mettre ma main sur l’Oint de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Voici donc, comme ton âme a été aujourd’hui de grand prix devant mes yeux, ainsi mon âme sera de grand prix devant les yeux de l’Eternel, et il me délivrera de toutes les afflictions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Et Saül dit à David: Béni sois-tu, mon fils David; tu ne manqueras pas de réussir, et d’avoir le dessus. Alors David continua son chemin, et Saül s’en retourna en son lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Mais David dit en son coeur: Certes je périrai un jour par les mains de Saul; ne vaut-il pas mieux que je me sauve au pays des Philistins, afin que Saul n’espère plus de me trouver, en me cherchant encore en quelqu’une des contrées d’Israël? car je me sauverai ainsi de ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'David donc se leva, lui et les six cents hommes qui étaient avec lui, et il passa vers Akis fils de Mahoc, Roi de Gath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Et David demeura avec Akis à Gath, lui et ses gens, chacun avec sa famille, David et ses deux femmes,; savoir Ahinoham, qui était de Jizréhel, et Abigaïl, qui avait été femme de Nabal, lequel était de Carmel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Alors on rapporta à Saül que David s’en était fui à Gath; ainsi il ne continua plus de le chercher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Or David dit à Akis: Je te prie, si j’ai trouvé grâce devant toi, qu’on me donne quelque lieu dans l’une des villes de la campagne, afin que je demeure là; car pourquoi ton serviteur demeurerait-il dans la ville royale avec toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Akis donc lui donna en ce jour-là Tsiklag; c’est pourquoi Tsiklag est demeurée aux Rois de Juda jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Le nombre des jours que David demeura au pays des Philistins fut un an et quatre mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Or David montait avec ses gens, et ils faisaient des courses sur les Guesuriens, les Guirziens, et les Hamalécites; car ces nations -là habitaient au pays où elles avaient habité d’ancienneté, depuis Sur jusqu’au pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Et David désolait ces pays-là, il ne laissait ni homme ni femme en vie, et il prenait les brebis, les boeufs, les ânes, les chameaux, et les vêtements, puis il s’en retournait, et venait vers Akis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Et Akis disait: Où avez-vous fait vos courses aujourd’hui? Et David répondait: Vers le Midi de Juda, vers le Midi des Jerahméeliens, et vers le Midi des Kéniens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Mais David ne laissait en vie ni homme ni femme pour les amener à Gath, de peur, disait-il, qu’ils ne rapportent quelque chose contre nous, en disant: Ainsi a fait David. Et il en usa ainsi pendant tous les jours qu’il demeura au pays des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Et Akis croyait David, et disait: Il s’est mis en mauvaise odeur auprès d’Israël son peuple; c’est pourquoi il sera mon serviteur à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Or il arriva qu’en ces jours-là les Philistins assemblèrent leurs armées pour faire la guerre contre Israël; et Akis dit à David: Sache certainement que vous viendrez avec moi au camp, toi et tes gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'Et David répondit à Akis: Certainement tu connaîtras ce que ton serviteur fera. Et Akis dit à David: C’est pour cela que je te confierai toujours la garde de ma personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Or Samuel était mort, et tout Israël en avait fait le deuil, et on l’avait enseveli à Rama, qui était sa ville; et Saül avait ôté du pays ceux qui avaient l’esprit de Python, et les devins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Les Philistins donc assemblés s’en vinrent, et se campèrent à Sunem, Saül aussi assembla tout Israël, et ils se campèrent à Guilboah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Et Saül voyant le camp des Philistins eut peur, et son coeur fut fort effrayé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Et Saül consulta l’Eternel; mais l’Eternel ne lui répondit rien, ni par des songes, ni par l’Urim, ni par les Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Et Saül dit à ses serviteurs: Cherchez-moi une femme qui ait un esprit de Python, et j’irai vers elle, et je m’enquerrai par son moyen de ce que je dois faire. Ses serviteurs lui dirent: Voilà, il y a une femme à Hendor qui a un esprit de Python.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Alors Saül se déguisa, et prit d’autres habits, et s’en alla, lui et deux hommes avec lui, et ils arrivèrent de nuit chez cette femme; et Saül lui dit: Je te prie, devine-moi par l’esprit de Python, et fais monter vers moi celui que je te dirai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Mais la femme lui répondit: Voici, tu sais ce que Saül a fait, et comment il a exterminé du pays ceux qui ont l’esprit de Python, et les devins; pourquoi donc dresses-tu un piège à mon âme pour me faire mourir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Et Saül lui jura par l’Eternel, et lui dit: L’Eternel est vivant, s’il t’arrive aucun mal pour ceci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Alors la femme dit: Qui veux-tu que je te fasse monter? Et il répondit: Fais-moi monter Samuel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Et la femme voyant Samuel s’écria à haute voix, en disant à Saül: Pourquoi m’as-tu déçue? car tu es Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Et le Roi lui répondit: Ne crains point; mais qu’as-tu vu? Et la femme dit à Saül: J’ai vu un Dieu qui montait de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Il lui dit encore: Comment est-il fait? Elle répondit: C’est un vieillard qui monte, et il est couvert d’un manteau. Et Saül connut que c’était Samuel, et s’étant baissé le visage contre terre, il se prosterna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Et Samuel dit à Saül: Pourquoi m’as-tu troublé en me faisant monter? Et Saül répondit: Je suis dans une grande angoisse; car les Philistins me font la guerre, et Dieu s’est retiré de moi, et ne m’a plus répondu, ni par les Prophètes, ni par des songes; c’est pourquoi je t’ai appelé, afin que tu me fasses entendre ce que j’aurai à faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Et Samuel dit: Pourquoi donc me consultes-tu, puisque l’Eternel s’est retiré de toi, et qu’il est devenu ton ennemi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Or l’Eternel a fait selon qu’il en avait parlé par moi; car l’Eternel a déchiré le Royaume d’entre tes mains, et l’a donné à ton domestique, à David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Parce que tu n’as point obéi à la voix de l’Eternel, et que tu n’as point exécuté l’ardeur de sa colère contre Hamalec, à cause de cela l’Eternel t’a fait ceci aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Et même l’Eternel livrera Israël avec toi entre les mains des Philistins, et vous serez demain avec moi, toi et tes fils; l’Eternel livrera aussi le camp d’Israël entre les mains des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Et Saül tomba aussitôt à terre tout étendu, car il fut fort effrayé des paroles de Samuel, et même les forces lui manquèrent, parce qu’il n’avait rien mangé de tout ce jour-là, ni de toute la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Alors cette femme-là vint à Saül, et voyant qu’il avait été fort troublé, elle lui dit: Voici, ta servante a obéi à ta voix, et j’ai exposé ma vie, et j’ai obéi aux paroles que tu m’as dites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Maintenant, je te prie, que tu écoutes aussi ce que ta servante te dira: Souffre que je mette devant toi une bouchée de pain, afin que tu manges, et que tu aies des forces pour t’en retourner par ton chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Et il le refusa, et dit: Je ne mangerai point. Mais ses serviteurs et la femme aussi le pressèrent tant, qu’il acquiesça à leurs paroles, et s’étant levé de terre, il s’assit sur un lit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Or cette femme-là avait un veau qu’elle engraissait en sa maison; et elle se hâta de le tuer, puis elle prit de la farine, et la pétrit, et en cuisit des pains sans levain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Ce qu’elle mit devant Saül; et devant ses serviteurs; et ils mangèrent; puis s’étant levés, ils s’en allèrent cette nuit-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Or les Philistins assemblèrent toutes leurs armées à Aphek; et les Israëlites étaient campés près de la fontaine de Jizréhel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Et les Gouverneurs des Philistins passèrent par leurs centaines et par leurs milliers; et David et ses gens passèrent sur l’arrière-garde avec Akis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Et les chefs des Philistins dirent: Qu’est-ce que ces Hébreux-là? Et Akis répondit aux chefs des Philistins: N’est-ce pas ici ce David, serviteur de Saül Roi d’Israël, qui a déjà été avec moi quelque temps, même quelques années? et je n’ai rien trouvé à redire en lui depuis le jour qu’il s’est rendu à moi, jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Mais les chefs des Philistins se mirent en colère contre lui, et lui dirent: Renvoie cet homme, et qu’il s’en retourne dans le lieu où tu l’as établi, et qu’il ne descende point avec nous dans la bataille, de peur qu’il ne se tourne contre nous dans la bataille; car comment pourrait-il se remettre en grâce avec son Seigneur? ne serait-ce pas par le moyen des têtes de ces hommes-ci?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'N’est-ce pas ici ce David, duquel on s’entre-répondait aux danses, en disant? Saül en a frappé ses mille et David ses dix mille?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Akis donc appela David, et lui dit: L’Eternel est vivant, que tu es certainement un homme droit, et que ta conduite au camp m’a paru bonne, car je n’ai point trouvé de mal en toi, depuis le jour que tu es venu à moi jusqu’à ce jour; mais tu ne plais point aux Gouverneurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Maintenant donc retourne-t’en, et t’en va en paix, afin que tu ne fasses aucune chose qui déplaise aux Gouverneurs des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'Et David dit à Akis: Mais qu’ai-je fait? et qu’as-tu trouvé en ton serviteur depuis le jour que j’ai été avec toi jusqu’à ce jour, que je n’aille point combattre contre les ennemis du Roi mon Seigneur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Et Akis répondit et dit à David: Je le sais: car tu es agréable à mes yeux, comme un Ange de Dieu; mais c’est seulement que les chefs des Philistins ont dit: Il ne montera point avec nous dans la bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'C’est pourquoi lève-toi de bon matin, avec les serviteurs de ton Seigneur qui sont venus avec toi; et étant levés de bon matin, sitôt que vous verrez le jour, allez-vous-en.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Ainsi David se leva de bon matin, lui et ses gens, pour partir dès le matin, et s’en retourner au pays des Philistins; mais les Philistins montèrent à Jizréhel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Or trois jours après David et ses gens étant revenus à Tsiklag, trouvèrent que les Hamalécites s’étaient jetés du côté du Midi, et sur Tsiklag, et qu’ils avaient frappé Tsiklag, et l’avaient brûlée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Et qu’ils avaient fait prisonnières les femmes qui étaient là, sans avoir tué aucun homme, depuis les plus petits jusqu’aux plus grands: mais ils les avaient emmenés, et s’en étaient allés leur chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'David donc et ses gens revinrent en la ville: et voici elle était brûlée, et leurs femmes, et leurs fils, et leurs filles avaient été faits prisonniers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'C’est pourquoi David et le peuple qui était avec lui élevèrent leur voix, et pleurèrent tellement qu’il n’y avait plus en eux de force pour pleurer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Et les deux femmes de David avaient été prises prisonnières, savoir Ahinoham de Jizréhel, et Abigaïl qui avait été femme de Nabal, lequel était de Carmel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Mais David fut dans une grande extrémité, parce que le peuple parlait de le lapider; car tout le peuple était outré à cause de leurs fils et de leurs filles; toutefois David se fortifia en l’Eternel son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Et il dit à Abiathar le Sacrificateur, fils d’Ahimélec: Mets, je te prie, l’Ephod pour moi; et Abiathar mit l’Ephod pour David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Et David consulta l’Eternel, en disant: Poursuivrai-je cette troupe-là; l’atteindrai-je? et il lui répondit: Poursuis-la; car tu ne manqueras point de l’atteindre, et de recouvrer tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'David donc s’en alla avec les six cents hommes qui étaient avec lui, et ils arrivèrent au torrent de Bésor, où s’arrêtèrent ceux qui demeuraient en arrière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Ainsi David et quatre cents hommes firent la poursuite, mais deux cents hommes s’arrêtèrent, qui étaient trop fatigués pour pouvoir passer le torrent de Bésor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Or ayant trouvé un homme Egyptien par les champs, ils l’amenèrent à David, et lui donnèrent du pain, et il mangea, puis ils lui donnèrent de l’eau à boire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'Ils lui donnèrent aussi quelques figues sèches, et deux grappes de raisins secs, et il mangea, et le coeur lui revint; car il y avait trois jours et trois nuits qu’il n’avait point mangé de pain, ni bu d’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Et David lui dit: A qui es-tu? et d’où es-tu? Et il répondit: Je suis un garçon Egyptien, serviteur d’un homme Hamalécite; et mon maître m’a abandonné, parce que je tombai malade il y a trois jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Nous nous étions jetés du côté du Midi des Keréthiens, et sur ce qui est de Juda, et du côté du Midi de Caleb, et nous avons brûlé Tsiklag par feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'Et David lui dit: Me conduiras-tu bien vers cette troupe-là? Et il répondit: Jure-moi par le nom de Dieu que tu ne me feras point mourir, et que tu ne me livreras point entre les mains de mon maître, et je te conduirai vers cette troupe-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Et il le conduisit dans ce lieu-là. Et voici, ils étaient dispersés sur toute la terre, mangeant, buvant, et dansant, à cause de ce grand butin qu’ils avaient pris au pays des Philistins, et au pays de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Et David les frappa depuis l’aube du jour jusqu’au soir du lendemain qu’il s’était mis à les poursuivre; et il n’en échappa aucun d’eux, hormis quatre cents jeunes hommes qui montèrent sur des chameaux, et qui s’enfuirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Et David recouvra tout ce que les Hamalécites avaient emporté; il recouvra aussi ses deux femmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Et ils trouvèrent que rien ne leur manquait, depuis le plus petit jusqu’au plus grand, tant des fils que des filles, et du butin, et de tout ce qu’ils leur avaient emporté; David recouvra le tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'David prit aussi tout le reste du gros et du menu bétail, qu’on mena devant les troupeaux qu’on leur avait pris; et on disait: C’est ici le butin de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Puis David vint vers les deux cents hommes qui avaient été tellement fatigués qu’ils n’avaient pu marcher après David, qui les avait fait demeurer auprès du torrent de Bésor; et ils sortirent au devant de David, et au devant du peuple qui était avec lui; et David s’étant approché du peuple, il les salua aimablement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Mais tous les mauvais et méchants hommes qui étaient allés avec David, prirent la parole, et dirent: Puisqu’ils ne sont point venus avec nous, nous ne leur donnerons rien du butin que nous avons recouvré, sinon à chacun d’eux sa femme et ses enfants, et qu’ils les emmènent, et s’en aillent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Mais David dit: Mes frères, vous ne ferez pas ainsi de ce que l’Eternel nous a donné, lequel nous a gardés, et a livré entre nos mains la troupe qui était venue contre nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Qui vous croirait en ce cas-ci? car celui qui demeure au bagage doit avoir autant de part que celui qui descend à la bataille; ils partageront également.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Ce qui fut ainsi pratiqué depuis ce jour-là, et il en fut fait une ordonnance et une loi en Israël, jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'David donc revint à Tsiklag, et envoya du butin aux Anciens de Juda, savoir à ses amis, en disant: Voici, un présent pour vous, du butin des ennemis de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Il en envoya à ceux qui étaient à Béthel, et à ceux qui étaient à Ramoth du Midi, et à ceux qui étaient à Jattir,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'Et à ceux qui étaient à Haroher, et à ceux qui étaient à Siphamoth, et à ceux qui étaient à Estemoah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'Et à ceux qui étaient à Racal, et à ceux qui étaient dans les villes des Jerahméeliens, et à ceux qui étaient dans les villes des Kéniens,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'Et à ceux qui étaient à Horma, et à ceux qui étaient à Cor-hasan, et à ceux qui étaient à Hathac,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'Et à ceux qui étaient à Hébron, et dans tous les lieux où David avait demeuré, lui et ses gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Or les Philistins combattirent contre Israël, et ceux d’Israël s’enfuirent de devant les Philistins, et furent tués en la montagne de Guilboah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Et les Philistins atteignirent Saül et ses fils, et tuèrent Jonathan, Abinadab et Malki-suah, fils de Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Et le combat se renforça contre Saül, et les archers tirant de l’arc le trouvèrent; et il eut fort grande peur de ces archers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Alors Saül dit à son écuyer: Tire ton épée, et m’en transperce, de peur que ces incirconcis ne viennent, ne me transpercent, et ne se jouent de moi; mais son écuyer ne le voulut point faire, parce qu’il était fort effrayé. Saül donc prit l’épée, et se jeta dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Alors l’écuyer de Saül ayant vu que Saül était mort, se jeta aussi sur son épée, et mourut avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Ainsi mourut en ce jour-là Saül et ses trois fils, son écuyer, et tous ses gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Et ceux d’Israël qui étaient au deçà de la vallée, et au deçà du Jourdain, ayant vu que les Israëlites s’en étaient fuis, et que Saül et ses fils étaient morts, abandonnèrent les villes, et s’enfuirent, de sorte que les Philistins y entrèrent, et y habitèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Or il arriva que dès le lendemain les Philistins vinrent pour dépouiller les morts, et ils trouvèrent Saül et ses trois fils étendus sur la montagne de Guilboah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Et ils coupèrent la tête de Saül, et le dépouillèrent de ses armes, qu’ils envoyèrent au pays des Philistins, dans tous les environs, pour en faire savoir les nouvelles dans les temples de leurs faux dieux, et parmi le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Et ils mirent ses armes au temple de Hastaroth, et attachèrent son corps à la muraille de Bethsan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Or les habitants de Jabés de Galaad apprirent ce que les Philistins avaient fait à Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'Et tous les vaillants hommes d’entr’eux, se levèrent et marchèrent toute la nuit, et enlevèrent le corps de Saül, et les corps de ses fils, de la muraille de Bethsan, et revinrent à Jabés, où ils les brûlèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Puis ils prirent leurs os, les ensevelirent sous un chêne près de Jabés, et ils jeûnèrent sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Or il arriva qu’après que Saül fut mort, David étant revenu de la défaite des Hamalécites, demeura à Tsiklag deux jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Et au troisième jour, voici un homme qui revenait du camp de Saül, ayant ses vêtements déchirés, et de la terre sur sa tête, lequel étant venu à David, se jeta en terre, et se prosterna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Et David lui dit: D’où viens-tu? et il lui répondit: Je me suis échappé du camp d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'David lui dit: Qu’est-il arrivé? Je te prie, raconte-le moi. Il répondit: Le peuple s’est enfui de la bataille, et il y en a eu beaucoup du peuple qui sont tombés morts; Saül aussi et Jonathan son fils sont morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Et David dit à ce jeune garçon qui lui disait ces nouvelles: Comment sais-tu que Saül et Jonathan son fils soient morts?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Et le jeune garçon qui lui disait ces nouvelles, lui répondit: Je me trouvai par hasard en la montagne de Guilboah, et voici Saül se tenait penché sur sa hallebarde, car voici, un chariot et quelques Chefs de gens de cheval le poursuivaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Et regardant derrière soi, il me vit, et m’appela; et je lui répondis: Me voici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Et il me dit: Qui es-tu? et je lui répondis: Je suis Hamalécite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Et il me dit: Tiens-toi ferme sur moi, je te prie, et me tue; car je suis dans une grande angoisse, et ma vie est encore toute en moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Je me suis donc tenu ferme sur lui, et je l’ai fait mourir; car je savais bien qu’il ne vivrait pas après s’être ainsi jeté sur sa hallebarde; et j’ai pris la couronne qu’il avait sur sa tête, et le bracelet qu’il avait en son bras, et je les ai apportés ici à mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Alors David prit ses vêtements, et les déchira; et tous les hommes qui étaient avec lui en firent de même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Ils menèrent deuil, ils pleurèrent, et ils jeûnèrent jusqu’au soir, à cause de Saül et de Jonathan son fils, et à cause du peuple de l’Eternel, et de la maison d’Israël, parce qu’ils étaient tombés par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Mais David dit au jeune garçon qui lui avait dit ces nouvelles: D’où es-tu? Et il répondit: Je suis fils d’un étranger Hamalécite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Et David lui dit: Comment n’as-tu pas craint d’avancer ta main pour tuer l’Oint de l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Alors David appela l’un de ses gens, et lui dit: Approche-toi, et te jette sur lui; lequel le frappa, et il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Car David lui avait dit: Ton sang soit sur ta tête, puisque ta bouche a porté témoignage contre toi, en disant: J’ai fait mourir l’Oint de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Alors David fit sur Saül, et sur Jonathan son fils, cette complainte,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'Laquelle il proféra pour enseigner aux enfants de Juda à tirer de l’arc; voici elle est écrite au Livre de Jasar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Ô noblesse d’Israël! ceux qui ont été tués sont sur tes hauts lieux. Comment sont tombés les hommes forts?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Ne l’allez point dire dans Gath, et n’en portez point les nouvelles dans les places d’Askélon; de peur que les filles des Philistins ne s’en réjouissent, de peur que les filles des incirconcis n’en tressaillent de joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Montagne de Guilboah, que la rosée et la pluie ne tombent point sur vous, ni sur les champs qui y sont haut élevés; parce que c’est là qu’a été jeté le bouclier des forts, et le bouclier de Saül, comme s’il n’eût point été oint d’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'L’arc de Jonathan ne revenait jamais sans le sang des morts, et sans la graisse des forts; et l’épée de Saül ne retournait jamais sans effet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saül et Jonathan, aimables et agréables en leur vie, n’ont point été séparés dans leur mort; ils étaient plus légers que les aigles, ils étaient plus forts que des lions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Filles d’Israël, pleurez sur Saül, qui faisait que vous étiez vêtues d’écarlate, que vous viviez dans les délices, et que vous portiez des ornements d’or sur vos vêtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Comment les forts sont-ils tombés au milieu de la bataille! comment Jonathan a-t-il été tué sur ces hauts lieux!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Jonathan mon frère! Je suis dans l’angoisse pour l’amour de toi; tu faisais tout mon plaisir; l’amour que j’avais pour toi était plus grand que celui qu’on a pour les femmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Comment sont tombés tes forts, et comment sont péris les instruments de guerre!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Or il arriva après cela que David consulta l’Eternel, en disant: Monterai-je en quelqu’une des villes de Juda? Et l’Eternel lui répondit: Monte. Et David dit: En laquelle monterai-je? Il répondit: A Hébron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'David donc monta là avec ses deux femmes, Ahinoham qui était de Jizréhel, et Abigal, qui avait été femme de Nabal, lequel était de Carmel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'David fit remonter aussi les hommes qui étaient avec lui, chacun avec sa famille, et ils demeurèrent dans les villes de Hébron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Et ceux de Juda vinrent, et oignirent là David pour Roi sur la maison de Juda. Et on fit rapport à David; en disant: Les hommes de Jabés de Galaad ont enseveli Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Et David envoya des messagers vers les hommes de Jabés de Galaad, et leur fit dire: Bénis soyez-vous de l’Eternel de ce que vous avez fait cette gratuité à Saül votre Seigneur, que de l’avoir enseveli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Que maintenant donc l’Eternel veuille user envers vous de gratuité, et de vérité; de ma part aussi je vous ferai du bien, parce que vous avez fait cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Et que maintenant vos mains se fortifient, et soyez hommes de coeur; car Saül votre Seigneur est mort, et la maison de Juda m’a oint pour être Roi sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Mais Abner fils de Ner, chef de l’armée de Saül, prit Is-boseth fils de Saül, et le fit passer à Mahanajim;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'Et l’établit Roi sur Galaad, et sur les Asuriens, et sur Jizréhel, et sur Ephraïm, et sur Benjamin; même sur tout Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Is-boseth fils de Saül était âgé de quarante ans quand il commença à régner sur Israël, et il régna deux ans. Il n’y avait que la maison de Juda qui suivît David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Et le nombre des jours que David régna à Hébron sur la maison de Juda, fut de sept ans et six mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Or Abner fils de Ner, et les gens d’Is-boseth fils de Saül, sortirent de Mahanajim, vers Gabaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Joab aussi fils de Tséruja, et les gens de David sortirent, et ils se rencontrèrent les uns les autres près de l’étang de Gabaon; et les uns se tenaient auprès de l’étang du côté de deçà, et les autres auprès de l’étang du côté de delà.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Alors Abner dit à Joab: Que quelques-uns de ces jeunes gens se lèvent maintenant, et qu’ils escarmouchent devant nous. Et Joab dit: Qu’ils se lèvent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Ils se levèrent donc, et on en compta douze de Benjamin pour le parti d’Is-boseth fils de Saül; et douze des gens de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Alors chacun d’eux empoignant son homme lui passa son épée dans les flancs, et ils tombèrent tous ensemble; et ce lieu-là fut appelé Helkath-hatsurim, qui est en Gabaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Et il y eut en ce jour-là un très-rude combat, dans lequel Abner fut battu avec ceux d’Israël par les gens de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Les trois fils de Tséruja, Joab, Abisaï, et Hasaël étaient là. Et Hasaël était léger du pied comme un chevreuil qui est par les champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Et Hasaël poursuivit Abner, sans se détourner à droite ni à gauche d’après Abner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Abner donc regardant derrière soi, dit: Es-tu Hasaël? et Hasaël répondit: Je le suis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Et Abner lui dit: Détourne-toi à droite ou à gauche, et saisis- toi de l’un de ces jeunes gens, et prends sa dépouille pour toi. Mais Hasaël ne voulut point se détourner de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Et Abner continuait à dire à Hasaël: Détourne-toi de moi; pourquoi te jetterais-je mort par terre? et comment oserais-je paraître devant Joab ton frère?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Mais il ne voulut jamais se détourner; et Abner le frappa de sa hallebarde à la cinquième côte du bout de derrière, tellement que sa hallebarde lui sortait par derrière, et il tomba là roide mort sur la place; et tous ceux qui venaient à l’endroit où Hasaël était tombé mort, s’arrêtaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Joab donc et Abisaï poursuivirent Abner, et le soleil se coucha quand ils arrivèrent au coteau d’Amma, qui est vis-à-vis de Gujah, au chemin du désert de Gabaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Et les enfants de Benjamin s’assemblèrent auprès d’Abner, se rangèrent en un bataillon, et se tinrent sur le sommet d’un coteau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Alors Abner cria à Joab, et dit: L’épée dévorera-t-elle sans cesse? ne sais-tu pas bien que l’amertume est à la fin; et jusqu’à quand différeras-tu de dire au peuple, qu’il cesse de poursuivre ses frères?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Et Joab dit: Dieu est vivant, que si tu avais parlé ainsi, le peuple se serait retiré dès le matin chacun arrière de son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Joab donc sonna de la trompette et tout le peuple s’arrêta, ils ne poursuivirent plus Israël, et ils ne continuèrent plus à se battre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Ainsi Abner et ses gens marchèrent toute cette nuit-là par la campagne, traversèrent le Jourdain, passèrent par tout Bithron, et arrivèrent à Mahanajim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Joab aussi revint de la poursuite d’Abner; et quand il eut assemblé tout le peuple, on trouva qu’il en manquait dix-neuf des gens de David, et Hasaël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Mais les gens de David frappèrent de ceux de Benjamin, savoir des gens d’Abner, trois cent soixante hommes qui moururent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Et ils enlevèrent Hasaël, et l’ensevelirent au sépulcre de son père, à Bethléhem; et toute cette nuit-là Joab et ses gens marchèrent et arrivèrent à Hébron sur le point du jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Or il y eut une longue guerre entre la maison de Saül, et la maison de David. Mais David s’avançait et se fortifiait; et la maison de Saül allait en diminuant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Et il naquit à David des fils à Hébron; son premier-né fut Amnon, d’Ahinoham, qui était de Jizréhel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'Le second fut Kiléab, d’Abigal, qui avait été femme de Nabal, lequel était de Carmel. Le troisième fut Absalom, fils de Mahaca, fille de Talmaï, Roi de Guesur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'Le quatrième fut Adonija, fils de Haggith. Le cinquième fut Sephatja, fils d’Abital.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'Et le sixième fut Jithréham, d’Hegla, qui était aussi femme de David. Ceux-ci naquirent à David à Hébron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Il arriva donc que pendant qu’il y eut guerre entre la maison de Saül et la maison de David, Abner soutenait la maison de Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Or Saül avait eu une concubine nommée Ritspa, fille d’Aja; et Is- boseth dit à Abner: Pourquoi es-tu venu vers la concubine de mon père?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Et Abner fut fort irrité à cause du discours d’Is-boseth, et il lui dit: Suis-je une tête de chien, moi qui ai fait paraître en ce temps-ci contre Juda mon attachement pour la maison de Saül ton père et pour ses frères, et ses amis, en ne te faisant point tomber entre les mains de David, que tu me recherches aujourd’hui pour l’iniquité d’une femme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Que Dieu fasse ainsi à Abner, et ainsi il y ajoute, si je ne fais à David selon ce que l’Eternel lui a juré;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'En lui transportant le Royaume de la maison de Saül, et en établissant le trône de David sur Israël et sur Juda, depuis Dan jusqu’à Beersébah!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Et Is-boseth n’osa répondre un seul mot à Abner, à cause qu’il le craignait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Abner donc envoya des messagers à David de sa part, pour lui dire: A qui est le pays? et pour lui dire: Fais accord avec moi, et voici ma main sera avec toi, pour réduire sous ton pouvoir tout Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Et David répondit: Je le veux bien; je ferai accord avec toi; je te demande seulement une chose, c’est que tu ne verras point ma face, si premièrement tu ne me ramènes Mical fille de Saül, quand tu viendras me voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Alors David envoya des messagers à Is-boseth fils de Saül, pour lui dire: Rends moi ma femme Mical, que j’ai épousée pour cent prépuces des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Et Is-boseth envoya, et l’ôta à son mari Paltiel fils de Laïs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Et son mari s’en alla avec elle pleurant continuellement après elle, jusqu’à Bahurim; et Abner lui dit: Va, et t’en retourne; et il s’en retourna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Or Abner parla aux Anciens d’Israël, et leur dit: Vous cherchiez autrefois David pour l’établir Roi sur vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Maintenant donc faites-le; car l’Eternel a parlé de David, et a dit: Par le moyen de David mon serviteur je délivrerai mon peuple d’Israël de la main des Philistins, et de la main de tous leurs ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Et Abner parla de même à ceux de Benjamin, eux l’entendant; puis il s’en alla pour faire entendre expressément à David, qui était à Hébron, ce qui semblait bon à Israël, et à toute la maison de Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Et Abner vint vers David à Hébron, et vingt hommes avec lui; et David fit un festin à Abner, et aux hommes qui étaient avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Puis Abner dit à David: Je me lèverai, et je m’en irai assembler tout Israël, afin qu’ils se rendent au Roi mon Seigneur, et qu’ils traitent alliance avec toi; et tu régneras comme ton âme le souhaite. Et David renvoya Abner, qui s’en alla en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Or voici, les gens de David revenaient avec Joab, de faire quelque course, et ils amenaient avec eux un grand butin; mais Abner n’était plus avec David à Hébron; car il l’avait renvoyé, et il s’en était allé en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Joab donc, et toute l’armée qui était avec lui, revint; et on fit ce rapport à Joab, en disant: Abner fils de Ner est venu vers le Roi, qui l’a renvoyé, et il s’en est allé en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Et Joab vint au Roi, et dit: Qu’as-tu fait? Voici, Abner est venu vers toi; pourquoi l’as-tu ainsi renvoyé, tellement qu’il s’en soit allé son chemin?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Tu sais bien qu’Abner fils de Ner est venu pour te tromper, pour reconnaître ta sortie et ton entrée, et savoir tout ce que tu fais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Et Joab sortit d’auprès de David, et envoya après Abner des gens qui le ramenèrent de la fosse de Sira, sans que David en sût rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Abner donc étant retourné à Hébron, Joab le tira à part au dedans de la porte pour lui parler en secret; et il le frappa là à la cinquième côte, et ainsi Abner mourut à cause du sang de Hasaël frère de Joab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Et David ayant appris ce qui était arrivé, dit: Je suis innocent, moi et mon Royaume, devant l’Eternel à jamais, du sang d’Abner fils de Ner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Que ce sang s’arrête sur la tête de Joab, et sur toute la maison de son père; et que la maison de Joab ne soit jamais sans quelque homme ayant un flux, ou ayant la lèpre, ou s’appuyant sur un bâton, ou tombant par l’épée, ou ayant disette de pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Ainsi Joab et Abisaï son frère tuèrent Abner, parce qu’il avait tué Hasaël leur frère près de Gabaon en la bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Et David dit à Joab, et à tout le peuple qui était avec lui: Déchirez vos vêtements, et couvrez-vous de sacs, et menez deuil en marchant devant Abner. Et le Roi David marchait après le cercueil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Et quand ils eurent enseveli Abner à Hébron, le Roi éleva sa voix, et pleura près du sépulcre d’Abner; tout le peuple aussi pleura.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Et le Roi fit une complainte sur Abner, et dit: Abner est-il mort comme meurt un lâche?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Tes mains n’étaient point liées, et tes pieds n’avaient point été mis dans des ceps d’airain, mais tu es tombé comme on tombe devant les méchants; et tout le peuple recommença à pleurer sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Puis tout le peuple vint pour faire prendre quelque nourriture à David, pendant qu’il était encore jour; mais David jura, et dit: Que Dieu me fasse ainsi, et ainsi il y ajoute, si avant le soleil couché je goûte du pain, ni aucune autre chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Et tout le peuple l’entendit, et le trouva bon; et tout le peuple approuva tout ce que le Roi fit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'En ce jour-là donc tout le peuple et tout Israël connut que ce qu’on avait fait mourir Abner fils de Ner, n’était point venu du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Et le Roi dit à ses serviteurs: Ne savez-vous pas qu’un capitaine, et même un grand capitaine, a été aujourd’hui mis à mort en Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Or je suis encore faible aujourd’hui, bien que j’aie été oint Roi, et ces gens, les fils de Tséruja, sont trop forts pour moi. L’Eternel veuille rendre à celui qui fait le mal selon sa malice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Quand le fils de Saül eut appris qu’Abner était mort à Hébron, ses mains devinrent lâches, et tout Israël fut étonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Or le fils de Saül avait deux capitaines de bandes, dont l’un avait nom Bahana, et l’autre Récab, fils de Rimmon Béerothien, des enfants de Benjamin; car la ville de Béeroth était aussi réputée de Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Et les Béerothiens s’étaient enfuis à Guittajim, et ils y ont fait leur séjour jusqu’à aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Et Jonathan, fils de Saül avait un fils blessé aux pieds, âgé de cinq ans, lorsque le bruit de la mort de Saül et de Jonathan vint de Jizréhel; et sa gouvernante le prit, et s’enfuit; et comme elle se hâtait de fuir, il tomba, et devint boiteux; et il fut nommé Méphiboseth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Récab donc et Bahana fils de Rimmon Béerothien vinrent, et entrèrent pendant la chaleur du jour dans la maison d’Is-boseth, qui prenait son repos du midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Ainsi Récab et Bahana son frère entrèrent jusqu’au milieu de la maison, allant prendre du froment, et ils le frappèrent à la cinquième côte, et se sauvèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Ils entrèrent donc dans la maison, lorsque Is-boseth était couché sur son lit, dans la chambre où il dormait, et ils le frappèrent, et le tuèrent; puis ils lui ôtèrent la tête, et la prirent, et ils marchèrent par le chemin de la campagne toute cette nuit-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Et ils apportèrent la tête d’Is-boseth à David à Hébron, et ils dirent au Roi: Voici la tête d’Is-boseth fils de Saül ton ennemi, qui cherchait ta vie; et l’Eternel a aujourd’hui vengé le Roi mon Seigneur, de Saül et de sa race.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Mais David répondit à Récab et à Bahana son frère, enfants de Rimmon Béerothien, et leur dit: L’Eternel qui a délivré mon âme de toute angoisse, est vivant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'Que je saisis celui qui vint m’annoncer et me dire: Voilà, Saül est mort, et qui pensait m’apprendre de bonnes nouvelles et je le tuai à Tsiklag, ce qui fut le salaire que je lui devais donner pour ses bonnes nouvelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Combien plus dois-je faire punir ces méchants qui ont tué un homme de bien dans sa maison, sur son lit? Maintenant donc ne redemanderai-je pas son sang de votre main, et ne vous exterminerai- je pas de la terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'David donc fit commandement à ses gens, lesquels les tuèrent et leur coupèrent les mains et les pieds, et les pendirent sur l’étang d’Hébron. Puis on prit la tête d’Is-boseth, et on l’ensevelit au sépulcre d’Abner à Hébron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Alors toutes les Tribus d’Israël vinrent vers David à Hébron, et lui parlèrent, en disant: Voici, nous sommes tes os et ta chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Et même auparavant, quand Saül était Roi sur nous, tu étais celui qui menais et qui ramenais Israël; et de plus l’Eternel t’a dit: Tu paîtras mon peuple d’Israël, et tu seras Conducteur d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Tous les Anciens donc d’Israël vinrent vers le Roi à Hébron; et le Roi David traita alliance avec eux à Hébron devant l’Eternel; et ils oignirent David pour Roi sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'David était âgé de trente ans quand il commença à régner, et il régna quarante ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'Il régna à Hébron sur Juda sept ans et six mois; puis il régna trente-trois ans à Jérusalem sur tout Israël et Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Or le Roi s’en alla avec ses gens à Jérusalem contre les Jébusiens qui habitaient en ce pays-là, lesquels dirent à David: Tu n’entreras point ici que tu n’aies ôté les aveugles et les boiteux; voulant dire, David n’entrera point ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Néanmoins David prit la forteresse de Sion, qui est la Cité de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Or David avait dit en ce jour-là: Quiconque aura battu les Jébusiens, et aura atteint le canal, et les aveugles et les boiteux qui sont haïs de l’âme de David, sera récompensé. C’est pourquoi on dit: Aucun aveugle ni boiteux n’entrera dans cette maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Et David habita dans la forteresse, et l’appela la Cité de David; et David y bâtit tout alentour, depuis Millo jusqu’au dedans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Et David faisait toujours des progrès; car l’Eternel le Dieu des armées était avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Hiram aussi Roi de Tyr envoya des messagers à David, et du bois de cèdre, et des charpentiers, et des tailleurs de pierres à bâtir; et ils bâtirent la maison de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Et David connut que l’Eternel l’avait affermi Roi sur Israël, et qu’il avait élevé son Royaume, à cause de son peuple d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Et David prit encore des concubines et des femmes de Jérusalem, après qu’il fut venu d’Hébron, et il lui naquit encore des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Et ce sont ici les noms de ceux qui lui naquirent à Jérusalem, Sammuah, et Sobab, et Nathan, et Salomon,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Et Jibhar, et Elisuah, et Népheg, et Japhiah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Et Elisama, et Eljadah, et Eliphelet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Or quand les Philistins eurent appris qu’on avait oint David pour Roi sur Israël, ils montèrent tous pour chercher David; et David l’ayant appris, descendit vers la forteresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Et les Philistins vinrent, et se répandirent dans la vallée des Réphaïms.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Alors David consulta l’Eternel, en disant: Monterai-je contre les Philistins? les livreras-tu entre mes mains? et l’Eternel répondit à David: Monte, car certainement je livrerai les Philistins entre tes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Alors David vint en Bahal-pératsim, et les battit là, et il dit: L’Eternel a fait écouler mes ennemis devant moi, comme par un débordement d’eaux; c’est pourquoi il nomma ce lieu-là, Bahal- pératsim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Et ils laissèrent là leurs faux dieux, lesquels David et ses gens emportèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Et les Philistins montèrent encore une autre fois, et se répandirent dans la vallée des Réphaïms.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Et David consulta l’Eternel, qui répondit: Tu ne monteras point; mais tu tourneras derrière eux, et iras contr’eux vis-à-vis des meuriers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Et quand tu entendras sur le sommet des meuriers un bruit comme de gens qui marchent, alors remue-toi; parce que l’Eternel sera sorti alors devant toi pour battre le camp des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'David donc fit ainsi que l’Eternel lui avait commandé; et battit les Philistins depuis Guébah jusqu’à Guézer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'David assembla encore tous les hommes d’élite d’Israël, qui furent trente mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Puis David se leva et partit avec tout le peuple qui était avec lui vers Bahalé de Juda, pour transporter l’Arche de Dieu, duquel le nom est appelé: Le nom de l’Eternel des armées, qui habite entre les Chérubins sur l’Arche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Et ils mirent l’Arche de Dieu sur un chariot tout neuf, et l’emmenèrent de la maison d’Abinadab, qui était au coteau; et Huza et Ahjo, enfants d’Abinadab, conduisaient le chariot neuf.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Et ils l’emmenèrent, savoir l’Arche de Dieu de la maison d’Abinadab, qui était au coteau, et Ahjo allait devant l’Arche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Et David et toute la maison d’Israël jouaient devant l’Eternel de toutes sortes d’instruments faits de bois de sapin, et des violons, des musettes, des tambours, des sistres, et des cymbales.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Et quand ils furent venus jusqu’à l’aire de Nacon, Huza porta sa main à l’Arche de Dieu, et la retint, parce que les boeufs avaient glissé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Et la colère de l’Eternel s’enflamma contre Huza, et Dieu le frappa là à cause de son indiscrétion, et il mourut là près de l’Arche de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Et David fut affligé de ce que l’Eternel avait fait brèche en la personne de Huza; c’est pourquoi on a appelé ce lieu-là jusqu’à aujourd’hui Pérets-Huza.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Et David eut peur de l’Eternel en ce jour-là, et dit: Comment l’Arche de l’Eternel entrerait-elle chez moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Et David ne voulut point retirer l’Arche de l’Eternel chez soi en la Cité de David, mais il la fit détourner en la maison d’Hobed-Edom Guittien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'Et l’Arche de l’Eternel demeura trois mois en la maison d’Hobed- Edom Guittien; et l’Eternel bénit Hobed-Edom, et toute sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Depuis on vint dire à David: L’Eternel a béni la maison d’Hobed- Edom, et tout ce qui lui appartient, pour l’amour de l’Arche de Dieu; c’est pourquoi David s’en alla, et amena l’Arche de Dieu de la maison d’Hobed-Edom, en la Cité de David, avec joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Et il arriva que quand ceux qui portaient l’Arche de Dieu eurent marche six pas, on sacrifia des taureaux et des béliers gras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Et David sautait de toute sa force devant l’Eternel; et il était ceint d’un Ephod de lin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Ainsi David et toute la maison d’Israël menaient l’Arche de l’Eternel avec des cris de joie, et au son des trompettes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Mais comme l’Arche de l’Eternel entrait dans la Cité de David, Mical fille de Saül, regardant par la fenêtre, vit le Roi David sautant de toute sa force devant l’Eternel, et elle le méprisa en son coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Ils emmenèrent donc l’Arche de l’Eternel, et la posèrent en son lieu, dans un Tabernacle que David lui avait tendu. Et David offrit des holocaustes et des sacrifices de prospérités devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Quand David eut achevé d’offrir des holocaustes et des sacrifices de prospérités, il bénit le peuple au nom de l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Et il partagea à tout le peuple, savoir à toute la multitude d’Israël, tant aux hommes qu’aux femmes, à chacun un gâteau, une pièce de chair, et une bouteille de vin; et tout le peuple s’en retourna chacun en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Puis David s’en retourna pour bénir sa maison; et Mical fille de Saül vint au-devant de lui, et lui dit: Que le Roi d’Israël s’est fait aujourd’hui un grand honneur en se découvrant aujourd’hui devant les yeux des servantes de ses serviteurs, comme ferait un homme de néant, sans en avoir honte!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Et David dit à Mical: Ç’a été devant l’Eternel, qui m’a choisi plutôt que ton père, et que toute sa maison, et qui m’a commandé d’être le Conducteur de son peuple d’Israël; c’est pourquoi je me réjouirai devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'Et je me rendrai encore plus abject que je n’ai fait cette fois, et je m’estimerai encore moins; malgré cela je serai honoré devant les servantes dont tu as parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Or Mical fille de Saül n’eut point d’enfants jusqu’au jour de sa mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Or il arriva qu’après que le Roi fut assis en sa maison, et que l’Eternel lui eut donné la paix avec tous ses ennemis d’alentour;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'Il dit à Nathan le Prophète: Regarde maintenant, j’habite dans une maison de cèdres, et l’Arche de Dieu habite dans des courtines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Et Nathan dit au Roi: Va, fais tout ce qui est en ton coeur; car l’Eternel est avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Mais il arriva cette nuit-là, que la parole de l’Eternel fut adressée à Nathan, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Va, et dis à David mon serviteur: Ainsi a dit l’Eternel: Me bâtirais-tu une maison afin que j’y habite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Puisque je n’ai point habité dans une maison depuis le jour que j’ai fait monter les enfants d’Israël hors d’Egypte, jusqu’à ce jour? mais j’ai marché çà et là dans un Tabernacle, et dans un pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Dans tous les lieux où j’ai marché avec tous les enfants d’Israël, en ai-je dit un seul mot à quelqu’une des Tribus d’Israël, à laquelle j’ai commandé de paître mon peuple d’Israël, en disant: Pourquoi ne m’avez-vous point bâti une maison de cèdres?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Maintenant donc tu diras ainsi à David mon serviteur: Ainsi a dit l’Eternel des armées: Je t’ai pris d’une cabane, d’après les brebis, afin que tu fusses le Conducteur de mon peuple d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'Et j’ai été avec toi partout où tu as marché, et j’ai exterminé tous tes ennemis de devant toi, et je t’ai tait un grand nom, comme le nom des grands qui sont sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Et j’établirai un lieu à mon peuple d’Israël, je le planterai, il habitera chez soi, il ne sera plus agité, et les injustes ne les affligeront plus, comme ils ont fait auparavant,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'Savoir, depuis le jour que j’ai ordonné des juges sur mon peuple d’Israël, et que je t’ai donné du repos de tous tes ennemis, et que l’Eternel t’a fait entendre qu’il te bâtirait une maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Quand tes jours seront accomplis, et que tu te seras endormi avec tes pères, je susciterai après toi ton fils, qui sera sorti de tes entrailles, et j’affermirai son règne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Ce sera lui qui bâtira une maison à mon Nom, et j’affermirai le trône de son règne à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Je lui serai père, et il me sera fils; que s’il commet quelque iniquité, je le châtierai avec une verge d’homme, et de plaies des fils des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Mais ma gratuité ne se retirera point de lui, comme je l’ai retirée de Saül, que j’ai ôté de devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Ainsi ta maison et ton règne seront assurés pour jamais devant tes yeux, et ton trône sera affermi à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Nathan parla ainsi à David, selon toutes ces paroles, et selon toute cette vision.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Alors le Roi David entra, et se tint devant l’Eternel, et dit: Qui suis-je, ô Seigneur Eternel! et quelle est ma maison, que tu m’aies fait venir au point où je suis?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Et encore cela t’a semblé être peu de chose, ô Seigneur Eternel! car tu as même parlé de la maison de ton serviteur pour un long temps. Est-ce là la manière d’agir des hommes, ô Seigneur Eternel!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Et que te pourrait dire davantage David? car, Seigneur Eternel, tu connais ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Tu as fait toutes ces grandes choses pour l’amour de ta parole, et selon ton coeur, afin de faire connaître ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'C’est pourquoi tu t’es montré grand, ô Eternel Dieu! car il n’y en a point de tel que toi, et il n’y a point d’autre Dieu que toi, selon tout ce que nous avons entendu de nos oreilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Et qui est comme ton peuple, comme Israël, la seule nation de la terre que Dieu est venu racheter, pour en faire son peuple, tant pour s’acquérir à lui-même un grand nom, que pour vous acquérir cette grandeur, et pour faire dans ton pays devant ton peuple, que tu t’es racheté d’Egypte, des choses terribles contre les nations et contre leurs dieux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Car tu t’es assuré ton peuple d’Israël, pour être ton peuple à jamais; et toi, ô Eternel! tu leur as été Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Maintenant donc, ô Eternel Dieu! confirme pour jamais la parole que tu as prononcée touchant ton serviteur, et touchant sa maison, et fais comme tu en as parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Et que ton Nom soit magnifié à jamais, tellement qu’on dise: L’Eternel des armées est le Dieu d’Israël; et que la maison de David ton serviteur demeure stable devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Car toi, ô Eternel des armées! Dieu d’Israël! tu as fait entendre à ton serviteur, et tu lui as dit: Je te bâtirai une maison, c’est pourquoi ton serviteur a pris la hardiesse de te faire cette prière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Maintenant donc, Seigneur Eternel! tu es Dieu, tes paroles seront véritables; or tu as promis ce bien à ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Veuille donc maintenant bénir la maison de ton serviteur, afin qu’elle soit éternellement devant toi; car tu en as ainsi parlé, Seigneur Eternel! et la maison de ton serviteur sera comblée de ta bénédiction éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Après cela il arriva que David battit les Philistins, et les abaissa, et David prit Methegamma de la main des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Il battit aussi les Moabites, et les mesura au cordeau, les faisant coucher par terre; et il en mesura deux cordeaux pour les faire mourir, et un plein cordeau pour leur sauver la vie; et le pays des Moabites fut à David sous cette condition, qu’ils lui seraient sujets et tributaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'David battit aussi Hadadhézer fils de Réhob, Roi de Tsoba, comme il allait pour recouvrer ses limites sur le fleuve d’Euphrate.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'Et David lui prit mille et sept cents hommes de cheval, et vingt mille hommes de pied, et coupa les jarrets des chevaux de tous les chariots, mais il en réserva cent chariots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Car les Syriens de Damas étaient venus pour donner du secours à Hadadhézer Roi de Tsoba; et David battit vingt-deux mille Syriens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Puis David mit garnison en Syrie de Damas, et le pays de ces Syriens fut à David sous cette condition, qu’ils lui seraient sujets et tributaires; et l’Eternel gardait David partout où il allait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Et David prit les boucliers d’or qui étaient aux serviteurs de Hadadhézer, et les apporta à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Le Roi David emporta aussi une grande quantité d’airain de Bétah, et de Bérothaï, villes de Hadadhézer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Or Tohi, Roi de Hamath, apprit que David avait défait toutes les forces de Hadadhézer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'Et il envoya Joram son fils vers le Roi David, pour le saluer, et le féliciter de ce qu’il avait fait la guerre contre Hadadhézer, et de ce qu’il l’avait défait; car Hadadhézer était en guerre continuellement avec Tohi, et Joram apporta des vaisseaux d’argent, et des vaisseaux d’or, et des vaisseaux d’airain;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Lesquels David consacra à l’Eternel avec l’argent et l’or qu’il avait déjà consacrés du butin de toutes les nations qu’il s’était assujetties;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'De Syrie, de Moab, des enfants de Hammon, des Philistins, de Hamalec, et du butin de Hadadhézer, fils de Réhob, Roi de Tsoba.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'David s’acquit aussi une grande réputation de ce qu’en retournant de la défaite des Syriens, il tailla en pièces dans la vallée du sel dix-huit mille Iduméens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Et il mit garnison dans l’Idumée, il mit, dis-je, garnison dans toute l’Idumée; et tous les Iduméens furent assujettis à David; et l’Eternel gardait David partout où il allait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Ainsi David régna sur tout Israël, faisant droit et justice à tout son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Et Joab fils de Tséruja avait la charge de l’armée; et Jéhosaphat fils d’Ahilud, était commis sur les registres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Et Tsadok fils d’Ahitub, et Ahimélec fils d’Abiathar étaient les Sacrificateurs, et Séraja était le Secrétaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Et Bénaja fils de Jéhojadah était sur les Kéréthiens et les Péléthiens; et les fils de David étaient les principaux Officiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Alors David dit: Mais n’y a-t-il plus personne qui soit demeuré de reste de la maison de Saül, et je lui ferai du bien pour l’amour de Jonathan?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Or il y avait dans la maison de Saül un serviteur nommé Tsiba, lequel on appela pour le faire venir vers David. Et le Roi lui dit: Es-tu Tsiba? et il répondit: Je suis ton serviteur Tsiba.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Et le Roi dit: N’y a-t-il plus personne de la maison de Saül, et j’userai envers lui d’une grande gratuité. Et Tsiba répondit au Roi: Il y a encore un des fils de Jonathan, qui est blessé aux pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Et le Roi lui dit: Où est-il? Et Tsiba répondit au Roi: Voilà, il est en la maison de Makir fils de Hammiel, à Lodébar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Alors le Roi David envoya, et le fit amener de la maison de Makir, fils de Hammiel, de Lodébar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Et quand Méphiboseth, le fils de Jonathan fils de Saül, fut venu vers David, il s’inclina sur son visage, et se prosterna. Et David dit: Méphiboseth; et il répondit: Voici ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'Et David lui dit: Ne crains point; car certainement je te ferai du bien pour l’amour de Jonathan ton père, et je te restituerai toutes les terres de Saül ton père, et tu mangeras toujours du pain à ma table.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Et Méphiboseth se prosterna, et dit: Qui suis-je moi ton serviteur, que tu aies regardé un chien mort, tel que je suis?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Et le Roi appela Tsiba serviteur de Saül, et lui dit: J’ai donné au fils de ton maître tout ce qui appartenait à Saül, et à toute sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'C’est pourquoi laboure pour lui ces terres-là, toi et tes fils, et tes serviteurs, et recueilles-en les fruits, afin que le fils de ton maître ait du pain à manger; mais quant à Méphiboseth, fils de ton maître, il mangera toujours du pain à ma table. Or Tsiba avait quinze fils, et vingt serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Et Tsiba dit au Roi: Ton serviteur fera tout ce que le Roi mon Seigneur a commandé à son serviteur. Mais quant à Méphiboseth, (dit le Roi) il mangera à ma table, comme un des fils du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Or Méphiboseth avait un petit-fils nommé Mica; et tous ceux qui demeuraient dans la maison de Tsiba étaient des serviteurs de Méphiboseth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Et Méphiboseth demeurait à Jérusalem, parce qu’il mangeait toujours à la table du Roi; et il était boiteux des deux pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Or il arriva après cela que le Roi des enfants de Hammon mourut, et Hanun son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Et David dit: J’userai de gratuité envers Hanun, fils de Nahas, comme son père a usé de gratuité envers moi; ainsi David lui envoya ses serviteurs pour le consoler de la mort de son père. Et les serviteurs de David vinrent au pays des enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Mais les principaux d’entre les enfants de Hammon dirent à Hanun leur Seigneur: Penses-tu que ce soit pour honorer ton père, que David t’a envoyé des consolateurs? N’est-ce pas pour reconnaître exactement la ville, et pour l’épier afin de la détruire, que David a envoyé ses serviteurs vers toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Hanun donc prit les serviteurs de David, et fit raser la moitié de leur barbe, et couper la moitié de leurs habits jusqu’aux hanches; puis il les renvoya.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Et ils le firent savoir à David, lequel envoya au devant d’eux; car ces hommes étaient fort confus: et le Roi leur fit dire: Tenez- vous à Jéricho jusqu’à ce que votre barbe soit revenue, et alors vous retournerez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Or les enfants de Hammon voyant qu’ils s’étaient mis en mauvaise odeur auprès de David, envoyèrent pour lever à leurs dépens vingt mille fantassins des Syriens de Beth-réhob, et des Syriens de Tsoba, et mille hommes du Roi de Mahaca, et douze mille hommes de ceux de Tob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Ce que David ayant appris, il envoya Joab et toute l’armée, savoir les plus vaillants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Et les enfants de Hammon sortirent, et se rangèrent en bataille à l’entrée de la porte; et les Syriens de Tsoba, et de Réhob, et ceux de Tob et de Mahaca étaient à part dans la campagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Et Joab voyant que leur armée était tournée contre lui, devant et derrière, prit des hommes d’élite d’entre tous ceux d’Israël et les rangea contre les Syriens;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Et il donna la conduite du reste du peuple à Abisaï son frère, qui le rangea contre les enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Et Joab lui dit: Si les Syriens sont plus forts que moi, tu me viendras délivrer; et si les enfants de Hammon sont plus forts que toi, j’irai aussi pour te délivrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Sois vaillant, et portons-nous vaillamment pour notre peuple, et pour les villes de notre Dieu; et que l’Eternel fasse ce qu’il lui semblera bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Alors Joab et le peuple qui était avec lui s’approchèrent pour donner bataille aux Syriens; et les Syriens s’enfuirent de devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Et les enfants de Hammon voyant que les Syriens avaient pris la fuite, s’enfuirent aussi de devant Abisaï, et entrèrent dans la ville; et Joab s’en retourna de la guerre contre les enfants de Hammon, et vint à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Mais les Syriens voyant qu’ils avaient été battus par ceux d’Israël, se rallièrent ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Et Hadadhézer envoya, et fit venir des Syriens de delà le fleuve, lesquels vinrent à Hélam, et Sobac, Chef de l’armée de Hadadhézer, les conduisait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Ce qui ayant été rapporté à David, il assembla tout Israël, et passa le Jourdain, et vint à Hélam; et les Syriens se rangèrent en bataille contre David, et combattirent contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Mais les Syriens s’enfuirent de devant Israël; et David défit sept cents chariots des Syriens, et quarante mille hommes de cheval; il frappa aussi Sobac Chef de leur armée, qui mourut là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Et quand tous les Rois serviteurs de Hadadhézer eurent vu qu’ils avaient été battus par ceux d’Israël, ils firent la paix avec Israël, et leur furent assujettis; et les Syriens craignirent de plus secourir les enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Or il arriva un an après, lorsque les Rois sortent à la guerre, que David envoya Joab, et avec lui ses serviteurs, et tout Israël, et ils détruisirent les enfants de Hammon, et assiégèrent Rabba; mais David demeura à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Et sur le soir il arriva que David se leva de dessus son lit, et comme il se promenait sur la plateforme de l’hôtel Royal, il vit de dessus cette plateforme une femme qui se lavait, et cette femme-là était fort belle à voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Et David envoya s’informer de cette femme-là, et on lui dit: N’est-ce pas là Bath-sebah fille d’Eliham, femme d’Urie le Héthien?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Et David envoya des messagers, et l’enleva; et étant venue vers lui, il coucha avec elle; car elle était nettoyée de sa souillure; puis elle s’en retourna en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Et cette femme conçut; et elle envoya le faire savoir à David, en disant: Je suis enceinte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Alors David envoya dire à Joab: Envoie-moi Urie le Héthien; et Joab envoya Urie à David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Et Urie vint à lui; et David lui demanda comment se portait Joab, et le peuple, et comment il en allait de la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Puis David dit à Urie: Descends en ta maison, et lave tes pieds. Et Urie sortit de la maison du Roi, et on porta après lui un présent Royal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Mais Urie dormit à la porte de la maison du Roi, avec tous les serviteurs de son Seigneur, et ne descendit point en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Et on le rapporta à David, et on lui dit: Urie n’est point descendu en sa maison. Et David dit à Urie: Ne viens-tu pas de voyage? Pourquoi n’es-tu pas descendu en ta maison?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Et Urie répondit à David: L’Arche, et Israël, et Juda logent sous des tentes; Monseigneur Joab aussi, et les serviteurs de mon Seigneur campent aux champs; et moi entrerais-je dans ma maison pour manger et boire, et pour coucher avec ma femme? Tu es vivant, et ton âme vit, si je fais une telle chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Et David dit à Urie: Demeure ici encore aujourd’hui, et demain je te renverrai. Urie donc demeura encore ce jour-là et le lendemain à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Puis David l’appela, et il mangea et but devant lui, et David l’enivra; et néanmoins il sortit au soir pour dormir dans son lit avec tous les serviteurs de son Seigneur, et ne descendit point en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Et le lendemain au matin David écrivit des lettres à Joab, et les envoya par les mains d’Urie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Et il écrivit ces lettres en ces termes: Mettez Urie à l’endroit où sera le plus fort de la bataille, et retirez-vous d’auprès de lui, afin qu’il soit frappé, et qu’il meure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Après donc que Joab eut considéré la ville, il mit Urie à l’endroit où il savait que seraient les plus vaillants hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Et ceux de la ville sortirent et combattirent contre Joab, et quelques-uns du peuple qui étaient des serviteurs de David moururent; Urie le Héthien mourut aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Alors Joab envoya à David pour lui faire savoir tout ce qui était arrivé dans ce combat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Et il commanda au messager, disant: Quand tu auras achevé de parler au Roi de tout ce qui est arrivé au combat,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'S’il arrive que le Roi se mette en colère et qu’il te dise: Pourquoi vous êtes-vous approchés de la ville pour combattre, ne savez-vous pas bien qu’on jette toujours quelque chose de dessus la muraille?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Qu’est-ce qui tua Abimélec fils de Jérubbeseth? ne fut-ce pas une pièce de meule qu’une femme jeta sur lui de dessus la muraille, dont il mourut à Tébets? Pourquoi vous êtes-vous approchés de la muraille? Tu lui diras: Ton serviteur Urie le Héthien y est mort aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Ainsi le messager partit, et étant arrivé il fit savoir à David tout ce pourquoi Joab l’avait envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Et le messager dit à David: Ils ont été plus forts que nous, et sont sortis contre nous aux champs, mais nous les avons repoussés jusqu’à l’entrée de la porte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Et les archers ont tiré contre tes serviteurs de dessus la muraille, et quelques-uns des serviteurs du Roi sont morts; ton serviteur Urie le Héthien est mort aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Et David dit au messager: Tu diras ainsi à Joab: Ne t’inquiète point de cela; car l’épée emporte autant l’un que l’autre; redouble le combat contre la ville, et détruis-la; et toi donne-lui courage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Et la femme d’Urie apprit qu’Urie son mari était mort, et elle fit le deuil de son mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Et après que le deuil fut passé, David envoya, et la retira dans sa maison, et elle lui fut pour femme, et lui enfanta un fils; mais ce que David avait fait déplut à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Et l’Eternel envoya Nathan à David, lequel vint à lui, et lui dit: Il y avait deux hommes dans une ville, l’un riche, et l’autre pauvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Le riche avait du gros et du menu bétail en fort grande abondance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Mais le pauvre n’avait rien du tout qu’une petite brebis, qu’il avait achetée et nourrie, et qui était crue chez lui et avec ses enfants, mangeant de ses morceaux, buvant dans sa coupe, et dormant en son sein, et elle lui était comme fille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Mais un homme qui voyageait étant venu chez cet homme riche, ce riche a épargné de prendre son gros et son menu bétail, pour en apprêter au voyageur qui était entré chez lui, et il a pris la brebis de cet homme pauvre, et l’a apprêtée à cet homme qui était entré chez lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Alors la colère de David s’enflamma fort contre cet homme-là; et il dit à Nathan: L’Eternel est vivant, que l’homme qui a fait cela est digne de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Et parce qu’il a fait cela, et qu’il n’a point épargné cette brebis, pour une brebis il en rendra quatre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Alors Nathan dit à David: Tu es cet homme-là. Ainsi a dit l’Eternel le Dieu d’Israël: Je t’ai oint pour être Roi sur Israël, et je t’ai délivré de la main de Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Même je t’ai donné la maison de ton Seigneur, et les femmes de ton Seigneur en ton sein, et je t’ai donné la maison d’Israël, et de Juda; et si c’est encore peu, je t’eusse ajouté telle et telle chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Pourquoi donc as-tu méprisé la parole de l’Eternel, en faisant ce qui lui déplaît? Tu as frappé avec l’épée Urie le Héthien, tu as enlevé sa femme afin qu’elle fût ta femme, et tu l’as tué par l’épée des enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Maintenant donc l’épée ne partira jamais de ta maison, parce que tu m’as méprisé, et que tu as enlevé la femme d’Urie le Héthien, afin qu’elle fût ta femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Ainsi a dit l’Eternel: Voici, je m’en vais faire sortir de ta propre maison un mal contre toi, j’enlèverai tes femmes devant tes yeux, je les donnerai à un homme de ta maison, et il dormira avec tes femmes à la vue de ce soleil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Car tu l’as fait en secret, mais moi, je le ferai en la présence de tout Israël, et devant le soleil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Alors David dit à Nathan: J’ai péché contre l’Eternel; et Nathan dit à David: Aussi l’Eternel a fait passer ton péché; tu ne mourras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Toutefois parce qu’en cela tu as donné occasion aux ennemis de l’Eternel de le blasphémer, à cause de cela le fils qui t’est né mourra certainement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Après cela Nathan s’en retourna en sa maison; et l’Eternel frappa l’enfant que la femme d’Urie avait enfanté à David, qui en fut fort affligé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Et David pria Dieu pour l’enfant, il jeûna et il passa la nuit couché sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Et les Anciens de sa maison se levèrent et vinrent vers lui, pour le faire lever de terre, mais il ne voulut point se lever, et il ne mangea d’aucune chose avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Et il arriva que l’enfant mourut le septième jour, et les serviteurs de David craignaient de lui apprendre que l’enfant était mort; car ils disaient: Voici, quand l’enfant était en vie, nous lui avons parlé, et il n’a point voulu écouter notre voix; comment donc lui dirions-nous que l’enfant est mort, afin qu’il s’afflige davantage?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Et David aperçut que ses serviteurs parlaient bas, et il comprit que l’enfant était mort; et David dit à ses serviteurs: L’enfant n’est-il pas mort? Ils répondirent: Il est mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Alors David se leva de terre, se lava, s’oignit, et changea d’habits; et il entra dans la maison de l’Eternel, et se prosterna; puis il revint en sa maison, et ayant demandé à manger, on mit de la viande devant lui, et il mangea.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Et ses serviteurs lui dirent: Qu’est-ce que tu fais? tu as jeûné et pleuré pour l’amour de l’enfant, lorsqu’il était encore en vie, et après que l’enfant est mort, tu t’es levé, et tu as mangé de la viande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Et il dit: Quand l’enfant était encore en vie, j’ai jeûné, et pleuré; car je disais: Qui sait si l’Eternel aura pitié de moi, et si l’enfant ne vivra point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Mais maintenant qu’il est mort, pourquoi jeûnerais-je? pourrais- je le faire revenir encore? Je m’en vais vers lui, et lui ne reviendra pas vers moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Et David consola sa femme Bath-sebah, et vint vers elle, et coucha avec elle, et elle lui enfanta un fils, qu’il nomma Salomon; et l’Eternel l’aima.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Ce qu’il envoya dire par le ministère de Nathan le Prophète, qui lui imposa le nom de Jédidja, à cause de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Or Joab avait combattu contre Rabba, qui appartenait aux enfants de Hammon, et avait pris la ville Royale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Et Joab avait envoyé des messagers vers David, pour lui dire: J’ai battu Rabba, et j’ai pris la ville des eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'C’est pourquoi maintenant assemble le reste du peuple, et campe- toi contre la ville, et la prends; de peur que si je la prenais, on ne réclamât mon nom sur elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'David donc assembla tout le peuple, et marcha contre Rabba; il la battit, et la prit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Et il prit la couronne de dessus la tête de leur Roi, laquelle pesait un talent d’or, et il y avait des pierres précieuses; et on la mit sur la tête de David, qui emmena un fort grand butin de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Il emmena aussi le peuple qui y était, et le mit sous des scies, et sous des herses de fer, et sous des haches de fer, et il les fit passer par un fourneau où l’on cuit les briques; il en fit ainsi à toutes les villes des enfants de Hammon. Puis David s’en retourna avec tout le peuple à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Or il arriva après cela qu’Absalom, fils de David, ayant une soeur qui était belle, et qui se nommait Tamar, Amnon fils de David, l’aima.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Et il fut si tourmenté de cette passion, qu’il tomba malade pour l’amour de Tamar sa sœur, car elle était vierge; et parce qu’il semblait trop difficile à Amnon de rien obtenir d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Or Amnon avait un intime ami nommé Jonadab, fils de Simha frère de David; et Jonadab était un homme fort rusé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Et il dit à Amnon: Fils du Roi, pourquoi deviens-tu ainsi exténué de jour en jour? ne me le déclareras-tu pas? Amnon lui dit: J’aime Tamar soeur de mon frère Absalom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Alors Jonadab lui dit: Couche-toi dans ton lit, et fais le malade; et quand ton père te viendra voir, tu lui diras: Je te prie que ma soeur Tamar vienne, afin qu’elle me fasse manger, en apprêtant devant moi quelque chose d’appétit, et que voyant ce qu’elle aura apprêté, je le mange de sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Amnon donc se coucha, et fit le malade; et quand le Roi le vint voir, il lui dit: Je te prie que ma soeur Tamar vienne et fasse deux beignets devant moi, et que je les mange de sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'David donc envoya vers Tamar en la maison et lui fit dire: Va- t’en maintenant en la maison de ton frère Amnon, et apprête-lui quelque chose d’appétit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Et Tamar s’en alla en la maison de son frère Amnon, qui était couché; et elle prit de la pâte, et la pétrit, et en fit devant lui des beignets, et les cuisit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Puis elle prit la poêle, et les versa devant lui, mais Amnon refusa d’en manger; et dit: Faites retirer tous ceux qui sont auprès de moi: et chacun se retira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Alors Amnon dit à Tamar: Apporte-moi cette viande dans le cabinet, et que j’en mange de ta main. Et Tamar prit les beignets qu’elle avait faits, et les apporta à Amnon son frère dans le cabinet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Et elle les lui présenta, afin qu’il en mangeât; mais il se saisit d’elle et lui dit: Viens, couche avec moi, ma soeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Et elle lui répondit: Non, mon frère, ne me viole point; car cela ne se fait point en Israël; ne fais point cette infamie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Et moi, que deviendrais-je avec mon opprobre? et toi, tu passerais pour un insensé en Israël. Maintenant donc parles-en, je te prie, au Roi, et il n’empêchera point que tu ne m’aies pour femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Mais il ne voulut point l’écouter; et il fut plus fort qu’elle, et la viola, et coucha avec elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Après cela, Amnon la haït d’une grande haine, en sorte que la haine qu’il lui portait, était plus grande que l’amour qu’il avait eu pour elle; ainsi Amnon lui dit: Lève-toi, va-t’en.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Et elle lui répondit: Tu n’as aucun sujet de me faire ce mal, que de me chasser; ce mal est plus grand que l’autre que tu m’as fait; mais il ne voulut point l’écouter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Il appela donc le garçon qui le servait, et lui dit: Qu’on chasse maintenant celle-ci d’auprès de moi, qu’on la mette dehors, et qu’on ferme la porte après elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Or elle était habillée d’une robe bigarrée; car les filles du Roi, qui étaient encore vierges, étaient ainsi habillées. Celui donc qui le servait la mit dehors, et ferma la porte après elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Alors Tamar prit de la cendre sur sa tête, et déchira la robe bigarrée qu’elle avait sur elle, et mit la main sur sa tête, et s’en allait en criant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Et son frère Absalom lui dit: Ton frère Amnon n’a-t-il pas été avec toi? Mais maintenant, ma soeur, tais-toi, il est ton frère; ne prends point ceci à coeur. Ainsi Tamar demeura toute désolée dans la maison d’Absalom son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Quand le Roi David eut appris toutes ces choses, il fut fort irrité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Or Absalom ne parlait ni en bien ni en mal à Amnon, parce qu’Absalom haïssait Amnon, à cause qu’il avait violé Tamar sa soeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Et il arriva au bout de deux ans entiers, qu’Absalom ayant les tondeurs à Bahal-hatsor, qui était près d’Ephraïm, il invita tous les fils du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Et Absalom vint vers le Roi, et lui dit: Voici, ton serviteur a maintenant les tondeurs; je te prie donc que le Roi et ses serviteurs viennent avec ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Mais le Roi dit à Absalom: Non, mon fils, je te prie que nous n’y allions point tous, afin que nous ne te soyons point à charge; et quoiqu’il le pressât fort, cependant il n’y voulut point aller; mais il le bénit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Et Absalom dit: Si tu ne viens point, je te prie que mon frère Amnon vienne avec nous. Et le Roi lui répondit: Pourquoi irait-il avec toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Et Absalom le pressa tant, qu’il laissa aller Amnon, et tous les fils du Roi avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Or Absalom avait commandé à ses serviteurs, en disant: Prenez bien garde, je vous prie, quand le coeur d’Amnon sera gai de vin, et que je vous dirai: Frappez Amnon, tuez-le; ne craignez point; n’est-ce pas moi qui vous l’aurai commandé? Fortifiez-vous, et portez-vous en vaillants hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Et les serviteurs d’Absalom firent à Amnon comme Absalom avait commandé, puis tous les fils du Roi se levèrent, et montèrent chacun sur sa mule, et s’enfuirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Et il arriva qu’étant encore en chemin, le bruit vint à David qu’Absalom avait tué tous les fils du Roi, et qu’il n’en était pas resté un seul d’entr’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Alors le Roi se leva, et déchira ses vêtements, et se coucha par terre; tous ses serviteurs aussi étaient là avec leurs vêtements déchirés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Et Jonadab fils de Simha, frère de David, prit la parole, et dit: Que mon Seigneur ne dise point qu’on a tué tous les jeunes hommes fils du Roi, car Amnon seul est mort; parce que ce qu’Absalom s’était proposé dès le jour qu’Amnon viola Tamar sa soeur, a été exécuté selon son commandement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Maintenant donc que le Roi mon Seigneur ne mette point ceci dans son coeur, en disant que tous les fils du Roi sont morts; car Amnon seul est mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Or Absalom s’enfuit, mais celui qui était en sentinelle levant les yeux, regarda; et voici, un grand peuple venait par le chemin de derrière lui, à côté de la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Et Jonadab dit au Roi: Voici les fils du Roi qui viennent; la chose est arrivée comme ton serviteur a dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Or aussitôt qu’il eut achevé de parler, voici on vit arriver les fils du Roi, qui élevèrent leur voix, et pleurèrent; le Roi aussi et tous ses serviteurs pleurèrent beaucoup.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Mais Absalom s’enfuit, et se retira vers Talmaï, fils de Hammihud Roi de Guesur: et David pleurait tous les jours sur son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Quand Absalom se fut enfui, et qu’il fut venu à Guesur, il demeura là trois ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Puis il prit envie au Roi David d’aller vers Absalom, parce qu’il était consolé de la mort d’Amnon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Alors Joab, fils de Tséruja, connaissant que le coeur du Roi était pour Absalom,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Envoya à Tékoah, et fit venir de là une femme sage, à laquelle il dit: Je te prie, fais semblant de lamenter, et te vêts maintenant des habits de deuil, et ne t’oins point d’huile, mais sois comme une femme qui depuis longtemps se lamente pour un mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Et entre vers le Roi, et tiens lui ces discours; car Joab lui mit en la bouche ce qu’elle devait dire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'La femme Tékohite donc parla au Roi, et s’inclina sur son visage en terre, et se prosterna, et dit: Ô Roi! aide-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Et le Roi lui dit: Qu’as-tu? Et elle répondit: Certes je suis une femme veuve, et mon mari est mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Or ta servante avait deux fils, qui se sont querellés dans les champs, et il n’y avait personne qui les séparât; ainsi l’un a frappé l’autre, et l’a tué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Et voici, toute la famille s’est élevée contre ta servante, en disant: Donne-nous celui qui a frappé son frère, afin que nous le mettions à mort, à cause de la vie de son frère qu’il a tué; et que nous exterminions même l’héritier; et ils veulent ainsi éteindre le charbon vif qui m’est resté, afin qu’ils ne laissent point de nom à mon mari, et qu’ils ne me laissent aucun de reste sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Le Roi dit à la femme: Va-t’en en ta maison, et je donnerai mes ordres en ta faveur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Alors la femme Tékohite dit au Roi: Mon Seigneur et mon Roi! que l’iniquité soit sur moi et sur la maison de mon père, et que le Roi et son trône en soient innocents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Et le Roi répondit: Amène-moi celui qui parlera contre toi, et jamais il ne lui arrivera de te toucher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Et elle dit: Je te prie que le Roi se souvienne de l’Eternel son Dieu, afin qu’il ne laisse point augmenter le nombre des garants du sang pour perdre mon fils, et qu’on ne l’extermine point. Et il répondit: L’Eternel est vivant, si un seul des cheveux de ton fils tombe à terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Et la femme dit: Je te prie que ta servante dise un mot au Roi mon Seigneur; et il répondit: Parle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Et la femme dit: Mais pourquoi as-tu pensé une chose comme celle- ci contre le peuple de Dieu? car le Roi en tenant ce discours ne se condamne-t-il point comme étant dans le même cas, en ce qu’il ne fait point retourner celui qu’il a banni?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Car certainement nous mourrons, et nous sommes semblables aux eaux qui s’écoulent sur la terre, lesquelles on ne ramasse point. Or Dieu ne lui a point ôté la vie, mais il a trouvé un moyen pour ne rejeter point loin de lui celui qui a été rejeté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Et maintenant je suis venue pour tenir ce discours au Roi mon Seigneur, parce que le peuple m’a épouvantée; et ta servante a dit: Je parlerai maintenant au Roi, peut-être que le Roi fera ce que sa servante lui dira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Si donc le Roi écoute sa servante pour la délivrer de la main de celui qui veut nous exterminer de l’héritage de Dieu, moi et mon fils;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Ta servante disait: Que maintenant la parole du Roi mon Seigneur nous apporte du repos; car le Roi mon Seigneur est comme un Ange de Dieu, pour connaître le bien et le mal; que donc l’Eternel ton Dieu soit avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Et le Roi répondit, et dit à la femme: Je te prie ne me cache rien de ce que je te vais demander. Et la femme dit: Je prie que le Roi mon Seigneur parle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Et le Roi dit: N’est-ce pas Joab qui te fait faire tout ceci? Et la femme répondit, et dit: Ton âme vit, ô mon Seigneur! qu’on ne saurait biaiser ni à droite ni à gauche sur tout ce que le Roi mon Seigneur a dit, puisqu’il est vrai que ton serviteur Joab me l’a commandé, et a lui-même mis dans la bouche de ta servante toutes ces paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'C’est ton serviteur Joab qui a fait que j’ai ainsi tourné ce discours; mais mon Seigneur est sage comme un Ange de Dieu, pour savoir tout ce qui se passe sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Alors le Roi dit à Joab: Voici maintenant; c’est toi qui as conduit cette affaire; va-t’en donc, et fais revenir le jeune homme Absalom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Et Joab s’inclina sur son visage en terre, et se prosterna, et bénit le Roi. Et Joab dit: Aujourd’hui ton serviteur a connu qu’il a trouvé grâce devant toi, ô Roi mon Seigneur! car le Roi a fait ce que son serviteur lui a dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Joab donc se leva et s’en alla à Guesur, et ramena Absalom à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Et le Roi dit: Qu’il se retire en sa maison, et qu’il ne voie point ma face; et ainsi Absalom se retira en sa maison, et ne vit point la face du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Or il n’y avait point d’homme en tout Israël qui fût si beau qu’Absalom, pour faire estime de sa beauté; depuis la plante des pieds jusqu’au sommet de la tête il n’y avait point en lui de défaut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Et quand il faisait couper ses cheveux, or il arrivait tous les ans qu’il les faisait couper, parce qu’ils lui étaient à charge, il pesait les cheveux de sa tête, qui pesaient deux cents sicles au poids du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Et il naquit à Absalom trois fils, et une fille, qui avait nom Tamar, et qui était une très-belle femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Et Absalom demeura deux ans entiers à Jérusalem sans voir la face du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'C’est pourquoi Absalom manda à Joab qu’il vînt vers lui, pour l’envoyer vers le Roi; mais il ne voulut point aller vers lui. Il le manda encore pour la seconde fois; mais il ne voulut point venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Alors Absalom dit à ses serviteurs: Vous voyez là le champ de Joab qui est auprès du mien, il y a de l’orge, allez et mettez-y le feu. Et les serviteurs d’Absalom mirent le feu à ce champ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Alors Joab se leva et vint vers Absalom dans sa maison; et lui dit: Pourquoi tes serviteurs ont-ils mis le feu à mon champ?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Et Absalom répondit à Joab: Voici, je t’ai envoyé dire: Viens ici, et je t’enverrai vers le Roi, et tu lui diras: Pourquoi suis-je venu de Guesur? il vaudrait mieux que j’y fusse encore. Maintenant donc que je voie la face du Roi; et s’il y a de l’iniquité en moi, qu’il me fasse mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Joab vint donc vers le Roi, et lui fit ce rapport; et le Roi appela Absalom, lequel vint vers lui, et se prosterna le visage en terre devant le Roi; et le Roi baisa Absalom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Or il arriva après cela qu’Absalom se pourvut de chariots, et de chevaux; et il avait cinquante archers qui marchaient devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Et Absalom se levait le matin, et se tenait à côté du chemin qui allait vers la porte; et s’il y avait quelqu’un qui eût quelque affaire, pour laquelle il fallût aller vers le Roi afin de demander justice, Absalom l’appelait, et lui disait: De quelle ville es-tu? et il répondait: Ton serviteur est d’une telle Tribu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Et Absalom lui disait: Regarde, ta cause est bonne et droite; mais tu n’as personne qui ait ordre du Roi de t’entendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Absalom disait encore: Oh! que ne m’établit-on pour juge dans le pays! et tout homme qui aurait des procès, et qui aurait droit, viendrait vers moi, et je lui ferais justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Il arrivait aussi que quand quelqu’un s’approchait de lui pour se prosterner devant lui, il lui tendait sa main, et le prenait, et le baisait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Absalom en faisait ainsi à tous ceux d’Israël qui venaient vers le Roi pour avoir justice; et Absalom gagnait les coeurs de ceux d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Et il arriva au bout de quarante ans, qu’Absalom dit au Roi: Je te prie que je m’en aille à Hébron pour m’acquitter de mon voeu que j’ai voué à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Car quand ton serviteur demeurait à Guesur en Syrie, il fit un voeu, en disant: Si l’Eternel me ramène pour être en repos à Jérusalem, j’en témoignerai ma reconnaissance à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Et le Roi lui répondit: Va en paix. Il se leva donc et s’en alla à Hébron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Or Absalom avait envoyé dans toutes les Tribus d’Israël des gens apostés, pour dire: Aussitôt que vous aurez entendu le son de la trompette, dites: Absalom est établi Roi à Hébron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Et deux cents hommes de Jérusalem qui avaient été invités, s’en allèrent avec Absalom, et ils y allaient dans la simplicité de leur cœur, ne sachant rien de cette affaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Absalom envoya aussi appeler, quand il offrait ses sacrifices, Achithophel Guilonite, conseiller de David, de sa ville de Guilo; et la conjuration devint plus puissante, parce que le peuple allait en augmentant avec Absalom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Alors il vint à David un messager, qui lui dit: Tous ceux d’Israël ont leur coeur tourné vers Absalom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Et David dit à tous ses serviteurs qui étaient avec lui à Jérusalem: Levez-vous, et fuyons; car nous ne saurions échapper devant Absalom. Hâtez-vous d’aller, de peur qu’il ne se hâte, qu’il ne nous atteigne, qu’il ne fasse venir le mal sur nous, et qu’il ne frappe la ville au tranchant de l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Et les serviteurs du Roi répondirent au Roi: Tes serviteurs sont prêts à faire tout ce que le Roi notre Seigneur trouvera bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Le Roi donc sortit, et toute sa maison le suivait; mais le Roi laissa dix femmes, qui étaient ses concubines, pour garder la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Le Roi donc sortit, et tout le peuple le suivait; et ils s’arrêtèrent en un lieu éloigné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Et tous ses serviteurs marchaient à côté de lui; et tous les Kéréthiens, et tous les Péléthiens, et tous les Guittiens, qui étaient six cents hommes venus de Gath, pour être à sa suite, marchaient devant le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Mais le Roi dit à Ittaï, Guittien: Pourquoi viendrais-tu aussi avec nous? retourne-t’en, et demeure avec le Roi; car tu es étranger, et même tu vas retourner bientôt en ton lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Tu ne fais que de venir; et te ferais-je aujourd’hui aller errant çà et là avec nous? car quant à moi, je m’en vais où je pourrai; retourne-t’en et remène tes frères; que la gratuité et la vérité soient avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Mais Ittaï répondit au Roi, en disant: L’Eternel est vivant, et le Roi mon Seigneur vit, qu’en quelque lieu où le Roi mon Seigneur sera, soit à la mort, soit à la vie, ton serviteur y sera aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'David donc dit à Ittaï: Viens, et marche. Alors Ittaï Guittien marcha avec tous ses gens, et tous ses petits enfants qui étaient avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Et tout le pays pleurait à grands cris, et tout le peuple passait plus avant; puis le Roi passa le torrent de Cédron, et tout le peuple passa vis-à-vis du chemin tirant vers le désert;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Là aussi était Tsadok avec tous les Lévites qui portaient l’Arche de l’alliance de Dieu, et ils posèrent là l’Arche de Dieu; et Abiathar monta pendant que tout le peuple achevait de sortir de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Et le Roi dit à Tsadok: Reporte l’Arche de Dieu dans la ville; si j’ai trouvé grâce devant l’Eternel il me ramènera, et me la fera voir, avec son Tabernacle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Que s’il me dit ainsi: Je ne prends point de plaisir en toi; me voici, qu’il fasse de moi ce qu’il lui semblera bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Le Roi dit encore au Sacrificateur Tsadok: N’es-tu pas le Voyant? retourne-t’en en paix à la ville, et Ahimahats ton fils, et Jonathan fils d’Abiathar, vos deux fils avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Regardez, je m’en vais demeurer dans les campagnes du désert, jusqu’à ce qu’on vienne m’apporter des nouvelles de votre part.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Tsadok donc et Abiathar reportèrent l’Arche de Dieu à Jérusalem, et demeurèrent là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Et David montait par la montée des oliviers, et en montant il pleurait, et il avait la tête couverte, et marchait nu-pieds; tout le peuple aussi qui était avec lui, montait chacun ayant sa tête couverte, et en montant ils pleuraient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Alors on fit ce rapport à David, et on lui dit: Achithophel est parmi ceux qui ont conjuré avec Absalom. Et David dit: Je te prie, ô Eternel! assoli le conseil d’Achithophel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Et il arriva que quand David fut venu jusqu’au sommet de la montagne, là où il se prosterna devant Dieu, voici Cusaï Arkite, vint au devant de lui, ayant ses habits déchirés, et de la terre sur sa tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Et David lui dit: Tu me seras à charge, si tu passes plus avant avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Mais si tu t’en retournes à la ville, et si tu dis à Absalom: Ô Roi! je serai ton serviteur, et comme j’ai été dès longtemps serviteur de ton père, je serai maintenant ton serviteur, tu dissiperas le conseil d’Achithophel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Et les Sacrificateurs Tsadok et Abiathar ne seront-ils pas là avec toi? de sorte que tout ce que tu auras entendu de la maison du Roi, tu le rapporteras aux Sacrificateurs Tsadok et Abiathar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Voici leurs deux fils, Ahimahats fils de Tsadok, et Jonathan fils d’Abiathar, sont là avec eux; vous m’apprendrez par eux tout ce que vous aurez entendu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Ainsi Cusaï l’intime ami de David retourna dans la ville, et Absalom vint à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Quand David eut passé un peu au delà du sommet de la montagne, voici Tsiba, serviteur de Méphiboseth, vint au devant de lui, avec deux ânes bâtés, sur lesquels il y avait deux cents pains, et cent paquets de raisins secs, et cent autres paquets de fruits d’Eté, et un baril de vin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Et le Roi dit à Tsiba: Que veux-tu faire de cela? Et Tsiba répondit: Les ânes sont pour la famille du Roi, afin qu’ils montent dessus; et le pain, et les autres fruits d’Eté à manger, sont pour les jeunes gens, et il y a du vin pour boire, afin que ceux qui se trouveront fatigués au désert, en boivent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Et le Roi lui dit: Mais où est le fils de ton Maître? Et Tsiba répondit au Roi: Voilà, il est demeuré à Jérusalem; car il a dit: Aujourd’hui la maison d’Israël me rendra le Royaume de mon père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Alors le Roi dit à Tsiba: Voilà, tout ce qui est à Méphiboseth, est à toi. Et Tsiba dit: Je me prosterne devant toi, je trouve grâce devant toi, ô Roi mon Seigneur!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Et le Roi David vint jusqu’à Bahurim; et voici il sortit de là un homme de la famille de la maison de Saül, nommé Simhi fils de Guéra, qui étant sorti avec impétuosité, faisait des imprécations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'Et jetait des pierres contre David, et contre tous les serviteurs du Roi David, et tout le peuple, et tous les hommes forts étaient à la droite et à la gauche du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Or Simhi parlait ainsi en le maudissant: Sors, sors, homme de sang, et méchant homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'L’Eternel a fait retomber sur toi tout le sang de la maison de Saül, en la place duquel tu as régné, et l’Eternel a mis le royaume entre les mains de ton fils Absalom, et voilà, tu souffres le mal que tu as fait, parce que tu es un homme de sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Alors Abisaï, fils de Tséruja, dit au Roi: Comment ce chien mort maudit-il le Roi mon Seigneur? que je passe, je te prie, et que je lui ôte la tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Mais le Roi répondit: Qu’ai-je à faire avec vous, fils de Tséruja? Qu’il me maudisse; car l’Eternel lui a dit: Maudis David; qui donc lui dira: Pourquoi l’as-tu fait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'David dit aussi à Abisaï, et à tous ses serviteurs: Voici, mon propre fils qui est sorti de mes entrailles, cherche ma vie, et combien plus maintenant un fils de Jémini? Laissez-le, et qu’il me maudisse; car l’Eternel le lui a dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Peut-être l’Eternel regardera mon affliction, l’Eternel me rendra le bien au lieu des malédictions que celui-ci me donne aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'David donc avec ses gens continuait son chemin, et Simhi allait à côté de la montagne, vis-à-vis de lui, continuant à maudire, jetant des pierres contre lui, et de la poudre en l’air.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Ainsi le Roi David, et tout le peuple qui était avec lui, étant fatigués, vinrent, et se rafraîchirent là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Or Absalom et tout le peuple, savoir les hommes d’Israël, entrèrent dans Jérusalem; et Achithophel était avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Or il arriva que quand Cusaï Arkite, l’intime ami de David, fut venu vers Absalom, il dit à Absalom: Vive le Roi, vive le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Et Absalom dit à Cusaï: Est-ce donc là l’affection que tu as pour ton intime ami? pourquoi n’es-tu point allé avec ton intime ami?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Mais Cusaï répondit à Absalom: Non; mais je serai à celui que l’Eternel a choisi, et que ce peuple, et tous les hommes d’Israël ont aussi choisi, et je demeurerai avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Et de plus, qui servirai-je? ne sera-ce pas son fils? Je serai ton serviteur, comme j’ai été le serviteur de ton père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Alors Absalom dit à Achithophel: Consultez ensemble pour voir ce que nous avons à faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Et Achithophel dit à Absalom: Va vers les concubines de ton père, qu’il a laissées pour garder la maison, afin que quand tout Israël saura que tu te seras mis en mauvaise odeur auprès de ton père, les mains de tous ceux qui sont avec toi, soient fortifiées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'On dressa donc un pavillon à Absalom sur le toit de la maison: et Absalom vint vers les concubines de son père, à la vue de tout Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Or le conseil que donnait Achithophel en ce temps-là était autant estimé, que si quelqu’un eût demandé le conseil de Dieu. C’est ainsi qu’on considérait tous les conseils qu’Achithophel donnait, tant à David qu’à Absalom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Après cela Achithophel dit à Absalom: Je choisirai maintenant douze mille hommes, et je me lèverai, et je poursuivrai David cette nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'Et je me jetterai sur lui; il est fatigué, et ses mains sont affaiblies, et je l’épouvanterai, tellement que tout le peuple qui est avec lui, s’enfuira, et je frapperai le Roi seulement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'Et je ferai que tout le peuple retournera à toi; car l’homme que tu cherches vaut autant que si tous retournaient à toi; ainsi tout le peuple sera sain et sauf.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Cet avis fut trouvé bon par Absalom, et par tous les Anciens d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Mais Absalom dit: Qu’on appelle maintenant aussi Cusaï Arkite, et que nous entendions aussi son avis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Or quand Cusaï fut venu vers Absalom, Absalom lui dit: Achithophel a donné un tel avis; ferons-nous ce qu’il a dit, ou non? Parle, toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Alors Cusaï dit à Absalom: Le conseil qu’Achithophel a donné maintenant, n’est pas bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Cusaï dit encore: Tu connais ton père et ses gens, que se sont des gens forts, et qui ont le coeur outré, comme une ourse des champs à qui on a pris ses petits; et ton père est un homme de guerre, qui ne passera point la nuit avec le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Voici, il est maintenant caché dans quelque fosse, ou dans quelque autre lieu; s’il arrive qu’au commencement on soit battu par eux, quiconque en entendra parler, l’ayant su, dira: Le peuple qui suit Absalom a été défait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Alors le plus vaillant, celui-là même qui avait le coeur comme un lion, se fondra; car tout Israël sait que ton père est un homme de coeur, et que ceux qui sont avec lui sont vaillants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Mais je suis d’avis qu’en diligence on assemble vers toi tout Israël, depuis Dan jusqu’à Beersébah, lequel sera en grand nombre comme le sable qui est sur le bord de la mer, et que toi-même en personne marches en bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Alors nous viendrons à lui en quelque lieu que nous le trouvions, et nous nous jetterons sur lui, comme la rosée tombe sur la terre, et il ne lui restera aucun de tous les hommes qui sont avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Que s’il se retire en quelque ville, tout Israël portera des cordes vers cette ville-là, et nous la traînerons jusques dans le torrent, en sorte qu’il ne s’en trouvera pas même une petite pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Alors Absalom et tous les hommes d’Israël dirent: Le conseil de Cusaï Arkite est meilleur que le conseil d’Achithophel; car l’Eternel avait décrété que le conseil d’Achithophel, qui était le plus utile pour Absalom, fût dissipé, afin de faire venir le mal sur Absalom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Alors Cusaï dit aux Sacrificateurs Tsadok et Abiathar: Achithophel a donné tel et tel conseil à Absalom, et aux Anciens d’Israël, mais moi j’ai donné tel et tel conseil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Maintenant donc envoyez en diligence, et faites savoir à David, et lui dites: Ne demeure point cette nuit dans les campagnes du désert, et même ne manque point de passer plus avant, de peur que le Roi ne soit englouti, et tout le peuple aussi qui est avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Or Jonathan et Ahimahats se tenaient près de la fontaine de Roguel; parce qu’ils n’osaient pas se montrer lorsqu’ils venaient dans la ville, et une servante leur alla rapporter le tout, afin qu’ils s’en allassent, et le rapportassent au Roi David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Mais un garçon les aperçut, qui le rapporta à Absalom; et ils marchèrent tous deux en diligence et vinrent à Bahurim, en la maison d’un homme qui avait en sa cour un puits, dans lequel ils descendirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Et la femme de cet homme prit une couverture, et l’étendit sur l’ouverture du puits, et répandit sur elle du grain pilé, et la chose ne fut point découverte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Car les serviteurs d’Absalom vinrent vers cette femme jusque dans la maison, et lui dirent: Où sont Ahimahats et Jonathan? Et la femme leur répondit: Ils ont passé le gué de l’eau. Les ayant donc cherchés, et ne les ayant point trouvés, ils s’en retournèrent à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Et après qu’ils s’en furent allés, Ahimahats et Jonathan remontèrent du puits, et s’en allèrent, et firent leur rapport au Roi David, en lui disant: Levez-vous, et passez l’eau en diligence, car Achithophel a donné un tel conseil contre vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Alors David se leva, et tout le peuple qui était avec lui, et ils passèrent le Jourdain jusqu’au point du jour; il n’y en eut pas un qui ne passât le Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Or Achithophel voyant qu’on n’avait point fait ce qu’il avait conseillé, fit seller son âne, et se leva, et s’en alla en sa maison, dans sa ville: et après qu’il eut disposé des affaires de sa maison, il s’étrangla, et mourut, et il fut enseveli au sépulcre de son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'Et David s’en vint à Mahanajim: et Absalom passa le Jourdain, lui et tous ceux d’Israël qui étaient avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Et Absalom établit Hamasa sur l’armée, en la place de Joab. Or Hamasa était fils d’un homme nommé Jithra, Israélite, qui était entré vers Abigal fille de Nahas, soeur de Tséruja, la mère de Joab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Et Israël avec Absalom se campa au pays de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Or il arriva qu’aussitôt que David fut arrivé à Mahanajim, Sobi fils de Nahas de Rabba, laquelle avait été aux enfants de Hammon, et Makir fils de Hammiel de Lodebar, et Barzillaï Galaadite de Roguelim,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Amenèrent des lits, des bassins, des vaisseaux de terre, du froment, de l’orge, de la farine, du grain rôti, des fèves, des lentilles, et des grains rôtis;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'Du miel, du beurre, des brebis, et des fromages de vache; ils les amenèrent, dis-je, à David, et au peuple qui était avec lui, afin qu’ils en mangeassent; car ils disaient: Ce peuple est affamé, et il est las, et il a soif dans ce désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Or David fit le dénombrement du peuple qui était avec lui, et il établit sur eux des capitaines sur les milliers et sur les centaines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Et David envoya le peuple, savoir un tiers sous la conduite de Joab; un autre tiers sous la conduite d’Abisaï fils de Tséruja, frère de Joab; et l’autre tiers sous la conduite d’Ittaï Guittien: puis le Roi dit au peuple: Certainement je sortirai aussi avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Mais le peuple lui dit: Tu ne sortiras point; car quand nous viendrions à prendre la fuite on n’en ferait point de cas; et même quand la moitié de nous y serait tuée, on n’en ferait point de cas; car tu es maintenant autant que dix mille d’entre nous, c’est pourquoi il nous vaut mieux que tu sois dans la ville pour nous secourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Et le Roi leur dit: Je ferai ce que bon vous semblera. Le Roi donc s’arrêta à la place de la porte, et tout le peuple sortit par centaines, et par milliers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Et le Roi commanda à Joab, et à Abisaï, et à Ittaï, en disant: Epargnez-moi le jeune homme Absalom; et tout le peuple entendit ce que le Roi commandait à tous les capitaines touchant Absalom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Ainsi le peuple sortit aux champs pour aller à la rencontre d’Israël; et la bataille fut donnée en la forêt d’Ephraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Là fut battu le peuple d’Israël par les serviteurs de David, et il y eut en ce jour-là dans le même lieu une grande défaite, savoir de vingt mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Et la bataille s’étendit là par tout le pays, et la forêt consuma en ce jour-là beaucoup plus de peuple, que l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Or Absalom se rencontra devant les serviteurs de David, et Absalom était monté sur un mulet, et son mulet étant entré sous les branches entrelacées d’un grand chêne, sa tête s’embarrassa dans le chêne, où il demeura entre le ciel et la terre, et le mulet qui était sous lui, passa au delà.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Et un homme ayant vu cela, le rapporta à Joab, et lui dit: Voici, j’ai vu Absalom pendu à un chêne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Et Joab répondit à celui qui lui disait ces nouvelles: Et voici, tu l’as vu, et pourquoi ne l’as-tu pas tué là, le jetant par terre? Et c’eût été à moi de te donner dix pièces d’argent, et une ceinture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Mais cet homme dit à Joab: Quand je compterais dans ma main mille pièces d’argent, je ne mettrais point ma main sur le fils du Roi, car nous avons entendu ce que le Roi t’a commandé, et à Abisaï, et à Ittaï, en disant: Prenez garde chacun au jeune homme Absalom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Autrement j’eusse commis une lâcheté au péril de ma vie; car rien ne serait caché au Roi; et même tu m’eusses été contraire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Et Joab répondit: Je n’attendrai pas tant en ta présence; et ayant pris trois dards en sa main, il en perça le coeur d’Absalom qui était encore vivant au milieu du chêne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Puis dix jeunes hommes qui portaient les armes de Joab, environnèrent Absalom, et le frappèrent, et le firent mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Alors Joab fit sonner la trompette, et le peuple cessa de poursuivre Israël, parce que Joab retint le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Et ils prirent Absalom, et le jetèrent en la forêt, dans une grande fosse; et mirent sur lui un fort grand monceau de pierres; mais tout Israël s’enfuit, chacun en sa tente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Or Absalom avait pris et dressé pour soi de son vivant une statue dans la vallée du Roi; car il disait: Je n’ai point de fils pour laisser la mémoire de mon nom; et il appela cette statue-là de son nom; et jusqu’à ce jour on l’appelle la place d’Absalom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Et Ahimahats, fils de Tsadok, dit: Je vous prie, que je coure maintenant, et que je porte ces bonnes nouvelles au Roi, que l’Eternel l’a garanti de la main de ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Et Joab lui répondit: Tu ne seras pas aujourd’hui porteur de bonnes nouvelles; mais tu le seras un autre jour; car aujourd’hui tu ne porterais pas de bonnes nouvelles, puisque le fils du Roi est mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Et Joab dit à Cusi: Va, et rapporte au Roi ce que tu as vu. Cusi se prosterna devant Joab, puis il se mit à courir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Ahimahats fils de Tsadok dit encore à Joab: Quoi qu’il en soit, je courrai aussi maintenant après Cusi; Joab lui dit: Pourquoi veux-tu courir, mon fils, puisque tu n’as pas de bonnes nouvelles à porter?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Mais il dit: Quoi qu’il en soit, je courrai; et Joab lui répondit: Cours. Ahimahats donc courut par le chemin de la plaine, et passa Cusi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'Or David était assis entre les deux portes, et la sentinelle était allée sur le toit de la porte vers la muraille; et élevant ses yeux elle regarda, et voilà un homme qui courait tout seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Et la sentinelle cria, et le fit savoir au Roi; et le Roi dit: S’il est seul, il apporte de bonnes nouvelles; et cet homme marchait incessamment, et approchait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Puis la sentinelle vit un autre homme, qui courait; et elle cria au portier, et dit: Voilà un homme qui court tout seul; et le Roi dit: Il apporte aussi de bonnes nouvelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Et la sentinelle dit: Il me semble à voir courir le premier, que c’est ainsi que court Ahimahats fils de Tsadok; et le Roi dit: C’est un homme de bien; il vient quand il y a de bonnes nouvelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Alors Ahimahats cria, et dit au Roi: Tout va bien, et il se prosterna devant le Roi, le visage contre terre, et dit: Béni soit l’Eternel ton Dieu qui a livré les hommes qui avaient levé leurs mains contre le Roi mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Et le Roi dit: Le jeune homme Absalom se porte-t-il bien? Et Ahimahats lui répondit: J’ai vu s’élever un grand tumulte lorsque Joab envoyait le serviteur du Roi, et moi ton serviteur; je ne sais pas exactement ce que c’était.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Et le Roi lui dit: Détourne-toi, et tiens-toi là. Il se détourna donc, et s’arrêta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Alors voici Cusi qui vint, et qui dit: Que le Roi mon Seigneur ait ces bonnes nouvelles, c’est que l’Eternel t’a aujourd’hui garanti de la main de tous ceux qui s’étaient élevés contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Et le Roi dit à Cusi: Le jeune homme Absalom se porte-t-il bien? Et Cusi lui répondit: Que les ennemis du Roi mon Seigneur, et tous ceux qui se sont élevés contre toi pour te faire du mal, deviennent comme ce jeune homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Alors le Roi fut fort ému, et monta à la chambre haute de la porte, et se mit à pleurer, et il disait ainsi en marchant: Mon fils Absalom! mon fils! mon fils Absalom! plût à Dieu que je fusse mort moi-même pour toi! Absalom mon fils! mon fils!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Et on rapporta à Joab, en disant: Voilà le Roi qui pleure et mène deuil sur Absalom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Ainsi la délivrance fut en ce jour-là changée en deuil pour tout le peuple; parce que le peuple avait entendu qu’on disait en ce jour- là: Le Roi a été fort affligé à cause de son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Tellement qu’en ce jour-là le peuple venait dans la ville à la dérobée, comme s’en irait à la dérobée, un peuple qui serait honteux d’avoir fui dans la bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Et le Roi couvrit son visage, et criait à haute voix: Mon fils Absalom! Absalom mon fils! mon fils!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Et Joab entra vers le Roi dans la maison, et lui dit: Tu as aujourd’hui rendu confuses les faces de tous tes serviteurs qui ont aujourd’hui garanti ta vie, et la vie de tes fils et de tes filles, et la vie de tes femmes, et la vie de tes concubines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'De ce que tu aimes ceux qui te haïssent, et que tu hais ceux qui t’aiment; car tu as aujourd’hui montré que tes capitaines et tes serviteurs ne te sont rien; et je connais aujourd’hui que si Absalom vivait, et que nous tous fussions morts aujourd’hui, la chose te plairait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Maintenant donc lève-toi, sors, et parle selon le coeur de tes serviteurs; car je te jure par l’Eternel que si tu ne sors, il ne demeurera point cette nuit un seul homme avec toi; et ce mal sera pire que tous ceux qui te sont arrivés depuis ta jeunesse jusqu’à présent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Alors le Roi se leva et s’assit à la porte: et on fit savoir à tout le peuple, en disant: Voilà, le Roi est assis à la porte; et tout le peuple vint devant le Roi; mais Israël s enfuit, chacun en sa tente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Et tout le peuple se disputait à l’envi dans toutes les Tribus d’Israël, en disant: Le Roi nous a délivrés de la main de nos ennemis, et nous a garantis de la main des Philistins, et maintenant qu’il s’en soit fui du pays à cause d’Absalom!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Or Absalom, que nous avions oint pour Roi sur nous, est mort en la bataille; et maintenant pourquoi ne parlez-vous point de ramener le Roi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Et Le Roi David envoya dire aux Sacrificateurs Tsadok et Abiathar: Parlez aux Anciens de Juda, et leur dites: Pourquoi seriez-vous les derniers à ramener le Roi en sa maison? car les discours que tout Israël avait tenus, étaient venus jusqu’au Roi dans sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Vous êtes mes frères, vous êtes mes os et ma chair; et pourquoi seriez-vous les derniers à ramener le Roi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Dites même à Hamasa: N’es-tu pas mon os et ma chair? Que Dieu me fasse ainsi et ainsi il y ajoute; si tu n’es le chef de l’armée devant moi à toujours en la place de Joab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Ainsi il fléchit le coeur de tous les hommes de Juda, comme si ce n’eût été qu’un seul homme, et ils envoyèrent dire au Roi: Retourne- t’en avec tous tes serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Le Roi donc s’en retourna, et vint jusqu’au Jourdain; et Juda vint jusqu’à Guilgal pour aller au-devant du Roi, afin de lui faire repasser le Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Et Simhi fils de Guéra, fils de Jémini, qui était de Bahurim, descendit en diligence avec les hommes de Juda au-devant du Roi David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Il avait avec lui mille hommes de Benjamin. Tsiba serviteur de la maison de Saül, et ses quinze enfants, et ses vingt serviteurs étaient aussi avec lui, et ils passèrent le Jourdain avant le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Le bateau passa aussi pour transporter la famille du Roi, et faire ce qu’il lui plairait. Et Simhi fils de Guéra se jeta à genoux devant le Roi, comme il passait le Jourdain;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'Et il dit au Roi: Que mon Seigneur ne m’impute point mon iniquité, et ne se souvienne point de ce que ton serviteur fit méchamment le jour que le Roi mon Seigneur sortait de Jérusalem, tellement que le Roi prenne cela à coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Car ton serviteur connaît qu’il a péché; et voilà, je suis aujourd’hui venu le premier de la maison de Joseph, pour descendre au devant du Roi mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Mais Abisaï fils de Tséruja, répondit, et dit: Sous ombre de ceci ne fera-t-on point mourir Simhi, puisqu’il a maudit l’Oint de l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Et David dit: Qu’ai-je à faire avec vous, fils de Tséruja? car vous m’êtes aujourd’hui des adversaires. Ferait-on mourir aujourd’hui quelqu’un en Israël? car ne connais-je pas bien qu’aujourd’hui je suis fait Roi sur Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Et le Roi dit à Simhi: Tu ne mourras point; et le Roi le lui jura.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Après cela Méphiboseth fils de Saül, descendit au devant du Roi, et il n’avait point lavé ses pieds, ni fait sa barbe, ni lavé ses habits, depuis que le Roi s’en était allé, jusqu’au jour qu’il revint en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Il se trouva donc au-devant du Roi comme le Roi entrait dans Jérusalem, et le Roi lui dit: Pourquoi n’es-tu pas venu avec moi, Méphiboseth?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Et il lui répondit: Mon Seigneur, mon serviteur m’a trompé, car ton serviteur avait dit: Je ferai seller mon âne, et je monterai dessus, et j’irai vers le Roi, car ton serviteur est boiteux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Et il a calomnié ton serviteur auprès du Roi mon Seigneur; mais le Roi mon Seigneur est comme un ange de Dieu; fais donc ce qu’il te semblera bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Car quoique tous ceux de la maison de mon père ne soient que des gens dignes de mort envers le Roi mon Seigneur; cependant tu as mis ton serviteur entre ceux qui mangeaient à ta table; et quel droit ai-je donc pour me plaindre encore au Roi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Et le Roi lui dit: Pourquoi me parlerais-tu encore de tes affaires? je l’ai dit: Toi et Tsiba partagez les terres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Et Méphiboseth répondit au Roi: Qu’il prenne même le tout, puisque le Roi mon Seigneur est revenu en paix dans sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Or Barzillaï de Galaad était descendu de Roguelim, et avait passé le Jourdain avec le Roi, pour l’accompagner jusqu’au delà du Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Et Barzillaï était fort vieux, âgé de quatre-vingts ans; et il avait nourri le Roi tandis qu’il avait demeuré à Mahanajim; car c’était un homme fort riche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Et le Roi avait dit à Barzillaï: Passe plus avant avec moi, et je te nourrirai avec moi à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Mais Barzillaï avait répondu au Roi: Combien d’années ai-je vécu, que je monte encore avec le Roi à Jérusalem?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Je suis aujourd’hui âgé de quatre-vingts ans, pourrais-je discerner le bon d’avec le mauvais? Ton serviteur pourrait-il savourer ce qu’il mangerait et boirait? Pourrais-je encore entendre la voix des chantres et des chanteuses? et pourquoi ton serviteur serait-il à charge au Roi mon Seigneur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Ton serviteur passera un peu plus avant que le Jourdain avec le Roi, mais pourquoi le Roi me voudrait-il donner une telle récompense?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Je te prie que ton serviteur s’en retourne, et que je meure dans ma ville pour être mis au sépulcre de mon père et de ma mère, mais voici, ton serviteur Kimham passera avec le Roi mon Seigneur; fais- lui ce qui te semblera bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Et le Roi dit: Que Kimham passe avec moi, et je lui ferai ce qui te semblera bon, car je t’accorderai tout ce que tu saurais demander de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Tout le peuple donc passa le Jourdain avec le Roi. Puis le Roi baisa Barzillaï, et le bénit; et Barzillaï s’en retourna en son lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'De là le Roi passa à Guilgal, et Kimham passa avec lui. Ainsi tout le peuple de Juda, et même la moitié du peuple d’Israël, ramena le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Mais voici, tous les hommes d’Israël vinrent vers le Roi, et lui dirent: Pourquoi nos frères les hommes de Juda, t’ont-ils enlevé, et ont-ils fait passer le Jourdain au Roi et à la famille, et à tous ses gens?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Et tous les hommes de Juda répondirent aux hommes d’Israël: Parce que le Roi nous est plus proche; et pourquoi vous fâchez-vous de cela? Avons-nous rien mangé de ce qui est au Roi; ou en recevrions- nous quelques présents?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Mais les hommes d’Israël répondirent aux hommes de Juda, et dirent: Nous avons dix parts au Roi, et même nous sommes à David quelque chose de plus que vous; pourquoi donc nous avez-vous méprisés; et n’avons-nous pas parlé les premiers de ramener notre Roi? mais les hommes de Juda parlèrent encore plus rudement que les hommes d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Et il se trouva là un méchant homme qui avait nom Sébah, fils de Bicri, homme de Jémini, qui sonna de la trompette, et qui dit: Nous n’avons point de part avec David, ni d’héritage à attendre du fils d’Isaï. Ô Israël! que chacun se retire en ses tentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Ainsi tous les hommes d’Israël se séparèrent de David, et suivirent Sébah fils de Bicri; mais les hommes de Juda s’attachèrent à leur Roi, et l’accompagnèrent depuis le Jourdain jusqu’à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Or quand David fut venu en sa maison à Jérusalem, il prit ses dix femmes concubines qu’il avait laissées pour garder sa maison, et les fit garder dans une maison, où il les nourrissait; mais il n’allait point vers elles; ainsi elles furent séquestrées jusqu’au jour de leur mort, pour vivre en veuvage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Puis le Roi dit à Hamasa: Assemble-moi dans trois jours à cri public les hommes de Juda, et représente toi ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Hamasa donc s’en alla assembler à cri public ceux de Juda; mais il tarda au delà du temps qu’on lui avait assigné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Et David dit à Abisaï: Maintenant Sébah fils de Bicri nous fera plus de mal que n’a fait Absalom; toi donc prends les serviteurs de ton Seigneur, et le poursuis, de peur qu’il ne trouve quelques villes fortes, et que nous ne le perdions de vue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Ainsi les gens de Joab sortirent après lui, avec les Kéréthiens, et les Péléthiens, et tous les hommes forts; ils sortirent donc de Jérusalem pour poursuivre Sébah fils de Bicri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Et comme ils étaient auprès de la grande pierre qui est à Gabaon, Hamasa vint au devant d’eux, et Joab avait sa casaque, dont il était vêtu, ceinte, et son épée était ceinte par dessus, attachée sur ses reins dans son fourreau, et quand il sortit elle tomba.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Et Joab dit à Hamasa: Te portes-tu bien, mon frère? Puis Joab prit de sa main droite la barbe de Hamasa pour le baiser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Or Hamasa ne prenait point garde à l’épée qui était en la main de Joab; et Joab l’en frappa à la cinquième côte, et répandit ses entrailles à terre, sans le frapper une seconde fois; et ainsi il mourut. Après cela Joab et Abisaï son frère poursuivirent Sébah fils de Bicri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Alors un des serviteurs de Joab s’arrêta auprès d’Hamasa, et dit: Quiconque aime Joab, et quiconque est pour David, qu’il suive Joab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Et Hamasa était vautré dans son sang au milieu du chemin; mais cet homme-là voyant que tout le peuple s’arrêtait, poussa Hamasa hors du chemin dans un champ, et jeta un vêtement sur lui, après qu’il eut vu que tous ceux qui venaient à lui s’arrêtaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Et quand on l’eut ôté du chemin, tous les hommes qui suivaient Joab passaient au delà, afin de poursuivre Sébah fils de Bicri;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Qui passa par toutes les Tribus d’Israël, jusqu’à Abelah, et Beth- mahaca, avec tous les Bériens qui s’étaient assemblés, et qui aussi l’avaient suivi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Les gens donc de Joab s’en vinrent, et l’assiégèrent à Abel Beth- mahaca, et ils élevèrent une terrasse contre la ville, au devant de la muraille; et tout le peuple qui était avec Joab rompait la muraille pour la faire tomber.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Alors une femme sage de la ville s’écria: Ecoutez, écoutez: Dites, je vous prie, à Joab: Approche-toi d’ici, et que je parle à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Et quand il se fut approché d’elle, elle lui dit: Es-tu Joab? Il répondit: Je le suis. Elle lui dit: Ecoute les paroles de ta servante. Il répondit: J’écoute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Elle parla encore, et dit: On disait communément autrefois: Qu’on aille demander conseil à Abel, et on a ainsi continué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Entre les villes fidèles d’Israël je suis une des plus paisibles; tu cherches à détruire une ville qui est une des capitales d’Israël; pourquoi détruirais-tu l’héritage de l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Joab lui répondit, et dit: A Dieu ne plaise! à Dieu ne plaise que je détruise, ni que je ruine!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'La chose n’est pas ainsi; mais un homme de la montagne d’Ephraïm, qui a nom Sébah, fils de Bicri, a levé sa main contre le Roi David; livrez-le moi lui seul, et je m’en irai de devant la ville. Et la femme dit à Joab: Voici, sa tête te sera jetée de dessus la muraille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Cette femme-là donc vint vers tout le peuple, et leur parla sagement, et ils coupèrent la tête à Sébah fils de Bicri, et la jetèrent à Joab. Alors on sonna de la trompette, et chacun se retira de devant la ville en sa tente; puis Joab s’en retourna vers le Roi à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Joab donc demeura établi sur toute l’armée d’Israël, et Bénaja fils de Jéhojadah sur les Kéréthiens, et sur les Péléthiens;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Et Adoram sur les tributs, et Jehosaphat fils d’Ahilud était commis sur les Registres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Séla était le Secrétaire; et Tsadok et Abiathar étaient les Sacrificateurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Et Hira Jaïrite était le principal officier de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Or il y eut du temps de David une famine qui dura trois ans de suite. Et David rechercha la face de l’Eternel; et l’Eternel lui répondit: C’est à cause de Saül et de sa maison sanguinaire; parce qu’il a fait mourir les Gabaonites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Alors le Roi appela les Gabaonites pour leur parler. Or les Gabaonites n’étaient point des enfants d’Israël, mais un reste des Amorrhéens; et les enfants d’Israël leur avaient juré de les laisser vivre; mais Saül par un zèle qu’il avait pour les enfants d’Israël et de Juda, avait cherché de les faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Et David dit aux Gabaonites: Que vous ferai-je, et par quel moyen vous apaiserai-je; afin que vous bénissiez l’héritage de l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Et les Gabaonites lui répondirent: Nous n’avons à faire ni de l’or ni de l’argent de Saül et de sa maison, ni qu’on fasse mourir personne en Israël. Et le Roi leur dit: Que demandez-vous donc que je fasse pour vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Et ils répondirent au Roi: Quant à cet homme qui nous a détruits, et qui a machiné contre nous, en sorte que nous ayons été exterminés, sans pouvoir subsister dans aucune des contrées d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'Qu’on nous livre sept hommes de ses fils, et nous les mettrons en croix devant l’Eternel, au coteau de Saül, l’Elu de l’Eternel. Et le Roi leur dit: Je vous les livrerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Or le Roi épargna Méphiboseth fils de Jonathan, fils de Saül, à cause du serment que David et Jonathan fils de Saül avaient fait entr’eux au nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Mais le Roi prit les deux fils de Ritspa fille d’Aja, qu’elle avait enfantés à Saül, savoir Armoni et Méphiboseth, et les cinq fils de Mical fille de Saül, qu’elle avait nourris à Hadriel fils de Barzillaï Méholathite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'Et il les livra entre les mains des Gabaonites, qui les mirent en croix sur la montagne devant l’Eternel; et ces sept-là furent tués ensemble, et on les fit mourir aux premiers jours de la moisson, savoir au commencement de la moisson des orges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Alors Ritspa fille d’Aja prit un sac, et le tendit pour elle au dessus d’un rocher, depuis le commencement de la moisson jusqu’à ce qu’il tombât de l’eau du ciel sur eux; et elle ne souffrait point qu’aucun oiseau des cieux se posât sur eux de jour, ni aucune bête des champs la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Et on rapporta à David ce que Ritspa, fille d’Aja, concubine de Saül, avait fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Et David s’en alla, et prit les os de Saül, et les os de Jonathan son fils, que les habitants de Jabés de Galaad avaient enlevés de la place de Beth-san, où les Philistins les avaient pendus, le jour qu’ils avaient tué Saül en Guilboah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Il emporta donc de là les os de Saül, et les os de Jonathan son fils. On recueillit aussi les os de ceux qui avaient été mis en croix;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'Et on les ensevelit avec les os de Saül et de Jonathan son fils au pays de Benjamin, à Tsélah, dans le sépulcre de Kis père de Saül; et on fit tout ce que le Roi avait commandé. Et après cela, Dieu fut apaisé envers le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Or il y avait eu aussi une autre guerre des Philistins contre les Israélites; et David y était allé, et ses serviteurs avec lui, et ils avaient tellement combattu contre les Philistins, que David défaillait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Et Jisbi-benob, qui était des enfants de Rapha, et qui avait une lance dont le fer pesait trois cents sicles d’airain, et qui était armé d’une nouvelle manière, avait résolu de frapper David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Mais Abisaï fils de Tséruja vint à son secours, et frappa le Philistin, et le tua. Alors les gens de David jurèrent, en disant: Tu ne sortiras plus avec nous en bataille, de peur que tu n’éteignes la Lampe d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Après cela il y eut une autre guerre à Gob contre les Philistins, où Sibbécaï le Husathite frappa Saph, qui était des enfants de Rapha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Il y eut encore une autre guerre à Gob contre les Philistins, en laquelle Elhanan, fils de Jaharé Oreguim Bethléhémite frappa le frère de Goliath Guittien, qui avait une hallebarde dont la hampe était comme l’ensuble d’un tisserand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Il y eut encore une autre guerre à Gath, où il se trouva un homme d’une taille extraordinaire, qui avait six doigts à chaque main, et six orteils à chaque pied, en tout vingt et quatre, lequel était aussi de la race de Rapha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Cet homme défia Israël; mais Jonathan fils de Simha, frère de David, le tua.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Ces quatre-là naquirent à Gath, de la race de Rapha, et moururent par les mains de David, ou par les mains de ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Après cela David prononça à l’Eternel les paroles de ce cantique, le jour que l’Eternel l’eut délivré de la main de tous ses ennemis, et surtout de la main de Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Il dit donc: L’Eternel est ma roche, et ma forteresse, et mon libérateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Dieu est mon rocher, je me retirerai vers lui; il est mon bouclier et la corne de mon salut; il est ma haute retraite et mon refuge; mon Sauveur, tu me garantis de la violence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Je crierai à l’Eternel, lequel on doit louer, et je serai délivré de mes ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Car les angoisses de la mort m’avaient environné; les torrents des méchants m’avaient troublé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Les cordeaux du sépulcre m’avaient entouré; les filets de la mort m’avaient surpris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'Quand j’ai été dans l’adversité j’ai crié à l’Eternel; j’ai, dis- je, crié à mon Dieu, et il a entendu ma voix de son palais, et mon cri est parvenu à ses oreilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Alors la terre fut ébranlée et trembla, les fondements des cieux croulèrent et furent ébranlés, parce qu’il était irrité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Une fumée montait de ses narines, et de sa bouche sortait un feu dévorant; les charbons de feu en étaient embrasés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Il baissa donc les cieux, et descendit, ayant une obscurité sous ses pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Et il était monté sur un Chérubin, et volait; et il parut sur les ailes du vent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Et il mit tout autour de soi les ténèbres pour tabernacle; savoir, les eaux amoncelées qui sont les nuées de l’air.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Des charbons de feu étaient embrasés de la splendeur qui était au devant de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'L’Eternel tonna des cieux, et le Souverain fit retentir sa voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Il tira ses flèches, et écarta mes ennemis; il fit briller l’éclair; et les mit en déroute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Alors le fond de la mer parut, et les fondements de la terre habitable furent découverts par l’Eternel qui les tançait, et par le souffle du vent de ses narines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Il étendit la main d’en haut, et m’enleva, et me tira des grosses eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Il me délivra de mon ennemi puissant, et de ceux qui me haïssaient, car ils étaient plus forts que moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Ils m’avaient devancé au jour de ma calamité; mais l’Eternel fut mon appui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Il m’a mis au large, il m’a délivré, parce qu’il a pris son plaisir en moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'L’Eternel m’a rendu selon ma justice; il m’a rendu selon la pureté de mes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Parce que j’ai tenu le chemin de l’Eternel, et que je ne me suis point détourné de mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Car j’ai eu devant moi tous ses droits, et je ne me suis point détourné de ses ordonnances.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Et j’ai été intègre envers lui, et je me suis donné garde de mon iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'L’Eternel donc m’a rendu selon ma justice, et selon ma pureté, qui a été devant ses yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Envers celui qui use de gratuité, tu uses de gratuité; et envers l’homme intègre tu te montres intègre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'Envers celui qui est pur tu te montres pur; mais envers le pervers tu agis selon sa perversité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Car tu sauves le peuple affligé, et tu jettes tes yeux sur les hautains, et les humilies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Tu es même ma lampe, ô Eternel! et l’Eternel fera reluire mes ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Et par ton moyen je me jetterai sur toute une troupe, et par le moyen de mon Dieu je franchirai la muraille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'La voie du Dieu Fort est parfaite, la parole de l’Eternel est affinée; c’est un bouclier à tous ceux qui se retirent vers lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Car qui est Dieu Fort, sinon l’Eternel? et qui est Rocher, sinon notre Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Le Dieu Fort, qui est ma force, est la vraie force, et il a aplani ma voie, qui était une voie d’intégrité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Il a rendu mes pieds égaux à ceux des biches, et m’a fait tenir debout sur mes lieux élevés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'C’est lui qui dresse mes mains au combat, de sorte qu’un arc d’airain a été rompu avec mes bras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Tu m’as aussi donné le bouclier de ton salut, et ta bonté m’a fait devenir plus grand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Tu as élargi le chemin sous mes pas, et mes talons n’ont point glissé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'J’ai poursuivi mes ennemis, et je les ai exterminés; et je ne m’en suis point retourné jusqu’à ce que je les aie consumés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Je les ai consumés, je les ai transpercés, et ils ne se sont point relevés; mais ils sont tombés sous mes pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Car tu m’as revêtu de force pour le combat; tu as fait plier sous moi ceux qui s’élevaient contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Tu as fait aussi que mes ennemis, et ceux qui me haïssaient ont tourné le dos devant moi, et je les ai détruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Ils regardaient çà et là, mais il n’y avait point de libérateur; ils criaient à l’Eternel, mais il ne leur a point répondu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Et je les ai brisés menu comme la poussière de la terre; je les ai écrasés, et je les ai foulés comme la boue des rues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Et tu m’as délivré des dissensions des peuples, tu m’as gardé pour être le chef des nations. Le peuple que je ne connaissais point m’a été assujetti.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Les étrangers m’ont menti; ayant ouï parler de moi, ils se sont rendus obéissants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Les étrangers se sont écoulés et ils ont tremblé de peur dans leurs retraites cachées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'L’Eternel est vivant, et mon rocher est béni; c’est pourquoi Dieu, le rocher de mon salut, soit exalté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Le Dieu Fort est celui qui me donne les moyens de me venger, et qui m’assujettit les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'C’est lui aussi qui me retire d’entre mes ennemis. Tu m’enlèves d’entre ceux qui s’élèvent contre moi; tu me délivres de l’homme outrageux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'C’est pourquoi, ô Eternel! je te célébrerai parmi les nations, et je chanterai des psaumes à ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'C’est lui qui est la tour des délivrances de son Roi, et qui use de gratuité envers David son Oint, et envers sa postérité à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Or ce sont ici les dernières paroles de David. David fils d’Isaï, l’homme qui a été élevé, pour être l’Oint du Dieu de Jacob, et qui compose les doux cantiques d’Israël, dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'L’Esprit de l’Eternel a parlé par moi, et sa parole a été sur ma langue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Le Dieu d’Israël a dit, le Rocher d’Israël m’a parlé, en disant: Le juste dominateur des hommes, le dominateur en la crainte de Dieu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'Est comme la lumière du matin quand le soleil se lève, du matin, dis-je, qui est sans nuages; il est comme l’herbe qui sort de la terre après la lumière du soleil quand il paraît après la pluie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Mais il n’en sera pas ainsi de ma maison envers le Dieu Fort, parce qu’il a traité avec moi une alliance éternelle bien établie, et assurée; car c’est tout mon salut, et tout mon plaisir; c’est pourquoi il ne fera pas simplement germer ma maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Mais les méchants seront tous ensemble comme des épines qu’on jette au loin, parce qu’on ne les prend point avec la main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Mais celui qui les veut manier, prend ou du fer, ou le bois d’une hallebarde; et on les brûle entièrement sur le lieu même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Ce sont ici les noms des vaillants hommes que David avait: Joseb- Basebeth Tachkémonite était un des principaux capitaines; c’était Hadino le Hetsnite, qui eut le dessus sur huit cents hommes qu’il tua en une seule fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Après lui était Eléazar, fils de Dodo, fils d’Ahohi, l’un de ces trois vaillants hommes qui étaient avec David lorsqu’on rendit honteux les Philistins assemblés là pour combattre, et que ceux d’Israël se retirèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Il se leva, et battit les Philistins, jusqu’à ce que sa main en fut lasse, et qu’elle demeura attachée à l’épée; en ce jour-là l’Eternel accorda une grande délivrance, et le peuple retourna après Eléazar, seulement pour prendre la dépouille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Après lui était Samma fils d’Agné Hararite; car les Philistins s’étant assemblés dans un bourg où il y avait un endroit d’un champ plein de lentilles, et le peuple fuyant devant les Philistins;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Il se tint au milieu de cet endroit du champ, et le défendit, et frappa les Philistins; tellement que l’Eternel accorda une grande délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Il en descendit encore trois d’entre les trente capitaines qui vinrent au temps de la moisson vers David, dans la caverne d’Hadullam, lorsqu’une compagnie de Philistins était campée en la vallée des Réphaïms.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'David était alors dans la forteresse, et la garnison des Philistins était en ce même temps-là à Bethléhem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Et David fit ce souhait, et dit: Qui est-ce qui me ferait boire de l’eau du puits qui est à la porte de Bethléhem?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Alors ces trois vaillants hommes passèrent au travers du camp des Philistins, et puisèrent de l’eau du puits qui est à la porte de Bethléhem, et l’ayant apportée, ils la présentèrent à David, lequel n’en voulut point boire, mais il la répandit en présence de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'Car il dit: Qu’il ne m’arrive jamais, ô Eternel! de faire une telle chose. N’est-ce pas là le sang de ces hommes qui ont fait ce voyage au péril de leur vie? Il n’en voulut donc point boire. Ces trois vaillants hommes firent cette action-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Il y avait aussi Abisaï frère de Joab fils de Tséruja, qui était un des principaux capitaines; celui-ci lançant sa hallebarde contre trois cents hommes, les blessa à mort, et il s’acquit un grand nom entre les trois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Ne fut-il pas le plus estimé entre ces trois-là? c’est pourquoi aussi il fut leur chef; cependant il n égala point les trois premiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Bénaja aussi fils de Jéhojadah, fils d’un vaillant homme, de Kabtléël, avait fait de grands exploits. Il frappa deux des plus puissants hommes de Moab; il descendit aussi et frappa un lion dans une fosse en un jour de neige.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Il frappa aussi un homme Egyptien, qui était un bel homme. Cet Egyptien avait en sa main une hallebarde; mais Bénaja descendit contre lui avec un bâton, arracha la hallebarde de la main de l’Egyptien, et le tua de sa propre hallebarde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Bénaja fils de Jéhojadah fit ces choses-là, et fut illustre entre les trois vaillants hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Et fut plus honoré que les trente; encore qu’il n’égalât point ces trois-là: c’est pourquoi David l’établit sur ses gens de commandement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Hasaël, frère de Joab, était des trente; Elhanan fils de Dodo, de Bethléhem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Samma Harodite; Elika Harodite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Helets Paltite; Hira fils de Hikkes, Tékohite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abihézer Hanathothite; Mebunnai Husathite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Tsalmon Ahohite; Maharaï Nétophathite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Héleb fils de Bahana Nétophathite; Ittaï fils de Ribaï de Guibha des enfants de Benjamin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Bénaja Pirhathonite; Hiddaï des vallées de Gahas;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abi Halbon Harbathite; Hazmaveth Barhumite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eliachba Sahalbonite; des enfants de Jesen, Jonathan;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Samma Hararite; Ahiam fils de Sarar Hararite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Eliphélet, fils d’Ahasbaï, fils de Mahacati; Eliham fils d’Achithophel Guilonite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hetseraï Carmélite; Parahaï Arbite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jiguéal fils de Nathan de Tsoba; Bani Gadite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Tsélek Hammonite; Naharaï Béérothite, qui portait les armes de Joab fils de Tséruja;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Hira Jithrite; Gareb Jithrite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Urie Héthien; en tout trente-sept.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Or la colère de l’Eternel s’embrasa encore contre Israël; parce que David fut incité contr’eux à dire: Va, dénombre Israël et Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Le Roi donc dit à Joab, chef de l’armée, lequel il avait avec soi: Passe maintenant par toutes les Tribus d’Israël, depuis Dan jusqu’à Beersébah, et dénombre le peuple, afin que j’en sache le nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Mais Joab répondit au Roi: Que l’Eternel ton Dieu veuille augmenter ton peuple autant, et cent fois autant qu’il est maintenant; et que les yeux du Roi mon Seigneur le voient! mais pourquoi le Roi mon Seigneur prend-il plaisir à cela?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Néanmoins la parole du Roi l’emporta sur Joab, et sur les Chefs de l’armée; et Joab et les chefs de l’armée sortirent de la présence du Roi pour dénombrer le peuple, savoir Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Ils passèrent donc le Jourdain, et se campèrent en Haroher, à main droite de la ville, qui est au milieu du torrent de Gad, et vers Jahzer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Et ils vinrent en Galaad, et dans la terre de ceux qui habitent au bas pays d’Hodsi, et vinrent à Dan-Jahan, et ensuite aux environs de Sidon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Et ils vinrent jusqu’à la forteresse de Tsor, et dans toutes les villes des Héviens, et des Cananéens, et sortirent vers le Midi de Juda à Beersébah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Ainsi ils traversèrent tout le pays, et revinrent à Jérusalem au bout de neuf mois et vingt jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Et Joab donna au Roi le rolle du dénombrement du peuple; et il y eut de ceux d’Israël huit cent mille hommes de guerre tirant l’épée, et de ceux de Juda cinq cent mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Alors David fut touché en son coeur, après qu’il eut fait ainsi dénombrer le peuple; et David dit à l’Eternel: J’ai commis un grand péché en faisant cela, mais, je te prie, ô Eternel! pardonne l’iniquité de ton serviteur; car j’ai agi très-follement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Après cela David se leva dès le matin, et la parole de l’Eternel fut adressée à Gad le Prophète, qui était le Voyant de David, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Va, et dis à David: Ainsi a dit l’Eternel: J’apporte trois choses contre toi; choisis l’une des trois, afin que je te la fasse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Gad vint donc vers David, et lui fit entendre cela en disant: Que veux-tu qui t’arrive: ou sept ans de famine sur ton pays; ou que durant trois mois tu fuies devant tes ennemis, et qu’ils te poursuivent; ou que durant trois jours la mortalité soit en ton pays? Avises-y maintenant, et regarde ce que tu veux que je réponde à celui qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'Et David répondit à Gad: Je suis dans une très-grande angoisse. Je te prie que nous tombions entre les mains de l’Eternel, car ses compassions sont en grand nombre; et que je ne tombe point entre les mains des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'L’Eternel donc envoya la mortalité en Israël, depuis le matin jusqu’au temps de l’assignation; et il mourut du peuple depuis Dan jusqu’à Beersébah, soixante-dix mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Mais quand l’Ange eut étendu sa main sur Jérusalem pour la ravager, l’Eternel se repentit de ce mal-là et dit à l’Ange qui faisait le dégât parmi le peuple: C’est assez, retire à cette heure ta main. Or l’Ange de l’Eternel était auprès de l’aire d’Arauna Jébusien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Car David voyant l’Ange qui frappait le peuple, parla à l’Eternel, et dit: Voici, c’est moi qui ai péché, c’est moi qui ai commis l’iniquité, mais ces brebis qu’ont-elles fait? Je te prie que ta main soit contre moi, et contre la maison de mon père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Et en ce jour-là Gad vint vers David, et lui dit: Monte, et dresse un autel à l’Eternel dans l’aire d’Arauna Jébusien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Et David monta selon la parole de Gad, ainsi que l’Eternel l’avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Et Arauna regarda, et vit le Roi, et ses serviteurs qui venaient vers lui; et ainsi Arauna sortit, et se prosterna devant le Roi, le visage contre terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Et Arauna dit: Pour quel sujet le Roi mon Seigneur vient-il vers son serviteur? Et David répondit: Pour acheter ton aire, et y bâtir un autel à l’Eternel, afin que cette plaie soit arrêtée de dessus le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Et Arauna dit à David: Que le Roi mon Seigneur prenne et offre ce qu’il lui plaira. Voilà des boeufs pour l’holocauste, et des chariots, et un attelage de boeufs au lieu de bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Arauna donna tout cela au Roi comme un Roi. Et Arauna dit au Roi: L’Eternel ton Dieu veuille t’avoir pour agréable!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Et le Roi répondit à Arauna: Non, mais je l’achèterai de toi pour un certain prix, et je n’offrirai point à l’Eternel mon Dieu des holocaustes qui ne me coûtent rien. Ainsi David acheta l’aire, et il acheta aussi les boeufs cinquante sicles d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Puis David bâtit là un autel à l’Eternel, et offrit des holocaustes et des sacrifices de prospérités; et l’Eternel fut apaisé envers le pays, et la plaie fut arrêtée en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Or le Roi David devint vieux, et avancé en âge; et quoiqu’on le couvrît de vêtements, il ne pouvait pourtant point se réchauffer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Et ses serviteurs lui dirent: Qu’on cherche au Roi notre seigneur une jeune fille vierge, qui se tienne devant le Roi, et qui en ait soin, et qu’elle dorme en son sein, afin que le Roi notre Seigneur se réchauffe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'On chercha donc dans toutes les contrées d’Israël une fille qui fût belle; et on trouva Abisag Sunamite, qu’on amena au Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Et cette jeune fille était fort belle, et elle avait soin du Roi, et le servait; mais le Roi ne la connut point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Alors Adonija fils de Haggith s’éleva, en disant: Je régnerai. Il s’établit des chariots, des gens de cheval, et cinquante hommes qui couraient devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Or son père ne voulait point le chagriner de son temps, et lui dire: Pourquoi agis-tu ainsi? Il était aussi de fort belle taille, et sa mère l’avait enfanté après Absalom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Et il communiqua ses affaires à Joab, fils de Tséruja, et au Sacrificateur Abiathar, qui l’aidèrent, et furent de son parti.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Mais le Sacrificateur Tsadok, et Bénaja fils de Jéhojadah, et Nathan le Prophète, et Simhi, et Réhi, et les vaillants hommes de David n’étaient point du parti d’Adonija.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Or Adonija fit tuer des brebis et des boeufs et des bêtes grasses près de la pierre de Zohéleth, qui était auprès de la fontaine de Roguel; et il convia tous ses frères les fils du Roi, et tous ceux de Juda qui étaient au service du Roi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Mais il ne convia point Nathan le Prophète, ni Bénaja, ni les vaillants hommes, ni Salomon son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Alors Nathan parla à Bath-sebah, mère de Salomon, en disant: N’as-tu pas entendu qu’Adonija fils de Hagguith a été fait Roi? et David notre Seigneur n’en sait rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Maintenant donc viens, et que je te donne un conseil, je te prie, et sauve ta vie, et la vie de ton fils Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Va, et te présente au Roi David, et lui dis: Mon Seigneur, n’as-tu pas juré à ta servante, en disant: Certainement ton fils Salomon régnera après moi, et sera assis sur mon trône? pourquoi donc Adonija a-t-il été fait Roi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Et voici, lorsque tu seras encore là, et que tu parleras avec le Roi, je viendrai après toi, et je continuerai le discours que tu auras commencé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Bath-sebah donc vint vers le Roi dans sa chambre; or le Roi était fort vieux, et Abisag Sunamite le servait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Et Bath-sebah s’inclina et se prosterna devant le Roi; et le Roi lui dit: Qu’as-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Et elle lui répondit: Mon Seigneur, tu as juré par l’Eternel ton Dieu à ta servante, et tu lui as dit: Certainement ton fils Salomon régnera après moi, et sera assis sur mon trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Mais maintenant voici, Adonija a été fait Roi, et tu n’en sais rien, ô Roi, mon Seigneur!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Il a même fait tuer des boeufs, des bêtes grasses, et des brebis en grand nombre, et a convié tous les fils du Roi, avec Abiathar le Sacrificateur, et Joab Chef de l’Armée, mais il n’a point convié ton serviteur Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Or quant à toi, ô Roi mon Seigneur! les yeux de tout Israël sont sur toi, afin que tu leur déclares qui doit être assis sur le trône du Roi mon Seigneur après lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Autrement il arrivera qu’aussitôt que le Roi mon Seigneur sera endormi avec ses pères, nous serons traités comme coupables, moi, et mon fils Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Et comme elle parlait encore avec le Roi, voici venir Nathan le Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Et on le fit savoir au Roi en disant: Voici Nathan le Prophète; et il se présenta devant le Roi, et se prosterna devant lui sur son visage en terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Et Nathan dit: Ô Roi mon Seigneur! as-tu dit: Adonija régnera après moi, et sera assis sur mon trône?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Car il est descendu aujourd’hui, et il a fait tuer des boeufs, des bêtes grasses, et des brebis en grand nombre, et a convié tous les fils du Roi, et les Chefs de l’armée, et le Sacrificateur Abiathar; et voilà ils mangent et boivent devant lui; et ils ont dit: Vive le Roi Adonija.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Mais il n’a convié ni moi ton serviteur, ni le Sacrificateur Tsadok, ni Bénaja, fils de Jéhojadah, ni Salomon ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Ceci aurait-il été fait de par le Roi mon Seigneur, sans que tu eusses fait savoir à ton serviteur qui est celui qui doit être assis sur le trône du Roi mon Seigneur après lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Et le Roi David répondit, et dit: Appelez-moi Bath-sebah; et elle se présenta devant le Roi, et se tint devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Alors le Roi jura et dit: L’Eternel qui m’a délivré de toute angoisse, est vivant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'Que comme je t’ai juré par l’Eternel le Dieu d’Israël, en disant: Certainement ton fils Salomon régnera après moi, et sera assis sur mon trône en ma place; je le ferai ainsi aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Alors Bath-sebah s’inclina le visage contre terre, et se prosterna devant le Roi, et dit: Que le Roi David mon Seigneur vive éternellement!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Et le Roi David dit: Appelez-moi Tsadok le Sacrificateur, et Nathan le Prophète, et Bénaja fils de Jéhojadah; et ils se présentèrent devant le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Et le Roi leur dit: Prenez avec vous les serviteurs de votre Seigneur, et faites monter mon fils Salomon sur ma mule, et faites-le descendre vers Guihon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Et que Tsadok le Sacrificateur, et Nathan le Prophète, l’oignent en ce lieu- là pour Roi sur Israël, puis vous sonnerez de la trompette, et vous direz: Vive le Roi Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Et vous monterez après lui, et il viendra, et s’assiéra sur mon trône, et il régnera en ma place; car j’ai ordonné qu’il soit Conducteur d’Israël et de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Et Bénaja fils de Jéhojadah répondit au Roi, et dit: Amen! que l’Eternel le Dieu du Roi mon Seigneur l’ordonne ainsi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Comme l’Eternel a été avec le Roi mon Seigneur, qu’il soit aussi avec Salomon, et qu’il élève son trône encore plus que le trône du Roi David mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Puis Tsadok le Sacrificateur descendit avec Nathan le Prophète, et Bénaja fils de Jéhojadah, les Kéréthiens et les Péléthiens, et ils firent monter Salomon sur la mule du Roi David, et le menèrent vers Guihon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Et Tsadok le Sacrificateur prit du Tabernacle une corne pleine d’huile, et oignit Salomon; puis on sonna de la trompette, et tout le peuple dit: Vive le Roi Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Et tout le monde monta après lui, et le peuple jouait de la flûte, et était dans la joie tellement que la terre se fendait des cris qu’ils jetaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Or Adonija et tous les conviés qui étaient avec lui, entendirent ce bruit comme ils achevaient de manger; et Joab entendant le son de la trompette, dit: Que veut dire ce bruit de la ville qui est ainsi émue?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Et comme il parlait encore, voici Jonathan fils d’Abiathar le Sacrificateur arriva; et Adonija lui dit: Entre; car tu es un vaillant homme, et tu apporteras de bonnes nouvelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Mais Jonathan répondit, et dit à Adonija: Certainement le Roi David notre Seigneur a établi Roi Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Et le Roi a envoyé avec lui Tsadok le Sacrificateur, Nathan le Prophète, Bénaja fils de Jéhojadah, et les Kéréthiens, et les Péléthiens, et ils l’ont fait monter sur la mule du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'Et Tsadok le Sacrificateur, et Nathan le Prophète l’ont oint pour Roi à Guihon, d’où ils sont remontés avec joie, et la ville est ainsi émue; c’est là le bruit que vous avez entendu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Et même Salomon s’est assis sur le trône du Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Et les serviteurs du Roi sont venus pour bénir le Roi David notre Seigneur, en disant: Que Dieu rende le nom de Salomon encore plus grand que ton nom, et qu’il élève son trône encore plus que ton trône! Et le Roi s’est prosterné sur le lit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Qui plus est, le Roi a dit ainsi: Béni soit l’Eternel le Dieu d’Israël, qui a fait aujourd’hui asseoir sur mon trône un successeur, lequel je vois de mes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Alors tous les conviés qui étaient avec Adonija furent dans un grand trouble, et se levèrent, et s’en allèrent chacun son chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Et Adonija craignant Salomon, se leva et s’en alla, et empoigna les cornes de l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Et on le rapporta à Salomon, en disant: Voilà Adonija qui a peur du Roi Salomon, et voilà il a empoigné les cornes de l’autel, en disant: Que le Roi Salomon me jure aujourd’hui qu’il ne fera point mourir son serviteur par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Et Salomon dit: Si à l’avenir il se porte en homme de bien il ne tombera pas un de ses cheveux en terre; mais s’il se trouve du mal en lui, il mourra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Alors le Roi Salomon envoya, et on le ramena de l’autel, et il vint, et se prosterna devant le Roi Salomon; et Salomon lui dit: Va-t’en en ta maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Or le temps de la mort de David étant proche, il donna ce commandement à son fils Salomon, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Je m’en vais par le chemin de toute la terre, fortifie-toi, et porte-toi en homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Et garde ce que l’Eternel ton Dieu veut que tu gardes, en marchant dans ses voies, et en gardant ses statuts, ses commandements, ses ordonnances, et ses témoignages, selon ce qui est écrit dans la Loi de Moïse, afin que tu réussisses en tout ce que tu feras, et en tout ce que tu entreprendras;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'Afin que l’Eternel confirme la parole qu’il m’a donnée, en disant: Si tes fils prennent garde à leur voie, pour marcher devant moi dans la vérité, de tout leur cœur, et de toute leur âme, il ne te manquera point de successeur assis sur le trône d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Au reste, tu sais ce que m’a fait Joab fils de Tséruja, et ce qu’il a fait aux deux Chefs des armées d’Israël, Abner fils de Ner, et Hamasa fils de Jéther, qu’il a tués, ayant répandu durant la paix le sang qu’on répand en temps de guerre, et ayant ensanglanté de ce sang qu’on répand en temps de guerre, la ceinture qu’il avait sur ses reins; et les souliers qu’il avait en ses pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Tu en feras donc selon ta sagesse, en sorte que tu ne laisseras point descendre paisiblement ses cheveux blancs au sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Mais tu feras du bien aux enfants de Barzillaï Galaadite, et ils seront du nombre de ceux qui mangent à ta table, parce qu’ils se sont ainsi approchés de moi quand je m’enfuyais de devant Absalom ton frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Voilà de plus avec toi Simhi, fils de Guéra, fils de Jémini de Bahurim, qui proféra contre moi des malédictions atroces, le jour que je m’en allais à Mahanajim; mais il descendit au devant de moi vers le Jourdain, et je lui jurai par l’Eternel, en disant: Je ne te ferai point mourir par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Maintenant donc tu ne le laisseras point impuni; car tu es sage, pour savoir ce que tu lui devras faire; et tu feras descendre ses cheveux blancs au sépulcre par une mort violente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Ainsi David s’endormit avec ses pères, et fut enseveli dans la Cité de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Et le temps que David régna sur Israël, fut quarante ans. Il régna sept ans à Hébron, et il régna trente-trois ans à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Et Salomon s’assit sur le trône de David son père, et son Royaume fut fort affermi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Alors Adonija fils de Haggith, vint vers Bath-sebah, mère de Salomon, et elle dit: Viens-tu à bonne intention? et il répondit: Je viens à bonne intention.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Puis il dit: J’ai un mot à te dire. Elle répondit: Parle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Et il dit: Tu sais bien que le Royaume m’appartenait, et que tout Israël s’attendait que je régnerais; mais le Royaume a été transféré, et il est échu à mon frère; parce que l’Eternel le lui a donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Maintenant donc j’ai à te faire une prière, ne me la refuse point. Et elle lui répondit: Parle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Et il dit: Je te prie, dis au Roi Salomon, car il ne te refusera rien, qu’il me donne Abisag Sunamite pour femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Et Bath-sebah répondit: Et bien, je parlerai pour toi au Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Bath-sebah vint donc au Roi Salomon lui parler pour Adonija; et le Roi se leva pour aller au devant de Bath-sebah, et se prosterna devant elle; puis il s’assit sur son trône, et fit mettre un siège pour sa mère, et elle s’assit à la main droite du Roi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Et dit: J’ai à te faire une petite demande, ne me la refuse point. Et le Roi lui répondit: Fais-la, ma mère; car je ne te la refuserai point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Et elle dit: Qu’on donne Abisag Sunamite pour femme à Adonija ton frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Mais le Roi Salomon répondit à sa mère, et dit: et pourquoi demandes-tu Abisag Sunamite pour Adonija? demande plutôt le Royaume pour lui, parce qu’il est mon frère plus âgé que moi; demande-le pour lui, pour Abiathar le Sacrificateur, et pour Joab fils de Tséruja.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Alors le Roi Salomon jura par l’Eternel, en disant: Que Dieu me fasse ainsi, et qu’ainsi il y ajoute, si Adonija n’a dit cette parole contre sa vie!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Or maintenant l’Eternel, qui m’a établi, et qui m’a fait asseoir sur le trône de David mon père, et qui m’a édifié une maison, comme il avait dit, est vivant, que certainement Adonija sera aujourd’hui mis à mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Et le Roi Salomon donna commission à Bénaja fils de Jéhojadah, qui se jeta sur lui, et il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Puis le Roi dit à Abiathar Sacrificateur: Va-t’en à Hanathoth dans ta possession, car tu mérites la mort; toutefois je ne te ferai point mourir aujourd’hui, parce que tu as porté l’Arche du Seigneur l’Eternel devant David mon père; et parce que tu as eu part à toutes les afflictions de mon père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Ainsi Salomon déposa Abiathar, afin qu’il ne fût plus Sacrificateur de l’Eternel; pour accomplir la parole de l’Eternel, qu’il avait prononcée en Silo contre la maison d’Héli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Et le bruit en étant venu jusqu’à Joab, qui s’était révolté pour suivre Adonija, quoiqu’il ne se fût point détourné après Absalom, il s’enfuit au Tabernacle de l’Eternel, et empoigna les cornes de l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Et on le rapporta au Roi Salomon, en disant: Joab s’en est enfui au Tabernacle de l’Eternel, et voilà, il est auprès de l’autel. Et Salomon envoya Bénaja fils de Jéhojadah, et lui dit: Va, jette-toi sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Bénaja donc entra au Tabernacle de l’Eternel, et dit à Joab: Ainsi a dit le Roi: Sors de là. Et il répondit: Non, mais je mourrai ici. Et Bénaja le rapporta au Roi, et dit: Joab m’a parlé ainsi, et m’a ainsi répondu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Et le Roi lui dit: Fais comme il t’a dit, et jette-toi sur lui, et l’ensevelis; et tu ôteras de dessus moi, et de dessus la maison de mon père, le sang que Joab a répandu sans cause.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Et l’Eternel fera retomber son sang sur sa tête, car il s’est jeté sur deux hommes plus justes et meilleurs que lui, et les a tués avec l’épée, sans que David mon père en sût rien; savoir Abner fils de Ner, chef de l’armée d’Israël; et Hamasa fils de Jéther, chef de l’armée de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Et leur sang retombera sur la tête de Joab, et sur la tête de sa postérité à toujours; mais il y aura paix de par l’Eternel, à toujours pour David, et pour sa postérité, et pour sa maison, et pour son trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Bénaja donc fils de Jéhojadah monta, et se jeta sur lui, et le tua; et on l’ensevelit dans sa maison au désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Alors le Roi établit Bénaja fils de Jéhojadah sur l’armée en la place de Joab; le Roi établit aussi Tsadok Sacrificateur en la place d’Abiathar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Puis le Roi envoya appeler Simhi, et lui dit: Bâtis-toi une maison à Jérusalem, et y demeure, et n’en sors point pour aller de côté ou d’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Car sache que le jour que tu en sortiras, et que tu passeras le torrent de Cédron, tu mourras certainement; ton sang sera sur ta tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Et Simhi répondit au Roi: Cette parole est bonne, ton serviteur fera tout ce que le Roi mon Seigneur a dit. Ainsi Simhi demeura à Jérusalem plusieurs jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Mais il arriva qu’au bout de trois ans, deux serviteurs de Simhi s’enfuirent vers Akis, fils de Mahaca Roi de Gath, et on le rapporta à Simhi en disant: Voilà tes serviteurs sont à Gath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Alors Simhi se leva, et sella son âne, et s’en alla à Gath vers Akis, pour chercher ses serviteurs; ainsi Simhi s’en alla, et ramena ses serviteurs de Gath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Et on rapporta à Salomon que Simhi était allé de Jérusalem à Gath, et qu’il était de retour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Et le Roi envoya appeler Simhi, et lui dit: Ne t’avais-je pas fait jurer par l’Eternel, et ne t’avais-je pas protesté, disant: Sache certainement que le jour que tu seras sorti, et que tu seras allé çà ou là, tu mourras certainement? et ne me répondis-tu pas: La parole que j’ai entendue est bonne?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Pourquoi donc n’as-tu pas gardé le serment que tu as fait par l’Eternel, et le commandement que je t’avais fait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Le Roi dit aussi à Simhi: Tu sais tout le mal que tu as fait à David mon père, et tu en es convaincu dans ton coeur; c’est pourquoi l’Eternel a fait retomber ton mal sur ta tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Mais le Roi Salomon sera béni, et le trône de David sera affermi devant l’Eternel à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Et le Roi donna commission à Bénaja fils de Jéhojadah, qui sortit, et se jeta sur lui; et il mourut. Et le Royaume fut affermi entre les mains de Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Or Salomon s’allia avec Pharaon Roi d’Egypte, et prit pour femme la fille de Pharaon, et l’amena en la Cité de David, jusqu’à ce qu’il eût achevé de bâtir sa maison, et la maison de l’Eternel, et la muraille de Jérusalem tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Seulement le peuple sacrifiait dans les hauts lieux, parce que jusques alors on n’avait point bâti de maison au Nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Et Salomon aima l’Eternel, marchant selon les ordonnances de David son père, seulement il sacrifiait dans les hauts lieux, et y faisait des parfums.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Le Roi donc s’en alla à Gabaon pour y sacrifier; car c’était le plus grand des hauts lieux; et Salomon sacrifia mille holocaustes sur l’autel qui était là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Et l’Eternel apparut de nuit à Salomon à Gabaon dans un songe, et Dieu lui dit: Demande ce que tu veux que je te donne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Et Salomon répondit: Tu as usé d’une grande gratuité envers ton serviteur David mon père, selon qu’il a marché devant toi en vérité, en justice, et en droiture de coeur envers toi, et tu lui as gardé cette grande gratuité de lui avoir donné un fils qui est assis sur son trône, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Or maintenant, ô Eternel mon Dieu! tu as fait régner ton serviteur en la place de David mon père, et je ne suis qu’un jeune homme, qui ne sait point comment il faut se conduire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Et ton serviteur est parmi ton peuple, que tu as choisi, et qui est un grand peuple qui ne se peut compter ni nombrer, tant il est en grand nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Donne donc à ton serviteur un coeur intelligent pour juger ton peuple, et pour discerner entre le bien et le mal; car qui pourrait juger ton peuple, qui est d’une si grande conséquence?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Et ce discours plut à l’Eternel, en ce que Salomon lui avait fait une telle demande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Et Dieu lui dit: Parce que tu m’as fait cette demande, et que tu n’as point demandé une longue vie, et que tu n’as point demandé des richesses, et que tu n’as point demandé la mort de tes ennemis, mais que tu as demandé de l’intelligence pour rendre la justice;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'Voici, j’ai fait selon ta parole; voici, je t’ai donné un coeur sage et intelligent, de sorte qu’il n’y en a point eu de semblable avant toi, et il n’y en aura point après toi qui te soit semblable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Et même je t’ai donné ce que tu n’as point demandé, savoir les richesses et la gloire, de sorte qu’il n’y aura point eu de Roi semblable à toi entre les Rois, tant que tu vivras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Et si tu marches dans mes voies pour garder mes ordonnances et mes commandements, comme David ton père y a marché, je prolongerai aussi tes jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Alors Salomon se réveilla, et voilà le songe. Puis il s’en retourna à Jérusalem, et se tint devant l’Arche de l’alliance de l’Eternel, et offrit des holocaustes et des sacrifices de prospérités, et fit un festin à tous ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Alors deux femmes de mauvaise vie vinrent au Roi, et se présentèrent devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Et l’une de ces femmes dit: Hélas, mon Seigneur! Nous demeurions cette femme-ci et moi dans une même maison, et j’ai accouché chez elle dans cette maison-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Le troisième jour après mon accouchement cette femme a aussi accouché, et nous étions ensemble; il n’y avait aucun étranger avec nous dans cette maison, nous étions seulement nous deux dans cette maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Or l’enfant de cette femme est mort la nuit, parce qu’elle s’était couchée sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Mais elle s’est levée à minuit, et a pris mon fils d’auprès de moi, pendant que ta servante dormait, et l’a couché dans son sein, et elle a couché dans mon sein son fils mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Et m’étant levée le matin pour allaiter mon fils, voilà, il était mort, mais l’ayant exactement considéré au matin, voilà, ce n’était point mon fils, que j’avais enfanté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Et l’autre femme répondit: Cela n’est pas ainsi, mais celui qui vit est mon fils, et celui qui est mort est ton fils. Mais l’autre dit: Cela n’est pas ainsi; mais celui qui est mort est ton fils, et celui qui vit est mon fils. Elles parlaient ainsi devant le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Et le Roi dit: Celle-ci dit, celui-ci qui est en vie est mon fils, et celui qui est mort est ton fils; et celle-là dit, cela n’est pas ainsi; mais celui qui est mort est ton fils, et celui qui vit est mon fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Alors le Roi dit: Apportez-moi une épée. Et on apporta une épée devant le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Et le Roi dit: Partagez en deux l’enfant qui vit, et donnez-en la moitié à l’une et la moitié à l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Alors la femme dont le fils était vivant, dit au Roi; car ses entrailles furent émues de compassion envers son fils: Hélas! mon Seigneur, qu’on donne à celle-ci l’enfant qui vit, et qu’on se garde bien de le faire mourir! Mais l’autre dit: Il ne sera ni à moi ni à toi; qu’on le partage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Alors le Roi répondit, et dit: Donnez à celle-ci l’enfant qui vit, et qu’on se garde bien de le faire mourir; celle-ci est la mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Et tous ceux d’Israël ayant entendu parler du jugement que le Roi avait rendu, craignirent le Roi; car ils reconnurent qu’il y avait en lui une sagesse divine pour rendre la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Le Roi Salomon donc fut Roi sur tout Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Et ceux-ci étaient les principaux Seigneurs de sa cour; Hazaria fils de Tsadok Sacrificateur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elihoreph et Ahija enfants de Sisa, Secrétaires; Jéhosaphat fils d’Ahilud, commis sur les Registres;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Bénaja fils de Jéhojadah avait la charge de l’armée; et Tsadok et Abiathar étaient les Sacrificateurs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Hazaria fils de Nathan avait la charge de ceux qui étaient commis sur les vivres; et Zabul fils de Nathan était le principal officier; et le favori du Roi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'et Ahisar était le grand-maître de la maison; et Adoniram fils de Habda, était commis sur les tributs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Or Salomon avait douze commissaires sur tout Israël, qui faisaient les provisions du Roi et de sa maison; et chacun avait un mois de l’année pour le pourvoir de vivres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Et ce sont ici leurs noms. Le fils de Hur était commis sur la montagne d’Ephraïm;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Le fils de Déker sur Makath, sur Sahalbim, sur Beth-sémes, sur Elon de Beth- hanan;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Le fils de Hésed sur Arubboth, et il avait Soco et tout le pays de Hépher;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Le fils d’Abinadab avait toute la contrée de Dor; il eut Taphath fille de Salomon pour femme;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Bahana fils d’Ahilud avait Tahanac et Méguiddo, et tout le pays de Beth- séan qui est vers le chemin tirant vers Tsarthan au dessous de Jizréhel, depuis Beth-séan jusqu’à Abelmeholah, et jusqu’au delà de Jokmeham;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Le fils de Guéber était commis sur Ramoth de Galaad, et il avait les bourgs de Jaïr fils de Manassé en Galaad; il avait aussi toute la contrée d’Argob en Basan, soixante grandes villes murées, et garnies de barres d’airain;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ahinadab fils de Hiddo était commis sur Mahanajim;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ahimahats, qui avait pour femme Basemath fille de Salomon, était commis sur Nephthali;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Bahana fils de Cusaï était commis sur Aser, et sur Haloth;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Jéhosaphat fils de Paruah, sur Issacar;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Simhi fils d’Ela, sur Benjamin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Guéber fils d’Uri, sur le pays de Galaad, qui avait été du pays de Sihon Roi des Amorrhéens, et de Hog Roi de Basan; et il était seul commis sur ce pays-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Juda et Israël étaient en grand nombre, comme le sable qui est sur le bord de la mer, tant ils étaient en grand nombre; ils mangeaient et buvaient, et se réjouissaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'Et Salomon dominait sur tous les Royaumes, depuis le fleuve jusqu’au pays des Philistins, et jusqu’à la frontière d’Egypte; et ils lui apportaient des présents, et lui furent assujettis tout le temps de sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'Or les vivres de Salomon pour chaque jour étaient trente Cores de fine farine, et soixante d’autre farine;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'Dix boeufs gras, et vingt boeufs des pâturages, et cent moutons; sans les cerfs, les daims, les buffles, et les volailles engraissées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Car il dominait sur toutes les contrées de deçà le fleuve, depuis Tiphsah jusqu’à Gaza, sur tous les Rois qui étaient deçà le fleuve, et il était en paix avec tous les pays d’alentour, de tous côtés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'Et Juda et Israël habitaient en assurance chacun sous sa vigne et sous son figuier, depuis Dan jusqu’à Beer-sebah, durant tout le temps de Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Salomon avait aussi quarante mille places à tenir des chevaux, et douze mille hommes de cheval.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'Or ces commis-là pourvoyaient de vivres le Roi Salomon, et tous ceux qui s’approchaient de la table du Roi Salomon, chacun en son mois, et ils ne les laissaient manquer de rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Ils faisaient aussi venir de l’orge et de la paille pour les chevaux et pour les genets, aux lieux où ils étaient, chacun selon la charge qu’il en avait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'Et Dieu donna de la sagesse à Salomon; et une fort grande intelligence, et une étendue d’esprit aussi grande que celle du sable qui est sur le bord de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'Et la sagesse de Salomon était plus grande que la sagesse de tous les Orientaux, et que toute la sagesse des Egyptiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Il était même plus sage que quelque homme que ce fût, plus qu’Ethan Ezrahite, qu’Héman, que Calcol, et que Dardah, les fils de Mahol; et sa réputation se répandit dans toutes les nations d’alentour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Il prononça trois mille paraboles, et fit cinq mille cantiques.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Il a aussi parlé des arbres, depuis le cèdre qui est au Liban, jusqu’à l’hysope qui sort de la muraille; il a aussi parlé des bêtes, des oiseaux, des reptiles, et des poissons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'Et il venait des gens d’entre tous les peuples pour entendre la sagesse de Salomon; et de la part de tous les Rois de la terre qui avaient entendu parler de sa sagesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Hiram aussi Roi de Tyr envoya ses serviteurs vers Salomon, ayant appris qu’on l’avait oint pour Roi en la place de son père; car Hiram avait toujours aimé David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Et Salomon envoya vers Hiram pour lui dire:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Tu sais que David mon père n’a pu bâtir une maison au Nom de l’Eternel son Dieu, à cause des guerres qui l’ont environné, jusqu’à ce que l’Eternel a eu mis ses ennemis sous ses pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Et maintenant l’Eternel mon Dieu m’a donné du repos tout alentour, et je n’ai point d’ennemis, ni d’affaire fâcheuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Voici donc je prétends bâtir une maison au Nom de l’Eternel mon Dieu, selon que l’Eternel en a parlé à David mon père en disant: Ton fils que je mettrai en ta place sur ton trône sera celui qui bâtira une maison à mon Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'C’est pourquoi commande maintenant qu’on coupe des cèdres du Liban, et que mes serviteurs soient avec tes serviteurs; et je te donnerai pour tes serviteurs telle récompense que tu me diras; car tu sais qu’il n’y a point de gens parmi nous qui s’entendent comme les Sidoniens, à couper le bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Or il arriva que quand Hiram eut entendu les paroles de Salomon, il s’en réjouit fort, et dit: Béni soit aujourd’hui l’Eternel, qui a donné à David un fils sage pour être Roi sur ce grand peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Hiram envoya donc vers Salomon pour lui dire: J’ai entendu ce que tu m’as envoyé dire, et je ferai tout ce que tu veux au sujet du bois de cèdre et du bois de sapin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Mes serviteurs les amèneront depuis le Liban jusqu’à la mer, puis je les ferai mettre sur la mer par radeaux, jusqu’au lieu que tu m’auras marqué, et je les ferai là délier, et tu les prendras, et de ton côté tu me satisferas en fournissant de vivres ma maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Hiram donc donnait du bois de cèdre et du bois de sapin à Salomon, autant qu’il en voulait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Et Salomon donnait à Hiram vingt mille Cores de froment pour la nourriture de sa maison, et vingt Cores d’huile très-pure; Salomon en donnait autant à Hiram chaque année.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Et l’Eternel donna de la sagesse à Salomon, comme l’Eternel lui en avait parlé; et il y eut paix entre Hiram et Salomon, et ils traitèrent alliance ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Le Roi Salomon fit aussi une levée de gens sur tout Israël, et la levée fut de trente mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Et il en envoyait dix mille au Liban chaque mois, tour à tour, ils étaient un mois au Liban, et deux mois en leur maison; et Adoniram était commis sur cette levée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Salomon avait aussi soixante-dix mille hommes qui portaient les faix, et quatre-vingt mille qui coupaient le bois sur la montagne;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Sans les Chefs des Commis de Salomon, qui avaient la charge de l’ouvrage, au nombre de trois mille trois cents, lesquels commandaient au peuple qui était employé à ce travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Et par le commandement du Roi, on amena de grandes pierres, et des pierres de prix, pour faire le fondement de la maison, qui étaient toutes taillées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'De sorte que les maçons de Salomon, et les maçons d’Hiram, et les tailleurs de pierres taillèrent et préparèrent le bois et les pierres pour bâtir la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Or il arriva qu’en l’année quatre cent quatre-vingt, après que les enfants d’Israël furent sortis du pays d’Egypte, la quatrième année du règne de Salomon sur Israël, au mois de Zif, qui est le second mois, il bâtit une maison à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Et la maison que le Roi Salomon bâtit à l’Eternel avait soixante coudées de long, et vingt de large, et trente coudées de haut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Le porche qui était devant le Temple de la maison, avait vingt coudées de long, qui répondait à la largeur de la maison, et il avait dix coudées de large sur le devant de la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Il fit aussi des fenêtres à la maison, larges par dedans, et rétrécies par dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Et joignant la muraille de la maison il bâtit des appentis de chambres l’une sur l’autre tout alentour, appuyés sur les murailles de la maison, tout autour du Temple, et de l’Oracle, ainsi il fit des chambres tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'La largeur de l’appentis d’en bas était de cinq coudées, et la largeur de celui du milieu était de six coudées, et la largeur du troisième était de sept coudées; car il avait fait des rétrécissements en la maison par dehors, afin que la charpenterie des appentis n’entrât pas dans les murailles de la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Or en bâtissant la maison on la bâtit de pierres amenées toutes telles qu’elles devaient être, de sorte qu’en bâtissant la maison on n’entendit ni marteau, ni hache, ni aucun outil de fer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'L’entrée des chambres du milieu était au côté droit de la maison, et on montait par une vis aux chambres du milieu; et de celles du milieu à celles du troisième étage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Il bâtit donc la maison, et l’acheva, et il couvrit la maison de lambris en voûte, et de poutres de cèdre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Et il bâtit les appentis joignant toute la maison, chacun de cinq coudées de haut, et ils tenaient à la maison par le moyen des bois de cèdre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Alors la parole de l’Eternel fut adressée à Salomon, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Quant à cette maison que tu bâtis, si tu marches dans mes statuts, et si tu fais mes ordonnances, et que tu gardes tous mes commandements, en y marchant, je ratifierai en ta faveur la parole que j’ai dite à David ton père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'Et j’habiterai au milieu des enfants d’Israël, et je n’abandonnerai point mon peuple d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Ainsi Salomon bâtit la maison, et l’acheva.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Il lambrissa d’ais de cèdre, les murailles de la maison par dedans, depuis le sol de la maison jusqu’à la voûte lambrissée; il les couvrit de bois par dedans, et il couvrit le sol de la maison d’ais de sapin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Il lambrissa aussi l’espace de vingt coudées d’ais de cèdre au fond de la maison, depuis le sol jusqu’au haut des murailles, et il lambrissa cet espace au dedans pour être l’Oracle, c’est-à-dire, le lieu Très-saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Mais la maison, savoir le Temple de devant, était de quarante coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Et les ais de cèdre qui étaient pour le dedans de la maison, étaient entaillés de boutons de fleurs épanouies, relevées en bosse; tout le dedans était de cèdre, on n’y voyait pas une pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Il disposa aussi l’Oracle au dedans de la maison vers le fond, pour y mettre l’Arche de l’alliance de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Et l’Oracle avait par devant vingt coudées de long, et vingt coudées de large, et vingt coudées de haut, et on le couvrit de fin or; on en couvrit aussi l’autel, fait d’ais de cèdre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Salomon donc couvrit de fin or la maison, depuis l’entredeux jusqu’au fond; et fit passer un voile avec des chaînes d’or au devant de l’Oracle, lequel il couvrit d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Ainsi il couvrit d’or toute la maison entièrement. Il couvrit aussi d’or tout l’autel qui était devant l’Oracle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Et il fit dans l’Oracle deux Chérubins de bois d’olivier, qui avaient chacun dix coudées de haut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'L’une des ailes de l’un des Chérubins avait cinq coudées, et l’autre aile du même Chérubin avait aussi cinq coudées; depuis le bout d’une aile jusqu’au bout de l’autre aile il y avait dix coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'L’autre Chérubin était aussi de dix coudées; car les deux Chérubins étaient d’une même mesure, et taillés l’un comme l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'La hauteur d’un Chérubin était de dix coudées, de même que celle de l’autre Chérubin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Et il mit les Chérubins au dedans de la maison vers le fond, et on étendit les ailes des Chérubins, en sorte que l’aile de l’un touchait à une muraille, et l’aile de l’autre Chérubin touchait à l’autre muraille; et leurs autres ailes se venaient joindre au milieu de la maison, et l’une des ailes touchait l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Et il couvrit d’or les Chérubins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Et il entailla toutes les murailles de la maison tout autour de sculptures bien profondes de Chérubins, et de palmes, et de boutons de fleurs épanouies, tant en la partie du dedans, qu’en celle du dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Il couvrit aussi d’or le sol de la maison, tant en la partie qui tirait vers le fond, qu’en celle du dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Et à l’entrée de l’Oracle il fit une porte à deux battants de bois d’olivier, dont les linteaux et les poteaux étaient de cinq membreures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Il fit donc une porte à deux battants de bois d’olivier, et entailla sur elle des moulures de Chérubins, de palmes, et de boutons de fleurs épanouies, et les couvrit d’or, étendant l’or sur les Chérubins et sur les palmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Il fit aussi à l’entrée du Temple des poteaux de bois d’olivier, de quatre membreures;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'Et une porte à deux battants de bois de sapin; les deux pièces d’un des battants étaient brisées; et les deux pièces de l’autre battant étaient aussi brisées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Et il y entailla des Chérubins, des palmes, et des boutons de fleurs épanouies, et les couvrit d’or, proprement posé sur les entailleures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Il bâtit aussi le parvis de dedans de trois rangées de pierres de taille, et d’une rangée de poutres de cèdre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'La quatrième année, au mois de Zif, les fondements de la maison de l’Eternel furent posés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'Et la onzième année, au mois de Bul, qui est le huitième mois, la maison fut achevée avec toutes ses appartenances et ses ordonnances; ainsi il mit sept ans à la bâtir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Salomon bâtit aussi sa maison, et l’acheva toute en treize ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Il bâtit aussi la maison du parc du Liban, de cent coudées de long, et de cinquante coudées de large, et de trente coudées de haut, sur quatre rangées de colonnes de cèdre; et sur les colonnes il y avait des poutres de cèdre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Il y avait aussi un couvert de bois de cèdre par dessus les chambres, qui était sur quarante-cinq colonnes, rangées de quinze en quinze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Et il y avait trois rangées de fenêtrages; et une fenêtre répondait à l’autre en trois endroits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Et toutes les portes et tous les poteaux étaient carrés, avec les fenêtres; et une fenêtre répondait à l’autre vis-à-vis en trois endroits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Il fit aussi un porche tout de colonnes, de cinquante coudées de long, et de trente coudées de large; et ce porche était au devant des colonnes de la maison, de sorte que les colonnes et les poutres étaient au devant d’elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Il fit aussi un porche pour le trône sur lequel il rendait ses jugements, appelé le Porche du jugement, et on le couvrit de cèdre depuis un bout du sol jusqu’à l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Et dans sa maison où il demeurait il y avait un autre parvis au dedans du porche, qui était du même ouvrage. Salomon fit aussi à la fille de Pharaon, qu’il avait épousée, une maison bâtie comme ce porche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Toutes ces choses étaient de pierres de prix, de la même mesure que les pierres de taille, sciées à la scie, en dedans et en dehors, depuis le fond jusqu’aux corniches, et par dehors jusqu’au grand parvis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Le fondement était aussi de pierres de prix, de grandes pierres, des pierres de dix coudées, et des pierres de huit coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Et par dessus il y avait des pierres de prix, de la même mesure que les pierres de taille, et que le bois de cèdre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Et le grand parvis avait aussi tout alentour trois rangées de pierres de taille, et une rangée de poutres de cèdre, comme le parvis de dedans la maison de l’Eternel, et le porche de la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Or le Roi Salomon avait fait venir de Tyr Hiram;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'fils d’une femme veuve de la Tribu de Nephthali, le père duquel était Tyrien, travaillant en cuivre; fort expert, intelligent, et savant pour faire toutes sortes d’ouvrages d’airain; il vint donc vers le Roi Salomon, et fit tout son ouvrage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Il fondit deux colonnes d’airain, la hauteur de l’une des colonne était de dix-huit coudées; et un réseau de douze coudées entourait l’autre colonne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Il fit aussi deux chapiteaux d’airain fondu pour mettre sur les sommets des colonnes; et la hauteur de l’un des chapiteaux était de cinq coudées, et la hauteur de l’autre chapiteau était aussi de cinq coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Il y avait des entrelassures en forme de rets, de filets entortillés en façon de chaînes, pour les chapiteaux qui étaient sur le sommet des colonnes, sept pour l’un des chapiteaux, et sept pour l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Et il les appropria aux colonnes, avec deux rangs de pommes de grenade sur un rets, tout autour, pour couvrir l’ un des chapiteaux qui était sur le sommet d’une des colonnes, et il fit la même chose pour l’autre chapiteau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Et les chapiteaux qui étaient sur le sommet des colonnes, étaient en façon de fleurs de lis, hauts de quatre coudées pour mettre au porche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Or les chapiteaux étaient sur les deux colonnes, ils étaient, dis-je, au dessus, depuis l’endroit du ventre qui était au delà du rets. Il y avait aussi deux cents pommes de grenade, disposées par rangs tout autour, sur le second chapiteau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Il dressa donc les colonnes au porche du Temple, et mit l’une à main droite et la nomma Jakin; et il mit l’autre à main gauche, et la nomma Boaz.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Et on posa sur le chapiteau des colonnes l’ouvrage fait en façon de fleurs de lis; ainsi l’ouvrage des colonnes fut achevé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Il fit aussi une mer de fonte qui avait dix coudées d’un bord à l’autre; ronde tout autour, de cinq coudées de haut; et un cordon de trente coudées l’environnait tout autour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Et il y avait tout autour, au dessous de son bord des figures de boeufs en relief, qui l’environnaient, dix à chaque coudée, lesquelles entouraient la mer tout autour. Il y avait deux rangées de ces figures de boeufs en relief, jetées en fonte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Et elle était posée sur douze boeufs, dont trois regardaient le Septentrion et trois regardaient l’Occident, et trois regardaient le Midi, et trois regardaient l’Orient. La mer était sur leurs dos, et tout le derrière de leurs corps était tourné en dedans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Son épaisseur était d’une paume, et son bord était comme le bord d’une coupe à façon de fleurs de lis; elle contenait deux mille baths.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Il fit aussi dix soubassements d’airain, ayant chacun quatre coudées de long, et quatre coudées de large, et trois coudées de haut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Or l’ouvrage de chaque soubassement était de telle manière, qu’ils avaient des châssis enchâssés entre des embâtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Et sur ces châssis, qui étaient entre les embâtements, il y avait des figures de lions, de boeufs, et de Chérubins. Et au dessus des embâtements il y avait un bassin sur le haut; et au dessous des figures de lions et de boeufs il y avait des corniches faites en pente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Et chaque soubassement avait quatre roues d’airain, avec des ais d’airain; et il y avait aux quatre angles certaines épaulières, qui se rendaient au dessous du cuvier au delà de toutes les corniches, sans qu’on s’en aperçût.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Or l’ouverture du cuvier, depuis le dedans du chapiteau en haut, était d’une coudée; mais l’ouverture du chapiteau était ronde de la façon du bassin, et elle était d’une coudée et demie, et sur les châssis de cette ouverture il y avait des gravures; ces ouvertures avaient aussi des châssis carrés, et non pas ronds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Et les quatre roues étaient au dessous des châssis; et les essieux des roues tenaient au soubassement; chaque roue avait la hauteur d’une coudée et demie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Et la façon des roues était selon la façon des roues de chariot; leurs essieux, leurs jantes, leurs moyeux, et leurs rayons étaient tous de fonte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Il y avait aussi quatre épaulières aux quatre angles de chaque soubassement, qui en étaient tirées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Il y avait aussi au sommet de chaque soubassement une demi-coudée de hauteur, qui était ronde tout autour; de sorte que chaque soubassement avait à son sommet ses tenons et ses châssis, qui en étaient tirés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Puis on grava les ais des tenons, et des châssis de chaque soubassement de figures de Chérubins, de lions et de palmes, selon le plan de chaque tenon, châssis, et corniche tout autour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Il fit les dix soubassements de cette même façon, ayant tous une même fonte, une même mesure, et une même entailleure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Il fit aussi dix cuviers d’airain, dont chacun contenait quarante baths, et chaque cuvier était de quatre coudées, chaque cuvier était sur chacun des dix soubassements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Et on mit cinq soubassements au côté droit du Temple, et cinq au côté gauche du Temple; et on plaça la mer au côté droit du Temple, tirant vers l’μOrient du côté du Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Ainsi Hiram fit des cuviers, et des racloirs, et des bassins, et il acheva de faire tout l’ouvrage qu’il faisait au Roi Salomon pour le Temple de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'Savoir, deux colonnes, et les deux bassins des chapiteaux qui étaient sur le sommet des colonnes; et deux réseaux pour couvrir les deux bassins qui étaient sur le sommet des colonnes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'Et quatre cents pommes de grenade pour les deux réseaux, de sorte qu’il y avait deux rangées de pommes de grenade pour chaque réseau, afin de couvrir les deux bassins des chapiteaux, qui étaient sur les colonnes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'Dix soubassements; et dix cuviers pour mettre sur les soubassements;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'Et une mer, et douze boeufs sous la mer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'Et des chaudrons, et des racloirs, et des bassins. Tous ces vaisseaux que Hiram fit au Roi Salomon pour le Temple de l’Eternel, étaient d’airain poli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'Le Roi les fit fondre en la plaine du Jourdain, dans une terre grasse, entre Succoth et Tsartan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Et Salomon ne pesa aucun de ces vaisseaux, parce qu’ils étaient en fort grand nombre; de sorte qu’on ne rechercha point le poids du cuivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Salomon fit aussi tous les ustensiles pour le Temple de l’Eternel, savoir l’autel d’or, et les tables d’or, sur lesquelles étaient les pains de proposition;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'Et cinq chandeliers de fin or à main droite, et cinq à main gauche devant l’Oracle, et les fleurs et les lampes, et les pincettes d’or;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'Et les coupes, les serpes, les bassins, les tasses, et les encensoirs de fin or. Les gonds même des portes de la maison de dedans, c’est-à-dire, du lieu Très-saint, et des portes de la maison, c’est-à-dire du Temple, étaient d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Ainsi tout l’ouvrage que le Roi Salomon fit pour la maison de l’Eternel fut achevé; puis il y fit apporter ce que David son père avait consacré, l’argent et l’or, et les vaisseaux, et le mit dans les trésors de la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Alors Salomon assembla devant lui à Jérusalem les Anciens d’Israël, et tous les chefs des Tribus, les principaux des pères des enfants d’Israël, pour transporter l’Arche de l’alliance de l’Eternel de la Cité de David, qui est Sion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Et tous ceux d’Israël furent assemblés vers le Roi Salomon, au mois d’Ethanim, qui est le septième mois, le jour même de la fête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Tous les Anciens d’Israël donc vinrent; et les Sacrificateurs portèrent l’Arche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'Ainsi on transporta l’Arche de l’Eternel, et le Tabernacle d’assignation, et tous les saints vaisseaux qui étaient au Tabernacle; les Sacrificateurs, dis- je, et les Lévites les emportèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Or le Roi Salomon, et toute l’assemblée d’Israël qui s’était rendue auprès de lui, étaient ensemble devant l’Arche et ils sacrifiaient du gros et du menu bétail en si grand nombre, qu’on ne le pouvait ni nombrer ni compter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Et les Sacrificateurs portèrent l’Arche de l’Alliance de l’Eternel en son lieu, dans l’Oracle de la maison, au lieu Très-saint, sous les ailes des Chérubins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Car les Chérubins étendaient les ailes sur l’endroit où devait être l’Arche, et les Chérubins couvraient l’Arche et ses barres, par dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Et ils retirèrent les barres en dedans, de sorte que les bouts des barres se voyaient du lieu Saint sur le devant de l’Oracle, mais ils ne se voyaient point au dehors; et elles sont demeurées là jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Il n’y avait rien dans l’Arche que les deux tables de pierre que Moïse y avait mises en Horeb, quand l’Eternel traita alliance avec les enfants d’Israël, lorsqu’ils furent sortis du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Or il arriva que comme les Sacrificateurs furent sortis du lieu Saint, une nuée remplit la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'De sorte que les Sacrificateurs ne se pouvaient tenir debout pour faire le service, à cause de la nuée; car la gloire de l’Eternel avait rempli la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Alors Salomon dit: L’Eternel a dit qu’il habiterait dans l’obscurité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'J’ai achevé, ô Eternel! de bâtir une maison pour ta demeure, un domicile fixe, afin que tu y habites éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Et le Roi tournant son visage, bénit toute l’assemblée d’Israël; car toute l’assemblée d’Israël se tenait là debout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Et il dit: Béni soit l’Eternel, le Dieu d’Israël, qui a parlé de sa propre bouche à David mon père, et qui l’a accompli par sa puissance, et a dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Depuis le jour que je retirai mon peuple d’Israël hors d’Egypte, je n’ai choisi aucune ville d’entre toutes les Tribus d’Israël pour y bâtir une maison, afin que mon Nom y fût; mais j’ai choisi David, afin qu’il eût la charge de mon peuple d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Et David mon père avait au coeur de bâtir une maison au Nom de l’Eternel, le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Mais l’Eternel dit à David mon père: Quant à ce que tu as eu au coeur de bâtir une maison à mon Nom, tu as bien fait d’avoir eu cela au coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Néanmoins tu ne bâtiras point cette maison, mais ton fils qui sortira de tes reins, sera celui qui bâtira cette maison à mon Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'L’Eternel a donc accompli sa parole, qu’il avait prononcée, et j’ai succédé à David mon père, et je suis assis sur le trône d’Israël, comme l’Eternel en avait parlé; et j’ai bâti cette maison au Nom de l’Eternel le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'Et j’ai assigné ici un lieu à l’Arche, dans laquelle est l’alliance de l’Eternel, qu’il traita avec nos pères, quand il les eut tirés hors du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Ensuite Salomon se tint devant l’autel de l’Eternel en la présence de toute l’assemblée d’Israël, et ayant ses mains étendues vers les cieux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'Il dit: Ô Eternel Dieu d’Israël! il n’y a point de Dieu semblable à toi dans les cieux en haut, ni sur la terre en bas; tu gardes l’alliance et la gratuité envers tes serviteurs, qui marchent de tout leur coeur devant ta face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Et tu as tenu à ton serviteur David mon père ce dont tu lui avais parlé; car ce dont tu lui avais parlé de ta bouche, tu l’as accompli de ta main, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Maintenant donc, ô Eternel Dieu d’Israël! tiens à ton serviteur David mon père, ce dont tu lui as parlé, en disant: Jamais il ne te sera retranché de devant ma face un successeur pour être assis sur le trône d’Israël, pourvu seulement que tes fils prennent garde à leur voie, afin de marcher devant ma face, comme tu y as marché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Et maintenant, ô Dieu d’Israël! je te prie, que ta parole, laquelle tu as prononcée à ton serviteur David mon père, soit ratifiée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Mais Dieu habiterait-il effectivement sur la terre? Voilà, les cieux, même les cieux des cieux ne te peuvent contenir; combien moins cette maison que j’ai bâtie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Toutefois, ô Eternel mon Dieu! aie égard à la prière de ton serviteur, et à sa supplication, pour entendre le cri et la prière que ton serviteur te fait aujourd’hui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Qui est, que tes yeux soient ouverts jour et nuit sur cette maison, le lieu dont tu as dit: Mon nom sera là, pour exaucer la prière que ton serviteur fait en ce lieu-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Exauce donc la supplication de ton serviteur, et de ton peuple d’Israël quand ils te prieront en ce lieu-ci; exauce -les, dis-je, du lieu de ta demeure, des cieux; exauce, et pardonne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Quand quelqu’un aura péché contre son prochain, et qu’on lui aura déféré le serment pour le faire jurer, et que le serment aura été fait devant ton autel dans cette maison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'Exauce -les toi des cieux, et exécute ce que portera l’exécration du serment, et juge tes serviteurs en condamnant le méchant, et lui rendant selon ce qu’il aura fait; et en justifiant le juste, et lui rendant selon sa justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Quand ton peuple d’Israël aura été battu par l’ennemi, à cause qu’ils auront péché contre toi, si ensuite ils se retournent vers toi, en réclamant ton nom, et en te faisant des prières et des supplications dans cette maison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'Exauce -les, toi, des cieux, et pardonne le péché de ton peuple d’Israël, et ramène-les dans la terre que tu as donnée à leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Quand les cieux seront resserrés, et qu’il n’y aura point de pluie, à cause que ceux d’Israël auront péché contre toi, s’ils te font prière en ce lieu- ci, et s’ils réclament ton Nom, et s’ils se détournent de leurs péchés, parce que tu les auras affligés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'Exauce -les, toi, des cieux, et pardonne le péché de tes serviteurs, et de ton peuple d’Israël, lorsque tu leur auras enseigné le bon chemin, par lequel ils doivent marcher, et envoie-leur la pluie sur la terre que tu as donnée à ton peuple pour héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Quand il y aura famine au pays, ou la mortalité; quand il y aura brûlure, nielle, sauterelles, et vermisseaux, même quand les ennemis les assiégeront jusques dans leur propre pays, ou qu’il y aura plaie, ou maladie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'Quelque prière, et quelque supplication que te fasse quelque homme que ce soit de tout ton peuple d’Israël, selon qu’ils auront connu chacun la plaie de son cœur; et que chacun aura étendu ses mains vers cette maison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'Alors exauce -les, toi, des cieux, du domicile arrêté de ta demeure, et pardonne, et fais, et rends à chacun selon toutes ses voies, parce que tu auras connu son coeur; car tu connais toi-seul le coeur de tous les hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'Afin qu’ils te craignent tout le temps qu’ils vivront sur la terre que tu as donnée à nos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Et même lorsque l’étranger qui ne sera pas de ton peuple d’Israël, mais qui sera venu d’un pays éloigné pour l’amour de ton Nom;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(Car on entendra parler de ton Nom, qui est grand, et de ta main forte, et de ton bras étendu;) lors donc qu’il sera venu, et qu’il te priera dans cette maison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'Exauce -le, toi, des cieux, du domicile arrêté de ta demeure, et fais selon tout ce pour quoi cet étranger aura crié vers toi; afin que tous les peuples de la terre connaissent ton Nom pour te craindre, comme ton peuple d’Israël; et pour connaître que ton Nom est réclamé sur cette maison que j’ai bâtie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Quand ton peuple sera sorti en guerre contre son ennemi, dans le chemin par lequel tu l’auras envoyé, s’ils font prière à l’Eternel en regardant vers cette ville que tu as choisie, et vers cette maison que j’ai bâtie à ton Nom;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'Alors exauce des cieux leur prière et leur supplication, et maintiens leur droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Quand ils auront péché contre toi, car il n’y a point d’homme qui ne pèche, et que tu seras irrité contr’eux, tellement que tu les auras livrés entre les mains de leurs ennemis, et que ceux qui les auront pris les auront menés captifs en pays ennemi, soit loin, soit près;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'Si au pays où ils auront été menés captifs, ils reviennent à eux-mêmes, et se repentant ils te prient au pays de ceux qui les auront emmenés captifs, en disant: Nous avons péché, nous avons fait iniquité, et nous avons fait méchamment;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'S’ils retournent donc à toi de tout leur coeur et de toute leur âme, dans le pays de leurs ennemis, qui les auront emmenés captifs, et s’ils t’adressent leurs prières, en regardant vers leur pays que tu as donné à leurs pères, vers cette ville que tu as choisie, et vers cette maison que j’ai bâtie à ton Nom;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'Alors exauce des cieux, du domicile arrêté de ta demeure, leur prière, et leur supplication, et maintiens leur droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'Et pardonne à ton peuple qui aura péché contre toi, et même pardonne-leur tous les crimes qu’ils auront commis contre toi, et fais que ceux qui les auront emmenés captifs aient pitié d’eux, et leur fassent grâce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Car ils sont ton peuple et ton héritage, que tu as tiré hors d’Egypte, du milieu d’un fourneau de fer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Que tes yeux donc soient ouverts sur la prière de ton serviteur, et sur la supplication de ton peuple d’Israël, pour les exaucer dans tout ce pourquoi ils crieront à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Car tu les as mis à part pour toi d’entre tous les peuples de la terre, afin qu’ils fussent ton héritage, comme tu en as parlé par le moyen de Moïse ton serviteur, quand tu retiras nos pères hors d’Egypte, ô Seigneur Eternel!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Or aussitôt que Salomon eut achevé de faire toute cette prière, et cette supplication à l’Eternel, il se leva de devant l’autel de l’Eternel, et n’étant plus à genoux, mais ayant encore les mains étendues vers les cieux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'Il se tint debout, et bénit toute l’assemblée d’Israël à haute voix, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Béni soit l’Eternel, qui a donné du repos à son peuple d’Israël, comme il en avait parlé; il n’est pas tombé à terre un seul mot de toutes les bonnes paroles qu’il avait prononcées par le moyen de Moïse son serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Que l’Eternel notre Dieu soit avec nous, comme il a été avec nos pères; qu’il ne nous abandonne point, et qu’il ne nous délaisse point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Mais qu’il incline notre coeur vers lui, afin que nous marchions en toutes ses voies, et que nous gardions ses commandements, ses statuts, et ses ordonnances qu’il a prescrites à nos pères;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Et que mes paroles, par lesquelles j’ai fait supplication à l’Eternel, soient présentes devant l’Eternel notre Dieu jour et nuit; afin qu’il maintienne le droit de son serviteur, et le droit de son peuple d’Israël, selon qu’il en aura besoin chaque jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'Afin que tous les peuples de la terre connaissent que c’est l’Eternel qui est Dieu, et qu’il n’y en a point d’autre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Et afin que votre coeur soit pur envers l’Eternel votre Dieu, pour marcher dans ses statuts, et pour garder ses commandements, comme aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Et le Roi, et tout Israël avec lui, sacrifièrent des sacrifices devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Et Salomon offrit un sacrifice de prospérités, qu’il sacrifia à l’Eternel, savoir, vingt et deux mille boeufs, et six vingt mille brebis. Ainsi le Roi et tous les enfants d’Israël dédièrent la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'En ce jour-là le Roi consacra le milieu du parvis, qui était devant la maison de l’Eternel; car il offrit là les holocaustes, et les gâteaux, et les graisses des sacrifices de prospérités, parce que l’autel d’airain qui était devant l’Eternel, était trop petit pour contenir les holocaustes, et les gâteaux, et les graisses des sacrifices de prospérités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Et en ce temps-là Salomon célébra une fête solennelle; et avec lui tout Israël qui était une grande assemblée, venue depuis où l’on entre en Hamath jusqu’au torrent d’Egypte, devant l’Eternel notre Dieu, et cela dura sept jours, et sept autres jours, ce qui fut quatorze jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Et au huitième jour il renvoya le peuple, qui bénit le Roi; puis ils s’en allèrent dans leurs tentes, en se réjouissant, et ayant le coeur plein de joie à cause de tout le bien que l’Eternel avait fait à David son serviteur, et à Israël son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Or après que Salomon eut achevé de bâtir la maison de l’Eternel, et la maison Royale, et tout ce que Salomon avait pris plaisir et souhaité de faire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'L’Eternel lui apparut pour la seconde fois comme il lui était apparu à Gabaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Et l’Eternel lui dit: J’ai exaucé ta prière, et la supplication que tu as faite devant moi; j’ai sanctifié cette maison que tu as bâtie pour y mettre mon Nom éternellement, et mes yeux et mon coeur seront toujours là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Quant à toi, si tu marches devant moi comme David ton père a marché, en intégrité et en droiture de coeur, faisant tout ce que je t’ai commandé, et si tu gardes mes statuts et mes ordonnances;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'Alors j’affermirai le trône de ton Royaume sur Israël à jamais, selon que j’en ai parlé à David ton père, en disant: Il ne te sera point retranché de successeur sur le trône d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Mais si vous et vos fils, vous vous détournez de moi, et que vous ne gardiez pas mes commandements et mes statuts, lesquels je vous ai proposés, et que vous vous en alliez et serviez d’autres dieux, et que vous vous prosterniez devant eux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'Je retrancherai Israël de dessus la terre que je leur ai donnée, et je rejetterai de devant moi cette maison que j’ai consacrée à mon Nom, et Israël sera en dérision et en moquerie à tous les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Et quant à cette maison qui aura été haut élevée, quiconque passera auprès d’elle sera étonné, et sifflera; et on dira: Pourquoi l’Eternel a-t-il fait ainsi à ce pays, et à cette maison?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Et on répondra: Parce qu’ils ont abandonné l’Eternel leur Dieu, qui avait tiré leurs pères hors du pays d’Egypte, et qu’ils se sont arrêtés à d’autres dieux, et se sont prosternés devant eux, et les ont servis, à cause de cela l’Eternel a fait venir sur eux tout ce mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Or il arriva qu’au bout des vingt ans, pendant lesquels Salomon bâtit les deux maisons, la maison de l’Eternel, et la maison Royale;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'Hiram Roi de Tyr ayant fait amener à Salomon du bois de cèdre, du bois de sapin, et de l’or, autant qu’il en avait voulu, le Roi Salomon donna à Hiram vingt villes dans le pays de Galilée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Et Hiram sortit de Tyr pour voir les villes que Salomon lui avait données, lesquelles ne lui plurent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Et il dit: Quelles villes m’as-tu données, mon frère? et il les appela, pays de Cabul, qui a été ainsi appelé jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Hiram avait aussi envoyé au Roi six vingts talents d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Or le Roi Salomon imposa un tribut, pour bâtir la maison de l’Eternel, et sa maison, et Millo, et la muraille de Jérusalem, et Hatsor, et Méguiddo, et Guézer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, '(Car Pharaon Roi d’Egypte était monté, et avait pris Guézer, et l’avait brûlée, et il avait tué les Cananéens qui habitaient en cette ville; mais il la donna pour dot à sa fille, femme de Salomon.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Salomon donc bâtit Guézer; et Beth-horon la basse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Et Bahalath, et Tadmor, au désert qui est au pays;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'Et toutes les villes de munitions qu’eut Salomon, et les villes où il tenait ses chariots, et les villes où il tenait ses gens de cheval, et ce que Salomon prit plaisir de bâtir à Jérusalem, et au Liban, et dans tout le pays de sa domination.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Et quant à tous les peuples qui étaient restés des Amorrhéens, des Héthiens, des Phérésiens, des Héviens, et des Jébusiens qui n’étaient point des enfants d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'Savoir quant à leurs enfants, qui étaient demeurés après eux au pays, et que les enfants d’Israël n’avaient pu détruire à la façon de l’interdit, Salomon les rendit tributaires, et les asservit jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Mais Salomon ne souffrit point qu’aucun des enfants d’Israël fût asservi; mais ils étaient gens de guerre, et ses officiers, et ses principaux chefs, et ses capitaines, et chefs de ses chariots, et ses hommes d’armes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Il y en avait aussi cinq cent cinquante qui étaient les principaux chefs de ceux qui étaient établis sur l’ouvrage de Salomon, lesquels avaient l’intendance sur le peuple qui faisait l’ouvrage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Or la fille de Pharaon monta de la Cité de David en sa maison, que Salomon lui avait bâtie; et alors il bâtit Millo.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Et trois fois par an Salomon offrait des holocaustes et des sacrifices de prospérités sur l’autel qu’il avait bâti à l’Eternel, et faisait des parfums sur celui qui était devant l’Eternel, après qu’il eut achevé la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Le Roi Salomon équipa aussi une flotte à Hetsjon-guéber, qui est près d’Eloth, sur le rivage de la mer Rouge, au pays d’Edom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Et Hiram envoya de ses serviteurs, gens de mer, et qui entendaient la marine, pour être avec les serviteurs de Salomon dans cette flotte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Et ils allèrent en Ophir, et prirent de là quatre cent vingt talents d’or; lesquels ils apportèrent au Roi Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Or la reine de Séba ayant appris la renommée de Salomon à cause du Nom de l’Eternel, le vint éprouver par des questions obscures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Et elle entra dans Jérusalem avec un fort grand train, et avec des chameaux qui portaient des choses aromatiques, et une grande quantité d’or, et de pierres précieuses; et étant venue à Salomon, elle lui parla de tout ce qu’elle avait en son coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Et Salomon lui expliqua tout ce qu’elle avait proposé; il n’y eut rien que le Roi n’entendît, et qu’il ne lui expliquât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Alors la Reine de Séba voyant toute la sagesse de Salomon, et la maison qu’il avait bâtie,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'Et les mets de sa table, le logement de ses serviteurs, l’ordre du service de ses officiers, leurs vêtements, ses échansons, et les holocaustes qu’il offrait dans la maison de l’Eternel, elle fut toute ravie en elle-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Et elle dit au Roi: Ce que j’ai appris dans mon pays de ton état et de ta sagesse, est véritable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Et je n’ai point cru ce qu’on en disait, jusqu’à ce que je sois venue, et que mes yeux l’aient vu; et voici on ne m’en avait point rapporté la moitié; ta sagesse et tes richesses surpassent tout ce que j’en avais entendu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Ô que bienheureux sont tes gens! ô que bienheureux sont tes serviteurs qui se tiennent continuellement devant toi, et qui écoutent ta sagesse!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Béni soit l’Eternel ton Dieu, qui t’a eu pour agréable, afin de te mettre sur le trône d’Israël; car l’Eternel a aimé Israël à toujours; et t’a établi Roi pour faire jugement et justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Puis elle fit présent au Roi de six vingts talents d’or, et d’une grande quantité de choses aromatiques, avec des pierres précieuses. Il ne vint jamais depuis une aussi grande abondance de choses aromatiques, que la Reine de Séba en donna au Roi Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Et la flotte d’Hiram, qui avait apporté de l’or d’Ophir, apporta aussi en fort grande abondance du bois d’Almugghim, et des pierres précieuses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Et le Roi fit des barrières de ce bois d’Almugghim, pour la maison de l’Eternel, et pour la maison Royale; il en fit aussi des violons, et des musettes pour les chantres; il n’était point venu de ce bois d’Almugghim, et on n’en avait point vu jusqu’à ce jour-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Et le Roi Salomon donna à la Reine de Séba tout ce qu’elle souhaita, et ce qu’elle lui demanda, outre ce qu’il lui donna selon la puissance d’un Roi tel que Salomon. Puis elle s’en retourna, et revint en son pays, avec ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Le poids de l’or qui revenait à Salomon chaque année, était de six cent soixante et six talents d’or;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'Sans ce qui lui revenait des facteurs marchands en gros, et de la marchandise de ceux qui vendaient en détail, et de tous les Rois d’Arabie, et des Gouverneurs de ce pays-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Le Roi Salomon fit aussi deux cents grands boucliers d’or étendu au marteau, employant six cents pièces d’or pour chaque bouclier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'Et trois cents autres boucliers d’or étendu au marteau, employant trois mines d’or pour chaque bouclier; et le Roi les mit dans la maison du parc du Liban.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Le Roi fit aussi un grand trône d’ivoire, qu’il couvrit de fin or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Ce trône avait six degrés, et le haut du trône était rond par derrière, il y avait des accoudoirs de côté et d’autre à l’endroit du siège, et deux lions étaient auprès des accoudoirs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Il y avait aussi douze lions sur les six degrés du trône, de côté et d’autre; il ne s’en est point fait de tel dans tous les Royaumes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Et toute la vaisselle du buffet du Roi Salomon était d’or; et tous les vaisseaux de la maison du parc du Liban étaient de fin or; il n’y en avait point d’argent; l’argent n’était rien estimé du temps de Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Car le Roi avait sur mer la flotte de Tarsis avec la flotte d’Hiram; et en trois ans une fois la flotte de Tarsis revenait, qui apportait de l’or, de l’argent, de l’ivoire, des singes, et des paons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Ainsi le Roi Salomon fut plus grand que tous les Rois de la terre, tant en richesses qu’en sagesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Et tous les habitants de la terre recherchaient de voir la face de Salomon, pour entendre la sagesse que Dieu avait mise en son coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Et chacun d’eux lui apportait son présent, savoir, des vaisseaux d’argent, des vaisseaux d’or, des vêtements, des armes, des choses aromatiques, et on lui amenait des chevaux, et des mulets, tous les ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Salomon fit aussi amas de chariots et de gens de cheval; tellement qu’il avait mille et quatre cents chariots, et douze mille hommes de cheval, qu’il fit conduire dans les villes où il tenait ses chariots; il y en avait aussi auprès du Roi à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Et le Roi fit que l’argent n’était non plus prisé à Jérusalem que les pierres; et les cèdres que les figuiers sauvages qui sont dans les plaines, tant il y en avait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Or quant au péage qui appartenait à Salomon, de la traite des chevaux qu’on tirait d’Egypte, et du fil, les fermiers du Roi se payaient en fil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Mais chaque chariot montait et sortait d’Egypte pour six cents pièces d’argent, et chaque cheval pour cent cinquante; et ainsi on en tirait par le moyen de ses fermiers pour tous les Rois des Héthiens, et pour les Rois de Syrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Or le Roi Salomon aima plusieurs femmes étrangères, outre la fille de Pharaon; savoir des Moabites, des Hammonites, des Iduméènnes, des Sidoniènnes et des Héthiènes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'Qui étaient d’entre les nations dont l’Eternel avait dit aux enfants d’Israël: Vous n’irez point vers elles, et elles ne viendront point vers vous; car certainement elles feraient détourner votre coeur pour suivre leurs dieux. Salomon s’attacha à elles, et les aima.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Il eut donc sept cents femmes Princesses, et trois cents concubines; et ses femmes firent égarer son coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Car il arriva sur le temps de la vieillesse de Salomon, que ses femmes firent détourner son coeur après d’autres dieux; et son coeur ne fut point droit devant l’Eternel son Dieu, comme avait été le coeur de David son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Et Salomon marcha après Hastaroth, la divinité des Sidoniens, et après Milcom, l’abomination des Hammonites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Ainsi Salomon fit ce qui déplaît à l’Eternel, et il ne persévéra point à suivre l’Eternel, comme avait fait David son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Et Salomon bâtit un haut lieu à Kémos, l’abomination des Moabites, sur la montagne qui est vis-à-vis de Jérusalem; et à Molec, l’abomination des enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Il en fit de même pour toutes ses femmes étrangères, qui faisaient des encensements et qui sacrifiaient à leurs dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'C’est pourquoi l’Eternel fut irrité contre Salomon, parce qu’il avait détourné son coeur de l’Eternel le Dieu d’Israël, qui lui était apparu deux fois;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'Et qui même lui avait fait ce commandement exprès, qu’il ne marchât point après d’autres dieux; mais il ne garda point ce que l’Eternel lui avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Et l’Eternel dit à Salomon: Parce que ceci a été en toi, que tu n’as pas gardé mon alliance et mes ordonnances que je t’avais prescrites, certainement je déchirerai le Royaume, afin qu’il ne soit plus à toi, et je le donnerai à ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Toutefois pour l’amour de David ton père je ne le ferai point en ton temps; ce sera d’entre les mains de ton fils que je déchirerai le Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Néanmoins je ne déchirerai pas tout le Royaume, j’en donnerai une Tribu à ton fils, pour l’amour de David mon serviteur, et pour l’amour de Jérusalem, que j’ai choisie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'L’Eternel donc suscita un ennemi à Salomon, savoir Hadad Iduméen, qui était de la race Royale d’Edom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Car il était arrivé qu’au temps que David était en Edom, lorsque Joab Chef de l’armée monta pour ensevelir ceux qui avaient été tués, comme il tuait tous les mâles d’Edom;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(Car Joab demeura là six mois avec tout Israël, jusqu’à ce qu’il eût exterminé tous les mâles d’Edom,)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Hadad s’était enfui, avec quelques Iduméens qui étaient d’entre les serviteurs de son père, pour se retirer en Egypte; et Hadad était alors fort jeune.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Et quand ils furent partis de Madian, ils vinrent à Paran, et prirent avec eux des gens de Paran, et se retirèrent en Egypte vers Pharaon Roi d’Egypte, qui lui donna une maison, et lui assigna de quoi vivre, et lui donna aussi une terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Et Hadad fut fort dans les bonnes grâces de Pharaon, de sorte qu’il le maria à la soeur de sa femme, la soeur de la Reine Tachpenès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Et la soeur de Tachpenès lui enfanta son fils Guénubath, que Tachpenès sevra dans la maison de Pharaon. Ainsi Guénubath était de la maison de Pharaon, entre les fils de Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Or quand Hadad eut appris en Egypte que David s’était endormi avec ses pères, et que Joab Chef de l’armée était mort, il dit à Pharaon: Donne-moi mon congé, et je m’en irai en mon pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Et Pharaon lui répondit: Mais de quoi as-tu besoin étant avec moi, pour demander ainsi de t’en aller en ton pays? et il dit: Je n’ai besoin de rien; mais cependant donne-moi mon congé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Dieu suscita aussi un autre ennemi à Salomon, savoir Rézon fils d’Eljadah, qui s’en était fui d’avec son Seigneur Hadar-hézer, Roi de Tsoba,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Qui assembla des gens contre lui, et fut Chef de quelques bandes, quand David les défit; et ils s’en allèrent à Damas, et y demeurèrent, et y régnèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Rézon donc fut ennemi d’Israël tout le temps de Salomon, outre le mal que fit Hadad; et il donna du chagrin à Israël, et régna sur la Syrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Jéroboam aussi fils de Nébat, Ephratien, de Tséréda, dont la mère avait nom Tséruha, femme veuve, serviteur de Salomon, s’éleva contre le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Et ce fut ici l’occasion pour laquelle il s’éleva contre le Roi; c’est que quand Salomon bâtissait Millo, et comblait le creux de la Cité de David son père;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Là se trouva Jéroboam, qui était un homme fort et vaillant; et Salomon voyant que ce jeune homme travaillait, le commit sur toute la charge de la maison de Joseph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Or il arriva en ce même temps, que Jéroboam étant sorti de Jérusalem, Ahija Silonite, Prophète, vêtu d’une robe neuve, le trouva dans le chemin, et ils étaient eux deux tout seuls aux champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Et Ahija prit la robe neuve qu’il avait sur lui, et la déchira en douze pièces;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'Et il dit à Jéroboam: Prends-en pour toi dix pièces; car ainsi a dit l’Eternel le Dieu d’Israël: Voici, je m’en vais déchirer le Royaume d’entre les mains de Salomon, et je t’en donnerai dix Tribus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Mais il en aura une Tribu, pour l’amour de David mon serviteur, et pour l’amour de Jérusalem, qui est la ville que j’ai choisie d’entre toutes les Tribus d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'Parce qu’ils m’ont abandonné, et se sont prosternés devant Hastaroth le dieu des Sidoniens, devant Kémos le dieu de Moab, et devant Milcom le dieu des enfants de Hammon, et qu’ils n’ont point marché dans mes voies, pour faire ce qui est droit devant moi, et pour garder mes statuts, et mes ordonnances, comme avait fait David, père de Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Toutefois je n’ôterai rien de ce Royaume d’entre ses mains; car tout le temps qu’il vivra je le maintiendrai Prince, pour l’amour de David mon serviteur que j’ai choisi, et qui a gardé mes commandements et mes statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Mais j’ôterai le Royaume d’entre les mains de son fils, et je t’en donnerai dix Tribus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'Et j’en donnerai une Tribu à son fils, afin que David mon serviteur ait une Lampe à toujours devant moi dans Jérusalem, qui est la ville que j’ai choisie pour y mettre mon Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Je te prendrai donc, et tu régneras sur tout ce que ton âme souhaitera, et tu seras Roi sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Et il arrivera que si tu m’obéis en tout ce que je te commanderai, et que tu marches dans mes voies, et que tu fasses tout ce qui est droit devant moi, en gardant mes statuts et mes commandements, comme a fait David mon serviteur, je serai avec toi, et je te bâtirai une maison qui sera stable, comme j’en ai bâti une à David, et je te donnerai Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Ainsi j’affligerai la postérité de David à cause de cela, mais non pas à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Salomon donc chercha de faire mourir Jéroboam; mais Jéroboam se leva, et s’enfuit en Egypte vers Sisak Roi d’Egypte; et il demeura en Egypte jusqu’à la mort de Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Or le reste des faits de Salomon, tout ce qu’il a fait, et sa sagesse, cela n’est-il pas écrit au Livre des faits de Salomon?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Or le temps que Salomon régna à Jérusalem sur tout Israël fut quarante ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Ainsi Salomon s’endormit avec ses pères, et il fut enseveli dans la Cité de David son père; et Roboam son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Et Roboam s’en alla à Sichem, parce que tout Israël était allé à Sichem pour l’établir Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Or il arriva que quand Jéroboam fils de Nébat, qui était encore en Egypte, où il s’était enfui de devant le Roi Salomon, l’eut appris, il se tint encore en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Mais on l’envoya appeler. Ainsi Jéroboam et toute l’assemblée d’Israël vinrent, et parlèrent à Roboam, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Ton père a mis sur nous un pesant joug; mais toi allège maintenant cette rude servitude de ton père, et ce pesant joug qu’il a mis sur nous, et nous te servirons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Et il leur répondit: Allez, et dans trois jours retournez vers moi; et le peuple s’en alla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Et le Roi Roboam consulta les vieillards qui avaient été auprès de Salomon son père, pendant sa vie, et leur dit: Comment et quelle chose me conseillez- vous de répondre à ce peuple?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Et ils lui répondirent, en disant: Si aujourd’hui tu te rends facile à ce peuple, et que tu lui cèdes, et que tu leur répondes avec douceur, ils seront tes serviteurs à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Mais il laissa le conseil que les vieillards lui avaient donné, et consulta les jeunes gens qui avaient été nourris avec lui, et qui étaient auprès de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Et il leur dit: Que me conseillez-vous de répondre à ce peuple, qui m’a parlé, en disant: Allège le joug que ton père a mis sur nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Alors les jeunes gens qui avaient été nourris avec lui, lui parlèrent, et lui dirent: Tu parleras ainsi à ce peuple qui t’est venu dire: Ton père a mis sur nous un pesant joug, mais toi allège-le-nous; tu leur parleras ainsi: Ce qui est le plus petit en moi, est plus gros que les reins de mon père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Or mon père a mis sur vous un pesant joug, mais moi je rendrai votre joug encore plus pesant; mon père vous a châtiés avec des verges, mais moi je vous châtierai avec des écourgées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Or trois jours après Jéroboam avec tout le peuple vint vers Roboam, selon que le Roi leur avait dit: Retournez vers moi dans trois jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Mais le Roi répondit durement au peuple, laissant le conseil que les vieillards lui avaient donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'Et il leur parla selon le conseil des jeunes gens, et leur dit: Mon père a mis sur vous un pesant joug, mais moi, je rendrai votre joug encore plus pesant; mon père vous a châtiés avec des verges, mais moi, je vous châtierai avec des écourgées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Le Roi donc n’écouta point le peuple; car cela était ainsi conduit par l’Eternel, pour ratifier la parole qu’il avait prononcée par le ministère d’Ahija Silonite, à Jéroboam, fils de Nébat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Et quand tout Israël eut vu que le Roi ne les avait point écoutés, le peuple fit cette réponse au Roi, en disant: Quelle part avons-nous en David? nous n’avons point d’héritage au fils d’Isaï. Israël, retire-toi dans tes tentes; et toi David pourvois maintenant à ta maison; ainsi Israël s’en alla dans ses tentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Mais quant aux enfants d’Israël qui habitaient dans les villes de Juda, Roboam régna sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Or le Roi Roboam envoya Adoram, qui était commis sur les tributs, mais tout Israël l’assomma de pierres, et il mourut. Alors le Roi Roboam se hâta de monter sur un chariot, pour s’enfuir à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Ainsi Israël se rebella contre la maison de David jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Et il arriva qu’aussitôt que tout Israël eut appris que Jéroboam s’en était retourné, ils l’envoyèrent appeler dans l’assemblée, et l’établirent Roi sur tout Israël. Et aucune Tribu ne suivit la maison de David, que la seule Tribu de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Et Roboam vint à Jérusalem, et assembla toute la maison de Juda, et la Tribu de Benjamin, savoir cent quatre vingt mille hommes choisis, et faits à la guerre, pour combattre contre la maison d’Israël, et pour réduire le Royaume sous l’obéissance de Roboam fils de Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Mais la parole de Dieu fut adressée à Semahja, homme de Dieu, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Parle à Roboam fils de Salomon, Roi de Juda, et à toute la maison de Juda, et de Benjamin, et au reste du peuple, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Ainsi a dit l’Eternel: Vous ne monterez point, et vous ne combattrez point contre vos frères, les enfants d’Israël; retournez-vous-en chacun en sa maison; car ceci a été fait de par moi; et ils obéirent à la parole de l’Eternel et s’en retournèrent, selon la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Or Jéroboam bâtit Sichem en la montagne d’Ephraïm, et y demeura, puis il sortit de là, et bâtit Pénuël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Et Jéroboam dit en soi-même: Maintenant le Royaume pourrait bien retourner à la maison de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Si ce peuple monte à Jérusalem pour faire des sacrifices dans la maison de l’Eternel, le coeur de ce peuple se tournera vers son Seigneur Roboam, Roi de Juda, et ils me tueront, et ils retourneront à Roboam, Roi de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Sur quoi le Roi ayant pris conseil, fit deux veaux d’or, et dit au peuple: Ce vous est trop de peine de monter à Jérusalem; voici tes dieux, ô Israël! qui t’ont fait monter hors du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Et il en mit un à Bethel, et il mit l’autre à Dan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Et cela fut une occasion de péché; car le peuple allait même jusqu’à Dan, pour se prosterner devant l’un des veaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Il fit aussi des maisons des hauts lieux, et établit des Sacrificateurs des derniers du peuple, qui n’étaient point des enfants de Lévi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Jéroboam ordonna aussi une fête solennelle au huitième mois, le quinzième jour du mois, à l’imitation de la fête solennelle qu’on célébrait en Juda, et il offrait sur un autel. Il en fit de même à Bethel, sacrifiant aux veaux qu’il avait faits, et il établit à Bethel des Sacrificateurs des hauts lieux qu’il avait faits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Or le quinzième jour du huitième mois, savoir au mois qu’il avait inventé de lui-même, il offrit sur l’autel qu’il avait fait à Bethel, et célébra la fête solennelle qu’il avait instituée pour les enfants d’Israël; et offrit sur l’autel, en faisant des encensements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Et voici, un homme de Dieu vint de Juda à Bethel avec la parole de l’Eternel, lorsque Jéroboam se tenait près de l’autel pour y faire des encensements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Et il cria contre l’autel selon la parole de l’Eternel; et dit: Autel! Autel! ainsi a dit l’Eternel, voici, un fils naîtra à la maison de David, qui aura nom Josias; il immolera sur toi les Sacrificateurs des hauts lieux qui font des encensements sur toi, et on brûlera sur toi les os des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Et il proposa ce jour-là même un miracle, en disant: C’est ici le miracle dont l’Eternel a parlé: Voici, l’autel se fendra tout maintenant, et la cendre qui est dessus sera répandue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Or il arriva qu’aussitôt que le Roi eut entendu la parole que l’homme de Dieu avait prononcée à haute voix contre l’autel de Bethel, Jéroboam étendit sa main de l’autel, en disant: Saisissez-le. Et la main qu’il étendit contre lui devint sèche, et il ne la put retirer à soi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'L’autel aussi se fendit, et la cendre qui était sur l’autel fut répandue, selon le miracle que l’homme de Dieu avait proposé suivant la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Et le Roi prit la parole, et dit à l’homme de Dieu: Je te prie qu’il te plaise de supplier l’Eternel ton Dieu, et de faire prière pour moi, afin que ma main retourne à moi. Et l’homme de Dieu supplia l’Eternel, et la main du Roi retourna à lui, et elle fut comme auparavant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Alors le Roi dit à l’homme de Dieu: Entre avec moi dans la maison, et y dîne, et je te ferai un présent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Mais l’homme de Dieu répondit au Roi: Quand tu me donnerais la moitié de ta maison, je n’entrerais point chez toi, et je ne mangerais point de pain, ni ne boirais d’eau en ce lieu-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Car il m’a été ainsi commandé par l’Eternel, qui m’a dit: Tu n’y mangeras point de pain, et tu n’y boiras point d’eau, et tu ne t’en retourneras point par le chemin par lequel tu y seras allé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Il s’en alla donc par un autre chemin, et ne s’en retourna point par le chemin par lequel il était venu à Bethel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Or il y avait un certain Prophète, vieux homme, qui demeurait à Bethel, à qui son fils vint raconter toutes les choses que l’homme de Dieu avait faites ce jour-là à Bethel, et les paroles qu’il avait dites au Roi; et les enfants de ce prophète les rapportèrent à leur père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Et leur père leur dit: Par quel chemin s’en est-il allé? Or ses enfants avaient vu le chemin par lequel l’homme de Dieu qui était venu de Juda s’en était allé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Et il dit à ses fils: Sellez-moi un âne; et ils le sellèrent, puis il monta dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'Et il s’en alla après l’homme de Dieu, et le trouva assis sous un chêne; et il lui dit: Es-tu l’homme de Dieu qui es venu de Juda? Et il lui répondit: C’est moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Alors il lui dit: Viens avec moi dans la maison, et y mange du pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Mais il répondit: Je ne puis retourner avec toi, ni entrer chez toi, et je ne mangerai point de pain, ni je ne boirai point d’eau avec toi en ce lieu-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Car il m’a été dit de la part de l’Eternel: Tu n’y mangeras point de pain, et tu n’y boiras point d’eau, et tu ne t’en retourneras point par le chemin par lequel tu y seras allé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Et il lui dit: Et moi aussi je suis prophète comme toi; et un Ange m’a parlé de la part de l’Eternel, en disant: Ramène-le avec toi dans ta maison, et qu’il mange du pain, et qu’il boive de l’eau; mais il lui mentait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Il s’en retourna donc avec lui, et il mangea du pain, et but de l’eau dans sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Et il arriva que comme ils étaient assis à table, la parole de l’Eternel fut adressée au prophète qui l’avait ramené.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'Et il cria à l’homme de Dieu qui était venu de Juda, en disant: Ainsi a dit l’Eternel; parce que tu as été rebelle au commandement de l’Eternel, et que tu n’as point gardé le commandement que l’Eternel ton Dieu t’avait prescrit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'Mais tu t’en es retourné, et tu as mangé du pain, et bu de l’eau dans le lieu dont l’Eternel t’avait dit; n’y mange point de pain, et n’y bois point d’eau, ton corps n’entrera point au sépulcre de tes pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Or après qu’il eut mangé du pain, et qu’il eut bu, le vieux Prophète fit seller un âne, pour le Prophète qu’il avait ramené.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Puis ce Prophète s’en alla, et un lion le rencontra dans le chemin, et le tua; et son corps était étendu par terre dans le chemin, et l’âne se tenait auprès du corps; le lion aussi se tenait auprès du corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Et voici quelques passants virent le corps étendu dans le chemin, et le lion qui se tenait auprès du corps; et ils vinrent le dire dans la ville où ce vieux prophète demeurait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Et le prophète qui avait ramené du chemin l’homme de Dieu, l’ayant appris, dit: C’est l’homme de Dieu qui a été rebelle au commandement de l’Eternel; c’est pourquoi l’Eternel l’a livré au lion, qui l’aura déchiré après l’avoir tué, selon la parole que l’Eternel avait dite à ce Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Et il parla à ses fils, en disant: Sellez-moi un âne; et ils le lui sellèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Et il s’en alla, et trouva le corps de l’homme de Dieu étendu dans le chemin, et l’âne et le lion qui se tenaient auprès du corps; le lion n’avait point mangé le corps, ni déchiré l’âne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Alors le prophète leva le corps de l’homme de Dieu, et le mit sur l’âne, et le ramena; et ce vieux prophète revint dans la ville pour en mener deuil, et l’ensevelir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Et il mit le corps de ce Prophète dans son sépulcre, et ils pleurèrent sur lui, en disant: Hélas mon frère!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Et il arriva qu’après qu’il l’eut enseveli, il parla à ses fils, en disant: Quand je serai mort, ensevelissez-moi au sépulcre où est enseveli l’homme de Dieu, et mettez mes os auprès de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Car ce qu’il a prononcé à haute voix selon la parole de l’Eternel contre l’autel qui est à Bethel, et contre toutes les maisons des hauts lieux qui sont dans les villes de Samarie, arrivera infailliblement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Néanmoins Jéroboam ne se détourna point de son mauvais train, mais il revint à faire des Sacrificateurs des hauts lieux d’entre les derniers du peuple; quiconque voulait, se consacrait, et était des Sacrificateurs des hauts lieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Et cela tourna en péché à la maison de Jéroboam, qui fut effacée et exterminée de dessus la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'En ce temps-là Abija fils de Jéroboam devint malade.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Et Jéroboam dit à sa femme: Lève-toi maintenant, et te déguise, en sorte qu’on ne connaisse point que tu es la femme de Jéroboam, et va-t’en à Silo; là est Ahija le Prophète, qui m’a dit que je serais Roi sur ce peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Et prends en ta main dix pains, et des gâteaux, et un vase plein de miel, et entre chez lui; il te déclarera ce qui doit arriver à ce jeune garçon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'La femme de Jéroboam fit donc ainsi; car elle se leva, et s’en alla à Silo, et entra dans la maison d’Ahija. Or Ahija ne pouvait voir, parce que ses yeux étaient obscurcis, à cause de sa vieillesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Et l’Eternel dit à Ahija: Voilà la femme de Jéroboam, qui vient pour s’enquérir de toi touchant son fils, parce qu’il est malade; tu lui diras telles et telles chose; quand elle entrera elle fera semblant d’être quelque autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Aussitôt donc qu’Ahija eut entendu le bruit de ses pieds, comme elle entrait à la porte, il dit: Entre, femme de Jéroboam. Pourquoi fais-tu semblant d’être quelque autre? Je suis envoyé vers toi pour t’annoncer des choses dures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Va, et dis à Jéroboam: Ainsi a dit l’Eternel le Dieu d’Israël; parce que je t’ai élevé du milieu du peuple, et que je t’ai établi pour Conducteur de mon peuple d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'Et que j’ai déchiré le Royaume de la maison de David, et que je te l’ai donné; mais parce que tu n’as point été comme David mon serviteur, qui a gardé mes commandements, et qui a marché après moi de tout son coeur, faisant seulement ce qui est droit devant moi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Et qu’en faisant ce que tu as fait, tu as fait pis que tous ceux qui ont été devant toi; vu que tu t’en es allé, et t’es fait d’autres dieux, et des images de fonte, pour m’irriter, et que tu m’as rejeté derrière ton dos;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'A cause de cela, voici, je m’en vais amener du mal sur la maison de Jéroboam, et je retrancherai ce qui appartient à Jéroboam, depuis l’homme jusqu’à un chien, tant ce qui est serré, que ce qui est délaissé en Israël, et je raclerai la maison de Jéroboam, comme on racle la fiente, jusqu’à ce qu’il n’en reste plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Celui de la famille de Jéroboam qui mourra dans la ville, les chiens le mangeront; et celui qui mourra aux champs, les oiseaux des cieux le mangeront; car l’Eternel a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Toi donc lève-toi, et t’en va en ta maison, et aussitôt que tes pieds entreront dans la ville, l’enfant mourra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Et tout Israël mènera deuil sur lui, et l’ensevelira; car lui seul de la famille de Jéroboam entrera au sépulcre, parce que l’Eternel le Dieu d’Israël a trouvé quelque chose de bon en lui seul de toute la maison de Jéroboam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Et l’Eternel s’établira un Roi sur Israël, qui en ce jour-là retranchera la maison de Jéroboam; et quoi? même dans peu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Et l’Eternel frappera Israël, l’agitant comme le roseau est agité dans l’eau; et il arrachera Israël de dessus cette bonne terre qu’il a donnée à leurs pères, et les dispersera au delà du fleuve; parce qu’ils ont fait leurs bocages, irritant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Et l’Eternel abandonnera Israël à cause des péchés de Jéroboam, par lesquels il a péché, et fait pécher Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Alors la femme de Jéroboam se leva, et s’en alla, et vint à Tirtsa: et comme elle mettait le pied sur le seuil de la maison, le jeune garçon mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Et on l’ensevelit, et tout Israël mena deuil sur lui, selon la parole de l’Eternel, laquelle il avait proférée par son serviteur Ahija le Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Et quant au reste des faits de Jéroboam, comment il a fait la guerre, et comment il a régné, voilà ils sont écrits au Livre des Chroniques des Rois d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Or le temps que Jéroboam régna, fut vingt et deux ans; puis il s’endormit avec ses pères, et Nadab son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Et Roboam fils de Salomon régnait en Juda; il avait quarante et un ans quand il commença à régner, et il régna dix-sept ans à Jérusalem, la ville que l’Eternel avait choisie d’entre toutes les Tribus d’Israël, pour y mettre son Nom. Sa mère avait nom Nahama, et était Hammonite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Et Juda aussi fit ce qui déplaît à l’Eternel, et par leurs péchés qu’ils commirent ils l’émurent à jalousie plus que leurs pères n’avaient fait dans tout ce qu’ils avaient fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Car eux aussi se bâtirent des hauts lieux; et firent des images, et des bocages, sur toute haute colline, et sous tout arbre verdoyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Même il y avait au pays des gens prostitués à la paillardise, et ils firent selon toutes les abominations des nations que l’Eternel avait chassées de devant les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Or il arriva qu’en la cinquième année du Roi Roboam, Sisak, Roi d’Egypte, monta contre Jérusalem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Et prit les trésors de la maison de l’Eternel, et les trésors de la maison Royale, et il emporta tout. Il prit aussi tous les boucliers d’or que Salomon avait faits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Et le Roi Roboam fit des boucliers d’airain au lieu de ceux-là, et les mit entre les mains des capitaines des archers qui gardaient la porte de la maison du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Et quand le Roi entrait dans la maison de l’Eternel, les archers les portaient, et ensuite ils les rapportaient dans la chambre des archers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Le reste des faits de Roboam, et tout ce qu’il a fait, n’est-il pas écrit au Livre des Chroniques des Rois de Juda?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Or il y eut toujours guerre entre Roboam et Jéroboam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Et Roboam s’endormit avec ses pères, et fut enseveli avec eux dans la Cité de David; sa mère avait nom Nahama, et était Hammonite; et Abijam son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'La dix-huitième année du Roi Jéroboam fils de Nébat, Abijam commença à régner sur Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Et il régna trois ans à Jérusalem; sa mère avait nom Mahaca, et était fille d’Abisalom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Il marcha dans tous les péchés que son père avait commis avant lui, et son coeur ne fut point pur envers l’Eternel son Dieu, comme l’avait été le coeur de David son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Mais pour l’amour de David l’Eternel son Dieu lui donna une Lampe dans Jérusalem, lui suscitant son fils après lui, et protégeant Jérusalem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Parce que David avait fait ce qui est droit devant l’Eternel, et tout le temps de sa vie il ne s’était point détourné de rien qu’il lui eût commandé, hormis dans l’affaire d’Urie l’Héthien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Or il y eut toujours guerre entre Roboam et Jéroboam tout le temps que Roboam vécut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Et le reste des actions d’Abijam, et même tout ce qu’il a fait, n’est-il pas écrit au Livre des Chroniques des Rois de Juda? Il y eut aussi guerre entre Abijam et Jéroboam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Ainsi Abijam s’endormit avec ses pères, et on l’ensevelit en la Cité de David; et Asa son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'La vingtième année de Jéroboam Roi d’Israël, Asa commença à régner sur Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Et il régna quarante et un ans à Jérusalem; sa mère avait nom Mahaca, et elle était fille d’Abisalom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Et Asa fit ce qui est droit devant l’Eternel, comme David son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Car il abolit du pays les prostitués à la paillardise, et ôta tous les dieux de fiente que ses pères avaient faits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Et même il déposa sa mère Mahaca, afin qu’elle ne fût plus régente, parce qu’elle avait fait un simulacre pour un bocage, et Asa mit en pièces le simulacre qu’elle avait fait, et le brûla près du torrent de Cédron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Mais les hauts lieux ne furent point ôtés; néanmoins le coeur d’Asa fut droit envers l’Eternel tout le temps de sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Et il remit dans la maison de l’Eternel les choses qui avaient été consacrées par son père, avec ce qu’il avait aussi lui-même consacré, d’argent, d’or, et de vaisseaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Or il y eut guerre entre Asa et Bahasa Roi d’Israël tout le temps de leur vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Car Bahasa Roi d’Israël monta contre Juda, et bâtit Rama, afin de ne laisser sortir ni entrer personne vers Asa Roi de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Et Asa prit tout l’argent et l’or qui était demeuré dans les trésors de l’Eternel, et dans les trésors de la maison Royale, et les donna à ses serviteurs, et le Roi Asa les envoya vers Ben-hadad fils de Tabrimon, fils de Hezjon Roi de Syrie, qui demeurait à Damas, pour lui dire:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Il y a alliance entre moi et toi, et entre mon père et le tien; voici, je t’envoie un présent en argent et en or; Va, romps l’alliance que tu as avec Bahasa Roi d’Israël, et qu’il se retire de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Et Ben-hadad accorda cela au Roi Asa, et envoya les capitaines de son armée, contre les villes d’Israël, et frappa Hijon, Dan, Abel-beth-mahaca, et tout Kinneroth, qui était joignant tout le pays de Nephthali.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Et il arriva qu’aussitôt que Bahasa l’eut appris, il cessa de bâtir Rama, et demeura à Tirtsa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Alors le Roi Asa fit publier par tout Juda que tous, sans en excepter aucun, eussent à emporter les pierres et le bois de Rama, que Bahasa faisait bâtir, et le Roi Asa en bâtit Guébah de Benjamin, et Mitspa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Le reste de tous les faits d’Asa, et toute sa valeur, et tout ce qu’il a fait, et les villes qu’il a bâties, n’est-il pas écrit au Livre des Chroniques des Rois de Juda? Au reste, il fut malade de ses pieds au temps de sa vieillesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Et Asa s’endormit avec ses pères, avec lesquels il fut enseveli en la Cité de David son père, et Josaphat son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Or Nadab fils de Jéroboam commença à régner sur Israël la seconde année d’Asa Roi de Juda, et il régna deux ans sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Et il fit ce qui déplaît à l’Eternel, et suivit le train de son père, et le péché par lequel il avait fait pécher Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Et Bahasa fils d’Ahija de la maison d’Issacar, fit une conspiration contre lui, et le frappa devant Guibbethon qui était aux Philistins, lorsque Nadab et tout Israël assiégeaient Guibbethon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Bahasa donc le fit mourir la troisième année d’Asa Roi de Juda, et il régna en sa place;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Et aussitôt qu’il vint à régner il frappa toute la maison de Jéroboam, et il ne laissa aucune âme vivante de la race de Jéroboam qu’il n’exterminât, selon la parole de l’Eternel qu’il avait proférée par son serviteur Ahija Silonite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'A cause des péchés de Jéroboam qu’il avait faits, et par lesquels il avait fait pécher Israël; et à cause du péché par lequel il avait irrité l’Eternel le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Le reste des faits de Nadab, et même tout ce qu’il a fait, n’est-il pas écrit au Livre des Chroniques des Rois d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Or il y eut guerre entre Asa et Bahasa Roi d’Israël, tout le temps de leur vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'La troisième année d’Asa Roi de Juda, Bahasa fils d’Ahija commença à régner sur tout Israël à Tirtsa, et régna vingt et quatre ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Et il fit ce qui déplaît à l’Eternel, et suivit le train de Jéroboam, et son péché, par lequel il avait fait pécher Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Alors la parole de l’Eternel fut adressée à Jéhu, fils de Hanani, contre Bahasa, pour lui dire:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Parce que je t’ai élevé de la poudre, et que je t’ai établi Conducteur de mon peuple d’Israël, et que malgré cela tu as suivi le train de Jéroboam, et as fait pécher mon peuple d’Israël, pour m’irriter par leurs péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Voici, je m’en vais entièrement exterminer Bahasa, et sa maison, et je mettrai ta maison au même état que j’ai mis la maison de Jéroboam fils de Nébat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Celui de la race de Bahasa qui mourra dans la ville, les chiens le mangeront; et celui des siens qui mourra aux champs, les oiseaux des cieux le mangeront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Le reste des faits de Bahasa, ce qu’il a fait, et sa valeur, n’est-il pas écrit au Livre des Chroniques des Rois d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Ainsi Bahasa s’endormit avec ses pères, et fut enseveli à Tirtsa, et Ela son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'La parole de l’Eternel fut aussi adressée par le moyen de Jéhu, fils de Hanani le Prophète, contre Bahasa, et contre sa maison, à cause de tout le mal qu’il avait fait devant l’Eternel, en l’irritant par l’oeuvre de ses mains, pour lui dire qu’il en serait comme de la maison de Jéroboam; même parce qu’il l’avait frappée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'L’an vingt et sixième d’Asa Roi de Juda, Ela fils de Bahasa commença à régner sur Israël, et il régna deux ans à Tirtsa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Et Zimri son serviteur, capitaine de la moitié des chariots, fit une conspiration contre Ela, lorsqu’il était à Tirtsa buvant et s’enivrant dans la maison d’Artsa son maître d’hôtel, à Tirtsa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Zimri donc vint, et le frappa, et le tua l’an vingt et septième d’Asa Roi de Juda, et régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Et comme il entrait en son règne, sitôt qu’il fut assis sur son trône, il frappa toute la maison de Bahasa; il n’en laissa rien depuis l’homme jusqu’à un chien; il ne lui laissa ni parent, ni ami.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Ainsi Zimri extermina toute la maison de Bahasa, selon la parole que l’Eternel avait proférée contre Bahasa, par le moyen de Jéhu le Prophète;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'A cause de tous les péchés de Bahasa, et des péchés d’Ela son fils, par lesquels ils avaient péché, et avaient fait pécher Israël, irritant l’Eternel le Dieu d’Israël par leurs vanités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Le reste des faits d’Ela, et même tout ce qu’il a fait, n’est-il pas écrit au Livre des Chroniques des Rois d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'La vingt et septième année d’Asa Roi de Juda, Zimri régna sept jours à Tirtsa; or le peuple était campé contre Guibbethon qui était aux Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Et le peuple qui était-là campé, entendit qu’on disait: Zimri a fait une conspiration, et il a même tué le Roi; c’est pourquoi en ce même jour tout Israël établit dans le camp pour Roi Homri, capitaine de l’armée d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Et Homri et tout Israël montèrent de devant Guibbethon, et assiégèrent Tirtsa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Mais dès que Zimri eut vu que la ville était prise, il entra au palais de la maison Royale, et brûla sur soi la maison Royale, et il mourut;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'A cause des péchés par lesquels il avait péché, faisant ce qui déplaît à l’Eternel, en suivant le train de Jéroboam, et son péché, qu’il avait fait pour faire pécher Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Le reste des faits de Zimri, et la conspiration qu’il fit, toutes ces choses ne sont-elles pas écrites au Livre des Chroniques des Rois d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Alors le peuple d’Israël se divisa en deux partis; la moitié du peuple suivait Tibni fils de Guinath, pour le faire Roi; et l’autre moitié suivait Homri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Mais le peuple qui suivait Homri, fut plus fort que le peuple qui suivait Tibni fils de Guinath, et Tibni mourut, et Homri régna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'La trente et unième année d’Asa Roi de Juda, Homri commença à régner sur Israël, et il régna douze ans; il régna six ans à Tirtsa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Puis il acheta de Sémer la montagne de Samarie, deux talents d’argent; et il bâtit une ville sur cette montagne, et il nomma la ville qu’il bâtit, du nom de Sémer, Seigneur de la montagne de Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Et Homri fit ce qui déplaît à l’Eternel; il fit même pis que tous ceux qui avaient été avant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Car il suivit tout le train de Jéroboam fils de Nébat, et son péché, par lequel il avait fait pécher Israël, afin qu’ils irritassent l’Eternel le Dieu d’Israël par leurs vanités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Le reste des faits de Homri, tout ce qu’il a fait, et les exploits qu’il fit, ne sont-ils pas écrits aux Livre des Chroniques des Rois d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Ainsi Homri s’endormit avec ses pères, et fut enseveli à Samarie, et Achab son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Achab fils de Homri commença à régner sur Israël la trente-huitième année d’Asa Roi de Juda; et Achab fils de Homri régna sur Israël à Samarie vingt et deux ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Et Achab fils de Homri fit ce qui déplaît à l’Eternel, plus que tous ceux qui avaient été avant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Et il arriva que, comme si ce lui eût été peu de chose de marcher dans les péchés de Jéroboam fils de Nébat, il prit pour femme Izebel, fille d’Eth-bahal, Roi des Sidoniens, puis il alla, et servit Bahal, et se prosterna devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Et il dressa un autel à Bahal, en la maison de Bahal, qu’il bâtit à Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Et Achab fit un bocage; de sorte qu’Achab fit encore pis que tous les Rois d’Israël qui avaient été avant lui, pour irriter l’Eternel le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'En son temps Hiel de Bethel bâtit Jérico, laquelle il fonda sur Abiram son premier-né, et posa ses portes sur Ségub son puîné, selon la parole que l’Eternel avait proférée par le moyen de Josué, fils de Nun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Alors Elie Tisbite, l’un de ceux qui s’étaient habitués à Galaad, dit à Achab: L’Eternel le Dieu d’Israël, en la présence duquel je me tiens, est vivant, qu’il n’y aura ces années-ci ni rosée ni pluie, sinon à ma parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Puis la parole de l’Eternel fut adressée à Elie, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Va-t’en d’ici, et tourne-toi vers l’Orient, et te cache au torrent de Kérith, qui est vis-à-vis du Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Tu boiras du torrent, et j’ai commandé aux corbeaux de t’y nourrir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Il partit donc, et fit selon la parole de l’Eternel; il s’en alla, dis-je, et demeura au torrent de Kérith, vis-à-vis du Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Et les corbeaux lui apportaient du pain et de la chair le matin, et du pain et de la chair le soir, et il buvait du torrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Mais il arriva qu’au bout de quelques jours le torrent tarit; parce qu’il n’y avait point eu de pluie au pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Alors la parole de l’Eternel lui fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Lève-toi, et t’en va à Sarepta, qui est près de Sidon, et demeure-là. Voici, j’ai commandé là à une femme veuve de t’y nourrir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Il se leva donc, et s’en alla à Sarepta; et comme il fut arrivé à la porte de la ville, voilà, une femme veuve était là, qui amassait du bois; et il l’appela, et lui dit: Je te prie, apporte-moi un peu d’eau dans un vaisseau, et que je boive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Elle s’en alla pour en prendre; et il la rappela, et lui dit: Je te prie, prends en ta main une bouchée de pain pour moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Mais elle répondit: L’Eternel ton Dieu est vivant, que je n’ai aucun gâteau; je n’ai que pleine ma main de farine dans une cruche, et un peu d’huile dans une fiole, et voici j’amasse deux bûches, puis je m’en irai, et je l’apprêterai pour moi et pour mon fils, et nous le mangerons; et après cela nous mourrons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Et Elie lui dit: Ne crains point; va, fais comme tu dis; mais fais m’en premièrement un petit gâteau, et apporte-le-moi, et puis tu en feras pour toi et pour ton fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Car ainsi a dit l’Eternel le Dieu d’Israël: La farine qui est dans la cruche, ne défaudra point, et l’huile qui est dans la fiole ne défaudra point, jusqu’à ce que l’Eternel donne de la pluie sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Elle s’en alla donc, et fit selon la parole d’Elie; et elle mangea, lui, et la famille de cette femme durant plusieurs jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'La farine de la cruche ne manqua point, et l’huile de la fiole ne tarit point, selon la parole que l’Eternel avait proférée par le moyen d’Elie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Après ces choses il arriva que le fils de la femme, maîtresse de la maison, devint malade; et la maladie fut si forte, qu’il expira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Et elle dit à Elie: Qu’y a-t-il entre moi et toi, homme de Dieu? Es-tu venu chez moi pour rappeler en mémoire mon iniquité, et pour faire mourir mon fils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Et il lui dit: Donne-moi ton fils; et il le prit du sein de cette femme, et le porta dans la chambre haute où il demeurait, et le coucha sur son lit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Puis il cria à l’Eternel, et dit: Eternel mon Dieu! as-tu donc tellement affligé cette veuve avec laquelle je demeure, que tu lui aies fait mourir son fils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Et il s’étendit tout de son long sur l’enfant par trois fois, et cria à l’Eternel, et dit: Eternel mon Dieu! je te prie que l’âme de cet enfant r’entre dans lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Et l’Eternel exauça la voix d’Elie, et l’âme de l’enfant r’entra dans lui, et il recouvra la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Et Elie prit l’enfant, et le fit descendre de la chambre haute dans la maison, et le donna à sa mère, en lui disant: Regarde, ton fils vit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Et la femme dit à Elie: Je connais maintenant, que tu es un homme de Dieu, et que la parole de l’Eternel, qui est dans ta bouche, est la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Plusieurs jours après il arriva que la parole de l’Eternel fut adressée à Elie, en la troisième année, en disant: Va, montre-toi à Achab, et je donnerai de la pluie sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Elie donc s’en alla pour se montrer à Achab; or il y avait une grande famine dans la Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Et Achab avait appelé Abdias son maître d’hôtel, (or Abdias craignait fort l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Car quand Izebel exterminait les Prophètes de l’Eternel, Abdias prit cent Prophètes, et les cacha, cinquante dans une caverne, et cinquante dans une autre, et les y nourrit de pain et d’eau.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Et Achab avait dit à Abdias: Va par le pays vers toutes les fontaines d’eaux, et vers tous les torrents; peut-être que nous trouverons de l’herbe, et que nous sauverons la vie aux chevaux et aux mulets, et nous ne laisserons point dépeupler le pays de bêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Ils partagèrent donc entr’eux le pays, afin d’aller partout; Achab allait séparément par un chemin, et Abdias allait séparément par un autre chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Et comme Abdias était en chemin, voilà, Elie le rencontra, et il reconnut Elie, et s’inclinant sur son visage, il lui dit: N’es-tu pas mon Seigneur Elie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Et Elie lui répondit: C’est moi-même; va, et dis à ton Seigneur, voici Elie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Et Abdias dit: Quel crime ai-je fait, que tu livres ton serviteur entre les mains d’Achab pour me faire mourir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'L’Eternel ton Dieu est vivant, qu’il n’y a ni nation, ni Royaume, où mon Seigneur n’ait envoyé pour te chercher; et on a répondu; il n’y est point. Il a même fait jurer les Royaumes et les nations pour découvrir si l’on ne pourrait point te trouver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Et maintenant tu dis: Va, et dis à ton Seigneur, voici Elie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Et il arrivera que quand je serai parti d’avec toi, l’Esprit de l’Eternel te transportera en quelque endroit que je ne saurai point, et je viendrai vers Achab pour lui déclarer ce que tu m’as dit, et ne te trouvant point, il me tuera; or ton serviteur craint l’Eternel dès sa jeunesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'N’a-t-on point dit à mon Seigneur ce que je fis quand Izebel tuait les Prophètes de l’Eternel, comment j’en cachai cent, cinquante dans une caverne, et cinquante dans une autre, et les y nourris de pain et d’eau?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Et maintenant tu dis, va; et dis à ton Seigneur, voici Elie; car il me tuera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Mais Elie lui répondit: L’Eternel des armées, devant lequel je me tiens, est vivant, que certainement je me montrerai aujourd’hui à Achab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Abdias donc s’en alla pour rencontrer Achab, et il lui fit entendre le tout; puis Achab alla au devant d’Elie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Et aussitôt qu’Achab eut vu Elie, il lui dit: N’es-tu pas celui qui trouble Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Et Elie lui répondit: Je n’ai point troublé Israël; mais c’est toi et la maison de ton père qui avez troublé Israël, en ce que vous avez abandonné les commandements de l’Eternel, et que vous avez marché après les Bahalins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Or maintenant envoie, et fais assembler vers moi tout Israël sur la montagne de Carmel, avec les quatre cent cinquante prophètes de Bahal, et les quatre cents prophètes des bocages qui mangent à la table d’Izebel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Ainsi Achab envoya vers tous les enfants d’Israël, et il assembla ces prophètes-là sur la montagne de Carmel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Puis Elie s’approcha de tout le peuple, et dit: Jusqu’à quand clocherez- vous des deux côtés? Si l’Eternel est Dieu, suivez-le; mais si Bahal est Dieu, suivez-le. Et le peuple ne lui répondit pas un seul mot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Alors Elie dit au peuple: Je suis demeuré seul Prophète de l’Eternel; et les prophètes de Bahal sont au nombre de quatre cent cinquante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Or qu’on nous donne deux veaux, qu’ils en choisissent l’un pour eux, qu’ils le coupent en pièces, et qu’ils le mettent sur du bois; mais qu’ils n’y mettent point de feu; et je préparerai l’autre veau, je le mettrai sur du bois, et je n’y mettrai point de feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Puis invoquez le nom de vos dieux, et moi j’invoquerai le Nom de l’Eternel; et que le Dieu qui aura exaucé par feu, soit reconnu pour Dieu. Et tout le peuple répondit et dit: C’est bien dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Et Elie dit aux Prophètes de Bahal: Choisissez un veau, et préparez-le les premiers; car vous êtes en plus grand nombre, et invoquez le nom de vos dieux; mais n’y mettez point de feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Ils prirent donc un veau qu’on leur donna, ils l’apprêtèrent, et ils invoquèrent le nom de Bahal depuis le matin jusqu’à midi, en disant: Bahal exauce-nous! Mais il n’y avait ni voix ni réponse, et ils sautaient par dessus l’autel qu’on avait fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Et sur le midi Elie se moquait d’eux, et disait: Criez à haute voix, car il est dieu; mais il pense à quelque chose, ou il est après quelque affaire, ou il est en voyage; peut-être qu’il dort; et il s’éveillera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Ils criaient donc à haute voix, et ils se faisaient des incisions avec des couteaux, et des lancettes; selon leur coutume, en sorte que le sang coulait sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Et quand le midi fut passé, et qu’ils eurent fait les prophètes jusqu’au temps qu’on offre l’oblation, sans qu’il y eût ni voix, ni réponse, ni apparence aucune qu’on eût égard à ce qu’ils faisaient;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Elie dit alors à tout le peuple: Approchez-vous de moi. Et tout le peuple s’approcha de lui, et il répara l’autel de l’Eternel, qui était démoli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Puis Elie prit douze pierres, selon le nombre des Tribus des enfants de Jacob, auquel la parole de l’Eternel avait été adressée, en disant: Israël sera ton nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Et il rebâtit de ces pierres l’autel au Nom de l’Eternel; puis il fit un conduit de la capacité de deux sats de semence à l’entour de l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Il rangea le bois, il coupa le veau en pièces, et il le mit sur le bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Puis il dit: Emplissez quatre cruches d’eau, et les versez sur l’holocauste, et sur le bois. Puis il leur dit: Faites-le encore pour la deuxième fois; et ils le firent pour la deuxième fois. De nouveau il leur dit: Faites-le encore pour la troisième fois; et ils le firent pour la troisième fois;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'De sorte que les eaux allaient à l’entour de l’autel; et il remplit même le conduit d’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Et au temps qu’on offre l’oblation, Elie le Prophète s’approcha, et dit: Ô Eternel! Dieu d’Abraham, d’Isaac, et d’Israël! fais qu’on connaisse aujourd’hui que tu es Dieu en Israël, et que je suis ton serviteur, et que j’ai fait toutes ces choses, selon ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Exauce-moi, ô Eternel! exauce-moi; et fais que ce peuple connaisse que tu es l’Eternel Dieu, et que c’est toi qui auras fait retourner leurs coeurs en arrière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Alors le feu de l’Eternel tomba, et consuma l’holocauste, le bois, les pierres, et la poudre, et huma toute l’eau qui était au conduit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Et tout le peuple voyant cela, tomba sur son visage, et dit: C’est l’Eternel qui est Dieu; c’est l’Eternel qui est Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Et Elie leur dit: Saisissez les Prophètes de Bahal, et qu’il n’en échappe pas un. Ils les saisirent donc, et Elie les fit descendre au torrent de Kison, et les fit égorger là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Puis Elie dit à Achab: Monte, mange, et bois; car il y a un son bruyant de pluie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Ainsi Achab monta pour manger et pour boire; et Elie monta au sommet du Carmel, et se penchant contre terre, il mit son visage entre ses genoux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Et il dit à son serviteur: Monte maintenant, et regarde vers la mer. Il monta donc, et regarda, et dit: Il n’y a rien. Et Elie lui dit: Retournes- y par sept fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'A la septième fois, il dit: Voilà une petite nuée comme la paume de la main d’un homme, laquelle monte de la mer. Alors Elie lui dit: Monte, et dis à Achab: Attelle ton chariot, et descends, de peur que la pluie ne te surprenne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Et il arriva que les cieux s’obscurcirent de tous côtés de nuées, accompagnées de vent, et il y eut une grande pluie; et Achab monta sur son chariot, et vint à Jizréhel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Et la main de l’Eternel fut sur Elie, qui s’étant retroussé sur les reins, courut devant Achab, jusqu’à l’entrée de Jizréhel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Or Achab rapporta à Izebel tout ce qu’Elie avait fait, et comment il avait entièrement tué avec l’épée tous les Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Et Izebel envoya un messager vers Elie, pour lui dire: Ainsi fassent les dieux, et ainsi ils y ajoutent, si demain, à cette heure-ci, je ne te mets au même état que l’un d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Et Elie voyant cela se leva, et s’en alla comme son coeur lui disait. Il s’en vint à Beersebah, qui appartient à Juda; et il laissa là son serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Mais lui s’en alla au désert, le chemin d’un jour, et y étant venu il s’assit sous un genêt, et demanda que Dieu retirât son âme, et dit: C’est assez, ô Eternel! prends maintenant mon âme; car je ne suis pas meilleur que mes pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Puis il se coucha, et s’endormit sous un genêt; et voici un Ange le toucha, et lui dit: Lève-toi, mange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Et il regarda, et voici à son chevet un gâteau cuit aux charbons, et une fiole d’eau. Il mangea donc et but, et se recoucha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Et l’Ange de l’Eternel retourna pour la seconde fois, et le toucha, et lui dit: Lève-toi, mange; car le chemin est trop long pour toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Il se leva donc, et mangea et but; puis avec la force que lui donna ce repas il marcha quarante jours et quarante nuits, jusqu’à Horeb, la montagne de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Et là il entra dans une caverne, et y passa la nuit. Ensuite voilà, la parole de l’Eternel lui fut adressée, et l’Eternel lui dit: Quelle affaire as-tu ici, Elie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Et il répondit: J’ai été extrêmement ému à jalousie pour l’Eternel le Dieu des armées, parce que les enfants d’Israël ont abandonné ton alliance; ils ont démoli tes autels, ils ont tué tes Prophètes avec l’épée, je suis resté moi seul, et ils cherchent ma vie pour me l’ôter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Mais il lui dit: Sors, et tiens-toi sur la montagne devant l’Eternel. Et voici, l’Eternel passait, et un grand vent impétueux, qui fendait les montagnes, et brisait les rochers, allait devant l’Eternel; mais l’Eternel n’était point dans ce vent. Après le vent se fit un tremblement; mais l’Eternel n’était point dans ce tremblement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Après le tremblement venait un feu; mais l’Eternel n’était point dans ce feu. Après le feu venait un son doux et subtil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Et il arriva que dès qu’Elie l’eut entendu, il enveloppa son visage de son manteau, et sortit, et se tint à l’entrée de la caverne, et voici, une voix lui fut adressée, et lui dit: Quelle affaire as-tu ici, Elie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Et il répondit: J’ai été extrêmement ému à jalousie pour l’Eternel le Dieu des armées, parce que les enfants d’Israël ont abandonné ton alliance; ils ont démoli tes autels, ils ont tué tes prophètes avec l’épée; je suis resté moi seul; et ils cherchent ma vie pour me l’ôter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Mais l’Eternel lui dit: Va, retourne-t’en par ton chemin vers le désert de Damas, et quand tu seras arrivé tu oindras Hazaël pour Roi sur la Syrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Tu oindras aussi Jéhu fils de Nimsi pour Roi sur Israël; et tu oindras Elisée fils de Saphat, qui est d’Abel-méhola pour Prophète en ta place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Et il arrivera que quiconque échappera de l’épée de Hazaël, Jéhu le fera mourir; et quiconque échappera de l’épée de Jéhu, Elisée le fera mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Mais je me suis réservé sept mille hommes de reste en Israël, savoir, tous ceux qui n’ont point fléchi leurs genoux devant Bahal, et dont la bouche ne l’a point baisé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Elie donc partit de là, et trouva Elisée fils de Saphat, qui labourait ayant douze paires de bœufs devant soi, et il était avec la douzième. Quand Elie eut passé vers lui, il jeta son manteau sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Et Elisée laissa ses boeufs, et courut après Elie, et dit: Je te prie, que je baise mon père, et ma mère, et puis je te suivrai. Et il lui dit: Va, et retourne; car que t’ai-je fait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Il s’en retourna donc d’avec lui et prit une paire de boeufs, et les sacrifia; et de l’attelage des boeufs il en bouillit la chair, et la donna au peuple, et ils mangèrent; puis il se leva, et suivit Elie, et il le servait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Alors Ben-hadad Roi de Syrie assembla toute son armée, et il y avait avec lui trente-deux Rois, des chevaux, et des chariots; puis il monta, assiégea Samarie, et il lui fit la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Et il envoya des messagers vers Achab Roi d’Israël dans la ville;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'Et il lui fit dire: Ainsi a dit Ben-hadad: Ton argent et ton or est à moi, tes femmes aussi, et tes beaux enfants sont à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Et le Roi d’Israël répondit, et dit: mon Seigneur, je suis à toi comme tu le dis, et tout ce que j’ai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Ensuite les messagers retournèrent, et dirent: Ainsi a dit expressément Ben- hadad: Puisque je t’ai envoyé dire: Donne-moi ton argent et ton or, ta femme, et tes enfants;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Certainement demain en ce même temps j’enverrai chez toi mes serviteurs, qui fouilleront ta maison, et les maisons de tes serviteurs, et se saisiront de tout ce que tu prends plaisir à voir, et ils l’emporteront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Alors le Roi d’Israël appela tous les Anciens du pays, et dit: Considérez je vous prie, et voyez que celui-ci ne cherche que du mal; car il avait envoyé vers moi pour avoir mes femmes, et mes enfants, mon argent et mon or; et je ne lui avais rien refusé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Et tous les Anciens et tout le peuple lui dirent: Ne l’écoute point, et ne lui complais point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Il répondit donc aux messagers de Ben-hadad: Dites au Roi mon Seigneur: Je ferai tout ce que tu as envoyé dire la première fois à ton serviteur, mais je ne pourrai faire ceci; et les messagers s’en allèrent, et lui rapportèrent cette réponse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Et Ben-hadad renvoya vers lui, en disant: Ainsi me fassent les dieux, et ainsi ils y ajoutent, si la poudre de Samarie suffit pour remplir le creux de la main de tous ceux du peuple qui me suivent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Mais le Roi d’Israël répondit, et dit: Dites-lui: que celui qui endosse le harnois, ne se glorifie point comme celui qui le quitte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Et il arriva qu’aussitôt que Ben-hadad eut entendu cette réponse (or il buvait alors dans les tentes avec les Rois) il dit à ses serviteurs: Rangez- vous en bataille. Et ils se rangèrent en bataille contre la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Alors voici un Prophète qui vint vers Achab Roi d’Israël, et qui lui dit: Ainsi a dit l’Eternel, n’as-tu pas vu cette grande multitude? Voilà, je m’en vais la livrer aujourd’hui entre tes mains, et tu sauras que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Et Achab dit: Par qui? et le Prophète lui répondit: Ainsi a dit l’Eternel: Ce sera par les valets des Gouverneurs des Provinces. Et Achab dit: Qui est-ce qui commencera la bataille? et il lui répondit: Toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Alors il dénombra les valets des Gouverneurs des Provinces, qui furent deux cent trente et deux; après eux il dénombra tout le peuple de tous les enfants d’Israël, qui furent sept mille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Et ils sortirent en plein midi, lorsque Ben-hadad buvait, s’enivrant dans les tentes, lui, et les trente-deux Rois qui étaient venus à son secours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Les valets donc des Gouverneurs des Provinces sortirent les premiers, et Ben-hadad envoya quelques-uns qui le lui rapportèrent, en disant: Il est sorti des gens de Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Et il dit: Soit qu’ils soient sortis pour la paix, ou qu’ils soient sortis pour faire la guerre, saisissez-les tous vifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Les valets donc des Gouverneurs des Provinces sortirent de la ville, et l’armée qui était après eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Et chacun d’eux frappa son homme, de sorte que les Syriens s’enfuirent, et Israël les poursuivit; et Ben-hadad Roi de Syrie se sauva sur un cheval, et les gens de cheval aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Et le Roi d’Israël sortit, et frappa les chevaux, et les chariots, en sorte qu’il fit un grand carnage des Syriens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Puis le Prophète vint vers le Roi d’Israël, et lui dit: Va, renforce-toi; et sache, et regarde ce que tu auras à faire; car l’an révolu le Roi de Syrie remontera contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Or les serviteurs du Roi de Syrie lui dirent: Leurs dieux sont des dieux de montagne, c’est pourquoi ils ont été plus forts que nous, mais combattons contr’eux dans la campagne; et certainement, nous serons plus forts qu’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Fais donc ceci: Ote chacun de ces Rois de leur place, et mets en leur lieu des capitaines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Puis lève une armée pareille à celle que tu as perdue, et autant de chevaux, et de chariots, et nous combattrons contr’eux dans la campagne, et tu verras si nous ne sommes pas plus forts qu’eux. Il acquiesça donc à ce qu’ils lui dirent, et le fit ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Un an donc après, Ben-hadad dénombra les Syriens, et monta en Aphek pour combattre contre Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'On fit aussi le dénombrement des enfants d’Israël; et s’étant fournis de vivres, ils s’en allèrent contre les Syriens. Les enfants d’Israël se campèrent vis-à-vis d’eux; et ils ne paraissaient pas plus que deux troupeaux de chèvres; mais les Syriens remplissaient la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Alors l’homme de Dieu vint, et parla au Roi d’Israël, et lui dit: Ainsi a dit l’Eternel: Parce que les Syriens ont dit: L’Eternel est Dieu des montagnes, et n’est point Dieu des vallées, je livrerai entre tes mains toute cette grande multitude, et vous saurez que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Sept jours durant ils demeurèrent campés vis-à-vis les uns des autres; mais le septième jour ils en vinrent aux mains; et les enfants d’Israël frappèrent en un seul jour cent mille hommes de pied des Syriens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Et le reste s’enfuit dans la ville d’Aphek, où la muraille tomba sur vingt et sept mille hommes qui étaient demeurés de reste. Et Ben-hadad s’enfuit, et entra dans la ville, et il se cacha dans le cabinet d’une chambre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Et ses serviteurs lui dirent: Voici maintenant, nous avons ouï dire que les Rois de la maison d’Israël sont des Rois débonnaires; maintenant donc mettons des sacs sur nos reins, et mettons des cordes à nos têtes; et sortons vers le Roi d’Israël; peut-être qu’il te donnera la vie sauve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Ils se ceignirent donc de sacs autour de leurs reins, et de cordes autour de leurs têtes, et ils vinrent vers le Roi d’Israël, et lui dirent: Ton serviteur Ben-hadad dit: Je te prie que je vive. Et il répondit: Vit-il encore? Il est mon frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Et ces gens étaient là comme au guet, et ils se hâtèrent de savoir précisément s’ils auraient de lui ce qu’ils prétendaient, et ils dirent: Ben-hadad est-il ton frère? Et il répondit: Allez, et l’amenez. Ben-hadad donc sortit vers lui, et il le fit monter sur le chariot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Et Ben-hadad lui dit: Je te rendrai les villes que mon père avait prises à ton père, et tu te feras des places en Damas comme mon père avait fait en Samarie. Et moi, répondit Achab, je te renverrai avec cette alliance. Il traita donc alliance avec lui, et le laissa aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Alors quelqu’un d’entre les fils des Prophètes dit à son compagnon, suivant la parole de l’Eternel: Frappe-moi; je te prie: mais celui-là refusa de le frapper.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Et il lui dit: Parce que tu n’as point obéi à la parole de l’Eternel, voilà tu vas te séparer de moi, et un lion te tuera. Quand il se fut séparé de lui, un lion le trouva, et le tua.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Puis il trouva un autre homme, et lui dit: Frappe-moi, je te prie; et cet homme-là ne manqua pas à le frapper, et il le blessa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Après cela le Prophète s’en alla, et s’arrêta attendant le Roi sur le chemin, et il se déguisa ayant un bandeau sur ses yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Et comme le Roi passait, il cria au Roi, et lui dit: Ton serviteur était allé au milieu de la bataille, et voilà quelqu’un s’étant retiré, m’a amené un homme, et m’a dit: Garde cet homme, s’il vient à s’échapper, ta vie en répondra, ou tu en payeras un talent d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Or il est arrivé que comme ton serviteur faisait quelques affaires çà et là, cet homme-là ne s’est point trouvé. Et le Roi d’Israël lui répondit: Telle est ta condamnation, tu en as décidé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Alors cet homme ôta promptement le bandeau de dessus ses yeux, et le Roi d’Israël reconnut que c’était un des Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Et ce Prophète lui dit: Ainsi a dit l’Eternel, parce que tu as laissé aller d’entre tes mains l’homme que j’avais condamné à l’interdit, ta vie répondra pour la sienne, et ton peuple pour son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Mais le Roi d’Israël se retira en sa maison tout refrogné et indigné, et vint en Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Or il arriva après ces choses, que Naboth Jizréhélite, ayant une vigne à Jizréhel, près du palais d’Achab, Roi de Samarie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Achab parla à Naboth, et lui dit: Cède-moi ta vigne, afin que j’en fasse un jardin de verdure; car elle est proche de ma maison, et je t’en donnerai pour celle-là une meilleure; ou si cela t’accommode mieux, je t’en donnerai l’argent qu’elle vaut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Mais Naboth répondit à Achab: A Dieu ne plaise que je te cède l’héritage de mes pères!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Et Achab vint en sa maison tout refrogné et indigné pour la parole que lui avait dite Naboth Jizréhélite, en disant: Je ne te céderai point l’héritage de mes pères; et il se coucha sur son lit, et tourna son visage, et ne mangea rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Alors Izebel sa femme entra vers lui, et lui dit: D’où vient que ton esprit est si triste? et pourquoi ne manges-tu point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Et il lui répondit: C’est parce qu’ayant parlé à Naboth Jizréhélite, et lui ayant dit: Donne-moi ta vigne pour de l’argent, ou si tu l’aimes mieux, je te donnerai une autre vigne pour celle-là, il m’a dit: Je ne te céderai point ma vigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Alors Izebel sa femme lui dit: Serais-tu maintenant Roi sur Israël? Lève- toi, mange quelque chose, et que ton coeur se réjouisse; je te ferai avoir la vigne de Naboth Jizréhélite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Et elle écrivit des Lettres au nom d’Achab, les scella du sceau du Roi, et elle envoya ces Lettres aux Anciens et Magistrats qui étaient dans la ville de Naboth, et qui y demeuraient avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Et elle écrivit dans ces Lettres ce qui s’ensuit: Publiez le jeûne, et faites tenir Naboth au haut bout du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Et faites tenir deux méchants hommes vis-à-vis de lui, et qu’ils témoignent contre lui, en disant: Tu as blasphémé contre Dieu, et mal parlé du Roi; puis vous le mènerez dehors, et vous le lapiderez, et qu’il meure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Les gens donc de la ville de Naboth, savoir les Anciens et les Magistrats qui demeuraient dans sa ville, firent comme Izebel leur avait mandé, et selon qu’il était écrit dans les Lettres qu’elle leur avait envoyées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Car ils publièrent le jeûne, et firent tenir Naboth au haut bout du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Et deux méchants hommes entrèrent, et se tinrent vis-à-vis de lui; et ces méchants hommes témoignèrent contre Naboth en la présence du peuple, en disant: Naboth a blasphémé contre Dieu, et il a mal parlé du Roi; puis ils le menèrent hors de la ville, et l’assommèrent de pierres, et il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Après cela ils envoyèrent vers Izebel, pour lui dire: Naboth a été lapidé, et il est mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Et il arriva qu’aussitôt qu’Izebel eut entendu que Naboth avait été lapidé, et qu’il était mort, elle dit à Achab: Lève-toi, mets-toi en possession de la vigne de Naboth Jizréhélite, qui avait refusé de te la donner pour de l’argent; car Naboth n’est plus en vie, mais il est mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Ainsi dès qu’Achab eut entendu que Naboth était mort, il se leva pour descendre en la vigne de Naboth Jizréhélite, et pour s’en mettre en possession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Alors la parole de l’Eternel fut adressée à Elie Tisbite, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Lève-toi, descends au devant d’Achab Roi d’Israël, lorsqu’il sera à Samarie; voilà il est dans la vigne de Naboth, où il est descendu pour s’en mettre en possession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Et tu lui parleras, en disant: Ainsi a dit l’Eternel: N’as-tu pas tué, et ne t’es-tu pas même mis en possession? Puis tu lui parleras ainsi, et diras: Ainsi a dit l’Eternel: Comme les chiens ont léché le sang de Naboth, les chiens lécheront aussi ton propre sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Et Achab dit à Elie: M’as-tu trouvé toi, mon ennemi? Mais il lui répondit: Oui, je t’ai trouvé, parce que tu t’es vendu pour faire ce qui déplaît à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Voici je m’en vais amener du mal sur toi, et je t’exterminerai entièrement; et depuis l’homme jusqu’à un chien, je retrancherai ce qui appartient à Achab, tant ce qui est serré, que ce qui est délaissé en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Et je mettrai ta maison au même état que j’ai mis la maison de Jéroboam fils de Nébat, et la maison de Bahasa, fils d’Ahija à cause du péché par lequel tu m’as irrité, et as fait pécher Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'L’Eternel parla aussi contre Izebel, disant: Les chiens mangeront Izebel près du rempart de Jizréhel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Celui qui appartient à Achab, et qui mourra dans la ville, les chiens le mangeront; et celui qui mourra aux champs, les oiseaux des cieux le mangeront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'En effet il n’y en avait point eu de semblable à Achab, qui se fût vendu pour faire ce qui déplaît à l’Eternel, selon que sa femme Izebel l’induisait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'De sorte qu’il se rendit fort abominable, allant après les dieux de fiente, selon tout ce qu’avaient fait les Amorrhéens que l’Eternel avait chassés de devant les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Et il arriva qu’aussitôt qu’Achab eut entendu ces paroles, il déchira ses vêtements, et mit un sac sur sa chair, et jeûna, et il se tenait couché, enveloppé d’un sac, et se traînait en marchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Et la parole de l’Eternel fut adressée à Elie Tisbite, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'N’as-tu pas vu qu’Achab s’est humilié devant moi? Or parce qu’il s’est humilié devant moi, je n’amènerai point ce mal en son temps, ce sera aux jours de son fils que j’amènerai ce mal sur sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Or on demeura trois ans sans qu’il y eût guerre entre la Syrie et Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'Puis il arriva en la troisième année, que Josaphat Roi de Juda étant descendu vers le Roi d’Israël,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Le Roi d’Israël dit à ses serviteurs: Ne savez-vous pas bien que Ramoth de Galaad nous appartient, et nous ne nous mettons point en devoir pour la retirer d’entre les mains du Roi de Syrie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Puis il dit à Josaphat: Ne viendras-tu pas avec moi à la guerre contre Ramoth de Galaad? Et Josaphat répondit au Roi d’Israël: Fais ton compte de moi comme de toi, et de mon peuple comme de ton peuple, et de mes chevaux comme de tes chevaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Josaphat dit encore au Roi d’Israël: Je te prie qu’aujourd’hui tu t’enquières de la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Et le Roi d’Israël assembla environ quatre cents Prophètes, auxquels il dit: Irai-je à la guerre contre Ramoth de Galaad, ou m’en éloigne-je? Et ils répondirent: Monte, car le Seigneur la livrera entre les mains du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Mais Josaphat dit: N’y a-t-il point ici encore quelque Prophète de l’Eternel, afin que nous l’interrogions?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Et le Roi d’Israël dit à Josaphat: Il y a encore un homme pour s’enquérir de l’Eternel par son moyen, mais je le hais, car il ne prophétise rien de bon, mais du mal, quand il est question de moi: c’est Michée fils de Jimla. Et Josaphat dit: Que le Roi ne parle point ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Alors le Roi d’Israël appela un Eunuque auquel il dit: Fais venir en diligence Michée fils de Jimla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Or le Roi d’Israël, et Josaphat Roi de Juda étaient assis chacun sur son trône, revêtus de leurs habits, dans la place, vers l’entrée de la porte de Samarie; et tous les prophètes prophétisaient en leur présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Et Tsidkija fils de Kénahana s’étant fait des cornes de fer, dit: Ainsi a dit l’Eternel: De ces cornes-ci tu heurteras les Syriens, jusqu’à les détruire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Et tous les Prophètes prophétisaient de même, en disant: Monte à Ramoth de Galaad, et tu réussiras; et l’Eternel la livrera entre les mains du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Or le messager qui était allé appeler Michée, lui parla, en disant: Voici maintenant, les Prophètes prophétisent tous d’une voix du bonheur au Roi; je te prie que ta parole soit semblable à celle de l’un d’eux, et prophétise lui du bonheur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Mais Michée lui répondit: L’Eternel est vivant, que je dirai ce que l’Eternel me dira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Il vint donc vers le Roi, et le Roi lui dit: Michée, irons-nous à la guerre contre Ramoth de Galaad; ou nous en désisterons-nous? Et il lui répondit: Monte, tu réussiras; et l’Eternel la livrera entre les mains du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Et le Roi lui dit: Jusqu’à combien de fois te conjurerai-je, de ne me dire que la vérité au Nom de l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Et il répondit: J’ai vu tout Israël dispersé par les montagnes, comme un troupeau de brebis qui n’a point de pasteur; et l’Eternel a dit: Ceux-ci sont sans Seigneurs; que chacun s’en retourne dans sa maison en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Alors le Roi d’Israël dit à Josaphat: Ne t’ai-je pas bien dit que quand il est question de moi il ne prophétise rien de bon, mais du mal?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Et Michée lui dit: Ecoute néanmoins la parole de l’Eternel; J’ai vu l’Eternel assis sur son trône, et toute l’armée des cieux se tenant devant lui, à sa droite et à sa gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Et l’Eternel a dit: Qui est-ce qui induira Achab, afin qu’il monte et qu’il tombe en Ramoth de Galaad? et l’un parlait d’une manière, et l’autre d’une autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Alors un esprit s’avança, et se tint devant l’Eternel, et dit: Je l’induirai. Et l’Eternel lui dit: Comment?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Et il répondit: Je sortirai, et je serai un esprit de mensonge dans la bouche de tous ses Prophètes. Et l’Eternel dit: Oui tu l’induiras, et même tu en viendras à bout; sors, et fais-le ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Maintenant donc voici, l’Eternel a mis un esprit de mensonge dans la bouche de tous ces tiens Prophètes, et l’Eternel a prononcé du mal contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Alors Tsidkija fils de Kénahana s’approcha, et frappa Michée sur la joue, et dit: Par où l’Esprit de l’Eternel s’est-il retiré de moi pour s’adresser à toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Et Michée répondit: Voici, tu le verras le jour que tu iras de chambre en chambre pour te cacher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Alors le Roi d’Israël dit: Qu’on prenne Michée, et qu’on le mène vers Amon, capitaine de la ville, et vers Joas le fils du Roi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'Et qu’on leur dise: Ainsi a dit le Roi: Mettez cet homme en prison, et ne lui donnez qu’un peu de pain à manger, et un peu d eau à boire, jusqu’à ce que je revienne en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Et Michée répondit: Si jamais tu reviens en paix, l’Eternel n’aura point parlé par moi. Il dit aussi: Entendez cela peuples, vous tous qui êtes ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Le Roi d’Israël donc monta avec Josaphat Roi de Juda contre Ramoth de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Et le Roi d’Israël dit à Josaphat: Que je me déguise, et que j’aille à la bataille; mais toi, revêts-toi de tes habits. Le Roi d’Israël donc se déguisa, et alla à la bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Or le Roi des Syriens avait commandé aux trente-deux capitaines de ses chariots, en disant: Vous ne combattrez contre qui que ce soit petit ou grand, mais contre le seul Roi d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Il arriva donc que dès que les capitaines des chariots eurent vu Josaphat, ils dirent: C’est certainement le Roi d’Israël; et ils se détournèrent vers lui pour le combattre, mais Josaphat s’écria.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Et sitôt que les capitaines des chariots eurent vu que ce n’était pas le Roi d’Israël, ils se détournèrent de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Alors quelqu’un tira de son arc de toute sa force, et frappa le Roi d’Israël entre les tassettes et les harnais; et le Roi dit à son cocher: Tourne ta main, et mène-moi hors du camp; car on m’a fort blessé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Or la bataille fut très-grande en ce jour-là; et le Roi d’Israël fut arrêté dans son chariot vis-à-vis des Syriens, et mourut sur le soir; et le sang de sa plaie coulait sur le fond du chariot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Et sitôt que le soleil fut couché, on fit crier par le camp, en disant: que chacun se retire en sa ville, et chacun en son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Le Roi donc mourut, et fut porté à Samarie, et y fut enseveli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Et on lava le chariot au vivier de Samarie, et les chiens léchèrent son sang, et aussi quand on lava ses armes, selon là parole que l’Eternel avait prononcée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Le reste des faits d’Achab, tout ce, dis-je, qu’il a fait, et quant à la maison d’ivoire qu’il bâtit, et à toutes les villes qu’il bâtit, toutes ces choses ne sont-elles pas écrites au Livre des Chroniques des Rois d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Ainsi Achab s’endormit avec ses pères, et Achazia son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Or Josaphat fils d’Asa avait commencé à régner sur Juda la quatrième année d’Achab, Roi d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Et Josaphat était âgé de trente-cinq ans, quand il commença à régner; et il régna vingt-cinq ans à Jérusalem. Le nom de sa mère était Hazuba, fille de Silhi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Et il suivit entièrement la voie d’Asa son père, et il ne s’en détourna point, faisant tout ce qui est droit devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Toutefois les hauts lieux ne furent point ôtés; le peuple sacrifiait encore et faisait des encensements dans les hauts lieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Josaphat fit aussi la paix avec le Roi d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Le reste des faits de Josaphat, et les exploits qu’il fit, et les guerres qu’il eut, ne sont-elles pas écrites au Livre des Chroniques des Rois de Juda?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Quant aux restes des prostitués qui étaient demeurés depuis le temps d’Asa son père, il les extermina du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Il n’y avait point alors de Roi en Edom; le Gouverneur était Viceroi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Josaphat équipa une flotte de Tharsis, pour aller quérir de l’or à Ophir; mais elle n’y alla point, parce que les navires furent brisés à Hetsjon-guéber.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Alors Achazia fils d’Achab dit à Josaphat: Que mes serviteurs aillent sur les navires avec les tiens; mais Josaphat ne le voulut point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Et Josaphat s’endormit avec ses pères, et fut enseveli avec eux en la Cité de David son père, et Joram son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Achazia fils d’Achab commença à régner sur Israël à Samarie, la dix-septième année de Josaphat Roi de Juda, et il régna deux ans sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Et il fit ce qui déplaît à l’Eternel, et suivit le train de son père, et le train de sa mère, et le train de Jéroboam fils de Nébat, qui avait fait pécher Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 54, 'Il servit Bahal, il se prosterna devant lui, et il irrita l’Eternel le Dieu d’Israël, comme avait fait son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Or après la mort d’Achab Moab se rebella contre Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Et Achazia tomba par le treillis de sa chambre haute qui était à Samarie, et en fut malade; et il envoya des messagers, et leur dit: Allez consulter Bahal-zébub, dieu de Hékron, pour savoir si je relèverai de cette maladie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Mais l’Ange de l’Eternel parla à Elie Tisbite, en disant: Lève-toi, monte au devant des messagers du Roi de Samarie, et leur dis: N’y a-t-il point de Dieu en Israël, que vous alliez consulter Bahal-zébub, dieu de Hékron?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'C’est pourquoi ainsi a dit l’Eternel: Tu ne descendras point du lit sur lequel tu es monté, mais certainement tu mourras. Cela dit, Elie s’en alla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Et les messagers s’en retournèrent vers Achazia, et il leur dit: Pourquoi êtes-vous revenus?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Et ils lui répondirent: Un homme est monté au-devant de nous, qui nous a dit: Allez, retournez vous-en vers le Roi qui vous a envoyés, et dites-lui: Ainsi a dit l’Eternel: N’y a-t-il point de Dieu en Israël, que tu envoies consulter Bahal-zébub dieu de Hékron? A cause de cela tu ne descendras point du lit sur lequel tu es monté, mais certainement tu mourras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Et il leur dit: Comment était fait cet homme qui est monté au devant de vous, et qui vous a dit ces paroles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Et ils lui répondirent: C’est un homme vêtu de poil, qui a une ceinture de cuir, ceinte sur ses reins; et il dit: C’est Elie Tisbite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Alors il envoya vers lui un capitaine de cinquante hommes, avec sa cinquantaine, lequel monta vers lui. Or voilà, il se tenait au sommet d’une montagne, et ce capitaine lui dit: Homme de Dieu, le Roi a dit que tu aies à descendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Mais Elie répondit, et dit au capitaine de la cinquantaine: Si je suis un homme de Dieu, que le feu descende des cieux, et te consume, toi et ta cinquantaine! Et le feu descendit des cieux, et le consuma, lui et sa cinquantaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Et Achazia envoya encore un autre capitaine de cinquante hommes avec sa cinquantaine, qui prit la parole, et lui dit: Homme de Dieu, ainsi a dit le Roi: Hâte-toi de descendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Mais Elie répondit, et leur dit: Si je suis un homme de Dieu, que le feu descende des cieux et te consume, toi et ta cinquantaine; et le feu de Dieu descendit des cieux, et le consuma, lui et sa cinquantaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Et Achazia envoya encore un capitaine d’une troisième cinquantaine avec sa cinquantaine, et ce troisième capitaine de cinquante hommes monta, et vint, et se courba sur ses genoux devant Elie, et le supplia, et lui dit: Homme de Dieu, je te prie que tu fasses cas de ma vie, et de la vie de ces cinquante hommes tes serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Voilà, le feu est descendu des cieux, et a consumé les deux premiers capitaines de cinquante hommes, avec leurs cinquantaines; mais maintenant je te prie, que tu fasses cas de ma vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Et l’Ange de l’Eternel dit à Elie: Descends avec lui, n’aie point peur de lui. Il se leva donc, et descendit avec lui vers le Roi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Et lui dit: Ainsi a dit l’Eternel: Parce que tu as envoyé des messagers pour consulter Bahal-zébub dieu de Hékron, comme s’il n’y avait point de Dieu en Israël, pour consulter sa parole: tu ne descendras point du lit sur lequel tu es monté, mais certainement tu mourras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Il mourut donc, selon la parole de l’Eternel, qu’Elie avait prononcée; et Joram commença à régner en sa place, la seconde année de Joram, fils de Josaphat, Roi de Juda, parce qu’Achazia n’avait point de fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Le reste des faits d’Achazia, lesquels il fit, n’est-il pas écrit au Livre des Chroniques des Rois d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Or il arriva lorsque l’Eternel voulut enlever Elie aux cieux par un tourbillon, qu’Elie et Elisée partirent de Guilgal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Et Elie dit à Elisée: Je te prie demeure ici, car l’Eternel m’envoie jusqu’à Bethel. Mais Elisée répondit: L’Eternel est vivant, et ton âme est vivante, que je ne te laisserai point; ainsi ils descendirent à Bethel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Et les fils des Prophètes qui étaient à Bethel, sortirent vers Elisée, et lui dirent: Ne sais-tu pas bien qu’aujourd’hui l’Eternel va enlever ton maître d’avec toi? Et il répondit: Je le sais bien aussi; taisez-vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Et Elie lui dit: Elisée, je te prie, demeure ici, car l’Eternel m’envoie à Jérico. Mais il lui répondit: L’Eternel est vivant, et ton âme est vivante, que je ne te laisserai point! Ainsi ils s’en allèrent à Jérico.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Et les fils des Prophètes qui étaient à Jérico vinrent vers Elisée, et lui dirent: Ne sais-tu pas bien que l’Eternel va enlever aujourd’hui ton maître d’avec toi? Et il répondit: Je le sais bien aussi; taisez-vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Et Elie lui dit: Elisée, je te prie demeure ici, car l’Eternel m’envoie jusqu’au Jourdain. Mais il répondit: L’Eternel est vivant, et ton âme est vivante, que je ne te laisserai point; ainsi ils s’en allèrent eux deux ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Et cinquante hommes d’entre les fils des Prophètes vinrent, et se tinrent loin vis-à-vis; et eux deux s’arrêtèrent près du Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Alors Elie prit son manteau, et le replia, et il en frappa les eaux, qui se divisèrent en deux, et ils passèrent tous deux à sec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Quand ils furent passés, Elie dit à Elisée: Demande ce que tu veux que je fasse pour toi, avant que je sois enlevé d’avec toi. Et Elisée répondit: Je te prie que j’aie de ton esprit autant que deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Et il lui dit: Tu as demandé une chose difficile; si tu me vois enlever d’avec toi, cela te sera accordé; mais si tu ne me vois point, cela ne te sera point accordé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Et il arriva que comme ils marchaient, en parlant, voilà, un chariot de feu et des chevaux de feu les séparèrent l’un de l’autre; et Elie monta aux cieux par un tourbillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Et Elisée le regardant criait: Mon père! mon père! chariot d’Israël, et sa cavalerie! et il ne le vit plus; puis prenant ses vêtements, il les déchira en deux pièces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Et il leva le manteau d’Elie qui était tombé de dessus lui, et s’en retourna, et s’arrêta sur le bord du Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Ensuite il prit le manteau d’Elie, qui était tombé de dessus lui, et frappa les eaux, et dit: Où est l’Eternel le Dieu d’Elie, l’Eternel lui-même? Il frappa donc les eaux, et elles se divisèrent en deux; et Elisée passa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Et quand les fils des Prophètes qui étaient à Jérico vis-à-vis, l’eurent vu, ils dirent: L’Esprit d’Elie s’est posé sur Elisée, et ils vinrent au-devant de lui, et se prosternèrent devant lui en terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'Et lui dirent: Voici maintenant avec tes serviteurs cinquante hommes puissants, nous te prions qu’ils s’en aillent chercher ton maître, de peur que l’Esprit de l’Eternel ne l’ait enlevé, et ne l’ait jeté sur quelque montagne, ou dans quelque vallée; et il répondit: N’y envoyez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Mais ils le pressèrent tant par leurs paroles, qu’il en était honteux. Il leur dit donc: Envoyez-y. Et ils envoyèrent ces cinquante hommes, qui pendant trois jours cherchèrent Elie, mais ils ne le trouvèrent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Puis ils retournèrent vers lui à Jérico, où il s’était arrêté, et il leur dit: Ne vous avais-je pas dit de n’y aller point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Et les gens de la ville dirent à Elisée: Voici maintenant, la demeure de cette ville est bonne, comme mon Seigneur voit, mais les eaux en sont mauvaises, et la terre en est stérile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Et il dit: Apportez-moi un vase neuf, et mettez-y du sel; et ils le lui apportèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Puis il alla vers le lieu d’où sortaient les eaux, et il y jeta le sel, en disant: Ainsi a dit l’Eternel: J’ai rendu ces eaux saines, elles ne causeront plus la mort, et la terre ne sera plus stérile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Elles furent donc rendues saines, et elles l’ont été jusqu’à ce jour, selon la parole qu’Elisée avait proférée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Il monta de là à Bethel; et comme il montait par le chemin, des petits garçons sortirent de la ville, et en se moquant de lui, ils lui disaient: Monte chauve, monte chauve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Et Elisée regarda derrière lui, et les ayant regardés, il les maudit au Nom de l’Eternel; sur quoi deux ourses sortirent de la forêt, et déchirèrent quarante-deux de ces enfants-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Et il s’en alla de là en la montagne de Carmel, d’où il s’en retourna à Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Or la dix-huitième année de Josaphat Roi de Juda, Joram fils d’Achab avait commencé à régner sur Israël en Samarie, et il régna douze ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Et fit ce qui déplaît à l’Eternel, non pas toutefois comme avaient fait son père et sa mère, car il ôta la statue de Bahal que son père avait faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Mais il adhéra aux péchés de Jéroboam fils de Nébat, par lesquels il avait fait pécher Israël, et ne se détourna point d’aucun d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Or Mésah, Roi de Moab, se mêlait de bétail, et payait au Roi d’Israël cent mille agneaux, et cent mille moutons portant laine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Mais aussitôt qu’Achab fut mort, il arriva que le Roi de Moab se rebella contre le Roi d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'C’est pourquoi le Roi Joram sortit ce jour-là de Samarie, et dénombra tout Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Puis il alla, et envoya vers Josaphat Roi de Juda, pour lui dire: Le Roi de Moab s’est rebellé contre moi, ne viendras-tu pas avec moi à la guerre contre Moab? et il répondit: J’y monterai; fais ton compte de moi comme de toi, de mon peuple comme de ton peuple, et de mes chevaux comme de tes chevaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Ensuite il dit: Par quel chemin monterons-nous? Et il répondit: Par le chemin du désert d’Edom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Ainsi le Roi d’Israël, et le Roi de Juda, et le Roi d’Edom partirent, et tournoyèrent par le chemin durant sept jours, jusqu’à ce qu’ils n’eurent plus d’eau pour le camp, ni pour les bêtes qu’ils menaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Et le Roi d’Israël dit: Ha! Ha! certainement l’Eternel a appelé ces trois Rois pour les livrer entre les mains de Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Et Josaphat dit: N’y a-t-il point ici quelque Prophète de l’Eternel, afin que par son moyen nous consultions l’Eternel? Et un des serviteurs du Roi d’Israël répondit, et dit: Il y a ici Elisée fils de Saphat, qui versait de l’eau sur les mains d’Elie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Alors Josaphat dit: La parole de l’Eternel est avec lui; et le Roi d’Israël, et Josaphat, et le Roi d’Edom descendirent vers lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Mais Elisée dit au Roi d’Israël: Qu’y a-t-il entre moi et toi? va-t’en vers les prophètes de ton père, et vers les prophètes de ta mère. Et le Roi d’Israël lui répondit: Non; car l’Eternel a appelé ces trois Rois pour les livrer entre les mains de Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Et Elisée dit: L’Eternel des armées, devant lequel je me tiens, est vivant, que si je n’avais de la considération pour Josaphat le Roi de Juda, je n’aurais aucun égard pour toi, et ne t’aurais même pas vu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Mais maintenant amenez-moi un joueur d’instruments. Et comme le joueur jouait des instruments, la main de l’Eternel fut sur Elisée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Et il dit: Ainsi a dit l’Eternel: Qu’on coupe par des fossés toute cette vallée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Car ainsi a dit l’Eternel: Vous ne verrez ni vent, ni pluie, et néanmoins cette vallée sera remplie d’eaux, et vous boirez, vous et vos bêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Encore cela est peu de chose pour l’Eternel; car il livrera Moab entre vos mains;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Et vous détruirez toutes les villes fortes, et toutes les villes principales, et vous abattrez tous les bons arbres, et vous boucherez toutes les fontaines d’eaux, et vous gâterez avec des pierres tous les meilleurs champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Il arriva donc au matin, environ l’heure qu’on offre l’oblation, qu’on vit venir des eaux du chemin d’Edom, en sorte que ce lieu-là fut rempli d’eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Or tous les Moabites ayant appris que ces Rois-là étaient montés pour leur faire la guerre, s’étaient assemblés à cri public, depuis tous ceux qui étaient en âge de porter les armes, et au-dessus, et ils se tinrent sur la frontière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Et le lendemain ils se levèrent de bon matin, et comme le soleil fut levé sur les eaux, les Moabites virent vis-à-vis d’eux les eaux rouges comme du sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'Et ils dirent: C’est du sang; certainement ces Rois-là se sont entre-tués, et chacun a frappé son compagnon; maintenant donc, Moabites, au butin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Ainsi ils vinrent au camp d’Israël, et les Israëlites se levèrent, et frappèrent les Moabites, lesquels s’enfuirent devant eux; puis ils entrèrent au pays, et frappèrent Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Ils détruisirent les villes; et chacun jetait des pierres dans les meilleurs champs, de sorte qu’ils les en remplirent; ils bouchèrent toutes les fontaines d’eaux, et abattirent tous les bons arbres, jusqu’à ne laisser que les pierres à Kir-haréseth, laquelle les tireurs de fronde environnèrent, et battirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Et le Roi de Moab voyant qu’il n’était pas le plus fort, prit avec lui sept cents hommes dégainant l’épée, pour enfoncer jusqu’au Roi d’Edom; mais ils ne purent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Alors il prit son fils premier-né, qui devait régner en sa place, et l’offrit en holocauste sur la muraille, et il y eut une grande indignation en Israël; ainsi ils se retirèrent de lui, et s’en retournèrent en leur pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Or une veuve d’un des fils des Prophètes cria à Elisée, en disant: Ton serviteur mon mari est mort, et tu sais que ton serviteur craignait l’Eternel, et son créancier est venu pour prendre mes deux enfants, afin qu’ils soient ses esclaves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Et Elisée lui répondit: Qu’est-ce que je ferai pour toi? déclare-moi ce que tu as en la maison. Et elle dit: Ta servante n’a rien dans toute la maison qu’un pot d’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Alors il lui dit: Va, demande des vaisseaux dans la rue à tous tes voisins, des vaisseaux vides, et n’en demande pas même en petit nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Puis rentre, et ferme la porte sur toi et sur tes enfants, et verse de ce pot d’huile dans tous ces vaisseaux, faisant ôter ceux qui seront pleins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Elle se retira donc d’auprès de lui, et ayant fermé la porte sur elle et sur ses enfants, ils lui apportaient les vaisseaux, et elle versait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Et il arriva qu’aussitôt qu’elle eut rempli les vaisseaux, elle dit à son fils: Apporte-moi encore un vaisseau; et il répondit: Il n’y a plus de vaisseau; et l’huile s’arrêta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Puis elle s’en vint, et le raconta à l’homme de Dieu, qui lui dit: Va, vends l’huile, et paye ta dette; et vous vivrez, toi et tes fils, de ce qu’il y aura de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Or il arriva qu’un jour qu’Elisée passait par Sunem, où il y avait une femme qui avait de grands biens, elle le retint avec grande instance à manger du pain; et toutes les fois qu’il passait, il s’y retirait pour manger du pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Et elle dit à son mari: Voilà, je connais maintenant que cet homme qui passe souvent chez nous, est un saint homme de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Faisons-lui, je te prie, une petite chambre haute, et mettons-lui là un lit, une table, un siège, et un chandelier, afin que quand il viendra chez nous, il se retire là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Etant donc un jour venu là, il se retira dans cette chambre haute, et y reposa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Puis il dit à Guéhazi son serviteur: Appelle cette Sunamite, et il l’appela; et elle se présenta devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Et il dit à Guéhazi: Dis maintenant à cette femme: Voici, tu as pris tous ces soins pour nous, que pourrait-on faire pour toi? as-tu à parler au Roi, ou au Chef de l’armée? Et elle répondit: J’habite au milieu de mon peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Et il dit à Guéhazi: Que faudrait-il faire pour elle? Et Guéhazi répondit: Certes elle n’a point de fils, et son mari est vieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Et Elisée lui dit: Appelle-la; et il l’appela, et elle se présenta à la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Et il lui dit: L’année qui vient, et en cette même saison, tu embrasseras un fils. Et elle répondit: Mon seigneur, homme de Dieu, ne mens point, ne mens point à ta servante!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Cette femme-là donc conçut, et enfanta un fils un an après, en la même saison, comme Elisée lui avait dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Et l’enfant étant devenu grand, il sortit un jour pour aller trouver son père, vers les moissonneurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Et il dit à son père: Ma tête! ma tête! et le père dit au serviteur: Porte-le à sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Il le porta donc et l’amena à sa mère, et il demeura sur ses genoux jusqu’à midi, puis il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Et elle monta, et le coucha sur le lit de l’homme de Dieu, et ayant fermé la porte sur lui, elle sortit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Puis elle cria à son mari, et dit: Je te prie envoie-moi un des serviteurs, et une ânesse, et je m’en irai jusqu’à l’homme de Dieu, puis je retournerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Et il dit: Pourquoi vas-tu vers lui aujourd’hui? ce n’est point la nouvelle Lune, ni le Sabbat. Et elle répondit: Tout va bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Elle fit donc seller l’ânesse, et dit à son serviteur: Mène-moi, et marche, et ne me retarde pas d’avancer chemin sur l’Anesse, si je ne te le dis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Ainsi elle s’en alla, et vint vers l’homme de Dieu en la montagne de Carmel; et sitôt que l’homme de Dieu l’eut vue venant vers lui, il dit à Guéhazi son serviteur: Voilà la Sunamite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Va, cours au-devant d’elle, et lui dis: Te portes-tu bien? ton mari se porte-t-il bien? l’enfant se porte-t-il bien? Et elle répondit: Nous nous portons bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Puis elle vint vers l’homme de Dieu en la montagne, et empoigna ses pieds; et Guéhazi s’approcha pour la repousser, mais l’homme de Dieu lui dit: Laisse- la, car elle a son cœur angoissé, et l’Eternel me l’a caché, et ne me l’a point déclaré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Alors elle dit: Avais-je demandé un fils à mon Seigneur? et ne te dis-je pas: Ne fais point que je sois trompée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Et il dit à Guéhazi: Trousse tes reins, prends mon bâton en ta main, et t’en va; si tu trouves quelqu’un, ne le salue point; et si quelqu’un te salue, ne lui réponds point; puis tu mettras mon bâton sur le visage de l’enfant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Mais la mère de l’enfant dit: L’Eternel est vivant, et ton âme est vivante, que je ne te laisserai point; il se leva donc, et s’en alla après elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Or Guéhazi était passé devant eux, et avait mis le bâton sur le visage de l’enfant; mais il n’y eut en cet enfant ni voix, ni apparence qu’il eût entendu; ainsi Guéhazi s’en retourna au devant d’Elisée, et lui en fit le rapport, en disant: L’enfant ne s’est point réveillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Elisée donc entra dans la maison, et voilà l’enfant mort était couché sur son lit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Et étant entré, il ferma la porte sur eux deux, et fit sa prière à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Puis il monta et se coucha sur l’enfant, et mit sa bouche sur la bouche de l’enfant, et ses yeux sur ses yeux, et ses paumes sur ses paumes, et se pencha sur lui; et la chair de l’enfant fut échauffée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Puis il se retirait et allait par la maison, tantôt dans un lieu, tantôt dans un autre, et il remontait, et se penchait encore sur lui; enfin l’enfant éternua par sept fois, et ouvrit ses yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Alors Elisée appela Guéhazi, et lui dit: Appelle cette Sunamite; et il l’appela; et elle vint à lui; et il lui dit: Prends ton fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Elle s’en vint donc, se jeta à ses pieds, et se prosterna en terre; puis elle prit son fils, et sortit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Après cela Elisée revint à Guilgal. Or il y avait une famine au pays, et les fils des Prophètes étaient assis devant lui; et il dit à son serviteur: Mets la grande chaudière, et cuis du potage pour les fils des Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Mais quelqu’un étant sorti aux champs pour cueillir des herbes, trouva de la vigne sauvage, et en cueillit des coloquintes sauvages pleine sa robe, et étant revenu, il les mit par pièces dans la chaudière où était le potage; car on ne savait point ce que c’était.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Et on dressa de ce potage à quelques-uns pour en manger; mais sitôt qu’ils eurent mangé de ce potage, ils s’écrièrent et dirent: Homme de Dieu, la mort est dans la chaudière; et ils n’en purent manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Et il dit: Apportez-moi de la farine; et il la jeta dans la chaudière, puis il dit: Qu’on en dresse à ce peuple, afin qu’il mange; et il n’y avait plus rien de mauvais dans la chaudière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Alors il vint un homme de Bahalsalisa, qui apporta à l’homme de Dieu du pain des premiers fruits, savoir vingt pains d’orge, et du grain en épi étant avec sa paille; et Elisée dit: Donne cela à ce peuple, afin qu’ils mangent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Et son serviteur lui dit: Donnerais-je ceci à cent hommes? Mais il lui répondit: Donne-le à ce peuple, et qu’ils mangent. Car ainsi a dit l’Eternel: Ils mangeront, et il y en aura de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Il mit donc cela devant eux, et ils mangèrent, et ils en laissèrent de reste, suivant la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Or Naaman, Chef de l’armée du Roi de Syrie était un homme puissant auprès de son Seigneur, et il était en grand honneur, parce que l’Eternel avait délivré les Syriens par son moyen, mais cet homme fort et vaillant était lépreux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Et quelques troupes sorties de Syrie, avaient amené prisonnière une petite fille du pays d’Israël, qui servait la femme de Naaman.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Et elle dit à sa maîtresse; Je souhaiterais que mon Seigneur se présentât devant le Prophète qui est en Samarie, il l’aurait aussitôt délivré de sa lèpre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Quelqu’un donc vint et le rapporta à son Seigneur, en disant: La fille qui est du pays d’Israël, a dit telle et telle chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Et le Roi de Syrie dit à Naaman: Va, vas-y, et j’enverrai des Lettres au Roi d’Israël. Naaman donc s’en alla, et prit avec soi dix talents d’argent, et six mille pièces d’or, et dix robes de rechange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Et il apporta au Roi d’Israël des Lettres de telle teneur. Maintenant, dès- que ces Lettres te seront parvenues, sache que je t’ai envoyé Naaman mon serviteur, afin que tu le délivres de sa lèpre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Or, dès que le Roi d’Israël eut lu les Lettres il déchira ses vêtements, et dit: Suis-je Dieu pour faire mourir, et pour rendre la vie, que celui-ci envoie vers moi, pour délivrer un homme de sa lèpre? C’est pourquoi sachez maintenant, et voyez qu’il cherche occasion contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Mais il arriva que dès qu’Elisée, homme de Dieu, eut appris que le Roi d’Israël avait déchiré ses vêtements, il envoya dire au Roi: Pourquoi as-tu déchiré tes vêtements? Qu’il s’en vienne maintenant vers moi, et qu’il sache qu’il y a un Prophète en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Naaman donc s’en vint avec ses chevaux, et avec son chariot, et il se tint à la porte de la maison d’Elisée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Et Elisée envoya un messager vers lui, pour lui dire: Va, et te lave sept fois au Jourdain, et ta chair te reviendra telle qu’auparavant, et tu seras net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Mais Naaman se mit en grande colère, et s’en alla, en disant: Voilà, je pensais en moi-même: Il sortira incontinent, et invoquera le Nom de l’Eternel son Dieu, et il avancera sa main sur l’endroit de la plaie, et délivrera le lépreux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Abana et Parpar, fleuves de Damas, ne sont-ils pas meilleurs que toutes les eaux d’Israël? ne m’y laverais-je pas bien? mais deviendrais-je net? ainsi donc il s’en retournait, et s’en allait tout en colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Mais ses serviteurs s’approchèrent, et lui parlèrent, en disant: Mon père, si le Prophète t’eût dit quelque grande chose, ne l’eusses-tu pas faite? Combien plutôt donc dois-tu faire ce qu’il t’a dit: Lave-toi, et tu deviendras net?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Ainsi il descendit, et se plongea sept fois au Jourdain, suivant la parole de l’homme de Dieu; et sa chair lui revint semblable à la chair d’un petit enfant; et il fut net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Alors il retourna vers l’homme de Dieu, lui et toute sa suite, et il vint se présenter devant lui; et dit: Voici, maintenant je connais qu’il n’ y a point d’autre Dieu en toute la terre, qu’en Israël. Maintenant donc, je te prie, prends ce présent de ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Mais Elisée répondit: L’Eternel, en la présence duquel je me tiens, est vivant, que je ne le prendrai point; et quoique Naaman le pressât fort de le prendre, Elisée le refusa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Naaman dit: Or je te prie, ne pourrait-on point donner de cette terre à ton serviteur la charge de deux mulets? car ton serviteur ne fera plus d’holocauste ni de sacrifice à d’autres dieux, mais seulement à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'L’Eternel veuille pardonner ceci à ton serviteur; c’est que quand mon maître entrera dans la maison de Rimmon pour se prosterner là et qu’il s’appuiera sur ma main, je me prosternerai dans la maison de Rimmon; l’Eternel, dis-je, veuille me le pardonner, quand je me prosternerai dans la maison de Rimmon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Et Elisée lui dit: Va en paix. Ainsi étant parti d’auprès de lui il marcha environ quelque petit espace de pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Alors Guéhazi, le serviteur d Elisée homme de Dieu, dit: Voici, mon maître a refusé de prendre de la main de Naaman Syrien aucune chose de tout ce qu’il avait apporté, l’Eternel est vivant, que je courrai après lui, et que je prendrai quelque chose de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Guéhazi donc courut après Naaman; et Naaman le voyant courir après lui, se jeta hors de son chariot au-devant de lui, et lui dit: Tout va-t-il bien?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Et il répondit: Tout va bien. Mon maître m’a envoyé pour te dire: Voici, à cette heure deux jeunes hommes de la montagne d’Ephraïm sont venus vers moi, qui sont des fils des Prophètes; je te prie donne-leur un talent d’argent; et deux robes de rechange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Et Naaman dit: Prends hardiment deux talents; et il le pressa tant qu’on lia deux talents d’argent dans deux sacs; il lui donna aussi deux robes de rechange; et il les donna à deux de ses serviteurs qui les portèrent devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Et quand il fut venu en un lieu secret, il le prit d’entre leurs mains, et le serra dans une maison, après quoi il renvoya ces gens-là, et ils s’en retournèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Puis il entra, et se présenta devant son maître. Et Elisée lui dit: D’où viens-tu, Guéhazi? Et il lui répondit: Ton serviteur n’a été nulle part.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Mais Elisée lui dit: Mon cœur n’est-il pas allé là, quand l’homme s’est retourné de dessus son chariot au-devant de toi? Est-ce le temps de prendre de l’argent, et de prendre des vêtements, des oliviers, des vignes, du menu et du gros bétail, des serviteurs et des servantes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'C’est pourquoi là lèpre de Naaman s’attachera à toi, et à ta postérité à jamais. Et Guéhazi sortit de devant Elisée blanc de lèpre comme de la neige.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Or les fils des Prophètes dirent à Elisée: Voici maintenant, le lieu où nous sommes assis devant toi, est trop étroit pour nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Allons-nous-en maintenant jusqu’au Jourdain, et nous prendrons de là chacun de nous une pièce de bois, et nous ferons là un lieu pour y demeurer; et il répondit: Allez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Et l’un d’eux dit: Je te prie qu’il te plaise de venir avec tes serviteurs; et il répondit: J’y irai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Il s’en alla donc avec eux; et ils allèrent au Jourdain, et ils coupèrent du bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Mais il arriva que comme l’un d’eux abattait une pièce de bois, le fer de sa cognée tomba dans l’eau; et il s’écria, et dit: Hélas mon Seigneur! encore est-il emprunté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Et l’homme de Dieu dit: Où est-il tombé? et il lui montra l’endroit; alors Elisée coupa un morceau de bois, et le jeta là, et il fit nager le fer par dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Et il dit: Lève-le; et cet homme étendit sa main, et le prit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Or le Roi de Syrie faisant la guerre à Israël, tenait conseil avec ses serviteurs, et disait: En un tel et un tel lieu sera mon camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Et l’homme de Dieu envoyait dire au Roi d’Israël: Donne-toi de garde de passer en ce lieu-là, car les Syriens y sont descendus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Et le Roi d’Israël envoyait au lieu que lui disait l’homme de Dieu, et il y pourvoyait, et était sur ses gardes; ce qu’il fit plusieurs fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Et le coeur du Roi de Syrie en fut troublé, et il appela ses serviteurs, et leur dit: Ne me découvrirez-vous pas qui est celui des nôtres qui envoie vers le Roi d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Et l’un de ses serviteurs lui dit: Il n’y en a point, ô Roi mon Seigneur! mais Elisée le Prophète qui est en Israël, déclare au Roi d’Israël les paroles mêmes que tu dis dans la chambre où tu couches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Et il dit: Allez, et voyez où il est, afin que j’envoie pour le prendre; et on lui rapporta, en disant: Le voilà à Dothan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Et il envoya là des chevaux, et des chariots, et de grandes troupes, qui vinrent de nuit, et qui environnèrent la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Or le serviteur de l’homme de Dieu se leva de grand matin, et sortit, et voici des troupes, et des chevaux, et des chariots qui environnaient la ville; et le serviteur de l’homme de Dieu lui dit: Hélas mon Seigneur! comment ferons-nous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Et il lui répondit: Ne crains point; car ceux qui sont avec nous, sont en plus grand nombre que ceux qui sont avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Elisée donc pria, et dit: Je te prie, ô Eternel! ouvre ses yeux, afin qu’il voie; et l’Eternel ouvrit les yeux du serviteur, et il vit, et voici la montagne était pleine de chevaux, et de chariots de feu autour d’Elisée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Puis les Syriens descendirent vers Elisée, et il pria l’Eternel, et dit: Je te prie, frappe ces gens d’éblouissement; et Dieu les frappa d’éblouissement, selon la parole d’Elisée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Et Elisée leur dit: Ce n’est pas ici le chemin, et ce n’est pas ici la ville; venez après moi, et je vous mènerai vers l’homme que vous cherchez; et il les mena à Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Et il arriva que sitôt qu’ils furent entrés dans Samarie, Elisée dit: Ô Eternel ouvre leurs yeux afin qu’ils voient. Et l’Eternel ouvrit leurs yeux, et ils virent, et voici ils étaient au milieu de Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Et dès que le Roi d’Israël les eut vus, il dit à Elisée: Frapperai-je, frapperai-je, mon père?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Et il répondit: Tu ne frapperas point; frapperais-tu de ton épée et de ton arc ceux que tu aurais pris prisonniers? mets, au contraire, du pain et de l’eau devant eux, et qu’ils mangent et boivent, et qu’après cela ils s’en aillent vers leur Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Et il leur fit grand’chère, et ils mangèrent et burent; puis il les laissa aller, et ils s’en allèrent vers leur Seigneur. Depuis ce temps-là les partis de Syrie ne revinrent plus au pays d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Mais il arriva, après ces choses que Ben-hadad Roi de Syrie, assembla toute son armée, et monta, et assiégea Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Et il y eut une grande famine dans Samarie; car voilà, ils l’assiégèrent si longtemps, que la tête d’un âne se vendait quatre-vingts pièces d’argent, et la quatrième partie d’un kad de fiente de pigeons, cinq pièces d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Or il arriva que comme le Roi d’Israël passait sur la muraille, une femme lui cria, en disant: Ô Roi mon Seigneur! délivre-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Et il répondit: Puisque l’Eternel ne te délivre point, comment te délivrerais-je? Serait-ce de l’aire ou de la cuve?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Il lui dit encore: Qu’as-tu? Et elle répondit: Cette femme-là m’a dit: Donne ton fils, et mangeons-le aujourd’hui, et nous mangerons mon fils demain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Ainsi nous avons bouilli mon fils, et l’avons mangé, et le jour d’après je lui ai dit: Donne ton fils, et mangeons-le; mais elle a caché son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Or dès que le Roi eut entendu les paroles de cette femme, il déchira ses vêtements, (or il passait alors sur la muraille) ce que le peuple vit, et voilà il avait un sac sur sa chair en dedans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'C’est pourquoi le Roi dit: Dieu me fasse ainsi, et ainsi il y ajoute, si aujourd’hui la tête d’Elisée fils de Saphat demeure sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Et Elisée étant assis dans sa maison, et les Anciens étant assis avec lui, le Roi envoya un homme de sa part; mais avant que le messager fût venu à Elisée, Elisée dit aux Anciens: Ne voyez-vous pas que le fils de ce meurtrier-là a envoyé ici pour m’ôter la tête? Prenez garde, sitôt que le messager sera entré, de fermer la porte, et de l’arrêter à la porte; n’entendez-vous pas le bruit des pieds de son maître qui vient après lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Et comme il parlait encore avec eux, voici le messager descendit vers lui, et le Roi dit: Voici, ce mal vient de l’Eternel, qu’attendrai-je plus de l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Alors Elisée dit: Ecoutez la parole de l’Eternel. Ainsi a dit l’Eternel: Demain à cette heure-ci on donnera le sat de fine farine pour un sicle, et les deux sats d’orge pour un sicle, à la porte de Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Mais un capitaine, sur la main duquel le Roi s’appuyait, répondit à l’homme de Dieu, et dit: Quand l’Eternel ferait maintenant des ouvertures au ciel, cela arriverait-il? Et Elisée dit: Voilà, tu le verras de tes yeux, mais tu n’en mangeras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Or il y avait à l’entrée de la porte quatre hommes lépreux, et ils dirent l’un à l’autre: Pourquoi demeurons-nous ici, jusqu’à ce que nous mourions?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Si nous parlons d’entrer dans la ville, la famine y est, et nous mourrons là; et si nous demeurons ici, nous mourrons aussi. Maintenant donc venez, et glissons-nous au camp des Syriens; s’ils nous laissent vivre, nous vivrons, et s’ils nous font mourir, nous mourrons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'C’est pourquoi ils se levèrent avant le jour pour entrer au camp des Syriens, et ils vinrent jusqu’à l’un des bouts du camp, et voilà il n’y avait personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Car le Seigneur avait fait entendre dans le camp des Syriens un bruit de chariots, et un bruit de chevaux, et un bruit d’une grande armée; de sorte qu’ils avaient dit l’un à l’autre: Voilà le Roi d’Israël a payé les Rois des Héthiens, et les Rois des Egyptiens pour venir contre nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'C’est pourquoi ils s’étaient levés avant le point du jour, et s’étaient enfuis, et ils avaient laissé leurs tentes, leurs chevaux, leurs ânes, et le camp comme il était; et ils s’étaient enfuis pour sauver leur vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Ces lépreux-là donc entrèrent jusqu’à l’un des bouts du camp, puis ils vinrent dans une tente, ils mangèrent, ils burent, ils prirent de là de l’argent, de l’or, et des vêtements, et ils s’en allèrent, et les cachèrent. Après quoi ils retournèrent et entrèrent dans une autre tente, et prirent de là aussi des mêmes choses, et s’en allèrent, et les cachèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Alors ils dirent l’un à l’autre: Nous ne faisons pas bien; ce jour est un jour de bonnes nouvelles, et nous ne disons mot! si nous attendons jusqu’à ce que le jour soit venu, l’iniquité nous trouvera; maintenant donc venez, allons, et faisons-le savoir à la maison du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Ils vinrent donc, et crièrent aux portiers de la ville, et leur firent entendre, en disant: Nous sommes entrés dans le camp des Syriens, et voilà, il n’y a personne, et on n’y entend la voix d’aucun homme; mais il y a seulement des chevaux attachés, et des ânes attachés, et les tentes sont comme elles étaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Alors les portiers s’écrièrent; et le firent entendre dans la maison du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Et le Roi se leva de nuit, et dit à ses serviteurs: Je vous dirai maintenant ce que les Syriens nous auront fait. Ils ont connu que nous sommes affamés, et ils seront sortis du camp pour se cacher aux champs, disant: Quand ils seront sortis hors de la ville, nous les prendrons vifs, et nous entrerons dans la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Qu’on prenne tout-à-l’heure cinq des chevaux qui sont demeurés de reste dans la ville; car voilà c’est presque tout ce qui est resté du grand nombre des chevaux d’Israël, c’est là presque tout ce qui n’a point été consumé de cette multitude de chevaux d’Israël, et envoyons voir ce que c’est.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Ils prirent donc deux chevaux de chariot, et ainsi le Roi envoya après le camp des Syriens, en disant: Allez, et voyez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Et ils s’en allèrent après eux jusqu’au Jourdain, et voilà, le chemin était plein de vêtements, et de hardes que les Syriens avaient jetées en se hâtant; puis les messagers retournèrent, et le rapportèrent au Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Alors le peuple sortit, et pilla le camp des Syriens, de sorte qu’on donna le sat de fine farine pour un sicle, et les deux sats d’orge pour un sicle, selon la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Et le Roi donna charge de garder la porte, au capitaine, sur la main duquel il s’appuyait; et le peuple le foula à la porte, tellement qu’il mourut, suivant ce que l’homme de Dieu avait dit, en parlant au Roi lorsqu’il était descendu vers lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Car lorsque l’homme de Dieu avait parlé au Roi, en disant: Demain au matin à cette heure-ci, on donnera à la porte de Samarie les deux sats d’orge pour un sicle, et le sat de fine farine pour un sicle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'Ce capitaine-là avait répondu à l’homme de Dieu, et avait dit: Quand maintenant l’Eternel ferait des ouvertures au ciel, ce que tu dis pourrait-il arriver? Et l’homme de Dieu avait dit: Voilà, tu le verras de tes yeux, mais tu n’en mangeras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Il lui en arriva donc ainsi; car le peuple le foula à la porte, de sorte qu’il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Or Elisée avait parlé à la femme au fils de laquelle il avait rendu la vie, en disant: Lève-toi, et t’en va, toi et ta famille, et fais ton séjour où tu pourras; car l’Eternel a appelé la famine, et même elle vient sur le pays pour y demeurer sept ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Cette femme-là donc s’étant levée avait fait selon la parole de l’homme de Dieu, et s’en était allée, elle et sa famille, et avait demeuré sept ans au pays des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Mais il arriva qu’au bout des sept ans cette femme-là s’en retourna du pays des Philistins, puis elle s’en alla pour faire requête au Roi touchant sa maison, et ses champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Alors le Roi parlait à Guéhazi serviteur de l’homme de Dieu, en disant: Je te prie récite-moi toutes les grandes choses qu’Elisée a faites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Et il arriva que lorsqu’il récitait au Roi comment Elisée avait rendu la vie à un mort, voici, la femme, au fils de laquelle il avait rendu la vie, vint faire requête au Roi touchant sa maison, et ses champs. Et Guéhazi dit: Ô Roi mon Seigneur! c’est ici la femme, et c’est ici son fils, à qui Elisée a rendu la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Alors le Roi interrogea la femme; et elle lui raconta ce qui s’était passé. Et le Roi lui donna un Eunuque, auquel il dit: Fais lui r’avoir tout ce qui lui appartenait, même tous les revenus de ses champs depuis le temps qu’elle a quitté le pays jusqu’à maintenant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Or Elisée alla à Damas, et alors Ben-hadad Roi de Syrie était malade, et on lui rapporta, et on lui dit: L’homme de Dieu est venu ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Et le Roi dit à Hazaël: Prends quelque présent avec toi, et t’en va au devant de l’homme de Dieu, et par son moyen enquiers-toi de l’Eternel; en disant: Relèverai-je de cette maladie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Et Hazaël s’en alla au-devant de lui, ayant pris avec soi un présent, savoir, quarante chameaux chargés de tout ce qu’il y avait de meilleur à Damas, et il vint, et se présenta devant lui, et dit: Ton fils Ben-hadad Roi de Syrie m’a envoyé vers toi, pour te dire: Relèverai-je de cette maladie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Et Elisée lui répondit: Va, et dis-lui: Certainement tu en pourrais relever; toutefois l’Eternel m’a montré que certainement il mourra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Et l’homme de Dieu arrêta sa vue sur Hazaël, et se retint longtemps; puis l’homme de Dieu pleura.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Et Hazaël dit: Pourquoi pleure mon Seigneur? Et il répondit: Parce que je sais combien tu feras de mal aux enfants d’Israël; tu mettras le feu à leurs villes fortes, et tu tueras avec l’épée leurs jeunes gens, et tu écraseras leurs petits enfants, et tu fendras leurs femmes enceintes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Et Hazaël dit: Mais qui est ton serviteur, qui n’est qu’un chien, pour faire de si grandes choses? Et Elisée répondit: L’Eternel m’a montré que tu seras Roi de Syrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Ainsi Hazaël se retira d’avec Elisée, et revint vers son maître, qui lui demanda: Que t’a dit Elisée? Et il répondit: Il m’a dit, que certainement tu peux relever de cette maladie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Mais il arriva que le lendemain Hazaël prit un drap épais, et l’ayant plongé dans l’eau, il l’étendit sur le visage de Ben-hadad, dont il mourut; et Hazaël régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Or la cinquième année de Joram fils d’Achab Roi d’Israël, Josaphat étant Roi de Juda, Joram fils de Josaphat Roi de Juda, commença à régner sur Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Il était âgé de trente-deux ans quand il commença à régner, et il régna huit ans à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Et il suivit le train des Rois d’Israël comme avait fait la maison d’Achab; car la fille d’Achab était sa femme, de sorte qu’il fit ce qui est déplaisant à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Toutefois l’Eternel ne voulut point détruire Juda, pour l’amour de David son serviteur, selon ce qu’il lui avait dit, qu’il lui donnerait une lampe, à lui et à ses fils, à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'De son temps ceux d’Edom se révoltèrent de l’obéissance de Juda, et établirent un Roi sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'C’est pourquoi Joram passa à Tsahir avec tous ses chariots, et se leva de nuit, et frappa les Iduméens qui étaient autour de lui, et les Gouverneurs des chariots; mais le peuple s’enfuit dans ses tentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Néanmoins les Iduméens se révoltèrent de l’obéissance de Juda, et cela a duré jusqu’à aujourd’hui. En ce même temps-là Libna aussi se révolta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Le reste des faits de Joram, tout ce, dis-je, qu’il a fait, n’est-il pas écrit au Livre des Chroniques des Rois de Juda?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Et Joram s’endormit avec ses pères, et fut enseveli avec eux dans la Cité de David; et Achazia son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'La douzième année de Joram fils d’Achab Roi d’Israël, Achazia fils de Joram Roi de Juda, commença à régner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Achazia était âgé de vingt-deux ans quand il commença à régner, et il régna un an à Jérusalem; sa mère avait nom Hathalia, et était fille de Homri Roi d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Il suivit le train de la maison d’Achab, et fit ce qui déplaît à l’Eternel, comme avait fait la maison d’Achab; car il était gendre de la maison d’Achab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Or il s’en alla avec Joram fils d’Achab à la guerre contre Hazaël Roi de Syrie, et Ramoth de Galaad, et les Syriens frappèrent Joram.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Et le Roi Joram s’en retourna pour se faire panser à Jizréhel des plaies que les Syriens lui avaient faites à Rama, quand il combattit contre Hazaël Roi de Syrie, et Achazia fils de Joram, Roi de Juda, descendit pour voir Joram fils d’Achab à Jizréhel, parce qu’il était malade.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Alors Elisée le Prophète appela un d’entre les fils des Prophètes, et lui dit: Trousse tes reins; et prends cette fiole d’huile en ta main, et t’en va à Ramoth de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Quand tu y seras entré, regarde où sera Jéhu fils de Josaphat, fils de Nimsi, et y entre, et l’ayant fait lever d’entre ses frères, tu le feras entrer dans quelque chambre secrète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Puis tu prendras la fiole d’huile, tu la verseras sur sa tête, et tu diras: Ainsi a dit l’Eternel: Je t’ai oint pour être Roi sur Israël. Après quoi tu ouvriras la porte, tu t’enfuiras, et tu ne t’arrêteras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Ainsi ce jeune homme, qui était le serviteur du Prophète, s’en alla à Ramoth de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Et quand il y fut entré, voici, les capitaines de l’armée étaient là assis; et il dit: Capitaine, j’ai à parler à toi. Et Jéhu répondit: A qui de nous tous parles-tu? Et il dit: A toi, Capitaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Alors Jéhu se leva, et entra dans la maison; et le jeune homme lui versa l’huile sur la tête, et lui dit: Ainsi a dit l’Eternel le Dieu d’Israël: Je t’ai oint pour être Roi sur le peuple de l’Eternel; c’est-à-dire sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Et tu frapperas la maison d’Achab ton Seigneur; car je ferai vengeance du sang de mes serviteurs les Prophètes, et du sang de tous les serviteurs de l’Eternel, en le redemandant de la main d’Izebel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Et toute la maison d’Achab périra, et je retrancherai à Achab depuis l’homme jusqu’à un chien, tant ce qui est serré que ce qui est délaissé en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Et je mettrai la maison d’Achab au même état que la maison de Jéroboam fils de Nébat, et la maison de Bahasa, fils d’Ahija.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Les chiens aussi mangeront Izebel au champ de Jizréhel, et il n’y aura personne qui l’ensevelisse; après quoi il ouvrit la porte, et s’enfuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Alors Jéhu sortit vers les serviteurs de son maître, et on lui dit: Tout va-t-il bien? Pourquoi cet insensé est-il venu vers toi? Et il leur répondit: Vous connaissez l’homme, et ce qu’il sait dire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Mais ils dirent: Ce n’est pas cela; déclare nous-le maintenant. Et il répondit: Il m’a dit telle et telle chose; il m’a dit: Ainsi a dit l’Eternel, je t’ai oint pour être Roi sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Alors ils se hâtèrent, et prirent chacun leurs vêtements, et les mirent sous lui au plus haut des degrés, et sonnèrent de la trompette, et dirent: Jéhu a été fait Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Ainsi Jéhu fils de Josaphat, fils de Nimsi se ligua contre Joram. Or Joram avait muni Ramoth de Galaad, lui et tout Israël, de peur d’Hazaël Roi de Syrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Et le Roi Joram s’en était retourné pour se faire panser à Jizréhel des plaies que les Syriens lui avaient faites, quand il combattit contre Hazaël Roi de Syrie. Et Jéhu dit: Si vous le trouvez bon, empêchons que personne ne sorte ni n’échappe de la ville pour aller porter cette nouvelle à Jizréhel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Alors Jéhu monta à cheval, et s’en alla à Jizréhel, car Joram était là malade; et Achazia Roi de Juda y était descendu pour visiter Joram.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Or il y avait une sentinelle sur une tour à Jizréhel, qui voyant venir la troupe de Jéhu dit: Je vois une troupe de gens. Et Joram dit: Prends un homme de cheval, et l’envoie au-devant d’eux, et qu’il dise: Y a-t-il paix?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Et l’homme de cheval s’en alla au-devant de lui, et dit: Ainsi dit le Roi: Y a-t-il paix? Et Jéhu répondit: Qu’as-tu à faire de paix? Mets-toi derrière moi; et la sentinelle le rapporta, en disant: Le messager est venu jusqu’à eux, et il ne retourne point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Et il envoya un autre homme de cheval, qui vint à eux, et dit: Ainsi a dit le Roi: Y a-t-il paix? Et Jéhu répondit: Qu’as-tu à faire de paix? Mets-toi derrière moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Et la sentinelle le rapporta, et dit: Il est venu jusqu’à eux, et il ne retourne point; mais la démarche est comme la démarche de Jéhu fils de Nimsi; car il marche avec furie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Alors Joram dit: Qu’on attelle; et on attela son chariot. Ainsi Joram Roi d’Israël sortit avec Achazia Roi de Juda, chacun dans son chariot, et ils allèrent pour rencontrer Jéhu, et ils le trouvèrent dans le champ de Naboth Jizréhélite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Et dès que Joram eut vu Jéhu, il dit: N’y a-t-il pas paix, Jéhu? Et Jéhu répondit: Quelle paix, tandis que les paillardises de ta mère Izebel, et ses enchantements seront en si grand nombre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Alors Joram tourna sa main, et s’enfuit; et dit à Achazia: Achazia, nous sommes trompés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Et Jéhu empoigna l’arc à pleine main, et frappa Joram entre ses épaules, de sorte que la flèche sortait au travers de son cœur, et il tomba sur ses genoux dans son chariot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Et Jéhu dit à Bidkar son capitaine: Prends -le, et le jette en quelque endroit du champ de Naboth Jizréhélite; car souviens-toi que quand nous étions à cheval moi et toi, l’un près de l’autre, à la suite d’Achab son père, l’Eternel prononça cette charge contre lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Si je ne vis hier au soir le sang de Naboth, et le sang de ses fils, dit l’Eternel, et si je ne te le rends dans ce champ-ci, dit l’Eternel; c’est pourquoi prends -le maintenant et le jette dans ce champ, suivant la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Or Achazia Roi de Juda ayant vu cela, s’était enfui par le chemin de la maison du jardin; mais Jéhu l’avait poursuivi, et avait dit: Frappez aussi celui-ci sur le chariot. Ce fut dans la montée de Gur qui est auprès de Jibleham; puis il s’enfuit à Meguiddo, et mourut là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Et ses serviteurs l’emmenèrent sur un chariot à Jérusalem, et l’ensevelirent dans son sépulcre avec ses pères, en la Cité de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Or l’onzième année de Joram fils d’Achab, Achazia avait commencé à régner sur Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Et Jéhu vint à Jizréhel, et Izebel ayant appris que Jéhu venait, farda son visage, orna sa tête, et elle regardait par la fenêtre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Et comme Jéhu entrait dans la porte, elle dit: En a-t-il bien pris à Zimri qui tua son Seigneur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Et il leva sa tête vers la fenêtre, et dit: Qui est ici de mes gens? Qui? Alors deux ou trois des Eunuques regardèrent vers lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Et il leur dit: Jetez-la en bas. Et ils la jetèrent, de sorte qu’il rejaillit de son sang contre la muraille, et contre les chevaux, et il la foula aux pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Et étant entré, il mangea, et but; puis il dit: Allez voir maintenant cette maudite-là, et l’ensevelissez, car elle est fille de Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Ils s’en allèrent donc pour l’ensevelir; mais ils n’y trouvèrent rien que le crâne, et les pieds, et les paumes des mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Et étant retournés ils le lui rapportèrent; et il dit: C’est la parole de l’Eternel laquelle il avait proférée par le moyen de son serviteur Elie Tisbite, en disant: Dans le champ de Jizréhel les chiens mangeront la chair d’Izebel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'Et la charogne d’Izebel sera comme du fumier sur le dessus du champ dans le champ de Jizréhel; de sorte qu’on ne pourra point dire: C’est ici Izebel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Or Achab avait soixante et dix fils à Samarie. Et Jéhu écrivit des Lettres et les envoya à Samarie aux principaux de Jizréhel, aux Anciens, et aux nourriciers d’Achab, leur mandant en ces termes:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Aussitôt que ces Lettres vous seront parvenues, à vous, qui avez avec vous les fils de votre maître, les chariots, les chevaux, la ville forte, et les armes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'Regardez qui est le plus considérable et le plus agréable d’entre les fils de votre maître, et mettez-le sur le trône de son père, et combattez pour la maison de votre maître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Et ils eurent une très-grande peur, et dirent: Voilà, deux Rois n’ont point pu tenir contre lui, comment donc pourrions-nous nous soutenir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Ceux-là donc qui avaient la charge de la maison, et ceux qui étaient commis sur la ville, et les Anciens, et les nourriciers mandèrent à Jéhu, en disant: Nous sommes tes serviteurs, nous ferons tout ce que tu nous diras; nous ne ferons personne Roi, fais ce qui te semblera bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Et il leur écrivit des Lettres pour la seconde fois, en ces termes: Si vous êtes à moi, et si vous obéissez à ma voix, prenez les têtes des fils de votre maître, et venez vers moi demain à cette heure-ci à Jizréhel. Or les fils du Roi, qui étaient soixante et dix-hommes, étaient avec les plus grands de la ville qui les nourrissaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Aussitôt donc que ces Lettres leur furent parvenues, ils prirent les fils du Roi, et mirent à mort soixante et dix hommes, et ayant mis leurs têtes dans des paniers, ils les lui envoyèrent à Jizréhel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Et un messager vint qui le lui rapporta, et dit: Ils ont apporté les têtes des fils du Roi. Et il répondit: Mettez-les en deux monceaux à l’entrée de la porte, jusqu’au matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Et il sortit au matin, et s’étant arrêté, il dit à tout le peuple: Vous êtes justes; voici j’ai fait une ligue contre mon Seigneur, et je l’ai tué; et qui est-ce qui a frappé tous ceux-ci?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Sachez maintenant qu’il ne tombera rien en terre de la parole de l’Eternel, laquelle l’Eternel a prononcée contre la maison d’Achab; et que l’Eternel a fait ce dont il avait parlé par le moyen de son serviteur Elie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Jéhu tua aussi tous ceux qui étaient demeurés de reste de la maison d’Achab à Jizréhel, et tous ceux qu’il avait avancés et ses familiers amis, et ses principaux officiers, en sorte qu’il ne lui en laissa pas un de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Puis il se leva, et partit, et alla à Samarie; et comme il fut près d’une cabane de bergers sur le chemin,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Il trouva les frères d’Achazia Roi de Juda, et il leur dit: Qui êtes-vous? Et ils répondirent: Nous sommes les frères d’Achazia, et nous sommes descendus pour saluer les fils du Roi, et les fils de la reine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Et il dit: Empoignez-les vifs. Et ils les empoignèrent tous vifs, et les mirent à mort, savoir quarante-deux hommes, auprès du puits de la cabane des bergers, et on n’en laissa pas un de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Et Jéhu étant parti de là, trouva Jonadab fils de Réchab, qui venait au- devant de lui, lequel il salua, et lui dit: Ton coeur est-il aussi droit envers moi que mon coeur l’est à ton égard? Et Jonadab répondit: Il l’est; oui il l’est, donne-moi ta main; et il lui donna sa main, et le fit monter avec lui dans le chariot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Puis il dit: Viens avec moi, et tu verras le zèle que j’ai pour l’Eternel. Ainsi on le mena dans son chariot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Et quand Jéhu fut venu à Samarie, il tua tous ceux qui étaient demeurés de reste de la maison d’Achab à Samarie, jusqu’à ce qu’il eût tout exterminé, selon la parole que l’Eternel avait dite à Elie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Puis Jéhu assembla tout le peuple, et leur dit: Achab n’a servi qu’un peu Bahal; mais Jéhu le servira beaucoup.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Maintenant donc appelez-moi tous les Prophètes de Bahal, tous ses serviteurs, et tous ses Sacrificateurs; qu’il n’y en manque pas un, car j’ai à faire un grand sacrifice à Bahal. Quiconque ne s’y trouvera pas il ne vivra point. Or Jéhu faisait cela par finesse, pour faire périr les serviteurs de Bahal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Et Jéhu dit: Sanctifiez une fête solennelle à Bahal; et ils la publièrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Et Jéhu envoya par tout Israël, et tous les serviteurs de Bahal vinrent; il n’y en eut pas un qui n’y vînt; et ils entrèrent dans la maison de Bahal, et la maison de Bahal fut remplie depuis un bout jusqu’à l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Alors il dit à celui qui avait la charge du revestiaire: Tires-en des vêtements pour tous les serviteurs de Bahal; et il leur en tira des vêtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Et Jéhu et Jonadab fils de Réchab entrèrent dans la maison de Bahal, et Jéhu dit aux serviteurs de Bahal: Cherchez diligemment, et regardez que par hasard il n’y ait ici entre vous quelqu’un des serviteurs de l’Eternel; et prenez garde qu’il n’y ait que les seuls serviteurs de Bahal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Ils entrèrent donc pour faire des sacrifices et des holocaustes. Or Jéhu avait fait mettre par dehors quatre-vingts hommes, et leur avait dit: S’il y a quelqu’un de ces hommes que je m’en vais mettre entre vos mains, qui en échappe, la vie de chacun de vous répondra pour la vie de cet homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Et il arriva que dès qu’on eut achevé de faire l’holocauste, Jéhu dit aux archers et aux capitaines: Entrez, tuez-les, et que nul n’échappe. Les archers donc et les capitaines les passèrent au fil de l’épée, et les jetèrent là, puis ils s’en allèrent jusqu’à la ville de la maison de Bahal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'Et ils tirèrent dehors les statues de la maison de Bahal, et les brûlèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Et ils démolirent la statue de Bahal. Ils démolirent aussi la maison de Bahal, et la firent servir de retraits, jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Ainsi Jéhu extermina Bahal d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Toutefois Jéhu ne se détourna point des péchés de Jéroboam fils de Nébat, par lesquels il avait fait pécher Israël, savoir des veaux d’or qui étaient à Bethel, et à Dan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Et l’Eternel dit à Jéhu: Parce que tu as fort bien exécuté ce qui était droit devant moi, et que tu as fait à la maison d’Achab tout ce que j’avais en mon coeur, tes fils seront assis sur le trône d’Israël jusqu’à la quatrième génération.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Mais Jéhu ne prit point garde à marcher de tout son coeur dans la loi de l’Eternel le Dieu d’Israël, et il ne se détourna point des péchés de Jéroboam par lesquels il avait fait pécher Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'En ce temps-là l’Eternel commença à retrancher quelque partie du Royaume d’Israël, car Hazaël battit les Israëlites dans toutes les frontières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'Depuis le Jourdain jusqu’au soleil levant savoir dans tout le pays de Galaad, des Gadites, des Rubénites, et de ceux de Manassé, depuis Haroher, qui est sur le torrent d’Arnon, jusqu’en Galaad et en Basan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Le reste des faits de Jéhu, tout ce, dis-je, qu’il a fait, et tous ses exploits, ne sont-ils pas écrits au Livre des Chroniques des Rois d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Et Jéhu s’endormit avec ses pères, et fut enseveli à Samarie; et Joachaz son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Or les jours que Jéhu régna sur Israël à Samarie furent vingt-huit ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Or Hathalia mère d’Achazia, ayant vu que son fils était mort, s’éleva, et extermina toute la race Royale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Mais Jéhosébah fille du Roi Joram, soeur d’Achazia prit Joas fils d’Achazia, et le déroba d’entre les fils du Roi qu’on faisait mourir, et le mit avec sa nourrice dans la chambre aux lits; et on le cacha de devant Hathalia, de sorte qu’on ne le fit point mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Et il fut caché avec elle dans la maison de l’Eternel, l’espace de six ans; cependant Hathalia régnait sur le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Et la septième année Jéhojadah envoya, et prit des centeniers, des capitaines, et des archers, et les fit entrer vers soi dans la maison de l’Eternel, et traita alliance avec eux, et les fit jurer dans la maison de l’Eternel, et leur montra le fils du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Puis il leur commanda, en disant: C’est ici ce que vous ferez: La troisième partie d’entre vous qui entrez en semaine, fera la garde de la maison du Roi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'Et la troisième partie sera à la porte de Sur; et la troisième partie sera à la porte qui est derrière les archers; ainsi vous ferez le guet pour garder le Temple, afin que personne n’y entre par force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Et les deux compagnies d’entre vous qui sortez de semaine, feront le guet pour garder la maison de l’Eternel, auprès du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Et vous environnerez le Roi tout autour, chacun ayant ses armes en sa main, et si quelqu’un entre dans les rangs, qu’il soit mis à mort; vous serez avec le Roi quand il sortira, et quand il entrera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Les centeniers donc firent comme Jéhojadah le Sacrificateur avait commandé; ils prirent chacun ses gens, tant ceux qui entraient en semaine, que ceux qui sortaient de semaine; et ils vinrent vers le Sacrificateur Jéhojadah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Et le sacrificateur donna aux centeniers des hallebardes et des boucliers qui avaient été au Roi David, et qui étaient dans la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Et les archers se tinrent rangés auprès du Roi tout alentour, ayant chacun les armes à la main, depuis le côté droit du Temple jusqu’au côté gauche, tant pour l’autel que pour le Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Et Jéhojadah fit amener le fils du Roi, et mit sur lui la couronne, et le Témoignage, et ils l’établirent Roi, et l’oignirent, et frappant des mains, ils dirent: Vive le Roi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Et Hathalia entendant le bruit des archers, et du peuple, entra vers le peuple dans la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Et elle regarda, et voilà, le Roi était près de la colonne, selon la coutume des Rois, et les capitaines et les trompettes étaient près du Roi, et tout le peuple du pays éclatait de joie, et on sonnait des trompettes. Alors Hathalia déchira ses vêtements, et cria: Conjuration! conjuration!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Et le Sacrificateur Jéhojadah commanda aux centeniers qui avaient la charge de l’armée, et leur dit: Menez-la hors des rangs, et que celui qui la suivra soit mis à mort par l’épée; car le Sacrificateur avait dit: Qu’on ne la mette point à mort dans la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Ils lui firent donc place; et elle revint dans la maison du Roi par le chemin de l’entrée des chevaux, et elle fut tuée là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Et Jéhojadah traita alliance entre l’Eternel, le Roi, et le peuple, qu’ils seraient pour peuple à l’Eternel; il traita de même alliance entre le Roi et le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Alors tout le peuple du pays entra dans la maison de Bahal, la démolirent, avec ses autels, et ils brisèrent entièrement ses images; ils tuèrent aussi Mattam Sacrificateur de Bahal, devant les autels; et le Sacrificateur ordonna des gardes en la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Et il prit les centeniers, les capitaines, les archers, et tout le peuple du pays, et ils firent descendre le Roi de la maison de l’Eternel, et ils entrèrent dans la maison du Roi par le chemin de la porte des archers, et Joas s’assit sur le trône des Rois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Et tout le peuple du pays fut dans la joie, et la ville fut en repos; quoiqu’on eût mis à mort Hathalia par l’épée dans la maison du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Joas était âgé de sept ans quand il commença à régner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'La septième année de Jéhu, Joas commença à régner, et il régna quarante ans à Jérusalem; sa mère avait nom Tsibja, et elle était de Béer-sebah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Joas fit ce qui est droit devant l’Eternel pendant tout le temps que Jéhojadah le Sacrificateur l’enseigna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Toutefois les hauts lieux ne furent point ôtés, le peuple sacrifiait encore et faisait des encensements dans les hauts lieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Et Joas dit aux Sacrificateurs: Quant à tout l’argent consacré que l’on apporte dans la maison de l’Eternel, soit l’argent de tout homme qui passe par le dénombrement, soit l’argent des personnes selon l’estimation qu’en fait le Sacrificateur, et tout l’argent que chacun apporte volontairement dans la maison de l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Que les Sacrificateurs le prennent par-devers eux, chacun de celui qu’il connaît, et qu’ils en réparent ce qui est à réparer du Temple, partout où l’on trouvera quelque chose à réparer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Mais il arriva que la vingt et troisième année du Roi Joas, les Sacrificateurs n’avaient point encore réparé ce qui était à réparer au Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Et le Roi Joas appela le Sacrificateur Jéhojadah, et les autres Sacrificateurs, et il leur dit: Pourquoi n’avez-vous pas réparé ce qui était à réparer au Temple? or maintenant ne prenez plus d’argent de ceux que vous connaissez, mais laissez-le pour ce qui est à réparer au Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Et les Sacrificateurs s’accordèrent à ne prendre plus l’argent du peuple, et à ne réparer point ce qui était à réparer au Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'C’est pourquoi le Sacrificateur Jéhojadah prit un coffre, et fit un trou à son couvercle, et le mit auprès de l’autel à main droite, à l’endroit par où l’on entrait dans la maison de l’Eternel; et les Sacrificateurs qui gardaient les vaisseaux, mettaient là tout l’argent qu’on apportait à la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Et dès qu’ils voyaient qu’il y avait beaucoup d’argent au coffre, le Secrétaire du Roi montait avec le grand Sacrificateur, et ils mettaient dans des sacs l’argent qui se trouvait dans la maison de l’Eternel, puis ils le comptaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Et ils délivraient cet argent bien compté entre les mains de ceux qui avaient la charge de l’oeuvre, et qui étaient commis sur la maison de l’Eternel, lesquels le distribuaient aux charpentiers et architectes qui refaisaient la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'Et aux maçons, et aux tailleurs de pierres, pour acheter du bois et des pierres de taille, afin de réparer ce qui était à réparer dans la maison de l’Eternel, et pour acheter tout ce qu’il fallait employer pour la réparation du Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Au reste, de cet argent qu’on apportait dans la maison de l’Eternel, on n’en faisait point de coupes d’argent, pour la maison de l’Eternel, ni de serpes, ni de bassins, ni de trompettes, ni aucun autre vaisseau d’or, ou vaisseau d’argent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Mais on le distribuait à ceux qui avaient la charge de l’oeuvre, lesquels en réparaient la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Et on ne faisait point rendre compte à ceux entre les mains de qui on avait délivré cet argent pour le distribuer à ceux qui faisaient le travail; car ils le faisaient fidèlement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'L’argent des sacrifices pour le délit, et l’argent des sacrifices pour les péchés n’était point apporté dans la maison de l’Eternel; car il était aux Sacrificateurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Alors Hazaël Roi de Syrie monta, et fit la guerre contre Gath, et la prit; puis Hazaël tourna visage pour monter contre Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Mais Joas Roi de Juda prit tout ce qui était consacré, que Josaphat, Joram, et Achazia ses pères, Rois de Juda, avaient consacré, et tout ce que lui-même avait consacré, et tout l’or qui se trouva dans les trésors de la maison de l’Eternel et de la maison du Roi, et l’envoya à Hazaël Roi de Syrie, qui se retira de devant Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Le reste des faits de Joas, tout ce, dis-je, qu’il a fait, n’est-il pas écrit au Livre des Chroniques des Rois de Juda?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Or ses serviteurs se soulevèrent, et se liguèrent, et frappèrent Joas dans la maison de Millo, qui est à la descente de Silla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Jozacar fils de Simhath, et Jozabad fils de Somer ses serviteurs le frappèrent, et il mourut; et on l’ensevelit avec ses pères dans la Cité de David; et Amatsia son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'La vingt et troisième année de Joas fils d’Achazia Roi de Juda, Joachaz fils de Jéhu commença à régner sur Israël à Samarie, et il régna dix-sept ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Et il fit ce qui déplaît à l’Eternel; car il suivit les péchés de Jéroboam fils de Nébat, par lesquels il avait fait pécher Israël, et il ne se détourna point d’aucun d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Et la colère de l’Eternel s’embrasa contre Israël, qui les livra entre les mains de Hazaël Roi de Syrie, et entre les mains de Ben-hadad fils de Hazaël durant tout ce temps-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Mais Joachaz supplia l’Eternel; et l’Eternel l’exauça; parce qu’il vit l’oppression d’Israël, car le Roi de Syrie les opprimait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'L’Eternel donc donna un libérateur à Israël, et ils sortirent de dessous la puissance des Syriens; ainsi les enfants d’Israël habitèrent dans leurs tentes comme auparavant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Toutefois ils ne se détournèrent point des péchés de la maison de Jéroboam, par lesquels il avait fait pécher Israël; mais ils y marchèrent, et même le bocage demeura debout à Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Quoique Dieu n’eût laissé d’entre le peuple à Joachaz que cinquante hommes de cheval, dix chariots, et dix mille hommes de pied, et que le Roi de Syrie les eût détruits, et les eût rendus menus comme la poudre qu’on foule dans l’aire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Le reste des faits de Joachaz, tout ce, dis-je, qu’il a fait, et ses exploits ne sont-ils pas écrits au Livre des Chroniques des Rois d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Ainsi Joachaz s’endormit avec ses pères, et on l’ensevelit à Samarie; et Joas son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'La trente-septième année de Joas Roi de Juda, Joas fils de Joachaz commença à régner sur Israël à Samarie, et il régna seize ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Et il fit ce qui déplaît à l’Eternel; il ne se détourna point d’aucun des péchés de Jéroboam fils de Nébat, par lesquels il avait fait pécher Israël, il y marcha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Le reste des faits de Joas, tout ce, dis-je, qu’il a fait, et la valeur avec laquelle il combattit contre Amatsia Roi de Juda, tout cela n’est-il pas écrit au Livre des Chroniques des Rois d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Et Joas s’endormit avec ses pères, et Jéroboam s’assit sur son trône; et Joas fut enseveli dans Samarie avec les Rois d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Or Elisée était malade d’une maladie dont il mourut; et Joas le Roi d’Israël était descendu, et avait pleuré sur son visage, en disant: Mon père! mon père! chariot d’Israël, et sa cavalerie!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Et Elisée lui dit: Prends un arc et des flèches; Il prit donc en sa main un arc et des flèches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Puis il dit au Roi d’Israël: Mets ta main sur l’arc; et quand il y eut mis sa main, Elisée mit ses mains sur celles du Roi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'Et lui dit: Ouvre la fenêtre qui regarde vers l’Orient; et quand il l’eut ouverte, Elisée lui dit: Tire. Après qu’il eut tiré, il lui dit: C’est la flèche de la délivrance de par l’Eternel, la flèche, dis-je, de la délivrance contre les Syriens; tu frapperas donc les Syriens en Aphek, jusqu’à les consumer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Il lui dit encore: Prends des flèches; et quand il les eut prises, il dit au Roi d’Israël: Frappe contre terre; et le Roi frappa trois fois, puis il s’arrêta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Et l’homme de Dieu se mit en fort grande colère contre lui, et lui dit: Il fallait frapper cinq ou six fois; et tu eusses frappé les Syriens jusqu’à les consumer; mais maintenant tu ne les frapperas que trois fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Et Elisée mourut, et on l’ensevelit. Or l’année suivante quelques troupes de Moabites entrèrent dans le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Et il arriva que comme on ensevelissait un homme, voici on vit venir une troupe de soldats, et on jeta cet homme-là dans le sépulcre d’Elisée; et cet homme étant roulé là dedans, et ayant touché les os d’Elisée, revint en vie, et se leva sur ses pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Or durant tout le temps de Joachaz, Hazaël Roi de Syrie avait opprimé les Israëlites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Mais l’Eternel eut compassion d’eux, et leur fit miséricorde, et se retourna vers eux pour l’amour de son alliance avec Abraham, Isaac, et Jacob, de sorte qu’il ne voulut point les exterminer, et il ne les rejeta point de devant soi, jusqu’à maintenant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Puis Hazaël Roi de Syrie mourut, et Ben-hadad son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Et Joas fils de Joachaz retira d’entre les mains de Ben-hadad fils d’Hazaël les villes qu’ Hazaël avait prises en guerre à Joachaz son père; Joas le battit trois fois, et recouvra les villes d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'La seconde année de Joas fils de Joachaz Roi d’Israël, Amatsia, fils de Joas Roi de Juda commença à régner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Il était âgé de vingt-cinq ans quand il commença à régner, et il régna vingt- neuf ans à Jérusalem; sa mère avait nom Jéhohaddan, et était de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Et il fit ce qui est droit devant l’Eternel, non pas toutefois comme David son père; il fit comme Joas son père avait fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'De sorte qu’il n’y eut que les hauts lieux qui ne furent point ôtés; le peuple sacrifiait encore et faisait des encensements dans les hauts lieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Et il arriva que dès que le Royaume fut affermi entre ses mains, il fit mourir ses serviteurs qui avaient tué le Roi son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Mais il ne fit point mourir les enfants de ceux qui l’avaient tué; suivant ce qui est écrit au Livre de la Loi de Moïse, dans lequel l’Eternel a commandé, en disant: On ne fera point mourir les pères pour les enfants, on ne fera pas non plus mourir les enfants pour les pères; mais on fera mourir chacun pour son péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Il frappa dix mille hommes d’Edom en la vallée du sel, et prit Sélah par guerre, et la nomma Jokthéel, qui est le nom qu’elle a eu jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Alors Amatsia envoya des messagers vers Joas le fils de Joachaz, fils de Jéhu, Roi d’Israël, pour lui dire: Viens, et que nous nous voyions l’un l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Et Joas Roi d’Israël envoya dire à Amatsia Roi de Juda: L’épine qui est au Liban a envoyé dire au cèdre qui est au Liban: Donne ta fille pour femme à mon fils, mais les bêtes sauvages qui sont au Liban, ont passé, et ont foulé l’épine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Parce que tu as rudement frappé Edom, ton coeur s’est élevé. Contente-toi de ta gloire, et tiens-toi dans ta maison; pourquoi exciterais-tu le mal par lequel tu tomberas, toi et Juda avec toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Mais Amatsia ne voulut point y acquiescer; et Joas Roi d’Israël monta, et ils se virent l’un l’autre, lui et Amatsia Roi de Juda, en Bethsémes, qui est de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Et Juda fut défait par Israël, et ils s’enfuirent chacun dans leurs tentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Et Joas Roi d’Israël prit Amatsia Roi de Juda, fils de Joas, fils d’Achazia, en Bethsémes, puis il vint à Jérusalem et fit une brèche de quatre cents coudées à la muraille de Jérusalem, depuis la porte d’Ephraïm, jusqu’à la porte du coin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Et ayant pris tout l’or et tout l’argent, et tous les vaisseaux qui furent trouvés dans la maison de l’Eternel, et dans les trésors de la maison Royale, et des gens pour otages, il s’en retourna à Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Le reste des faits de Joas, et sa valeur, et comment il combattit contre Amatsia, tout cela n’est-il pas écrit au Livre des Chroniques des Rois d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Et Joas s’endormit avec ses pères, et fut enseveli à Samarie avec les Rois d’Israël; et Jéroboam son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Et Amatsia fils de Joas Roi de Juda vécut quinze ans après la mort de Joas fils de Joachaz Roi d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Le reste des faits d’Amatsia n’est-il pas écrit au Livre des Chroniques des Rois de Juda?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Or on fit une conspiration contre lui à Jérusalem, et il s’enfuit à Lakis; mais on envoya après lui à Lakis, et on le tua là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Et on l’apporta sur des chevaux, et il fut enseveli à Jérusalem avec ses pères, dans la Cité de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Alors tout le peuple de Juda prit Hazaria âgé de seize ans, et ils l’établirent Roi en la place d’Amatsia son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Il bâtit Elath, l’ayant remise en la puissance de Juda, après que le Roi fut endormi avec ses pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'La quinzième année d’Amatsia fils de Joas Roi de Juda, Jéroboam, fils de Joas, commença à régner sur Israël à Samarie, et il régna l’espace de quarante et un ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Et il fit ce qui déplaît à l’Eternel, et ne se détourna point d’aucun des péchés de Jéroboam fils de Nébat, par lesquels il avait fait pécher Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Il rétablit les bornes d’Israël depuis l’entrée de Hamath, jusqu’à la mer de la campagne, selon la parole de l’Eternel le Dieu d’Israël, qu’il avait proférée par le moyen de son serviteur Jonas fils d’Amittaï, Prophète, qui était de Gathhépher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Parce que l’Eternel vit que l’affliction d’Israël était fort amère, et qu’il n’y avait ni de ce qui est serré, ni de ce qui est délaissé, et qu’il n’y avait personne qui aidât Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Et que l’Eternel n’avait point parlé d’effacer le nom d’Israël de dessous les cieux, à cause de cela il les délivra par les mains de Jéroboam fils de Joas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Le reste des faits de Jéroboam, tout ce, dis-je, qu’il a fait, et la valeur avec laquelle il combattit, et comment il reconquit Damas et Hamath de Juda en Israël, n’est-il pas écrit au Livre des Chroniques des Rois d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Puis Jéroboam s’endormit avec ses pères, les Rois d’Israël, et Zacharie son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'La vingt-septième année de Jéroboam Roi d’Israël, Hazaria fils d’Amatsia Roi de Juda régnait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Il était âgé de seize ans quand il commença à régner, et il régna cinquante- deux ans à Jérusalem; sa mère avait nom Jécolia, et était de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Il fit ce qui est droit devant l’Eternel, comme avait fait Amatsia son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Tellement qu’il n’y eut que les hauts lieux qui ne furent point ôtés; le peuple sacrifiait encore et faisait des encensements sur les hauts lieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Or l’Eternel frappa le Roi, qui fut lépreux jusqu’au jour qu’il mourut, et il demeura dans une maison séquestrée; et Jotham fils du Roi avait la charge de la maison, jugeant le peuple du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Le reste des faits de Hazaria, tout ce, dis-je, qu’il a fait, n’est-il pas écrit au Livre des Chroniques des Rois de Juda?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Et Hazaria s’endormit avec ses pères, et fut enseveli avec ses pères en la Cité de David, et Jotham son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'La trente-huitième année de Hazaria Roi de Juda, Zacharie fils de Jéroboam commença à régner sur Israël à Samarie, et il régna six mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Et il fit ce gui déplaît à l’Eternel, comme avaient fait ses pères; il ne se détourna point des péchés de Jéroboam fils de Nébat, par lesquels il avait fait pécher Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Or Sallum fils de Jabés, fit une conspiration contre lui, et le frappa en la présence du peuple, et le tua, et il régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Quant au reste des faits de Zacharie, voilà, ils sont écrits au Livre des Chroniques des Rois d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'C’est là la parole de l’Eternel laquelle il avait prononcée à Jéhu, en disant: Tes fils seront assis sur le trône d’Israël jusqu’à la quatrième génération; et il arriva ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sallum fils de Jabés commença à régner la trente-neuvième année d’Hozias Roi de Juda, et il ne régna que l’espace d’un mois entier à Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Car Ménahem fils de Gadi, qui était de Tirtsa, monta, et entra dans Samarie, et frappa Sallum fils de Jabés à Samarie, et le tua, et il régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Quant au reste des faits de Sallum, et quant à la conspiration qu’il fit, voilà, ces choses sont écrites au Livre des Chroniques des Rois d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Et Ménahem battit Tiphsah, et tous ceux qui étaient dedans, et dans sa contrée, depuis Tirtsa, parce qu’elle ne lui avait point ouvert les portes, et les tua; et il fendit toutes les femmes grosses qui s’y trouvèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'La trente-neuvième année de Hazaria Roi de Juda, Ménahem fils de Gadi, commença à régner sur Israël, il régna dix ans en Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Et il fit ce qui déplaît à l’Eternel; il ne se détourna point des péchés de Jéroboam fils de Nébat, par lesquels il avait fait pécher Israël, durant tout son temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Alors Pul, Roi des Assyriens, vint contre le pays; et Ménahem donna mille talents d’argent à Pul, afin qu’il lui aidât à affermir son Royaume entre ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Et Ménahem tira cet argent d’Israël, de tous ceux qui étaient puissants en biens, pour le donner au Roi des Assyriens, de chacun cinquante sicles d’argent; ainsi le Roi des Assyriens s’en retourna, et ne s’arrêta point au pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Le reste des faits de Ménahem, tout ce, dis-je, qu’il a fait, n’est-il pas écrit au Livre des Chroniques des Rois d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Et Ménahem s’endormit avec ses pères, et Pékachia son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'La cinquantième année d’Hazaria Roi de Juda, Pékachia fils de Ménahem commença à régner sur Israël à Samarie, et il régna deux ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Et il fit ce qui déplaît à l’Eternel, et ne se détourna point des péchés de Jéroboam fils de Nébat, par lesquels il avait fait pécher Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Et Pékach fils de Rémalia son capitaine fit une conspiration contre lui, et le frappa à Samarie, au palais de la maison Royale, avec Argob et Arié, ayant avec soi cinquante hommes des enfants des Galaadites; ainsi il le tua, et il régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Le reste des actions de Pékachia, tout ce, dis-je, qu’il a fait, voilà, il est écrit au Livre des Chroniques des Rois d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'La cinquante et deuxième année d’Hazaria Roi de Juda, Pékach fils de Rémalia commença à régner sur Israël à Samarie, et il régna vingt ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Et il fit ce qui déplaît à l’Eternel, il ne se détourna point des péchés de Jéroboam fils de Nébat, par lesquels il avait fait pécher Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Aux jours de Pékach Roi d’Israël, Tiglath-piléser Roi des. Assyriens, vint, et prit Hijon, et Abel-bethmahaca, et Janoah, et Kédés, et Hatsor, et Galaad, et la Galilée, même tout le pays de Nephthali, et en transporta le peuple en Assyrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Or Hosée, fils d’Ela, fit une conspiration contre Pékach fils de Rémalia, et le frappa, et le tua, et il régna en sa place la vingtième année de Jotham fils de Hozias.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Le reste des faits de Pékach, tout ce, dis-je, qu’il a fait, voilà, il est écrit au Livre des Chroniques des Rois d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'La seconde année de Pékach fils de Rémalia Roi d’Israël, Jotham fils de Hozias, Roi de Juda commença à régner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Il était âgé de vingt et cinq ans quand il commença à régner; et il régna seize ans à Jérusalem; sa mère avait nom Jérusa, et était fille de Tsadok.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Il fit ce qui est droit devant l’Eternel; il fit comme Hozias son père avait fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'De sorte qu’il n’y eut que les hauts lieux qui ne furent point ôtés, le peuple sacrifiait encore et faisait des encensements dans les hauts lieux; ce fut lui qui bâtit la plus haute porte de la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Le reste des faits de Jotham, tout ce, dis-je, qu’il a fait, n’est-il pas écrit au Livre des Chroniques des Rois de Juda?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'En ces jours-là l’Eternel commença d’envoyer contre Juda Retsin Roi de Syrie et Pékach fils de Rémalia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Et Jotham s’endormit avec ses pères, et fut enseveli en la Cité de David son père, et Achaz son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'La dix-septième année de Pékach fils de Rémalia, Achaz fils de Jotham Roi de Juda, commença à régner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Achaz était âgé de vingt ans quand il commença à régner; et il régna seize ans à Jérusalem; et il ne fit point ce qui est droit devant l’Eternel son Dieu comme avait fait David son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Mais il suivit le train des Rois d’Israël, et même il fit passer son fils par le feu, selon les abominations des nations que l’Eternel avait chassées de devant les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Il sacrifiait aussi et faisait des encensements dans les hauts lieux, et sur les coteaux, et sous tout arbre verdoyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Alors Retsin Roi de Syrie, et Pékach fils de Rémalia Roi d’Israël, montèrent contre Jérusalem pour lui faire la guerre, et ils assiégèrent Achaz; mais ils n’en purent point venir à bout par les armes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'En ce temps-là Retsin Roi de Syrie, remit Elath en la puissance des Syriens, car il déposséda les Juifs d’Elath, et les Syriens entrèrent à Elath, et ils y ont demeuré jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Or Achaz avait envoyé des messagers à Tiglath-piléser Roi des Assyriens, pour lui dire: Je suis ton serviteur, et ton fils; monte et délivre-moi de la main du Roi des Syriens, et de la main du Roi d’Israël, qui s’élèvent contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Et Achaz avait pris l’argent et l’or qui s’était trouvé dans la maison de l’Eternel, et dans les trésors de la maison Royale, et il l’avait envoyé en don au Roi d’Assyrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Et le Roi d’Assyrie y acquiesça, et monta à Damas, et la prit, et en transporta le peuple à Kir, et fit mourir Retsin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Alors le Roi Achaz s’en alla au devant de Tiglath-piléser Roi d’Assyrie, à Damas; et le Roi Achaz ayant vu l’autel qui était à Damas, envoya à Urie le Sacrificateur la figure et le modèle de cet autel, selon toute la façon qu’il avait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Et Urie le Sacrificateur bâtit un autel, suivant tout ce que le Roi Achaz avait mandé de Damas; Urie le Sacrificateur le fit tout semblable, en attendant que le Roi Achaz fût revenu de Damas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Et quand le Roi Achaz fut revenu de Damas, et eut vu l’autel, il s’en approcha, et offrit sur cet autel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'Et fit fumer son holocauste et son sacrifice, et versa ses aspersions, et répandit le sang de ses sacrifices de prospérité sur cet autel-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Et quant à l’autel d’airain qui était devant l’Eternel, il le fit reculer de devant la maison, d’entre l’autel et la maison de l’Eternel, et le mit à côté de cet autre autel, vers le Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Et le Roi Achaz commanda à Urie le Sacrificateur, et lui dit: Fais fumer l’holocauste du matin, et l’oblation du soir, et l’holocauste du Roi avec son gâteau, et l’holocauste de tout le peuple du pays avec leurs gâteaux et leurs aspersions sur le grand autel, et répands tout le sang des holocaustes et tout le sang des sacrifices sur cet autel; mais l’autel d’airain sera pour moi, afin de m’y enquérir du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Et Urie le Sacrificateur fit comme le Roi Achaz lui avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Le Roi Achaz retrancha aussi les embattements des soubassements, et en ôta les cuviers qui étaient dessus, et fit ôter la mer de dessus les boeufs d’airain, qui étaient dessous, et la mit sur un pavé de pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Il ôta aussi de la maison de l’Eternel le couvert du Sabbat qu’on avait bâti au Temple, et l’entrée du Roi qui était en dehors, à cause du Roi des Assyriens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Le reste des faits d’Achaz, lesquels il a faits, n’est-il pas écrit au Livre des Chroniques des Rois de Juda?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Puis Achaz s’endormit avec ses pères, et fut enseveli avec eux en la Cité de David; et Ezéchias son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'La douzième année d’Achaz Roi de Juda, Hosée fils d’Ela commença à régner à Samarie sur Israël, et il régna neuf ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Et il fit ce qui déplaît à l’Eternel, non pas toutefois comme les Rois d’Israël qui avaient été avant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Salmanéser Roi des Assyriens monta contre lui, et Hosée lui fut asservi, et il lui envoyait des présents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Mais le Roi des Assyriens découvrit une conspiration en Hosée; car Hosée avait envoyé des messagers vers So, Roi d’Egypte, et il n’envoyait plus de présents tous les ans au Roi d’Assyrie; c’est pourquoi le Roi des Assyriens l’enferma, et le mit en prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Le Roi des Assyriens monta par tout le pays, et monta à Samarie, et l’assiégea pendant trois ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'La neuvième année d’Hosée, le Roi des Assyriens prit Samarie, et transporta les Israëlites en Assyrie, et les fit habiter à Chalach, et sur Chabor fleuve de Gozan, et dans les villes des Mèdes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Car il était arrivé que les enfants d’Israël avaient péché contre l’Eternel leur Dieu qui les avait fait monter hors du pays d’Egypte, de dessous la main de Pharaon Roi d’Egypte, et avaient révéré d’autres dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'Et ils avaient suivi le train des nations que l’Eternel avait chassées de devant les enfants d’Israël, et le train des Rois d’Israël qu’ils avaient établis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Et les enfants d’Israël avaient fait couvertement des choses qui n’étaient point droites devant l’Eternel leur Dieu; et s’étaient bâti des hauts lieux par toutes leurs villes, depuis la tour des gardes jusqu’aux villes fortes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'Ils s’étaient dressé des statues, et planté des bocages, sur toutes les hautes collines et sous tout arbre verdoyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'Ils avaient fait là des encensements dans tous les hauts lieux, à l’imitation des nations que l’Eternel avait chassées de devant eux; et ils avaient fait des choses méchantes pour irriter l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'Et ils avaient servi les dieux de fiente, au sujet desquels l’Eternel leur avait dit: Vous ne ferez point cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Et l’Eternel avait sommé Israël et Juda par le moyen de tous les Prophètes, ayant toute sorte de vision, en disant: Détournez-vous de toutes vos méchantes voies; retournez, et gardez mes commandements, et mes statuts, selon toute la Loi que j’ai commandée à vos pères, et que je vous ai envoyée par mes serviteurs les Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Mais ils n’avaient point écouté, et ils avaient roidi leur cou, comme leurs pères avaient roidi leur cou, lesquels n’avaient point cru à l’Eternel leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Et ils avaient dédaigné ses statuts, et son alliance, qu’il avait traitée avec leurs pères, et ses témoignages, par lesquels il les avait sommés, et avaient marché après la vanité, et étaient devenus vains, et avaient suivi les nations qui étaient autour d’eux, touchant lesquelles l’Eternel avait commandé qu’ils ne fissent point comme elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Et ayant abandonné tous les commandements de l’Eternel leur Dieu, ils s’étaient fait des simulacres de fonte, c’est-à-dire deux veaux, et avaient planté des bocages, et s’étaient prosternés devant toute l’armée des cieux, et avaient servi Bahal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Ils avaient fait aussi passer leurs fils, et leurs filles par le feu, et s’étaient adonnés aux divinations, et aux enchantements, et s’étaient vendus pour faire ce qui déplaît à l’Eternel afin de l’irriter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'C’est pourquoi l’Eternel fut fort irrité contre Israël, et il les rejeta, en sorte qu’il n’y eut que la seule Tribu de Juda, qui restât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Et même Juda ne garda point les commandements de l’Eternel son Dieu, mais ils marchèrent dans les ordonnances qu’Israël avait établies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'C’est pourquoi l’Eternel rejeta toute la race d’Israël, car il les affligea, et les livra entre les mains de ceux qui les pillaient, jusqu’à ce qu’il les eût rejetés de devant sa face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Parce qu’Israël s’était retranché de la maison de David, et avait établi Roi Jéroboam fils de Nébat, car Jéroboam avait débauché Israël, afin qu’il ne suivît plus l’Eternel, et leur avait fait commettre un grand péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'C’est pourquoi les enfants d’Israël marchèrent dans tous les péchés que Jéroboam avait faits, et ils ne s’en sont point retirés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'Jusqu’à ce que l’Eternel les a rejetés de devant soi, selon qu’il en avait parlé par le moyen de tous ses serviteurs les Prophètes; et Israël a été transporté de dessus la terre en Assyrie, jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Et le Roi des Assyriens fit venir des gens de Babel, et de Cuth, et de Hava, et de Hamath, et de Sépharvajim, et les fit habiter dans les villes de Samarie, en la place des enfants d’Israël; et ils possédèrent la Samarie, et ils habitèrent dans ses villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Or il arriva qu’au commencement qu’ils habitèrent là, ils ne révérèrent point l’Eternel, et l’Eternel envoya contr’eux des lions, qui les tuaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Et on dit au Roi des Assyriens: Les nations que tu as transportées et fait habiter dans les villes de Samarie, ne savent pas la manière de servir le Dieu du pays; c’est pourquoi il a envoyé contr’eux des lions, et voilà, ces lions les tuent, parce qu’ils ne savent pas la manière de servir le Dieu du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Alors le Roi des Assyriens commanda, en disant: Faites aller là quelqu’un des Sacrificateurs que vous en avez transportés; qu’on aille donc, et qu’on demeure là, et qu’on enseigne la manière de servir le Dieu du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Ainsi un des Sacrificateurs qu’on avait transportés de Samarie, vint et habita à Béthel, et il leur enseignait comment ils devaient révérer l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Mais chaque nation fit ses dieux, et ils les mirent dans les maisons des hauts lieux que les Samaritains avaient faits; chaque nation les mit dans ses villes où ils habitaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Car les gens de Babel firent Succoth-benoth; et les gens de Cuth firent Nergal; et les gens de Hamath firent Asima.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'Et les Haviens firent Nibchaz et Tartac; mais ceux de Sépharvajim brûlaient leurs enfants au feu à Adrammélec et Hanammélec, les dieux de Sépharvajim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Toutefois ils révéraient l’Eternel, et ils établirent pour Sacrificateurs des hauts lieux des derniers d’entr’eux, qui leur faisaient le service dans les maisons des hauts lieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Ainsi ils révéraient l’Eternel, et en même temps ils servaient leurs dieux à la manière des nations qu’on avait transportées hors de là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Et jusqu’à ce jour ils font selon leurs premières coutumes; ils ne révèrent point l’Eternel, et néanmoins ils ne font ni selon leurs statuts et selon leurs ordonnances, ni selon la Loi et le commandement que l’Eternel Dieu donna aux enfants de Jacob, lequel il nomma Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Avec lesquels l’Eternel avait traité alliance, et auxquels il avait commandé, en disant: Vous ne révérerez point d’autres dieux, et ne vous prosternerez point devant eux; vous ne les servirez point, et vous ne leur sacrifierez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Mais vous révérerez l’Eternel qui vous a fait monter hors du pays d’Egypte par une grande force, et avec un bras étendu; et vous vous prosternerez devant lui, et vous lui sacrifierez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Vous prendrez garde à faire toujours les statuts, les ordonnances, la Loi, et les commandements qu’il vous a écrits; et vous ne révérerez point d’autres dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Vous n’oublierez donc point l’alliance que j’ai traitée avec vous, et vous ne révérerez point d’autres dieux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Mais vous révérerez l’Eternel votre Dieu, et il vous délivrera de la main de tous vos ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Mais ils n’écoutèrent point, et ils firent selon leurs premières coutumes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Ainsi ces nations-là révéraient l’Eternel, et servaient en même temps leurs images; et leurs enfants, et les enfants de leurs enfants font jusqu’à ce jour comme leurs pères ont fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Or la troisième année d’Hosée fils d’Ela Roi d’Israël, Ezéchias fils d’Achaz Roi de Juda commença à régner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Il était âgé de vingt-cinq ans quand il commença à régner, et il régna vingt et neuf ans à Jérusalem; sa mère avait nom Abi, et était fille de Zacharie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Il fit ce gui est droit devant l’Eternel comme avait fait David son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Il ôta les hauts lieux, mit en pièces les statues, coupa les bocages, et il brisa le serpent d’airain que Moïse avait fait, parce que jusqu’à ce jour-là les enfants d’Israël lui faisaient des encensements; et il le nomma Néhustan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Il mit son espérance en l’Eternel le Dieu d’Israël, et après lui il n’y eut point de Roi semblable à lui entre tous les Rois de Juda, comme il n’y en avait point eu entre ceux qui avaient été avant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Il s’attacha à l’Eternel, il ne s’en détourna point; et il garda les commandements que l’Eternel avait donnés à Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Et l’Eternel fut avec lui partout où il allait, et il prospérait; mais il se rebella contre le Roi des Assyriens, pour ne lui être point assujetti.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Il frappa les Philistins jusqu’à Gaza, et ses confins, depuis les tours des gardes jusqu’aux villes fortes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Or il arriva en la quatrième année du Roi Ezéchias, qui était la septième du règne d’Hosée fils d’Ela Roi d’Israël, que Salmanéser Roi des Assyriens monta contre Samarie, et l’assiégea.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Au bout de trois ans ils la prirent; et ainsi la sixième année du règne d’Ezéchias, qui était la neuvième d’Hosée Roi d’Israël, Samarie fut prise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Et le Roi des Assyriens transporta les Israëlites en Assyrie, et les fit mener à Chalach, et sur le Chabor, fleuve de Gozan, et dans les villes des Mèdes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Parce qu’ils n’avaient point obéi à la voix de l’Eternel leur Dieu, mais avaient transgressé son alliance, et tout ce que Moïse serviteur de l’Eternel avait commandé; ils n’y avaient point obéi, et ne l’avaient point fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Or en la quatorzième année du Roi Ezéchias, Sanchérib Roi des Assyriens monta contre toutes les villes fortes de Juda, et les prit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Et Ezéchias Roi de Juda envoya dire au Roi des Assyriens à Lakis: J’ai fait une faute, retire-toi de moi, je payerai tout ce que tu m’imposeras; et le Roi des Assyriens imposa trois cents talents d’argent, et trente talents d’or à Ezéchias Roi de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Et Ezéchias donna tout l’argent qui se trouva dans la maison de l’Eternel, et dans les trésors de la maison Royale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'En ce temps-là Ezéchias mit en pièces les portes du Temple de l’Eternel, et les linteaux que lui-même avait couverts de lames d’or, et il les donna au Roi des Assyriens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Puis le Roi des Assyriens envoya de Lakis, Tarta, Rab-saris, et Rab-saké, avec de grandes forces vers le Roi Ezéchias à Jérusalem; et ils montèrent et vinrent à Jérusalem. Or étant montés et venus ils se présentèrent auprès du conduit du haut étang, qui est au grand chemin du champ du foulon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Et ils appelèrent le Roi tout haut. Alors Eliakim fils de Hilkija maître d’hôtel, et Sebna le Secrétaire, et Joach fils d’Asaph, commis sur les Registres, sortirent vers eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Et Rab-saké leur dit: Dites maintenant à Ezéchias: Ainsi a dit le grand Roi, le Roi des Assyriens: Quelle est cette confiance sur laquelle tu t’appuies?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Tu parles, mais ce ne sont que des paroles; le conseil et la force sont requis à la guerre. Mais en qui t’es-tu confié, pour te rebeller contre moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Voici maintenant, tu t’es confié en l’Egypte, en ce roseau cassé, sur lequel si quelqu’un s’appuie, il lui entrera dans la main, et la percera; tel est Pharaon Roi d’Egypte à tous ceux qui se confient en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Que si vous me dites: Nous nous confions en l’Eternel notre Dieu; n’ est - ce pas celui dont Ezéchias a détruit les hauts lieux, et les autels, et a dit à Juda, et à Jérusalem: Vous vous prosternerez devant cet autel à Jérusalem?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Or maintenant donne des otages au Roi des Assyriens mon Maître, et je te donnerai deux mille chevaux, si tu peux donner autant d’hommes pour monter dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Comment donc ferais-tu tourner visage au moindre Gouverneur d’entre les serviteurs de mon Maître? mais tu te confies en l’Egypte, à cause des chariots et des gens de cheval.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Mais maintenant suis-je monté sans l’Eternel contre ce lieu-ci pour le détruire? l’Eternel m’a dit: Monte contre ce pays-là, et le détruis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Alors Eliakim fils de Hilkija, et Sebna, et Joach dirent à Rab-saké: Nous te prions de parler en Langue Syriaque à tes serviteurs, car nous l’entendons; et ne nous parle point en Langue Judaïque, le peuple qui est sur la muraille l’écoutant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Et Rab-saké leur répondit: Mon Maître m’a-t-il envoyé vers ton Maître, ou vers toi, pour parler ce langage? ne m’a-t-il pas envoyé vers les hommes qui se tiennent sur la muraille; pour leur dire qu’ils mangeront leur propre fiente, et qu’ils boiront leur urine avec vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Rab-saké donc se tint debout, et s’écria à haute voix en Langue Judaïque, et parla, et dit: Ecoutez la parole du grand Roi, le Roi des Assyriens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Ainsi a dit le Roi: Qu’Ezéchias ne vous abuse point; car il ne vous pourra point délivrer de ma main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Qu’Ezéchias ne vous fasse point confier en l’Eternel, en disant: L’Eternel indubitablement nous délivrera, et cette ville ne sera point livrée entre les mains du Roi des Assyriens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'N’écoutez point Ezéchias; car ainsi a dit le Roi des Assyriens: Faites composition avec moi, et sortez vers moi; et vous mangerez chacun de sa vigne, et chacun de son figuier, et vous boirez chacun de l’eau de sa citerne;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'Avant que je vienne, et que je vous emmène en un pays qui est comme votre pays, un pays de froment et de bon vin, un pays de pain et de vignes, un pays d’oliviers qui portent de l’huile, et un pays de miel; vous vivrez, et vous ne mourrez point; mais n’écoutez point Ezéchias, quand il vous voudra persuader, en disant: L’Eternel nous délivrera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Les dieux des nations ont-ils délivré chacun leur pays de la main du Roi des Assyriens?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Où sont les dieux de Hamath, et d’Arpad; où sont les dieux de Sépharvajim, d’Henah, et de Hiwah? et même a-t-on délivré Samarie de ma main?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Qui sont ceux d’entre tous les dieux de ces pays-là qui aient délivré leur pays de ma main, pour dire que l’Eternel délivrera Jérusalem de ma main?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Et le peuple se tut, et on ne lui répondit pas un mot; car le Roi avait commandé disant: Vous ne lui répondrez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Après cela, Eliakim fils de Hilkija Maître d’hôtel, et Sebna le Secrétaire, et Joach fils d’Asaph, commis sur les Registres, s’en revinrent, les vêtements déchirés, vers Ezéchias, et ils lui rapportèrent les paroles de Rab-saké.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Et il arriva que dès que le Roi Ezéchias eut entendu ces choses, il déchira ses vêtements, et se couvrit d’un sac, et entra dans la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Puis il envoya Eliakim, Maître d’hôtel, et Sebna le Secrétaire, et les anciens d’entre les Sacrificateurs, couverts de sacs, vers Esaïe le Prophète fils d’Amots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Et ils lui dirent: Ainsi a dit Ezéchias: Ce jour est un jour d’angoisse, et de répréhension, et de blasphème; car les enfants sont venus jusqu’à l’ouverture de la matrice, mais il n’y a point de force pour enfanter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Peut-être que l’Eternel ton Dieu aura entendu toutes les paroles de Rab-saké, que le Roi des Assyriens son Maître a envoyé pour blasphémer le Dieu vivant, et pour l’outrager par les paroles que l’Eternel ton Dieu a entendues; fais donc une prière pour le reste qui se trouve encore.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Les serviteurs donc du Roi Ezéchias vinrent vers Esaïe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Et Esaïe leur dit, vous direz ainsi à votre Maître: Ainsi a dit l’Eternel: Ne crains point pour les paroles que tu as entendues, par lesquelles les serviteurs du Roi des Assyriens m’ont blasphémé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Voici, je m’en vais mettre en lui un tel esprit, qu’ayant entendu un certain bruit, il retournera en son pays, et je le ferai tomber par l’épée dans son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Or quand Rab-saké s’en fut retourné, il alla trouver le Roi des Assyriens qui battait Libna; car il avait appris qu’il était parti de Lakis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Le Roi donc des Assyriens eut des nouvelles touchant Tirhaca Roi d’Ethiopie: Voilà, lui disait-on, il est sorti pour te combattre. C’est pourquoi il s’en retourna, mais il envoya des messagers à Ezéchias, en leur disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Vous parlerez ainsi à Ezéchias Roi de Juda, et lui direz: Que ton Dieu, en qui tu te confies, ne t’abuse point en te disant: Jérusalem ne sera point livrée entre les mains du Roi des Assyriens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Voilà, tu as entendu ce que les Rois des Assyriens ont fait à tous les pays en les détruisant entièrement; et tu échapperais?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Les dieux des nations que mes ancêtres ont détruites, savoir de Gozan, de Caran, de Retseph, et des enfants d’Héden, qui sont en Thélasar, les ont-ils délivrées?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Où est le Roi de Hamath, le Roi d’Arpad, et le Roi de la ville de Sépharvajim, Hanath, et Hiwah?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Et quand Ezéchias eut reçu les Lettres de la main des messagers, et les eut lues, il monta dans la maison de l’Eternel, et Ezéchias les déploya devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Puis Ezéchias fit sa prière devant l’Eternel, et dit: Ô Eternel Dieu d’Israël! qui es assis entre les Chérubins, toi seul es le Dieu de tous les Royaumes de la terre; tu as fait les cieux et la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Ô Eternel! incline ton oreille, et écoute; ouvre tes yeux, et regarde; et écoute les paroles de Sanchérib, et de celui qu’il a envoyé pour blasphémer le Dieu vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Il est vrai, ô Eternel! que les Rois des Assyriens ont détruit ces nations- là, et leurs pays;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'Et qu’ils ont jeté qu feu leurs dieux, car ce n’étaient point des dieux, mais des ouvrages de main d’homme, du bois, et de la pierre, c’est pourquoi ils les ont détruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Maintenant donc, ô Eternel notre Dieu! je te prie, délivre-nous de la main de Sanchérib, afin que tous les Royaumes de la terre sachent que c’est toi, ô Eternel! qui es le seul Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Alors Esaïe fils d’Amots, envoya vers Ezéchias, pour lui dire: Ainsi a dit l’Eternel le Dieu d’Israël: Je t’ai exaucé dans ce que tu m’as demandé touchant Sanchérib Roi des Assyriens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'C’est ici la parole que l’Eternel a prononcée contre lui. La vierge fille de Sion t’a méprisé, et s’est moquée de toi; la fille de Jérusalem a hoché la tête après toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Qui as-tu outragé et blasphémé? contre qui as-tu élevé la voix, et levé les yeux en haut? c’est contre le Saint d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Tu as outragé le Seigneur par le moyen de tes messagers, et tu as dit: Avec la multitude de mes chariots je suis monté tout au haut des montagnes aux côtés du Liban; je couperai les plus hauts cèdres, et les plus beaux sapins qui y soient, et j’entrerai dans les logis qui sont à ses bouts, et dans la forêt de son Carmel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'J’ai creusé des sources après avoir bu les eaux étrangères; et j’ai tari avec la plante de mes pieds tous les ruisseaux des forteresses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'N’as-tu pas appris qu’il y a déjà longtemps que j’ai fait cette ville, et qu’anciennement je l’ai ainsi formée? et l’aurais-je maintenant amenée au point d’être réduite en désolation, et les villes munies, en monceaux de ruines?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Il est vrai que leurs habitants étant sans force ont été épouvantés, et confus, et qu’ils sont devenus comme l’herbe des champs, comme l’herbe verte, et le foin des toits, et comme la moisson qui a été touchée de la brûlure, avant qu elle soit crue en épi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Mais je sais ta demeure, ta sortie et ton entrée, et comment tu es forcené contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Or parce que tu es forcené contre moi, et que ton insolence est montée à mes oreilles, je mettrai ma boucle en tes narines, et mon mors dans tes mâchoires, et je te ferai retourner par le chemin par lequel tu es venu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Et ceci te sera pour signe, ô Ezéchias! c’est qu’on mangera cette année ce qui viendra de soi-même aux champs; et la seconde année, ce qui croîtra encore sans semer; mais la troisième année, vous sèmerez, et vous moissonnerez; vous planterez des vignes, et vous en mangerez le fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Et ce qui est réchappé et demeuré de reste dans la maison de Juda, étendra sa racine par dessous, et elle produira son fruit par dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Car de Jérusalem sortira quelque reste, et de la montagne de Sion quelques réchappés; la jalousie de l’Eternel des armées fera cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'C’est pourquoi ainsi a dit l’Eternel touchant le Roi des Assyriens: Il n’entrera point dans cette ville, il n’y jettera même aucune flèche, et il ne se présentera point contr’elle avec le bouclier, et il ne dressera point de terrasse contr’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Il s’en retournera par le chemin par lequel il est venu, et n’entrera point dans cette ville, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Car je garantirai cette ville, afin de la délivrer, pour l’amour de moi, et pour l’amour de David mon serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Il arriva donc cette nuit-là qu’un Ange de l’Eternel sortit, et tua cent quatre-vingt et cinq mille hommes au camp des Assyriens; et quand on se fut levé de bon matin, voilà, c’étaient tous corps morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Et Sanchérib Roi des Assyriens partit de là, et s’en alla, et s’en retourna, et se tint à Ninive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Et il arriva, comme il était prosterné dans la maison de Nisroc son Dieu, qu’Adrammélec et Saréetser ses fils le tuèrent avec l’épée, puis ils se sauvèrent au pays d’Ararat; et Esarhaddon son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'En ce temps-là Ezéchias fut malade à la mort; et le Prophète Esaïe fils d’Amots vint à lui, et lui dit: Ainsi a dit l’Eternel: Dispose de ta maison, car tu t’en vas mourir, et tu ne vivras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Alors Ezéchias tourna son visage contre la muraille, et fit sa prière à l’Eternel, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Je te prie, ô Eternel! que maintenant tu te souviennes comment j’ai marché devant toi en vérité, et en intégrité de coeur, et comment j’ai fait ce qui t’était agréable. Et Ezéchias pleura abondamment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Or il arriva qu’Esaïe n’étant point encore sorti de la cour du milieu, la parole de l’Eternel lui fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Retourne, et dis à Ezéchias conducteur de mon peuple: Ainsi a dit l’Eternel, le Dieu de David ton père; j’ai exaucé ta prière, j’ai vu tes larmes; voici je te vais guérir; dans trois jours tu monteras dans la maison de l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'J’ajouterai quinze ans à tes jours, je te délivrerai, toi et cette ville, de la main du Roi des Assyriens; et je garantirai cette ville, pour l’amour de moi, et pour l’amour de David mon serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Puis Esaïe dit: Prenez une masse de figues sèches; et ils la prirent, et la mirent sur l’ulcère; et il fut guéri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Or Ezéchias avait dit à Esaïe: Quel signe aurai-je que l’Eternel me guérira, et qu’au troisième jour je monterai en la maison de l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Et Esaïe répondit: Ceci t’est donné par l’Eternel pour un signe que l’Eternel accomplira la parole qu il a prononcée; l’ombre s’avancera-t-elle de dix degrés, ou retournera-t-elle en arrière de dix degrés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Et Ezéchias dit: C’est peu de chose que l’ombre s’avance de dix degrés; non, mais que l’ombre retourne en arrière de dix degrés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Et Esaïe le Prophète cria à l’Eternel; et l’Eternel fit retourner l’ombre par les degrés par lesquels elle était descendue au cadran d’Achaz, dix degrés en arrière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'En ce temps-là Bréodac-Baladan fils de Baladan Roi de Babylone, envoya des Lettres avec un présent à Ezéchias, parce qu’il avait appris qu’Ezéchias avait été malade.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Et Ezéchias les ayant entendus leur montra tous ses cabinets les plus curieux, l’argent, et l’or, et les aromates, et ses huiles de senteur, et tout son arsenal, et tout ce qui se trouvait dans ses trésors; il n’y eut rien dans sa maison et dans toute sa cour qu’Ezéchias ne leur montrât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Puis le Prophète Esaïe vint vers le Roi Ezéchias, et lui dit: Qu’ont dit ces gens-là? et d’où sont-ils venus vers toi? Et Ezéchias répondit: Ils sont venus d’un pays fort éloigné, ils sont venus de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Et Esaïe dit: Qu’ont-ils vu dans ta maison? Et Ezéchias répondit: Ils ont vu tout ce qui est dans ma maison; il n’y a rien dans mes trésors que je ne leur aie montré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Alors Esaïe dit à Ezéchias: Ecoute la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Voici, les jours viendront que tout ce qui est dans ta maison, et ce que tes pères ont amassé dans leurs trésors jusqu’à ce jour, sera emporté à Babylone; il n’en demeurera rien de reste, a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'On prendra même de tes fils qui seront sortis de toi, et que tu auras engendrés, afin qu’ils soient Eunuques au palais du Roi de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Et Ezéchias répondit à Esaïe: La parole de l’Eternel que tu as prononcée, est bonne; et il ajouta: N’y aura-t-il point paix et sûreté pendant mes jours?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Le reste des faits d’Ezéchias, et tous ses exploits, et comment il fit l’étang, et l’aqueduc par lequel il fit entrer les eaux dans la ville, n’est-il pas écrit au Livre des Chroniques des Rois de Juda?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Et Ezéchias s’endormit avec ses pères; et Manassé son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manassé était âgé de douze ans, quand il commença à régner, et il régna cinquante-cinq ans à Jérusalem; sa mère avait nom Hephtsiba.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Et il fit ce qui déplaît à l’Eternel, selon les abominations des nations que l’Eternel avait chassées de devant les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Car il rebâtit les hauts lieux qu’Ezéchias son père avait détruits, et redressa des autels à Bahal, et fit un bocage, comme avait fait Achab Roi d’Israël, il se prosterna devant toute l’armée des cieux, et il les servit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Il bâtit aussi des autels dans la maison de l’Eternel, de laquelle l’Eternel avait dit: Je mettrai mon Nom dans Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Il bâtit, dis-je, des autels à toute l’armée des cieux dans les deux parvis de la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Il fit aussi passer son fils par le feu, et il pronostiquait les temps, et observait les augures; il dressa un oracle d’esprit de Python, et de diseurs de bonne aventure; il faisait de plus en plus ce qui déplaît à l’Eternel pour l’irriter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Il posa aussi l’image du bocage qu’il avait fait, dans la maison dont l’Eternel avait dit à David, et à Salomon son fils: Je mettrai à perpétuité mon Nom dans cette maison, et dans Jérusalem, que j’ai choisie d’entre toutes les Tribus d Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Et je ne ferai plus sortir les Israëlites hors de cette terre que j’ai donnée à leurs pères, pourvu seulement qu’ils prennent garde à faire selon tout ce que je leur ai commandé, et selon toute la Loi que Moïse mon serviteur leur a ordonnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Mais ils n’obéirent point; car Manassé les fit égarer, jusqu’à faire pis que les nations que Dieu avait exterminées de devant les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Et l’Eternel parla par le moyen de ses serviteurs les Prophètes, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Parce que Manassé Roi de Juda a commis ces abominations, faisant pis que tout ce qu’ont fait les Amorrhéens qui ont été avant lui, et parce aussi qu’il a fait pécher Juda par ses dieux de fiente:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'A cause de cela l’Eternel le Dieu d’Israël, dit ainsi: Voici, je m’en vais faire venir un mal sur Jérusalem et sur Juda, tel que quiconque en entendra parler, les deux oreilles lui en corneront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Car j’étendrai sur Jérusalem le cordeau de Samarie, et le niveau de la maison d’Achab; et je torcherai Jérusalem comme une écuelle qu’on torche, et laquelle, après qu’on l’a torchée, on renverse sur son fond.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Et j’abandonnerai le reste de mon héritage, et je les livrerai entre les mains de leurs ennemis; et ils seront en pillage, et en proie à tous leurs ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'Parce qu’ils ont fait ce qui me déplaît, et qu’ils m’ont irrité depuis le jour que leurs pères sont sortis d’Egypte, même jusqu’à ce jour-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Davantage Manassé répandit une grande abondance de sang innocent, jusqu’à en remplir Jérusalem d’un bout à l’autre, outre son péché par lequel il fit pécher Juda; tellement qu’il fit ce qui déplaît à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Le reste des faits de Manassé, tout ce, dis-je, qu’il a fait; et le péché qu’il commit, n’est-il pas écrit au Livre des Chroniques des Rois de Juda?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Puis Manassé s’endormit avec ses pères, et fut enseveli au jardin de sa maison, au Jardin de Huza; et Amon son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Amon était âgé de vingt-deux ans, quand il commença à régner, et il régna deux ans à Jérusalem; sa mère avait nom Messullémet, fille de Haruts de Jotba.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Il fit ce qui déplaît à l’Eternel comme avait fait Manassé son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Car il suivit tout le train que son père avait tenu, et servit les dieux de fiente que son père avait servis, et se prosterna devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Il abandonna l’Eternel le Dieu de ses pères, et il ne marcha point dans la voie de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Or les serviteurs d’Amon firent une conspiration contre lui, et tuèrent le Roi dans sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Mais le peuple du pays frappa tous ceux qui avaient conspiré contre le Roi Amon, et ils établirent Josias son fils Roi en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Le reste des faits d’Amon, lesquels il a fait, n’est-il pas écrit au Livre des Chroniques des Rois de Juda?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Or on l’ensevelit dans son sépulcre au Jardin de Huza; et Josias son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Josias était âgé de huit ans quand il commença à régner, et il régna trente et un ans à Jérusalem; sa mère avait nom Jédida, fille de Hadaja de Botskath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Il fit ce qui est droit devant l’Eternel, et marcha dans toute la voie de David son père, et ne s’en détourna ni à droite ni à gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Or il arriva la dix-huitième année du Roi Josias, que le Roi envoya dans la maison de l’Eternel, Saphan, fils d’Atsalia, fils de Mésullam, le Secrétaire, en lui disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Monte vers Hilkija le grand Sacrificateur, et dis-lui de lever la somme de l’argent qu’on apporte dans la maison de l’Eternel, et que ceux qui gardent les vaisseaux ont recueilli du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'Et qu’on le délivre entre les mains de ceux qui ont la charge de l’oeuvre, et qui sont commis sur la maison de l’Eternel, qu’on le délivre, dis-je, à ceux qui ont la charge de l’oeuvre qui se fait dans la maison de l’Eternel, pour réparer ce qui est à réparer au Temple;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'Savoir aux charpentiers, aux architectes, et aux maçons, et afin d’acheter du bois et des pierres de taille pour réparer le Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Mais qu’on ne leur fasse pas rendre compte de l’argent qu’on leur délivre entre les mains, parce qu’ils s’y portent fidèlement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Alors Hilkija le grand Sacrificateur, dit à Saphan le Secrétaire: J’ai trouvé le Livre de la Loi dans la maison de l’Eternel; et Hilkija donna ce livre à Saphan, qui le lut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Et Saphan le Secrétaire s’en vint au Roi, et rapporta la chose au Roi, et dit: Tes serviteurs ont amassé l’argent qui a été trouvé dans le Temple, et l’ont délivré entre les mains de ceux qui ont la charge de l’oeuvre, et qui sont commis sur la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Saphan le secrétaire fit aussi entendre au Roi, en disant: Hilkija le Sacrificateur m’a donné un Livre; et Saphan le lut devant le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Et il arriva qu’aussitôt que le Roi eut entendu les paroles du Livre de la Loi, il déchira ses vêtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Et il commanda au Sacrificateur Hilkija, et à Ahikam fils de Saphan, et à Hacbor fils de Micaja, et à Saphan le Secrétaire, et à Hasaja serviteur du Roi, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Allez, consultez l’Eternel pour moi, et pour le peuple, et pour tout Juda, touchant les paroles de ce Livre qui a été trouvé; car la colère de l’Eternel qui s’est allumée contre nous, est grande, parce que nos pères n’ont point obéi aux paroles de ce Livre, pour faire tout ce qui nous y est prescrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Hilkija donc le Sacrificateur, et Ahikam, et Hacbor, et Saphan, et Hasaja s’en allèrent vers Hulda la prophétesse, femme de Sallum fils de Tikva, fils de Harhas, gardien des vêtements, laquelle demeurait à Jérusalem au collège, et ils parlèrent avec elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Et elle leur répondit: Ainsi a dit l’Eternel le Dieu d’Israël: Dites à l’homme qui vous a envoyés vers moi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Ainsi a dit l’Eternel: Voici je m’en vais faire venir du mal sur ce lieu- ci, et sur ses habitants, selon toutes les paroles du Livre que le Roi de Juda a lu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Parce qu’ils m’ont abandonné, et qu’ils ont fait des encensements aux autres dieux, pour m’irriter par toutes les actions de leurs mains, ma colère s’est allumée contre ce lieu, et elle ne sera point éteinte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Mais quant au Roi de Juda qui vous a envoyés pour consulter l’Eternel; vous lui direz: Ainsi a dit l’Eternel le Dieu d’Israël, touchant les paroles que tu as entendues;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Parce que ton coeur s’est amolli, et que tu t’es humilié devant l’Eternel, quand tu as entendu ce que j’ai prononcé contre ce lieu-ci, et contre ses habitants, qu’ils seraient en désolation et en malédiction, parce que tu as déchiré tes vêtements, et que tu as pleuré devant moi, je t’ai exaucé, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'C’est pourquoi voici, je vais te retirer avec tes pères, et tu seras retiré dans tes sépulcres en paix, et tes yeux ne verront point tout ce mal que je m’en vais faire venir sur ce lieu. Et ils rapportèrent toutes ces choses au Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Alors le Roi envoya, et on assembla vers lui tous les Anciens de Juda et de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Et le Roi monta à la maison de l’Eternel, et avec lui tous les hommes de Juda, et tous les habitants de Jérusalem, et les Sacrificateurs et les Prophètes, et tout le peuple, depuis le plus petit jusqu’au plus grand, et on lut, eux l’entendant, toutes les paroles du Livre de l’alliance, qui avait été trouvé dans la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Et le Roi se tint auprès de la colonne, et traita devant l’Eternel cette alliance-ci, qu’ils suivraient l’Eternel, et qu’ils garderaient de tout leur cœur, et de toute leur âme, ses commandements, ses témoignages, et ses statuts, pour persévérer dans les paroles de cette alliance, écrites dans ce Livre; et tout le peuple se tint à cette alliance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Alors le Roi commanda à Hilkija le grand Sacrificateur, et aux Sacrificateurs du second rang, et à ceux qui gardaient les vaisseaux, de tirer hors du Temple de l’Eternel tous les ustensiles qui avaient été faits pour Bahal, et pour les bocages, et pour toute l’armée des cieux; et il les brûla hors de Jérusalem dans les champs de Cédron, et on emporta leur poudre à Béthel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Et il abolit les prêtres des idoles, que les Rois de Juda avaient établis quand on faisait des encensements dans les hauts lieux, dans les villes de Juda, et autour de Jérusalem; il abolit aussi ceux qui faisaient des encensements à Bahal; au soleil, à la lune, et aux astres, à toute l’armée des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Il fit aussi emporter le bocage de la maison de l’Eternel hors de Jérusalem, en la vallée de Cédron, et le brûla dans la vallée de Cédron; il le réduisit en poudre, et le jeta sur le sépulcre des enfants du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Ensuite il démolit les maisons des prostitués à paillardise, lesquelles étaient dans la maison de l’Eternel; et dans lesquelles les femmes travaillaient à faire des pavillons pour le bocage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Il fit aussi venir des villes de Juda tous les Sacrificateurs, et profana les hauts lieux où les Sacrificateurs avaient fait des encensements, depuis Guébah jusqu’à Béer-sebah; et il démolit les hauts lieux des portes qui étaient à l’entrée de la porte de Josué, capitaine de la ville, laquelle est à la gauche de la porte de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Au reste, ceux qui avaient été Sacrificateurs des hauts lieux ne montaient point vers l’autel de l’Eternel à Jérusalem, mais ils mangeaient des pains sans levain parmi leurs frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Il profana aussi Topheth, qui était dans la vallée du fils de Hinnom, afin qu’il ne servît plus à personne pour y faire passer son fils ou sa fille par le feu, à Molec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Il ôta aussi de l’entrée de la maison de l’Eternel les chevaux que les Rois de Juda avaient consacrés au soleil, vers le logis de Néthanmélec Eunuque, situé à Parvarim, et il brûla au feu les chariots du soleil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Le Roi démolit aussi les autels qui étaient sur le toit de la chambre haute d’Achaz, que les Rois de Juda avaient faits, et les autels que Manassé avait faits dans les deux parvis de la maison de l’Eternel; il les brisa, les ôtant de là, et il en répandit la poudre au torrent de Cédron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Le Roi profana aussi les hauts lieux qui étaient vis-à-vis de Jérusalem à la main droite sur la montagne des oliviers, que Salomon Roi d’Israël avait bâtis à Hastareth, l’abomination des Sidoniens; et à Kémos, l’abomination des Moabites; et à Milkom, l’abomination des enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Il brisa aussi les statues, et coupa les bocages, et remplit d’ossements d’hommes les lieux ou ils étaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Il démolit aussi l’autel qui était à Bethel, et le haut lieu qu’avait fait Jéroboam fils de Nébat, qui avait fait pécher Israël, cet autel-là, dis-je, et le haut lieu; il brûla le haut lieu, et le réduisit en poudre, et brûla le bocage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Or Josias s’étant tourné, avait vu les sépulcres qui étaient là en la montagne, et il avait envoyé prendre les os des sépulcres, et les avait brûlés sur l’autel, et il l’avait ainsi profané, suivant la parole de l’Eternel, que l’homme de Dieu avait prononcée à haute voix, lorsqu’il prononça ces choses-là à haute voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Et le Roi avait dit: Qu’est-ce que ce tombeau que je vois? Et les hommes de la ville lui avaient répondu: C’est le sépulcre de l’homme de Dieu qui vint de Juda, et qui prononça à haute voix les choses que tu as faites sur l’autel de Bethel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Et il avait dit: Laissez-le, que personne ne remue ses os; ainsi ils avaient préservé ses os, avec les os du Prophète qui était venu de Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Josias ôta aussi toutes les maisons des hauts lieux qui étaient dans les villes de Samarie, que les Rois d’Israël avaient faites pour irriter l’Eternel; et il leur fit selon tout ce qu’il avait fait à Bethel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Et il sacrifia sur les autels tous les sacrificateurs des hauts lieux qui étaient là, et brûla sur eux des ossements d’hommes; puis il s’en retourna à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Alors le Roi commanda à tout le peuple, en disant: Célébrez la Pâque à l’Eternel votre Dieu, en la manière qu’il est écrit au Livre de cette alliance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Et certainement jamais Pâque ne fut célébrée dans le temps des Juges qui avaient jugé en Israël, ni dans tout le temps des Rois d’Israël, et des Rois de Juda,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Comme cette Pâque qui fut célébrée en l’honneur de l’Eternel dans Jérusalem, la dix-huitième année du Roi Josias.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Josias extermina aussi ceux qui avaient des esprits de Python, les diseurs de bonne aventure, les Théraphims, les dieux de fiente, et toutes les abominations qui avaient été vues dans le pays de Juda, et dans Jérusalem; afin d’accomplir les paroles de la Loi, écrites au livre qu’ Hilkija le Sacrificateur avait trouvé dans la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Avant lui il n’y eut point de Roi qui lui fut semblable, qui se retournât vers l’Eternel de tout son coeur, et de toute son âme, et de toute sa force; selon toute la Loi de Moïse; et après lui il ne s’en est point levé de semblable à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Toutefois l’Eternel ne revint point de l’ardeur de sa grande colère de laquelle il avait été embrasé contre Juda, à cause de tout ce que Manassé avait fait pour l’irriter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Car l’Eternel avait dit: Je rejetterai aussi Juda de devant ma face, comme j’ai rejeté Israël; et je rejetterai cette ville de Jérusalem, que j’ai choisie, et la maison de laquelle j’ai dit: Mon nom sera là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Le reste des faits de Josias, tout ce, dis-je, qu’il a fait, n’est-il pas écrit au Livre des Chroniques des Rois de Juda?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'De son temps, Pharaon-Néco Roi d’Egypte monta contre le Roi des Assyriens vers le fleuve d’Euphrate, et Josias s’en alla au devant de lui, mais dès que Pharaon l’eut vu, il le tua à Méguiddo.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Et ses serviteurs le chargèrent mort sur un chariot de Méguiddo, et le portèrent à Jérusalem, et l’ensevelirent dans son sépulcre; et le peuple du pays prit Jéhoachaz, fils de Josias, et ils l’oignirent, et l’établirent Roi en la place de son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Jéhoachaz était âgé de vingt et trois ans, quand il commença à régner, et il régna trois mois à Jérusalem; sa mère avait nom Hamutal, fille de Jérémie de Libna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Il fit ce qui déplaît à l’Eternel, comme avaient fait ses pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Et Pharaon-Néco l’emprisonna à Ribla, au pays de Hamath, afin qu’il ne régnât plus à Jérusalem; et il imposa sur le pays une amende de cent talents d’argent, et d’un talent d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Puis Pharaon-Néco établit pour Roi Eliakim fils de Josias, en la place de Josias son père, et lui changea son nom, l’appelant Jéhojakim; et il prît Jéhoachaz, qui vint en Egypte, où il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Or Jéhojakim donna cet argent et cet or à Pharaon, ayant mis des taxes sur le pays pour fournir cet argent selon le commandement de Pharaon; et il leva l’argent et l’or de chacun du peuple du pays selon qu’il était taxé, pour donner à Pharaon-Néco.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Jéhojakim était âgé de vingt-cinq ans quand il commença à régner, et il régna onze ans à Jérusalem; sa mère avait nom Zebudda, fille de Pédaja de Ruma.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Il fit ce qui déplaît à l’Eternel, comme avaient fait ses pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'De son temps Nébuchadnetsar, Roi de Babylone, monta contre Jéhojakim, et Jéhojakim lui fut asservi l’espace de trois ans; puis ayant changé de volonté, il se rebella contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Et l’Eternel envoya contre Jéhojakim des troupes de Chaldéens, et des troupes de Syriens, et des troupes de Moab, et des troupes des enfants de Hammon; il les envoya, dis-je, contre Juda, pour le détruire, suivant la parole de l’Eternel qu’il avait prononcée par le moyen des Prophètes ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Et cela arriva selon le mandement de l’Eternel contre Juda, pour le rejeter de devant sa face, à cause des péchés de Manassé, selon tout ce qu’il avait fait;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'Et à cause aussi du sang innocent qu’il avait répandu, ayant rempli Jérusalem de sang innocent; c’est pourquoi l’Eternel ne lui voulut point pardonner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Le reste des faits de Jéhojakim, tout ce, dis-je, qu’il a fait, n’est-il pas écrit au Livre des Chroniques des Rois de Juda?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Ainsi Jéhojakim s’endormit avec ses pères; et Jéhojachin son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Or le Roi d’Egypte ne sortit plus de son pays, parce que le Roi de Babylone avait pris tout ce qui était au Roi d Egypte, depuis le torrent d’Egypte jusqu’au fleuve d’Euphrate.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Jéhojachin était âgé de dix-huit ans quand il commença à régner, et il régna trois mois à Jérusalem; sa mère avait nom Nehusta, fille d’Elnathan de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Il fit ce qui déplaît à l’Eternel, comme avait fait son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'En ce temps-là les gens de Nébuchadnetsar, Roi de Babylone, montèrent contre Jérusalem, et là ville fut assiégée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Et Nébuchadnetsar Roi de Babylone vint contre la ville, lorsque ses gens l’assiégeaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Alors Jéhojachin Roi de Juda sortit vers le Roi de Babylone, lui, sa mère, ses gens, ses capitaines, et ses Eunuques; de sorte que le Roi de Babylone le prit la huitième année de son règne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Et il tira hors de là, selon que l’Eternel en avait parlé, tous les trésors de la maison de l’Eternel, et les trésors de la maison Royale, et mit en pièces tous les ustensiles d’or que Salomon Roi d’Israël avait faits pour le Temple de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Et il transporta tout Jérusalem, savoir, tous les capitaines, et tous les vaillants hommes de guerre, au nombre de dix mille captifs, avec les charpentiers et les serruriers, de sorte qu’il ne demeura personne de reste que le pauvre peuple du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Ainsi il transporta Jéhojachin à Babylone, avec la mère du Roi, et les femmes du Roi et ses Eunuques, et il emmena captifs à Babylone tous les plus puissants du pays de Jérusalem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Avec tous les hommes vaillants au nombre de sept mille, et les charpentiers et les serruriers au nombre de mille, tous puissants et propres à la guerre, lesquels le Roi de Babylone emmena captifs à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Et le Roi de Babylone établit pour Roi, en la place de Jéhojachin, Mattania son oncle, et lui changea son nom, l’appelant Sédécias.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Sédécias était âgé de vingt et un ans, quand il commença à régner, et il régna onze ans à Jérusalem; sa mère avait nom Hamutal, fille de Jérémie de Libna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Il fit ce qui déplaît à l’Eternel comme avait fait Jéhojakim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Car il arriva à cause de la colère de l’Eternel contre Jérusalem et contre Juda, afin qu’il les rejetât de devant sa face, que Sédécias se rebella contre le Roi de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Il arriva donc la neuvième année du règne de Sédécias, le dixième jour du dixième mois, que Nébucadnetsar Roi de Babylone vint avec toute son armée contre Jérusalem, et se campa contr’elle, et ils bâtirent des forts tout autour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Et la ville fut assiégée jusqu’à la onzième année du Roi Sédécias.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Et le neuvième jour du quatrième mois la famine augmenta dans la ville, de sorte qu’il n’y avait point de pain pour le peuple du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Alors la brèche fut faite à la ville, et tous les gens de guerre s’enfuirent de nuit par le chemin de la porte entre les deux murailles qui étaient près du jardin du Roi (or les Caldéens étaient tout joignant la ville à l’environ) et le Roi s’en alla par le chemin de la campagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Mais l’armée des Caldéens poursuivit le Roi, et quand ils l’eurent atteint dans les campagnes de Jérico, toute son armée se dispersa d’auprès de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Ils prirent donc le Roi, et le firent monter vers le Roi de Babylone à Ribla; où on lui fit son procès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Et on égorgea les fils de Sédécias en sa présence; après quoi on creva les yeux à Sédécias, et l’ayant lié de doubles chaînes d’airain, on le mena à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Et au septième jour du cinquième mois, en la dix-neuvième année du Roi Nébucadnetsar, Roi de Babylone, Nébuzar-adan prévôt de l’hôtel, serviteur du Roi de Babylone, entra dans Jérusalem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Et il brûla la maison de l’Eternel, et la maison Royale, et toutes les maisons de Jérusalem, et mit le feu dans toutes les maisons des Grands.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Et toute l’armée des Caldéens, qui était avec le prévôt de l’hôtel, démolit les murailles de Jérusalem tout autour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Et Nébuzar-adan prévôt de l’hôtel transporta à Babylone le reste du peuple, savoir ceux qui étaient demeurés de reste dans la ville, et ceux qui s’étaient allés rendre au Roi de Babylone, et le reste de la multitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Néanmoins le prévôt de l’hôtel laissa quelques-uns des plus pauvres du pays pour être vignerons et laboureurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Et les Caldéens mirent en pièces les colonnes d’airain qui étaient dans la maison de l’Eternel, et les soubassements, et la mer d’airain qui était dans la maison de l’Eternel, et ils en emportèrent l’airain à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Ils emportèrent aussi les chaudrons, et les racloirs, et les serpes, et les tasses, et tous les ustensiles d’airain dont on faisait le service.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Le prévôt de l’hôtel emporta aussi les encensoirs et les bassins; et ce qui était d’or, et ce qui était d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Quant aux deux colonnes, à la mer, et aux soubassements que Salomon avait faits pour la maison de l’Eternel, on ne pesa point l’airain de tous ces vaisseaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Chaque colonne avait dix-huit coudées de haut, et elle avait un chapiteau d’airain par dessus, dont la hauteur était de trois coudées, outre le rets et les grenades qui étaient autour du chapiteau, le tout d’airain; et la seconde colonne était de même façon, avec le rets.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Le prévôt de l’hôtel emmena aussi Séraja premier Sacrificateur, et Sophonie second Sacrificateur, et les trois gardes des vaisseaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'Il emmena aussi de la ville un Eunuque qui avait la charge des hommes de guerre, et cinq hommes de ceux qui voyaient la face du Roi, lesquels furent trouvés dans la ville. Il emmena aussi le Secrétaire du Capitaine de l’armée qui enrôlait le peuple du pays, et soixante hommes d’entre le peuple du pays, qui furent trouvés dans la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Nébuzar-adan donc prévôt de l’hôtel les prit, et les mena au Roi de Babylone à Ribla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Et le Roi de Babylone les frappa, et les fit mourir à Ribla, au pays de Hamath; ainsi Juda fut transporté hors de sa terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Mais quant au peuple qui était demeuré de reste au pays de Juda, et que Nébucadnetsar Roi de Babylone y avait laissé, il établit pour Gouverneur sur eux Guédalia fils d’Ahikam, fils de Saphan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Quand tous les Capitaines des gens de guerre, et leurs gens, eurent appris que le Roi de Babylone avait établi Guédalia pour Gouverneur, ils allèrent trouver Guédalia à Mitspa, savoir Ismaël fils de Néthania, et Johanan fils de Karéath, et Séraja fils de Tanhumeth Nétophathite, Jaazania fils d’un Mahachathite, eux et leurs gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Et Guédalia leur jura et à leurs gens, et leur dit: Ne faites pas difficulté d’être serviteurs des Caldéens; demeurez au pays, et servez le Roi de Babylone, et vous vous en trouverez bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Mais il arriva au septième mois, qu’Ismaël fils de Néthania, fils d’Elisamah, qui était du sang Royal, et dix hommes avec lui vinrent, et frappèrent Guédalia, dont il mourut. Ils frappèrent aussi les Juifs et les Caldéens qui étaient avec lui à Mitspa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Et tout le peuple depuis le plus petit jusqu’au plus grand, avec les capitaines des gens de guerre, se levèrent, et s’en allèrent en Egypte, parce qu’ils avaient peur des Caldéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Or il arriva la trente-septième année de la captivité de Jéhojachin Roi de Juda, le vingt-septième jour du douzième mois, qu’Evilmérodac, Roi de Babylone, l’année qu’il commença à régner, tira hors de prison Jéhojachin Roi de Juda, et le mit en liberté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Et il lui parla avec douceur, et mit son trône au dessus du trône des Rois qui étaient avec lui à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Et après qu’il lui eut changé ses vêtements de prison, il mangea du pain ordinairement tout le temps de sa vie en sa présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Et quant à son ordinaire, un ordinaire continuel lui fut établi par le Roi chaque jour, tout le temps de sa vie. Retournez au début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Seth, Enos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kénan, Mahalaléël, Jéred;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Hénoc, Méthusélah, Lémec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noé, Sem, Cam, et Japheth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Les enfants de Japheth furent, Gomer, Magog, Madaï, Javan, Tubal, Mésec, et Tiras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Les enfants de Gomer furent, Askenaz, Diphath, et Togarma.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Et les enfants de Javan furent, Elisam, Tarsa, Kittim, et Rodanim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Les enfants de Cam furent, Cus, Mitsraïm, Put, et Canaan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Et les enfants de Cus furent, Séba, Havila, Sabta, Rahma, et Sabteca. Et les enfants de Rahma furent, Séba et Dédan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Cus engendra aussi Nimrod, qui commença d’être puissant sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Et Mitsraïm engendra Ludim, Hanamim, Léhabim, Naphtuhim,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Pathrusim, Casluhim (desquels sont issus les Philistins), et Caphtorim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Et Canaan engendra Sidon son fils aîné, et Heth;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'Les Jébusiens, les Amorrhéens, les Guirgasiens,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Les Héviens, les Harkiens, les Siniens,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Les Arvadiens, les Tsemariens, et les Hamathiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Les enfants de Sem furent, Hélam, Assur, Arpacsad, Lud, Aram, Hus, Hul, Guéther, et Mésec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Et Arpacsad engendra Sélah, et Sélah engendra Héber.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Et à Héber naquirent deux fils; l’un s’appelait Péleg, car en son temps la terre fut partagée; et son frère se nommait Joktan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Et Joktan engendra Almodad, Seleph, Hatsarmaveth, Jerah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadoram, Uzal, Dikla,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Hébal, Abimaël, Séba,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ophir, Havila, et Jobab; tous ceux-là furent les enfants de Joktan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arpacsad, Sélah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Héber, Péleg, Réhu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nacor, Taré,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Et Abram, qui est Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Les enfants d’Abraham furent, Isaac et Ismaël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Ce sont ici leurs générations; le premier-né d’Ismaël fut Nébajoth, puis Kédar, Adbéël, Mibsam,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Mismah, Duma, Massa, Hadad, Téma,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jéthur, Naphis, et Kedma; ce sont là les enfants d’Ismaël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Quant aux enfants de Kétura concubine d’Abraham, elle enfanta Zimram, Joksan, Médan, Madian, Jisbak, et Suah; et les enfants de Joksan furent, Séba, et Dédan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Et les enfants de Madian furent, Hépha, Hépher, Hanoc, Abidah, et Eldaha. Tous ceux-là furent les enfants de Kétura.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Or Abraham avait engendré Isaac; et les enfants d’Isaac furent, Esaü, et Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Les enfants d’Esaü furent, Eliphaz, Réhuël, Jéhus, Jahlam, et Korah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Les enfants d’Eliphaz furent, Téman, Omar, Tséphi, Gahtham, et Kénaz; et Timnah lui enfanta Hamalec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Les enfants de Réhuël furent, Nahath, Zérah, Samma, et Miza.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Et les enfants de Séhir furent, Lotan, Sobal, Tsibhon, Hana, Dison, Etser, et Disan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Et les enfants de Lotan furent, Hori, et Homam; et Timnah fut soeur de Lotan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Les enfants de Sobal furent, Halian, Manahath, Hébal, Séphi, et Onam. Les enfants de Tsibhon furent, Aja, et Hana.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Les enfants d’Hana furent, Dison. Les enfants de Dison furent, Hamram, Esban, Jitran, et Kéran.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Les enfants d’Etser furent, Bilhan, Zahavan et Jahakan. Les enfants de Dison furent, Huts, et Aran.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Or ce sont ici les Rois qui ont régné au pays d’Edom, avant qu’aucun Roi régnât sur les enfants d’Israël; Bélah fils de Béhor, et le nom de sa ville était Dinhaba.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Et Bélah mourut, et Jobab, fils de Perah de Botsra, régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Et Jobab mourut, et Husam, du pays des Témanites, régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Et Husam mourut, et Hadad fils de Bédad régna en sa place, qui défit Madian au territoire de Moab. Le nom de sa ville était Havith.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Et Hadad mourut, et Samla, de Masreka, régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Et Samla mourut, et Saül, de Rehoboth du fleuve, régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Et Saül mourut, et Bahal-hanan de Hacbor régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Et Bahal-hanan mourut, et Hadad régna en sa place. Le nom de sa ville était Pahi, et le nom de sa femme Mehetabéël, qui était fille de Matred, et petite- fille de Me-zahab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Enfin Hadad mourut. Ensuite vinrent les Ducs d’Edom, le Duc Timna, le Duc Halia, le Duc Jétheth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'Le Duc Aholibama, le Duc Ela, le Duc Pinon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'Le Duc Kénaz, le Duc Téman, le Duc Mibtsar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'Le Duc Magdiël, et le Duc Hiram. Ce sont là les Ducs d’Edom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Ce sont ici les enfants d’Israël, Ruben, Siméon, Lévi, Juda, Issacar, Zabulon,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Joseph, Benjamin, Nephthali, Gad, et Aser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Les enfants de Juda furent, Her, Onan, et Séla. Ces trois lui naquirent de la fille de Suah, Cananéenne; mais Her premier-né de Juda fut méchant devant l’Eternel, et il le fit mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Et Tamar, sa belle-fille, lui enfanta Pharez et Zara. Tous les enfants de Juda furent cinq.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Les enfants de Pharez, Hetsron, et Hamul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Et les enfants de Zara furent, Zimri, Ethan, Héman, Calcol et Darah, cinq en tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Carmi n’eut point de fils qu’ Hachar qui troubla Israël, et qui pécha en prenant de l’interdit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Et Ethan n’eut point de fils qu’Hazaria.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Et les enfants qui naquirent à Hetsron furent Jérahméël, Ram, et Célubaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Et Ram engendra Hamminadab, et Hamminadab engendra Nahasson, chef des enfants de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Et Nahasson engendra Salma, et Salma engendra Booz.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Et Booz engendra Obed, et Obed engendra Isaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Et Isaï engendra son premier-né Eliab, le second Abinadab, le troisième Simha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Le quatrième Nathanaël, le cinquième Raddaï,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Le sixième Otsen, et le septième, David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Et Tséruïa et Abigaïl furent leurs soeurs. Tséruïa eut trois fils, Abisaï, Joab, et Hazaël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Et Abigaïl enfanta Hamasa, dont le père fut Jéther Ismaëlite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Or Caleb fils de Hetsron eut des enfants de Hazuba sa femme, et aussi de Jérihoth; et ses enfants furent, Jéser, Sobob, et Ardon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Et Hazuba mourut, et Caleb prit à femme Ephrat, qui lui enfanta Hur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Et Hur engendra Uri, et Uri engendra Betsaléël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Après cela Hetsron vint vers la fille de Makir père de Galaad, et la prit pour sa femme, étant âgé de soixante ans; et elle lui enfanta Ségub.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Et Ségub engendra Jaïr, qui eut vingt et trois villes au pays de Galaad;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Et il prit sur Guésur et sur Aram les bourgades de Jaïr, et Kénath avec les villes de son ressort, qui sont soixante villes: tous ceux-là furent enfants de Makir père de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Et après la mort de Hetsron, lorsque Caleb vint vers Ephrat, la femme de Hetsron Abija lui enfanta Ashur père de Tékoah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Et les enfants de Jérahméël premier-né de Hetsron furent, Ram son fils aîné, puis Buna, et Oren, et Otsem, nés d’Achija.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Jérahméël eut aussi une autre femme, nommée Hatara, qui fut mère d’Onam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Et les enfants de Ram premier-né de Jérahméël furent, Mahats, Jamin, et Heker.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Et les enfants d’Onam furent, Sammaï, et Jadah; et les enfants de Sammaï furent, Nadab, et Abisur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Le nom de la femme d’Abisur fut Abihaïl, qui lui enfanta Acham, et Molid.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Et les enfants de Nadab furent, Séled, et Appajim; mais Séled mourut sans enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Et Appajim n’eut point de fils que Jiséhi; et Jiséhi n’eut point de fils que Sésan; et Sésan n’eut qu’ Ahlaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Et les enfants de Jadah, frère de Sammaï, furent Jéther, et Jonathan; mais Jéther mourut sans enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Et les enfants de Jonathan furent, Péleth, et Zara; ce furent là les enfants de Jérahméël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Et Sésan n’eut point de fils, mais des filles; or il avait un serviteur Egyptien, nommé Jarhah;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Et Sésan donna sa fille pour femme à Jarhah son serviteur, et elle lui enfanta Hattaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Et Hattaï engendra Nathan, et Nathan engendra Zabad;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Et Zabad engendra Ephlal; et Ephlal engendra Obed;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Et Obed engendra Jéhu; et Jéhu engendra Hazaria;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Et Hazaria engendra Hélets; et Hélets engendra Elhasa;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Et Elhasa engendra Sismaï; et Sismaï engendra Sallum;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Et Sallum engendra Jékamia; et Jékamia engendra Elisamah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Les enfants de Caleb, frère de Jérahméël, furent, Mésah son premier-né; celui-ci est le père de Ziph, et les enfants de Marésa père d’Hébron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Et les enfants d’Hébron furent Korah, Tappuah, Rekem et Sémah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Et Sémah engendra Raham, père de Jokeham, et Rekem engendra Sammaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Le fils de Sammaï fut Mahon; et Mahon fut père de Beth-tsur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Et Hépha concubine de Caleb, enfanta Haran, Motsa et Gazez; Haran aussi engendra Gazez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Et les enfants de Jadaï furent Reguem, Jotham, Guésan, Pelet, Hépha, et Sahaph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Et Mahaca, la concubine de Caleb, enfanta Séber, et Tirhana.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Et la femme de Sahaph, père de Madmanna, enfanta Séva, père de Macbéna, et le père de Guibha, et la fille de Caleb fut Hacsa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Ceux-ci furent les enfants de Caleb, fils de Hur, premier-né d’Ephrat, Sobal, père de Kirjath-jéharim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma père de Bethléhem, Hareph père de Beth-gader.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Et Sobal père de Kirjath-jéharim eut des enfants, Haroë, et Hatsi- menuhoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Et les familles de Kirjath-jéharim furent les Jithriens, les Puthiens, les Sumathiens, et les Misrahiens; dont sont sortis les Tsarhathiens, et les Estaoliens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Les enfants de Salma, Bethléhem, et les Nétophatiens, Hatroth, Bethjoab, Hatsimenuhoth, et les Tsorhiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'Et les familles des Scribes, qui habitaient à Jahbets, Tirhathiens, Simhathiens, Suchathiens; ce sont les Kéniens, qui sont sortis de Hamath père de Réchab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Or ce sont ici les enfants de David, qui lui naquirent à Hébron. Le premier- né fut Amnon, fils d’Ahinoham de Jizréhel; le second Daniel, d’Abigaïl du mont Carmel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'Le troisième Absalom fils de Mahaca, fille de Talmaï Roi de Guésur; le quatrième Adonija, fils de Hagguith;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'Le cinquième Sephatia, d’Abital; le sixième Jithréham, d’Hégla sa femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Ces six lui naquirent à Hébron, où il régna sept ans et six mois; puis il régna trente-trois ans à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Et ceux-ci lui naquirent à Jérusalem, Simha, Sobab, Nathan, et Salomon, tous quatre de Bathsuah, fille d’Hammiël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'Et Jibhar, Elisamah, Eliphelet,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Nogah, Nepheg, Japhiah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elisamah, Eliadah, et Eliphelet, qui sont neuf.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Tous enfants de David, outre les enfants des concubines, et Tamar leur soeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Le fils de Salomon fut Roboam; duquel fut fils Abija; duquel fut fils Asa; duquel fut fils Josaphat;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'Duquel fut fils Joram; duquel fut fils Achazia; duquel fut fils Joas;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'Duquel fut fils Amatsia; duquel fut fils Hazaria; duquel fut fils Jotham;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'Duquel fut fils Achaz; duquel fut fils Ezéchias; duquel fut fils Manassé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'Duquel fut fils Amon; duquel fut fils Josias.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Et les enfants de Josias furent Johanan son premier-né, le second Jéhojakim, le troisième Sédécias, le quatrième Sallum.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Et les enfants de Jéhojakim furent Jéchonias son fils, qui eut pour fils Sédécias.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Et quant aux enfants de Jéchonias qui fut emmené en captivité, Salathiël fut son fils;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Dont les fils furent Malkiram, Pédaja, Senatsar, Jékamia, Hosamah, et Nédabia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Et les enfants de Pédaja furent Zorobabel, et Simhi; et les enfants de Zorobabel furent Mésullam, Hanania, et Sélomith leur soeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'Et de Mésullam Hasuba, Ohel, Bérécia, Hasadia, et Jusab-hesed, en tout cinq.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Et les enfants de Hanania furent Pelatia, et Esaïe. Les enfants de Réphaja, les enfants d’Arnan, les enfants de Hobadia, et les enfants de Sécania.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Et les enfants de Sécania, Sémahja; et les enfants de Sémahja, Hattus, Jiguéal, Bariah, Neharia, Saphat, en tout six.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Et les enfants de Neharia furent ces trois Eliohenaï, Ezéchias, et Hazrikam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Et les enfants d’Eliohenaï furent ces sept Hodaivahu, Eliasib, Pélaïa, Hakkub, Johanan, Delaja, et Hanani.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Les enfants de Juda furent Pharez, Hetsron, Carmi, Hur, et Sobal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Et Reaja fils de Sobal engendra Jahath, et Jahath engendra Ahumaï, et Ladad. Ce sont là les familles des Tsorhathiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Et ceux-ci sont du père de Hétham, Jizréhel, Jisma, et Jidbas, et le nom de leur soeur était Hatselelponi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Et Penuël père de Guédor, et Hézer père de Husa; ce sont là les enfants de Hur, premier-né d’Ephrat père de Bethléhem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Et Ashur, père de Tékoah, eut deux femmes, Héléa, et Nahara.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Et Nahara lui enfanta Ahuzam, Hepher, Témeni, et Hahastari: ce sont là les enfants de Nahara.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Et les enfants de Héléa furent Tséreth, Jetsohar, et Etnan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Et Kots engendra Hanub, et Tsobeba, et les familles d’Ahathel, fils de Harum;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Entre lesquelles il y eut Jahbets plus distingué que ses frères; et sa mère lui avait donné le nom de Jahbets, parce que, dit-elle, je l’ai enfanté avec travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Or Jahbets invoqua le Dieu d’Israël, en disant: Ô! Si tu me bénissais abondamment, et que tu étendisses mes limites, et que ta main fût avec moi, et que tu me garantisses tellement du mal, que je fusse sans douleur. Et Dieu lui accorda ce qu’il avait demandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Et Kélub frère de Suha engendra Méhir, qui fut père d’Eston.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Et Eston engendra Beth-rapha, Paséah, et Téhinna, père d’Hirnahas; ce sont là les gens de Réca.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Et les enfants de Kénaz furent, Hothniel et Séraja. Et les enfants de Hothniel, Hathath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Et Méhonothaï engendra Hophra; et Séraja engendra Joab père de la vallée des ouvriers; car ils étaient ouvriers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Et les enfants de Caleb, fils de Jéphunné, furent, Hiru, Ela, et Naham. Et les enfants d’Ela, Kénaz.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Et les enfants de Jehallelel furent, Ziph, Zipha, Tiria, et Asarel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Et les enfants d’Esdras furent, Jéther, Méred, Hépher, et Jalon; et la femme de Méred enfanta Marie, Sammaï, et Jisbah père d’Estemoah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Et sa femme Jéhudija enfanta Jéred père de Guédor, et Héber père de Soco, et Jékuthiel père de Zanoah. Mais ceux-là sont les enfants de Bithia fille de Pharaon, que Méred prit pour femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Et les enfants de la femme de Hodija, soeur de Naham, furent le père de Kéhila Garmien, et Estemoah Mahacatien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Et les enfants de Simmon furent, Amnon, Rinna, Ben-hanan, et Tilon. Et les enfants de Jishi furent, Zoheth, et Ben-zoheth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Les enfants de Séla fils de Juda, furent, Hel père de Léca, et Lahda père de Marésa, et les familles de la maison de l’ouvrage du fin lin, qui sont de la maison d’Absbéath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'Et Jokim, et les gens de Cozeba, et Joas, et Saraph, qui dominèrent sur Moab, et Jasubiléhem; mais ce sont là des choses anciennes).');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Ils furent potiers de terre, et gens qui se tenaient dans les vergers et dans les parcs, et qui habitaient là chez le Roi pour son ouvrage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Les enfants de Siméon furent, Némuël, Jamin, Jarib, Zérah, et Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Sallum son fils, Mibsam son fils, et Mismah son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Et les enfants de Mismah furent Hamuël son fils, Zacur son fils, et Simhi son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Et Simhi eut seize fils et six filles; mais ses frères n’eurent pas beaucoup d’enfants, et toute leur famille ne put être aussi nombreuse que celle des enfants de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Et ils habitèrent à Béer-sebah, à Molada, à Hatsar-stuhal,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'A Bilha, à Hetsem, à Tholad,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'A Betuël, à Horma, à Tsiklag,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'A Beth-marcaboth, à Hatsarsusim, à Beth-birei, et à Saharajim. Ce furent là leurs villes jusqu’au temps que David fut Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Et leurs bourgades furent, Hétam, Hajin, Rimmon, Token, et Hassan, cinq villes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'Et tous leurs villages, qui étaient autour de ces villes-là, jusqu’à Bahal. Ce sont là leurs habitations, et leur généalogie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Or Mésobab, Jamlec, Josa fils d’Amatsia;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Joël, Jéhu fils de Josibia, fils de Séraja, fils de Hasiel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Eliohenaï, Jahakoba, Jésahaja, Hasaïa, Hadiël, Jésimiël, Bénéja.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'Et Ziza, fils de Siphehi, fils d’Allon, fils de Jedaja, fils de Simri, fils de Semahja;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Etaient ceux qui avaient été nommés pour être les principaux dans leurs familles, lorsque les maisons de leurs pères multiplièrent beaucoup.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Et ils partirent pour entrer dans Guédor, jusqu’à l’Orient de la vallée, cherchant des pâturages pour leurs troupeaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Et ils trouvèrent des pâturages gras et bons, et un pays spacieux, paisible, et fertile; car ceux qui avaient habité là auparavant étaient descendus de Cam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Ceux-ci donc qui ont été décrits par leurs noms, vinrent du temps d’Ezéchias Roi de Juda, et abattirent leurs tentes, et les habitations qui y furent trouvées, et les détruisirent à la façon de l’interdit, jusqu’à ce jour, et y habitèrent à leur place, car il y avait là des pâturages pour leurs brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Et cinq cents hommes d’entr’eux, c’est-à-dire, des enfants de Siméon, s’en allèrent en la montagne de Séhir, et ils avaient pour leurs chefs Pelatia, Néharia, Rephaia, et Huziël, enfants de Jishi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'Et ils frappèrent le reste des réchappés des Hamalécites, et ils ont habité là jusqu’à aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Or les enfants de Ruben, le premier-né d’Israël (car il était le premier-né; mais après qu’il eut souillé le lit de son père, son droit d’aînesse fut donné aux enfants de Joseph fils d’Israël; non cependant pour être mis le premier dans la généalogie selon le droit d’aînesse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Car Juda fut le plus puissant entre ses frères, et de lui sont sortis les Conducteurs; mais le droit d’aînesse fut donné à Joseph.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Les enfants, dis-je, de Ruben premier-né d’Israël, furent, Hénoc, Pallu, Hetsron, et Carmi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Les enfants de Joël furent Sémaia son fils, Gog son fils, Simhi son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'Mica son fils, Réaia son fils, Bahal son fils,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'Bééra son fils, qui fut transporté par Tiglat-Piletséer Roi des Assyriens; c’est lui qui était le principal chef des Rubénites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Et ses frères selon leurs familles, quand ils furent mis dans la généalogie selon leurs parentages, avaient pour Chefs Jehiël, et Zécaria.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Et Bélah fils de Hazaz, fils de Samah, fils de Johel, habitait depuis Haroher jusqu’à Necò et Bahal-méhon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Ensuite il habita du côté de l’Orient jusqu’à l’entrée du désert, depuis le fleuve d’Euphrate; car son bétail s’était multiplié au pays de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Et du temps de Saül ils firent la guerre contre les Hagaréniens, qui moururent par leurs mains, et ils habitèrent dans leurs tentes, en tout le pays qui regarde vers l’Orient de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Et les enfants de Gad habitèrent près d’eux, au pays de Basan, jusqu’à Salca.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Joël fut le premier Chef, et Saphan le second après lui, puis Jahnaï, puis Saphat en Basan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Et leurs frères selon la maison de leurs pères, furent sept, Micaël, Mesullam, Sébah, Joraï, Jahcan, Ziah, et Héber.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Ceux-ci furent les enfants d’Abihaïl fils de Huri, fils de Jaroah, fils de Galaad, fils de Micaël, fils de Jésisaï, fils de Jahdo, fils de Buz.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Ahi fils de Habdiël, fils de Guni, fut le Chef de la maison de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Et ils habitèrent en Galaad, et en Basan, et dans les villes de son ressort, et dans tous les faubourgs de Saron, selon leurs limites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Tous ceux-ci furent mis dans la généalogie du temps de Jotham Roi de Juda, et du temps de Jéroboam Roi d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Il y eut des enfants de Ruben, et de ceux de Gad, et de la demi-Tribu de Manassé, d’entre les vaillants hommes, portant le bouclier et l’épée, tirant de l’arc, et propres à la guerre, quarante-quatre mille sept cent soixante, marchant en bataille;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Qui firent la guerre contre les Hagaréniens, contre Jéthur, Naphis, et Nodab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Et ils furent aidés contr’eux, de sorte que les Hagaréniens, et tous ceux qui étaient avec eux, furent livrés entre leurs mains, parce qu’ils crièrent à Dieu quand ils combattaient, et il fut fléchi par leurs prières, à cause qu’ils avaient mis leur espérance en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Ainsi ils prirent leur bétail, consistant en cinquante mille chameaux, deux cent cinquante mille brebis, deux mille ânes, et cent mille personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Et il en tomba morts un fort grand nombre, parce que la bataille venait de Dieu; et ils habitèrent là en leur place, jusqu’au temps qu’ils furent transportés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Les enfants de la demi-Tribu de Manassé habitèrent aussi en ce pays-là, et s’étendirent depuis Basan jusqu’à Bahal-hermon et à Sénir, qui est la montagne de Hermon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Et ce sont ici les Chefs de la maison de leurs pères; Hépher, Jisehi, Eliël, Hazriël, Jérémie, Hodavia, et Jacdiël, hommes forts et vaillants, gens de réputation, et Chefs de la maison de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Mais ils péchèrent contre le Dieu de leurs pères, et paillardèrent après les dieux des peuples du pays, que l’Eternel avait détruits devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Et le Dieu d’Israël émut l’esprit de Pul Roi des Assyriens, et l’esprit de Tiglath-Pilhéser Roi des Assyriens, qui transporta les Rubénites, et les Gadites, et la demi-Tribu de Manassé, et les emmena à Chalach, à Chabor, à Hara, et au fleuve de Gozan, où ils sont demeurés jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Les enfants de Lévi furent, Guerson, Kéhath, et Mérari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Les enfants de Kéhath furent, Hamram, Jitshar, Hébron, et Huziël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Et les enfants d’Hamram, Aaron, Moïse, et Marie. Et les enfants d’Aaron, Nadab, Abihu, Eléazar, et Ithamar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eléazar engendra Phinées, et Phinées engendra Abisuah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Et Abisuah engendra Bukki, et Bukki engendra Huzi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Et Huzi engendra Zérahja, et Zérahja engendra Mérajoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Et Mérajoth engendra Amaria, et Amaria engendra Ahitub.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Et Ahitub engendra Tsadoc, et Tsadoc engendra Ahimahats.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Et Ahimahats engendra Hazaria, et Hazaria engendra Johanan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Et Johanan engendra Hazaria, qui exerça la sacrificature au Temple que Salomon bâtit à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Et Hazaria engendra Amaria, et Amaria engendra Ahitub.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Et Ahitub engendra Tsadoc, et Tsadoc engendra Sallum.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Et Sallum engendra Hilkija, et Hilkija engendra Hazaria.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Et Hazaria engendra Séraja, et Séraja engendra Jéhotsadak;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Et Jéhotsadak s’en alla, quand l’Eternel transporta Juda et Jérusalem par le moyen de Nébuchadnetsar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Les enfants de Lévi donc furent, Guerson, Kéhath, et Mérari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Et ce sont ici les noms des enfants de Guerson, Ribni, et Simhi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Les enfants de Kéhath furent, Hamram, Jitshar, Hébron, et Huziël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Les enfants de Mérari furent, Mahli, et Musi. Ce sont là les familles des Lévites, selon les maisons de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'De Guerson, Libni son fils, Jahath son fils, Zimna son fils,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'Joah son fils, Hiddo son fils, Zérah son fils, Jéhateraï son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Des enfants de Kéhath, Hamminadab son fils, Coré son fils, Assir son fils,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'Elkana son fils, Ebiasaph son fils, Assir son fils,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Tahath son fils, Uriël son fils, Huzija son fils, et Saül son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Les enfants d’Elkana furent, Hamasaï, puis Ahimoth,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Puis Elkana. Les enfants d’Elkana furent, Tsophaï son fils, Nahats son fils,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'Eliab son fils, Jéroham son fils, Elkana son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Quant aux enfants de Samuël fils d’Elkana, son fils aîné fut Vasni, puis Abija.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Les enfants de Mérari furent, Mahli, Libni son fils, Simhi son fils, Huza son fils,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'Simha son fils, Hagguija son fils, Hasaïa son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Or ce sont ici ceux que David établit pour maîtres de la musique de la maison de l’Eternel, depuis que l’Arche fut dans un lieu arrêté;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'Qui faisaient le service devant le pavillon du Tabernacle d’assignation en chantant; jusqu’à ce que Salomon eût bâti la maison de l’Eternel à Jérusalem; et qui continuèrent dans leur ministère selon l’ordonnance qui en fut faite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Ce sont, dis-je, ici ceux qui firent le service avec leurs fils. D’entre les enfants des Kéhathites, Héman le chantre, fils de Joël, fils de Samuël,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Fils d’Elkana, fils de Jéroham, fils d’Eliël, fils de Toah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Fils de Tsuph, fils d’Elkana, fils de Mahat, fils de Hamasaï,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'Fils d’Elkana, fils de Joël, fils de Hazaria, fils de Sophonie,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'Fils de Tahat, fils d’Assir, fils de Ebiasaph, fils de Coré,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'Fils de Jitshar, fils de Kéhath, fils de Lévi, fils d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Et son frère Asaph, qui se tenait à sa droite. Asaph était fils de Bérécia, fils de Simha,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'Fils de Micaël, fils de Bahaséja, fils de Malkija,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Fils d’Etni, fils de Zérah, fils de Hadaja,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Fils d’Ethan, fils de Zimma, fils de Simhi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Fils de Jahath, fils de Guerson, fils de Lévi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Et les enfants de Mérari leurs frères étaient à la main gauche; savoir Ethan, fils de Kisi, fils de Habdi, fils de Malluc,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Fils de Hasabia, fils d’Amatsia, fils de Hilkija,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Fils d’Amtsi, fils de Bani, fils de Semer,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Fils de Mahli, fils de Musi, fils de Mérari, fils de Lévi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Et leurs autres frères Lévites furent ordonnés pour tout le service du pavillon de la maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Mais Aaron et ses fils offraient les parfums sur l’autel de l’holocauste, et sur l’autel des parfums, pour tout ce qu’il fallait faire dans le lieu Très- saint, et pour faire propitiation pour Israël; comme Moïse, serviteur de Dieu, l’avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Or ce sont ici les enfants d’Aaron, Eléazar son fils, Phinées son fils, Abisuah son fils,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Bukki son fils, Huzi son fils, Zérahja son fils,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'Mérajoth son fils, Amaria son fils, Ahitub son fils,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Tsadoc son fils, Ahimahats son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Et ce sont ici leurs demeures, selon leurs châteaux, dans leurs contrées. Quant aux enfants d’Aaron, qui appartiennent à la famille des Kéhathites, lorsqu’on jeta le sort pour eux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'On leur donna Hébron au pays de Juda, et ses faubourgs tout autour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Mais on donna à Caleb, fils de Jéphunné, le territoire de la ville et ses villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'On donna donc aux enfants d’Aaron, Hébron d’entre les villes de refuge, et Libna, avec ses faubourgs, Jattir et Estemoah, avec leurs faubourgs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Hilen, avec ses faubourgs, Débir, avec ses faubourgs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Hasan, avec ses faubourgs, et Beth-sémes, avec ses faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Et de la Tribu de Benjamin, Guébah, avec ses faubourgs, Halemeth, avec ses faubourgs, et Hanathoth, avec ses faubourgs. Toutes leurs villes, selon leurs familles, étaient treize en nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'On donna au reste des enfants de Kéhath, par sort, dix villes des familles de la demi-Tribu, c’est-à-dire, de la demi-Tribu de Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Et aux enfants de Guerson, selon leurs familles, de la Tribu d’Issacar, de la Tribu d’Aser, de la Tribu de Nephthali, et de la Tribu de Manassé en Basan, treize villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Et aux enfants de Mérari, selon leurs familles, par sort, douze villes, de la Tribu de Ruben, de la Tribu de Gad, et de la Tribu de Zabulon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Ainsi les enfants d’Israël donnèrent aux Lévites ces villes-là, avec leurs faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'Et ils donnèrent, par sort de la Tribu des enfants de Juda, de la Tribu des enfants de Siméon, et de la Tribu des enfants de Benjamin, ces villes-là qui devaient être nommées par leurs noms.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Et pour ceux qui étaient des autres familles des enfants de Kéhath, il y eut pour leur contrée des villes de la Tribu d’Ephraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Car on leur donna entre les villes de refuge, Sichem, avec ses faubourgs, en la montagne d’Ephraïm, Guézer, avec ses faubourgs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'Jokméham, avec ses faubourgs; Beth-horon, avec ses faubourgs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'Ajalon, avec ses faubourgs, et Gath-rimmon, avec ses faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'Et de la demi-Tribu de Manassé, Haner, avec ses faubourgs, et Bilham, avec ses faubourgs, on donna, dis-je, ces villes-là aux familles qui restaient des enfants de Kéhath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Aux enfants de Guerson, on donna, des familles de la demi-Tribu de Manassé, Golan en Basan, avec ses faubourgs, et Hastaroth, avec ses faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'De la Tribu d’Issacar, Kédes avec ses faubourgs, Dobrath, avec ses faubourgs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'Ramoth, avec ses faubourgs, et Hanem, avec ses faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'Et de la Tribu d’Aser, Masal, avec ses faubourgs, Habdon, avec ses faubourgs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'Hukkok, avec ses faubourgs, et Rehod, avec ses faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'Et de la Tribu de Nephthali, Kédes en Galilée, avec ses faubourgs, Hammon, avec ses faubourgs, et Kirjathajim, avec ses faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Aux enfants de Mérari, qui étaient de reste d’entre les Lévites, on donna, de la Tribu de Zabulon, Rimmono, avec ses faubourgs, et Tabor, avec ses faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'Et au delà du Jourdain, vis-à-vis de Jérico, vers l’Orient du Jourdain, de la Tribu de Ruben, Betser au désert, avec ses faubourgs, Jathsa, avec ses faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'Kédémoth, avec ses faubourgs, et Méphahath, avec ses faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'Et de la Tribu de Gad, Ramoth en Galaad, avec ses faubourgs, Mahanajim, avec ses faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'Hesbon, avec ses faubourgs, et Jahzer, avec ses faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Et les enfants d’Issacar, furent ces quatre Tolah, Puah, Jasub et Simron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Et les enfants de Tolah furent Huzi, Réphaja, Jériel, Jahmaï, Jibsam, et Samuël; chefs des maisons de leurs pères qui étaient de Tolah; gens forts et vaillants en leurs générations. Le compte qui en fut fait aux jours de David fut de vingt-deux mille six cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Les enfants de Huzi, Jizrahia; et les enfants de Jizrahia, Micaël, Hobadia, Joël, et Jiscija, en tout cinq chefs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Et avec eux, suivant leurs générations, et selon les familles de leurs pères, il y eut en troupes de gens de guerre trente-six mille hommes; car ils eurent plusieurs femmes et plusieurs enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Et leurs frères selon toutes les familles d’Issacar, hommes forts et vaillants, étant comptés tous selon leur généalogie, furent quatre-vingt et sept mille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Les enfants de Benjamin furent trois, Bélah, Béker, et Jédihaël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Et les enfants de Bélah furent, Etsbon, Huzi, Huziël, Jérimoth, et Hiri; cinq chefs des familles des pères, hommes forts et vaillants; et leur dénombrement selon leur généalogie monta à vingt-deux mille et trente-quatre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Et les enfants de Béker furent, Zemira, Joas, Elihézer, Eliohenaï, Homri, Jérimoth, Abija, Hanathoth, et Halemeth; tous ceux-là furent enfants de Béker.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'Et leur dénombrement selon leur généalogie, selon leurs générations, et les chefs des familles de leurs pères, monta à vingt mille deux cents hommes, forts et vaillants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Et Jédihaël eut pour fils Bilhan. Et les enfants de Bilhan furent, Jéhus, Benjamin, Ehud, Kénahana, Zethan, Tarsis, et Ahisahar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Tous ceux-là furent enfants de Jédihaël, selon les chefs des familles des pères, forts et vaillants, dix-sept mille deux cents hommes, marchant en bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Suppim et Huppim furent enfants de Hir; et Husim fut fils d’Aher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Les enfants de Nephthali furent Jahtsiël, Guni, Jetser, et Sallum, petits- fils de Bilha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Les enfants de Manassé, Asriël, que la femme de Galaad enfanta. Or la concubine Syrienne de Manassé avait enfanté Makir père de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Et Makir prit une femme de la parenté de Huppim et de Suppim; car ils avaient une soeur nommée Mahaca. Et le nom d’un des petits-fils de Galaad fut Tselophcad; et Tselophcad n’eut que des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Et Mahaca, femme de Makir, enfanta un fils et l’appela Pérés, et le nom de son frère Serés, dont les enfants furent, Ulam et Rékem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Et le fils d’Ulam fut Bedan. Ce sont là les enfants de Galaad, fils de Makir, fils de Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Mais sa soeur Moleketh enfanta Ishud, Abihézer, et Mahla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Et les enfants de Semidah furent, Ahiam, Sekem, Likhi, et Aniham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Or les enfants d’Ephraïm furent, Sutelah; Béred son fils, Tahath son fils, Elhada son fils, Tahath son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'Zabad son fils, Sutelah son fils, et Hézer, et Elhad. Mais ceux de Gad, nés au pays, les mirent à mort, parce qu’ils étaient descendus pour prendre leur bétail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Et Ephraïm leur père en mena deuil plusieurs jours; et ses frères vinrent pour le consoler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Puis il vint vers sa femme, qui conçut, et enfanta un fils; et elle l’appela Bériha, parce qu’ il fut conçu dans l’affliction arrivée en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Et sa fille Séera, qui bâtit la basse et la haute Beth-horon, et Uzen-Séera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Son fils fut Repha, puis Reseph, et Telah son fils, Tahan son fils,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'Lahdan son fils, Hammihud son fils, Elisamah son fils,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'Nun son fils, Josué son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Leur possession et habitation fut Béthel, avec les villes de son ressort, et du côté d’Orient, Naharan; et du côté d’Occident, Guézer, avec les villes de son ressort, et Sichem, avec les villes de son ressort, jusqu’à Haza, avec les villes de son ressort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Et dans les lieux qui étaient aux enfants de Manassé, Bethséan, avec les villes de son ressort, Tahanac, avec les villes de son ressort, Méguiddo, avec les villes de son ressort, Dor, avec les villes de son ressort. Les enfants de Joseph, fils d’Israël, habitèrent dans ces villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Les enfants d’Aser furent, Jimna, Jisua, Isaï, Bériha, et Sérah leur soeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Et les enfants de Bériha furent, Héber, et Malkiël, qui fut père de Birzavith.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Et Héber engendra Japhlet, Somer, Hotham, et Suah leur soeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Les enfants de Japhlet furent Pasah, Bimhal, et Hasvath. Ce sont là les enfants de Japhlet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Et les enfants de Semer furent Ahi, Rohega, Jéhubba, et Aram.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Et les enfants d’Hélem son frère furent, Tsophah, Jimnah, Sellés, et Hamal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Les enfants de Tsophah furent Suah, Harnepher, Suhal, Béri, Jimra,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Betser, Hod, Samma, Silsa, Jithran, et Béera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Et les enfants de Jéther furent, Jephunné, Pispa, et Ara.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Et les enfants de Hulla furent, Arah, Hanniël, et Ritsia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Tous ceux-là furent enfants d’Aser, chefs des maisons des pères, gens d’élite, forts et vaillants, chefs des principaux, et leur dénombrement selon leur généalogie, qui fut fait quand on s’assemblait pour aller à la guerre, fut de vingt-six mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Or Benjamin engendra Bélah, qui fut son premier-né, Asbel le second, Achrah le troisième,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Noah le quatrième, et Rapha le cinquième.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Et les enfants de Bélah furent, Addar, Guéra, Abihud.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abisuah, Nahaman, Ahoah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Guéra, Séphuphan, et Huram.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Ce sont là les enfants d’Ehud. Ceux-là étaient chefs des pères des habitants de Guéba, qui furent transportés à Manahath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Et Nahaman, et Ahija, et Guéra, qui les transporta; et qui après engendra Huza et Ahihud.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Or Saharajim, après les avoir renvoyés, eut des enfants au pays de Moab, de Husim, et de Bahara ses femmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Et il engendra, de Hodés sa femme Jobab, Tsibia, Mesa, Malcam,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jehuts, Socja, et Mirma. Ce sont là ses enfants, chefs des pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Mais de Husim il engendra Abitub, Elpahal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Et les enfants d’Elpahal furent Héber, Misham, et Semed, qui bâtit Onò, et Lod, et les villes de son ressort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Et Bériha et Sémah furent chefs des pères des habitants d’Ajalon; ils mirent en fuite les habitants de Gath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Et Ahio, Sasak, Jérémoth,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Zébadia, Harad, Héder,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Micaël, Jispa, et Joha, enfants de Bériha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Et Zébadia, Mesullam, Hiski, Héber,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Jisméraï, Jizlia, et Jobab, enfants d’Elpahal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Et Jakim, Zicri, Zabdi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elihenaï, Tsillethaï, Eliël,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Hadaja, Beraja, et Simrath, enfants de Simhi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Et Jispan, Héber, Eliël,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Habdon, Zicri, Hanan,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Hananja, Hélam, Hantothija,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jiphdeja et Pénuël, enfants de Sasak.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Et Samseraï, Seharia, Hathalija,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaharésia, Elija, et Zicri, enfants de Jéroham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Ce sont là les chefs des pères selon les générations qui furent chefs; et ils habitèrent à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'Et le père de Gabaon habita à Gabaon, sa femme avait nom Mahaca.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Et son fils premier-né fut Habdon, puis Tsur, Kis, Bahal, Nadab,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Guédor, Ahio, et Zeker.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Et Mikloth engendra Siméa. Ils habitèrent aussi vis-à-vis de leurs frères à Jérusalem, avec leurs frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Et Ner engendra Kis, et Kis engendra Saül, et Saül engendra Jonathan, Malki- suah, Abinadab, et Esbahal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Le fils de Jonathan fut Mérib-bahal; et Mérib-bahal engendra Mica.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Et les enfants de Mica furent, Pithon, Mélec, Taréah, et Achaz.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Et Achaz engendra Jéhohadda; et Jéhohadda engendra Halemeth, Hasmaveth, et Zimri; et Zimri engendra Motsa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Et Motsa engendra Binha, qui eut pour fils Rapha, qui eut pour fils Elhasa, qui eut pour fils Atsel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Et Atsel eut six fils, dont les noms sont, Hazrikam, Bocru, Ismaël, Séharia, Hobadia, et Hanan; tous ceux-là furent enfants d’Atsel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Et les enfants de Hesek son frère furent, Ulam son premier-né, Jéhu le second, Eliphelet le troisième.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Et les enfants d’Ulam furent des hommes forts et vaillants, tirant bien de l’arc, et ils eurent beaucoup de fils et de petits-fils, jusqu’à cent cinquante; tous des enfants de Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Ainsi tous ceux d’Israël furent rangés par généalogie, et voilà, ils sont écrits au Livre des Rois d’Israël; et ceux de Juda furent transportés à Babylone à cause de leurs péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Mais ce sont ici les premiers qui habitèrent dans leurs possessions, et dans leurs villes, tant d’Israël, que des Sacrificateurs, des Lévites, et des Néthiniens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Et il demeura dans Jérusalem, des enfants de Juda, des enfants de Benjamin, et des enfants d’Ephraïm et de Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Huthaï fils d’Hammihud, fils de Homri, fils d’Imri, fils de Bani, des enfants de Pharez, fils de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Et des Silonites, Hasaïa le premier-né, et ses fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Et des enfants de Zara, Jéhuël, et ses frères, six cent quatre-vingt et dix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Et des enfants de Benjamin, Sallu fils de Mésullam, fils de Hodavia, fils de Hassenua.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'Et Jibnéja fils de Jéroham, et Ela fils de Huzi, fils de Micri; et Mésullam fils de Saphatia, fils de Réhuël, fils de Jibnija.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'Leurs frères, selon leurs générations, furent neuf cent cinquante-six. Tous ces hommes-là furent chefs des pères, selon la maison de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Et des Sacrificateurs, Jédahja, Jéhojarib, et Jakin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Et Hazaria fils de Hilkija, fils de Mésullam, fils de Tsadoc, fils de Mérajoth, fils d’Ahitub, conducteur de la maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'Et Hadaja fils de Jéroham, fils de Pashur, fils de Malkija; et Mahasaï, fils d’Hadiël, fils de Jahzéra, fils de Mésullam, fils de Mésillémith, fils d’Immer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'Et leurs frères chefs en la maison de leurs pères, mille sept cent soixante hommes, forts et vaillants, pour faire l’oeuvre du service de la maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Et les Lévites, Sémahja, fils de Hasub, fils de Hazrikam, fils de Hasabia, des enfants de Mérari,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Bakbakar, Hérès, et Galal; et Mattania fils de Mica, fils de Zicri, fils d’Asaph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Et Hobadia fils de Sémathia, fils de Galal, fils de Jéduthun; et Bérécia, fils d’Asa, fils d’Elkana, qui habita dans les bourgs des Nétophatiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Et quant aux portiers, Sallum, Hakkub, Talmon, et Ahiman, et leurs frères; mais Sallum était le chef;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Et il l’a été jusqu’à maintenant, ayant la charge de la porte du Roi vers l’Orient. Ceux-là furent portiers selon les familles des enfants de Lévi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Et Sallum fils de Coré, fils d’Ebiasaph, fils de Coré, et ses frères Corites, selon la maison de son père, avaient la charge de l’ouvrage du service, gardant les vaisseaux du Tabernacle, comme leurs pères en avaient gardé l’entrée au camp de l’Eternel,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Lorsque Phinées, fils d’Eléazar, fut établi chef sur eux en la présence de l’Eternel, qui était avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Et Zacharie fils de Mésélémia était le portier de l’entrée du Tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Ce sont là tous ceux qui furent choisis pour être les portiers des entrées, deux cent et douze; qui furent mis selon les familles par généalogie, selon leurs bourgs, comme David et Samuël le Voyant les avaient établis dans leur office.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Eux, dis-je, et leurs enfants furent établis sur les portes de la maison de l’Eternel, qui est la maison du Tabernacle, pour y faire la garde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Les portiers devaient être vers les quatre vents; savoir, vers l’Orient et l’Occident, vers le Septentrion et le Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Et leurs frères, qui étaient dans leurs bourgs, devaient venir avec eux de sept jours en sept jours, de temps en temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Car selon cet ordre, il y avait toujours quatre maîtres-portiers, Lévites, qui étaient même commis sur les chambres, et sur les trésors de la maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Et ils se tenaient la nuit tout autour de la maison de Dieu; car la garde leur en appartenait, et ils avaient la charge de l’ouvrir tous les matins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Il y en avait aussi quelques-uns d’entr’eux commis sur les vaisseaux du service; car on les portait dans le Temple, par compte, et on les en tirait par compte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Il y en avait aussi qui étaient commis sur les autres ustensiles, et sur tous les vaisseaux consacrés, et sur la fleur de farine, et sur le vin, et sur l’huile, et sur l’encens, et sur les choses aromatiques.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Mais ceux qui faisaient les parfums des choses aromatiques, étaient des enfants des Sacrificateurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Et Mattitia, d’entre les Lévites, premier-né de Sallum, Corite, avait la charge de ce qui se faisait avec les plaques.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Et il y en avait d’entre les enfants des Kéhathites, leurs frères, qui avaient la charge du pain de proposition pour l’apprêter chaque Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Et d’entr’eux il y avait aussi des chantres, chefs des pères des Lévites, qui demeuraient dans les chambres, sans avoir autre charge, parce qu’ils devaient être en fonction le jour et la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Ce sont là les chefs des pères des Lévites, selon leurs familles; ils furent chefs, et ils habitèrent à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'Or Jéhiël, le père de Gabaon, habita à Gabaon; et le nom de sa femme était Mahaca.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Et son fils premier-né Habdon, puis Tsur, Kis, Bahal, Ner, Nadab,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Guédor, Ahio, Zacharie, et Mikloth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Et Mikloth engendra Siméam; et ils habitèrent vis-à-vis de leurs frères à Jérusalem avec leurs frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Et Ner engendra Kis, et Kis engendra Saül, et Saül engendra Jonathan, Malki- suah, Abinadab et Esbahal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Et le fils de Jonathan fut Mérib-bahal; et Mérib-bahal engendra Mica.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Et les enfants de Mica furent, Pithon, Mélec, Tahréah, et Achaz.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Et Achaz engendra Jahra; et Jahra engendra Halemeth, Hazmaveth, et Zimri; et Zimri engendra Motsa,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Et Motsa engendra Binha, qui eut pour fils Réphaja, qui eut pour fils Elhasa, qui eut pour fils Atsel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Et Atsel eut six fils, dont les noms sont Hazrikam, Bocru, Ismaël, Séharia, Hobadia, et Hanan. Ce furent là les fils d’Atsel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Or les Philistins combattirent contre Israël, et ceux d’Israël s’enfuirent devant les Philistins, et tombèrent blessés à mort en la montagne de Guilboah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Et les Philistins poursuivirent et atteignirent Saül et ses fils, et tuèrent Jonathan, Abinadab et Malki-suah, les fils de Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Et le combat se renforça contre Saül, de sorte que ceux qui tiraient de l’arc le trouvèrent, et il eut peur de ces archers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Alors Saül dit à celui qui portait ses armes: Tire ton épée, et m’en transperce, de peur que ces incirconcis ne viennent, et ne fassent de moi selon leur volonté; mais celui qui portait ses armes ne le voulut point faire; parce qu’il craignait beaucoup. Saül donc prit son épée, et se jeta dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Alors celui qui portait les armes de Saül, ayant vu que Saül était mort, se jeta aussi sur son épée, et mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Ainsi mourut Saül, et ses trois fils; et tous ses gens moururent avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Et tous ceux d’Israël, qui étaient dans la vallée, ayant vu qu’ils s’en étaient fuis, et que Saül et ses fils étaient morts, abandonnèrent leurs villes, et s’enfuirent, de sorte que les Philistins y entrèrent, et y habitèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Or il arriva que dès le lendemain les Philistins vinrent pour dépouiller les morts, et ils trouvèrent Saül et ses fils étendus en la montagne de Guilboah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Et l’ayant dépouillé, ils lui ôtèrent la tête, et ses armes, et les envoyèrent au pays des Philistins tout à l’environ, pour en faire savoir les nouvelles à leurs dieux, et au peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Ils mirent ses armes au temple de leur dieu, et ils attachèrent sa tête en la maison de Dagon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Or tous ceux de Jabés de Galaad ayant appris tout ce que les Philistins avaient fait à Saül,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'Tous les vaillants hommes d’entr’eux se levèrent, et enlevèrent le corps de Saül, et les corps de ses fils, et les apportèrent à Jabés, et ils ensevelirent leurs os sous un chêne à Jabés, et jeûnèrent pendant sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Saül donc mourut pour le crime qu’il avait commis contre l’Eternel, en ce qu’il n’avait point gardé la parole de l’Eternel, et qu’il avait même consulté l’esprit de Python pour savoir ce qui lui devait arriver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'Il ne s’était point adressé à l’Eternel; c’est pourquoi l’Eternel le fit mourir, et transporta le Royaume à David fils d’Isaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Et tous ceux d’Israël s’assemblèrent auprès de David à Hébron, et lui dirent: Voici, nous sommes tes os, et ta chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Et même ci-devant, quand Saül était Roi, tu étais celui qui menais et qui ramenais Israël. Et l’Eternel ton Dieu t’a dit: Tu paîtras mon peuple d’Israël, et tu seras le Conducteur de mon peuple d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Tous les Anciens donc d’Israël vinrent vers le Roi à Hébron; et David traita alliance avec eux à Hébron devant l’Eternel; et ils oignirent David pour Roi sur Israël, suivant la parole que l’Eternel avait proférée par le moyen de Samuël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Or David et tous ceux d’Israël s’en allèrent à Jérusalem, qui est Jébus; car là étaient encore les Jébusiens qui habitaient au pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Et ceux qui habitaient à Jébus, dirent à David: Tu n’entreras point ici. Mais David prit la forteresse de Sion, qui est la Cité de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Car David avait dit: Quiconque aura le premier frappé les Jébusiens, sera Chef et Capitaine. Et Joab fils de Tséruiä monta le premier, et fut fait Chef.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Et David habita dans la forteresse; c’est pourquoi on l’appela la Cité de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Il bâtit aussi la ville tout alentour, depuis Millo jusqu’aux environs; mais Joab répara le reste de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Et David allait toujours en avançant et en croissant; car l’Eternel des armées était avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Ce sont ici les principaux des hommes forts que David avait, qui se portèrent vaillamment avec lui, et avec tout Israël, pour son Royaume, afin de le faire régner suivant la parole de l’Eternel touchant Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Ceux-ci donc sont du nombre des hommes forts que David avait; Jasobham fils de Hacmoni, Chef entre les trois principaux, qui lançant sa hallebarde contre trois cents hommes, les blessa à mort en une seule fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Après lui était Eléazar fils de Dodo Ahohite, qui fut un des trois hommes forts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Ce fut lui qui se trouva avec David à Pasdammim, lorsque les Philistins s’étaient assemblés pour combattre; or il y avait une partie d’un champ semée d’orge, et le peuple s’en était fui devant les Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Et eux s’arrêtèrent au milieu de cette partie du champ, et la garantirent, et battirent les Philistins. Ainsi l’Eternel accorda une grande délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Il en descendit encore trois d’entre les trente Capitaines près du rocher, vers David, en la caverne de Hadullam, lorsque l’armée des Philistins était campée dans la vallée des Réphaïms.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Et David était alors dans la forteresse, et la garnison des Philistins était en ce même temps-là à Bethléhem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Et David fit un souhait, et dit: Qui est-ce qui me ferait boire de l’eau du puits qui est à la porte de Bethléhem?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Alors ces trois hommes passèrent tout au travers du camp des Philistins, et puisèrent de l’eau du puits qui était à la porte de Bethléhem; et l’ayant apportée, la présentèrent à David, qui n’en voulut point boire, mais la répandit à l’honneur de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'Car il dit: A Dieu ne plaise que je fasse une telle chose! Boirais-je le sang de ces hommes qui ont fait un tel voyage au péril de leur vie; car ils m’ont apporté cette eau au péril de leur vie; ainsi il n’en voulut point boire. Ces trois vaillants hommes firent cette action-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Et Abisaï frère de Joab était Chef des trois, lequel lançant sa hallebarde contre trois cents hommes, les blessa à mort, et il fut célèbre entre les trois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Entre les trois il fut plus honoré que les deux autres, et il fut leur Chef; cependant il n’égala point ces trois autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Bénéja aussi fils de Jéhojadah, fils d’un vaillant homme de Kabtséël, avait fait de grands exploits. Il tua deux des plus puissants hommes de Moab; et il descendit et frappa un lion au milieu d’une fosse, en un jour de neige.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Il tua aussi un homme Egyptien qui était haut de cinq coudées. Cet Egyptien avait en sa main une hallebarde grosse comme une ensuble de tisserand; mais il descendit contre lui avec un bâton, et arracha la hallebarde de la main de l’Egyptien, et le tua de sa propre hallebarde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Bénéja fils de Jéhojadah fit ces choses-là, et fut célèbre entre ces trois vaillants hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Voilà, il était honoré plus que les trente; cependant il n’égala point ces trois-là; et David l’établit sur ses gens de commandement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Et les plus vaillants d’entre les gens de guerre furent, Hazaël, frère de Joab; et Elhanan fils de Dodo, de Bethléhem,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Sammoth Harorite, Helets Pelonien,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Hira fils de Hikkes Tékohite, Abihézer Hanathothite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibbécaï Husathite, Hilaï Ahohite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maharaï Nétophathite, Héled fils de Bahana Nétophathite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ithaï fils de Ribaï, de Guibha des enfants de Benjamin, Bénéja Pirhathonite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Huraï des vallées de Gahas, Abiël Harbathite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Hazmaveth Baharumite, Eliachba Sahalbonite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Des enfants de Hasen Guizonite, Jonathan fils de Sagué Hararite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Ahiam fils de Sacar Hararite, Eliphal fils d’Ur,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hépher Mékérathite, Ahija Pélonien,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hetsro de Carmel, Naharaï fils d’Ezbaï,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joël frère de Nathan, Mibhar fils de Hagri,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Tselek Hammonite, Naharaï Bérothite, qui portait les armes de Joab fils de Tséruiä,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Hira Jithrite, Gareb Jithrite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Urie Héthien, Zabad fils d’Ahlaï,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Hadina fils de Siza Rubénite, Chef des Rubénites, et trente avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanan fils de Mahaca, et Josaphat Mithnite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Huzija Hastérathite, Samah et Jéhiël fils de Hotham Harohérite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jédihaël fils de Simri, et Joha son frère, Titsite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliël Hammahavim, Jéribaï, et Josavia enfants d’Elnaham, et Jithma Moabite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliël, et Hobed, et Jasiël de Metsobaja.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Or ce sont ici ceux qui allèrent trouver David à Tsiklag, lorsqu’il y était encore enfermé à cause de Saül fils de Kis, et qui étaient des plus vaillants, pour donner du secours dans la guerre,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'Equipés d’arcs, se servant de la main droite et de la gauche à jeter des pierres, et à tirer des flèches avec l’arc. D’entre les parents de Saül, qui étaient de Benjamin,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Ahihézer le Chef, et Joas, enfants de Sémaha, qui était de Guibha, et Jéziël, et Pelet enfants de Hazmaveth, et Beraca, et Jéhu Hanathothite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Et Jismahja Gabaonite, vaillant entre les trente, et même plus que les trente, et Jérémie, Jahaziël, Johanan, et Jozabad Guédérothite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Elhuzaï, Jérimoth, Béhalia, Sémaria, et Séphatia Haruphien,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elkana, Jisija, Hazaréël, Johézer et Jasobham Corites,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Et Johéla et Zébadia, enfants de Jéroham de Guédor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Quelques-uns aussi des Gadites se retirèrent vers David, dans la forteresse au désert, hommes forts et vaillants, experts à la guerre, et maniant le bouclier et la lance. Leurs visages étaient comme des faces de lion, et ils semblaient des daims sur les montagnes, tant ils couraient légèrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Hézer le premier, Hobadia le second, Eliab le troisième,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Mismanna le quatrième, Jérémie le cinquième,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Hattaï le sixième; Eliël le septième,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Johanan le huitième, Elzabad le neuvième,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Jérémie le dixième, Macbannaï le onzième.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Ceux-là d’entre les enfants de Gad furent Capitaines de l’armée; le moindre avait la charge de cent hommes, et le plus distingué, de mille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Ce sont ceux qui passèrent le Jourdain au premier mois, au temps qu’il a accoutumé de se déborder sur tous ses rivages; et ils chassèrent ceux qui demeuraient dans les vallées, vers l’Orient et l’Occident.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Il vint aussi des enfants de Benjamin et de Juda vers David à la forteresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Et David sortit au devant d’eux et prenant la parole, il leur dit: Si vous êtes venus en paix vers moi pour m’aider, mon coeur vous sera uni; mais si c’est pour me trahir, et me livrer à mes ennemis, quoique je ne sois coupable d’aucune violence, que le Dieu de nos pères le voie, et qu’il en fasse la punition.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Et l’esprit revêtit Hamasaï un des principaux Capitaines, qui dit: Que la paix soit avec toi, ô David! qu’elle soit avec toi, fils d’Isaï! que la paix soit à ceux qui t’aident, puisque ton Dieu t’aide! Et David les reçut, et les établit entre les Capitaines de ses troupes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Il y en eut aussi de ceux de Manassé qui s’allèrent rendre à David, quand il vint avec les Philistins pour combattre contre Saül; mais ils ne leur donnèrent point de secours, parce que les Gouverneurs des Philistins, après en avoir délibéré entr’eux, le renvoyèrent, en disant: Il se tournera vers son Seigneur Saül, au péril de nos têtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Quand donc il retournait à Tsiklag, Hadna, Jozabad, Jédihaël, Micaël, Jozabad, Elihu, et Tsillethaï, Chefs des milliers qui étaient en Manassé, se tournèrent vers lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Et ils aidèrent David contre la troupe des Hamalécites, car ils étaient tous forts et vaillants, et ils furent faits Capitaines dans l’armée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Et même à toute heure il venait des gens vers David pour l’aider, de sorte qu’il eut une grande armée, comme une armée de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Or ce sont ici les dénombrements des hommes équipés pour la guerre, qui vinrent vers David à Hébron, afin de faire tomber sur lui le Royaume de Saül, suivant le commandement de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Des enfants de Juda, qui portaient le bouclier et la javeline, six mille huit cents, équipés pour la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Des enfants de Siméon, forts et vaillants pour la guerre, sept mille et cent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Des enfants de Lévi, quatre mille six cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Et Jéhojadah, conducteur de ceux d’Aaron et avec lui trois mille sept cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'Et Tsadoc, jeune homme fort et vaillant, et vingt et deux des principaux de la maison de son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'Des enfants de Benjamin, parents de Saül, trois mille; car jusqu’alors la plus grande partie d’entr’eux avait tâché de soutenir la maison de Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Des enfants d’Ephraïm vingt mille huit cents, forts et vaillants, et hommes de réputation dans la maison de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'De la demi-Tribu de Manassé dix-huit mille, qui furent nommés par leur nom pour aller établir David Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Des enfants d’Issacar, fort intelligents dans la connaissance des temps, pour savoir ce que devait faire Israël, deux cents de leurs Chefs, et tous leurs frères se conduisaient par leur avis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'De Zabulon, cinquante mille combattants, rangés en bataille avec toutes sortes d’armes, et gardant leur rang d’un coeur assuré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'De Nephthali, mille capitaines, et avec eux trente-sept mille, portant le bouclier et la hallebarde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'Des Danites, vingt-huit mille six cents, rangés en bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'D’Aser, quarante mille combattants, et gardant leur rang en bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'De ceux de delà le Jourdain, savoir des Rubénites, des Gadites, et de la demi-Tribu de Manassé, six-vingt mille, avec tous les instruments de guerre pour combattre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Tous ceux-ci, gens de guerre, rangés en bataille, vinrent tous de bon coeur à Hébron, pour établir David Roi sur tout Israël; et tout le reste d’Israël était aussi d’un même sentiment pour établir David Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Et ils furent là avec David, mangeant et buvant pendant trois jours; car leurs frères leur avaient préparé des vivres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Et même ceux qui étaient les plus proches d’eux jusqu’à Issacar, et Zabulon, et Nephthali, apportaient du pain sur des ânes et sur des chameaux, sur des mulets, et sur des boeufs, de la farine, des figues sèches, des raisins secs, du vin, et de l’huile, et ils amenaient des bœufs, et des brebis en abondance; car il y avait joie en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Or David demanda conseil aux chefs de milliers, et de centaines, et à tous les conducteurs du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Et il dit à toute l’assemblée d’Israël: Si vous l’approuvez, et que cela vienne de l’Eternel notre Dieu, envoyons partout vers nos autres frères qui sont dans toutes les contrées d’Israël, et avec lesquels sont les Sacrificateurs et les Lévites, dans leurs villes et dans leurs faubourgs, afin qu’ils s’assemblent vers nous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Et que nous ramenions auprès de nous l’Arche de notre Dieu; car nous ne l’avons pas recherchée aux jours de Saül.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Et toute l’assemblée répondit qu’on le fît ainsi; car la chose avait été trouvée bonne par tout le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'David donc assembla tout Israël, depuis Sihor, le torrent d’Egypte, jusqu’à l’entrée du pays de Hamath, pour ramener de Kirjath-jéharim l’Arche de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Et David monta avec tout Israël vers Bahala à Kirjath-jéharim, qui appartient à Juda, pour faire amener de là l’Arche de Dieu l’Eternel, qui habite entre les chérubins, le nom duquel est invoqué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Et ils mirent l’Arche de Dieu sur un chariot neuf, et l’emmenèrent de la maison d’Abinadab; et Huza et Ahio conduisaient le chariot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Et David et tout Israël jouaient en la présence de Dieu de toute leur force, des cantiques, sur des violons, des musettes, des tambours, des cymbales, et des trompettes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Et quand ils furent arrivés à l’aire de Kidon, Huza étendit sa main pour retenir l’Arche, parce que les boeufs avaient glissé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Et la colère de l’Eternel s’enflamma contre Huza, qui le frappa, parce qu’il avait étendu sa main contre l’Arche; et il mourut en la présence de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Et David fut affligé de ce que l’Eternel avait fait une brèche en la personne de Huza; et on a appelé jusqu’à aujourd’hui le nom de ce lieu-là, Pérets-Huza.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Et David eut peur de Dieu en ce jour-là, et il dit: Comment ferais-je entrer chez moi l’Arche de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'C’est pourquoi David ne la retira point chez lui, dans la Cité de David; mais il la fit détourner dans la maison d’Hobed-Edom Guittien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Et l’Arche de Dieu demeura trois mois avec la famille d’Hobed-Edom, dans sa maison; et l’Eternel bénit la maison d’Hobed-Edom, et tout ce qui lui appartenait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Et Hiram Roi de Tyr envoya des messagers à David, et du bois de cèdre, et des maçons, et des charpentiers, pour lui bâtir une maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Alors David connut que l’Eternel l’avait affermi Roi sur Israël, parce que son règne avait été fort élevé, pour l’amour de son peuple d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Et David prit encore des femmes à Jérusalem, et il engendra encore des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Et ce sont ici les noms des enfants qu’il eut à Jérusalem, Sammuah, Sobab, Nathan, Salomon,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Jibhar, Elisuah, Elpélet,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Nogah, Népheg, Japhiah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisamah, Béël-jadah, et Eliphelet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Or quand les Philistins eurent su que David avait été oint pour Roi sur tout Israël, ils montèrent tous pour chercher David; et David l’ayant appris, sortit au devant d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Et les Philistins vinrent, et se répandirent dans la vallée des Réphaïms.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Et David consulta Dieu, en disant: Monterai-je contre les Philistins, et les livreras-tu entre mes mains? Et l’Eternel lui répondit: Monte, et je les livrerai entre tes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Alors ils montèrent à Bahal-pératsim, et David les battit là; et il dit: Dieu a fait écouler mes ennemis par ma main, comme un débordement d’eaux; c’est pourquoi on nomma ce lieu-là Bahal-pératsim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Et ils laissèrent là leurs dieux; et David commanda qu’on les brûlât au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Et les Philistins se répandirent encore une autre fois dans cette même vallée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Et David consulta encore Dieu; et Dieu lui répondit: Tu ne monteras point vers eux, mais tu tournoieras autour d’eux, et tu iras contr’eux vis-à-vis des mûriers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Et sitôt que tu auras entendu aux sommets des mûriers un bruit comme de gens qui marchent, tu sortiras alors au combat; car Dieu sera sorti devant toi pour frapper le camp des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'David donc fit selon ce que Dieu lui avait commandé; et on frappa le camp des Philistins, depuis Gabaon jusqu’à Guézer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Ainsi la renommée de David se répandit par tous ces pays-là; et l’Eternel remplit de frayeur toutes ces nations-là, au seul nom de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Or David bâtit pour lui des maisons dans la Cité de David, et prépara un lieu pour l’Arche de Dieu; et lui tendit un tabernacle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Et David dit: L’Arche de Dieu ne doit être portée que par les Lévites; car l’Eternel les a choisis pour porter l’Arche de Dieu, et pour faire le service à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'David donc assembla tous ceux d’Israël à Jérusalem, pour amener l’Arche de l’Eternel dans le lieu qu’il lui avait préparé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'David assembla aussi les enfants d’Aaron, et les Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Des enfants de Kéhath, Uriël le Chef, et ses frères, six vingts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'Des enfants de Mérari, Hasaïa le Chef, et ses frères, deux cent et vingt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'Des enfants de Guersom, Joël le Chef, et ses frères, cent trente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Des enfants d’Elitsaphan, Sémahja le chef, et ses frères, deux cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Des enfants de Hébron, Eliël le Chef, et ses frères, quatre-vingts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Des enfants de Huziël, Hamminadab le Chef et ses frères, cent et douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'David donc appela Tsadoc et Abiathar les Sacrificateurs, et ces Lévites-là, savoir, Uriël, Hasaïa, Joël, Sémahja, Eliël, et Hamminadab;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'Et il leur dit: Vous qui êtes les Chefs des pères des Lévites, sanctifiez- vous, vous et vos frères; et transportez l’Arche de l’Eternel le Dieu d’Israël, au lieu que je lui ai préparé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Parce que vous n’y avez pas été la première fois, l’Eternel notre Dieu a fait une brèche entre nous; car nous ne l’avons pas recherché comme il est ordonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Les Sacrificateurs donc et les Lévites se sanctifièrent pour amener l’Arche de l’Eternel, le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Et les enfants des Lévites portèrent l’Arche de Dieu sur leurs épaules, avec les barres qu’ils avaient sur eux, comme Moïse l’avait commandé suivant la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Et David dit aux Chefs des Lévites, d’établir quelques-uns de leurs frères qui chantassent avec des instruments de musique, savoir des musettes, des violons, et des cymbales, et qui fissent retentir leur voix avec joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Les Lévites donc établirent Héman fils de Joël, et d’entre ses frères, Asaph fils de Bérécia; et des enfants de Mérari, qui étaient leurs frères, Ethan fils de Kusaïa;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'Et avec eux leurs frères pour être au second rang, Zacharie, Ben, Jahaziël, Sémiramoth, Jéhiël, Hunni, Eliab, Bénéja, Mahaséïa, Mattitia, et Eliphaléhu, Miknéïa, Hobed-Edom, et Jéhiël, portiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Et quant à Héman, Asaph, et Ethan chantres, ils sonnaient des cymbales d’airain, en faisant retentir leur voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Et Zacharie, Haziël, Sémiramoth, Jéhiël, Hunni, Eliab, Mahaséïa, et Bénéja jouaient de la musette, sur Halamoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Et Mattitia, Eliphaléhu, Miknéja, Hobed-Edom, Jéhiël, et Hazaria jouaient des violons sur l’octave, pour renforcer le ton.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Mais Kénaïa, le principal des Lévites avait la charge de faire porter l’Arche, enseignant comment il la fallait porter; car il était homme fort intelligent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Et Bérécia et Elkana, étaient portiers pour l’Arche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Et Sébania, Jéhosaphat, Nathanaël, Hamasaï, Zacharie, Bénéja, Elihézer, Sacrificateurs, sonnaient des trompettes devant l’Arche de Dieu, et Hobed-Edom et Jéhïa étaient portiers pour l’Arche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'David donc et les Anciens d’Israël, avec les Gouverneurs de milliers, marchaient, amenant avec joie l’Arche de l’alliance de l’Eternel, de la maison d’Hobed-Edom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Et selon que Dieu soulageait les Lévites qui portaient l’Arche de l’alliance de l’Eternel, on sacrifiait sept veaux et sept béliers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Et David était vêtu d’un éphod de fin lin; et tous les Lévites aussi qui portaient l’Arche, et les chantres; et Kénaïa, qui avait la principale charge de faire porter l’Arche, était avec les chantres; et David avait un éphod de lin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Ainsi tout Israël amena l’Arche de l’alliance de l’Eternel, avec de grands cris de joie, et au son du cor, des trompettes et des cymbales, faisant retentir leur voix avec des musettes et des violons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Mais il arriva, comme l’Arche de l’alliance de l’Eternel entrait dans la Cité de David, que Mical fille de Saül, regardant par la fenêtre, vit le Roi David sautant et jouant, et elle le méprisa dans son coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Ils amenèrent donc l’Arche de Dieu, et la posèrent dans le tabernacle que David lui avait tendu; et on offrit devant Dieu des holocaustes et des sacrifices de prospérités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Et quand David eut achevé d’offrir les holocaustes et les sacrifices de prospérités, il bénit le peuple au Nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Et il distribua à chacun, tant aux hommes qu’aux femmes, un pain, et une pièce de chair, et une bouteille de vin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Et il établit quelques-uns des Lévites devant l’Arche de l’Eternel, pour y faire le service, pour célébrer, remercier, et louer le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Asaph était le premier, et Zacharie le second, Jéhiël, Sémiramoth, Jéhiël, Mattitia, Eliab, Bénéja, Hobed-Edom, et Jéchiël, qui avaient des instruments de musique, savoir des musettes et des violons; et Asaph faisait retentir sa voix avec des cymbales.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Et Bénéja et Jahaziël Sacrificateurs étaient continuellement avec des trompettes devant l’Arche de l’alliance de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Et en ce même jour David remit entre les mains d’Asaph et de ses frères, les Psaumes suivants, pour commencer à célébrer l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'CELEBREZ l’Eternel, invoquez son Nom, faites connaître parmi les peuples ses exploits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Chantez lui, psalmodiez lui, parlez de toutes ses merveilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Glorifiez-vous du Nom de sa sainteté; que le coeur de ceux qui cherchent l’Eternel se réjouisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Recherchez l’Eternel et sa force, cherchez continuellement sa face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Souvenez-vous des merveilles qu’il a faites; de ses miracles, et des jugements de sa bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'La postérité d’Israël sont ses serviteurs; les enfants de Jacob sont ses');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Il est l’Eternel notre Dieu; ses jugements sont par toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Souvenez-vous toujours de son alliance, de la parole qu’il a prescrite en mille générations;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'Du traité qu’il a fait avec Abraham; et de son serment fait à Isaac;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Lequel il a confirmé à Jacob et à Israël, pour être une ordonnance et une alliance éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'En disant: Je te donnerai le pays de Canaan, pour le lot de ton héritage;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Encore que vous soyez un petit nombre de gens, et même que vous y séjourniez depuis peu de temps, comme étrangers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Car ils étaient errants de nation en nation, et d’un Royaume vers un autre peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Il n’a pas souffert qu’aucun les outrageât; même il a châtié les Rois pour l’amour d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Et il a dit: Ne touchez point à mes Oints, et ne faites point de mal à mes Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'TOUTE la terre, chantez à l’Eternel, prêchez chaque jour sa délivrance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Racontez sa gloire parmi les nations, et ses merveilles parmi tous les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Car l’Eternel est grand, et très-digne de louange, il est plus redoutable que tous les dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Et en effet tous les dieux des peuples sont des idoles; mais l’Eternel a fait les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'La Majesté et la magnificence marchent devant lui; la force et la joie sont dans le lieu où il habite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Familles des peuples, attribuez à l’Eternel, attribuez à l’Eternel gloire et force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Attribuez à l’Eternel la gloire due à son Nom; apportez l’oblation, et présentez-vous devant lui; prosternez-vous devant l’Eternel avec une sainte magnificence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Vous tous les habitants de la terre tremblez, tout étonnés pour la présence de sa face; car la terre habitable est affermie par lui, sans qu’elle soit ébranlée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Que les cieux se réjouissent, que la terre s’égaye, et qu’on dise parmi les nations: L’Eternel règne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Que la mer et tout ce qu’elle contient bruie; que les champs et tout ce qui est en eux se réjouissent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Alors les arbres de la forêt crieront de joie au devant de l’Eternel, parce qu’il vient juger la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Célébrez l’Eternel, car il est bon; parce que sa gratuité demeure à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Et dites: Ô Dieu! de notre salut, sauve-nous, et nous rassemble, et nous retire d’entre les nations, pour célébrer ton saint Nom, et pour nous glorifier en ta louange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Béni soit l’Eternel le Dieu d’Israël, depuis un siècle jusqu’à l’autre! Et tout le peuple dit: Amen; et on loua l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'On laissa donc là devant l’Arche de l’alliance de l’Eternel, Asaph et ses frères, pour faire le service continuellement, selon ce qu’il y avait à faire chaque jour devant l’Arche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'Et Hobed-Edom, et ses frères, au nombre de soixante-huit, Hobed-Edom, dis- je, fils de Jéduthun, et Hosa pour portiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Et on laissa Tsadoc le Sacrificateur, et ses frères Sacrificateurs, devant le pavillon de l’Eternel, dans le haut lieu qui était à Gabaon,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'Pour offrir des holocaustes à l’Eternel continuellement sur l’autel de l’holocauste, le matin, et le soir, et pour faire toutes les choses qui sont écrites dans la Loi de l’Eternel, lesquelles il avait commandées à Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Et avec eux Héman et Jéduthun, et les autres qui furent choisis et marqués par leur nom, pour célébrer l’Eternel, parce que sa gratuité demeure éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Et Héman et Jéduthun étaient avec ceux-là; il y avait aussi des trompettes, et des cymbales pour ceux qui faisaient retentir leur voix, et des instruments pour chanter les cantiques de Dieu; et les fils de Jéduthun étaient portiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Puis tout le peuple s’en alla chacun en sa maison, et David aussi s’en retourna pour bénir sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Or il arriva après que David fut tranquille en sa maison, qu’il dit à Nathan le Prophète: Voici, je demeure dans une maison de cèdres, et l’Arche de l’alliance de l’Eternel n’est que sous des courtines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Et Nathan dit à David: Fais tout ce qui est en ton coeur; car Dieu est avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Mais il arriva cette nuit-là que la parole de Dieu fut adressée à Nathan, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Va, et dis à David mon serviteur: Ainsi a dit l’Eternel: Tu ne me bâtiras point de maison pour y habiter;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Puisque je n’ai point habité dans aucune maison depuis le temps que j’ai fait monter les enfants d’Israël hors d’Egypte jusqu’à ce jour; mais j’ai été de tabernacle en tabernacle, et de pavillon en pavillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Partout où i’ai marché avec tout Israël, en ai-je parlé à un seul des Juges d’Israël, auxquels j’ai commandé de paître mon peuple, et leur ai-je dit: Pourquoi ne m’avez-vous point bâti une maison de cèdres?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Maintenant donc tu diras ainsi à David mon serviteur: Ainsi a dit l’Eternel des armées: Je t’ai pris d’une cabane, d’après les brebis, afin que tu fusses le conducteur de mon peuple d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'Et j’ai été avec toi partout où tu as marché, et j’ai exterminé de devant toi tous tes ennemis, et je t’ai fait un nom tel qu’est le nom des Grands qui sont sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Et j’établirai un lieu à mon peuple d’Israël, et je le planterai, et il habitera chez soi, et ne sera plus agité; les fils d’iniquité ne le mineront plus comme ils ont fait auparavant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'Savoir; depuis les jours que j’ai ordonné des Juges sur mon peuple d’Israël, que j’ai abaissé tous tes ennemis, et que je t’ai fait entendre que l’Eternel te bâtirait une maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Il arrivera donc que quand tes jours seront accomplis pour t’en aller avec tes pères, je ferai lever ta postérité après toi, qui sera un de tes fils, et j’établirai son règne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Il me bâtira une maison, et j’affermirai son trône à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Je lui serai père, et il me sera fils; et je ne retirerai point de lui ma gratuité, comme je l’ai retirée de celui qui a été avant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Mais je l’établirai dans ma maison et dans mon Royaume à jamais, et son trône sera affermi pour toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Nathan récita à David toutes ces paroles, et toute cette vision.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Alors le Roi David entra, et se tint devant l’Eternel, et dit: Ô Eternel Dieu! Qui suis-je, et quelle est ma maison, que tu m’aies fait parvenir au point où je suis?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Mais cela t’a semblé être peu de chose, ô Dieu! et tu as parlé de la maison de ton serviteur pour le temps à venir, et tu as pourvu à moi; l’excellence de l’homme est selon ce qu’il est, ô Eternel Dieu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Que te pourrait dire encore David de l’honneur que tu fais à ton serviteur? car tu connais ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Ô Eternel! pour l’amour de ton serviteur, et selon ton coeur, tu as fait toutes ces grandes choses, pour faire connaître toutes ces grandeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Ô Eternel! il n’y en a point de semblable à toi, et il n’y a point d’autre Dieu que toi selon tout ce que nous avons entendu de nos oreilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Et qui est comme ton peuple d’Israël, la seule nation sur la terre que Dieu lui-même est venu racheter pour soi, afin qu’elle soit son peuple, et pour t’acquérir un renom de choses grandes et redoutables, en chassant les nations de devant ton peuple, que tu t’es racheté d’Egypte?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Et tu t’es établi ton peuple d’Israël pour peuple à jamais; et toi, ô Eternel! tu leur as été Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Maintenant donc, ô Eternel! que la parole, que tu as prononcée touchant ton serviteur et sa maison, soit ferme à jamais, et fais comme tu en as parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Et que ton Nom demeure ferme, et soit magnifié à jamais, de sorte qu’on dise: L’Eternel des armées, le Dieu d’Israël est Dieu à Israël; et que la maison de David ton serviteur soit affermie devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Car tu as fait, ô mon Dieu! entendre à ton serviteur que tu lui bâtirais une maison; c’est pourquoi ton serviteur a pris la hardiesse de te faire cette prière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Or maintenant, ô Eternel! tu es Dieu, et tu as parlé de ce bien à ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Veuille donc maintenant bénir la maison de ton serviteur, afin qu’elle soit éternellement devant toi; car, tu l’as bénie, ô Eternel! et elle sera bénie à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Et il arriva que David battit les Philistins, et les abaissa, et prit Gath, et les villes de son ressort sur les Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Il battit aussi les Moabites, et les Moabites furent asservis, et faits tributaires à David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'David battit aussi Hadarhézer Roi de Tsoba vers Hamath, comme il s’en allait pour établir ses limites sur le fleuve d’Euphrate.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Et David lui prit mille chariots, et sept mille hommes de cheval, et vingt mille hommes de pied; et il coupa les jarrets des chevaux de tous les chariots, mais il en réserva cent chariots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Or les Syriens de Damas étaient venus pour donner du secours à Hadarhézer Roi de Tsoba; et David battit vingt et deux mille Syriens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Puis David mit garnison en Syrie de Damas, et ces Syriens-là furent serviteurs et tributaires à David; et l’Eternel gardait David partout où il allait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Et David prit les boucliers d’or qui étaient aux serviteurs de Hadarhézer, et les apporta à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Il emporta aussi de Tibhath, et de Cun, villes de Hadarhézer, une grande quantité d’airain, dont Salomon fit la mer d’airain, et les colonnes, et les vaisseaux d’airain;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Or Tohu Roi de Kamath apprit que David avait défait toute l’armée de Hadarhézer Roi de Tsoba.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'Et il envoya Hadoram son fils vers le Roi David pour le saluer, et le féliciter de ce qu’il avait combattu Hadarhézer, et qu’il l’avait défait; car Hadarhézer était dans une guerre continuelle contre Tohu; et quant à tous les vaisseaux d’or, et d’argent, et d’airain,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Le Roi David les consacra aussi à l’Eternel, avec l’argent et l’or qu’il avait emporté de toutes les nations, savoir, d’Edom, de Moab, des enfants de Hammon, des Philistins, et des Hamalécites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Et Abisaï fils de Tséruiä battit dix-huit mille Iduméens dans la vallée du sel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'Et mit garnison dans l’Idumée, et tous les Iduméens furent asservis à David; et l’Eternel gardait David partout où il allait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Ainsi David régna sur tout Israël, rendant jugement et justice à tout son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Et Joab fils de Tséruiä avait la charge de l’armée, et Jéhosaphat fils d’Ahilud était commis sur les Registres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Et Tsadoc, fils d’Ahitub, et Abimélec, fils d’Abiathar, étaient les Sacrificateurs; et Sausa était le Secrétaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Et Bénéja fils de Jéhojadah était sur les Kéréthiens et les Péléthiens; mais les fils de David étaient les premiers auprès du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Or il arriva après cela que Nahas Roi des enfants de Hammon mourut, et son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Et David dit: J’userai de gratuité envers Hanun, fils de Nahas; car son père a usé de gratuité envers moi. Ainsi David envoya des messagers pour le consoler sur la mort de son père; et les serviteurs de David vinrent au pays des enfants de Hammon vers Hanun pour le consoler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Mais les principaux d’entre les enfants de Hammon dirent à Hanun: Penses-tu que ce soit pour honorer ton père que David t’a envoyé des consolateurs? n’est-ce pas pour examiner exactement et épier le pays, afin de le détruire, que ses serviteurs sont venus vers toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Hanun donc prit les serviteurs de David, et les fit raser, et fit couper leurs habits par le milieu jusqu’aux hanches, puis il les renvoya.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Et ils s’en allèrent, et le firent savoir par le moyen de quelques personnes à David, qui envoya au devant d’eux; car ces hommes-là étaient fort confus. Et le Roi leur manda: Demeurez à Jérico jusqu’à ce que votre barbe soit recrue; et alors vous retournerez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Or les enfants de Hammon voyant qu’ils s’étaient mis en mauvaise odeur auprès de David, Hanun et eux envoyèrent mille talents d’argent, pour prendre à leurs dépens des chariots et des gens de cheval de Mésopotamie, et de Syrie, de Mahaca, et de Tsoba.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Et ils levèrent à leurs frais pour eux trente-deux mille hommes, et des chariots, et le Roi de Mahaca avec son peuple qui vinrent, et se campèrent devant Médeba. Les Hammonites aussi s’assemblèrent de leurs villes, et vinrent pour combattre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Ce que David ayant appris, il envoya Joab, et ceux de toute l’armée qui étaient les plus vaillants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Et les enfants de Hammon sortirent, et rangèrent leur armée en bataille à l’entrée de la ville, et les Rois qui étaient venus, étaient à part dans la campagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Et Joab voyant que l’armée était tournée contre lui, devant et derrière, prit de tous les gens d’élite d’Israël, et les rangea contre les Syriens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Et il donna la conduite du reste du peuple à Abisaï son frère; et on les rangea contre les enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Et Joab lui dit: Si les Syriens sont plus forts que moi, tu viendras me délivrer; et si les enfants de Hammon sont plus forts que toi, je te délivrerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Sois vaillant, et portons-nous vaillamment pour notre peuple, et pour les villes de notre Dieu; et que l’Eternel fasse ce qui lui semblera bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Alors Joab et le peuple qui était avec lui s’approchèrent pour donner bataille aux Syriens, qui s’enfuirent de devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Et les enfants de Hammon voyant que les Syriens s’en étaient fuis, eux aussi s’enfuirent de devant Abisaï frère de Joab, et rentrèrent dans la ville; et Joab revint à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Mais les Syriens, qui avaient été battus par ceux d’Israël, envoyèrent des messagers, et firent venir les Syriens qui étaient au delà du fleuve; et Sophach capitaine de l’armée de Hadarhézer les conduisait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Ce qui ayant été rapporté à David, il assembla tout Israël, et passa le Jourdain, et alla au devant d’eux, et se rangea en bataille contr’eux. David donc rangea la bataille contre les Syriens, et ils combattirent contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Mais les Syriens s’enfuirent de devant Israël; et David défit sept mille chariots des Syriens, et quarante mille hommes de pied, et il tua Sophach le Chef de l’armée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Alors les serviteurs de Hadarhézer voyant qu’ils avaient été battus par ceux d’Israël, firent la paix avec David, et lui furent asservis; et les Syriens ne voulurent plus secourir les enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Or il arriva l’armée suivante, au temps que les Rois font leur sortie, que Joab conduisit le gros de l’armée, et ravagea le pays des enfants de Hammon; puis il alla assiéger Rabba, tandis que David demeurait à Jérusalem; et Joab battit Rabba, et la détruisit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Et David prit la couronne de dessus la tête de leur Roi, et il trouva qu’elle pesait un talent d’or, et il y avait des pierres précieuses; et on la mit sur la tête de David, qui emmena un fort grand butin de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Il emmena aussi le peuple qui y était, et les scia avec des scies, et avec des herses de fer et de scies. David traita de la sorte toutes les villes des enfants de Hammon; puis il s’en retourna avec tout le peuple à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Il arriva après cela que la guerre continua à Guézer contre les Philistins; et alors Sibbecaï le Husathite frappa Sippaï, qui était des enfants de Rapha, et ils furent abaissés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Il y eut encore une autre guerre contre les Philistins, dans laquelle Elhanan fils de Jahir frappa Lahmi, frère de Goliath Guittien, qui avait une hallebarde dont la hampe était comme l’ensuble d’un tisserand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Il y eut encore une autre guerre à Gath, où se trouva un homme de grande stature, qui avait six doigts à chaque main, et six orteils à chaque pied, de sorte qu’il en avait en tout vingt-quatre; et il était aussi de la race de Rapha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Et il défia Israël; mais Jonathan, fils de Simha frère de David, le tua.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Ceux-là naquirent à Gath; ils étaient de la race de Rapha, et ils moururent par les mains de David, et par les mains de ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Mais Satan s’éleva contre Israël, et incita David à faire le dénombrement d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Et David dit à Joab et aux principaux du peuple: Allez et dénombrez Israël, depuis Béer-sebah jusqu’à Dan, et rapportez-le moi, afin que j’en sache le nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Mais Joab répondit: Que l’Eternel veuille augmenter son peuple cent fois autant qu’il est, ô Roi mon Seigneur! tous ne sont-ils pas serviteurs de mon Seigneur? Pourquoi mon Seigneur cherche-t-il cela? et pourquoi cela serait- il imputé comme un crime à Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Mais la parole du Roi l’emporta sur Joab; et Joab partit, et alla par tout Israël; puis il revint à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Et Joab donna à David le rôle du dénombrement du peuple, et il se trouva de tout Israël onze cent mille hommes tirant l’épée, et de Juda, quatre cent soixante et dix mille hommes, tirant l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Bien qu’il n’eût pas compté entr’eux Lévi ni Benjamin, parce que Joab exécutait la parole du Roi à contre-coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Or cette chose déplut à Dieu, c’est pourquoi il frappa Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Et David dit à Dieu: J’ai commis un très-grand péché d’avoir fait une telle chose; je te prie pardonne maintenant l’iniquité de ton serviteur, car j’ai agi très-follement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Et l’Eternel parla à Gad, le Voyant de David, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Va, parle à David, et lui dis: Ainsi a dit l’Eternel, je te propose trois choses; choisis l’une d’elles, afin que je te la fasse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Et Gad vint à David, et lui dit: Ainsi a dit l’Eternel:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Choisis ou la famine durant l’espace de trois ans; ou d’être consumé, durant trois mois, étant poursuivi de tes ennemis, en sorte que l’épée de tes ennemis t’atteigne; ou que l’épée de l’Eternel, c’est-à-dire, la mortalité, soit durant trois jours sur le pays, et que l’Ange de l’Eternel fasse le dégât dans toutes les contrées d’Israël. Maintenant donc regarde ce que j’aurai à répondre à celui qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Alors David répondit à Gad: Je suis dans une très-grande angoisse; que je tombe, je te prie, entre les mains de l’Eternel, parce que ses compassions sont en très grand nombre; mais que je ne tombe point entre les mains des hommes.!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'L’Eternel envoya donc la mortalité sur Israël; et il tomba soixante et dix mille hommes d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Dieu envoya aussi l’Ange à Jérusalem pour y faire le dégât; et comme il faisait le dégât, l’Eternel regarda, et se repentit de ce mal; et il dit à l’Ange qui faisait le dégât: C’est assez; retire à présent ta main. Et l’Ange de l’Eternel était auprès de l’aire d’Ornan Jébusien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Or David élevant ses yeux vit l’Ange de l’Eternel qui était entre la terre et le ciel, ayant dans sa main son épée nue, tournée contre Jérusalem. Et David et les Anciens couverts de sacs, tombèrent sur leurs faces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Et David dit à Dieu: N’est-ce pas moi qui ai commandé qu’on fit le dénombrement du peuple? c’est donc moi qui ai péché et qui ai très-mal agi; mais ces brebis qu’ont-elles fait? Eternel mon Dieu! je te prie que ta main soit contre moi, et contre la maison de mon père, mais qu’elle ne soit pas contre ton peuple, pour le détruire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Alors l’Ange de l’Eternel commanda à Gad de dire à David, qu’il montât pour dresser un autel à l’Eternel, dans l’aire d’Ornan Jébusien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'David donc monta selon la parole que Gad lui avait dite au nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Et Ornan s’étant retourné, et ayant vu l’Ange, se tenait caché avec ses quatre fils. Or Ornan foulait du blé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Et David vint jusqu’à Ornan; et Ornan regarda, et ayant vu David, il sortit de l’aire, et se prosterna devant lui, le visage en terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Et David dit à Ornan: Donne-moi la place de cette aire, et j’y bâtirai un autel à l’Eternel; donne-la-moi pour le prix qu’elle vaut, afin que cette plaie soit arrêtée de dessus le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Et Ornan dit à David: Prends-la, et que le Roi mon Seigneur fasse tout ce qui lui semblera bon. Voici, je donne ces boeufs pour les holocaustes, et ces instruments à fouler du blé, au lieu de bois, et ce blé pour le gâteau; je donne toutes ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Mais le Roi David lui répondit: Non; mais certainement j’achèterai tout cela au prix qu’il vaut; car je ne présenterai point à l’Eternel ce qui est à toi, et je n’offrirai point un holocauste d’une chose que j’aie eue pour rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'David donna donc à Ornan pour cette place, six cents sicles d’or de poids.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Puis il bâtit là un autel à l’Eternel, et il offrit des holocaustes, et des sacrifices de prospérités, et il invoqua l’Eternel, qui l’exauça par le feu envoyé des cieux sur l’autel de l’holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Alors l’Eternel commanda à l’Ange; et l’Ange remit son épée dans son fourreau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'En ce temps-là David voyant que l’Eternel l’avait exaucé dans l’aire d’Ornan Jébusien, y sacrifia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Or le pavillon de l’Eternel que Moïse avait fait au désert, et l’autel des holocaustes étaient en ce temps-là dans le haut lieu de Gabaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Mais David ne put point aller devant cet autel pour invoquer Dieu, parce qu’il avait été troublé à cause de l’épée de l’Ange de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Et David dit: C’est ici la maison de l’Eternel Dieu, et c’est ici l’autel pour les holocaustes d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Et David commanda qu’on assemblât les étrangers qui étaient au pays d’Israël, et il prit d’entr’eux des maçons pour tailler des pierres de taille, afin d’en bâtir la maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'David assembla aussi du fer en abondance, afin d’en faire des clous pour les linteaux des portes, et pour les assemblages; et une si grande quantité d’airain qu’il était sans poids;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'Et du bois de cèdre sans nombre; parce que les Sidoniens et les Tyriens amenaient à David du bois de cèdre en abondance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Car David dit: Salomon mon fils est jeune et délicat, et la maison qu’il faut bâtir à l’Eternel doit être magnifique en excellence, en réputation, et en gloire, dans tous les pays; je lui préparerai donc maintenant de quoi la bâtir. Ainsi David prépara, avant sa mort, ces choses en abondance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Puis il appela Salomon son fils, et lui commanda de bâtir une maison à l’Eternel le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'David donc dit à Salomon: Mon fils, j’ai désiré de bâtir une maison au Nom de l’Eternel mon Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Mais la parole de l’Eternel m’a été adressée, en disant: Tu as répandu beaucoup de sang, et tu as fait de grandes guerres; tu ne bâtiras point de maison à mon Nom, parce que tu as répandu beaucoup de sang sur la terre devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Voici, il va te naître un fils, qui sera homme de paix; et je le rendrai tranquille par rapport à tous ses ennemis tout autour, c’est pourquoi son nom sera Salomon. Et en son temps je donnerai la paix et le repos à Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Ce sera lui qui bâtira une maison à mon Nom; et il me sera fils, et je lui serai père; et j’affermirai le trône de son règne sur Israël, à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Maintenant donc, mon fils! l’Eternel sera avec toi, et tu prospéreras, et tu bâtiras la maison de l’Eternel ton Dieu, ainsi qu’il a parlé de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Seulement, que l’Eternel te donne de la sagesse et de l’intelligence, et qu’il t’instruise touchant le gouvernement d’Israël, et comment tu dois garder la Loi de l’Eternel ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Et tu prospéreras si tu prends garde à faire les statuts et les ordonnances que l’Eternel a prescrites à Moïse pour Israël. Fortifie-toi et prends courage; ne crains point, et ne t’effraie de rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Voici, selon ma petitesse j’ai préparé pour la maison de l’Eternel cent mille talents d’or, et un million de talents d’argent. Quant à l’airain et au fer, il est sans poids, car il est en grande abondance. J’ai aussi préparé le bois et les pierres; et tu y ajouteras ce qu’il faudra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Tu as avec toi beaucoup d’ouvriers, de maçons, de tailleurs de pierres, de charpentiers, et de toute sorte de gens experts en tout ouvrage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Il y a de l’or et de l’argent, de l’airain et du fer sans nombre; applique- toi donc à la faire, et l’Eternel sera avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'David commanda aussi à tous les principaux d’Israël d’aider Salomon son fils; et il leur dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'L’Eternel votre Dieu n’est-il pas avec vous, et ne vous a-t-il pas donné du repos de tous côtés? car il a livré entre mes mains les habitants du pays, et le pays a été soumis devant l’Eternel, et devant son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Maintenant donc appliquez vos coeurs et vos âmes à rechercher l’Eternel votre Dieu, et mettez-vous à bâtir le Sanctuaire de l’Eternel Dieu, pour amener l’Arche de l’alliance de l’Eternel, et les saints vaisseaux de Dieu dans la maison qui doit être bâtie au Nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Or David étant vieux et rassasié de jours, établit Salomon son fils pour Roi sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Et il assembla tous les principaux d’Israël, et les Sacrificateurs, et les Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Et on fit le dénombrement des Lévites, depuis l’âge de trente ans, et au dessus; et les mâles d’entr’eux étant comptés, chacun par tête, il y eut trente-huit mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Il y en eut d’entre eux vingt et quatre mille qui vaquaient ordinairement à l’oeuvre de la maison de l’Eternel, et six mille qui étaient prévôts et juges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'Et quatre mille portiers, et quatre autres mille qui louaient l’Eternel avec des instruments, que j’ai faits, dit David, pour le louer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'David les distribua aussi selon le partage qui avait été fait des enfants de Lévi, savoir Guerson, Kéhath, et Mérari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Des Guersonites il y eut, Lahdan, et Simhi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Les enfants de Lahdan furent ces trois, Jéhiël le premier, puis Zetham, puis Joël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Les enfants de Simhi furent ces trois, Sélomith, Haziël, et Haran. Ce sont là les Chefs des pères de la famille, de Lahdan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Et les enfants de Simhi furent, Jahath, Ziza, Jéhus, et Bériha; ce sont là les quatre enfants de Simhi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Et Jahath était le premier, et Ziza le second; mais Jéhus et Bériha n’eurent pas beaucoup d’enfants, c’est pourquoi ils furent comptés pour un seul Chef de famille dans la maison de leur père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Des enfants de Kéhath il y eut, Hamram, Jitshar, Hébron, et Huziël, en tout quatre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Les enfants d’Hamram furent, Aaron et Moïse; et Aaron fut séparé lui et ses fils à toujours, pour sanctifier le lieu Très-saint, pour faire des encensements en la présence de l’Eternel, pour le servir, et pour bénir en son Nom à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Et quant à Moïse, homme de Dieu, ses enfants devaient être censés de la Tribu de Lévi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Les enfants de Moïse furent Guersom et Elihézer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Des enfants de Guersom, Sébuël le premier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Et quant aux enfants d’Elihézer, Réhabia fut le premier; et Elihézer n’eut point d’autres enfants, mais les enfants de Réhabia multiplièrent merveilleusement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Des enfants de Jitshar, Sélomith était le premier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Les enfants de Hébron furent Jérija le premier, Amaria le second, Jahaziël le troisième, Jékamham le quatrième.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Les enfants de Huziël furent, Mica le premier, Jisija le second.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Des enfants de Mérari il y eut, Mahli et Musi. Les enfants de Mahli furent, Eléazar et Kis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Et Eléazar mourut, et n’eut point de fils, mais des filles; et les fils de Kis leurs frères les prirent pour femmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Les enfants de Musi furent, Mahli, Héder, et Jérémoth, eux trois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Ce sont là les enfants de Lévi selon les maisons de leurs pères, Chefs des pères, selon leurs dénombrements qui furent faits selon le nombre de leurs noms, étant comptés chacun par tête, et ils faisaient la fonction pour le service de la maison de l’Eternel, depuis l’âge de vingt ans, et au dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Car David dit: L’Eternel Dieu d’Israël a donné du repos à son peuple, et il a établi sa demeure dans Jérusalem pour toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Et même quant aux Lévites, ils n’avaient plus à porter le Tabernacle, ni tous les ustensiles pour son service.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'C’est pourquoi dans les derniers Registres de David, les enfants de Lévi furent dénombrés depuis l’âge de vingt ans, et au dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Car leur charge était d’assister les enfants d’Aaron pour le service de la maison de l’Eternel, étant établis sur le parvis, et sur les chambres, et pour nettoyer toutes les choses saintes, et pour l’oeuvre du service de la maison de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'Et pour les pains de proposition, pour la fleur de farine dont devait être fait le gâteau, et pour les beignets sans levain, pour tout ce qui se cuit sur la plaque, pour tout ce qui est rissolé, et pour la petite et grande mesure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'Et pour se présenter tous les matins et tous les soirs, afin de célébrer et louer l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'Et quand on offrait tous les holocaustes qu’il fallait offrir à l’Eternel les jours de Sabbat aux nouvelles lunes, et aux fêtes solennelles, continuellement devant l’Eternel, selon le nombre qui en avait été ordonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'Et afin qu’ils fissent la garde du Tabernacle d’assignation, et la garde du Sanctuaire, et la garde des fils d’Aaron leurs frères, pour le service de la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Et quant aux enfants d’Aaron, ce sont ici leurs départements. Les enfants d’Aaron furent, Nadab, Abihu, Eléazar et Ithamar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Mais Nadab et Abihu moururent en la présence de leur père, et n’eurent point d’enfants; et Eléazar et Ithamar exercèrent la sacrificature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Or David les distribua, savoir, Tsadoc, qui était des enfants d’Eléazar; et Ahimélec, qui était des enfants d’Ithamar, pour leurs charges, dans le service qu’ils avaient à faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Et quand on les distribua, on trouva un beaucoup plus grand nombre des enfants d’Eléazar pour être Chefs de famille, que des enfants d’Ithamar, y ayant eu des enfants d’Eléazar, seize Chefs, selon leurs familles, et n’y en ayant eu que huit, des enfants d’Ithamar, selon leurs familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Et on fit leurs départements par sort, les entremêlant les uns parmi les autres; car les Gouverneurs du Sanctuaire, et les Gouverneurs de la maison de Dieu furent tirés tant des enfants d’Eléazar, que des enfants d’Ithamar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Et Sémahja fils de Nathanaël scribe, qui était de la Tribu de Lévi, les mit par écrit en la présence du Roi, des principaux du peuple, de Tsadoc le Sacrificateur, d’Ahimélec, fils d’Abiathar, et des Chefs des pères des familles des Sacrificateurs, et de celles des Lévites. Le chef d’une maison de père se tirait pour Eléazar, et celui qui était tiré après, se tirait pour Ithamar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Le premier sort donc échut à Jéhojarib, le second à Jédahia,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'Le troisième à Harim, le quatrième à Sehorim,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'Le cinquième à Malkija, le sixième à Mijamin,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'Le septième à Kots, le huitième à Abija,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'Le neuvième à Jésuah, le dixième à Sécania,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'L’onzième à Eliasib, le douzième à Jakim,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'Le treizième à Huppa, le quatorzième à Jésébab,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'Le quinzième à Bilga, le seizième à Immer,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'Le dix-septième à Hézir, le dix-huitième à Pitsets,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'Le dix-neuvième à Péthahja, le vingtième à Ezéchiel,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'Le vingt et unième à Jakim, et le vingt et deuxième à Gamul,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'Le vingt et troisième à Délaja, le vingt et quatrième à Mahazia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Tel fut leur dénombrement pour le service qu’ils avaient à faire, lorsqu’ils entraient dans la maison de l’Eternel, selon qu’il leur avait été ordonné par Aaron leur père, comme l’Eternel le Dieu d’Israël le lui avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Et quant aux enfants de Lévi qu’il y avait eu de reste des enfants de Hamram, il y eut Subaël, et des enfants de Subaël Jehdéja.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'De ceux de Réhabia, des enfants, dis-je, de Réhabia, Jisija était le premier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Des Jitsharites, Sélomoth; des enfants de Sélomoth, Jahath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Et des enfants de Jérija, Amaria le second; Jahaziël le troisième, Jékamham le quatrième.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Des enfants de’Huziël, Mica; des enfants de Mica, Samir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Le frère de Mica, était Jisija; des enfants de Jisija, Zacharie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Des enfants de Mérari, Mahli, et Musi. Des enfants de Jahazija, son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Des enfants donc de Mérari, de Jahazija, son fils, et Soham, Zaccur et Hibri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'De Mahli, Eléazar, qui n’eut point de fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'De Kis, les enfants de Kis, Jérahméël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Et des enfants de Musi, Mahli, Héder, et Jérimoth. Ce sont là les enfants des Lévites, selon les maisons de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Et ils jetèrent pareillement les sorts selon le nombre de leurs frères les enfants d’Aaron, en la présence du Roi David, de Tsadoc, et d’Ahimélec, et des Chefs des pères des familles des Sacrificateurs et des Lévites; les Chefs des pères de famille correspondant à leurs plus jeunes frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Et David et les Chefs de l’armée mirent à part pour le service, d’entre les enfants d’Asaph, d’Héman, et de Jéduthun, ceux qui prophétisaient avec des violons, des musettes, et des cymbales; et ceux d’entr’eux qui furent dénombrés étaient des hommes propres pour être employés au service qu’ils devaient faire,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Des enfants d’Asaph; Zaccur, Joseph, Néthania, et Asarela, enfants d’Asaph, sous la conduite d’Asaph, qui prophétisait par la commission du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'De Jéduthun; les six enfants de Jéduthun, Guédalia, Tséri, Esaïe, Hasabia, Mattitia, et Simhi, jouaient du violon, sous la conduite de leur père Jéduthun, qui prophétisait en célébrant et louant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'D’Héman; les enfants d’Héman, Bukkija, Mattania, Huziël, Sébuël, Jérimoth, Hanania, Hanani, Elijatha, Guiddalti, Romamti-hézer, Josbekasa, Malloth, Hothir, Mahazioth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Tous ceux-là étaient enfants d’Héman, le voyant du Roi dans les paroles de Dieu, pour en exalter la puissance; car Dieu donna à Héman quatorze fils et trois filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Tous ceux-là étaient employés sous la conduite de leurs pères, aux cantiques de la maison de l’Eternel, avec des cymbales, des musettes, et des violons, dans le service de la maison de Dieu, selon la commission du Roi donnée à Asaph, à Jéduthun, et à Héman.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Et leur nombre avec leurs frères, auxquels on avait enseigné les cantiques de l’Eternel, était de deux cent quatre-vingt et huit, tous fort intelligents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Et ils jetèrent leurs sorts touchant leur charge en mettant les uns contre les autres, les plus petits étant égalés aux plus grands, et les docteurs aux disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Et le premier sort échut à Asaph, savoir à Joseph. Le second à Guédalia; et lui, ses frères, et ses fils étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Le troisième à Zaccur; lui, ses fils et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Le quatrième à Jitsri; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Le cinquième à Néthania; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Le sixième à Bukkija; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Le septième à Jésarela; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Le huitième à Esaïe; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Le neuvième à Mattania; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Le dixième à Simhi; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'L’onzième à Hazaréël; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Le douzième à Hasabia; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Le treizième à Subaël; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Le quatorzième à Mattitia; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Le quinzième à Jérémoth; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Le seizième à Hanania; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Le dix-septième à Josbekasa; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Le dix-huitième à Hanani; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Le dix-neuvième à Malloth; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Le vingtième à Elijatha; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Le vingt et unième à Hothir; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Le vingt et deuxième à Guiddalti; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Le vingt et troisième à Mahazioth; lui, ses fils, et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Le vingt et quatrième à Romamti-hézer; lui, ses fils et ses frères étaient douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Et quant aux départements des portiers; il y eut pour les Corites, Mésélémia fils de Coré, d’entre les enfants d’Asaph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Et les enfants de Mésélémia furent, Zacharie le premier-né; Jédihaël le second; Zébadia le troisième; Jathniël le quatrième,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Hélam le cinquième, Johanum le sixième; Eliehohenaï le septième.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Et les enfants de Hobed-Edom furent, Sémahja le premier-né, Jéhozabad le second, Joah le troisième, Sacar le quatrième, Nathanaël le cinquième,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Hammiel le sixième, Issacar le septième, Pehulletaï le huitième; car Dieu l’avait béni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Et à Sémahja son fils naquirent des enfants, qui eurent le commandement sur la maison de leur père, parce qu’ils étaient hommes forts et vaillants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Les enfants donc de Sémahja furent, Hothni, et Réphaël, Hobed, et Elzabad, ses frères, hommes vaillants, Elihu et Sémacia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Tous ceux-là étaient des enfants d’Hobed-Edom, eux et leurs fils, et leurs frères, hommes vaillants, et forts pour le service; ils étaient soixante-deux d’Hobed-Edom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Et les enfants de Mésélémia avec ses frères étaient dix-huit, vaillants hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Et les enfants de Hoza, d’entre les enfants de Mérari, furent Simri le Chef; car quoiqu’il ne fût pas l’aîné, néanmoins son père l’établit pour Chef.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Hilkija était le second, Tebalia le troisième, Zacharie le quatrième; tous les enfants et frères de Hoza furent treize.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'On fit à ceux-là les départements des portiers, en sorte que les charges furent distribuées aux Chefs de famille, en égalant les uns aux autres, afin qu’ils servissent dans la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Car ils jetèrent les sorts autant pour le plus petit que pour le plus grand, selon leurs familles, pour chaque porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Et ainsi le sort pour la porte vers l’Orient échut à Sélémia. Puis on jeta le sort pour Zacharie son fils, sage conseiller, et son sort échut pour la porte vers le Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Le sort d’Hobed-Edom échut pour la porte vers le Midi, et la maison des assemblées échut à ses fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'A Suppim et à Hosa pour la porte vers l’Occident, auprès de la porte de Salleketh, au chemin montant; une garde étant vis-à-vis de l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Il y avait vers l’Orient, six Lévites; vers le Septentrion, quatre par jour; vers le Midi, quatre aussi par jour; et vers la maison des assemblées deux de chaque côté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'A Parbar vers l’Occident, il y en avait quatre au chemin, et deux à Parbar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Ce sont là les départements des portiers pour les enfants des Corites, et pour les enfants de Mérari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Ceux-ci aussi étaient Lévites; Ahija commis sur les trésors de la maison de Dieu, et sur les trésors des choses consacrées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Des enfants de Lahdan, qui étaient d’entre les enfants des Guersonites; du côté de Lahdan, d’entre les Chefs des pères appartenant à Lahdan Guersonite, Jéhiëli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'D’entre les enfants de Jéhiëli, Zétham, et Joël son frère, commis sur les trésors de la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Pour les Hamramites, Jitsharites, Hébronites, et Hoziëlites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Et Sébuël fils de Guersom, fils de Moïse, était commis sur les autres trésors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Et quant à ses frères du côté d’Elihézer, dont Réhabia fut fils, qui eut pour fils Esaïe, qui eut pour fils Joram, qui eut pour fils Zicri, qui eut pour fils Sélomith.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Ce Sélomith et ses frères furent commis sur les trésors des choses saintes que le Roi David, les Chefs des pères, les Gouverneurs de milliers, et de centaines; et les Capitaines de l’armée avaient consacrées;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Qu’ils avaient, dis-je, consacrées des batailles et des dépouilles, pour le bâtiment de la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Et tout ce qu’avait consacré Samuël le voyant, et Saül fils de Kis, et Abner fils de Ner, et Joab fils de Tséruïa; tout ce, enfin, qu’on consacrait, était mis entre les mains de Sélomith et de ses frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'D’entre les Jitsharites, Kénania et ses fils étaient employés aux affaires de dehors sur Israël, pour être prévôts et juges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Quant aux Hébronites, Hasabia et ses frères, hommes vaillants, au nombre de mille sept cents, présidaient sur le gouvernement d’Israël au deçà du Jourdain, vers l’Occident, pour tout ce qui concernait l’Eternel, et pour le service du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Quant aux Hébronites, selon leurs générations dans les familles des pères, Jérija fut le Chef des Hébronites. On en fit la recherche en la quarantième année du règne de David, et on trouva parmi eux à Jahzer de Galaad des hommes forts et vaillants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'Les frères donc de Jérija, hommes vaillants, furent deux mille sept cents, issus des Chefs des pères; et le Roi David les établit sur les Rubénites, sur les Gadites, et sur la demi-Tribu de Manassé, pour tout ce qui concernait Dieu, et pour les affaires du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Or quant aux enfants d’Israël, selon leur dénombrement, il y avait des Chefs de pères, des Gouverneurs de milliers et de centaines, et leurs prévôts, qui servaient le Roi selon tout l’état des départements, dont l’un entrait, et l’autre sortait, de mois en mois, durant tous les mois de l’année; et chaque département était de vingt et quatre mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Et Jasobham fils de Zabdiël présidait sur le premier département, pour le premier mois; et dans son département il y avait vingt et quatre mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Il était des enfants de Pharés, Chef de tous les capitaines de l’armée du premier mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Dodaï Ahohite présidait sur le département du second mois, ayant Mikloth pour Lieutenant en son département; et dans son département il y avait vingt et quatre mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Le Chef de la troisième armée pour le troisième mois, était Bénaja fils de Jéhojadah Sacrificateur, et capitaine en Chef; et dans son département il y avait vingt et quatre mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'C’est ce Bénaja qui était fort entre les trente, et par dessus les trente; et Hammizabad son fils était dans son département.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Le quatrième pour le quatrième mois était Hazaël frère de Joab, et Zébadia son fils, après lui; et il y avait dans son département vingt et quatre mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Le cinquième pour le cinquième mois était le capitaine Samhuth de Jizrah; et dans son département il y avait vingt et quatre mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Le sixième pour le sixième mois était Hira fils d’Hikkés Tékohite; et dans son département il y avait vingt et quatre mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Le septième pour le septième mois était Hélets Pélonite, des enfants d’Ephraïm; et il y avait dans son département vingt et quatre mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Le huitième pour le huitième mois était Sibbecaï Husathite, de la famille des Zarhites; et il y avait dans son département vingt et quatre mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Le neuvième pour le neuvième mois était Abihézer Hanathothite, des Benjamites; et il y avait dans son département vingt et quatre mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Le dixième pour le dixième mois était Naharaï Nétophathite, de la famille des Zarhites; et il y avait dans son département vingt et quatre mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'L’onzième pour l’onzième mois était Bénaja Pirhathonite, des enfants d’Ephraïm; et il y avait dans son département vingt et quatre mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Le douzième pour le douzième mois était Heldaï Nétophathite, appartenant à Hothniël; et il y avait dans son département vingt et quatre mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Et ceux-ci présidaient sur les Tribus d’Israël; Elihézer fils de Zicri était le conducteur des Rubénites. Des Siméonites, Séphatia fils de Mahaca.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Des Lévites, Hasabia fils de Kémuël. De ceux d’Aaron, Tsadoc.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'De Juda, Elihu, qui était des frères de David. De ceux d’Issacar, Homri fils de Micaël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'De ceux de Zabulon, Jismahia, fils de Hobadia. De ceux de Nephthali, Jérimoth fils de Hazriël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'Des enfants d’Ephraïm, Hosée fils de Hazazia. De la demi-Tribu de Manassé, Joël fils de Pédaja.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'De l’autre demi-Tribu de Manassé en Galaad, Jiddo fils de Zacharie. De ceux de Benjamin, Jahasiël fils d’Abner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'De ceux de Dan, Hazaréël fils de Jéroham. Ce sont là les principaux des Tribus d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Mais David ne fit point le dénombrement des Israélites, depuis l’âge de vingt ans et au dessous; parce que l’Eternel avait dit qu’il multiplierait Israël comme les étoiles du ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Joab fils de Tséruiä avait bien commencé à en faire le dénombrement, mais il n’acheva pas, parce que l’indignation de Dieu s’était répandue à cause de cela sur Israël; c’est pourquoi ce dénombrement ne fut point mis parmi les dénombrements enregistrés dans les Chroniques du Roi David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Or Hazmaveth fils d’Hadiël était commis sur les finances du Roi; mais Jonathan fils d’Huzija était commis sur les finances qui étaient à la campagne, dans les villes et aux villages et aux châteaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Et Hezri, fils de Kélub, était commis sur ceux qui travaillaient dans la campagne au labourage de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Et Simhi Ramathite sur les vignes, et Zabdi Siphmien sur ce qui provenait des vignes, et sur les celliers du vin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Et Bahal-hanan Guéderite sur les oliviers, et sur les figuiers qui étaient en la campagne; et Johas sur les celliers à huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Et Sitraï Saronite, était commis sur le gros bétail qui paissait en Saron; et Saphat fils de Hadlaï sur le gros bétail qui paissait dans les vallées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Et Obil Ismaëlite sur les chameaux; Jéhdeja Méronothite, sur les ânesses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Et Jaziz Hagarénien sur les troupeaux du menu bétail. Tous ceux-là avaient la charge du bétail qui appartenait au Roi David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Mais Jonathan, oncle de David, était conseiller, homme fort intelligent et scribe, et Jéhiël fils de Hacmoni était avec les enfants du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Et Achitophel était le conseiller du Roi; et Cusaï Arkite était l’intime ami du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Après Achitophel était Jéhojadah fils de Bénaja et Abiathar; et Joab était le Général de l’armée du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Or David assembla à Jérusalem tous les Chefs d’Israël, les Chefs des Tribus, et les Chefs des départements qui servaient le Roi; et les Gouverneurs de milliers et de centaines, et ceux qui avaient la charge de tous les biens du Roi, et de tout ce qu il possédait, ses fils avec ses Eunuques, et les hommes puissants, et tous les hommes forts et vaillants;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Puis le Roi David se leva sur ses pieds, et dit: Mes frères, et mon peuple, écoutez-moi: J’ai désiré de bâtir une maison de repos à l’Arche de l’alliance de l’Eternel, et au marchepied de notre Dieu, et j’ai fait les préparatifs pour la bâtir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Mais Dieu m’a dit: Tu ne bâtiras point de maison à mon Nom, parce que tu es un homme de guerre, et que tu as répandu beaucoup de sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Or comme l’Eternel le Dieu d’Israël m’a choisi de toute la maison de mon père pour être Roi sur Israël à toujours; car il a choisi Juda pour Conducteur, et de la maison de Juda la maison de mon père, et d’entre les fils de mon père il a pris son plaisir en moi, pour me faire régner sur tout Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Aussi d’entre tous mes fils (car l’Eternel m’a donné plusieurs fils) il a choisi Salomon mon fils, pour s’asseoir sur le trône du Royaume de l’Eternel sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Et il m’a dit: Salomon ton fils est celui qui bâtira ma maison et mes parvis;: car je me le suis choisi pour fils et je lui serai père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Et j’affermirai son règne à toujours, s’il s’applique à faire mes commandements et à observer mes ordonnances, comme il le fait aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Maintenant donc je vous somme en la présence de tout Israël, qui est l’assemblée de l’Eternel, et devant notre Dieu qui l’entend, que vous ayez à garder et à rechercher diligemment tous les commandements de l’Eternel votre Dieu, afin que vous possédiez ce bon pays, et que vous le fassiez hériter à vos enfants après vous, à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Et toi Salomon mon fils, connais le Dieu de ton père, et sers-le avec un coeur droit, et une bonne volonté; car l’Eternel sonde tous les coeurs, et connaît toutes les imaginations des pensées. Si tu le cherches, il se fera trouver à toi; mais si tu l’abandonnes, il te rejettera pour toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Considère maintenant, que l’Eternel t’a choisi pour bâtir une maison pour son sanctuaire; fortifie-toi donc, et applique-toi à y travailler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Et David donna à Salomon son fils le modèle du portique, de ses maisons, de ses cabinets, de ses chambres hautes, de ses cabinets de dedans, et du lieu du Propitiatoire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'Et le modèle de toutes les choses qui lui avaient été inspirées par l’Esprit qui était avec lui, pour les parvis de la maison de l’Eternel, pour les chambres d’alentour, pour les trésors de la maison de l’Eternel, et pour les trésors des choses saintes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'Et pour les départements des Sacrificateurs et des Lévites, et pour toute l’oeuvre du service de la maison de l’Eternel, et pour tous les ustensiles du service de la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Il lui donna aussi de l’or à certain poids, pour les choses qui devaient être d’or, savoir pour tous les ustensiles de chaque service; et de l’argent à certain poids, pour tous les ustensiles d’argent, savoir pour tous les ustensiles de chaque service.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Le poids des chandeliers d’or, et de leurs lampes d’or, selon le poids de chaque chandelier et de ses lampes; et le poids des chandeliers d’argent, selon le poids de chaque chandelier et de ses lampes, selon le service de chaque chandelier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Et le poids de l’or pesant ce qu’il fallait pour chaque table des pains de proposition; et de l’argent pour les tables d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'Et de l’or pur pour les fourchettes, pour les bassins, pour les gobelets, et pour les plats d’or, selon le poids de chaque plat; et de l’argent pour les plats d’argent, selon le poids de chaque plat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'Et de l’or affiné à certain poids pour l’autel des parfums; et de l’or pour le modèle du chariot des Chérubins qui étendaient les ailes, et qui couvraient l’Arche de l’alliance de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Toutes ces choses, dit-il, m’ont été données par écrit, de la part de l’Eternel, afin que j’eusse l’intelligence de tous les ouvrages de ce modèle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'C’est pourquoi David dit à Salomon son fils: Fortifie-toi, et prends courage, et travaille; ne crains point, et ne t’effraie de rien; car l’Eternel Dieu, mon Dieu, sera avec toi, il ne te délaissera point, et il ne t’abandonnera point, que tu n’aies achevé tout l’ouvrage du service de la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Et voici, j’ai fait les départements des Sacrificateurs et des Lévites pour tout le service de la maison de Dieu; et il y a avec toi pour tout cet ouvrage toutes sortes de gens prompts et experts, pour toute sorte de service; et les Chefs avec tout le peuple seront prêts pour exécuter tout ce que tu diras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Puis le Roi David dit à toute l’assemblée: Dieu a choisi un seul de mes fils, savoir Salomon, qui est encore jeune et délicat, et l’ouvrage est grand; car ce palais n’est point pour un homme, mais pour l’Eternel Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Et moi, j’ai préparé de toutes mes forces pour la maison de mon Dieu, de l’or pour les choses qui doivent être d’or, de l’argent pour celles qui doivent être d’argent; de l’airain pour celles d’airain, du fer pour celles de fer, du bois pour celles de bois, des pierres d’onyx, et des pierres pour être enchâssées, des pierres d’escarboucle, et des pierres de diverses couleurs; des pierres précieuses de toutes sortes, et du marbre en abondance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Et outre cela, parce que j’ai une grande affection pour la maison de mon Dieu, je donne pour la maison de mon Dieu, outre toutes les choses que j’ai préparées pour la maison du Sanctuaire, l’or et l’argent que j’ai entre mes plus précieux joyaux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'Savoir, trois mille talents d’or, de l’or d’Ophir, et sept mille talents d’argent affiné, pour revêtir les murailles de la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Afin qu’il y ait de l’or partout où il faut de l’or, et de l’argent partout où il faut de l’argent; et pour tout l’ouvrage qui se fera par main d’ouvriers. Or qui est celui d’entre vous qui se disposera volontairement à offrir aujourd’hui libéralement à l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Alors les Chefs des pères, et les Chefs des Tribus d’Israël, et les Gouverneurs de milliers et de centaines, et ceux qui avaient la charge des affaires du Roi offrirent volontairement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'Et ils donnèrent pour le service de la maison de Dieu cinq mille talents et dix mille drachmes d’or, dix mille talents d’argent, dix-huit mille talents d’airain, et cent mille talents de fer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Ils mirent aussi les pierreries que chacun avait, au trésor de la maison de l’Eternel, entre les mains de Jéhiël Guersonite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Et le peuple offrait avec joie volontairement; car ils offraient de tout leur coeur leurs offrandes volontaires à l’Eternel; et David en eut une fort grande joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Puis David bénit l’Eternel en la présence de toute l’assemblée, et dit: Ô Eternel Dieu d’Israël notre père! tu es béni de tout temps et à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Ô Eternel! c’est à toi qu’appartient la magnificence, la puissance, la gloire, l’éternité, et la majesté; car tout ce qui est aux cieux et en la terre est à toi; ô Eternel! le Royaume est à toi, et tu es le Prince de toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Les richesses et les honneurs viennent de toi, et tu as la domination sur toutes choses; la force et la puissance est en ta main, et il est aussi en ta main d’agrandir et de fortifier toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Maintenant donc, ô notre Dieu! nous te célébrons, et nous louons ton Nom glorieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Mais qui suis-je, et qui est mon peuple, que nous ayons assez de pouvoir pour offrir ces choses volontairement? car toutes choses viennent de toi, et les ayant reçues de ta main, nous te les présentons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Et même nous sommes étrangers et forains chez toi, comme ont été tous nos pères; et nos jours sont comme l’ombre sur la terre, et il n’y a nulle espérance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Eternel notre Dieu! toute cette abondance, que nous avons préparée pour bâtir une maison à ton saint Nom, est de ta main, et toutes ces choses sont à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Et je sais, ô mon Dieu! que c’est toi qui sondes les coeurs, et que tu prends plaisir à la droiture; c’est pourquoi j’ai volontairement offert d’un coeur droit toutes ces choses, et j’ai vu maintenant avec joie que ton peuple, qui s’est trouvé ici, t’a fait son offrande volontairement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Ô Eternel! Dieu d’Abraham, d’Isaac, et d’Israël nos pères, entretiens ceci à toujours, savoir l’inclination des pensées du coeur de ton peuple, et tourne leurs coeurs vers toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Donne aussi un coeur droit à Salomon mon fils, afin qu’il garde tes commandements, tes témoignages, et tes statuts, et qu’il fasse tout ce qui est nécessaire et qu’il bâtisse le palais que j’ai préparé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Après cela David dit à toute l’assemblée: Bénissez maintenant l’Eternel votre Dieu. Et toute l’assemblée bénit l’Eternel, le Dieu de leurs pères, et s’inclinant, ils se prosternèrent devant l’Eternel, et devant le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Et le lendemain ils sacrifièrent des sacrifices à l’Eternel, et lui offrirent des holocaustes, savoir mille veaux, mille moutons, et mille agneaux, avec leurs aspersions; et des sacrifices en grand nombre pour tous ceux d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Et ils mangèrent et burent ce jour-là devant l’Eternel avec une grande joie; et ils établirent Roi pour la seconde fois Salomon fils de David, et l’oignirent en l’honneur de l’Eternel pour être leur Conducteur, et Tsadoc pour Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Salomon donc s’assit sur le trône de l’Eternel pour être Roi en la place de David son père, et il prospéra; car tout Israël lui obéit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Et tous les principaux et les puissants, et même tous les fils du Roi David consentirent d’être les sujets du Roi Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Ainsi l’Eternel éleva souverainement Salomon, à la vue de tout Israël; et lui donna une majesté Royale, telle qu’aucun Roi avant lui n’en avait eue en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'David donc fils d’Isaï régna sur tout Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Et les jours qu’il régna sur Israël furent quarante ans; il régna sept ans à Hébron, et trente-trois ans à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Puis il mourut en bonne vieillesse, rassasié de jours, de richesses, et de gloire; et Salomon son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Or quant aux faits du Roi David, tant les premiers que les derniers, voilà, ils sont écrits au Livre de Samuël le Voyant, et aux Livres de Nathan le Prophète, et aux Livres de Gad le Voyant,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'Avec tout son règne, et sa force, et les temps qui passèrent sur lui, et sur Israël, et sur tous les Royaumes des pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Or Salomon, fils de David, s’affermit dans son règne; l’Éternel son Dieu fut avec lui, et l’éleva extrêmement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Et Salomon parla à tout Israël, aux chefs de milliers et de centaines, aux juges et à tous les principaux de tout Israël, chefs des maisons des pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Et Salomon et toute l’assemblée avec lui, allèrent au haut lieu qui était à Gabaon; car là était le tabernacle d’assignation de Dieu, que Moïse, serviteur de l’Éternel, avait fait dans le désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Mais David avait amené l’arche de Dieu, de Kirjath-Jearim au lieu qu’il avait préparé; car il lui avait dressé un tabernacle à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'L’autel d’airain que Betsaléel, fils d’Uri, fils de Hur, avait fait, était là devant la Demeure de l’Éternel. Et Salomon et l’assemblée y cherchèrent l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Et Salomon offrit là, devant l’Éternel, mille holocaustes, sur l’autel d’airain qui était devant le tabernacle d’assignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'En cette nuit-là, Dieu apparut à Salomon, et lui dit: Demande ce que tu veux que je te donne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Et Salomon répondit à Dieu: Tu as usé de grande miséricorde envers David, mon père, et tu m’as établi roi à sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Maintenant, Éternel Dieu! que ta parole à David, mon père, soit ferme; car tu m’as établi roi sur un peuple nombreux comme la poussière de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Donne-moi donc maintenant de la sagesse et de l’intelligence, afin que je sache me conduire devant ce peuple; car qui pourrait juger ton peuple, ce peuple si grand?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Et Dieu dit à Salomon: Puisque c’est là ce qui est dans ton cœur, et que tu n’as demandé ni des richesses, ni des biens, ni de la gloire, ni la mort de ceux qui te haïssent, ni même des jours nombreux, mais que tu as demandé pour toi de la sagesse et de l’intelligence, afin de pouvoir juger mon peuple, sur lequel je t’ai établi roi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'La sagesse et l’intelligence te sont données. Je te donnerai aussi des richesses, des biens et de la gloire, comme n’en ont pas eu les rois qui ont été avant toi, et comme n’en aura aucun après toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Puis Salomon s’en retourna à Jérusalem, du haut lieu qui était à Gabaon, de devant le tabernacle d’assignation; et il régna sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Salomon rassembla des chars et des cavaliers; il avait quatorze cents chars et douze mille cavaliers; et il les mit dans les villes où il tenait ses chars, et auprès du roi, à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Et le roi fit que l’argent et l’or étaient aussi communs à Jérusalem que les pierres, et les cèdres, que les sycomores de la plaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Le lieu d’où l’on tirait les chevaux pour Salomon était l’Égypte; une troupe de marchands du roi allaient en chercher un convoi pour un prix convenu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'On faisait monter et sortir d’Égypte un char pour six cents sicles d’argent, et un cheval pour cent cinquante. On en amenait de même par eux pour tous les rois des Héthiens, et pour les rois de Syrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Or Salomon ordonna de bâtir une maison au nom de l’Éternel, et pour lui une maison royale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Et Salomon compta soixante et dix mille hommes pour porter les fardeaux, et quatre-vingt mille pour tailler les pierres dans la montagne, et trois mille six cents préposés sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Puis Salomon envoya vers Huram, roi de Tyr, pour lui dire: Fais pour moi comme tu as fait pour David, mon père, à qui tu as envoyé des cèdres, pour se bâtir une maison afin d’y habiter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Voici, je vais bâtir une maison au nom de l’Éternel mon Dieu, pour la lui consacrer, pour faire fumer devant lui le parfum des aromates, pour présenter continuellement devant lui les pains de proposition, et pour offrir les holocaustes du matin et du soir, des sabbats, des nouvelles lunes, et des fêtes de l’Éternel, notre Dieu, ce qui est un devoir pour Israël à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'La maison que je vais bâtir sera grande; car notre Dieu est plus grand que tous les dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Mais qui aurait le pouvoir de lui bâtir une maison, puisque les cieux et les cieux des cieux ne sauraient le contenir? Et qui suis-je pour lui bâtir une maison, si ce n’est pour faire fumer des parfums devant sa face?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Maintenant envoie-moi un homme habile à travailler en or, en argent, en airain et en fer, en écarlate, en cramoisi et en pourpre, sachant sculpter des sculptures, pour travailler avec les hommes habiles que j’ai avec moi en Juda et à Jérusalem, et que David, mon père, a préparés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Envoie-moi aussi du Liban du bois de cèdre, de cyprès et de santal; car je sais que tes serviteurs savent couper le bois du Liban. Voici, mes serviteurs seront avec les tiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Qu’on me prépare du bois en grande quantité; car la maison que je vais bâtir sera grande et magnifique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Et je donnerai à tes serviteurs qui couperont, qui abattront les bois, vingt mille cores de froment foulé, vingt mille cores d’orge, vingt mille baths de vin, et vingt mille baths d’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Huram, roi de Tyr, répondit, dans un écrit qu’il envoya à Salomon: C’est parce que l’Éternel aime son peuple qu’il t’a établi roi sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Et Huram dit: Béni soit l’Éternel, le Dieu d’Israël, qui a fait les cieux et la terre, de ce qu’il a donné au roi David un fils sage, prudent et intelligent, qui va bâtir une maison à l’Éternel, et une maison royale pour lui!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Je t’envoie donc un homme habile et intelligent, Huram-Abi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Fils d’une femme d’entre les filles de Dan, et d’un père tyrien. Il sait travailler en or, en argent, en airain et en fer, en pierres et en bois, en écarlate, en pourpre, en fin lin et en cramoisi; il sait sculpter toutes sortes de sculptures et imaginer toutes sortes d’objets d’art qu’on lui donne à faire. Il travaillera avec tes hommes habiles et avec les hommes habiles de mon seigneur David, ton père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Et maintenant, que mon seigneur envoie à ses serviteurs le froment, l’orge, l’huile et le vin qu’il a dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Et nous couperons des bois du Liban autant qu’il t’en faudra, et nous te les amènerons en radeaux, par mer, jusqu’à Japho, et tu les feras monter à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Alors Salomon compta tous les étrangers qui étaient au pays d’Israël, après le dénombrement que David, son père, en avait fait; on en trouva cent cinquante-trois mille six cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'Et il en établit soixante et dix mille qui portaient des fardeaux, quatre-vingt mille qui taillaient les pierres dans la montagne, et trois mille six cents préposés pour faire travailler le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Salomon commença donc à bâtir la maison de l’Éternel à Jérusalem, sur la montagne de Morija, qui avait été indiquée à David, son père, au lieu même que David avait préparé dans l’aire d’Ornan, le Jébusien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Il commença à bâtir, le second jour du second mois, la quatrième année de son règne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Or voici la base fixée par Salomon pour bâtir la maison de Dieu: La longueur, en coudées de l’ancienne mesure, était de soixante coudées, et la largeur de vingt coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Le portique, qui était sur le devant, et dont la longueur répondait à la largeur de la maison, avait vingt coudées, et cent vingt de hauteur. Il le revêtit intérieurement d’or pur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Et il couvrit la grande maison de bois de cyprès; il la revêtit d’or fin, et y fit mettre des palmes et des chaînettes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Il revêtit la maison de pierres précieuses, pour l’ornement; et l’or était de l’or de Parvaïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Il revêtit d’or la maison, les poutres, les seuils, les parois et les portes; et il sculpta des chérubins sur les parois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Il fit le lieu très-saint, dont la longueur était de vingt coudées, selon la largeur de la maison, et la largeur de vingt coudées; et il le couvrit d’or fin, se montant à six cents talents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Et le poids des clous montait à cinquante sicles d’or. Il revêtit aussi d’or les chambres hautes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Il fit deux chérubins dans le lieu très-saint, en travail de sculpture, et on les couvrit d’or;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'La longueur des ailes des chérubins était de vingt coudées; l’aile de l’un, longue de cinq coudées, touchait à la paroi de la maison, et l’autre aile, longue de cinq coudées, touchait à l’aile de l’autre chérubin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Et l’aile de l’autre chérubin, longue de cinq coudées, touchait la paroi de la maison; et l’autre aile, longue de cinq coudées, joignait l’aile de l’autre chérubin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Les ailes de ces chérubins avaient une étendue de vingt coudées; ils se tenaient debout sur leurs pieds, leur face tournée vers la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Il fit le voile de pourpre, d’écarlate, de cramoisi et de fin lin; et il mit dessus des chérubins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Devant la maison il fit deux colonnes, de trente-cinq coudées de hauteur; et le chapiteau qui les surmontait, était de cinq coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Il fit des chaînettes dans le sanctuaire; et il en mit sur le sommet des colonnes; et il fit cent grenades qu’il mit aux chaînettes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Il dressa les colonnes sur le devant du temple, l’une à droite, et l’autre à gauche; il appela celle de droite Jakin (il a fondé), et celle de gauche Boaz (en lui la force).');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Il fit aussi un autel d’airain de vingt coudées de long, de vingt coudées de large, et de dix coudées de haut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Il fit la mer de fonte de dix coudées d’un bord à l’autre, ronde tout autour, et haute de cinq coudées; et un cordon de trente coudées l’environnait tout autour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Et des figures de bœufs l’entouraient en dessous, tout autour, dix par coudée, environnant la mer tout autour; il y avait deux rangées de bœufs fondus avec elle dans sa fonte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Elle était posée sur douze bœufs, dont trois tournés vers le nord, trois tournés vers l’occident, trois tournés vers le midi, et trois tournés vers l’orient; la mer était sur eux, et toutes leurs croupes étaient en dedans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Son épaisseur était d’une palme; et son bord était comme le bord d’une coupe, en fleur de lis; elle contenait trois mille baths.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Il fit aussi dix cuves, et en mit cinq à droite et cinq à gauche, pour y laver. On y lavait ce qui appartenait aux holocaustes, et la mer servait aux sacrificateurs pour s’y laver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Il fit dix chandeliers d’or, selon la forme qu’ils devaient avoir, et les mit dans le temple, cinq à droite et cinq à gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Il fit aussi dix tables, et il les mit dans le temple, cinq à droite, et cinq à gauche; et il fit cent coupes d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Il fit encore le parvis des sacrificateurs, et le grand parvis, et des portes pour ce parvis, et couvrit d’airain ces portes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Il mit la mer du côté droit, vers l’orient, en face du midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Et Huram fit les pots, les pelles et les coupes; et il acheva de faire l’œuvre qu’il faisait pour le roi Salomon dans la maison de Dieu:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'Deux colonnes, les renflements et les deux chapiteaux, sur le sommet des colonnes; les deux réseaux pour couvrir les deux renflements des chapiteaux, sur le sommet des colonnes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'Et les quatre cents grenades pour les deux réseaux, deux rangs de grenades à chaque réseau, pour couvrir les deux renflements des chapiteaux, sur le sommet des colonnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Il fit aussi les socles, et il fit les cuves sur les socles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'Une mer et les douze bœufs sous elle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Les pots, les pelles et les fourchettes et tous les ustensiles qui en dépendaient, Huram-Abi les fit au roi Salomon, pour la maison de l’Éternel, en airain poli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Le roi les fit fondre dans la plaine du Jourdain, dans une terre grasse, entre Succoth et Tséréda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Et Salomon fit tous ces ustensiles en grand nombre, car on ne pouvait estimer le poids de l’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Salomon fit encore tous ces ustensiles qui appartenaient à la maison de Dieu: l’autel d’or, et les tables sur lesquelles on mettait le pain de proposition;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'Les chandeliers et leurs lampes d’or fin, qu’on devait allumer devant le sanctuaire, selon l’ordonnance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'Les fleurs, les lampes, et les mouchettes d’or, d’un or parfaitement pur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'Et les serpes, les bassins, les tasses et les encensoirs d’or fin. Et quant à l’entrée de la maison, les portes intérieures conduisant au lieu très-saint, et les portes de la maison, pour entrer au temple, étaient d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Ainsi fut achevé tout l’ouvrage que Salomon fit pour la maison de l’Éternel. Puis Salomon fit apporter ce que David, son père, avait consacré: l’argent, l’or et tous les ustensiles; et il les mit dans les trésors de la maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Alors Salomon assembla à Jérusalem les anciens d’Israël, et tous les chefs des tribus, les principaux des pères des enfants d’Israël, pour transporter de la ville de David, qui est Sion, l’arche de l’alliance de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Et tous les hommes d’Israël se réunirent auprès du roi pour la fête; c’était le septième mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Tous les anciens d’Israël vinrent, et les Lévites portèrent l’arche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'Ils transportèrent l’arche, le tabernacle d’assignation, et tous les ustensiles sacrés qui étaient dans le tabernacle; les sacrificateurs et les Lévites les transportèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Or le roi Salomon et toute l’assemblée d’Israël réunie auprès de lui étaient devant l’arche, sacrifiant du menu et du gros bétail, en si grand nombre qu’on ne le pouvait ni compter ni nombrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Et les sacrificateurs portèrent l’arche de l’alliance de l’Éternel à sa place, dans le sanctuaire de la maison, dans le lieu très-saint, sous les ailes des chérubins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Les chérubins étendaient les ailes sur l’endroit où devait être l’arche; et les chérubins couvraient l’arche et ses barres par- dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Les barres avaient une longueur telle que leurs extrémités se voyaient en avant de l’arche, sur le devant du sanctuaire; mais elles ne se voyaient point du dehors. Et l’arche a été là jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Il n’y avait dans l’arche que les deux tables que Moïse y avait mises en Horeb, quand l’Éternel traita alliance avec les enfants d’Israël, à leur sortie d’Égypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Or il arriva, comme les sacrificateurs sortaient du lieu saint (car tous les sacrificateurs présents s’étaient sanctifiés, sans observer l’ordre des classes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Et tous les Lévites qui étaient chantres, Asaph, Héman, Jéduthun, leurs fils et leurs frères, vêtus de fin lin, avec des cymbales, des lyres et des harpes, se tenaient à l’orient de l’autel; et il y avait avec eux cent vingt sacrificateurs, qui sonnaient des trompettes),');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Lorsque, comme un seul homme, ceux qui sonnaient des trompettes et ceux qui chantaient firent entendre leur voix d’un même accord, pour célébrer et pour louer l’Éternel, et qu’ils firent retentir le son des trompettes, des cymbales et d’autres instruments de musique, et qu’ils célébrèrent l’Éternel, en disant: Car il est bon, car sa miséricorde demeure à toujours! il arriva que la maison de l’Éternel fut remplie d’une nuée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Et les sacrificateurs ne purent s’y tenir pour faire le service, à cause de la nuée; car la gloire de l’Éternel remplissait la maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Alors Salomon dit: L’Éternel a dit qu’il habiterait dans l’obscurité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Et moi, j’ai bâti une maison pour ta demeure, et un domicile afin que tu y habites à toujours!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Puis le roi tourna son visage, et bénit toute l’assemblée d’Israël; et toute l’assemblée d’Israël était debout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Et il dit: Béni soit l’Éternel, le Dieu d’Israël, qui de sa bouche a parlé à David, mon père, et qui, de sa main, a accompli ce qu’il avait promis en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Depuis le jour où j’ai fait sortir mon peuple du pays d’Égypte, je n’ai point choisi de ville entre toutes les tribus d’Israël pour y bâtir une maison, afin que mon nom y fût, et je n’ai point choisi d’homme pour être chef de mon peuple d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Mais j’ai choisi Jérusalem pour que mon nom y fût, et j’ai choisi David pour qu’il régnât sur mon peuple d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Or David, mon père, avait dessein de bâtir une maison au nom de l’Éternel, le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Mais l’Éternel dit à David, mon père: Puisque tu as eu le dessein de bâtir une maison à mon nom, tu as bien fait de former ce dessein.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Seulement ce n’est pas toi qui bâtiras cette maison; mais c’est ton fils, issu de toi, qui bâtira cette maison à mon nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'L’Éternel a donc accompli la parole qu’il avait prononcée; j’ai succédé à David, mon père, et je me suis assis sur le trône d’Israël, comme l’Éternel l’avait dit, et j’ai bâti cette maison au nom de l’Éternel, le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Et j’y ai mis l’arche, où est l’alliance de l’Éternel, qu’il a traitée avec les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Puis il se plaça devant l’autel de l’Éternel, en face de toute l’assemblée d’Israël, et il étendit ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Car Salomon avait fait une tribune d’airain, et il l’avait mise au milieu du grand parvis; elle était longue de cinq coudées, large de cinq coudées, et haute de trois coudées; il s’y plaça, se mit à genoux, en face de toute l’assemblée d’Israël, et, étendant ses mains vers les cieux, il dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'O Éternel, Dieu d’Israël! ni dans les cieux, ni sur la terre, il n’y a de Dieu semblable à toi, qui gardes l’alliance et la miséricorde envers tes serviteurs qui marchent de tout leur cœur devant ta face;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Toi qui as tenu à ton serviteur David, mon père, ce que tu lui avais promis; et ce que tu as prononcé de ta bouche, tu l’as accompli de ta main, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Maintenant donc, ô Éternel, Dieu d’Israël! tiens à ton serviteur David, mon père, ce que tu lui as promis en disant: Tu ne manqueras jamais devant moi d’un successeur assis sur le trône d’Israël; pourvu que tes fils prennent garde à leur voie, pour marcher dans ma loi, comme tu as marché devant ma face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Et maintenant, ô Éternel, Dieu d’Israël! que ta parole, que tu as prononcée à David, ton serviteur, soit ratifiée!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Mais serait-il vrai que Dieu habitât sur la terre avec les hommes? Voici, les cieux, même les cieux des cieux, ne peuvent te contenir, combien moins cette maison que j’ai bâtie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Toutefois, ô Éternel, mon Dieu! aie égard à la prière de ton serviteur et à sa supplication, pour écouter le cri et la prière que ton serviteur t’adresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Que tes yeux soient ouverts, jour et nuit, sur cette maison, sur le lieu où tu as promis de mettre ton nom, exauçant la prière que ton serviteur te fait en ce lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Exauce les supplications de ton serviteur et de ton peuple d’Israël, quand ils prieront en ce lieu; exauce-les des cieux, du lieu de ta demeure; exauce et pardonne!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Quand quelqu’un aura péché contre son prochain, et qu’on lui déférera le serment pour le faire jurer, et qu’il viendra prêter serment devant ton autel, dans cette maison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'Toi, écoute des cieux, agis et juge tes serviteurs, en donnant au méchant son salaire, et faisant retomber sa conduite sur sa tête; en justifiant le juste, et lui rendant selon sa justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Quand ton peuple d’Israël aura été battu par l’ennemi, pour avoir péché contre toi; s’ils retournent à toi, s’ils donnent gloire à ton nom, s’ils t’adressent dans cette maison des prières et des supplications;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'Toi, exauce-les des cieux, et pardonne le péché de ton peuple d’Israël, et ramène-les dans la terre que tu as donnée à eux et à leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Quand les cieux seront fermés, et qu’il n’y aura point de pluie, parce qu’ils auront péché contre toi; s’ils prient en ce lieu, s’ils donnent gloire à ton nom, et s’ils se détournent de leurs péchés, parce que tu les auras affligés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'Toi, exauce-les des cieux, et pardonne le péché de tes serviteurs et de ton peuple d’Israël, après que tu leur auras enseigné le bon chemin, par lequel ils doivent marcher; et envoie de la pluie sur la terre que tu as donnée en héritage à ton peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Quand il y aura dans le pays la famine ou la peste, quand il y aura la rouille, la nielle, les sauterelles ou les chenilles, quand les ennemis les assiégeront dans leur pays, dans leurs portes, ou qu’il y aura une plaie, une maladie quelconque;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'Quelque prière, quelque supplication que fasse quelque homme que ce soit de tout ton peuple d’Israël, selon qu’ils auront reconnu chacun sa plaie et sa douleur, et que chacun aura étendu ses mains vers cette maison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'Toi, exauce-les des cieux, du lieu de ta demeure, et pardonne; rends à chacun selon toutes ses voies, toi qui connais son cœur; car seul tu connais le cœur des enfants des hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'Afin qu’ils te craignent, pour marcher dans tes voies, tout le temps qu’ils vivront sur la terre que tu as donnée à nos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Et l’étranger lui-même, qui ne sera pas de ton peuple d’Israël, mais qui viendra d’un pays éloigné, à cause de ton grand nom, de ta main forte, et de ton bras étendu; quand il viendra prier dans cette maison,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'Toi, exauce-le des cieux, du lieu de ta demeure, et fais tout ce que cet étranger réclamera de toi; afin que tous les peuples de la terre connaissent ton nom, qu’ils te craignent comme ton peuple d’Israël, et sachent que ton nom est invoqué sur cette maison que j’ai bâtie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Quand ton peuple sortira en guerre contre ses ennemis, par le chemin où tu l’auras envoyé; s’ils te prient, en regardant vers cette ville que tu as choisie, et vers cette maison que j’ai bâtie à ton nom,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'Exauce des cieux leur prière et leur supplication, et fais-leur droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Quand ils auront péché contre toi (car il n’y a point d’homme qui ne pèche), et que, irrité contre eux, tu les auras livrés à leurs ennemis, et que ceux qui les auront pris les auront emmenés captifs en quelque pays, soit au loin, soit au près;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'Si, dans le pays où ils seront captifs, ils rentrent en eux-mêmes, et que, se repentant, ils prient dans le pays de leur captivité, en disant: Nous avons péché, nous avons commis l’iniquité, nous avons agi méchamment!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'S’ils retournent à toi de tout leur cœur et de toute leur âme, dans le pays de leur captivité où on les aura emmenés captifs, et s’ils t’adressent leurs prières, en regardant vers leur pays, que tu as donné à leurs pères, vers cette ville que tu as choisie, et vers cette maison que j’ai bâtie à ton nom;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'Exauce des cieux, du lieu de ta demeure, leurs prières et leurs supplications, et fais-leur droit; pardonne à ton peuple qui aura péché contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Maintenant, ô mon Dieu! que tes yeux soient ouverts et que tes oreilles soient attentives à la prière faite en ce lieu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Et maintenant, Éternel Dieu! lève-toi, viens au lieu de ton repos, toi et l’arche de ta force. Éternel Dieu, que tes sacrificateurs soient revêtus de salut, et que tes bien-aimés se réjouissent de leur bonheur!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Éternel Dieu, ne repousse pas ton oint; souviens-toi des grâces accordées à David, ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Lorsque Salomon eut achevé de prier, le feu descendit du ciel et consuma l’holocauste et les sacrifices; et la gloire de l’Éternel remplit la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Et les sacrificateurs ne pouvaient entrer dans la maison de l’Éternel, parce que la gloire de l’Éternel avait rempli la maison de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Tous les enfants d’Israël virent descendre le feu et la gloire de l’Éternel sur la maison; et ils se courbèrent, le visage en terre, sur le pavé, se prosternèrent, et louèrent l’Éternel, en disant: Car il est bon, car sa miséricorde demeure éternellement!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Or le roi et tout le peuple offraient des sacrifices devant l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Et le roi Salomon offrit un sacrifice de vingt-deux mille bœufs, et cent vingt mille brebis. Ainsi le roi et tout le peuple firent la dédicace de la maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Et les sacrificateurs se tenaient à leurs postes, ainsi que les Lévites, avec les instruments de musique de l’Éternel, que le roi David avait faits pour louer l’Éternel en disant: Car sa miséricorde demeure éternellement! quand David le célébrait par leur moyen. Et les sacrificateurs sonnaient des trompettes vis-à-vis d’eux, et tout Israël se tenait debout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Salomon consacra le milieu du parvis, qui est devant la maison de l’Éternel; car il offrit là les holocaustes et les graisses des sacrifices de prospérités, parce que l’autel d’airain que Salomon avait fait ne pouvait contenir les holocaustes, les offrandes et les graisses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Ainsi Salomon célébra, en ce temps-là, la fête pendant sept jours, avec tout Israël. Il y avait une fort grande assemblée, venue depuis l’entrée d’Hamath jusqu’au torrent d’Égypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Le huitième jour, ils firent une assemblée solennelle; car ils firent la dédicace de l’autel pendant sept jours, et la fête pendant sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Le vingt-troisième jour du septième mois, il renvoya le peuple dans ses tentes, joyeux et content, à cause du bien que l’Éternel avait fait à David, à Salomon, et à Israël, son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Salomon acheva donc la maison de l’Éternel et la maison du roi; et il réussit dans tout ce qu’il avait eu dessein de faire dans la maison de l’Éternel et dans la sienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Et l’Éternel apparut à Salomon pendant la nuit, et lui dit: J’ai exaucé ta prière, et je me suis choisi ce lieu pour une maison de sacrifices.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Si je ferme les cieux, et qu’il n’y ait point de pluie, et si je commande aux sauterelles de consumer le pays, et si j’envoie la peste parmi mon peuple;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'Et que mon peuple, sur lequel mon nom est invoqué, s’humilie, prie, et cherche ma face, et qu’il se détourne de ses mauvaises voies, alors je l’exaucerai des cieux, je pardonnerai ses péchés, et je guérirai son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Mes yeux seront désormais ouverts, et mes oreilles seront attentives à la prière faite en ce lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Maintenant j’ai choisi et j’ai sanctifié cette maison, afin que mon nom y soit à toujours; mes yeux et mon cœur seront toujours là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Et toi, si tu marches devant moi comme David, ton père, a marché, faisant tout ce que je t’ai commandé, et si tu gardes mes lois et mes ordonnances,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'J’affermirai le trône de ton royaume, comme je l’ai promis à David, ton père, en disant: Il ne te manquera point de successeur qui règne en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Mais si vous vous détournez, et que vous abandonniez mes lois et mes commandements que je vous ai prescrits, et que vous alliez servir d’autres dieux, et vous prosterner devant eux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'Je vous arracherai de mon pays que je vous ai donné, je rejetterai loin de moi cette maison que j’ai consacrée à mon nom, et j’en ferai la fable et la risée de tous les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Et pour ce qui est de cette maison, qui aura été si haut élevée, quiconque passera près d’elle sera étonné, et dira: Pourquoi l’Éternel a-t-il ainsi traité ce pays et cette maison?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Et on répondra: Parce qu’ils ont abandonné l’Éternel, le Dieu de leurs pères, qui les fit sortir du pays d’Égypte, et qu’ils se sont attachés à d’autres dieux, et qu’ils se sont prosternés devant eux, et les ont servis; c’est pour cela qu’il a fait venir sur eux tous ces maux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Il arriva, au bout des vingt ans pendant lesquels Salomon bâtit la maison de l’Éternel et la sienne,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Qu’il bâtit les villes que Huram lui avait données, et y fit habiter les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Puis Salomon marcha contre Hamath, de Tsoba, et s’en empara.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Il bâtit Thadmor au désert, et toutes les villes servant de magasin qu’il bâtit dans le pays de Hamath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Il bâtit Beth-Horon la haute, et Beth-Horon la basse, villes fortes avec murailles, portes et barres;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'Baalath, et toutes les villes servant de magasin, qu’avait Salomon, et toutes les villes pour les chars, et les villes pour la cavalerie, et tout ce que Salomon prit plaisir à bâtir à Jérusalem, et au Liban, et dans tout le pays de sa domination.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Tout le peuple qui était resté des Héthiens, des Amoréens, des Phéréziens, des Héviens et des Jébusiens, qui n’étaient point d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'Leurs descendants, qui étaient restés après eux dans le pays, et que les enfants d’Israël n’avaient pas détruits, Salomon en fit des levées pour la corvée, jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Salomon n’employa comme esclave pour ses travaux aucun des enfants d’Israël; mais ils étaient gens de guerre, et chefs de ses meilleurs guerriers, et chefs de ses chars et de sa cavalerie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Et voici le nombre des chefs de ceux qui étaient préposés aux travaux du roi Salomon; ils étaient deux cent cinquante, ayant autorité sur le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Or Salomon fit monter la fille de Pharaon, de la cité de David dans la maison qu’il lui avait bâtie; car il dit: Ma femme n’habitera point dans la maison de David, roi d’Israël, parce que les lieux où l’arche de l’Éternel est entrée sont saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Alors Salomon offrit des holocaustes à l’Éternel sur l’autel de l’Éternel qu’il avait bâti devant le portique,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Offrant chaque jour ce qui était prescrit par Moïse, pour les sabbats, pour les nouvelles lunes, et pour les fêtes, trois fois l’année, à la fête des pains sans levain, à la fête des semaines, et à la fête des tabernacles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Il établit, selon l’ordonnance de David, son père, les classes des sacrificateurs selon leur office, et les Lévites selon leurs charges, pour célébrer l’Éternel et pour faire, jour par jour, le service en présence des sacrificateurs, et les portiers, selon leurs classes, à chaque porte; car tel était le commandement de David, homme de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'On ne s’écarta point du commandement du roi, pour les sacrificateurs et les Lévites, ni pour aucune chose, ni pour les trésors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Ainsi fut préparée toute l’œuvre de Salomon, jusqu’au jour de la fondation de la maison de l’Éternel et jusqu’à ce qu’elle fût achevée. La maison de l’Éternel fut donc achevée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Alors Salomon alla à Etsjon-Guéber et à Éloth, sur le bord de la mer, dans le pays d’Édom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Et Huram lui envoya, sous la conduite de ses serviteurs, des navires et des serviteurs connaissant la mer. Ils allèrent avec les serviteurs de Salomon à Ophir, et ils y prirent quatre cent cinquante talents d’or, qu’ils apportèrent au roi Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Or la reine de Shéba, ayant appris la renommée de Salomon, vint à Jérusalem pour éprouver Salomon par des questions obscures. Elle avait un fort grand train, et des chameaux portant des aromates, de l’or en grande quantité et des pierres précieuses. Elle vint à Salomon, et elle lui dit tout ce qu’elle avait dans le cœur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Et Salomon lui expliqua tout ce qu’elle proposa; il n’y eut rien que Salomon n’entendît et qu’il ne lui expliquât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Alors, la reine de Shéba voyant la sagesse de Salomon, et la maison qu’il avait bâtie,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'Et les mets de sa table, et la demeure de ses serviteurs, l’ordre de service et les vêtements de ceux qui le servaient, et ses échansons et leurs vêtements, et sa montée, par où l’on montait à la maison de l’Éternel, elle fut toute hors d’elle-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Et elle dit au roi: Ce que j’ai entendu dire dans mon pays, de ton état et de ta sagesse, est véritable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Je ne croyais point ce qu’on en disait, jusqu’à ce que je sois venue, et que mes yeux l’aient vu; et voici, on ne m’avait pas rapporté la moitié de la grandeur de ta sagesse; tu surpasses ce que j’avais appris de la renommée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Heureux tes gens! heureux tes serviteurs qui se tiennent continuellement devant toi, et qui écoutent ta sagesse!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Béni soit l’Éternel, ton Dieu, qui t’a eu pour agréable, pour te placer sur son trône, comme roi pour l’Éternel, ton Dieu! C’est parce que ton Dieu aime Israël, pour le faire subsister à jamais, qu’il t’a établi roi sur eux pour faire droit et justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Et elle donna au roi cent vingt talents d’or, et une très grande quantité d’aromates, et des pierres précieuses; et il n’y eut plus d’aromates tels que ceux que la reine de Shéba donna au roi Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Les serviteurs de Huram et les serviteurs de Salomon, qui amenèrent de l’or d’Ophir, amenèrent aussi du bois de santal et des pierres précieuses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Le roi fit de ce bois de santal des escaliers pour la maison de l’Éternel et pour la maison du roi, et des harpes et des lyres pour les chantres. On n’en avait point vu auparavant de semblable dans le pays de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Et le roi Salomon donna à la reine de Shéba tout ce qu’elle souhaita, ce qu’elle demanda, plus qu’elle n’avait apporté au roi; et elle s’en retourna, et revint en son pays, elle et ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Le poids de l’or qui arrivait à Salomon chaque année, était de six cent soixante-six talents d’or;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'Outre ce qu’il retirait des négociants et des marchands qui en apportaient, et de tous les rois d’Arabie et des gouverneurs du pays, qui apportaient de l’or et de l’argent à Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Le roi Salomon fit deux cents grands boucliers d’or battu employant six cents sicles d’or battu, pour chaque bouclier;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'Et trois cents boucliers plus petits d’or battu, employant trois cents sicles d’or pour chaque bouclier; et le roi les mit dans la maison de la Forêt du Liban.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Le roi fit aussi un grand trône d’ivoire, qu’il couvrit d’or pur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Ce trône avait six degrés et un marche-pied d’or qui tenaient au trône; et il avait des accoudoirs de l’un et de l’autre côté du siège; et deux lions se tenaient auprès des accoudoirs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Et douze lions se tenaient là sur les six degrés, des deux côtés. Rien de pareil n’avait été fait pour aucun royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Et tous les vases à boire du roi Salomon étaient d’or, et toute la vaisselle de la maison de la Forêt du Liban était d’or pur; rien n’était d’argent; on n’en faisait aucun cas du vivant de Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Car les navires du roi allaient à Tarsis avec les serviteurs de Huram; et tous les trois ans une fois arrivaient les navires de Tarsis, apportant de l’or, de l’argent, des dents d’éléphants, des singes et des paons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Ainsi le roi Salomon fut plus grand que tous les rois de la terre, en richesses et en sagesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Tous les rois de la terre recherchaient la face de Salomon, pour entendre la sagesse que Dieu lui avait mise dans le cœur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Et chacun d’eux apportait son présent, des vases d’argent, et des vases d’or, des vêtements, des armes, des aromates, des chevaux et des mulets, année par année.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Salomon avait quatre mille râteliers de chevaux, avec des chars, et douze mille cavaliers, qu’il mit dans les villes des chars, et auprès du roi à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Il dominait sur tous les rois depuis le fleuve jusqu’au pays des Philistins, et jusqu’à la frontière d’Égypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Et le roi fit que l’argent était aussi commun à Jérusalem que les pierres, et les cèdres aussi nombreux que les sycomores qui sont dans la plaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'On tirait des chevaux pour Salomon, de l’Égypte et de tous les pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Quant au reste des actions de Salomon, les premières et les dernières, cela n’est-il pas écrit dans le livre de Nathan, le prophète, dans la prophétie d’Achija, le Silonite, et dans la vision de Jéeddo, le Voyant, touchant Jéroboam, fils de Nébat?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Salomon régna quarante ans à Jérusalem sur tout Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Puis Salomon s’endormit avec ses pères, et on l’ensevelit dans la cité de David, son père; et Roboam, son fils, régna à sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Roboam se rendit à Sichem, car tout Israël était venu à Sichem pour l’établir roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Quand Jéroboam, fils de Nébat, qui était en Égypte, où il s’était enfui de devant le roi Salomon, l’eut appris, il revint d’Égypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Or on l’avait envoyé appeler. Ainsi Jéroboam et tout Israël vinrent et parlèrent à Roboam, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Ton père a mis sur nous un joug pesant; allège maintenant cette rude servitude de ton père, et ce joug pesant qu’il nous a imposé, et nous te servirons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Alors il leur dit: Revenez vers moi dans trois jours. Ainsi le peuple s’en alla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Et le roi Roboam consulta les vieillards qui avaient été auprès de Salomon, son père, pendant sa vie, et il leur dit: Quelle réponse me conseillez-vous de faire à ce peuple?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Et ils lui répondirent en ces termes: Si tu es bon envers ce peuple, si tu es bienveillant envers eux, et que tu leur dises de bonnes paroles, ils seront tes serviteurs à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Mais il laissa le conseil que les vieillards lui avaient donné, et il consulta les jeunes gens qui avaient grandi avec lui, et qui se tenaient devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Et il leur dit: Que me conseillez-vous de répondre à ce peuple, qui m’a parlé, et m’a dit: Allège le joug que ton père a mis sur nous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Et les jeunes gens qui avaient grandi avec lui, lui répondirent, en disant: Tu diras ainsi à ce peuple qui t’a parlé, et t’a dit: Ton père a mis sur nous un joug pesant, mais toi, allège-le; tu leur répondras ainsi: Mon petit doigt est plus gros que les reins de mon père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Or, mon père vous a imposé un joug pesant, mais moi, je rendrai votre joug plus pesant encore. Mon père vous a châtiés avec des fouets, mais moi, je vous châtierai avec des fouets garnis de pointes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Trois jours après, Jéroboam avec tout le peuple vint vers Roboam, suivant ce que le roi avait dit: Revenez vers moi dans trois jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Mais le roi leur répondit rudement, et le roi Roboam ne suivit point le conseil des vieillards;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'Il leur parla suivant le conseil des jeunes gens, et leur dit: Mon père a mis sur vous un joug pesant; mais moi, j’y ajouterai encore. Mon père vous a châtiés avec des fouets; mais moi, je vous châtierai avec des fouets garnis de pointes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Le roi n’écouta donc point le peuple; car cela était dispensé de la part de Dieu, afin que l’Éternel ratifiât la parole qu’il avait prononcée par Achija, le Silonite, à Jéroboam, fils de Nébat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Et quand tout Israël vit que le roi ne les écoutait point, le peuple répondit au roi, en disant: Quelle part avons-nous avec David? Nous n’avons point d’héritage avec le fils d’Isaï. Israël, chacun à ses tentes! Maintenant, David, pourvois à ta maison. Ainsi tout Israël s’en alla dans ses tentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Mais quant aux enfants d’Israël qui habitaient les villes de Juda, Roboam régna sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Alors le roi Roboam envoya Hadoram, qui était préposé aux impôts; mais les enfants d’Israël l’assommèrent à coups de pierres, et il mourut. Et le roi Roboam se hâta de monter sur un char pour s’enfuir à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'C’est ainsi qu’Israël s’est rebellé contre la maison de David, jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Roboam, étant arrivé à Jérusalem, assembla la maison de Juda et de Benjamin, cent quatre-vingt mille hommes de guerre choisis, pour combattre contre Israël, pour ramener le royaume à Roboam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Mais la parole de l’Éternel fut adressée à Shémaeja, homme de Dieu, en ces termes:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Parle à Roboam, fils de Salomon, roi de Juda, et à tout Israël en Juda et en Benjamin, et dis-leur:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Ainsi dit l’Éternel: Vous ne monterez point, et vous ne combattrez point contre vos frères; retournez- vous-en, chacun dans sa maison; car ceci vient de moi. Et ils obéirent aux paroles de l’Éternel, et s’en retournèrent, renonçant à marcher contre Jéroboam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Roboam demeura donc à Jérusalem, et il bâtit des villes fortes en Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Il bâtit Bethléhem, Étam, Thékoa,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Beth-Tsur, Soco, Adullam,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gath, Marésha, Ziph,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraïm, Lakis, Azéka,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Tsoréa, Ajalon et Hébron, qui étaient en Juda et en Benjamin, et en fit des villes fortes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Il les fortifia, et y mit des gouverneurs et des provisions de vivres, d’huile et de vin,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'Et, dans chacune de ces villes, des boucliers et des lances, et il les rendit très fortes. Ainsi Juda et Benjamin furent à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Les sacrificateurs et les Lévites, qui étaient dans tout Israël, vinrent de toutes parts se ranger auprès de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Car les Lévites abandonnèrent leurs banlieues et leurs propriétés et vinrent en Juda et à Jérusalem, parce que Jéroboam, avec ses fils, les avaient rejetés des fonctions de sacrificateurs à l’Éternel,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'Et s’était établi des sacrificateurs pour les hauts lieux et les démons, et pour les veaux qu’il avait faits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Et à leur suite, de toutes les tribus d’Israël, ceux qui avaient à cœur de chercher l’Éternel, le Dieu d’Israël, vinrent à Jérusalem pour sacrifier à l’Éternel, le Dieu de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Et ils fortifièrent le royaume de Juda et affermirent Roboam, fils de Salomon, pendant trois ans; car on suivit les voies de David et de Salomon pendant trois ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Or Roboam prit pour femme Mahalath, fille de Jérimoth, fils de David, et d’Abichaïl, fille d’Éliab, fils d’Isaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Elle lui enfanta des fils: Jéush, Shémaria et Zaham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Après elle, il prit Maaca, fille d’Absalom, qui lui enfanta Abija, Atthaï, Ziza et Shélomith.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Et Roboam aima Maaca, fille d’Absalom, plus que toutes ses femmes et ses concubines. Car il prit dix-huit femmes et soixante concubines, et il engendra vingt-huit fils et soixante filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Roboam établit pour chef Abija, fils de Maaca, comme prince entre ses frères; car il voulait le faire roi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Et il agit prudemment et dispersa tous ses fils dans toutes les contrées de Juda et de Benjamin, dans toutes les villes fortes; il leur donna abondamment de quoi vivre, et demanda pour eux une multitude de femmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Lorsque la royauté de Roboam se fut affermie et qu’il fut devenu fort, il abandonna la loi de l’Éternel, et tout Israël avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Et il arriva, la cinquième année du roi Roboam, que Shishak, roi d’Égypte, monta contre Jérusalem, parce qu’ils avaient péché contre l’Éternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'Il avait douze cents chars et soixante mille cavaliers, et le peuple venu avec lui d’Égypte était innombrable, des Libyens, des Sukkiens et des Éthiopiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Il prit les villes fortes qui appartenaient à Juda, et vint jusqu’à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Alors Shémaeja, le prophète, vint vers Roboam et vers les chefs de Juda, qui s’étaient assemblés à Jérusalem, à l’approche de Shishak, et leur dit: Ainsi a dit l’Éternel: Vous m’avez abandonné; moi aussi je vous abandonne aux mains de Shishak.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Alors les chefs d’Israël et le roi s’humilièrent, et dirent: L’Éternel est juste!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Et quand l’Éternel vit qu’ils s’étaient humiliés, la parole de l’Éternel fut adressée à Shémaeja, et il lui dit: Ils se sont humiliés; je ne les détruirai pas; et je leur donnerai bientôt un moyen d’échapper, et mon courroux ne se répandra point sur Jérusalem par la main de Shishak.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Toutefois ils lui seront asservis, afin qu’ils sachent ce que c’est que de me servir ou de servir les royaumes des autres pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Shishak, roi d’Égypte, monta donc contre Jérusalem, et prit les trésors de la maison de l’Éternel, et les trésors de la maison royale; il prit tout. Il prit les boucliers d’or que Salomon avait faits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'Le roi Roboam fit à leur place des boucliers d’airain, et il les mit entre les mains des chefs des coureurs qui gardaient la porte de la maison du roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Et toutes les fois que le roi entrait dans la maison de l’Éternel, les coureurs venaient, et les portaient; puis ils les rapportaient dans la chambre des coureurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Ainsi comme il s’était humilié, la colère de l’Éternel se détourna de lui, et ne le détruisit pas entièrement; car il y avait encore de bonnes choses en Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Le roi Roboam se fortifia donc dans Jérusalem, et régna. Il avait quarante et un ans quand il devint roi, et il régna dix-sept ans à Jérusalem, la ville que l’Éternel avait choisie, de toutes les tribus d’Israël, pour y mettre son nom. Sa mère s’appelait Naama, l’Ammonite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Il fit le mal, car il n’appliqua pas son cœur à chercher l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Or les actions de Roboam, les premières et les dernières, ne sont- elles pas écrites dans les livres de Shémaeja, le prophète, et d’Iddo, le Voyant, aux généalogies? Et les guerres de Roboam et de Jéroboam furent continuelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Et Roboam s’endormit avec ses pères, et il fut enseveli dans la cité de David; et Abija, son fils, régna à sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'La dix-huitième année du roi Jéroboam, Abija commença à régner sur Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Il régna trois ans à Jérusalem. Sa mère s’appelait Micaja, fille d’Uriel, de Guibea. Or il y eut guerre entre Abija et Jéroboam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Abija engagea la guerre avec une armée de vaillants guerriers, quatre cent mille hommes d’élite; et Jéroboam se rangea en bataille contre lui avec huit cent mille hommes d’élite, vaillants guerriers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Et Abija se tint sur la montagne de Tsémaraïm, qui est dans la montagne d’Éphraïm, et dit: Jéroboam et tout Israël, écoutez-moi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Ne devez-vous pas savoir que l’Éternel, le Dieu d’Israël, a donné pour toujours la royauté sur Israël, à David, à lui et à ses fils, par une alliance inviolable!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Mais Jéroboam, fils de Nébat, serviteur de Salomon, fils de David, s’est élevé, et s’est révolté contre son seigneur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Et des gens de rien, des misérables se sont joints à lui et se sont fortifiés contre Roboam, fils de Salomon. Or Roboam était un enfant et de faible courage, et il ne tint pas devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Et maintenant, vous pensez tenir devant la royauté de l’Éternel, qui est entre les mains des fils de David; et vous êtes une grande multitude, et vous avez avec vous les veaux d’or que Jéroboam vous a faits pour être vos dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'N’avez-vous pas repoussé les sacrificateurs de l’Éternel, les fils d’Aaron, et les Lévites? Et ne vous êtes-vous pas fait des sacrificateurs à la façon des peuples des autres pays? Quiconque est venu, pour être consacré, avec un jeune taureau et sept béliers, est devenu sacrificateur de ce qui n’est pas Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Mais pour nous, l’Éternel est notre Dieu, et nous ne l’avons point abandonné; les sacrificateurs qui font le service de l’Éternel, sont enfants d’Aaron, et ce sont les Lévites qui fonctionnent,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'Faisant fumer pour l’Éternel, chaque matin et chaque soir, les holocaustes et le parfum d’aromates. Les pains de proposition sont rangés sur la table pure, et on allume le chandelier d’or, avec ses lampes, chaque soir. Car nous gardons ce que l’Éternel notre Dieu veut qu’on garde; mais vous, vous l’avez abandonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Voici, Dieu et ses sacrificateurs sont avec nous, à notre tête, et les trompettes au son éclatant, pour les faire retentir contre vous. Enfants d’Israël, ne combattez pas contre l’Éternel, le Dieu de vos pères; car cela ne vous réussira point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Mais Jéroboam fit faire un détour à une embuscade, pour arriver derrière eux. Ainsi les Israélites étaient en face de Juda, et l’embuscade était derrière ceux-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Ceux de Juda regardèrent donc, et voici, ils avaient la bataille en face et par-derrière. Alors ils crièrent à l’Éternel, et les sacrificateurs sonnèrent des trompettes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Et tous les hommes de Juda poussèrent un cri de guerre, et au cri de guerre des hommes de Juda, Dieu frappa Jéroboam et tout Israël devant Abija et Juda;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Et les enfants d’Israël s’enfuirent devant ceux de Juda, et Dieu les livra entre leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Abija et son peuple en firent un grand carnage, et il tomba d’Israël cinq cent mille hommes d’élite blessés à mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Ainsi les enfants d’Israël furent humiliés en ce temps-là; et les enfants de Juda devinrent forts, parce qu’ils s’étaient appuyés sur l’Éternel, le Dieu de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Or Abija poursuivit Jéroboam, et lui prit ces villes: Béthel et les villes de son ressort, Jeshana et les villes de son ressort, Éphron et les villes de son ressort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Jéroboam n’eut plus de force pendant le temps d’Abija; et l’Éternel le frappa, et il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Mais Abija devint puissant. Il prit quatorze femmes, et engendra vingt-deux fils et seize filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Le reste des actions d’Abija, et sa conduite, et ses paroles sont écrites dans les mémoires du prophète Iddo.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Abija s’endormit avec ses pères, et on l’ensevelit dans la cité de David; et Asa son fils régna à sa place. De son temps, le pays fut en repos pendant dix ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Asa fit ce qui est bon et droit aux yeux de l’Éternel, son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Il ôta les autels étrangers et les hauts lieux; il brisa les statues et mit en pièces les emblèmes d’Ashéra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Et il recommanda à Juda de rechercher l’Éternel, le Dieu de leurs pères, et de pratiquer la loi et les commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Il ôta de toutes les villes de Juda les hauts lieux et les colonnes consacrées au soleil. Et le royaume fut en repos devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Il bâtit des villes fortes en Juda; car le pays fut en repos; et pendant ces années-là il n’y eut point de guerre contre lui, parce que l’Éternel lui donna du repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Et il dit à Juda: Bâtissons ces villes, et environnons-les de murailles, de tours, de portes et de barres; le pays est encore devant nous, parce que nous avons recherché l’Éternel notre Dieu; nous l’avons recherché, et il nous a donné du repos de tous côtés. Ainsi ils bâtirent et prospérèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Or Asa avait une armée de trois cent mille hommes de Juda, portant le grand bouclier et la lance, et de deux cent quatre-vingt mille de Benjamin, portant le petit bouclier et tirant de l’arc, tous vaillants guerriers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Mais Zérach, l’Éthiopien, sortit contre eux avec une armée d’un million d’hommes, et de trois cents chars; et il vint jusqu’à Marésha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Et Asa alla au-devant de lui, et ils se rangèrent en bataille dans la vallée de Tséphatha, près de Marésha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Alors Asa cria à l’Éternel son Dieu, et dit: Éternel! Tu ne fais point de différence pour aider, que l’on soit nombreux ou sans force! Aide-nous, Éternel, notre Dieu! car nous nous sommes appuyés sur toi, et nous sommes venus en ton nom contre cette multitude. Tu es l’Éternel, notre Dieu: que l’homme ne prévale pas contre toi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Et l’Éternel frappa les Éthiopiens devant Asa et devant Juda; et les Éthiopiens s’enfuirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Asa et le peuple qui était avec lui, les poursuivirent jusqu’à Guérar, et il tomba tant d’Éthiopiens, qu’ils ne purent se remettre; car ils furent écrasés devant l’Éternel et son armée, et on emporta un fort grand butin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Ils frappèrent toutes les villes autour de Guérar, car la terreur de l’Éternel était sur elles; et ils pillèrent toutes ces villes, car il s’y trouvait beaucoup de butin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Ils frappèrent aussi les tentes des troupeaux, et emmenèrent des brebis et des chameaux en abondance; puis ils retournèrent à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Alors l’Esprit de Dieu fut sur Azaria, fils d’Oded.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Et il sortit au-devant d’Asa, et lui dit: Asa, et tout Juda et Benjamin, écoutez-moi! L’Éternel est avec vous quand vous êtes avec lui. Si vous le cherchez, vous le trouverez; mais si vous l’abandonnez, il vous abandonnera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Pendant longtemps Israël a été sans vrai Dieu, sans sacrificateur qui enseignât, et sans loi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Mais dans sa détresse il revint à l’Éternel, le Dieu d’Israël; ils le recherchèrent, et il se laissa trouver d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Dans ces temps-là, il n’y avait point de sécurité pour ceux qui allaient et venaient, car il y avait de grands troubles parmi tous les habitants du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Une nation était heurtée par une autre, et une ville par une autre ville; car Dieu les agitait par toutes sortes d’angoisses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Mais vous, fortifiez-vous, et que vos mains ne soient point lâches; car il y a un salaire pour ce que vous ferez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Quand Asa eut entendu ces paroles et la prophétie d’Oded, le prophète, il se fortifia, et fit disparaître les abominations de tout le pays de Juda et de Benjamin, et des villes qu’il avait prises dans la montagne d’Éphraïm; et il rétablit l’autel de l’Éternel, qui était devant le portique de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Puis il rassembla tout Juda et Benjamin, et ceux d’Éphraïm, de Manassé et de Siméon, qui demeuraient avec eux; car un grand nombre de gens d’Israël passaient à lui, voyant que l’Éternel son Dieu était avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Ils s’assemblèrent donc à Jérusalem, le troisième mois de la quinzième année du règne d’Asa;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'Et ils sacrifièrent, ce jour-là, à l’Éternel, sept cents bœufs et sept mille brebis, du butin qu’ils avaient amené.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Et ils rentrèrent dans l’alliance, pour chercher l’Éternel, le Dieu de leurs pères, de tout leur cœur et de toute leur âme;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'En sorte qu’on devait faire mourir tous ceux qui ne rechercheraient pas l’Éternel, le Dieu d’Israël, tant les petits que les grands, tant les hommes que les femmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Et ils prêtèrent serment à l’Éternel, à haute voix, avec acclamation, et au son des trompettes et des cors;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Et tout Juda se réjouit de ce serment, parce qu’ils avaient juré de tout leur cœur, et qu’ils avaient recherché l’Éternel de leur plein gré, et qu’ils l’avaient trouvé. Et l’Éternel leur donna du repos de tous côtés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Le roi Asa destitua même de son rang sa mère, Maaca, parce qu’elle avait fait une idole pour Ashéra. Asa abattit son idole, la mit en pièces, et la brûla au torrent de Cédron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Mais les hauts lieux ne furent point ôtés du milieu d’Israël; néanmoins le cœur d’Asa fut intègre tout le long de ses jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Il remit dans la maison de Dieu les choses qui avaient été consacrées par son père, avec ce qu’il avait lui-même consacré, l’argent, l’or et les ustensiles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Et il n’y eut point de guerre jusqu’à la trente-cinquième année du règne d’Asa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'La trente-sixième année du règne d’Asa, Baesha, roi d’Israël, monta contre Juda, et il bâtit Rama, afin de ne laisser sortir ni entrer aucun homme pour Asa, roi de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Alors Asa tira de l’argent et de l’or des trésors de la maison de l’Éternel et de la maison royale, et il envoya vers Ben-Hadad, roi de Syrie, qui habitait à Damas, pour lui dire:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Il y a alliance entre moi et toi, comme entre mon père et le tien; voici, je t’envoie de l’argent et de l’or; va, romps ton alliance avec Baesha, roi d’Israël, afin qu’il se retire de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Et Ben-Hadad écouta le roi Asa, et il envoya les capitaines de ses armées contre les villes d’Israël, et ils frappèrent Ijjon, Dan, Abel-Maïm, et tous les magasins des villes de Nephthali.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Et aussitôt que Baesha l’eut appris, il cessa de bâtir Rama et suspendit son travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Alors le roi Asa prit avec lui tout Juda, et ils emportèrent les pierres et le bois de Rama, que Baesha faisait bâtir; et il en bâtit Guéba et Mitspa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'En ce temps-là, Hanani, le voyant, vint vers Asa, roi de Juda, et lui dit: Parce que tu t’es appuyé sur le roi de Syrie, et que tu ne t’es point appuyé sur l’Éternel, ton Dieu, l’armée du roi de Syrie a échappé de ta main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Les Éthiopiens et les Libyens n’étaient-ils pas une fort grande armée, ayant des chars et des cavaliers en fort grand nombre? Mais parce que tu t’appuyais sur l’Éternel, il les livra entre tes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Car les yeux de l’Éternel parcourent toute la terre, pour soutenir ceux dont le cœur est tout entier à lui. Tu as agi follement en cela; car désormais tu auras des guerres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Et Asa fut irrité contre le voyant, et le mit en prison, car il était fort indigné contre lui à ce sujet. Asa opprima aussi, en ce temps-là, quelques-uns du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Or voici, les actions d’Asa, les premières et les dernières, sont écrites au livre des rois de Juda et d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'La trente-neuvième année de son règne, Asa fut malade des pieds, et sa maladie fut très grave; et toutefois dans sa maladie, il ne chercha point l’Éternel, mais les médecins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Puis Asa s’endormit avec ses pères, et il mourut la quarante et unième année de son règne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Et on l’ensevelit dans le tombeau qu’il s’était creusé dans la cité de David. On le coucha sur un lit qu’il avait rempli de parfums et d’aromates, préparés en ouvrage de parfumerie; et on lui en brûla une quantité très considérable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Josaphat, son fils, régna à sa place, et se fortifia contre Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Il mit des troupes dans toutes les villes fortes de Juda, et des garnisons dans le pays de Juda, et dans les villes d’Éphraïm qu’Asa, son père, avait prises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Et l’Éternel fut avec Josaphat, parce qu’il suivit les premières voies de David, son père, et qu’il ne rechercha point les Baalim;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Car il rechercha le Dieu de son père, et il marcha dans ses commandements, et non pas selon ce que faisait Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'L’Éternel affermit donc le royaume entre ses mains; et tout Juda apportait des présents à Josaphat, et il eut richesse et gloire en abondance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Son cœur s’enhardit dans les voies de l’Éternel, et il ôta encore de Juda les hauts lieux et les emblèmes d’Ashéra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Puis, la troisième année de son règne, il envoya ses chefs Benhaïl, Obadia, Zacharie, Nathanaël et Micaja, pour enseigner dans les villes de Juda;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'Et avec eux les Lévites Shémaja, Néthania, Zébadia, Asaël, Shémiramoth, Jonathan, Adonija, Tobija et Tob-Adonija, Lévites, et avec eux Élishama et Joram, sacrificateurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Ils enseignèrent en Juda, ayant avec eux le livre de la loi de l’Éternel. Ils firent le tour de toutes les villes de Juda, et enseignèrent parmi le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Et la terreur de l’Éternel fut sur tous les royaumes des pays qui entouraient Juda, et ils ne firent point la guerre à Josaphat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Même de chez les Philistins on apportait des présents à Josaphat, et un tribut d’argent; et les Arabes lui amenèrent aussi du bétail, sept mille sept cents béliers, et sept mille sept cents boucs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Ainsi Josaphat alla grandissant jusqu’au plus haut degré. Et il bâtit en Juda des châteaux et des villes à magasins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Il fit de grands travaux dans les villes de Juda; et il avait des gens de guerre, hommes vaillants, à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Et voici leur dénombrement, selon les maisons de leurs pères. Les chefs de milliers de Juda furent: Adna, le chef, avec trois cent mille vaillants guerriers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'A côté de lui, Jochanan, le chef, avec deux cent quatre-vingt mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'A côté de lui, Amasia, fils de Zicri, qui s’était volontairement offert à l’Éternel, avec deux cent mille vaillants guerriers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'De Benjamin, Éliada, vaillant guerrier, avec deux cent mille hommes, armés de l’arc et du bouclier;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'A côté de lui Jéhozabad, avec cent quatre-vingt mille hommes équipés pour l’armée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Tels sont ceux qui étaient au service du roi, outre ceux que le roi avait mis dans les villes fortes, dans tout Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Or, Josaphat, ayant beaucoup de richesses et de gloire, s’allia par mariage avec Achab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Et au bout de quelques années, il descendit vers Achab, à Samarie. Et Achab tua pour lui, et pour le peuple qui était avec lui, un grand nombre de brebis et de bœufs, et l’incita à monter à Ramoth de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Achab, roi d’Israël, dit à Josaphat, roi de Juda: Viendras-tu avec moi à Ramoth de Galaad? Et il lui répondit: Dispose de moi comme de toi, et de mon peuple comme de ton peuple; et nous irons avec toi à la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Puis Josaphat dit au roi d’Israël: Consulte d’abord, je te prie, la parole de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Alors le roi d’Israël assembla les prophètes, au nombre de quatre cents, et leur dit: Irons-nous à la guerre contre Ramoth de Galaad, ou y renoncerai-je? Et ils répondirent: Monte, et Dieu la livrera entre les mains du roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Mais Josaphat dit: N’y a-t-il point ici encore quelque prophète de l’Éternel, par qui nous puissions le consulter?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Et le roi d’Israël dit à Josaphat: Il y a encore un homme par qui on peut consulter l’Éternel; mais je le hais, car il ne me prophétise rien de bon, mais toujours du mal; c’est Michée, fils de Jimla. Et Josaphat dit: Que le roi ne parle pas ainsi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Alors le roi d’Israël appela un officier, et dit: Fais promptement venir Michée, fils de Jimla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Or le roi d’Israël et Josaphat, roi de Juda, étaient assis, chacun sur son trône, revêtus de leurs habits royaux, et ils étaient assis dans la place, à l’entrée de la porte de Samarie; et tous les prophètes prophétisaient en leur présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Alors Tsidkija, fils de Kénaana, s’étant fait des cornes de fer, dit: Ainsi a dit l’Éternel: Avec ces cornes tu heurteras les Syriens, jusqu’à les détruire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Et tous les prophètes prophétisaient de même, en disant: Monte à Ramoth de Galaad, et tu réussiras, et l’Éternel la livrera entre les mains du roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Or le messager qui était allé appeler Michée, lui parla, et lui dit: Voici, les prophètes prédisent tous d’une voix du bien au roi; je te prie, que ta parole soit semblable à celle de chacun d’eux, et annonce du bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Mais Michée répondit: L’Éternel est vivant! je dirai ce que mon Dieu dira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Il vint donc vers le roi, et le roi lui dit: Michée, irons-nous à la guerre contre Ramoth de Galaad, ou y renoncerai-je? Et il répondit: Montez, vous réussirez, et ils seront livrés entre vos mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Et le roi lui dit: Combien de fois t’adjurerai-je de ne me dire que la vérité au nom de l’Éternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Et il répondit: J’ai vu tout Israël dispersé par les montagnes, comme un troupeau de brebis qui n’a point de pasteur; et l’Éternel a dit: Ces gens n’ont point de seigneur; que chacun retourne en paix dans sa maison!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Alors le roi d’Israël dit à Josaphat: Ne t’ai-je pas dit qu’il ne prophétise rien de bon quand il s’agit de moi, mais seulement du mal?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Et Michée dit: C’est pourquoi, écoutez la parole de l’Éternel: J’ai vu l’Éternel assis sur son trône, et toute l’armée des cieux se tenant à sa droite et à sa gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Et l’Éternel dit: Qui est-ce qui séduira Achab, roi d’Israël, afin qu’il monte et qu’il périsse à Ramoth de Galaad? Et l’un répondait d’une façon et l’autre d’une autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Alors un esprit s’avança et se tint devant l’Éternel, et dit: Moi, je le séduirai. L’Éternel lui dit: Comment?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Il répondit: Je sortirai, et je serai un esprit de mensonge dans la bouche de tous ses prophètes. Et l’Éternel dit: Tu le séduiras, et même tu en viendras à bout. Sors, et fais ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Maintenant donc, voici, l’Éternel a mis un esprit de mensonge dans la bouche de tes prophètes que voilà; et l’Éternel a prononcé du mal contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Alors Tsidkija, fils de Kénaana, s’approcha, et frappa Michée sur la joue, et dit: Par quel chemin l’Esprit de l’Éternel s’est-il éloigné de moi pour te parler?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Et Michée répondit: Voici, tu le verras au jour où tu iras de chambre en chambre pour te cacher!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Alors le roi d’Israël dit: Prenez Michée, et menez-le vers Amon, capitaine de la ville, et vers Joas, fils du roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'Et vous direz: Ainsi a dit le roi: Mettez cet homme en prison, et nourrissez-le du pain de l’affliction et de l’eau de l’affliction, jusqu’à ce que je revienne en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Et Michée dit: Si jamais tu reviens en paix, l’Éternel n’aura point parlé par moi. Et il dit: Vous tous, peuples, entendez!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Le roi d’Israël monta donc avec Josaphat, roi de Juda, à Ramoth de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Et le roi d’Israël dit à Josaphat: Je me déguiserai pour aller au combat; mais toi, revêts-toi de tes habits. Ainsi le roi d’Israël se déguisa; et ils allèrent au combat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Or le roi des Syriens avait donné cet ordre aux chefs de ses chars, disant: Vous n’attaquerez ni petit ni grand, mais seulement le roi d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Sitôt donc que les chefs des chars eurent vu Josaphat, ils dirent: C’est le roi d’Israël! et ils l’environnèrent pour l’attaquer; mais Josaphat cria, et l’Éternel le secourut, et Dieu les éloigna de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Et quand les chefs des chars virent que ce n’était pas le roi d’Israël, ils se détournèrent de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Alors un homme tira de son arc tout au hasard, et frappa le roi d’Israël entre les jointures de la cuirasse; et le roi dit au cocher: Tourne, et mène-moi hors des rangs; car je suis blessé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Or, en ce jour-là le combat fut acharné; et le roi d’Israël demeura dans son char, vis-à-vis des Syriens, jusqu’au soir; et il mourut vers le coucher du soleil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Josaphat, roi de Juda, revint sain et sauf dans sa maison, à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Mais Jéhu, fils de Hanani, le Voyant, sortit au-devant du roi Josaphat, et lui dit: Est-ce le méchant qu’il faut aider? Sont-ce les ennemis de l’Éternel que tu aimes? A cause de cela, l’Éternel est irrité contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Mais il s’est trouvé de bonnes choses en toi, car tu as ôté du pays les emblèmes d’Ashéra, et tu as appliqué ton cœur à rechercher Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Et Josaphat habita à Jérusalem. Puis, de nouveau, il sortit parmi le peuple, depuis Béer-Shéba jusqu’à la montagne d’Éphraïm, et il les ramena à l’Éternel, le Dieu de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Il établit aussi des juges dans le pays, dans toutes les villes fortes de Juda, dans chaque ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Et il dit aux juges: Regardez à ce que vous ferez; car ce n’est pas pour l’homme que vous jugerez, mais pour l’Éternel, qui sera avec vous quand vous jugerez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Maintenant, que la crainte de l’Éternel soit sur vous; prenez garde à ce que vous ferez; car il n’y a point d’iniquité dans l’Éternel notre Dieu, ni d’acception de personnes, ni d’acceptation de présents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Josaphat établit aussi à Jérusalem des Lévites, et des sacrificateurs, et des chefs des pères d’Israël, pour le jugement de l’Éternel, et pour les contestations. Et on revint à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Et il leur donna des ordres, en disant: Vous agirez ainsi dans la crainte de l’Éternel, avec fidélité et avec intégrité de cœur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Et pour les différends qui viendront devant vous, de la part de vos frères qui habitent dans leurs villes, qu’il s’agisse d’un meurtre, d’une loi, d’un commandement, de statuts ou d’ordonnances, vous les éclairerez, afin qu’ils ne se rendent pas coupables envers l’Éternel, et qu’il n’y ait point de courroux sur vous et sur vos frères. Vous agirez ainsi, et vous ne serez point trouvés coupables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Et voici, Amaria, le principal sacrificateur, est préposé sur vous pour toutes les affaires de l’Éternel, et Zébadia, fils d’Ismaël, prince de la maison de Juda, pour toutes les affaires du roi; et pour secrétaires vous avez devant vous les Lévites. Fortifiez-vous et agissez; et que l’Éternel soit avec l’homme de bien!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Il arriva, après cela, que les enfants de Moab et les enfants d’Ammon (car avec eux il y avait des Ammonites), vinrent contre Josaphat pour lui faire la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'On vint donc le rapporter à Josaphat, en disant: Il vient contre toi une grande multitude d’au delà de la mer, de Syrie; et les voici à Hatsatson-Thamar, qui est En-Guédi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Alors Josaphat craignit; et il se disposa à rechercher l’Éternel, et il publia un jeûne pour tout Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Juda s’assembla donc pour demander du secours à l’Éternel; on vint même de toutes les villes de Juda pour chercher l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Et Josaphat se tint debout dans l’assemblée de Juda et de Jérusalem, dans la maison de l’Éternel, devant le nouveau parvis;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'Et il dit: Éternel, Dieu de nos pères! n’es-tu pas Dieu dans les cieux, et n’est-ce pas toi qui domines sur tous les royaumes des nations? Et n’as-tu pas en ta main la force et la puissance, en sorte que nul ne peut te résister?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'N’est-ce pas toi, ô notre Dieu! qui as dépossédé les habitants de ce pays devant ton peuple d’Israël, et qui l’as donné pour toujours à la postérité d’Abraham, qui t’aimait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Ils l’ont habité, et t’y ont bâti un sanctuaire pour ton nom, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'S’il nous arrive quelque mal, l’épée, le jugement, la peste, ou la famine, nous nous tiendrons devant cette maison, et en ta présence; car ton nom est en cette maison; et nous crierons à toi dans notre détresse, et tu exauceras et tu délivreras!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Maintenant, voici les enfants d’Ammon et de Moab, et ceux de la montagne de Séir, chez lesquels tu ne permis pas à Israël d’entrer, quand il venait du pays d’Égypte, car il se détourna d’eux, et ne les détruisit pas,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Les voici qui nous en récompensent, en venant nous chasser de ton héritage, dont tu nous as donné la possession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'O notre Dieu! ne les jugeras-tu pas? Car il n’y a point de force en nous devant cette grande multitude qui vient contre nous, et nous ne savons que faire; mais nos yeux sont sur toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Or tout Juda se tenait devant l’Éternel, même avec leurs familles, leurs femmes et leurs enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Alors l’Esprit de l’Éternel fut sur Jachaziel, fils de Zacharie, fils de Bénaja, fils de Jéïel, fils de Matthania, Lévite, d’entre les enfants d’Asaph, au milieu de l’assemblée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'Et il dit: Vous, tout Juda, et habitants de Jérusalem, et toi, roi Josaphat, soyez attentifs! Ainsi vous dit l’Éternel: Ne craignez point, et ne soyez point effrayés à cause de cette grande multitude; car ce ne sera pas à vous de combattre, mais à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Descendez demain contre eux; les voici qui montent par la montée de Tsits, et vous les trouverez à l’extrémité de la vallée, en face du désert de Jéruël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Ce ne sera point à vous de combattre en cette bataille; présentez- vous, tenez-vous là, et voyez la délivrance que l’Éternel va vous donner. Juda et Jérusalem, ne craignez point, et ne soyez point effrayés! Demain, sortez au-devant d’eux, et l’Éternel sera avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Alors Josaphat s’inclina le visage contre terre, et tout Juda et les habitants de Jérusalem se jetèrent devant l’Éternel, se prosternant devant l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Et les Lévites, d’entre les enfants des Kéhathites et d’entre les enfants des Corites, se levèrent pour célébrer l’Éternel, le Dieu d’Israël, d’une voix forte et haute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Puis, le matin, ils se levèrent de bonne heure et sortirent vers le désert de Thékoa; et comme ils sortaient, Josaphat se tint là et dit: Juda et vous, habitants de Jérusalem, écoutez-moi: Croyez en l’Éternel votre Dieu, et vous serez en sûreté; croyez en ses prophètes, et vous réussirez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Puis, ayant délibéré avec le peuple, il établit des chantres de l’Éternel, qui célébraient sa sainte magnificence; et, marchant devant l’armée, ils disaient: Louez l’Éternel, car sa miséricorde demeure à toujours!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Et au moment où ils commencèrent le chant et la louange, l’Éternel mit des embuscades contre les enfants d’Ammon, et de Moab, et ceux de la montagne de Séir, qui venaient contre Juda, et ils furent battus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Les enfants d’Ammon et de Moab se levèrent contre les habitants de la montagne de Séir, pour les vouer à l’interdit et les exterminer; et quand ils en eurent fini avec les habitants de Séir, ils s’aidèrent l’un l’autre à se détruire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Et quand Juda arriva sur la hauteur d’où l’on voit le désert, ils regardèrent vers cette multitude, et voici, c’étaient des cadavres gisant à terre, sans qu’il en fût échappé un seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Ainsi Josaphat et son peuple vinrent pour piller leur butin, et ils trouvèrent parmi eux, au milieu des cadavres, des biens en abondance, et des objets précieux; et ils en enlevèrent tant, qu’ils ne le pouvaient porter; et ils pillèrent le butin pendant trois jours, car il était considérable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Et, le quatrième jour, ils s’assemblèrent dans la vallée de Bénédiction; car ils bénirent là l’Éternel; c’est pourquoi, on a appelé ce lieu, jusqu’à ce jour, la vallée de Bénédiction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Puis tous les hommes de Juda et de Jérusalem, et Josaphat, à leur tête, reprirent joyeusement le chemin de Jérusalem; car l’Éternel leur avait donné de la joie au sujet de leurs ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Ils entrèrent donc à Jérusalem, dans la maison de l’Éternel, avec des lyres, des harpes et des trompettes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Et la terreur de Dieu fut sur tous les royaumes des divers pays, quand ils eurent appris que l’Éternel avait combattu contre les ennemis d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Ainsi le royaume de Josaphat fut tranquille, et son Dieu lui donna du repos de tous côtés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Josaphat régna donc sur Juda. Il était âgé de trente-cinq ans quand il devint roi, et il régna vingt-cinq ans à Jérusalem. Sa mère s’appelait Azuba, fille de Shilchi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Il suivit les traces d’Asa, son père, et il ne s’en détourna point, faisant ce qui est droit devant l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Seulement les hauts lieux ne furent point ôtés, et le peuple n’avait pas encore tourné son cœur vers le Dieu de ses pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Or le reste des actions de Josaphat, les premières et les dernières, voici, elles sont écrites dans les mémoires de Jéhu, fils de Hanani, insérés dans le livre des rois d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Après cela, Josaphat, roi de Juda, s’associa avec Achazia, roi d’Israël, dont la conduite était impie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Il s’associa avec lui pour faire des navires, afin d’aller à Tarsis; et ils firent des navires à Etsjon-Guéber.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Alors Éliézer, fils de Dodava, de Marésha, prophétisa contre Josaphat, en disant: Parce que tu t’es associé avec Achazia, l’Éternel a détruit ton œuvre. Et les navires furent brisés, et ne purent aller à Tarsis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Puis Josaphat s’endormit avec ses pères, et il fut enseveli avec eux dans la cité de David; et Joram, son fils, régna à sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Il avait des frères, fils de Josaphat, Azaria, Jéhiel, Zacharie, Azaria, Micaël et Shéphatia. Tous ceux-là étaient fils de Josaphat, roi d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Leur père leur avait fait de grands dons d’argent, d’or et de choses précieuses, avec des villes fortes en Juda; mais il avait donné le royaume à Joram, parce qu’il était l’aîné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Quand Joram se fut élevé sur le royaume de son père, et s’y fut fortifié, il fit mourir par l’épée tous ses frères, et quelques-uns aussi des chefs d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Joram était âgé de trente-deux ans, quand il devint roi, et il régna huit ans à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Il marcha dans la voie des rois d’Israël, comme avait fait la maison d’Achab; car la fille d’Achab était sa femme, et il fit ce qui est mal aux yeux de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Toutefois, l’Éternel, à cause de l’alliance qu’il avait traitée avec David, ne voulut pas détruire la maison de David, selon qu’il avait dit qu’il lui donnerait une lampe, à lui et à ses fils, pour toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'De son temps, Édom se révolta de l’obéissance de Juda, et ils établirent un roi sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Joram se mit donc en marche avec ses chefs et tous ses chars; et, s’étant levé de nuit, il battit les Édomites, qui l’entouraient, et tous les chefs des chars.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Néanmoins Édom s’est révolté contre l’autorité de Juda jusqu’à ce jour. En ce même temps, Libna se révolta contre son autorité, parce qu’il avait abandonné l’Éternel, le Dieu de ses pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Lui aussi fit des hauts lieux dans les montagnes de Juda; il fit que les habitants de Jérusalem se prostituèrent, et il y poussa ceux de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Alors il lui vint un écrit de la part d’Élie, le prophète, disant: Ainsi a dit l’Éternel, le Dieu de David, ton père: Parce que tu n’as point suivi les traces de Josaphat, ton père, ni celles d’Asa, roi de Juda,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'Mais que tu as suivi le train des rois d’Israël, et que tu débauches Juda et les habitants de Jérusalem, comme l’a fait la maison d’Achab, et que tu as tué tes frères, la maison de ton père, meilleurs que toi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'Voici l’Éternel va frapper d’une grande plaie ton peuple, tes enfants, tes femmes et tous tes biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Et toi, tu auras de grandes souffrances, par une maladie d’entrailles; jusque-là que tes entrailles sortiront par la force de la maladie, qui augmentera de jour en jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Et l’Éternel excita contre Joram l’esprit des Philistins et des Arabes, qui habitent près des Éthiopiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Ils montèrent donc contre Juda, et y pénétrèrent, et pillèrent toutes les richesses qui furent trouvées dans la maison du roi; et même, ils emmenèrent captifs ses enfants et ses femmes, de sorte qu’il ne lui demeura aucun fils, sinon Joachaz, le plus jeune de ses fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Après tout cela, l’Éternel le frappa dans ses entrailles, d’une maladie incurable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Et il arriva, au bout d’un certain temps, vers la fin de la seconde année, que ses entrailles sortirent par la force de sa maladie, et il mourut dans de grandes souffrances; son peuple ne fit point brûler sur lui de parfums, comme on avait fait sur ses pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Il était âgé de trente-deux ans quand il devint roi, et il régna huit ans à Jérusalem. Il s’en alla sans être regretté, et on l’ensevelit dans la cité de David, mais non dans les tombeaux des rois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Les habitants de Jérusalem établirent pour roi à sa place Achazia, le plus jeune de ses fils, parce que les troupes qui étaient venues au camp avec les Arabes, avaient tué tous les plus âgés; et Achazia, fils de Joram, roi de Juda, régna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Achazia était âgé de quarante-deux ans, quand il devint roi, et il régna un an à Jérusalem. Sa mère s’appelait Athalie, fille d’Omri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Il suivit aussi les voies de la maison d’Achab; car sa mère était sa conseillère pour faire du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Il fit donc ce qui est mauvais aux yeux de l’Éternel, comme la maison d’Achab; parce qu’ils furent ses conseillers après la mort de son père, pour sa ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Gouverné par leurs conseils, il alla même avec Joram, fils d’Achab, roi d’Israël, à la guerre, à Ramoth de Galaad, contre Hazaël, roi de Syrie. Et les Syriens frappèrent Joram,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Qui s’en retourna pour se faire guérir à Jizréel, des blessures que les Syriens lui avaient faites à Rama, lorsqu’il faisait la guerre contre Hazaël, roi de Syrie. Alors Azaria, fils de Joram, roi de Juda, descendit pour voir Joram, le fils d’Achab, à Jizréel, parce qu’il était malade.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Or ce fut pour son entière ruine, qui procédait de Dieu, qu’Achazia vint auprès de Joram. En effet, quand il fut arrivé, il sortit avec Joram au-devant de Jéhu, fils de Nimshi, que l’Éternel avait oint pour exterminer la maison d’Achab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Et il arriva, comme Jéhu faisait justice de la maison d’Achab, qu’il trouva les chefs de Juda et les fils des frères d’Achazia, qui servaient Achazia, et il les tua.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Il chercha ensuite Achazia, qui s’était caché à Samarie; on le prit, et on l’amena vers Jéhu, et on le fit mourir. Puis on l’ensevelit, car on dit: C’est le fils de Josaphat, qui a recherché l’Éternel de tout son cœur. Et il n’y eut plus personne dans la maison d’Achazia qui fût capable de régner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Or Athalie, mère d’Achazia, voyant que son fils était mort, se leva, et extermina toute la race royale de la maison de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Mais Joshabath, fille du roi Joram, prit Joas, fils d’Achazia, le déroba d’entre les fils du roi qu’on faisait mourir, et le mit avec sa nourrice, dans la salle des lits. Ainsi Joshabath, fille du roi Joram et femme de Jéhojada, le sacrificateur, étant la sœur d’Achazia, le cacha aux yeux d’Athalie, qui ne le fit point mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Il fut ainsi caché avec eux, six ans, dans la maison de Dieu; et Athalie régnait sur le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Mais la septième année, Jéhojada se fortifia, et traita alliance avec les chefs de centaines, Azaria, fils de Jérocham, Ismaël, fils de Jochanan, Azaria, fils d’Obed, Maaséja, fils d’Adaja, et Élishaphat, fils de Zicri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Ils firent le tour de Juda, assemblèrent, de toutes les villes de Juda, les Lévites et les chefs des pères d’Israël, et vinrent à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Et toute l’assemblée traita alliance avec le roi, dans la maison de Dieu. Et Jéhojada leur dit: Voici, le fils du roi régnera, selon que l’Éternel a parlé au sujet des fils de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Voici ce que vous ferez: Le tiers de ceux d’entre vous qui entrez en service au sabbat, sacrificateurs et Lévites, gardera les portes d’entrée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'Un autre tiers se tiendra dans la maison du roi, et un tiers à la porte de Jésod; et tout le peuple sera dans les parvis de la maison de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Que nul n’entre dans la maison de l’Éternel, sinon les sacrificateurs et les Lévites de service: ceux-ci entreront, car ils sont consacrés; et tout le peuple fera la garde de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Et les Lévites environneront le roi de tous côtés, tenant chacun leurs armes à la main, et quiconque entrera dans la maison, sera mis à mort; et vous serez avec le roi quand il entrera et quand il sortira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Les Lévites et tout Juda, firent donc tout ce que Jéhojada, le sacrificateur, avait commandé. Ils prirent chacun leurs gens, tant ceux qui entraient en service au sabbat, que ceux qui en sortaient; car Jéhojada, le sacrificateur, ne congédia point les classes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Et Jéhojada, le sacrificateur, donna aux chefs de centaines les lances, les boucliers et les rondelles qui provenaient du roi David, et qui étaient dans la maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Puis il rangea tout le peuple, chacun tenant ses armes à la main, auprès du roi tout à l’entour, depuis le côté droit du temple jusqu’au côté gauche du temple, le long de l’autel et du temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Alors ils firent sortir le fils du roi, et mirent sur lui la couronne et le témoignage; et ils l’établirent roi, et Jéhojada et ses fils l’oignirent, et dirent: Vive le roi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Mais Athalie, entendant le bruit du peuple qui courait et célébrait le roi, vint vers le peuple, dans la maison de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Elle regarda, et voici, le roi était debout près de sa colonne, à l’entrée, et les capitaines et les trompettes étaient près du roi, et tout le peuple du pays était dans la joie, et l’on sonnait des trompettes; et les chantres, avec des instruments de musique, dirigeaient les chants de louanges. Alors Athalie déchira ses vêtements et dit: Conspiration! conspiration!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Et le sacrificateur Jéhojada fit sortir les chefs de centaines qui commandaient l’armée, et leur dit: Menez-la hors des rangs, et que celui qui la suivra soit mis à mort par l’épée! Car le sacrificateur avait dit: Ne la mettez point à mort dans la maison de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Ils mirent donc la main sur elle, et elle revint, par l’entrée de la porte des chevaux, dans la maison du roi; et là ils la firent mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Puis Jéhojada, tout le peuple et le roi, firent une alliance, pour être le peuple de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Et tout le peuple entra dans la maison de Baal. Et ils la démolirent; ils brisèrent ses autels et ses images, et ils tuèrent devant les autels Matthan, sacrificateur de Baal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Jéhojada remit aussi les fonctions de la maison de l’Éternel entre les mains des sacrificateurs, Lévites, que David avait distribués dans la maison de l’Éternel, afin qu’ils offrissent des holocaustes à l’Éternel, comme il est écrit dans la loi de Moïse, avec joie et avec des cantiques, selon les ordonnances de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Il établit aussi les portiers aux portes de la maison de l’Éternel, afin qu’aucune personne souillée, de quelque manière que ce fût, n’y entrât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Il prit les chefs de centaines, et les hommes considérables, et ceux qui étaient en autorité sur le peuple, et tout le peuple du pays; et il fit descendre le roi, de la maison de l’Éternel, et ils entrèrent par la porte supérieure dans la maison du roi, et ils firent asseoir le roi sur le trône royal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Alors tout le peuple du pays se réjouit, et la ville fut en repos, après qu’on eut mis à mort Athalie par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joas était âgé de sept ans quand il devint roi, et il régna quarante ans à Jérusalem; sa mère s’appelait Tsibia, de Béer-Shéba.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Joas fit ce qui est droit aux yeux de l’Éternel, pendant toute la vie de Jéhojada, le sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Et Jéhojada lui donna deux femmes, dont il eut des fils et des filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Après cela Joas eut la pensée de réparer la maison de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Il assembla donc les sacrificateurs et les Lévites, et leur dit: Allez par les villes de Juda, et amassez de l’argent par tout Israël, pour réparer la maison de votre Dieu d’année en année, et hâtez cette affaire. Mais les Lévites ne se hâtèrent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Alors le roi appela Jéhojada, leur chef, et lui dit: Pourquoi n’as- tu pas veillé à ce que les Lévites apportassent, de Juda et de Jérusalem, l’impôt que Moïse, serviteur de l’Éternel, mit sur l’assemblée d’Israël, pour le tabernacle du témoignage?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Car l’impie Athalie et ses enfants ont ravagé la maison de Dieu; et même ils ont employé pour les Baals toutes les choses consacrées à la maison de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Et le roi ordonna qu’on fît un coffre, et qu’on le mît à la porte de la maison de l’Éternel, en dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Puis on publia dans Juda et dans Jérusalem, qu’on apportât à l’Éternel l’impôt mis par Moïse, serviteur de Dieu, sur Israël dans le désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Tous les chefs et tout le peuple s’en réjouirent, et ils apportèrent leur tribut, et jetèrent dans le coffre, jusqu’à ce qu’il fût plein.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Or, quand c’était le moment d’apporter le coffre à l’inspection du roi, par l’entremise des Lévites, et que ceux-ci voyaient qu’il y avait beaucoup d’argent, un secrétaire du roi et un commissaire du principal sacrificateur venaient et vidaient le coffre; puis ils le rapportaient et le remettaient à sa place. Ils faisaient ainsi jour après jour, et ils recueillaient de l’argent en abondance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Le roi et Jéhojada le donnaient à ceux qui étaient chargés de l’ouvrage pour le service de la maison de l’Éternel, et ceux-ci louaient des tailleurs de pierres et des charpentiers pour réparer la maison de l’Éternel, et aussi des ouvriers en fer et en airain, pour réparer la maison de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Ceux qui étaient chargés de l’ouvrage travaillèrent donc, et par leurs soins, l’œuvre fut réparée; de sorte qu’ils rétablirent la maison de Dieu en son état, et la consolidèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Lorsqu’ils eurent achevé, ils apportèrent devant le roi et devant Jéhojada le reste de l’argent, dont il fit faire des ustensiles pour la maison de l’Éternel, des ustensiles pour le service et pour les holocaustes, des coupes et d’autres ustensiles d’or et d’argent. Et on offrit continuellement des holocaustes dans la maison de l’Éternel, tant que vécut Jéhojada.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Or Jéhojada devint vieux et rassasié de jours, et il mourut; il était âgé de cent trente ans quand il mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'On l’ensevelit dans la cité de David avec les rois; car il avait fait du bien à Israël, et à l’égard de Dieu et de sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Mais, après que Jéhojada fut mort, les principaux de Juda vinrent et se prosternèrent devant le roi; alors le roi les écouta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Et ils abandonnèrent la maison de l’Éternel, le Dieu de leurs pères, et ils servirent les emblèmes d’Ashéra et les idoles; et la colère de l’Éternel fut sur Juda et sur Jérusalem, parce qu’ils s’étaient ainsi rendus coupables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Et l’Éternel envoya parmi eux, pour les faire retourner à lui, des prophètes qui témoignèrent contre eux; mais ils ne voulurent point les écouter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Alors l’Esprit de Dieu revêtit Zacharie, fils de Jéhojada, le sacrificateur, et, se tenant debout au-dessus du peuple, il leur dit: Dieu a dit ainsi: Pourquoi transgressez-vous les commandements de l’Éternel? Vous ne prospérerez point; car vous avez abandonné l’Éternel, et il vous abandonnera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Mais ils conspirèrent contre lui, et l’assommèrent de pierres, par le commandement du roi, dans le parvis de la maison de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Ainsi le roi Joas ne se souvint point de la bonté dont Jéhojada, père de Zacharie, avait usé envers lui; et il tua son fils, qui dit en mourant: L’Éternel le voit, et il en demandera compte!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Et il arriva, quand l’année fut révolue, que l’armée de Syrie monta contre Joas, et vint en Juda et à Jérusalem. Or les Syriens détruisirent, d’entre le peuple, tous les principaux du peuple, et ils envoyèrent au roi, à Damas, tout leur butin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Bien que ce fût avec un petit nombre d’hommes qu’arrivât l’armée de Syrie, l’Éternel livra entre leurs mains une très nombreuse armée, parce qu’ils avaient abandonné l’Éternel, le Dieu de leurs pères. Ainsi les Syriens firent justice de Joas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Et quand ils se furent éloignés de lui, après l’avoir laissé dans de grandes souffrances, ses serviteurs conspirèrent contre lui, à cause du sang des fils de Jéhojada, le sacrificateur; ils le tuèrent sur son lit, et il mourut. On l’ensevelit dans la cité de David; mais on ne l’ensevelit pas dans les tombeaux des rois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Et ce sont ici ceux qui conspirèrent contre lui: Zabad, fils de Shimeath, femme ammonite, et Jozabad, fils de Shimrith, femme moabite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Quant à ses fils et à la grande charge qui lui fut imposée, et à la restauration de la maison de Dieu, voici, ces choses sont écrites dans les mémoires sur le livre des rois. Amatsia, son fils, régna à sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Amatsia devint roi à l’âge de vingt-cinq ans, et il régna vingt- neuf ans à Jérusalem. Sa mère s’appelait Joaddan, de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Il fit ce qui est droit aux yeux de l’Éternel, mais non d’un cœur intègre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Il arriva, après qu’il fut affermi dans son royaume, qu’il fit mourir ses serviteurs qui avaient tué le roi, son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Mais il ne fit pas mourir leurs enfants; car il fit selon ce qui est écrit dans la loi, dans le livre de Moïse, où l’Éternel a donné ce commandement: On ne fera point mourir les pères pour les enfants, et on ne fera point mourir les enfants pour les pères; mais on fera mourir chacun pour son péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Puis Amatsia rassembla ceux de Juda, et il les rangea selon les maisons des pères, par chefs de milliers et par chefs de centaines, pour tout Juda et Benjamin; il en fit le dénombrement depuis l’âge de vingt ans et au-dessus; et il trouva trois cent mille hommes d’élite, propres à l’armée, maniant la lance et le bouclier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Il prit aussi à sa solde, pour cent talents d’argent, cent mille vaillants hommes de guerre d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Mais un homme de Dieu vint à lui, et lui dit: O roi! que l’armée d’Israël ne marche point avec toi; car l’Éternel n’est point avec Israël, avec tous ces fils d’Éphraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Sinon, tu peux aller, agir, être vaillant au combat; mais Dieu te fera tomber devant l’ennemi; car Dieu a le pouvoir d’aider et de faire tomber.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Et Amatsia dit à l’homme de Dieu: Mais que faire à l’égard des cent talents que j’ai donnés à la troupe d’Israël? Et l’homme de Dieu dit: L’Éternel en a pour t’en donner beaucoup plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Ainsi Amatsia sépara les troupes qui lui étaient venues d’Éphraïm, afin qu’elles retournassent chez elles; mais leur colère s’enflamma contre Juda, et ces gens s’en retournèrent chez eux dans une ardente colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Alors Amatsia, ayant pris courage, conduisit son peuple et s’en alla dans la vallée du Sel, où il tua dix mille hommes des enfants de Séir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Et les enfants de Juda prirent dix mille hommes vivants, qu’ils amenèrent au sommet d’une roche, d’où ils les précipitèrent, et ils furent tous brisés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Mais les gens de la troupe qu’Amatsia avait renvoyée, afin qu’ils ne vinssent point avec lui à la guerre, se jetèrent sur les villes de Juda, depuis Samarie jusqu’à Beth-Horon, y tuèrent trois mille personnes, et pillèrent un grand butin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Et après qu’Amatsia fut de retour de la défaite des Édomites, il fit apporter les dieux des enfants de Séir, et se les établit pour dieux; il se prosterna devant eux, et leur fit des encensements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Alors la colère de l’Éternel s’enflamma contre Amatsia, et il envoya vers lui un prophète, qui lui dit: Pourquoi as-tu recherché les dieux de ce peuple, qui n’ont point délivré leur peuple de ta main?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Et comme il parlait au roi, le roi lui dit: T’a-t-on établi conseiller du roi? Retire-toi! pourquoi te frapperait-on? Et le prophète se retira, mais en disant: Je sais que Dieu a résolu de te détruire, parce que tu as fait cela, et que tu n’as point écouté mon conseil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Puis Amatsia, roi de Juda, ayant tenu conseil, envoya vers Joas, fils de Joachaz, fils de Jéhu, roi d’Israël, pour lui dire: Viens, que nous nous voyions en face!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Mais Joas, roi d’Israël, envoya dire à Amatsia, roi de Juda: L’épine qui est au Liban a envoyé dire au cèdre du Liban: Donne ta fille pour femme à mon fils. Mais les bêtes sauvages qui sont au Liban ont passé et ont foulé l’épine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Voici, tu dis que tu as battu Édom; et ton cœur s’est élevé pour te glorifier. Maintenant, reste dans ta maison! Pourquoi t’engagerais-tu dans un malheur où tu tomberais, toi et Juda avec toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Mais Amatsia ne l’écouta point; car cela venait de Dieu, afin de les livrer entre les mains de Joas parce qu’ils avaient recherché les dieux d’Édom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Joas, roi d’Israël, monta donc; et ils se virent en face, lui et Amatsia, roi de Juda, à Beth-Shémèsh, qui est de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Et Juda fut battu devant Israël, et ils s’enfuirent chacun dans leurs tentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Et Joas, roi d’Israël, prit Amatsia, roi de Juda, fils de Joas, fils de Joachaz, à Beth-Shémèsh. Il l’emmena à Jérusalem, et fit une brèche de quatre cents coudées dans la muraille de Jérusalem, depuis la porte d’Éphraïm, jusqu’à la porte du coin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Il prit tout l’or et l’argent, et tous les vases qui furent trouvés dans la maison de Dieu, sous la garde d’Obed-Édom, et les trésors de la maison du roi, et des otages; et il s’en retourna à Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Et Amatsia, fils de Joas, roi de Juda, vécut quinze ans, après que Joas, fils de Joachaz, roi d’Israël, fut mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Le reste des actions d’Amatsia, les premières et les dernières, voici cela n’est-il pas écrit dans le livre des rois de Juda et d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Or, depuis le moment où Amatsia se détourna de l’Éternel, on fit une conspiration contre lui à Jérusalem, et il s’enfuit à Lakis; mais on envoya après lui à Lakis, et on le tua là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Puis on le transporta sur des chevaux, et on l’ensevelit avec ses pères dans la ville de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Alors, tout le peuple de Juda prit Ozias, qui était âgé de seize ans, et ils l’établirent roi à la place de son père Amatsia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Ce fut lui qui bâtit Éloth, et la ramena sous la puissance de Juda, après que le roi se fut endormi avec ses pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Ozias était âgé de seize ans quand il devint roi, et il régna cinquante-deux ans à Jérusalem. Sa mère s’appelait Jécolia, de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Il fit ce qui est droit aux yeux de l’Éternel, comme avait fait Amatsia, son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Il s’appliqua à rechercher Dieu pendant la vie de Zacharie, homme intelligent dans les visions de Dieu; et pendant les jours qu’il rechercha l’Éternel, Dieu le fit prospérer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Il sortit et fit la guerre contre les Philistins; et il renversa la muraille de Gath, la muraille de Jabné, et la muraille d’Asdod; et il bâtit des villes dans le pays d’Asdod, et chez les Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Et Dieu lui donna du secours contre les Philistins et contre les Arabes qui habitaient à Gur-Baal, et contre les Maonites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Les Ammonites même faisaient des présents à Ozias, et sa renommée parvint jusqu’à l’entrée de l’Égypte; car il devint très puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Ozias bâtit des tours à Jérusalem, sur la porte du coin, sur la porte de la vallée, et sur l’angle rentrant; et il les fortifia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Il bâtit des tours dans le désert, et il creusa de nombreuses citernes, parce qu’il avait beaucoup de bétail dans la plaine et dans la campagne, et des laboureurs et des vignerons sur les montagnes, et au Carmel; car il aimait l’agriculture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Ozias avait une armée de gens de guerre, allant en campagne par bandes, selon le compte de leur dénombrement fait par Jéïel, le scribe, et Maaséja, le prévôt, sous la conduite de Hanania, l’un des chefs du roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Le nombre total des chefs des pères, des vaillants guerriers, était de deux mille six cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Sous leur conduite était une armée de trois cent sept mille cinq cents combattants, tous gens de guerre, forts et vaillants, pour aider le roi contre l’ennemi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Et Ozias leur procura, pour toute l’armée, des boucliers, des lances, des casques, des cuirasses, des arcs et des pierres de fronde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Il fit aussi à Jérusalem des machines de l’invention d’un ingénieur, pour être placées sur les tours et sur les angles, pour lancer des flèches et de grosses pierres. Et sa renommée s’étendit au loin; car il fut merveilleusement aidé, jusqu’à ce qu’il fût devenu fort puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Mais lorsqu’il fut puissant, son cœur s’éleva jusqu’à se corrompre; et il commit un péché contre l’Éternel, son Dieu: il entra dans le temple de l’Éternel pour brûler le parfum sur l’autel des parfums.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Mais Asaria, le sacrificateur, entra après lui, et avec lui quatre-vingts sacrificateurs de l’Éternel, hommes vaillants,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Qui s’opposèrent au roi Ozias, et lui dirent: Ce n’est pas à toi, Ozias, d’offrir le parfum à l’Éternel, mais aux sacrificateurs, fils d’Aaron, qui sont consacrés pour cela. Sors du sanctuaire, car tu as péché, et cela ne sera pas à ta gloire devant l’Éternel Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Alors Ozias, qui avait à la main un encensoir pour faire brûler le parfum, se mit en colère, et comme il s’irritait contre les sacrificateurs, la lèpre parut sur son front, en présence des sacrificateurs, dans la maison de l’Éternel, près de l’autel des parfums.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Et Asaria, le principal sacrificateur, le regarda ainsi que tous les sacrificateurs, et voici, il avait la lèpre au front. Ils le firent donc sortir en hâte de là; et lui-même se hâta de sortir, parce que l’Éternel l’avait frappé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Le roi Ozias fut ainsi lépreux jusqu’au jour de sa mort, et demeura comme lépreux dans une maison écartée, car il était exclu de la maison de l’Éternel. Et Jotham, son fils, avait le commandement de la maison du roi, jugeant le peuple du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Or Ésaïe, fils d’Amots, le prophète, a écrit le reste des actions d’Ozias, les premières et les dernières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Et Ozias s’endormit avec ses pères, et on l’ensevelit avec ses pères dans le champ de la sépulture des rois; car on dit: Il est lépreux. Et Jotham, son fils, régna à sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jotham était âgé de vingt-cinq ans quand il devint roi, et il régna seize ans à Jérusalem. Sa mère s’appelait Jérusha, fille de Tsadok.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Il fit ce qui est droit aux yeux de l’Éternel, tout comme Ozias, son père, avait fait; seulement il n’entra pas dans le temple de l’Éternel; néanmoins le peuple se corrompait encore.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Ce fut lui qui bâtit la porte supérieure de la maison de l’Éternel, et il bâtit beaucoup à la muraille d’Ophel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Il bâtit des villes dans la montagne de Juda, et des châteaux, et des tours dans les forêts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Il fut en guerre avec le roi des enfants d’Ammon, et fut le plus fort; et cette année-là, les enfants d’Ammon lui donnèrent cent talents d’argent, dix mille cores de froment, et dix mille d’orge. Les enfants d’Ammon lui en donnèrent autant la seconde et la troisième année.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Jotham devint donc très puissant, parce qu’il avait affermi ses voies devant l’Éternel, son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Le reste des actions de Jotham, toutes ses guerres, et sa conduite, voici, toutes ces choses sont écrites au livre des rois d’Israël et de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Il était âgé de vingt-cinq ans quand il devint roi, et il régna seize ans à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Puis Jotham s’endormit avec ses pères, et on l’ensevelit dans la cité de David; et Achaz, son fils, régna à sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Achaz était âgé de vingt ans quand il devint roi, et il régna seize ans à Jérusalem. Il ne fit point ce qui est droit aux y eux de l’Éternel, comme David, son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Il suivit la voie des rois d’Israël; et il fit même des images de fonte pour les Baals.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Il fit des encensements dans la vallée du fils de Hinnom, et il brûla ses fils au feu, selon les abominations des nations que l’Éternel avait chassées devant les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Il sacrifiait aussi et faisait des encensements dans les hauts lieux, sur les collines, et sous tout arbre verdoyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Et l’Éternel son Dieu le livra entre les mains du roi de Syrie; et les Syriens le battirent et lui prirent un grand nombre de prisonniers, qu’ils emmenèrent à Damas. Il fut aussi livré entre les mains du roi d’Israël, qui lui fit essuyer une grande défaite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Car Pékach, fils de Rémalia, tua en un seul jour, en Juda, cent vingt mille hommes, tous vaillants hommes, parce qu’ils avaient abandonné l’Éternel, le Dieu de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Et Zicri, homme vaillant d’Éphraïm, tua Maaséja, fils du roi, et Azrikam, qui avait la conduite de la maison, et Elkana, le second après le roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Et les enfants d’Israël emmenèrent prisonniers, deux cent mille de leurs frères, tant femmes que fils et filles; ils firent aussi sur eux un grand butin, et ils emmenèrent le butin à Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Or un prophète de l’Éternel, nommé Oded, était là; il sortit au- devant de cette armée, qui revenait à Samarie, et leur dit: Voici, l’Éternel, le Dieu de vos pères, étant indigné contre Juda, les a livrés entre vos mains, et vous les avez tués avec une fureur qui est parvenue jusqu’aux cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Et maintenant, vous prétendez vous assujettir, pour serviteurs et pour servantes, les enfants de Juda et de Jérusalem! Mais n’est-ce pas vous, surtout, qui êtes coupables envers l’Éternel, votre Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Maintenant écoutez-moi, et remmenez les prisonniers que vous avez faits parmi vos frères; car l’ardeur de la colère de l’Éternel est sur vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Alors quelques-uns des chefs des enfants d’Éphraïm, Azaria, fils de Jochanan, Bérékia, fils de Meshillémoth, Ézéchias, fils de Shallum, et Amasa, fils de Hadlaï, s’élevèrent contre ceux qui revenaient de l’armée,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'Et leur dirent: Vous ne ferez point entrer ici ces prisonniers; car, pour nous rendre coupables devant l’Éternel, vous voulez ajouter à nos péchés et à notre culpabilité; car nous sommes déjà très coupables, et l’ardeur de la colère est sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Alors les soldats abandonnèrent les prisonniers et le butin devant les chefs et devant toute l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Et ces hommes, qui ont été désignés par leurs noms, se levèrent, prirent les prisonniers, et vêtirent, au moyen du butin, tous ceux d’entre eux qui étaient nus; ils les vêtirent, ils les chaussèrent; ils leur donnèrent à manger et à boire; ils les oignirent, et ils conduisirent sur des ânes tous ceux qui ne pouvaient pas se soutenir, et les menèrent à Jérico, la ville des palmiers, auprès de leurs frères; puis ils s’en retournèrent à Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'En ce temps-là, le roi Achaz envoya vers les rois d’Assyrie, afin qu’ils lui donnassent du secours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Les Édomites étaient encore venus, avaient battu Juda, et emmené des prisonniers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Les Philistins s’étaient aussi jetés sur les villes de la plaine et du midi de Juda; et ils avaient pris Beth-Shémèsh, Ajalon, Guédéroth, Soco et les villes de son ressort, Thimna et les villes de son ressort, Guimzo et les villes de son ressort, et ils y habitaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Car l’Éternel avait abaissé Juda, à cause d’Achaz, roi d’Israël, parce qu’il avait relâché tout frein en Juda, et qu’il avait grandement péché contre l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Or Thilgath-Pilnéser, roi d’Assyrie, vint vers lui; mais il l’opprima, bien loin de le fortifier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Car Achaz dépouilla la maison de l’Éternel, la maison du roi et celle des principaux du peuple, pour faire des présents au roi d’Assyrie, mais sans en retirer secours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Et dans le temps de sa détresse, il continua à pécher contre l’Éternel. C’était toujours le roi Achaz.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Il sacrifia aux dieux de Damas qui l’avaient frappé, et il dit: Puisque les dieux des rois de Syrie leur viennent en aide, je leur sacrifierai, afin qu’ils me soient en aide. Mais ils furent cause de sa chute et de celle de tout Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Or Achaz rassembla les vases de la maison de Dieu, et il mit en pièces les vases de la maison de Dieu. Il ferma les portes de la maison de l’Éternel, et se fit des autels dans tous les coins de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Et il fit des hauts lieux dans chaque ville de Juda, pour faire des encensements à d’autres dieux; et il irrita l’Éternel, le Dieu de ses pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Quant au reste de ses actions, et de toutes ses voies, les premières et les dernières, voici, elles sont écrites dans le livre des rois de Juda et d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Puis Achaz s’endormit avec ses pères, et on l’ensevelit dans la cité, à Jérusalem; car on ne le mit point dans les tombeaux des rois d’Israël; et Ézéchias, son fils, régna à sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Ézéchias devint roi à l’âge de vingt-cinq ans, et il régna vingt- neuf ans à Jérusalem. Sa mère s’appelait Abija, fille de Zacharie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Il fit ce qui est droit aux yeux de l’Éternel, tout comme avait fait David, son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'La première année de son règne, au premier mois, il ouvrit les portes de la maison de l’Éternel, et il les répara.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Il fit venir les sacrificateurs et les Lévites, et les assembla dans la place orientale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'Et il leur dit: Écoutez-moi, Lévites! sanctifiez-vous maintenant, et sanctifiez la maison de l’Éternel, le Dieu de vos pères, et ôtez du sanctuaire la souillure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Car nos pères ont péché et fait ce qui est mauvais aux yeux de l’Éternel, notre Dieu; ils l’ont abandonné, ils ont détourné leurs faces de la demeure de l’Éternel et lui ont tourné le dos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Ils ont même fermé les portes du portique, et ont éteint les lampes, et ils n’ont point fait fumer le parfum, et ils n’ont point offert l’holocauste au Dieu d’Israël dans le sanctuaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'C’est pourquoi le courroux de l’Éternel a été sur Juda et sur Jérusalem; et il les a livrés au trouble, à la désolation, à la moquerie, comme vous le voyez de vos yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Et voici, à cause de cela, nos pères sont tombés par l’épée, et nos fils, nos filles et nos femmes sont en captivité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Maintenant donc j’ai l’intention de traiter alliance avec l’Éternel, le Dieu d’Israël, pour que l’ardeur de sa colère se détourne de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Or, mes enfants, ne soyez pas indifférents; car l’Éternel vous a choisis, afin que vous vous teniez devant lui pour le servir, pour être ses serviteurs, et pour lui offrir le parfum.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Et les Lévites se levèrent: Machath, fils d’Amasaï, Joël, fils d’Azaria, des enfants des Kéhathites; et des enfants de Mérari, Kis, fils d’Abdi, Azaria, fils de Jéhalléléel; et des Guershonites, Joach, fils de Zimma, et Éden, fils de Joach;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'Et des enfants d’Élitsaphan, Shimri et Jéïel; et des enfants d’Asaph, Zacharie et Matthania;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'Et des enfants d’Héman, Jéhiel et Shimeï, et des enfants de Jéduthun, Shémaja et Uzziel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Ils assemblèrent leurs frères, et ils se sanctifièrent; et ils entrèrent selon le commandement du roi, et suivant les paroles de l’Éternel, pour purifier la maison de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Ainsi les sacrificateurs entrèrent dans l’intérieur de la maison de l’Éternel, pour la purifier; et ils portèrent dehors, au parvis de la maison de l’Éternel, toutes les souillures qu’ils trouvèrent dans le temple de l’Éternel; et les Lévites les reçurent pour les emporter dehors, au torrent de Cédron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Ils commencèrent à sanctifier le temple, le premier jour du premier mois; le huitième jour du mois, ils entrèrent au portique de l’Éternel, et ils sanctifièrent la maison de l’Éternel pendant huit jours; le seizième jour du premier mois, ils eurent achevé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Après cela ils se rendirent chez le roi Ézéchias, et dirent: Nous avons purifié toute la maison de l’Éternel, l’autel des holocaustes et tous ses ustensiles, et la table des pains de proposition et tous ses ustensiles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Nous avons remis en état et sanctifié tous les ustensiles que le roi Achaz avait rejetés pendant son règne, par suite de son péché; et voici, ils sont devant l’autel de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Alors le roi Ézéchias se leva de bon matin, assembla les principaux de la ville, et monta à la maison de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Et ils amenèrent sept taureaux, sept béliers, sept agneaux et sept boucs, destinés à des sacrifices pour le péché, pour le royaume, pour le sanctuaire et pour Juda. Puis le roi dit aux sacrificateurs, fils d’Aaron, qu’ils les offrissent sur l’autel de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Ils égorgèrent donc les bœufs, et les sacrificateurs en reçurent le sang, et le répandirent sur l’autel; ils égorgèrent les béliers, et en répandirent le sang sur l’autel; ils égorgèrent les agneaux, et en répandirent le sang sur l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Puis on fit approcher les boucs du sacrifice pour le péché, devant le roi et devant l’assemblée, et ils posèrent leurs mains sur eux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Et les sacrificateurs les égorgèrent, et offrirent en expiation leur sang sur l’autel, pour faire l’expiation pour tout Israël; car le roi avait ordonné l’holocauste et le sacrifice pour le péché, pour tout Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Il fit aussi tenir les Lévites dans la maison de l’Éternel, avec des cymbales, des lyres et des harpes, selon le commandement de David et de Gad, le Voyant du roi, et de Nathan, le prophète; car c’était un commandement de l’Éternel, par ses prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Les Lévites se tinrent donc là avec les instruments de David, et les sacrificateurs avec les trompettes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Alors Ézéchias commanda qu’on offrît l’holocauste sur l’autel; et au moment où commença l’holocauste, commença aussi le cantique de l’Éternel, avec les trompettes et l’accompagnement des instruments de David, roi d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Et toute l’assemblée se prosterna, le chant retentit, et les trompettes sonnèrent; le tout jusqu’à ce qu’on eût achevé l’holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Et quand on eut achevé d’offrir l’holocauste, le roi et tous ceux qui se trouvaient avec lui fléchirent les genoux et se prosternèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Puis le roi Ézéchias et les chefs dirent aux Lévites de louer l’Éternel avec les paroles de David et d’Asaph, le Voyant; et ils le louèrent avec des transports de joie, et ils s’inclinèrent et se prosternèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Alors Ézéchias prit la parole, et dit: Vous avez maintenant consacré vos mains à l’Éternel; approchez-vous, amenez des sacrifices, et offrez des louanges dans la maison de l’Éternel. Et l’assemblée amena des sacrifices et offrit des louanges, et tous ceux qui étaient de bonne volonté offrirent des holocaustes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Le nombre des holocaustes que l’assemblée offrit, fut de soixante et dix taureaux, cent béliers, deux cents agneaux, le tout en holocauste à l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Six cents bœufs et trois mille brebis furent en outre consacrés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Mais les sacrificateurs étaient en petit nombre, et ils ne purent pas dépouiller tous les holocaustes; les Lévites, leurs frères, les aidèrent, jusqu’à ce que l’ouvrage fût achevé, et jusqu’à ce que les autres sacrificateurs se fussent sanctifiés; car les Lévites eurent le cœur plus droit pour se sanctifier, que les sacrificateurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Il y eut aussi un grand nombre d’holocaustes, avec les graisses des sacrifices de prospérités, et avec les libations des holocaustes. Ainsi le service de la maison de l’Éternel fut rétabli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Et Ézéchias et tout le peuple se réjouirent de ce que Dieu avait ainsi disposé le peuple; car la chose se fit subitement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Puis Ézéchias envoya vers tout Israël et Juda; et il écrivit même des lettres à Éphraïm et à Manassé, pour qu’ils vinssent à la maison de l’Éternel, à Jérusalem, célébrer la pâque en l’honneur de l’Éternel, le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Le roi, et ses chefs et toute l’assemblée, avaient résolu en conseil, à Jérusalem, de célébrer la pâque au second mois;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Car on n’avait pas pu la célébrer en son temps, parce qu’il n’y avait pas assez de sacrificateurs sanctifiés, et que le peuple n’était pas rassemblé à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'La chose plut au roi et à toute l’assemblée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Et ils décidèrent de publier par tout Israël, depuis Béer-Shéba jusqu’à Dan, qu’on vînt célébrer la pâque à l’Éternel, le Dieu d’Israël, à Jérusalem; car depuis longtemps ils ne l’avaient pas célébrée conformément à ce qui est écrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Les coureurs allèrent donc avec des lettres de la part du roi et de ses chefs, par tout Israël et Juda, en disant, selon que le roi l’avait commandé: Enfants d’Israël, retournez à l’Éternel, le Dieu d’Abraham, d’Isaac et d’Israël, et il reviendra vers le reste d’entre vous qui est échappé de la main des rois d’Assyrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Ne soyez pas comme vos pères, ni comme vos frères, qui ont péché contre l’Éternel, le Dieu de leurs pères, de sorte qu’il les a mis en désolation, comme vous le voyez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Maintenant, ne roidissez pas votre cou, comme vos pères; tendez la main vers l’Éternel, venez à son sanctuaire, qu’il a consacré pour toujours, servez l’Éternel, votre Dieu, et l’ardeur de sa colère se détournera de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Car si vous retournez à l’Éternel, vos frères et vos fils trouveront miséricorde auprès de ceux qui les ont emmenés captifs, et ils reviendront en ce pays, parce que l’Éternel, votre Dieu, est clément et miséricordieux; et il ne détournera point sa face de vous, si vous revenez à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Les coureurs passaient ainsi de ville en ville, par le pays d’Éphraïm et de Manassé, et jusqu’à Zabulon; mais l’on se moquait d’eux et l’on s’en raillait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Toutefois, quelques-uns d’Asser, de Manassé et de Zabulon s’humilièrent, et vinrent à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'La main de Dieu fut aussi sur Juda, pour leur donner un même cœur, afin d’exécuter le commandement du roi et des chefs, selon la parole de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Et il s’assembla à Jérusalem un peuple nombreux, pour célébrer la fête des pains sans levain, au second mois: ce fut une fort grande assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Ils se levèrent, et ils ôtèrent les autels qui étaient dans Jérusalem; ils ôtèrent aussi tous ceux où l’on brûlait de l’encens, et ils les jetèrent dans le torrent de Cédron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Puis on immola la pâque, au quatorzième jour du second mois; car les sacrificateurs et les Lévites avaient eu honte et s’étaient sanctifiés, et ils offrirent des holocaustes dans la maison de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Ils se tinrent, à leur place, suivant leur règle, d’après la loi de Moïse, homme de Dieu. Et les sacrificateurs répandaient le sang qu’ils recevaient de la main des Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Car il y en avait une grande partie dans l’assemblée qui ne s’étaient pas purifiés; et les Lévites eurent la charge d’immoler les victimes de la pâque pour tous ceux qui n’étaient pas purs, afin de les consacrer à l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Car une grande partie du peuple, beaucoup de ceux d’Éphraïm, de Manassé, d’Issacar et de Zabulon, ne s’étaient pas purifiés, et mangèrent la pâque, sans se conformer à ce qui est écrit. Mais Ézéchias pria pour eux, en disant: Que l’Éternel, qui est bon, fasse l’expiation,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'Pour quiconque a disposé son cœur à rechercher Dieu, l’Éternel, le Dieu de ses pères, bien que ce ne soit pas selon la purification du sanctuaire!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Et l’Éternel exauça Ézéchias, et il pardonna au peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Les enfants d’Israël qui se trouvèrent à Jérusalem célébrèrent donc la fête des pains sans levain, pendant sept jours, avec une grande joie; et les Lévites et les sacrificateurs célébraient l’Éternel chaque jour, avec les instruments qui retentissaient à la louange de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Et Ézéchias parla au cœur de tous les Lévites, qui se montraient intelligents dans la bonne science du service de l’Éternel. Ils mangèrent les repas de la fête pendant sept jours, offrant des sacrifices de prospérités, et louant l’Éternel le Dieu de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Puis toute l’assemblée résolut de célébrer sept autres jours. Et ils célébrèrent ces sept jours dans la joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Car Ézéchias, roi de Juda, fit présent à l’assemblée de mille taureaux et de sept mille moutons; et les chefs firent présent à l’assemblée de mille taureaux et de dix mille moutons; et des sacrificateurs, en grand nombre, s’étaient sanctifiés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Et toute l’assemblée de Juda, avec les sacrificateurs et les Lévites, et toute l’assemblée venue d’Israël, et les étrangers venus du pays d’Israël, et ceux qui habitaient en Juda, se réjouirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Il y eut donc une grande joie à Jérusalem; car depuis le temps de Salomon, fils de David, roi d’Israël, il n’y avait rien eu de semblable dans Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Puis les sacrificateurs lévites se levèrent et bénirent le peuple, et leur voix fut entendue, et leur prière parvint jusqu’aux cieux, jusqu’à la sainte demeure de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Lorsque tout cela fut achevé, tous ceux d’Israël qui se trouvaient là, allèrent par les villes de Juda, et brisèrent les statues, abattirent les emblèmes d’Ashéra et démolirent les hauts lieux et les autels, dans tout Juda et Benjamin et dans Éphraïm et Manassé, jusqu’à ce que tout fût détruit. Ensuite tous les enfants d’Israël retournèrent dans leurs villes, chacun dans sa possession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Puis Ézéchias rétablit les classes des sacrificateurs et des Lévites, selon leurs divisions, chacun selon ses fonctions, tant les sacrificateurs que les Lévites, pour les holocaustes et les sacrifices de prospérités, pour faire le service, pour louer et pour célébrer Dieu aux portes du camp de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Le roi donna aussi une portion de ses biens pour les holocaustes, pour les holocaustes du matin et du soir, pour les holocaustes des sabbats, des nouvelles lunes et des fêtes, comme il est écrit dans la loi de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Et il dit au peuple, aux habitants de Jérusalem, de donner la portion des sacrificateurs et des Lévites, afin qu’ils s’appliquassent à la loi de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Et aussitôt que la chose fut publiée, les enfants d’Israël donnèrent en abondance les prémices du blé, du moût, de l’huile, du miel et de tous les produits des champs; ils apportèrent la dîme de tout, en abondance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Et les enfants d’Israël et de Juda, qui habitaient dans les villes de Juda, apportèrent aussi la dîme du gros et du menu bétail, et la dîme des choses saintes, qui étaient consacrées à l’Éternel, leur Dieu; et ils les mirent par monceaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Ils commencèrent à faire les monceaux au troisième mois, et au septième mois ils les achevèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Alors Ézéchias et les chefs vinrent, et virent les monceaux, et ils bénirent l’Éternel et son peuple d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Et Ézéchias interrogea les sacrificateurs et les Lévites au sujet de ces monceaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Et Azaria, le principal sacrificateur, de la maison de Tsadok, lui parla, et dit: Depuis qu’on a commencé à apporter des offrandes dans la maison de l’Éternel, nous avons mangé, et nous avons été rassasiés, et il en est resté en abondance; car l’Éternel a béni son peuple, et cette grande quantité est ce qu’il y a eu de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Alors Ézéchias dit qu’on préparât des chambres dans la maison de l’Éternel, et on les prépara.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'Et on apporta fidèlement les offrandes, et la dîme, et les choses consacrées. Et Conania, le Lévite, en eut l’intendance, et Shimeï, son frère, était son second.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Jéhiel, Azazia, Nachath, Asaël, Jérimoth, Josabad, Éliel, Jismakia, Machath, et Benaïa, étaient commis sous l’autorité de Conania et de Shimeï, son frère, par l’ordre du roi Ézéchias, et d’Azaria, gouverneur de la maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Coré, fils de Jimna, le Lévite, qui était portier vers l’orient, avait la charge des dons volontaires offerts à Dieu, pour distribuer l’offrande élevée de l’Éternel, et les choses très saintes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Et sous sa direction étaient Éden, Minjamin, Josué, Shémaja, Amaria, et Shécania, dans les villes des sacrificateurs, pour distribuer fidèlement les portions à leurs frères, grands et petits, suivant leurs divisions,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'Outre ceux qui étaient enregistrés comme mâles, depuis l’âge de trois ans et au-dessus; à tous ceux qui entraient dans la maison de l’Éternel, pour les fonctions de chaque jour, selon le service de leurs charges, suivant leurs divisions;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Aux sacrificateurs enregistrés selon la maison de leurs pères, et aux Lévites, depuis ceux de vingt ans et au-dessus, selon leurs charges et selon leurs divisions;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'A ceux de toute l’assemblée enregistrés avec leurs petits enfants, leurs femmes, leurs fils et leurs filles; car ils se consacraient avec fidélité aux choses saintes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Et quant aux enfants d’Aaron, les sacrificateurs, qui étaient à la campagne, dans la banlieue de leurs villes, il y avait dans chaque ville des gens désignés par leurs noms, pour distribuer les portions à tous les mâles des sacrificateurs, et à tous les Lévites enregistrés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Ézéchias en usa ainsi par tout Juda; et il fit ce qui est bon, droit et véritable, devant l’Éternel son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Et, dans tout l’ouvrage qu’il entreprit pour le service de la maison de Dieu, et pour la loi, et pour les commandements, en recherchant son Dieu, il agit de tout son cœur, et il réussit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Après ces choses et ces actes de fidélité, arriva Sanchérib, roi des Assyriens; il entra en Juda, et campa contre les villes fortes, dans l’intention de s’en emparer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Or Ézéchias, voyant que Sanchérib était venu, et qu’il se tournait contre Jérusalem pour lui faire la guerre,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'Tint conseil avec ses chefs et ses hommes vaillants pour boucher les sources d’eau qui étaient hors de la ville, et ils l’aidèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Un peuple nombreux s’assembla donc, et ils bouchèrent toutes les sources et le cours d’eau qui coule par le milieu de la contrée, en disant: Pourquoi les rois des Assyriens trouveraient-ils à leur venue des eaux en abondance?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Il se fortifia et rebâtit toute la muraille où l’on avait fait brèche, et l’éleva jusqu’aux tours; il bâtit une autre muraille en dehors; il fortifia Millo, dans la cité de David, et il fit faire beaucoup de traits et de boucliers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Il établit des capitaines de guerre sur le peuple, les rassembla auprès de lui sur la place de la porte de la ville, et parla à leur cœur, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Fortifiez-vous et soyez fermes! Ne craignez point et ne soyez point effrayés devant le roi des Assyriens et devant toute la multitude qui est avec lui; car avec nous il y a plus qu’avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Avec lui est le bras de la chair, mais avec nous est l’Éternel, notre Dieu, pour nous aider et pour combattre dans nos combats. Et le peuple eut confiance dans les paroles d’Ézéchias, roi de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Après cela, Sanchérib, roi d’Assyrie, pendant qu’il était devant Lakis, ayant avec lui toutes ses forces, envoya ses serviteurs à Jérusalem vers Ézéchias, roi de Juda, et vers tous ceux de Juda qui étaient à Jérusalem, pour leur dire:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Ainsi dit Sanchérib, roi des Assyriens: En quoi vous confiez-vous, que vous restiez à Jérusalem dans la détresse');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Ézéchias ne vous induit-il pas à vous livrer à la mort, par la famine et par la soif, en vous disant: L’Éternel, notre Dieu, nous délivrera de la main du roi des Assyriens?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'N’est-ce pas lui, Ézéchias, qui a aboli ses hauts lieux et ses autels, et qui a fait ce commandement à Juda et à Jérusalem, en disant: Vous vous prosternerez devant un seul autel, et vous y ferez fumer le parfum?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Ne savez-vous pas ce que nous avons fait, moi et mes pères, à tous les peuples des autres pays? Les dieux des nations de ces pays ont- ils pu délivrer leur pays de ma main?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Quel est celui de tous les dieux de ces nations, que mes pères ont entièrement détruites, qui ait pu délivrer son peuple de ma main, pour que votre Dieu puisse vous délivrer de ma main?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Maintenant donc qu’Ézéchias ne vous abuse point, et qu’il ne vous incite plus de cette manière, et ne le croyez pas; car aucun dieu d’aucune nation ni d’aucun royaume n’a pu délivrer son peuple de ma main, ni de la main de mes pères; combien moins votre Dieu vous délivrerait-il de ma main?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Et ses serviteurs parlèrent encore contre l’Éternel Dieu, et contre Ézéchias, son serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Il écrivit aussi des lettres pour insulter l’Éternel, le Dieu d’Israël, en parlant ainsi contre lui: Comme les dieux des nations des autres pays n’ont pu délivrer leur peuple de ma main, ainsi le Dieu d’Ézéchias ne pourra délivrer son peuple de ma main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Et ses serviteurs crièrent à haute voix en langue judaïque, au peuple de Jérusalem qui était sur la muraille, pour les effrayer et les épouvanter, afin de prendre la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Ils parlèrent du Dieu de Jérusalem comme des dieux des peuples de la terre, ouvrage de mains d’hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Alors le roi Ézéchias, et Ésaïe, le prophète, fils d’Amots, prièrent à ce sujet et crièrent vers les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Et l’Éternel envoya un ange, qui extermina tous les vaillants hommes, les princes et les chefs dans le camp du roi d’Assyrie, en sorte qu’il s’en retourna confus en son pays. Et, comme il était entré dans la maison de son dieu, ceux qui étaient sortis de ces entrailles, le firent tomber là par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Ainsi l’Éternel sauva Ézéchias et les habitants de Jérusalem de la main de Sanchérib, roi d’Assyrie, et de la main de tous, et il les protégea de tous côtés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Puis beaucoup de gens apportèrent des offrandes à l’Éternel, à Jérusalem, et des choses précieuses à Ézéchias, roi de Juda, qui après cela fut élevé aux yeux de toutes les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'En ces jours-là, Ézéchias fut malade à la mort, et pria l’Éternel, qui l’exauça et lui accorda un prodige.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Mais Ézéchias ne fut pas reconnaissant du bienfait qu’il avait reçu; car son cœur s’éleva, et il y eut de l’indignation contre lui, et contre Juda et Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Mais Ézéchias s’humilia de l’élévation de son cœur, lui et les habitants de Jérusalem, et l’indignation de l’Éternel ne vint pas sur eux pendant la vie d’Ézéchias.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Et Ézéchias eut beaucoup de richesses et d’honneurs, et il se fit des trésors d’argent, d’or, de pierres précieuses, d’aromates, de boucliers, et de toutes sortes d’objets désirables;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'Des magasins pour les produits en blé, en moût et en huile, des étables pour toute sorte de bétail, et des troupeaux pour les étables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Il se bâtit des villes, et il eut en abondance des troupeaux de gros et de menu bétail; car Dieu lui avait donné de fort grandes richesses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Ce fut lui, Ézéchias, qui boucha l’issue supérieure des eaux de Guihon, et les conduisit droit en bas, vers l’occident de la cité de David. Ainsi Ézéchias réussit dans tout ce qu’il fit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Toutefois, lorsque les chefs de Babylone envoyèrent des messagers vers lui pour s’informer du prodige qui était arrivé dans le pays, Dieu l’abandonna pour l’éprouver, afin de connaître tout ce qui était dans son cœur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Quant au reste des actions d’Ézéchias, et à ses œuvres de piété, voici, cela est écrit dans la vision d’Ésaïe, le prophète, fils d’Amots, dans le livre des rois de Juda et d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Puis Ézéchias s’endormit avec ses pères, et on l’ensevelit au plus haut des tombeaux des fils de David; tout Juda et les habitants de Jérusalem lui rendirent honneur à sa mort; et Manassé, son fils, régna à sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manassé était âgé de douze ans quand il devint roi, et il régna cinquante-cinq ans à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Il fit ce qui est mauvais aux yeux de l’Éternel, selon les abominations des nations que l’Éternel avait chassées devant les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Il rebâtit les hauts lieux qu’Ézéchias, son père, avait démolis, il éleva des autels aux Baals, il fit des emblèmes d’Ashéra, et se prosterna devant toute l’armée des cieux et la servit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Il bâtit aussi des autels dans la maison de l’Éternel, de laquelle l’Éternel avait dit: Mon nom sera dans Jérusalem à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Il bâtit des autels à toute l’armée des cieux, dans les deux parvis de la maison de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Il fit passer ses fils par le feu dans la vallée du fils de Hinnom; il pratiquait la magie, les sorcelleries et les augures; il établit des nécromanciens et des devins. Il fit de plus en plus ce qui est mauvais aux yeux de l’Éternel, pour l’irriter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Il plaça une image taillée, une idole qu’il avait faite, dans la maison de Dieu, de laquelle Dieu avait dit à David et à Salomon, son fils: Je mettrai à perpétuité mon nom dans cette maison et dans Jérusalem, que j’ai choisie entre toutes les tribus d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Et je ne ferai plus sortir Israël de la terre que j’ai assignée à leurs pères, pourvu seulement qu’ils prennent garde à faire tout ce que je leur ai commandé, selon toute la loi, les préceptes et les ordonnances prescrites par Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Manassé fit donc que Juda et les habitants de Jérusalem s’égarèrent, jusqu’à faire pis que les nations que l’Éternel avait exterminées devant les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Et l’Éternel parla à Manassé et à son peuple; mais ils n’y voulurent point entendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Alors l’Éternel fit venir contre eux les chefs de l’armée du roi des Assyriens, qui mirent Manassé dans les fers; ils le lièrent d’une double chaîne d’airain, et l’emmenèrent à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Et lorsqu’il fut dans l’angoisse, il implora l’Éternel, son Dieu, et il s’humilia fort devant le Dieu de ses pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Il lui adressa ses supplications, et Dieu fut fléchi par sa prière, et exauça sa supplication; et il le fit retourner à Jérusalem, dans son royaume; et Manassé reconnut que c’est l’Éternel qui est Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Après cela, il bâtit une muraille extérieure à la cité de David, à l’occident, vers Guihon, dans la vallée, jusqu’à l’entrée de la porte des Poissons; il en entoura Ophel, et lui donna une grande hauteur; il établit aussi des chefs d’armée dans toutes les villes fortes de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Il ôta de la maison de l’Éternel les dieux des étrangers, et l’idole, et tous les autels, qu’il avait bâtis sur la montagne de la maison de l’Éternel et à Jérusalem; et il les jeta hors de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Puis il rebâtit l’autel de l’Éternel et y offrit des sacrifices de prospérités et de louanges; et il ordonna à Juda de servir l’Éternel, le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Toutefois le peuple sacrifiait encore dans les hauts lieux, mais seulement à l’Éternel, son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Le reste des actions de Manassé, sa prière à son Dieu, et les paroles des Voyants qui lui parlaient au nom de l’Éternel, le Dieu d’Israël, voici, cela est écrit dans les actes des rois d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Sa prière, et comment Dieu fut fléchi, tout son péché et son infidélité, les places dans lesquelles il bâtit des hauts lieux, et dressa des emblèmes d’Ashéra et des images taillées, avant qu’il s’humiliât, voici cela est écrit dans les paroles des Voyants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Puis Manassé s’endormit avec ses pères, et on l’ensevelit dans sa maison; et Amon, son fils, régna à sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Amon était âgé de vingt-deux ans quand il devint roi, et il régna deux ans à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Il fit ce qui est mauvais aux yeux de l’Éternel, comme avait fait Manassé, son père; il sacrifia à toutes les images taillées que Manassé, son père, avait faites, et il les servit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Mais il ne s’humilia point devant l’Éternel, comme Manassé, son père, s’était humilié, car lui, Amon, se rendit coupable de plus en plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Et ses serviteurs conspirèrent contre lui, et le firent mourir dans sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Mais le peuple du pays frappa tous ceux qui avaient conspiré contre le roi Amon; et le peuple du pays établit pour roi, à sa place, Josias, son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Josias était âgé de huit ans quand il devint roi, et il régna trente et un ans à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Il fit ce qui est droit aux yeux de l’Éternel; il marcha sur les traces de David, son père; il ne s’en détourna ni à droite ni à gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'La huitième année de son règne, comme il était encore jeune, il commença à rechercher le Dieu de David, son père; et la douzième année, il commença à purifier Juda et Jérusalem des hauts lieux, des emblèmes d’Ashéra, et des images taillées, et des images de fonte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'On détruisit en sa présence les autels des Baals, et il abattit les colonnes solaires qui étaient dessus. Il brisa les emblèmes d’Ashéra, les images taillées et les images de fonte; et les ayant réduites en poudre, il la répandit sur les tombeaux de ceux qui leur avaient sacrifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Puis il brûla les os des sacrificateurs sur leurs autels, et il purifia Juda et Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Dans les villes de Manassé, d’Éphraïm et de Siméon, et jusqu’à Nephthali, dans leurs ruines, partout,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'Il démolit les autels, et mit en pièces les emblèmes d’Ashéra et les images taillées, et les réduisit en poussière; et il abattit toutes les colonnes solaires dans tout le pays d’Israël. Puis il revint à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Et la dix-huitième année de son règne, après qu’il eut purifié le pays et le temple, il envoya Shaphan, fils d’Atsalia, et Maaséja, capitaine de la ville, et Joach, fils de Joachaz, l’archiviste, pour réparer la maison de l’Éternel, son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Et ils vinrent vers Hilkija, le grand sacrificateur; et on livra l’argent qui avait été apporté dans la maison de Dieu et que les Lévites, gardiens du seuil, avaient recueilli de Manassé, et d’Éphraïm, et de tout le reste d’Israël, et de tout Juda, et de Benjamin, et des habitants de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'On le remit entre les mains de ceux qui avaient la charge de l’ouvrage, qui étaient préposés sur la maison de l’Éternel; et ceux qui avaient la charge de l’ouvrage, qui travaillaient dans la maison de l’Éternel, le distribuèrent pour la réparer et la restaurer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Ils le remirent aux charpentiers et aux maçons, pour acheter des pierres de taille et du bois pour les assemblages et pour la charpente des maisons que les rois de Juda avaient détruites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Et ces hommes s’employaient fidèlement au travail. Jachath et Obadia, Lévites d’entre les enfants de Mérari, étaient préposés sur eux, et Zacharie et Méshullam, d’entre les enfants des Kéhathites, pour les diriger; et ces Lévites étaient tous habiles dans les instruments de musique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Ils surveillaient ceux qui portaient les fardeaux, et dirigeaient tous ceux qui faisaient l’ouvrage, dans chaque genre de service; il y avait des scribes, des commissaires et des portiers, d’entre les Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Or, comme on retirait l’argent qui avait été apporté dans la maison de l’Éternel, Hilkija, le sacrificateur, trouva le livre de la loi de l’Éternel, donné par Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Alors Hilkija, prenant la parole, dit à Shaphan, le secrétaire: J’ai trouvé le livre de la loi dans la maison de l’Éternel. Et Hilkija donna le livre à Shaphan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Et Shaphan apporta le livre au roi, et rendit compte au roi, en disant: Tes serviteurs font tout ce qu’on leur a donné à faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Ils ont versé l’argent qui a été trouvé dans la maison de l’Éternel, et l’ont remis entre les mains des commissaires, et entre les mains de ceux qui ont la charge de l’ouvrage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Shaphan, le secrétaire, dit aussi au roi: Hilkija, le sacrificateur, m’a donné un livre; et Shaphan y lut devant le roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Or il arriva, dès que le roi eut entendu les paroles de la loi, qu’il déchira ses vêtements;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Et il donna cet ordre à Hilkija, à Achikam, fils de Shaphan, à Abdon, fils de Mica, à Shaphan, le secrétaire, et à Asaja, serviteur du roi, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Allez, consultez l’Éternel pour moi et pour ce qui reste en Israël et en Juda, touchant les paroles du livre qui a été trouvé; car la colère de l’Éternel qui s’est répandue sur nous, est grande, parce que nos pères n’ont point gardé la parole de l’Éternel, pour faire selon tout ce qui est écrit dans ce livre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Hilkija et ceux que le roi avait désignés allèrent vers Hulda, la prophétesse, femme de Shallum, fils de Tokhath, fils de Hasra, gardien des vêtements. Elle habitait à Jérusalem, dans le second quartier; et ils lui parlèrent dans ce sens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Et elle leur répondit: Ainsi a dit l’Éternel, le Dieu d’Israël: Dites à l’homme qui vous a envoyés vers moi:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Ainsi a dit l’Éternel: Voici, je vais faire venir du mal sur ce lieu et sur ses habitants, toutes les malédictions qui sont écrites dans le livre qu’on a lu devant le roi de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Parce qu’ils m’ont abandonné, et qu’ils ont fait des encensements à d’autres dieux, pour m’irriter par toutes les œuvres de leurs mains, ma colère s’est répandue sur ce lieu, et elle ne sera point éteinte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Mais quant au roi de Juda, qui vous a envoyés pour consulter l’Éternel, vous lui direz: Ainsi a dit l’Éternel, le Dieu d’Israël, quant aux paroles que tu as entendues:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Parce que ton cœur a été touché, et que tu t’es humilié devant Dieu, quand tu as entendu ses paroles contre ce lieu et contre ses habitants; parce que tu t’es humilié devant moi, et que tu as déchiré tes vêtements, et que tu as pleuré devant moi, moi aussi, j’ai entendu, dit l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Voici, je vais te recueillir avec tes pères, et tu seras recueilli en paix dans tes tombeaux, et tes yeux ne verront point tout le mal que je vais faire venir sur ce lieu et sur ses habitants. Et ils rapportèrent au roi cette parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Alors le roi envoya assembler tous les anciens de Juda et de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Et le roi monta à la maison de l’Éternel avec tous les hommes de Juda, et les habitants de Jérusalem, les sacrificateurs et les Lévites, et tout le peuple, depuis le plus grand jusqu’au plus petit; et on lut devant eux toutes les paroles du livre de l’alliance, qui avait été trouvé dans la maison de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Et le roi se tint debout à sa place; et il traita alliance devant l’Éternel, promettant de suivre l’Éternel et de garder ses commandements, ses témoignages et ses lois, de tout son cœur et de toute son âme, en pratiquant les paroles de l’alliance écrites dans ce livre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Et il y fit adhérer tous ceux qui se trouvaient à Jérusalem et en Benjamin; et les habitants de Jérusalem firent selon l’alliance de Dieu, le Dieu de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Josias ôta donc, de tous les pays appartenant aux enfants d’Israël, toutes les abominations; et il obligea tous ceux qui se trouvaient en Israël à servir l’Éternel leur Dieu. Pendant toute sa vie, ils ne se détournèrent point de l’Éternel, le Dieu de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Or Josias célébra la pâque à l’Éternel, à Jérusalem, et on immola la pâque, le quatorzième jour du premier mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Et il établit les sacrificateurs dans leurs charges, et les encouragea au service de la maison de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Il dit aussi aux Lévites qui enseignaient tout Israël, et qui étaient consacrés à l’Éternel: Mettez l’arche sainte dans la maison que Salomon, fils de David, roi d’Israël, a bâtie. Vous n’avez plus à la porter sur l’épaule; maintenant, servez l’Éternel, votre Dieu, et son peuple d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Tenez-vous prêts, selon les maisons de vos pères, selon vos divisions, suivant l’écrit de David, roi d’Israël, et suivant l’écrit de Salomon, son fils;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Tenez-vous dans le sanctuaire, selon les classes des maisons des pères, pour vos frères, les enfants du peuple, et selon le partage de la maison des pères des Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Immolez la pâque, sanctifiez-vous, et préparez-la pour vos frères, en faisant selon la parole de l’Éternel prononcée par Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Et Josias fit aux gens du peuple, à tous ceux qui se trouvaient là, un présent de menu bétail, en agneaux et en chevreaux, au nombre de trente mille, le tout pour faire la pâque, et de trois mille bœufs; cela fut pris sur les biens du roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Et ses chefs firent un présent volontaire au peuple, aux sacrificateurs et aux Lévites. Hilkija, Zacharie et Jéhiel, princes de la maison de Dieu, donnèrent aux sacrificateurs, pour faire la pâque, deux mille six cents agneaux, et trois cents bœufs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Conania, Shémaja et Nathanaël, ses frères, et Hashabia, Jéïel et Jozabad, chefs des Lévites, en présentèrent cinq mille aux Lévites pour faire la pâque, et cinq cents bœufs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Le service étant préparé, les sacrificateurs se tinrent à leurs places, ainsi que les Lévites suivant leurs divisions, selon le commandement du roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Puis on immola la pâque; et les sacrificateurs répandaient le sang reçu des mains des Lévites, et les Lévites dépouillaient les victimes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Ils mirent à part les holocaustes, pour les donner aux gens du peuple, suivant les divisions des maisons de leurs pères, afin de les offrir à l’Éternel, selon qu’il est écrit au livre de Moïse; ils firent de même pour les bœufs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Et ils firent cuire la pâque au feu, selon l’ordonnance; et ils firent cuire les choses consacrées, dans des chaudières, des chaudrons et des poêles; et ils s’empressaient de les distribuer à tous les gens du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Ensuite ils apprêtèrent ce qui était pour eux et pour les sacrificateurs; car les sacrificateurs, enfants d’Aaron, furent occupés jusqu’à la nuit à offrir les holocaustes et les graisses; c’est pourquoi, les Lévites apprêtèrent ce qu’il fallait pour eux et pour les sacrificateurs, enfants d’Aaron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Or les chantres, enfants d’Asaph, étaient à leur place, selon le commandement de David, d’Asaph, d’Héman et de Jéduthun, le Voyant du roi; et les portiers étaient à chaque porte. Ils n’eurent pas à interrompre leur service, car les Lévites, leurs frères, apprêtaient ce qui était pour eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Ainsi, tout le service de l’Éternel fut organisé en ce jour-là, pour faire la pâque, et pour offrir les holocaustes sur l’autel de l’Éternel, selon le commandement du roi Josias.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Les enfants d’Israël qui s’y trouvèrent, célébrèrent donc la pâque, en ce temps-là, et la fête des pains sans levain, pendant sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'On n’avait point célébré de pâque semblable en Israël, depuis les jours de Samuel, le prophète; et aucun des rois d’Israël n’avait célébré une pâque pareille à celle que célébrèrent Josias, les sacrificateurs et les Lévites, tout Juda et Israël, qui s’y trouvèrent avec les habitants de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Cette pâque fut célébrée la dix-huitième année du règne de Josias.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Après tout cela, quand Josias eut réparé le temple, Néco, roi d’Égypte, monta pour faire la guerre à Carkémish, sur l’Euphrate; et Josias sortit à sa rencontre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Mais Néco lui envoya des messagers, pour lui dire: Qu’y a-t-il entre moi et toi, roi de Juda? Ce n’est pas à toi que j’en veux aujourd’hui, mais à une maison avec laquelle je suis en guerre; et Dieu m’a dit de me hâter. Cesse de t’opposer à Dieu, qui est avec moi, de peur qu’il ne te détruise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Cependant Josias ne voulut point se détourner de lui; il se déguisa pour combattre contre lui; et il n’écouta pas les paroles de Néco, qui procédaient de la bouche de Dieu. Il vint donc pour combattre, dans la plaine de Méguiddo.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Et les archers tirèrent sur le roi Josias; et le roi dit à ses serviteurs: Emportez-moi, car je suis fort blessé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Et ses serviteurs l’emportèrent du char, le mirent sur un second char qu’il avait, et le menèrent à Jérusalem, et il mourut. Puis il fut enseveli dans les tombeaux de ses pères, et tous ceux de Juda et de Jérusalem pleurèrent Josias.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Jérémie fit aussi une complainte sur Josias; et tous les chantres et toutes les chanteuses ont parlé de Josias dans leurs complaintes, jusqu’à ce jour, et on en a fait une coutume en Israël. Voici, ces choses sont écrites dans les complaintes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Le reste des actions de Josias, et ses œuvres de piété, conformes à ce qui est écrit dans la loi de l’Éternel,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'Ses premières et ses dernières actions, sont écrites dans le livre des rois d’Israël et de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Alors le peuple du pays prit Joachaz, fils de Josias, et l’établit roi à Jérusalem, à la place de son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Joachaz était âgé de vingt-trois ans quand il devint roi, et il régna trois mois à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Le roi d’Égypte le déposa, à Jérusalem, et frappa le pays d’une amende de cent talents d’argent et d’un talent d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Et le roi d’Égypte établit pour roi sur Juda et Jérusalem Éliakim, frère de Joachaz, et changea son nom en celui de Jéhojakim. Puis Néco prit Joachaz, son frère, et l’emmena en Égypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Jéhojakim était âgé de vingt-cinq ans quand il devint roi, et il régna onze ans à Jérusalem. Il fit ce qui est mauvais aux yeux de l’Éternel, son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Et Nébucadnetsar, roi de Babylone, monta contre lui, et le lia d’une double chaîne d’airain, pour le mener à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Nébucadnetsar emporta aussi à Babylone des vases de la maison de l’Éternel, et il les mit dans son palais, à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Le reste des actions de Jéhojakim, et les abominations qu’il commit, et ce qui se trouva en lui, voici, ces choses sont écrites dans le livre des rois d’Israël et de Juda. Et Jéhojakin, son fils, régna à sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Jéhojakin était âgé de huit ans quand il devint roi, et il régna trois mois et dix jours à Jérusalem. Il fit ce qui est mauvais aux yeux de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Et l’année suivante, le roi Nébucadnetsar envoya, et le fit amener à Babylone, avec les vases précieux de la maison de l’Éternel; et il établit roi sur Juda et Jérusalem, Sédécias, son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Sédécias était âgé de vingt et un ans quand il devint roi, et il régna onze ans à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Il fit ce qui est mauvais aux yeux de l’Éternel, son Dieu; et il ne s’humilia point devant Jérémie, le prophète, qui lui parlait de la part de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Il se révolta même contre le roi Nébucadnetsar, qui l’avait fait jurer par le nom de Dieu; et il roidit son cou, et il endurcit son cœur, pour ne pas retourner à l’Éternel, le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'De même tous les chefs des sacrificateurs et le peuple multiplièrent de plus en plus leurs offenses, selon toutes les abominations des nations; et ils souillèrent la maison de l’Éternel, qu’il avait consacrée dans Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Or l’Éternel, le Dieu de leurs pères, leur avait envoyé des avertissements par le moyen de ses messagers, qu’il envoya de bonne heure; car il voulait épargner son peuple et sa propre demeure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Mais ils se moquèrent des envoyés de Dieu, ils méprisèrent ses paroles, et ils se raillèrent de ses prophètes, jusqu’à ce que la colère de l’Éternel contre son peuple montât au point qu’il n’y eut plus de remède.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Alors il fit monter contre eux le roi des Caldéens, et tua leurs jeunes gens par l’épée, dans la maison de leur sanctuaire; il n’épargna ni le jeune homme, ni la vierge, ni le vieillard, ni l’homme à cheveux blancs; il livra tout entre ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Nébucadnetsar emmena à Babylone tous les vases de la maison de Dieu, grands et petits, les trésors de la maison de l’Éternel, et les trésors du roi et de ses chefs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Ils brûlèrent la maison de Dieu; ils démolirent les murailles de Jérusalem; ils livrèrent au feu tous ses palais, et détruisirent tous les objets précieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Puis le roi transporta à Babylone ceux qui avaient échappé à l’épée, et ils furent ses esclaves et ceux de ses fils, jusqu’à la domination du royaume de Perse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'Afin que la parole de l’Éternel, prononcée par la bouche de Jérémie, fût accomplie; jusqu’à ce que le pays eût acquitté ses sabbats. Pendant tout le temps qu’il fut dévasté, il se reposa jusqu’à l’accomplissement de soixante-dix ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Mais la première année de Cyrus, roi de Perse, afin que la parole de l’Éternel, prononcée par Jérémie, fût accomplie, l’Éternel réveilla l’esprit de Cyrus, roi de Perse, qui fit publier par tout son royaume, et même par écrit, un édit portant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Ainsi a dit Cyrus, roi de Perse: L’Éternel, le Dieu des cieux, m’a donné tous les royaumes de la terre, et lui-même m’a ordonné de lui bâtir une maison à Jérusalem, qui est en Juda. Qui d’entre vous est de son peuple? Que l’Éternel, son Dieu, soit avec lui, et qu’il monte!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'La première année donc de Cyrus Roi de Perse, afin que la parole de l’Eternel, prononcée par Jérémie, fût accomplie, l’Eternel excita l’esprit de Cyrus, Roi de Perse, qui fit publier dans tout son Royaume, et même par Lettres, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Ainsi a dit Cyrus, Roi de Perse: L’Eternel le Dieu des cieux m’a donné tous les Royaumes de la terre, et lui-même m’a ordonné de lui bâtir une maison à Jérusalem, qui est en Judée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Qui est-ce d’entre vous de tout son peuple qui s’y veuille employer? Que son Dieu soit avec lui, et qu’il monte à Jérusalem, qui est en Judée, et qu’il rebâtisse la maison de l’Eternel le Dieu d’Israël; c’est le Dieu qui habite à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Et quant à tous ceux qui demeureront en arrière, de quelque lieu que ce soit où ils fassent leur séjour, que les gens du lieu où ils demeurent, les soulagent d’argent, d’or, de biens, et de montures, outre ce qu’on offrira volontairement pour la maison du Dieu qui habite à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Alors les Chefs des pères de Juda, de Benjamin, des Sacrificateurs et des Lévites, se levèrent pour conduire tous ceux dont Dieu réveilla l’esprit, afin de remonter pour rebâtir la maison de l’Eternel, qui habite à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Et tous ceux qui étaient à l’entour d’eux les encouragèrent, leur fournissant des vaisseaux d’argent, et d’or, des biens, des montures, et des choses exquises, outre tout ce qu’on offrit volontairement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Et le Roi Cyrus fit prendre les vaisseaux de la maison de l’Eternel, que Nébucadnetsar avait tirés de Jérusalem, et qu’il avait mis dans la maison de son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Et Cyrus, Roi de Perse, les fit sortir par Mithredath, le trésorier, qui les livra par compte à Sesbatsar, Prince de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Et c’est ici leur nombre, trente bassins d’or, mille bassins d’argent, vingt et neuf couteaux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'Trente plats d’or, quatre cent et dix plats d’argent du second ordre, et d’autres ustensiles par milliers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Tous les ustensiles d’or et d’argent étaient cinq mille quatre cents. Sesbatsar les fit tous rapporter, quand on fit remonter de Babylone à Jérusalem le peuple qui en avait été transporté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Or ce sont ici ceux de la province qui remontèrent de la captivité, d’entre ceux qui avaient été transportés, que Nébucadnetsar Roi de Babylone avait transportés à Babylone, et qui retournèrent à Jérusalem, et en Judée; chacun en sa ville;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Qui vinrent avec Zorobabel, Jésuah, Néhémie, Séraja, Réhélaja, Mardochée, Bilsan, Mispar, Bigvaï, Réhun, et Bahana; le nombre, dis-je, des hommes du peuple d’Israël fut le suivant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Les enfants de Parrhos, deux mille cent soixante et douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Les enfants de Séphatia, trois cent soixante et douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Les enfants d’Arah, sept cent soixante et quinze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Les enfants de Pahath-Moab, des enfants de Jésuah, et de Joab, deux mille huit cent et douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Les enfants de Hélam, mille deux cent cinquante-quatre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Les enfants de Zattu, neuf cent quarante-cinq.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Les enfants de Zaccaï, sept cent soixante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Les enfants de Bani, six cent quarante-deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Les enfants de Bébaï, six cent vingt et trois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Les enfants d’Hazgad, mille deux cent vingt et deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Les enfants d’Adonikam, six cent soixante-six.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Les enfants de Bigvaï, deux mille cinquante-six.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Les enfants de Hadin, quatre cent cinquante-quatre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Les enfants d’Ater, issu d’Ezéchias, quatre-vingt-dix-huit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Les enfants de Betsaï, trois cent vingt et trois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Les enfants de Jora, cent et douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Les enfants de Hasum, deux cent vingt et trois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Les enfants de Guibhar, quatre-vingt et quinze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'Les enfants de Bethléhem, six-vingt et trois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Les gens de Nétopha, cinquante-six.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'Les gens de Hanathoth, cent vingt et huit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Les enfants d’Hazmaveth, quarante-deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'Les enfants de Kiriath-harim, de Képhira, et de Bééroth, sept cent quarante-trois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'Les enfants de Rama et de Guérah, six cent vingt et un.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'Les gens de Micmas, cent vingt et deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'Les gens de Béth-el et de Haï, deux cent vingt et trois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'Les enfants de Nébo, cinquante-deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Les enfants de Magbis, cent cinquante-six.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'Les enfants d’un autre Hélam, mille deux cent cinquante-quatre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Les enfants de Harim, trois cent et vingt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'Les enfants de Lod, de Hadid, et d’Ono, sept cent vingt-cinq.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'Les enfants de Jérico, trois cent quarante-cinq.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'Les enfants de Sénaa, trois mille six cent trente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Des Sacrificateurs. Les enfants de Jédahia, de la maison de Jésuah, neuf cent soixante et treize.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Les enfants d’Immer, mille cinquante-deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Les enfants de Pasur, mille deux cent quarante-sept.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Les enfants de Harim, mille et dix-sept.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Des Lévites. Les enfants de Jésuah, et de Kadmiel, d’entre les enfants de Hodavia, soixante et quatorze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Des chantres. Les enfants d’Asaph, cent vingt-huit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Des enfants des portiers. Les entants de Sallum, les enfants d’Ater, les enfants de Talmon, les enfants de Hakkub, les enfants de Hatita, les enfants de Sobaï, tous cent trente-neuf.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Des Néthiniens. Les enfants de Tsiha, les enfants de Hasupha, les enfants de Tabbahoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Les enfants de Kéros, les enfants de Sihaha, les enfants de Padon,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'Les enfants de Lebana, les enfants de Hagaba, les enfants de Hakkub,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Les enfants de Hagab, les enfants de Samlaï, les enfants de Hanan,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'Les enfants de Guiddel, les enfants de Gahar, les enfants de Réaja.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Les enfants de Retsin, les enfants de Nékoda, les enfants de Gazam,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'Les enfants de Huza, les enfants de Paséah, les enfants de Bésaï,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Les enfants d’Asna, les enfants de Méhunim, les enfants de Néphusim,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'Les enfants de Bakbuk, les enfants de Hakupha, les enfants de Harhur,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Les enfants de Batsluth, les enfants de Méhida, les enfants de Harsa,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'Les enfants de Barkos, les enfants de Sisra, les enfants de Témah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Les enfants de Netsiah, les enfants de Hatipha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Des enfants des serviteurs de Salomon; les enfants de Sotaï, les enfants de Sophereth, les enfants de Peruda,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Les enfants de Jahala, les enfants de Darkon, les enfants de Guiddel,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'Les enfants de Sépharia, les enfants de Hattil, les enfants de Pokéreth-hatsébajim, les enfants d’Ami.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Tous les Néthiniens, et les enfants des serviteurs de Salomon, furent trois cent quatre-vingtdouze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Or ce sont ici ceux qui montèrent de Telmelah, de Tel-harsa, de Kérub, d’Adan, et d’Immer; lesquels ne purent montrer la maison de leurs pères, ni leur race, et faire voir s’ils étaient d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Les enfants de Délaja, les enfants de Tobija, les enfants de Nékoda, six cent cinquante et deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'Des enfants des Sacrificateurs; les enfants de Habaja, les enfants de Kots, les enfants de Barzillaï, qui ayant pris pour femme une des filles de Barzillaï Galaadite, fut appelé de leur nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Ceux-là cherchèrent leur registre, en recherchant leur généalogie, mais ils n’y furent point trouvés; c’est pourquoi ils furent rejetés de la sacrificature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Et Attirsatha leur dit qu’ils ne mangeassent point des choses très-saintes, tandis que le Sacrificateur assisterait avec l’Urim et le Thummim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Tout le peuple ensemble était de quarante-deux mille trois cent soixante;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'Sans leurs serviteurs et leurs servantes, qui étaient sept mille trois cent trente-sept; et ils avaient deux cents chantres ou chanteuses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Ils avaient sept cent trente-six chevaux, et deux cent quarante- cinq mulets,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'Quatre cent trente-cinq chameaux, et six mille sept cent vingt ânes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Et quelques-uns d’entre les Chefs des pères, après qu’ils furent venus pour rebâtir la maison de l’Eternel, qui habite à Jérusalem, offrant volontairement pour la maison de Dieu, afin de la remettre en son état,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Donnèrent au trésor de l’ouvrage, selon leur pouvoir, soixante et un mille drachmes d’or, et cinq mille mines d’argent, et cent robes de Sacrificateurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Et ainsi les Sacrificateurs, les Lévites, quelques-uns du peuple, les chantres, les portiers, et les Néthiniens, habitèrent dans leurs villes, et tous ceux d’Israël aussi dans leurs villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Or le septième mois approchant, et les enfants d’Israël étant dans leurs villes, le peuple s’assembla à Jérusalem comme si ce n’eût été qu’un seul homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Alors Jésuah, fils de Jotsadak, se leva avec ses frères les Sacrificateurs, et Zorobabel fils de Salathiel, avec ses frères, et ils bâtirent l’autel du Dieu d’Israël, pour y offrir les holocaustes, ainsi qu’il est écrit dans la Loi de Moïse, homme de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Et ils posèrent l’autel de Dieu sur sa base, parce qu’ils avaient peur en eux-mêmes des peuples du pays, et ils y offrirent des holocaustes à l’Eternel, les holocaustes du matin et du soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Ils célébrèrent aussi la fête solennelle des Tabernacles, en la manière qu’il est écrit dans la Loi; et ils offrirent les holocaustes chaque jour, autant qu’il en fallait, selon que portait l’ordinaire de chaque jour;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'Après cela, l’holocauste continuel, et ceux des nouvelles lunes, et de toutes les fêtes solennelles de l’Eternel, lesquelles on sanctifiait, et de tous ceux qui présentaient une offrande volontaire à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Dès le premier jour du septième mois ils commencèrent à offrir des holocaustes à l’Eternel; bien que le Temple de l’Eternel ne fût pas encore fondé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Mais ils donnèrent de l’argent aux tailleurs de pierres et aux charpentiers, ils donnèrent aussi à manger et à boire, et de l’huile, aux Sidoniens et aux Tyriens, afin qu’ils amenassent du bois de cèdre du Liban à la mer de Japho, selon la permission que Cyrus, Roi de Perse, leur en avait donnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Et la seconde année de leur arrivée en la maison de Dieu à Jérusalem, au second mois, Zorobabel, fils de Salathiel, et Jésuah, fils de Jotsadak, et le reste de leurs frères, les Sacrificateurs, et les Lévites, et tous ceux qui étaient venus de la captivité à Jérusalem, commencèrent à fonder le Temple; et ils établirent des Lévites, depuis l’âge de vingt ans et au-dessus, pour presser l’ouvrage de la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Et Jésuah assistait avec ses fils et ses frères, et Kadmiel avec ses fils, enfants de Juda, pour presser ceux qui faisaient l’ouvrage en la maison de Dieu; et les fils de Hémadad, avec leurs fils et leurs frères, Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Et lorsque ceux qui bâtissaient fondaient le Temple de l’Eternel, on y fit assister les Sacrificateurs revêtus, ayant leurs trompettes; et les Lévites, enfants d’Asaph, avec les cymbales, pour louer l’Eternel, selon l’institution de David, Roi d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Et ils s’entre-répondaient en louant et célébrant l’Eternel, chantant: Qu’il est bon, parce que sa gratuité demeure à toujours sur Israël. Et tout le peuple jeta de grands cris de joie en louant l’Eternel, parce qu’on fondait la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Mais plusieurs des Sacrificateurs et des Lévites, et des Chefs des pères qui étaient âgés, et qui avaient vu la première maison sur son fondement, se représentant cette maison-là, pleuraient à haute voix; mais plusieurs élevaient leur voix avec des cris de réjouissance, et d’allégresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Et le peuple ne pouvait discerner la voix des cris de joie, et d’allégresse, d’avec la voix des pleurs du peuple; cependant le peuple jetait de grands cris de joie, en sorte que la voix fut entendue bien loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Or les ennemis de Juda et de Benjamin ayant entendu que ceux qui étaient retournés de la captivité rebâtissaient le Temple à l’Eternel, le Dieu d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'Vinrent vers Zorobabel et vers les Chefs des pères, et leur dirent: Permettez que nous bâtissions avec vous; car nous invoquerons votre Dieu comme vous faites; aussi lui avons-nous sacrifié depuis le temps d’Ezar-haddon Roi d’Assyrie, qui nous a fait monter ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Mais Zorobabel, et Jésuah, et les autres Chefs des pères d’Israël leur répondirent: Il n’est pas à propos que vous et nous bâtissions la maison à notre Dieu; mais nous, qui sommes ici ensemble, nous bâtirons à l’Eternel le Dieu d’Israël, ainsi que le Roi Cyrus Roi de Perse nous l’a commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'C’est pourquoi le peuple du pays rendait lâches les mains du peuple de Juda, et les effrayait lorsqu’ils bâtissaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Et même ils avaient à leurs gages des gens qui leur donnaient conseil afin de dissiper leur dessein, pendant tout le temps de Cyrus Roi de Perse, jusqu’au règne de Darius Roi de Perse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Car pendant le règne d’Assuérus, au commencement de son règne, ils écrivirent une accusation calomnieuse contre les habitants de Juda et de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Et du temps d’Artaxerxes, Bislam, Mithredat, Tabéel, et les autres de sa compagnie écrivirent à Artaxerxes Roi de Perse. L’écriture de la copie de la lettre était en lettres Syriaques, et elle était couchée en langue Syriaque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Réhum donc, Président du conseil, et Simsaï, le Secrétaire, écrivirent une Lettre touchant Jérusalem au Roi Artaxerxes, comme il s’ensuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Réhum Président du conseil, et Simsaï le Secrétaire, et les autres de leur compagnie, Diniens, Apharsatkiens, Tarpéliens, Arphasiens, Arkéviens, Babyloniens, Susankiens, Déhaviens, et Hélamites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'Et les autres peuples que le grand et glorieux Osnapar avait transportés, et fait habiter dans la ville de Samarie, et les autres qui étaient de deçà le fleuve; de telle date.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'C’est donc ici la teneur de la Lettre qu’ils lui envoyèrent. Au Roi Artaxerxes. Tes serviteurs les gens de deçà le fleuve, et de telle date.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Que le Roi soit averti, que les Juifs qui sont montés d’auprès de lui vers nous, sont venus à Jérusalem, et qu’ils bâtissent la ville rebelle et méchante, et posent les fondements des murailles, et les relèvent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Que maintenant donc le Roi soit averti, que si cette ville est rebâtie, et ses murailles fondées, ils ne paieront plus de taille, ni de gabelle, ni de péage, et elle causera ainsi une grande perte aux revenus du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Et parce que nous sommes aux gages du Roi, il nous serait mal- séant, de voir ce mépris du Roi; c’est pourquoi nous avons envoyé au Roi, et nous lui faisons savoir;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'Qu’il cherche au Livre des Mémoires de ses pères, et qu’il trouvera écrit dans ce Livre des Mémoires, et y apprendra que cette ville est une ville rebelle, et pernicieuse aux Rois et aux provinces; et que de tout temps on y a fait des complots, et qu’à cause de cela cette ville a été détruite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Nous faisons donc savoir au Roi, que si cette ville est rebâtie, et ses murailles fondées, il n’aura plus de part à ce qui est au deçà du fleuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Et c’est ici la réponse que le Roi envoya à Réhum, Président du conseil, et à Simsaï le Secrétaire, et aux autres de leur compagnie qui demeuraient à Samarie, et aux autres de deçà le fleuve. Bien vous soit, et de telle date.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'La teneur des lettres que vous nous avez envoyées, a été exposée et lue devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Et j’ai donné ordre, et on a cherché et trouvé, que de tout temps cette ville-là s’élève contre les Rois, et qu’on y a fait des rébellions et des complots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Et qu’aussi il y a eu à Jérusalem des Rois puissants, qui ont dominé sur tous ceux de delà le fleuve, et qu’on leur payait des tailles, des gabelles et des péages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Maintenant donc, donnez un ordre pour faire cesser ces gens-là, afin que cette ville ne soit point rebâtie, jusques à ce que je l’ordonne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Et gardez-vous de manquer en ceci; car pourquoi croîtrait le dommage au préjudice des Rois?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Or quand la teneur des patentes du Roi Artaxerxes eut été lue en la présence de Réhum, et de Simsaï le Secrétaire, et de ceux de leur compagnie, ils s’en allèrent en diligence à Jérusalem vers les Juifs, et les firent cesser avec main forte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Alors le travail de la maison de Dieu, qui habite à Jérusalem, cessa, et elle demeura dans cet état, jusqu’à la seconde année du règne de Darius Roi de Perse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Alors Aggée le Prophète, et Zacharie, fils de Hiddo le Prophète, prophétisaient aux Juifs qui étaient en Juda et à Jérusalem, au Nom du Dieu d’Israël, qui les avait envoyés vers eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Et Zorobabel fils de Salathiel, et Jésuah fils de Jotsadak, se levèrent et commencèrent à rebâtir la maison de Dieu, qui habite à Jérusalem; et ils avaient avec eux les Prophètes de Dieu, qui les aidaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'En ce temps-là Tattenaï, Gouverneur de deçà le fleuve, et Sétharboznaï, et leurs compagnons vinrent à eux et leur parlèrent ainsi: Qui vous a donné ordre de rebâtir cette maison, et de fonder ces murailles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Et ils leur parlèrent aussi en cette manière: Quels sont les noms des hommes qui bâtissent cet édifice?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Mais parce que sur les Anciens des Juifs était l’oeil de leur Dieu, on ne les fit point cesser, jusqu’à ce que l’affaire parvint à Darius, et qu’alors ils rapportassent des Lettres sur cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'La teneur des Lettres que Tattenaï Gouverneur de deçà le fleuve, et Sétharboznaï, et ses compagnons Apharsékiens, qui étaient de deçà le fleuve, envoyèrent au Roi Darius.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Ils lui envoyèrent une relation du fait, et il y avait ainsi écrit: Toute paix soit au Roi Darius.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Que le Roi soit averti que nous sommes allés en la province de Judée, vers la maison du grand Dieu, laquelle on bâtit de grosses pierres, et même la charpenterie est posée aux parois, et cet édifice se bâtit en diligence, et s’avance entre leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Et nous avons interrogé les Anciens qui étaient là, et nous leur avons parlé ainsi: Qui vous a donné ordre de rebâtir cette maison, et de fonder ces murailles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Et nous leur avons aussi demandé leurs noms, pour les faire savoir au Roi, afin que nous écrivissions les noms des principaux d’entr’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Et ils nous ont répondu de cette manière, disant: Nous sommes les serviteurs du Dieu des cieux et de la terre, et nous rebâtissons la maison qui avait été bâtie ci-devant il y a longtemps, laquelle un grand Roi d’Israël avait bâtie et fondée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Mais après que nos pères eurent provoqué à la colère le Dieu des cieux, il les livra entre les mains de Nébucadnetsar Roi de Babylone, Caldéen, qui détruisit cette maison, et qui transporta le peuple à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Mais en la première année de Cyrus, Roi de Babylone, le Roi Cyrus commanda qu’on rebâtît cette maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Et même le Roi Cyrus tira hors du Temple de Babylone les vaisseaux d’or et d’argent de la maison de Dieu, que Nébucadnetsar avait emportés du Temple qui était à Jérusalem, et qu’il avait apportés au Temple de Babylone, et ils furent délivrés à un nommé Sesbatsar, lequel il avait établi Gouverneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'Et il lui dit: Prends ces ustensiles, et t’en va, et fais-les porter au Temple qui était à Jérusalem; et que la maison de Dieu soit rebâtie en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Alors ce Sesbatsar vint, et posa les fondements de la maison de Dieu, qui habite à Jérusalem; et depuis ce temps-là jusqu’à présent, on la bâtit, et elle n’est point encore achevée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Maintenant donc, s’il semble bon au Roi, qu’on cherche dans la maison des trésors du Roi laquelle est à Babylone, s’il est vrai qu’il y ait eu un ordre donné par Cyrus de rebâtir cette maison de Dieu à Jérusalem; et que le Roi nous fasse savoir sa volonté sur cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Alors le Roi Darius donna ses ordres, et on rechercha dans le lieu où l’on tenait les registres, et où l’on mettait les trésors en Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Et on trouva dans un coffre, au palais Royal, qui était dans la province de Mède, un rouleau; et ce Mémoire y était ainsi couché par écrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'La première année du Roi Cyrus, le Roi Cyrus ordonna; que quant à la maison de Dieu à Jérusalem, cette maison-là serait rebâtie, afin qu’elle fût le lieu où l’on fît les sacrifices, et que ses fondements seraient assez forts pour soutenir son faix, de laquelle la hauteur serait de soixante coudées, et la longueur de soixante coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Et qu’on bâtirait trois rangées de grosses pierres, et une rangée de bois neuf, et que la dépense serait fournie de l’hôtel du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Et quant aux ustensiles d’or et d’argent de la maison de Dieu, lesquels Nébucadnetsar avait tirés du Temple qui était à Jérusalem, et apportés à Babylone, qu’on les rendrait, et qu’ils seraient remis au Temple qui était à Jérusalem, chacun en sa place, et qu’on les ferait conduire en la maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Maintenant donc, vous Tattenaï, Gouverneur de delà le fleuve, et Sétharboznaï, et vos compagnons Apharsékiens, qui êtes de delà le fleuve, retirez-vous de là;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Laissez faire l’ouvrage de cette maison de Dieu, et que le Gouverneur des Juifs et leurs Anciens rebâtissent cette maison de Dieu en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Et cet ordre est fait de ma part touchant ce que vous aurez à faire, avec les Anciens de ces Juifs pour rebâtir cette maison de Dieu, c’est que des finances du Roi qui reviennent des tailles de delà le fleuve, les frais soient incontinent fournis à ces gens-là, afin qu’on ne les fasse point chômer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Et quant à ce qui sera nécessaire, soit veaux, soit moutons, ou agneaux pour les holocaustes qu’il faut faire au Dieu des cieux, soit blé, ou sel, ou vin et huile, ainsi que le diront les Sacrificateurs qui sont à Jérusalem, qu’on le leur donne chaque jour, sans y manquer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Afin qu’ils offrent des sacrifices de bonne odeur au Dieu des cieux, et qu’ils prient pour la vie du Roi et de ses enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'J’ordonne aussi, que quiconque changera ceci, on arrache de sa maison un bois qui sera dressé, afin qu’il y soit exterminé, et qu’à cause de cela on fasse de sa maison une voirie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Et que Dieu, qui a fait habiter là son Nom, détruise tout Roi et tout peuple qui aura étendu sa main pour changer et détruire cette maison de Dieu qui habite à Jérusalem. Moi Darius ai donné cet ordre; qu’il soit donc incontinent exécuté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Alors Tattenaï, Gouverneur de deçà le fleuve, et Sétharboznaï, et ses compagnons le firent incontinent exécuter, parce que le Roi Darius le leur avait ainsi écrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Or les Anciens des Juifs bâtissaient, et ils prospéraient suivant la prophétie d’Aggée le Prophète, et de Zacharie, fils de Hiddo. Ils bâtirent donc ayant posé les fondements par le commandement du Dieu d’Israël, et par l’ordre de Cyrus et de Darius, et aussi d’Artaxerxes, Roi de Perse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Et cette maison de Dieu fut achevée le troisième jour du mois d’Adar, en la sixième année du règne du Roi Darius.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Et les enfants d’Israël, les Sacrificateurs, les Lévites, et le reste de ceux qui étaient retournés de la captivité, célébrèrent la dédicace de cette maison de Dieu avec joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Et ils offrirent pour la dédicace de cette maison de Dieu, cent veaux, deux cents béliers, quatre cents agneaux, et douze jeunes boucs pour le péché pour tout Israël, selon le nombre des Tribus d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Et ils établirent les Sacrificateurs en leurs rangs, et les Lévites en leurs départements, pour le service qui se fait à Dieu dans Jérusalem; selon ce qui en est écrit au Livre de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Puis ceux qui étaient retournés de la captivité célébrèrent la Pâque le quatorzième jour du premier mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Car les Sacrificateurs s’étaient purifiés avec les Lévites, de sorte qu’ils étaient tous nets, c’est pourquoi ils égorgèrent la Pâque pour tous ceux qui étaient retournés de la captivité, et pour leurs frères les Sacrificateurs, et pour eux-mêmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Ainsi elle fut mangée par les enfants d’Israël qui étaient revenus de la captivité, et par tous ceux qui s’étaient retirés vers eux de la souillure des nations du pays, pour rechercher l’Eternel le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Et ils célébrèrent avec joie la fête solennelle des pains sans levain pendant sept jours, parce que l’Eternel leur avait donné matière de joie, en ayant tourné vers eux le coeur du Roi d’Assyrie, pour fortifier leurs mains dans le travail de la maison de Dieu, le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Or après ces choses, et durant le règne d’Artaxerxes, Roi de Perse, Esdras fils de Séraja, fils de Hazaria, fils de Hilkija,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'Fils de Sallum, fils de Tsadok, fils d’Ahitub,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'Fils d’Amaria, fils de Hazaria, fils de Mérajoth,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'Fils de Zérahia, fils de Huzi, fils de Bukki,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'Fils d’Abisuah, fils de Phinées, fils d’Eléazar, fils d’Aaron premier Sacrificateur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Esdras, dis-je, qui était un Scribe bien exercé en la Loi de Moïse, que l’Eternel le Dieu d’Israël avait donnée, monta de Babylone, et le Roi lui accorda toute sa requête, selon que la main de l’Eternel son Dieu était sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Quelques-uns aussi des enfants d’Israël, des Sacrificateurs, des Lévites, des chantres, des portiers, et des Néthiniens, montèrent à Jérusalem la septième année du Roi Artaxerxes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Et Esdras arriva à Jérusalem le cinquième mois de la septième année du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Car au premier jour du premier mois, on commença de partir de Babylone; et au premier jour du cinquième mois il arriva à Jérusalem, selon que la main de son Dieu était bonne sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Car Esdras avait disposé son coeur à étudier la Loi de l’Eternel, et à la faire, et à enseigner parmi le peuple d’Israël les statuts, et les ordonnances.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Or c’est ici la teneur des patentes que le Roi Artaxerxes donna à Esdras, Sacrificateur et Scribe, Scribe des paroles des commandements de l’Eternel et de ses ordonnances, entre les Israélites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Artaxerxes Roi des Rois, à Esdras Sacrificateur et Scribe de la Loi du Dieu des cieux, soit une parfaite santé; et de telle date.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'J’ordonne, que tous ceux de mon Royaume qui sont du peuple d’Israël, et de ses Sacrificateurs et Lévites, qui se présenteront volontairement pour aller à Jérusalem, aillent avec toi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Parce que tu es envoyé de la part du Roi, et de ses sept conseillers, pour t’informer en Judée, et à Jérusalem touchant la Loi de ton Dieu, laquelle tu as en ta main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'Et pour porter l’argent et l’or que le Roi et ses conseillers ont volontairement offerts au Dieu d’Israël, dont la demeure est à Jérusalem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'Et tout l’argent et l’or que tu trouveras en toute la province de Babylone, avec les offrandes volontaires du peuple et des Sacrificateurs, offrant volontairement à la maison de leur Dieu qui habite à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Afin qu’incessamment tu achètes de cet argent-là des veaux, des béliers, des agneaux, avec leurs gâteaux et leurs aspersions, et que tu les offres sur l’autel de la maison de votre Dieu, qui habite à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Et que vous fassiez selon la volonté de votre Dieu, ce qu’il te semblera bon à toi et à tes frères de faire du reste de l’argent et de l’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Et quant aux ustensiles qui te sont donnés pour le service de la maison de ton Dieu, remets-les en la présence du Dieu de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Et quant au reste qui sera nécessaire pour la maison de ton Dieu, autant qu’il t’en faudra employer, tu le prendras de la maison des trésors du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Et de ma part Artaxerxes Roi il est ordonné à tous les trésoriers qui sont au delà du fleuve, que tout ce qu’Esdras Sacrificateur et Scribe de la Loi du Dieu des cieux vous demandera soit fait incontinent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'Jusqu’à cent talents d’argent, et jusqu’à cent Cores de froment, et jusqu’à cent Bats de vin, et jusqu’à cent Bats d’huile; et du sel sans nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Que tout ce qui est commandé par le Dieu des cieux, soit promptement fait à la maison du Dieu des cieux; de peur qu’il n’y ait de l’indignation contre le Royaume, et contre le Roi et ses enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'De plus, nous vous faisons savoir qu’on ne pourra imposer ni taille, ni gabelle, ni péage sur aucun Sacrificateur, ou Lévite, ou chantre, ou portier, ou Néthinien, ou ministre de cette maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Et quant à toi, Esdras, établis des magistrats et des juges selon la sagesse de ton Dieu, de laquelle tu es doué, afin qu’ils fassent justice à tout ce peuple qui est au delà du fleuve; c’est-à-dire, à tous ceux qui connaissent les lois de ton Dieu, et afin que vous enseigniez celui qui ne les saura point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Et quant à tous ceux qui n’observeront point la Loi de ton Dieu, et la Loi du Roi, qu’il soit aussitôt jugé, soit à la mort, soit au bannissement, soit à une amende pécuniaire, ou à l’emprisonnement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Béni soit l’Eternel, le Dieu de nos pères, qui a mis une telle chose au coeur du Roi, pour honorer la maison de l’Eternel, qui habite à Jérusalem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'Et qui a fait que j’ai trouvé grâce devant le Roi, devant ses conseillers, et devant tous les puissants gentils-hommes du Roi. Ainsi donc m’étant fortifié, selon que la main de l’Eternel mon Dieu était sur moi, j’assemblai les Chefs d’Israël, afin qu’ils montassent avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Or ce sont ici les Chefs des pères, avec le dénombrement qui fut fait selon les généalogies, de ceux qui montèrent avec moi de Babylone, pendant le règne du Roi Artaxerxes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Des enfants de Phinées, Guersom; des enfants d’Ithamar, Daniel; des enfants de David, Hattus;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'Des enfants de Sécania, qui était des enfants de Parhos, Zacharie, et avec lui, en faisant le dénombrement par leur généalogie selon les mâles, cent cinquante hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Des enfants de Péhath-Moab, Eliehohénaï fils de Zérahia, et avec lui deux cents hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Des enfants de Sécania, le fils de Jahaziël, et avec lui trois cents hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Des enfants de Hadin, Hébed fils de Jonathan, et avec lui cinquante hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Des enfants de Hélam, Esaïe, fils de Hathalia, et avec lui soixante-dix hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Des enfants de Sépharia, Zébadia fils de Micaël, et avec lui quatre-vingts hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Des enfants de Joab, Habadia fils de Jéhiël, et avec lui deux cent dix-huit hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'Des enfants de Sélomith, le fils de Josiphia, et avec lui cent soixante hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Des enfants de Bébaï, Zacharie fils de Bébaï, et avec lui vingt- huit hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'Des enfants de Hazgad, Johanan, fils de Katan, et avec lui cent et dix hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'Des enfants d’Adonicam, les derniers, desquels les noms sont Eliphelet, Jéhiël, et Sémahia, et avec eux soixante hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'Des enfants de Bigvaï, Huthaï, Zabbud, et avec eux soixante-dix hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Et je les assemblai près de la rivière, qui se rend à Ahava, et nous y demeurâmes trois jours. Puis je pris garde au peuple et aux Sacrificateurs, et je n’y trouvai aucun des enfants de Lévi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Et ainsi j’envoyai d’entre les principaux Elihéser, Ariel, Sémahia, Elnathan, Jarib, Elnathan, Nathan, Zacharie, et Mésullam, avec Jojarib et Elnathan, docteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'Et je leur donnai des ordres pour Iddo, principal chef, qui demeurait dans le lieu de Casiphia; et je mis en leur bouche les paroles qu’ils devaient dire à Iddo, et à son frère, Néthiniens, dans le lieu de Casiphia, afin qu’ils nous fissent venir des ministres pour la maison de notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Et ils nous amenèrent, selon que la main de notre Dieu était bonne sur nous, un homme intelligent, d’entre les enfants de Mahli, fils de Lévi, fils d’Israël; savoir Sérébia, avec ses fils et ses frères, qui furent dix-huit hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'Et Hasabia, et avec lui Esaïe, d’entre les enfants de Mérari, ses frères, et leurs enfants, vingt hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'Et des Néthiniens, que David et les principaux du peuple avaient assignés pour le service des Lévites, deux cent et vingt Néthiniens, qui furent tous nommés par leurs noms.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Et je publiai là le jeûne auprès de la rivière d’Ahava, afin de nous humilier devant notre Dieu, le priant de nous donner un heureux voyage pour nous, et pour nos familles, et pour tous nos biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Car j’eus honte de demander au Roi des forces et des gens de cheval pour nous défendre des ennemis par le chemin; à cause que nous avions dit au Roi en termes exprès: La main de notre Dieu est favorable à tous ceux qui l’invoquent; mais sa force et sa colère est contre ceux qui l’abandonnent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Nous jeûnâmes donc, et nous implorâmes le secours de notre Dieu à cause de cela; et il fut fléchi par nos prières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Alors je séparai douze des principaux des Sacrificateurs; avec Sérébia, Hasabia, et avec eux dix de leurs frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'Et je leur pesai l’argent et l’or et les ustensiles, qui étaient l’offrande que le Roi, ses conseillers, ses gentilshommes, et tous ceux d’Israël qui s’ y étaient trouvés, avaient faite à la maison de notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Je leur pesai donc, et je leur délivrai six cent cinquante talents d’argent, et des plats d’argent pesant cent talents, et cent talents d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'Et vingt plats d’or montant à mille drachmes, et deux ustensiles de cuivre resplendissant et fin, aussi précieux que s’ils eussent été d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Et je leur dis: Vous êtes sanctifiés à l’Eternel; et les ustensiles sont sanctifiés; et cet argent et cet or est une offrande volontaire faite à l’Eternel le Dieu de vos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Ayez-y l’oeil et gardez-les, jusqu’à ce que vous les pesiez en la présence des principaux des Sacrificateurs et des Lévites, et devant les principaux des pères d’Israël à Jérusalem, dans les chambres de la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Les Sacrificateurs donc et les Lévites reçurent le poids de l’argent, et de l’or, et des ustensiles, pour les apporter à Jérusalem, dans la maison de notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Et nous partîmes de la rivière d’Ahava le douzième jour du premier mois, pour aller à Jérusalem; et la main de notre Dieu fut sur nous; et il nous délivra de la main des ennemis, et de leurs embûches sur le chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Puis nous arrivâmes à Jérusalem, et nous étant reposés trois jours,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Au quatrième jour nous pesâmes l’argent et l’or, et les ustensiles dans la maison de notre Dieu, et nous les délivrâmes à Mérémoth, fils d’Urija Sacrificateur, avec lequel était Eléazar fils de Phinées; et avec eux Jozabad fils de Jésuah, et Nohadia, fils de Binuï, Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Selon le nombre et le poids de toutes ces choses, et tout le poids en fut mis alors par écrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Et ceux qui avaient été transportés, et qui étaient retournés de la captivité, offrirent pour tout Israël, en holocauste au Dieu d’Israël, douze veaux, quatre-vingt-seize béliers, soixante-dix-sept agneaux, et douze boucs pour le péché; le tout en holocauste à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Et ils remirent les ordonnances du Roi entre les mains des Satrapes du Roi et des Gouverneurs qui étaient au deçà du fleuve, lesquels favorisèrent le peuple, et la maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Or sitôt que ces choses-là furent achevées, les principaux du peuple s’approchèrent vers moi, en disant: Le peuple d’Israël, et les Sacrificateurs, et les Lévites ne se sont point séparés des peuples de ces pays, comme ils le devaient faire à cause de leurs abominations, savoir des Cananéens, des Héthiens, des Phéréziens, des Jébusiens, des Hammonites, des Moabites, des Egyptiens, et des Amorrhéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Car ils ont pris de leurs filles pour eux et pour leurs fils; et la semence sainte a été mêlée avec les peuples de ces pays; et même il y a des principaux du peuple, et plusieurs magistrats, qui ont été les premiers à commettre ce péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Et sitôt que j’eus entendu cela, je déchirai mes vêtements, et mon manteau, et j’arrachai les cheveux de ma tête, et les poils de ma barbe, et je m’assis tout désolé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Et tous ceux qui tremblaient aux paroles du Dieu d’Israël, s’assemblèrent vers moi à cause du crime de ceux de la captivité, et je demeurai assis tout désolé jusqu’à l’oblation du soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Et au temps de l’oblation du soir je me levai de mon affliction, et ayant mes vêtements et mon manteau déchirés, je me mis à genoux, et j’étendis mes mains vers l’Eternel mon Dieu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'Et je dis: Mon Dieu! j’ai honte, et je suis trop confus pour oser élever, ô mon Dieu! ma face vers toi; car nos iniquités sont multipliées au dessus de nos têtes, et notre crime s’est élevé jusques aux cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Depuis les jours de nos pères jusqu’à aujourd’hui nous sommes extrêmement coupables; et nous avons été livrés à cause de nos iniquités, nous, nos Rois, et nos Sacrificateurs, entre les mains des Rois des pays, pour être mis au fil de l’épée, emmenés captifs, pillés, et exposés à l’ignominie, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Mais l’Eternel notre Dieu nous a maintenant fait grâce, comme en un moment, de sorte qu’il a fait que quelques-uns de nous sont demeurés de reste, et il nous a donné un clou dans son saint lieu, afin que notre Dieu éclairât nos yeux, et nous donnât quelque petit répit dans notre servitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Car nous sommes esclaves, et toutefois notre Dieu ne nous a point abandonnés dans notre servitude; mais il nous a fait trouver grâce devant les Rois de Perse, pour nous donner du répit, afin de relever la maison de notre Dieu, et rétablir ses lieux déserts, et pour nous donner une cloison en Juda, et à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Mais maintenant, ô notre Dieu! que dirons-nous après ces choses? car nous avons abandonné tes commandements,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'Que tu as donnés par tes serviteurs les Prophètes, en disant: Le pays auquel vous allez entrer pour le posséder, est un pays souillé par la souillure des peuples de ces pays-là, à cause des abominations dont ils l’ont rempli, depuis un bout jusqu’à l’autre par leurs impuretés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Maintenant donc, ne donnez point vos filles à leurs fils, et ne prenez point leurs filles pour vos fils, et ne cherchez point leur paix, ni leur bien à jamais; afin que vous soyez affermis, et que vous mangiez les biens du pays, et que vous le fassiez hériter à vos fils pour toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Or après toutes les choses qui nous sont arrivées à cause de nos mauvaises oeuvres, et du grand crime qui s’est trouvé en nous; et parce, ô notre Dieu! que tu es demeuré dans tes punitions au dessous de ce que nos péchés méritaient, et que tu nous as donné un résidu tel qu’est celui-ci;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'Retournerions-nous à enfreindre tes commandements, et à faire alliance avec ces peuples abominables? Ne serais-tu pas irrité contre nous, jusqu’à nous consumer, en sorte qu’il n’y aurait plus aucun résidu, ni aucune ressource?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Eternel Dieu d’Israël! tu es juste; car nous sommes demeurés de reste, comme il se voit aujourd’hui. Voici, nous sommes devant toi avec notre crime; quoiqu’il n’y ait pas moyen de subsister devant toi à cause de ce que nous avons fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Et comme Esdras priait, et faisait cette confession, pleurant, et étant prosterné en terre devant la maison de Dieu, une fort grande multitude d’hommes, et de femmes, et d’enfants de ceux d’Israël, s’assembla vers lui; et le peuple pleura abondamment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Alors Sécania fils de Jéhiël, d’entre les enfants de Hélam, prit la parole, et dit à Esdras: Nous avons péché contre notre Dieu, en ce que nous avons pris des femmes étrangères d’entre les peuples de ce pays; mais maintenant il y a espérance pour Israël en ceci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'C’est pourquoi traitons maintenant cette alliance avec notre Dieu, que nous ferons sortir toutes les femmes, et tout ce qui est né d’elles, selon le conseil du Seigneur, et de ceux qui tremblent au commandement de notre Dieu; et qu’il en soit fait selon la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Lève-toi, car cette affaire te regarde, et nous serons avec toi; prends donc courage, et agis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Alors Esdras se leva, et fit jurer les principaux des Sacrificateurs, des Lévites, et de tout Israël, qu’ils feraient selon cette parole; et ils jurèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Puis Esdras se leva de devant la maison de Dieu, et s’en alla dans la chambre de Johanan fils d’Eliasib, et y entra; et il ne mangea point de pain, ni ne but point d’eau, parce qu’il menait deuil à cause du péché de ceux de la captivité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Alors on publia dans le pays de Juda et dans Jérusalem, à tous ceux qui étaient retournés de la captivité, qu’ils eussent à s’assembler à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'Et que quiconque ne s’y rendrait pas dans trois jours, selon l’avis des principaux et des Anciens, tout son bien serait mis à l’interdit, et que pour lui, il serait séparé de l’assemblée de ceux de la captivité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Ainsi tous ceux de Juda et de Benjamin s’assemblèrent à Jérusalem dans les trois jours, ce qui fut au neuvième mois le vingtième jour du mois; et tout le peuple se tint devant la place de la maison de Dieu, tremblant pour ce sujet, et à cause des pluies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Puis Esdras le Sacrificateur se leva, et leur dit: Vous avez péché en ce que vous avez pris chez vous des femmes étrangères, de sorte que vous avez augmenté le crime d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Mais maintenant faites confession de votre faute à l’Eternel le Dieu de vos pères, et faites sa volonté, et séparez-vous des peuples du pays, et des femmes étrangères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Et toute l’assemblée répondit, et dit à haute voix: C’est notre devoir de faire ce que tu as dit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Mais le peuple est grand, et ce temps est fort pluvieux, c’est pourquoi il n’ y a pas moyen de demeurer dehors, et cette affaire n’est pas d’un jour, ni de deux; car nous sommes beaucoup de gens qui avons péché en cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Que tous les principaux d’entre nous comparaissent donc devant toute l’assemblée, et que tous ceux qui sont dans nos villes, et qui ont pris chez eux des femmes étrangères, viennent en certain temps, et que les Anciens de chaque ville et ses juges soient avec eux; jusqu’à ce que nous détournions de nous l’ardeur de la colère de notre Dieu, et que ceci soit achevé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Et Jonathan fils d’Hazaël, et Jahzéja fils de Tikva furent établis pour cette affaire; et Mésullam et Sabéthaï, Lévites, les aidèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Et ceux qui étaient retournés de la captivité en firent de même, tellement qu’on choisit Esdras le Sacrificateur, et ceux qui étaient les Chefs des pères selon les maisons de leurs pères, tous nommés par leurs noms, qui commencèrent leurs séances le premier jour du dixième mois, pour s’informer du fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'Et le premier jour du premier mois ils eurent fini avec tous ceux qui avaient pris chez eux des femmes étrangères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Or quant aux fils des Sacrificateurs qui avaient pris chez eux des femmes étrangères, il se trouva d’entre les enfants de Jésuah, fils de Jotsadak et de ses frères, Mahaséja, Elihézer, Jarib, et Guédalia;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'Qui donnèrent les mains à renvoyer leurs femmes; et avouant qu’ils étaient coupables, ils offrirent pour leur délit un bélier du troupeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Des enfants d’Immer, Hanani, et Zébadia;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'Et des enfants de Harim, Mahaséja, Elie, Sémahia, Jéhiël, et Huzija;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'Et des enfants de Pashur, Eliohenaï, Mahaséja, Ismaël, Nathanaël, Jozabad, et Elhasa;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Et des Lévites, Jozabad, Simhi, Kélaja, (qui est le même que Kélita) Péthahia, Juda, et Elihézer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Et des chantres, Eliasib; et des portiers, Sallum, Telem, et Uri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Et de ceux d’Israël; des enfants de Parhos, Ramia, Jizija, Malkija, Mijamin, Elhazar, Malkija et Bénaja;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'Et des enfants de Hélam, Mattania, Zacharie, Jéhiël, Habdi, Jérémoth, et Elie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'Et des enfants de Zattu, Eliohénaï, Eliasib, Mattania, Jérémoth, Zabad, et Haziza;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'Et des enfants de Bébaï, Johanan, Hanania, Zabbaï, et Hathlaï;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'Et des enfants de Bani, Mésullam, Malluc, Hadaja, Jasub, Séal, et Ramoth;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'Et des enfants de Pahath-Moab, Hadna, Kélal, Bénaja, Mahaséja, Mattania, Bethsaléël, Binnuï, et Manassé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'Et des enfants de Harim, Elihézer, Jisija, Malkija, Sémahia, Siméon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Malluc et Semaria;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Et des enfants de Masum, Mattenaï, Mattata, Zabad, Eliphélet, Jérémaï, Manassé, et Simhi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Et des enfants de Bani, Mahadaï, Hamram, Uël,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Bénaja, Bédéja, Kéluhu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vania, Mérémoth, Eliasib,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mattania, Matténaï, Jahasaï,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Bani, Binnuï, Simhi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Sélémia, Nathan, Hadaja,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Mabnadbaï, Sasaï, Saraï,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Hazaréel, Sélémia, Sémaria,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Sallum, Amaria, et Joseph;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Et des enfants de Nébo, Jéhiël, Mattitia, Zabad, Zébina, Jaddan, Joël, et Bénaja.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Tous ceux-là avaient pris des femmes étrangères; et il y avait quelques-uns d’entr’eux qui avaient eu des enfants de ces femmes-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Les faits de Néhémie, fils de Hacalia. Il arriva au mois de Kisleu, en la vingtième année, comme j’étais à Susan, la ville capitale,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Que Hanani, l’un de mes frères, et quelques gens, arrivèrent de Juda; et je m’enquis d’eux touchant les Juifs réchappés, qui étaient de reste de la captivité, et touchant Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Et ils me dirent: Ceux qui sont restés de la captivité, sont là dans la province, dans une grande misère et en opprobre; et la muraille de Jérusalem demeure renversée, et ses portes brûlées par feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Or il arriva que dès que j’eus entendu ces paroles, je m’assis, je pleurai, je menai deuil quelques jours, je jeûnai, et je fis ma prière devant le Dieu des cieux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'Et je dis: Je te prie, ô Eternel! Dieu des cieux, qui es le Fort, le Grand et le Terrible, qui gardes l’alliance et la gratuité à ceux qui t’aiment et qui observent tes commandements!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Je te prie, que ton oreille soit attentive, et que tes yeux soient ouverts pour entendre la prière de ton serviteur, laquelle je te présente en ce temps- ci, jour et nuit, pour les enfants d’Israël tes serviteurs, en faisant confession des péchés des enfants d’Israël, lesquels nous avons commis contre toi; même moi et la maison de mon père, nous avons péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Certainement nous sommes coupables devant toi, et nous n’avons point gardé les commandements, ni les ordonnances, ni les jugements que tu as prescrits à Moïse, ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Mais je te prie, souviens-toi de la parole dont tu donnas charge à Moïse, ton serviteur, en disant: Vous commettrez des crimes, et je vous disperserai parmi les peuples;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'Puis vous retournerez à moi, et vous garderez mes commandements, et les ferez; et s’il y en a d’entre vous qui aient été chassés jusqu’à un bout des cieux, je vous rassemblerai de là, et je vous ramènerai au lieu que j’aurai choisi pour y faire habiter mon Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Or ceux-ci sont tes serviteurs et ton peuple, que tu as racheté par ta grande puissance et par ta main forte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Je te prie donc, Seigneur! que ton oreille soit maintenant attentive à la prière de ton serviteur, et à la supplication de tes serviteurs, qui prennent plaisir à craindre ton Nom; et fais, je te prie, prospérer aujourd’hui ton serviteur, et fais qu’il trouve grâce envers cet homme-ci; car j’étais échanson du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Et il arriva, au mois de Nisan, la vingtième année du Roi Artaxerxes, que le vin ayant été apporté devant lui, je pris le vin, et le présentai au Roi. Or je n’avais jamais eu mauvais visage devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Et le Roi me dit: Pourquoi as-tu mauvais visage, puisque tu n’es point malade? Cela ne vient que d’une mauvaise disposition d’esprit. Alors je craignis fort;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'Et je répondis au Roi: Que le Roi vive éternellement! Comment mon visage ne serait-il pas mauvais, puisque la ville qui est le lieu des sépulcres de mes pères, demeure désolée, et que ses portes ont été consumées par le feu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Et le Roi dit: Que me demandes-tu? Alors je priai le Dieu des cieux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'Et je dis au Roi: Si le Roi le trouve bon, et si ton serviteur t’est agréable, envoie-moi en Judée, vers la ville des sépulcres de mes pères, pour la rebâtir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Et le Roi me dit, et sa femme aussi, qui était assise auprès de lui: Combien serais-tu à faire ton voyage, et quand retournerais-tu? Et après que j’eus déclaré le temps au Roi, il trouva bon de me donner mon congé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Puis je dis au Roi: Si le Roi le trouve bon, qu’on me donne des lettres pour les Gouverneurs de delà le fleuve, afin qu’ils me fassent passer, jusqu’à ce que j’arrive en Judée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'Et des lettres pour Asaph, le garde du parc du Roi, afin qu’il me donne du bois pour la charpenterie des portes de la forteresse qui touche à la maison de Dieu, et pour les portes des murailles de la ville, et pour la maison dans laquelle j’entrerai. Et le Roi me l’accorda, selon que la main de mon Dieu était bonne sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Je vins donc vers les Gouverneurs qui sont de deçà le fleuve, et je leur donnai les paquets du Roi. Or le Roi avait envoyé avec moi des capitaines de guerre et des gens de cheval.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Ce que Samballat, Horonite, et Tobija, serviteur hammonite, ayant appris, ils eurent un fort grand dépit de ce qu’il était venu quelqu’un pour procurer du bien aux enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Ainsi j’arrivai à Jérusalem, et je fus là trois jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Puis je me levai de nuit, moi et quelque peu de gens avec moi; mais je ne déclarai à personne ce que mon Dieu m’avait mis au coeur de faire à Jérusalem; et il n’y avait point d’autre monture avec moi, que celle sur laquelle j’étais monté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Je sortis donc de nuit par la porte de la vallée, et je vins par-devant la fontaine du dragon, à la porte de la fiente; et je considérais les murailles de Jérusalem, comment elles demeuraient renversées, et comment ses portes avaient été consumées par le feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'De là je passai à la porte de la fontaine, et vers l’étang du Roi; et il n’ y avait point de lieu où je pusse passer avec ma monture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Et je montai de nuit par le torrent, et je considérai la muraille; puis en m’en retournant, je rentrai par la porte de la vallée; et ainsi je m’en retournai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Or les magistrats ne savaient point où j’étais allé, ni ce que je faisais; aussi je n’en avais rien déclaré jusques alors, ni aux Juifs, ni aux Sacrificateurs, ni aux principaux, ni aux magistrats, ni au reste de ceux qui maniaient les affaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Alors je leur dis: Vous voyez la misère dans laquelle nous sommes; comment Jérusalem demeure désolée, et ses portes brûlées par le feu. Venez, et rebâtissons les murailles de Jérusalem, et que nous ne soyons plus en opprobre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Et je leur déclarai que la main de mon Dieu était bonne sur moi, et je leur rapportai aussi les paroles que le Roi m’avait dites. Alors ils dirent: Levons-nous, et bâtissons. Ils fortifièrent donc leurs mains pour bien faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Mais Samballat Horonite, et Tobija serviteur hammonite, et Guésem Arabe, l’ayant appris, se moquèrent de nous, et nous méprisèrent, en disant: Qu’est- ce que vous faites? Ne vous rebellez-vous pas contre le Roi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Et je leur répondis ce mot, et leur dis: le Dieu des cieux est celui qui nous fera prospérer; nous donc, qui sommes ses serviteurs, nous nous lèverons et nous bâtirons; mais vous, vous n’avez aucune part, ni droit, ni mémorial, à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Eliasib donc, le grand Sacrificateur se leva, avec ses frères les sacrificateurs, et ils rebâtirent la porte du bercail, laquelle ils sanctifièrent, et ils y posèrent ses portes, et ils la sanctifièrent jusqu’à la tour de Méah, jusqu’à la tour de Hananéël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Et à son côté rebâtirent les gens de Jérico; et à côté d’eux Zaccur, fils d’Imri, rebâtit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Et les enfants de Sénaa rebâtirent la porte des poissons, laquelle ils planchéièrent, et y mirent ses portes, ses serrures et ses barres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Et à leur côté répara Mérémoth, fils d’Urija, fils de Kots; et à leur côté répara Mésullam, fils de Bérecia, fils de Mésézabéël, et à leur côté répara Tsadok, fils de Bahana.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Et à leur côté réparèrent les Tékohites; mais les plus considérables d’entre eux ne se rangèrent point à l’oeuvre de leur Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Et Jéhojadah, fils de Paséah, et Mésullam, fils de Bésodia, réparèrent la porte vieille, laquelle ils planchéièrent, et ils y mirent ses portes, ses serrures et ses barres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Et à leur côté réparèrent Mélatia Gabaonite, et Jadon Méronothite, de Gabaon et de Mitspa, vers le siège du Gouverneur de deçà le fleuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Et à côté de ce siège répara Huziël, fils de Harhaja, d’ entre les orfèvres; et à son côté répara Hanania fils de Harakkahim; et ainsi ils relevèrent Jérusalem jusqu’à la muraille large.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Et à leur côté répara Réphaja, fils de Hur, capitaine d’un demi-quartier de Jérusalem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Et à leur côté répara Jédaja, fils de Harumaph, même à l’endroit de sa maison; et à son côté répara Hattus, fils de Hasabnéja.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Et Malkija, fils de Harim, et Hasub, fils de Pahath-Moab, en réparèrent autant, et même la tour des fours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Et à leur côté Sallum, fils de Lobès, capitaine de l’autre demi-quartier de Jérusalem, répara, lui et ses filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Et Hanun et les habitants de Zanoah réparèrent la porte de la vallée, ils la rebâtirent, et mirent ses portes, ses serrures, et ses barres, et ils bâtirent mille coudées de muraille, jusqu’à la porte de la fiente,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Et Malkija, fils de Réchab, capitaine du quartier de Beth-Kérem, répara la porte de la fiente; il la rebâtit, et mit ses portes, ses serrures et ses barres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Et Sallum, fils de Col-Hoze, capitaine du quartier de Mitspa, répara la porte de la fontaine; il la rebâtit, et la couvrit, et mit ses portes, ses serrures, et ses barres; et il répara aussi la muraille de l’étang de Sélah, tirant vers le jardin du Roi, et jusqu’aux degrés qui descendent de la Cité de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Après lui répara Néhémie, fils d’Hazbuk, capitaine du demi-quartier de Beth- Tsur, jusqu’à l’endroit des sépulcres de David, et jusqu’à l’étang qui avait été refait, et jusqu’à la maison des forts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Après lui réparèrent les Lévites, Néhum, fils de Bani; et à son côté répara Hasabja, capitaine du demi-quartier de Kéhila, pour ceux de son quartier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Après lui réparèrent leurs frères, savoir, Bavvaï, fils de Hénadad, capitaine de l’autre demi-quartier de Kéhila.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Et à son côté Héser, fils de Jésuah, capitaine de Mitspa, en répara autant, à l’endroit par où l’on monte à l’arsenal de l’encoignûre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Après lui Baruch, fils de Zaccaï, prit courage, et en répara autant, depuis l’encoignûre jusqu’à l’entrée de la maison d’Eliasib, grand Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Après lui Mérémoth, fils d’Urija, fils de Kots, en répara autant, depuis l’entrée de la maison d’Eliasib, jusqu’au bout de la maison d’Eliasib.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Et après lui réparèrent les Sacrificateurs, habitants de la campagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Après eux, Benjamin et Hasub réparèrent à l’endroit de leur maison. Après lesquels, Hazaria, fils de Mahaséja, fils d’Hanania, répara auprès de sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Après lui, Binnuï, fils de Henadad, en répara autant, depuis la maison d’Hazaria, jusqu’à l’encoignûre, même jusqu’au coin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Et Palal, fils d’Uzaï, depuis l’endroit de l’encoignûre, et de la tour, qui sort de la haute maison du Roi, qui est auprès du parvis de la prison. Après lui Pédaja, fils de Parhos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'Et les Néthiniens, qui demeuraient en Hophel, réparèrent vers l’Orient, jusqu’à l’endroit de la porte des eaux, et vers la tour qui sort en dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Après eux, les Tékohites en réparèrent autant, depuis l’endroit de la grande tour qui sort en dehors, jusqu’à la muraille d’Hophel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Et les Sacrificateurs réparèrent depuis le dessus de la porte des chevaux, chacun à l’endroit de sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Après eux Tsadok, fils d’Immer, répara à l’endroit de sa maison. Et après lui répara Sémahia, fils de Sécania, garde de la porte Orientale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Après lui Hanania, fils de Sélemia, et Hanun le sixième fils de Tsalaph, en réparèrent autant. Après eux, Mésullam, fils de Bérécia, répara à l’endroit de sa chambre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Après lui Malkija, fils de Tsoreph, répara jusqu’à la maison des Néthiniens, et des revendeurs, et l’endroit de la porte de Miphkad, et jusqu’à la montée du coin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Et les orfèvres et les revendeurs réparèrent entre la montée du coin et la porte du bercail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Or il arriva que Samballat, ayant appris que nous rebâtissions la muraille, fut fort indigné et fort irrité; et il se moqua des Juifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Car il dit en la présence de ses frères, et des gens de guerre de Samarie: Que font ces Juifs languissants? Les laissera-t-on faire? Sacrifieront-ils? et achèveront-ils tout en un jour? Pourront-ils faire revenir les pierres des monceaux de poudre, puisqu’elles sont brûlées?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Et Tobija, Hammonite, qui était auprès de lui, dit: Encore qu’ils bâtissent, si un renard monte, il rompra leur muraille de pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Ô notre Dieu! écoute, comment nous sommes en mépris, et fais retourner leur opprobre sur leur tête, et mets-les en proie dans un pays de captivité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Et ne couvre point leur iniquité, et que leur péché ne soit point effacé devant ta face; car ils ont usé de discours piquants, s’attachant aux bâtisseurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Nous rebâtîmes donc la muraille, et tout le mur fut rejoint jusqu’à sa moitié; car le peuple avait le coeur au travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Mais quand Samballat et Tobija, et les Arabes, les Hammonites, et les Asdodiens eurent appris que la muraille de Jérusalem avait été refaite, et qu’on avait commencé à reclore ce qui avait été rompu, ils furent fort en colère;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Et ils se liguèrent entre eux tous ensemble, pour venir faire la guerre contre Jérusalem, et pour faire échouer son dessein.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Alors nous priâmes notre Dieu, et ayant peur d’eux, nous posâmes des gardes le jour et la nuit contre eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Et Juda dit: La force des ouvriers est affaiblie, et il y a beaucoup de ruines, en sorte que nous ne pourrons pas bâtir la muraille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Or nos ennemis avaient dit: Qu’ils n’en sachent rien, et qu’ils n’en voient rien, jusqu’à ce que nous entrions au milieu d’eux, et que nous les mettions à mort, et fassions cesser l’ouvrage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Mais il arriva que les Juifs qui demeuraient parmi eux, étant venus vers nous, nous dirent par dix fois: Prenez garde à tous les endroits par lesquels vous pourriez vous tourner vers nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'C’est pourquoi je rangeai le peuple depuis le bas, derrière la muraille, sur des lieux élevés, selon leurs familles, avec leurs épées, leurs javelines et leurs arcs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Puis je regardai et me levai; et je dis aux principaux et aux magistrats, et au reste du peuple: N’ayez point peur d’eux; souvenez-vous du Seigneur, qui est grand et terrible, et combattez pour vos frères, pour vos fils et pour vos filles, pour vos femmes et pour vos maisons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Et quand nos ennemis eurent su que nous avions été avertis, Dieu dissipa leur conseil; et nous retournâmes tous aux murailles, chacun à son travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Depuis ce jour-là une moitié de mes gens travaillait, et l’autre moitié tenait des javelines, des boucliers, des arcs et des corselets; et les Gouverneurs suivaient chaque famille de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Ceux qui bâtissaient la muraille, et ceux qui chargeaient les portefaix, travaillaient chacun d’une main, et de l’autre ils tenaient l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'Car chacun de ceux qui bâtissaient était ceint sur ses reins d’une épée, et ils bâtissaient ainsi équipés; et le trompette était près de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Car je dis aux principaux et aux magistrats, et au reste du peuple: L’ouvrage est grand et étendu, et nous sommes écartés sur la muraille loin l’un de l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'En quelque lieu donc que vous entendiez le son de la trompette, courez- y vers nous; notre Dieu combattra pour nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'C’était donc ainsi que nous travaillions; mais la moitié tenait des javelines, depuis le point du jour, jusqu’au lever des étoiles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Et en ce temps-là je dis au peuple: Que chacun avec son serviteur, passe la nuit dans Jérusalem, afin qu’ils nous servent la nuit pour faire le guet, et le jour pour travailler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Et moi, mes frères, mes serviteurs, et les gens de la garde qui me suivent, nous ne quitterons point nos habits: que chacun vienne avec son épée, et avec de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Or il y eut un grand cri du peuple et de leurs femmes, contre les Juifs leurs frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Car il y en avait qui disaient: Que plusieurs d’entre nous engagent leurs fils et leurs filles, pour prendre du froment, afin que nous mangions, et que nous vivions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Et il y en avait d’autres qui disaient: nous engageons nos champs, et nos vignes, et nos maisons, pour prendre du froment contre la famine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Il y en avait aussi qui disaient: nous empruntons de l’argent pour la taille du Roi, sur nos champs et sur nos vignes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Toutefois notre chair est comme la chair de nos frères, et nos fils sont comme leurs fils; et voici, nous assujettissons nos fils et nos filles pour être esclaves; et quelques-unes de nos filles sont déjà assujetties, et ne sont plus en notre pouvoir; et nos champs et nos vignes sont à d’autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Or je fus fort en colère quand j’eus entendu leur cri et ces paroles-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Et je consultai en moi-même; puis je censurai les principaux et les magistrats, et je leur dis: Vous exigez rigoureusement ce que chacun de vous a imposé à son frère; et je fis convoquer contre eux la grande assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Et je leur dis: Nous avons racheté selon notre pouvoir nos frères Juifs, qui avaient été vendus aux nations, et vous vendriez vous-mêmes vos frères, ou nous seraient-ils vendus? Alors ils se turent, et ne surent que dire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Et je dis: Vous ne faites pas bien; ne voulez-vous pas marcher dans la crainte de notre Dieu, plutôt que d’être en opprobre aux nations qui sont nos ennemies?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Nous pourrions aussi exiger de l’argent et du froment, moi, mes frères, et mes serviteurs; mais quittons-leur, je vous prie, cette dette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Rendez-leur, je vous prie, aujourd’hui leurs champs, leurs vignes, leurs oliviers et leurs maisons, et outre cela, le centième de l’argent, du froment, du vin, et de l’huile que vous exigez d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Et ils répondirent: Nous les rendrons, et nous ne leur demanderons rien; nous ferons ce que tu dis; alors j’appelai les Sacrificateurs, et je les fis jurer qu’ils le feraient ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Et je secouai mon sein, et je dis: Que Dieu secoue ainsi de sa maison et de son travail tout homme qui n’aura point mis en effet cette parole, et qu’il soit ainsi secoué et vidé. Et toute l’assemblée répondit: Amen! Et ils louèrent l’Eternel; et le peuple fit selon cette parole-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Et même, depuis le jour auquel le Roi m’avait commandé d’être leur Gouverneur au pays de Juda, qui est depuis la vingtième année jusqu’à la trente-deuxième année du Roi Artaxerxes, l’espace de douze ans, moi et mes frères, nous n’avons point pris ce qui était assigné au Gouverneur pour son plat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Quoique les premiers Gouverneurs qui avaient été avant moi, eussent chargé le peuple, et eussent pris d’eux du pain et du vin, outre quarante sicles d’argent, et qu’aussi leurs serviteurs eussent dominé sur le peuple; mais je n’ai point fait ainsi, à cause de la crainte de mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Et même j’ai réparé une partie de cette muraille, et nous n’avons point acheté de champ, et tous mes serviteurs ont été assemblés là après le travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Et, outre cela, les Juifs et les Magistrats, au nombre de cent cinquante hommes, et ceux qui venaient vers nous des nations qui étaient autour de nous, étaient à ma table.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Et ce qu’on apprêtait chaque jour, était un boeuf, et six moutons choisis. On m’apprêtait aussi des volailles; et de dix en dix jours on me présentait de toute sorte de vin en abondance; et nonobstant tout cela, je n’ai point demandé le plat qui était assigné au Gouverneur; car c’eût été une rude servitude pour ce peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Ô mon Dieu! souviens-toi de moi en bien, selon tout ce que j’ai fait pour ce peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Or il arriva que quand Samballat, Tobija, et Guésem Arabe, et le reste de nos ennemis eurent appris que j’avais rebâti la muraille, et qu’il n’y était demeuré aucune brèche, bien que jusqu’à ce temps-là, je n’eusse pas encore mis les battants aux portes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Samballat et Guésem envoyèrent vers moi, pour me dire: Viens, et que nous nous trouvions ensemble aux villages qui sont à la campagne d’Ono. Or ils avaient comploté de me faire du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Mais j’envoyai des messagers vers eux, pour leur dire: Je fais un grand ouvrage, et je ne saurais descendre. Pourquoi cesserait l’ouvrage, comme cela arriverait lorsque je l’aurais laissé, et que je serais descendu vers vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Et ils me mandèrent la même chose quatre fois; et je leur répondis de même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Alors Samballat envoya vers moi son serviteur, pour me tenir le même discours une cinquième fois; et il avait en sa main une Lettre ouverte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Dans laquelle il était écrit: On entend dire parmi les nations, et Gasmu le dit, que vous pensez, toi et les Juifs, à vous rebeller, et que c’est pour cela que tu rebâtis la muraille, et que tu t’en vas être le Roi, selon ce qu’on en dit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Et même que tu as ordonné des Prophètes pour te louer dans Jérusalem, et pour dire: Il est Roi en Judée. Or, maintenant, on fera entendre au Roi ces mêmes choses; viens donc maintenant afin que nous consultions ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Et je renvoyai vers lui, pour lui dire: Ce que tu dis n’est point, mais tu l’inventes de toi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Car eux tous nous épouvantaient, en disant: Leurs mains quitteront le travail, de sorte qu’il ne se fera point. Maintenant donc, ô Dieu! renforce mes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Outre cela, je vins en la maison de Sémahia, fils de Délaja, fils de Méhétabéel, lequel était retenu. Et il me dit: Assemblons-nous en la maison de Dieu, dans le Temple, et fermons les portes du Temple; car ils doivent venir pour te tuer, et ils viendront de nuit pour te tuer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Mais je répondis: Un homme tel que moi s’enfuirait-il? Et qui sera l’homme tel que je suis, qui entre au Temple, pour sauver sa vie? Je n’y entrerai point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Et voilà, je connus bien que Dieu ne l’avait point envoyé; mais qu’il avait prononcé cette Prophétie contre moi, et que Samballat et Tobija lui donnaient pension,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Car il était leur pensionnaire pour m’épouvanter, et pour m’obliger à agir de la sorte, et à commettre cette faute, afin qu’ils eussent quelque mauvaise chose à me reprocher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Ô mon Dieu! souviens-toi de Tobija et de Samballat, selon leurs actions; et aussi de Nohadia prophétesse, et du reste des prophètes qui tâchaient de m’épouvanter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Néanmoins la muraille fut achevée le vingt-cinquième jour du mois d’Elul, en cinquante-deux jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Quand donc tous nos ennemis l’eurent appris, et que toutes les nations qui étaient autour de nous l’eurent vu, ils en furent tout consternés en eux- mêmes, et ils connurent que cet ouvrage avait été fait par le secours de notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Mais aussi en ces jours-là les principaux de Juda envoyaient Lettres sur Lettres qui allaient à Tobija; et celles de Tobija venaient à eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Car il y en avait plusieurs en Judée qui s’étaient liés à lui par serment, à cause qu’il était gendre de Séchania, fils d’Arah, et que Johanan, son fils avait pris la fille de Mésullam fils de Bérecia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Et même ils racontaient ses bienfaits en ma présence, et lui rapportaient mes discours; et Tobija envoyait des Lettres pour m’épouvanter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Or, après que la muraille fut rebâtie, et que j’eus mis les portes, et qu’on eut fait une revue des chantres et des Lévites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Je commandai à Hanani mon frère, et à Hanania capitaine de la forteresse de Jérusalem; car il était tel qu’un homme fidèle doit être, et il craignait Dieu plus que plusieurs autres;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Et je leur dis: Que les portes de Jérusalem ne s’ouvrent point jusqu’à la chaleur du soleil; et quand ceux qui se tiendront là auront fermé les portes, examinez- les: et qu’on pose des gardes d’entre les habitants de Jérusalem, chacun selon sa garde, et chacun vis-à-vis de sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Or la ville était spacieuse et grande, mais il y avait peu de peuple, et ses maisons n’étaient point bâties.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Et mon Dieu me mit au coeur d’assembler les principaux et les magistrats, et le peuple, pour en faire le dénombrement selon leurs généalogies; et je trouvai le registre du dénombrement selon les généalogies de ceux qui étaient montés la première fois; et j’y trouvai ainsi écrit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Ce sont ici ceux de la Province qui remontèrent de la captivité, d’entre ceux qui avaient été transportés, lesquels Nébuchadnetsar Roi de Babylone avait transportés, et qui retournèrent à Jérusalem et en Judée, chacun en sa ville;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Qui vinrent avec Zorobabel, Jésuah, Néhémie, Hazaria, Rahamia, Nahamani, Mardochée, Bisan, Mitspéreth, Begvaï, Néhum, et Bahana; le nombre, dis-je, des hommes du peuple d’Israël est tel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Les enfants de Parhos, deux mille cent soixante et douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Les enfants de Séphatia, trois cent soixante et douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Les enfants d’Arah, six cent cinquante-deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Les enfants de Pahath-Moab, des enfants de Jésuah et de Joab, deux mille huit cent dix-huit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Les enfants de Hélam, mille deux cent cinquante-quatre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Les enfants de Zattu, huit cent quarante-cinq.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Les enfants de Zaccaï, sept cent soixante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Les enfants de Binnui, six cent quarante-huit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Les enfants de Bébaï, six cent vingt-huit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Les enfants de Hazgad, deux mille trois cent vingt-deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Les enfants d’Adonikam, six cent soixante-sept.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Les enfants de Bigvaï, deux mille soixante-sept.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Les enfants de Hadin, six cent cinquante-cinq.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Les enfants d’Ater, issu d’Ezéchias, quatre-vingt-dix-huit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Les enfants de Hasum, trois cent vingt-huit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Les enfants de Betsaï, trois cent vingt-quatre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Les enfants de Harib, cent douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Les enfants de Gabaon, quatre-vingt-quinze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'Les gens de Bethléhem et de Nétopha, cent quatre-vingt-huit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Les gens d’Hanathoth, cent vingt-huit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'Les gens de Beth-Hazmaveth, quarante-deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'Les gens de Kiriath-Jéharim, de Képhira et de Béeroth, sept cent quarante- trois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'Les gens de Rama et de Guébah, six cent vingt et un.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'Les gens de Micmas, cent vingt-deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'Les gens de Béthel, et de Haï, cent vingt-trois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'Les gens de l’autre Nébo, cinquante-deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'Les enfants d’un autre Hélam, mille deux cent cinquante-quatre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Les enfants de Harim, trois cent vingt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'Les enfants de Jéricho, trois cent quarante-cinq.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'Les enfants de Lod, de Hadid et d’Ono, sept cent vingt et un.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'Les enfants de Sénaa, trois mille neuf cent trente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Des Sacrificateurs: Les enfants de Jédahia, de la maison de Jésuah, neuf cent soixante et treize.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Les enfants d’Immer, mille cinquante-deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Les enfants de Pashur, mille deux cent quarante-sept.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Les enfants de Harim, mille dix-sept.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Des Lévites: Les enfants de Jésuah et de Kadmiel, d’entre les enfants de Hodeva, soixante quatorze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Des chantres: Les enfants d’Asaph, cent quarante-huit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Des portiers: Les enfants de Sallum, les enfants d’Ater, les enfants de Talmon, les enfants d’Hakkub, les enfantsde Hattita, les enfants de Sobaï, cent trente-huit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Des Néthiniens: Les enfants de Tsiha, les enfants de Hasupha, les enfants de Tabbahoth,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Les enfants de Kéros, les enfants de Siha, les enfants de Padon,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'Les enfants de Lebana, les enfants de Hagaba, les enfants de Salmaï,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'Les enfants de Hanan, les enfants de Guiddel, les enfants de Gahar,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'Les enfants de Réaja, les enfants de Retsin, les enfants de Nékoda,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'Les enfants de Gazam, les enfants de Huza, les enfants de Paséah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'Les enfants de Bésaï, les enfants de Méhunim, les enfants de Néphisésim,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'Les enfants de Bakbuk, les enfants de Hakupha, les enfants de Harhur,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'Les enfants de Batslith, les enfants de Méhida, les enfants de Harsa,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'Les enfants de Barkos, les enfants de Sisra, les enfants de Témah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'Les enfants de Netsiah, les enfants de Hatipha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Des enfants des serviteurs de Salomon: Les enfants de Sotaï, les enfants de Sophéreth, les enfants de Périda,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'Les enfants de Jahala, les enfants de Darkon, les enfants de Guiddel,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'Les enfants de Séphatia, les enfants de Hattil, les enfants de Pockereth- Hatsébajim, les enfants d’Amon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Tous les Néthiniens, et les enfants des serviteurs de Salomon, étaient trois cent quatre-vingt-douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Or ce sont ici ceux qui montèrent de Telmelah, de Tel-Harsa, de Kérub, d’Addon et d’Immer, lesquels ne purent montrer la maison de leurs pères, ni leur race, pour savoir s’ils étaient d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Les enfants de Délaja, les enfants de Tobija, les enfants de Nékoda, six cent quarante-deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'Et des Sacrificateurs: Les enfants de Habaja, les enfants de Kots, les enfants de Barzillaï, qui prit pour femme une des filles de Barzillaï Galaadite, et qui fut appelé de leur nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Ils cherchèrent leur registre en recherchant leur généalogie, mais ils n’y furent point trouvés; c’est pourquoi ils furent exclus de la Sacrificature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Et Attirsatha leur dit; qu’ils ne mangeassent point des choses très- saintes, jusqu’à ce que le Sacrificateur assistât avec l’Urim et le Thummim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Toute l’assemblée réunie était de quarante-deux mille trois cent soixante;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'Sans leurs serviteurs et leurs servantes, qui étaient sept mille trois cent trente-sept; et ils avaient deux cent quarante-cinq chantres ou chanteuses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Ils avaient sept cent trente-six chevaux, deux cent quarante-cinq mulets;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Quatre cent trente-cinq chameaux, et six mille sept cent vingt ânes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Or quelques-uns des Chefs des pères contribuèrent pour l’ouvrage. Attirsatha donna au trésor mille drachmes d’or, cinquante bassins, cinq cent trente robes de Sacrificateurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Et quelques autres d’entre les Chefs des pères donnèrent pour le trésor de l’ouvrage, vingt mille drachmes d’or, et deux mille deux cent mines d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Et ce que le reste du peuple donna, fut vingt mille drachmes d’or, et deux mille mines d’argent, et soixante-sept robes de Sacrificateurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'Et ainsi les Sacrificateurs, les Lévites, les portiers, les chantres, quelques-uns du peuple, les Néthiniens, et tous ceux d’Israël habitèrent dans leurs villes; de sorte que quand le septième mois approcha, les enfants d’Israël étaient dans leurs villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Or tout le peuple s’assembla, comme si ce n’eût été qu’un seul homme, en la place qui était devant la porte des eaux; et ils dirent à Esdras le Scribe qu’il apportât le Livre de la Loi de Moïse, laquelle l’Eternel avait ordonnée à Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Et ainsi le premier jour du septième mois Esdras le Sacrificateur apporta la Loi devant l’assemblée, composée d’hommes, et de femmes, et de tous ceux qui étaient capables d’entendre, afin qu’on l’écoutât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Et il lut au Livre, dans la place qui était devant la porte des eaux, depuis l’aube du jour jusqu’à midi, en la présence des hommes, et des femmes, et de ceux qui étaient capables d’entendre; et les oreilles de tout le peuple étaient attentives à la lecture du Livre de la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Ainsi Esdras le Scribe se tint debout sur un lieu éminent bâti de bois, qu’on avait dressé pour cela; et il avait auprès de lui Mattitia, Sémah, Hanaja, Urija, Hilkija et Mahaséja, à sa main droite; et à sa gauche étaient Pédaja, Misaël, Malkija, Hasum, Hasbadduna, Zacharie, et Mésullam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Et Esdras ouvrit le Livre devant tout le peuple; car il était au-dessus de tout le peuple; et sitôt qu’il l’eut ouvert, tout le peuple se tint debout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Puis Esdras bénit l’Eternel, le grand Dieu; et tout le peuple répondit: Amen! Amen! En élevant leurs mains. Puis ils s’inclinèrent et se prosternèrent devant l’Eternel, le visage contre terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Aussi Jésuah, Bani, Sérebja, Jamin, Hakkub, Sabéthaï, Hodija, Mahaséja, Kélita, Hazaria, Jozabad, Hanan, Pelaja, et les autres Lévites, faisaient comprendre la Loi au peuple, le peuple se tenant en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Et ils lisaient au Livre de la Loi de Dieu, ils l’expliquaient, et en donnaient l’intelligence, la faisant comprendre par l’Ecriture même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Or Néhémie, qui est Attirsatha, et Esdras Sacrificateur et Scribe, et les Lévites qui instruisaient le peuple dirent à tout le peuple; ce jour est saint à l’Eternel notre Dieu, ne menez point de deuil, et ne pleurez point; car tout le peuple pleura dès qu’il eut entendu les paroles de la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Puis on leur dit: Allez, mangez du plus gras, et buvez du plus doux; et envoyez-en des portions à ceux qui n’ont rien de prêt; car ce jour est saint à notre Seigneur: ne soyez donc point tristes, puisque la joie de l’Eternel est votre force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Et les Lévites faisaient faire silence parmi tout le peuple, en disant: Faites silence, car ce jour est saint, et ne vous attristez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Ainsi tout le peuple s’en alla pour manger et pour boire, et pour envoyer des présents, et pour faire une grande réjouissance, parce qu’ils avaient bien compris les paroles qu’on leur avait enseignées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Et le second jour du mois, les Chefs des pères de tout le peuple, les Sacrificateurs, et les Lévites, s’assemblèrent vers Esdras le Scribe, pour avoir l’intelligence des paroles de la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Ils trouvèrent donc écrit en la Loi que l’Eternel avait ordonnée par le moyen de Moïse, que les enfants d’Israël demeurassent dans des tabernacles pendant la fête solennelle au septième mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'Ce qu’ils firent savoir et qu’ils publièrent par toutes leurs villes, et à Jérusalem, en disant: Allez sur la montagne, et apportez des rameaux d’oliviers, et des rameaux d’autres arbres huileux, des rameaux de myrte, des rameaux de palmier, et des rameaux de bois branchus, afin de faire des tabernacles, selon ce qui est écrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Le peuple donc alla sur la montagne, et ils apportèrent des rameaux, et se firent des tabernacles, chacun sur son toit, et dans les cours de leurs maisons, et dans les parvis de la maison de Dieu, et à la place de la porte des eaux, et à la place de la porte d’Ephraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Et ainsi toute l’assemblée de ceux qui étaient retournés de la captivité fit des tabernacles, et ils se tinrent dans les tabernacles. Or les enfants d’Israël n’en avaient point fait de tels, depuis les jours de Josué fils de Nun, jusqu’à ce jour-là; et il y eut une fort grande joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Et on lut au Livre de la Loi de Dieu chaque jour, depuis le premier jour jusqu’au dernier. Ainsi on célébra la fête solennelle pendant sept jours, et il y eut une assemblée solennelle au huitième jour, comme il était ordonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Et le vingt-quatrième jour du même mois, les enfants d’Israël s’assemblèrent, jeûnant, revêtus de sacs, et ayant de la terre sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Et la race d’Israël se sépara de tous les étrangers, et ils se présentèrent, confessant leurs péchés et les iniquités de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Ils se levèrent donc en leur place, et on lut au Livre de la Loi de l’Eternel, leur Dieu pendant la quatrième partie du jour, et pendant une autre quatrième partie, ils faisaient confession de leurs péchés, et se prosternaient devant l’Eternel leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Et Jésuah, Bani, Kadmiel, Sébania, Bunni, Sérebia, Bani et Kenani se levèrent sur le lieu qu’on avait élevé pour les Lévites, et crièrent à haute voix à l’Eternel leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Et les Lévites, savoir, Jésuah, Kadmiel, Bani, Hasabnéja, Sérebia, Hodija, Sébania et Péthahia, dirent: Levez-vous, bénissez l’Eternel votre Dieu de siècle en siècle; et qu’on bénisse, ô Dieu! le Nom de ta gloire; et qu’il soit élevé au-dessus de toute bénédiction et louange!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Tu es toi seul l’Eternel, tu as fait les cieux, les cieux des cieux, et toute leur armée; la terre, et tout ce qui y est; les mers, et toutes les choses qui y sont. Tu vivifies toutes ces choses, et l’armée des cieux se prosterne devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Tu es l’Eternel Dieu, qui choisis Abram, et qui le tiras hors d’Ur des Chaldéens, et lui imposas le nom d’Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Tu trouvas son coeur fidèle devant toi, et tu traitas avec lui cette alliance, que tu donnerais le pays des Cananéens, des Héthiens, des Amorrhéens, des Phéréziens, des Jébusiens, et des Guirgasiens, que tu le donnerais à sa postérité; et tu as accompli ce que tu as promis, parce que tu es juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Car tu as regardé l’affliction de nos pères en Egypte, et tu as ouï leur cri près de la mer Rouge;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Et tu as fait des prodiges et des miracles sur Pharaon et sur tous ses serviteurs, et sur tout le peuple de son pays; parce que tu connus qu’ils s’étaient fièrement élevés contre eux, et tu t’es acquis un nom, tel qu’ il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Tu fendis aussi la mer devant eux, et ils passèrent par le sec au travers de la mer; et tu jetas au fond des abîmes ceux qui les poursuivaient, comme une pierre dans les eaux violentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Tu les as même conduits de jour par la colonne de nuée, et de nuit par la colonne de feu, pour les éclairer dans le chemin par où ils devaient aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Tu descendis aussi sur la montagne de Sinaï, tu parlas avec eux des cieux, tu leur donnas des ordonnances droites, et des lois véritables, des statuts et des commandements justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Tu leur enseignas ton saint Sabbat; et tu leur donnas les commandements, les statuts, et la Loi par le moyen de Moïse ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Tu leur donnas aussi des cieux du pain pour leur faim, et tu fis sortir l’eau du rocher pour leur soif, et tu leur dis qu’ils entrassent, et qu’ils possédassent le pays au sujet duquel tu avais levé ta main que tu le leur donnerais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Mais eux et nos pères se sont fièrement élevés et ont roidi leur cou, et n’ont point écouté tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Ils refusèrent d’écouter, et ne se souvinrent point des merveilles que tu avais faites en leur faveur; mais ils roidirent leur cou, et par leur rébellion ils se proposèrent de s’établir un Chef pour retourner à leur servitude. Mais comme tu es un Dieu qui pardonne, miséricordieux, pitoyable, tardif à la colère, et abondant en gratuité, tu ne les abandonnas point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Et quand ils se firent un veau de fonte, et qu’ils dirent: Voici ton Dieu qui t’a fait monter hors d’Egypte, et qu’ils te firent de grands outrages;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'Tu ne les abandonnas pourtant point dans le désert par tes grandes miséricordes; la colonne de nuée ne se retira point de dessus eux de jour, pour les conduire par le chemin, ni la colonne de feu de nuit, pour les éclairer dans le chemin par lequel ils devaient aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Et tu leur donnas ton bon Esprit pour les rendre sages; et tu ne retiras point ta Manne loin de leur bouche, et tu leur donnas de l’eau pour leur soif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Ainsi tu les nourris quarante ans au désert, en sorte que rien ne leur manqua. Leurs vêtements ne s’envieillirent point, et leurs pieds ne furent point foulés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Et tu leur donnas les Royaumes et les peuples, et les leur partageas par contrées; car ils ont possédé le pays de Sihon, savoir le pays du Roi de Hesbon, et le pays de Hog, Roi de Basan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Et tu multiplias leurs enfants comme les étoiles des cieux, et les introduisis au pays duquel tu avais dit à leurs pères, qu’ils y entreraient pour le posséder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Ainsi leurs enfants y entrèrent, et possédèrent le pays; et tu abaissas devant eux les Cananéens, habitants du pays, et les livras entre leurs mains, eux et leurs Rois, et les peuples du pays, afin qu’ils les traitassent selon leur volonté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'De sorte qu’ils prirent les villes fermées et la terre grasse, et possédèrent les maisons pleines de tous biens, les puits qu’on avait creusés, les vignes, les oliviers, et les arbres fruitiers en abondance, desquels ils ont mangé, et ont été rassasiés; ils ont été engraissés, et ils se sont délicieusement traités de tes grands biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Mais ils t’ont irrité, et se sont rebellés contre toi; ils ont jeté ta Loi derrière leur dos, ils ont tué les Prophètes qui les sommaient pour les ramener à toi, et ils t’ont fait de grands outrages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'C’est pourquoi tu les as livrés entre les mains de leurs ennemis, qui les ont affligés; mais au temps de leur angoisse ils ont crié à toi, et tu les as exaucés des cieux, et, selon tes grandes miséricordes tu leur as donné des libérateurs, qui les ont délivrés de la main de leurs ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Mais dès qu’ils avaient du repos ils retournaient à mal faire en ta présence; c’est pourquoi tu les abandonnais entre les mains de leurs ennemis qui dominaient sur eux. Puis ils retournaient et criaient vers toi, et tu les exauçais des cieux. Ainsi tu les as délivrés selon tes miséricordes, plusieurs fois, et en divers temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Et tu les as sommés pour les ramener à ta Loi, mais ils se sont fièrement élevés, et n’ont point obéi à tes commandements; mais ils ont péché contre tes ordonnances, lesquelles si l’homme accomplit, il vivra par elles. Ils ont toujours tiré l’épaule en arrière, et ont roidi leur cou, et n’ont pas écouté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Et tu les as attendus patiemment plusieurs années, et tu les as sommés par ton Esprit par le ministère de tes Prophètes; mais ils ne leur ont point prêté l’oreille; c’est pourquoi tu les as livrés entre les mains des peuples des pays étrangers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Néanmoins par tes grandes miséricordes, tu ne les as point détruits, ni tu ne les as point entièrement abandonnés; car tu es le Dieu Fort, miséricordieux, et pitoyable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Maintenant donc, ô notre Dieu! Le fort, le grand, le puissant et le terrible, gardant l’alliance et la gratuité; Que cette affliction qui nous est arrivée, à nous, à nos Rois, à nos principaux, à nos Sacrificateurs, à nos Prophètes, à nos pères et à tout ton peuple, depuis le temps des Rois d’Assyrie, jusqu’à aujourd’hui, ne soit point réputée petite devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Certainement tu es juste en toutes les choses qui nous sont arrivées; car tu as agi selon la vérité, mais nous, nous avons agi criminellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Ni nos Rois, ni nos principaux, ni nos Sacrificateurs, ni nos pères n’ont point mis en effet ta Loi, et n’ont point été attentifs à tes commandements, ni à tes sommations par lesquelles tu les as sommés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Car ils ne t’ont point servi durant leur règne, ni durant les grands biens que tu leur as faits, même dans le pays spacieux et gras que tu leur avais donné pour être à leur disposition, et ils ne se sont point détournés de leurs mauvaises oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Voici, nous sommes aujourd’hui esclaves, même dans le pays que tu as donné à nos pères pour en manger le fruit et les biens; voici, nous y sommes esclaves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Et il rapporte en abondance pour les Rois que tu as établis sur nous à cause de nos péchés, et qui dominent sur nos corps; et sur nos bêtes, à leur volonté; de sorte que nous sommes dans une grande angoisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'C’est pourquoi, à cause de toutes ces choses nous contractons une ferme alliance, et nous l’écrivons; et les principaux d’entre nous, nos Lévites, et nos Sacrificateurs y apposent leurs seings.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Or ceux qui apposèrent leurs seings, furent, Néhémie, qui est Attirsatha, fils de Hachalia, et Sédécias.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Séraja, Hazaria, Jérémie,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Pashur, Hamaria, Malkija,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hattus, Sébania, Malluc,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Harim, Mérémoth, Hobadia,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Guinnethon, Baruc,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mésullam, Abija, Mijamin,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Mahazia, Bilgaï et Sémahia. Ce furent -là les Sacrificateurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Des Lévites: Jésuah fils d’Azania, Binnui d’entre les enfants de Hénadad, et Kadmiel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'Et leurs frères, Sébania, Hodija, Kélita, Pélaja, Hanan,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Micaï, Réhob, Asabja.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Zaccur, Sérebia, Sébania,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hodija, Bani et Béninu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Des Chefs du peuple, Parhos, Pahath-Moab, Hélam, Zattu, Bani,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Bunni, Hazgad, Bébaï,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adonija, Bigvaï, Hadin,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Ater, Ezéchias, Hazur,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hodija, Hasum, Betsaï,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Hariph, Hanathoth, Nébaï,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpihas, Mésullam, Hézir,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mésézabéel, Tsadok, Jadduah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pélatia, Hanan, Hanaja,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Osée, Hanania, Hasub,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Lohès, Pilha, Sobek,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Réhum, Hasabna, Mahaséja,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Ahija, Hanan, Hunan,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Malluc, Harim et Bahana.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Quant au reste du peuple les Sacrificateurs, les Lévites, les portiers, les chantres, les Néthiniens, et tous ceux qui s’étaient séparés des peuples des pays pour faire la Loi de Dieu, leurs femmes, leurs fils, et leurs filles, tous ceux qui étaient capables de connaissance et d’intelligence,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Adhérèrent entièrement à leurs frères, les plus considérables d’entre eux, et prêtèrent serment avec exécration et jurèrent de marcher dans la Loi de Dieu, qui avait été donnée par le moyen de Moïse serviteur de Dieu, et de garder et de faire tous les commandements de l’Eternel notre Seigneur, ses jugements et ses ordonnances;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'Et de ne donner point de nos filles aux peuples du pays, et de ne prendre point leurs filles pour nos fils;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Et de ne prendre rien le jour du Sabbat, ou tel autre jour sanctifié, des peuples du pays, qui apportent des marchandises, et toutes sortes de denrées le jour du Sabbat, pour les vendre; et d’abandonner la septième année, avec tout le droit d’exiger ce qui est dû.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Nous fîmes aussi des ordonnances, nous chargeant de donner chaque année la troisième partie d’un sicle, pour le service de la maison de notre Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Pour les pains de proposition, pour le gâteau continuel, et pour l’holocauste continuel; et pour ceux des Sabbats, des nouvelles lunes, et des fêtes solennelles; pour les choses saintes, et pour les offrandes pour le péché, afin de réconcilier Israël; enfin, pour tout ce qui se faisait dans la maison de notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Nous jetâmes aussi le sort touchant le bois des oblations, tant les sacrificateurs et les Lévites, que le peuple; afin de l’amener dans la maison de notre Dieu, selon les maisons de nos pères, et dans les temps déterminés, d’année en année, pour brûler sur l’autel de notre Dieu, ainsi qu’il est écrit dans la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Nous ordonnâmes aussi que nous apporterions dans la maison de l’Eternel, d’année en année, les premiers fruits de notre terre, et les prémices de tous les fruits de tous les arbres;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Et que nous rachèterions les premiers-nés de nos fils, et de nos bêtes, comme il est écrit dans la Loi; et que nous amènerions en la maison de notre Dieu, aux Sacrificateurs qui font le service dans la maison de notre Dieu, les premiers-nés de nos boeufs et de notre menu bétail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'Et que nous apporterions les prémices de notre pâte, nos oblations, les fruits de tous les arbres, le vin, et l’huile aux Sacrificateurs, dans les chambres de la maison de notre Dieu, et la dîme de notre terre aux Lévites, et que les Lévites prendraient les dîmes par toutes les villes de notre labourage;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Et qu’il y aurait un Sacrificateur, fils d’Aaron, avec les Lévites pour dîmer les Lévites, et que les Lévites apporteraient la dîme de la dîme en la maison de notre Dieu, dans les chambres, au lieu où étaient les greniers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, '(car les enfants d’Israël? et les enfants de Lévi devaient apporter dans les chambres l’oblation du froment, du vin? et de l’huile; et là étaient les ustensiles du Sanctuaire, et les Sacrificateurs qui font le service, et les portiers, et les chantres) et que nous n’abandonnerions point la maison de notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Et les principaux du peuple s’habituèrent a Jérusalem, mais tout le reste du peuple jeta le sort, afin qu’une des dix parties s’habituât à Jérusalem la sainte Cité, et que les neuf autres parties demeurassent dans les autres villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Et le peuple bénit tous ceux qui se présentèrent volontairement pour s’habituer à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Or ce sont ici les principaux de la province qui s’habituèrent à Jérusalem; les autres s’étant habitués dans les villes de Juda, chacun dans sa possession, selon leurs villes, savoir les Israélites, les Sacrificateurs, les Lévites, les Néthiniens, et les enfants des serviteurs de Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'Ceux de Juda et de Benjamin s’habituèrent donc à Jérusalem; des enfants de Juda Hathaja fils d’Huzija, fils de Zacharie, fils d’Amaria, fils de Séphatia, fils de Mahalaléel, d’entre les enfants de Pharès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'Et Mahaséja fils de Baruc, fils de Colhozé, fils de Hazaja, fils d’Hadaja, fils de Jojarib, fils de Zacharie, fils de Siloni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Tous ceux-là étaient enfants de Pharès, qui s’habituèrent à Jérusalem, quatre cent soixante-huit, vaillants hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Et ceux-ci étaient d’entre les enfants de Benjamin; Sallu, fils de Mésullam, fils de Johed, fils de Pédaja, fils de Kolaja, fils de Mahaséja, fils d’Ithiel, fils d’Esaïe;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'Et après lui Gabbaï, Sallaï, neuf cent vingt-huit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Et Joël fils de Zicri était commis sur eux; et Juda fils de Sénua était Lieutenant de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Des Sacrificateurs: Jéhahia, fils de Jojarib, Jakin,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Séraja, fils de Hilkija, fils de Mésullam, fils de Tsadok, fils de Mérajoth, fils d’Ahitub, Conducteur de la maison de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'Et leurs frères, qui faisaient le service de la maison, huit cent vingt- deux. Et Hodaja fils de Jéroham, fils de Pélalja, fils d Amtsi, fils de Zacharie, fils de Pashur, fils de Malkija.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'Et ses frères, les Chefs des pères, deux cent quarante-deux. Et Hamassaï, fils d’Hazaréel, fils d’Ahzaï, fils de Mésillémoth, fils d’Immer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'Et leurs frères, forts et vaillants, cent vingt-huit; et Zabdiel, fils de Guédolim, était commis sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Et des Lévites: Sémahja, fils de Hasub, fils d’Hazrikam, fils de Hasabia, fils de Bunni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'Et Sabbethaï et Jozabad étaient commis sur le travail de dehors pour la maison de Dieu, étant d’entre les Chefs des Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'Et Mattania, fils de Mica, fils de Zabdi, fils d’Asaph, était le principal des chantres, qui commençait le premier à chanter les louanges dans la prière. Et Bakbukia était le second d’entre ses frères, puis Habda, fils de Sammuah, fils de Galal, fils de Jéduthun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Tous les Lévites qui s’établirent dans la sainte Cité, étaient deux cent quatre-vingt-quatre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Et des portiers, Hakkub, Talmon, et leurs frères qui gardaient les portes, cent soixante et douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Et le reste des Israélites, des Sacrificateurs, et des Lévites fut dans toutes les villes de Juda, chacun en son héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Mais les Néthiniens habitèrent à Hophel; et Tsiha et Guispa étaient commis sur les Néthiniens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Et celui qui avait la charge des Lévites à Jérusalem, était Huzi fils de Bani, fils de Hasabia, fils de Mattania, fils de Mica, d’entre les enfants d’Asaph, chantres, pour l’ouvrage de la maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Car il y avait aussi un commandement du Roi qui les regardait, et il y avait un état assuré pour les chantres chaque jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Et Péthahia, fils de Mésézabéel, d’entre les enfants de Zara, fils de Juda, était commissaire du Roi, dans tout ce qui était à faire envers le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Or quant aux bourgades avec leurs territoires, quelques-uns des enfants de Juda habitèrent à Kiriath-Arbah, et dans les lieux de son ressort; à Dibon, et dans les lieux de son ressort; à Jékabtséel, et dans les lieux de son ressort;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'A Jésuah, à Molada, à Beth-Pélet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'A Hatsar-Sual, à Béer-Sébah, et dans les lieux de son ressort;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'A Tsiklag, à Mécona, et dans les lieux de son ressort;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'A Hen-rimmon, à Tsorah, à Jarmuth,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'A Zanoah, à Hadullam, et dans leurs bourgades; à Lakis, et dans ses territoires; et à Hazeka, et dans les lieux de son ressort. Et ils habitèrent depuis Béer-Sébah jusqu’à la vallée de Hinnom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Et les enfants de Benjamin habitèrent depuis Guébah, à Micmas, Haja, Bethel, et dans les lieux de son ressort;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'A Hanathoth, Nob, Hanania,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hatsor, Rama, Guittajim,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadid, Tsébohim, Néballat,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lod, et Ono, la vallée des manoeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Et quelques-uns des Lévites habitèrent dans leurs partages de Juda et de Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Or ce sont ici les Sacrificateurs et les Lévites qui montèrent avec Zorobabel, fils de Salathiel, et avec Jésuah, savoir: Séraja, Jérémie, Esdras,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amaria, Malluc, Hattus,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sécania, Réhum, Mérémoth,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Hiddo, Guinnethoï, Abija,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijamin, Mahadia, Bilga,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Sémahia, Jojarib, Jédahia,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Hamok, Hilkija, Jédahia. Ce furent là les principaux des Sacrificateurs, et de leurs frères, du temps de Jésuah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Et quant aux Lévites, il y avait Jésuah, Binnui, Kadmiel, Sérebia, Juda, et Mattania, qui était commis sur les louanges, lui et ses frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'Et Bakbukia, et Hunni, leurs frères, étaient vis-à-vis d’eux en leurs charges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Or Jésuah engendra Jojakim, et Jojakim engendra Eliasib, et Eliasib engendra Jojadah,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Et Jojadah engendra Jonathan, et Jonathan engendra Jadduah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Et ceux-ci au temps de Jojakim étaient Sacrificateurs, Chefs des pères; pour Séraja, Méraja; pour Jérémie, Hanania;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Pour Esdras, Mésullam; pour Amaria, Johanan;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Pour Mélicu, Jonathan; pour Sébania, Joseph;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Pour Harim, Hadna; pour Mérajoth, Helkaï;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Pour Hiddo, Zacharie; pour Guinnethon, Mésullam;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Pour Abija, Zicri; pour Minjamin et Mohadia, Piltaï;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Pour Bilga, Sammuah; pour Sémahia, Jonathan;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'Pour Jojarib, Matténaï; pour Jédahia, Huzi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Pour Sallaï, Kallaï; pour Hamok, Héber;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Pour Hilkija, Hasabia; pour Jédahia, Nathanaël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Quant aux Lévites, les chefs de leurs pères, du temps d’Eliasib, Jojadah, Johanan et Jadduah sont enregistrés avec les Sacrificateurs, jusqu’au règne de Darius de Perse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'De sorte que les enfants de Lévi Chefs des pères ont été enregistrés au Livre des Chroniques, jusqu’au temps de Johanan, petit- fils d’Eliasib.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Les Chefs donc des Lévites furent Hasabia, Sérebia, et Jésuah, fils de Kadmiel, et leurs frères étaient vis-à-vis d’eux, pour louer et célébrer le Nom de Dieu, selon le commandement de David, homme de Dieu, un rang correspondant à l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Mattania, Bakbukia et Hobadia, Mésullam, Talmon, et Hakkub avaient la charge des portiers qui faisaient la garde dans les assemblées des portes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Ceux-là furent du temps de Jojakim, fils de Jésuah, fils de Jotsadak, et du temps de Néhémie le Gouverneur, et d’Esdras Sacrificateur et Scribe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Or en la dédicace de la muraille de Jérusalem, on envoya quérir les Lévites de tous leurs lieux, pour les faire venir à Jérusalem, afin qu’on célébrât la dédicace avec joie, par des actions de grâces, et par des cantiques sur des cymbales, des musettes, et des violons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'On assembla donc ceux qui étaient de la race des chantres, tant de la campagne des environs de Jérusalem, que des bourgades des Nétophathiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'Et du lieu de Guilgal, et des territoires de Guébah et d’Hazmaveth; car les chantres s’étaient bâti des bourgades aux environs de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Ainsi les Sacrificateurs et les Lévites se purifièrent, ils purifièrent aussi le peuple, les portes, et la muraille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Puis je fis monter les principaux de Juda sur la muraille, et j’établis deux grandes bandes qui devaient chanter les louanges de Dieu, et le chemin de l’une était à la droite, sur la muraille tendant vers la porte de la fiente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Et après eux marchait Hosahia, avec la moitié des principaux de Juda;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'savoir Hazaria, Esdras, Mésullam,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda, Benjamin, Sémahia et Jérémie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'Et quelques-uns d’entre les enfants des Sacrificateurs avec les trompettes. Puis Zacharie fils de Jonathan, fils de Sémahia, fils de Mattania, fils de Micaja, fils de Zaccur, fils d’Asaph,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'Et ses frères, Sémahia, Hazaréel, Milalaï, Guilalaï, Mahaï, Nathanaël, Juda, et Hanani, avec les instruments des cantiques de David, homme de Dieu; et Esdras le cribe marchait devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Et ils vinrent vers la porte de la fontaine qui était vis-à-vis d’eux, et montèrent aux degrés de la cité de David, par la montée de la muraille, depuis la maison de David, jusqu’à la porte des eaux, vers l’orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Et la seconde bande de ceux qui chantaient les louanges de Dieu, allait à l’opposite, et j’allais après elle, avec l’autre moitié du peuple, allant sur la muraille, par-dessus la tour des fours, jusqu’à la muraille large;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'Et vers la porte d’Ephraïm, et vers la porte vieille, et vers la porte des poissons, vers la tour de Hananéel, et vers la tour de Méah, jusqu’à la porte du bercail, et ils s’arrêtèrent vers la porte de la prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Puis les deux bandes de ceux qui chantaient les louanges de Dieu, s’arrêtèrent dans la maison de Dieu. Je m’arrêtai aussi avec la moitié des magistrats qui étaient avec moi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'Et les Sacrificateurs, Eliakim, Mahaséja, Minjamin, Micaja, Eliohénaï, Zacharie, et Hanania, avec les trompettes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'Et Mahaséja, Sémahia, Elhaza, Huzi, Johanan, Malkija, Hélam et Hézer. Puis les chantres, desquels Jizrahia avait la charge, firent retentir leur voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'On offrit aussi en ce jour-là de grands sacrifices, et on se réjouit, parce que Dieu leur avait donné une grande matière de joie: même les femmes et les enfants se réjouirent; et la joie de Jérusalem fut entendue de loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Et on établit en ce jour-là des hommes sur les chambres des trésors, des oblations, des prémices et des dîmes; pour rassembler du territoire des villes les portions ordonnées par la Loi aux Sacrificateurs et aux Lévites; car Juda fut dans la joie à cause des Sacrificateurs et des Lévites, qui se trouvaient là;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Parce qu’ils avaient gardé la charge qui leur avait été donnée de la part de leur Dieu, et la charge de la purification. On établit aussi des chantres, et des portiers, selon le commandement de David, et de Salomon, son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Car autrefois, du temps de David et d’Asaph, on avait établi des Chefs des chantres, et des cantiques de louange, et d’action de grâces à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'C’est pourquoi tous les Israélites du temps de Zorobabel, et du temps de Néhémie, donnaient les portions des chantres et des portiers, savoir, ce qu’il fallait chaque jour, et les consacraient aux Lévites, et les Lévites les consacraient aux enfants d’Aaron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'En ce temps-là on lut au Livre de Moïse, tout le peuple l’entendant, et on y trouva écrit que les Hammonites et les Moabites ne devaient point entrer à jamais dans l’assemblée de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'Parce qu’ils n’étaient pas venus au-devant des enfants d’Israël, avec du pain et de l’eau; et qu’ils avaient loué Balaam contre eux pour les maudire; mais notre Dieu avait changé la malédiction en bénédiction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'C’est pourquoi il arriva que dès qu’on eut entendu la Loi, on sépara d’Israël tout mélange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Or, avant que ceci arrivât, Eliasib, Sacrificateur ayant été commis sur les chambres de la maison de notre Dieu, s’était allié à Tobija;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'Et lui avait dressé une grande chambre, où auparavant on mettait les gâteaux, l’encens, les ustensiles, et les dîmes du froment, du vin et de l’huile, qui étaient ordonnées pour les Lévites, pour les chantres et pour les portiers, avec ce qui se levait pour les Sacrificateurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Or je n’étais point à Jérusalem pendant tout cela: car la trente-deuxième année d’Artaxerxes, Roi de Babylone, je retournai vers le Roi; et au bout de quelque temps je fus redemandé au Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'Je revins donc à Jérusalem, et alors j’entendis le mal qu’Eliasib avait fait dans ce qui regardait Tobija, lui dressant une chambre dans le parvis de la maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Ce qui me déplut fort; et je jetai tous les meubles de la maison de Tobija hors de la chambre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Et on nettoya les chambres selon que je l’avais commandé, et j’y fis rapporter les ustensiles de la maison de Dieu, les gâteaux et l’encens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'J’entendis aussi que les portions des Lévites ne leur avaient point été données; de sorte que les Lévites, et les chantres qui faisaient le service, s’étaient retirés chacun dans le bien qu’il avait aux champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Et je censurai les magistrats, leur disant: Pourquoi a-t-on abandonné la maison de Dieu? Je les rassemblai donc, et les rétablis en leur place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Et tous ceux de Juda apportèrent les dîmes du froment, du vin et de l’huile, aux greniers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Et j’ordonnai pour receveur sur les greniers, Sélemia Sacrificateur, et Tsadok Scribe; et d’entre les Lévites, Pédaja; et pour leur aider, Hanan fils de Zaccur, fils de Mattania; parce qu’ils passaient pour être très-fidèles; et leur charge était de distribuer ce qu’il fallait à leurs frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Mon Dieu! Souviens-toi de moi touchant ceci; et n’efface point ce que j’ai fait d’une bonne et d’une sincère affection, pour la maison de mon Dieu, et pour ce qu’il est ordonné d’y faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'En ces jours-là je vis quelques-uns en Juda qui foulaient aux pressoirs le jour du Sabbat, et d’autres qui apportaient des gerbes, et qui chargeaient sur les ânes du vin, des raisins, des figues, et toute autre sorte de fardeau, et les apportaient à Jérusalem le jour du Sabbat; et je les sommai le jour qu’ils vendaient les provisions, de ne le plus faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Aussi les Tyriens qui demeuraient à Jérusalem, apportaient du poisson, et plusieurs autres marchandises; et les vendaient aux enfants de Juda dans Jérusalem le jour du Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Je censurai donc les principaux de Juda, et leur dis: Quel mal ne faites- vous pas de violer le jour du Sabbat?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Vos pères n’ont-ils pas fait la même chose, et n’est-ce pas pour cela que notre Dieu a fait venir tout ce mal sur nous et sur cette ville? Et vous augmentez l’ardeur de la colère de l’Eternel contre Israël, en violant le Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'C’est pourquoi dès que le soleil s’était retiré des portes de Jérusalem avant le Sabbat, on fermait les portes, par mon commandement. Je commandai aussi qu’on ne les ouvrît point jusqu’après le Sabbat; et je fis tenir quelques-uns de mes gens sur les portes, afin qu’il n’entrât aucune charge le jour du Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Et les revendeurs, et ceux qui vendaient toute sorte de denrées passèrent la nuit une fois ou deux hors de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Et je les sommai de ne faire plus cela, et je leur dis: Pourquoi passez- vous la nuit devant la muraille? Si vous y retournez, je mettrai la main sur vous. Ainsi, depuis ce temps-là, ils ne vinrent plus le jour du Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Je dis aussi aux Lévites de se purifier, et de venir garder les portes pour sanctifier le jour du Sabbat. Aussi, ô mon Dieu! Souviens-toi de moi touchant ceci, et me pardonne selon la grandeur de ta miséricorde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'En ces jours-là je vis des Juifs qui avaient pris des femmes asdodiennes, hammonites et moabites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'De sorte que leurs enfants parlaient en partie asdodien, et ne savaient point parler Juif; mais ils parlaient la langue de divers peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'C’est pourquoi je les repris, et les blâmai; j’en battis même quelques-uns, et leur arrachai les cheveux, et les fis jurer par le nom de Dieu, qu’ils ne donneraient point leurs filles aux fils des étrangers, et qu’ils ne prendraient point de leurs filles pour leurs fils, ou pour eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Salomon, le Roi d’Israël, n’a-t-il point péché par ce moyen? Quoique entre beaucoup de nations il n’y eût point de Roi semblable à lui, et qu’il fût aimé de son Dieu, et que Dieu l’eût établi pour Roi sur tout Israël: toutefois les femmes étrangères l’ont fait pécher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Vous accorderions-nous donc de faire tout ce grand mal, en commettant ce crime contre notre Dieu, de prendre des femmes étrangères?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Or il y en avait même un d’entre les enfants de Jojadah, fils d’Eliasib, grand Sacrificateur, qui était gendre de Samballat Horonite, lequel je chassai pour cette raison-là d’auprès de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Mon Dieu! Qu’il te souvienne d’eux, à cause qu’ils ont souillé la sacrificature, l’alliance dis-je, de la sacrificature et des Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Ainsi je les nettoyai de tous les étrangers, et je rétablis les charges aux Sacrificateurs et aux Lévites, à chacun selon ce qu’il avait à faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'Et j’ordonnai ce qu’il fallait faire touchant le bois des oblations dans les temps déterminés, et touchant les premiers fruits. Mon Dieu! Souviens-toi de moi en bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Or il arriva au temps d’Assuérus, qui régnait depuis les Indes jusqu’en Ethiopie, sur cent vingt-sept provinces;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'Il arriva, dis-je, en ce temps-là, que le Roi Assuérus étant assis sur le trône de son règne à Susan, la ville capitale;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'La troisième année de son règne, il fit un festin à tous les principaux Seigneurs de ses pays, et à ses serviteurs, de sorte que la puissance de la Perse et de la Médie, savoir les plus grands Seigneurs, et les Gouverneurs des provinces étaient devant lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'Pour montrer les richesses de la gloire de son Royaume, et la splendeur de l’excellence de sa grandeur, durant plusieurs jours; savoir cent quatre-vingts jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Et au bout de ces jours-là, le Roi fît un festin pendant sept jours, dans le parvis du jardin du palais Royal, à tout le peuple qui se trouva dans Susan, la ville capitale, depuis le plus grand jusqu’au plus petit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Les tapisseries de blanc, de vert et de pourpre tenaient avec des cordons de fin lin et d’écarlate à des anneaux d’argent, et à des piliers de marbre; les lits étaient d’or et d’argent sur un pavé de porphyre, de marbre, d’albâtre, et de marbre tacheté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Et on donnait à boire en vaisselle d’or, qui était en diverses façons; et il y avait du vin Royal en abondance, selon l’opulence du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Et la manière de boire fut telle qu’on l’avait ordonné. On ne contraignait personne; car le Roi avait ainsi expressément commandé à tous ses maîtres d’hôtel, de faire selon la volonté de chacun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Et Vasti la Reine fit aussi un festin aux femmes dans la maison Royale, qui était au Roi Assuérus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Or au septième jour, comme le Roi avait le coeur gai de vin, il commanda à Méhuman, Bizta, Harbona, Bigtha, Abagtha, Zéthar, et Carcas, les sept Eunuques qui servaient devant le Roi Assuérus,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'Qu’ils amenassent devant lui la Reine Vasti, portant la couronne Royale, afin de faire voir sa beauté aux peuples et aux Seigneurs; car elle était belle à voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Mais la Reine Vasti refusa de venir au commandement que le Roi lui fit faire par les Eunuques; et le Roi se mit en fort grande colère, et sa colère s’embrasa au dedans de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Alors le Roi dit aux Sages qui avaient la connaissance des temps, (car le Roi communiquait ainsi avec tous ceux qui connaissaient les lois et le droit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'Et alors Carséna, Séthar, Admatha, Tarsis, Mérès, Marséna, et Mémucan, sept Seigneurs de Perse et de Médie, étaient proches de lui, qui voyaient la face du Roi, et ils avaient les premiers sièges dans le Royaume.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Qu’y a-t-il à faire selon les lois à la Reine Vasti, pour n’avoir pas exécuté le commandement que le Roi Assuérus lui a envoyé faire par les Eunuques?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Alors Mémucan parla en présence du Roi et des Seigneurs, disant: La Reine Vasti n’a pas seulement mal agi contre le Roi, mais aussi contre tous les Seigneurs, et contre tous les peuples qui sont dans toutes les provinces du Roi Assuérus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Car l’action de la Reine viendra à la connaissance de toutes les femmes, pour leur faire mépriser leurs maris, quand on dira: Le Roi Assuérus avait commandé qu’on lui amenât la Reine, et elle n’y est pas venue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Et aujourd’hui les Dames de Perse et de Médie qui auront appris la réponse de la Reine, répondront ainsi à tous les Seigneurs des pays du Roi; et comme ce sera une marque de mépris, ce sera aussi un sujet d’emportement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Si le Roi donc le trouve ainsi bon, qu’un Edit Royal soit publié de sa part, et qu’il soit écrit entre les ordonnances de Perse et de la Médie, et qu’il soit irrévocable; savoir que Vasti ne vienne plus devant le Roi Assuérus; et que le Roi donne son Royaume à sa compagne, qui sera meilleure qu’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Et l’Edit, que le Roi aura fait ayant été su par tout son Royaume, quelque grand qu’il soit, toutes les femmes honoreront leurs maris, depuis le plus grand jusqu’au plus petit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Et cette parole plut au Roi et aux Seigneurs; et le Roi fit selon la parole de Mémucan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Il envoya des lettres par toutes les provinces du Roi, à chaque province selon sa manière d’écrire, et à chaque peuple selon sa langue, afin que chacun fût maître en sa maison, et parlant selon la langue de son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Après ces choses, quand la colère du Roi Assuérus fut apaisée, il se souvint de Vasti, et de ce qu’elle avait fait, et de ce qui avait été décrété contr’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Et les jeunes gens qui servaient le Roi, dirent: Qu’on cherche au Roi des jeunes filles vierges, et belles à voir;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Et que le Roi établisse des commissaires dans toutes les provinces de son Royaume, qui assemblent toutes les jeunes filles, vierges et belles à voir, dans Susan, la ville capitale, en l’hôtel des femmes sous la charge d’Hégaï, Eunuque du Roi, le gardien des femmes, qu’on leur donne leurs préparatifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'Et la jeune fille qui plaira au Roi, régnera en la place de Vasti. Et la chose plut au Roi, et il le fit ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Or il y avait à Susan, la ville capitale, un homme Juif, qui avait nom Mardochée, fils de Jaïr, fils de Simhi, fils de Kis, Benjamite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'Lequel avait été transporté de Jérusalem, avec les prisonniers qui avaient été emmenés captifs avec Jéchonias, Roi de Juda, lesquels Nébuchadnetsar, Roi de Babylone, avait transportés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Et il nourrissait Hadassa, qui est Esther, fille de son oncle; car elle n’avait ni père ni mère; et la jeune fille était de belle taille, et très-belle à voir; et après la mort de son père et de sa mère Mardochée l’avait prise pour sa fille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Et quand la parole du Roi et son édit fut su, et que plusieurs jeunes filles eurent été assemblées à Susan la ville capitale, sous la charge d’Hégaï, Esther aussi fut amenée dans la maison du Roi, sous la charge d’Hégaï, gardien des femmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Lequel voyant la jeune fille, elle lui plut, et gagna ses bonnes grâces, de sorte qu’il lui fit aussitôt expédier ses préparatifs, et il lui ordonna son état et sept jeunes filles, telles qu’il les lui fallait ordonner de la maison du Roi, et lui fit changer d’appartement, et la logea, elle et toutes les jeunes filles, dans un des plus beaux appartements de l’hôtel des femmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Or Esther ne déclara point son peuple, ni son parentage, car Mardochée lui avait enjoint de n’en rien déclarer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Et Mardochée se promenait tous les jours devant le parvis de l’hôtel des femmes, pour savoir comment se portait Esther, et ce qu’on ferait d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Or quand le tour de chaque jeune fille était venu pour entrer vers le Roi Assuérus, ayant achevé tout ce qui lui échéait à faire selon ce qui était ordonné touchant les femmes, douze mois durant; (car c’est ainsi que s’accomplissaient les jours de leurs préparatifs, savoir durant six mois, avec de l’huile et de la myrrhe, et durant autres six mois avec des choses aromatiques, et autres préparatifs de femmes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Alors dans cet état la jeune fille entrait vers le Roi;) tout ce qu’elle demandait lui était donné pour aller avec elle depuis l’hôtel des femmes jusqu’à l’hôtel du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Elle y entrait sur le soir, et sur le matin elle retournait dans le second hôtel des femmes sous la charge de Sahasgaz Eunuque du Roi, gardien des concubines; et elle n’entrait plus vers le Roi, si ce n’est que le Roi la voulût, et qu’elle fût appelée nommément.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Quand donc le tour d’Esther fille d’Abihaïl, oncle de Mardochée, laquelle Mardochée avait prise pour sa fille, fut venu pour entrer chez le Roi; elle ne demanda rien sinon ce que dirait Hégaï Eunuque du Roi, gardien des femmes; et Esther gagnait la bonne grâce de tous ceux qui la voyaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Ainsi Esther fut amenée au Roi Assuérus, dans son hôtel Royal, le dixième mois, qui est le mois de Tébeth en la septième année de son règne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Et le Roi aima plus Esther que toutes les autres femmes, et elle gagna ses bonnes grâces et sa bienveillance plus que toutes les vierges; et il mit la couronne du Royaume sur sa tête, et l’établit pour Reine en la place de Vasti.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Alors le Roi fit un grand festin à tous les principaux Seigneurs de ses pays, et à ses serviteurs, savoir le festin d’Esther; et il soulagea les provinces, et fit des présents selon l’opulence royale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Or pendant qu’on assemblait les vierges pour la seconde fois, et que Mardochée était assis à la porte du Roi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Esther ne déclara point son parentage, ni son peuple, selon que Mardochée le lui avait enjoint; car elle exécutait ce que lui disait Mardochée, comme quand elle était nourrie chez lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'En ces jours-là, Mardochée étant assis à la porte du Roi, Bigthan et Térès, deux des Eunuques du Roi d’entre ceux qui gardaient l’entrée, se mutinèrent, et ils cherchaient de mettre la main sur le Roi Assuérus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Ce que Mardochée ayant appris, il le fit savoir à la Reine Esther; puis Esther le redit au Roi de la part de Mardochée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Et on s’enquit de la chose, et on trouva que cela était vrai. Et les Eunuques furent tous deux pendus à un gibet, et cela fut écrit dans le Livre des Chroniques en la présence du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Après ces choses le Roi Assuérus fit de grands honneurs à Haman fils d’Hammédatha Agagien, il l’éleva, et mit son trône au dessus de tous les Seigneurs qui étaient avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Et tous les serviteurs du Roi qui étaient à la porte du Roi s’inclinaient et se prosternaient devant Haman; car le Roi en avait ainsi ordonné. Mais Mardochée ne s’inclinait point, ni ne se prosternait point devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Et les serviteurs du Roi qui étaient à la porte du Roi, disaient à Mardochée: Pourquoi violes-tu le commandement du Roi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Il arriva donc qu’après qu’ils le lui eurent dit plusieurs jours, et qu’il ne les eut point écoutés, ils le rapportèrent à Haman, pour voir si les paroles de Mardochée seraient fermes; parce qu’il leur avait déclaré qu’il était Juif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Et Haman vit que Mardochée ne s’inclinait, ni ne se prosternait point devant lui; et il en fut rempli de colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Or il ne daignait pas mettre la main sur Mardochée seul; mais parce qu’on lui avait rapporté de quelle nation était Mardochée, il cherchait d’exterminer tous les Juifs qui étaient par tout le Royaume d’Assuérus, comme étant la nation de Mardochée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Et au premier mois, qui est le mois de Nisan, la douzième année du Roi Assuérus, on jeta Pur, c’est-à-dire le sort, devant Haman, pour chaque jour, et pour chaque mois, et le sort tomba sur le douzième mois, qui est le mois d’Adar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Et Haman dit au Roi Assuérus: Il y a un certain peuple dispersé entre les peuples, par toutes les provinces de ton Royaume, et qui toutefois se tient à part, duquel les lois sont différentes de celles de tout autre peuple, et ils ne font point les lois du Roi, de sorte qu’il n’est pas expédient au Roi de les laisser ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'S’il plaît donc au Roi, qu’on écrive pour les détruire, et je délivrerai dix mille talents d’argent entre les mains de ceux qui manient les affaires, pour les porter dans les trésors du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Alors le Roi tira son anneau de sa main, et le donna à Haman fils de Hammédatha Agagien, oppresseur des Juifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Outre cela le Roi dit à Haman: Cet argent t’est donné, avec le peuple, pour faire de lui comme il te plaira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Et le treizième jour du premier mois les Secrétaires du Roi furent appelés; et on écrivit selon le commandement d’Haman, aux Satrapes du Roi, aux Gouverneurs de chaque province, et aux principaux de chaque peuple; à chaque province selon sa façon d’écrire, et à chaque peuple selon sa Langue; le tout fut écrit au nom du Roi Assuérus, et cacheté de l’anneau du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Et les lettres furent envoyées par des courriers dans toutes les provinces du Roi, afin qu’on eût à exterminer, à tuer et détruire tous les Juifs, tant les jeunes que les vieux, les petits enfants et les femmes, dans un même jour, qui était le treizième du douzième mois, qui est le mois d’Adar, et à piller leurs dépouilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Les patentes qui furent écrites portaient, que cette ordonnance serait publiée dans chaque province, et qu’elle serait proposée publiquement à tous les peuples, afin qu’on fût prêt pour ce jour-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Ainsi les courriers pressés par le commandement du Roi partirent. L’ordonnance fut aussi publiée dans Susan, la ville capitale. Mais le Roi et Haman étaient assis pour boire, pendant que la ville de Susan était en perplexité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Or quand Mardochée eut appris tout ce qui avait été fait, il déchira ses vêtements, et se couvrit d’un sac et de cendre, et il sortit par la ville, criant d’un cri grand et amer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Et il vint jusqu’au devant de la porte du Roi; (car il n’était point permis d’entrer dans la porte du Roi étant vêtu d’un sac).');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Et en chaque province, dans les lieux où la parole du Roi et son ordonnance parvint, les Juifs furent en grand deuil, jeûnant, pleurant, et se lamentant; et plusieurs se couchaient sur le sac, et sur la cendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Or les demoiselles d’Esther, et ses Eunuques vinrent et lui rapportèrent ces choses, et la Reine fut fort affligée, et elle envoya des vêtements pour en vêtir Mardochée, et afin qu’il ôtât son sac de dessus lui; mais il ne les prit point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Alors Esther appela Hatach l’un des Eunuques du Roi, lequel il avait établi pour la servir, et elle lui donna charge de savoir de Mardochée, ce que c’était, et pourquoi il en usait ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Hatach donc sortit vers Mardochée en la place de la ville, qui était au devant de la porte du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Et Mardochée lui déclara tout ce qui lui était arrivé, et l’offre de l’argent comptant qu’Haman avait promis de délivrer au trésor du Roi, à cause des Juifs, afin qu’on les détruisît.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Et il lui donna une copie de l’ordonnance qui avait été mise par écrit, et qui avait été publiée dans Susan, afin de les exterminer, pour la montrer à Esther, et lui faire entendre le tout, et lui recommander d’entrer chez le Roi pour lui demander grâce, et lui faire requête pour sa nation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Ainsi Hatach revint, et rapporta à Esther les paroles de Mardochée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Et Esther dit à Hatach, et lui commanda de dire à Mardochée:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Tous les serviteurs du Roi, et le peuple des provinces du Roi savent qu’il n’y a ni homme, ni femme qui entre chez le Roi au parvis de dedans, sans y être appelé, et que c’est une de ses lois, de le faire mourir; à moins que le Roi ne lui ait tendu le sceptre d’or, car en ce cas-là il a la vie sauve; or il y a déjà trente jours que je n’ai point été appelée pour entrer chez le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'On rapporta donc les paroles d’Esther à Mardochée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Et Mardochée dit qu’on fit cette réponse à Esther: Ne pense pas en toi-même que toi seule d’entre tous les Juifs échappes dans la maison du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Mais si tu te tais entièrement en ce temps-ci, les Juifs respireront et seront délivrés par quelque autre moyen; mais vous périrez, toi et la maison de ton père. Et qui sait si tu n’es point parvenue au Royaume pour un temps comme celui-ci?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Alors Esther dit qu’on fit cette réponse à Mardochée:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Va, assemble tous les Juifs qui se trouveront à Susan, et jeûnez pour moi, et ne mangez et ne buvez de trois jours, tant la nuit que le jour; et moi et mes demoiselles nous jeûnerons de même; puis je m’en irai ainsi vers le Roi, ce qui n’est point selon la Loi; et s’il arrive que je périsse, que je périsse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Mardochée donc s’en alla, et fit comme Esther lui avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Et il arriva qu’au troisième jour Esther se vêtit d’un habit Royal, et se tint au parvis de dedans du palais du Roi qui était au devant de l’hôtel du Roi, et le Roi était assis sur le trône de son Royaume dans le palais Royal, vis-à-vis de la porte du palais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Or dès que le Roi vit la Reine Esther qui se tenait debout au parvis, elle gagna ses bonnes grâces; de sorte que le Roi tendit à Esther le sceptre d’or qui était en sa main; et Esther s’approcha, et toucha le bout du sceptre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Et le Roi lui dit: Qu’as-tu Reine Esther? et quelle est ta demande? quand ce serait jusqu’à la moitié du Royaume, il te sera donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Et Esther répondit: Si le Roi le trouve bon, que le Roi vienne aujourd’hui avec Haman au festin que je lui ai préparé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Alors le Roi dit: Qu’on fasse venir en diligence Haman, pour accomplir la parole d’Esther. Le Roi donc vint avec Haman au festin qu’Esther avait préparé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Et le Roi dit à Esther au vin de la collation: Quelle est ta demande? et elle te sera octroyée. Et quelle est ta prière? quand tu me demanderais jusqu’à la moitié du Royaume, cela sera fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Alors Esther répondit, et dit: Ma demande, et ma prière est,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Si j’ai trouvé grâce devant le Roi, et si le Roi trouve bon d’accorder ma demande, et d’exaucer ma requête; que le Roi et Haman viennent au festin que je leur préparerai, et je ferai demain selon la parole du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Et Haman sortit en ce jour-là, joyeux et le coeur gai. Mais sitôt qu’il eut vu à la porte du Roi Mardochée, qui ne se leva point, et ne se remua point pour lui, Haman fut rempli de colère contre Mardochée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Toutefois Haman se fit violence, et vint en sa maison; puis il envoya quérir ses amis, et Zérès sa femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Alors Haman leur raconta la gloire de ses richesses, et l’excellence de ses enfants, et toutes les choses dans lesquelles le Roi l’avait agrandi, et comment il l’avait élevé par-dessus les principaux Seigneurs et Serviteurs du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Puis Haman dit: Et même la Reine Esther n’a fait venir que moi avec le Roi au festin qu’elle a fait, et je suis encore demain convié par elle avec le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Mais tout cela ne me sert de rien, pendant tout le temps que je vois Mardochée, ce Juif, séant à la porte du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Alors Zérès sa femme, et tous ses amis lui répondirent: Qu’on fasse un gibet haut de cinquante coudées, et demain au matin dis au Roi qu’on y pende Mardochée; et va-t’en joyeux au festin avec le Roi. Et la chose plut à Haman, et il fit faire le gibet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Cette nuit-là le Roi ne pouvait dormir; et il commanda qu’on lui apportât le Livre des Mémoires, c’est-à-dire les Chroniques; et on les lut devant le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Et il trouva écrit que Mardochée avait donné avis de la conspiration de Bigthana et de Térès, deux des Eunuques du Roi, d’entre ceux qui gardaient l’entrée, lesquels avaient cherché de mettre la main sur le Roi Assuérus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Alors le Roi dit: Quel honneur et quelle distinction a-t-on accordés à Mardochée pour cela? Et les gens du Roi, qui le servaient, répondirent: On n’a rien fait pour lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Et le Roi dit: Qui est au parvis? Or Haman était venu au parvis du palais du Roi, pour dire au Roi qu’il fît pendre Mardochée au gibet qu’il lui avait fait préparer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Et les gens du Roi lui répondirent: Voilà Haman qui est au parvis; et le Roi dit: Qu’il entre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Haman donc entra, et le Roi lui dit: Que faudrait-il faire à un homme que le Roi prend plaisir d’honorer? (Or Haman dit en son coeur: A qui le Roi voudrait-il faire plus d’honneur qu’à moi?)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Et Haman répondit au Roi: Quant à l’homme que le Roi prend plaisir d’honorer,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'Qu’on lui apporte le vêtement Royal, dont le Roi se vêt, et qu’on lui amène le cheval que le Roi monte, et qu’on lui mette la couronne Royale sur la tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Et qu’ensuite on donne ce vêtement et ce cheval à quelqu’un des principaux et des plus grands Seigneurs qui sont auprès du Roi, et qu’on revête l’homme que le Roi prend plaisir d’honorer, et qu’on le fasse aller à cheval par les rues de la ville; et qu’on crie devant lui: C’est ainsi qu’on doit faire à l’homme que le Roi prend plaisir d’honorer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Alors le Roi dit à Haman: Hâte-toi, prends le vêtement, et le cheval, comme tu l’as dit, et fais ainsi à Mardochée le Juif qui est assis à la porte du Roi; n’omets rien de tout ce que tu as dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Haman donc prit le vêtement et le cheval, et vêtit Mardochée, et il le fit aller à cheval par les rues de la ville, et il criait devant lui: C’est ainsi qu’on doit faire à l’homme que le Roi prend plaisir d’honorer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Puis Mardochée s’en retourna à la porte du Roi; mais Haman se retira promptement en sa maison, tout affligé, et ayant la tête couverte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Et Haman raconta à Zérès sa femme, et à tous ses amis, tout ce qui lui était arrivé. Alors ses sages et Zérès sa femme lui répondirent: Si Mardochée (devant lequel tu as commencé de tomber) est de la race des Juifs, tu n’auras point le dessus sur lui, mais certainement tu tomberas devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Et comme ils parlaient encore avec lui, les Eunuques du Roi vinrent, et se hâtèrent d’amener Haman au festin qu’Esther avait préparé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Le Roi donc et Haman vinrent au festin avec la Reine Esther.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Et le Roi dit à Esther encore ce second jour, au vin de la collation: Quelle est ta demande, Reine Esther? et elle te sera octroyée; et quelle est ta prière? fût-ce jusqu’à la moitié du Royaume, cela sera fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Alors la Reine Esther répondit, et dit: Si j’ai trouvé grâce devant toi, ô Roi! et si le Roi le trouve bon, que ma vie me soit donnée à ma demande, et que mon peuple me soit donné à ma prière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Car nous avons été vendus, moi et mon peuple, pour être exterminés, tués et détruits. Que si nous avions été vendus pour être serviteurs et servantes, je me fusse tue; bien que l’oppresseur ne récompenserait point le dommage que le Roi en recevrait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Et le Roi Assuérus parla et dit à la Reine Esther: Qui est et où est cet homme, qui a été si téméraire que de faire cela?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Et Esther répondit: l’oppresseur et l’ennemi est ce méchant Haman ici. Alors Haman fut troublé de la présence du Roi et de la Reine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Et le Roi en colère se leva du vin de la collation, et il entra dans le jardin du palais; mais Haman resta, afin de prier pour sa vie la Reine Esther; car il voyait bien que le Roi était résolu de le perdre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Puis le Roi retourna du jardin du palais au lieu où l’on avait présenté le vin de la collation; (or Haman s’était jeté sur le lit où était Esther) et le Roi dit: Forcerait-il bien encore sous mes yeux la Reine en cette maison? Dès que la parole fut sortie de la bouche du Roi, aussitôt on couvrit le visage d’Haman.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Et Harbona l’un des Eunuques dit en la présence du Roi: Voilà même le gibet qu’Haman a fait faire pour Mardochée, qui donna ce bon avis pour le Roi, est tout dressé dans la maison d’Haman, haut de cinquante coudées; et le Roi dit: Pendez-l’y.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Et ils pendirent Haman au gibet qu’il avait préparé pour Mardochée; et la colère du Roi fut apaisée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Ce même jour-là le Roi Assuérus donna à la Reine Esther la maison d’Haman l’oppresseur des Juifs. Et Mardochée se présenta devant le Roi; car Esther avait déclaré ce qu’il lui était.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Et le Roi prit son anneau qu’il avait fait ôter à Haman, et le donna à Mardochée; et Esther établit Mardochée sur la maison d’Haman.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Et Esther continua de parler en la présence du Roi, et se jetant à ses pieds elle pleura, et elle le supplia de faire que la malice d’Haman Agagien, et ce qu’il avait machiné contre les Juifs, n’eût point d’effet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Et le Roi tendit le sceptre d’or à Esther. Alors Esther se leva, et se tint debout devant le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Et elle dit: Si le Roi le trouve bon, et si j’ai trouvé grâce devant lui, et si la chose semble raisonnable au Roi, et si je lui suis agréable, qu’on écrive pour révoquer les Lettres qui regardaient la machination d’Haman fils d’Hammédatha Agagien, qu’il avait écrites pour détruire les Juifs qui sont dans toutes les provinces du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Car comment pourrais-je voir le mal qui arriverait à mon peuple, et comment pourrais-je voir la destruction de ma parenté?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Et le Roi Assuérus dit à la Reine Esther et à Mardochée Juif: Voilà, j’ai donné la maison d’Haman à Esther, et on l’a pendu au gibet, parce qu’il avait étendu sa main sur les Juifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Vous donc écrivez au nom du Roi en faveur des Juifs, comme il vous plaira, et cachetez l’écrit de l’anneau du Roi; car l’écriture, qui est écrite au nom du Roi, et cachetée de l’anneau du Roi, ne se révoque point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Et en ce même temps, le vingt-troisième jour du troisième mois qui est le mois de Sivan, les Secrétaires du Roi furent appelés, et on écrivit aux Juifs, comme Mardochée le commanda; et aux Satrapes, et aux Gouverneurs, et aux principaux des provinces, qui étaient depuis les Indes jusqu’en Ethiopie, savoir cent vingt-sept provinces, à chaque province selon sa façon d’écrire, et à chaque peuple selon sa Langue, et aux Juifs selon leur façon d’écrire, et selon leur Langue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'On écrivit donc des Lettres au nom du Roi Assuérus, et on les cacheta de l’anneau du Roi; puis on les envoya par des courriers, montés sur des chevaux, des dromadaires et des mulets;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Savoir que le Roi avait octroyé aux Juifs qui étaient dans chaque ville de s’assembler, et de se mettre en défense pour leur vie, afin d’exterminer, de tuer, et de détruire toute assemblée de gens, de quelque peuple et de quelque province que ce soit, qui se trouveraient en armes pour opprimer les Juifs, de les exterminer eux et leurs petits enfants, et leurs femmes, et de piller leurs dépouilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'Dans un même jour dans toutes les provinces du Roi Assuérus; savoir, le treizième jour du douzième mois, qui est le mois d’Adar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Les patentes qui furent écrites portaient, que cette ordonnance serait publiée dans chaque province, et proposée publiquement à tous les peuples, afin que les Juifs fussent prêts en ce jour-là pour se venger de leurs ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Ainsi les courriers, montés sur des chevaux et des mulets, partirent, se dépêchant et se hâtant pour la parole du Roi; l’ordonnance fut aussi publiée dans Susan, la ville capitale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Et Mardochée sortait de devant le Roi en vêtement Royal de couleur de pourpre et de blanc, avec une grande couronne d’or, et une robe de fin lin, et d’écarlate; et la ville de Susan jetait des cris de réjouissance, et elle fut dans la joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Et il y eut pour les Juifs de la prospérité, de la joie, de la réjouissance, et de l’honneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Et dans chaque province, et dans chaque ville, dans les lieux où la parole du Roi et son ordonnance était parvenue, il y eut de l’allégresse, et de la joie pour les Juifs, des festins, et des jours de fête; et même plusieurs d’entre les peuples des pays se faisaient Juifs, parce que la frayeur des Juifs les avait saisis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Le douzième mois donc, qui est le mois d’Adar, le treizième jour de ce mois, auquel la parole du Roi et son ordonnance devait être exécutée, au jour que les ennemis des Juifs espéraient en être les maîtres, au lieu que le contraire devait arriver, savoir que les Juifs seraient maîtres de ceux qui les haïssaient;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Les Juifs s’assemblèrent dans leurs villes, par toutes les provinces du Roi Assuérus, pour mettre la main sur ceux qui cherchaient leur perte; mais nul ne put tenir ferme devant eux, parce que la frayeur qu’on avait d’eux avait saisi tous les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Et tous les principaux des provinces, et les Satrapes, et les Gouverneurs, et ceux qui maniaient les affaires du Roi, soutenaient les Juifs, parce que la frayeur qu’on avait de Mardochée les avait saisis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Car Mardochée était grand dans la maison du Roi, et sa réputation allait par toutes les provinces; parce que cet homme Mardochée allait en croissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Les Juifs donc frappèrent tous leurs ennemis à coups d’épée, et en firent un grand carnage, de sorte qu’ils traitèrent selon leurs désirs ceux qui les haïssaient,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Et même dans Susan, la ville capitale, les Juifs tuèrent et firent périr cinq cents hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Ils tuèrent aussi Parsandata, Dalphon, Aspatha,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Poratha, Adalia, Aridatha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Parmastha, Arisaï, Aridaï, et Vajezatha;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'Dix fils d’Haman fils d’Hammédatha, l’oppresseur des Juifs; mais ils ne mirent point leurs mains au pillage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Et ce jour-là on rapporta au Roi le nombre de ceux qui avaient été tués dans Susan, la ville capitale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Et le Roi dit à la Reine Esther: Dans Susan la ville capitale, les Juifs ont tué et détruit cinq cents hommes, et les dix fils d’Haman, qu’auront-ils fait au reste des provinces du Roi? Toutefois quelle est ta demande? et elle te sera octroyée; et quelle est encore ta prière? et cela sera fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Et Esther répondit: Si le Roi le trouve bon qu’il soit permis encore demain aux Juifs, qui sont à Susan, de faire selon ce qu’il avait été ordonné de faire aujourd’hui, et qu’on pende au gibet les dix fils d’Haman.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Et le Roi commanda que cela fût ainsi fait; de sorte que l’ordonnance fut publiée dans Susan, et on pendit les dix fils d’Haman.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Les Juifs donc qui étaient dans Susan, s’assemblèrent encore le quatorzième jour du mois d’Adar, et tuèrent dans Susan trois cents hommes; mais ils ne mirent point leurs mains au pillage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Et le reste des Juifs qui étaient dans les provinces du Roi, s’assemblèrent, et se mirent en défense pour leur vie, et ils eurent du repos de leurs ennemis, et tuèrent soixante et quinze mille hommes de ceux qui les haïssaient; mais ils ne mirent point leurs mains au pillage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Cela se fit le treizième jour du mois d’Adar, mais le quatorzième du même mois ils se reposèrent, et ils le célébrèrent comme un jour de festin et de joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Et les Juifs qui étaient dans Susan, s’assemblèrent le treizième et le quatorzième jour du même mois, mais ils se reposèrent le quinzième, et le célébrèrent comme un jour de festin et de joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'C’est pourquoi les Juifs des bourgs, qui habitent dans des villes non murées, emploient le quatorzième jour du mois d’Adar, en réjouissance, en festins, en jour de fête, et à envoyer des présents l’un à l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Car Mardochée écrivit ces choses, et en envoya les Lettres à tous les Juifs qui étaient dans toutes les provinces du Roi Assuérus, tant près que loin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'Leur ordonnant qu’ils célébrassent le quatorzième jour du mois d’Adar, et le quinzième jour du même mois chaque année.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'Selon les jours auxquels les Juifs avaient eu du repos de leurs ennemis, et selon le mois où leur angoisse fut changée en joie, et leur deuil en jour de fête, afin qu’ils les célébrassent comme des jours de festin et de joie, et en envoyant des présents l’un à l’autre, et des dons aux pauvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Et chacun des Juifs se soumit à faire ce qu’on avait commencé, et ce que Mardochée leur avait écrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Parce qu’Haman fils d’Hammédatha Agagien, l’oppresseur de tous les Juifs, avait machiné contre les Juifs de les détruire, et qu’il avait jeté Pur, c’est-à-dire le sort, pour les défaire, et pour les détruire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Mais quand Esther fut venue devant le Roi, il commanda par Lettres que la méchante machination qu’ Haman avait faite contre les Juifs, retombât sur sa tête, et qu’on le pendît, lui et ses fils, au gibet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'C’est pourquoi on appelle ces jours-là Purim, du nom de Pur. Et suivant toutes les paroles de cette dépêche, et selon ce qu ils avaient vu sur cela, et ce qui leur était arrivé,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Les Juifs établirent et se soumirent, eux et leur postérité, et tous ceux qui se joindraient à eux, à ne manquer point de célébrer selon ce qui en avait été écrit, ces deux jours dans leur saison chaque année.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'Et ils ordonnèrent que la mémoire de ces jours serait célébrée et solennisée dans chaque âge, dans chaque famille, dans chaque province et dans chaque ville; et qu’on n’abolirait point ces jours de Purim entre les Juifs, et que la mémoire de ces jours-là ne s’effacerait point en leur postérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'La Reine Esther aussi, fille d’Abihaïl, avec Mardochée Juif écrivit tout ce qui était requis pour autoriser cette patente de Purim, pour la seconde fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Et on envoya des Lettres à tous les Juifs, dans les cent vingt- sept provinces du Royaume d’Assuérus, avec des paroles de paix et de vérité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'Pour établir ces jours de Purim dans leur saison, comme Mardochée Juif, et la Reine Esther l’avaient établi; et comme ils les avaient établis pour eux-mêmes, et pour leur postérité, pour être des monuments de leurs jeûnes, et de leur cri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Ainsi l’édit d’Esther autorisa cet arrêt-là de Purim; comme il est écrit dans ce Livre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Puis le Roi Assuérus imposa un tribut sur le pays, et sur les Iles de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Or quant à tous les exploits de sa force et de sa puissance, et quant à la description de la magnificence de Mardochée, de laquelle le Roi l’honora, ces choses ne sont-elles pas écrites dans le Livre des Chroniques des Rois de Médie et de Perse?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Car Mardochée le Juif fut le second après le Roi Assuérus, et il fut grand parmi les Juifs, et agréable à la multitude de ses frères, procurant le bien de son peuple, et parlant pour la prospérité de toute sa race.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Il y avait dans le pays d’Uts, un homme dont le nom était Job; cet homme était intègre, droit, craignant Dieu et se détournant du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Et il lui naquit sept fils et trois filles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Et il possédait sept mille brebis, trois mille chameaux, cinq cents paires de bœufs, cinq cents ânesses, et un très grand nombre de serviteurs, et cet homme était le plus grand des enfants de l’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Et ses fils allaient les uns chez les autres et se donnaient un repas chacun à leur jour, et ils envoyaient convier leurs trois sœurs à manger et à boire avec eux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Et quand le cercle des jours de festin était achevé, Job envoyait chercher ses fils pour les purifier, et se levant de bon matin, il offrait un holocauste pour chacun d’eux; car Job disait: Peut-être mes fils ont-ils péché, et ont-ils renié Dieu dans leurs cœurs. Ainsi faisait Job toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Or, il arriva un jour que les fils de Dieu étant venus se présenter devant l’Éternel, Satan vint aussi au milieu d’eux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Et l’Éternel dit à Satan: D’où viens-tu? Et Satan répondit à l’Éternel, et dit: De courir çà et là sur la terre et de m’y promener.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Et l’Éternel dit à Satan: As-tu remarqué mon serviteur Job? Il n’y en a pas comme lui sur la terre, intègre, droit, craignant Dieu, et se détournant du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Et Satan répondit à l’Éternel, et dit: Est-ce pour rien que Job craint Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'N’as-tu pas fait comme une haie de tous côtés autour de lui, autour de sa maison, autour de tout ce qui lui appartient? Tu as béni l’œuvre de ses mains, et ses troupeaux se répandent sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Mais étends ta main, touche à tout ce qui lui appartient; et tu verras s’il ne te renie pas en face!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Et l’Éternel dit à Satan: Voici, tout ce qui lui appartient est dans ta main; seulement ne porte pas la main sur lui. Et Satan sortit de devant la face de l’Éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Il arriva donc qu’un jour, comme ses fils et ses filles mangeaient et buvaient du vin dans la maison de leur frère aîné, un messager vint vers Job,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'Et lui dit: Les bœufs labouraient, et les ânesses paissaient à côté d’eux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'Et ceux de Shéba se sont jetés dessus, et les ont pris, et ont passé les serviteurs au fil de l’épée; et je me suis échappé, moi seul, pour te l’annoncer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Cet homme parlait encore, lorsqu’un autre vint et dit: Le feu de Dieu est tombé du ciel, et il a brûlé les brebis et les serviteurs, et les a consumés; et je me suis échappé, moi seul, pour te l’annoncer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Cet homme parlait encore, lorsqu’un autre vint et dit: Des Caldéens ont fait trois bandes, et ont fondu sur les chameaux et les ont pris; et ils ont passé les serviteurs au fil de l’épée; et je me suis échappé, moi seul, pour te l’annoncer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Cet homme parlait encore, lorsqu’un autre vint et dit: Tes fils et tes filles mangeaient et buvaient du vin dans la maison de leur frère aîné;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'Et voici, un grand vent est venu de l’autre côté du désert, et a donné contre les quatre coins de la maison, et elle est tombée sur les jeunes gens, et ils sont morts; et je me suis échappé, moi seul, pour te l’annoncer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Alors Job se leva, et il déchira son manteau, et il rasa sa tête; et il se jeta par terre, et il se prosterna,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'Et il dit: Nu je suis sorti du ventre de ma mère, et nu j’y retournerai; l’Éternel a donné, l’Éternel a ôté, que le nom de l’Éternel soit béni!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'En tout cela, Job ne pécha point, et n’attribua rien de mauvais à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Or, il arriva un jour que les fils de Dieu étant venus se présenter devant l’Éternel, Satan vint aussi au milieu d’eux, se présenter devant l’Éternel,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Et l’Éternel dit à Satan: D’où viens-tu? Et Satan répondit à l’Éternel, et dit: De courir çà et là sur la terre et de m’y promener.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Et l’Éternel dit à Satan: As-tu remarqué mon serviteur Job? Il n’y en a pas comme lui sur la terre, intègre, droit, craignant Dieu, et se détournant du mal. Il tient encore ferme dans son intégrité, et tu m’as excité à le ruiner sans motif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Et Satan répondit à l’Éternel et dit: Peau pour peau! Tout ce que l’homme possède, il le donne pour sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Mais étends ta main, et touche à ses os et à sa chair; et tu verras s’il ne te renie pas en face!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Et l’Éternel dit à Satan: Voici, il est en ta main; seulement respecte sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Et Satan sortit de devant la face de l’Éternel; et il frappa Job d’un ulcère malin, depuis la plante des pieds jusqu’au sommet de la tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Et Job prit un tesson pour se gratter, et il était assis dans la cendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Et sa femme lui dit: Tu tiens ferme encore dans ton intégrité! Renie Dieu, et meurs!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Et il lui dit: Tu parles comme une femme insensée! Nous recevons le bien de la part de Dieu, et nous ne recevrions pas le mal! En tout cela, Job ne pécha point par ses lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Et trois amis de Job, Éliphaz, de Théman, Bildad, de Shuach, Tsophar, de Naama, ayant appris tous les maux qui lui étaient arrivés, partirent chacun de leur pays, et convinrent ensemble d’un jour pour venir lui faire leurs condoléances et le consoler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Et, ayant de loin levé les yeux, ils ne le reconnurent pas; alors ils élevèrent la voix et ils pleurèrent; et ils déchirèrent leur manteau, et ils jetèrent de la poussière vers le ciel, au-dessus de leur tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Puis ils restèrent assis à terre avec lui, sept jours et sept nuits, et aucun d’eux ne lui dit une parole, car ils voyaient que sa douleur était fort grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Après cela, Job ouvrit la bouche et maudit le jour de sa naissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Et, prenant la parole, Job dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Périsse le jour où je suis né, et la nuit qui a dit: Un homme est conçu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Que ce jour soit ténèbres, que Dieu ne s’en enquière pas d’en haut, qu’aucune lumière ne brille sur lui!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Que les ténèbres et l’ombre de la mort le reprennent, qu’une sombre nuée demeure sur lui, qu’une éclipse le remplisse d’horreur!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Que l’obscurité s’empare de cette nuit, qu’elle ne se réjouisse pas au milieu des jours de l’année, qu’elle n’entre pas dans le compte des mois!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Voici, que cette nuit soit stérile, et qu’aucun cri de joie n’y survienne!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Qu’ils la maudissent ceux qui maudissent les jours, ceux qui sont habiles à faire lever Léviathan!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Que les étoiles de son crépuscule soient obscurcies, qu’elle attende la lumière et qu’il n’y en ait point, et qu’elle ne voie pas les paupières de l’aurore!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Parce qu’elle n’a pas fermé le sein qui me porta, et n’a point caché la douleur à mes yeux!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Que ne suis-je mort dès le sein de ma mère? Au sortir de ses flancs, que n’ai-je expiré?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Pourquoi des genoux se sont-ils présentés à moi, et pourquoi des mamelles pour être sucées?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Car, maintenant, je serais couché et tranquille, je dormirais, je serais en repos,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'Avec les rois et les arbitres de la terre, qui se bâtissent des mausolées,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'Avec les princes qui ont de l’or, qui remplissent d’argent leurs maisons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Ou bien, comme l’avorton caché, je n’existerais pas; comme les petits enfants qui n’ont pas vu la lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Là, les méchants ne tourmentent plus personne, et là se reposent les hommes fatigués;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'Avec eux, les captifs sont tranquilles: ils n’entendent plus la voix de l’exacteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Là, le petit et le grand sont ensemble, et l’esclave est délivré de son maître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Pourquoi donne-t-on la lumière au malheureux, et la vie à ceux dont l’âme est pleine d’amertume?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'Qui attendent la mort, et elle ne vient point, qui la recherchent plus qu’un trésor,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'Qui seraient contents jusqu’à l’allégresse et ravis de joie, s’ils trouvaient le tombeau?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'A l’homme qui ne connaît pas sa voie et que Dieu cerne de tous côtés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Car je soupire au lieu de manger, et mes cris se répandent comme l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Ce que je crains m’arrive, et ce que j’appréhende vient sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Je n’ai ni paix, ni tranquillité, ni repos! Le tourment est venu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Alors Éliphaz, de Théman, prit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Si l’on tente de te parler, te fâcheras-tu? Mais qui pourrait retenir ses paroles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Voici, tu as souvent instruit les autres, et tu as fortifié les mains affaiblies;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Tes paroles ont relevé ceux qui chancelaient, et tu as raffermi les genoux qui pliaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Et maintenant que le malheur t’arrive, tu te fâches; et parce qu’il t’a atteint, tu es tout éperdu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Ta piété ne fait-elle pas ta confiance? Ton espérance, n’est-ce pas l’intégrité de tes voies?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Cherche dans ta mémoire; quel est l’innocent qui a péri, et où des justes ont-ils été exterminés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Pour moi, j’ai vu que ceux qui labourent l’iniquité et qui sèment la peine, la moissonnent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Ils périssent par le souffle de Dieu, et ils sont consumés par le vent de sa colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Le rugissement du lion, le cri du grand lion cesse, et les dents du lionceau sont anéanties;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Le lion périt faute de proie, et les petits de la lionne sont dispersés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Une parole m’est furtivement arrivée, et mon oreille en a saisi le murmure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Au milieu de mes pensées, pendant les visions de la nuit, quand un profond sommeil tombe sur les humains,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Une frayeur et un tremblement me saisirent, et effrayèrent tous mes os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Un esprit passa devant moi, et fit hérisser le poil de ma chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Il se tint là et je ne reconnus pas son visage; une figure était devant mes yeux. Il y eut un silence; et j’entendis une voix:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, '\"L’homme sera-t-il juste devant Dieu? L’homme sera-t-il pur devant celui qui l’a fait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Voici, il ne se fie pas à ses serviteurs, il trouve des défauts à ses anges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'Combien plus chez ceux qui habitent des maisons d’argile, qui ont leurs fondements dans la poussière, qu’on écrase comme des vermisseaux!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Ils sont détruits du matin au soir; sans qu’on y prenne garde, ils périssent pour toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'La corde de leur tente est coupée, ils meurent, sans avoir été sages. \"');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Crie maintenant! Y aura-t-il quelqu’un qui te réponde? Et vers lequel des saints te tourneras-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'La colère tue l’insensé, et le dépit fait mourir celui qui est destitué de sens;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'J’ai vu l’insensé étendant ses racines, mais soudain j’ai maudit sa demeure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Ses fils sont loin de tout secours, ils sont écrasés à la porte, et personne ne les délivre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'L’affamé dévore sa moisson; il la lui prend à travers les épines de sa haie; l’homme altéré convoite ses biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Car la souffrance ne sort pas de la poussière, et la peine ne germe pas du sol,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'De sorte que l’homme soit né pour la peine, comme l’étincelle pour voler en haut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Mais moi, j’aurais recours à Dieu, et j’adresserais ma parole à Dieu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Qui fait de grandes choses qu’on ne peut sonder, de merveilleuses choses qu’on ne peut compter;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Qui répand la pluie sur la face de la terre, et qui envoie les eaux sur la face des champs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Qui met en haut ceux qui sont abaissés, et ceux qui sont en deuil au faîte du bonheur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Qui dissipe les projets des hommes rusés, et leurs mains ne viennent à bout de rien;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Qui prend les sages dans leurs propres ruses, et le dessein des pervers est renversé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'De jour, ils rencontrent les ténèbres, et, comme dans la nuit, ils tâtonnent en plein midi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Et il délivre le pauvre de l’épée de leur bouche, et de la main des puissants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Et il y a une espérance pour les malheureux, et la méchanceté a la bouche fermée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Voici, heureux l’homme que Dieu châtie! Ne méprise donc pas la correction du Tout-Puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Car c’est lui qui fait la plaie et la bande; il blesse et ses mains guérissent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Dans six détresses, il te délivrera; et dans sept, le mal ne te touchera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'En temps de famine, il te garantira de la mort, et en temps de guerre, du tranchant de l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Tu seras à couvert du fléau de la langue, et tu n’auras point peur de la désolation, quand elle arrivera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Tu riras de la dévastation et de la famine, et tu n’auras pas peur des bêtes de la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Car tu auras un pacte avec les pierres des champs, et les bêtes des champs seront en paix avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Et tu verras la prospérité dans ta tente: tu visiteras tes pâturages,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Et rien ne t’y manquera; et tu verras ta postérité croissante, et tes descendants pareils à l’herbe de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Tu entreras mûr dans le tombeau, comme une gerbe qu’on emporte en son temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Voilà, nous avons examiné la chose; elle est ainsi, écoute cela, et fais-en ton profit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Et Job prit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'Oh! si l’on pesait ma douleur, et si l’on mettait en même temps mes calamités dans la balance!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Elles seraient plus pesantes que le sable des mers! Voilà pourquoi mes paroles sont outrées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Car les flèches du Tout-Puissant sont sur moi: mon âme en boit le venin. Les terreurs de Dieu se rangent en bataille contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'L’onagre brait-il auprès de l’herbe? Et le bœuf mugit-il auprès de son fourrage?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Mange-t-on sans sel ce qui est fade? Trouve-t-on du goût dans un blanc d’œuf?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Ce que mon âme refusait de toucher, est comme devenu ma dégoûtante nourriture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Oh! puisse mon vœu s’accomplir et Dieu me donner ce que j’attends!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Qu’il plaise à Dieu de me réduire en poussière, qu’il laisse aller sa main pour m’achever!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Et j’aurai une consolation, et j’aurai des transports de joie au milieu des tourments qu’il ne m’épargne pas: c’est que je n’ai pas renié les paroles du Saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Quelle est ma force pour que j’espère, et quelle est ma fin pour que je prenne patience?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Ma force est-elle la force des pierres? Ma chair est-elle d’airain?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Ne suis-je pas sans secours, et toute ressource ne m’est-elle pas ôtée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Le malheureux a droit à la pitié de son ami, eût-il abandonné la crainte du Tout-Puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Mes amis m’ont trompé comme un torrent, comme le lit des torrents qui passent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Ils sont troublés par les glaçons, la neige s’y engloutit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Mais, au temps de la sécheresse, ils tarissent, et, dans les chaleurs, ils disparaissent de leur place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Les caravanes se détournent de leur route; elles montent dans le désert et se perdent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Les caravanes de Théma y comptaient; les voyageurs de Shéba s’y attendaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Ils sont honteux d’avoir eu cette confiance: ils arrivent sur les lieux, et restent confondus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'C’est ainsi que vous me manquez à présent; vous voyez une chose terrible, et vous en avez horreur!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Mais vous ai-je dit: \"Donnez-moi quelque chose, et, de vos biens, faites des présents en ma faveur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'Délivrez-moi de la main de l’ennemi, et rachetez-moi de la main des violents? \"');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Instruisez-moi, et je me tairai. Faites-moi comprendre en quoi j’ai erré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Oh! que les paroles droites ont de force! Mais que veut censurer votre censure?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Sont-ce des mots que vous voulez censurer? Mais il faut laisser au vent les paroles d’un homme au désespoir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Vraiment, vous joueriez au sort un orphelin, et vous vendriez votre ami!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Mais, à présent, veuillez jeter les yeux sur moi, et voyez si je vous mens en face!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Revenez donc, et soyez sans injustice! Revenez, et que mon bon droit paraisse!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Y a-t-il de l’injustice dans ma langue? Et mon palais ne sait-il pas discerner le mal?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'L’homme n’a-t-il pas sur la terre un service de soldat, et ses jours ne sont-ils pas comme ceux d’un mercenaire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Comme un esclave, il soupire après l’ombre, et, comme un mercenaire, il attend son salaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Ainsi j’ai reçu en partage des mois de déception, et l’on m’a assigné des nuits de fatigue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Si je suis couché, je dis: Quand me lèverai-je? Quand finira la nuit? Et je suis rassasié d’inquiétudes jusqu’au point du jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Ma chair est couverte de vermine et d’écailles terreuses; ma peau se crevasse et coule.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Mes jours ont passé plus légers que la navette du tisserand, et ils se consument sans espoir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Considère que ma vie est un souffle, et que mon œil ne reverra plus le bonheur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'L’œil qui me voit, ne m’apercevra plus; tes yeux me chercheront, et je ne serai plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'La nuée se dissipe et s’en va, ainsi celui qui descend aux enfers n’en remontera pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Il ne reviendra plus dans sa maison, et son lieu ne le reconnaîtra plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'C’est pourquoi, je ne retiendrai point ma bouche, je parlerai dans la détresse de mon esprit, je me plaindrai dans l’amertume de mon âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Suis-je une mer? Suis-je un monstre marin, pour que tu poses autour de moi une garde?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Quand je dis: Mon lit me consolera; ma couche me soulagera de ma peine;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'Alors, tu me terrifies par des songes, et tu m’épouvantes par des visions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Ainsi j’aime mieux étouffer, j’aime mieux mourir que conserver mes os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Je suis ennuyé de la vie. Je ne vivrai pas toujours. Retire-toi de moi, car mes jours sont un souffle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Qu’est-ce que l’homme pour que tu en fasses un si grand cas, pour que tu prennes garde à lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Pour que tu l’inspectes tous les matins, pour que tu le scrutes à chaque instant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Quand finiras-tu de me regarder? Ne me lâcheras-tu pas, pour que j’avale ma salive?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Si j’ai péché, que t’ai-je fait, à toi, ô surveillant des hommes! Pourquoi m’as-tu mis en butte à tes coups, et suis-je à charge à moi- même?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Et pourquoi ne pardonnes-tu pas mon péché, et ne fais-tu pas disparaître mon iniquité? Car je vais maintenant me coucher dans la poussière; tu me chercheras, et je ne serai plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Alors Bildad, de Shuach, prit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Jusques à quand parleras-tu ainsi, et les paroles de ta bouche ressembleront-elles à un vent impétueux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Dieu ferait-il fléchir le droit, le Tout-Puissant ferait-il fléchir la justice?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Si tes fils ont péché contre lui, il les a livrés à leur crime.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Mais toi, si tu cherches Dieu, et si tu demandes grâce au Tout- Puissant,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Si tu es pur et droit, il veillera certainement sur toi; il restaurera la demeure de ta justice;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Tes commencements auront été peu de chose, et ta fin sera très grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Interroge, en effet, les générations précédentes, et fais attention aux recherches de leurs pères;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Car nous sommes d’hier et nous ne savons rien; car nos jours sur la terre sont comme une ombre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Mais eux, ne t’enseigneront-ils pas, ne te parleront-ils pas, ne tireront-ils pas de leur cœur ces discours:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Le roseau croît-il hors des marais, et le jonc pousse-t-il sans eau?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Il est encore en sa verdure, on ne le coupe pas, et avant toutes les herbes, il est desséché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Telle est la destinée de tous ceux qui oublient Dieu: l’espérance de l’impie périra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Sa confiance sera trompée, et sa sécurité deviendra une toile d’araignée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Il s’appuiera sur sa maison, et elle ne tiendra pas; il s’y cramponnera, et elle ne restera pas debout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Il est plein de vigueur, exposé au soleil, et ses jets poussent par-dessus son jardin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Mais ses racines s’entrelacent sur des monceaux de pierres, il rencontre un sol de rochers,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Et si on l’enlève de sa place, celle-ci le renie et lui dit: Je ne t’ai point connu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Telle est la joie qu’il a de sa conduite, et d’autres après lui s’élèveront de la poussière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'C’est ainsi que Dieu ne rejette pas l’homme intègre, mais il ne donne pas la main aux méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Il remplira encore ta bouche de joie, et tes lèvres de chants d’allégresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Tes ennemis seront couverts de honte, et la tente des méchants ne sera plus!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Et Job prit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Certainement, je sais qu’il en est ainsi; et comment l’homme serait-il juste devant Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'S’il veut plaider avec lui, il ne lui répondra pas une fois sur mille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Il est habile en son intelligence, et puissant en sa force: qui lui a résisté et s’en est bien trouvé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Il transporte les montagnes, et elles ne le savent pas; il les bouleverse en sa fureur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Il fait trembler la terre sur sa base, et ses colonnes sont ébranlées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Il parle au soleil, et le soleil ne se lève pas; et il met un sceau sur les étoiles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Seul, il étend les cieux, et il marche sur les hauteurs de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Il a créé la grande Ourse, l’Orion, et la Pléiade, et les régions cachées du midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Il fait de grandes choses qu’on ne peut sonder, de merveilleuses choses qu’on ne peut compter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Voici, il passe près de moi, et je ne le vois pas; il passe encore, et je ne l’aperçois pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'S’il ravit, qui le lui fera rendre? Qui lui dira: Que fais-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Dieu ne revient pas sur sa colère; sous lui sont abattus les plus puissants rebelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Combien moins lui pourrais-je répondre, moi, et choisir mes paroles pour lui parler!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Quand j’aurais raison, je ne lui répondrais pas; je demanderais grâce à mon juge!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Si je le citais, et qu’il me répondît, je ne croirais pas qu’il voulût écouter ma voix,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Lui qui fond sur moi dans une tempête, et qui multiplie mes plaies sans motif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Il ne me permet point de reprendre haleine; il me rassasie d’amertume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'S’il est question de force, il dit: \"Me voilà! \" S’il est question de droit: \"Qui m’assigne? \"');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Quand même je serais juste, ma bouche me condamnerait; je serais innocent, qu’elle me déclarerait coupable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Je suis innocent. Je ne me soucie pas de vivre, je ne fais aucun cas de ma vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Tout se vaut! C’est pourquoi j’ai dit: Il détruit l’innocent comme l’impie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Quand un fléau soudain répand la mort, il se rit des épreuves des innocents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'La terre est livrée aux mains des méchants; il couvre les yeux de ceux qui la jugent. Si ce n’est lui, qui est-ce donc');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Mes jours ont été plus légers qu’un courrier; ils se sont enfuis, sans voir le bonheur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Ils ont glissé comme des barques de roseaux, comme l’aigle qui fond sur sa proie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Si je dis: Je veux oublier ma plainte, quitter mon air triste, et reprendre ma sérénité,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Je suis effrayé de toutes mes douleurs: je sais que tu ne me jugeras pas innocent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Moi, je suis condamné, pourquoi me fatiguer en vain?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Quand je me laverais dans la neige, quand je purifierais mes mains dans la potasse,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'Tu me plongerais dans le fossé, et mes vêtements m’auraient en horreur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Car il n’est pas un homme comme moi pour que je lui réponde, pour que nous allions ensemble en justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Il n’y a pas d’arbitre entre nous, qui pose sa main sur nous deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Qu’il ôte sa verge de dessus moi, et que ses terreurs ne me troublent plus!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Alors je lui parlerai sans crainte; car, dans l’état où je me trouve, je ne suis plus à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Mon âme a pris en dégoût la vie; je laisserai aller ma plainte, je parlerai dans l’amertume de mon âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Je dirai à Dieu: Ne me condamne point; fais-moi savoir pourquoi tu me prends à partie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Peux-tu te plaire à accabler, à repousser l’œuvre de tes mains, et à éclairer les desseins des méchants?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'As-tu des yeux de chair? Vois-tu comme voient les mortels?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Tes jours sont-ils comme les jours des mortels? Tes années sont- elles comme les jours des humains?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Pour que tu fasses la recherche de mon iniquité et l’enquête de mon péché,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Quoique tu saches que je ne suis pas coupable, et que nul ne peut me délivrer de ta main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Tes mains m’ont formé et m’ont fait tout entier. Et tu me détruirais!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Souviens-toi donc que tu m’as formé comme de l’argile, et tu me ferais rentrer dans la poussière!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Ne m’as-tu pas coulé comme du lait, et caillé comme un fromage?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Tu m’as revêtu de peau et de chair, et tu m’as composé d’os et de nerfs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Tu m’as comblé de vie et de grâces, et ta providence a gardé mon souffle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Et voici ce que tu me réservais en ton cœur! Et voici, je le vois, ce qui était dans ta pensée:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Si je péchais, tu le remarquerais, et tu ne m’absoudrais pas de ma faute;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Si j’étais méchant, malheur à moi! Si j’étais juste, je n’en lèverais pas la tête plus haut, je serais rassasié d’ignominie et spectateur de ma propre misère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Si je redressais la tête, tu me donnerais la chasse comme à un lion, et tu multiplierais tes exploits contre moi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Tu produirais de nouveaux témoins contre moi, tu redoublerais de colère à mon égard, tes bataillons se renouvelleraient contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Mais pourquoi m’as-tu fait sortir du sein de ma mère? J’eusse expiré, et aucun œil ne m’aurait vu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Je serais comme n’ayant pas été; j’aurais été porté du sein maternel au tombeau!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Mes jours ne sont-ils pas en petit nombre? Qu’il me laisse! Qu’il éloigne sa main de moi, et que je respire un peu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'Avant que j’aille, pour n’en plus revenir, dans la terre des ténèbres et de l’ombre de la mort;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'Terre obscure comme la nuit, où règnent l’ombre de la mort et le chaos, où la lumière est comme la nuit!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Alors Tsophar, de Naama, prit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'Ne répondra-t-on point à tant de discours, et suffira-t-il d’être un grand parleur pour être justifié?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Tes vains propos feront-ils taire les gens? Te moqueras-tu, sans que personne te confonde?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Tu as dit: Ma doctrine est pure, je suis sans tache devant tes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Mais je voudrais que Dieu parlât, et qu’il ouvrît sa bouche pour te répondre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'Qu’il te montrât les secrets de sa sagesse, de son immense sagesse; et tu reconnaîtrais que Dieu oublie une partie de ton iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Trouveras-tu le fond de Dieu? Trouveras-tu la limite du Tout- Puissant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Ce sont les hauteurs des cieux: qu’y feras-tu? C’est plus profond que les enfers: qu’y connaîtras-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Son étendue est plus longue que la terre, et plus large que la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'S’il saisit, s’il emprisonne, s’il assemble le tribunal, qui l’en empêchera?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Car il connaît, lui, les hommes de rien; il voit l’iniquité, sans qu’elle s’en doute;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Mais l’homme vide de sens de-viendra intelligent, quand l’ânon sauvage naîtra comme un homme!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Si tu disposes bien ton cœur, et si tu étends tes mains vers Dieu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, '(Si l’iniquité est en tes mains, éloigne-la, et que le crime n’habite point dans tes tentes!)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Alors certainement tu lèveras ton front sans tache; tu seras raffermi et tu ne craindras rien;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Tu oublieras tes peines, tu t’en souviendras comme des eaux écoulées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'La vie se lèvera pour toi plus brillante que le midi, et l’obscurité même sera comme le matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Tu seras plein de confiance, parce que tu auras lieu d’espérer; tu exploreras autour de toi, et tu te coucheras en sécurité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Tu t’étendras à ton aise, et nul ne t’effraiera; et bien des gens te feront la cour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Mais les yeux des méchants seront consumés; tout refuge leur sera ôté, et toute leur espérance sera de rendre l’âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Et Job prit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Vraiment, vous êtes tout un peuple, et avec vous mourra la sagesse!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'J’ai pourtant du sens aussi bien que vous, je ne vous suis point inférieur; et qui ne sait de telles choses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Je suis un homme qui est en risée à son ami; un homme qui invoquait Dieu, et Dieu lui répondait! En risée! un homme juste, intègre!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Mépris au malheur! telle est la pensée des heureux; le mépris est réservé à ceux dont le pied chancelle!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Elles sont en paix, les tentes des pillards, et toutes les sécurités sont pour ceux qui irritent Dieu, qui se font un dieu de leur bras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Mais interroge donc les bêtes, et elles t’instruiront; ou les oiseaux des cieux, et ils te l’annonceront;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Ou parle à la terre, et elle t’instruira; et les poissons de la mer te le raconteront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Qui ne sait, parmi tous ces êtres, que la main de Dieu a fait cet univers?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'Qu’il tient en sa main l’âme de tous les vivants, l’esprit de toute chair d’homme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'L’oreille ne juge-t-elle pas des discours, comme le palais goûte les aliments?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'La sagesse est dans les vieillards, et le discernement est le fruit des longs jours!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Non, c’est en Dieu que se trouvent la sagesse et la force; c’est à lui qu’appartiennent le conseil et l’intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Voici, il démolit, et on ne rebâtit point; il enferme quelqu’un, et on ne lui ouvre pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Voici, il retient les eaux, et elles tarissent; il les lâche, et elles bouleversent la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'En lui résident la puissance et la sagesse; de lui dépendent celui qui s’égare et celui qui égare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Il fait marcher pieds nus les conseillers; il frappe de folie les juges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Il relâche l’autorité des rois, et il serre la corde sur leurs reins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Il fait marcher pieds nus les prêtres, et il renverse les puissants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Il ôte la parole aux plus assurés, et il prive de sens les vieillards.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Il verse le mépris sur les nobles, et il délie la ceinture des forts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Il met en évidence les profondeurs cachées dans les ténèbres, et il amène à la lumière l’ombre de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Il agrandit les nations, et il les perd; il étend les nations, et il les conduit en captivité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Il ôte le sens aux chefs des peuples de la terre, et il les fait errer dans un désert sans chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'Ils tâtonnent dans les ténèbres, sans aucune clarté, et il les fait errer comme un homme ivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Voici, mon œil a vu tout cela; mon oreille l’a entendu et compris;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Ce que vous savez, je le sais aussi; je ne vous suis pas inférieur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Mais je veux parler au Tout-Puissant, je veux plaider auprès de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Mais vous, vous êtes des inventeurs de mensonges. Vous êtes tous des médecins de néant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Puissiez-vous demeurer dans le silence, et que ce soit là votre sagesse!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Écoutez donc ma réprimande, et soyez attentifs à la réplique de mes lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Tiendrez-vous des discours injustes en faveur de Dieu? Et, pour le défendre, direz-vous des mensonges?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Ferez-vous acception de personnes en sa faveur? Prétendrez-vous plaider pour Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Vous en prendra-t-il bien, s’il vous sonde? Comme on trompe un homme, le tromperez-vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Certainement, il vous reprendra, si secrètement vous faites acception de personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Sa majesté ne vous épouvantera-t-elle point, et sa frayeur ne tombera-t-elle pas sur vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Vos réminiscences sont des sentences de cendre, vos remparts sont des remparts de boue!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Taisez-vous, laissez-moi; je veux parler, et qu’il m’arrive ce qui pourra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Pourquoi prendrais-je ma chair dans mes dents? Non, j’exposerai ma vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Voici, il me tuera; je n’ai plus d’espoir. Du moins, je défendrai ma conduite devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Et cela me tournera à salut; car un impie ne viendrait pas devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Écoutez, écoutez mes paroles, prêtez l’oreille à mes déclarations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Voici, j’ai préparé ma cause. Je sais que je serai justifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Quelqu’un plaidera-t-il contre moi? Alors je me tais, et je meurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Seulement, ne me fais point deux choses, et alors je ne me cacherai pas loin de ta face:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Éloigne ta main de moi, et que ta terreur ne me trouble point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Puis, appelle-moi et je répondrai. Ou bien, que je parle, et tu me répliqueras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Combien ai-je commis d’iniquités et de péchés? Fais-moi connaître ma transgression et mon péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Pourquoi caches-tu ta face, et me tiens-tu pour ton ennemi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Veux-tu effrayer une feuille que le vent emporte, et poursuivre une paille desséchée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Pour que tu écrives contre moi d’amers arrêts, et que tu me fasses recevoir la peine des péchés de ma jeunesse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Pour que tu mettes mes pieds dans des ceps, que tu épies tous mes chemins, et que tu traces une limite autour de la plante de mes pieds;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Et ce corps se détruit comme du bois vermoulu, comme un vêtement que la teigne a rongé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'L’homme né de femme a la vie courte, et est rassasié de trouble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Comme une fleur, il éclot, et on le coupe; il fuit comme une ombre, et ne subsiste point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Et c’est sur cet être que tu ouvres les yeux, et c’est moi que tu conduis en justice avec toi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Qui peut tirer la pureté de la souillure? Personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Si ses jours sont déterminés, si le nombre de ses mois est fixé par-devers toi, si tu lui as prescrit des limites qu’il ne passera pas,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Détourne tes regards de lui, et qu’il ait quelque repos, jusqu’à ce qu’il goûte, comme un mercenaire, la fin de sa journée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Car il y a de l’espérance pour l’arbre, si on l’a coupé; il reverdit encore, et il ne cesse pas d’avoir des rejetons;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Si sa racine vieillit dans la terre, et si dans la poussière son tronc est mort,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'Dès qu’il sent l’eau, il pousse de nouveau, et il produit des branches comme un jeune plant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Mais quand l’homme meurt, il reste gisant; quand l’homme a expiré, où est-il?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Les eaux de la mer s’écoulent, le fleuve tarit et se dessèche,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Ainsi l’homme se couche, et il ne se relève point. Tant qu’il y aura des cieux, ils ne se réveilleront point, et on ne les fera pas sortir de leur sommeil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Oh! si tu me cachais dans le Sépulcre, si tu me mettais à couvert, jusqu’à ce que ta colère fût passée! Si tu me donnais un terme, après lequel tu te souviendrais de moi');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, '(Si l’homme meurt, revivra-t-il?), tout le temps de ma consigne, j’attendrais, jusqu’à ce que vînt mon remplacement!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Tu appellerais, et je répondrais; tu désirerais de revoir l’ouvrage de tes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Mais, maintenant, tu comptes mes pas, et tu observes tous mes péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Ma transgression est scellée dans le sac, et tu as ajouté à mon iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Mais la montagne s’éboule; le rocher est transporté hors de sa place;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Les eaux minent les pierres; les inondations entraînent la poussière de la terre: ainsi fais-tu périr l’espérance du mortel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Tu ne cesses de l’assaillir, et il s’en va; tu changes son aspect, et tu le renvoies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Que ses fils soient honorés, il n’en saura rien; qu’ils soient méprisés, il ne le verra pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'C’est sur lui seul que sa chair s’afflige, et sur lui que son âme gémit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Alors Éliphaz, de Théman, prit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Le sage répond-il par une science vaine, et remplit-il de vent sa poitrine?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Discute-t-il avec des propos qui ne servent de rien, et avec des paroles sans profit?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Bien plus, tu abolis la piété, et tu détruis la prière qui s’adresse à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Ton iniquité inspire ta bouche, et tu as choisi le langage des rusés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Ta bouche te condamne, et non pas moi; et tes lèvres témoignent contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Es-tu le premier-né des hommes, et as-tu été formé avant les montagnes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'As-tu entendu ce qui s’est dit dans le conseil de Dieu, et as-tu pris pour toi la sagesse?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Que sais-tu que nous ne sachions? Quelle connaissance as-tu que nous n’ayons aussi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Il y a aussi parmi nous des cheveux blancs, des vieillards, plus riches de jours que ton père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Est-ce donc peu de chose pour toi que les consolations de Dieu et les paroles dites avec douceur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Pourquoi ton cœur s’emporte-t-il? Et pourquoi tes yeux regardent- ils de travers?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'C’est contre Dieu que tu tournes ta colère, et que tu fais sortir de ta bouche de tels discours!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Qu’est-ce qu’un mortel pour qu’il soit pur, et un fils de femme pour qu’il soit juste?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Voici, Dieu ne se fie pas à ses saints, et les cieux ne sont pas purs à ses yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Combien plus est abominable et corrompu, l’homme qui boit l’iniquité comme l’eau!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Je t’instruirai, écoute-moi. Je te raconterai ce que j’ai vu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'Ce que les sages ont proclamé, ce qu’ils n’ont point caché, l’ayant tenu de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'A eux seuls ce pays avait été donné, et l’étranger n’avait pas pénétré chez eux:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, '\"Toute sa vie, le méchant est tourmenté, et un petit nombre d’années sont réservées au malfaiteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Des bruits effrayants remplissent ses oreilles; en pleine paix, le destructeur vient sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Il ne croit pas pouvoir sortir des ténèbres, et il se voit épié par l’épée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Il court çà et là, cherchant son pain; il sait que le jour des ténèbres lui est préparé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'La détresse et l’angoisse l’épouvantent; elles l’assaillent comme un roi prêt au combat;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Parce qu’il a levé la main contre Dieu, et a bravé le Tout- Puissant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Il a couru vers lui, avec audace, sous le dos épais de ses boucliers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'L’embonpoint avait couvert son visage, et la graisse s’était accumulée sur ses flancs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'C’est pourquoi il habite des villes détruites, des maisons désertes, tout près de n’être plus que des monceaux de pierres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Il ne s’enrichira pas, et sa fortune ne subsistera pas, et ses propriétés ne s’étendront pas sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Il ne pourra pas sortir des ténèbres; la flamme desséchera ses rejetons, et il s’en ira par le souffle de la bouche de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Qu’il ne compte pas sur la vanité qui le séduit; car la vanité sera sa récompense.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Avant le temps, il prendra fin, et ses branches ne reverdiront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'On arrachera ses fruits non mûrs, comme à une vigne; on jettera sa fleur, comme celle d’un olivier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Car la famille de l’hypocrite est stérile, et le feu dévore les tentes de l’homme corrompu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Il conçoit le tourment, et il enfante la peine; et son ventre prépare une déception. \"');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Et Job prit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'J’ai souvent entendu de pareils discours; vous êtes tous des consolateurs fâcheux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'N’y aura-t-il point de fin à ces discours en l’air? Et qu’est-ce qui te force à me répondre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Moi aussi, je parlerais comme vous, si vous étiez à ma place. J’accumulerais des paroles contre vous; je hocherais la tête sur vous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Je vous fortifierais avec ma bouche, et le mouvement de mes lèvres vous soulagerait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Si je parle, ma douleur ne sera point soulagée. Si je me tais, en sera-t-elle diminuée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Maintenant il m’a épuisé. Tu as dévasté toute ma famille,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Tu m’as saisi, et cela témoigne contre moi; ma maigreur s’est élevée contre moi, elle m’accuse en face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Sa fureur m’a déchiré, et s’est acharnée sur moi. Il a grincé des dents contre moi; mon ennemi aiguise contre moi ses yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Ils ont ouvert contre moi leur bouche; ils m’ont frappé à la joue pour m’outrager; ils se réunissent tous ensemble contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Dieu m’a livré à l’impie; il m’a jeté aux mains des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'J’étais en repos, et il m’a écrasé; il m’a saisi à la gorge, et il m’a brisé. Il m’a posé en butte à ses traits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Ses flèches m’environnent; il me perce les reins, et ne m’épargne pas; il répand à terre mon fiel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Il me fait plaie sur plaie; il court sur moi comme un guerrier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'J’ai cousu un sac sur ma peau; j’ai souillé mon front dans la poussière;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'J’ai le visage tout enflammé, à force de pleurer, et l’ombre de la mort est sur mes paupières,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Quoiqu’il n’y ait point de crime dans mes mains, et que ma prière soit pure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'O terre, ne cache point mon sang, et qu’il n’y ait aucun lieu où s’arrête mon cri!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'A présent même, voici, j’ai mon témoin dans les cieux, et mon garant dans les hauts lieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Mes amis se moquent de moi: c’est vers Dieu que mon œil se tourne en pleurant,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Pour qu’il décide entre l’homme et Dieu, entre le fils d’Adam et son semblable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Car les années qui me sont comptées s’en vont, et j’entre dans un chemin d’où je ne reviendrai pas!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Mon souffle se perd; mes jours s’éteignent; le tombeau m’attend!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Certes, je suis entouré de railleurs, et mon œil veille toute la nuit au milieu de leurs insultes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Dépose un gage, sois ma caution auprès de toi-même; car qui voudrait répondre pour moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Tu as fermé leur cœur à l’intelligence; c’est pourquoi tu ne les feras pas triompher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Tel livre ses amis au pillage, dont les enfants auront les yeux consumés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'On a fait de moi la fable des peuples, un être à qui l’on crache au visage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Et mon œil s’est consumé de chagrin, et tous mes membres sont comme une ombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Les hommes droits en sont consternés, et l’innocent est irrité contre l’impie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Le juste néanmoins persévère dans sa voie, et celui dont les mains sont pures redouble de constance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Mais, pour vous tous, allons, recommencez! Je ne trouverai pas un sage parmi vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Mes jours sont passés; mes desseins, chers à mon cœur, sont renversés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Ils changent la nuit en jour; ils disent la lumière proche, en face des ténèbres!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Quand je n’attends plus pour demeure que le Sépulcre, quand j’étends ma couche dans les ténèbres,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Quand je crie au tombeau: Tu es mon père! et aux vers: Vous êtes ma mère et ma sœur!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Où est donc mon espérance? Et mon espérance, qui pourrait la voir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Elle descendra aux portes du Sépulcre, quand nous irons en-semble reposer dans la poussière!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Alors Bildad, de Shuach, prit la parole et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Quand finirez-vous ces discours? Ayez du bon sens, et ensuite parlons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Pourquoi sommes-nous regardés comme des bêtes, et sommes-nous stupides à vos yeux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'O toi qui te déchires toi-même dans ta fureur, la terre sera-t-elle abandonnée à cause de toi, et le rocher sera-t-il transporté hors de sa place?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Oui, la lumière du méchant s’éteindra, et la flamme de son feu ne brillera pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'La lumière s’obscurcira dans sa tente, et la lampe s’éteindra au- dessus de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Ses pas si puissants seront restreints, et son propre conseil le renversera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Car il sera pris dans les filets par ses pieds, et il marchera sur le piège.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Le lacet le tiendra par le talon, et le filet le saisira:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Une corde est cachée pour lui sous terre, et une trappe sur son sentier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'De tous côtés des terreurs l’assiégeront, et feront courir ses pieds çà et là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Sa vigueur sera affamée; la calamité se tiendra prête à ses côtés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Il dévorera les membres de son corps, il dévorera ses membres, le premier-né de la mort!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'On l’arrachera de sa tente, objet de sa confiance; on l’amènera au roi des épouvantements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'On habitera dans sa tente, qui ne sera plus à lui; le soufre sera répandu sur sa demeure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'En bas ses racines sécheront, et en haut ses branches seront coupées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Sa mémoire disparaîtra de la terre, et on ne prononcera plus son nom sur les places.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'On le chassera de la lumière dans les ténèbres, et on le bannira du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Il n’aura ni lignée, ni descendance au milieu de son peuple, ni survivant dans ses habitations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Ceux d’Occident seront stupéfaits du jour de sa ruine, et ceux d’Orient en seront saisis d’horreur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Tel est le sort de l’injuste. Telle est la destinée de celui qui ne connaît pas Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Alors Job prit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Jusques à quand affligerez-vous mon âme, et m’accablerez-vous de paroles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Voilà déjà dix fois que vous m’outragez: vous n’avez pas honte de me maltraiter?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Vraiment si j’ai failli, ma faute demeure avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Si vraiment vous vous élevez contre moi, si vous me reprochez l’opprobre où je me trouve,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Sachez donc que c’est Dieu qui m’a fait tort, et qui a tendu ses filets autour de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Voici, je crie à la violence, et on ne me répond pas; je crie au secours, et il n’y a point de justice!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Il a fermé mon chemin, et je ne puis passer; il a mis des ténèbres sur mes sentiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Il m’a dépouillé de ma gloire; il a ôté la couronne de ma tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Il m’a détruit de tous côtés, et je m’en vais; il a arraché, comme un arbre, mon espérance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Il a allumé sa colère contre moi, et il m’a tenu pour l’un de ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Ses troupes sont venues en-semble; elles ont dressé contre moi leurs chaussées, et se sont campées autour de ma tente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Il a éloigné de moi mes frères, et ceux qui me connaissaient se sont écartés comme des étrangers;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Mes proches m’ont abandonné, et mes connaissances m’ont oublié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Les hôtes de ma maison et mes servantes m’ont traité comme un étranger; je suis devenu un inconnu pour eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'J’ai appelé mon serviteur, il ne m’a pas répondu; de ma propre bouche, j’ai dû le supplier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Mon haleine est insupportable à ma femme, et ma prière aux fils de ma mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Les petits enfants eux-mêmes me méprisent: si je veux me lever, ils parlent contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Tous mes intimes m’ont en abomination, et ceux que j’aimais se sont tournés contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Mes os se sont attachés à ma peau et à ma chair, et je me suis échappé avec la peau de mes dents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Ayez pitié de moi, ayez pitié de moi, vous, mes amis! Car la main de Dieu m’a frappé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Pourquoi me persécutez-vous comme Dieu, et ne pouvez-vous vous rassasier de ma chair?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Oh! je voudrais que mes paroles fussent écrites quelque part! Je voudrais qu’elles fussent inscrites dans un livre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Qu’avec un burin de fer et avec du plomb, elles fussent gravées sur le roc, pour toujours!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Pour moi, je sais que mon Rédempteur est vivant, qu’à la fin il se lèvera sur la terre,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'Et qu’après cette peau qui se détruit, et hors de ma chair, je verrai Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Moi, je le verrai, à moi propice; mes yeux le verront, et non un autre. Mes reins se consument en mon sein!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Si vous dites: Comment le poursuivrons-nous, et trouverons-nous en lui la cause de son malheur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Craignez l’épée pour vous-mêmes, car la fureur est un crime digne de l’épée, afin que vous sachiez qu’il y a un jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Tsophar, de Naama, prit la parole et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'C’est pour cela que mes pensées me poussent à répondre, et c’est pour cette raison que j’ai hâte de le faire:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'J’ai entendu une leçon outrageante, mais l’esprit tire de mon intelligence une réponse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Ne sais-tu pas que, de tout temps, depuis que Dieu a mis l’homme sur la terre,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'Le triomphe du méchant est de peu de durée, et la joie de l’impie n’a qu’un moment?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Quand son élévation monterait jusqu’aux cieux, et quand sa tête atteindrait les nues,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'Il périra pour toujours, comme son ordure; ceux qui le voyaient diront: Où est-il?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Il s’envolera comme un songe, et on ne le trouvera plus; il s’évanouira comme un rêve de la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'L’œil qui l’a vu ne le verra plus, et son lieu ne l’apercevra plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Ses enfants feront la cour aux pauvres, et ses propres mains restitueront ses biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Ses os sont pleins de jeunesse, mais elle reposera avec lui dans la poussière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Si le mal est doux à sa bouche, s’il le cache sous sa langue,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'S’il le ménage et ne le rejette point, s’il le retient dans son palais,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'Sa nourriture se changera dans ses entrailles, et deviendra dans son sein du fiel d’aspic.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Il a englouti des richesses, et il les vomira; Dieu les arrachera de son ventre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Il sucera du venin d’aspic; la langue de la vipère le tuera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Il ne verra plus les ruisseaux, les fleuves, les torrents de miel et de lait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Il rendra le fruit de son travail, et ne l’avalera pas; il restituera à proportion de ce qu’il aura amassé, et ne s’en réjouira pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Parce qu’il a foulé, abandonné le pauvre, pillé la maison au lieu de la bâtir;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Parce qu’il n’a pas connu le repos dans son avidité, il ne sauvera rien de ce qu’il a tant désiré;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Rien n’échappait à sa voracité, c’est pourquoi son bonheur ne durera pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Au comble de l’abondance, il sera dans la gêne; les mains de tous les malheureux se jetteront sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Il arrivera que pour lui remplir le ventre, Dieu enverra contre lui l’ardeur de sa colère; il la fera pleuvoir sur lui et entrer dans sa chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Il fuira devant les armes de fer, l’arc d’airain le transpercera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Il arrachera la flèche, et elle sortira de son corps, et le fer étincelant, de son foie; les frayeurs de la mort viendront sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Toutes les calamités sont réservées à ses trésors, un feu qu’on n’aura pas besoin de souffler le dévorera, et ce qui restera dans sa tente sera consumé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Les cieux découvriront son iniquité, et la terre s’élèvera contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Le revenu de sa maison sera emporté. Tout s’écoulera au jour de la colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Telle est la part que Dieu réserve à l’homme méchant, tel est l’héritage que Dieu lui assigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Et Job prit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Écoutez attentivement mes discours, et que cela me tienne lieu de vos consolations!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Supportez-moi, et je parlerai; et, après que j’aurai parlé, tu te moqueras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Mais est-ce à un homme que s’adresse ma plainte? Et comment ne perdrais-je pas toute patience?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Regardez-moi, et soyez étonnés, et mettez la main sur la bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Quand j’y pense, je suis éperdu, et un frisson saisit ma chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Pourquoi les méchants vivent-ils, vieillissent-ils, et croissent- ils en force?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Leur postérité s’établit devant eux, avec eux, et leurs rejetons sont sous leurs yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Leurs maisons sont en paix, à l’abri de la crainte, et la verge de Dieu n’est pas sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Leur taureau n’est jamais impuissant, leur génisse vêle et n’avorte pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Ils font courir devant eux leurs enfants comme un troupeau, et leur progéniture bondit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Ils chantent avec le tambourin et la harpe, ils s’égaient au son du hautbois,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Ils passent leurs jours dans le bonheur, et ils descendent au Sépulcre en un moment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Et cependant ils ont dit à Dieu: \"Éloigne-toi de nous, nous ne voulons pas connaître tes voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Qu’est-ce que le Tout-Puissant, pour que nous le servions? Et que gagnerions-nous à le prier? \"');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Voici, leur bonheur n’est-il pas en leurs mains? (Que le conseil des méchants soit loin de moi!)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Combien de fois arrive-t-il que la lampe des méchants s’éteigne, que leur ruine vienne sur eux, que Dieu leur partage leurs lots dans sa colère,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Qu’ils soient comme la paille au souffle du vent, et comme la balle enlevée par le tourbillon?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Vous dites: \"Dieu réserve la peine à ses enfants; \" mais qu’Il le punisse lui-même, afin qu’il le sente!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Qu’il voie de ses propres yeux sa ruine, qu’il boive la colère du Tout-Puissant!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Car, que lui importe sa maison après lui, quand le nombre de ses mois est tranché?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Enseignerait-on la science à Dieu, lui qui juge ceux qui sont élevés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'L’un meurt au sein du bien-être, tout à son aise et en repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Ses flancs sont chargés de graisse, et ses os comme abreuvés de mœlle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Un autre meurt dans l’amertume de son âme, n’ayant jamais goûté le bonheur:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Ils sont couchés ensemble dans la poussière, et les vers les couvrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Voici, je connais vos pensées et les desseins que vous formez contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Car vous dites: Où est la maison de l’homme opulent, et où est la tente, demeure des méchants?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'N’avez-vous jamais interrogé les voyageurs, et n’avez-vous pas reconnu, par leurs témoignages,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'Qu’au jour de la calamité, le méchant est épargné, et qu’au jour des colères, il est éloigné?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Qui lui représente en face sa conduite, et qui lui rend ce qu’il a fait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Il est porté au tombeau, et, sur le tertre, il veille encore.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Les mottes de la vallée lui sont légères; après lui, suivent à la file tous les hommes, et devant lui, la foule est innombrable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Comment donc me donnez-vous des consolations vaines? De vos réponses, ce qui reste, c’est la perfidie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Alors Éliphaz, de Théman, prit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'L’homme est-il utile à Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'C’est à lui-même que le sage est utile. Le Tout-Puissant a-t-il de l’intérêt à ce que tu sois juste? Gagne-t-il quelque chose à ce que tu marches dans l’intégrité?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Est-ce par crainte de toi, qu’il te reprend, et qu’il entre en jugement avec toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Ta méchanceté n’est-elle pas grande, et tes iniquités ne sont-elles pas sans nombre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Tu exigeais des gages de tes frères, sans motif; tu privais de leurs vêtements ceux qui étaient nus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Tu ne donnais pas d’eau à boire à l’homme altéré, et tu refusais le pain à l’homme affamé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Tu livrais la terre à celui qui était puissant, et celui pour qui tu avais des égards y habitait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Tu renvoyais les veuves les mains vides, et les bras des orphelins étaient brisés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'C’est pour cela que les pièges sont autour de toi, qu’une subite frayeur t’épouvante,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Ou que les ténèbres t’empêchent de voir, et que le débordement des eaux te submerge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Dieu n’est-il pas là-haut dans les cieux? Regarde le front des étoiles: combien elles sont élevées!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Et tu as dit: \"Qu’est-ce que Dieu connaît? Jugera-t-il à travers l’obscurité?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Les nues sont pour lui un voile, et il ne voit rien; il se promène sur la voûte des cieux. \"');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Veux-tu suivre l’ancien chemin, où ont marché les hommes d’iniquité,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Qui ont été retranchés avant le temps, et dont un fleuve a emporté les fondations,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'Qui disaient à Dieu: \"Éloigne-toi de nous! \" Et que leur avait fait le Tout-Puissant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Il avait rempli leurs maisons de biens! (Ah! loin de moi le conseil des méchants!)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Les justes le verront et se réjouiront; l’innocent se moquera d’eux:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, '\"Certainement notre adversaire a été détruit; le feu a dévoré ce qui en restait. \"');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Attache-toi donc à Lui, et tu seras en paix, et il t’en arrivera du bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Reçois de sa bouche l’instruction, et mets ses paroles dans ton cœur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Si tu reviens au Tout-Puissant, tu seras rétabli; éloigne l’iniquité de ta tente,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Jette l’or dans la poussière, et l’or d’Ophir dans les rochers des torrents,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'Et le Tout-Puissant sera ton or, il sera pour toi et argent et trésors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Car alors tu feras tes délices du Tout-Puissant, et tu élèveras ton visage vers Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Tu le supplieras, et il t’exaucera, et tu lui rendras tes vœux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Si tu formes un dessein, il te réussira, et la lumière resplendira sur tes voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Quand on aura humilié quelqu’un, et que tu diras: Qu’il soit élevé! Dieu délivrera celui qui avait les yeux baissés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Il délivrera le coupable; il sera délivré par la pureté de tes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Et Job prit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Maintenant encore ma plainte est une révolte, et pourtant ma main comprime mes soupirs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Oh! si je savais où le trouver, j’irais jusqu’à son trône,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'J’exposerais ma cause devant lui, et je remplirais ma bouche de preuves;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Je saurais ce qu’il me répondrait, et je comprendrais ce qu’il me dirait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Contesterait-il avec moi dans la grandeur de sa force? Non, seulement il ferait attention à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Ce serait alors un juste qui raisonnerait avec lui, et je serais absous pour toujours par mon juge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Voici, si je vais à l’Orient, il n’y est pas; si je vais à l’Occident, je ne le découvre pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Est-il occupé au Nord, je ne le vois pas. Se cache-t-il au Midi, je ne l’aperçois pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Il sait la voie que j’ai suivie; qu’il m’éprouve, j’en sortirai comme l’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Mon pied s’est attaché à ses pas, j’ai gardé sa voie, et je ne m’en suis pas détourné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Je ne me suis point écarté du commandement de ses lèvres, j’ai tenu aux paroles de sa bouche plus qu’à ma provision ordinaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Mais il n’a qu’une pensée; qui l’en fera revenir? Ce que son âme désire, il le fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Il achèvera ce qu’il a décidé de moi, et il a dans l’esprit bien d’autres choses pareilles à celle-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'C’est pourquoi sa présence m’épouvante; quand j’y pense, j’ai peur de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Dieu a amolli mon cœur, et le Tout-Puissant m’a épouvanté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Car je n’ai pas été retranché avant l’arrivée des ténèbres, et il n’a pas éloigné de ma face l’obscurité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Pourquoi n’y a-t-il pas des temps réservés par le Tout-Puissant? Et pourquoi ceux qui le connaissent ne voient-ils pas ses jours?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'On remue les bornes; on ravit les troupeaux, et on les fait paître;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'On emmène l’âne des orphelins, on prend pour gage le bœuf de la veuve;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'On fait écarter les pauvres du chemin, et les affligés du pays sont contraints de se cacher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Voici, ils sont dans le désert comme des ânes sauvages; ils sortent pour leur travail, espérant une proie; la steppe leur donne le pain pour les enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Ils moissonnent leur pâture dans les champs, ils maraudent dans la vigne de l’impie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Ils passent la nuit nus, faute de vêtement, et n’ont pas de quoi se couvrir contre le froid;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Ils sont percés par la pluie des montagnes, et, manquant d’abri, ils embrassent le rocher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'On arrache l’orphelin à la mamelle, on prend des gages sur le pauvre,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'On le force à marcher nu, sans vêtements, on fait porter les gerbes à des affamés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'Ceux qui pressent l’huile dans leurs maisons, ceux qui foulent dans leurs pressoirs, ont soif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Du sein de la ville, les mourants se lamentent; l’âme des blessés crie; et Dieu ne prend pas garde à ces indignités!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'En voici d’autres qui se révoltent contre la lumière, qui ne connaissent pas ses voies, et ne se tiennent pas dans ses sentiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Le meurtrier se lève au point du jour; il tue le pauvre et l’indigent, et, de nuit, il dérobe comme un voleur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'L’œil de l’adultère épie le soir; il dit: \"Aucun œil ne me verra, \" et il se voile le visage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'Ils forcent les maisons dans les ténèbres, ils se tiennent enfermés le jour, ils ne savent pas ce que c’est que la lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Car le matin leur est à tous comme l’ombre de la mort; si quelqu’un les reconnaît, ils ont des frayeurs mortelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Ils disparaissent comme un corps léger sur la surface de l’eau; leur héritage est maudit sur la terre; ils ne prennent plus le chemin des vignes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'La sécheresse et la chaleur consument les eaux de la neige; ainsi le Sépulcre dévore ceux qui pèchent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Le sein qui les porta les oublie; les vers font d’eux bonne chère; on ne se souvient plus d’eux; l’injuste est brisé comme du bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Lui qui tourmentait la femme stérile, sans enfants, et ne faisait aucun bien à la veuve;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Qui entraînait les puissants par sa force; qui se levait et nul n’était sûr de sa vie:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Dieu lui donnait de la sécurité, et il s’y appuyait; et ses yeux étaient sur leurs voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Ils s’étaient élevés: un peu de temps encore, ils ne sont plus; ils s’affaissent, ils sont emportés comme les autres; ils sont coupés comme une tête d’épi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'S’il n’en est pas ainsi, qui me convaincra de mensonge, et mettra à néant mon discours?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Et Bildad, de Shuach, prit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'L’empire et la terreur lui appartiennent, il fait règner la paix dans ses hauts lieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Ses cohortes se peuvent-elles compter, et sur qui sa lumière ne se lève-t-elle pas?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Et comment l’homme serait-il juste devant Dieu? Et comment celui qui est né de la femme serait-il pur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Voici, la lune même est sans éclat, et les étoiles ne sont pas pures à ses yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Combien moins l’homme qui n’est qu’un ver, et le fils de l’homme qui n’est qu’un vermisseau!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Job prit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Comme tu as aidé celui qui était sans force! Comme tu as secouru le bras sans vigueur!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Comme tu as bien conseillé l’homme sans raison, et fait paraître l’abondance de ta sagesse!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'A qui as-tu adressé des discours? Et de qui est l’esprit qui est sorti de toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Les ombres tremblent au-dessous des eaux et de leurs habitants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Le Sépulcre est à nu devant lui, et l’abîme est sans voile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Il étend le septentrion sur le vide, il suspend la terre sur le néant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Il renferme les eaux dans ses nuages, et la nuée n’éclate pas sous leur poids.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Il couvre la face de son trône, il déploie au-dessus sa nuée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Il décrit un cercle sur les eaux, au point où la lumière confine avec les ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Les colonnes des cieux sont ébranlées, et s’étonnent à sa menace.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Par sa force, il soulève la mer; et par son habileté, il écrase les plus puissants rebelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Son souffle rend le ciel pur; sa main perce le dragon fugitif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Ce ne sont là que les bords de ses voies; qu’il est faible le bruit qu’en saisit notre oreille! Et qui pourra entendre le tonnerre de sa puissance?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Et Job continua son discours sentencieux, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'Par le Dieu qui a mis mon droit de côté, par le Tout-Puissant qui a rempli mon âme d’amertume,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Tant qu’un souffle me restera, tant que l’esprit de Dieu sera dans mes narines,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'Mes lèvres ne prononceront rien d’injuste, et ma langue ne dira rien de faux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Loin de moi la pensée de vous donner raison! Jusqu’à mon dernier soupir, je ne me dépouillerai pas de mon intégrité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'J’ai maintenu ma justice, et je ne faiblirai pas; ma conscience ne me reproche aucun de mes jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Que mon ennemi soit comme le méchant, et mon adversaire comme l’injuste!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Car quel sera l’espoir de l’impie, quand Dieu retranchera, quand Dieu arrachera son âme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Dieu entendra-t-il ses cris, quand la détresse viendra sur lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Trouvera-t-il son plaisir dans le Tout-Puissant? Invoquera-t-il Dieu en tout temps?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Je vous enseignerai comment Dieu agit, et je ne vous cacherai pas la pensée du Tout-Puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Voici, vous-mêmes, vous avez tous vu ces choses, et pourquoi donc vous laissez-vous aller à ces vaines pensées');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Voici la part que Dieu réserve au méchant, et l’héritage que les violents reçoivent du Tout-Puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Si ses enfants se multiplient, c’est pour l’épée; et ses rejetons ne seront pas rassasiés de pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Ses survivants seront ensevelis par la peste, et leurs veuves ne les pleureront pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Qu’il amasse de l’argent comme la poussière, qu’il entasse des vêtements comme de la boue,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'Il entassera, et le juste s’en revêtira, et l’innocent se partagera son argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Il se bâtit une maison comme celle de la teigne, comme la cabane du gardien des vignes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Il se couche riche, et c’est pour la dernière fois; il ouvre ses yeux, et il n’est plus;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Les frayeurs l’atteignent comme des eaux débordées; la tempête le ravit dans la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Le vent d’Orient l’emporte, et il s’en va; il l’arrache de sa place comme un tourbillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Le Seigneur jette sur lui ses traits, et ne l’épargne pas; il fuit de toute sa force devant sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'On bat des mains contre lui; on le chasse à coups de sifflets.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'L’argent a des lieux d’extraction, et l’or a des endroits où on l’affine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Le fer se tire de la poussière, et la pierre fondue donne l’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'L’homme dissipe les ténèbres; il explore, jusqu’aux extrêmes limites, la pierre qui est dans l’obscurité et l’ombre de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Il creuse un puits, loin des passants; ne se souvenant plus de ses pieds, il est suspendu et balancé loin des humains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'C’est de la terre que sort le pain, et elle est bouleversée, dans ses profondeurs, comme par le feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Ses rochers sont la demeure du saphir, et l’on y trouve la poudre d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'L’oiseau de proie n’en connaît pas le chemin, et l’œil du milan ne le découvre pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Les bêtes féroces n’y ont point marché, le lion n’a point passé par là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'L’homme met la main sur le granit; il bouleverse les montagnes jusqu’en leurs fondements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Il taille des galeries dans les rochers, et son œil découvre tout ce qu’il y a de précieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Il arrête la filtration des eaux, et il met au jour ce qui était caché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Mais la sagesse, où la trouvera-t-on? Où donc est le lieu de l’intelligence?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'L’homme ne connaît pas son prix, et elle ne se trouve pas dans la terre des vivants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'L’abîme dit: Elle n’est pas en moi; et la mer dit: Elle n’est pas avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Elle ne se donne pas pour de l’or fin, elle ne s’achète pas au poids de l’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'On ne la met pas en balance avec l’or d’Ophir; ni avec le précieux onyx, ni avec le saphir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'On ne la compare point avec l’or et avec le verre, et on ne l’échange pas pour des vases d’or fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'On ne parle ni du corail ni du cristal, et la possession de la sagesse vaut plus que des perles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'On ne la compare pas avec la topaze d’Éthiopie; on ne la met pas en balance avec l’or le plus fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Mais la sagesse, d’où viendra-t-elle? Et où donc est la demeure de l’intelligence?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Elle est cachée aux yeux de tous les vivants; elle se dérobe aux oiseaux des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Le gouffre et la mort disent: Nous avons de nos oreilles entendu parler d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'C’est Dieu qui sait son chemin; c’est lui qui connaît sa demeure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Car il regarde, lui, jusqu’aux extrémités du monde; il voit sous tous les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Quand il donnait au vent son poids, quand il pesait et mesurait les eaux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'Quand il prescrivait une loi à la pluie, et un chemin à l’éclair des tonnerres,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'Il la vit alors et la proclama; il l’établit, et même il la sonda;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Puis il dit à l’homme: Voici, la crainte du Seigneur, c’est la sagesse, et se détourner du mal, c’est l’intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Job continua son discours sentencieux, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'Oh! que ne suis-je comme aux mois d’autrefois, comme au jour où Dieu me gardait,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'Quand son flambeau luisait sur ma tête, quand je marchais à sa lumière dans les ténèbres;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Comme aux jours de mon automne, quand l’amitié de Dieu veillait sur ma tente;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'Quand le Tout-Puissant était encore avec moi, et que mes jeunes gens m’entouraient;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'Quand je lavais mes pieds dans le lait, et que le rocher se fondait près de moi en torrent d’huile!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Quand je sortais pour me rendre à la porte de la ville, et que je me faisais préparer un siège dans la place publique,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Les jeunes gens, me voyant, se retiraient; les vieillards se levaient et se tenaient debout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Des princes s’arrêtaient de parler, et mettaient la main sur leur bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'La voix des chefs s’éteignait, et leur langue s’attachait à leur palais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Car l’oreille qui m’entendait me proclamait heureux, et l’œil qui me voyait me rendait témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Car je délivrais l’affligé qui criait, et l’orphelin qui n’avait personne pour le secourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'La bénédiction de celui qui s’en allait périr venait sur moi, et je faisais chanter de joie le cœur de la veuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Je me revêtais de la justice, et elle se revêtait de moi. Mon équité était mon manteau et ma tiare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'J’étais les yeux de l’aveugle, et les pieds du boiteux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'J’étais le père des pauvres, et j’étudiais à fond la cause de l’inconnu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'Je brisais les mâchoires de l’injuste, et j’arrachais la proie d’entre ses dents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Et je disais: Je mourrai avec mon nid, et je multiplierai mes jours comme le phénix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Ma racine sera exposée à l’eau, et la rosée passera la nuit dans mes branches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Ma gloire se renouvellera en moi, et mon arc se renforcera dans ma main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'On m’écoutait, on attendait et on se taisait, jusqu’à ce que j’eusse donné mon avis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Après que j’avais parlé, on ne répliquait pas, et ma parole découlait goutte à goutte sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Ils m’attendaient comme la pluie, et ils ouvraient leur bouche comme pour une ondée tardive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Je souriais quand ils étaient désespérés; et ils n’altéraient pas la sérénité de mon visage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'J’aimais à aller avec eux, et je m’asseyais à leur tête; je siégeais comme un roi au milieu de ses gardes, comme un consolateur au milieu des affligés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Mais, maintenant, des hommes plus jeunes que moi se moquent de moi, des hommes dont je n’aurais pas daigné mettre les pères avec les chiens de mon troupeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Et qu’aurais-je pu faire de la force de leurs mains? En eux avait péri toute vigueur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Exténués par la disette et la faim, ils broutent les lieux arides, depuis longtemps désolés et déserts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'Ils cueillent l’herbe sauvage près des buissons, et la racine des genêts est leur nourriture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'On les chasse du milieu des hommes; on crie après eux comme après un larron;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Ils habitent dans des torrents affreux, dans les trous de la terre, et parmi les rochers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'On les entend braire dans les buissons, ils s’étendent pêle-mêle sous les chardons;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'Race impie, race sans nom, qui avait été chassée du pays!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Et maintenant je suis le sujet de leurs chansons, et je fais la matière de leurs propos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Ils m’ont en horreur, ils s’éloignent de moi; ils ne craignent pas de me cracher au visage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Parce que Dieu a détendu la corde de mon arc et m’a humilié, ils ont secoué tout frein devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Cette engeance se lève à ma droite; ils poussent mes pieds; ils construisent contre moi des routes pour me nuire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Ils rompent mon chemin, ils aident à ma ruine, eux à qui personne ne porterait secours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Ils arrivent comme par une large brèche, ils se précipitent au milieu du fracas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Toutes les terreurs se tournent contre moi, elles poursuivent ma prospérité comme le vent, et mon bonheur a passé comme un nuage!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Et maintenant mon âme se fond en moi, les jours d’affliction m’ont atteint;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'La nuit perce mes os et les détache, et ceux qui me rongent ne dorment pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Par la violence extrême de mon mal, mon vêtement se déforme; il me serre comme le col de ma tunique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Dieu m’a jeté dans la boue, et je ressemble à la poussière et à la cendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Je crie vers toi, et tu ne me réponds pas; je me tiens debout devant toi, et tu me considères!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Tu es devenu cruel pour moi; tu t’opposes à moi avec toute la force de ton bras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Tu m’enlèves, tu me fais chevaucher sur le vent, et tu me fais fondre au bruit de la tempête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Oui, je sais bien que tu m’amènes à la mort, et dans la demeure, rendez-vous de tous les vivants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Seulement, n’étendrait-on pas la main au milieu de la ruine? Et, dans sa calamité, ne serait-il donc pas permis de pousser un cri?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Ne pleurais-je pas sur l’homme qui passait de mauvais jours? Mon âme n’était-elle pas affligée à cause du pauvre');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'J’ai attendu le bonheur, et le malheur est arrivé. J’espérais la lumière, et les ténèbres sont venues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Mes entrailles bouillonnent sans repos; les jours d’affliction m’ont assailli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Je marche tout noirci, et non par le soleil. Je me lève dans l’assemblée, et je crie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Je suis devenu le frère des chacals, et le compagnon des autruches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Ma peau se noircit et tombe. Mes os sont brûlés par la fièvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Ma harpe s’est changée en deuil, et mon luth en voix de pleurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'J’avais fait un accord avec mes yeux; et comment aurais-je regardé une vierge?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Car quelle part Dieu m’aurait-il faite d’en haut, et quel héritage le Tout-Puissant m’aurait-il envoyé des cieux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'La calamité n’est-elle pas pour le pervers, et l’adversité pour ceux qui commettent l’iniquité?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Ne voit-il pas toute ma conduite, et ne compte-t-il pas tous mes pas?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Si j’ai marché dans le mensonge, et si mon pied s’est hâté pour tromper,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'Que Dieu me pèse dans des balances justes, et il reconnaîtra mon intégrité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Si mes pas se sont détournés de la voie, et si mon cœur a suivi mes yeux, et si quelque souillure s’est attachée à mes mains,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'Que je sème et qu’un autre mange, et que mes rejetons soient déracinés!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Si mon cœur a été séduit par quelque femme, et si j’ai fait le guet à la porte de mon prochain,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'Que ma femme broie le grain pour un autre, et que d’autres se penchent sur elle!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Car c’est là une méchanceté préméditée, une iniquité punie par les juges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'C’est un feu qui dévore jusqu’à pleine destruction, qui eût ruiné tous mes biens dans leur racine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Si j’ai méprisé le droit de mon serviteur ou de ma servante, quand ils ont eu des contestations avec moi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'Et que ferais-je, quand Dieu se lèvera, et quand il demandera compte, que lui répondrais-je?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Celui qui m’a fait dans le sein de ma mère, ne l’a-t-il pas fait aussi? Un même créateur ne nous a-t-il pas formés dans le sein maternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Si j’ai refusé aux pauvres leur demande, si j’ai laissé se consumer les yeux de la veuve,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'Si j’ai mangé seul mon morceau, et si l’orphelin n’en a point mangé,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'Certes, dès ma jeunesse, il a grandi près de moi comme près d’un père, et dès le sein de ma mère, j’ai été le guide de la veuve,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Si j’ai vu un homme périr faute de vêtement, et le pauvre manquer de couverture;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'Si ses reins ne m’ont pas béni, et s’il n’a pas été réchauffé par la toison de mes agneaux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'Si j’ai levé ma main contre l’orphelin, parce que je me voyais appuyé à la porte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'Que mon épaule tombe de ma nuque, et que mon bras soit cassé et séparé de l’os!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Car la frayeur serait sur moi avec la calamité de Dieu, et je ne pourrais pas subsister devant sa majesté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Si j’ai mis dans l’or ma confiance, et si j’ai dit à l’or fin: Tu es ma sécurité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Si je me suis réjoui de ce que ma fortune était grande, et de ce que ma main avait beaucoup acquis;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Si, voyant le soleil briller et la lune s’avancer magnifique,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'Mon cœur a été secrètement séduit, et si ma main a envoyé des baisers');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, '(Ce qui est aussi une iniquité punie par le juge, car c’est un reniement du Dieu d’en haut);');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Si je me suis réjoui du malheur de mon ennemi, si j’ai sauté de joie quand le mal l’a atteint');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, '(Je n’ai pas permis à ma langue de pécher en demandant sa mort dans des malédictions);');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Si les gens de ma maison n’ont pas dit: \"Où y a-t-il quelqu’un qui n’ait été rassasié de sa viande? \"');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, '(L’étranger ne passait pas la nuit dehors; j’ouvrais ma porte au voyageur);');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Si j’ai caché, comme Adam, mes fautes; si j’ai enfermé mon crime dans mon sein,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'Parce que je craignais la foule et redoutais le mépris des familles, en sorte que je restais tranquille et n’osais franchir ma porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Oh! si quelqu’un m’écoutait! Voici ma signature: Que le Tout- Puissant me réponde, et que mon adversaire écrive son mémoire!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Je jure que je le porterai sur mon épaule, je me l’attacherai comme une couronne,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Je lui déclarerai le nombre de mes pas, je l’aborderai comme un prince.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Si ma terre crie contre moi, et si mes sillons pleurent avec elle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'Si je mange ses fruits sans l’avoir payée, si je fais rendre l’âme à ses maîtres,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'Qu’elle produise de l’épine au lieu de froment, et l’ivraie au lieu d’orge! C’est ici la fin des paroles de Job.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Alors ces trois hommes-là cessèrent de répondre à Job, parce qu’il croyait être juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Et Élihu, fils de Barakéel, Buzite, de la famille de Ram, se mit dans une fort grande colère contre Job, parce qu’il se justifiait lui-même devant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Il se mit aussi en colère contre ses trois amis, parce qu’ils ne trouvaient rien à répondre, et que néanmoins ils avaient condamné Job.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Et Élihu avait attendu pour s’adresser à Job qu’ils eussent parlé, parce qu’ils étaient plus âgés que lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Élihu, voyant que ces trois hommes n’avaient plus aucune réponse à la bouche, se mit en colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Et Élihu, fils de Barakéel, Buzite, prit la parole, et dit: Je suis jeune et vous êtes des vieillards, aussi j’ai craint et je n’ai pas osé vous dire mon avis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Je me disais: Les jours parleront, et le grand nombre des années fera connaître la sagesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Mais c’est l’esprit qui est dans les hommes, c’est le souffle du Tout-Puissant qui les rend intelligents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Ce ne sont pas les aînés qui sont sages; ce ne sont pas les vieillards qui comprennent ce qui est juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'C’est pourquoi je dis: Écoute-moi; je dirai mon avis, moi aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Voici, j’ai attendu vos discours, j’ai écouté vos raisonnements, jusqu’à ce que vous eussiez bien examiné les discours de Job.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'Je vous ai suivis attentivement, et voici, pas un de vous n’a convaincu Job, pas un n’a répondu à ses paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Ne dites pas: Nous avons trouvé la sagesse! Dieu seul le mettra en fuite, et non un homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Il n’a pas dirigé ses discours contre moi, et je ne lui répondrai pas à votre manière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Ils sont consternés! Ils ne répondent plus! On leur a ôté l’usage de la parole!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'J’ai attendu: puisqu’ils ne parlent plus, qu’ils se tiennent là sans répondre,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Je répondrai, moi aussi, pour ma part; je dirai mon avis, moi aussi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Car je suis rempli de discours; l’esprit qui est en mon sein me presse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Voici, mon sein est comme un vin sans issue, il va éclater comme des outres neuves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Je parlerai donc et je me soulagerai, j’ouvrirai mes lèvres et je répondrai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Qu’il ne m’arrive pas d’être partial, et de flatter qui que ce soit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Car je ne sais pas flatter: mon créateur ne m’enlèverait-il pas bientôt!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Mais toi, ô Job, écoute mes discours, et prête l’oreille à toutes mes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Voici, j’ouvre la bouche, ma langue parle en mon palais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Mes paroles exprimeront la droiture de mon cœur; mes lèvres diront franchement ce que je sais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'C’est l’Esprit de Dieu qui m’a fait; c’est le souffle du Tout- Puissant qui m’a donné la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Si tu le peux, réponds-moi; résiste-moi en face, et tiens-toi bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Voici, je suis ton égal devant Dieu; j’ai été tiré de la boue, moi aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Voici, ma terreur ne te troublera point, et ma majesté ne pèsera pas sur toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Vraiment, tu as dit à mes oreilles, et j’ai entendu le son de tes paroles:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Je suis pur, sans péché; je suis net, et il n’y a point d’iniquité en moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Voici, Dieu me cherche querelle, il me tient pour son ennemi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Il met mes pieds dans les ceps, il surveille tous mes mouvements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Voici, en cela, tu n’as pas été juste, te répondrai-je; car Dieu est plus grand que l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Pourquoi as-tu plaidé contre lui? Il ne rend pas compte de ce qu’il fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Dieu parle cependant une fois, deux fois, mais on n’y prend pas garde;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'En songe, par des visions nocturnes, quand le sommeil tombe sur les humains, pendant qu’ils dorment sur leur couche;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'Alors il ouvre l’oreille de l’homme, et il met le sceau sur ses réprimandes,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'Afin de détourner l’homme de son œuvre, et d’éloigner de lui l’orgueil,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Afin de préserver son âme de la fosse, et sa vie de l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'L’homme est aussi châtié par des douleurs, sur son lit, par l’agitation continuelle de ses os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Alors sa vie prend en horreur le pain, et son âme les mets les plus désirés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Sa chair se consume et disparaît; ses os qu’on ne voyait pas, sont mis à nu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'Son âme approche de la fosse, et sa vie de ceux qui font mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'S’il y a pour cet homme quelque ange médiateur, un entre mille, pour lui faire connaître ce qu’il doit faire,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'Alors Dieu prend pitié de lui, et dit: \"Rachète-le; qu’il ne descende pas dans la fosse; j’ai trouvé une rançon! \"');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Sa chair prend plus de fraîcheur que dans son enfance; il revient aux jours de sa jeunesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Il supplie Dieu, et Dieu lui est favorable. Il lui fait contempler avec joie sa face, et il lui rend sa justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Il chante au milieu des hommes, et il dit: \"J’avais péché, j’avais violé la justice, et ma peine n’a pas égalé ma faute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Il a racheté mon âme, afin qu’elle ne passât point dans la fosse, et ma vie voit encore la lumière! \"');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Voilà ce que Dieu fait deux, trois fois, envers l’homme,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'Pour ramener son âme de la fosse, pour qu’elle soit éclairée de la lumière des vivants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Sois attentif, Job, écoute-moi! Tais-toi, et je parlerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Si tu as quelque chose à dire, réponds-moi; parle, car je désire te justifier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Sinon, écoute-moi; tais-toi, et je t’enseignerai la sagesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Élihu reprit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Vous, sages, écoutez mes discours; et vous, savants, prêtez-moi l’oreille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Car l’oreille juge des discours, comme le palais goûte ce qu’on doit manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Choisissons ensemble ce qui est juste; voyons, entre nous, ce qui est bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Job a dit: \"Je suis juste, mais Dieu met mon droit de côté;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'En dépit de mon droit, je suis un menteur; ma plaie est douloureuse, sans que j’aie péché. \"');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Y a-t-il un homme tel que Job, qui boit le blasphème comme l’eau,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'Qui marche dans la compagnie des ouvriers d’iniquité, et qui va avec les hommes pervers?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Car il a dit: L’homme ne gagne rien à se plaire avec Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'C’est pourquoi, vous qui avez de l’intelligence, écoutez-moi. Loin de Dieu la méchanceté! loin du Tout-Puissant l’injustice!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Il rend à l’homme selon ses œuvres, et il fait trouver à chacun selon sa conduite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Certainement Dieu ne commet pas d’injustice, le Tout-Puissant ne fait pas fléchir le droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Qui lui a commis le soin de la terre? Qui lui a confié l’univers?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'S’il ne pensait qu’à lui, s’il retirait à lui son esprit et son souffle,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'Toute chair expirerait à la fois, et l’homme retournerait dans la poussière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Si donc tu as de l’intelligence, écoute cela; prête l’oreille au son de mes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Eh quoi! celui qui haïrait la justice, régnerait-il? Et condamnerais-tu celui qui est souverainement juste?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Lui qui dit aux rois \"Scélérat! \" et \"Méchant! \" aux princes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Qui n’a point égard à la personne des grands, qui ne connaît pas le riche plus que le pauvre, car ils sont tous l’ouvrage de ses mains?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'En un moment ils mourront; au milieu de la nuit, un peuple est ébranlé et passe; le potentat puissant est emporté, et non par une main d’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Car les yeux de Dieu sont sur les voies de l’homme, et il regarde tous ses pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Il n’y a ni ténèbres ni ombre de la mort, où se puissent cacher les ouvriers d’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Il ne regarde pas à deux fois un homme, pour le faire aller en jugement avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Il brise les puissants, sans enquête, et il en établit d’autres à leur place,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Parce qu’il connaît leurs œuvres; il les renverse de nuit, et ils sont brisés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Il les flagelle comme des impies, à la vue de tout le monde,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'Parce qu’ils se sont détournés de lui, et n’ont pas du tout pris garde à ses voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'Ils ont fait monter jusqu’à lui le cri du pauvre, et il a entendu la clameur des affligés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'S’il donne le repos, qui est-ce qui le condamnera? S’il cache sa face, qui le regardera? soit qu’il s’agisse d’un peuple ou d’un particulier,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'Pour que l’homme impie ne règne pas, pour qu’il ne soit pas en piège au peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Car a-t-il dit à Dieu: \"J’ai souffert, je ne pécherai plus;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Ce que je ne vois pas, montre-le-moi; si j’ai fait le mal, je ne le ferai plus? \"');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Est-ce donc d’après tes idées que le mal doit être puni? Car tu as montré du mécontentement. Ainsi, c’est à toi de décider, non à moi! Dis ce que tu sais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Les hommes de sens me diront, ainsi que le sage qui m’aura écouté:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, '\"Job ne parle pas avec con-naissance, et ses paroles sont sans intelligence. \"');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Ah! que Job soit éprouvé jusqu’à la fin, puisqu’il a répondu comme les méchants!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Car il ajoute à son péché une transgression nouvelle; il s’applaudit au milieu de nous; il parle de plus en plus contre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Élihu reprit la parole, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'As-tu pensé avoir raison de dire: Je suis juste devant Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Car tu as dit: Que m’en revient-il, et qu’y gagnerai-je de plus qu’à mon péché?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Je te répondrai en mes discours, et à tes amis avec toi:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Regarde les cieux, et les considère; vois les nues, elles sont plus hautes que toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Si tu pèches, quel effet produis-tu sur lui? et si tes péchés se multiplient, qu’est-ce que tu lui fais?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Si tu es juste, que lui donnes-tu, et que reçoit-il de ta main?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'C’est à un homme tel que toi que ta méchanceté peut nuire, et au fils de l’homme que ta justice peut être utile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'On crie sous le poids de l’oppression, on gémit sous la violence des grands,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'Et l’on ne dit pas: Où est Dieu, mon créateur, celui qui donne de quoi chanter dans la nuit,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'Qui nous rend plus instruits que les bêtes de la terre, et plus sages que les oiseaux des cieux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Ils crient donc sans être exaucés, à cause de l’orgueil des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Dieu n’écoute pas ce qui n’est que mensonge, et le Tout-Puissant n’y a point égard.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Quoique tu aies dit que tu ne le vois pas, le procès est devant lui: attends-le!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Et maintenant, parce que sa colère ne punit pas, parce qu’il ne prend pas rigoureusement connaissance du péché,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Job ouvre sa bouche pour de vains discours, il entasse paroles sur paroles sans science.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Élihu continua, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Attends un peu et je t’instruirai, car il y a encore des raisons pour la cause de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Je prendrai de loin ma science, et je donnerai droit à mon créateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Car, certainement, mes discours ne sont point mensongers, et c’est un homme qui te parle d’une science parfaite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Voici, Dieu est puissant, et il ne dédaigne personne; il est puissant par la force de son intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Il ne laisse point vivre le méchant, et il fait droit aux affligés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Il ne détourne pas ses yeux des justes, il place ces justes avec les rois sur le trône; et il les y fait asseoir pour toujours, et ils sont élevés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'S’ils sont liés de chaînes, s’ils sont pris dans les liens de l’affliction,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'Il leur fait connaître ce qu’ils ont fait, leurs péchés et leur orgueil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'Alors il ouvre leur oreille à la réprimande; il leur dit de se détourner de l’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'S’ils l’écoutent, et s’ils le servent, ils achèvent leurs jours dans le bonheur, et leurs années dans la joie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Mais s’ils ne l’écoutent pas, ils passent par l’épée, et ils expirent dans leur aveuglement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Les cœurs impies se mettent en colère; ils ne crient point à lui quand il les a liés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Leur âme meurt en sa jeunesse, et leur vie s’éteint comme celle des débauchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Il sauve l’affligé par son affliction, et il l’instruit par sa douleur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Et toi-même, il te mettra hors de ta détresse, au large, loin de toute angoisse, et ta table sera dressée, couverte de graisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Mais si tu es plein de la cause du méchant, cette cause et la condamnation se suivront de près.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Prends garde que la colère ne te pousse au blasphème, et ne te laisse pas égarer par la pensée d’une abondante expiation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Ferait-il cas de ta richesse? Il n’estimera ni l’or ni les moyens de l’opulence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Ne souhaite point la nuit, en laquelle les peuples sont enlevés sur place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Garde-toi de te tourner vers l’iniquité; car tu la préfères à l’affliction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Voici, Dieu est élevé en sa puissance; qui pourrait enseigner comme lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Qui lui a prescrit sa voie? Et qui lui dira: Tu as fait une injustice?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Souviens-toi de célébrer ses ouvrages, que tous les hommes chantent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Tout homme les admire, chacun les contemple de loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Voici, Dieu est élevé, et nous ne le connaissons pas; le nombre de ses années, nul ne peut le sonder!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Il attire les gouttes d’eau, elles se fondent en pluie, au milieu du brouillard;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'Les nuées la font couler, et tomber goutte à goutte sur la foule des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Et qui pourrait comprendre le déploiement des nuées, et le fracas de sa tente?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Voici, il étend sur lui-même la lumière, et il couvre le profond des mers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'C’est ainsi qu’il juge les peuples, et qu’il donne la nourriture en abondance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Il tient cachée dans sa main la lumière, et il lui prescrit de frapper.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Son tonnerre l’annonce, et les troupeaux font connaître qu’il s’approche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Mon cœur en est tout tremblant, et il bondit hors de sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Écoutez, écoutez le bruit de sa voix, et le grondement qui sort de sa bouche!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Il l’envoie sous tous les cieux, et son éclair va jusqu’aux extrémités de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Puis, sa voix rugit; il tonne de sa voix magnifique, et il n’épargne pas ses éclairs, quand retentit sa voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Dieu tonne de sa voix merveilleusement; il fait de grandes choses, que nous ne comprenons pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Il dit à la neige: Tombe sur la terre; il le dit aux ondées, aux fortes ondées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Il ferme la main de tous les hommes, afin que tous les hommes, ses créatures, le connaissent,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Et les bêtes se retirent dans leurs tanières, et elles demeurent dans leurs repaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Des profondeurs du Sud vient la tempête, et des vents du Nord vient le froid;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Par son souffle, Dieu forme la glace, et l’eau qui s’étendait est resserrée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Il charge d’humidité la nue; il disperse les nuages, pleins de ses éclairs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Et ceux-ci se promènent de tous côtés, selon ses directions, pour faire tout ce qu’il commande, sur la face de la terre habitée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Que ce soit pour châtier, ou pour rendre sa terre fertile, ou pour exercer sa bonté, il leur fait atteindre le but.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Prête l’oreille à cela, Job: arrête-toi, et considère les merveilles de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Sais-tu comment Dieu les prépare, comment il fait briller la lumière de sa nue?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Sais-tu comment se balancent les nuages, cette merveille de celui dont la science est parfaite?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Comment tes vêtements sont chauds quand il endort la terre par le vent du Midi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'As-tu étendu avec lui les cieux, fermes comme un miroir de métal?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Apprends-nous donc ce que nous devons dire de lui: car nous ne saurions préparer des discours du sein de nos ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Voudrais-je qu’on lui rapportât ce que je dis? Jamais homme voulut-il être englouti?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Et maintenant on ne peut regarder le soleil brillant dans les cieux, quand un vent a passé et les a purifiés,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Quand une lueur d’or vient du septentrion. Il y a en Dieu une majesté redoutable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Le Tout-Puissant! nous ne pouvons l’atteindre; il est sublime en puissance, en droit, en justice; il n’opprime personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'C’est pourquoi les hommes le craignent. Mais il ne regarde pas ceux qui sont sages en leur cœur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Alors l’Éternel répondit à Job du sein de la tempête, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Qui est celui-ci qui obscurcit mes plans par des discours sans science?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Ceins donc tes reins comme un vaillant homme, je t’interrogerai, et tu m’instruiras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Où étais-tu quand je jetais les fondations de la terre? Dis-le, si tu as de l’intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Qui en a réglé les mesures, si tu le sais, ou qui a étendu le niveau sur elle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Sur quoi en a-t-on fait plonger les bases, ou qui en a posé la pierre angulaire,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'Quand les étoiles du matin poussaient ensemble des cris de joie, et les fils de Dieu, des acclamations?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Et qui renferma la mer dans des portes, quand elle sortit en s’élançant du sein de la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Quand je lui donnai la nuée pour vêtement, et l’obscurité pour langes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Quand j’établis ma loi sur elle, quand je lui mis des verrous et des portes,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'Et que je lui dis: Tu viendras jusqu’ici, et tu n’iras pas plus loin; ici s’arrêtera l’orgueil de tes flots?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Depuis que tu es au monde, as-tu commandé au matin, as-tu marqué à l’aurore sa place,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'Pour qu’elle saisisse les extrémités de la terre, et que les méchants soient chassés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'La terre change de forme comme l’argile sous le cachet, et toutes choses se lèvent comme pour la vêtir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'La lumière des méchants leur est ôtée, et le bras des menaçants est rompu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'As-tu pénétré jusqu’aux sources de la mer, et t’es-tu promené au fond de l’abîme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Les portes de la mort se sont-elles découvertes à toi? Et as-tu vu les portes de l’ombre de la mort?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'As-tu compris l’étendue de la terre? Si tu sais tout cela, dis-le!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Où est le chemin du séjour de la lumière? Et les ténèbres, où est leur demeure?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Car tu peux les ramener à leur domaine, et tu connais les sentiers de leur maison!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Tu le sais; car alors tu étais né, et le nombre de tes jours est grand!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'As-tu pénétré jusqu’aux trésors de neige? Et as-tu vu les trésors de grêle,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'Que je réserve pour les temps de détresse, pour le jour de la bataille et du combat?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Par quels chemins se partage la lumière, et le vent d’orient se répand-il sur la terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Qui a donné à l’averse ses canaux, et sa voie à l’éclair des tonnerres,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'Pour faire pleuvoir sur une terre sans habitants, sur un désert sans hommes,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'Pour abreuver des lieux déserts et désolés, et faire germer et sortir l’herbe?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'La pluie a-t-elle un père? Ou, qui enfante les gouttes de rosée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'De quel sein est sortie la glace? Et qui enfante le givre du ciel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Les eaux se dissimulent, changées en pierre, et la surface de l’abîme se prend.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Peux-tu resserrer les liens des Pléiades, ou détacher les chaînes d’Orion?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Fais-tu sortir en leur temps les signes du zodiaque? Et conduis-tu la grande Ourse avec ses petits?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Connais-tu les lois du ciel? Ou disposes-tu de son pouvoir sur la terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Élèves-tu ta voix vers la nuée, pour que des eaux abondantes te couvrent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Envoies-tu les éclairs? Partent-ils, et te disent-ils: Nous voici?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Qui a mis la sagesse dans les nues, qui a donné au météore l’intelligence?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Qui compte les nuages avec sagesse, qui incline les outres des cieux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'Quand la poussière se délaie et se met en fusion, et que les mottes s’agglomèrent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Chasses-tu pour le lion sa proie, et assouvis-tu la faim des lionceaux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Quand ils se tapissent dans leurs repaires, quand ils sont aux aguets dans les fourrés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Qui apprête la nourriture au corbeau, quand ses petits crient vers Dieu et volent çà et là, n’ayant rien à manger?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Sais-tu le temps où les chamois mettent bas? As-tu observé quand les biches faonnent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'As-tu compté les mois de leur portée, et sais-tu le temps où elles mettent bas?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'Elles se courbent, elles font sortir leurs petits, et se délivrent de leurs douleurs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Leurs petits se fortifient, ils croissent en plein air, ils s’en vont et ne reviennent plus vers elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Qui a lâché l’onagre en liberté, et qui a délié les liens de cet animal farouche,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'A qui j’ai donné la steppe pour demeure, et la terre salée pour habitation?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Il se rit du bruit de la ville; il n’entend pas les clameurs de l’ânier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Il parcourt les montagnes qui sont ses pâturages, il cherche partout de la verdure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Le buffle veut-il te servir? Passe-t-il la nuit auprès de ta crèche?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Attaches-tu le buffle par la corde au sillon? Herse-t-il tes champs en te suivant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Te fies-tu à lui parce que sa force est grande, et lui abandonnes- tu ton travail?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Comptes-tu sur lui pour rentrer ton grain, et pour l’amasser sur ton aire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'L’aile de l’autruche s’agite joyeusement; est-ce l’aile et la plume de la cigogne?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Non, car elle abandonne ses œufs à terre, elle les fait couver sur la poussière;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Elle oublie qu’un pied peut les fouler, une bête des champs les écraser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Elle est dure envers ses petits, comme s’ils n’étaient pas siens. Son travail est vain, elle ne s’en inquiète pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Car Dieu l’a privée de sagesse, et ne lui a point départi d’intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Quand elle se lève, et bat des ailes, elle se moque du cheval et de son cavalier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'As-tu donné au cheval sa vigueur? As-tu revêtu son cou de la crinière frémissante?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Le fais-tu bondir comme la sauterelle? Son fier hennissement donne la terreur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'De son pied il creuse la terre; il se réjouit en sa force; il va à la rencontre de l’homme armé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Il se rit de la crainte, il n’a peur de rien; il ne recule point devant l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Sur lui retentit le carquois, la lance étincelante et le javelot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Bondissant et frémissant, il dévore l’espace; il ne peut se contenir dès que la trompette sonne;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Dès qu’il entend la trompette, il hennit; il sent de loin la bataille, la voix tonnante des chefs et les clameurs des guerriers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Est-ce par ta sagesse que l’épervier prend son vol, et déploie ses ailes vers le Midi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Est-ce sur ton ordre que l’aigle s’élève, et qu’il place son aire sur les hauteurs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 31, 'Il habite sur les rochers, il se tient sur la dent des rochers, sur les lieux inaccessibles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 32, 'De là, il découvre sa proie; ses yeux la voient de loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 33, 'Ses petits sucent le sang, et partout où il y a des corps morts, il s’y trouve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 34, 'L’Éternel adressa la parole à Job, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 35, 'Le censeur contestera-t-il avec le Tout-Puissant? L’accusateur de Dieu répondra-t-il à cela?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 36, 'Alors Job répondit à l’Éternel et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 37, 'Je suis trop peu de chose; que te répondrais-je? Je mets ma main sur ma bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 38, 'J’ai parlé une fois, et je ne répondrai plus. J’ai parlé deux fois, et je n’y retournerai plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Et l’Éternel répondit à Job du sein de la tempête, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Ceins tes reins, comme un vaillant homme; je t’interrogerai, et tu m’instruiras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Est-ce que tu voudrais anéantir ma justice? me condamner pour te justifier?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'As-tu un bras comme celui de Dieu; tonnes-tu de la voix, comme lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Pare-toi donc de magnificence et de grandeur; et revêts-toi de majesté et de gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Répands les fureurs de ta colère, d’un regard humilie tous les orgueilleux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'D’un regard abaisse tous les orgueilleux, et écrase les méchants sur place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Cache-les tous ensemble dans la poussière, et enferme leurs visages dans les ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Alors, moi aussi, je te louerai, car ta main t’aura aidé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Vois donc le Béhémoth, que j’ai fait aussi bien que toi; il mange l’herbe comme le bœuf;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Vois donc: sa force est dans ses flancs, et sa vigueur dans les muscles de son ventre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Il remue sa queue semblable au cèdre; les tendons de ses hanches sont entrelacés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Ses os sont des tubes d’airain, ses membres sont comme des barres de fer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'C’est le chef-d’œuvre de Dieu, son créateur lui a donné son épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Les montagnes portent pour lui leur herbe; là se jouent toutes les bêtes des champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Il se couche sous les lotus, dans l’ombre des roseaux et dans le limon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Les lotus le couvrent de leur ombre, et les saules du torrent l’environnent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Vois, le fleuve déborde avec violence, il n’a point peur; il serait tranquille quand le Jourdain monterait à sa gueule.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Qu’on le prenne à force ouverte! Ou qu’à l’aide de filets on lui perce le nez!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Tu tireras le Léviathan avec un hameçon? et tu serreras sa langue avec une corde?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Mettras-tu un jonc dans ses narines, perceras-tu sa joue avec un crochet?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'T’adressera-t-il beaucoup de prières, et te dira-t-il de douces paroles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Fera-t-il un accord avec toi, et le prendras-tu pour esclave à toujours?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'En joueras-tu comme d’un oiseau, et l’attacheras-tu pour amuser tes filles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 25, 'Les associés en feront-ils commerce, le partageront-ils entre des marchands?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 26, 'Perceras-tu sa peau d’un dard, et sa tête d’un harpon?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 27, 'Mets ta main sur lui: tu te souviendras de la bataille, et tu n’y reviendras pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 28, 'Voici, tout espoir de le prendre est trompé; à son seul aspect on est jeté à terre!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Il n’y a point d’homme si hardi qui l’ose réveiller; et qui se tiendra debout devant moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Qui m’a fait des avances, et je lui rendrai? Tout ce qui est sous les cieux est à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Je ne me tairai pas sur ses membres, sur ses forces, et sur la beauté de sa stature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Qui a soulevé le dessus de son vêtement? Qui est entré dans sa double mâchoire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Qui a ouvert les portes de sa gueule? La terreur est autour de ses dents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Ses puissants boucliers sont superbes; ils sont fermés, étroitement scellés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Ils se touchent l’un l’autre, le vent ne passe point entre eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Ils sont adhérents l’un à l’autre; ils se tiennent, ils ne se séparent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Ses éternuements jettent un éclat de lumière, et ses yeux sont comme les paupières de l’aurore.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'De sa bouche sortent des lueurs, et s’échappent des étincelles de feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'De ses narines sort une fumée, comme d’un vase qui bout ou d’une chaudière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Son souffle enflammerait des charbons, et une flamme sort de sa gueule.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Dans son cou réside la force, et la terreur marche devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Les fanons de sa chair sont adhérents; ils sont massifs, inébranlables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Son cœur est massif comme une pierre, massif comme la meule de dessous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Quand il se lève, les plus forts tremblent, ils défaillent d’effroi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Quand on l’approche, l’épée ne sert à rien, ni la lance, ni le dard, ni la cuirasse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Il regarde le fer comme de la paille, et l’airain comme du bois pourri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'La flèche ne le fait pas fuir, les pierres de la fronde sont pour lui comme du chaume;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Comme du chaume, la massue; il se rit du frémissement des javelots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Son ventre a des tessons pointus: il étend une herse sur le limon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Il fait bouillonner le gouffre comme une chaudière, il rend la mer semblable à un vase de parfumeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Il laisse après lui une trace brillante, on dirait sur l’abîme une blanche chevelure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Il n’a pas son pareil sur la terre; il a été fait pour ne rien craindre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Il regarde tout ce qui est élevé; il est roi des plus fiers animaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Alors Job répondit à l’Éternel, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Je sais que tu peux tout, et qu’on ne saurait t’empêcher d’accomplir un dessein.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, '\"Qui obscurcit mes plans sans science? \" J’ai parlé et je ne comprenais pas; ce sont des choses trop merveilleuses pour moi, et je ne les connais point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, '\"Écoute donc et je parlerai; je t’interrogerai et tu m’instruiras. \"');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Mes oreilles avaient entendu parler de toi; mais, maintenant, mon œil t’a vu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'C’est pourquoi je me condamne et je me repens, sur la poussière et sur la cendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Or, après que l’Éternel eut ainsi parlé à Job, il dit à Éliphaz, de Théman: Ma colère est enflammée contre toi et contre tes deux amis, parce que vous n’avez pas parlé avec droiture devant moi, comme Job, mon serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Maintenant, prenez sept taureaux et sept béliers, et allez vers mon serviteur Job, offrez un holocauste pour vous, et Job, mon serviteur, priera pour vous; et par égard pour lui, je ne vous traiterai pas selon votre folie, car vous n’avez pas parlé avec droiture devant moi, comme mon serviteur Job.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Et Éliphaz, de Théman, Bildad, de Shuach, et Tsophar, de Naama, allèrent et firent comme leur avait dit l’Éternel, et l’Éternel eut égard à Job.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Et l’Éternel rétablit Job dans ses biens, quand il eut prié pour ses amis; et il lui rendit au double tout ce qu’il avait eu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Tous ses frères, et toutes ses sœurs, tous ceux qui l’avaient connu auparavant vinrent vers lui, et mangèrent avec lui dans sa maison. Ils lui firent leurs condoléances, et le consolèrent au sujet de tout le mal que l’Éternel avait fait venir sur lui, et chacun lui donna une késita et un anneau d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Ainsi l’Éternel bénit le dernier état de Job plus que le premier; il eut quatorze mille brebis, six mille chameaux, et mille couples de bœufs, et mille ânesses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Il eut sept fils et trois filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'Il donna à la première le nom de Jémima (colombe), à la seconde celui de Ketsia (parfum), à la troisième celui de Kéren-Happuc (flacon de fard).');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Et il ne se trouvait pas de femmes aussi belles que les filles de Job dans tout le pays; et leur père leur donna un héritage avec leurs frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Job vécut, après ces choses, cent quarante ans, et vit ses fils et les fils de ses fils jusqu’à la quatrième génération.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Et il mourut âgé et rassasié de jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Bienheureux est l’homme qui ne vit point selon le conseil des méchants, et qui ne s’arrête point dans la voie des pécheurs, et qui ne s’assied point au banc des moqueurs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Mais qui prend plaisir en la Loi de l’Eternel, et qui médite jour et nuit en sa Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Car il sera comme un arbre planté près des ruisseaux d’eaux, qui rend son fruit en sa saison, et duquel le feuillage ne se flétrit point; et ainsi tout ce qu’il fera prospérera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Il n’en sera pas ainsi des méchants; mais ils seront comme la balle que le vent chasse au loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'C’est pourquoi les méchants ne subsisteront point en jugement, ni les pécheurs dans l’assemblée des justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Car l’Eternel connaît la voie des justes; mais la voie des méchants périra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Pourquoi se mutinent les nations, et pourquoi les peuples projettent-ils des choses vaines?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Les Rois de la terre se trouvent en personne, et les Princes consultent ensemble contre l’Eternel, et contre son Oint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Rompons, disent-ils, leurs liens, et jetons loin de nous leurs cordes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Celui qui habite dans les cieux se rira d’eux; le Seigneur s’en moquera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Alors il leur parlera en sa colère, et il les remplira de terreur par la grandeur de son courroux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Et moi, dira-t-il, j’ai sacré mon Roi sur Sion, la montagne de ma Sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Je vous réciterai quel a été ce sacre; l’Eternel m’a dit: tu es mon Fils, je t’ai aujourd’hui engendré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Demande-moi, et je te donnerai pour ton héritage les nations, et pour ta possession les bouts de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Tu les briseras avec un sceptre de fer, et tu les mettras en pièces comme un vaisseau de potier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Maintenant donc, ô Rois! ayez de l’intelligence; Juges de la terre, recevez instruction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Servez l’Eternel avec crainte, et égayez-vous avec tremblement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Baisez le Fils, de peur qu’il ne s’irrite, et que vous ne périssiez dans cette conduite, quand sa colère s’embrasera tant soit peu. Ô que bienheureux sont tous ceux qui se confient en lui!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Psaume de David au sujet de sa fuite de devant Absalom son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Ô Eternel! Combien sont multipliés ceux qui me pressent! beaucoup de gens s’élèvent contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Plusieurs disent de mon âme: il n’y a point en Dieu de délivrance pour lui. Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Mais toi, ô Eternel! tu es un bouclier autour de moi, tu es ma gloire, et tu es celui qui me fais lever la tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'J’ai crié de ma voix à l’Eternel, et il m’a répondu de la montagne de sa sainteté. Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Je me suis couché, je me suis endormi, je me suis réveillé; car l’Eternel me soutient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Je ne craindrai point plusieurs milliers de peuples, quand ils se rangeraient contre moi tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Lève-toi, Eternel mon Dieu! délivre-moi. Certainement tu as frappé en la joue tous mes ennemis; tu as cassé les dents des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 9, 'La délivrance vient de l’Eternel; ta bénédiction est sur ton peuple. Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Psaume de David, donné au maître chantre, pour le chanter sur Néguinoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Ô Dieu! de ma justice, puisque je crie, réponds-moi; quand j’étais à l’étroit, tu m’as mis au large; aie pitié de moi, et exauce ma requête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Gens d’autorité, jusqu’à quand ma gloire sera-t-elle diffamée? jusqu’à quand aimerez-vous la vanité, et chercherez-vous le mensonge? Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Or sachez que l’Eternel s’est choisi un bien-aimé. L’Eternel m’exaucera quand je crierai vers lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Tremblez, et ne péchez point; pensez en vous-mêmes sur votre couche, et demeurez tranquilles. Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Sacrifiez des sacrifices de justice, et confiez-vous en l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Plusieurs disent: qui nous fera voir des biens? Lève sur nous la clarté de ta face, ô Eternel!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Tu as mis plus de joie dans mon coeur, qu’ils n’en ont au temps que leur froment et leur meilleur vin ont été abondants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 9, 'Je me coucherai et je dormirai aussi en paix; car toi seul, ô Eternel! me feras habiter en assurance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Psaume de David, donné au maître chantre, pour le chanter sur Néhiloth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Eternel! prête l’oreille à mes paroles, entends ma méditation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Mon Roi et mon Dieu! sois attentif à la voix de mon cri; car c’est à toi que j’adresse ma requête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Eternel, entends dès le matin ma voix; dès le matin je me tournerai vers toi, et je serai au guet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Car tu n’es point un Dieu qui prennes plaisir à la méchanceté; le méchant ne séjournera point chez toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Les orgueilleux ne subsisteront point devant toi; tu as toujours haï tous les ouvriers d’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Tu feras périr ceux qui profèrent le mensonge; l’Eternel a en abomination l’homme sanguinaire et le trompeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Mais moi comblé de tes bienfaits j’entrerai dans ta maison; je me prosternerai dans le palais de ta sainteté avec les sentiments d’une crainte respectueuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Eternel, conduis-moi par ta justice, à cause de mes ennemis; dresse ta voie devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Car il n’y a rien de droit en sa bouche, leur intérieur n’est que malice; leur gosier est un sépulcre ouvert, ils flattent de leur langue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Ô Dieu! fais-leur leur procès, et qu’ils échouent dans leurs entreprises; chasse-les au loin, à cause du grand nombre de leurs transgressions; car ils se sont rebellés contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Mais que tous ceux qui se confient en toi, se réjouissent, qu’ils soient en joie perpétuellement, et que tu sois leur protecteur; et que ceux qui aiment ton Nom, s’égayent en toi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 13, 'Car, ô Eternel! tu béniras le juste, et tu l’environneras de bienveillance comme d’un bouclier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Psaume de David, donné au maître chantre, pour le chanter en Néguinoth, sur Séminith.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Eternel! ne me reprends point en ta colère, et ne me châtie point en ta fureur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Eternel, aie pitié de moi, car je suis sans aucune force; guéris-moi, ô Eternel! car mes os sont épouvantés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Même mon âme est fort troublée; et toi, ô Eternel! jusques à quand?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Eternel! retourne-toi, garantis mon âme, délivre-moi pour l’amour de ta gratuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Car il n’est point fait mention de toi en la mort; et qui est-ce qui te célébrera dans le sépulcre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Je me suis épuisé à force de soupirer; je baigne mon lit toutes les nuits, je le trempe de mes larmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Mon regard est tout défait de chagrin, il est envieilli à cause de tous ceux qui me pressent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Retirez-vous loin de moi, vous tous ouvriers d’iniquité, car l’Eternel a entendu la voix de mes pleurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'L’Eternel a entendu ma supplication, l’Eternel a reçu ma requête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 11, 'Tous mes ennemis seront honteux et épouvantés; ils s’en retourneront, ils seront confus en un moment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Siggajon de David, qu’il chanta à l’Eternel touchant l’affaire de Cus Benjamite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Eternel mon Dieu! je me suis retiré vers toi; délivre-moi de tous ceux qui me poursuivent, et garantis-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'De peur qu’il ne me déchire comme un lion, me mettant en pièces, sans qu’il y ait personne qui me délivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Eternel mon Dieu! si j’ai commis une telle action, s’il y a de l’iniquité dans mes mains;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'Si j’ai récompensé de mal celui qui avait la paix avec moi, et si je n’ai pas garanti celui qui m’opprimait à tort;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Que l’ennemi me poursuive, et qu’il m’atteigne; qu’il foule ma vie en terre, et qu’il loge ma gloire dans la poudre! Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Lève-toi, ô Eternel! en ta colère, parais pour arrêter les fureurs de mes ennemis, et te réveille pour moi; tu as ordonné le droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Que l’assemblée des peuples t’environne, et toi tourne-toi vers elle en un lieu éminent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Que l’Eternel juge les peuples; fais moi droit, ô Eternel! selon ma justice, et selon mon intégrité, qui est en moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Que la malice des méchants prenne fin, et affermis le juste, toi, dis-je, qui sondes les coeurs et les reins; ô Dieu juste!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Mon bouclier est en Dieu, qui délivre ceux qui sont droits de coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Dieu fait droit au juste, et le Dieu Fort s’irrite tous les jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Si le méchant ne se convertit, Dieu aiguisera son épée; il a bandé son arc et l’a ajusté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Et il a préparé contre lui des armes mortelles; il mettra en oeuvre ses flèches contre les ardents persécuteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Voici le méchant travaille pour enfanter l’outrage, et il a conçu le travail: mais il enfantera une chose qui le trompera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Il a fait une fosse, il l’a creusée: mais il est tombé dans la fosse qu’il a faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Son travail retournera sur sa tête, et sa violence lui descendra sur le sommet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 18, 'Je célébrerai l’Eternel selon sa justice, et je psalmodierai le Nom de l’Eternel souverain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Psaume de David, donné au maître chantre, pour le chanter sur Guittith.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Eternel notre Seigneur! que ton Nom est magnifique par toute la terre, vu que tu as mis ta Majesté au-dessus des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'De la bouche des petits enfants, et de ceux qui tètent, tu as fondé ta force, à cause de tes adversaires; afin de faire cesser l’ennemi et le vindicatif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Quand je regarde tes cieux, l’ouvrage de tes doigts, la lune et les étoiles que tu as arrangées,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Je dis: qu’est-ce que de l’homme, que tu te souviennes de lui; et du fils de l’homme, que tu le visites?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Car tu l’as fait un peu moindre que les Anges, et tu l’as couronné de gloire et d’honneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Tu l’as fait Seigneur des oeuvres de tes mains; tu as mis toutes choses sous ses pieds,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Les brebis et les boeufs sans réserve, même les bêtes des champs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Les oiseaux des cieux, et les poissons de la mer, ce qui traverse par les sentiers de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 10, 'Eternel notre Seigneur! que ton Nom est magnifique par toute la terre!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Psaume de David, donné au maître chantre, pour le chanter sur Muth-Labben.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Je célébrerai de tout mon coeur l’Eternel; je raconterai toutes tes merveilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Je me réjouirai et je m’égayerai en toi; je psalmodierai ton Nom, ô Souverain!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Parce que mes ennemis sont retournés en arrière; ils sont tombés, et ils ont péri de devant ta face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Car tu m’as fait droit et justice; tu t’es assis sur le trône, toi juste juge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Tu as réprimé fortement les nations, tu as fait périr le méchant, tu as effacé leur nom pour toujours, et à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Ô ennemi! les désolations ont-elles pris fin? as-tu aussi rasé les villes pour jamais? leur mémoire est-elle périe avec elles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Mais l’Eternel sera assis éternellement; il a préparé son trône pour juger;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Et il jugera le monde avec justice, et fera droit aux peuples avec équité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Et l’Eternel sera une haute retraite à celui qui sera foulé, il lui sera une haute retraite au temps qu’il sera dans l’angoisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Et ceux qui connaissent ton Nom, s’assureront sur toi: car, ô Eternel! tu n’abandonnes point ceux qui te cherchent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Psalmodiez à l’Eternel qui habite en Sion; annoncez ses exploits parmi les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Car il recherche les meurtres, et il s’en souvient; il n’oublie point le cri des débonnaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Eternel! aie pitié de moi; regarde mon affliction causée par ceux qui me haïssent, toi qui me retires des portes de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Afin que je raconte toutes tes louanges dans les portes de la fille de Sion. Je me réjouirai de la délivrance que tu m’auras donnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Les nations ont été enfoncées dans la fosse qu’elles avaient faite; leur pied a été pris au filet qu’elles avaient caché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'L’Eternel s’est fait connaître; il a fait jugement; le méchant est enlacé dans l’ouvrage de ses mains. Higgajon, Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Les méchants retourneront vers le sépulcre, toutes les nations, dis-je, qui oublient Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Car le pauvre ne sera point oublié à jamais, et l’attente des affligés ne périra point à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Lève-toi, ô Eternel! et que l’homme mortel ne se renforce point! que la vengeance soit faite des nations devant ta face!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 21, 'Eternel, remplis-les de frayeur; et que les nations sachent qu’elles ne sont que des hommes mortels. Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Pourquoi, ô Eternel! te tiens-tu loin, et te caches-tu au temps que nous sommes dans la détresse?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Le méchant par son orgueil poursuit ardemment l’affligé; mais ils seront pris par les machinations qu’ils ont préméditées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Car le méchant se glorifie du souhait de son âme, il estime heureux l’avare, et il irrite l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Le méchant marchant avec fierté ne fait conscience de rien; toutes ses pensées sont, qu’il n’y a point de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Son train prospère en tout temps; tes jugements sont éloignés de devant lui; il souffle contre tous ses adversaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Il dit en son coeur: je ne serai jamais ébranlé; car je ne puis avoir de mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Sa bouche est pleine de malédictions, de tromperies, et de fraude; il n’y a sous sa langue qu’oppression et qu’outrage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Il se tient aux embûches dans des villages; il tue l’innocent dans des lieux cachés; ses yeux épient le troupeau des désolés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Il se tient aux embûches en un lieu caché, comme un lion dans son fort; il se tient aux embûches pour attraper l’affligé; il attrape l’affligé, l’attirant en son filet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Il se tapit, et se baisse, et puis le troupeau des désolés tombe entre ses bras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Il dit en son coeur: le Dieu Fort l’a oublié, il a caché sa face, il ne le verra jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Eternel, lève-toi, ô Dieu Fort! hausse ta main, et n’oublie point les débonnaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Pourquoi le méchant irriterait-il Dieu? Il a dit en son coeur que tu n’en feras aucune recherche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Tu l’as vu; car lorsqu’on afflige ou qu’on maltraite quelqu’un, tu regardes pour le mettre entre tes mains, le troupeau des désolés se réfugie auprès de toi; tu as aidé l’orphelin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Casse le bras du méchant, et recherche la méchanceté de l’injuste, jusqu’à ce que tu n’en trouves plus rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'L’Eternel est Roi à toujours, et à perpétuité; les nations ont été exterminées de dessus sa terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Eternel, tu exauces le souhait des débonnaires, affermis leur coeur, et que ton oreille les écoute attentivement;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Pour faire droit à l’orphelin et à celui qui est foulé, afin que l’homme mortel, qui est de terre, ne continue plus à donner de l’effroi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Psaume de David, donné au maître chantre. Je me suis retiré vers l’Eternel; comment donc dites-vous à mon âme: Fuis- t’en en votre montagne, oiseau?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'En effet, les méchants bandent l’arc, ils ont ajusté leur flèche sur la corde, pour tirer en secret contre ceux qui sont droits de coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Puisque les fondements sont ruinés, que fera le juste?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'L’Eternel est au palais de sa Sainteté; l’Eternel a son Trône aux cieux; ses yeux contemplent, et ses paupières sondent les fils des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'L’Eternel sonde le juste et le méchant; et son âme hait celui qui aime la violence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Il fera pleuvoir sur les méchants des filets, du feu, et du souffre; et un vent de tempête sera la portion de leur breuvage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Car l’Eternel juste aime la justice, ses yeux contemplent l’homme droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Psaume de David, donné au maître chantre, pour le chanter sur Seminith.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Délivre, ô Eternel! parce que l’homme de bien ne se voit plus, et que les véritables ont disparu entre les fils des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Chacun dit la fausseté à son compagnon avec des lèvres flatteuses, et ils parlent avec un coeur double.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'L’Eternel veuille retrancher toutes les lèvres flatteuses, et la langue qui parle fièrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Parce qu’ils disent: nous aurons le dessus par nos langues; nos lèvres sont en notre puissance; qui sera Seigneur sur nous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'A cause du mauvais traitement que l’on fait aux affligés, à cause du gémissement des pauvres, je me lèverai maintenant, dit l’Eternel, je mettrai en sûreté celui à qui l’on tend des pièges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Les paroles de l’Eternel sont des paroles pures, c’est un argent affiné au fourneau de terre, épuré par sept fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Toi, Eternel! gardes-les, et préserve à jamais chacun d’eux de cette race de gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 9, 'Car les méchants se promènent de toutes parts, tandis que des gens abjects sont élevés entre les fils des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Psaume de David, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Eternel, jusques à quand m’oublieras-tu? Sera-ce pour toujours? jusques à quand cacheras-tu ta face de moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Jusques à quand consulterai-je en moi-même, et affligerai-je mon coeur durant le jour? Jusques à quand s’élèvera mon ennemi contre moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Eternel mon Dieu! regarde, exauce-moi, illumine mes yeux, de peur que je ne dorme du sommeil de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'De peur que mon ennemi ne dise: j’ai eu le dessus; que mes adversaires ne se réjouissent si je venais à tomber.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Mais moi, je me confie en ta gratuité, mon coeur se réjouira de la délivrance que tu m’auras donnée; je chanterai à l’Eternel de ce qu’il m’aura fait ce bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Psaume de David, donné au maître chantre. L’insensé a dit en son coeur: il n’y a point de Dieu. Ils se sont corrompus, ils se sont rendus abominables en leurs actions; il n’y a personne qui fasse le bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'L’Eternel a regardé des cieux sur les fils des hommes, pour voir s’il y en a quelqu’un qui soit intelligent, et qui cherche Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Ils se sont tous égarés, ils se sont tous ensemble rendus odieux, il n’y a personne qui fasse le bien, non pas même un seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Tous ces ouvriers d’iniquité n’ont-ils point de connaissance? Ils mangent mon peuple comme s’ils mangeaient du pain, ils n’invoquent point l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Là ils seront saisis d’une grande frayeur; car Dieu est avec la race juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Vous faites honte à l’affligé de ce qu’il s’est proposé l’Eternel pour sa retraite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Ô! qui donnera de Sion la délivrance d’Israël! Quand l’Eternel aura ramené son peuple captif, Jacob s’égaiera, Israël se réjouira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Psaume de David. Eternel, qui est-ce qui séjournera dans ton Tabernacle? qui est-ce qui habitera en la montagne de ta Sainteté?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Ce sera celui qui marche dans l’intégrité, qui fait ce qui est juste, et qui profère la vérité telle qu’elle est dans son cœur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Qui ne médit point par sa langue, qui ne fait point de mal à son ami, qui ne diffame point son prochain;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Aux yeux duquel est méprisable celui qui mérite d’être rejeté, mais il honore ceux qui craignent l’Eternel; s’il a juré, fût-ce à son dommage, il n’en changera rien;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Qui ne donne point son argent à usure, et qui ne prend point de présent contre l’innocent; celui qui fait ces choses, ne sera jamais ébranlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Mictam de David. Garde-moi, ô Dieu Fort! car je me suis confié en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Mon âme! tu as dit à l’Eternel: Tu es le Seigneur, mon bien ne va pas jusqu’à toi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Mais aux Saints qui sont en la terre, et à ces personnes distinguées, en qui je prends tout mon plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Les angoisses de ceux qui courent après un autre, seront multipliées. Je ne ferai point leurs aspersions de sang, et leur nom ne passera point par ma bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'L’Eternel est la part de mon héritage, et de mon breuvage; tu maintiens mon lot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Les cordeaux me sont échus en des lieux agréables, et un très bel héritage m’a été accordé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Je bénirai l’Eternel, qui me donne conseil, je le bénirai même durant les nuits dans lesquelles mes reins m’enseignent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Je me suis toujours proposé l’Eternel devant moi; et puisqu’il est à ma droite, je ne serai point ébranlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'C’est pourquoi mon coeur s’est réjoui, et ma langue s’est égayée; aussi ma chair habitera avec assurance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Car tu n’abandonneras point mon âme au sépulcre, et tu ne permettras point que ton bien-aimé sente la corruption.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Tu me feras connaître le chemin de la vie; ta face est un rassasiement de joie; il y a des plaisirs à ta droite pour jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Requête de David. Eternel! écoute ma juste cause, sois attentif à mon cri, prête l’oreille à ma requête, laquelle je te fais sans qu’il y ait de fraude en mes lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Que mon droit sorte de ta présence, que tes yeux regardent à la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Tu as sondé mon coeur, tu l’ as visité de nuit, tu m’as examiné, tu n’as rien trouvé; ma pensée ne va point au-delà de ma parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Quant aux actions des hommes, selon la parole de tes lèvres, je me suis donné garde de la conduite de l’homme violent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Ayant affermi mes pas en tes sentiers, les plantes de mes pieds n’ont point chancelé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Ô Dieu Fort! je t’invoque, parce que tu as accoutumé de m’exaucer; incline ton oreille vers moi, écoute mes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Rends admirables tes gratuités, toi qui délivres ceux qui se retirent vers toi de devant ceux qui s’élèvent contre ta droite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Garde-moi comme la prunelle de l’oeil, et me cache sous l’ombre de tes ailes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'De devant ces méchants qui m’ont pillé; et de mes ennemis mortels, qui m’environnent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'La graisse leur cache le visage; ils parlent fièrement de leur bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Maintenant, ils nous environnent à chaque pas que nous faisons; ils jettent leur regard pour nous étendre par terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Il ressemble au lion qui ne demande qu’à déchirer, et au lionceau qui se tient dans les lieux cachés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Lève-toi, ô Eternel, devance-le, renverse-le; délivre mon âme du méchant par ton épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'Eternel, délivre-moi par ta main de ces gens, des gens du monde, desquels le partage est en cette vie, et dont tu remplis le ventre de tes provisions; leurs enfants sont rassasiés, et ils laissent leurs restes à leurs petits enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Mais moi, je verrai ta face en justice, et je serai rassasié de ta ressemblance, quand je serai réveillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Psaume de David, serviteur de l’Eternel, qui prononça à l’Eternel les paroles de ce Cantique le jour que l’Eternel l’eut délivré de la main de Saül. Donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Il dit donc: Eternel! qui es ma force, je t’aimerai d’une affection cordiale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'L’Eternel est ma roche, et ma forteresse, et mon libérateur; mon Dieu Fort est mon rocher, je me confierai en lui; il est mon bouclier, et la corne de mon salut, ma haute retraite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Je crierai à l’Eternel, lequel on doit louer; et je serai délivré de mes ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Les cordeaux de la mort m’avaient environné, et des torrents des méchants m’avaient épouvanté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'Les cordeaux du sépulcre m’avaient ceint, les filets de la mort m’avaient surpris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Quand j’ai été en adversité, j’ai crié à l’Eternel, j’ai, dis-je, crié à mon Dieu; il a ouï ma voix de son palais; le cri que j’ai jeté devant lui, est parvenu à ses oreilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Alors la terre fut ébranlée, et trembla; et les fondements des montagnes croulèrent, et furent ébranlés, parce qu’il était irrité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Une fumée montait de ses narines, et de sa bouche sortait un feu dévorant, des charbons en étaient embrasés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Il abaissa donc les cieux, et descendit, ayant une obscurité sous ses pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Il était monté sur un Chérubin, et il volait; il était porté sur les ailes du vent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Il mit les ténèbres pour sa demeure secrète: et autour de lui était son Tabernacle, savoir les ténèbres d’eaux, qui sont les nuées de l’air.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'De la lueur qui était au-devant de lui ses nuées furent écartées, et il y avait de la grêle, et des charbons de feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Et l’Eternel tonna dans les cieux, et le Souverain fit retentir sa voix avec de la grêle et des charbons de feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Il tira ses flèches, et écarta mes ennemis; il lança des éclairs, et les mit en déroute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Alors le fond des eaux parut, et les fondements de la terre habitable furent découverts, à cause que tu les tançais, ô Eternel! par le souffle du vent de tes narines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Il étendit la main d’en haut, il m’enleva, et me tira des grosses eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Il me délivra de mon puissant ennemi, et de ceux qui me haïssaient, car ils étaient plus forts que moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Ils m’avaient devancé au jour de ma calamité; mais l’Eternel me fut pour appui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Il m’a fait sortir au large; il m’a délivré, parce qu’il a pris son plaisir en moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'L’Eternel m’a rendu selon ma justice, il m’a traité selon la pureté de mes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Parce que j’ai tenu le chemin de l’Eternel, et que je ne me suis point détourné de mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Car j’ai eu devant moi tous ses commandements, et je n’ai point rejeté loin de moi ses ordonnances.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'J’ai été intègre envers lui, et je me suis donné garde de mon iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'L’Eternel donc m’a rendu selon ma justice, et selon la pureté de mes mains, qu’il a connue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Envers celui qui use de gratuité tu uses de gratuité, et envers l’homme entier tu te montres entier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Envers celui qui est pur tu te montres pur: mais envers le pervers tu agis selon sa perversité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Car tu sauves le peuple affligé, et tu abaisses les yeux hautains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Même c’est toi qui fais luire ma lampe; l’Eternel mon Dieu fera reluire mes ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Même par ton moyen je me jetterai sur toute une troupe, et par le moyen de mon Dieu je franchirai la muraille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'La voie du Dieu Fort est pure; la parole de l’Eternel est affinée: c’est un bouclier à tous ceux qui se confient en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Car qui est Dieu sinon l’Eternel? et qui est Rocher sinon notre Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'C’est le Dieu Fort qui me ceint de force, et qui rend mon chemin uni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Il a rendu mes pieds égaux à ceux des biches, et il m’a fait tenir debout sur mes lieux haut élevés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'C’est lui qui a dressé mes mains au combat, tellement qu’un arc d’airain a été rompu avec mes bras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Tu m’as aussi donné le bouclier de ta protection, et ta droite m’a soutenu, et ta débonnaireté m’a fait devenir fort grand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Tu m’as fait marcher au large, et mes talons n’ont point glissé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'J’ai poursuivi mes ennemis, je les ai atteints, et je ne m’en suis point retourné jusqu’à ce que je les eusse consumés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Je les ai transpercés, tellement qu’ils n’ont point pu se relever: ils sont tombés à mes pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Car tu m’as ceint de force pour le combat; tu as courbé sous moi ceux qui s’élevaient contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Tu as fait aussi que mes ennemis ont tourné le dos devant moi, et j’ai détruit ceux qui me haïssaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Ils criaient, mais il n’y avait point de libérateur; ils criaient vers l’Eternel, mais il ne leur a point répondu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Et je les ai brisés menu comme la poussière qui est dispersée par le vent, et je les ai foulés comme la boue des rues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Tu m’as fait échapper aux séditions du peuple; tu m’as établi Chef des nations; le peuple que je ne connaissais point, m’a été asservi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Aussitôt qu’ils ont ouï parler de moi ils se sont rendus obéissants; les étrangers m’ont caché leurs pensées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Les étrangers se sont enfuis, et ils ont tremblé de peur dans leurs retraites cachées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'L’Eternel est vivant, et mon rocher est béni; que donc le Dieu de ma délivrance soit exalté!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Le Dieu Fort est celui qui me donne les moyens de me venger, et qui a rangé les peuples sous moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'C’est lui qui m’a délivré de mes ennemis; même tu m’enlèves d’entre ceux qui s’élèvent contre moi, tu me délivres de l’homme violent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'C’est pourquoi, ô Eternel! je te célébrerai parmi les nations, et je chanterai des Psaumes à ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 51, 'C’est lui qui délivre magnifiquement son Roi, et qui use de gratuité envers David son Oint, et envers sa postérité à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Psaume de David, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Les cieux racontent la gloire du Dieu Fort, et l’étendue donne à connaître l’ouvrage de ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Un jour fournit en abondance de quoi parler à l’autre jour, et une nuit montre la science à l’autre nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Il n’y a point en eux de langage, il n’y a point de paroles; toutefois leur voix est ouïe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Leur contour couvre toute la terre, et leur voix est allée jusqu’au bout du monde habitable. Il a posé en eux un pavillon pour le soleil;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Tellement qu’il est semblable à un époux sortant de son cabinet nuptial; il s’égaie comme un homme vaillant pour faire sa course.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Son départ est de l’un des bouts des cieux, et son tour se fait sur l’un et sur l’autre bout, et il n’y a rien qui se puisse mettre à couvert de sa chaleur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'La Loi de l’Eternel est parfaite, restaurant l’âme; le témoignage de l’Eternel est assuré, donnant la sagesse au simple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Les commandements de l’Eternel sont droits, ils réjouissent le coeur; le commandement de l’Eternel est pur, et fait que les yeux voient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'La crainte de l’Eternel est pure, permanente à perpétuité; les jugements de l’Eternel ne sont que vérité, et ils se trouvent pareillement justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Ils sont plus désirables que l’or, même que beaucoup de fin or; et plus doux que le miel, même que ce qui distille des rayons de miel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Aussi ton serviteur est rendu éclairé par eux, et il y a un grand salaire à les observer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Qui est-ce qui connaît ses fautes commises par erreur? Purifie-moi de mes fautes cachées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Eloigne aussi ton serviteur des actions commises par fierté, en sorte qu’elles ne dominent point en moi; alors je serai pur, et serai net des grands crimes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 15, 'Que les propos de ma bouche, et la méditation de mon coeur te soient agréables, ô Eternel! mon rocher, et mon Rédempteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Psaume de David, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Que l’Eternel te réponde au jour que tu seras en détresse; que le nom du Dieu de Jacob te mette en une haute retraite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Qu’il envoie ton secours du saint lieu, et qu’il te soutienne de Sion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Qu’il se souvienne de toutes tes oblations, qu’il réduise en cendre ton holocauste; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Qu’il te donne ce que ton coeur désire, et qu’il fasse réussir tes desseins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Nous triompherons de ta délivrance, et nous marcherons à enseignes déployées au Nom de notre Dieu; l’Eternel t’accordera toutes tes demandes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Déjà je connais que l’Eternel a délivré son Oint; il lui répondra des Cieux de sa Sainteté; la délivrance faite par sa droite est avec force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Les uns se vantent de leurs chariots, et les autres de leurs chevaux, mais nous nous glorifierons du Nom de l’Eternel notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Ceux-là ont ployé, et sont tombés; mais nous nous sommes relevés, et soutenus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 10, 'Eternel, délivre. Que le Roi nous réponde au jour que nous crierons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Psaume de David, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Eternel, le Roi se réjouira de ta force, et combien s’égayera-t-il de ta délivrance?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Tu lui as donné le souhait de son coeur, et ne lui as point refusé ce qu’il a proféré de ses lèvres; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Car tu l’as prévenu de bénédictions de biens, et tu as mis sur sa tête une couronne de fin or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Il t’avait demandé la vie, et tu la lui as donnée: même un prolongement de jours à toujours et à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Sa gloire est grande par ta délivrance; tu l’as couvert de majesté et d’honneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Car tu l’as mis pour bénédictions à perpétuité; tu l’as rempli de joie par ta face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Parce que le Roi s’assure en l’Eternel, et en la gratuité du Souverain, il ne sera point ébranlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Ta main trouvera tous tes ennemis; ta droite trouvera tous ceux qui te haïssent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Tu les rendras comme un four de feu au temps de ton courroux; l’Eternel les engloutira en sa colère, et le feu les consumera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Tu feras périr leur fruit de dessus la terre, et leur race d’entre les fils des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Car ils ont intenté du mal contre toi, et ils ont machiné une entreprise dont ils ne pourront pas venir à bout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Parce que tu les mettras en butte, et que tu coucheras tes flèches sur tes cordes contre leurs visages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 14, 'Elève-toi, Eternel, par ta force; et nous chanterons et psalmodierons ta puissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Psaume de David, donné au maître chantre, pour le chanter sur Ajelet- Hassachar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Mon Dieu! mon Dieu! pourquoi m’as-tu abandonné, t’éloignant de ma délivrance, et des paroles de mon rugissement?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Mon Dieu! je crie de jour, mais tu ne réponds point; et de nuit, et je ne cesse point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Toutefois tu es le Saint habitant au milieu des louanges d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Nos pères se sont confiés en toi; ils se sont confiés, et tu les as délivrés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Ils ont crié vers toi, et ils ont été délivrés; ils se sont appuyés sur toi, et ils n’ont point été confus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Mais moi, je suis un ver, et non point un homme, l’opprobre des hommes, et le méprisé du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Tous ceux qui me voient, se moquent de moi; ils me font la moue; ils branlent la tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Il s’abandonne, disent-ils, à l’Eternel; qu’il le délivre, et qu’il le retire, puisqu’il prend son bon plaisir en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Cependant c’est toi qui m’as tiré hors du ventre de ma mère, qui m’as mis en sûreté lorsque j’étais aux mamelles de ma mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'J’ai été mis en ta charge dès la matrice; tu es mon Dieu Fort dès le ventre de ma mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Ne t’éloigne point de moi; car la détresse est près de moi, et il n’y a personne qui me secoure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Plusieurs taureaux m’ont environné; de puissants taureaux de Basan m’ont entouré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Ils ont ouvert leur gueule contre moi, comme un lion déchirant et rugissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Je me suis écoulé comme de l’eau, et tous mes os sont déjoints; mon coeur est comme de la cire, s’étant fondu dans mes entrailles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Ma vigueur est desséchée comme de la brique, et ma langue tient à mon palais, et tu m’as mis dans la poussière de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Car des chiens m’ont environné, une assemblée de méchants m’a entouré; ils ont percé mes mains et mes pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Je compterais tous mes os un par un; ils me contemplent, ils me regardent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Ils partagent entr’eux mes vêtements, et jettent le sort sur ma robe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Toi donc, Eternel! ne t’éloigne point; ma force, hâte-toi de me secourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Délivre ma vie de l’épée, délivre mon unique de la patte du chien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Délivre-moi de la gueule du lion, et réponds-moi en me retirant d’entre les cornes des licornes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Je déclarerai ton Nom à mes frères, je te louerai au milieu de l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Vous qui craignez l’Eternel, louez le; toute la race de Jacob, glorifiez- le; et toute la race d’Israël redoutez-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Car il n’a point méprisé ni dédaigné l’affliction de l’affligé, et n’a point caché sa face arrière de lui; mais quand l’affligé a crié vers lui, il l’a exaucé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Ma louange commencera par toi dans la grande assemblée; je rendrai mes voeux en la présence de ceux qui te craignent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Les débonnaires mangeront, et seront rassasiés; ceux qui cherchent l’Eternel le loueront; votre coeur vivra à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Tous les bouts de la terre s’en souviendront, et ils se convertiront à l’Eternel, et toutes les familles des nations se prosterneront devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Car le règne appartient à l’Eternel, et il domine sur les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Tous les gens de la terre mangeront, et se prosterneront devant lui; tous ceux qui descendent en la poudre s’inclineront, même celui qui ne peut garantir sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'La postérité le servira, et sera consacrée au Seigneur d’âge en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 32, 'Ils viendront, et ils publieront sa justice au peuple qui naîtra, parce qu’il aura fait ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Psaume de David. L’Eternel est mon berger, je n’aurai point de disette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Il me fait reposer dans des parcs herbeux, et me mène le long des eaux paisibles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Il restaure mon âme, et me conduit pour l’amour de son Nom, par des sentiers unis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Même quand je marcherais par la vallée de l’ombre de la mort, je ne craindrais aucun mal; car tu es avec moi; ton bâton et ta houlette sont ceux qui me consolent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Tu dresses la table devant moi, à la vue de ceux qui me serrent; tu as oint ma tête d’huile odoriférante, et ma coupe est comble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Quoi qu’il en soit, les biens et la gratuité m’accompagneront tous les jours de ma vie, et mon habitation sera dans la maison de l’Eternel pour longtemps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Psaume de David. La terre appartient à l’Eternel, avec tout ce qui est en elle, la terre habitable, et ceux qui y habitent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Car il l’a fondée sur les mers, et l’a posée sur les fleuves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Qui est-ce qui montera en la montagne de l’Eternel? et qui est-ce qui demeurera dans le lieu de sa sainteté?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Ce sera l’homme qui a les mains pures et le coeur net, qui n’aspire point de son âme à la fausseté, et qui ne jure point en tromperie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Il recevra bénédiction de l’Eternel, et justice de Dieu son Sauveur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Tels sont ceux qui l’invoquent, ceux qui cherchent ta face en Jacob: Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Portes, élevez vos linteaux, et vous portes éternelles, haussez-vous, et le Roi de gloire entrera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Qui est ce Roi de gloire? C’est l’Eternel fort et puissant, l’Eternel puissant en bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Portes, élevez vos linteaux, élevez-les aussi, vous portes éternelles, et le Roi de gloire entrera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Qui est ce Roi de gloire? L’Eternel des armées; c’est lui qui est le Roi de gloire: Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Psaume de David. Aleph. Eternel, j’élève mon âme à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Mon Dieu, je m’assure en toi, fais que je ne sois point confus, et que mes ennemis ne triomphent point de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Certes, pas un de ceux qui se confient en toi, ne sera confus; ceux qui agissent perfidement sans sujet seront confus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Eternel! fais-moi connaître tes voies, enseigne-moi tes sentiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'He. Vau. Fais-moi marcher selon la vérité, et m’enseigne; car tu es le Dieu de ma délivrance; je m’attends à toi tout le jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Eternel, souviens-toi de tes compassions et de tes gratuités; car elles sont de tout temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Ne te souviens point des péchés de ma jeunesse, ni de mes transgressions; selon ta gratuité souviens-toi de moi, pour l’amour de ta bonté, ô Eternel!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'L’Eternel est bon et droit, c’est pourquoi il enseignera aux pécheurs le chemin qu’ils doivent tenir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Il fera marcher dans la justice les débonnaires, et il leur enseignera sa voie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Tous les sentiers de l’Eternel sont gratuité et vérité à ceux qui gardent son alliance et ses témoignages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Pour l’amour de ton Nom, ô Eternel! tu me pardonneras mon iniquité, quoiqu’elle soit grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Qui est l’homme qui craint l’Eternel? L’Eternel lui enseignera le chemin qu’il doit choisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Son âme logera au milieu des biens, et sa postérité possédera la terre en héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Le secret de l’Eternel est pour ceux qui le craignent, et son alliance pour la leur donner à connaître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Mes yeux sont continuellement sur l’Eternel; car c’est lui qui tirera mes pieds du filet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Tourne ta face vers moi, et aie pitié de moi; car je suis seul, et affligé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Les détresses de mon coeur se sont augmentées; tire-moi hors de mes angoisses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Regarde mon affliction et mon travail, et me pardonne tous mes péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Regarde mes ennemis, car ils sont en grand nombre, et ils me haïssent d’une haine pleine de violence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Garde mon âme, et me délivre; fais que je ne sois point confus; car je me suis retiré vers toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Que l’intégrité et la droiture me gardent; car je me suis attendu à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Ô Dieu! rachète Israël de toutes ses détresses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Psaume de David. Eternel, fais-moi droit, car j’ai marché en mon intégrité, et je me suis confié en l’Eternel; je ne chancellerai point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Eternel, sonde-moi et m’éprouve, examine mes reins et mon coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Car ta gratuité est devant mes yeux, et j’ai marché en ta vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Je ne me suis point assis avec les hommes vains, et je n’ai point fréquenté les gens couverts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'J’ai haï la compagnie des méchants, et je ne hante point les impies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Je lave mes mains dans l’innocence, et je fais le tour de ton autel, ô Eternel!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'Pour éclater en voix d’action de grâces, et pour raconter toutes tes merveilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Eternel, j’aime la demeure de ta maison, et le lieu dans lequel est le pavillon de ta gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'N’assemble point mon âme avec les pécheurs, ni ma vie avec les hommes sanguinaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'Dans les mains desquels il y a de la méchanceté préméditée, et dont la main droite est pleine de présents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Mais moi, je marche en mon intégrité; rachète-moi, et aie pitié de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Mon pied s’est arrêté au chemin uni; je bénirai l’Eternel dans les assemblées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Psaume de David. L’Eternel est ma lumière et ma délivrance; de qui aurai-je peur? l’Eternel est la force de ma vie; de qui aurai-je frayeur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Lorsque les méchants, mes adversaires et mes ennemis, m’ont approché, se jetant sur moi pour manger ma chair, ils ont bronché et sont tombés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Quand toute une armée se camperait contre moi, mon coeur ne craindrait point; s’il s’élève guerre contre moi, j’aurai confiance en ceci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'J’ai demandé une chose à l’Eternel, et je la requerrai encore, c’est que j’habite en la maison de l’Eternel tous les jours de ma vie, pour contempler la présence ravissante de l’Eternel, et pour visiter soigneusement son palais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Car il me cachera dans sa loge au mauvais temps; il me tiendra caché dans le secret de son Tabernacle; il m’élèvera sur un rocher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Même maintenant ma tête s’élèvera par-dessus mes ennemis qui sont à l’entour de moi, et je sacrifierai dans son Tabernacle des sacrifices de cri de réjouissance; je chanterai et psalmodierai à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Eternel! écoute ma voix, je t’invoque; aie pitié de moi, et m’exauce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Mon coeur me dit de ta part: cherchez ma face; je chercherai ta face, ô Eternel!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Ne me cache point ta face, ne rejette point en courroux ton serviteur; tu as été mon aide; ô Dieu de ma délivrance, ne me délaisse point, et ne m’abandonne point!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Quand mon père et ma mère m’auraient abandonné, toutefois l’Eternel me recueillera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Eternel, enseigne-moi ta voie, et me conduis par un sentier uni, à cause de mes ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Ne me livre point au désir de mes adversaires; car de faux témoins, et ceux qui ne soufflent que violence, se sont élevés contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'N’eût été que j’ai cru que je verrais les biens de l’Eternel en la terre des vivants, c’était fait de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Attends-toi à l’Eternel, et demeure ferme, et il fortifiera ton coeur; attends-toi, dis-je, à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Psaume de David. Je crie à toi, ô Eternel! mon rocher, ne te rends point sourd envers moi, de peur que si tu ne me réponds, je ne sois fait semblable à ceux qui descendent en la fosse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Exauce la voix de mes supplications, lorsque je crie à toi, quand j’élève mes mains vers l’Oracle de ta Sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Ne me traîne point avec les méchants, ni avec les ouvriers d’iniquité, qui parlent de paix avec leurs prochains, pendant que la malice est dans leur coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Traite-les selon leurs oeuvres, et selon la malice de leurs actions: traite- les selon l’ouvrage de leurs mains; rends-leur ce qu’ils ont mérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Parce qu’ils ne prennent point garde aux oeuvres de l’Eternel, à l’oeuvre, dis-je, de ses mains; il les ruinera, et ne les édifiera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Béni soit l’Eternel; car il a exaucé la voix de mes supplications.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'L’Eternel est ma force et mon bouclier; mon coeur a eu sa confiance en lui; j’ai été secouru, et mon coeur s’est réjoui; c’est pourquoi je le célébrerai par mon Cantique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'L’Eternel est leur force, et il est la force des délivrances de son Oint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Délivre ton peuple, et bénis ton héritage, nourris-les, et les élève éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Psaume de David. Fils des Princes rendez à l’Eternel, rendez à l’Eternel la gloire et la force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Rendez à l’Eternel la gloire due à son Nom; prosternez-vous devant l’Eternel dans son Sanctuaire magnifique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'La voix de l’Eternel est sur les eaux, le Dieu Fort de gloire fait tonner; l’Eternel est sur les grandes eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'La voix de l’Eternel est forte, la voix de l’Eternel est magnifique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'La voix de l’Eternel brise les cèdres, même l’Eternel brise les cèdres du Liban,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Et les fait sauter comme un veau: il fait sauter le Liban et Sirion, comme un faon de licorne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'La voix de l’Eternel jette des éclats de flamme de feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'La voix de l’Eternel fait trembler le désert, l’Eternel fait trembler le désert de Kadès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'La voix de l’Eternel fait faonner les biches, et découvre les forêts; mais quant à son Palais, chacun l’y glorifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'L’Eternel a présidé sur le déluge; et l’Eternel présidera comme Roi éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'L’Eternel donnera de la force à son peuple; l’Eternel bénira son peuple en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Psaume, qui fut un Cantique de la dédicace de la maison de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Eternel, je t’exalterai, parce que tu m’as délivré et que tu n’as pas réjoui mes ennemis de ma défaite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Eternel mon Dieu, j’ai crié vers toi, et tu m’as guéri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Eternel, tu as fait remonter mon âme du sépulcre; tu m’as rendu la vie, afin que je ne descendisse point en la fosse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Psalmodiez à l’Eternel, vous ses bien-aimés, et célébrez la mémoire de sa Sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Car il n’y a qu’un moment en sa colère, mais il y a toute une vie en sa faveur; la lamentation loge-t-elle le soir chez nous? le chant de triomphe y est le matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Quand j’étais en ma prospérité, je disais: je ne serai jamais ébranlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Eternel, par ta faveur tu avais fait que la force se tenait en ma montagne; as-tu caché ta face? J’ai été tout effrayé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Eternel, j’ai crié à toi, et j’ai présenté ma supplication à l’Eternel, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Quel profit y aura-t-il en mon sang, si je descends dans la fosse? la poudre te célébrera-t-elle? prêchera-t-elle ta vérité?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Eternel, écoute, et aie pitié de moi; Eternel, sois-moi en aide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Tu as changé mon deuil en allégresse; tu as détaché mon sac, et tu m’as ceint de joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 13, 'Afin que ma langue te psalmodie, et ne se taise point. Eternel, mon Dieu! je te célébrerai à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Psaume de David, au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Eternel, je me suis retiré vers toi, fais que je ne sois jamais confus, délivre-moi par ta justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Incline ton oreille vers moi, délivre-moi promptement; sois-moi pour une forte roche et pour une forteresse, afin que je m’y puisse sauver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Car tu es mon rocher et ma forteresse; c’est pourquoi mène-moi et me conduis, pour l’amour de ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Tire-moi hors du filet qu’on m’a tendu en secret, car tu es ma force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Je remets mon esprit en ta main; tu m’as racheté, ô Eternel! le Dieu de la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'J’ai haï ceux qui s’adonnent aux vanités trompeuses; mais moi, je me suis confié en l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Je m’égayerai et me réjouirai de ta gratuité, parce que tu as regardé mon affliction, et que tu as jeté les yeux sur mon âme en ses détresses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Et parce que tu ne m’as point livré entre les mains de l’ennemi, mais as fait tenir debout mes pieds au large.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Eternel, aie pitié de moi, car je suis en détresse; mon regard est tout défait de chagrin, mon âme aussi et mon ventre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Car ma vie est consumée d’ennui, et mes ans à force de soupirer; ma vertu est déchue, à cause de la peine de mon iniquité, et mes os sont consumés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'J’ai été en opprobre à cause de tous mes adversaires, je l’ai même été extrêmement à mes voisins, et en frayeur à ceux de ma connaissance; ceux qui me voient dehors s’enfuient de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'J’ai été mis en oubli dans le coeur des hommes, comme un mort; j’ai été estimé comme un vaisseau de nul usage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Car j’ai ouï les insultes de plusieurs; la frayeur m’a saisi de tous côtés, quand ils consultaient ensemble contre moi. Ils ont machiné de m’ôter la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Toutefois, ô Eternel! je me suis confié en toi; j’ai dit: Tu es mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Mes temps sont en ta main, délivre-moi de la main de mes ennemis, et de ceux qui me poursuivent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Fais luire ta face sur ton serviteur, délivre-moi par ta gratuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Eternel! que je ne sois point confus, puisque je t’ai invoqué; que les méchants soient confus, qu’ils soient couchés dans le sépulcre!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Que les lèvres menteuses soient muettes, lesquelles profèrent des paroles dures contre le juste, avec orgueil et avec mépris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Ô! que tes biens sont grands, lesquels tu as réservés pour ceux qui te craignent, et que tu as faits en la présence des fils des hommes, à ceux qui se retirent vers toi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Tu les caches dans le lieu secret où tu habites loin de l’orgueil des hommes; tu les préserves en une loge à couvert des disputes des langues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Béni soit l’Eternel, de ce qu’il a rendu admirable sa gratuité envers moi, comme si j’eusse été en une place forte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Je disais en ma précipitation: je suis retranché de devant tes yeux; et néanmoins tu as exaucé la voix de mes supplications, quand j’ai crié à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Aimez l’Eternel vous tous ses bien-aimés; l’Eternel garde les fidèles, et il punit sévèrement celui qui agit avec fierté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 25, 'Vous tous qui avez votre attente à l’Eternel, demeurez fermes, et il fortifiera votre coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Maskil de David. Ô! Que bienheureux est celui de qui la transgression est pardonnée, et dont le péché est couvert!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Ô que bienheureux est l’homme à qui l’Eternel n’impute point son iniquité, et dans l’esprit duquel il n’y a point de fraude!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Quand je me suis tu, mes os se sont consumés; et aussi quand je n’ai fait que rugir tout le jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Parce que jour et nuit ta main s’appesantissait sur moi, ma vigueur s’est changée en une sécheresse d’Eté. Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Je t’ai fait connaître mon péché, et je n’ai point caché mon iniquité. J’ai dit: Je ferai confession de mes transgressions à l’Eternel; et tu as ôté la peine de mon péché. Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'C’est pourquoi tout bien-aimé de toi te suppliera au temps qu’on te trouve, tellement qu’en un déluge de grandes eaux, elles ne l’atteindront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Tu es mon asile, tu me gardes de détresse; tu m’environnes de chants de triomphe à cause de la délivrance. Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Je te rendrai avisé, je t’enseignerai le chemin dans lequel tu dois marcher, et je te guiderai de mon oeil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Ne soyez point comme le cheval, ni comme le mulet, qui sont sans intelligence, desquels il faut emmuseler la bouche avec un mors et un frein, de peur qu’ils n’approchent de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Plusieurs douleurs atteindront le méchant; mais la gratuité environnera l’homme qui se confie en l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Vous justes, réjouissez-vous en l’Eternel, égayez-vous, et chantez de joie vous tous qui êtes droits de coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Vous justes, chantez de joie à cause de l’Eternel; sa louange est bienséante aux hommes droits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Célébrez l’Eternel avec le violon, chantez-lui des Psaumes avec la musette, et l’instrument à dix cordes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Chantez-lui un nouveau Cantique, touchez adroitement vos instruments de musique avec un cri de réjouissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Car la parole de l’Eternel est pure, et toutes ses oeuvres sont avec fermeté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Il aime la justice et la droiture; la terre est remplie de la gratuité de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Les cieux ont été faits par la parole de l’Eternel, et toute leur armée par le souffle de sa bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Il assemble les eaux de la mer comme en un monceau, il met les abîmes comme dans des céliers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Que toute la terre craigne l’Eternel, que tous les habitants de la terre habitable le redoutent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Car il a dit, et ce qu’il a dit a eu son être, il a commandé, et la chose a comparu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'L’Eternel dissipe le conseil des nations, il anéantit les desseins des peuples;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Mais le conseil de l’Eternel se soutient à toujours; les desseins de son coeur subsistent d’âge en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Ô! que bienheureuse est la nation dont l’Eternel est le Dieu, et le peuple qu’il s’est choisi pour héritage!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'L’Eternel regarde des Cieux, il voit tous les enfants des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Il prend garde du lieu de sa résidence à tous les habitants de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'C’est lui qui forme également leur coeur, et qui prend garde à toutes leurs actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Le Roi n’est point sauvé par une grosse armée, et l’homme puissant n’échappe point par sa grande force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Le cheval manque à sauver, et ne délivre point par la grandeur de sa force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Voici, l’oeil de l’Eternel est sur ceux qui le craignent, sur ceux qui s’attendent à sa gratuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'Afin qu’il les délivre de la mort, et les entretienne en vie durant la famine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Notre âme s’est confiée en l’Eternel; il est notre aide et notre bouclier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Certainement notre coeur se réjouira en lui, parce que nous avons mis notre assurance en son saint Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Que ta gratuité soit sur nous, ô Eternel! selon que nous nous sommes confiés en toi');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Psaume de David, sur ce qu’il changea son extérieur en la présence d’Abimélec, qui le chassa, et il s’en alla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Je bénirai l’Eternel en tout temps, sa louange sera continuellement en ma bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Mon âme se glorifiera en l’Eternel; les débonnaires l’entendront, et s’en réjouiront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Magnifiez l’Eternel avec moi, et exaltons son Nom tous ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'J’ai cherché l’Eternel, et il m’a répondu, et m’a délivré de toutes mes frayeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'He. Vau. L’a-t-on regardé? on en est illuminé, et leurs faces ne sont point confuses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Cet affligé a crié, et l’Eternel l’a exaucé, et l’a délivré de toutes ses détresses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'L’Ange de l’Eternel se campe tout autour de ceux qui le craignent, et les garantit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Savourez, et voyez que l’Eternel est bon; ô que bienheureux est l’homme qui se confie en lui!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Craignez l’Eternel vous ses Saints; car rien ne manque à ceux qui le craignent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Les lionceaux ont disette, ils ont faim; mais ceux qui cherchent l’Eternel n’auront besoin d’aucun bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Venez, enfants, écoutez-moi; je vous enseignerai la crainte de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Qui est l’homme qui prenne plaisir à vivre, et qui aime la longue vie pour voir du bien?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Garde ta langue de mal, et tes lèvres de parler avec tromperie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Détourne-toi du mal, et fais le bien; cherche la paix et la poursuis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Les yeux de l’Eternel sont sur les justes, et ses oreilles sont attentives à leur cri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'La face de l’Eternel est contre ceux qui font le mal, pour exterminer de la terre leur mémoire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Quand les justes crient, l’Eternel les exauce, et il les délivre de toutes leurs détresses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'L’Eternel est près de ceux qui ont le coeur déchiré par la douleur, et il délivre ceux qui ont l’esprit abattu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Le juste a des maux en grand nombre, mais l’Eternel le délivre de tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Il garde tous ses os, et pas un n’en est cassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'La malice fera mourir le méchant; et ceux qui haïssent le juste seront détruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 23, 'L’Eternel rachète l’âme de ses serviteurs; et aucun de ceux qui se confient en lui, ne sera détruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Psaume de David. Eternel, plaide contre ceux qui plaident contre moi, fais la guerre à ceux qui me font la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Prends le bouclier et l’écu, et lève-toi pour me secourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Saisis la lance, et serre le passage au-devant de ceux qui me poursuivent; dis à mon âme: je suis ta délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Que ceux qui cherchent mon âme soient honteux et confus, et que ceux qui machinent mon mal, soient repoussés en arrière, et rougissent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Qu’ils soient comme de la balle exposée au vent, et que l’Ange de l’Eternel les chasse çà et là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Que leur chemin soit ténébreux et glissant; que l’Ange de l’Eternel les poursuive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Car sans cause ils m’ont caché la fosse où étaient tendus leurs rets et sans cause ils ont creusé pour surprendre mon âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Que la ruine dont il ne s’avise point, lui advienne; et que son filet, qu’il a caché, le surprenne, et qu’il tombe en cette même ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Mais que mon âme s’égaye en l’Eternel, et se réjouisse en sa délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Tous mes os diront: Eternel, qui est semblable à toi, qui délivres l’affligé de la main de celui qui est plus fort que lui, l’affligé, dis-je, et le pauvre, de la main de celui qui le pille?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Des témoins violents s’élèvent contre moi, on me redemande des choses dont je ne sais rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Ils m’ont rendu le mal pour le bien, tâchant de m’ôter la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Mais moi, quand ils ont été malades, je me vêtais d’un sac, j’affligeais mon âme par le jeûne, ma prière retournait dans mon sein.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'J’ai agi comme si c’eût été mon intime ami, comme si c’eût été mon frère; j’allais courbé en habit de deuil, comme celui qui mènerait deuil pour sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Mais quand j’ai chancelé, ils se réjouissaient, et s’assemblaient; des gens de néant se sont assemblés contre moi, sans que j’en susse rien; ils ont ri à bouche ouverte, et n’ont point cessé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Avec les hypocrites d’entre les railleurs qui suivent les bonnes tables, et ils ont grincé les dents contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Seigneur, combien de temps le verras-tu? retire mon âme de leurs tempêtes, mon unique d’entre les lionceaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Je te célébrerai dans une grande assemblée, je te louerai parmi un grand peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Que ceux qui me sont ennemis sans sujet ne se réjouissent point de moi; et que ceux qui me haïssent sans cause ne m’insultent point par leurs regards.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Car ils ne parlent point de paix; mais ils préméditent des choses pleines de fraude contre les pacifiques de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Et ils ont ouvert leur bouche autant qu’ils ont pu contre moi, et ont dit: aha! aha! notre oeil l’a vu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Ô Eternel! tu l’as vu: ne te tais point; Seigneur, ne t’éloigne point de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Réveille-toi, réveille-toi, dis-je, ô mon Dieu et mon Seigneur! pour me rendre justice, et pour soutenir ma cause.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Juge-moi selon ta justice, Eternel mon Dieu! et qu’ils ne se réjouissent point de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Qu’ils ne disent point en leur coeur: aha, notre âme! et qu’ils ne disent point: nous l’avons englouti.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Que ceux qui se réjouissent de mon mal soient honteux et rougissent tous ensemble; et que ceux qui s’élèvent contre moi soient couverts de honte et de confusion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Mais que ceux qui sont affectionnés à ma justice se réjouissent avec chant de triomphe, et s’égayent, et qu’ils disent incessamment: magnifié soit l’Eternel qui s’affectionne à la paix de son serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Alors ma langue s’entretiendra de ta justice et de ta louange tout le jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Psaume de David, serviteur de l’Eternel, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'La transgression du méchant me dit au-dedans du coeur, qu’il n’y a point de crainte de Dieu devant ses yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Car il se flatte en soi-même quand son iniquité se présente pour être haïe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Les paroles de sa bouche ne sont qu’injustice et que fraude, il se garde d’être attentif à bien faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Il machine sur son lit les moyens de nuire; il s’arrête au chemin qui n’est pas bon; il n’a point en horreur le mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Eternel, ta gratuité atteint jusqu’aux cieux, ta fidélité jusqu’aux nues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Ta justice est comme de hautes montagnes, tes jugements sont un grand abîme. Eternel, tu conserves les hommes et les bêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Ô Dieu! combien est précieuse ta gratuité! aussi les fils des hommes se retirent sous l’ombre de tes ailes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Ils seront abondamment rassasiés de la graisse de ta maison, et tu les abreuveras au fleuve de tes délices.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Car la source de la vie est par-devers toi, et par ta clarté nous voyons clair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Continue ta gratuité sur ceux qui te connaissent, et ta justice sur ceux qui sont droits de coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Que le pied de l’orgueilleux ne s’avance point sur moi, et que la main des méchants ne m’ébranle point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 13, 'Là sont tombés les ouvriers d’iniquité, ils ont été renversés, et n’ont pu se relever.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Psaume de David. Ne te dépite point à cause des méchants, ne sois point jaloux de ceux qui s’adonnent à la perversité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Car ils seront soudainement retranchés comme le foin, et se faneront comme l’herbe verte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Assure-toi en l’Eternel, et fais ce qui est bon; habite la terre, et te nourris de vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Et prends ton plaisir en l’Eternel, et il t’accordera les demandes de ton coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Remets ta voie sur l’Eternel, et te confie en lui; et il agira;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'Et il manifestera ta justice comme la clarté, et ton droit comme le midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Demeure tranquille te confiant en l’Eternel, et l’attends; ne te dépite point à cause de celui qui fait bien ses affaires, à cause, dis-je, de l’homme qui vient à bout de ses entreprises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Garde-toi de te courroucer, et renonce à la colère; ne te dépite point, au moins pour mal faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Car les méchants seront retranchés; mais ceux qui se confient en l’Eternel hériteront la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Encore donc un peu de temps, et le méchant ne sera plus; et tu prendras garde à son lieu, et il n’y sera plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Mais les débonnaires hériteront la terre, et jouiront à leur aise d’une grande prospérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Le méchant machine contre le juste, et grince ses dents contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Le Seigneur se rira de lui, car il a vu que son jour approche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Les méchants ont tiré leur épée, et ont bandé leur arc, pour abattre l’affligé, et le pauvre, et pour massacrer ceux qui marchent dans la droiture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Mais leur épée entrera dans leur coeur, et leurs arcs seront rompus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Mieux vaut au juste le peu qu’il a, que l’abondance à beaucoup de méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Car les bras des méchants seront cassés, mais l’Eternel soutient les justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'L’Eternel connaît les jours de ceux qui sont intègres, et leur héritage demeurera à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Ils ne seront point confus au mauvais temps, mais ils seront rassasiés au temps de la famine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Mais les méchants périront, et les ennemis de l’Eternel s’évanouiront comme la graisse des agneaux, ils s’en iront en fumée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Le méchant emprunte, et ne rend point; mais le juste a compassion, et donne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Car les bénis de l’Eternel hériteront la terre; mais ceux qu’il a maudits seront retranchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Les pas de l’homme qu’il a béni sont conduits par l’Eternel, et il prend plaisir à ses voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'S’il tombe, il ne sera pas entièrement abattu; car l’Eternel lui soutient la main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'J’ai été jeune, et j’ai atteint la vieillesse, mais je n’ai point vu le juste abandonné, ni sa postérité mendiant son pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Il est ému de pitié tout le jour, et il prête; et sa postérité est en bénédiction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Retire-toi du mal, et fais le bien; et tu auras une demeure éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Car l’Eternel aime ce qui est juste, et il n’abandonne point ses bien- aimés; c’est pourquoi ils sont gardés à toujours; mais la postérité des méchants est retranchée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Les justes hériteront la terre, et y habiteront à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'La bouche du juste proférera la sagesse, et sa langue prononcera la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'La Loi de son Dieu est dans son coeur, aucun de ses pas ne chancellera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Le méchant épie le juste, et cherche à le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'L’Eternel ne l’abandonnera point entre ses mains, et ne le laissera point condamner quand on le jugera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Attends l’Eternel, et prends garde à sa voie, et il t’exaltera, afin que tu hérites la terre, et tu verras comment les méchants seront retranchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'J’ai vu le méchant terrible, et s’étendant comme un laurier vert;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Mais il est passé, et voilà, il n’est plus; je l’ai cherché, et il ne s’est point trouvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Prends garde à l’homme intègre, et considère l’homme droit; car la fin d’un tel homme est la prospérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Mais les prévaricateurs seront tous ensemble détruits, et ce qui sera resté des méchants sera retranché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Mais la délivrance des justes viendra de l’Eternel, il sera leur force au temps de la détresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Car l’Eternel leur aide, et les délivre: il les délivrera des méchants, et les sauvera, parce qu’ils se seront confiés en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Psaume de David, pour réduire en mémoire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Eternel, ne me reprends point en ta colère, et ne me châtie point en ta fureur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Car tes flèches sont entrées en moi, et ta main s’est appesantie sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Il n’y a rien d’entier en ma chair, à cause de ton indignation; ni de repos dans mes os, à cause de mon péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Car mes iniquités ont surmonté ma tête, elles se sont appesanties comme un pesant fardeau, au-delà de mes forces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Mes plaies sont pourries et coulent, à cause de ma folie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Je suis courbé et penché outre mesure; je marche en deuil tout le jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Car mes aines sont remplies d’inflammation, et dans ma chair il n’y a rien d’entier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Je suis affaibli et tout brisé, je rugis du grand frémissement de mon coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Seigneur, tout mon désir est devant toi, et mon gémissement ne t’est point caché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Mon coeur est agité çà et là, ma force m’a abandonné, et la clarté aussi de mes yeux: même ils ne sont plus avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Ceux qui m’aiment, et même mes intimes amis, se tiennent loin de ma plaie, et mes proches se tiennent loin de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Et ceux qui cherchent ma vie, m’ont tendu des filets, et ceux qui cherchent ma perte, parlent de calamités, et songent des tromperies tout le jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Mais moi je n’entends non plus qu’un sourd, et je suis comme un muet qui n’ouvre point sa bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Je suis, dis-je, comme un homme qui n’entend point, et qui n’a point de réplique en sa bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Puisque je me suis attendu à toi, ô Eternel, tu me répondras, Seigneur mon Dieu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Car j’ai dit: Il faut prendre garde qu’ils ne triomphent de moi: quand mon pied glisse, ils s’élèvent contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Quand je suis prêt à clocher; et que ma douleur est continuellement devant moi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Quand je déclare mon iniquité et que je suis en peine pour mon péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Cependant mes ennemis, qui sont vivants, se renforcent, et ceux qui me haïssent à tort se multiplient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Et ceux qui me rendent le mal pour le bien, me sont contraires, parce que je recherche le bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Eternel, ne m’abandonne point; mon Dieu! ne t’éloigne point de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 23, 'Hâte-toi de venir à mon secours, Seigneur, qui es ma délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Psaume de David, donné au maître chantre, savoir à Jéduthun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'J’ai dit: Je prendrai garde à mes voies, afin que je ne pèche point par ma langue; je garderai ma bouche avec une muselière, pendant que le méchant sera devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'J’ai été muet sans dire mot, je me suis tu du bien; mais ma douleur s’est renforcée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Mon coeur s’est échauffé au-dedans de moi, et le feu s’est embrasé en ma méditation; j’ai parlé de ma langue, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Eternel! donne-moi à connaître ma fin, et quelle est la mesure de mes jours; fais que je sache de combien petite durée je suis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Voilà, tu as réduit mes jours à la mesure de quatre doigts, et le temps de ma vie est devant toi comme un rien; certainement ce n’est que pure vanité de tout homme, quoiqu’il soit debout. Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Certainement l’homme se promène parmi ce qui n’a que de l’apparence; certainement on s’agite inutilement; on amasse des biens, et on ne sait point qui les recueillera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Or maintenant qu’ai-je attendu, Seigneur? mon attente est à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Délivre-moi de toutes mes transgressions, et ne permets point que je sois en opprobre à l’insensé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Je me suis tu, et je n’ai point ouvert ma bouche, parce que c’est toi qui l’as fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Retire de moi la plaie que tu m’as faite; je suis consumé par la guerre que tu me fais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Aussitôt que tu châties quelqu’un, en le censurant à cause de son iniquité, tu consumes sa beauté comme la teigne; certainement tout homme est vanité: Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Eternel, écoute ma requête, et prête l’oreille à mon cri, et ne sois point sourd à mes larmes; car je suis voyageur et étranger chez toi, comme ont été tous mes pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 14, 'Retire-toi de moi, afin que je reprenne mes forces, avant que je m’en aille, et que je ne sois plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Psaume de David, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'J’ai attendu patiemment l’Eternel, et il s’est tourné vers moi, et a ouï mon cri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'Il m’a fait remonter hors d’un puits bruyant, et d’un bourbier fangeux; il a mis mes pieds sur un roc, et a assuré mes pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Et il a mis en ma bouche un nouveau Cantique, qui est la louange de notre Dieu. Plusieurs verront cela, et ils craindront, et se confieront en l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Ô que bienheureux est l’homme qui s’est proposé l’Eternel pour son assurance, et qui ne regarde point aux orgueilleux, ni à ceux qui se détournent vers le mensonge!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Eternel mon Dieu! tu as fait que tes merveilles et tes pensées envers nous sont en grand nombre; Il n’est pas possible de les arranger devant toi: les veux-je réciter et dire? elles sont en si grand nombre, que je ne les saurais raconter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Tu ne prends point plaisir au sacrifice ni au gâteau; mais tu m’as percé les oreilles; tu n’as point demandé d’holocauste, ni d’oblation pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Alors j’ai dit: Voici, je viens, il est écrit de moi au rôle du Livre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Mon Dieu, j’ai pris plaisir à faire ta volonté, et ta Loi est au-dedans de mes entrailles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'J’ai prêché ta justice dans la grande assemblée; voilà, je n’ai point retenu mes lèvres; tu le sais, ô Eternel!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Je n’ai point caché ta justice, qui est au-dedans de mon coeur; j’ai déclaré ta fidélité et ta délivrance; je n’ai point scellé ta gratuité ni ta vérité dans la grande assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Et toi, Eternel! ne m’épargne point tes compassions; que ta gratuité et ta vérité me gardent continuellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Car des maux sans nombre m’ont environné; mes iniquités m’ont atteint, et je ne les ai pu voir; elles surpassent en nombre les cheveux de ma tête, et mon coeur m’a abandonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Eternel, veuille me délivrer; Eternel, hâte-toi de venir à mon secours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Que ceux-là soient tous honteux et rougissent ensemble qui cherchent mon âme pour la perdre; et que ceux qui prennent plaisir à mon malheur, retournent en arrière, et soient confus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Que ceux qui disent de moi: Aha! Aha! soient consumés, en récompense de la honte qu’ils m’ont faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Que tous ceux qui te cherchent, s’égayent et se réjouissent en toi; et que ceux qui aiment ta délivrance, disent continuellement: Magnifié soit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 18, 'Or je suis affligé et misérable, mais le Seigneur a soin de moi; tu es mon secours et mon libérateur; mon Dieu ne tarde point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Psaume de David, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Ô que bienheureux est celui qui se conduit sagement envers l’affligé! l’Eternel le délivrera au jour de la calamité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'L’Eternel le gardera et le préservera en vie; il sera même rendu heureux en la terre; ne le livre donc point au gré de ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'L’Eternel le soutiendra quand il sera dans un lit de langueur; tu transformeras tout son lit, quand il sera malade.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'J’ai dit: Eternel! aie pitié de moi, guéris mon âme; quoique j’aie péché contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Mes ennemis me souhaitant du mal, disent: Quand mourra-t-il? et quand périra son nom?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Et si quelqu’un d’eux vient me visiter, il parle en mensonge; son coeur s’amasse de quoi me fâcher. Est-il sorti? il en parle dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Tous ceux qui m’ont en haine murmurent sourdement ensemble contre moi, et machinent du mal contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Quelque action, disent-ils, telle que les méchants commettent, le tient enserré, et cet homme qui est couché, ne se relèvera plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Même celui qui avait la paix avec moi, sur lequel je m’assurais, et qui mangeait mon pain, a levé le talon contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Mais toi, ô Eternel! aie pitié de moi, et me relève; et je le leur rendrai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'En ceci je connais que tu prends plaisir en moi, que mon ennemi ne triomphe point de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Pour moi, tu m’as maintenu dans mon entier, et tu m’as établi devant toi pour toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 14, 'Béni soit l’Eternel, le Dieu d’Israël, de siècle en siècle. Amen! Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Maskil des enfants de Coré, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Comme le cerf brame après le courant des eaux, ainsi mon âme soupire ardemment après toi, ô Dieu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Mon âme a soif de Dieu, du Dieu Fort, et vivant; ô quand entrerai-je et me présenterai-je devant la face de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Mes larmes m’ont été au lieu de pain, jour et nuit, quand on me disait chaque jour: Où est ton Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Je rappelais ces choses dans mon souvenir, et je m’en entretenais en moi-même, savoir que je marchais en la troupe, et que je m’en allais tout doucement en leur compagnie, avec une voix de triomphe et de louange, jusques à la maison de Dieu, et qu’une grande multitude de gens sautait alors de joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Mon âme, pourquoi t’abats-tu, et frémis-tu au-dedans de moi? Attends-toi à Dieu; car je le célébrerai encore; son regard est la délivrance même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Mon Dieu! mon âme est abattue en moi-même, parce qu’il me souvient de toi depuis la région du Jourdain, et de celle des Hermoniens, et de la montagne de Mitshar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Un abîme appelle un autre abîme au son de tes canaux; toutes tes vagues et tes flots ont passé sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'L’Eternel mandera de jour sa gratuité, et son Cantique sera de nuit avec moi, et je ferai requête au Dieu Fort, qui est ma vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Je dirai au Dieu Fort qui est mon rocher: pourquoi m’as-tu oublié? pourquoi marcherai-je en deuil à cause de l’oppression de l’ennemi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Mes adversaires m’ont fait outrage; ç’a été une épée dans mes os, quand ils m’ont dit chaque jour, où est ton Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 12, 'Mon âme, pourquoi t’abats-tu, et pourquoi frémis-tu au-dedans de moi? Attends-toi à Dieu; car je le célébrerai encore, il est ma délivrance, et mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Fais-moi justice, ô Dieu! et soutiens mon droit contre la nation cruelle; délivre-moi de l’homme trompeur et pervers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Puisque tu es le Dieu de ma force, pourquoi m’as-tu rejeté? pourquoi marcherai-je en deuil à cause de l’oppression de l’ennemi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Envoie ta lumière et ta vérité, afin qu’elles me conduisent et m’introduisent en la montagne de ta Sainteté, et en tes Tabernacles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Alors je viendrai à l’Autel de Dieu, vers le Dieu Fort de l’allégresse de ma joie, et je te célébrerai sur le violon, ô Dieu! mon Dieu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Mon âme, pourquoi t’abats-tu, et pourquoi frémis-tu au-dedans de moi? Attends-toi à Dieu; car je le célébrerai encore; il est ma délivrance, et mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Maskil des enfants de Coré, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Ô Dieu nous avons ouï de nos oreilles, et nos pères nous ont raconté les exploits que tu as faits en leurs jours, aux jours d’autrefois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Tu as de ta main chassé les nations, et tu as affermi nos pères; tu as affligé les peuples, et tu as fait prospérer nos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Car ce n’est point par leur épée qu’ils ont conquis le pays, et ce n’a point été leur bras, qui les a délivrés; mais ta droite, et ton bras, et la lumière de ta face; parce que tu les affectionnais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Ô Dieu! c’est toi qui es mon Roi, ordonne les délivrances de Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Avec toi nous battrons nos adversaires, par ton Nom nous foulerons ceux qui s’élèvent contre nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Car je ne me confie point en mon arc, et ce ne sera pas mon épée qui me délivrera;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Mais tu nous délivreras de nos adversaires, et tu rendras confus ceux qui nous haïssent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Nous nous glorifierons en Dieu tout le jour, et nous célébrerons à toujours ton Nom. Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Mais tu nous as rejetés, et rendus confus, et tu ne sors plus avec nos armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Tu nous as fait retourner en arrière de devant l’adversaire, et nos ennemis se sont enrichis de ce qu’ils ont pillé sur nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Tu nous as livrés comme des brebis destinées à être mangées, et tu nous as dispersés entre les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Tu as vendu ton peuple pour rien, et tu n’as point fait hausser leur prix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Tu nous as mis en opprobre chez nos voisins, en dérision, et en raillerie auprès de ceux qui habitent autour de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Tu nous as mis en dicton parmi les nations, et en hochement de tête parmi les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Ma confusion est tout le jour devant moi, et la honte de ma face m’a tout couvert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'A cause des discours de celui qui nous fait des reproches, et qui nous injurie, et à cause de l’ennemi et du vindicatif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Tout cela nous est arrivé, et cependant nous ne t’avons point oublié, et nous n’avons point faussé ton alliance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Notre coeur n’a point reculé en arrière, ni nos pas ne se sont point détournés de tes sentiers;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Quoique tu nous aies froissés parmi des dragons, et couverts de l’ombre de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Si nous eussions oublié le Nom de notre Dieu, et que nous eussions étendu nos mains vers un dieu étranger,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Dieu ne s’en enquerrait-il point? vu que c’est lui qui connaît les secrets du coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Mais nous sommes tous les jours mis à mort pour l’amour de toi, et nous sommes regardés comme des brebis de la boucherie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Lève-toi, pourquoi dors-tu, Seigneur? Réveille-toi, ne nous rejette point à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Pourquoi caches-tu ta face, et pourquoi oublies-tu notre affliction et notre oppression?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Car notre âme est penchée jusques en la poudre, et notre ventre est attaché contre terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 27, 'Lève-toi pour nous secourir, et nous délivre pour l’amour de ta gratuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Maskil des enfants de Coré, qui est un Cantique nuptial, donné au maitre chantre, pour le chanter sur Sosannim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Mon coeur médite un excellent discours, et j’ai dit: mes ouvrages seront pour le Roi; ma langue sera la plume d’un écrivain diligent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Tu es plus beau qu’aucun des fils des hommes; la grâce est répandue sur tes lèvres, parce que Dieu t’a béni éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Ô Très-puissant, ceins ton épée sur ta cuisse, ta majesté et ta magnificence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Et prospère en ta magnificence; sois porté sur la parole de vérité, de débonnaireté, et de justice; et ta droite t’enseignera des choses terribles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Tes flèches sont aiguës, les peuples tomberont sous toi; elles entreront dans le coeur des ennemis du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Ton trône, ô Dieu! est à toujours et à perpétuité; le sceptre de ton règne est un sceptre d’équité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Tu aimes la justice, et tu hais la méchanceté; c’est pourquoi, ô Dieu! ton Dieu t’a oint d’une huile de joie par-dessus tes compagnons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Ce n’est que myrrhe, aloès et casse de tous tes vêtements, quand tu sors des palais d’ivoire, dont ils t’ont réjoui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Des filles de Rois sont entre tes dames d’honneur; ta femme est à ta droite, parée d’or d’Ophir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Ecoute fille, et considère; rends-toi attentive, oublie ton peuple, et la maison de ton père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Et le Roi mettra son affection en ta beauté; puisqu’il est ton Seigneur, prosterne-toi devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Et la fille de Tyr, et les plus riches des peuples te supplieront avec des présents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'La fille du Roi est intérieurement toute pleine de gloire; son vêtement est semé d’enchâssures d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Elle sera présentée au Roi en vêtements de broderie; et les filles qui viennent après elle, et qui sont ses compagnes, seront amenées vers toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Elles te seront présentées avec réjouissance et allégresse, et elles entreront au palais du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Tes enfants seront au lieu de tes pères; tu les établiras pour Princes par toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 18, 'Je rendrai ton Nom mémorable dans tous les âges, et à cause de cela les peuples te célébreront à toujours et à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Cantique des enfants de Coré, donné au maître chantre, pour le chanter sur Halamoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Dieu est notre retraite, notre force, et notre secours dans les détresses; et fort aisé à trouver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'C’est pourquoi nous ne craindrons point, quand on remuerait la terre, et que les montagnes se renverseraient dans la mer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Quand ses eaux viendraient à bruire et à se troubler, et que les montagnes seraient ébranlées par l’élévation de ses vagues; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Les ruisseaux de la rivière réjouiront la ville de Dieu, qui est le saint lieu où demeure le Souverain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Dieu est au milieu d’elle; elle ne sera point ébranlée. Dieu lui donnera du secours dès le point du jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Les nations ont mené du bruit, les Royaumes ont été ébranlés; il a fait ouïr sa voix, et la terre s’est fondue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'L’Eternel des armées est avec nous; le Dieu de Jacob nous est une haute retraite; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Venez, contemplez les faits de l’Eternel, et voyez quels dégâts il a faits en la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Il a fait cesser les guerres jusques au bout de la terre; il rompt les arcs, il brise les hallebardes, il brûle les chariots par feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Cessez, a-t-il dit, et connaissez que je suis Dieu; je serai exalté parmi les nations, je serai exalté par toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 12, 'L’Eternel des armées est avec nous; le Dieu de Jacob nous est une haute retraite; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Psaume des enfants de Coré, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Peuples battez tous des mains, jetez des cris de réjouissance à Dieu avec une voix de triomphe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Car l’Eternel qui est le Souverain est terrible et il est grand Roi sur toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Il range les peuples sous nous, et les nations, sous nos pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Il nous a choisi, notre héritage, qui est la magnificence de Jacob, lequel il aime; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Dieu est monté avec un cri de réjouissance; l’Eternel est monté avec un son de trompette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Psalmodiez à Dieu, psalmodiez, psalmodiez à notre Roi, psalmodiez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Car Dieu est le Roi de toute la terre; tout homme entendu, psalmodiez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Dieu règne sur les nations; Dieu est assis sur le trône de sa sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 10, 'Les principaux des peuples se sont assembles vers le peuple du Dieu d’Abraham; car les boucliers de la terre sont à Dieu; il est fort exalté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Cantique de Psaume, des enfants de Coré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'L’Eternel est grand, et fort louable en la ville de notre Dieu, en la montagne de sa Sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Le plus beau de la contrée, la joie de toute la terre, c’est la montagne de Sion au fond de l’Aquilon; c’est la ville du grand Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Dieu est connu en ses palais pour une haute retraite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Car voici, les Rois s’étaient donné assignation, ils avaient passé outre tous ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'L’ont-ils vue? ils en ont été aussitôt étonnés; ils ont été tout troublés, ils s’en sont fuis à l’étourdie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Là le tremblement les a saisis, et une douleur comme de celle qui enfante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Ils ont été chassés comme par le vent d’Orient qui brise les navires de Tarsis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Comme nous l’avions entendu, ainsi l’avons-nous vu dans la ville de l’Eternel des armées, dans la ville de notre Dieu, laquelle Dieu maintiendra à toujours; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Ô Dieu! nous avons entendu ta gratuité au milieu de ton Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Ô Dieu! tel qu’est ton Nom, telle est ta louange jusqu’aux bouts de la terre; ta droite est pleine de justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'La montagne de Sion se réjouira, et les filles de Juda auront de la joie, à cause de tes jugements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Environnez Sion, et l’entourez, et comptez ses tours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Prenez bien garde à son avant-mur, et considérez ses palais; afin que vous le racontiez à la génération à venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 15, 'Car c’est le Dieu qui est notre Dieu à toujours et à perpétuité; il nous accompagnera jusques à la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Psaume des enfants de Coré, au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Vous tous peuples, entendez ceci; vous habitants du monde, prêtez l’oreille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Que ceux du bas état, et ceux qui sont d’une condition élevée écoutent; pareillement le riche et le pauvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Ma bouche prononcera des discours pleins de sagesse, et ce que mon coeur a médité sont des choses pleines de sens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Je prêterai l’oreille à un propos sentencieux, j’exposerai mes dits notables sur le violon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Pourquoi craindrai-je au mauvais temps, quand l’iniquité de mes talons m’environnera?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Il y en a qui se fient en leurs biens, et qui se glorifient en l’abondance de leurs richesses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'Personne ne pourra avec ses richesses racheter son frère, ni donner à Dieu sa rançon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'Car le rachat de leur âme est trop considérable, et il ne se fera jamais;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Pour faire qu’il vive encore à jamais et qu’il ne voie point la fosse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Car on voit que les sages meurent, et pareillement que le fol et l’abruti périssent, et qu’ils laissent leurs biens à d’autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Leur intention est que leurs maisons durent à toujours, et que leurs habitations demeurent d’âge en âge; ils ont appelé les terres de leur nom;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Et toutefois l’homme ne se maintient point dans ses honneurs, mais il est rendu semblable aux bêtes brutes qui périssent entièrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Ce chemin qu’ils tiennent, leur tourne à folie, et néanmoins leurs successeurs prennent plaisir à leurs enseignements; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Ils seront mis au sépulcre comme des brebis; la mort se repaîtra d’eux, et les hommes droits auront domination sur eux au matin, et leur force sera le sépulcre pour les y faire consumer, chacun d’eux étant transporté hors de son domicile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Mais Dieu rachètera mon âme de la puissance du sépulcre, quand il me prendra à soi; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Ne crains point quand tu verras quelqu’un enrichi, et quand la gloire de sa maison sera multipliée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Car lorsqu’il mourra, il n’emportera rien; sa gloire ne descendra point après lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Quoiqu’il ait béni son âme en sa vie, et quoiqu’on te loue parce que tu te seras fait du bien;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Venant jusques à la race des pères de chacun d’eux, ce sera comme s’ils n’avaient jamais vu la lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 21, 'L’homme qui est en honneur, et n’a point d’intelligence, est semblable aux bêtes brutes qui périssent entièrement');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Psaume d’Asaph Le Dieu Fort, le Dieu, l’Eternel a parlé, et il a appelé toute la terre, depuis le soleil levant jusques au soleil couchant');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Dieu a fait luire sa splendeur de Sion, qui est d’une beauté parfaite');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Notre Dieu viendra, il ne se taira point: il y aura devant lui un feu dévorant, et tout autour de lui une grosse tempête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Il appellera les cieux d’en haut, et la terre, pour juger son peuple, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, 'Assemblez-moi mes bien-aimés qui ont traité alliance avec moi sur le sacrifice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Les cieux aussi annonceront sa justice: parce que Dieu est le juge; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Ecoute, ô mon peuple, et je parlerai; entends, Israël, et je te sommerai; je suis Dieu, ton Dieu, moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Je ne te reprendrai point pour tes sacrifices, ni pour tes holocaustes, qui ont été continuellement devant moi');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Je ne prendrai point de veau de ta maison, ni de boucs de tes parcs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Car toute bête de la forêt est à moi, et les bêtes aussi qui paissent en mille montagnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Je connais tous les oiseaux des montagnes; et toute sorte de bêtes des champs est à mon commandement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Si j’avais faim, je ne t’en dirais rien; car la terre habitable est à moi, et tout ce qui est en elle');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Mangerais-je la chair des gros taureaux? et boirais-je le sang des boucs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Sacrifie louange à Dieu, et rends tes voeux au Souverain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'Et invoque-moi au jour de ta détresse, je t’en tirerai hors, et tu me glorifieras');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Mais Dieu a dit au méchant: qu’as-tu que faire de réciter mes statuts, et de prendre mon alliance en ta bouche;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Vu que tu hais la correction, et que tu as jeté mes paroles derrière toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Si tu vois un larron, tu cours avec lui; et ta portion est avec les adultères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Tu lâches ta bouche au mal, et par ta langue tu trames la fraude;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Tu t’assieds et parles contre ton frère, et tu couvres d’opprobre le fils de ta mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Tu as fait ces choses-là, et je m’en suis tu; et tu as estimé que véritablement je fusse comme toi; mais je t’en reprendrai, et je déduirai le tout par ordre en ta présence');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Entendez cela maintenant, vous qui oubliez Dieu; de peur que je ne vous ravisse, et qu’il n’y ait personne qui vous délivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Celui qui sacrifie la louange me glorifiera; et à celui qui prend garde à sa voie, je montrerai la délivrance de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Psaume de David, au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Touchant ce que Nathan le Prophète vint à lui, après qu’il fut entré vers Bathsebah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Ô Dieu! aie pitié de moi selon ta gratuité, selon la grandeur de tes compassions efface mes forfaits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Lave-moi parfaitement de mon iniquité, et me nettoie de mon péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Car je connais mes transgressions, et mon péché est continuellement devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'J’ai péché contre toi, contre toi proprement, et j’ai fait ce qui déplaît à tes yeux: afin que tu sois connu juste quand tu parles, et trouvé pur, quand tu juges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Voilà, j’ai été formé dans l’iniquité, et ma mère m’a échauffé dans le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Voilà, tu aimes la vérité dans le coeur, et tu m’as enseigné la sagesse dans le secret de mon coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Purifie-moi du péché avec de l’hysope, et je serai net; lave-moi, et je serai plus blanc que la neige.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Fais-moi entendre la joie et l’allégresse, et fais que les os que tu as brisés se réjouissent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Détourne ta face de mes péchés, et efface toutes mes iniquités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Ô Dieu! crée-moi un coeur net, et renouvelle au dedans de moi un esprit bien remis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Ne me rejette point de devant ta face, et ne m’ôte point l’Esprit de ta Sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Rends-moi la joie de ton salut, et que l’Esprit de l’affranchissement me soutienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'J’enseignerai tes voies aux transgresseurs, et les pécheurs se convertiront à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Ô Dieu! Dieu de mon salut, délivre-moi de tant de sang, et ma langue chantera hautement ta justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Seigneur, ouvre mes lèvres, et ma bouche annoncera ta louange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Car tu ne prends point plaisir aux sacrifices, autrement j’en donnerais; l’holocauste ne t’est point agréable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Les sacrifices de Dieu sont l’esprit froissé: ô Dieu! tu ne méprises point le coeur froissé et brisé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 20, 'Fais du bien selon ta bienveillance à Sion, et édifie les murs de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 21, 'Alors tu prendras plaisir aux sacrifices de justice, à l’holocauste, et aux sacrifices qui se consument entièrement par le feu; alors on offrira des veaux sur ton autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Maskil de David, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Sur ce que Doëg Iduméen vint à Saül, et lui rapporta, disant: David est venu en la maison d’Ahimélec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Pourquoi te vantes-tu du mal, vaillant homme? La gratuité du Dieu Fort dure tous les jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Ta langue trame des méchancetés, elle est comme un rasoir affilé, qui trompe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Tu aimes plus le mal que le bien, et le mensonge plus que de dire la vérité; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Tu aimes tous les discours pernicieux, et le langage trompeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Aussi le Dieu Fort te détruira pour jamais; il t’enlèvera et t’arrachera de ta tente, et il te déracinera de la terre des vivants; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Et les justes le verront, et craindront, et ils se riront d’un tel homme, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Voilà cet homme qui ne tenait point Dieu pour sa force, mais qui s’assurait sur ses grandes richesses, et qui mettait sa force en sa malice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 10, 'Mais moi, je serai dans la maison de Dieu comme un olivier qui verdit. Je m’assure en la gratuité de Dieu pour toujours et à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 11, 'Je te célébrerai à jamais de ce que tu auras fait ces choses; et je mettrai mon espérance en ton Nom, parce qu’il est bon envers tes bien-aimés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Maskil de David, donné au maître chantre, pour le chanter sur Mahalath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'L’insensé dit en son coeur: Il n’y a point de Dieu. Ils se sont corrompus, ils ont rendu abominable leur perversité; il n’y a personne qui fasse bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Dieu a regardé des Cieux sur les fils des hommes, pour voir s’il y en a quelqu’un qui soit intelligent, et qui cherche Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Ils se sont tous retirés en arrière, et se sont tous rendus odieux: il n’y a personne qui fasse bien, non pas même un seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Les ouvriers d’iniquité n’ont-ils point de connaissance, mangeant mon peuple, comme s’ils mangeaient du pain? Ils n’invoquent point Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Ils seront extrêmement effrayés là où ils n’avaient point eu de peur; car Dieu a dispersé les os de celui qui se campe contre toi. Tu les as rendus confus, parce que Dieu les a rendus contemptibles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 7, 'Ô qui donnera de Sion les délivrances d’Israël? Quand Dieu aura ramené son peuple captif, Jacob s’égayera, Israël se réjouira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Maskil de David, donné au maître chantre, pour le chanter sur Néguinoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Touchant ce que les Ziphiens vinrent à Saül, et lui dirent: David ne se tient-il pas caché parmi nous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Ô Dieu, délivre-moi par ton Nom, et me fais justice par ta puissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Ô Dieu, écoute ma requête, et prête l’oreille aux paroles de ma bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Car des étrangers se sont élevés contre moi, et des gens terribles, qui n’ont point Dieu devant leurs yeux, cherchent ma vie; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Voilà, Dieu m’accorde son secours; le Seigneur est de ceux qui soutiennent mon âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Il fera retourner le mal sur ceux qui m’épient; détruis-les selon ta vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 8, 'Je te ferai sacrifice de bon coeur; Eternel! je célébrerai ton Nom, parce qu’il est bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 9, 'Car il m’a délivré de toute détresse: et mon oeil a vu ce qu’il voulait voir en mes ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Maskil de David, donné au maître chantre, pour le chanter sur Néguinoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Ô Dieu! prête l’oreille à ma requête, et ne te cache point arrière de ma supplication.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Ecoute-moi, et m’exauce, je verse des larmes dans ma méditation et je suis agité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'A cause du bruit que fait l’ennemi, et à cause de l’oppression du méchant; car ils font tomber sur moi tout outrage, et ils me haïssent jusques à la fureur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Mon coeur est au-dedans de moi comme en travail d’enfant, et des frayeurs mortelles sont tombées sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'La crainte et le tremblement se sont jetés sur moi, et l’épouvantement m’a couvert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Et j’ai dit: Ô qui me donnerait des ailes de pigeon? je m’envolerais, et je me poserais en quelque endroit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Voilà, je m’enfuirais bien loin, et je me tiendrais au désert; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Je me hâterais de me garantir de ce vent excité par la tempête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Seigneur, engloutis-les, divise leur langue; car j’ai vu la violence et les querelles en la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Elles l’environnent jour et nuit sur ses murailles; l’outrage et le tourment sont au milieu d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Les calamités sont au milieu d’elle, et la tromperie et la fraude ne partent point de ses places.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Car ce n’est pas mon ennemi qui m’a diffamé, autrement je l’eusse souffert; ce n’est point celui qui m’a en haine qui s’est élevé contre moi, autrement je me fusse caché de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Mais c’est toi, ô homme! qui étais estimé autant que moi, mon gouverneur, et mon familier;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Qui prenions plaisir à communiquer nos secrets ensemble, et qui allions de compagnie en la maison de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Que la mort, comme un exacteur, se jette sur eux! qu’ils descendent tous vifs en la fosse! Car il n’y a que des maux parmi eux dans leur assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Mais moi je crierai à Dieu, et l’Eternel me délivrera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Le soir, et le matin, et à midi je parlerai et je m’émouvrai, et il entendra ma voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Il délivrera mon âme en paix de la guerre qu’on me fait; car j’ai à faire contre beaucoup de gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Le Dieu Fort l’entendra, et les accablera; car il préside de toute ancienneté; Sélah! Parce qu’il n’y a point de changement en eux, et qu’ils ne craignent point Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Chacun d’eux a jeté ses mains sur ceux qui vivaient paisiblement avec lui, et a violé son accord.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Les paroles de sa bouche sont plus douces que le beurre, mais la guerre est dans son coeur; ses paroles sont plus douces que l’huile, néanmoins elles sont tout autant d’épées nues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Rejette ta charge sur l’Eternel, et il te soulagera: il ne permettra jamais que le juste tombe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 24, 'Mais toi, ô Dieu! tu les précipiteras au puits de la perdition: les hommes sanguinaires et trompeurs ne parviendront point à la moitié de leurs jours: mais je m’assurerai en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Mictam de David, donné au maître chantre, pour le chanter sur Jonathelem- rehokim, touchant ce que les Philistins le prirent dans Gath.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Ô Dieu! aie pitié de moi, car l’homme mortel m’engloutit et m’opprime, me faisant tout le jour la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Mes espions m’ont englouti tout le jour; car, ô Très-haut! Plusieurs me font la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Le jour auquel je craindrai je me confierai en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Je louerai en Dieu sa parole, je me confie en Dieu, je ne craindrai rien; que me fera la chair?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Tout le jour ils tordent mes propos, et toutes leurs pensées tendent à me nuire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Ils s’assemblent, ils se tiennent cachés, ils observent mes talons, attendant comment ils surprendront mon âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Leur moyen d’échapper c’est par outrage; ô Dieu, précipite les peuples en ta colère!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Tu as compté mes allées et venues; mets mes larmes dans tes vaisseaux; ne sont-elles pas écrites dans ton registre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Le jour auquel je crierai à toi, mes ennemis retourneront en arrière; je sais que Dieu est pour moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'Je louerai en Dieu sa parole, je louerai en l’Eternel sa parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Je me confie en Dieu, je ne craindrai rien; que me fera l’homme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Ô Dieu, tes voeux seront sur moi; je te rendrai des actions de grâces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 14, 'Puisque tu as délivré mon âme de la mort, ne garderais-tu pas mes pieds de broncher, afin que je marche devant Dieu en la lumière des vivants?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Mictam de David, donné au maître chantre, pour le chanter sur Al- tasheth: touchant ce qu’il s’enfuit de devant Saül en la caverne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Aie pitié de moi; ô Dieu! Aie pitié de moi; car mon âme se retire vers toi, et je me retire sous l’ombre de tes ailes, jusqu’à ce que les calamités soient passées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Je crierai au Dieu souverain, au Dieu Fort, qui accomplit son oeuvre pour moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Il enverra des cieux, et me délivrera; il rendra honteux celui qui me veut dévorer; Sélah. Dieu enverra sa gratuité et sa vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Mon âme est parmi des lions; je demeure parmi des boutefeux; parmi des hommes dont les dents sont des hallebardes et des flèches, et dont la langue est une épée aiguë.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Ô Dieu! élève-toi sur les cieux, et que ta gloire soit sur toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Ils avaient préparé le rets à mes pas; mon âme penchait déjà. Ils avaient creusé une fosse devant moi, mais ils sont tombés au milieu d’elle; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Mon coeur est disposé, ô Dieu! mon coeur est disposé, je chanterai et psalmodierai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Réveille-toi ma gloire, réveille-toi musette et violon, je me réveillerai à l’aube du jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Seigneur, je te célébrerai parmi les peuples, je te psalmodierai parmi les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Car ta gratuité est grande jusqu’aux cieux, et ta vérité jusqu’aux nues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 12, 'Ô Dieu! élève-toi sur les cieux, et que ta gloire soit sur toute la terre!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Mictam de David, donné au maître chantre, pour le chanter sur Al-tasheth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'En vérité, vous gens de l’assemblée, prononcez-vous ce qui est juste? Vous fils des hommes, jugez-vous avec droiture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Au contraire, vous tramez des injustices dans votre coeur; vous balancez la violence de vos mains en la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Les méchants se sont égarés dès la matrice, ils ont erré dès le ventre de leur mère, en parlant faussement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Ils ont un venin semblable au venin du serpent, et ils sont comme l’aspic sourd, qui bouche son oreille;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Qui n’écoute point la voix des enchanteurs, la voix du charmeur fort expert en charmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Ô Dieu, brise-leur les dents dans leur bouche! Eternel, romps les dents mâchelières des lionceaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Qu’ils s’écoulent comme de l’eau, et qu’ils se fondent! que chacun d’eux bande son arc, mais que ses flèches soient comme si elles étaient rompues!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Qu’il s’en aille comme un limaçon qui se fond! qu’ils ne voient point le soleil non plus que l’avorton d’une femme!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Avant que vos chaudières aient senti le feu des épines, l’ardeur de la colère, semblable à un tourbillon, enlèvera chacun d’eux comme de la chair crue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Le juste se réjouira quand il aura vu la vengeance; il lavera ses pieds au sang du méchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 12, 'Et chacun dira: quoi qu’il en soit, il y a une récompense pour le juste; quoi qu’il en soit, il y a un Dieu qui juge en la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Mictam de David, donné au maître chantre, pour le chanter sur Al- tasheth; touchant ce que Saül envoya des gens qui épièrent sa maison afin de le tuer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Mon Dieu! délivre-moi de mes ennemis, garantis-moi de ceux qui s’élèvent contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Délivre-moi des ouvriers d’iniquité, et me garde des hommes sanguinaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Car voici, ils m’ont dressé des embûches, et des gens robustes se sont assemblés contre moi, bien qu’il n’y ait point en moi de transgression ni de péché, ô Eternel!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Ils courent çà et là, et se mettent en ordre, bien qu’il n’y ait point d’iniquité en moi; réveille-toi pour venir au-devant de moi, et regarde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Toi donc, ô Eternel! Dieu des armées, Dieu d’Israël, réveille-toi pour visiter toutes les nations; ne fais point de grâce à pas un de ceux qui outragent perfidement; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Ils vont et viennent sur le soir, ils font du bruit comme des chiens, ils font le tour de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Voilà, ils s’évaporent en discours; il y a des épées en leurs lèvres; car, disent-ils, qui est-ce qui nous entend?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Mais toi, Eternel! tu te riras d’eux, tu te moqueras de toutes les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'A cause de sa force, je m’attends à toi; car Dieu est ma haute retraite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Dieu qui me favorise me préviendra, Dieu me fera voir ce que je désire en ceux qui m’observent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Ne les tue pas, de peur que mon peuple ne l’oublie; fais-les errer par ta puissance, et les abats, Seigneur, qui es notre bouclier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Le péché de leur bouche est la parole de leurs lèvres; qu’ils soient donc pris par leur orgueil; car ils ne tiennent que des discours d’exécration et de mensonge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Consume-les avec fureur, consume- les de sorte qu’ils ne soient plus; et qu’on sache que Dieu domine en Jacob, et jusqu’aux bouts de la terre; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Qu’ils aillent donc et viennent sur le soir, qu’ils fassent du bruit comme des chiens, et qu’ils fassent le tour de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Qu’ils se donnent du mouvement pour trouver à manger, et qu’ils passent la nuit sans être rassasiés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Mais moi je chanterai ta force, et je louerai dès le matin à haute voix ta gratuité, parce que tu m’as été une haute retraite, et mon asile au jour que j’étais en détresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 18, 'Ma Force! Je te psalmodierai; car Dieu est ma haute retraite, et le Dieu qui me favorise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Mictam de David, propre pour enseigner, et donné au maître chantre, pour le chanter sur Susan-heduth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Touchant la guerre qu’il eut contre la Syrie de Mésopotamie, et contre la Syrie de Tsoba; et touchant ce que Joab retournant défit douze mille Iduméens dans la vallée du sel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Ô Dieu! tu nous as rejetés, tu nous as dispersés, tu t’es courroucé; retourne-toi vers nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Tu as ébranlé la terre, et l’as mise en pièces; répare ses fractures, car elle est affaissée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Tu as fait voir à ton peuple des choses dures, tu nous as abreuvés de vin d’étourdissement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Mais depuis tu as donné une bannière à ceux qui te craignent, afin de l’élever en haut pour l’amour de ta vérité; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Afin que ceux que tu aimes soient délivrés. Sauve-moi par ta droite, et exauce-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Dieu a parlé dans son Sanctuaire; je me réjouirai; je partagerai Sichem, et je mesurerai la vallée de Succoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Galaad sera à moi, Manassé aussi sera à moi, et Ephraïm sera la force de mon chef, Juda sera mon législateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Moab sera le bassin où je me laverai; je jetterai mon soulier à Edom; Ô Palestine, triomphe à cause de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Qui sera-ce qui me conduira en la ville munie? Qui sera-ce qui me conduira jusques en Edom?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Ne sera-ce pas toi, ô Dieu! qui nous avais rejetés, et qui ne sortais plus, ô Dieu! avec nos armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 13, 'Donne-nous du secours pour sortir de détresse; car la délivrance qu’on attend de l’homme est vanité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 14, 'Nous ferons des actions de valeur avec le secours de Dieu, et il foulera nos ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Psaume de David, donné au maître chantre, pour le chanter sur Néguinoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Ô Dieu écoute mon cri, sois attentif à ma requête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Je crierai à toi du bout de la terre, lorsque mon coeur se pâme; conduis-moi sur cette roche, qui est trop haute pour moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Car tu m’as été pour retraite, et pour une forte tour au-devant de l’ennemi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Je séjournerai dans ton Tabernacle durant un long temps; je me retirerai sous l’ombre de tes ailes; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Car tu as, ô Dieu! exaucé mes voeux, et tu m’as donné l’héritage de ceux qui craignent ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Tu ajouteras des jours aux jours du Roi; et ses années seront comme plusieurs âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Il demeurera à toujours en la présence de Dieu; que la gratuité et la vérité le gardent!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 9, 'Ainsi je psalmodierai ton Nom à perpétuité, en te rendant mes voeux chaque jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Psaume de David, donné au maître chantre, d’entre les enfants de Jéduthun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Quoiqu’il en soit, mon âme se repose en Dieu; c’est de lui que vient ma délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Quoiqu’il en soit, il est mon rocher, et ma délivrance, et ma haute retraite; je ne serai pas entièrement ébranlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Jusques à quand machinerez-vous des maux contre un homme? Vous serez tous mis à mort, et vous serez comme le mur qui penche, et comme une cloison qui a été ébranlée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Ils ne font que consulter pour le faire déchoir de son élévation; ils prennent plaisir au mensonge; ils bénissent de leur bouche, mais au-dedans ils maudissent; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Mais toi mon âme, demeure tranquille, regardant à Dieu; car mon attente est en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Quoiqu’il en soit, il est mon rocher, et ma délivrance, et ma haute retraite; je ne serai point ébranlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'En Dieu est ma délivrance et ma gloire; en Dieu est le rocher de ma force et ma retraite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Peuples, confiez-vous en lui en tout temps, déchargez votre coeur devant lui; Dieu est notre retraite; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Ceux du bas état ne sont que vanité: les nobles ne sont que mensonge; si on les mettait tous ensemble en une balance, ils se trouveraient plus légers que la vanité même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Ne mettez point votre confiance dans la tromperie, ni dans la rapine; ne devenez point vains; et quand les richesses abonderont, n’y mettez point votre cœur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Dieu a une fois parlé, et j’ai ouï cela deux fois, savoir, que la force est à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 13, 'Et c’est à toi, Seigneur, qu’appartient la gratuité; certainement tu rendras à chacun selon son oeuvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Psaume de David, lorsqu’il était dans le désert de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Ô Dieu! tu es mon Dieu Fort, je te cherche au point du jour; mon âme a soif de toi, ma chair te souhaite en cette terre déserte, altérée, et sans eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Pour voir ta force et ta gloire, ainsi que je t’ai contemplé dans ton Sanctuaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Car ta gratuité est meilleure que la vie; mes lèvres te loueront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Et ainsi je te bénirai durant ma vie, et j’élèverai mes mains en ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Mon âme est rassasiée comme de moelle et de graisse; et ma bouche te loue avec un chant de réjouissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Quand je me souviens de toi dans mon lit, je médite de toi durant les veilles de la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Parce que tu m’as été en secours, à cause de cela je me réjouirai à l’ombre de tes ailes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Mon âme s’est attachée à toi pour te suivre, et ta droite me soutient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Mais ceux-ci qui demandent que mon âme tombe en ruine, entreront au plus bas de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'On les détruira à coups d’épée; ils seront la portion des renards.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 12, 'Mais le Roi se réjouira en Dieu; et quiconque jure par lui s’en glorifiera; car la bouche de ceux qui mentent sera fermée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Psaume de David, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Ô Dieu! écoute ma voix quand je m’écrie; garde ma vie de la frayeur de l’ennemi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Tiens-moi caché loin du secret conseil des malins, et de l’assemblée tumultueuse des ouvriers d’iniquité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'Qui ont aiguisé leur langue comme une épée; et qui ont tiré pour leur flèche une parole amère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Afin de tirer contre celui qui est juste jusque dans le lieu où il se croyait en sûreté; ils tirent promptement contre lui; et ils n’ont point de crainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Ils s’assurent sur de mauvaises affaires, et tiennent des discours pour cacher des filets; et ils disent: Qui les verra?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Ils cherchent curieusement des méchancetés; ils ont sondé tout ce qui se peut sonder, même ce qui peut être au-dedans de l’homme, et au coeur le plus profond.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Mais Dieu a subitement tiré son trait contr’eux, et ils en ont été blessés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Et ils ont fait tomber sur eux-mêmes leur propre langue; ils iront çà et là; chacun les verra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Et tous les hommes craindront, et ils raconteront l’oeuvre de Dieu, et considéreront ce qu’il aura fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 11, 'Le juste se réjouira en l’Eternel, et se retirera vers lui; et tous ceux qui sont droits de coeur s’en glorifieront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Psaume de David, qui est un Cantique, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Ô Dieu! la louange t’ attend dans le silence en Sion, et le voeu te sera rendu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Tu y entends les requêtes, toute créature viendra jusqu’à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Les iniquités avaient prévalu sur moi, mais tu feras l’expiation de nos transgressions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Ô que bienheureux est celui que tu auras choisi et que tu auras fait approcher, afin qu’il habite dans tes parvis! Nous serons rassasiés des biens de ta maison, des biens du saint lieu de ton palais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Ô Dieu de notre délivrance, tu nous répondras par des choses terribles, faites avec justice, toi qui es l’assurance de tous les bouts de la terre, et des plus éloignés de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Il tient fermes les montagnes par sa force, et il est ceint de puissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Il apaise le bruit de la mer, le bruit de ses ondes, et l’émotion des peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Et ceux qui habitent aux bouts de la terre ont peur de tes prodiges; tu réjouis l’Orient et l’Occident.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Tu visites la terre, et après que tu l’as rendue altérée, tu l’enrichis amplement; le ruisseau de Dieu est plein d’eau; tu prépares leurs blés, après que tu l’as ainsi disposée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Tu arroses ses sillons, et tu aplanis ses rayons; tu l’amollis par la pluie menue, et tu bénis son germe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Tu couronnes l’année de tes biens, et tes ornières font couler la graisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Elles la font couler sur les loges du désert, et les côteaux sont ceints de joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 14, 'Les campagnes sont revêtues de troupeaux, et les vallées sont couvertes de froment; elles en triomphent, et elles en chantent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Cantique de Psaume, donné au maître chantre. Toute la terre, jetez des cris de réjouissance à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Psalmodiez la gloire de son Nom, rendez sa louange glorieuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Dites à Dieu: ô que tu es terrible en tes exploits! Tes ennemis te mentiront à cause de la grandeur de ta force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Toute la terre se prosternera devant toi, et te psalmodiera; elle psalmodiera ton Nom; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Venez, et voyez les oeuvres de Dieu: il est terrible en exploits sur les fils des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Il a fait de la mer une terre sèche; on a passé le fleuve à pied sec; et là nous nous sommes réjouis en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Il domine par sa puissance éternellement; ses yeux prennent garde sur les nations; les revêches ne se pourront point élever; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Peuples, bénissez notre Dieu, et faites retentir le son de sa louange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'C’est lui qui a remis notre âme en vie, et qui n’a point permis que nos pieds bronchassent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Car, ô Dieu! tu nous avais sondés, tu nous avais affinés comme on affine l’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Tu nous avais amenés aux filets, tu avais mis une étreinte en nos reins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Tu avais fait monter les hommes sur notre tête, et nous étions entrés dans le feu et dans l’eau; mais tu nous as fait entrer en un lieu fertile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'J’entrerai dans ta maison avec des holocaustes; et je te rendrai mes voeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'Lesquels mes lèvres ont proférés, et que ma bouche a prononcés, lorsque j’étais en détresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Je t’offrirai des holocaustes de bêtes moelleuses, avec la graisse des moutons, laquelle on fait fumer; je te sacrifierai des taureaux et des boucs; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Vous tous qui craignez Dieu, venez, écoutez, et je raconterai ce qu’il a fait à mon âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Je l’ai invoqué de ma bouche, et il a été exalté par ma langue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Si j’eusse médité quelque outrage dans mon coeur, le Seigneur ne m’eût point écouté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Mais certainement Dieu m’a écouté, et il a été attentif à la voix de ma supplication.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Béni soit Dieu qui n’a point rejeté ma supplication, et qui n’a point éloigné de moi sa gratuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Psaume de Cantique, donné au maître chantre, pour le chanter sur Neguinoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Que Dieu ait pitié de nous, et nous bénisse, et qu’il fasse luire sa face sur nous! Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Afin que ta voie soit connue en la terre, et ta délivrance parmi toutes les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Les peuples te célébreront, ô Dieu! tous les peuples te célébreront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Les peuples se réjouiront, et chanteront de joie; parce que tu jugeras les peuples en équité, et que tu conduiras les nations sur la terre; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Les peuples te célébreront, ô Dieu, tous les peuples te célébreront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'La terre produira son fruit; Dieu, notre Dieu, nous bénira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 8, 'Dieu nous bénira; et tous les bouts de la terre le craindront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Psaume de Cantique, de David, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Que Dieu se lève, et ses ennemis seront dispersés, et ceux qui le haïssent s’enfuiront de devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Tu les chasseras comme la fumée est chassée par le vent; comme la cire se fond devant le feu, ainsi les méchants périront devant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Mais les justes se réjouiront et s’égayeront devant Dieu, et tressailliront de joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Chantez à Dieu, psalmodiez son Nom, exaltez celui qui est monté sur les cieux; son Nom, est l’Eternel; et égayez-vous en sa présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Il est le père des orphelins, et le juge des veuves; Dieu est dans la demeure de sa Sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Dieu fait habiter en famille ceux qui étaient seuls; il délivre ceux qui étaient enchaînés, mais les revêches demeurent en une terre déserte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Ô Dieu! Quand tu sortis devant ton peuple, quand tu marchais par le désert; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'La terre trembla, et les cieux répandirent leurs eaux à cause de la présence de Dieu, ce mont de Sinaï trembla à cause de la présence de Dieu, du Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Ô Dieu! tu as fait tomber une pluie abondante sur ton héritage; et quand il était las, tu l’as rétabli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Ton troupeau s’y est tenu. Tu accommodes de tes biens celui qui est affligé, ô Dieu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Le Seigneur a donné de quoi parler; les messagers de bonnes nouvelles ont été une grande armée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Les Rois des armées s’en sont fuis, ils s’en sont fuis, et celle qui se tenait à la maison a partagé le butin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Quand vous auriez couché entre les chenets arrangés, vous serez comme les ailes d’un pigeon couvert d’argent, et dont les ailes sont comme la couleur jaune du fin or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Quand le Tout-puissant dissipa les Rois en cet héritage, il devint blanc, comme la neige qui est en Tsalmon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'La montagne de Dieu est un mont de Basan; une montagne élevée, un mont de Basan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Pourquoi lui insultez-vous, montagnes dont le sommet est élevé? Dieu a désiré cette montagne pour y habiter, et l’Eternel y demeurera à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'La chevalerie de Dieu se compte par vingt-mille, par des milliers redoublés; le Seigneur est au milieu d’eux; c’est un Sinaï en Sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Tu es monté en haut, tu as mené captifs les prisonniers, tu as pris des dons pour les distribuer entre les hommes, et même entre les rebelles, afin qu’ils habitent dans le lieu de l’Eternel Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Béni soit le Seigneur, qui tous les jours nous comble de ses biens; le Dieu Fort est notre délivrance; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Le Dieu Fort nous est un Dieu Fort pour nous délivrer, et les issues de la mort sont à l’Eternel le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Certainement Dieu écrasera la tête de ses ennemis, le sommet de la tête chevelue de celui qui marche dans ses vices.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Le Seigneur a dit: je ferai retourner les miens de Basan, je les ferai retourner du fond de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Afin que ton pied et la langue de tes chiens s’enfoncent dans le sang des ennemis, dans le sang de chacun d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Ô Dieu! Ils ont vu tes démarches dans le lieu saint, les démarches de mon Dieu Fort, mon Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Les chantres allaient devant, ensuite les joueurs d’instruments, et au milieu les jeunes filles, jouant du tambour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Bénissez Dieu dans les assemblées, bénissez le Seigneur, vous qui êtes de la source d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Là Benjamin le petit a dominé sur eux; les principaux de Juda ont été leur accablement de pierres: là ont dominé les principaux de Zabulon, et les principaux de Nephthali.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Ton Dieu a ordonné ta force. Donne force, ô Dieu; c’est toi qui nous as fait ceci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Dans ton Temple, à Jérusalem, les Rois t’amèneront des présents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Tance rudement les bêtes sauvages des roseaux, l’assemblée des forts taureaux, et les veaux des peuples, et ceux qui se montrent parés de lames d’argent. Il a dissipé les peuples qui ne demandent que la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'De grands Seigneurs viendront d’Egypte; Cus se hâtera d’étendre ses mains vers Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Royaumes de la terre, chantez à Dieu, psalmodiez au Seigneur; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Psalmodiez à celui qui est monté dans les cieux des cieux qui sont d’ancienneté; voilà, il fait retentir de sa voix un son véhément.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Attribuez la force à Dieu; sa magnificence est sur Israël, et sa force est dans les nuées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 36, 'Ô Dieu! Tu es redouté à cause de tes Sanctuaires. Le Dieu Fort d’Israël est celui qui donne la force et la puissance à son peuple; Béni soit Dieu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Psaume de David, donné au maître chantre, pour le chanter sur Sosannim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Délivre-moi, ô Dieu, car les eaux me sont entrées jusque dans l’âme. Je suis enfoncé dans un bourbier profond, dans lequel il n’y a point où prendre pied; je suis entré au plus profond des eaux, et le fil des eaux se débordant, m’emporte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Je suis las de crier, mon gosier en est asséché; mes yeux sont consumés pendant que j’attends après mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Ceux qui me haïssent sans cause, passent en nombre les cheveux de ma tête; ceux qui tâchent à me ruiner, et qui me sont ennemis à tort, se sont renforcés: j’ai alors rendu ce que je n’avais point ravi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Ô Dieu! Tu connais ma folie, et mes fautes ne te sont point cachées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Ô Seigneur Eternel des armées! que ceux qui se confient en toi, ne soient point rendus honteux à cause de moi; et que ceux qui te cherchent ne soient point confus à cause de moi, ô Dieu d’Israël!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Car pour l’amour de toi j’ai souffert l’opprobre, la honte a couvert mon visage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Je suis devenu étranger à mes frères, et un homme de dehors aux enfants de ma mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Car le zèle de ta maison m’a rongé, et les outrages de ceux qui t’outrageaient sont tombés sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Et j’ai pleuré en jeûnant: mais cela m’a été tourné en opprobre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'J’ai aussi pris un sac pour vêtement, mais je leur ai été un sujet de raillerie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Ceux qui sont assis à la porte discourent de moi, et je sers de chanson aux ivrognes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Mais, pour moi, ma requête s’adresse à toi, ô Eternel! Il y a un temps de ton bon plaisir, ô Dieu! selon la grandeur de ta gratuité. Réponds-moi selon la vérité de ta délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Délivre-moi du bourbier, fais que je n’y enfonce point, et que je sois délivré de ceux qui me haïssent, et des eaux profondes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Que le fil des eaux se débordant ne m’emporte point, et que le gouffre ne m’engloutisse point, et que le puits ne ferme point sa gueule sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Eternel! Exauce-moi, car ta gratuité est bonne; tourne la face vers moi selon la grandeur de tes compassions;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Et ne cache point ta face arrière de ton serviteur, car je suis en détresse: hâte-toi, exauce-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Approche-toi de mon âme, rachète-la; délivre-moi à cause de mes ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Tu connais toi-même mon opprobre, et ma honte, et mon ignominie; tous mes ennemis sont devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'L’opprobre m’a déchiré le coeur, et je suis languissant; j’ai attendu que quelqu’un eût compassion de moi, mais il n’y en a point eu: et j’ai attendu des consolateurs, mais je n’en ai point trouvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Ils m’ont au contraire donné du fiel pour mon repas; et dans ma soif ils m’ont abreuvé de vinaigre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Que leur table soit un filet tendu devant eux; et que ce qui tend à la prospérité leur soit en piège.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Que leurs yeux soient tellement obscurcis, qu’ils ne puissent point voir; et fais continuellement chanceler leurs reins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Répands ton indignation sur eux, et que l’ardeur de ta colère les saisisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Que leur palais soit désolé, et qu’il n’y ait personne qui habite dans leurs tentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Car ils persécutent celui que tu avais frappé, et font leurs contes de la douleur de ceux que tu avais blessés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Mets iniquité sur leur iniquité; et qu’ils n’entrent point en ta justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Qu’ils soient effacés du Livre de vie, et qu’ils ne soient point écrits avec les justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Mais pour moi, qui suis affligé, et dans la douleur, ta délivrance, ô Dieu! m’élèvera en une haute retraite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Je louerai le Nom de Dieu par des Cantiques, et je le magnifierai par une louange solennelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Et cela plaira plus à l’Eternel qu’un taureau, plus qu’un veau qui a des cornes, et l’ongle divisé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Les débonnaires le verront, et ils s’en réjouiront, et votre coeur vivra, le coeur, dis-je, de vous tous qui cherchez Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Car l’Eternel exauce les misérables, et ne méprise point ses prisonniers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Que les cieux et la terre le louent; que la mer et tout ce qui se meut en elle le louent aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Car Dieu délivrera Sion, et bâtira les villes de Juda; on y habitera, et on la possèdera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Et la postérité de ses serviteurs l’héritera, et ceux qui aiment son Nom demeureront en elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 37, '');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Psaume de David, pour faire souvenir, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Ô Dieu! hâte-toi de me délivrer; ô Dieu! hâte-toi de venir à mon secours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Que ceux qui cherchent mon âme soient honteux et rougissent; et que ceux qui prennent plaisir à mon mal soient repoussés en arrière, et soient confus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Que ceux qui disent: Aha! Aha! retournent en arrière pour la récompense de la honte qu’ils m’ont faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Que tous ceux qui te cherchent s’égayent et se réjouissent en toi; et que ceux qui aiment ta délivrance, disent toujours: Magnifié soit Dieu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 6, 'Or je suis affligé et misérable; ô Dieu! hâte-toi de venir vers moi; tu es mon secours et mon libérateur; ô Eternel! ne tarde point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Eternel! je me suis retiré vers toi, fais que je ne sois jamais confus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Délivre-moi par ta justice, et me garantis: incline ton oreille vers moi, et me mets en sûreté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Sois-moi pour un rocher de retraite, afin que je m’y puisse toujours retirer; tu as donné ordre de me mettre en sûreté; car tu es mon rocher, et ma forteresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Mon Dieu! délivre-moi de la main du méchant, de la main du pervers, et de l’oppresseur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Car tu es mon attente, Seigneur Eternel! et ma confiance dès ma jeunesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'J’ai été appuyé sur toi dès le ventre de ma mère; c’est toi qui m’as tiré hors des entrailles de ma mère; tu es le sujet continuel de mes louanges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'J’ai été à plusieurs comme un monstre; mais tu es ma forte retraite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Que ma bouche soit remplie de ta louange, et de ta magnificence chaque jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Ne me rejette point au temps de ma vieillesse; ne m’abandonne point maintenant que ma force est consumée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Car mes ennemis ont parlé de moi, et ceux qui épient mon âme ont pris conseil ensemble;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'Disant: Dieu l’a abandonné; poursuivez-le, et le saisissez; car il n’y a personne qui le délivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Ô Dieu! ne t’éloigne point de moi; mon Dieu hâte-toi de venir à mon secours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Que ceux qui sont ennemis de mon âme soient honteux et défaits; et que ceux qui cherchent mon mal soient enveloppés d’opprobre et de honte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Mais moi je vivrai toujours en espérance en toi, et je te louerai tous les jours davantage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Ma bouche racontera chaque jour ta justice, et ta délivrance, bien que je n’en sache point le nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Je marcherai par la force du Seigneur Eternel; je raconterai ta seule justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Ô Dieu! tu m’as enseigné dès ma jeunesse, et j’ai annoncé jusques à présent tes merveilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Je les ai annoncées jusqu’à la vieillesse, même jusques à la vieillesse toute blanche; ô Dieu! ne m’abandonne point jusqu’à ce que j’aie annoncé ton bras à cette génération, et ta puissance à tous ceux qui viendront après.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Car ta justice, ô Dieu! est haut élevée, parce que tu as fait de grandes choses. Ô Dieu qui est semblable à toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Qui m’ayant fait voir plusieurs détresses et plusieurs maux, m’as de nouveau rendu la vie, et m’as fait remonter hors des abîmes de la terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Tu accroîtras ma grandeur, et tu me consoleras encore.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Aussi, mon Dieu! je te célébrerai pour l’amour de ta vérité avec l’instrument de la musette; ô Saint d’Israël, je te psalmodierai avec la harpe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Mes lèvres et mon âme, que tu auras rachetée, chanteront de joie, quand je te psalmodierai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Ma langue aussi discourra chaque jour de ta justice, parce que ceux qui cherchent mon mal seront honteux et rougiront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Pour Salomon. Ô Dieu, donne tes jugements au Roi, et ta justice au fils du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Qu’il juge justement ton peuple, et équitablement ceux des tiens qui seront affligés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Que les montagnes portent la paix pour le peuple, et que les coteaux la portent en justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Qu’il fasse droit aux affligés d’entre le peuple; qu’il délivre les enfants du misérable, et qu’il froisse l’oppresseur!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Ils te craindront tant que le soleil et la lune dureront, dans tous les âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Il descendra comme la pluie sur le regain, et comme la même pluie sur l’herbe fauchée de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'En son temps le juste fleurira, et il y aura abondance de paix, jusqu’à ce qu’il n’y ait plus de lune.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Même il dominera depuis une mer jusqu’à l’autre, et depuis le fleuve jusqu’aux bouts de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Les habitants des déserts se courberont devant lui, et ses ennemis lécheront la poudre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Les Rois de Tarsis et des Iles lui présenteront des dons; les Rois de Scéba et de Séba lui apporteront des présents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Tous les Rois aussi se prosterneront devant lui, toutes les nations le serviront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Car il délivrera le misérable criant à lui, et l’affligé, et celui qui n’a personne qui l’aide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Il aura compassion du pauvre et du misérable, et il sauvera les âmes des misérables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Il garantira leur âme de la fraude et de la violence, et leur sang sera précieux devant ses yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Il vivra donc, et on lui donnera de l’or de Séba, et on fera des prières pour lui continuellement; et on le bénira chaque jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Une poignée de froment étant semée dans la terre, au sommet des montagnes, son fruit mènera du bruit comme les arbres du Liban; et les hommes fleuriront par les villes, comme l’herbe de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Sa renommée durera à toujours; sa renommée ira de père en fils tant que le soleil durera; et on se bénira en lui; toutes les nations le publieront bien- heureux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Béni soit l’Eternel Dieu, le Dieu d’Israël, qui seul fait des choses merveilleuses!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Béni soit aussi éternellement le Nom de sa gloire, et que toute la terre soit remplie de sa gloire. Amen! oui Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Ici finissent les prières de David, fils d’Isaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Psaume d’Asaph. Quoi qu’il en soit, Dieu est bon à Israël, savoir, à ceux qui sont nets de coeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Or quant à moi, mes pieds m’ont presque manqué, et il s’en est peu fallu que mes pas n’aient glissé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Car j’ai porté envie aux insensés, en voyant la prospérité des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Parce qu’il n’y a point d’angoisses en leur mort, mais leur force est en son entier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Ils ne sont point en travail avec les autres hommes, et ils ne sont point battus avec les autres hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'C’est pourquoi l’orgueil les environne comme un collier, et un vêtement de violence les couvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Les yeux leur sortent dehors à force de graisse; ils surpassent les desseins de leur coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Ils sont pernicieux, et parlent malicieusement d’opprimer; ils parlent comme placés sur un lieu élevé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Ils mettent leur bouche aux cieux, et leur langue parcourt la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'C’est pourquoi son peuple en revient là, quand on lui fait sucer l’eau à plein verre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Et ils disent: comment le Dieu Fort connaîtrait-il, et y aurait-il de la connaissance au Souverain?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Voilà, ceux-ci sont méchants, et étant à leur aise en ce monde, ils acquièrent de plus en plus des richesses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Quoi qu’il en soit, c’est en vain que j’ai purifié mon coeur, et que j’ai lavé mes mains dans l’innocence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Car j’ai été battu tous les jours, et mon châtiment revenait tous les matins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Mais quand j’ai dit: j’en parlerai ainsi; voilà, j’ai été infidèle à la génération de tes enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Toutefois j’ai tâché à connaître cela; mais cela m’a paru fort difficile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Jusques à ce que je sois entré au sanctuaire du Dieu Fort, et que j’aie considéré la fin de telles gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Quoi qu’il en soit, tu les as mis en des lieux glissants, tu les fais tomber dans des précipices.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Comment ont-ils été ainsi détruits en un moment? sont-ils défaillis? ont-ils été consumés d’épouvantements?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Ils sont comme un songe lorsqu’on s’est réveillé. Seigneur tu mettras en mépris leur ressemblance quand tu te réveilleras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Or quand mon coeur s’aigrissait, et que je me tourmentais en mes reins;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'J’étais alors stupide, et je n’avais aucune connaissance; j’étais comme une brute en ta présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Je serai donc toujours avec toi; tu m’as pris par la main droite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Tu me conduiras par ton conseil, et puis tu me recevras dans la gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Quel autre ai-je au Ciel? Or je n’ai pris plaisir sur la terre en rien qu’en toi seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Ma chair et mon coeur étaient consumés; mais Dieu est le rocher de mon coeur, et mon partage à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Car voilà, ceux qui s’éloignent de toi, périront; tu retrancheras tous ceux qui se détournent de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Mais pour moi, approcher de Dieu est mon bien; j’ai mis toute mon espérance au Seigneur Eternel, afin que je raconte tous tes ouvrages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Maskil d’Asaph. Ô Dieu, pourquoi nous as-tu rejetés pour jamais? et pourquoi es-tu enflammé de colère contre le troupeau de ta pâture?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Souviens-toi de ton assemblée que tu as acquise d’ancienneté. Tu t’es approprié cette montagne de Sion, sur laquelle tu as habité, afin qu’elle fût la portion de ton héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Avance tes pas vers les masures de perpétuelle durée; l’ennemi a tout renversé au lieu Saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Tes adversaires ont rugi au milieu de tes Synagogues; ils ont mis leurs enseignes pour enseignes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Là chacun se faisait voir élevant en haut les haches à travers le bois entrelacé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Et maintenant avec des coignées et des marteaux ils brisent ensemble ses entaillures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Ils ont mis en feu tes sanctuaires, et ont profané le Pavillon dédié à ton Nom, l’abattant par terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Ils ont dit en leur coeur: saccageons-les tous ensemble; ils ont brûlé toutes les Synagogues du Dieu Fort sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Nous ne voyons plus nos enseignes; il n’y a plus de Prophètes; et il n’y a aucun avec nous qui sache jusques à quand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Ô Dieu! jusques à quand l’adversaire te couvrira-t-il d’opprobres? L’ennemi méprisera-t-il ton Nom à jamais?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Pourquoi retires-tu ta main, même ta droite? Consume-les en la tirant du milieu de ton sein.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Or Dieu est mon Roi d’ancienneté, faisant des délivrances au milieu de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Tu as fendu la mer par ta force; tu as cassé les têtes des baleines sur les eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Tu as brisé les têtes du Léviathan, tu l’as donné en viande au peuple des habitants des déserts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Tu as ouvert la fontaine et le torrent, tu as desséché les grosses rivières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'A toi est le jour, à toi aussi est la nuit; tu as établi la lumière et le soleil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Tu as posé toutes les limites de la terre; tu as formé l’Eté et l’Hiver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Souviens-toi de ceci, que l’ennemi a blasphémé l’Eternel, et qu’un peuple insensé a outragé ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'N’abandonne point à la troupe de telles gens l’âme de ta tourterelle, n’oublie point à jamais la troupe de tes affligés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Regarde à ton alliance; car les lieux ténébreux de la terre sont remplis de cabanes de violence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Ne permets pas que celui qui est foulé s’en retourne tout confus, et fais que l’affligé et le pauvre louent ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Ô Dieu! lève-toi, défends ta cause, souviens-toi de l’opprobre qui t’est fait tous les jours par l’insensé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'N’oublie point le cri de tes adversaires; le bruit de ceux qui s’élèvent contre toi monte continuellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Psaume d’Asaph, Cantique donné au maître chantre, pour le chanter sur Altasheth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Ô Dieu! nous t’avons célébré; nous t’avons célébré; et ton Nom était près de nous; on a raconté tes merveilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Quand j’aurai accepté l’assignation, je jugerai droitement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Le pays s’écoulait avec tous ceux qui y habitent; mais j’ai affermi ses piliers; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'J’ai dit aux insensés: n’agissez point follement; et aux méchants: ne faites point les superbes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'N’affectez point la domination, et ne parlez point avec fierté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Car l’élévation ne vient point d’Orient, ni d’Occident, ni du désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Car c’est Dieu qui gouverne; il abaisse l’un, et élève l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Même il y a une coupe en la main de l’Eternel, et le vin rougit dedans; il est plein de mixtion, et Dieu en verse; certainement tous les méchants de la terre en suceront et boiront les lies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Mais moi, j’en ferai le récit à toujours, je psalmodierai au Dieu de Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 11, 'J’humilierai tous les méchants,; mais les justes seront élevés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Psaume d’Asaph, Cantique donné au maître chantre, pour le chanter sur Neguinoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Dieu est connu en Judée, sa renommée est grande en Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Et son Tabernacle est en Salem, et son domicile en Sion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Là il a rompu les arcs étincelants, le bouclier, l’épée, et la bataille; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Tu es resplendissant, et plus magnifique que les montagnes de ravage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Les plus courageux ont été étourdis, ils ont été dans un profond assoupissement, et aucun de ces hommes vaillants n’a trouvé ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Ô Dieu de Jacob, les chariots et les chevaux ont été assoupis quand tu les as tancés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Tu es terrible, toi; et qui est-ce qui pourra subsister devant toi, dès que ta colère paraît?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Tu as fait entendre des cieux le jugement; la terre en a eu peur, et s’est tenue dans le silence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Quand tu te levas, ô Dieu! pour faire jugement, pour délivrer tous les débonnaires de la terre; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Certainement la colère de l’homme retournera à ta louange: tu garrotteras le reste de ces hommes violents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Vouez, et rendez vos voeux à l’Eternel votre Dieu, vous tous qui êtes autour de lui, et qu’on apporte des dons au Redoutable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 13, 'Il retranche la vie des Conducteurs; il est redoutable aux Rois de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Psaume d’Asaph, donné au maître chantre, d’entre les enfants de Jéduthun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Ma voix s’adresse à Dieu, et je crierai; ma voix s’adresse à Dieu, et il m’écoutera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'J’ai cherché le Seigneur au jour de ma détresse: ma plaie coulait durant la nuit, et ne cessait point; mon âme refusait d’être consolée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Je me souvenais de Dieu, et je me tourmentais: je faisais bruit, et mon esprit était transi; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Tu avais empêché mes yeux de dormir, j’étais tout troublé, et ne pouvais parler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Je pensais aux jours d’autrefois, et aux années des siècles passés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Il me souvenait de ma mélodie de nuit, je méditais en mon coeur, et mon esprit cherchait diligemment, en disant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Le Seigneur m’a-t-il rejeté pour toujours? et ne continuera-t-il plus à m’avoir pour agréable?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Sa gratuité est-elle disparue pour jamais? Sa parole a-t-elle pris fin pour tout âge?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Le Dieu Fort a-t-il oublié d’avoir pitié? a-t-il en colère fermé la porte de ses compassions? Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Puis j’ai dit: c’est bien ce qui m’affaiblit; mais la droite du Souverain change.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Je me suis souvenu des exploits de l’Eternel; je me suis, dis-je, souvenu de tes merveilles d’autrefois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Et j’ai médité toutes tes oeuvres, et j’ai discouru de tes exploits, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Ô Dieu! ta voie est dans ton Sanctuaire. Qui est Dieu Fort, et grand comme Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Tu es le Dieu Fort qui fais des merveilles; tu as fait connaître ta force parmi les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Tu as délivré par ton bras ton peuple, les enfants de Jacob et de Joseph; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Les eaux t’ont vu, ô Dieu! les eaux t’ont vu, et ont tremblé, même les abîmes en ont été émus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Les nuées ont versé un déluge d’eau; les nuées ont fait retentir leur son; tes traits aussi ont volé çà et là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Le son de ton tonnerre était accompagné de croulements, les éclairs ont éclairé la terre habitable, la terre en a été émue et en a tremblé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Ta voie a été par la mer; et tes sentiers dans les grosses eaux; et néanmoins tes traces n’ont point été connues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 21, 'Tu as mené ton peuple comme un troupeau, sous la conduite de Moïse et d’Aaron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Maskil d’Asaph. Mon peuple, écoute ma Loi, prêtez vos oreilles aux paroles de ma bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'J’ouvrirai ma bouche en similitudes: je manifesterai les choses notables du temps d’autrefois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Lesquelles nous avons ouïes et connues, et que nos pères nous on racontées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'Nous ne les cèlerons point à leurs enfants, et ils raconteront à la génération à venir les louanges de l’Eternel, et sa force, et ses merveilles qu’il a faites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Car il a établi le témoignage en Jacob, et il a mis la Loi en Israël; et il donna charge à nos pères de les faire entendre à leurs enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'Afin que la génération à venir, les enfants, dis-je, qui naîtraient, les connut, et qu’ils se missent en devoir de les raconter à leurs enfants;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Et afin qu’ils missent leur confiance en Dieu, et qu’ils n’oubliassent point les exploits du Dieu Fort, et qu’ils gardassent ses commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'Et qu’ils ne fussent point, comme leurs pères, une génération revêche et rebelle, une génération qui n’a point soumis son coeur, et l’esprit de laquelle n’a point été fidèle au Dieu Fort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Les enfants d’Ephraïm armés entre les archers, ont tourné le dos le jour de la bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Ils n’ont point gardé l’alliance de Dieu, et ont refusé de marcher selon sa Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Et ils ont mis en oubli ses exploits et ses merveilles qu’il leur avait fait voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Il a fait des miracles en la présence de leurs pères au pays d’Egypte, au territoire de Tsohan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Il a fendu la mer, et les a fait passer au travers, et il a fait arrêter les eaux comme un monceau de pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Et il les a conduits de jour par la nuée, et toute la nuit par une lumière de feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Il a fendu les rochers au désert, et leur a donné abondamment à boire, comme s’il eût puisé des abîmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Il a fait, dis-je, sortir des ruisseaux de la roche, et en a fait découler des eaux comme des rivières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Toutefois ils continuèrent à pécher contre lui, irritant le Souverain au désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'Et ils tentèrent le Dieu Fort dans leurs coeurs, en demandant de la viande qui flattât leur appétit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'Ils parlèrent contre Dieu, disant: le Dieu Fort nous pourrait- il dresser une table en ce désert?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Voilà, dirent-ils, il a frappé le rocher, et les eaux en sont découlées, et il en est sorti des torrents abondamment, mais pourrait-il aussi nous donner du pain? apprêterait-il bien de la viande à son peuple?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'C’est pourquoi l’Eternel les ayant ouïs, se mit en grande colère, et le feu s’embrasa contre Jacob, et sa colère s’excita contre Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'Parce qu’ils n’avaient point cru en Dieu, et ne s’étaient point confiés en sa délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Bien qu’il eût donné commandement aux nuées d’en haut, et qu’il eût ouvert les portes des cieux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'Et qu’il eût fait pleuvoir la manne sur eux afin qu’ils en mangeassent, et qu’il leur eût donné le froment des cieux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Tellement que chacun mangeait du pain des puissants. Il leur envoya donc de la viande pour s’en rassasier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Il excita dans les cieux le vent d’Orient, et il amena par sa force le vent du midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Et il fit pleuvoir sur eux de la chair comme de la poussière, et des oiseaux volants, en une quantité pareille au sable de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Et il la fit tomber au milieu de leur camp, et autour de leurs pavillons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Et ils en mangèrent, et en furent pleinement rassasiés, car il avait accompli leur souhait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Mais ils n’en avaient pas encore perdu l’envie, et leur viande était encore dans leur bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'Quand la colère de Dieu s’excita contre eux, et qu’il mit à mort les gras d’entre eux, et abattit les gens d’élite d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Nonobstant cela, ils péchèrent encore, et n’ajoutèrent point de foi à ses merveilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'C’est pourquoi il consuma soudainement leurs jours, et leurs années promptement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Quand il les mettait à mort, alors ils le recherchaient, ils se repentaient, et ils cherchaient le Dieu Fort dès le matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'Et ils se souvenaient que Dieu était leur rocher, et que le Dieu Fort et Souverain était celui qui les délivrait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Mais ils faisaient beau semblant de leur bouche, et ils lui mentaient de leur langue;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'Car leur coeur n’était point droit envers lui, et ils ne furent point fidèles en son alliance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Toutefois, comme il est pitoyable, il pardonna leur iniquité, tellement qu’il ne les détruisit point, mais il apaisa souvent sa colère, et n’émut point toute sa fureur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Et il se souvint qu’ils n’étaient que chair, qu’un vent qui passe, et qui ne revient point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Combien de fois l’ont-ils irrité au désert, et combien de fois l’ont-ils ennuyé dans ce lieu inhabitable?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Car coup sur coup ils tentaient le Dieu Fort; et bornaient le Saint d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Ils ne se sont point souvenus de sa main, ni du jour qu’il les avait délivrés de la main de celui qui les affligeait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'Ils ne se sont point souvenus de celui qui avait fait ses signes en Egypte, et ses miracles au territoire de Tsohan:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Et qui avait changé en sang leurs rivières et leurs ruisseaux, afin qu’ils n’en pussent point boire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Et qui avait envoyé contre eux une mêlée de bêtes, qui les mangèrent; et des grenouilles, qui les détruisirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Et qui avait donné leurs fruits aux vermisseaux, et leur travail aux sauterelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Qui avait détruit leurs vignes par la grêle, et leurs sycomores par les orages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Et qui avait livré leur bétail à la grêle, et leurs troupeaux aux foudres étincelantes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Qui avait envoyé sur eux l’ardeur de sa colère, grande colère, indignation et détresse, qui sont un envoi de messagers de maux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Qui avait dressé le chemin à sa colère, et n’avait point retiré leur âme de la mort; et qui avait livré leur bétail à la mortalité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Et qui avait frappé tout premier-né en Egypte, les prémices de la vigueur dans les tentes de Cam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Qui avait fait partir son peuple comme des brebis; et qui l’avait mené par le désert comme un troupeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Et qui les avait conduits sûrement, et sans qu ils eussent aucune frayeur, là où la mer couvrit leurs ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Et qui les avait introduits en la contrée de sa Sainteté, savoir en cette montagne que sa droite a conquise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Et qui avait chassé de devant eux les nations qu’il leur a fait tomber en lot d’héritage, et avait fait habiter les Tribus d’Israël dans les tentes de ces nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Mais ils ont tenté et irrité le Dieu Souverain, et n’ont point gardé ses témoignages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Et ils se sont retirés en arrière, et se sont portés infidèlement, ainsi que leurs pères; ils se sont renversés comme un arc qui trompe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Et ils l’ont provoqué à la colère par leurs hauts lieux, et l’ont ému à la jalousie par leurs images taillées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Dieu l’a ouï, et s’est mis en grande colère, et il a fort méprisé Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Et il a abandonné le pavillon de Silo, le Tabernacle où il habitait entre les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Et il a livré en captivité sa force et son ornement entre les mains de l’ennemi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Et il a livré son peuple à l’épée et s’est mis en grande colère contre son héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Le feu a consumé leurs gens d’élite, et leurs vierges n’ont point été louées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Leurs Sacrificateurs sont tombés par l’épée, et leurs veuves ne les ont point pleuré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Puis le Seigneur s’est réveillé comme un homme qui se serait endormi, et comme un puissant homme qui s’écrie ayant encore le vin dans la tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'Et il a frappé ses adversaires par derrière, et les a mis en opprobre perpétuel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Mais il a dédaigné le Tabernacle de Joseph, et n’a point choisi la Tribu d’Ephraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Mais il a choisi la Tribu de Juda, la montagne de Sion, laquelle il aime;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Et il a bâti son Sanctuaire comme des bâtiments haut élevés, et l’a établi comme la terre qu’il a fondée pour toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Et il a choisi David, son serviteur, et l’a pris des parcs des brebis;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Il l’a pris, dis-je, d’après les brebis qui allaitent, et l’a amené pour paître Jacob son peuple, et Israël son héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Aussi les a-t-il fait repus selon l’intégrité de son coeur, et conduits par la sage direction de ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Psaume d’Asaph. Ô Dieu! les nations sont entrées dans ton héritage; on a profané le Temple de ta Sainteté, on a mis Jérusalem en monceaux de pierres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'On a donné les corps morts de tes serviteurs pour viande aux oiseaux des cieux, et la chair de tes bien-aimés aux bêtes de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'On a répandu leur sang comme de l’eau à l’entour de Jérusalem, et il n’y avait personne qui les ensevelît.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Nous avons été en opprobre à nos voisins, en moquerie et en raillerie à ceux qui habitent autour de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Jusques à quand, ô Eternel, te courrouceras-tu à jamais? Ta jalousie s’embrasera-t-elle comme un feu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Répands ta fureur sur les nations qui ne te connaissent point, et sur les Royaumes qui n’invoquent point ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Car on a dévoré Jacob, et on a ravagé ses demeures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Ne rappelle point devant nous les iniquités commises ci-devant; et que tes compassions nous préviennent; car nous sommes devenus fort chétifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Ô Dieu de notre délivrance, aide-nous pour l’amour de la gloire de ton Nom, et nous délivre; et pardonne-nous nos péchés pour l’amour de ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Pourquoi diraient les nations: Où est leur Dieu? Que la vengeance du sang de tes serviteurs, qui a été répandu, soit manifestée parmi les nations en notre présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Que le gémissement des prisonniers vienne en ta présence, mais réserve, selon la grandeur de ta puissance, ceux qui sont déjà voués à la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Et rends à nos voisins, dans leur sein, sept fois au double l’opprobre qu’ils t’ont fait, ô Eternel!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Mais nous, ton peuple, et le troupeau de ta pâture, nous te célébrerons à toujours d’âge en âge, et nous raconterons ta louange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Psaume d’Asaph, donné au maître chantre, pour le chanter sur Sosannim-héduth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Toi qui pais Israël, prête l’oreille, toi qui mènes Joseph comme un troupeau, toi qui es assis entre les Chérubins, fais reluire ta splendeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Réveille ta puissance au-devant d’Ephraïm, de Benjamin, et de Manassé; et viens pour notre délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Ô Dieu! ramène-nous, et fais reluire ta face; et nous serons délivrés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Ô Eternel, Dieu des armées, jusques à quand seras-tu irrité contre la requête de ton peuple?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Tu les as nourris de pain de larmes, et tu les as abreuvés de pleurs à grande mesure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Tu nous as mis pour un sujet de dispute entre nos voisins, et nos ennemis se moquent de nous entre eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Ô Dieu des armées ramène-nous, et fais reluire ta face; et nous serons délivrés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Tu avais transporté une vigne hors d’Egypte; tu avais chassé les nations, et tu l’avais plantée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Tu avais préparé une place devant elle, tu lui avais fait prendre racine, et elle avait rempli la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Les montagnes étaient couvertes de son ombre, et ses rameaux étaient comme de hauts cèdres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Elle avait étendu ses branches jusqu’à la mer, et ses rejetons jusqu’au fleuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Pourquoi as-tu rompu ses cloisons, de sorte que tous les passants en ont cueilli les raisins?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Les sangliers de la forêt l’ont détruite, et toutes sortes de bêtes sauvages l’ont broutée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Ô Dieu des armées retourne, je te prie; regarde des cieux, vois, et visite cette vigne;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Et le plant que ta droite avait planté, et les provins que tu avais fait devenir forts pour toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Elle est brûlée par feu, elle est retranchée; ils périssent dès que tu te montres pour les tancer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Que ta main soit sur l’homme de ta droite, sur le fils de l’homme que tu t’es fortifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Et nous ne nous retirerons point arrière de toi. Rends-nous la vie, et nous invoquerons ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 20, 'Ô Eternel! Dieu des armées, ramène-nous, et fais reluire ta face; et nous serons délivrés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Psaume d’Asaph, donné au maître chantre, pour le chanter sur Guittith.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Chantez gaiement à Dieu, qui est notre force; jetez des cris de réjouissance en l’honneur du Dieu de Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Entonnez le Cantique, prenez le tambour, la harpe agréable, et la musette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Sonnez la trompette en la nouvelle lune, en la solennité, pour le jour de notre fête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Car c’est un statut à Israël, une ordonnance du Dieu de Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Il établit cela pour témoignage en Joseph, lorsqu’il sortit contre le pays d’Egypte, où j’ouïs un langage que je n’entendais pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'J’ai retiré, dit-il, ses épaules de dessous la charge, et ses mains ont été retirées arrière des pots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Tu as crié étant en détresse, et je t’en ai retiré; je t’ai répondu du milieu de la nue où gronde le tonnerre; je t’ai éprouvé auprès des eaux de Mériba; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Ecoute mon peuple, je te sommerai; Israël ô si tu m’écoutais!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Il n’y aura point au milieu de toi de dieu étranger, et tu ne te prosterneras point devant les dieux des étrangers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Je suis l’Eternel ton Dieu, qui t’ai fait monter hors du pays d’Egypte; dilate ta bouche, et je l’emplirai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Mais mon peuple n’a point écouté ma voix, et Israël ne m’a point eu à gré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'C’est pourquoi je les ai abandonnés à la dureté de leur coeur, et ils ont marché selon leurs conseils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Ô si mon peuple m’eût écouté! si Israël eût marché dans mes voies!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'J’eusse en un instant abattu leurs ennemis, et j’eusse tourné ma main contre leurs adversaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Ceux qui haïssent l’Eternel lui auraient menti, et le temps de mon peuple eût été à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 17, 'Et Dieu l’eût nourri de la moelle du froment; et je t’eusse, dit-il, rassasié du miel qui distille de la roche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Psaume d’Asaph. Dieu assiste dans l’assemblée des forts, il juge au milieu des Juges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Jusques à quand jugerez-vous injustement, et aurez-vous égard à l’apparence de la personne des méchants? Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Faites droit à celui qu’on opprime, et à l’orphelin; faites justice à l’affligé et au pauvre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Délivrez celui qu’on maltraite et le misérable, retirez-le de la main des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Ils ne connaissent ni n’entendent rien; ils marchent dans les ténèbres, tous les fondements de la terre sont ébranlés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'J’ai dit: vous êtes des dieux, et vous êtes tous enfants du Souverain;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Toutefois vous mourrez comme les hommes, et vous qui êtes les principaux vous tomberez comme un autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Ô Dieu! lève-toi, juge la terre; car tu auras en héritage toutes les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Cantique et Psaume d’Asaph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Ô Dieu! ne garde point le silence, ne te tais point, et ne te tiens point en repos, ô Dieu Fort!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Car voici, tes ennemis bruient; et ceux qui te haïssent ont levé la tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Ils ont consulté finement en secret contre ton peuple, et ils ont tenu conseil contre ceux qui se sont retirés vers toi pour se cacher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Ils ont dit: venez, et détruisons-les, en sorte qu’ils ne soient plus une nation, et qu’on ne fasse plus mention du nom d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Car ils ont consulté ensemble d’un même esprit; ils ont fait alliance contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Les tentes des Iduméens, des Ismaélites, des Moabites, et des Hagaréniens;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'les Guébalites, les Hammonites, les Hamalécites, et les Philistins, avec les habitants de Tyr.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Assur aussi s’est joint avec eux; ils ont servi de bras aux enfants de Lot: Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Fais-leur comme tu fis à Madian, comme à Sisera, et comme à Jabin, auprès du torrent de Kison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Qui furent défaits à Hen-dor, et servirent de fumier à la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Fais que les principaux d’entr’eux soient comme Horeb, et comme Zéeb; et que tous leurs Princes soient comme Zébah et Tsalmunah;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Parce qu’ils ont dit: conquérons-nous les habitations agréables de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Mon Dieu! rends-les semblables à une boule, et au chaume chassé par le vent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Comme le feu brûle une forêt, et comme la flamme embrase les montagnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Poursuis-les ainsi par ta tempête, et épouvante-les par ton tourbillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Couvre leurs visages d’ignominie, afin qu’on cherche ton Nom, ô Eternel!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Qu’ils soient honteux et épouvantés à jamais, qu’ils rougissent, et qu’ils périssent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 19, 'Afin qu’on connaisse que toi seul, qui as nom l’Eternel, es Souverain sur toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Psaume des enfants de Coré, donné au maître chantre, pour le chanter sur Guittith.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Eternel des armées, combien sont aimables tes Tabernacles!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Mon âme désire ardemment, et même elle défaut après les parvis de l’Eternel; mon coeur et ma chair tressaillent de joie après le Dieu Fort et vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Le passereau même a bien trouvé sa maison, et l’hirondelle son nid, où elle a mis ses petits; tes autels, ô Eternel des armées! mon Roi, et mon Dieu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Ô que bien-heureux sont ceux qui habitent en ta maison, et qui te louent incessamment! Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Ô que bien-heureux est l’homme dont la force est en toi, et ceux au coeur desquels sont les chemins battus!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Passant par la vallée de Baca ils la réduisent en fontaine; la pluie aussi comble les marais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Ils marchent avec force pour se présenter devant Dieu en Sion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Eternel Dieu des armées, écoute ma requête; Dieu de Jacob, prête l’oreille; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Ô Dieu, notre bouclier, vois, et regarde la face de ton Oint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Car mieux vaut un jour en tes parvis, que mille ailleurs. J’aimerais mieux me tenir à la porte en la maison de mon Dieu, que de demeurer dans les tentes des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Car l’Eternel Dieu nous est un soleil et un bouclier; l’Eternel donne la grâce et la gloire, et il n’épargne aucun bien à ceux qui marchent dans l’intégrité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 13, 'Eternel des armées, ô que bien-heureux est l’homme qui se confie en toi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Psaume des enfants de Coré, donné au maître chantre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Eternel, tu t’es apaisé envers ta terre, tu as ramené et mis en repos les prisonniers de Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Tu as pardonné l’iniquité de ton peuple, et tu as couvert tous leurs péchés; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Tu as retiré toute ta colère, tu es revenu de l’ardeur de ton indignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Ô Dieu de notre délivrance, rétablis-nous, et fais cesser la colère que tu as contre nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Seras-tu courroucé à toujours contre nous? feras-tu durer ta colère d’âge en âge?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Ne reviendras-tu pas à nous rendre la vie, afin que ton peuple se réjouisse en toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Eternel, fais-nous voir ta miséricorde, et accorde-nous ta délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'J’écouterai ce que dira le Dieu Fort, l’Eternel; car il parlera de paix à son peuple et à ses bien-aimés, mais que jamais ils ne retournent à leur folie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Certainement sa délivrance est proche de ceux qui le craignent, afin que la gloire habite en notre pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'La bonté et la vérité se sont rencontrées; la justice et la paix se sont entre-baisées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'La vérité germera de la terre, et la justice regardera des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'L’Eternel aussi donnera le bien, tellement que notre terre rendra son fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 14, 'La justice marchera devant lui, et il la mettra partout où il passera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Requête de David. Eternel, écoute, réponds-moi; car je suis affligé et misérable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Garde mon âme, car je suis un de tes bien-aimés; ô toi mon Dieu, délivre ton serviteur, qui se confie en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Seigneur, aie pitié de moi, car je crie à toi tout le jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Réjouis l’âme de ton serviteur; car j’élève mon âme à toi, Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Parce que toi, ô Eternel! es bon et clément, et d’une grande bonté envers tous ceux qui t’invoquent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Eternel, prête l’oreille à ma prière, et sois attentif à la voix de mes supplications.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Je t’invoque au jour de ma détresse, car tu m’exauces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Seigneur, il n’y a aucun entre les dieux qui soit semblable à toi, et il n’y a point de telles oeuvres que les tiennes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Seigneur, toutes les nations que tu as faites viendront, et se prosterneront devant toi, et glorifieront ton Nom;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Car tu es grand, et tu fais des choses merveilleuses, tu es Dieu, toi seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Eternel! enseigne-moi tes voies, et je marcherai en ta vérité; lie mon coeur à la crainte de ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Seigneur mon Dieu, je te célébrerai de tout mon coeur, et je glorifierai ton Nom à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Car ta bonté est grande envers moi, et tu as retiré mon âme d’un sépulcre profond.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Ô Dieu! des gens orgueilleux se sont élevés contre moi, et une bande de gens terribles, qui ne t’ont point eu devant leurs yeux, a cherché ma vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Mais toi, Seigneur, tu es le Dieu Fort, pitoyable, miséricordieux, tardif à colère, et abondant en bonté et en vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Tourne-toi vers moi, et aie pitié de moi; donne ta force à ton serviteur, délivre le fils de ta servante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Montre-moi quelque signe de ta faveur, et que ceux qui me haïssent le voient, et soient honteux, parce que tu m’auras aidé, ô Eternel! et m’auras consolé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Psaume de cantique des enfants de Coré. Sa fondation est dans les saintes montagnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'L’Eternel aime les portes de Sion, plus que tous les Tabernacles de Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Ce qui se dit de toi, Cité de Dieu, sont des choses glorieuses; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Je ferai mention de Rahab et de Babylone entre ceux qui me connaissent; voici la Palestine, et Tyr, et Cus. Celui-ci, disait- on, est né là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Mais de Sion il sera dit: celui-ci et celui-là y est né; et le Souverain lui-même l’établira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Quand l’Eternel enregistrera les peuples, il dénombrera aussi ceux- là, et il dira: celui-ci est né là; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Et les chantres, de même que les joueurs de flûtes, et toutes mes sources seront en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Maskil d’Héman Ezrahite, qui est un Cantique de Psaume, donné au maître chantre d’entre les enfants de Coré, pour le chanter sur Mahalath-lehannoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Eternel! Dieu de ma délivrance, je crie jour et nuit devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Que ma prière vienne en ta présence; ouvre ton oreille à mon cri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Car mon âme a tout son saoul de maux, et ma vie est venue jusqu’au sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'On m’a mis au rang de ceux qui descendent en la fosse; je suis devenu comme un homme qui n’a plus de vigueur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Placé parmi les morts, comme les blessés à mort couchés au sépulcre, desquels il ne te souvient plus, et qui sont retranchés par ta main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Tu m’as mis en une fosse des plus basses, dans des lieux ténébreux, dans des lieux profonds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Ta fureur s’est jetée sur moi, et tu m’as accablé de tous tes flots; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Tu as éloigné de moi ceux de qui j’étais connu, tu m’as mis en une extrême abomination devant eux; je suis enfermé tellement, que je ne puis sortir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Mon oeil languit d’affliction; Eternel! je crie à toi tout le jour, j’étends mes mains vers toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Feras-tu un miracle envers les morts? ou les trépassés se relèveront-ils pour te célébrer? Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Racontera-t-on ta miséricorde dans le sépulcre? et ta fidélité dans le tombeau?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Connaîtra-t-on tes merveilles dans les ténèbres; et ta justice au pays d’oubli?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Mais moi, ô Eternel! je crie à toi, ma prière te prévient dès le matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Eternel! pourquoi rejettes-tu mon âme, pourquoi caches-tu ta face de moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Je suis affligé et comme rendant l’esprit dès ma jeunesse; j’ai été exposé à tes terreurs, et je ne sais où j’en suis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Les ardeurs de ta colère sont passées sur moi, et tes frayeurs m’ont retranché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Ils m’ont tout le jour environné comme des eaux, ils m’ont entouré tous ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 19, 'Tu as éloigné de moi mon ami, même mon intime ami, et ceux de qui je suis connu me sont des ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Maskil d’Ethan Ezrahite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Je chanterai les bontés de l’Eternel à toujours; je manifesterai de ma bouche ta fidélité d’âge en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Car j’ai dit: ta bonté continue à toujours, comme les cieux, tu as établi en eux ta fidélité quand tu as dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'J’ai traité alliance avec mon élu, j’ai fait serment à David mon serviteur, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'J’établirai ta race à toujours, et j’affermirai ton trône d’âge en âge; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Et les cieux célèbrent tes merveilles, ô Eternel! ta fidélité aussi est célébrée dans l’assemblée des Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Car qui est-ce au-dessus des nues qui soit égal à l’Eternel? Qui est semblable à l’Eternel entre les fils des forts?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Le Dieu Fort se rend extrêmement terrible dans le Conseil secret des Saints, il est plus redouté que tous ceux qui sont à l’entour de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Ô Eternel Dieu des armées, qui est semblable à toi, puissant Eternel? aussi ta fidélité est à l’entour de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Tu as puissance sur l’élévation des flots de la mer; quand ses vagues s’élèvent, tu les fais rabaisser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Tu as abattu Rahab comme un homme blessé à mort; tu as dissipé tes ennemis par le bras de ta force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'A toi sont les cieux, à toi aussi est la terre; tu as fondé la terre habitable, et tout ce qui est en elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Tu as créé l’Aquilon et le Midi; Tabor et Hermon se réjouissent en ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Tu as un bras puissant, ta main est forte, et ta droite est haut élevée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'La justice et l’équité sont la base de ton trône; la gratuité et la vérité marchent devant ta face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Ô que bienheureux est le peuple qui sait ce que c’est que du cri de réjouissance! Ils marcheront, ô Eternel! à la clarté de ta face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Ils s’égayeront tout le jour en ton Nom, et ils se glorifieront de ta justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Parce que tu es la gloire de leur force; et notre pouvoir est distingué par ta faveur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Car notre bouclier est l’Eternel, et notre Roi est le Saint d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Tu as autrefois parlé en vision touchant ton bien-aimé, et tu as dit: J’ai ordonné mon secours en faveur d’un homme vaillant; j’ai élevé l’élu d’entre le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'J’ai trouvé David mon serviteur, je l’ai oint de ma sainte huile;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Ma main sera ferme avec lui, et mon bras le renforcera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'L’ennemi ne le rançonnera point, et l’inique ne l’affligera point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Mais je froisserai devant lui ses adversaires, et je détruirai ceux qui le haïssent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Ma fidélité et ma bonté seront avec lui; et sa gloire sera élevée en mon Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Et je mettrai sa main sur la mer, et sa droite sur les fleuves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Il m’invoquera, disant: Tu es mon Père; mon Dieu Fort, et le Rocher de ma délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Aussi je l’établirai l’aîné et le souverain sur les Rois de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Je lui garderai ma bonté à toujours, et mon alliance lui sera assurée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Je rendrai éternelle sa postérité, et je ferai que son trône sera comme les jours des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Mais si ses enfants abandonnent ma Loi, et ne marchent point selon mes ordonnances;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'S’ils violent mes statuts, et qu’ils ne gardent point mes commandements;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Je visiterai de verge leur transgression, et de plaie leur iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Mais je ne retirerai point de lui ma bonté, et je ne lui fausserai point ma foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Je ne violerai point mon alliance, et je ne changerai point ce qui est sorti de mes lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'J’ai une fois juré par ma sainteté; (si je mens jamais à David;)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Que sa race sera à toujours, et que son trône sera comme le soleil, en ma présence:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Qu’il sera affermi à toujours comme la lune; et il y en aura dans les cieux un témoin certain; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Néanmoins tu l’as rejeté, et l’as dédaigné; tu t’es mis en grande colère contre ton Oint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Tu as rejeté l’alliance faite avec ton serviteur; tu as souillé sa couronne, en la jetant par terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Tu as rompu toutes ses cloisons; tu as mis en ruine ses forteresses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Tous ceux qui passaient par le chemin l’ont pillé; il a été mis en opprobre à ses voisins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Tu as élevé la droite de ses adversaires, tu as réjoui tous ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Tu as aussi émoussé la pointe de son épée, et tu ne l’as point redressé en la bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Tu as fait cesser sa splendeur, et tu as jeté par terre son trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Tu as abrégé les jours de sa jeunesse, et l’as couvert de honte; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Jusques à quand, ô Eternel? te cacheras-tu à jamais? ta fureur s’embrasera-t-elle comme un feu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Souviens-toi de combien petite durée je suis; pourquoi aurais-tu créé en vain tous les fils des hommes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Qui est l’homme qui vivra, et ne verra point la mort, et qui garantira son âme de la main du sépulcre? (Sélah.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Seigneur, où sont tes bontés précédentes lesquelles tu as jurées à David sur ta fidélité?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Seigneur! souviens-toi de l’opprobre de tes serviteurs, et comment je porte dans mon sein l’opprobre qui nous a été fait par tous les grands peuples,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'L’opprobre dont tes ennemis ont diffamé, ô Eternel! dont ils ont diffamé les traces de ton Oint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 53, 'Béni soit à toujours l’Eternel; Amen! Oui, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Requête de Moïse, homme de Dieu. Seigneur! Tu nous as été une retraite d’âge en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Avant que les montagnes fussent nées, et que tu eusses formé la terre, la terre, dis-je, habitable, même de siècle en siècle, tu es le Dieu Fort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Tu réduis l’homme mortel jusques à le menuiser, et tu dis: Fils des hommes, retournez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Car mille ans sont devant tes yeux comme le jour d’hier qui est passé, et comme une veille en la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Tu les emportes comme par une ravine d’eau; ils sont comme un songe au matin; comme une herbe qui se change,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Laquelle fleurit au matin, et reverdit; le soir on la coupe, et elle se fane.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Car nous sommes consumés par ta colère, et nous sommes troublés par ta fureur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Tu as mis devant toi nos iniquités, et devant la clarté de ta face nos fautes cachées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Car tous nos jours s’en vont par ta grande colère, et nous consumons nos années comme une pensée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Les jours de nos années reviennent à soixante et dix ans, et s’il y en a de vigoureux, à quatre-vingts ans; même le plus beau de ces jours n’est que travail et tourment; et il s’en va bientôt, et nous nous envolons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Qui est-ce qui connaît, selon ta crainte, la force de ton indignation et de ta grande colère?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Enseigne-nous à tellement compter nos jours, que nous en puissions avoir un coeur rempli de sagesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Eternel! retourne-toi; jusques à quand? sois apaisé envers tes serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Rassasie-nous chaque matin de ta bonté, afin que nous nous réjouissions, et que nous soyons joyeux tout le long de nos jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Réjouis-nous au prix des jours que tu nous as affligés, et au prix des années auxquelles nous avons senti des maux:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Que ton oeuvre paraisse sur tes serviteurs, et ta gloire sur leurs enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Et que le bon plaisir de l’Eternel notre Dieu, soit sur nous, et dirige l’oeuvre de nos mains; oui dirige l’oeuvre de nos mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Celui qui se tient dans la demeure du Souverain, se loge à l’ombre du Tout-Puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Je dirai à l’Eternel: Tu es ma retraite, et ma forteresse, tu es mon Dieu en qui je m’assure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Certes il te délivrera du filet du chasseur; et de la mortalité malheureuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Il te couvrira de ses plumes, et tu auras retraite sous ses ailes; sa vérité te servira de rondache et de bouclier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Tu n’auras point peur de ce qui épouvante de nuit, ni de la flèche qui vole de jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'Ni de la mortalité qui marche dans les ténèbres; ni de la destruction qui fait le dégât en plein midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Il en tombera mille à ton côté, et dix mille à ta droite; mais la destruction n’approchera point de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Seulement tu contempleras de tes yeux, et tu verras la récompense des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Car tu es ma retraite, ô Eternel! tu as établi le Souverain pour ton domicile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Aucun mal ne te rencontrera, et aucune plaie n’approchera de ta tente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Car il donnera charge de toi à ses Anges, afin qu’ils te gardent en toutes tes voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Ils te porteront dans leurs mains, de peur que ton pied ne heurte contre la pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Tu marcheras sur le lion et sur l’aspic, et tu fouleras le lionceau et le dragon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Puisqu’il m’aime avec affection, dit le Seigneur, je le délivrerai; je le mettrai en une haute retraite, parce qu’il connaît mon Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Il m’invoquera, et je l’exaucerai; je serai avec lui dans la détresse, je l’en retirerai, et le glorifierai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Je le rassasierai de jours, et je lui ferai voir ma délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Psaume de cantique, pour le jour du Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'C’est une belle chose que de célébrer l’Eternel, et de psalmodier à ton Nom, ô Souverain!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'Afin d’annoncer chaque matin ta bonté et ta fidélité toutes les nuits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Sur l’instrument à dix cordes, et sur la musette, et par un Cantique prémédité sur la harpe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Car, ô Eternel! tu m’ as réjoui par tes oeuvres; je me réjouirai des oeuvres de tes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Ô Eternel! que tes oeuvres sont magnifiques! tes pensées sont merveilleusement profondes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'L’homme abruti n’y connaît rien, et le fou n’entend point ceci,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Savoir, que les méchants croissent comme l’herbe, et que tous les ouvriers d’iniquité fleurissent, pour être exterminés éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Mais toi, ô Eternel! tu es haut élevé à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Car voici tes ennemis, ô Eternel! car voici tes ennemis périront, et tous les ouvriers d’iniquité seront dissipés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Mais tu élèveras ma corne comme celle d’une licorne, et mon onction sera d’une huile toute fraîche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Et mon oeil verra en ceux qui m’épient, et mes oreilles entendront touchant les malins, qui s’élèvent contre moi, ce que je désire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Le juste fleurira comme la palme, il croîtra comme le cèdre au Liban.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Etant plantés dans la maison de l’Eternel, ils fleuriront dans les parvis de notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Encore porteront-ils des fruits dans la vieillesse toute blanche; ils seront en bon point, et demeureront verts;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 16, 'Afin d’annoncer que l’Eternel est droit; c’est mon rocher, et il n’y a point d’injustice en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'L’Eternel règne, il est revêtu de magnificence, l’Eternel est revêtu de force, il s’en est ceint; aussi la terre habitable est affermie, tellement qu’elle ne sera point ébranlée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Ton trône a été établi dès lors, tu es de toute éternité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Les fleuves ont élevé, ô Eternel! les fleuves ont augmenté leur bruit, les fleuves ont élevé leurs flots;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'L’Eternel, qui est dans les lieux élevés, est plus puissant que le bruit des grosses eaux, et que les fortes vagues de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Tes témoignages sont fort certains; Eternel! la sainteté a orné ta maison pour une longue durée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Ô Éternel! qui es le Dieu Fort des vengeances, le Dieu Fort des vengeances, fais reluire ta splendeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Toi, Juge de la terre, élève-toi: rends la récompense aux orgueilleux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Jusques à quand les méchants, ô Eternel! jusques à quand les méchants s’égayeront-ils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Jusques à quand tous les ouvriers d’iniquité proféreront-ils et diront-ils des paroles rudes, et se vanteront-ils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Eternel, ils froissent ton peuple, et affligent ton héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Ils tuent la veuve et l’étranger, et ils mettent à mort les orphelins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Et ils ont dit: L’Eternel ne le verra point; le Dieu de Jacob n’en entendra rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Vous les plus abrutis d’entre le peuple, prenez garde à ceci; et vous insensés, quand serez-vous intelligents?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Celui qui a planté l’oreille, n’entendra-t-il point? celui qui a formé l’oeil, ne verra-t-il point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Celui qui châtie les nations, celui qui enseigne la science aux hommes, ne censurera-t-il point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'L’Eternel connaît que les pensées des hommes ne sont que vanité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Ô que bienheureux est l’homme que tu châties, ô Eternel! et que tu instruis par ta Loi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'Afin que lu le mettes à couvert des jours d’adversité, jusqu’à ce que la fosse soit creusée au méchant!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Car l’Eternel ne délaissera point son peuple, et n’abandonnera point son héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'C’est pourquoi le jugement s’unira à la justice, et tous ceux qui sont droits de coeur le suivront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Qui est-ce qui se lèvera pour moi contre les méchants? Qui est-ce qui m’assistera contre les ouvriers d’iniquité?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Si l’Eternel ne m’eût été en secours, mon âme eût été dans peu logée dans le lieu du silence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Si j’ai dit: Mon pied a glissé; ta bonté, ô Eternel! m’a soutenu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Quand j’avais beaucoup de pensées au-dedans de moi, tes consolations ont récréé mon âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Le tribunal des méchants qui machine du mal contre les règles de la justice, sera-t-il joint à toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Ils s’attroupent contre l’âme du juste, et condamnent le sang innocent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Or l’Eternel m’a été pour une haute retraite; et mon Dieu, pour le rocher de mon refuge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Il fera retourner sur eux leur outrage, et, les détruira par leur propre malice. L’Eternel notre Dieu les détruira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Venez, chantons à l’Eternel, jetons des cris de réjouissance au rocher de notre salut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Allons au-devant de lui en lui présentant nos louanges; et jetons devant lui des cris de réjouissance en chantant des Psaumes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Car l’Eternel est un Dieu Fort et grand, et il est un grand Roi par-dessus tous les dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'Les lieux les plus profonds de la terre sont en sa main, et les sommets des montagnes sont à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'C’est à lui qu’appartient la mer, car lui-même l’a faite, et ses mains ont formé le sec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Venez, prosternons-nous, inclinons-nous, et mettons-nous à genoux devant l’Eternel qui nous a faits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Car il est notre Dieu, et nous sommes le peuple de sa pâture, et les brebis de sa conduite. Si vous entendez aujourd’hui sa voix,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'N’endurcissez point votre coeur, comme en Mériba, et comme à la journée de Massa, au désert;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'Là où vos pères m’ont tenté et éprouvé; et aussi ont-ils vu mes oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'J’ai été ennuyé de cette génération durant quarante ans, et j’ai dit: c’est un peuple dont le coeur s’égare; et ils n’ont point connu mes voies;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'C’est pourquoi j’ai juré en ma colère, s’ils entrent dans mon repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Chantez à l’Eternel un nouveau cantique; vous toute la terre chantez à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Chantez à l’Eternel, bénissez son Nom, prêchez de jour en jour sa délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Racontez sa gloire parmi les nations, et ses merveilles parmi tous les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Car l’Eternel est grand, et digne d’être loué; il est redoutable par-dessus tous les dieux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Car tous les dieux des peuples ne sont que des idoles; mais l’Eternel a fait les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'La majesté et la magnificence marchent devant lui; la force et l’excellence sont dans son sanctuaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Familles des peuples rendez à l’Eternel, rendez à l’Eternel la gloire et la force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Rendez à l’Eternel la gloire due à son Nom; apportez l’oblation, et entrez dans ses parvis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Prosternez-vous devant l’Eternel avec une sainte magnificence; vous tous les habitants de la terre tremblez tout étonnés, à cause de la présence de sa face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Dites parmi les nations: l’Eternel règne; même la terre habitable est affermie, et elle ne sera point ébranlée; il jugera les peuples en équité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Que les cieux se réjouissent, et que la terre s’égaye! Que la mer et ce qui est contenu en elle bruie!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Que les champs s’égayent, avec tout ce qui est en eux. Alors tous les arbres de la forêt chanteront de joie,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'Au-devant de l’Eternel, parce qu’il vient, parce qu’il vient pour juger la terre; il jugera en justice le monde habitable, et les peuples selon sa fidélité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'L’Eternel règne, que la terre s’en égaye, et que plusieurs Iles s’en réjouissent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'La nuée et l’obscurité sont autour de lui; la justice et le jugement sont la base de son trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Le feu marche devant lui, et embrase tout autour ses adversaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Ses éclairs éclairent le monde habitable, et la terre le voyant en tremble tout étonnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Les montagnes se fondent comme de la cire, à cause de la présence de l’Eternel, à cause de la présence du Seigneur de toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Les cieux annoncent sa justice, et tous les peuples voient sa gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Que tous ceux qui servent les images, et qui se glorifient aux idoles, soient confus; vous dieux, prosternez-vous tous devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Sion l’a entendu, et s’en est réjouie; et les filles de Juda se sont égayées pour l’amour de tes jugements, ô Eternel!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Car tu es l’Eternel, haut élevé sur toute la terre; tu es fort élevé au-dessus de tous les dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Vous qui aimez l’Eternel, haïssez le mal; car il garde les âmes de ses bien-aimés, et les délivre de la main des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'La lumière est faite pour le juste, et la joie pour ceux qui sont droits de coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Justes, réjouissez-vous en l’Eternel, et célébrez la mémoire de sa sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Psaume. Chantez à l’Eternel un nouveau Cantique; car il a fait des choses merveilleuses; sa droite et le bras de sa Sainteté l’ont délivré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'L’Eternel a fait connaître sa délivrance, il a révélé sa justice devant les yeux des nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Il s’est souvenu de sa gratuité et de sa fidélité envers la maison d’Israël; tous les bouts de la terre ont vu la délivrance de notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Vous tous habitants de la terre, jetez des cris de réjouissance à l’Eternel, faites retentir vos cris, chantez de joie, et psalmodiez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Psalmodiez à l’Eternel avec la harpe, avec la harpe et avec une voix mélodieuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Jetez des cris de réjouissance avec les trompettes et le son du cor devant le Roi, l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Que la mer bruie, avec tout ce qu’elle contient, et que la terre et ceux qui y habitent fassent éclater leurs cris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Que les fleuves frappent des mains, et que les montagnes chantent de joie,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'Au-devant de l’Eternel; car il vient pour juger la terre; il jugera en justice le monde habitable, et les peuples en équité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'L’Eternel règne, que les peuples tremblent; il est assis entre les Chérubins, que la terre soit ébranlée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'L’Eternel est grand en Sion, et il est élevé par-dessus tous les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Ils célébreront ton Nom, grand et terrible; car il est saint;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Et la force du Roi, car il aime la justice; tu as ordonné l’équité, tu as prononcé des jugements justes en Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Exaltez l’Eternel notre Dieu, et prosternez-vous devant son marchepied; il est saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Moïse et Aaron ont été entre ses Sacrificateurs; et Samuel entre ceux qui invoquaient son Nom; ils invoquaient l’Eternel, et il leur répondait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Il parlait à eux de la colonne de nuée; ils ont gardé ses témoignages et l’ordonnance qu’il leur avait donnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Ô Eternel mon Dieu! tu les as exaucés, tu leur as été un Dieu Fort, leur pardonnant, et faisant vengeance de leurs actes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Exaltez l’Eternel notre Dieu, et prosternez-vous en la montagne de sa Sainteté, car l’Eternel, notre Dieu est saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Psaume d’action de grâces. Vous tous habitants de la terre, jetez des cris de réjouissance à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Servez l’Eternel avec allégresse, venez devant lui avec un chant de joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Connaissez que l’Eternel est Dieu. C’est lui qui nous a faits, et ce n’est pas nous qui nous sommes faits; nous sommes son peuple, et le troupeau de sa pâture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Entrez dans ses portes avec des actions de grâces; et dans ses parvis, avec des louanges; célébrez-le, bénissez son Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Car l’Eternel est bon; sa bonté demeure à toujours, et sa fidélité d’âge en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Psaume de David. Je chanterai la miséricorde et la justice; Eternel! je te psalmodierai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Je me rendrai attentif à une conduite pure jusqu’à ce que tu viennes à moi; je marcherai dans l’intégrité de mon coeur, au milieu de ma maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Je ne mettrai point devant mes yeux de chose méchante; j’ai en haine les actions des débauchés; rien ne s’en attachera à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Le coeur mauvais se retirera d’auprès de moi; je n’avouerai point le méchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Je retrancherai celui qui médit en secret de son prochain; je ne pourrai pas souffrir celui qui a les yeux élevés et le coeur enflé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Je prendrai garde aux gens de bien du pays, afin qu’ils demeurent avec moi; celui qui marche dans la voie entière, me servira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Celui qui usera de tromperie ne demeurera point dans ma maison; celui qui profère mensonge, ne sera point affermi devant mes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Je retrancherai chaque matin tous les méchants du pays, afin d’exterminer de la Cité de l’Eternel tous les ouvriers d’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Prière de l’affligé étant dans l’angoisse, et répandant sa plainte devant l’Eternel. 2.Eternel! écoute ma prière, et que mon cri vienne jusqu’à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Ne cache point ta face arrière de moi; au jour que je suis en détresse, prête l’oreille à ma requête; au jour que je t’invoque, hâte-toi, réponds-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Car mes jours se sont évanouis comme la fumée, et mes os sont desséchés comme un foyer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Mon coeur a été frappé, et est devenu sec comme l’herbe, parce que j’ai oublié de manger mon pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Mes os sont attachés à ma chair, à cause de la voix de mon gémissement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Je suis devenu semblable au cormoran du désert; et je suis comme la chouette des lieux sauvages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Je veille, et je suis semblable au passereau, qui est seul sur le toit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Mes ennemis me disent tous les jours des outrages, et ceux qui sont furieux contre moi, jurent contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Parce que j’ai mangé la cendre comme le pain, et que j’ai mêlé ma boisson de pleurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'A cause de ta colère et de ton indignation: parce qu’après m’avoir élevé bien haut, tu m’as jeté par terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Mes jours sont comme l’ombre qui décline, et je deviens sec comme l’herbe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Mais toi, ô Eternel! tu demeures éternellement, et ta mémoire est d’âge en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Tu te lèveras, et tu auras compassion de Sion; car il est temps d’en avoir pitié, parce que le temps assigné est échu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Car tes serviteurs sont affectionnés à ses pierres, et ont pitié de sa poudre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Alors les nations redouteront le Nom de l’Eternel, et tous les Rois de la terre, ta gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Quand l’Eternel aura édifié Sion; quand il aura été vu en sa gloire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Quand il aura eu égard à la prière du désolé, et qu’il n’aura point méprisé leur supplication.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Cela sera enregistré pour la génération à venir, le peuple qui sera créé louera l’Eternel,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'De ce qu’il aura jeté la vue du haut lieu de sa sainteté, et que l’Eternel aura regardé des cieux en la terre,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Pour entendre le gémissement des prisonniers, et pour délier ceux qui étaient dévoués à la mort;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'Afin qu’on annonce le Nom de l’Eternel dans Sion, et sa louange dans Jérusalem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'Quand les peuples se seront joints ensemble et les Royaumes aussi, pour servir l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Il a abattu ma force en chemin, il a abrégé mes jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'J’ai dit: mon Dieu, ne m’enlève point au milieu de mes jours! Tes ans durent d’âge en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Tu as jadis fondé la terre, et les cieux sont l’ouvrage de tes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Ils périront, mais tu seras permanent, et eux tous s’envieilliront comme un vêtement; tu les changeras comme un habit, et ils seront changés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Mais toi, tu es toujours le même; et tes ans ne seront jamais achevés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Les enfants de tes serviteurs habiteront près de toi, et leur race sera établie devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 29, '');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Psaume de David. Mon âme, bénis l’Eternel, et que tout ce qui est au-dedans de moi bénisse le Nom de sa Sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Mon âme, bénis l’Eternel, et n’oublie pas un de ses bienfaits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'C’est lui qui te pardonne toutes tes iniquités, qui guérit toutes tes infirmités;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'Qui garantit ta vie de la fosse, qui te couronne de gratuité et de compassions;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'Qui rassasie ta bouche de biens; ta jeunesse est renouvelée comme celle de l’aigle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'L’Eternel fait justice et droit à tous ceux à qui l’on fait tort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Il a fait connaître ses voies à Moïse, et ses exploits aux enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'L’Eternel est pitoyable, miséricordieux, tardif à colère, et abondant en grâce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Il ne dispute point éternellement, et il ne garde point à toujours sa colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Il ne nous a point fait selon nos péchés, et ne nous a point rendu selon nos iniquités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Car autant que les cieux sont élevés par-dessus la terre, autant sa gratuité est grande sur ceux qui le craignent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Il a éloigné de nous nos forfaits, autant que l’Orient est éloigné de l’Occident.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'De telle compassion qu’un père est ému envers ses enfants, de telle compassion l’Eternel est ému envers ceux qui le craignent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Car il sait bien de quoi nous sommes faits, se souvenant que nous ne sommes que poudre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Les jours de l’homme mortel sont comme le foin, il fleurit comme la fleur d’un champ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Car le vent étant passé par-dessus, elle n’est plus, et son lieu ne la reconnaît plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Mais la miséricorde de l’Eternel est de tout temps, et elle sera à toujours en faveur de ceux qui le craignent; et sa justice en faveur des enfants de leurs enfants;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'Pour ceux qui gardent son alliance, et qui se souviennent de ses commandements pour les faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'L’Eternel a établi son Trône dans les cieux, et son règne a domination sur tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Bénissez l’Eternel, vous ses Anges puissants en vertu, qui faites son commandement, en obéissant à la voix de sa parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Bénissez l’Eternel, vous toutes ses armées, qui êtes ses Ministres faisant son bon plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Bénissez l’Eternel, vous toutes ses oeuvres, par tous les lieux de sa domination. Mon âme, bénis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Mon âme, bénis l’Eternel. Ô Eternel mon Dieu, tu es merveilleusement grand, tu es revêtu de majesté et de magnificence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Il s’enveloppe de lumière comme d’un vêtement, il étend les cieux comme un voile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Il planchéie ses hautes chambres entre les eaux; il fait des grosses nuées son chariot, il se promène sur les ailes du vent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Il fait des vents ses Anges, et du feu brûlant ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Il a fondé la terre sur ses bases, tellement qu’elle ne sera point ébranlée à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Tu l’avais couverte de l’abîme comme d’un vêtement, les eaux se tenaient sur les montagnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Elles s’enfuirent à ta menace, et se mirent promptement en fuite au son de ton tonnerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Les montagnes s’élevèrent, et les vallées s’abaissèrent, au même lieu que tu leur avais établi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Tu leur as mis une borne qu’elles ne passeront point, elles ne retourneront plus à couvrir la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'C’est lui qui conduit les fontaines par les vallées, tellement qu’elles se promènent entre les monts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Elles abreuvent toutes les bêtes des champs, les ânes sauvages en étanchent leur soif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Les oiseaux des cieux se tiennent auprès d’elles, et font résonner leur voix d’entre la ramée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Il abreuve les montagnes de ses chambres hautes; et la terre est rassasiée du fruit de tes oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Il fait germer le foin pour le bétail, et l’herbe pour le service de l’homme, faisant sortir le pain de la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'Et le vin qui réjouit le coeur de l’homme, qui fait reluire son visage avec l’huile, et qui soutient le coeur de l’homme avec le pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Les hauts arbres en sont rassasiés, et les cèdres du Liban, qu’il a plantés,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Afin que les oiseaux y fassent leurs nids. Quant à la cigogne, les sapins sont sa demeure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Les hautes montagnes sont pour les chamois et les rochers sont la retraite des lapins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Il a fait la lune pour les saisons, et le soleil connaît son coucher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Tu amènes les ténèbres, et la nuit vient, durant laquelle toutes les bêtes de la forêt trottent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Les lionceaux rugissent après la proie, et pour demander au Dieu Fort leur pâture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Le soleil se lève-t-il? ils se retirent et demeurent gisants en leurs tanières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Alors l’homme sort à son ouvrage et à son travail, jusqu’au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Ô Eternel, que tes oeuvres sont en grand nombre! tu les as toutes faites avec sagesse; la terre est pleine de tes richesses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Cette mer grande et spacieuse, où il y a sans nombre des animaux se mouvant, des petites bêtes avec des grandes!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Là se promènent les navires, et ce Léviathan que tu as formé pour s’y ébattre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Elles s’attendent toutes à toi, afin que tu leur donnes la pâture en leur temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Quand tu la leur donnes, elles la recueillent, et quand tu ouvres ta main, elles sont rassasiées de biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Caches-tu ta face? elles sont troublées; retires-tu leur souffle, elles défaillent, et retournent en leur poudre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Mais si tu renvoies ton Esprit, elles sont créées, et tu renouvelles la face de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Que la gloire de l’Eternel soit à toujours, que l’Eternel se réjouisse en ses oeuvres!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Il jette sa vue sur la terre, et elle en tremble; il touche les montagnes, et elles en fument.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Je chanterai à l’Eternel durant ma vie; je psalmodierai à mon Dieu pendant que j’existerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Ma méditation lui sera agréable; et je me réjouirai en l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Que les pécheurs soient consumés de dessus la terre, et qu’il n’y ait plus de méchants! Mon âme, bénis l’Eternel; louez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Célébrez l’Eternel, invoquez son Nom, faites connaître parmi les peuples ses exploits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Chantez-lui, psalmodiez-lui, parlez de toutes ses merveilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Glorifiez-vous du Nom de sa sainteté, et que le coeur de ceux qui cherchent l’Eternel se réjouisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Recherchez l’Eternel, et sa force; cherchez continuellement sa face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Souvenez-vous de ses merveilles qu’il a faites, de ses miracles, et des jugements de sa bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'La postérité d’Abraham sont ses serviteurs; les enfants de Jacob sont ses élus;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Il est l’Eternel notre Dieu; ses jugements sont sur toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Il s’est souvenu à toujours de son alliance, de la parole qu’il a commandée en mille générations;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'Du traité qu’il a fait avec Abraham, et du serment qu’il a fait à Isaac,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'Lequel il a ratifié pour être une ordonnance à Jacob, et à Israël pour être une alliance éternelle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'En disant: je te donnerai le pays de Canaan, pour le lot de ton héritage;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Encore qu’ils fussent un petit nombre de gens, et qu’ils y séjournassent peu de temps comme étrangers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Car ils allaient de nation en nation, et d’un Royaume vers un autre peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Il ne souffrit pas qu’aucun les opprimât: et il a même châtié des Rois pour l’amour d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'Disant: Ne touchez point à mes Oints, et ne faites point de mal à mes Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Il appela aussi la famine sur la terre, et rompit tout le bâton du pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Il envoya un personnage devant eux; Joseph fut vendu pour esclave.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'On lui enserra les pieds en des ceps, sa personne fut mise aux fers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'Jusqu’au temps que sa parole fût venue, et que la parole de l’Eternel l’eût éprouvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Le Roi envoya, et on le relâcha; le dominateur des peuples envoya, et on le délia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Il l’établit pour maître sur sa maison, et pour dominateur sur tout son domaine;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'Pour soumettre les principaux à ses désirs, et pour instruire ses Anciens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Puis Israël entra en Egypte, et Jacob séjourna au pays de Cam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Et l’ Eternel fit extrêmement multiplier son peuple, et le rendit plus puissant que ceux qui l’opprimaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Il changea leur coeur, de sorte qu’ils eurent son peuple en haine, jusques à conspirer contre ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Il envoya Moïse son serviteur, et Aaron, qu’il avait élu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Lesquels accomplirent sur eux les prodiges, et les miracles qu’ils avaient eu charge de faire dans le pays de Cam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Il envoya les ténèbres, et fit obscurcir l’air; et ils ne furent point rebelles à ses ordres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Il convertit leurs eaux en sang, et fit mourir leurs poissons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Leur terre produisit en abondance des grenouilles, jusqu’au dedans des cabinets de leurs Rois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Il parla, et une mêlée de bêtes vint, et des poux sur tout leur pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Il fit que leurs pluies furent de la grêle, et qu’il y eut sur leur terre un feu flamboyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Il frappa leurs vignes, et leurs figuiers, et il brisa les arbres de leur pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Il commanda, et les sauterelles vinrent, et des hurebecs sans nombre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'Qui broutèrent toute l’herbe en leur pays, et qui dévorèrent le fruit de leur terroir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Et il frappa tout premier-né dans leur pays, qui étaient les prémices de toute leur vigueur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Puis il les tira dehors avec de l’or et de l’argent, et il n’y eut aucun qui chancelât parmi ses Tribus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'L’Egypte se réjouit à leur départ; car la peur qu’ils avaient d’eux, les avait saisis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Il étendit la nuée pour couverture, et le feu pour éclairer la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Le peuple demanda, et il fit venir des cailles, et il les rassasia du pain des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Il ouvrit le rocher, et les eaux en coulèrent; et coururent par les lieux secs, comme une rivière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Car il se souvint de la parole de sa sainteté, laquelle il avait donnée à Abraham son serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Et il tira dehors son peuple avec allégresse, et ses élus avec chant de joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'Il leur donna les pays des nations, et ils possédèrent le fruit du travail des peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'Afin qu’ils gardassent ses statuts, et qu’ils observassent ses lois. Louez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Louez l’Eternel. Célébrez l’Eternel; car il est bon, parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Qui pourrait réciter les exploits de l’Eternel? Qui pourrait faire retentir toute sa louange?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Ô que bienheureux sont ceux qui observent la justice, et qui font en tout temps ce qui est juste!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Eternel, souviens-toi de moi selon la bienveillance que tu portes à ton peuple, et aie soin de moi selon ta délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Afin que je voie le bien de tes élus, que je me réjouisse dans la joie de ta nation, et que je me glorifie avec ton héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Nous avons péché avec nos pères, nous avons agi iniquement, nous avons mal fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Nos pères n’ont point été attentifs à tes merveilles en Egypte; ils ne se sont point souvenus de la multitude de tes faveurs; mais ils ont été rebelles auprès de la mer, vers la mer Rouge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Toutefois il les délivra pour l’amour de son Nom, afin de donner à connaître sa puissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Car il tança la mer Rouge, et elle se sécha, et il les conduisit par les gouffres comme par le désert;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Et les délivra de la main de ceux qui les haïssaient, et les garantit de la main de l’ennemi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Et les eaux couvrirent leurs oppresseurs, il n’en resta pas un seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Alors ils crurent à ses paroles, et ils chantèrent sa louange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Mais ils mirent incontinent en oubli ses oeuvres, et ne s’attendirent point à son conseil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Mais ils furent épris de convoitise au désert, et ils tentèrent le Dieu Fort au lieu inhabitable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Alors il leur donna ce qu’ils avaient demandé, toutefois il leur envoya une phtisie en leur corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Ils portèrent envie à Moïse dans le camp, et à Aaron le saint de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'La terre s’ouvrit, et engloutit Dathan, et couvrit la bande d’Abiram.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'Aussi le feu s’alluma en leur assemblée, et la flamme brûla les méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Ils firent un veau en Horeb, et se prosternèrent devant l’image de fonte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'Ils changèrent leur gloire en la figure d’un boeuf qui mange l’herbe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Ils oublièrent le Dieu Fort, leur Libérateur, qui avait fait de grandes choses en Egypte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Des choses merveilleuses au pays de Cam, et des choses terribles sur la mer Rouge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'C’est pourquoi il dit qu’il les détruirait; mais Moïse son élu se tint à la brèche devant lui, pour détourner sa fureur, afin qu’il ne les défît point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Ils méprisèrent le pays désirable, et ne crurent point à sa parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'Et ils se mutinèrent dans leurs tentes, et n’obéirent point à la voix de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'C’est pourquoi il leur jura la main levée, qu’il les renverserait dans le désert,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'Et qu’il accablerait leur postérité parmi les nations, et qu’il les disperserait par les pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Ils se joignirent aux adorateurs de Bahal-Péhor, et mangèrent des sacrifices des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'Et ils dépitèrent Dieu par les choses à quoi ils s’adonnèrent, tellement qu’une plaie fit brèche sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Mais Phinées se présenta, et fit justice; et la plaie fut arrêtée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Et cela lui a été alloué pour justice dans tous les âges à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Ils excitèrent aussi sa colère près des eaux de Mériba, et il en avint du mal à Moïse à cause d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Car ils chagrinèrent son esprit, et il parla légèrement de ses lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Ils n’ont point détruit les peuples que l’Eternel leur avait dit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'Mais ils se sont mêlés parmi ces nations, et ils ont appris leurs manières de faire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'Et ont servi à leurs faux dieux, lesquels leur ont été en pièges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Car ils ont sacrifié leurs fils et leurs filles aux démons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'Et ils ont répandu le sang innocent, le sang de leurs fils et de leurs filles, lesquels ils ont sacrifiés aux faux dieux de Canaan; et le pays a été souillé de sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Et ils ont été souillés par leurs oeuvres, et ont paillardé par les choses à quoi ils se sont adonnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'C’est pourquoi la colère de l’Eternel s’est embrasée contre son peuple, et il a eu en abomination son héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'Et il les a livrés entre les mains des nations, et ceux qui les haïssaient, ont dominé sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Et leurs ennemis les ont opprimés, et ils ont été humiliés sous leur main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Il les a souvent délivrés, mais ils l’ont irrité par leur conseil, et ils ont été mis en langueur par leur iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Toutefois il les a regardés dans leur détresse, quand il entendait leur clameur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Et il s’est souvenu en leur faveur de son alliance, et s’est repenti selon la grandeur de ses compassions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Et il a fait que ceux qui les avaient emmenés captifs, ont eu pitié d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Eternel notre Dieu, délivre-nous et nous recueille d’entre les nations, afin que nous célébrions le Nom de ta sainteté, et que nous nous glorifiions en ta louange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Béni soit l’Eternel, le Dieu d’Israël, depuis un siècle jusqu’à l’autre siècle! et que tout le peuple dise, Amen! Louez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Célébrez l’Eternel, car il est bon, parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Que ceux-là le disent, qui sont les rachetés de l’Eternel, lesquels il a rachetés de la main de l’oppresseur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'Et ceux aussi qu’il a ramassés des pays d’Orient et d’Occident, d’Aquilon et de Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Ils étaient errants par le désert, en un chemin solitaire, et ils ne trouvaient aucune ville habitée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Ils étaient affamés et altérés, l’âme leur défaillait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Alors ils ont crié vers l’Eternel dans leur détresse; il les a délivrés de leurs angoisses,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'Et les a conduits au droit chemin pour aller en une ville habitée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Qu’ils célèbrent envers l’Eternel sa gratuité, et ses merveilles envers les fils des hommes:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Parce qu’il a désaltéré l’âme altérée, et rassasié de ses biens l’âme affamée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Ceux qui demeurent dans les ténèbres, et dans l’ombre de la mort, garrottés d’affliction et de fer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Parce qu’ils ont été rebelles aux paroles du Dieu Fort, et qu’ils ont rejeté par mépris le conseil du Souverain;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Et il a humilié leur coeur par le travail, et ils ont été abattus, sans qu’il y eût personne qui les aidât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Alors ils ont crié vers l’Eternel en leur détresse, et il les a délivrés de leurs angoisses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Il les a tirés hors des ténèbres, et de l’ombre de la mort, et il a rompu leurs liens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Qu’ils célèbrent envers l’Eternel sa gratuité, et ses merveilles envers les fils des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Parce qu’il a brisé les portes d’airain, et cassé les barreaux de fer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Les fols qui sont affligés à cause de leur transgression, et à cause de leurs iniquités;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Leur âme a en horreur toute viande, et ils touchent aux portes de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Alors ils ont crié vers l’Eternel dans leur détresse, et il les a délivrés de leurs angoisses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Il envoie sa parole, et les guérit, et il les délivre de leurs tombeaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Qu’ils célèbrent envers l’Eternel sa gratuité, et ses merveilles envers les fils des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'Et qu’ils sacrifient des sacrifices d’actions de grâces, et qu’ils racontent ses oeuvres en chantant de joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Ceux qui descendent sur la mer dans des navires, faisant commerce parmi les grandes eaux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'Qui voient les oeuvres de l’Eternel, et ses merveilles dans les lieux profonds,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, '(Car il commande, et fait comparaître le vent de tempête, qui élève les vagues de la mer.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Ils montent aux cieux, ils descendent aux abîmes; leur âme se fond d’angoisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Ils branlent, et chancellent comme un homme ivre, et toute leur sagesse leur manque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Alors ils crient vers l’Eternel dans leur détresse, et il les tire hors de leurs angoisses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Il arrête la tourmente, la changeant en calme, et les ondes sont calmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Puis ils se réjouissent de ce qu’elles sont apaisées, et il les conduit au port qu’ils désiraient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Qu’ils célèbrent envers l’Eternel sa gratuité, et ses merveilles envers les fils des hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Et qu’ils l’exaltent dans la congrégation du peuple, et le louent dans l’assemblée des Anciens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Il réduit les fleuves en désert, et les sources d’eaux en sécheresse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'Et la terre fertile en terre salée, à cause de la malice de ceux qui y habitent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Il réduit le désert en des étangs d’eaux, et la terre sèche en des sources d’eaux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'Et il y fait habiter ceux qui étaient affamés, tellement qu’ils y bâtissent des villes habitables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Et sèment les champs, et plantent des vignes qui rendent du fruit tous les ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Il les bénit, et ils sont fort multipliés, et il ne laisse point diminuer leur bétail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Puis ils se diminuent, et sont humiliés par l’oppression, le mal, et l’ennui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Il répand le mépris sur les principaux, et les fait errer par des lieux hideux, où il n’y a point de chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Mais il tire le pauvre hors de l’affliction, et donne les familles comme par troupeaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Les hommes droits voient cela, et s’en réjouissent; mais toute iniquité a la bouche fermée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Quiconque est sage, prendra garde à ces choses, afin qu’on considère les bontés de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Cantique de Psaume de David. Mon coeur est disposé, ô Dieu! ma gloire l’est aussi, je chanterai et je psalmodierai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Réveille-toi, ma musette et ma harpe, je me réveillerai à l’aube du jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Eternel, je te célébrerai parmi les peuples, et je te psalmodierai parmi les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Car ta bonté est grande par-dessus les cieux, et ta vérité atteint jusqu’aux nues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Ô Dieu! élève-toi sur les cieux, et que ta gloire soit sur toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Afin que ceux que tu aimes soient délivrés; sauve-moi par ta droite, et exauce-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Dieu a parlé en son Sanctuaire; je me réjouirai; je partagerai Sichem, et mesurerai la vallée de Succoth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Galaad sera à moi, Manassé sera à moi, et Ephraïm sera ma principale force, Juda mon Législateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Moab sera le bassin où je me laverai, je jetterai mon soulier sur Edom, je triompherai de la Palestine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Qui sera-ce qui me conduira en la ville munie? qui sera-ce qui me conduira jusques en Edom?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Ne sera-ce pas toi, ô Dieu! qui nous avais rejetés, et qui ne sortais plus, ô Dieu! avec nos armées?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Donne-nous secours pour sortir de la détresse; car la délivrance qu’on attend de l’homme est vaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Nous ferons des actions de valeur en Dieu, et il foulera nos ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 14, '');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Psaume de David, donné au maître chantre. Ô Dieu de ma louange, ne te tais point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Car la bouche du méchant, et la bouche remplie de fraudes se sont ouvertes contre moi, et m’ont parlé, en usant d’une langue trompeuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Et des paroles pleines de haine m’ont environné, et ils me font la guerre sans cause.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Au lieu que je les aimais, ils ont été mes ennemis; mais moi, je n’ai fait que prier en leur faveur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Et ils m’ont rendu le mal pour le bien, et la haine pour l’amour que je leur portais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Etablis le méchant sur lui, et fais que l’adversaire se tienne à sa droite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Quand il sera jugé, fais qu’il soit déclaré méchant, et que sa prière soit regardée comme un crime.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Que sa vie soit courte, et qu’un autre prenne sa charge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Que ses enfants soient orphelins, et sa femme veuve;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Et que ses enfants soient entièrement vagabonds, et qu’ils mendient et quêtent en sortant de leurs maisons détruites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Que le créancier usant d’exaction attrape tout ce qui est à lui, et que les étrangers butinent tout son travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Qu’il n’y ait personne qui étende sa compassion sur lui, et qu’il n’y ait personne qui ait pitié de ses orphelins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Que sa postérité soit exposée à être retranchée; que leur nom soit effacé dans la race qui le suivra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Que l’iniquité de ses pères revienne en mémoire à l’Eternel, et que le péché de sa mère ne soit point effacé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Qu’ils soient continuellement devant l’Eternel; et qu’il retranche leur mémoire de la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Parce qu’il ne s’est point souvenu d’user de miséricorde, mais il a persécuté l’homme affligé et misérable, dont le coeur est brisé, et cela pour le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Puisqu’il a aimé la malédiction, que la malédiction tombe sur lui; et parce qu’il n’a point pris plaisir à la bénédiction, que la bénédiction aussi s’éloigne de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Et qu’il soit revêtu de malédiction comme de sa robe, et qu’elle entre dans son corps comme de l’eau, et dans ses os comme de l’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Qu’elle lui soit comme un vêtement dont il se couvre, et comme une ceinture, dont il se ceigne continuellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Telle soit de part l’Eternel la récompense de mes adversaires, et de ceux qui parlent mal de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Mais toi, Eternel Seigneur, agis avec moi pour l’amour de ton Nom; et parce que ta miséricorde est tendre, délivre-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Car je suis affligé et misérable, et mon coeur est blessé au- dedans de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Je m’en vais comme l’ombre quand elle décline, et je suis chassé comme une sauterelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Mes genoux sont affaiblis par le jeûne, et ma chair s’est amaigrie, au lieu qu’elle était en bon point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Encore leur suis-je en opprobre; quand ils me voient ils branlent la tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Eternel mon Dieu! aide-moi, et délivre-moi selon ta miséricorde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Afin qu’on connaisse que c’est ici ta main, et que toi, ô Eternel! tu as fait ceci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Ils maudiront, mais tu béniras; ils s’élèveront, mais ils seront confus, et ton serviteur se réjouira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Que mes adversaires soient revêtus de confusion, et couverts de leur honte comme d’un manteau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Je célébrerai hautement de ma bouche l’Eternel, et je le louerai au milieu de plusieurs nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'De ce qu’il se tient à la droite du misérable, pour le délivrer de ceux qui condamnent son âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Psaume de David. L’Eternel a dit à mon Seigneur: assieds-toi à ma droite, jusqu’à ce que j’aie mis tes ennemis pour le marchepied de tes pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'L’Eternel transmettra de Sion le sceptre de ta force, en disant: Domine au milieu de tes ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Ton peuple sera un peuple plein de franche volonté au jour que tu assembleras ton armée en sainte pompe; la rosée de ta jeunesse te sera produite du sein de l’aube du jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'L’Eternel l’a juré, et il ne s’en repentira point, que tu es Sacrificateur éternellement, à la façon de Melchisédec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Le Seigneur est à ta droite, il froissera les Rois au jour de sa colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Il exercera jugement sur les nations, il remplira tout de corps morts; il froissera le Chef qui domine sur un grand pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Il boira du torrent par le chemin, c’est pourquoi il lèvera haut la tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Louez l’Eternel. Aleph Je célébrerai l’Eternel de tout mon coeur, Beth. dans la compagnie des hommes droits, et dans l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Les oeuvres de l’Eternel sont grandes, Daleth. Elles sont recherchées de tous ceux qui y prennent plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Son oeuvre n’est que majesté et magnificence, Vau. et sa justice demeure à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Il a rendu ses merveilles mémorables. Heth. L’Eternel est miséricordieux et pitoyable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Il a donné à vivre à ceux qui le craignent; Jod. il s’est souvenu à toujours de son alliance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Il a manifesté à son peuple la force de ses oeuvres, Lamed. en leur donnant l’héritage des nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Les oeuvres de ses mains ne sont que vérité et équité; Nun. tous ses commandements sont véritables;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Appuyés à perpétuité et à toujours, Hajin. étant faits avec fidélité et droiture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Il a envoyé la rédemption à son peuple; Tsade. il lui a donné une alliance éternelle; Koph. son nom est saint et terrible.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Ce qu’il y a de capital dans la sagesse c’est la crainte de l’Eternel: Scin. tous ceux qui s’adonnent à faire ce qu’elle prescrit sont bien sages; Thau. sa louange demeure à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Louez l’Eternel. Aleph. Bienheureux est l’homme qui craint l’Eternel, Beth. et qui prend un singulier plaisir en ses commandements!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Sa postérité sera puissante en la terre, Daleth. la génération des hommes droits sera bénie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Il y aura des biens et des richesses en sa maison; Vau. et sa justice demeure à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'La lumière s’est levée dans les ténèbres à ceux qui sont justes; Heth. il est pitoyable, miséricordieux et charitable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'L’homme de bien fait des aumônes, et prête; Jod. Il dispense ses affaires avec droiture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Même il ne sera jamais ébranlé. Lamed. Le juste sera en mémoire perpétuelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Il n’aura peur d’aucun mauvais rapport; Nun. Son coeur est ferme s’assurant en l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Son coeur est bien appuyé, il ne craindra point, Hajin. jusqu’à ce qu’il ait vu en ses adversaires ce qu’il désire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Il a répandu, il a donné aux pauvres; Tsade. sa justice demeure à perpétuité; Koph. sa corne sera élevée en gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Le méchant le verra, et en aura du dépit. Sein. Il grincera les dents, et se fondra; Thau. le désir des méchants périra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Louez l’Eternel. Louez, vous serviteurs de l’Eternel, louez le Nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Le Nom de l’Eternel soit béni dès maintenant et à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Le Nom de l’Eternel est digne de louange depuis le soleil levant jusqu’au soleil couchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'L’Eternel est élevé par-dessus toutes les nations, sa gloire est par-dessus les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Qui est semblable à l’Eternel notre Dieu, lequel habite aux lieux très-hauts?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'Lequel s’abaisse pour regarder aux cieux, et en la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Lequel relève l’affligé de la poudre, et retire le pauvre de dessus le fumier,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'Pour le faire asseoir avec les principaux, avec les principaux, dis-je, de son peuple;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Lequel donne une famille à la femme qui était stérile, la rendant mère d’enfants, et joyeuse. Louez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Quand Israël sortit d’Egypte, et la maison de Jacob d’avec le peuple barbare,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Juda devint une chose sacrée à Dieu, et Israël son empire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'La mer le vit, et s’enfuit, le Jourdain s’en retourna en arrière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Les montagnes sautèrent comme des moutons, et les coteaux comme des agneaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Ô mer! qu’avais-tu pour t’enfuir? et toi Jourdain, pour retourner en arrière?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Et vous montagnes, que vous ayez sauté comme des moutons; et vous coteaux, comme des agneaux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Ô terre! tremble pour la présence du Seigneur, pour la présence du Dieu de Jacob;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Qui a changé le rocher en un étang d’eaux, et la pierre très dure en une source d’eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Non point à nous, ô Eternel! non point à nous, mais à ton Nom donne gloire pour l’amour de ta miséricorde, pour l’amour de ta vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Pourquoi diraient les nations: où est maintenant leur Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Certes notre Dieu est aux cieux; il fait tout ce qu’il lui plaît.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Leurs dieux sont des dieux d’or et d’argent, un ouvrage des mains d’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Ils ont une bouche, et ne parlent point; ils ont des yeux, et ne voient point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Ils ont des oreilles, et n’entendent point; ils ont un nez, et ils n’ en flairent point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Des mains, et ils n’ en touchent point; des pieds, et ils n’en marchent point; et ils ne rendent aucun son de leur gosier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Que ceux qui les font, et tous ceux qui s’y confient, leur soient faits semblables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Israël confie-toi en l’Eternel; il est le secours et le bouclier de ceux qui se confient en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Maison d’Aaron, confiez-vous en l’Eternel; il est leur aide et leur bouclier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Vous qui craignez l’Eternel, confiez-vous en l’Eternel; il est leur aide et leur bouclier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'L’Eternel s’est souvenu de nous, il bénira, il bénira la maison d’Israël, il bénira la maison d’Aaron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Il bénira ceux qui craignent l’Eternel, tant les petits que les grands.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'L’Eternel ajoutera bénédiction sur vous, sur vous et sur vos enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Vous êtes bénis de l’Eternel, qui a fait les cieux et la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Quant aux Cieux, les Cieux sont à l’Eternel; mais il a donné la terre aux enfants des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Les morts, et tous ceux qui descendent où l’on ne dit plus mot, ne loueront point l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Mais nous, nous bénirons l’Eternel dès maintenant, et à toujours. Louez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'J’aime l’Eternel, car il a exaucé ma voix, et mes supplications.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Car il a incliné son oreille vers moi, c’est pourquoi je l’invoquerai durant mes jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Les cordeaux de la mort m’avaient environné, et les détresses du sépulcre m’avaient rencontré; j’avais rencontré la détresse et l’ennui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Mais j’invoquai le Nom de l’Eternel, en disant: je te prie, ô Eternel! délivre mon âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'L’Eternel est pitoyable et juste, et notre Dieu fait miséricorde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'L’Eternel garde les simples; j’étais devenu misérable, et il m’a sauvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Mon âme, retourne en ton repos; car l’Eternel t’a fait du bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Parce que tu as mis à couvert mon âme de la mort, mes yeux de pleurs, et mes pieds de chute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Je marcherai en la présence de l’Eternel dans la terre des vivants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'J’ai cru, c’est pourquoi j’ai parlé; j’ai été fort affligé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Je disais en ma précipitation: tout homme est menteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Que rendrai-je à l’Eternel? tous ses bienfaits sont sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Je prendrai la coupe des délivrances, et j’invoquerai le Nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Je rendrai maintenant mes voeux à l’Eternel, devant tout son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Toute sorte de mort des bien-aimés de l’Eternel est précieuse devant ses yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Ouï, ô Eternel! car je suis ton serviteur, je suis ton serviteur, fils de ta servante, tu as délié mes liens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Je te sacrifierai des sacrifices d’actions de grâces, et j’invoquerai le Nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Je rendrai maintenant mes voeux à l’Eternel, devant tout son peuple;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'Dans les parvis de la maison de l’Eternel, au milieu de toi, Jérusalem. Louez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Toutes nations, louez l’Eternel; tous peuples, célébrez-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Car sa miséricorde est grande envers nous, et la vérité de l’Eternel demeure à toujours. Louez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Célébrez l’Eternel, car il est bon; parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Qu’Israël dise maintenant, que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Que la maison d’Aaron dise maintenant, que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Que ceux qui craignent l’Eternel disent maintenant, que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Me trouvant dans la détresse, j’ai invoqué l’Eternel, et l’Eternel m’a répondu, et m’a mis au large.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'L’Eternel est pour moi, je ne craindrai point. Que me ferait l’homme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'L’Eternel est pour moi entre ceux qui m’aident; c’est pourquoi je verrai en ceux qui me haïssent ce que je désire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Mieux vaut se confier en l’Eternel, que de se confier en l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Mieux vaut se confier en l’Eternel, que de se reposer sur les principaux d’entre les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Ils m’avaient environné; mais au Nom de l’Eternel je les mettrai en pièces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Ils m’avaient environné, ils m’avaient, dis-je, environné; mais au Nom de l’Eternel je les ai mis en pièces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Ils m’avaient environné comme des abeilles; ils ont été éteints comme un feu d’épines, car au Nom de l’Eternel je les ai mis en pièces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Tu m’avais rudement poussé, pour me faire tomber, mais l’Eternel m’a été en aide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'L’Eternel est ma force, et le sujet de mon Cantique, et il a été mon libérateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Une voix de chant de triomphe et de délivrance retentit dans les tabernacles des justes; la droite de l’Eternel, s’écrient ils, fait vertu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'La droite de l’Eternel est haut élevée, la droite de l’Eternel fait vertu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Je ne mourrai point, mais je vivrai, et je raconterai les faits de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'L’Eternel m’a châtié sévèrement, mais il ne m’a point livré à la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Ouvrez-moi les portes de justice; j’y entrerai, et je célébrerai l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'C’est ici la porte de l’Eternel; les justes y entreront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Je te célébrerai de ce que tu m’as exaucé et de ce que tu as été mon libérateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'La Pierre que les Architectes avaient rejetée, est devenue le principal du coin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Ceci a été fait par l’Eternel, et a été une chose merveilleuse devant nos yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'C’est ici la journée que l’Eternel a faite; égayons-nous? et nous réjouissons en elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Eternel, je te prie, délivre maintenant. Eternel, je te prie, donne maintenant prospérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Béni soit celui qui vient au Nom de l’Eternel; nous vous bénissons de la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'L’Eternel est le Dieu Fort, et il nous a éclairés. Liez avec des cordes la bête du sacrifice, et amenez-la, jusqu’aux cornes de l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Tu es mon Dieu Fort, c’est pourquoi je te célébrerai. Tu es mon Dieu, je t’exalterai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Célébrez l’Eternel; car il est bon, parce que sa miséricorde demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'ALEPH. Bienheureux sont ceux qui sont intègres en leur voie, qui marchent en la Loi de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Bienheureux sont ceux qui gardent ses témoignages, et qui le cherchent de tout leur coeur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Qui aussi ne font point d’iniquité, et qui marchent dans ses voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Tu as donné tes commandements afin qu’on les garde soigneusement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Qu’il te plaise, ô Dieu! que mes voies soient bien dressées, pour garder tes statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Et je ne rougirai point de honte, quand je regarderai à tous tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Je te célébrerai avec droiture de coeur, quand j’aurai appris les ordonnances de ta justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Je veux garder tes statuts; ne me délaisse point entièrement. BETH.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Par quel moyen le jeune homme rendra-t-il pure sa voie? Ce sera en y prenant garde selon ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Je t’ai recherché de tout mon coeur, ne me fais point fourvoyer de tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'J’ai serré ta parole dans mon coeur, afin que je ne pèche point contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Eternel! tu es béni; enseigne-moi tes statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'J’ai raconté de mes lèvres toutes les ordonnances de ta bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Je me suis réjoui dans le chemin de tes témoignages, comme si j’eusse eu toutes les richesses du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Je m’entretiendrai de tes commandements, et je regarderai à tes sentiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Je prends plaisir à tes statuts, et je n’oublierai point tes paroles. GUIMEL.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Fais ce bien à ton serviteur que.je vive, et je garderai ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Dessille mes yeux, afin que je regarde aux merveilles de ta Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Je suis voyageur en la terre; ne cache point de moi tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Mon âme est toute embrasée de l’affection qu’elle a de tout temps pour tes ordonnances.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Tu as rudement tancé les orgueilleux maudits, qui se détournent de tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Ote de dessus moi l’opprobre et le mépris; car j’ai gardé tes témoignages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Même les principaux se sont assis et ont parlé contre moi, pendant que ton serviteur s’entretenait de tes statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Aussi tes témoignages sont mes plaisirs, et les gens de mon conseil. DALETH.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Mon âme est attachée à la poudre; fais-moi revivre selon ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Je t’ai déclaré au long mes voies, et tu m’as répondu; enseigne- moi tes statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Fais-moi entendre la voie de tes commandements, et je discourrai de tes merveilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Mon âme s’est fondue d’ennui, relève moi selon tes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Eloigne de moi la voie du mensonge, et me donne gratuitement ta Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'J’ai choisi la voie de la vérité, et je me suis proposé tes ordonnances.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'J’ai été attaché à tes témoignages, ô Eternel! ne me fais point rougir de honte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Je courrai par la voie de tes commandements, quand tu auras mis mon coeur au large. HE.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Eternel, enseigne-moi la voie de tes statuts, et je la garderai jusques au bout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Donne-moi de l’intelligence; je garderai ta Loi, et je l’observerai de tout mon coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Fais-moi marcher dans le sentier de tes commandements; car j’y prends plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Incline mon coeur à tes témoignages, et non point au gain déshonnête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Détourne mes yeux qu’ils ne regardent à la vanité; fais-moi revivre par le moyen de tes voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Ratifie ta parole à ton serviteur, qui est adonné à ta crainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Ote mon opprobre, lequel j’ai craint; car tes ordonnances sont bonnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Voici, je suis affectionné à tes commandements; fais-moi revivre par ta justice. VAU.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Et que tes faveurs viennent sur moi, ô Eternel! et ta délivrance aussi, selon ta parole;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'Afin que j’aie de quoi répondre à celui qui me charge d’opprobre: car j’ai mis ma confiance en ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Et n’arrache point de ma bouche la parole de vérité; car je me suis attendu à tes ordonnances.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Je garderai continuellement ta Loi, à toujours et à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Je marcherai au large, parce que j’ai recherché tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Je parlerai de tes témoignages devant les Rois, et je ne rougirai point de honte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Et je prendrai mon plaisir en tes commandements, que j’ai aimés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Même j’étendrai mes mains vers tes commandements, que j’ai aimés; et je m’entretiendrai de tes statuts. ZAIN.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Souviens-toi de la parole donnée à ton serviteur, à laquelle tu as fait que je me suis attendu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'C’ est ici ma consolation dans mon affliction, que ta parole m’a remis en vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Les orgueilleux se sont fort moqués de moi, mais je ne me suis point dé tourné de ta Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Eternel, je me suis souvenu des jugements d’ancienneté, et je me suis consolé en eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'L’horreur m’a saisi, à cause des méchants qui ont abandonné ta Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Tes statuts ont été le sujet de mes cantiques dans la maison où j ai demeuré comme voyageur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Eternel, je me suis souvenu de ton Nom pendant la nuit, et j’ai gardé ta Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Cela m’est arrivé, parce que je gardais tes commandements. HETH.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Ô Eternel! j’ai conclu que ma portion était de garder tes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Je t’ai supplié de tout mon cœur, aie pitié de moi selon ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'J’ai fait le compte de mes voies, et j’ai rebroussé chemin vers tes témoignages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Je me suis hâté, je n’ai point différé à garder tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Les troupes des méchants m’ont pillé, mais je n’ai point oublié ta Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Je me lève à minuit pour te célébrer à cause des ordonnances de ta justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Je m’accompagne de tous ceux qui te craignent, et qui gardent tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Eternel, la terre est pleine de tes faveurs; enseigne-moi tes statuts. TETH.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Eternel, tu as fait du bien à ton serviteur selon ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Enseigne-moi d’avoir bon sens et connaissance, car j’ai ajouté foi à tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Avant que je fusse affligé, j’allais à travers champs; mais maintenant j’observe ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Tu es bon et bienfaisant, enseigne-moi tes statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Les orgueilleux ont forgé des faussetés contre moi; mais je garderai de tout mon coeur tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Leur coeur est comme figé de graisse; mais moi, je prends plaisir en ta Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Il m’est bon que j’aie été affligé, afin que j’apprenne tes statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'La Loi que tu as prononcée de ta bouche, m’ est plus précieuse que mille pièces d’or ou d’argent. JOD.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Tes mains m’ont fait, et façonné; rends-moi entendu, afin que j’apprenne tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Ceux qui te craignent me verront, et se réjouiront; parce que je me suis attendu à ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Je connais, ô Eternel! que tes ordonnances ne sont que justice; et que tu m’as affligé suivant ta fidélité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Je te prie, que ta miséricorde me console, selon ta parole adressée à ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Que tes compassions se répandent sur moi, et je vivrai; car ta Loi est tout mon plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Que les orgueilleux rougissent de honte, de ce qu ils m’ont renversé sans sujet; mais moi, je discourrai de tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Que ceux qui te craignent, et ceux qui connaissent tes témoignages, reviennent vers moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Que mon coeur soit intègre dans tes statuts, afin que je ne rougisse point de honte. CAPH.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Mon âme s’est consumée en attendant ta délivrance; je me suis attendu à ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Mes yeux se sont épuisés en attendant ta parole, lorsque j’ai dit: quand me consoleras-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Car je suis devenu comme un outre mis à la fumée, et je n’ai point oublié tes statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Combien ont à durer les jours de ton serviteur? Quand jugeras- tu ceux qui me poursuivent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Les orgueilleux m’ont creusé des fosses, ce qui n’est pas selon ta Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Tous tes commandements ne sont que fidélité; on me persécute sans cause; aide-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'On m’a presque réduit à rien, et mis par terre: mais je n’ai point abandonné tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Fais-moi revivre selon ta miséricorde, et je garderai le témoignage de ta bouche. LAMED.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Ô Eternel! ta parole subsiste à toujours dans les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Ta fidélité dure d’âge en âge; tu as établi la terre, et elle demeure ferme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Ces choses subsistent aujourd’hui selon tes ordonnances; car toutes choses te servent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'N’eût été que ta Loi a été tout mon plaisir, j’eusse déjà péri dans mon affliction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Je n’oublierai jamais tes commandements; car tu m’as fait revivre par eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Je suis à toi, sauve-moi; car j’ai recherché tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Les méchants m’ont attendu, pour me faire périr; mais je me suis rendu attentif à tes témoignages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'J’ai vu un bout dans toutes les choses les plus parfaites; mais ton commandement est d’une très-grande étendue. MEM.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Ô combien j’aime ta Loi! c’est ce dont je m’entretiens tout le jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Tu m’as rendu plus sage par tes commandements, que ne sont mes ennemis; parce que tes commandements sont toujours avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'J’ai surpassé en prudence tous ceux qui m’avaient enseigné, parce que tes témoignages son mon entretien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Je suis devenu plus intelligent que les anciens, parce que j’ai observé tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'J’ai gardé mes pieds de toute mauvaise voie, afin que j’observasse ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Je ne me suis point détourné de tes ordonnances, parce que tu me les as enseignées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Ô que ta parole a été douce à mon palais! plus douce que le miel à ma bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Je suis devenu intelligent par tes commandements, c’est pourquoi j’ai haï toute voie de mensonge. NUN.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Ta parole est une lampe à mon pied, et une lumière à mon sentier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'J’ai juré, et je le tiendrai, d’observer les ordonnances de ta justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Eternel, je suis extrêmement affligé, fais-moi revivre selon ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Eternel, je te prie, aie pour agréables les oblations volontaires de ma bouche, et enseigne-moi tes ordonnances.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Ma vie a été continuellement en danger, toutefois je n’ai point oublié ta Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Les méchants m’ont tendu des piéges, toutefois je ne me suis point égaré de tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'J’ai pris pour héritage perpétuel tes témoignages; car ils sont la joie de mon coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'J’ai incliné mon coeur à accomplir toujours tes statuts jusques au bout. SAMECH.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'J’ai eu en haine les pensées diverses, mais j’ai aimé ta Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Tu es mon asile et mon bouclier, je me suis attendu à ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Méchants, retirez-vous de moi, et je garderai les commandements de mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Soutiens-moi suivant ta parole, et je vivrai; et ne me fais point rougir de honte en me refusant ce que j’espérais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Soutiens-moi, et je serai en sûreté, et j’aurai continuellement les yeux sur tes statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Tu as foulé aux pieds tous ceux qui se détournent de tes statuts; car le mensonge est le moyen dont ils se servent pour tromper.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Tu as réduit à néant tous les méchants de la terre, comme n’étant qu’écume; c’est pourquoi j’ai aimé tes témoignages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Ma chair a frémi de la frayeur que j’ai de toi, et j’ai craint tes jugements. HAJIN.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'J’ai exercé jugement et justice, ne m’abandonne point à ceux qui me font tort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Sois le pleige de ton serviteur pour son bien; et ne permets pas que je sois opprimé par les orgueilleux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Mes yeux se sont épuisés en attendant ta délivrance, et la parole de ta justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Agis envers ton serviteur suivant ta miséricorde et m’enseigne tes statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Je suis ton serviteur, rends-moi intelligent, et je connaîtrai tes témoignages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Il est temps que l’Eternel opère; ils ont aboli ta Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'C’est pourquoi j’ai aimé tes commandements, plus que l’or, même plus que le fin or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'C’est pourquoi j’ai estimé droits tous les commandements que tu donnes de toutes choses, et j’ai eu en haine toute voie de mensonge. PE.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Tes témoignages sont des choses merveilleuses; c’est pourquoi mon âme les a gardés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'L’entrée de tes paroles illumine, et donne de l’intelligence aux simples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'J’ai ouvert ma bouche, et j’ai soupiré; car j’ai souhaité tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Regarde-moi, et aie pitié de moi, selon que tu as ordinairement compassion de ceux qui aiment ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Affermis mes pas sur ta parole, et que l’iniquité n’ait point d’empire sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Délivre-moi de l’oppression des hommes, afin que je garde tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Fais luire ta face sur ton serviteur, et m’enseigne tes statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Mes yeux se sont fondus en ruisseaux d’eau, parce qu’on n’observe point ta Loi. TSADE.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Tu es juste, ô Eternel! et droit en tes jugements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Tu as ordonné tes témoignages comme une chose juste, et souverainement ferme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Mon zèle m’a miné; parce que mes adversaires ont oublié tes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Ta parole est souverainement raffinée, c’est pourquoi ton serviteur l’aime.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Je suis petit et méprisé, toutefois je n’oublie point tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Ta justice est une justice à toujours, et ta Loi est la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'La détresse et l’angoisse m’avaient rencontré; mais tes commandements sont mes plaisirs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Tes témoignages ne sont que justice à toujours; donne m’en l’intelligence, afin que je vive. KOPH.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'J’ai crié de tout mon coeur, réponds-moi, ô Eternel! et je garderai tes statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'J’ai crié vers toi; sauve-moi, afin que j’observe tes témoignages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'J’ai prévenu le point du jour, et j’ai crié; je me suis attendu à ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Mes yeux ont prévenu les veilles de la nuit pour méditer la parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Ecoute ma voix selon ta miséricorde: ô Eternel! fais-moi revivre selon ton ordonnance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Ceux qui sont adonnés à des machinations se sont approchés de moi, et ils se sont éloignés de ta Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Eternel, tu es aussi près de moi; et tous tes commandements ne sont que vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'J’ai connu dès longtemps touchant tes témoignages, que tu les as fondés pour toujours. RESCH.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Regarde mon affliction, et m’en retire; car je n’ai point oublié ta Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Soutiens ma cause, et me rachète; fais-moi revivre suivant ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'La délivrance est loin des méchants; parce qu’ils n’ont point recherché tes statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Tes compassions sont en grand nombre, ô Eternel! fais-moi revivre selon tes ordonnances.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Ceux qui me persécutent et qui me pressent, sont en grand nombre: toutefois je ne me suis point détourné de tes témoignages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'J’ai jeté les yeux sur les perfides et j’ai été rempli de tristesse de ce qu’ils n’observaient point ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Regarde combien j’ai aimé tes commandements; Eternel! fais-moi revivre selon ta miséricorde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Le principal point de ta parole est la vérité, et toute l’ordonnance de ta justice est à toujours. SCIN.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Les principaux du peuple m’ont persécuté sans sujet; mais mon coeur a été effrayé à cause de ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Je me réjouis de ta parole, comme ferait celui qui aurait trouvé un grand butin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'J’ai eu en haine et en abomination le mensonge; j’ai aimé ta Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Sept fois le jour je te loue à cause des ordonnances de ta justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Il y a une grande paix pour ceux qui aiment ta Loi, et rien ne peut les renverser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Eternel, j’ai espéré en ta délivrance, et j’ai fait tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Mon âme a observé tes témoignages, et je les ai souverainement aimés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'J’ai observé tes commandements et tes témoignages; car toutes mes voies sont devant toi. THAU.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Eternel, que mon cri approche de ta présence; rends-moi intelligent selon ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Que ma supplication vienne devant toi; délivre-moi selon ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Mes lèvres publieront ta louange, quand tu m’auras enseigné tes statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Ma langue ne s’entretiendra que de ta parole; parce que tous tes commandements ne sont que justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Que ta main me soit en aide, parce que j’ai choisi tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Eternel, j’ai souhaité ta délivrance, et ta Loi est tout mon plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Que mon âme vive, afin qu’elle te loue; et fais que tes ordonnances me soient en aide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'J’ai été égaré comme la brebis perdue; cherche ton serviteur; car je n’ai point mis en oubli tes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Cantique de Mahaloth. J’ai invoqué l’Eternel en ma grande détresse, et il m’a exaucé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Eternel, délivre mon âme des fausses lèvres, et de la langue trompeuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Que te donnera, et te profitera la langue trompeuse?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Ce sont des flèches aiguës tirées par un homme puissant, et des charbons de genèvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Hélas! Que je suis misérable de séjourner en Mésech, et de demeurer aux tentes de Kédar!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Que mon âme ait tant demeuré avec celui qui hait la paix!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Je ne cherche que la paix, mais lorsque j’en parle, les voilà à la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Cantique de Mahaloth. J’élève mes yeux vers les montagnes, d’où me viendra le secours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Mon secours vient de l’Eternel qui a fait les cieux et la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Il ne permettra point que ton pied soit ébranlé; celui qui te garde ne sommeillera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Voilà, celui qui garde Israël ne sommeillera point, et ne s’endormira point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'L’Eternel est celui qui te garde, l’Eternel est ton ombre, il est à ta main droite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Le soleil ne donnera point sur toi, de jour; ni la lune, de nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'L’Eternel te gardera de tout mal, il gardera ton âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'L’Eternel gardera ton issue et ton entrée, dès maintenant et à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Cantique de Mahaloth, de David. Je me suis réjoui à cause de ceux qui me disaient: nous irons à la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Nos pieds se sont arrêté en tes portes, ô Jérusalem!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jérusalem, qui est bâtie comme une ville dont les habitants sont fort unis,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'A laquelle montent les Tribus, les Tribus de l’Eternel, ce qui est un témoignage à Israël, pour célébrer le Nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Car c’est là qu’ont été posés les sièges pour juger, les sièges, dis-je, de la maison de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Priez pour la paix de Jérusalem; que ceux qui t’aiment jouissent de la prospérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Que la paix soit à ton avant-mur, et la prospérité dans tes palais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Pour l’amour de mes frères et de mes amis, je prierai maintenant pour ta paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'A cause de la maison de l’Eternel notre Dieu je procurerai ton bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Cantique de Mahaloth. J’élève mes yeux à toi, qui habites dans les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Voici, comme les yeux des serviteurs regardent à la main de leurs maîtres; et comme les yeux de la servante regardent à la main de sa maîtresse; ainsi nos yeux regardent à l’Eternel notre Dieu, jusqu’à ce qu’il ait pitié de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Aie pitié de nous, ô Eternel! aie pitié de nous; car nous avons été accablés de mépris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Notre âme est accablée des insultes de ceux qui sont à leur aise, et du mépris des orgueilleux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Cantique de Mahaloth, de David. N’eut été l’Eternel, qui a été pour nous, dise maintenant Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'N’eût été l’Eternel, qui a été pour nous, quand les hommes se sont élevés contre nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'Ils nous eussent dès lors engloutis tout vifs; pendant que leur colère était enflammée contre nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Dès-lors les eaux se fussent débordées sur nous, un torrent eût passé sur notre âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Dès-lors les eaux enflées fussent passées sur notre âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Béni soit l’Eternel; qui ne nous a point livrés en proie à leurs dents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Notre âme est échappée, comme l’oiseau du filet des oiseleurs; le filet a été rompu, et nous sommes échappés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Notre aide soit au nom de l’Eternel qui a fait les cieux et la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Cantique de Mahaloth. Ceux qui se confient en l’Eternel sont comme la montagne de Sion, qui ne peut être ébranlée, et qui se soutient à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Quant à Jérusalem, il y a des montagnes à l’entour d’elle, et l’Eternel est à l’entour de son peuple, dès maintenant et à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Car la verge de la méchanceté ne reposera point sur le lot des justes; de peur que les justes ne mettent leurs mains à l’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Eternel, bénis les gens de bien et ceux dont le coeur est droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Mais quant à ceux qui tordent leurs sentiers obliques, l’Eternel les fera marcher avec les ouvriers d’iniquité. La paix sera sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Cantique de Mahaloth. Quand l’Eternel ramena les captifs de Sion, nous étions comme ceux qui songent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Alors notre bouche fut remplie de joie, et notre langue de chant de triomphe, alors on disait parmi les nations: l’Eternel a fait de grandes choses à ceux-ci;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'L’Eternel nous a fait de grandes choses; nous en avons été réjouis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Ô Eternel! ramène nos prisonniers, en sorte qu’ils soient comme les courants des eaux au pays du Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Ceux qui sèment avec larmes, moissonneront avec chant de triomphe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Celui qui porte la semence pour la mettre en terre, ira son chemin en pleurant, mais il reviendra avec chant de triomphe, quand il portera ses gerbes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Cantique de Mahaloth, de Salomon. Si l’Eternel ne bâtit la maison, ceux qui la bâtissent, y travaillent en vain; si l’Eternel ne garde la ville, celui qui la garde, fait le guet en vain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'C’est en vain que vous vous levez de grand matin, que vous vous couchez tard, et que vous mangez le pain de douleurs; certes c’est Dieu qui donne du repos à celui qu’il aime.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Voici, les enfants sont un héritage donné par l’Eternel; et le fruit du ventre est une récompense de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Telles que sont les flèches en la main d’un homme puissant, tels sont les fils d’un père qui est dans la fleur de son âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Ô Que bienheureux est l’homme qui en a rempli son carquois! des hommes comme ceux-là ne rougiront point de honte, quand ils parleront avec leurs ennemis à la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Cantique de Mahaloth. Bienheureux est quiconque craint l’Eternel, et marche dans ses voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Car tu mangeras du travail de tes mains; tu seras bienheureux, et tu prospéreras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Ta femme sera dans ta maison, comme une vigne abondante en fruit; et tes enfants seront autour de ta table, comme des plantes d’oliviers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Voici, certainement ainsi sera béni le personnage qui craint l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'L’Eternel te bénira de Sion, et tu verras le bien de Jérusalem tous les jours de ta vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'Et tu verras des enfants à tes enfants. La paix sera sur Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Cantique de Mahaloth. Qu’Israël dise maintenant: ils m’ont souvent tourmenté dès ma jeunesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'Ils m’ont souvent tourmenté dès ma jeunesse; toutefois ils n’ont point encore été plus forts que moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Des laboureurs ont labouré sur mon dos, ils y ont tiré tout au long leurs sillons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'L’Eternel est juste; il a coupé les cordes des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Tous ceux qui ont Sion en haine, rougiront de honte, et seront repoussés en arrière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Ils seront comme l’herbe des toits, qui est sèche avant qu’elle monte en tuyau;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'De laquelle le moissonneur ne remplit point sa main, ni celui qui cueille les javelles n’en remplit point ses bras;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Et dont les passants ne diront point: la bénédiction de l’Eternel soit sur vous; nous vous bénissons au nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Cantique Mahaloth. Ô Éternel! je t’invoque des lieux profonds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Seigneur, écoute ma voix! que tes oreilles soient attentives à la voix de mes supplications.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Ô Eternel! si tu prends garde aux iniquités, Seigneur, qui est-ce qui subsistera?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Mais il y a pardon par-devers toi, afin que tu sois craint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'J’ai attendu l’Eternel; mon âme l’a attendu, et j’ai eu mon attente en sa parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Mon âme attend le Seigneur plus que les sentinelles n’attendent le matin, plus que les sentinelles n’attendent le matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Israël, attends-toi à l’Eternel: car l’Eternel est miséricordieux et il y a rédemption en abondance par devers lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'Et lui-même rachètera Israël de toutes ses iniquités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Cantique de Mahaloth, de David. Ô Éternel! mon coeur ne s’est point élevé, et mes yeux ne se sont point haussés, et je n’ai point marché en des choses grandes et merveilleuses au-dessus de ma portée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'N’ai-je point soumis et fait taire mon coeur, comme celui qui est sevré fait envers sa mère; mon coeur est en moi, comme celui qui est sevré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Israël attends-toi à l’Eternel dès maintenant et à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Cantique de Mahaloth. Ô Eternel! souviens-toi de David, et de toute son affliction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Lequel a juré à l’Eternel, et fait voeu au Puissant de Jacob, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'Si j’entre au Tabernacle de ma maison, et si je monte sur le lit où je couche;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'Si je donne du sommeil à mes yeux, si je laisse sommeiller mes paupières,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'Jusqu’à ce que j’aurai trouvé un lieu à l’Eternel, et des pavillons pour le Puissant de Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Voici, nous avons ouï parler d’elle vers Ephrat, nous l’avons trouvée aux champs de Jahar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Nous entrerons dans ses pavillons, et nous nous prosternerons devant son marchepied.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Lève-toi, ô Eternel! pour venir en ton repos, toi, et l’Arche de ta force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Que tes Sacrificateurs soient revêtus de la justice, et que tes bien-aimés chantent de joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Pour l’amour de David ton serviteur, ne fais point que ton Oint tourne le visage en arrière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'L’Eternel a juré en vérité à David, et il ne se rétractera point, disant: je mettrai du fruit de ton ventre sur ton trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Si tes enfants gardent mon alliance, et mon témoignage, que je leur enseignerai, leurs fils aussi seront assis à perpétuité sur ton trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Car l’Eternel a choisi Sion; il l’a préférée pour être son siège.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'Elle est, dit-il, mon repos à perpétuité; j’y demeurerai, parce que je l’ai chérie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Je bénirai abondamment ses vivres; je rassasierai de pain ses pauvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Et je revêtirai ses Sacrificateurs de délivrance; et ses bien- aimés chanteront avec des transports.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Je ferai qu’en elle germera une corne à David; je préparerai une lampe à mon Oint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Je revêtirai de honte ses ennemis, et son diadème fleurira sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Voici, oh! Que c’est une chose bonne, et que c’est une chose agréable, que les frères s’entretiennent, qu’ils s’entretiennent, dis-je, ensemble!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'C’est comme cette huile précieuse, répandue sur la tête, laquelle découle sur la barbe d’Aaron, et qui découle sur le bord de ses vêtements;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Et comme la rosée de Hermon, et celle qui descend sur les montagnes de Sion: car c’est là que l’Eternel a ordonné la bénédiction et la vie, à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Cantique de Mahaloth. Voici, bénissez l’Eternel, vous tous les serviteurs de l’Eternel, qui assistez toutes les nuits dans la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Elevez vos mains dans le Sanctuaire, et bénissez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'L’Eternel, qui a fait les cieux et la terre, te bénisse de Sion!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Louez le Nom de l’Eternel; vous serviteurs de l’Eternel, louez-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'Vous qui assistez en la maison de l’Eternel, aux parvis de la maison de notre Dieu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Louez l’Eternel, car l’Eternel est bon; psalmodiez à son Nom, car il est agréable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Car l’Eternel s’est choisi Jacob, et Israël pour son plus précieux joyau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Certainement je sais que l’Eternel est grand, et que notre Seigneur est au-dessus de tous les dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'L’Eternel fait tout ce qu’il lui plaît, dans les cieux et sur la terre, dans la mer, et dans tous les abîmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'C’est lui qui fait monter les vapeurs du bout de la terre; il fait les éclairs pour la pluie; il tire le vent hors de ses trésors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'C’est lui qui a frappé les premiers-nés d’Egypte, tant des hommes que des bêtes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Qui a envoyé des prodiges et des miracles au milieu de toi, ô Egypte! contre Pharaon, et contre tous ses serviteurs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Qui a frappé plusieurs nations, et tué les puissants Rois;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Savoir, Sihon le roi des Amorrhéens, et Hog le roi de Hasan, et ceux de tous les Royaumes de Canaan;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'Et qui a donné leur pays en héritage, en héritage, dis-je, à Israël son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Eternel, ta renommée est perpétuelle; Eternel, la mémoire qu’on a de toi est d’âge en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Car l’Eternel jugera son peuple, et se repentira à l’égard de ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Les dieux des nations ne sont que de l’or et de l’argent, un ouvrage de mains d’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Ils ont une bouche, et ne parlent point; ils ont des yeux, et ne voient point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'Ils ont des oreilles, et n’entendent point; il n’y a point aussi de souffle dans leur bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Que ceux qui les font, et tous ceux qui s’y confient, leur soient faits semblables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Maison d’Israël, bénissez l’Eternel; maison d’Aaron, bénissez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Maison des Lévites, bénissez l’Eternel; vous qui craignez l’Eternel, bénissez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Béni soit de Sion l’Eternel qui habite dans Jérusalem. Louez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Célébrez l’Eternel, car il est bon; parce que sa miséricorde demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Célébrez le Dieu des dieux; parce que sa miséricorde demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Célébrez le Seigneur des Seigneurs; parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Célébrez celui qui seul fait de grandes merveilles; parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Celui qui a fait avec intelligence les cieux; parce que sa bonté demeure à toujours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Celui qui a étendu la terre sur les eaux; parce que sa bonté demeure à toujours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Celui qui a fait les grands luminaires; parce que sa bonté demeure à toujours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Le soleil pour dominer sur le jour; parce que sa bonté demeure à toujours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'La lune et les étoiles pour avoir domination sur la nuit; parce que sa bonté demeure à toujours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Celui qui a frappé l’Egypte en leurs premiers-nés; parce que sa bonté demeure à toujours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'Et qui a fait sortir Israël du milieu d’eux; parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'Et cela avec main forte et bras étendu; parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Il a fendu la mer Rouge en deux; parce que sa bonté demeure à toujours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'Et a fait passer Israël par le milieu d’elle; parce que sa bonté demeure à toujours:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'Et a renversé Pharaon et son armée dans la mer Rouge; parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Il a conduit son peuple par le désert; parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'I1 a frappé les grands Rois; parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'Et a tué les Rois magnifiques; parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Savoir, Sihon Roi des Amorrhéens; parce que sa bonté demeure à toujours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'Et Hog Roi de Basan; parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'Et a donné leur pays en héritage; parce que sa bonté demeure à toujours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'En héritage à Israël son serviteur; parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Et qui, lorsque nous étions fort abaissés, s’est souvenu de nous, parce que sa bonté demeure à toujours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'Et nous a délivrés de la main de nos adversaires; parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Et il donne la nourriture à toute chair; parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Célébrez le Dieu des cieux; parce que sa bonté demeure à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Nous nous sommes assis auprès des fleuves de Babylone, et nous y avons pleuré, nous souvenant de Sion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Nous avons pendu nos harpes aux saules, au milieu d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Quand ceux qui nous avaient emmenés prisonniers, nous ont demandé des paroles de Cantique, et de les réjouir de nos harpes que nous avions pendues, en nous disant: Chantez-nous quelque chose des cantiques de Sion; nous avons répondu:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Comment chanterions-nous les Cantiques de l’Eternel dans une terre d’étrangèrs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Si je t’oublie, Jérusalem, que ma droite s’oublie elle-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Que ma langue soit attachée à mon palais, si je ne me souviens de toi, et si je ne fais de Jérusalem le principal sujet de ma réjouissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Ô Eternel, souviens-toi des enfants d’Edom, qui en la journée de Jérusalem disaient: découvrez, découvrez jusqu’à ses fondements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Fille de Babylone, qui va être détruite, heureux celui qui te rendra la pareille de ce que tu nous as fait!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Heureux celui qui saisira tes petits enfants et qui les froissera contre les pierres!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Psaume de David. Je te célébrerai de tout mon coeur, je te psalmodierai en la présence des Souverains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Je me prosternerai dans le palais de ta sainteté, et je célébrerai ton Nom pour l’amour de ta bonté, et de ta vérité; car tu as magnifié ta parole au-dessus de toute ta renommée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Au jour que j’ai crié tu m’as exaucé; et tu m’as fortifié d’une nouvelle force en mon âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Eternel! Tous les Rois de la terre te célébreront, quand ils auront ouï les paroles de ta bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'Et ils chanteront les voies de l’Eternel; car la gloire de l’Eternel est grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Car l’Eternel est haut élevé, et il voit les choses basses, et il connaît de loin les choses élevées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Si je marche au milieu de l’adversité, tu me vivifieras, tu avanceras ta main contre la colère de mes ennemis, et ta droite me délivrera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'L’Eternel achèvera ce qui me concerne. Eternel, ta bonté demeure à toujours; tu n’abandonneras point l’oeuvre de tes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Psaume de David, donné au maître chantre. Eternel, tu m’as sondé, et tu m’as connu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Tu connais quand je m’assieds et quand je me lève; tu aperçois de loin ma pensée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Tu m’enceins, soit que je marche, soit que je m’arrête; et tu as accoutumé toutes mes voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Même avant que la parole soit sur ma langue, voici, ô Eternel! tu connais déjà le tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Tu me tiens serré par derrière et par devant, et tu as mis sur moi ta main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Ta science est trop merveilleuse pour moi, et elle est si haut élevée, que je n’y saurais atteindre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Où irai-je loin de ton Esprit; et où fuirai-je loin de ta face?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Si je monte aux cieux, tu y es; si je me couche au sépulcre, t’y voilà.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Si je prends les ailes de l’aube du jour, et que je me loge au bout de la mer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'Là même ta main me conduira, et ta droite m’y saisira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Si je dis: au moins les ténèbres me couvriront; la nuit même sera une lumière tout autour de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Même les ténèbres ne me cacheront point à toi, et la nuit resplendira comme le jour, et les ténèbres comme la lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Or tu as possédé mes reins dès-lors que tu m’as enveloppé au ventre de ma mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Je te célébrerai de ce que j’ai été fait d’une si étrange et si admirable manière; tes oeuvres sont merveilleuses, et mon âme le connaît très-bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'L’agencement de mes os ne t’a point été caché, lorsque j’ai été fait en un lieu secret, et façonné comme de broderie dans les bas lieux de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Tes yeux m’ont vu quand j’étais comme un peloton, et toutes ces choses s’écrivaient dans ton livre aux jours qu’elles se formaient, même lorsqu’il n’y en avait encore aucune.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'C’est pourquoi, ô Dieu Fort! combien me sont précieuses les considérations que j’ai de tes faits, et combien en est grand le nombre!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Les veux-je nombrer? elles sont en plus grand nombre que le sablon. Suis-je réveillé? je suis encore avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Ô Dieu! ne tueras-tu pas le méchant? c’est pourquoi, hommes sanguinaires, retirez-vous loin de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Car ils ont parlé de toi, en pensant à quelque méchanceté; ils ont élevé tes ennemis en mentant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Eternel, n’aurais-je point en haine ceux qui te haïssent; et ne serais-je point irrité contre ceux qui s’élèvent contre toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Je les ai haïs d’une parfaite haine; ils m’ont été pour ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Ô Dieu Fort! sonde-moi, et considère mon coeur; éprouve-moi, et considère mes discours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Et regarde s’il y a en moi aucun dessein de chagriner autrui; et conduis-moi par la voie du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Psaume de David, donné au maître chantre. Eternel, délivre-moi de l’homme méchant; garde-moi de l’homme violent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Ils ont pensé des maux en leur coeur; ils assemblent tous les jours des combats.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'Ils affilent leur langue comme un serpent; il y a du venin de vipères sous leurs lèvres; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Eternel, garde-moi des mains du méchant, préserve-moi de l’homme violent, de ceux qui ont machiné de me heurter pour me faire tomber.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Les orgueilleux m’ont caché le piège, et ils ont tendu avec des cordes un rets à l’endroit de mon passage, ils ont mis des trébuchets pour me prendre; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'J’ai dit à l’Eternel: tu es mon Dieu Fort; Eternel! prête l’oreille à la voix de mes supplications.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Ô Eternel! Seigneur! la force de mon salut, tu as couvert de toutes parts ma tête au jour de la bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Eternel n’accorde point au méchant ses souhaits; ne fais point que sa pensée ait son effet, ils s’élèveraient. Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Quant aux principaux de ceux qui m’assiégent, que la peine de leurs lèvres les couvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Que des charbons embrasés tombent sur eux, qu’il les fasse tomber au feu, et dans des fosses profondes, sans qu’ils se relèvent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Que l’homme médisant ne soit point affermi en la terre; et quant à l’homme violent et mauvais, qu’on chasse après lui jusqu’à ce qu’il soit exterminé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Je sais que l’Eternel fera justice à l’affligé, et droit aux misérables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Quoi qu’il en soit, les justes célébreront ton Nom, et les hommes droits habiteront devant ta face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 14, '');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Psaume de David. Eternel, je t’invoque, hâte-toi de venir vers moi; prête l’oreille à ma voix lorsque je crie à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Que ma requête te soit agréable comme le parfum; et l’élévation de mes mains, comme l’oblation du soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Eternel, mets une garde à ma bouche; garde l’entrée de mes lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'N’incline point mon coeur à des choses mauvaises, tellement que je commette quelques méchantes actions par malice, avec les hommes ouvriers d’iniquité; et que je ne mange point de leurs délices.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Que le juste me frappe, ce me sera une faveur: et qu’il me réprimande, ce me sera un baume excellent; il ne blessera point ma tête; car même encore ma requête sera pour eux en leurs calamités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Quand leurs gouverneurs auront été précipités parmi des rochers, alors on entendra que mes paroles sont agréables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Nos os sont épars près de la gueule du sépulcre, comme quand quelqu’un coupe et fend le bois qui est par terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'C’est pourquoi, ô Eternel Seigneur! mes yeux sont vers toi; je me suis retiré vers toi, n’abandonne point mon âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Garde-moi du piége qu’ils m’ont tendu, et des filets des ouvriers d’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Que tous les méchants tombent chacun dans son filet, jusqu’à ce que je sois passé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Maschil de David, qui est une requête qu’il fit lorsqu’il était dans la caverne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Je crie de ma voix à l’Eternel, je supplie de ma voix l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'J’épands devant lui ma complainte; je déclare mon angoisse devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Quand mon esprit s’est pâmé en moi, alors tu as connu mon sentier. Ils m’ont caché un piége au chemin par lequel je marchais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Je contemplais à ma droite, et je regardais, et il n y avait personne qui me reconnût; tout refuge me manquait, et il n’y avait personne qui eût soin de mon âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Eternel, je me suis écrié vers toi; j’ai dit, tu es ma retraite et ma portion en la terre des vivants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Sois attentif à mon cri, car je suis devenu fort chétif; délivre- moi de ceux qui me poursuivent; car ils sont plus puissants que moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 8, 'Délivre-moi du lieu où je suis renfermé, et je célébrerai ton Nom; les justes viendront autour de moi, parce que tu m’auras fait ce bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Psaume de David. Eternel, écoute ma requête, prête l’oreille à mes supplications, suivant ta fidélité; réponds-moi à cause de ta justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Et n’entre point en jugement avec ton serviteur; car nul homme vivant ne sera justifié devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Car l’ennemi poursuit mon âme; il a foulé ma vie par terre; il m’as mis aux lieux ténébreux, comme ceux qui sont morts depuis longtemps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Et mon esprit se pâme en moi, mon coeur est désolé au-dedans de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Il me souvient des jours anciens; je médite tous tes faits, et je discours des oeuvres de tes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'J’étends mes mains vers toi; mon âme s’adresse à toi comme une terre altérée: Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Ô Eternel, hâte-toi, réponds-moi, l’esprit me défaut; ne cache point ta face arrière de moi, tellement que je devienne semblable à ceux qui descendent en la fosse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Fais-moi ouïr dès le matin ta miséricorde, car je me suis assuré en toi; fais-moi connaître le chemin par lequel j’ai à marcher, car j’ai élevé mon coeur vers toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Eternel, délivre-moi de mes ennemis; car je me suis réfugié chez toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Enseigne-moi à faire ta volonté; car tu es mon Dieu; que ton bon Esprit me conduise comme par un pays uni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Eternel, rends-moi la vie pour l’amour de ton Nom; retire mon âme de la détresse, à cause de ta justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Et selon la bonté que tu as pour moi retranche mes ennemis, et détruis tous ceux qui tiennent mon âme serrée, parce que je suis ton serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Psaume de David. Béni soit l’Eternel, mon rocher, qui dispose mes mains au combat, et mes doigts à la bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Qui déploie sa bonté envers moi, qui est ma forteresse, ma haute retraite, mon libérateur, mon bouclier, et je me suis retiré vers lui; il range mon peuple sous moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Ô Eternel! qu’est-ce que de l’homme, que tu aies soin de lui? du fils de l’homme mortel, que tu en tiennes compte?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'L’homme est semblable à la vanité; ses jours sont comme une ombre qui passe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Eternel abaisse tes cieux, et descends; touche les montagnes, et qu’elles fument.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Lance l’éclair, et les dissipe; décoche tes flèches, et les mets en déroute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Etends tes mains d’en haut, sauve-moi, et me délivre des grosses eaux, de la main des enfants de l’étranger;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'La bouche desquels profère mensonge; et dont la droite est une droite trompeuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Ô Dieu! je chanterai un nouveau Cantique; je te psalmodierai sur la musette, et avec l’instrument à dix cordes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'C’est lui qui envoie la délivrance aux Rois, et qui délivre de l’épée dangereuse David son serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Retire-moi et me délivre de la main des enfants de l’étranger; dont la bouche profère mensonge, et dont la droite est une droite trompeuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Afin que nos fils soient comme de jeunes plantes, croissant en leur jeunesse; et nos filles, comme des pierres angulaires taillées pour l’ornement d’un palais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Que nos dépenses soient pleines, fournissant toute espèce de provision; que nos troupeaux multiplient par milliers, même par dix milliers dans nos rues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Que nos boeufs soient chargés de graisse. Qu’il n’y ait ni brèche, ni sortie dans nos murailles ni cri dans nos places.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Ô que bienheureux est le peuple auquel il en est ainsi! ô que bienheureux est le peuple duquel l’Eternel est le Dieu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Psaume de louange, composé par David. Aleph. Mon Dieu, mon Roi, je t’exalterai, et je bénirai ton Nom à toujours, et à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Je te bénirai chaque jour, et je louerai ton Nom à toujours, et à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'L’Eternel est grand et très-digne de louange, il n’est pas possible de sonder sa grandeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Une génération dira la louange de tes oeuvres à l’autre génération, et elles raconteront tes exploits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Je discourrai de la magnificence glorieuse de ta Majesté, et de tes faits merveilleux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Et ils réciteront la force de tes faits redoutables; et je raconterai ta grandeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Ils répandront la mémoire de ta grande bonté, et ils raconteront avec chant de triomphe ta justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'L’Eternel est miséricordieux et pitoyable, tardif à la colère, et grand en bonté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'L’Eternel est bon envers tous, et ses compassions sont au- dessus de toutes ses oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Eternel, toutes tes oeuvres te célébreront, et tes bien- aimés te béniront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Ils réciteront la gloire de ton règne, et ils raconteront tes grands exploits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Afin de donner à connaître aux hommes tes grands exploits, et la gloire de la magnificence de ton règne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Ton règne est un règne de tous les siècles, et ta domination est dans tous les âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'L’Eternel soutient tous ceux qui s’en vont tomber, et redresse tous ceux qui sont courbés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Les yeux de tous les animaux s’attendent à toi, et tu leur donnes leur pâture en leur temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Tu ouvres ta main, et tu rassasies à souhait toute créature vivante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'L’Eternel est juste en toutes ses voies, et plein de bonté en toutes ses oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'L’Eternel est près de tous ceux qui l’invoquent, de tous ceux, dis-je, qui l’invoquent en vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Il accomplit le souhait de ceux qui le craignent, et il exauce leur cri, et les délivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'L’Eternel garde tous ceux qui l’aiment; mais il exterminera tous les méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Ma bouche racontera la louange de l’Eternel, et toute chair bénira le Nom de sa sainteté à toujours, et à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Louez l’Eternel. Mon âme, loue l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Je louerai l’Eternel durant ma vie, je psalmodierai à mon Dieu tant que je vivrai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Ne vous assurez point sur les principaux d’entre les peuples, ni sur aucun fils d’homme, à qui il n’appartient point de délivrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Son esprit sort, et l’homme retourne en sa terre, et en ce jour-là ses desseins périssent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Ô que bienheureux est celui à qui le Dieu Fort de Jacob est en aide, et dont l’attente est en l’Eternel son Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'Qui a fait les cieux et la terre, la mer, et tout ce qui y est, et qui garde la vérité à toujours!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Qui fait droit à ceux à qui on fait tort; et qui donne du pain à ceux qui ont faim. L’Eternel délie ceux qui sont liés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'L’Eternel ouvre les yeux aux aveugles; l’Eternel redresse ceux qui sont courbés; l’Eternel aime les justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'L’Eternel garde les étrangers, il maintient l’orphelin et la veuve, et renverse le train des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'L’Eternel régnera à toujours. Ô Sion! ton Dieu est d’âge en âge. Louez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Louez l’Eternel; car c’est une chose bonne de psalmodier à notre Dieu, car c’est une chose agréable; et la louange en est bienséante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'L’Eternel est celui qui bâtit Jérusalem; il rassemblera ceux d’Israël qui sont dispersés çà et là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Il guérit ceux qui sont brisés de coeur, et il bande leurs plaies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Il compte le nombre des étoiles; il les appelle toutes par leur nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Notre Seigneur est grand et d’une grande puissance, son intelligence est incompréhensible.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'L’Eternel maintient les débonnaires, mais il abaisse les méchants jusqu’en terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Chantez à l’Eternel avec action de grâces, vous entre-répondant les uns aux autres; psalmodiez avec la harpe à notre Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Qui couvre de nuées les cieux; qui apprête la pluie pour la terre; qui fait produire le foin aux montagnes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Qui donne la pâture au bétail, et aux petits du corbeau, qui crient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Il ne prend point de plaisir en la force du cheval; il ne fait point cas des jambières de l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'L’Eternel met son affection en ceux qui le craignent, en ceux qui s’attendent à sa bonté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Jérusalem, loue l’Eternel; Sion, loue ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Car il a renforcé les barres de tes portes; il a béni tes enfants au milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'C’est lui qui rend paisibles tes contrées, et qui te rassasie de la moelle du froment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'C’est lui qui envoie sa parole sur la terre, et sa parole court avec beaucoup de vitesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'C’est lui qui donne la neige comme des flocons de laine, et qui répand la bruine comme de la cendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'C’est lui qui jette sa glace comme par morceaux; et qui est-ce qui pourra durer devant sa froidure?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Il envoie sa parole, et les fait fondre; il fait souffler son vent, et les eaux s’écoulent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Il déclare ses paroles à Jacob, et ses statuts et ses ordonnances à Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Il n’a pas fait ainsi à toutes les nations, c’est pourquoi elles ne connaissent point ses ordonnances. Louez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Louez l’Eternel. Louez des cieux l’Eternel; louez-le dans les hauts lieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Tous ses Anges, louez-le; toutes ses armées, louez-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Louez-le, vous soleil et lune; toutes les étoiles qui jetez de la lumière, louez-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Louez-le, vous cieux des cieux; et vous eaux qui êtes sur les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Que ces choses louent le Nom de l’Eternel; car il a commandé, et elles ont été créées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Et il les a établies à perpétuité et à toujours; il y a mis une ordonnance qui ne passera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Louez de la terre l’Eternel; louez-le, baleines, et tous les abîmes,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Feu et grêle, neige, et vapeur, vent de tourbillon, qui exécutez sa parole,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'Montagnes, et tous coteaux, arbres fruitiers, et tous cèdres,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'Bêtes sauvages, et tout bétail, reptiles, et oiseaux qui avez des ailes,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'Rois de la terre, et tous peuples, Princes, et tous Gouverneurs de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Ceux qui sont à la fleur de leur âge, et les vierges aussi, les vieillards, et les jeunes gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Qu’ils louent le Nom de l’Eternel; car son Nom seul est haut élevé; sa Majesté est sur la terre, et sur les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Et il a fait lever en haut une corne à son peuple, ce qui est une louange à tous ses bien-aimés, aux enfants d’Israël, qui est le peuple qui est près de lui. Louez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Louez l’Eternel. Chantez à l’Eternel un nouveau Cantique, et sa louange dans l’assemblée de ses bien-aimés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Qu’Israël se réjouisse en celui qui l’a fait, et que les enfants de Sion s’égayent en leur Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Qu’ils louent son Nom sur la flûte, qu’ils lui psalmodient sur le tambour, et sur la harpe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Car l’Eternel met son affection en son peuple; il rendra honorables les débonnaires en les délivrant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Les bien-aimés s’égayeront avec gloire, et ils se réjouiront dans leurs lits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Les louanges du Dieu Fort seront dans leur bouche, et des épées affilées à deux tranchants dans leur main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'Pour se venger des nations, et pour châtier les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'Pour lier leurs Rois de chaînes, et les plus honorables d’entr’eux de ceps de fer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'Pour exercer sur eux le jugement qui est écrit. Cet honneur est pour tous ses bien-aimés. Louez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Louez l’Eternel. Louez le Dieu Fort à cause de sa sainteté; Louez-le à cause de cette étendue qu’il a faite par sa force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Louez-le de ses grands exploits, louez-le selon la grandeur de sa Majesté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Louez-le avec le son de la trompette; louez-le avec la musette, et la harpe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Louez-le avec le tambour et la flûte; louez-le sur l’épinette, et sur les orgues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Louez-le avec les cymbales retentissantes; louez-le avec les cymbales de cri de réjouissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Que tout ce qui respire loue l’Eternel! Louez l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Les Proverbes de Salomon, fils de David, et Roi d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Pour connaître la sagesse et l’instruction, pour entendre les discours d’intelligence;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Pour recevoir une leçon de bon sens, de justice, de jugement et d’équité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Pour donner du discernement aux simples, et de la connaissance et de l’adresse aux jeunes gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Le sage écoutera, et deviendra mieux appris, et l’homme intelligent acquerra de la prudence;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Afin d’entendre les discours sentencieux, et ce qui est élégamment dit; les paroles des sages, et leurs énigmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'La crainte de l’Eternel est la principale science; mais les fous méprisent la sagesse et l’instruction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Mon fils, écoute l’instruction de ton père, et n’abandonne point l’enseignement de ta mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Car ce seront des grâces enfilées ensemble autour de ta tête, et des colliers autour de ton cou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Mon fils, si les pécheurs te veulent attirer, ne t’y accorde point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'S’ils disent: Viens avec nous, dressons des embûches pour tuer; épions secrètement l’innocent, quoiqu’il ne nous en ait point donné de sujet;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Engloutissons-les tout vifs, comme le sépulcre; et tout entiers, comme ceux qui descendent en la fosse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Nous trouverons toute sorte de biens précieux, nous remplirons nos maisons de butin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Tu y auras ton lot parmi nous, il n’y aura qu’une bourse pour nous tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Mon fils, ne te mets point en chemin avec eux; retire ton pied de leur sentier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Parce que leurs pieds courent au mal, et se hâtent pour répandre le sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Car comme c’est sans sujet que le rets est étendu devant les yeux de tout ce qui a des ailes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Ainsi ceux-ci dressent des embûches contre le sang de ceux-là, et épient secrètement leurs vies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Tel est le train de tout homme convoiteux de gain déshonnête, lequel enlèvera la vie de ceux qui y sont adonnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'La souveraine Sapience crie hautement au dehors, elle fait retentir sa voix dans les rues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'Elle crie dans les carrefours, là où on fait le plus de bruit, aux entrées des portes, elle prononce ses paroles par la ville:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Sots, dit-elle, jusques à quand aimerez-vous la sottise? Et jusqu’à quand les moqueurs prendront-ils plaisir à la moquerie, et les fous auront-ils en haine la science?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Etant repris par moi, convertissez-vous; voici, je vous donnerai de mon Esprit en abondance, et je vous ferai connaître mes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Parce que j’ai crié, et que vous avez refusé d’ouïr; parce que j’ai étendu ma main, et qu’il n’y a eu personne qui y prit garde;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'Et parce que vous avez rejeté tout mon conseil, et que vous n’avez point agréé que je vous reprisse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'Aussi je me rirai de votre calamité, je me moquerai quand votre effroi surviendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'Quand votre effroi surviendra comme une ruine, et que votre calamité viendra comme un tourbillon; quand la détresse et l’angoisse viendront sur vous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Alors on criera vers moi, mais je ne répondrai point; on me cherchera de grand matin, mais on ne me trouvera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Parce qu’ils auront haï la science, et qu’ils n’auront point choisi la crainte de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'Ils n’ont point aimé mon conseil; ils ont dédaigné toutes mes répréhensions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Qu’ils mangent donc le fruit de leur voie, et qu’ils se rassasient de leurs conseils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Car l’aise des sots les tue, et la prospérité des fous les perd.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Mais celui qui m’écoutera, habitera en sûreté, et sera à son aise sans être effrayé d’aucun mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Mon fils, si tu reçois mes paroles, et que tu mettes en réserve par-devers toi mes commandements;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'Tellement que tu rendes ton oreille attentive à la sagesse, et que tu inclines ton coeur à l’intelligence;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Si tu appelles à toi la prudence, et que tu adresses ta voix à l’intelligence;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'Si tu la cherches comme de l’argent, et si tu la recherches soigneusement comme des trésors;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'Alors tu connaîtras la crainte de l’Eternel, et tu trouveras la connaissance de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Car l’Eternel donne la sagesse; et de sa bouche procède la connaissance et l’intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Il réserve pour ceux qui sont droits un état permanent, et il est le bouclier de ceux qui marchent dans l’intégrité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'Pour garder les sentiers de jugement; tellement qu’ il gardera la voie de ses bien-aimés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Alors tu entendras la justice, et le jugement, et l’équité, et tout bon chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Si la sagesse vient en ton coeur, et si la connaissance est agréable à ton âme;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'La prudence te conservera, et l’intelligence te gardera;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Pour te délivrer du mauvais chemin, et de l’homme prononçant de mauvais discours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'De ceux qui laissent les chemins de la droiture pour marcher par les voies de ténèbres;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'Qui se réjouissent à mal faire, et s’égayent dans les renversements que fait le méchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'Desquels les chemins sont tortus, et qui vont de travers en leur train.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Et afin qu’il te délivre de la femme étrangère, et de la femme d’autrui, dont les paroles sont flatteuses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'Qui abandonne le conducteur de sa jeunesse, et qui a oublié l’alliance de son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Car sa maison penche vers la mort, et son chemin mène vers les trépassés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Pas un de ceux qui vont vers elle, n’en retourne, ni ne reprend les sentiers de la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Afin aussi que tu marches dans la voie des gens de bien, et que tu gardes les sentiers des justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Car ceux qui sont justes habiteront en la terre, et les hommes intègres demeureront de reste en elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'Mais les méchants seront retranchés de la terre, et ceux qui agissent perfidement en seront arrachés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Mon fils, ne mets point en oubli mon enseignement, et que ton coeur garde mes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Car ils t’apporteront de longs jours, et des années de vie, et de prospérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Que la gratuité et la vérité ne t’abandonnent point: lie-les à ton cou, et écris-les sur la table de ton coeur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Et tu trouveras la grâce et le bon sens aux yeux de Dieu et des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Confie-toi de tout ton coeur en l’Eternel, et ne t’appuie point sur ta prudence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Considère-le en toutes tes voies, et il dirigera tes sentiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Ne sois point sage à tes yeux; crains l’Eternel, et détourne-toi du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Ce sera une médecine à ton nombril, et une humectation à tes os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Honore l’Eternel de ton bien, et des prémices de tout ton revenu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'Et tes greniers seront remplis d’abondance, et tes cuves rompront de moût.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Mon fils, ne rebute point l’instruction de l’Eternel, et ne te fâche point de ce qu’il te reprend.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Car l’Eternel reprend celui qu’il aime, même comme un père l’enfant auquel il prend plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Ô! que bienheureux est l’homme qui trouve la sagesse, et l’homme qui met en avant l’intelligence!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Car le trafic qu’on peut faire d’elle, est meilleur que le trafic de l’argent; et le revenu qu’on en peut avoir, est meilleur que le fin or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Elle est plus précieuse que les perles, et toutes tes choses désirables ne la valent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Il y a de longs jours en sa main droite, des richesses et de la gloire en sa gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Ses voies sont des voies agréables, et tous ses sentiers ne sont que prospérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Elle est l’arbre de vie à ceux qui l’embrassent; et tous ceux qui la tiennent sont rendus bienheureux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'L’Eternel a fondé la terre par la sapience, et il a disposé les cieux par l’intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Les abîmes se débordent par sa science, et les nuées distillent la rosée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Mon fils, qu’elles ne s’écartent point de devant tes yeux; garde la droite connaissance et la prudence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'Et elles seront la vie de ton âme, et l’ornement de ton cou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Alors tu marcheras en assurance par ta voie, et ton pied ne bronchera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Si tu te couches, tu n’auras point de frayeur, et quand tu te seras couché ton sommeil sera doux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Ne crains point la frayeur subite, ni la ruine des méchants, quand elle arrivera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Car l’Eternel sera ton espérance, et il gardera ton pied d’être pris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Ne retiens pas le bien de ceux à qui il appartient, encore qu’il fût en ta puissance de le faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Ne dis point à ton prochain: Va, et retourne, et je te le donnerai demain, quand tu l’as par-devers toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Ne machine point de mal contre ton prochain; vu qu’il habite en assurance avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'N’aie point de procès sans sujet avec aucun, à moins qu’il ne t’ait fait quelque tort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Ne porte point d’envie à l’homme violent, et ne choisis aucune de ses voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Car celui qui va de travers est en abomination à l’Eternel; mais son secret est avec ceux qui sont justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'La malédiction de l’Eternel est dans la maison du méchant; mais il bénit la demeure des justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Certes il se moque des moqueurs, mais il fait grâce aux débonnaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Les sages hériteront la gloire; mais l’ignominie élève les fous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Enfants, écoutez l’instruction du père, et soyez attentifs à connaître la prudence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Car je vous donne une bonne doctrine, ne laissez donc point mon enseignement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Quand j’ai été fils à mon père, tendre et unique auprès de ma mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'Il m’a enseigné, et m’a dit: Que ton coeur retienne mes paroles; garde mes commandements, et tu vivras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Acquiers la sagesse, acquiers la prudence; n’en oublie rien, et ne te détourne point des paroles de ma bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Ne l’abandonne point, et elle te gardera; aime-la, et elle te conservera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'La principale chose, c’est la sagesse; acquiers la sagesse, et sur toutes tes acquisitions, acquiers la prudence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Estime-la, et elle t’exaltera; elle te glorifiera, quand tu l’auras embrassée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Elle posera des grâces enfilées ensemble sur ta tête, et elle te donnera une couronne d’ornement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Ecoute, mon fils, et reçois mes paroles, et les années de ta vie te seront multipliées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Je t’ai enseigné le chemin de la sagesse, et je t’ai fait marcher par les sentiers de la droiture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Quand tu y marcheras, ta démarche ne sera point serrée; et si tu cours, tu ne broncheras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Embrasse l’instruction, ne la lâche point, garde-la; car c’est ta vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'N’entre point au sentier des méchants, et ne pose point ton pied au chemin des hommes pervers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Détourne-t’en, ne passe point par là, éloigne-t’en, et passe outre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Car ils ne dormiraient pas, s’ils n’avaient fait quelque mal; et le sommeil leur serait ôté, s’ils n’avaient fait tomber quelqu’un.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Parce qu’ils mangent le pain de méchanceté, et qu’ils boivent le vin de la violence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Mais le sentier des justes est comme la lumière resplendissante, qui augmente son éclat jusqu’à ce que le jour soit en sa perfection.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'La voie des méchants est comme l’obscurité; ils ne savent point où ils tomberont.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Mon fils, sois attentif à mes paroles, incline ton oreille à mes discours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Qu’ils ne s’écartent point de tes yeux; garde-les dans ton coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Car ils sont la vie de ceux qui les trouvent, et la santé de tout le corps de chacun d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Garde ton coeur de tout ce dont il faut se garder; car de lui procèdent les sources de la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Eloigne de toi la perversité de la bouche, et la dépravation des lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Que tes yeux regardent droit, et que tes paupières dirigent ton chemin devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Balance le chemin de tes pieds, et que toutes tes voies soient bien dressées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Ne décline ni à droite ni à gauche; détourne ton pied du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Mon fils, sois attentif à ma sagesse, incline ton oreille à mon intelligence;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'Afin que tu gardes mes avis, et que tes lèvres conservent la science.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Car les lèvres de l’étrangère distillent des rayons de miel, et son palais est plus doux que l’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Mais ce qui en provient est amer comme de l’absinthe, et aigu comme une épée à deux tranchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Ses pieds descendent à la mort, ses démarches aboutissent au sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Afin que tu ne balances point le chemin de la vie; ses chemins en sont écartés, tu ne le connaîtras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Maintenant donc, enfants, écoutez-moi, et ne vous détournez point des paroles de ma bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Eloigne ton chemin de la femme étrangère, et n’approche point de l’entrée de sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'De peur que tu ne donnes ton honneur à d’autres, et tes ans au cruel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'De peur que les étrangers ne se rassasient de tes facultés, et que le fruit de ton travail ne soit en la maison du forain;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'Et que tu ne rugisses quand tu seras près de ta fin, quand ta chair et ton corps seront consumés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'Et que tu ne dises: Comment ai-je haï l’instruction, et comment mon coeur a-t-il dédaigné les répréhensions?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Et comment n’ai-je point obéi à la voix de ceux qui m’instruisaient, et n’ai-je point incliné mon oreille à ceux qui m’enseignaient?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Peu s’en est fallu que je n’aie été dans toute sorte de mal, au milieu de la congrégation et de l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Bois des eaux de ta citerne, et des ruisseaux du milieu de ton puits;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Que tes fontaines se répandent dehors, et les ruisseaux d’eau par les rues;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Qu’elles soient à toi seul, et non aux étrangers avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Que ta source soit bénie, et réjouis-toi de la femme de ta jeunesse,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Comme d’une biche aimable, et d’une chevrette gracieuse; que ses mamelles te rassasient en tout temps, et sois continuellement épris de son amour;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Et pourquoi, mon fils, irais-tu errant après l’étrangère, et embrasserais-tu le sein de la foraine?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Vu que les voies de l’homme sont devant les yeux de l’Eternel, et qu’il pèse toutes ses voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Les iniquités du méchant l’attraperont, et il sera retenu par les cordes de son péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Il mourra faute d’instruction, et il ira errant par la grandeur de sa folie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Mon fils, si tu as cautionné pour quelqu’un envers ton ami, ou si tu as frappé dans la main à l’étranger,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'Tu es enlacé par les paroles de ta bouche, tu es pris par les paroles de ta bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Mon fils, fais maintenant ceci, et te dégage, puisque tu es tombé entre les mains de ton intime ami, va, prosterne-toi, et encourage tes amis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Ne donne point de sommeil à tes yeux, et ne laisse point sommeiller tes paupières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Dégage-toi comme le daim de la main du chasseur, et comme l’oiseau de la main de l’oiseleur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Va, paresseux, vers la fourmi, regarde ses voies, et sois sage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Elle n’a ni chef, ni directeur, ni gouverneur,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'Et cependant elle prépare en été son pain, et amasse durant la moisson de quoi manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Paresseux, jusqu’à quand te tiendras-tu couché? Quand te lèveras- tu de ton lit?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Un peu de sommeil, dis-tu, un peu de sommeil, un peu de ploiement de bras, afin de demeurer couché;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'Et ta pauvreté viendra comme un passant; et ta disette, comme un soldat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'L’homme qui imite le démon, est un homme violent et ses discours sont faux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'Il fait signe de ses yeux, il parle de ses pieds, il enseigne de ses doigts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Il y a des renversements dans son coeur, il machine du mal en tout temps, il fait naître des querelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'C’est pourquoi sa calamité viendra subitement, il sera subitement brisé, il n’y aura point de guérison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Dieu hait ces six choses, et même sept lui sont en abomination;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Savoir, les yeux hautains, la fausse langue, les mains qui répandent le sang innocent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'Le coeur qui machine de mauvais desseins; les pieds qui se hâtent pour courir au mal;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'Le faux témoin qui profère des mensonges; et celui qui sème des querelles entre les frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Mon fils, garde le commandement de ton père, et n’abandonne point l’enseignement de ta mère;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Tiens-les continuellement liés à ton coeur, et les attache à ton cou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Quand tu marcheras, il te conduira; et quand tu te coucheras, il te gardera; et quand tu te réveilleras, il s’entretiendra avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Car le commandement est une lampe; et l’enseignement une lumière; et les répréhensions propres à instruire sont le chemin de la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'Pour te garder de la mauvaise femme, et des flatteries de la langue étrangère,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Ne convoite point en ton coeur sa beauté, et ne te laisse point prendre à ses yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Car pour l’amour de la femme débauchée on en vient jusqu’à un morceau de pain, et la femme convoiteuse d’homme chasse après l’âme précieuse de l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Quelqu’un peut-il prendre du feu dans son sein, sans que ses habits brûlent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Quelqu’un marchera-t-il sur la braise, sans que ses pieds en soient brûlés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Ainsi en prend-il à celui qui entre vers la femme de son prochain; quiconque la touchera, ne sera point innocent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'On ne méprise point un larron, s’il dérobe pour remplir son âme, quand il a faim;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Et s’il est trouvé, il le récompensera sept fois au double, il donnera tout ce qu’il a dans sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Mais celui qui commet adultère avec une femme, est dépourvu de sens; et celui qui le fera, sera le destructeur de son âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Il trouvera des plaies et de l’ignominie, et son opprobre ne sera point effacé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Car la jalousie est une fureur de mari, qui n’épargnera point l’adultère au jour de la vengeance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Il n’aura égard à aucune rançon, et il n’acceptera rien, quand tu multiplierais les présents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Mon fils, garde mes paroles, et mets en réserve par-devers toi mes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Garde mes commandements, et tu vivras, et garde mon enseignement comme la prunelle de tes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Lie-les à tes doigts, écris-les sur la table de ton coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Dis à la sagesse: Tu es ma soeur; et appelle la prudence, ta parente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'Afin qu’elles te gardent de la femme étrangère, et de la foraine, qui se sert de paroles flatteuses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Comme je regardais à la fenêtre de ma maison par mes treillis,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'Je vis entre les sots, et je considérai entre les jeunes gens un jeune homme dépourvu de sens,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Qui passait par une rue, près du coin d’une certaine femme, et qui tenait le chemin de sa maison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'Sur le soir à la fin du jour, lorsque la nuit devenait noire et obscure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Et voici, une femme vint au-devant de lui, parée en femme de mauvaise vie, et pleine de ruse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Bruyante et débauchée, et dont les pieds ne demeurent point dans sa maison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Etant tantôt dehors, et tantôt dans les rues, et se tenant aux aguets à chaque coin de rue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Elle le prit, et le baisa; et avec un visage effronté, lui dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'J’ai chez moi des sacrifices de prospérité; j’ai aujourd’hui payé mes voeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'C’est pourquoi je suis sortie au-devant de toi, pour te chercher soigneusement, et je t’ai trouvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'J’ai garni mon lit d’un tour de réseau, entrecoupé de fil d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Je l’ai parfumé de myrrhe, d’aloès et de cinnamome.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Viens, enivrons-nous de plaisir jusqu’au matin, réjouissons-nous en amours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Car mon mari n’est point en sa maison; il s’en est allé en voyage bien loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Il a pris avec soi un sac d’argent; il retournera en sa maison au jour assigné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Elle l’a fait détourner par beaucoup de douces paroles, et l’a attiré par la flatterie de ses lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Il s’en est aussitôt allé après elle, comme le boeuf s’en va à la boucherie, et comme le fou, aux ceps pour être châtié;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'Jusqu’à ce que la flèche lui ait transpercé le foie; comme l’oiseau qui se hâte vers le filet, ne sachant point qu’on l’a tendu contre sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Maintenant donc, enfants, écoutez-moi, et soyez attentifs à mes discours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Que ton coeur ne se détourne point vers les voies de cette femme, et qu’elle ne te fasse point égarer dans ses sentiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Car elle a fait tomber plusieurs blessés à mort, et tous ceux qu’elle a tués étaient forts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Sa maison sont les voies du sépulcre, qui descendent aux cabinets de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'La Sapience ne crie-t-elle pas? et l’Intelligence ne fait-elle pas ouïr sa voix?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Elle s’est présentée sur le sommet des lieux élevés; sur le chemin, aux carrefours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Elle crie à la place des portes; à l’entrée de la ville; à l’avenue des portes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'Ô vous! hommes de qualité, je vous appelle; et ma voix s’adresse aussi aux gens du commun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Vous simples, entendez ce que c’est que du discernement, et vous tous, devenez intelligents de coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Ecoutez, car je dirai des choses importantes: et l’ouverture de mes lèvres sera de choses droites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Parce que mon palais parlera de la vérité, et que mes lèvres ont en abomination la méchanceté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Tous les discours de ma bouche sont avec justice, il n’y a rien en eux de contraint, ni de mauvais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Ils sont tous aisés à trouver à l’homme intelligent, et droits à ceux qui ont trouvé la science.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Recevez mon instruction, et non pas de l’argent; et la science, plutôt que du fin or choisi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Car la sagesse est meilleure que les perles; et tout ce qu’on saurait souhaiter, ne la vaut pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Moi la Sapience je demeure avec la discrétion, et je trouve la science de prudence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'La crainte de l’Eternel c’est de haïr le mal. J’ai en haine l’orgueil et l’arrogance, la voie de méchanceté, la bouche hypocrite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'A moi appartient le conseil et l’adresse; je suis la prudence, à moi appartient la force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Par moi règnent les Rois, et par moi les Princes décernent la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Par moi dominent les Seigneurs, et les Princes, et tous les juges de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'J’aime ceux qui m’aiment; et ceux qui me cherchent soigneusement, me trouveront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Avec moi sont les richesses et la gloire, les biens permanents, et la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Mon fruit est meilleur que le fin or, même que l’or raffiné; et mon revenu est meilleur que l’argent choisi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Je fais marcher par le chemin de la justice, et par le milieu des sentiers de la droiture;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'Afin que je fasse hériter des biens permanents à ceux qui m’aiment, et que je remplisse leurs trésors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'L’Eternel m’a possédée dès le commencement de sa voie, même avant qu’il fît aucune de ses oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'J’ai été déclarée Princesse dès le siècle, dès le commencement, dès l’ancienneté de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'J’ai été engendrée lorsqu’il n’y avait point encore d’abîmes, ni de fontaines chargées d’eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'J’ai été engendrée avant que les montagnes fussent posées, et avant les coteaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Lorsqu’il n’avait point encore fait la terre, ni les campagnes, ni le plus beau des terres du monde habitable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Quand il disposait les cieux; quand il traçait le cercle au- dessus des abîmes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'Quand il affermissait les nuées d’en haut; quand il serrait ferme les fontaines des abîmes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'Quand il mettait son ordonnance touchant la mer, afin que les eaux ne passassent point ses bords; quand il compassait les fondements de la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'J’étais alors par-devers lui son nourrisson, j’étais ses délices de tous les jours, et toujours j’étais en joie en sa présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Je me réjouissais en la partie habitable de sa terre, et mes plaisirs étaient avec les enfants des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Maintenant donc, enfants, écoutez-moi; car bienheureux seront ceux qui garderont mes voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Ecoutez l’instruction, et soyez sages, et ne la rejetez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Ô! que bienheureux est l’homme qui m’écoute, ne bougeant de mes portes tous les jours, et gardant les poteaux de mes portes!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Car celui qui me trouve, trouve la vie, et attire la faveur de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Mais celui qui m’offense, fait tort à son âme; tous ceux qui me haïssent, aiment la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'La Souveraine Sapience a bâti sa maison, elle a taillé ses sept colonnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Elle a apprêté sa viande, elle a mixtionné son vin; elle a aussi dressé sa table.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Elle a envoyé ses servantes; et elle appelle de dessus les créneaux des lieux les plus élevés de la ville, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'Qui est celui qui est simple? qu’il se retire ici; et elle dit à celui qui est dépourvu de sens:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'Venez, mangez de mon pain, et buvez du vin que j’ai mixtionné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Laissez la sottise, et vous vivrez; et marchez droit par la voie de la prudence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Celui qui instruit le moqueur, en reçoit de l’ignominie; et celui qui reprend le méchant, en reçoit une tache.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Ne reprends point le moqueur, de peur qu’il ne te haïsse; reprends le sage, et il t’aimera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Donne instruction au sage, et il deviendra encore plus sage; enseigne le juste, et il croîtra en science.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Le commencement de la sagesse est la crainte de l’Eternel; et la science des saints, c’est la prudence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Car tes jours seront multipliés par moi, et des années de vie te seront ajoutées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Si tu es sage, tu seras sage pour toi-même; mais si tu es moqueur, tu en porteras seul la peine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'La femme folle est bruyante; ce n’est que sottise, et elle ne connaît rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Et elle s’assied à la porte de sa maison sur un siège, dans les lieux élevés de la ville;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'Pour appeler les passants qui vont droit leur chemin, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'Qui est celui qui est simple? qu’il se retire ici; et elle dit à celui qui est dépourvu de sens:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, 'Les eaux dérobées sont douces, et le pain pris en secret est agréable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Et il ne connaît point que là sont les trépassés, et que ceux qu’elle a conviés sont au fond du sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Proverbes de Salomon. L’enfant sage réjouit son père, mais l’enfant insensé est l’ennui de sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Les trésors de méchanceté ne profiteront de rien; mais la justice garantira de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'L’Eternel n’affamera point l’âme du juste; mais la malice des méchants les pousse au loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'La main paresseuse fait devenir pauvre; mais la main des diligents enrichit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'L’enfant prudent amasse en été; mais celui qui dort durant la moisson, est un enfant qui fait honte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Les bénédictions seront sur la tête du juste; mais la violence couvrira la bouche des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'La mémoire du juste sera en bénédiction; mais la réputation des méchants sera flétrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Le sage de coeur recevra les commandements; mais le fou de lèvres tombera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Celui qui marche dans l’intégrité, marche en assurance; mais celui qui pervertit ses voies, sera connu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Celui qui fait signe de l’oeil, donne de la peine; et le fou de lèvres sera renversé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'La bouche du juste est une source de vie; mais l’extorsion couvrira la bouche des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'La haine excite les querelles; mais la charité couvre tous les forfaits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'La sagesse se trouve sur les lèvres de l’homme intelligent; mais la verge est pour le dos de celui qui est dépourvu de sens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Les sages mettent en réserve la science; mais la bouche du fou est une ruine prochaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Les biens du riche sont la ville de sa force; mais la pauvreté des misérables est leur ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'L’oeuvre du juste tend à la vie; mais le rapport du méchant tend au péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Celui qui garde l’instruction, tient le chemin qui tend à la vie; mais celui qui néglige la correction, se fourvoie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Celui qui couvre la haine, use de fausses lèvres; et celui qui met en avant des choses diffamatoires, est fou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'La multitude des paroles n’est pas exempte de péché; mais celui qui retient ses lèvres, est prudent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'La langue du juste est un argent choisi; mais le coeur des méchants est bien peu de chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Les lèvres du juste en instruisent plusieurs; mais les fous mourront faute de sens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'La bénédiction de l’Eternel est celle qui enrichit, et l’Eternel n’y ajoute aucun travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'C’est comme un jeu au fou de faire quelque méchanceté; mais la sagesse est de l’homme intelligent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Ce que le méchant craint, lui arrivera; mais Dieu accordera aux justes ce qu’ils désirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Comme le tourbillon passe, ainsi le méchant n’est plus; mais le juste est un fondement perpétuel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Ce qu’est le vinaigre aux dents, et la fumée aux yeux; tel est le paresseux à ceux qui l’envoient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'La crainte de l’Eternel accroît le nombre des jours; mais les ans des méchants seront retranchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'L’espérance des justes n’est que joie; mais l’attente des méchants périra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'La voie de l’Eternel est la force de l’homme intègre; mais elle est la ruine des ouvriers d’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Le juste ne sera jamais ébranlé; mais les méchants n’habiteront point en la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'La bouche du juste produira la sagesse; mais la langue hypocrite sera retranchée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Les lèvres du juste connaissent ce qui est agréable; mais la bouche des méchants n’est que renversements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'La fausse balance est une abomination à l’Eternel; mais le poids juste lui plaît.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'L’orgueil est-il venu? aussi est venue l’ignominie; mais la sagesse est avec ceux qui sont modestes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'L’intégrité des hommes droits les conduit; mais la perversité des perfides les détruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Les richesses ne serviront de rien au jour de l’indignation; mais la justice garantira de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'La justice de l’homme intègre dresse sa voie; mais le méchant tombera par sa méchanceté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'La justice des hommes droits les délivrera; mais les perfides seront pris dans leur méchanceté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Quand l’homme méchant meurt, son attente périt; et l’espérance des hommes violents périra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Le juste est délivré de la détresse; mais le méchant entre en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Celui qui se contrefait de sa bouche corrompt son prochain; mais les justes en sont délivrés par la science.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'La ville s’égaye du bien des justes, et il y a chant de triomphe quand les méchants périssent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'La ville est élevée par la bénédiction des hommes droits, mais elle est renversée par la bouche des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Celui qui méprise son prochain, est dépourvu de sens; mais l’homme prudent se tait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Celui qui va rapportant, révèle le secret; mais celui qui est de coeur fidèle, cèle la chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Le peuple tombe par faute de prudence, mais la délivrance est dans la multitude de gens de conseil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Celui qui cautionne pour un étranger, ne peut manquer d’avoir du mal, mais celui qui hait ceux qui frappent en la main, est assuré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'La femme gracieuse obtient de l’honneur, et les hommes robustes obtiennent les richesses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'L’homme doux fait du bien à soi-même; mais le cruel trouble sa chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Le méchant fait une oeuvre qui le trompe; mais la récompense est assurée à celui qui sème la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Ainsi la justice tend à la vie, et celui qui poursuit le mal tend à sa mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Ceux qui sont dépravés de coeur, sont en abomination à l’Eternel; mais ceux qui sont intègres dans leurs voies, lui sont agréables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'De main en main le méchant ne demeurera point impuni; mais la race des justes sera délivrée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Une belle femme se détournant de la raison, est comme une bague d’or au museau d’une truie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Le souhait des justes n’est que bien; mais l’attente des méchants n’est qu’indignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Tel répand, qui sera augmenté davantage; et tel resserre outre mesure, qui n’en aura que disette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'La personne qui bénit, sera engraissée; et celui qui arrose abondamment, regorgera lui-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Le peuple maudira celui qui retient le froment; mais la bénédiction sera sur la tête de celui qui le débite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Celui qui procure soigneusement le bien, acquiert de la faveur; mais le mal arrivera à celui qui le recherche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Celui qui se fie en ses richesses, tombera; mais les justes reverdiront comme la feuille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Celui qui ne gouverne pas sa maison par ordre, aura le vent pour héritage; et le fou sera serviteur du sage de coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Le fruit du juste est un arbre de vie; et celui qui gagne les âmes est sage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Voici, le juste reçoit en la terre sa rétribution, combien plus le méchant et le pécheur la recevront-ils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Celui qui aime l’instruction, aime la science; mais celui qui hait d’être repris, est un stupide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'L’homme de bien attire la faveur de l’Eternel; mais l’Eternel condamnera l’homme qui machine du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'L’homme ne sera point affermi par la méchanceté; mais la racine des justes ne sera point ébranlée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'La femme vaillante est la couronne de son mari; mais celle qui fait honte, est comme de la vermoulure à ses os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Les pensées des justes ne sont que jugement; mais les conseils des méchants ne sont que fraude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Les paroles des méchants ne tendent qu’à dresser des embûches pour répandre le sang; mais la bouche des hommes droits les délivrera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Les méchants sont renversés, et ils ne sont plus; mais la maison des justes se maintiendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'L’homme est loué selon sa prudence; mais le coeur dépravé sera en mépris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Mieux vaut l’homme qui ne fait point cas de soi-même, bien qu’il ait des serviteurs, que celui qui se glorifie, et qui a faute de pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Le juste a égard à la vie de sa bête; mais les compassions des méchants sont cruelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Celui qui laboure sa terre, sera rassasié de pain; mais celui qui suit les fainéants, est dépourvu de sens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Ce que le méchant désire, est un rets de maux; mais la racine des justes donnera son fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Il y a un lacet de mal dans le forfait des lèvres; mais le juste sortira de la détresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'L’homme sera rassasié de biens par le fruit de sa bouche; et on rendra à l’homme la rétribution de ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'La voie du fou est droite à son opinion; mais celui qui écoute le conseil, est sage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Quant au fou, son dépit se connaît le même jour; mais l’homme bien avisé couvre son ignominie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Celui qui prononce des choses véritables, fait rapport de ce qui est juste; mais le faux témoin fait des rapports trompeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Il y a tel qui profère comme des pointes d’épée; mais la langue des sages est santé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'La parole véritable est ferme à perpétuité; mais la fausse langue n’est que pour un moment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Il y aura tromperie dans le coeur de ceux qui machinent du mal; mais il y aura de la joie pour ceux qui conseillent la paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'On ne fera point qu’aucun outrage rencontre le juste; mais les méchants seront remplis de mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Les fausses lèvres sont une abomination à l’Eternel; mais ceux qui agissent fidèlement, lui sont agréables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'L’homme bien avisé cèle la science; mais le coeur des fous publie la folie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'La main des diligents dominera; mais la main paresseuse sera tributaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Le chagrin qui est au coeur de l’homme, l’accable; mais la bonne parole le réjouit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Le juste a plus de reste que son voisin; mais la voie des méchants les fera fourvoyer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Le paresseux ne rôtit point sa chasse; mais les biens précieux de l’homme sont au diligent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'La vie est dans le chemin de la justice, et la voie de son sentier ne tend point à la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'L’enfant sage écoute l’instruction de son père, mais le moqueur n’écoute point la répréhension.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'L’homme mangera du bien par le fruit de sa bouche; mais l’âme de ceux qui agissent perfidement, mangera l’extorsion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Celui qui garde sa bouche, garde son âme; mais celui qui ouvre à tout propos ses lèvres, tombera en ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'L’âme du paresseux ne fait que souhaiter, et il n’a rien; mais l’âme des diligents sera engraissée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Le juste hait la parole de mensonge, mais elle met le méchant en mauvaise odeur, et le fait tomber dans la confusion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'La justice garde celui qui est intègre dans sa voie, mais la méchanceté renversera celui qui s’égare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Tel fait du riche, qui n’a rien du tout; et tel fait du pauvre, qui a de grandes richesses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Les richesses font que l’homme est rançonné; mais le pauvre n’entend point de menaces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'La lumière des justes sera gaie; mais la lampe des méchants sera éteinte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'L’orgueil ne produit que querelle; mais la sagesse est avec ceux qui prennent conseil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Les richesses provenues de vanité seront diminuées; mais celui qui amasse avec la main, les multipliera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'L’espoir différé fait languir le coeur; mais le souhait qui arrive, est comme l’arbre de vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Celui qui méprise la parole, périra à cause d’elle; mais celui qui craint le commandement, en aura la récompense.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'L’enseignement du sage est une source de vie pour se détourner des filets de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Le bon entendement donne de la grâce; mais la voie de ceux qui agissent perfidement, est raboteuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Tout homme bien avisé agira avec connaissance; mais le fou répandra sa folie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Le méchant messager tombe dans le mal; mais l’ambassadeur fidèle est santé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'La pauvreté et l’ignominie arriveront à celui qui rejette l’instruction; mais celui qui garde la répréhension, sera honoré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Le souhait accompli est une chose douce à l’âme; mais se détourner du mal, est une abomination aux fous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Celui qui converse avec les sages, deviendra sage; mais le compagnon des fous sera accablé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Le mal poursuit les pécheurs; mais le bien sera rendu aux justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'L’homme de bien laissera de quoi hériter aux enfants de ses enfants; mais les richesses du pécheur sont réservées aux justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Il y a beaucoup à manger dans les terres défrichées des pauvres; mais il y a tel qui est consumé par faute de règle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Celui qui épargne sa verge, hait son fils; mais celui qui l’aime, se hâte de le châtier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Le juste mangera jusqu’à être rassasié à son souhait; mais le ventre des méchants aura disette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Toute femme sage bâtit sa maison; mais la folle la ruine de ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Celui qui marche en sa droiture, révère l’Eternel; mais celui qui va de travers en ses voies, le méprise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'La verge d’orgueil est dans la bouche du fou; mais les lèvres des sages les garderont.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Où il n’y a point de boeuf, la grange est vide; et l’abondance du revenu provient de la force du boeuf.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Le témoin véritable ne mentira jamais; mais le faux témoin avance volontiers des mensonges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Le moqueur cherche la sagesse, et ne la trouve point; mais la science est aisée à trouver à l’homme intelligent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Eloigne-toi de l’homme insensé, puisque tu ne lui as point connu de lèvres de science.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'La sagesse de l’homme bien avisé est d’entendre sa voie; mais la folie des fous n’est que tromperie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Les fous pallient le délit; mais il n’y a que plaisir entre les hommes droits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Le coeur d’un chacun connaît l’amertume de son âme; et un autre n’est point mêlé dans sa joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'La maison des méchants sera abolie; mais le tabernacle des hommes droits fleurira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Il y a telle voie qui semble droite à l’homme, mais dont l’issue sont les voies de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Même en riant le coeur sera triste, et la joie finit par l’ennui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Celui qui a un coeur hypocrite, sera rassasié de ses voies; mais l’homme de bien le sera de ce qui est en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Le simple croit à toute parole; mais l’homme bien avisé considère ses pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Le sage craint, et se retire du mal; mais le fou se met en colère, et se tient assuré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'L’homme colère fait des folies; et l’homme rusé est haï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Les niais hériteront la folie; mais les bien-avisés seront couronnés de science.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Les malins seront humiliés devant les bons, et les méchants, devant les portes du juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Le pauvre est haï, même de son ami; mais les amis du riche sont en grand nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Celui qui méprise son prochain s’égare; mais celui qui a pitié des débonnaires, est bienheureux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Ceux qui machinent du mal ne se fourvoient-ils pas? Mais la bonté et la vérité seront pour ceux qui procurent le bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'En tout travail il y a quelque profit, mais le babil des lèvres ne tourne qu’à disette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Les richesses des sages leur sont comme une couronne; mais la folie des fous n’est que folie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Le témoin véritable délivre les âmes; mais celui qui prononce des mensonges, n’est que tromperie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'En la crainte de l’Eternel il y a une ferme assurance, et une retraite pour ses enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'La crainte de l’Eternel est une source de vie pour se détourner des filets de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'La puissance d’un Roi consiste dans la multitude du peuple; mais quand le peuple diminue, c’est l’abaissement du Prince.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Celui qui est lent à la colère, est de grande intelligence; mais celui qui est prompt à se courroucer, excite la folie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Le coeur doux est la vie de la chair; mais l’envie est la vermoulure des os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Celui qui fait tort au pauvre, déshonore celui qui l’a fait; mais celui-là l’honore, qui a pitié du nécessiteux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Le méchant sera poussé au loin par sa malice; mais le juste trouve retraite même en sa mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'La sagesse repose au coeur de l’homme intelligent; et elle est même reconnue au milieu des fous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'La justice élève une nation; mais le péché est l’opprobre des peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Le Roi prend plaisir au serviteur prudent; mais son indignation sera contre celui qui lui fait déshonneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'La réponse douce apaise la fureur; mais la parole fâcheuse excite la colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'La langue des sages embellit la science; mais la bouche des fous profère la folie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Les yeux de l’Eternel sont en tous lieux, contemplant les méchants et les bons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'La langue qui corrige le prochain, est comme l’arbre de vie; mais celle où il y a de la perversité, est un rompement d’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Le fou méprise l’instruction de son père; mais celui qui prend garde à la répréhension, deviendra bien-avisé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Il y a un grand trésor dans la maison du juste; mais il y a du trouble dans le revenu du méchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Les lèvres des sages répandent partout la science; mais le coeur des fous ne fait pas ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Le sacrifice des méchants est en abomination à l’Eternel; mais la requête des hommes droits lui est agréable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'La voie du méchant est en abomination à l’Eternel; mais il aime celui qui s’adonne soigneusement à la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Le châtiment est fâcheux à celui qui quitte le droit chemin; mais celui qui hait d’être repris, mourra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Le sépulcre et le gouffre sont devant l’Eternel; combien plus les coeurs des enfants des hommes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Le moqueur n’aime point qu’on le reprenne, et il n’ira jamais vers les sages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Le coeur joyeux rend la face belle, mais l’esprit est abattu par l’ennui du coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Le coeur de l’homme prudent cherche la science; mais la bouche des fous se repaît de folie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Tous les jours de l’affligé sont mauvais; mais quand on a le coeur gai, c’est un banquet perpétuel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Un peu de bien vaut mieux avec la crainte de l’Eternel, qu’un grand trésor avec lequel il y a du trouble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Mieux vaut un repas d’herbes, où il y a de l’amitié, qu’un repas de boeuf bien gras, où il y a de la haine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'L’homme furieux excite la querelle; mais l’homme tardif à colère apaise la dispute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'La voie du paresseux est comme une haie de ronces; mais le chemin des hommes droits est relevé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'L’enfant sage réjouit le père; mais l’homme insensé méprise sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'La folie est la joie de celui qui est dépourvu de sens; mais l’homme prudent dresse ses pas pour marcher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Les résolutions deviennent inutiles où il n’y a point de conseil; mais il y a de la fermeté dans la multitude des conseillers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'L’homme a de la joie dans les réponses de sa bouche; et la parole dite en son temps combien est-elle bonne?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Le chemin de la vie tend en haut pour l’homme prudent, afin qu’il se retire du sépulcre qui est en bas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'L’Eternel démolit la maison des orgueilleux, mais il établit la borne de la veuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Les pensées du malin sont en abomination à l’Eternel; mais celles de ceux qui sont purs, sont des paroles agréables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Celui qui est entièrement adonné au gain déshonnête, trouble sa maison; mais celui qui hait les dons, vivra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Le coeur du juste médite ce qu’il doit répondre; mais la bouche des méchants profère des choses mauvaises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'L’Eternel est loin des méchants; mais il exauce la requête des justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'La clarté des yeux réjouit le coeur; et la bonne renommée engraisse les os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'L’oreille qui écoute la répréhension de vie, logera parmi les sages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Celui qui rejette l’instruction a en dédain son âme; mais celui qui écoute la répréhension, s’acquiert du sens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'La crainte de l’Eternel est une instruction de sagesse, et l’humilité va devant la gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Les préparations du coeur sont à l’homme; mais le discours de la langue est de par l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Chacune des voies de l’homme lui semble pure; mais l’Eternel pèse les esprits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Remets tes affaires à l’Eternel, et tes pensées seront bien ordonnées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'L’Eternel a fait tout pour soi-même; et même le méchant pour le jour de la calamité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'L’Eternel a en abomination tout homme hautain de coeur; de main en main il ne demeurera point impuni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Il y aura propitiation pour l’iniquité par la miséricorde et la vérité; et on se détourne du mal par la crainte de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Quand l’Eternel prend plaisir aux voies de l’homme, il apaise envers lui ses ennemis mêmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Il vaut mieux un peu de bien avec justice, qu’un gros revenu là où l’on n’a point de droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Le coeur de l’homme délibère de sa voie; mais l’Eternel conduit ses pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Il y a divination aux lèvres du Roi, et sa bouche ne se fourvoiera point du droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'La balance et le trébuchet justes sont de l’Eternel, et tous les poids du sachet sont son oeuvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Ce doit être une abomination aux Rois de faire injustice, parce que le trône est établi par la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Les Rois doivent prendre plaisir aux lèvres de justice, et aimer celui qui profère des choses justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Ce sont autant de messagers de mort que la colère du Roi; mais l’homme sage l’apaisera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'C’est vie que le visage serein du Roi, et sa faveur est comme la nuée portant la pluie de la dernière saison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Combien est-il plus précieux que le fin or, d’acquérir de la sagesse; et combien est-il plus excellent que l’argent, d’acquérir de la prudence?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Le chemin relevé des hommes droits, c’est de se détourner du mal; celui-là garde son âme qui prend garde à son train.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'L’orgueil va devant l’écrasement; et la fierté d’esprit devant la ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Mieux vaut être humilié d’esprit avec les débonnaires, que de partager le butin avec les orgueilleux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Celui qui prend garde à la parole, trouvera le bien; et celui qui se confie en l’Eternel, est bienheureux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'On appellera prudent le sage de coeur; et la douceur des lèvres augmente la doctrine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'La prudence est à ceux qui la possèdent une source de vie; mais l’instruction des fous est une folie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Le coeur sage conduit prudemment sa bouche, et ajoute doctrine sur ses lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Les paroles agréables sont des rayons de miel, douceur à l’âme, et santé aux os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'II y a telle voie qui semble droite à l’homme, mais dont la fin sont les voies de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'L’âme de celui qui travaille, travaille pour lui-même, parce que sa bouche se courbe devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Le méchant creuse le mal, et il y a comme un feu brûlant sur ses lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'L’homme qui use de renversements, sème des querelles, et le rapporteur met le plus grand ami en division.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'L’homme violent attire son compagnon, et le fait marcher par une voie qui n’est pas bonne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Il fait signe des yeux pour machiner des renversements, et remuant ses lèvres il exécute le mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Les cheveux blancs sont une couronne d’honneur; et elle se trouvera dans la voie de la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Celui qui est tardif à colère, vaut mieux que l’homme fort; et celui qui est le maître de son coeur, vaut mieux que celui qui prend des villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'On jette le sort au giron, mais tout ce qui en doit arriver, est de par l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Mieux vaut un morceau de pain sec là où il y a la paix, qu’une maison pleine de viandes apprêtées, là où il y a des querelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Le serviteur prudent sera maître sur l’enfant qui fait honte, et il partagera l’héritage entre les frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Le fourneau est pour éprouver l’argent, et le creuset, l’or; mais l’Eternel éprouve les coeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Le malin est attentif à la lèvre trompeuse, et le menteur écoute la mauvaise langue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Celui qui se moque du pauvre, déshonore celui qui a fait le pauvre; et celui qui se réjouit de la calamité, ne demeurera point impuni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Les enfants des enfants sont la couronne des vieilles gens, et l’honneur des enfants ce sont leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'La parole grave ne convient point à un fou; combien moins la parole de mensonge aux principaux d’entre le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Le présent est comme une pierre précieuse aux yeux de ceux qui y sont adonnés; de quelque côté qu’il se tourne, il réussit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Celui qui cache le forfait, cherche l’amitié; mais celui qui rapporte la chose, met le plus grand ami en division.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'La répréhension se fait mieux sentir à l’homme prudent, que cent coups au fou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Le malin ne cherche que rébellion, mais le messager cruel sera envoyé contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Que l’homme rencontre plutôt une ourse qui a perdu ses petits, qu’un fou dans sa folie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Le mal ne partira point de la maison de celui qui rend le mal pour le bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Le commencement d’une querelle est comme quand on lâche l’eau; mais avant qu’on vienne à la mêlée, retire-toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Celui qui déclare juste le méchant, et celui qui déclare méchant le juste, sont tous deux en abomination à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Que sert le prix dans la main du fou pour acheter la sagesse, vu qu’il n’a point de sens?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'L’intime ami aime en tout temps, et il naîtra comme un frère dans la détresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Celui-là est dépourvu de sens qui touche à la main, et qui se rend caution envers son ami.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Celui qui aime les querelles, aime le forfait; celui qui hausse son portail, cherche sa ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Celui qui est pervers de coeur, ne trouvera point le bien; et l’hypocrite tombera dans la calamité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Celui qui engendre un fou, en aura de l’ennui, et le père du fou ne se réjouira point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Le coeur joyeux vaut une médecine; mais l’esprit abattu dessèche les os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Le méchant prend le présent du sein, pour pervertir les voies de jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'La sagesse est en la présence de l’homme prudent; mais les yeux du fou sont au bout de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'L’enfant insensé est l’ennui de son père, et l’amertume de celle qui l’a enfanté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Il n’est pas juste de condamner l’innocent à l’amende, ni que les principaux d’entre le peuple frappent quelqu’un pour avoir agi avec droiture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'L’homme retenu dans ses paroles sait ce que c’est que de la science, et l’homme qui est d’un esprit froid, est un homme intelligent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Même le fou, quand il se tait, est réputé sage; et celui qui serre ses lèvres, est réputé entendu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'L’homme particulier cherche ce qui lui fait plaisir, et se mêle de savoir comment tout doit aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Le fou ne prend point plaisir à l’intelligence, mais à ce que son coeur soit manifesté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Quand le méchant vient, le mépris vient aussi, et le reproche avec l’ignominie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Les paroles de la bouche d’un digne personnage sont comme des eaux profondes; et la source de la sagesse est un torrent qui bouillonne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Il n’est pas bon d’avoir égard à l’apparence de la personne du méchant, pour renverser le juste en jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Les lèvres du fou entrent en querelle, et sa bouche appelle les combats.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'La bouche du fou lui est une ruine, et ses lèvres sont un piège à son âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Les paroles du flatteur sont comme de ceux qui ne font pas semblant d’y toucher, mais elles descendent jusqu’au dedans du ventre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Celui aussi qui se porte lâchement dans son ouvrage, est frère de celui qui dissipe ce qu’il a.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Le nom de l’Eternel est une forte tour, le juste y courra, et il y sera en une haute retraite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Les biens du riche sont la ville de sa force, et comme une haute muraille de retraite, selon son imagination.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Le coeur de l’homme s’élève avant que la ruine arrive; mais l’humilité précède la gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Celui qui répond à quelque propos avant que de l’ avoir ouï, c’est à lui une folie et une confusion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'L’esprit d’un homme fort soutiendra son infirmité; mais l’esprit abattu, qui le relèvera?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Le coeur de l’homme intelligent acquiert de la science, et l’oreille des sages cherche la science.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Le présent d’un homme lui fait faire place, et le conduit devant les grands.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Celui qui plaide le premier, est juste; mais sa partie vient, et examine le tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Le sort fait cesser les procès, et fait les partages entre les puissants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Un frère offensé se rend plus difficile qu’une ville forte, et les discordes en sont comme les verrous d’un palais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Le ventre de chacun sera rassasié du fruit de sa bouche; il sera rassasié du revenu de ses lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'La mort et la vie sont au pouvoir de la langue, et celui qui l’aime mangera de ses fruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Celui qui trouve une digne femme trouve le bien, et il a obtenu une faveur de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Le pauvre ne prononce que des supplications, mais le riche ne répond que des paroles rudes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Que l’homme qui a des intimes amis, se tienne à leur amitié; parce qu’il y a tel ami qui est plus attaché que le frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Le pauvre qui marche dans son intégrité, vaut mieux que celui qui pervertit ses lèvres, et qui est fou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'La vie même sans science n’est pas une chose bonne; et celui qui se hâte des pieds, s’égare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'La folie de l’homme renversera son intention, et son coeur se dépitera contre l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Les richesses assemblent beaucoup d’amis; mais celui qui est pauvre, est abandonné de son ami.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Le faux témoin ne demeurera point impuni; et celui qui profère des mensonges, n’échappera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Plusieurs supplient celui qui est en état de faire du bien, et chacun est ami d’un homme qui donne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Tous les frères du pauvre le haïssent; combien plus ses amis se retireront-ils de lui? Poursuit-il? il n’y a que des paroles pour lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Celui qui acquiert du sens, aime son âme; et celui qui prend garde à l’intelligence, c’est pour trouver le bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Le faux témoin ne demeurera point impuni; et celui qui profère des mensonges, périra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'L’aise ne sied pas bien à un fou; combien moins sied-il à un esclave, de dominer sur les personnes de distinction?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'La prudence de l’homme retient sa colère; c’est un honneur pour lui de passer par-dessus le tort qu’on lui fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'L’indignation du Roi est comme le rugissement d’un jeune lion; mais sa faveur est comme la rosée sur l’herbe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'L’enfant insensé est un grand malheur à son père, et les querelles de la femme sont une gouttière continuelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'La maison et les richesses sont l’héritage des pères; mais la femme prudente est de par l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'La paresse fait venir le sommeil, et l’âme négligente aura faim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Celui qui garde le commandement, garde son âme; mais celui qui méprise ses voies, mourra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Celui qui a pitié du pauvre, prête à l’Eternel, et il lui rendra son bienfait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Châtie ton enfant tandis qu’il y a de l’espérance, et ne va point jusqu’à le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Celui qui est de grande furie en porte la peine; et si tu l’en retires, tu y en ajouteras davantage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Ecoute le conseil, et reçois l’instruction, afin que tu deviennes sage en ton dernier temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Il y a plusieurs pensées au coeur de l’homme, mais le conseil de l’Eternel est permanent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Ce que l’homme doit désirer, c’est d’user de miséricorde; et le pauvre vaut mieux que l’homme menteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'La crainte de l’Eternel conduit à la vie, et celui qui l’a, passera la nuit étant rassasié, sans qu’il soit visité d’aucun mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Le paresseux cache sa main dans le sein, et il ne daigne même pas la ramener à sa bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Si tu bats le moqueur, le niais en deviendra avisé; et si tu reprends l’homme intelligent, il entendra ce qu’il faut savoir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'L’enfant qui fait honte et confusion, détruit le père, et chasse la mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Mon fils, cesse d’ouïr ce qui te pourrait apprendre à te fourvoyer des paroles de la science.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Le témoin qui a un mauvais coeur se moque de la justice; et la bouche des méchants engloutit l’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Les jugements sont préparés pour les moqueurs, et les grands coups pour le dos des fous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Le vin est moqueur, et la cervoise est mutine; et quiconque y excède, n’est pas sage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'La terreur du Roi est comme le rugissement d’un jeune lion; celui qui se met en colère contre lui, pèche contre soi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'C’est une gloire à l’homme de s’abstenir de procès; mais chaque insensé s’en mêle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Le paresseux ne labourera point à cause du mauvais temps, mais il mendiera durant la moisson, et il n’aura rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Le conseil dans le coeur d’un digne personnage est comme des eaux profondes, et l’homme intelligent l’y puisera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'La plupart des hommes prêchent leur bonté; mais qui est-ce qui trouvera un homme véritable?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Ô! que les enfants du juste qui marchent dans son intégrité, seront heureux après lui!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Le Roi séant sur le trône de justice dissipe tout mal par son regard.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Qui est-ce qui peut dire: J’ai purifié mon coeur; je suis net de mon péché?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Le double poids et la double mesure sont tous deux en abomination à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Un jeune enfant même fait connaître par ses actions si son oeuvre sera pure, et si elle sera droite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Et l’oreille qui entend, et l’oeil qui voit, l’Eternel les a faits tous les deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'N’aime point le sommeil, de peur que tu ne deviennes pauvre; ouvre tes yeux, et tu auras suffisamment de pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'Il est mauvais, il est mauvais, dit l’acheteur; puis il s’en va, et se vante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Il y a de l’or, et beaucoup de perles; mais les lèvres qui prononcent la science sont un vase précieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Quand quelqu’un aura cautionné pour l’étranger, prends son vêtement, et prends gage de lui pour l’étrangère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Le pain volé est doux à l’homme; mais ensuite sa bouche sera remplie de gravier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Chaque pensée s’affermit par le conseil; fais donc la guerre avec prudence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Celui qui révèle le secret va médisant; ne te mêle donc point avec celui qui séduit par ses lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'La lampe de celui qui maudit son père, ou sa mère, sera éteinte dans les ténèbres les plus noires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'L’héritage pour lequel on s’est trop hâté du commencement, ne sera point béni sur la fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Ne dis point: je rendrai le mal; mais attends l’Eternel, et il te délivrera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Le double poids est en abomination à l’Eternel, et la fausse balance n’ est pas bonne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Les pas de l’homme sont de par l’Eternel, comment donc l’homme entendra-t-il sa voie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'C’est un piège à l’homme d’engloutir la chose sainte, et de chercher à s’emparer des choses vouées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Le sage Roi dissipe les méchants, et fait tourner la roue sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'C’est une lampe de l’Eternel que l’esprit de l’homme; elle sonde jusqu’aux choses les plus profondes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'La bonté et la vérité conserveront le Roi; et il soutient son trône par ses faveurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'La force des jeunes gens est leur gloire; et les cheveux blancs sont l’honneur des anciens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'La meurtrissure de la plaie est un nettoiement au méchant, et des coups qui pénètrent jusqu’au fond de l’âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Le coeur du Roi est en la main de l’Eternel comme des ruisseaux d’eaux, il l’incline à tout ce qu’il veut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Chaque voie de l’homme lui semble droite; mais l’Eternel pèse les coeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Faire ce qui est juste et droit, est une chose que l’Eternel aime mieux que des sacrifices.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Les yeux élevés, et le coeur enflé, est le labourage des méchants, qui n’est que péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Les pensées d’un homme diligent le conduisent à l’abondance, mais tout étourdi tombe dans l’indigence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Travailler à avoir des trésors par une langue trompeuse, c’est une vanité poussée au loin par ceux qui cherchent la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Le fourragement des méchants les abattra, parce qu’ils auront refusé de faire ce qui est droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Quand un homme marche de travers, il s’égare; mais l’oeuvre de celui qui est pur, est droite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Il vaut mieux habiter au coin d’un toit, que dans une maison spacieuse avec une femme querelleuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'L’âme du méchant souhaite le mal, et son prochain ne trouve point de grâce devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Quand on punit le moqueur, le niais devient sage; et quand on instruit le sage, il reçoit la science.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Le juste considère prudemment la maison du méchant, quand les méchants sont renversés dans la misère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Celui qui bouche son oreille pour n’ouïr point le cri du chétif, criera aussi lui-même, et on ne lui répondra point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Le don fait en secret apaise la colère, et le présent mis au sein apaise une véhémente fureur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'C’est une joie au juste de faire ce qui est droit; mais c’est une frayeur aux ouvriers d’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'L’homme qui se détourne du chemin de la prudence aura sa demeure dans l’assemblée des trépassés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'L’homme qui aime à rire, sera indigent; et celui qui aime le vin et la graisse, ne s’enrichira point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Le méchant sera l’échange du juste; et le perfide, au lieu des hommes intègres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Il vaut mieux habiter dans une terre déserte, qu’avec une femme querelleuse et qui se dépite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'La provision désirable, et l’huile, est dans la demeure du sage; mais l’homme fou l’engloutit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Celui qui s’adonne soigneusement à la justice, et à la miséricorde, trouvera la vie, la justice, et la gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Le sage entre dans la ville des forts, et rabaisse la force de sa confiance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Celui qui garde sa bouche et sa langue, garde son âme de détresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Un superbe arrogant s’appelle un moqueur, qui fait tout avec colère et fierté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Le souhait du paresseux le tue; car ses mains ont refusé de travailler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Il y a tel qui tout le jour ne fait que souhaiter; mais le juste donne, et n’épargne rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Le sacrifice des méchants est une abomination; combien plus s’ils l’apportent avec une méchante intention?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Le témoin menteur périra; mais l’homme qui écoute, parlera avec gain de cause.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'L’homme méchant a un air impudent; mais l’homme juste dresse ses voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Il n’y a ni sagesse, ni intelligence, ni conseil contre l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Le cheval est équipé pour le jour de la bataille, mais la délivrance vient de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'La renommée est préférable aux grandes richesses, et la bonne grâce plus que l’argent ni l’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Le riche et le pauvre s’entre-rencontrent: celui qui les a tous faits, c’est l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'L’homme bien avisé prévoit le mal, et se tient caché; mais les niais passent, et en payent l’amende.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'La récompense de la débonnaireté et de la crainte de l’Eternel sont les richesses, la gloire et la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Il y a des épines et des pièges dans la voie du pervers; celui qui aime son âme, s’en retirera loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Instruis le jeune enfant, à l’entrée de sa voie; lors même qu’il sera devenu vieux, il ne s’en retirera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Le riche dominera sur les pauvres; et celui qui emprunte, sera serviteur de l’homme qui prête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Celui qui sème la perversité, moissonnera le tourment; et la verge de son indignation prendra fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'L’oeil bénin sera béni, parce qu’il aura donné de son pain au pauvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Chasse le moqueur, et le débat sortira, et la querelle, et l’ignominie cesseront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Le Roi est ami de celui qui aime la pureté de coeur, et qui a de la grâce en son parler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Les yeux de l’Eternel protègent la science, mais il renverse les paroles du perfide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Le paresseux dit: le lion est là dehors; je serais tué dans les rues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'La bouche des étrangers est une fosse profonde; celui que l’Eternel a en détestation, y tombera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'La folie est liée au coeur du jeune enfant; mais la verge du châtiment la fera éloigner de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Celui qui fait tort au pauvre pour s’accroître, et qui donne au riche, ne peut manquer de tomber dans l’indigence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Prête ton oreille, et écoute les paroles des sages, et applique ton coeur à ma science.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Car ce te sera une chose agréable si tu les gardes au-dedans de toi, et si elles sont rangées ensemble sur tes lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Je te l’ai aujourd’hui fait entendre, à toi, dis-je, afin que ta confiance soit en l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Ne t’ai-je pas écrit des choses convenables aux Gouverneurs en conseil et en science;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'Afin de te donner à connaître la certitude des paroles de vérité, pour répondre des paroles de vérité à ceux qui envoient vers toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Ne pille point le chétif, parce qu’il est chétif; et ne foule point l’affligé à la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Car l’Eternel défendra leur cause, et enlèvera l’âme de ceux qui les auront volés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Ne t’accompagne point de l’homme colère, et ne va point avec l’homme furieux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'De peur que tu n’apprennes son train, et que tu ne reçoives un piège dans ton âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Ne sois point de ceux qui frappent dans la main, ni de ceux qui cautionnent pour les dettes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Si tu n’avais pas de quoi payer, pourquoi prendrait-on ton lit de dessous toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Ne recule point la borne ancienne que tes pères ont faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'As-tu vu un homme habile en son travail? il sera au service des Rois, et non à celui des gens de basse condition.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Quand tu seras assis pour manger avec quelque Seigneur, considère attentivement ce qui sera devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'Autrement tu te mettras le couteau à la gorge, si ton appétit te domine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Ne désire point ses friandises, car c’est une viande trompeuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Ne travaille point à t’enrichir; et désiste-toi de la résolution que tu en as prise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Jetteras-tu tes yeux sur ce qui bientôt n’est plus? car certainement il se fera des ailes; il s’envolera, comme un aigle dans les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Ne mange point la viande de celui qui a l’oeil malin, et ne désire point ses friandises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Car selon qu’il a pensé en son âme, tel est-il. Il te dira bien: mange et bois, mais son coeur n’est point avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Ton morceau, que tu auras mangé, tu le voudrais rendre, et tu auras perdu tes paroles agréables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Ne parle point, le fou t’écoutant; car il méprisera la prudence de ton discours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Ne recule point la borne ancienne, et n’entre point dans les champs des orphelins:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Car leur garant est puissant; il défendra leur cause contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Applique ton coeur à l’instruction, et tes oreilles aux paroles de science.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'N’écarte point du jeune enfant la correction; quand tu l’auras frappé de la verge, il n’en mourra point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Tu le frapperas avec la verge, mais tu délivreras son âme du sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Mon fils, si ton coeur est sage, mon coeur s’en réjouira, oui, moi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'Certes mes reins tressailliront de joie, quand tes lèvres proféreront des choses droites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Que ton coeur ne porte point d’envie aux pécheurs; mais adonne- toi à la crainte de l’Eternel tout le jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Car véritablement il y aura bonne issue, et ton attente ne sera point retranchée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Toi, mon fils, écoute, et sois sage; et fais marcher ton coeur dans cette voie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Ne fréquente point les ivrognes, ni les gourmands.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Car l’ivrogne et le gourmand seront appauvris; et le long dormir fait vêtir des robes déchirées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Ecoute ton père, comme étant celui qui t’a engendré; et ne méprise point ta mère, quand elle sera devenue vieille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Achète la vérité, et ne la vends point; achète la sagesse, l’instruction et la prudence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Le père du juste s’égayera extrêmement; et celui qui aura engendré le sage, en aura de la joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Que ton père et ta mère se réjouissent, et que celle qui t’a enfanté s’égaye.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Mon fils, donne-moi ton coeur, et que tes yeux prennent garde à mes voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Car la femme débauchée est une fosse profonde, et l’étrangère est un puits de détresse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Aussi se tient-elle en embûche, comme après la proie: et elle multipliera les transgresseurs entre les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'A qui est: malheur à moi? à qui est: hélas? à qui les débats? à qui le bruit? à qui les blessures sans cause? à qui la rougeur des yeux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'A ceux qui s’arrêtent auprès du vin, et qui vont chercher le vin mixtionné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Ne regarde point le vin quand il se montre rouge, et quand il donne sa couleur dans la coupe, et qu’il coule droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Il mord par derrière comme un serpent, et il pique comme un basilic.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Puis tes yeux regarderont les femmes étrangères, et ton coeur parlera en insensé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'Et tu seras comme celui qui dort au coeur de la mer, et comme celui qui dort au sommet du mât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, 'On m’a battu, diras-tu, et je n’en ai point été malade; on m’a moulu de coups, et je ne l’ai point senti; quand me réveillerai-je? Je me remettrai encore à le chercher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Ne porte point d’envie aux hommes malins, et ne désire point d’être avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Car leur coeur pense à piller, et leurs lèvres parlent de nuire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'La maison sera bâtie par la sagesse, et sera affermie par l’intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'Et par la science les cabinets seront remplis de tous les biens précieux et agréables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'L’homme sage est accompagné de force, et l’homme qui a de l’intelligence renforce la puissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Car par la prudence tu feras la guerre avantageusement, et la délivrance consiste dans le nombre des conseillers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Il n’y a point de sagesse qui ne soit trop haute pour le fou; il n’ouvrira point sa bouche à la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Celui qui pense à faire mal, on l’appellera, Songe-malice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Le discours de la folie n’est que péché, et le moqueur est en abomination à l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Si tu as perdu courage dans la calamité, ta force s’est diminuée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Si tu te retiens pour ne délivrer point ceux qui sont traînés à la mort, et qui sont sur le point d’être tués,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Parce que tu diras: Voici, nous n’en avons rien su; celui qui pèse les coeurs ne l’entendra-t-il point? et celui qui garde ton âme, ne le saura-t-il point? et ne rendra-t-il point à chacun selon son oeuvre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Mon fils, mange le miel, car il est bon; et le rayon de miel, car il est doux à ton palais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Ainsi sera à ton âme la connaissance de la sagesse, quand tu l’auras trouvée; et il y aura une bonne issue, et ton attente ne sera point retranchée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Méchant, n’épie point le domicile du juste, et ne détruis point son gîte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Car le juste tombera sept fois, et sera relevé; mais les méchants tombent dans le mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Quand ton ennemi sera tombé, ne t’en réjouis point; et quand il sera renversé, que ton coeur ne s’en égaye point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'De peur que l’Eternel ne le voie, et que cela ne lui déplaise, tellement qu’il détourne de dessus lui sa colère sur toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Ne te dépite point à cause des gens malins; ne porte point d’envie aux méchants;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Car il n’y aura point de bonne issue pour le méchant, et la lampe des méchants sera éteinte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Mon fils, crains l’Eternel, et le Roi; et ne te mêle point avec des gens remuants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Car leur calamité s’élèvera tout d’un coup; et qui sait l’inconvénient qui arrivera à ces deux-là?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Ces choses aussi sont pour les sages. Il n’est pas bon d’avoir égard à l’apparence des personnes en jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Celui qui dit au méchant: Tu es juste, les peuples le maudiront, et les nations l’auront en détestation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'Mais pour ceux qui le reprennent, ils en retireront de la satisfaction, et la bénédiction que les biens accompagnent se répandra sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Celui qui répond avec justesse fait plaisir à celui qui l’écoute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Range ton ouvrage dehors, et l’apprête au champ qui est à toi, et puis bâtis ta maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Ne sois point témoin contre ton prochain, sans qu’il en soit besoin; car voudrais-tu t’en faire croire par tes lèvres?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Ne dis point: comme il m’a fait, ainsi lui ferai-je; je rendrai à cet homme selon ce qu’il m’a fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'J’ai passé près du champ de l’homme paresseux, et près de la vigne de l’homme dépourvu de sens;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'Et voilà, tout y était monté en chardons, et les orties avaient couvert le dessus, et sa cloison de pierres était démolie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Et ayant vu cela, je le mis dans mon coeur, je le regardai, j’en reçus de l’instruction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Un peu de dormir, un peu de sommeil, un peu de ploiement de bras pour demeurer couché,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'Et ta pauvreté viendra comme un passant; et ta disette, comme un soldat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Ces choses sont aussi des Proverbes de Salomon, que les gens d’Ezéchias Roi de Juda ont copiés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'La gloire de Dieu est de celer la chose; et la gloire des Rois est de sonder les affaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Il n’y a pas moyen de sonder les cieux à cause de leur hauteur; ni la terre à cause de sa profondeur; ni le coeur des Rois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Ôte les écumes de l’argent, et il en sortira une bague au fondeur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Ôte le méchant de devant le Roi, et son trône sera affermi par la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Ne fais point le magnifique devant le Roi, et ne te tiens point dans la place des Grands.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Car il vaut mieux qu’on te dise; monte ici, que si on t’abaissait devant celui qui est en dignité, lequel tes yeux auront vu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Ne te hâte pas de sortir pour quereller, de peur que tu ne saches que faire à la fin, après que ton prochain t’aura rendu confus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Traite tellement ton différend avec ton prochain, que tu ne révèles point le secret d’un autre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'De peur que celui qui l’écoute ne te le reproche, et que tu n’en reçoives un opprobre qui ne s’efface point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Telles que sont des pommes d’or émaillées d’argent, telle est la parole dite comme il faut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Quand on reprend le sage qui a l’oreille attentive, c’est comme une bague d’or, ou comme un joyau de fin or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'L’ambassadeur fidèle est à ceux qui l’envoient, comme la froideur de la neige au temps de la moisson, et il restaure l’âme de son maître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Celui qui se vante d’une fausse libéralité, est comme les nuées et le vent sans pluie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Le capitaine est fléchi par la patience, et la langue douce brise les os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Quand tu auras trouvé du miel, n’en mange qu’autant qu’il t’en faut, de peur qu’en étant soûlé, tu ne le rendes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Mets rarement ton pied dans la maison de ton prochain, de peur qu’étant rassasié de toi, il ne te haïsse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'L’homme qui porte un faux témoignage contre son prochain, est un marteau, une épée, et une flèche aiguë.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'La confiance qu’on met en celui qui se porte perfidement au temps de la détresse, est une dent qui se rompt, et un pied qui glisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Celui qui chante des chansons au coeur affligé, est comme celui qui ôte sa robe dans le temps du froid, et comme du vinaigre répandu sur le savon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Si celui qui te hait a faim, donne-lui à manger du pain; et s’il a soif, donne-lui à boire de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'Car tu enlèveras des charbons de feu de dessus sa tête, et l’Eternel te le rendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Le vent de bise chasse la pluie; et le visage sévère chasse la langue qui médit en secret.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Il vaut mieux habiter au coin d’un toit, que dans une maison spacieuse avec une femme querelleuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Les bonnes nouvelles apportées d’un pays éloigné, sont comme de l’eau fraîche à une personne altérée et lasse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Le juste qui bronche devant le méchant, est une fontaine embourbée, et une source gâtée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Comme il n’est pas bon de manger trop de miel, aussi il n’y a pas de la gloire pour ceux qui la cherchent avec trop d’ardeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'L’homme qui ne peut pas retenir son esprit, est comme une ville où il y a brèche, et qui est sans murailles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Comme la neige ne convient pas en été, ni la pluie en la moisson, ainsi la gloire ne convient point à un fou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Comme l’oiseau est prompt à aller çà et là, et l’hirondelle à voler, ainsi la malédiction donnée sans sujet n’arrivera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Le fouet est pour le cheval, le licou pour l’âne, et la verge pour le dos des fous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Ne réponds point au fou selon sa folie, de peur que tu ne lui sois semblable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Réponds au fou selon sa folie, de peur qu’il ne s’estime être sage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Celui qui envoie des messages par un fou, se coupe les pieds; et boit la peine du tort qu’il s’est fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Faites marcher un homme qui ne va qu’en clochant; il en sera tout de même d’un propos sentencieux dans la bouche des fous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Il en est de celui qui donne de la gloire à un fou, comme s’il jetait une pierre précieuse dans un monceau de pierres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Ce qu’est une épine qui entre dans la main d’un homme ivre, cela même est un propos sentencieux dans la bouche des fous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Les Grands donnent de l’ennui à tous, et prennent à gage les fous et les transgresseurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Comme le chien retourne à ce qu’il a vomi, ainsi le fou réitère sa folie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'As-tu vu un homme qui croit être sage? il y a plus d’espérance d’un fou que de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Le paresseux dit: le grand lion est dans le chemin, le lion est par les champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Comme une porte tourne sur ses gonds, ainsi se tourne le paresseux sur son lit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Le paresseux cache sa main au sein, il a de la peine de la ramener à sa bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Le paresseux se croit plus sage que sept autres qui donnent de sages conseils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Celui qui en passant se met en colère pour une dispute qui ne le touche en rien, est comme celui qui prend un chien par les oreilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Tel qu’est celui qui fait de l’insensé, et qui cependant jette des feux, des flèches, et des choses propres à tuer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'Tel est l’homme qui a trompé son ami, et qui après cela dit: Ne me jouais-je pas?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Le feu s’éteint faute de bois; ainsi quand il n’y aura plus de semeurs de rapports, les querelles s’apaiseront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Le charbon est pour faire de la braise, et le bois pour faire du feu, et l’homme querelleux pour exciter des querelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Les paroles d’un semeur de rapports sont comme de ceux qui ne font pas semblant d’y toucher, mais elles descendent jusqu’au-dedans du coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Les lèvres ardentes, et le coeur mauvais, sont comme de la litharge enduite sur un pot de terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Celui qui hait se contrefait en ses lèvres, mais il cache la fraude au-dedans de soi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Quand il parlera gracieusement, ne le crois point; car il y a sept abominations dans son coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'La malice de celui qui la cache comme dans un lieu secret, sera révélée dans l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Celui qui creuse la fosse, y tombera; et la pierre retournera sur celui qui la roule.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'La fausse langue hait celui qu’elle a abattu; et la bouche qui flatte fait tomber.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Ne te vante point du jour de demain; car tu ne sais pas quelle chose le jour enfantera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Qu’un autre te loue, et non pas ta bouche; que ce soit l’étranger, et non pas tes lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'La pierre est pesante, et le sablon est accablant; mais le dépit du fou est plus pesant que tous les deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Il y a de la cruauté dans la fureur, et du débordement dans la colère; mais qui pourra subsister devant la jalousie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'La correction ouverte vaut mieux qu’un amour secret.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Les plaies faites par celui qui aime, sont fidèles, et les baisers de celui qui hait, sont à craindre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'L’âme rassasiée foule les rayons de miel; mais à l’âme qui a faim, toute chose amère est douce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Tel qu’est un oiseau s’écartant de son nid, tel est l’homme qui s’écarte de son lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'L’huile et le parfum réjouissent le coeur, et il en est ainsi de la douceur d’un ami, laquelle vient d’un conseil cordial.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Ne quitte point ton ami, ni l’ami de ton père, et n’entre point en la maison de ton frère au temps de ta calamité; car le voisin qui est proche, vaut mieux que le frère qui est loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Mon fils sois sage, et réjouis mon coeur, afin que j’aie de quoi répondre à celui qui me fait des reproches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'L’homme bien avisé prévoit le mal, et se tient caché; mais les niais passent outre, et ils en payent l’amende.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Quand quelqu’un aura cautionné pour l’étranger, prends son vêtement, et prends gage de lui pour l’étrangère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Celui qui bénit son ami à haute voix, se levant de grand matin, sera tenu comme s’il le maudissait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Une gouttière continuelle au temps de la grosse pluie, et une femme querelleuse, c’est tout un.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Celui qui la veut retenir, retient le vent; et elle se fera connaître comme un parfum qu’il aurait dans sa main droite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Comme le fer aiguise le fer, ainsi l’homme aiguise la face de son ami.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Comme celui qui garde le figuier, mangera de son fruit; ainsi celui qui garde son maître sera honoré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Comme dans l’eau le visage répond au visage, ainsi le coeur de l’homme répond à l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Le sépulcre et le gouffre ne sont jamais rassasiés; aussi les yeux des hommes ne sont jamais satisfaits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Comme le fourneau est pour éprouver l’argent, et le creuset l’or; ainsi est à l’homme la bouche qui le loue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Quand tu pilerais le fou au mortier parmi du grain qu’on pile avec un pilon, sa folie ne se départira point de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Sois soigneux à reconnaître l’état de tes brebis, et mets ton coeur aux parcs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Car le trésor ne dure point à toujours, et la couronne n’est pas d’âge en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Le foin se montre, et l’herbe paraît, et on amasse les herbes des montagnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'Les agneaux sont pour te vêtir, et les boucs sont le prix d’un champ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'Et l’abondance du lait des chèvres sera pour ton manger, pour le manger de ta maison, et pour la vie de tes servantes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Tout méchant fuit sans qu’on le poursuive; mais les justes seront assurés comme un jeune lion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Il y a plusieurs gouverneurs, à cause des forfaits du pays, mais pour l’amour de l’homme avisé et intelligent, il y aura prolongation du même Gouvernement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'L’homme qui est pauvre, et qui opprime les chétifs, est comme une pluie, qui faisant du ravage cause la disette du pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Ceux qui abandonnent la Loi, louent le méchant; mais ceux qui gardent la Loi, leur font la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Les gens adonnés au mal n’entendent point ce qui est droit; mais ceux qui cherchent l’Eternel entendent tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Le pauvre qui marche en son intégrité, vaut mieux que le pervers qui marche par deux chemins, encore qu’il soit riche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Celui qui garde la Loi est un enfant prudent, mais celui qui entretient les gourmands, fait honte à son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Celui qui augmente son bien par usure et par surcroît, l’assemble pour celui qui en fera des libéralités aux pauvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Celui qui détourne son oreille pour ne point écouter la Loi, sa requête elle-même sera une abomination.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Celui qui fait égarer par un mauvais chemin ceux qui vont droit, tombera dans la fosse qu’il aura faite; mais ceux qui sont intègres hériteront le bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'L’homme riche pense être sage; mais le chétif qui est intelligent, le sondera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Quand les justes se réjouissent, la gloire est grande, mais quand les méchants sont élevés, chacun se déguise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Celui qui cache ses transgressions, ne prospérera point; mais celui qui les confesse, et les délaisse, obtiendra miséricorde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Bienheureux est l’homme qui se donne frayeur continuellement; mais celui qui endurcit son coeur, tombera dans la calamité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Le dominateur méchant sur un peuple pauvre, est un lion rugissant, et comme un ours quêtant sa proie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Le Conducteur qui manque d’intelligence, fait beaucoup d’extorsions; mais celui qui hait le gain déshonnête, prolongera ses jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'L’homme qui fait tort au sang d’une personne, fuira jusqu’en la fosse, sans qu’aucun le retienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Celui qui marche dans l’intégrité sera sauvé; mais le pervers qui marche par deux chemins, tombera tout à coup.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Celui qui laboure sa terre, sera rassasié de pain; mais celui qui suit les fainéants, sera accablé de misère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'L’homme fidèle abondera en bénédictions, mais celui qui se hâte de s’enrichir ne demeurera point impuni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Il n’est pas bon d’avoir égard à l’apparence des personnes; car pour un morceau de pain, l’homme commettrait un crime.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'L’homme qui a l’oeil malin se hâte pour avoir des richesses, et il ne sait pas que la disette lui arrivera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Celui qui reprend quelqu’un, sera à la fin plus chéri que celui qui flatte de sa langue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Celui qui pille son père ou sa mère, et qui dit que ce n’est point un péché, est compagnon de l’homme dissipateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Celui qui a le coeur enflé excite la querelle; mais celui qui s’assure sur l’Eternel, sera engraissé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Celui qui se confie en son propre coeur, est un fou; mais celui qui marche sagement, sera délivré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Celui qui donne au pauvre, n’aura point de disette; mais celui qui en détourne ses yeux, abondera en malédictions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Quand les méchants s’élèvent, l’homme se cache; mais quand ils périssent, les justes se multiplient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'L’homme qui étant repris roidit son cou, sera subitement brisé, sans qu’il y ait de guérison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Quand les justes sont avancés, le peuple se réjouit; mais quand le méchant domine, le peuple gémit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'L’homme qui aime la sagesse, réjouit son père; mais celui qui entretient les femmes débauchées, dissipe ses richesses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Le Roi maintient le pays par le jugement; mais l’homme qui est adonné aux présents, le ruinera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'L’homme qui flatte son prochain, étend le filet devant ses pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'Le mal qui est au forfait de l’homme, lui est comme un piège; mais le juste chantera, et se réjouira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Le juste prend connaissance de la cause des pauvres; mais le méchant n’en prend point connaissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Les hommes moqueurs troublent la ville; mais les sages apaisent la colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'L’homme sage contestant avec l’homme fou, soit qu’il s’émeuve, soit qu’il rie, n’aura point de repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Les hommes sanguinaires ont en haine l’homme intègre, mais les hommes droits tiennent chère sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Le fou pousse au-dehors toute sa passion, mais le sage la réprime, et la renvoie en arrière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Tous les serviteurs d’un Prince qui prête l’oreille à la parole de mensonge, sont méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Le pauvre et l’homme usurier s’entre-rencontrent, et l’Eternel illumine les yeux de tous deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Le trône du Roi qui fait justice selon la vérité aux pauvres, sera établi à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'La verge et la répréhension donnent la sagesse; mais l’enfant abandonné à lui-même fait honte à sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Quand les méchants sont avancés, les forfaits se multiplient; mais les justes verront leur ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Corrige ton enfant, et il te mettra en repos, et il donnera du plaisir à ton âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Lorsqu’il n’y a point de vision, le peuple est abandonné; mais bienheureux est celui qui garde la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Le serviteur ne se corrige point par des paroles; car il entendra, et ne répondra point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'As-tu vu un homme précipité en ses paroles? il y a plus d’espérance d’un fou que de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Le serviteur sera enfin fils de celui qui l’élève délicatement dès sa jeunesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'L’homme colère excite les querelles, et l’homme furieux commet plusieurs forfaits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'L’orgueil de l’homme l’abaisse, mais celui qui est humble d’esprit obtient la gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Celui qui partage avec le larron, hait son âme; il entend le serment d’exécration, et il ne le décèle point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'L’effroi que conçoit un homme, lui tend un piège; mais celui qui s’assure en l’Eternel aura une haute retraite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Plusieurs recherchent la face de celui qui domine; mais c’est de l’Eternel que vient le jugement qu’on donne touchant quelqu’un.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'L’homme inique est en abomination aux justes; et celui qui va droit, est en abomination au méchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Les paroles d’Agur fils de Jaké, savoir la charge que cet homme- là proféra à Ithiel, à Ithiel, dis-je, et à Ucal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Certainement je suis le plus hébété de tous les hommes, et il n’y a point en moi de prudence humaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'Et je n’ai point appris la sagesse; et saurais-je la science des saints?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Qui est celui qui est monté aux cieux, et qui en est descendu? Qui est celui qui a renfermé le vent dans ses poings, qui a serré les eaux dans son manteau, qui a dressé toutes les bornes de la terre? Quel est son nom, et quel est le nom de son fils, si tu le connais?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Toute la parole de Dieu est épurée; il est un bouclier à ceux qui ont leur refuge vers lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'N’ajoute rien à ses paroles, de peur qu’il ne te reprenne, et que tu ne sois trouvé menteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Je t’ai demandé deux choses, ne me les refuse point durant ma vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Eloigne de moi la vanité, et la parole de mensonge; ne me donne ni pauvreté ni richesses, nourris-moi du pain de mon ordinaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'De peur qu’étant rassasié je ne te renie, et que je ne dise: qui est l’Eternel? de peur aussi qu’étant appauvri, je ne dérobe, et que je ne prenne en vain le nom de mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Ne blâme point le serviteur devant son maître, de peur que ce serviteur ne te maudisse, et qu’il ne t’en arrive du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Il y a une race de gens qui maudit son père, et qui ne bénit point sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'Il y a une race de gens qui pense être nette, et qui toutefois n’est point lavée de son ordure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Il y a une race de gens de laquelle les yeux sont fort hautains, et dont les paupières sont élevées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'Il y a une race de gens dont les dents sont des épées, et dont les dents mâchelières sont des couteaux, pour consumer de dessus la terre les affligés et les nécessiteux d’entre les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'La sangsue a deux filles, qui disent: Apporte, apporte. Il y a trois choses qui ne se rassasient point; il y en a même quatre qui ne disent point; C’est assez:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'Le sépulcre, la matrice stérile, la terre qui n’est point rassasiée d’eau, et le feu qui ne dit point: C’est assez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'L’oeil de celui qui se moque de son père, et qui méprise l’enseignement de sa mère, les corbeaux des torrents le crèveront, et les petits de l’aigle le mangeront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Il y a trois choses qui sont trop merveilleuses pour moi, même quatre, lesquelles je ne connais point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'Savoir, la trace de l’aigle dans l’air, la trace du serpent sur un rocher, le chemin d’un navire au milieu de la mer, et la trace de l’homme vers la vierge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Telle est la trace de la femme adultère; elle mange, et s’essuie la bouche, puis elle dit: Je n’ai point commis d’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'La terre tremble pour trois choses, même pour quatre, lesquelles elle ne peut porter:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'Pour le serviteur quand il règne; pour l’insensé quand il est rassasié de viande;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'Pour la femme digne d’être haïe, quand elle se marie; et pour la servante quand elle hérite de sa maîtresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Il y a quatre choses très-petites en la terre qui toutefois sont bien sages et bien avisées:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'Les fourmis, qui sont un peuple faible, et qui néanmoins préparent durant l’été leur nourriture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'Les lapins, qui sont un peuple sans force, et qui néanmoins font leurs maisons dans les rochers;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'Les sauterelles, qui n’ont point de Roi, et qui toutefois vont toutes par bandes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'L’araignée, qui saisit les mouches avec ses pieds, et qui est pourtant dans les palais des Rois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Il y a trois choses qui ont un beau marcher, même quatre, qui ont une belle démarche:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'Le lion, qui est le plus fort d’entre les bêtes, et qui ne tourne point en arrière pour la rencontre de qui que ce soit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'Le cheval, qui a les flancs bien troussés; le bouc; et le Roi, devant qui personne ne peut subsister.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Si tu t’es porté follement en t’élevant, et si tu as mal pensé, mets ta main sur la bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Comme celui qui bat le lait, en fait sortir le beurre; et celui qui presse le nez, en fait sortir le sang; ainsi celui qui presse la colère, excite la querelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Les paroles du Roi Lémuel et l’instruction que sa mère lui donna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Quoi? mon fils? quoi, fils de mon ventre? eh quoi? mon fils, pour lequel j’ai tant fait de voeux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Ne donne point ta force aux femmes, et ne mets point ton étude à détruire les Rois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Lémuel, ce n’est point aux Rois, ce n’est point aux Rois de boire le vin, ni aux Princes de boire la cervoise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'De peur qu’ayant bu, ils n’oublient l’ordonnance, et qu’ils n’altèrent le droit de tous les pauvres affligés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Donnez de la cervoise à celui qui s’en va périr, et du vin à celui qui est dans l’amertume de coeur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Afin qu’il en boive, et qu’il oublie sa pauvreté, et ne se souvienne plus de sa peine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Ouvre ta bouche en faveur du muet, pour le droit de tous ceux qui s’en vont périr.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Ouvre ta bouche, fais justice, et fais droit à l’affligé et au nécessiteux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Aleph. Qui est-ce qui trouvera une vaillante femme? car son prix surpasse de beaucoup les perles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Beth. Le coeur de son mari s’assure en elle, et il ne manquera point de dépouilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Guimel. Elle lui fait du bien tous les jours de sa vie, et jamais du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Daleth. Elle cherche de la laine et du lin, et elle fait ce qu’elle veut de ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'He. Elle est comme les navires d’un marchand, elle amène son pain de loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Vau. Elle se lève lorsqu’il est encore nuit, elle distribue la nourriture nécessaire à sa maison, et elle donne à ses servantes leur tâche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Zajin. Elle considère un champ, et l’acquiert; et elle plante la vigne du fruit de ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Heth. Elle ceint ses reins de force, et fortifie ses bras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Teth. Elle éprouve que son trafic est bon; sa lampe ne s’éteint point la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Jod. Elle met ses mains au fuseau, et ses mains tiennent la quenouille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Caph. Elle tend sa main à l’affligé, et avance ses mains au nécessiteux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Lamed. Elle ne craint point la neige pour sa famille, car toute sa famille est vêtue de vêtements doubles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Mem. Elle se fait des tours de lit; le fin lin et l’écarlate est ce dont elle s’habille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Nun. Son mari est reconnu aux portes, quand il est assis avec les Anciens du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Samech. Elle fait du linge, et le vend; et elle fait des ceintures, qu’elle donne au marchand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Hajin. La force et la magnificence est son vêtement, et elle se rit du jour à venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Pe. Elle ouvre sa bouche avec sagesse, et la Loi de la charité est sur sa langue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Tsade. Elle contemple le train de sa maison, et ne mange point le pain de paresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Koph. Ses enfants se lèvent, et la disent bienheureuse; son mari aussi, et il la loue, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Resch. Plusieurs filles ont été vaillantes; mais tu les surpasses toutes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Scin. La grâce trompe, et la beauté s’évanouit; mais la femme qui craint l’Eternel, sera celle qui sera louée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Thau. Donnez-lui des fruits de ses mains, et que ses oeuvres la louent aux portes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Les paroles de l’Ecclésiaste, fils de David, Roi de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Vanité des vanités, dit l’Ecclésiaste; vanité des vanités, tout est vanité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Quel avantage a l’homme de tout son travail auquel il s’occupe sous le soleil?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Une génération passe, et l’autre génération vient, mais la terre demeure toujours ferme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Le soleil aussi se lève, et le soleil se couche, et il soupire après le lieu d’où il se lève.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Le vent va vers le Midi, et tournoie vers l’Aquilon; il va tournoyant çà et là, et il retourne après ses circuits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Tous les fleuves vont en la mer, et la mer n’en est point remplie; les fleuves retournent au lieu d’où ils étaient partis, pour revenir en la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Toutes choses travaillent plus que l’homme ne saurait dire: l’œil n’est jamais rassasié de voir, ni l’oreille assouvie d’ouïr.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Ce qui a été, c’est ce qui sera; et ce qui a été fait, est ce qui se fera, et il n’y a rien de nouveau sous le soleil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Y a-t-il quelque chose dont on puisse dire: Regarde cela, il est nouveau? Il a déjà été dans les siècles qui ont été avant nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'On ne se souvient point des choses qui ont précédé, on ne se souviendra point des choses qui seront à l’avenir, et ceux qui viendront n’en auront aucun souvenir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Moi l’Ecclésiaste, j’ai été Roi sur Israël à Jérusalem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'Et j’ai appliqué mon cœur à rechercher et à sonder par la sagesse tout ce qui se faisait sous les cieux, ce qui est une occupation fâcheuse que Dieu a donnée aux hommes, afin qu’ils s’y occupent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'J’ai regardé tout ce qui se faisait sous le soleil, et voilà tout est vanité, et rongement d’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Ce qui est tortu ne se peut redresser; et les défauts ne se peuvent nombrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'J’ai parlé en mon cœur, disant: Voici, je me suis agrandi et accru en sagesse, par-dessus tous ceux qui ont été avant moi sur Jérusalem, et mon cœur a vu beaucoup de sagesse et de science.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Et j’ai appliqué mon cœur à connaître la sagesse, et à connaître les sottises et la folie, mais j’ai reconnu que cela aussi était un rongement d’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Car où il y a abondance de sagesse, il y a abondance de chagrin; et celui qui s’accroît de la science, s’accroît du chagrin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'J’ai dit en mon cœur: Voyons, que je t’éprouve maintenant par la joie, et prends du bon temps; et voilà, cela aussi est une vanité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'J’ai dit touchant le ris: Il est insensé; et touchant la joie: De quoi sert-elle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'J’ai recherché en moi-même le moyen de me traiter délicatement, de faire que mon cœur s’accoutumât cependant à la sagesse, et qu’il comprît ce que c’est que la folie, jusques à ce que je visse ce qu’il serait bon aux hommes de faire sous les cieux, pendant les jours de leur vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Je me suis fait des choses magnifiques; je me suis bâti des maisons; je me suis planté des vignes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Je me suis fait des jardins et des vergers, et j’y ai planté des arbres fruitiers de toutes sortes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Je me suis fait des réservoirs d’eaux, pour en arroser le parc planté d’arbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'J’ai acquis des hommes et des femmes esclaves; et j’ai eu des esclaves nés en ma maison, et j’ai eu plus de gros et de menu bétail que tous ceux qui ont été avant moi dans Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Je me suis aussi amassé de l’argent et de l’or, et des plus précieux joyaux qui se trouvent chez les Rois et dans les Provinces; je me suis acquis des chanteurs et des chanteuses, et les délices des hommes, une harmonie d’instruments de musique, même plusieurs harmonies de toutes sortes d’instruments;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Je me suis agrandi, et je me suis accru plus que tous ceux qui ont été avant moi dans Jérusalem, et ma sagesse est demeurée avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Enfin, je n’ai rien refusé à mes yeux de tout ce qu’ils ont demandé, et je n’ai épargné aucune joie à mon cœur; car mon cœur s’est réjoui de tout mon travail; et c’est là tout ce que j’ai eu de tout mon travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Mais ayant considéré toutes mes œuvres que mes mains avaient faites, et tout le travail auquel je m’étais occupé en les faisant, voilà tout était vanité, et rongement d’esprit; tellement que l’homme n’a aucun avantage de ce qui est sous le soleil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Puis je me suis mis à considérer tant la sagesse, que les sottises, et la folie, (or qui est l’homme qui pourrait suivre le Roi en ce qui a été déjà fait?)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Et j’ai vu que la sagesse a beaucoup d’avantage sur la folie, comme la lumière a beaucoup d’avantage sur les ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Le sage a ses yeux en sa tête, et le fou marche dans les ténèbres; mais j’ai aussi connu qu’un même accident leur arrive à tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'C’est pourquoi j’ai dit en mon cœur: Il m’arrivera comme au fou; de quoi donc me servira-t-il alors d’avoir été plus sage? C’est pourquoi j’ai dit en mon cœur, que cela aussi est une vanité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Car on ne se souviendra pas du sage, non plus que du fou; parce que ce qui est maintenant, va être oublié dans les jours qui suivent; et comment le sage meurt-il de même que le fou?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'C’est pourquoi j’ai haï cette vie, à cause que les choses qui se sont faites sous le soleil m’ont déplu; car tout est vanité, et rongement d’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'J’ai aussi haï tout mon travail, auquel je me suis occupé sous le soleil, parce que je le laisserai à l’homme qui sera après moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Et qui sait s’il sera sage ou fou? Cependant il sera maître de tout mon travail, auquel je me suis occupé, et de ce en quoi j’ai été sage sous le soleil; cela aussi est une vanité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'C’est pourquoi j’ai fait en sorte que mon cœur perdît toute espérance de tout le travail auquel je m’étais occupé sous le soleil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Car il y a tel homme, dont le travail a été avec sagesse, science, et adresse, qui néanmoins le laisse à celui qui n’y a point travaillé comme étant sa part; cela aussi est une vanité et un grand mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Car qu’est-ce que l’homme a de tout son travail, et du rongement de son cœur, dont il se travaille sous le soleil?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Puisque tous ses jours ne sont que douleurs, et son occupation que chagrin; même la nuit son cœur ne repose point; cela aussi est une vanité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'N’est-ce donc pas un bien pour l’homme de manger, et de boire, et de faire que son âme jouisse du bien dans son travail? J’ai vu aussi que cela vient de la main de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Car qui en mangera, et qui s’en sentira plutôt que moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Parce que Dieu donne à celui qui lui est agréable, de la sagesse, de la science, et de la joie; mais il donne au pécheur de l’occupation à recueillir et à assembler, afin que cela soit donné à celui qui est agréable à Dieu; cela aussi est une vanité, et un rongement d’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'A toute chose sa saison, et à toute affaire sous les cieux, son temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Il y a un temps de naître, et un temps de mourir; un temps de planter, et un temps d’arracher ce qui est planté;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Un temps de tuer, et un temps de guérir; un temps de démolir, et un temps de bâtir;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Un temps de pleurer, et un temps de rire; un temps de lamenter, et un temps de sauter de joie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Un temps de jeter des pierres, et un temps de les ramasser; un temps d’embrasser, et un temps de s’éloigner des embrassements;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Un temps de chercher, et un temps de laisser perdre; un temps de garder, et un temps de rejeter;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Un temps de déchirer, et un temps de coudre; un temps de se taire, et un temps de parler;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Un temps d’aimer, et un temps de haïr; un temps de guerre, et un temps de paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Quel avantage a celui qui travaille, de ce en quoi il se travaille?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'J’ai considéré cette occupation que Dieu a donnée aux hommes pour s’y appliquer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Il a fait que toutes choses sont belles en leur temps; aussi a-t- il mis le monde en leur cœur, sans toutefois que l’homme puisse comprendre d’un bout à l’autre l’œuvre que Dieu a faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'C’est pourquoi j’ai connu qu’il n’y a rien de meilleur aux hommes, que de se réjouir, et de bien faire pendant leur vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Et même, que chacun mange et boive, et qu’il jouisse du bien de tout son travail, c’est un don de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'J’ai connu que quoi que Dieu fasse, c’est toujours lui-même, on ne saurait qu’y ajouter, ni qu’en diminuer; et Dieu le fait afin qu’on le craigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Ce qui a été, est maintenant; et ce qui doit être, a déjà été; et Dieu rappelle ce qui est passé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'J’ai encore vu sous le soleil, qu’au lieu établi pour juger, il y a de la méchanceté; et qu’au lieu établi pour faire justice, il y a aussi de la méchanceté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Et j’ai dit en mon cœur: Dieu jugera le juste et l’injuste; car il y a là un temps pour toute chose, et sur toute œuvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'J’ai pensé en mon cœur sur l’état des hommes, que Dieu les en éclaircirait, et qu’ils verraient qu’ils ne sont que des bêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Car l’accident qui arrive aux hommes, et l’accident qui arrive aux bêtes est un même accident: telle qu’est la mort de l’un, telle est la mort de l’autre; et ils ont tous un même souffle, et l’homme n’a point d’avantage sur la bête; car tout est vanité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Tout va en un même lieu; tout a été fait de la poudre, et tout retourne en la poudre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Qui est-ce qui connaît que le souffle des hommes monte en haut, et que le souffle de la bête descend en bas en terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'J’ai donc connu qu’il n’y a rien de meilleur à l’homme que de se réjouir en ce qu’il fait; parce que c’est là sa portion; car qui est-ce qui le ramènera pour voir ce qui sera après lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Puis je me suis mis à regarder toutes les injustices qui se font sous le soleil; et voilà les larmes de ceux à qui on fait tort, et ils n’ont point de consolation; et la force est du côté de ceux qui leur font tort, et ils n’ont point de consolateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'C’est pourquoi j’estime plus les morts qui sont déjà morts, que les vivants qui sont encore vivants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'Même j’estime celui qui n’a pas encore été, plus heureux que les uns et les autres; car il n’a pas vu les mauvaises actions qui se font sous le soleil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Puis j’ai regardé tout le travail, et l’adresse de chaque métier, et j’ai vu que l’un porte envie à l’autre; cela aussi est une vanité, et un rongement d’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Le fou tient ses mains ployées, et se consume soi-même, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Mieux vaut plein le creux de la main, avec repos, que pleines les deux paumes, avec travail et rongement d’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Puis je me suis mis à regarder une autre vanité sous le soleil;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'C’est qu’il y a tel qui est seul, et qui n’a point de second, qui aussi n’a ni fils ni frère, et qui cependant ne met nulle fin à son travail; même son œil ne voit jamais assez de richesses, et il ne dit point en lui-même: Pour qui est-ce que je travaille, et que je prive mon âme du bien? Cela aussi est une vanité, et une fâcheuse occupation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Deux valent mieux qu’un; car ils ont un meilleur salaire de leur travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Même si l’un des deux tombe, l’autre relèvera son compagnon; mais malheur à celui qui est seul; parce qu’étant tombé, il n’aura personne pour le relever.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Si deux aussi couchent ensemble, ils en auront plus de chaleur; mais celui qui est seul, comment aura-t-il chaud?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Que si quelqu’un force l’un ou l’autre, les deux lui pourront résister; et la corde à trois cordons ne se rompt pas sitôt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Un enfant pauvre et sage vaut mieux qu’un Roi vieux et insensé, qui ne sait ce que c’est que d’être averti.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Car il y a tel qui sort de prison pour régner; et de même il y a tel qui étant né Roi, devient pauvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'J’ai vu tous les vivants qui marchent sous le soleil, suivre le fils qui est la seconde personne après le Roi, et qui doit être en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Tout ce peuple-là, savoir tous ceux qui ont été devant ceux-ci, est sans fin; ces derniers aussi ne se réjouiront point de celui- ci; certainement cela aussi est une vanité, et un rongement d’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Quand tu entreras dans la maison de Dieu, prends garde à ton pied; et approche-toi pour ouïr, plutôt que pour donner ce que donnent les fous, savoir le sacrifice; car ils ne savent point qu’ils font mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Ne te précipite point à parler, et que ton cœur ne se hâte point de parler devant Dieu; car Dieu est au ciel, et toi sur la terre; c’est pourquoi use de peu de paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Car comme le songe vient de la multitude des occupations; ainsi la voix des fous sort de la multitude des paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Quand tu auras voué quelque vœu à Dieu, ne diffère point de l’accomplir; car il ne prend point de plaisir aux fous; accomplis donc ce que tu auras voué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Il vaut mieux que tu ne fasses point de vœux, que d’en faire, et ne les accomplir point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Ne permets point que ta bouche te fasse pécher, et ne dis point devant le messager de Dieu, que c’est ignorance. Pourquoi se courroucerait l’Eternel à cause de ta parole, et détruirait-il l’œuvre de tes mains?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Car comme dans la multitude des songes il y a des vanités, aussi y en a-t-il beaucoup dans la multitude des paroles; mais crains Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Si tu vois dans la Province qu’on fasse tort au pauvre, et que le droit et la justice y soient violés, ne t’étonne point de cela; car un plus haut élevé que ce haut élevé y prend garde, et il y en a de plus haut élevés qu’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'La terre a de l’avantage par-dessus toutes choses; le Roi est asservi au champ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Celui qui aime l’argent, n’est point assouvi par l’argent; et celui qui aime un grand train, n’en est pas nourri; cela aussi est une vanité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Où il y a beaucoup de bien, là il y a beaucoup de gens qui le mangent; et quel avantage en revient-il à son maître, sinon qu’il le voit de ses yeux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Le dormir de celui qui laboure est doux, soit qu’il mange peu, ou beaucoup; mais le rassasiement du riche ne le laisse point dormir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Il y a un mal fâcheux que j’ai vu sous le soleil, c’est que des richesses sont conservées à leurs maîtres afin qu’ils en aient du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Et ces richesses-là périssent par quelque fâcheux accident, de sorte qu’on aura engendré un enfant, et il n’aura rien entre ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Et comme il est sorti nu du ventre de sa mère, il s’en retournera nu, s’en allant comme il est venu, et il n’emportera rien de son travail auquel il a employé ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Et c’ est aussi un mal fâcheux, que comme il est venu, il s’en va de même; et quel avantage a-t-il d’avoir travaillé après du vent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Il mange aussi tous les jours de sa vie en ténèbres, et se chagrine beaucoup, et son mal va jusqu’à la fureur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Voilà donc ce que j’ai vu, que c’est une chose bonne et agréable à l’homme, de manger et de boire, et de jouir du bien de tout son travail qu’il aura fait sous le soleil, durant les jours de sa vie, lesquels Dieu lui a donnés; car c’est là sa portion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Aussi ce que Dieu donne de richesses et de biens à un homme, quel qu’il soit, et dont il le fait maître, pour en manger, et pour en prendre sa part, et pour se réjouir de son travail, c’est là un don de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'Car il ne se souviendra pas beaucoup des jours de sa vie, parce que Dieu lui répond par la joie de son cœur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Il y a un mal que j’ai vu sous le soleil, et qui est fréquent parmi les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'C’est qu’il y a tel homme à qui Dieu donne des richesses, des biens, et des honneurs, en sorte qu’il ne manque rien à son âme de tout ce qu’il saurait souhaiter; mais Dieu ne l’en fait pas le maître pour en manger, et un étranger le mangera; cela est une vanité, et un mal fâcheux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Quand un homme en aurait engendré cent, et qu’il aurait vécu plusieurs années, en sorte que les jours de ses années se soient fort multipliés, cependant si son âme ne s’est point rassasiée de bien, et même s’il n’a point eu de sépulture, je dis qu’un avorton vaut mieux que lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Car il sera venu en vain, et s’en sera allé dans les ténèbres, et son nom aura été couvert de ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Même en ce qu’il n’aura point vu le soleil, ni rien connu, il aura eu plus de repos que cet homme-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Et s’il vivait deux fois mille ans, et qu’il ne jouit d’aucun bien, tous ne vont-ils pas en un même lieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Tout le travail de l’homme est pour sa bouche, et cependant son désir n’est jamais assouvi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Car qu’est-ce que le sage a plus que le fou? ou quel avantage a l’affligé qui sait marcher devant les vivants?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Mieux vaut ce qu’on voit de ses yeux, que si l’âme fait de grandes recherches; cela aussi est une vanité, et un rongement d’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Le nom de ce qui a été, a déjà été nommé; et savait-on ce que devait être l’homme, et qu’il ne pourrait plaider avec celui qui est plus fort que lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Quand on a beaucoup, on n’en a que plus de vanité; et quel avantage en a l’homme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Car qui est-ce qui connaît ce qui est bon à l’homme en sa vie, pendant les jours de la vie de sa vanité, lesquels il passe comme une ombre? Et qui est-ce qui déclarera à l’homme ce qui sera après lui sous le soleil?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'La réputation vaut mieux que le bon parfum; et le jour de la mort, que le jour de la naissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Il vaut mieux aller dans une maison de deuil, que d’aller dans une maison de festin; car en celle-là est la fin de tout homme, et le vivant met cela en son cœur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Il vaut mieux être fâché que rire; à cause que par la tristesse du visage le cœur devient joyeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Le cœur des sages est dans la maison du deuil; mais le cœur des fous est dans la maison de joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Il vaut mieux ouïr la répréhension du sage, que d’ouïr la chanson des fous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Car tel qu’est le bruit des épines sous le chaudron, tel est le ris du fou; cela aussi est une vanité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Certainement l’oppression fait perdre le sens au sage; et le don fait perdre l’entendement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Mieux vaut la fin d’une chose, que son commencement. Mieux vaut l’homme qui est d’un esprit patient, que l’homme qui est d’un esprit hautain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Ne te précipite point dans ton esprit pour te dépiter; car le dépit repose dans le sein des fous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Ne dis point: D’où vient que les jours passés ont été meilleurs que ceux-ci? Car ce que tu t’enquiers de cela n’est pas de la sagesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'La sagesse est bonne avec un héritage, et ceux qui voient le soleil reçoivent de l’avantage d’ elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Car on est à couvert à l’ombre de la sagesse, de même qu’à l’ombre de l’argent; mais la science a cet avantage, que la sagesse fait vivre celui qui en est doué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Regarde l’œuvre de Dieu; car qui est-ce qui pourra redresser ce qu’il aura renversé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Au jour du bien, use du bien, et au jour de l’adversité, prends- y garde; car Dieu a fait l’un à l’opposite de l’autre, afin que l’homme ne trouve rien à redire après lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'J’ai vu tout ceci pendant les jours de ma vanité; il y a tel juste, qui périt dans sa justice; et il y a tel méchant, qui prolonge ses jours dans sa méchanceté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Ne te crois pas trop juste, et ne te fais pas plus sage qu’il ne faut; pourquoi en serais-tu surpris?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Ne sois point trop remuant, et ne sois point fou; pourquoi mourrais-tu avant ton temps?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Il est bon que tu retiennes ceci, et aussi que tu ne retires point ta main de l’autre; car qui craint Dieu sort de tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'La sagesse donne plus de force au sage, que dix Gouverneurs qui seraient dans une ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Certainement il n’y a point d’homme juste sur la terre, qui agisse toujours bien, et qui ne pèche point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Ne mets point aussi ton cœur à toutes les paroles qu’on dira, afin que tu n’entendes pas ton serviteur médisant de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Car aussi ton cœur a connu plusieurs fois que tu as pareillement mal parlé des autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'J’ai essayé tout ceci avec sagesse, et j’ai dit: J’acquerrai de la sagesse; mais elle s’est éloignée de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Ce qui a été, est bien loin, et il est enfoncé fort bas; qui le trouvera?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Moi et mon cœur nous nous sommes agités pour savoir, pour épier, et pour chercher la sagesse, et la raison de tout; et pour connaître la malice de la folie, de la bêtise, et des sottises;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'Et j’ai trouvé que la femme qui est comme des rets, et dont le cœur est comme des filets, et dont les mains sont comme des liens, est une chose plus amère que la mort; celui qui est agréable à Dieu en échappera, mais le pécheur y sera pris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Vois, dit l’Ecclésiaste, ce que j’ai trouvé en cherchant la raison de toutes choses, l’une après l’autre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'C’est, que jusqu’à présent mon âme a cherché, mais que je n’ai point trouvé, c’est, dis-je, que j’ai bien trouvé un homme entre mille; mais pas une femme entre elles toutes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Seulement voici ce que j’ai trouvé; c’est que Dieu a créé l’homme juste; mais ils ont cherché beaucoup de discours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Qui est tel que le sage? et qui sait ce que veulent dire les choses? La sagesse de l’homme fait reluire son visage, et son regard farouche en est changé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Prends garde (je te le dis) à la bouche du Roi, et à la parole du jurement de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Ne te précipite point de te retirer de devant sa face; et ne persévère point en une chose mauvaise; car il fera tout ce qu’il lui plaira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'En quelque lieu qu’est la parole du Roi, là est la puissance; et qui lui dira: Que fais-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Celui qui garde le commandement, ne sentira aucun mal; et le cœur du sage discerne le temps, et ce qui est juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Car dans toute affaire il y a un temps à considérer la justice de la chose, autrement mal sur mal tombe sur l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Car il ne sait pas ce qui arrivera; et même qui est-ce qui lui déclarera quand ce sera?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'L’homme n’est point le maître de son esprit pour le pouvoir retenir; il n’a point de puissance sur le jour de la mort; et il n’y a point de délivrance en une telle guerre; et la méchanceté ne délivrera point son maître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'J’ai vu tout cela, et j’ai appliqué mon cœur à toute oeuvre qui s’est faite sous le soleil. Il y a un temps auquel un homme domine sur l’autre, à son malheur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Et alors j’ai vu les méchants ensevelis, et puis retournés; et ceux qui étaient venus du lieu du Saint, et qui avaient bien fait, être mis en oubli dans la ville. Cela aussi est une vanité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Parce que la sentence contre les mauvaises oeuvres ne s’exécute point incontinent, à cause de cela le cœur des hommes est plein au- dedans d’eux-mêmes d’envie de mal faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'Car le pécheur fait mal cent fois, et Dieu lui donne du délai; mais je connais aussi qu’il sera bien à ceux qui craignent Dieu, et qui révèrent sa face:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'Mais qu’il ne sera pas bien au méchant, et qu’il ne prolongera point ses jours, non plus que l’ombre, parce qu’il ne révère point la face de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Il y a une vanité qui arrive sur la terre, c’est qu’il y a des justes, à qui il arrive selon l’œuvre des méchants; et il y a aussi des méchants, à qui il arrive selon l’œuvre des justes; j’ai dit que cela aussi est une vanité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'C’est pourquoi j’ai prisé la joie, parce qu’il n’y a rien sous le soleil de meilleur à l’homme, que de manger et de boire, et de se réjouir; c’est aussi ce qui lui demeurera de son travail durant les jours de sa vie, que Dieu lui donne sous le soleil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Après avoir appliqué mon cœur à connaître la sagesse, et à regarder les occupations qu’il y a sur la terre, (car même ni jour, ni nuit, l’homme ne donne point de repos à ses yeux.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'Après avoir, dis-je, vu toute l’œuvre de Dieu, et que l’homme ne peut trouver l’œuvre qui se fait sous le soleil, pour laquelle l’homme se travaille en la cherchant, et il ne la trouve point, et même si le sage se propose de la savoir, il ne la peut trouver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Certainement j’ai appliqué mon cœur à tout ceci; et pour éclaircir tout ceci, savoir que les justes et les sages, et leurs faits sont en la main de Dieu; mais les hommes ne connaissent ni l’amour ni la haine de tout ce qui est devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Tout arrive également à tous; un même accident arrive au juste et au méchant; au bon, au net, et au souillé; à celui qui sacrifie, et à celui qui ne sacrifie point; le pécheur est comme l’homme de bien; celui qui jure, comme celui qui craint de jurer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'C’est ici une chose fâcheuse entre toutes celles qui se font sous le soleil, qu’un même accident arrive à tous, et qu’aussi le cœur des hommes est plein de maux, et que des folies occupent leurs cœurs durant leur vie, et après cela ils vont vers les morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Et qui est celui qui leur voudrait être associé? Il y a de l’espérance pour tous ceux qui sont encore vivants: et même un chien vivant vaut mieux qu’un lion mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Certainement les vivants savent qu’ils mourront, mais les morts ne savent rien, et ne gagnent plus rien; car leur mémoire est mise en oubli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Aussi leur amour, leur haine, leur envie a déjà péri, et ils n’ont plus aucune part au monde dans tout ce qui se fait sous le soleil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Va, mange ton pain avec joie, et bois gaiement ton vin; car Dieu a déjà tes oeuvres pour agréables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Que tes vêtements soient blancs en tout temps, et que le parfum ne manque point sur ta tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Vis joyeusement tous les jours de la vie de ta vanité avec la femme que tu as aimée, et qui t’a été donnée sous le soleil pour tous les jours de ta vanité; car c’est là ta portion dans cette vie, et ce qui te revient de ton travail que tu fais sous le soleil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Tout ce que tu auras moyen de faire, fais-le selon ton pouvoir; car au sépulcre, où tu vas, il n’y a ni occupation, ni discours, ni science, ni sagesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Je me suis tourné ailleurs, et j’ai vu sous le soleil que la course n’est point aux légers, ni aux forts la bataille, ni aux sages le pain, ni aux prudents les richesses, ni la grâce aux savants; mais que le temps et l’occasion décident de ce qui arrive à tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Car aussi l’homme même ne connaît point son temps, non plus que les poissons qui sont pris au filet, lequel est mauvais pour eux, et les oiseaux qui sont pris au lacet; car les hommes sont ainsi enlacés par le temps mauvais, lorsqu’il tombe subitement sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'J’ai vu aussi cette sagesse sous le soleil, laquelle m’a semblé grande;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'C’est qu’il y avait une petite ville, et peu de gens dedans, contre laquelle est venu un grand Roi, qui l’a investie, et qui a bâti de grands forts contre elle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Mais il s’est trouvé en elle un homme pauvre, et sage, qui l’a délivrée par sa sagesse; mais nul ne s’est souvenu de cet homme-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Alors j’ai dit: La sagesse vaut mieux que la force, et cependant la sagesse de ce pauvre a été méprisée, et on n’entend point parler de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Les paroles des sages doivent être écoutées plus paisiblement que le cri de celui qui domine entre les fous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Mieux vaut la sagesse que tous les instruments de guerre; et un seul homme pécheur détruit un grand bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Les mouches mortes font puer et bouillonner les parfums du parfumeur; et un peu de folie produit le même effet à l’égard de celui qui est estimé pour sa sagesse, et pour sa gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Le sage a le cœur à sa droite, mais le fou a le coeur à sa gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Et même quand le fou se met en chemin, le sens lui manque; et il dit de chacun: Il est fou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Si l’esprit de celui qui domine s’élève contre toi, ne sors point de ta condition; car la douceur fait pardonner de grandes fautes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Il y a un mal que j’ai vu sous le soleil, comme une erreur qui procède du Prince;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'C’est que la folie est mise aux plus hauts lieux, et que les riches sont assis en un lieu bas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'J’ai vu les serviteurs à cheval, et les Seigneurs aller à pied, comme des serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Celui qui creuse la fosse, y tombera; et celui qui coupe la haie, le serpent le mordra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Celui qui remue des pierres hors de leur place, en sera blessé; et celui qui fend du bois, en sera en danger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Si le fer est émoussé, et qu’on n’en ait point fourbi la lame, il surmontera même la force; mais la sagesse est une adresse excellente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Si le serpent mord sans faire du bruit, le médisant ne vaut pas mieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Les paroles de la bouche du sage ne sont que grâce; mais les lèvres du fou le réduisent à néant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Le commencement des paroles de sa bouche est une folie; et les dernières paroles de sa bouche sont une mauvaise sottise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Or le fou entasse beaucoup de paroles; et toutefois l’homme ne sait point ce qui arrivera; et qui est-ce qui lui déclarera ce qui sera après lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Le travail des fous ne fait que les fatiguer, et pas un d’eux ne sait trouver le chemin pour arriver à la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Malheur à toi, terre, quand ton Roi est jeune, et quand tes Gouverneurs mangent dès le matin!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Que tu es heureuse, ô terre! quand ton Roi est de race illustre, et que tes Gouverneurs mangent quand il en est temps, pour leur réfection, et non par débauche!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'A cause des mains paresseuses le plancher s’affaisse, et à cause des mains lâches, la maison a des gouttières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'On apprête la viande pour se réjouir, et le vin réjouit les vivants; mais l’argent répond de tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Ne dis point mal du Roi, non pas même dans ta pensée; ne dis point aussi mal du riche dans la chambre où tu couches; car les oiseaux des cieux en porteraient la voix, et ce qui vole en porterait les nouvelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Jette ton pain sur la surface des eaux; car avec le temps tu le trouveras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Fais -en part à sept, et même à huit; car tu ne sais point quel mal viendra sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Si les nuées sont pleines, elles répandront la pluie sur la terre; et si un arbre tombe vers le Midi, ou vers le Septentrion, au lieu auquel il sera tombé, il demeurera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Celui qui prend garde au vent, ne sèmera point; et celui qui regarde les nuées, ne moissonnera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Comme tu ne sais point quel est le chemin du vent, ni comment se forment les os dans le ventre de celle qui est enceinte; ainsi tu ne sais pas l’œuvre de Dieu, et comment il fait tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Sème ta semence dès le matin, et ne laisse pas reposer tes mains le soir; car tu ne sais point lequel sera le meilleur, ceci ou cela; et si tous deux seront pareillement bons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Il est vrai que la lumière est douce, et qu’il est agréable aux yeux de voir le soleil;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Mais si l’homme vit beaucoup d’années, et qu’il se réjouisse tout le long de ces années-là, et qu’ensuite il lui souvienne des jours de ténèbres, lesquels seront en grand nombre, tout ce qui lui sera arrivé, sera une vanité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Jeune homme, réjouis-toi en ton jeune âge, et que ton coeur te rende gai aux jours de ta jeunesse, et marche comme ton coeur te mène, et selon le regard de tes yeux; mais sache que pour toutes ces choses Dieu t’amènera en jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'Ôte le chagrin de ton coeur, et éloigne de toi le mal; car le jeune âge et l’adolescence ne sont que vanité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'Mais souviens-toi de ton Créateur aux jours de ta jeunesse, avant que les jours mauvais viennent, et avant que les années arrivent desquelles tu dises: Je n’y prends point de plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'Avant que le soleil, la lumière, la lune et les étoiles s’obscurcissent, et que les nuées viennent l’une sur l’autre après la pluie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'Lorsque les gardes de la maison trembleront, et que les hommes forts se courberont, et que celles qui meulent cesseront, parce qu’elles auront été diminuées; et quand celles qui regardent par les fenêtres, seront obscurcies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'Et quand les deux battants de la porte seront fermés vers la rue, avec abaissement du son de la meule; quand on se lèvera à la voix de l’oiseau, et que toutes les chanteuses seront abaissées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'Quand aussi l’on craindra ce qui est haut, et qu’on tremblera en allant; quand l’amandier fleurira, et quand les cigales se rendront pesantes; et que l’appétit s’en ira, (car l’homme s’en va dans la maison où il demeurera à toujours,) et quand on fera le tour par les rues, en menant deuil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Avant que le câble d’argent se déchaîne, que le vase d’or se débonde, que la cruche se brise sur la fontaine; que la roue se rompe sur la citerne;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Et avant que la poudre retourne en la terre, comme elle y avait été, et que l’esprit retourne à Dieu, qui l’a donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Vanité des vanités, dit l’Ecclésiaste, tout est vanité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Plus l’Ecclésiaste a été sage, plus il a enseigné la science au peuple; il a fait entendre, il a recherché et mis en ordre plusieurs graves sentences.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'L’Ecclésiaste a cherché pour trouver des discours agréables; mais ce qui en a été écrit ici, est la droiture même; ce sont des paroles de vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Les paroles des sages sont comme des aiguillons, et les maîtres qui en ont fait des recueils, sont comme des clous fichés, et ces choses ont été données par un Pasteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Mon fils garde-toi de ce qui est au-delà de ceci; car il n’y a point de fin à faire plusieurs Livres, et tant d’étude n’est que travail qu’on se donne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 15, 'Le but de tout le discours qui a été ouï, c’est: Crains Dieu, et garde ses commandements; car c’est là le tout de l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 16, 'Parce que Dieu amènera toute oeuvre en jugement, touchant tout ce qui est caché, soit bien, soit mal. ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Le Cantique des cantiques, qui est de Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Qu’il me baise des baisers de sa bouche; car tes amours sont plus agréables que le vin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'A cause de l’odeur de tes excellents parfums, ton nom est comme un parfum répandu: c’est pourquoi les filles t’ont aimé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Tire-moi, et nous courrons après toi; lorsque le Roi m’aura introduite dans ses cabinets, nous nous égayerons et nous nous réjouirons en toi; nous célébrerons tes amours plus que le vin; les hommes droits t’ont aimé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Ô filles de Jérusalem, je suis brune, mais de bonne grâce; je suis comme les tentes de Kédar, et comme les courtines de Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Ne prenez pas garde à moi, de ce que je suis brune, car le soleil m’a regardée; les enfants de ma mère se sont mis en colère contre moi, ils m’ont mise à garder les vignes; et je n’ai point gardé la vigne qui était à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Déclare-moi, toi qu’aime mon âme, où tu pais, et où tu fais reposer ton troupeau sur le midi; car pourquoi serais-je comme une femme errante vers les parcs de tes compagnons?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Si tu ne le sais pas, ô la plus belle d’entre les femmes! sors après les traces du troupeau, et pais tes chevrettes près des cabanes des bergers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Ma grande amie, je te compare au plus beau couple de chevaux que j’aie aux chariots de Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Tes joues ont bonne grâce avec les atours, et ton cou avec les colliers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Nous te ferons des atours d’or, avec des boutons d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Tandis que le Roi a été assis à table, mon aspic a rendu son odeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Mon bien-aimé est avec moi comme un sachet de myrrhe; il passera la nuit entre mes mamelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Mon bien-aimé m’est comme une grappe de troëne dans les vignes d’Henguédi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Te voilà belle, ma grande amie, te voilà belle; tes yeux sont comme ceux des colombes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Te voilà beau, mon bien-aimé; que tu es agréable! aussi notre couche est-elle féconde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Les poutres de nos maisons sont de cèdre, et nos soliveaux de sapin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Je suis la rose de Saron, et le muguet des vallées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Tel qu’est le muguet entre les épines, telle est ma grande amie entre les filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Tel qu’est le pommier entre les arbres d’une forêt, tel est mon bien-aimé entre les jeunes hommes; j’ai désiré son ombre, et m’y suis assise, et son fruit a été doux à mon palais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Il m’a menée dans la salle du festin; et sa livrée, laquelle je porte, c’est AMOUR.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Faites-moi revenir les forces avec les liqueurs; faites-moi un lit de pommes; car je me pâme d’amour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Que sa main gauche soit sous ma tête, et que sa droite m’embrasse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Filles de Jérusalem, je vous adjure par les chevreuils et par les biches des champs, que vous ne réveilliez point celle que j’aime, que vous ne la réveilliez point, jusqu’à ce qu’elle le veuille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'C’est ici la voix de mon bien-aimé; le voici qui vient, sautelant sur les montagnes, et bondissant sur les coteaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Mon bien-aimé est semblable au chevreuil, ou au faon des biches; le voilà qui se tient derrière notre muraille; il regarde par les fenêtres, il se fait voir par les treillis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Mon bien-aimé a pris la parole, et m’a dit: Lève-toi, ma grande amie, ma belle, et t’en viens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Car voici, l’hiver est passé, la pluie est passée, elle s’en est allée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Les fleurs paraissent en la terre, le temps des chansons est venu, et la voix de la tourterelle a déjà été ouïe dans notre contrée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Le figuier a poussé ses figons, et les vignes leurs grappes, et elles rendent de l’odeur. Lève-toi, ma grande amie, ma belle, et t’en viens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Ma colombe, qui te tiens dans les fentes de la roche, dans les enfoncements des lieux escarpés, fais-moi voir ton regard, fais-moi ouïr ta voix; car ta voix est douce, et ton regard est gracieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Prenez-nous les renards, et les petits renards, qui gâtent les vignes, depuis que nos vignes ont poussé des grappes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Mon bien-aimé est à moi, et je suis à lui; il paît son troupeau parmi les muguets.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Avant que le vent du jour souffle, et que les ombres s’enfuient, retourne mon bien-aimé, et sois comme le chevreuil, ou le faon des biches, sur les montagnes entrecoupées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'J’ai cherché durant les nuits sur mon lit celui qu’aime mon âme; je l’ai cherché, mais je ne l’ai point trouvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Je me lèverai maintenant, et je ferai le tour de la ville, des carrefours et des places, et je chercherai celui qu’aime mon âme. Je l’ai cherché, mais je ne l’ai point trouvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Le guet, qui faisait la ronde par la ville, m’a trouvée. N’avez- vous point vu, leur ai-je dit, celui qu’aime mon âme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'A peine les avais-je passés, que je trouvai celui qu’aime mon âme; je le pris, et je ne le lâcherai point que je ne l’aie amené à la maison de ma mère, et dans la chambre de celle qui m’a conçue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Filles de Jérusalem, je vous adjure par les chevreuils et par les biches des champs, que vous ne réveilliez point celle que j’aime, que vous ne la réveilliez point, jusqu’à ce qu’elle le veuille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Qui est celle-ci qui monte du désert, comme des colonnes de fumée en forme de palmiers, parfumée de myrrhe et d’encens, et de toute sorte de poudre de parfumeur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Voici le lit de Salomon, autour duquel il y a soixante vaillants hommes, des plus vaillants d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'tous maniant l’épée, et très-bien dressés à la guerre, ayant chacun son épée sur sa cuisse à cause des frayeurs de la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Le Roi Salomon s’est fait un lit de bois du Liban.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Il a fait ses piliers d’argent et l’intérieur d’or, son ciel d’écarlate, et au milieu il a placé celle qu’il aime entre les filles de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Sortez, filles de Sion, et regardez le Roi Salomon, avec la couronne dont sa mère l’a couronné au jour de ses épousailles, et au jour de la joie de son coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Te voilà belle, ma grande amie, te voilà belle; tes yeux sont comme ceux des colombes entre tes tresses; tes cheveux sont comme le poil d’un troupeau de chèvres lesquelles on tond, lorsqu’elles sont descendues de la montagne de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Tes dents sont comme un troupeau de brebis tondues, qui remontent du lavoir, et qui sont toutes deux à deux, et il n’y en a pas une qui manque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Tes lèvres sont comme un fil teint en écarlate. Ton parler est gracieux; ta tempe est comme une pièce de pomme de grenade au dedans de tes tresses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Ton cou est comme la tour de David, bâtie à créneaux, à laquelle pendent mille boucliers, et toutes les grands boucliers des vaillants hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Tes deux mamelles sont comme deux faons jumeaux d’une chevrette, qui paissent parmi le muguet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Avant que le vent du jour souffle, et que les ombres s’enfuient, je m’en irai à la montagne de myrrhe, et au coteau d’encens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Tu es toute belle, ma grande amie, et il n’ y a point de tache en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Viens du Liban avec moi, mon Epouse, viens du Liban avec moi; regarde du sommet d’Amana, du sommet de Senir et de Hermon, des repaires des lions, et des montagnes des léopards.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Tu m’as ravi le coeur, ma soeur, mon Epouse; tu m’as ravi le coeur, par l’un de tes yeux, et par l’un des colliers de ton cou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Combien sont belles tes amours, ma soeur, mon épouse? combien sont tes amours meilleures que le vin? et l’odeur de tes parfums plus qu’aucune drogue aromatique?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Tes lèvres, mon Epouse, distillent des rayons de miel; le miel et le lait sont sous ta langue, et l’odeur de tes vêtements est comme l’odeur du Liban.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Ma soeur, mon Epouse, tu es un jardin clos, une source close; et une fontaine cachetée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Tes rejetons sont un parc de grenadiers, avec des fruits délicieux, de troëne, avec l’aspic;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'l’aspic et le safran, la canne odoriférante et le cinnamome, avec tout arbre d’encens; la myrrhe et l’aloès, avec toutes les principales drogues aromatiques.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Ô fontaine des jardins! ô puits d’eau vive! et ruisseaux coulant du Liban.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Lève-toi bise, et viens, vent du Midi, souffle dans mon jardin; afin que ses drogues aromatiques distillent. Que mon bien-aimé vienne en son jardin, et qu’il mange de ses fruits délicieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Je suis venu dans mon jardin, ma soeur, mon épouse; j’ai cueilli ma myrrhe, avec mes drogues aromatiques; j’ai mangé mes rayons de miel, et mon miel; j’ai bu mon vin et mon lait; Mes amis, mangez, buvez; faites bonne chère, mes bien-aimés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'J’étais endormie, mais mon coeur veillait; et voici la voix de mon bien-aimé qui heurtait, en disant: Ouvre-moi, ma soeur, ma grande amie, ma colombe, ma parfaite; car ma tête est pleine de rosée; et mes cheveux de l’humidité de la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'J’ai dépouillé ma robe, lui dis-je, comment la revêtirais-je? J’ai lavé mes pieds, comment les souillerais-je?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Mon bien-aimé a avancé sa main par le trou de la porte, et mes entrailles ont été émues à cause de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Je me suis levée pour ouvrir à mon bien-aimé, et la myrrhe a distillé de mes mains, et la myrrhe franche de mes doigts, sur les garnitures du verrou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'J’ai ouvert à mon bien-aimé, mais mon bien-aimé s’était retiré, il avait passé; mon âme se pâma de l’avoir ouï parler; je le cherchai, mais je ne le trouvai point; je l’appelai, mais il ne me répondit point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Le guet qui faisait la ronde par la ville me trouva, ils me battirent, ils me blessèrent; les gardes des murailles m’ôtèrent mon voile de dessus moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Filles de Jérusalem, je vous adjure, si vous trouvez mon bien-aimé, que vous lui rapportiez; et quoi? Que je me pâme d’amour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Qu’est-ce de ton bien-aimé plus que d’un autre, ô la plus belle d’entre les femmes? Qu’est-ce de ton bien-aimé plus que d’un autre, que tu nous aies ainsi conjurées?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Mon bien-aimé est blanc et vermeil, un porte-enseigne choisi entre dix mille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Sa tête est un or très-fin; ses cheveux sont crépus, noirs comme un corbeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Ses yeux sont comme ceux des colombes sur les ruisseaux des eaux courantes, lavés dans du lait, et comme enchâssés dans des chatons d’ anneau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Ses joues sont comme un carreau de drogues aromatiques, et comme des fleurs parfumées, ses lèvres sont comme du muguet; elles distillent la myrrhe franche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Ses mains sont comme des anneaux d’or, où il y a des chrysolithes enchâssées; son ventre est comme d’un ivoire bien poli, couvert de saphirs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Ses jambes sont comme des piliers de marbre, fondés sur des soubassements de fin or; son port est comme le Liban; il est exquis comme les cèdres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Son palais n’est que douceur; tout ce qui est en lui est aimable. Tel est mon bien-aimé, tel est mon ami, filles de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Où est allé ton bien-aimé, ô la plus belle des femmes? De quel côté est allé ton bien-aimé, et nous le chercherons avec toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Mon bien-aimé est descendu dans son verger, aux carreaux des drogues aromatiques, pour paître son troupeau dans les vergers, et cueillir du muguet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Je suis à mon bien-aimé, et mon bien-aimé est à moi; il paît son troupeau parmi le muguet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Ma grande amie, tu es belle comme Tirtsa, agréable comme Jérusalem, redoutable comme des armées qui marchent à enseignes déployées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Détourne tes yeux qu’ils ne me regardent; car ils me forcent; Tes cheveux sont comme un troupeau de chèvres qu’on tond lorsqu’elles sont descendues de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Tes dents sont comme un troupeau de brebis qui remontent du lavoir, et qui sont toutes deux à deux, et il n’y en a pas une qui manque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Ta tempe est comme une pièce de pomme de grenade au dedans de tes tresses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Qu’il y ait soixante Reines, et quatre-vingts concubines, et des vierges sans nombre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Ma colombe, ma parfaite, est unique; elle est unique à sa mère, à celle qui l’a enfantée; les filles l’ont vue, et l’ont dite bienheureuse; les Reines et les concubines l’ont louée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Qui est celle-ci qui paraît comme l’aube du jour, belle comme la lune, brillante comme le soleil, redoutable comme des armées qui marchent à enseignes déployées?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Je suis descendu au verger des noyers, pour voir les fruits de la vallée qui mûrissent, et pour voir si la vigne s’avance, et si les grenadiers ont poussé leur fleur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Je ne me suis point aperçu que mon affection m’a rendu semblable aux chariots d’Haminadab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, 'Reviens, reviens, ô Sulamite! reviens, reviens, et que nous te contemplions. Que contempleriez-vous en la Sulamite? Comme une danse de deux bandes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Fille de Prince, combien sont belles tes démarches, avec ta chaussure! Le tour de tes hanches est comme des colliers travaillés de la main d’un excellent ouvrier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Ton nombril est comme une tasse ronde, toute comble de breuvage, ton ventre est comme un tas de blé entouré de muguet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Tes deux mamelles sont comme deux faons jumeaux d’une chevrette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Ton cou est comme une tour d’ivoire; tes yeux sont comme les viviers qui sont en Hesbon, près de la porte de Bathrabbim; ton visage est comme la tour du Liban qui regarde vers Damas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Ta tête est sur toi comme du cramoisi, et les cheveux fins de ta tête sont comme de l’écarlate; Le Roi est attaché aux galeries pour te contempler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Que tu es belle, et que tu es agréable, amour délicieuse!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Ta taille est semblable à un palmier, et tes mamelles à des grappes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'J’ai dit: Je monterai sur le palmier, et j’empoignerai ses branches? et tes mamelles me seront maintenant comme des grappes de vigne; et l’odeur de ton visage, comme l’odeur des pommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Et ton palais comme le bon vin qui coule en faveur de mon bien- aimé, et qui fait parler les lèvres des dormants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Je suis à mon bien-aimé, et son désir est vers moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Viens, mon bien-aimé, sortons aux champs, passons la nuit aux villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Levons-nous dès le matin pour aller aux vignes, et voyons si la vigne est avancée, et si la grappe est formée, et si les grenadiers sont fleuris; là je te donnerai mes amours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Les mandragores jettent leur odeur, et à nos portes il y a de toutes sortes de fruits exquis, des fruits nouveaux, et des fruits gardés, que je t’ai conservés, ô mon bien-aimé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Plût à Dieu que tu me fusses comme un frère qui a sucé les mamelles de ma mère! je t’irais trouver dehors, je te baiserais, et on ne m’en mépriserait point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Je t’amènerais, je t’introduirais dans la maison de ma mère, tu m’enseignerais, et je te ferais boire du vin mixtionné d’aromates, et du moût de mon grenadier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Que sa main gauche soit sous ma tête, et que sa droite m’embrasse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Je vous adjure, Filles de Jérusalem, que vous ne réveilliez point celle que j’aime, que vous ne la réveilliez point, jusqu’à ce qu’elle le veuille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Qui est celle-ci qui monte du désert, mollement appuyée sur son bien-aimé? Je t’ai réveillée sous un pommier, là où ta mère t’a enfantée, là où celle qui t’a conçue, t’a enfanté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Mets-moi comme un cachet sur ton coeur, comme un cachet sur ton bras; car l’amour est fort comme la mort, et la jalousie est cruelle comme le sépulcre; leurs embrasements sont des embrasements de feu, et une flamme très-véhémente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Beaucoup d’eaux ne pourraient point éteindre cet amour-là, et les fleuves mêmes ne le pourraient pas noyer; si quelqu’un donnait tous les biens de sa maison pour cet amour, certainement on n’en tiendrait aucun compte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Nous avons une petite soeur qui n’a pas encore de mamelles; que ferons nous à notre soeur le jour qu’on parlera d’elle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Si elle est comme une muraille, nous bâtirons sur elle un palais d’argent; et si elle est comme une porte, nous la renforcerons d’un entablement de cèdre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Je suis comme une muraille, et mes mamelles sont comme des tours; j’ai été alors si favorisée de lui, que j’ai trouvé la paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Salomon a eu une vigne en Bahalhamon, qu’il a donnée à des gardes, et chacun d’eux en doit apporter pour son fruit mille pièces d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Ma vigne, qui est à moi, est à mon commandement: Ô Salomon, que les mille pièces d’argent soient à toi, et qu’il y en ait deux cents pour les gardes du fruit de la vigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Ô toi qui habites dans les jardins, les amis sont attentifs à ta voix; fais que je l’entende.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Mon bien-aimé, fuis-t’en aussi vite qu’un chevreuil, ou qu’un faon de biche, sur les montagnes des drogues aromatiques. ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'La vision d’Esaïe, fils d’Amots, laquelle il a vue touchant Juda et Jérusalem, aux jours de Hozias, de Jotham, d’Achas, et d’Ezéchias, Rois de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Cieux écoutez, et toi Terre prête l’oreille, car l’Eternel a parlé, disant; j’ai nourri des enfants, je les ai élevés, mais ils se sont rebellés contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Le boeuf connaît son possesseur, et l’âne la crèche de son maître; mais Israël n’a point de connaissance, mon peuple n’a point d’intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Ha! nation pécheresse, peuple chargé d’iniquité, race de gens malins, enfants qui ne font que se corrompre; ils ont abandonné l’Eternel, ils ont irrité par leur mépris le Saint d’Israël, ils se sont retirés en arrière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Pourquoi seriez-vous encore battus? vous ajouterez la révolte; toute tête est en douleur, et tout coeur est languissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Depuis la plante du pied jusqu’à la tête il n’y a rien d’entier en lui; il n’y a que blessure, meurtrissure, et plaie pourrie, qui n’ont point été nettoyées, ni bandées, et dont aucune n’a été adoucie d’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Votre pays n’est que désolation, et vos villes sont en feu; les étrangers dévorent votre terre en votre présence, et cette désolation est comme un bouleversement fait par des étrangers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Car la fille de Sion restera comme une cabane dans une vigne; comme une loge dans un champ de concombres; comme une ville serrée de près.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Si l’Eternel des armées ne nous eût laissé des gens de reste, qui sont même bien peu, nous eussions été comme Sodome, nous eussions été semblables à Gomorrhe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Ecoutez la parole de l’Eternel, Conducteurs de Sodome, prêtez l’oreille à la Loi de notre Dieu, peuple de Gomorrhe!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Qu’ai-je à faire, dit l’Eternel, de la multitude de vos sacrifices? je suis rassasié d’holocaustes de moutons, et de la graisse de bêtes grasses, je ne prends point de plaisir au sang des taureaux, ni des agneaux, ni des boucs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Quand vous entrez pour vous présenter devant ma face; qui a requis cela de vos mains, que vous fouliez de vos pieds mes parvis?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Ne continuez plus à m’apporter des oblations de néant; le parfum m’est en abomination; quant aux nouvelles Lunes, et aux Sabbats, et à la publication de vos convocations, je n’en puis plus supporter l’ennui, ni de vos assemblées solennelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Mon âme hait vos nouvelles Lunes, et vos fêtes solennelles; elles me sont fâcheuses, je suis las de les supporter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'C’est pourquoi quand vous étendrez vos mains, je cacherai mes yeux de vous, et quand vous multiplierez vos prières, je ne les exaucerai point; vos mains sont pleines de sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Lavez-vous, nettoyez-vous, ôtez de devant mes yeux la malice de vos actions; cessez de mal faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Apprenez à bien faire; recherchez la droiture; redressez celui qui est foulé, faites justice à l’orphelin, défendez la cause de la veuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Venez maintenant, dit l’Eternel, et débattons nos droits; quand vos péchés seraient comme le cramoisi, ils seront blanchis comme la neige; et quand ils seraient rouges comme le vermillon, ils seront blanchis comme la laine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Si vous obéissez volontairement, vous mangerez le meilleur du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Mais si vous refusez d’obéir, et si vous êtes rebelles, vous serez consumés par l’épée; car la bouche de l’Eternel a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Comment s’est prostituée la cité fidèle? elle était pleine de droiture, et la justice logeait en elle, mais maintenant elle est pleine de meurtriers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Ton argent est devenu de l’écume, et ton breuvage est mêlé d’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Les Principaux de ton peuple sont revêches, et compagnons de larrons; chacun d’eux aime les présents, ils courent après les récompenses; ils ne font point droit à l’orphelin, et la cause de la veuve ne vient point devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'C’est pourquoi le Seigneur, l’Eternel des armées, le Puissant d’Israël dit; Ha! je me satisferai en punissant mes adversaires, et je me vengerai de mes ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Et je remettrai ma main sur toi, et je refondrai au net ton écume, et j’ôterai tout ton étain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'Mais je rétablirai tes Juges, tels qu’ ils étaient la première fois, et tes Conseillers, tels que du commencement; et après cela on t’appellera, Cité de justice, ville fidèle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Sion sera rachetée par le jugement, et ceux qui y retourneront seront rachetés par la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Mais les rebelles, et les pécheurs seront froissés ensemble; et ceux qui ont abandonné l’Eternel, seront consumés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Car on sera honteux à cause des chênes que vous avez désirés; et vous rougirez à cause des jardins que vous avez choisis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Car vous serez comme le chêne dont la feuille tombe, et comme le jardin qui n’a point d’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'Et le fort sera de l’étoupe, et son oeuvre une étincelle; et tous deux brûleront ensemble, et il n’y aura personne qui éteigne le feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'La parole qu’Esaïe fils d’Amots a vue touchant Juda et Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Or il arrivera aux derniers jours que la montagne de la maison de l’Eternel sera affermie au sommet des montagnes, et qu’elle sera élevée par-dessus les coteaux, et toutes les nations y aborderont.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Et plusieurs peuples iront, et diront; venez, et montons à la montagne de l’Eternel, à la maison du Dieu de Jacob; et il nous instruira de ses voies, et nous marcherons dans ses sentiers; car la Loi sortira de Sion, et la parole de l’Eternel sortira de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Il exercera le jugement parmi les nations, et il reprendra plusieurs peuples; ils forgeront de leurs épées des hoyaux, et de leurs hallebardes des serpes; une nation ne lèvera plus l’épée contre l’autre, et ils ne s’adonneront plus à la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Venez, ô Maison de Jacob! et marchons dans la lumière de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Certes tu as rejeté ton peuple, la maison de Jacob, parce qu’ils se sont remplis d’Orient, et de pronostiqueurs, comme les Philistins; et qu’ils se sont plu aux enfants des étrangers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Son pays a été rempli d’argent et d’or, et il n’y a point eu de fin à ses trésors; son pays a été rempli de chevaux, et il n’ y a point eu de fin à ses chariots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Son pays a été rempli d’idoles; ils se sont prosternés devant l’ouvrage de leurs mains, devant ce que leurs doigts ont fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Et ceux du commun se sont inclinés, et les personnes de qualité se sont baissées; ne leur pardonne donc point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Entre dans la roche, et te cache dans la poudre, à cause de la frayeur de l’Eternel, et à cause de la gloire de sa majesté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Les yeux hautains des hommes seront abaissés, et les hommes qui s’élèvent seront humiliés, et l’Eternel sera seul haut élevé en ce jour-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Car il y a un jour assigné par l’Eternel des armées contre tout orgueilleux et hautain, et contre tout homme qui s’élève, et il sera abaissé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'Et contre tous les cèdres du Liban hauts et élevés, et contre tous les chênes de Basan;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'Et contre toutes les hautes montagnes, et contre tous les coteaux élevés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'Et contre toute haute tour, et contre toute muraille forte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'Et contre tous les navires de Tarsis, et contre toutes les peintures de plaisance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Et l’élévation des hommes sera humiliée, et les hommes qui s’élèvent seront abaissés; et l’Eternel sera seul haut élevé en ce jour-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Et quant aux idoles, elles tomberont toutes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Et les hommes entreront aux cavernes des rochers, et aux trous de la terre, à cause de la frayeur de l’Eternel, et à cause de sa gloire magnifique, lorsqu’il se lèvera pour châtier la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'En ce jour-là l’homme jettera aux taupes et aux chauves-souris les idoles de son argent, et les idoles de son or, qu’on lui aura faites pour se prosterner devant elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'Et ils entreront dans les fentes des rochers, et dans les quartiers des rochers à cause de la frayeur de l’Eternel, et à cause de sa gloire magnifique, quand il se lèvera pour punir la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Retirez-vous de l’homme duquel le souffle est dans ses narines; car quel cas mérite-t-il qu’on en fasse?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Car voici, le Seigneur, l’Eternel des armées, s’en va ôter de Jérusalem et de Juda le soutien et l’appui, tout soutien de pain, et tout soutien d’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'L’homme fort, et l’homme de guerre, le juge et le Prophète, l’homme éclairé sur l’avenir, et l’ancien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Le cinquantenier, et l’homme d’autorité, le conseiller, et l’expert entre les artisans, et le bien-disant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Et je leur donnerai de jeunes gens pour gouverneurs, et des enfants domineront sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Et le peuple sera rançonné l’un par l’autre, et chacun par son prochain. L’enfant se portera arrogamment contre le vieillard, et l’homme abject contre l’honorable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Même un homme prendra son frère de la maison de son père, et lui dira; tu as un manteau, sois notre conducteur, et que cette dissipation-ci soit sous ta conduite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Et celui-là lèvera la main en ce jour-là, en disant; je ne saurais y remédier, et en ma maison il n’y a ni pain ni manteau; ne me faites point donc conducteur du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Certes Jérusalem est renversée, et Juda est tombé; parce que leur langue et leurs actions sont contre l’Eternel, pour irriter les yeux de sa gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Ce qu’ils montrent sur leur visage rend témoignage contr’eux, ils ont publié leur péché comme Sodome, et ne l’ont point célé; malheur à leur âme, car ils ont attiré le mal sur eux!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Dites au juste, que bien lui sera: car les justes mangeront le fruit de leurs oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Malheur au méchant qui ne cherche qu’à faire mal; car la rétribution de ses mains lui sera faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Quant à mon peuple, les enfants sont ses prévôts, et les femmes dominent sur lui. Mon peuple, ceux qui te guident, te font égarer, et t’ont fait perdre la route de tes chemins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'L’Eternel se présente pour plaider, il se tient debout pour juger les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'L’Eternel entrera en jugement avec les Anciens de son peuple, et avec ses Principaux; car vous avez consumé la vigne, et ce que vous avez ravi à l’affligé est dans vos maisons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Que vous revient-il de fouler mon peuple, et d’écraser le visage des affligés? dit le Seigneur, l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'L’Eternel a dit aussi; parce que les filles de Sion se sont élevées, et ont marché la gorge découverte, et faisant signe des yeux, et qu’elles ont marché avec une fière démarche faisant du bruit avec leurs pieds,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'L’Eternel rendra chauve le sommet de la tête des filles de Sion, et l’Eternel découvrira leur nudité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'En ce temps-là le Seigneur ôtera l’ornement des sonnettes, et les agrafes, et les boucles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'Les petites boîtes, et les chaînettes, et les papillotes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'Les atours, et les jarretières, et les rubans, et les bagues à senteur, et les oreillettes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'Les anneaux, et les bagues qui leur pendent sur le nez;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'Les mantelets, et les capes, et les voiles, et les poinçons,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'Et les miroirs, et les crêpes, et les tiares, et les couvre-chefs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Et il arrivera qu’au lieu de senteurs aromatiques, il y aura de la puanteur; et au lieu d’être ceintes, elles seront découvertes, et au lieu de cheveux frisés, elles auront la tête chauve; et au lieu de ceintures de cordon, elles seront ceintes de cordes de sac; et au lieu d’un beau teint, elles auront le teint tout hâlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Tes gens tomberont par l’épée, et ta force par la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Et ses portes se plaindront, et mèneront deuil; et elle sera vidée, et gisante par terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Et en ce temps-là sept femmes prendront un homme seul, en disant; nous mangerons notre pain, et nous nous vêtirons de nos habits; seulement que ton nom soit réclamé sur nous; ôte notre opprobre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'En ce temps-là le Germe de l’Eternel sera plein de noblesse et de gloire, et le fruit de la terre plein de grandeur et d’excellence, pour ceux qui seront réchappés d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Et il arrivera que celui qui sera resté dans Sion, et qui sera demeuré de reste dans Jérusalem, sera appelé Saint; et ceux qui seront dans Jérusalem seront tous marqués pour vivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Quand le Seigneur aura lavé la souillure des filles de Sion, et qu’il aura essuyé le sang de Jérusalem du milieu d’elle, en esprit de jugement, et en esprit de consomption par le feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Aussi l’Eternel créera sur toute l’étendue du mont de Sion, et sur ses assemblées, une nuée de jour avec une fumée, et une splendeur de feu flamboyant de nuit; car la gloire se répandra partout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'Et il y aura de jour une cabane pour donner de l’ombre contre la chaleur, et pour servir de refuge et d’asile contre la tempête et la pluie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Je chanterai maintenant pour mon ami le Cantique de mon Bien-aimé, touchant sa vigne. Mon ami avait une vigne en un coteau d’un lieu gras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Et il l’environna d’une haie, et en ôta les pierres, et la planta de ceps exquis; il bâtit aussi une tour au milieu d’elle, et y tailla une cuve; or il s’attendait qu’elle produirait des raisins, mais elle a produit des grappes sauvages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Maintenant donc vous habitants de Jérusalem, et vous hommes de Juda, jugez, je vous prie, entre moi et ma vigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Qu’y avait-il plus à faire à ma vigne que je ne lui aie fait? pourquoi ai-je attendu qu’elle produisît des raisins, et elle a produit des grappes sauvages?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Maintenant donc que je vous fasse entendre, je vous prie, ce que je m’en vais faire à ma vigne: J’ôterai sa haie, et elle sera broutée; je romprai sa cloison, et elle sera foulée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Et je la réduirai en désert, elle ne sera plus taillée ni fossoyée, et les ronces et les épines y croîtront; et je commanderai aux nuées qu’elles ne fassent plus tomber de pluie sur elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Or la maison d’Israël est la vigne de l’Eternel des armées, et les hommes de Juda sont la plante en laquelle il prenait plaisir; il en a attendu la droiture, et voici le saccagement; la justice, et voici la clameur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Malheur à ceux qui joignent maison à maison, et qui approchent un champ de l’autre, jusques à ce qu’il n’y ait plus d’espace, et que vous vous rendiez seuls habitants du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'L’Eternel des armées me fait entendre, disant: Si des maisons vastes ne sont réduites en désolation, et si les grandes et les belles maisons ne sont sans habitants?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Même dix journaux de vigne ne feront qu’un Bath, et la semence d’un Homer ne fera qu’un Epha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Malheur à ceux qui se lèvent de bon matin, qui recherchent la cervoise, qui demeurent jusqu’au soir, et jusqu’à ce que le vin les échauffe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'La harpe, la musette, le tambour, la flûte, et le vin sont dans leurs festins; et ils ne regardent point l’oeuvre de l’Eternel, et ne voient point l’ouvrage de ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Mon peuple est emmené captif, parce qu’il n’a point eu de connaissance; et les plus honorables d’entr’eux sont des pauvres, morts de faim, et leur multitude est asséchée de soif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'C’est pourquoi le sépulcre s’est élargi, et a ouvert sa gueule sans mesure; et sa magnificence y descendra, sa multitude, sa pompe, et ceux qui s’y réjouissent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Ceux du commun seront humiliés, et les personnes de qualité seront abaissées, et les yeux des hautains seront abaissés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Et l’Eternel des armées sera haut élevé en jugement, et le Dieu Fort, le Saint sera sanctifié dans la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Les agneaux paîtront selon qu’ils seront parqués, et allant d’un lieu à l’autre, ils mangeront les déserts où le bétail devenait gras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Malheur à ceux qui tirent l’iniquité avec des câbles de vanité; et le péché, comme avec des cordages de chariot;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'Qui disent; qu’il se hâte, et qu’il fasse venir son oeuvre bientôt, afin que nous le voyions; et que le conseil du Saint d’Israël s’avance, et qu’il vienne; et nous saurons ce que c’est.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Malheur à ceux qui appellent le mal, bien, et le bien, mal; qui font les ténèbres, lumière, et la lumière, ténèbres; qui font l’amer, doux, et le doux, amer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Malheur à ceux qui sont sages à leurs yeux, et intelligents en se considérant eux-mêmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Malheur à ceux qui sont puissants à boire le vin, et vaillants à avaler la cervoise;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'Qui justifient le méchant pour des présents, et qui ôtent à chacun des justes sa justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'C’est pourquoi comme le flambeau de feu consume le chaume, et la flamme consume la balle, ils seront ainsi consumés; leur racine sera comme la pourriture, et leur fleur sera détruite comme la poussière, parce qu’ils ont rebuté la Loi de l’Eternel des armées, et rejeté par mépris la parole du Saint d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'C’est pourquoi la colère de l’Eternel s’est embrasée contre son peuple, et il a étendu sa main sur lui, et l’a frappé; et les montagnes en ont croulé, et leurs corps morts ont été mis en pièces au milieu des rues. Malgré tout cela il n’a point fait cesser sa colère, mais sa main est encore étendue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Et il élèvera l’enseigne vers les nations éloignées, et sifflera à chacune d’elles depuis les bouts de la terre; et voici chacune viendra promptement et légèrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Il n’y aura pas un d’eux qui soit las, ni qui bronche, ni qui sommeille, ni qui dorme, et la ceinture de leurs reins ne sera point déliée, et la courroie de leur soulier ne sera point rompue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Leurs flèches seront aiguës, et tous leurs arcs tendus; les cornes des pieds de leurs chevaux seront tout comme autant de cailloux, et les roues de leurs chariots comme un tourbillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Leur rugissement sera comme celui du vieux lion, ils rugiront comme des lionceaux; ils bruiront, et raviront la proie; ils l’emporteront, et il n’y aura personne qui la leur ôte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'En ce temps-là on mènera un bruit sur lui, semblable au bruit de la mer, et il regardera vers la terre, mais voici il y aura des ténèbres, et la calamité viendra avec la lumière; il y aura des ténèbres au ciel sur elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'L’année en laquelle mourut le Roi Hozias, je vis le Seigneur séant sur un trône haut et élevé, et ses pans remplissaient le Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Les Séraphins se tenaient au-dessus de lui, et chacun d’eux avait six ailes; de deux ils couvraient leur face, et de deux ils couvraient leurs pieds, et de deux ils volaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Et ils criaient l’un à l’autre, et disaient: Saint, Saint, Saint est l’Eternel des armées; tout ce qui est dans toute la terre est sa gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Et les poteaux des seuils furent ébranlés par la voix de celui qui criait; et la maison fut remplie de fumée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Alors je dis; Hélas moi! car c’est fait de moi, parce que je suis un homme souillé de lèvres, et que je demeure parmi un peuple souillé de lèvres; et mes yeux ont vu le Roi, l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Mais l’un des Séraphins vola vers moi, tenant en sa main un charbon vif, qu’il avait pris de dessus l’autel avec des pincettes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Et il en toucha ma bouche, et dit; voici, ceci a touché tes lèvres, c’est pourquoi ton iniquité sera ôtée, et la propitiation sera faite pour ton péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Puis j’ouïs la voix du Seigneur, disant; qui enverrai-je, et qui ira pour nous? et je dis; me voici, envoie-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Et il dit; va, et dis à ce peuple; En entendant vous entendrez, mais vous ne comprendrez point; et en voyant vous verrez, mais vous n’apercevrez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Engraisse le cœur de ce peuple, et rends ses oreilles pesantes, et bouche ses yeux; de peur qu’il ne voie de ses yeux, et qu’il n’entende de ses oreilles, et que son cœur ne comprenne, et qu’il ne se convertisse, et qu’il ne recouvre la santé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Et je dis; jusques-à quand, Seigneur? et il répondit: Jusques-à ce que les villes aient été désolées, et qu’il n’y ait plus d’habitants, ni d’homme dans les maisons, et que la terre soit mise en une entière désolation;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'Et que l’Eternel ait dispersé au loin les hommes, et que celle qu’il aura abandonnée ait demeuré longtemps au milieu du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Toutefois il y en aura encore en elle une dizaine, puis elle sera derechef broutée; mais comme la fermeté des chênes et des rouvres consiste en ce qu’ils rejettent, ainsi la semence sainte sera la fermeté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Or il avint aux jours d’Achaz fils de Jotham, fils d’Hozias Roi de Juda, que Retsin Roi de Syrie, et Pékach fils de Rémalja Roi d’Israël, montèrent contre Jérusalem pour lui faire la guerre; mais ils ne la purent forcer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Et on rapporta à la maison de David, en disant; La Syrie s’est reposée sur Ephraïm. Et le cœur d’Achaz, et le cœur de son peuple fut ébranlé, comme les arbres des forêts sont ébranlés par le vent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Alors l’Eternel dit à Esaïe; Sors maintenant au-devant d’Achaz, toi, et Séar-Jasub ton fils, vers le bout du conduit du haut étang, vers le grand chemin du champ du foulon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'Et lui dis; prends garde à toi, et demeure tranquille; ne crains point, et que ton cœur ne devienne point lâche à cause des deux queues de ces tisons fumants, à cause, dis-je, de l’ardeur de la colère de Retsin et de la Syrie, et du fils de Rémalja.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'De ce que la Syrie a délibéré avec Ephraïm et le fils de Rémalja de te faire du mal, en disant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Montons en Judée, et la réveillons, et nous y faisons ouverture, partageons-la entre nous, et établissons pour Roi le fils de Tabéal, au milieu d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Ainsi a dit le Seigneur, l’Eternel; cela n’aura point d’effet, et ne se fera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Car la Capitale de la Syrie c’est Damas, et le Chef de Damas c’est Retsin; et dans soixante-cinq ans Ephraïm sera froissé pour n’être plus un peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Et la Capitale d’Ephraïm c’est Samarie; et le Chef de Samarie c’est le fils de Rémalja, et si vous ne croyez ceci, certainement vous ne serez point affermis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Et l’Eternel continua de parler avec Achaz, en disant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Demande un signe pour toi, de l’Eternel ton Dieu, demande -le, soit au plus bas lieu, soit dans le plus haut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Et Achaz dit; je n’en demanderai point, et je ne tenterai point l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Alors Esaïe dit; ecoutez maintenant, ô Maison de David! Vous est-ce peu de chose de travailler les hommes, que vous travailliez aussi mon Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'C’est pourquoi le Seigneur lui-même vous donnera un signe; voici, une Vierge sera enceinte, et elle enfantera un fils, et appellera son Nom EMMANUEL;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Il mangera du beurre et du miel, jusques à ce qu’il sache rejeter le mal, et choisir le bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Mais avant que l’enfant sache rejeter le mal, et choisir le bien, la terre que tu as en détestation, sera abandonnée par ses deux Rois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'L’Eternel fera venir sur toi, et sur ton peuple, et sur la maison de ton père, par le Roi d’Assur, des jours tels qu’il n’y en a point eu de semblables depuis le jour qu’Ephraïm se sépara de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Et il arrivera qu’en ce jour-là, l’Eternel sifflera aux mouches qui sont au bout des ruisseaux d’Egypte, et aux abeilles qui sont au pays d’Assur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'Et elles viendront, et se poseront toutes dans les vallées désertes, et dans les trous des rochers, et par tous les buissons, et par tous les halliers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'Et ce jour-là, le Seigneur rasera avec le rasoir pris à louage au delà du fleuve, savoir avec le Roi d’Assur, la tête et les poils des pieds, et il achèvera aussi la barbe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'Et il arrivera en ce temps-là qu’un homme nourrira une vache et deux brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'Mais il arrivera que pour l’abondance du lait qu’elles rendront, il mangera du beurre; car tout homme qui sera demeuré de reste dans le pays, mangera du beurre et du miel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Et il arrivera en ce jour-là que tout lieu où il y aura eu mille vignes, de mille pièces d’argent, sera réduit en ronces et en épines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'On y entrera avec des flèches et avec l’arc, car tout le pays ne sera que ronces et épines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Et dans toutes les montagnes qu’on essartait avec la serpe, là on ne craindra plus de voir des ronces et des épines, mais ce sera pour y jeter les bœufs, et pour être foulé des brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Et l’Eternel me dit; Prends-toi un grand rouleau, et y écris avec une touche, en grosses lettres; QU’ON SE DEPECHE DE BUTINER; IL HATE LE PILLAGE.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'De quoi je pris avec moi des fidèles témoins, savoir Urie le Sacrificateur, et Zacharie fils de Jébéréchia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Puis je m’approchai de la Prophétesse, laquelle conçut, et enfanta un fils; et l’Eternel me dit; appelle son nom Mahersalal-has-baz.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Car avant que l’enfant sache crier, mon père! et ma mère! on enlèvera la puissance de Damas, et le butin de Samarie, devant le Roi d’Assur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Et l’Eternel continua encore de me parler, en disant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Parce que ce peuple a rejeté les eaux de Siloé qui vont doucement, et qu’il s’est réjoui de Retsin, et du fils de Rémalja;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'Pour cette cause, voici, le Seigneur s’en va faire venir sur eux les eaux du fleuve, fortes, et grosses, savoir le Roi d’Assur, et toute sa gloire, et ce fleuve montera par-dessus tous ses courants d’eau, et ira par-dessus tous ses bords.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'Et il traversera en Juda, et se débordera, et passera tellement qu’il atteindra jusqu’au cou; et les étendues de ses ailes rempliront la largeur de ton pays, ô Emmanuel!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Peuples, alliez-vous, et soyez froissés; et prêtez l’oreille, vous tous qui êtes d’un pays éloigné; équipez-vous, et soyez froissés; équipez-vous, et soyez froissés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Prenez conseil, et il sera dissipé; dites la parole, et elle n’aura point d’effet, parce que le Dieu Fort est avec nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Car ainsi m’a dit l’Eternel avec une main forte, et il m’a instruit de n’aller point par le chemin de ce peuple-ci, en me disant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Ne dites point, Conjuration, toutes les fois que ce peuple dit, Conjuration; et ne craignez point ce qu’il craint, et ne vous en épouvantez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Sanctifiez l’Eternel des armées, lui-même; et qu’il soit votre crainte, et votre épouvantement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'Et il vous sera pour sanctuaire; mais il sera une pierre d’achoppement, et un rocher de trébuchement aux deux maisons d’Israël; en piége et en filets aux habitants de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Et plusieurs d’entr’eux trébucheront, et tomberont, et seront froissés, et seront enlacés, et seront pris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Empaquette le Témoignage, cachette la Loi parmi mes disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'J’attendrai donc l’Eternel, qui cache sa face de la maison de Jacob, et je m’attendrai à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Me voici, avec les enfants que l’Eternel m’a donnés pour être un signe et un miracle en Israël, de par l’Eternel des armées, qui habite en la montagne de Sion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Que s’ils vous disent; enquérez vous des esprits de Python, et des diseurs de bonne aventure, qui gazouillent et grommellent; répondez; le peuple ne s’enquerra-t-il point de son Dieu? aller pour les vivants aux morts!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'A la Loi, et au Témoignage. Que s’ils ne parlent selon cette parole-ci, certainement il n’y aura point de lumière pour lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Et il sera errant sur la terre, étant endurci et affamé; et il arrivera que dans sa faim il se dépitera, et maudira son Roi et son Dieu; et il regardera en haut;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'Puis il regardera vers la terre, et voilà la détresse, et les ténèbres, une effrayante angoisse, et il sera enfoncé dans l’obscurité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 23, 'Car il n’y a point eu d’obscurité épaisse pour celle qui a été affligée, au temps que le premier se déchargea légèrement vers le pays de Zabulon, et vers le pays de Nephthali; et que le dernier s’appesantit sur le chemin de la mer, au deçà du Jourdain dans la Galilée des Gentils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Le peuple qui marchait dans les ténèbres a vu une grande lumière, et la lumière a relui sur ceux qui habitaient au pays de l’ombre de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Tu as multiplié la nation, tu lui as accru la joie, ils se réjouiront devant toi, comme on se réjouit en la maison, comme on s’égaye quand on partage le butin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Car tu as mis en pièces le joug dont il était chargé, et le bâton dont on lui battait ordinairement les épaules, et la verge de son exacteur, comme au jour de Madian.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Parce que tout choc de ceux qui se battent le fait avec tumulte, et que les vêtements sont vautrés dans le sang; mais ceci sera comme un embrasement, quand le feu dévore quelque chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Car l’enfant nous est né, le Fils nous a été donné, et l’empire a été posé sur son épaule, et on appellera son nom, l’Admirable, le Conseiller, le Dieu Fort et puissant, le Père d’éternité, le Prince de paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Il n’y aura point de fin à l’accroissement de l’empire, et à la prospérité sur le trône de David, et sur son règne, pour l’affermir et l’établir en jugement et en justice, dès maintenant et à toujours; la jalousie de l’Eternel des armées fera cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'Le Seigneur a envoyé la parole en Jacob, et elle est tombée en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Et tout le peuple, savoir Ephraïm, et les habitants de Samarie le connaîtront, et néanmoins ils diront avec orgueil et avec un cœur hautain;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'Les briques sont tombées, mais nous bâtirons de pierres de taille; les figuiers sauvages ont été coupés, mais nous les changerons en cèdres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Après que l’Eternel aura élevé les ennemis de Retsin au-dessus de lui, il amènera aussi pêle-mêle les ennemis d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'La Syrie du côté d’Orient, et les Philistins du côté d’Occident, qui dévoreront Israël à gueule ouverte. Malgré tout cela il ne fera point cesser sa colère, mais sa main sera encore étendue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Parce que le peuple ne se sera point retourné jusqu’à celui qui le frappait, et qu’ils n’auront pas recherché l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'A cause de cela l’Eternel retranchera d’Israël en un seul jour la tête et la queue, le rameau et le jonc.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'L’Ancien et l’homme d’autorité; c’est la tête; et le Prophète enseignant mensonge, c’est la queue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Ceux donc qui font accroire à ce peuple qu’il est heureux, se trouveront des séducteurs; et ceux à qui on fait accroire qu’ils sont heureux, seront perdus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'C’est pourquoi le Seigneur ne prendra point plaisir à ses jeunes gens d’élite, et n’aura point pitié de ses orphelins, ni de ses veuves; car tous, tant qu’ils sont, ce sont des hypocrites, et des malins, et toute bouche ne profère que des infamies. Malgré tout cela, il ne fera point cesser sa colère, mais sa main sera encore étendue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Car la méchanceté est embrasée comme un feu, elle dévorera les ronces et les épines, et s’allumera dans les lieux les plus épais de la forêt, qui se perdront en s’élevant, comme une fumée qui monte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'La terre sera obscurcie à cause de la fureur de l’Eternel des armées, et le peuple sera comme la pâture du feu; l’un n’aura point compassion de l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Il ravira à main droite, et il aura faim; il mangera à main gauche, et ils ne seront point rassasiés; chacun mangera la chair de son bras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Manassé dévorera Ephraïm, et Ephraïm dévorera Manassé; eux ensemble seront contre Juda. Malgré tout cela il ne fera point cesser sa colère, mais sa main sera encore étendue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Malheur à ceux qui font des ordonnances d’iniquité, et qui dictent l’oppression qu’on leur a dictée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'Pour enlever aux chétifs de leur droit, et pour ravir le droit des affligés de mon peuple, afin d’avoir les veuves pour leur butin, et de piller les orphelins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Et que ferez-vous au jour de la visitation, et de la ruine éclatante qui viendra de loin? vers qui recourrez-vous pour avoir du secours, et où laisserez-vous votre gloire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Sans qu’aucun soit courbé sous les prisonniers, ils tomberont même sous ceux qui auront été tués. Malgré tout cela il ne fera point cesser sa colère, mais sa main sera encore étendue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Malheur à Assur, la verge de ma colère; quoique le bâton qui est en leur main soit mon indignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Je l’enverrai contre la nation hypocrite, et je le dépêcherai contre le peuple de ma fureur, afin qu’il fasse un grand butin, et un grand pillage, et qu’il le foule comme la boue des rues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Mais il ne l’estimera pas ainsi, et son cœur ne le pensera pas ainsi; mais il aura en son cœur de détruire et d’exterminer beaucoup de nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Car il dira; mes Princes ne sont-ils pas autant de Rois?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Calno, n’est-elle pas comme Carchémis? Hamath, n’est-elle pas comme Arpad? et Samarie, n’est-elle pas comme Damas?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Ainsi que ma main a soumis les Royaumes qui avaient des idoles, et desquels les images taillées valaient plus que celles de Jérusalem et de Samarie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'Ne ferai-je pas aussi à Jérusalem et à ses dieux, comme j’ai fait à Samarie et à ses idoles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Mais il arrivera que quand le Seigneur aura achevé toute son œuvre dans la montagne de Sion et à Jérusalem, j’examinerai le fruit de la grandeur du cœur du Roi d’Assyrie, et la gloire de la fierté de ses yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Parce qu’il aura dit; je l’ai fait par la force de ma main, et par ma sagesse, car je suis intelligent; j’ai ôté les bornes des peuples, et j’ai pillé ce qu’ils avaient de plus précieux, et comme puissant j’ai fait descendre ceux qui étaient assis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Et ma main a trouvé comme un nid les richesses des peuples; et ainsi qu’on rassemble les œufs délaissés, ainsi ai-je rassemblé toute la terre, et il n’y a eu personne qui ait remué l’aile, ou qui ait ouvert le bec, ou qui ait grommelé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'La cognée se glorifiera-t-elle contre celui qui en coupe? ou la scie se magnifiera-t-elle contre celui qui la remue? comme si la verge se remuait contre ceux qui la lèvent en haut, et que le bâton s’élevât, comme s’il n’était pas du bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'C’est pourquoi le Seigneur, l’Eternel des armées enverra la maigreur sur ses hommes gras, et par le dessous de sa gloire il allumera un embrasement, tel que l’embrasement d’un feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Car la lumière d’Israël sera un feu, et son Saint sera une flamme, qui embrasera et consumera ses épines et ses ronces tout en un jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Et il consumera la gloire de sa forêt, et de son Carmel, depuis l’âme jusqu’à la chair; et il en sera comme quand celui qui porte l’étendart est défait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'Et le reste des arbres de sa forêt seront aisés à compter, tellement qu’un enfant les mettrait bien en écrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'Et il arrivera en ce jour-là que le résidu d’Israël, et ceux qui seront réchappés de la maison de Jacob, ne s’appuieront plus sur celui qui les frappait, mais ils s’appuieront en vérité sur l’Eternel, le Saint d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Le résidu sera converti, le résidu, dis-je, de Jacob sera converti au Dieu Fort et puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Car, ô Israël! quand ton peuple serait comme le sablon de la mer, un résidu en sera converti, mais la consomption déterminée fera déborder la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Car le Seigneur l’Eternel des armées s’en va faire une consomption, même déterminée, au milieu de toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel des armées; mon peuple qui habites dans Sion, ne crains point le Roi d’Assyrie; il te frappera de la verge, et il lèvera son bâton sur toi à la manière d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Mais encore un peu de temps, un peu de temps, et mon indignation sera consommée, et ma colère sera à leur destruction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Et l’Eternel des armées lèvera sur lui un fouet, qui sera comme la plaie de Madian au rocher d’Horeb; et comme son bâton sur la mer, lequel il élèvera aussi comme contre les Egyptiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'Et il arrivera en ce jour-là, que son fardeau sera ôté de dessus ton épaule, et son joug de dessus ton cou; et le joug sera rompu à cause de l’onction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Il est venu à Hajath, il est passé à Migron, et il a mis son bagage à Michmas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Ils ont passé le gué; ils ont fait leur gîte à Guébah, Rama s’est effrayée, Guibha-Saül s’en est fuie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Fille de Gallim, élève ta voix, pauvre Hanathoth, fais-toi ouïr vers Laïs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madména s’est écartée, les habitants de Guébim s’en sont fuis en foule.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Encore un jour, il s’arrêtera à Nob; il lèvera sa main contre la montagne de la fille de Sion, contre le coteau de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Voici, le Seigneur, l’Eternel des armées ébranchera les rameaux avec force, et ceux qui sont les plus haut élevés, seront coupés; et les haut montés seront abaissés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Et il taillera avec le fer les lieux les plus épais de la forêt, et le Liban tombera avec impétuosité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Mais il sortira un rejeton du tronc d’Isaï, et un surgeon croîtra de ses racines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'Et l’Esprit de l’Eternel reposera sur lui, l’Esprit de sapience et d’intelligence, l’Esprit de conseil et de force, l’Esprit de science et de crainte de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Et il lui fera sentir la crainte de l’Eternel, tellement qu’il ne jugera point sur la vue de ses yeux, et ne reprendra point sur l’ouïe de ses oreilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Mais il jugera avec justice les chétifs, et il reprendra avec droiture, pour maintenir les débonnaires de la terre, et il frappera la terre par la verge de sa bouche, et fera mourir le méchant par l’esprit de ses lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Et la justice sera la ceinture de ses reins; et la fidélité, la ceinture de ses flancs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Le loup demeurera avec l’agneau, et le léopard gîtera avec le chevreau; le veau, et le lionceau, et le bétail qu’on engraisse seront ensemble, et un petit enfant les conduira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'La jeune vache paîtra avec l’ourse, leurs petits gîteront ensemble, et le lion mangera du fourrage comme le boeuf.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Et l’enfant qui tète s’ébattra sur le trou de l’aspic; et l’enfant qu’on sèvre mettra sa main au trou du basilic.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'On ne nuira et on ne fera aucun dommage à personne dans toute la montagne de ma Sainteté; parce que la terre aura été remplie de la connaissance de l’Eternel, comme le fond de la mer des eaux qui le couvrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Car en ce jour-là il arrivera que les nations rechercheront la racine d’Isaï, dressée pour être l’enseigne des peuples; et son séjour ne sera que gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Et il arrivera en ce jour-là, que le Seigneur mettra encore sa main une seconde fois pour acquérir le résidu de son peuple, qui sera demeuré de reste en Assyrie, en Egypte, à Pathros, à Chus, à Hélam, à Sinhar, à Hamath, et dans les Iles de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Et il élèvera l’enseigne parmi les nations, et assemblera les Israélites qui auront été chassés, et recueillera des quatre coins de la terre ceux de Juda qui auront été dispersés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Et la jalousie d’Ephraïm sera ôtée, et les oppresseurs de Juda seront retranchés; Ephraïm ne sera plus jaloux de Juda, et Juda n’opprimera plus Ephraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Mais ils voleront sur le collet aux Philistins vers la mer; ils pilleront ensemble les enfants d’Orient; Edom et Moab seront ceux sur lesquels ils jetteront leurs mains, et les enfants de Hammon leur obéiront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'L’Eternel exterminera aussi à la façon de l’interdit la Langue de la mer d’Egypte, et lèvera sa main contre le fleuve par la force de son vent, et il le frappera sur les sept rivières, et fera qu’on y marchera avec des souliers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Et il y aura un chemin pour le résidu de son peuple qui sera demeuré de reste en Assyrie, comme il y en eut un pour Israël au temps qu’il remonta du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'Et tu diras en ce jour-là; Eternel! je te célébrerai, parce qu’ayant été courroucé contre moi, ta colère s’est apaisée, et tu m’as consolé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Voici, le Dieu Fort est ma délivrance, j’aurai confiance, et je ne serai point effrayé; car l’Eternel, l’Eternel est ma force et ma louange, et il a été mon Sauveur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Et vous puiserez des fontaines de cette délivrance des eaux avec joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'Et vous direz en ce jour-là; Célébrez l’Eternel, réclamez son Nom, faites connaître parmi les peuples ses exploits, faites souvenir que son Nom est une haute retraite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Psalmodiez à l’Eternel, car il a fait des choses magnifiques; cela est connu dans toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Habitante de Sion, égaye-toi, et te réjouis avec chant de triomphe; car le Saint d’Israël est grand au milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'La charge de Babylone, qu’Esaïe fils d’Amots a vue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Elevez l’enseigne sur la haute montagne, élevez la voix vers eux, remuez la main, et qu’on entre dans les portes des magnifiques.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'C’est moi qui ai donné charge à ceux qui me sont dévoués, et j’ai appelé pour exécuter ma colère mes hommes forts, qui s’égayent à cause de ma grandeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Il y a sur les montagnes un bruit d’une multitude, tel qu’est celui d’un grand peuple, un bruit d’un son éclatant des Royaumes des nations assemblées; l’Eternel des armées fait la revue de l’armée pour le combat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'L’Eternel et les instruments de son indignation viennent d’un pays éloigné, du bout des cieux, pour détruire tout le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Hurlez; car la journée de l’Eternel est proche, elle viendra comme un dégât fait par le Tout-Puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'C’est pourquoi toutes les mains deviendront lâches, et tout coeur d’homme se fondra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'Ils seront épouvantés, les détresses et les douleurs les saisiront, ils seront en travail comme celle qui enfante, chacun s’étonnera regardant vers son prochain, leurs visages seront comme des visages enflammés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Voici, la journée de l’Eternel vient, elle est cruelle, elle n’est que fureur et ardeur de colère, pour réduire le pays en désolation, et il en exterminera les pécheurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Même les étoiles des cieux et leurs astres ne feront point luire leur clarté; le Soleil s’obscurcira quand il se lèvera, et la Lune ne fera point resplendir sa lueur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'Je punirai le monde habitable à cause de sa malice, et les méchants à cause de leur iniquité; je ferai cesser l’arrogance de ceux qui se portent fièrement, et j’abaisserai la hauteur de ceux qui se font redouter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Je ferai qu’un homme sera plus précieux que le fin or; et une personne, plus que l’or d’Ophir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'C’est pourquoi je ferai crouler les cieux, et la terre sera ébranlée de sa place, à cause de la fureur de l’Eternel des armées, et à cause du jour de l’ardeur de sa colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Et chacun sera comme un chevreuil qui est chassé, et comme une brebis que personne ne retire; chacun tournera visage vers son peuple, et chacun s’enfuira vers son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Quiconque sera trouvé, sera transpercé; et quiconque s’y sera joint, tombera par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Et leurs petits enfants seront écrasés devant leurs yeux, leurs maisons seront pillées, et leurs femmes violées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Voici, je vais susciter contre eux les Mèdes, qui ne feront aucune estime de l’argent, et qui ne s’arrêteront point à l’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Leurs arcs écraseront les jeunes gens, et ils n’auront point de pitié du fruit du ventre, leur oeil n’épargnera point les enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Ainsi Babylone, la noblesse des Royaumes, l’excellence de l’orgueil des Chaldéens, sera comme quand Dieu renversa Sodome et Gomorrhe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Elle ne sera point habitée à jamais, elle ne sera point habitée de génération en génération, même les Arabes n’y dresseront point leurs tentes, ni les bergers n’y mettront point leurs parcs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Mais les bêtes sauvages des déserts y auront leurs repaires; et leurs maisons seront remplies de fouines, les chats-huants y habiteront, et les chouettes y sauteront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'Et les bêtes sauvages des Iles s’entre-répondront les unes aux autres dans ses palais désolés, et les dragons dans ses châteaux de plaisance; son temps est même prêt à venir, et ses jours ne seront point prolongés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Car l’Eternel aura pitié de Jacob, et élira encore Israël, et il les rétablira dans leur terre, et les étrangers se joindront à eux, et s’attacheront à la maison de Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Et les peuples les prendront, et les mèneront en leur lieu, et la maison d’Israël les possédera en droit d’héritage sur la terre de l’Eternel, comme des serviteurs et des servantes; ils tiendront captifs ceux qui les avaient tenus captifs, et ils domineront sur leurs exacteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Et il arrivera qu’au jour que l’Eternel fera cesser ton travail, ton tourment, et la dure servitude sous laquelle on t’aura asservi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'Tu te moqueras ainsi du Roi de Babylone, et tu diras; comment se repose l’exacteur? comment se repose celle qui était si avide de richesses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'L’Eternel a rompu le bâton des méchants, et la verge des dominateurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'Celui qui frappait avec fureur les peuples de coups que l’on ne pouvait point détourner, qui dominait sur les nations avec colère, est poursuivi sans qu’il s’en puisse garantir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Toute la terre a été mise en repos et en tranquillité; on a éclaté en chant de triomphe, à gorge déployée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Même les sapins et les cèdres du Liban se sont réjouis de toi, en disant; Depuis que tu es endormi, personne n’est monté pour nous tailler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Le sépulcre profond s’est ému à cause de toi, pour aller au-devant de toi à ta venue, il a réveillé à cause de toi les trépassés, et a fait lever de leurs sièges tous les principaux de la terre, tous les Rois des nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Eux tous prendront la parole, et te diront; tu as été aussi affaibli que nous; tu as été rendu semblable à nous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'On a fait descendre ta hauteur au sépulcre, avec le bruit de tes musettes; tu es couché sur une couche de vers, et la vermine est ce qui te couvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Comment es-tu tombée des cieux, Etoile du matin, fille de l’aube du jour? toi qui foulais les nations, tu es abattue jusques en terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Tu disais en ton coeur; Je monterai aux cieux, je placerai mon trône au-dessus des étoiles du Dieu Fort; je serai assis en la montagne d’assignation, aux côtés d’Aquilon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Je monterai au-dessus des hauts lieux des nuées; je serai semblable au Souverain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Et cependant on t’a fait descendre au sépulcre, au fond de la fosse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Ceux qui te verront te regarderont et te considéreront, en disant; N’est-ce pas ici ce personnage qui faisait trembler la terre, qui ébranlait les Royaumes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'Qui a réduit le monde habitable comme en un désert, et qui a détruit ses villes, et n’a point relâché ses prisonniers pour les renvoyer en leur maison?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Tous les Rois des nations sont morts avec gloire, chacun dans sa maison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Mais tu as été jeté loin de ton sépulcre, comme un rejeton pourri, comme un habillement de gens tués, transpercés avec l’épée, qui sont descendus parmi les pierres d’une fosse, comme une charogne foulée aux pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Tu ne seras point rangé comme eux dans le sépulcre; car tu as ravagé ta terre; tu as tué ton peuple; la race des malins ne sera point renommée à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Préparez la tuerie pour ses enfants, à cause de l’iniquité de leurs pères; afin qu’ils ne se relèvent point, et qu’ils n’héritent point la terre, et ne remplissent point de villes le dessus de la terre habitable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Je m’élèverai contre eux, dit l’Eternel des armées, et je retrancherai à Babylone le nom, et le reste qu’elle a, le fils et le petit-fils, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'Et je la réduirai en habitation de butors, et en marais d’eaux, et je la balayerai d’un balai de destruction, dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'L’Eternel des armées a juré, en disant; S’il n’est fait ainsi que je l’ai pensé, même comme je l’ai arrêté dans mon conseil, il tiendra;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'C’est que je froisserai le Roi d’Assyrie dans ma terre, je le foulerai sur mes montagnes; et son joug sera ôté de dessus eux, et son fardeau sera ôté de dessus leurs épaules.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'C’est là le conseil qui a été arrêté contre toute la terre, et c’est là la main étendue sur toutes les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Car l’Eternel des armées l’a arrêté en son conseil; et qui l’empêcherait? et sa main est étendue; et qui la détournerait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'L’année en laquelle mourut le Roi Achaz, cette charge-ci fut mise en avant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Toi, toute la contrée des Philistins, ne te réjouis point de ce que la verge de celui qui te frappait a été brisée; car de la racine du serpent sortira un basilic, et son fruit sera un serpent brûlant qui vole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Les plus misérables seront repus, et les pauvres reposeront en assurance, mais je ferai mourir de faim ta racine, et on tuera ce qui sera resté en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Toi porte, hurle; toi ville, crie; toi tout le pays des Philistins, sois comme une chose qui s’écoule; car une fumée viendra de l’Aquilon, et il ne restera pas un seul homme dans ses habitations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Et que répondra-t-on aux Ambassadeurs de cette nation? On répondra que l’Eternel a fondé Sion; et que les affligés de son peuple se retireront vers elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'La charge de Moab; parce que Har de Moab a été ravagée de nuit, il a été défait; parce que Kir de Moab a été saccagée de nuit, il a été défait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Il est monté à Bajith, et à Dibon, dans les hauts lieux, pour pleurer; Moab hurlera sur Nébo, et sur Médeba, toutes ses têtes seront chauves, et toute barbe sera rasée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'On sera ceint de sacs dans ses rues, chacun hurlera fondant en larmes sur ses toits, et dans ses places.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Hesbon et Elhalé se sont écriées, leur voix a été ouïe jusqu’à Jahats; c’est pourquoi ceux de Moab qui seront équipés pour aller à la guerre, jetteront des cris lamentables, son âme se tourmentera au dedans de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Mon coeur crie à cause de Moab; ses fugitifs s’en sont fuis jusqu’à Tsohar, comme une génisse de trois ans; car on montera par la montée de Luhith avec des pleurs, et on fera retentir le cri de la plaie au chemin de Horonajim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Même les eaux de Nimrim ne seront que désolations, même le foin est déjà séché, l’herbe a été consumée, et il n’y a point de verdure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Il aura acquis des richesses en abondance, afin que ce qu’ils auront réservé soit porté dans la vallée des Arabes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Car le cri a environné la contrée de Moab; son hurlement ira jusqu’à Eglajim, et son hurlement jusqu’à Béer-Elim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Même les eaux de Dimon ont été remplies de sang; car j’ajouterai un surcroît sur Dimon, savoir le lion à ceux qui seront réchappés de Moab, et au résidu du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Envoyez l’agneau au Dominateur de la terre, envoyez-le du rocher du désert, à la montagne de la fille de Sion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Car il arrivera que les filles de Moab seront au passage d’Arnon, comme un oiseau volant çà et là, comme une nichée chassée de son nid.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Mets en avant le conseil, fais l’ordonnance, sers d’ombre comme une nuit au milieu du midi; cache ceux qui ont été chassés, et ne décèle point ceux qui sont errants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Que ceux de mon peuple qui ont été chassés séjournent chez toi, ô Moab! sois leur une retraite contre celui qui fait le dégât; car celui qui usait d’extorsion a cessé, le dégât a pris fin, ceux qui foulaient sont consumés de dessus la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'Et le trône sera établi par la gratuité; et sur ce trône sera assis en vérité, dans le tabernacle de David, un qui jugera, qui recherchera le droit, et qui se hâtera de faire justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Nous avons entendu l’orgueil de Moab le très-orgueilleux, sa fierté, et son orgueil, et son arrogance; ceux sur qui il s’appuie ne sont rien de ferme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'C’est pourquoi Moab hurlera sur Moab, chacun hurlera; vous grommellerez pour les fondements de Kir-Haréseth; il n’y aura que des gens blessés à mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Car les guérets de Hesbon, et le vignoble de Sibma, languissent; les Seigneurs des nations ont foulé ses meilleurs plants, qui atteignaient jusques à Jahzer, ils couraient çà et là par le désert, et ses provins s’étendaient et passaient au delà de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'C’est pourquoi je pleurerai du pleur de Jahzer, le vignoble de Sibma; je t’arroserai de mes larmes, ô Hesbon et Elhalé! car l’ennemi avec des cris s’est jeté sur tes fruits d’Eté, et sur ta moisson.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Et la joie et la gaieté s’est retirée du champ fertile; on ne se réjouira plus, et on ne s’égayera plus dans les vignes, celui qui foulait le vin ne le foulera plus dans les cuves, j’ai fait cesser la chanson de la vendange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'C’est pourquoi mes entrailles mèneront du bruit comme une harpe sur Moab, et mon ventre sur Kir-Hérès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Et il arrivera qu’on verra que Moab se lassera pour aller au haut lieu, et qu’il entrera en son saint lieu pour prier; mais il ne pourra rien obtenir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'C’est là la parole que l’Eternel a prononcée depuis longtemps sur Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Et maintenant l’Eternel a parlé, en disant; dans trois ans, tels que sont les ans d’un mercenaire, la gloire de Moab sera avilie, avec toute cette grande multitude; et le résidu sera petit, ce sera peu de chose, ce ne sera rien de considérable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'La charge de Damas; voici, Damas est détruite pour n’être plus ville, et elle ne sera qu’un monceau de ruines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Les villes de Haroher seront abandonnées, elles deviendront des parcs de brebis qui y reposeront, et il n’y aura personne qui les épouvante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Il n’y aura point de forteresse en Ephraïm, ni de Royaume à Damas, ni dans le reste de la Syrie; ils seront comme la gloire des enfants d’Israël, dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'Et il arrivera en ce jour-là, que la gloire de Jacob sera diminuée, et que la graisse de sa chair sera fondue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Et il en arrivera comme quand le moissonneur cueille les blés, et qu’il moissonne les épis avec son bras; il en arrivera, dis-je, comme quand on ramasse les épis dans la vallée des Réphaïns.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Mais il y demeurera quelques grappillages, comme quand on secoue l’olivier, et qu’il reste deux ou trois olives au bout des plus hautes branches, et qu’il y en a quatre ou cinq que l’olivier a produites dans ses branches fruitières, dit l’Eternel, le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'En ce jour-là, l’homme tournera sa vue vers celui qui l’a fait, et ses yeux regarderont vers le Saint d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'Et il ne jettera plus sa vue vers les autels qui sont l’ouvrage de ses mains, et ne regardera plus ce que ses doigts auront fait, ni les bocages, ni les tabernacles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'En ce jour-là, les villes de sa force, qui auront été abandonnées à cause des enfants d’Israël, seront comme un bois taillis et des rameaux abandonnés, et il y aura désolation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Parce que tu as oublié le Dieu de ton salut, et que tu ne t’es point souvenue du rocher de ta force, à cause de cela tu as transplanté des plantes tirées des lieux de plaisance, et tu as planté des provins d’un pays étranger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'De jour tu auras fait croître ce que tu auras planté, et le matin tu auras fait lever ta semence; mais la moisson sera enlevée au jour que l’on voulait en jouir, et il y aura une douleur désespérée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Malheur à la multitude de plusieurs peuples qui bruient comme bruient les mers; et à la tempête éclatante des nations, qui font du bruit comme une tempête éclatante d’eaux impétueuses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Les nations bruient comme une tempête éclatante de grosses eaux, mais il la menacera, et elle s’enfuira loin; elle sera poursuivie comme la balle des montagnes, chassée par le vent, et comme une boule poussée par un tourbillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Au temps du soir voici l’épouvante, mais avant le matin il ne sera plus; c’est là la portion de ceux qui nous auront fourragés, et le lot de ceux qui nous auront pillés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Malheur au pays qui fait ombre avec des ailes, qui est au-delà des fleuves de Chus;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'Qui envoie par mer des ambassadeurs, et dans des vaisseaux de jonc sur les eaux. Allez, messagers légers, vers la nation de grand attirail et brillante, vers le peuple terrible, depuis là où il est et par delà; nation allant à la file, et qui foule tout, dont les fleuves ravagent sa terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Vous tous les habitants du monde habitable, et vous qui demeurez dans le pays, sitôt que l’enseigne sera élevée sur les montagnes, regardez, et sitôt que le cor aura sonné écoutez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Car ainsi m’a dit l’Eternel; je me tiendrai tranquille; mais je regarderai sur mon domicile arrêté, et je lui serai comme une chaleur brillante de splendeur, et comme une nuée de rosée dans la chaleur de la moisson.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Car avant la moisson, sitôt que le bouton sera venu en sa perfection, et que la fleur sera devenue un raisin se mûrissant, il coupera les rameaux avec des serpes, et il ôtera les sarments, les ayant retranchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Ils seront tous ensemble abandonnés aux oiseaux de proie qui demeurent dans les montagnes, et aux bêtes du pays; les oiseaux de proie seront sur eux tout le long de l’Eté, et toutes les bêtes du pays y passeront leur hiver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'En ce temps-là sera apporté à l’Eternel des armées un présent du peuple de long attirail et brillant, de la part, dis-je, du peuple terrible, depuis là où il est, et par delà; de la nation allant à la file, et qui foule tout; les fleuves de laquelle ont ravagé son pays, dans la demeure du Nom de l’Eternel des armées, en la montagne de Sion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'La charge de l’Egypte. Voici, l’Eternel s’en va monter sur une nuée légère, et il entrera dans l’Egypte; et les idoles d’Egypte s’enfuiront de toutes parts de devant sa face, et le coeur de l’Egypte se fondra au milieu d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Et je ferai venir pêle-mêle l’Egyptien contre l’Egyptien, et chacun fera la guerre contre son frère, et chacun contre son ami, ville contre ville, Royaume contre Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'L’esprit de l’Egypte s’évanouira au milieu d’elle, et je dissiperai son conseil, et ils interrogeront les idoles, et les enchanteurs, et les esprits de Python, et les diseurs de bonne aventure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Et je livrerai l’Egypte en la main d’un Seigneur sévère, et un Roi cruel dominera sur eux, dit le Seigneur, l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Et les eaux de la mer défaudront, et le fleuve séchera, et tarira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Et on fera détourner les fleuves; les ruisseaux des digues s’abaisseront et sécheront; les roseaux et les joncs seront coupés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Les prairies qui sont près des ruisseaux, et sur l’embouchure du fleuve, et tout ce qui aura été semé le long des ruisseaux, séchera, sera jeté loin, et ne sera plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Et les pêcheurs gémiront, et tous ceux qui jettent l’hameçon au fleuve, mèneront deuil, et ceux qui étendent les rets sur les eaux, languiront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Ceux qui travaillent en lin et en fin crêpe, et ceux qui tissent les filets, seront honteux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Et ses chaussées seront rompues; et tous ceux qui font des écluses de viviers seront contristés de coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Certes les principaux de Tsohan sont fous, les sages d’entre les conseillers de Pharaon sont un conseil abruti; comment dites-vous à Pharaon; je suis fils des sages, le fils des Rois anciens?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Où sont-ils maintenant? où sont, dis-je, tes sages? qu’ils t’annoncent, je te prie, s’ils le savent, ce que l’Eternel des armées a décrété contre l’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Les principaux de Tsohan sont devenus insensés; les principaux de Noph se sont trompés; les Cantons des Tribus d’Egypte l’ont fait égarer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'L’Eternel a versé au milieu d’elle un esprit de renversement, et on a fait errer l’Egypte dans toutes ses oeuvres, comme un homme ivre se vautre dans son vomissement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Et il n’y aura aucun ouvrage qui serve à l’Egypte, rien de ce que fera la tête ou la queue, le rameau ou le jonc.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'En ce jour-là l’Egypte sera comme des femmes, et elle sera étonnée et épouvantée à cause de la main élevée de l’Eternel des armées, laquelle il s’en va élever contr’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Et la terre de Juda sera en effroi à l’Egypte; quiconque fera mention d’elle, en sera épouvanté en soi-même, à cause du conseil de l’Eternel des armées, lequel il s’en va décréter contr’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'En ce jour-là il y aura cinq villes au pays d’Egypte qui parleront le langage de Chanaan, et qui jureront à l’Eternel des armées; et l’une sera appelée Ville de destruction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'En ce jour-là il y aura un autel à l’Eternel au milieu du pays d’Egypte, et une enseigne dressée à l’Eternel sur sa frontière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'Et cela sera pour signe et pour témoignage à l’Eternel des armées dans le pays d’Egypte; car ils crieront à l’Eternel à cause des oppresseurs, et il leur enverra un libérateur, et un grand personnage qui les délivrera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Et l’Eternel se fera connaître à l’Egypte; et en ce jour-là l’Egypte connaîtra l’Eternel, et le servira, offrant des sacrifices et des gâteaux, et elle vouera des voeux à l’Eternel, et les accomplira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'L’Eternel donc frappera les Egyptiens, les frappant et les guérissant, et ils retourneront jusques à l’Eternel, qui sera fléchi par leurs prières, et les guérira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'En ce jour-là il y aura un chemin battu de l’Egypte en Assyrie; et l’Assyrie viendra en Egypte, et l’Egypte en Assyrie, et l’Egypte servira avec l’Assyrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'En ce jour-là Israël sera joint pour la troisième partie à l’Egypte et à l’Assyrie, et la bénédiction sera au milieu de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'Ce que l’Eternel des armées bénira, en disant: Bénie soit l’Egypte mon peuple; et bénie soit l’Assyrie l’ouvrage de mes mains; et Israël mon héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'L’Année en laquelle Tartan, envoyé par Sargon Roi d’Assyrie, vint contre Asdod, et combattit contre Asdod, et la prit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'En ce temps-là, l’Eternel parla par le ministère d’Esaïe fils d’Amots, en disant; va, et délie le sac de dessus tes reins, et déchausse tes souliers de tes pieds; ce qu’il fit, allant nu et déchaussé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Puis l’Eternel dit; comme mon serviteur Esaïe a marché nu et déchaussé, ce qui est un signe et un prodige contre l’Egypte et contre Chus pour trois années;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'Ainsi le Roi d’Assyrie emmènera d’Egypte et de Chus prisonniers et captifs les jeunes et les vieux, les nus et les déchaussés, ayant les hanches découvertes, ce qui sera l’opprobre de l’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Ils seront effrayés, et ils seront honteux à cause de Chus, auquel ils regardaient; et à cause de l’Egypte, qui était leur gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Et celui qui habite en cette Ile-ci dira en ce jour-là; voilà en quel état est celui auquel nous regardions, celui auprès de qui nous nous sommes réfugiés pour avoir du secours, afin d’être délivrés de la rencontre du Roi d’Assyrie; et comment pourrons-nous échapper?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'La charge du désert de la mer. Il vient du désert, de la terre épouvantable, comme des Tourbillons qui s’élèvent au pays du Midi, pour traverser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Une dure vision m’a été déclarée. Le perfide demeure perfide; celui qui saccage, saccage toujours. Hélamites, montez; Mèdes, assiégez; j’ai fait cesser tous ses soupirs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'C’est pourquoi mes reins ont été remplis de douleur; les angoisses m’ont saisi, comme les angoisses de celle qui enfante; je me suis tourmenté à cause de ce que j’ai ouï, et j’ai été tout troublé à cause de ce que j’ai vu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Mon cœur a été agité de toutes parts, et un tremblement m’a épouvanté; on m’a rendu horrible la nuit de mes plaisirs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Qu’on dresse la table, qu’on fasse le guet, qu’on mange, qu’on boive; levez-vous, Capitaines, oignez le bouclier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Car ainsi me dit le Seigneur; va, pose la sentinelle, et qu’elle rapporte ce qu’elle verra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Et elle vit un chariot, une couple de gens de cheval, un chariot tiré par des ânes, et un chariot tiré par des chameaux, et elle les considéra fort attentivement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Et cria; C’est un lion; Seigneur, je me tiens en sentinelle continuellement de jour, et je me tiens en ma garde toutes les nuits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'Et voici venir le chariot d’un homme, une paire de gens de cheval. Alors elle parla, et dit; Elle est tombée, elle est tombée, Babylone; et toutes les images taillées de ses dieux ont été brisées par terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'C’est ce que j’ai foulé, et le grain que j’ai battu dans mon aire. Je vous ai annoncé ce que j’ai ouï de l’Eternel des armées, du Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'La charge de Duma. On crie à moi de Séhir; ô sentinelle! qu’y a- t-il depuis le soir? ô sentinelle! qu’y a-t-il depuis la nuit?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'La sentinelle a dit; Le matin est venu, mais il s’en va être nuit; si vous demandez, demandez: retournez, venez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'La charge contre l’Arabie. Vous passerez pêle-mêle la nuit dans la forêt, troupes de Dédanim;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Eaux, venez au-devant de celui qui a soif; les habitants du pays de Téma sont venus au-devant de celui qui s’en allait errant çà et là avec du pain pour lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Car ils s’en sont allés errant çà et là de devant les épées, de devant l’épée dégainée, et de devant l’arc tendu, et de devant le fort de la bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Car ainsi m’a dit le Seigneur; dans un an, tels que sont les ans d’un mercenaire, toute la gloire de Kédar prendra fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'Et le reste du nombre des forts archers des enfants de Kédar sera diminué; car l’Eternel le Dieu d’Israël a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'La charge de la vallée de vision. Qu’as-tu maintenant, que tu sois toute montée sur les toits,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Toi pleine de tumulte, ville bruyante, ville qui ne demandais qu’à t’égayer? tes blessés à mort n’ont pas été blessés à mort par l’épée, et ils ne sont pas morts par la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Tous tes conducteurs sont allés errant çà et là ensemble, ils ont été liés par les archers; tous ceux des tiens qui ont été trouvés ont été liés ensemble, s’en étant fuis loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'C’est pourquoi j’ai dit; retirez-vous de moi, je pleurerai amèrement. Ne vous empressez point de me consoler touchant le dégât de la fille de mon peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Car c’est le jour de trouble, d’oppression, et de perplexité, de par le Seigneur, l’Eternel des armées, dans la vallée de vision; il s’en va démolir la muraille, et le cri en ira jusqu’à la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Même Hélam a pris son carquois, il y a des hommes montés sur des chariots, et Kir a découvert le bouclier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'Et il est arrivé que l’élite de tes vallées a été remplie de chariots, et les gens de cheval se sont tous rangés en bataille contre la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Et on a découvert ce qui couvrait Juda, et tu as regardé en ce jour-là vers les armes de la maison du parc.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'Et vous avez vu que les brèches de la cité de David étaient grandes; et vous avez assemblé les eaux du bas étang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Et vous avez fait le dénombrement des maisons de Jérusalem, et démoli les maisons pour fortifier la muraille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Vous avez aussi fait un réservoir d’eaux entre les deux murailles, pour les eaux du vieux étang; mais vous n’avez point regardé à celui qui l’a faite et formée dès longtemps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Et le Seigneur, l’Eternel des armées, vous a appelés ce jour-là aux pleurs et au deuil, à vous arracher les cheveux, et à ceindre le sac;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'Et voici il y a de la joie et de l’allégresse; on tue des bœufs, on égorge des moutons, on en mange la chair, et on boit du vin; puis on dit; Mangeons et buvons; car demain nous mourrons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Or l’Eternel des armées m’a déclaré, disant; si jamais cette iniquité vous est pardonnée, que vous n’en mouriez, a dit le Seigneur, l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Ainsi a dit le Seigneur, l’Eternel des armées; va, entre chez ce trésorier, chez Sebna maître d’hôtel et lui dis;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Qu’as-tu à faire ici? et qui est ici qui t’appartienne, que tu te sois taillé ici un sépulcre? Il taille un lieu éminent pour son sépulcre, et se creuse une demeure dans un rocher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Voici, ô homme! l’Eternel te chassera loin, et te couvrira entièrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Il te fera rouler fort vite comme une boule en un pays large et spacieux; tu mourras là, et là seront les chariots de ta gloire, de toi qui es la honte de la maison de ton Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Et je te jetterai hors de ton rang, et on te déposera de ton emploi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Et il arrivera en ce jour-là que j’appellerai mon serviteur Eliakim, fils de Hilkija.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'Et je le vêtirai de ta casaque, je le ceindrai de ton baudrier, je mettrai ton autorité entre ses mains, et il sera pour père à ceux qui habitent dans Jérusalem, et à la maison de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Et je mettrai la clef de la maison de David sur son épaule; et il ouvrira, et il n’y aura personne qui ferme; et il fermera, et il n’y aura personne qui ouvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Et je le ficherai comme un croc en un lieu ferme; et il sera pour trône de gloire à la maison de son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Et on y pendra toute la gloire de la maison de son père, de ses parents, et de celles qui lui appartiennent; tous les ustensiles des plus petites choses, depuis les ustensiles des tasses jusques à tous les ustensiles des musettes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'En ce jour-là, dit l’Eternel des armées, le croc qui avait été fiché en un lieu ferme, sera ôté; et étant retranché il tombera, et ce dont il était chargé sera retranché; car l’Eternel a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'La charge de Tyr. Hurlez, navires de Tarsis, car elle est détruite, il n’y a plus de maisons, on n’y viendra plus; ceci leur a été découvert du pays de Chittim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Vous qui habitez dans l’Ile, taisez-vous; toi qui étais remplie de marchands de Sidon, et de ceux qui traversaient la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Les grains de Sihor qui viennent parmi les grandes eaux, la moisson du fleuve, était son revenu, et elle était la foire des nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Sois honteuse, ô Sidon! car la mer, la forteresse de la mer, a parlé, en disant; je n’ai point été en travail d’enfant, et je n’ai point enfanté, et je n’ai point nourri de jeunes gens, ni élevé aucunes vierges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Selon le bruit qui a été touchant l’Egypte, ainsi sera-t-on en travail quand on entendra le bruit touchant Tyr.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Passez en Tarsis, hurlez, vous qui habitez dans les Iles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'N’est-ce pas ici votre ville qui s’égayait? celle dont l’ancienneté est de fort longtemps sera portée bien loin par ses propres pieds, pour séjourner en un pays étranger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Qui a pris ce conseil contre Tyr, laquelle couronne les siens, de laquelle les marchands sont des Princes, et dont les facteurs sont les plus honorables de la terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'L’Eternel des armées a pris ce conseil, pour flétrir l’orgueil de toute la noblesse, et pour avilir tous les plus honorables de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Traverse ton pays comme une rivière, ô fille de Tarsis; il n’y a plus de ceinture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Il a étendu sa main sur la mer, et a fait trembler les Royaumes; l’Eternel a donné ordre à un marchand de détruire ses forteresses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'Et il a dit; tu ne continueras plus à t’égayer, étant opprimée, vierge, fille de Sidon. Lève-toi, traverse en Chittim; encore n’y aura-t-il point là de repos pour toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Voilà le pays des Chaldéens; ce peuple-là n’était pas autrefois; Assur l’a fondé pour les gens de marine; on a dressé ses forteresses, on a élevé ses palais, et il l’a mis en ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Hurlez, navires de Tarsis; car votre force est détruite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'Et il arrivera en ce jour-là, que Tyr sera mise en oubli durant soixante-dix ans, selon les jours d’un Roi; mais au bout de soixante-dix ans on chantera une chanson à Tyr comme à une femme prostituée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Prends la harpe, environne la ville, ô prostituée, qui avais été mise en oubli, sonne avec force, chante et rechante, afin qu’on se ressouvienne de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Et il arrivera au bout de soixante-dix ans, que l’Eternel visitera Tyr, mais elle retournera au salaire de sa prostitution, et elle se prostituera avec tous les Royaumes des pays qui sont sur le dessus de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Et son trafic et son salaire sera sanctifié à l’Eternel; il n’en sera rien réservé, ni serré; car son trafic sera pour ceux qui habitent en la présence de l’Eternel, pour en manger jusques à être rassasiés, et pour avoir des habits de longue durée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Voici, l’Eternel s’en va rendre le pays vide, et l’épuiser; et il en renversera le dessus, et dispersera ses habitants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Et tel sera le Sacrificateur que le peuple; tel le maître que son serviteur; telle la dame que sa servante; tel le vendeur que l’acheteur; tel celui qui prête que celui qui emprunte; tel le créancier, que le débiteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Le pays sera entièrement vidé, et entièrement pillé; car l’Eternel a prononcé cet arrêt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'La terre mène deuil, elle est déchue; le pays habité est devenu languissant, il est déchu; les plus distingués du peuple de la terre sont languissants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Le pays a été profané par ses habitants, qui marchent sur lui; parce qu’ils ont transgressé les lois, ils ont changé les ordonnances, et ont enfreint l’alliance éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'C’est pourquoi l’exécration du serment a dévoré le pays, et ses habitants ont été mis en désolation; à cause de cela les habitants du pays sont brûlés, et peu de gens sont demeurés de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Le vin excellent a mené deuil, la vigne languit, tous ceux qui avaient le cœur joyeux soupirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'La joie des tambours a cessé; le bruit de ceux qui s’égayent est fini; la joie de la harpe a cessé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'On ne boira plus de vin avec des chansons; la cervoise sera amère à ceux qui la boivent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'La ville défigurée a été ruinée, toute maison est fermée, tellement que personne n’y entre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'La clameur est dans les places à cause que le vin a manqué, toute la joie est tournée en obscurité, l’allégresse du pays s’en est allée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'La désolation est demeurée dans la ville, et la porte est frappée d’une ruine éclatante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Car il arrivera au milieu de la terre, et parmi les peuples, comme quand on secoue l’olivier, et comme quand on grappille après avoir achevé de vendanger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Ceux-ci élèveront leur voix, ils se réjouiront avec chant de triomphe, et s’égayeront de devers la mer, à cause de la majesté de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'C’est pourquoi glorifiez l’Eternel dans les vallées, le Nom de l’Eternel, le Dieu d’Israël, dans les Iles de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Nous avions entendu du bout de la terre des cantiques qui portaient que le Juste était plein de noblesse; mais j’ai dit: Maigreur sur moi! maigreur sur moi! Malheur à moi! les perfides ont agi perfidement; et ils ont imité la mauvaise foi des perfides.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'La frayeur, la fosse, et le piège sont sur toi, habitant du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Et il arrivera que celui qui s’enfuira à cause du bruit de la frayeur, tombera dans la fosse; et celui qui sera remonté hors de la fosse, sera attrapé au filet; car les bondes d’en haut sont ouvertes, et les fondements de la terre tremblent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'La terre s’est entièrement brisée, la terre s’est entièrement écrasée, la terre s’est entièrement remuée de sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'La terre chancellera entièrement comme un homme ivre, et sera transportée comme une loge, et son forfait s’appesantira sur elle, tellement qu’elle tombera, et ne se relèvera plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'Et il arrivera en ce jour-là, que l’Eternel visitera dans un lieu élevé l’armée superbe, et les Rois de la terre, sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'Et ils seront assemblés en troupe comme des prisonniers dans une fosse; et ils seront enfermés dans une prison, et après plusieurs jours ils seront visités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'La lune rougira, et le soleil sera honteux, quand l’Eternel des armées régnera en la montagne de Sion, et à Jérusalem; et ce ne sera que gloire en la présence de ses Anciens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Eternel, tu es mon Dieu, je t’exalterai, je célébrerai ton nom, car tu as fait des choses merveilleuses; les conseils pris dès longtemps se sont trouvés être la fermeté même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Car tu as fait de la ville un monceau de pierres, et de la forte cité une ruine; le palais des étrangers qui était dans la ville, ne sera jamais rebâti.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Et à cause de cela le peuple fort te glorifiera, la ville des nations redoutables te révérera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Parce que tu as été la force du chétif, la force du misérable en sa détresse, le refuge contre le débordement, l’ombrage contre le hâle; car le souffle des terribles est comme un débordement qui abattrait une muraille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Tu rabaisseras la tempête éclatante des étrangers, comme le hâle est rabaissé dans un pays sec, le hâle, dis-je, par l’ombre d’une nuée; le branchage des terribles sera abattu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Et l’Eternel des armées fera à tous les peuples en cette montagne un banquet de choses grasses, un banquet de vins étant sur leur mère, un banquet, dis-je, de choses grasses et moelleuses, et de vins étant sur leur mère, bien purifiés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Et il enlèvera en cette montagne l’enveloppe redoublée qu’on voit sur tous les peuples, et la couverture qui est étendue sur toutes les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Il détruira la mort par sa victoire; et le Seigneur l’Eternel essuiera les larmes de dessus tout visage, et il ôtera l’opprobre de son peuple de dessus toute la terre; car l’Eternel a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Et l’on dira en ce jour-là; voici, c’est ici notre Dieu; nous l’avons attendu, aussi nous sauvera-t-il; c’est ici l’Eternel; nous l’avons attendu; nous nous égayerons, et nous réjouirons de son salut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Car la main de l’Eternel reposera sur cette montagne; mais Moab sera foulé sous lui, comme on foule la paille pour en faire du fumier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Et il étendra ses mains au travers de lui, comme celui qui nage les étend pour nager, et il rabaissera sa fierté, se faisant ouverture avec ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Et il abaissera la forteresse des plus hautes retraites de tes murailles, il les renversera, il les jettera à terre, et les réduira en poussière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'En ce jour-là ce Cantique sera chanté au pays de Juda; nous avons une ville forte; la délivrance y sera mise pour muraille et pour avant-mur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Ouvrez les portes, et la nation juste, celle qui garde la fidélité, y entrera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'C’est une délibération arrêtée, que tu conserveras la vraie paix; car on se confie en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Confiez-vous en l’Eternel à perpétuité; car le rocher des siècles est en l’Eternel Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Car il abaissera ceux qui habitent aux lieux haut élevés, il renversera la ville de haute retraite, il la renversera jusqu’en terre, il la réduira jusqu’à la poussière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Le pied marchera dessus; les pieds, dis-je, des affligés, les plantes des chétifs marcheront dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Le sentier est uni au juste; tu dresses au niveau le chemin du juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Aussi t’avons-nous attendu, ô Eternel! dans le sentier de tes jugements, et le désir de notre âme tend vers ton Nom, et vers ton mémorial.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'De nuit je t’ai désiré de mon âme, et dès le point du jour je te rechercherai de mon esprit, qui est au dedans de moi; car lorsque tes jugements sont en la terre, les habitants de la terre habitable apprennent la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Est-il fait grâce au méchant? il n’en apprend point la justice, mais il agira méchamment en la terre de la droiture, et il ne regardera point à la majesté de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Eternel, ta main est-elle haut élevée? ils ne l’ aperçoivent point; mais ils l’ apercevront, et ils seront honteux à cause de la jalousie que tu montres en faveur de ton peuple; et le feu dont tu punis tes ennemis les dévorera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Eternel! tu nous procureras la paix: car aussi c’est toi qui prends soin de tout ce qui nous regarde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Eternel notre Dieu, d’autres Seigneurs que toi nous ont maîtrisés, mais c’est par toi seul que nous faisons mention de ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Ils sont morts, ils ne vivront plus; ils sont trépassés, ils ne se relèveront point, parce que tu les as visités et exterminés, et que tu as fait périr toute mémoire d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Eternel, tu avais accru la nation, tu avais accru la nation, tu as été glorifié, mais tu les as jetés loin dans tous les bouts de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Eternel, étant en détresse ils se sont rendus auprès de toi, ils ont supprimé leur humble requête quand ton châtiment a été sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Comme celle qui est enceinte est en travail, et crie dans ses tranchées, lorsqu’elle est prête d’enfanter; tels avons-nous été à cause de ton courroux, ô Eternel!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Nous avons conçu, et nous avons été en travail; nous avons comme enfanté du vent, nous ne saurions en aucune manière délivrer le pays, et les habitants de la terre habitable ne tomberaient point par notre force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Tes morts vivront, même mon corps mort vivra; ils se relèveront. Réveillez-vous et vous réjouissez avec chant de triomphe, vous habitants de la poussière; car ta rosée est comme la rosée des herbes, et la terre jettera dehors les trépassés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Va, mon peuple, entre dans tes cabinets, et ferme ta porte sur toi; cache-toi pour un petit moment, jusques à ce que l’indignation soit passée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Car voici, l’Eternel s’en va sortir de son lieu pour visiter l’iniquité des habitants de la terre, commise contre lui; alors la terre découvrira le sang qu’elle aura reçu, et ne couvrira plus ceux qu’on a mis à mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'En ce jour-là l’Eternel punira de sa dure et grande et forte épée, le Léviathan, le serpent traversant; le Léviathan, dis-je serpent tortu, et il tuera la baleine qui est dans la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'En ce jour-là chantez, vous entre-répondant l’un à l’autre, touchant la vigne fertile en vin rouge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'C’est moi l’Eternel qui la garde, je l’arroserai de moment en moment, je la garderai nuit et jour, afin que personne ne lui fasse du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Il n’y a point de fureur en moi; qui m’opposera des ronces et des épines pour les combattre? je marcherai sur elles, je les brûlerai toutes ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Ou forcerait-il ma force? Qu’il fasse la paix avec moi, qu’il fasse la paix avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Il fera ci-après que Jacob prendra racine; Israël boutonnera, et s’épanouira; et ils rempliront de fruit le dessus de la terre habitable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'L’aurait-il frappé de la même plaie dont il frappe celui qui l’a frappé? et aurait-il été tué comme ont été tués ceux qu’il a tués?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Tu plaideras avec elle modérément, quand tu la renverras; même quand il ferait retentir son vent rude, au jour du vent d’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'C’est pourquoi l’expiation de l’iniquité de Jacob sera faite par ce moyen, et ceci en sera le fruit entier, que son péché sera ôté; quand il aura mis toutes les pierres de l’autel comme des pierres de plâtre menuisées, et lorsque les bocages, et les tabernacles ne seront plus debout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Car la ville munie sera désolée, le logement agréable sera abandonné et délaissé comme un désert, le veau y paîtra, il y gîtera, et il broutera les branches qui y seront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Quand son branchage sera sec il sera brisé, et les femmes y venant en allumeront du feu; car ce n’est pas un peuple intelligent, c’est pourquoi celui qui l’a fait n’aura point pitié de lui, et celui qui l’a formé ne lui fera point de grâce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Il arrivera donc en ce jour-là, que l’Eternel secouera depuis le cours du fleuve, jusqu’au torrent d’Egypte; mais vous serez glanés un à un, ô enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Et il arrivera en ce jour-là, qu’on sonnera du grand cor, et ceux qui s’étaient perdus au pays d’Assyrie, et ceux qui avaient été chassés au pays d’Egypte, reviendront, et se prosterneront devant l’Eternel, en la sainte montagne, à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Malheur à la couronne de fierté, des ivrognes d’Ephraïm, la noblesse de la gloire duquel n’est qu’une fleur qui tombe; ceux qui sont sur le sommet de la grasse vallée sont étourdis de vin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Voici, le Seigneur a en main un fort et puissant homme, ressemblant à une tempête de grêle, à un tourbillon qui brise tout, à une tempête de grosses eaux débordées; il jettera tout par terre avec la main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'La couronne de fierté et les ivrognes d’Ephraïm seront foulés aux pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Et la noblesse de sa gloire qui est sur le sommet de la grasse vallée ne sera qu’une fleur qui tombe; ils seront comme les fruits hâtifs avant l’Eté, lesquels incontinent que quelqu’un a vus, il les dévore dès qu’il les a dans sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'En ce jour-là l’Eternel des armées sera pour couronne de noblesse, et pour diadème de gloire au résidu de son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'Et pour esprit de jugement à celui qui sera assis sur le siège de jugement; et pour force à ceux qui dans le combat feront retourner les commis jusques à la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Mais ceux-ci aussi se sont oubliés dans le vin, et se sont fourvoyés dans la cervoise; le Sacrificateur et le Prophète se sont oubliés dans la cervoise; ils ont été engloutis par le vin, ils se sont fourvoyés a cause de la cervoise; ils se sont oubliés dans la vision, ils ont bronché dans le jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Car toutes leurs tables ont été couvertes de ce qu’ils ont rendu et de leurs ordures; tellement qu’il n’y a plus de place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'A qui enseignerait-on la science, et à qui ferait-on entendre l’enseignement? ils sont comme ceux qu’on vient de sevrer, et de retirer de la mamelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Car il faut leur donner commandement après commandement; commandement après commandement; ligne après ligne; ligne après ligne; un peu ici, un peu là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'C’est pourquoi il parlera à ce peuple-ci avec un bégayement de lèvres, et une langue étrangère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'Il lui avait dit; c’est ici le repos, que vous donniez du repos à celui qui est lassé, et c’est ici le soulagement; mais ils n’ont point voulu écouter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Ainsi la parole de l’Eternel leur sera commandement après commandement; commandement après commandement; ligne après ligne; ligne après ligne; un peu ici, un peu là; afin qu’ils aillent et tombent à la renverse, et qu’ils soient brisés; et afin qu’ils tombent dans le piége, et qu’ils soient pris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'C’est pourquoi écoutez la parole de l’Eternel, vous hommes moqueurs, qui dominez sur ce peuple qui est à Jérusalem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Car vous avez dit; nous avons fait accord avec la mort, et nous avons intelligence avec le sépulcre; quand le fléau débordé traversera, il ne viendra point sur nous, car nous avons mis le mensonge pour notre retraite, et nous nous sommes cachés sous la fausseté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'C’est pourquoi ainsi a dit le Seigneur, l’Eternel; voici je mettrai pour fondement une pierre en Sion, une pierre éprouvée, la pierre de l’angle le plus précieux, pour être un fondement solide; celui qui croira ne se hâtera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Et je mettrai le jugement à l’équerre, et la justice au niveau; et la grêle détruira la retraite du mensonge, et les eaux inonderont le lieu où l’on se retirait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Et votre accord avec la mort sera aboli, et votre intelligence avec le sépulcre ne tiendra point; quand le fléau débordé traversera, vous en serez foulés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Dès qu’il traversera il vous emportera; or il traversera tous les matins, de jour, et de nuit; et dès qu’on en entendra le bruit il n’y aura que remuement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Car le lit sera trop court, et on ne pourra pas s’y étendre; et la couverture trop étroite quand on se voudra envelopper.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Parce que l’Eternel se lèvera comme en la montagne de Pératsim, et il sera ému comme dans la vallée de Gabaon, pour faire son oeuvre, son oeuvre extraordinaire, et pour faire son travail, son travail non accoutumé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Maintenant donc ne vous moquez plus, de peur que vos liens ne soient renforcés, car j’ai entendu de par le Seigneur l’Eternel des armées une consomption, qui est même déterminée sur tout le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Prêtez l’oreille, et écoutez ma voix; soyez attentifs, et écoutez mon discours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Celui qui laboure pour semer, labourera-t-il tous les jours? ne cassera-t-il pas, et ne rompra-t-il pas les mottes de sa terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Quand il en aura égalé le dessus, ne sèmera-t-il pas la vesce; ne répandra-t-il pas le cumin, ne mettra-t-il pas le froment au meilleur endroit, et l’orge en son lieu assigné, et l’épeautre en son quartier?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Parce que son Dieu l’instruit et l’enseigne touchant ce qu’il faut faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Car on ne foule pas la vesce avec la herse, et on ne tourne point la roue du chariot sur le cumin; mais on bat la vesce avec la verge, et le cumin avec le bâton.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Le blé dont on fait le pain se menuise,car le laboureur ne saurait jamais le fouler entièrement, et quoiqu’il l’écrase avec la roue de son chariot, néanmoins il ne le menuisera pas avec ses chevaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Ceci aussi procède de l’Eternel des armées, qui est admirable en conseil, et magnifique en moyens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Malheur à Ariel, à Ariel, la ville où David s’est campé; ajoutez année sur année, qu’on égorge des victimes pour les Fêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Mais je mettrai Ariel à l’étroit, et la ville ne sera que tristesse et que deuil, et elle me sera comme Ariel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Car je me camperai en rond contre toi, et je t’assiégerai avec des tours, et je dresserai contre toi des forts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Et tu seras abaissée, et tu parleras comme de dedans la terre, et ta parole sera basse, comme si elle sortait de la poussière, et ta voix, comme celle d’un esprit de Python, sortira de la terre, et ta parole marmottera comme si elle sortait de la poussière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Et la multitude de tes étrangers sera comme de la poudre menue; et la multitude des terribles sera comme de la balle qui passe, et cela sera pour un petit moment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Elle sera visitée par l’Eternel des armées avec des tonnerres, et avec des tremblements de terre, et avec un grand bruit, tempête, tourbillon, et flamme de feu dévorant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Et la multitude de toutes les nations qui feront la guerre à Ariel, et tous ceux qui combattront contre la ville, et ceux qui la serreront de près, seront comme un songe d’une vision de nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Et il arrivera, que comme celui qui a faim, songe qu’il mange, mais quand il est réveillé, son âme est vide; et comme celui qui a soif, songe qu’il boit, mais quand il est réveillé, il est las, et son âme est altérée, ainsi sera la multitude de toutes les nations qui combattront contre la montagne de Sion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Arrêtez-vous, et vous étonnez; écriez-vous, et criez; Ils se sont enivrés, mais non pas de vin; ils chancellent, mais non pas à cause de la cervoise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Car l’Eternel a répandu sur vous un esprit d’un profond dormir; il a bouché vos yeux; il a bandé ceux de vos Prophètes, et de vos principaux Voyants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Et toute vision vous sera comme les paroles d’un livre cacheté qu’on donnerait à un homme de lettres en lui disant; Nous te prions, lis ceci; et il répondrait: Je ne saurais, car il est cacheté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'Puis si on le donnait à quelqu’un qui ne fût point homme de lettres, en lui disant; nous te prions, lis ceci; il répondrait; je ne sais point lire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'C’est pourquoi le Seigneur dit; parce que ce peuple s’approche de moi de sa bouche, et qu’ils m’honorent de leurs lèvres, mais qu’il a éloigné son coeur de moi, et parce que la crainte qu’ils ont de moi est un commandement d’hommes, enseigné par des hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'A cause de cela, voici, je continuerai de faire à l’égard de ce peuple-ci des merveilles et des prodiges étranges: c’est que la sapience de ses sages périra, et l’intelligence de ses hommes savants disparaîtra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Malheur à ceux qui veulent aller plus loin que l’Eternel, pour cacher leur conseil, et dont les oeuvres sont dans les ténèbres, et qui disent; qui nous voit, et qui nous aperçoit?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Ce que vous renversez ne sera-t-il pas réputé comme l’argile d’un potier? même, l’ouvrage dira-t-il de celui qui l’a fait: il ne m’a point fait? et la chose formée dira-t-elle de celui qui l’a formée; il n’y entendait rien?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Le Liban ne sera-t-il pas encore dans très-peu de temps changé en un Carmel? et Carmel ne sera-t-il pas réputé comme une forêt?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Et les sourds entendront en ce jour-là les paroles du livre, et les yeux des aveugles étant délivrés de l’obscurité et des ténèbres, verront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Et les débonnaires auront joie sur joie en l’Eternel, et les pauvres d’entre les hommes s’égayeront au Saint d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Car le terrible prendra fin, et le moqueur sera consumé, et tous ceux qui veillent pour commettre l’iniquité, seront retranchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'Ceux qui font tenir pour coupables les hommes pour une parole, et qui tendent des pièges à celui qui les reprend en la porte, et qui font tomber le juste en confusion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'C’est pourquoi l’Eternel, qui a racheté Abraham, a dit ainsi touchant la maison de Jacob; Jacob ne sera plus honteux, et sa face ne pâlira plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Car quand il verra ses fils être un ouvrage de mes mains au milieu de lui, ils sanctifieront mon Nom; ils sanctifieront, dis-je, le Saint de Jacob, et redouteront le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Et ceux dont l’Esprit s’était fourvoyé deviendront prudents; et ceux qui murmuraient apprendront la doctrine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Malheur aux enfants revêches, dit l’Eternel, qui prennent conseil, et non pas de moi; et qui se forgent des idoles, où mon esprit n’est point, afin d’ajouter péché sur péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'Qui sans avoir interrogé ma bouche marchent pour descendre en Egypte, afin de se fortifier de la force de Pharaon, et se retirer sous l’ombre d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Car la force de Pharaon vous tournera à honte, et la retraite sous l’ombre d’Egypte vous tournera à confusion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Car les principaux de son peuple ont été à Tsohan, et ses messagers sont parvenus jusques à Hanès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Tous seront rendus honteux par un peuple qui ne leur profitera de rien, ils n’en recevront aucun secours ni aucun avantage, mais il sera leur honte, et leur opprobre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Les bêtes seront chargées pour aller au Midi; ils porteront leurs richesses sur les dos des ânons, et leurs trésors sur la bosse des chameaux, vers le peuple qui ne leur profitera point, au pays de détresse et d’angoisse, d’où viennent le vieux lion, et le lion, la vipère, et le serpent brûlant qui vole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Car le secours que les Egyptiens leur donneront ne sera que vanité, et qu’un néant; c’est pourquoi j’ai crié ceci; leur force est de se tenir tranquilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Entre donc maintenant, et l’écris en leur présence sur une table, et rédige-le par écrit dans un livre,afin que cela demeure pour le temps à venir, à perpétuité, à jamais;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Que c’est ici un peuple rebelle, des enfants menteurs, des enfants qui ne veulent point écouter la Loi de l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'Qui ont dit aux Voyants; ne voyez point; et à ceux qui voient des visions; ne voyez point de visions de justice, mais dites-nous des choses agréables, voyez des visions trompeuses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Retirez-vous du chemin, détournez-vous du sentier, faites cesser le Saint d’Israël de devant nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'C’est pourquoi ainsi a dit le Saint d’Israël; parce que vous avez rejeté cette parole, et que vous vous êtes confiés en l’oppression, et en vos moyens obliques, et que vous vous êtes appuyés sur ces choses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'A cause de cela cette iniquité vous sera comme la fente d’une muraille qui s’en va tomber, faisant ventre jusques au haut, de laquelle la ruine vient soudainement, et en un moment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'Il la brisera donc comme on brise une bouteille d’un potier de terre qui est cassée, laquelle on n’épargne point, et des pièces de laquelle ne se trouverait pas un têt pour prendre du feu du foyer, ou pour puiser de l’eau d’une fosse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Car ainsi avait dit le Seigneur, l’Eternel, le Saint d’Israël; en vous tenant tranquilles et en repos vous serez délivrés, votre force sera en vous tenant en repos et en espérance; mais vous ne l’avez point agréé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Et vous avez dit; non, mais nous nous enfuirons sur des chevaux; à cause de cela vous vous enfuirez. Et vous avez dit; nous monterons sur des chevaux légers; à cause de cela ceux qui vous poursuivront seront légers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Mille d’entre vous s’enfuiront à la menace d’un seul; vous vous enfuirez à la menace de cinq; jusqu’à ce que vous soyez abandonnés comme un arbre tout ébranché au sommet d’une montagne, et comme un étendard sur un coteau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Et cependant l’Eternel attend pour vous faire grâce, et ainsi il sera exalté en ayant pitié de vous; car l’Eternel est le Dieu de jugement; ô que bienheureux sont tous ceux qui se confient en lui!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Car le peuple demeurera dans Sion, et dans Jérusalem; tu ne pleureras point; certes il te fera grâce sitôt qu’il aura ouï ton cri; sitôt qu’il t’aura ouï, il t’exaucera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Le Seigneur vous donnera du pain de détresse, et de l’eau d’angoisse, mais tes Docteurs ne s’envoleront plus, et tes yeux verront tes Docteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'Et tes oreilles entendront la parole de celui qui sera derrière toi, disant; c’est ici le chemin, marchez-y; soit que vous tiriez à droite, soit que vous tiriez à gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Et vous tiendrez pour souillés les chapiteaux des images taillées, faites de l’argent d’un chacun de vous, et les ornements faits de l’or fondu d’un chacun de vous; tu les jetteras au loin, comme un sang impur; et tu diras; videz-le dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Et il donnera la pluie sur tes semailles, quand tu auras semé en la terre; et le grain du revenu de la terre sera abondant, et bien nourri; en ce jour-là ton bétail paîtra dans une campagne spacieuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Et les boeufs et les ânes qui labourent la terre mangeront le pur fourrage de ce qui aura été vanné avec la pelle et le van.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Et il y aura des ruisseaux d’eaux courantes sur toute haute montagne, et sur tout coteau haut élevé, au jour de la grande tuerie, quand les tours tomberont.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Et la lumière de la lune sera comme la lumière du soleil; et la lumière du soleil sera sept fois aussi grande, comme si c’était la lumière de sept jours, au jour que l’Eternel aura bandé la froissure de son peuple, et qu’il aura guéri la blessure de sa plaie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Voici, le Nom de l’Eternel vient de loin, sa colère est ardente, et une pesante charge; ses lèvres sont remplies d’indignation, et sa langue est comme un feu dévorant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'Et son Esprit est comme un torrent débordé, qui atteint jusques au milieu du cou, pour disperser les nations, d’une telle dispersion, qu’elles seront réduites à néant; et il est comme une bride aux mâchoires des peuples, qui les fera aller à travers champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Vous aurez un cantique tel que celui de la nuit en laquelle on se prépare à célébrer une fête solennelle; et vous aurez une allégresse de coeur telle qu’a celui qui marche avec la flûte, pour venir en la montagne de l’Eternel, vers le rocher d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Et l’Eternel fera entendre sa voix, pleine de majesté, et il fera voir où aura assené son bras dans l’indignation de sa colère, avec une flamme de feu dévorant, avec éclat, tempête, et pierres de grêle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Car l’Assyrien, qui frappait du bâton, sera effrayé par la voix de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'Et partout ou passera le bâton enfoncé dont l’Eternel l’aura assené, et par lequel il aura combattu dans les batailles à bras élevé, on y entendra des tambours et des harpes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Car Topheth est déjà préparée, et même elle est apprêtée pour le Roi; il l’a faite profonde et large; son bûcher c’est du feu, et force bois; le souffle de l’Eternel l’allumant comme un torrent de soufre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Malheur à ceux qui descendent en Egypte, pour avoir de l’aide, et qui s’appuient sur les chevaux, et qui mettent leur confiance en leurs chariots, quand ils sont en grand nombre; et en leurs gens de cheval, quand ils sont bien forts; et qui n’ont point regardé au Saint d’Israël, et n’ont point recherché l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Et cependant, c’est lui qui est sage; et il fait venir le mal, et ne révoque point sa parole; il s’élèvera contre la maison des méchants, et contre ceux qui aident aux ouvriers d’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Or les Egyptiens sont des hommes, et non pas le Dieu Fort; et leurs chevaux ne sont que chair, et non pas esprit; l’Eternel donc étendra sa main, et celui qui donne du secours sera renversé; et celui à qui le secours est donné tombera; et eux tous ensemble seront consumés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Mais ainsi m’a dit l’Eternel; Comme le lion et le lionceau rugit sur sa proie, et quoiqu’on appelle contre lui un grand nombre de bergers, il n’est point effrayé pour leur cri, et ne s’abaisse point pour leur bruit; ainsi l’Eternel des armées descendra pour combattre en faveur de la montagne de Sion, et de son coteau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Comme les oiseaux volent, ainsi l’Eternel des armées garantira Jérusalem, la garantissant et la délivrant, passant outre, et la sauvant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Retournez vers celui de qui les enfants d’Israël se sont étrangement éloignés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Car en ce jour-là chacun rejettera les idoles de son argent, et les idoles de son or, lesquelles vos mains vous ont faites pour vous faire pécher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Et l’Assyrien tombera par l’épée, qui ne sera point l’épée d’un vaillant homme,et l’épée qui ne sera point une épée d’homme le dévorera, et il s’enfuira de devant l’épée, et ses jeunes gens d’élite seront rendus tributaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Et saisi de frayeur il s’en ira à sa forteresse, et ses capitaines seront effrayés à cause de la bannière, dit l’Eternel, duquel le feu est dans Sion, et le fourneau dans Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Voici, un Roi régnera en justice, et les Princes présideront avec équité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Et ce personnage sera comme le lieu auquel on se retire à couvert du vent, et comme un asile contre la tempête; comme sont les ruisseaux d’eaux dans un pays sec, et l’ombre d’un gros rocher en une terre altérée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Alors les yeux de ceux qui voient, ne seront point retenus; et les oreilles de ceux qui entendent, seront attentives.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Et le coeur des étourdis entendra la science; et la langue des bègues parlera aisément, et nettement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Le chiche ne sera plus appelé libéral, et l’avare ne sera plus nommé magnifique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Car le chiche ne prononce que chicheté, et son coeur ne machine qu’iniquité, pour exécuter son déguisement, et pour proférer des choses fausses contre l’Eternel; pour rendre vide l’âme de l’affamé, et faire tarir la boisson à celui qui a soif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Les instruments de l’avare sont pernicieux; il prend des conseils pleins de machinations, pour attraper par des paroles de mensonge les affligés, même quand le pauvre parle droitement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Mais le libéral prend des conseils de libéralité, et se lève pour user de libéralité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Femmes qui êtes à votre aise, levez-vous, écoutez ma voix; filles qui vous tenez assurées, prêtez l’oreille à ma parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Dans un an et quelques jours au delà, vous qui vous tenez assurées, serez troublées; car la vendange a manqué; la récolte ne viendra plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Vous qui êtes à votre aise, tremblez; vous qui vous tenez assurées, soyez troublées; dépouillez-vous, quittez vos habits, et vous ceignez de sacs sur les reins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'On se frappe la poitrine, à cause de la vigne abondante en fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Les épines et les ronces monteront sur la terre de mon peuple; même sur toutes les maisons où il y a de la joie, et sur la ville qui s’égaye.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Car le palais s’en va être abandonné; la multitude de la cité s’en va être délaissée; les lieux inacceccibles du pays et les forteresses seront autant de cavernes à toujours; là se joueront les ânes sauvages, et les petits y paîtront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'Jusqu’à ce que l’Esprit soit versé d’en haut sur nous; et que le désert devienne un Carmel, et que Carmel soit réputé comme une forêt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Le jugement habitera au désert, et la justice se tiendra en Carmel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'La paix sera l’effet de la justice, et le labourage de la justice sera le repos et la sûreté, jusques à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Et mon peuple habitera en un logis paisible, et dans des pavillons assurés, et dans un repos fort tranquille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Mais la grêle tombera sur la forêt, et la ville sera entièrement abaissée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'O que vous êtes heureux, vous qui semez sur toutes les eaux, et qui y faites aller le pied du boeuf et de l’âne!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Malheur à toi qui fourrages, et qui n’as point été fourragé, et à toi, qui agis avec perfidie, et envers qui on n’a point usé de perfidie; sitôt que tu auras achevé de fourrager, tu seras fourragé; et sitôt que tu auras achevé d’agir avec perfidie, on te traitera avec perfidie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Eternel aie pitié de nous; nous nous sommes attendus à toi; sois leur bras dès le matin, et notre délivrance au temps de la détresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Les peuples se sont écartés à cause du son bruyant, les nations se sont dispersées à cause que tu t’es élevé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Et votre butin sera ramassé comme l’on ramasse les vermisseaux, on sautera sur lui comme sautellent les sauterelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'L’Eternel s’en va être exalté, car il habite en un lieu haut élevé; il remplira Sion de jugement et de justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Et la certitude de ta durée, et la force de tes délivrances sera la sagesse et la science; la crainte de l’Eternel sera son trésor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Voici, leurs hérauts crient dehors, et les messagers de paix pleurent amèrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Les chemins ont été réduits en désolation, les passants ne passent plus par les sentiers; il a rompu l’alliance, il a rejeté les villes, il ne fait pas même cas des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'On mène deuil; la terre languit, le Liban est sec et coupé; Saron est devenu comme une lande; et Basan et Carmel ont été ébranlés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Maintenant je me lèverai, dira l’Eternel, maintenant je serai exalté, maintenant je serai élevé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Vous concevrez de la balle, et vous enfanterez du chaume; votre souffle vous dévorera comme le feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Et les peuples seront comme des fourneaux de chaux; ils seront brûlés au feu comme des épines coupées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Vous qui êtes loin, écoutez ce que j’ai fait; et vous qui êtes près, connaissez ma force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Les pécheurs seront effrayés dans Sion, et le tremblement saisira les hypocrites, tellement qu’ils diront; Qui est-ce d’entre nous qui pourra séjourner avec le feu dévorant? Qui est-ce d’entre nous qui pourra séjourner avec les ardeurs éternelles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Celui qui observe la justice, et qui profère des choses droites; celui qui rejette le gain déshonnête d’extorsion, et qui secoue ses mains pour ne prendre point de présents; celui qui bouche ses oreilles pour n’ouïr point le sang, et qui ferme ses yeux pour ne voir point le mal;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'Celui-là habitera en des lieux haut élevés; des forteresses assises sur des rochers seront sa haute retraite; son pain lui sera donné, et ses eaux ne lui manqueront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Tes yeux contempleront le Roi en sa beauté; et ils regarderont la terre éloignée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Ton coeur méditera-t-il la frayeur? en disant; où est le secrétaire? où est celui qui pèse? où est celui qui tient le compte des tours?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Tu ne verras point le peuple fier, peuple de langage inconnu, qu’on n’entend point; et de langue bégayante, qu’on ne comprend point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Regarde Sion, la ville de nos fêtes solennelles, que tes yeux voient Jérusalem, séjour tranquille, tabernacle qui ne sera point transporté, et dont les pieux ne seront jamais ôtés, ni aucun de ses cordeaux ne sera rompu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Car c’est là vraiment que l’Eternel nous est magnifique; c’est le lieu des fleuves, et des rivières très larges, dans lequel n’ira point de navire à rame, et où aucun gros navire ne passera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Parce que l’Eternel est notre Juge, l’Eternel est notre Législateur, l’Eternel est notre Roi; c’est lui qui vous sauvera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Tes cordages sont lâchés, et ainsi ils ne tiendront point ferme leur mât, et on n’étendra point la voile; alors la dépouille d’un grand butin sera partagée; les boiteux même pilleront le butin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'Et celui qui fera sa demeure dans la maison, ne dira point; je suis malade; le peuple qui habitera en elle, sera déchargé d’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Approchez-vous, nations, pour écouter, et vous peuples, soyez attentifs; que la terre et tout ce qui est en elle, écoute; que le monde habitable et tout ce qui y est produit, écoute;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Car l’indignation de l’Eternel est sur toutes ces nations, et sa fureur sur toute leur armée; il les a mises à l’interdit, il les a livrées pour être tuées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Leurs blessés à mort seront jetés là, et la puanteur de leurs corps morts se répandra, et les montagnes découleront de leur sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Et toute l’armée des cieux se fondra, et les cieux seront mis en rouleau comme un livre, et toute leur armée tombera, comme tombe la feuille de la vigne, et comme tombe celle du figuier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Parce que mon épée est enivrée dans les cieux, voici, elle descendra en jugement contre Edom, et contre le peuple que j’ai mis à l’interdit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'L’épée de l’Eternel est pleine de sang; elle s’est engraissée de sa graisse et du sang des agneaux, et des boucs, et de la graisse des rognons de moutons; car il y a un sacrifice à l’Eternel dans Botsra, et une grande tuerie au pays d’Edom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Et les licornes descendront avec eux, et les veaux avec les taureaux; leur terre sera enivrée de sang, et leur poussière sera engraissée de graisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Car il y a un jour de vengeance à l’Eternel, et une année de rétribution pour maintenir le droit de Sion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Et ses torrents seront changés en poix, et sa poussière en soufre, et sa terre deviendra de la poix ardente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Elle ne sera point éteinte ni nuit ni jour; sa fumée montera éternellement, elle sera désolée de génération en génération; il n’y aura personne qui passe par elle à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Et le cormoran et le butor la posséderont, le hibou et le corbeau y habiteront; et on étendra sur elle la ligne de confusion, et le niveau de désordre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Ses magistrats crieront qu’il n’y a plus là de Royaume, et tous ses gouverneurs seront réduits à rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Les épines croîtront dans ses palais, les chardons et les buissons dans ses forteresses, et elle sera le repaire des dragons, et le parvis des chats-huants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Là les bêtes sauvages des déserts rencontreront les bêtes sauvages des Iles, et la chouette criera à sa compagne; là même se posera l’orfraie, et y trouvera son repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Là le martinet fera son nid, il y couvera, il y éclôra, et il recueillera ses petits sous son ombre; et là aussi seront assemblés les vautours l’un avec l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Recherchez au Livre de l’Eternel, et lisez: il ne s’en est pas manqué un seul point; celle-là ni sa compagne n’y ont point manqué; car c’est ma bouche qui l’a commandé, et son Esprit est celui qui les aura assemblés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Car il leur a jeté le sort, et sa main leur a distribué cette terre au cordeau; ils la posséderont à toujours, ils y habiteront d’âge en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Le désert et le lieu aride se réjouiront, et le lieu solitaire s’égayera, et fleurira comme une rose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Il fleurira abondamment, et s’égayera, s’égayant même et chantant en triomphe. La gloire du Liban lui est donnée, avec la magnificence de Carmel et de Saron, ils verront la gloire de l’Eternel, et la magnificence de notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Renforcez les mains lâches, et fortifiez les genoux tremblants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Dites à ceux qui ont le coeur troublé; prenez courage, et ne craignez plus; voici votre Dieu; la vengeance viendra, la rétribution de Dieu; il viendra lui-même, et vous délivrera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Alors les yeux des aveugles seront ouverts, et les oreilles des sourds seront débouchées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Alors le boiteux sautera comme un cerf, et la langue du muet chantera en triomphe; car des eaux sourdront au désert; et des torrents, au lieu solitaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Et les lieux qui étaient secs, deviendront des étangs, et la terre altérée deviendra des sources d’eaux, et dans les repaires des dragons où ils faisaient leur gîte, il y aura un parvis à roseaux et à joncs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Et il y aura là un sentier et un chemin, qui sera appelé le chemin de sainteté; celui qui est souillé n’y passera point, mais il sera pour ceux-là; celui qui va son chemin, et les fous, ne s’y égareront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Là il n’y aura point de lion, et aucune de ces bêtes qui ravissent les autres, n’y montera point, et ne s’y trouvera point; mais les rachetés y marcheront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Ceux donc desquels l’Eternel aura payé la rançon, retourneront, et viendront en Sion avec chant de triomphe, et une joie éternelle sera sur leur tête; ils obtiendront la joie et l’allégresse; la douleur et le gémissement s’enfuiront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Or il arriva la quatorzième année du Roi Ezéchias, que Sennachérib, Roi des Assyriens, monta contre toutes les villes closes de Juda, et les prit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Puis le roi des Assyriens envoya Rabsaké avec de grandes forces de Lachis à Jérusalem, vers le roi Ezéchias, et il se présenta près du conduit du haut étang, au grand chemin du champ du foulon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Et Eliakim, fils de Hilkija, Maître d’hôtel, et Sebna le Secrétaire, et Joab fils d’Asaph, commis sur les registres, sortirent vers lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Et Rabsaké leur dit; dites maintenant à Ezéchias; ainsi dit le grand Roi, le Roi des Assyriens; quelle est cette confiance que tu as?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Je te dis que ce ne sont là que des paroles; mais le conseil et la force sont requis à la guerre: or maintenant sur qui t’es-tu confié, que tu te sois rebellé contre moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Voici, tu t’es confié sur ce bâton qui n’est qu’un roseau cassé, sur l’Egypte, sur lequel si quelqu’un s’appuie, il lui entrera dans la main, et la percera; tel est Pharaon Roi d’Egypte à tous ceux qui se confient en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Que si tu me dis; nous nous confions en l’Eternel, notre Dieu; n’est-ce pas celui-là même duquel Ezéchias a ôté les hauts lieux et les autels, et a dit à Juda et à Jérusalem; vous vous prosternerez devant cet autel-ci?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Maintenant donc donne des otages au Roi des Assyriens mon maître; et je te donnerai deux mille chevaux, si tu peux donner autant d’hommes pour monter dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Et comment ferais-tu tourner visage au moindre gouverneur d’entre les serviteurs de mon maître? mais tu te confies en l’Egypte, à cause des chariots, et des gens de cheval.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Mais suis-je maintenant monté sans l’Eternel contre ce pays pour le détruire? L’Eternel m’a dit; monte contre ce pays-là, et le détruis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Alors Eliakim, et Sebna, et Joab dirent à Rabsaké; nous te prions de parler en langue syriaque à tes serviteurs, car nous l’entendons; mais ne parle point à nous en langue Judaïque, pendant que le peuple, qui est sur la muraille, l’écoute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Et Rabsaké répondit; mon maître m’a-t-il envoyé vers ton maître, ou vers toi, pour dire ces paroles-là? ne m’a-t-il pas envoyé vers les hommes qui se tiennent sur la muraille, pour leur dire qu’ils mangeront leur propre fiente, et qu’ils boiront leur urine avec vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Rabsaké donc se dressa, et s’écria à haute voix en langue Judaïque, et dit; écoutez les paroles du grand Roi, le Roi des Assyriens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Le Roi a dit ainsi; qu’Ezéchias ne vous abuse point; car il ne vous pourra pas délivrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Et qu’Ezéchias ne vous fasse point confier en l’Eternel, en disant; l’Eternel indubitablement nous délivrera; cette ville ne sera point livrée entre les mains du Roi des Assyriens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'N’écoutez point Ezéchias; car ainsi a dit le Roi des Assyriens; faites un accord pour votre bien avec moi, et sortez vers moi, et vous mangerez chacun de sa vigne, et chacun de son figuier, et vous boirez chacun de l’eau de sa citerne;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'Jusqu’à ce que je vienne, et que je vous emmène en un pays qui est comme votre pays, un pays de froment et de bon vin, un pays de pain et de vignes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Qu’Ezéchias donc ne vous séduise point, en disant; L’Eternel nous délivrera. Les dieux des nations ont-ils délivré chacun leur pays de la main du Roi des Assyriens?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Où sont les dieux de Hamath et d’Arpad? où sont les dieux de Sépharvajim? et même a-t-on délivré Samarie de ma main?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Qui sont ceux d’entre tous les dieux de ces pays-là qui aient délivré leur pays de ma main, pour dire que l’Eternel délivrera Jérusalem de ma main?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Mais ils se turent, et ne lui répondirent pas un mot; car le Roi avait commandé, disant; vous ne lui répondrez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Après cela Eliakim fils de Hilkija, Maître d’hôtel et Sebna le Secrétaire, et Joab fils d’Asaph, commis sur les registres, s’en revinrent, les vêtements déchirés, vers Ezéchias, et lui rapportèrent les paroles de Rabsaké.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Et il arriva qu’aussitôt que le Roi Ezéchias eut entendu ces choses, il déchira ses vêtements, et se couvrit d’un sac; et entra dans la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Puis il envoya Eliakim Maître d’hôtel, et Sebna le Secrétaire, et les anciens d’entre les Sacrificateurs, couverts de sacs, vers Esaïe le Prophète fils d’Amots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Et ils lui dirent; ainsi a dit Ezéchias; ce jour-ci est le jour d’angoisse, et de répréhension, et de blasphème; car les enfants sont venus jusqu’à l’ouverture de la matrice, mais il n’y a point de force pour enfanter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Peut-être que l’Eternel ton Dieu aura entendu les paroles de Rabsaké, lequel le Roi des Assyriens son maître a envoyé pour blasphémer le Dieu vivant, et lui faire outrage, selon les paroles que l’Eternel ton Dieu a ouïes; fais donc requête pour le reste qui se trouve encore.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Les serviteurs donc du Roi Ezéchias vinrent vers Esaïe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Et Esaïe leur dit; vous direz ainsi à votre maître; ainsi a dit l’Eternel; ne crains point pour les paroles que tu as entendues, par lesquelles les serviteurs du roi du Roi des Assyriens m’ont blasphémé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Voici, je m’en vais mettre en lui un tel esprit, qu’ayant entendu un certain bruit, il retournera en son pays, et je le ferai tomber par l’épée dans son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Or quand Rabsaké s’en fut retourné, il alla trouver le Roi des Assyriens, qui battait Libna; car Rabsaké avait appris qu’il était parti de Lachis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Le Roi donc des Assyriens ouït dire touchant Tirhaka Roi d’Ethiopie; il est sorti pour te combattre; ce qu’ayant entendu, il envoya des messagers vers Ezéchias, en leur disant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'Vous parlerez ainsi à Ezéchias Roi de Juda, disant; que ton Dieu auquel tu te confies, ne t’abuse point, en disant; Jérusalem ne sera point livrée en la main du Roi des Assyriens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Voilà, tu as entendu ce que les Rois des Assyriens ont fait à tous les pays, en les détruisant entièrement; et tu échapperais?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Les dieux des nations que mes ancêtres ont détruites, savoir de Gozan, de Charan, de Retseph, et des enfants d’Héden, qui sont en Phélasar, les ont-ils délivrées?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Où est le Roi de Hamath, et le Roi d’Arpad, et le Roi de la ville de Sépharvajim, Hénah et Hivah?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Et quand Ezéchias eut reçu les Lettres de la main des messagers, et les eut lues, il monta en la maison de l’Eternel, et Ezéchias les déploya devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Puis Ezéchias fit sa prière à l’Eternel, en disant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'O Eternel des armées! Dieu d’Israël! qui es assis entre les Chérubins; toi seul es le Dieu de tous les royaumes de la terre; tu as fait les cieux et la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'O Eternel! incline ton oreille, et écoute; ô Eternel!ouvre tes yeux, et regarde, et écoute toutes les paroles de Sanchérib, lesquelles il m’a envoyé dire pour blasphémer le Dieu vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Il est bien vrai, ô Eternel! que les Rois des Assyriens ont détruit tous les pays, et leurs contrées;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'Et qu’ils ont jeté au feu leurs dieux; car ce n’étaient point des dieux; mais un ouvrage de main d’homme, du bois et de la pierre; c’est pourquoi ils les ont détruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Maintenant donc, ô Eternel notre Dieu! délivre-nous de la main de Sanchérib, afin que tous les Royaumes de la terre sachent que toi seul es l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Alors Esaïe fils d’Amots envoya vers Ezéchias, pour lui dire; ainsi a dit l’Eternel, le Dieu d’Israël; quant à ce dont tu m’as requis touchant Sanchérib Roi des Assyriens;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'C’est ici la parole que l’Eternel a prononcée contre lui. La vierge fille de Sion, t’a méprisé, et s’est moquée de toi; la fille de Jérusalem a branlé la tête après toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Qui as-tu outragé et blasphémé? contre qui as-tu élevé ta voix, et levé tes yeux en haut? c’est contre le Saint d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Tu as outragé le Seigneur par le moyen de tes serviteurs, et tu as dit; je suis monté avec la multitude de mes chariots sur le haut des montagnes, aux côtés du Liban, je couperai les plus hauts cèdres, et les plus beaux sapins qui y soient, et j’entrerai jusques en son plus haut bout, et en la forêt de son Carmel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'J’ai creusé des sources, et j’en ai bu les eaux; et j’ai tari de la plante de mes pieds tous les ruisseaux des forteresses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'N’as-tu pas entendu que déjà dès longtemps j’ai fait cette ville, et que d’ancienneté je l’ai ainsi formée? et maintenant l’aurais-je conservée pour être réduite en désolation, et les villes munies, en monceaux de ruines?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Or leurs habitants étant dénués de force ont été épouvantés et confus, et sont devenus comme l’herbe des champs; et l’herbe verte, comme le foin des toits, qui est sec avant qu’il soit monté en tuyau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Mais je sais ton repaire, ta sortie, et ton entrée, et comment tu es furieux contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Parce que tu es furieux contre moi, et que ton insolence est montée à mes oreilles, je mettrai ma boucle en tes narines, et mon mors en ta bouche, et je te ferai retourner par le chemin par lequel tu es venu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Et ceci te sera pour signe, ô Ezéchias, c’est qu’on mangera cette année ce qui viendra de soi-même aux champs; et en la seconde année, ce qui croîtra encore sans semer; mais la troisième année, vous sèmerez et vous moissonnerez; vous planterez des vignes, et vous en mangerez le fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Et ce qui est réchappé, et demeuré de reste dans la maison de Juda, étendra sa racine par-dessous, et elle produira son fruit par- dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Car il sortira de Jérusalem quelques restes, et de la montagne de Sion quelques réchappés, la jalousie de l’Eternel des armées fera cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'C’est pourquoi ainsi a dit l’Eternel touchant le Roi des Assyriens; il n’entrera point en cette ville, et il n’y jettera aucune flèche, il ne se présentera point contr’elle avec le bouclier, et il ne dressera point de terrasse contr’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Il s’en retournera par le chemin par lequel il est venu, et il n’entrera point en cette ville, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Car je garantirai cette ville, afin de la délivrer pour l’amour de moi, et pour l’amour de David mon serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Un Ange donc de l’Eternel sortit, et tua cent quatre-vingt-cinq mille hommes au camp des Assyriens; et quand on fut levé de bon matin, voilà c’étaient tous des corps morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Et Sanchérib Roi des Assyriens partit de là, il s’en alla, et s’en retourna, et se tint à Ninive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Et il arriva qu’étant prosterné dans la maison de Nisroc son Dieu, Adrammélec et Saréetser ses fils le tuèrent avec l’épée; puis ils se sauvèrent au pays d’Ararat, et Esarhaddon son fils régna en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'En ces jours-là Ezéchias fut malade à la mort, et Esaïe le Prophète fils d’Amots vint vers lui, et lui dit; ainsi a dit l’Eternel; dispose de ta maison, car tu t’en vas mourir, et tu ne vivras plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Alors Ezéchias tourna sa face contre la muraille, et fit sa prière à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'Et dit; souviens-toi maintenant je te prie, ô Eternel! comment j’ai marché devant toi en vérité et en intégrité de cœur, et comment j’ai fait ce qui t’était agréable; et Ezéchias pleura abondamment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Or la parole de l’Eternel fut adressée à Esaïe, en disant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Va, et dis à Ezéchias ainsi a dit l’Eternel, le Dieu de David ton père; j’ai exaucé ta prière, j’ai vu tes larmes; voici, je m’en vais ajouter quinze années à tes jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'Et je te délivrerai de la main du Roi des Assyriens, toi et cette ville, et je garantirai cette ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Et ce signe t’est donné par l’Eternel, pour faire voir que l’Eternel accomplira cette parole qu’il a prononcée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Voici, je m’en vais faire retourner l’ombre des degrés par lesquels elle est descendue au cadran d’Achaz, de dix degrés en arrière avec le soleil; et le soleil retourna de dix degrés par les degrés par lesquels il était descendu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Or c’est ici l’Ecrit d’Ezéchias Roi de Juda, touchant ce qu’il fut malade, et qu’il fut guéri de sa maladie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'J’avais dit dans le retranchement de mes jours; je m’en irai aux portes du sépulcre, je suis privé de ce qui restait de mes années.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'J’avais dit; je ne contemplerai plus l’Eternel, l’Eternel, dans la terre des vivants; je ne verrai plus personne avec les habitants du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Ma durée s’en est allée, et a été transportée d’avec moi, comme une cabane de berger; j’ai tranché ma vie comme le tisserand coupe sa toile; il me coupera dès les pesnes: du matin au soir tu m’auras enlevé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Je me proposais jusqu’au matin qu’il était comme un lion, qu’il briserait ainsi tous mes os; du matin au soir tu m’auras enlevé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Je grommelais comme la grue, et comme l’hirondelle; je gémissais comme le pigeon; mes yeux défaillaient à force de regarder en haut; Seigneur, on me fait force, sois mon garant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Que dirai-je? il m’a parlé; et lui même l’a fait; je m’en irai tout doucement, tous les ans de ma vie, dans l’amertume de mon âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Seigneur, par ces choses-là on a la vie, et dans tout ce qui est en ces choses consiste la vie de mon esprit; ainsi tu me rétabliras, et me feras revivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Voici, dans ma paix une grande amertume m’était survenue, mais tu as embrassé ma personne, afin qu’elle ne tombât point dans la fosse de la pourriture; parce que tu as jeté tous mes péchés derrière ton dos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Car le sépulcre ne te célébrera point, la mort ne te louera point; ceux qui descendent en la fosse, ne s’attendent plus à ta vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Mais le vivant, le vivant, est celui qui te célébrera, comme moi aujourd’hui; le père conduira les enfants à la connaissance de ta vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'L’Eternel m’est venu délivrer, et à cause de cela nous jouerons sur les instruments mes cantiques tous les jours de notre vie, dans la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Or Esaïe avait dit; qu’on prenne une masse de figues sèches, et qu’on en fasse une emplâtre sur l’ulcère, et il guérira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Et Ezéchias avait dit; quel est le signe que je monterai en la maison de l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'En ce temps-là Mérodach-Baladan, fils de Baladan, Roi de Babylone, envoya des Lettres avec un présent à Ezéchias, parce qu’il avait entendu qu’il avait été malade, et qu’il était guéri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Et Ezéchias en fut joyeux, et leur montra les cabinets de ses choses précieuses, l’argent, et l’or, et les choses aromatiques, et les onguents précieux, tout son arsenal, et tout ce qui se trouvait dans ses trésors; il n’y eut rien qu’Ezéchias ne leur montrât dans sa maison, et dans toute sa cour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Puis le Prophète Esaïe vint vers le roi Ezéchias, et lui dit; qu’ont dit ces hommes-là, et d’où sont-ils venus vers toi? et Ezéchias répondit; ils sont venus vers moi d’un pays éloigné; de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Et Esaïe dit; qu’ont-ils vu dans ta maison? et Ezéchias répondit; ils ont vu tout ce qui est dans ma maison; il n’y a rien eu dans mes trésors que je ne leur aie montré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Et Esaïe dit à Ezéchias; écoute la parole de l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Voici venir les jours que tout ce qui est dans ta maison, et ce que tes pères ont amassé dans leurs trésors jusqu’à aujourd’hui, sera emporté en Babylone; il n’en demeurera rien de reste; a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Même on prendra de tes fils qui sortiront de toi, et que tu auras engendrés, afin qu’ils soient Eunuques au palais du Roi de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Et Ezéchias répondit à Esaïe; La parole de l’Eternel que tu as prononcée, est bonne; et il ajouta; Au moins qu’il y ait paix et sûreté en mes jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Consolez, consolez mon peuple, dira votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Parlez à Jérusalem selon son cœur, et lui criez que son temps marqué est accompli, que son iniquité est tenue pour acquittée, qu’elle a reçu de la main de l’Eternel le double pour tous ses péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'La voix de celui qui crie au désert est; préparez le chemin de l’Eternel, dressez parmi les landes les sentiers à notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Toute vallée sera comblée, et toute montagne et tout coteau seront abaissés, et les lieux tortus seront redressés, et les lieux raboteux seront aplanis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Alors la gloire de l’Eternel se manifestera, et toute chair ensemble la verra; car la bouche de l’Eternel a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'La voix dit; crie; et on a répondu; que crierai-je? Toute chair est comme l’herbe, et toute sa grâce est comme la fleur d’un champ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'L’herbe est séchée, et la fleur est tombée, parce que le vent de l’Eternel a soufflé dessus; vraiment le peuple est comme l’herbe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'L’herbe est séchée, et la fleur est tombée; mais la parole de notre Dieu demeure éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Sion, qui annonces de bonnes nouvelles, monte sur une haute montagne; Jérusalem, qui annonces de bonnes nouvelles, élève ta voix avec force; élève-la, ne crains point; dis aux villes de Juda; voici votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Voici, le Seigneur l’Eternel viendra contre le fort, et son bras dominera sur lui; voici son salaire est avec lui, et son loyer marche devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Il paîtra son troupeau, comme un berger,il assemblera les agneaux entre ses bras, il les placera en son sein; il conduira celles qui allaitent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Qui est celui qui a mesuré les eaux avec le creux de sa main, et qui a compassé les cieux avec la paume; qui a rassemblé toute la poussière de la terre dans un boisseau; et qui a pesé au crochet les montagnes, et les coteaux à la balance?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Qui a dirigé l’Esprit de l’Eternel, ou qui étant son conseiller, lui a montré quelque chose?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Avec qui a-t-il pris conseil, et qui l’a instruit, et lui a enseigné le sentier de jugement? Qui lui a enseigné la science, et lui a montré le chemin de la prudence?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Voilà, les nations sont comme une goutte qui tombe d’un sceau, et elles sont réputées comme la menue poussière d’une balance; voilà, il a jeté çà et là les Iles comme de la poudre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Et le Liban ne suffirait pas pour faire le feu, et les bêtes qui y sont ne seraient pas suffisantes pour l’holocauste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Toutes les nations sont devant lui comme un rien, et il ne les considère que comme de la poussière, et comme un néant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'A qui donc ferez-vous ressembler le Dieu Fort, et quelle ressemblance lui approprierez-vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'L’ouvrier fond l’image, et l’orfèvre étend de l’or par-dessus, et lui fond des chaînettes d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Celui qui est si pauvre qu’il n’a pas de quoi offrir, choisit un bois qui ne pourrisse point, et cherche un ouvrier expert, pour faire une image taillée qui ne bouge point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'N’aurez-vous jamais de connaissance? n’écouterez-vous jamais? ne vous a-t-il pas été déclaré dès le commencement? ne l’avez-vous pas entendu dès les fondements de la terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'C’est lui qui est assis au-dessus du globe de la terre, et à qui ses habitants sont comme des sauterelles; c’est lui qui étend les cieux comme un voile, il les a même étendus comme une tente pour y habiter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'C’est lui qui réduit les Princes à rien, et qui fait être les gouverneurs de la terre comme une chose de néant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Même ils ne seront point plantés, même ils ne seront point semés, même leur tronc ne jettera point de racine en terre; même il soufflera sur eux, et ils sécheront, et le tourbillon les emportera comme de la paille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'A qui donc me ferez-vous ressembler, et à qui serais-je égalé? dit le Saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Elevez vos yeux en haut, et regardez; qui a créé ces choses? c’est celui qui fait sortir leur armée par ordre, et qui les appelle toutes par leur nom; il n’y en a pas une qui manque, à cause de la grandeur de ses forces, et parce qu’il excelle en puissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Pourquoi donc dirais-tu, ô Jacob! et pourquoi dirais-tu, ô Israël! mon état est caché à l’Eternel, et mon droit est inconnu à mon Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Ne sais-tu pas et n’as-tu pas entendu que le Dieu d’éternité, l’Eternel, a créé les bornes de la terre? il ne se lasse point, et ne se travaille point, et il n’y a pas moyen de sonder son intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'C’est lui qui donne de la force à celui qui est las, et qui multiplie la force de celui qui n’a aucune vigueur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Les jeunes gens se lassent et se travaillent, même les jeunes gens d’élite tombent sans force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'Mais ceux qui s’attendent à l’Eternel prennent de nouvelles forces; les ailes leur reviennent comme aux aigles; ils courront; et ne se fatigueront point; ils marcheront, et ne se lasseront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Iles, faites-moi silence, et que les peuples prennent de nouvelles forces; qu’ils approchent, et qu’alors ils parlent; allons ensemble en jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Qui est celui qui a fait lever de l’Orient la justice? qui l’a appelée afin qu’elle le suivit pas à pas? qui a soumis à son commandement les nations, lui a fait avoir domination sur les Rois, et les a livrés à son épée, comme de la poussière; et à son arc, comme de la paille poussée par le vent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Il les a poursuivis, et il est passé en paix par le chemin auquel il n’était point entré de ses pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Qui est celui qui a opéré et fait ces choses? c’est celui qui a appelé les âges dès le commencement. Moi l’Eternel je suis le premier, et je suis avec les derniers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Les Iles ont vu, et ont eu crainte, les bouts de la terre ont été effrayés, ils se sont approchés et sont venus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Chacun a aidé à son prochain, et a dit à son frère; fortifie-toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'L’ouvrier a encouragé le fondeur; celui qui frappe doucement du marteau encourage celui qui frappe sur l’enclume, et dit; Cela est bon pour souder, puis il le fait tenir avec des clous, afin qu’il ne bouge point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Mais toi, Israël, tu es mon serviteur, et toi, Jacob, tu es celui que j’ai élu, la race d’Abraham qui m’a aimé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'Car je t’ai pris des bouts de la terre, je t’ai appelé, en te préférant aux plus excellents qui sont en elle, et je t’ai dit; C’est toi qui es mon serviteur, je t’ai élu, et je ne t’ai point rejeté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Ne crains point, car je suis avec toi; ne sois point étonné, car je suis ton Dieu; je t’ai fortifié, et je t’ai aidé, même je t’ai maintenu par la dextre de ma justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Voici, tous ceux qui sont indignés contre toi seront honteux et confus; ils seront réduits à néant, et les hommes qui ont querelle avec toi périront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Tu chercheras les hommes qui ont querelle avec toi, et tu ne les trouveras point; ils seront réduits à néant; et ceux qui te font la guerre, seront comme ce qui n’est plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Car je suis l’Eternel ton Dieu, soutenant ta main droite, celui qui te dis; ne crains point, c’est moi qui t’ai aidé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Ne crains point, vermisseau de Jacob, hommes mortels d’Israël; je t’aiderai dit l’Eternel, et ton défenseur c’est le Saint d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Voici, je te ferai être comme une herse pointue toute neuve, ayant des dents; tu fouleras les montagnes et les menuiseras, et tu rendras les coteaux semblables à de la balle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Tu les vanneras, et le vent les emportera, et le tourbillon les dispersera; mais tu t’égayeras en l’Eternel, tu te glorifieras au Saint d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Quant aux affligés et aux misérables qui cherchent des eaux, et n’en ont point, la langue desquels est tellement altérée qu’elle n’en peut plus, moi l’Eternel je les exaucerai; moi le Dieu d’Israël je ne les abandonnerai point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Je ferai sourdre des fleuves dans les lieux haut élevés, et des fontaines au milieu des vallées; je réduirai le désert en des étangs d’eaux, et la terre sèche en des sources d’eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Je ferai croître au désert le cèdre, le pin, le myrte, et l’olivier; je mettrai aux landes le sapin, l’orme et le buis ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'Afin qu’on voie, qu’on sache, qu’on pense, et qu’on entende pareillement que la main de l’Eternel a fait cela, et que le Saint d’Israël a créé cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Produisez votre procès, dit l’Eternel; et mettez en avant les fondements de votre cause, dit le Roi de Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Qu’on les amène, et qu’ils nous déclarent les choses qui arriveront; déclarez-nous que veulent dire les choses qui ont été auparavant, et nous y prendrons garde; et nous saurons leur issue; ou faites-nous entendre ce qui est prêt à arriver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Déclarez les choses qui doivent arriver ci-après; et nous saurons que vous êtes dieux; faites aussi du bien ou du mal, et nous en serons tout étonnés; puis nous regarderons ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Voici, vous êtes de rien, et ce que vous faites est inutile; celui qui vous choisit n’est qu’abomination.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Je l’ai suscité d’Aquilon, et il viendra; il réclamera mon Nom de devers le soleil levant, et marchera sur les Magistrats, comme sur le mortier, et les foulera, comme le potier foule la boue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Qui est celui qui a manifesté ces choses dès le commencement, afin que nous le connaissions, et avant le temps où nous sommes, et nous dirons qu’il est juste? mais il n’y a personne qui les annonce, même il n’y a personne qui les donne à entendre, même il n’y a personne qui entende vos paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Le premier sera pour Sion, disant; voici, les voici; et je donnerai quelqu’un à Jérusalem qui annoncera de bonnes nouvelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'J’ai regardé, et il n’y avait point d’homme notable; même entre ceux-là, et il n’y avait aucun homme de conseil; je les ai aussi interrogés, afin qu’ils répondissent quelque chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Voici, quant à eux tous, leurs oeuvres ne sont que vanité, une chose de néant; leurs idoles de fonte sont du vent et de la confusion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Voici mon serviteur, je le maintiendrai: c’est mon Elu, auquel mon âme prend son bon plaisir; j’ai mis mon Esprit sur lui; il manifestra le jugement aux nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Il ne criera point, et il ne haussera, ni ne fera ouïr sa voix dans les rues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Il ne brisera point le roseau cassé, et n’éteindra point le lumignon fumant; il mettra en avant le jugement en vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Il ne se retirera point, ni ne se hâtera point, qu’il n’ait mis un règlement en la terre; et les Iles s’attendront à sa Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Ainsi a dit le Dieu Fort, l’Eternel, qui a créé les cieux, et les a étendus, qui a aplani la terre avec ce qu’elle produit, qui donne la respiration au peuple qui est sur elle, et l’esprit à ceux qui y marchent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Moi l’Eternel, je t’ai appelé en justice, et je prendrai ta main, et te garderai; et je te ferai être l’alliance du peuple, et la lumière des nations:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'Afin d’ouvrir les yeux qui ne voient point, et de retirer les prisonniers hors du lieu où on les tient enfermés, et ceux qui habitent dans les ténèbres, hors de la prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Je suis l’Eternel, c’est là mon Nom; et je ne donnerai point ma gloire à un autre, ni ma louange aux images taillées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Voici, les choses qui ont été prédites auparavant sont arrivées; et je vous en annonce de nouvelles, et je vous les ferai entendre avant qu’elles soient arrivées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Chantez à l’Eternel un nouveau cantique, et que sa louange éclate du bout de la terre; que ceux qui descendent en la mer; et tout ce qui est en elle; que les Iles, et leurs habitants;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Que le désert et ses villes élèvent la voix; que les villages où habite Kédar; et ceux qui habitent dans les rochers éclatent en chant de triomphe; qu’ils s’écrient du sommet des montagnes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Qu’on donne gloire à l’Eternel, et qu’on publie sa louange dans les Iles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'L’Eternel sortira comme un homme vaillant, il réveillera sa jalousie comme un homme de guerre, il jettera des cris de joie, il jettera, dis je, de grands cris, et se fortifiera contre ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Je me suis tu dès longtemps; me tiendrais-je en repos? me retiendrais-je? je crierai comme celle qui enfante, je détruirai, et j’engloutirai tout ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Je réduirai les montagnes et les coteaux en désert, et je dessécherai toute leur herbe; je réduirai les fleuves en Iles, et je ferai tarir les étangs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Je conduirai les aveugles par un chemin qu’ ils ne connaissent point, je les ferai marcher par des sentiers qu’ils ne connaissent point; je réduirai devant eux les ténèbres en lumière, et les choses tortues en choses droites; je leur ferai de telles choses, et je ne les abandonnerai point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Que ceux-là donc se retirent en arrière, et soient tout honteux, qui se confient aux images taillées, et qui disent aux images de fonte; vous êtes nos dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Sourds, écoutez; et vous aveugles regardez et voyez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Qui est aveugle, sinon mon serviteur? et qui est sourd, comme mon messager que j’ai envoyé? Qui est aveugle, comme celui que j’ai comblé de grâces? qui, dis-je, est aveugle, comme le serviteur de l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Vous voyez beaucoup de choses, mais vous ne prenez garde à rien; vous avez les oreilles ouvertes, mais vous n’entendez rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'L’Eternel prenait plaisir en lui à cause de sa justice; il magnifiait sa Loi, et le rendait honorable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Mais c’est ici un peuple pillé et fourragé; ils seront tous enlacés dans les cavernes, et seront cachés dans les prisons; ils seront en pillage, et il n’y aura personne qui les délivre; ils seront fourragés, et il n’y aura personne qui dise; restituez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Qui est celui d’entre vous qui prêtera l’oreille à ceci, qui y sera attentif, et qui l’entendra dorénavant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Qui est-ce qui a livré Jacob au pillage, et Israël aux fourrageurs? N’a-ce pas été l’Eternel, contre lequel nous avons péché? Parce qu’on n’a point agréé de marcher dans ses voies, et qu’on n’a point écouté sa Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'C’est pourquoi il a répandu sur lui la fureur de sa colère, et une forte guerre; et il l’a embrasé tout alentour, mais Israël ne l’a point connu; et tu l’as brûlé, mais il ne s’en est point soucié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Mais maintenant ainsi a dit l’Eternel, qui t’a créé, ô Jacob! et qui t’a formé, ô Israël? Ne crains point, car je t’ai racheté, je t’ai appelé par ton Nom; tu es à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Quand tu passeras par les eaux, je serai avec toi, et quand tu passeras par les fleuves, ils ne te noieront point; quand tu marcheras dans le feu, tu ne seras point brûlé, et la flamme ne t’embrasera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Car je suis l’Eternel ton Dieu, le Saint d’Israël ton Sauveur; j’ai donné l’Egypte pour ta rançon, Chus et Séba pour toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Depuis que tu as été précieux devant mes yeux, tu as été rendu honorable, et je t’ai aimé; et je donnerai les hommes pour toi, et les peuples pour ta vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Ne crains point, car je suis avec toi; je ferai venir ta postérité d’Orient, et je t’assemblerai d’Occident.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Je dirai à l’Aquilon, Donne; et au Midi; ne mets point d’empêchement; amène mes fils de loin, et mes filles du bout de la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'Savoir, tous ceux qui sont appelés de mon Nom; car je les ai créés pour ma gloire; je les ai formés, et les ai faits:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Amenant dehors le peuple aveugle, qui a des yeux; et les sourds, qui ont des oreilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Que toutes les nations soient ramassées ensemble, et que les peuples soient assemblés. Lequel d’entre eux a prédit cette chose-là? et qui sont ceux qui nous ont fait entendre les choses qui ont été ci-devant? qu’ils produisent leurs témoins, et qu’ils se justifient; qu’on les entende, et qu’après cela on dise; il est vrai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Vous êtes mes témoins, dit l’Eternel, et mon serviteur aussi, que j’ai élu; afin que vous connaissiez, et que vous me croyiez, et que vous entendiez que c’est moi. Il n y a point eu de Dieu Fort avant moi, qui ait rien formé, et il n’y en aura point après moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'C’est moi, c’est moi qui suis l’Eternel, et il n’y a point de Sauveur que moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'C’est moi qui ai prédit ce qui devait arriver, c’est moi qui vous ai délivrés, et qui vous ai fait entendre l’avenir et il n’y a point eu parmi vous de dieu étranger qui ait fait ces choses; et vous êtes mes témoins, dit l’Eternel, que je suis le Dieu Fort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Et même j’étais dès qu’il y a eu de jour, et il n’y a personne qui puisse délivrer de ma main; je ferai une chose, et qui est-ce qui m’en empêchera?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Ainsi a dit l’Eternel votre Rédempteur, le Saint d’Israël; j’enverrai pour l’amour de vous contre Babylone, et je les ferai tous descendre fugitifs, et le cri des Chaldéens sera dans les navires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'C’est moi qui suis l’Eternel, votre Saint, le Créateur d’Israël, votre Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Ainsi a dit l’Eternel, qui a dressé un chemin dans la mer, et un sentier parmi les eaux impétueuses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'Quant à celui qui amenait des chariots et des chevaux, et de grandes forces; ils ont tous été étendus ensemble, et ils ne se relèveront point, ils ont été étouffés, ils ont été éteints comme un lumignon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Ne faites point mention des choses de ci-devant, et ne considérez point les choses anciennes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Voici, je m’en vais faire une chose nouvelle qui paraîtra bientôt, ne la connaîtrez-vous pas? C’est que je mettrai un chemin au désert, et des fleuves au lieu désolé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Les bêtes des champs, les dragons, et les chats-huants me glorifieront, parce que j’aurai mis des eaux au désert, et des fleuves au lieu désolé, pour abreuver mon peuple, que j’ai élu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Je me suis formé ce peuple-ci, et j’ai dit; ils raconteront ma louange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Mais toi Jacob, tu ne m’as point invoqué, quand tu t’es travaillé pour moi, ô Israël!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Tu ne m’as point offert les menues bêtes de tes holocaustes, et tu ne m’as point glorifié dans tes sacrifices; je ne t’ai point asservi pour me faire des oblations, et je ne t’ai point fatigué pour me présenter de l’encens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Tu ne m’as point acheté à prix d’argent du roseau aromatique, et tu ne m’as point enivré de la graisse de tes sacrifices; mais tu m’as asservi par tes péchés, et tu m’as travaillé par tes iniquités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'C’est moi, c’est moi qui efface tes forfaits pour l’amour de moi, et je ne me souviendrai plus de tes péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Remets-moi en mémoire, et plaidons ensemble; toi, déduis tes raisons, afin que tu te justifies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Ton premier père a péché, et tes entremetteurs ont prévariqué contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'C’est pourquoi je traiterai comme souillés les principaux du lieu Saint, et je mettrai Jacob en interdit, et Israël en opprobre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Mais maintenant, ô Jacob! mon serviteur, écoute; et toi Israël que j’ai élu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Ainsi a dit l’Eternel, qui t’a fait et formé dès le ventre, et qui t’aide; ne crains point, ô Jacob mon serviteur! et toi Jésurun que j’ai élu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Car je répandrai des eaux sur celui qui est altéré, et des rivières sur la terre sèche; je répandrai mon esprit sur ta postérité, et ma bénédiction sur ceux qui sortiront de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'Et ils germeront comme parmi l’herbage, comme les saules auprès des eaux courantes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'L’un dira; je suis à l’Eternel, et l’autre se réclamera du nom de Jacob; et un autre écrira de sa main; je suis à l’Eternel; et se surnommera du Nom d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Ainsi a dit l’Eternel, le Roi d’Israël et son Rédempteur, l’Eternel des armées; je suis le premier, et je suis le dernier; et il n’y a point d’autre Dieu que moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Et qui est celui qui ait appelé comme moi, qui m’ait déclaré, et ordonné cela, depuis que j’ai établi le peuple ancien? qu’ils leur déclarent les choses à venir, les choses, dis-je, qui arriveront ci-après.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Ne soyez point effrayés, et ne soyez point troublés; ne te l’ai-je pas fait entendre et déclaré dès ce temps-là? et vous m’en êtes témoins; y-a-t-il quelque autre Dieu que moi? certes il n’y a point d’autre Rocher; je n’en connais point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Les ouvriers des images taillées ne sont tous qu’un rien, et leurs choses les plus précieux ne profitent de rien; et ils leur sont témoins qu’ils ne voient point, et ne connaissent point, afin qu’ils soient honteux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Mais qui est-ce qui a formé un Dieu Fort, et qui a fondu une image taillée, pour n’en avoir aucun profit?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Voici, tous ses compagnons seront honteux, car ces ouvriers-là sont d’entre les hommes; ils seront effrayés et rendus honteux tous ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Le forgeron de fer prend le ciseau et travaille avec le charbon, il le forme avec des marteaux, il le fait à force de bras, même ayant faim, tellement qu’il n’en peut plus; et s’il ne boit point d’eau, il en est tout fatigué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Le menuisier étend sa règle, et le crayonne avec de la craie; il le fait avec des équerres, et le forme au compas, et le fait à la ressemblance d’un homme, et le pare comme un homme, afin qu’il demeure dans la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Il se coupe des cèdres, et prend un cyprès, ou un chêne, qu’il a laissé croître parmi les arbres de la forêt; il plante un frêne, et la pluie le fait croître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Puis il servira à l’homme pour brûler; car il en prend, et s’en chauffe; il en fait, dis-je, du feu, et en cuit du pain; il en fait aussi un Dieu, et se prosterne devant lui; il en fait une image taillée, et l’adore.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Il en brûle au feu une partie, et d’une autre partie il mange sa chair, laquelle il rôtit, et s’en rassasie; il s’en chauffe aussi, et il dit; ha! ha! je me suis réchauffé, j’ai vu la lueur du feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Puis du reste il en fait un Dieu pour être son image taillée; il l’adore et se prosterne, et lui fait sa requête, et lui dit; Délivre-moi, car tu es mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Ces gens ne savent et n’entendent rien; car on leur a plâtré les yeux, afin qu’ils ne voient point; et leurs coeurs, afin qu’ils n’entendent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Nul ne rentre en soi-même, et n’a ni connaissance, ni intelligence, pour dire; j’ai brûlé la moitié de ceci au feu, et même j’en ai cuit du pain sur les charbons; j’en ai rôti de la chair, et j’en ai mangé; et du reste en ferais-je une abomination? adorerais-je une branche de bois?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Il se paît de cendre, et son coeur abusé le fait égarer; et il ne délivrera point son âme, et ne dira point; ce qui est dans ma main droite n’est-il pas une fausseté?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Jacob et Israël, souviens-toi de ces choses, car tu es mon serviteur; je t’ai formé, tu es mon serviteur, ô Israël! je ne te mettrai point en oubli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'J’ai effacé tes forfaits comme une nuée épaisse, et tes péchés, comme une nuée; retourne à moi, car je t’ai racheté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'O cieux! réjouissez-vous avec chant de triomphe, car l’Eternel a opéré; lieux bas de la terre, jetez des cris de réjouissance; montagnes, éclatez de joie avec chant de triomphe; et vous aussi forêts, et tous les arbres qui êtes en elles, parce que l’Eternel a racheté Jacob, et s’est manifesté glorieusement en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Ainsi a dit l’Eternel ton Rédempteur, et celui gui t’a formé dès le ventre; je suis l’Eternel qui ai fait toutes choses, qui seul ai étendu les cieux, et qui ai par moi-même aplani la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Qui dissipe les signes des menteurs, qui rends insensés les devins; qui renverse l’esprit des sages, et qui fais que leur science devient une folie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'C’est lui qui met en exécution la parole de son serviteur, et qui accomplit le conseil de ses messagers; qui dit à Jérusalem; tu seras encore habitée; et aux villes de Juda; vous serez rebâties; et je redresserai ses lieux déserts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Qui dit au gouffre; sois asséché, et je tarirai tes fleuves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'Qui dit de Cyrus; c’est mon Berger; il accomplira tout mon bon plaisir, disant même à Jérusalem; tu seras rebâtie; et au Temple; tu seras fondé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Ainsi a dit l’Eternel à son Oint, à Cyrus, duquel j’ai pris la main droite, afin que je terrasse les nations devant lui, et que je délie les reins des Rois; afin qu’on ouvre devant lui les portes, et que les portes ne soient point fermées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'J’irai devant toi, et je dresserai les chemins tortus; je romprai les portes d’airain, et je mettrai en pièces les barres de fer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'Et je te donnerai les trésors cachés, et les richesses le plus secrètement gardées, afin que tu saches que je suis l’Eternel, le Dieu d’Israël, qui t’appelle par ton Nom;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Pour l’amour de Jacob mon serviteur, et d’Israël mon élu; je t’ai, dis-je, appelé par ton nom, et je t’ai surnommé, bien que tu ne me connusses point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Je suis l’Eternel, et il n’y en a point d’autre; il n’y a point de Dieu que moi. Je t’ai ceint, quoique tu ne me connusses point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'Afin qu’on connaisse depuis le soleil levant, et depuis le soleil couchant, qu’il n’y a point d’autre Dieu que moi. Je suis l’Eternel, et il n’y en a point d’autre:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Qui forme la lumière, et qui crée les ténèbres; qui fais la paix, et qui crée l’adversité; c’est moi l’Eternel qui fais toutes ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'O cieux! envoyez la rosée d’en haut, et que les nuées fassent distiller la justice; que la terre s’ouvre, qu’elle produise le salut, et que la justice germe ensemble! moi l’Eternel j’ai créé cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Malheur à celui qui plaide contre celui qui l’a formé. Que le pot plaide contre les autres pots de terre; mais l’argile dira-t-elle à celui qui l’a formée; que fais-tu? et tu n’as point d’adresse pour ton ouvrage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Malheur à celui qui dit à son père; pourquoi engendres-tu? et à sa mère; pourquoi enfantes-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Ainsi a dit l’Eternel, le Saint d’Israël, qui est son Créateur; ils m’ont interrogé touchant les choses à venir; et me donneriez- vous la Loi touchant mes fils, et touchant l’oeuvre de mes mains?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'C’est moi qui ai fait la terre, et qui ai créé l’homme sur elle; c’est moi qui ai étendu les cieux de mes mains, et qui ai donné la loi à toute leur armée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'C’est moi qui ai suscité celui-ci en justice, et j’adresserai tous ses desseins, il rebâtira ma ville, et renverra sans rançon et sans présents mon peuple qui aura été transporté, a dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Ainsi a dit l’Eternel; le travail de l’Egypte, et le trafic de Chus, et les Sabéens, gens de grande stature, passeront vers toi, Jérusalem, et ils seront à toi, ils marcheront après toi, ils passeront enchaînés, et se prosterneront devant toi, ils te feront leurs supplications, et te diront; certes le Dieu Fort est au milieu de toi, et il n’y a point d’autre Dieu que lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Certainement tu es le Dieu Fort qui te caches, le Dieu d’Israël, le Sauveur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Eux tous ont été honteux et confus; les ouvriers d’images s’en sont allés ensemble avec honte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Mais Israël a été sauvé par l’Eternel, d’un salut éternel; vous ne serez point honteux, et vous ne serez point confus à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Car ainsi a dit l’Eternel qui a créé les cieux, lui qui est le Dieu qui a formé la terre, et qui l’a faite, lui qui l’a affermie; il ne l’a point créée pour être une chose vide, mais il l’a formée pour être habitée. Je suis l’Eternel, et il n’y en a point d’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Je n’ai point parlé en secret, ni en quelque lieu ténébreux de la terre; je n’ai point dit à la postérité de Jacob; cherchez-moi en vain. Je suis l’Eternel, proférant la justice, déclarant les choses droites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Assemblez-vous, et venez, approchez-vous ensemble, vous les réchappés d’entre les nations. Ceux qui portent le bois de leur image taillée ne savent rien, ni ceux qui font requête à un Dieu qui ne délivre point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Déclarez, et faites approcher, et même qu’on consulte ensemble; qui est-ce qui a fait entendre une telle chose dès longtemps auparavant? qui l’a déclarée dès lors? n’est-ce pas moi l’Eternel? or il n’y a point d’autre Dieu que moi; il n’y a point de Dieu Fort, Juste et Sauveur, que moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Vous tous les bouts de la terre, regardez vers moi, et soyez sauvés; car je suis le Dieu Fort, et il n’y en a point d’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'J’ai juré par moi-même, et la parole est sortie en justice de ma bouche, et elle ne sera point révoquée, que tout genou se pliera devant moi, et que toute langue jurera par moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Certainement on dira de moi; La justice et la force est en l’Eternel; mais quiconque viendra contre lui, sera honteux, et tous ceux qui seront indignés contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'Toute la postérité d’Israël sera justifiée, et elle se glorifiera en l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Bel s’est incliné sur ses genoux; Nébo est renversé, leurs faux dieux ont été mis sur des bêtes, et sur les juments; les idoles que vous portiez ont été chargées, elles ont été un faix aux bêtes lassées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Elles se sont courbées, elles se sont inclinées sur leurs genoux ensemble, et n’ont pu éviter d’être chargées, elles-mêmes sont allées en captivité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Maison de Jacob, écoutez-moi, et vous, tout le résidu de la maison d’Israël, dont je me suis chargé dès le ventre, et qui avez été portés dès la matrice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Je serai le même jusques à votre vieillesse, et je vous chargerai sur moi jusques à votre blanche vieillesse; je l’ai fait, et je vous porterai encore, je vous chargerai sur moi, et je vous délivrerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'A qui me compareriez-vous, et à qui m’égaleriez-vous? et a qui me feriez-vous ressembler, pour dire que nous fussions semblables?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Ils tirent l’or de la bourse, et pèsent l’argent à la balance, et louent un orfèvre pour en faire un Dieu; ils l’adorent, et se prosternent devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'On le porte sur les épaules, on s’en charge, on le pose en sa place, où il se tient debout, et ne bouge point de son lieu; puis on criera à lui, mais il ne répondra point, et il ne délivrera point de leur détresse ceux qui crieront à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Souvenez-vous de cela, et reprenez courage, vous transgresseurs, et revenez à votre sens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Souvenez-vous des premières choses qui ont été autrefois: car c’est moi qui suis le Dieu Fort, et il n’y a point d’autre Dieu, et il n’y a rien qui soit semblable à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Qui déclare dès le commencement la fin, et longtemps auparavant les choses qui n’ont point encore été faites; qui dis; Mon conseil tiendra, et je mettrai en exécution tout mon bon plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Qui appelle d’Orient l’oiseau de proie, et d’une terre éloignée un homme qui exécutera mon conseil. Ai-je parlé, aussi ferai-je venir la chose; je l’ai formée, aussi la mettrai-je en effet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Ecoutez-moi, vous qui avez le cœur endurci, et qui êtes éloignés de la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'J’ai fait approcher ma justice, elle ne s’éloignera point, et ma délivrance ne tardera point; je mettrai la délivrance en Sion pour Israël, qui est ma gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Descends, assieds-toi sur la poussière, Vierge fille de Babylone, assieds-toi à terre, il n’y a plus de trône pour la fille des Chaldéens, car tu ne te feras, plus appeler, la délicate et la voluptueuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Mets la main aux meules, et fais moudre la farine; délie tes tresses, déchausse-toi, découvre tes jambes et passe les fleuves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Ta honte sera découverte, et ton opprobre sera vu; je prendrai vengeance, je n’irai point contre toi en homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Quant à notre Rédempteur, son Nom est l’Eternel des armées, le Saint d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Assieds-toi sans dire mot, et entre dans les ténèbres, fille des Chaldéens, car tu ne te feras plus appeler, la Dame des Royaumes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'J’ai été embrasé de colère contre mon peuple, j’ai profané mon héritage, c’est pourquoi je les ai livrés entre tes mains, mais tu n’as point usé de miséricorde envers eux, tu as grièvement appesanti ton joug sur le vieillard;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'Et tu as dit; je serai Dame à toujours, tellement que tu n’as point mis ces choses-là dans ton cœur; tu ne t’es point souvenue de ce qui en arriverait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Maintenant donc écoute ceci, toi voluptueuse; qui habites en assurance, qui dis en ton cœur; c’est moi, et il n’y en as point d’autre que moi; je ne deviendrai point veuve, et je ne saurai point ce que c’est que d’être privée d’enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'C’est que ces deux choses t’arriveront en un moment, en un même jour, la privation d’enfants et le veuvage; elles sont venues sur toi dans tout leur entier, pour le grand nombre de tes sortilèges, et pour la grande abondance de tes enchantements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Et tu t’es confiée en ta malice, et as dit; Il n’y a personne qui me voie; ta sagesse et ta science est celle qui t’a fait égarer; tellement que tu as dit en ton cœur; C’est moi, et il n’y en a point d’autre que moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'C’est pourquoi le mal viendra sur toi, et tu ne sauras point quand il sera près d’arriver, et le malheur qui tombera sur toi sera tel, que tu ne le pourras point détourner; et la ruine éclatante, laquelle tu ne sauras point, viendra subitement sur toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Tiens-toi maintenant avec tes enchantements, et avec le grand nombre de tes sortilèges, après lesquels tu as travaillé dès ta jeunesse; peut-être que tu en pourras avoir quelque profit; peut- être que tu en seras renforcée');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Tu t’es lassée à force de demander des conseils. Que les spectateurs des cieux qui contemplent les étoiles, et qui font leurs prédictions selon les lunes, comparaissent maintenant, et qu’ils te délivrent des choses qui viendront sur toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Voici, ils sont devenus comme de la paille, le feu les a brûlés; ils ne délivreront point leur âme de la puissance de la flamme; il n’y a point de charbons pour se chauffer, et il n’y a point de lueur de feu pour s’asseoir vis-à-vis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Tels te sont devenus ceux après lesquels tu as travaillé, et avec lesquels tu as trafiqué dès ta jeunesse; chacun s’en est fui en son quartier comme un vagabond; il n’y a personne qui te délivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Ecoutez ceci, maison de Jacob, qui êtes appelés du nom d’Israël, et qui êtes issus des eaux de Juda, qui jurez par le nom de l’Eternel, et qui faites mention du Dieu d’Israël, mais non pas conformément à la vérité, et à la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Car ils prennent leur nom de la sainte Cité, et s’appuient sur le Dieu d’Israël, duquel le nom est l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'J’ai déclaré dès jadis les choses qui ont précédé, et elles sont sorties de ma bouche, et je les ai publiées; je les ai faites subitement, et elles sont arrivées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Parce que j’ai connu que tu étais revêche, et que ton cou était comme une barre de fer, et que ton front était d’airain;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'Je t’ai déclaré ces choses dès lors, et je te les ai fait entendre avant qu’elles arrivassent, de peur que tu ne disses; mes dieux ont fait ces choses, et mon image taillée, et mon image de fonte les ont commandées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Tu l’as ouï, vois tout ceci; et vous, ne l’annoncerez-vous pas? je te fais entendre dès maintenant des choses nouvelles, et qui étaient en réserve, et que tu ne savais pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Maintenant elles ont été créées, et non pas dès jadis, et avant ce jour-ci tu n’en avais rien entendu, afin que tu ne dises pas; voici, je les savais bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Encore n’as-tu pas entendu; encore n’as-tu pas connu, et depuis ce temps ton oreille n’a point été ouverte; car j’ai connu que tu agirais perfidement; aussi as-tu été appelé Transgresseur dès le ventre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Pour l’amour de mon Nom je différerai ma colère, et pour l’amour de ma louange je retiendrai mon courroux contre toi, afin de ne te retrancher pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Voici, je t’ai épuré, mais non pas comme on épure l’argent; je t’ai élu au creuset de l’affliction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Pour l’amour de moi, pour l’amour de moi je le ferai; car comment mon Nom serait-il profané? certes je ne donnerai point ma gloire à un autre');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Ecoute-moi, Jacob, et toi Israël, appelé par moi; c’est moi qui suis le premier, et qui suis aussi le dernier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Ma main aussi a fondé la terre, et ma droite a mesuré les cieux à l’empan; quand je le les appelle, ils comparaissent ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Vous tous, assemblez-vous, et écoutez; lequel de ceux-là a déclaré de telles choses? l’Eternel l’a aimé, il mettra en exécution son bon plaisir contre Babylone, et son bras sera contre les Chaldéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'C’est moi, c’est moi qui ai parlé,je l’ai aussi appelé, je l’ai amené, et ses desseins lui ont réussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Approchez-vous de moi, et écoutez ceci; dès le commencement je n’ai point parlé en secret, au temps que la chose a été faite, j’ai été là. Or maintenant le Seigneur l’Eternel, et son Esprit, m’ont envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Ainsi a dit l’Eternel ton Rédempteur, le Saint d’Israël; je suis l’Eternel ton Dieu, qui t’enseigne à profiter, et qui te guide par le chemin où tu dois marcher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'O si tu eusses été attentif à mes commandements! car ta paix eût été comme un fleuve, et ta justice comme les flots de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'Et ta postérité eût été multipliée comme le sable, et ceux qui sortent de tes entrailles, comme le gravier de la mer; son nom n’eût point été retranché ni effacé de devant ma face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Sortez de Bapylone, fuyez loin des Chaldéens; publiez ceci avec une voix de chant de triomphe, annoncez, publiez ceci, et le mandez dire jusques au bout de la terre; dites, l’Eternel a racheté son serviteur Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Et ils n’ont point eu soif quand il les a fait marcher par les déserts; il leur a fait découler l’eau hors du rocher, même il leur a fendu le rocher, et les eaux en sont découlées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Il n’y a point de paix pour les méchants, a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Ecoutes-moi, Iles, et soyez attentifs, vous peuples éloignés; l’Eternel m’a appelé dès le ventre; il a fait mention de mon nom dès les entrailles de ma mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Et il a rendu ma bouche semblable à une épée aiguë; il m’a caché dans l’ombre de sa main, et m’a rendu semblable à une flèche bien polie, il m’a serré dans son carquois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'Et il m’a dit; tu es mon serviteur; Israël est celui en qui je me glorifierai par toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Et moi j’ai dit; j’ai travaillé en vain; j’ai usé ma force pour néant et sans fruit; toutefois mon droit est par-devers l’Eternel, mon œuvre est par-devers mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Maintenant donc l’Eternel, qui m’a formé dès le ventre pour lui être serviteur, m’a dit que je lui ramène Jacob; mais Israël ne se rassemble point; toutefois je serai glorifié aux yeux de l’Eternel, et mon Dieu sera ma force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Et il m’a dit; c’est peu de chose que tu me sois serviteur pour rétablir les Tribus de Jacob, et pour délivrer les captifs d’Israël; c’est pourquoi je t’ai donné pour lumière aux nations, afin que tu sois mon salut jusques au bout de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Ainsi a dit lesernel, le Rédempteur, le Saint d’Israël, à la personne méprisée, à celui qui est abominable dans la nation, au serviteur de ceux qui dominent; les Rois le verront, et se lèveront, et les principaux aussi, et ils se prosterneront devant lui, pour l’amour de l’Eternel, qui est fidèle, et du Saint d’Israël qui t’a élu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Ainsi a dit l’Eternel; je t’ai exaucé au temps de la bienveillance, et je t’ai aidé au jour du salut; je te garderai, et je te donnerai pour être l’alliance du peuple, pour rétablir la terre, et afin que tu possèdes les héritages désolés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'Disant à ceux qui sont garrottés; sortez; et à ceux qui sont dans les ténèbres; montrez-vous. Ils paîtront sur les chemins, et leurs pâturages seront sur tous les lieux haut élevés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Ils n’auront point de faim; ils n’auront point de soif; et la chaleur, ni le soleil ne les frappera plus, car celui qui a pitié d’eux les conduira, et les mènera aux sources d’eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Et je réduirai toutes mes montagnes en chemins, et mes sentiers seront relevés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Voici, ceux-ci viendront de loin; et voici, ceux-là viendront de l’Aquilon, et ceux-là de la mer, et les autres du pays des Siniens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'O cieux! réjouissez-vous avec chant de triomphe, et toi terre, égaye-toi, et vous montagnes, éclatez de joie avec chant de triomphe; car l’Eternel a consolé son peuple, et il aura compassion de ceux qu’il aura affligés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Mais Sion a dit; l’Eternel m’a délaissée, et le Seigneur m’a oubliée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'La femme peut-elle oublier son enfant qu’elle allaite, en sorte qu’elle n’ait point pitié du fils de son ventre? Mais quand les femmes les auraient oubliés, encore ne t’oublierai-je pas, moi');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Voici, je t’ai portraite sur les paumes de mes mains; tes murs sont continuellement devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Tes enfants viendront à grande hâte; mais ceux qui te détruisaient et qui te réduisaient en désert, sortiront du milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Elève tes yeux à l’environ, et regarde; tous ceux-ci se sont assemblés, ils sont venus à toi. Je suis vivant, dit l’Eternel, que tu te revêtiras de ceux-ci comme d’un ornement, et tu t’en orneras, comme une épouse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Car tes déserts, et tes lieux désolés, et ton pays détruit, sera maintenant trop étroit pour ses habitants, et ceux qui t’engloutissaient s’éloigneront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Les enfants que tu auras, après avoir perdu les autres, diront encore, toi l’entendant; ce lieu est trop étroit pour moi, fais-moi place afin que j’y puisse demeurer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Et tu diras en ton cœur; qui m’a engendré ceux-ci; vu que j’avais perdu mes enfants, et que j’étais seule? emmenée en captivité, et agitée, et qui m’a nourri ceux-ci? voici, j’étais demeurée toute seule, et ceux-ci où étaient-ils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Ainsi a dit le Seigneur l’Eternel; voici, je lèverai ma main vers les nations, et j’élèverai mon enseigne vers les peuples; et ils apporteront tes fils entre leurs bras, et on chargera tes filles sur les épaules.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Et les Rois seront tes nourriciers, et les Princesses leurs femmes tes nourrices; ils se prosterneront devant toi le visage contre terre, et lécheront la poudre de tes pieds; et tu sauras que je suis l’Eternel, et que ceux qui se confient en moi ne seront point honteux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Le pillage sera-t-il ôté à l’homme puissant? et les captifs du juste seront-ils délivrés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Car ainsi a dit l’Eternel; même les captifs pris par l’homme puissant, lui seront ôtés, et le pillage de l’homme fort sera enlevé; car je plaiderai moi-même avec ceux qui plaident contre toi, et je délivrerai tes enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Et je ferai que ceux qui t’auront opprimée mangeront leur propre chair, et s’enivreront de leur sang, comme du moût, et toute chair connaîtra que je suis l’Eternel qui te sauve, et ton Rédempteur, le puissant de Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Ainsi a dit l’Eternel; où sont les lettres de divorce de votre mère que j’ai renvoyée? ou qui est celui de mes créanciers à qui je vous aie vendus? voilà, vous avez été vendus pour vos iniquités, et votre mère a été renvoyée pour vos forfaits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Pourquoi suis-je venu, et il ne s’est trouvé personne? j’ai crié, et il n’y a personne qui ait répondu. Ma main est-elle en quelque sorte raccourcie, tellement que je ne puisse pas racheter? ou n’y a- t-il plus de force en moi pour délivrer? Voici, je fais tarir la mer, quand je la tance; je réduis les fleuves en désert, tellement que leur poisson devient puant, étant mort de soif, parce qu’il n’y a point d’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Je revêts les cieux de noirceur, et je mets un sac pour leur couverture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Le Seigneur l’Eternel m’a donné la langue des savants, pour savoir assaisonner la parole à celui qui est accablé de maux; chaque matin il me réveille soigneusement afin que je prête l’oreille aux discours des sages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Le Seigneur l’Eternel, m’a ouvert l’oreille, et je n’ai point été rebelle, et ne me suis point retiré en arrière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'J’ai exposé mon dos à ceux qui me frappaient, et mes joues à ceux qui me tiraient le poil, je n’ai point caché mon visage en arrière des opprobres, ni des crachats.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Mais le Seigneur l’Eternel m’a aidé, c’est pourquoi je n’ai point été confus; et ainsi, j’ai rendu mon visage semblable à un caillou; car je sais que je ne serai point rendu honteux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Celui qui me justifie est près; qui est-ce qui plaidera contre moi? comparaissons ensemble; qui est-ce qui est mon adverse partie? qu’il approche de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Voilà, le Seigneur, l’Eternel m’aidera, qui sera-ce qui me condamnera? voilà, eux tous seront usés comme un vêtement, la teigne les rongera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Qui est celui d’entre vous qui craigne l’Eternel, et qui écoute la voix de son serviteur? Que celui qui a marché dans les ténèbres, et qui n’avait point de clarté, ait confiance au Nom de l’Eternel, et qu’il s’appuie sur son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Voilà, vous tous qui allumez le feu, et qui vous ceignez d’étincelles, marchez à la lueur de votre feu, et dans les étincelles que vous avez embrasées; ceci vous a été fait de ma main, vous serez gisants dans les tourments.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Ecoutez-moi, vous qui suivez la justice, et qui cherchez l’Eternel; regardez au rocher duquel vous avez été taillés, et au creux de la citerne dont vous avez été tirés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Regardez à Abraham, votre père, et à Sara qui vous a enfantés; comment je l’ai appelé, lui étant tout seul, comment je l’ai béni, et multiplié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Car l’Eternel consolera Sion, il consolera toutes ses désolations, et rendra son désert semblable à Héden, et ses landes semblables au jardin de l’Eternel; en elle sera trouvée la joie et l’allégresse, la louange et la voix de mélodie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Ecoutez-moi donc attentivement, mon peuple, et prêtez-moi l’oreille, vous ma nation; car la Loi sortira de moi, et j’établirai mon jugement pour être la lumière des peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Ma justice est près, mon salut a paru, et mes bras jugeront les peuples; les Iles se confieront en moi, et leur confiance sera en mon bras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Elevez vos yeux vers les cieux, et regardez en bas vers la terre; car les cieux s’évanouiront comme la fumée, et la terre sera usée comme un vêtement, et ses habitants mourront pareillement; mais mon salut demeurera à toujours, et ma justice ne sera point anéantie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Ecoutez-moi, vous qui savez ce que c’est de la justice, peuple dans le cœur duquel est ma Loi; ne craignez point l’opprobre des hommes, et ne soyez point honteux de leurs reproches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Car la teigne les rongera comme un vêtement, et le ver les dévorera comme la laine; mais ma justice demeurera à toujours, et mon salut dans tous les âges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Réveille-toi, réveille-toi, revêts-toi de force, bras de l’Eternel, réveille-toi, comme aux jours anciens, aux siècles passés. N’es-tu pas celui qui as taillé en pièces Rahab, et qui as blessé mortellement le dragon?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'N’est-ce pas toi qui as fait tarir la mer, les eaux du grand abîme? qui as réduit les lieux les plus profonds de la mer en un chemin, afin que les rachetés y passassent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Et ceux dont l’Eternel aura payé la rançon, retourneront, et viendront en Sion avec chant de triomphe; et une allégresse éternelle sera sur leurs têtes; ils obtiendront la joie et l’allégresse, la douleur et le gémissement s’enfuiront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'C’est moi, c’est moi qui vous console; qui es-tu que tu aies peur de l’homme mortel, qui mourra, et du fils de l’homme qui deviendra comme du foin?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'Et tu as oublié l’Eternel qui t’a faite, qui a étendu les cieux, qui a fondé la terre; et tu t’es continuellement effrayée chaque jour à cause de la fureur de celui qui te pressait, quand il s’apprêtait à détruire; et où est maintenant la fureur de celui qui te pressait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Il se hâtera de faire que celui qui aura été transporté d’un lieu à l’autre, soit mis en liberté, afin qu’il ne meure point dans la fosse, et que son pain ne lui manque point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Car je suis l’Eternel ton Dieu, qui fend la mer, et les flots en bruient; l’Eternel des armées est son Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Or j’ai mis mes paroles en ta bouche, et je t’ai couvert de l’ombre de ma main, afin que j’affermisse les cieux, et que je fonde la terre, et que je dise à Sion; tu es mon peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Réveille-toi, réveille-toi; lève toi, Jérusalem, qui as bu de la main de l’Eternel la coupe de sa fureur; tu as bu, tu as sucé la lie de la coupe d’étourdissement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Il n’y a pas un de tous les enfants qu’elle a enfantés, qui la conduise; et de tous les enfants qu’elle a nourris, il n’y en a pas un qui la prenne par la main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Ces deux choses te sont arrivées; et qui est-ce qui te plaint? le dégât, la plaie, la famine et l’épée; par qui te consolerai-je?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Tes enfants se sont pâmés, ils ont été gisants aux carrefours de toutes les rues, comme un bœuf sauvage pris dans les filets, pleins de la fureur de l’Eternel, et de ce que ton Dieu les a réprimés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'C’est pourquoi, écoute maintenant ceci, ô affligée, et ivre! mais non pas de vin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Ainsi a dit l’Eternel ton Seigneur, et ton Dieu, qui plaide la cause de son peuple; voici, j’ai pris de la main la coupe d’étourdissement, la lie de la coupe de ma fureur, tu n’en boiras plus désormais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Car je la mettrai en la main de ceux qui t’ont affligée, et qui ont dit à ton âme; Courbe-toi, et nous passerons; c’est pourquoi tu as exposé ton corps comme la terre, et comme une rue aux passants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Réveille-toi, réveille toi, Sion; revêts-toi de ta force; Jérusalem, ville de sainteté, revêts-toi de tes vêtements magnifiques; car l’incirconcis et le souillé ne passeront plus désormais parmi toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Jérusalem, secoue la poudre de dessus toi, lève-toi, et t’assieds: défais-toi des liens de ton cou, fille de Sion, captive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Car ainsi a dit l’Eternel; vous avez été vendus pour rien, et vous serez aussi rachetés sans argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Car ainsi a dit le Seigneur l’Eternel; mon peuple descendit au commencement en Egypte pour y séjourner; mais les Assyriens l’ont opprimé pour rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Et maintenant, qu’ai-je à faire ici, dit l’Eternel, que mon peuple ait été enlevé pour rien? Ceux qui dominent sur lui le font hurler, dit l’Eternel, et ils ont fait continuellement chaque jour, que mon Nom est blasphémé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'C’est pourquoi mon peuple connaîtra mon Nom: c’est pourquoi il connaîtra en ce jour-là que c’est moi qui aurai dit; me voici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Combien sont beaux sur les montagnes les pieds de celui qui apporte de bonnes nouvelles, qui publie la paix, qui apporte de bonnes nouvelles touchant le bien, qui publie le salut, et qui dit à Sion; ton Dieu règne!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Tes sentinelles élèveront leurs voix, et se réjouiront ensemble avec chant de triomphe; car elles verront de leurs deux yeux comment l’Eternel ramènera Sion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Déserts de Jérusalem, éclatez, réjouissez-vous ensemble avec chant de triomphe; car l’Eternel a consolé son peuple, il a racheté Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'L’Eternel a manifesté le bras de sa sainteté devant les yeux de toutes les nations; et tous les bouts de la terre verront le salut de notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Retirez-vous, retirez-vous, sortez de là, ne touchez point à aucune chose souillée, sortez du milieu d’elle; nettoyez-vous, vous qui portez les vaisseaux de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Car vous ne sortirez point en hâte, et vous ne marcherez point en fuyant, parce que l’Eternel ira devant vous, et le Dieu d’Israël sera votre arrière-garde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Voici, mon serviteur prospérera, il sera fort exalté, et élevé, et glorifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Comme plusieurs ont été étonnés en te voyant, de ce que tu étais ainsi défait de visage plus que pas un autre, et de forme, plus que pas un des enfants des hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'Ainsi il fera rejaillir le sang de plusieurs nations, et les Rois fermeront la bouche sur toi; car ceux auxquels on n’en avait point parlé, le verront; et ceux qui n’en avaient rien ouï, l’entendront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Qui est-ce qui a cru à notre prédication? et à qui est-ce qu’a été visible le bras de l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Toutefois il est monté comme un rejeton devant lui, et comme une racine sortant d’une terre altérée; il n’y a en lui ni forme, ni apparence, quand nous le regardons, il n’y a rien en lui à le voir, qui fasse que nous le désirions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Il est le méprisé et le rejeté des hommes, homme de douleurs, et sachant ce que c’est que la langueur; et nous avons comme caché notre visage arrière de lui, tant il était méprisé; et nous ne l’avons rien estimé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Mais il a porté nos langueurs, et il a chargé nos douleurs; et nous avons estimé qu’étant ainsi frappé, il était battu de Dieu, et affligé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Or il était navré pour nos forfaits, et froissé pour nos iniquités, l’amende qui nous apporte la paix a été sur lui, et par sa meurtrissure nous avons la guérison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Nous avons tous été errants comme des brebis; nous nous sommes détournés chacun en suivant son propre chemin, et l’Eternel a fait venir sur lui l’iniquité de nous tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Chacun lui demande, et il en est affligé, toutefois il n’a point ouvert sa bouche, il a été mené à la boucherie comme un agneau, et comme une brebis muette devant celui qui la tond, et il n’a point ouvert sa bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Il a été enlevé de la force de l’angoisse et de la condamnation,mais qui racontera sa durée? car il a été retranché de la terre des vivants, et la plaie lui a été faite pour le forfait de mon peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Or on avait ordonné son sépulcre avec les méchants, mais il a été avec le riche en sa mort; car il n’avait point fait d’outrage, et il ne s’est point trouvé de fraude en sa bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Toutefois l’Eternel l’ayant voulu froisser, l’a mis en langueur. Après qu’il aura mis son âme en oblation pour le péché, il se verra de la postérité, il prolongera ses jours et le bon plaisir de l’Eternel prospérera en sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Il jouira du travail de son âme, et en sera rassasié; mon serviteur juste en justifiera plusieurs par la connaissance qu’ils auront de lui; et lui-même portera leurs iniquités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'C’est pourquoi je lui donnerai son partage parmi les grands, et il partagera le butin avec les puissants, parce qu’il aura épandu son âme à la mort, qu’il aura été mis au rang des transgresseurs, et que lui-même aura porté les péchés de plusieurs, et aura intercédé pour les transgresseurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Réjouis-toi avec chant de triomphe, stérile qui n’enfantais point, toi qui ne savais ce que c’est du travail d’enfant, éclate de joie avec chant de triomphe, et t’égaye; car les enfants de celle qui était délaissée, seront en plus grand nombre que les enfants de celle qui était mariée, a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Elargis le lieu de ta tente, et qu’on étende les courtines de tes pavillons; n’épargne rien, allonge tes cordages, et fais tenir ferme tes pieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Car tu te répandras à droite et à gauche, et ta postérité possédera les nations, et rendra habitées les villes désertes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Ne crains point, car tu ne seras point honteuse, ni confuse, et tu ne rougiras point; mais tu oublieras la honte de ta jeunesse, et tu ne te souviendras plus de l’opprobre de ton veuvage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Car ton mari est celui qui t’a faite; l’Eternel des armées est son Nom; et ton Rédempteur est le Saint d’Israël: il sera appelé le Dieu de toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Car l’Eternel t’a appelée comme une femme délaissée et travaillée en son esprit, et comme une femme qu’on aurait épousée dans la jeunesse, et qui aurait été répudiée, a dit ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Je t’ai délaissée pour un petit moment; mais je te rassemblerai par de grandes compassions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'J’ai caché ma face arrière de toi pour un moment dans le temps de l’indignation; mais j’ai eu compassion de toi par une gratuité éternelle, a dit l’Eternel ton Rédempteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Car ceci me sera comme les eaux de Noé; c’est que comme j’ai juré que les eaux de Noé ne passeront plus sur la terre; ainsi j’ai juré que je ne serai plus indigné contre toi, et que je ne te tancerai plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Car quand les montagnes se remueraient, et que les coteaux crouleraient, ma gratuité ne se retirera point de toi, et l’alliance de ma paix ne bougera point, a dit l’Eternel, qui a compassion de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'O affligée! agitée de la tempête, destituée de consolation, voici, je m’en vais coucher des escarboucles pour tes pierres, et je te fonderai sur des saphirs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'Et je ferai tes fenêtrages d’agates, et tes portes seront de pierres de rubis, et toute ton enceinte de pierres précieuses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Aussi tous tes enfants seront enseignés de l’Eternel, et la paix de tes fils sera abondante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Tu seras affermie en justice, tu seras loin de l’oppression, et tu ne craindras rien; tu seras, dis-je, loin de la frayeur, car elle n’approchera point de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Voici, on ne manquera pas de comploter contre toi, mais ce ne sera pas de par moi; quiconque complotera contre toi, tombera pour l’amour de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Voici, c’est moi qui ai créé le forgeron soufflant le charbon au feu, et formant l’instrument pour son ouvrage; et c’est moi qui ai créé le destructeur pour dissiper.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Nulles armes forgées contre toi ne prospéreront, et tu convaincras de malice toute langue qui se sera élevée contre toi en jugement; c’est là l’héritage des serviteurs de l’Eternel, et leur justice de par moi, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Hola, vous tous qui êtes altérés, venez aux eaux, et vous qui n’avez point d’argent, venez, achetez, et mangez; venez, dis-je, achetez sans argent et sans aucun prix, du vin et du lait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Pourquoi employez-vous l’argent pour des choses qui ne nourrissent point? et votre travail pour des choses qui ne rassasient point? écoutez-moi attentivement, et vous mangerez de ce qui est bon, et votre âme jouira à plaisir de la graisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Inclinez votre oreille, et venez à moi; écoutez, et votre âme vivra; et je traiterai avec vous une alliance éternelle, savoir les gratuités immuables promises à David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Voici, je l’ai donné pour être témoin aux peuples, pour être conducteur, et pour donner des commandements aux peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Voici, tu appelleras la nation que tu ne connaissais point, et les nations qui ne te connaissaient point accourront à toi, à cause de l’Eternel ton Dieu et du Saint d’Israël qui t’aura glorifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Cherchez l’Eternel pendant qu’il se trouve, invoquez-le tandis qu’il est près.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Que le méchant laisse sa voie, et l’homme injuste ses pensées, et qu’il retourne à l’Eternel, et il aura pitié de lui; et à notre Dieu, car il pardonne abondamment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Car mes pensées ne sont pas vos pensées, et mes voies ne sont pas vos voies, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Mais autant que les cieux sont élevés par-dessus la terre, autant mes voies sont élevées par-dessus vos voies; et mes pensées, par- dessus vos pensées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Car comme la pluie et la neige descendent des cieux, et n’y retournent plus, mais arrosent la terre, et la font produire, et germer, tellement qu’elle donne la semence au semeur, et le pain à celui qui mange;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'Ainsi sera ma parole qui sera sortie de ma bouche, elle ne retournera point vers moi sans effet, mais elle fera tout ce en quoi j’aurai pris plaisir, et prospérera dans les choses pour lesquelles je l’aurai envoyée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Car vous sortirez avec joie, et vous serez conduits en paix; les montagnes et les coteaux éclateront de joie avec chant de triomphe devant vous, et tous les arbres des champs frapperont des mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Au lieu du buisson croîtra le sapin; et au lieu de l’épine croîtra le myrte; et ceci fera connaître le nom de l’Eternel et ce sera un signe perpétuel, qui ne sera point retranché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Ainsi a dit l’Eternel; observez la justice, et faites ce qui est juste; car mon salut est prêt à venir; et ma justice à être révélée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'O que bienheureux est l’homme qui fera cela, et le fils de l’homme qui s’y tiendra, observant le Sabbat de peur de le profaner, et gardant ses mains de faire aucun mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Et que l’enfant de l’étranger qui se sera joint à l’Eternel, ne parle point, en disant; l’Eternel me sépare entièrement de son peuple; et que l’eunuque ne dise point; voici, je suis un arbre sec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Car ainsi a dit l’Eternel touchant les eunuques; ceux qui garderont mes Sabbats, et qui choisiront ce en quoi je prends plaisir, et se tiendront à mon alliance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'Je leur donnerai dans ma maison et dans mes murailles une place et un nom meilleur que le nom de fils ou de filles; je leur donnerai à chacun une réputation perpétuelle, qui ne sera point retranché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Et quant aux enfants de l’étranger qui se seront joints à l’Eternel, pour le servir, et pour aimer le Nom de l’Eternel, afin de lui être serviteurs, savoir tous ceux qui gardent le sabbat de peur de le profaner, et qui se tiennent à mon alliance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'Je les amènerai aussi à la montagne de ma sainteté, et je les réjouirai dans la maison dans laquelle on m’invoque, leurs holocaustes et leurs sacrifices seront agréables sur mon autel; car ma maison sera appelée, la maison de prière pour tous les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Encore en assemblerai-je vers lui outre ceux qui y sont assemblés, dit le Seigneur l’Eternel, qui rassemble les exilés d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Bêtes des champs, bêtes des forêts, venez toutes pour manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Toutes ses sentinelles sont aveugles; elles ne savent rien; ce sont tous des chiens muets qui ne peuvent aboyer, dormant et demeurant couchés, et aimant à sommeiller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Ce sont des chiens goulus, qui ne savent ce que c’est que d’être rassasiés; et ce sont des pasteurs qui ne savent rien comprendre; ils se sont tous tournés à leur train, chacun à son gain déshonnête dans son quartier, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Venez, je prendrai du vin et nous nous enivrerons de cervoise; et le jour de demain sera comme celui d’aujourd’hui, même beaucoup plus grand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Le juste est mort, et il n’y a personne qui y prenne garde; et les gens de bien sont recueillis, sans qu’on y soit attentif, sans qu’on considère que le juste a été recueilli de devant le mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Il entrera en paix, ils se reposent dans leurs sépulcres, savoir quiconque aura marché devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Mais vous enfants de la devineresse, race adultère, et qui paillardez, approchez ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'De qui vous êtes-vous moqués? contre qui avez-vous ouvert la bouche, et tiré la langue? n’êtes-vous pas des enfants prévaricateurs, et une fausse race?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Qui vous échauffez après les chênes, et sous tout arbre vert; et qui égorgez les enfants dans les vallées, sous les quartiers des rochers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Ta portion est dans les pierres polies des torrents; ce sont elles, ce sont elles, qui sont ton lot; tu leur as aussi répandu ton aspersion, tu leur as offert des offrandes; pourrai-je être content de ces choses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Tu as mis ton lit sur les montagnes hautes et élevées, même tu y es montée pour faire des sacrifices.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Et tu as mis derrière la porte et derrière le poteau ton mémorial, car tu t’es découverte loin de moi, et tu es montée, tu as élargi ton lit, et tu te l’es taillé plus grand que n’ont fait ceux-là; tu as aimé leur lit, tu as pris garde aux belles places.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Tu as voyagé vers le Roi avec des onguents précieux, et tu as ajouté parfums sur parfums; tu as envoyé tes ambassades bien loin, et tu t’es abaissée jusqu’aux enfers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Tu t’es travaillée dans la longueur de ton chemin, et tu n’as point dit; c’en est fait. Tu as trouvé la vigueur de ta main, et à cause de cela tu n’as point été languissante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Et de qui as-tu eu peur, qui as-tu craint, que tu m’aies menti, et que tu ne te sois point souvenue de moi, et que tu ne t’en sois point souciée? Est-ce que je me suis tu; même de si longtemps, que tu ne m’aies point craint?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Je déclarerai ta justice et tes oeuvres, qui ne te profiteront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Que ceux que tu assembles te délivrent, quand tu crieras; mais le vent les enlèvera tous, la vanité les emportera; mais celui qui se retire vers moi héritera la terre, et possédera la montagne de ma sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Et on dira; relevez, relevez, préparez les chemins, ôtez les empêchements loin du chemin de mon peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Car ainsi a dit celui qui est haut et élevé, qui habite dans l’éternité et duquel le nom est le Saint; j’habiterai dans le lieu haut et Saint, et avec celui qui a le coeur brisé, et qui est humble d’esprit, afin de vivifier l’esprit des humbles, et afin de vivifier ceux qui ont le coeur brisé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Parce que je ne débattrai point à toujours, et que je ne serai point indigné à jamais; car c’est de par moi que l’esprit se revêt, et c’est moi qui ai fait les âmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'A cause de l’iniquité de son gain déshonnête j’ai été indigné, et je l’ai frappé; j’ai caché ma face, et j’ai été indigné; mais le revêche s’en est allé, et a suivi la voie de son coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'J’ai vu ses voies, et toutefois je l’ai guéri; je l’ai ramené, et je lui ai rendu ses consolations, savoir, à ceux d’entre eux qui mènent deuil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Je crée ce qui est proféré par les lèvres; paix, paix à celui qui est loin, et à celui qui est près, a dit l’Eternel, car je le guérirai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Mais les méchants sont comme la mer qui est dans la tourmente, quand elle ne se peut apaiser; et ses eaux jettent de la bourbe et du limon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Il n’y a point de paix pour les méchants, a dit mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Crie à plein gosier, ne t’épargne point, élève ta voix comme un cor, et déclare à mon peuple leur iniquité, et à la maison de Jacob leurs péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Car ils me cherchent chaque jour, et prennent plaisir à savoir mes voies, comme une nation qui aurait suivi la justice, et qui n’aurait point abandonné le jugement de son Dieu; ils s’informent auprès des jugements de justice, et prennent plaisir à approcher de Dieu; et puis ils disent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Pourquoi avons-nous jeûné, et tu n’y as point eu d’égard? pourquoi avons-nous affligé nos âmes, et tu ne t’en es point soucié? Voici, au jour de votre jeûne vous trouvez votre volonté, et vous exigez tout ce en quoi vous tourmentez les autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Voici, vous jeûnez pour faire des procès et des querelles, et pour frapper du poing méchamment; vous ne jeûnez point comme ce jour le requerrait afin de faire que votre voix soit exaucée d’en haut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Est-ce là le jeûne que j’ai choisi, que l’homme afflige son âme un jour? Est-ce en courbant sa tête comme le jonc, et en étendant le sac et la cendre? appelleras-tu cela un jeûne, et un jour agréable à l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'N’est-ce pas plutôt ici le jeûne que j’ai choisi, que tu dénoues les liens de la méchanceté; que tu délies les cordages du joug, que tu laisses aller libres ceux qui sont foulés; et que vous rompiez tout joug?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'N’est-ce pas que tu partages ton pain à celui qui a faim? et que tu fasses venir en ta maison les affligés qui sont errants? quand tu vois un homme nu, que tu le couvres, et que tu ne te caches point arrière de ta chair?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Alors ta lumière éclôra comme l’aube du jour, et ta guérison germera incontinent, ta justice ira devant toi, et la gloire de l’Eternel sera ton arrière-garde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Alors tu prieras, et l’Eternel t’exaucera; tu crieras, et il dira; me voici. Si tu ôtes du milieu de toi le joug, et que tu cesses de hausser le doigt, et de dire des outrages;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'Si tu ouvres ton coeur à celui qui a faim, et que tu rassasies l’âme affligée; et ta lumière naîtra dans les ténèbres, et les ténèbres seront comme le Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Et l’Eternel te conduira continuellement, il rassasiera ton âme dans les grandes sécheresses, il engraissera tes os, et tu seras comme un jardin arrosé, et comme une source dont les eaux ne défaillent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Et des gens sortiront de toi qui rebâtiront les lieux déserts depuis longtemps; tu rétabliras les fondements ruinés depuis plusieurs générations; et on t’appellera le Réparateur des brèches, et le redresseur des chemins; afin qu’on habite au pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Si tu retires ton pied du Sabbat, toi qui fais ta volonté au jour de ma sainteté; et si tu appelles le Sabbat tes délices, et honorable ce qui est saint à l’Eternel, et que tu l’honores en ne suivant point tes voies, ne trouvant point ta volonté, et n’usant point de beaucoup de paroles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'Alors tu jouiras de délices en l’Eternel, et je te ferai passer comme à cheval par-dessus les lieux haut élevés de la terre, et je te donnerai à manger l’héritage de Jacob ton père; car la bouche de l’Eternel a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Voici, la main de l’Eternel n’est pas raccourcie pour ne pouvoir pas délivrer, et son oreille n’est pas devenue pesante, pour ne pouvoir pas ouïr.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Mais ce sont vos iniquités qui ont fait séparation entre vous et votre Dieu; et vos péchés ont fait qu’il a caché sa face de vous, afin qu’il ne vous entende point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Car vos mains sont souillées de sang, et vos doigts d’iniquité; vos lèvres ont proféré le mensonge, et votre langue a prononcé la perversité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Il n’y a personne qui crie pour la justice, et il n’y a personne qui plaide pour la vérité; on se fie en des choses de néant, et on parle vanité; on conçoit le travail, et on enfante le tourment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Ils ont éclos des oeufs de basilic, et ils ont tissu des toiles d’araignée; celui qui aura mangé de leurs oeufs en mourra; et si on les écrase, il en sortira une vipère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Leurs toiles ne serviront point à faire des vêtements, et on ne se couvrira point de leurs ouvrages; car leurs ouvrages sont des ouvrages de tourment, et il y a en leurs mains des actions de violence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Leurs pieds courent au mal, et se hâtent pour répandre le sang innocent; leurs pensées sont des pensées de tourment; le dégât et la calamité est dans leurs voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Ils ne connaissent point le chemin de la paix, et il n’y a point de jugement dans leurs ornières, ils se sont pervertis dans leurs sentiers, tous ceux qui y marchent ignorent la paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'C’est pourquoi le jugement s’est éloigné de nous, et la justice ne vient point jusques à nous; nous attendions la lumière, et voici les ténèbres; la splendeur, et nous marchons dans l’obscurité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Nous avons tâtonné après la paroi comme des aveugles; nous avons, dis-je, tâtonné comme ceux qui sont sans yeux; nous avons bronché en plein midi comme sur la brune, et nous avons été dans les lieux abondants comme y seraient des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Nous rugissons tous comme des ours, et nous ne cessons de gémir comme des colombes; nous attendions le jugement, et il n’y en a point; la délivrance, et elle s’est éloignée de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Car nos forfaits se sont multipliés devant toi, et chacun de nos péchés a témoigné contre nous; parce que nos forfaits sont avec nous, et nous connaissons nos iniquités;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Qui sont de pécher et de mentir contre l’Eternel, de s’éloigner de notre Dieu, de proférer l’oppression et la révolte; de concevoir et prononcer du coeur des paroles de mensonge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'C’est pourquoi le jugement s’est éloigné et la justice s’est tenue loin; car la vérité est tombée par les rues, et la droiture n’y a pu entrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Même la vérité a disparu, et quiconque se retire du mal est exposé au pillage; l’Eternel l’a vu, et cela lui a déplu, parce qu’il n’y a point de droiture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Il a vu aussi qu’il n’ y avait point d’homme qui soutînt l’innocence et il s’est étonné que personne ne se mettait à la brèche; c’est pourquoi son bras l’a délivré, et sa propre justice l’a soutenu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Car il s’est revêtu de la justice comme d’une cuirasse, et le casque du salut a été sur sa tête; il s’est revêtu des habits de la vengeance comme d’un vêtement, et s’est couvert de jalousie comme d’un manteau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Comme pour les rétributions, et comme quand quelqu’un veut rendre la pareille, savoir la fureur à ses adversaires, et la rétribution à ses ennemis; il rendra ainsi la rétribution aux Iles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Et on craindra le Nom de l’Eternel depuis l’Occident; et sa gloire depuis le Soleil levant; car l’ennemi viendra comme un fleuve, mais l’Esprit de l’Eternel lèvera l’enseigne contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Et le Rédempteur viendra en Sion, et vers ceux de Jacob qui se convertissent de leur péché, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Et quant à moi; c’est ici mon alliance que je ferai avec eux, a dit l’Eternel; mon Esprit qui est sur toi, et mes paroles que j’ai mises en ta bouche, ne bougeront point de ta bouche, ni de la bouche de ta postérité, ni de la bouche de la postérité de ta postérité, a dit l’Eternel, dès maintenant et à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Lève-toi, sois illuminée; car ta lumière est venue, et la gloire de l’Eternel s’est levée sur toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Car voici, les ténèbres couvriront la terre, et l’obscurité couvrira les peuples; mais l’Eternel se lèvera sur toi, et sa gloire paraîtra sur toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Et les nations marcheront à ta lumière, et les Rois à la splendeur qui se lèvera sur toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Elève tes yeux à l’environ, et regarde; tous ceux-ci se sont assemblés, ils sont venus vers toi; tes fils viendront de loin, et tes filles seront nourries par des nourriciers, étant portées sur les côtés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Alors tu verras, et tu seras éclairée, et ton coeur s’étonnera, et s’épanouira de joie, quand l’abondance de la mer se sera tournée vers toi, et que la puissance des nations sera venue chez toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Une abondance de chameaux te couvrira; les dromadaires de Madian et d’Hépha, et tous ceux de Séba viendront, ils apporteront de l’or et de l’encens, et publieront les louanges de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Toutes les brebis de Kédar seront assemblées vers toi, les moutons de Nébajoth seront pour ton service; ils seront agréables étant offerts sur mon autel, et je rendrai magnifique la maison de ma gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Quelles sont ces volées, épaisses comme des nuées, qui volent comme des pigeons à leurs trous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Car les Iles s’attendront à moi, et les navires de Tarsis les premiers, afin d’amener tes fils de loin, avec leur argent et leur or, pour l’amour du Nom de l’Eternel ton Dieu, et du Saint d’Israël, parce qu’il t’aura glorifiée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Et les fils des étrangers rebâtiront tes murailles, et leurs Rois seront employés à ton service; car je t’ai frappée en ma fureur, mais j’ai eu pitié de toi au temps de mon bon plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Tes portes aussi seront continuellement ouvertes, elles ne seront fermées ni nuit ni jour, afin que les forces des nations te soient amenées, et que leurs Rois y soient conduits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Car la nation et le Royaume qui ne te serviront point, périront; et ces nations-là seront réduites en une entière désolation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'La gloire du Liban viendra vers toi, le sapin, l’orme, et le buis ensemble, pour rendre honorable le lieu de mon Sanctuaire; et je rendrai glorieux le lieu de mes pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Même les enfants de ceux qui t’auront affligée viendront vers toi en se courbant; et tous ceux qui te méprisaient se prosterneront à tes pieds, et t’appelleront, La ville de l’Eternel, la Sion du Saint d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Au lieu que tu as été délaissée et haïe, tellement qu’il n’y avait personne qui passât parmi toi, je te mettrai dans une élévation éternelle, et dans une joie qui sera de génération en génération.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Et tu suceras le lait des nations, et tu suceras la mamelle des Rois, et tu sauras que je suis l’Eternel ton Sauveur, et ton Rédempteur, le Puissant de Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Je ferai venir de l’or au lieu de l’airain, et je ferai venir de l’argent au lieu du fer, et de l’airain au lieu du bois, et du fer au lieu des pierres; et je ferai que la paix te gouvernera, et que tes exacteurs ne seront que justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'On n’entendra plus parler de violence en ton pays, ni de dégât, ni de calamité en tes contrées, mais tu appelleras tes murailles, Salut, et tes portes, Louange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Tu n’auras plus le soleil pour la lumière du jour, et la lueur de la lune ne t’éclairera plus; mais l’Eternel te sera pour lumière éternelle, et ton Dieu pour ta gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Ton soleil ne se couchera plus, et ta lune ne se retirera plus, car l’Eternel te sera pour lumière perpétuelle, et les jours de ton deuil seront finis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Et quant à ton peuple, ils seront tous justes; ils posséderont éternellement la terre; savoir le germe de mes plantes, l’oeuvre de mes mains, pour y être glorifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'La petite famille croîtra jusqu’à mille personnes, et la moindre deviendra une nation forte. Je suis l’Eternel, je hâterai ceci en son temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'L’Esprit du Seigneur l’Eternel est sur moi, c’est pourquoi l’Eternel m’a oint pour évangéliser aux débonnaires, il m’a envoyé pour guérir ceux qui ont le cœur brisé, pour publier aux captifs la liberté, et aux prisonniers l’ouverture de la prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'Pour publier l’an de la bienveillance de l’Eternel, et le jour de la vengeance de notre Dieu; pour consoler tous ceux qui mènent deuil;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'Pour annoncer à ceux de Sion qui mènent deuil, que la magnificence leur sera donnée au lieu de la cendre; l’huile de joie au lieu du deuil; le manteau de louange au lieu de l’esprit d’accablement; tellement qu’on les appellera les chênes de la justice, et la plante de l’Eternel, pour s’y glorifier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Et ils rebâtiront ce qui aura été dès longtemps désert, ils rétabliront les lieux qui auront été auparavant désolés, et ils renouvelleront les villes désertes, et les choses désolées d’âge en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Et les étrangers s’y tiendront, et paîtront vos brebis, et les enfants de l’étranger seront vos laboureurs et vos vignerons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Mais vous, vous serez appelés les Sacrificateurs de l’Eternel, et on vous nommera les Ministres de notre Dieu; vous mangerez les richesses des nations, et vous vous vanterez de leur gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Au lieu de la honte que vous avez eue les nations en auront le double, et elles crieront tout haut que la confusion est leur portion; c’est pourquoi ils posséderont le double en leur pays, et auront une joie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Car je suis l’Eternel, qui aime le jugement, et qui hais la rapine pour l’holocauste; j’établirai leur oeuvre dans la vérité, et je traiterai avec eux une alliance éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Et leur race sera connue entre les nations, et ceux qui seront sortis d’eux, seront connus parmi les peuples; tous ceux qui les verront connaîtront qu’ils sont la race que l’Eternel aura bénie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Je me réjouirai extrêmement en l’Eternel, et mon âme s’égayera en mon Dieu; car il m’a revêtu des vêtements du salut, et m’a couvert du manteau de la justice, comme un époux qui se pare de magnificence, et comme une épouse qui s’orne de ses joyaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Car comme la terre pousse son germe, et comme un jardin fait germer les choses qui y sont semées, ainsi le Seigneur l’Eternel fera germer la justice, et la louange en la présence de toutes les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Pour l’amour de Sion je ne me tiendrai point tranquille, et pour l’amour de Jérusalem je ne serai point en repos que sa justice ne sorte dehors comme une splendeur, et que sa délivrance ne soit allumée comme une lampe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Alors les nations verront ta justice, et tous les Rois, ta gloire; et on t’appellera d’un nouveau nom, que la bouche de l’Eternel aura expressément déclaré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Tu seras une couronne d’ornement en la main de l’Eternel, et une tiare royale dans la main de ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'On ne te nommera plus, la délaissée, et on ne nommera plus ta terre, la désolation; mais on t’appellera, mon bon plaisir en elle; et ta terre, la mariée, car l’Eternel prendra son bon plaisir en toi, et ta terre aura un mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Car comme le jeune homme se marie à la vierge, et comme tes enfants se marient chez toi, ainsi ton Dieu se réjouira de toi, de la joie qu’un époux a de son épouse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Jérusalem, j’ai ordonné des gardes sur tes murailles tout le jour et toute la nuit continuellement, ils ne se tairont point. Vous qui faites mention de l’Eternel ne gardez point le silence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'Et ne discontinuez point de l’invoquer jusques à ce qu’il rétablisse et remette Jérusalem en un état renommé sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'L’Eternel a juré par sa dextre, et par le bras de sa force; si je donne plus ton froment pour nourriture à tes ennemis, et si les étrangers boivent plus ton vin excellent pour lequel tu as travaillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Car ceux qui auront amassé le froment, le mangeront, et ils loueront l’Eternel; et ceux qui auront recueilli le vin, le boiront dans les parvis de ma sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Passez, passez par les portes, disant; Préparez le chemin du peuple, relevez, relevez le sentier, et ôtez-en les pierres, et élevez l’enseigne vers les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Voici, l’Eternel a fait entendre ceci jusques au bout de la terre; Dites à la fille de Sion; voici, ton Sauveur vient; voici, son salaire est par-devers lui, et sa récompense marche devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Et on les appellera, le peuple saint, les rachetés de l’Eternel, et on t’appellera, la recherchée, la ville non abandonnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Qui est celui-ci qui vient d’Edom, de Botsra, ayant les habits teints en rouge; celui-ci qui est magnifiquement paré en son vêtement, marchant selon la grandeur de sa force? C’est moi qui parle en justice, et qui ai tout pouvoir de sauver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Pourquoi y a-t-il du rouge en ton vêtement? et pourquoi tes habits sont-ils comme les habits de ceux qui foulent au pressoir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'J’ai été tout seul à fouler au pressoir, et personne d’entre les peuples n’a été avec moi; cependant j’ai marché sur eux en ma colère, et je les ai foulés en ma fureur; et leur sang a rejailli sur mes vêtements, et j’ai souillé tous mes habits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Car le jour de la vengeance est dans mon cœur, et l’année en laquelle je dois racheter les miens, est venue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'J’ai donc regardé, et il n’y a eu personne qui m’aidât; et j’ai été étonné, et il n’y a eu personne qui me soutînt; mais mon bras m’a sauvé, et ma fureur m’a soutenu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Ainsi j’ai foulé les peuples en ma colère, et je les ai enivrés en ma fureur; et j’ai abattu leur force par terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Je ferai mention des gratuités de l’Eternel, qui sont les louanges de l’Eternel, à cause de tous les bienfaits que l’Eternel nous a faits; car grand est le bien de la maison d’Israël, lequel il leur a fait selon ses compassions, et selon la grandeur de ses gratuités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Car il a dit; quoi qu’il en soit, ils sont mon peuple, des enfants qui ne dégénéreront point; et il leur a été Sauveur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Et dans toute leur angoisse il a été en angoisse, et l’Ange de sa face les a délivrés; lui-même les a rachetés par son amour et sa clémence, et il les a portés, et les a élevés en tout temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Mais ils ont été rebelles, et ils ont contristé l’Esprit de sa sainteté, c’est pourquoi il est devenu leur ennemi, et il a lui- même combattu contr’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Et on s’est souvenu des jours anciens de Moïse, et de son peuple. Où est celui, a-t-on dit, qui les faisait remonter hors de la mer, avec les pasteurs de son troupeau? où est celui qui mettait au milieu d’eux l’Esprit de sa sainteté;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Qui les menait étant à la main droite de Moïse, par le bras de sa gloire? qui fendait les eaux devant eux, afin qu’il s’acquît un nom éternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Qui les menait par les abîmes, et ils n’y ont point bronché, non plus que le cheval dans un lieu de pâturage?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'L’Esprit de l’Eternel les a menés tout doucement comme on mène une bête qui descend dans une plaine; tu as ainsi conduit ton peuple, afin de t’acquérir un nom glorieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Regarde des cieux, et vois de la demeure de ta sainteté et de ta gloire. Où est ta jalousie, et ta force, et l’émotion bruyante de tes entrailles et de tes compassions, lesquelles se sont retenues envers moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Certes tu es notre Père, encore qu’Abraham ne nous reconnût point, et qu’Israël ne nous avouât point; Eternel, c’est toi qui es notre Père, et ton Nom est notre Rédempteur de tout temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Pourquoi nous as-tu fait égarer, ô Eternel! hors de tes voies, et pourquoi as-tu aliéné notre cœur de ta crainte? retourne-toi en faveur de tes serviteurs, en faveur des Tribus de ton héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Le peuple de ta sainteté a été en possession bien peu de temps; nos ennemis ont foulé ton Sanctuaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Nous avons été comme ceux sur lesquels tu ne domines point depuis longtemps, et sur lesquels ton Nom n’est point réclamé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'A la mienne volonté que tu fendisses les cieux, et que tu descendisses, et que les montagnes s’écoulassent de devant toi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'Comme un feu de fonte est ardent, et comme le feu fait bouillir l’eau; tellement que ton Nom fût manifesté à tes ennemis, et que les nations tremblassent à cause de ta présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Quand tu fis les choses terribles que nous n’attendions point, tu descendis, et les montagnes s’écoulèrent de devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Et on n’a jamais ouï ni entendu des oreilles, ni l’œil n’a jamais vu de Dieu hormis toi, qui fît de telles choses pour ceux qui s’attendent à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Tu es venu rencontrer celui qui se réjouissait, et qui se portait justement; ils se souviendront de toi dans tes voies; voici, tu as été ému à indignation parce que nous avons péché; tes compassions sont éternelles, c’est pourquoi nous serons sauvés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Or nous sommes tous devenus comme une chose souillée, et toutes nos justices sont comme le linge le plus souillé; nous sommes tous tombés comme la feuille, et nos iniquités nous ont transportés comme le vent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Et il n’y a personne qui réclame ton Nom, qui se réveille pour te demeurer fortement attaché; c’est pourquoi tu as caché ta face de nous, et tu nous as fait fondre par la force de nos iniquités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Mais maintenant, ô Eternel! tu es notre Père; nous sommes l’argile, et tu es celui qui nous as formés, et nous sommes tous l’ouvrage de ta main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Eternel, ne sois point excessivement indigné contre nous, et ne te souviens point à toujours de notre iniquité. Voici, regarde, nous te prions, nous sommes tous ton peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Les villes de ta sainteté sont devenues un désert; Sion est devenue un désert, et Jérusalem une désolation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'La maison de notre sanctification et de notre magnificence, où nos pères t’ont loué, a été brûlée par le feu, et il n’y a rien eu de toutes les choses qui nous étaient chères qui n’ait été désolé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'Eternel, ne te retiendras-tu pas après ces choses? et ne cesseras-tu pas? car tu nous as extrêmement affligés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Je me suis fait rechercher de ceux qui ne me demandaient point, et je me suis fait trouver à ceux qui ne me cherchaient point; j’ai dit à la nation qui ne s’appelait point de mon Nom; me voici, me voici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'J’ai tout le jour étendu mes mains au peuple rebelle, à ceux qui marchent dans le mauvais chemin, savoir après leurs pensées;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'Au peuple de ceux qui m’irritent continuellement en face, qui sacrifient dans les jardins, et qui font des parfums sur les autels de briques.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'Qui se tiennent dans les sépulcres, et passent la nuit dans les lieux désolés; qui mangent la chair de pourceau, et qui ont dans leurs vaisseaux le jus des choses abominables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'Qui disent; retire toi, n’approche point de moi, car je suis plus saint que toi; ceux-là sont une fumée à mes narines, un feu ardent tout le jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Voici, ceci est écrit devant moi, je ne m’en tairai point, mais je le rendrai, oui je le rendrai dans leur sein,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'A savoir vos iniquités, et les iniquités de vos pères ensemble, a dit l’Eternel; lesquels ont fait des parfums sur les montagnes, et m’ont déshonoré sur les coteaux; c’est pourquoi je leur mesurerai aussi dans leur sein le salaire de ce qu’ils ont fait au commencement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Ainsi a dit l’Eternel; comme quand on trouve dans une grappe du vin à épreindre, et qu’on dit; ne la gâte pas, car il y a en elle de la bénédiction; j’en ferai de même à cause de mes serviteurs, afin que le tout ne soit point détruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Et je ferai sortir de la postérité de Jacob et de Juda celui qui héritera mes montagnes, et mes élus hériteront le pays, et mes serviteurs y habiteront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Et Saron sera pour les cabanes du menu bétail, et la vallée de Hachor sera le gîte du gros bétail, pour mon peuple qui m’aura recherché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Mais vous, qui abandonnez l’Eternel, et qui oubliez la montagne de ma sainteté, qui dressez la table à l’armée des cieux, et qui fournissez l’aspersion à autant qu’on en peut compter;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'Je vous compterai aussi avec l’épée, et vous serez tous courbés, pour être égorgés; parce que j’ai appelé, et que vous n’avez point répondu; j’ai parlé, et vous n’avez point écouté; mais vous avez fait ce qui me déplaît, et vous avez choisi les choses auxquelles je ne prends point de plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'C’est pourquoi, ainsi a dit le Seigneur l’Eternel; voici, mes serviteurs mangeront, et vous aurez faim; voici, mes serviteurs boiront, et vous aurez soif; voici mes serviteurs se réjouiront, et vous serez honteux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Voici, mes serviteurs se réjouiront avec chant de triomphe pour la joie qu’ils auront au cœur, mais vous crierez pour la douleur que vous aurez au cœur, et vous hurlerez à cause de l’accablement de votre esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Et vous laisserez votre nom à mes élus pour s’en servir dans les exécrations, et le Seigneur l’Eternel te fera mourir; mais il appellera ses serviteurs d’un autre nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Celui qui se bénira en la terre, se bénira par le Dieu de Vérité; et celui qui jurera sur la terre, jurera par le Dieu de Vérité; car les angoisses du passé seront oubliées, et même elles seront cachées devant mes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Car voici, je m’en vais créer de nouveaux cieux, et une nouvelle terre; et on ne se souviendra plus des choses précédentes, et elles ne reviendront plus au cœur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Mais plutôt vous vous réjouirez, et vous vous égayerez à toujours en ce que je m’en vais créer; car voici, je m’en vais créer Jérusalem, pour n’être que joie, et son peuple, pour n’être qu’allégresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Je m’égayerai donc sur Jérusalem, et je me réjouirai sur mon peuple; et on n’y entendra plus de voix de pleurs, ni de voix de clameurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Il n’y aura plus désormais aucun enfant né depuis peu de jours, ni aucun vieillard qui n’accomplisse ses jours; car celui qui mourra âgé de cent ans sera encore jeune; mais le pécheur âgé de cent ans sera maudit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Même ils bâtiront des maisons, et y habiteront; ils planteront des vignes, et ils en mangeront le fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Ils ne bâtiront pas des maisons afin qu’un autre y habite; ils ne planteront pas des vignes afin qu’un autre en mange le fruit; car les jours de mon peuple seront comme les jours des arbres; et mes élus perpétueront le travail de leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Ils ne travailleront plus en vain, et n’engendreront plus des enfants pour être exposés à la frayeur; car ils seront la postérité des bénis de l’Eternel, et ceux qui sortiront d’eux seront avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Et il arrivera qu’avant qu’ils crient, je les exaucerai; et lorsque encore ils parleront, je les aurai déjà ouïs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Le loup et l’agneau paîtront ensemble, et le lion mangera du fourrage comme le bœuf, et la poudre sera la nourriture du serpent; on ne nuira point, et on ne fera aucun dommage dans toute la montagne de ma sainteté; a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Ainsi a dit l’Eternel; les cieux sont mon trône, et la terre est le marchepied de mes pieds: quelle maison me bâtiriez-vous, et quel serait le lieu de mon repos?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Car ma main a fait toutes ces choses, et c’est par moi que toutes ces choses ont eu leur être, dit l’Eternel. Mais à qui regarderai-je? à celui qui est affligé, et qui a l’esprit brisé, et qui tremble à ma parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Celui qui égorge un bœuf, c’est comme qui tuerait un homme; celui qui sacrifie une brebis, c’est comme qui couperait le cou à un chien; celui qui offre un gâteau, c’est comme qui offrirait le sang d’un pourceau; celui qui fait un parfum d’encens, c’est comme qui bénirait une idole. Mais ils ont choisi leurs voies, et leur âme a pris plaisir en leurs abominations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Moi aussi je ferai attention à leurs tromperies, et je ferai venir sur eux les choses qu’ils craignent; parce que j’ai crié, et qu’il n’y a eu personne qui répondît: que j’ai parlé, et qu’ils n’ont point écouté; parce qu’ils ont fait ce qui me déplaît, et qu’ils ont choisi les choses auxquelles je ne prends point de plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Ecoutez la parole de l’Eternel, vous qui tremblez à sa parole; vos frères qui vous haïssent, et qui vous rejettent comme une chose abominable, à cause de mon Nom, ont dit; que l’Eternel montre sa gloire. Il sera donc vu à votre joie, mais eux seront honteux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Un son éclatant vient de la ville, un son vient du Temple, le son de l’Eternel, rendant la pareille à ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Elle a enfanté avant que de sentir le travail d’enfant; elle a été délivrée d’un enfant mâle, avant que les tranchées lui vinssent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Qui entendit jamais une telle chose, et qui en a jamais vu de semblables? Ferait-on qu’un pays fût enfanté en un jour? ou une nation naîtrait-elle tout d’un coup, que Sion ait enfanté ses fils aussitôt qu’elle a été en travail d’enfant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Moi qui fais enfanter les autres, ne ferais-je point enfanter Sion? a dit l’Eternel; Moi qui donne de la postérité aux autres, l’empêcherais-je d’enfanter? a dit ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Réjouissez-vous avec Jérusalem, et vous égayez en elle, vous tous qui l’aimez; vous tous qui meniez deuil sur elle, réjouissez-vous avec elle l’une grande joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Afin que vous soyez allaités, et que vous soyez rassasiés de la mamelle de ses consolations; afin que vous suciez le lait, et que vous jouissiez à plaisir de toutes les sortes de sa gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Car ainsi a dit l’Eternel; voici, je m’en vais faire couler vers elle la paix comme un fleuve, et la gloire des nations comme un torrent débordé; et vous serez allaités, portés sur les côtés, et on vous fera jouer sur les genoux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Je vous caresserai pour vous apaiser, comme quand une mère caresse son enfant pour l’apaiser; car vous serez consolés en Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Et vous le verrez, et votre cœur se réjouira, et vos os germeront comme l’herbe; et la main de l’Eternel sera connue envers ses serviteurs; mais il sera ému à indignation contre ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Car voici, l’Eternel viendra avec le feu, et ses chariots seront comme la tempête, afin qu’il tourne sa colère en fureur, et sa menace en flamme de feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Car l’Eternel exercera jugement contre toute chair par le feu, et avec son épée, et le nombre de ceux qui seront mis à mort par l’Eternel, sera grand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Ceux qui se sanctifient et se purifient au milieu des jardins, l’un après l’autre, qui mangent de la chair de pourceau, et des choses abominables, comme des souris, seront ensemble consumés, a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Mais pour moi, voyant leurs oeuvres, et leurs pensées, le temps vient d’assembler toutes les nations et les langues; ils viendront, et verront ma gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Car je mettrai une marque en eux, et j’enverrai ceux d’entre eux qui seront réchappés, vers les nations, en Tarsis, en Pul, en Lud, gens tirant de l’arc, en Tubal, et en Javan, et vers les Iles éloignées qui n’ont point entendu ma renommée, et qui n’ont point vu ma gloire, et ils annonceront ma gloire parmi les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Et ils amèneront tous vos frères, d’entre toutes les nations, sur des chevaux, sur des chariots, et dans des litières, sur des mulets, et sur des dromadaires, pour offrande à l’Eternel, à la montagne de ma sainteté, à Jérusalem, a dit l’Eternel, comme lorsque les enfants d’Israël apportent l’offrande dans un vaisseau net, à la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Et même j’en prendrai d’entre eux pour Sacrificateurs, et pour Lévites, a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Car comme les nouveaux cieux et la nouvelle terre que je m’en vais faire, seront établis devant moi, dit l’Eternel; ainsi sera établie votre postérité, et votre nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'Et il arrivera que depuis une nouvelle lune jusqu’à l’autre, et d’un Sabbat à l’autre, toute chair viendra se prosterner devant ma face, a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'Et ils sortiront dehors, et verront les corps morts des hommes qui auront péché contre moi; car leur ver ne mourra point, et leur feu ne sera point éteint; et ils seront méprisés de tout le monde. ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Les paroles de Jérémie, fils de Hilkija, d’entre les Sacrificateurs qui étaient à Hanathoth, au pays de Benjamin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'Auquel fut adressée la parole de l’Eternel, aux jours de Josias fils d’Amon Roi de Juda, la treizième année de son règne;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'Laquelle lui fut aussi adressée aux jours de Jéhojakim, fils de Josias, Roi de Juda, jusqu’à la fin de la onzième année de Sédécias, fils de Josias, Roi de Juda, savoir jusqu’au temps que Jérusalem fut transportée, ce qui arriva au cinquième mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'La parole donc de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Avant que je te formasse dans le ventre de ta mère, je t’ai connu; et avant que tu fusses sorti de son sein, je t’ai sanctifié, je t’ai établi Prophète pour les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Et je répondis: Ha! ha! Seigneur Eternel! voici, je ne sais pas parler; car je suis un enfant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Et l’Eternel me dit: ne dis point: je suis un enfant; car tu iras partout où je t’enverrai, et tu diras tout ce que je te commanderai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Ne crains point de te montrer devant eux, car je suis avec toi pour te délivrer, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Et l’Eternel avança sa main, et en toucha ma bouche, puis l’Eternel me dit: voici, j’ai mis mes paroles en ta bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Regarde, je t’ai établi aujourd’hui sur les nations, et sur les Royaumes, afin que tu arraches et que tu démolisses, que tu ruines, et que tu détruises; que tu bâtisses, et que tu plantes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Puis la parole de l’Eternel me fut adressée, en disant: que vois-tu, Jérémie? Et je répondis: je vois une branche d’amandier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Et l’Eternel me dit: tu as bien vu; car je me hâte d’exécuter ma parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Alors la parole de l’Eternel me fut adressée pour la seconde fois, en disant: que vois-tu? Et je répondis: je vois un pot bouillant, dont le devant est tourné vers l’Aquilon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Et l’Eternel me dit: le mal se découvrira du côté de l’Aquilon sur tous les habitants de ce pays-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Car voici, je m’en vais appeler toutes les familles des Royaumes de l’Aquilon, dit l’Eternel; et elles viendront, et mettront chacune son trône à l’entrée des portes de Jérusalem, et près de toutes ses murailles à l’environ, et près de toutes les villes de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Et je leur prononcerai mes jugements, à cause de toute leur malice, par laquelle ils m’ont délaissé, et ont fait des parfums à d’autres dieux, et se sont prosternés devant l’ouvrage de leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Toi donc, trousse tes reins, et te lève, et dis-leur toutes les choses que je te commanderai; ne crains point de te montrer devant eux, de peur que je ne te fasse mettre en pièces en leur présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Car voici, je t’ai aujourd’hui établi comme une ville forte; et comme une colonne de fer, et comme des murailles d’airain, contre tout ce pays-ci, c’est-à-dire, contre les Rois de Juda, contre les principaux du pays, contre ses Sacrificateurs, et contre le peuple du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Et ils combattront contre toi, mais ils ne seront pas plus forts que toi; car je suis avec toi, dit l’Eternel, pour te délivrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Et la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Va, et crie, ceux de Jérusalem l’entendant, et dis: Ainsi a dit l’Eternel: il me souvient pour l’amour de toi de la compassion que j’ai eue pour toi en ta jeunesse, et de l’amour de tes épousailles, quand tu venais après moi dans le désert, en un pays qu’on ne sème point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Israël était une chose sainte à l’Eternel, c’étaient les prémices de son revenu; tous ceux qui le dévoraient étaient trouvés coupables, il leur en arrivait du mal, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Ecoutez la parole de l’Eternel, maison de Jacob, et vous toutes les familles de la maison d’Israël:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Ainsi a dit l’Eternel: quelle injustice ont trouvée vos pères en moi, qu’ils se soient éloignés de moi, qu’ils aient marché après la vanité, et qu’ils soient devenus vains?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Et ils n’ont point dit: où est l’Eternel qui nous a fait remonter du pays d’Egypte, qui nous a conduits par un désert, par un pays de landes et montagneux, par un pays aride et d’ombre de mort, par un pays où aucun homme n’avait passé, et où personne n’avait habité?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Car je vous ai fait entrer dans un pays de Carmel, afin que vous mangeassiez ses fruits, et de ses biens; mais sitôt que vous y êtes entrés, vous avez souillé mon pays, et avez rendu abominable mon héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Les Sacrificateurs n’ont point dit: où est l’Eternel? Et ceux qui expliquaient la Loi, ne m’ont point connu; et les pasteurs ont prévariqué contre moi, et les prophètes ont prophétisé de par Bahal, et ont marché après des choses qui ne profitent de rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Pour cette cause encore je plaiderai avec vous, dit l’Eternel, et je plaiderai avec les enfants de vos enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Car passez par les Îles de Kittim, et voyez; envoyez en Kédar, et considérez bien, et regardez s’il y a eu rien de tel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Y a-t-il aucune nation qui ait changé de dieux, lesquels toutefois ne sont pas dieux? Mais mon peuple a changé sa gloire en ce qui ne profite de rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Cieux soyez étonnés de ceci; ayez- en de l’horreur, et soyez extrêmement asséchés, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Car mon peuple a fait deux maux; ils m’ont abandonné, moi qui suis la source des eaux vives, pour se creuser des citernes, des citernes crevassées qui ne peuvent point contenir d’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Israël est-il un esclave, ou un esclave né dans la maison? pourquoi donc a-t-il été mis au pillage?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Les lionceaux ont rugi, et ont jeté leur cri sur lui; et on a mis leur pays en désolation, ses villes ont été brûlées, de sorte qu’il n’y a personne qui y habite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Même les enfants de Noph, et de Taphnés te casseront le sommet de la tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Ne t’es-tu pas fait cela parce que tu as abandonné l’Eternel ton Dieu, dans le temps qu’il te menait par le chemin?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Et maintenant, qu’as-tu affaire d’aller en Egypte pour y boire de l’eau de Sihor? et qu’as-tu affaire d’aller en Assyrie, pour y boire de l’eau du fleuve?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Ta malice te châtiera, et tes débauches te réprimanderont, afin que tu saches et que tu voies que c’est une chose mauvaise et amère, que tu aies abandonné l’Eternel ton Dieu, et que tu ne sois point rempli de ma frayeur, dit le Seigneur l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Parce que depuis longtemps j’ai brisé ton joug, et rompu tes liens, tu as dit: je ne serai plus dans la servitude; c’est pourquoi tu as erré en te prostituant sur toute haute colline, et sous tout arbre vert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Or je t’avais moi-même plantée comme une vigne exquise, de laquelle tout le plant était franc; comment donc t’es-tu changée en sarments d’une vigne abâtardie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Quand tu te laverais avec du nitre, et que tu prendrais beaucoup de savon, ton iniquité demeurerait encore marquée devant moi, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Comment dis-tu: je ne me suis point souillée, je ne suis point allée après les Bahalins? Regarde ton train dans la vallée, reconnais ce que tu as fait, dromadaire légère, qui ne tiens point de route certaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Anesse sauvage, accoutumée au désert, humant le vent à son plaisir; et qui est-ce qui lui pourrait faire rebrousser sa course? nul de ceux qui la cherchent ne se lassera après elle, on la trouvera en son mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Retiens ton pied, que tu ne marches déchaussée, et ton gosier, que tu ne sois altérée. Mais tu as dit: c’en est fait. Non; car j’aime les étrangers, et j’irai après eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Comme le larron est confus, quand il est surpris, ainsi sont confus ceux de la maison d’Israël, eux, leurs Rois, les principaux d’entre eux, leurs Sacrificateurs, et leurs Prophètes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'Qui disent au bois: tu es mon père; et à la pierre: tu m’as engendré. Car ils m’ont tourné le dos, et non pas la face; puis ils disent dans le temps de leur calamité: lève-toi, et nous délivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Et où sont tes dieux que tu t’es faits? qu’ils se lèvent pour voir s’ils te délivreront au temps de la calamité; car, ô Juda! tu as eu autant de dieux que de villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Pourquoi plaideriez-vous contre moi? vous avez tous péché contre moi, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'J’ai frappé en vain vos enfants, ils n’ont point reçu d’instruction; votre épée a dévoré vos Prophètes, comme un lion qui ravage tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Ô race! considérez vous-mêmes la parole de l’Eternel, qui dit: Ai-je été un désert à Israël? ai-je été une terre toute ténébreuse? Pourquoi mon peuple a-t-il dit: nous sommes les maîtres; nous ne viendrons plus à toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'La vierge oubliera-t-elle son ornement? l’épouse ses atours? mais mon peuple m’a oublié durant des jours sans nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Pourquoi rends-tu ainsi affectée ta contenance pour chercher des amoureux, en sorte que tu as même enseigné tes manières de faire aux femmes de mauvaise vie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Même dans les pans de ta robe a été trouvé le sang des âmes des pauvres innocents, que tu n’avais point surpris en fracture, mais il y a été trouvé pour toutes ces choses-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Et tu dis: je suis innocente; quoi qu’il en soit, sa colère s’est détournée de moi. Voici, je m’en vais contester contre toi, sur ce que tu as dit: je n’ai point péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Pourquoi te donnes-tu tant de mouvement, changeant de chemin? tu seras aussi confuse d’Egypte, que tu as été confuse d’Assyrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Tu sortiras même d’ici, ayant tes mains sur ta tête, parce que l’Eternel a rejeté les fondements de ta confiance, et tu n’auras aucune prospérité par eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'On dit: si quelqu’un délaisse sa femme, et qu’elle se séparant de lui se joigne à un autre mari, le premier mari retournera-t-il encore vers elle? Le pays même n’en serait-il pas entièrement souillé? Or toi, tu t’es prostituée à plusieurs amoureux, toutefois retourne-toi vers moi, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Lève tes yeux vers les lieux élevés, et regarde quel est le lieu où tu ne te sois point abandonnée; tu te tenais par les chemins, comme un Arabe au désert; et tu as souillé le pays par tes débauches, et par ta malice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'C’est pourquoi les pluies ont été retenues, et il n’y a point eu de pluie de la dernière saison, et tu as un front de femme débauchée; tu n’as point voulu avoir de honte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Ne crieras-tu point désormais vers moi: mon Père, tu es le conducteur de ma jeunesse?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Tiendra-t-il sa colère à toujours, et me la gardera-t-il à jamais? Voici, tu as ainsi parlé, et tu as fait ces maux-là, autant que tu as pu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Aussi l’Eternel me dit aux jours du Roi Josias: n’as-tu point vu ce qu’Israël la revêche a fait? elle s’en est allée sur toute haute montagne, et sous tout arbre vert, et elle s’y est prostituée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Et quand elle a eu fait toutes ces choses, j’ai dit: retourne-toi vers moi; mais elle n’est point retournée; ce que sa soeur Juda la perfide a vu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Et j’ai vu que pour toutes les occasions par lesquelles Israël la revêche avait commis adultère, je l’ai renvoyée, et lui ai donné ses lettres de divorce; toutefois Juda sa soeur l’infidèle n’a point eu de crainte, mais s’en est allée, et elle aussi s’est prostituée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Et il est arrivé que par la facilité qu’elle a à s’abandonner elle a souillé le pays, et a commis adultère avec la pierre et le bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Et néanmoins pour tout ceci, Juda sa soeur la perfide n’est point retournée à moi de tout son coeur, mais avec mensonge, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'L’Eternel donc m’a dit: Israël la revêche s’est montrée plus juste que Juda la perfide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Va donc, et crie ces paroles-ci vers l’Aquilon; et dis: retourne-toi, Israël la revêche, dit l’Eternel; je ne ferai point tomber ma colère sur vous; car je suis miséricordieux, dit l’Eternel, et je ne vous la garderai point à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Mais reconnais ton iniquité; car tu as péché contre l’Eternel ton Dieu, et tu t’es prostituée aux étrangers sous tout arbre vert, et n’as point écouté ma voix, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Enfants revêches, convertissez-vous, dit l’Eternel; car j’ai droit de mari sur vous; et je vous prendrai l’un d’une ville, et deux d’une lignée, et je vous ferai entrer en Sion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Et je vous donnerai des pasteurs selon mon coeur, qui vous paîtront de science et d’intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Et il arrivera que quand vous serez multipliés et accrus sur la terre, en ces jours-là, dit l’Eternel, on ne dira plus: L’Arche de l’alliance de l’Eternel; elle ne leur montera plus au coeur, ils n’en feront point mention, ils ne la visiteront plus, et cela ne se fera plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'En ce temps-là on appellera Jérusalem, le Trône de l’Eternel, et toutes les nations s’assembleront vers elle, au Nom de l’Eternel, à Jérusalem, et elles ne marcheront plus après la dureté de leur coeur mauvais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'En ces jours-là la maison de Juda marchera avec la maison d’Israël, et ils viendront ensemble du pays d’Aquilon au pays que j’ai donné en héritage à vos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Car j’ai dit: comment te mettrai-je entre mes fils, et te donnerai-je la terre désirable, l’héritage de la noblesse des armées des nations? et j’ai dit: tu me crieras, mon Père, et tu ne te détourneras point de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Certainement comme une femme pèche contre son ami, ainsi avez-vous péché contre moi, maison d’Israël, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Une voix a été ouïe sur les lieux élevés, des pleurs de supplications des enfants d’Israël, parce qu’ils ont perverti leur voie, et qu’ils ont mis en oubli l’Eternel, leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Enfants rebelles, convertissez-vous, je remédierai à vos rébellions. Voici, nous venons vers toi; car tu es l’Eternel notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Certainement on s’attend en vain aux collines, et à la multitude des montagnes; mais c’est en l’Eternel notre Dieu qu’est la délivrance d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Car la honte a consumé dès notre jeunesse le travail de nos pères, leurs brebis et leurs boeufs, leurs fils et leurs filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Nous serons gisants dans notre honte, et notre ignominie nous couvrira, parce que nous avons péché contre l’Eternel notre Dieu, nous et nos pères, dès notre jeunesse, et jusqu’à aujourd’hui; et nous n’avons point obéi à la voix de l’Eternel notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Israël, si tu te retournes, dit l’Eternel, retourne-toi à moi; si tu ôtes tes abominations de devant moi, tu ne seras plus errant ça et là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'Alors tu jureras en vérité, et en jugement, et en justice, l’Eternel est vivant; et les nations se béniront en lui, et se glorifieront en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Car ainsi a dit l’Eternel à ceux de Juda et de Jérusalem: défrichez-vous les terres, et ne semez point sur les épines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Hommes de Juda, et vous habitants de Jérusalem, soyez circoncis à l’Eternel, et ôtez les prépuces de vos coeurs; de peur que ma fureur ne sorte comme un feu, et qu’elle ne s’embrase, sans qu’il y ait personne qui l’éteigne, à cause de la méchanceté de vos actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Faites savoir en Juda, et publiez dans Jérusalem, et dites: sonnez du cor par le pays, criez, et vous amassez; et dites: assemblez- vous, et nous entrerons dans les villes fortes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Dressez l’enseigne vers Sion, retirez-vous en troupe, et ne vous arrêtez point; car je m’en vais faire venir de l’Aquilon le mal et une grande calamité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Le lion est sorti de la caverne, et le destructeur des nations est parti; il est sorti de son lieu pour réduire ton pays en désolation, tes villes seront ruinées, tellement qu’il n’y aura personne qui y habite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'C’est pourquoi ceignez-vous de sacs, lamentez, et hurlez; car l’ardeur de la colère de l’Eternel n’est point détournée de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Et il arrivera en ce jour-là, dit l’Eternel, que le coeur du Roi, et le coeur des principaux sera épouvanté, et que les Sacrificateurs seront étonnés, et que les Prophètes seront tout confus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'C’est pourquoi j’ai dit: ha! ha! Seigneur Eternel! oui certainement tu as abusé ce peuple et Jérusalem, en disant: vous aurez la paix; et l’épée est venue jusqu’à l’âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'En ce temps-là on dira à ce peuple, et à Jérusalem: un vent éclaircissant les lieux élevés souffle au désert, dans le chemin de la fille de mon peuple, non pas pour vanner ni pour nettoyer:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Un vent plus véhément que ceux-là viendra à moi, et je leur ferai maintenant leur procès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Voici, il montera comme des nuées, et ses chariots seront semblables à un tourbillon, ses chevaux seront plus légers que des aigles; malheur à nous! car nous sommes détruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Jérusalem, nettoie ton coeur de ta malice, afin que tu sois délivrée; jusques à quand séjourneront au dedans de toi les pensées de ton injustice?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Car le cri apporte des nouvelles de Dan, et publie du mont d’Ephraïm le tourment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Faites l’entendre aux nations, voici, publiez contre Jérusalem, et dites: les assiégeants viennent d’un pays éloigné, et ils ont jeté leur cri contre les villes de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Ils se sont mis tout autour d’elle comme les gardes des champs, parce qu’elle m’a été rebelle, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Ta conduite et tes actions t’ont produit ces choses; telle a été ta malice; parce que ç’a été une chose amère; certainement elle te touchera jusques au coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Mon ventre! mon ventre! je suis dans la douleur; le dedans de mon coeur, mon coeur me bat, je ne me puis taire; car ô mon âme! tu as ouï le son du cor, et le retentissement bruyant de l’alarme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Une ruine est appelée par l’autre, car toute la terre est détruite; mes tentes ont été incontinent détruites, et mes pavillons en un moment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Jusques à quand verrai-je l’enseigne, et entendrai-je le son du cor?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Car mon peuple est insensé, ils ne m’ont point reconnu; ce sont des enfants insensés, et qui n’ont point d’entendement; ils sont habiles à faire le mal, mais ils ne savent pas faire le bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'J’ai regardé la terre, et voici, elle est sans forme et vide; et les cieux, et il n’y a point de clarté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'J’ai regardé les montagnes, et voici, elles branlent; et toutes les collines sont renversées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'J’ai regardé, et voici, il n’y a pas un seul homme, et tous les oiseaux des cieux s’en sont fuis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'J’ai regardé, et voici, Carmel est un désert, et toutes ses villes ont été ruinées par l’Eternel, et par l’ardeur de sa colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Car ainsi a dit l’Eternel: toute la terre ne sera que désolation; néanmoins je ne l’achèverai pas entièrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'C’est pourquoi la terre mènera deuil, et les cieux seront obscurcis au-dessus, parce que je l’ai prononcé; je l’ai pensé, je ne m’en repentirai point, et je ne le révoquerai point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Toute ville s’enfuit à cause du bruit des gens de cheval, et de ceux qui tirent de l’arc; ils sont entrés dans les bois épais, et sont montés sur les rochers; toute ville est abandonnée et personne n’y habite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Et quand tu auras été détruite, que feras-tu? quoique tu te vêtes de cramoisi, et que tu te pares d’ornements d’or, et que tu couvres ton visage de fard, tu t’embellis en vain; tes amoureux t’ont rebutée, ils chercheront ta vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Car j’ai ouï un cri comme celui d’une femme qui est en travail, et une angoisse comme celle d’une femme qui est en travail de son premier-né; c’est le cri de la fille de Sion; elle soupire, elle étend ses mains, en disant: Malheur maintenant à moi, car mon âme est défaillie à cause des meurtriers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Promenez-vous par les rues de Jérusalem, et regardez maintenant, et sachez, et vous enquérez par ses places, si vous y trouverez un homme de bien, s’il y a quelqu’un qui fasse ce qui est droit, et qui cherche la fidélité; et je pardonnerai à la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Que s’ils disent: l’Eternel est vivant; ils jurent en cela plus faussement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Eternel, tes yeux ne regardent-ils pas à la fidélité? Tu les as frappés, et ils n’en ont point senti de douleur; tu les as consumés, et ils ont refusé de recevoir instruction; ils ont endurci leurs faces plus qu’une roche, ils ont refusé de se convertir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Et j’ai dit: certainement ce ne sont que les plus abjects, qui se sont montrés fous, parce qu’ils ne connaissent point la voie de l’Eternel, le droit de leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Je m’en irai donc aux plus grands, et je leur parlerai; car ceux- là connaissent la voie de l’Eternel, le droit de leur Dieu; mais ceux-là mêmes ont aussi brisé le joug, et ont rompu les liens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'C’est pourquoi le lion de la forêt les a tués, le loup du soir les a ravagés, et le léopard est au guet contre leurs villes; quiconque en sortira sera déchiré, car leurs péchés sont multipliés, et leurs rébellions sont renforcées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Comment te pardonnerai-je en cela? tes fils m’ont abandonné, et ils jurent par ceux qui ne sont point dieux; je les ai rassasiés, et ils ont commis adultère et sont allés en foule dans la maison de la prostituée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Ils sont comme des chevaux bien repus, quand ils se lèvent le matin, chacun hennit après la femme de son prochain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Ne punirais-je point ces choses-là, dit l’Eternel? et mon âme ne se vengerait-elle pas d’une nation qui est telle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Montez sur ses murailles, et les rompez; mais ne les achevez pas entièrement; ôtez ses créneaux; car ils ne sont point à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Parce que la maison d’Israël et la maison de Juda se sont portées fort infidèlement contre moi, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Ils ont démenti l’Eternel, et ont dit: cela n’arrivera pas, et le mal ne viendra pas sur nous, nous ne verrons pas l’épée ni la famine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Et les Prophètes sont légers comme le vent, et la parole n’est point en eux; ainsi leur sera-t-il fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'C’est pourquoi, ainsi a dit l’Eternel, le Dieu des armées: parce que vous avez proféré cette parole-là, voici, je m’en vais mettre mes paroles en ta bouche pour y être comme un feu, et ce peuple sera comme le bois, et ce feu les consumera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Maison d’Israël, voici, je m’en vais faire venir contre vous une nation d’un pays éloigné, dit l’Eternel, une nation robuste, une nation ancienne, une nation de laquelle tu ne sauras point la Langue, et dont tu n’entendras point ce qu’elle dira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Son carquois est comme un sépulcre ouvert, et ils sont tous vaillants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Et elle mangera ta moisson et ton pain, que tes fils et tes filles doivent manger; elle mangera tes brebis, et tes boeufs; elle mangera les fruits de tes vignes, et de tes figuiers, et réduira à la pauvreté par l’épée tes villes fortes, sur lesquelles tu te confiais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Toutefois en ces jours-là, dit l’Eternel, je ne vous achèverai pas entièrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Et il arrivera que vous direz: pourquoi l’Eternel notre Dieu nous a-t-il fait toutes ces choses? et tu leur diras ainsi: comme vous m’avez abandonné, et avez servi les dieux de l’étranger dans votre pays, ainsi serez-vous asservis aux étrangers en un pays qui n’est point à vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Faites savoir ceci dans la maison de Jacob, et le publiez dans Juda, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Ecoutez maintenant ceci, peuple fou, et qui n’avez point d’intelligence, qui avez des yeux, et ne voyez point; et qui avez des oreilles, et n’entendez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Ne me craindrez-vous point, dit l’Eternel, et ne serez-vous point épouvantés devant ma face? moi qui ai mis le sable pour la borne de la mer, par une ordonnance perpétuelle, et qui ne passera point; ses vagues s’émeuvent, mais elles ne seront pas les plus fortes; et elles bruient, mais elles ne la passeront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Mais ce peuple-ci a un coeur rétif et rebelle; ils se sont reculés en arrière, et s’en sont allés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Et ils n’ont point dit en leur coeur: craignons maintenant l’Eternel notre Dieu, qui nous donne la pluie de la première et de la dernière saison, et qui nous garde les semaines ordonnées pour la moisson.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Vos iniquités ont détourné ces choses, et vos péchés ont empêché qu’il ne vous arrivât du bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Car il s’est trouvé dans mon peuple des méchants qui sont aux aguets, comme celui qui tend des pièges, ils posent une machine de perdition pour y prendre les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Comme la cage est remplie d’oiseaux, ainsi leurs maisons sont remplies de fraude, et par ce moyen ils se sont agrandis et enrichis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Ils sont engraissés et parés; même ils ont surpassé les actions des méchants; ils ne font justice à personne, non pas même à l’orphelin, et ils prospèrent, et ne font point droit aux pauvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Ne punirais-je point ces choses-là, dit l’Eternel? et mon âme ne se vengerait-elle pas d’une nation qui est telle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Il est arrivé en la terre une chose étonnante, et qui fait horreur:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'C’est que les Prophètes prophétisent le mensonge, et les Sacrificateurs dominent par leur moyen; et mon peuple a aimé cela. Que ferez-vous donc quand elle prendra fin?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Enfants de Benjamin, fuyez vous-en par troupes du milieu de Jérusalem, et sonnez du cor à Tékoah, et élevez un signal de feu à Bethkérem; car le mal et une grande ruine a paru de l’Aquilon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'J’avais rendu la fille de Sion semblable à une femme qui ne bouge point de la maison, et qui est délicate.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Les pasteurs avec leurs troupeaux viendront contre elles, ils planteront leurs tentes autour d’elle, chacun paîtra en son quartier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Préparez le combat contre elle, levez-vous, et montons en plein midi. Malheur à nous, car le jour décline, et les ombres du soir s’accroissent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Levez-vous, montons de nuit, et ruinons ses palais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Car ainsi a dit l’Eternel des armées: coupez des arbres, et dressez des terrasses contre Jérusalem; c’est la ville qui doit être visitée, elle n’est tout entière que rapine au dedans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Comme le puits fait bouillonner ses eaux, ainsi elle fait bouillonner sa malice; on n’entend en elle devant moi continuellement que violence et que dégât, avec des maladies et des plaies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Jérusalem, reçois instruction, de peur que mon affection ne se retire de toi, et que je ne fasse de toi un désert, et une terre inhabitable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Ainsi a dit l’Eternel des armées: on grappillera entièrement comme une vigne les restes d’Israël; remets ta main dans les paniers comme un vendangeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'A qui parlerai-je, et qui sommerai-je, afin qu’ils écoutent? voici, leur oreille est incirconcise, et ils ne peuvent entendre; voici, la parole de l’Eternel leur est en opprobre, ils n’y prennent point de plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'C’est pourquoi je suis plein de la fureur de l’Eternel, et je suis las de la retenir, de sorte que je la répandrai sur les enfants par la rue, et sur l’assemblée des jeunes gens, même le mari sera pris avec la femme, et l’homme âgé avec celui qui est rassasié de jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Et leurs maisons retourneront aux étrangers, les champs, et les femmes aussi; car j’étendrai ma main sur les habitants du pays, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Parce que depuis le plus petit d’entre eux jusques au plus grand, chacun s’adonne au gain déshonnête, tant le Prophète que le Sacrificateur, tous se portent faussement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'Et ils ont pansé la froissure de la fille de mon peuple à la légère, disant: paix, paix; et il n’y avait point de paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Ont-ils été confus de ce qu’ils ont commis des abominations? Ils n’en ont même eu aucune honte, et ils ne savent ce que c’est que de rougir; c’est pourquoi ils tomberont sur ceux qui seront tombés, ils tomberont au temps que je les visiterai, a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Ainsi a dit l’Eternel: tenez-vous sur les chemins, et regardez, et vous enquérez touchant les sentiers des siècles passés, quel est le bon chemin, et marchez-y, et vous trouverez le repos de vos âmes; et ils ont répondu: nous n’ y marcherons point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'J’avais aussi établi sur vous des sentinelles qui disent: soyez attentifs au son de la trompette; mais on a répondu: nous n’ y serons point attentifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Vous donc, nations, écoutez, et toi Assemblée, connais ce qui est entre eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Ecoute, terre: voici, je m’en vais faire venir un mal sur ce peuple, savoir le fruit de leurs pensées, parce qu’ils n’ont point été attentifs à mes paroles, et qu’ils ont rejeté ma Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Pourquoi m’offrir de l’encens venu de Seba, et le bon roseau aromatique du pays éloigné? vos holocaustes ne me plaisent point, et vos sacrifices ne me sont point agréables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'C’est pourquoi ainsi a dit l’Eternel: voici, je m’en vais mettre en ce peuple des achoppements, auxquels les pères et les enfants, le voisin et son compagnon heurteront ensemble, et ils périront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Ainsi a dit l’Eternel: voici, un peuple vient du pays de l’Aquilon, et une grande nation se réveillera du fond de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Ils prendront l’arc et l’étendard; ils seront cruels, et n’auront point de compassion; leur voix bruira comme la mer, et ils seront montés sur des chevaux, chacun d’eux est rangé en homme de guerre contre toi, fille de Sion!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'En aurons-nous ouï le bruit? nos mains en deviendront lâches; l’angoisse nous saisira, et un travail comme de celle qui enfante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Ne sortez point aux champs, et n’allez point par le chemin, car l’épée de l’ennemi et la frayeur est tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Fille de mon peuple, ceins-toi d’un sac, et te vautre dans la cendre; mène deuil comme sur un fils unique, et fais une lamentation très-amère, car le destructeur viendra subitement sur nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Je t’ai établi comme une place forte et une forteresse au milieu de mon peuple, afin que tu connaisses et sondes leur voie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Ils sont tous revêches, et plus que revêches, et ils vont médisant; ils sont comme de l’airain, et du fer; ils sont tous des gens qui se perdent l’un l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Le soufflet est brûlé, le plomb est consumé par le feu, le fondeur a fondu en vain, car les mauvais n’ont point été séparés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'On les appellera: Argent réprouvé; car l’Eternel les a réprouvés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'La parole fut adressée à Jérémie par l’Eternel, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Tiens-toi debout à la porte de la maison de l’Eternel, et y crie cette parole, et dis: vous tous hommes de Juda qui entrez par ces portes, pour vous prosterner devant l’Eternel, écoutez la parole de l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Ainsi a dit l’Eternel des armées, le Dieu d’Israël: corrigez votre vie et vos actions, et je vous ferai habiter en ce lieu-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Ne vous fiez point sur des paroles trompeuses, en disant: c’est ici le Temple de l’Eternel, le Temple de l’Eternel, le Temple de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Mais corrigez sérieusement votre conduite et vos actions, et appliquez-vous à faire droit à ceux qui plaident l’un contre l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'Et ne faites point de tort à l’étranger, ni à l’orphelin, ni à la veuve; et ne répandez point en ce lieu-ci le sang innocent, et ne marchez point après les dieux étrangers, à votre ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'Et je vous ferai habiter depuis un siècle jusqu’à l’autre siècle en ce lieu-ci, au pays que j’ai donné à vos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Voici, vous vous fiez sur des paroles trompeuses, sans aucun profit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Ne dérobez-vous pas? ne tuez-vous pas? ne commettez-vous pas adultère? ne jurez-vous pas faussement? ne faites-vous pas des encensements à Bahal? n’allez-vous pas après les dieux étrangers, que vous ne connaissez point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Toutefois vous venez, et vous vous présentez devant moi dans cette maison, sur laquelle mon Nom est réclamé, et vous dites: nous avons été délivrés pour faire toutes ces abominations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Cette maison, sur laquelle mon Nom est réclamé devant vos yeux, n’est-elle pas devenue une caverne de brigands? et voici, moi-même je l’ai vu, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Mais allez maintenant à mon lieu, qui était à Silo, là où j’avais placé mon Nom dès le commencement, et regardez ce que je lui ai fait, à cause de la malice de mon peuple d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Maintenant donc, parce que vous faites toutes ces choses, dit l’Eternel, et que je vous ai parlé, me levant dès le matin, et parlant, et que vous n’avez point écouté; je vous ai appelés, et vous n’avez point répondu:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'Je ferai à cette maison, sur laquelle mon Nom est réclamé, et sur laquelle vous vous fiez, et à ce lieu que je vous ai donné à vous et à vos pères, comme j’ai fait à Silo.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'Et je vous chasserai de devant ma face, comme j’ai chassé tous vos frères, avec toute la postérité d’Ephraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Toi donc ne prie point pour ce peuple, et ne jette point de cri, et ne fais point de requête pour eux, et n’intercède point envers moi; car je ne t’exaucerai point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Ne vois-tu pas ce qu’ils font dans les villes de Juda, et dans les rues de Jérusalem?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Les fils amassent le bois, et les pères allument le feu, et les femmes pétrissent la pâte pour faire des gâteaux à la Reine des cieux; et pour faire des aspersions aux dieux étrangers, afin de m’irriter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Ce qu’ils m’irritent est-il contre moi? dit l’Eternel. N’est-ce pas contre eux-mêmes, à la confusion de leurs faces?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: voici, ma colère et ma fureur vont fondre sur ce lieu-ci, sur les hommes et sur les bêtes, sur les arbres des champs, et sur le fruit de la terre, ma colère s’embrasera, et ne s’éteindra point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Ainsi a dit l’Eternel des armées, le Dieu d’Israël: ajoutez vos holocaustes à vos sacrifices, et mangez-en la chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Car je n’ai point parlé avec vos pères, et je ne leur ai point donné de commandement touchant les holocaustes et les sacrifices, au jour que je les fis sortir du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Mais voici ce que je leur ai commandé, disant: écoutez ma voix, et je serai votre Dieu, et vous serez mon peuple; et marchez dans toutes les voies que je vous ai ordonnées, afin que vous soyez heureux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Mais ils n’ont point écouté, et n’ont point incliné leur oreille; mais ils ont suivi d’autres conseils, et la dureté de leur coeur mauvais, ils se sont éloignés et ne sont point retournés jusques à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Depuis le jour que vos pères sont sortis du pays d’Egypte, jusqu’à aujourd’hui, je vous ai envoyé tous mes serviteurs Prophètes, me levant chaque jour dès le matin, et les envoyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Mais ils ne m’ont point écouté, et ils n’ont point incliné leur oreille, mais ils ont raidi leur cou; ils ont fait pis que leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Tu leur diras donc toutes ces paroles, mais ils ne t’écouteront point; et tu crieras après eux, mais ils ne te répondront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'C’est pourquoi tu leur diras: c’est ici la nation qui n’a point écouté la voix de l’Eternel son Dieu, et qui n’a point reçu d’instruction; la fidélité est périe, et elle a été retranchée de leur bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Tonds ta chevelure, ô Jérusalem! et la jette au loin, et prononce à haute voix ta complainte sur les lieux élevés; car l’Eternel a rejeté et abandonné la génération contre laquelle il est fort courroucé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Parce que les enfants de Juda ont fait ce qui me déplaît, dit l’Eternel, ils ont mis leurs abominations dans cette maison, sur laquelle mon Nom est invoqué, afin de la souiller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Et ils ont bâti les hauts lieux de Topheth, qui est dans la vallée du fils de Hinnom, pour brûler leurs fils et leurs filles au feu, ce que je n’ai pas commandé, et à quoi je n’ai jamais pensé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'C’est pourquoi voici, les jours viennent, dit l’Eternel, qu’elle ne sera plus appelée Topheth, ni la vallée du fils de Hinnom, mais la vallée de la tuerie, et on ensevelira les morts à Topheth, à cause qu’il n’y aura plus d’autre lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Et les corps morts de ce peuple seront pour viande aux oiseaux des cieux, et aux bêtes de la terre, sans qu’il y ait personne qui les effarouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Je ferai aussi cesser des villes de Juda, et des rues de Jérusalem, la voix de joie, et la voix d’allégresse, la voix de l’époux, et la voix de l’épouse, car le pays sera mis en désolation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'En ce temps-là, dit l’Eternel, on jettera les os des Rois de Juda, et les os de ses Princes, les os des Sacrificateurs, et les os des Prophètes, et les os des habitants de Jérusalem, hors de leurs sépulcres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'Et on les étendra devant le soleil, et devant la lune, et devant toute l’armée des cieux, qui sont des choses qu’ils ont aimées, qu’ils ont servies et après lesquelles ils ont marché; des choses qu’ils ont recherchées, et devant lesquelles ils se sont prosternés; ils ne seront point recueillis ni ensevelis, ils seront comme du fumier sur le dessus de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Et la mort sera plus désirable que la vie à tous ceux qui seront restés de cette méchante race, ceux, dis-je, qui seront restés dans tous les lieux où je les aurai chassés, dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Tu leur diras donc: ainsi a dit l’Eternel: si on tombe, ne se relèvera-t-on pas? et si on se détourne, ne retournera-t-on pas au chemin?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Pourquoi donc s’est égaré ce peuple, les habitants de Jérusalem, d’un égarement continuel? ils se sont adonnés opiniâtrement à la tromperie, et ont refusé de se convertir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Je me suis rendu attentif, et j’ai écouté, mais nul ne parle selon la justice, il n’y a personne qui se repente de son péché, disant: qu’ai-je fait? Ils sont tous retournés vers les objets qui les entraînent, comme le cheval qui se jette avec impétuosité parmi la bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Même la cigogne a connu dans les cieux ses saisons, la tourterelle et l’hirondelle, et la grue, ont pris garde au temps qu’elles doivent venir; mais mon peuple n’a point connu le droit de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Comment dites-vous: nous sommes les sages, et la Loi de l’Eternel est avec nous? voilà, certes on a agi faussement, et la plume des Scribes est une plume de fausseté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Les sages ont été confus, ils ont été épouvantés et pris, car ils ont rejeté la parole de l’Eternel? et en quoi seraient-ils sages?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'C’est pourquoi je donnerai leurs femmes à d’autres, et leurs champs à des gens qui les posséderont en héritage; car depuis le plus petit jusqu’au plus grand, chacun s’adonne au gain déshonnête, tant le Prophète que le Sacrificateur, tous agissent faussement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Et ils ont pansé la plaie de la fille de mon peuple à la légère, en disant: paix, paix; et il n’y avait point de paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Ont-ils été confus de ce qu’ils ont commis abomination? Ils n’en ont eu même aucune honte, et ils ne savent ce que c’est que de rougir; c’est pourquoi ils tomberont sur ceux qui seront tombés; ils tomberont au temps que je les visiterai, a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'En les ramassant je les consumerai entièrement dit l’Eternel; il n’y a pas une grappe dans les vignes; et il n’y a pas une figue au figuier, la feuille est flétrie, et ce que je leur ai donné sera transporté avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Pour quelle raison nous arrêtons-nous? Assemblez-vous, et entrons dans les villes fortes, et nous serons là en repos, car l’Eternel notre Dieu nous a fait taire, et nous a donné à boire de l’eau de fiel, parce que nous avons péché contre l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'On attend la paix, et il n’y a rien de bon; on attend le temps de la guérison, et voici le trouble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Le ronflement de ses chevaux a été ouï de Dan, et tout le pays a été ému du bruit des hennissements de ses puissants chevaux; ils sont venus et ont dévoré le pays et tout ce qui y était, la ville et ceux qui habitaient en elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Qui plus est, voici, je m’en vais envoyer contre vous des serpents, des basilics, contre lesquels il n’y a point d’enchantement, et ils vous mordront, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'J’ai voulu prendre des forces pour soutenir la douleur, mais mon coeur est languissant au dedans de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Voici la voix du cri de la fille de mon peuple qui crie d’un pays éloigné; l’Eternel n’est-il point en Sion? son Roi n’est-il point au milieu d’elle? Mais pourquoi m’ont-ils irrité par leurs images taillées, par les vanités de l’étranger?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'La moisson est passée; l’Eté est fini, et nous n’avons point été délivrés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Je suis amèrement affligé à cause de la calamité de la fille de mon peuple, j’en suis en deuil, j’en suis tout désolé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'N’y a-t-il point de baume en Galaad? n’y a-t-il point là de médecin? pourquoi donc la plaie de la fille de mon peuple n’est-elle pas consolidée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Plût à Dieu que ma tête fût comme un réservoir d’eau, et que mes yeux fussent une vive fontaine de larmes, et je pleurerais jour et nuit les blessés à mort de la fille de mon peuple!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Plût à Dieu que j’eusse au désert une cabane de voyageurs, j’abandonnerais mon peuple, et me retirerais d’avec eux; car ils sont tous des adultères, et une troupe de perfides.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Ils ont tendu leur langue, qui leur a été comme leur arc pour décocher le mensonge, et ils se sont renforcés dans la terre contre la fidélité, parce qu’ils sont allés de malice en malice, et ne m’ont point reconnu, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Gardez-vous chacun de son intime ami, et ne vous fiez à aucun frère; car tout frère fait métier de supplanter, et tout intime ami va médisant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Et chacun se moque de son intime ami, et on ne parle point en vérité; ils ont instruit leur langue à dire le mensonge, ils se tourmentent extrêmement pour mal faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Ta demeure est au milieu de la tromperie; ils refusent à cause de la tromperie de me reconnaître, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'C’est pourquoi ainsi a dit l’Eternel des armées: voici, je m’en vais les fondre, et je les éprouverai; car comment en agirais-je autrement à l’égard de la fille de mon peuple?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Leur langue est un trait décoché, elle profère des fraudes; chacun a la paix dans sa bouche avec son intime ami, mais dans son intérieur il lui dresse des embûches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Ne punirais-je point en eux ces choses-là? dit l’Eternel. Mon âme ne se vengerait-elle pas d’une nation qui est telle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'J’élèverai ma voix avec larmes, et je prononcerai à haute voix une lamentation à cause des montagnes, et une complainte à cause des cabanes du désert, parce qu’elles ont été brûlées, de sorte qu’il n’y a personne qui y passe, et qu’on n’y entend plus le cri des troupeaux; les oiseaux des cieux et le bétail s’en sont fuis, ils s’en sont allés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Et je réduirai Jérusalem en monceaux de ruines, elle sera une retraite de dragons, et je détruirai les villes de Juda, tellement qu’il n’y aura personne qui y habite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Qui est l’homme sage qui entende ceci, et qui est celui à qui la bouche de l’Eternel ait parlé, qui en fasse le rapport, et qui dise pourquoi le pays est-il désolé, et brûlé comme un désert, sans que personne y passe?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'L’Eternel donc a dit: parce qu’ils ont abandonné ma Loi, laquelle je leur avais proposée, et qu’ils n’ont point écouté ma voix, et n’ont point marché selon elle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'Mais parce qu’ils ont marché après la dureté de leur coeur, et après les Bahalins; ce que leurs pères leur ont enseigné;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'C’est pourquoi, ainsi a dit l’Eternel des armées, le Dieu d’Israël: voici, je m’en vais donner à manger à ce peuple-ci de l’absinthe, et je leur donnerai à boire de l’eau de fiel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Je les disperserai parmi les nations que ni eux ni leurs pères n’ont point connues; et j’enverrai après eux l’épée, jusqu’à ce que je les aie consumés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Ainsi a dit l’Eternel des armées: recherchez, et appelez des pleureuses, afin qu’elles viennent, et mandez les femmes sages, et qu’elles viennent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Qu’elles se hâtent, et qu’elles prononcent à haute voix une lamentation sur nous, et que nos yeux se fondent en pleurs et que nos paupières fassent ruisseler des larmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Car une voix de lamentation a été ouïe de Sion, disant: comment avons-nous été détruits? Nous sommes fort confus, parce que nous avons abandonné le pays, parce que nos tentes nous ont jetés dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'C’est pourquoi, vous femmes, écoutez la parole de l’Eternel, et que votre oreille reçoive la parole de sa bouche; et enseignez vos filles à lamenter, et chacune sa compagne à faire des complaintes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Car la mort est montée par nos fenêtres, elle est entrée dans nos palais, pour exterminer les enfants, tellement qu’il n’y en a plus dans les rues; et les jeunes gens, tellement qu’il n’y en a plus par les places.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Dis: ainsi a dit l’Eternel: même les corps morts des hommes seront étendus comme du fumier sur le dessus des champs, et comme une poignée d’épis après les moissonneurs, lesquels personne ne recueille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Ainsi a dit l’Eternel: que le sage ne se glorifie point en sa sagesse; que le fort ne se glorifie point en sa force, et que le riche ne se glorifie point en ses richesses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Mais que celui qui se glorifie, se glorifie en ce qu’il a de l’intelligence, et qu’il me connaît; car je suis l’Eternel, qui fais miséricorde, et jugement, et justice sur la terre; parce que je prends plaisir en ces choses-là, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Voici, les jours viennent, dit l’Eternel, que je punirai tout circoncis ayant encore le prépuce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'L’Egypte, et Juda, et Edom, et les enfants de Hammon, et Moab, et tous ceux qui sont aux bouts des coins, habitant dans le désert; car toutes les nations ont le prépuce, et toute la maison d’Israël a le prépuce du coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Maison d’Israël, écoutez la parole que l’Eternel a prononcée sur vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Ainsi a dit l’Eternel: n’apprenez point les façons de faire des nations, et ne soyez point épouvantés des signes des cieux, sous ombre que les nations en sont épouvantées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Car les statuts des peuples ne sont que vanité, parce qu’on coupe du bois de la forêt pour le mettre en oeuvre avec la hache;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Puis on l’embellit avec de l’argent et de l’or, et on le fait tenir avec des clous et à coups de marteau, afin qu’il ne remue point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Ils sont façonnés tout droits comme un palmier, et ils ne parlent point; on les porte par nécessité, à cause qu’ils ne peuvent pas marcher; ne les craignez point, car ils ne font point de mal, et aussi il n’est pas en leur pouvoir de faire du bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Il n’y a point de dieu semblable à toi, ô Eternel! tu es grand, et ton Nom est grand en force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Qui ne te craindrait, Roi des nations, car cela t’est dû? parce qu’entre tous les plus sages des nations, et dans tous leurs Royaumes il n’y en a point de semblable à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'Et ils sont tous ensemble abrutis, et devenus fous; le bois ne leur apprend que des vanités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'L’argent qui est étendu en plaques, est apporté de Tarsis, et l’or est apporté d’Uphaz, pour être mis en oeuvre par l’ouvrier, et par les mains du fondeur; et la pourpre et l’écarlate est leur vêtement; toutes ces choses sont l’ouvrage de gens adroits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Mais l’Eternel est le Dieu de vérité, c’est le Dieu vivant, et le Roi éternel; la terre sera ébranlée par sa colère, et les nations ne pourront soutenir son indignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Vous leur direz ainsi: les dieux qui n’ont point fait les cieux et la terre périront de la terre, et de dessous les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Mais l’Eternel est celui qui a fait la terre par sa vertu, qui a formé le monde habitable par sa sagesse, et qui a étendu les cieux par son intelligence;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Sitôt qu’il a fait éclater sa voix il y a un grand bruit d’eaux dans les cieux; après qu’il a fait monter du bout de la terre les vapeurs, il fait briller l’éclair avant la pluie, et il tire le vent hors de ses trésors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Tout homme se montre abruti dans sa science; tout fondeur est rendu honteux par les images taillées; car ce qu’ils font est une fausseté, et il n’y a point de respiration en elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Elles ne sont que vanité, et un ouvrage propre à abuser; elles périront au temps de leur visitation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'La portion de Jacob n’est point comme ces choses-là; car c’est celui qui a tout formé, et Israël est le lot de son héritage; son nom est l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Toi qui habites en un lieu fort, retire du pays ta marchandise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Car ainsi a dit l’Eternel: voici, je m’en vais à cette fois jeter au loin, comme avec une fronde, les habitants du pays, et je les mettrai à l’étroit, tellement qu’ils le trouveront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Malheur à moi, diront-ils, à cause de ma plaie, ma plaie est douloureuse. Mais moi j’ai dit: quoi qu’il en soit, c’est une maladie qu’il faut que je souffre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Ma tente est gâtée; tous mes cordages sont rompus; mes enfants sont sortis d’auprès de moi, et ne sont plus; il n’y a plus personne qui dresse ma tente, et qui élève mes pavillons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Car les pasteurs sont abrutis, et n’ont point recherché l’Eternel; c’est pourquoi ils ne se sont point conduits sagement, et tous leurs pâturages ont été dissipés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Voici, un bruit de certaines nouvelles est venu, avec une grande émotion de devers le pays d’Aquilon, pour ravager les villes de Juda, et en faire une retraite de dragons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Eternel, je connais que la voie de l’homme ne dépend pas de lui, et qu’il n’est pas au pouvoir de l’homme qui marche, de diriger ses pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Ô Eternel! châtie-moi, mais que ce soit par mesure, et non en ta colère, de peur que tu ne me réduises à rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Répands ta fureur sur les nations qui ne te connaissent point, et sur les familles qui n’invoquent point ton Nom; car ils ont dévoré Jacob, ils l’ont, dis-je, dévoré et consumé, et ils ont mis en désolation son agréable demeure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'La parole fut adressée à Jérémie par l’Éternel, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Ecoutez les paroles de cette alliance, et prononcez -les aux hommes de Juda, et aux habitants de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Tu leur diras donc: ainsi a dit l’Eternel le Dieu d’Israël: maudit soit l’homme qui n’écoutera point les paroles de cette alliance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'Laquelle j’ai ordonnée à vos pères, le jour que je les ai retirés du pays d’Egypte, du fourneau de fer, en disant: Ecoutez ma voix, et faites toutes les choses que je vous ai commandées, et vous serez mon peuple, et je serai votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'Afin que je ratifie le serment que j’ai fait à vos pères, de leur donner un pays découlant de lait et de miel, comme il paraît aujourd’hui. Et je répondis, et dis: Ainsi soit-il! ô Eternel!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Puis l’Eternel me dit: crie toutes ces paroles par les villes de Juda, et par les rues de Jérusalem, en disant: écoutez les paroles de cette alliance, et les faites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Car j’ai sommé expressément vos pères au jour que je les ai fait monter du pays d’Egypte jusqu’à aujourd’hui, me levant dès le matin, et les sommant, en disant: écoutez ma voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Mais ils ne l’ont pas écoutée, et n’y ont point incliné leur oreille, mais ils ont marché chacun suivant la dureté de leur coeur mauvais; c’est pourquoi j’ai fait venir sur eux toutes les paroles de cette alliance, laquelle je leur avais commandé de garder, et qu’ils n’ont point gardée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Et l’Eternel me dit: il y a une conjuration parmi les hommes de Juda, et parmi les habitants de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Ils sont retournés aux iniquités de leurs ancêtres, qui ont refusé d’écouter mes paroles, et qui sont allés après d’autres dieux pour les servir; la maison d’Israël et la maison de Juda ont enfreint mon alliance, que j’avais traitée avec leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'C’est pourquoi ainsi a dit l’Eternel: voici, je m’en vais faire venir sur eux un mal duquel ils ne pourront sortir; ils crieront vers moi, mais je ne les exaucerai point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Et les villes de Juda et les habitants de Jérusalem s’en iront, et crieront vers les dieux auxquels ils font leurs parfums; mais ces dieux-là ne les délivreront nullement au temps de leur affliction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Car, ô Juda! tu as eu autant de dieux que de villes; et toi, Jérusalem, tu as dressé autant d’autels aux choses honteuses, que tu as de rues, des autels, dis-je, pour faire des parfums à Bahal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Toi donc ne fais point de requête pour ce peuple, et ne jette point de cri, ni ne fais point de prière pour eux; car je ne les exaucerai point au temps qu’ils crieront vers moi dans leur calamité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Qu’est-ce que mon bien-aimé a à faire dans ma maison, que tant de gens se servent d’elle pour y faire leurs complots? la chair sainte est transportée loin de toi, et encore quand tu fais mal, tu t’égayes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'L’Eternel avait appelé ton nom, Olivier vert et beau, à cause du beau fruit; mais au son d’un grand bruit il y a allumé le feu, et ses branches ont été rompues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Car l’Eternel des armées, qui t’a plantée, a prononcé du mal contre toi, à cause de la malice de la maison d’Israël, et de la maison de Juda, qu’ils ont commise contre eux-mêmes, jusqu’à m’irriter en faisant des parfums à Bahal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Et l’Eternel me l’a donné à connaître, et je l’ai connu; et tu m’as fait voir leurs actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Mais moi, comme un agneau, ou comme un boeuf qui est mené pour être égorgé, je n’ai point su qu’ils eussent fait contre moi quelque machination, en disant: détruisons l’arbre avec son fruit, et l’exterminons de la terre des vivants, et qu’on ne se souvienne plus de son nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Mais toi, Eternel des armées, qui juges justement, et qui sondes les reins et le coeur, fais que je voie la vengeance que tu feras d’eux; car je t’ai découvert ma cause.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'C’est pourquoi ainsi a dit l’Eternel, touchant les gens de Hanathoth, qui cherchent ta vie, et qui disent: ne prophétise plus au Nom de l’Eternel, et tu ne mourras point par nos mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'C’est pourquoi donc ainsi a dit l’Eternel des armées: voici, je vais les punir; les jeunes gens mourront par l’épée, leurs fils et leurs filles mourront par la famine;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'Et il ne restera rien d’eux, car je ferai venir le mal sur les gens de Hanathoth, en l’année de leur visitation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Eternel, quand je contesterai avec toi, tu seras trouvé juste; mais toutefois j’entrerai en contestation avec toi. Pourquoi la voie des méchants a-t-elle prospéré; et pourquoi tous les perfides vivent-ils en paix?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Tu les as plantés, et ils ont pris racine; ils s’avancent, et fructifient. Tu es près de leur bouche, mais tu es loin de leurs reins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Mais, ô Eternel! tu m’as connu, tu m’as vu, et tu as sondé quel est mon coeur envers toi. Traîne-les comme des brebis qu’on mène pour être égorgées, et prépare-les pour le jour de la tuerie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Jusques à quand la terre mènera-t-elle deuil, et l’herbe de tous les champs séchera-t-elle à cause de la malice des habitants qui sont en la terre? Les bêtes et les oiseaux ont été consumés par la disette, parce que ces méchants ont dit: on ne verra point notre dernière fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Si tu as couru avec les gens de pied, et qu’ils t’aient lassé, comment te mêleras-tu parmi les chevaux? et si tu t’es cru en sûreté dans une terre de paix, que feras-tu lorsque le Jourdain sera enflé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Certainement tes frères mêmes, et la maison de ton père, ceux-là mêmes ont agi perfidement contre toi, eux-mêmes ont crié après toi à plein gosier; ne les crois point, quoiqu’ils te parlent aimablement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'J’ai abandonné ma maison, j’ai quitté mon héritage, ce que mon âme aimait le plus je l’ai livré en la main de ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Mon héritage m’a été comme un lion dans la forêt; il a jeté son cri contre moi, c’est pourquoi je l’ai en haine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Mon héritage me sera-t-il donc comme l’oiseau peint? les oiseaux ne sont-ils pas autour de lui? Venez, assemblez-vous, vous tous les animaux des champs, venez pour le dévorer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Plusieurs pasteurs ont gâté ma vigne, ils ont foulé mon partage, ils ont réduit mon partage désirable en un désert affreux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'On l’a ravagé, et lui, tout désolé, a été en deuil devant moi; toute la terre a été ravagée, parce qu’il n’y a personne qui y fasse attention.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Les destructeurs sont venus sur toutes les hautes places qui sont au désert, car l’épée de l’Eternel dévore depuis un bout du pays jusqu’à l’autre; il n’y a point de paix pour aucune chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Ils ont semé du froment, et ils moissonneront des épines; ils se sont peinés, et ils n’y profiteront rien; vous serez confus en vos revenus par l’ardeur de la colère de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Ainsi a dit l’Eternel contre tous mes mauvais voisins, qui mettent la main sur l’héritage que j’ai fait hériter à mon peuple d’Israël: voici, je vais les arracher de leur pays, et j’arracherai la maison de Juda du milieu d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Mais il arrivera qu’après les avoir arrachés, j’aurai encore compassion d’eux, et je les ferai retourner chacun à son héritage, et chacun en son quartier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Et il arrivera que s’ils apprennent bien les voies de mon peuple, pour jurer en mon Nom, l’Eternel est vivant, ainsi qu’ils ont enseigné à mon peuple à jurer par Bahal, ils seront édifiés parmi mon peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Mais s’ils n’écoutent point, j’arracherai entièrement une telle nation, et la ferai périr, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Ainsi m’a dit l’Eternel: Va, et achète-toi une ceinture de lin, et mets-la sur tes reins, et ne la mets point dans l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'J’achetai donc une ceinture selon la parole de l’Eternel, et la mis sur mes reins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Et la parole de l’Eternel me fut adressée pour la seconde fois, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Prends la ceinture que tu as achetée, et qui est sur tes reins, et te lève, et t’en va vers l’Euphrate, et la cache là dans le trou d’un rocher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Je m’en allai donc, et la cachai dans l’Euphrate, comme l’Eternel m’avait commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Et il arriva que plusieurs jours après l’Eternel me dit: lève-toi, et t’en va vers l’Euphrate, et reprends de là la ceinture que je t’avais commandé d’y cacher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Et je m’en allai vers l’Euphrate, je creusai; et je repris la ceinture du lieu où je l’avais cachée, et voici, la ceinture était pourrie, et n’était plus bonne à rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Alors la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Ainsi a dit l’Eternel: je ferai ainsi pourrir l’orgueil de Juda, et le grand orgueil de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'L’orgueil de ce peuple très méchant, qui refusent d’écouter mes paroles, et qui marchent selon la dureté de leur coeur, et vont après d’autres dieux pour les servir, et pour se prosterner devant eux, tellement qu’il sera comme cette ceinture, qui n’est bonne à aucune chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Car comme une ceinture est jointe sur les reins d’un homme, je m’étais attaché toute la maison d’Israël, et toute la maison de Juda, dit l’Eternel, afin qu’ils fussent mon peuple, ma renommée, ma louange, et ma gloire; mais ils n’ont point écouté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Tu leur diras donc cette parole-ci: ainsi a dit l’Eternel, le Dieu d’Israël: tout vaisseau sera rempli de vin; et ils te diront: ne savons-nous pas bien que tout vaisseau sera rempli de vin?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Mais tu leur diras: ainsi a dit l’Eternel: voici, je m’en vais remplir d’ivresse tous les habitants de ce pays, et les Rois qui sont assis sur le trône de David pour l’amour de lui, et les Sacrificateurs, et les Prophètes, et tous les habitants de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Et je les briserai l’un contre l’autre, les pères et les enfants ensemble, dit l’Eternel, je n’en aurai point de compassion, je ne les épargnerai point, et je n’en aurai point de pitié pour ne les détruire point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Ecoutez et prêtez l’oreille, ne vous élevez point, car l’Eternel a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Donnez gloire à l’Eternel votre Dieu, avant qu’il fasse venir les ténèbres, et avant que vos pieds bronchent sur les montagnes dans lesquelles on ne voit pas clair; vous attendrez la lumière, et il la changera en une ombre de mort, et la réduira en obscurité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Que si vous n’écoutez ceci, mon âme pleurera en secret à cause de votre orgueil, et mon oeil versera des larmes en abondance, même il se fondra en larmes, parce que le troupeau de l’Eternel aura été emmené prisonnier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Dis au Roi et à la Régente: humiliez-vous, et vous asseyez sur la cendre, car votre couronne magnifique tombera de dessus vos têtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Les villes du Midi sont fermées, et il n’y a personne qui les ouvre; tout Juda est transporté en captivité, il est universellement transporté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Levez vos yeux, et voyez ceux qui viennent de l’Aquilon. Où est le parc qui t’a été donné, et ton magnifique troupeau?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Que diras-tu quand il te punira? car tu les as enseignés contre toi, pour être supérieurs sur ta tête; les douleurs ne te saisiront- elles point, comme elles saisissent la femme qui enfante?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Que si tu dis en ton coeur: pourquoi me sont arrivées ces choses? C’est pour la grandeur de ton iniquité que tes habits ont été retroussés, et que tes talons ont été serrés de près.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Le More changerait-il sa peau, et le léopard ses taches? pourriez-vous aussi faire quelque bien, vous qui n’êtes appris qu’à mal faire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'C’est pourquoi je les disperserai comme du chaume, qui est emporté ça et là par le vent du désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'C’est ici ton lot, et la portion que je t’ai mesurée dit l’Eternel; parce que tu m’as oublié, et que tu as mis ta confiance au mensonge,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'A cause de cela j’ai retroussé tes habits sur ton visage, et ton ignominie paraîtra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Tes adultères, et tes hennissements, l’énormité de ta prostitution est sur les collines, par les champs, j’ai vu tes abominations; malheur à toi, Jérusalem, ne seras-tu point nettoyée? jusques à quand cela durera-t-il?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'La parole de l’Eternel, qui fut adressée à Jérémie, sur ce que les pluies avaient été retenues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'La Judée a mené deuil, et ses portes sont en un pitoyable état. Ils sont tous en deuil gisant par terre, et le cri de Jérusalem est monté au ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Et les personnes distinguées ont envoyé à l’eau les moindres d’entre eux; ils sont venus aux lieux creux, ils n’y ont point trouvé d’eau, et ils s’en sont retournés leurs vaisseaux vides; ils ont été rendus honteux et confus, et ils ont couvert leur tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Parce que la terre s’est crevassée à cause qu’il n’y a point eu de pluie au pays; les laboureurs ont été rendus honteux, et ils ont couvert leur tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Même la biche a fait son faon au champ et l’a abandonné, parce qu’il n’y a point d’herbe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Et les ânes sauvages se sont tenus sur les lieux élevés, ils ont attiré l’air comme des dragons; leurs yeux sont consumés, parce qu’il n’y a point d’herbe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Eternel, si nos iniquités rendent témoignage contre nous, agis à cause de ton Nom, car nos rébellions sont multipliées; c’est contre toi que nous avons péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Toi qui es l’attente d’Israël, et son libérateur au temps de la détresse, pourquoi serais-tu en la terre comme un étranger, et comme un voyageur qui se détourne pour passer la nuit?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Pourquoi serais-tu comme un homme étonné, et comme un homme fort qui ne peut délivrer? Or tu es au milieu de nous, ô Eternel! et ton Nom est réclamé sur nous; ne nous abandonne point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'L’Eternel a dit ainsi à ce peuple, parce qu’ils ont aimé à aller ainsi çà et là, et qu’ils n’ont point retenu leurs pieds, l’Eternel n’a point pris plaisir en eux, il se souviendra maintenant de leurs iniquités, et il punira leurs péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Puis l’Eternel me dit: ne fais point de requête en faveur de ce peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Quand ils jeûneront, je n’exaucerai point leur cri, et quand ils offriront des holocaustes et des oblations, je n’y prendrai point de plaisir; mais je les consumerai par l’épée, et par la famine, et par la mortalité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Et je dis: ah! ah! Seigneur Eternel! voici, les Prophètes leur disent: vous ne verrez point l’épée, et vous n’aurez point de famine, mais je vous donnerai une paix assurée en ce lieu-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Et l’Eternel me dit: ce n’est que mensonge ce que ces prophètes prophétisent en mon Nom; je ne les ai point envoyés, je ne leur ai point donné de charge, et je ne leur ai point parlé; ils vous prophétisent des visions de mensonge, des divinations de néant, et des tromperies de leur coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'C’est pourquoi, ainsi a dit l’Eternel touchant les prophètes qui prophétisent en mon Nom, et que je n’ai point envoyés, et qui disent: l’épée ni la famine ne sera point en ce pays; ces prophètes-là seront consumés par l’épée et par la famine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Et le peuple auquel ils ont prophétisé sera jeté par les rues de Jérusalem à cause de la famine et de l’épée; et il n’y aura personne qui les ensevelisse, tant eux que leurs femmes, leurs fils et leurs filles, et je répandrai sur eux leur méchanceté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Tu leur diras donc cette parole-ci: que mes yeux se fondent en larmes nuit et jour, et qu’ils ne cessent point; car la vierge, fille de mon peuple, a été fort maltraitée, la plaie en est fort douloureuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Si je sors aux champs, voici les gens morts par l’épée; et si j’entre en la ville, voici les langueurs de la faim; même le Prophète et le Sacrificateur ont couru par le pays, et ils ne savent où ils en sont.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Aurais-tu entièrement rejeté Juda? et ton âme aurait-elle Sion en dédain? Pourquoi nous as-tu frappés tellement qu’il n’y a point de guérison? on attend la paix, et il n’y a rien de bon; et le temps de la guérison, et voici le trouble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Eternel, nous reconnaissons notre méchanceté, et l’iniquité de nos pères; car nous avons péché contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Ne nous rejette point à cause de ton Nom, et n’expose point à opprobre le trône de ta gloire; souviens-toi de ton alliance avec nous, et ne la romps point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Parmi les vanités des nations y en a-t-il qui fassent pleuvoir, et les cieux donnent-ils la menue pluie? N’est-ce pas toi qui le fais, ô Eternel notre Dieu? C’est pourquoi nous nous attendrons à toi; car c’est toi qui as fait toutes ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Et l’Eternel me dit: quand Moïse et Samuel se tiendraient devant moi, je n’aurais pourtant point d’affection pour ce peuple; chasse- les de devant ma face, et qu’ils sortent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Que s’ils te disent: où sortirons-nous? Tu leur répondras: ainsi a dit l’Eternel: ceux qui sont destinés à la mort iront à la mort; et ceux qui sont destinés à l’épée iront à l’épée; et ceux qui sont destinés à la famine, iront à la famine; et ceux qui sont destinés à la captivité iront en captivité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'J’établirai aussi sur eux quatre espèces de punitions, dit l’Eternel, l’épée pour tuer, et les chiens pour traîner, et les oiseaux des cieux, et les bêtes de la terre pour dévorer et pour détruire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Et je les livrerai à être agités par tous les Royaumes de la terre, à cause de Manassé fils d’Ezéchias, Roi de Juda, pour les choses qu’il a faites dans Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Car qui serait ému de compassion envers toi, Jérusalem? ou qui viendrait se condouloir avec toi? ou qui se détournerait pour s’enquérir de ta prospérité?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Tu m’as abandonné, dit l’Eternel, et tu t’en es allée en arrière; c’est pourquoi j’étendrai ma main sur toi, et je te détruirai; je suis las de me repentir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Je les vannerai avec un van aux portes du pays; j’ai désolé et fait périr mon peuple, et ils ne se sont point détournés de leur voie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'J’ai multiplié ses veuves plus que le sable de la mer, je leur ai amené sur la mère de leur jeunesse un destructeur en plein midi, j’ai fait tomber subitement sur elle l’ennemi et les frayeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Celle qui en avait enfanté sept est devenue languissante, elle a rendu l’esprit, son soleil lui est couché pendant qu’il était encore jour, elle a été rendue honteuse et confuse; et je livrerai son reste à l’épée devant leurs ennemis, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Malheur à moi, ô ma mère! de ce que tu m’as enfanté pour être un homme de débat, et un homme de querelle à tout le pays; je ne me suis obligé à personne, et personne ne s’est obligé à moi, et néanmoins chacun me maudit et me méprise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Alors l’Eternel dit: ceux qui seront restés de toi ne viendront-ils pas à bien? et ne ferai-je pas que l’ennemi viendra au devant de toi au temps de la calamité, et au temps de la détresse?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Le fer usera-t-il le fer de l’Aquilon, et l’acier?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Je livrerai au pillage, sans en faire le prix, tes richesses et tes trésors; et cela à cause de tous tes péchés, et même par toutes tes contrées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Et je ferai passer tes ennemis par un pays que tu ne connais point, car le feu a été allumé en ma colère, il sera allumé sur vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Eternel, tu le connais, souviens-toi de moi, et me visite, et me venge de ceux qui me persécutent; ne m’enlève point, quand tu auras longtemps différé ta colère; connais que j’ai souffert opprobre pour l’amour de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Tes paroles se sont-elles trouvées? je les ai aussitôt mangées; et ta parole m’a été en joie, et elle a été l’allégresse de mon coeur; car ton Nom est réclamé sur moi, ô Eternel! Dieu des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Je ne me suis point assis au conventicule des railleurs, et je ne m’y suis point réjoui; mais je me suis tenu assis tout seul, à cause de ta main, parce que tu m’as rempli d’indignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Pourquoi ma douleur est-elle rendue continuelle, et ma plaie est-elle sans espérance? elle a refusé d’être guérie; me serais-tu bien comme une chose qui trompe? comme des eaux qui ne durent pas?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'C’est pourquoi ainsi a dit l’Eternel: si tu te retournes, je te ramènerai, et tu te tiendras devant moi; et si tu sépares la chose précieuse de la méprisable, tu seras comme ma bouche; qu’ils se retournent vers toi, mais toi ne retourne pas vers eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Et je te ferai être à l’égard de ce peuple une muraille d’acier bien forte; ils combattront contre toi, mais ils n’auront point le dessus contre toi, car je suis avec toi pour te garantir, et pour te délivrer, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Et je te délivrerai de la main des malins, et te rachèterai de la main des terribles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Puis la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Tu ne prendras point de femme, et tu n’auras point de fils ni de filles en ce lieu-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Car ainsi a dit l’Eternel touchant les fils et les filles qui naîtront en ce lieu-ci, et touchant leurs mères qui les auront enfantés, et touchant les pères qui les auront engendrés en ce pays;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Ils mourront de maladies très douloureuses; ils ne seront point lamentés, ni ensevelis, mais ils seront sur le dessus de la terre comme du fumier, et ils seront consumés par l’épée et par la famine, et leurs corps morts seront pour viande aux oiseaux des cieux, et aux bêtes de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Même, ainsi a dit l’Eternel: n’entre point en aucune maison de deuil, et ne va point lamenter, ni te condouloir pour eux; car j’ai retiré de ce peuple, dit l’Eternel, ma paix, ma miséricorde, et mes compassions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Et les grands et les petits mourront en ce pays; ils ne seront point ensevelis, et on ne les pleurera point, et personne ne se fera aucune incision, ni ne se rasera pour eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'On ne leur distribuera point de pain dans le deuil pour consoler quelqu’un d’eux au sujet d’un mort; et on ne leur donnera point à boire de la coupe de consolation pour leur père ou pour leur mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Aussi tu n’entreras point en aucune maison de festin afin de t’asseoir avec eux pour manger, ou pour boire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Car ainsi a dit l’Eternel des armées, le Dieu d’Israël: voici, je m’en vais faire cesser de ce lieu-ci devant vos yeux et en vos jours, la voix de joie et la voix d’allégresse, la voix de l’époux et la voix de l’épouse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Et il arrivera que quand tu auras prononcé à ce peuple toutes ces paroles-là, ils te diront: pourquoi l’Eternel a-t-il prononcé tout ce grand mal contre nous? et quelle est notre iniquité, et quel est notre péché que nous avons commis contre l’Eternel notre Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Et tu leur diras: parce que vos pères m’ont abandonné, dit l’Eternel, et sont allés après d’autres dieux, et les ont servis, et se sont prosternés devant eux, et m’ont abandonné, et n’ont point gardé ma Loi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Et que vous avez encore fait pis que vos pères; car voici, chacun de vous marche après la dureté de son coeur mauvais, afin de ne m’écouter point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'A cause de cela je vous transporterai de ce pays en un pays que vous n’avez point connu, ni vous ni vos pères; et là vous serez asservis jour et nuit à d’autres dieux, parce que je ne vous aurai point fait de grâce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Néanmoins voici, les jours viennent, dit l’Eternel, qu’on ne dira plus: l’Eternel est vivant qui a fait remonter les enfants d’Israël du pays d’Egypte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'Mais, l’Eternel est vivant qui a fait remonter les enfants d’Israël du pays de l’Aquilon, et de tous les pays auxquels il les avait chassés; après que je les aurai ramenés dans leur pays, lequel j’ai donné à leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Voici, je m’en vais mander à plusieurs Pêcheurs, dit l’Eternel, et ils les pêcheront; et ensuite je m’en vais mander à plusieurs Veneurs, qui les chasseront par toutes les montagnes, et par tous les coteaux, et par tous les trous des rochers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Car mes yeux sont sur tout leur train, lequel n’est point caché devant moi; ni leur iniquité n’est point celée devant mes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Mais premièrement je leur rendrai le double de leur iniquité et de leur péché, à cause qu’ils ont souillé mon pays par leurs victimes abominables, et qu’ils ont rempli mon héritage de leurs abominations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Eternel, qui es ma force et ma puissance, et mon refuge au jour de la détresse, les nations viendront à toi des bouts de la terre, et diront: certes nos pères ont hérité le mensonge et la vanité, et les choses auxquelles il n’y a point de profit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'L’homme se fera-t-il bien des dieux? qui toutefois ne sont point dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'C’est pourquoi, voici, je vais leur faire connaître à cette fois, je vais leur faire connaître ma main et ma force, et ils sauront que mon Nom est l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Le péché de Juda est écrit avec un burin d’acier de fer, et avec une pointe de diamant; il est gravé sur la table de leur coeur, et aux cornes de leurs autels.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'De sorte que leurs fils se souviendront de leurs autels, et de leurs bocages, auprès des arbres verts sur les hautes collines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Montagnard, je livrerai par les champs tes richesses et tous tes trésors au pillage; tes hauts lieux sont pleins de péché dans toutes tes contrées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Et toi, et ceux qui sont avec toi, vous laisserez vacant l’héritage que je t’avais donné, et je ferai que tu seras asservi à tes ennemis, dans un pays que tu ne connais point, parce que vous avez allumé le feu en ma colère; et il brûlera à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Ainsi a dit l’Eternel: maudit soit l’homme qui se confie en l’homme, et qui fait de la chair son bras, et dont le coeur se retire de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Car il sera comme la bruyère en une lande, et il ne s’apercevra point quand le bien sera venu; mais il demeurera au désert en des lieux secs, en une terre salée et inhabitable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Béni soit l’homme qui se confie en l’Eternel, et duquel l’Eternel est la confiance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Car il sera comme un arbre planté près des eaux, et qui étend ses racines le long d’une eau courante; quand la chaleur viendra, il ne s’en apercevra point; et sa feuille sera verte, il ne sera point en peine en l’année de la sécheresse, et ne cessera point de porter du fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Le coeur est rusé, et désespérément malin par dessus toutes choses; qui le connaîtra?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Je suis l’Eternel, qui sonde le coeur, et qui éprouve les reins; même pour rendre à chacun selon sa voie, et selon le fruit de ses actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Celui qui acquiert des richesses, sans observer la justice, est une perdrix qui couve ce qu’elle n’a point pondu; il les laissera au milieu de ses jours, et à la fin il sera trouvé insensé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Le lieu de notre Sanctuaire est un trône de gloire, un lieu haut élevé dès le commencement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Eternel, qui es l’attente d’Israël, tous ceux qui t’abandonnent seront honteux; ceux qui se détournent de moi, seront écrits en la terre, parce qu’ils ont délaissé la source des eaux vives, l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Eternel, guéris-moi, et je serai guéri; sauve-moi, et je serai sauvé; car tu es ma louange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Voici, ceux-ci me disent: où est la parole de l’Eternel? qu’elle vienne présentement!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Mais je ne me suis point avancé plus qu’un pasteur après toi, et je n’ai point désiré le jour de l’extrême affliction, tu le sais; et ce qui est sorti de mes lèvres a été devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Ne me sois point en effroi, tu es ma retraite au jour du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Que ceux qui me persécutent soient honteux, mais que je ne sois point honteux; qu’ils soient épouvantés, mais que je ne sois point épouvanté; amène sur eux le jour du mal, et les accable d’une double plaie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Ainsi m’a dit l’Eternel: va, et tiens-toi debout à la porte des enfants du peuple, par laquelle les Rois de Juda entrent, et par laquelle ils sortent; et à toutes les portes de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'Et leur dis: écoutez la parole de l’Eternel, Rois de Juda, et vous tous hommes de Juda, et vous tous habitants de Jérusalem qui entrez par ces portes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Ainsi a dit l’Eternel: prenez garde à vos âmes, et ne portez aucun fardeau le jour du Sabbat, et ne les faites point passer par les portes de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Et ne tirez point hors de vos maisons aucun fardeau le jour du Sabbat, et ne faites aucune oeuvre, mais sanctifiez le jour du Sabbat, comme j’ai commandé à vos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Mais ils n’ont point écouté, et n’ont point incliné leur oreille, mais ils ont raidi leur cou, pour n’écouter point, et pour ne recevoir point d’instruction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Il arrivera donc si vous m’écoutez attentivement, dit l’Eternel pour ne faire passer aucun fardeau par les portes de cette ville le jour du Sabbat, et si vous sanctifiez le jour du Sabbat, tellement que vous ne fassiez aucune oeuvre en ce jour-là;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'Que les Rois et les principaux, ceux qui sont assis sur le trône de David, montés sur des chariots et sur des chevaux, eux et les principaux d’entre eux, les hommes de Juda, et les habitants de Jérusalem, entreront par les portes de cette ville; et cette ville sera habitée à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'On viendra aussi des villes de Juda, et des environs de Jérusalem et du pays de Benjamin, et de la campagne, et des montagnes, et de devers le Midi, et on apportera des holocaustes, des sacrifices, des oblations et de l’encens; on apportera aussi des sacrifices d’action de grâces en la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Mais si vous ne m’écoutez point pour sanctifier le jour du Sabbat, et pour ne porter aucun fardeau, et n’en faire entrer aucun par les portes de Jérusalem le jour du Sabbat, je mettrai le feu à ses portes, il consumera les palais de Jérusalem, et ne sera point éteint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Cette parole fut adressée de par l’Eternel à Jérémie, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Lève-toi, et descends dans la maison d’un potier, et là je te ferai entendre mes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Je descendis donc dans la maison d’un potier, et voici, il faisait son ouvrage, assis sur sa selle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Et le vase qu’il faisait de l’argile qui était en sa main, fut gâté, et il en fit encore un autre vase, comme il lui sembla bon de le faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Alors la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Maison d’Israël, ne vous pourrai-je pas faire comme a fait ce potier; dit l’Eternel? voici, comme l’argile est dans la main d’un potier, ainsi êtes-vous dans ma main, maison d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'En un instant je parlerai contre une nation, et contre un Royaume, pour arracher, pour démolir, et pour détruire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Mais si cette nation contre laquelle j’aurai parlé se détourne du mal qu’elle aura fait, je me repentirai aussi du mal que j’avais pensé de lui faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Et si en un instant je parle d’une nation et d’un Royaume, pour l’édifier et pour le planter;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'Et que cette nation fasse ce qui me déplaît, en sorte qu’elle n’écoute point ma voix, je me repentirai aussi du bien que j’avais dit que je lui ferais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Or donc parle maintenant aux hommes de Juda, et aux habitants de Jérusalem, en disant: ainsi a dit l’Eternel: voici, je projette du mal contre vous, et je forme un dessein contre vous; abandonnez donc maintenant chacun sa mauvaise voie, et changez votre voie, et vos actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Et ils répondirent: il n’y a plus d’espérance; c’est pourquoi nous suivrons nos pensées, et chacun de nous fera selon la dureté de son coeur mauvais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'C’est pourquoi ainsi a dit l’Eternel: Demandez maintenant aux nations qui a entendu de telles choses? la vierge d’Israël a fait une chose très-énorme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'N’abandonnera-t-on pas la neige du Liban pour la roche du champ? et ne laissera-t-on pas les eaux qui ne sont point naturelles, et qui sont froides, encore qu’elles coulent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Mais mon peuple m’a oublié, et il a fait des parfums à ce qui n’est que vanité, et qui les a fait broncher dans leurs voies, pour les faire retirer des sentiers anciens, afin de marcher dans les sentiers d’un chemin qui n’est point battu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'Pour faire venir sur leur pays une désolation et un opprobre perpétuel; tellement que quiconque passera par là en sera étonné, et branlera la tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Je les disperserai devant l’ennemi, comme par le vent d’Orient; je leur tournerai le dos, au jour de leur calamité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Et ils ont dit: venez, et faisons quelques machinations contre Jérémie; car la Loi ne se perdra pas chez le Sacrificateur, ni le conseil chez le Sage, ni la parole chez le Prophète; venez, et frappons-le de la langue, et ne soyons point attentifs à aucun de ses discours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Eternel, entends-moi, et écoute la voix de ceux qui plaident contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Le mal sera-t-il rendu pour le bien? car ils ont creusé une fosse pour mon âme. Souviens-toi que je me suis présenté devant toi afin de parler pour leur bien, et afin de détourner d’eux ta grande colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'C’est pourquoi livre leurs enfants à la famine, et fais couler leur sang à coups d’épée; que leurs femmes soient privées d’enfants, et veuves, et que leurs maris soient mis à mort; et leurs jeunes gens tués avec l’épée dans la bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Que le cri soit ouï de leurs maisons, quand tu auras fait venir subitement des troupes contre eux; parce qu’ils ont creusé une fosse pour me prendre, et qu’ils ont tendu des filets à mes pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Or tu sais, ô Eternel! que tout leur conseil est contre moi pour me mettre à mort; ne sois point apaisé à l’égard de leur iniquité, et n’efface point leur péché de devant ta face, mais qu’on les fasse tomber en ta présence; agis contre eux au temps de ta colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Ainsi a dit l’Eternel: va, et achète une bouteille de terre d’un potier, et prends des anciens du peuple, et des anciens des Sacrificateurs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'Et sors à la vallée du fils de Hinnom, qui est auprès de l’entrée de la porte Orientale, et crie là les paroles que je te dirai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'Dis donc: Rois de Juda, et vous habitants de Jérusalem, écoutez la parole de l’Eternel: ainsi a dit l’Eternel des armées, le Dieu d’Israël: voici, je m’en vais faire venir sur ce lieu-ci un mal, tel que quiconque l’entendra, les oreilles lui en tinteront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Parce qu’ils m’ont abandonné, et qu’ils ont profané ce lieu, et y ont fait des encensements à d’autres dieux, que ni eux, ni leurs pères, ni les Rois de Juda n’ont point connus, et parce qu’ils ont rempli ce lieu du sang des innocents;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'Et qu’ils ont bâti des hauts lieux de Bahal, afin de brûler au feu leurs fils pour en faire des holocaustes à Bahal, ce que je n’ai point commandé, et dont je n’ai point parlé, et à quoi je n’ai jamais pensé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'A cause de cela voici, les jours viennent, dit l’Eternel, que ce lieu-ci ne sera plus appelé Topheth, ni la vallée du fils de Hinnom, mais la vallée de la tuerie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Et j’anéantirai le conseil de Juda et de Jérusalem en ce lieu-ci, et je les ferai tomber par l’épée en la présence de leurs ennemis, et en la main de ceux qui cherchent leur vie; et je donnerai leurs corps morts à manger aux oiseaux des cieux et aux bêtes de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Je détruirai cette ville, et je la couvrirai d’opprobre; quiconque passera près d’elle sera étonné, et lui insultera à cause de toutes ses plaies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Et je leur ferai manger la chair de leurs fils, et la chair de leurs filles; et chacun mangera la chair de son compagnon durant le siège, et dans l’extrémité où les réduiront leurs ennemis, et ceux qui cherchent leur vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Puis tu casseras la bouteille en présence de ceux qui seront allés avec toi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'Et tu leur diras: ainsi a dit l’Eternel des armées: je briserai ce peuple et cette ville, de même qu’on brise un vaisseau de potier, qui ne peut être soudé, et ils seront ensevelis à Topheth, parce qu’il n’y aura plus d’autre lieu pour les ensevelir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Je ferai ainsi à ce lieu-ci, dit l’Eternel, et à ses habitants; tellement que je réduirai cette ville au même état que Topheth;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Et les maisons de Jérusalem, et les maisons des Rois de Juda seront souillées, comme le lieu de Topheth, à cause de toutes les maisons sur les toits desquelles ils ont fait des parfums à toute l’armée des cieux, et des aspersions à d’autres dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Puis Jérémie s’en vint de Topheth là où l’Eternel l’avait envoyé pour prophétiser, et il se tint debout au parvis de la maison de l’Eternel, et dit à tout le peuple:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Ainsi a dit l’Eternel des armées, le Dieu d’Israël: voici, je m’en vais faire venir sur cette ville, et sur toutes ses villes, tout le mal que j’ai prononcé contre elle, parce qu’ils ont raidi leur cou, pour ne point écouter mes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Alors Pashur, fils d’Immer Sacrificateur, qui était prévôt et conducteur dans la maison de l’Eternel, entendit Jérémie qui prophétisait ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Et Pashur frappa le Prophète Jérémie, et le mit dans la prison qui est à la haute porte de Benjamin, en la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Et il arriva dès le lendemain, que Pashur tira Jérémie hors de la prison, et Jérémie lui dit: l’Eternel n’a pas appelé ton Nom Pashur, mais Magor-missabib.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Car ainsi a dit l’Eternel: voici, je vais te livrer à la frayeur, toi, et tous tes amis, qui tomberont par l’épée de leurs ennemis, et tes yeux le verront; je livrerai tous ceux de Juda entre les mains du Roi de Babylone, qui les transportera à Babylone, et les frappera avec l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Et je livrerai toutes les richesses de cette ville, et tout son travail, et tout ce qu’elle a de précieux, je livrerai, dis-je, tous les trésors des Rois de Juda, entre les mains de leurs ennemis, qui les pilleront, les enlèveront, et les emporteront à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Et toi, Pashur, et tous les habitants de ta maison, vous irez en captivité, tu iras à Babylone, tu y mourras, et y seras enseveli, toi et tous tes amis, auxquels tu as prophétisé le mensonge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Ô Eternel! tu m’as sollicité, et j’ai été attiré; tu as été plus fort que moi, et tu as eu le dessus; je suis un objet de moquerie tout le jour, chacun se moque de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Car depuis que je parle je n’ai fait que jeter des cris, que crier violence et pillerie, parce que la parole de l’Eternel m’est tournée en opprobre et en moquerie tout le jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'C’est pourquoi j’ai dit: je ne ferai plus mention de lui, et je ne parlerai plus en son Nom; mais il y a eu dans mon coeur comme un feu ardent, renfermé dans mes os; je suis las de le porter, et je n’en puis plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Car j’ai ouï les insultes de plusieurs, la frayeur m’a saisi de tous côtés. Rapportez, disent-ils, et nous le rapporterons. Tous ceux qui ont paix avec moi épient si je bronche, et disent: peut- être qu’il sera abusé; alors nous aurons le dessus, et nous nous vengerons de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Mais l’Eternel est avec moi comme un homme fort et terrible; c’est pourquoi ceux qui me persécutent seront renversés, ils n’auront point le dessus, ils seront honteux; car ils n’ont pas été prudents; ce sera une confusion éternelle, qui ne s’oubliera jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'C’est pourquoi, Eternel des armées, qui sondes les justes, qui vois les reins et le coeur, fais que je voie la vengeance que tu en feras; car je t’ai découvert ma cause.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Chantez à l’Eternel, louez l’Eternel; car il a délivré l’âme des pauvres de la main des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Maudit soit le jour auquel je naquis; que le jour auquel ma mère m’enfanta ne soit point béni.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Maudit soit l’homme qui apporta de bonnes nouvelles à mon père, en lui disant: un enfant mâle t’est né; et qui le réjouit si bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Que cet homme-là soit comme les villes que l’Eternel a renversées sans s’en repentir, qu’il entende le cri au matin, et le retentissement bruyant au temps du Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'Que ne m’a-t-on fait mourir dans le sein de ma mère? pourquoi ma mère ne m’a-t-elle été mon sépulcre, et pourquoi son sein n’a-t-il conçu sans jamais enfanter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Pourquoi suis-je né pour ne voir que peine et qu’ennui, et afin que mes jours fussent consumés avec honte?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'La parole qui fut adressée à Jérémie de par l’Eternel, lorsque le Roi Sédécias envoya vers lui Pashur fils de Malkija, et Sophonie fils de Mahaséja Sacrificateur, pour lui dire:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Enquiers-toi maintenant de l’Eternel pour nous; car Nébucadnetsar Roi de Babylone combat contre nous; peut-être que l’Eternel agira pour nous selon toutes ses merveilles, et le fera retirer de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Et Jérémie leur dit: vous direz ainsi à Sédécias:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Ainsi a dit l’Eternel, le Dieu d’Israël: voici, je m’en vais faire retourner de dehors la muraille les instruments de guerre qui sont en vos mains, avec lesquels vous combattez contre le Roi de Babylone et contre les Caldéens qui vous assiègent, et je les ramasserai au milieu de cette ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Et je combattrai contre vous avec une main étendue, et avec un bras puissant, avec colère, avec ardeur, et avec une grande indignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'Et je frapperai les habitants de cette ville, les hommes, et les bêtes; et ils mourront d’une grande mortalité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Et après cela, dit l’Eternel, je livrerai Sédécias Roi de Juda, et ses serviteurs, et le peuple, et ceux qui seront demeurés de reste en cette ville de la mortalité, de l’épée, et de la famine, en la main de Nébucadnetsar Roi de Babylone, et en la main de leurs ennemis, et en la main de ceux qui cherchent leur vie; et il les frappera au tranchant de l’épée, il ne les épargnera point, il n’en aura point de compassion, il n’en aura point de pitié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Tu diras aussi à ce peuple: ainsi a dit l’Eternel: voici, je mets devant vous le chemin de la vie, et le chemin de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Quiconque se tiendra dans cette ville mourra par l’épée, ou par la famine, ou par la mortalité, mais celui qui en sortira, et se rendra aux Caldéens qui vous assiègent, vivra, et sa vie lui sera pour butin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Car j’ai dressé ma face en mal et non en bien contre cette ville, dit l’Eternel, elle sera livrée en la main du Roi de Babylone, et il la brûlera par le feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Et quant à la maison du Roi de Juda, écoutez la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Maison de David, ainsi a dit l’Eternel: faites justice dès le matin, et délivrez celui qui aura été pillé, d’entre les mains de celui qui lui fait tort, de peur que ma fureur ne sorte comme un feu, et qu’elle ne s’embrase, et qu’il n’y ait personne qui l’éteigne, à cause de la malice de vos actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Voici, j’en veux à toi, qui habites dans la vallée, et qui es le rocher du plat pays, dit l’Eternel; à vous qui dites: qui est-ce qui descendra contre nous, et qui entrera dans nos demeures?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Et je vous punirai selon le fruit de vos actions, dit l’Eternel; et j’allumerai le feu dans sa forêt, lequel consumera tout ce qui est à l’entour d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Ainsi a dit l’Eternel: descends en la maison du Roi de Juda, et y prononce cette parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'Tu diras donc: écoute la parole de l’Eternel, ô Roi de Juda! qui es assis sur le trône de David, toi et tes serviteurs, et ton peuple, qui entrez par ces portes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Ainsi a dit l’Eternel: faites jugement et justice, et délivrez celui qui aura été pillé, d’entre les mains de celui qui lui fait tort; ne foulez point l’orphelin, ni l’étranger, ni la veuve; et n’usez d’aucune violence, et ne répandez point le sang innocent dans ce lieu-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Car si vous mettez exactement en effet cette parole, alors les Rois qui sont assis en la place de David sur son trône, montés sur des chariots et sur des chevaux, entreront par les portes de cette maison, eux et leurs serviteurs, et leur peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Mais si vous n’écoutez point ces paroles, j’ai juré par moi-même, dit l’Eternel, que cette maison sera réduite en désolation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Car ainsi a dit l’Eternel touchant la maison du Roi de Juda: tu m’es un Galaad, et le sommet du Liban, mais si je ne te réduis en désert, et en villes qui ne sont point habitées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Je préparerai contre toi des destructeurs chacun avec ses armes, qui couperont tes cèdres exquis, et les jetteront au feu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Et plusieurs nations passeront près de cette ville, et chacun dira à son compagnon: pourquoi l’Eternel a-t-il fait ainsi à cette grande ville?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Et on dira: c’est parce qu’ils ont abandonné l’alliance de l’Eternel leur Dieu, et qu’ils se sont prosternés devant d’autres dieux, et les ont servis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Ne pleurez point celui qui est mort, et n’en faites point de lamentation; mais pleurez amèrement celui qui s’en va, car il ne retournera plus, et ne verra plus le pays de sa naissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Car ainsi a dit l’Eternel touchant Sallum fils de Josias, Roi de Juda, qui a régné en la place de Josias son père, et qui est sorti de ce lieu, iI n’y retournera plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'Mais il mourra au lieu auquel on l’a transporté, et ne verra plus ce pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Malheur à celui qui bâtit sa maison par l’injustice, et ses étages sans droiture, qui se sert pour rien de son prochain, et ne lui donne point le salaire de son travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'Qui dit: je me bâtirai une grande maison et des étages bien aérés, et qui se perce des fenêtrages; elle est lambrissée de cèdre, et peinte de vermillon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Régneras-tu, que tu te mêles parmi les cèdres? Ton père n’a-t-il pas mangé et bu? quand il a fait jugement et justice, alors il a prospéré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Il a jugé la cause de l’affligé, et du pauvre, et alors il a prospéré; cela n’était-il pas me connaître? dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Mais tes yeux et ton coeur ne sont adonnés qu’à ton gain déshonnête, qu’à répandre le sang innocent, qu’à faire tort, et qu’à opprimer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'C’est pourquoi, ainsi a dit l’Eternel touchant Jéhojakim fils de Josias Roi de Juda: on ne le plaindra point, en disant: hélas mon frère! et hélas ma soeur! on ne le plaindra point, en disant: hélas Sire! et, hélas sa magnificence!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Il sera enseveli de la sépulture d’un âne, étant traîné, et jeté au delà des portes de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Monte au Liban, et crie, jette ta voix en Basan, et crie par les passages, à cause que tous tes amoureux ont été mis en pièces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Je t’ai parlé durant ta grande prospérité, mais tu as dit: je n’écouterai point; tel est ton train dès ta jeunesse, que tu n’as point écouté ma voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Le vent remplira tous tes pasteurs, et tes amoureux iront en captivité; certainement tu seras alors honteuse et confuse à cause de toute ta malice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Tu te tiens au Liban, et tu fais ton nid dans les cèdres, ô que tu seras un objet de compassion quand les tranchées te viendront, et ta douleur, comme de la femme qui est en travail d’enfant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Je suis vivant, dit l’Eternel, que quand Chonja, fils de Jéhojakim, Roi de Juda, serait un cachet en ma main droite, je l’arracherai de là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'Et je le livrerai en la main de ceux qui cherchent la vie, et en la main de ceux de la présence desquels tu as peur, et en la main de Nébucadnetsar Roi de Babylone, et en la main des Caldéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Et je te jetterai, toi et ta mère qui t’a enfanté, en un autre pays, auquel vous n’êtes point nés; et vous y mourrez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Et quant au pays qu’ils désirent pour y retourner, ils n’y retourneront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Ce personnage Chonja serait-ce une idole méprisée et rompue? serait-ce un vaisseau qui n’a rien d’aimable? pourquoi ont-ils été jetés là, lui et sa postérité, jetés, dis-je, en un pays qu’ils ne connaissent point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Ô terre! terre! terre! écoute la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Ainsi a dit l’Eternel: écrivez que ce personnage-là est privé d’enfant, que c’est un homme qui ne prospérera point pendant ses jours, et que même il n’y aura point d’homme de sa postérité qui prospère, et qui soit assis sur le trône de David, ni qui domine plus en Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Malheur aux pasteurs qui détruisent et dissipent le troupeau de ma pâture, dit l’Eternel!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'C’est pourquoi ainsi a dit l’Eternel, le Dieu d’Israël, touchant les pasteurs qui paissent mon peuple: vous avez dissipé mes brebis, et vous les avez chassées, et ne les avez point visitées; voici, je m’en vais visiter sur vous la malice de vos actions, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Mais je rassemblerai le reste de mes brebis de tous les pays auxquels je les aurai chassées, et les ferai retourner à leurs parcs, et elles fructifieront et multiplieront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'J’établirai aussi sur elles des pasteurs qui les paîtront, et elles n’auront plus de peur, et ne s’épouvanteront point, et il n’en manquera aucune, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Voici, les jours viennent, dit l’Eternel, que je ferai lever à David un Germe juste, qui régnera comme Roi; il prospérera, et exercera le jugement et la justice sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'En ses jours Juda sera sauvé, et Israël habitera en assurance; et c’est ici le nom, duquel on l’appellera: l’Eternel notre justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'C’est pourquoi voici, les jours viennent, dit l’Eternel, qu’on ne dira plus: l’Eternel est vivant, qui a fait remonter les enfants d’Israël du pays d’Egypte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'Mais, l’Eternel est vivant, qui a fait remonter, et qui a ramené la postérité de la maison d’Israël, du pays de devers l’Aquilon, et de tous les pays auxquels je les avais chassés, et ils habiteront en leur terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'A cause des Prophètes mon coeur est brisé au dedans de moi, tous mes os en tremblent, je suis comme un homme ivre, et comme un homme que le vin a surmonté, à cause de l’Eternel, et à cause des paroles de sa sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Car le pays est rempli d’hommes adultères, et le pays mène deuil à cause des exécrations: les pâturages du désert sont devenus tous secs, l’oppression de ces gens est mauvaise, et leur force n’est pas en faveur de l’équité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Car le Prophète et le Sacrificateur se contrefont; j’ai même trouvé dans ma maison leur méchanceté, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'C’est pourquoi leur voie sera comme des lieux glissants dans les ténèbres, ils y seront poussés, et y tomberont; car je ferai venir du mal sur eux, en l’année de leur visitation, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Or j’avais bien vu des choses mal convenables dans les Prophètes de Samarie, car ils prophétisaient de par Bahal, et faisaient égarer mon peuple Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Mais j’ai vu des choses énormes dans les Prophètes de Jérusalem; car ils commettent des adultères, et ils marchent dans le mensonge; ils ont donné main forte aux hommes injustes et pas un ne s’est détourné de sa malice; ils me sont tous comme Sodome, et les habitants de la ville, comme Gomorrhe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'C’est pourquoi, ainsi a dit l’Eternel des armées touchant ces Prophètes: voici, je m’en vais leur faire manger de l’absinthe, et leur faire boire de l’eau de fiel; parce que la profanation s’est répandue des Prophètes de Jérusalem par tout le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Ainsi a dit l’Eternel des armées: n’écoutez point les paroles des Prophètes qui vous prophétisent; ils vous font devenir vains, ils prononcent la vision de leur coeur, et ils ne la tiennent pas de la bouche de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Ils ne cessent de dire à ceux qui me méprisent: l’Eternel a dit: vous aurez la paix; et ils disent à tous ceux qui marchent dans la dureté de leur coeur: il ne vous arrivera point de mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Car qui s’est trouvé au conseil secret de l’Eternel? et qui a aperçu et ouï sa parole? qui a été attentif à sa parole, et l’a ouïe?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Voici la tempête de l’Eternel, sa fureur va se montrer, et le tourbillon prêt à fondre tombera sur la tête des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'La colère de l’Eternel ne sera point détournée qu’il n’ait exécuté et mis en effet les pensées de son coeur; vous aurez une claire intelligence de ceci sur la fin des jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Je n’ai point envoyé ces Prophètes-là, et ils ont couru; je ne leur ai point parlé, et ils ont prophétisé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'S’ils s’étaient trouvés dans mon conseil secret, ils auraient aussi fait entendre mes paroles à mon peuple, et ils les auraient détournés de leur mauvais train, et de la malice de leurs actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Suis-je un Dieu de près, dit l’Eternel, et ne suis-je point aussi un Dieu de loin?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Quelqu’un se pourra-t-il cacher dans quelque retraite, que je ne le voie point? dit l’Eternel. Ne remplis-je pas, moi, les cieux et la terre? dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'J’ai ouï ce que les Prophètes ont dit, prophétisant le mensonge en mon Nom, et disant: j’ai eu un songe, j’ai eu un songe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Jusques à quand ceci sera-t-il au coeur des Prophètes qui prophétisent le mensonge, et qui prophétisent la tromperie de leur coeur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Qui pensent comment ils feront oublier mon Nom à mon peuple, par les songes qu’un chacun d’eux récite à son compagnon, comme leurs pères ont oublié mon Nom pour Bahal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Que le Prophète par devers lequel est le songe, récite le songe; et que celui par devers lequel est ma parole, profère ma parole en vérité. Quelle convenance y a-t-il de la paille avec le froment? dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Ma parole n’est-elle pas comme un feu, dit l’Eternel; et comme un marteau qui brise la pierre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'C’est pourquoi voici, j’en veux aux Prophètes, dit l’Eternel, qui dérobent mes paroles, chacun de son prochain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Voici, j’en veux aux Prophètes, dit l’Eternel, qui accommodent leurs langues, et qui disent: il dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Voici, j’en veux à ceux qui prophétisent des songes de fausseté, dit l’Eternel, et qui les récitent, et font égarer mon peuple par leurs mensonges, et par leur témérité, quoique je ne les aie point envoyés, et que je ne leur aie point donné de charge; c’est pourquoi ils ne profiteront de rien à ce peuple, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Si donc ce peuple t’interroge, ou qu’il interroge le Prophète, ou le Sacrificateur, en disant: quelle est la charge de l’Eternel? tu leur diras: quelle charge? Je vous abandonnerai, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Et quant au Prophète, et au Sacrificateur, et au peuple qui aura dit: la charge de l’Eternel; je punirai cet homme-là, et sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Vous direz ainsi chacun à son compagnon, et chacun à son frère: qu’a répondu l’Eternel; et qu’a prononcé l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Et vous ne ferez plus mention de la charge de l’Eternel; car la parole de chacun lui sera pour charge; parce que vous avez perverti les paroles du Dieu vivant, les paroles de l’Eternel des armées, notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Tu diras ainsi au Prophète: que t’a répondu l’Eternel, et que t’a prononcé l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Et si vous dites: la charge de l’Eternel; à cause de cela, a dit l’Eternel, parce que vous avez dit cette parole, la charge de l’Eternel; et que j’ai envoyé vers vous, pour vous dire: ne dites plus: la charge de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'A cause de cela me voici, et je vous oublierai entièrement, et j’arracherai de ma présence, vous et la ville que j’ai donnée à vous et à vos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'Et je mettrai sur vous un opprobre éternel, et une confusion éternelle, qui ne sera point mise en oubli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'L’Eternel me fit voir une vision, et voici deux paniers de figues, posés devant le Temple de l’Eternel, après que Nébucadnetsar Roi de Babylone eut transporté de Jérusalem Jéchonias fils de Jéhojakim, Roi de Juda, et les principaux de Juda, avec les charpentiers et les serruriers, et les eut emmenés à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'L’un des paniers avait de fort bonnes figues, comme sont d’ordinaire les figues qui sont les premières mûres; et l’autre panier avait de fort mauvaises figues, lesquelles on n’aurait pu manger, tant elles étaient mauvaises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Et l’Eternel me dit: que vois-tu, Jérémie? Et je répondis: des figues, de bonnes figues, fort bonnes; et de mauvaises, fort mauvaises, lesquelles on ne saurait manger, tant elles sont mauvaises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Alors la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'Ainsi a dit l’Eternel, le Dieu d’Israël: comme ces figues sont bonnes, ainsi je me souviendrai, pour leur faire du bien, de ceux qui ont été transportés de Juda, lesquels j’ai envoyés hors de ce lieu au pays des Caldéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Et je mettrai mes yeux sur eux pour leur faire du bien, et je les ferai retourner en ce pays, je les y rétablirai, et je ne les ruinerai plus, je les planterai, et je ne les arracherai point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Et je leur donnerai un coeur pour me connaître, pour connaître, dis-je, que je suis l’Eternel; et ils seront mon peuple, et je serai leur Dieu: car ils se retourneront à moi de tout leur coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Et comme ces figues sont si mauvaises qu’on n’en peut manger, tant elles sont mauvaises; ainsi certainement, a dit l’Eternel, je rendrai tel Sédécias le Roi de Juda, et les principaux de sa Cour, et le reste de Jérusalem qui sont demeurés dans ce pays, et ceux qui s’habitueront au pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Et je les livrerai pour être agités pour leur malheur par tous les Royaumes de la terre, et pour être en opprobre, en proverbe, en raillerie, et en malédiction par tous les lieux où je les aurai chassés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Et j’enverrai sur eux l’épée, la famine, et la mortalité, jusqu’à ce qu’ils soient consumés de dessus la terre que je leur avais donnée, à eux, et à leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'La parole qui fut adressée à Jérémie touchant tout le peuple de Juda, la quatrième année de Jéhojakim fils de Josias Roi de Juda, qui est la première année de Nébucadnetsar Roi de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'Laquelle Jérémie le Prophète prononça à tout le peuple de Juda, et à tous les habitants de Jérusalem, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Depuis la treizième année de Josias fils d’Amon Roi de Juda, jusqu’à ce jour, qui est la vingt-troisième année, la parole de l’Eternel m’a été adressée, et je vous ai parlé, me levant dès le matin, et parlant; mais vous n’avez point écouté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Et l’Eternel vous a envoyé tous ses serviteurs Prophètes, se levant dès le matin, et les envoyant; mais vous ne les avez point écoutés, et vous n’avez point incliné vos oreilles pour écouter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Lorsqu’ils disaient: détournez-vous maintenant chacun de son mauvais train, et de la malice de vos actions, et vous habiterez d’un siècle à l’autre sur la terre que l’Eternel vous a donnée, à vous et à vos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Et n’allez point après d’autres dieux, pour les servir, et pour vous prosterner devant eux, et ne m’irritez point par les oeuvres de vos mains; et je ne vous ferai aucun mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Mais vous m’avez désobéi, dit l’Eternel, pour m’irriter par les oeuvres de vos mains, à votre dommage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'C’est pourquoi ainsi a dit l’Eternel des armées: parce que vous n’avez point écouté mes paroles,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'Voici, j’enverrai, et j’assemblerai toutes les familles de l’Aquilon, dit l’Eternel, j’enverrai, dis-je, vers Nébucadnetsar Roi de Babylone mon serviteur; et je les ferai venir contre ce pays et contre ses habitants, et contre toutes ces nations d’alentour; je les détruirai à la façon de l’interdit, je les mettrai en désolation, et en opprobre, et en déserts éternels.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Et je ferai cesser parmi eux la voix de joie, et la voix d’allégresse, la voix de l’époux et la voix de l’épouse, le bruit des meules, et la lumière des lampes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'Et tout ce pays sera un désert, jusqu’à s’en étonner, et ces nations seront asservies au Roi de Babylone soixante-dix ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Et il arrivera que quand les soixante-dix ans seront accomplis, je punirai, dit l’Eternel, le Roi de Babylone, et cette nation-là, de leurs iniquités, et le pays des Caldéens, que je mettrai en désolations éternelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Et je ferai venir sur ce pays-là toutes mes paroles que j’ai prononcées contre lui, toutes les choses qui sont écrites dans ce livre, lesquelles Jérémie a prophétisées contre toutes ces nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Car de grands Rois aussi et de grandes nations se serviront d’eux, et je leur rendrai selon leurs actions, et selon l’oeuvre de leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Car ainsi m’a dit l’Eternel, le Dieu d’Israël: prends de ma main la coupe de ce vin, savoir de cette fureur-ci, et en fais boire à tous les peuples auxquels je t’envoie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Ils en boiront, et ils en seront troublés, et ils en perdront l’esprit, à cause de l’épée que j’enverrai parmi eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Je pris donc la coupe de la main de l’Eternel, et j’en fis boire à toutes les nations auxquelles l’Eternel m’envoyait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Savoir à Jérusalem, et aux villes de Juda, et à ses Rois, et à ses principaux, pour les mettre en désolation, en étonnement, en opprobre, et en malédiction, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'A Pharaon Roi d’Egypte, et à ses serviteurs, et aux principaux de sa Cour, et à tout son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'Et à tout le mélange d’Arabie, et à tous les Rois du pays de Huts; et à tous les Rois du pays des Philistins, à Askélon, Gaza, et Hékron, et au reste d’Asdod.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'A Edom; et à Moab; et aux enfants de Hammon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'A tous les Rois de Tyr; et à tous les Rois de Sidon; et aux Rois des Iles qui sont au delà de la mer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'A Dédan; Téma; et Buz; et à tous ceux qui se sont coupés les cheveux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'A tous les Rois d’Arabie, et à tous les Rois du mélange qui habitent au désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'Et à tous les Rois de Zimri; et à tous les Rois de Hélam; et à tous les Rois de Mède;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'Et à tous les Rois de l’Aquilon, tant proches qu’éloignés l’un de l’autre; et à tous les Royaumes de la terre, qui sont sur le dessus de la terre; et le Roi de Sésac en boira après eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Et tu leur diras: ainsi a dit l’Eternel des armées, le Dieu d’Israël: buvez et soyez enivrés, même rendez le vin que vous avez bu et soyez renversés sans vous relever, à cause de l’épée que j’enverrai parmi vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Or il arrivera qu’ils refuseront de prendre la coupe de ta main pour en boire; mais tu leur diras: ainsi a dit l’Eternel des armées: vous en boirez certainement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Car voici, je commence d’envoyer du mal sur la ville sur laquelle mon Nom est réclamé, et vous, en seriez-vous exempts en quelque sorte? vous n’en serez point exempts; car je m’en vais appeler l’épée sur tous les habitants de la terre, dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Tu prophétiseras donc contre eux toutes ces paroles-là, et tu leur diras: l’Eternel rugira d’en haut, et fera entendre sa voix de la demeure de sa Sainteté; il rugira d’une façon épouvantable contre son agréable demeure; il redoublera vers tous les habitants de la terre un cri d’encouragement, comme quand on presse au pressoir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Le son éclatant en est venu jusques au bout de la terre; car l’Eternel plaide avec les nations, et il contestera contre toute chair; on livrera les méchants à l’épée, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Ainsi a dit l’Eternel des armées: voici, le mal s’en va sortir d’une nation à l’autre, et un grand tourbillon se lèvera du fond de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'Et en ce jour-là ceux qui auront été mis à mort par l’Eternel seront étendus depuis un bout de la terre, jusques à son autre bout, ils ne seront point pleurés, et ils ne seront point recueillis, ni ensevelis; mais ils seront comme du fumier sur le dessus de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Vous pasteurs, hurlez et criez; et vous magnifiques du troupeau, vautrez-vous dans la poudre; car les jours déterminés pour vous massacrer, et les jours de votre mort sont accomplis; et vous tomberez comme un vaisseau désirable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Et les pasteurs n’auront aucun moyen de s’enfuir, ni les magnifiques du troupeau, d’échapper.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Il y aura une voix du cri des pasteurs, et un hurlement des plus puissants du troupeau, à cause que l’Eternel s’en va ravager leurs pâturages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'Et les cabanes paisibles seront abattues, à cause de l’ardeur de la colère de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Il a abandonné son Tabernacle, comme le lionceau, car leur pays va être mis en désolation, à cause de l’ardeur de la fourrageuse, à cause, dis-je, de l’ardeur de sa colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Au commencement du règne de Jéhojakim, fils de Josias, Roi de Juda, cette parole fut adressée à Jérémie par l’Eternel, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Ainsi a dit l’Eternel: tiens-toi debout au parvis de la maison de l’Eternel, et prononce à toutes les villes de Juda qui viennent pour se prosterner dans la maison de l’Eternel, toutes les paroles que je t’ai commandé de leur prononcer; n’en retranche pas une parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Peut-être qu’ils écouteront, et qu’ils se détourneront chacun de son mauvais train; et je me repentirai du mal que je pense de leur faire à cause de la malice de leurs actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Tu leur diras donc: ainsi a dit l’Eternel: si vous ne m’écoutez point pour marcher dans ma Loi, laquelle je vous ai proposée,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'Pour obéir aux paroles des Prophètes mes serviteurs que je vous envoie, me levant dès le matin, et les envoyant, lesquels vous n’avez point écoutés:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'Je mettrai cette maison en même état que Silo, et je livrerai cette ville en malédiction à toutes les nations de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Or les Sacrificateurs et les Prophètes, et tout le peuple entendirent Jérémie prononçant ces paroles dans la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Et il arriva qu’aussitôt que Jérémie eut achevé de prononcer tout ce que l’Eternel lui avait commandé de prononcer à tout le peuple, les Sacrificateurs et les Prophètes et tout le peuple le saisirent, en disant: tu mourras de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Pourquoi as-tu prophétisé au Nom de l’Eternel, disant: cette maison sera comme Silo, et cette ville sera déserte, tellement que personne n’y habitera? Et tout le peuple s’assembla vers Jérémie dans la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Et les principaux de Juda ayant ouï toutes ces choses montèrent de la maison du Roi à la maison de l’Eternel, et s’assirent à l’entrée de la porte neuve de la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Et les Sacrificateurs et les Prophètes parlèrent aux principaux, et à tout le peuple, en disant: cet homme mérite d’être condamné à la mort, car il a prophétisé contre cette ville, comme vous l’avez entendu de vos oreilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Et Jérémie parla à tous les principaux, et à tout le peuple, en disant: l’Eternel m’a envoyé pour prophétiser contre cette maison, et contre cette ville, selon toutes les paroles que vous avez ouïes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Maintenant donc, corrigez votre conduite et vos actions; et écoutez la voix de l’Eternel votre Dieu, et l’Eternel se repentira du mal qu’il a prononcé contre vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Pour moi, me voici entre vos mains, faites de moi comme il vous semblera bon et juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Mais sachez comme une chose certaine, que si vous me faites mourir, vous mettrez du sang innocent sur vous, et sur cette ville, et sur ses habitants; car en vérité l’Eternel m’a envoyé vers vous, afin de prononcer toutes ces paroles, vous l’entendant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Alors les principaux et tout le peuple dirent aux Sacrificateurs et aux Prophètes: cet homme ne mérite pas d’être condamné à la mort; car il nous a parlé au Nom de l’Eternel notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Et quelques-uns des Anciens du pays se levèrent, et parlèrent à toute l’assemblée du peuple, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Michée Morastite a prophétisé aux jours d’Ezéchias Roi de Juda, et a parlé à tout le peuple de Juda, en disant: ainsi a dit l’Eternel des armées, Sion sera labourée comme un champ, et Jérusalem sera réduite en monceaux de pierres, et la montagne du Temple en de hauts lieux d’une forêt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Ezéchias le Roi de Juda, et tous ceux de Juda le firent-ils mourir? Ne craignit-il pas l’Eternel, et ne supplia-t-il pas l’Eternel? et l’Eternel se repentit du mal qu’il avait prononcé contre eux; nous faisons donc un grand mal contre nos âmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Mais aussi, dirent les autres, il y eut un homme qui prophétisa au Nom de l’Eternel, savoir Urie, fils de Sémahia, de Kiriath- jéharim, lequel ayant prophétisé contre cette même ville, et contre ce même pays, en la même manière que Jérémie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Et le Roi Jéhojakim, avec tous ses officiers, et les principaux ayant entendu ses paroles, le Roi chercha à le faire mourir; mais Urie l’ayant appris, et ayant craint, s’enfuit, et se retira en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Et le Roi Jéhojakim envoya des hommes en Egypte, savoir Elnathan, fils de Hacbor, et quelques gens avec lui, qui allèrent en Egypte,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Et qui firent revenir Urie d’Egypte, et l’amenèrent au Roi Jéhojakim, qui le frappa avec l’épée, et jeta son corps mort aux sépulcres du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Toutefois la main d’Ahikam fils de Saphan fut pour Jérémie, afin qu’on ne le livrât point entre les mains du peuple, pour le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Au commencement du règne de Jéhojakim fils de Josias, Roi de Juda, cette parole fut adressée par l’Eternel à Jérémie, pour dire:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Ainsi m’a dit l’Eternel: fais-toi des liens, et des jougs, et les mets sur ton cou;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Et les envoie au Roi d’Edom, et au Roi de Moab, et au Roi des enfants de Hammon, et au Roi de Tyr, et au Roi de Sidon, par les mains des messagers qui doivent venir à Jérusalem vers Sédécias Roi de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'Et commande-leur de dire à leurs maîtres: ainsi a dit l’Eternel des armées, le Dieu d’Israël: vous direz ainsi à vos maîtres:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'J’ai fait la terre, les hommes, et les bêtes qui sont sur la terre par ma grande force, et par mon bras étendu, et je l’ai donnée à qui bon m’a semblé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Et maintenant j’ai livré tous ces pays en la main de Nébucadnetsar Roi de Babylone, mon serviteur; et même je lui ai donné les bêtes de la campagne, afin qu’elles lui soient asservies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Et toutes les nations lui seront asservies, et à son fils, et au fils de son fils, jusqu’à ce que le temps de son pays même vienne aussi, et que plusieurs nations et de grands Rois l’asservissent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Et il arrivera que la nation et le Royaume qui ne se sera pas soumis à Nébucadnetsar, Roi de Babylone, et qui n’aura pas soumis son cou au joug du Roi de Babylone, je punirai cette nation-là, dit l’Eternel, par l’épée, et par la famine, et par la mortalité, jusqu’à ce que je les aie consumés par sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Vous donc n’écoutez point vos Prophètes, ni vos devins, ni vos songeurs, ni vos augures, ni vos magiciens, qui vous parlent, en disant: vous ne serez point asservis au Roi de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Car ils vous prophétisent le mensonge pour vous faire aller loin de votre terre, afin que je vous en jette dehors, et que vous périssiez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Mais la nation qui soumettra son cou au joug du Roi de Babylone, et qui se soumettra à lui, je la laisserai dans sa terre, dit l’Eternel, et elle la labourera, et y demeurera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Puis je parlai à Sédécias Roi de Juda, selon toutes ces paroles- là, en disant: soumettez votre cou au joug du Roi de Babylone, et rendez-vous sujets à lui, et à son peuple, et vous vivrez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Pourquoi mourriez-vous, toi et ton peuple, par l’épée, et par la famine, et par la mortalité, selon que l’Eternel a parlé touchant la nation qui ne se sera point soumise au Roi de Babylone?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'N’écoutez donc point les paroles des Prophètes qui vous parlent, en disant: vous ne serez point asservis au Roi de Babylone; car ils vous prophétisent le mensonge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Même je ne les ai point envoyés, dit l’Eternel, et ils vous prophétisent faussement en mon Nom, afin que je vous rejette, et que vous périssiez, vous et les Prophètes qui vous prophétisent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Je parlai aussi aux Sacrificateurs, et à tout le peuple, en disant: ainsi a dit l’Eternel: n’écoutez point les paroles de vos Prophètes qui vous prophétisent, en disant: voici, les vaisseaux de la maison de l’Eternel retourneront bientôt de Babylone; car ils vous prophétisent le mensonge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Ne les écoutez donc point, rendez-vous sujets au Roi de Babylone, et vous vivrez; pourquoi cette ville serait-elle réduite en un désert?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Et s’ils sont Prophètes, et que la parole de l’Eternel soit en eux, qu’ils intercèdent maintenant envers l’Eternel des armées, afin que les vaisseaux qui sont restés dans la maison de l’Eternel, et dans la maison du Roi de Juda, et à Jérusalem, n’aillent point à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Car ainsi a dit l’Eternel des armées touchant les colonnes, et la mer, et les soubassements, et les autres vaisseaux qui sont restés en cette ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'Lesquels Nébucadnetsar Roi de Babylone n’a point emportés, quand il a transporté de Jérusalem à Babylone Jéchonias fils de Jéhojakim Roi de Juda, et tous les Magistrats de Juda, et de Jérusalem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'L’Eternel, dis-je, des armées, le Dieu d’Israël a dit ainsi, touchant les vaisseaux qui sont restés dans la maison de l’Eternel, et dans la maison du Roi de Juda, et à Jérusalem:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'Ils seront emportés à Babylone, et ils y demeureront jusqu’au jour que je les visiterai, dit l’Eternel; puis je les ferai remonter, et revenir en ce lieu-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Il arriva aussi en cette même année, au commencement du règne de Sédécias Roi de Juda, savoir en la quatrième année, au cinquième mois, que Hanania fils de Hazur Prophète, qui était de Gabaon, me parla dans la maison de l’Eternel, en la présence des Sacrificateurs et de tout le peuple, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Ainsi a dit l’Eternel des armées, le Dieu d’Israël: j’ai rompu le joug du Roi de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Dans deux ans accomplis je ferai rapporter en ce lieu-ci tous les vaisseaux de la maison de l’Eternel, que Nébucadnetsar Roi de Babylone a emportés de ce lieu, et transportés à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Et je ferai revenir en ce lieu-ci, dit l’Eternel, Jéchonias fils de Jéhojakim Roi de Juda, et tous ceux qui ont été transportés de Juda en Babylone; car je romprai le joug du Roi de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Alors Jérémie le Prophète parla à Hanania le Prophète, en la présence des Sacrificateurs, et en la présence de tout le peuple qui assistaient dans la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Et Jérémie le Prophète dit: ainsi soit-il; qu’ainsi fasse l’Eternel; que l’Eternel mette en effet tes paroles que tu as prophétisées, afin qu’il fasse revenir de Babylone en ce lieu-ci les vaisseaux de la maison de l’Eternel, et tous ceux qui ont été transportés à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Toutefois écoute maintenant cette parole que je prononce, toi et tout le peuple l’entendant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Les Prophètes qui ont été avant moi et avant toi dès longtemps, ont prophétisé contre plusieurs pays, et contre de grands Royaumes, la guerre, et l’affliction, et la mortalité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Le Prophète qui aura prophétisé la paix, quand la parole de ce Prophète sera accomplie, ce Prophète-là sera reconnu pour avoir été véritablement envoyé par l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Alors Hanania le Prophète prit le joug de dessus le cou de Jérémie le Prophète, et le rompit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Puis Hanania parla en la présence de tout le peuple, en disant: ainsi a dit l’Eternel: entre ci et deux ans accomplis, je romprai ainsi le joug de Nébucadnetsar Roi de Babylone de dessus le cou de toutes les nations. Et Jérémie le Prophète s’en alla son chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Mais la parole de l’Eternel fut adressée à Jérémie, après que Hanania le Prophète eut rompu le joug de dessus le cou de Jérémie le Prophète, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Va, et parle à Hanania, en disant: ainsi a dit l’Eternel: tu as rompu les jougs qui étaient de bois, mais au lieu de ceux-là, fais-en qui soient de fer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Car ainsi a dit l’Eternel des armées, le Dieu d’Israël: j’ai mis un joug de fer sur le cou de toutes ces nations, afin qu’elles soient asservies à Nébucadnetsar Roi de Babylone, car elles lui seront asservies, et je lui ai aussi donné les bêtes des champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Puis Jérémie le Prophète dit à Hanania le prophète: écoute maintenant, ô Hanania! l’Eternel ne t’a point envoyé, mais tu as fait que ce peuple s’est confié au mensonge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'C’est pourquoi ainsi a dit l’Eternel, voici, je te chasserai de dessus la terre, et tu mourras cette année; car tu as parlé de révolte contre l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Et Hanania le prophète mourut cette année-là au septième mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Or ce sont ici les paroles des Lettres que Jérémie le Prophète envoya de Jérusalem au reste des Anciens de ceux qui avaient été transportés, et aux Sacrificateurs, et aux Prophètes, et à tout le peuple que Nébucadnetsar avait transporté de Jérusalem à Babylone;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'Après que le Roi Jéchonias fut sorti de Jérusalem, avec la Régente, et les Eunuques, et les principaux de Juda et de Jérusalem, et les charpentiers, et les serruriers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Par Elhasa fils de Saphan, et Guémarja fils de Hilkija, lesquels Sédécias Roi de Juda envoyait à Babylone vers Nébucadnetsar Roi de Babylone; et ces Lettres étaient de telle teneur:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Ainsi a dit l’Eternel des armées, le Dieu d’Israël, à tous ceux qui ont été transportés, et que j’ai fait transporter de Jérusalem à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Bâtissez des maisons, et y demeurez; plantez des jardins, et en mangez les fruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Prenez des femmes, et engendrez des fils et des filles; prenez aussi des femmes pour vos fils, et donnez vos filles à des hommes, et qu’elles enfantent des fils et des filles, et multipliez là, et ne soyez point diminués.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Et cherchez la paix de la ville dans laquelle je vous ai fait transporter, et priez l’Eternel pour elle; parce qu’en sa paix vous aurez la paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Car ainsi a dit l’Eternel des armées, le Dieu d’Israël: que vos prophètes qui sont parmi vous, et vos devins, ne vous séduisent point, et ne croyez point à vos songes que vous songez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Parce qu’ils vous prophétisent faussement en mon Nom; je ne les ai point envoyés, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Car ainsi a dit l’Eternel: lorsque les soixante-dix ans seront accomplis à Babylone, je vous visiterai, et je mettrai en exécution ma bonne parole sur vous, pour vous faire retourner en ce lieu-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Car je sais que les pensées que j’ai sur vous, dit l’Eternel, sont des pensées de paix, et non pas d’adversité, pour vous donner une fin telle que vous attendez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Alors vous m’invoquerez pour vous en retourner; et vous me prierez, et je vous exaucerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'Vous me chercherez, et vous me trouverez, après que vous m’aurez recherché de tout votre coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'Car je me ferai trouver à vous, dit l’Eternel, je ramènerai vos captifs, et je vous rassemblerai d’entre toutes les nations, et de tous les lieux où je vous aurai dispersés, dit l’Eternel, et je vous ferai retourner au lieu dont je vous aurai transportés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Parce que vous aurez dit: l’Eternel nous a suscité des Prophètes qui ont prophétisé que nous viendrions à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'C’est pourquoi ainsi a dit l’Eternel, touchant le Roi qui est assis sur le trône de David, et touchant tout le peuple qui habite dans cette ville, c’est-à-dire, touchant vos frères qui ne sont point allés avec vous en captivité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'Ainsi a dit l’Eternel des armées: voici, je m’en vais envoyer sur eux l’épée, la famine, et la mortalité, et je les ferai devenir comme des figues qui sont étrangement mauvaises, et qu’on ne peut manger, tant elles sont mauvaises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Et je les poursuivrai avec l’épée, par la famine, et par la mortalité; et je les abandonnerai à être agités par tous les Royaumes de la terre, et pour être en exécration, en étonnement, en raillerie, et en opprobre à toutes les nations parmi lesquelles je les aurai dispersés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'Parce qu’ils n’ont point écouté mes paroles, dit l’Eternel, qui leur ai envoyé mes serviteurs Prophètes, en me levant dès le matin, et les envoyant; et vous n’avez point écouté, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Vous tous donc qui avez été transportés, et que j’ai renvoyés de Jérusalem à Babylone, écoutez la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Ainsi a dit l’Eternel des armées, le Dieu d’Israël, touchant Achab fils de Kolaja, et touchant Sédécias fils de Mahaséja, qui vous prophétisent faussement en mon Nom: voici, je m’en vais les livrer en la main de Nébucadnetsar Roi de Babylone, et il les frappera devant vos yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'Et on prendra d’eux un formulaire de malédiction parmi tous ceux qui ont été transportés de Juda, qui sont à Babylone, en disant: l’Eternel te mette en tel état qu’il a mis Sédécias et Achab, lesquels le Roi de Babylone a grillés au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'Parce qu’ils ont commis des impuretés en Israël, et qu’ils ont commis adultère avec les femmes de leurs prochains, et qu’ils ont dit en mon Nom des paroles fausses, que je ne leur avais pas commandées, et je le sais, et j’en suis témoin, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Parle aussi à Sémahia Néhélamite, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Ainsi a dit l’Eternel des armées, le Dieu d’Israël: parce que tu as envoyé en ton Nom des Lettres à tout le peuple qui est à Jérusalem, et à Sophonie fils de Mahaséja Sacrificateur, et à tous les Sacrificateurs, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'L’Eternel t’a établi pour Sacrificateur en la place de Jéhojadah le Sacrificateur, afin que vous ayez la charge de la maison de l’Eternel sur tout homme agité par l’esprit, et faisant du Prophète, pour les mettre en prison et aux fers:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Et maintenant, pourquoi n’as-tu pas réprimé Jérémie de Hanathot, qui vous prophétise?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Car à cause de cela il nous a envoyé dire à Babylone: la captivité sera longue: bâtissez des maisons, et y demeurez; plantez des jardins, et mangez-en les fruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, '(Or Sophonie le Sacrificateur avait lu ces Lettres-là, Jérémie le Prophète l’entendant,)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'C’est pourquoi la parole de l’Eternel fut adressée à Jérémie, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Mande à tous ceux qui ont été transportés, et leur dis: ainsi a dit l’Eternel touchant Sémahia Néhélamite: parce que Sémahia vous a prophétisé, quoique je ne l’aie point envoyé, et vous a fait confier au mensonge;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'A cause de cela l’Eternel a dit ainsi: voici, je m’en vais punir Sémahia Néhélamite et sa postérité, et il n’y aura personne de sa race qui habite parmi ce peuple, et il ne verra point le bien que je m’en vais faire à mon peuple, dit l’Eternel; parce qu’il a parlé de révolte contre l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'La parole qui fut adressée à Jérémie par l’Eternel, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Ainsi a parlé l’Eternel, le Dieu d’Israël, en disant: écris-toi dans un livre toutes les paroles que je t’ai dites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Car voici, les jours viennent, dit l’Eternel, que je ramènerai les captifs de mon peuple d’Israël et de Juda, a dit l’Eternel, et je les ferai retourner au pays que j’ai donné à leurs pères, et ils le posséderont.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Et ce sont ici les paroles que l’Eternel a prononcées touchant Israël, et Juda:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Ainsi a donc dit l’Eternel: nous avons ouï un bruit d’épouvantement et de frayeur, et il n’y a point de paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Informez-vous, je vous prie, et considérez si un mâle enfante; pourquoi donc ai-je vu tout homme tenant ses mains sur ses reins comme une femme qui enfante? et pourquoi tous les visages sont-ils jaunes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Hélas! que cette journée-là est grande, il n’y en a point eu de semblable, et elle sera un temps de détresse à Jacob; mais il en sera pourtant délivré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Et il arrivera en ce jour-là, dit l’Eternel des armées, que je briserai son joug de dessus ton cou, et que je romprai tes liens; et les étrangers ne t’asserviront plus;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Mais ils serviront l’Eternel leur Dieu, et David leur Roi, lequel je leur susciterai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Toi donc, mon serviteur Jacob, ne crains point, dit l’Eternel, et ne t’épouvante point, ô Israël! car voici, je m’en vais te délivrer du pays éloigné; et ta postérité du pays de leur captivité; et Jacob retournera, il sera en repos et à son aise, et il n’y aura personne qui lui fasse peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Car je suis avec toi, dit l’Eternel, pour te délivrer; et même je consumerai entièrement toutes les nations parmi lesquelles je t’aurai dispersé; mais quant à toi, je ne te consumerai point entièrement, mais je te châtierai par mesure, et je ne te tiendrai pas entièrement pour innocent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Car ainsi a dit l’Eternel: ta blessure est hors d’espérance, et ta plaie est fort douloureuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Il n’y a personne qui défende ta cause pour nettoyer ta plaie; il n’y a point pour toi de remède qui y fasse revenir la chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Tous tes amoureux t’ont oubliée, ils ne te cherchent point; car je t’ai frappée d’une plaie d’ennemi, d’un châtiment d’homme cruel, à cause de la grandeur de tes iniquités; tes péchés se sont renforcés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Pourquoi cries-tu à cause de ta plaie? ta douleur est hors d’espérance; je t’ai fait ces choses à cause de la grandeur de ton iniquité, tes péchés se sont renforcés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Néanmoins tous ceux qui te dévorent, seront dévorés, et tous ceux qui te mettent dans la détresse iront en captivité; et tous ceux qui te fourragent seront fourragés; et j’abandonnerai au pillage tous ceux qui te pillent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Même je consoliderai tes plaies, et te guérirai de tes blessures, dit l’Eternel. Parce qu’ils t’ont appelée la déchassée, et qu’ils ont dit: c’est Sion, personne ne la recherche:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Ainsi a dit l’Eternel: voici, je m’en vais ramener les captifs des tentes de Jacob, et j’aurai pitié de ses pavillons; la ville sera rétablie sur son sol, et le palais sera assis en sa place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Et il sortira d’eux actions de grâces et voix de gens qui rient, et je les multiplierai, et ils ne seront plus diminués; et je les agrandirai, et ils ne seront point rendus petits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Et ses enfants seront comme auparavant, et son assemblée sera affermie devant moi, et je punirai tous ceux qui l’oppriment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Et celui qui aura autorité sur lui sera de lui, et son dominateur sortira du milieu de lui, je le ferai approcher, et il viendra vers moi; car qui est celui qui ait disposé son coeur pour venir vers moi? dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'Et vous serez mon peuple, et je serai votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Voici, la tempête de l’Eternel, la fureur est sortie, un tourbillon qui s’entasse; il se posera sur la tête des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'L’ardeur de la colère de l’Eternel ne se détournera point, jusqu’à ce qu’il ait exécuté et mis en effet les desseins de son coeur; vous entendrez ceci aux derniers jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'En ce temps-là, dit l’Eternel, je serai le Dieu de toutes les familles d’Israël, et ils seront mon peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Ainsi a dit l’Eternel: le peuple réchappé de l’épée a trouvé grâce dans le désert; on va pour faire trouver du repos à Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'L’Eternel m’est apparu de loin, et m’a dit: je t’ai aimée d’un amour éternel, c’est pourquoi j’ai prolongé envers toi ma gratuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Je t’établirai encore, et tu seras établie, ô vierge d’Israël! Tu te pareras encore de tes tambours, et tu sortiras avec la danse des joueurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Tu planteras encore des vignes sur les montagnes de Samarie; les vignerons les planteront, et ils en recueilleront les fruits pour leur usage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Car il y a un jour auquel les gardes crieront en la montagne d’Ephraïm: levez-vous, et montons en Sion vers l’Eternel notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Car ainsi a dit l’Eternel: réjouissez-vous avec chant de triomphe, et avec allégresse à cause de Jacob, et vous égayez à cause du chef des nations; faites-le entendre, chantez des louanges, et dites: Eternel, délivre ton peuple, le reste d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Voici, je m’en vais les faire venir du pays d’Aquilon, et je les rassemblerai du fond de la terre; l’aveugle et le boiteux, la femme enceinte et celle qui enfante seront ensemble parmi eux; une grande assemblée retournera ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Ils y seront allés en pleurant, mais je les ferai retourner avec des supplications, et je les conduirai aux torrents d’eaux, et par un droit chemin, auquel ils ne broncheront point; car j’ai été pour père à Israël, et Ephraïm est mon premier-né.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Nations, écoutez la parole de l’Eternel, et l’annoncez aux Iles éloignées, et dites: celui qui a dispersé Israël le rassemblera, et le gardera comme un berger garde son troupeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Car l’Eternel a racheté Jacob, et l’a retiré de la main d’un ennemi plus fort que lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Ils viendront donc, et se réjouiront avec chant de triomphe au lieu le plus haut de Sion, et ils accourront aux biens de l’Eternel, au froment, au vin, et à l’huile, et au fruit du gros et du menu bétail; et leur âme sera comme un jardin plein de fontaines, et ils ne seront plus dans l’ennui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Alors la vierge se réjouira en la danse, et les jeunes gens et les anciens ensemble, et je tournerai leur deuil en joie, et je les consolerai, et les réjouirai les délivrant de leur douleur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Je rassasierai aussi de graisse l’âme des Sacrificateurs, et mon peuple sera rassasié de mon bien, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Ainsi a dit l’Eternel: une voix très amère de lamentation et de pleurs a été ouïe à Rama, Rachel pleurant ses enfants, a refusé d’être consolée touchant ses enfants, de ce qu’il n’y en a plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Ainsi a dit l’Eternel: empêche ta voix de lamenter, et tes yeux de verser des larmes, car ton oeuvre aura son salaire, dit l’Eternel, et on retournera du pays de l’ennemi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Et il y a de l’espérance pour tes derniers jours, dit l’Eternel, et tes enfants retourneront en leurs quartiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'J’ai très bien ouï Ephraïm se plaignant, et disant: tu m’as châtié, et j’ai été châtié comme un taureau indompté; convertis-moi, et je serai converti; car tu es l’Eternel mon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Certes après que j’aurai été converti, je me repentirai; et après que je me serai reconnu, je frapperai sur ma cuisse. J’ai été honteux et confus, parce que j’ai porté l’opprobre de ma jeunesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Ephraïm ne m’a-t-il pas été un cher enfant? ne m’a-t-il pas été un enfant que j’ai aimé? car toutes les fois que j’ai parlé de lui, je n’ai pas manqué de m’en souvenir avec tendresse: c’est pourquoi mes entrailles se sont émues à cause de lui, et j’aurai certainement pitié de lui, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Dresse-toi des indices sur les chemins, et fais des monceaux de pierres; prends garde aux chemins, et par quelle voie tu es venue. Retourne-t-en, vierge d’Israël, retourne à tes villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Jusques à quand seras-tu agitée, fille rebelle? Car l’Eternel a créé une chose nouvelle sur la terre, la femme environnera l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Ainsi a dit l’Eternel des armées, le Dieu d’Israël: on dira encore cette parole-ci dans le pays de Juda et dans ses villes, quand j’aurai ramené leurs captifs: l’Eternel te bénisse, ô agréable demeure de la justice, montagne de sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Et Juda et toutes ses villes ensemble, les laboureurs, et ceux qui marchent avec les troupeaux, habiteront en elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Car j’ai enivré l’âme altérée par le travail, et j’ai rempli toute âme qui languissait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'C’est pourquoi je me suis réveillé, et j’ai regardé, et mon sommeil m’a été doux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Voici, les jours viennent, dit l’Eternel, que j’ensemencerai la maison d’Israël, et la maison de Juda, de semence d’hommes, et de semence de bêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Et il arrivera que comme j’ai veillé sur eux pour arracher et démolir, pour détruire, pour perdre, et pour faire du mal; ainsi je veillerai sur eux pour bâtir et pour planter, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'En ces jours-là on ne dira plus: les pères ont mangé le verjus, et les dents des enfants en sont agacées;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Mais chacun mourra pour son iniquité; tout homme qui mangera le verjus, ses dents en seront agacées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Voici, les jours viennent, dit l’Eternel, que je traiterai une nouvelle alliance avec la maison d’Israël, et avec la maison de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'Non selon l’alliance que je traitai avec leurs pères, au jour que je les pris par la main pour les faire sortir du pays d’Egypte, laquelle alliance ils ont enfreinte; et toutefois je leur avais été pour mari, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Car c’est ici l’alliance que je traiterai avec la maison d’Israël après ces jours-là, dit l’Eternel: Je mettrai ma Loi au dedans d’eux, je l’écrirai dans leur coeur; et je serai leur Dieu, et ils seront mon peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Chacun d’eux n’enseignera plus son prochain, ni chacun son frère, en disant: connaissez l’Eternel; car ils me connaîtront tous, depuis le plus petit d’entre eux jusques au plus grand, dit l’Eternel; parce que je pardonnerai leur iniquité, et que je ne me souviendrai plus de leur péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Ainsi a dit l’Eternel, qui donne le soleil pour être la lumière du jour, et le règlement de la lune et des étoiles pour être la lumière de la nuit; qui fend la mer, et les flots en bruient; duquel le Nom est l’Eternel des armées;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Si jamais ces règlements disparaissent de devant moi, dit l’Eternel, aussi la race d’Israël cessera d’être à jamais une nation devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Ainsi a dit l’Eternel: si les cieux se peuvent mesurer par dessus, et les fondements de la terre sonder par dessous, aussi rejetterai-je toute la race d’Israël; à cause de toutes les choses qu’ils ont faites, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Voici, les jours viennent, dit l’Eternel, que cette ville sera rebâtie à l’Eternel, depuis la tour d’Hananéel, jusqu’à la porte du coin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'Et encore le cordeau à mesurer sera tiré vis-à-vis d’elle sur la colline de Gareb, et fera le tour vers Goha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Et toute la vallée de la voirie et des cendres, et tout le quartier jusqu’au torrent de Cédron, jusqu’au coin de la porte des chevaux vers l’Orient, sera une sainteté à l’Eternel, et ne sera plus démoli ni détruit à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'La parole qui fut adressée de par l’Eternel à Jérémie, la dixième année de Sédécias Roi de Juda, qui est l’an dix-huitième de Nébucadnetsar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, '(Or l’armée du Roi de Babylone assiégeait alors Jérusalem, et Jérémie le Prophète était enfermé dans la cour de la prison, qui était dans la maison du Roi de Juda;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Car Sédécias Roi de Juda l’avait enfermé, et lui avait dit: pourquoi prophétises-tu? en disant: ainsi a dit l’Eternel: voici, je m’en vais livrer cette ville en la main du Roi de Babylone, et il la prendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'Et Sédécias Roi de Juda n’échappera point de la main des Caldéens, mais il sera certainement livré en la main du Roi de Babylone, et lui parlera bouche à bouche, et ses yeux verront les yeux de ce Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'Et il emmènera Sédécias à Babylone, qui y demeurera jusqu’à ce que je le visite, dit l’Eternel; si vous combattez contre les Caldéens, vous ne prospérerez point;)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Jérémie donc dit: la parole de l’Eternel m’a été adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Voici Hanaméel fils de Sallum ton oncle, qui vient vers toi, pour te dire: achète-toi mon champ, qui est à Hanathoth; car tu as le droit de retrait lignager pour le racheter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Hanaméel donc, fils de mon oncle, vint à moi, selon la parole de l’Eternel, dans la cour de la prison, et me dit: achète, je te prie, mon champ qui est à Hanathoth, dans le territoire de Benjamin: car tu as le droit de possession héréditaire, et de retrait lignager, achète-le donc pour toi; et je connus alors que c’était la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Ainsi j’achetai le champ de Hanaméel, fils de mon oncle, qui est à Hanathoth; et je lui pesai l’argent, qui fut dix-sept sicles d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'Puis j’en écrivis le contrat, et le cachetai, et je pris des témoins après avoir pesé l’argent dans la balance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Et je pris le contrat d’acquisition, tant celui qui était cacheté, selon l’ordonnance et les statuts, que celui qui était ouvert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'Et je donnai le contrat d’acquisition à Baruc fils de Nérija, fils de Mahaséja, en présence d’Hanaméel fils de mon oncle, et des témoins qui s’étaient souscrits dans le contrat de l’acquisition, et en présence de tous les Juifs qui étaient assis dans la cour de la prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'Puis je commandai en leur présence à Baruc, en lui disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'Ainsi a dit l’Eternel des armées, le Dieu d’Israël: prends ces contrats ici, savoir ce contrat d’acquisition, qui est cacheté, et ce contrat qui est ouvert, et mets-les dans un pot de terre, afin qu’ils puissent se conserver longtemps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Car ainsi a dit l’Eternel des armées, le Dieu d’Israël: on achètera encore des maisons, des champs, et des vignes en ce pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Et après que j’eus donné à Baruc fils de Nerija le contrat d’acquisition, je fis requête à l’Eternel, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Ah! ah! Seigneur Eternel, voici, tu as fait le ciel et la terre par ta grande puissance, et par ton bras étendu; aucune chose ne te sera difficile;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Tu fais miséricorde jusqu’en mille générations, et tu rends l’iniquité des pères dans le sein de leurs enfants après eux; tu es le Dieu Fort, le Grand, le Puissant, le Nom duquel est l’Eternel des armées;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'Grand en conseil, et abondant en moyens; car tes yeux sont ouverts sur toutes les voies des enfants des hommes, pour rendre à chacun selon ses voies, et selon le fruit de ses oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Tu as fait au pays d’Egypte des signes et des miracles qui sont connus jusques à ce jour, et dans Israël, et parmi les hommes, et tu t’es acquis un nom tel qu’ il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Car tu as retiré Israël ton peuple du pays d’Egypte, avec des signes et des miracles, et avec une main forte, et avec un bras étendu, et en répandant partout la frayeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'Et tu leur as donné ce pays que tu avais juré à leurs pères de leur donner, qui est un pays découlant de lait et de miel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Et ils y sont entrés et l’ont possédé; mais ils n’ont point obéi à ta voix, et n’ont point marché en ta Loi, et n’ont pas fait toutes les choses que tu leur avais commandé de faire; c’est pourquoi tu as fait que tout ce mal ici les a rencontrés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Voilà, les terrasses sont élevées, on est venu contre la ville pour la prendre, et à cause de l’épée, de la famine, et de la mortalité, la ville est livrée en la main des Caldéens qui combattent contre elle; et ce que tu as dit est arrivé, et voici, tu le vois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Et cependant, Seigneur Eternel! tu m’as dit: achète-toi ce champ à prix d’argent, et prends-en des témoins, quoique la ville soit livrée en la main des Caldéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Mais la parole de l’Eternel fut adressée à Jérémie, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Voici, je suis l’Eternel, le Dieu de toute chair; y aura-t-il quelque chose qui me soit difficile?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'C’est pourquoi ainsi a dit l’Eternel: voici, je m’en vais livrer cette ville entre les mains des Caldéens, et entre les mains de Nébucadnetsar Roi de Babylone, qui la prendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Et les Caldéens qui combattent contre cette ville, y entreront, et mettront le feu à cette ville, et la brûleront, avec les maisons sur les toits desquelles on a fait des parfums à Bahal, et où l’on a fait des aspersions à d’autres dieux pour m’irriter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Car les enfants d’Israël et les enfants de Juda n’ont fait dès leur jeunesse que ce qui déplaît à mes yeux; et les enfants d’Israël ne font que m’irriter par les oeuvres de leurs mains, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Car cette ville a été portée à provoquer ma colère et ma fureur, depuis le jour qu’ils l’ont bâtie, jusqu’à aujourd’hui, afin que je l’abolisse de devant ma face;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'A cause de toute la malice des enfants d’Israël, et des enfants de Juda, qu’ils ont commise pour m’irriter, eux, leurs Rois, les principaux d’entre eux, leurs Sacrificateurs, et leurs Prophètes, les hommes de Juda, et les habitants de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Ils m’ont abandonné; et quand je les ai enseignés, me levant dès le matin et les enseignant, ils n’ont point été obéissants pour recevoir instruction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Mais ils ont mis leurs abominations dans la maison sur laquelle mon Nom est réclamé, pour la souiller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Et ils ont bâti les hauts lieux de Bahal, qui sont en la vallée du fils de Hinnom, pour faire passer par le feu leurs fils et leurs filles à Molec; ce que je ne leur avais point commandé, et je n’avais jamais pensé qu’ils fissent cette abomination pour faire pécher Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Et maintenant, à cause de cela l’Eternel, le Dieu d’Israël, dit ainsi touchant cette ville de laquelle vous dites qu’elle est livrée entre les mains du Roi de Babylone, à cause que l’épée, la famine, et la mortalité sont en elle:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Voici, je m’en vais les rassembler de tous les pays dans lesquels je les aurai dispersés par ma colère et par ma fureur, et par ma grande indignation, et je les ferai retourner en ce lieu-ci, et je les y ferai demeurer en sûreté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'Et ils me seront pour peuple, et je leur serai pour Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'Et je leur donnerai un même coeur, et un même chemin, afin qu’ils me craignent à toujours, pour leur bien et le bien de leurs enfants après eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Et je traiterai avec eux une alliance éternelle, savoir que je ne me retirerai point d’eux pour leur faire du bien; et je mettrai ma crainte dans leur coeur, afin qu’ils ne se retirent point de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Et je prendrai plaisir à leur faire du bien, et je les planterai dans ce pays-ci solidement, de tout mon coeur, et de toute mon âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Car ainsi a dit l’Eternel: comme j’ai fait venir tout ce grand mal sur ce peuple, ainsi je m’en vais faire venir sur eux tout le bien que je prononce en leur faveur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Et on achètera des champs dans ce pays, duquel vous dites que ce n’est que désolation, n’y ayant ni homme ni bête, et qui est livré entre les mains des Caldéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'On achètera, dis-je, des champs à prix d’argent, et on en écrira les contrats, et on les cachettera, et on en prendra des témoins au pays de Benjamin, et aux environs de Jérusalem, dans les villes de Juda, tant dans les villes des montagnes, que dans les villes de la plaine, et dans les villes du Midi. Car je ferai retourner leurs captifs, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Et la parole de l’Eternel fut adressée une seconde fois à Jérémie, quand il était encore enfermé dans la cour de la prison, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Ainsi a dit l’Eternel qui s’en va faire ceci, l’Eternel qui s’en va le former pour l’établir, le Nom duquel est l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Crie vers moi, je te répondrai, et je te déclarerai des choses grandes et cachées, lesquelles tu ne sais point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Car ainsi a dit l’Eternel, le Dieu d’Israël, touchant les maisons de cette ville-ci, et les maisons des Rois de Juda; elles s’en vont être démolies par le moyen des terrasses, et par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Ils sont venus à combattre contre les Caldéens, mais ç’a été pour remplir leurs maisons des corps morts des hommes que j’ai fait frapper en ma colère et en ma fureur, et parce que j’ai caché ma face de cette ville à cause de toute leur malice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Voici, je m’en vais lui donner la santé et la guérison, je les guérirai, et je leur ferai voir abondance de paix et de vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Et je ferai retourner les captifs de Juda, et les captifs d’Israël, et je les rétablirai comme auparavant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'Et je les purifierai de toute leur iniquité, par laquelle ils ont péché contre moi; et je pardonnerai toutes leurs iniquités par lesquelles ils ont péché contre moi, et par lesquelles ils ont péché grièvement contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Et cette ville me sera un sujet de réjouissance, de louange et de gloire, chez toutes les nations de la terre qui entendront parler de tout le bien que je vais leur faire, et elles seront effrayées et épouvantées à cause de tout le bien, et de toute la prospérité que je vais lui donner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Ainsi a dit l’Eternel: dans ce lieu-ci duquel vous dites: il est désert, n’y ayant ni homme ni bête, dans les villes de Juda, et dans les rues de Jérusalem, qui sont désolées, n’y ayant ni homme, ni habitant, ni aucune bête, on y entendra encore,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'La voix de joie, et la voix d’allégresse, la voix de l’époux, et la voix de l’épouse, et la voix de ceux qui disent: célébrez l’Eternel des armées; car l’Eternel est bon, parce que sa miséricorde demeure à toujours, lorsqu’ils apportent des oblations d’action de grâces à la maison de l’Eternel; car je ferai retourner les captifs de ce pays, et je les mettrai au même état qu’auparavant, a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Ainsi a dit l’Eternel des armées: en ce lieu désert, où il n’y a ni homme ni bête, et dans toutes ses villes, il y aura encore des cabanes de bergers qui y feront reposer leurs troupeaux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'Dans les villes des montagnes, et dans les villes de la plaine, dans les villes du Midi, dans le pays de Benjamin, dans les environs de Jérusalem, et dans les villes de Juda; et les troupeaux passeront encore sous les mains de celui qui les compte, a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Voici, les jours viennent, dit l’Eternel, que je mettrai en effet la bonne parole que j’ai prononcée touchant la maison d’Israël, et la maison de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'En ces jours-là, et en ce temps-là je ferai germer à David le Germe de justice, qui exercera le jugement et la justice en la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'En ces jours-là Juda sera délivré, et Jérusalem habitera en assurance, et c’est ici le nom dont elle sera appelée: l’Eternel notre justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Car ainsi a dit l’Eternel, il ne manquera jamais à David d’homme assis sur le trône de la maison d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Et d’entre les Sacrificateurs Lévites, il ne manquera jamais d’y avoir devant moi d’homme offrant des holocaustes, faisant les parfums de gâteau, et faisant des sacrifices tous les jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Davantage la parole de l’Eternel fut adressée à Jérémie, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Ainsi a dit l’Eternel: Si vous pouvez abolir mon alliance touchant le jour, et mon alliance touchant la nuit, tellement que le jour et la nuit ne soient plus en leur temps;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'Aussi mon alliance avec David mon serviteur sera abolie; tellement qu’il n’ait plus de fils régnant sur son trône; et avec les Lévites Sacrificateurs, faisant mon service.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Car comme on ne peut compter l’armée des cieux, ni mesurer le sable de la mer, ainsi je multiplierai la postérité de David mon serviteur, et les Lévites qui font mon service.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'La parole de l’Eternel fut encore adressée à Jérémie, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'N’as-tu pas vu ce que ce peuple a prononcé, disant: l’Eternel a rejeté les deux familles qu’il avait élues; car par là ils méprisent mon peuple; tellement qu’à leur compte il ne sera plus une nation?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Ainsi a dit l’Eternel: si je n’ai point établi mon alliance touchant le jour et la nuit, et si je n’ai point établi les ordonnances des cieux et de la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'Aussi rejetterai-je la postérité de Jacob, et celle de David mon serviteur, pour ne prendre plus de sa postérité des gens qui dominent sur la postérité d’Abraham, d’Isaac, et de Jacob; car je ferai retourner leurs captifs, et j’aurai compassion d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'La parole qui fut adressée par l’Eternel à Jérémie, lorsque Nébucadnetsar Roi de Babylone, et toute son armée, tous les Royaumes de la terre, et tous les peuples qui étaient sous la puissance de sa main combattaient contre Jérusalem, et contre toutes ses villes, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'Ainsi a dit l’Eternel, le Dieu d’Israël: va, et parle à Sédécias Roi de Juda, et lui dis: ainsi a dit l’Eternel, voici, je m’en vais livrer cette ville en la main du Roi de Babylone, et il la brûlera au feu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Et tu n’échapperas point de sa main; car certainement tu seras pris; et tu seras livré entre ses mains, et tes yeux verront les yeux du Roi de Babylone; et il parlera à toi bouche à bouche, et tu viendras dans Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Toutefois, ô Sédécias Roi de Juda, écoute la parole de l’Eternel: l’Eternel a parlé ainsi de toi: tu ne mourras point par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'Mais tu mourras en paix, et on fera brûler sur toi des choses aromatiques, comme on en a brûlé sur tes pères, les Rois précédents qui ont été devant toi; et on te plaindra, en disant: hélas, Seigneur! car j’ai prononcé cette parole, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Jérémie donc le Prophète prononça toutes ces paroles-là à Sédécias Roi de Juda, dans Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'Et l’armée du Roi de Babylone combattait contre Jérusalem, et contre toutes les villes de Juda qui étaient demeurées de reste, savoir contre Lakis, et contre Hazéka, car c’étaient les seules villes fortes qui restaient entre les villes de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'La parole qui fut adressée par l’Eternel à Jérémie, après que le Roi Sédécias eut traité alliance avec tout le peuple qui était à Jérusalem, pour leur publier la liberté;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'Afin que chacun renvoyât libre son serviteur, et chacun sa servante, Hébreu ou Hébreue, et qu’aucun Juif ne fût l’esclave de son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Tous les principaux donc, et tout le peuple qui étaient entrés dans cette alliance, entendirent que chacun devait renvoyer libre son serviteur, et chacun sa servante, sans plus les asservir; et ils obéirent, et les renvoyèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Mais ensuite ils changèrent d’avis, et firent revenir leurs serviteurs et leurs servantes, qu’ils avaient renvoyés libres, et les assujettirent pour leur être serviteurs et servantes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Et la parole de l’Eternel fut adressée à Jérémie par l’Eternel, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'Ainsi a dit l’Eternel, le Dieu d’Israël: je traitai alliance avec vos pères, le jour que je les tirai hors du pays d’Egypte, de la maison de servitude, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Dans la septième année vous renverrez chacun votre frère Hébreu, qui vous aura été vendu; il te servira six ans, puis tu le renverras libre d’avec toi; mais vos pères ne m’ont point écouté, et n’ont point incliné leur oreille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Et vous vous étiez convertis aujourd’hui, et vous aviez fait ce qui était juste devant moi, en publiant la liberté chacun à son prochain, et vous aviez traité alliance en ma présence, dans la maison sur laquelle mon Nom est réclamé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Mais vous avez changé d’avis, et avez souillé mon Nom; car vous avez fait revenir chacun son serviteur, et chacun sa servante, que vous aviez renvoyés libres pour être à eux-mêmes, et vous les avez assujettis, afin qu’ils vous soient serviteurs et servantes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'C’est pourquoi ainsi a dit l’Eternel: vous ne m’avez point écouté pour publier la liberté chacun à son frère, et chacun à son prochain; voici, je m’en vais publier, dit l’Eternel, la liberté contre vous à l’épée, à la peste, et à la famine; et je vous livrerai pour être transportés par tous les Royaumes de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Et je livrerai les hommes qui ont transgressé mon alliance, et qui n’ont point effectué les paroles de l’alliance qu’ils ont traitée devant moi, lorsqu’ils sont passés entre les deux moitiés du veau qu’ils ont coupé en deux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Les principaux de Juda, et les principaux de Jérusalem, les Eunuques, et les Sacrificateurs et tout le peuple du pays, qui ont passé entre les deux moitiés du veau;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'Je les livrerai, dis-je, entre les mains de leurs ennemis, et entre les mains de ceux qui cherchent leur vie; et leurs corps morts seront pour viande aux oiseaux des cieux, et aux bêtes de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Je livrerai aussi Sédécias Roi de Juda, et les principaux de sa Cour entre les mains de leurs ennemis, et entre les mains de ceux qui cherchent leur vie; savoir entre les mains de l’armée du Roi de Babylone, qui s’est retiré de devant vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Voici, je m’en vais leur donner ordre, dit l’Eternel, et je les ferai retourner vers cette ville-ci, et ils combattront contre elle, et la prendront, et la brûleront au feu, et je mettrai les villes de Juda en désolation, tellement qu’il n’y aura personne qui y habite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'C’est ici la parole qui fut adressée par l’Eternel à Jérémie, aux jours de Jéhojakim, fils de Josias Roi de Juda, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Va à la maison des Récabites, et leur parle, et les fais venir en la maison de l’Eternel, dans l’une des chambres, et présente-leur du vin à boire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Je pris donc Jaazanja fils de Jérémie, fils de Habatsinja, et ses frères, et tous ses fils, et toute la maison des Récabites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'Et je les fis venir dans la maison de l’Eternel, en la chambre des fils de Hanan, fils de Jigdalia, homme de Dieu, laquelle était près de la chambre des principaux; qui était sur la chambre de Mahaséja, fils de Sallum, garde des vaisseaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Et je mis devant les enfants de la maison des Récabites, des gobelets pleins de vin, et des tasses, et je leur dis: buvez du vin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Et ils répondirent: nous ne boirons point de vin; car Jéhonadab, fils de Récab notre père nous a donné un commandement, en disant: vous ne boirez point de vin, ni vous, ni vos enfants, à jamais;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'Vous ne bâtirez aucune maison, vous ne sèmerez aucune semence, vous ne planterez aucune vigne, et vous n’en aurez point; mais vous habiterez en des tentes tous les jours de votre vie, afin que vous viviez longtemps sur la terre dans laquelle vous séjournez comme étrangers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Nous avons donc obéi à la voix de Jéhonadab, fils de Récab notre père, dans toutes les choses qu’il nous a commandées, de sorte que nous n’avons point bu de vin tous les jours de notre vie, ni nous, ni nos femmes, ni nos fils, ni nos filles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'Nous n’avons bâti aucune maison pour notre demeure, et nous n’avons eu ni vigne, ni champ, ni semence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'Mais nous avons demeuré dans des tentes, et nous avons obéi, et avons fait selon toutes les choses que Jéhonadab notre père nous a commandées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Mais il est arrivé que quand Nébucadnetsar Roi de Babylone est monté au pays, nous avons dit: venez, et entrons dans Jérusalem pour fuir de devant l’armée des Caldéens, et de devant l’armée de Syrie; et nous sommes demeurés dans Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Alors la parole de l’Eternel fut adressée à Jérémie, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Ainsi a dit l’Eternel des armées, le Dieu d’Israël: va, et dis aux hommes de Juda, et aux habitants de Jérusalem: ne recevrez-vous point d’instruction pour obéir à mes paroles? dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Toutes les paroles de Jéhonadab, fils de Récab, qu’il a commandées à ses enfants de ne boire point de vin, ont été observées, et ils n’ en ont point bu jusques à ce jour; mais ils ont obéi au commandement de leur père; mais moi je vous ai parlé, me levant dès le matin, et parlant, et vous ne m’avez point obéi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Car je vous ai envoyé tous les Prophètes, mes serviteurs, me levant dès le matin, et les envoyant, pour vous dire: détournez-vous maintenant chacun de son mauvais train, et corrigez vos actions, et ne suivez point d’autres dieux pour les servir, afin que vous demeuriez en la terre que j’ai donnée à vous et à vos pères; mais vous n’avez point incliné vos oreilles, et ne m’avez point écouté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Parce que les enfants de Jéhonadab fils de Récab ont observé le commandement de leur père, lequel il leur avait fait, et que ce peuple ne m’a point écouté;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'A cause de cela l’Eternel le Dieu des armées, le Dieu d’Israël, dit ainsi: voici, je m’en vais faire venir sur Juda et sur tous les habitants de Jérusalem tout le mal que j’ai prononcé contre eux; parce que je leur ai parlé, et ils n’ont point écouté; et que je les ai appelés, et ils n’ont point répondu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Et Jérémie dit à la maison des Récabites: ainsi a dit l’Eternel des armées, le Dieu d’Israël: parce que vous avez obéi au commandement de Jéhonadab votre père, et que vous avez gardé tous ses commandements, et avez fait selon tout ce qu’il vous a commandé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'C’est pourquoi ainsi a dit l’Eternel des armées, le Dieu d’Israël: il n’arrivera jamais qu’il n’y ait quelqu’un appartenant à Jéhonadab fils de Récab, qui assiste devant moi tous les jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Or il arriva, en la quatrième année de Jéhojakim fils de Josias Roi de Juda, que cette parole fut adressée par l’Eternel à Jérémie, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Prends-toi un rouleau de livre, et y écris toutes les paroles que je t’ai dites contre Israël, et contre Juda, et contre toutes les nations, depuis le jour que je t’ai parlé, c’est-à-dire, depuis les jours de Josias, jusqu’à aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Peut-être que la maison de Juda fera attention à tout le mal que je pense de leur faire, afin que chacun se détourne de sa mauvaise voie, et que je leur pardonne leur iniquité, et leur péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Jérémie donc appela Baruc, fils de Nérija, et Baruc écrivit de la bouche de Jérémie dans le rouleau de livre toutes les paroles de l’Eternel, lesquelles il lui dicta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Puis Jérémie donna charge à Baruc, en disant: je suis retenu, et je ne puis entrer dans la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Tu y entreras donc, et tu liras dans le rouleau que tu as écrit, et que je t’ai dicté de ma bouche, les paroles de l’Eternel, le peuple l’entendant, en la maison de l’Eternel, au jour du jeûne; tu les liras, dis-je, tous ceux de Juda, qui seront venus de leurs villes, l’entendant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Peut-être que leur supplication sera reçue devant l’Eternel, et que chacun se détournera de sa mauvaise voie; car la colère et la fureur que l’Eternel a déclarée contre ce peuple est grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Baruc donc fils de Nérija fit selon tout ce que Jérémie le Prophète lui avait commandé, lisant dans le livre les paroles de l’Eternel, en la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Or il arriva en la cinquième année de Jéhojakim fils de Josias Roi de Juda, au neuvième mois, qu’on publia le jeûne en la présence de l’Eternel à tout le peuple de Jérusalem et à tout le peuple qui était venu des villes de Juda à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Et Baruc lut dans le livre les paroles de Jérémie, en la maison de l’Eternel, dans la chambre de Guémaria fils de Saphan, Secrétaire, dans le haut parvis, à l’entrée de la porte neuve de la maison de l’Eternel, tout le peuple l’entendant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Et quand Michée fils de Guémaria, fils de Saphan, eut ouï par la lecture du livre toutes les paroles de l’Eternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'Il descendit en la maison du Roi vers la chambre du Secrétaire, et voici tous les principaux y étaient assis, savoir Elisamah le Secrétaire, et Délaia fils de Sémahia, Elnathan fils de Hacbor, et Guémaria fils de Saphan, et Sédécias fils de Hanania, et tous les principaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Et Michée leur rapporta toutes les paroles qu’il avait ouïes quand Baruc lisait au livre le peuple l’entendant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'C’est pourquoi tous les principaux envoyèrent vers Baruc, Jéhudi, fils de Néthania, fils de Sélemja, fils de Cusci, pour lui dire: prends en ta main le rouleau dans lequel tu as lu, le peuple l’entendant, et viens ici. Baruch donc fils de Nérija prit le rouleau en sa main, et vint vers eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Et ils lui dirent: assieds-toi maintenant, et y lis, nous l’entendant; et Baruc lut, eux l’écoutant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Et il arriva que sitôt qu’ils eurent ouï toutes ces paroles, ils furent effrayés entre eux, et dirent à Baruc: nous ne manquerons point de rapporter au Roi toutes ces paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Et ils interrogèrent Baruc, en disant: déclare-nous maintenant comment tu as écrit toutes ces paroles-là de sa bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Et Baruc leur dit: il me dictait de sa bouche toutes ces paroles, et je les écrivais avec de l’encre dans le livre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Alors les principaux dirent à Baruc: va, et te cache, toi et Jérémie, et que personne ne sache où vous serez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Puis ils s’en allèrent vers le Roi au parvis, mais ils mirent en garde le rouleau dans la chambre d’Elisamah le Secrétaire; et ils racontèrent toutes ces paroles, le Roi l’entendant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Et le Roi envoya Jéhudi pour prendre le rouleau; et quand Jéhudi l’eut pris de la chambre d’Elisamah le Secrétaire, il le lut, le Roi et tous les principaux qui assistaient autour de lui l’entendant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Or le Roi était assis dans l’appartement d’hiver, au neuvième mois, et il y avait devant lui un brasier ardent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Et il arriva qu’aussitôt que Jéhudi en eut lu trois ou quatre pages, le Roi le coupa avec le canif du Secrétaire, et le jeta au feu du brasier, jusqu’à ce que tout le rouleau fût consumé au feu qui était dans le brasier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Et ni le Roi ni tous ses serviteurs qui entendirent toutes ces paroles n’en furent point effrayés, et ne déchirèrent point leurs vêtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Toutefois Elnathan, et Délaia, et Guémaria intercédèrent envers le Roi, afin qu’il ne brûlât point le rouleau, mais il ne les écouta point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Même le Roi commanda à Jérahméel fils de Hammélec, et à Séraja fils de Hazriel, et à Sélemja fils de Habdéel, de saisir Baruc le secrétaire, et Jérémie le Prophète; mais l’Eternel les cacha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Et la parole de l’Eternel fut adressée à Jérémie, après que le Roi eut brûlé le rouleau, et les paroles que Baruc avait écrites de la bouche de Jérémie, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Prends encore un autre rouleau, et y écris toutes les premières paroles qui étaient dans le premier rouleau que Jéhojakim Roi de Juda a brûlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Et tu diras à Jéhojakim Roi de Juda: ainsi a dit l’Eternel: tu as brûlé ce rouleau, et tu as dit: pourquoi y as-tu écrit, en disant que le Roi de Babylone viendra certainement, et qu’il ravagera ce pays, et en exterminera les hommes et les bêtes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'C’est pourquoi ainsi a dit l’Eternel touchant Jéhojakim Roi de Juda: il n’aura personne qui soit assis sur le trône de David, et son corps mort sera jeté de jour à la chaleur, et de nuit à la gelée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Je visiterai donc sur lui, et sur sa postérité, et sur ses serviteurs, leur iniquité; et je ferai venir sur eux, et sur les habitants de Jérusalem, et sur les hommes de Juda, tout le mal que je leur ai prononcé, et qu’ils n’ont point écouté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Jérémie donc prit un autre rouleau, et le donna à Baruc fils de Nérija Secrétaire, lequel y écrivit de la bouche de Jérémie toutes les paroles du livre que Jéhojakim Roi de Juda avait brûlé au feu, et plusieurs paroles semblables y furent encore ajoutées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Or le Roi Sédécias, fils de Josias, régna en la place de Chonja fils de Jéhojakim, et il fut établi pour Roi sur le pays de Juda par Nébucadnetsar Roi de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Mais il n’obéit point, ni lui, ni ses serviteurs, ni le peuple du pays, aux paroles de l’Eternel, qu’il avait prononcées par le moyen de Jérémie le Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Toutefois le Roi Sédécias envoya Jéhucal fils de Sélemja, et Sophonie fils de Mahaséja Sacrificateur, vers Jérémie le Prophète, pour lui dire: fais, je te prie, requête pour nous à l’Eternel notre Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, '(Car Jérémie allait et venait parmi le peuple, parce qu’on ne l’avait pas encore mis en prison.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Alors l’armée de Pharaon sortit d’Egypte, et quand les Caldéens, qui assiégeaient Jérusalem, en ouïrent les nouvelles, ils se retirèrent de devant Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Et la parole de l’Eternel fut adressée à Jérémie le Prophète, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'Ainsi a dit l’Eternel, le Dieu d’Israël: vous direz ainsi au Roi de Juda, qui vous a envoyés pour m’interroger: voici, l’armée de Pharaon, qui est sortie à votre secours, s’en va retourner en son pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'Et les Caldéens reviendront, et combattront contre cette ville, et la prendront, et la brûleront au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Ainsi a dit l’Eternel: ne vous abusez point vous-mêmes, en disant: les Caldéens se retireront certainement de nous; car ils ne s’en retireront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Même quand vous auriez battu toute l’armée des Caldéens qui combattent contre vous, et qu’il n’y aurait de reste entre eux que des gens percés de blessures, ils se relèveront pourtant chacun dans sa tente, et brûleront cette ville au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Or il arriva que quand l’armée des Caldéens se fut retirée de devant Jérusalem, à cause de l’armée de Pharaon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'Jérémie sortit de Jérusalem pour s’en aller au pays de Benjamin, se glissant hors de là à travers le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Mais quand il fut à la porte de Benjamin, il y avait là un capitaine de la garde, duquel le nom était Jireija, fils de Sélemja, fils de Hanania, qui saisit Jérémie le Prophète, en lui disant: Tu te vas rendre aux Caldéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Et Jérémie répondit: cela n’est point; je ne vais point me rendre aux Caldéens; mais il ne l’écouta point, et Jireija prit Jérémie, et l’amena vers les principaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Et les principaux se mirent en colère contre Jérémie, et le battirent, et le mirent en prison dans la maison de Jéhonathan le Secrétaire, car ils en avaient fait un lieu de prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Et ainsi Jérémie entra dans la fosse, et dans les cachots; et Jérémie y demeura plusieurs jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Mais le Roi Sédécias y envoya, et l’en tira, et il l’interrogea en secret dans sa maison, et lui dit: y a-t-il quelque parole de par l’Eternel? Et Jérémie répondit: il y en a; et lui dit: tu seras livré entre les mains du Roi de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Puis Jérémie dit au Roi Sédécias: quelle faute ai-je commise contre toi, et envers tes serviteurs, et envers ce peuple, pour m’avoir mis en prison?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Mais où sont vos Prophètes qui vous prophétisaient, en disant: le Roi de Babylone ne reviendra point contre vous, ni contre ce pays?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Or écoute maintenant, je te prie, ô Roi mon Seigneur! et que maintenant ma supplication soit reçue devant ta face, et ne me renvoie point dans la maison de Jéhonathan le Secrétaire, de peur que je n’y meure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'C’est pourquoi le Roi Sédécias commanda qu’on gardât Jérémie dans la cour de la prison, et qu’on lui donnât tous les jours un pain de la place des boulangers, jusqu’à ce que tout le pain de la ville fût consumé. Ainsi Jérémie demeura dans la cour de la prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Mais Séphatia fils de Mattan, et Guédalia fils de Pashur, et Jucal fils de Sélemja, et Pashur fils de Malkija, entendirent les paroles que Jérémie prononçait à tout le peuple, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Ainsi a dit l’Eternel: celui qui demeurera dans cette ville mourra par l’épée, par la famine, ou par la mortalité, mais celui qui sortira vers les Caldéens vivra, et son âme lui sera pour butin, et il vivra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Ainsi a dit l’Eternel: cette ville sera livrée certainement à l’armée du Roi de Babylone, et il la prendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Et les principaux dirent au Roi: qu’on fasse mourir cet homme; car par ce moyen il rend lâches les mains des hommes de guerre qui sont demeurés de reste dans cette ville, et les mains de tout le peuple, en leur disant de telles paroles; parce que cet homme ne cherche point la prospérité de ce peuple, mais le mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Et le Roi Sédécias dit: voici, il est entre vos mains; car le Roi ne peut rien par dessus vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Ils prirent donc Jérémie, et le jetèrent dans la fosse de Malkija, fils de Hammélec, laquelle était dans la cour de la prison, et ils descendirent Jérémie avec des cordes dans cette fosse où il n’y avait point d’eau, mais de la boue; et ainsi Jérémie enfonça dans la boue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Mais Hebed-mélec Cusien, Eunuque, qui était dans la maison du Roi, apprit qu’ils avaient mis Jérémie dans cette fosse; et le Roi était assis à la porte de Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Et Hebed-mélec sortit de la maison du Roi, et parla au Roi, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Ô Roi mon Seigneur! ces hommes-là ont mal fait dans tout ce qu’ils ont fait contre Jérémie le Prophète, en le jetant dans la fosse, car il serait déjà mort de faim dans le lieu où il était, parce qu’il n’ y a plus de pain dans la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'C’est pourquoi le Roi commanda à Hebed-mélec Cusien, en disant: prends d’ici trente hommes sous ta conduite, et fais remonter hors de la fosse Jérémie le Prophète, avant qu’il meure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Hebed-mélec donc prit ces hommes sous sa conduite, et entra dans la maison du Roi au lieu qui est sous la Trésorerie, d’où il prit de vieux lambeaux et de vieux haillons, et les descendit avec des cordes à Jérémie dans la fosse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Et Hebed-mélec Cusien dit à Jérémie: mets ces vieux lambeaux et ces haillons sous les aisselles de tes bras, au dessous des cordes; et Jérémie fit ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Ainsi ils tirèrent Jérémie dehors avec les cordes, et le firent remonter hors de la fosse; et Jérémie demeura dans la cour de la prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Et le Roi Sédécias envoya, et fit amener vers lui Jérémie le Prophète à la troisième entrée qui était dans la maison de l’Eternel. Et le Roi dit à Jérémie: je vais te demander une chose, ne m’en cèle rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Et Jérémie répondit à Sédécias: quand je te l’aurai déclarée, n’est-il pas vrai que tu me feras mourir? et quand je t’aurai donné conseil, tu ne m’écouteras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Alors le Roi Sédécias jura secrètement à Jérémie, en disant: l’Eternel est vivant, qui nous a fait cette âme-ci, que je ne te ferai point mourir, et que je ne te livrerai point entre les mains de ces gens-là qui cherchent ta vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Alors Jérémie dit à Sédécias: ainsi a dit l’Eternel, le Dieu des armées, le Dieu d’Israël: si tu sors volontairement pour aller vers les principaux du Roi de Babylone, ta vie te sera conservée, et cette ville ne sera point brûlée au feu, et tu vivras toi et ta maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Mais si tu ne sors pas vers les principaux du Roi de Babylone, cette ville sera livrée entre les mains des Caldéens, qui la brûleront au feu; et tu n’échapperas point de leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Et le Roi Sédécias dit à Jérémie: j’appréhende à cause des Juifs qui se sont rendus aux Caldéens, qu’on ne me livre entre leurs mains, et qu’ils ne se moquent de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Et Jérémie lui répondit: on ne te livrera point à eux; je te prie, écoute la voix de l’Eternel dans ce que je te dis, afin que tu t’en trouves bien, et que tu vives.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Que si tu refuses de sortir, voici ce que l’Eternel m’a fait voir,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'C’est que, voici, toutes les femmes qui sont demeurées de reste dans la maison du Roi de Juda, seront menées dehors aux principaux du Roi de Babylone, et elles diront que ceux qui ne te prédisaient que paix, t’ont incité, et t’ont gagné; tellement que tes pieds sont enfoncés dans la boue, s’étant reculés en arrière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Ils s’en vont donc mener dehors aux Caldéens toutes tes femmes et tes enfants, et tu n’échapperas point de leurs mains, mais tu seras pris, pour être livré entre les mains du Roi de Babylone, et tu seras cause que cette ville sera brûlée au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Alors Sédécias dit à Jérémie: que personne ne sache rien de ces paroles, et tu ne mourras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Et si les principaux entendent que je t’ai parlé, et qu’ils viennent vers toi, et te disent: déclare-nous maintenant ce que tu as dit au Roi, et ce que le Roi a dit, ne nous en cèle rien, et nous ne te ferons point mourir;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'Tu leur diras: j’ai présenté ma supplication devant le Roi, afin qu’il ne me fît point ramener dans la maison de Jéhonathan pour y mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Tous les principaux donc vinrent vers Jérémie, et l’interrogèrent; mais il leur fit un rapport conforme à toutes les paroles que le Roi lui avait commandé de dire; et ils cessèrent de lui parler, car on n’avait rien su de cette affaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Ainsi Jérémie demeura dans la cour de la prison, jusqu’au jour que Jérusalem fut prise, et il y était lorsque Jérusalem fut prise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'La neuvième année de Sédécias Roi de Juda, au dixième mois, Nébucadnetsar Roi de Babylone vint avec toute son armée contre Jérusalem, et ils l’assiégèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'Et la onzième année de Sédécias, au quatrième mois, le neuvième jour du mois, il y eut une brèche faite à la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'Et tous les principaux Capitaines du Roi de Babylone y entrèrent, et s’assirent à la porte du milieu, savoir Nergal- saréetser, Samgar-nebu, Sar-sekim, Rabsaris, Nergal, Saréetser, Rabmag, et tout le reste des principaux Capitaines du Roi de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Or il arriva qu’aussitôt que Sédécias Roi de Juda, et tous les hommes de guerre les eurent vus, ils s’enfuirent, et sortirent de nuit hors de la ville, par le chemin du jardin du Roi, par la porte qui était entre les deux murailles, et ils s’en allaient par le chemin de la campagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Mais l’armée des Caldéens les poursuivit, et ils atteignirent Sédécias dans les campagnes de Jérico; et l’ayant pris, ils l’amenèrent vers Nébucadnetsar Roi de Babylone à Ribla, qui est au pays de Hamath, où on lui fit son procès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Et le Roi de Babylone fit égorger à Ribla les fils de Sédécias en sa présence; le Roi de Babylone fit aussi égorger tous les magistrats de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Puis il fit crever les yeux à Sédécias, et le fit lier de doubles chaînes d’airain, pour l’emmener à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Les Caldéens brûlèrent aussi les maisons royales, et les maisons du peuple, et démolirent les murailles de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Et Nébuzar-adan, prévôt de l’hôtel, transporta à Babylone le reste du peuple qui était demeuré dans la ville, et ceux qui s’étaient allés rendre à lui, le résidu, dis-je, du peuple qui était demeuré de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Mais Nébuzar-adan, prévôt de l’hôtel, laissa d’entre le peuple les plus pauvres qui n’avaient rien dans le pays de Juda, et en ce jour- là il leur donna des vignes et des champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Or Nébucadnetsar Roi de Babylone avait donné ordre et commission à Nébuzar-adan prévôt de l’hôtel, touchant Jérémie, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Retire cet homme-là, et aie les yeux sur lui, et ne lui fais aucun mal; mais fais pour lui tout ce qu’il te dira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Nébuzar-adan donc, prévôt de l’hôtel, envoya, et aussi Nébusazban, Rabsaris, Nergal, Saréetser, Rabmag, et tous les principaux Capitaines du Roi de Babylone;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'Ils envoyèrent, dis-je, retirer Jérémie de la cour de la prison, et le donnèrent à Guédalia fils d’Ahikam, fils de Saphan, pour le conduire à la maison; ainsi il demeura parmi le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Or la parole de l’Eternel avait été adressée à Jérémie, du temps qu’il était enfermé dans la cour de la prison, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Va, et parle à Hebed-mélec Cusien, et lui dis: ainsi a dit l’Eternel des armées, le Dieu d’Israël: voici, je m’en vais faire venir mes paroles sur cette ville pour son malheur, et non point pour son bien, et elles seront accomplies ce jour-là, en ta présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Mais je te délivrerai en ce jour-là, dit l’Eternel, et tu ne seras point livré entre les mains des hommes dont tu as peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Car certainement je te délivrerai, tellement que tu ne tomberas point par l’épée; mais ta vie te sera pour butin, parce que tu as eu confiance en moi, dit 1’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'La parole qui fut adressée par l’Eternel à Jérémie, quand Nébuzar-adan prévôt de l’hôtel l’eut renvoyé de Rama, après l’avoir pris lorsqu’il était lié de chaînes parmi tous ceux qu’on transportait de Jérusalem et de Juda, et qu’on menait captifs à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Quand donc le prévôt de l’hôtel eut retiré Jérémie, il lui dit: l’Eternel ton Dieu a prononcé ce mal sur ce lieu-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'Et l’Eternel l’a fait venir, et a fait ainsi qu’il avait dit; parce que vous avez péché contre l’Eternel, et que vous n’avez point écouté sa voix, à cause de cela ceci vous est arrivé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Maintenant donc voici, aujourd’hui je t’ai délié des chaînes que tu avais aux mains, s’il te plaît de venir avec moi à Babylone, viens et je prendrai soin de toi; mais s’il ne te plaît pas de venir avec moi à Babylone, demeure; regarde, toute la terre est à ta disposition; va où il te semblera bon et convenable d’aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Or Guédalia ne retournera plus ici; retourne-t’en donc vers Guédalia fils d’Ahikam, fils de Saphan, que le Roi de Babylone a commis sur les villes de Juda; et demeure avec lui parmi le peuple, ou va partout où il te plaira d’aller; et le prévôt de l’hôtel lui donna des vivres et quelques présents, et le renvoya.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Jérémie donc alla vers Guédalia fils d’Ahikam à Mitspa, et demeura avec lui parmi le peuple qui était resté dans le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Et tous les Capitaines des gens de guerre qui étaient à la campagne, eux et leurs gens entendirent que le Roi de Babylone avait commis Guédalia fils d’Ahikam sur le pays, et qu’il lui avait commis les hommes, et les femmes, et les enfants, et cela d’entre les plus pauvres du pays, savoir de ceux qui n’avaient pas été transportés à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'Alors ils allèrent vers Guédalia à Mitspa; savoir, Ismaël fils de Néthania, et Johanan et Jonathan enfants de Karéah, et Séraja fils de Tanhumet, et les enfants de Héphai Nétophathite, et Jézania fils d’un Mahacathite, eux et leurs gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Et Guédalia fils d’Ahikam, fils de Saphan, leur jura, à eux et à leurs gens, en disant: ne faites pas difficulté d’être assujettis aux Caldéens, demeurez dans le pays, et soyez sujets du Roi de Babylone, et vous vous en trouverez bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Et pour moi, voici, je demeurerai à Mitspa pour me tenir prêt à recevoir les ordres des Caldéens qui viendront vers nous; mais vous, recueillez le vin, les fruits d’Eté, et l’huile, et mettez-les dans vos vaisseaux, et demeurez dans vos villes que vous avez prises pour votre demeure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Pareillement aussi tous les Juifs qui étaient en Moab, et parmi les enfants de Hammon, et dans l’Idumée, et dans tous ces pays-là, quand ils eurent entendu que le Roi de Babylone avait laissé quelque reste à Juda, et qu’il avait commis sur eux Guédalia fils d’Ahikam, fils de Saphan;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Tous ces Juifs-là retournèrent de tous les lieux auxquels ils avaient été chassés, et vinrent au pays de Juda, vers Guédalia à Mitspa, et recueillirent du vin, et des fruits d’Eté en grande abondance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Mais Johanan fils de Karéah, et tous les Capitaines des gens de guerre qui étaient à la campagne vinrent vers Guédalia à Mitspa;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'Et lui dirent: ne sais-tu pas certainement que Bahalis, Roi des enfants de Hammon, a envoyé Ismaël le fils de Néthania pour t’ôter la vie? mais Guédalia fils d’Ahikam ne les crut point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Et Johanan fils de Karéah parla en secret à Guédalia à Mitspa, en disant: je m’en irai maintenant, et je frapperai Ismaël fils de Néthania, sans que personne le sache; pourquoi t’ôterait-il la vie, afin que tous les Juifs qui se sont rassemblés vers toi soient dissipés, et que les restes de Juda périssent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Mais Guédalia, fils d’Ahikam, dit à Johanan fils de Karéah: ne fais point cela; car tu parles faussement d’Ismaël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Or il arriva au septième mois qu’Ismaël fils de Néthania, fils d’Elisamah, de la race royale, et l’un des principaux de chez le Roi, et dix hommes avec lui, vinrent vers Guédalia fils d’Ahikam à Mitspa, et mangèrent là du pain ensemble à Mitspa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Mais Ismaël fils de Néthania se leva, et les dix hommes qui étaient avec lui, et ils frappèrent avec l’épée Guédalia fils d’Ahikam, fils de Saphan, et on le fit mourir, lui que le Roi de Babylone avait commis sur le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Ismaël frappa aussi tous les Juifs qui étaient avec lui, c’est-à- dire, avec Guédalia à Mitspa, et les Caldéens, gens de guerre, qui furent trouvés là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Et il arriva que le jour après qu’on eut fait mourir Guédalia, avant que personne le sût,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'Quelques hommes de Sichem, de Silo, et de Samarie; en tout quatre- vingts hommes, ayant la barbe rasée, les vêtements déchirés, et s’étant fait des incisions, vinrent avec des dons et de l’encens dans leurs mains pour les apporter en la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Alors Ismaël fils de Néthania sortit de Mitspa au devant d’eux, et il marchait en pleurant, et quand il les eut rencontrés, il leur dit: venez vers Guédalia fils d’Ahikam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Mais sitôt qu’ils furent venus au milieu de la ville, Ismaël fils de Néthania, accompagné des hommes qui étaient avec lui, les égorgea, et les jeta dans une fosse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Mais il se trouva dix hommes entre eux qui dirent à Ismaël: ne nous fais point mourir, car nous avons dans les champs des amas secrets de froment, d’orge, d’huile, et de miel; et il les laissa, et ne les fit point mourir avec leurs frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Et la fosse dans laquelle Ismaël jeta les corps morts des hommes qu’il tua à l’occasion de Guédalia est celle que le Roi Asa avait fait faire lorsqu’il eut peur de Bahasa Roi d’Israël; et Ismaël fils de Néthania la remplit de gens tués.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Et Ismaël emmena prisonniers tous ceux du peuple qui étaient demeurés de reste à Mitspa, savoir les filles du Roi, et tout le peuple qui était demeuré de reste à Mitspa, que Nébuzar-adan prévôt de l’hôtel avait commis à Guédalia fils d’Ahikam; Ismaël, dis-je, fils de Néthania, les emmenait prisonniers, et s’en allait pour passer vers les enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Mais Johanan fils de Karéah, et tous les Capitaines des gens de guerre qui étaient avec lui, ayant entendu tout le mal qu’Ismaël fils de Néthania avait fait;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'Et ayant pris tous leurs gens ils s’en allèrent pour combattre contre Ismaël fils de Néthania, lequel ils rencontrèrent près des grosses eaux qui sont à Gabaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Et il arriva qu’aussitôt que tout le peuple qui était avec Ismaël eut vu Johanan fils de Karéah, et tous les Capitaines des gens de guerre qui étaient avec lui, ils s’en réjouirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Et tout le peuple qu’Ismaël emmenait prisonnier de Mitspa tourna visage, et se retournant ils s’en allèrent vers Johanan fils de Karéah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Mais Ismaël fils de Néthania échappa avec huit hommes de devant Johanan, et s’en alla vers les enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Et Johanan fils de Karéah, et tous les Capitaines des gens de guerre qui étaient avec lui prirent tout le reste du peuple qu’ils avaient retiré des mains d’Ismaël fils de Néthania, qu’il emmenait prisonnier de Mitspa, après qu’il eut frappé Guédalia fils d’Ahikam, savoir les vaillants hommes de guerre, et les femmes, et les enfants, et les Eunuques; et les ramenèrent de Gabaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Et ils s’en allèrent et demeurèrent à Guéruth-kimham, auprès de Bethléhem, pour s’en aller et se retirer en Egypte,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'A cause des Caldéens; car ils avaient peur d’eux, parce qu’Ismaël fils de Néthania avait tué Guédalia fils d’Ahikam, qui avait été commis sur le pays par le Roi de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Alors tous les Capitaines des gens de guerre, et Johanan fils de Karéah, et Jézania fils de Hosahia, et tout le peuple, depuis le plus petit jusqu’au plus grand, s’approchèrent,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'Et dirent à Jérémie le Prophète: que notre supplication soit reçue de toi, et fais requête à l’Eternel ton Dieu pour nous, savoir pour tout ce reste-ci; car de beaucoup de monde que nous étions nous sommes restés peu, comme tes yeux nous voient;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Et que l’Eternel ton Dieu nous déclare le chemin par lequel nous aurons à marcher, et ce que nous avons à faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Et Jérémie le Prophète leur répondit: J’ai entendu votre demande; voici, je m’en vais faire requête à l’Eternel votre Dieu selon vos paroles; et il arrivera que je vous déclarerai tout ce que l’Eternel vous répondra, et je ne vous en cacherai pas un mot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Et ils dirent à Jérémie: l’Eternel soit pour témoin véritable et fidèle entre nous, si nous ne faisons selon toutes les paroles, pour lesquelles l’Eternel ton Dieu t’aura envoyé vers nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Soit bien, soit mal, nous obéirons à la voix de l’Eternel notre Dieu, vers lequel nous t’envoyons; afin qu’il nous arrive du bien quand nous aurons obéi à la voix de l’Eternel notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Et il arriva au bout de dix jours que la parole de l’Eternel fut adressée à Jérémie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Et il appela Johanan fils de Karéah, et tous les Capitaines des gens de guerre qui étaient avec lui, et tout le peuple, depuis le plus petit jusqu’au plus grand;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'Et leur dit: Ainsi a dit l’Eternel, le Dieu d’Israël, vers lequel vous m’avez envoyé pour présenter votre supplication devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Si vous continuez à demeurer dans ce pays, je vous rétablirai, et je ne vous détruirai point; je vous y planterai, et je ne vous arracherai point, car je me suis repenti du mal que je vous ai fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'N’ayez point peur du Roi de Babylone, duquel vous avez peur; n’en ayez point peur, dit l’Eternel, car je suis avec vous pour vous sauver, et pour vous délivrer de sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Même je vous ferai obtenir miséricorde, tellement qu’il aura pitié de vous, et vous fera retourner en votre pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Que si vous dites: nous ne demeurerons point en ce pays, et nous n’écouterons point la voix de l’Eternel notre Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'En disant: non; mais nous irons au pays d’Egypte, afin que nous ne voyions point de guerre, et que nous n’entendions point le son de la trompette, et que nous n’ayons point disette de pain; et nous demeurerons là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'A cause de cela écoutez maintenant la parole de l’Eternel, vous les restes de Juda. Ainsi a dit l’Eternel des armées, le Dieu d’Israël: si vous vous préparez pour aller en Egypte, et que vous y entriez pour y séjourner;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'Il arrivera que l’épée dont vous avez peur vous attrapera là au pays d’Egypte; et la famine que vous craignez si fort vous suivra en Egypte, tellement que vous y mourrez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Et il arrivera que tous les hommes qui auront fait les démarches nécessaires pour entrer en Egypte afin d’y séjourner, mourront par l’épée, par la famine, et par la mortalité; nul d’eux ne restera, ni échappera de devant le mal que je m’en vais faire venir sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Car ainsi a dit l’Eternel des armées, le Dieu d’Israël: comme ma colère et ma fureur a fondu sur les habitants de Jérusalem, ainsi ma fureur fondra sur vous, quand vous serez entrés en Egypte; et vous serez en exécration, et en étonnement, et en malédiction, et en opprobre; et vous ne verrez plus ce lieu-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Vous, les restes de Juda, l’Eternel a parlé contre vous: n’entrez point en Egypte, vous sentirez certainement que je vous en ai sommés aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Car vous avez usé de fraude contre vous-mêmes quand vous m’avez envoyé vers l’Eternel votre Dieu, en me disant: fais requête pour nous envers l’Eternel notre Dieu, et nous déclare tout ce que l’Eternel notre Dieu te dira, et nous le ferons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Et je vous l’ ai déclaré aujourd’hui; mais vous n’avez point écouté la voix de l’Eternel votre Dieu, ni rien de tout ce pour quoi il m’a envoyé vers vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Maintenant donc sachez certainement que vous mourrez par l’épée, par la famine, et par la mortalité, au lieu auquel vous avez désiré d’entrer, pour y séjourner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Or il arriva qu’aussitôt que Jérémie eut achevé de prononcer à tout le peuple toutes les paroles de l’Eternel leur Dieu, pour lesquelles l’Eternel leur Dieu l’avait envoyé vers eux, savoir toutes ces choses-là;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'Hazaria fils de Hosahja, et Johanan fils de Karéah, et tous ces hommes fiers, dirent à Jérémie: tu profères des mensonges; l’Eternel notre Dieu ne t’a pas envoyé nous dire: n’entrez point en Egypte pour y séjourner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Mais Baruc fils de Nérija t’incite contre nous, afin de nous livrer entre les mains des Caldéens, pour nous faire mourir, et pour nous faire transporter à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Ainsi Johanan fils de Karéah, et tous les Capitaines des gens de guerre, et tout le peuple n’écoutèrent point la voix de l’Eternel, pour demeurer au pays de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Car Johanan fils de Karéah, et tous les Capitaines des gens de guerre prirent tout le résidu de ceux de Juda qui étaient retournés de toutes les nations, parmi lesquelles ils avaient été chassés, pour demeurer dans le pays de Juda;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'Les hommes, et les femmes, et les enfants, et les filles du Roi, et toutes les personnes que Nébuzar-adan prévôt de l’hôtel avait laissées avec Guédalia fils d’Ahikam, fils de Saphan; ils prirent aussi Jérémie le Prophète, et Baruc fils de Nérija;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'Et ils entrèrent au pays d’Egypte, car ils n’obéirent point à la voix de l’Eternel; et ils vinrent jusqu’à Taphnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Alors la parole de l’Eternel fut adressée à Jérémie dans Taphnés, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Prends en ta main de grosses pierres, et les cache dans l’argile, en la tuilerie qui est à l’entrée de la maison de Pharaon à Taphnés, les Juifs le voyant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'Et leur dis: Ainsi a dit l’Eternel des armées, le Dieu d’Israël: voici, je m’en vais mander et faire venir Nébucadnetsar Roi de Babylone mon serviteur, et je mettrai son trône sur ces pierres que j’ai cachées, et il étendra son pavillon sur elles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Et il viendra et frappera le pays d’Egypte. Ceux qui sont destinés à la mort, iront à la mort; et ceux qui sont destinés à la captivité, iront en captivité; et ceux qui sont destinés à l’épée, seront livrés à l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Et j’allumerai le feu dans les maisons des dieux d’Egypte, et Nébucadnetsar les brûlera, et il emmènera captifs ceux d’Egypte, et il se parera des richesses du pays d’Egypte, comme le pasteur s’enveloppe de son vêtement, et il en sortira en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Il brisera aussi les statues de la maison du soleil qui est au pays d’Egypte, et brûlera au feu les maisons des dieux d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'La parole qui fut adressée à Jérémie touchant tous les Juifs qui demeuraient au pays d’Egypte, et qui habitaient à Migdol, à Taphnés, à Noph, et au pays de Patros, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Ainsi a dit l’Eternel des armées, le Dieu d’Israël: vous avez vu tout le mal que j’ai fait venir sur Jérusalem, et sur toutes les villes de Juda; et voici elles sont aujourd’hui un désert, et personne n’y demeure;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'A cause des maux qu’ils ont faits pour m’irriter, en allant faire des encensements pour servir d’autres dieux, lesquels ils n’ont point connus, ni eux, ni vous, ni vos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Et je vous ai envoyé tous mes serviteurs les Prophètes, me levant dès le matin, et les envoyant pour vous dire: ne commettez point maintenant cette chose abominable, laquelle je hais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Mais ils n’ont point écouté, et n’ont point incliné leur oreille pour se détourner de leur malice, afin de ne faire point d’encensements à d’autres dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'C’est pourquoi ma fureur et ma colère s’est répandue sur eux et s’est allumée dans les villes de Juda, et dans les rues de Jérusalem, qui sont réduites en désert, et en désolation, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Maintenant donc, ainsi a dit l’Eternel, le Dieu des armées, le Dieu d’Israël: pourquoi faites-vous ce grand mal contre vous-mêmes, pour vous faire retrancher du milieu de Juda, hommes et femmes, petits enfants, et ceux qui tètent, afin qu’on ne vous laisse aucun de reste?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'En m’irritant par les oeuvres de vos mains, en faisant des encensements à d’autres dieux dans le pays d’Egypte, auquel vous venez d’entrer pour y séjourner, afin que vous soyez retranchés, et que vous soyez en malédiction et en opprobre parmi toutes les nations de la terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Avez-vous oublié les crimes de vos pères, et les crimes des Rois de Juda, et les crimes de leurs femmes, et vos propres crimes, et les crimes de vos femmes, qu’elles ont commis dans le pays de Juda, et dans les rues de Jérusalem?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Jusques à ce jour ils n’ont point été affligés, ils n’ont point eu de crainte, et ils n’ont point marché en ma Loi, ni en mes ordonnances, que je vous ai proposées, et à vos pères aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'C’est pourquoi ainsi a dit l’Eternel des armées, le Dieu d’Israël: voici, je m’en vais tourner ma face contre vous pour vous nuire, et pour retrancher tout Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Et je prendrai le reste de ceux de Juda qui se sont préparés pour entrer au pays d’Egypte, et y séjourner, et ils seront tous consumés; ils tomberont dans le pays d’Egypte, ils seront consumés par l’épée, et par la famine, depuis le plus petit jusqu’au plus grand; ils mourront par l’épée, et par la famine; et ils seront en exécration, en étonnement, en malédiction, et en opprobre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Et je punirai ceux qui demeurent au pays d’Egypte, comme j’ai puni Jérusalem, par l’épée, par la famine, et par la mortalité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'Et il n’y aura personne des restes de Juda d’entre ceux qui sont venus pour demeurer là, c’est-à-dire, au pays d’Egypte, pour retourner au pays de Juda, auquel ils se promettent de retourner pour y demeurer, qui échappe, et qui y reste; car pas un ne retournera, sinon ceux qui se seront échappés des autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Mais tous ceux qui savaient que leurs femmes faisaient des encensements à d’autres dieux, et toutes les femmes qui étaient là en grande compagnie; et tout le peuple qui demeurait dans le pays d’Egypte, à Patros, répondirent à Jérémie, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Quant à la parole que tu nous as dite au Nom de l’Eternel, nous ne t’écouterons point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'Mais nous ferons assurément tout ce qui est sorti de notre bouche en faisant des encensements à la Reine des cieux, et lui faisant des aspersions, comme nous et nos pères, nos Rois, et les principaux d’entre nous avons fait dans les villes de Juda, et dans les rues de Jérusalem, et nous avons eu alors abondamment de pain, nous avons été à notre aise, et nous n’avons point vu de mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Mais depuis le temps que nous avons cessé de faire des encensements à la Reine des cieux, et de lui faire des aspersions, nous avons eu faute de tout, et nous avons été consumés par l’épée et par la famine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Quand nous faisions des encensements à la Reine des cieux, et quand nous lui faisions des aspersions, lui avons-nous offert à l’insu de nos maris des gâteaux sur lesquels elle était représentée, ou lui avons-nous répandu des aspersions?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Alors Jérémie parla à tout le peuple, contre les hommes, et contre les femmes, et contre tout le peuple qui avait fait cette réponse, et leur dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'L’Eternel ne s’est-il pas souvenu des encensements que vous avez faits dans les villes de Juda, et dans les rues de Jérusalem, vous et vos pères, vos Rois et les principaux d’entre vous, et le peuple du pays, et son coeur n’en a-t-il pas été touché?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'En sorte que l’Eternel ne l’a pu supporter davantage, à cause de la malice de vos actions, et à cause des abominations que vous avez commises; tellement que votre pays a été réduit en désert, et en étonnement, et en malédiction, sans que personne y habite, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Parce donc que vous avez fait ces encensements, et que vous avez péché contre l’Eternel, et que vous n’avez point écouté la voix de l’Eternel, et n’avez point marché en sa Loi, ni en ses ordonnances, ni en ses témoignages, à cause de cela ce mal vous est arrivé, comme il paraît aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Puis Jérémie dit à tout le peuple, et à toutes les femmes: vous tous ceux de Juda, qui êtes au pays d’Egypte, écoutez la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Ainsi a parlé l’Eternel des armées le Dieu d’Israël, en disant: c’est vous, et vos femmes qui ont parlé par votre bouche touchant ce que vous avez accompli de vos mains, en disant: certainement nous accomplirons nos voeux que nous avons voués, en faisant des encensements à la Reine des cieux; et lui faisant des aspersions. Vous avez entièrement accompli vos voeux, et vous les avez effectués très exactement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'C’est pourquoi écoutez la parole de l’Eternel, vous tous ceux de Juda qui demeurez au pays d’Egypte: voici, j’ai juré par mon grand Nom, a dit l’Eternel, que mon Nom ne sera plus réclamé par la bouche d’aucun de Juda, qui dise en tout le pays d’Egypte: le Seigneur l’Eternel est vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Voici, je veille contre eux pour leur mal, et non pour leur bien; et tous les hommes de Juda qui sont au pays d’Egypte seront consumés par l’épée, et par la famine, jusqu’à ce qu’il n’y en ait plus aucun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Et ceux qui seront échappés de l’épée retourneront du pays d’Egypte au pays de Juda en fort petit nombre, et tout le reste de ceux de Juda qui seront entrés au pays d’Egypte pour y séjourner, saura quelle est la parole qui s’accomplira, la mienne, ou la leur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Et ceci vous sera pour signe, dit l’Eternel, que je vous punirai en ce lieu-ci, afin que vous sachiez que mes paroles seront infailliblement accomplies contre vous en mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Ainsi a dit l’Eternel: voici, je m’en vais livrer Pharaon-Hophrah Roi d’Egypte en la main de ses ennemis, et en la main de ceux qui cherchent sa vie, comme j’ai livré Sédécias Roi de Juda en la main de Nébucadnetsar Roi de Babylone son ennemi, et qui cherchait sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'La parole que Jérémie le Prophète dit à Baruc fils de Nérija, quand il écrivait dans un livre ces paroles-là, de la bouche de Jérémie, en la quatrième année de Jéhojakim fils de Josias Roi de Juda, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Ainsi a dit l’Eternel, le Dieu d’Israël, touchant toi, Baruc.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Tu as dit: malheur à moi! car l’Eternel a ajouté la tristesse à ma douleur; je me suis lassé dans mon gémissement, et je n’ai point trouvé de repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Tu lui diras ainsi: ainsi a dit l’Eternel: voici, je m’en vais détruire ce que j’ai bâti, et arracher ce que j’ai planté, savoir tout ce pays-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Et toi te chercherais-tu des grandeurs? Ne les cherche point; car voici, je m’en vais faire venir du mal sur toute chair, dit l’Eternel; mais je te donnerai ta vie pour butin, dans tous les lieux où tu iras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'La parole de l’Eternel qui fut adressée à Jérémie le Prophète contre les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'A l’égard de l’Egypte, contre l’armée de Pharaon-Neco Roi d’Egypte, qui était auprès du fleuve d’Euphrate, à Carkémis, laquelle Nébucadnetsar Roi de Babylone défit en la quatrième année de Jéhojakim, fils de Josias Roi de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Préparez le bouclier et l’écu, et approchez-vous pour la bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Attelez les chevaux, et vous cavaliers, montez; présentez-vous avec les casques, fourbissez les lances, revêtez les cuirasses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'D’où vient que je vois ceci? Ils sont effrayés; ils tournent en arrière; leurs hommes forts ont été défaits, et s’enfuient avec précipitation, sans regarder derrière eux; la frayeur les environne, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Que l’homme léger à la course ne s’enfuie point, et que le fort ne se sauve point; ils sont renversés et tombés vers l’Aquilon, auprès du rivage du fleuve d’Euphrate.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Qui est celui-ci qui s’élève comme une rivière, et duquel les eaux sont émues comme les fleuves?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'C’est l’Egypte; elle s’élève comme une rivière, et ses eaux s’émeuvent comme les fleuves; et elle dit: je m’élèverai, je couvrirai la terre, je détruirai les villes, et ceux qui y habitent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Montez chevaux, agissez en furieux, venez chariots, et que les hommes forts sortent: ceux de Cus et de Put qui manient le bouclier, et les Ludiens qui manient et bandent l’arc.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Car c’est ici la journée du Seigneur l’Eternel des armées, journée de vengeance, pour se venger de ses adversaires. L’épée dévorera, et elle sera rassasiée et enivrée de leur sang; car il y a un sacrifice au Seigneur l’Eternel des armées dans le pays de l’Aquilon, auprès du fleuve d’Euphrate.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Monte en Galaad, et prends du baume, vierge fille d’Egypte. En vain emploies-tu remède sur remède; car il n’y a point de guérison pour toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Les nations ont appris ton ignominie, et ton cri a rempli la terre; car le fort est tombé sur le fort, et ils sont tombés tous deux ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'La parole que l’Eternel prononça à Jérémie le Prophète touchant la venue de Nébucadnetsar Roi de Babylone, pour frapper le pays d’Egypte:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Faites savoir en Egypte, et publiez à Migdol, à Noph, et à Taphnés; et dites: présente-toi, et te tiens prêt; car l’épée a dévoré ce qui est autour de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Pourquoi chacun de tes vaillants hommes a-t-il été emporté? il n’a pu tenir ferme, parce que l’Eternel l’a poussé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Il en a terrassé un grand nombre, et même chacun est tombé sur son compagnon, et ils ont dit: lève-toi, retournons à notre peuple, et au pays de notre naissance, loin de l’épée de l’oppresseur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Ils ont crié là, Pharaon Roi d’Egypte n’est que bruit; il a laissé passer le temps assigné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Je suis vivant, dit le Roi dont le Nom est l’Eternel des armées, que comme Tabor est entre les montagnes, et comme Carmel est dans la mer, ainsi viendra-t-il.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Ô fille habitante de l’Egypte, équipe-toi pour déloger, car Noph sera désolée, et rendue déserte, sans qu’ il y ait plus d’habitants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'L’Egypte est une très belle génisse; mais la destruction vient, elle vient de l’Aquilon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Même les gens de guerre qu’elle entretient chez elle à ses gages, sont comme des veaux engraissés, car aussi ont-ils tourné le dos; ils s’en sont fuis ensemble, ils n’ont point tenu ferme, parce que le jour de leur calamité, le temps de leur punition est venu sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Elle sifflera comme un serpent, car ils marcheront avec une puissante armée, et ils viendront contre elle avec des cognées, comme des bûcherons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Ils couperont sa forêt, dit l’Eternel, quoiqu’on n’en pût compter les arbres; parce que leur armée sera en plus grand nombre que les sauterelles, et on ne saurait la compter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'La fille d’Egypte est rendue honteuse, elle est livrée entre les mains du peuple de l’Aquilon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'L’Eternel des armées, le Dieu d’Israël, a dit: voici, je m’en vais punir le grand peuple de No, et Pharaon, et l’Egypte, et ses dieux, et ses Rois, tant Pharaon, que ceux qui se confient en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Et je les livrerai entre les mains de ceux qui cherchent leur vie, entre les mains, dis-je, de Nébucadnetsar Roi de Babylone, et entre les mains de ses serviteurs; mais après cela elle sera habitée comme aux temps passés, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Et toi Jacob mon serviteur, ne crains point, et ne t’épouvante point, toi Israël; car voici, je m’en vais te délivrer du pays éloigné; et ta postérité, du pays de leur captivité; et Jacob retournera, et sera en repos et à son aise, et il n’y aura personne qui lui fasse peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Toi donc, Jacob mon serviteur, ne crains point, dit l’Eternel; car je suis avec toi; et même je consumerai entièrement toutes les nations parmi lesquelles je t’aurai chassé; mais je ne te consumerai point entièrement, et je te châtierai par mesure; toutefois je ne te tiendrai pas tout à fait pour innocent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'La parole de l’Eternel, qui fut adressée à Jérémie le Prophète contre les Philistins, avant que Pharaon frappât Gaza.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Ainsi a dit l’Eternel: voici des eaux qui montent de l’Aquilon; elles seront comme un torrent débordé; elles se déborderont sur la terre, et sur tout ce qui est en elle, sur la ville, et sur ses habitants; les hommes crieront, et tous les habitants du pays hurleront;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'A cause du bruit éclatant de la corne des pieds de ses puissants chevaux, à cause de l’impétuosité de ses chariots, et à cause du bruit de ses roues; les pères n’ont pas regardé les enfants, tant ils ont eu les mains lâches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'A cause du jour qui vient pour ravager tous les Philistins, et pour retrancher à Tyr et à Sidon quiconque restera pour les secourir; car l’Eternel s’en va saccager les Philistins, qui sont les restes de l’Ile de Caphtor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Gaza est devenue chauve; Askélon ne dit plus mot avec le reste de leur vallée; jusques à quand feras-tu des incisions sur toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Ha! épée de l’Eternel, jusques à quand ne te reposeras-tu point? rentre en ton fourreau, apaise-toi, et te tiens en repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Mais comment te reposerais-tu? car l’Eternel lui a donné charge, il l’a assignée contre Askélon, et contre le rivage de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Quant à Moab; ainsi a dit l’Eternel des armées, le Dieu d’Israël: malheur à Nébo, car elle a été saccagée! Kiriathajim a été rendue honteuse, et a été prise; la haute retraite a été rendue honteuse et effrayée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Moab ne se glorifiera plus de Hesbon; car on a machiné du mal contre elle, en disant: venez, et exterminons-la, et qu’elle ne soit plus nation; toi aussi Madmen tu seras détruite, et l’épée te poursuivra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Il y a un bruit de crierie de devers Horonajim, pillage et une grande défaite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Moab est brisé, on a fait ouïr le cri de ses petits enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Pleurs sur pleurs monteront par la montée de Luhith, car on entendra dans la descente de Horonajim ceux qui crieront à cause des plaies que les ennemis leur auront faites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Fuyez, dira-t-on, sauvez vos vies; et vous serez comme de la bruyère dans un désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Car parce que tu as eu confiance en tes ouvrages, et en tes trésors, tu seras prise, et Kémos sortira pour être transporté avec ses Sacrificateurs, et ses principaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Et celui qui fait le dégât entrera dans toutes les villes, et pas une ville n’échappera; la vallée périra, et le plat pays sera détruit, suivant ce que l’Eternel a dit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Donnez des ailes à Moab; car certainement il s’envolera, et ses villes seront réduites en désolation, sans qu’il y ait personne qui y habite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Maudit soit celui qui fera l’oeuvre de l’Eternel frauduleusement, et maudit soit celui qui gardera son épée de répandre le sang!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Moab a été à son aise depuis sa jeunesse; il a reposé sur sa lie; il n’a point été vidé de vaisseau en vaisseau, et n’a point été transporté, c’est pourquoi sa saveur lui est toujours demeurée, et son odeur ne s’est point changée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Mais voici, les jours viennent, dit l’Eternel, que je lui enverrai des gens qui l’enlèveront, qui videront ses vaisseaux, et qui mettront ses outres en pièces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Et Moab sera honteux à cause de Kémos, comme la maison d’Israël est devenue honteuse à cause de Béthel, qui était sa confiance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Comment dites-vous: nous sommes forts et vaillants dans le combat?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Moab va être saccagé, et chacune de ses villes s’en va en fumée, et l’élite de ses jeunes gens va descendre pour être égorgée, dit le Roi dont le Nom est l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'La calamité de Moab est proche, et sa ruine s’avance à grands pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Vous tous qui êtes autour de lui, soyez-en émus à compassion, et vous tous qui connaissez son nom, dites: comment a été rompue cette forte verge, et ce sceptre d’honneur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Toi qui te tiens chez la fille de Dibon, descends de ta gloire, et t’assieds dans un lieu de sécheresse; car celui qui a saccagé Moab est monté contre toi, et a détruit tes forteresses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Habitante d’Haroher, tiens-toi sur le chemin, et contemple; interroge celui qui s’enfuit, et celle qui est échappée, et dis: qu’est-il arrivé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Moab est rendu honteux; car il a été mis en pièces; hurlez et criez, rapportez dans Arnon que Moab a été saccagé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Et que le jugement est venu sur le plat pays, sur Holon, et sur Jathsa, et sur Mephahat,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'Et sur Dibon, et sur Nebo, et sur Bethdiblathajim,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'Et sur Kiriathajim, et sur Beth-gamul, et sur Beth-méhon,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'Et sur Kérijoth, et sur Botsra, et sur toutes les villes du pays de Moab éloignées et proches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'La force de Moab a été rompue, et son bras a été cassé, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Enivrez-le, car il s’est élevé contre l’Eternel. Moab se vautrera dans le vin qu’il aura rendu et il deviendra aussi un sujet de moquerie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Car, ô Moab! Israël ne t’a-t-il pas été en dérision, comme un homme qui aurait été surpris entre les larrons? chaque fois que tu as parlé de lui, tu en as tressailli de joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Habitants de Moab quittez les villes, et demeurez dans les rochers, et soyez comme le pigeon qui fait son nid aux côtés de l’entrée des cavernes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Nous avons appris l’orgueil de Moab le très-superbe, son arrogance et son orgueil, et sa fierté, et son coeur altier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'J’ai connu sa fureur, dit l’Eternel; mais il n’en sera pas ainsi; j’ai connu ceux sur lesquels il s’appuie; ils n’ont rien fait de droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Je hurlerai donc à cause de Moab, même je crierai à cause de Moab tout entier; on gémira sur ceux de Kir-hérès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Ô vignoble de Sibmah je pleurerai sur toi du pleur de Jahzer; tes provins ont passé au delà de la mer, ils ont atteint jusqu’à la mer de Jahzer; celui qui fait le dégât s’est jeté sur tes fruits d’Eté, et sur ta vendange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'L’allégresse aussi, et la gaieté s’est retirée loin du champ fertile, et du pays de Moab, et j’ai fait cesser le vin des cuves; on n’y foulera plus en chantant, et la chanson de la vendange n’ y sera plus chantée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'A cause du cri de Hesbon qui est parvenu jusqu’à Elhalé, ils ont jeté leurs cris jusqu’à Jahats; même depuis Tsohar jusqu’à Horonajim, comme une génisse de trois ans; car aussi les eaux de Nimrim seront réduites en désolation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Et je ferai qu’il n’y aura plus en Moab, dit l’Eternel, aucun qui offre sur les hauts lieux, ni aucun qui fasse des encensements à ses dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'C’est pourquoi mon coeur mènera un bruit sur Moab comme des flûtes; mon coeur mènera un bruit comme des flûtes sur ceux de Kir-hérès, parce que toute l’abondance de ce qu’il a acquis est périe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Car toute tête sera chauve, et toute barbe sera rasée; et il y aura des incisions sur toutes les mains, et le sac sera sur les reins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Il y aura des lamentations sur tous les toits de Moab, et dans ses places, parce que j’aurai brisé Moab comme un vaisseau auquel on ne prend nul plaisir, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Hurlez, en disant: comment a-t-il été mis en pièces? Comment Moab a-t-il tourné le dos tout honteux? car Moab sera un objet de moquerie et de frayeur à tous ceux qui sont autour de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Car ainsi a dit l’Eternel: voici il volera comme un aigle, et il étendra ses ailes sur Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Kérijoth a été prise, et on s’est saisi des forteresses, et le coeur des hommes forts de Moab sera en ce jour-là comme le coeur d’une femme qui est en travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Et Moab sera exterminé, tellement qu’il ne sera plus peuple, parce qu’il s’est élevé contre l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Habitant de Moab, la frayeur, la fosse, et le filet sont sur toi, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Celui qui s’enfuira à cause de la frayeur, tombera dans la fosse; et celui qui remontera de la fosse, sera pris au filet; car je ferai venir sur lui, c’est-à-savoir sur Moab, l’année de leur punition, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'Ils se sont arrêtés en l’ombre de Hesbon, voulant éviter la force; mais le feu est sorti de Hesbon, et la flamme du milieu de Sihon, qui dévorera un canton de Moab, et le sommet de la tête des gens bruyants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Malheur à toi, Moab! le peuple de Kémos est perdu; car tes fils ont été enlevés pour être emmenés captifs, et tes filles pour être emmenées captives.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Toutefois je ramènerai et mettrai en repos les captifs de Moab, aux derniers jours, dit l’Eternel. Jusqu’ici est le jugement de Moab.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Quant aux enfants de Hammon, ainsi a dit l’Eternel: Israël n’a-t- il point d’enfants, ou n’a-t-il point d’héritier? pourquoi donc Malcam a-t-il hérité du pays de Gad, et pourquoi son peuple demeure-t-il dans les villes de Gad?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'C’est pourquoi voici, les jours viennent, dit l’Eternel, que je ferai ouïr l’alarme dans Rabba des enfants de Hammon, et elle sera réduite en un monceau de ruines, et les villes de son ressort seront brûlées au feu, et Israël possédera ceux qui l’auront possédé, a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Hurle, ô Hesbon! car Haï a été ravagée. Villes du ressort de Rabba, criez; ceignez le sac sur vous, lamentez, courez le long des haies; car Malcam ira en captivité avec ses Sacrificateurs et ses principaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Pourquoi te glorifies-tu de tes vallées? ta vallée est écoulée, fille revêche. Elle se confiait en ses trésors, et disait: qui viendra contre moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Voici, je m’en vais faire venir de tous tes environs la frayeur sur toi, dit le Seigneur l’Eternel des armées, et vous serez chassés chacun çà et là, et il n’y aura personne qui rassemble les dispersés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Mais après cela je ferai retourner les captifs des enfants de Hammon, dit l’Etemel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Quant à Edom, ainsi a dit l’Eternel des armées: n’est-il pas vrai qu’ il n’ y a plus de sagesse dans Téman? le conseil a manqué à ses habitants, leur sagesse s’est évanouie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Fuyez, tournez le dos, vous habitants de Dédan, qui avez fait des creux pour y habiter; car j’ai fait venir sur Esaü sa calamité, le temps auquel je l’ai visité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Est-il entré chez toi des vendangeurs? ils ne t’auraient point laissé de grappillage. Sont-ce des larrons de nuit? ils auraient fait du dégât autant qu’il leur aurait suffi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Mais j’ai fouillé Esaü, j’ai découvert ses lieux secrets, tellement qu’il ne se pourra cacher; sa postérité est ravagée, ses frères aussi, et ses voisins; et ce n’est plus rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Laisse tes orphelins, et je leur donnerai de quoi vivre, et que tes veuves s’assurent sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Car ainsi a dit l’Eternel: voici, ceux qui ne devaient point boire de la coupe, en boiront certainement; et toi en serais-tu exempt en quelque manière? tu n’en seras point exempt; mais tu en boiras certainement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Car j’ai juré par moi-même, dit l’Eternel, que Botsra sera réduite en désolation, en opprobre, en désert, et en malédiction, et que toutes ses villes seront réduites en déserts perpétuels.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'J’ai ouï une publication de par l’Eternel, et il y a un ambassadeur envoyé parmi les nations, pour leur dire: assemblez- vous, et venez contre elle, et levez-vous pour combattre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Car voici, je t’avais fait petit entre les nations, et contemptible entre les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Mais ta présomption, et la fierté de ton coeur t’ont séduit, toi qui habites dans les creux des rochers, et qui occupes la hauteur des coteaux. Quand tu aurais élevé ton nid comme l’aigle, je t’en ferai descendre, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Et l’Idumée sera réduite en désolation, tellement que quiconque passera près d’elle en sera étonné, et lui insultera à cause de toutes ses plaies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Il n’y demeurera personne, a dit l’Eternel, et aucun fils d’homme n’y séjournera, comme dans la subversion de Sodome et de Gomorrhe, et de leurs lieux circonvoisins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Voici, il montera comme un lion à cause de l’enflure du Jourdain, vers la demeure du pays rude, et après l’avoir fait reposer je le ferai courir hors de l’Idumée. Et qui est d’élite, que je lui donne commission contre elle? car qui est semblable à moi? et qui me déterminera le temps? et qui sera le Pasteur qui tiendra ferme contre moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'C’est pourquoi écoutez la résolution que l’Eternel a prise contre Edom, et les desseins qu’il a formés contre les habitants de Téman; si les plus petits du troupeau ne les traînent par terre, et si l’on ne réduit en désolation leurs cabanes sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'La terre a été ébranlée du bruit de leur ruine; il y a eu un cri, le son en a été ouï en la mer Rouge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Voici, il montera comme un aigle, et il volera, et étendra ses ailes sur Botsra; et le coeur des forts d’Edom en ce jour-là sera comme le coeur d’une femme qui est en travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Quant à Damas; Hamath et Arpad ont été rendues honteuses, parce qu’elles ont appris des nouvelles très mauvaises, ils sont fondus, il y a une tourmente en la mer, elle ne se peut apaiser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damas est toute lâche, elle est mise en fuite, la peur l’a surprise, l’angoisse et les douleurs l’ont saisie comme d’une femme qui enfante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Comment n’a été réservée la ville renommée, ma ville de plaisance?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Car ses gens d’élite tomberont dans ses rues, et on fera perdre la parole à tous ses hommes de guerre en ce jour-là, dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'Et je mettrai le feu à la muraille de Damas, qui dévorera les palais de Ben-hadad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Quant à Kédar, et aux Royaumes de Hatsor, lesquels Nébucanetsar Roi de Babylone frappera, ainsi a dit l’Eternel: levez-vous, montez vers Kédar, et détruisez les enfants d’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Ils enlèveront leurs tentes et leurs troupeaux, et prendront pour eux leurs tentes, et tout leur équipage, et leurs chameaux, et on criera: frayeur tout autour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Fuyez, écartez-vous tant que vous pourrez, vous habitants de Hatsor, qui avez fait des creux pour y habiter, dit l’Eternel; car Nébucadnetsar Roi de Babylone a formé un dessein contre vous, il a pris une résolution contre vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Levez-vous, montez vers la nation qui est en repos, qui habite en assurance, dit l’Eternel; qui n’ont ni portes, ni barres, et qui habitent seuls.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Et leurs chameaux seront au pillage, et la multitude de leur bétail sera en proie; et je les disperserai à tout vent, vers ceux qui se coupent l’extrémité des cheveux, et je ferai venir de tous les côtés leur calamité, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Et Hatsor deviendra un repaire de dragons, et un désert à toujours; il n’y demeurera personne, et aucun fils d’homme n’y séjournera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'La parole de l’Eternel qui fut adressée à Jérémie le Prophète, contre Hélam, au commencement du règne de Sédécias Roi de Juda, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'Ainsi a dit l’Eternel des armées: voici, je m’en vais rompre l’arc d’Hélam, qui est leur principale force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'Et je ferai venir contre Hélam les quatre vents, des quatre bouts des cieux; et je les disperserai par tous ces vents-là; et il n’y aura point de nation chez laquelle ne viennent ceux qui seront chassés d’Hélam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Et je ferai que ceux d’Hélam seront épouvantés devant leurs ennemis, et devant ceux qui cherchent leur vie; et je ferai venir du mal sur eux, l’ardeur de ma colère, dit l’Eternel; et j’enverrai l’épée après eux, jusqu’à ce que je les aie consumés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Et je mettrai mon trône en Hélam, et j’en détruirai les Rois et les principaux, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Mais il arrivera qu’aux derniers jours je ferai retourner d’Hélam les captifs, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'La parole que l’Eternel prononça contre Babylone, et contre le pays des Caldéens, par le moyen de Jérémie le Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Faites savoir parmi les nations, et publiez-le, et levez l’enseigne; publiez-le, ne le cachez point; dites: Babylone a été prise; Bel est rendu honteux; Mérodac est brisé, ses idoles sont rendues honteuses, et leurs dieux de fiente sont brisés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Car une nation est montée contre elle de devers l’Aquilon, qui mettra son pays en désolation, et il n’y aura personne qui y habite; les hommes et les bêtes s’en sont fuis, ils s’en sont allés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'En ces jours-là, et en ce temps-là, dit l’Eternel, les enfants d’Israël viendront, eux et les enfants de Juda ensemble; ils marcheront allant et pleurant, et cherchant l’Eternel leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Ceux de Sion s’enquerront du chemin vers lequel ils devront dresser leurs faces, et ils diront: venez, et vous joignez à l’Eternel. Il y a une alliance éternelle, elle ne sera jamais mise en oubli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Mon peuple a été comme des brebis perdues; leurs pasteurs les ont fait égarer, et les ont fait errer par les montagnes; ils sont allés de montagne en colline, et ils ont mis en oubli leur gîte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Tous ceux qui les ont trouvées les ont mangées, et leurs ennemis ont dit: nous ne serons coupables d’aucun mal, parce qu’ils ont péché contre l’Eternel, contre le séjour de la justice; et l’Eternel a été l’attente de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Fuyez hors de Babylone, et sortez du pays des Caldéens, et soyez comme les boucs qui vont devant le troupeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Car voici, je m’en vais susciter et faire venir contre Babylone une assemblée de grandes nations du pays de l’Aquilon, qui se rangeront en bataille contre elle, de sorte qu’elle sera prise. Leurs flèches seront comme celles d’un homme puissant, qui ne fait que détruire, et qui ne retourne point à vide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'Et la Caldée sera abandonnée au pillage, et tous ceux qui la pilleront seront assouvis, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Parce que vous vous êtes réjouis, parce que vous vous êtes égayés, en ravageant mon héritage, parce que vous vous êtes engraissés comme une génisse qui est à l’herbe, et que vous avez henni comme de puissants chevaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Votre mère est devenue fort honteuse, et celle qui vous a enfantés a rougi; voici, elle sera toute la dernière entre les nations, elle sera un désert, un pays sec, une lande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Elle ne sera plus habitée à cause de l’indignation de l’Eternel, elle ne sera tout entière que désolation; quiconque passera près de Babylone sera étonné, et lui insultera à cause de toutes ses plaies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Rangez-vous en bataille contre Babylone, mettez-vous tout alentour; vous tous qui tendez l’arc, tirez contre elle, et n’épargnez point les traits; car elle a péché contre l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Jetez des cris de joie contre elle tout alentour; elle a tendu sa main; ses fondements sont tombés, ses murailles sont renversées; car c’est ici la vengeance de l’Eternel; vengez-vous d’elle; faites-lui comme elle a fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Retranchez de Babylone le semeur, et celui qui tient la faucille au temps de la moisson; que chacun s’en retourne vers son peuple, et que chacun s’enfuie vers son pays, à cause de l’épée de l’oppresseur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Israël est comme une brebis égarée que les lions ont effarouchée. Le Roi d’Assur l’a dévorée le premier, mais ce dernier-ci, Nébucadnetsar Roi de Babylone, lui a brisé les os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'C’est pourquoi ainsi a dit l’Eternel des armées, le Dieu d’Israël: voici, je m’en vais visiter le Roi de Babylone et son pays, comme j’ai visité le Roi d’Assyrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Et je ferai retourner Israël en ses cabanes; il paîtra en Carmel et en Basan, et son âme sera rassasiée en la montagne d’Ephraïm, et de Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'En ces jours-là, et en ce temps-là, dit l’Eternel, on cherchera l’iniquité d’Israël, mais il n’y en aura point; et les péchés de Juda, mais ils ne seront point trouvés; car je pardonnerai à ceux que j’aurai fait demeurer de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Venez contre ce pays-là, vous deux rebelles; monte contre lui, et contre les habitants destinés à la visitation; taris, et détruis à la façon de l’interdit après eux, dit l’Eternel, et fais selon toutes les choses que je t’ai commandées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'L’alarme est au pays, et une grande calamité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Comment est mis en pièces et est rompu le marteau de toute la terre! Comment Babylone est-elle réduite en sujet d’étonnement parmi les nations!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Je t’ai tendu des filets, et aussi as-tu été prise, ô Babylone! et tu n’en savais rien; tu as été trouvée, et même attrapée, parce que tu t’en es prise à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'L’Eternel a ouvert son arsenal, et en a tiré les armes de son indignation; parce que le Seigneur l’Eternel des armées a une entreprise à exécuter dans le pays des Caldéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Venez contre elle des bouts de la terre, ouvrez ses granges, foulez-la comme des javelles; détruisez-la à la façon de l’interdit, et qu’elle n’ait rien de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Coupez la gorge à tous ses veaux, et qu’ils descendent à la tuerie; malheur à eux! car le jour est venu, le temps de leur visitation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'On entend la voix de ceux qui s’enfuient, et qui sont échappés du pays de Babylone, pour annoncer dans Sion la vengeance de l’Eternel notre Dieu, la vengeance de son Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Assemblez à cri public les archers contre Babylone; vous tous qui tirez de l’arc, campez-vous contre elle tout alentour; que personne n’échappe; rendez-lui selon ses oeuvres; faites-lui selon tout ce qu’elle a fait; car elle s’est fièrement portée contre l’Eternel, contre le Saint d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'C’est pourquoi ses gens d’élite tomberont dans les places, et on fera perdre la parole à tous ses gens de guerre en ce jour-là, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Voici, j’en veux à toi, qui es la fierté même, dit le Seigneur l’Eternel des armées; car ton jour est venu, le temps auquel je te visiterai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'La fierté bronchera et tombera, et il n’y aura personne qui la relève; j’allumerai aussi le feu en ses villes, et il dévorera tous ses environs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Ainsi a dit l’Eternel des armées: les enfants d’Israël et les enfants de Juda ont été ensemble opprimés; tous ceux qui les ont pris les retiennent, et ont refusé de les laisser aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Leur Rédempteur est fort, son Nom est l’Eternel des armées; il plaidera avec chaleur leur cause, pour donner du repos au pays, et mettre dans le trouble les habitants de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'L’épée est sur les Caldéens, dit l’Eternel, et sur les habitants de Babylone, sur ses principaux, et sur ses sages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'L’épée est tirée contre ses Devins, et ils en perdront l’esprit; l’épée est sur ses hommes forts, et ils en seront épouvantés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'L’épée est sur ses chevaux, et sur ses chariots, et sur tout l’amas de diverses sortes de gens lequel est au milieu d’elle, et ils deviendront comme des femmes; l’épée est sur ses trésors, et ils seront pillés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'La sécheresse sera sur ses eaux, et elles tariront; parce que c’est un pays d’images taillées, et ils agiront en insensés à l’égard de leurs dieux qui les épouvantent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'C’est pourquoi les bêtes sauvages des déserts avec celles des Iles y habiteront, et les chats-huants y habiteront aussi; et elle ne sera plus habitée à jamais, et on n’y demeurera point en quelque temps que ce soit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Il n’y demeurera personne, a dit l’Eternel, et aucun fils d’homme n’y habitera, comme dans la subversion que Dieu a faite de Sodome et de Gomorrhe, et de leurs lieux circonvoisins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Voici, un peuple et une grande nation vient de l’Aquilon, et plusieurs Rois se réveilleront du fond de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Ils prendront l’arc et l’étendard; ils sont cruels, et ils n’auront point de compassion; leur voix bruira comme la mer, et ils seront montés sur des chevaux; chacun d’eux est rangé en homme de guerre contre toi, fille de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Le Roi de Babylone en a ouï le bruit, et ses mains en sont devenues lâches; l’angoisse l’a saisi, et un travail comme de celle qui enfante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Voici, il montera comme un lion à cause de l’enflure du Jourdain, vers la demeure du pays rude, et après que je les aurai fait reposer je les ferai courir hors de la Caldée, et qui est d’élite, que je lui donne commission contre elle? Car qui est semblable à moi? et qui me déterminera le temps? et qui sera le Pasteur qui tiendra ferme contre moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'C’est pourquoi écoutez la résolution que l’Eternel a prise contre Babylone, et les desseins qu’il a faits contre le pays des Caldéens: si les plus petits du troupeau ne les traînent par terre, et si on ne réduit en désolation leurs cabanes sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'La terre a été ébranlée du bruit de la prise de Babylone, et le cri en a été ouï parmi les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Ainsi a dit l’Eternel: voici, je m’en vais faire lever un vent de destruction contre Babylone, et contre ceux qui habitent au coeur du Royaume de ceux qui s’élèvent contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'Et j’enverrai contre Babylone des vanneurs qui la vanneront, et qui videront son pays; car de tous côtés ils seront venus contre elle au jour de son mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Qu’on bande l’arc contre celui qui bande son arc, et contre celui qui se confie en sa cuirasse; et n’épargnez point ses gens d’élite, exterminez à la façon de l’interdit toute son armée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Et les blessés à mort tomberont au pays des Caldéens; et les transpercés tomberont dans ses places;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Car Israël et Juda n’est point privé de son Dieu, de l’Eternel des armées; quoique leur pays ait été trouvé par le Saint d’Israël plein de crimes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Fuyez hors de Babylone, et sauvez chacun sa vie, ne soyez point exterminés dans son iniquité; car c’est le temps de la vengeance de l’Eternel; il lui rend ce qu’elle a mérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Babylone a été comme une coupe d’or en la main de l’Eternel, enivrant toute la terre; les nations ont bu de son vin; c’est pourquoi les nations en ont perdu l’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Babylone est tombée en un instant, et a été brisée; hurlez sur elle, prenez du baume pour sa douleur, peut-être qu’elle guérira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Nous avons traité Babylone, et elle n’est point guérie; laissez-la et allons-nous-en chacun en son pays; car son procès est parvenu jusqu’aux cieux, et s’est élevé jusqu’aux nues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'L’Eternel a mis en évidence notre justice. Venez, et racontons en Sion l’oeuvre de l’Eternel notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Fourbissez les flèches, et empoignez à pleines mains les boucliers; l’Eternel a réveillé l’esprit des Rois de Méde; car sa pensée est contre Babylone pour la détruire, parce que c’est ici la vengeance de l’Eternel, et la vengeance de son Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Elevez l’enseigne sur les murailles de Babylone, renforcez la garnison, posez les gardes, préparez des embûches; car l’Eternel a formé un dessein, même il a fait ce qu’il a dit contre les habitants de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Tu étais assise sur plusieurs eaux, abondante en trésors; ta fin est venue, et le comble de ton gain déshonnête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'L’Eternel des armées a juré par soi-même, en disant: si je ne te remplis d’hommes comme de hurebecs, et s’ils ne s’entre-répondent pour s’encourager contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'C’est lui qui a fait la terre par sa vertu, et qui a rangé le monde habitable par sa sagesse, et qui a étendu les cieux par son intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Sitôt qu’il fait ouïr sa voix il y a un grand bruit d’eaux dans les cieux; après qu’il a fait monter du bout de la terre les vapeurs, ses éclairs annoncent la pluie, et il tire le vent hors de ses trésors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Tout homme paraît abruti dans sa science; tout fondeur est rendu honteux par les images taillées; car ce qu’ils fondent est une fausseté, et il n’y a point de respiration en elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Elles ne sont que vanité, et un ouvrage propre à abuser; elles périront au temps de leur visitation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'La portion de Jacob n’est point comme ces choses-là; car c’est celui qui a tout formé, et il est le lot de son héritage; son Nom est l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Tu m’as été un marteau et des instruments de guerre; par toi j’ai mis en pièces les nations, et par toi j’ai détruit les Royaumes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Et par toi j’ai mis en pièces le cheval et celui qui le monte; et par toi j’ai mis en pièces le chariot et celui qui était monté dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Et par toi j’ai mis en pièces l’homme et la femme; et par toi j’ai mis en pièces le vieillard et le jeune garçon; et par toi j’ai mis en pièces le jeune homme et la vierge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Et par toi j’ai mis en pièces le pasteur et son troupeau; et par toi j’ai mis en pièces le laboureur et ses boeufs accouplés; et par toi j’ai mis en pièces les gouverneurs et les magistrats.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Mais je rendrai à Babylone, et à tous les habitants de la Caldée, tout le mal qu’ils ont fait à Sion, vous le voyant, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Voici, j’en veux à toi, montagne qui détruis, dit l’Eternel, qui détruis toute la terre; et j’étendrai ma main sur toi, et je te roulerai en bas du haut des rochers, et je te réduirai en montagne d’embrasement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'Et on ne pourra prendre de toi aucune pierre pour la placer à l’angle de l’édifice, ni aucune pierre pour servir de fondement, car tu seras des désolations perpétuelles, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Levez l’enseigne sur la terre, sonnez de la trompette parmi les nations; préparez les nations contre elle; convoquez contre elle les Royaumes d’Ararat, de Minni, et d’Askenas; établissez contre elle des Capitaines, faites monter ses chevaux comme le hurebec qui se hérisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Préparez contre elle les nations, les Rois de Méde, ses gouverneurs, et tous ses magistrats, et tout le pays de sa domination.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Et la terre en sera ébranlée, et en sera en travail, parce que tout ce que l’Eternel a pensé a été effectué contre Babylone, pour réduire le pays en désolation, tellement qu’il n’y ait personne qui y habite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Les hommes forts de Babylone ont cessé de combattre, ils se sont tenus dans les forteresses, leur force est éteinte, et ils sont devenus comme des femmes; on a brûlé ses demeures; et ses barres ont été rompues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Le courrier viendra à la rencontre du courrier, et le messager viendra à la rencontre du messager, pour annoncer au Roi de Babylone que sa ville est prise par un bout;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'Et que ses gués sont surpris, et que ses marais sont brûlés au feu, et que les hommes de guerre sont épouvantés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Car ainsi a dit l’Eternel des armées, le Dieu d’Israël: la fille de Babylone est comme une aire; il est temps qu’elle soit foulée; encore un peu, et le temps de sa moisson viendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Nébucadnetsar Roi de Babylone, dira Jérusalem, m’a dévorée et m’a froissée; il m’a mise dans le même état qu’un vaisseau qui ne sert de rien; il m’a engloutie comme un dragon; il a rempli son ventre de mes délices, il m’a chassée au loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Ce qu’il m’a ravi par violence, et ma chair est à Babylone, dira l’habitante de Sion; et mon sang est chez les habitants de la Caldée, dira Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'C’est pourquoi ainsi a dit l’Eternel: voici, je m’en vais plaider ta cause, et je ferai la vengeance pour toi; je dessécherai sa mer, et je ferai tarir sa source.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'Et Babylone sera réduite en monceaux, en demeure de dragons, en étonnement, et en opprobre, sans que personne y habite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Ils rugiront ensemble comme des lionceaux, et bruiront comme des faons de lions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Je les ferai échauffer dans leurs festins, et les enivrerai, afin qu’ils se réjouissent, et qu’ils dorment d’un sommeil perpétuel, et qu’ils ne se réveillent plus, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Je les ferai descendre comme des agneaux à la tuerie, et comme on y mène les moutons avec les boucs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Comment a été prise Sésac? et comment a été saisie celle qui était la louange de toute la terre? comment Babylone a-t-elle été réduite en désolation parmi les nations?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'La mer est montée sur Babylone, elle a été couverte de la multitude de ses flots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Ses villes ont été un sujet d’étonnement, une terre sèche et de landes, un pays où personne ne demeure, et où il ne passe pas un fils d’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Je punirai aussi Bel à Babylone, et je tirerai hors de sa bouche ce qu’il avait englouti, et les nations n’aborderont plus vers lui; la muraille même de Babylone est tombée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Mon peuple, sortez du milieu d’elle, et sauvez chacun sa vie de l’ardeur de la colère de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'De peur que votre coeur ne s’amollisse, et que vous n’ayez peur des nouvelles qu’on entendra dans tout le pays; car des nouvelles viendront une année, et après cela d’autres nouvelles une autre année, et il y aura violence dans la terre, et dominateur sur dominateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'C’est pourquoi voici, les jours viennent que je punirai les images taillées de Babylone, et tout son pays sera rendu honteux, et tous ses blessés à mort tomberont au milieu d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Les cieux, et la terre, et tout ce qui y est, se réjouiront avec chant de triomphe contre Babylone, parce qu’il viendra de l’Aquilon des destructeurs contre elle, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Et comme Babylone a fait tomber les blessés à mort d’Israël, ainsi les blessés à mort de tout le pays tomberont à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Vous qui êtes échappés de l’épée, marchez, ne vous arrêtez point; souvenez-vous de l’Eternel dans ces pays éloignés où vous êtes, et que Jérusalem vous revienne au coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Mais vous direz: nous sommes honteux des reproches que nous avons entendus; la confusion a couvert nos faces, en ce que les étrangers sont venus contre les Sanctuaires de la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'C’est pourquoi voici, les jours viennent, dit l’Eternel, que je ferai justice de ses images taillées, et les blessés à mort gémiront par tout son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Quand Babylone serait montée jusqu’aux cieux, et qu’elle aurait fortifié le plus haut de sa forteresse, toutefois les destructeurs y entreront de par moi, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Un grand cri s’entend de Babylone, et un grand débris du pays des Caldéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Parce que l’Eternel s’en va détruire Babylone, et il abolira du milieu d’elle la voix magnifique, et leurs flots bruiront comme de grosses eaux, l’éclat de leur bruit retentira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Car le destructeur est venu contre elle, contre Babylone; ses hommes forts ont été pris, et leurs arcs ont été brisés; car le Dieu Fort des rétributions, l’Eternel, ne manque jamais à rendre la pareille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'J’enivrerai donc ses principaux et ses sages, ses gouverneurs et ses magistrats, et ses hommes forts; ils dormiront d’un sommeil perpétuel, et ils ne se réveilleront plus, dit le Roi dont le Nom est l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Ainsi a dit l’Eternel des armées: Il n’y aura aucune muraille de Babylone, quelque large qu’elle soit, qui ne soit entièrement rasée; et ses portes, qui sont si hautes, seront brûlées au feu; ainsi les peuples auront travaillé inutilement, et les nations pour le feu, et elles s’y seront lassées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'C’est ici l’ordre que Jérémie le Prophète donna à Séraja, fils de Nérija, fils de Mahaséja, quand il alla de la part de Sédécias Roi de Juda en Babylone, la quatrième année de son Règne; or Séraja était principal Chambellan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Car Jérémie écrivit dans un livre tout le mal qui devait venir sur Babylone; savoir toutes ces paroles qui sont écrites contre Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Jérémie donc dit à Séraja: Sitôt que tu seras venu à Babylone, et que tu l’auras vue, tu liras toutes ces paroles-là;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'Et tu diras: Eternel, tu as parlé contre ce lieu-ci pour l’exterminer, en sorte qu’il n’y ait aucun habitant, depuis l’homme jusqu’à la bête, mais qu’il soit réduit en désolations perpétuelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Et sitôt que tu auras achevé de lire ce livre, tu le lieras à une pierre, et le jetteras dans l’Euphrate;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'Et tu diras: Babylone sera ainsi plongée, et elle ne se relèvera point du mal que je m’en vais faire venir sur elle, et ils en seront accablés. Jusques ici sont les paroles de Jérémie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Sédécias était âgé de vingt-et-un ans quand il commença à régner, et il régna onze ans à Jérusalem, sa mère avait nom Hamutal, et elle était fille de Jérémie de Libna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Il fit ce qui déplaît à l’Eternel, comme avait fait Jéhojakim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Car il arriva à cause de la colère de l’Eternel contre Jérusalem et Juda, jusqu’à les rejeter de devant soi, que Sédécias se rebella contre le Roi de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Il arriva donc l’an neuvième de son Règne; le dixième jour du dixième mois, que Nébucadnetsar Roi de Babylone vint contre Jérusalem, lui et toute son armée, et ils se campèrent contre elle, et firent des terrasses tout alentour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Et la ville fut assiégée jusqu’à l’onzième année du Roi Sédécias.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Et le neuvième jour du quatrième mois la famine se renforça dans la ville, tellement qu’il n’y avait point de pain pour le peuple du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Alors la brèche fut faite à la ville, et tous les gens de guerre s’enfuirent, et sortirent de nuit hors de la ville, par le chemin de la porte entre les deux murailles, qui était près du jardin du Roi (or les Caldéens étaient tout autour de la ville) et s’en allèrent par le chemin de la campagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Mais l’armée des Caldéens poursuivit le Roi, et quand ils eurent atteint Sédécias dans les campagnes de Jéricho toute son armée se dispersa d’avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Ils prirent donc le Roi, et le firent monter vers le Roi de Babylone à Riblatha au pays de Hamath, où on lui fit son procès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Et le Roi de Babylone fit égorger les fils de Sédécias en sa présence; il fit égorger aussi tous les principaux de Juda à Riblatha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Puis il fit crever les yeux à Sédécias, et le fit lier de doubles chaînes d’airain, et le Roi de Babylone le mena à Babylone, et le mit en prison jusqu’au jour de sa mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Et au dixième jour du cinquième mois, en l’an dix-neuvième de Nébucadnetsar Roi de Babylone, Nébuzar-adan, prévôt de l’hôtel, serviteur ordinaire du Roi de Babylone, entra dans Jérusalem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'Et brûla la maison de l’Eternel, et la maison Royale, et toutes les maisons de Jérusalem, et mit le feu dans toutes les maisons des Grands.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Et toute l’armée des Caldéens, qui était avec le prévôt de l’hôtel, démolit toutes les murailles qui étaient autour de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Et Nébuzar-adan, prévôt de l’hôtel, transporta à Babylone des plus pauvres du peuple, le reste du peuple, savoir ceux qui étaient demeurés de reste dans la ville, et ceux qui étaient allés rendre au Roi de Babylone, avec le reste de la multitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Toutefois Nébuzar-adan, prévôt de l’hôlel, laissa quelques-uns des plus pauvres du pays pour être vignerons et laboureurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Et les Caldéens mirent en pièces les colonnes d’airain qui étaient dans la maison de l’Eternel, avec les soubassements; et la mer d’airain qui était dans la maison de l’Eternel, et en emportèrent tout l’airain à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Ils emportèrent aussi les chaudrons, et les racloirs, et les serpes, et les bassins, et les tasses, et tous les ustensiles d’airain dont on faisait le service.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Le prévôt de l’hôtel emporta aussi les coupes, et les encensoirs, et les bassins, et les chaudrons, et les chandeliers, et les tasses, et les gobelets; ce qui était d’or, et ce qui était d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Quant aux deux colonnes, à la mer, et aux douze boeufs d’airain qui servaient de soubassements, lesquels le Roi Salomon avait faits pour la maison de l’Eternel, on ne pesa point l’airain de tous ces vaisseaux-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Or quant aux colonnes chaque colonne avait dix-huit coudées de haut, et un cordon de douze coudées l’environnait; et elle était épaisse de quatre doigts, et était creuse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'et il y avait par-dessus un chapiteau d’airain; et la hauteur d’un des chapiteaux était de cinq coudées, il y avait aussi un rets et des grenades tout autour du chapiteau, le tout d’airain; et la seconde colonne était de même façon, et aussi les grenades.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'Il y avait aussi quatre-vingt-seize grenades au côté, et les grenades qui étaient sur le rets à l’entour, étaient cent en tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Davantage le prévôt de l’hôtel emmena Séraja, qui était le premier Sacrificateur, et Sophonie, qui était le second Sacrificateur, et les trois gardes des vaisseaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'Il emmena aussi de la ville un Eunuque qui avait la charge des hommes de guerre, et sept hommes de ceux qui étaient près de la personne du Roi, lesquels furent trouvés dans la ville; et le Secrétaire du Capitaine de l’armée qui enrôlait le peuple du pays; et soixante hommes d’entre le peuple du pays, qui furent trouvés dans la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Nébuzar-adan donc, prévôt de l’hôtel, les prit, et les emmena vers le Roi de Babylone à Ribla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Et le Roi de Babylone les frappa, et les fit mourir à Ribla au pays de Hamath. Ainsi Juda fut transporté hors de sa terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Et c’est ici le peuple que Nébucadnetsar transporta; la septième année, trois mille vingt-trois Juifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'La dix-huitième année de Nébucadnetsar, on transporta de Jérusalem huit cent trente-deux personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'La vingt-troisième année de Nébucadnetsar, Nébuzar-adan, prévôt de l’hôtel, transporta sept cent quarante-cinq personnes des Juifs; toutes les personnes donc furent quatre mille six cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Or il arriva l’an trente-septième de la captivité de Jéhojachin, Roi de Juda, au vingt-cinquième jour du douzième mois, qu’Evilmérodac, Roi de Babylone, l’année qu’il commença à régner, tira de prison Jéhojachin Roi de Juda, et le mit en liberté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Et lui parla avec bonté, et mit son trône au dessus du trône des autres Rois qui étaient avec lui à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Et après qu’il lui eut changé ses vêtements de prison, il mangea du pain ordinairement tous les jours de sa vie en la présence du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Et quant à son ordinaire, un ordinaire continuel lui fut établi de par le Roi de Babylone pour chaque jour, jusques au jour de sa mort, tout le temps de sa vie. ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Comment est-il arrivé que la ville si peuplée se trouve si solitaire? que celle qui était grande entre les nations est devenue comme veuve? que celle qui était Dame entre les Provinces a été rendue tributaire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Elle ne cesse de pleurer pendant la nuit, et ses larmes sont sur ses joues; il n’y a pas un de tous ses amis qui la console; ses intimes amis ont agi perfidement contre elle, ils sont devenus ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'La Judée a été emmenée captive tant elle est affligée, et tant est grande sa servitude; elle demeure maintenant entre les nations, et ne trouve point de repos; tous ses persécuteurs l’ont attrapée entre ses détroits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Les chemins de Sion mènent deuil de ce qu’il n’y a plus personne qui vienne aux fêtes solennelles; toutes ses portes sont désolées, ses Sacrificateurs sanglotent, ses vierges sont accablées de tristesse; elle est remplie d’amertume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Ses adversaires ont été établis pour chefs, ses ennemis ont prospéré; car l’Eternel l’a plongée dans l’affliction à cause de la multitude de ses crimes, ses petits enfants ont marché captifs devant l’adversaire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Et tout l’honneur de la fille de Sion s’est retiré d’elle; ses principaux sont devenus semblables à des cerfs qui ne trouvent point de pâture, et ils ont marché destitués de force, devant celui qui les poursuivait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Jérusalem dans les jours de son affliction et de son pauvre état s’est souvenue de toutes ses choses désirables qu’elle avait depuis si longtemps, lorsque son peuple est tombé par la main de l’ennemi, sans qu’aucun la secourût; les ennemis l’ont vue, et se sont moqués de ses sabbats.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jérusalem a grièvement péché; c’est pourquoi on a branlé la tête contre elle; tous ceux qui l’honoraient l’ont méprisée, parce qu’ils ont vu son ignominie; elle en a aussi sangloté, et s’est retournée en arrière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Sa souillure était dans les pans de sa robe, et elle ne s’est point souvenue de sa fin; elle a été extraordinairement abaissée, et elle n’a point de consolateur. Regarde, ô Eternel! mon affliction, car l’ennemi s’est élevé avec orgueil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'L’ennemi a étendu sa main sur toutes ses choses désirables; car elle a vu entrer dans son Sanctuaire les nations au sujet desquelles tu avais donné cet ordre: Elles n’entreront point dans ton assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Tout son peuple sanglote, cherchant du pain; ils ont donné leurs choses désirables pour des aliments, afin de se faire revenir le coeur; regarde, ô Eternel! et contemple; car je suis devenue méprisée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Cela ne vous touche-t-il point? Vous tous passants, contemplez, et voyez s’il y a une douleur, comme ma douleur, qui m’a été faite, à moi que l’Eternel a accablée de douleur au jour de l’ardeur de sa colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Il a envoyé d’en haut le feu dans mes os, lequel les a tous gagnés; il a tendu un rets à mes pieds, et m’a fait aller en arrière; il m’a rendue désolée et languissante pendant tout le jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Le joug de mes iniquités est tenu serré par sa main; ils sont entortillés, et appliqués sur mon cou; il a fait déchoir ma force; le Seigneur m’a livrée entre les mains de ceux dont je ne pourrai point me relever.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Le Seigneur a abattu tous les hommes forts que j’avais au milieu de moi; il a appelé contre moi ses gens assignés, pour mettre en pièces mes gens d’élite. Le Seigneur a tiré le pressoir sur la vierge de la fille de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'A cause de ces choses je pleure, et mon oeil, mon oeil se fond en eau; car le consolateur qui me faisait revenir le coeur est loin de moi; mes enfants sont désolés, parce que l’ennemi a été le plus fort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Sion se déchire de ses mains, et personne ne la console; l’Eternel a mandé contre Jacob ses ennemis à l’entour de lui; Jérusalem est devenue entre eux, comme une femme séparée à cause de sa souillure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'L’Eternel est juste, car je me suis rebellée contre son commandement. Ecoutez, je vous prie, vous tous peuples, et regardez ma douleur; mes vierges et mes gens d’élite sont allés en captivité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'J’ai appelé mes amis, mais ils m’ont trompée. Mes Sacrificateurs, et mes Anciens sont morts dans la ville; car ils ont cherché à manger pour eux, afin de se faire revenir le coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Regarde, ô Eternel! car je suis dans la détresse; mes entrailles bruient, mon coeur palpite au dedans de moi, parce que je n’ai fait qu’être rebelle; au dehors l’épée m’a privée d’enfants; au dedans il y a comme la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'On m’a ouïe sangloter, et je n’ai personne qui me console; tous mes ennemis ont appris mon malheur, et s’en sont réjouis, parce que tu l’as fait; tu amèneras le jour que tu as assigné, et ils seront dans mon état.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Que toute leur malice vienne en ta présence, et fais-leur comme tu m’as fait à cause de tous mes péchés; car mes sanglots sont en grand nombre, et mon coeur est languissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Comment est-il arrivé que le Seigneur a couvert de sa colère la fille de Sion tout à l’entour, comme d’une nuée, et qu’il a jeté des cieux en terre l’ornement d’Israël, et ne s’est point souvenu au jour de sa colère du marchepied de ses pieds?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Le Seigneur a abîmé, et n’a point épargné toutes les habitations de Jacob, il a ruiné par sa fureur les forteresses de la fille de Juda, et l’a jetée par terre; il a profané le Royaume et ses principaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Il a retranché toute la force d’Israël par l’ardeur de sa colère; il a retiré sa dextre en arrière de devant l’ennemi; il s’est allumé dans Jacob comme un feu flamboyant, qui l’a consumé tout à l’environ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Il a tendu son arc comme un ennemi; sa dextre y a été appliquée comme celle d’un adversaire; et il a tué tout ce qui était agréable à l’oeil dans le tabernacle de la fille de Sion; il a répandu sa fureur comme un feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Le Seigneur a été comme un ennemi; il a abîmé Israël, il a abîmé tous ses palais, il a dissipé toutes ses forteresses, et il a multiplié dans la fille de Juda le deuil et l’affliction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Il a mis en pièces avec violence son domicile, comme la cabane d’un jardin; il a détruit le lieu de son Assemblée; l’Eternel a fait oublier dans Sion la fête solennelle et le Sabbat, et il a rejeté dans l’indignation de sa colère le Roi et le Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Le Seigneur a rejeté au loin son autel, il a détruit son Sanctuaire; il a livré en la main de l’ennemi les murailles de ses palais; ils ont jeté leurs cris dans la maison de l’Eternel comme aux jours des fêtes solennelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'L’Eternel s’est proposé de détruire la muraille de la fille de Sion; il y a étendu le cordeau, et il n’a point retenu sa main qu’il ne l’ait abîmée; et il a rendu désolé l’avant-mur, et la muraille, ils ont été détruits tous ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Ses portes sont enfoncées en terre, il a détruit et brisé ses barres; son Roi et ses principaux sont parmi les nations; la Loi n’ est plus, même ses Prophètes n’ont trouvé aucune vision de par l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Les Anciens de la fille de Sion sont assis à terre, et se taisent; ils ont mis de la poudre sur leur tête, ils se sont ceints de sacs; les vierges de Jérusalem baissent leurs têtes vers la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Mes yeux sont consumés à force de larmes, mes entrailles bruient, mon foie s’est répandu en terre, à cause de la plaie de la fille de mon peuple, parce que les petits enfants et ceux qui têtaient sont pâmés dans les places de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Ils ont dit à leurs mères: où est le froment et le vin? lorsqu’ils tombaient en faiblesse dans les places de la ville, comme un homme blessé à mort, et qu’ils rendaient l’esprit au sein de leurs mères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Mem Qui prendrai-je à témoin envers toi? Qui comparerai-je avec toi, fille de Jérusalem, et qui est-ce que je t’égalerai, afin que je te console, vierge fille de Sion; car ta plaie est grande comme une mer? Qui est celui qui te guérira?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Tes Prophètes t’ont prévu des choses vaines et frivoles, et ils n’ont point découvert ton iniquité pour détourner ta captivité; mais ils t’ont prévu des charges vaines, et propres à te faire chasser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Tous les passants ont battu des mains sur toi, ils se sont moqués, et ils ont branlé leur tête contre la fille de Jérusalem, en disant: est-ce ici la ville de laquelle on disait: la parfaite en beauté; la joie de toute la terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Tous tes ennemis ont ouvert leur bouche sur toi, ils se sont moqués, ils ont grincé les dents, et ils ont dit: nous les avons abîmés; vraiment c’est ici la journée que nous attendions, nous l’ avons trouvée, nous l’avons vue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'L’Eternel a fait ce qu’il avait projeté, il a accompli sa parole qu’il avait ordonnée depuis longtemps; il a ruiné et n’a point épargné, il a réjoui sur toi l’ennemi, il a fait éclater la force de tes adversaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Leur coeur a crié au Seigneur. Muraille de la fille de Sion, fais couler des larmes jour et nuit, comme un torrent; ne te donne point de repos; et que la prunelle de tes yeux ne cesse point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Lève-toi et t’écrie de nuit sur le commencement des veilles; répands ton coeur comme de l’eau en la présence du Seigneur; lève tes mains vers lui, pour l’âme de tes petits enfants qui pâment de faim aux coins de toutes les rues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Regarde, ô Eternel! et considère à qui tu as ainsi fait. Les femmes n’ont-elles pas mangé leur fruit, les petits enfants qu’elles emmaillottaient? Le Sacrificateur et le Prophète n’ont-ils pas été tués dans le Sanctuaire du Seigneur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Le jeune enfant et le vieillard ont été gisants à terre par les rues; mes vierges et mes gens d’élite sont tombés par l’épée; tu as tué au jour de ta colère, tu as massacré, tu n’as point épargné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Tu as convié comme à un jour solennel mes frayeurs d’alentour, et nul n’est échappé, ni demeuré de reste au jour de la colère de l’Eternel; ceux que j’avais emmaillottés et élevés, mon ennemi les a consumés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Je suis l’homme qui ai vu l’affliction par la verge de sa fureur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Il m’a conduit et amené dans les ténèbres, et non dans la lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Certes il s’est tourné contre moi, il a tous les jours tourné sa main contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Il a fait vieillir ma chair et ma peau, il a brisé mes os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Il a bâti contre moi, et m’a environné de fiel et de travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Il m’a fait tenir dans des lieux ténébreux, comme ceux qui sont morts dès longtemps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Il a fait une cloison autour de moi, afin que je ne sorte point; il a appesanti mes fers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Même quand je crie et que j’élève ma voix, il rejette ma requête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Il a fait un mur de pierres de taille pour fermer mes chemins, il a renversé mes sentiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Ce m’est un ours qui est aux embûches, et un lion qui se tient dans un lieu caché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Il a détourné mes chemins, et m’a mis en pièces, il m’a rendu désolé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Il a tendu son arc, et m’a mis comme une butte pour la flèche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Il a fait entrer dans mes reins les flèches dont son carquois est plein.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'J’ai été en risée à tous les peuples, et leur chanson, tout le jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Il m’a rassasié d’amertume, il m’a enivré d’absinthe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Il m’a cassé les dents avec du gravier, il m’a couvert de cendre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Tellement que la paix s’est éloignée de mon âme; j’ai oublié ce que c’est que d’être à son aise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Et j’ai dit: ma force est perdue, et mon espérance aussi que j’avais en l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Souviens-toi de mon affliction, et de mon pauvre état, qui n’est qu’absinthe et que fiel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Mon âme s’ en souvient sans cesse, et elle est abattue au dedans de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Mais je rappellerai ceci en mon coeur, et c’est pourquoi j’aurai espérance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Ce sont les gratuités de l’Eternel que nous n’avons point été consumés, parce que ses compassions ne sont point taries.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Elles se renouvellent chaque matin; c’est une chose grande que ta fidélité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'L’Eternel est ma portion, dit mon âme, c’est pourquoi j’aurai espérance en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'L’Eternel est bon à ceux qui s’attendent à lui, et à l’âme qui le recherche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'C’est une chose bonne qu’on attende, même en se tenant en repos, la délivrance de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'C’est une chose bonne à l’homme de porter le joug en sa jeunesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Il est assis solitaire et se tient tranquille, parce qu’on l’a chargé sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Il met sa bouche dans la poussière, si peut-être il y aura quelque espérance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Il présente la joue à celui qui le frappe; il est accablé d’opprobre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Car le Seigneur ne rejette point à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'Mais s’il afflige quelqu’un, il en a aussi compassion selon la grandeur de ses gratuités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Car ce n’est pas volontiers qu’il afflige et contriste les fils des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Lorsqu’on foule sous ses pieds tous les prisonniers du monde;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'Lorsqu’on pervertit le droit de quelqu’un en la présence du Très- haut;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'Lorsqu’on fait tort à quelqu’un dans son procès, le Seigneur ne le voit-il point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Qui est-ce qui dit que cela a été fait, et que le Seigneur ne l’ a point commandé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Les maux, et les biens ne procèdent-ils point de l’ordre du Très- haut?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Pourquoi se dépiterait l’homme vivant, l’homme, dis-je, à cause de ses péchés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Recherchons nos voies, et les sondons, et retournons jusqu’à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Levons nos coeurs et nos mains au Dieu Fort qui est aux cieux, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Nous avons péché, nous avons été rebelles, tu n’as point pardonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Tu nous as couverts de ta colère, et nous as poursuivis, tu as tué, tu n’as point épargné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Tu t’es couvert d’une nuée, afin que la requête ne passât point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Tu nous as fait être la raclure et le rebut au milieu des peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Tous nos ennemis ont ouvert leur bouche sur nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'La frayeur et la fosse, le dégât et la calamité nous sont arrivés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Mon oeil s’est fondu en ruisseaux d’eaux à cause de la plaie de la fille de mon peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Mon oeil verse des larmes, et ne cesse point, parce qu’il n’y a aucun relâche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'Jusques à ce que l’Eternel regarde et voie des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Mon oeil afflige mon âme à cause de toutes les filles de ma ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Ceux qui me sont ennemis sans cause m’ont poursuivi à outrance, comme on chasse après l’oiseau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Ils ont enserré ma vie dans une fosse, et ont roulé une pierre sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Les eaux ont regorgé par-dessus ma tête; je disais: je suis retranché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'J’ai invoqué ton Nom, ô Eternel! d’une des plus basses fosses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Tu as ouï ma voix, ne ferme point ton oreille, afin que je n’expire point à force de crier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Tu t’es approché au jour que je t’ai invoqué, et tu as dit: ne crains rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Ô Seigneur! tu as plaidé la cause de mon âme; et tu as garanti ma vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Tu as vu, ô Eternel! le tort qu’on me fait, fais-moi droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Tu as vu toutes les vengeances dont ils ont usé, et toutes leurs machinations contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Tu as ouï, ô Eternel! leur opprobe et toutes leurs machinations contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'Les discours de ceux qui s’élèvent contre moi, et leur dessein qu’ils ont contre moi tout le long du jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Considère quand ils s’asseyent, et quand ils se lèvent, car je suis leur chanson.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Rends-leur la pareille, ô Eternel! selon l’ouvrage de leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Donne-leur un tel ennui qu’il leur couvre le coeur; donne-leur ta malédiction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Poursuis-les en ta colère, et les efface de dessous les cieux de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Comment l’or est-il devenu obscur, et le fin or s’est-il changé? Comment les pierres du Sanctuaire sont-elles semées aux coins de toutes les rues?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Comment les chers enfants de Sion, qui étaient estimés comme le meilleur or, sont-ils réputés comme des vases de terre qui ne sont que l’ouvrage de la main d’un potier?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Il y a même des monstres marins qui présentent leurs mammelles et qui allaitent leurs petits; mais la fille de mon peuple a à faire à des gens cruels, comme les chats-huants qui sont au désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'La langue de celui qui têtait s’est attachée à son palais dans sa soif; les petits enfants ont demandé du pain, et personne ne leur en a rompu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Ceux qui mangeaient des viandes délicates sont demeurés désolés dans les rues; et ceux qui étaient nourris sur l’écarlate ont embrassé l’ordure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Et la peine de l’iniquité de la fille de mon peuple est plus grande, que la peine du péché de Sodome, qui a été renversée comme en un moment, et à laquelle les mains ne sont point lassées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Ses hommes honorables étaient plus nets que la neige, plus blancs que le lait; leur teint était plus vermeil que les pierres précieuses, et ils étaient polis comme un saphir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Leur visage est plus noir que les ténèbres, on ne les connaît point par les rues; leur peau tient à leurs os; elle est devenue sèche comme du bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Ceux qui ont été mis à mort par l’épée, ont été plus heureux que ceux qui sont morts par la famine; à cause que ceux-ci se sont consumés peu à peu, étant transpercés par le défaut du revenu des champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Les mains des femmes, naturellement tendres, ont cuit leurs enfants, et ils leur ont été pour viande dans le temps de la calamité de la fille de mon peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'L’Eternel a accompli sa fureur, il a répandu l’ardeur de sa colère, et a allumé dans Sion le feu qui a dévoré ses fondements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Les Rois de la terre, et tous les habitants de la terre habitable n’eussent jamais cru que l’adversaire et l’ennemi fût entré dans les portes de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Cela est arrivé à cause des péchés de ses prophètes, et des iniquités de ses Sacrificateurs, qui répandaient le sang des justes au milieu d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Les aveugles ont erré ça et là par les rues, et on était tellement souillé de sang, qu’ils ne pouvaient trouver à qui ils touchassent la robe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'On leur criait: retirez-vous, souillé, retirez-vous, retirez-vous, n’ y touchez point. Certes ils s’en sont envolés, et ils ont été transportés ça et là; on a dit parmi les nations, ils n’y retourneront plus pour y séjourner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'La face de l’Eternel les a écartés, il ne continuera plus de les regarder. Ils n’ont point eu de respect pour la personne des Sacrificateurs, ni pitié des vieillards.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Jusqu’ici nos yeux se sont consumés après notre aide de néant; nous avons regardé de dessus nos lieux élevés vers une nation qui ne peut pas délivrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Ils ont épié nos pas, afin que nous ne marchassions point par nos places; notre fin est approchée, nos jours sont accomplis; notre fin, dis-je, est venue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Nos persécuteurs ont été plus légers que les aigles des cieux; ils nous ont poursuivis sur les montagnes, ils ont mis des embûches contre nous au désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Le souffle de nos narines, l’Oint de l’Eternel, a été pris dans leurs fosses, celui duquel nous disions: nous vivrons parmi les nations sous son ombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Réjouis-toi, et sois dans l’allégresse, fille d’Edom, qui demeures au pays de Huts; la coupe passera aussi vers toi, tu en seras enivrée, et tu t’en découvriras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Fille de Sion, la peine de ton iniquité est accomplie, il ne te transportera plus; mais il visitera ton iniquité, ô fille d’Edom! il découvrira tes péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Souviens-toi, ô Eternel! de ce qui nous est arrivé; regarde et vois notre opprobre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Notre héritage a été renversé par des étrangers, nos maisons par des forains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Nous sommes devenus comme des orphelins qui sont sans pères, et nos mères sont comme des veuves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Nous avons bu notre eau pour de l’argent, et notre bois nous a été mis à prix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Nous avons été poursuivis l’épée sur la gorge. Nous nous sommes donnés beaucoup de mouvement, et nous n’avons point eu de repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Nous avons étendu la main aux Egyptiens et aux Assyriens pour avoir suffisamment de pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Nos pères ont péché, et ne sont plus; et nous avons porté leurs iniquités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Les esclaves ont dominé sur nous, et personne ne nous a délivrés de leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Nous amenions notre pain au péril de notre vie, à cause de l’épée du désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Notre peau a été noircie comme un four, à cause de l’ardeur véhémente de la faim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Ils ont humilié les femmes dans Sion, et les vierges dans les villes de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Les principaux ont été pendus par leur main; et on n’a porté aucun respect à la personne des Anciens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Ils ont pris les jeunes gens pour moudre, et les enfants sont tombés sous le bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Les Anciens ont cessé de se trouver aux portes, et les jeunes gens de chanter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'La joie de notre coeur est cessée, et notre danse est tournée en deuil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'La couronne de notre tête est tombée. Malheur maintenant à nous parce que nous avons péché!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'C’est pourquoi notre coeur est languissant. A cause de ces choses nos yeux sont obscurcis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'A cause de la montagne de Sion qui est désolée; les renards n’en bougent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Mais toi, ô Eternel! tu demeures éternellement, et ton trône est d’âge en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Pourquoi nous oublierais-tu à jamais? pourquoi nous délaisserais- tu si longtemps?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Convertis-nous à toi, ô Eternel! et nous serons convertis; renouvelle nos jours comme ils étaient autrefois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Mais tu nous as entièrement rejetés, tu t’es extrêmement courroucé contre nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Or il arriva en la trentième année, au cinquième jour du quatrième mois, comme j’étais parmi ceux qui avaient été transportés sur le fleuve de Kébar, que les cieux furent ouverts, et je vis des visions de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Au cinquième jour du mois de cette année, qui fut la cinquième après que le Roi Jéhojachin eut été mené en captivité,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'La parole de l’Eternel fut adressée expressément à Ezéchiel Sacrificateur, fils de Buzi, au pays des Caldéens, sur le fleuve de Kébar, et la main de l’Eternel fut là sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Je vis donc, et voici un vent de tempête qui venait de l’Aquilon, et une grosse nuée, et un feu s’entortillant; et il y avait autour de la nuée une splendeur, et au milieu de la nuée paraissait comme la couleur du Hasmal, lorsqu’il sort du feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Et du milieu de cette couleur de Hasmal paraissait une ressemblance de quatre animaux, et c’était ici leur forme; ils avaient la ressemblance d’un homme;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Et chacun d’eux avait quatre faces, et chacun quatre ailes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Et leurs pieds étaient des pieds droits; et la plante de leurs pieds était comme la plante d’un pied de veau, et ils étincelaient comme la couleur d’un airain poli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Et il y avait des mains d’homme sous leurs ailes à leurs quatre côtés; et tous quatre avaient leurs faces et leurs ailes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Leurs ailes étaient jointes l’une à l’autre; ils ne se tournaient point quand ils marchaient, mais chacun marchait vis-à-vis de soi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Et la ressemblance de leurs faces était la face d’un homme, et la face d’un lion, à la main droite des quatre; et la face d’un boeuf à la gauche des quatre; et la face d’un aigle, à tous les quatre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Et leurs faces et leurs ailes étaient divisées par le haut; chacun avait des ailes, qui se joignaient l’une à l’autre, et deux couvraient leurs corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Et chacun d’eux marchait vis-à-vis de soi; vers quelque part que l’esprit les poussât ils y allaient; et ils ne se tournaient point lorsqu’ils marchaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Et quant à la ressemblance des animaux, leur regard était comme des charbons de feu ardent, et comme qui verrait des lampes; le feu courait parmi les animaux; et le feu avait une splendeur, et de ce feu sortait un éclair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Et les animaux couraient et retournaient, selon que l’éclair paraissait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Et comme j’eus vu les animaux, voici, une roue apparut sur la terre auprès des animaux pour ses quatre faces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Et la ressemblance et la façon des roues était comme la couleur d’un chrysolithe, et toutes les quatre avaient une même ressemblance; leur ressemblance et leur façon était comme si une roue eût été au dedans d’une autre roue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'En marchant elles allaient sur leurs quatre côtés, et elles ne se tournaient point quand elles allaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Et elles avaient des jantes, et étaient si hautes, qu’elles faisaient peur, et leurs jantes étaient pleines d’yeux tout autour des quatre roues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Et quand les animaux marchaient, les roues marchaient auprès d’eux; et quand les animaux s’élevaient de dessus la terre, les roues aussi s’élevaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Vers quelque part que l’Esprit voulût aller ils y allaient; l’Esprit tendait-il là? ils y allaient, et les roues s’élevaient vis-à-vis d’eux; car l’Esprit des animaux était dans les roues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Quand ils marchaient, elles marchaient; et quand ils s’arrêtaient, elles s’arrêtaient; et quand ils s’élevaient de dessus terre, les roues aussi s’élevaient vis-à-vis d’eux; car l’Esprit des animaux était dans les roues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Et la ressemblance de ce qui était au-dessus des têtes des animaux, était une étendue semblable à la voir à un cristal dont l’état remplissait de respect, laquelle s’étendait sur leurs têtes par dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Et leurs ailes se tenaient droites au dessous de l’étendue, l’une vers l’autre; et ils avaient chacun deux ailes dont ils se couvraient, chacun, dis-je, en avait deux qui couvraient leurs corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Puis j’ouïs le bruit que faisaient leurs ailes quand ils marchaient, qui était comme le bruit des grosses eaux, et comme le bruit du Tout-Puissant, un bruit éclatant comme le bruit d’une armée; et quand ils s’arrêtaient, ils baissaient leurs ailes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Et lorsqu’en s’arrêtant ils baissaient leurs ailes, il se faisait un bruit au dessus de l’étendue qui était sur leurs têtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Et au dessus de cette étendue, qui était sur leurs têtes, il y avait la ressemblance d’un trône, qui était, à le voir, comme une pierre de saphir: et sur la ressemblance du trône il y avait une ressemblance, qui, à la voir, était comme un homme assis sur le trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Et je vis comme la couleur du Hasmal, ressemblant à un feu, au dedans duquel il était tout à l’entour; depuis la ressemblance de ses reins, et par dessus; et depuis la ressemblance de ses reins jusqu’en bas je vis comme qui verrait du feu, et il y avait une splendeur autour de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Et la splendeur qui se voyait autour de lui était comme l’arc qui se fait dans la nuée en un jour de pluie. C’est là la vision de la représentation de la gloire de l’Eternel; laquelle ayant vue, je tombai sur ma face, et j’entendis une voix qui parlait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Et il me fut dit: Fils d’homme, tiens-toi sur tes pieds, et je parlerai avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Alors l’Esprit entra dans moi, après qu’on m’eut parlé, et il me releva sur mes pieds, et j’ouïs celui qui me parlait,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Qui me dit: fils d’homme; je t’envoie vers les enfants d’Israël, vers des nations rebelles qui se sont rebellées contre moi; eux et leurs pères ont péché contre moi jusques à ce propre jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Et ce sont des enfants effrontés, et d’un coeur obstiné, vers lesquels je t’envoie; c’est pourquoi tu leur diras que le Seigneur l’Eternel a ainsi parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Et soit qu’ils écoutent, ou qu’ils n’en fassent rien; car ils sont une maison rebelle, ils sauront pourtant qu’il y aura eu un Prophète parmi eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Mais toi, fils d’homme, ne les crains point, et ne crains point leurs paroles; quoique des gens revêches et dont les langues sont perçantes comme des épines soient avec toi, et que tu demeures parmi des scorpions; ne crains point leurs paroles, et ne t’effraie point à cause d’eux, quoiqu’ils soient une maison rebelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Tu leur prononceras donc mes paroles, soit qu’ils écoutent, ou qu’ils n’en fassent rien; car ils ne sont que rébellion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Mais toi, fils d’homme, écoute ce que je te dis, et ne sois point rebelle, comme cette maison rebelle; ouvre ta bouche, et mange ce que je te vais donner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Alors je regardai, et voici, une main fut envoyée vers moi, et voici, elle avait un rouleau de livre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Et elle l’ouvrit devant moi, et voici, il était écrit dedans et dehors, et des lamentations, des regrets, et des malédictions y étaient écrites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Puis il me dit: fils d’homme, mange ce que tu trouveras, mange ce rouleau, et t’en va, et parle à la maison d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'J’ouvris donc ma bouche, et il me fit manger ce rouleau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Et il me dit: fils d’homme, repais ton ventre, et remplis tes entrailles de ce rouleau que je te donne; et je le mangeai, et il fut doux dans ma bouche comme du miel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Puis il me dit: fils d’homme, lève-toi et va vers la maison d’Israël, et leur prononce mes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Car tu n’es point envoyé vers un peuple de langage inconnu, ou de langue barbare; c’est vers la maison d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Ni vers plusieurs peuples de langage inconnu, ou de langue barbare, dont tu ne puisses pas entendre les paroles; si je t’eusse envoyé vers eux, ne t’écouteraient-ils pas?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Mais la maison d’Israël ne te voudra pas écouter, parce qu’ils ne me veulent point écouter; car toute la maison d’Israël est effrontée, et d’un coeur obstiné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Voici, j’ai renforcé ta face contre leurs faces, et j’ai renforcé ton front contre leurs fronts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Et j’ai rendu ton front semblable à un diamant, et plus fort qu’un caillou; ne les crains donc point, et ne t’effraie point à cause d’eux, quoiqu’ils soient une maison rebelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Puis il me dit: fils d’homme, reçois dans ton coeur, et écoute de tes oreilles toutes les paroles que je te dirai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Lève-toi donc, va vers ceux qui ont été emmenés captifs, va vers les enfants de ton peuple, parle-leur, et leur dis que le Seigneur l’Eternel a ainsi parlé, soit qu’ils écoutent, ou qu’ils n’en fassent rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Puis l’Esprit m’éleva, et j’ouïs après moi une voix qui me causa une grande émotion, disant: Bénie soit de son lieu la gloire de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'Et j’ouïs le bruit des ailes des animaux, qui s’entre-touchaient les unes les autres, et le bruit des roues vis-à-vis d’eux, j’ouïs, dis-je, une voix qui me causa une grande émotion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'L’Esprit donc m’éleva, et me ravit, et je m’en allai l’esprit rempli d’amertume et de colère mais la main de l’Eternel me fortifia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Je vins donc vers ceux qui avaient été transportés à Télabib, vers ceux qui demeuraient auprès du fleuve de Kébar; et je me tins là où ils se tenaient, même je me tins là parmi eux sept jours, tout étonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Et au bout de sept jours, la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Fils d’homme, je t’ai établi pour surveillant à la maison d’Israël; tu écouteras donc la parole de ma bouche, et tu les avertiras de ma part.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Quand j’aurai dit au méchant: tu mourras de mort, et que tu ne l’auras point averti, et que tu ne lui auras point parlé pour l’avertir de se garder de son méchant train, afin de lui sauver la vie; ce méchant-là mourra dans son iniquité, mais je redemanderai son sang de ta main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Que si tu as averti le méchant, et qu’il ne se soit point détourné de sa méchanceté, ni de son méchant train; il mourra dans son iniquité, mais tu auras délivré ton âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Pareillement si le juste se détourne de sa justice, et commet l’iniquité, lorsque j’aurai mis quelque obstacle devant lui, il mourra, parce que tu ne l’auras point averti; il mourra dans son péché, et il ne sera point fait mention de ses justices qu’il aura faites; mais je redemanderai son sang de ta main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Que si tu avertis le juste de ne pécher point, et que lui aussi ne pèche point, il vivra certainement, parce qu’il aura été averti, et toi pareillement tu auras délivré ton âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Et la main de l’Eternel fut là sur moi, et il me dit: lève-toi, et sors vers la campagne, et là je te parlerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Je me levai donc, et sortis vers la campagne; et voici, la gloire de l’Eternel se tenait là, telle que la gloire que j’avais vue auprès du fleuve de Kébar, et je tombai sur ma face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Alors l’Esprit entra dans moi, et me releva sur mes pieds, et il me parla, et me dit: entre, et t’enferme dans ta maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Car quant à toi, fils d’homme, voici, on mettra des cordes sur toi, et on t’en liera, et tu ne sortiras point pour aller parmi eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Et je ferai tenir ta langue à ton palais, tu seras muet, et tu ne les reprendras point; parce qu’ils sont une maison rebelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Mais quand je te parlerai, j’ouvrirai ta bouche, et tu leur diras: ainsi a dit le Seigneur l’Eternel: que celui qui écoute, écoute; et que celui qui n’écoute pas, n’écoute pas; car ils sont une maison rebelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'Et toi, fils d’homme, prends-toi un tableau carré, et le mets devant toi, et traces-y la ville de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Puis tu mettras le siège contre elle, tu bâtiras contre elle des forts, tu élèveras contre elle des terrasses, tu poseras des camps contre elle, et tu mettras autour d’elle des machines pour la battre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Tu prendras aussi une plaque de fer, et tu la mettras pour un mur de fer entre toi et la ville, et tu dresseras ta face contre elle, et elle sera assiégée, et tu l’assiégeras; ce sera un signe à la maison d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Après tu dormiras sur ton côté gauche, et tu mettras sur lui l’iniquité de la maison d’Israël; selon le nombre des jours que tu dormiras sur ce côté, tu porteras leur iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Et je t’ai assigné les ans de leur iniquité selon le nombre des jours, savoir trois cent quatre-vingt-dix jours; ainsi tu porteras l’iniquité de la maison d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Et quand tu auras accompli ces jours-là, tu dormiras la seconde fois sur ton côté droit, et tu porteras l’iniquité de la maison de Juda pendant quarante jours, un jour pour un an; car je t’ai assigné un jour pour un an.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Et tu dresseras ta face vers le siège ordonné contre Jérusalem, et ton bras sera retroussé; et tu prophétiseras contre elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Or voici j’ai mis sur toi des cordes, et tu ne te tourneras point de l’un de tes côtés à l’autre, jusqu’à ce que tu aies accompli les jours de ton siège.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Tu prendras aussi du froment, de l’orge, des fèves, des lentilles, du millet, et de l’épeautre, et tu les mettras dans un vaisseau, et t’en feras du pain selon le nombre des jours que tu dormiras sur ton côté; tu en mangeras pendant trois cent quatre-vingt-dix jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Et la viande que tu mangeras sera du poids de vingt sicles par jour; et tu la mangeras depuis un temps jusqu’à l’autre temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Et tu boiras de l’eau par mesure, savoir la sixième partie d’un Hin; tu la boiras depuis un temps jusqu’à l’autre temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Tu mangeras aussi des gâteaux d’orge, et tu les cuiras avec de la fiente sortie de l’homme, eux le voyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Puis l’Eternel dit: les enfants d’Israël mangeront ainsi leur pain souillé parmi les nations vers lesquelles je les chasserai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Et je dis: ah! ah! Seigneur Eternel, voici, mon âme n’a point été souillée, et je n’ai mangé d’aucune bête morte d’elle-même, ou déchirée par les bêtes sauvages, depuis ma jeunesse jusqu’à présent; et aucune chair impure n’est entrée dans ma bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Et il me répondit: voici, je t’ai donné la fiente des boeufs, au lieu de la fiente de l’homme, et tu feras cuire ton pain avec cette fiente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Puis il me dit: fils d’homme, voici, je m’en vais rompre le bâton du pain dans Jérusalem; et ils mangeront leur pain à poids, et avec chagrin; et ils boiront l’eau par mesure, et avec étonnement;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'Parce que le pain et l’eau leur manqueront, et ils seront étonnés se regardant l’un l’autre, et ils fondront à cause de leur iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Davantage toi, fils d’homme, prends-toi un couteau tranchant; prends-toi un rasoir de barbier; et fais-le passer sur ta tête, et sur ta barbe; puis tu prendras une balance à peser, et tu partageras ce que tu auras rasé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Tu en brûleras une troisième partie dans le feu, au milieu de la ville, lorsque les jours du siège s’accompliront, et tu en prendras une autre troisième partie, et tu frapperas de l’épée à l’entour; et tu disperseras au vent l’autre troisième partie; car je tirerai l’épée après eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Et tu en prendras de là quelque petit nombre, et les serreras aux pans de ton manteau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Et de ceux-là, tu en prendras encore, et les jetteras au milieu du feu, et les brûleras au feu; et il en sortira du feu contre toute la maison d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Ainsi a dit le Seigneur l’Eternel: c’est ici cette Jérusalem que j’avais placée au milieu des nations et des pays qui sont autour d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Elle a changé mes ordonnances en une méchanceté pire que celle des nations, et mes statuts en une méchanceté pire que celle des pays qui sont autour d’elle; car ils ont rejeté mes ordonnances, et n’ont point marché dans mes statuts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'C’est pourquoi le Seigneur l’Eternel a dit ainsi: parce que vous avez multiplié vos méchancetés plus que les nations qui sont autour de vous, et que vous n’avez point marché dans mes statuts, et n’avez point observé mes ordonnances, et que vous n’avez pas même fait selon les ordonnances des nations qui sont autour de vous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'A cause de cela le Seigneur l’Eternel dit ainsi: voici, j’ en veux à toi, oui moi-même, et j’exécuterai au milieu de toi mes jugements, devant les yeux des nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'Et je ferai en toi, à cause de toutes tes abominations, des choses que je ne fis jamais, et telles que je n’en ferai jamais de semblables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Les pères mangeront leurs enfants au milieu de toi, et les enfants mangeront leurs pères; et j’exécuterai mes jugements sur toi, et je disperserai à tous vents tout ce qui restera de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Et je suis vivant, dit le Seigneur l’Eternel, parce que tu as souillé mon Sanctuaire par toutes tes infamies, et par toutes tes abominations, moi-même je te raserai, et mon oeil ne t’épargnera point, et je n’en aurai point de compassion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Une troisième partie d’entre vous mourra de mortalité, et sera consumée par la famine au milieu de toi; et une troisième partie tombera par l’épée autour de toi; et je disperserai à tous vents l’autre troisième partie, et je tirerai l’épée après eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Car ma colère sera portée à son comble, et je ferai reposer ma fureur sur eux, et je me satisferai; et ils sauront que moi l’Eternel j’ai parlé dans ma jalousie, quand j’aurai consommé ma fureur sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Je te mettrai en désert et en opprobre parmi les nations qui sont autour de toi, tellement que tous les passants le verront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Et tu seras en opprobre, en ignominie, en instruction, et en étonnement aux nations qui sont autour de toi, quand j’aurai exécuté mes jugements sur toi, avec colère, avec fureur, et par des châtiments pleins de fureur; moi l’Eternel j’ai parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Après que j’aurai décoché sur eux les mauvaises flèches de la famine, qui seront mortelles, lesquelles je décocherai pour vous détruire, encore j’augmenterai la famine sur vous, et je vous romprai le bâton du pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Je vous enverrai la famine, et des bêtes nuisibles, qui te priveront d’enfants; et la mortalité et le sang passeront parmi toi, et je ferai venir l’épée sur toi; moi l’Eternel j’ai parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Fils d’homme, tourne ta face contre les montagnes d’Israël, et prophétise contre elles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'Et dis: montagnes d’Israël, écoutez la parole du Seigneur l’Eternel. Ainsi a dit le Seigneur l’Eternel aux montagnes et aux coteaux, aux cours des rivières, et aux vallées: me voici, je m’en vais faire venir l’épée sur vous, et je détruirai vos hauts lieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Et vos autels seront désolés, et les tabernacles de vos idoles seront brisés, et j’abattrai les blessés à mort d’entre vous, devant vos dieux de fiente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Car je mettrai les cadavres des enfants d’Israël devant leurs dieux de fiente, et je disperserai vos os autour de vos autels.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Les villes seront désertes en toutes vos demeures, et les hauts lieux seront désolés, tellement que vos autels seront déserts et désolés, et vos dieux de fiente seront brisés, et ne seront plus; les tabernacles de vos idoles seront mis en pièces, et vos ouvrages seront abolis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'Et les blessés à mort tomberont parmi vous; et vous saurez que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Mais j’en laisserai d’entre vous quelques-uns de reste, afin que vous ayez quelques réchappés de l’épée entre les nations, quand vous serez dispersés parmi les pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Et vos réchappés se souviendront de moi entre les nations parmi lesquelles ils seront captifs, parce que je me serai tourmenté à cause de leur coeur adonné à la fornication, qui s’est détourné de moi, et à cause de leurs yeux qui se livrent à la fornication après leurs dieux de fiente; et ils se déplairont en eux-mêmes au sujet des maux qu’ils auront faits dans toutes leurs abominations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Et ils sauront que je suis l’Eternel, qui n’aurai point parlé en vain de leur faire ce mal-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Ainsi a dit le Seigneur l’Eternel: frappe de ta main et bats de ton pied, et dis: hélas! à cause de toutes les abominations des maux de la maison d’Israël; car ils tomberont par l’épée, par la famine, et par la mortalité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Celui qui sera loin mourra par la mortalité, et celui qui sera près tombera par l’épée; et celui qui sera demeuré de reste, et qui sera assiégé, mourra par la famine; ainsi je consommerai ma fureur sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Et vous saurez que je suis l’Eternel, quand les blessés à mort d’entre eux seront parmi leurs dieux de fiente, autour de leurs autels, sur tout coteau haut élevé, sur tous les sommets des montagnes, sous tout arbre vert, et sous tout chêne branchu, qui est le lieu auquel ils ont fait des parfums de bonne odeur à tous leurs dieux de fiente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'J’étendrai donc ma main sur eux, et je rendrai leur pays désolé et désert dans toutes leurs demeures, plus que le désert qui est vers Dibla; et ils sauront que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Puis la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Et toi, fils d’homme, écoute: ainsi a dit le Seigneur l’Eternel à la terre d’Israël: la fin, la fin vient sur les quatre coins de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Maintenant la fin vient sur toi, et j’enverrai sur toi ma colère, et je te jugerai selon ta voie, et je mettrai sur toi toutes tes abominations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Et mon oeil ne t’épargnera point, et je n’aurai point de compassion; mais je mettrai ta voie sur toi, et tes abominations seront au milieu de toi; et vous saurez que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Ainsi a dit le Seigneur l’Eternel: voici un mal, un seul mal qui vient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'La fin vient, la fin vient, elle se réveille contre toi; voici, le mal vient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Le matin vient sur toi qui demeures au pays; le temps vient, le jour est près de toi; il ne sera que frayeur, et non point une invitation des montagnes à s’entre-réjouir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Maintenant je répandrai bientôt ma fureur sur toi, et je consommerai ma colère sur toi, et je te jugerai selon ta voie, je mettrai sur toi toutes tes abominations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Mon oeil ne t’épargnera point, et je n’aurai point de compassion, je te punirai selon ta voie, et tes abominations seront au milieu de toi; et vous saurez que je suis l’Eternel qui frappe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Voici le jour, voici il vient, le matin paraît, la verge a fleuri, la fierté a jeté des boutons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'La violence est crûe en verge de méchanceté; il ne restera rien d’eux, ni de leur multitude, ni de leur tumulte, et on ne les lamentera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Le temps vient, le jour est tout proche: que celui donc qui achète ne se réjouisse point, et que celui qui vend n’en mène point de deuil; car il y a une ardeur de colère sur toute la multitude de son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Car celui qui vend ne retournera point à ce qu’il aura vendu, quand ils seraient encore en vie; parce que la vision touchant toute la multitude de son pays ne sera point révoquée, et chacun portera la peine de son iniquité, tant qu’il vivra; ils ne reprendront jamais courage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Ils ont sonné la trompette, et ils ont tout préparé, mais il n’y a personne qui aille au combat, parce que l’ardeur de ma colère est sur toute la multitude de son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'L’épée est au dehors, et la mortalité et la famine sont au dedans; celui qui sera aux champs, mourra par l’épée; et celui qui sera dans la ville, la famine et la mortalité le dévoreront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Et les réchappés d’entre eux s’enfuiront, et seront par les montagnes comme les pigeons des vallées, tous gémissants, chacun dans son iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Toutes les mains deviendront lâches, et tous les genoux se fondront en eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Ils se ceindront de sacs, et le tremblement les couvrira, la confusion sera sur tous leurs visages, et leurs têtes deviendront chauves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Ils jetteront leur argent par les rues, et leur or s’en ira au loin; leur argent ni leur or ne les pourront pas délivrer au jour de la grande colère de l’Eternel; ils ne rassasieront point leurs âmes, et ne rempliront point leurs entrailles, parce que leur iniquité aura été leur ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'II avait mis entre eux la noblesse de son magnifique ornement; mais ils y ont placé des images de leurs abominations, et de leurs infamies, c’est pourquoi je la leur ai exposée à être chassée au loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'Et je l’ai livrée en pillage dans la main des étrangers, et en proie aux méchants de la terre, qui la profaneront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Je détournerai aussi ma face d’eux, et on violera mon lieu secret, et les saccageurs y entreront, et le profaneront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Fais une chaîne; car le pays est plein de crimes de meurtre, et la ville est pleine de violence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'C’est pourquoi je ferai venir les plus méchants des nations, qui possèderont leurs maisons, et je ferai cesser l’orgueil des puissants, et leurs saints lieux seront profanés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'La destruction vient, et ils chercheront la paix, mais il n’y en aura point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Malheur viendra sur malheur, et il y aura rumeur sur rumeur; ils demanderont la vision aux Prophètes; la Loi périra chez le Sacrificateur, et le conseil chez les anciens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Le Roi mènera deuil, les principaux se vêtiront de désolation, et les mains du peuple du pays tomberont de frayeur; je les traiterai selon leur voie, et je les jugerai selon qu’ils l’auront mérité; et ils sauront que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'Puis il arriva en la sixième année, au cinquième jour du sixième mois, comme j’étais assis dans ma maison, et que les Anciens de Juda étaient assis devant moi, que la main du Seigneur l’Eternel tomba là sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Et je regardai, et voici une ressemblance qui était comme une apparence de feu; depuis la ressemblance de ses reins jusqu’en bas c’était du feu, et depuis ses reins jusqu’en haut, c’était comme qui verrait une splendeur telle que la couleur du Hasmal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Et il avança une forme de main, et me prit par la chevelure de ma tête, et l’Esprit m’éleva entre la terre et les cieux, et me transporta à Jérusalem, dans des visions de Dieu, à l’entrée de la porte du parvis de dedans, qui regarde vers l’Aquilon, où était posée l’idole de jalousie qui provoque à la jalousie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Et voici, la gloire du Dieu d’Israël était là, selon la vision que j’avais vue à la campagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Et il me dit: fils d’homme, lève maintenant tes yeux vers le chemin qui tend vers l’Aquilon; et j’élevai mes yeux vers le chemin qui tend vers l’Aquilon, et voici du côté de l’Aquilon à la porte de l’autel était cette idole de jalousie, à l’entrée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Et il me dit: fils d’homme, ne vois-tu pas ce que ceux-ci font, et les grandes abominations que la maison d’Israël commet ici, afin que je me retire de mon Sanctuaire? mais tourne-toi encore, et tu verras de grandes abominations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Il me mena donc à l’entrée du parvis, et je regardai, et voici il y avait un trou dans la paroi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Et il me dit: fils d’homme, perce maintenant la paroi; et quand j’eus percé la paroi, il se trouva là une porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Puis il me dit: Entre, et regarde les méchantes abominations qu’ils commettent ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'J’entrai donc, et je regardai; et voici toute sorte de figures de reptiles, et de bêtes, et d’abominations, et tous les dieux de fiente de la maison d’Israël étaient peints sur la paroi, tout autour, tout autour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Et soixante-dix hommes d’entre les Anciens de la maison d’Israël, avec Jaazanja fils de Saphan, qui était debout au milieu d’eux, se tenaient debout devant elles, et chacun avait en sa main un encensoir, d’où montait en haut une épaisse nuée de parfum.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Alors il me dit: fils d’homme, n’as-tu pas vu ce que les Anciens de la maison d’Israël font dans les ténèbres, chacun dans son cabinet peint? car ils disent: l’Eternel ne nous voit point; l’Eternel a abandonné le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Puis il me dit: tourne-toi encore, et tu verras les grandes abominations que ceux-ci commettent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Il m’amena donc à l’entrée de la porte de la maison de l’Eternel qui est vers l’Aquilon; et voici, il y avait là des femmes assises qui pleuraient Thammus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Et il me dit: fils d’homme, n’as-tu pas vu? tourne-toi encore, et tu verras des abominations plus grandes que celles-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Il me fit donc entrer au parvis du dedans de la maison de l’Eternel, et voici à l’entrée du Temple de l’Eternel, entre le porche et l’autel, environ vingt-cinq hommes qui avaient le dos tourné contre le Temple de l’Eternel, et leurs visages tournés vers l’Orient, qui se prosternaient vers l’Orient devant le soleil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Alors il me dit: fils d’homme, n’as-tu pas vu? est-ce une chose légère à la maison de Juda de commettre ces abominations qu’ils commettent ici? car ils ont rempli le pays de violence, et ils se sont ainsi tournés pour m’irriter; mais voici ils mettent une écharde à leurs nez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Et moi, j’agirai en ma fureur; mon oeil ne les épargnera point, et je n’ en aurai point de compassion; et quand ils crieront à haute voix à mes oreilles, je ne les exaucerai point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Puis il cria d’une voix forte moi l’entendant, et il dit: faites approcher ceux qui ont commission contre la ville, chacun avec son instrument de destruction dans sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Et voici six hommes venaient de devers le chemin de la haute porte qui regarde vers l’Aquilon, et chacun avait en sa main son instrument de destruction; et il y avait au milieu d’eux un homme vêtu de lin, qui avait un cornet d’écrivain sur ses reins; et ils entrèrent, et se tinrent auprès de l’autel d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Alors la gloire du Dieu d’Israël s’éleva de dessus le Chérubin sur lequel elle était, et vint sur le seuil de la maison, et il cria à l’homme qui était vêtu de lin, et qui avait le cornet d’écrivain sur ses reins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'Et l’Eternel lui dit: passe par le milieu de la ville, par le milieu de Jérusalem, et marque la lettre Thau sur les fronts des hommes qui gémissent et qui soupirent à cause de toutes les abominations qui se commettent au dedans d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Et il dit aux autres, moi l’entendant: passez par la ville après lui, et frappez; que votre oeil n’épargne personne, et n’ayez point de compassion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Tuez tout, les vieillards, les jeunes gens, les vierges, les petits enfants, et les femmes; mais n’approchez point d’aucun de ceux sur lesquels sera la lettre Thau, et commencez par mon Sanctuaire. Ils commencèrent donc par les vieillards qui étaient devant la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Et il leur dit: profanez la maison, et remplissez les parvis de gens tués; sortez, et ils sortirent, et frappèrent par la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Or il arriva que comme ils frappaient, je demeurai là, et m’étant prosterné le visage contre terre, je criai, et dis: Ah! ah! Seigneur Eternel! t’en vas-tu donc détruire tous les restes d’Israël, en répandant ta fureur sur Jérusalem?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Et il me dit: l’iniquité de la maison d’Israël et de Juda est excessivement grande, et le pays est rempli de meurtres, et la ville remplie de crimes; car ils ont dit: l’Eternel a abandonné le pays, et l’Eternel ne nous voit point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Et quant à moi, mon oeil aussi ne les épargnera point, et je n’en aurai point de compassion; je leur rendrai leur train sur leur tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Et voici, l’homme vêtu de lin, qui avait le cornet sur ses reins, rapporta ce qui avait été fait, et il dit: J’ai fait comme tu m’as commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Puis je regardai, et voici dans l’étendue qui était sur la tête des Chérubins parut au-dessus d’eux comme une pierre de saphir, qui, à la voir, était semblable à un trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Et on parla à l’homme vêtu de lin, et on lui dit: entre dans l’entre-deux des roues au dessous du Chérubin, et remplis tes paumes de charbons de feu de l’entre-deux des Chérubins, et les répands sur la ville; il y entra donc, moi le voyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Et les Chérubins se tenaient à main droite de la maison quand l’homme entra; et une nuée remplit le parvis intérieur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Puis la gloire de l’Eternel s’éleva de dessus les Chérubins pour venir sur le seuil de la maison, et la maison fut remplie d’une nuée; le parvis aussi fut rempli de la splendeur de la gloire de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Et on entendit le bruit des ailes des Chérubins jusqu’au parvis extérieur, comme la voix du Dieu Fort Tout-puissant, quand il parle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Et il arriva que quand il eut commandé à l’homme qui était vêtu de lin, en disant: prends du feu de l’entre-deux des Chérubins; il entra, et se tint auprès des roues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Et l’un des Chérubins étendit sa main vers l’entre-deux des Chérubins au feu qui était dans l’entre-deux des Chérubins; et il en prit, et le mit entre les mains de l’homme vêtu de lin, qui l’ayant reçu, se retira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, '(Car il apparaissait dans les Chérubins la figure d’une main d’homme sous leurs ailes.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Puis je regardai, et voici quatre roues auprès des Chérubins, une roue auprès d’un des Chérubins, et une autre roue auprès d’un Chérubin; et la ressemblance des roues était comme la couleur d’une pierre de chrysolithe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Et quant à leur ressemblance, toutes quatre avaient une même façon, comme si une roue eût été au dedans d’une autre roue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Quand elles marchaient, elles allaient sur leurs quatre côtés; et en marchant elles ne se tournaient point, mais au lieu vers lequel le chef tendait, elles allaient après lui; elles ne se tournaient point quand elles marchaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Non plus que tout le corps des Chérubins, ni leur dos, ni leurs mains, ni leurs ailes; et les roues, savoir leurs quatre roues, étaient pleines d’yeux à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Et quant aux roues, on les appela, moi l’entendant, un chariot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Et chaque animal avait quatre faces: la première face était la face d’un Chérubin; et la seconde face était la face d’un homme; et la troisième était la face d’un lion; et la quatrième la face d’un aigle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Puis les Chérubins s’élevèrent en haut. Ce sont là les animaux que j’avais vus auprès du fleuve de Kébar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Et lorsque les Chérubins marchaient, les roues aussi marchaient auprès d’eux, et quand les Chérubins élevaient leurs ailes pour s’élever de terre, les roues ne se contournaient point d’auprès d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Lorsqu’ils s’arrêtaient, elles s’arrêtaient; et lorsqu’ils s’élevaient, elles s’élevaient; car l’esprit des animaux était dans les roues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Puis la gloire de l’Eternel se retira de dessus le seuil de la maison, et se tint au dessus des Chérubins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Et les Chérubins élevant leurs ailes, s’élevèrent de terre en ma présence quand ils partirent; et les roues s’élevèrent aussi vis- à-vis d’eux, et chacun d’eux s’arrêta à l’entrée de la porte Orientale de la maison de l’Eternel; et la gloire du Dieu d’Israël était sur eux par dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Ce sont là les animaux que j’avais vus sous le Dieu d’Israël près du fleuve de Kébar; et je connus que c’étaient des Chérubins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Chacun avait quatre faces, et chacun quatre ailes, et il y avait une ressemblance de main d’homme sous leurs ailes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Et quant à la ressemblance de leurs faces, c’étaient les faces que j’avais vues auprès du fleuve de Kébar, et leur même regard, et elles-mêmes; et chacun marchait vis-à-vis de soi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Puis l’Esprit m’éleva, et me mena à la porte Orientale de la maison de l’Eternel qui regarde vers l’Orient; et voici vingt-cinq hommes à l’entrée de la porte; et je vis au milieu d’eux Jaazanja fils de Hazur, et Pélatja fils de Bénaja, les principaux du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Et il me dit: fils d’homme, ceux-ci sont les hommes qui ont des pensées d’iniquité, et qui donnent un mauvais conseil dans cette ville;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'En disant: ce n’est pas une chose prête; qu’on bâtisse des maisons; elle est la chaudière, et nous sommes la chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'C’est pourquoi prophétise contre eux, prophétise, fils d’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'L’Esprit donc de l’Eternel tomba sur moi, et me dit: parle. Ainsi a dit l’Eternel: vous parlez ainsi, maison d’Israël, et je connais toutes les pensées de votre esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Vous avez multiplié vos gens tués dans cette ville; et vous avez rempli ses rues de gens que vous avez mis à mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'C’est pourquoi, ainsi a dit le Seigneur l’Eternel: les gens que vous avez fait mourir, et que vous avez mis au milieu d’elle, sont la chair, et elle est la chaudière, mais je vous tirerai hors du milieu d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Vous avez eu peur de l’épée, mais je ferai venir l’épée sur vous, dit le Seigneur l’Etemel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'Et je vous tirerai hors de la ville, je vous livrerai entre les mains des étrangers, et j’exécuterai mes jugements contre vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Vous tomberez par l’épée; je vous jugerai dans le pays d’Israël; et vous saurez que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Elle ne vous sera point une chaudière, et vous ne serez point au dedans d’elle comme la chair; je vous jugerai dans le pays d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'Et vous saurez que je suis l’Eternel; car vous n’avez point marché dans mes statuts, et vous n’avez point suivi mes ordonnances; mais vous avez agi selon les ordonnances des nations qui sont autour de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Or il arriva comme je prophétisais, que Pélatja fils de Bénaja mourut; alors je me prosternai sur mon visage, et je criai à haute voix, et dis: ah! ah! Seigneur Eternel! t’en vas-tu consumer entièrement le reste d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Et la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Fils d’homme, tes frères, tes frères, les hommes de ta parenté, et tous ceux de la maison d’Israël entièrement sont ceux auxquels les habitants de Jérusalem ont dit: éloignez-vous de l’Eternel, la terre nous a été donnée en héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'C’est pourquoi dis-leur: ainsi a dit le Seigneur l’Eternel: quoique je les aie éloignés entre les nations, et que je les aie dispersés par les pays, je leur ai pourtant été comme un petit Sanctuaire dans les pays auxquels ils sont venus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'C’est pourquoi dis-leur: ainsi a dit le Seigneur l’Eternel: aussi je vous recueillerai d’entre les peuples, et je vous rassemblerai des pays auxquels vous avez été dispersés, et je vous donnerai la terre d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Et ils y entreront, et ôteront hors d’elle toutes ses infamies, et toutes ses abominations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Et je ferai qu’ils n’auront qu’un coeur, et je mettrai au dedans d’eux un esprit nouveau; j’ôterai le coeur de pierre hors de leur chair, et je leur donnerai un coeur de chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'Afin qu’ils marchent dans mes statuts; qu’ils gardent mes ordonnances, et qu’ils les fassent; et ils seront mon peuple, et je serai leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Mais quant à ceux dont le coeur va après le désir de leurs infamies et de leurs abominations, quant à ceux-là, je ferai tomber sur leur tête les peines que mérite leur conduite, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Puis les Chérubins élevèrent leurs ailes, et les roues qui étaient vis-à-vis d’eux s’élevèrent aussi, et la gloire aussi du Dieu d’Israël qui était sur eux par dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'Et la gloire de l’Eternel s’éleva du milieu de la ville, et s’arrêta sur la montagne qui est à l’Orient de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Puis l’Esprit m’enleva, et me transporta en Caldée, vers ceux qui avaient été emmenés captifs, le tout en vision par l’Esprit de Dieu. Et la vision que j’avais vue disparut de devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Alors je dis à ceux qui avaient été emmenés captifs toutes les choses que l’Eternel m’avait fait voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Fils d’homme: tu demeures au milieu d’une maison rebelle, au milieu de gens qui ont des yeux pour voir, et ne voient point; et qui ont des oreilles pour ouïr, et n’entendent point; parce qu’ils sont une maison rebelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Toi donc, fils d’homme, fais-toi l’équipage d’un homme qui déloge, et déloge de jour, eux le voyant; déloge, dis-je, de ton lieu pour aller en un autre, eux le voyant; peut-être qu’ils y prendront garde; quoiqu’ils soient une maison rebelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Tu mettras donc dehors pendant le jour ton équipage, tel qu’est l’équipage d’un homme qui déloge, eux le voyant; et sur le soir tu sortiras, eux le voyant, comme quand on sort pour déloger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Perce-toi la paroi, eux le voyant, et tire par-là dehors ton équipage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Tu le porteras sur l’épaule, eux le voyant, et tu le tireras dehors sur la brune; tu couvriras aussi ton visage, afin que tu ne voies point la terre; car je t’ai mis pour être un signe à la maison d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Je fis donc comme il m’avait été commandé: je portai dehors durant le jour mon équipage tel qu’est l’équipage d’un homme qui déloge, et sur le soir je me perçai la paroi avec la main, je le tirai dehors sur la brune, et le portai sur l’épaule, eux le voyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Et au matin la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Fils d’homme, la maison d’Israël, maison rebelle, ne t’a-t-elle pas dit: qu’est-ce que tu fais?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Dis-leur: ainsi a dit le Seigneur l’Eternel: Cet ordre dont je suis chargé s’adresse au Prince qui est dans Jérusalem, et à toute la maison d’Israël qui est parmi eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Dis: Je vous suis pour un signe; comme j’ai fait, ainsi il leur sera fait; ils délogeront pour s’en aller en captivité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Et le Prince qui est parmi eux, portera sur la brune son équipage sur l’épaule, et sortira; on lui percera la paroi pour le tirer par-là dehors; il couvrira son visage, afin qu’il ne voie point de ses yeux la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'J’étendrai mon rets sur lui, et il sera pris dans mes filets; et je le ferai entrer dans Babylone au pays des Caldéens, mais il ne la verra point, et il y mourra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Et je disperserai à tout vent tout ce qui est autour de lui, son secours, et toutes ses troupes; et je tirerai l’épée après eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'Et ils sauront que je suis l’Eternel, quand je les aurai répandus parmi les nations, et que je les aurai dispersés par les pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Et je laisserai de reste d’entre eux quelque peu de gens, préservés de l’épée, de la famine, et de la mortalité, afin qu’ils racontent toutes leurs abominations, parmi les nations vers lesquelles ils seront parvenus; et ils sauront que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Puis la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Fils d’homme, mange ton pain dans l’agitation, et bois ton eau en tremblant et avec inquiétude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'Puis tu diras au peuple du pays: ainsi a dit le Seigneur l’Eternel touchant les habitants de Jérusalem, à la terre d’Israël: ils mangeront leur pain avec chagrin, et ils boiront leur eau avec frayeur, parce que son pays sera désolé, étant privé de son abondance, à cause de la violence de tous ceux qui y habitent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Et les villes peuplées seront désertes, et le pays ne sera que désolation; et vous saurez que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Fils d’homme, quel est ce proverbe dont vous usez touchant la terre d’Israël, en disant: les jours seront prolongés, et toute vision périra?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'C’est pourquoi dis-leur: ainsi a dit le Seigneur l’Eternel, je ferai cesser ce proverbe, et on ne s’en servira plus pour proverbe en Israël; et dis-leur: les jours, et la parole de toute vision sont proches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Car il n’y aura plus désormais aucune vision de vanité, ni aucune divination de flatteur, au milieu de la maison d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Car moi l’Eternel, je parlerai, et la parole que j’aurai prononcée sera mise en exécution, elle ne sera plus différée; mais, ô maison rebelle! je prononcerai en vos jours la parole, et je l’exécuterai, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Fils d’homme, voici, ceux de la maison d’Israël disent: la vision que celui-ci voit n’arrivera pas de longtemps, et il prophétise pour des temps qui sont encore éloignés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'C’est pourquoi dis-leur: ainsi a dit le Seigneur l’Eternel: aucune de mes paroles ne sera plus différée, mais la parole que j’aurai prononcée sera exécutée incessamment, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Fils d’homme, prophétise contre les Prophètes d’Israël qui se mêlent de prophétiser, et dis à ces Prophètes qui prophétisent de leur propre mouvement: écoutez la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Ainsi a dit le Seigneur l’Eternel: malheur aux Prophètes insensés qui suivent leur propre esprit, et qui n’ont point eu de vision.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Israël, tes Prophètes ont été comme des renards dans les déserts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Vous n’êtes point montés aux brèches, et vous n’avez point refait les cloisons pour la maison d’Israël, afin de vous trouver au combat à la journée de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Ils ont eu des visions de vanité, et des divinations de mensonge, en disant: l’Eternel a dit; et toutefois l’Eternel ne les avait point envoyés; et ils ont fait espérer que leur parole serait accomplie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'N’avez-vous pas vu des visions de vanité, et prononcé des divinations de mensonge? cependant vous dites: l’Eternel a parlé; et je n’ai point parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: parce que vous avez prononcé la vanité, et que vous avez eu des visions de mensonge, à cause de cela j’en veux à vous, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Et ma main sera sur les Prophètes qui ont des visions de vanité, et des divinations de mensonge; ils ne seront plus admis dans le conseil de mon peuple, ils ne seront plus écrits dans les registres de la maison d’Israël, ils n’entreront plus en la terre d’Israël; et vous saurez que je suis le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Parce, oui parce qu’ils ont abusé mon peuple, en disant: Paix! et il n’ y avait point de paix. L’un bâtissait la paroi, et les autres l’enduisaient de mortier mal lié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Dis à ceux qui enduisent la paroi de mortier mal lié, qu’elle tombera; il y aura une pluie débordée, et vous, pierres de grêle, vous tomberez sur elle, et un vent de tempête la fendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'Et voici, la paroi est tombée; ne vous sera-t-il donc pas dit: où est l’enduit dont vous l’avez enduite?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: je ferai éclater en ma fureur un vent impétueux, et il y aura une pluie débordée en ma colère, et des pierres de grêle en ma fureur pour détruire entièrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Et je démolirai la paroi que vous avez enduite de mortier mal lié, je la jetterai par terre, tellement que son fondement sera découvert, et elle tombera; vous serez consumés au milieu d’elle, et vous saurez que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Ainsi je consommerai ma colère contre la paroi, et contre ceux qui l’enduisent de mortier mal lié; et je vous dirai: la paroi n’est plus, ni ceux qui l’ont enduite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'Savoir les Prophètes d’Israël, qui prophétisent touchant Jérusalem, et qui voient pour elle des visions de paix; et néanmoins il n’y a point de paix, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Aussi, toi fils d’homme, tourne ta face contre les filles de ton peuple qui prophétisent de leur propre mouvement, et prophétise contre elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'Et dis: ainsi a dit le Seigneur l’Eternel: malheur à celles qui cousent des coussins pour s’accouder le long du bras jusques aux mains, et qui font des voiles pour mettre sur la tête des personnes de toute taille, pour séduire les âmes. Séduiriez-vous les âmes de mon peuple; et vous garantiriez-vous vos âmes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Et me profaneriez-vous envers mon peuple pour des poignées d’orge, et pour des pièces de pain en faisant mourir les âmes qui ne devaient point mourir, et faisant vivre les âmes qui ne devaient point vivre, en mentant à mon peuple qui écoute le mensonge?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: voici, j’en veux à vos coussins, par lesquels vous séduisez les âmes pour les faire voler vers vous; et je déchirerai ces coussins de vos bras, et je ferai échapper les âmes que vous avez attirées afin qu’elles volent vers vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Je déchirerai aussi vos voiles, et je délivrerai mon peuple d’entre vos mains, et ils ne seront plus entre vos mains pour en faire votre chasse; et vous saurez que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Parce que vous avez affligé sans sujet le coeur du juste, lequel je ne contristais point, et que vous avez renforcé les mains du méchant, afin qu’il ne se détournât point de son mauvais train, et que je lui sauvasse la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'C’est pourquoi vous n’aurez plus aucune vision de vanité, ni aucune divination, mais je délivrerai mon peuple d’entre vos mains; et vous saurez que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Or quelques-uns des Anciens d’Israël vinrent vers moi, et s’assirent devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Et la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Fils d’homme, ces gens-ci ont posé leurs idoles dans leurs coeurs, et ont mis devant leur face l’achoppement de leur iniquité; serais- je recherché d’eux sérieusement?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'C’est pourquoi parle-leur, et leur dis: ainsi a dit le Seigneur l’Eternel. Quiconque de la maison d’Israël aura posé ses idoles dans son coeur, et aura mis devant sa face l’achoppement de son iniquité, et viendra vers le Prophète, Je suis l’Eternel, je lui ai répondu tout ce que je lui veux répondre, puisqu’il vient avec la multitude de ses idoles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'Afin que je prenne la maison d’Israël par leur propre coeur, car eux tous se sont éloignés de moi par leurs idoles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'C’est pourquoi dis à la maison d’Israël: ainsi a dit le Seigneur l’Eternel, convertissez-vous, et faites qu’on se retire de vos idoles, et détournez-vous de toutes vos abominations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Car quiconque de la maison d’Israël, ou des étrangers qui séjournent en Israël, se sera séparé de moi, et aura posé ses idoles dans son coeur, et mis l’achoppement de son iniquité devant sa face, s’il vient vers le Prophète pour m’interroger par lui, je suis l’Eternel, on lui a répondu tout ce qu’on a à lui répondre de ma part.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Et je me tournerai contre cet homme, et je le ferai servir de signe, et de jouet, et je le retrancherai du milieu de mon peuple; et vous saurez que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Et s’il arrive que le Prophète soit séduit, et qu’il profère quelque parole, moi l’Eternel j’aurai séduit ce Prophète-là, et j’étendrai ma main sur lui, et je l’exterminerai du milieu de mon peuple d’Israël;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'Et ils porteront la peine de leur iniquité; la peine de l’iniquité du Prophète sera toute telle que la peine de celui qui l’aura interrogé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'Afin que la maison d’Israël ne s’éloigne plus de moi, et qu’ils ne se souillent plus par tous leurs crimes; alors ils seront mon peuple, et je serai leur Dieu, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Puis la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Fils d’homme, lorsqu’un pays aura péché contre moi, en commettant une infidélité, et que j’aurai étendu ma main contre lui, et que je lui aurai rompu le bâton du pain, et envoyé la famine, et retranché du milieu de lui tant les hommes que les bêtes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'Et que ces trois hommes, Noé, Daniel et Job, y seraient, ils délivreraient leurs âmes par leur justice, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Si je fais passer les mauvaises bêtes par ce pays-là, et qu’elles le désolent, tellement que ce ne soit que désolation, sans qu’il y ait personne qui y passe à cause des bêtes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'Et que ces trois hommes-là s’y trouvent; je suis vivant, dit le Seigneur l’Eternel, qu’ils ne délivreront ni fils ni filles, eux seulement seront délivrés, et le pays ne sera que désolation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Ou si je fais venir l’épée sur ce pays-là, et si je dis: que l’épée passe par le pays, et qu’elle en retranche les hommes et les bêtes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'Si ces trois hommes-là se trouvent au milieu du pays, je suis vivant, dit le Seigneur l’Eternel, qu’ils ne délivreront ni fils, ni filles; mais eux seulement seront délivrés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Ou si j’envoie la mortalité sur ce pays-là, et que je répande ma colère contre lui, jusques à faire ruisseler le sang, tellement que je retranche du milieu de lui les hommes et les bêtes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'Et que Noé, Daniel et Job s’y trouvent, je suis vivant, dit le Seigneur l’Eternel, qu’ils ne délivreront ni fils ni filles; mais ils délivreront leurs âmes par leur justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Car ainsi a dit le Seigneur l’Eternel: combien plus quand j’aurai envoyé mes quatre plaies mortelles, l’épée, et la famine, et les bêtes nuisibles, et la mortalité, contre Jérusalem, pour en retrancher les hommes et les bêtes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Et toutefois, voici, quelques réchappés y demeureront de reste, savoir ceux qu’on s’en va faire sortir, et fils et filles; voici, ils viennent vers vous, et vous verrez leur train de vie, et leurs actions, et vous serez satisfaits du mal que j’aurai fait venir contre Jérusalem, et de tout ce que j’aurai fait venir sur elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'Vous en serez, dis-je, satisfaits, lorsque vous aurez vu leur train de vie, et leurs actions; et vous connaîtrez que je n’aurai point exécuté sans cause tout ce que j’aurai fait en elle, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Fils d’homme, que vaut le bois de la vigne plus que les autres bois? et les sarments plus que les branches des arbres d’une forêt?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'En prendra-t-on du bois pour en faire quelque ouvrage? ou en prendra-t-on un croc pour y pendre quelque chose?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Voici, on le met au feu pour être consumé: le feu a consumé aussitôt ses deux bouts, et le milieu est en feu; vaut-il rien pour quelque ouvrage?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Voici, quand il est entier, on n’en fait aucun ouvrage; combien moins quand le feu l’aura consumé, et qu’il sera brûlé, sera-t-il propre pour quelque ouvrage?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: comme le bois de la vigne est tel entre les arbres d’une forêt, que je l’ai assigné au feu pour être consumé; ainsi je livrerai les habitants de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Et je me tournerai contre eux; seront-ils sortis du feu? encore le feu les consumera; et vous saurez que je suis l’Eternel, quand je me serai tourné contre eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Et je ferai que le pays ne sera que désolation; parce qu’ils ont commis une infidélité, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'La parole de l’Eternel me fut aussi adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Fils d’homme, fais connaître à Jérusalem ses abominations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'Et dis: ainsi a dit le Seigneur l’Eternel à Jérusalem: tu as tiré ton extraction et ta naissance du pays des Cananéens; ton père était Amorrhéen, et ta mère, Héthienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Et quant à ta naissance, le jour que tu naquis ton nombril ne fut point coupé, tu ne fus point lavée dans l’eau, pour être nettoyée; tu ne fus point salée de sel, ni emmaillotée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Il n’y a point eu d’oeil qui ait eu pitié de toi, pour te faire aucune de ces choses, en ayant compassion de toi; mais tu fus jetée sur le dessus d’un champ, parce qu’on avait horreur de toi le jour que tu naquis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Et passant auprès de toi je te vis gisante par terre dans ton sang, et je te dis: vis dans ton sang; et je te redis encore: vis dans ton sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Je t’ai fait croître par millions, comme croît l’herbe d’un champ; et tu crûs et tu devins grande, tu parvins à une parfaite beauté; ton corps se forma et tu devins nubile, mais tu étais abandonnée et sans habits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Et je passai auprès de toi, et je te regardai, et voici ton âge était l’âge d’être mariée: et j’étendis sur toi le pan de ma robe, et je couvris ta nudité; et je te jurai, et j’entrai en alliance avec toi, dit le Seigneur l’Eternel, et tu devins mienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Et je te lavai dans l’eau, et en t’y plongeant j’ôtai le sang de dessus toi, et je t’oignis d’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Je te vêtis de broderie, je te chaussai de peaux de couleur d’hyacinthe, je te ceignis de fin lin, et je te couvris de soie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Je te parai d’ornements, je mis des bracelets en tes mains, et un collier à ton cou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'Je mis une bague sur ton front, des pendants à tes oreilles, et une couronne de gloire sur ta tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Tu fus donc parée d’or et d’argent, et ton vêtement était de fin lin, de soie, et de broderie; tu mangeas la fleur du froment, et le miel, et l’huile; et tu devins extrêmement belle, et tu prospéras jusques à régner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Et ta renommée se répandit parmi les nations à cause de ta beauté, car elle était parfaite, à cause de ma magnificence que j’avais mise sur toi, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Mais tu t’es confiée en ta beauté, et tu t’es prostituée à cause de ta renommée, et tu t’es abandonnée à tout passant pour être à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Et tu as pris de tes vêtements, et t’en es fait des hauts lieux de diverses couleurs, tels qu’il n’y en a point, ni n’y en aura de semblables, et tu t’y es prostituée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Et tu as pris tes bagues magnifiques, faites de mon or et de mon argent, que je t’avais donné, et tu t’en es fait des images d’un mâle, et tu as commis fornication avec elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Et tu as pris tes vêtements de broderie, et les en as couvertes: et tu as mis mon huile de senteurs et mon parfum devant elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Et mon pain que je t’avais donné, la fleur du froment, et l’huile, et le miel que je t’avais donné à manger, tu as mis cela devant elle en sacrifice de bonne odeur; il a été fait ainsi, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Tu as aussi pris tes fils et tes filles que tu m’avais enfantés, et tu les leur as sacrifiés pour être consumés. Est-ce peu de chose, ce qui est procédé de tes adultères;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'Que tu aies égorgé mes fils, et que tu les aies livrés pour les faire passer par le feu, à l’honneur de ces idoles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Et parmi toutes tes abominations et tes adultères, tu ne t’es point ressouvenue du temps de ta jeunesse, quand tu étais sans habits et toute découverte, et gisante par terre dans ton sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Et il est arrivé après toute ta malice, (Malheur, Malheur à toi! dit le Seigneur l’Eternel.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'Que tu t’es bâti un lieu éminent, et t’es fait des hauts lieux par toutes les places.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'A chaque bout de chemin tu as bâti un haut lieu, et tu as rendu ta beauté abominable, et tu t’es prostituée à tout passant, et tu as multiplié tes adultères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Tu t’es abandonnée aux enfants d’Egypte, tes voisins qui ont une taille avantageuse; et tu as multiplié tes adultères pour m’irriter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Et voici, j’ai étendu ma main sur toi, et j’ai diminué ton état, et je t’ai abandonnée à la volonté de celles qui te haïssaient, savoir des filles des Philistins, lesquelles ont honte de ton train qui n’est que méchanceté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Tu t’es aussi abandonnée aux enfants des Assyriens, parce que tu n’étais pas encore assouvie; et après avoir commis adultère avec eux, tu n’as point encore été assouvie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Mais tu as multiplié tes adultères dans le pays de Canaan jusques en Caldée, et tu n’as point encore pour cela été assouvie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'O! que ton coeur est lâche, dit le Seigneur l’Eternel, d’avoir fait toutes ces choses-là, qui sont les actions d’une insigne prostituée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'De t’être bâti un lieu éminent à chaque bout de chemin, et d’avoir fait ton haut lieu dans toutes les places. Et encore n’as-tu pas fait comme les femmes débauchées, en ce que tu n’as point tenu compte du salaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'Femme adultère, tu prends des étrangers au lieu de ton mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'On donne un salaire à toutes les prostituées, mais toi tu as donné à tous tes adultères les présents, que ton mari t’avait fait et tu leur as fait des présents, afin que de toutes parts ils vinssent vers toi, pour se plonger avec toi dans le crime.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Et il t’est arrivé dans tes fornications tout le contraire de ce qui arrive aux autres femmes, car personne ne te recherchant pour commettre adultère tu as donné des présents, et aucun présent ne t’a été donné; tu as donc agi tout au contraire des autres femmes de mauvaise vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'C’est pourquoi, ô adultère, écoute la parole de l’Eternel:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Ainsi a dit le Seigneur l’Eternel: parce que ton venin s’est répandu, et que dans tes excès tu t’es abandonnée à ceux que tu aimais, et à tes abominables idoles, et que tu as mis à mort tes enfants, lesquels tu leur as donnés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'A cause de cela voici, je vais assembler tous tes adultères, avec lesquels tu as pris tes plaisirs, et tous ceux que tu as aimés, avec tous ceux que tu as haïs; même je les assemblerai de toutes parts contre toi, et je découvrirai ta honte à leurs yeux et ils verront ton infamie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Et je te jugerai comme on juge les femmes adultères, et celles qui répandent le sang; et je te livrerai pour être mise à mort selon ma fureur et ma jalousie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Je te livrerai, dis-je, entre leurs mains; et ils détruiront tes lieux éminents, et démoliront tes hauts lieux; ils te dépouilleront de tes vêtements, et emporteront tes bagues dont tu te parais, et te laisseront sans habits et toute découverte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Et on fera monter contre toi un amas de gens qui t’assommeront de pierres, et qui te perceront avec leurs épées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'Puis ils mettront le feu à tes maisons, et feront ces exécutions sur toi en la présence de plusieurs femmes, et je te garderai bien de t’abandonner, et même tu ne donneras plus de salaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Et je satisferai ma fureur sur toi, tellement que ma jalousie se retirera de toi; et je serai en repos, et ne me courroucerai plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Parce que tu ne t’es point souvenue du temps de ta jeunesse, et que tu m’as provoqué par toutes ces choses-là; à cause de cela voici, j’ai fait tomber la peine de tes crimes sur ta tête, dit le Seigneur l’Eternel; et tu n’as pas fait cette réflexion dans toutes tes abominations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Voici, tous ceux qui usent de proverbe feront un proverbe de toi, en disant: telle qu’ est la mère, telle est sa fille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Tu es la fille de ta mère, qui a dédaigné son mari et ses enfants; et tu es la soeur de chacune de tes soeurs, qui ont dédaigné leurs maris et leurs enfants; votre mère était Héthienne, et votre père était Amorrhéen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Et ta grande soeur c’est Samarie, avec les villes de son ressort, laquelle se tient à ta gauche; et ta petite soeur qui se tient à ta droite, c’est Sodome avec les villes de son ressort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Et tu n’as pas seulement marché dans leurs voies, et fait selon leurs abominations, comme si c’eût été fort peu de chose, mais tu t’es corrompue plus qu’elles dans toutes tes voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Je suis vivant dit le Seigneur l’Eternel, que Sodome ta soeur, elle ni les villes de son ressort, n’ont point fait comme tu as fait, toi et les villes de ton ressort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Voici, ç’a été ici l’iniquité de Sodome ta soeur, l’orgueil, l’abondance de pain, et une molle oisiveté; elle a eu de quoi, elle et les villes de son ressort, mais elle n’a point assisté l’affligé, et le pauvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Elles se sont élevées, et ont commis abomination devant moi, et je les ai exterminées, comme j’ai vu qu’il était à propos de faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Et quant à Samarie, elle n’a pas péché la moitié autant que toi; car tu as multiplié tes abominations plus qu’elles, et tu as justifié tes soeurs par toutes les abominations que tu as commises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'C’est pourquoi aussi porte ta confusion, toi qui as jugé chacune de tes soeurs, à cause de tes péchés, par lesquels tu as été rendue plus abominable qu’elles; elles sont plus justes que toi; c’est pourquoi aussi sois honteuse, et porte ta confusion, vu que tu as justifié tes soeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Quand je ramènerai leurs captifs, les captifs, dis-je, de Sodome, et des villes de son ressort, et les captifs de Samarie, et des villes de son ressort, je ramènerai aussi les captifs de ta captivité parmi elles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'Afin que tu portes ta confusion, et que tu sois confuse à cause de tout ce que tu as fait, et que tu les consoles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Quand ta soeur Sodome, et les villes de son ressort, retourneront à leur état précédent; et quand Samarie, et les villes de son ressort, retourneront à leur état précédent, aussi toi, et les villes de ton ressort, retournerez à votre état précédent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Or ta bouche n’a point fait mention de ta soeur Sodome au jour de tes fiertés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'Avant que ta méchanceté fût découverte; comme elle le fut au temps de l’opprobre des filles de Syrie, et de toutes celles d’alentour, savoir les filles des Philistins, qui te pillèrent de tous côtés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Tu portes sur toi ton énormité et tes abominations, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Car ainsi a dit le Seigneur l’Eternel: je te ferai comme tu as fait, quand tu as méprisé l’exécration du serment, en violant l’alliance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Mais pourtant je me souviendrai de l’alliance que j’ai traitée avec toi dans les jours de ta jeunesse, et j’établirai avec toi une alliance éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Et tu te souviendras de tes voies, et en seras confuse, lorsque tu recevras tes soeurs, tant tes plus grandes, que tes plus petites, et je te les donnerai pour filles; mais non pas selon ton alliance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Car j’établirai mon alliance avec toi, et tu sauras que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'Afin que tu te souviennes de ta vie passée, que tu en sois honteuse, et que tu n’ouvres plus la bouche, à cause de ta confusion, après que j’aurai été apaisé envers toi, pour tout ce que tu auras fait, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Et la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Fils d’homme, propose une énigme, et mets en avant une similitude à la maison d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'Et dis: ainsi a dit le Seigneur l’Eternel: une grand aigle à grandes ailes, et d’un long plumage, pleine de plumes comme en façon de broderie, est venue au Liban, et a enlevé la cime d’un cèdre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Elle a rompu le bout de ses jets, et l’a transporté en un pays marchand, et l’a mis dans une ville de négociants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Et elle a pris de la semence du pays, et l’a mise en un champ propre à semer, et la portant près des grosses eaux, l’a plantée comme un saule.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Cette semence poussa, et devint un cep vigoureux, mais bas, ayant ses rameaux tournés vers cette aigle, et ses racines étant sous elle; cette semence devint donc un cep, et produisit des sarments et poussa des rejetons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Mais il y avait une autre grande aigle à grandes ailes, et de beaucoup de plumes; et voici ce cep serra vers elle ses racines, et étendit ses branches vers elle, afin qu’elle l’arrosât des eaux qui coulaient dans les carreaux de son parterre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Il était donc planté en une bonne terre, près des grosses eaux, en sorte qu’il jetait des sarments et portait du fruit, et il était devenu un cep excellent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Dis: ainsi a dit le Seigneur l’Eternel, viendra-t-il à bien? n’arrachera-t-elle pas ses racines, et ne coupera-t-elle pas ses fruits, et ils deviendront secs? tous les sarments qu’il a jetés sécheront, et il ne faudra pas même un grand effort, et beaucoup de monde, pour l’enlever de dessus ses racines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Mais voici, quoique planté, viendra-t-il pourtant à bien? Quand le vent d’Orient l’aura touché, ne séchera-t-il pas entièrement? il séchera sur le terrain où il était planté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Puis la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Dis maintenant à la maison rebelle: ne savez-vous pas ce que veulent dire ces choses? Dis: voici, le Roi de Babylone est venu à Jérusalem, et en a pris le Roi, et les Princes, et les a emmenés avec lui à Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Et il en a pris un de la race Royale, il a traité alliance avec lui, il lui a fait prêter serment avec exécration, et il a retenu les puissants du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'Afin que le Royaume fût tenu bas, et qu’il ne s’élevât point, mais qu’en gardant son alliance, il subsistât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Mais celui-ci s’est rebellé contre lui, envoyant ses messagers en Egypte, afin qu’on lui donnât des chevaux, et un grand peuple. Celui qui fait de telles choses prospérera-t-il? échappera-t-il? et ayant enfreint l’alliance, échappera-t-il?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Je suis vivant, dit le Seigneur l’Eternel, si celui-ci ne meurt au pays du Roi qui l’a établi pour Roi, parce qu’il a méprisé le serment d’exécration qu’il lui avait fait, et parce qu’il a enfreint l’alliance qu’il avait faite avec lui, si, dis-je, il ne meurt dans Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Et Pharaon ne fera rien pour lui dans la guerre, avec une grande armée et beaucoup de troupes, lorsque l’ennemi aura dressé des terrasses, et bâti des bastions pour exterminer beaucoup de gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Parce qu’il a méprisé le serment d’exécration en violant l’alliance; car voici, après avoir donné sa main, il a fait néanmoins toutes ces choses-là; il n’échappera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: je suis vivant, si je ne fais tomber sur sa tête mon serment d’exécration qu’il a méprisé, et mon alliance qu’il a enfreinte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Et j’étendrai mon rets sur lui, et il sera pris dans mes filets, et je le ferai entrer dans Babylone, et là j’entrerai en jugement contre lui pour le crime qu’il a commis contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Et tous ses fugitifs avec toutes ses troupes tomberont par l’épée, et ceux qui demeureront de reste seront dispersés à tout vent; et vous saurez que moi l’Eternel j’ai parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Ainsi a dit le Seigneur l’Eternel: je prendrai aussi un rameau de la cime de ce haut cèdre, et je le planterai; je couperai, dis- je, du bout de ses jeunes branches un tendre rameau, et je le planterai sur une montagne haute et éminente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Je le planterai sur la haute montagne d’Israël, et là il produira des branches, et fera du fruit, et il deviendra un excellent cèdre; et des oiseaux de tout plumage demeureront sous lui, et habiteront sous l’ombre de ses branches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Et tous les bois des champs connaîtront que moi l’Eternel j’aurai abaissé le grand arbre, et élevé le petit arbre, fait sécher le bois vert, et fait reverdir le bois sec; moi l’Eternel, j’ai parlé, et je le ferai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Que voulez-vous dire, vous qui usez ordinairement de ce proverbe touchant le pays d’Israël, en disant: les pères ont mangé le verjus et les dents des enfants en sont agacées?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Je suis vivant, dit le Seigneur l’Eternel, que vous n’userez plus de ce proverbe en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Voici, toutes les âmes sont à moi; l’âme de l’enfant est à moi comme l’âme du père; et l’âme qui péchera sera celle qui mourra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Mais l’homme qui sera juste, et qui fera ce qui est juste et droit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'Qui n’aura point mangé sur les montagnes, et qui n’aura point levé ses yeux vers les idoles de la maison d’Israël, et n’aura point souillé la femme de son prochain, et ne se sera point approché de la femme dans son état d’impureté,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'Et qui n’aura foulé personne, qui aura rendu le gage à son débiteur, qui n’aura point ravi le bien d’autrui, qui aura donné de son pain à celui qui avait faim, et qui aura couvert d’un vêtement celui qui était nu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'Qui n’aura point prêté à usure, et n’aura point pris de surcroît; qui aura détourné sa main de l’iniquité; qui aura rendu un droit jugement entre les parties qui plaident ensemble,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'Qui aura marché dans mes statuts, et aura gardé mes ordonnances pour agir en vérité, celui-là est juste; certainement il vivra, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Que s’il a engendré un enfant qui soit un meurtrier, répandant le sang, et commettant des choses semblables;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'Et qui ne fasse aucune de ces choses, que j’ai commandées, mais qu’il mange sur les montagnes, qu’il corrompe la femme de son prochain,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'Qu’il foule l’affligé, et le pauvre, qu’il ravisse le bien d’autrui, et qu’il ne rende point le gage, qu’il lève ses yeux vers les idoles et commette des abominations;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'Qu’il donne à usure, et qu’il prenne du surcroît: vivra-t-il? Il ne vivra pas, quand il aura commis toutes ces abominations, on le fera mourir de mort, et son sang sera sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Mais s’il engendre un fils qui voyant tous les péchés que son père aura commis, y prenne garde, et ne fasse pas de semblables choses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'Qu’il ne mange point sur les montagnes, et qu’il ne lève point ses yeux vers les idoles de la maison d’Israël, qu’il ne corrompe point la femme de son prochain;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'Et qu’il ne foule personne; qu’il ne prenne point de gages; qu’il ne ravisse point le bien d’autrui, qu’il donne de son pain à celui qui a faim, et qu’il couvre celui qui est nu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'Qu’il retire sa main de dessus l’affligé, qu’il ne prenne ni usure ni surcroît, qu’il garde mes ordonnances, et qu’il marche dans mes statuts; il ne mourra point pour l’iniquité de son père, mais certainement il vivra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Mais son père, parce qu’il a usé de fraude, et qu’il a ravi ce qui était à son frère, et fait parmi son peuple ce qui n’est pas bon, voici, il mourra pour son iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Mais, direz-vous: pourquoi un tel fils ne portera-t-il pas l’iniquité de son père? Parce qu’un tel fils a fait ce qui était juste et droit, et qu’il a gardé tous mes statuts, et les a faits; certainement il vivra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'L’âme qui péchera sera celle qui mourra. Le fils ne portera point l’iniquité du père, et le père ne portera point l’iniquité du fils; la justice du juste sera sur le juste; et la méchanceté du méchant sera sur le méchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Que si le méchant se détourne de tous ses péchés qu’il aura commis, et qu’il garde tous mes statuts, et fasse ce qui est juste et droit, certainement il vivra, il ne mourra point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Il ne lui sera point fait mention de tous ses crimes qu’il aura commis, mais il vivra pour sa justice, à laquelle il se sera adonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Prendrais-je en aucune manière plaisir à la mort du méchant, dit le Seigneur l’Eternel, et non plutôt qu’il se détourne de son train, et qu’il vive?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Mais si le juste se détourne de sa justice, et qu’il commette l’iniquité, selon toutes les abominations que le méchant a accoutumé de commettre, vivra-t-il? il ne sera point fait mention de toutes ses justices qu’il aura faites, à cause de son crime qu’il aura commis, et à cause de son péché qu’il aura fait; il mourra pour ces choses-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Et vous, vous dites: la voie du Seigneur n’est pas bien réglée. Ecoutez maintenant maison d’Israël; ma voie n’est-elle pas bien réglée? ne sont-ce pas plutôt vos voies qui ne sont pas bien réglées?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Quand le juste se détournera de sa justice, et qu’il commettra l’iniquité, il mourra pour ces choses-là; il mourra pour son iniquité qu’il aura commise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Et quand le méchant se détournera de sa méchanceté qu’il aura commise, et qu’il fera ce qui est juste et droit, il fera vivre son âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Ayant donc considéré sa conduite, et s’étant détourné de tous ses crimes qu’il aura commis, certainement il vivra, il ne mourra point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Et la maison d’Israël dira: la voie du Seigneur l’Eternel n’est pas bien réglée. Ô maison d’Israël! mes voies ne sont-elles pas bien réglées? ne sont-ce pas plutôt vos voies qui ne sont pas bien réglées?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'C’est pourquoi je jugerai un chacun de vous selon ses voies, ô maison d’Israël! dit le Seigneur. Convertissez-vous, et détournez- vous de tous vos péchés, et l’iniquité ne vous sera point en ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Jetez loin de vous tous les crimes par lesquels vous avez péché; et faites-vous un nouveau coeur, et un esprit nouveau, et pourquoi mourriez-vous, ô maison d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Car je ne prends point de plaisir à la mort de celui qui meurt, dit le Seigneur l’Eternel. Convertissez-vous donc, et vivez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'Et toi prononce à haute voix une complainte touchant les Principaux d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'Et dis: qu’était-ce de ta mère? C’était une lionne qui a gîté entre les lions, et qui a élevé ses petits parmi les lionceaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Et elle a fait croître un de ses petits, qui est devenu un lionceau, et qui a appris à déchirer la proie, tellement qu’il a dévoré les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Les nations en ont ouï parler, il a été attrapé en leur fosse; et elles l’ont emmené avec des boucles au pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Puis ayant vu qu’elle avait attendu, et que son attente était perdue, elle a pris un autre de ses petits, et elle en a fait un lionceau;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Qui marchant parmi les lions est devenu un lionceau, et a appris à déchirer la proie tellement qu’il a dévoré les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Il a désolé leurs palais, et il a ravagé leurs villes, de sorte que le pays, et tout ce qui y est, a été épouvanté par le cri de son rugissement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Et les nations ont été rangées contre lui, de toutes les Provinces, et elles ont étendu leurs rets contre lui; il a été attrapé en leur fosse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Puis ils l’ont enfermé et enchaîné, pour l’amener au Roi de Babylone, et le mettre en une forteresse, afin que sa voix ne fût plus ouïe sur les montagnes d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Ta mère était en ton sang comme une vigne plantée auprès des eaux, et elle est devenue chargée de fruits et de rameaux, à cause des grandes eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Et elle a eu des verges fortes pour en faire des sceptres de dominateurs; et son tronc s’est élevé jusqu’à ses branches touffues, et elle a été vue en sa hauteur avec la multitude de ses rameaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Mais elle a été arrachée avec fureur, et jetée par terre; et le vent d’Orient a séché son fruit; ses verges fortes ont été rompues, et ont séché; le feu les a consumées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Et maintenant elle est plantée au désert, en une terre sèche et aride.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Et le feu est sorti d’une verge de ses branches, et a consumé son fruit, et il n’y a point eu en elle de verge forte pour en faire un sceptre à dominer. C’est ici la complainte, et on s’en servira pour complainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Or il arriva la septième année, au dixième jour du cinquième mois, que quelques-uns des Anciens d’Israël vinrent pour consulter l’Eternel, et s’assirent devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Et la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Fils d’homme, parle aux Anciens d’Israël, et leur dis: ainsi a dit le Seigneur l’Eternel: est-ce pour me consulter que vous venez? Je suis vivant, dit le Seigneur l’Eternel, si vous me consultez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Ne les jugeras-tu pas, ne les jugeras-tu pas, fils d’homme? donne- leur à connaître les abominations de leurs pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'Et leur dis: ainsi a dit le Seigneur l’Eternel: le jour que j’élus Israël, et que je levai ma main à la postérité de la maison de Jacob, et que je me donnai à connaître à eux au pays d’Egypte, et que je leur levai ma main, en disant: Je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'En ce jour-là même je leur levai ma main, que je les tirerais hors du pays d’Egypte, pour les amener au pays que j’avais découvert pour eux, pays découlant de lait et de miel, et qui est la noblesse de tous les pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Alors je leur dis: que chacun de vous rejette de devant ses yeux les abominations, et ne vous souillez point par les idoles d’Egypte; je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Mais ils se rebellèrent contre moi, et ils n’agréèrent point de m’écouter; pas un d’eux ne rejeta de devant ses yeux les abominations, ni ne quitta les idoles d’Egypte; et je dis que je répandrais ma fureur sur eux, et que je consommerais ma colère sur eux au pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Mais ce que je les ai tirés hors du pays d’Egypte, je l’ai fait pour l’amour de mon Nom, afin qu’il ne fût point profané en la présence des nations parmi lesquelles ils étaient, et en la présence desquelles je m’étais donné à connaître à eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Je les tirai donc hors du pays d’Egypte, et les amenai au désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'Et je leur donnai mes statuts, et leur fis connaître mes ordonnances, lesquelles si l’homme accomplit, il vivra par elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Je leur donnai aussi mes Sabbats, pour être un signe entre moi et eux, afin qu’ils connussent que je suis l’Eternel qui les sanctifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Mais ceux de la maison d’Israël se rebellèrent contre moi au désert, ils ne marchèrent point dans mes statuts, mais ils rejetèrent mes ordonnances; lesquelles si l’homme accomplit il vivra par elles; et ils profanèrent extrêmement mes Sabbats; c’est pourquoi je dis que je répandrais sur eux ma fureur au désert pour les consumer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Et je l’ai fait pour l’amour de mon Nom, afin qu’il ne fût point profané devant les nations, en la présence desquelles je les avais tirés d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Et même je leur levai ma main au désert que je ne les amènerais point au pays que je leur avais donné, pays découlant de lait et de miel, et qui est la noblesse de tous les pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'Parce qu’ils avaient rejeté mes ordonnances, qu’ils n’avaient point marché dans mes statuts, et qu’ils avaient profané mes Sabbats; car leur coeur marchait après leurs idoles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Toutefois mon oeil les épargna pour ne les détruire point, et je ne les consumai point entièrement au désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Mais je dis à leurs enfants au désert: ne marchez point dans les statuts de vos pères, et ne gardez point leurs ordonnances, et ne vous souillez point par leurs idoles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Je suis l’Eternel votre Dieu; marchez dans mes statuts, et gardez mes ordonnances, et les faites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'Sanctifiez mes Sabbats, et ils seront un signe entre moi et vous, afin que vous connaissiez que je suis l’Eternel votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Mais les enfants se rebellèrent aussi contre moi, et ils ne marchèrent point dans mes statuts, et ne gardèrent point mes ordonnances pour les faire; lesquelles si l’homme accomplit, il vivra par elles; et ils profanèrent mes Sabbats; c’est pourquoi je dis que je répandrais ma fureur sur eux, et que je consommerais ma colère sur eux au désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Toutefois je retirai ma main, et je le fis pour l’amour de mon Nom, afin qu’il ne fût point profané devant les nations, en la présence desquelles je les avais tirés d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Et néanmoins je leur levai ma main au désert, que je les répandrais parmi les nations, et que je les disperserais dans les pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'Parce qu’ils n’avaient point accompli mes ordonnances, et qu’ils avaient rejeté mes statuts, et profané mes Sabbats, et que leurs yeux étaient attachés aux idoles de leurs pères,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'A cause de cela je leur ai donné des statuts qui n’étaient pas bons, et des ordonnances par lesquelles ils ne vivraient point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'Et je les ai souillés en leurs dons, en ce qu’ils ont fait passer par le feu tous les premiers-nés, afin que je les misse en désolation, et afin que l’on connût que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'C’est pourquoi, toi fils d’homme, parle à la maison d’Israël, et leur dis: ainsi a dit le Seigneur l’Eternel: vos pères m’ont encore outragé, en ce qu’ils ont commis un tel crime contre moi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'C’est que les ayant introduits au pays, touchant lequel j’avais levé ma main pour le leur donner, ils ont regardé toute haute colline, et tout arbre branchu, et ils y ont fait leurs sacrifices, ils y ont posé leur oblation pour m’irriter, ils y ont mis leurs parfums, et ils y ont répandu leurs aspersions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Et je leur ai dit: que veulent dire ces hauts lieux auxquels vous allez? et toutefois leur nom a été appelé hauts lieux jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'C’est pourquoi dis à la maison d’Israël: ainsi a dit le Seigneur l’Eternel: ne vous souillez-vous pas dans le train de vos pères, et ne vous prostituez-vous point à leurs idoles abominables?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Et en offrant vos dons, quand vous faites passer vos enfants par le feu; vous vous souillez par toutes vos idoles jusqu’à ce jour. Est-ce ainsi que vous me consultez, ô maison d’Israël? Je suis vivant, dit le Seigneur l’Eternel, que vous ne me consultez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Et ce que vous pensez n’arrivera nullement, en ce que vous dites: nous serons comme les nations, et comme les familles des pays, en servant le bois et la pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Je suis vivant, dit le Seigneur l’Eternel, si je ne règne sur vous avec une main forte, et un bras étendu, et avec effusion de colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'Et si je ne vous tire d’entre les peuples, et ne vous rassemble hors des pays dans lesquels vous aurez été dispersés avec une main forte, et un bras étendu et avec effusion de colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'Et si je ne vous fais venir au désert des peuples, et si je ne conteste là contre vous, face à face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Comme j’ai contesté contre vos pères au désert du pays d’Egypte, ainsi contesterai-je contre vous, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'Et je vous ferai passer sous la verge, et vous ramènerai au lieu de l’alliance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'Et je mettrai à part d’entre vous les rebelles, et ceux qui se révoltent contre moi; et je les ferai sortir du pays auquel ils séjournent, mais ils n’entreront point en la terre d’Israël; et vous saurez que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Vous donc, ô maison d’Israël! ainsi a dit le Seigneur l’Eternel, allez, servez chacun vos idoles, même puisque vous ne me voulez pas écouter; aussi ne profanerez-vous plus le Nom de ma sainteté par vos dons, et par vos idoles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Mais ce sera en ma sainte montagne, en la haute montagne d’Israël, dit le Seigneur l’Eternel, que toute la maison d’Israël me servira, dans toute cette terre; je prendrai là plaisir en eux, et là je demanderai vos offrandes élevées, et les prémices de vos dons, avec toutes vos choses sanctifiées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Je prendrai plaisir en vous par vos agréables odeurs, quand je vous aurai retirés d’entre les peuples, et que je vous aurai rassemblés des pays dans lesquels vous aurez été dispersés; et je serai sanctifié en vous, les nations le voyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Et vous saurez que je suis l’Eternel, quand je vous aurai fait revenir en la terre d’Israël, qui est le pays touchant lequel j’ai levé ma main pour le donner à vos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Et là vous vous souviendrez de vos voies, et de toutes vos actions, par lesquelles vous vous êtes souillés; et vous vous déplairez en vous-mêmes de tous vos maux que vous aurez faits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Et vous saurez que je suis l’Eternel, par tout ce que j’aurai fait envers vous, à cause de mon Nom, et non pas selon vos méchantes voies, et vos actions corrompues, ô maison d’Israël! dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Fils d’homme, tourne ta face vers le chemin de Théman, et fais découler ta parole vers le Midi, et prophétise contre la forêt du champ du Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'Et dis à la forêt du Midi: écoute la parole de l’Eternel. Ainsi a dit le Seigneur l’Eternel: voici, je m’en vais allumer au dedans de toi un feu qui consumera tout bois vert et tout bois sec au dedans de toi; la flamme de l’embrasement ne s’éteindra point, et tout le dessus en sera brûlé, depuis le Midi jusqu’au Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Et toute chair verra que moi l’Eternel j’y ai allumé le feu; et il ne s’éteindra point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Et je dis: ha! ha! Seigneur Eternel, ils disent de moi: n’est- il pas vrai que celui-ci ne fait que mettre en avant des similitudes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Et la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'Fils d’homme, tourne ta face vers Jérusalem, et fais découler ta parole vers les saints lieux, et prophétise contre la terre d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Et dis à la terre d’Israël: ainsi a dit l’Eternel: voici, j’en veux à toi, et je tirerai mon épée de son fourreau, et je retrancherai du milieu de toi le juste et le méchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Parce que je retrancherai du milieu de toi le juste et le méchant, à cause de cela mon épée sortira de son fourreau contre toute chair, depuis le Midi jusqu’au Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Et toute chair saura que moi l’Eternel j’aurai tiré mon épée de son fourreau, et elle n’y retournera plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Aussi toi, fils d’homme gémis en te rompant les reins de douleur, et soupire avec amertume en leur présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Et quand ils te diront: pourquoi gémis-tu? alors tu répondras: c’est à cause du bruit, car il vient, et tout coeur se fondra, et toutes les mains deviendront lâches, et tout esprit sera étourdi, et tous les genoux se fondront en eau; voici, il vient, et il sera accompli, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Puis la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Fils d’homme, prophétise, et dis: ainsi a dit l’Eternel: dis, l’épée, l’épée a été aiguisée, et elle est aussi fourbie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Elle a été aiguisée pour faire un grand carnage, elle a été fourbie afin qu’elle brille: nous réjouirons-nous? C’ est la verge de mon fils; elle dédaigne tout bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Et l’Eternel l’a donnée à fourbir, afin qu’on la tienne à la main; l’épée a été aiguisée, et elle a été fourbie pour la mettre en la main du destructeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Crie et hurle, fils d’homme, car elle est contre mon peuple, elle est contre tous les principaux d’Israël; les frayeurs de l’épée seront sur mon peuple; c’est pourquoi frappe sur ta cuisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Quand ce serait une épreuve, et que serait-ce? Si même cette épée qui dédaigne tout bois, était une verge, il n’en serait rien, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'Toi donc, fils d’homme, prophétise, et frappe d’une main contre l’autre, et que l’épée soit redoublée pour la troisième fois, l’épée des tués est l’épée contre les grands qui seront tués, passant jusqu’à eux dans leurs cabinets.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'J’ai mis à toutes leurs portes l’épée luisante, afin que le coeur se fonde, et que les ruines soient multipliées. Ah! elle est faite pour briller et réservée pour tuer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Joins-toi épée, frappe à la droite; avance-toi, frappe à la gauche, à quelque côté que tu te rencontres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Je frapperai aussi d’une main contre l’autre, et je satisferai ma colère: moi l’Eternel j’ai parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Et la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Et toi, fils d’homme, propose-toi deux chemins par où l’épée du Roi de Babylone pourrait venir, et que les deux chemins sortent d’un même pays, et les choisis, choisis-les à l’endroit où commence le chemin de la ville de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Tu te proposeras le chemin par lequel l’épée doit venir contre Rabba des enfants de Hammon, et le chemin qui va en Judée, et à Jérusalem, ville forte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Car le Roi de Babylone s’est arrêté dans un chemin fourchu, au commencement de deux chemins, pour consulter les devins; il a poli les flèches; il a interrogé les Théraphims; il a regardé au foie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Dans sa main droite est la divination contre Jérusalem, pour y disposer les béliers, pour publier la tuerie, pour crier l’alarme à haute voix, pour ranger les béliers contre les portes, pour dresser des terrasses, et bâtir des forts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Mais ce leur sera comme qui devinerait faussement en leur présence; il y a de grands serments entre eux, mais il va rappeler le souvenir de leur iniquité, afin qu’on y soit surpris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: parce que vous avez fait revenir le souvenir de votre iniquité, lorsque vos crimes se sont découverts, tellement que vos péchés se voient dans toutes vos actions; parce, dis-je, que vous avez fait qu’on se souvienne de vous, vous serez surpris avec la main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Et toi profane, méchant, Prince d’Israël, le jour duquel est venu au temps de l’iniquité, ce qui fera sa fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'Ainsi a dit le Seigneur l’Eternel, qu’on ôte cette tiare, et qu’on enlève cette couronne: ce ne sera plus celle-ci; j’élèverai ce qui est bas, et j’abaisserai ce qui est haut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Je la mettrai à la renverse, à la renverse, à la renverse, et elle ne sera plus, jusqu’à ce que vienne celui auquel appartient le gouvernement, et je le lui donnerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 33, 'Et toi, fils d’homme, prophétise, et dis: ainsi a dit le Seigneur l’Eternel touchant les enfants de Hammon, et touchant leur opprobre; dis donc, épée, épée dégainée, fourbie pour faire la tuerie, pour consumer avec son éclat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 34, 'Pendant qu’on voit pour toi des visions de vanité, et qu’on devine pour toi le mensonge, afin qu’on te mette sur le cou des méchants qui sont mis à mort; le jour desquels est venu au temps de l’iniquité, ce qui sera sa fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 35, 'La remettrait-on dans son fourreau? je te jugerai sur le lieu auquel tu as été créé, au pays de ton extraction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 36, 'Je répandrai mon indignation sur toi, j’allumerai sur toi le feu de ma fureur, et je te livrerai entre les mains d’hommes brutaux, et forgeurs de destruction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 37, 'Tu seras destiné au feu pour être dévoré; ton sang sera au milieu de la terre: on ne se souviendra plus de toi, car c’est moi l’Eternel, qui ai parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'Et toi, fils d’homme, ne jugeras-tu pas, ne jugeras-tu pas la ville sanguinaire, et ne lui donneras-tu pas à connaître toutes ses abominations?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Tu diras donc, ainsi a dit le Seigneur l’Eternel: ville qui répands le sang au dedans de toi, afin que ton temps vienne, et qui as fait des idoles à ton préjudice, pour en être souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Tu t’es rendue coupable par ton sang que tu as répandu, et tu t’es souillée par tes idoles que tu as faites; tu as fait approcher tes jours, et tu es venue jusqu’à tes ans; c’est pourquoi je t’ai exposée en opprobre aux nations, et en dérision à tous les pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Celles qui sont près de toi, et celles qui en sont loin, se moqueront de toi, infâme de réputation, et remplie de troubles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Voici, les Princes d’Israël ont contribué au dedans de toi, chacun selon sa force, à répandre le sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'On a méprisé père et mère au dedans de toi; on a usé de tromperie à l’égard de l’étranger au dedans de toi; on a opprimé l’orphelin et la veuve au dedans de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Tu as méprisé mes choses saintes, et profané mes Sabbats.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Des gens médisants ont été au dedans de toi pour répandre le sang, et ceux qui sont au dedans de toi ont mangé sur les montagnes; on a commis des actions énormes au milieu de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'L’enfant a découvert la nudité du père au dedans de toi, et on a humilié au dedans de toi la femme dans le temps de sa souillure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Et l’un a commis abomination avec la femme de son prochain; et l’autre en commettant des actions énormes a souillé sa belle-fille; et l’autre a humilié sa soeur, fille de son père, au dedans de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'On a reçu au dedans de toi des présents pour répandre le sang; tu as pris de l’usure et du surcroît; et tu as fait un gain déshonnête sur tes prochains, en usant de tromperie; et tu m’as oublié, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Et voici, j’ai frappé de mes mains l’une contre l’autre à cause de ton gain déshonnête que tu as fait, et à cause de ton sang qui a été répandu au dedans de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Ton coeur pourra-t-il tenir ferme? ou tes mains seront-elles fortes aux jours que j’agirai contre toi? moi l’Eternel j’ai parlé, et je le ferai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Et je te disperserai parmi les nations, je te vannerai par les pays, et je consumerai ta souillure, jusqu’à ce qu’il n’y en ait plus en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Et tu seras partagée en toi-même en la présence des nations, et tu sauras que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Puis la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Fils d’homme: la maison d’Israël m’est devenue comme de l’écume; eux tous sont de l’airain, de l’étain, du fer et du plomb dans un creuset; ils sont devenus comme une écume d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: parce que vous êtes tous devenus comme de l’écume, voici, je vais à cause de cela vous assembler au milieu de Jérusalem,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Comme qui assemblerait de l’argent, de l’airain, du fer, du plomb, et de l’étain dans un creuset, afin d’y souffler le feu pour les fondre; je vous assemblerai ainsi en ma colère, et en ma fureur, je me satisferai, et je vous fondrai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Je vous assemblerai donc, je soufflerai contre vous le feu de ma fureur, et vous serez fondus au milieu de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Comme l’argent se fond dans le creuset, ainsi vous serez fondus au milieu d’elle, et vous saurez que moi l’Eternel j’ai répandu ma fureur sur vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Fils d’homme, dis-lui: tu es une terre qui n’a pas été nettoyée ni mouillée de pluie au jour de l’indignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Il y a un complot de ses Prophètes au milieu d’elle; ils seront comme des lions rugissants, qui ravissent la proie: ils ont dévoré les âmes; ils ont emporté les richesses, et la gloire; ils ont multiplié les veuves au milieu d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Ses Sacrificateurs ont fait violence à ma Loi; et ont profané mes choses saintes; ils n’ont point mis différence entre la chose sainte et la profane, ils n’ont point donné à connaître la différence qu’il y a entre la chose immonde et la nette, et ils ont caché leurs yeux de mes Sabbats, et j’ai été profané au milieu d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Ses principaux ont été au milieu d’elle comme des loups qui ravissent la proie, pour répandre le sang et pour détruire les âmes, pour s’adonner au gain déshonnête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Ses Prophètes aussi les ont enduits de mortier mal lié; ils ont des visions fausses, et ils leur devinent le mensonge, en disant: ainsi a dit le Seigneur l’Eternel; et cependant l’Eternel n’avait point parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Le peuple du pays a usé de tromperies, et ils ont ravi le bien d’autrui, et ont opprimé l’affligé et le pauvre, et ont foulé l’étranger contre tout droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Et j’ai cherché quelqu’un d’entre eux qui refît la cloison, et qui se tînt à la brèche devant moi pour le pays, afin que je ne le détruisisse point; mais je n’en ai point trouvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'C’est pourquoi je répandrai sur eux mon indignation, et je les consumerai par le feu de ma fureur; je ferai tomber la peine de leur train sur leur tête, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Fils d’homme, il y a eu deux femmes, filles d’une même mère,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Qui se sont prostituées en Egypte, elles se sont abandonnées dans leur jeunesse: là leur sein fut déshonoré et leur virginité flétrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Et c’étaient ici leurs noms, celui de la plus grande était Ahola, et celui de sa soeur, Aholiba; elles étaient à moi, et elles ont enfanté des fils et des filles; leurs noms donc étaient Ahola, qui était Samarie; et Aholiba, qui est Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Or Ahola a commis adultère étant ma femme, et s’est rendue amoureuse de ses amoureux, c’est-à-dire, des Assyriens ses voisins;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'Vêtus de pourpre, gouverneurs, et magistrats, tous jeunes et aimables, tous cavaliers, montés sur des chevaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Et elle a commis ses adultères avec eux, qui tous étaient l’élite des enfants des Assyriens, et avec tous ceux de qui elle s’est rendue amoureuse, et s’est souillée avec toutes leurs idoles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Elle n’a pas même quitté ses fornications qu’elle avait apportées d’Egypte, où l’on avait couché avec elle dans sa jeunesse, où l’on avait déshonoré sa virginité et où ils s’étaient livrés à l’impureté avec elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'C’est pourquoi je l’ai livrée entre les mains de ses amoureux, entre les mains, dis-je, des enfants des Assyriens, dont elle s’était rendue amoureuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Ils l’ont couverte d’opprobre, ils ont enlevé ses fils et ses filles, et l’ont tuée elle-même avec l’épée, et elle a été fameuse entre les femmes, après qu’ils ont exercé des jugements sur elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Et quand sa soeur Aholiba a vu cela, elle a fait pis qu’elle dans ses amours; même elle a fait pis dans ses débauches, que sa soeur n’avait fait dans les siennes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Elle s’est rendue amoureuse des enfants des Assyriens, des gouverneurs et des magistrats ses voisins, vêtus magnifiquement, et des cavaliers montés sur des chevaux, tous jeunes et bien faits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Et j’ai vu qu’elle s’était souillée, et que c’était un même train de toutes les deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Et encore a-t-elle augmenté ses impudicités, car ayant vu des hommes portraits sur la paroi, les images des Caldéens, peints de vermillon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'Ceints de baudriers sur leurs reins, et ayant des habillements de tête flottants et teints, eux tous ayant l’apparence de grands Seigneurs, et la ressemblance des enfants de Babylone en Caldée; terre de leur naissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'Elle s’en est rendue amoureuse par le regard de ses yeux, et a envoyé des messagers vers eux au pays des Caldéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Et les enfants de Babylone sont venus vers elle au lit de ses prostitutions, et l’ont souillée par leurs adultères; et elle s’est aussi souillée avec eux; et après cela son coeur s’est détaché d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Elle a donc manifesté ses fornications et fait connaître son opprobre; et mon coeur s’est détaché d’elle, comme mon coeur s’était détaché de sa soeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Car elle a multiplié ses adultères, jusqu’à rappeler le souvenir des jours de sa jeunesse, auxquels elle s’était abandonnée au pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'Et s’est rendue amoureuse de leurs fornicateurs, la chair desquels est comme la chair des ânes; et dont la force égale celle des chevaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Tu as donc repris les actions de ta jeunesse, lorsque tu as été déshonorée, depuis que tu étais en Egypte, à cause du sein de ta jeunesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'C’est pourquoi, ô Aholiba, ainsi a dit le Seigneur l’Eternel: voici, je m’en vais réveiller contre toi tous tes amoureux, desquels ton coeur s’est détaché, et je les amènerai contre toi tout à l’environ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Savoir les enfants de Babylone, et tous les Caldéens, Pekod, Soah, Koah, et tous les Assyriens avec eux, tous jeunes gens d’élite, gouverneurs et magistrats, grands Seigneurs, et renommés, tous montant à cheval.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Et ils viendront contre toi avec des chars, des chariots, et des charrettes, et avec un grand amas de peuples; et ils emploieront contre toi de toutes parts, des écus, des boucliers, et des casques, et je leur mettrai le jugement en main, et ils te jugeront selon leur jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Et je mettrai ma jalousie contre toi, et ils agiront contre toi avec fureur; ils te retrancheront le nez et les oreilles; et ce qui sera demeuré de reste en toi tombera par l’épée. Ils enlèveront tes fils et tes filles; et ce qui sera demeuré de reste en toi sera dévoré par le feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Ils te dépouilleront de tes vêtements, et enlèveront les ornements dont tu te pares.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Et je ferai cesser en toi ton énormité, et ta fornication que tu as apportée du pays d’Egypte, et tu ne lèveras plus tes yeux vers eux, et ne te souviendras plus de l’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Car ainsi a dit le Seigneur l’Eternel: voici, je vais te livrer en la main de ceux que tu hais, en la main de ceux de qui ton coeur s’est détaché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'Ils te traiteront avec haine, et enlèveront tout ton travail, et te laisseront sans habits et découverte, et la turpitude de tes adultères, et de ton énormité, et de tes fornications, sera découverte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'On te fera ces choses-là parce que tu t’es prostituée aux nations, avec lesquelles tu t’es souillée par leurs idoles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Tu as marché dans le chemin de ta soeur, c’est pourquoi je mettrai sa coupe en ta main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Ainsi a dit le Seigneur l’Eternel: tu boiras la coupe profonde et large de ta soeur qui sera une coupe d’une grande mesure; tu seras en dérision et en moquerie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Tu seras remplie d’ivresse et de douleur, par la coupe de désolation et de dégât, qui est la coupe de ta soeur Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Tu la boiras, et la suceras, et tu briseras ses vaisseaux de terre et tu déchireras ton sein: car j’ai parlé, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: parce que tu m’as mis en oubli, et que tu m’as jeté derrière ton dos, aussi porteras-tu la peine de ton énormité, et de tes adultères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Puis l’Eternel me dit: fils d’homme, ne jugeras-tu pas Ahola et Aholiba? déclare-leur donc leurs abominations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Déclare-leur comment elles ont commis adultère et comment il y a du sang dans leurs mains; comment, dis-je, elles ont commis adultère avec leurs idoles, et ont même fait passer par le feu leurs enfants pour les consumer, ces enfants qu’elles m’avaient enfantés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Voici encore ce qu’elles m’ont fait; elles ont souillé mon saint lieu ce même jour-là, et ont profané mes Sabbats.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Car après avoir égorgé leurs enfants à leurs idoles, elles sont entrées ce même jour-là dans mon saint lieu pour le profaner; et voilà, comment elles ont fait au milieu de ma maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Et qui plus est, elles ont envoyé vers des hommes d’un pays éloigné, qui sont venus aussitôt que les messagers leur ont été envoyés; et pour l’amour d’eux tu t’es lavée, et tu as fardé ton visage, et t’es parée d’ornement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'Et t’es assise sur un lit honorable, devant lequel a été apprêtée une table, sur laquelle tu as mis mon parfum, et mon huile de senteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Et il y a eu en elle le bruit d’une troupe de gens qui sont à leur aise; et outre ces hommes-là, tant il y a eu de gens, on a fait venir des Sabéens du désert, qui ont mis des bracelets en leurs mains, et des couronnes magnifiques sur leurs têtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Et j’ai dit touchant celle qui avait vieilli dans l’adultère: Maintenant ses impudicités prendront fin, et elle aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Et toutefois on est venu vers elle, comme on vient vers une femme prostituée; ils sont ainsi venus vers Ahola, et vers Aholiba, femmes pleines d’énormité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Les hommes justes donc les jugeront comme on juge les femmes adultères, et comme on juge celles qui répandent le sang; car elles sont adultères, et le sang est en leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: qu’on fasse monter l’assemblée contre elles, et qu’elles soient abandonnées au tumulte et au pillage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'Et que l’assemblée les assomme de pierres, et les taille en pièces avec leurs épées; qu’ils tuent leurs fils et leurs filles, et qu’ils brûlent au feu leurs maisons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Et ainsi j’abolirai du pays l’énormité, et toutes les femmes seront enseignées à ne faire point selon votre énormité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'On mettra votre énormité sur vous, et vous porterez les péchés de vos idoles; et vous saurez que je suis le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Or en la neuvième année, au dixième jour du dixième mois, la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Fils d’homme, écris-toi le nom de ce jour, de ce propre jour; car en ce même jour le Roi de Babylone s’est approché contre Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Mets donc en avant une similitude à la maison rebelle, et leur dis: Ainsi a dit le Seigneur l’Eternel: mets, mets la chaudière, et verse de l’eau dedans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Assemble ses pièces dans elle, toutes les bonnes pièces, la cuisse, et l’épaule, et la remplis des meilleurs os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Prends la meilleure bête du troupeau, et fais brûler des os sous la chaudière, fais-la bouillir à gros bouillons, et que les os cuisent dans elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Car ainsi a dit le Seigneur l’Eternel: malheur à la ville sanguinaire, à la chaudière dans laquelle est son écume, et de laquelle l’écume n’est point sortie; vide-la pièce après pièce; et que le sort ne soit point jeté sur elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Parce que son sang est au milieu d’elle, qu’elle l’a mis sur la pierre sèche, et qu’elle ne l’a point répandu sur la terre pour le couvrir de poussière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'J’ai mis son sang sur une pierre sèche, afin qu’il ne soit point couvert, pour faire monter la fureur, et pour en prendre vengeance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: malheur à la ville sanguinaire; j’en ferai aussi un grand tas de bois à brûler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Amasse beaucoup de bois, allume le feu, fais cuire la chair entièrement, et la fais consumer, et que les os soient brûlés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Puis mets sur les charbons ardents la chaudière toute vide, afin qu’elle s’échauffe, et que son airain se brûle, et que son ordure soit fondue au dedans d’elle, et que son écume soit consumée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Elle m’a travaillé par des mensonges, et sa grosse écume n’est point sortie d’elle; son écume s’en ira au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'Il y a de l’énormité en ta souillure; car je t’avais purifiée, et tu n’as point été nette; tu ne seras point encore nettoyée de ta souillure, jusqu’à ce que j’aie satisfait ma fureur sur toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Moi l’Eternel j’ai parlé, cela arrivera, et je le ferai; et je ne me retirerai point en arrière, je n’épargnerai point, et je ne serai point apaisé. On t’a jugée selon ton train, et selon tes actions, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Et la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Fils d’homme, voici, je vais t’ôter par une plaie ce que tes yeux voient avec le plus de plaisir; mais n’en mène point de deuil, et ne pleure point, ne fais point couler tes larmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Garde-toi de gémir, et ne mène point le deuil qu’on a accoutumé de mener sur les morts; laisse ton bonnet sur ta tête, et mets tes souliers à tes pieds, et ne cache point la lèvre de dessus, et ne mange point le pain des autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Je parlai donc au peuple le matin, et ma femme mourut le soir; et le lendemain matin je fis comme il m’avait été commandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'Et le peuple me dit: ne nous déclareras-tu point ce que nous signifient ces choses-là que tu fais?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Et je leur répondis: la parole de l’Eternel m’a été adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Dis à la maison d’Israël: ainsi a dit le Seigneur l’Eternel: voici, je m’en vais profaner mon Sanctuaire, la magnificence de votre force, ce qui est le plus agréable à vos yeux, ce que vous voudriez qu’on épargnât sur toutes choses; et vos fils et vos filles, que vous aurez laissés, tomberont par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Vous ferez alors comme j’ai fait; vous ne couvrirez point vos lèvres, et vous ne mangerez point le pain des autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'Et vos bonnets seront sur vos têtes, et vos souliers à vos pieds; vous ne mènerez point de deuil, ni ne pleurerez; mais vous fondrez à cause de vos iniquités, et vous gémirez les uns avec les autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Et Ezéchiel vous sera pour un signe; vous ferez selon toutes les choses qu’il a faites; et quand cela sera arrivé, vous connaîtrez que je suis le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Et quant à toi, fils d’homme, au jour que je leur ôterai leur force, la joie de leur ornement, l’objet le plus agréable à leurs yeux, et l’objet de leurs coeurs, leurs fils et leurs filles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'En ce même jour-là quelqu’un qui sera échappé ne viendra-t-il pas vers toi pour te le raconter?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'En ce jour-là ta bouche sera ouverte envers celui qui sera échappé, et tu parleras, et ne seras plus muet; ainsi tu leur seras pour un signe, et ils sauront que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Puis la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Fils d’homme, tourne ta face vers les enfants de Hammon, et prophétise contre eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'Et dis aux enfants de Hammon: écoutez la parole du Seigneur l’Eternel. Parce que vous avez dit: ha! ha! contre mon Sanctuaire, à cause qu’il était profané; et contre la terre d’Israël, parce qu’elle était désolée; et contre la maison de Juda, parce qu’ils allaient en captivité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'A cause de cela voici, je m’en vais te donner en héritage aux enfants d’Orient, et ils bâtiront des palais dans tes villes, et ils demeureront chez toi; ils mangeront tes fruits et boiront ton lait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Et je livrerai Rabba pour être le repaire des chameaux, et le pays des enfants de Hammon pour être le gîte des brebis; et vous saurez que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Car ainsi a dit le Seigneur l’Eternel: parce que tu as frappé des mains, et que tu as battu des pieds, et que tu t’es réjouie de bon coeur dans tout le mépris que tu as eu pour la terre d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'A cause de cela voici, j’ai étendu ma main sur toi, et je te livrerai pour être pillée par les nations, et je te retrancherai d’entre les peuples, je te ferai périr d’entre les pays; je te détruirai; et tu sauras que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Ainsi a dit le Seigneur l’Eternel: parce que Moab et Séhir ont dit: voici, la maison de Juda est comme toutes les autres nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'A cause de cela voici, je m’en vais ouvrir le quartier de Moab du côté des villes, du côté, dis-je, de ses villes frontières, la noblesse du pays de Bethjésimoth, de Bahal-Méhon et de Kirjathajim,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'Aux enfants d’Orient, qui sont au delà du pays des enfants de Hammon, lequel je leur ai donné en héritage, afin qu’on ne se souvienne plus des enfants de Hammon parmi les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'J’exercerai aussi des jugements contre Moab, et ils sauront que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Ainsi a dit le Seigneur l’Eternel: à cause de ce qu’Edom a fait quand il s’est inhumainement vengé de la maison de Juda, et parce qu’il s’est rendu fort coupable en se vengeant d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'A cause de cela, le Seigneur l’Eternel dit ainsi: j’étendrai ma main sur Edom, j’en retrancherai les hommes et les bêtes, et je le réduirai en désert; depuis Théman et de devers Dédan ils tomberont par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'J’exercerai ma vengeance sur Edom à cause de mon peuple d’Israël, et on traitera Edom selon ma colère, et selon ma fureur, et ils sentiront ce que c’est que de ma vengeance, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Ainsi a dit le Seigneur l’Eternel: à cause que les Philistins ont agi par vengeance, et qu’ils se sont inhumainement vengés avec plaisir et avec mépris, jusqu’à tout détruire par une inimitié immortelle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'A cause de cela le Seigneur l’Eternel dit ainsi: voici, je m’en vais étendre ma main sur les Philistins, j’exterminerai les Kéréthiens, et je ferai périr le reste de leurs ports de mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'Et je déploierai sur eux de grandes vengeances par des châtiments de fureur; et ils sauront que je suis l’Eternel, quand j’aurai exécuté sur eux ma vengeance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'Et il arriva en l’onzième année, le premier jour du mois, que la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Fils d’homme, parce que Tyr a dit touchant Jérusalem: ha! ha! celle qui était la porte des peuples a été rompue, elle s’est réfugiée chez moi, je serai remplie parce qu’elle a été rendue déserte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'A cause de cela ainsi a dit le Seigneur l’Eternel: voici, j’en veux à toi, Tyr, et je ferai monter contre toi plusieurs nations, comme la mer fait monter ses flots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Et elles détruiront les murailles de Tyr, et démoliront ses tours; je raclerai sa poudre, et la rendrai semblable à une pierre sèche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Elle servira à étendre les filets au milieu de la mer; car j’ai parlé, dit le Seigneur l’Eternel, et elle sera en pillage aux nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'Et les villes de son ressort, qui sont à la campagne, seront mises au fil de l’épée, et elles sauront que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Car ainsi a dit le Seigneur l’Eternel: voici je m’en vais faire venir de l’Aquilon contre Tyr, Nébucadnetsar, Roi de Babylone, le Roi des Rois, avec des chevaux, et des chariots, et des gens de cheval, et un grand peuple assemblé de toutes parts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Il mettra au fil de l’épée les villes de ton ressort qui sont à la campagne, il fera des forts contre toi, il dressera des terrasses contre toi, et il lèvera les boucliers contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'Et il posera ses machines de guerre contre tes murailles, et démolira tes tours avec ses marteaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'La poussière de ses chevaux te couvrira à cause de leur multitude; tes murailles trembleront du bruit des gens de cheval, des charrettes, et des chariots, quand il entrera par tes portes, comme on entre dans une ville à laquelle on a fait brèche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Il foulera toutes tes rues avec la corne des pieds de ses chevaux; il tuera ton peuple avec l’épée, et les trophées de ta force tomberont par terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Puis ils butineront tes biens, et pilleront ta marchandise; ils ruineront tes murailles, et démoliront tes maisons de plaisance; et ils mettront tes pierres et ton bois et ta poussière au milieu des eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Et je ferai cesser le bruit de tes chansons, et le son de tes harpes ne sera plus ouï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Je te rendrai semblable à une pierre sèche; elle sera un lieu pour étendre les filets, et elle ne sera plus rebâtie, parce que moi l’Eternel j’ai parlé, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Ainsi a dit le Seigneur l’Eternel à Tyr: les Iles ne trembleront- elles pas du bruit de ta ruine, quand ceux qui seront blessés à mort gémiront, quand le carnage se fera au milieu de toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Tous les Princes de la mer descendront de leurs sièges, et ôteront leurs manteaux, et dépouilleront leurs vêtements de broderie, et se vêtiront de frayeur; ils s’assiéront sur la terre, et ils seront effrayés de moment en moment, et seront désolés à cause de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'Et ils prononceront à haute voix une complainte sur toi, et te diront: comment as-tu péri, toi qui étais fréquentée par ceux qui vont sur la mer, ville renommée, qui étais forte en la mer, toi et tes habitants, qui se sont fait redouter à tous ceux qui habitent en elle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Maintenant les Iles seront effrayées au jour de ta ruine, et les Iles qui sont en la mer seront étonnées à cause de ta fuite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Car ainsi a dit le Seigneur l’Eternel: quand je t’aurai rendue une ville désolée, comme sont les villes qui ne sont point habitées, quand j’aurai fait tomber sur toi l’abîme, et que les grosses eaux t’auront couverte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'Alors je te ferai descendre avec ceux qui descendent en la fosse, vers le peuple d’autrefois, et je te placerai aux lieux les plus bas de la terre, aux endroits désolés depuis longtemps, avec ceux qui descendent en la fosse, afin que tu ne sois plus habitée; mais je remettrai la noblesse parmi la terre des vivants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Je ferai qu’on sera tout étonné à cause de toi, de ce que tu n’es plus; et quand on te cherchera, on ne te trouvera plus à jamais, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Toi donc, fils d’homme, prononce à haute voix une complainte sur Tyr;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'Et dis à Tyr: Toi qui demeures aux avenues de la mer, qui fais métier de revendre aux peuples en plusieurs Iles; ainsi a dit le Seigneur l’Eternel: Tyr, tu as dit: je suis parfaite en beauté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Tes confins sont au coeur de la mer, ceux qui t’ont bâtie t’ont rendue parfaite en beauté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Ils t’ont bâti tous les côtés des navires de sapins de Senir; ils ont pris les cèdres du Liban pour te faire des mâts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Ils ont fait tes rames de chênes de Basan, et la troupe des Assyriens a fait tes bancs d’ivoire, apporté des Iles de Kittim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Le fin lin d’Egypte, travaillé en broderie, a été ce que tu étendais pour te servir de voiles; ce dont tu te couvrais était la pourpre et l’écarlate des Iles d’Elisa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Les habitants de Sidon et d’Arvad ont été tes matelots; ô Tyr! tes sages qui étaient au dedans de toi ont été tes pilotes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Les anciens de Guébal, et ses hommes experts ont été parmi toi, réparant tes brèches; tous les navires de la mer, et leurs mariniers, ont été au dedans de toi, pour trafiquer avec toi de ton trafic.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Ceux de Perse, et de Lud, et de Put ont été au dedans de toi pour être tes gens de guerre; ils ont pendu chez toi le bouclier et le casque; ils t’ont rendue magnifique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Les enfants d’Arvad avec tes troupes ont été sur tes murailles tout à l’entour, et ceux de Gammad ont été dans tes tours; ils ont pendu leurs boucliers sur tes murailles à l’entour, ils ont achevé de te rendre parfaite en beauté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Ceux de Tarsis ont trafiqué avec toi de toutes sortes de richesses, faisant valoir tes foires en argent, en fer, en étain et en plomb.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Javan, Tubal, et Mésec ont été tes facteurs, faisant valoir ton commerce en hommes, et en vaisseaux d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Ceux de la maison de Thogarma ont fait valoir tes foires en chevaux, et en cavaliers, et en mulets.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Les enfants de Dédan ont été tes facteurs; tu avais en ta main le commerce de plusieurs Iles; et on t’a rendu en échange des dents d’ivoire, et de l’ébène.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'La Syrie a trafiqué avec toi; en quantité d’ouvrages faits pour toi; on a fait valoir tes foires en escarboucles, en écarlate, en broderie, en fin lin, en corail, et en agate.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Juda et le pays d’Israël ont été tes facteurs, faisant valoir ton commerce en blé de Minnith et de Pannag, en miel, en huile, et en baume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damas a trafiqué avec toi en quantité d’ouvrages faits pour toi en toute sorte de richesses, en vin de Helbon, et en laine blanche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Et Dan, et Javan et Mosel, ont fait valoir tes foires en fer luisant; la casse et le roseau aromatique ont été dans ton commerce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Ceux de Dédan ont été tes facteurs en draps précieux pour les chariots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Les Arabes, et tous les principaux de Kédar, ont été des marchands que tu avais en ta main, trafiquant avec toi en agneaux, en moutons, et en boucs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Les marchands de Séba et de Rahma ont été tes facteurs, faisant valoir tes foires en toutes sortes de drogues les plus exquises, et en toute sorte de pierres précieuses, et en or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Haran, et Canne, et Héden, ont fait trafic de ce qui venait de Séba; et l’Assyrie a appris ton trafic.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Ceux-ci ont été tes facteurs en toutes sortes de choses, en draps de pourpre et de broderie, et en des caisses pour des vêtements précieux, en cordons entortillés; même les coffres de cèdre ont été dans ton trafic.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Les navires de Tarsis t’ont célébrée dans leurs chansons à cause de ton commerce, et tu as été remplie et rendue fort glorieuse, bâtie au coeur de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Tes matelots t’ont amenée en de grosses eaux, le vent d’Orient t’a brisée au coeur de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Tes richesses, et tes foires, ton commerce, tes mariniers, et tes pilotes, ceux qui réparaient tes brèches, et ceux qui avaient le soin de ton commerce, tous tes gens de guerre qui étaient au dedans de toi, et toute ta multitude qui est au milieu de toi, tomberont dans le coeur de la mer au jour de ta ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Les faubourgs trembleront au bruit du cri de tes pilotes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Et tous ceux qui manient la rame descendront de leurs navires, les mariniers, et tous les pilotes de la mer; ils se tiendront sur la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'Et feront ouïr sur toi leur voix, et crieront amèrement; ils jetteront de la poudre sur leurs têtes, et se vautreront dans la cendre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'Ils arracheront leurs cheveux, et rendront leur tête chauve à cause de toi, ils se ceindront de sacs, et te pleureront avec amertume d’esprit, en menant deuil amèrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Et ils prononceront à haute voix sur toi une complainte dans leur lamentation, et feront leur complainte sur toi, en disant: qui fut jamais telle que Tyr, telle que celle qui a été détruite au coeur de la mer?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Tu as rassasié plusieurs peuples par la traite des marchandises qu’on apportait de tes foires au delà des mers; et tu as enrichi les Rois de la terre par la grandeur de tes richesses et de ton commerce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Mais quand tu as été brisée par la mer au fond des eaux, ton commerce et toute ta multitude sont tombés avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Tous les habitants des Iles ont été désolés à cause de toi; et leurs Rois ont été horriblement épouvantés, et leur visage en a pâli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Les marchands d’entre les peuples t’ont insulté, tu es cause qu’on est tout étonné de ce que tu ne seras plus à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Fils d’homme, dis au conducteur de Tyr: ainsi a dit le Seigneur l’Eternel: parce que ton coeur s’est élevé et que tu as dit: je suis le Dieu Fort, et je suis assis dans le siège de Dieu, au coeur de la mer, quoique tu sois un homme, et non le Dieu Fort, et parce que tu as élevé ton coeur comme si tu étais un Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'Voici, tu es plus sage que Daniel, rien de caché ne t’a été rendu obscur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Tu t’es acquis de la puissance par ta sagesse et par ta prudence; et tu as assemblé de l’or et de l’argent dans tes trésors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'Tu as multiplié ta puissance par la grandeur de ta sagesse dans ton commerce, puis ton coeur s’est élevé à cause de ta puissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'C’est pourquoi le Seigneur l’Eternel dit ainsi: parce que tu as élevé ton coeur, comme si tu étais un Dieu:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'A cause de cela voici, je m’en vais faire venir contre toi des étrangers les plus terribles d’entre les nations, qui tireront leurs épées sur la beauté de ta sagesse, et souilleront ton lustre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'Ils te feront descendre en la fosse, et tu mourras au coeur de la mer, de la mort des blessés à mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Iras-tu disant devant celui qui te tuera, je suis Dieu? vu que tu te trouveras homme, et non le Dieu Fort, dans la main de celui qui te blessera mortellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Tu mourras de la mort des incirconcis par la main des étrangers; car j’ai parlé, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Fils d’homme, prononce à haute voix une complainte sur le Roi de Tyr, et lui dis: ainsi a dit le Seigneur l’Eternel: toi à qui rien ne manque, plein de sagesse, et parfait en beauté;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Tu as été en Héden le jardin de Dieu; ta couverture était de pierres précieuses de toutes sortes, de Sardoine, de Topaze, de Jaspe, de Chrysolithe, d’Onyx, de Béryl, de Saphir, d’Escarboucle, d’Emeraude, et d’or; ce que savaient faire tes tambours et tes flûtes a été chez toi; ils ont été tous prêts au jour que tu fus créé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Tu as été un Chérubin, oint pour servir de protection; je t’avais établi, et tu as été dans la sainte montagne de Dieu; tu as marché entre les pierres éclatantes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Tu as été parfait en tes voies dès le jour que tu fus créé, jusqu’à ce que la perversité a été trouvée en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Selon la grandeur de ton trafic on a rempli le milieu de toi de violence, et tu as péché; c’est pourquoi je te jetterai comme une chose souillée hors de la montagne de Dieu, et je te détruirai d’entre les pierres éclatantes, ô Chérubin! qui sers de protection.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Ton coeur s’est élevé à cause de ta beauté, tu as perdu ta sagesse à cause de ton éclat; je t’ai jeté par terre, je t’ai mis en spectacle aux Rois, afin qu’ils te regardent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Tu as profané tes Sanctuaires par la multitude de tes iniquités, en usant mal de ton trafic; et j’ai fait sortir du milieu de toi un feu qui t’a consumé, et je t’ai réduit en cendre sur la terre, en la présence de tous ceux qui te voient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Tous ceux qui te connaissent entre les peuples ont été désolés à cause de toi; tu es cause qu’on est tout étonné de ce que tu ne seras plus à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Puis la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Fils d’homme, tourne ta face vers Sidon, et prophétise contre elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'Et dis: ainsi a dit le Seigneur l’Eternel: voici j’en veux à toi, Sidon, et je serai glorifié au milieu de toi; et on saura que je suis l’Eternel, quand j’aurai exercé des jugements contre elle, et que j’y aurai été sanctifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'J’enverrai donc dans elle la mortalité, et le sang dans ses places, et les blessés à mort tomberont au milieu d’elle par l’épée qui viendra de toutes parts sur elle; et ils sauront que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Et elle ne sera plus une ronce piquante à la maison d’Israël, ni une épine causant plus de douleur qu’aucun de ceux qui sont autour d’eux, et qui les pillent; et ils sauront que je suis le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Ainsi a dit le Seigneur l’Eternel: quand j’aurai rassemblé la maison d’Israël d’entre les peuples parmi lesquels ils auront été dispersés, je serai sanctifié en eux, les nations le voyant, et ils habiteront sur leur terre que j’ai donnée à mon serviteur Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Ils y habiteront en sûreté, ils bâtiront des maisons, ils planteront des vignes; ils y habiteront, dis-je, en sûreté, lorsque j’aurai exercé des jugements contre ceux qui les auront pillés de toutes parts; et ils sauront que je suis l’Eternel leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'La dixième année, au douzième jour du dixième mois, la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Fils d’homme, tourne ta face contre Pharaon Roi d’Egypte, et prophétise contre lui, et contre toute l’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Parle, et dis: ainsi a dit le Seigneur l’Eternel: voici, j’en veux à toi, Pharaon Roi d’Egypte, grande Baleine couchée au milieu de tes bras d’eau, qui as dit: mes bras d’eau sont à moi, et je me les suis faits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'C’est pourquoi je mettrai des crocs dans tes mâchoires, et je ferai attacher à tes écailles les poissons de tes bras d’eau; et je te tirerai hors de tes bras d’eau, avec tous les poissons de tes bras d’eau, qui auront été attachés à tes écailles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Et t’ayant tiré dans le désert, je te laisserai là, toi, et tous les poissons de tes bras d’eau; tu seras étendu sur le dessus de la campagne; tu ne seras point recueilli ni ramassé; je t’ai livré aux bêtes de la terre, et aux oiseaux des cieux, pour en être dévoré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'Et tous les habitants d’Egypte sauront que je suis l’Eternel; parce qu’ils auront été à la maison d’Israël un bâton, qui n’était qu’un roseau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Quand ils t’ont pris par la main, tu t’es rompu, et tu leur as percé toute l’épaule; et quand ils se sont appuyés sur toi, tu t’es cassé, et tu les as fait tomber à la renverse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: voici, je m’en vais faire venir l’épée sur toi, et j’exterminerai du milieu de toi les hommes et les bêtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'Et le pays d’Egypte sera en désolation et en désert, et ils sauront que je suis l’Eternel, parce que le Roi d’Egypte a dit: les bras d’eau sont à moi, et je les ai faits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'C’est pourquoi voici, j’en veux à toi, et à tes bras d’eau, et je réduirai le pays d’Egypte en désert de sécheresse et de désolation, depuis la tour de Syène, jusques aux marches de Cus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Nul pied d’homme ne passera par là, et il n’y passera non plus aucun pied de bête, et elle sera quarante ans sans être habitée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Car je réduirai le pays d’Egypte en désolation entre les pays désolés, et ses villes entre les villes réduites en désert; elles seront en désolation durant quarante ans, je disperserai les Egyptiens parmi les nations, et je les répandrai parmi les pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Toutefois, ainsi a dit le Seigneur l’Eternel: au bout de quarante ans je ramasserai les Egyptiens d’entre les peuples parmi lesquels ils auront été dispersés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'Et je ramènerai les captifs d’Egypte, et les ferai retourner au pays de Pathros, au pays de leur extraction, mais ils seront là un Royaume abaissé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Il sera le plus bas des Royaumes, et il ne s’élèvera plus au dessus des nations, et je le diminuerai, afin qu’il ne domine point sur les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'Et il ne sera plus l’assurance de la maison d’Israël, les faisant souvenir de leur iniquité quand les enfants d’Israël regardaient après eux; et ils sauront que je suis le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Et il arriva la vingt-septième année, au premier jour du premier mois, que la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Fils d’homme, Nébucadnetsar Roi de Babylone a fait servir son armée dans un service pénible contre Tyr; toute tête en est devenue chauve, et toute épaule en a été foulée, mais il n’a point eu de salaire, ni lui, ni son armée, à cause de Tyr, pour le service qu’il a fait contre elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: voici, je m’en vais donner à Nébucadnetsar Roi de Babylone le pays d’Egypte; et il en enlèvera la multitude, il en emportera le butin, et en fera le pillage; et ce sera là le salaire de son armée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Pour le salaire de l’ouvrage auquel il a servi contre Tyr, je lui ai donné le pays d’Egypte, parce qu’ils ont travaillé pour moi, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'En ce jour-là je ferai germer la corne de la maison d’Israël, et j’ouvrirai ta bouche au milieu d’eux, et ils sauront que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Fils d’homme, prophétise, et dis: ainsi a dit le Seigneur l’Eternel: hurlez, et dites: ah quelle journée!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Car la journée est proche, oui la journée de l’Eternel est proche, c’est une journée de nuage; ce sera le temps des nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'L’épée viendra sur l’Egypte, et il y aura de l’effroi en Cus, quand ceux qui seront blessés à mort tomberont dans l’Egypte, et quand on enlèvera la multitude de son peuple, et que ses fondements seront ruinés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Cus, et Put, et Lud, et tout le mélange d’Arabie, et Cub, et les enfants du pays allié tomberont par l’épée avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Ainsi a dit l’Eternel: ceux qui soutiendront l’Egypte, tomberont; et l’orgueil de sa force sera renversé; ils tomberont en elle par l’épée depuis la tour de Syène, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'Et ils seront désolés au milieu des pays désolés, et ses villes seront au milieu des villes rendues désertes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'Et ils sauront que je suis l’Eternel, quand j’aurai mis le feu en Egypte; et tous ceux qui lui donneront du secours, seront brisés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'En ce jour-là des messagers sortiront de ma part dans des navires pour effrayer Cus l’assurée, et il y aura entre eux un tourment tel qu’à la journée d’Egypte; car voici, il vient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Ainsi a dit le Seigneur l’Eternel: je ferai périr la multitude d’Egypte par la puissance de Nébucadnetsar, Roi de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Lui et son peuple avec lui, les plus terribles d’entre les nations, seront amenés pour ruiner le pays, et ils tireront leurs épées contre les Egyptiens, et rempliront la terre de morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Et je mettrai à sec les bras d’eau, et je livrerai le pays entre les mains de gens méchants, je désolerai le pays, et tout ce qui y est, par la puissance des étrangers; moi l’Eternel j’ai parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Ainsi a dit le Seigneur l’Eternel: je détruirai aussi les idoles, j’anéantirai les faux dieux de Noph, et il n’y aura point de Prince qui soit du pays d’Egypte; et je mettrai la frayeur dans le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Je désolerai Pathros, je mettrai le feu à Tsohan, et j’exercerai des jugements dans No.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Et je répandrai ma fureur sur Sin, qui est la force d’Egypte, et j’exterminerai la multitude qui est à No.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Quand je mettrai le feu en Egypte, Sin sera grièvement tourmentée, et No sera rompue par diverses brèches, et il n’y aura à Noph que détresses en plein jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Les jeunes gens d’élite d’Aven et de Pibeseth tomberont par l’épée, et elles iront en captivité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Et le jour défaudra dans Taphnès, lorsque j’y romprai les barres d’Egypte, et que l’orgueil de sa force aura cessé; une nuée la couvrira, et les villes de son ressort iront en captivité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Et j’exercerai des jugements en Egypte; et ils sauront que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Or il était arrivé en la onzième année, au septième jour du premier mois, que la parole de l’Eternel m’avait été adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Fils d’homme, j’ai rompu le bras de Pharaon Roi d’Egypte; et voici on ne l’a point bandé pour le guérir, en sorte qu’on lui ait mis des linges pour le bander, et pour le fortifier, afin qu’il pût empoigner l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: voici, j’en veux à Pharaon Roi d’Egypte, et je romprai ses bras, tant celui qui est fort, que celui qui est rompu, et je ferai tomber l’épée de sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Et je disperserai les Egyptiens parmi les nations, et les répandrai parmi les pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Et je fortifierai les bras du Roi de Babylone, et je lui mettrai mon épée en la main; mais je romprai les bras de Pharaon, et Pharaon jettera des sanglots devant lui, comme des gens blessés à mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Je fortifierai donc les bras du Roi de Babylone, mais les bras de Pharaon tomberont; et on saura que je suis l’Eternel, quand j’aurai mis mon épée en la main du Roi de Babylone, et qu’il l’aura étendue sur le pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Et je disperserai les Egyptiens parmi les nations, et les répandrai parmi les pays; et ils sauront que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Il arriva aussi en la onzième année, au premier jour du troisième mois, que la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Fils d’homme, dis à Pharaon Roi d’Egypte, et à la multitude de son peuple: A qui ressembles-tu dans ta grandeur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Voici, le Roi d’Assyrie a été tel qu’est un cèdre au Liban, ayant de belles branches, et des rameaux qui faisaient une grande ombre, et qui étaient d’une grande hauteur; sa cime a été fort touffue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Les eaux l’ont fait croître, l’abîme l’a fait monter fort haut, ses fleuves ont coulé autour de ses plantes, et il a envoyé les conduits de ses eaux vers tous les arbres des champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'C’est pourquoi sa hauteur s’est élevée par dessus tous les autres arbres des champs, ses branches ont été multipliées, et ses rameaux sont devenus longs par les grandes eaux, lorsqu’il poussait ses branches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Tous les oiseaux des cieux ont fait leurs nids dans ses branches, et toutes les bêtes des champs ont fait leurs petits sous ses rameaux, et toutes les grandes nations ont habité sous son ombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Il était donc devenu beau dans sa grandeur, et dans l’étendue de ses branches, parce que sa racine était sur de grandes eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Les cèdres qui étaient au Jardin de Dieu ne lui ôtaient rien de son lustre; les sapins n’étaient point pareils à ses branches, et les châtaigniers n’égalaient point l’étendue de ses rameaux; tous les arbres qui étaient au Jardin de Dieu n’ont point été pareils à lui en sa beauté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Je l’avais fait beau dans la multitude de ses rameaux, tellement que tous les arbres d’Héden, qui étaient au Jardin de Dieu, lui portaient envie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'C’est pourquoi le Seigneur l’Eternel dit ainsi: parce que tu t’es élevé en hauteur, comme celui-là, qui avait sa cime toute touffue, a élevé son coeur dans sa hauteur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'Et je l’ai livré entre les mains du plus fort d’entre les nations, qui l’a traité comme il fallait, et je l’ai chassé à cause de sa méchanceté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'Et les étrangers les plus terribles d’entre les nations l’ont coupé, et l’ont laissé là, et ses branches sont tombées sur les montagnes, et sur toutes les vallées; et ses rameaux se sont rompus dans tous les cours des eaux de la terre, et tous les peuples de la terre se sont retirés de dessous son ombre, et l’ont laissé là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Tous les oiseaux des cieux se sont tenus sur ses ruines, et toutes les bêtes des champs se sont retirées vers ses rameaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'C’est pourquoi aucun arbre arrosé d’eaux ne s’élève de sa hauteur, et ne produit de cime touffue, et les plus forts d’entre eux, même de tous ceux qui hument l’eau, ne subsistent point dans leur hauteur; car eux tous sont livrés à la mort dans la terre basse parmi les enfants des hommes, avec ceux qui descendent en la fosse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Ainsi a dit le Seigneur l’Eternel: le jour qu’il descendit au sépulcre, je fis mener deuil sur lui, je couvris l’abîme devant lui, et j’empêchai ses fleuves de couler, et les grosses eaux furent retenues; je fis que le Liban fut en deuil à cause de lui, et tous les arbres des champs en furent fatigués.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'J’ébranlai les nations par le bruit de sa ruine, quand je le fis descendre au sépulcre, avec ceux qui descendent dans la fosse; et tous les arbres d’Héden, l’élite et le meilleur du Liban, tous humant l’eau, furent rendus contents au bas de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Eux aussi sont descendus avec lui au sépulcre, vers ceux qui ont été tués par l’épée, et son bras, c’est-à-dire, ceux qui habitaient sous son ombre parmi les nations, y sont aussi descendus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'A qui donc as-tu ressemblé en gloire et en grandeur entre les arbres d’Héden? et pourtant tu seras jeté bas avec les arbres d’Héden dans les lieux profonds de la terre, tu seras gisant au milieu des incirconcis, avec ceux qui ont été tués par l’épée. C’est ici Pharaon, et toute la multitude de son peuple, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Il arriva aussi en la douzième année, le premier jour du douzième mois, que la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Fils d’homme, prononce à haute voix une complainte sur Pharaon Roi d’Egypte, et lui dis: tu as été entre les nations semblable à un lionceau, et tel qu’un grand poisson dans les mers; tu t’élançais dans tes fleuves, et tu troublais les eaux avec tes pieds, et remplissais de bourbe leurs fleuves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Ainsi a dit le Seigneur l’Eternel: j’étendrai mon rets sur toi par un amas de plusieurs peuples, qui te tireront étant dans mes filets.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Et je te laisserai à l’abandon sur la terre; je te jetterai sur le dessus des champs, et je ferai demeurer sur toi tous les oiseaux des cieux, et rassasierai de toi les bêtes de toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Car je mettrai ta chair sur les montagnes, et je remplirai tes vallées des débris de tes hauteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'Et j’arroserai de ton sang jusques aux montagnes, la terre où tu nages, et les lits des eaux seront remplis de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Et quand je t’aurai éteint, je couvrirai les cieux, et ferai obscurcir leurs étoiles, je couvrirai le soleil de nuages, et la lune ne donnera plus sa lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Je ferai obscurcir sur toi tous les luminaires qui donnent la lumière dans les cieux, et je répandrai les ténèbres sur ton pays, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Et je ferai que le coeur de plusieurs peuples frémira, quand j’aurai fait venir la nouvelle de ta plaie parmi les nations, en des pays que tu n’as point connus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Et je remplirai d’étonnement plusieurs peuples à cause de toi, et leurs Rois seront tout épouvantés à cause de toi, quand je ferai luire mon épée à leurs yeux; et ils seront effrayés de moment en moment, chacun dans soi-même, au jour de ta ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Car ainsi a dit le Seigneur l’Eternel: l’épée du Roi de Babylone viendra sur toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'J’abattrai ta multitude par les épées des hommes forts, qui tous sont les plus terribles d’entre les nations; et ils détruiront l’orgueil de l’Egypte, et toute la multitude de son peuple sera ruinée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Et je ferai périr tout son bétail d’auprès des grosses eaux, et aucun pied d’homme ne les troublera plus, ni aucun pied de bête ne les agitera plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Alors je rendrai profondes leurs eaux, et je ferai couler leurs fleuves comme de l’huile, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Quand j’aurai réduit le pays d’Egypte en désolation, et que le pays aura été dénué des choses dont il était rempli; quand j’aurai frappé tous ceux qui y habitent, ils sauront alors que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'C’est ici la complainte qu’on fera sur elle, les filles des nations feront cette complainte sur elle; elles feront, dis-je, cette complainte sur l’Egypte, et sur toute la multitude de son peuple, dit le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Il arriva aussi en la douzième année, le quinzième jour du mois, que la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Fils d’homme, dresse une lamentation sur la multitude d’Egypte, et fais-la descendre, elle et les filles des nations magnifiques, aux plus bas lieux de la terre, avec ceux qui descendent en la fosse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Par dessus qui m’ aurais-tu été agréable? descends, et sois gisante avec les incirconcis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Ils tomberont au milieu de ceux qui auront été tués par l’épée; l’épée a déjà été donnée; traînez-la avec toute la multitude de son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Les plus forts d’entre les puissants lui parleront du milieu du sépulcre, avec ceux qui lui donnaient du secours, et diront: ils sont descendus, ils sont gisants, les incirconcis tués par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Là est l’Assyrien, et toute son assemblée; ses sépulcres sont autour de lui, eux tous, mis à mort, sont tombés par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Car ses sépulcres ont été posés au fond de la fosse, et son assemblée autour de sa sépulture; eux tous qui avaient répandu leur terreur sur la terre des vivants, sont tombés morts par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Là est Hélam, et toute sa multitude autour de son sépulcre; eux tous sont tombés morts par l’épée, ils sont descendus incirconcis dans les plus bas lieux de la terre, et après avoir répandu leur terreur sur la terre des vivants, ils ont porté leur ignominie avec ceux qui descendent dans la fosse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'On a mis sa couche parmi ceux qui ont été tués, avec toute sa multitude; ses sépulcres sont autour de lui; eux tous incirconcis tués par l’épée, quoiqu’ils aient répandu leur terreur sur la terre des vivants, toutefois ils ont porté leur ignominie avec ceux qui descendent en la fosse; il a été mis parmi ceux qui ont été tués.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Là est Mesec, Tubal, et toute la multitude de leurs gens; leurs sépulcres sont autour d’eux; eux tous incirconcis, tués par l’épée, quoiqu’ils aient répandu leur terreur sur la terre des vivants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Ils n’ont pourtant point été gisants avec les hommes vaillants qui sont tombés d’entre les incirconcis, lesquels sont descendus au sépulcre avec leurs instruments de guerre, dont on a mis les épées sous leurs têtes, et dont les iniquités ont reposé sur leurs os; parce que la terreur des hommes forts est en la terre des vivants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Toi aussi tu seras froissé au milieu des incirconcis, et tu seras gisant avec ceux qui ont été tués par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Là est Edom, ses Rois, et tous ses Princes, qui ont été mis avec leur force parmi ceux qui ont été tués par l’épée; ils seront gisants avec les incirconcis, et avec ceux qui sont descendus dans la fosse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Là sont tous les Princes de l’Aquilon, et tous les Sidoniens, qui sont descendus avec ceux qui ont été tués, à cause de leur terreur, étant honteux de leur force; et ils sont gisants incirconcis avec ceux qui ont été tués par l’épée, et ils ont porté leur ignominie avec ceux qui sont descendus dans la fosse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Pharaon les verra, et il sera consolé de toute la multitude de son peuple; Pharaon, dit le Seigneur l’Eternel a vu les blessés par l’épée et toute son armée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Car j’ai mis ma terreur en la terre des vivants, c’est pourquoi Pharaon avec toute la multitude de son peuple sera gisant au milieu des incirconcis, avec ceux qui ont été tués par l’épée, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Fils d’homme, parle aux enfants de ton peuple, et leur dis: quand je ferai venir l’épée sur quelque pays, et que le peuple du pays aura choisi quelqu’un d’entre eux, et l’aura établi pour leur servir de sentinelle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'Et que lui voyant venir l’épée sur le pays, aura sonné du cor, et aura averti le peuple;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'Si le peuple ayant bien ouï le son du cor, ne se tient pas sur ses gardes, et qu’ensuite l’épée vienne, et le dépêche, son sang sera sur sa tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Car il a ouï le son du cor, et ne s’est point tenu sur ses gardes; son sang donc sera sur lui-même; mais s’il se tient sur ses gardes, il sauvera sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Que si la sentinelle voit venir l’épée, et qu’elle ne sonne point du cor, en sorte que le peuple ne se tienne point sur ses gardes, et qu’ensuite l’épée survienne, et ôte la vie à quelqu’un d’entre eux; celui-ci aura bien été surpris dans son iniquité, mais je redemanderai son sang de la main de la sentinelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Toi donc, fils d’homme, je t’ai établi pour sentinelle à la maison d’Israël; tu écouteras donc la parole de ma bouche, et tu les avertiras de ma part.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Quand j’aurai dit au méchant: méchant, tu mourras de mort; et que tu n’auras point parlé au méchant pour l’ avertir de se détourner de sa voie, ce méchant mourra dans son iniquité; mais je redemanderai son sang de ta main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Mais si tu as averti le méchant de se détourner de sa voie, et qu’il ne se soit point détourné de sa voie, il mourra dans son iniquité; mais toi tu auras délivré ton âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Toi donc, fils d’homme, dis à la maison d’Israël: vous avez parlé ainsi, en disant: puisque nos crimes et nos péchés sont sur nous, et que nous périssons à cause d’eux, comment pourrions-nous vivre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Dis-leur: je suis vivant, dit le Seigneur l’Eternel, que je ne prends point plaisir en la mort du méchant, mais plutôt que le méchant se détourne de sa voie, et qu’il vive. Détournez-vous, détournez-vous de votre méchante voie; et pourquoi mourriez-vous, maison d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Toi donc, fils d’homme, dis aux enfants de ton peuple: la justice du juste ne le délivrera point, au jour qu’il aura péché, et le méchant ne tombera point par sa méchanceté, au jour qu’il s’en sera détourné; et le juste ne pourra pas vivre par sa justice, au jour qu’il aura péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Quand j’aurai dit au juste qu’il vivra certainement, et que lui, se confiant sur sa justice, aura commis l’iniquité, on ne se souviendra plus d’aucune de ses justices, mais il mourra dans son iniquité qu’il aura commise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Aussi quand j’aurai dit au méchant: tu mourras de mort; s’il se détourne de son péché, et qu’il fasse ce qui est juste et droit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'Si le méchant rend le gage, et qu’il restitue ce qu’il aura ravi, et qu’il marche dans les statuts de la vie, sans commettre d’iniquité, certainement il vivra, il ne mourra point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'On ne se souviendra plus des péchés qu’il aura commis; il a fait ce qui est juste et droit; certainement il vivra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Or les enfants de ton peuple ont dit: la voie du Seigneur n’est pas bien réglée; mais c’est plutôt leur voie qui n’est pas bien réglée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Quand le juste se détournera de sa justice, et qu’il commettra l’iniquité, il mourra pour ces choses-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Et quand le méchant se détournera de sa méchanceté, et qu’il fera ce qui est juste et droit, il vivra pour ces choses-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Et vous avez dit: la voie du Seigneur n’est pas bien réglée! Je vous jugerai, maison d’Israël, chacun selon sa voie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'Or il arriva en la douzième année de notre captivité, au cinquième jour du dixième mois, que quelqu’un qui était échappé de Jérusalem vint vers moi, en disant: la ville a été prise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Et la main de l’Eternel avait été sur moi le soir avant que celui qui était échappé vînt, et l’Eternel avait ouvert ma bouche, en attendant que cet homme vînt le matin vers moi; et ma bouche ayant été ouverte, je ne me tus plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Et la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Fils d’homme, ceux qui habitent en ces lieux déserts, sur la terre d’Israël, discourent, en disant: Abraham était seul, et il a possédé le pays; mais nous sommes un grand nombre de gens; et le pays nous a été donné en héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'C’est pourquoi tu leur diras: ainsi a dit le Seigneur l’Eternel: vous mangez la chair avec le sang, et vous levez vos yeux vers vos idoles, et vous répandez le sang; et vous posséderiez le pays?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Vous vous appuyez sur votre épée; vous commettez abomination, et vous souillez chacun de vous la femme de son prochain; et vous posséderiez le pays?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Tu leur diras ainsi: ainsi a dit le Seigneur l’Eternel: je suis vivant, que ceux qui sont en ces lieux déserts tomberont par l’épée, et que je livrerai aux bêtes celui qui est par les champs, afin qu’elles le mangent; et que ceux qui sont dans les forteresses, et dans les cavernes, mourront de mortalité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Ainsi je réduirai le pays en désolation et en désert, tellement que l’orgueil de sa force sera aboli, et les montagnes d’Israël seront désolées, en sorte qu’il n’y passera plus personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Et ils connaîtront que je suis l’Eternel, quand j’aurai réduit leur pays en désolation et en désert, à cause de toutes leurs abominations qu’ils ont commises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Et quant à toi, fils d’homme, les enfants de ton peuple causent de toi auprès des murailles, et aux entrées des maisons, et parlent l’un à l’autre chacun avec son prochain, en disant: venez maintenant, et écoutez quelle est la parole qui est procédée de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'Et ils viennent vers toi comme en foule, et mon peuple s’assied devant toi, et ils écoutent tes paroles, mais ils ne les mettent point en effet; ils les répètent comme si c’était une chanson profane, mais leur coeur marche toujours après leur gain déshonnête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Et voici tu leur es comme un homme qui leur chante une chanson profane avec une belle voix, qui résonne bien; car ils écoutent bien tes paroles, mais ils ne les mettent point en effet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Mais quand cela sera arrivé (et le voici qui vient), ils sauront qu’il y a eu un Prophète au milieu d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Fils d’homme, prophétise contre les Pasteurs d’Israël; prophétise, et dis à ces Pasteurs: ainsi a dit le Seigneur l’Eternel: malheur aux Pasteurs d’Israël qui ne paissent qu’eux-mêmes! Les pasteurs ne paissent-ils pas le troupeau?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Vous en mangez la graisse, et vous vous habillez de la laine; vous tuez ce qui est gras, et vous ne paissez point le troupeau!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Vous n’avez point fortifié les brebis languissantes, vous n’avez point donné de remède à celle qui était malade, vous n’avez point bandé la plaie de celle qui avait la jambe rompue, vous n’avez point ramené celle qui était chassée, et vous n’avez point cherché celle qui était perdue; mais vous les avez maîtrisées avec dureté et rigueur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Et elles ont été dispersées, par la disette des Pasteurs, et elles ont été exposées à toutes les bêtes des champs, pour en être dévorées, étant dispersées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Mes brebis ont été errantes par toutes les montagnes, et par tous les coteaux élevés; mes brebis ont été dispersées sur tout le dessus de la terre; et il n’y a eu personne qui les recherchât, et il n’y a eu personne qui s’en enquît.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'C’est pourquoi Pasteurs, écoutez la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Je suis vivant, dit le Seigneur l’Eternel, si je ne fais justice de ce que mes brebis ont été exposées en proie, et de ce que mes brebis ont été exposées à être dévorées de toutes les bêtes des champs, parce qu’elles n’avaient point de Pasteur; et de ce que mes Pasteurs n’ont point recherché mes brebis, mais que les Pasteurs se sont nourris simplement eux-mêmes, et n’ont point fait paître mes brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'C’est pourquoi Pasteurs, écoutez la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Ainsi a dit le Seigneur l’Eternel: Voici, j’en veux à ces Pasteurs-là, et je redemanderai mes brebis de leur main, je les ferai cesser de paître les brebis; et les pasteurs ne se repaîtront plus uniquement eux-mêmes, mais je délivrerai mes brebis de leur bouche, et elles ne seront plus dévorées par eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Car ainsi a dit le Seigneur l’Eternel: me voici, je redemanderai mes brebis, et je les rechercherai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Comme le Pasteur se trouvant parmi son troupeau, recherche ses brebis dispersées; ainsi je rechercherai mes brebis, et les retirerai de tous les lieux où elles auront été dispersées au jour de la nuée et de l’obscurité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Je les retirerai donc d’entre les peuples, et les rassemblerai des pays, et les ramènerai dans leur terre, et les nourrirai sur les montagnes d’Israël, auprès des cours des eaux et dans toutes les demeures du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Je les paîtrai dans de bons pâturages, et leur parc sera dans les hautes montagnes d’Israël; et là elles coucheront dans un bon parc, et paîtront en de gras pâturages sur les montagnes d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Moi-même je paîtrai mes brebis, et les ferai reposer, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Je chercherai celle qui sera perdue, et je ramènerai celle qui sera chassée, je banderai la plaie de celle qui aura la jambe rompue, et je fortifierai celle qui sera malade; mais je détruirai la grasse et la forte; je les paîtrai par raison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Mais quant à vous, mes brebis; ainsi a dit le Seigneur l’Eternel: voici, je m’en vais mettre à part les brebis, les béliers, et les boucs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Vous est-ce peu de chose d’être nourries de bonne pâture, que vous fouliez à vos pieds le reste de votre pâture? et de boire des eaux claires, que vous troubliez le reste avec vos pieds?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'Mais mes brebis sont nourries de la pâture que vous foulez à vos pieds, et elles boivent ce que vos pieds ont troublé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'C’est pourquoi le Seigneur l’Eternel leur a dit ainsi: me voici, je mettrai moi-même à part la brebis grasse, et la brebis maigre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Parce que vous avez poussé du côté et de l’épaule, et que vous heurtez de vos cornes toutes celles qui sont languissantes, jusqu’à ce que vous les ayez chassées dehors;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'Je sauverai mon troupeau, tellement qu’il ne sera plus en proie, et je distinguerai entre brebis et brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Je susciterai sur elles un Pasteur qui les paîtra, savoir mon serviteur David; il les paîtra, et lui-même sera leur Pasteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Et moi l’Eternel, je serai leur Dieu; et mon serviteur David sera Prince au milieu d’elles; moi l’Eternel j’ai parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Et je traiterai avec elles une alliance de paix; et je détruirai dans le pays les mauvaises bêtes; et les brebis habiteront au désert sûrement, et dormiront dans les forêts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Et je les comblerai de bénédiction, et tous les environs aussi de mon coteau; et je ferai tomber la pluie en sa saison; ce seront des pluies de bénédiction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Et les arbres des champs produiront leur fruit, et la terre rapportera son revenu; et elles seront en leur terre sûrement, et sauront que je suis l’Eternel, quand j’aurai rompu les bois de leur joug, et que je les aurai délivrées de la main de ceux qui se les asservissaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Et elles ne seront plus en proie aux nations, et les bêtes de la terre ne les dévoreront plus; mais elles habiteront sûrement, et il n’y aura personne qui les épouvante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Je leur susciterai une plante célèbre; elles ne mourront plus de faim sur la terre, et elles ne porteront plus l’opprobre des nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Et ils sauront que moi l’Eternel leur Dieu suis avec eux, et qu’eux, la maison d’Israël, sont mon peuple, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Or vous êtes mes brebis, vous hommes, les brebis de mon pâturage, et je suis votre Dieu, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Fils d’homme, tourne ta face contre la montagne de Séhir, et prophétise contre elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'Et lui dis: ainsi a dit le Seigneur l’Eternel: voici, j’en veux à toi, montagne de Séhir, et j’étendrai ma main contre toi, et te réduirai en désolation et en désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Je réduirai tes villes en désert, et tu ne seras que désolation, et tu connaîtras que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Parce que tu as eu une inimitié immortelle, et que tu as fait couler le sang des enfants d’Israël à coups d’épée, au temps de leur calamité, et au temps de leur iniquité, qui en a été la fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'C’est pourquoi je suis vivant, dit le Seigneur l’Eternel, que je te mettrai toute en sang, et le sang te poursuivra; parce que tu n’as point haï le sang, le sang aussi te poursuivra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Et je réduirai la montagne de Séhir en désolation et en désert, et j’en éloignerai tous ceux qui la fréquentaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Et je remplirai ses montagnes de ses gens mis à mort; tes hommes tués par l’épée tomberont en tes coteaux, et en tes vallées, et en tous tes courants d’eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Je te réduirai en désolations éternelles, et tes villes ne seront plus habitées; et vous saurez que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Parce que tu as dit: les deux nations, et les deux pays seront à moi, et nous les posséderons, quoique l’Eternel ait été là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'A cause de cela, je suis vivant, dit le Seigneur l’Eternel, que j’agirai selon ton courroux, et selon ton envie que tu as exécutée, à cause de tes haines contre eux; et je serai connu entre eux quand je t’aurai jugé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'Et tu sauras que moi l’Eternel j’ai ouï toutes les paroles insultantes que tu as prononcées contre les montagnes d’Israël, en disant: elles ont été désolées, elles nous ont été données pour les consumer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Et vous m’avez bravé par vos discours, et vous avez multiplié vos paroles contre moi; je l’ai ouï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Ainsi a dit le Seigneur l’Eternel: quand toute la terre se réjouira, je te réduirai en désolation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Comme tu t’es réjouie sur l’héritage de la maison d’Israël, parce qu’il a été désolé, j’en ferai de même envers toi; tu ne seras que désolation, ô montagne de Séhir! même tout Edom entièrement; et ils sauront que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'Et toi, fils d’homme, prophétise aussi touchant les montagnes d’Israël, et dis: montagnes d’Israël, écoutez la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Ainsi a dit le Seigneur l’Eternel: parce que l’ennemi a dit contre vous: ha! ha! Tous les lieux haut élevés, qui même sont d’ancienneté, sont devenus notre possession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'C’est pourquoi prophétise, et dis: ainsi a dit le Seigneur l’Eternel: parce, oui, parce qu’on vous a réduites en désolation, et que ceux d’alentour, vous ont englouties, afin que vous fussiez en possession au reste des nations, et qu’on vous a exposées à la langue et aux insultes des nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'A cause de cela, montagnes d’Israël, écoutez la parole du Seigneur l’Eternel: ainsi a dit le Seigneur l’Eternel aux montagnes, et aux coteaux, aux courants d’eaux, et aux vallées, aux lieux détruits et désolés, et aux villes abandonnées qui ont été en pillage et en moquerie au reste des nations qui sont tout à l’entour;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'A cause de cela, dis-je, ainsi a dit le Seigneur l’Eternel: si je ne parle en l’ardeur de ma jalousie contre le reste des nations, et contre tous ceux d’Idumée qui se sont attribué ma terre en possession, avec une joie dont leur coeur était plein, et avec un mépris dont ils se faisaient un grand plaisir, pour la mettre au pillage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'C’est pourquoi prophétise touchant la terre d’Israël, et dis aux montagnes, et aux coteaux, aux courants d’eaux, et aux vallées: ainsi a dit le Seigneur l’Eternel: voici, j’ai parlé en ma jalousie, et en ma fureur, parce que vous avez porté l’ignominie des nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: j’ai levé ma main, si les nations qui sont tout autour de vous ne portent leur ignominie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Mais vous, montagnes d’Israël, vous pousserez vos branches, et vous porterez votre fruit pour mon peuple d’Israël; car ils sont prêts à venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Car me voici, je viens à vous, et je retournerai vers vous, et vous serez labourées, et semées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'Et je multiplierai les hommes sur vous, savoir la maison d’Israël tout entière, et les villes seront habitées, et les lieux déserts seront rebâtis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Et je multiplierai sur vous les hommes et les bêtes, qui y multiplieront, et fructifieront; je ferai que vous serez habités comme anciennement, et je vous ferai plus de bien que vous n’en avez eu au commencement; et vous saurez que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Et je ferai marcher sur vous des hommes, savoir mon peuple d’Israël, qui vous posséderont, vous leur serez en héritage, et vous ne les consumerez plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Ainsi a dit le Seigneur l’Eternel: parce qu’on dit de vous: tu es un pays qui dévore les hommes, et tu as consumé tes habitants;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'A cause de cela tu ne dévoreras plus les hommes, et ne consumeras plus tes habitants, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Et je ferai que tu n’entendras plus l’ignominie des nations, et que tu ne porteras plus l’opprobre des peuples; et tu ne feras plus périr tes habitants, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Puis la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Fils d’homme, ceux de la maison d’Israël habitant en leur terre l’ont souillée par leur voie et par leurs actions; leur voie est devenue devant moi telle qu’est la souillure de la femme séparée à cause de son impureté;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Et j’ai répandu ma fureur sur eux à cause du sang qu’ils ont répandu sur le pays, et parce qu’ils l’ont souillé par leurs idoles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'Et je les ai dispersés parmi les nations, et ils ont été répandus par les pays; je les ai jugés selon leur voie, et selon leurs actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Et étant venus parmi les nations au milieu desquelles ils sont venus, ils ont profané le Nom de ma Sainteté, en ce qu’on a dit d’eux: ceux-ci sont le peuple de l’Eternel, et cependant ils sont sortis de son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Mais j’ai épargné le Nom de ma Sainteté, lequel la maison d’Israël avait profané parmi les nations au milieu desquelles ils étaient venus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'C’est pourquoi dis à la maison d’Israël: ainsi a dit le Seigneur l’Eternel: je ne le fais point à cause de vous, ô maison d’Israël! mais à cause du Nom de ma Sainteté, que vous avez profané parmi les nations au milieu desquelles vous êtes venus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Et je sanctifierai mon grand Nom, qui a été profané parmi les nations, et que vous avez profané parmi elles; et les nations sauront que je suis l’Eternel, dit le Seigneur l’Eternel, quand je serai sanctifié en vous, en leur présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Je vous retirerai donc d’entre les nations, je vous rassemblerai de tous pays, et je vous ramènerai en votre terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Et je répandrai sur vous des eaux nettes, et vous serez nettoyés; je vous nettoierai de toutes vos souillures, et de toutes vos idoles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Je vous donnerai un nouveau coeur, je mettrai au dedans de vous un Esprit nouveau; j’ôterai de votre chair le coeur de pierre, et je vous donnerai un coeur de chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Et je mettrai mon Esprit au dedans de vous, je ferai que vous marcherez dans mes statuts, et que vous garderez mes ordonnances, et les ferez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Et vous demeurerez au pays que j’ai donné à vos pères, et vous serez mon peuple, et je serai votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Je vous délivrerai de toutes vos souillures, j’appellerai le froment, je le multiplierai, et je ne vous enverrai plus la famine;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Mais je multiplierai le fruit des arbres, et le revenu des champs, afin que vous ne portiez plus l’opprobre de la famine entre les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Et vous vous souviendrez de votre mauvaise voie et de vos actions, qui n’étaient pas bonnes, et vous détesterez en vous-mêmes vos iniquités, et vos abominations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Je ne le fais point pour l’amour de vous, dit le Seigneur l’Eternel, afin que vous le sachiez. Soyez honteux et confus à cause de votre voie, ô maison d’Israël!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Ainsi a dit le Seigneur l’Eternel: au jour que je vous aurai purifiés de toutes vos iniquités je vous ferai habiter dans des villes, et les lieux déserts seront rebâtis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'Et la terre désolée sera labourée, au lieu qu’elle n’a été que désolation, en la présence de tous les passants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'Et on dira: cette terre-ci qui était désolée, est devenue comme le jardin d’Héden; et ces villes qui avaient été désertes, désolées, et détruites, sont fortifiées et habitées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Et les nations qui seront demeurées de reste autour de vous sauront que moi l’Eternel j’aurai rebâti les lieux détruits, et planté le pays désolé, moi l’Eternel j’ai parlé, et je le ferai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Ainsi a dit le Seigneur l’Eternel: encore serai-je recherché par la maison d’Israël, pour leur faire ceci, savoir que je multiplie leurs hommes comme un troupeau de brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Les villes qui sont désertes seront remplies de troupes d’hommes, tels que sont les troupeaux des bêtes sanctifiées, tels que sont les troupeaux des bêtes qu’on amène à Jérusalem en ses fêtes solennelles; et ils sauront que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'La main de l’Eternel fut sur moi, et l’Eternel me fit sortir en esprit, et me posa au milieu d’une campagne qui était pleine d’os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Et il me fit passer auprès d’eux tout à l’environ, et voici, ils étaient en fort grand nombre sur le dessus de cette campagne, et étaient fort secs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Puis il me dit: fils d’homme, ces os pourraient-ils bien revivre? Et je répondis: Seigneur Eternel, tu le sais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Alors il me dit: prophétise sur ces os, et leur dis: os secs, écoutez la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Ainsi a dit le Seigneur l’Eternel à ces os: voici, je m’en vais faire entrer l’esprit en vous, et vous revivrez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Et je mettrai des nerfs sur vous, et je ferai croître de la chair sur vous, et j’étendrai la peau sur vous; puis je remettrai l’esprit en vous, et vous revivrez; et vous saurez que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Alors je prophétisai selon qu’il m’avait été commandé, et sitôt que j’eus prophétisé il se fit un son, et voici, il se fit un mouvement, et ces os s’approchèrent l’un de l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Puis je regardai, et voici, il vint des nerfs sur eux, et il y crût de la chair, et la peau y fut étendue par dessus; mais l’esprit n’y était point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Alors il me dit: prophétise à l’esprit, prophétise, fils d’homme, et dis à l’esprit: ainsi a dit le Seigneur l’Eternel: esprit, viens des quatre vents, et souffle sur ces morts, et qu’ils revivent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Je prophétisai donc comme il m’avait commandé, et l’esprit entra en eux, et ils revécurent, et se tinrent sur leurs pieds; et ce fut une armée extrêmement grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Alors il me dit: fils d’homme, ces os sont toute la maison d’Israël; voici, ils disent: nos os sont devenus secs, et notre attente est perdue, c’en est fait de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'C’est pourquoi prophétise, et leur dis: ainsi a dit le Seigneur l’Eternel: mon peuple, voici, je m’en vais ouvrir vos sépulcres, et je vous tirerai hors de vos sépulcres, et vous ferai rentrer en la terre d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'Et vous, mon peuple, vous saurez que je suis l’Eternel quand j’aurai ouvert vos sépulcres, et que je vous aurai tirés hors de vos sépulcres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Et je mettrai mon esprit en vous, et vous revivrez, et je vous placerai sur votre terre; et vous saurez que moi l’Eternel j’aurai parlé, et que je l’aurai fait, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Puis la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'Et toi, fils d’homme, prends un bois, et écris dessus: pour Juda, et pour les enfants d’Israël ses compagnons; prends encore un autre bois, et écris dessus: le bois d’Ephraïm et de toute la maison d’Israël ses compagnons, pour Joseph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Puis tu les joindras l’un à l’autre pour ne former qu’un même bois, et ils seront unis dans ta main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Et quand les enfants de ton peuple demanderont, en disant: ne nous déclareras-tu pas ce que tu veux dire par ces choses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'Dis-leur: ainsi a dit le Seigneur l’Eternel: voici, je m’en vais prendre le bois de Joseph qui est en la main d’Ephraïm, et des Tribus d’Israël ses compagnons, et je les mettrai sur celui-ci, savoir sur le bois de Juda; et je les ferai être un seul bois; et ils ne seront qu’un seul bois en ma main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Ainsi les bois sur lesquels tu auras écrit seront en ta main, eux le voyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Et dis-leur: ainsi a dit le Seigneur l’Eternel: voici, je m’en vais prendre les enfants d’Israël d’entre les nations parmi lesquelles ils sont allés, je les rassemblerai de toutes parts, et je les ferai rentrer en leur terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'Et je ferai qu’ils seront une seule nation dans le pays, sur les montagnes d’Israël; ils n’auront tous qu’un Roi pour leur Roi, ils ne seront plus deux nations, et ils ne seront plus divisés en deux Royaumes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Et ils ne se souilleront plus par leurs idoles, ni par leurs infamies, ni par tous leurs crimes, et je les retirerai de toutes leurs demeures dans lesquelles ils ont péché, et je les purifierai; et ils seront mon peuple, et je serai leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Et David mon serviteur sera leur Roi, et ils auront tous un seul Pasteur; et ils marcheront dans mes ordonnances, ils garderont mes statuts, et les feront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'Et ils habiteront au pays que j’ai donné à Jacob mon serviteur, dans lequel vos pères ont habité; ils y habiteront, dis-je, eux, et leurs enfants, et les enfants de leurs enfants, à toujours; et David mon serviteur sera leur Prince à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Et je traiterai avec eux une alliance de paix, et il y aura une alliance éternelle avec eux, et je les établirai, et les multiplierai, je mettrai mon Sanctuaire au milieu d’eux à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Et mon pavillon sera parmi eux; et je serai leur Dieu, et ils seront mon peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Et les nations sauront que je suis l’Eternel qui sanctifie Israël, quand mon Sanctuaire sera au milieu d’eux à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'La parole de l’Eternel me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Fils d’homme, tourne ta face vers Gog au pays de Magog, Prince des chefs de Mésec et de Tubal, et prophétise contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'Et dis: ainsi a dit le Seigneur l’Eternel: voici, j’en veux à toi, Gog, Prince des chefs de Mésec et de Tubal;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Et je te ferai retourner en arrière, et je mettrai des boucles dans tes mâchoires, et te ferai sortir avec toute ton armée, avec les chevaux, et les gens de cheval, tous parfaitement bien équipés, une grande multitude avec des écus et des boucliers, et tous maniant l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Ceux de Perse, de Cus, et de Put avec eux, qui tous ont des boucliers et des casques.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gomer et toutes ses bandes, la maison de Togarma du fond de l’Aquilon, avec toutes ses troupes, et plusieurs peuples avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Apprête-toi, et tiens-toi prêt, toi, et toute la multitude qui s’est assemblée vers toi, et sois-leur pour garde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Après plusieurs jours tu seras visité, et dans les dernières années tu viendras au pays qui aura été délivré de l’épée, et au peuple ramassé d’entre plusieurs peuples, aux montagnes d’Israël qui auront été continuellement en désert; tu viendras en ce pays-là, lorsque ce pays ayant été retiré d’entre les peuples, tous y habiteront en assurance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Tu monteras donc comme une ruine qui éclate, et tu viendras comme une nuée pour couvrir la terre, toi, et toutes tes bandes, et plusieurs peuples avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Ainsi a dit le Seigneur l’Eternel: il arrivera en ces jours-là que plusieurs choses monteront en ton coeur, et que tu formeras un dessein pernicieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'Car tu diras: je monterai contre le pays dont les villes sont sans murailles; j’envahirai ceux qui sont en repos, qui habitent en assurance, qui demeurent tous dans des villes sans murailles, lesquelles n’ont ni barres ni portes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'Pour enlever un grand butin et faire un grand pillage; pour remettre ta main sur les déserts qui de nouveau étaient habités et sur le peuple ramassé d’entre les nations, lequel vaque à son bétail, et à ses biens, au milieu du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Seba, et Dedan, et les marchands de Tarsis, et tous ses lionceaux, te diront: ne vas-tu pas pour faire un grand butin, et n’as-tu pas assemblé ta multitude pour faire un grand pillage, pour emporter de l’argent et de l’or, pour prendre le bétail et les biens, pour enlever un grand butin?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Toi donc, fils d’homme, prophétise, et dis à Gog: ainsi a dit le Seigneur l’Eternel: en ce jour-là, quand mon peuple d’Israël habitera en assurance, ne le sauras-tu pas?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'Et ne viendras-tu pas de ton lieu, du fond de l’Aquilon, toi, et plusieurs peuples avec toi, eux tous gens de cheval, une grande multitude, et une grosse armée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'Et ne monteras-tu pas contre mon peuple d’Israël, comme une nuée pour couvrir la terre? tu seras aux derniers jours, et je te ferai venir sur ma terre, afin que les nations me connaissent, quand je serai sanctifié en toi, ô Gog! en leur présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Ainsi a dit le Seigneur l’Eternel: n’est-ce pas de toi que j’ai parlé autrefois par le ministère de mes serviteurs, les Prophètes d’Israël, qui ont prophétisé en ces jours-là pendant plusieurs années, qu’on te ferait venir contre eux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Mais il arrivera en ce jour-là, au jour de la venue de Gog sur la terre d’Israël, dit le Seigneur l’Eternel, que ma colère éclatera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Et je parlerai en ma jalousie et en l’ardeur de ma fureur, si en ce jour-là il n’y a une grande agitation sur la terre d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'Et les poissons de la mer, et les oiseaux des cieux, et les bêtes des champs, et tout reptile qui rampe sur la terre, et tous les hommes qui sont sur le dessus de la terre seront épouvantés par ma présence; les montagnes seront renversées, les tours et les murailles seront abattues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Et j’appellerai contre lui l’épée par toutes mes montagnes, dit le Seigneur l’Eternel; l’épée de chacun d’eux sera contre son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Et j’entrerai en jugement avec lui par la mortalité, et par le sang, et je ferai pleuvoir sur lui, et sur ses troupes, et sur les grands peuples qui seront avec lui, des torrents d’eau, des pierres de grêle, du feu et du soufre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Je me glorifierai, je me sanctifierai, je serai connu en la présence de plusieurs nations; et elles sauront que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Toi donc, fils d’homme, prophétise contre Gog, et dis: ainsi a dit le Seigneur l’Eternel: voici, j’en veux à toi, Gog, Prince des chefs de Mésec et de Tubal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Et je te ferai retourner en arrière, n’en laissant que de six l’un, après t’avoir fait monter du fond de l’Aquilon, et t’avoir fait venir sur les montagnes d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Car je romprai ton arc dans ta main gauche, et je ferai tomber tes flèches de ta main droite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Tu tomberas sur les montagnes d’Israël, toi et toutes tes troupes, et les peuples qui seront avec toi; je t’ai livré aux oiseaux de proie entre tous les oiseaux, et aux bêtes des champs, pour en être dévoré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Tu tomberas sur le dessus des champs, parce que j’ai parlé, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Et je mettrai le feu en Magog, et parmi ceux qui demeurent en assurance dans les Iles; et ils sauront que je suis l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Et je ferai connaître le Nom de ma Sainteté au milieu de mon peuple d’Israël; et je ne profanerai plus le Nom de ma Sainteté; les nations sauront que je suis l’Eternel, le Saint en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Voici cela est arrivé, et a été fait, dit le Seigneur l’Eternel; c’est ici la journée dont j’ai parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Et les habitants des villes d’Israël sortiront, et allumeront le feu, et brûleront les armes, les boucliers, les écus, les arcs, les flèches, les bâtons qu’on lance de la main, et les javelots, et ils y tiendront le feu allumé sept ans durant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Et on n’apportera point de bois des champs, et on n’en coupera point des forêts, parce qu’ils feront du feu de ces armes, lorsqu’ils butineront ceux qui les avaient butinés, et qu’ils pilleront ceux qui les avaient pillés, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'Et il arrivera en ce jour-là que je donnerai à Gog dans ces quartiers-là un lieu pour sépulcre en Israël, savoir la vallée des passants, qui est au devant de la mer, et d’étonnement elle réduira les passants au silence; on enterrera là Gog, et toute la multitude de son peuple, et on l’appellera, la vallée d’Hammon-Gog.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Et ceux de la maison d’Israël les enterreront pendant l’espace de sept mois pour purifier le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'Tout le peuple, dis-je, du pays les enterrera, et cela leur sera un nom, savoir le jour auquel j’aurai été glorifié, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'Et ils mettront à part des gens qui ne feront autre chose que parcourir le pays, lesquels avec les passants enterreront ceux qui seront demeurés de reste sur le dessus de la terre, pour la purifier, et ils en chercheront jusques au bout de sept mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Et ces passants-là iront par le pays, et celui qui verra l’os d’un homme, dressera auprès de lui un signal; jusqu’à ce que les enterreurs l’aient enterré dans la vallée d’Hammon-Gog.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Et aussi le nom de la ville sera Hamona, et on nettoiera le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Toi donc, fils d’homme, ainsi a dit le Seigneur l’Eternel: dis aux oiseaux de toutes espèces, et à toutes les bêtes des champs: assemblez-vous et venez; amassez-vous de toutes parts vers mon sacrifice que je fais pour vous, qui est un grand sacrifice sur les montagnes d’Israël, vous mangerez de la chair, et vous boirez du sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Vous mangerez la chair des hommes forts, et vous boirez le sang des principaux de la terre, le sang des moutons, des agneaux, des boucs; et des veaux, tous grasses bêtes de Basan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Vous mangerez de la graisse jusques à en être rassasiés, et vous boirez au sang jusqu’à en être ivres, de la graisse, dis-je, et du sang de mon sacrifice, que j’aurai sacrifié pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Et vous serez rassasiés à ma table, de chevaux, et de bêtes d’attelage, d’hommes forts, et de tous hommes de guerre, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Et je mettrai ma gloire entre les nations, et toutes les nations verront mon jugement que j’aurai exercé, et comment j’aurai mis ma main sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'Et la maison d’Israël connaîtra dès ce jour-là, et dans la suite, que je suis l’Eternel leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Et les nations sauront que la maison d’Israël avait été transportée en captivité à cause de son iniquité, parce qu’ils avaient péché contre moi, et que je leur avais caché ma face, et les avais livrés entre les mains de leurs ennemis, tellement qu’ils étaient tous tombés par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Je leur avais fait selon leur souillure, et selon leur crime, et je leur avais caché ma face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: maintenant je ramènerai la captivité de Jacob, et j’aurai pitié de toute la maison d’Israël, et je serai jaloux du Nom de ma Sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Après qu’ils auront porté leur ignominie, et tout leur crime, par lequel ils avaient péché contre moi, quand ils demeuraient en sûreté dans leur terre, et sans qu’il y eût personne qui les épouvantât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Parce que je les ramènerai d’entre les peuples, que je les rassemblerai des pays de leurs ennemis, et que je serai sanctifié en eux, en la présence de plusieurs nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Et ils sauront que je suis l’Eternel leur Dieu, lorsqu’après les avoir transportés entre les nations, je les aurai rassemblés en leur terre, et que je n’en aurai laissé demeurer là aucun de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Et je ne leur cacherai plus ma face, depuis que j’aurai répandu mon Esprit sur la maison d’Israël, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'En la vingt-cinquième année de notre captivité, au commencement de l’année, au dixième jour du mois, la quatorzième année après que la ville fut prise, en ce même jour la main de l’Eternel fut sur moi, et il m’amena là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'Il m’amena donc par des visions de Dieu, au pays d’Israël, et me posa sur une montagne fort haute, sur laquelle du côté du Midi il y avait comme le bâtiment d’une ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Et après qu’il m’y eut fait entrer, voici un homme, qui à le voir était comme qui verrait de l’airain, lequel avait en sa main un cordeau de lin, et une canne à mesurer, et qui se tenait debout à la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Et cet homme me parla, et me dit: fils d’homme, regarde de tes yeux, et écoute de tes oreilles, et applique ton coeur à toutes les choses que je m’en vais te faire voir, car tu as été amené ici afin que je te les fasse voir, et que tu fasses savoir à la maison d’Israël toutes les choses que tu t’en vas voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Voici donc une muraille au dehors de la maison tout à l’environ. Et comme cet homme avait en la main une canne à mesurer longue de six coudées, chaque coudée étant d’une coudée commune et une paume, il mesura la largeur de ce mur bâti, laquelle était d’une canne, et sa hauteur d’une autre canne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Puis il vint vers une porte qui regardait le chemin tendant vers l’Orient, et monta par ses degrés, et il mesura l’un des poteaux de la porte d’une canne en largeur, et l’autre poteau d’une autre canne en largeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'Puis il mesura chaque chambre d’une canne en longueur, et d’une canne en largeur, et les entre-deux des chambres de cinq coudées, et il mesura d’une canne chacun des poteaux de la porte d’auprès de l’allée qui menait à la porte la plus intérieure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Puis il mesura d’une canne l’allée qui menait à la porte la plus intérieure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Ensuite il mesura de huit coudées l’allée du portail, et ses auvents de deux coudées, ensemble ceux de l’allée qui menait à la porte la plus intérieure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Or les chambres du portail vers le chemin d’Orient étaient trois deçà et trois delà, toutes trois d’une même mesure, et les auvents deçà et delà étaient d’une même mesure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Puis il mesura de dix coudées la largeur de l’ouverture de la première porte, et de treize coudées la longueur de la même porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Ensuite il mesura d’un côté un espace limité au devant des chambres d’une coudée de deçà, et une autre coudée d’espace limité de l’autre côté; puis il mesura chaque chambre de six coudées deçà, et de six coudées delà.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Après cela il mesura le portail depuis le toit d’une chambre jusqu’au toit de l’autre, de la largeur de vingt-cinq coudées; les ouvertures y étaient l’une vis-à-vis de l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Puis il mit en auvents soixante coudées, et au bout des auvents le parvis tout autour du portail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Il y avait ainsi des avenues au devant de la porte, et au devant de l’allée qui menait à la porte intérieure, cinquante coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Or il y avait aux chambres des fenêtres rétrécies, et à leurs auvents, lesquelles regardaient sur le dedans du portail tout à l’entour, et de même aux allées; et les fenêtres qui étaient tout à l’entour, regardaient en dedans, et il y avait des palmes aux auvents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Il me mena donc au dedans du parvis de dehors, et voici des chambres et des perrons, bâtis de tous côtés dans ce parvis, et trente chambres à chaque perron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Or les perrons qui étaient vers les côtés des portes à l’endroit de la longueur des portes, étaient les perrons les plus bas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Ensuite il mesura dans la largeur du parvis depuis le devant de la porte qui menait vers le bas au devant du parvis de dedans et en dehors, cent coudées, même en ce qui était de l’Orient, et en ce qui était du Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Après cela il mesura la longueur et la largeur du parvis de dehors de la porte qui regardait le chemin du Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Et quant aux chambres, trois deçà et trois delà, et quant à ses auvents et ses allées, le tout fut selon les mesures du premier portail; tellement que le portail de ce second parvis de dehors avait en longueur cinquante coudées, et en largeur vingt-cinq coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Ses fenêtres aussi et ses autres allées, et ses palmes furent selon les mesures du parvis de dehors la porte qui regardait le chemin d’Orient; tellement qu’on y montait par sept degrés, et ses allées se rencontraient l’une devant l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Et la porte du parvis de dedans était vis-à-vis de la première porte du Septentrion, comme elle était au côté qui regardait vers l’Orient; et il mesura depuis une porte jusques à l’autre cent coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Après cela il me conduisit au chemin tirant vers le Midi, et voici le portail du chemin tirant vers le Midi, et il en mesura les auvents et les allées suivant les mesures précédentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Il y avait aussi des fenêtres dans ce portail, et dans ses allées tout à l’entour, pareilles aux fenêtres précédentes; tellement qu’il avait cinquante coudées de long, et vingt-cinq coudées de large.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Il avait aussi sept degrés par lesquels on y montait, et devant lesquels se rencontraient ses allées; de même il avait des palmes pour ses auvents, l’une deçà, et l’autre delà.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Pareillement le parvis de dedans avait sa porte vis-à-vis du chemin tirant vers le Midi; de sorte qu’il mesura depuis cette porte jusques à la porte du chemin tirant vers le Midi, cent coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Après cela il me fit entrer au parvis de dedans par la porte du côté du Midi, et il mesura le portail qui y était du côté du Midi, selon les mesures précédentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'Tellement que les chambres qui y étaient, ses auvents et ses allées avaient les mesures précédentes, et ce portail et ses allées tout autour, avaient des fenêtres, et il avait cinquante coudées de long, et vingt-cinq coudées de large.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Et il avait des allées tout à l’entour, qui avaient vingt-cinq coudées de long, et cinq coudées de large.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Il avait aussi ses allées vers le parvis de dehors, et des palmes à ses auvents, et huit degrés par lesquels on y montait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Après cela il me fit entrer au parvis de dedans la porte qui regardait le chemin de l’Orient, et il y mesura le portail selon les mesures précédentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Tellement que les chambres qui y étaient, ses auvents, et ses allées, avaient les mesures précédentes, et ce portail et ses allées qu’il avait tout à l’environ, avaient des fenêtres, et il avait cinquante coudées de long, et vingt-cinq de large.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Il avait aussi ses allées vers le parvis de dehors, et des palmes à ses auvents deçà et delà, et huit degrés par lesquels on y montait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Après cela il me mena vers la porte du Septentrion, et il la mesura selon les mesures précédentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Et ses chambres, ses auvents, et ses allées. Or il y avait des fenêtres tout à l’entour; et un portail de cinquante coudées de long, et de vingt-cinq coudées de large.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Il y avait aussi des auvents vers le parvis de dehors, et des palmes à ses auvents, deçà et delà, et huit degrés par lesquels on y montait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Il y avait aussi des chambres qui avaient leurs ouvertures vers les auvents qui se rendaient aux portes près desquelles on lavait les holocaustes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'Il y avait aussi dans l’allée du portail deux tables deçà, et deux tables delà, pour y égorger les bêtes qu’on sacrifierait pour l’holocauste, et les bêtes qu’on sacrifierait pour le péché, et les bêtes qu’on sacrifierait pour le délit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Et vers l’un des côtés de la porte au dehors vers le lieu où l’on montait, à l’entrée de la porte qui regardait le Septentrion, il y avait deux tables, et à l’autre côté de la même porte qui tirait vers l’allée de la porte, deux autres tables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Il y avait donc quatre tables deçà, et quatre tables delà, vers les jambages de la porte; et ainsi huit tables sur lesquelles on égorgeait les bêtes qu’on sacrifiait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Or les quatre tables qui étaient pour l’holocauste, étaient de pierre de taille, de la longueur d’une coudée et demie, et de la largeur d’une coudée et demie, et de la hauteur d’une coudée; et même on devait poser sur elles les instruments avec lesquels on égorgeait l’holocauste, et les autres sacrifices.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Il y avait aussi au dedans de la maison tout à l’entour, des râteliers à écorcher, larges d’une paume, fort bien accommodés, d’où on apportait la chair des oblations sur les tables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Et au dehors de la porte qui était la plus intérieure, il y avait des chambres pour les chantres au parvis intérieur, lesquelles étaient au côté de la porte du Septentrion, et regardaient le chemin tirant vers le Midi; et puis une rangée de chambres qui étaient au côté de la porte Orientale, lesquelles regardaient le chemin tirant vers le Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Puis il me dit: ces chambres qui regardent le chemin tirant vers le Midi, sont pour les Sacrificateurs qui ont la charge de la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Mais ces chambres qui regardent le chemin tirant vers le Septentrion, sont pour les Sacrificateurs qui ont la charge de l’autel, qui sont les fils de Tsadok, lesquels d’entre les enfants de Lévi s’approchent de l’Eternel pour faire son service.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Puis il mesura un parvis de la longueur de cent coudées, et de la largeur d’autres cent coudées, en carré, et l’autel était au devant du Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Ensuite il me fit entrer dans le vestibule du Temple; et il mesura les poteaux du vestibule de cinq coudées deçà, et de cinq coudées delà, puis la largeur de la porte de trois coudées deçà, et de trois coudées delà.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'La longueur de ce vestibule était de vingt coudées, et la largeur de onze coudées, il se prenait dès les degrés par lesquels on y montait; et il y avait des colonnes près des poteaux, l’une deçà et l’autre delà.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Puis il me fit entrer vers le Temple, et il mesura des poteaux de six coudées de largeur d’un côté, et de six coudées de largeur de l’autre côté, qui est la largeur du Tabernacle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'Ensuite il mesura la largeur de l’ouverture de la porte qui était de dix coudées, et les côtés de l’ouverture de cinq coudées, d’une part, et de cinq coudées de l’autre part. Puis il mesura dans le Temple une longueur de quarante coudées, et une largeur de vingt coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Puis il entra vers le lieu qui était plus intérieur, et il mesura un poteau d’une ouverture de porte de deux coudées, et la hauteur de cette ouverture de six coudées, et la largeur de cette ouverture de sept coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Puis il mesura au dedans de cette ouverture une longueur de vingt coudées, et une largeur de vingt coudées sur le sol du Temple; et il me dit: C’est ici le lieu Très-saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Puis il mesura l’épaisseur de la muraille du Temple, qui fut de six coudées, et la largeur des chambres qui étaient tout autour du Temple, de quatre coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Or quant à ces chambres, il y en avait trois l’une sur l’autre, tellement qu’il y en avait trente, ainsi rangées, desquelles les soliveaux entraient dans une muraille qui touchait à la muraille du Temple, et qui avait été ajoutée tout à l’entour, afin que les soliveaux de ces chambres y fussent appuyés, et qu’ils ne portassent point sur la muraille du Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Or il y avait une largeur et un circuit autour du Temple, beaucoup plus haut que les chambres, car cette muraille, par le moyen de laquelle on montait tout autour du Temple, était beaucoup plus haute tout à l’entour du Temple, et ainsi elle était cause que le Temple était plus large en haut qu’en bas, et par ce moyen on montait de l’étage d’en bas à celui qui était au-dessus de l’étage du milieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Je vis aussi vers le Temple tout à l’entour une hauteur qui était comme les fondements des chambres, laquelle avait une grande canne, c’est-à-dire, six coudées de celles qui vont jusqu’à l’aisselle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'La largeur de la muraille qu’avaient les chambres vers le dehors, était de cinq coudées; lequel espace était aussi dans la muraille, où on laissait quelque endroit qui n’était point bâti; et ces deux murailles étaient ce sur quoi étaient appuyées les chambres d’alentour du Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'Or entre les chambres il y avait un espace de vingt coudées de largeur tout autour du Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'L’ouverture des chambres était vers la muraille en laquelle on laissait quelque endroit qui n’était point bâti, savoir une ouverture du côté du chemin vers le Septentrion, et une autre ouverture du côté vers le Midi; et la largeur du lieu où était la muraille, en laquelle on laissait quelque endroit qui n’était point bâti, était de cinq coudées tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Or le bâtiment qui se rendait sur le devant de la séparation, qui faisait le côté du chemin vers l’Occident, avait la largeur de soixante-dix coudées, et la muraille du bâtiment cinq coudées de largeur tout à l’entour, tellement que sa longueur était de quatre- vingt-dix coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Puis il mesura le Temple, qui eut en longueur cent coudées; de sorte que les séparations, les bâtiments et les parois qui y étaient, avaient en longueur cent coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'La largeur aussi du devant du Temple, et des séparations vers l’Orient, cent coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Et il mesura la longueur du bâtiment qui était vis-à-vis de la séparation qui était au derrière du Temple, et de ses chambres de côté et d’autre, et elle était de cent coudées; puis il y avait le Temple intérieur, et les allées du parvis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'Les poteaux et les fenêtres qui étaient rétrécies, et les chambres d’alentour du Temple dans tous leurs trois étages, depuis le long des poteaux, n’étaient qu’un lambris de bois tout à l’entour; et le sol en était couvert jusques aux fenêtres, qui en étaient couvertes de même;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Jusques au dessus des ouvertures, et jusques à la maison intérieure aussi bien qu’au dehors, et par dessus toutes les murailles d’alentour, tant dans la maison intérieure que dans l’extérieure: en y gardant toutes les mesures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Et ce lambris était sculpté de Chérubins et de palmes, tellement qu’il y avait une palme entre un Chérubin et l’autre, et chaque Chérubin avait deux faces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'Et la face d’homme était tournée vers la palme d’un côté, et la face de lionceau était tournée vers la palme de l’autre côté; et ainsi il était sculpté par toute la maison tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Depuis le sol jusques au dessus des ouvertures il y avait des Chérubins et des palmes sculptées, même jusqu’au dessus de la muraille du Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Les poteaux de la porte du Temple étaient carrés; et le devant du lieu Saint avait une représentation telle que la représentation précédente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'L’autel était de bois, de la hauteur de trois coudées, et de deux coudées de longueur; et ses coins qu’il avait, et sa longueur, et ses côtés étaient de bois. Puis il me dit: c’est ici la Table qui est devant l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Il y avait aussi des battants à la porte du Temple, et de même à la porte du lieu Très-saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'Or chacun de ces battants était divisé en deux qui étaient deux battants qui se repliaient: de sorte que chacun des deux battants était encore brisé en deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Il y avait aussi des Chérubins et des palmes figurées sur les portes du Temple, comme il y en avait de figurées sur les parois. Il y avait aussi de grosses pièces de bois sur le devant du porche en dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Il y avait pareillement des fenêtres rétrécies, et des palmes deçà et delà, aux côtés du porche; il y avait aussi les chambres qui étaient autour du Temple, et puis les grosses pièces de bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Après cela il me fit sortir vers le parvis de dehors, par le chemin tirant vers le Septentrion; et il me fit entrer vers les chambres qui étaient le long de la séparation, et qui étaient le long du bâtiment vers le Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'Vis-à-vis de la longueur de cent coudées il y avait une ouverture vers le Septentrion, et la largeur était de cinquante coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Le long de vingt coudées qui étaient du parvis intérieur, et le long du perron qui était du parvis de dehors, il y avait des chambres vis-à-vis des autres chambres, à trois étages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Et au devant de ces chambres il y avait un promenoir large de dix coudées en dedans, vers lequel il y avait un chemin d’une coudée, et leurs ouvertures étaient vers le Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Or les chambres de dessus étaient rétrécies; car les chambres basses et les moyennes, desquelles était composé ce bâtiment, s’avançaient plus que celles-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Car elles étaient à trois étages, et n’avaient point de colonnes, telles que sont les colonnes des parvis, et pour cela il avait été réservé quelque chose des chambres basses et des moyennes dès le sol du premier étage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Et le parquet qui était au dehors vis-à-vis des chambres, et qui avait un chemin tirant vers le parvis de dehors, vis-à-vis des chambres, avait cinquante coudées de long.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Car la longueur des chambres qu’avait le parvis de dehors, était de cinquante coudées. Et voici, il y avait cent coudées dans ce qui était vis-à-vis du Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Or au-dessous des chambres qui étaient dans ce parvis était l’endroit par lequel il était entré du côté d’Orient, quand il était venu là du parvis extérieur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Il y avait dans la largeur, le parquet du parvis vers les chemins qui se rendaient en Orient, et des chambres vis-à-vis de la séparation, et vis-à-vis du bâtiment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'Et il y avait des chemins au devant d’elles, à la façon des chambres qui étaient vers le chemin du Septentrion, et elles avaient une même longueur et une même largeur, et toutes les mêmes sorties, selon leurs dispositions, et selon leurs ouvertures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Même les ouvertures des chambres qui étaient vers le chemin du Midi, étaient comme les ouvertures de ces chambres-là; tellement que l’ouverture était là où commençait le chemin, et le chemin se rendait vis-à-vis du parquet tout accommodé, savoir le chemin qui venait du parvis d’Orient pour aller vers les chambres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Après cela il me dit: les chambres du parvis du Septentrion, et les chambres du parvis du Midi, qui sont le long des séparations, étant les chambres du lieu Saint, sont celles où les Sacrificateurs qui approchent de l’Eternel, mangeront les choses très-saintes. Ils poseront donc là les choses très-saintes, savoir les gâteaux, les oblations pour le péché, et les oblations pour le délit; car ce lieu est saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Quand les Sacrificateurs y seront entrés, ils ne sortiront point du lieu Saint pour venir au parvis extérieur, qu’ils n’aient posé là leurs habits avec lesquels ils font le service; car ils sont saints; et qu’ils n’aient revêtu d’autres vêtements; alors ils s’approcheront du parvis du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Après qu’il eut achevé les mesures de la maison intérieure, il me fit sortir par le chemin de la porte qui regardait le chemin de l’Orient, puis il mesura l’enclos qui était tout à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Il mesura donc le côté d’Orient avec la canne à mesurer, et il y eut tout le long cinq cents cannes, de la canne à mesurer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Ensuite il mesura le côté du Septentrion, qui eut tout le long cinq cents cannes, de la canne à mesurer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Puis il mesura le côté du Midi qui eut cinq cents cannes, de la canne à mesurer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Après il fit le tour du côté de l’Occident, et le mesura, et il y eut cinq cents cannes, de la canne à mesurer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Il mesura donc cet enclos à ses quatre côtés, dans lesquels il y avait une muraille tout à l’entour, et cette muraille avait à l’endroit de la longueur cinq cents cannes, et à l’endroit de la largeur cinq cents cannes, et elle servait à séparer le lieu saint d’avec le lieu profane.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Puis il me ramena vers la porte mentionnée ci-dessus, savoir vers la porte qui regardait le chemin de l’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Et voici la gloire du Dieu d’Israël qui venait de devers le chemin de l’Orient, et le bruit qu’il menait, était comme le bruit de beaucoup d’eaux, et la terre resplendissait de sa gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'Et la vision que j’eus alors était semblable à celle que j’avais vue lorsque j’étais venu pour détruire la ville, tellement que ces visions étaient comme la vision que j’avais vue sur le fleuve de Kébar; et je me prosternai le visage contre terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Puis la gloire de l’Eternel entra dans la maison par le chemin de la porte qui regardait le chemin de l’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Et l’Esprit m’enleva, et me fit entrer dans le parvis intérieur, et voici la gloire de l’Eternel avait rempli la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Et je l’ouïs s’adressant à moi du dedans de la maison, et l’homme qui me conduisait était debout près de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'L’Eternel donc me dit: fils d’homme, c’est ici le lieu de mon trône, et le lieu des plantes de mes pieds, dans lequel je ferai ma demeure pour jamais parmi les enfants d’Israël; et la maison d’Israël ne souillera plus mon saint Nom, ni eux, ni leurs Rois, par leurs fornications; mais plutôt ils souilleront leurs hauts lieux par les cadavres de leurs Rois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Car ils ont mis leur seuil près de mon seuil, et leur poteau tout joignant mon poteau, tellement qu’il n’y a eu que la paroi entre moi et eux; et ainsi ils ont souillé mon saint Nom par leurs abominations, lesquelles ils ont faites, c’est pourquoi je les ai consumés en ma colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Maintenant ils rejetteront loin de moi leurs adultères et les cadavres de leurs Rois, et je ferai ma demeure pour jamais parmi eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Toi donc, fils d’homme, fais entendre à la maison d’Israël ce qui est de ce Temple; et qu’ils soient confus à cause de leurs iniquités; et qu’ils en mesurent le plan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Quand donc ils auront été confus de tout ce qu’ils ont fait, fais- leur entendre la forme de ce Temple, et sa disposition, avec ses sorties et ses entrées, et toutes ses figures et toutes ses ordonnances, et toutes ses formes, et toutes ses lois, et les écris, eux le voyant, afin qu’ils observent toute la disposition qu’il y faut garder, et toutes les ordonnances qui en auront été établies, et qu’ils les pratiquent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'C’est donc ici la Loi de ce Temple; tout l’enclos de ce Temple, sur le haut de la montagne, sera un lieu très-saint tout à l’entour. Voilà telle est la Loi de ce Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Mais ce sont ici les mesures de l’autel prises à la coudée, qui vaut une coudée commune et une paume. Le sein de l’autel aura une coudée de hauteur et une coudée de largeur, et son enclos sur son bord tout à l’entour sera haut d’une demi-coudée; ce sein sera le dos de l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Or depuis le sein enfoncé en terre jusques à la saillie d’en bas il y aura deux coudées, et cette saillie aura une coudée de largeur; puis il y aura quatre coudées depuis la petite saillie jusques à la grande saillie, laquelle aura une coudée de largeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Après cela il y aura l’hariel, haut de quatre coudées; puis il y aura quatre cornes qui sortiront de l’hariel, et qui s’élèveront en haut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Et l’hariel aura douze coudées de longueur, correspondantes à douze coudées de largeur; et il sera carré par ses quatre côtés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Mais chaque saillie aura quatorze coudées de longueur, correspondantes à quatorze coudées de largeur à ses quatre côtés, et elle aura tout à l’entour un enclos haut de demi-coudée, parce que chaque saillie aura un sein d’une coudée tout à l’entour, et les endroits par où on y montera regarderont l’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Et il me dit: fils d’homme, ainsi a dit le Seigneur l’Eternel: ce sont ici les statuts de l’autel pour le jour qu’il aura été fait, afin qu’on y offre l’holocauste, et qu’on y répande le sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'C’est que tu donneras aux Sacrificateurs Lévites, qui sont de la race de Tsadok, et qui approchent de moi, dit le Seigneur l’Eternel, afin qu’ils y fassent mon service, un jeune veau en sacrifice pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Et tu prendras de son sang, et en mettras sur les quatre cornes de l’autel, et sur les quatre coins des saillies, et sur les enclos à l’entour, et ainsi tu purifieras l’autel, et feras propitiation pour lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Puis tu prendras le veau qui est le sacrifice pour le péché, et on le brûlera au lieu ordonné de la maison, au dehors du Sanctuaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Et le second jour tu offriras un bouc d’entre les chèvres, sans tare, en sacrifice pour le péché; et on en purifiera l’autel comme on l’aura purifié avec le veau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Après que tu auras achevé de purifier l’autel, tu offriras un jeune veau sans tare, et un bélier sans tare, d’entre les brebis;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Tu les offriras en la présence de l’Eternel, et les Sacrificateurs jetteront du sel par dessus, et les offriront en holocauste à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Durant sept jours tu sacrifieras chaque jour un bouc, tel qu’on sacrifie pour le péché, et les Sacrificateurs sacrifieront un jeune veau et un bélier sans tare, d’entre les brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Durant sept jours les Sacrificateurs feront propitiation pour l’autel, et le nettoieront, et chacun d’eux sera consacré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Après qu’on aura achevé ces jours-là, s’il arrive dès le huitième jour, et dans la suite, que les Sacrificateurs sacrifient sur cet autel vos holocaustes et vos sacrifices de prospérité, je serai apaisé envers vous, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Puis il me ramena au chemin de la porte extérieure du Sanctuaire, laquelle regardait l’Orient, et elle était fermée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Et l’Eternel me dit: cette porte-ci sera fermée, et ne sera point ouverte, et personne n’y passera, parce que l’Eternel le Dieu d’Israël est entré par cette porte; elle sera donc fermée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Elle sera pour le Prince: le Prince sera le seul qui s’y assiéra pour manger devant l’Eternel; il entrera par le chemin de l’allée de cette porte-là, et sortira par le même chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Et il me fit revenir par le chemin de la porte du Septentrion jusque sur le devant de la maison, et je regardai, et voici, la gloire de l’Eternel avait rempli la maison de l’Eternel, et je me prosternai sur ma face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Alors l’Eternel me dit: fils d’homme, applique ton coeur, et regarde de tes yeux, et écoute de tes oreilles tout ce dont je te vais parler, touchant toutes les ordonnances et toutes les lois qui concernent la maison de l’Eternel: applique ton coeur à ce qui concerne l’entrée de la maison par toutes les sorties du Sanctuaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'Tu diras donc à ceux qui sont extrêmement rebelles, savoir à la maison d’Israël: ainsi a dit le Seigneur l’Eternel: maison d’Israël! Qu’il vous suffise qu’entre toutes vos abominations,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'Vous ayez fait entrer les enfants de l’étranger, qui étaient incirconcis de coeur, et incirconcis de chair, pour être dans mon Sanctuaire, afin de profaner ma maison, quand vous avez offert ma viande, savoir la graisse et le sang, et ils ont enfreint mon alliance, outre toutes vos autres abominations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Et vous n’avez point donné ordre que mes choses saintes fussent observées, mais vous avez établi comme il vous a plu dans mon Sanctuaire, des gens pour y être les gardes des choses que j’avais commandé de garder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Ainsi a dit le Seigneur l’Eternel: pas un de tous ceux qui seront enfants d’étranger, incirconcis de coeur, et incirconcis de chair, n’entrera dans mon Sanctuaire, même pas un d’entre tous les enfants d’étranger, qui seront parmi les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Mais les Lévites qui se sont éloignés de moi, lorsque Israël s’est égaré, et qui se sont égarés de moi pour suivre leurs idoles, porteront la peine de leur iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Toutefois ils seront employés dans mon Sanctuaire aux charges qui sont vers les portes de la maison, et ils feront le service de la maison; ils égorgeront pour le peuple les bêtes pour l’holocauste, et pour les autres sacrifices, et se tiendront prêts devant lui pour le servir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Parce qu’ils les ont servis se présentant devant leurs idoles, et qu’ils ont été une occasion de chute dans le crime à la maison d’Israël, à cause de cela j’ai levé ma main en jurant contre eux, dit le Seigneur l’Eternel, qu’ils porteront la peine de leur iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Tellement qu’ils n’approcheront plus de moi pour m’exercer la sacrificature, ni pour approcher d’aucune de mes choses saintes aux lieux les plus saints, mais ils porteront leur confusion et leurs abominations, lesquelles ils ont commises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'C’est pourquoi je les établirai pour avoir la garde de la maison pour tout son service, et pour tout ce qui s’y fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Mais quant aux Sacrificateurs Lévites, enfants de Tsadok, qui ont soigneusement administré ce qu’il fallait faire dans mon Sanctuaire, lorsque les enfants d’Israël se sont éloignés de moi, ceux-là s’approcheront de moi pour faire mon service, et se tiendront devant moi pour m’offrir la graisse et le sang, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Ceux-là entreront dans mon Sanctuaire, et ceux-là s’approcheront de ma table, pour faire mon service, et ils administreront soigneusement ce que j’ai ordonné de faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Et il arrivera que quand ils entreront aux portes des parvis intérieurs, ils se vêtiront de robes de lin; et il n’y aura point de laine sur eux pendant qu’ils feront le service aux portes des parvis intérieurs et dans le Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Ils auront des ornements de lin sur leur tête, et des caleçons de lin sur leurs reins, et ne se ceindront point à l’endroit où l’on sue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Mais quand ils sortiront au parvis extérieur, au parvis, dis-je, extérieur, vers le peuple, ils se dévêtiront de leurs habits, avec lesquels ils font le service, et les poseront dans les chambres saintes, et se revêtiront d’autres habits, afin qu’ils ne sanctifient point le peuple avec leurs habits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Ils ne se raseront point la tête, ni ne laisseront point croître leurs cheveux, mais simplement ils tondront leurs têtes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Pas un des Sacrificateurs ne boira du vin, quand ils entreront au parvis intérieur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Ils ne prendront point pour femme une veuve, ni une répudiée; mais ils prendront des vierges, de la race de la maison d’Israël, ou une veuve qui soit veuve d’un Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Et ils enseigneront à mon peuple la différence qu’il y a entre la chose sainte et la chose profane, et leur feront entendre la différence qu’il y a entre ce qui est souillé et ce qui est net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Et quand il surviendra quelque procès, ils assisteront au jugement, et jugeront suivant les lois que j’ai données; et ils garderont mes lois et mes statuts dans toutes mes solennités, et ils sanctifieront mes Sabbats.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Pas un des Sacrificateurs n’entrera vers le corps mort d’aucun homme, de peur d’en être souillé, si ce n’est que ce soit pour leur père, pour leur mère, pour leur fils, pour leur fille, pour leur frère, et pour leur soeur qui n’aura point eu de mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Et après que chacun d’eux se sera purifié, on lui comptera sept jours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'Et le jour qu’il entrera aux lieux saints, savoir au parvis intérieur pour faire le service aux lieux saints, il offrira un sacrifice pour son péché, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Et cela leur sera pour héritage. Ce sera moi qui serai leur héritage, car vous ne leur donnerez aucune possession en Israël, et ce sera moi qui serai leur possession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Ils mangeront donc les gâteaux et ce qui s’offrira pour le péché, et ce qui s’offrira pour le délit; et tout interdit en Israël leur appartiendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Et les prémices de tout ce qui est produit le premier en toutes choses, et de tout ce qui sera présenté en offrande élevée de toutes choses, d’entre toutes vos offrandes élevées, appartiendront aux Sacrificateurs; vous donnerez aussi les prémices de vos pâtes aux Sacrificateurs, afin qu’ils fassent reposer la bénédiction sur la maison de chacun de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Les Sacrificateurs ne mangeront point de chair d’aucune bête morte d’elle-même, ni rien de déchiré, soit oiseau, soit bête à quatre pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Or quand vous partagerez au sort le pays en héritage, vous en lèverez une portion pour l’Eternel, la lui présentant comme en offrande élevée, laquelle étant prise sur la longueur du pays, sera sanctifiée d’entre toutes les autres portions du pays, et aura de longueur vingt-cinq mille cannes, et de largeur, dix mille; ce sera une chose sainte dans tous ses confins à l’entour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'De cette portion il y aura cinq cents cannes correspondantes à cinq cents autres cannes, mesurées en carré à l’entour, pour le lieu Saint, et cinquante coudées à l’entour pour ses faubourgs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Tu mesureras donc de cette mesure l’espace du lieu Saint, savoir de la longueur de vingt-cinq mille, et de la largeur de dix mille cannes; et le Sanctuaire, et le lieu Très-saint, sera dans cet espace.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Cette portion sanctifiée d’entre les autres du pays appartiendra aux Sacrificateurs ministres du Sanctuaire, qui approchent de l’Eternel pour faire son service, et elle leur sera un lieu pour des maisons, et un Sanctuaire pour le Sanctuaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Puis il y aura vingt-cinq mille autres cannes en longueur, et dix mille en largeur, lesquelles appartiendront aux Lévites qui font le service de la maison, pour être leur possession, avec les vingt chambres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Puis vous donnerez pour la possession de la ville la largeur de cinq mille, et la longueur de vingt-cinq mille, suivant la proportion de la portion sanctifiée, qui aura été levée sur toute la masse; et cela sera pour toute la maison d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Puis vous assignerez la portion du Prince tant au delà de la portion sanctifiée qui aura été levée sur toute la masse, qu’au deçà de la possession de la ville, savoir tout le long de la portion sanctifiée qui aura été levée sur toute la masse, et tout le long de la possession de la ville, tirant depuis le canton de l’Occident, jusques à l’Occident, et depuis le canton qui regarde vers l’Orient, jusque vers l’Orient; tellement que l’autre longueur sera aux parties opposées à l’une des autres portions, tirant depuis les confins d’Occident vers les confins qui regardent vers l’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Ce qui sera de toute cette terre-là appartiendra au Prince pour être possédé par lui au pays d’Israël; et les Princes que j’établirai ne fouleront plus mon peuple, mais ils distribueront le pays à la maison d’Israël, selon leurs Tribus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Ainsi a dit le Seigneur l’Eternel: Princes d’Israël, qu’il vous suffise; ôtez la violence et le pillage, et faites jugement et justice; ôtez vos extorsions de dessus mon peuple, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Ayez la balance juste, et l’épha juste, et le bath juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'L’épha et le bath seront de même mesure; tellement qu’on prendra un bath pour la dixième partie d’un homer, et l’épha sera la dixième partie d’un homer, la mesure de l’un et de l’autre se rapportera à l’homer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Et le sicle sera de vingt oboles; et vingt sicles, vingt-cinq sicles, quinze sicles feront la mine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'C’est ici l’oblation que vous offrirez en offrande élevée; la sixième partie d’un épha d’un homer de blé; et vous donnerez la sixième partie d’un épha d’un homer d’orge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Et parce que le bath est la mesure pour l’huile, l’offrande ordonnée pour l’huile sera la dixième partie d’un bath pour core, en tant que dix baths feront un homer; car dix baths feront un homer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Pareillement l’offrande ordonnée des bêtes du menu bétail sera de deux cents l’une, même des meilleurs pâturages d’Israël; toute laquelle oblation sera employée en gâteaux, et en holocaustes, et en sacrifices de prospérité, afin de faire propitiation pour vous, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Tout le peuple qui est du pays sera tenu à cette offrande élevée, pour celui qui sera Prince en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Mais le Prince sera tenu de fournir les holocaustes, et les gâteaux, et les aspersions qu’il faudra offrir aux fêtes solennelles, aux nouvelles lunes et aux Sabbats, et dans toutes les solennités de la maison d’Israël. Il tiendra prêtes les bêtes qu’on sacrifiera pour le péché, et les gâteaux, et les bêtes qu’on sacrifiera pour l’holocauste, et les bêtes qu’on sacrifiera pour les sacrifices de prospérité, afin de faire propitiation pour la maison d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Ainsi a dit le Seigneur l’Eternel: au premier mois, au premier jour du mois, tu prendras un jeune veau sans tare, et tu purifieras le Sanctuaire par ce sacrifice offert pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Tellement que le Sacrificateur prendra du sang de ce sacrifice offert pour le péché, et en mettra sur les poteaux de la maison, et sur les quatre coins des saillies de l’autel, et sur les poteaux des portes des parvis intérieurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Tu en feras ainsi au septième jour du même mois, à cause des hommes qui pèchent par ignorance, et à cause des hommes simples; et vous ferez ainsi propitiation pour la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Au premier mois au quatorzième jour du mois, vous aurez la Pâque, fête solennelle qui durera sept jours, pendant lesquels on mangera des pains sans levain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Et en ce jour-là le Prince offrira un veau pour le péché, tant pour lui que pour tout le peuple du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Pareillement durant les sept jours de cette fête solennelle, il offrira chaque jour sept veaux et sept béliers, sans tare, pour l’holocauste qu’on offrira à l’Eternel, et un bouc d’entre les chèvres pour le sacrifice pour le péché, chacun de ces sept jours- là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Pareillement il offrira un épha pour le gâteau de chaque veau, et un épha pour le gâteau de chaque bélier, et un hin d’huile pour chaque épha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Au septième mois, le quinzième jour du mois, en la fête solennelle, il offrira durant sept jours les mêmes choses, savoir le même sacrifice pour le péché, le même holocauste, les mêmes gâteaux, et les mêmes mesures d’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Ainsi a dit le Seigneur l’Eternel: la porte du parvis intérieur, laquelle regarde l’Orient, sera fermée les six jours ouvriers, mais elle sera ouverte le jour du Sabbat, et pareillement elle sera ouverte le jour de la nouvelle lune.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Et le Prince y entrera par le chemin de l’allée de la porte du parvis extérieur, et se tiendra près de l’un des poteaux de l’autre porte, et les Sacrificateurs prépareront son holocauste et ses sacrifices de prospérité; puis il se prosternera sur le seuil de cette autre porte, et ensuite il sortira; mais cette autre porte ne sera point fermée jusques au soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Tellement que le peuple du pays se prosternera devant l’Eternel à l’entrée de cette autre porte-ci, les jours de Sabbat et des nouvelles lunes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Or l’holocauste que le Prince offrira à l’Eternel le jour du Sabbat sera de six agneaux sans tare, et d’un bélier sans tare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'Et le gâteau pour le bélier sera d’un épha, et le gâteau pour chacun des agneaux sera selon ce qu’il pourra donner; mais il y aura un hin d’huile pour chaque épha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Et au jour de la nouvelle Lune son holocauste sera d’un jeune veau, sans tare, et de six agneaux et d’un bélier, aussi sans tare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'Et il offrira pour le gâteau du veau, un épha, et pour le gâteau du bélier, un autre épha, et pour chacun des agneaux selon ce qu’il pourra donner; mais il y aura un hin d’huile pour chaque épha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Et comme le Prince sera entré au Temple par le chemin de l’allée de cette même porte du parvis extérieur, laquelle regarde l’Orient, aussi sortira-t-il par le même chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Mais quand le peuple du pays y entrera pour se présenter devant l’Eternel, aux fêtes solennelles, celui qui y entrera par le chemin de la porte du Septentrion pour y adorer l’Eternel, sortira par le chemin de la porte du Midi; et celui qui y entrera par le chemin de la porte du Midi, sortira par le chemin de la porte qui regarde vers le Septentrion; tellement que personne ne retournera par le chemin de la porte par laquelle il sera entré, mais il sortira par celle qui est vis-à-vis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Alors le Prince entrera parmi eux, quand ils entreront; et quand ils sortiront, ils sortiront ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Or dans ces fêtes solennelles, et dans ces solennités, le gâteau d’un veau sera d’un épha, et le gâteau d’un bélier d’un autre épha, et le gâteau de chacun des agneaux sera selon que le Prince pourra donner, et il y aura un hin d’huile pour chaque épha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Que si le Prince offre un sacrifice volontaire, quelque holocauste, soit quelques sacrifices de prospérités en offrande volontaire à l’Eternel, on lui ouvrira la porte qui regarde l’Orient, et il offrira son holocauste et ses sacrifices de prospérités comme il les offre le jour du Sabbat, puis il sortira, et après qu’il sera sorti, on fermera cette porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Tu sacrifieras chaque jour en holocauste à l’Eternel un agneau d’un an sans tare, tu le sacrifieras tous les matins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Tu offriras aussi tous les matins avec lui un gâteau, fait de la sixième partie d’un épha, et de la troisième d’un hin d’huile pour en détremper la fine farine; c’est là le gâteau continuel qu’il faut offrir par ordonnances perpétuelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Ainsi on offrira tous les matins en holocauste continuel cet agneau et ce gâteau détrempé avec cette huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Ainsi a dit le Seigneur l’Eternel: quand le Prince aura fait un don de quelque pièce de son héritage à quelqu’un de ses fils, ce don appartiendra à ses fils; parce qu’ils ont droit de possession en l’héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Mais s’il fait un don de quelque pièce de son héritage à l’un de ses serviteurs, le don lui appartiendra bien, mais seulement jusques à l’an d’affranchissement, auquel il retournera au Prince; car quoi qu’il en soit, c’est son héritage qui appartient à ses fils, c’est pourquoi il leur demeurera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Et le Prince n’usurpera rien de l’héritage du peuple, les fraudant de la possession qui leur appartient, seulement il laissera en héritage à ses fils la possession qui lui appartient, afin qu’aucun de mon peuple ne soit chassé de sa possession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Puis il me mena par l’entrée qui était vers le côté de la porte, aux chambres saintes qui appartenaient aux Sacrificateurs, lesquelles regardaient vers le Septentrion, et voilà, il y avait un certain lieu aux deux côtés du fond qui regardaient vers l’Occident.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Et il me dit: c’est là le lieu auquel les Sacrificateurs bouilliront le reste de la bête qu’on aura sacrifiée pour le délit, et le reste de la bête qu’on aura sacrifiée pour le péché, et où ils cuiront les gâteaux; afin qu’ils ne les emportent point au parvis extérieur pour en sanctifier le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Puis il me fit sortir vers le parvis extérieur, et me fit traverser vers les quatre coins du parvis, et voici, il y avait un parvis à chaque coin du parvis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'Tellement qu’aux quatre coins de ce parvis il y avait d’autres parvis qui y étaient joints, et ils étaient longs de quarante coudées, et larges de trente; et tous quatre avaient une même mesure, et avaient leurs quatre coins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Tous ces quatre parvis avaient une rangée de bâtiments élevés tout à l’entour, et ce qui était bâti au dessous de ces rangées de bâtiment élevé, tout à l’entour, c’étaient des lieux propres à cuire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Et il me dit: ce sont ici les cuisines, où ceux qui font le service de la maison cuiront les sacrifices du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Puis il me fit retourner vers l’entrée de la maison, et voici des eaux qui sortaient de dessous le seuil de la maison vers l’Orient, car le devant de la maison était vers l’Orient; et ces eaux-là descendaient de dessous, du côté droit de la maison de devers le côté Méridional de l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Puis il me fit sortir par le chemin de la porte qui regardait vers le Septentrion, et me fit faire le tour par le chemin extérieur jusqu’à la porte extérieure, même jusques au chemin qui regardait l’Orient, et voici, les eaux coulaient du côté droit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Quand cet homme commença de s’avancer vers l’Orient, il avait en sa main un cordeau, et il en mesura mille coudées; puis il me fit passer au travers de ces eaux-là, et elles me venaient jusqu’aux deux chevilles des pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Puis il mesura mille autres coudées; et il me fit passer au travers de ces eaux-là, et elles me venaient jusqu’aux deux genoux; puis il mesura mille autres coudées; et il me fit passer au travers de ces eaux-là, et elles me venaient jusques aux reins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Puis il mesura mille autres coudées; mais ces eaux-là étaient déjà un torrent, que je ne pouvais passer à gué; car ces eaux-là s’étaient enflées, c’étaient des eaux qu’il fallait passer à la nage, et un torrent que l’on ne pouvait passer à gué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Alors il me dit: fils d’homme, as-tu vu? puis il me fit aller plus outre, et me fit revenir vers le bord du torrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Quand j’y fus revenu, voilà un fort grand nombre d’arbres sur les deux bords du torrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Puis il me dit: ces eaux-ci se vont rendre dans la Galilée Orientale, et elles descendront à la campagne, puis elles entreront dans la mer, et quand elles se seront rendues dans la mer, les eaux en deviendront saines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'Et il arrivera que tout animal vivant, qui se traînera partout où entrera chacun des deux torrents, vivra, et il y aura une fort grande quantité de poissons. Lors donc que ces eaux seront entrées là, les autres en seront rendues saines, et tout vivra là où ce torrent sera entré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Pareillement il arrivera que les pêcheurs se tiendront le long de cette mer, depuis Henguédi jusques à Henhéglajim; tellement que tout ce circuit sera plein de filets tous étendus pour prendre du poisson, et le poisson qu’on y pêchera sera en fort grand nombre, chacun selon son espèce, comme le poisson qu’on pêche dans la grande mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Ses marais et ses fosses ont été assignées pour y faire le sel, à cause qu’elles ne seront point rendues saines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Et auprès de ce torrent, et sur ses deux bords il croîtra des arbres fruitiers de toutes sortes, dont le feuillage ne flétrira point, et où l’on trouvera toujours du fruit; dans tous leurs mois ils produiront des fruits hâtifs, parce que les eaux de ce torrent sortent du Sanctuaire, et à cause de cela leur fruit sera bon à manger, et leur feuillage servira de remède.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Ainsi a dit le Seigneur l’Eternel: ce sont ici les frontières du pays dont vous vous rendrez possesseurs en titre d’héritage, selon les douze Tribus d’Israël; Joseph en aura deux portions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Or vous l’hériterez l’un comme l’autre, le pays touchant lequel j’ai levé ma main de le donner à vos pères; et ce pays-là vous écherra en héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'C’est donc ici la frontière du pays, du côté du Septentrion, vers la grande mer, savoir ce qui est du chemin d’Héthlon, au quartier par où l’on vient à Tsédad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Où sont Hamath, la contrée tirant vers Béroth, et Sibrajim, qui est entre la frontière de Damas, et entre la frontière de Hamath, et les bourgs d’entre-deux, qui sont vers la frontière de Havran.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'La frontière donc prise de la mer sera Hatsar-henan; la frontière de Damas, et le Septentrion qui regarde proprement vers le Septentrion, savoir, la frontière de Hamath, et le canton du Septentrion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Mais vous mesurerez le côté de l’Orient depuis ce qui est entre Havran, Damas, Galaad, et le pays d’Israël qui est delà le Jourdain, et depuis la frontière qui est vers la mer Orientale; et ainsi vous mesurerez le canton qui regarde proprement vers l’Orient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Puis vous mesurerez le côté du Midi qui regarde proprement vers le vent d’Autan, depuis Tamar jusques aux eaux des débats de Kadès, le long du torrent jusques à la grande mer; ainsi vous mesurerez le canton qui regarde proprement vers le vent d’Autan, tirant vers le Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Or le côté de l’Occident sera la grande mer, depuis la frontière du Midi jusques à l’endroit de l’entrée de Hamath, ce sera là le côté de l’Occident.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Après cela vous vous partagerez ce pays-là selon les Tribus d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'A condition toutefois que vous ferez que ce pays-là écherra en héritage à vous et aux étrangers qui habitent parmi vous, lesquels auront engendré des enfants parmi vous, et ils vous seront comme celui qui est né au pays entre les enfants d’Israël, tellement qu’ils viendront avec vous en partage de l’héritage parmi les Tribus d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'Et il arrivera que vous assignerez à l’étranger son héritage dans la Tribu en laquelle il demeurera, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Ce sont ici les noms des Tribus; depuis le bout du côté qui regarde vers le Septentrion, le long de la contrée du chemin de Hethlon, du quartier par lequel on entre en Hamath, jusques à Hatsar-henan, qui est la frontière de Damas, du côté qui regarde vers le Septentrion, le long de la contrée de Hamath, tellement que ce bout ait le canton de l’Orient et celui de l’Occident, il y aura une portion pour Dan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Et tout joignant les confins de Dan, depuis le canton de l’Orient, jusqu’au canton qui regarde vers l’Occident, il y aura une autre portion pour Aser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Et tout joignant les confins d’Aser, encore depuis le canton qui regarde vers l’Orient, jusqu’au canton qui regarde vers l’Occident, il y aura une autre portion pour Nephthali.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Et tout joignant les confins de Nephthali, depuis le canton qui regarde vers l’Orient, jusqu’au canton qui regarde vers l’Occident, il y aura une autre portion pour Manassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Et tout joignant les confins de Manassé, depuis le canton qui regarde vers l’Occident, jusqu’au canton qui regarde vers l’Orient, il y aura une autre portion pour Ephraïm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Et tout joignant les confins d’Ephraïm, encore depuis le canton de l’Orient, jusqu’au canton qui regarde vers l’Occident, il y aura une autre portion pour Ruben.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Et tout joignant les confins de Ruben, depuis le canton de l’Orient, jusqu’au canton qui regarde vers l’Occident, il y aura une autre portion pour Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Et tout le long des confins de Juda, depuis le canton de l’Orient, jusqu’au canton qui regarde vers l’Occident, il y aura une portion que vous lèverez sur toute la masse du pays comme en offrande élevée, laquelle aura vingt-cinq mille cannes de largeur; et de longueur autant que l’une des autres portions, depuis le canton qui regarde vers l’Orient, jusqu’au canton qui regarde vers l’Occident; tellement que le Sanctuaire sera au milieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'La portion que vous lèverez pour l’Eternel, la lui présentant comme en offrande élevée, aura vingt-cinq mille cannes de longueur, et dix mille de largeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Et cette portion sainte sera pour ceux-ci, savoir pour les Sacrificateurs, et elle aura le long du côté qui regarde vers le Septentrion vingt-cinq mille cannes de longueur, et le long du côté qui regarde vers l’Occident dix mille de largeur; et pareillement le long du côté qui regarde vers l’Orient dix mille, puis le long du côté qui regarde vers le Midi vingt-cinq mille cannes de longueur; et le Sanctuaire de l’Eternel sera au milieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Elle sera pour les Sacrificateurs, et quiconque aura été sanctifié d’entre les fils de Tsadok, qui ont fait ce que j’avais ordonné qu’on fît, et qui ne se sont point égarés quand les enfants d’Israël se sont égarés, comme se sont égarés les autres Lévites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Ceux-là auront une portion ainsi levée sur l’autre qui aura été auparavant levée sur toute la masse du pays, comme étant une chose très-sainte, et elle sera vers les confins de la portion des Lévites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Car la portion des Lévites sera tout joignant les confins de ce qui appartiendra aux Sacrificateurs, et elle aura vingt-cinq mille cannes de longueur, et dix mille de largeur; tellement que toute la longueur sera de vingt-cinq mille cannes, et la largeur de dix mille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Or ils n’en vendront rien, et aucun d’entre eux n’en échangera rien, ni ne transportera les prémices du pays; parce que c’est une chose sanctifiée à l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Mais les cinq mille cannes qui restent dans la largeur sur le devant des vingt-cinq mille cannes de longueur, est un lieu profane pour la ville, tant pour son assiette que pour ses faubourgs; et la ville sera au milieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Et ce sont ici les mesures qu’aura l’assiette de la ville, du côté du Septentrion, quatre mille cinq cents cannes, et du côté du Midi, quatre mille cinq cents, et du côté de l’Orient, quatre mille cinq cents, et du côté tirant vers l’Occident, quatre mille cinq cents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Puis il y aura des faubourgs pour la ville, vers le Septentrion, de deux cent cinquante cannes; et vers le Midi, de deux cent cinquante, et vers l’Orient, de deux cent cinquante; et vers l’Occident, de deux cent cinquante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Quant à ce qui sera de reste en la longueur, et qui sera tout joignant la portion sanctitiée, et qui aura dix mille cannes du côté tirant vers l’Orient, et dix mille autres cannes du côlé tirant vers l’Occident, auquel côté il sera aussi tout joignant la portion sanctifiée, le revenu qu’on en tirera sera pour nourrir ceux qui feront le service qu’il faut dans la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'Or ceux qui feront le service qu’il faut dans la ville, étant pris de toutes les Tribus d’Israël, cultiveront ce pays-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Vous lèverez donc sur toute la masse du pays pour être une portion sainte, présentée à l’Eternel comme en offrande élevée, toute cette portion qui sera de vingt-cinq mille cannes, répondant à vingt-cinq mille autres cannes, le tout pris en carré, et en y comprenant la possession de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Puis ce qui restera sera pour le Prince, tant au delà de la portion sainte, présentée à l’Eternel comme en offrande élevée, qu’au deçà de la possession de la ville, le long des vingt-cinq mille cannes de la portion qui aura été levée sur toute la masse, jusques aux frontières qui regardent vers l’Orient, et ce qui sera tendant vers l’Occident, le long des autres vingt-cinq mille cannes, jusques aux frontières qui regardent vers l’Occident, tout joignant les autres portions, sera pour le Prince; et ainsi la portion sainte, présentée à l’Eternel comme en offrande élevée, et le Sanctuaire de la maison seront au milieu de tout le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Ce qui sera donc pour le Prince sera dans les entre-deux depuis la possession des Lévites, et depuis la possession de la ville; ce qui sera entre ces possessions-là, et les confins de Juda, et les confins de Benjamin, sera pour le Prince.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Or ce qui sera de reste sera pour les autres Tribus. Depuis le canton de ce qui regarde vers l’Orient, jusques au canton de ce qui regarde vers l’Occident, il y aura une portion pour Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Puis tout joignant les confins de Benjamin depuis le canton de ce qui regarde vers l’Orient, jusques au canton de ce qui regarde vers l’Occident, il y aura une autre portion pour Siméon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Puis tout joignant les confins de Siméon, depuis le canton de ce qui regarde vers l’Orient, jusques au canton de ce qui regarde vers l’Occident, il y aura une autre portion pour Issacar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Puis tout joignant les confins d’Issacar, depuis le canton de ce qui regarde vers l’Orient, jusques au canton de ce qui regarde vers l’Occident, il y aura une autre portion pour Zabulon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Puis tout joignant les confins de Zabulon, depuis le canton de ce qui regarde vers l’Orient, jusques au canton de ce qui regarde vers l’Occident, il y aura une autre portion pour Gad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Or ce qui appartient au côté du Midi, qui regarde proprement le vent d’Autan, est sur la frontière de Gad; et cette frontière sera depuis Tamar jusques aux eaux du débat de Kadès, le long du torrent jusques à la grande mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'C’est là le pays que vous partagerez par sort en héritage aux Tribus d’Israël, et ce sont là leurs portions, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Et ce sont ici les sorties de la ville. Du côté du Septentrion il y aura quatre mille cinq cents mesures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'Puis quant aux portes de la ville, qui seront nommées des noms des Tribus d’Israël, il y aura trois portes qui regarderont vers le Septentrion; une appelée la porte de Ruben; une appelée la porte de Juda, et une appelée la porte de Lévi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Au côté de ce qui regarde vers l’Orient, il y aura quatre mille cinq cents cannes, et trois portes; une appelée la porte de Joseph; une appelée la porte de Benjamin, et une appelée la porte de Dan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Et au côté de ce qui regarde vers le Midi il y aura quatre mille cinq cents mesures, et trois portes; une appelée la porte de Siméon; une appelée la porte d’Issacar; et une appelée la porte de Zabulon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Au côté de ce qui regarde vers l’Occident il y aura quatre mille cinq cents cannes, auxquelles il y aura trois portes; une appelée la porte de Gad; une appelée la porte d’Aser; et une appelée la porte de Nephthali.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Ainsi le circuit de la ville sera de dix-huit mille cannes; et le nom de la ville depuis ce jour-là sera: L’ETERNEL EST LA.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'La troisième année de Jéhojakim Roi de Juda, Nébucadnetsar Roi de Babylone vint contre Jérusalem, et l’assiégea.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Et le Seigneur livra en sa main Jéhojakim Roi de Juda, et une partie des vaisseaux de la maison de Dieu, lesquels Nébucadnetsar fit emporter au pays de Sinhar en la maison de son Dieu; et il mit ces vaisseaux en la Trésorerie de son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Et le Roi dit à Aspenaz, Capitaine de ses Eunuques, qu’il amenât d’entre les enfants d’Israël, et de la race Royale et des principaux Seigneurs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'Quelques jeunes enfants, en qui il n’y eût aucun défaut, beaux de visage, instruits en toute sagesse, connaissant les sciences, qui eussent beaucoup d’intelligence, et en qui il y eût de la force, pour se tenir au palais du Roi; et qu’on leur enseignât les lettres et la langue des Caldéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Et le Roi leur assigna pour provision chaque jour une portion de la viande Royale, et du vin dont il buvait; afin qu’on les nourrît ainsi trois ans, et qu’ensuite quelques-uns d’entre eux servissent en la présence du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Entre ceux-là il y eut des enfants de Juda, Daniel, Hanania, Misaël et Hazaria.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Mais le Capitaine des Eunuques leur mit d’autres noms; car il donna à Daniel le nom de Beltesatsar; à Hanania, celui de Sadrac; à Misaël, celui de Mésac; et à Hazaria, celui d’Habed-nego.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Or Daniel se proposa dans son coeur de ne se point souiller par la portion de la viande du Roi, ni par le vin dont le Roi buvait; c’est pourquoi il supplia le Chef des Eunuques afin qu’il ne l’engageât point à se souiller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Et Dieu fit que le Chef des Eunuques eut de la bonté pour Daniel, et qu’il eut pitié de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Toutefois le Capitaine des Eunuques dit à Daniel: Je crains le Roi mon maître, qui a ordonné votre manger et votre boire; pourquoi verrait-il vos visages plus défaits que ceux des autres jeunes enfants vos semblables, et rendriez-vous ma tête coupable envers le Roi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Mais Daniel dit à Meltsar, qui avait été ordonné par le Capitaine des Eunuques sur Daniel, Hanania, Misaël, et Hazaria;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Eprouve, je te prie, tes serviteurs pendant dix jours, et qu’on nous donne des légumes à manger, et de l’eau à boire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Et après cela regarde nos visages, et les visages des jeunes enfants qui mangent la portion de la viande Royale; puis tu feras à tes serviteurs selon ce que tu auras vu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Et il leur accorda cela, et les éprouva pendant dix jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Mais au bout des dix jours leurs visages parurent en meilleur état, et ils avaient plus d’embonpoint que tous les jeunes enfants qui mangeaient la portion de la viande Royale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Ainsi Meltsar prenait la portion de leur viande, et le vin qu’ils devaient boire, et leur donnait des légumes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Et Dieu donna à ces quatre jeunes enfants de la science et de l’intelligence dans toutes les lettres, et de la sagesse; et Daniel s’entendait en toute vision, et dans les songes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Et au bout des jours que le Roi avait dit qu’on les amenât, le Capitaine des Eunuques les amena devant Nébucadnetsar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Et le Roi s’entretint avec eux; mais entre eux tous il ne s’en trouva point de tels que Daniel, Hanania, Misaël, et Hazaria; et ils se tinrent en la présence du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Et dans toute question savante et qui demandait de la pénétration, sur quoi le Roi les interrogeait il trouva dix fois plus de science en eux que dans tous les tireurs d’horoscope et les astrologues qui étaient en tout son Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Et Daniel y fut jusqu’à la première année du Roi Cyrus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Or en la seconde année du règne de Nébucadnetsar, Nébucadnetsar songea des songes, et son esprit fut ému, et son sommeil finit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Alors le Roi commanda qu’on appelât les magiciens, et les astrologues, et les enchanteurs, et les Caldéens, pour expliquer au Roi ses songes; ils vinrent donc et se présentèrent devant le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Et le Roi leur dit: J’ai songé un songe, et mon esprit s’est agité, tâchant de savoir le songe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Et les Caldéens répondirent au Roi en langue Syriaque: Roi, vis éternellement! dis le songe à tes serviteurs, et nous en donnerons l’interprétation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Mais le Roi répondit, et dit aux Caldéens: La chose m’est échappée; si vous ne me faites connaître le songe et son interprétation, vous serez mis en pièces, et vos maisons seront réduites en voirie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Mais si vous me manifestez le songe et son interprétation; vous recevrez de moi des dons, des largesses, et un grand honneur; quoi qu’il en soit, manifestez-moi le songe et son interprétation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Ils répondirent pour la seconde fois, et dirent: Que le Roi dise le songe à ses serviteurs, et nous en donnerons l’interprétation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Le Roi répondit, et dit: Je connais maintenant que vous ne cherchez qu’à gagner du temps, parce que vous voyez que la chose m’est échappée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Mais si vous ne me faites pas connaître le songe, il y a une même sentence contre vous; car vous vous êtes préparés pour dire devant moi quelque parole fausse et perverse, en attendant que le temps soit changé. Quoi qu’il en soit, dites-moi le songe, et je saurai que vous m’en pouvez donner l’interprétation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Les Caldéens répondirent au Roi, et dirent: Il n’y a aucun homme sur la terre qui puisse exécuter ce que le Roi demande; et aussi il n’y a ni Roi, ni Seigneur, ni Gouverneur qui ait jamais demandé une telle chose à quelque magicien, astrologue, ou Caldéen que ce soit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Car la chose que le Roi demande est extrêmement difficile et il n’y a que les dieux, lesquels n’ont aucune fréquentation avec la chair, qui la puissent déclarer au Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'C’est pourquoi le Roi commanda avec grande colère et indignation qu’on mît à mort tous les sages de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'La sentence donc fut publiée, et on tuait les sages; et on cherchait Daniel et ses compagnons, pour les tuer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Alors Daniel détourna l’exécution du conseil, et de l’arrêt donné à Arioc, prévôt de l’hôtel du Roi, qui était sorti pour tuer les sages de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Et il demanda et dit à Arioc, commissaire du Roi: Pourquoi la sentence est-elle si pressante de par le Roi? Et Arioc déclara le fait à Daniel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Et Daniel entra, et pria le Roi de lui donner du temps, et qu’il donnerait l’interprétation au Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Alors Daniel alla en sa maison, et déclara l’affaire à Hanania, à Misaël, et à Hazaria, ses compagnons;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'Qui implorèrent la miséricorde du Dieu des cieux sur ce secret, afin qu’on ne mît point à mort Daniel et ses compagnons, avec le reste des sages de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Et le secret fut révélé à Daniel dans une vision de nuit, et là- dessus Daniel bénit le Dieu des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Daniel donc prenant la parole, dit: Béni soit le nom de Dieu, depuis un siècle jusqu’à l’autre; car à lui est la sagesse et la force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Et c’est lui qui change les temps et les saisons, qui ôte les Rois, et qui établit les Rois, qui donne la sagesse aux sages, et la connaissance à ceux qui ont de l’intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'C’est lui qui découvre les choses profondes et cachées, il connaît les choses qui sont dans les ténèbres, et la lumière demeure avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Ô Dieu de nos pères! je te célèbre et te loue de ce que tu m’as donné de la sagesse et de la force, et de ce que tu m’as maintenant fait savoir ce que nous t’avons demandé, en nous ayant fait connaître la parole du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'C’est pourquoi Daniel alla vers Arioc, que le Roi avait commis pour faire mourir les sages de Babylone, et étant arrivé, il lui parla ainsi: Ne fais point mettre à mort les sages de Babylone, mais fais-moi entrer devant le Roi, et je donnerai au Roi l’interprétation qu’il souhaite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Alors Arioc fit promptement entrer Daniel devant le Roi, et lui parla ainsi: J’ai trouvé un homme d’entre ceux qui ont été emmenés captifs de Juda qui donnera au Roi l’interprétation de son songe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Et le Roi prenant la parole, dit à Daniel, qui avait nom Beltesatsar: Me pourras-tu faire connaître le songe que j’ai vu, et son interprétation?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Et Daniel répondit en la présence du Roi, et dit: Le secret que le Roi demande est tel, que ni les astrologues, ni les magiciens, ni les devins, ne le peuvent point découvrir au Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Mais il y a un Dieu aux cieux qui révèle les secrets, et qui a fait connaître au Roi Nébucadnetsar ce qui doit arriver aux derniers temps. Ton songe, et les visions de ta tête que tu as eues sur ton lit, sont telles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Tes pensées, ô Roi! te sont montées dans ton lit, touchant ce qui arriverait ci-après, et celui qui révèle les secrets t’a déclaré ce qui doit arriver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Et ce secret m’a été révélé, non point par quelque sagesse qui soit en moi, plus qu’en aucun des vivants, mais afin de donner au Roi l’interprétation de son songe, et afin que tu connaisses les pensées de ton coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Tu contemplais, ô Roi! et voici une grande statue, et cette grande statue, dont la splendeur était excellente, était debout devant toi, et elle était terrible à voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'La tête de cette statue était d’un or très-fin, sa poitrine et ses bras étaient d’argent; son ventre et ses hanches étaient d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'Ses jambes étaient de fer, et ses pieds étaient en partie de fer, et en partie de terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Tu contemplais cela jusqu’à ce qu’une pierre fût coupée sans main, laquelle frappa la statue en ses pieds de fer et de terre, et les brisa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Alors furent brisés ensemble le fer, la terre, l’airain, l’argent et l’or, et ils devinrent comme la paille de l’aire d’Eté, que le vent transporte çà et là; et il ne fut plus trouvé aucun lieu pour eux, mais cette pierre qui avait frappé la statue devint une grande montagne, et remplit toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'C’est là le songe; nous dirons maintenant son interprétation en la présence du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Toi ô Roi! qui es le Roi des Rois; parce que le Dieu des cieux t’a donné le Royaume, la puissance, la force et la gloire,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'Et qu’en quelque lieu qu’habitent les enfants des hommes, les bêtes des champs, et les oiseaux des cieux, il les a donnés en ta main, et t’a fait dominer sur eux tous, tu es la tête d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Mais après toi il s’élèvera un autre Royaume, moindre que le tien, et ensuite un autre troisième Royaume qui sera d’airain, lequel dominera sur toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Puis il y aura un quatrième Royaume, fort comme du fer, parce que le fer brise, et met en pièces toutes choses; et comme le fer met en pièces toutes ces choses, ainsi il brisera et mettra tout en pièces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Et quant à ce que tu as vu que les pieds et les orteils étaient en partie de terre de potier, et en partie de fer, c’est que le Royaume sera divisé, et il y aura en lui de la force du fer, selon que tu as vu le fer mêlé avec la terre de potier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Et ce que les orteils des pieds étaient en partie de fer, et en partie de terre, c’est que ce Royaume sera en partie fort, et en partie frêle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Mais ce que tu as vu le fer mêlé avec la terre de potier, c’est qu’ils se mêleront par semence humaine, mais ils ne se joindront point l’un avec l’autre, ainsi que le fer ne peut point se mêler avec la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Et au temps de ces Rois le Dieu des cieux suscitera un Royaume qui ne sera jamais dissipé, et ce Royaume ne sera point laissé à un autre peuple, mais il brisera et consumera tous ces Royaumes, et il sera établi éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Selon que tu as vu que de la montagne une pierre a été coupée sans main, et qu’elle a brisé le fer, l’airain, la terre, l’argent, et l’or. Le grand Dieu a fait connaître au Roi ce qui arrivera ci- après; or le songe est véritable, et son interprétation est certaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Alors le Roi Nébucadnetsar tomba sur sa face, et se prosterna devant Daniel, et dit qu’on lui donnât de quoi faire des oblations et des offrandes de bonne odeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Aussi le Roi parla à Daniel, et lui dit: Certainement votre Dieu est le Dieu des dieux, et le Seigneur des Rois, et c’est lui qui révèle les secrets, puisque tu as pu déclarer ce secret.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Alors le Roi éleva en honneur Daniel, et lui donna beaucoup de grands présents; il l’établit Gouverneur sur toute la Province de Babylone, et le fit plus grand Seigneur que tous ceux qui avaient la surintendance sur tous les sages de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Et Daniel fit une requête au Roi; et le roi établit sur les affaires de la Province de Babylone, Sadrac, Mésac, et Habed-négo, mais Daniel était à la porte du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Le Roi Nébucadnetsar fit une statue d’or, dont la hauteur était de soixante coudées, et la largeur de six coudées; et il la dressa dans la campagne de Dura, en la Province de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Puis le Roi Nébucadnetsar envoya pour assembler les Satrapes, les Lieutenants, les Ducs, les Baillifs, les Receveurs, les Conseillers, les Prévôts, et tous les Gouverneurs des Provinces, afin qu’ils vinssent à la dédicace de la statue que le Roi Nébucadnetsar avait dressée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Ainsi furent assemblés les Satrapes, les Lieutenants, les Ducs, les Baillifs, les Receveurs, les Conseillers, les Prévôts, et tous les Gouverneurs des Provinces, pour la dédicace de la statue que le Roi Nébucadnetsar avait dressée; et ils se tenaient debout devant la statue que le Roi Nébucadnetsar avait dressée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Alors un héraut cria à haute voix, en disant: On vous fait savoir, ô peuples, nations, et Langues!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Qu’à l’heure que vous entendrez le son du cor, du clairon, de la harpe, de la saquebute, du psaltérion, de la symphonie, et de toute sorte de musique, vous ayez à vous jeter à terre, et à vous prosterner devant la statue d’or que le Roi Nébucadnetsar a dressée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Et quiconque ne se jettera pas à terre et ne se prosternera point, sera jeté à cette même heure-là au milieu de la fournaise de feu ardent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'C’est pourquoi au même instant et sitôt que tous les peuples entendirent le son du cor, du clairon, de la harpe, de la saquebute, du psaltérion, et de toute sorte de musique, tous les peuples, les nations, et les Langues, se jetèrent à terre, et se prosternèrent devant la statue d’or que le Roi avait dressée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Sur quoi certains Caldéens s’approchèrent en même temps, et accusèrent les Juifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Et ils parlèrent et dirent au Roi Nébucadnetsar: Roi, vis éternellement!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Toi Roi, tu as fait un Edit, que tout homme qui aurait ouï le son du cor, du clairon, de la harpe, de la saquebute, du psaltérion, de la symphonie, et de toute sorte de musique, se jetât à terre, et se prosternât devant la statue d’or;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'Et que quiconque ne se jetterait pas à terre, et ne se prosternerait point, serait jeté au milieu de la fournaise de feu ardent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Or il y a de certains Juifs que tu as établis sur les affaires de la Province de Babylone, savoir Sadrac, Mésac, et Habed-négo, et ces hommes-là, ô roi! n’ont point tenu compte de toi; ils ne servent point tes dieux, et ne se prosternent point devant la statue d’or que tu as dressée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Alors le Roi Nébucadnetsar saisi de colère et de fureur, commanda qu’on amenât Sadrac, Mésac, et Habed-négo, et ces hommes-là furent amenés devant le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Et le Roi Nébucadnetsar prenant la parole leur dit: Est-il vrai, Sadrac, Mésac, et Habed-négo, que vous ne servez point mes dieux, et que vous ne vous prosternez point devant la statue d’or que j’ai dressée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Maintenant n’êtes-vous pas prêts, au temps que vous entendrez le son du cor, du clairon, de la harpe, de la saquebute, du psaltérion, de la symphonie, et de toute sorte de musique, de vous jeter à terre, et de vous prosterner devant la statue que j’ai faite? Que si vous ne vous prosternez pas, vous serez jetés à cette même heure au milieu de la fournaise de feu ardent. Et qui est le Dieu qui vous délivrera de mes mains?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Sadrac, Mésac et Habed-négo répondirent, et dirent au Roi Nébucadnetsar: Il n’est pas besoin, que nous te répondions sur ce sujet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Voici, notre Dieu, que nous servons, nous peut délivrer de la fournaise de feu ardent, et il nous délivrera de ta main, ô Roi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Sinon, sache, ô Roi! que nous ne servirons point tes dieux, et que nous ne nous prosternerons point devant la statue d’or que tu as dressée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Alors Nébucadnetsar fut rempli de fureur, et l’air de son visage fut changé contre Sadrac, Mésac, et Habed-négo; et prenant la parole, il commanda qu’on échauffât la fournaise sept fois autant qu’elle avait accoutumé d’être échauffée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Puis il commanda aux hommes les plus forts et les plus vaillants qui fussent dans son armée, de lier Sadrac, Mésac, et Habed-négo, pour les jeter en la fournaise de feu ardent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Et en même temps ces personnages-là furent liés avec leurs caleçons, leurs chaussures, leurs tiares, et leurs vêtements, et furent jetés au milieu de la fournaise de feu ardent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Et parce que la parole du Roi était pressante, et que la fournaise était extraordinairement embrasée, la flamme du feu tua les hommes qui y avaient jeté Sadrac, Mésac, et Habed-négo.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Et ces trois personnages, Sadrac, Mésac, et Habed-négo, tombèrent tous liés au milieu de la fournaise de feu ardent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Alors le Roi Nébucadnetsar fut tout étonné, et se leva promptement, et prenant la parole, il dit à ses Conseillers: N’avons-nous pas jeté trois hommes au milieu du feu tout liés? Et ils répondirent, et dirent au Roi: Il est vrai, ô Roi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Il répondit, et dit: Voici, je vois quatre hommes déliés qui marchent au milieu du feu, et il n’y a en eux aucun dommage, et la forme du quatrième est semblable à un fils de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Alors Nébucadnetsar s’approcha vers la porte de la fournaise de feu ardent; et prenant la parole, il dit: Sadrac, Mésac, et Habed- négo, serviteurs du Dieu souverain, sortez, et venez. Alors Sadrac, Mésac, et Habed-négo sortirent du milieu du feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Puis les Satrapes, les Lieutenants, les Gouverneurs, et les Conseillers du Roi, s’assemblèrent pour contempler ces personnages- là, et le feu n’avait eu aucune puissance sur leurs corps, et un cheveu de leur tête n’était point grillé, et leurs caleçons n’étaient en rien changés, et l’odeur du feu n’avait point passé sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Alors Nébucadnetsar prit la parole, et dit: Béni soit le Dieu de Sadrac, Mésac, et Habed-négo qui a envoyé son Ange, et a délivré ses serviteurs qui ont eu espérance en lui, et qui ont violé la parole du Roi, et ont abandonné leurs corps, pour ne servir aucun dieu que leur Dieu, et ne se prosterner point devant aucun autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'De par moi donc est fait un Edit, que tout homme de quelque nation et Langue qu’il soit, qui dira quelque chose de mal convenable contre le Dieu de Sadrac, Mésac, et Habed-négo, soit mis en pièces, et que sa maison soit réduite en voirie, parce qu’il n’y a aucun autre Dieu qui puisse délivrer comme lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Alors le Roi avança Sadrac, Mésac, et Habed-négo dans la Province de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Le Roi Nébucadnetsar, à tous peuples, nations, et Langues qui habitent en toute la terre: Que votre paix soit multipliée!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Il m’a semblé bon de vous déclarer les signes et les merveilles que le Dieu souverain a faites envers moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Ô! que ses signes sont grands, et ses merveilles pleines de force! Son règne est un règne éternel, et sa puissance est de génération en génération.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Moi Nébucadnetsar j’étais tranquille dans ma maison, et dans un état florissant au milieu de mon palais;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Lorsque je vis un songe qui m’épouvanta; et les pensées que j’eus dans mon lit, et les visions de ma tête me troublèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Et de par moi fut fait un Edit, qu’on fît venir devant moi tous les sages de Babylone, afin qu’ils me déclarassent l’interprétation du songe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Alors vinrent les magiciens, les astrologues, les Caldéens, et les devins, et je récitai le songe devant eux, mais ils ne m’en purent point donner l’interprétation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Mais à la fin Daniel, qui a nom Beltesatsar, selon le nom de mon Dieu, et auquel est l’Esprit des dieux saints, entra devant moi, et je récitai le songe devant lui, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Beltesatsar Chef des Mages, comme je connais que l’Esprit des dieux saints est en toi, et que nul secret ne t’est difficile, écoute les visions de mon songe que j’ai vues, et dis son interprétation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Les visions donc de ma tête sur mon lit étaient telles. Voici, je voyais un arbre au milieu de la terre, la hauteur duquel était fort grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Cet arbre était devenu grand et fort, son sommet touchait les cieux, et il se faisait voir jusqu’au bout de toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Son branchage était beau, et son fruit abondant, et il y avait de quoi manger pour tous; les bêtes des champs se mettaient à l’ombre au-dessous de lui, et les oiseaux des cieux habitaient dans ses branches, et toute chair en était nourrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Je regardais dans les visions de ma tête sur mon lit, et voici, un Veillant et Saint descendit des cieux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Il cria à haute voix, et parla ainsi: Coupez l’arbre, et l’ébranchez; jetez çà et là son branchage, et répandez son fruit; que les bêtes s’écartent de dessous lui, et les oiseaux d’entre ses branches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Toutefois laissez le tronc de ses racines dans la terre, et l’ayant lié avec des chaînes de fer et d’airain, qu’il soit parmi l’herbe des champs, qu’il soit arrosé de la rosée des cieux, et qu’il ait sa portion avec les bêtes en l’herbe de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Que son coeur soit changé pour n’être plus un coeur d’homme, et qu’il lui soit donné un coeur de bête; et que sept temps passent sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'La chose est par le décret des Veillants, et la demande avec parole des Saints; afin que les vivants connaissent que le Souverain domine sur le Royaume des hommes, et qu’il le donne à qui il lui plaît, et y établit le plus abject des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Moi Nébucadnetsar Roi, j’ai vu ce songe, toi donc Beltesatsar, dis son interprétation; car aucun des sages de mon royaume ne m’en peut déclarer l’interprétation, mais toi, tu le peux; parce que l’Esprit des dieux saints est en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Alors Daniel, dont le nom était Beltesatsar, demeura tout étonné environ une heure, et ses pensées le troublaient; et le Roi lui parla, et dit: Beltesatsar, que le songe ni son interprétation ne te trouble point; et Beltesatsar répondit, et dit: Mon Seigneur, que le songe arrive à ceux qui t’ont en haine, et son interprétation à tes ennemis!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'L’arbre que tu as vu, qui était devenu grand et fort, dont le sommet touchait les cieux, et qui se faisait voir par toute la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'Et dont le branchage était beau, et le fruit abondant, et auquel il y avait de quoi manger pour tous, sous lequel demeuraient les bêtes des champs, et aux branches duquel habitaient les oiseaux des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'C’est toi-même, ô Roi! qui es devenu grand et fort, tellement que ta grandeur s’est accrue, et est parvenue jusqu’aux cieux, et ta domination jusqu’au bout de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Mais, quant à ce que le Roi a vu le Veillant et le Saint qui descendait des cieux, et qui disait: Coupez l’arbre, et l’ébranchez, toutefois laissez le tronc de ses racines dans la terre, et qu’il soit lié avec des liens de fer et d’airain parmi l’herbe des champs, qu’il soit arrosé de la rosée des cieux, et qu’il ait sa portion avec les bêtes des champs, jusqu’à ce que sept temps soient passés sur lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'C’en est ici l’interprétation, ô Roi! et c’est ici le décret du Souverain, lequel est venu sur le Roi mon Seigneur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'C’est qu’on te chassera d’entre les hommes, ton habitation sera avec les bêtes des champs, et on te paîtra d’herbe comme les boeufs, et tu seras arrosé de la rosée des cieux; et sept temps passeront sur toi, jusques à ce que tu connaisses que le Souverain domine sur le Royaume des hommes, et qu’il le donne à qui il lui plaît.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Mais, quant à ce qui a été dit qu’on laissât le tronc des racines de cet arbre-là, c’est que ton Royaume te sera rendu, dès que tu auras connu que les Cieux dominent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'C’est pourquoi; ô Roi! que mon conseil te soit agréable, et rachète tes péchés par la justice, et tes iniquités en faisant miséricorde aux pauvres; voici, ce sera une prolongation à ta prospérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Toutes ces choses arrivèrent au Roi Nébucadnetsar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Au bout de douze mois, il se promenait dans le palais Royal de Babylone;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'Et le Roi prenant la parole, dit: N’est-ce pas ici Babylone la grande, que j’ai bâtie pour être la demeure Royale par le pouvoir de ma force, et pour la gloire de ma magnificence?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'La parole était encore dans la bouche du Roi quand une voix vint des cieux, disant: Roi Nébucadnetsar, on t’annonce que ton Royaume te va être ôté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'Et on va te chasser d’entre les hommes, et ton habitation sera avec les bêtes des champs; on te paîtra d’herbe comme les boeufs, et sept temps passeront sur toi, jusques à ce que tu connaisses que le Souverain domine sur le Royaume des hommes, et qu’il le donne à qui il lui plaît.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'A cette même heure-là cette parole fut accomplie sur Nébucadnetsar, et il fut chassé d’entre les hommes, il mangea l’herbe comme les boeufs, et son corps fut arrosé de la rosée des cieux jusqu’à ce que son poil crût comme celui de l’aigle, et ses ongles comme ceux des oiseaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Mais à la fin de ces jours-là moi Nébucadnetsar je levai mes yeux vers les cieux; mon sens me revint, je bénis le Souverain, je louai et j’honorai celui qui vit éternellement, duquel la puissance est une puissance éternelle, et le règne de génération en génération.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'Et au prix duquel tous les habitants de la terre ne sont rien estimés; il fait ce qui lui plaît tant dans l’armée des cieux, que parmi les habitants de la terre; et il n’y a personne qui empêche sa main, et qui lui dise: Qu’as-tu fait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'En ce temps-là mon sens me revint, et je retournai à la gloire de mon Royaume, ma magnificence et ma splendeur me fut rendue, et mes conseillers et mes gentilshommes me redemandèrent, je fus rétabli dans mon Royaume, et ma gloire fut augmentée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'Maintenant donc moi Nébucadnetsar je loue, j’exalte, et je glorifie le Roi des cieux, duquel toutes les oeuvres sont véritables, ses voies justes, et qui peut abaisser ceux qui marchent avec orgueil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Le Roi Belsatsar fit un grand festin à mille de ses gentilshommes, et il buvait le vin devant ces mille courtisans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Et ayant un peu bu, il commanda qu’on apportât les vaisseaux d’or et d’argent que Nébucadnetsar son père avait tirés du Temple qui était à Jérusalem; afin que le Roi et ses gentilshommes, ses femmes et ses concubines y bussent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Alors furent apportés les vaisseaux d’or qu’on avait tirés du Temple de la maison de Dieu qui était à Jérusalem, et le Roi, et ses gentilshommes, ses femmes, et ses concubines y burent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Ils y burent donc du vin, et louèrent leurs dieux d’or, d’argent, d’airain, de fer, de bois et de pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Et à cette même heure-là sortirent de la muraille des doigts d’une main d’homme, qui écrivaient à l’endroit du chandelier, sur l’enduit de la muraille du palais royal; et le Roi voyait cette partie de main qui écrivait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Alors le visage du Roi fut changé, et ses pensées le troublèrent, et les jointures de ses reins se desserraient, et ses genoux heurtaient l’un contre l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Puis le Roi cria à haute voix qu’on amenât les astrologues, les Caldéens, et les devins; et le Roi parla et dit aux sages de Babylone: Quiconque lira cette écriture, et me déclarera son interprétation, sera vêtu d’écarlate, et il aura un collier d’or à son cou, et sera le troisième dans le Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Alors tous les sages du Roi entrèrent, mais ils ne purent point lire l’écriture, ni en donner au Roi l’interprétation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Dont le Roi Belsatsar fut fort troublé, et son visage en fut tout changé; ses gentilshommes aussi en furent épouvantés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Or la Reine entra dans la maison du festin, à cause de ce qui était arrivé au Roi et à ses gentilshommes; et la Reine parla, et dit: Roi, vis éternellement! que tes pensées ne te troublent point, et que ton visage ne se change point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Il y a dans ton Royaume un homme en qui est l’Esprit des dieux saints, et au temps de ton père l’on trouva en lui une lumière, une intelligence, et une sagesse telle qu’est la sagesse des dieux; et le Roi Nébucadnetsar ton père, ton père lui-même, ô Roi! l’établit chef des Mages, des astrologues, des Caldéens et des devins,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Parce qu’un plus grand esprit, et plus de connaissance et d’intelligence, pour interpréter les songes, et pour expliquer les questions obscures, et résoudre les choses difficiles, fut trouvé en lui, et cet homme c’est Daniel, à qui le Roi avait donné le nom de Beltesatsar. Maintenant donc que Daniel soit appelé, et il donnera l’interprétation, que tu souhaites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Alors Daniel fut amené devant le Roi, et le Roi prenant la parole dit à Daniel: Es-tu ce Daniel qui es d’entre ceux qui ont été emmenés captifs de Juda, que le Roi mon père a fait emmener de Juda?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Or j’ai ouï dire de toi que l’Esprit des dieux est en toi, et qu’il s’est trouvé en toi une lumière, une intelligence, et une sagesse singulière;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Et maintenant les sages et les astrologues ont été amenés devant moi, afin qu’ils lussent cette écriture, et m’en donnassent l’interprétation, mais ils n’en peuvent point donner l’interprétation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Mais j’ai ouï dire de toi que tu peux interpréter et résoudre les choses difficiles; maintenant donc si tu peux lire cette écriture, et m’en donner l’interprétation, tu seras vêtu d’écarlate, et tu porteras à ton cou un collier d’or, et tu seras le troisième dans le Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Alors Daniel répondit et dit devant le Roi: Que tes dons te demeurent, et donne tes présents à un autre; toutefois je lirai l’écriture au Roi, et je lui en donnerai l’interprétation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Ô Roi! le Dieu souverain avait donné à Nébucadnetsar ton père, le Royaume, la magnificence, la gloire et l’honneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'Et à cause de la grandeur qu’il lui avait donnée, tous les peuples, les nations, et les Langues tremblaient devant lui, et le redoutaient; car il faisait mourir ceux qu’il voulait, et sauvait la vie à ceux qu’il voulait; il élevait ceux qu’il voulait, et abaissait ceux qu’il voulait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Mais après que son coeur se fut élevé, et que son esprit se fut affermi dans son orgueil, il fut déposé de son siège royal, et on le dépouilla de sa gloire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Et il fut chassé d’entre les hommes, et son coeur fut rendu semblable à celui des bêtes, et sa demeure fut avec les ânes sauvages; on le paissait d’herbe comme les boeufs, et son corps fut arrosé de la rosée des cieux, jusqu’à ce qu’il connût que le Dieu souverain a puissance sur les Royaumes des hommes, et qu’il y établit ceux qu’il lui plaît.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Toi aussi Belsatsar son fils, tu n’as point humilié ton coeur, quoique tu susses toutes ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Mais tu t’es élevé contre le Seigneur des cieux, et on a apporté devant toi les vaisseaux de sa maison, et vous y avez bu du vin, toi et tes gentilshommes, tes femmes et tes concubines; et tu as loué les dieux d’argent, d’or, d’airain, de fer, de bois, et de pierre, qui ne voient, ni n’entendent, ni ne connaissent, et tu n’as point glorifié le Dieu dans la main duquel est ton souffle, et toutes tes voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Alors de sa part a été envoyée cette partie de main, et cette écriture a été écrite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Or c’est ici l’écriture qui a été écrite: MÉNÉ, MÉNÉ, THÉKEL, UPHARSIN.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Et c’est ici l’interprétation de ces paroles; MÉNÉ: Dieu a calculé ton règne, et y a mis la fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'THÉKEL: Tu as été pesé en la balance, et tu as été trouvé léger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'PÉRÈS: Ton Royaume a été divisé, et il a été donné aux Mèdes et aux Perses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Alors par le commandement de Belsatsar on vêtit Daniel d’écarlate, et on mit un collier d’or à son cou, et on publia de lui, qu’il serait le troisième dans le Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'En cette même nuit Belsatsar, Roi de Caldée, fut tué;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'Et Darius le Mède prit le Royaume, étant âgé d’environ soixante- deux ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Or il plut à Darius d’établir sur le Royaume six-vingts Satrapes pour être sur tout le Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Et au-dessus d’eux trois Gouverneurs, dont Daniel était l’un, auxquels ces Satrapes devaient rendre compte, afin que le Roi ne souffrît aucun préjudice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Mais Daniel excellait par-dessus les autres Gouverneurs et Satrapes, parce qu’il avait plus d’esprit qu’eux; et le Roi pensait à l’établir sur tout le Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Alors les Gouverneurs et les Satrapes cherchaient à trouver quelque occasion d’accuser Daniel touchant les affaires du Royaume; mais ils ne pouvaient trouver en lui aucune occasion ni aucun vice, parce qu’il était fidèle, et qu’il ne se trouvait en lui ni faute, ni vice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Ces hommes donc dirent: Nous ne trouverons point d’occasion d’accuser ce Daniel, si nous ne la trouvons dans ce qui regarde la Loi de son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Alors ces Gouverneurs et ces Satrapes s’assemblèrent vers le Roi, et lui parlèrent ainsi: Roi Darius, vis éternellement!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Tous les Gouverneurs de ton Royaume, les Lieutenants, les Satrapes, les Conseillers, et les Capitaines sont d’avis d’établir une ordonnance royale, et de faire un décret ferme, que quiconque fera aucune requête à quelque Dieu, ou à quelque homme que ce soit, d’ici à trente jours, sinon à toi, ô Roi! qu’il soit jeté dans la fosse des lions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Maintenant donc, ô Roi! établis ce décret, et fais en écrire des Lettres afin qu’on ne le change point, selon que la Loi des Mèdes et des Perses est irrévocable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'C’est pourquoi le Roi Darius écrivit la lettre et le décret.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Or quand Daniel eut appris que les Lettres en étaient écrites, il entra dans sa maison, et les fenêtres de sa chambre étant ouvertes du côté de Jérusalem, il se mettait trois fois le jour à genoux, et il priait et célébrait son Dieu, comme il avait fait auparavant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Alors ces hommes s’assemblèrent, et trouvèrent Daniel priant, et faisant requête à son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Ils s’approchèrent et dirent au Roi touchant le décret royal: N’as-tu pas écrit ce décret, que tout homme qui ferait requête à quelque Dieu, ou à quelque homme que ce fût, d’ici à trente jours, sinon à toi, ô Roi! serait jeté dans la fosse des lions? Et le Roi répondit, et dit: La chose est constante, selon la Loi des Mèdes et des Perses, laquelle est irrévocable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Alors ils répondirent, et dirent au Roi: Daniel, qui est un de ceux qui ont été emmenés captifs de Juda, n’a tenu compte de toi, ô Roi! ni du décret que tu as écrit; mais il prie, faisant requête trois fois le jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Ce que le Roi ayant entendu, il en eut en lui-même un grand déplaisir, et il prit à coeur Daniel pour le délivrer, et s’appliqua fortement jusqu’au soleil couchant à le délivrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Mais ces hommes-là s’assemblèrent vers le Roi, et lui dirent: Ô Roi! sache que la Loi des Mèdes et des Perses est, que tout décret et toute ordonnance que le Roi aura établie, ne se doit point changer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Alors le Roi commanda qu’on amenât Daniel, et qu’on le jetât dans la fosse des lions. Et le Roi prenant la parole dit à Daniel: Ton Dieu, lequel tu sers incessamment, sera celui qui te délivrera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Et on apporta une pierre, qui fut mise sur l’ouverture de la fosse, et le Roi la scella de son anneau, et de l’anneau de ses gentilshommes, afin que rien ne fût changé touchant Daniel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Après quoi le Roi s’en alla dans son palais, et passa la nuit sans souper, et on ne lui fit point venir les instruments de musique, il ne put même point dormir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Puis le Roi se leva de grand matin, lorsque le jour commençait à luire, et s’en alla en diligence vers la fosse des lions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Et comme il approchait de la fosse, il cria d’une voix triste: Daniel, et le Roi prenant la parole dit à Daniel: Daniel, serviteur du Dieu vivant, ton Dieu, lequel tu sers incessamment, aurait-il bien pu te délivrer des lions?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Alors Daniel dit au Roi: Ô Roi, vis éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Mon Dieu a envoyé son Ange, et a fermé la gueule des lions, tellement qu’ils ne m’ont fait aucun mal, parce que j’ai été trouvé innocent devant lui; et même à ton égard, ô Roi! je n’ai commis aucune faute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Alors le Roi eut en lui-même une grande joie, et il commanda qu’on tirât Daniel hors de la fosse. Ainsi Daniel fut tiré hors de la fosse, et on ne trouva en lui aucune blessure, parce qu’il avait cru en son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Et par le commandement du Roi, ces hommes qui avaient accusé Daniel, furent amenés, et jetés, eux, leurs enfants, et leurs femmes, dans la fosse des lions, et avant qu’ils fussent parvenus au bas de la fosse, les lions se saisirent d’eux, et leur brisèrent tous les os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Alors le Roi Darius écrivit des Lettres de telle teneur: A tous peuples, nations et Langues, qui habitent en toute la terre; que votre paix soit multipliée!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'De par moi est fait un Edit, que dans toute l’étendue de mon Royaume on ait de la crainte et de la frayeur pour le Dieu de Daniel, car c’est le Dieu vivant, et permanent à toujours; et son Royaume ne sera point dissipé, et sa domination sera jusqu’à la fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Il sauve et délivre, il fait des prodiges et des merveilles dans les cieux et sur la terre, et il a délivré Daniel de la puissance des lions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Ainsi Daniel prospéra au temps du règne de Darius, et au temps du règne de Cyrus de Perse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'La première année de Belsatsar, Roi de Babylone, Daniel vit un songe, et étant dans son lit il eut des visions en sa tête; puis il écrivit le songe, et il en dit le sommaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Daniel donc parla, et dit: Je regardais de nuit en ma vision, et voici, les quatre vents des cieux se levèrent avec impétuosité sur la grande mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Puis quatre grandes bêtes montèrent de la mer, différentes l’une de l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'La première était comme un lion, et elle avait des ailes d’aigle, et je la regardai jusqu’à ce que les plumes de ses ailes furent arrachées, et qu’elle se fut levée de terre, et dressée sur ses pieds comme un homme, et il lui fut donné un coeur d’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Et voici une autre bête qui fut la seconde semblable à un ours, laquelle se tenait sur un côté, et avait trois crocs dans la gueule entre ses dents; et on lui disait ainsi: Lève-toi, mange beaucoup de chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Après celle-là je regardai, et voici une autre bête, semblable à un léopard, qui avait sur son dos quatre ailes d’oiseau, et cette bête avait quatre têtes, et la domination lui fut donnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Après celle-là je regardais dans les visions de la nuit, et voici la quatrième bête, qui était épouvantable, affreuse, et très forte, elle avait de grandes dents de fer, elle mangeait, et brisait, et elle foulait à ses pieds ce qui restait, elle était différente de toutes les bêtes qui avaient été avant elle, et avait dix cornes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Je considérais ces cornes, et voici, une autre petite corne montait entre elles, et trois des premières cornes furent arrachées par elle; et voici, il y avait en cette corne des yeux semblables aux yeux d’un homme, et une bouche qui disait de grandes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Je regardais jusqu’à ce que les trônes furent roulés, et que l’Ancien des jours s’assit; son vêtement était blanc comme la neige, et les cheveux de sa tête étaient comme de la laine nette; son trône était des flammes de feu, et ses roues un feu ardent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Un fleuve de feu sortait et se répandait de devant lui; mille milliers le servaient, et dix mille millions assistaient devant lui; le jugement se tint, et les livres furent ouverts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Et je regardais à cause de la voix des grandes paroles que cette corne proférait; je regardai donc jusqu’à ce que la bête fut tuée, et que son corps fut détruit et donné pour être brûlé au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'La domination fut aussi ôtée aux autres bêtes, quoiqu’une longue vie leur eût été donnée jusqu’à un temps et un temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Je regardais encore dans les visions de la nuit, et voici, comme le Fils de l’homme, qui venait avec les nuées des cieux, et il vint jusqu’à l’Ancien des jours, et se tint devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Et il lui donna la seigneurie, et l’honneur, et le règne; et tous les peuples, les nations, et les Langues le serviront, sa domination est une domination éternelle qui ne passera point, et son règne ne sera point dissipé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Alors l’esprit me défaillit dans mon corps, de moi Daniel, et les visions de ma tête me troublèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Je m’approchai de l’un des assistants, et lui demandai la vérité de toutes ces choses; et il me parla, et me donna l’interprétation de ces choses, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Ces quatre grandes bêtes sont quatre Rois, qui s’élèveront sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Et les Saints du Souverain recevront le Royaume, et obtiendront le Royaume jusqu’au siècle, et au siècle des siècles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Alors je voulus savoir la vérité touchant la quatrième bête, qui était différente de toutes les autres, et fort terrible, de laquelle les dents étaient de fer, et les ongles d’airain, qui mangeait, et brisait, et foulait à ses pieds ce qui restait;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'Et touchant les dix cornes qui étaient en sa tête; et touchant l’autre corne qui montait, par le moyen de laquelle les trois étaient tombées; et de ce que cette corne-là avait des yeux, et une bouche qui proférait de grandes choses; et de ce que son apparence était plus grande que celle de ses compagnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'J’avais regardé comment cette corne faisait la guerre contre les Saints, et les surmontait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'Jusqu’à ce que l’Ancien des jours fût venu, et que le jugement fût donné aux Saints du Souverain, et que le temps vînt auquel les Saints obtinssent le Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Il me parla donc ainsi: La quatrième bête sera un quatrième Royaume sur la terre, lequel sera différent de tous les Royaumes, et dévorera toute la terre, et la foulera, et la brisera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Mais les dix cornes sont dix Rois qui s’élèveront de ce Royaume, et un autre s’élèvera après eux, qui sera différent des premiers, et il abattra trois Rois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Il proférera des paroles contre le Souverain, et détruira les Saints du Souverain, et pensera de pouvoir changer les temps et la Loi; et les Saints seront livrés en sa main jusqu’à un temps, et des temps, et une moitié de temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Mais le jugement se tiendra, et on lui ôtera sa domination, en le détruisant et le faisant périr, jusqu’à en voir la fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Afin que le règne, et la domination, et la grandeur des Royaumes qui sont sous tous les cieux, soit donné au peuple des Saints du Souverain; son Royaume est un Royaume éternel, et tous les Empires lui seront assujettis, et lui obéiront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Jusqu’ici est la fin de cette parole-là. Quant à moi Daniel, mes pensées me troublèrent fort, et mon bon visage fut changé en moi; toutefois je gardai cette parole dans mon coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'La troisième année du Roi Belsatsar, une vision m’apparut, à moi Daniel, après celle qui m’était apparue au commencement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Je vis donc une vision, et ce fut à Susan, capitale de la Province d’Hélam que je la vis; je vis, dis-je, une vision, et j’étais sur le fleuve d’Ulaï.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Et j’élevai mes yeux, et regardai; et voici, un bélier se tenait près du fleuve, et il avait deux cornes; et les deux cornes étaient hautes; mais l’une était plus haute que l’autre, et la plus haute s’élevait sur le derrière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Je vis ce bélier heurtant des cornes contre l’Occident, et contre l’Aquilon, et contre le Midi, et pas une bête ne pouvait subsister devant lui, et il n’y avait personne qui lui pût rien ôter, mais il agissait selon sa volonté, et devenait grand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Et comme je regardais cela, voici, un bouc d’entre les chèvres venait de l’Occident sur le dessus de toute la terre, et ne touchait point à terre; et ce bouc avait entre ses yeux une corne, qui paraissait beaucoup.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Et il vint jusqu’au bélier qui avait deux cornes, lequel j’avais vu se tenant près du fleuve, et il courut contre lui dans la fureur de sa force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Et je le vis approcher du bélier et s’irritant contre lui, il heurta le bélier, et brisa ses deux cornes; et il n’y avait aucune force au bélier pour tenir ferme contre lui, et quand il l’eut jeté par terre, il le foula, et nul ne pouvait délivrer le bélier de sa puissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Alors le bouc d’entre les chèvres devint fort grand, et sitôt qu’il fut devenu puissant, la grande corne fut rompue, et en sa place il en crût quatre, fort apparentes, vers les quatre vents des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Et de l’une d’elles sortit une autre corne petite, qui s’agrandit vers le Midi, et vers l’Orient, et vers le pays de noblesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Elle s’agrandit même jusqu’à l’armée des cieux, et renversa une partie de l’armée, et des étoiles, et les foula.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Même elle s’agrandit jusqu’au Chef de l’armée; et le sacrifice continuel fut ôté par cette corne, et le domicile assuré de son sanctuaire fut jeté par terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Et un certain temps lui fut donné à cause de l’infidélité contre le sacrifice continuel, et elle jeta la vérité par terre, et fit de grands exploits, et prospéra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Alors j’ouïs un Saint qui parlait, et un Saint disait à quelqu’un qui parlait: Jusqu’à quand durera cette vision touchant le sacrifice continuel, et touchant le crime qui cause la désolation, pour livrer le Sanctuaire et l’armée à être foulés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Et il me dit: Jusqu’à deux mille trois cents soirs et matins; après quoi le Sanctuaire sera purifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Or quand moi Daniel j’eus vu la vision, et que j’en eus demandé l’interprétation, voici, comme la ressemblance d’un homme se tint devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Et j’entendis la voix d’un homme au milieu du fleuve Ulaï, qui cria, et dit: Gabriel, fais entendre la vision à cet homme-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Puis Gabriel s’en vint près du lieu où je me tenais, et quand il fut venu, je fus épouvanté, et je tombai sur ma face; et il me dit: Fils d’homme, entends, car il y a un temps marqué pour cette vision.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Et comme il parlait avec moi, je m’assoupis ayant le visage contre terre; puis il me toucha, et me fit tenir debout dans le lieu où je me tenais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Et il dit: Voici, je te ferai savoir ce qui arrivera à la fin de l’indignation; car il y a une assignation déterminée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Le bélier que tu as vu qui avait deux cornes, ce sont les Rois des Mèdes et des Perses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Et le bouc velu, c’est le Roi de Javan; et la grande corne qui était entre ses yeux, c’est le premier Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Et ce qu’elle s’est rompue, et que quatre cornes sont venues en sa place, ce sont quatre Royaumes, qui s’établiront de cette nation; mais non pas selon la force de cette corne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Et vers la fin de leur règne, quand le nombre des perfides sera accompli, il se lèvera un Roi, fourbe et d’un esprit pénétrant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Et sa puissance s’accroîtra, mais non point par sa force; et il fera de merveilleux dégâts, et prospérera, et fera de grands exploits, et il détruira les puissants, et le peuple des Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Et par la subtilité de son esprit il fera prospérer la fraude en sa main, et il s’élèvera en son coeur, et en perdra plusieurs par la prospérité; il résistera contre le Seigneur des Seigneurs, mais il sera brisé sans main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Or la vision du soir et du matin, qui a été dite, est très- véritable; et toi, cachette la vision, car elle n’arrivera point de longtemps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Et moi Daniel, je fus tout défait et malade pendant quelques jours; puis je me levai, et je fis les affaires du Roi; et j’étais tout étonné de la vision, mais il n’y eut personne qui l’entendit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'La première année de Darius, fils d’Assuérus, de la race des Mèdes, qui avait été établi Roi sur le Royaume des Caldéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'La première année, dis-je, de son règne, moi Daniel ayant entendu par les Livres, que le nombre des années, duquel l’Eternel avait parlé au Prophète Jérémie pour finir les désolations de Jérusalem, était de soixante et dix ans;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Je tournai ma face vers le Seigneur Dieu, cherchant à faire requête et supplication avec le jeûne, le sac, et la cendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Et je priai l’Eternel mon Dieu, je lui fis ma confession, et je dis: Hélas! Seigneur, le Dieu Fort, le Grand, le Terrible, qui gardes l’alliance et la miséricorde à ceux qui t’aiment, et qui gardent tes commandements;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Nous avons péché, nous avons commis l’iniquité, nous avons agi méchamment, nous avons été rebelles, et nous nous sommes détournés de tes commandements et de tes ordonnances;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Et nous n’avons point obéi aux Prophètes tes serviteurs qui ont parlé en ton Nom à nos Rois, à nos principaux, à nos pères, et à tout le peuple du pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Ô Seigneur! à toi est la justice, et à nous la confusion de face, qui couvre aujourd’hui les hommes de Juda, et les habitants de Jérusalem, et tous ceux d’Israël qui sont près et qui sont loin, par tous les pays dans lesquels tu les as dispersés, à cause de leur prévarication qu’ils ont commise contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Seigneur, à nous est la confusion de face, à nos Rois, à nos principaux, et à nos pères, parce que nous avons péché contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Les miséricordes et les pardons sont du Seigneur notre Dieu, car nous nous sommes rebellés contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'Et nous n’avons point écouté la voix de l’Eternel notre Dieu pour marcher dans ses lois, qu’il a mises devant nous par le moyen de ses serviteurs, les Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Et tous ceux d’Israël ont transgressé ta Loi, et se sont détournés pour n’écouter point ta voix; c’est pourquoi l’exécration et le serment écrit dans la Loi de Moïse, serviteur de Dieu, ont fondu sur nous; car nous avons péché contre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Et il a ratifié ses paroles qu’il avait prononcées contre nous, et contre nos gouverneurs qui nous ont gouvernés, et il a fait venir sur nous un grand mal, tel qu’il n’en est point arrivé sous tous les cieux de semblable à celui qui est arrivé à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Tout ce mal est venu sur nous, selon ce qui est écrit dans la Loi de Moïse; et nous n’avons point supplié l’Eternel notre Dieu, pour nous détourner de nos iniquités, et pour nous rendre attentifs à ta vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Et l’Eternel a veillé sur le mal, que nous avons fait et il l’a fait venir sur nous; car l’Eternel notre Dieu est juste en toutes ses oeuvres qu’il a faites, vu que nous n’avons point obéi à sa voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Or maintenant, Seigneur notre Dieu! qui as tiré ton peuple du pays d’Egypte par main forte, et qui t’es acquis un nom, tel qu’ il paraît aujourd’hui, nous avons péché, nous avons été méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Seigneur, je te prie que selon toutes tes justices ta colère et ton indignation soient détournées de ta ville de Jérusalem, la montagne de ta sainteté; car c’est à cause de nos péchés, et à cause des iniquités de nos pères, que Jérusalem et ton peuple sont en opprobre à tous ceux qui sont autour de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Ecoute donc, maintenant, ô notre Dieu! la requête de ton serviteur, et ses supplications, et pour l’amour du Seigneur fais reluire ta face sur ton Sanctuaire désolé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Mon Dieu! prête l’oreille, et écoute; ouvre tes yeux, et regarde nos désolations, et la ville sur laquelle ton Nom a été invoqué; car nous ne présentons point nos supplications devant ta face appuyés sur nos justices, mais sur tes grandes compassions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Seigneur exauce, Seigneur pardonne, Seigneur sois attentif, et opère; ne tarde point, à cause de toi-même, mon Dieu! car ton nom a été invoqué sur ta ville, et sur ton peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Or comme je parlais encore, et faisais ma requête, et confessais mon péché, et le péché de mon peuple d’Israël, et répandais ma supplication en la présence de l’Eternel mon Dieu, pour la montagne de la sainteté de mon Dieu:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'Comme donc je parlais encore dans ma prière, ce personnage Gabriel que j’avais vu en vision du commencement, volant promptement me toucha, environ sur le temps de l’oblation du soir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Il m’instruisit, il me parla, et me dit: Daniel, je suis sorti maintenant pour te faire entendre une chose digne d’être entendue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'La parole est sortie dès le commencement de tes supplications, et je suis venu pour te le déclarer, parce que tu es agréable. Entends donc la parole, et entends la vision.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Il y a septante semaines déterminées sur ton peuple, et sur ta sainte ville, pour abolir l’infidélité, consumer le péché, faire propitiation pour l’iniquité, pour amener la justice des siècles, pour mettre le sceau à la vision, et à la prophétie, et pour oindre le Saint des Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Tu sauras donc, et tu entendras, que depuis la sortie de la parole portant qu’on s’en retourne, et qu’on rebâtisse Jérusalem, jusqu’au CHRIST le Conducteur, il y a sept semaines et soixante-deux semaines; et les places et la brèche seront rebâties, et cela en un temps d’angoisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Et après ces soixante-deux semaines, le CHRIST sera retranché, mais non pas pour soi; puis le peuple du Conducteur, qui viendra, détruira la ville et le Sanctuaire, et la fin en sera avec débordement, et les désolations sont déterminées jusqu’à la fin de la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Et il confirmera l’alliance à plusieurs dans une semaine, et à la moitié de cette semaine il fera cesser le sacrifice, et l’oblation; puis par le moyen des ailes abominables, qui causeront la désolation, même jusqu’à une consomption déterminée, la désolation fondra sur le désolé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'La troisième année de Cyrus, Roi de Perse, une parole fut révélée à Daniel, qui était nommé Beltesatsar; et cette parole est vraie, mais le temps déterminé en est long, et il entendit la parole, et il eut intelligence dans la vision.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'En ce temps-là, moi Daniel je fus en deuil pendant trois semaines entières;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Et je ne mangeai point de pain agréable au goût, et il n’entra point de viande ni de vin dans ma bouche, et je ne m’oignis point du tout, jusqu’à ce que ces trois semaines entières fussent accomplies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'Et le vingt-quatrième jour du premier mois j’étais auprès du bord du grand fleuve, qui est Hiddékel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Et j’élevai mes yeux, et regardai; et voilà un homme vêtu de lin, et duquel les reins étaient ceints d’une ceinture de fin or d’Uphaz;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Et son corps était comme de chrysolithe, et son visage comme la splendeur d’un éclair, ses yeux étaient comme des lampes de feu, et ses bras et ses pieds comme l’éclat d’un airain poli, et le bruit de ses paroles était comme le bruit d’une multitude de gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Et moi Daniel je vis seul la vision, et les hommes qui étaient avec moi ne la virent point; mais une grande frayeur tomba sur eux, et ils s’enfuirent pour se cacher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Et moi étant laissé tout seul je vis cette grande vision, et il ne demeura point de force en moi; aussi mon extérieur fut changé, jusqu’à être tout défait, et je ne conservai aucune vigueur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Car j’ouïs la voix de ses paroles, et sitôt que j’eus ouï la voix de ses paroles je fus accablé de sommeil, couché sur mon visage, ayant mon visage contre terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Et voici, une main me toucha, et me fit mettre sur mes genoux, et sur les paumes de mes mains;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Puis il me dit: Daniel, homme aimé de Dieu, entends les paroles que je te dis, et te tiens debout sur tes pieds, car j’ai été maintenant envoyé vers toi; et quand il m’eut dit cette parole-là, je me tins debout, en tremblant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Et il me dit: Ne crains point, Daniel, car dès le premier jour que tu as appliqué ton coeur à entendre, et à t’affliger en la présence de ton Dieu, tes paroles ont été exaucées, et je suis venu à cause de tes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Mais le Chef du Royaume de Perse a résisté contre moi vingt et un jours; mais voici, Michaël, l’un des principaux Chefs, est venu pour m’aider, et je suis demeuré là chez les Rois de Perse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Et je suis venu pour te faire entendre ce qui doit arriver à ton peuple aux derniers jours, car il y a encore une vision pour ces jours-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Et comme il me tenait ces discours, je mis mon visage contre terre, et je me tus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Et voici, quelqu’un ayant la ressemblance d’un homme toucha mes lèvres, et ouvrant ma bouche, je parlai, et je dis à celui qui était auprès de moi: mon Seigneur! mes jointures se sont relâchées par cette vision, et je n’ai conservé aucune vigueur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Et comment pourra le serviteur de mon Seigneur parler avec mon Seigneur, puisque dès maintenant il n’est resté en moi aucune vigueur, et que mon souffle n’est point demeuré en moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Alors celui qui ressemblait à un homme me toucha encore, et me fortifia.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Et me dit: ne crains point, homme qui es reçu en grâce; paix soit avec toi, fortifie-toi, fortifie-toi, dis-je; et comme il parlait avec moi, je me fortifiai, et je dis: Que mon seigneur parle, car tu m’as fortifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Et il dit: Ne sais-tu pas pourquoi je suis venu vers toi? Or maintenant je m’en retournerai pour combattre contre le Chef de Perse; puis je sortirai, et voici, le Chef de Javan viendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Au reste, je te déclarerai ce qui est écrit dans l’Ecriture de vérité; cependant il n’y en a pas un qui tienne ferme avec moi en ces choses, sinon Michaël votre chef.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Or en la première année de Darius le Mède j’assistais pour l’affermir et le fortifier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Et maintenant aussi je te ferai savoir la vérité: Voici, il y aura encore trois Rois en Perse, puis le quatrième possédera de grandes richesses par-dessus tous; et s’étant fortifié par ses richesses il soulèvera tout le monde contre le Royaume de Javan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Et un Roi puissant se lèvera, et dominera avec une grande puissance, et fera selon sa volonté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Et sitôt qu’il sera en état, son Royaume sera brisé, et partagé vers les quatre vents des cieux, et ne sera point pour sa race, ni selon la domination avec laquelle il aura dominé: car son Royaume sera extirpé, et sera donné à d’autres, outre ceux-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Et le Roi du Midi sera fort puissant, mais un des principaux chefs du Roi de Javan sera plus puissant que le Roi du Midi, et dominera, et sa domination sera une grande domination.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Et au bout de certaines années ils s’allieront, et la fille du Roi du Midi viendra vers le Roi de l’Aquilon, pour redresser les affaires; mais elle ne retiendra point la force du bras, et ni lui ni son bras ne subsisteront point; mais elle sera livrée, et ceux aussi qui l’auront amenée, et celui qui sera né d’elle, et qui la fortifiait en ces temps-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Mais le soutien du Royaume du Midi s’élèvera d’un rejeton des racines d’elle, et viendra à l’armée, et entrera dans les forteresses du Roi de l’Aquilon, et y fera de grands exploits, et se fortifiera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Et même il emmènera captifs en Egypte leurs dieux avec les vaisseaux de leurs aspersions, et avec leurs vaisseaux précieux d’argent et d’or, et il subsistera quelques années plus que le Roi de l’Aquilon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Et le Roi du Midi entrera dans son Royaume, mais il s’en retournera en son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Mais les fils de celui-là entreront en guerre, et assembleront une multitude de grandes armées; puis l’un d’eux viendra certainement, et se répandra, et passera; il retournera, dis-je, et s’avancera en bataille jusqu’à la forteresse du Roi du Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Et le Roi du Midi sera irrité, et sortira, et combattra contre lui, savoir contre le Roi de l’Aquilon; et il assemblera une grande multitude, et cette multitude sera livrée entre les mains du Roi du Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Et après avoir défait cette multitude il élèvera son coeur, et abattra des gens à milliers, mais il ne sera pas fortifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Car le Roi de l’Aquilon reviendra, et assemblera une plus grande multitude que la première, et au bout de quelque temps, savoir, de quelques années, il viendra certainement avec une grande armée, et un grand appareil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Et en ce temps-là plusieurs s’élèveront contre le Roi du Midi; et les hommes violents de ton peuple s’élèveront, afin de confirmer la vision, mais ils tomberont.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Et le Roi de l’Aquilon viendra, et fera des terrasses, et prendra les villes fortes; et les bras du Midi, ni son peuple d’élite ne pourront point résister, car il n’y aura point de force pour résister.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Et il fera de celui qui sera venu contre lui, selon sa volonté, et il n’y aura personne qui tienne ferme devant lui; et il s’arrêtera au pays de noblesse, et il y aura consomption par sa force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Puis il tournera sa face pour entrer par force dans tout le Royaume de celui-là, et ses affaires iront bien, et il fera de grands exploits, et il lui donnera une fille de femmes, pour ruiner le Royaume; mais cela ne tiendra point, et elle ne sera point pour lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Puis il tournera sa face vers les Iles, et en prendra plusieurs, mais un capitaine l’obligera de cesser l’opprobre qu’il faisait, et outre cela il fera retomber sur lui son opprobre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Puis il tournera visage vers les forteresses de son pays, il heurtera, il sera renversé, et il ne sera plus trouvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Et un autre sera établi en sa place, qui enverra l’exacteur pour la Majesté Royale, et il sera détruit dans peu de jours, mais non dans une rencontre, ni dans une bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Et en sa place il en sera établi un autre qui sera méprisé, auquel on ne donnera point l’honneur royal; mais il viendra en paix, et il occupera le Royaume par des flatteries.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Et les bras des grandes eaux seront engloutis par un déluge devant lui, et seront rompus, et il sera le Chef d’un accord.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Mais après les accords faits avec lui, il usera de tromperie, et il montera, et se renforcera avec peu de gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Il entrera dans les lieux gras d’une Province alors paisible, et il fera des choses que ses pères, ni les pères de ses pères, n’ont point faites; il leur répandra le pillage, le butin, et les richesses; et il formera des desseins contre les forteresses: et cela jusqu’à un certain temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Puis il réveillera sa force et son coeur contre le Roi du Midi, avec une grande armée, et le Roi du Midi s’avancera en bataille avec une très grande et très forte armée, mais il ne subsistera point, parce qu’on formera des entreprises contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Et ceux qui mangent les mets de sa table le mettront en pièces, et son armée sera accablée, comme d’un déluge, et beaucoup de gens tomberont blessés à mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Et le coeur de ces deux Rois sera adonné à s’entre-nuire, et ils parleront en une même table avec tromperie, ce qui ne tournera point à bien; car il y aura encore une fin au temps ordonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Après quoi il s’en retournera en son pays avec de grandes richesses, et son coeur sera contre la sainte alliance, et il fera de grands exploits, puis il retournera en son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Ensuite il retournera au temps préfix, et il viendra contre le Midi, mais cette dernière expédition ne sera pas comme la précédente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Car les navires de Kittim viendront contre lui, dont il sera contristé, et il s’en retournera, et il sera irrité contre la sainte alliance, et fera de grands exploits, et retournera, et s’entendra avec les apostats de la sainte alliance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Et les forces seront de son côté, et on souillera le Sanctuaire, qui est la forteresse, et on ôtera le sacrifice continuel, et on y mettra l’abomination qui causera la désolation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Et il fera pécher par flatteries ceux qui se porteront méchamment dans l’alliance; mais le peuple de ceux qui connaîtront leur Dieu se fortifiera, et fera de grands exploits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Et les plus intelligents d’entre le peuple donneront instruction à plusieurs, et il y en aura qui tomberont par l’épée et par la flamme, ou qui seront en captivité et en proie durant plusieurs jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Et lorsqu’ils tomberont ainsi, ils seront un peu secourus; mais plusieurs se joindront à eux sous un beau semblant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Et quelques-uns de ces plus intelligents tomberont, afin qu’il y en ait d’entre eux qui soient rendus éprouvés, qui soient épurés, et qui soient blanchis, jusqu’au temps déterminé; car cela est encore pour un certain temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Ce Roi donc fera selon sa volonté, et s’enorgueillira, et s’élèvera par-dessus tout Dieu; il proférera des choses étranges contre le Dieu des dieux, et prospérera jusqu’à ce que l’indignation ait pris fin; car la détermination en a été faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Et il ne se souciera point des dieux de ses pères, ni de l’amour des femmes, même il ne se souciera d’aucun Dieu; car il s’élèvera au-dessus de tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Mais il honorera dans son lieu le dieu Mahuzzim, il honorera, dis- je, avec de l’or et de l’argent, et des pierres précieuses, et des choses désirables, le dieu que ses pères n’ont point connu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'Et il fera de grands exploits dans les forteresses les plus fortes, tenant le parti du dieu inconnu qu’il aura connu, il leur multipliera la gloire, et les fera dominer sur plusieurs, et leur partagera le pays à prix d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Et au temps déterminé le Roi du Midi choquera avec lui de ses cornes mais le Roi de l’Aquilon se lèvera contre lui comme une tempête, avec des chariots et des gens de cheval, et avec plusieurs navires, et il entrera dans ses terres, et les inondera, et passera outre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Et il entrera au pays de noblesse, et plusieurs pays seront ruinés, mais ceux-ci réchapperont de sa main, savoir, Edom, et Moab, et le principal lieu des enfants de Hammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Il mettra donc la main sur ces pays-là; et le pays d’Egypte n’échappera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Il se rendra maître des trésors d’or et d’argent, et de toutes les choses désirables de l’Egypte; les Libyens et ceux de Cus seront à sa suite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Mais les nouvelles de l’Orient et de l’Aquilon le troubleront, et il sortira avec une grande fureur, pour détruire et exterminer beaucoup de gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Et il dressera les tentes de sa maison royale entre les mers, à l’ opposite de la noble montagne de la sainteté; mais il viendra à sa fin, et personne ne lui donnera du secours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Or, en ce temps-là Michaël, ce grand Chef qui tient ferme pour les enfants de ton peuple, tiendra ferme; et ce sera un temps de détresse, tel qu’il n’y en a point eu depuis qu’il y a eu des nations, jusqu’à ce temps-là; et en ce temps-là ton peuple, c’est à savoir, quiconque sera trouvé écrit dans le Livre, échappera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Et plusieurs de ceux qui dorment dans la poussière de la terre se réveilleront, les uns pour la vie éternelle, et les autres pour les opprobres et pour l’infamie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Et ceux qui auront été intelligents, luiront comme la splendeur de l’étendue; et ceux qui en auront amené plusieurs à la justice luiront comme des étoiles, à toujours et à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Mais toi, Daniel, ferme ces paroles, et cachette ce Livre jusqu’au temps déterminé, auquel plusieurs courront, et la science sera augmentée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Alors moi Daniel je regardai; et voici, deux autres se tenaient debout, l’un en deçà, sur le bord du fleuve, et l’autre au delà, sur le bord du fleuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Et on dit à l’homme vêtu de lin qui était au-dessus des eaux du fleuve: Quand est-ce que sera la fin de ces merveilles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Et j’entendis l’homme vêtu de lin, qui était au-dessus des eaux du fleuve, lequel ayant élevé sa main droite et sa main gauche vers les cieux, jura par celui qui vit éternellement, que ce sera jusqu’à un temps, à des temps, et une moitié de temps; et quand il aura achevé de disperser la force du peuple saint, toutes ces choses-là seront accomplies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Ce que j’ouïs bien, mais je ne l’entendis point; et je dis: Mon Seigneur, quelle sera l’issue de ces choses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Et il dit: Va, Daniel, car ces paroles sont closes et cachetées jusqu’au temps déterminé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Il y en aura plusieurs qui seront nettoyés et blanchis, et rendus éprouvés; mais les méchants agiront méchamment, et pas un des méchants n’aura de l’intelligence, mais les intelligents comprendront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Or depuis le temps que le sacrifice continuel aura été ôté, et qu’on aura mis l’abomination de la désolation, il y aura mille deux cent quatre-vingt-dix jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Heureux celui qui attendra, et qui parviendra jusques à mille trois cent trente-cinq jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Mais toi, va à ta fin; néanmoins tu te reposeras, et demeureras dans ton état jusqu’à la fin de tes jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'La parole de l’Eternel qui fut adressée à Osée fils de Béeri, au temps de Hozias, Jotham, Achaz et Ezéchias, Rois de Juda, et au temps de Jéroboam fils de Joas, Roi d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Au commencement que l’Eternel parla par Osée, l’Eternel dit à Osée: Va, prends-toi une femme débauchée, et aie d’elle des enfants illégitimes; car le pays ne fait que commettre adultère, se détournant de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Il s’en alla donc, et prit Gomer, fille de Diblajim, laquelle conçut, et lui enfanta un fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Et l’Eternel lui dit: Appelle son nom Jizréhel; car encore un peu de temps, et je visiterai le sang de Jizréhel sur la maison de Jéhu, et ferai cesser le règne de la maison d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'Et il arrivera qu’en ce jour-là je romprai l’arc d’Israël dans la vallée de Jizréhel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Elle conçut encore, et elle enfanta une fille, et l’Eternel lui dit: Appelle son nom Lo-ruhama; car je ne continuerai plus de faire miséricorde à la maison d’Israël, mais je les enlèverai entièrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Mais je ferai miséricorde à la maison de Juda, et je les délivrerai par l’Eternel leur Dieu; et je ne les délivrerai point par l’arc, ni par l’épée, ni par des combats, ni par des chevaux, ni par des gens de cheval.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Puis quand elle eut sevré Lo-ruhama, elle conçut, et enfanta un fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Et l’Eternel dit: Appelle son nom Lo-hammi; car vous n’êtes point mon peuple, et je ne serai point votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Toutefois il arrivera que le nombre des enfants d’Israël sera comme le sable de la mer, qui ne se peut ni mesurer, ni compter; et il arrivera qu’au lieu où on leur aura dit: Vous êtes Lo-hammi, il leur sera dit: Vous êtes les enfants du Dieu vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'Aussi les enfants de Juda, et les enfants d’Israël seront assemblés, et ils s’établiront un Chef, et remonteront hors du pays; car la journée de Jizréhel aura été grande. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Appelez vos frères Hammi, et vos soeurs Ruhama.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Plaidez, plaidez avec votre mère, car elle n’ est point ma femme, et aussi ne suis-je point son mari; et qu’elle ôte ses prostitutions de devant elle, et ses adultères de son sein.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'De peur que je ne manifeste sa nudité, que je ne la remette dans l’état où elle était le jour qu’elle naquit, que je ne la réduise en désert, et que je ne la fasse être comme une terre sèche, et ne la fasse mourir de soif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Et que je n’use point de miséricorde envers ses enfants, car ce sont des enfants de prostitution.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Parce que leur mère s’est prostituée, celle qui les a conçus s’est déshonorée, car elle a dit: Je m’en irai après ceux que j’aime, qui me donnent mon pain et mes eaux, ma laine, et mon lin, mon huile, et mes boissons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'C’est pourquoi, voici, je boucherai d’épines ton chemin, et je ferai une cloison de pierres, en sorte qu’elle ne trouvera point ses sentiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Elle ira donc vers ceux dont elle recherche l’amitié; mais elle ne les atteindra point; elle les cherchera, mais elle ne les trouvera point; et elle dira: Je m’en irai et retournerai à mon premier mari, car alors j’étais mieux que je ne suis maintenant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Mais elle n’a point connu que c’était moi qui lui avais donné le froment, et le vin, et l’huile, et qui lui avais multiplié l’argent et l’or dont ils ont fait un Bahal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'C’est pourquoi je viendrai à reprendre mon froment en son temps, et mon vin en sa saison, et je retirerai ma laine et mon lin qui couvraient sa nudité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Et maintenant je découvrirai sa turpitude devant les yeux de ceux qui l’aiment, et personne ne la délivrera de ma main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Je ferai cesser toute sa joie, ses fêtes, ses nouvelles lunes, ses Sabbats, et toutes ses solennités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Et je gâterai ses vignobles, et ses figuiers, desquels elle a dit: Ce sont ici mes salaires que ceux qui m’aiment m’ont donnés; et je les réduirai en forêt, et les bêtes des champs les dévoreront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Et je visiterai sur elle les jours des Bahalins, durant lesquels elle leur faisait des parfums, et se parait de ses bagues et de ses joyaux, et s’en allait après ceux qui l’aimaient, et m’oubliait, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Néanmoins, voici, je l’attirerai après que je l’aurai promenée par le désert, et je lui parlerai selon son coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Et je lui donnerai ses vignes, depuis ce lieu-là, et la vallée de Hachor, pour l’entrée de son attente, et elle y chantera comme au temps de sa jeunesse, et comme lorsqu’elle remonta du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Et il arrivera en ce jour-là, dit l’Eternel, que tu m’appelleras, Mon mari, et que tu ne m’appelleras plus, Mon Bahal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Car j’ôterai de sa bouche les noms des Bahalins, et on n’en fera plus mention par leur nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Aussi en ce temps-là je traiterai pour eux une alliance avec les bêtes des champs, et avec les oiseaux des cieux, et avec les reptiles de la terre; et je briserai et j’ôterai du pays, l’arc, et l’épée, et la guerre, et je les ferai dormir en sûreté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Et je t’épouserai pour moi à toujours; je t’épouserai, dis-je, pour moi, en justice, et en jugement, et en gratuité, et en compassions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Même je t’épouserai en fermeté, et tu connaîtras l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Et il arrivera en ce temps-là que je répondrai, dit l’Eternel, que je répondrai aux cieux, et les cieux répondront à la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'Et la terre répondra au froment, au bon vin, et à l’huile; et eux répondront à Jizréhel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Puis je la sèmerai pour moi en la terre, et je ferai miséricorde à Lo- ruhama; et je dirai à Lo-hammi, tu es mon peuple; et il me dira, mon Dieu. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Après cela l’Eternel me dit: Va encore aimer une femme aimée d’un ami, et néanmoins adultère, selon l’amour de l’Eternel envers les enfants d’Israël, qui toutefois regardent à d’autres dieux, et aiment les flacons de vin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Je m’acquis donc cette femme- là pour quinze pièces d’argent et un homer et demi d’orge;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Et je lui dis: Tu demeureras avec moi pendant plusieurs jours; tu ne t’abandonneras plus, et tu ne seras à aucun mari; et aussi je te serai fidèle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Car les enfants d’Israël demeureront plusieurs jours sans Roi et sans Gouverneur, sans sacrifice, et sans statue, sans Ephod et sans Théraphim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Mais après cela les enfants d’Israël se repentiront, et rechercheront l’Eternel leur Dieu, et David leur Roi, ils révéreront l’Eternel et sa bonté aux derniers jours. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Enfants d’Israël, écoutez la parole de l’Eternel; car l’Eternel a un procès avec les habitants du pays; parce qu’il n’y a point de vérité, ni de miséricorde, ni de connaissance de Dieu au pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Il n’y a qu’exécration, que mensonge, que meurtre, que larcin et qu’adultère; ils se sont entièrement débordés, et un meurtre touche l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'C’est pourquoi le pays sera en deuil, et tout homme qui y habite sera dans la langueur, avec les bêtes des champs, et les oiseaux des cieux; même les poissons de la mer périront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Quoi qu’il en soit, qu’on ne plaide avec personne, et qu’on ne reprenne personne; car, quant à ton peuple, ce sont autant de gens qui disputent avec le Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Tu tomberas donc en plein jour, et le prophète aussi tombera avec toi de nuit, et j’exterminerai ta mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Mon peuple est détruit à cause qu’il est sans science. Parce que tu as rejeté la science, je te rejetterai, afin que tu ne m’exerces plus la sacrificature. Puisque tu as oublié la Loi de ton Dieu, moi aussi j’oublierai tes enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'A mesure qu’ils se sont accrus ils ont péché contre moi: je changerai leur gloire en ignominie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Ils mangent les péchés de mon peuple, et ne demandent rien que son iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'C’est pourquoi le Sacrificateur sera traité comme le peuple, et je le visiterai selon son train, et je lui rendrai selon ses actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Et ils mangeront, mais ils ne seront point rassasiés; ils se prostitueront, mais ils ne multiplieront point; parce qu’ils ont abandonné l’Eternel, pour ne s’y tenir point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'La luxure, et le vin, et le moût, ôtent l’entendement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Mon peuple demande avis à son bois, et son bâton lui répond: car l’esprit de fornication les a fait errer, et ils ont commis adultère se détournant de leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Ils sacrifient sur le sommet des montagnes, et font des parfums sur les coteaux, sous les chênes, sous les peupliers, et sous les ormes, parce que leur ombre est bonne; c’est pourquoi vos filles se prostitueront, et les femmes de vos fils commettront adultère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Je ne ferai point punition de vos filles quand elles se seront abandonnées, ni des femmes de vos fils, quand elles auront commis adultère; à cause qu’ils se séparent avec les prostituées, et qu’ils sacrifient avec les femmes débauchées; ainsi le peuple qui est sans intelligence, sera ruiné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Si tu commets adultère, ô Israël! au moins que Juda ne se rende point coupable; n’entrez donc point dans Guilgal, et ne montez point à Beth-aven, et ne jurez point; l’Eternel est vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Parce qu’Israël a été revêche comme une génisse revêche, l’Eternel les paîtra maintenant comme des agneaux dans des lieux spacieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Ephraïm s’est associé aux idoles; abandonne-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Leur breuvage est devenu aigre; ils n’ont fait que se prostituer; ils n’aiment qu’à dire, apportez; ce n’est qu’ignominie que ses protecteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Le vent l’a enserré dans ses ailes, et ils auront honte de leurs sacrifices. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Ecoutez ceci Sacrificateurs, et vous maison d’Israël, soyez attentifs, et vous maison du Roi, prêtez l’oreille; car c est à vous de faire justice; mais vous êtes devenus comme un piège en Mitspa, et comme un rets étendu sur Tabor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Et ils ont subtilement inventé les moyens d’égorger les révoltés, mais je les châtierai tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Je sais qui est Ephraïm, et Israël ne m’est point inconnu: car maintenant, toi, Ephraïm, tu as commis adultère, Israël est souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Leurs déportements ne permettront point qu’ils retournent à leur Dieu, parce que l’esprit de fornication est au milieu d’eux, et ils ne connaissent point l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Aussi la fierté d’Israël témoignera contre lui, et Israël et Ephraïm tomberont dans leur iniquité; Juda aussi tombera avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Ils iront avec leurs brebis et leurs boeufs chercher l’Eternel, mais ils ne le trouveront point, il s’est retiré d’avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Ils se sont portés infidèlement contre l’Eternel; car ils ont engendré des enfants étrangers; maintenant un mois les dévorera avec leurs biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Sonnez du cor à Guibha, et de la trompette à Rama; sonnez avec retentissement à Bethaven; on est derrière toi, Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Ephraïm sera en désolation au jour de la correction; je le fais savoir parmi les Tribus d’Israël comme une chose certaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Les Gouverneurs de Juda sont autant de remueurs de bornes, je répandrai sur eux ma fureur comme de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Ephraïm est opprimé, il est brisé justement, parce que de son bon gré il est allé après le commandement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Je serai donc à Ephraïm comme la teigne, et à la maison de Juda, comme la vermoulure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Et Ephraïm a vu sa langueur, et Juda sa plaie; Ephraïm s’en est allé vers le Roi d’Assyrie, et on a envoyé vers le Roi Jareb, mais il ne vous pourra pas guérir, et il ne pansera point la plaie pour vous en délivrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Car je serai comme un lion à Ephraïm, et comme un lionceau à la maison de Juda; c’est moi, c’est moi qui déchirerai, puis je m’en irai; j’emporterai la proie, et il n’y aura personne qui me l’ôte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Je m’en irai, et retournerai en mon lieu, jusqu’à ce qu’ils se reconnaissent coupables, et qu’ils cherchent ma face; ils me chercheront de grand matin dans leur angoisse. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Venez, diront-ils, et retournons à l’Eternel, car c’est lui qui a déchiré, mais il nous guérira; il a frappé, mais il nous bandera nos plaies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Il nous aura remis en vie dans deux jours, et au troisième jour il nous aura rétablis, et nous vivrons en sa présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Car nous connaîtrons l’Eternel, et nous continuerons à le connaître; son lever se prépare comme celui du point du jour, et il viendra à nous comme la pluie, comme la pluie de la dernière saison qui humecte la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Que te ferai-je, Ephraïm? que te ferai-je, Juda? puisque votre piété est comme une nuée du matin, comme une rosée du matin qui s’en va.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'C’est pourquoi je les ai charpentés par mes Prophètes, je les ai tués par les paroles de ma bouche, et mes jugements sur eux seront comme la lumière qui se lève.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Car je prends plaisir à la miséricorde, et non point aux sacrifices; et à la connaissance de Dieu, plus qu’aux holocaustes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Mais ils ont transgressé l’alliance, comme si elle eût été d’un homme, en quoi ils se sont portés perfidement contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Galaad est une ville d’ouvriers d’iniquité, rusée à tuer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Et comme les bandes des voleurs attendent quelqu’un, ainsi les Sacrificateurs, après avoir comploté, tuent les gens sur le chemin, du côté de Sichem; car ils exécutent leurs méchants desseins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'J’ai vu une chose infâme dans la maison d’Israël; là est la prostitution d’Ephraïm, Israël en est souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Aussi Juda te moissonnera, quand je ramènerai mon peuple captif. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Comme je guérissais Israël, l’iniquité d’Ephraïm et les méchancetés de Samarie se sont découvertes, car ils ont commis fausseté, et le larron entre, et le brigand détrousse dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Et ils n’ont point pensé en leur coeur que je me souviens de toute leur malice; leurs déportements, qui ont été en ma présence, les ont maintenant environnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Ils réjouissent le Roi par leur malice, et les Gouverneurs par leurs perfidies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Eux tous commettent adultère, étant embrasés comme un four que le fournier a chauffé, après qu’il a cessé d’éveiller depuis que la pâte est pétrie jusqu’à ce qu’elle soit levée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Au jour de notre Roi, on a rendu malades les Gouverneurs à force de leur faire boire des bouteilles de vin; il a tendu la main aux bouffons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Car ils ont appliqué à leurs embûches leur coeur embrasé comme un four; leur fournier dort toute la nuit, le matin le four est embrasé comme un feu accompagné de flamme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Ils sont tous échauffés comme un four, et ils dévorent leurs Gouverneurs; tous leurs Rois sont tombés, et il n’y a aucun d’entre eux qui crie à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Ephraïm même se mêle avec les peuples; Ephraïm est comme un gâteau qui n’a point été tourné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Les étrangers ont dévoré sa force, et il ne l’a point connu; les cheveux blancs sont déjà parsemés en lui, et il n’en a rien connu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'L’orgueil d’Israël donc rendra témoignage contre lui; car ils ne se sont point convertis à l’Eternel leur Dieu, et ne l’ont point recherché pour tout cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Ephraïm est devenu comme une colombe simple, sans entendement; car ils ont réclamé l’Egypte, et sont allés vers le Roi d’Assyrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Mais quand ils y iront, j’étendrai mon rets sur eux; et je les abattrai comme les oiseaux des cieux; je les châtierai, selon qu’on l’a fait entendre dans leur assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Malheur à eux, parce qu’ils s’égarent çà et là de moi; ils seront exposés au dégât; car ils ont agi méchamment contre moi; encore les rachèterais-je, mais ils profèrent des mensonges contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'Ils ne crient point vers moi en leur coeur, quand ils hurlent dans leurs lits; ils se déchiquettent pour le froment et le bon vin, et ils se détournent de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Je les ai châtiés, et j’ai fortifié leurs bras, mais ils ont pensé du mal contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Ils se retournent, mais non point au Souverain; ils sont devenus comme un arc qui trompe; les principaux d’entre eux tomberont par l’épée, à cause de la fureur de leur langue; cela leur tournera en moquerie au pays d’Egypte. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Crie comme si tu avais une trompette en ta bouche. Il vient comme un aigle contre la Maison de l’Eternel; parce qu’ils ont transgressé mon alliance, et qu’ils ont agi méchamment contre ma Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Ils crieront à moi: Mon Dieu! nous t’avons connu, dira Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Israël a rejeté le bien; l’ennemi le poursuivra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Ils ont fait régner, mais non pas de ma part; ils ont établi des Gouverneurs, et je n’en ai rien su; ils se sont fait des dieux de leur or et de leur argent; c’est pourquoi ils seront retranchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Samarie, ton veau t’a chassée loin; ma colère s’est embrasée contre eux; jusqu’à quand ne pourront-ils point s’adonner à l’innocence?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Car il est aussi d’Israël, l’orfèvre l’a fait, et il n’est point Dieu; c’est pourquoi le veau de Samarie sera mis en pièces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Parce qu’ils sèment le vent ils recueilleront le tourbillon; et il n’ y aura point de blé debout; le grain ne fera point de farine, et s’il en fait, les étrangers la dévoreront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Israël est dévoré; il est maintenant entre les nations comme un vaisseau dont on ne se soucie point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Car ils sont montés vers le Roi d’Assyrie qui est un âne sauvage, se tenant seul à part; Ephraïm a donné des gages à ceux qu’il aimait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Et parce qu’ils ont donné des gages aux nations, je les assemblerai maintenant; on y a même commencé quelque peu, à cause de l’impôt pour le Roi des Princes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Parce qu’Ephraïm a fait plusieurs autels pour pécher, ils auront des autels pour pécher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Je lui ai écrit les grandes choses de ma Loi, mais elles sont estimées comme des lois étrangères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Quant aux sacrifices qui me sont offerts, ils sacrifient de la chair, et la mangent; mais l’Eternel ne les accepte point, et maintenant il se souviendra de leur iniquité, et punira leurs péchés; ils retourneront en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Israël a mis en oubli celui qui l’a fait, et il a bâti des palais; et Juda a fait plusieurs villes fortes; c’est pourquoi j’enverrai le feu dans les villes de celui ci, quand il aura dévoré les palais de celui-là. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Israël ne te réjouis point jusqu’à t’égayer comme les autres peuples, de ce que tu as commis adultère, te retirant loin de ton Dieu. Tu as aimé le salaire de la fornication dans toutes les aires de froment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'L’aire et la cuve ne les repaîtra point, et le vin doux leur mentira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Ils ne demeureront point en la terre de l’Eternel, mais Ephraïm retournera en Egypte, et ils mangeront en Assyrie la viande souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Ils ne feront point aspersion de vin à l’Eternel, et leurs sacrifices ne lui plairont point; mais ils leur seront comme le pain de deuil; tous ceux qui en mangeront seront souillés; parce que leur pain est pour leurs trépassés, il n’entrera point dans la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Que ferez-vous aux jours des fêtes solennelles, et aux jours des fêtes de l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Car voici, ils s’en sont allés à cause du dégât; l’Egypte les serrera, Memphis les ensevelira; on ne désirera que leur argent; le chardon sera leur héritier, et l’épine sera dans leurs tabernacles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Les jours de la visitation sont venus, les jours de la rétribution sont venus, et Israël le saura. Les Prophètes sont fous, les hommes de révélation sont insensés à cause de la grandeur de ton iniquité, et de ta grande aversion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'La sentinelle d’Ephraïm est avec mon Dieu; mais le Prophète est un filet d’oiseleur dans tous les chemins d’Ephraïm, il est l’aversion contre la maison de son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Ils se sont extrêmement corrompus, comme aux jours de Guibha; il se souviendra de leur iniquité, il punira leurs péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'J’avais, dira-t-il, trouvé Israël comme des grappes dans un désert; j’avais vu vos pères comme un premier fruit en un figuier dans son commencement; mais ils sont entrés vers Bahal-péhor, et se sont séparés pour aller après une chose honteuse, et se sont rendus abominables comme ce qu’ils ont aimé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'La gloire d’Ephraïm s’envolera aussi vite qu’un oiseau, dès la naissance, dès le ventre, et dès la conception.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Que s’ils élèvent leurs enfants, je les en priverai, tellement que pas un d’entre eux ne deviendra homme; car aussi, malheur à eux, quand je me serai retiré d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Ephraïm était comme j’ai vu Tyr, plantée en un lieu agréable, mais néanmoins Ephraïm mènera ses fils au meurtrier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Ô Eternel! donne-leur; mais que leur donnerais-tu? donne-leur un sein sujet à avorter, et des mamelles taries.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Toute leur méchanceté est à Guilgal; c’est pourquoi je les ai là haïs; je les chasserai de ma maison à cause de la malice de leurs actions; je ne continuerai plus à les aimer; tous les principaux d’entre eux sont revêches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Ephraïm a été frappé; et leur racine est asséchée, ils ne feront plus de fruit; et s’ils engendrent des enfants, je mettrai à mort les fruits désirables de leur ventre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Mon Dieu les rejettera, parce qu’ils ne l’ont point écouté, et ils seront vagabonds parmi les nations. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Israël est une vigne déserte, elle ne fait de fruit que pour elle-même, il a multiplié des autels selon la multiplication de son fruit, selon la bonté de leur pays, ils ont embelli leurs statues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Il a divisé leur coeur, ils vont être traités en coupables, il abattra leurs autels, il détruira leurs statues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Car bientôt ils diront: Nous n’avons point de Roi, parce que nous n’avons point craint l’Eternel; et que nous ferait un Roi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Ils ont prononcé des paroles, jurant faussement quand ils ont traité alliance; c’est pourquoi le jugement germera sur les sillons des champs, comme le fiel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Les habitants de Samarie seront épouvantés à cause des jeunes vaches de Beth- aven: car le peuple mènera deuil sur son idole; et les prêtres de ses idoles, qui s’en étaient réjouis, mèneront deuil à cause que sa gloire est transportée loin d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Même elle sera transportée en Assyrie, pour en faire présent au Roi Jareb; Ephraïm recevra de la honte, et Israël sera honteux de son conseil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Le Roi de Samarie sera retranché, comme l’écume qui est au-dessus de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Et les hauts lieux d’Aven, qui sont le péché d’Israël, seront détruits; l’épine et le chardon croîtront sur les autels; et on dira aux montagnes, Couvrez-nous; et aux coteaux: Tombez sur nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Israël, tu as péché dès les jours de Guibha; ils s’y sont arrêtés; la bataille qui était contre les pervers, ne les empoigna point à Guibha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Je les châtierai selon ma volonté, et les peuples seront assemblés contre eux, parce qu’ils se sont attachés aux deux objets de leurs amours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Ephraïm est comme une jeune vache bien dressée, qui aime à fouler le blé, mais j’ai méprisé la beauté de son cou. Je ferai qu’Ephraïm tirera la charrue, Juda labourera, Jacob rompra ses mottes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Semez-vous à la justice, et vous moissonnerez selon la gratuité; rompez les mottes de terre; car il est temps de rechercher l’Eternel, jusqu’à ce qu’il vienne, et fasse pleuvoir sur vous la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Vous avez labouré la méchanceté, et vous avez moissonné la perversité; vous avez mangé le fruit du mensonge, parce que tu as eu confiance en tes voies, à cause de la multitude de tes hommes forts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'C’est pourquoi un tumulte s’élèvera parmi ton peuple, et on saccagera toutes tes forteresses, comme Salman saccagea Beth-Abel au jour de la bataille, où la mère fut écrasée sur les enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Béthel vous fera de même, à cause de la malice de votre méchanceté; le Roi d’Israël sera entièrement exterminé au point du jour. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Quand Israël était jeune enfant, je l’ai aimé, et j’ai appelé mon fils hors d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Lorsqu’on les appelait, ils s’en sont allés de devant ceux qui les appelaient; ils ont sacrifié aux Bahalins, et ont fait des encensements aux images taillées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Et j’ai appris à Ephraïm à marcher; on l’a porté sur les bras, et ils n’ont point connu que je les avais guéris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Je les ai tirés avec des cordeaux d’humanité, et avec des liens d’amitié; et je leur ai été comme ceux qui enlèveraient le joug de dessus leur cou, et j’ai fait approcher de lui la viande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Il ne retournera point au pays d’Egypte; mais le Roi d’Assyrie sera son Roi, parce qu’ils n’ont point voulu se convertir à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'L’épée s’arrêtera dans ses villes, et consumera ses forces, et les dévorera, à cause de leurs conseils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Et mon peuple pend attaché à sa rébellion contre moi; et on le rappelle au Souverain, mais pas un d’eux ne l’exalte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Comment te mettrais-je, Ephraïm? Comment te livrerais-je, Israël? comment te mettrais-je comme j’ai mis Adama, et te ferais-je tel que Tséboïm? Mon coeur est agité dans moi, mes compassions se sont toutes ensemble échauffées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Je n’exécuterai point l’ardeur de ma colère, je ne retournerai point à détruire Ephraïm; car je suis le Dieu Fort, et non pas un homme; je suis le Saint au milieu de toi, et je n’entrerai point dans la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Ils marcheront après l’Eternel; il rugira comme un lion; et quand il rugira, les enfants accourront de l’Occident en hâte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Ils accourront en hâte hors d’Egypte, comme des oiseaux; et hors du pays d’Assyrie, comme des pigeons, et je les ferai habiter dans leurs maisons, dit l’Eternel. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Ephraïm m’a abordé avec des mensonges, et la maison d’Israël avec des tromperies, lorsque Juda dominait encore avec le Dieu Fort, et qu’il était fidèle avec les Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Ephraïm se repaît de vent, et va après le vent d’Orient; il multiplie tous les jours ses mensonges et le dégât, et ils traitent alliance avec l’Assyrie, et l’on porte des huiles de senteur en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'L’Eternel a aussi un procès avec Juda, et il visitera Jacob selon son train, il lui rendra selon ses oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Dès le ventre il supplanta son frère, puis par sa force il fut vainqueur en luttant avec Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Il fut vainqueur en luttant avec l’Ange, et fut le plus fort; il pleura, et lui demanda grâce; il le trouva à Béthel, et là Dieu parla avec nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Or l’Eternel est le Dieu des armées; son mémorial, c’est L’ Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Toi donc retourne-toi à ton Dieu; garde la miséricorde et le jugement, et aie continuellement espérance en ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Ephraïm est un marchand; il y a en sa main des balances trompeuses; il aime à faire des extorsions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Et Ephraïm a dit: Quoi qu’il en soit, je suis devenu riche; je me suis acquis des richesses; pas un de mes travaux ne feront trouver en moi une iniquité qui soit un péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Et moi je suis l’Eternel ton Dieu dès le pays d’Egypte; je te ferai encore habiter dans des tentes, comme aux jours de fête solennelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Je parlerai par les Prophètes, et multiplierai les visions, et je proposerai des similitudes par le moyen des Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Certainement Galaad n’est qu’iniquité, certainement ils ne sont que vanité; ils ont sacrifié des boeufs en Guilgal; même leurs autels sont comme des monceaux sur les sillons des champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Or Jacob s’enfuit au pays de Syrie, et Israël servit pour une femme, et pour une femme il garda le bétail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Puis l’Eternel fit remonter Israël hors d’Egypte par le Prophète, et il fut gardé par le Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 15, 'Mais Ephraïm a provoqué Dieu à une amère indignation, c’est pourquoi on répandra son sang sur lui, et son Seigneur lui rendra son opprobre. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Si-tôt qu’Ephraïm eut parlé, on trembla; il avait élevé le Royaume en Israël, mais il s’est rendu coupable par Bahal, et il est mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Et maintenant ils continuent à pécher, et ils se sont fait de leur argent une image de fonte, selon leur intelligence, des idoles qui ne sont qu’ouvrage d’ouvriers, mais desquelles pourtant ils disent aux hommes qui sacrifient: qu’on baise les veaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'C’est pourquoi ils seront comme la nuée du matin, et comme la rosée du matin, laquelle s’en va; comme la balle qui est emportée hors de l’aire par le tourbillon; et comme la fumée sortant de la cheminée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Et moi je suis l’Eternel ton Dieu dès le pays d Egypte, et tu ne devrais reconnaître d’autre dieu que moi; aussi il n’y a point de Sauveur que moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Je t’ai connu au désert, en une terre aride.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Ils ont été rassasiés selon l’abondance de leurs pâturages, ils ont été rassasiés, et leur coeur s’est élevé; et ils m’ont oublié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Je leur ai donc été comme un grand lion; et je les ai épiés sur le chemin comme un léopard.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Je les rencontrerai comme une ourse à qui on a ôté ses petits, et je déchirerai la taie de leur coeur, et là je les dévorerai comme un vieux lion; la bête des champs les déchirera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'On t’a perdu, ô Israël! mais en moi réside ton secours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Serai-je ton Roi? Où est-il ton roi? et qu’il te délivre en toutes tes villes; où sont tes Gouverneurs, desquels tu as dit: Donne-moi un Roi, et des Seigneurs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Je t’ai donné un Roi en ma colère, et je l’ôterai en ma fureur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'L’iniquité d’Ephraïm est liée, et son péché est serré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Les douleurs comme de celle qui enfante le surprendront; c’est un enfant qui n’est pas sage, car il ne se tient pas à temps à la brèche des enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Je les eusse rachetés de la puissance du sépulcre, et les eusse garantis de la mort; j’eusse été tes pestes, ô mort! et ta destruction, ô sépulcre! mais la repentance est cachée loin de mes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Quand il aura fructifié entre ses frères, le vent Oriental, le vent de l’Eternel montant du désert, viendra, et ses sources sécheront, et sa fontaine tarira, et on pillera le trésor de toutes les choses désirables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Samarie sera désolée, car elle s’est rebellée contre son Dieu; ils tomberont par l’épée, leurs petits enfants seront écrasés, et on fendra le ventre de leurs femmes enceintes. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Israël, retourne-toi jusqu’à l’Eternel ton Dieu; car tu es tombé par ton iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Prenez avec vous ce que vous avez à dire, et retournez-vous à l’Eternel, et lui dites: Ote toute l’iniquité, et prends le bien, pour le mettre en sa place, et nous te rendrons les bouveaux de nos lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'L’Assyrie ne nous délivrera pas; nous ne monterons plus sur des chevaux, et nous ne dirons plus à l’ouvrage de nos mains: Vous êtes nos dieux; car l’orphelin trouve compassion devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Je guérirai leur rébellion, et les aimerai volontairement; parce que ma colère est détournée d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Je serai comme une rosée à Israël; il fleurira comme le lis, et jettera ses racines comme les arbres du Liban.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Ses branches s’avanceront, et sa magnificence sera comme celle de l’olivier, et son odeur comme celle du Liban.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Ils retourneront pour se tenir assis sous son ombre, et ils foisonneront comme le froment, et fleuriront comme la vigne, et l’odeur de chacun d’eux sera comme celle du vin du Liban.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Ephraïm dira: Qu’ai-je plus à faire avec les faux dieux? Je l’exaucerai, et le regarderai; je lui serai comme le sapin vert, ton fruit procédera de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Qui est celui qui est sage? qu’il entende ces choses; et qui est celui qui est prudent? qu’il les connaisse; car les voies de l’Eternel sont droites; aussi les justes y marcheront, mais les rebelles y tomberont. Retournez au Début This Website is Hosted by../../lilacsandbutterflies/images/EClilacsbanner.gif ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'La parole de l’Eternel qui fut adressée à Joël, fils de Péthuel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Anciens, écoutez ceci, et vous, tous les habitants du pays, prêtez l’oreille. Est-il arrivé de votre temps, ou même du temps de vos pères, une chose comme celle-ci?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Faites-en le récit à vos enfants, et que vos enfants le fassent à leurs enfants, et leurs enfants à une autre génération.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'La sauterelle a brouté les restes du hanneton, et le hurebec a brouté les restes de la sauterelle, et le vermisseau a brouté les restes du hurebec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Ivrognes, réveillez-vous, et pleurez; et vous tous buveurs de vin hurlez à cause du vin nouveau, parce qu’il est retranché à votre bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Car une nation puissante et innombrable est montée contre mon pays; ses dents sont des dents de lion, et elle a les dents mâchelières d’un vieux lion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Elle a réduit ma vigne en désert, et a ôté l’écorce de mes figuiers; elle les a entièrement dépouillés, et les a abattus, leurs branches en sont devenues blanches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Lamente-toi comme une jeune femme qui se serait ceinte d’un sac, à cause de la mort du mari de sa jeunesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Le gâteau et l’aspersion sont retranchés de la maison de l’Eternel, et les Sacrificateurs qui font le service de l’Eternel mènent deuil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Les champs sont ravagés, la terre mène deuil parce que le froment est ravagé, que le vin doux est tari, et que l’huile manque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Laboureurs soyez confus; vignerons hurlez à cause du froment et de l’orge; car la moisson des champs est périe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Les vignes sont sans fruit, et les figuiers ont manqué; les grenadiers, et les palmiers, les pommiers et tous les arbres des champs ont séché, c’est pourquoi la joie a cessé entre les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Sacrificateurs ceignez-vous, et lamentez; vous qui faites le service de l’autel, hurlez, vous qui faites le service de mon Dieu entrez, passez la nuit vêtus de sacs, car il est défendu au gâteau et à l’aspersion d’entrer en la maison de votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Sanctifiez le jeûne, publiez l’assemblée solennelle, assemblez les anciens, et tous les habitants du pays en la maison de l’Eternel votre Dieu, et criez à l’Eternel; en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Hélas, quelle journée! car la journée de l’Eternel est proche, et elle viendra comme un dégât fait par le Tout-puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Les vivres ne sont-ils pas retranchés de devant nos yeux; et la joie et l’allégresse, de la maison de notre Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Les grains sont pourris sous leurs mottes, les greniers sont désolés, c’en est fait des granges, parce que le froment a manqué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Ô combien ont gémi les bêtes, et dans quelle peine ont été les troupeaux de boeufs, parce qu’ils n’ont point de pâturage! Aussi les troupeaux de brebis sont désolés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Eternel, je crierai à toi, car le feu a consumé les cabanes du désert, et la flamme a brûlé tous les arbres des champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Même toutes les bêtes des champs crient à toi, parce que les cours des eaux sont taris, et que le feu a consumé les cabanes du désert. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Sonnez du cor en Sion, et sonnez avec un retentissement bruyant en la montagne de ma sainteté; que tous les habitants du pays tremblent; car la journée de l’Eternel vient; car elle est proche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Journée de ténèbres et d’obscurité; journée de nuées et de brouillards. Comme l’aube du jour s’étend sur les montagnes, ainsi s’étend un peuple grand et puissant, auquel il n’ y a point eu de semblable de tout temps, et après lequel il n’y en aura point de semblable dans la suite des siècles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Le feu dévore devant sa face, et derrière lui la flamme brûle; le pays était avant sa venue comme le jardin d’Héden; et après qu’il sera parti il sera comme un désert de désolation; et même il n’y aura rien qui lui échappe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'C’est, à le voir, comme si on voyait des chevaux, et ils courront comme des gens de cheval;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Et ils sauteront menant un bruit semblable à celui des chariots sur les sommets des montagnes, et au bruit d’une flamme de feu, qui dévore du chaume; et ils seront comme un peuple puissant rangé en bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Les peuples trembleront en le voyant; tous les visages en deviendront pâles et livides.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Ils courront comme des gens vaillants, et monteront sur la muraille comme des gens de guerre; ils marcheront chacun en son rang, et ne se détourneront point de leurs chemins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'L’un ne pressera point l’autre, mais chacun marchera dans son chemin, ils se jetteront au travers des épées, et ne seront point blessés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Ils iront çà et là par la ville, ils courront sur la muraille, ils monteront sur les maisons, ils entreront par les fenêtres comme le larron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'La terre tremblera devant lui, les cieux seront ébranlés, le soleil et la lune seront obscurcis, et les étoiles retireront leur lueur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Aussi l’Eternel fera entendre sa voix devant son armée, parce que son camp sera très-grand; car l’exécuteur de sa parole sera puissant; certainement la journée de l’Eternel est grande et terrible; et qui la pourra soutenir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Maintenant donc aussi, dit l’Eternel, retournez-vous jusqu’à moi de tout votre coeur, avec jeûne, avec larmes, et lamentation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Et déchirez vos coeurs, et non pas vos vêtements, et retournez à l’Eternel votre Dieu; car il est miséricordieux et pitoyable, tardif à colère, et abondant en miséricorde, et qui se repent d’avoir affligé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Qui sait si l’Eternel votre Dieu ne viendra point à se repentir, et s’il ne laissera point après soi bénédiction, gâteau, et aspersion?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Sonnez du cor en Sion, sanctifiez le jeûne, publiez l’assemblée solennelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Assemblez le peuple, sanctifiez la congrégation, amassez les anciens, assemblez les enfants, et ceux qui sucent les mamelles; que le nouveau marié sorte de son cabinet, et la nouvelle mariée de sa chambre nuptiale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Que les Sacrificateurs qui font le service de l’Eternel pleurent entre le porche et l’autel, et qu’ils disent: Eternel, pardonne à ton peuple, et n’expose point ton héritage à l’opprobre, tellement que les nations en fassent le sujet de leurs railleries. Pourquoi dirait-on entre les peuples: Où est leur Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Or l’Eternel a été jaloux de sa terre, et il a été ému de compassion envers son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Et l’Eternel a répondu et a dit à son peuple: Voici, je vous enverrai du froment, du bon vin, et de l’huile, et vous en serez rassasiés, et je ne vous exposerai plus à l’opprobre entre les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'J’éloignerai de vous l’armée venue du Septentrion, et je la pousserai en un pays sec et désolé; la partie antérieure vers la mer Orientale; et celle de derrière, vers la mer Occidentale; sa puanteur montera, et son infection s’élèvera, après avoir fait de grandes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Ne crains point, terre; égaye-toi et te réjouis; car l’Eternel a fait de grandes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Ne craignez point, bêtes des champs, car les pâturages du désert ont poussé leur jet, et même les arbres ont pousse leur fruit; le figuier et la vigne ont poussé avec vigueur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Et vous enfants de Sion égayez-vous, et vous réjouissez en l’Eternel votre Dieu; car il vous a donné la pluie selon la justice, et même il a fait couler sur vous la pluie de la première saison, et celle de la dernière, au premier mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'Et les aires seront remplies de froment, et les cuves regorgeront de moût et d’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'Ainsi je vous rendrai les fruits des années que la sauterelle, le hurebec, le vermisseau, et le hanneton, ma grande armée, que j’avais envoyée contre vous, avait broutés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Vous aurez donc abondamment de quoi manger et être rassasiés; et vous louerez le nom de l’Eternel votre Dieu, qui vous aura fait des choses merveilleuses; et mon peuple ne sera point confus à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Et vous saurez que je suis au milieu d’Israël, et que je suis l’Eternel votre Dieu, et qu’il n’y en a point d’autre; et mon peuple ne sera point confus à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'Et il arrivera après ces choses que je répandrai mon Esprit sur toute chair; et vos fils et vos filles prophétiseront; vos vieillards songeront des songes, et vos jeunes gens verront des visions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'Et même en ces jours-là je répandrai mon Esprit sur les serviteurs et sur les servantes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'Et je ferai des prodiges dans les cieux et sur la terre, du sang et du feu, et des colonnes de fumée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'Le soleil sera changé en ténèbres et la lune en sang, avant que le jour grand et terrible de l’Eternel vienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'Et il arrivera que quiconque invoquera le Nom de l’Eternel sera sauvé; car le salut sera en la montagne de Sion, et dans Jérusalem, comme l’Eternel a dit, et dans les résidus que l’Eternel aura appelés. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Car voici, en ces jours-là et en ce temps-là auquel je ferai retourner ceux qui auront été emmenés captifs de Juda et de Jérusalem,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'J’assemblerai toutes les nations, et les ferai descendre en la vallée de Josaphat, et là j’entrerai en jugement avec eux, à cause de mon peuple, et de mon héritage d’Israël, lequel ils ont dispersé parmi les nations, et parce qu’ils ont partagé entre eux mon pays;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Et qu’ils ont jeté le sort sur mon peuple; et qu’ils ont donné un enfant pour une prostituée, et ont vendu la jeune fille pour du vin, qu’ils ont bu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Et qu’ai-je aussi affaire de vous, Tyr et Sidon, et de vous, toutes les limites de la Palestine, me rendrez-vous ma récompense, ou me voulez-vous irriter? Je vous rendrai promptement et sans délai votre récompense sur votre tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Car vous avez pris mon argent et mon or, et avez emporté dans vos temples mes choses les plus précieuses, et les meilleures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'Et vous avez vendu les enfants de Juda, et les enfants de Jérusalem aux enfants des Grecs, afin de les éloigner de leur contrée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Voici, je les ferai lever du lieu auquel ils ont été transportés après que vous les avez vendus; et je ferai retourner votre récompense sur votre tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'Je vendrai donc vos fils et vos filles entre les mains des enfants de Juda, et ils les vendront à ceux de Séba, qui les transporteront vers une nation éloignée; car l’Eternel a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Publiez ceci parmi les nations: Préparez la guerre; réveillez les hommes forts, que tous les gens de guerre s’approchent, et qu’ils montent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Forgez des épées de vos hoyaux, et des javelines de vos serpes; et que le faible dise: Je suis fort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Amassez-vous, et venez, toutes nations d’alentour, et soyez assemblées; l’Eternel abattra là tes hommes forts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Que les nations se réveillent, et qu’elles montent à la vallée de Josaphat; car je serai assis là pour juger toutes les nations d’alentour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Mettez la faucille, car la moisson est mûre; venez, et descendez, car le pressoir est plein: les cuves regorgent, car leur malice est grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Peuples, peuples, à la vallée de décision; car la journée de l’Eternel est proche dans la vallée de décision.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'Le soleil et la lune ont été obscurcis, et les étoiles ont retiré leur lueur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'Et l’Eternel rugira de Sion, et fera ouïr sa voix de Jérusalem, et les Cieux et la terre seront ébranlés, et l’Eternel sera un asile à son peuple, et la force des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'Et vous saurez que je suis l’Eternel votre Dieu, qui habite en Sion, la montagne de ma sainteté; et Jérusalem ne sera que sainteté, et les étrangers n’y passeront plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'Et il arrivera en ce jour-là que les montagnes distilleront le moût, et que les coteaux se fondront en lait, les eaux courront dans tous les ruisseaux de Juda, et il sortira une fontaine de la maison de l’Eternel, et elle arrosera la vallée de Sittim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'L’Egypte sera en désolation, et l’Idumée en désert de désolation, à cause de la violence faite aux enfants de Juda, desquels ils ont répandu le sang innocent dans leur pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Mais la Judée sera habitée éternellement, et Jérusalem d’âge en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'Et je nettoierai leur sang que je n’avais point nettoyé; car l’Eternel habite en Sion. Retournez au Début ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Les paroles d’Amos, qui était d’entre les bergers de Tékoah, lesquelles il entendit dans une vision touchant Israël, du temps d’Hozias Roi de Juda, et de Jéroboam fils de Joas, Roi d’Israël, deux ans avant le tremblement de terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Il dit donc: L’Eternel rugira de Sion, et fera ouïr sa voix de Jérusalem, et les cabanes des bergers lamenteront, et le sommet de Carmel séchera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Ainsi a dit l’Eternel: à cause de trois crimes de Damas, même à cause de quatre, je ne rappellerai point cela, mais je le ferai parce qu’ils ont froissé Galaad avec des herses de fer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Et j’enverrai le feu à la maison de Hazaël, et il dévorera le palais de Benhadad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Je briserai aussi la barre de Damas, et j’exterminerai de Bikhath-aven ses habitants, et de la maison d’Héden celui qui y tient le sceptre; et le peuple de Syrie sera transporté à Kir, a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Ainsi a dit l’Eternel: à cause de trois crimes de Gaza, même à cause de quatre, je ne rappellerai point cela; mais je le ferai parce qu’ils ont transporté ceux de Juda en une captivité entière, jusqu’à les livrer à Edom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Et j’enverrai le feu à la muraille de Gaza, et il dévorera ses palais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Et j’exterminerai d’Asdod ses habitants, et d’Askélon celui qui y tient le sceptre; puis je tournerai ma main sur Hékron, et le reste des Philistins périra, a dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Ainsi a dit l’Eternel: à cause de trois crimes de Tyr, même à cause de quatre, je ne rappellerai point cela, mais je le ferai parce qu’ils ont livré ceux de Juda en une captivité entière à Edom, et ne se sont point souvenus de l’alliance fraternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Et j’enverrai le feu à la muraille de Tyr, et il dévorera ses palais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Ainsi a dit l’Eternel: à cause de trois crimes d’Edom, même à cause de quatre, je ne rappellerai point cela; mais je le ferai parce qu’il a poursuivi son frère avec l’épée, et qu’il a altéré ses compassions, et que sa colère déchire continuellement, et qu’il garde sa fureur à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Et j’enverrai le feu en Téman, et il dévorera les palais de Botsra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Ainsi a dit l’Eternel: à cause de trois crimes des enfants de Hammon, même à cause de quatre, je ne rappellerai point cela; mais je le ferai parce que pour élargir leurs bornes ils ont fendu en Galaad le ventre des femmes enceintes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Et j’allumerai le feu, avec alarme au jour de la bataille, avec tourbillon au jour de la tempête, en la muraille de Rabba, et il dévorera ses palais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'Et leur Roi ira en captivité, et avec lui les principaux de son pays, a dit l’Eternel. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Ainsi a dit l’Eternel: à cause de trois crimes de Moab, même à cause de quatre, je ne rappellerai point cela; mais je le ferai parce qu’il a brûlé les os du Roi d’Edom, jusqu’à les calciner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Et j’enverrai le feu en Moab, et il dévorera les palais de Kérijoth; et Moab mourra dans le tumulte, dans l’alarme, et au bruit du cor.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Et j’exterminerai les Gouverneurs du milieu de son pays; et je tuerai ensemble avec lui tous les principaux du pays, a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Ainsi a dit l’Eternel: à cause de trois crimes de Juda, même à cause de quatre, je ne rappellerai point cela; mais je le ferai parce qu’ils ont rejeté la Loi de l’Eternel, et n’ont point gardé ses statuts; mais leurs mensonges, lesquels leurs pères avaient suivis, les ont fait égarer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Et j’enverrai le feu en Juda, et il dévorera les palais de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Ainsi a dit l’Eternel: à cause de trois crimes d’Israël, même à cause de quatre, je ne rappellerai point cela; mais je le ferai parce qu’ils ont vendu le juste pour de l’argent, et le pauvre pour une paire de souliers;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'Soupirant après la poussière de la terre pour la jeter sur la tête des chétifs; et ils pervertissent la voie des débonnaires; et le fils et le père s’en vont à une même jeune fille, pour profaner le Nom de ma sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Et se couchent près de tout autel, sur les vêtements qu’ils ont pris en gage, et boivent dans la maison de leurs dieux le vin des condamnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'J’ai pourtant détruit devant eux l’Amorrhéen, dont la hauteur était comme la hauteur des cèdres, et qui était fort comme les chênes; et j’ai ruiné son fruit par-dessus, et ses racines par-dessous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Je vous ai aussi tirés du pays d’Egypte, et je vous ai conduits par le désert durant quarante ans, afin que vous possédassiez le pays de l’Amorrhéen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Davantage, j’ai suscité quelques-uns d’entre vos fils pour être Prophètes, et quelques-uns d’entre vos jeunes gens pour être Nazariens; n’est-il pas ainsi, enfants d’Israël; dit l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Mais vous avez fait boire du vin aux Nazariens, et vous avez commandé aux Prophètes, et leur avez dit: Ne prophétisez plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Voici, je m’en vais fouler le lieu où vous habitez, comme un chariot plein de gerbes foule tout par où il passe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Tellement que l’homme léger ne pourra point fuir, et le fort ne pourra pas faire usage de sa vigueur, et le vaillant ne sauvera point sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'Et celui qui manie l’arc, ne pourra point demeurer ferme; et celui qui est léger à la course n’échappera point; et l’homme de cheval ne sauvera point sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'Et le plus courageux entre les hommes forts s’enfuira tout nu en ce jour- là, dit l’Eternel. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Enfants d’Israël, écoutez la parole que l’Eternel a prononcée contre vous, contre toutes les familles, dis-je, que j’ai tirées du pays d’Egypte, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Je vous ai connus vous seuls d’entre toutes les familles de la terre; c’est pourquoi je visiterai sur vous toutes vos iniquités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Deux hommes marcheront-ils ensemble, s’ils ne s’en sont accordés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Le lion rugira-t-il dans la forêt, s’il n’a quelque proie? Le lionceau jettera-t-il son cri de son gîte, s’il n’a pris quelque chose?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'L’oiseau tomberait-il dans le filet sur la terre, sans qu’on lui eût tendu des pièges? Lèverait-on le filet de dessus la terre, sans avoir du tout rien pris?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Le cor sonnera-t-il par la ville sans que le peuple en étant tout effrayé s’assemble? ou y aura-t-il dans la ville quelque mal que l’Éternel n’ait fait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Car le Seigneur l’Eternel ne fera aucune chose qu’il n’ait révélé son secret aux Prophètes ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Le lion a rugi, qui ne craindra? Le Seigneur l’Eternel a parlé, qui ne prophétisera?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Faites entendre ceci dans les palais d’Asdod, et dans les palais du pays d’Egypte, et dites: Assemblez-vous sur les montagnes de Samarie, et regardez les grands désordres qui y sont, et ceux auxquels on fait tort au-dedans d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Car ils n’ont point su faire ce qui est juste, dit l’Eternel, amassant la violence et la rapine dans leurs palais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'C’est pourquoi ainsi a dit le Seigneur l’Eternel: L’ennemi viendra, et sera autour du pays, et il t’ôtera ta force, et tes palais seront pillés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Ainsi a dit l’Eternel: comme si un berger sauvait de la gueule d’un lion les deux jarrets, ou le bout d’une oreille, ainsi les enfants d’Israël, qui demeurent en Samarie, seront arrachés du coin du lit, et de leur asile de Damas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Ecoutez, et protestez contre la maison de Jacob, dit le Seigneur l’Eternel, le Dieu des armées;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'qu’au jour que je visiterai les crimes d’Israël sur lui, aussi je ferai visitation sur les autels de Béthel, et les cornes de l’autel seront retranchées, et tomberont par terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Et je frapperai la maison d’hiver et la maison d’été; et les maisons d’ivoire seront détruites, et les grandes maisons prendront fin, dit l’Eternel. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Ecoutez cette parole-ci, vaches de Basan, qui vous tenez dans la montagne de Samarie, qui faites tort aux chétifs, et qui opprimez les pauvres; qui dites à leurs seigneurs: Apportez, et que nous buvions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Le Seigneur l’Eternel a juré par sa sainteté, que voici, les jours viennent sur vous qu’il vous enlèvera sur des boucliers; et ce qui restera de vous, avec des hameçons de pêche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Et vous sortirez dehors par les brèches, chacune devant soi; et vous jetterez là ce que vous avez amassé dans les palais, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Entrez dans Béthel, et y commettez vos crimes; multipliez vos péchés dans Guilgal, et amenez vos sacrifices dès le matin, et vos dîmes au bout de trois ans accomplis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Et faites un parfum de pain levé pour l’oblation d’action de grâces; publiez les oblations volontaires, et faites les savoir; car vous l’aimez ainsi, enfants d’Israël, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'C’est pourquoi aussi, je vous ai envoyé la famine en toutes vos villes, et la disette de pain en toutes vos demeures; mais pour cela vous ne vous êtes point retournés jusqu’à moi, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Je vous ai aussi retenu la pluie, quand il restait encore trois mois jusqu’à la moisson, et j’ai fait pleuvoir sur une ville, et je n’ai point fait pleuvoir sur l’autre; une pièce de terre a été arrosée de pluie, et l’autre pièce, sur laquelle il n’a point plu, est desséchée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Et deux, même trois villes, sont allées vers une ville pour boire de l’eau, et n’ont point été désaltérées, mais pour cela vous ne vous êtes point retournés jusqu’à moi, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Je vous ai frappés de brûlure, et de nielle; et le hanneton a brouté autant de jardins et de vignes, de figuiers et d’oliviers que vous aviez, mais pour cela vous ne vous êtes point retournés jusqu’à moi, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Je vous ai envoyé la mortalité, de la manière que je l’avais envoyée en Egypte, et j’ai fait mourir par l’épée vos gens d’élite, et vos chevaux qui avaient été pris, et j’ai fait monter la puanteur de vos camps même en vos narines, mais pour cela vous ne vous êtes point retournés jusqu’à moi, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'J’en ai renversé d’entre vous en la manière que Dieu renversa Sodome et Gomorrhe, et vous avez été comme un tison arraché du feu, mais pour cela vous ne vous êtes point retournés jusqu’à moi, dit l’Eternel,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'C’est pourquoi je te traiterai ainsi, ô Israël! et parce que je te ferai ceci, prépare-toi à la rencontre de ton Dieu, ô Israël!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Car voici, celui qui a formé les montagnes, et qui a créé le vent, et qui déclare à l’homme quelle est sa pensée, qui fait l’aube et l’obscurité, et qui marche sur les lieux hauts de la terre; l’Eternel Dieu des armées est son Nom. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Ecoutez cette parole, qui est la complainte que je prononce à haute voix touchant vous, maison d’Israël!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Elle est tombée, elle ne se relèvera plus, la vierge d’Israël; elle est abandonnée sur la terre, il n’y a personne qui la relève.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Car ainsi a dit le Seigneur l’Eternel, à la maison d’Israël: La ville de laquelle il en sortait mille, n’en aura de reste que cent; et celle de laquelle il en sortait cent, n’en aura de reste que dix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Car ainsi a dit l’Eternel à la maison d’Israël: Cherchez-moi, et vous vivrez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Et ne cherchez point Béthel, et n’entrez point dans Guilgal, et ne passez point à Béer-Sébah; car Guilgal sera entièrement transportée en captivité, et Béthel sera détruite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Cherchez l’Eternel, et vous vivrez, de peur qu’il ne saisisse la maison de Joseph, comme un feu qui la consumera, sans qu’il y ait personne qui l’éteigne à Béthel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Parce qu’ils changent le jugement en absinthe, et qu’ils renversent la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Cherchez celui qui a fait la Poussinière et l’Orion, qui change les plus noires ténèbres en aube du jour, et qui fait devenir le jour obscur comme la nuit; qui appelle les eaux de la mer, et les répand sur le dessus de la terre, le nom duquel est l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Qui renforce le fourrageur par-dessus l’homme fort, tellement que le fourrageur entrera dans la forteresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Ils haïssent à la porte ceux qui les reprennent, et ils ont en abomination celui qui parle en intégrité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'C’est pourquoi à cause que vous opprimez le pauvre, et lui enlevez la charge de froment, vous avez bâti des maisons de pierre de taille; mais vous n’y habiterez point; vous avez planté des vignes bonnes à souhait; mais vous n’en boirez point le vin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Car j’ai connu vos crimes, ils sont en grand nombre, et vos péchés se sont multipliés: vous êtes des oppresseurs du juste, et des preneurs de rançon, et vous pervertissez à la porte le droit des pauvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'C’est pourquoi l’homme prudent se tiendra dans le silence en ce temps-là; car le temps est mauvais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Cherchez le bien, et non pas le mal, afin que vous viviez; et ainsi l’Eternel, le Dieu des armées, sera avec vous, comme vous l’avez dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Haïssez le mal, et aimez le bien, et établissez le jugement à la porte; l’Eternel le Dieu des armées, aura peut-être pitié du reste de Joseph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'C’est pourquoi l’Eternel le Dieu des armées, le Seigneur dit ainsi; Il y aura lamentation par toutes les places, et on criera par toutes les rues Hélas! Hélas! Et on appellera au deuil le laboureur, et à la lamentation ceux qui en savent le métier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Et il y aura lamentation par toutes les vignes; car je passerai tout au travers de toi, a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Malheur à vous qui désirez le jour de l’Eternel; De quoi vous servira le jour de l’Eternel? Ce sont des ténèbres, et non pas une lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'C’est comme si un homme s’enfuyait de devant un lion, et qu’un ours le rencontrât, ou qu’il entrât en la maison, et appuyât sa main sur la paroi, et qu’un serpent le mordît.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Le jour de l’Eternel ne sont-ce pas des ténèbres, et non une lumière? Et l’obscurité n’est-elle point en lui, et non la clarté?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Je hais et rejette vos fêtes solennelles, et je ne flairerai point l’odeur de vos parfums dans vos assemblées solennelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Que si vous m’offrez des holocaustes et des gâteaux, je ne les accepterai point; et je ne regarderai point les oblations de prospérités que vous ferez de vos bêtes grasses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Ote de devant moi le bruit de tes chansons, car je n’écouterai point la mélodie de tes musettes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Mais le jugement roulera comme de l’eau, et la justice comme un torrent impétueux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Est-ce à moi, maison d’Israël, que vous avez offert des sacrifices et des gâteaux dans le désert pendant quarante ans?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Au contraire vous avez porté le tabernacle de votre Moloc, et Kijun vos images, et l’étoile de vos dieux, que vous vous êtes faits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'C’est pourquoi je vous transporterai au-delà de Damas, a dit l’Eternel, duquel le nom est le Dieu des armées. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Hola! vous qui êtes à votre aise en Sion, et vous qui vous confiez en la montagne de Samarie, lieux les plus renommés d’entre les principaux des nations, auxquels va la maison d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Passez jusqu’à Calne, et regardez; et vous en allez de là à Hamath la grande; puis descendez à Gath des Philistins; n’étaient-ils pas plus excellents que ces Royaumes-ci? Leur pays n’était-il pas plus étendu que votre pays?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Vous qui éloignez les jours de la calamité, et qui approchez de vous le siège de violence;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Qui vous couchez sur des lits d’ivoire, et vous étendez sur vos couches; qui mangez les agneaux choisis du troupeau, et les veaux pris du lieu où on les engraisse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Qui fredonnez au son de la musette; qui inventez des instruments de musique, comme David;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Qui buvez le vin dans des bassins, et vous parfumez des parfums les plus exquis, et qui n’êtes point malades pour la plaie de Joseph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'A cause de cela ils s’en iront incessamment en captivité, entre les premiers qui s’en iront en captivité, et le luxe de ces personnes voluptueuses prendra fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Le Seigneur l’Eternel a juré par soi-même, l’Eternel Dieu des armées dit ainsi: J’ai en détestation l’orgueil de Jacob, et j’ai en haine ses palais, c’est pourquoi je livrerai la ville, et tout ce qui est en elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Et s’il arrive qu’il y ait dix hommes de reste dans une maison, ils mourront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Et l’oncle de chacun d’eux les prendra, et les brûlera pour en mettre les os hors de la maison; et il dira à celui qui sera au fond de la maison: y a-t-il encore quelqu’un avec toi? Et il répondra: C’en est la fin. Puis son oncle lui dira: Tais-toi; car aussi ils n’eussent point fait commémoration du nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Car voici l’Eternel commande, et il frappera les grandes maisons par des débordements d’eau, et les petites maisons par des fentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Les chevaux courront-ils par les rochers? ou y labourera-t-on avec des boeufs? mais vous avez changé le jugement en fiel, et le fruit de la justice en absinthe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Vous vous réjouissez en des choses de néant, et vous dites: Ne nous sommes-nous pas acquis de l’élévation par notre force?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Mais, ô maison d’Israël! voici, j’élèverai contre vous une nation, dit l’Eternel le Dieu des armées, laquelle vous opprimera depuis l’entrée de Hamath jusqu’au torrent du désert. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Le Seigneur l’Eternel me fit voir cette vision, et voici, il formait des sauterelles au commencement que le regain croissait; et voici, c’était le regain d’après les fenaisons du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Et quand elles eurent achevé de manger l’herbe de la terre, alors je dis: Seigneur Eternel, sois propice, je te prie; Comment se relèverait Jacob? car il est petit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Et l’Eternel se repentit de cela. Cela n’arrivera point, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Puis le Seigneur l’Eternel me fit voir cette vision: et voici, le Seigneur l’Eternel criait tout haut, qu’on fît jugement par feu; et le feu dévora un grand abîme, et il dévora aussi une pièce de terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Et je dis: Seigneur Eternel! cesse, je te prie; comment se relèverait Jacob? car il est petit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Et l’Eternel se repentit de cela. Cela aussi n’arrivera point, dit le Seigneur l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Puis il me fit voir cette vision: et voici, le Seigneur se tenait debout sur un mur fait au niveau, et il avait en sa main un niveau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Et l’Eternel me dit: Que vois-tu, Amos? Et je répondis: Un niveau. Et le Seigneur me dit: Voici, je m’en vais mettre le niveau au milieu de mon peuple d’Israël, et je ne lui en passerai plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Et les hauts lieux d’Isaac seront désolés, et les sanctuaires d’Israël seront détruits; et je me dresserai contre la maison de Jéroboam avec l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Alors Amatsia, Sacrificateur de Béthel, envoya dire à Jéroboam Roi d’Israël: Amos a conspiré contre toi au milieu de la maison d’Israël; le pays ne pourrait pas porter toutes ses paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Car ainsi a dit Amos: Jéroboam mourra par l’épée, et Israël ne manquera point d’être transporté hors de sa terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Puis Amatsia dit à Amos: Voyant, va, et t’enfuis au pays de Juda, et mange là ton pain, et y prophétise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Mais ne continue plus de prophétiser à Béthel; car c’est le sanctuaire du Roi, et c’est la maison du Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Et Amos répondit, et dit à Amatsia: Je n’étais ni Prophète, ni fils de Prophète; mais j’étais un bouvier, et je cueillais des figues sauvages;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Et l’Eternel me prit d’après le troupeau, et l’Eternel me dit: Va, prophétise à mon peuple d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Ecoute donc maintenant la parole de l’Eternel; Tu me dis: Ne prophétise plus contre Israël, et ne fais plus dégoutter la parole contre la maison d’Isaac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'C’est pourquoi ainsi a dit l’Eternel: Ta femme se prostituera dans la ville, et tes fils et tes filles tomberont par l’épée, et ta terre sera partagée au cordeau, et tu mourras en une terre souillée, et Israël ne manquera point d’être transporté hors de sa terre. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Le Seigneur l’Eternel me fit voir cette vision, et voici, un panier de fruits d’Eté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Et il dit: Que vois-tu, Amos? Et je répondis: Un panier de fruits d’Eté. Et l’Eternel me dit: La fin est venue sur mon peuple d’Israël, je ne lui en passerai plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Les cantiques du Temple seront des hurlements en ce temps-là, dit le Seigneur l’Eternel. Il y aura grand nombre de corps morts que l’on jettera en tous lieux en silence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Ecoutez ceci vous qui engloutissez les pauvres, même jusqu’à désoler les affligés du pays;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Et qui dites: Quand sera passé ce mois? et nous débiterons le blé; et quand sera passé ce sabbat? et nous mettrons en vente le froment, en faisant l’épha plus petit, augmentant le sicle, et falsifiant les balances pour tromper.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'Afin que nous acquérions les chétifs par argent, et le pauvre pour une paire de souliers, et que nous débitions les criblures du froment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'L’Eternel a juré par la magnificence de Jacob: Si j’oublie jamais aucune de leurs actions!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'La terre ne sera-t-elle point émue d’une telle chose, et tous ses habitants ne lamenteront-ils point? Ne s’écoulera-t-elle pas toute comme un fleuve, et ne sera-t-elle pas emportée et submergée comme par le fleuve d’Egypte?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'Et il arrivera en ce jour-là, dit le Seigneur l’Eternel, que je ferai coucher le soleil en plein Midi, et que je ferai venir les ténèbres sur la terre en un jour serein.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Je changerai vos fêtes solennelles en deuil, et tous vos cantiques en lamentation; je mettrai le sac sur tous les reins, et je rendrai chauves toutes les têtes; et je mettrai le pays en une telle lamentation, que celle d’un fils unique; et sa fin sera telle que d’un jour amer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Voici, les jours viennent, dit le Seigneur l’Eternel, que j’enverrai la famine sur le pays, non la famine du pain, ni la soif de l’eau, mais la famine d’ouïr les paroles de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Ils courront depuis une mer jusqu’à l’autre, et ils iront de tous côtés depuis l’Aquilon jusqu’à l’Orient, pour chercher la parole de l’Eternel; mais ils ne la trouveront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'En ce jour-là, pâmeront de soif les belles vierges et les jeunes hommes,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'qui jurent par le délit de Samarie, et disent: ô Dan! Ton Dieu est vivant: et, vive la voie de Béersébah; ils tomberont donc, et ne se relèveront plus. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Je vis le Seigneur se tenant debout sur l’autel, et disant: Frappe le linteau de la porte, et que les poteaux soient ébranlés; et blesse-les tous à la tête, et je tuerai par l’épée ce qui sera resté d’eux; celui d’entre eux qui s’enfuyait ne s’enfuira point; et celui d’entre eux qui échappait, ne réchappera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Quand ils auraient creusé jusqu’aux lieux les plus bas de la terre, ma main les enlèvera de là; quand ils monteraient jusqu’aux cieux, je les en ferai descendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'Et quand ils se seraient cachés au sommet de Carmel, je les y rechercherai et les enlèverai de là; et quand ils se seraient cachés de devant mes yeux au fond de la mer, je commanderai au serpent de les y mordre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Et lorsqu’ils s’en iront en captivité devant leurs ennemis, je commanderai à l’épée qu’elle les y tue; je mettrai mes yeux sur eux pour leur faire du mal, et non pas pour leur faire du bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Car c’est le Seigneur l’Eternel des armées qui touche la terre, et elle se fond, et tous ceux qui l’habitent mènent deuil, et elle s’écoule toute comme un fleuve, et est submergée comme par le fleuve d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Qui a bâti ses étages dans les cieux, et qui a établi ses armées sur la terre; qui appelle les eaux de la mer, et qui les répand sur le dessus de la terre; son nom est l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Ne m’êtes-vous pas comme les enfants des Cusiens, vous, enfants d’Israël? dit l’Eternel. N’ai-je pas fait monter Israël du pays d’Egypte, et les Philistins de Caphtor, et les Syriens de Kir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Voici, les yeux du Seigneur l’Eternel sont sur le Royaume pécheur, et je l’abolirai de dessus la terre; mais pourtant je n’abolirai point entièrement la maison de Jacob, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Car voici je commanderai, et je ferai errer la maison d’Israël parmi toutes les nations, comme on fait promener le grain dans le crible, sans qu’il en tombe un grain en terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Tous les pécheurs de mon peuple mourront par l’épée, eux qui disent: Le mal n’approchera point de nous et ne nous préviendra point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'En ce temps-là je relèverai le Tabernacle de David qui sera tombé, et je réparerai ses brèches, et je refermerai ses ouvertures; je le rebâtirai comme il était aux jours anciens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'Afin qu’ils possèdent le reste de l’Idumée, et toutes les nations sur lesquelles mon Nom sera invoqué; dit l’Eternel, qui fait cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Voici, les jours viennent, dit l’Eternel, que le laboureur atteindra le moissonneur, et que celui qui foule les raisins atteindra celui qui jette la semence; et les montagnes distilleront le moût, et tous les coteaux en découleront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Et je ramènerai de la captivité ceux de mon peuple d’Israël qui auront été emmenés captifs, et on rebâtira les villes désertes, et on y habitera; ils planteront des vignes, et ils en boiront le vin; ils feront aussi des jardins, et ils en mangeront les fruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Je les planterai sur leur terre, et ils ne seront plus arrachés de leur terre, laquelle je leur ai donnée; dit l’Eternel ton Dieu. Retournez au Début This Website is Hosted by../../lilacsandbutterflies/images/EClilacsbanner.gif ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'La vision d’Abdias. Ainsi a dit le Seigneur l’Eternel touchant Edom: Nous avons ouï une publication de par l’Eternel, et un Envoyé a été dépêché parmi les nations, et elles ont dit: Courage levons-nous contre lui pour le combattre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Voici, je te rendrai petit entre les nations, tu seras fort méprisé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'L’orgueil de ton coeur t’a séduit, toi qui habites dans les fentes des rochers, qui sont ta haute demeure, et qui dis en ton coeur: Qui est-ce qui me renversera par terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Quand tu aurais élevé ton nid comme l’aigle, et quand même tu l’aurais mis entre les étoiles, je te jetterai de là par terre, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Sont-ce des larrons qui sont entrés chez toi, ou des voleurs de nuit? Comment donc as-tu été rasé? N’eussent-ils pas dérobé jusqu’à ce qu’ils en eussent eu assez? Si des vendangeurs fussent entrés chez toi, n’eussent-ils pas laissé quelque grappillage?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Comment a été fouillé Esaü? Comment ont été examinés ses lieux secrets?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Tous tes alliés t’ont conduit jusqu’à la frontière; ceux qui étaient en paix avec toi t’ont trompé, et ont eu le dessus sur toi; ceux qui mangeaient ton pain t’ont donné le coup par-dessous, sans qu’on l’aperçût.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Ne sera-ce pas en ce temps-là, dit l’Eternel, que je ferai périr les sages au milieu d’Edom, et la prudence dans la montagne d’Esaü?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Tes hommes forts seront aussi étonnés, ô Téman! afin que les hommes soient retranchés de la montagne d’Esaü, à force de les y tuer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'La honte te couvrira, et tu seras retranché pour jamais, à cause de la violence faite à ton frère Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Lorsque tu te tenais vis-à-vis quand les étrangers menaient son armée en captivité, et que les forains entraient dans ses portes, et qu’ils jetaient le sort sur Jérusalem, tu étais aussi comme l’un d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Mais tu ne devais pas prendre plaisir à voir la journée de ton frère quand il a été livré aux étrangers, et tu ne devais pas te réjouir sur les enfants de Juda au jour qu’ils ont été détruits, et tu ne les devais pas braver au jour de la détresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Et tu ne devais pas entrer dans la porte de mon peuple au jour de sa calamité, et tu ne devais pas prendre plaisir, toi, dis-je, à voir son mal au jour de sa calamité, et tes mains ne se devaient pas avancer sur son bien, au jour de sa calamité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Et tu ne te devais pas tenir sur les passages, pour exterminer ses réchappés; ni livrer ceux qui étaient restés, au jour de la détresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Car la journée de l’Eternel est proche sur toutes les nations; comme tu as fait, il te sera ainsi fait; ta récompense retournera sur ta tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Car comme vous avez bu sur la montagne de ma sainteté la coupe de ma fureur, ainsi toutes les nations la boiront sans interruption; oui, elles la boiront, et l’ avaleront, et elles seront comme si elles n’avaient point été.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Mais il y aura des réchappés sur la montagne de Sion, et elle sera sainte, et la maison de Jacob possédera ses possessions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Et la maison de Jacob sera un feu, et la maison de Joseph une flamme, et la maison d’Esaü du chaume; ils s’allumeront parmi eux, et les consumeront; et il n’y aura rien de reste dans la maison d’Esaü; car l’Eternel a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Ils posséderont le Midi, savoir la montagne d’Esaü; et la campagne, savoir les Philistins, et ils posséderont le territoire d’Ephraïm, et le territoire de Samarie; et Benjamin possédera Galaad.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Et ces bandes des enfants d’Israël qui auront été transportés, posséderont ce qui était des Cananéens, jusqu’à Sarepta; et ceux de Jérusalem qui auront été transportés, posséderont ce qui est jusqu’à Sépharad, ils le posséderont avec les villes du Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Car les libérateurs monteront en la montagne de Sion, pour juger la montagne d’Esaü; et le Royaume sera à l’Eternel. Retournez au Début ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Or la parole de l’Eternel fut adressée à Jonas fils d’Amittaï, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Lève-toi, et t’en va à Ninive, la grande ville, et tonne contre elle; car leur malice est montée jusqu’à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Mais Jonas se leva pour s’enfuir en Tarsis, de devant la face de l’Eternel, et descendit à Japho, où il trouva un navire qui allait en Tarsis; et ayant payé le port, il y entra, pour aller avec eux en Tarsis, de devant la face de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Mais l’Eternel éleva un grand vent sur la mer, et il y eut une grande tourmente en la mer, de sorte que le navire se pensa rompre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Et les mariniers eurent peur, et ils crièrent chacun à son Dieu, et jetèrent dans la mer la charge du navire pour l’en décharger; mais Jonas était descendu au fond du navire, et y était couché, et il dormait profondément.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Alors le maître pilote s’approcha de lui, et lui dit: Qu’as-tu, dormeur? Lève-toi, crie à ton Dieu; il pensera, peut-être, à nous, et nous ne périrons point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Puis ils se dirent l’un à l’autre: Venez, et jetons le sort afin que nous sachions à cause de qui ce mal nous est arrivé. Ils jetèrent donc le sort, et le sort tomba sur Jonas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Alors ils lui dirent: Déclare-nous maintenant, pourquoi ce mal-ici nous est arrivé, quel est ton métier, et d’où tu viens; quel est ton pays, et de quel peuple tu es.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Et il leur dit: Je suis Hébreu, et je crains l’Eternel, le Dieu des cieux, qui a fait la mer et le sec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Alors ces hommes furent saisis d’une grande crainte, et lui dirent: Pourquoi as-tu fait cela? Car ces hommes avaient entendu qu’il s’enfuyait de devant la face de l’Eternel, parce qu’il le leur avait déclaré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Et ils lui dirent: Que te ferons-nous afin que la mer se calme, nous laissant en paix? Car la mer se tourmentait de plus en plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Et il leur répondit: Prenez-moi, et me jetez dans la mer, et la mer s’apaisera, vous laissant en paix; car je connais que cette grande tourmente est venue sur vous à cause de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Et ces hommes voguaient pour relâcher à terre, mais ils ne pouvaient, parce que la mer s’agitait de plus en plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Ils crièrent donc à l’Eternel, et dirent: Eternel, nous te prions que nous ne périssions point maintenant à cause de l’âme de cet homme-ci, et ne mets point sur nous le sang innocent; car tu es l’Eternel, tu en as fait comme il t’a plu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Alors ils prirent Jonas, et le jetèrent dans la mer, et la tourmente de la mer s’arrêta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Et ces gens-là craignirent l’Eternel d’une grande crainte, et ils offrirent des sacrifices à l’Eternel, et vouèrent des voeux. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Or l’Eternel avait préparé un grand poisson pour engloutir Jonas; et Jonas demeura dans le ventre du poisson trois jours et trois nuits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Et Jonas fit sa prière à l’Eternel son Dieu, dans le ventre du poisson.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Et il dit: J’ai crié à l’Eternel à cause de ma détresse, et il m’a exaucé; je me suis écrié du ventre du sépulcre, et tu as ouï ma voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Tu m’as jeté au fond, au coeur de la mer, et le courant m’a environné; tous tes flots et toutes tes vagues ont passé sur moi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Et j’ai dit: Je suis rejeté de devant tes yeux; mais néanmoins je verrai encore le Temple de ta sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Les eaux m’ont environné jusqu’à l’âme, l’abîme m’a environné tout à l’entour, les roseaux se sont entortillés autour de ma tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Je suis descendu jusqu’aux racines des montagnes, la terre avec ses barres était autour de moi pour jamais; mais tu as fait remonter ma vie hors de la fosse, ô Eternel, mon Dieu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Quand mon âme se pâmait en moi, je me suis souvenu de l’Eternel, et ma prière est parvenue à toi, jusqu’au palais de ta sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Ceux qui s’adonnent aux vanités fausses abandonnent leur gratuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Mais moi, je te sacrifierai avec voix de louange, je rendrai ce que j’ai voué; car le salut est de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 11, 'Alors l’Eternel fit commandement au poisson, et il dégorgea Jonas sur le sec. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Puis la parole de l’Eternel fut adressée à Jonas une seconde fois, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Lève-toi, et t’en va à Ninive la grande ville; et y publie à haute voix ce que je t’ordonne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Jonas donc se leva, et s’en alla à Ninive, suivant la parole de l’Eternel. Or Ninive était une très-grande ville, de trois journées de chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Et Jonas commença d’entrer dans la ville le chemin d’une journée, et il cria et dit: Encore quarante jours, et Ninive sera renversée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Et les hommes de Ninive crurent à Dieu, et publièrent le jeûne, et se vêtirent de sacs, depuis le plus grand d’entre eux jusqu’au plus petit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Car cette parole était parvenue jusqu’au Roi de Ninive, lequel se leva de son trône, et ôta de dessus soi son vêtement magnifique, et se couvrit d’un sac, et s’assit sur la cendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Puis il fit faire une proclamation, et on publia dans Ninive par le décret du Roi et de ses Princes, en disant: Que ni homme, ni bête, ni boeuf, ni brebis, ne goûtent d’aucune chose, qu’ils ne se repaissent point, et qu’ils ne boivent point d’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Et que les hommes soient couverts de sacs, et les bêtes aussi; et qu’ils crient à Dieu de toute leur force, et que chacun se convertisse de sa mauvaise voie, et des actions violentes qu’ils ont commises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Qui sait si Dieu viendra à se repentir, et s’il se détournera de l’ardeur de sa colère, en sorte que nous ne périssions point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Et Dieu regarda à ce qu’ils avaient fait, savoir comment ils s’étaient détournés de leur mauvaise voie, et Dieu se repentit du mal qu’il avait dit qu’il leur ferait, et ne le fit point. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Mais cela déplut à Jonas, il lui déplut extrêmement, et il en fut en colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'C’est pourquoi il fit cette requête à l’Eternel, et dit: Ô Eternel! je te prie, n’est-ce pas ici ce que je disais, quand j’étais encore en mon pays? C’est pourquoi j’avais voulu m’enfuir en Tarsis; car je connaissais que tu es un Dieu Fort, miséricordieux, pitoyable, tardif à colère, abondant en gratuité, et qui te repens du mal dont tu as menacé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Maintenant donc, ô Eternel! ôte-moi, je te prie, la vie; car la mort m’est meilleure que la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Et l’Eternel dit: Est-ce bien fait à toi de t’être ainsi mis en colère?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Et Jonas sortit de la ville, et s’assit du côté de l’Orient de la ville, et se fit là une cabane, et se tint à l’ombre sous elle, jusqu’à ce qu’il vît ce qui arriverait à la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Et l’Eternel Dieu prépara un kikajon, et le fit croître au-dessus de Jonas, afin qu’il lui fît ombre sur sa tête, et qu’il le délivrât de son mal; et Jonas se réjouit extrêmement du kikajon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Puis Dieu prépara pour le lendemain, lorsque l’aube du jour monterait, un ver qui frappa le kikajon, et il sécha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Et il arriva que quand le soleil fut levé Dieu prépara un vent Oriental qu’on n’apercevait point, et le soleil frappa sur la tête de Jonas, en sorte que s’évanouissant il demanda de mourir, et il dit: La mort m’est meilleure que la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Et Dieu dit à Jonas: Est-ce bien fait à toi de t’être ainsi dépité au sujet de ce kikajon? Et il répondit: C’est bien fait à moi que je me sois ainsi dépité, même jusqu’à la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Et l’Eternel dit: Tu voudrais qu’on eût épargné le kikajon, pour lequel tu n’as point travaillé, et que tu n’as point fait croître; car il est venu en une nuit, et en une nuit il est péri;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'Et moi, n’épargnerais-je point Ninive, cette grande ville, dans laquelle il y a plus de six vingt mille créatures humaines qui ne savent point discerner entre leur main droite et leur main gauche, et où il y a aussi une grande quantité de bêtes. Retournez au Début ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'La parole de l’Eternel qui fut adressée à Michée Morasite au temps de Jotham, Achaz, et Ezéchias, Rois de Juda, laquelle lui fut adressée dans une vision, contre Samarie et Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Vous tous peuples, écoutez; et toi terre, sois attentive, et que tout ce qui est en elle écoute; et que le Seigneur l’Eternel soit témoin contre vous, le Seigneur, dis-je, sortant du palais de sa sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Car voici, l’Eternel s’en va sortir de son lieu, il descendra, et marchera sur les lieux hauts de la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Et les montagnes se fondront sous lui, et les vallées se fendront, elles seront comme de la cire devant le feu, et comme des eaux qui coulent en une descente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Tout ceci arrivera à cause du crime de Jacob, et à cause des péchés de la maison d’Israël. Or quel est le crime de Jacob? N’est-ce pas Samarie? Et quels sont les hauts lieux de Juda? N’est-ce pas Jérusalem?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'C’est pourquoi je réduirai Samarie comme en un monceau de pierres ramassées dans les champs où l’on veut planter des vignes; et je ferai rouler ses pierres dans la vallée, et je découvrirai ses fondements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Et toutes ses images taillées seront brisées, tous les salaires de sa prostitution seront brûlés au feu, et je mettrai tous ses faux dieux en désolation; parce qu’elle les a entassés par le moyen du salaire de sa prostitution, ils serviront de salaire à une prostituée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'C’est pourquoi je me plaindrai, et je hurlerai; je m’en irai dépouillé et nu; je ferai une lamentation comme celle des dragons, et je mènerai un deuil comme celui des chats-huants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Car il n’y a pas une de ses plaies qui ne soit incurable, chacune d’elles est venue jusqu’en Juda, et l’ennemi est parvenu jusqu’à la porte de mon peuple, jusqu’à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Ne l’annoncez point dans Gath, ne pleurez nullement; vautre-toi sur la poussière dans la maison d’Haphra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Habitante de Saphir passe, ayant ta nudité toute découverte; l’habitante de Tsaanan n’est point sortie pour la complainte de la maison d’Esel; on apprendra de vous à se tenir dans la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Car l’habitante de Maroth aura été dans l’angoisse pour son bien; parce que le mal est descendu de par l’Eternel sur la porte de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Attelle le cheval au chariot, habitante de Lakis, toi qui es le commencement du péché de la fille de Sion; car en toi ont été trouvés les crimes d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'C’est pourquoi donne des présents à cause de Moreseth de Gath; les maisons d’Aczib mentiront aux Rois d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Je te ferai aussi venir un héritier, habitante de Maresa; et la gloire d’Israël viendra jusqu’à Hadullam.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Arrache tes cheveux, et te fais tondre à cause de tes fils qui font tes délices; arrache tout le poil de ton corps comme un aigle qui mue, car ils sont emmenés prisonniers loin de toi. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Malheur à ceux qui pensent à faire outrage, qui forgent le mal sur leurs lits, et qui l’exécutent dès le point du jour, parce qu’ils ont le pouvoir en main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'S’ils convoitent des possessions, ils les ont aussitôt ravies, et s’ils convoitent des maisons, ils les ont aussitôt prises; ainsi ils oppriment l’homme et sa maison, l’homme, dis-je, et son héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'C’est pourquoi ainsi a dit l’Eternel: Voici, je pense contre cette famille-ci un mal duquel vous ne pourrez point vous mettre à couvert, et vous ne marcherez point à tête levée; car ce temps est mauvais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'En ce temps-là on fera de vous un proverbe lugubre, et l’on gémira d’un gémissement lamentable, en disant: Nous sommes entièrement détruits, il a changé la portion de mon peuple; comment nous l’aurait-il ôtée? partage-t-il nos champs, pour nous les faire rendre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'C’est pourquoi il n’y aura personne pour toi qui jette le cordeau pour ton lot dans la congrégation de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'On dit: Ne prophétisez point, ils prophétiseront, mais ils ne prophétiseront point pour ceux-ci; l’ignominie ne tournera point en arrière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Or toi qui es appelée Maison de Jacob, l’Esprit de l’Eternel est-il amoindri? Sont-ce là ses actes? Mes paroles ne sont-elles pas bonnes pour celui qui marche droitement?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Mais celui qui était hier mon peuple, s’élève à la manière d’un ennemi, pour rencontrer un manteau; vous dépouillez le vêtement magnifique à ceux qui passent en assurance, étant de retour de la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Vous mettez les femmes de mon peuple hors des maisons où elles prenaient plaisir; vous ôtez pour jamais ma gloire de dessus leurs petits enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Levez-vous, et marchez, car ce pays ne vous est plus un lieu de repos; parce qu’il est souillé, il vous détruira, même d’une prompte destruction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'S’il y a quelque homme qui marche selon le vent, et qui mente faussement, en disant; Je te prophétiserai du vin et de la cervoise; ce sera le Prophète de ce peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Mais je t’assemblerai tout entier, ô Jacob! et je ramasserai entièrement le reste d’Israël, et le mettrai tout ensemble comme les brebis de Botsra, comme un troupeau au milieu de son étable; il y aura un grand bruit pour la foule des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Le briseur montera devant eux, on brisera, et on passera outre, et eux sortiront par la porte; et leur Roi passera devant eux, et l’Eternel sera à leur tête. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'C’est pourquoi j’ai dit: Ecoutez maintenant, Chefs de Jacob, et vous Conducteurs de la maison d’Israël: N’est ce point à vous de connaître ce qui est juste?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Ils haïssent le bien, et aiment le mal; ils ravissent la peau de ces gens-ci de dessus eux, et leur chair de dessus leurs os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'Et ce qu’ils mangent; c’est la chair de mon peuple, et ils ont écorché leur peau de dessus eux, et ont cassé leurs os, et les ont mis par pièces comme dans un pot, et comme de la chair dans une chaudière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Alors ils crieront à l’Eternel, mais il ne les exaucera point, et il cachera sa face d’eux en ce temps-là, selon qu’ils se sont mal conduits dans leurs actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Ainsi a dit l’Eternel contre les Prophètes qui font égarer mon peuple, qui mordent de leurs dents, et qui crient: Paix! et si quelqu’un ne leur donne rien dans leur bouche, ils publient la guerre contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'C’est pourquoi la nuit sera sur vous, afin que vous n’ayez point de vision; et elle s’obscurcira, afin que vous ne deviniez point; le soleil se couchera sur ces Prophètes-là, et le jour leur sera ténébreux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Et les voyants seront honteux, et les devins rougiront de honte; eux tous se couvriront sur la lèvre de dessus, parce qu’il n’y aura aucune réponse de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Mais moi, je suis rempli de force, et de jugement, et de courage, par l’Esprit de l’Eternel, pour déclarer à Jacob son crime, et à Israël son péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Ecoutez maintenant ceci, Chefs de la maison de Jacob, et vous Conducteurs de la maison d’Israël, qui avez le jugement en abomination, et qui pervertissez tout ce qui est juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'On bâtit Sion de sang, et Jérusalem d’injustices.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Ses Chefs jugent pour des présents, ses Sacrificateurs enseignent pour le salaire, et ses prophètes devinent pour de l’argent, puis ils s’appuient sur l’Eternel, en disant: L’Eternel n’est-il pas parmi nous? Il ne viendra point de mal sur nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'C’est pourquoi à cause de vous, Sion sera labourée comme un champ, et Jérusalem sera réduite en monceaux de pierres, et la montagne du Temple en hauts lieux de forêt. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Mais il arrivera aux derniers jours, que la montagne de la maison de l’Eternel sera affermie au sommet des montagnes, et sera élevée par-dessus les coteaux; les peuples y aborderont.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Et plusieurs nations iront, et diront: Venez, et montons à la montagne de l’Eternel, et à la maison du Dieu de Jacob; et il nous enseignera touchant ses voies, et nous marcherons dans ses sentiers; car la Loi sortira de Sion, et la parole de l’Eternel sortira de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Il exercera jugement parmi plusieurs peuples, et il censurera fortement les grandes nations jusqu’aux pays les plus éloignés; et de leurs épées elles forgeront des hoyaux; et de leurs hallebardes, des serpes; une nation ne lèvera plus l’épée contre l’autre, et elles ne s’adonneront plus à la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Mais chacun s’assiéra sous sa vigne et sous son figuier, et il n’y aura personne qui les épouvante; car la bouche de l’Eternel des armées a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Certainement tous les peuples marcheront chacun au nom de son dieu; mais nous marcherons au nom de l’Eternel notre Dieu à toujours et à perpétuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'En ce temps-là, dit l’Eternel, j’assemblerai la boiteuse, et je recueillerai celle qui avait été chassée, et celle que j’avais affligée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Et je mettrai la boiteuse, pour être un résidu, et celle qui était éloignée, pour être une nation robuste; l’Eternel régnera sur eux en la montagne de Sion dès cette heure-là à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Et toi, Tour du troupeau, Hophel, la fille de Sion viendra jusqu’à toi; et la première domination viendra, le Royaume, dis-je, viendra à la fille de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Pourquoi t’écries-tu maintenant si fort? N’y a-t-il point de Roi au milieu de toi? Ou ton conseiller est-il péri, que la douleur t’ait saisie comme de celle qui enfante?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Sois en travail, et crie, fille de Sion, comme celle qui enfante; car tu sortiras bientôt de la ville, et tu demeureras aux champs, et viendras jusqu’à Babylone; mais là tu seras délivrée; là l’Eternel te rachètera des mains de tes ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Et maintenant se sont assemblées contre toi plusieurs nations qui disent: Qu’elle soit profanée, et que notre oeil voie en Sion ce qu’il y voudrait voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Mais ils ne connaissent point les pensées de l’Eternel, et n’entendent point son conseil; car il les a assemblées comme des gerbes dans l’aire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Lève-toi, et foule, fille de Sion, car je ferai que ta corne sera de fer, et je ferai que tes ongles seront d’airain; et tu menuiseras plusieurs peuples, et je dédierai comme un interdit leur gain à l’Eternel, et leurs biens au Seigneur de toute la terre. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Maintenant assemble-toi par troupes, fille de troupes; on a mis le siège contre nous, on frappera le Gouverneur d’Israël avec la verge sur la joue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Mais toi, Bethléhem Ephrata, petite pour être entre les milliers de Juda, de toi me sortira quelqu’un pour être Dominateur en Israël; et ses issues sont d’ancienneté, dès les jours éternels.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'C’est pourquoi il les livrera jusqu’au temps que celle qui est en travail d’enfant aura enfanté; et le reste de ses frères retournera avec les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Et il se maintiendra et gouvernera par la force de l’Eternel, avec la magnificence du Nom de l’Eternel son Dieu; et ils demeureront fermes; car en peu de temps il s’agrandira jusqu’aux bouts de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Et c’est lui qui sera la paix. Après que l’Assyrien sera entré dans notre pays, et qu’il aura mis le pied dans nos palais, nous établirons contre lui sept pasteurs, et huit princes pris du commun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Et ils ravageront le pays d’Assyrie avec l’épée, et le pays de Nimrod à ses portes; et il nous délivrera des Assyriens, quand ils seront entrés dans notre pays, et qu’ils auront mis le pied dans nos quartiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Et le reste de Jacob sera au milieu de plusieurs peuples comme une rosée qui vient de l’Eternel, et comme une pluie menue qui tombe sur l’herbe, laquelle on n’attend point d’aucun homme, et qu’on n’espère point des enfants des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Aussi le reste de Jacob sera parmi les nations, et au milieu de plusieurs peuples, comme un lion parmi les bêtes des forêts, et comme un lionceau parmi des troupeaux de brebis; lequel y passant foule et déchire, sans que personne en puisse rien garantir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Ta main sera élevée sur tes adversaires, et tous tes ennemis seront retranchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'Et il arrivera en ce temps-là, dit l’Eternel, que je retrancherai tes chevaux du milieu de toi, et ferai périr tes chariots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Et je retrancherai les villes de ton pays, et ruinerai toutes tes forteresses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Je retrancherai aussi les sorcelleries de ta main, et tu n’auras plus aucun pronostiqueur de temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Et je retrancherai tes images taillées et tes statues du milieu de toi, et tu ne te prosterneras plus devant l’ouvrage de tes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'J’arracherai aussi tes bocages du milieu de toi, et effacerai tes ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'Et je ferai vengeance avec colère et avec fureur de toutes les nations qui ne m’auront point écouté. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Ecoutez maintenant ce que dit l’Eternel: Lève-toi, plaide par- devant les montagnes, et que les collines entendent ta voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Ecoutez, montagnes, le procès de l’Eternel, écoutez-le aussi vous qui êtes les plus fermes fondements de la terre; car l’Eternel a un procès avec son peuple, et il plaidera avec Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Mon peuple, que t’ai-je fait, ou en quoi t’ai-je causé de la peine? Réponds-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Car je t’ai fait remonter hors du pays d’Egypte, et t’ai délivré de la maison de servitude, et j’ai envoyé devant toi Moïse, Aaron et Marie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Mon peuple, qu’il te souvienne, je te prie, quel conseil Balak Roi de Moab avait pris contre toi, et de ce que Balaam fils de Béhor lui répondit: et de ce que j’ai fait depuis Sittim jusqu’à Guilgal, afin que tu connaisses les justices de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Avec quoi préviendrai-je l’Eternel, et me prosternerai-je devant le Dieu souverain? Le préviendrai-je avec des holocaustes, et avec des veaux d’un an?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'L’Eternel prendra-t-il plaisir aux milliers de moutons, ou à dix mille torrents d’huile? Donnerai-je mon premier-né pour mon crime, le fruit de mon ventre pour le péché de mon âme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Ô homme! Il t’a déclaré ce qui est bon; et qu’est-ce que l’Eternel requiert de toi, sinon que tu fasses ce qui est juste, que tu aimes la bénignité, et que tu marches en toute humilité avec ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'La voix de l’Eternel crie à la ville, (car ton Nom voit comme il va de tout:) Ecoutez la verge, et celui qui l’a assignée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Chacun n’a-t-il pas encore une maison de méchant, des trésors de méchanceté, et un Epha court, et détestable?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Tiendrai-je pour net celui qui a de fausses balances, et de fausses pierres à peser dans son sachet?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Car ses riches sont remplis de choses ravies par violence, ses habitants usent de mensonge, et il y a une langue trompeuse dans leur bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'C’est pourquoi je t’ai rendue languissante en te frappant, et te rendant désolée à cause de tes péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Tu mangeras, mais tu ne seras point rassasiée; et la cause de ton abaissement sera au-dedans de toi-même; tu ôteras de devant, mais tu ne sauveras point; et ce que tu auras sauvé, je le livrerai à l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Tu sèmeras, mais tu ne moissonneras point; tu presseras l’olive, mais tu ne t’oindras point d’huile; et le moût, mais tu ne boiras point le vin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Car on a gardé les ordonnances de Homri, et toute l’oeuvre de la maison d’Achab, et vous avez marché dans leurs conseils, afin que je mette en désolation et en opprobre ceux qui habitent en elle, et que vous portiez l’opprobre de mon peuple. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Malheur à moi! car je suis comme quand on a cueilli les fruits d’Eté, et les grappillages de la vendange; il n’y a point de grappe pour manger, et mon âme désirait des premiers fruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Le débonnaire est péri de dessus la terre, et il n’y a pas un homme juste entre les hommes; ils sont tous en embûche pour verser le sang, chacun chasse après son frère avec des filets.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Pour faire du mal avec les deux mains; le Gouverneur exige, et le Juge court après la récompense, et les grands ne parlent que des outrages qu’ils souhaitent, et qu’ils entortillent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Le plus homme de bien d’entre eux est comme une ronce, et le plus juste est pire qu’une haie d’épines: ta visitation, qui est le jour de tes surveillants, est venue, et leur perplexité sera bientôt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Ne croyez point à votre intime ami, et ne vous confiez point en vos conducteurs; garde-toi d’ouvrir ta bouche devant la femme qui dort en ton sein.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Car le fils déshonore le père, la fille s’élève contre sa mère, la belle-fille contre sa belle-mère, et les domestiques de chacun sont ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Mais moi, je serai au guet, attendant l’Eternel; j’attendrai le Dieu de mon salut; mon Dieu m’exaucera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Toi, mon ennemie, ne te réjouis point sur moi; si je suis tombée, je me relèverai; si j’ai été gisante dans les ténèbres, l’Eternel m’éclairera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Je porterai l’indignation de l’Eternel, parce que j’ai péché contre lui, jusqu’à ce qu’il ait défendu ma cause, et qu’il m’ait fait justice; il me conduira à la lumière, je verrai sa justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Et mon ennemie le verra, et la honte la couvrira; celle qui me disait: Où est l’Eternel, ton Dieu? mes yeux la verront, et elle sera bientôt pour être foulée comme la boue des rues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Au temps qu’il rebâtira tes cloisons, en ce tempslà les édits seront étendus au loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'En ce temps-là on viendra jusqu’à toi, même d’Assyrie et des villes fortes, et depuis les villes fortes jusqu’au fleuve, et depuis une mer jusqu’à l’autre, et depuis une montagne jusqu’à l’autre montagne;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Après que le pays aura été en désolation à cause de ses habitants, et pour le fruit de leurs actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Pais avec ta houlette ton peuple, le troupeau de ton héritage, qui demeure seul dans les forêts au milieu de Carmel; et fais qu’ils paissent en Basan et en Galaad, comme au temps d’autrefois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Je lui ferai voir des choses merveilleuses, comme au temps que tu sortis du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Les nations le verront, et elles seront honteuses avec toute leur force; elles mettront la main sur la bouche, et leurs oreilles seront sourdes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Elles lécheront la poudre comme le serpent, et trembleront dans leurs enclos comme les reptiles de la terre; elles accourront tout effrayées vers l’Eternel, notre Dieu, et te craindront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Qui est le Dieu Fort comme toi, qui es un Dieu qui ôte l’iniquité, et qui passe par-dessus les péchés du reste de son héritage? Il ne tient point à toujours sa colère, parce qu’il se plaît en la gratuité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Il aura encore compassion de nous; il effacera nos iniquités, et jettera tous nos péchés au fond de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Tu maintiendras ta vérité à Jacob, et ta gratuité à Abraham, laquelle tu as jurée à nos pères dès les siècles passés. Retournez au Début This Website is Hosted by../../lilacsandbutterflies/images/EClilacsbanner.gif ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'La charge de Ninive, qui est le livre de la vision de Nahum Elkosien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Le Dieu Fort est jaloux, et l’Eternel est vengeur, l’Eternel est vengeur, et il a la fureur à son commandement; l’Eternel se venge de ses adversaires, et la garde à ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'L’Eternel est tardif à colère, et grand en force, mais il ne tient nullement le coupable pour innocent; l’Eternel marche parmi les tourbillons et les tempêtes, et les nuées sont la poudre de ses pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Il tance la mer, et la fait tarir, et il dessèche tous les fleuves; Basan et Carmel sont rendus languissants, la fleur du Liban est aussi rendue languissante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Les montagnes tremblent à cause de lui, et les coteaux s’écoulent; la terre monte en feu à cause de sa présence, la terre, dis-je, habitable, et tous ceux qui y habitent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Qui subsistera devant son indignation? et qui demeurera ferme dans l’ardeur de sa colère? Sa fureur se répand comme un feu, et les rochers se brisent devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'L’Eternel est bon, il est une forteresse au temps de la détresse, et il connaît ceux qui se confient en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Il s’en va passer comme un débordement d’eaux; il réduira son lieu à néant, et fera que les ténèbres poursuivront ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Que pourriez-vous machiner contre l’Eternel? C’est lui qui réduit à néant; la détresse n’y retounera point une seconde fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Car étant entortillés comme des épines, et ivres selon qu’ils ont accoutumé de s’enivrer, ils seront consumés entièrement comme la paille sèche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'De toi est sorti celui qui machine du mal contre l’Eternel, et qui met en avant un méchant conseil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Ainsi a dit l’Eternel: Encore qu’ils soient en paix, et en grand nombre, ils seront certainement retranchés, et on passera outre; or je t’ai affligée, mais je ne t’affligerai plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Mais maintenant je romprai son joug de dessus toi, et je mettrai en pièces tes liens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Car l’Eternel a donné commission contre toi; il n’en naîtra plus de ton nom; je retrancherai de la maison de tes dieux les images de taille et de fonte; je ferai de cette maison-là ton sépulcre, après que tu seras tombé dans le mépris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Voici sur les montagnes les pieds de celui qui apporte de bonnes nouvelles, et qui publie la paix! Toi Juda, célèbre tes fêtes solennelles, et rends tes voeux; car les hommes violents ne passeront plus à l’avenir au milieu de toi, ils sont entièrement retranchés. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Le destructeur est monté contre toi; garde la forteresse, prends garde aux avenues, fortifie tes reins, ramasse toutes tes forces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Car l’Eternel a abaissé la fierté de Jacob comme la fierté d’Israël; parce que les videurs les ont vidés, et qu’ils ont ravagé leurs sarments.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Le bouclier de ses hommes forts est rendu rouge; ses hommes vaillants sont teints de vermillon; les chariots marcheront avec un feu de torches, au jour qu’il aura rangé ses batailles, et que les sapins branleront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Les chariots couront avec rapidité dans les rues, et s’entre- heurteront dans les places, ils seront, à les voir comme des flambeaux, et courront comme des éclairs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Il se souviendra de ses hommes vaillants, mais ils seront renversés en chemin; ils se hâteront de venir à ses murailles, et la contre- défense sera toute prête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Les portes des fleuves sont ouvertes, et le palais s’est fondu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'On y a fait tenir chacun debout, la Reine a été emmenée prisonnière, on l’a fait monter, et ses servantes l’ont accompagnée, comme avec une voix de colombe, frappant leurs poitrines comme un tambour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Or Ninive, depuis qu’elle a été bâtie, a été comme un vivier d’eaux; mais ils s’enfuient; arrêtez-vous, arrêtez-vous; mais il n’y a personne qui tourne visage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Pillez l’argent, pillez l’or; il y a de bornes à son fane, qui l’emporte sur tous les vaisseaux précieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Qu’elle soit toute vidée et revidée, même tout épuisée; que leur coeur se fonde, que leurs genoux se heurtent l’un contre l’autre; que le tourment soit dans les reins de tous, et que leurs visages deviennent noirs comme un pot qui a été mis sur le feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Où est le repaire des lions, et le viandis des lionceaux, dans lequel se retiraient les lions, et où se tenaient les vieux lions, et les faons des lions, sans qu’aucun les effarouchât?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Les lions ravissaient tout ce qu’il fallait pour leurs faons, et étranglaient les bêtes pour leurs vielles lionnes, et ils remplissaient leurs tanières de proie, et leurs repaires de rapine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Voici, j’en veux à toi, dit l’Eternel des armées, et je brûlerai tes chariots, et ils s’en iront en fumée, et l’épée consumera tes lionceaux; je retrancherai de la terre ta proie, et la voix de tes ambassadeurs ne sera plus entendue. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Malheur à la ville sanguinaire qui est toute pleine de mensonge, et toute remplie de proie; la rapine ne s’en retirera point:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Ni le bruit du fouet, ni le bruit impétueux des roues, ni les chevaux battant des pieds, ni les chariots sautelant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Ni les gens de cheval faisant bondir leurs chevaux, ni l’épée brillante, ni la hallebarde étincelante, ni la multitude des blessés à mort, ni le grand nombre des corps morts, et il n’y aura nulle fin aux corps morts, de sorte qu’on sera renversé sur leurs corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'A cause de la multitude des prostitutions de cette prostituée pleine de charmes, experte en sortilèges, qui vendait les nations par ses prostitutions, et les familles par ses enchantements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Voici, j’en veux à toi, dit l’Eternel des armées, je te dépouillerai de tes vêtements; je manifesterai ta honte aux nations, et ton ignominie aux Royaumes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Je ferai tomber sur ta tête la peine de tes abominations, je te consumerai et je te couvrirai d’infamie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Et il arrivera que quiconque te verra s’éloignera de toi, et dira: Ninive est détruite; qui aura compassion d’elle? D’où te chercherai-je des consolateurs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Vaux-tu mieux que No la nourricière, située entre les fleuves, qui a les eaux à l’entour de soi, dont la mer est le rempart, à qui la mer sert de murailles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Sa force était Cus et l’Egypte, et une infinité d’autres peuples; Put et les Lybiens sont allés à son secours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Elle-même aussi a été transportée hors de sa terre, elle s’en est allée en captivité; même ses enfants ont été écrasés aux carrefours de toutes les rues, et on a jeté le sort sur ses gens honorables, et tous ses Principaux ont été liés de chaînes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Toi aussi tu seras enivrée, tu te tiendras cachée, et tu chercheras du secours contre l’ennemi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Toutes tes forteresses seront comme des figues, et comme des premiers fruits, qui étant secoués, tombent dans la bouche de celui qui les veut manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Voici, ton peuple sera comme autant de femmes au milieu de toi; les portes de ton pays seront toutes ouvertes à tes ennemis; le feu consumera tes barres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Puise-toi de l’eau pour le siége, fortifie tes remparts, enfonce le pied dans la terre grasse, et foule l’argile, et rebâtis la briqueterie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Là le feu te consumera; l’épée te retranchera, elle te dévorera comme le hurebec dévore les arbres. Qu’on s’amasse comme les hurebecs, amasse-toi comme les sauterelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Tu as multiplié tes négociants en plus grand nombre que les étoiles des cieux; les hurebecs s’étant répandus ont tout ravagé, et puis ils s’en sont envolés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Ceux qui portent le diadème au milieu de toi sont comme des sauterelles, et tes capitaines comme de grandes sauterelles qui se campent dans les cloisons au temps de la fraîcheur, et qui, lorsque le soleil est levé, s’écartent, de sorte qu’on ne connaît plus le lieu où elles ont été.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Tes Pasteurs se sont endormis, ô Roi d’Assyrie! tes hommes illustres se sont tenus dans leurs tentes; ton peuple est dispersé par les montagnes, et il n’ y a personne qui le rassemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Il n’y a point de remède à ta blessure, ta plaie est douloureuse; tous ceux qui entendront parler de toi battront des mains sur toi; car qui est-ce qui n’a pas continuellement éprouvé les effets de ta malice? Retournez au Début ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'La charge qu’Habacuc le Prophète a vue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Ô Eternel! jusques à quand crierai-je, sans que tu m’écoutes? jusques à quand crierai-je vers toi, on me traite avec violence, sans que tu me délivres?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Pourquoi me fais-tu voir l’outrage, et vois-tu la perversité? Pourquoi y a-t-il du dégât et de la violence devant moi, et des gens qui excitent des procès et des querelles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Parce que la Loi est sans force, et que la justice ne se fait jamais, à cause de cela le méchant environne le juste, et à cause de cela le jugement sort tout corrompu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Regardez entre les nations, et voyez, et soyez étonnés et tout interdits, car je m’en vais faire en votre temps une oeuvre que vous ne croirez point quand on vous la racontera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Car voici, je m’en vais susciter les Caldéens, qui sont une nation cruelle et impétueuse, marchant sur l’étendue de la terre, pour posséder des demeures qui ne lui appartiennent pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Elle est affreuse et terrible, son gouvernement et son autorité viendra d’elle même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Ses chevaux sont plus légers que les léopards, et ils ont la vue plus aiguë que les loups du soir; et ses gens de cheval se répandront çà et là, même ses gens de cheval viendront de loin; ils voleront comme un aigle qui se hâte pour repaître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Elle viendra toute pour faire le dégât; ce qu’ils engloutiront de leurs regards sera porté vers l’Orient, et elle amassera les prisonniers comme du sable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Elle se moque des Rois, et se joue des Princes; elle se rit de toutes les forteresses, en faisant des terrasses, elle les prendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Alors elle renforcera son courage, et passera outre, mais elle se rendra coupable, en disant que cette puissance qu’elle a est de son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'N’es-tu pas de toute éternité, ô Eternel! mon Dieu! mon Saint? Nous ne mourrons point; ô Eternel! Tu l’as mis pour faire jugement; et toi, mon Rocher, tu l’as fondé pour punir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Tu as les yeux trop purs pour voir le mal, et tu ne saurais prendre plaisir à regarder le mal, qu’on fait à autrui. Pourquoi regarderais-tu les perfides, et te tairais-tu quand le méchant dévore son prochain qui est plus juste que lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Or tu as fait les hommes comme les poissons de la mer, et comme le reptile qui n’a point de dominateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Il a tout enlevé avec l’hameçon; il l’a amassé avec son filet, et l’a assemblé dans son rets; c’est pourquoi il se réjouira, et s’égayera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'A cause de cela il sacrifiera à son filet, et fera des encensements à son rets, parce qu’il aura eu par leur moyen une grasse portion, et que sa viande est une chose moelleuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Videra-t-il à cause de cela son filet? et ne cessera-t-il jamais de faire le carnage des nations? Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Je me tenais en sentinelle, j’étais debout dans la forteresse, et faisais le guet, pour voir ce qui me serait dit, et ce que je répondrais sur ma plainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Et l’Eternel m’a répondu, et m’a dit: Ecris la vision, et l’exprime lisiblement sur des tablettes, afin qu’on la lise couramment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Car la vision est encore différée jusqu’à un certain temps, et l’Eternel parlera de ce qui arrivera à la fin, et il ne mentira point; s’il tarde, attends-le, car il ne manquera point de venir, et il ne tardera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Voici, l’âme qui s’élève en quelqu’un n’est point droite en lui; mais le juste vivra de sa foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Et combien plus l’homme adonné au vin est-il prévaricateur, et l’homme puissant est-il orgueilleux, ne se tenant point tranquille chez soi; qui élargit son âme comme le sépulcre, et qui est insatiable comme la mort, il amasse vers lui toutes les nations, et réunit à soi tous les peuples?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Tous ceux-là ne feront-ils pas de lui un sujet de raillerie et de sentences énigmatiques? Et ne dira-t-on pas: Malheur à celui qui assemble ce qui ne lui appartient point; jusqu’à quand le fera t- il, et entassera-t-il sur soi de la boue épaisse?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'N’y en aura-t-il point qui tout incontinent s’élèveront pour te mordre? Et ne s’en réveillera-t-il point qui te feront courir çà et là, et à qui tu seras en pillage?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Parce que tu as butiné plusieurs nations, tout le reste des peuples te butinera, et à cause aussi des meurtres des hommes, et de la violence faite au pays, à la ville, et à tous ses habitants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Malheur à celui qui cherche à faire un gain injuste pour établir sa maison; afin de placer son nid en haut pour être délivré de la griffe du malin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Tu as pris un conseil de confusion pour ta maison en consumant beaucoup de peuples, et tu as péché contre toi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Car la pierre criera de la paroi, et les noeuds qui sont dans les poutres lui répondront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Malheur à celui qui cimente la ville avec le sang, et qui fonde la ville sur l’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Voici, n’ est -ce pas de par l’Eternel des armées que les peuples travaillent pour en nourrir abondamment le feu, et que les nations se fatiguent très inutilement?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Mais la terre sera remplie de la connaissance de la gloire de l’Eternel, comme les eaux comblent la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Malheur à celui qui fait boire son compagnon en lui approchant sa bouteille, et même l’enivrant, afin qu’on voie leur nudité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Tu auras encore plus de déshonneur, que tu n’as eu de gloire; toi aussi bois, et montre ton opprobre; la coupe de la dextre de l’Eternel fera le tour parmi toi, et l’ignominie sera répandue sur ta gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Car la violence faite au Liban te couvrira; et le dégât fait par les grosses bêtes les rendra tout étonnés, à cause des meurtres des hommes, et de la violence faite au pays, à la ville, et à tous ses habitants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'De quoi sert l’image taillée que son ouvrier l’ait taillée? Ce n’est que fonte, et qu’un docteur de mensonge; de quoi sert- elle, pour que l’ouvrier qui fait des idoles muettes se fie en son ouvrage?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Malheur à ceux qui disent au bois, réveille-toi; et à la pierre muette, réveille-toi; enseignera-t-elle? Voici, elle est couverte d’or et d’argent, et toutefois il n’y a aucun esprit au-dedans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Mais l’Eternel est au Temple de sa sainteté; toute la terre, tais-toi, redoutant sa présence. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'La requête d’Habacuc le Prophète pour les ignorances.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Eternel, j’ai ouï ce que tu m’as fait ouïr, et j’ai été saisi de crainte, Ô Eternel! entretiens ton ouvrage en son être parmi le cours des années, fais- le connaître parmi le cours des années; souviens-toi, quand tu es en colère, d’avoir compassion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Dieu vint de Téman, et le Saint vint du mont de Paran; Sélah. Sa Majesté couvrait les cieux, et la terre fut remplie de sa louange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Sa splendeur était comme la lumière même, et des rayons sortaient de sa main; c’est là où réside sa force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'La mortalité marchait devant lui, et le charbon vif sortait à ses pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Il s’arrêta, et mesura le pays; il regarda, et fit tressaillir les nations; les montagnes qui ont été de tout temps, furent brisées, et les coteaux des siècles se baissèrent; les chemins du monde sont à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Je vis les tentes de Cusan accablées sous la punition; les pavillons du pays de Madian furent ébranlés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'L’Eternel était-il courroucé contre les fleuves? ta colère était -elle contre les fleuves? ta fureur était -elle contre la mer, lorsque tu montas sur tes chevaux et sur tes chariots pour délivrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Ton arc se réveilla, et tira toutes les flèches, selon le serment fait aux Tribus, savoir ta parole; Sélah. Tu fendis la terre, et tu en fis sortir des fleuves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Les montagnes te virent, et elles en furent en travail; l’impétuosité des eaux passa, l’abîme fit retentir sa voix, la profondeur leva ses mains en haut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Le soleil et la lune s’arrêtèrent dans leur habitation, ils marchèrent à la lueur de tes flèches, et à la splendeur de l’éclair de ta hallebarde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Tu marchas sur la terre avec indignation, et foulas les nations avec colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Tu sortis pour la délivrance de ton peuple, tu sortis avec ton Oint pour la délivrance; tu transperças le Chef, afin qu’il n’y en eût plus dans la maison du méchant, découvrant le fondement jusques au fond; Sélah.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Tu perças avec ses bâtons le Chef de ses bourgs, quand ils venaient comme une tempête pour me dissiper; ils s’égayaient comme pour dévorer l’affligé dans sa retraite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Tu marchas avec tes chevaux par la mer; les grandes eaux ayant été amoncelées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'J’ai entendu ce que tu m’as déclaré, et mes entrailles en ont été émues; à ta voix le tremblement a saisi mes lèvres; la pourriture est entrée en mes os, et j’ai tremblé dans moi-même, car je serai en repos au jour de la détresse, lorsque montant vers le peuple, il le mettra en pièces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Car le figuier ne poussera point, et il n’y aura point de fruit dans les vignes; ce que l’olivier produit mentira, et aucun champ ne produira rien à manger; les brebis seront retranchées du parc, et il n’ y aura point de boeufs dans les étables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Mais moi, je me réjouirai en l’Eternel, et je m’égayerai au Dieu de ma délivrance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'L’Eternel, le Seigneur est ma force, et il rendra mes pieds semblables à ceux des biches, et me fera marcher sur mes lieux élevés. Au maître chantre sur Néguinoth. Retournez au Début ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'C’est ici la parole de l’Eternel qui fut adressée à Sophonie fils de Cusi, fils de Guédalia, fils d’Amaria, fils d’Ezéchias, du temps de Josias fils d’Amon Roi de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Je ferai entièrement périr toutes choses de dessus cette terre, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Je ferai périr l’homme et le bétail; je consumerai les oiseaux des cieux, et les poissons de la mer; et les ruines arriveront aux méchants, et je retrancherai les hommes de dessus cette terre, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'J’étendrai ma main sur Juda, et sur tous les habitants de Jérusalem; je retrancherai de ce lieu-ci le reste des Bahalins, et les noms des prêtres des faux dieux, et les sacrificateurs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'Et ceux qui se prosternent sur les toits devant l’armée des cieux, et ceux qui se prosternent devant l’Eternel, jurent par lui, et qui jurent aussi par Malcam:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'Et ceux qui se détournent de l’Eternel, et ceux qui n’ont point cherché l’Eternel, qui ne l’ont point recherché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Tais-toi, à cause de la présence du Seigneur l’Eternel, car la journée de l’Eternel est proche; l’Eternel a préparé le sacrifice, il a invité ses conviés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Et il arrivera au jour du sacrifice de l’Eternel que je punirai les Seigneurs, et les enfants du Roi, et tous ceux qui s’habillent de vêtements étrangers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Et je punirai en ce jour-là tous ceux qui sautent par-dessus le seuil, et ceux qui remplissent de violence et de fraude la maison de leurs maîtres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'Et en ce jour-là dit l’Eternel, il y aura de grands cris vers la porte des poissons, et des hurlements vers la seconde ville, et une grande désolation vers les coteaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Vous qui habitez dans Mactès, hurlez; car tous ceux qui trafiquaient ont été défaits, et tous ceux qui apportaient de l’argent, ont été retranchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Et il arrivera en ce temps-là, que je fouillerai Jérusalem avec des lampes, que je punirai les hommes qui sont figés sur leurs lies, et qui disent en leurs coeurs; L’Eternel ne nous fera ni bien ni mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Et leurs biens seront au pillage, et leurs maisons en désolation, et ils auront bâti des maisons, mais ils n’y habiteront point; et ils auront planté des vignes, mais ils n’en boiront pas le vin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'La grande journée de l’Eternel est proche, elle est proche, et elle se hâte fort; la journée de l’Eternel n’est que bruit; celui qui est en amertume, crie de toute sa force; Là sont les hommes forts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Cette journée-là est une journée de fureur, une journée de détresse et d’angoisse, une journée de bruit éclatant et effrayant, une journée de ténèbres et d’obscurité, une journée de nuées et de brouillards;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'Une journée de cornet et d’alarme contre les villes munies, et contre les hautes tours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Je mettrai les hommes dans la détresse, et ils marcheront comme des aveugles, parce qu’ils ont péché contre l’Eternel; et leur sang sera répandu comme de la poussière, et leur chair comme de la fiente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Ni leur argent ni leur or ne les pourront point délivrer en la journée de la fureur de l’Eternel; et tout ce pays sera dévoré par le feu de sa jalousie; car il se hâtera de consumer tous les habitants de ce pays. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Examinez-vous, examinez-vous avec soin ô nation qui n’êtes pas aimable!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Avant que le décret enfante, et que le jour passe comme de la balle; avant que l’ardeur de la colère de l’Eternel vienne sur vous, avant que le jour de la colère de l’Eternel vienne sur vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Vous, tous les débonnaires du pays, qui faites ce qu’il ordonne, cherchez l’Eternel, cherchez la justice, cherchez la débonnaireté; peut-être serez-vous mis en sûreté au jour de la colère de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Mais Gaza sera abandonnée, et Askélon sera en désolation; on chassera les habitants d’Asdod en plein Midi, et Hékron sera arrachée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Malheur aux habitants de la contrée maritime, à la nation des Kéréthiens, la parole de l’Eternel est contre vous; Canaan, qui es le pays des Philistins, je te détruirai, tellement que personne n’y habitera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Et la contrée maritime ne sera que cabanes, que loges de bergers, et parcs de brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Et cette contrée sera pour le reste de la maison de Juda; ils paîtront dans ces lieux-là, et le soir ils feront leur gîte dans les maisons d’Askélon; car l’Eternel leur Dieu les visitera, et il ramènera leurs captifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'J’ai ouï les insultes de Moab, et les invectives des enfants de Hammon, dont ils ont diffamé mon peuple, et l’ont bravé sur leur frontière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'C’est pourquoi, je suis vivant, dit l’Eternel des armées, le Dieu d’Israël, que Moab sera comme Sodome, et les enfants de Mammon comme Gomorrhe, un lieu couvert d’orties, et une carrière de sel et de désolation à jamais; les restes de mon peuple les pilleront, et les restes de ma nation les posséderont.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Ceci leur arrivera en échange de leur orgueil, parce qu’ils ont usé d’insultes et de vanteries, contre le peuple de l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'L’Eternel sera terrible contre eux; car il amaigrira tous les dieux du pays; et on se prosternera devant lui, chacun de son lieu, même toutes les Iles des nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Vous aussi habitants de Cus, vous serez blessés à mort par mon épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Il étendra aussi sa main sur l’Aquilon, et il détruira l’Assyrie, et mettra Ninive en désolation, en un lieu aride comme un désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Et les troupeaux feront leur gîte au milieu d’elle, et toutes les bêtes des nations, même le cormoran, et le butor logeront dans ses porteaux, la voix des oiseaux retentira à la fenêtre, la désolation sera au seuil, parce qu’il en aura abbatu des cèdres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'C’est là cette ville remplie de joie, qui se tenait assurée, et qui disait en son coeur; c’est moi, et il n’y en a point d’autre que moi. Comment a-t-elle été réduite en désert, pour être le gîte des bêtes? Quiconque passera près d elle se moquera, et branlera sa main. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Malheur à la ville gloutonne, et souillée, et qui ne fait qu’opprimer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Elle n’a point écouté la voix; elle n’a point reçu d’instruction; elle ne s’est point confiée en l’Eternel; elle ne s’est point approchée de son Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Ses princes sont au-dedans d’elle des lions rugissants, et ses gouverneurs sont des loups du soir, qui ne quittent point les os pour les ronger au matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Ses prophètes sont des téméraires, et des hommes infidèles; ses sacrificateurs ont souillé les choses saintes, ils ont fait violence à la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'L’Eternel juste est au milieu d’elle, il ne fait point d’iniquité; chaque matin il met son jugement en lumière, sans que rien y manque; mais l’inique ne sait ce que c’est que d’avoir honte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'J’ai exterminé les nations, et leurs forteresses ont été désolées; j’ai rendu désertes leurs places, tellement que personne n’y passe; leurs villes ont été détruites, sans qu’il y soit resté un seul homme, et sans qu’il y ait aucun habitant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Et je disais; Au moins tu me craindras, tu recevras instruction, et sa demeure ne sera point retranchée, quelque punition que j’envoie sur elle; mais ils se sont levés de bon matin, ils ont corrompu toutes leurs actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'C’est pourquoi attendez-moi, dit l’Eternel, au jour que je me lèverai pour le dégât; car mon ordonnance est d’amasser les nations, et d’assembler les Royaumes, afin que je répande sur eux mon indignation, et toute l’ardeur de ma colère; car tout le pays sera dévoré par le feu de ma jalousie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Même alors je changerai aux peuples leurs lèvres, en des lèvres pures; afin qu’ils invoquent tous le Nom de l’Eternel, pour le servir d’un même esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Mes adorateurs qui sont au-delà des fleuves de Cus, savoir, la fille de mes dispersés, m’apporteront mes offrandes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'En ce jour-là tu ne seras plus confuse à cause de toutes tes actions, par lesquelles tu as péché contre moi; parce qu’alors j’aurai ôté du milieu de toi ceux qui se réjouissent de ton orgueil, et désormais tu ne t’enorgueilliras plus de la montagne de ma sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Et je ferai demeurer de reste au milieu de toi un peuple affligé et chétif, qui auront leur retraite vers le Nom de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Les restes d’Israël ne feront point d’iniquité, et ne proféreront point de mensonge, et il n’y aura point dans leur bouche de langue trompeuse; aussi ils paîtront, et feront leur gîte, et il n’y aura personne qui les épouvante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Réjouis-toi avec chant de triomphe, fille de Sion! Jette des cris de réjouissance, ô Israël! Réjouis-toi, et t’égaye de tout ton coeur, fille de Jérusalem!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'L’Eternel a aboli ta condamnation, il a éloigné ton ennemi; le Roi d’Israël, l’Eternel, est au milieu de toi; tu ne sentiras plus de mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'En ce temps-là, on dira à Jérusalem: Ne crains point, Sion, que tes mains ne soient point lâches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'L’Eternel ton Dieu est au milieu de toi; le Puissant te délivrera; il se réjouira à cause de toi d’une grande joie: Il se taira à cause de son amour, et il s’égayera à cause de toi avec chant de triomphe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Je rassemblerai ceux qui sont affligés à cause de l’assemblée assignée; ils sont sortis de toi; ce qui la surchargeait ne sera qu’opprobre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Voici, je détruirai en ce temps-là tous ceux qui t’auront affligée; je délivrerai la boiteuse, je recueillerai celle qui avait été chassée, et je les ferai louer et devenir célèbres, dans tous les pays où ils auront été couverts de honte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'En ce temps-là je vous ferai retourner, et en ce temps-là je vous rassemblerai; car je vous rendrai célèbres et un sujet de louange parmi tous les peuples de la terre, quand je ramènerai vos captifs en votre présence; a dit l’Eternel. Retournez au Début This Website is Hosted by../../lilacsandbutterflies/images/EClilacsbanner.gif ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'La seconde année du Roi Darius, le premier jour du sixième mois, la parole de l’Eternel fut adressée par le moyen d’Aggée le Prophète, à Zorobabel, fils de Salathiel, Gouverneur de Judée, et à Jéhosuah, fils de Jéhotsadak, grand Sacrificateur, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Ainsi a parlé l’Erternel des armées, en disant: Ce peuple-ci a dit: Le temps n’est pas ecore venu, le temps de rebâtir la maison de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'C’est pourquoi la parole de l’Eternel a été adressée par le moyen d’Aggée le Prophète, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Est-il temps pour vous d’habiter dans vos maisons lambrissées, pendant que cette maison demeure désolée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Maintenat donc ainsi a dit l’Eternel des armées: Considérez attentivement votre conduite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Vous avez semé beaucoup, mais vous avez peu serré; vous avez mangé, mais non pas jusqu’à être rassasiés; vous avez bu, mais vous n’avez pas eu de quoi boire abondamment; vous avez été vêtus, mais non pas jusqu’à en être échauffés, et celui qui se loue, se loue pour mettre son salaire dans un sac percé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Ainsi a dit l’Eternel des armées: Pesez bien votre conduite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Montez à la montagne, apportez du bois, et bâtissez cette maison; et j’y prendrai mon plaisir, et je serai glorifié, a dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'On regardait à beaucoup, et voici, tout est revenu à peu; et vous l’avez apporté à la maison, et j’ai soufflé desssus; pourquoi? A cause de ma maison, dit l’Eternel des armées, laquelle demeure désolée, pendant que vous courez chacun à sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'A cause de cela les cieux se sont fermés sur nous pour ne point donner la rosée, et la terre a retenu son rapport.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Et j’ai appelé la sécheresse sur la terre, et sur les montagnes, et sur le froment, et sur le moût, et sur l’huile, et sur tout ce que la terre produit, et sur les hommes, et sur les bêtes, et sur tout le travail des mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Zorobabel donc, fils de Salathiel, et Jéhosuah, fils de Jéhotsadak, grand Sacrificateur, et tout le reste du peuple, entendirent la voix de l’Eternel leur Dieu, et les paroles d’Aggée le Prophète, ainsi que l’Eternel leur Dieu l’avait envoyé; et le peuple eut peur de la présence de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Et Aggée, Ambassadeur de l’Eternel, parla au peuple, suivant l’ambassade de l’Eternel, en disant: Je suis avec vous, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Et l’Eternel excita l’esprit de Zorobabel fils de Salathiel, Gouverneur de Juda, et l’esprit de Jéhosuah, fils de Jéhotsadak, grand Sacrificateur, et l’esprit de tout le reste du peuple; et ils vinrent, et travaillèrent à la maison de l’Eternel leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'Le vingt-quatrième jour du sixième mois, de la seconde année du Roi Darius. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Le vingt et unième jour du septième mois, la parole de l’Eternel fut adressée par le moyen d’Aggée le Prophète, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Parle maintenant à Zorobabel, fils de Salathiel, Gouverneur de Juda, et à Jéhosuah, fils de Jéhotsadak, grand Sacrificateur, et au reste du peuple, et leur dis:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Qui est celui qui est demeuré de reste d’entre vous, qui ait vu cette maison dans sa première gloire, et telle que vous la voyez maintenant? N’est-elle pas comme un rien devant vos yeux, au prix de celle-là?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Maintenant donc toi, Zorobabel, fortifie-toi, dit l’Eternel; aussi toi, Jéhosuah, fils de Jéhotsadak, grand Sacrificateur, fortifie toi; vous aussi, tout le peuple du pays, fortifiez-vous, dit l’Eternel, et travaillez, car je suis avec vous, dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'La parole de l’alliance que je traitai avec vous, quand vous sortîtes d’Egypte, et mon esprit demeurent au milieu de vous; ne craignez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Car ainsi a dit l’Eternel des armées: encore une fois, ce qui même sera dans peu de temps, j’ébranlerai les cieux et la terre, la mer, et le sec;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Et j’ébranlerai toutes les nations; et les désirés d’entre toutes les nations viendront; et je remplirai de gloire cette maison; a dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'L’argent est à moi, et l’or est à moi, dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'La gloire ce cette dernière maison-ci sera plus grande que celle de la première, a dit l’Eternel des armées, et je mettrai la paix en ce lieux-ci, dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Le vingt-quatrième jour du neuvième mois de la seconde année de Darius, la parole de l’Eternel fut adressée par le moyen d’Aggée le Prophète, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Ainsi a dit l’Eternel des armées: Interroge maintenant les Sacrificateurs touchant la loi, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Si quelqu’un porte au coin de son vêtement de la chair sanctifiée, et qu’il touche du coin de son vêtement à du pain, ou à quelque chose cuite, ou à du vin, ou à de l’huile, ou à quelque viande que ce soit, cela en sera-t-il sanctifié? Et les Sacrificateurs répondirent, et dirent: Non.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Alors Aggée dit: Si celui qui est souillé pour un mort touche toutes ces choses-là, ne seront-elles pas souillées? Et les Sacrificateurs répondirent, et dirent: Elles seront souillées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Alors Aggée répondit, et dit: Ainsi est ce peuple, et ainsi est cette nation devant ma face, dit l’Eternel; et ainsi est toute l’oeuvre de leurs mains; même ce qu’ils offrent ici, est souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Maintenant donc mettez ceci, je vous prie, dans votre coeur; depuis ce jour et au-dessus, avant qu’on remît pierre sur pierre au Temple de l’Eternel,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Avant cela, dis-je, quand on est venu à un monceau de blé, au lieu de vingt mesures, il ne s’y en est trouvé que dix; et quand on est venu au pressoir, au lieu de puiser du pressoir cinquante mesures, il ne s’y en est trouvé que vingt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Je vous ai frappés de brûlure, et de nielle, et de grêle dans tout le labeur de vos mains; et vous n’êtes point retournés à moi, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Mettez maintenant ceci dans votre coeur; depuis ce jour, et au- dessus, depuis, dis-je, le vingt-quatrième jour du neuvième mois, depuis ce jour-ci auquel les fondements du Temple de l’Eternel ont été jetés, mettez ceci dans votre coeur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Ce que vous avez semé est-il encore retourné au grenier? Même jusqu’à la vigne, et au figuier, et au grenadier, et à l’olivier, rien n’a rapporté; mais depuis ce jour-ci je donnerai la bénédiction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Et la parole de l’Eternel fut adressée pour la seconde fois à Aggée, le vingt-quatrième jour du mois, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Parle à Zorobabel, Gouverneur de Juda, en disant: J’ébranlerai les cieux et la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'Je renverserai le trône des Royaumes, je détruirai la force des Royaumes des Nations! je renverserai les chariots, et ceux qui montent dessus; et les chevaux, et ceux qui sont montés dessus, seront abattus, chacun par l’épée de son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'En ce temps là, dit l’Eternel des armées, je te prendrai, ô Zorobabel! fils de Salathiel, mon serviteur, dit l’Eternel, et je te mettrai comme un anneau de cachet; car je t’ai élu, dit l’Eternel des armées. Retournez au Début ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Le huitième mois de la seconde année de Darius, la parole de l’Eternel fut adressée à Zacharie, fils de Barachie, fils d’Hiddo, le Prophète, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'L’Eternel a été extrêmement indigné contre vos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'C’est pourquoi tu leur diras: Ainsi a dit l’Eternel des armées: Retournez-vous vers moi, dit l’Eternel des armées; et je me retournerai vers vous, dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Ne soyez point comme vos pères, auxquels les Prophètes qui ont été ci-devant criaient, en disant: Ainsi a dit l’Eternel des armées: Détournez-vous maintenant de votre mauvais train, et de vos mauvaises actions; mais ils n’ont pas écouté, et n’ont pas été attentifs à ce que je leur disais, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Vos pères où sont-ils? Et ces Prophètes-là devaient-ils vivre à toujours?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Cependant mes paroles et mes ordonnances que j’avais enjointes aux Prophètes mes serviteurs, n’ont-elles pas atteint vos pères? De sorte que, s’étant convertis, ils ont dit: Comme l’Eternel des armées avait pensé de nous faire selon notre train, et selon nos actions, ainsi nous a-t-il fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Le vingt-quatrième jour du onzième mois, qui est le mois de Sébat, en la seconde année de Darius, la parole de l’Eternel fut adressée à Zacharie, fils de Barachie, fils d’Hiddo, le Prophète, comme s’ensuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'J’eus de nuit une vision: et voici, un homme était monté sur un cheval roux, et il se tenait entre des myrtes qui étaient en un lieu profond; et après lui il y avait des chevaux roux, des chevaux pommelés et des blancs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Et je dis: Mon Seigneur! Que signifient ces choses? Et l’Ange qui parlait avec moi me dit: Je te montrerai ce que ces choses signifient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Et l’homme qui se tenait entre les myrtes, répondit, et dit: Ce sont ici ceux que l’Eternel a envoyés pour parcourir la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Et ils répondirent à l’Ange de l’Eternel qui se tenait entre les myrtes, et dirent: Nous avons parcouru la terre; et voici, toute la terre est habitée, et est en repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Alors l’Ange de l’Eternel répondit, et dit: Eternel des armées, jusqu’à quand n’auras-tu point compassion de Jérusalem et des villes de Juda, contre lesquelles tu as été indigné pendant ces soixante et dix années?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Et l’Eternel répondit à l’Ange qui parlait avec moi, de bonnes paroles, des paroles de consolation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Puis l’Ange qui parlait avec moi, me dit: Crie, en disant: Ainsi a dit l’Eternel des armées: Je suis ému d’une grande jalousie pour Jérusalem et pour Sion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'Et je suis extrêmement indigné contre les nations qui sont à leur aise; car j’étais indigné pour un peu de temps, et ils ont aidé au mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'C’est pourquoi ainsi a dit l’Eternel: Je me suis retourné vers Jérusalem par compassion, et ma maison sera rebâtie dans elle, dit l’Eternel des armées; et le niveau sera étendu sur Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Crie encore, en disant: Ainsi a dit l’Eternel des armées: Mes villes regorgeront encore de biens, et l’Eternel consolera encore Sion, et élira encore Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Puis j’élevai mes yeux, et regardai; et voici quatre cornes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'Alors je dis à l’Ange qui parlait avec moi: Que veulent dire ces choses? Et il me répondit: Ce sont les cornes qui ont dissipé Juda, Israël et Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Puis l’Eternel me montra quatre forgerons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'Et je dis: Que viennent faire ceux-ci? Et il répondit, et dit: Ce sont là les cornes qui ont dissipé Juda, tellement que personne ne levait la tête; mais ceux-ci sont venus pour les effrayer, et pour abattre les cornes des nations qui ont élevé la corne contre le pays de Juda, pour le dissiper. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'J’élevai encore mes yeux, et regardai; et voilà un homme qui avait à la main un cordeau à mesurer,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Auquel je dis: Où vas-tu? Et il me répondit: Je vais mesurer Jérusalem, pour voir quelle est sa largeur, et quelle est sa longueur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Et voici, l’Ange qui parlait avec moi sortit, et un autre Ange sortit au-devant de lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'Et lui dit: Cours, et parle à ce jeune homme-là, en disant: Jérusalem sera habitée sans murailles, à cause de la multitude d’hommes et de bêtes qui seront au milieu d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Mais je lui serai, dit l’Eternel, une muraille de feu tout autour, et je serai pour gloire au milieu d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Ha! Fuyez, fuyez hors du pays de l’Aquilon, dit l’Eternel: car je vous ai dispersés vers les quatre vents des cieux, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Ha! Sion qui demeures avec la fille de Babylone, sauve-toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Car ainsi a dit l’Eternel des armées, lequel après la gloire m’a envoyé vers les nations qui vous ont pillés, que qui vous touche, touche la prunelle de son oeil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Car voici, je vais lever ma main sur eux, et ils seront en proie à leurs serviteurs, et vous connaîtrez que l’Eternel des armées m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Réjouis-toi avec chant de triomphe, et t’égaye, fille de Sion; car voici, je viens, et j’habiterai au milieu de toi, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Et plusieurs nations se joindront à l’Eternel en ce jour-là, et deviendront mon peuple; et j’habiterai au milieu de toi; et tu sauras que l’Eternel des armées m’a envoyé vers toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Et l’Eternel héritera Juda pour son partage en la terre de sa sainteté, et il choisira encore Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Que toute chair se taise, devant la face de l’Eternel, car il s’est réveillé de la demeure de sa sainteté. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Puis l’Eternel me fit voir Jéhosuah, le grand Sacrificateur, se tenant debout devant l’Ange de l’Eternel; et Satan qui se tenait debout à sa droite, pour le contrarier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Et l’Eternel dit à Satan: Que l’Eternel te tance rudement, ô Satan! Que l’Eternel, dis-je, qui a élu Jérusalem, te tance rudement! N’est-ce pas ici ce tison qui a été retiré du feu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Or Jéhosuah était vêtu de vêtements sales, et il se tenait debout devant l’Ange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Et l’Ange prit la parole, et dit à ceux qui étaient debout devant lui: Otez de dessus lui ces vêtements sales. Et il dit à Jéhosuah: Regarde, j’ai fait passer de dessus toi ton iniquité, et je t’ai vêtu de nouveaux vêtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Et je dis: Qu’on lui mette une tiare nette sur sa tête; et on lui mit sur la tête une tiare nette; puis on le vêtit de vêtements, et l’Ange de l’Eternel était présent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Alors l’Ange de l’Eternel protesta à Jéhosuah, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Ainsi a dit l’Eternel des armées: Si tu marches dans mes voies, et que tu observes ce que je veux qui soit observé, tu auras la juridiction de ma maison, et tu garderas mes parvis, et je ferai que tu marcheras parmi ces assistants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Ecoute maintenant, Jéhosuah, grand Sacrificateur, toi, et tes compagnons qui sont assis devant toi, parce que ce sont des gens qu’on tient pour des monstres, certainement voici, je m’en vais faire venir Germe, mon serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Car voici, quant à la pierre que j’ai mise devant Jéhosuah, sur cette pierre, qui n’est qu’une, il y a sept yeux. Voici, je m’en vais graver sa gravure, dit l’Eternel des armées, et j’ôterai en un jour l’iniquité de ce pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'En ce jour-là, dit l’Eternel des armées, chacun de vous appellera son prochain sous la vigne et sous le figuier. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Puis l’Ange qui parlait avec moi retourna, et me réveilla comme un homme qu’on réveille de son sommeil;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'Et me dit: Que vois-tu? Et je répondis: Je regarde, et voilà un chandelier tout d’or, et un bassin au-dessus de son sommet, et ses sept lampes sont sur lui, avec sept tuyaux pour les sept lampes qui sont à son sommet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'Et il y a deux oliviers au-dessus, l’un à la droite du bassin, et l’autre à la gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Alors je pris la parole, et je dis à l’Ange qui parlait avec moi, ce qui s’ensuit: Mon Seigneur, que veulent dire ces choses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Et l’Ange qui parlait avec moi, répondit, et me dit: Ne sais-tu pas ce que veulent dire ces choses? Et je dis: Non, mon Seigneur!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Et il répondit, et me dit: C’est ici la parole de l’Eternel à Zorobabel, disant: Ce n’est point par armée, ni par force, mais par mon Esprit, a dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Qui es-tu, grande montagne, devant Zorobabel? Une plaine. Il tirera la pierre la plus haute; il y aura des sons éclatants; Grâce, Grâce pour elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Aussi la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Les mains de Zorobabel ont fondé cette maison, et ses mains l’achèveront; et tu sauras que l’Eternel des armées m’a envoyé vers vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Car qui est-ce qui a méprisé le temps des petits commencements? Vu que ces sept là, savoir, les yeux de l’Eternel qui vont çà et là par toute la terre, se réjouiront, et verront la pierre du niveau en la main de Zorobabel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Et je répondis, et lui dis: Que signifient ces deux oliviers, à la droite et à la gauche du chandelier?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Et je pris la parole pour la seconde fois, et lui dis: Que signifient ces deux branches d’olivier qui sont auprès des deux becs d’or, desquels l’or découle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Et il me répondit, et dit: Ne sais-tu pas ce que signifient ces choses? Et je dis: Non, mon Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Et il dit: Ce sont les deux fils de l’huile, qui se tiennent devant le Seigneur de toute la terre. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Puis je me retournai, et levai mes yeux pour regarder; et voici un rouleau volant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Alors il me dit: Que vois-tu? Et je répondis: Je vois un rouleau volant, dont la longueur est de vingt coudées, et sa largeur de dix coudées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Et il me dit: C’est là l’exécration du serment qui sort sur le dessus de toute la terre; car quiconque d’entre ce peuple-ci dérobe, sera puni comme elle; et quiconque d’entre ce peuple -ci jure, sera puni comme elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Je déploierai cette exécration, dit l’Eternel des armées, et elle entrera dans la maison du larron, et dans la maison de celui qui jure faussement par mon Nom, et elle logera au milieu de leur maison, et la consumera avec son bois et ses pierres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Et l’Ange qui parlait avec moi sortit, et me dit: Lève maintenant tes yeux, et regarde ce qui sort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Et je dis: Qu’est-ce? Et il répondit: C’est un Epha qui sort dehors. Puis il dit: C’est l’oeil que j’ai sur eux par toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Et voici, on portait une masse de plomb, et une femme était assise au milieu de l’Epha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Et il dit: C’est là la méchanceté; puis il la jeta au milieu de l’Epha, et mit la masse de plomb sur son ouverture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Puis levant mes yeux, je regardai, et voici deux femmes qui sortaient, et le vent soufflait dans leurs ailes; or elles avaient des ailes comme les ailes d’une cigogne; et elles enlevèrent l’Epha entre la terre et les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Et je dis à l’Ange qui parlait avec moi: Où emportent-elles l’Epha?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Et il me répondit: C’est pour lui bâtir une maison au pays de Sinhar laquelle étant établie, il sera là posé sur sa base. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Et j’élevai encore mes yeux, et regardai, et voici quatre chariots, qui sortaient d’entre deux montagnes; et ces montagnes étaient des montagnes d’airain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Au premier chariot il y avait des chevaux roux; au second chariot, des chevaux noirs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'Au troisième chariot, des chevaux blancs; au quatrième chariot, des chevaux cendrés, mouchetés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Et je pris la parole, et dis à l’Ange qui parlait avec moi: Mon Seigneur, que veulent dire ces choses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Et l’Ange répondit, et me dit: Ce sont les quatre vents des cieux qui sortent du lieu où ils se tenaient devant le Seigneur de toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Quant au chariot où sont les chevaux noirs, ils sortent vers le pays de l’Aquilon, et les blancs sortent après eux; mais les mouchetés sortent vers le pays du Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'Ensuite les cendrés sortirent, et demandèrent d’aller courir par la terre. Et il leur dit: Allez, et courez par la terre. Et ils coururent par la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Puis il m’appela, et me parla, en disant: Voici, ceux qui sortent vers le pays de l’Aquilon, ont fait reposer mon Esprit dans le pays de l’Aquilon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Et la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Prends de ceux qui sont de retour de la captivité, savoir, de chez Heldaï, de chez Tobija, et de chez Jédahïa; et viens ce même jour-là, et entre dans la maison de Josias fils de Sophonie, qui sont venus de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Et prends de l’argent et de l’or, et fais-en des couronnes, et les mets sur la tête de Jéhosuah, fils de Jéhotsadak, grand Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'Et parle-lui, en disant: Ainsi a parlé l’Eternel des armées, disant: Voici un homme, duquel le nom est Germe, qui germera de dessous soi, et qui bâtira le Temple de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Oui, lui-même bâtira le Temple de l’Eternel; et lui-même sera rempli de majesté, et sera assis, et dominera sur son trône, et sera Sacrificateur, étant sur son trône; et il y aura un conseil de paix entre les deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Et les couronnes seront à Hélem, et à Tobija, et à Jédahïa, et à Hen fils de Sophonie pour mémorial, dans le Temple de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Et ceux qui sont de loin viendront, et bâtiront au Temple de l’Eternel; et vous saurez que l’Eternel des armées m’a envoyé vers vous; et ceci arrivera si vous écoutez attentivement la voix de l’Eternel votre Dieu. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Puis il arriva la quatrième année du Roi Darius, que la parole de l’Eternel fut adressée à Zacharie le quatrième jour du neuvième mois, qui est le mois de Kisleu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'lorsqu’on eut envoyé Saretser, et Réguem-mélec et ses gens, à la maison du Dieu Fort, pour supplier l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'Et pour parler aux Sacrificateurs de la maison de l’Eternel des armées, et aux Prophètes, en disant: Pleurerai-je au cinquième mois, me tenant séparé, comme j’ai déjà fait pendant plusieurs années?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Et la parole de l’Eternel me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Parle à tout le peuple du pays, et aux Sacrificateurs, et leur dis: Quand vous avez jeûné, et pleuré au cinquième mois, et au septième, il y a déjà soixante et dix ans, avez-vous célébré ce jeûne pour l’amour de moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Et quand vous buvez et mangez, n’est-ce pas vous qui mangez, et vous qui buvez?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Ne sont-ce pas les paroles que l’Eternel a fait entendre par le moyen des Prophètes qui ont été ci-devant, lorsque Jérusalem était habitée et paisible, elle et ses villes qui sont autour d’elle, et lors qu’on habitait vers le midi, et dans la plaine?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Puis la parole de l’Eternel fut adressée à Zacharie, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Ainsi avait parlé l’Eternel des armées, en disant: Faites ce qui est vraiment juste, et exercez la miséricorde et la compassion chacun envers son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'Et ne faites point de tort à la veuve, ni à l’orphelin, ni à l’étranger, ni à l’affligé, et ne méditez aucun mal dans vos coeurs chacun contre son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Mais ils n’y ont point voulu entendre, et ont tiré l’épaule en arrière, et ils ont appesanti leurs oreilles pour ne point ouïr.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'Et ils ont rendu leur coeur dur comme le diamant, pour ne point écouter la Loi, et les paroles que l’Eternel des armées envoyait par son Esprit, par le moyen des Prophètes qui ont été ci-devant; c’est pourquoi il y a eu une grande indignation de par l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Et il est arrivé, que comme quand on leur a crié, ils n’ont point écouté; ainsi, quand ils ont crié, je n’ai point écouté, a dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'Et je les ai dispersés comme par un tourbillon parmi toutes les nations qu’ils ne connaissaient point, et le pays a été désolé après eux, tellement qu’il n’y a eu personne qui y passât, ni repassât, et on a mis le pays désirable en désolation. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'La parole de l’Eternel des armées me fut encore adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'Ainsi a dit l’Eternel des armées: J’ai été jaloux pour Sion d’une grande jalousie, et j’ai été jaloux pour elle avec une grande indignation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Ainsi a dit l’Eternel: Je me suis retourné vers Sion, et j’habiterai au milieu de Jérusalem; et Jérusalem sera appelée, Ville de vérité; et la montagne de l’Eternel des armées sera appelée, montagne de sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Ainsi a dit l’Eternel des armées: Il demeurera encore des vieillards et des vieilles femmes dans les places de Jérusalem, et chacun aura son bâton à la main à cause de son grand âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Et les place de la ville seront remplies de fils et de filles, qui se joueront dans ses places.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Ainsi a dit l’Eternel des armées: S’il semble difficile devant les yeux du reste de ce peuple, que cela arrive en ces jours-là, sera- t-il pourtant difficile devant mes yeux, Dit l’Eternel des armées?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Ainsi a dit l’Eternel des armées: Voici, je m’en vais délivrer mon peuple du pays de l’Orient, et du pays du soleil couchant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'Et je les ferai venir et ils habiteront dans Jérusalem, et ils seront mon peuple, et je serai leur Dieu en vérité et en justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Ainsi a dit l’Eternel des armées: Vous qui entendez en ces jours- ci ces paroles de la bouche des Prophètes qui ont été au jour que la maison de l’Eternel a été fondée, et le Temple rebâti, que vos mains soient fortifiées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Car avant ces jours-ci il n’y avait point de salaire pour l’homme, ni de salaire pour la bête; et il n’y avait point de paix pour les allants, ni pour les venants, à cause de la détresse, et j’envoyais tous les hommes l’un contre l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Mais maintenant je ne ferai point à ceux qui sont restés de ce peuple, comme j’ai fait les jours précédents; dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Mais ce qu’ils sèmeront sera une semence de prospérité, la semence de paix sera là; la vigne rendra son fruit, et la terre donnera son rapport; les cieux donneront leur rosée, et je ferai hériter toutes ces choses à ceux qui seront restés de ce peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'Et il arrivera, ô maison de Juda et maison d’Israël! Que comme vous avez été en malédiction parmi les nations, ainsi je vous en délivrerai, et vous serez en bénédiction; ne craignez point, mais que vos mains soient fortifiées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Car ainsi a dit l’Eternel des armées: Comme j’ai pensé de vous affliger, quand vos pères ont provoqué mon indignation, dit l’Eternel des armées, et je ne m’en suis point repenti;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'Ainsi au contraire je me suis retourné, et j’ai pensé en ces jours-ci de faire du bien à Jérusalem, et à la maison de Juda; ne craignez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Et ce sont ici les choses que vous devez faire: Parlez en vérité, chacun avec son prochain; prononcez la vérité et un jugement de paix dans vos portes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'Et que personne ne machine du mal dans son coeur contre son prochain; et n’aimez point le faux serment: car ce sont là des choses que je hais, dit l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Puis la parole de l’Eternel des armées me fut adressée, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'Ainsi a dit l’Eternel des armées: Le jeûne du quatrième mois, et le jeûne du cinquième, et le jeûne du septième, et le jeûne du dixième, seront changés pour la maison de Juda en joie et en allégresse, et en des fêtes solennelles de réjouissance; aimez donc la vérité et la paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Ainsi a dit l’Eternel des armées: Encore il arrivera que les peuples et les habitants de plusieurs villes viendront;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'Et que les habitants de l’une iront à l’autre, en disant: Allons, allons supplier l’Eternel, et rechercher l’Eternel des armées; Je m’y en irai moi aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Ainsi plusieurs peuples, et de puissantes nations viendront rechercher l’Eternel des armées à Jérusalem, et y supplier l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Ainsi a dit l’Eternel des armées: Il arrivera en ces jours-là que dix hommes de toutes les langues des nations empoigneront et tiendront ferme le pan de la robe d’un Juif, en disant: Nous irons avec vous; car nous avons entendu que Dieu est avec vous. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'La charge de la Parole de l’Eternel contre le pays de Hadrac, laquelle se posera sur Damas; car l’Eternel a l’oeil sur les hommes et sur toutes les Tribus d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'Même aussi Hamath, et Tyr, et Sidon, en seront bornées, quoique chacune d’elles soit fort sage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Car Tyr s’est bâti une forteresse, et a amoncelé l’argent comme de la poussière; et le fin or, comme la boue des rues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Voici, le Seigneur l’appauvrira, et en la frappant il jettera sa puissance dans la mer, et elle sera consumée par le feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Askelon le verra, et craindra; Gaza aussi le verra, et en sera comme en travail d’enfant; et Hékron aussi, parce que ce à quoi elle regardait, l’aura rendue confuse; et il n’y aura plus de Roi à Gaza, et Askelon ne fleurira plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'Et le bâtard habitera à Asdod; et je retrancherai l’orgueil des Philistins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Mais j’ôterai leur sang de la bouche de chacun d’eux, et leurs abominations d’entre leurs dents; et lui aussi sera réservé pour notre Dieu, qui sera comme chef dans Juda, et Hékron sera comme le Jébusien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Et je me camperai autour de ma maison, à cause de l’armée, et à cause des allants et venants; et l’exacteur ne passera plus parmi eux; car maintenant je la regarde de mes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Que ta joie soit vive, fille de Sion! Jette des cris de réjouissance, fille de Jérusalem! Voici, ton Roi viendra à toi, étant juste, et qui se garantit par soi même, abject, et monté sur un âne, et sur un ânon, poulain d’une ânesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Et je retrancherai d’Ephraïm les chariots, et de Jérusalem les chevaux; et l’arc de la bataille sera aussi retranché, et le Roi parlera de paix aux nations; et sa domination s’étendra depuis une mer jusqu’à l’autre mer, et depuis le fleuve jusqu’aux bouts de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Quant à toi aussi à cause du sang de ton alliance, je mettrai tes prisonniers hors de la fosse où il n’y a point d’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Retournez à la forteresse, vous prisonniers qui avez espérance, même aujourd’hui je t’annonce que je te rendrai le double.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Après que je me serai tendu Juda comme un arc, et que j’aurai rempli Ephraïm comme un carquois, et que j’aurai, ô Sion! Réveille tes enfants contre tes enfants, ô Javan! Et que je t’aurai mis comme l’épée d’un puissant homme;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Alors l’Eternel se montrera contre eux, et ses dards partiront comme l’éclair, et le Seigneur l’Eternel, sonnera du cor, et marchera avec les tourbillons du Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'L’Eternel des armées sera leur protecteur, et ils mangeront après avoir subjugué ceux qui tirent les pierres de fronde; ils boiront en menant du bruit comme des hommes ivres, ils se rempliront de vin comme un bassin, et comme les coins de l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Et l’Eternel leur Dieu les délivrera en ce jour-là comme étant le troupeau de son peuple; même des pierres couronnées seront élevées sur sa terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Car combien sera grande sa bonté, et sa beauté? Le froment fera croître les jeunes hommes, et le vin doux rendra ses vierges éloquentes. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Demandez de la pluie à l’Eternel au temps de la pluie de la dernière saison, et l’Eternel fera des éclairs, et vous donnera une pluie abondante, et à chacun de l’herbe dans son champ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Car les Théraphims ont dit fausseté, et les devins ont vu le mensonge, ils ont proféré des songes vains, et ont donné des consolations vaines; c’est pourquoi on s’en est allé comme des brebis, et on a été abattu, parce qu’ il n’y avait point de pasteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Ma colère s’est embrasée contre ces pasteurs-là, et j’ai puni ces boucs; mais l’Eternel des armées a fait la revue de son troupeau, savoir, de la maison de Juda; et il les a rangés en bataille comme son cheval d’honneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'De lui est l’encoignure, de lui est le clou, de lui est l’arc de bataille, et pareillement de lui sortira tout exacteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'Mais ils seront comme des vaillants hommes qui foulent la boue des chemins dans la bataille, et ils combattront, parce que l’Eternel sera avec eux, et les gens de cheval seront confus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Car je renforcerai la maison de Juda, et je préserverai la maison de Joseph; et je les ramènerai, et les ferai habiter en repos, parce que j’aurai compassion d’eux, et ils seront comme si je ne les avais point rejetés; car je suis l’Eternel leur Dieu, et je les exaucerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Et ceux d’Ephraïm seront comme un vaillant homme, et leur coeur se réjouira comme par le vin; et ses fils le verront, et se réjouiront; leur coeur s’égayera en l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Je leur sifflerai, et je les rassemblerai, parce que je les aurai rachetés; et ils seront multipliés comme ils l’ont été auparavant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Et après que je les aurai semés entre les peuples, ils se souviendront de moi dans les pays éloignés, et ils vivront avec leurs fils, et retourneront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Ainsi je les ramènerai du pays d’Egypte, je les rassemblerai d’Assyrie, je les ferai venir au pays de Galaad, et au Liban, et il n’y aura point assez d’espace pour eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Et la détresse passera par la mer, et il y frappera les flots; et toutes les profondeurs du fleuve seront taries, et l’orgueil de l’Assyrie sera abattu, et le sceptre d’Egypte sera ôté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Et je les renforcerai en l’Eternel, et ils marcheront en son Nom, dit l’Eternel. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Liban, ouvre tes portes, et le feu consumera tes cèdres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Sapin, hurle; car le cèdre est tombé, parce que les choses magnifiques ont été ravagées; chênes de Basan, hurlez, car la forêt qui était comme une place forte, a été coupée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Il y a un cri de hurlement des pasteurs, parce que leur magnificence a été ravagée, il y a un cri de rugissement des lionceaux, parce que l’orgueil du Jourdain a été ravagé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Ainsi a dit l’Eternel mon Dieu: Pais les brebis exposées à la tuerie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'Que leurs possesseurs tuent, sans qu’on les en tienne pour coupables, et chaque vendeur desquelles dit: Béni soit l’Eternel, je suis enrichi: Et, pas un de leurs pasteurs ne les épargne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Certes aussi je n’aurai plus pitié de ceux qui habitent dans le pays, dit l’Eternel; car voici, je ferai que chacun se trouvera entre les mains de son prochain, et entre les mains de son Roi, et ils fouleront le pays, et je ne le délivrerai point de leur main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Je me suis donc mis à paître les brebis exposées à la tuerie, qui sont véritablement les plus pauvres du troupeau. Puis je pris deux verges, dont j’appelai l’une Beauté; et l’autre, Cordon; et je me mis à paître les brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Et je supprimai trois pasteurs en un mois, car mon âme s’est ennuyée d’eux, et aussi leur âme s’était dégoûtée de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Et je dis: Je ne vous paîtrai plus; que ce qui meurt, meure; et que ce qui est supprimé, soit supprimé; et que celles qui seront de reste dévorent chacune la chair l’une de l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Puis je pris ma verge, appelée Beauté, et la mis en pièces pour rompre mon alliance que j’avais traitée avec tous ces peuples;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Et elle fut rompue en ce jour-là; et ainsi les plus pauvres du troupeau qui prennent garde à moi connurent que c’était la parole de l’Eternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Et je leur dis: S’il vous semble bon donnez- moi mon salaire; sinon, ne me le donnez pas: alors ils pesèrent mon salaire, qui fut trente pièces d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Et l’Eternel me dit: Jette-les pour un potier, ce prix honorable auquel j’ai été apprécié par eux; alors je pris les trente pièces d’argent, et les jetai dans la maison de l’Eternel, pour un potier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Puis je rompis ma seconde verge, appelée Cordon, pour rompre la fraternité entre Juda et Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Et l’Eternel me dit: Prends-toi encore l’équipage d’un pasteur insensé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Car voici, je m’en vais susciter un pasteur au pays, qui ne visitera point les brebis qui s’en vont perdues; il ne cherchera point celles qui sont délicates, il ne guérira point celles qui sont malades, et il ne portera point celles qui sont demeurées en arrière, mais il mangera la chair des plus grasses, et fendra leurs ongles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Malheur au pasteur inutile, qui abandonne le troupeau; L’épée sera sur son bras, et sur son oeil droit; son bras séchera certainement, et son oeil droit sera entièrement obscurci. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'La charge de la parole de l’Eternel, touchant Israël; l’Eternel, qui étend les cieux, et qui fonde la terre, et qui forme l’esprit de l’homme au-dedans de lui, a dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Voici, je ferai que Jérusalem sera une coupe d’étourdissement à tous les peuples d’alentour; et même elle sera une occasion de siège contre Juda et contre Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'Et il arrivera en ce temps-là, que je ferai que Jérusalem sera une pierre pesante à tous les peuples; tous ceux qui s’en chargeront, en seront entièrement écrasés, car toutes les nations de la terre s’assembleront contre elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'En ce temps-là, dit l’Eternel, je frapperai d’étourdissement tout cheval, et de folie l’homme qui sera monté dessus; et j’ouvrirai mes yeux sur la maison de Juda, et je frapperai d’aveuglement tous les chevaux des peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Et les Conducteurs de Juda diront en leur coeur; Les habitants de Jérusalem sont ma force de par l’Eternel des armées, leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'En ce temps-là je ferai que les Conducteurs de Juda seront comme un foyer de feu parmi du bois, et comme un flambeau de feu parmi des gerbes, et ils dévoreront à droite et à gauche tous les peuples d’alentour; et Jérusalem sera encore habitée en sa place, à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Et l’Eternel garantira les tabernacles de Juda avant toutes choses, afin que la gloire de la maison de David, et la gloire des habitants de Jérusalem ne s’élève point par-dessus Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'En ce temps-là l’Eternel sera le protecteur des habitants de Jérusalem; et le plus faible d’entre eux sera en ce temps-là comme David, et la maison de David sera comme des Anges, comme l’Ange de l’Eternel devant leur face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'Et il arrivera qu’en ce temps-là je chercherai à détruire toutes les nations qui viendront contre Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Et je répandrai sur la maison de David, et sur les habitants de Jérusalem, l’Esprit de grâce et de supplications; et ils regarderont vers moi, qu’ils auront percé, et ils en mèneront deuil, comme quand on mène deuil d’un fils unique, et ils en seront en amertume, comme quand on est en amertume à cause d’un premier-né.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'En ce jour-là il y aura un grand deuil à Jérusalem, tel que fut le deuil d’Hadadrimmon dans la plaine de Méguiddon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Et la terre mènera deuil, chaque famille à part: la famille de la maison de David à part, et les femmes de cette maison-là à part; la famille de la maison de Nathan à part, et les femmes de cette maison- là à part.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'La famille de la maison de Lévi à part, et les femmes de cette maison-là à part; la famille de Simhi à part, et ses femmes à part.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'Toutes les familles qui seront restées, chaque famille à part, et leurs femmes à part. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'En ce temps-là il y aura une source ouverte en faveur de la maison de David, et des habitants de Jérusalem, pour le péché, et pour la souillure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'Il arrivera aussi en ce temps-là, dit l’Eternel des armées, que je retrancherai du pays les noms des faux dieux; et on n’en fera plus mention; j’ôterai aussi du pays les faux prophètes, et l’esprit d’impureté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'Et il arrivera que quand quelqu’un prophétisera dorénavant, son père et sa mère qui l’auront engendré, lui diront: Tu ne vivras plus; car tu as prononcé des mensonges au Nom de l’Eternel; et son père et sa mère qui l’auront engendré, le transperceront quand il prophétisera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'Et il arrivera en ce temps-là que ces prophètes seront confus chacun de sa vision, quand il aura prophétisé; et ils ne seront plus vêtus de manteau de poil, pour mentir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Et il dira: Je ne suis point prophète, mais je suis un laboureur; car on m’a appris à gouverner du bétail dès ma jeunesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'Et on lui dira: Que veulent donc dire ces blessures en tes mains? Et il répondra: Ce sont celles qui m’ont été faites dans la maison de mes amis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Epée, réveille-toi sur mon Pasteur, et sur l’homme qui est mon compagnon, dit l’Eternel des armées; frappe le Pasteur, et les brebis seront dispersées, et je tournerai ma main sur les petits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Et il arrivera dans toute la terre, dit l’Eternel, que deux parties seront retranchées en elle, et défaudront, mais la troisième y demeurera de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Et j’amènerai la troisième partie au feu, je les affinerai comme on affine l’argent, et je les éprouverai comme on éprouve l’or, chacun d’eux invoquera mon Nom, et je l’exaucerai; je dirai: C’est ici mon peuple; et il dira: L’Eternel est mon Dieu. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Voici, il vient un jour pour l’Eternel, et tes dépouilles seront partagées au milieu de toi, Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'J’assemblerai donc toutes les nations en bataille contre Jérusalem, et la ville sera prise, et les maisons pillées, et les femmes violées, et la moitié de la ville sortira en captivité, mais le reste du peuple ne sera point retranché de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Car l’Eternel sortira, et combattra contre ces nations-là, comme il a combattu au jour de la bataille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Et ses pieds se tiendront debout en ce jour-là sur la montagne des Oliviers, qui est vis-à-vis de Jérusalem, du côté d’orient; et la montagne des Oliviers sera fendue par le milieu, vers l’Orient et l’Occident, de sorte qu’il y aura une très-grande vallée; et une moitié de la montagne se retirera vers l’Aquilon, et l’autre moitié vers le Midi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Et vous fuirez par cette vallée de montagnes; car il fera joindre cette vallée de montagnes jusqu’à Atsal; et vous fuirez comme vous vous enfuites de devant le tremblement de terre, aux jours d’Hozias Roi de Juda; alors l’Eternel mon Dieu viendra, et tous les saints seront avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'Et il arrivera qu’en ce jour-là, la lumière précieuse ne sera pas mêlée de ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Mais le jour sera sans mélange, lequel sera connu de l’Eternel: Il n’y aura point une alternative de jour et de nuit, mais au temps du soir il y aura de la lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'Et il arrivera qu’en ce jour-là des eaux vives sortiront de Jérusalem; la moitié d’elles ira vers la mer d’Orient; et l’autre moitié, vers la mer d’Occident; il y en aura en été et en hiver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Et l’Eternel sera Roi sur toute la terre; en ce jour-là il n’y aura qu’un seul Eternel, et son nom ne sera qu’un.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Et toute la terre deviendra comme la campagne depuis Guébah jusqu’à Rimmon, vers le Midi de Jérusalem, laquelle sera exaltée et habitée en sa place, depuis la porte de Benjamin, jusqu’à l’endroit de la première porte, et jusqu’à la porte des encoignures, et depuis la tour de Hananéel, jusqu’aux pressoirs du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'On y demeurera, et il n’y aura plus d’interdit, mais Jérusalem sera habitée en sûreté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Or ce sera ici la plaie de laquelle l’Eternel frappera tous les peuples qui auront fait la guerre contre Jérusalem; il fera que la chair de chacun se fondra, eux étant sur leurs pieds; et leurs yeux se fondront dans leurs orbites, et leurs langues se fondront dans leur bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'Et il arrivera en ce jour-là qu’il y aura un grand trouble entre eux par l’Eternel; car chacun saisira la main de son prochain, et la main de l’un s’élèvera contre la main de l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Juda aussi combattra à Jérusalem, et les richesses de toutes les nations d’alentour y seront assemblées: l’or, et l’argent, et des vêtements en très grand nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Aussi la plaie des chevaux, des mulets, des chameaux et des ânes, et de toutes les bêtes qui seront en ces champs-là, sera telle que la plaie précédente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Et il arrivera que tous ceux qui seront restés de toutes les nations venues contre Jérusalem, monteront en foule chaque année pour se prosterner devant le Roi, l’Eternel des armées, et pour célébrer la fête des Tabernacles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Et il arrivera que quiconque d’entre les familles de la terre ne sera point monté à Jérusalem, pour se prosterner devant le Roi, l’Eternel des armées, il n’y aura point de pluie sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'Et si la famille d’Egypte n’y monte point, et qu’elle n’y vienne point, quoiqu’il n’y ait point de pluie sur eux, ils seront frappés de cette plaie dont l’Eternel frappera les nations qui ne seront point montées pour célébrer la fête des Tabernacles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Tel sera le péché d’Egypte, et le péché de toutes les nations qui ne seront point montées pour célébrer la fête des Tabernacles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'En ce temps-là il sera écrit sur les sonnettes des chevaux: LA SAINTETÉ A L’ETERNEL; et il y aura des chaudières dans la maison de l’Eternel, autant que de bassins devant l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Et toute chaudière qui sera dans Jérusalem et en Juda, sera sainteté à l’Eternel des armées; et tous ceux qui sacrifieront, viendront, et en prendront, et y cuiront; et il n’y aura plus en ce jour-là de Cananéen dans la maison de l’Eternel des armées. Retournez au Début ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'La charge de la parole de l’Eternel contre Israël, par le moyen de Malachie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Je vous ai aimés, a dit l’Eternel; et vous avez dit: En quoi nous as-tu aimés? Esaü n’était-il pas frère de Jacob, dit l’Eternel? Or j’ai aimé Jacob;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'Mais j’ai haï Esaü, et j’ai mis ses montagnes en désolation, et son héritage pour les dragons du désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Que si Edom dit: Nous avons été appauvris, mais nous retournerons, et rebâtirons les lieux ruinés, l’Eternel des armées dit ainsi: Ils rebâtiront, mais je détruirai, et on les appellera: Pays de méchanceté, et le peuple contre lequel l’Eternel est indigné à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Vos yeux le verront, et vous direz: L’Eternel se magnifie sur ceux qui sont aux frontières d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Le fils honore le père, et le serviteur son Seigneur; si donc je suis Père, où est l’honneur qui m’appartient? et si je suis Seigneur, où est la crainte qu’on a de moi? a dit l’Eternel des armées, à vous Sacrificateurs, qui méprisez mon Nom. Et vous avez dit: En quoi avons-nous méprisé ton Nom?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Vous offrez sur mon autel du pain souillé, et vous dites: En quoi t’avons-nous déshonoré? C’est en ce que vous dites: La table de l’Eternel est contemplative.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Et quand vous amenez une bête aveugle pour la sacrifier, n’y a-t-il point de mal en cela? Et quand vous l’amenez boiteuse ou malade, n’y a-t-il point de mal en cela? Présente-la à ton Gouverneur, t’en saura-t-il gré, ou te recevra-t-il favorablement? a dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Maintenant donc suppliez le Dieu Fort, afin qu’il ait pitié de nous; cela venant de votre main, vous recevra-t-il favorablement? a dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Qui est aussi celui d’entre vous qui ferme les portes? car n’est- ce pas en vain que vous faites brûler le feu sur mon autel? Je ne prends point de plaisir en vous, a dit l’Eternel des armées; et je n’aurai point pour agréable l’oblation de vos mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Mais depuis le soleil levant jusqu’au soleil couchant, mon Nom sera grand parmi les nations, et en tous lieux on offrira à mon Nom le parfum, et une oblation pure; car mon Nom sera grand parmi les nations, a dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Mais vous l’avez profané, en disant: La table de l’Eternel est souillée, elle et ce qui en revient; sa viande est méprisable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Vous dites aussi: Voici, ô que de travail! et vous soufflez dessus, a dit l’Eternel des armées. Vous amenez ce qui a été dérobé, ce qui est boiteux, et malade, vous l’amenez, dis-je, pour m’être offert. Accepterai-je cela de vos mains, a dit l’Eternel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'C’est pourquoi, maudit soit l’homme trompeur, qui ayant un mâle en son troupeau, et faisant un voeu, sacrifie à l’Eternel ce qui est défectueux; car je suis un grand Roi, a dit l’Eternel des armées, et mon Nom est redouté parmi les nations. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Or c’est maintenant à vous, Sacrificateurs, que s’adresse ce commandement:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Si vous n’écoutez point, et que vous ne preniez point à coeur de donner gloire à mon Nom, dit l’Eternel des armées, j’enverrai sur vous la malédiction, et je maudirai vos bénédictions; et déjà même je les ai maudites, parce que vous ne prenez point cela à coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Voici, je m’en vais tancer rudement votre postérité, et je répandrai la fiente de vos victimes sur vos visages, la fiente, dis-je, de vos solennités; et elle vous emportera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Alors vous saurez que je vous avais adressé ce commandement, que mon alliance fût avec Lévi; a dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Mon alliance de vie et de paix était avec lui; et je les lui ai données, afin qu’il me révérât; et il m’a révéré, et a été effrayé de la présence de mon Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'La Loi de vérité a été dans sa bouche, et il ne s’est point trouvé de perversité dans ses lèvres; il a marché avec moi dans la paix et dans la droiture, et il en a détourné plusieurs de l’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Car les lèvres du Sacrificateur gardaient la science, et on recherchait la Loi de sa bouche, parce qu’il était le messager de l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Mais vous vous êtes retirés de ce chemin-là, vous avez fait broncher plusieurs dans la Loi, et vous avez corrompu l’alliance de Lévi, a dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'C’est pourquoi je vous ai rendus méprisables et abjects à tout le peuple; car vous ne tenez point mes chemins, et vous avez égard à l’apparence des personnes en la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'N’avons-nous pas tous un même Père? Un seul Dieu Fort ne nous a-t-il pas créés? Pourquoi donc chacun agit-il perfidement contre son frère, en violant l’alliance de nos pères?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Juda a agi perfidement, et on a commis abomination dans Israël, et dans Jérusalem; car Juda a profané la sainteté de l’Eternel, qui l’aimait, et s’est marié à la fille d’un dieu étranger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'L’Eternel retranchera des tabernacles de Jacob quiconque aura fait cette chose-là, tant celui qui réveille que celui qui répond, et que celui qui présente l’oblation à l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Et voici une autre chose que vous faites: Vous couvrez l’autel de l’Eternel de larmes, de plaintes, et de gémissements, de sorte que je ne regarde plus à l’oblation, et que je ne prends rien à gré de ce qui vient de vos mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Et vous dites: Pourquoi? C’est parce que l’Eternel est intervenu comme témoin entre toi et la femme de ta jeunesse, contre laquelle tu agis perfidement; et toutefois elle est ta compagne, et la femme qui t’a été accordée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Or il n’en a fait qu’un; et néanmoins il y avait en lui abondance d’esprit. Mais pourquoi n’en a-t-il fait qu’un? C’est parce qu’il cherchait une postérité de Dieu. Gardez-vous donc dans votre esprit; et quant à la femme de ta jeunesse, prenez garde qu’on n’agisse point perfidement avec elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Car l’Eternel le Dieu d’Israël a dit qu’il hait qu’on la renvoie. Mais on couvre la violence sous sa robe, a dit l’Eternel des armées. Gardez-vous donc dans votre esprit, et n’agissez point en perfides.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Vous avez travaillé l’Eternel par vos paroles; vous avez dit: En quoi l’avons-nous travaillé? C’est quand vous dites: Quiconque fait du mal plaît à l’Eternel, et il prend plaisir à de telles gens. Autrement où est le Dieu du jugement? Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Voici, je m’en vais envoyer mon messager, et il préparera la voie devant moi, et incontinent le Seigneur que vous cherchez entrera dans son Temple, l’Ange, dis-je, de l’alliance, lequel vous souhaitez; voici, il vient, a dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Mais qui pourra soutenir le jour de sa venue? et qui pourra subsister quand il paraîtra? Car il sera comme le feu de celui qui raffine, et comme le savon des foulons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Et il sera assis comme celui qui raffine et qui purifie l’argent; il nettoiera les fils de Lévi, il les épurera comme l’or et l’argent; et ils présenteront à l’Eternel une oblation suivant la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'L’oblation de Juda et de Jérusalem sera agréable à l’Eternel, comme dans les jours d’autrefois, et comme dans les premières années.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Je m’approcherai de vous pour faire jugement, et je serai témoin subit contre les enchanteurs, et contre les adultères, et contre ceux qui jurent faussement, et contre ceux qui fraudent le loyer du mercenaire, qui oppriment la veuve et l’orphelin, et qui font tort à l’étranger, et qui ne me craignent point, a dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Parce que je suis l’Eternel, et que je n’ai point changé, à cause de cela, enfants de Jacob, vous n’avez point été consumés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Depuis le temps de vos pères vous vous êtes détournés de mes statuts, et ne les avez point gardés. Retournez-vous vers moi, et je me retournerai vers vous, a dit l’Eternel des armées. Et vous dites: En quoi nous convertirons-nous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'L’homme pillera-t-il Dieu, que vous me pilliez? Et vous dites: En quoi t’avons-nous pillé? Vous l’avez fait dans les dîmes et dans les offrandes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Vous êtes certainement maudits, parce que vous me pillez, vous toute la nation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Apportez toutes les dîmes aux lieux ordonnés pour les garder, et qu’il y ait provision dans ma maison; et dès maintenant éprouvez-moi en ceci, a dit l’Eternel des armées, si je ne vous ouvre les canaux des cieux, et si je ne répands en votre faveur la bénédiction, en sorte que vous n’y pourrez point suffire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Et je réprimerai pour l’amour de vous le dévorateur, et il ne vous ravagera point les fruits de la terre; et vos vignes ne seront point stériles dans la campagne, a dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'Toutes les nations vous diront heureux, parce que vous serez un pays souhaitable, a dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Vos paroles se sont renforcées contre moi, a dit l’Eternel; et vous dites: Qu’avons-nous donc dit contre toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Vous avez dit: C’est en vain qu’on sert Dieu, et qu’avons-nous gagné d’avoir gardé ce qu’il a commandé de garder, et d’avoir marché en pauvre état pour l’amour de l’Eternel des armées?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Et maintenant nous tenons pour heureux les orgueilleux; et même ceux qui commettent la méchanceté, sont avancés, et s’ils ont tenté Dieu, ils ont été délivrés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Alors ceux qui craignent l’Eternel ont parlé l’un à l’autre, et l’Eternel y a été attentif, et l’a ouï, et on a écrit un livre de mémoires, devant lui; pour ceux qui craignent l’Eternel, et qui pensent à son Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Et ils seront miens, a dit l’Eternel des armées, lorsque je mettrai à part mes plus précieux joyaux, et je leur pardonnerai, ainsi que chacun pardonne à son fils qui le sert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Convertissez-vous donc, et vous verrez la différence qu’il y a entre le juste et le méchant; entre celui qui sert Dieu et celui qui ne l’a point servi. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Car voici, le jour vient; ardent comme un four; tous les orgueilleux, et tous les méchants seront comme du chaume, et ce jour qui vient, a dit l’Eternel des armées, les embrasera, et ne leur laissera ni racine, ni rameau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Mais pour vous qui craignez mon Nom, se lèvera le Soleil de justice, et la santé sera dans ses rayons; vous sortirez, et vous acquerrez de l’embonpoint comme de jeunes boeufs que l’on engraisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'Et vous foulerez les méchants; car ils seront comme de la cendre sous les plantes de vos pieds, au jour que je ferai mon oeuvre, a dit l’Eternel des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Souvenez-vous de la Loi de Moïse mon serviteur, à qui je donnai en Horeb pour tout Israël des statuts et des jugements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Voici, je m’en vais vous envoyer Elie le Prophète, avant que le jour grand et terrible de l’Eternel vienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'Il convertira le coeur des pères envers les enfants, et le coeur des enfants, envers leurs pères, de peur que je ne vienne, et que je ne frappe la terre à la façon de l’interdit. Retournez au Début ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Le Livre de la Généalogie de Jésus-Christ, fils de David, fils d’Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham engendra Isaac; et Isaac engendra Jacob; et Jacob engendra Juda, et ses frères;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Et Juda engendra Pharès et Zara, de Thamar; et Pharès engendra Esrom; et Esrom engendra Aram;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Et Aram engendra Aminadab; et Aminadab engendra Naasson; et Naasson engendra Salmon;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Et Salmon engendra Booz, de Rachab; et Booz engendra Obed, de Ruth; et Obed engendra Jessé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Et Jessé engendra le Roi David; et le Roi David engendra Salomon, de celle qui avait été femme d’Urie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Et Salomon engendra Roboam; et Roboam engendra Abia; et Abia engendra Asa;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Et Asa engendra Josaphat; et Josaphat engendra Joram; et Joram engendra Hozias;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Et Hozias engendra Joatham; et Joatham engendra Achaz; et Achaz engendra Ezéchias;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Et Ezéchias engendra Manassé; et Manassé engendra Amon; et Amon engendra Josias;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Et Josias engendra Jakim; et Jakim engendra Jéchonias, et ses frères, vers le temps qu’ils furent transportés en Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Et après qu’ils eurent été transportés en Babylone, Jéchonias engendra Salathiël; et Salathiël engendra Zorobabel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Et Zorobabel engendra Abiud; et Abiud engendra Eliakim; et Eliakim engendra Azor;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Et Azor engendra Sadoc; et Sadoc engendra Achim; et Achim engendra Eliud;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Et Eliud engendra Eléazar; et Eléazar engendra Matthan; et Matthan engendra Jacob;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Et Jacob engendra Joseph, le mari de Marie, de laquelle est né Jésus, qui est appelé Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Ainsi toutes les générations depuis Abraham jusqu’à David, sont quatorze générations; et depuis David jusqu’au temps qu’ils furent transportés en Babylone, quatorze générations; et depuis qu’ils eurent été transportés en Babylone jusqu’à Christ, quatorze générations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Or la naissance de Jésus-Christ arriva en cette manière. Comme Marie sa mère eut été fiancée à Joseph, avant qu’ils fussent ensemble, elle se trouva enceinte par l’opération du Saint-Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Et Joseph son mari, parce qu’il était juste, et qu’il ne la voulait point diffamer, la voulut renvoyer secrètement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Mais comme il pensait à ces choses, voici, l’Ange du Seigneur lui apparut dans un songe, et lui dit: Joseph, fils de David, ne crains point de recevoir Marie ta femme; car ce qui a été conçu en elle est du Saint-Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Et elle enfantera un fils, et tu appelleras son nom Jésus; car il sauvera son peuple de leurs péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Or tout ceci est arrivé afin que fût accompli ce dont le Seigneur avait parlé par le Prophète, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, 'Voici, la Vierge sera enceinte, et elle enfantera un fils; et on appellera son nom Emmanuël, ce qui signifie, DIEU AVEC NOUS.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Joseph étant donc réveillé de son sommeil, fit comme l’Ange du Seigneur lui avait commandé, et reçut sa femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'Mais il ne la connut point jusqu’à ce qu’elle eût enfanté son fils premier- né; et il appela son nom Jésus. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Or Jésus étant né à Bethléhem, ville de Juda, au temps du Roi Hérode, voici arriver des Sages d’Orient à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'En disant: où est le Roi des Juifs qui est né? car nous avons vu son étoile en Orient, et nous sommes venus l’adorer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Ce que le Roi Hérode ayant entendu, il en fut troublé, et tout Jérusalem avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Et ayant assemblé tous les principaux Sacrificateurs, et les Scribes du peuple, il s’informa d’eux où le Christ devait naître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Et ils lui dirent: à Bethléhem, ville de Judée; car il est ainsi écrit par un Prophète:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'Et toi, Bethléhem, terre de Juda, tu n’es nullement la plus petite entre les Gouverneurs de Juda, car de toi sortira le Conducteur qui paîtra mon peuple d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Alors Hérode ayant appelé en secret les Sages, s’informa d’eux soigneusement du temps que l’étoile leur était apparue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'Et les envoyant à Bethléhem, il leur dit: Allez, et vous informez soigneusement touchant le petit enfant; et quand vous l’aurez trouvé, faites- le-moi savoir, afin que j’y aille aussi, et que je l’adore.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Eux donc ayant ouï le Roi, s’en allèrent, et voici, l’étoile qu’ils avaient vue en Orient allait devant eux, jusqu’à ce qu’elle vint et s’arrêta sur le lieu où était le petit enfant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Et quand ils virent l’étoile, ils se réjouirent d’une fort grande joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Et entrés dans la maison, ils trouvèrent le petit enfant avec Marie sa mère, lequel ils adorèrent, en se prosternant en terre; et après avoir déployé leurs trésors, ils lui offrirent des présents, savoir, de l’or, de l’encens et de la myrrhe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Puis étant divinement avertis dans un songe, de ne retourner point vers Hérode, ils se retirèrent en leur pays par un autre chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Or après qu’ils se furent retirés, voici, l’Ange du Seigneur apparut dans un songe à Joseph, et lui dit: lève-toi, et prends le petit enfant, et sa mère, et t’enfuis en Egypte, et demeure là, jusqu’à ce que je te le dise; car Hérode cherchera le petit enfant pour le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Joseph donc étant réveillé, prit de nuit le petit enfant, et sa mère, et se retira en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'Et il demeura là jusques à la mort d’Hérode; afin que fût accompli ce dont le Seigneur avait parlé par un Prophète, disant: J’ai appelé mon Fils hors d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Alors Hérode voyant que les Sages s’étaient moqués de lui, fut fort en colère, et il envoya tuer tous les enfants qui étaient à Bethléhem, et dans tout son territoire; depuis l’âge de deux ans, et au-dessous, selon le temps dont il s’était exactement informé des Sages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Alors fut accompli ce dont avait parlé Jérémie le Prophète, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'On a ouï à Rama un cri, une lamentation, des plaintes, et un grand gémissement: Rachel pleurant ses enfants, et n’ayant point voulu être consolée de ce qu’ils ne sont plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Mais après qu’Hérode fut mort, voici, l’Ange du Seigneur apparut dans un songe à Joseph, en Egypte,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'Et lui dit: lève-toi, et prends le petit enfant, et sa mère, et t’en va au pays d’Israël; car ceux qui cherchaient à ôter la vie au petit enfant sont morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Joseph donc s’étant réveillé, prit le petit enfant et sa mère, et s’en vint au pays d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Mais quand il eut appris qu’Archélaüs régnait en Judée, à la place d’Hérode son père, il craignit d’y aller; et étant divinement averti dans un songe, il se retira en Galilée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'Et y étant arrivé, il habita dans la ville appelée Nazareth; afin que fût accompli ce qui avait été dit par les Prophètes: il sera appelé Nazarien. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'Or, en ce temps-là vint Jean-Baptiste, prêchant dans le désert de la Judée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'Et disant: Convertissez-vous; car le Royaume des cieux est proche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Car c’est ici celui dont il a été parlé par Esaïe le Prophète, en disant: la voix de celui qui crie dans le désert est: préparez le chemin du Seigneur, aplanissez ses sentiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Or Jean avait son vêtement de poil de chameau, et une ceinture de cuir autour de ses reins, et son manger était des sauterelles et du miel sauvage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Alors les habitants de Jérusalem, et de toute la Judée, et de tout le pays des environs du Jourdain, vinrent à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'Et ils étaient baptisés par lui au Jourdain confessant leurs péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Mais voyant plusieurs des Pharisiens et des Saducéens venir à son baptême, il leur dit: race de vipères, qui vous a avertis de fuir la colère à venir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Faites donc des fruits convenables à la repentance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'Et ne présumez point de dire en vous-mêmes: nous avons Abraham pour père; car je vous dis que Dieu peut faire naître de ces pierres mêmes des enfants à Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Or la cognée est déjà mise à la racine des arbres; c’est pourquoi tout arbre qui ne fait point de bon fruit s’en va être coupé, et jeté au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Pour moi, je vous baptise d’eau en signe de repentance; mais celui qui vient après moi est plus puissant que moi, et je ne suis pas digne de porter ses souliers; celui-là vous baptisera du Saint-Esprit, et de feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Il a son van en sa main, et il nettoiera entièrement son aire, et il assemblera son froment au grenier; mais il brûlera la paille au feu qui ne s’éteint point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Alors Jésus vint de Galilée au Jourdain vers Jean pour être baptisé par lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Mais Jean l’en empêchait fort, en lui disant: J’ai besoin d’être baptisé par toi, et tu viens vers moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Et Jésus répondant lui dit: Laisse moi faire pour le présent: car il nous est ainsi convenable d’accomplir toute justice; et alors il le laissa faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Et quand Jésus eut été baptisé, il sortit incontinent hors de l’eau, et voilà, les cieux lui furent ouverts, et Jean vit l’Esprit de Dieu descendant comme une colombe, et venant sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Et voilà une voix du ciel, disant: Celui-ci est mon Fils bien-aimé, en qui j’ai pris mon bon plaisir. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Alors Jésus fut emmené par l’Esprit au désert, pour y être tenté par le diable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Et quand il eut jeûné quarante jours, et quarante nuits, finalement il eut faim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Et le Tentateur s’approchant, lui dit: Si tu es le Fils de Dieu, dis que ces pierres deviennent des pains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Mais Jésus répondit, et dit: Il est écrit: L’homme ne vivra point de pain seulement, mais de toute parole qui sort de la bouche de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Alors le diable le transporta dans la sainte ville, et le mit sur les créneaux du Temple;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'Et il lui dit: Si tu es le Fils de Dieu, jette-toi en bas; car il est écrit: Il ordonnera à ses Anges de te porter en leurs mains, de peur que tu ne heurtes ton pied contre quelque pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Jésus lui dit: il est aussi écrit: tu ne tenteras point le Seigneur ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Le diable le transporta encore sur une fort haute montagne, et lui montra tous les Royaumes du monde et leur gloire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'Et il lui dit: je te donnerai toutes ces choses, si en te prosternant en terre, tu m’adores.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Mais Jésus lui dit: va Satan: car il est écrit: Tu adoreras le Seigneur ton Dieu, et tu le serviras lui seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Alors le diable le laissa, et voilà, les Anges s’approchèrent, et le servirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Or Jésus ayant ouï dire que Jean avait été mis en prison, se retira en Galilée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Et ayant quitté Nazareth, il alla demeurer à Capernaüm, ville maritime, sur les confins de Zabulon, et de Nephthali.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'Afin que fût accompli ce dont il avait été parlé par Esaïe le Prophète, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, 'Le pays de Zabulon, et le pays de Nephthali, vers le chemin de la mer, au- delà du Jourdain, la Galilée des Gentils;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'Ce peuple, qui était assis dans les ténèbres, a vu une grande lumière; et à ceux qui étaient assis dans la région et dans l’ombre de la mort, la lumière s’est levée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Dès lors Jésus commença à prêcher, et à dire: Convertissez-vous: car le Royaume des cieux est proche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Et comme Jésus marchait le long de la mer de Galilée, il vit deux frères, savoir, Simon, qui fut appelé Pierre, et André son frère, qui jetaient leurs filets dans la mer: car ils étaient pêcheurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Et il leur dit: venez après moi, et je vous ferai pêcheurs d’hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Et ayant aussitôt quitté leurs filets, ils le suivirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Et de là étant allé plus avant, il vit deux autres frères, Jacques, fils de Zébédée, et Jean, son frère, dans une nacelle, avec Zébédée leur père, qui raccommodaient leurs filets, et il les appela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Et ayant aussitôt quitté leur nacelle, et leur père, ils le suivirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Et Jésus allait par toute la Galilée, enseignant dans leurs Synagogues, prêchant l’Evangile du Royaume, et guérissant toute sorte de maladies, et toute sorte de langueurs parmi le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Et sa renommée se répandit par toute la Syrie; et on lui présentait tous ceux qui se portaient mal, tourmentés de diverses maladies, les démoniaques, les lunatiques, les paralytiques; et il les guérissait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Et de grandes troupes de peuple le suivirent de Galilée, et de Décapolis, et de Jérusalem, et de Judée, et de delà le Jourdain. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Or Jésus voyant tout ce peuple, monta sur une montagne; puis s’étant assis, ses Disciples s’approchèrent de lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Et ayant commencé à parler, il les enseignait, de la sorte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Bienheureux sont les pauvres en esprit; car le Royaume des cieux est à eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Bienheureux sont ceux qui pleurent; car ils seront consolés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Bienheureux sont les débonnaires; car ils hériteront la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Bienheureux sont ceux qui sont affamés et altérés de la justice; car ils seront rassasiés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Bienheureux sont les miséricordieux; car la miséricorde leur sera faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Bienheureux sont ceux qui sont nets de coeur; car ils verront Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Bienheureux sont ceux qui procurent la paix; car ils seront appelés enfants de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Bienheureux sont ceux qui sont persécutés pour la justice; car le Royaume des cieux est à eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Vous serez bienheureux quand on vous aura injuriés et persécutés, et quand, à cause de moi, on aura dit faussement contre vous toute sorte de mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Réjouissez-vous, et tressaillez de joie; parce que votre récompense est grande dans les cieux; car on a ainsi persécuté les Prophètes qui ont été avant vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Vous êtes le sel de la terre; mais si le sel perd sa saveur, avec quoi le salera-t-on? il ne vaut plus rien qu’à être jeté dehors, et foulé des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Vous êtes la lumière du monde; une ville située sur une montagne ne peut point être cachée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Et on n’allume point la lampe pour la mettre sous un boisseau, mais sur un chandelier, et elle éclaire tous ceux qui sont dans la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Ainsi, que votre lumière luise devant les hommes, afin qu’ils voient vos bonnes oeuvres, et qu’ils glorifient votre Père qui est aux cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Ne croyez pas que je sois venu anéantir la Loi, ou les Prophètes; je ne suis pas venu les anéantir, mais les accomplir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Car je vous dis en vérité, que jusqu’à ce que le ciel et la terre soient passés, un seul Iota, ou un seul trait de lettre ne passera point, que toutes choses ne soient faites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Celui donc qui aura violé l’un de ces petits commandements, et qui aura enseigné ainsi les hommes, sera tenu le plus petit au Royaume des cieux; mais celui qui les aura faits et enseignés, sera tenu grand au Royaume des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Car je vous dis que si votre justice ne surpasse celle des Scribes et des Pharisiens, vous n’entrerez point dans le Royaume des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Vous avez entendu qu’il a été dit aux Anciens: Tu ne tueras point; et qui tuera, sera punissable par le jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Mais moi je vous dis: que quiconque se met en colère sans cause contre son frère, sera punissable par le jugement; et celui qui dira à son frère, Racha, sera punissable par le conseil; et celui qui lui dira, fou, sera punissable par la géhenne du feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Si donc tu apportes ton offrande à l’autel, et que là il te souvienne que ton frère a quelque chose contre toi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'Laisse-là ton offrande devant l’autel, et va te réconcilier premièrement avec ton frère, puis viens, et offre ton offrande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Sois bientôt d’accord avec ta partie adverse, tandis que tu es en chemin avec elle; de peur que ta partie adverse ne te livre au juge, et que le juge ne te livre au sergent, et que tu ne sois mis en prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'En vérité, je te dis, que tu ne sortiras point de là, jusqu’à ce que tu aies payé le dernier quadrin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Vous avez entendu qu’il a été dit aux Anciens: Tu ne commettras point adultère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Mais moi je vous dis, que quiconque regarde une femme pour la convoiter, il a déjà commis dans son coeur un adultère avec elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Que si ton oeil droit te fait broncher, arrache-le, et le jette loin de toi; car il vaut mieux qu’un de tes membres périsse, que si tout ton corps était jeté dans la géhenne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Et si ta main droite te fait broncher, coupe-la, et la jette loin de toi; car il vaut mieux qu’un de tes membres périsse, que si tout ton corps était jeté dans la géhenne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Il a été dit encore: si quelqu’un répudie sa femme, qu’il lui donne la Lettre de divorce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Mais moi je vous dis, que quiconque aura répudié sa femme, si ce n’est pour cause d’adultère, il la fait devenir adultère; et quiconque se mariera à la femme répudiée, commet un adultère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Vous avez aussi appris qu’il a été dit aux Anciens: tu ne te parjureras point, mais tu rendras au Seigneur ce que tu auras promis par jurement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Mais moi, je vous dis: ne jurez en aucune manière; ni par le ciel, car c’est le trône de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'Ni par la terre, car c’est le marchepied de ses pieds; ni par Jérusalem, parce que c’est la ville du grand Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Tu ne jureras point non plus par ta tête; car tu ne peux faire un cheveu blanc ou noir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Mais que votre parole soit: oui, oui; non, non; car ce qui est de plus, est mauvais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Vous avez appris qu’il a été dit: oeil pour oeil, et dent pour dent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Mais moi, je vous dis: ne résistez point au mal; mais si quelqu’un te frappe à ta joue droite, présente-lui aussi l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'Et si quelqu’un veut plaider contre toi, et t’ôter ta robe, laisse-lui encore le manteau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'Et si quelqu’un te veut contraindre d’aller avec lui une lieue, vas-en deux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Donne à celui qui te demande, et ne te détourne point de celui qui veut emprunter de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Vous avez appris qu’il a été dit: tu aimeras ton prochain, et tu haïras ton ennemi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Mais moi je vous dis: aimez vos ennemis, et bénissez ceux qui vous maudissent, faites du bien à ceux qui vous haïssent, et priez pour ceux qui vous courent sus, et vous persécutent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'Afin que vous soyez les enfants de votre Père qui est aux cieux; car il fait lever son soleil sur les méchants, et sur les gens de bien, et il envoie sa pluie sur les justes, et sur les injustes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Car si vous aimez seulement ceux qui vous aiment, quelle récompense en aurez-vous? Les péagers mêmes n’en font-ils pas tout autant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Et si vous faites accueil seulement à vos frères, que faites-vous plus que les autres? les péagers mêmes ne le font-ils pas aussi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Soyez donc parfaits, comme votre Père qui est aux cieux est parfait. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Prenez garde de ne faire point votre aumône devant les hommes, pour en être regardés; autrement vous n’en recevrez point la récompense de votre Père qui est aux cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Lors donc que tu feras ton aumône, ne fais point sonner la trompette devant toi, comme les hypocrites font dans les Synagogues, et dans les rues, pour en être honorés des hommes; en vérité je vous dis, qu’ils reçoivent leur récompense.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Mais quand tu fais ton aumône, que ta main gauche ne sache point ce que fait ta droite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'Afin que ton aumône soit dans le secret, et ton Père, qui voit ce qui se fait en secret t’en récompensera publiquement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Et quand tu prieras, ne sois point comme les hypocrites; car ils aiment à prier en se tenant debout dans les Synagogues et aux coins des rues, afin d’être vus des hommes; en vérité je vous dis, qu’ils reçoivent leur récompense.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Mais toi, quand tu pries, entre dans ton cabinet, et ayant fermé ta porte, prie ton Père, qui te voit dans ce lieu secret; et ton Père qui te voit dans ce lieu secret, te récompensera publiquement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Or quand vous priez, n’usez point de vaines redites, comme font les Païens; car ils s’imaginent d’être exaucés en parlant beaucoup.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Ne leur ressemblez donc point; car votre Père sait de quoi vous avez besoin, avant que vous le lui demandiez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Vous donc priez ainsi: notre Père qui es aux cieux, ton Nom soit sanctifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Ton Règne vienne. Ta volonté soit faite sur la terre comme au ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Donne-nous aujourd’hui notre pain quotidien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'Et nous quitte nos dettes, comme nous quittons aussi les dettes à nos débiteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'Et ne nous induis point en tentation; mais délivre-nous du mal. Car à toi est le règne, et la puissance, et la gloire à jamais. Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Car si vous pardonnez aux hommes leurs offenses, votre Père céleste vous pardonnera aussi les vôtres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Mais si vous ne pardonnez point aux hommes leurs offenses, votre Père ne vous pardonnera point non plus vos offenses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Et quand vous jeûnerez, ne prenez point un air triste, comme font les hypocrites; car ils se rendent tout défaits de visage, afin qu’il paraisse aux hommes qu’ils jeûnent; en vérité je vous dis, qu’ils reçoivent leur récompense.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Mais toi, quand tu jeûnes, oins ta tête, et lave ton visage;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'Afin qu’il ne paraisse point aux hommes que tu jeûnes, mais ton Père qui est présent dans ton lieu secret; et ton Père qui te voit dans ton lieu secret, te récompensera publiquement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Ne vous amassez point des trésors sur la terre, que les vers et la rouille consument et que les larrons percent et dérobent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Mais amassez-vous des trésors dans le ciel, où ni les vers ni la rouille ne consument rien, et où les larrons ne percent ni ne dérobent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Car où est votre trésor, là sera aussi votre coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'L’oeil est la lumière du corps; si donc ton oeil est net, tout ton corps sera éclairé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Mais si ton oeil est mal disposé, tout ton corps sera ténébreux; si donc la lumière qui est en toi, n’est que ténèbres, combien seront grandes les ténèbres mêmes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Nul ne peut servir deux maîtres; car, ou il haïra l’un, et aimera l’autre; ou il s’attachera à l’un, et méprisera l’autre; vous ne pouvez servir Dieu et Mammon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'C’est pourquoi je vous dis: ne soyez point en souci pour votre vie, de ce que vous mangerez, et de ce que vous boirez; ni pour votre corps, de quoi vous serez vêtus; la vie n’est-elle pas plus que la nourriture, et le corps plus que le vêtement?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Considérez les oiseaux du ciel; car ils ne sèment, ni ne moissonnent, ni n’assemblent dans des greniers, et cependant votre Père céleste les nourrit; n’êtes-vous pas beaucoup plus excellents qu’eux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Et qui est celui d’entre vous qui puisse par son souci ajouter une coudée à sa taille?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Et pourquoi êtes-vous en souci du vêtement? apprenez comment croissent les lis des champs; ils ne travaillent, ni ne filent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'Cependant je vous dis que Salomon même dans toute sa gloire n’a pas été vêtu comme l’un d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Si donc Dieu revêt ainsi l’herbe des champs, qui est aujourd’hui sur pied, et qui demain sera jetée au four, ne vous vêtira-t-il pas beaucoup plutôt, ô gens de petite foi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Ne soyez donc point en souci, disant: que mangerons-nous? ou que boirons- nous? ou de quoi serons-nous vêtus?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Vu que les Païens recherchent toutes ces choses; car votre Père céleste connaît que vous avez besoin de toutes ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Mais cherchez premièrement le Royaume de Dieu, et sa justice, et toutes ces choses vous seront données par-dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Ne soyez donc point en souci pour le lendemain; car le lendemain prendra soin de ce qui le regarde; à chaque jour suffit sa peine. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Ne jugez point, afin que vous ne soyez point jugés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Car de tel jugement que vous jugez, vous serez jugés; et de telle mesure que vous mesurerez, on vous mesurera réciproquement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Et pourquoi regardes-tu le fétu qui est dans l’oeil de ton frère, et tu ne prends pas garde à la poutre dans ton oeil?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Ou comment dis-tu à ton frère? Permets que j’ôte de ton oeil ce fétu, et voilà, tu as une poutre dans ton oeil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Hypocrite, ôte premièrement de ton oeil la poutre, et après cela tu verras comment tu ôteras le fétu de l’oeil de ton frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Ne donnez point les choses saintes aux chiens, et ne jetez point vos perles devant les pourceaux, de peur qu’ils ne les foulent à leurs pieds, et que se retournant, ils ne vous déchirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Demandez, et il vous sera donné; cherchez, et vous trouverez; heurtez, et il vous sera ouvert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Car quiconque demande, reçoit; et quiconque cherche, trouve; et il sera ouvert à celui qui heurte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Et qui sera l’homme d’entre vous qui donne une pierre à son fils, s’il lui demande du pain?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Et s’il lui demande un poisson, lui donnera-t-il un serpent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Si donc vous, qui êtes méchants, savez bien donner à vos enfants des choses bonnes, combien plus votre Père qui est aux cieux, donnera-t-il des biens à ceux qui les lui demandent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Toutes les choses donc que vous voulez que les hommes vous fassent, faites- les leur aussi de même, car c’est là la Loi et les Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Entrez par la porte étroite; car c’est la porte large et le chemin spacieux qui mène à la perdition, et il y en a beaucoup qui entrent par elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Car la porte est étroite, et le chemin est étroit qui mène à la vie, et il y en a peu qui le trouvent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Or gardez-vous des faux Prophètes, qui viennent à vous en habit de brebis, mais qui au-dedans sont des loups ravissants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Vous les connaîtrez à leurs fruits. Cueille-t-on les raisins à des épines, ou les figues à des chardons?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Ainsi tout bon arbre fait de bons fruits; mais le mauvais arbre fait de mauvais fruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Le bon arbre ne peut point faire de mauvais fruits, ni le mauvais arbre faire de bons fruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Tout arbre qui ne fait point de bon fruit est coupé, et jeté au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Vous les connaîtrez donc à leurs fruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Tous ceux qui me disent: Seigneur! Seigneur! n’entreront pas dans le Royaume des cieux; mais celui qui fait la volonté de mon Père qui est aux cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Plusieurs me diront en ce jour-là: Seigneur! Seigneur! n’avons-nous pas prophétisé en ton Nom? et n’avons-nous pas chassé les démons en ton Nom? et n’avons-nous pas fait plusieurs miracles en ton Nom?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Mais je leur dirai alors tout ouvertement: je ne vous ai jamais reconnus; retirez-vous de moi, vous qui vous adonnez à l’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Quiconque entend donc ces paroles que je dis, et les met en pratique, je le comparerai à l’homme prudent qui a bâti sa maison sur la roche;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'Et lorsque la pluie est tombée, et que les torrents sont venus, et que les vents ont soufflé, et ont donné contre cette maison, elle n’est point tombée, parce qu’elle était fondée sur la roche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Mais quiconque entend ces paroles que je dis, et ne les met point en pratique, sera semblable à l’homme insensé, qui a bâti sa maison sur le sable;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'Et lorsque la pluie est tombée, et que les torrents sont venus, et que les vents ont soufflé, et ont donné contre cette maison, elle est tombée, et sa ruine a été grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Or il arriva que quand Jésus eut achevé ce discours, les troupes furent étonnées de sa doctrine;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'Car il les enseignait comme ayant de l’autorité, et non pas comme les Scribes. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Et quand il fut descendu de la montagne, de grandes troupes le suivirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Et voici, un lépreux vint et se prosterna devant lui, en lui disant: Seigneur, si tu veux, tu peux me rendre net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Et Jésus étendant la main, le toucha, en disant: je le veux, sois net; et incontinent sa lèpre fut guérie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Puis Jésus lui dit: prends garde de ne le dire à personne; mais va, et te montre au Sacrificateur, et offre le don que Moïse a ordonné, afin que cela leur serve de témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Et quand Jésus fut entré dans Capernaüm, un Centenier vint à lui, le priant,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'Et disant: Seigneur, mon serviteur est paralytique dans ma maison, et il souffre extrêmement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Jésus lui dit: j’irai, et je le guérirai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Mais le Centenier lui répondit: Seigneur, je ne suis pas digne que tu entres sous mon toit; mais dis seulement la parole, et mon serviteur sera guéri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Car moi-même qui suis un homme constitué sous la puissance d’autrui, j’ai sous moi des gens de guerre, et je dis à l’un: va, et il va; et à un autre: viens, et il vient; et à mon serviteur: fais cela, et il le fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Ce que Jésus ayant entendu, il s’en étonna, et dit à ceux qui le suivaient: en vérité, je vous dis que je n’ai pas trouvé, même en Israël, une si grande foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Mais je vous dis que plusieurs viendront d’Orient et d’Occident, et seront à table dans le Royaume des cieux, avec Abraham, Isaac et Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Et les enfants du Royaume seront jetés dans les ténèbres de dehors, où il y aura des pleurs et des grincements de dents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Alors Jésus dit au Centenier: va, et qu’il te soit fait selon que tu as cru. Et à l’heure même son serviteur fut guéri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Puis Jésus étant venu dans la maison de Pierre, vit la belle-mère de Pierre qui était au lit, et qui avait la fièvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Et lui ayant touché la main, la fièvre la quitta; puis elle se leva, et les servit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Et le soir étant venu, on lui présenta plusieurs démoniaques, desquels il chassa par sa parole les esprits malins, et guérit tous ceux qui se portaient mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'Afin que fût accompli ce dont il avait été parlé par Esaïe le Prophète, en disant: il a pris nos langueurs, et a porté nos maladies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Or Jésus voyant autour de lui de grandes troupes, commanda de passer à l’autre rivage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Et un Scribe s’approchant, lui dit: Maître, je te suivrai partout où tu iras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Et Jésus lui dit: les renards ont des tanières, et les oiseaux du ciel ont des nids; mais le Fils de l’homme n’a pas où il puisse reposer sa tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Puis un autre de ses Disciples lui dit: Seigneur, permets-moi d’aller premièrement ensevelir mon père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Et Jésus lui dit: suis-moi, et laisse les morts ensevelir leurs morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Et quand il fut entré dans la nacelle, ses Disciples le suivirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Et voici, il s’éleva sur la mer une si grande tempête que la nacelle était couverte de flots; et Jésus dormait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Et ses Disciples vinrent, et l’éveillèrent, en lui disant: Seigneur, sauve- nous, nous périssons!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Et il leur dit: pourquoi avez-vous peur, gens de petite foi? Alors s’étant levé il parla fortement aux vents et à la mer, et il se fit un grand calme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Et les gens qui étaient là s’en étonnèrent, et dirent: qui est celui-ci que les vents même et la mer lui obéissent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Et quand il fut passé à l’autre côté, dans le pays des Gergéséniens, deux démoniaques étant sortis des sépulcres le vinrent rencontrer, et ils étaient si dangereux que personne ne pouvait passer par ce chemin-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Et voici, ils s’écrièrent, en disant: qu’y a-t-il entre nous et toi, Jésus Fils de Dieu? Es-tu venu ici nous tourmenter avant le temps?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Or il y avait un peu loin d’eux un grand troupeau de pourceaux qui paissait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Et les démons le priaient, en disant: si tu nous jettes dehors, permets- nous de nous en aller dans ce troupeau de pourceaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Et il leur dit: allez. Et eux étant sortis s’en allèrent dans le troupeau de pourceaux; et voilà, tout ce troupeau de pourceaux se précipita dans la mer, et ils moururent dans les eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Et ceux qui les gardaient s’enfuirent; et étant venus dans la ville, ils racontèrent toutes ces choses, et ce qui était arrivé aux démoniaques.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Et voilà, toute la ville alla au-devant de Jésus, et l’ayant vu, ils le prièrent de se retirer de leur pays. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Alors, étant entré dans la nacelle, il repassa la mer, et vint en sa ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Et voici, on lui présenta un paralytique couché dans un lit. Et Jésus voyant leur foi, dit au paralytique: aie bon courage, mon fils! tes péchés te sont pardonnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Et voici, quelques-uns des Scribes disaient en eux-mêmes: celui-ci blasphème.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Mais Jésus connaissant leurs pensées, leur dit: pourquoi pensez-vous du mal dans vos coeurs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Car lequel est le plus aisé, ou de dire? Tes péchés te sont pardonnés; ou de dire? Lève-toi, et marche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Or afin que vous sachiez que le Fils de l’homme a le pouvoir sur la terre de pardonner les péchés, il dit alors au paralytique: lève-toi, charge ton lit, et t’en va en ta maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Et il se leva, et s’en alla en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Ce que les troupes ayant vu, elles s’en étonnèrent, et elles glorifièrent Dieu de ce qu’il avait donné une telle puissance aux hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Puis Jésus passant plus avant, vit un homme, nommé Matthieu, assis au lieu du péage, et il lui dit: suis-moi; et il se leva, et le suivit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Et comme Jésus était à table dans la maison de Matthieu, voici plusieurs péagers, et des gens de mauvaise vie, qui étaient venus là, se mirent à table avec Jésus et ses Disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Ce que les Pharisiens ayant vu, ils dirent à ses Disciples: pourquoi votre Maître mange-t-il avec des péagers et des gens de mauvaise vie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Mais Jésus l’ayant entendu, leur dit: ceux qui sont en santé n’ont pas besoin de médecin, mais ceux qui se portent mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Mais allez, et apprenez ce que veulent dire ces paroles: je veux miséricorde, et non pas sacrifice; car je ne suis pas venu pour appeler à la repentance les justes, mais les pécheurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Alors les Disciples de Jean vinrent à lui, et lui dirent: pourquoi nous et les Pharisiens jeûnons-nous souvent, et tes Disciples ne jeûnent point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Et Jésus leur répondit: les gens de la chambre du nouveau marié peuvent-ils s’affliger pendant que le nouveau marié est avec eux? mais les jours viendront que le nouveau marié leur sera ôté, et c’est alors qu’ils jeûneront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Aussi personne ne met une pièce de drap neuf à un vieux habit; car ce qui est mis pour remplir, emporte de l’habit, et la déchirure en est plus grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'On ne met pas non plus le vin nouveau dans de vieux vaisseaux; autrement les vaisseaux se rompent, et le vin se répand, et les vaisseaux périssent; mais on met le vin nouveau dans des vaisseaux neufs, et l’un et l’autre se conservent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Comme il leur disait ces choses, voici venir un Seigneur qui se prosterna devant lui, en lui disant: ma fille est déjà morte, mais viens, et pose ta main sur elle, et elle vivra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Et Jésus s’étant levé le suivit avec ses Disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Et voici, une femme travaillée d’une perte de sang depuis douze ans, vint par derrière, et toucha le bord de son vêtement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'Car elle disait en elle-même: si seulement je touche son vêtement, je serai guérie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Et Jésus s’étant retourné, et la regardant, lui dit: aie bon courage, ma fille! ta foi t’a sauvée; et dans ce moment la femme fut guérie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Or, quand Jésus fut arrivé à la maison de ce Seigneur, et qu’il eut vu les joueurs d’instruments, et une troupe de gens qui faisait un grand bruit,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'Il leur dit: retirez-vous, car la jeune fille n’est pas morte, mais elle dort; et ils se moquaient de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Après donc qu’on eut fait sortir toute cette troupe, il entra, et prit la main de la jeune fille, et elle se leva.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Et le bruit s’en répandit par tout ce pays-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Et comme Jésus passait plus loin, deux aveugles le suivirent, en criant et disant: Fils de David, aie pitié de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Et quand il fut arrivé dans la maison, ces aveugles vinrent à lui, et il leur dit: croyez-vous que je puisse faire ce que vous me demandez? Ils lui répondirent: oui vraiment, Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Alors il toucha leurs yeux, en disant: qu’il vous soit fait selon votre foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Et leurs yeux furent ouverts; et Jésus leur défendit avec menaces, disant: Prenez garde que personne ne le sache.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Mais eux étant partis, répandirent sa renommée dans tout ce pays-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Et comme ils sortaient, voici, on lui présenta un homme muet et démoniaque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Et quand le démon eut été chassé dehors, le muet parla; et les troupes s’en étonnèrent, en disant: il ne s’est jamais rien vu de semblable en Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Mais les Pharisiens disaient: il chasse les démons par le prince des démons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Or Jésus allait dans toutes les villes et dans les bourgades, enseignant dans leurs Synagogues, et prêchant l’Evangile du Royaume, et guérissant toute sorte de maladies, et toute sorte d’infirmités parmi le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Et voyant les troupes, il en fut ému de compassion, parce qu’ils étaient dispersés et errants comme des brebis qui n’ont point de pasteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Et il dit à ses Disciples: certes la moisson est grande, mais il y a peu d’ouvriers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Priez donc le Seigneur de la moisson, qu’il envoie des ouvriers en sa moisson. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Alors Jésus ayant appelé ses douze Disciples, leur donna puissance sur les esprits immondes pour les chasser hors des possédés, et pour guérir toute sorte de maladies, et toute sorte d’infirmités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Et ce sont ici les noms des douze Apôtres: le premier est Simon, nommé Pierre, et André son frère; Jacques, fils de Zébédée, et Jean, son frère;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Philippe et Barthélemy; Thomas, et Matthieu le péager; Jacques, fils d’Alphée, et Lebbée, surnommé Thaddée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon Cananéen, et Judas Iscariot, qui même le trahit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Jésus envoya ces douze, et leur commanda, en disant: n’allez point vers les Gentils, et n’entrez point dans aucune ville des Samaritains;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'Mais plutôt allez vers les brebis perdues de la Maison d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Et quand vous serez partis, prêchez, en disant: le Royaume des cieux est proche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Guérissez les malades, rendez nets les lépreux, ressuscitez les morts, chassez les démons hors des possédés; vous l’avez reçu gratuitement, donnez- le gratuitement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Ne faites provision ni d’or, ni d’argent, ni de monnaie dans vos ceintures;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'Ni de sac pour le voyage, ni de deux robes, ni de souliers, ni de bâton; car l’ouvrier est digne de sa nourriture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Et dans quelque ville ou bourgade que vous entriez, informez-vous qui y est digne de vous loger; et demeurez chez lui jusqu’à ce que vous partiez de là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Et quand vous entrerez dans quelque maison, saluez-la.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Et si cette maison en est digne, que votre paix vienne sur elle; mais si elle n’en est pas digne, que votre paix retourne à vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Mais lorsque quelqu’un ne vous recevra point, et n’écoutera point vos paroles, secouez en partant de cette maison, ou de cette ville, la poussière de vos pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Je vous dis en vérité, que ceux du pays de Sodome et de Gomorrhe seront traités moins rigoureusement au jour du jugement que cette ville-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Voici, je vous envoie comme des brebis au milieu des loups; soyez donc prudents comme des serpents, et simples comme des colombes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Et donnez-vous garde des hommes; car ils vous livreront aux Consistoires, et vous fouetteront dans leurs Synagogues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'Et vous serez menés devant les Gouverneurs, et même devant les Rois, à cause de moi, pour leur rendre témoignage de moi de même qu’aux nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Mais quand ils vous livreront, ne soyez point en peine de ce que vous aurez à dire, ni comment vous parlerez, parce qu’il vous sera donné dans ce moment- là ce que vous aurez à dire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Car ce n’est pas vous qui parlez, mais c’est l’Esprit de votre Père qui parle en vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Or le frère livrera son frère à la mort, et le père son enfant; et les enfants s’élèveront contre leurs pères et leurs mères, et les feront mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'Et vous serez haïs de tous à cause de mon Nom; mais quiconque persévérera jusques à la fin, sera sauvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Or quand ils vous persécuteront dans une ville, fuyez dans une autre; car en vérité je vous dis, que vous n’aurez pas achevé de parcourir toutes les villes d’Israël, que le Fils de l’homme ne soit venu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Le Disciple n’est point au-dessus du maître, ni le serviteur au-dessus de son Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Il suffit au Disciple d’être comme son maître, et au serviteur comme son Seigneur, s’ils ont appelé le père de famille Béelzébul, combien plus appelleront-ils ainsi ses domestiques?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Ne les craignez donc point. Or il n’y a rien de caché qui ne se découvre, ni rien de secret qui ne vienne à être connu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Ce que je vous dis dans les ténèbres, dites-le dans la lumière; et ce que je vous dis à l’oreille, prêchez-le sur les maisons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Et ne craignez point ceux qui tuent le corps, et qui ne peuvent point tuer l’âme; mais plutôt craignez celui qui peut perdre et l’âme et le corps en les jetant dans la géhenne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Ne vend-on pas deux passereaux pour un sou? et cependant aucun d’eux ne tombe point en terre sans la volonté de votre Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Et les cheveux mêmes de votre tête sont tous comptés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Ne craignez donc point; vous valez mieux que beaucoup de passereaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Quiconque donc me confessera devant les hommes, je le confesserai aussi devant mon Père qui est aux cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Mais quiconque me reniera devant les hommes, je le renierai aussi devant mon Père qui est aux cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Ne croyez pas que je sois venu apporter la paix sur la terre; je n’y suis pas venu apporter la paix, mais l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Car je suis venu mettre en division le fils contre son père, et la fille contre sa mère, et la belle-fille contre sa belle-mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'Et les propres domestiques d’un homme seront ses ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Celui qui aime son père ou sa mère plus que moi, n’est pas digne de moi; et celui qui aime son fils ou sa fille plus que moi, n’est pas digne de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'Et quiconque ne prend pas sa croix, et ne vient après moi, n’est pas digne de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Celui qui aura conservé sa vie, la perdra; mais celui qui aura perdu sa vie pour l’amour de moi, la retrouvera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Celui qui vous reçoit, me reçoit; et celui qui me reçoit, reçoit celui qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Celui qui reçoit un Prophète en qualité de Prophète, recevra la récompense d’un Prophète; et celui qui reçoit un juste en qualité de juste, recevra la récompense d’un juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Et quiconque aura donné à boire seulement un verre d’eau froide à un de ces petits en qualité de Disciple, je vous dis en vérité, qu’il ne perdra point sa récompense. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Et il arriva que quand Jésus eut achevé de donner ses ordres à ses douze Disciples, il partit de là pour aller enseigner et prêcher dans leurs villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Or Jean ayant ouï parler dans la prison des actions de Christ, envoya deux de ses Disciples pour lui dire:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'Es-tu celui qui devait venir, ou si nous devons en attendre un autre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Et Jésus répondant, leur dit: allez, et rapportez à Jean les choses que vous entendez, et que vous voyez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Les aveugles recouvrent la vue, les boiteux marchent, les lépreux sont nettoyés, les sourds entendent, les morts sont ressuscités, et l’Evangile est annoncé aux pauvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'Mais bienheureux est celui qui n’aura point été scandalisé en moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Et comme ils s’en allaient, Jésus se mit à dire de Jean aux troupes: qu’êtes-vous allés voir au désert? Un roseau agité du vent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Mais qu’êtes-vous allés voir? Un homme vêtu de précieux vêtements? voici, ceux qui portent des habits précieux, sont dans les maisons des Rois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Mais qu’êtes-vous allés voir? Un Prophète? oui, vous dis-je, et plus qu’un Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Car il est celui duquel il a été ainsi écrit: voici, j’envoie mon messager devant ta face, lequel préparera ton chemin devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'En vérité, je vous dis, qu’entre ceux qui sont nés d’une femme, il n’en a été suscité aucun plus grand que Jean Baptiste; toutefois celui qui est le moindre dans le Royaume des cieux, est plus grand que lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Or depuis les jours de Jean Baptiste jusques à maintenant, le Royaume des cieux est forcé, et les violents le ravissent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Car tous les Prophètes et la Loi jusqu’à Jean ont prophétisé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'Et si vous voulez recevoir mes paroles, c’est l’Elie qui devait venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Qui a des oreilles pour ouïr, qu’il entende.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Mais à qui comparerai-je cette génération? Elle est semblable aux petits enfants qui sont assis aux marchés, et qui crient à leurs compagnons,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'Et leur disent: nous avons joué de la flûte, et vous n’avez point dansé; nous vous avons chanté des airs lugubres, et vous ne vous êtes point lamentés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Car Jean est venu ne mangeant ni ne buvant; et ils disent: il a un démon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Le Fils de l’homme est venu mangeant et buvant; et ils disent: voilà un mangeur et un buveur, un ami des péagers et des gens de mauvaise vie; mais la sagesse a été justifiée par ses enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Alors il commença à reprocher aux villes où il avait fait beaucoup de miracles, qu’elles ne s’étaient point repenties, en leur disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Malheur à toi, Corazin! malheur à toi, Bethsaïda! car si les miracles qui ont été faits au milieu de vous, eussent été faits dans Tyr et dans Sidon, il y a longtemps qu’elles se seraient repenties avec le sac et la cendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'C’est pourquoi je vous dis que Tyr et Sidon seront traitées moins rigoureusement que vous, au jour du jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Et toi Capernaüm, qui as été élevée jusques au ciel, tu seras abaissée jusque dans l’enfer; car si les miracles qui ont été faits au milieu de toi, eussent été faits dans Sodome, elle subsisterait encore.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'C’est pourquoi je vous dis, que ceux de Sodome seront traités moins rigoureusement que toi, au jour du jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'En ce temps-là Jésus prenant la parole dit: je te célèbre, ô mon Père! Seigneur du ciel et de la terre, de ce que tu as caché ces choses aux sages et aux intelligents, et que tu les as révélées aux petits enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Il est ainsi, ô mon Père! parce que telle a été ta bonne volonté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Toutes choses m’ont été accordées par mon Père! mais personne ne connaît le Fils, que le Père; et personne ne connaît le Père que le Fils, et celui à qui le Fils l’aura voulu révéler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Venez à moi vous tous qui êtes fatigués et chargés, et je vous soulagerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Chargez mon joug sur vous, et apprenez de moi parce que je suis doux et humble de coeur; et vous trouverez le repos de vos âmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Car mon joug est aisé, et mon fardeau est léger. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'En ce temps-là Jésus allait par des blés un jour de Sabbat, et ses Disciples ayant faim se mirent à arracher des épis, et à les manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Et les Pharisiens voyant cela, lui dirent: voilà, tes Disciples font une chose qu’il n’est pas permis de faire le jour du Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Mais il leur dit: n’avez-vous point lu ce que fit David quand il eut faim, lui et ceux qui étaient avec lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Comment il entra dans la maison de Dieu, et mangea les pains de proposition, lesquels il ne lui était pas permis de manger, ni à ceux qui étaient avec lui, mais aux Sacrificateurs seulement?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Ou n’avez-vous point lu dans la Loi, qu’aux jours du Sabbat les Sacrificateurs violent le Sabbat dans le Temple, et ils n’en sont point coupables?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Or je vous dis, qu’il y a ici quelqu’un qui est plus grand que le Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Mais si vous saviez ce que signifient ces paroles: je veux miséricorde, et non pas sacrifice, vous n’auriez pas condamné ceux qui ne sont point coupables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Car le Fils de l’homme est Seigneur même du Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Puis étant parti de là, il vint dans leur Synagogue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Et voici, il y avait là un homme qui avait une main sèche, et pour avoir sujet de l’accuser ils l’interrogèrent, en disant: est-il permis de guérir aux jours du Sabbat?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Et il leur dit: qui sera celui d’entre vous s’il a une brebis, et qu’elle vienne à tomber dans une fosse le jour du Sabbat, qui ne la prenne, et ne la relève?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Or combien vaut mieux un homme qu’une brebis? il est donc permis de faire du bien les jours du Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Alors il dit à cet homme: étends ta main; il l’étendit, et elle fut rendue saine comme l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Or les Pharisiens étant sortis consultèrent contre lui comment ils feraient pour le perdre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Mais Jésus connaissant cela, partit de là, et de grandes troupes le suivirent, et il les guérit tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'Et il leur défendit avec menaces de le donner à connaître;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'Afin que fût accompli ce dont il avait été parlé par Esaïe le Prophète, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Voici mon serviteur que j’ai élu, mon bien-aimé, qui est l’objet de mon amour, je mettrai mon Esprit en lui, et il annoncera le jugement aux nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Il ne contestera point, il ne criera point, et personne n’entendra sa voix dans les rues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Il ne brisera point le roseau cassé, et n’éteindra point le lumignon qui fume, jusqu’à ce qu’il ait fait triompher la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'Et les nations espéreront en son nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Alors il lui fut présenté un homme tourmenté d’un démon, aveugle, et muet, et il le guérit; de sorte que celui qui avait été aveugle et muet, parlait et voyait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'Et toutes les troupes en furent étonnées, et elles disaient: celui-ci n’est-il pas le Fils de David?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Mais les Pharisiens ayant entendu cela, disaient: celui-ci ne chasse les démons que par Béelzébul, prince des démons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Mais Jésus connaissant leurs pensées, leur dit: tout Royaume divisé contre soi-même sera réduit en désert; et toute ville, ou maison, divisée contre soi- même ne subsistera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Or si Satan jette Satan dehors, il est divisé contre soi-même; comment donc son Royaume subsistera-t-il?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'Et si je chasse les démons par Béelzébul, par qui vos fils les chassent-ils? c’est pourquoi ils seront eux-mêmes vos juges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Mais si je chasse les démons par l’Esprit de Dieu, certes le Royaume de Dieu est venu jusqu’à vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Ou, comment quelqu’un pourra-t-il entrer dans la maison d’un homme fort, et piller son bien, si premièrement il n’a lié l’homme fort? et alors il pillera sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Celui qui n’est point avec moi, est contre moi; et celui qui n’assemble point avec moi, il disperse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'C’est pourquoi je vous dis, que tout péché et tout blasphème sera pardonné aux hommes; mais le blasphème contre l’Esprit ne leur sera point pardonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Et si quelqu’un a parlé contre le Fils de l’homme, il lui sera pardonné; mais si quelqu’un a parlé contre le Saint-Esprit, il ne lui sera pardonné ni en ce siècle, ni en celui qui est à venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Ou faites l’arbre bon, et son fruit sera bon; ou faites l’arbre mauvais, et son fruit sera mauvais: car l’arbre est connu par le fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Race de vipères, comment pourriez-vous parler bien, étant méchants? car de l’abondance du coeur la bouche parle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'L’homme de bien tire de bonnes choses, du bon trésor de son coeur; et l’homme méchant tire de mauvaises choses du mauvais trésor de son coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Or je vous dis, que les hommes rendront compte au jour du jugement, de toute parole oiseuse qu’ils auront dite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Car tu seras justifié par tes paroles, et tu seras condamné par tes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Alors quelques-uns des Scribes et des Pharisiens lui dirent: Maître, nous voudrions bien te voir faire quelque miracle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Mais il leur répondit, et dit: la nation méchante et adultère recherche un miracle, mais il ne lui sera point donné d’autre miracle que celui de Jonas le Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Car comme Jonas fut dans le ventre de la baleine trois jours et trois nuits, ainsi le Fils de l’homme sera dans le sein de la terre trois jours et trois nuits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Les Ninivites se lèveront au jour du jugement contre cette nation, et la condamneront, parce qu’ils se sont repentis à la prédication de Jonas; et voici, il y a ici plus que Jonas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'La Reine du Midi se lèvera au jour du jugement contre cette nation, et la condamnera, parce qu’elle vint du bout de la terre pour entendre la sagesse de Salomon; et voici, il y a ici plus que Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Or quand l’esprit immonde est sorti d’un homme, il va par des lieux secs, cherchant du repos, mais il n’en trouve point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Et alors il dit: je retournerai dans ma maison, d’où je suis sorti; et quand il y est venu, il la trouve vide, balayée et parée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Puis il s’en va, et prend avec soi sept autres esprits plus méchants que lui, qui y étant entrés, habitent là; et ainsi la fin de cet homme est pire que le commencement; il en arrivera de même à cette nation perverse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Et comme il parlait encore aux troupes, voici, sa mère et ses frères étaient dehors cherchant de lui parler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'Et quelqu’un lui dit: voilà, ta mère et tes frères sont là dehors, qui cherchent de te parler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Mais il répondit à celui qui lui avait dit cela: qui est ma mère, et qui sont mes frères?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Et étendant sa main sur ses Disciples, il dit: voici ma mère et mes frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Car quiconque fera la volonté de mon Père qui est aux cieux, celui-là est mon frère, et ma soeur, et ma mère. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Ce même jour-là Jésus étant sorti de la maison, s’assit près de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Et de grandes troupes s’assemblèrent autour de lui, c’est pourquoi il monta dans une nacelle, et s’assit, et toute la multitude se tenait sur le rivage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Et il leur parla de plusieurs choses par des similitudes, en disant: voici, un semeur sortit pour semer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'Et comme il semait, une partie de la semence tomba le long du chemin, et les oiseaux vinrent, et la mangèrent toute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Et une autre partie tomba dans des lieux pierreux, où elle n’avait guère de terre, et aussitôt elle leva, parce qu’elle n’entrait pas profondément dans la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Et le soleil s’étant levé, elle fut brûlée; et parce qu’elle n’avait point de racine, elle sécha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Et une autre partie tomba entre des épines; et les épines montèrent, et l’étouffèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Et une autre partie tomba dans une bonne terre, et rendit du fruit, un grain en rendit cent, un autre, soixante, et un autre, trente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Qui a des oreilles pour ouïr, qu’il entende.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Alors les Disciples s’approchant lui dirent: pourquoi leur parles-tu par des similitudes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Il répondit, et leur dit: c’est parce qu’il vous est donné de connaître les mystères du Royaume des cieux, et que, pour eux, il ne leur est point donné de les connaître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Car à celui qui a, il sera donné, et il aura encore plus; mais à celui qui n’a rien, cela même qu’il a lui sera ôté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'C’est pourquoi je leur parle par des similitudes, à cause qu’en voyant ils ne voient point, et qu’en entendant ils n’entendent point, et ne comprennent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Et ainsi s’accomplit en eux la prophétie d’Esaïe, qui dit: en entendant vous ne comprendrez point; et en voyant vous verrez, et vous n’apercevrez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Car le coeur de ce peuple est engraissé, et ils ont ouï dur de leurs oreilles, et ont cligné de leurs yeux; de peur qu’ils ne voient des yeux, et qu’ils n’entendent des oreilles, et qu’ils ne comprennent du coeur, et ne se convertissent, et que je ne les guérisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Mais vos yeux sont bienheureux, car ils voient; et, vos oreilles sont bienheureuses, car elles entendent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Car en vérité je vous dis, que plusieurs Prophètes et plusieurs justes ont désiré de voir les choses que vous voyez, et ils ne les ont point vues; et d’ouïr les choses que vous entendez, et ils ne les ont point ouïes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Vous donc, écoutez le sens de la similitude du semeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Quand un homme écoute la parole du Royaume, et ne la comprend point, le malin vient, et ravit ce qui est semé dans son coeur; et c’est là celui qui a reçu la semence auprès du chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Et celui qui a reçu la semence dans des lieux pierreux, c’est celui qui écoute la parole, et qui la reçoit aussitôt avec joie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'Mais il n’a point de racine en lui-même, c’est pourquoi il n’est qu’à temps; de sorte que dès que l’affliction ou la persécution survienne à cause de la parole, il est aussitôt scandalisé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Et celui qui a reçu la semence entre les épines, c’est celui qui écoute la parole de Dieu, mais l’inquiétude pour les choses de ce monde, et la tromperie des richesses étouffent la parole, et elle devient infructueuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Mais celui qui a reçu la semence dans une bonne terre, c’est celui qui écoute la parole, et qui la comprend; et porte du fruit, et produit, l’un cent, l’autre soixante, et l’autre trente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Il leur proposa une autre similitude, en disant: le Royaume des cieux ressemble à un homme qui a semé de la bonne semence dans son champ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Mais pendant que les hommes dormaient, son ennemi est venu, qui a semé de l’ivraie parmi le blé, puis s’en est allé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Et après que la semence fut venue en herbe, et qu’elle eut porté du fruit, alors aussi parut l’ivraie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Et les serviteurs du père de famille vinrent à lui, et lui dirent: Seigneur, n’as-tu pas semé de la bonne semence dans ton champ? d’où vient donc qu’il y a de l’ivraie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Mais il leur dit: c’est l’ennemi qui a fait cela. Et les serviteurs lui dirent: veux-tu donc que nous y allions, et que nous cueillions l’ivraie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Et il leur dit: non; de peur qu’il n’arrive qu’en cueillant l’ivraie, vous n’arrachiez le blé en même temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Laissez-les croître tous deux ensemble, jusqu’à la moisson; et au temps de la moisson, je dirai aux moissonneurs: cueillez premièrement l’ivraie, et la liez en faisceaux pour la brûler; mais assemblez le blé dans mon grenier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Il leur proposa une autre similitude, en disant: le Royaume des cieux est semblable au grain de semence de moutarde que quelqu’un a pris et semé dans son champ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Qui est bien la plus petite de toutes les semences; mais quand il est crû, il est plus grand que les autres plantes, et devient un arbre; tellement que les oiseaux du ciel y viennent, et font leurs nids dans ses branches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Il leur dit une autre similitude: le Royaume des cieux est semblable au levain qu’une femme prend, et qu’elle met parmi trois mesures de farine, jusqu’à ce qu’elle soit toute levée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Jésus dit toutes ces choses aux troupes en similitudes, et il ne leur parlait point sans similitudes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'Afin que fût accompli ce dont il avait été parlé par le Prophète, en disant: j’ouvrirai ma bouche en similitudes; je déclarerai les choses qui ont été cachées dès la fondation du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Alors Jésus ayant laissé les troupes, s’en alla à la maison, et ses Disciples vinrent à lui, et lui dirent: explique-nous la similitude de l’ivraie du champ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Et il leur répondit et dit: celui qui sème la bonne semence, c’est le Fils de l’homme;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'Et le champ, c’est le monde; la bonne semence ce sont les enfants du Royaume, et l’ivraie ce sont les enfants du malin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'Et l’ennemi qui l’a semée, c’est le diable; la moisson, c’est la fin du monde, et les moissonneurs sont les Anges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Comme donc on cueille l’ivraie, et on la brûle au feu, il en sera de même à la fin de ce monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Le Fils de l’homme enverra ses Anges, qui cueilleront de son Royaume tous les scandales, et ceux qui commettent l’iniquité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'Et les jetteront dans la fournaise du feu; là il y aura des pleurs et des grincements de dents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Alors les justes reluiront comme le soleil dans le Royaume de leur Père. Qui a des oreilles pour ouïr, qu’il entende.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Le Royaume des cieux est encore semblable à un trésor caché dans un champ, lequel un homme ayant trouvé, l’a caché; puis de la joie qu’il en a, il s’en va, et vend tout ce qu’il a, et achète ce champ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Le Royaume des cieux est encore semblable à un marchand qui cherche de bonnes perles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'Et qui ayant trouvé une perle de grand prix, s’en est allé, et a vendu tout ce qu’il avait, et l’a achetée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Le Royaume des cieux est encore semblable à un filet jeté dans la mer, et amassant toutes sortes de choses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Lequel étant plein, les pêcheurs le tirent en haut sur le rivage, puis s’étant assis, ils mettent ce qu’il y a de bon à part dans leurs vaisseaux, et jettent dehors ce qui ne vaut rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Il en sera de même à la fin du monde, les Anges viendront, et sépareront les méchants d’avec les justes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'Et les jetteront dans la fournaise du feu; là il y aura des pleurs, et des grincements de dents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Jésus leur dit: avez-vous compris toutes ces choses? Ils lui répondirent: oui, Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Et il leur dit: c’est pour cela que tout Scribe qui est bien instruit pour le Royaume des cieux, est semblable à un père de famille qui tire de son trésor des choses nouvelles, et des choses anciennes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Et quand Jésus eut achevé ces similitudes, il partit de là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'Et étant venu en son pays, il les enseignait dans leur Synagogue, de telle sorte qu’ils en étaient étonnés, et disaient: d’où viennent à celui-ci cette science et ces vertus?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Celui-ci n’est-il pas le fils du charpentier? sa mère ne s’appelle-t-elle pas Marie? et ses frères ne s’appellent-ils pas Jacques, Joses, Simon et Jude?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Et ses soeurs ne sont-elles pas toutes parmi nous? D’où viennent donc à celui-ci toutes ces choses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'Tellement qu’ils étaient scandalisés en lui. Mais Jésus leur dit: un Prophète n’est sans honneur que dans son pays, et dans sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Et il ne fit là guère de miracles, à cause de leur incrédulité. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'En ce temps-là Hérode le Tétrarque ouït la renommée de Jésus;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'Et il dit à ses serviteurs: c’est Jean Baptiste; il est ressuscité des morts, c’est pourquoi la vertu de faire des miracles agit puissamment en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Car Hérode avait fait prendre Jean, et l’avait fait lier et mettre en prison, à cause d’Hérodias, femme de Philippe son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Parce que Jean lui disait: il ne t’est pas permis de l’avoir pour femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Et il eût bien voulu le faire mourir, mais il craignait le peuple, à cause qu’on tenait Jean pour Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Or au jour du festin de la naissance d’Hérode, la fille d’Hérodias dansa en pleine salle, et plut à Hérode.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'C’est pourquoi il lui promit avec serment de lui donner tout ce qu’elle demanderait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Elle donc étant poussée auparavant par sa mère, lui dit: donne-moi ici dans un plat la tête de Jean Baptiste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Et le roi en fut marri; mais à cause des serments, et de ceux qui étaient à table avec lui, il commanda qu’on la lui donnât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Et il envoya décapiter Jean dans la prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Et sa tête fut apportée dans un plat, et donnée à la fille, qui la présenta à sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Puis ses disciples vinrent, et emportèrent son corps, et l’ensevelirent; et ils vinrent l’annoncer à Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Et Jésus l’ayant entendu se retira de là dans une nacelle, vers un lieu désert, pour y être en particulier; ce que les troupes ayant appris, elles sortirent des villes voisines, et le suivirent à pied.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Et Jésus étant sorti vit une grande multitude, et il en fut ému de compassion, et guérit leurs malades.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Et comme il se faisait tard, ses Disciples vinrent à lui, et lui dirent: ce lieu est désert, et l’heure est déjà passée; donne congé à ces troupes, afin qu’elles s’en aillent aux bourgades, et qu’elles achètent des vivres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Mais Jésus leur dit: ils n’ont pas besoin de s’en aller; donnez-leur vous- mêmes à manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Et ils lui dirent: nous n’avons ici que cinq pains et deux poissons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Et il leur dit: apportez-les-moi ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Et après avoir commandé aux troupes de s’asseoir sur l’herbe, il prit les cinq pains et les deux poissons, et levant les yeux au ciel, il bénit Dieu; puis ayant rompu les pains, il les donna aux Disciples, et les Disciples aux troupes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Et ils en mangèrent tous, et furent rassasiés, et ils remportèrent du reste des pièces de pain douze corbeilles pleines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Or ceux qui avaient mangé étaient environ cinq mille hommes, sans compter les femmes et les petits enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Incontinent après Jésus obligea ses Disciples de monter dans la nacelle, et de passer avant lui à l’autre côté, pendant qu’il donnerait congé aux troupes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Et quand il leur eut donné congé, il monta sur une montagne pour être en particulier, afin de prier; et le soir étant venu, il était là seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Or la nacelle était déjà au milieu de la mer, battue par les vagues; car le vent était contraire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Et sur la quatrième veille de la nuit Jésus vint vers eux, marchant sur la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Et ses Disciples le voyant marcher sur la mer, ils en furent troublés, et ils dirent: c’est un fantôme; et de la peur qu’ils eurent ils jetèrent des cris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Mais tout aussitôt Jésus parla à eux, et leur dit: rassurez-vous; c’est moi, n’ayez point de peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Et Pierre lui répondant, dit: Seigneur! si c’est toi, commande que j’aille à toi sur les eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Et il lui dit: viens. Et Pierre étant descendu de la nacelle marcha sur les eaux pour aller à Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Mais voyant que le vent était fort, il eut peur; et comme il commençait à s’enfoncer, il s’écria, en disant: Seigneur! sauve-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Et aussitôt Jésus étendit sa main, et le prit, en lui disant: homme de petite foi, pourquoi as-tu douté?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Et quand ils furent montés dans la nacelle, le vent s’apaisa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Alors ceux qui étaient dans la nacelle, vinrent, et l’adorèrent, en disant: certes tu es le Fils de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Puis étant passés au-delà de la mer, ils vinrent en la contrée de Génézareth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Et quand les gens de ce lieu-là l’eurent reconnu, ils envoyèrent l’annoncer par toute la contrée d’alentour; et ils lui présentèrent tous ceux qui se portaient mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'Et ils le priaient de permettre qu’ils touchassent seulement le bord de sa robe; et tous ceux qui le touchèrent furent guéris. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Alors des Scribes et des Pharisiens vinrent de Jérusalem à Jésus, et lui dirent:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Pourquoi tes Disciples transgressent-ils la tradition des Anciens? car ils ne lavent point leurs mains quand ils prennent leur repas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Mais il répondit, et leur dit: et vous, pourquoi transgressez-vous le commandement de Dieu par votre tradition?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Car Dieu a commandé, disant: honore ton père et ta mère. Et il a dit aussi: que celui qui maudira son père ou sa mère, meure de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Mais vous dites: quiconque aura dit à son père ou à sa mère: Tout don qui sera offert de par moi, sera à ton profit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'Encore qu’il n’honore pas son père, ou sa mère, il ne sera point coupable; et ainsi vous avez anéanti le commandement de Dieu par votre tradition.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Hypocrites, Esaïe a bien prophétisé de vous, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, 'Ce peuple s’approche de moi de sa bouche, et m’honore de ses lèvres; mais leur coeur est fort éloigné de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Mais ils m’honorent en vain, enseignant des doctrines qui ne sont que des commandements d’hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Puis ayant appelé les troupes, il leur dit: écoutez, et comprenez ceci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Ce n’est pas ce qui entre dans la bouche qui souille l’homme; mais ce qui sort de la bouche c’est ce qui souille l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Sur cela les Disciples s’approchant, lui dirent: n’as-tu pas connu que les Pharisiens ont été scandalisés quand ils ont ouï ce discours?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Et il répondit, et dit: toute plante que mon Père céleste n’a pas plantée, sera déracinée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Laissez-les, ce sont des aveugles, conducteurs d’aveugles; si un aveugle conduit un autre aveugle, ils tomberont tous deux dans la fosse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Alors Pierre prenant la parole, lui dit: explique-nous cette similitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Et Jésus dit: êtes-vous encore, vous aussi, sans intelligence?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'N’entendez-vous pas encore que tout ce qui entre dans la bouche descend dans l’estomac et ensuite est jeté au secret?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Mais les choses qui sortent de la bouche partent du coeur, et ces choses-là souillent l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Car du coeur sortent les mauvaises pensées, les meurtres, les adultères, les fornications, les larcins, les faux témoignages, les médisances.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Ce sont là les choses qui souillent l’homme; mais de manger sans avoir les mains lavées, cela ne souille point l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Alors Jésus partant de là se retira vers les quartiers de Tyr et de Sidon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'Et voici, une femme Cananéenne, qui était partie de ces quartiers-là, s’écria, en lui disant: Seigneur! Fils de David, aie pitié de moi! ma fille est misérablement tourmentée d’un démon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Mais il ne lui répondit mot; et ses Disciples s’approchant le prièrent, disant: renvoie-la; car elle crie après nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Et il répondit, et dit: je ne suis envoyé qu’aux brebis perdues de la maison d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Mais elle vint, et l’adora, disant: Seigneur, assiste-moi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Et il lui répondit, et dit: il ne convient pas de prendre le pain des enfants, et de le jeter aux petits chiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Mais elle dit: cela est vrai, Seigneur! cependant les petits chiens mangent des miettes qui tombent de la table de leurs maîtres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Alors Jésus répondant, lui dit: Ô femme! ta foi est grande; qu’il te soit fait comme tu le souhaites: et dès ce moment-là sa fille fut guérie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Et Jésus partant de là vint près de la mer de Galilée; puis il monta sur une montagne, et s’assit là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Et plusieurs troupes de gens vinrent à lui, ayant avec eux des boiteux, des aveugles, des muets, des manchots, et plusieurs autres; lesquels on mit aux pieds de Jésus, et il les guérit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'De sorte que ces troupes s’étonnèrent de voir les muets parler, les manchots être sains, les boiteux marcher, et les aveugles voir; et elles glorifièrent le Dieu d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Alors Jésus ayant appelé ses Disciples, dit: je suis ému de compassion envers cette multitude de gens, car il y a déjà trois jours qu’ils ne bougent d’avec moi, et ils n’ont rien à manger; et je ne veux pas les renvoyer à jeun, de peur que les forces ne leur manquent en chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Et ses Disciples lui dirent: d’où pourrions-nous tirer dans ce désert assez de pains pour rassasier une si grande multitude?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Et Jésus leur dit: combien avez-vous de pains? ils lui dirent: Sept, et quelque peu de petits poissons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Alors il commanda aux troupes de s’asseoir par terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'Et ayant pris les sept pains et les poissons, il les rompit après avoir béni Dieu, et les donna à ses Disciples, et les Disciples au peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Et ils mangèrent tous, et furent rassasiés; et on remporta du reste des pièces de pain sept corbeilles pleines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Or ceux qui avaient mangé étaient quatre mille hommes, sans compter les femmes et les petits enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Et Jésus ayant donné congé aux troupes, monta sur une nacelle, et vint au territoire de Magdala. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Alors des Pharisiens et des saducéens vinrent à lui, et pour l’éprouver, ils lui demandèrent qu’il leur fît voir quelque miracle dans le ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Mais il répondit, et leur dit: quand le soir est venu, vous dites: il fera beau temps, car le ciel est rouge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'Et le matin vous dites: il y aura aujourd’hui de l’orage, car le ciel est rouge, et sombre. Hypocrites, vous savez bien juger de l’apparence du ciel, et vous ne pouvez juger des signes des saisons!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'La nation méchante et adultère recherche un miracle; mais il ne lui sera point donné d’ autre miracle que celui de Jonas le Prophète; et les laissant il s’en alla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Et quand ses Disciples furent venus au rivage de delà, ils avaient oublié de prendre des pains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Et Jésus leur dit: voyez, et donnez-vous garde du levain des Pharisiens et des Saducéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Or ils pensaient en eux-mêmes, et disaient: c’est parce que nous n’avons pas pris de pains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Et Jésus connaissant leur pensée, leur dit: gens de petite foi, qu’est-ce que vous pensez en vous-mêmes au sujet de ce que vous n’avez point pris de pains?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Ne comprenez-vous point encore, et ne vous souvient-il plus des cinq pains des cinq mille hommes, et combien de corbeilles vous en recueillîtes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Ni des sept pains des quatre mille hommes, et combien de corbeilles vous en recueillîtes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Comment ne comprenez-vous point que ce n’est pas touchant le pain que je vous ai dit, de vous donner garde du levain des Pharisiens et des Saducéens?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Alors ils comprirent que ce n’était pas du levain du pain qu’il leur avait dit de se donner garde, mais de la doctrine des Pharisiens et des Saducéens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Et Jésus venant aux quartiers de Césarée de Philippe, interrogea ses Disciples, en disant: qui disent les hommes que je suis, moi le Fils de l’homme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Et ils lui répondirent: les uns disent que tu es Jean Baptiste; les autres, Elie; et les autres, Jérémie, ou l’un des Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Il leur dit: et vous, qui dites-vous que je suis?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Simon Pierre répondit, et dit: Tu es le Christ, le Fils du Dieu vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Et Jésus répondit, et dit: tu es bienheureux, Simon, fils de Jonas: car la chair et le sang ne te l’a pas révélé, mais mon Père qui est aux cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Et je te dis aussi, que tu es Pierre, et sur cette pierre j’édifierai mon Eglise; et les portes de l’enfer ne prévaudront point contre elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Et je te donnerai les clefs du Royaume des cieux; et tout ce que tu auras lié sur la terre, sera lié dans les cieux; et tout ce que tu auras délié sur la terre, sera délié dans les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Alors il commanda expressément à ses Disciples de ne dire à personne qu’il fût Jésus le Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Dès lors Jésus commença à déclarer à ses Disciples, qu’il fallait qu’il allât à Jérusalem, et qu’il y souffrît beaucoup de la part des Anciens, et des principaux Sacrificateurs, et des Scribes; et qu’il y fût mis à mort, et qu’il ressuscitât le troisième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Mais Pierre l’ayant tiré à part se mit à le reprendre, en lui disant: Seigneur, aie pitié de toi; cela ne t’arrivera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Mais lui s’étant retourné, dit à Pierre: retire-toi de moi, Satan, tu m’es en scandale; car tu ne comprends pas les choses qui sont de Dieu, mais celles qui sont des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Alors Jésus dit à ses Disciples: si quelqu’un veut venir après moi, qu’il renonce à soi-même, et qu’il charge sa croix; et me suive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Car quiconque voudra sauver son âme, la perdra; mais quiconque perdra son âme pour l’amour de moi, la trouvera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Mais que profiterait-il à un homme de gagner tout le monde, s’il fait la perte de son âme? ou que donnera l’homme en échange de son âme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Car le Fils de l’homme doit venir environné de la gloire de son Père avec ses Anges, et alors il rendra à chacun selon ses oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'En vérité je vous dis, qu’il y a quelques-uns de ceux qui sont ici présents, qui ne mourront point, jusqu’à ce qu’ils aient vu le Fils de l’homme venir en son règne. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Et six jours après, Jésus prit Pierre, et Jacques, et Jean son frère, et les mena à l’écart sur une haute montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'Et il fut transfiguré en leur présence et son visage resplendit comme le soleil; et ses vêtements devinrent blancs comme la lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Et voici, ils virent Moïse et Elie, qui s’entretenaient avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Alors Pierre prenant la parole, dit à Jésus: Seigneur, il est bon que nous soyons ici; faisons-y, si tu le veux, trois tentes, une pour toi, une pour Moïse, et une pour Elie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Et comme il parlait encore, voici une nuée resplendissante qui les couvrit de son ombre; puis voilà une voix qui vint de la nuée, disant: celui-ci est mon Fils bien-aimé, en qui j’ai pris mon bon plaisir; écoutez-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Ce que les Disciples ayant ouï, ils tombèrent le visage contre terre, et eurent une très grande peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Mais Jésus s’approchant les toucha, en leur disant: levez-vous, et n’ayez point de peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Et eux levant leurs yeux, ne virent personne, que Jésus tout seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Et comme ils descendaient de la montagne, Jésus leur commanda, en disant: ne dites à personne la vision, jusqu’à ce que le Fils de l’homme soit ressuscité des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Et ses Disciples l’interrogèrent, en disant: pourquoi donc les Scribes disent-ils qu’il faut qu’Elie vienne premièrement?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Et Jésus répondant dit: il est vrai qu’Elie viendra premièrement, et qu’il rétablira toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Mais je vous dis qu’Elie est déjà venu, et ils ne l’ont point connu; mais ils lui ont fait tout ce qu’ils ont voulu; ainsi le Fils de l’homme doit souffrir aussi de leur part.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Alors les Disciples comprirent que c’était de Jean Baptiste qu’il leur avait parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Et quand ils furent venus vers les troupes, un homme s’approcha, et se mit à genoux devant lui,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'Et lui dit: Seigneur! aie pitié de mon fils, qui est lunatique, et misérablement affligé; car il tombe souvent dans le feu, et souvent dans l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Et je l’ai présenté à tes Disciples; mais ils ne l’ont pu guérir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Et Jésus répondant, dit: Ô race incrédule, et perverse, jusques à quand serai-je avec vous? jusques à quand vous supporterai-je? amenez-le-moi ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Et Jésus censura fortement le démon, qui sortit hors de cet enfant, et à l’heure même l’enfant fut guéri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Alors les Disciples vinrent en particulier à Jésus, et lui dirent: pourquoi ne l’avons-nous pu jeter dehors?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Et Jésus leur répondit: c’est à cause de votre incrédulité: car en vérité je vous dis, que si vous aviez de la foi, aussi gros qu’un grain de semence de moutarde, vous diriez à cette montagne: transporte-toi d’ici là, et elle s’y transporterait; et rien ne vous serait impossible.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Mais cette sorte de démons ne sort que par la prière et par le jeûne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Et comme ils se trouvaient en Galilée, Jésus leur dit: il arrivera que le Fils de l’homme sera livré entre les mains des hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'Et qu’ils le feront mourir, mais le troisième jour il ressuscitera. Et les Disciples en furent fort attristés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Et lorsqu’ils furent venus à Capernaüm, ceux qui recevaient les didrachmes s’adressèrent à Pierre et lui dirent: votre Maître ne paye-t-il pas les didrachmes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Il dit: oui. Et quand il fut entré dans la maison, Jésus le prévint, en lui disant: qu’est-ce qu’il t’en semble, Simon? Les Rois de la terre, de qui prennent-ils des tributs, ou des impôts? est-ce de leurs enfants, ou des étrangers?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Pierre dit: des étrangers. Jésus lui répondit: les enfants en sont donc exempts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Mais afin que nous ne les scandalisions point, va-t’en à la mer, et jette l’hameçon, et prends le premier poisson qui montera; et quand tu lui auras ouvert la bouche, tu y trouveras un statère; prends-le, et le leur donne pour moi et pour toi. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'En cette même heure-là les Disciples vinrent à Jésus, en lui disant: qui est le plus grand au Royaume des cieux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Et Jésus ayant appelé un petit enfant, le mit au milieu d’eux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'Et leur dit: en vérité je vous dis, que si vous n’êtes changés, et si vous ne devenez comme de petits enfants, vous n’entrerez point dans le Royaume des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'C’est pourquoi quiconque deviendra humble, comme est ce petit enfant, celui- là est le plus grand au Royaume des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'Et quiconque reçoit un tel petit enfant en mon Nom, il me reçoit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Mais quiconque scandalise un de ces petits qui croient en moi, il lui vaudrait mieux qu’on lui pendît une meule d’âne au cou, et qu’on le jetât au fond de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Malheur au monde à cause des scandales; car il est infaillible qu’il n’arrive des scandales; toutefois malheur à l’homme par qui le scandale arrive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Que si ta main ou ton pied te fait broncher, coupe-les, et jette-les loin de toi; car il vaut mieux que tu entres boiteux ou manchot dans la vie, que d’avoir deux pieds ou deux mains, et d’être jeté au feu éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Et si ton oeil te fait broncher, arrache-le, et jette-le loin de toi; car il vaut mieux que tu entres dans la vie n’ayant qu’un oeil, que d’avoir deux yeux, et d’être jeté dans la géhenne du feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Prenez garde de ne mépriser aucun de ces petits, car je vous dis, que dans les cieux leurs Anges regardent toujours la face de mon Père qui est aux cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Car le Fils de l’homme est venu pour sauver ce qui était perdu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Que vous en semble? Si un homme a cent brebis, et qu’il y en ait une qui se soit égarée, ne laisse-t-il pas les quatre-vingt-dix-neuf, pour s’en aller dans les montagnes chercher celle qui s’est égarée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Et s’il arrive qu’il la trouve, en vérité je vous dis, qu’il en a plus de joie, que des quatre-vingt-dix-neuf qui ne se sont point égarées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Ainsi la volonté de votre Père qui est aux cieux n’est pas qu’un seul de ces petits périsse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Que si ton frère a péché contre toi, va, et reprends-le entre toi et lui seul; s’il t’écoute, tu as gagné ton frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Mais s’il ne t’écoute point, prends encore avec toi une ou deux personnes; afin qu’en la bouche de deux ou de trois témoins toute parole soit ferme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Que s’il ne daigne pas les écouter, dis-le à l’Eglise; et s’il ne daigne pas écouter l’Eglise, qu’il te soit comme un païen et comme un péager.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'En vérité je vous dis, que tout ce que vous aurez lié sur la terre, sera lié dans le ciel; et tout ce que vous aurez délié sur la terre, sera délié dans le ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Je vous dis aussi, que si deux d’entre vous s’accordent sur la terre, tout ce qu’ils demanderont leur sera donné par mon Père qui est aux cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Car là où il y en a deux ou trois assemblés en mon Nom, je suis là au milieu d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Alors Pierre s’approchant, lui dit: Seigneur, jusques à combien de fois mon frère péchera-t-il contre moi, et je lui pardonnerai? sera-ce jusqu’à sept fois?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Jésus lui répondit: je ne te dis pas jusqu’à sept fois, mais jusqu’à sept fois septante fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'C’est pourquoi le Royaume des cieux est semblable à un Roi qui voulut compter avec ses serviteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Et quand il eut commencé à compter, on lui en présenta un qui lui devait dix mille talents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Et parce qu’il n’avait pas de quoi payer, son Seigneur commanda qu’il fût vendu, lui et sa femme et ses enfants, et tout ce qu’il avait, et que la dette fût payée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Mais ce serviteur se jetant à ses pieds, le suppliait, en disant: Seigneur! aie patience, et je te rendrai le tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Alors le Seigneur de ce serviteur, touché de compassion, le relâcha, et lui quitta la dette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Mais ce serviteur étant sorti, rencontra un de ses compagnons de service, qui lui devait cent deniers; et l’ayant pris, il l’étranglait, en lui disant: paye-moi ce que tu me dois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Mais son compagnon de service se jetant à ses pieds, le priait, en disant: aie patience, et je te rendrai le tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Mais il n’en voulut rien faire; et il s’en alla, et le mit en prison, jusqu’à ce qu’il eût payé la dette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Or ses autres compagnons de service voyant ce qui était arrivé, en furent extrêmement touchés, et ils s’en vinrent, et déclarèrent à leur Seigneur tout ce qui s’était passé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Alors son Seigneur le fit venir, et lui dit: méchant serviteur, je t’ai quitté toute cette dette, parce que tu m’en as prié;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'Ne te fallait-il pas aussi avoir pitié de ton compagnon de service, comme j’avais eu pitié de toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Et Son seigneur étant en colère le livra aux sergents, jusqu’à ce qu’il lui eût payé tout ce qui lui était dû.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'C’est ainsi que vous fera mon Père céleste, si vous ne pardonnez de tout votre coeur chacun à son frère ses fautes. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Et il arriva que quand Jésus eut achevé ces discours, il partit de Galilée, et vint vers les confins de la Judée, au delà du Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'Et de grandes troupes le suivirent, et il guérit là leurs malades.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Alors des Pharisiens vinrent à lui pour l’éprouver, et ils lui dirent: est- il permis à un homme de répudier sa femme pour quelque cause que ce soit?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Et il répondit, et leur dit: n’avez-vous point lu que celui qui les a faits dès le commencement, fit un homme et une femme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'Et qu’il dit: A cause de cela l’homme laissera son père et sa mère, et se joindra à sa femme, et les deux ne seront qu’une seule chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'C’est pourquoi ils ne sont plus deux, mais une seule chair. Ce donc que Dieu a joint, que l’homme ne le sépare point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Ils lui dirent: pourquoi donc Moïse a-t-il commandé de donner la Lettre de divorce, et de répudier sa femme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Il leur dit: c’est à cause de la dureté de votre coeur, que Moïse vous a permis de répudier vos femmes; mais au commencement il n’en était pas ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Et moi je vous dis, que quiconque répudiera sa femme, si ce n’est pour cause d’adultère, et se mariera à une autre, commet un adultère; et que celui qui se sera marié à celle qui est répudiée, commet un adultère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Ses Disciples lui dirent: Si telle est la condition de l’homme à l’égard de sa femme, il ne convient pas de se marier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Mais il leur dit: tous ne sont pas capables de cela, mais seulement ceux à qui il est donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Car il y a des eunuques, qui sont ainsi nés du ventre de leur mère; et il y a des eunuques, qui ont été faits eunuques par les hommes; et il y a des eunuques qui se sont faits eux-mêmes eunuques pour le Royaume des cieux. Que celui qui peut comprendre ceci, le comprenne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Alors on lui présenta des petits enfants, afin qu’il leur imposât les mains, et qu’il priât pour eux; mais les Disciples les en reprenaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Et Jésus leur dit: laissez venir à moi les petits enfants, et ne les empêchez point; car le Royaume des cieux est pour ceux qui leur ressemblent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Puis leur ayant imposé les mains, il partit de là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Et voici, quelqu’un s’approchant lui dit: Maître qui est bon, quel bien ferai-je pour avoir la vie éternelle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Il lui répondit: pourquoi m’appelles-tu bon? Dieu est le seul être qui soit bon. Que si tu veux entrer dans la vie, garde les commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Il lui dit: quels? Et Jésus lui répondit: tu ne tueras point. Tu ne commettras point adultère. Tu ne déroberas point. Tu ne diras point de faux témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'Honore ton père et ta mère; et tu aimeras ton prochain comme toi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Le jeune homme lui dit: j’ai gardé toutes ces choses dès ma jeunesse; que me manque-t-il encore?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jésus lui dit: si tu veux être parfait, va, vends ce que tu as, et le donne aux pauvres, et tu auras un trésor dans le ciel; puis viens, et me suis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Mais quand ce jeune homme eut entendu cette parole, il s’en alla tout triste, parce qu’il avait de grands biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Alors Jésus dit à ses Disciples: en vérité je vous dis, qu’un riche entrera difficilement dans le Royaume des cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Je vous le dis encore: Il est plus aisé qu’un chameau passe par le trou d’une aiguille, qu’il ne l’est qu’un riche entre dans le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Ses Disciples ayant entendu ces choses s’étonnèrent fort, et ils dirent: qui peut donc être sauvé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Et Jésus les regardant, leur dit: quant aux hommes, cela est impossible; mais quant à Dieu, toutes choses sont possibles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Alors Pierre prenant la parole, lui dit: voici, nous avons tout quitté, et t’avons suivi; que nous en arrivera-t-il donc?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Et Jésus leur dit: en vérité je vous dis, que vous qui m’avez suivi, dans la régénération, quand le Fils de l’homme sera assis sur le trône de sa gloire, vous aussi serez assis sur douze trônes, jugeant les douze Tribus d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'Et quiconque aura quitté ou maisons, ou frères, ou soeurs, ou père, ou mère, ou femme, ou enfants, ou champs, à cause de mon Nom, il en recevra cent fois autant, et héritera la vie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Mais plusieurs qui sont les premiers, seront les derniers; et les derniers seront les premiers. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Car le Royaume des cieux est semblable à un père de famille, qui sortit dès le point du jour afin de louer des ouvriers pour sa vigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Et quand il eut accordé avec les ouvriers à un denier par jour, il les envoya à sa vigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'Puis étant sorti sur les trois heures, il en vit d’autres qui étaient au marché, sans rien faire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'Auxquels il dit: allez-vous-en aussi à ma vigne, et je vous donnerai ce qui sera raisonnable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Et ils y allèrent. Puis il sortit encore environ sur les six heures, et sur les neuf heures, et il en fit de même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Et étant sorti sur les onze heures, il en trouva d’autres qui étaient sans rien faire, auxquels il dit: pourquoi vous tenez-vous ici tout le jour sans rien faire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Ils lui répondirent: parce que personne ne nous a loués. Et il leur dit: allez-vous-en aussi à ma vigne, et vous recevrez ce qui sera raisonnable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Et le soir étant venu, le maître de la vigne dit à celui qui avait la charge de ses affaires: appelle les ouvriers, et leur paye leur salaire, en commençant depuis les derniers jusques aux premiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Alors ceux qui avaient été loués vers les onze heures étant venus, ils reçurent chacun un denier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Or quand les premiers furent venus ils croyaient recevoir davantage, mais ils reçurent aussi chacun un denier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'Et l’ayant reçu, ils murmuraient contre le père de famille,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'En disant: ces derniers n’ont travaillé qu’une heure, et tu les as faits égaux à nous, qui avons porté le faix du jour, et la chaleur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Et il répondit à l’un d’eux, et lui dit: mon ami, je ne te fais point de tort, n’as-tu pas accordé avec moi à un denier?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Prends ce qui est à toi, et t’en va; mais si je veux donner à ce dernier autant qu’à toi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Ne m’est-il pas permis de faire ce que je veux de mes biens? ton oeil est- il malin de ce que je suis bon?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Ainsi les derniers seront les premiers, et les premiers seront les derniers, car il y a beaucoup d’appelés, mais peu d’élus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Et Jésus montant à Jérusalem, prit à part sur le chemin ses douze Disciples, et leur dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, 'Voici, nous montons à Jérusalem, et le Fils de l’homme sera livré aux principaux Sacrificateurs et aux Scribes, et ils le condamneront à la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'Ils le livreront aux Gentils pour s’en moquer, le fouetter, et le crucifier; mais le troisième jour il ressuscitera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Alors la mère des fils de Zébédée vint à lui avec ses fils, se prosternant, et lui demandant une grâce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Et il lui dit: que veux-tu? Elle lui dit: ordonne que mes deux fils, qui sont ici, soient assis l’un à ta main droite, et l’autre à ta gauche dans ton Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Et Jésus répondit et dit: vous ne savez ce que vous demandez, pouvez-vous boire la coupe que je dois boire, et être baptisés du baptême dont je dois être baptisé; ils lui répondirent: nous le pouvons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Et il leur dit: il est vrai que vous boirez ma coupe, et que vous serez baptisés du baptême dont je serai baptisé; mais d’être assis à ma droite ou à ma gauche, ce n’est point à moi de le donner, mais il sera donné à ceux à qui cela est destiné par mon Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Les dix autres Disciples ayant ouï cela, furent indignés contre les deux frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Mais Jésus les ayant appelés, leur dit: vous savez que les Princes des nations les maîtrisent, et que les Grands usent d’autorité sur elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Mais il n’en sera pas ainsi entre vous: au contraire, quiconque voudra être grand entre vous, qu’il soit votre serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'Et quiconque voudra être le premier entre vous, qu’il soit votre serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'De même que le Fils de l’homme n’est pas venu pour être servi, mais pour servir, et afin de donner sa vie en rançon pour plusieurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Et comme ils partaient de Jéricho, une grande troupe le suivit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'Et voici, deux aveugles qui étaient assis au bord du chemin, ayant ouï que Jésus passait, crièrent, en disant: Seigneur, Fils de David! aie pitié de nous!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Et la troupe les reprit, afin qu’ils se tussent; mais ils criaient encore plus fort: Seigneur, Fils de David! aie pitié de nous!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Et Jésus s’arrêtant, les appela, et leur dit: que voulez-vous que je vous fasse?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Ils lui dirent: Seigneur, que nos yeux soient ouverts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Et Jésus étant ému de compassion, toucha leurs yeux, et incontinent leurs yeux recouvrèrent la vue; et ils le suivirent. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Or quand ils furent près de Jérusalem, et qu’ils furent venus à Bethphagé au mont des oliviers, Jésus envoya alors deux Disciples,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'En leur disant: allez à ce village qui est vis-à-vis de vous, et d’abord vous trouverez une ânesse attachée, et son poulain avec elle; détachez-les, et amenez-les-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Et si quelqu’un vous dit quelque chose, vous direz que le Seigneur en a besoin; et aussitôt il les laissera aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Or tout cela se fit afin que fût accompli ce dont il avait été parlé par le Prophète, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, 'Dites à la fille de Sion: voici, ton Roi vient à toi, débonnaire, et monté sur une ânesse, et sur le poulain d’une ânesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Les Disciples donc s’en allèrent, et firent ce que Jésus leur avait ordonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Et ils amenèrent l’ânesse et l’ânon, et mirent leurs vêtements dessus, et ils l’y firent asseoir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Alors de grandes troupes étendirent leurs vêtements par le chemin, et les autres coupaient des rameaux des arbres, et les étendaient par le chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Et les troupes qui allaient devant, et celles qui suivaient, criaient, en disant: Hosanna! au Fils de David, béni soit celui qui vient au Nom du Seigneur; Hosanna dans les lieux très-hauts!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Et quand il fut entré dans Jérusalem, toute la ville fut émue, disant: qui est celui-ci?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Et les troupes disaient: c’est Jésus le Prophète, qui est de Nazareth en Galilée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Et Jésus entra dans le Temple de Dieu, et chassa dehors tous ceux qui vendaient et qui achetaient dans le Temple, et renversa les tables des changeurs, et les sièges de ceux qui vendaient des pigeons;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'Et il leur dit: il est écrit: ma Maison sera appelée une Maison de prière, mais vous en avez fait une caverne de voleurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Alors des aveugles et des boiteux vinrent à lui dans le Temple, et il les guérit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Mais quand les principaux Sacrificateurs et les Scribes eurent vu les merveilles qu’il avait faites, et les enfants criant dans le Temple, et disant: Hosanna au Fils de David! ils en furent indignés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'Et ils lui dirent: entends-tu ce que ceux-ci disent; et Jésus leur dit: oui; mais n’avez-vous jamais lu ces paroles: tu as mis le comble à ta louange par la bouche des enfants, et de ceux qui tettent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Et les ayant laissés, il sortit de la ville, pour s’en aller à Béthanie, et il y passa la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Or le matin, comme il retournait à la ville, il eut faim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Et voyant un figuier qui était sur le chemin, il s’en approcha, mais il n’y trouva que des feuilles; et il lui dit: qu’aucun fruit ne naisse plus de toi jamais: et incontinent le figuier sécha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Ce que les Disciples ayant vu ils en furent étonnés, disant: comment est-ce que le figuier est devenu sec en un instant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Et Jésus répondant leur dit: en vérité je vous dis, que si vous avez la foi, et que vous ne doutiez point, non seulement vous ferez ce qui a été fait au figuier, mais même si vous dites à cette montagne: quitte ta place, et te jette dans la mer, cela se fera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Et quoi que vous demandiez en priant Dieu si vous croyez, vous le recevrez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Puis quand il fut venu au Temple, les principaux Sacrificateurs et les Anciens du peuple vinrent à lui, comme il enseignait, et lui dirent: par quelle autorité fais-tu ces choses; et qui est-ce qui t’a donné cette autorité?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Jésus répondant leur dit: je vous interrogerai aussi d’une chose, et si vous me la dites, je vous dirai aussi par quelle autorité je fais ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Le Baptême de Jean d’où était-il? Du ciel, ou des hommes? Or ils disputaient en eux-mêmes, en disant: si nous disons: du ciel, il nous dira: pourquoi donc ne l’avez-vous point cru?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Et si nous disons: des hommes, nous craignons les troupes: car tous tiennent Jean pour un Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Alors ils répondirent à Jésus, en disant: nous ne savons. Et il leur dit: je ne vous dirai point aussi par quelle autorité je fais ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Mais que vous semble? Un homme avait deux fils, et venant au premier, il lui dit: mon fils, va-t’en, et travaille aujourd’hui dans ma vigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Lequel répondant, dit: je n’y veux point aller; mais après s’étant repenti, il y alla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Puis il vint à l’autre, et lui dit la même chose; et celui-ci répondit, et dit: j’y vais, Seigneur; mais il n’y alla point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Lequel des deux fit la volonté du père? ils lui répondirent: le premier. Et Jésus leur dit: en vérité je vous dis, que les péagers et les femmes de mauvaise vie vous devancent au Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Car Jean est venu à vous par la voie de la justice, et vous ne l’avez point cru; mais les péagers et les femmes débauchées l’ont cru; et vous, ayant vu cela, ne vous êtes point repentis ensuite pour le croire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Ecoutez une autre similitude: il y avait un père de famille qui planta une vigne, et l’environna d’une haie, et y creusa un pressoir, et y bâtit une tour; puis il la loua à des vignerons, et s’en alla dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Et la saison des fruits étant proche, il envoya ses serviteurs aux vignerons, pour en recevoir les fruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Mais les vignerons ayant pris ses serviteurs, fouettèrent l’un, tuèrent l’autre, et en assommèrent un autre de pierres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Il envoya encore d’autres serviteurs en plus grand nombre que les premiers, et ils leur en firent de même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Enfin, il envoya vers eux son propre fils, en disant: ils auront du respect pour mon fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Mais quand les vignerons virent le fils, ils dirent entre eux: celui-ci est l’héritier; venez, tuons-le, et saisissons-nous de son héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'L’ayant donc pris, ils le jetèrent hors de la vigne, et le tuèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Quand donc le Seigneur de la vigne sera venu, que fera-t-il à ces vignerons?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Ils lui dirent: il les fera périr malheureusement comme des méchants, et louera sa vigne à d’autres vignerons, qui lui en rendront les fruits en leur saison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Et Jésus leur dit: n’avez-vous jamais lu dans les Ecritures: la pierre que ceux qui bâtissent ont rejetée, est devenue la maîtresse pierre du coin; ceci a été fait par le Seigneur, et c’est une chose merveilleuse devant nos yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'C’est pourquoi je vous dis, que le Royaume de Dieu vous sera ôté, et il sera donné à une nation qui en rapportera les fruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'Or celui qui tombera sur cette pierre en sera brisé; et elle écrasera celui sur qui elle tombera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Et quand les principaux Sacrificateurs et les Pharisiens eurent entendu ces similitudes, ils connurent qu’il parlait d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'Et ils cherchaient à se saisir de lui, mais ils craignirent les troupes, parce qu’on le tenait pour un Prophète. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Alors Jésus prenant la parole, leur parla encore par similitudes, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, 'Le Royaume des cieux est semblable à un Roi qui fit les noces de son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'Et il envoya ses serviteurs pour appeler ceux qui avaient été conviés aux noces; mais ils n’y voulurent point venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Il envoya encore d’autres serviteurs, disant: dites à ceux qui étaient conviés: voici, j’ai apprêté mon dîner; mes taureaux et mes bêtes grasses sont tuées, et tout est prêt; venez aux noces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Mais eux n’en tenant point de compte, s’en allèrent l’un à sa métairie, et l’autre à son trafic.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'Et les autres prirent ses serviteurs, et les outragèrent, et les tuèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Quand le Roi l’entendit, il se mit en colère, et y ayant envoyé ses troupes, il fit périr ces meurtriers-là, et brûla leur ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Puis il dit à ses serviteurs: Eh bien! les noces sont apprêtées, mais ceux qui y étaient conviés n’en étaient pas dignes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Allez donc aux carrefours des chemins, et autant de gens que vous trouverez, conviez-les aux noces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Alors ses serviteurs allèrent dans les chemins, et assemblèrent tous ceux qu’ils trouvèrent, tant mauvais que bons, tellement que le lieu des noces fut rempli de gens qui étaient à table.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Et le Roi étant entré pour voir ceux qui étaient à table, il y vit un homme qui n’était pas vêtu d’une robe de noces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'Et il lui dit: mon ami, comment es-tu entré ici, sans avoir une robe de noces? et il eut la bouche fermée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Alors le Roi dit aux serviteurs: liez-le pieds et mains, emportez-le, et le jetez dans les ténèbres de dehors; là il y aura des pleurs et des grincements de dents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Car il y a beaucoup d’appelés, mais peu d’élus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Alors les Pharisiens s’étant retirés, consultèrent ensemble comment ils le surprendraient en paroles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'Et ils lui envoyèrent leurs disciples, avec des Hérodiens, en disant: Maître, nous savons que tu es véritable, que tu enseignes la voie de Dieu en vérité, et que tu ne te soucies de personne; car tu ne regardes point à l’apparence des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Dis-nous donc ce qu’il te semble de ceci: est-il permis de payer le tribut à César, ou non?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Et Jésus connaissant leur malice, dit: Hypocrites, pourquoi me tentez-vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Montrez-moi la monnaie de tribut; et ils lui présentèrent un denier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'Et il leur dit: de qui est cette image, et cette inscription?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Ils lui répondirent: de César. Alors il leur dit: rendez donc à César les choses qui sont à César, et à Dieu, celles qui sont à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Et ayant entendu cela ils en furent étonnés, et le laissant, ils s’en allèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Le même jour les Saducéens, qui disent qu’il n’y a point de résurrection, vinrent à lui, et l’interrogèrent,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'En disant: Maître, Moïse a dit: si quelqu’un vient à mourir sans enfants, que son frère prenne sa femme, et il donnera des enfants à son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Or il y avait parmi nous sept frères, dont l’aîné, après s’être marié, mourut, et n’ayant point eu d’enfants, laissa sa femme à son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'De même le second, puis le troisième, jusques au septième.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Et après eux tous, la femme mourut aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'En la résurrection donc duquel des sept sera-t-elle femme? car tous l’ont eue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Mais Jésus répondant leur dit: vous errez, ne connaissant point les Ecritures, ni la puissance de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Car en la résurrection on ne prend ni on ne donne point de femmes en mariage, mais on est comme les Anges de Dieu dans le ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Et quant à la résurrection des morts, n’avez-vous point lu ce dont Dieu vous a parlé, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, 'Je suis le Dieu d’Abraham, et le Dieu d’Isaac, et le Dieu de Jacob; or Dieu n’est pas le Dieu des morts, mais des vivants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Ce que les troupes ayant entendu, elles admirèrent sa doctrine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Et quand les Pharisiens eurent appris qu’il avait fermé la bouche aux Saducéens, ils s’assemblèrent dans un même lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'Et l’un d’eux, qui était Docteur de la Loi, l’interrogea pour l’éprouver, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'Maître, lequel est le grand commandement de la Loi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Jésus lui dit: tu aimeras le Seigneur ton Dieu de tout ton coeur, et de toute ton âme, et de toute ta pensée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'Celui-ci est le premier et le grand commandement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Et le second semblable à celui-là, est: tu aimeras ton prochain comme toi- même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'De ces deux commandements dépendent toute la Loi et les Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Et les Pharisiens étant assemblés, Jésus les interrogea,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'Disant: que vous semble-t-il du Christ? De qui est-il Fils? Ils lui répondirent: de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Et il leur dit: comment donc David, parlant par l’Esprit, l’appelle-t-il son Seigneur? disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, 'Le Seigneur a dit à mon Seigneur, assieds-toi à ma droite, jusqu’à ce que j’aie mis tes ennemis pour le marchepied de tes pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Si donc David l’appelle son Seigneur, comment est-il son Fils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Et personne ne lui pouvait répondre un seul mot, ni personne n’osa plus l’interroger depuis ce jour-là. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Alors Jésus parla aux troupes, et à ses Disciples,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'Disant: Les Scribes et les Pharisiens sont assis dans la chaire de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Toutes les choses donc qu’ils vous diront d’observer, observez-les, et les faites, mais non point leurs oeuvres: parce qu’ils disent, et ne font pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Car ils lient ensemble des fardeaux pesants et insupportables, et les mettent sur les épaules des hommes; mais ils ne veulent point les remuer de leur doigt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Et ils font toutes leurs oeuvres pour être regardés des hommes; car ils portent de larges phylactères, et de longues franges à leurs vêtements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'Et ils aiment les premières places dans les festins, et les premiers sièges dans les Synagogues;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'Et les salutations aux marchés; et d’être appelés des hommes, Notre maître! Notre maître!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Mais pour vous, ne soyez point appelés, Notre Maître; car Christ seul est votre Docteur; et pour vous, vous êtes tous frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'Et n’appelez personne sur la terre votre père; car un seul est votre Père, lequel est dans les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Et ne soyez point appelés Docteurs: car Christ seul est votre Docteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Mais que celui qui est le plus grand entre vous, soit votre serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Car quiconque s’élèvera sera abaissé; et quiconque s’abaissera, sera élevé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Mais malheur à vous, Scribes et Pharisiens hypocrites, qui fermez le Royaume des cieux aux hommes: car vous-mêmes n’y entrez point, ni ne souffrez que ceux qui y veulent entrer, y entrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Malheur à vous, Scribes et Pharisiens hypocrites; car vous dévorez les maisons des veuves, même sous le prétexte de faire de longues prières, c’est pourquoi vous en recevrez une plus grande condamnation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Malheur à vous, Scribes et Pharisiens hypocrites! car vous courez la mer et la terre pour faire un prosélyte, et après qu’il l’est devenu, vous le rendez fils de la géhenne, deux fois plus que vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Malheur à vous Conducteurs aveugles, qui dites: quiconque aura juré par le Temple, ce n’est rien; mais qui aura juré par l’or du Temple, il est obligé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Fous, et aveugles! car lequel est le plus grand, ou l’or, ou le Temple qui sanctifie l’or?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'Et quiconque, dites-vous, aura juré par l’autel, ce n’est rien; mais qui aura juré par le don qui est sur l’autel, il est lié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Fous et aveugles! car lequel est le plus grand, ou le don, ou l’autel qui sanctifie le don?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Celui donc qui jure par l’autel, jure par l’autel et par toutes les choses qui sont dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'Et quiconque jure par le Temple, jure par le Temple, et par celui qui y habite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'Et quiconque jure par le ciel, jure par le trône de Dieu, et par celui qui y est assis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Malheur à vous, Scribes et Pharisiens hypocrites; car vous payez la dîme de la menthe, de l’aneth et du cumin; et vous laissez les choses les plus importantes de la Loi, c’est-à-dire, le jugement, la miséricorde et la fidélité; il fallait faire ces choses-ci, et ne laisser point celles-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Conducteurs aveugles, vous coulez le moucheron, et vous engloutissez le chameau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Malheur à vous, Scribes et Pharisiens hypocrites, car vous nettoyez le dehors de la coupe et du plat; mais le dedans est plein de rapine et d’intempérance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Pharisien aveugle, nettoie premièrement le dedans de la coupe et du plat, afin que le dehors aussi soit net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Malheur à vous, Scribes et Pharisiens hypocrites; car vous êtes semblables aux sépulcres blanchis, qui paraissent beaux par dehors, mais qui au dedans sont pleins d’ossements de morts, et de toute sorte d’ordure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Ainsi vous paraissez justes par dehors aux hommes, mais au dedans vous êtes pleins d’hypocrisie et d’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Malheur à vous, Scribes et Pharisiens hypocrites, car vous bâtissez les tombeaux des Prophètes, et vous réparez les sépulcres des Justes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'Et vous dites: si nous avions été du temps de nos pères, nous n’aurions pas participé avec eux au meurtre des Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Ainsi vous êtes témoins contre vous-mêmes, que vous êtes les enfants de ceux qui ont fait mourir les Prophètes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Et vous achevez de remplir la mesure de vos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Serpents, race de vipères! comment éviterez-vous le supplice de la géhenne?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Car voici, je vous envoie des Prophètes, et des Sages, et des Scribes, vous en tuerez, vous en crucifierez, vous en fouetterez dans vos Synagogues, et +vous les persécuterez de ville en ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'Afin que vienne sur vous tout le sang juste qui a été répandu sur la terre, depuis le sang d’Abel le juste, jusques au sang de Zacharie, fils de Barachie, que vous avez tué entre le Temple et l’autel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'En vérité je vous dis, que toutes ces choses viendront sur cette génération.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jérusalem, Jérusalem, qui tues les Prophètes, et qui lapides ceux qui te sont envoyés, combien de fois ai-je voulu rassembler tes enfants, comme la poule rassemble ses poussins sous ses ailes, et vous ne l’avez point voulu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Voici, votre maison va devenir déserte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Car je vous dis, que désormais vous ne me verrez plus, jusqu’à ce que vous disiez: béni soit celui qui vient au Nom du Seigneur! Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Et comme Jésus sortait et s’en allait du Temple, ses Disciples s’approchèrent de lui pour lui faire remarquer les bâtiments du Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Et Jésus leur dit: Voyez-vous bien toutes ces choses? en vérité je vous dis, qu’il ne sera laissé ici pierre sur pierre qui ne soit démolie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Puis s’étant assis sur la montagne des oliviers, ses Disciples vinrent à lui en particulier, et lui dirent: Dis-nous quand ces choses arriveront, et quel sera le signe de ton avènement, et de la fin du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Et Jésus répondant leur dit: Prenez garde que personne ne vous séduise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Car plusieurs viendront en mon Nom, disant: je suis le Christ: et ils en séduiront plusieurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Et vous entendrez des guerres et des bruits de guerres; mais prenez garde que vous n’en soyez point troublés; car il faut que toutes ces choses arrivent; mais ce ne sera pas encore la fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Car une nation s’élèvera contre une autre nation, et un Royaume contre un autre Royaume; et il y aura des famines, et des pestes, et des tremblements de terre en divers lieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Mais toutes ces choses ne sont qu’un commencement de douleurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Alors ils vous livreront pour être affligés, et vous tueront; et vous serez haïs de toutes les nations, à cause de mon Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'Et alors plusieurs seront scandalisés, et se trahiront l’un l’autre, et se haïront l’un l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'Et il s’élèvera plusieurs faux prophètes, qui en séduiront plusieurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'Et parce que l’iniquité sera multipliée, la charité de plusieurs se refroidira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Mais qui aura persévéré jusqu’à la fin, celui-là sera sauvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Et cet Evangile du Royaume sera prêché dans toute la terre habitable, pour servir de témoignage à toutes les nations, et alors viendra la fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Or quand vous verrez l’abomination qui causera la désolation, qui a été prédite par Daniel le Prophète, être établie dans le lieu saint, (Que celui qui lit ce Prophète y fasse attention.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'Alors, que ceux qui seront en Judée, s’enfuient aux montagnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'Et que celui qui sera sur la maison, ne descende point pour emporter quoi que ce soit de sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'Et que celui qui est aux champs, ne retourne point en arrière pour emporter ses habits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Mais malheur aux femmes enceintes, et à celles qui allaiteront en ces jours- là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Or priez que votre fuite ne soit point en hiver, ni en un jour de Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Car alors il y aura une grande affliction, telle qu’il n’y en a point eu de semblable depuis le commencement du monde jusques à maintenant, ni il n’y en aura plus de telle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'Et si ces jours-là n’eussent été abrégés, il n’y eût eu personne de sauvé; mais à cause des élus, ces jours-là seront abrégés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Alors si quelqu’un vous dit: Voici, le Christ est ici; ou, il est là; ne le croyez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Car il s’élèvera de faux christs et de faux prophètes, qui feront de grands prodiges et des miracles, pour séduire même les élus, s’il était possible.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Voici, je vous l’ai prédit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Si on vous dit: voici, il est au désert, ne sortez point; voici, il est dans le lieu le plus retiré de la maison, ne le croyez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Mais comme l’éclair sort de l’Orient, et se fait voir jusqu’à l’Occident, il en sera de même de l’avènement du Fils de l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Car où sera le corps mort, là s’assembleront les aigles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Or, aussitôt après l’affliction de ces jours-là, le soleil deviendra obscur, et la lune ne donnera point sa lumière, et les étoiles tomberont du ciel, et les vertus des cieux seront ébranlées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Et alors le signe du Fils de l’homme paraîtra dans le ciel. Alors aussi toutes les Tribus de la terre se lamenteront en se frappant la poitrine, et verront le Fils de l’homme venant dans les nuées du ciel, avec une grande puissance, et une grande gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Et il enverra ses Anges, qui avec un grand son de trompette assembleront ses élus, des quatre vents, depuis l’un des bouts des cieux jusques à l’autre bout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Or apprenez cette similitude prise du figuier: Quand ses branches sont déjà en sève, et qu’il pousse des feuilles, vous connaissez que l’été est proche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'De même quand vous verrez toutes ces choses, sachez que le Fils de l’homme est proche, et qu’il est à la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'En vérité je vous dis, que cette génération ne passera point, que toutes ces choses ne soient arrivées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Le ciel et la terre passeront, mais mes paroles ne passeront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Or quant à ce jour-là, et à l’heure, personne ne le sait; non pas même les Anges du ciel, mais mon Père seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Mais comme il en était aux jours de Noé, il en sera de même de l’avènement du fils de l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Car comme aux jours avant le déluge les hommes mangeaient et buvaient, se mariaient, et donnaient en mariage, jusqu’au jour que Noé entra dans l’arche;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'Et ils ne connurent point que le déluge viendrait, jusqu’à ce qu’il vint, et les emporta tous; il en sera de même de l’avènement du Fils de l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Alors deux hommes seront dans un champ; l’un sera pris, et l’autre laissé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Deux femmes moudront au moulin, l’une sera prise, et l’autre laissée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Veillez donc; car vous ne savez point à quelle heure votre Seigneur doit venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Mais sachez ceci, que si un père de famille savait à quelle veille de la nuit le larron doit venir, il veillerait, et ne laisserait point percer sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'C’est pourquoi, vous aussi tenez-vous prêts; car le Fils de l’homme viendra à l’heure que vous n’y penserez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Qui est donc le serviteur fidèle et prudent, que son maître a établi sur tous ses serviteurs, pour leur donner la nourriture dans le temps qu’il faut?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Bienheureux est ce serviteur que son maître en arrivant trouvera agir de cette manière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'En vérité je vous dis, qu’il l’établira sur tous ses biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Mais si c’est un méchant serviteur, qui dise en soi-même: mon maître tarde à venir;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'Et qu’il se mette à battre ses compagnons de service, et à manger et à boire avec les ivrognes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'Le maître de ce serviteur viendra au jour qu’il ne l’attend point, et à l’heure qu’il ne sait point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'Et il le séparera, et le mettra au rang des hypocrites; là il y aura des pleurs et des grincements de dents. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Alors le Royaume des cieux sera semblable à dix vierges qui ayant pris leurs lampes, s’en allèrent au-devant de l’époux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Or il y en avait cinq sages, et cinq folles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Les folles, en prenant leurs lampes, n’avaient point pris d’huile avec elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Mais les sages avaient pris de l’huile dans leurs vaisseaux avec leurs lampes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Et comme l’époux tardait à venir, elles sommeillèrent toutes, et s’endormirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Or à minuit il se fit un cri, disant: voici, l’époux vient, sortez au- devant de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Alors toutes ces vierges se levèrent, et préparèrent leurs lampes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Et les folles dirent aux sages: donnez-nous de votre huile, car nos lampes s’éteignent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Mais les sages répondirent, en disant: Nous ne pouvons vous en donner, de peur que nous n’en ayons pas assez pour nous et pour vous; mais plutôt allez vers ceux qui en vendent, et en achetez pour vous-mêmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Or pendant qu’elles en allaient acheter, l’époux vint; et celles qui étaient prêtes entrèrent avec lui dans la salle des noces, puis la porte fut fermée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Après cela les autres vierges vinrent aussi, et dirent: Seigneur! Seigneur! ouvre-nous!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Mais il leur répondit, et dit: en vérité je ne vous connais point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Veillez donc; car vous ne savez ni le jour ni l’heure en laquelle le Fils de l’homme viendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Car il en est de lui comme d’un homme qui s’en allant dehors, appela ses serviteurs, et leur commit ses biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'Et il donna à l’un cinq talents, et à l’autre deux, et à un autre un; à chacun selon sa portée; et aussitôt après il partit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Or celui qui avait reçu les cinq talents, s’en alla, et en trafiqua, et gagna cinq autres talents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'De même celui qui avait reçu les deux talents, en gagna aussi deux autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Mais celui qui n’en avait reçu qu’un, s’en alla, et l’enfouit dans la terre, et cacha l’argent de son maître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Or longtemps après le maître de ces serviteurs vint, et fit compte avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Alors celui qui avait reçu les cinq talents, vint, et présenta cinq autres talents, en disant: Seigneur, tu m’as confié cinq talents, voici, j’en ai gagné cinq autres par-dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Et son Seigneur lui dit: cela va bien, bon et fidèle serviteur; tu as été fidèle en peu de chose, je t’établirai sur beaucoup; viens participer à la joie de ton Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Ensuite celui qui avait reçu les deux talents, vint, et dit: Seigneur, tu m’as confié deux talents; voici, j’en ai gagné deux autres par-dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Et son seigneur lui dit: cela va bien, bon et fidèle serviteur, tu as été fidèle en peu de chose, je t’établirai sur beaucoup: viens prendre part à la joie de ton Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Mais celui qui n’avait reçu qu’un talent, vint, et dit: Seigneur, je savais que tu es un homme dur, qui moissonnes où tu n’as point semé; et qui amasses où tu n’as point répandu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'C’est pourquoi craignant de perdre ton talent, je suis allé le cacher dans la terre; voici, tu as ici ce qui t’appartient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Et son Seigneur répondant, lui dit: méchant et lâche serviteur, tu savais que je moissonnais où je n’ai point semé, et que j’amassais où je n’ai point répandu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Il fallait donc que tu donnasses mon argent aux banquiers, et à mon retour je l’aurais reçu avec l’intérêt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Otez-lui donc le talent, et donnez-le à celui qui a les dix talents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Car à chacun qui a, il sera donné, et il en aura encore plus, mais à celui qui n’a rien, cela même qu’il a, lui sera ôté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Jetez donc le serviteur inutile dans les ténèbres de dehors; là il y aura des pleurs et des grincements de dents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Or quand le Fils de l’homme viendra environné de sa gloire et accompagné de tous les saints Anges, alors il s’assiéra sur le trône de sa gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'Et toutes les nations seront assemblées devant lui; et il séparera les uns d’avec les autres, comme le berger sépare les brebis d’avec les boucs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'Et il mettra les brebis à sa droite, et les boucs à sa gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Alors le Roi dira à ceux qui seront à sa droite: venez les bénis de mon Père, possédez en héritage le Royaume qui vous a été préparé dès la fondation du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Car j’ai eu faim, et vous m’avez donné à manger; j’ai eu soif, et vous m’avez donné à boire; j’étais étranger, et vous m’avez recueilli;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'J’étais nu, et vous m’avez vêtu; j’étais malade, et vous m’avez visité; j’étais en prison, et vous êtes venus vers moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Alors les justes lui répondront, en disant: Seigneur, quand est-ce que nous t’avons vu avoir faim, et que nous t’avons donné à manger; ou avoir soif, et que nous t’avons donné à boire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Et quand est-ce que nous t’avons vu étranger, et que nous t’avons recueilli; ou nu, et que nous t’avons vêtu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Ou quand est-ce que nous t’avons vu malade, ou en prison, et que nous sommes venus vers toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Et le Roi répondant, leur dira: en vérité je vous dis, qu’en tant que vous avez fait ces choses à l’un de ces plus petits de mes frères, vous me l’avez fait à moi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Alors il dira aussi à ceux qui seront à sa gauche: Maudits retirez-vous de moi, et allez au feu éternel, qui est préparé au diable et à ses anges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Car j’ai eu faim, et vous ne m’avez point donné à manger; j’ai eu soif et vous ne m’avez point donné à boire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'J’étais étranger, et vous ne m’avez point recueilli; j’ai été nu, et vous ne m’avez point vêtu; j’ai été malade et en prison, et vous ne m’avez point visité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Alors ceux-là aussi lui répondront, en disant: Seigneur, quand est-ce que nous t’avons vu avoir faim, ou avoir soif, ou être étranger, ou nu, ou malade, ou en prison, et que nous ne t’avons point secouru?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Alors il leur répondra, en disant: en vérité je vous dis, que parce que vous n’avez point fait ces choses à l’un de ces plus petits, vous ne me l’avez point fait aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Et ceux-ci s’en iront aux peines éternelles; mais les justes iront jouir de la vie éternelle. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Et il arriva que quand Jésus eut achevé tous ces discours, il dit à ses Disciples:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, 'Vous savez que la Fête de Pâque est dans deux jours; et le Fils de l’homme va être livré pour être crucifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Alors les principaux Sacrificateurs, et les Scribes, et les Anciens du peuple s’assemblèrent dans la salle du souverain Sacrificateur, appelé Caïphe;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'Et tinrent conseil ensemble pour se saisir de Jésus par finesse, afin de le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Mais ils disaient: que ce ne soit point durant la Fête, de peur qu’il ne se fasse quelque émotion parmi le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Et comme Jésus était à Béthanie, dans la maison de Simon le lépreux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'Il vint à lui une femme qui avait un vase d’albâtre plein d’un parfum de grand prix, et qui le répandit sur sa tête, lorsqu’il était à table.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Mais ses Disciples voyant cela, en furent indignés, et dirent: à quoi sert cette perte?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Car ce parfum pouvait être vendu beaucoup, et être donné aux pauvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Mais Jésus connaissant cela, leur dit: pourquoi donnez-vous du déplaisir à cette femme? car elle a fait une bonne action envers moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Parce que vous aurez toujours des pauvres avec vous; mais vous ne m’aurez pas toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Car ce qu’elle a répandu ce parfum sur mon corps, elle l’a fait pour l’appareil de ma sépulture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'En vérité je vous dis, que dans tous les endroits du monde où cet Evangile sera prêché, ce qu’elle a fait sera aussi récité en mémoire d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Alors l’un des douze, appelé Judas Iscariot, s’en alla vers les principaux Sacrificateurs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'Et leur dit: que me voulez-vous donner, et je vous le livrerai? Et ils lui comptèrent trente pièces d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Et dès lors il cherchait une occasion pour le livrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Or le premier jour des pains sans levain, les Disciples vinrent à Jésus, en lui disant: où veux-tu que nous t’apprêtions à manger la Pâque?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Et il répondit: allez à la ville vers un tel, et dites-lui: le Maître dit: mon temps est proche; je ferai la Pâque chez toi avec mes Disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Et les Disciples firent comme Jésus leur avait ordonné, et préparèrent la Pâque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Or quand le soir fut venu, il se mit à table avec les douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'Et comme ils mangeaient, il leur dit: en vérité je vous dis, que l’un de vous me trahira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Et ils en furent fort attristés, et chacun d’eux commença à lui dire: Seigneur, est-ce moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Mais il leur répondit, et dit: celui qui met sa main au plat pour tremper avec moi, c’est celui qui me trahira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Or le Fils de l’homme s’en va, selon qu’il est écrit de lui; mais malheur à cet homme par qui le Fils de l’homme est trahi; il eût été bon à cet homme-là de n’être point né.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Et Judas qui le trahissait, répondant dit: Maître, est-ce moi? Jésus lui dit: tu l’as dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Et comme ils mangeaient, Jésus prit le pain, et après qu’il eut béni Dieu, il le rompit et le donna à ses Disciples, et leur dit: prenez, mangez; ceci est mon corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Puis ayant pris la coupe, et béni Dieu, il la leur donna, en leur disant: buvez-en tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'Car ceci est mon sang, le sang du Nouveau Testament, qui est répandu pour plusieurs en rémission des péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Or je vous dis: que depuis cette heure je ne boirai point de ce fruit de vigne, jusqu’au jour que je le boirai nouveau avec vous, dans le Royaume de mon Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Et quand ils eurent chanté le Cantique, ils s’en allèrent à la montagne des oliviers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Alors Jésus leur dit: vous serez tous cette nuit scandalisés à cause de moi; car il est écrit: je frapperai le Berger, et les brebis du troupeau seront dispersées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Mais après que je serai ressuscité, j’irai devant vous en Galilée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Et Pierre prenant la parole, lui dit: quand même tous seraient scandalisés à cause de toi, je ne le serai jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jésus lui dit: en vérité je te dis, qu’en cette même nuit, avant que le coq ait chanté, tu me renieras trois fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Pierre lui dit: quand même il me faudrait mourir avec toi, je ne te renierai point; et tous les Disciples dirent la même chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Alors Jésus s’en vint avec eux en un lieu appelé Gethsémané; et il dit à ses Disciples: asseyez-vous ici, jusques à ce que j’aie prié dans le lieu où je vais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Et il prit avec lui Pierre et les deux fils de Zébédée, et il commença à être attristé et fort angoissé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Alors il leur dit: mon âme est de toutes parts saisie de tristesse jusques à la mort; demeurez ici, et veillez avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Puis s’en allant un peu plus avant, il se prosterna le visage contre terre, priant, et disant: mon Père, s’il est possible, fais que cette coupe passe loin de moi; toutefois non point comme je le veux, mais comme tu le veux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Puis il vint à ses Disciples, et les trouva dormants, et il dit à Pierre: est-il possible que vous n’ayez pu veiller une heure avec moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Veillez, et priez que vous n’entriez point en tentation: car l’esprit est prompt, mais la chair est faible.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Il s’en alla encore pour la seconde fois, et il pria, disant: mon Père, s’il n’est pas possible que cette coupe passe loin de moi, sans que je la boive; que ta volonté soit faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Il revint ensuite, et les trouva encore dormants; car leurs yeux étaient appesantis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Et les ayant laissés, il s’en alla encore, et pria pour la troisième fois, disant les mêmes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Alors il vint à ses Disciples, et leur dit: Dormez dorénavant, et vous reposez; voici, l’heure est proche, et le Fils de l’homme va être livré entre les mains des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Levez-vous, allons, voici, celui qui me trahit s’approche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Et comme il parlait encore, voici, Judas, l’un des douze, vint, et avec lui une grande troupe, avec des épées et des bâtons, envoyés de la part des principaux Sacrificateurs, et des Anciens du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Or celui qui le trahissait leur avait donné un signal, disant: celui que je baiserai, c’est lui, saisissez-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Et aussitôt s’approchant de Jésus, il lui dit: Maître, je te salue; et il le baisa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Et Jésus lui dit: mon ami, pour quel sujet es-tu ici? Alors s’étant approchés, ils mirent les mains sur Jésus, et le saisirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Et voici, l’un de ceux qui étaient avec Jésus, portant la main sur son épée, la tira, et en frappa le serviteur du souverain Sacrificateur, et lui emporta l’oreille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Alors Jésus lui dit: Remets ton épée en son lieu; car tous ceux qui auront pris l’épée, périront par l’épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Crois-tu que je ne puisse pas maintenant prier mon Père, qui me donnerait présentement plus de douze Légions d’Anges?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Mais comment seraient accomplies les Ecritures qui disent qu’il faut que cela arrive ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'En ce même instant Jésus dit aux troupes: vous êtes sortis avec des épées et des bâtons, comme après un brigand, pour me prendre; j’étais tous les jours assis parmi vous, enseignant dans le Temple, et vous ne m’avez point saisi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Mais tout ceci est arrivé afin que les Ecritures des Prophètes soient accomplies. Alors tous les Disciples l’abandonnèrent, et s’enfuirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Et ceux qui avaient pris Jésus l’amenèrent chez Caïphe, souverain Sacrificateur, chez qui les Scribes et les Anciens étaient assemblés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Et Pierre le suivait de loin, jusques à la cour du souverain Sacrificateur, et étant entré dedans, il s’assit avec les officiers pour voir quelle en serait la fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Or les principaux Sacrificateurs, et les Anciens, et tout le Conseil cherchaient de faux témoignages contre Jésus, pour le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'Mais ils n’en trouvaient point; et bien que plusieurs faux témoins fussent venus, ils n’en trouvèrent point de propres; mais à la fin deux faux témoins s’approchèrent,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'Qui dirent: celui-ci a dit: je puis détruire le Temple de Dieu, et le rebâtir en trois jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Alors le souverain Sacrificateur se leva, et lui dit: ne réponds-tu rien? qu’est-ce que ceux-ci témoignent contre toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Mais Jésus se tut. Et le souverain Sacrificateur prenant la parole, lui dit: je te somme par le Dieu vivant, de nous dire si tu es le Christ, le Fils de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Jésus lui dit: tu l’as dit; de plus, je vous dis, que désormais vous verrez le Fils de l’homme assis à la droite de la Puissance de Dieu, et venant sur les nuées du ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Alors le souverain Sacrificateur déchira ses vêtements, en disant: Il a blasphémé; qu’avons-nous plus affaire de témoins? Voici, vous avez ouï maintenant son blasphème; que vous en semble?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Ils répondirent: il est digne de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Alors ils lui crachèrent au visage, et les uns lui donnaient des soufflets, et les autres le frappaient de leurs verges;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'En lui disant: Christ, prophétise-nous qui est celui qui t’a frappé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Or Pierre était assis dehors dans la cour, et une servante s’approcha de lui, et lui dit: tu étais aussi avec Jésus le Galiléen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Mais il le nia devant tous, en disant: je ne sais ce que tu dis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Et comme il était sorti dans le vestibule, une autre servante le vit, et elle dit à ceux qui étaient là: celui-ci aussi était avec Jésus le Nazarien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Et il le nia encore avec serment, disant: je ne connais point cet homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Et un peu après, ceux qui se trouvaient là s’approchèrent, et dirent à Pierre: certainement tu es aussi de ces gens-là, car ton langage te donne à connaître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Alors il commença à faire des imprécations, et à jurer, en disant: je ne connais point cet homme; et aussitôt le coq chanta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Et Pierre se souvint de la parole de Jésus, qui lui avait dit: avant que le coq ait chanté, tu me renieras trois fois: et étant sorti dehors, il pleura amèrement. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Puis quand le matin fut venu, tous les principaux Sacrificateurs et les Anciens du peuple tinrent conseil contre Jésus pour le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'Et l’ayant lié, ils l’amenèrent et le livrèrent à Ponce Pilate, qui était le Gouverneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Alors Judas qui l’avait trahi, voyant qu’il était condamné, se repentit, et reporta les trente pièces d’argent aux principaux Sacrificateurs et aux Anciens,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'En leur disant: j’ai péché en trahissant le sang innocent; mais ils lui dirent: que nous importe? tu y aviseras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Et après avoir jeté les pièces d’argent dans le Temple, il se retira, et s’en étant allé il s’étrangla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Mais les principaux Sacrificateurs ayant pris les pièces d’argent, dirent: il n’est pas permis de les mettre dans le trésor; car c’est un prix de sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Et après qu’ils eurent consulté entre eux, ils en achetèrent le champ d’un potier, pour la sépulture des étrangers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'C’est pourquoi ce champ-là a été appelé jusqu’à aujourd’hui, le champ du sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Alors fut accompli ce dont il avait été parlé par Jérémie le Prophète, disant: et ils ont pris trente pièces d’argent, le prix de celui qui a été apprécié, lequel ceux d’entre les enfants d’Israël ont apprécié;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'Et ils les ont données pour en acheter le champ d’un potier, selon ce que le Seigneur m’avait ordonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Or Jésus fut présenté devant le Gouverneur, et le Gouverneur l’interrogea, disant: es-tu le Roi des Juifs? Jésus lui répondit: tu le dis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Et étant accusé par les principaux Sacrificateurs et les Anciens, il ne répondait rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Alors Pilate lui dit: n’entends-tu pas combien ils portent de témoignages contre toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Mais il ne lui répondit pas un mot sur quoi que ce fût; de sorte que le Gouverneur s’en étonnait extrêmement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Or le Gouverneur avait accoutumé de relâcher au peuple le jour de la Fête un prisonnier, quel que ce fût qu’on demandât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Et il y avait alors un prisonnier fameux, nommé Barabbas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Quand donc ils furent assemblés, Pilate leur dit: lequel voulez-vous que je vous relâche? Barabbas, ou Jésus qu’on appelle Christ?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Car il savait bien qu’ils l’avaient livré par envie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Et comme il était assis au siége judicial, sa femme envoya lui dire: n’entre point dans l’affaire de ce juste, car j’ai aujourd’hui beaucoup souffert à son sujet en songeant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Et les principaux Sacrificateurs et les Anciens persuadèrent à la multitude du peuple de demander Barabbas, et de faire périr Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Et le Gouverneur prenant la parole leur dit: Lequel des deux voulez-vous que je vous relâche? Ils dirent: Barabbas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Pilate leur dit: que ferai-je donc de Jésus qu’on appelle Christ? Ils lui dirent tous: qu’il soit crucifié!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Et le Gouverneur leur dit: mais quel mal a-t-il fait? et ils crièrent encore plus fort, en disant: qu’il soit crucifié!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Alors Pilate voyant qu’il ne gagnait rien, mais que le tumulte s’augmentait, prit de l’eau, et lava ses mains devant le peuple, en disant: je suis innocent du sang de ce juste, vous y penserez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Et tout le peuple répondant, dit: Que son sang soit sur nous, et sur nos enfants!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Alors il leur relâcha Barabbas; et après avoir fait fouetter Jésus, il le leur livra pour être crucifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Et les soldats du Gouverneur amenèrent Jésus au Prétoire, et assemblèrent devant lui toute la cohorte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'Et après l’avoir dépouillé, ils mirent sur lui un manteau d’écarlate.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'Et ayant fait une couronne d’épines entrelacées, ils la mirent sur sa tête, avec un roseau dans sa main droite; puis s’agenouillant devant lui, ils se moquaient de lui, en disant: nous te saluons, Roi des Juifs!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'Et après avoir craché contre lui, ils prirent le roseau, et ils en frappaient sa tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Et après s’être moqués de lui, ils lui ôtèrent le manteau, et le vêtirent de ses vêtements, et l’amenèrent pour le crucifier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Et comme ils sortaient, ils rencontrèrent un Cyrénéen, nommé Simon, lequel ils contraignirent de porter la croix de Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Et étant arrivés au lieu appelé Golgotha, c’est-à-dire, le lieu du Crâne,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'Ils lui donnèrent à boire du vinaigre mêlé avec du fiel; mais quand il en eut goûté, il n’en voulut point boire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Et après l’avoir crucifié, ils partagèrent ses vêtements, en les jetant au sort, afin que ce qui avait été dit par un Prophète, fût accompli: ils ont partagé entre eux mes vêtements, et ont jeté ma robe au sort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'Puis s’étant assis, ils le gardaient là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'Ils mirent aussi au-dessus de sa tête un écriteau, où la cause de sa condamnation était marquée en ces mots: CELUI-CI EST JÉSUS LE ROI DES JUIFS.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Et deux brigands furent crucifiés avec lui, l’un à sa droite, et l’autre à sa gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Et ceux qui passaient par là, lui disaient des outrages, en branlant la tête,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'Et disant: toi qui détruis le Temple, et qui le rebâtis en trois jours, sauve-toi toi-même; si tu es le Fils de Dieu, descends de la croix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Pareillement aussi les principaux Sacrificateurs avec les Scribes et les Anciens, se moquant, disaient:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, 'Il a sauvé les autres, il ne se peut sauver lui-même: s’il est le Roi d’Israël, qu’il descende maintenant de la croix, et nous croirons en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Il se confie en Dieu; mais si Dieu l’aime, qu’il le délivre maintenant, car il a dit: je suis le Fils de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Les brigands aussi qui étaient crucifiés avec lui, lui reprochaient la même chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Or depuis six heures il y eut des ténèbres sur tout le pays, jusqu’à neuf heures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Et environ les neuf heures Jésus s’écria à haute voix, en disant: Eli, Eli, lamma sabachthani? c’est-à-dire, Mon Dieu! mon Dieu! pourquoi m’as-tu abandonné?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Et quelques-uns de ceux qui étaient là présents, ayant entendu cela, disaient: il appelle Elie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Et aussitôt un d’entre eux courut, et prit une éponge, et l’ayant remplie de vinaigre, la mit au bout d’un roseau, et lui en donna à boire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Mais les autres disaient: laisse, voyons si Elie viendra le sauver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Alors Jésus ayant crié encore à haute voix, rendit l’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'Et voici, le voile du Temple se déchira en deux, depuis le haut jusqu’en bas; et la terre trembla, et les pierres se fendirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'Et les sépulcres s’ouvrirent, et plusieurs corps des Saints, qui étaient morts ressuscitèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'Et étant sortis des sépulcres après sa résurrection, ils entrèrent dans la sainte Citée, et se montrèrent à plusieurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Or le Centenier, et ceux qui avec lui gardaient Jésus, ayant vu le tremblement de terre, et tout ce qui venait d’arriver, eurent une fort grande peur, et dirent: certainement celui-ci était le Fils de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Il y avait là aussi plusieurs femmes qui regardaient de loin, et qui avaient suivi Jésus depuis la Galilée, en le servant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Entre lesquelles étaient Marie-Magdeleine; et Marie mère de Jacques et de Joses; et la mère des fils de Zébédée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Et le soir étant venu, un homme riche d’Arimathée, nommé Joseph, qui même avait été Disciple de Jésus,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Vint à Pilate, et demanda le corps de Jésus; et en même temps Pilate commanda que le corps fût rendu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Ainsi Joseph prit le corps, et l’enveloppa d’un linceul net;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'Et le mit dans son sépulcre neuf, qu’il avait taillé dans le roc; et après avoir roulé une grande pierre à l’entrée du sépulcre, il s’en alla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Et là étaient Marie-Magdeleine et l’autre Marie, assises vis-à-vis du sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Or le lendemain, qui est après la préparation du Sabbat, les principaux Sacrificateurs et les Pharisiens s’assemblèrent vers Pilate,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'Et lui dirent: Seigneur! il nous souvient que ce séducteur disait, quand il était encore en vie: dans trois jours je ressusciterai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Commande donc que le sépulcre soit gardé sûrement jusques au troisième jour; de peur que ses Disciples ne viennent de nuit, et ne le dérobent, et qu’ils ne disent au peuple: il est ressuscité des morts; car cette dernière imposture serait pire que la première.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Mais Pilate leur dit: vous avez la garde; allez, et assurez-le comme vous l’entendrez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Ils s’en allèrent donc, et assurèrent le sépulcre, scellant la pierre, et y mettant des gardes. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Or au soir du Sabbat, au jour qui devait luire pour le premier de la semaine, Marie-Madeleine, et l’autre Marie vinrent voir le sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'Et voici, il se fit un grand tremblement de terre, car l’Ange du Seigneur descendit du ciel, et vint, et roula la pierre à côté de l’entrée du sépulcre, et s’assit sur elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Et son visage était comme un éclair, et son vêtement blanc comme de la neige.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Et les gardes en furent tellement saisis de frayeur, qu’ils devinrent comme morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Mais l’Ange prenant la parole, dit aux femmes: pour vous, n’ayez point de peur; car je sais que vous cherchez Jésus, qui a été crucifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Il n’est point ici; car il est ressuscité, comme il l’avait dit; venez, et voyez le lieu où le Seigneur était couché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'Et allez-vous-en promptement, et dites à ses Disciples qu’il est ressuscité des morts. Et voici, il s’en va devant vous en Galilée, vous le verrez là; voici, je vous l’ai dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Alors elles sortirent promptement du sépulcre avec crainte et grande joie; et coururent l’annoncer à ses Disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Mais comme elles allaient pour l’annoncer à ses Disciples, voici, Jésus se présenta devant elles, et leur dit: je vous salue. Et elles s’approchèrent, et embrassèrent ses pieds, et l’adorèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Alors Jésus leur dit: ne craignez point; allez, et dites à mes frères d’aller en Galilée, et qu’ils me verront là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Or quand elles furent parties, voici, quelques-uns de la garde vinrent dans la ville, et ils rapportèrent aux principaux Sacrificateurs toutes les choses qui étaient arrivées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Sur quoi les Sacrificateurs s’assemblèrent avec les Anciens, et après avoir consulté, ils donnèrent une bonne somme d’argent aux soldats,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'En leur disant: dites: ses Disciples sont venus de nuit, et l’ont dérobé lorsque nous dormions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'Et si le Gouverneur vient à en entendre parler, nous le lui persuaderons, et nous vous mettrons hors de peine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Eux donc ayant pris l’argent, firent ainsi qu’ils avaient été instruits; et ce bruit s’en est répandu parmi les Juifs, jusqu’à aujourd’hui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Mais les onze Disciples s’en allèrent en Galilée, sur la montagne où Jésus leur avait ordonné de se rendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Et quand ils l’eurent vu, ils l’adorèrent, mais quelques-uns doutèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Et Jésus s’approchant leur parla, en disant: toute puissance m’est donnée dans le ciel et sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Allez donc, et enseignez toutes les nations, les baptisant au Nom du Père, et du Fils, et du Saint-Esprit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'Et les enseignant de garder tout ce que je vous ai commandé. Et voici, je suis toujours avec vous jusques à la fin du monde. Amen. Retournez au Début This Website is Hosted by../../lilacsandbutterflies/images/EClilacsbanner.gif ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Le commencement de l’Evangile de Jésus-Christ, Fils de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Selon qu’il est écrit dans les Prophètes: voici, j’envoie mon messager devant ta face, lequel préparera ta voie devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'La voix de celui qui crie dans le désert est: préparez le chemin du Seigneur, aplanissez ses sentiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Jean baptisait dans le désert, et prêchait le Baptême de repentance, pour obtenir la rémission des péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Et tout le pays de Judée, et les habitants de Jérusalem allaient vers lui, et ils étaient tous baptisés par lui dans le fleuve du Jourdain, confessant leurs péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Or Jean était vêtu de poils de chameau, et il avait une ceinture de cuir autour de ses reins, et mangeait des sauterelles et du miel sauvage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Et il prêchait, en disant: il en vient un après moi, qui est plus puissant que moi, duquel je ne suis pas digne de délier en me baissant la courroie des souliers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Pour moi, je vous ai baptisés d’eau; mais il vous baptisera du Saint-Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Or il arriva en ces jours-là que Jésus vint de Nazareth, ville de Galilée, et il fut baptisé par Jean au Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Et en même temps qu’il sortait de l’eau, Jean vit les cieux se fendre, et le Saint-Esprit descendre sur lui comme une colombe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Et il y eut une voix des cieux, disant: tu es mon Fils bien-aimé, en qui j’ai mis toute mon affection.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Et aussitôt l’Esprit le poussa à se rendre dans un désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Et il fut là au désert quarante jours, étant tenté par Satan; et il était avec les bêtes sauvages, et les Anges le servaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Or après que Jean eut été mis en prison, Jésus vint en Galilée, prêchant l’Evangile du Royaume de Dieu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'Et disant: le temps est accompli, et le Royaume de Dieu est approché; convertissez-vous, et croyez à 1’Evangile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Et comme il marchait près de la mer de Galilée, il vit Simon et André son frère, qui jetaient leurs filets dans la mer, car ils étaient pêcheurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Et Jésus leur dit: suivez-moi, et je vous ferai pêcheurs d’hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Et ayant aussitôt quitté leurs filets, ils le suivirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Puis passant de là un peu plus avant, il vit Jacques fils de Zébédée, et Jean son frère, qui raccommodaient leurs filets dans la nacelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'Et aussitôt il les appela, et eux laissant leur père Zébédée dans la nacelle, avec les ouvriers, le suivirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Puis ils entrèrent dans Capernaüm; et aussitôt après, au jour du Sabbat, étant entré dans la Synagogue, il enseignait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'Et ils s’étonnaient de sa doctrine; car il les enseignait comme ayant autorité, et non pas comme les Scribes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'Or il se trouva dans leur Synagogue un homme qui avait un esprit immonde, qui s’écria,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'En disant: Ha! qu’y a-t-il entre toi et nous, Jésus Nazarien? es-tu venu pour nous détruire? Je sais qui tu es: tu es le Saint de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Mais Jésus lui parla fortement, et lui dit: tais-toi, et sors de cet homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Alors l’esprit immonde le tourmentant, et criant à haute voix, sortit de cet homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Et tous en furent étonnés, de sorte qu’ils se demandaient les uns aux autres, et disaient: qu’est ceci? quelle doctrine nouvelle est celle-ci? il commande avec autorité, même aux esprits immondes, et ils lui obéissent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Et sa renommée se répandit incessamment dans tout le pays des environs de la Galilée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Et aussitôt après étant sortis de la Synagogue, ils allèrent avec Jacques et Jean dans la maison de Simon et d’André.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Or la belle-mère de Simon était au lit, malade de la fièvre; et d’abord ils lui parlèrent d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Et s’étant approché, il la releva, en la prenant par la main; et à l’instant la fièvre la quitta; et elle les servit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Or le soir étant venu, comme le soleil se couchait, on lui apporta tous les malades, et les démoniaques,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'Et toute la ville était assemblée devant la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Et il guérit plusieurs malades qui avaient de différentes maladies; et chassa plusieurs démons hors des possédés, et il ne permit point que les démons dissent qu’ils le connussent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Puis au matin, comme il était encore fort nuit, s’étant levé, il sortit, et s’en alla en un lieu désert, et il priait là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Et Simon, et ceux qui étaient avec lui, le suivirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'Et l’ayant trouvé, ils lui dirent: tous te cherchent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Et il leur dit: allons aux bourgades voisines, afin que j’y prêche aussi; car je suis venu pour cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Il prêchait donc dans leurs Synagogues par toute la Galilée, et chassait les démons hors des possédés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Et un lépreux vint à lui, le priant et se mettant à genoux devant lui, et lui disant: si tu veux, tu peux me rendre net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Et Jésus étant ému de compassion étendit sa main, et le toucha, en lui disant: je le veux, sois net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Et quand il eut dit cela, la lèpre se retira aussitôt de cet homme, et il fut net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Puis l’ayant menacé, il le renvoya incessamment,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'Et lui dit: prends garde de n’en rien dire à personne; mais va, et te montre au Sacrificateur, et présente pour ta purification les choses que Moïse a commandées, pour leur servir de témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Mais lui étant parti, commença à publier plusieurs choses, et à divulguer ce qui s’était passé; de sorte que Jésus ne pouvait plus entrer ouvertement dans la ville, mais il se tenait dehors en des lieux déserts; et de toutes parts on venait à lui. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Quelques jours après il revint à Capernaüm; et on ouït dire qu’il était dans la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Et aussitôt il s’y assembla beaucoup de gens, tellement que l’espace même d’auprès de la porte ne les pouvait contenir, et il leur annonçait la parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Et quelques-uns vinrent à lui, portant un paralytique, qui était soutenu par quatre personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Mais parce qu’ils ne pouvaient approcher de lui à cause de la foule, ils découvrirent le toit du lieu où il était, et l’ayant percé, ils descendirent le petit lit dans lequel le paralytique était couché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Et Jésus ayant vu leur foi, dit au paralytique: mon fils, tes péchés te sont pardonnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Et quelques Scribes qui étaient là assis, raisonnaient ainsi en eux-mêmes:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Pourquoi celui-ci prononce-t-il ainsi des blasphèmes? qui est-ce qui peut pardonner les péchés, que Dieu seul?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Et Jésus ayant aussitôt connu par son esprit qu’ils raisonnaient ainsi en eux mêmes, il leur dit: pourquoi faites-vous ces raisonnements dans vos coeurs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Car lequel est le plus aisé, ou de dire au paralytique: tes péchés te sont pardonnés; ou de lui dire: lève-toi, et charge ton petit lit, et marche?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Mais afin que vous sachiez que le Fils de l’homme a le pouvoir sur la terre de pardonner les péchés, il dit au paralytique:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Je te dis: lève-toi, et charge ton petit lit, et t’en va en ta maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Et il se leva aussitôt, et ayant chargé son petit lit, il sortit en la présence de tous; de sorte qu’ils en furent tous étonnés, et ils glorifièrent Dieu, en disant: nous ne vîmes jamais une telle chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Et Jésus sortit encore vers la mer, et tout le peuple venait à lui, et il les enseignait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Et en passant il vit Lévi, fils d’Alphée, assis dans le lieu du péage, et il lui dit: suis-moi. Et Lévi s’étant levé, le suivit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Or il arriva que comme Jésus était à table dans la maison de Lévi, plusieurs péagers et des gens de mauvaise vie se mirent aussi à table avec Jésus et ses Disciples; car il y avait là beaucoup de gens qui l’avaient suivi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Mais les Scribes et les Pharisiens voyant qu’il mangeait avec les péagers et les gens de mauvaise vie, disaient à ses Disciples: pourquoi est-ce qu’il mange et boit avec les péagers et les gens de mauvaise vie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Et Jésus ayant entendu cela, leur dit: ceux qui sont en santé n’ont pas besoin de médecin, mais ceux qui se portent mal; je ne suis point venu appeler à la repentance les justes, mais les pécheurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Or les disciples de Jean et ceux des Pharisiens jeûnaient; et ils vinrent à Jésus, et lui dirent: pourquoi les disciples de Jean, et ceux des Pharisiens jeûnent-ils, et tes Disciples ne jeûnent point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Et Jésus leur répondit: les amis de l’Epoux peuvent-ils jeûner pendant que l’Epoux est avec eux? tandis qu’ils ont l’Epoux avec eux, ils ne peuvent point jeûner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Mais les jours viendront que l’Epoux leur sera ôté, et alors ils jeûneront en ces jours-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Aussi personne ne coud une pièce de drap neuf à un vieux vêtement; autrement la pièce du drap neuf emporte du vieux, et la déchirure en est plus grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Et personne ne met le vin nouveau dans de vieux vaisseaux; autrement le vin nouveau rompt les vaisseaux, et le vin se répand, et les vaisseaux se perdent; mais le vin nouveau doit être mis dans des vaisseaux neufs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Et il arriva que comme il passait par des blés un jour de Sabbat, ses Disciples en marchant se mirent à arracher des épis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Et les Pharisiens lui dirent: regarde, pourquoi font-ils ce qui n’est pas permis les jours de Sabbat?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Mais il leur dit: n’avez-vous jamais lu ce que fit David quand il fut dans la nécessité, et qu’il eut faim, lui et ceux qui étaient avec lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Comment il entra dans la Maison de Dieu, au temps d’Abiathar, principal Sacrificateur, et mangea les pains de proposition, lesquels il n’était permis qu’aux Sacrificateurs de manger; et il en donna même à ceux qui étaient avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Puis il leur dit: le Sabbat est fait pour l’homme, et non pas l’homme pour le Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'De sorte que le Fils de l’homme est Seigneur même du Sabbat. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Puis il entra encore dans la Synagogue, et il y avait là un homme qui avait une main sèche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Et ils l’observaient, pour voir s’il le guérirait le jour du Sabbat, afin de l’accuser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Et Jésus dit à l’homme qui avait la main sèche: lève-toi, et te place là au milieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Puis il leur dit: est-il permis de faire du bien les jours de Sabbat, ou de faire du mal? de sauver une personne, ou de la tuer? mais ils se turent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Alors les regardant de tous côtés avec indignation, et étant tout ensemble affligé de l’endurcissement de leur coeur, il dit à cet homme: étends ta main; et il l’étendit; et sa main fut rendue saine comme l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Alors les Pharisiens étant sortis, ils consultèrent contre lui avec les Hérodiens, comment ils feraient pour le perdre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Mais Jésus se retira avec ses Disciples vers la mer, et une grande multitude le suivit de Galilée, et de Judée, et de Jérusalem, et d’Idumée, et de delà le Jourdain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'Et ceux des environs de Tyr et de Sidon, ayant entendu les grandes choses qu’il faisait, vinrent vers lui en grand nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Et il dit à ses Disciples, qu’une petite nacelle ne bougeât point de là pour le servir, à cause des troupes, afin qu’elles ne le pressassent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Car il en avait guéri beaucoup, de sorte que tous ceux qui étaient affligés de quelque fléau, se jetaient sur lui, pour le toucher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Et les esprits immondes, quand ils le voyaient, se prosternaient devant lui, et s’écriaient, en disant: tu es le Fils de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Mais il leur défendait avec de grandes menaces de le faire connaître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Puis il monta sur une montagne, et appela ceux qu’il voulut, et ils vinrent à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Et il en ordonna douze pour être avec lui, et pour les envoyer prêcher;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'Et afin qu’ils eussent la puissance de guérir les maladies, et de chasser les démons hors des possédés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Et ce sont ici les noms de ces douze, Simon qu’il surnomma Pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'Et Jacques fils de Zébédée, et Jean, frère de Jacques, auxquels il donna le nom de Boanergès, qui veut dire, fils de tonnerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'Et André, et Philippe, et Barthélemy, et Matthieu, et Thomas, et Jacques fils d’Alphée, et Thaddée, et Simon le Cananéen,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'Et Judas Iscariot, qui même le trahit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Puis ils vinrent en la maison, et il s’y assembla encore une si grande multitude, qu’ils ne pouvaient pas même prendre leur repas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Et quand ses parents eurent entendu cela, ils sortirent pour se saisir de lui; car ils disaient qu’il était hors du sens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Et les Scribes qui étaient descendus de Jérusalem, disaient: Il a Béelzébul, et il chasse les démons par le prince des démons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Mais Jésus les ayant appelés, leur dit par des similitudes: comment Satan peut-il chasser Satan dehors?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Car si un Royaume est divisé contre soi-même, ce Royaume-là ne peut point subsister.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'Et si une maison est divisée contre elle-même, cette maison-là ne peut point subsister.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Si donc Satan s’élève contre lui-même, et est divisé, il ne peut point se soutenir, mais il tend à sa fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Nul ne peut entrer dans la maison d’un homme fort, et piller son bien, si auparavant il n’a lié l’homme fort; mais alors il pillera sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'En vérité je vous dis, que toutes sortes de péchés seront pardonnés aux enfants des hommes, et aussi toutes sortes de blasphèmes par lesquels ils auront blasphémé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'Mais quiconque aura blasphémé contre le Saint-Esprit, n’aura jamais de pardon, mais il sera soumis à une condamnation éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Or c’était parce qu’ils disaient: il est possédé d’un esprit immonde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Sur cela ses frères et sa mère arrivèrent là, et se tenant dehors ils l’envoyèrent appeler; et la multitude était assise autour de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'Et on lui dit: voilà ta mère et tes frères là dehors, qui te demandent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Mais il leur répondit, en disant: qui est ma mère, et qui sont mes frères?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Et après avoir regardé de tous côtés ceux qui étaient assis autour de lui, il dit: voici ma mère et mes frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Car quiconque fera la volonté de Dieu, celui-là est mon frère, et ma soeur, et ma mère. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Puis il se mit encore à enseigner près de la mer, et de grandes troupes s’assemblèrent vers lui; de sorte qu’il monta dans une nacelle, et s’étant assis dans la nacelle sur la mer, tout le peuple demeura à terre sur le rivage de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Et il leur enseignait beaucoup de choses par des similitudes, et il leur disait dans ses instructions:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Ecoutez: voici, un semeur sortit pour semer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Et il arriva qu’en semant, une partie de la semence tomba le long du chemin, et les oiseaux du ciel vinrent, et la mangèrent toute');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Une autre partie tomba dans des lieux pierreux, où elle n’avait guère de terre, et aussitôt elle leva, parce qu’elle n’entrait pas profondément dans la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'Mais quand le soleil fut levé, elle fut brûlée, et parce qu’elle n’avait pas de racine, elle se sécha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Une autre partie tomba parmi des épines; et les épines montèrent, et l’étouffèrent, et elle ne rendit point de fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Et une autre partie tomba dans une bonne terre, et rendit du fruit, montant et croissant; tellement qu’un grain en rapporta trente, un autre soixante, et un autre cent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Et il leur dit: qui a des oreilles pour ouïr, qu’il entende!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Et quand il fut en particulier, ceux qui étaient autour de lui avec les douze, l’interrogèrent touchant cette parabole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Et il leur dit: il vous est donné de connaître le secret du Royaume de Dieu; mais à ceux qui sont dehors, toutes choses se traitent par des paraboles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'Afin qu’en voyant ils voient, et n’aperçoivent point; et qu’en entendant ils entendent et ne comprennent point: de peur qu’ils ne se convertissent, et que leurs péchés ne leur soient pardonnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Puis il leur dit: ne comprenez-vous pas cette parabole? et comment donc connaîtrez-vous toutes les paraboles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Le semeur c’est celui qui sème la parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Et voici, ceux qui reçoivent la semence le long du chemin, ce sont ceux en qui la parole est semée, mais après qu’ils l’ont ouïe, Satan vient incessamment, et ravit la parole semée en leurs coeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'De même, ceux qui reçoivent la semence dans des lieux pierreux, ce sont ceux qui ayant ouï la parole, la reçoivent aussitôt avec joie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'Mais ils n’ont point de racine en eux-mêmes, et ne sont que pour un temps; de sorte que l’affliction et la persécution s’élevant à cause de la parole, ils sont incessamment scandalisés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Et ceux qui reçoivent la semence entre les épines sont ceux qui entendent la parole;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'Mais les soucis de ce monde, et la tromperie des richesses, et les convoitises des autres choses étant entrées dans leurs esprits, étouffent la parole, et elle devient infructueuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Mais ceux qui ont reçu la semence dans une bonne terre, sont ceux qui entendent la parole, et qui la reçoivent, et portent du fruit: l’un trente, et l’autre soixante, et l’autre cent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Il leur disait aussi: apporte-t-on la lampe pour la mettre sous un boisseau, ou sous un lit? N’est-ce pas pour la mettre sur un chandelier?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Car il n’y a rien de secret qui ne soit manifesté; et il n’y a rien de caché qui ne vienne en évidence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Si quelqu’un a des oreilles pour ouïr, qu’il entende.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Il leur dit encore: prenez garde à ce que vous entendez; de la mesure dont vous mesurerez, il vous sera mesuré; mais à vous qui entendez, il sera ajouté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Car à celui qui a, il lui sera donné; et à celui qui n’a rien, cela même qu’il a, lui sera ôté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Il disait aussi: le Royaume de Dieu est comme si un homme après avoir jeté de la semence dans la terre, dormait, et se levait de nuit et de jour;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'Et que la semence germât et crût, sans qu’il sache comment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Car la terre produit d’elle-même, premièrement l’herbe, ensuite l’épi, et puis le plein froment dans l’épi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'Et quand le blé est mûr, on y met incessamment la faucille, parce que la moisson est prête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Il disait encore: à quoi comparerons-nous le Royaume de Dieu, ou par quelle similitude le représenterons-nous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Il en est comme du grain de moutarde, qui, lorsqu’on le sème dans la terre, est bien la plus petite de toutes les semences qui sont jetées dans la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'Mais après qu’il est semé, il lève, et devient plus grand que toutes les autres plantes, et jette de grandes branches, tellement que les oiseaux du ciel peuvent faire leurs nids sous son ombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'Ainsi par plusieurs similitudes de cette sorte il leur annonçait la parole de Dieu, selon qu’ils pouvaient l’entendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Et il ne leur parlait point sans similitude; mais en particulier il expliquait tout à ses Disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Or en ce même jour, comme le soir fut venu, il leur dit: passons delà l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Et laissant les troupes, ils l’emmenèrent avec eux, lui étant déjà dans la nacelle; et il y avait aussi d’autres petites nacelles avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Et il se leva un si grand tourbillon de vent, que les vagues se jetaient dans la nacelle, de sorte qu’elle s’emplissait déjà.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Or il était à la poupe, dormant sur un oreiller; et ils le réveillèrent, et lui dirent: Maître, ne te soucies-tu point que nous périssions?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Mais lui étant réveillé, tança le vent, et dit à la mer: tais-toi, sois tranquille; et le vent cessa, et il se fit un grand calme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Puis il leur dit: pourquoi êtes-vous ainsi craintifs? comment n’avez-vous point de foi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Et ils furent saisis d’une grande crainte, et ils se disaient l’un à l’autre: mais qui est celui-ci, que le vent même et la mer lui obéissent? Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Et ils arrivèrent au delà de la mer, dans le pays des Gadaréniens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Et quand il fut sorti de la nacelle, un homme qui avait un esprit immonde, sortit d’abord des sépulcres, et le vint rencontrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'Cet homme faisait sa demeure dans les sépulcres, et personne ne le pouvait tenir lié, non pas même avec des chaînes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'Parce que souvent, quand il avait été lié de fers et de chaînes, il avait rompu les chaînes, et mis les fers en pièces, et personne ne le pouvait dompter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Et il était continuellement de nuit et de jour dans les montagnes, et dans les sépulcres, criant, et se frappant avec des pierres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Mais quand il eut vu Jésus de loin, il courut et se prosterna devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'Et criant à haute voix, il dit: qu’y a-t-il entre nous, Jésus, Fils du Dieu souverain? Je te conjure de la part de Dieu, de ne me tourmenter point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Car Jésus lui disait: sors de cet homme, esprit immonde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Alors il lui demanda: comment te nommes-tu? Et il répondit, et dit: J’ai nom Légion; parce que nous sommes plusieurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Et il le priait instamment qu’il ne les envoyât point hors de cette contrée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Or il y avait là vers les montagnes un grand troupeau de pourceaux qui paissait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'Et tous ces démons le priaient, en disant: Envoie-nous dans les pourceaux, afin que nous entrions en eux; et aussitôt Jésus le leur permit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Alors ces esprits immondes étant sortis, entrèrent dans les pourceaux, et le troupeau, qui était d’environ deux mille, se jeta du haut en bas dans la mer; et ils furent étouffés dans la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Et ceux qui paissaient les pourceaux s’enfuirent, et en portèrent les nouvelles dans la ville, et dans les villages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Et ceux de la ville sortirent pour voir ce qui était arrivé, et vinrent à Jésus; et ils virent le démoniaque, celui qui avait eu la légion, assis et vêtu, et en bon sens; et ils furent saisis de crainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Et ceux qui avaient vu le miracle, leur racontèrent ce qui était arrivé au démoniaque, et aux pourceaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Alors ils se mirent à le prier qu’il se retirât de leurs quartiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Et quand il fut entré dans la nacelle, celui qui avait été démoniaque le pria de permettre qu’il fût avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Mais Jésus ne le lui permit point, et lui dit: va-t’en à ta maison vers les tiens, et raconte-leur les grandes choses que le Seigneur t’a faites, et comment il a eu pitié de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Il s’en alla donc, et se mit à publier en Décapolis les grandes choses que Jésus lui avait faites; et tous s’en étonnaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Et quand Jésus fut repassé à l’autre rivage dans une nacelle, de grandes troupes s’assemblèrent vers lui, et il était près de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Et voici un des Principaux de la Synagogue nommé Jaïrus, vint à lui, et le voyant, il se jeta à ses pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'Et il le priait instamment, en disant: ma petite fille est à l’extrémité; je te prie de venir, et de lui imposer les mains, afin qu’elle soit guérie, et qu’elle vive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Jésus s’en alla donc avec lui; et de grandes troupes de gens le suivaient et le pressaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Or une femme qui avait une perte de sang depuis douze ans,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'Et qui avait beaucoup souffert entre les mains de plusieurs médecins, et avait dépensé tout son bien, sans avoir rien profité, mais plutôt était allée en empirant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Ayant ouï parler de Jésus, vint dans la foule par derrière, et toucha son vêtement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Car elle disait: si je touche seulement ses vêtements, je serai guérie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Et dans ce moment la perte de sang s’arrêta; et elle sentit en son corps qu’elle était guérie de son fléau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Et aussitôt Jésus reconnaissant en soi-même la vertu qui était sortie de lui, se retourna vers la foule, en disant: qui est-ce qui a touché mes vêtements?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Et ses Disciples lui dirent: tu vois que la foule te presse, et tu dis: qui est-ce qui m’a touché?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Mais il regardait tout autour pour voir celle qui avait fait cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Alors la femme saisie de crainte et toute tremblante, sachant ce qui avait été fait en sa personne, vint et se jeta à ses pieds, et lui déclara toute la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Et il lui dit: ma fille! ta foi t’a sauvée; va-t’en en paix, et sois guérie de ton fléau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Comme il parlait encore, il vint des gens de chez le Principal de la Synagogue, qui lui dirent: ta fille est morte, pourquoi donnes-tu encore de la peine au Maître?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Mais Jésus ayant aussitôt entendu ce qu’on disait, dit au Principal de la Synagogue: ne crains point; crois seulement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'Et il ne permit à personne de le suivre, sinon à Pierre, et à Jacques, et à Jean, le frère de Jacques.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Puis il vint à la maison du Principal de la Synagogue, et il vit le tumulte, c’est-à-dire, ceux qui pleuraient et qui jetaient de grands cris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Et étant entré, il leur dit: pourquoi faites-vous tout ce bruit, et pourquoi pleurez-vous? la petite fille n’est pas morte, mais elle dort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'Et ils se riaient de lui. Mais Jésus les ayant tous fait sortir, prit le père et la mère de la petite fille, et ceux qui étaient avec lui, et entra là où la petite fille était couchée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'Et ayant pris la main de l’enfant, il lui dit: Talitha cumi, qui étant expliqué, veut dire: petite fille (je te dis) lève-toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'Et d’abord la petite fille se leva, et marcha; car elle était âgée de douze ans; et ils en furent dans un grand étonnement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Et il leur commanda fort expressément que personne ne le sût; puis il dit qu’on lui donnât à manger. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Puis il partit de là, et vint en son pays; et ses Disciples le suivirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Et le jour du Sabbat étant venu, il se mit à enseigner dans la Synagogue; et beaucoup de ceux qui l’entendaient, étaient dans l’étonnement, et ils disaient: d’où viennent ces choses à celui-ci? et quelle est cette sagesse qui lui est donnée; et que même de tels prodiges se fassent par ses mains?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Celui-ci n’est-il pas charpentier? fils de Marie, frère de Jacques, et de Joses, et de Jude, et de Simon? et ses soeurs ne sont-elles pas ici parmi nous? et ils étaient scandalisés à cause de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Mais Jésus leur dit: un Prophète n’est sans honneur que dans son pays, et parmi ses parents et ceux de sa famille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Et il ne put faire là aucun miracle, sinon qu’il guérit quelque peu de malades, en leur imposant les mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'Et il s’étonnait de leur incrédulité, et parcourait les villages d’alentour, en enseignant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Alors il appela les douze, et commença à les envoyer deux à deux, et leur donna puissance sur les esprits immondes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'Et il leur commanda de ne rien prendre pour le chemin, qu’un seul bâton, et de ne porter ni sac, ni pain, ni monnaie dans leur ceinture;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'Mais d’être chaussés de souliers, et de ne porter point deux robes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Il leur disait aussi: partout où vous entrerez dans une maison, demeurez- y jusqu’à ce que vous partiez de là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'Et tous ceux qui ne vous recevront point, et ne vous écouteront point, en partant de là, secouez la poussière de vos pieds, pour être un témoignage contre eux. En vérité je vous dis, que ceux de Sodome et de Gomorrhe seront traités moins rigoureusement au jour du jugement que cette ville-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Etant donc partis, ils prêchèrent qu’on s’amendât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'Et ils chassèrent plusieurs démons hors des possédés, et oignirent d’huile plusieurs malades, et les guérirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Or le Roi Hérode en ouït parler, car le nom de Jésus était devenu fort célèbre, et il dit: Ce Jean qui baptisait, est ressuscité des morts; c’est pourquoi la vertu de faire des miracles agit puissamment en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Les autres disaient: c’est Elie; et les autres disaient: c’est un Prophète, ou comme un des Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Quand donc Hérode eut appris cela, il dit: c’est Jean que j’ai fait décapiter, il est ressuscité des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Car Hérode avait envoyé prendre Jean, et l’avait fait lier dans une prison, à cause d’Hérodias femme de Philippe son frère, parce qu’il l’avait prise en mariage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Car Jean disait à Hérode: il ne t’est pas permis d’avoir la femme de ton frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'C’est pourquoi Hérodias lui en voulait, et désirait de le faire mourir, mais elle ne pouvait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Car Hérode craignait Jean, sachant que c’était un homme juste et saint, et il avait du respect pour lui, et lorsqu’il l’avait entendu, il faisait beaucoup de choses que Jean avait dit de faire, car il l’écoutait volontiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Mais un jour étant venu à propos, qu’Hérode faisait le festin du jour de sa naissance aux grands Seigneurs, et aux Capitaines, et aux Principaux de la Galilée,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'La fille d’Hérodias y entra, et dansa, et ayant plu à Hérode, et à ceux qui étaient à table avec lui, le Roi dit à la jeune fille: demande-moi ce que tu voudras, et je te le donnerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Et il lui jura, disant: tout ce que tu me demanderas, je te le donnerai, jusqu’à la moitié de mon Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Et elle étant sortie, dit à sa mère: qu’est-ce que je demanderai? Et sa mère lui dit: la tête de Jean Baptiste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Puis étant aussitôt rentrée avec empressement vers le Roi, elle lui fit sa demande, en disant: je voudrais qu’incessamment tu me donnasses dans un plat la tête de Jean Baptiste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Et le Roi en fut très marri, mais il ne voulut pas la refuser à cause du serment, et de ceux qui étaient à table avec lui:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Et il envoya incontinent un de ses gardes, et lui commanda d’apporter la tête de Jean: le garde y alla, et décapita Jean dans la prison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'Et apporta sa tête dans un plat, et la donna à la jeune fille, et la jeune fille la donna à sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Ce que les disciples de Jean ayant appris, ils vinrent et emportèrent son corps, et le mirent dans un sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Or les Apôtres se rassemblèrent vers Jésus, et lui racontèrent tout ce qu’ils avaient fait, et enseigné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Et il leur dit: venez-vous-en à l’écart dans un lieu retiré, et vous reposez un peu; car il y avait beaucoup de gens qui allaient et qui venaient, de sorte qu’ils n’avaient pas même le loisir de manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Ils s’en allèrent donc dans une nacelle en un lieu retiré, pour y être en particulier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Mais le peuple vit qu’ils s’en allaient, et plusieurs l’ayant reconnu, y accoururent à pied de toutes les villes, et y arrivèrent avant eux, et s’assemblèrent auprès de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Et Jésus étant sorti, vit là de grandes troupes, et il fut ému de compassion envers elles, de ce qu’elles étaient comme des brebis qui n’ont point de pasteur; et il se mit à leur enseigner plusieurs choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Et comme il était déjà tard, ses Disciples s’approchèrent de lui, en disant: ce lieu est désert, et il est déjà tard.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Donne-leur congé, afin qu’ils s’en aillent aux villages et aux bourgades d’alentour, et qu’ils achètent des pains pour eux; car ils n’ont rien à manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Et il leur répondit, et dit: donnez-leur vous-mêmes à manger. Et ils lui dirent: irions-nous acheter pour deux cents deniers de pain, afin de leur donner à manger?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Et il leur dit: combien avez-vous de pains? allez et regardez. Et après l’avoir su, ils dirent: cinq, et deux poissons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Alors il leur commanda de les faire tous asseoir par troupes sur l’herbe verte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'Et ils s’assirent par troupes, les unes de cent, et les autres de cinquante personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Et quand il eut pris les cinq pains et les deux poissons, regardant vers le ciel, il bénit Dieu, et rompit les pains, puis il les donna à ses Disciples, afin qu’ils les missent devant eux, et il partagea à tous les deux poissons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Et ils en mangèrent tous, et furent rassasiés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'Et on emporta des pièces de pain douze corbeilles pleines, et quelques restes des poissons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Or ceux qui avaient mangé des pains étaient environ cinq mille hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Et aussitôt après il obligea ses Disciples de monter sur la nacelle, et d’aller devant lui au delà de la mer vers Bethsaïda, pendant qu’il donnerait congé aux troupes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Et quand il leur eut donné congé, il s’en alla sur la montagne pour prier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Et le soir étant venu, la nacelle était au milieu de la mer, et lui seul était à terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Et il vit qu’ils avaient grande peine à ramer, parce que le vent leur était contraire; et environ la quatrième veille de la nuit, il alla vers eux marchant sur la mer, et il les voulait devancer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Mais quand ils le virent marchant sur la mer, ils crurent que ce fût un fantôme, et ils s’écrièrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'Car ils le virent tous, et ils furent troublés; mais il leur parla aussitôt, et leur dit: rassurez-vous, c’est moi; n’ayez point de peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'Et il monta vers eux dans la nacelle, et le vent cessa; ce qui augmenta beaucoup leur étonnement et leur admiration.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'Car ils n’avaient pas bien fait réflexion au miracle des pains; à cause que leur coeur était stupide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Et quand ils furent passés au delà de la mer, ils arrivèrent en la contrée de Génézareth, où ils abordèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Et après qu’ils furent sortis de la nacelle, ceux du lieu le reconnurent d’abord.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'Et ils coururent çà et là par toute la contrée d’alentour, et se mirent à lui apporter de tous côtés les malades dans de petits lits, là où ils entendaient dire qu’il était.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'Et partout où il était entré dans les bourgs, ou dans les villes, ou dans les villages, ils mettaient les malades dans les marchés, et ils le priaient de permettre qu’au moins ils pussent toucher le bord de sa robe; et tous ceux qui le touchaient, étaient guéris. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Alors les Pharisiens, et quelques Scribes qui étaient venus de Jérusalem, s’assemblèrent auprès de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'Et ayant vu que quelques-uns de ses Disciples prenaient leur repas avec des mains souillées, c’est-à-dire, sans être lavées, ils les en blâmèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, '(Car les Pharisiens et tous les Juifs ne mangent point qu’ils ne lavent souvent leurs mains, retenant les traditions des anciens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'Et étant de retour du marché, ils ne mangent point qu’ils ne se soient lavés. Il y a plusieurs autres observances dont ils se sont chargés, comme de laver les coupes, les pots, les vaisseaux d’airain, et les lits.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Sur cela les Pharisiens et les Scribes l’interrogèrent, en disant: pourquoi tes Disciples ne se conduisent-ils pas selon la tradition des Anciens, mais prennent leur repas sans se laver les mains?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Et il leur répondit, et leur dit: certainement Esaïe a bien prophétisé de vous, hypocrites, comme il est écrit: ce peuple m’honore des lèvres, mais leur coeur est bien éloigné de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Mais ils m’honorent en vain, enseignant des doctrines qui ne sont que des commandements d’hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Car en laissant le commandement de Dieu, vous retenez la tradition des hommes, savoir de laver les pots et les coupes, et vous faites beaucoup d’autres choses semblables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Il leur dit aussi: vous annulez bien le commandement de Dieu, afin de garder votre tradition.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Car Moïse a dit: honore ton père et ta mère; et, que celui qui maudira son père ou sa mère, meure de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Mais vous dites: si quelqu’un dit à son père ou à sa mère, le corban (c’est-à-dire le don) qui sera fait de par moi, viendra à ton profit, il ne sera point coupable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'Et vous ne lui permettez plus de rien faire pour son père ou pour sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Anéantissant ainsi la parole de Dieu par votre tradition que vous avez établie; et vous faites encore plusieurs choses semblables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Puis ayant appelé toutes les troupes, il leur dit: écoutez-moi vous tous, et entendez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Il n’y a rien de ce qui est hors de l’homme, qui entrant au dedans de lui, puisse le souiller; mais les choses qui sortent de lui, ce sont celles qui souillent l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Si quelqu’un a des oreilles pour ouïr, qu’il entende.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Puis quand il fut entré dans la maison, s’étant retiré d’avec les troupes, ses Disciples l’interrogèrent touchant cette similitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Et il leur dit: Et vous, êtes-vous donc aussi sans intelligence? ne comprenez-vous pas que tout ce qui entre de dehors dans l’homme ne peut point le souiller?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'Parce qu’il n’entre pas dans son coeur, mais dans l’estomac d’où ensuite cela est jeté dans le lieu secret, en purifiant ainsi le corps de toutes les viandes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Mais il leur disait: ce qui sort de l’homme, c’est ce qui souille l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Car du dedans, c’est-à-dire du coeur des hommes, sortent les mauvaises pensées, les adultères, les fornications, les meurtres,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'Les larcins, les mauvaises pratiques pour avoir le bien d’autrui, les méchancetés, la fraude, l’impudicité, le regard malin, les discours outrageux, la fierté, la folie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Tous ces maux sortent du dedans, et souillent l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Puis partant de là, il s’en alla vers les frontières de Tyr et de Sidon; et étant entré dans une maison, il ne voulait pas que personne le sût; mais il ne put être caché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Car une femme qui avait une petite fille possédée d’un esprit immonde, ayant ouï parler de lui, vint et se jeta à ses pieds;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, '(Or cette femme était Grecque, Syro-Phénicienne de nation) et elle le pria qu’il chassât le démon hors de sa fille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Mais Jésus lui dit: laisse premièrement rassasier les enfants; car il n’est pas raisonnable de prendre le pain des enfants, et de le jeter aux petits chiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Et elle lui répondit, et dit: cela est vrai, Seigneur! cependant les petits chiens mangent sous la table les miettes que les enfants laissent tomber.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Alors il lui dit: à cause de cette parole va-t’en: le démon est sorti de ta fille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Quand elle s’en fut donc allée en sa maison, elle trouva que le démon était sorti, et que sa fille était couchée sur le lit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Puis Jésus étant encore parti des frontières de Tyr et de Sidon, il vint à la mer de Galilée par le milieu du pays de Décapolis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Et on lui amena un sourd qui avait la parole empêchée, et on le pria de poser les mains sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Et Jésus l’ayant tiré à part, hors de la foule, lui mit les doigts dans les oreilles; et ayant craché, lui toucha la langue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'Puis regardant vers le ciel, il soupira, et lui dit: Ephphatha, c’est-à- dire, Ouvre-toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Et aussitôt ses oreilles s’ouvrirent, et le lien de sa langue se délia, et il parla aisément.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Et Jésus leur commanda de ne le dire à personne; mais plus il le défendait, plus ils le publiaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Et ils en étaient extrêmement étonnés, disant: il a tout bien fait; il fait ouïr les sourds, et parler les muets. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'En ces jours-là comme il y avait là une fort grande multitude, et qu’ils n’avaient rien à manger, Jésus appela ses Disciples, et leur dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Je suis ému de compassion envers cette multitude, car il y a déjà trois jours qu’ils ne bougent d’avec moi, et ils n’ont rien à manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'Et si je les renvoie à jeûn en leurs maisons, ils tomberont en défaillance par le chemin, car quelques-uns d’eux sont venus de loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Et ses Disciples lui répondirent: d’où les pourra-t-on rassasier de pains, ici, dans un désert?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Et il leur demanda: combien avez-vous de pains? Ils lui dirent: Sept.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Alors il commanda aux troupes de s’asseoir par terre, et il prit les sept pains, et après avoir béni Dieu il les rompit, et les donna à ses Disciples pour les mettre devant les troupes; et ils les mirent devant elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Ils avaient aussi quelque peu de petits poissons; et après qu’il eut béni Dieu, il commanda qu’ils les leur missent aussi devant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Et ils en mangèrent, et furent rassasiés; et on remporta du reste des pièces de pain sept corbeilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, '(Or ceux qui en avaient mangé étaient environ quatre mille). Et ensuite il leur donna congé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Et aussitôt après il monta dans une nacelle avec ses Disciples, et alla aux quartiers de Dalmanutha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Et il vint là des Pharisiens qui se mirent à disputer avec lui, et qui pour l’éprouver, lui demandèrent quelque miracle du ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Alors Jésus soupirant profondément en son esprit, dit: pourquoi cette génération demande-t-elle un miracle? en vérité je vous dis, qu’il ne lui en sera point accordé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Et les laissant, il remonta dans la nacelle, et passa à l’autre rivage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Or ils avaient oublié de prendre des pains, et ils n’en avaient qu’un avec eux dans la nacelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Et il leur commanda, disant: voyez, donnez-vous de garde du levain des Pharisiens, et du levain d’Hérode.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Et ils discouraient entre eux, disant: c’est parce que nous n’avons point de pains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Et Jésus connaissant cela, leur dit: pourquoi discourez-vous touchant ce que vous n’avez point de pains? ne considérez-vous point encore, et ne comprenez-vous point? avez-vous encore votre coeur stupide?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Ayant des yeux, ne voyez-vous point? ayant des oreilles, n’entendez-vous point? et n’avez-vous point de mémoire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Quand je distribuai les cinq pains aux cinq mille hommes, combien recueillîtes-vous de corbeilles pleines des pièces qu’il y eut de reste? ils lui dirent: douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'Et quand je distribuai les sept pains aux quatre mille hommes, combien recueillîtes-vous de corbeilles pleines des pièces qu’il y eut de reste? ils lui dirent: sept.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Et il leur dit: comment n’avez-vous point d’intelligence?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Puis il vint à Bethsaïda, et on lui présenta un aveugle, en le priant qu’il le touchât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Alors il prit la main de l’aveugle, et le mena hors de la bourgade, et ayant mis de sa salive sur ses yeux, et posé les mains sur lui, il lui demanda s’il voyait quelque chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Et cet homme ayant regardé, dit: Je vois des hommes qui marchent, et qui me paraissent comme des arbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Jésus lui mit encore les mains sur les yeux, et lui commanda de regarder; et il fut rétabli, et les voyait tous de loin clairement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Puis il le renvoya en sa maison, en lui disant: n’entre point dans la bourgade, et ne le dis à personne de la bourgade.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Et Jésus et ses Disciples étant partis de là, ils vinrent aux bourgades de Césarée de Philippe, et sur le chemin il interrogea ses Disciples leur disant: qui disent les hommes que je suis?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Ils répondirent: les uns disent que tu es Jean Baptiste; les autres, Elie; et les autres, l’un des Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Alors il leur dit: et vous, qui dites vous que je suis? Pierre répondant lui dit: tu es le Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Et il leur défendit avec menaces, de dire cela de lui à personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Et il commença à leur enseigner qu’il fallait que le Fils de l’homme souffrît beaucoup, et qu’il fût rejeté des Anciens, et des principaux Sacrificateurs, et des Scribes; et qu’il fût mis à mort, et qu’il ressuscitât trois jours après.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Et il tenait ces discours tout ouvertement; sur quoi Pierre le prit en particulier, et se mit à le reprendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Mais lui se retournant, et regardant ses Disciples, tança Pierre, en lui disant: va arrière de moi, Satan; car tu ne comprends pas les choses qui sont de Dieu, mais celles qui sont des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Puis ayant appelé les troupes et ses Disciples, il leur dit: quiconque veut venir après moi, qu’il renonce à soi même, et qu’il charge sa croix, et me suive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Car quiconque voudra sauver son âme, la perdra; mais quiconque perdra son âme pour l’amour de moi et de l’Evangile, celui-là la sauvera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Car que profiterait-il à un homme de gagner tout le monde, s’il fait la perte de son âme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Ou que donnera l’homme en échange de son âme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Car quiconque aura eu honte de moi et de mes paroles parmi cette nation adultère et pécheresse, le Fils de l’homme aura aussi honte de lui, quand il sera venu environné de la gloire de son Père avec les saints Anges. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Il leur disait aussi: en vérité je vous dis, que parmi ceux qui sont ici présents, il y en a quelques-uns qui ne mourront point jusqu’à ce qu’ils aient vu le Règne de Dieu venir avec puissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Et six jours après, Jésus prit avec soi Pierre et Jacques, et Jean, et les mena seuls à l’écart sur une haute montagne, et il fut transfiguré devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'Et ses vêtements devinrent reluisants et blancs comme de la neige, tels qu’il n’y a point de foulon sur la terre qui les pût ainsi blanchir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Et en même temps leur apparurent Elie et Moïse, qui parlaient avec Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Alors Pierre prenant la parole, dit à Jésus: Maître, il est bon que nous soyons ici; faisons-y donc trois tabernacles, un pour toi, un pour Moïse, et un pour Elie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Or il ne savait ce qu’il disait, car ils étaient épouvantés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Et il vint une nuée qui les couvrit de son ombre; et il vint de la nuée une voix, disant: celui-ci est mon Fils bien-aimé, écoutez-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Et aussitôt ayant regardé de tous côtés, ils ne virent plus personne, sinon Jésus seul avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Et comme ils descendaient de la montagne, il leur commanda expressément de ne raconter à personne ce qu’ils avaient vu, sinon après que le Fils de l’homme serait ressuscité des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Et ils retinrent cette parole-là en eux-mêmes, s’entre-demandant ce que c’était que ressusciter des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Puis ils l’interrogèrent, disant: pourquoi les Scribes disent-ils qu’il faut qu’Elie vienne premièrement?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Il répondit, et leur dit: il est vrai, Elie étant venu premièrement doit rétablir toutes choses, et comme il est écrit du Fils de l’homme, il faut qu’il souffre beaucoup, et qu’il soit chargé de mépris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Mais je vous dis que même Elie est venu, et qu’ils lui ont fait tout ce qu’ils ont voulu, comme il est écrit de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Puis étant revenu vers les Disciples, il vit autour d’eux une grande troupe, et des Scribes qui disputaient avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Et dès que toute cette troupe le vit, elle fut saisie d’étonnement; et ils accoururent pour le saluer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Et il interrogea les Scribes, disant: de quoi disputez-vous avec eux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Et quelqu’un de la troupe prenant la parole, dit: Maître, je t’ai amené mon fils qui a un esprit muet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'Lequel l’agite cruellement partout où il le saisit, et il écume, et grince les dents, et devient sec; et j’ai prié tes Disciples de chasser ce démon, mais ils n’ont pu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Alors Jésus lui répondant, dit: Ô génération incrédule! jusques à quand serai-je avec vous? jusques à quand vous supporterai-je? amenez-le-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'Et ils le lui amenèrent; et quand il l’eut vu l’esprit l’agita sur-le-champ avec violence, de sorte que l’enfant tomba à terre, et se tournait çà et là en écumant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Et Jésus demanda au père de l’enfant: combien y a-t-il de temps que ceci lui est arrivé? et il dit: dès son enfance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'Et souvent il l’a jeté dans le feu et dans l’eau pour le faire périr; mais si tu y peux quelque chose, assiste-nous, étant ému de compassion envers nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Alors Jésus lui dit: si tu le peux croire, toutes choses sont possibles au croyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Et aussitôt le père de l’enfant s’écriant avec larmes, dit: Je crois, Seigneur! aide-moi dans mon incrédulité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Et quand Jésus vit que le peuple y accourait l’un sur l’autre, il censura fortement l’esprit immonde, en lui disant: esprit muet et sourd, je te commande, moi, sors de cet enfant, et n’y rentre plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Et le démon sortit en criant, et faisant beaucoup souffrir cet enfant, qui en devint comme mort, tellement que plusieurs disaient: il est mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Mais Jésus l’ayant pris par la main, le redressa; et il se leva.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Puis Jésus étant entré dans la maison, ses Disciples lui demandèrent en particulier: pourquoi ne l’avons-nous pu chasser?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Et il leur répondit: cette sorte de démons ne peut sortir si ce n’est par la prière et par le jeûne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'Et étant partis de là, ils traversèrent la Galilée; mais il ne voulut pas que personne le sût.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Or il enseignait ses Disciples, et leur disait: le Fils de l’homme va être livré entre les mains des hommes, et ils le feront mourir, mais après qu’il aura été mis à mort, il ressuscitera le troisième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Mais ils ne comprenaient point ce discours, et ils craignaient de l’interroger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'Après ces choses il vint à Capernaüm, et quand il fut arrivé à la maison, il leur demanda: de quoi disputiez-vous ensemble en chemin?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Et ils se turent: car ils avaient disputé ensemble en chemin, qui d’entre eux était le plus grand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Et après qu’il se fut assis, il appela les douze, et leur dit: si quelqu’un veut être le premier entre vous, il sera le dernier de tous, et le serviteur de tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'Et ayant pris un petit enfant, il le mit au milieu d’eux, et après l’avoir pris entre ses bras, il leur dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'Quiconque recevra l’un de tels petits enfants en mon Nom, il me reçoit; et quiconque me reçoit, ce n’est pas moi qu’il reçoit, mais il reçoit celui qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Alors Jean prit la parole, et dit: Maître, nous avons vu quelqu’un qui chassait les démons en ton Nom, et qui pourtant ne nous suit point; et nous l’en avons empêché, parce qu’il ne nous suit point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Mais Jésus leur dit: ne l’en empêchez point; parce qu’il n’y a personne qui fasse un miracle en mon Nom, qui aussitôt puisse mal parler de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Car qui n’est pas contre nous, il est pour nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Et quiconque vous donnera à boire un verre d’eau en mon Nom, parce que vous êtes à Christ, en vérité je vous dis, qu’il ne perdra point sa récompense.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Mais quiconque scandalisera l’un de ces petits qui croient en moi, il lui vaudrait mieux qu’on mit une pierre de meule autour de son cou, et qu’on le jetât dans la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Or si ta main te fait broncher, coupe-la: il vaut mieux que tu entres manchot dans la vie, que d’avoir deux mains, et aller dans la géhenne, au feu qui ne s’éteint point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'Là où leur ver ne meurt point, et le feu ne s’éteint point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'Et si ton pied te fait broncher, coupe-le: il vaut mieux que tu entres boiteux dans la vie, que d’avoir deux pieds, et être jeté dans la géhenne, au feu qui ne s’éteint point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'Là où leur ver ne meurt point, et le feu ne s’éteint point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Et si ton oeil te fait broncher, arrache-le: il vaut mieux que tu entres dans le Royaume de Dieu n’ayant qu’un oeil, que d’avoir deux yeux, et être jeté dans la géhenne du feu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'Là où leur ver ne meurt point, et où le feu ne s’éteint point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Car chacun sera salé de feu; et toute oblation sera salée de sel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'C’est une bonne chose que le sel; mais si le sel devient insipide, avec quoi lui rendra-t-on sa saveur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 51, 'Ayez du sel en vous-mêmes, et soyez en paix entre vous. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Puis étant parti de là, il vint sur les confins de la Judée, au delà du Jourdain, et les troupes s’étant encore assemblées auprès de lui, il les enseignait comme il avait accoutumé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Alors des Pharisiens vinrent à lui, et pour l’éprouver ils lui demandèrent: est-il permis à un homme de répudier sa femme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Il répondit, et leur dit: qu’est-ce que Moïse vous a commandé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Ils dirent: Moïse a permis d’écrire la Lettre de divorce, et de répudier ainsi sa femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Et Jésus répondant leur dit: il vous a donné ce commandement à cause de la dureté de votre coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Mais au commencement de la création, Dieu fit un homme et une femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'C’est pourquoi l’homme laissera son père et sa mère, et s’attachera à sa femme;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'Et les deux seront une seule chair: ainsi ils ne sont plus deux, mais une seule chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Que l’homme donc ne sépare pas ce que Dieu a joint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Puis ses Disciples l’interrogèrent encore sur cela même dans la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Et il leur dit: quiconque laissera sa femme, et se mariera à une autre, il commet un adultère contre elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'Pareillement si la femme laisse son mari, et se marie à un autre, elle commet un adultère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Et on lui présenta de petits enfants, afin qu’il les touchât; mais les Disciples reprenaient ceux qui les présentaient;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Et Jésus voyant cela, en fut indigné, et il leur dit: laissez venir à moi les petits enfants, et ne les en empêchez point; car le Royaume de Dieu appartient à ceux qui leur ressemblent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'En vérité, je vous dis, que quiconque ne recevra pas comme un petit enfant le Royaume de Dieu, il n’y entrera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Après les avoir donc pris entre ses bras, il les bénit, en posant les mains sur eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Et comme il sortait pour se mettre en chemin, un homme accourut, et se mit à genoux devant lui, et lui fit cette demande: Maître qui es bon, que ferai-je pour hériter la vie éternelle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Et Jésus lui répondit: pourquoi m’appelles-tu bon? il n’y a nul être qui soit bon que Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Tu sais les Commandements: Ne commets point adultère. Ne tue point. Ne dérobe point. Ne dis point de faux témoignage. Ne fais aucun tort à personne. Honore ton père et ta mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Il répondit, et lui dit: Maître, j’ai gardé toutes ces choses dès ma jeunesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Et Jésus ayant jeté l’oeil sur lui, l’aima, et lui dit: il te manque une chose; va, et vends tout ce que tu as, et le donne aux pauvres, et tu auras un trésor au ciel; puis viens, et me suis, ayant chargé la croix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Mais il fut fâché de ce mot, et s’en alla tout triste, parce qu’il avait de grands biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Alors Jésus ayant regardé alentour, dit à ses Disciples: combien difficilement ceux qui ont des richesses entreront-ils dans le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Et ses Disciples s’étonnèrent de ces paroles; mais Jésus prenant encore la parole, leur dit: mes enfants, qu’il est difficile à ceux qui se confient aux richesses d’entrer dans le Royaume de Dieu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Il est plus aisé qu’un chameau passe par le trou d’une aiguille, qu’il ne l’est qu’un riche entre dans le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Et ils s’en étonnèrent encore davantage, disant entre eux: et qui peut être sauvé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Mais Jésus les ayant regardés, leur dit: cela est impossible quant aux hommes, mais non pas quant à Dieu; car toutes choses sont possibles à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Alors Pierre se mit à lui dire: voici, nous avons tout quitté, et t’avons suivi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Et Jésus répondant, dit: en vérité je vous dis, qu’il n’y a personne qui ait laissé ou maison, ou frères, ou soeurs, ou père, ou mère, ou femme, ou enfants, ou champs, pour l’amour de moi, et de l’Evangile,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'Qui n’en reçoive maintenant en ce temps-ci cent fois autant, maisons, et frères, et soeurs, et mère, et enfants, et champs, avec des persécutions; et dans le siècle à venir, la vie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Mais plusieurs qui sont les premiers, seront les derniers; et les derniers seront les premiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Or ils étaient en chemin, montant à Jérusalem, et Jésus allait devant eux; et ils étaient épouvantés, et craignaient en le suivant, parce que Jésus ayant encore pris à l’écart les douze, s’était mis à leur déclarer les choses qui lui devaient arriver;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'Disant: voici, nous montons à Jérusalem; et le Fils de l’homme sera livré aux principaux Sacrificateurs, et aux Scribes; et ils le condamneront à mort, et le livreront aux Gentils;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'Qui se moqueront de lui, et le fouetteront, et cracheront contre lui, puis ils le feront mourir; mais il ressuscitera le troisième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Alors Jacques et Jean, fils de Zébédée, vinrent à lui, en lui disant: Maître, nous voudrions que tu fisses pour nous ce que nous te demanderons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Et il leur dit: que voulez-vous que je fasse pour vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Et ils lui dirent: accorde-nous que dans ta gloire nous soyons assis l’un à ta droite, et l’autre à ta gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Et Jésus leur dit: vous ne savez ce que vous demandez; pouvez-vous boire la coupe que je dois boire; et être baptisés du Baptême dont je dois être baptisé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Ils lui répondirent: nous le pouvons. Et Jésus leur dit: il est vrai que vous boirez la coupe que je dois boire, et que vous serez baptisés du Baptême dont je dois être baptisé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'Mais d’être assis à ma droite et à ma gauche, ce n’est pas à moi de le donner; mais il sera donné à ceux à qui il est préparé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Ce que les dix autres ayant ouï, ils conçurent de l’indignation contre Jacques et Jean.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Et Jésus les ayant appelés, leur dit: vous savez que ceux qui dominent sur les nations les maîtrisent, et que les Grands d’entre eux usent d’autorité sur elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Mais il n’en sera pas ainsi entre vous; mais quiconque voudra être le plus grand entre vous, sera votre serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'Et quiconque d’entre vous voudra être le premier, sera le serviteur de tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Car aussi le Fils de l’homme n’est pas venu pour être servi, mais pour servir, et pour donner sa vie en rançon pour plusieurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'Puis ils arrivèrent à Jéricho; et comme il partait de Jéricho avec ses Disciples et une grande troupe, un aveugle, appelé Bartimée, c’est-à-dire, fils de Timée, était assis sur le chemin, et mendiait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'Et ayant entendu que c’était Jésus le Nazarien, il se mit à crier, et à dire: Jésus, Fils de David, aie pitié de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Et plusieurs le censuraient fortement, afin qu’il se tût; mais il criait encore plus fort: Fils de David, aie pitié de moi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Et Jésus s’étant arrêté, dit qu’on l’appelât. On l’appela donc, en lui disant: prends courage, lève-toi, il t’appelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Et jetant bas son manteau, il se leva, et s’en vint à Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Et Jésus prenant la parole, lui dit: que veux-tu que je te fasse? Et l’aveugle lui dit: Maître, que je recouvre la vue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Et Jésus lui dit: Va, ta foi t’a sauvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 53, 'Et sur-le-champ il recouvra la vue, et il suivit Jésus par le chemin. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Et comme ils approchaient de Jérusalem, étant près de Bethphagé, et de Béthanie, vers le mont des oliviers, il envoya deux de ses Disciples,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'Et il leur dit: allez-vous-en à cette bourgade qui est vis-à-vis de vous; et en y entrant, vous trouverez un ânon attaché, sur lequel jamais homme ne s’assit; détachez-le, et l’amenez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Et si quelqu’un vous dit: pourquoi faites-vous cela? dites que le Seigneur en a besoin; et d’abord il l’enverra ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Ils partirent donc, et trouvèrent l’ânon qui était attaché dehors, auprès de la porte, entre deux chemins, et ils le détachèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Et quelques-uns de ceux qui étaient là, leur dirent: pourquoi détachez-vous cet ânon?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Et ils leur répondirent comme Jésus avait commandé; et on les laissa faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Ils amenèrent donc l’ânon à Jésus, et mirent leurs vêtements sur l’ânon, et il s’assit dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Et plusieurs étendaient leurs vêtements par le chemin, et d’autres coupaient des rameaux des arbres, et les répandaient par le chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Et ceux qui allaient devant, et ceux qui suivaient, criaient, disant: Hosanna! Béni soit celui qui vient au Nom du Seigneur!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Béni soit le règne de David notre père, le règne qui vient au Nom du Seigneur; Hosanna dans les lieux très-hauts!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Jésus entra ainsi dans Jérusalem, et au Temple, et après avoir regardé de tous côtés, comme il était déjà tard, il sortit pour aller à Béthanie avec les douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Et le lendemain en revenant de Béthanie, il eut faim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'Et voyant de loin un figuier qui avait des feuilles, il alla voir s’il y trouverait quelque chose, mais y étant venu, il n’y trouva rien que des feuilles; car ce n’était pas la saison des figues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Et Jésus prenant la parole dit au figuier: que jamais personne ne mange de fruit de toi. Et ses Disciples l’entendirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Ils vinrent donc à Jérusalem, et quand Jésus fut entré au Temple, il se mit à chasser dehors ceux qui vendaient, et ceux qui achetaient dans le Temple, et il renversa les tables des changeurs, et les sièges de ceux qui vendaient des pigeons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'Et il ne permettait point que personne portât aucun vaisseau par le Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Et il les enseignait, en leur disant: n’est-il pas écrit? ma Maison sera appelée une Maison de prière par toutes les nations; mais vous en avez fait une caverne de voleurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Ce que les Scribes et les principaux Sacrificateurs ayant entendu, ils cherchaient comment ils feraient pour le perdre; car ils le craignaient, à cause que tout le peuple avait de l’admiration pour sa doctrine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Et le soir étant venu il sortit de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Et le matin comme ils passaient auprès du figuier, ils virent qu’il était devenu sec jusqu’à la racine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Et Pierre s’étant souvenu de ce qui s’était passé, dit à Jésus: Maître, voici, le figuier que tu as maudit, est tout sec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Et Jésus répondant, leur dit: croyez en Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Car en vérité je vous dis, que quiconque dira à cette montagne: quitte ta place, et te jette dans la mer, et qui ne chancellera point en son coeur, mais croira que ce qu’il dit se fera, tout ce qu’il aura dit lui sera fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'C’est pourquoi je vous dis: tout ce que vous demanderez en priant, croyez que vous le recevrez, et il vous sera fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Mais quand vous vous présenterez pour faire votre prière, si vous avez quelque chose contre quelqu’un, pardonnez-lui, afin que votre Père qui est aux cieux vous pardonne aussi vos fautes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Mais si vous ne pardonnez point, votre Père qui est aux cieux ne vous pardonnera point aussi vos fautes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'Ils retournèrent encore à Jérusalem, et comme il marchait dans le Temple, les principaux Sacrificateurs, et les Scribes, et les Anciens vinrent à lui,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'Et lui dirent: par quelle autorité fais-tu ces choses, et qui est celui qui t’a donné cette autorité, pour faire les choses que tu fais?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Et Jésus répondant leur dit: je vous interrogerai aussi d’une chose, et répondez-moi; puis je vous dirai par quelle autorité je fais ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Le Baptême de Jean était-il du ciel, ou des hommes? répondez-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Et ils raisonnaient entre eux, disant: si nous disons, du ciel: il nous dira: pourquoi donc ne l’avez-vous point cru?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Et si nous disons: des hommes, nous avons à craindre le peuple; car tous croyaient que Jean avait été un vrai Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Alors pour réponse ils dirent à Jésus: nous ne savons. Et Jésus répondant leur dit: Je ne vous dirai point aussi par quelle autorité je fais ces choses. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Puis il se mit à leur dire par une parabole: Quelqu’un, dit-il, planta une vigne, et l’environna d’une haie, et il y creusa une fosse pour un pressoir, et y bâtit une tour; puis il la loua à des vignerons, et s’en alla dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Or en la saison des raisins il envoya un serviteur aux vignerons, pour recevoir d’eux du fruit de la vigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Mais eux le prenant, le battirent, et le renvoyèrent à vide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Il leur envoya encore un autre serviteur; et eux lui jetant des pierres, lui meurtrirent la tête, et le renvoyèrent, après l’avoir honteusement traité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Il en envoya encore un autre, lequel ils tuèrent; et plusieurs autres, desquels ils battirent les uns, et tuèrent les autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Mais ayant encore un Fils, son bien-aimé, il le leur envoya aussi pour le dernier, disant: ils respecteront mon Fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Mais ces vignerons dirent entre eux: c’est ici l’héritier, venez, tuons-le, et l’héritage sera nôtre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'L’ayant donc pris, ils le tuèrent, et le jetèrent hors de la vigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Que fera donc le Seigneur de la vigne? il viendra, et fera périr ces vignerons, et donnera la vigne à d’autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Et n’avez-vous point lu cette Ecriture? La pierre que ceux qui bâtissaient ont rejetée, est devenue la maîtresse pierre du coin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'Ceci a été fait par le Seigneur, et c’est une chose merveilleuse devant nos yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Alors ils tâchèrent de le saisir, mais ils craignirent le peuple; car ils connurent qu’il avait dit cette similitude contre eux; c’est pourquoi le laissant, ils s’en allèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Mais ils lui envoyèrent quelques-uns des Pharisiens et des Hérodiens, pour le surprendre dans ses discours;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Lesquels étant venus, lui dirent: Maître, nous savons que tu es véritable, et que tu ne considères personne; car tu n’as point d’égard à l’apparence des hommes, mais tu enseignes la voie de Dieu selon la vérité; est-il permis de payer le tribut à César, ou non? le payerons-nous, ou si nous ne le payerons- nous point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Mais Jésus connaissant leur hypocrisie, leur dit: pourquoi me tentez-vous? apportez-moi un denier, que je le voie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Et ils le lui présentèrent. Alors il leur dit: de qui est cette image, et cette inscription? ils lui répondirent: de César.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Et Jésus répondant leur dit: rendez à César les choses qui sont à César, et à Dieu celles qui sont à Dieu; et ils en furent étonnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Alors les Saducéens, qui disent qu’il n’y a point de résurrection, vinrent à lui, et l’interrogèrent, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Maître, Moïse nous a laissé par écrit: que si le frère de quelqu’un est mort, et a laissé sa femme, et n’a point laissé d’enfants, son frère prenne sa femme, et qu’il suscite lignée à son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Or il y avait sept frères, dont l’aîné prit une femme, et mourant ne laissa point d’enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'Et le second la prit, et mourut, et lui aussi ne laissa point d’enfants; et le troisième tout de même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'Les sept donc la prirent, et ne laissèrent point d’enfants; la femme aussi mourut, la dernière de tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'En la résurrection donc, quand ils seront ressuscités, duquel sera-t-elle la femme? car les sept l’ont eue pour leur femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Et Jésus répondant leur dit: la raison pour laquelle vous tombez dans l’erreur, c’est que vous ne connaissez point les Ecritures, ni la puissance de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Car quand ils seront ressuscités des morts, ils ne prendront point de femme, et on ne leur donnera point de femmes en mariage, mais ils seront comme les Anges qui sont aux cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Et quant aux morts, pour vous montrer qu’ils ressuscitent, n’avez-vous point lu dans le Livre de Moïse, comment Dieu lui parla dans le buisson, en disant: je suis le Dieu d’Abraham, et le Dieu d’Isaac, et le Dieu de Jacob?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Or il n’est pas le Dieu des morts, mais le Dieu des vivants. Vous êtes donc dans une grande erreur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Et quelqu’un des Scribes qui les avait ouïs disputer, voyant qu’il leur avait bien répondu, s’approcha de lui, et lui demanda: quel est le premier de tous les Commandements?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Et Jésus lui répondit: le premier de tous les Commandements est: écoute Israël, le Seigneur notre Dieu est le seul Seigneur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'Et tu aimeras le Seigneur ton Dieu de tout ton coeur, de toute ton âme, de toute ta pensée, et de toute ta force. C’est là le premier Commandement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Et le second, qui est semblable au premier, est celui-ci: tu aimeras ton prochain comme toi-même. Il n’y a point d’autre Commandement plus grand que ceux-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Et le Scribe lui dit: Maître, tu as bien dit selon la vérité, qu’il y a un seul Dieu, et qu’il n’y en a point d’autre que lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'Et que de l’aimer de tout son coeur, de toute son intelligence, de toute son âme, et de toute sa force; et d’aimer son prochain comme soi-même, c’est plus que tous les holocaustes et les sacrifices.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Et Jésus voyant que ce Scribe avait répondu prudemment, lui dit: tu n’es pas loin du Royaume de Dieu. Et personne n’osait plus l’interroger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Et comme Jésus enseignait dans le Temple, il prit la parole, et il dit: comment disent les Scribes que le Christ est le Fils de David?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Car David lui-même a dit par le Saint-Esprit: le Seigneur a dit à mon Seigneur: assieds-toi à ma droite, jusqu’a ce que j’aie mis tes ennemis pour le marchepied de tes pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'Puis donc que David lui-même l’appelle son Seigneur, comment est-il son fils? Et de grandes troupes prenaient plaisir à l’entendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Il leur disait aussi en les enseignant: donnez vous garde des Scribes, qui prennent plaisir à se promener en robes longues, et qui aiment les salutations dans les marchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'Et les premiers sièges dans les Synagogues, et les premières places dans les festins;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'Qui dévorent entièrement les maisons des veuves, même sous le prétexte de faire de longues prières. Ils en recevront une plus grande condamnation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Et Jésus étant assis vis-à-vis du tronc prenait garde comment le peuple mettait de l’argent au tronc.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'Et plusieurs riches y mettaient beaucoup; et une pauvre veuve vint, qui y mit deux petites pièces, qui font la quatrième partie d’un sou.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Et Jésus ayant appelé ses Disciples, il leur dit: en vérité je vous dis, que cette pauvre veuve a plus mis au tronc que tous ceux qui y ont mis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Car tous y ont mis de leur superflu; mais celle-ci y a mis de son indigence tout ce qu’elle avait, toute sa subsistance. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Et comme il se retirait du Temple, un de ses Disciples lui dit: Maître, regarde quelles pierres et quels bâtiments.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Et Jésus répondant lui dit: vois-tu ces grands bâtiments? il n’y sera point laissé pierre sur pierre qui ne soit démolie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Et comme il se fut assis au mont des oliviers vis-à-vis du Temple, Pierre et Jacques, Jean et André, l’interrogèrent en particulier,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Disant: dis-nous quand ces choses arriveront, et quel signe il y aura quand toutes ces choses devront s’accomplir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Et Jésus leur répondant, se mit à leur dire: prenez garde que quelqu’un ne vous séduise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Car plusieurs viendront en mon Nom, disant: c’est moi qui suis le Christ. Et ils en séduiront plusieurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Or quand vous entendrez des guerres, et des bruits de guerres, ne soyez point troublés; parce qu’il faut que ces choses arrivent; mais ce ne sera pas encore la fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Car une nation s’élèvera contre une autre nation, et un Royaume contre un autre Royaume; et il y aura des tremblements de terre de lieu en lieu, et des famines et des troubles: ces choses ne seront que les premières douleurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Mais prenez garde à vous-mêmes: car ils vous livreront aux Consistoires, et aux Synagogues; vous serez fouettés, et vous serez présentés devant les gouverneurs et devant les Rois, à cause de moi, pour leur être en témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Mais il faut que l’Evangile soit auparavant prêché dans toutes les nations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Et quand ils vous mèneront pour vous livrer, ne soyez point auparavant en peine de ce que vous aurez à dire, et n’y méditez point, mais tout ce qui vous sera donné à dire en ce moment-là, dites-le: car ce n’est pas vous qui parlez, mais le Saint-Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Or le frère livrera son frère à la mort, et le père l’enfant, et les enfants se soulèveront contre leurs pères et leurs mères, et les feront mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'Et vous serez haïs de tous à cause de mon Nom; mais qui persévérera jusques à la fin, celui-là sera sauvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Or quand vous verrez l’abomination qui cause la désolation qui a été prédite par Daniel le Prophète, être établie où elle ne doit point être (que celui qui lit ce Prophète y fasse attention!) alors que ceux qui seront en Judée s’enfuient aux montagnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'Et que celui qui sera sur la maison, ne descende point dans la maison, et n’y entre point pour emporter quoi que ce soit de sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'Et que celui qui sera aux champs, ne retourne point en arrière pour emporter son habillement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Mais malheur à celles qui seront enceintes, et à celles qui allaiteront en ces jours-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Or priez Dieu que votre fuite n’arrive point en hiver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Car en ces jours-là il y aura une telle affliction, qu’il n’y en a point eu de semblable depuis le commencement de la création des choses que Dieu a créées, jusqu’à maintenant, et il n’y en aura jamais qui l’égale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Et si le Seigneur n’eût abrégé ces jours-là, il n’y aurait personne de sauvé; mais il a abrégé ces jours, à cause des élus qu’il a élus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Et alors si quelqu’un vous dit: voici, le Christ est ici; ou voici, il est là, ne le croyez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Car il s’élèvera de faux christs et de faux prophètes, qui feront des prodiges et des miracles, pour séduire les élus mêmes, s’il était possible.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Mais donnez-vous-en garde; voici, je vous l’ai tout prédit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Or en ces jours-là, après cette affliction, le soleil sera obscurci, et la lune ne donnera point sa clarté;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'Et les étoiles du ciel tomberont, et les vertus qui sont dans les cieux seront ébranlées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Et ils verront alors le Fils de l’homme venant sur les nuées, avec une grande puissance et une grande gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'Et alors il enverra ses Anges, et il assemblera ses élus, des quatre vents, depuis le bout de la terre jusques au bout au ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Or apprenez cette similitude prise du figuier: quand son rameau est en sève, et qu’il jette des feuilles, vous connaissez que l’été est proche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Ainsi, quand vous verrez que ces choses arriveront, sachez qu’il est proche, et à la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'En vérité je vous dis, que cette génération ne passera point, que toutes ces choses ne soient arrivées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Le ciel et la terre passeront, mais mes paroles ne passeront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Or quant à ce jour et à cette heure, personne ne le sait, non pas même les Anges qui sont au ciel, ni même le Fils, mais mon Père seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Faites attention à tout, veillez et priez: car vous ne savez point quand ce temps arrivera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'C’est comme si un homme allant dehors, et laissant sa maison, donnait de l’emploi à ses serviteurs, et à chacun sa tâche, et qu’il commandât au portier de veiller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Veillez donc: car vous ne savez point quand le Seigneur de la maison viendra, si ce sera le soir, ou à minuit, ou à l’heure que le coq chante, ou au matin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'De peur qu’arrivant tout à coup il ne vous trouve dormants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Or les choses que je vous dis, je les dis à tous; veillez. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Or la fête de Pâque et des pains sans levain était deux jours après; et les principaux Sacrificateurs et les Scribes cherchaient comment ils pourraient se saisir de Jésus par finesse, et le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Mais ils disaient: non point durant la Fête, de peur qu’il ne se fasse du tumulte parmi le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Et comme il était à Béthanie, dans la maison de Simon le lépreux, et qu’il était à table, il vint là une femme qui avait un vase d’albâtre, rempli d’un parfum de nard pur et de grand prix; et elle rompit le vase, et répandit le parfum sur la tête de Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Et quelques-uns en furent indignés en eux-mêmes, et ils disaient: à quoi sert la perte de ce parfum?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Car il pouvait être vendu plus de trois cents deniers, et être donné aux pauvres. Ainsi ils murmuraient contre elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Mais Jésus dit: laissez-la; pourquoi lui donnez-vous du déplaisir? Elle a fait une bonne action envers moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Parce que vous aurez toujours des pauvres avec vous, et vous leur pourrez faire du bien toutes les fois que vous voudrez; mais vous ne m’aurez pas toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Elle a fait ce qui était en son pouvoir, elle a anticipé d’oindre mon corps pour l’appareil de ma sépulture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'En vérité je vous dis, qu’en quelque lieu du monde que cet Evangile sera prêché, ceci aussi qu’elle a fait sera récité en mémoire d’elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Alors Judas Iscariot, l’un des douze, s’en alla vers les principaux Sacrificateurs pour le leur livrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Qui, l’ayant ouï, s’en réjouirent, et lui promirent de lui donner de l’argent, et il cherchait comment il le livrerait commodément.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Or le premier jour des pains sans levain, auquel on sacrifiait l’agneau de Pâque, ses Disciples lui dirent: où veux-tu que nous t’allions apprêter à manger l’agneau de Pâque?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Et il envoya deux de ses Disciples, et leur dit: allez en la ville, et un homme vous viendra à la rencontre, portant une cruche d’eau, suivez-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'Et en quelque lieu qu’il entre, dites au maître de la maison: le Maître dit: où est le logis où je mangerai l’agneau de Pâque avec mes Disciples?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Et il vous montrera une grande chambre, ornée et préparée; apprêtez-nous là l’agneau de Pâque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Ses Disciples donc s’en allèrent; et étant arrivés dans la ville, ils trouvèrent tout comme il leur avait dit, et ils apprêtèrent l’agneau de Pâque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Et sur le soir Jésus vint lui-même avec les douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Et comme ils étaient à table, et qu’ils mangeaient, Jésus leur dit: en vérité je vous dis, que l’un de vous, qui mange avec moi, me trahira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Et ils commencèrent à s’attrister; et ils lui dirent l’un après l’autre: est-ce moi? et l’autre: est-ce moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Mais il répondit, et leur dit: c’est l’un des douze qui trempe avec moi au plat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Certes le Fils de l’homme s’en va, selon qu’il est écrit de lui; mais malheur à l’homme par qui le Fils de l’homme est trahi; il eût été bon à cet homme-là de n’être point né.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Et comme ils mangeaient, Jésus prit le pain, et après avoir béni Dieu, il le rompit, et le leur donna, et leur dit: Prenez, mangez, ceci est mon corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Puis ayant pris la coupe, il rendit grâces, et la leur donna; et ils en burent tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'Et il leur dit: ceci est mon sang, le sang du Nouveau Testament, qui est répandu pour plusieurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'En vérité je vous dis, que je ne boirai plus du fruit de la vigne jusqu’au jour que je le boirai nouveau dans le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Et quand ils eurent chanté le cantique, ils s’en allèrent à la montagne des oliviers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Et Jésus leur dit: vous serez tous cette nuit scandalisés en moi; car il est écrit: je frapperai le Berger, et les brebis seront dispersées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Mais après que je serai ressuscité, j’irai devant vous en Galilée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Et Pierre lui dit: quand même tous seraient scandalisés, je ne le serai pourtant point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Et Jésus lui dit: en vérité, je te dis, qu’aujourd’hui, en cette propre nuit, avant que le coq ait chanté deux fois, tu me renieras trois fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Mais Pierre disait encore plus fortement: quand même il me faudrait mourir avec toi, je ne te renierai point; et ils lui dirent tous la même chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'Puis ils vinrent en un lieu nommé Gethsémané; et il dit à ses Disciples: asseyez-vous ici jusqu’à ce que j’aie prié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Et il prit avec lui Pierre, et Jacques, et Jean, et il commença à être effrayé et fort agité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'Et il leur dit: mon âme est saisie de tristesse jusques à la mort, demeurez ici, et veillez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Puis s’en allant un peu plus outre, il se jeta en terre, et il priait que s’il était possible, l’heure passât arrière de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'Et il disait: Abba, Père, toutes choses te sont possibles, transporte cette coupe arrière de moi, toutefois, non point ce que je veux, mais ce que tu veux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Puis il revint, et les trouva dormants; et il dit à Pierre: Simon, dors-tu? n’as-tu pu veiller une heure?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Veillez, et priez que vous n’entriez point en tentation, car quant à l’esprit, il est prompt, mais la chair est faible.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'Et il s’en alla encore, et il pria, disant les mêmes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Puis étant retourné, il les trouva encore dormants, car leurs yeux étaient appesantis; et ils ne savaient que lui répondre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Il vint encore, pour la troisième fois, et leur dit: dormez dorénavant, et vous reposez; il suffit, l’heure est venue; voici, le Fils de l’homme s’en va être livré entre les mains des méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Levez-vous, allons; voici, celui qui me trahit s’approche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Et aussitôt, comme il parlait encore, Judas, l’un des douze, vint, et avec lui une grande troupe ayant des épées et des bâtons, de la part des principaux Sacrificateurs, et des Scribes et des Anciens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Or celui qui le trahissait avait donné un signal entre eux, disant: celui que je baiserai, c’est lui; saisissez-le, et emmenez-le sûrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Quand donc il fut venu, il s’approcha aussitôt de lui, et lui dit: Maître, Maître, et il le baisa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Alors ils mirent les mains sur Jésus, et le saisirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Et quelqu’un de ceux qui étaient là présents, tira son épée, et en frappa le serviteur du souverain Sacrificateur, et lui emporta l’oreille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Alors Jésus prit la parole, et leur dit: êtes-vous sortis comme après un brigand, avec des épées et des bâtons, pour me prendre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'J’étais tous les jours parmi vous enseignant dans le Temple, et vous ne m’avez point saisi; mais tout ceci est arrivé afin que les Ecritures soient accomplies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Alors tous ses Disciples l’abandonnèrent, et s’enfuirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Et un certain jeune homme le suivait, enveloppé d’un linceul sur le corps nu; et quelques jeunes gens le saisirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'Mais abandonnant son linceul, il s’enfuit d’eux tout nu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Et ils menèrent Jésus au souverain Sacrificateur, chez qui s’assemblèrent tous les principaux Sacrificateurs, les Anciens et les Scribes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Et Pierre le suivait de loin jusque dans la cour du souverain Sacrificateur; et il était assis avec les serviteurs, et se chauffait près du feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Or les principaux Sacrificateurs et tout le Consistoire cherchaient quelque témoignage contre Jésus pour le faire mourir, mais ils n’en trouvaient point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Car plusieurs disaient de faux témoignages contre lui, mais les témoignages n’étaient point suffisants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Alors quelques-uns s’élevèrent, et portèrent de faux témoignages contre lui, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, 'Nous avons ouï qu’il disait: Je détruirai ce Temple qui est fait de main et en trois jours j’en rebâtirai un autre qui ne sera point fait de main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Mais encore avec tout cela leurs témoignages n’étaient point suffisants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Alors le souverain Sacrificateur se levant au milieu, interrogea Jésus, disant: ne réponds-tu rien? qu’est-ce que ceux-ci témoignent contre toi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Mais il se tut, et ne répondit rien. Le souverain Sacrificateur l’interrogea encore, et lui dit: es-tu le Christ, le Fils du Dieu béni?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Et Jésus lui dit: Je le suis; et vous verrez le Fils de l’homme assis à la droite de la puissance de Dieu, et venant sur les nuées du ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Alors le souverain Sacrificateur déchira ses vêtements, et dit: qu’avons- nous encore affaire de témoins?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Vous avez ouï le blasphème: que vous en semble? Alors tous le condamnèrent comme étant digne de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Et quelques-uns se mirent à cracher contre lui, et à lui couvrir le visage, et à lui donner des souffets; et ils lui disaient: prophétise; et les sergents lui donnaient des coups avec leurs verges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Or comme Pierre était en bas dans la cour, une des servantes du souverain Sacrificateur vint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'Et quand elle eut aperçu Pierre qui se chauffait, elle le regarda en face, et lui dit: et toi, tu étais avec Jésus le Nazarien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Mais il le nia, disant: je ne le connais point, et je ne sais ce que tu dis; puis il sortit dehors au vestibule, et le coq chanta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Et la servante l’ayant regardé encore, elle se mit à dire à ceux qui étaient là présents: celui-ci est de ces gens-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Mais il le nia une seconde fois. Et encore un peu après, ceux qui étaient là présents, dirent à Pierre: certainement tu es de ces gens-là, car tu es Galiléen, et ton langage s’y rapporte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Alors il se mit à se maudire, et à jurer, disant: je ne connais point cet homme-là dont vous parlez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Et le coq chanta pour la seconde fois; et Pierre se ressouvint de cette parole que Jésus lui avait dite: avant que le coq ait chanté deux fois, tu me renieras trois fois. Et étant sorti il pleura. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Et d’abord au matin les principaux Sacrificateurs avec les Anciens et les Scribes, et tout le Consistoire, ayant tenu conseil, firent lier Jésus, et l’emmenèrent, et le livrèrent à Pilate.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Et Pilate l’interrogea, disant: es-tu le Roi des Juifs? Et Jésus répondant lui dit: tu le dis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Or les principaux Sacrificateurs l’accusaient de plusieurs choses, mais il ne répondit rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Et Pilate l’interrogea encore, disant: ne réponds-tu rien? vois combien de choses ils déposent contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Mais Jésus ne répondit rien non plus; de sorte que Pilate s’en étonnait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Or il leur relâchait à la Fête un prisonnier, lequel que ce fût qu’ils demandassent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Et il y en avait un, nommé Barabbas, qui était prisonnier avec ses complices pour une sédition, dans laquelle ils avaient commis un meurtre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Et le peuple criant tout haut, se mit à demander à Pilate qu’il fît comme il leur avait toujours fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Mais Pilate leur répondit, en disant: voulez-vous que je vous relâche le Roi des Juifs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, '(Car il savait bien que les principaux Sacrificateurs l’avaient livré par envie.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Mais les principaux Sacrificateurs excitèrent le peuple à demander que plutôt il relâchât Barabbas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Et Pilate répondant, leur dit encore: que voulez-vous donc que je fasse de celui que vous appelez Roi des Juifs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Et ils s’écrièrent encore: crucifie-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Alors Pilate leur dit: mais quel mal a-t-il fait? et ils s’écrièrent encore plus fort: crucifie-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Pilate donc voulant contenter le peuple, leur relâcha Barabbas; et après avoir fait fouetter Jésus, il le livra pour être crucifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Alors les soldats l’emmenèrent dans la cour, qui est le Prétoire, et toute la cohorte s’étant là assemblée,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'Ils le vêtirent d’une robe de pourpre, et ayant fait une couronne d’épines entrelacées l’une dans l’autre, ils la lui mirent sur la tête;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'Puis ils commencèrent à le saluer, en lui disant: nous te saluons, Roi des Juifs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Et ils lui frappaient la tête avec un roseau, et crachaient contre lui; et se mettant à genoux, ils se prosternaient devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Et après s’être ainsi moqués de lui, ils le dépouillèrent de la robe de pourpre, et le revêtirent de ses habits, et l’emmenèrent dehors pour le crucifier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Et ils contraignirent un certain homme, nommé Simon, Cyrénéen, père d’Alexandre et de Rufus, qui passait par là, revenant des champs, de porter sa croix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'Et ils le menèrent au lieu appelé Golgotha, c’est-à-dire, le lieu du Crâne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'Et ils lui donnèrent à boire du vin mixtionné avec de la myrrhe; mais il ne le prit point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'Et quand ils l’eurent crucifié, ils partagèrent ses vêtements, en les jetant au sort pour savoir ce que chacun en aurait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Or il était trois heures quand ils le crucifièrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Et l’écriteau contenant la cause de sa condamnation était: LE ROI DES JUIFS.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Ils crucifièrent aussi avec lui deux brigands, l’un à sa main droite, et l’autre à sa gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'Et ainsi fut accomplie l’Ecriture, qui dit: Et il a été mis au rang des malfaiteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Et ceux qui passaient près de là lui disaient des outrages, branlant la tête, et disant: Hé! toi, qui détruis le Temple, et qui le rebâtis en trois jours,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'Sauve-toi toi-même, et descends de la croix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Les principaux Sacrificateurs se moquant aussi avec les Scribes disaient entre eux: il a sauvé les autres, il ne peut se sauver lui-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Que le Christ, le Roi d’Israël descende maintenant de la croix, afin que nous le voyions et que nous croyions! Ceux aussi qui étaient crucifiés avec lui, lui disaient des outrages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Mais quand il fut six heures, il y eut des ténèbres sur tout le pays jusqu’à neuf heures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'Et à neuf heures Jésus cria à haute voix, disant: Eloï, Eloï, lamma sabachthani? c’est-à-dire: Mon Dieu! Mon Dieu! pourquoi m’as-tu abandonné?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Ce que quelques-uns de ceux qui étaient là présents, ayant entendu, ils dirent: voilà, il appelle Elie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Et quelqu’un accourut, qui remplit une éponge de vinaigre, et qui l’ayant mise au bout d’un roseau, lui en donna à boire, en disant: laissez, voyons si Elie viendra pour l’ôter de la croix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Et Jésus ayant jeté un grand cri, rendit l’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'Et le voile du Temple se déchira en deux, depuis le haut jusqu’en bas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Et le Centenier qui était là vis-à-vis de lui, voyant qu’il avait rendu l’esprit en criant ainsi, dit: certainement cet homme était Fils de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Il y avait là aussi des femmes qui regardaient de loin, entre lesquelles étaient Marie-Magdeleine, et Marie mère de Jacques le mineur, et de Joses, et Salomé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'Qui lorsqu’il était en Galilée, l’avaient suivi, et l’avaient servi; il y avait là aussi plusieurs autres femmes qui étaient montées avec lui à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Et le soir étant déjà venu, parce que c’était la Préparation qui est avant le Sabbat;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'Joseph d’Arimathée, Conseiller honorable, qui attendait aussi le Règne de Dieu, s’étant enhardi, vint à Pilate, et lui demanda le corps de Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Et Pilate s’étonna qu’il fût déjà mort; et ayant appelé le Centenier, il lui demanda s’il y avait longtemps qu’il était mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'Ce qu’ayant appris du Centenier, il donna le corps à Joseph.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Et Joseph ayant acheté un linceul, le descendit de la croix, et l’enveloppa du linceul, et le mit dans un sépulcre qui était taillé dans le roc, puis il roula une pierre sur l’entrée du sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Et Marie-Magdeleine, et Marie mère de Joses regardaient où on le mettait. Retournez au Début');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Or le jour du Sabbat étant passé, Marie-Magdeleine, et Marie mère de Jacques, et Salomé achetèrent des aromates, pour le venir embaumer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Et de fort grand matin, le premier jour de la semaine, elles arrivèrent au sépulcre, le soleil étant levé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Et elles disaient entre elles: qui nous roulera la pierre de l’entrée du sépulcre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Et ayant regardé, elles virent que la pierre était roulée; car elle était fort grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Puis étant entrées dans le sépulcre, elles virent un jeune homme assis à main droite, vêtu d’une robe blanche, et elles s’épouvantèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Mais il leur dit: ne vous épouvantez point; vous cherchez Jésus le Nazarien qui a été crucifié; il est ressuscité, il n’est point ici; voici le lieu où on l’avait mis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Mais allez, et dites à ses Disciples, et à Pierre, qu’il s’en va devant vous en Galilée; vous le verrez là, comme il vous l’a dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Elles partirent aussitôt et s’enfuirent du sépulcre: car le tremblement et la frayeur les avaient saisies, et elles ne dirent rien à personne, car elles avaient peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Or Jésus étant ressuscité le matin du premier jour de la semaine, il apparut premièrement à Marie-Magdeleine, de laquelle il avait chassé sept démons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Et elle s’en alla, et l’annonça à ceux qui avaient été avec lui, lesquels étaient dans le deuil, et pleuraient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Mais quand ils ouïrent dire qu’il était vivant, et qu’elle l’avait vu, ils ne la crurent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Après cela il se montra sous une autre forme à deux d’entre eux, qui étaient en chemin pour aller aux champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Et ceux-ci étant retournés, l’annoncèrent aux autres; mais ils ne les crurent point non plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Enfin il se montra aux onze, qui étaient assis ensemble, et il leur reprocha leur incrédulité et leur dureté de coeur, en ce qu’ils n’avaient point cru ceux qui l’avaient vu ressuscité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Et il leur dit: allez par tout le monde, et prêchez l’Evangile à toute créature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Celui qui aura cru, et qui aura été baptisé, sera sauvé; mais celui qui n’aura point cru, sera condamné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Et ce sont ici les miracles qui accompagneront ceux qui auront cru: ils chasseront les démons en mon Nom; ils parleront de nouveaux langages;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'Ils saisiront les serpents avec la main, et quand ils auront bu quelque chose mortelle, elle ne leur nuira point; ils imposeront les mains aux malades, et ils seront guéris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Or le Seigneur après leur avoir parlé de la sorte fut élevé en haut au ciel, et s’assit à la droite de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Et eux étant partis prêchèrent partout; et le Seigneur coopérait avec eux, et confirmait la parole par les prodiges qui l’accompagnaient. Retournez au Début This Website is Hosted by../../lilacsandbutterflies/images/EClilacsbanner.gif ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Parce que plusieurs se sont appliqués à mettre par ordre un récit des choses qui ont été pleinement certifiées entre nous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'Comme nous les ont donné à connaître ceux qui les ont vues eux-mêmes dès le commencement, et qui ont été les Ministres de la parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'Il m’a aussi semblé bon, après avoir examiné exactement toutes choses depuis le commencement jusques à la fin, très-excellent Théophile, de t’en écrire par ordre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'Afin que tu connaisses la certitude des choses dont tu as été informé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Au temps d’Hérode Roi de Judée, il y avait un certain Sacrificateur nommé Zacharie, du rang d’Abia; et sa femme était des filles d’Aaron, et son nom était Elisabeth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Et ils étaient tous deux justes devant Dieu, marchant dans tous les commandements, et dans toutes les ordonnances du Seigneur, sans reproche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Et ils n’avaient point d’enfants, à cause qu’Elisabeth était stérile; et qu’ils étaient fort avancés en âge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Or il arriva que comme Zacharie exerçait la sacrificature devant le Seigneur, à son tour;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'Selon la coutume d’exercer la sacrificature, le sort lui échut d’offrir le parfum et d’entrer pour cet effet dans le Temple du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Et toute la multitude du peuple était dehors en prières, à l’heure qu’on offrait le parfum.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Et l’Ange du Seigneur lui apparut, se tenant au côté droit de l’autel du parfum.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Et Zacharie fut troublé quand il le vit, et il fut saisi de crainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Mais l’Ange lui dit: Zacharie, ne crains point; car ta prière est exaucée, et Elisabeth ta femme enfantera un fils, et tu appelleras son nom Jean.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Et tu en auras une grande joie, et plusieurs se réjouiront de sa naissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Car il sera grand devant le Seigneur, et il ne boira ni vin ni cervoise; et il sera rempli du Saint-Esprit dès le ventre de sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'Et il convertira plusieurs des enfants d’Israël au Seigneur leur Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Car il ira devant lui animé de l’esprit et de la vertu d’Elie, afin qu’il ramène les coeurs des pères dans les enfants, et les rebelles à la prudence des justes, pour préparer au Seigneur un peuple bien disposé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Alors Zacharie dit à l’Ange: comment connaîtrai-je cela? car je suis vieux, et ma femme est fort âgée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Et l’Ange répondant lui dit: Je suis Gabriel qui me tiens devant Dieu, et qui ai été envoyé pour te parler, et pour t’annoncer ces bonnes nouvelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Et voici, tu seras sans parler, et tu ne pourras point parler jusqu’au jour que ces choses arriveront; parce que tu n’as point cru à mes paroles qui s’accompliront en leur temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Or le peuple attendait Zacharie, et on s’étonnait de ce qu’il tardait tant dans le Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Mais quand il fut sorti, il ne pouvait pas leur parler, et ils connurent qu’il avait vu quelque vision dans le Temple; Car il le leur donnait à entendre par des signes; et il demeura muet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Et il arriva que quand les jours de son ministère furent achevés, il retourna en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Et après ces jours-là, Elisabeth sa femme conçut, et elle se cacha l’espace de cinq mois, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'Certes, le Seigneur en a agi avec moi ainsi aux jours qu’il m’a regardée pour ôter mon opprobre d’entre les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'Or au sixième mois, l’Ange Gabriel fut envoyé de Dieu dans une ville de Galilée, appelée Nazareth;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'Vers une Vierge fiancée à un homme nommé Joseph, qui était de la maison de David; et le nom de la Vierge était Marie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'Et l’Ange étant entré dans le lieu où elle était, lui dit: je te salue, ô toi qui es reçue en grâce; le Seigneur est avec toi; tu es bénie entre les femmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Et quand elle l’eut vu, elle fut fort troublée à cause de ses paroles; et elle considérait en elle-même quelle était cette salutation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Et l’Ange lui dit: Marie, ne crains point; car tu as trouvé grâce devant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Et voici, tu concevras en ton ventre, et tu enfanteras un fils, et tu appelleras son nom JESUS.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Il sera grand, et sera appelé le Fils du Souverain, et le Seigneur Dieu lui donnera le trône de David son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'Et il régnera sur la maison de Jacob éternellement, et il n’y aura point de fin à son règne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Alors Marie dit à l’Ange: comment arrivera ceci, vu que je ne connais point d’homme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'Et l’Ange répondant lui dit: le Saint-Esprit surviendra en toi, et la vertu du Souverain t’enombrera; c’est pourquoi ce qui naîtra de toi Saint, sera appelé le Fils de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Et voici, Elizabeth, ta cousine, a aussi conçu un fils en sa vieillesse; et c’est ici le sixième mois de la grossesse de celle qui était appelée stérile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Car rien ne sera impossible à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Et Marie dit: voici la servante du Seigneur; qu’il me soit fait selon ta parole! Et l’Ange se retira d’avec elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Or en ces jours-là Marie se leva, et s’en alla en hâte au pays des montagnes dans une ville de Juda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'Et elle entra dans la maison de Zacharie, et salua Elisabeth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Et il arriva qu’aussitôt qu’Elisabeth eut entendu ta salutation de Marie, le petit enfant tressaillit en son ventre, et Elisabeth fut remplie du Saint- Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'Et elle s’écria à haute voix, et dit: tu es bénie entre les femmes, et béni est le fruit de ton ventre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Et d’où me vient ceci, que la mère de mon Seigneur vienne vers moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Car voici, dès que la voix de ta salutation est parvenue à mes oreilles, le petit enfant a tressailli de joie en mon ventre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Or bienheureuse est celle qui a cru: car les choses qui lui ont été dites par le Seigneur, auront leur accomplissement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Alors Marie dit: Mon âme magnifie le Seigneur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'Et mon esprit s’est égayé en Dieu, qui est mon Sauveur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Car il a regardé la bassesse de sa servante; voici, certes désormais tous les âges me diront bienheureuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Car le Puissant m’a fait de grandes choses, et son Nom est Saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'Et sa miséricorde est de génération en génération en faveur de ceux qui le craignent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Il a puissamment opéré par son bras; il a dissipé les desseins que les orgueilleux formaient dans leurs cœurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Il a renversé de dessus leurs trônes les puissants, et il a élevé les petits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Il a rempli de biens ceux qui avaient faim; il a renvoyé les riches vides.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Il a pris en sa protection Israël, son serviteur, pour se souvenir de sa miséricorde;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, '(Selon qu’il en a parlé à nos pères, savoir à Abraham et à sa postérité) à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Et Marie demeura avec elle environ trois mois, puis elle s’en retourna en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Or le terme d’Elisabeth fut accompli pour accoucher; et elle mit au monde un fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Et ses voisins, et ses parents ayant appris que le Seigneur avait fait éclater sa miséricorde envers elle, s’en réjouissaient avec elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Et il arriva qu’au huitième jour ils vinrent pour circoncire le petit enfant, et ils l’appelaient Zacharie, du nom de son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Mais sa mère prit la parole, et dit: Non, mais il sera nommé Jean.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'Et ils lui dirent: il n’y a personne en ta parenté gui soit appelé de ce nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'Alors ils firent signe à son père, qu’il déclarât comment il voulait qu’il fût nommé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Et Zacharie ayant demandé des tablettes, écrivit: Jean est son nom; et tous en furent étonnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'Et à l’instant sa bouche fut ouverte, et sa langue déliée, tellement qu’il parlait en louant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Et tous ses voisins en furent saisis de crainte; et toutes ces choses furent divulguées dans tout le pays des montagnes de Judée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'Et tous ceux qui les entendirent les mirent en leur coeur, disant: que sera-ce de ce petit enfant? et la main du Seigneur était avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Alors Zacharie son père fut rempli du Saint-Esprit, et il prophétisa, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, 'Béni soit le Seigneur, le Dieu d’Israël, de ce qu’il a visité et délivré son peuple;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'Et de ce qu’il nous a suscité un puissant Sauveur dans la maison de David, son serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'Selon ce qu’il avait dit par la bouche de ses saints Prophètes, qui ont été de tout temps;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'Que nous serions sauvés de la main de nos ennemis, et de la main de tous ceux qui nous haïssent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'Pour exercer sa miséricorde envers nos pères, et pour avoir mémoire de sa sainte alliance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'Qui est le serment qu’il a fait à Abraham notre père;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'Savoir, qu’il nous accorderait, qu’étant délivrés de la main de nos ennemis, nous le servirions sans crainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'En sainteté et en justice devant lui, tous les jours de notre vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Et toi, petit enfant, tu seras appelé le Prophète du Souverain; car tu iras devant la face du Seigneur, pour préparer ses voies;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'Et pour donner la connaissance du salut à son peuple, dans la rémission de leurs péchés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'Par les entrailles de la miséricorde de notre Dieu, desquelles l’Orient d’en haut nous a visités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'Afin de reluire à ceux qui sont assis dans les ténèbres et dans l’ombre de la mort, et pour conduire nos pas dans le chemin de la paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Et le petit enfant croissait, et se fortifiait en esprit; et il fut dans les déserts jusqu’au jour qu’il devait être manifesté à Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Or il arriva en ces jours-là, qu’un Edit fut publié de la part de César Auguste, portant que tout le monde fût enregistré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Et cette première description fut faite lorsque Cyrénius avait le gouvernement de Syrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Ainsi tous allaient pour être mis par écrit, chacun en sa ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Et Joseph monta de Galilée en Judée, savoir de la ville de Nazareth, en la cité de David, appelée Bethléhem, à cause qu’il était de la maison et de la famille de David;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'Pour être enregistré avec Marie, la femme qui lui avait été fiancée, laquelle était enceinte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Et il arriva comme ils étaient là, que son terme pour accoucher fut accompli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'Et elle mit au monde son fils premier-né, et l’emmaillota, et le coucha dans une crèche, à cause qu’il n’y avait point de place pour eux dans l’hôtellerie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Or il y avait en ces quartiers-là des bergers couchant aux champs, et gardant leur troupeau durant les veilles de la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Et voici, l’Ange du Seigneur survint vers eux, et la clarté du Seigneur resplendit autour d’eux, et ils furent saisis d’une fort grande peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Mais l’Ange leur dit: n’ayez point de peur; car voici, je vous annonce un grand sujet de joie qui sera tel pour tout le peuple:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'C’est qu’aujourd’hui dans la cité de David vous est né le Sauveur, qui est le Christ, le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Et c’est ici la marque à laquelle vous le reconnaîtrez, c’est que vous trouverez le petit enfant emmailloté, et couché dans une crèche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Et aussitôt avec l’Ange il y eut une multitude de l’armée céleste, louant Dieu, et disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Gloire soit à Dieu dans les lieux très-hauts, que la paix soit sur la terre et la bonne volonté dans les hommes!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Et il arriva qu’après que les Anges s’en furent allés d’avec eux au ciel, les bergers dirent entre eux: allons donc jusqu’à Bethléhem, et voyons cette chose qui est arrivée, et que le Seigneur nous a découverte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Ils allèrent donc à grand hâte, et ils trouvèrent Marie et Joseph, et le petit enfant couché dans une crèche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Et quand ils l’eurent vu, ils divulguèrent ce qui leur avait été dit touchant ce petit enfant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Et tous ceux qui les ouïrent s’étonnèrent des choses qui leur étaient dites par les bergers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Et Marie gardait soigneusement toutes ces choses, et les repassait dans son esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Puis les bergers s’en retournèrent, glorifiant et louant Dieu de toutes ces choses qu’ils avaient ouïes et vues, selon qu’il leur en avait été parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Et quand les huit jours furent accomplis pour circoncire l’enfant, alors son nom fut appelé JESUS, lequel avait été nommé par l’Ange, avant qu’il fût conçu dans le ventre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Et quand les jours de la purification de Marie furent accomplis selon la Loi de Moïse, ils le portèrent à Jérusalem, pour le présenter au Seigneur,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '(Selon ce qui est écrit dans la Loi du Seigneur: que tout mâle premier-né sera appelé saint au Seigneur.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'Et pour offrir l’oblation prescrite dans la Loi du Seigneur, savoir une paire de tourterelles, ou deux pigeonneaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'Or voici, il y avait à Jérusalem un homme qui avait nom Siméon, et cet homme était juste et craignant Dieu, et il attendait la consolation d’Israël; et le Saint-Esprit était en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'Et il avait été averti divinement par le Saint-Esprit, qu’il ne mourrait point, que premièrement il n’eût vu le Christ du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Lui donc étant poussé par l’Esprit vint au Temple; et comme le père et la mère portaient dans le Temple le petit enfant Jésus, pour faire de lui selon l’usage de la Loi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'Il le prit entre ses bras, et bénit Dieu, et dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Seigneur, tu laisses maintenant aller ton serviteur en paix selon ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'Car mes yeux ont vu ton salut;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'Lequel tu as préparé devant la face de tous les peuples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'La lumière pour éclairer les nations; et pour être la gloire de ton peuple d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Et Joseph et sa mère s’étonnaient des choses qui étaient dites de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Et Siméon le bénit, et dit à Marie sa mère: voici, celui-ci est mis pour être une occasion de chute et de relèvement de plusieurs en Israël, et pour être un signe auquel on contredira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, '(Et même aussi une épée percera ta propre âme) afin que les pensées de plusieurs coeurs soient découvertes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Il y avait aussi Anne la Prophétesse, fille de Phanuel de la Tribu d’Aser, qui était déjà avancée en âge, et qui avait vécu avec son mari sept ans depuis sa virginité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'Et veuve d’environ quatre-vingt-quatre ans, elle ne bougeait point du temple, servant Dieu en jeûnes et en prières, nuit et jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Elle étant donc survenue en ce même moment, louait aussi le Seigneur, et parlait de lui à tous ceux qui attendaient la délivrance à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Et quand ils eurent accompli tout ce qui est ordonné par la Loi du Seigneur, ils s’en retournèrent en Galilée, à Nazareth leur ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Et le petit enfant croissait et se fortifiait en esprit, étant rempli de sagesse; et la grâce de Dieu était sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Or son père et sa mère allaient tous les ans à Jérusalem à la fête de Pâque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Et quand il eut atteint l’âge de douze ans, son père et sa mère étant montés à Jérusalem selon la coutume de la fête,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'Et s’en retournant après avoir accompli les jours de la Fête, l’enfant Jésus demeura dans Jérusalem; et Joseph et sa mère ne s’en aperçurent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Mais croyant qu’il était dans la troupe des voyageurs, ils marchèrent une journée; puis ils le cherchèrent entre leurs parents et ceux de leur connaissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'Et ne le trouvant point, ils s’en retournèrent à Jérusalem, en le cherchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'Or il arriva que trois jours après ils le trouvèrent dans le Temple, assis au milieu des Docteurs, les écoutant, et les interrogeant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'Et tous ceux qui l’entendaient s’étonnaient de sa sagesse et de ses réponses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Et quand ils le virent, ils en furent étonnés, et sa mère lui dit: mon enfant, pourquoi nous as-tu fait ainsi; voici, ton père et moi te cherchions étant en grande peine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Et il leur dit: pourquoi me cherchiez vous? ne saviez-vous pas qu’il me faut être occupé aux affaires de mon Père?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Mais ils ne comprirent point ce qu’il leur disait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Alors il descendit avec eux, et vint à Nazareth; et il leur était soumis; et sa mère conservait toutes ces paroles-là dans son coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Et Jésus s’avançait en sagesse, et en stature, et en grâce, envers Dieu et envers les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Or en la quinzième année de l’empire de Tibère César, lorsque Ponce Pilate était Gouverneur de la Judée, et qu’Hérode était Tétrarque en Galilée, et son frère Philippe Tétrarque dans la contrée d’Iturée et de Trachonite, et Lysanias Tétrarque en Abilène;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'Anne et Caïphe étant souverains Sacrificateurs, la parole de Dieu fut adressée à Jean fils de Zacharie, au désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Et il vint dans tout le pays des environs du Jourdain, prêchant le Baptême de repentance, pour la rémission des péchés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'Comme il est écrit au Livre des paroles d’Esaïe le Prophète, disant: la voix de celui qui crie dans le désert, est: Préparez le chemin du Seigneur, aplanissez ses sentiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Toute vallée sera comblée, et toute montagne et toute colline sera abaissée, et les choses tortues seront redressées, et les chemins raboteux seront aplanis;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'Et toute chair verra le salut de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Il disait donc à la foule de ceux qui venaient pour être baptisés par lui: Race de vipères, qui vous a avertis de fuir la colère à venir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Faites des fruits convenables à la repentance, et ne vous mettez point à dire en vous-mêmes: nous avons Abraham pour père; car je vous dis, que Dieu peut faire naître, même de ces pierres, des enfants à Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Or la cognée est déjà mise à la racine des arbres; tout arbre donc qui ne fait point de bon fruit, s’en va être coupé, et jeté au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Alors les troupes l’interrogèrent, disant: que ferons-nous donc?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Et il répondit, et leur dit: que celui qui a deux robes en donne une à celui qui n’en a point; et que celui qui a de quoi manger en fasse de même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Il vint aussi à lui des péagers pour être baptisés, qui lui dirent: maître, que ferons-nous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Et il leur dit: n’exigez rien au-delà de ce qui vous est ordonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Les gens de guerre l’interrogèrent aussi, disant: et nous, que ferons-nous? Il leur dit: n’usez point de concussion, ni de fraude contre personne, mais contentez-vous de vos gages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Et comme le peuple était dans l’attente, et raisonnait en soi-même si Jean n’était point le Christ,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Jean prit la parole, et dit à tous: pour moi, je vous baptise d’eau; mais il en vient un plus puissant que moi, duquel je ne suis pas digne de délier la courroie des souliers; celui-là vous baptisera du Saint-Esprit et de feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Il a son van en sa main, et il nettoiera entièrement son aire, et assemblera le froment dans son grenier, mais il brûlera la paille au feu qui ne s’éteint point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Et en faisant plusieurs autres exhortations, il évangélisait au peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Mais Hérode le Tétrarque étant repris par lui au sujet d’Hérodias, femme de Philippe son frère, et à cause de tous les maux qu’il avait faits,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'Ajouta encore à tous les autres celui de mettre Jean en prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Or il arriva que comme tout le peuple était baptisé, Jésus aussi étant baptisé, et priant, le ciel s’ouvrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'Et le Saint-Esprit descendit sur lui sous une forme corporelle, comme celle d’une colombe; et il y eut une voix du ciel, qui lui dit: tu es mon Fils bien-aimé, j’ai pris en toi mon bon plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Et Jésus commençait d’avoir environ trente ans, fils (comme on l’estimait) de Joseph, qui était fils de Héli,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'Fils de Matthat, fils de Lévi, fils de Melchi, fils de Janna, fils de Joseph,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'Fils de Mattathie, fils d’Amos, fils de Nahum, fils d’Héli, fils de Naggé,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'Fils de Maath, fils de Mattathie, fils de Sémei, fils de Joseph, fils de Juda,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'Fils de Johanna, fils de Rhésa, fils de Zorobabel, fils de Salathiel, fils de Néri,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'Fils de Melchi, fils d’Addi, fils de Cosam, fils d’Elmodam, fils d’Er,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'Fils de José, fils d’Eliézer, fils de Jorim, fils de Matthat, fils de Lévi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'Fils de Siméon, fils de Juda, fils de Joseph, fils de Jonan, fils d’Eliakim,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'Fils de Melca, fils de Maïnan, fils de Matthata, fils de Nathan, fils de David,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'Fils de Jessé, fils d’Obed, fils de Booz, fils de Salmon, fils de Naasson,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'Fils d’Aminadab, fils d’Aram, fils d’Esrom, fils de Pharès, fils de Juda,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'Fils de Jacob, fils d’Isaac, fils d’Abraham, fils de Thara, fils de Nachor,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'Fils de Sarug, fils de Ragau, fils de Phaleg, fils d’Héber, fils de Sala,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'Fils de Caïnan, fils d’Arphaxad, fils de Sem, fils de Noé, fils de Lamech,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'Fils de Mathusala, fils d’Hénoc, fils de Jared, fils de Mahalaléel, fils de Caïnan,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'Fils d’Enos, fils de Seth, fils d’Adam, fils de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Or Jésus étant rempli du Saint-Esprit s’en retourna de devers le Jourdain, et fut mené par la vertu de l’Esprit au désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'Et il fut tenté du diable quarante jours, et ne mangea rien du tout durant ces jours-là, mais après qu’ils furent passés, finalement il eut faim.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Et le diable lui dit: si tu es le Fils de Dieu, dis à cette pierre qu’elle devienne du pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Et Jésus lui répondit, en disant: il est écrit: que l’homme ne vivra pas seulement de pain, mais de toute parole de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Alors le diable l’emmena sur une haute montagne, et lui montra en un moment de temps tous les Royaumes du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'Et le diable lui dit: je te donnerai toute cette puissance et leur gloire; car elle m’a été donnée, et je la donne à qui je veux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Si tu veux donc te prosterner devant moi, tout sera tien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Mais Jésus répondant, lui dit: va arrière de moi, satan,; car il est écrit: tu adoreras le Seigneur ton Dieu, et tu le serviras lui seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Il l’amena aussi à Jérusalem, et le mit sur la balustrade du Temple, et lui dit: si tu es le Fils de Dieu, jette-toi d’ici en bas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'Car il est écrit qu’il ordonnera à ses Anges de te conserver!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'Et qu’ils te porteront en leurs mains, de peur que tu ne heurtes ton pied contre quelque pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Mais Jésus répondant, lui dit: il a été dit: tu ne tenteras point le Seigneur ton Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Et quand toute la tentation fut finie, le diable se retira d’avec lui; pour un temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Et Jésus retourna en Galilée par la vertu de l’Esprit, et sa renommée se répandit par tout le pays d’alentour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Car il enseignait dans leurs Synagogues, et était honoré de tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Et il vint à Nazareth, où il avait été nourri, et entra dans la Synagogue le jour du Sabbat, selon sa coutume; puis il se leva pour lire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'Et on lui donna le Livre du Prophète Esaïe, et quand il eut déployé le Livre, il trouva le passage où il est écrit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, 'L’Esprit du Seigneur est sur moi, parce qu’il m’a oint; il m’a envoyé pour évangéliser aux pauvres; pour guérir ceux qui ont le coeur froissé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'Pour publier aux captifs la délivrance, et aux aveugles le recouvrement de la vue; pour mettre en liberté ceux qui sont foulés; et pour publier l’an agréable du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Puis ayant ployé le Livre, et l’ayant rendu au Ministre, il s’assit; et les yeux de tous ceux qui étaient dans la Synagogue étaient arrêtés sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Alors il commença à leur dire: aujourd’hui cette Ecriture est accomplie, vous l’entendant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Et tous lui rendaient témoignage, et s’étonnaient des paroles pleines de grâce qui sortaient de sa bouche; et ils disaient: celui-ci n’est-il pas le Fils de Joseph?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Et il leur dit: assurément vous me direz ce proverbe: médecin, guéris-toi toi-même; et fais ici dans ton pays toutes les choses que nous avons ouï dire que tu as faites à Capernaüm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Mais il leur dit: en vérité je vous dis qu’aucun Prophète n’est bien reçu dans son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Et certes je vous dis qu’il y avait plusieurs veuves en Israël, du temps d’Elie, lorsque le ciel fut fermé trois ans et six mois; de sorte qu’il y eut une grande famine par tout le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'Et toutefois Elie ne fut envoyé vers aucune d’elles, mais seulement vers une femme veuve dans Sarepta de Sidon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'Il y avait aussi plusieurs lépreux en Israël du temps d’Elisée le Prophète; toutefois pas un d’eux ne fut guéri; mais seulement Naaman, qui était Syrien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Et ils furent tous remplis de colère dans la Synagogue, entendant ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'Et s’étant levés, ils le mirent hors de la ville, et le menèrent jusqu’au bord de la montagne sur laquelle leur ville était bâtie, pour le jeter du haut en bas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Mais il passa au milieu d’eux, et s’en alla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Et il descendit à Capernaüm, ville de Galilée, et il les enseignait là les jours de Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'Et ils s’étonnaient de sa doctrine; car sa parole était avec autorité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Or il y avait dans la Synagogue un homme qui était possédé d’un démon impur, lequel s’écria à haute voix,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'En disant: ha! qu’y a-t-il entre nous et toi, Jésus Nazarien? Es-tu venu pour nous détruire? je sais qui tu es, le Saint de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Et Jésus le censura fortement, en lui disant: tais-toi; et sors de cet homme. Et le diable après l’avoir jeté avec impétuosité au milieu de l’assemblée sortit de cet homme, sans lui avoir fait aucun mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Et ils furent tous saisis d’étonnement, et ils parlaient entre eux, et disaient: quelle parole est celle-ci, qu’il commande avec autorité et avec puissance aux esprits immondes, et ils sortent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'Et sa renommée se répandit dans tous les quartiers du pays d’alentour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Et quand Jésus se fut levé de la Synagogue, il entra dans la maison de Simon, et la belle-mère de Simon était détenue d’une grosse fièvre, et on le pria pour elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Et s’étant penché sur elle, il tança la fièvre et la fièvre la quitta; et incontinent elle se leva, et les servit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Et comme le soleil se couchait, tous ceux qui avaient des malades de diverses maladies, les lui amenèrent; et posant les mains sur chacun d’eux, il les guérissait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Les démons aussi sortaient hors de plusieurs, criant, et disant: tu es le Christ, le Fils de Dieu; mais il les censurait fortement, et ne leur permettait pas de dire qu’ils sussent qu’il était le Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Et dès qu’il fut jour il partit, et s’en alla en un lieu désert; et les troupes le cherchaient, et étant venues à lui, elles le retenaient, afin qu’il ne partît point d’avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Mais il leur dit: il faut que j’évangélise aussi aux autres villes le Royaume de Dieu: car je suis envoyé pour cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'Et il prêchait dans les Synagogues de la Galilée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Or il arriva, comme la foule se jetait toute sur lui pour entendre la parole de Dieu, qu’il se tenait sur le bord du lac de Génézareth.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'Et voyant deux nacelles qui étaient au bord du lac, et dont les pêcheurs étaient descendus, et lavaient leurs rets, il monta dans l’une de ces nacelles, qui était à Simon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Et il le pria de la mener un peu loin de terre; puis s’étant assis, il enseignait les troupes de dessus la nacelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Et quand il eut cessé de parler, il dit à Simon: mène en pleine eau, et lâchez vos filets pour pêcher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Et Simon répondant, lui dit: Maître, nous avons travaillé toute la nuit, et nous n’avons rien pris; toutefois à ta parole je lâcherai les filets.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Ce qu’ayant fait, ils enfermèrent une si grande quantité de poissons, que leurs filets se rompaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Et ils firent signe à leurs compagnons qui étaient dans l’autre nacelle, de venir les aider; et étant venus, ils remplirent les deux nacelles, tellement qu’elles s’enfonçaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Et quand Simon-Pierre eut vu cela, il se jeta aux genoux de Jésus, en lui disant: Seigneur, retire-toi de moi; car je suis un homme pécheur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Parce que la frayeur l’avait saisi, lui et tous ceux qui étaient avec lui, à cause de la prise de poissons qu’ils venaient de faire; de même que Jacques et Jean, fils de Zébédée, qui étaient compagnons de Simon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'Alors Jésus dit à Simon: n’aie point de peur; dorénavant tu seras un pêcheur d’hommes vivants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Et quand ils eurent amené les nacelles à terre, ils quittèrent tout, et le suivirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Or il arriva que comme il était dans une des villes de ce pays-là, voici, un homme plein de lèpre voyant Jésus, se jeta en terre sur sa face, et le pria, disant: Seigneur, si tu veux, tu peux me rendre net.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Et Jésus étendit la main, et le toucha, en disant: je le veux, sois net; et incontinent la lèpre le quitta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Et il lui commanda de ne le dire à personne; mais va, lui dit-il, et te montre au Sacrificateur, et offre pour ta purification ce que Moïse a commandé, pour leur servir de témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Et sa renommée se répandait de plus en plus, tellement que de grandes troupes s’assemblaient pour l’entendre, et pour être guéries par lui de leurs maladies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Mais il se tenait retiré dans les déserts, et priait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Or il arriva un jour qu’il enseignait, que des Pharisiens et des Docteurs de la Loi, qui étaient venus de toutes les bourgades de Galilée, et de Judée, et de Jérusalem, étaient là assis, et la puissance du Seigneur était là pour opérer des guérisons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Et voici des hommes qui portaient dans un lit un homme qui était paralytique, et ils cherchaient le moyen de le porter dans la maison, et de le mettre devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Mais ne trouvant point par quel côté ils pourraient l’introduire, à cause de la foule, ils montèrent sur la maison, et ils le descendirent par les tuiles, avec le petit lit, au milieu devant Jésus;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Qui voyant leur foi, dit au paralytique: homme, tes péchés te sont pardonnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Alors les Scribes et les Pharisiens commencèrent à raisonner en eux-mêmes, disant: qui est celui-ci qui prononce des blasphèmes? Qui est-ce qui peut pardonner les péchés, que Dieu seul?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Mais Jésus connaissant leurs pensées, prit la parole, et leur dit: pourquoi raisonnez-vous ainsi en vous-mêmes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Lequel est le plus aisé, ou de dire: tes péchés te sont pardonnés; ou de dire: lève-toi, et marche?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Or afin que vous sachiez que le Fils de l’homme a le pouvoir sur la terre de pardonner les péchés, il dit au paralytique: je te dis, lève-toi, charge ton petit lit, et t’en va en ta maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Et à l’instant le paralytique s’étant levé devant eux, chargea le lit où il était couché, et s’en alla en sa maison, glorifiant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Et ils furent tous saisis d’étonnement, et ils glorifiaient Dieu, et étant remplis de crainte, ils disaient: certainement nous avons vu aujourd’hui des choses qu’on n’eût jamais attendues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Après cela il sortit, et il vit un péager nommé Lévi, assis au lieu du péage, et il lui dit: suis-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Lequel abandonnant tout, se leva, et le suivit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Et Lévi fit un grand festin dans sa maison, où il y avait une grosse assemblée de péagers, et d’autres gens qui étaient avec eux à table.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Et les Scribes de ce lieu-là et les Pharisiens, murmuraient contre ses Disciples, en disant: pourquoi est-ce que vous mangez et que vous buvez avec des péagers et des gens de mauvaise vie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Mais Jésus prenant la parole, leur dit: ceux qui sont en santé n’ont pas besoin de médecin, mais ceux qui se portent mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Je ne suis point venu appeler à la repentance les justes, mais les pécheurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Ils lui dirent aussi: pourquoi est-ce que les disciples de Jean jeûnent souvent, et font des prières; pareillement aussi ceux des Pharisiens; mais les tiens mangent et boivent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Et il leur dit: pouvez-vous faire jeûner les amis de l’Epoux pendant que l’Epoux est avec eux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Mais les jours viendront que l’Epoux leur sera ôté; alors ils jeûneront en ces jours-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Puis il leur dit cette similitude: personne ne met une pièce d’un vêtement neuf à un vieux vêtement; autrement le neuf déchire le vieux, et la pièce du neuf ne se rapporte point au vieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'Pareillement, personne ne met le vin nouveau dans de vieux vaisseaux; autrement le vin nouveau rompra les vaisseaux, et se répandra, et les vaisseaux seront perdus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Mais le vin nouveau doit être mis dans des vaisseaux neufs; et ainsi ils se conservent l’un et l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Et il n’y a personne qui boive du vieux, qui veuille aussitôt du nouveau: car il dit: le vieux est meilleur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Or il arriva le jour de Sabbat second-premier, qu’il passait par des blés, et ses Disciples arrachaient des épis, et les froissant entre leurs mains, ils en mangeaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Et quelques-uns des Pharisiens leur dirent: pourquoi faites-vous une chose qu’il n’est pas permis de faire les jours du Sabbat?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Et Jésus prenant la parole, leur dit: n’avez-vous point lu ce que fit David quand il eut faim, lui, et ceux qui étaient avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Comment il entra dans la Maison de Dieu, et prit les pains de proposition, et en mangea, et en donna aussi à ceux qui étaient avec lui, quoiqu’il ne soit permis qu’aux seuls Sacrificateurs d’en manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Puis il leur dit: Le Fils de l’homme est Seigneur même du Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Il arriva aussi un autre jour de Sabbat, qu’il entra dans la Synagogue, et qu’il enseignait; et il y avait là un homme dont la main droite était sèche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Or les Scribes et les Pharisiens prenaient garde s’il le guérirait le jour du Sabbat, afin qu’ils trouvassent de quoi l’accuser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Mais il connaissait leurs pensées; et il dit à l’homme qui avait la main sèche: lève-toi, et tiens-toi debout au milieu. Et lui se levant se tint debout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Puis Jésus leur dit: je vous demanderai une chose: est-il permis de faire du bien les jours de Sabbat, ou de faire du mal? de sauver une personne, ou de la laisser mourir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Et quand il les eut tous regardés à l’environ, il dit à cet homme: étends ta main; ce qu’il fit; et sa main fut rendue saine comme l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Et ils furent remplis de fureur, et ils s’entretenaient ensemble touchant ce qu’ils pourraient faire à Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'Or il arriva en ces jours-là, qu’il s’en alla sur une montagne pour prier, et qu’il passa toute la nuit à prier Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Et quand le jour fut venu, il appela ses Disciples; et en élut douze, lesquels il nomma aussi Apôtres;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Savoir Simon, qu’il nomma aussi Pierre, et André son frère, Jacques et Jean, Philippe et Barthélemi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Matthieu et Thomas, Jacques fils d’Alphée, et Simon surnommé Zélotes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Jude frère de Jacques, et Judas Iscariot, qui aussi fut traître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Puis descendant avec eux, il s’arrêta dans une plaine avec la troupe de ses disciples, et une grande multitude de peuple de toute la Judée, et de Jérusalem, et de la contrée maritime de Tyr et de Sidon, qui étaient venus pour l’entendre, et pour être guéris de leurs maladies;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'Et ceux aussi qui étaient tourmentés par des esprits immondes; et ils furent guéris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'Et toute la multitude tâchait de le toucher; car il sortait de lui une vertu qui les guérissait tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Alors tournant les yeux vers ses Disciples, il leur disait: vous êtes bienheureux, vous pauvres; car le Royaume de Dieu vous appartient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Vous êtes bienheureux, vous qui maintenant avez faim; car vous serez rassasiés. Vous êtes bienheureux, vous qui pleurez maintenant; car vous serez dans la joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Vous serez bienheureux quand les hommes vous haïront, et vous retrancheront de leur société, et vous diront des outrages, et rejetteront votre nom comme mauvais, à cause du Fils de l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Réjouissez-vous en ce jour-là, et tressaillez de joie; car voici, votre récompense est grande au ciel; et leurs pères en faisaient de même aux Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Mais malheur à vous riches; car vous remportez votre consolation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Malheur à vous qui êtes remplis; car vous aurez faim. Malheur à vous qui riez maintenant; car vous lamenterez et pleurerez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Malheur à vous quand tous les hommes diront du bien de vous; car leurs pères en faisaient de même aux faux prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Mais à vous qui m’entendez, je vous dis: aimez vos ennemis; faites du bien à ceux qui vous haïssent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'Bénissez ceux qui vous maudissent, et priez pour ceux qui vous courent sus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Et à celui qui te frappe sur une joue, présente-lui aussi l’autre; et si quelqu’un t’ôte ton manteau, ne l’empêche point de prendre aussi la tunique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Et à tout homme qui te demande, donne-lui; et à celui qui t’ôte ce qui t’appartient, ne le redemande point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Et comme vous voulez que les hommes vous fassent, faites-leur aussi de même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Mais si vous aimez seulement ceux qui vous aiment, quel gré vous en saura- t-on? car les gens de mauvaise vie aiment aussi ceux qui les aiment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Et si vous ne faites du bien qu’à ceux qui vous ont fait du bien, quel gré vous en saura-t-on? car les gens de mauvaise vie font aussi le même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Et si vous ne prêtez qu’à ceux de qui vous espérez de recevoir, quel gré vous en saura-t-on? car les gens de mauvaise vie prêtent aussi aux gens de mauvaise vie, afin qu’ils en reçoivent la pareille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'C’est pourquoi aimez vos ennemis, et faites du bien, et prêtez sans en rien espérer, et votre récompense sera grande, et vous serez les fils du Souverain, car il est bienfaisant envers les ingrats et les méchants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Soyez donc miséricordieux comme votre Père est miséricordieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Et ne jugez point, et vous ne serez point jugés; ne condamnez point, et vous ne serez point condamnés; quittez, et il vous sera quitté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Donnez, et il vous sera donné; on vous donnera dans le sein bonne mesure, pressée et entassée, et qui s’en ira par-dessus; car de la mesure que vous mesurerez, on vous mesurera réciproquement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Il leur disait aussi cette similitude: est-il possible qu’un aveugle puisse mener un autre aveugle? ne tomberont-ils pas tous deux dans la fosse?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Le disciple n’est point par-dessus son maître; mais tout disciple accompli sera rendu conforme à son maître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Et pourquoi regardes-tu le fétu qui est dans l’oeil de ton frère, et tu n’aperçois pas une poutre dans ton propre oeil?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Ou comment peux-tu dire à ton frère? mon frère permets que j’ôte le fétu qui est dans ton oeil, toi qui ne vois pas une poutre qui est dans ton oeil. Hypocrite, ôte premièrement la poutre de ton oeil, et après cela tu verras comment tu ôteras le fétu qui est dans l’oeil de ton frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Certes un arbre n’est point bon, qui fait de mauvais fruit; ni un arbre n’est point mauvais, qui fait de bon fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Et chaque arbre est connu à son fruit; car aussi les figues ne se cueillent pas des épines, et on ne vendange pas des raisins, d’un buisson.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'L’homme de bien tire de bonnes choses du bon trésor de son coeur; et l’homme méchant tire de mauvaises choses du mauvais trésor de son coeur; car c’est de l’abondance du coeur que la bouche parle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Mais pourquoi m’appelez-vous Seigneur, Seigneur, et vous ne faites pas ce que je dis?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Je vous montrerai à qui est semblable celui qui vient à moi, et qui entendant mes paroles, les met en pratique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Il est semblable à un homme qui bâtissant une maison, a foui et creusé profondément, et a mis le fondement sur la roche? de sorte qu’un débordement d’eaux étant survenu, le fleuve est bien allé donner contre cette maison? mais il ne l’a pu ébranler; parce qu’elle était fondée sur la roche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Mais celui, au contraire, qui ayant entendu mes paroles, ne les a point mises en pratique, est semblable à un homme qui a bâti sa maison sur la terre, sans lui faire de fondement; car le fleuve ayant donné contre cette maison, elle est tombée aussitôt; et la ruine de cette maison a été grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Et quand il eut achevé tout ce discours devant le peuple qui l’écoutait, il entra dans Capernaüm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Or le serviteur d’un certain Centenier, à qui il était fort cher, était malade, et s’en allait mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Et quand le Centenier eut entendu parler de Jésus, il envoya vers lui quelques Anciens des Juifs, pour le prier de venir guérir son serviteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Et étant venus à Jésus, ils le prièrent instamment, en lui disant qu’il était digne qu’on lui accordât cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'Car, disaient-ils, il aime notre nation, et il nous a bâti la Synagogue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Jésus s’en alla donc avec eux; et comme déjà il n’était plus guère loin de la maison, le Centenier envoya ses amis au-devant de lui, pour lui dire: Seigneur ne te fatigue point; car je ne suis pas digne que tu entres sous mon toit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'C’est pourquoi aussi je ne me suis pas cru digne d’aller moi-même vers toi; mais dis seulement une parole, et mon serviteur sera guéri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Car moi-même qui suis un homme constitué sous la puissance d’autrui, j’ai sous moi des gens de guerre; et je dis à l’un: va, et il va; et à un autre: viens, et il vient; et à mon serviteur: fais cela, et il le fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Ce que Jésus ayant entendu, il l’admira; et se tournant, il dit à la troupe qui le suivait: je vous dis, que je n’ai pas trouvé, même en Israël, une si grande foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Et quand ceux qui avaient été envoyés furent de retour à la maison, ils trouvèrent le serviteur qui avait été malade, se portant bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Et le jour d’après il arriva que Jésus allait à une ville nommée Naïn, et plusieurs de ses disciples et une grosse troupe allaient avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Et comme il approchait de la porte de la ville, voici, on portait dehors un mort, fils unique de sa mère, qui était veuve; et une grande troupe de la ville était avec elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Et quand le Seigneur l’eut vue, il fut touché de compassion envers elle; et il lui dit: ne pleure point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Puis s’étant approché, il toucha la bière; et ceux qui portaient le corps s’arrêtèrent, et il dit: Jeune homme, je te dis, lève-toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Et le mort se leva en son séant, et commença à parler; et Jésus le rendit à sa mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Et ils furent tous saisis de crainte, et ils glorifiaient Dieu, disant: certainement un grand Prophète s’est levé parmi nous; et certainement Dieu a visité son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Et le bruit de ce miracle se répandit dans toute la Judée, et dans tout le pays circonvoisin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'Et toutes ces choses ayant été rapportées à Jean par ses Disciples,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'Jean appela deux de ses disciples, et les envoya vers Jésus, pour lui dire: es-tu celui qui devait venir, ou si nous devons en attendre un autre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Et étant venus à lui, ils lui dirent: Jean-Baptiste nous a envoyés auprès de toi, pour te dire: es-tu celui qui devait venir, ou si nous devons en attendre un autre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, '(Or, en cette même heure-là il guérit plusieurs personnes de maladies et de fléaux, et des malins esprits; et il donna la vue à plusieurs aveugles.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Ensuite Jésus leur répondit, et leur dit: allez, et rapportez à Jean ce que vous avez vu et ouï, que les aveugles recouvrent la vue; que les boiteux marchent; que les lépreux sont nettoyés; que les sourds entendent; que les morts ressuscitent; et que l’Evangile est prêché aux pauvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'Mais bienheureux est quiconque n’aura point été scandalisé à cause de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Puis quand les messagers de Jean furent partis, il se mit à dire de Jean aux troupes: qu’êtes-vous allés voir au désert? Un roseau agité du vent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Mais qu’êtes-vous allés voir? Un homme vêtu de précieux vêtements? Voici, c’est dans les palais des Rois que se trouvent ceux qui sont magnifiquement vêtus, et qui vivent dans les délices.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Mais qu’êtes-vous donc allés voir? Un Prophète? Oui, vous dis-je, et plus qu’un Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'C’est de lui qu’il est écrit: voici, j’envoie mon Messager devant ta face, et il préparera ta voie devant toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Car je vous dis qu’entre ceux qui sont nés de femme, il n’y a aucun Prophète plus grand que Jean Baptiste; et toutefois le moindre dans le Royaume de Dieu est plus grand que lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Et tout le peuple qui entendait cela, et les péagers qui avaient été baptisés du Baptême de Jean justifièrent Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Mais les Pharisiens, et les Docteurs de la Loi, qui n’avaient point été baptisés par lui, rendirent le dessein de Dieu inutile à leur égard.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'Alors le Seigneur dit: à qui donc comparerai-je les hommes de cette génération; et à quoi ressemblent-ils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Ils sont semblables aux enfants qui sont assis au marché, et qui crient les uns aux autres, et disent: nous avons joué de la flûte, et vous n’avez point dansé; nous vous avons chanté des airs lugubres, et vous n’avez point pleuré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Car Jean Baptiste est venu ne mangeant point de pain, et ne buvant point de vin; et vous dites: il a un Démon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Le Fils de l’homme est venu mangeant et buvant; et vous dites: voici un mangeur et un buveur, un ami des péagers et des gens de mauvaise vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Mais la sagesse a été justifiée par tous ses enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Or un des Pharisiens le pria de manger chez lui; et il entra dans la maison de ce Pharisien, et se mit à table.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Et voici, il y avait dans la ville une femme de mauvaise vie, qui ayant su que Jésus était à table dans la maison du Pharisien, apporta un vase d’albâtre plein d’une huile odoriférante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'Et se tenant derrière à ses pieds, et pleurant, elle se mit à les arroser de ses larmes, et elle les essuyait avec ses propres cheveux, et lui baisait les pieds, et les oignait de cette huile odoriférante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Mais le Pharisien qui l’avait convié, voyant cela, dit en soi-même: si celui-ci était Prophète, certes il saurait qui et quelle est cette femme qui le touche: car c’est une femme de mauvaise vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Et Jésus prenant la parole lui dit: Simon, j’ai quelque chose à te dire; et il dit: Maître, dis-la.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Un créancier avait deux débiteurs: l’un lui devait cinq cents deniers, et l’autre cinquante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Et comme ils n’avaient pas de quoi payer, il quitta la dette à l’un et à l’autre; dis donc, lequel d’eux l’aimera le plus?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Et Simon répondant lui dit: j’estime que c’est celui à qui il a quitté davantage. Et Jésus lui dit: tu as droitement jugé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Alors se tournant vers la femme, il dit à Simon: vois-tu cette femme? je suis entré dans ta maison, et tu ne m’as point donné d’eau pour laver mes pieds; mais elle a arrosé mes pieds de ses larmes, et les a essuyés avec ses propres cheveux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Tu ne m’as point donné un baiser, mais elle, depuis que je suis entré, n’a cessé de baiser mes pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Tu n’as point oint ma tête d’huile; mais elle a oint mes pieds d’une huile odoriférante:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'C’est pourquoi je te dis, que ses péchés, qui sont grands, lui sont pardonnés; car elle a beaucoup aimé; or celui à qui il est moins pardonné, aime moins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Puis il dit à la femme: tes péchés te sont pardonnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Et ceux qui étaient avec lui à table, se mirent à dire entre eux: qui est celui-ci qui même pardonne les péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Mais il dit à la femme: ta foi t’a sauvée; va-t’en en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Or il arriva après cela qu’il allait de ville en ville, et de bourgade en bourgade, prêchant et annonçant le royaume de Dieu; et les douze Disciples étaient avec lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'Et quelques femmes aussi qu’il avait délivrées des malins esprits, et des maladies, savoir Marie, qu’on appelait Magdelaine, de laquelle étaient sortis sept démons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'Et Jeanne femme de Chuzas, lequel avait le maniement des affaires d’Hérode; et Susanne, et plusieurs autres qui l’assistaient de leurs biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Et comme une grande troupe s’assemblait, et que plusieurs allaient à lui de toutes les villes, il leur dit cette parabole:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'Un semeur sortit pour semer sa semence; et en semant, une partie de la semence tomba le long du chemin, et fut foulée aux pieds, et les oiseaux du ciel la mangèrent toute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Et une autre partie tomba dans un lieu pierreux; et quand elle fut levée, elle se sécha, parce qu’elle n’avait point d’humidité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Et une autre partie tomba entre des épines; et les épines se levèrent ensemble avec elle, et l’étouffèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Et une autre partie tomba dans une bonne terre; et quand elle fut levée, elle rendit du fruit cent fois autant. En disant ces choses, il criait: qui a des oreilles pour ouïr, qu’il entende.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Et ses Disciples l’interrogèrent, pour savoir ce que signifiait cette parabole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Et il répondit: il vous est donné de connaître les secrets du Royaume de Dieu, mais il n’en est parlé aux autres qu’en similitudes, afin qu’en voyant ils ne voient point, et qu’en entendant ils ne comprennent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Voici donc ce que signifie cette parabole; la semence, c’est la parole de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Et ceux qui ont reçu la semence le long du chemin, ce sont ceux qui écoutent la parole; mais ensuite vient le démon, qui ôte de leur coeur la parole, de peur qu’en croyant ils ne soient sauvés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Et ceux qui ont reçu la semence dans un lieu pierreux, ce sont ceux qui ayant ouï la parole, la reçoivent avec joie; mais ils n’ont point de racine; ils croient pour un temps, mais au temps de la tentation ils se retirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Et ce qui est tombé entre des épines, ce sont ceux qui ayant ouï la parole, et s’en étant allés, sont étouffés par les soucis, par les richesses, et par les voluptés de cette vie, et ils ne rapportent point de fruit à maturité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Mais ce qui est tombé dans une bonne terre, ce sont ceux qui ayant ouï la parole, la retiennent dans un coeur honnête et bon, et rapportent du fruit avec patience.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Nul, après avoir allumé la lampe, ne la couvre d’un vaisseau, ni ne la met sous un lit, mais il la met sur un chandelier, afin que ceux, qui entrent voient la lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Car il n’y a point de secret qui ne soit manifesté; ni de chose cachée qui ne se connaisse, et qui ne vienne en lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Regardez donc comment vous écoutez; car à celui qui a il sera donné; mais à celui qui n’a rien, cela même qu’il croit avoir, lui sera ôté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Alors sa mère et ses frères vinrent vers lui, mais ils ne pouvaient l’aborder à cause de la foule.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'Et il lui fut rapporté, en disant: ta mère et tes frères sont là dehors, qui désirent de te voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Mais il répondit, et leur dit: ma mère et mes frères sont ceux qui écoutent la parole de Dieu, et qui la mettent en pratique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Or il arriva qu’un jour il monta dans une nacelle avec ses Disciples, et il leur dit: passons à l’autre côté du lac; et ils partirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Et comme ils voguaient, il s’endormit, et un vent impétueux s’étant levé sur le lac, la nacelle se remplissait d’eau, et ils étaient en grand péril.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Alors ils vinrent à lui, et l’éveillèrent, disant: Maître! Maître! nous périssons. Mais lui s’étant levé, parla en Maître au vent et aux flots, et ils s’apaisèrent; et le calme revint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Alors il leur dit: où est votre foi? et eux saisis de crainte et d’admiration, disaient entre eux: mais qui est celui-ci, qu’il commande même aux vents et à l’eau, et ils lui obéissent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'Puis ils naviguèrent vers le pays des Gadaréniens, qui est vis-à-vis de la Galilée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Et quand il fut descendu à terre, il vint à sa rencontre un homme de cette ville-là, qui depuis longtemps était possédé des démons, et n’était point couvert d’habits, et ne demeurait point dans les maisons, mais dans les sépulcres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Et ayant aperçu Jésus, il s’écria, et se prosterna devant lui, disant à haute voix: qu’y a-t-il entre moi et toi, Jésus Fils du Dieu Souverain? je te prie, ne me tourmente point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Car Jésus commandait à l’esprit immonde de sortir hors de cet homme; parce qu’il l’avait tenu enserré depuis longtemps, et quoique cet homme fût lié de chaînes et gardé dans les fers il brisait ses liens, et était emporté par le démon dans les déserts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Et Jésus lui demanda: comment as-tu nom? Et il dit: Légion; car plusieurs démons étaient entrés en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Mais ils priaient Jésus qu’il ne leur commandât point d’aller dans l’abîme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Or il y avait là un grand troupeau de pourceaux qui paissaient sur la montagne, et ils le priaient de leur permettre d’entrer dans ces pourceaux; et il le leur permit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Et les démons sortant de cet homme entrèrent dans les pourceaux; et le troupeau se jeta du haut en bas dans le lac; et fut étouffé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Et quand ceux qui le gardaient eurent vu ce qui était arrivé, ils s’enfuirent, et allèrent le raconter dans la ville et par les champs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Et les gens sortirent pour voir ce qui était arrivé, et vinrent à Jésus, et ils trouvèrent l’homme duquel les démons étaient sortis, assis aux pieds de Jésus, vêtu, et de sens rassis et posé; et ils eurent peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Et ceux qui avaient vu tout cela, leur racontèrent comment le démoniaque avait été délivré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Alors toute cette multitude venue de divers endroits voisins des Gadaréniens le prièrent de se retirer de chez eux; car ils étaient saisis d’une grande crainte; il remonta donc dans la nacelle, et s’en retourna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Et l’homme duquel les démons étaient sortis, le priait qu’il fût avec lui; mais Jésus le renvoya, en lui disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, 'Retourne-t-en en ta maison, et raconte quelles grandes choses Dieu t’a faites. Il s’en alla donc publiant par toute la ville toutes les choses que Jésus lui avait faites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Et quand Jésus fut de retour, la multitude le reçut avec joie; car tous l’attendaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Et voici, un homme appelé Jaïrus, qui était le Principal de la Synagogue, vint, et se jetant aux pieds de Jésus, le pria de venir en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'Car il avait une fille unique, âgée d’environ douze ans, qui se mourait; et comme il s’en allait, les troupes le pressaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'Et une femme qui avait une perte de sang depuis douze ans, et qui avait dépensé tout son bien en médecins, sans qu’elle eût pu être guérie par aucun;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'S’approchant de lui par derrière, toucha le bord de son vêtement; et à l’instant la perte de sang s’arrêta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Et Jésus dit: qui est-ce qui m’a touché? et comme tous niaient que ce fût eux, Pierre lui dit, et ceux aussi qui étaient avec lui: Maître, les troupes te pressent et te foulent, et tu dis: qui est-ce qui m’a touché?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Mais Jésus dit: quelqu’un m’a touché; car j’ai connu qu’une vertu est sortie de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Alors la femme voyant que cela ne lui avait point été caché, vint toute tremblante, et se jetant à ses pieds, lui déclara devant tout le peuple pour quelle raison elle l’avait touché, et comment elle avait été guérie dans le moment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Et il lui dit: ma fille rassure-toi, ta foi t’a guérie; va-t-en en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Et comme il parlait encore, quelqu’un vint de chez le Principal de la Synagogue, qui lui dit: ta fille est morte, ne fatigue point le Maître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Mais Jésus l’ayant entendu, répondit au père de la fille, disant: ne crains point; crois seulement, et elle sera guérie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Et quand il fut arrivé à la maison, il ne laissa entrer personne, que Pierre, et Jacques, et Jean, avec le père et la mère de la fille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Or ils la pleuraient tous, et de douleur ils se frappaient la poitrine; mais il leur dit: ne pleurez point, elle n’est pas morte, mais elle dort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'Et ils se riaient de lui, sachant bien qu’elle était morte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Mais lui les ayant tous mis dehors, et ayant pris la main de la fille, cria, en disant: Fille, lève toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Et son esprit retourna, et elle se leva d’abord; et il commanda qu’on lui donnât à manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Et le père et la mère de la fille en furent étonnés, mais il leur commanda de ne dire à personne ce qui avait été fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Puis Jésus ayant assemblé ses douze Disciples, leur donna puissance et autorité sur tous les démons, et le pouvoir de guérir les malades.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'Et il les envoya prêcher le Royaume de Dieu, et guérir les malades,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Et leur dit: ne portez rien pour le voyage, ni bâtons, ni sac, ni pain, ni argent; et n’ayez point chacun deux robes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Et en quelque maison que vous entriez, demeurez-y jusqu’à ce que vous partiez de là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Et partout où l’on ne vous recevra point, en partant de cette ville-là secouez la poudre de vos pieds, en témoignage contre eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Eux donc étant partis allaient de bourgade en bourgade, évangélisant, et guérissant partout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Or Hérode le Tétrarque ouït parler de toutes les choses que Jésus faisait; et il ne savait que croire de ce que quelques-uns disaient que Jean était ressuscité des morts;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'Et quelques-uns, qu’Elie était apparu; et d’autres, que quelqu’un des anciens Prophètes était ressuscité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Et Hérode dit: j’ai fait décapiter Jean; qui est donc celui-ci de qui j’entends dire de telles choses? Et il cherchait à le voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Puis les Apôtres étant de retour, lui racontèrent toutes les choses qu’ils avaient faites. Et Jésus les emmena avec lui, et se retira dans un lieu désert, près de la ville appelée Bethsaïda.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Ce que les troupes ayant su, elles le suivirent, et il les reçut, et leur parlait du Royaume de Dieu, et guérissait ceux qui avaient besoin d’être guéris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Or le jour ayant commencé à baisser, les douze Disciples vinrent à lui, et lui dirent: donne congé à cette multitude, afin qu’ils s’en aillent aux bourgades et aux villages des environs, pour s’y retirer, et trouver à manger; car nous sommes ici dans un pays désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Mais il leur dit: donnez-leur vous-mêmes à manger. Et ils dirent: nous n’avons pas plus de cinq pains et de deux poissons; à moins que nous n’allions acheter des vivres pour tout ce peuple;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Car ils étaient environ cinq mille hommes. Et il dit à ses Disciples: faites-les arranger par troupes, de cinquante chacune.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'Ils le firent ainsi, et les firent tous arranger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Puis il prit les cinq pains et les deux poissons, et regardant vers le ciel, il les bénit, et les rompit, et il les distribua à ses Disciples, afin qu’ils les missent devant cette multitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Et ils en mangèrent tous, et furent rassasiés, et on remporta douze corbeilles pleines des pièces de pain qu’il y avait eu de reste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'Or il arriva que comme il était dans un lieu retiré pour prier, et que les Disciples étaient avec lui, il les interrogea, disant: qui disent les troupes que je suis?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Ils lui répondirent: Les uns disent que tu es Jean Baptiste; et les autres, Elie; et les autres, que quelqu’un des anciens Prophètes est ressuscité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Il leur dit alors: et vous, qui dites-vous que je suis? Et Pierre répondant lui dit: tu es le Christ de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Mais usant de menaces il leur commanda de ne le dire à personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'Et il leur dit: il faut que le Fils de l’homme souffre beaucoup, et qu’il soit rejeté des Anciens, et des principaux Sacrificateurs, et des Scribes, et qu’il soit mis à mort, et qu’il ressuscite le troisième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Puis il disait à tous: si quelqu’un veut venir après moi, qu’il renonce à soi-même, et qu’il charge de jour en jour sa croix, et me suive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Car quiconque voudra sauver sa vie, la perdra; mais quiconque perdra sa vie pour l’amour de moi, la sauvera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Et que sert-il à un homme de gagner tout le monde, s’il se détruit lui-même, et se perd lui-même?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Car quiconque aura eu honte de moi et de mes paroles; le Fils de l’homme aura honte de lui, quand il viendra en sa gloire, et dans celle du Père, et des saints Anges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Et je vous dis, en vérité, qu’entre ceux qui sont ici présents, il y en a qui ne mourront point jusqu’à ce qu’ils aient vu le règne de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Or il arriva environ huit jours après ces paroles, qu’il prit avec lui Pierre, et Jean, et Jacques, et qu’il monta sur une montagne pour prier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Et comme il priait, la forme de son visage devint tout autre, et son vêtement devint blanc en sorte qu’il était resplendissant comme un éclair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'Et voici, deux personnages, savoir Moïse et Elie, parlaient avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'Et ils apparurent environnés de gloire, et ils parlaient de sa mort qu’il devait souffrir à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Or Pierre et ceux qui étaient avec lui étaient accablés de sommeil; et quand ils furent réveillés, ils virent sa gloire, et les deux personnages qui étaient avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Et il arriva comme ces personnages se séparaient de lui, que Pierre dit à Jésus: Maître, il est bon que nous soyons ici, faisons-y donc trois tentes, une pour toi, une pour Moïse, et une pour Elie; ne sachant ce qu’il disait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Et comme il disait ces choses, une nuée vint qui les couvrit de son ombre; et comme ils entraient dans la nuée, ils eurent peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Et une voix vint de la nuée, disant: celui-ci est mon Fils bien-aimé; écoutez-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Et comme la voix se prononçait, Jésus se trouva seul. Et ils se turent tous, et ils ne rapportèrent en ces jours-là à personne rien de ce qu’ils avaient vu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Or il arriva le jour suivant, qu’eux étant descendus de la montagne, une grande troupe vint à sa rencontre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'Et voici, un homme de la troupe s’écria, disant: Maître, Je te prie, jette les yeux sur mon fils, car je n’ai que celui-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'Et voici, un esprit le saisit, qui aussitôt le fait crier, et l’agite avec violence en le faisant écumer, et à peine il se retire de lui, après l’avoir comme brisé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'Or j’ai prié tes Disciples de le chasser dehors, mais ils n’ont pu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Et Jésus répondant dit: ô génération incrédule et perverse, jusques à quand serai-je avec vous, et vous supporterai-je? Amène ici ton fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Et comme il approchait seulement, le démon l’agita violemment comme s’il l’eût voulu déchirer; mais Jésus censura fortement l’esprit immonde, et guérit l’enfant, et le rendit à son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Et tous furent étonnés de la magnifique vertu de Dieu. Et comme tous s’étonnaient de tout ce qu’il faisait, il dit à ses Disciples:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Vous, écoutez bien ces discours: car il arrivera que le Fils de l’homme sera livré entre les mains des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Mais ils ne comprirent point cette parole, et elle leur était tellement obscure, qu’ils ne la comprenaient pas; et ils craignaient de l’interroger touchant cette parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Puis ils entrèrent en dispute, pour savoir lequel d’entre eux était le plus grand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Mais Jésus voyant la pensée de leur coeur, prit un petit enfant, et le mit auprès de lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'Puis il leur dit: quiconque recevra ce petit enfant en mon Nom, il me reçoit; et quiconque me recevra, il reçoit celui qui m’a envoyé. Car celui qui est le plus petit d’entre vous tous, c’est celui qui sera grand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Et Jean prenant la parole, dit: Maître, nous avons vu quelqu’un qui chassait les démons en ton Nom, et nous l’en avons empêché parce qu’il ne te suit point avec nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Mais Jésus lui dit: ne l’en empêchez point; car celui qui n’est pas contre nous, est pour nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Or il arriva quand les jours de son élévation s’accomplissaient, qu’il dressa sa face, tout résolu d’aller à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'Et il envoya devant lui des messagers, qui étant partis entrèrent dans une bourgade des Samaritains, pour lui préparer un logis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Mais les Samaritains ne le reçurent point, parce qu’il paraissait qu’il allait à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Et quand Jacques et Jean, ses Disciples, virent cela, ils dirent: Seigneur! veux-tu que nous disions, comme fit Elie, que le feu descende du ciel, et les consume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Mais Jésus se tournant les censura fortement, en leur disant: Vous ne savez de quel esprit vous êtes animés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Car le Fils de l’homme n’est pas venu pour faire périr les âmes des hommes, mais pour les sauver. Ainsi ils s’en allèrent à une autre bourgade.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Et il arriva comme ils allaient par le chemin, qu’un certain homme lui dit: je te suivrai, Seigneur, partout où tu iras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Mais Jésus lui répondit: les renards ont des tanières, et les oiseaux du ciel ont des nids, mais le Fils de l’homme n’a pas où reposer sa tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Puis il dit à un autre: suis-moi; et celui-ci lui répondit: permets-moi premièrement d’aller ensevelir mon père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Et Jésus lui dit: laisse les morts ensevelir leurs morts; mais toi, va, et annonce le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Un autre aussi lui dit: Seigneur, je te suivrai; mais permets-moi de prendre premièrement congé de ceux qui sont dans ma maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Mais Jésus lui répondit: nul qui met la main à la charrue, et qui regarde en arrière, n’est bien disposé pour le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Or après ces choses le Seigneur en ordonna aussi soixante-dix autres, et les envoya deux à deux devant lui, dans toutes les villes et dans tous les lieux où il devait aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Et il leur disait: La moisson est grande, mais il y a peu d’ouvriers; priez donc le Seigneur de la moisson, qu’il pousse des ouvriers dans sa moisson.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Allez, voici, je vous envoie comme des agneaux au milieu des loups.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Ne portez ni bourse, ni sac, ni souliers, et ne saluez personne dans le chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Et en quelque maison que vous entriez, dites premièrement: paix soit à cette maison!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Que s’il y a là quelqu’un qui soit digne de paix, votre paix reposera sur lui; sinon elle retournera à vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Et demeurez dans cette maison, mangeant et buvant de ce qui sera mis devant vous; car l’ouvrier est digne de son salaire. Ne passez point de maison en maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Et en quelque ville que vous entriez, et qu’on vous reçoive, mangez de ce qui sera mis devant vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'Et guérissez les malades qui y seront, et dites-leur: Le Royaume de Dieu est approché de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Mais en quelque ville que vous entriez, si on ne vous reçoit point, sortez dans ses rues, et dites:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'Nous secouons contre vous-mêmes la poussière de votre ville qui s’est attachée à nous; toutefois sachez que le Royaume de Dieu est approché de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Et je vous dis, qu’en cette journée-là ceux de Sodome seront traités moins rigoureusement que cette ville-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Malheur à toi Chorazin, malheur à toi Bethsaïda! car si les miracles qui ont été faits au milieu de vous avaient été faits dans Tyr et dans Sidon, il y a longtemps qu’elles se seraient repenties, couvertes d’un sac, et assises sur la cendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'C’est pourquoi Tyr et Sidon seront traitées moins rigoureusement que vous au jour du jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Et toi Capernaüm, qui as été élevée jusqu’au ciel, tu seras abaissée jusque dans l’enfer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Celui qui vous écoute, m’écoute; et celui qui vous rejette, me rejette; or celui qui me rejette, rejette celui qui m a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Or les soixante-dix s’en revinrent avec joie, en disant: Seigneur, les démons mêmes nous sont assujettis en ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Et il leur dit: je contemplais satan tombant du ciel comme un éclair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Voici, je vous donne la puissance de marcher sur les serpents et sur les scorpions, et sur toute la force de l’ennemi; et rien ne vous nuira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Toutefois ne vous réjouissez pas de ce que les esprits vous sont assujettis, mais plutôt réjouissez-vous de ce que vos noms sont écrits dans les cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'En ce même instant Jésus se réjouit en esprit, et dit: je te loue, ô Père! Seigneur du ciel et de la terre, de ce que tu as caché ces choses aux sages et aux intelligents, et que tu les as révélées aux petits enfants; il est ainsi, ô Père! parce que telle a été ta bonne volonté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Toutes choses m’ont été données en main par mon Père; et personne ne connaît qui est le Fils, sinon le Père; ni qui est le Père, sinon le Fils; et celui à qui le Fils l’aura voulu révéler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Puis se tournant vers ses Disciples, il leur dit en particulier: bienheureux sont les yeux qui voient ce que vous voyez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Car je vous dis, que plusieurs Prophètes et plusieurs Rois ont désiré de voir les choses que vous voyez, et ils ne les ont point vues, et d’ouïr les choses que vous entendez, et ils ne les ont point entendues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Alors voici, un Docteur de la Loi s’étant levé pour l’éprouver lui dit: Maître, que dois-je faire pour avoir la vie éternelle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Et il lui dit: qu’est-il écrit dans la Loi? comment lis-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Et il répondit, et dit: tu aimeras le Seigneur ton Dieu de tout ton coeur, et de toute ton âme, et de toute ta force, et de toute ta pensée; et ton prochain comme toi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Et Jésus lui dit: tu as bien répondu; fais cela, et tu vivras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Mais lui se voulant justifier, dit à Jésus: et qui est mon prochain?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Et Jésus répondant, lui dit: un homme descendait de Jérusalem à Jéricho, et il tomba entre les mains des voleurs, qui le dépouillèrent, et qui après l’avoir blessé de plusieurs coups, s’en allèrent, le laissant à demi-mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Or par rencontre un Sacrificateur descendait par le même chemin, et quand il le vit, il passa de l’autre côté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Un Lévite aussi étant arrivé en cet endroit-là, et voyant cet homme, passa tout de même de l’autre côté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Mais un Samaritain faisant son chemin vint à lui, et le voyant il fut touché de compassion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'Et s’approchant lui banda ses plaies, et y versa de l’huile et du vin; puis le mit sur sa propre monture, et le mena dans l’hôtellerie, et eut soin de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Et le lendemain en partant il tira de sa bourse deux deniers, et les donna à l’hôte, en lui disant: aie soin de lui; et tout ce que tu dépenseras de plus, je te le rendrai à mon retour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Lequel donc de ces trois te semble-t-il avoir été le prochain de celui qui était tombé entre les mains des voleurs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Il répondit: c’est celui qui a usé de miséricorde envers lui. Jésus donc lui dit: va, et toi aussi fais de même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Et il arriva comme ils s’en allaient, qu’il entra dans une bourgade; et une femme nommée Marthe le reçut dans sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Et elle avait une soeur nommée Marie, qui se tenant assise aux pieds de Jésus, écoutait sa parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Mais Marthe était distraite par divers soins; et étant venue à Jésus, elle dit: Seigneur, ne te soucies-tu point que ma soeur me laisse servir toute seule, dis-lui donc qu’elle m’aide de son côté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Et Jésus répondant, lui dit: Marthe, Marthe, tu t’inquiètes et tu t’agites pour beaucoup de choses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'Mais une chose est nécessaire; et Marie a choisi la bonne part, qui ne lui sera point ôtée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Et il arriva, comme il était en prière en un certain lieu, qu’après qu’il eut cessé de prier, quelqu’un de ses Disciples lui dit: Seigneur, enseigne-nous à prier, ainsi que Jean a enseigné ses Disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Et il leur dit: quand vous prierez, dites: Notre Père qui es aux cieux, ton Nom soit sanctifié. Ton Règne vienne. Ta volonté soit faite en la terre comme au ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Donne-nous chaque jour notre pain quotidien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'Et pardonne-nous nos péchés; car nous quittons aussi les dettes à tous ceux qui nous doivent. Et ne nous induis point en tentation, mais délivre-nous du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Puis il leur dit: qui sera celui d’entre vous, lequel ayant un ami qui aille à lui sur le minuit, et lui dise: Mon ami, prête moi trois pains;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'Car un de mes amis m’est survenu en passant, et je n’ai rien pour lui présenter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'Et que celui qui est dedans réponde et dise: ne m’importune point; car ma porte est déjà fermée, et mes petits enfants sont avec moi au lit; je ne puis me lever pour t’en donner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Je vous dis, qu’encore qu’il ne se lève point pour lui en donner à cause qu’il est son ami, il se lèvera pourtant à cause de son importunité, et lui en donnera autant qu’il en aura besoin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Ainsi je vous dis: demandez, et il vous sera donné; cherchez, et vous trouverez; heurtez, et il vous sera ouvert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Car quiconque demande, reçoit; et quiconque cherche, trouve; et il sera ouvert à celui qui heurte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Que si un enfant demande du pain à quelqu’un d’entre vous qui soit son père, lui donnera-t-il une pierre? Ou, s’il demande du poisson, lui donnera-t-il, au lieu du poisson, un serpent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Ou, s’il demande un oeuf, lui donnera-t-il un scorpion?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Si donc vous qui êtes méchants, savez bien donner à vos enfants de bonnes choses, combien plus votre Père céleste donnera-t-il le Saint-Esprit à ceux qui le lui demandent?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Alors il chassa un démon qui était muet; et il arriva que quand le démon fut sorti, le muet parla; et les troupes s’en étonnèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Et quelques-uns d’entre eux dirent: c’est par Béelzebul, prince des démons, qu’il chasse les démons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Mais les autres pour l’éprouver, lui demandaient un miracle du ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Mais lui connaissant leurs pensées, leur dit: tout Royaume divisé contre soi-même sera réduit en désert; et toute maison divisée contre elle-même tombe en ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Que si satan est aussi divisé contre lui-même, comment subsistera son règne? Car vous dites que je chasse les démons par Béelzebul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Que si je chasse les démons par Béelzebul, vos fils par qui les chassent-ils? c’est pourquoi ils seront eux-mêmes vos juges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Mais si je chasse les démons par le doigt de Dieu, certes le Règne de Dieu est parvenu à vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Quand un homme fort et bien armé garde son hôtel, les choses qu’il a sont en sûreté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'Mais s’il en survient un autre plus fort que lui, qui le surmonte, il lui ôte toutes ses armes auxquelles il se confiait, et fait le partage de ses dépouilles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Celui qui n’est point avec moi, est contre moi; et celui qui n’assemble point avec moi, il disperse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Quand l’esprit immonde est sorti d’un homme, il va par des lieux secs, cherchant du repos; et n’en trouvant point, il dit: je retournerai dans ma maison, d’où je suis sorti.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'Et y étant venu, il la trouve balayée et parée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Alors il s’en va, et prend avec soi sept autres esprits plus méchants que lui, et ils entrent et demeurent là; de sorte que la dernière condition de cet homme-là est pire que la première.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Or il arriva comme il disait ces choses, qu’une femme d’entre les troupes éleva sa voix, et lui dit: bienheureux est le ventre qui t’a porté, et les mamelles que tu as tétées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Et il dit: mais plutôt bienheureux sont ceux qui écoutent la parole de Dieu, et qui la gardent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Et comme les troupes s’amassaient, il se mit à dire: cette génération est méchante; elle demande un miracle, mais il ne lui sera point accordé d’autre miracle, que le miracle de Jonas le Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Car comme Jonas fut un signe à ceux de Ninive, ainsi le Fils de l’homme en sera un à cette génération.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'La Reine du Midi se lèvera au jour du jugement contre les hommes de cette génération, et les condamnera; parce qu’elle vint du bout de la terre pour entendre la sagesse de Salomon; et voici, il y a ici plus que Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Les gens de Ninive se lèveront au jour du jugement contre cette génération, et la condamneront; parce qu’ils se sont repentis à la prédication de Jonas; et voici, il y a ici plus que Jonas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Or nul qui allume une lampe, ne la met dans un lieu caché, ou sous un boisseau, mais sur un chandelier, afin que ceux qui entrent, voient la lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'La lumière du corps c’est l’oeil: si donc ton oeil est net, tout ton corps aussi sera éclairé; mais s’il est mauvais, ton corps aussi sera ténébreux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Regarde donc que la lumière qui est en toi ne soit des ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Si donc ton corps est éclairé, n’ayant aucune partie ténébreuse, il sera éclairé partout, comme quand la lampe t’éclaire par sa lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Et comme il parlait, un Pharisien le pria de dîner chez lui; et Jésus y entra, et se mit à table.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Mais le Pharisien s’étonna de voir qu’il ne s’était point premièrement lavé avant le dîner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Mais le Seigneur lui dit: vous autres Pharisiens vous nettoyez le dehors de la coupe et du plat; mais le dedans de vous est plein de rapine et de méchanceté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Insensés, celui qui a fait le dehors, n’a-t-il pas fait aussi le dedans?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Mais plutôt donnez l’aumône de ce que vous avez, et voici, toutes choses vous seront nettes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Mais malheur à vous, Pharisiens; car vous payez la dîme de la menthe, et de la rue, et de toute sorte d’herbage, et vous négligez le jugement et l’amour de Dieu: il fallait faire ces choses-ci, et ne laisser point celles-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Malheur à vous, Pharisiens, qui aimez les premières places dans les Synagogues, et les salutations dans les marchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Malheur à vous, Scribes et Pharisiens hypocrites; car vous êtes comme les sépulcres qui ne paraissent point, en sorte que les hommes qui passent par- dessus n’en savent rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Alors quelqu’un des Docteurs de la Loi prit la parole, et lui dit: Maître, en disant ces choses, tu nous dis aussi des injures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Et Jésus lui dit: malheur aussi à vous, Docteurs de la Loi, car vous chargez les hommes de fardeaux insupportables, mais vous-mêmes ne touchez point ces fardeaux de l’un de vos doigts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Malheur à vous; car vous bâtissez les sépulcres des Prophètes, que vos pères ont tués.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Certes, vous témoignez que vous consentez aux actions de vos pères; car ils les ont tués, et vous bâtissez leurs sépulcres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'C’est pourquoi aussi la sagesse de Dieu a dit: je leur enverrai des Prophètes et des Apôtres, et ils en tueront, et en chasseront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'Afin que le sang de tous les Prophètes qui a été répandu dès la fondation du monde, soit redemandé à cette nation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'Depuis le sang d’Abel, jusqu’au sang de Zacharie, qui fut tué entre l’autel et le Temple; oui, je vous dis qu’il sera redemandé à cette nation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Malheur à vous, Docteurs de la Loi; parce qu’ayant enlevé la clef de la science, vous-mêmes n’êtes point entrés, et vous avez empêché ceux qui entraient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Et comme il leur disait ces choses, les Scribes et les Pharisiens se mirent à le presser encore plus fortement, et à lui tirer de la bouche plusieurs choses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'Lui dressant des pièges, et tâchant de recueillir captieusement quelque chose de sa bouche, pour avoir de quoi l’accuser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Cependant les troupes s’étant assemblées par milliers, en sorte qu’ils se foulaient les uns les autres, il se mit à dire à ses Disciples: donnez-vous garde surtout du levain des Pharisiens qui est l’hypocrisie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Car il n’y a rien de caché, qui ne doive être révélé; ni rien de si secret, qui ne doive être connu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'C’est pourquoi les choses que vous avez dites dans les ténèbres, seront ouïes dans la lumière; et ce dont vous avez parlé à l’oreille dans les chambres, sera prêché sur les maisons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Et je vous dis à vous mes amis: ne craignez point ceux qui tuent le corps, et qui après cela ne sauraient rien faire davantage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Mais je vous montrerai qui vous devez craindre; craignez celui qui a la puissance, après qu’il a tué, d’envoyer dans la géhenne; oui, vous dis-je, craignez celui-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Ne donne-t-on pas cinq petits passereaux pour deux pites? Et cependant un seul d’eux n’est point oublié devant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Tous les cheveux même de votre tête sont comptés; ne craignez donc point; vous valez mieux que beaucoup de passereaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Or je vous dis, que quiconque me confessera devant les hommes, le Fils de l’homme le confessera aussi devant les Anges de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'Mais quiconque me reniera devant les hommes, il sera renié devant les Anges de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Et quiconque parlera contre le Fils de l’homme, il lui sera pardonné; mais à celui qui aura blasphémé contre le Saint-Esprit, il ne lui sera point pardonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Et quand ils vous mèneront aux Synagogues, et aux Magistrats, et aux Puissances, ne soyez point en peine comment, ou quelle chose vous répondrez, ou de ce que vous aurez à dire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'Car le Saint-Esprit vous enseignera dans ce même instant ce qu’il faudra dire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Et quelqu’un de la troupe lui dit: Maître, dis à mon frère qu’il partage avec moi l’héritage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Mais il lui répondit: ô homme! qui est-ce qui m’a établi sur vous pour être votre juge, et pour faire vos partages?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Puis il leur dit: voyez, et gardez-vous d’avarice; car encore que les biens abondent à quelqu’un, il n’a pourtant pas la vie par ses biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Et il leur dit cette parabole: Les champs d’un homme riche avaient rapporté en abondance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'Et il pensait en lui-même, disant: que ferai-je, car je n’ai point où je puisse assembler mes fruits?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Puis il dit: voici ce que je ferai: j’abattrai mes greniers, et j’en bâtirai de plus grands, et j’y assemblerai tous mes revenus et mes biens;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'Puis je dirai à mon âme: mon âme, tu as beaucoup de biens assemblés pour beaucoup d’années, repose-toi, mange, bois, et fais grande chère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Mais Dieu lui dit: insensé, en cette même nuit ton âme te sera redemandée; et les choses que tu as préparées, à qui seront-elles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Il en est ainsi de celui qui fait de grands amas de biens pour soi-même, et qui n’est pas riche en Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Alors il dit à ses Disciples: à cause de cela je vous dis, ne soyez point en souci pour votre vie, de ce que vous mangerez; ni pour votre corps, de quoi vous serez vêtus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'La vie est plus que la nourriture, et le corps est plus que le vêtement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Considérez les corbeaux, ils ne sèment, ni ne moissonnent, et ils n’ont point de cellier, ni de grenier, et cependant Dieu les nourrit; combien valez- vous mieux que les oiseaux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Et qui est celui de vous qui par son souci puisse ajouter une coudée à sa stature?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Si donc vous ne pouvez pas même ce qui est très-petit, pourquoi êtes-vous en souci du reste?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Considérez comment croissent les lis, ils ne travaillent, ni ne filent, et cependant je vous dis que Salomon même dans toute sa gloire n’était point vêtu comme l’un d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Que si Dieu revêt ainsi l’herbe qui est aujourd’hui au champ, et qui demain est mise au four, combien plus vous vêtira-t-il, ô gens de petite foi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Ne dites donc point: que mangerons-nous, ou que boirons-nous? et ne soyez point en suspens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Car les gens de ce monde sont après à rechercher toutes ces choses; mais votre Père sait que vous avez besoin de ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Mais plutôt cherchez le Royaume de Dieu, et toutes ces choses vous seront données par-dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Ne crains point, petit troupeau; car il a plu à votre Père de vous donner le Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Vendez ce que vous avez, et donnez en l’aumône; faites-vous des bourses qui ne s’envieillissent point; et un trésor dans les cieux, qui ne défaille jamais, d’où le larron n’approche point, et où la teigne ne gâte rien;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Car où est votre trésor, là sera aussi votre coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Que vos reins soient ceints, et vos lampes allumées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'Et soyez semblables aux serviteurs qui attendent le maître quand il retournera des noces; afin que quand il viendra, et qu’il heurtera, ils lui ouvrent aussitôt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Bienheureux sont ces serviteurs que le maître trouvera veillants, quand il arrivera. En vérité je vous dis qu’il se ceindra, et les fera mettre à table, et s’avançant il les servira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Que s’il arrive sur la seconde veille, ou sur la troisième, et qu’il les trouve ainsi veillants, bienheureux sont ces serviteurs-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Or sachez ceci, que si le père de famille savait à quelle heure le larron doit venir, il veillerait, et ne laisserait point percer sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Vous donc aussi tenez-vous prêts, car le Fils de l’homme viendra à l’heure que vous n’y penserez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Et Pierre lui dit: Seigneur, dis-tu cette parabole pour nous, ou aussi pour tous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Et le Seigneur dit: qui est donc le dispensateur fidèle et prudent, que le maître aura établi sur toute la troupe de ses serviteurs pour leur donner l’ordinaire dans le temps qu’il faut?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Bienheureux est ce serviteur-là que son maître trouvera faisant ainsi, quand il viendra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'En vérité, je vous dis, qu’il l’établira sur tout ce qu’il a.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Mais si ce serviteur-là dit en son coeur: mon maître tarde longtemps à venir, et qu’il se mette à battre les serviteurs et les servantes, et à manger, et à boire, et à s’enivrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'Le maître de ce serviteur viendra au jour qu’il ne l’attend point, et à l’heure qu’il ne sait point, et il le séparera, et le mettra au rang des infidèles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Or le serviteur qui a connu la volonté de son maître, et qui ne s’est pas tenu prêt, et n’a point fait selon sa volonté, sera battu de plusieurs coups.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Mais celui qui ne l’a point connue, et qui a fait des choses dignes de châtiment, sera battu de moins de coups; car à chacun à qui il aura été beaucoup donné, il sera beaucoup redemandé; et à celui à qui il aura été beaucoup confié, il sera plus redemandé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Je suis venu mettre le feu en la terre; et que veux-je, s’il est déjà allumé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Or j’ai à être baptisé d’un Baptême; et combien suis-je pressé jusqu’à ce qu’il soit accompli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Pensez-vous que je sois venu mettre la paix en la terre? non, vous dis-je; mais plutôt la division.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Car désormais ils seront cinq dans une maison, divisés, trois contre deux, et deux contre trois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'Le père sera divisé contre le fils, et le fils contre le père; la mère contre la fille, et la fille contre la mère; la belle-mère contre sa belle- fille, et la belle-fille contre sa belle-mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Puis il disait aux troupes: quand vous voyez une nuée qui se lève de l’occident, vous dites d’abord: la pluie vient, et cela arrive ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'Et quand vous voyez souffler le vent du Midi, vous dites qu’il fera chaud; et cela arrive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Hypocrites, vous savez bien discerner les apparences du ciel et de la terre; et comment ne discernez-vous point cette saison?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Et pourquoi aussi ne reconnaissez-vous pas de vous-mêmes ce qui est juste?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Or quand tu vas au Magistrat avec ta partie adverse, tâche en chemin d’en être délivré; de peur qu’elle ne te tire devant le juge, et que le juge ne te livre au sergent, et que le sergent ne te mette en prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Je te dis que tu ne sortiras point de là jusqu’à ce que tu aies rendu la dernière pite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'En ce même temps quelques-uns qui se trouvaient là présents, lui racontèrent ce qui s’était passé touchant les Galiléens, desquels Pilate avait mêlé le sang avec leurs sacrifices.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Et Jésus répondant leur dit: croyez-vous que ces Galiléens fussent plus pécheurs que tous les Galiléens, parce qu’ils ont souffert de telles choses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Non, vous dis-je; mais si vous ne vous repentez, vous périrez tous de la même manière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Ou croyez-vous que ces dix-huit sur qui la tour de Siloé tomba, et les tua, fussent plus coupables que tous les habitants de Jérusalem?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Non, vous dis-je; mais si vous ne vous repentez, vous périrez tous de la même manière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Il disait aussi cette parabole: quelqu’un avait un figuier planté dans sa vigne, et il y vint chercher du fruit, mais il n’y en trouva point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Et il dit au vigneron: voici, il y a trois ans que je viens chercher du fruit en ce figuier, et je n’y en trouve point; coupe-le; pourquoi occupe-t- il inutilement la terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Et le vigneron répondant, lui dit: Seigneur, laisse-le encore pour cette année, jusqu’à ce que je l’aie déchaussé, et que j’y aie mis du fumier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'Que s’il fait du fruit, tu le laisseras; sinon, tu le couperas après cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Or comme il enseignait dans une de leurs Synagogues un jour de Sabbat,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Voici, il y avait là une femme qui était possédée d’un démon qui la rendait malade depuis dix-huit ans, et elle était courbée, et ne pouvait nullement se redresser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Et quand Jésus l’eut vue, il l’appela, et lui dit: femme, tu es délivrée de ta maladie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'Et il posa les mains sur elle; et dans ce moment elle fut redressée, et glorifiait Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Mais le Maître de la Synagogue, indigné de ce que Jésus avait guéri au jour du Sabbat, prenant la parole dit à l’assemblée: il y a six jours auxquels il faut travailler; venez donc ces jours-là, et soyez guéris, et non point au jour du Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Et le Seigneur lui répondit, et dit: hypocrite, chacun de vous ne détache- t-il pas son boeuf ou son âne de la crèche le jour du Sabbat, et ne les mène-t- il pas boire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Et ne fallait-il pas délier de ce lien au jour du Sabbat celle-ci qui est fille d’Abraham, laquelle satan avait liée il y a déjà dix-huit ans?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Comme il disait ces choses, tous ses adversaires étaient confus; mais toutes les troupes se réjouissaient de toutes les choses glorieuses qu’il opérait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Il disait aussi: à quoi est semblable le Royaume de Dieu, et à quoi le comparerai-je?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Il est semblable au grain de semence de moutarde qu’un homme prit, et mit en son jardin, lequel crût, et devint un grand arbre, tellement que les oiseaux du ciel faisaient leurs nids dans ses branches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'Il dit encore: à quoi comparerai-je le Royaume de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Il est semblable au levain qu’une femme prit, et qu’elle mit parmi trois mesures de farine, jusqu’à ce qu’elle fût toute levée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'Puis il s’en allait par les villes et par les bourgades, enseignant, et tenant le chemin de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Et quelqu’un lui dit: Seigneur, n’y a-t-il que peu de gens qui soient sauvés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Et il leur dit: faites effort pour entrer par la porte étroite; car je vous dis que plusieurs tâcheront d’entrer, et ils ne le pourront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Et après que le père de famille se sera levé, et qu’il aura fermé la porte, et que vous étant dehors vous vous mettrez à heurter à la porte, en disant: Seigneur! Seigneur! ouvre-nous; et que lui vous répondant vous dira: je ne sais d’où vous êtes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Alors vous vous mettrez à dire: nous avons mangé et bu en ta présence, et tu as enseigné dans nos rues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'Mais il dira: je vous dis que je ne sais d’où vous êtes; retirez-vous de moi, vous tous qui faites le métier d’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Là il y aura des pleurs et des grincements de dents; quand vous verrez Abraham, et Isaac, et Jacob, et tous les Prophètes dans le Royaume de Dieu, et que vous serez jetés dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Il en viendra aussi d’Orient, et d’Occident, et du Septentrion, et du Midi, qui seront à table dans le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Et voici, ceux qui sont les derniers seront les premiers, et ceux qui sont les premiers seront les derniers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'En ce même jour-là quelques Pharisiens vinrent à lui et lui dirent: retire- toi et t’en va d’ici; car Hérode te veut tuer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Et il leur répondit: allez, et dites à ce renard: voici, je chasse les démons, et j’achève aujourd’hui et demain de faire des guérisons, et le troisième jour je prends fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'C’est pourquoi il me faut marcher aujourd’hui et demain, et le jour suivant; car il n’arrive point qu’un Prophète meure hors de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jérusalem, Jérusalem, qui tues les Prophètes, et qui lapides ceux qui te sont envoyés; combien de fois ai-je voulu rassembler tes enfants, comme la poule rassemble ses poussins sous ses ailes, et vous ne l’avez point voulu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Voici, votre maison va être déserte; et je vous dis en vérité, que vous ne me verrez point jusqu’à ce qu’il arrivera que vous direz: béni soit celui qui vient au nom du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Il arriva aussi que Jésus étant entré un jour de Sabbat dans la maison d’un des principaux des Pharisiens, pour prendre son repas, ils l’observaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Et voici, un homme hydropique était là devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Et Jésus prenant la parole, parla aux Docteurs de la Loi, et aux Pharisiens, disant: est-il permis de guérir au jour du Sabbat?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Et ils ne dirent mot. Alors ayant pris le malade, il le guérit, et le renvoya.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Puis s’adressant à eux, il leur dit: qui sera celui d’entre vous, qui ayant un âne ou un boeuf lequel vienne à tomber dans un puits, ne l’en retire aussitôt le jour du Sabbat?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Et ils ne pouvaient répliquer à ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Il proposait aussi aux conviés une similitude, prenant garde comment ils choisissaient les premières places à table, et il leur disait:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Quand tu seras convié par quelqu’un à des noces, ne te mets point à table à la première place, de peur qu’il n’arrive qu’un plus honorable que toi soit aussi convié;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'Et que celui qui vous aura convié, ne vienne, et ne te dise: donne ta place à celui-ci; et qu’alors tu ne commences avec honte de te mettre à la dernière place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Mais quand tu seras convié, va, et te mets à la dernière place, afin que quand celui qui t’a convié viendra, il te dise: mon ami, monte plus haut; et alors cela te tournera à honneur devant tous ceux qui seront à table avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Car quiconque s’élève, sera abaissé; et quiconque s’abaisse, sera élevé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Il disait aussi à celui qui l’avait convié: quand tu fais un dîner ou un souper, n’invite point tes amis, ni tes frères, ni tes parents, ni tes riches voisins; de peur qu’ils ne te convient à leur tour, et que la pareille ne te soit rendue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Mais quand tu feras un festin, convie les pauvres, les impotents, les boiteux et les aveugles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'Et tu seras bienheureux de ce qu’ils n’ont pas de quoi te rendre la pareille; car la pareille te sera rendue en la résurrection des justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Et un de ceux qui étaient à table, ayant entendu ces paroles, lui dit: bienheureux sera celui qui mangera du pain dans le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Et Jésus dit: un homme fit un grand souper, et y convia beaucoup de gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'Et à l’heure du souper il envoya son serviteur pour dire aux conviés: venez, car tout est déjà prêt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Mais ils commencèrent tous unanimement à s’excuser. Le premier lui dit: j’ai acheté un héritage, et il me faut nécessairement partir pour l’aller voir; je te prie, tiens-moi pour excusé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Un autre dit: j’ai acheté cinq couples de boeufs, et je m’en vais les éprouver; je te prie, tiens-moi pour excusé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Et un autre dit: j’ai épousé une femme, c’est pourquoi je n’y puis aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Ainsi le serviteur s’en retourna, et rapporta ces choses à son maître. Alors le père de famille tout en colère, dit à son serviteur: va-t’en promptement dans les places et dans les rues de la ville, et amène ici les pauvres, et les impotents, et les boiteux et les aveugles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'Puis le serviteur dit: Maître, il a été fait ainsi que tu as commandé, et il y a encore de la place.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Et le maître dit au serviteur: va dans les chemins et le long des haies, et ceux que tu trouveras, contrains-les d’entrer, afin que ma maison soit remplie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Car je vous dis qu’aucun de ces hommes qui avaient été conviés ne goûtera de mon souper.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Or de grandes troupes allaient avec lui; et lui se tournant leur dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, 'Si quelqu’un vient vers moi, et ne hait pas son père et sa mère, et sa femme et ses enfants, et ses frères, et ses soeurs, et même sa propre vie, il ne peut être mon disciple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Et quiconque ne porte sa croix, et ne vient après moi, il ne peut être mon disciple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Mais qui est celui d’entre vous, qui voulant bâtir une tour, ne s’asseye premièrement, et ne calcule la dépense pour voir s’il a de quoi l’achever?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'De peur qu’après en avoir jeté le fondement, et n’ayant pu achever, tous ceux qui le verront ne commencent à se moquer de lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'En disant: cet homme a commencé à bâtir, et il n’a pu achever.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Ou, qui est le Roi qui parte pour donner bataille à un autre Roi, qui premièrement ne s’asseye, et ne consulte s’il pourra avec dix mille hommes aller à la rencontre de celui qui vient contre lui avec vingt mille?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Autrement, il lui envoie une ambassade, pendant qu’il est encore loin, et demande la paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Ainsi donc chacun de vous qui ne renonce pas à tout ce qu’il a, ne peut être mon disciple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Le sel est bon; mais si le sel devient insipide, avec quoi le salera-t-on?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Il n’est propre ni pour la terre, ni pour le fumier; mais on le jette dehors. Qui a des oreilles pour ouïr, qu’il entende!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Or tous les péagers et les gens de mauvaise vie s’approchaient de lui pour l’entendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Mais les Pharisiens et les Scribes murmuraient, disant: celui-ci reçoit les gens de mauvaise vie, et mange avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Mais il leur proposa cette parabole, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Qui est l’homme d’entre vous qui ayant cent brebis, s’il en perd une, ne laisse les quatre-vingt-dix-neuf au désert, et ne s’en aille après celle qui est perdue, jusqu’à ce qu’il l’ait trouvée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Et qui l’ayant trouvée ne la mette sur ses épaules bien joyeux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'Et étant de retour en sa maison, n’appelle ses amis et ses voisins, et ne leur dise: réjouissez-vous avec moi; car j’ai trouvé ma brebis qui était perdue?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Je vous dis, qu’il y aura de même de la joie au ciel pour un seul pécheur qui vient à se repentir, plus que pour quatre-vingt-dix-neuf justes, qui n’ont pas besoin de repentance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Ou qui est la femme qui ayant dix drachmes, si elle perd une drachme, n’allume la chandelle, et ne balaye la maison, et ne la cherche diligemment, jusqu’à ce qu’elle l’ait trouvée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Et qui après l’avoir trouvé, n’appelle ses amis et ses voisines, en leur disant: réjouissez-vous avec moi; car j’ai trouvé la drachme que j’avais perdue?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Ainsi je vous dis qu’il y a de la joie devant les Anges de Dieu pour un seul pécheur qui vient à se repentir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Il leur dit aussi: un homme avait deux fils;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'Et le plus jeune dit à son père: mon père, donne-moi la part du bien qui m’appartient; et il leur partagea ses biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Et peu de jours après, quand le plus jeune fils eut tout ramassé, il s’en alla dehors en un pays éloigné; et là il dissipa son bien en vivant dans la débauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Et après qu’il eut tout dépensé, une grande famine survint en ce pays-là; et il commença d’être dans la disette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Alors il s’en alla, et se mit au service d’un des habitants du pays, qui l’envoya dans ses possessions pour paître les pourceaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Et il désirait de se rassasier des gousses que les pourceaux mangeaient; mais personne ne lui en donnait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Or étant revenu à lui-même, il dit: combien y a-t-il de mercenaires dans la maison de mon père, qui ont du pain en abondance, et moi je meurs de faim?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Je me lèverai, et je m’en irai vers mon père, et je lui dirai: mon père, j’ai péché contre le ciel et devant toi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'Et je ne suis plus digne d’être appelé ton fils; traite-moi comme l’un de tes mercenaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Il se leva donc, et vint vers son père; et comme il était encore loin, son père le vit, et fut touché de compassion, et courant à lui, se jeta à son cou, et le baisa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Mais le fils lui dit: mon père, j’ai péché contre le ciel et devant toi; et je ne suis plus digne d’être appelé ton fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Et le père dit à ses serviteurs: apportez la plus belle robe, et l’en revêtez, mettez-lui un anneau au doigt, et des souliers aux pieds;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'Et amenez-moi le veau gras, et le tuez, et faisons bonne chère en le mangeant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'Car mon fils que voici, était mort, mais il est ressuscité; il était perdu, mais il est retrouvé. Et ils commencèrent à faire bonne chère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Or son fils aîné était aux champs, et comme il revenait et qu’il approchait de la maison, il entendit la mélodie et les danses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'Et ayant appelé un des serviteurs, il lui demanda ce que c’était.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'Et ce serviteur lui dit: ton frère est venu, et ton père a tué le veau gras, parce qu’il l’a recouvré sain et sauf.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Mais il se mit en colère, et ne voulut point entrer; et son père étant sorti le priait d’entrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Mais il répondit, et dit à son père: voici, il y a tant d’années que je te sers, et jamais je n’ai transgressé ton commandement, et cependant tu ne m’as jamais donné un chevreau pour faire bonne chère avec mes amis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Mais quand celui-ci, ton fils, qui a mangé ton bien avec des femmes de mauvaise vie, est venu, tu lui as tué le veau gras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Et le père lui dit: mon enfant, tu es toujours avec moi, et tous mes biens sont à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Or il fallait faire bonne chère, et se réjouir, parce que celui-ci, ton frère, était mort, et il est ressuscité; il était perdu, et il est retrouvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Il disait aussi à ses Disciples: Il y avait un homme riche qui avait un économe, lequel fut accusé devant lui comme dissipateur de ses biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Sur quoi l’ayant appelé, il lui dit: qu’est-ce que j’entends dire de toi? Rends compte de ton administration; car tu n’auras plus le pouvoir d’administrer mes biens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Alors l’économe dit en lui-même: que ferai-je, puisque mon maître m’ôte l’administration? je ne puis pas fouir la terre, et j’ai honte de mendier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Je sais ce que je ferai, afin que quand mon administration me sera ôtée, quelques-uns me reçoivent dans leurs maisons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Alors il appela chacun des débiteurs de son maître, et il dit au premier: combien dois-tu à mon maître?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Il dit: cent mesures d’huile. Et il lui dit: prends ton obligation, et t’assieds sur-le-champ, et n’en écris que cinquante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Puis il dit à un autre: et toi combien dois-tu? et il dit: cent mesures de froment. Et il lui dit: prends ton obligation, et n’en écris que quatre- vingts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Et le maître loua l’économe infidèle de ce qu’il avait agi prudemment. Ainsi les enfants de ce siècle sont plus prudents en leur génération, que les enfants de lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Et moi aussi je vous dis: faites-vous des amis des richesses iniques; afin que quand vous viendrez à manquer, ils vous reçoivent dans les Tabernacles éternels.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Celui qui est fidèle en très peu de chose, est fidèle aussi dans les grandes choses; et celui qui est injuste en très peu de chose, est injuste aussi dans les grandes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Si donc vous n’avez pas été fidèles dans les richesses iniques, qui vous confiera les vraies richesses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Et si en ce qui est à autrui vous n’avez pas été fidèles, qui vous donnera ce qui est vôtre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Nul serviteur ne peut servir deux maîtres; car ou il haïra l’un, et aimera l’autre; ou il s’attachera à l’un, et méprisera l’autre. Vous ne pouvez servir Dieu et les richesses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Or les Pharisiens aussi, qui étaient avares, entendaient toutes ces choses, et ils se moquaient de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Et il leur dit: vous vous justifiez vous-mêmes devant les hommes; mais Dieu connaît vos coeurs; c’est pourquoi ce qui est grand devant les hommes, est en abomination devant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'La Loi et les Prophètes ont duré jusqu’à Jean; depuis ce temps-là le Règne de Dieu est évangélisé, et chacun le force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Or il est plus aisé que le ciel et la terre passent, que non pas qu’il tombe un seul point de la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Quiconque répudie sa femme, et se marie à une autre, commet un adultère, et quiconque prend celle qui a été répudiée par son mari, commet un adultère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Or il y avait un homme riche, qui se vêtait de pourpre et de fin lin, et qui tous les jours se traitait splendidement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Il y avait aussi un pauvre, nommé Lazare, couché à la porte du riche, et tout couvert d’ulcères;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'Et qui désirait d’être rassasié des miettes qui tombaient de la table du riche; et même les chiens venaient, et lui léchaient ses ulcères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Et il arriva que le pauvre mourut, et il fut porté par les Anges au sein d’Abraham; le riche mourut aussi, et fut enseveli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Et étant en enfer, et élevant ses yeux, comme il était dans les tourments, il vit de loin Abraham et Lazare dans son sein.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Et s’écriant, il dit: Père Abraham aie pitié de moi, et envoie Lazare, qui mouillant dans l’eau le bout de son doigt, vienne rafraîchir ma langue; car je suis grièvement tourmenté dans cette flamme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Et Abraham répondit: mon fils, souviens-toi que tu as reçu tes biens en ta vie, et que Lazare y a eu ses maux; mais il est maintenant consolé, et tu es grièvement tourmenté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'Et outre tout cela, il y a un grand abîme entre nous et vous; tellement que ceux qui veulent passer d’ici vers vous, ne le peuvent; ni de là, passer ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Et il dit: je te prie donc, père, de l’envoyer en la maison de mon père;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'Car j’ai cinq frères, afin qu’il leur rende témoignage de l’état où je suis; de peur qu’eux aussi ne viennent dans ce lieu de tourment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Abraham lui répondit: Ils ont Moïse et les Prophètes; qu’ils les écoutent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'Mais il dit: Non, père Abraham, mais si quelqu’un des morts va vers eux, ils se repentiront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Et Abraham lui dit: s’ils n’écoutent point Moïse et les Prophètes, ils ne seront pas non plus persuadés, quand quelqu’un des morts ressusciterait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Or il dit à ses Disciples: il ne se peut faire qu’il n’arrive des scandales; mais malheur à celui par qui ils arrivent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Il lui vaudrait mieux qu’on lui mît une pierre de meule autour de son cou, et qu’il fût jeté dans la mer, que de scandaliser un seul de ces petits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Soyez attentifs sur vous-mêmes. Si donc ton Frère a péché contre toi, reprends-le; et s’il se repent, pardonne-lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'Et si sept fois le jour il a péché contre toi, et que sept fois le jour il retourne à toi, disant: je me repens; tu lui pardonneras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Alors les Apôtres dirent au Seigneur: augmente-nous la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Et le Seigneur dit: si vous aviez de la foi aussi gros qu’un grain de semence de moutarde, vous pourriez dire à ce mûrier: déracine-toi, et te plante dans la mer; et il vous obéirait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Mais qui est celui d’entre vous qui ayant un serviteur labourant, ou paissant le bétail, et qui le voyant retourner des champs, lui dise incontinent: avance-toi, et mets-toi à table;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Et qui plutôt ne lui dise: apprête-moi à souper, ceins-toi, et me sers jusqu’à ce que j’aie mangé et bu; et après cela tu mangeras et tu boiras?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Mais est-il pour cela obligé à ce serviteur de ce qu’il a fait ce qu’il lui avait commandé? Je ne le pense pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Vous aussi de même, quand vous aurez fait toutes les choses qui vous sont commandées, dites: nous sommes des serviteurs inutiles; parce que ce que nous avons fait, nous étions obligés de le faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'Et il arriva qu’en allant à Jérusalem, il passait par le milieu de la Samarie, et de la Galilée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Et comme il entrait dans une bourgade, dix hommes lépreux le rencontrèrent, et ils s’arrêtèrent de loin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'Et élevant leur voix, ils lui dirent: Jésus, Maître, aie pitié de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Et quand il les eut vus, il leur dit: allez, montrez-vous aux Sacrificateurs. Et il arriva qu’en s’en allant ils furent rendus nets.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Et l’un d’eux voyant qu’il était guéri, s’en retourna, glorifiant Dieu à haute voix;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'Et il se jeta en terre sur sa face aux pieds de Jésus, lui rendant grâces. Or c’était un Samaritain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Alors Jésus prenant la parole, dit: les dix n’ont-ils pas été rendus nets? et les neuf où sont-ils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Il n’y a eu que cet étranger qui soit retourné pour rendre gloire à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'Alors il lui dit: lève-toi; va-t’en, ta foi t’a sauvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Or étant interrogé par les Pharisiens, quand viendrait le Règne de Dieu; il répondit, et leur dit: le Règne de Dieu ne viendra point avec apparence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'Et on ne dira point: voici, il est ici; ou voilà, il est là; car voici, le Règne de Dieu est au-dedans de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Il dit aussi à ses Disciples: les jours viendront que vous désirerez de voir un des jours du Fils de l’homme, mais vous ne le verrez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'Et l’on vous dira: voici, il est ici; ou voilà, il est là; mais n’y allez point, et ne les suivez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Car comme l’éclair brille de l’un des côtés de dessous le ciel, et reluit jusques à l’autre qui est sous le ciel, tel sera aussi le Fils de l’homme en son jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Mais il faut premièrement qu’il souffre beaucoup, et qu’il soit rejeté par cette nation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Et comme il arriva aux jours de Noé, il arrivera de même aux jours du Fils de l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'On mangeait et on buvait; on prenait et on donnait des femmes en mariage jusqu’au jour que Noé entra dans l’Arche; et le déluge vint qui les fit tous périr.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Il arriva aussi la même chose aux jours de Lot: on mangeait, on buvait, on achetait, on vendait, on plantait et on bâtissait;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'Mais au jour que Lot sortit de Sodome, il plut du feu et du soufre du ciel, qui les fit tous périr.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Il en sera de même au jour que le Fils de l’homme sera manifesté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'En ce jour-là que celui qui sera sur la maison, et qui aura son ménage dans la maison, ne descende point pour l’emporter; et que celui qui sera aux champs, ne retourne point non plus à ce qui est demeuré en arrière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Souvenez-vous de la femme de Lot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Quiconque cherchera à sauver sa vie, la perdra; et quiconque la perdra, la vivifiera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Je vous dis, qu’en cette nuit-là deux seront dans un même lit: l’un sera pris, et l’autre laissé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Il y aura deux femmes qui moudront ensemble: l’une sera prise, et l’autre laissée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Deux seront aux champs: l’un sera pris, et l’autre laissé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'Et eux répondant lui dirent: où sera-ce Seigneur? et il leur dit: en quelque lieu que sera le corps mort, là aussi s’assembleront les aigles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Il leur proposa aussi une parabole, pour faire voir qu’il faut toujours prier, et ne se lasser point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Disant: Il y avait dans une ville un juge, qui ne craignait point Dieu, et qui ne respectait personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Et dans la même ville il y avait une veuve, qui l’allait souvent trouver, et lui dire: fais-moi justice de ma partie adverse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Pendant longtemps il n’en voulut rien faire. Mais après cela il dit en lui- même: quoique je ne craigne point Dieu, et que je ne respecte personne,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'Néanmoins, parce que cette veuve me donne de la peine, je lui ferai justice, de peur qu’elle ne vienne perpétuellement me rompre la tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Et le Seigneur dit: écoutez ce que dit le juge inique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Et Dieu ne vengera-t-il point ses élus qui crient à lui jour et nuit, quoiqu’il diffère de s’irriter pour l’amour d’eux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Je vous dis que bientôt il les vengera. Mais quand le Fils de l’homme viendra, pensez-vous qu’il trouve de la foi sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Il dit aussi cette parabole à quelques-uns qui se confiaient en eux-mêmes d’être justes, et qui tenaient les autres pour rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Deux hommes montèrent au Temple pour prier, l’un Pharisien; et l’autre, péager.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Le Pharisien se tenant à l’écart priait en lui-même en ces termes: ô Dieu! je te rends grâces de ce que je ne suis point comme le reste des hommes, qui sont ravisseurs, injustes, adultères, ni même comme ce péager.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Je jeûne deux fois la semaine, et je donne la dîme de tout ce que je possède.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Mais le péager se tenant loin, n’osait pas même lever les yeux vers le ciel, mais frappait sa poitrine, en disant: ô Dieu! sois apaisé envers moi qui suis pécheur!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Je vous dis que celui-ci descendit en sa maison justifié, plutôt que l’autre; car quiconque s’élève, sera abaissé, et quiconque s’abaisse, sera élevé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Et quelques-uns lui présentèrent aussi de petits enfants, afin qu’il les touchât, ce que les Disciples voyant, ils censurèrent ceux qui les présentaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Mais Jésus les ayant fait venir à lui, dit: laissez venir à moi les petits enfants, et ne les en empêchez point; car le Royaume de Dieu est pour ceux qui leur ressemblent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'En vérité je vous dis: que quiconque ne recevra point comme un enfant le Royaume de Dieu, n’y entrera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Et un Seigneur l’interrogea, disant: Maître qui es bon, que ferai-je pour hériter la vie éternelle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Jésus lui dit: pourquoi m’appelles-tu bon? Il n’y a nul bon qu’un seul, qui est Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Tu sais les Commandements: tu ne commettras point adultère. Tu ne tueras point. Tu ne déroberas point. Tu ne diras point faux témoignage. Honore ton père et ta mère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'Et il lui dit: j’ai gardé toutes ces choses dès ma jeunesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Et quand Jésus eut entendu cela, il lui dit: il te manque encore une chose: vends tout ce que tu as, et le distribue aux pauvres, et tu auras un trésor au ciel; puis viens, et me suis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Mais lui ayant entendu ces choses devint fort triste, car il était extrêmement riche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Et Jésus voyant qu’il était devenu fort triste, dit: qu’il est malaisé que ceux qui ont des biens entrent dans le Royaume de Dieu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Il est certes plus aisé qu’un chameau passe par le trou d’une aiguille, qu’il ne l’est qu’un riche entre dans le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Et ceux qui entendirent cela, dirent: Et qui peut donc être sauvé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Et il leur dit: les choses qui sont impossibles aux hommes sont possibles à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Et Pierre dit: voici, nous avons tout quitté, et nous t’avons suivi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Et il leur dit: en vérité je vous dis, qu’il n’y en a pas un qui ait quitté sa maison, ou ses parents, ou ses frères, ou sa femme, ou ses enfants pour l’amour du Royaume de Dieu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'Qui ne reçoive beaucoup plus en ce temps-ci, et au siècle à venir la vie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Puis Jésus prit à part les douze, et il leur dit: voici, nous montons à Jérusalem, et toutes les choses qui sont écrites par les Prophètes touchant le Fils de l’homme, seront accomplies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Car il sera livré aux Gentils; il sera moqué, et injurié, et on lui crachera au visage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'Et après qu’ils l’auront fouetté, ils le feront mourir; mais il ressuscitera le troisième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Mais ils ne comprirent rien de tout cela, et ce discours était si obscur pour eux qu’ils ne comprirent point ce qu’il leur disait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Or il arriva comme il approchait de Jéricho, qu’il y avait un aveugle assis près du chemin, et qui mendiait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Et entendant la multitude qui passait, il demanda ce que c’était.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'Et on lui dit que Jésus le Nazarien passait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Alors il cria, disant: Jésus, Fils de David, aie pitié de moi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Et ceux qui allaient devant, le reprenaient, afin qu’il se tût; mais il criait beaucoup plus fort: Fils de David, aie pitié de moi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Et Jésus s’étant arrêté commanda qu’on le lui amenât; et quand il se fut approché, il l’interrogea,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Disant: que veux-tu que je te fasse? Il répondit: Seigneur, que je recouvre la vue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Et Jésus lui dit: recouvre la vue; ta foi t’a sauvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'Et à l’instant il recouvra la vue; et il suivait Jésus, glorifiant Dieu. Et tout le peuple voyant cela, en loua Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Et Jésus étant entré dans Jéricho, allait par la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Et voici un homme appelé Zachée, qui était principal péager, et qui était riche,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'Tâchait de voir lequel était Jésus, mais il ne pouvait à cause de la foule, car il était petit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'C’est pourquoi il accourut devant, et monta sur un sycomore pour le voir; car il devait passer par là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Et quand Jésus fut venu à cet endroit-là, regardant en haut, il le vit, et lui dit: Zachée, descends promptement; car il faut que je demeure aujourd’hui dans ta maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Et il descendit promptement, et le reçut avec joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Et tous voyant cela murmuraient, disant qu’il était entré chez un homme de mauvaise vie pour y loger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Et Zachée se présentant là, dit au Seigneur: Voici, Seigneur, je donne la moitié de mes biens aux pauvres; et si j’ai fait tort à quelqu’un en quelque chose, j’en rends le quadruple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Et Jésus lui dit: aujourd’hui le salut est entré dans cette maison; parce que celui-ci aussi est fils d’Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Car le Fils de l’homme est venu chercher et sauver ce qui était perdu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Et comme ils entendaient ces choses, Jésus poursuivit son discours, et proposa une parabole, parce qu’il était près de Jérusalem, et qu’ils pensaient qu’à l’instant le Règne de Dieu devait être manifesté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Il dit donc: un homme noble s’en alla dans un pays éloigné, pour se mettre en possession d’un Royaume, mais dans la vue de revenir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Et ayant appelé dix de ses serviteurs, il leur donna dix marcs d’argent et leur dit: Faites-les valoir jusqu’à ce que je vienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Or ses citoyens le haïssaient: c’est pourquoi ils envoyèrent après lui une députation, pour dire: nous ne voulons pas que celui-ci règne sur nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Il arriva donc après qu’il fut retourné, et qu’il se fut mis en possession du Royaume, qu’il commanda qu’on lui appelât ces serviteurs à qui il avait confié son argent, afin qu’il sût combien chacun aurait gagné par son trafic.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Alors le premier vint, disant: Seigneur, ton marc a produit dix autres marcs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Et il lui dit: cela va bien, bon serviteur; parce que tu as été fidèle en peu de chose, aie puissance sur dix villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Et un autre vint, disant: Seigneur, ton marc en a produit cinq autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Et il dit aussi à celui-ci: et toi, sois établi sur cinq villes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'Et un autre vint, disant: Seigneur, voici ton marc que j’ai tenu enveloppé dans un linge;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'Car je t’ai craint, parce que tu es un homme sévère; tu prends ce que tu n’as point mis, et tu moissonnes ce que tu n’as point semé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Et il lui dit: méchant serviteur, je te jugerai par ta propre parole: tu savais que je suis un homme sévère, prenant ce que je n’ai point mis, et moissonnant ce que je n’ai point semé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Pourquoi donc n’as-tu pas mis mon argent à la banque, et à mon retour je l’eusse retiré avec l’intérêt?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'Alors il dit à ceux qui étaient présents: Otez-lui le marc, et donnez-le à celui qui a les dix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'Et ils lui dirent: Seigneur, il a dix marcs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'Ainsi je vous dis, qu’à chacun qui aura, il sera donné; et à celui qui n’a rien, cela même qu’il a, lui sera ôté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Au reste, amenez ici ces ennemis qui n’ont pas voulu que je régnasse sur eux, et tuez-les devant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Et ayant dit ces choses, il allait devant eux, montant à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Et il arriva comme il approchait de Bethphagé et de Béthanie, vers la montagne appelée des oliviers, qu’il envoya deux de ses Disciples,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'En leur disant: allez à la bourgade qui est vis-à-vis de vous, et y étant entrés, vous trouverez un ânon attaché, sur lequel jamais homme n’est monté; détachez-le, et amenez-le-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Que si quelqu’un vous demande pourquoi vous le détachez, vous lui direz ainsi: c’est parce que le Seigneur en a besoin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Et ceux qui étaient envoyés s’en allèrent, et trouvèrent l’ânon comme il le leur avait dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Et comme ils détachaient l’ânon, les maîtres leur dirent: pourquoi détachez-vous cet ânon?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Ils répondirent: le Seigneur en a besoin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'Ils l’emmenèrent donc à Jésus, et ils jetèrent leurs vêtements sur l’ânon; puis ils mirent Jésus dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'En même temps qu’il marchait, ils étendaient leurs vêtements par le chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Et lorsqu’il fut proche de la descente de la montagne des oliviers, toute la multitude des Disciples se réjouissant, se mit à louer Dieu à haute voix, pour tous les miracles qu’ils avaient vus;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'Disant: béni soit le Roi qui vient au Nom du Seigneur; que la paix soit dans le ciel, et la gloire dans les lieux très-hauts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Et quelques-uns d’entre les Pharisiens de la troupe lui dirent: Maître, reprends tes Disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Et Jésus répondant, leur dit: je vous dis que si ceux-ci se taisent, les pierres mêmes crieront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Et quand il fut proche, voyant la ville, il pleura sur elle, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'O! si toi aussi eusses connu, au moins en cette tienne journée, les choses qui appartiennent à ta paix! mais maintenant elles sont cachées devant tes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Car les jours viendront sur toi que tes ennemis t’environneront de tranchées, ils t’enfermeront, et t’enserreront de tous côtés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'Et te raseront, toi et tes enfants qui sont au-dedans de toi, et ils ne laisseront en toi pierre sur pierre, parce que tu n’as point connu le temps de ta visitation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'Puis étant entré au Temple, il commença à chasser dehors ceux qui y vendaient et qui y achetaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'Leur disant: il est écrit: ma Maison est la Maison de prière; mais vous en avez fait une caverne de voleurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Et il était tous les jours enseignant dans le Temple, et les principaux Sacrificateurs et les Scribes, tâchaient de le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'Mais ils ne trouvaient rien qu’ils lui pussent faire; car tout le peuple était fort attentif à l’écouter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Et il arriva un de ces jours-là, comme il enseignait le peuple dans le Temple, et qu’il évangélisait, que les principaux Sacrificateurs et les Scribes survinrent avec les Anciens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'Et ils lui parlèrent, en disant: dis-nous par quelle autorité tu fais ces choses, ou qui est celui qui t’a donné cette autorité?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Et Jésus répondant leur dit: je vous interrogerai aussi sur un article, et répondez-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Le Baptême de Jean était-il du ciel, ou des hommes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Or ils disputaient entre eux, disant: si nous disons: du ciel; il dira: pourquoi donc ne l’avez-vous point cru?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Et si nous disons: des hommes, tout le peuple nous lapidera; car ils sont persuadés que Jean était un Prophète;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'C’est pourquoi ils répondirent qu’ils ne savaient d’où il était.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'Et Jésus leur dit: je ne vous dirai point aussi par quelle autorité je fais ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Alors il se mit à dire au peuple cette parabole: Un homme planta une vigne, et la loua à des vignerons, et fut longtemps dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'Et dans la saison du fruit, il envoya un serviteur vers les vignerons, afin qu’ils lui donnassent du fruit de la vigne, mais les vignerons l’ayant battu, le renvoyèrent à vide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Il leur envoya encore un autre serviteur; mais ils le battirent aussi, et après l’avoir traité indignement, ils le renvoyèrent à vide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Il en envoya encore un troisième, mais ils le blessèrent aussi, et le jetèrent dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Alors le seigneur de la vigne dit: que ferai-je? j’y enverrai mon fils, le bien aimé; peut-être que quand ils le verront, ils le respecteront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Mais quand les vignerons le virent, ils raisonnèrent entre eux, en disant: celui-ci est l’héritier; venez, tuons-le, afin que l’héritage soit à nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'Et ils le jetèrent hors de la vigne, et le tuèrent. Que leur fera donc le maître de la vigne?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Il viendra, et fera périr ces vignerons-là, et il donnera la vigne à d’autres. Ce qu’eux ayant entendu, ils dirent: à Dieu ne plaise!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Alors il les regarda, et dit: que veut donc dire ce qui est écrit: la pierre que ceux qui bâtissent ont rejetée, est devenue la maîtresse pierre du coin?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Quiconque tombera sur cette pierre, sera brisé; et elle écrasera celui sur qui elle tombera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'Les principaux Sacrificateurs et les Scribes cherchèrent dans ce même instant à mettre les mains sur lui: car ils connurent bien qu’il avait dit cette parabole contre eux, mais ils craignirent le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Et l’observant ils envoyèrent des gens concertés, qui contrefaisaient les gens de bien, pour le surprendre en paroles, afin de le livrer à la domination et à la puissance du Gouverneur,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Lesquels l’interrogèrent, en disant: Maître, nous savons que tu parles et que tu enseignes conformément à la justice, et que tu ne regardes point à l’apparence des personnes, mais que tu enseignes la voie de Dieu en vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Nous est-il permis de payer le tribut à César, ou non?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Mais lui ayant aperçu leur ruse, leur dit: pourquoi me tentez-vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Montrez-moi un denier; de qui a-t-il l’image et l’inscription? ils lui répondirent: de César.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Et il leur dit: rendez donc à César les choses qui sont à César; et à Dieu les choses qui sont à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'Ainsi ils ne purent rien trouver à redire dans sa réponse en présence du peuple; mais tout étonnés de sa réponse, ils se turent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Alors quelques-uns des Sadducéens, qui nient formellement la résurrection, s’approchèrent, et l’interrogèrent,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'Disant: Maître, Moïse nous a laissé par écrit, que si le frère de quelqu’un est mort ayant une femme, et qu’il soit mort sans enfants, son frère prenne sa femme, et qu’il suscite des enfants à son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Or il y eut sept frères, dont l’aîné prit une femme, et mourut sans enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'Et le second la prit, et mourut aussi sans enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'Puis le troisième la prit, et de même tous les sept; et ils moururent sans avoir laissé des enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Et après tous la femme aussi mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Duquel d’eux donc sera-t-elle femme en la résurrection? car les sept l’ont eue pour femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Et Jésus répondant leur dit: les enfants de ce siècle prennent et sont pris en mariage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'Mais ceux qui seront faits dignes d’obtenir ce siècle-là et la résurrection des morts, ne prendront ni ne seront pris en mariage;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Car ils ne pourront plus mourir, parce qu’ils seront semblables aux Anges, et qu’ils seront fils de Dieu, étant fils de la résurrection.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Or que les morts ressuscitent, Moïse même l’a montré auprès du buisson, quand il appelle le Seigneur le Dieu d’Abraham, et le Dieu d’Isaac, et le Dieu de Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Or il n’est point le Dieu des morts, mais des vivants: car tous vivent en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Et quelques-uns des Scribes prenant la parole, dirent: Maître, tu as bien dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Et ils ne l’osèrent plus interroger de rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Mais lui leur dit: comment dit-on que le Christ est Fils de David.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'Car David lui-même dit au Livre des Psaumes: le Seigneur a dit à mon Seigneur: assieds-toi à ma droite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'Jusqu’à ce que j’aie mis tes ennemis pour le marchepied de tes pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'Puis donc que David l’appelle son Seigneur, comment, est-il son Fils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Et comme tout le peuple écoutait, il dit à ses Disciples:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, 'Donnez-vous garde des Scribes, qui se plaisent à se promener en robes longues, et qui aiment les salutations dans les marchés, et les premières chaires dans les Synagogues, et les premières places dans les festins;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'Et qui dévorent entièrement les maisons des veuves, même sous prétexte de faire de longues prières; car ils en recevront une plus grande condamnation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Et comme Jésus regardait, il vit des riches qui mettaient leurs dons au tronc.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Il vit aussi une pauvre veuve qui y mettait deux petites pièces de monnaie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'Et il dit: certes je vous dis, que cette pauvre veuve a plus mis que tous les autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Car tous ceux-ci ont mis aux offrandes de Dieu, de leur superflu; mais celle-ci y a mis de sa disette tout ce qu’elle avait pour vivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Et comme quelques-uns disaient du Temple, qu’il était orné de belles pierres, et de dons, il dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'Est-ce cela que vous regardez? les jours viendront qu’il n’y sera laissé pierre sur pierre qui ne soit démolie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Et ils l’interrogèrent, en disant: Maître, quand sera-ce donc que ces choses arriveront? et quel signe y aura-t-il quand ces choses devront arriver?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Et il dit: prenez garde que vous ne soyez point séduits; car plusieurs viendront en mon Nom, disant: c’est moi qui suis le Christ; et même le temps approche; n’allez donc point après eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Et quand vous entendrez des guerres et des séditions, ne vous épouvantez point; car il faut que ces choses arrivent premièrement, mais la fin ne sera pas tout aussitôt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Alors il leur dit: une nation s’élèvera contre une autre nation, et un royaume contre un autre royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'Et il y aura de grands tremblements de terre en tous lieux, et des famines, et des pestes, et des épouvantements, et de grands signes du ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Mais avant toutes ces choses ils mettront les mains sur vous, et vous persécuteront, vous livrant aux Synagogues, et vous mettant en prison; et ils vous mèneront devant les Rois et les Gouverneurs, à cause de mon Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Et cela vous sera pour témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Mettez donc en vos coeurs de ne préméditer point comment vous aurez à répondre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'Car je vous donnerai une bouche et une sagesse, à laquelle tous ceux qui vous seront contraires, ne pourront contredire, ni résister.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Vous serez aussi livrés par vos pères et par vos mères, et par vos frères, et par vos parents, et par vos amis; et ils en feront mourir plusieurs d’entre vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'Et vous serez haïs de tous à cause de mon Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Mais un cheveu de votre tête ne sera point perdu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'Possédez vos âmes par votre patience.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Et quand vous verrez Jérusalem être environnée d’armées, sachez alors que sa désolation est proche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Alors que ceux qui sont en Judée, s’enfuient aux montagnes; et que ceux qui sont dans Jérusalem, s’en retirent; et que ceux qui sont aux champs, n’entrent point en elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Car ce seront là les jours de la vengeance, afin que toutes les choses qui sont écrites soient accomplies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Or malheur à celles qui seront enceintes, et à celles qui allaiteront en ces jours-là; car il y aura une grande calamité sur le pays, et une grande colère contre ce peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'Et ils tomberont sous le tranchant de l’épée, et seront menés captifs dans toutes les nations; et Jérusalem sera foulée par les Gentils, jusqu’à ce que les temps des Gentils soient accomplis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'Et il y aura des signes dans le soleil et dans la lune, et dans les étoiles, et une telle détresse des nations, qu’on ne saura que devenir sur la terre, la mer bruyant et les ondes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'De sorte que les hommes seront comme rendant l’âme de peur, et à cause de l’attente dès choses qui surviendront dans toute la terre; car les vertus des cieux seront ébranlées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Et alors on verra le Fils de l’homme venant sur une nuée avec puissance et grande gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Or quand ces choses commenceront d’arriver, regardez en haut, et levez vos têtes, parce que votre délivrance approche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'Et il leur proposa cette comparaison: voyez le figuier et tous les autres arbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'Quand ils commencent à pousser, vous connaissez de vous-mêmes, en regardant, que l’été est déjà près.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Vous aussi de même, quand vous verrez arriver ces choses, sachez que le Règne de Dieu est près.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'En vérité je vous dis, que cette génération ne passera point, que toutes ces choses ne soient arrivées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Le ciel et la terre passeront, mais mes paroles ne passeront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Prenez donc garde à vous-mêmes, de peur que vos coeurs ne soient appesantis par la gourmandise et l’ivrognerie, et par les soucis de cette vie; et que ce jour-là ne vous surprenne subitement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'Car il surprendra comme un filet tous ceux qui habitent sur le dessus de toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Veillez donc, priant en tout temps, afin que vous soyez faits dignes d’éviter toutes ces choses qui doivent arriver; et afin que vous puissiez subsister devant le Fils de l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Or il enseignait le jour dans le Temple; et il sortait et demeurait la nuit dans la montagne qui est appelée des oliviers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'Et dès le point du jour, tout le peuple venait vers lui au Temple pour l’entendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Or la fête des pains sans levain, qu’on appelle Pâque, approchait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Et les principaux Sacrificateurs et les Scribes cherchaient comment ils le pourraient faire mourir: car ils craignaient le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Mais satan entra dans Judas, surnommé Iscariot, qui était du nombre des douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'Lequel s’en alla, et parla avec les principaux Sacrificateurs et les Capitaines, de la manière dont il le leur livrerait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Et ils en furent joyeux, et convinrent qu’ils lui donneraient de l’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Et il le leur promit; et il cherchait le temps propre pour le leur livrer sans tumulte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Or le jour des pains sans levain, auquel il fallait sacrifier l’ Agneau de Pâque, arriva.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Et Jésus envoya Pierre et Jean, en leur disant: allez, et apprêtez-nous l’ Agneau de Pâque, afin que nous le mangions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Et ils lui dirent: où veux-tu que nous l’apprêtions?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Et il leur dit: voici, quand vous serez entrés dans la ville vous rencontrerez un homme portant une cruche d’eau, suivez-le en la maison où il entrera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'Et dites au maître de la maison: le Maître t’envoie dire: où est le logis où je mangerai l’ Agneau de Pâque avec mes Disciples?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Et il vous montrera une grande chambre haute, parée; apprêtez là l’ Agneau de Pâque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'S’en étant donc allés, ils trouvèrent tout comme il leur avait dit; et ils apprêtèrent l’ Agneau de Pâque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Et quand l’heure fut venue, il se mit à table, et les douze Apôtres avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Et il leur dit: j’ai fort désiré de manger cet Agneau de Pâque avec vous avant que je souffre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Car je vous dis, que je n’en mangerai plus jusqu’à ce qu’il soit accompli dans le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Et ayant pris la coupe, il rendit grâces, et il dit: prenez-la, et la distribuez entre vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Car je vous dis, que je ne boirai plus du fruit de la vigne, jusqu’à ce que le Règne de Dieu soit venu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Puis prenant le pain, et ayant rendu grâces, il le rompit et le leur donna, en disant: ceci est mon corps, qui est donné pour vous; faites ceci en mémoire de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'De même aussi il leur donna la coupe, après le souper, en disant: cette coupe est le Nouveau Testament en mon sang, qui est répandu pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Cependant voici, la main de celui qui me trahit est avec moi à table.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Et certes le Fils de l’homme s’en va; selon ce qui est déterminé; toutefois malheur à cet homme par qui il est trahi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Alors ils se mirent à s’entredemander l’un à l’autre, qui serait celui d’entre eux à qui il arriverait de commettre cette action.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Il arriva aussi une contestation entre eux, pour savoir lequel d’entre eux serait estimé le plus grand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Mais il leur dit: Les Rois des nations les maîtrisent; et ceux qui usent d’autorité sur elles sont nommés bienfaiteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Mais il n’en sera pas ainsi de vous: au contraire, que le plus grand entre vous soit comme le moindre; et celui qui gouverne, comme celui qui sert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Car lequel est le plus grand, celui qui est à table, ou celui qui sert? N’est-ce pas celui qui est à table? Or je suis au milieu de vous comme celui qui sert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Or vous êtes ceux qui avez persévéré avec moi dans mes tentations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'C’est pourquoi je vous confie le Royaume comme mon Père me l’a confié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'Afin que vous mangiez et que vous buviez à ma table dans mon Royaume; et que vous soyez assis sur des trônes jugeant les douze Tribus d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Le Seigneur dit aussi: Simon, Simon, voici, satan a demandé instamment à vous cribler comme le blé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Mais j’ai prié pour toi que ta foi ne défaille point; toi donc, quand tu seras un jour converti, fortifie tes frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'Et Pierre lui dit: Seigneur, je suis tout prêt d’aller avec toi, soit en prison soit à la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Mais Jésus lui dit: Pierre, je te dis que le coq ne chantera point aujourd’hui, que premièrement tu ne renies par trois fois de m’avoir connu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'Puis il leur dit: quand je vous ai envoyés sans bourse, sans sac, et sans souliers, avez-vous manqué de quelque chose? Ils répondirent: de rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Et il leur dit: mais maintenant que celui qui a une bourse la prenne, et de même celui qui a un sac; et que celui qui n’a point d’épée vende sa robe, et achète une épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Car je vous dis, qu’il faut que ceci aussi qui est écrit, soit accompli en moi: et il a été mis au rang des iniques. Car certainement les choses qui ont été prédites de moi, s’en vont être accomplies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Et ils dirent: Seigneur, voici deux épées. Et il leur dit: c’est assez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Puis il partit, et s’en alla, selon sa coutume, au mont des oliviers; et ses Disciples le suivirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Et quand il fut arrivé en ce lieu-là, il leur dit: Priez que vous n’entriez point en tentation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Puis s’étant éloigné d’eux environ d’un jet de pierre, et s’étant mis à genoux, il priait,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'Disant: Père, si tu voulais transporter cette coupe loin de moi; toutefois que ma volonté ne soit point faite, mais la tienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Et un Ange lui apparut du ciel, le fortifiant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'Et lui étant en agonie, priait plus instamment, et sa sueur devint comme des grumeaux de sang découlant en terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'Puis s’étant levé de sa prière, il revint à ses Disciples, lesquels il trouva dormant de tristesse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'Et il leur dit: pourquoi dormez-vous? levez-vous, et priez que vous n’entriez point en tentation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Et comme il parlait encore, voici une troupe, et celui qui avait nom Judas, l’un des douze, vint devant eux, et s’approcha de Jésus pour le baiser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Et Jésus lui dit: Judas, trahis-tu le Fils de l’homme par un baiser?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Alors ceux qui étaient autour de lui, voyant ce qui allait arriver, lui dirent: Seigneur, frapperons-nous de l’épée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'Et l’un d’eux frappa le serviteur du souverain Sacrificateur, et lui emporta l’oreille droite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Mais Jésus prenant la parole dit: laissez -les faire jusques ici. Et lui ayant touché l’oreille, il le guérit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Puis Jésus dit aux principaux Sacrificateurs, et aux Capitaines du Temple, et aux Anciens qui étaient venus contre lui: êtes-vous venus comme après un brigand avec des épées et des bâtons?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Quoique j’aie été tous les jours avec vous au Temple, vous n’avez pas mis la main sur moi; mais c’est ici votre heure, et la puissance des ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Se saisissant donc de lui, ils l’emmenèrent, et le firent entrer dans la maison du souverain Sacrificateur; et Pierre suivait de loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Or ces gens ayant allumé du feu au milieu de la cour, et s’étant assis ensemble, Pierre s’assit aussi parmi eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Et une servante le voyant assis auprès du feu, et ayant l’œil arrêté sur lui, dit: celui-ci aussi était avec lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Mais il le nia, disant: femme, je ne le connais point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Et un peu après, un autre le voyant, dit: tu es aussi de ces gens-là, mais Pierre dit: ô homme! je n’en suis point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Et environ l’espace d’une heure après, quelque autre affirmait, et disait: certainement celui-ci aussi était avec lui: car il est Galiléen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Et Pierre dit: ô homme! je ne sais ce que tu dis. Et dans ce moment, comme il parlait encore, le coq chanta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'Et le Seigneur se tournant, regarda Pierre; et Pierre se ressouvint de la parole du Seigneur, qui lui avait dit: avant que le coq chante, tu me renieras trois fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'Alors Pierre étant sorti dehors, pleura amèrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Or ceux qui tenaient Jésus, se moquaient de lui, et le frappaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'Et lui ayant bandé les yeux, ils lui donnaient des coups sur le visage, et l’interrogeaient, disant: devine qui est celui qui t’a frappé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Et ils disaient plusieurs autres choses contre lui, en l’outrageant de paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Et quand le jour fut venu, les Anciens du peuple, et les principaux Sacrificateurs, et les Scribes, s’assemblèrent, et l’emmenèrent dans le conseil;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'Et lui dirent: si tu es le Christ, dis-le-nous. Et il leur répondit: si je vous le dis, vous ne le croirez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'Que si aussi je vous interroge, vous ne me répondrez point, et vous ne me laisserez point aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Désormais le Fils de l’homme sera assis à la droite de la puissance de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Alors ils dirent tous: es-tu donc le Fils de Dieu? Il leur dit: vous le dites vous-mêmes que je le suis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Et ils dirent: qu’avons-nous besoin encore de témoignage? car nous-mêmes nous l’avons ouï de sa bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Puis ils se levèrent tous et le menèrent à Pilate.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'Et ils se mirent à l’accuser, disant: nous avons trouvé cet homme sollicitant la nation à la révolte, et défendant de donner le tribut à César, et se disant être le Christ, le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Et Pilate l’interrogea, disant: ss-tu le Roi des Juifs? Et Jésus répondant, lui dit: tu le dis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Alors Pilate dit aux principaux Sacrificateurs et à la troupe du peuple: je ne trouve aucun crime en cet homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Mais ils insistaient encore davantage, disant: il émeut le peuple, enseignant par toute la Judée, et ayant commencé depuis la Galilée jusques ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Or quand Pilate entendit parler de la Galilée, il demanda si cet homme était Galiléen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'Et ayant appris qu’il était de la juridiction d’Hérode, il le renvoya à Hérode, qui en ces jours-là était aussi à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Et lorsque Hérode vit Jésus, il en fut fort joyeux, car il y avait longtemps qu’il désirait de le voir, à cause qu’il entendait dire plusieurs choses de lui, et il espérait qu’il lui verrait faire quelque miracle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Il l’interrogea donc par divers discours; mais Jésus ne lui répondit rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Et les principaux Sacrificateurs et les Scribes comparurent, l’accusant avec une grande véhémence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Mais Hérode avec ses gens l’ayant méprisé, et s’étant moqué de lui, après qu’il l’eut revêtu d’un vêtement blanc, le renvoya à Pilate.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'Et en ce même jour Pilate et Hérode devinrent amis entre eux; car auparavant ils étaient ennemis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Alors Pilate ayant appelé les principaux Sacrificateurs, et les Gouverneurs, et le peuple, il leur dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'Vous m’avez présenté cet homme comme soulevant le peuple; et voici, l’en ayant fait répondre devant vous, je n’ai trouvé en cet homme aucun de ces crimes dont vous l’accusez;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Ni Hérode non plus; car je vous ai renvoyés à lui, et voici, rien ne lui a été fait qui marque qu’il soit digne de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Quand donc je l’aurai fait fouetter, je le relâcherai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'Or il fallait qu’il leur relâchât quelqu’un à la fête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Et toutes les troupes s’écrièrent ensemble, disant: ôte celui-ci, et relâche-nous Barabbas;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Qui avait été mis en prison pour quelque sédition faite dans la ville, avec meurtre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Pilate donc leur parla encore, voulant relâcher Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Mais ils s’écriaient, disant: crucifie, Crucifie-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Et il leur dit pour la troisième fois, mais quel mal a fait cet homme? je ne trouve rien en lui qui soit digne de mort; l’ayant donc fait fouetter, je le relâcherai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Mais ils insistaient à grands cris, demandant qu’il fût crucifié; et leurs cris et ceux des principaux Sacrificateurs se renforçaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Alors Pilate prononça que ce qu’ils demandaient, fût fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'Et il leur relâcha celui qui pour sédition et pour meurtre avait été mis en prison, et lequel ils demandaient; et il abandonna Jésus à leur volonté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Et comme ils l’emmenaient, ils prirent un certain Simon, Cyrénien, qui venait des champs, et le chargèrent de la croix pour la porter après Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Or il était suivi d’une grande multitude de peuple et de femmes, qui se frappaient la poitrine, et le pleuraient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Mais Jésus se tournant vers elles, leur dit: filles de Jérusalem, ne pleurez point sur moi, mais pleurez sur vous-mêmes, et sur vos enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Car voici, les jours viendront auxquels on dira: bienheureuses sont les stériles, et celles qui n’ont point eu d’enfant, et les mamelles qui n’ont point nourri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Alors ils se mettront à dire aux montagnes: tombez sur nous; et aux côteaux: couvrez-nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Car s’ils font ces choses au bois vert, que sera-t-il fait au bois sec?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Deux autres aussi qui étaient des malfaiteurs, furent menés pour les faire mourir avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Et quand ils furent venus au lieu qui est appelé le Test, ils le crucifièrent là, et les malfaiteurs aussi, l’un à la droite, et l’autre à la gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Mais Jésus disait: Père, pardonne-leur, car ils ne savent ce qu’ils font. Ils firent ensuite le partage de ses vêtements, et ils les jetèrent au sort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Et le peuple se tenait là regardant; et les Gouverneurs aussi se moquaient de lui avec eux, disant: il a sauvé les autres, qu’il se sauve lui-même, s’il est le Christ, l’élu de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Les soldats aussi se moquaient de lui, s’approchant, et lui présentant du vinaigre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'Et disant: si tu es le Roi des Juifs, sauve-toi toi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Or il y avait au-dessus de lui un écriteau en lettres Grecques, et Romaines, et Hébraïques, en ces mots: CELUI-CI EST LE ROI DES JUIFS.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Et l’un des malfaiteurs qui étaient pendus, l’outrageait, disant: si tu es le Christ, sauve-toi toi-même, et nous aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Mais l’autre prenant la parole le censurait fortement, disant: au moins ne crains-tu point Dieu, puisque tu es dans la même condamnation?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Et pour nous, nous y sommes justement: car nous recevons des choses dignes de nos crimes, mais celui-ci n’a rien fait qui ne se dût faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Puis il disait à Jésus: Seigneur! souviens-toi de moi quand tu viendras en ton Règne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Et Jésus lui dit: en vérité je te dis, qu’aujourd’hui tu seras avec moi en paradis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Or il était environ six heures, et il se fit des ténèbres par tout le pays jusqu’à neuf heures;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'Et le soleil fut obscurci, et le voile du Temple se déchira par le milieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'Et Jésus criant à haute voix, dit: Père, je remets mon esprit entre tes mains! Et ayant dit cela, il rendit l’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Or le Centenier voyant ce qui était arrivé, glorifia Dieu, disant: certes cet homme était juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Et toutes les troupes qui s’étaient assemblées à ce spectacle, voyant les choses qui étaient arrivées, s’en retournaient frappant leurs poitrines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Et tous ceux de sa connaissance, et les femmes qui l’avaient suivi de Galilée, se tenaient loin, regardant ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Et voici un personnage appelé Joseph, Conseiller, homme de bien, et juste,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'Qui n’avait point consenti à leur résolution, ni à leur action, lequel était d’Arimathée ville des Juifs, et qui aussi attendait le Règne de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Etant venu à Pilate, lui demanda le corps de Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'Et l’ayant descendu de la croix, il l’enveloppa dans un linceul, et le mit en un sépulcre taillé dans le roc, où personne n’avait encore été mis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'Or c’était le jour de la préparation, et le jour du Sabbat allait commencer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Et les femmes qui étaient venues de Galilée avec Jésus, ayant suivi Joseph, regardèrent le sépulcre, et comment le corps de Jésus y était mis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Puis s’en étant retournées, elles préparèrent des drogues aromatiques et des parfums; et le jour du Sabbat elles se reposèrent selon le commandement de la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Mais le premier jour de la semaine, comme il était encore fort matin, elles vinrent au sépulcre, et quelques autres avec elles, apportant les aromates, qu’elles avaient préparés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Et elles trouvèrent la pierre roulée à côté du sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'Et étant entrées, elles ne trouvèrent point le corps du Seigneur Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'Et il arriva que comme elles étaient en grande perplexité touchant cela, voici, deux personnages parurent devant elles en vêtements tout couverts de lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'Et comme elles étaient toutes épouvantées, et baissaient le visage en terre, ils leur dirent: pourquoi cherchez-vous parmi les morts celui qui est vivant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Il n’est point ici, mais il est ressuscité; qu’il vous souvienne comment il vous parla quand il était encore en Galilée,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'Disant: qu’il fallait que le Fils de l’homme fût livré entre les mains des pécheurs, et qu’il fût crucifié; et qu’il ressuscitât le troisième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'Et elles se souvinrent de ses paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'Puis s’en étant retournées du sépulcre, elles annoncèrent toutes ces choses aux onze Disciples, et à tous les autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Or ce fut Marie-Magdeleine, et Jeanne, et Marie mère de Jacques, et les autres qui étaient avec elles, qui dirent ces choses aux Apôtres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Mais les paroles de ces femmes leur semblèrent comme des rêveries, et ils ne les crurent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Néanmoins Pierre s’étant levé, courut au sépulcre, et s’étant courbé pour regarder, il ne vit que les linceuls mis à côté; puis il partit, admirant en lui-même ce qui était arrivé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Or voici, deux d’entre eux étaient ce jour-là en chemin, pour aller à une bourgade nommée Emmaüs, qui était loin de Jérusalem, environ soixante stades.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'Et ils s’entretenaient ensemble de toutes ces choses qui étaient arrivées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Et il arriva que comme ils parlaient et conféraient entre eux, Jésus lui- même s’étant approché, se mit à marcher avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Mais leurs yeux étaient retenus de sorte qu’ils ne le reconnaissaient pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Et il leur dit: quels sont ces discours que vous tenez entre vous en marchant? et pourquoi êtes-vous tout tristes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Et l’un d’eux, qui avait nom Cléopas, répondit, et lui dit: es-tu seul étranger dans Jérusalem, qui ne saches point les choses qui y sont arrivées ces jours-ci?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'Et il leur dit: quelles? ils répondirent: c’est touchant Jésus le Nazarien, qui était un Prophète, puissant en oeuvres et en paroles devant Dieu, et devant tout le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'Et comment les principaux Sacrificateurs et nos Gouverneurs l’ont livré pour être condamné à mort, et l’ont crucifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Or nous espérions que ce serait lui qui délivrerait Israël; mais avec tout cela, c’est aujourd’hui le troisième jour que ces choses sont arrivées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Toutefois quelques femmes d’entre nous nous ont fort étonnés, car elles ont été de grand matin au sépulcre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'Et n’ayant point trouvé son corps, elles sont revenues, en disant que même elles avaient vu une apparition d’Anges, qui disaient qu’il est vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Et quelques-uns des nôtres sont allés au sépulcre, et ont trouvé ainsi que les femmes avaient dit; mais pour lui, ils ne l’ont point vu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Alors il leur dit: ô gens dépourvus de sens, et tardifs de coeur à croire toutes les choses que les Prophètes ont prononcées!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Ne fallait-il pas que le Christ souffrît ces choses, et qu’il entrât en sa gloire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'Puis commençant par Moïse, et continuant par tous les Prophètes, il leur expliquait dans toutes les Ecritures les choses qui le regardaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Et comme ils furent près de la bourgade où ils allaient, il faisait semblant d’aller plus loin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Mais ils le forcèrent, en lui disant: demeure avec nous, car le soir approche, et le jour commence à baisser. Il entra donc pour demeurer avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'Et il arriva que comme il était à table avec eux, il prit le pain, et il le bénit; et l’ayant rompu, il le leur distribua.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Alors leurs yeux furent ouverts, en sorte qu’ils le reconnurent; mais il disparut de devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'Et ils dirent entre eux: notre coeur ne brûlait-il pas au-dedans de nous, lorsqu’il nous parlait par le chemin, et qu’il nous expliquait les Ecritures?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'Et se levant dans ce moment, ils s’en retournèrent à Jérusalem, où ils trouvèrent les onze assemblés, et ceux qui étaient avec eux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'Qui disaient: le Seigneur est véritablement ressuscité, et il est apparu à Simon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Et ceux-ci aussi racontèrent les choses qui leur étaient arrivées en chemin, et comment il avait été reconnu d’eux en rompant le pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Et comme ils tenaient ces discours, Jésus se présenta lui-même au milieu d’eux, et leur dit: que la paix soit avec vous!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Mais eux tout troublés et épouvantés croyaient voir un esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Et il leur dit: pourquoi vous troublez-vous, et pourquoi monte-t-il des pensées dans vos coeurs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Voyez mes mains et mes pieds; car c’est moi-même: touchez-moi, et me considérez bien; car un esprit n’a ni chair ni os, comme vous voyez que j’ai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'Et en disant cela, il leur montra ses mains et ses pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Mais comme encore de joie ils ne croyaient point, et qu’ils s’étonnaient, il leur dit: avez-vous ici quelque chose à manger?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Et ils lui présentèrent une pièce de poisson rôti, et d’un rayon de miel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Et l’ayant pris, il mangea devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Puis il leur dit: ce sont ici les discours que je vous tenais quand j’étais encore avec vous: qu’il fallait que toutes les choses qui sont écrites de moi dans la Loi de Moïse, et dans les Prophètes, et dans les Psaumes, fussent accomplies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Alors il leur ouvrit l’esprit pour entendre les Ecritures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'Et il leur dit: il est ainsi écrit, et ainsi il fallait que le Christ souffrît, et qu’il ressuscitât des morts le troisième jour;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'Et qu’on prêchât en son Nom la repentance et la rémission des péchés parmi toutes les nations, en commençant par Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Et vous êtes témoins de ces choses; et voici, je m’en vais envoyer sur vous la promesse de mon Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'Vous donc demeurez dans la ville de Jérusalem, jusqu’à ce que vous soyez revêtus de la vertu d’en haut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Après quoi il les mena dehors jusqu’en Béthanie, et levant ses mains en haut, il les bénit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Et il arriva qu’en les bénissant, il se sépara d’eux, et fut élevé au ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'Et eux l’ayant adoré, s’en retournèrent à Jérusalem avec une grande joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'Et ils étaient toujours dans le Temple, louant et bénissant Dieu. Amen! ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Au commencement était la Parole, et la Parole était avec Dieu; et cette parole était Dieu:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Elle était au commencement avec Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Toutes choses ont été faites par elle, et sans elle rien de ce qui a été fait, n’a été fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'En elle était la vie, et la vie était la Lumière des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Et la Lumière luit dans les ténèbres, mais les ténèbres ne l’ont point reçue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Il y eut un homme appelé Jean, qui fut envoyé de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Il vint pour rendre témoignage, pour rendre, dis-je, témoignage à la Lumière, afin que tous crûssent par lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Il n’était pas la Lumière, mais il était envoyé pour rendre témoignage à la Lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Cette Lumière était la véritable, qui éclaire tout homme venant au monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Elle était au monde, et le monde a été fait par elle; mais le monde ne l’a point connue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Il est venu chez soi; et les siens ne l’ont point reçu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Mais à tous ceux qui l’ont reçu, il leur a donné le droit d’être faits enfants de Dieu, savoir à ceux qui croient en son Nom;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Lesquels ne sont point nés de sang, ni de la volonté de la chair, ni de la volonté de l’homme; mais ils sont nés de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Et la Parole a été faite chair, elle a habité parmi nous, et nous avons contemplé sa gloire, qui a été une gloire, comme la gloire du Fils unique du Père, pleine de grâce et de vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Jean a donc rendu témoignage de lui, et a crié, disant: c’est celui duquel je disais: celui qui vient après moi m’est préféré, car il était avant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Et nous avons tous reçu de sa plénitude, et grâce pour grâce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Car la Loi a été donnée par Moïse; la grâce et la vérité est venue par Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Personne ne vit jamais Dieu; le Fils unique qui est au sein du Père, est celui qui nous l’a révélé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Et c’est ici le témoignage de Jean, lorsque les Juifs envoyèrent de Jérusalem des Sacrificateurs et des Lévites pour l’interroger, et lui dire: toi qui es-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Car il l’avoua, et ne le nia point, il l’avoua, dis-je, en disant: ce n’est pas moi qui suis le Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Sur quoi ils lui demandèrent: qui es-tu donc? Es-tu Elie? Et il dit: je ne le suis point. Es-tu le Prophète? Et il répondit: non.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Ils lui dirent donc: qui es-tu, afin que nous donnions réponse à ceux qui nous ont envoyés; que dis-tu de toi-même?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Il dit: je suis la voix de celui qui crie dans le désert: aplanissez le chemin du Seigneur, comme a dit Esaïe le Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Or ceux qui avaient été envoyés vers lui étaient d’entre les Pharisiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'Ils l’interrogèrent encore, et lui dirent: pourquoi donc baptises-tu si tu n’es point le Christ, ni Elie, ni le Prophète?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Jean leur répondit, et leur dit: pour moi, je baptise d’eau; mais il y en a un au milieu de vous, que vous ne connaissez point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'C’est celui qui vient après moi, qui m’est préféré, et duquel je ne suis pas digne de délier la courroie du soulier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Ces choses arrivèrent à Bethabara, au-delà du Jourdain, où Jean baptisait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Le lendemain Jean vit Jésus venir à lui, et il dit: voilà l’Agneau de Dieu, qui ôte le péché du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'C’est celui duquel je disais: après moi vient un personnage qui m’est préféré; car il était avant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Et pour moi, je ne le connaissais point; mais afin qu’il soit manifesté à Israël, je suis venu à cause de cela baptiser d’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'Jean rendit aussi témoignage, en disant: j’ai vu l’Esprit descendre du ciel comme une colombe, et s’arrêter sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Et pour moi, je ne le connaissais point; mais celui qui m’a envoyé baptiser d’eau, m’avait dit: celui sur qui tu verras l’Esprit descendre, et se fixer sur lui, c’est celui qui baptise du Saint-Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Et je l’ai vu, et j’ai rendu témoignage, que c’est lui qui est le Fils de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Le lendemain encore Jean s’arrêta, et avec lui deux de ses disciples;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'Et regardant Jésus qui marchait, il dit: voilà l’Agneau de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Et les deux disciples l’entendirent tenant ce discours, et ils suivirent Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Et Jésus se retournant, et voyant qu’ils le suivaient, il leur dit: que cherchez-vous? Ils lui répondirent: Rabbi, c’est-à-dire, Maître, où demeures-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Il leur dit: venez, et le voyez. Ils y allèrent, et ils virent où il demeurait; et ils demeurèrent avec lui ce jour-là; car il était environ dix heures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Or André, frère de Simon Pierre, était l’un des deux qui en avaient ouï parler à Jean, et qui l’avaient suivi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Celui-ci trouva le premier Simon son frère, et il lui dit: nous avons trouvé le Messie; c’est-à-dire, le Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Et il le mena vers Jésus, et Jésus ayant jeté la vue sur lui, dit: tu es Simon, fils de Jonas, tu seras appelé Céphas; c’est-à-dire, Pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Le lendemain Jésus voulut aller en Galilée, et il trouva Philippe, auquel il dit: suis-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Or Philippe était de Bethsaïda, la ville d’André et de Pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Philippe trouva Nathanaël, et lui dit: nous avons trouvé Jésus, qui est de Nazareth, fils de Joseph, celui duquel Moïse a écrit dans la Loi, et duquel aussi les Prophètes ont écrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Et Nathanaël lui dit: peut-il venir quelque chose de bon de Nazareth? Philippe lui dit: viens, et vois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jésus aperçut Nathanaël venir vers lui, et il dit de lui: voici vraiment un Israëlite en qui il n’y a point de fraude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Nathanaël lui dit: d’où me connais-tu? Jésus répondit, et lui dit: avant que Philippe t’eût appelé quand tu étais sous le figuier, je te voyais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Nathanaël répondit, et lui dit: Maître, tu es le Fils de Dieu; tu es le Roi d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jésus répondit, et lui dit: parce que je t’ai dit que je te voyais sous le figuier, tu crois; tu verras bien de plus grandes choses que ceci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Il lui dit aussi: en vérité, en vérité je vous dis: désormais vous verrez le ciel ouvert, et les Anges de Dieu montant et descendant sur le Fils de l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Or trois jours après on faisait des noces à Cana de Galilée, et la mère de Jésus était là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Et Jésus fut aussi convié aux noces, avec ses Disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Et le vin étant venu à manquer, la mère de Jésus lui dit: ils n’ont point de vin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Mais Jésus lui répondit: qu’y a-t-il entre moi et toi, femme? mon heure n’est point encore venue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Sa mère dit aux serviteurs: faites tout ce qu’il vous dira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Or il y avait là six vaisseaux de pierre, mis selon l’usage de la purification des Juifs, dont chacun tenait deux ou trois mesures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Et Jésus leur dit: emplissez d’eau ces vaisseaux. Et ils les emplirent jusques au haut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Puis il leur dit: versez-en maintenant, et portez-en au maître d’hôtel. Et ils lui en portèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Quand le maître d’hôtel eut goûté l’eau qui avait été changée en vin, (or il ne savait pas d’où cela venait, mais les serviteurs qui avaient puisé l’eau, le savaient bien,) il s’adressa à l’époux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'Et lui dit: tout homme sert le bon vin le premier, et puis le moindre après qu’on a bu plus largement; mais toi, tu as gardé le bon vin jusqu’à maintenant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Jésus fit ce premier miracle à Cana de Galilée, et il manifesta sa gloire, et ses Disciples crurent en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Après cela il descendit à Capernaüm avec sa mère, et ses frères, et ses Disciples; mais ils y demeurèrent peu de jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Car la Pâque des Juifs était proche; c’est pourquoi Jésus monta à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Et il trouva dans le Temple des gens qui vendaient des boeufs, et des brebis, et des pigeons; et les changeurs qui y étaient assis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Et ayant fait un fouet avec de petites cordes, il les chassa tous du Temple, avec les brebis, et les boeufs; et il répandit la monnaie des changeurs, et renversa les tables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Et il dit à ceux qui vendaient des pigeons: ôtez ces choses d’ici, et ne faites pas de la Maison de mon Père un lieu de marché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Alors ses Disciples se souvinrent qu’il était écrit: le zèle de ta Maison m’a rongé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Mais les Juifs prenant la parole, lui dirent: quel miracle nous montres-tu, pour entreprendre de faire de telles choses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Jésus répondit, et leur dit: abattez ce Temple, et en trois jours je le relèverai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Et les Juifs dirent: on a été quarante-six ans à bâtir ce Temple, et tu le relèveras dans trois jours!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Mais il parlait du Temple, de son corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'C’est pourquoi lorsqu’il fut ressuscité des morts, ses Disciples se souvinrent qu’il leur avait dit cela, et ils crurent à l’Ecriture, et à la parole que Jésus avait dite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Et comme il était à Jérusalem le jour de la fête de Pâque, plusieurs crurent en son Nom, contemplant les miracles qu’il faisait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Mais Jésus ne se fiait point à eux, parce qu’il les connaissait tous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'Et qu’il n’avait pas besoin que personne lui rendit témoignage d’ aucun homme; car lui-même savait ce qui était dans l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Or il y avait un homme d’entre les Pharisiens, nommé Nicodème, qui était un des principaux d’entre les Juifs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Lequel vint de nuit à Jésus, et lui dit: Maître, nous savons que tu es un Docteur venu de Dieu: car personne ne peut faire les miracles que tu fais, si Dieu n’est avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jésus répondit, et lui dit: en vérité, en vérité je te dis: si quelqu’un n’est né de nouveau, il ne peut point voir le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nicodème lui dit: comment peut naître un homme quand il est vieux? peut-il rentrer dans le sein de sa mère, et naître une seconde fois?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jésus répondit: en vérité, en vérité je te dis: si quelqu’un n’est né d’eau et d’esprit, il ne peut point entrer dans le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Ce qui est né de la chair, est chair; et ce qui est né de l’Esprit, est esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Ne t’étonne pas de ce que je t’ai dit: il vous faut être nés de nouveau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Le vent souffle où il veut, et tu en entends le son; mais tu ne sais d’où il vient, ni où il va: il en est ainsi de tout homme qui est né de l’Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nicodème répondit, et lui dit: comment se peuvent faire ces choses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jésus répondit, et lui dit: tu es Docteur d’Israël, et tu ne connais point ces choses!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'En vérité, en vérité je te dis: que ce que nous savons, nous le disons; et ce que nous avons vu, nous le témoignons; mais vous ne recevez point notre témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Si je vous ai dit ces choses terrestres, et vous ne les croyez point, comment croirez-vous si je vous dis des choses célestes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Car personne n’est monté au ciel, sinon celui qui est descendu du ciel, savoir le Fils de l’homme qui est au ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Or comme Moïse éleva le serpent au désert, ainsi il faut que le Fils de l’homme soit élevé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'Afin que quiconque croit en lui ne périsse point, mais qu’il ait la vie éternelle,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Car Dieu a tant aimé le monde, qu’il a donné son Fils unique, afin que quiconque croit en lui ne périsse point, mais qu’il ait la vie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Car Dieu n’a point envoyé son Fils au monde pour condamner le monde, mais afin que le monde soit sauvé par lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Celui qui croit en lui ne sera point condamné; mais celui qui ne croit point est déjà condamné; parce qu’il n’a point crut au Nom du Fils unique de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Or c’est ici le sujet de la condamnation, que la lumière est venue au monde, et que les hommes ont mieux aimé les ténèbres que la lumière, parce que leurs oeuvres étaient mauvaises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Car quiconque s’adonne à des choses mauvaises, hait la lumière, et ne vient point à la lumière, de peur que ses oeuvres ne soient censurées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Mais celui qui s’adonne à la vérité, vient à la lumière, afin que ses oeuvres soient manifestées, parce qu’elles sont faites selon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Après ces choses Jésus vint avec ses Disciples au pays de Judée; et il demeurait là avec eux, et baptisait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Or Jean baptisait aussi en Enon, près de Salim, parce qu’il y avait là beaucoup d’eau; et on venait là, et on y était baptisé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Car Jean n’avait pas encore été mis en prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Or il y eut une question mue par les disciples de Jean avec les Juifs, touchant la purification.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Et ils vinrent à Jean, et lui dirent: Maître, celui qui était avec toi au-delà du Jourdain, et à qui tu as rendu témoignage, voilà, il baptise, et tous viennent à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Jean répondit, et dit: l’homme ne peut recevoir aucune chose, si elle ne lui est donnée du ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Vous-mêmes m’êtes témoins que j’ai dit: ce n’est pas moi qui suis le Christ, mais je suis envoyé devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Celui qui possède l’Epouse est l’Epoux; mais l’ami de l’Epoux qui assiste, et qui l’entend, est tout réjoui par la voix de l’Epoux; c’est pourquoi cette joie que j’ai, est accomplie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Il faut qu’il croisse, et que je diminue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Celui qui est venu d’en haut, est au-dessus de tous; celui qui est venu de la terre, est de la terre, et il parle comme venu de la terre; celui qui est venu du ciel, est au-dessus de tous:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'Et ce qu’il a vu et ouï, il le témoigne; mais personne ne reçoit son témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Celui qui a reçu son témoignage a scellé que Dieu est véritable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Car celui que Dieu a envoyé annonce les paroles de Dieu; car Dieu ne lui donne point l’Esprit par mesure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Le Père aime le Fils, et il lui a donné toutes choses en main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Qui croit au Fils, a la vie éternelle; mais qui désobéit au Fils, ne verra point la vie; mais la colère de Dieu demeure sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Or quand le Seigneur eut connu que les Pharisiens avaient ouï dire qu’il faisait et baptisait plus de disciples que Jean;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, 'Toutefois Jésus ne baptisait point lui-même, mais c’étaient ses Disciples;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'Il laissa la Judée, et s’en alla encore en Galilée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Or il fallait qu’il traversât par la Samarie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Il vint donc en une ville de Samarie, nommée Sichar, qui est près de la possession que Jacob donna à Joseph son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Or il y avait là une fontaine de Jacob; et Jésus étant lassé du chemin, se tenait là assis sur la fontaine; c’était environ les six heures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Et une femme Samaritaine étant venue pour puiser de l’eau, Jésus lui dit: donne-moi à boire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Car ses Disciples s’en étaient allés à la ville pour acheter des vivres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Mais cette femme Samaritaine lui dit: comment toi qui es Juif, me demandes-tu à boire, à moi qui suis une femme Samaritaine? car les Juifs n’ont point de communication avec les Samaritains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jésus répondit, et lui dit: si tu connaissais le don de Dieu, et qui est celui qui te dit: donne-moi à boire, tu lui en eusses demandé toi- même, et il t’eût donné de l’eau vive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'La femme lui dit: Seigneur, tu n’as rien pour puiser, et le puits est profond; d’où as-tu donc cette eau vive?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Es-tu plus grand que Jacob notre père, qui nous a donné le puits, et lui-même en a bu, et ses enfants, et son bétail?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jésus répondit, et lui dit: quiconque boit de cette eau-ci aura encore soif;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'Mais celui qui boira de l’eau que je lui donnerai, n’aura jamais soif; mais l’eau que je lui donnerai deviendra en lui une fontaine d’eau qui jaillira jusque dans la vie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'La femme lui dit: Seigneur, donne-moi de cette eau, afin que je n’aie plus soif, et que je ne vienne plus ici puiser de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Jésus lui dit: va, et appelle ton mari, et t’en viens ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'La femme répondit, et lui dit: je n’ai point de mari. Jésus lui dit: tu as bien dit: je n’ai point de mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Car tu as eu cinq maris, et celui que tu as maintenant n’est point ton mari; en cela tu as dit la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'La femme lui dit: Seigneur, je vois que tu es un Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Nos pères ont adoré sur cette montagne-là, et vous dites qu’à Jérusalem est le lieu où il faut adorer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Jésus lui dit: femme, crois-moi, l’heure vient que vous n’adorerez le Père, ni sur cette montagne, ni à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Vous adorez ce que vous ne connaissez point; nous adorons ce que nous connaissons; car le salut vient des Juifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Mais l’heure vient, et elle est maintenant, que les vrais adorateurs adoreront le Père en esprit et en vérité; car aussi le Père en demande de tels qui l’adorent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Dieu est esprit; et il faut que ceux qui l’adorent, l’adorent en esprit et en vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'La femme lui répondit: je sais que le Messie, c’est-à-dire le Christ, doit venir; quand donc il sera venu, il nous annoncera toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Jésus lui dit: c’est moi-même, qui parle avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Sur cela ses Disciples vinrent, et ils s’étonnèrent de ce qu’il parlait avec une femme; toutefois nul ne dit: que demandes-tu? ou pourquoi parles-tu avec elle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'La femme donc laissa sa cruche, et s’en alla à la ville, et elle dit aux habitants:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Venez, voyez un homme qui m’a dit tout ce que j’ai fait, celui-ci n’est-il point le Christ?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Ils sortirent donc de la ville, et vinrent vers lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Cependant les Disciples le priaient, disant: Maître, mange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Mais il leur dit: j’ai à manger d’une viande que vous ne savez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Sur quoi les Disciples disaient entre eux: quelqu’un lui aurait-il apporté à manger?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jésus leur dit: ma viande est que je fasse la volonté de celui qui m’a envoyé, et que j’accomplisse son oeuvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Ne dites-vous pas qu’il y a encore quatre mois, et la moisson viendra? voici, je vous dis, levez vos yeux, et regardez les campagnes, car elles sont déjà blanches pour moissonner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Or celui qui moissonne reçoit le salaire, et assemble le fruit en vie éternelle; afin que celui qui sème et celui qui moissonne se réjouissent ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Or ce que l’on dit d’ordinaire, que l’un sème, et l’autre moissonne, est vrai en ceci,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Que je vous ai envoyés moissonner ce en quoi vous n’avez point travaillé; d’autres ont travaillé, et vous êtes entrés dans leur travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Or plusieurs des Samaritains de cette ville-là crurent en lui, pour la parole de la femme, qui avait rendu ce témoignage: il m’a dit tout ce que j’ai fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Quand donc les Samaritains furent venus vers lui, ils le prièrent de demeurer avec eux; et il demeura là deux jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Et beaucoup plus de gens crurent pour sa parole;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'Et ils disaient à la femme: ce n’est plus pour ta parole que nous croyons; car nous-mêmes l’avons entendu, et nous savons que celui-ci est véritablement le Christ, le Sauveur du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Or deux jours après il partit de là, et s’en alla en Galilée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Car Jésus avait rendu témoignage qu’un Prophète n’est point honoré en son pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Quand donc il fut venu en Galilée, les Galiléens le reçurent, ayant vu toutes les choses qu’il avait faites à Jérusalem le jour de la Fête: car eux aussi étaient venus à la Fête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Jésus donc vint encore à Cana de Galilée, où il avait changé l’eau en vin. Or il y avait à Capernaüm un Seigneur de la cour, duquel le fils était malade;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Qui ayant entendu que Jésus était venu de Judée en Galilée, s’en alla vers lui, et le pria de descendre pour guérir son fils: car il s’en allait mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Mais Jésus lui dit: si vous ne voyez des prodiges et des miracles, vous ne croyez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Et ce Seigneur de la cour lui dit: Seigneur, descends avant que mon fils meure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Jésus lui dit: va, ton fils vit. Cet homme crut à la parole que Jésus lui avait dite, et il s’en alla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Et comme déjà il descendait, ses serviteurs vinrent au-devant de lui, et lui apportèrent des nouvelles, disant: ton fils vit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Et il leur demanda à quelle heure il s’était trouvé mieux; et ils lui dirent: hier sur les sept heures la fièvre le quitta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Le père donc connut que c’était à cette même heure-là que Jésus lui avait dit: ton fils vit. Et il crut, avec toute sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Jésus fit encore ce second miracle, quand il fut venu de Judée en Galilée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Après ces choses il y avait une fête des Juifs, et Jésus monta à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Or il y a à Jérusalem, au marché aux brebis, un lavoir appelé en Hébreu Béthesda ayant cinq portiques;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'Dans lesquels gisait un grand nombre de malades, d’aveugles, de boiteux, et de gens qui avaient les membres secs, attendant le mouvement de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Car un Ange descendait en certains temps au lavoir, et troublait l’eau; et alors le premier qui descendait au lavoir après que l’eau en avait été troublée, était guéri, de quelque maladie qu’il fût détenu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Or il y avait là un homme malade depuis trente-huit ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Et Jésus le voyant couché par terre, et connaissant qu’il avait déjà été là longtemps, lui dit: veux-tu être guéri?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Le malade lui répondit: Seigneur, je n’ai personne qui me jette au lavoir quand l’eau est troublée, et pendant que j’y viens, un autre y descend avant moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jésus lui dit: lève-toi, charge ton petit lit, et marche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Et sur-le-champ l’homme fut guéri, et chargea son petit lit, et il marchait. Or c’était un jour de Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Les Juifs donc dirent à celui qui avait été guéri: c’est un jour de Sabbat, il ne t’est pas permis de charger ton petit lit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Il leur répondit: celui qui m’a guéri m’a dit: charge ton petit lit, et marche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Alors ils lui demandèrent: qui est celui qui t’a dit: charge ton petit lit, et marche?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Mais celui qui avait été guéri ne savait pas qui c’était: car Jésus s’était éclipsé du milieu de la foule qui était en ce lieu-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Depuis, Jésus le trouva au Temple, et lui dit: voici, tu as été guéri; ne pèche plus désormais, de peur que pis ne t’arrive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Cet homme s’en alla, et rapporta aux Juifs que c’était Jésus qui l’avait guéri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'C’est pourquoi les Juifs poursuivaient Jésus, et cherchaient à le faire mourir, parce qu’il avait fait ces choses le jour du Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Mais Jésus leur répondit: mon Père travaille jusqu’à maintenant, et je travaille aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Et à cause de cela les Juifs tâchaient encore plus de le faire mourir, parce que non seulement il avait violé le Sabbat, mais aussi parce qu’il disait que Dieu était son propre Père, se faisant égal à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Mais Jésus répondit, et leur dit: en vérité, en vérité je vous dis, que le Fils ne peut rien faire de soi-même, sinon qu’il le voie faire au Père: car quelque chose que le Père fasse, le Fils aussi le fait de même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Car le Père aime le Fils, et lui montre toutes les choses qu’il fait; et il lui montrera de plus grandes oeuvres que celle-ci, afin que vous en soyez dans l’admiration.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Car comme le Père ressuscite les morts et les vivifie, de même aussi le Fils vivifie ceux qu’il veut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Car le Père ne juge personne; mais il a donné tout jugement au Fils;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'Afin que tous honorent le Fils, comme ils honorent le Père; celui qui n’honore point le Fils, n’honore point le Père qui l’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'En vérité, en vérité je vous dis: que celui qui entend ma parole, et croit à celui qui m’a envoyé, a la vie éternelle, et il ne sera point exposé à la condamnation, mais il est passé de la mort à la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'En vérité, en vérité je vous dis: que l’heure vient, et elle est même déjà venue, que les morts entendront la voix du Fils de Dieu, et ceux qui l’auront entendue, vivront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Car comme le Père a la vie en soi même, ainsi il a donné au Fils d’avoir la vie en soi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'Et il lui a donné le pouvoir de juger parce qu’il est le Fils de l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Ne soyez point étonnés de cela: car l’heure viendra, en laquelle tous ceux qui sont dans les sépulcres entendront sa voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'Et ils sortiront, savoir ceux qui auront bien fait, en résurrection de vie; et ceux qui auront mal fait, en résurrection de condamnation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Je ne puis rien faire de moi-même: je juge conformément à ce que j’entends, et mon jugement est juste; car je ne cherche point ma volonté, mais la volonté du Père qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Si je rends témoignage de moi-même, mon témoignage n’est pas digne de foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'C’est un autre qui rend témoignage de moi, et je sais que le témoignage qu’il rend de moi est digne de foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Vous avez envoyé vers Jean, et il a rendu témoignage à la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Or je ne cherche point le témoignage des hommes; mais je dis ces choses afin que vous soyez sauvés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Il était une lampe ardente et brillante; et vous avez voulu vous réjouir pour un peu de temps en sa lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Mais moi j’ai un témoignage plus grand que celui de Jean; car les oeuvres que mon Père m’a données pour les accomplir, ces oeuvres mêmes que je fais, témoignent de moi que mon Père m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'Et le Père qui m’a envoyé, a lui-même rendu témoignage de moi; jamais vous n’ouîtes sa voix, ni ne vîtes sa face.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'Et vous n’avez point sa parole demeurante en vous; puisque vous ne croyez point à celui qu’il a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Enquérez-vous diligemment des Ecritures: car vous estimez avoir par elles la vie éternelle, et ce sont elles qui portent témoignage de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'Mais vous ne voulez point venir à moi, pour avoir la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Je ne tire point ma gloire des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Mais je connais bien que vous n’avez point l’amour de Dieu en vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Je suis venu au Nom de mon Père, et vous ne me recevez point; si un autre vient en son propre nom, vous le recevrez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Comment pouvez-vous croire, puisque vous cherchez la gloire l’un de l’autre, et que vous ne cherchez point la gloire qui vient de Dieu seul?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Ne croyez point que je vous doive accuser envers mon Père; Moïse sur qui vous vous fondez, est celui qui vous accusera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Car si vous croyiez Moïse, vous me croiriez aussi; vu qu’il a écrit de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Mais si vous ne croyez point à ses écrits, comment croirez-vous à mes paroles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Après ces choses Jésus s’en alla au delà de la mer de Galilée, qui est la mer de Tibériade.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Et de grandes troupes le suivaient, à cause qu’ils voyaient les miracles qu’il faisait en ceux qui étaient malades.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Mais Jésus monta sur une montagne, et il s’assit là avec ses Disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Or le jour de Pâque, qui était la Fête des Juifs, était proche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Et Jésus ayant levé ses yeux, et voyant que de grandes troupes venaient à lui, dit à Philippe: d’où achèterons-nous des pains, afin que ceux-ci aient à manger?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Or il disait cela pour l’éprouver: car il savait bien ce qu’il devait faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Philippe lui répondit: quand nous aurions pour deux cents deniers de pain, cela ne leur suffirait point, quoique chacun d’eux n’en prît que tant soit peu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Et l’un de ses Disciples, savoir André, frère de Simon Pierre, lui dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Il y a ici un petit garçon qui a cinq pains d’orge et deux poissons; mais qu’est-ce que cela pour tant de gens?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Alors Jésus dit: faites asseoir les gens; (or il y avait beaucoup d’herbe en ce lieu-là), les gens donc s’assirent au nombre d’environ cinq mille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Et Jésus prit les pains; et après avoir rendu grâces, il les distribua aux Disciples, et les Disciples à ceux qui étaient assis, et de même des poissons, autant qu’ils en voulaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Et après qu’ils furent rassasiés, il dit à ses Disciples: amassez les pièces qui sont de reste, afin que rien ne soit perdu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Ils les amassèrent donc, et ils remplirent douze corbeilles des pièces des cinq pains d’orge, qui étaient demeurées de reste à ceux qui en avaient mangé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Or ces gens ayant vu le miracle que Jésus avait fait, disaient: celui-ci est véritablement le Prophète qui devait venir au monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Mais Jésus ayant connu qu’ils devaient venir l’enlever afin de le faire Roi, se retira encore tout seul en la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Et quand le soir fut venu, ses Disciples descendirent à la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'Et étant montés dans la nacelle, ils passaient au delà de la mer vers Capernaüm, et il était déjà nuit, que Jésus n’était pas encore venu à eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'Et la mer s’éleva par un grand vent qui soufflait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Mais après qu’ils eurent ramé environ vingt-cinq ou trente stades, ils virent Jésus marchant sur la mer, et s’approchant de la nacelle; et ils eurent peur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Mais il leur dit: c’est moi, ne craignez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Ils le reçurent donc avec plaisir dans la nacelle, et aussitôt la nacelle prit terre au lieu où ils allaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Le lendemain les troupes qui étaient demeurées de l’autre côté de la mer, voyant qu’il n’y avait point là d’autre nacelle que celle-là seule dans laquelle ses Disciples étaient entrés, et que Jésus n’était point entré avec ses Disciples dans la nacelle, mais que ses Disciples s’en étaient allés seuls;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'Et d’autres nacelles étant venues de Tibériade près du lieu où ils avaient mangé le pain, après que le Seigneur eut rendu grâces;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Ces troupes donc qui voyaient que Jésus n’était point là, ni ses Disciples, montèrent aussi dans ces nacelles, et vinrent à Capernaüm, cherchant Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Et l’ayant trouvé au delà de la mer, ils lui dirent: Maître, quand es-tu arrivé ici?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jésus leur répondit, et leur dit: en vérité, en vérité je vous dis: vous me cherchez, non parce que vous avez vu des miracles, mais parce que vous avez mangé des pains, et que vous avez été rassasiés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Travaillez, non point après la viande qui périt, mais après celle qui est permanente jusque dans la vie éternelle, laquelle le Fils de l’homme vous donnera; car le Père, savoir Dieu, l’a approuvé de son cachet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Ils lui dirent donc: que ferons-nous pour faire les oeuvres de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Jésus répondit, et leur dit: c’est ici l’oeuvre de Dieu, que vous croyiez en celui qu’il a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Alors ils lui dirent: quel miracle fais-tu donc, afin que nous le voyions, et que nous te croyions? quelle oeuvre fais-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Nos pères ont mangé la manne au désert; selon ce qui est écrit: il leur a donné à manger le pain du ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Mais Jésus leur dit: en vérité, en vérité je vous dis: Moïse ne vous a pas donné le pain du ciel; mais mon Père vous donne le vrai pain du ciel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Car le pain de Dieu c’est celui qui est descendu du ciel, et qui donne la vie au monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Ils lui dirent donc: Seigneur, donne-nous toujours ce pain-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Et Jésus leur dit: je suis le pain de vie. Celui qui vient à moi, n’aura point de faim; et celui qui croit en moi, n’aura jamais soif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Mais je vous ai dit que vous m’avez vu, et cependant vous ne croyez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Tout ce que mon Père me donne, viendra à moi; et je ne mettrai point dehors celui qui viendra à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Car je suis descendu du ciel non point pour faire ma volonté, mais la volonté de celui qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Et c’est ici la volonté du Père qui m’a envoyé, que je ne perde rien de tout ce qu’il m’a donné, mais que je le ressuscite au dernier jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Et c’est ici la volonté de celui qui m’a envoyé, que quiconque contemple le Fils, et croit en lui, ait la vie éternelle; c’est pourquoi je le ressusciterai au dernier jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Or les Juifs murmuraient contre lui de ce qu’il avait dit: je suis le pain descendu du ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'Car ils disaient: n’est-ce pas ici Jésus, le fils de Joseph, duquel nous connaissons le père et la mère? comment donc dit celui-ci: je suis descendu du ciel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Jésus donc répondit, et leur dit: ne murmurez point entre vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Nul ne peut venir à moi, si le Père, qui m’a envoyé, ne le tire; et moi, je le ressusciterai au dernier jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Il est écrit dans les Prophètes: et ils seront tous enseignés de Dieu. Quiconque donc a écouté le Père, et a été instruit de ses intentions, vient à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Non point qu’aucun ait vu le Père, sinon celui qui est de Dieu, celui- là a vu le Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'En vérité, en vérité je vous dis: qui croit en moi a la vie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Je suis le pain de vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Vos pères ont mangé la manne au désert, et ils sont morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'C’est ici le pain qui est descendu du ciel, afin que si quelqu’un en mange, il ne meure point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Je suis le pain vivifiant qui suis descendu du ciel; si quelqu’un mange de ce pain, il vivra éternellement; et le pain que je donnerai, c’est ma chair, laquelle je donnerai pour la vie du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Les Juifs donc disputaient entre eux, et disaient: comment celui-ci nous peut-il donner sa chair à manger?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Et Jésus leur dit: en vérité, en vérité je vous dis, que si vous ne mangez la chair du Fils de l’homme, et ne buvez son sang, vous n’aurez point la vie en vous-mêmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Celui qui mange ma chair, et qui boit mon sang a la vie éternelle; et je le ressusciterai au dernier jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Car ma chair est une véritable nourriture, et mon sang est un véritable breuvage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Celui qui mange ma chair, et qui boit mon sang, demeure en moi, et moi en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Comme le Père qui est vivant m’a envoyé, et que je suis vivant par le Père; ainsi celui qui me mangera, vivra aussi par moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'C’est ici le pain qui est descendu du ciel, non point comme vos pères ont mangé la manne, et ils sont morts; celui qui mangera ce pain, vivra éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Il dit ces choses dans la Synagogue, enseignant à Capernaüm.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Et plusieurs de ses disciples l’ayant entendu, dirent: cette parole est dure, qui la peut ouïr?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Mais Jésus sachant en lui-même que ses disciples murmuraient de cela, leur dit: ceci vous scandalise-t-il?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Que sera-ce donc si vous voyez le Fils de l’homme monter où il était premièrement?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'C’est l’esprit qui vivifie; la chair ne profite de rien; les paroles que je vous dis, sont esprit et vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Mais il y en a plusieurs entre vous qui ne croient point; car Jésus savait dès le commencement qui seraient ceux qui ne croiraient point, et qui serait celui qui le trahirait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'Il leur dit donc: c’est pour cela que je vous ai dit, que nul ne peut venir à moi, s’il ne lui est donné de mon Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Dès cette heure-là plusieurs de ses Disciples l’abandonnèrent, et ils ne marchaient plus avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Et Jésus dit aux douze: et vous, ne vous en voulez-vous point aussi aller?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Mais Simon Pierre lui répondit: Seigneur! auprès de qui nous en irons-nous? tu as les paroles de la vie éternelle:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'Et nous avons cru, et nous avons connu que tu es le Christ, le Fils du Dieu vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Jésus leur répondit: ne vous ai-je pas choisis vous douze? et toutefois l’un de vous est un démon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Or il disait cela de Judas Iscariot, fils de Simon; car c’était celui à qui il devait arriver de le trahir, quoiqu’il fût l’un des douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Après ces choses Jésus demeurait en Galilée, car il ne voulait point demeurer en Judée, parce que les Juifs cherchaient à le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Or la Fête des Juifs, appelée des Tabernacles, était proche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Et ses frères lui dirent: pars d’ici, et t’en va en Judée, afin que tes disciples aussi contemplent les oeuvres que tu fais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Car on ne fait rien en secret, lorsqu’on cherche de se porter franchement; si tu fais ces choses-ci, montre-toi toi-même au monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Car ses frères mêmes ne croyaient point en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Et Jésus leur dit: mon temps n’est pas encore venu, mais votre temps est toujours prêt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Le monde ne peut pas vous avoir en haine, mais il me hait: parce que je rends témoignage contre lui que ses oeuvres sont mauvaises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Montez vous autres à cette Fête; pour moi je ne monte point encore à cette Fête, parce que mon temps n’est pas encore accompli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Et leur ayant dit ces choses, il demeura en Galilée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Mais comme ses frères furent montés, alors il monta aussi à la Fête, non point publiquement, mais comme en secret.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Or les Juifs le cherchaient à la Fête, et ils disaient: où est-il?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Et il y avait un grand murmure sur son sujet parmi les troupes. Les uns disaient: il est homme de bien; et les autres disaient: non, mais il séduit le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Toutefois personne ne parlait franchement de lui, à cause de la crainte qu’on avait des Juifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Et comme la Fête était déjà à demi passée, Jésus monta au Temple, et il y enseignait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Et les Juifs s’en étonnaient, disant: comment celui-ci sait-il les Ecritures, vu qu’il ne les a point apprises?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Jésus leur répondit, et dit: ma doctrine n’est pas mienne, mais elle est de celui qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Si quelqu’un veut faire sa volonté, il connaîtra de la doctrine, savoir si elle est de Dieu, ou si je parle de moi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Celui qui parle de soi-même, cherche sa propre gloire; mais celui qui cherche la gloire de celui qui l’a envoyé, est véritable, et il n’y a point d’injustice en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Moïse ne vous a-t-il pas donné la Loi? et cependant nul de vous n’observe la Loi? pourquoi cherchez-vous à me faire mourir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Les troupes répondirent: tu as un démon; qui est-ce qui cherche à te faire mourir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jésus répondit, et leur dit: j’ai fait une oeuvre, et vous vous en êtes tous étonnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Et vous, parce que Moïse vous a donné la Circoncision, laquelle n’est pourtant pas de Moïse, mais des pères, vous circoncisez bien un homme le jour du Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Si donc l’homme reçoit la Circoncision le jour du Sabbat, afin que la Loi de Moïse ne soit point violée, êtes-vous fâchés contre moi de ce que j’ai guéri un homme tout entier le jour du Sabbat?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Ne jugez point sur les apparences, mais jugez suivant l’équité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Alors quelques-uns de ceux de Jérusalem disaient: n’est-ce pas celui qu’ils cherchent à faire mourir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Et cependant voici, il parle librement, et ils ne lui disent rien; les Gouverneurs auraient-ils connu certainement que celui-ci est véritablement le Christ?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Or nous savons bien d’où est celui-ci, mais quand le Christ viendra, personne ne saura d’où il est.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Jésus donc criait dans le Temple enseignant, et disant: et vous me connaissez, et vous savez d’où je suis; et je ne suis point venu de moi- même, mais celui qui m’a envoyé, est véritable, et vous ne le connaissez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Mais moi, je le connais: car je suis issu de lui, et c’est lui qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Alors ils cherchaient à le prendre, mais personne ne mit les mains sur lui, parce que son heure n’était pas encore venue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Et plusieurs d’entre les troupes crurent en lui, et ils disaient: quand le Christ sera venu, fera-t-il plus de miracles que celui-ci n’a fait');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Les Pharisiens entendirent la troupe murmurant ces choses de lui; et les Pharisiens, avec les principaux Sacrificateurs envoyèrent des huissiers pour le prendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Et Jésus leur dit: je suis encore pour un peu de temps avec vous, puis je m’en vais à celui qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Vous me chercherez, mais vous ne me trouverez point; et là où je serai, vous n’y pouvez venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Les Juifs donc dirent entre eux: où doit-il aller que nous ne le trouverons point? doit-il aller vers ceux qui sont dispersés parmi les Grecs, et enseigner les Grecs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Quel est ce discours qu’il a tenu: vous me chercherez, mais vous ne me trouverez point; et là où je serai, vous n’y pouvez venir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Et en la dernière et grande journée de la Fête, Jésus se trouva là, criant, et disant: si quelqu’un a soif, qu’il vienne à moi, et qu’il boive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Celui qui croit en moi, selon ce que dit l’Ecriture, des fleuves d’eau vive découleront de son ventre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, '(Or il disait cela de l’Esprit que devaient recevoir ceux qui croyaient en lui; car le Saint-Esprit n’était pas encore donné, parce que Jésus n’était pas encore glorifié.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Plusieurs donc de la troupe ayant entendu ce discours, disaient: celui-ci est véritablement le Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Les autres disaient: celui-ci est le Christ. Et les autres disaient: mais le Christ viendra-t-il de Galilée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'L’Ecriture ne dit-elle pas que le Christ viendra de la semence de David, et de la bourgade de Bethléhem, où demeurait David?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Il y eut donc de la division entre le peuple à cause de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Et quelques-uns d’entre eux le voulaient saisir, mais personne ne mit les mains sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Ainsi les huissiers s’en retournèrent vers les principaux Sacrificateurs et les Pharisiens, qui leur dirent: pourquoi ne l’avez- vous point amené?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Les huissiers répondirent: jamais homme ne parla comme cet homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Mais les Pharisiens leur répondirent: n’avez-vous point été séduits, vous aussi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Aucun des Gouverneurs ou des Pharisiens a-t-il cru en lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Mais cette populace, qui ne sait ce que c’est que de la Loi, est plus qu’exécrable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Nicodème (celui qui était venu vers Jésus de nuit, et qui était l’un d’entre eux) leur dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Notre Loi juge-t-elle un homme avant que de l’avoir entendu, et d’avoir connu ce qu’il a fait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Ils répondirent, et lui dirent: n’es-tu pas aussi de Galilée? enquiers-toi, et sache qu’aucun Prophète n’a été suscité de Galilée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'Et chacun s’en alla en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Mais Jésus s’en alla à la montagne des oliviers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Et à la pointe du jour il vint encore au Temple, et tout le peuple vint à lui, et s’étant assis, il les enseignait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Et les Scribes et les Pharisiens lui amenèrent une femme surprise en adultère; et l’ayant placée au milieu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'Ils lui dirent: Maître, cette femme a été surprise sur le fait même commettant adultère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'Or Moïse nous a commandé dans la Loi de lapider celles qui sont dans son cas; toi donc qu’en dis-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Or ils disaient cela pour l’éprouver, afin qu’ils eussent de quoi l’accuser. Mais Jésus s’étant penché en bas écrivait avec son doigt sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Et comme ils continuaient à l’interroger, s’étant relevé, il leur dit: que celui de vous qui est sans péché, jette le premier la pierre contre elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Et s’étant encore baissé, il écrivait sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Or quand ils eurent entendu cela, étant condamnés par leur conscience, ils sortirent un à un, en commençant depuis les plus anciens jusques aux derniers; de sorte que Jésus demeura seul avec la femme qui était là au milieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Alors Jésus s’étant relevé, et ne voyant personne que la femme, il lui dit: femme, où sont ceux qui t’accusaient? nul ne t’a-t-il condamnée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Elle dit: nul, Seigneur. Et Jésus lui dit: je ne te condamne pas non plus, va, et ne pèche plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Et Jésus leur parla encore, en disant: je suis la lumière du monde; celui qui me suit ne marchera point dans les ténèbres, mais il aura la lumière de la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Alors les Pharisiens lui dirent: tu rends témoignage de toi-même, ton témoignage n’est pas digne de foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jésus répondit, et leur dit: quoique je rende témoignage de moi-même, mon témoignage est digne de foi; car je sais d’où je suis venu, et où je vais; mais vous ne savez d’où je viens, ni où je vais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Vous jugez selon la chair, mais moi, je ne juge personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Que si même je juge, mon jugement est digne de foi; car je ne suis point seul, mais il y a et moi et le Père qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Il est même écrit dans votre Loi, que le témoignage de deux hommes est digne de foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Je rends témoignage de moi-même, et le Père qui m’a envoyé rend aussi témoignage de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Alors ils lui dirent: où est ton Père? Jésus répondit: vous ne connaissez ni moi, ni mon Père. Si vous me connaissiez, vous connaîtriez aussi mon Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Jésus dit ces paroles dans la Trésorerie enseignant au Temple; mais personne ne le saisit, parce que son heure n’était pas encore venue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Et Jésus leur dit encore: je m’en vais, et vous me chercherez, mais vous mourrez en votre péché; là où je vais vous n’y pouvez venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Les Juifs donc disaient: se tuera-t-il lui-même, qu’il dise: là où je vais, vous n’y pouvez venir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Alors il leur dit: vous êtes d’en bas, mais moi, je suis d’en haut; vous êtes de ce monde, mais moi, je ne suis point de ce monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'C’est pourquoi je vous ai dit, que vous mourrez en vos péchés; car si vous ne croyez que je suis l’envoyé de Dieu, vous mourrez en vos péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Alors ils lui dirent: toi, qui es-tu? Et Jésus leur dit: ce que je vous dis dès le commencement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'J’ai beaucoup de choses à dire de vous et à condamner en vous, mais celui qui m’a envoyé, est véritable, et les choses que j’ai ouïes de lui, je les dis au monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Ils ne connurent point qu’il leur parlait du Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Jésus donc leur dit: quand vous aurez élevé le Fils de l’homme, vous connaîtrez alors que je suis l’envoyé de Dieu, et que je ne fais rien de moi-même, mais que je dis ces choses ainsi que mon Père m’a enseigné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'Car celui qui m’a envoyé est avec moi, le Père ne m’a point laissé seul, parce que je fais toujours les choses qui lui plaisent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Comme il disait ces choses plusieurs crurent en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Et Jésus disait aux Juifs qui avaient cru en lui: si vous persistez en ma parole, vous serez vraiment mes disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'Et vous connaîtrez la vérité, et la vérité vous rendra libres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Ils lui répondirent: nous sommes la postérité d’Abraham, et jamais nous ne servîmes personne; comment donc dis-tu: vous serez rendus libres?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jésus leur répondit: en vérité, en vérité je vous dis: quiconque fait le péché, est esclave du péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Or l’esclave ne demeure point toujours dans la maison; le fils y demeure toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Si donc le Fils vous affranchit, vous serez véritablement libres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Je sais que vous êtes la postérité d’Abraham, mais pourtant vous tâchez à me faire mourir, parce que ma parole n’est pas reçue dans vos coeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Je vous dis ce que j’ai vu chez mon Père; et vous aussi vous faites les choses que vous avez vues chez votre père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Ils répondirent, et lui dirent: notre père c’est Abraham. Jésus leur dit: si vous étiez enfants d’Abraham, vous feriez les oeuvres d’Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Mais maintenant vous tâchez à me faire mourir, moi qui suis un homme qui vous ai dit la vérité, laquelle j’ai ouïe de Dieu; Abraham n’a point fait cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Vous faites les actions de votre père. Et ils lui dirent: nous ne sommes pas nés d’un mauvais commerce; nous avons un père qui est Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Mais Jésus leur dit: si Dieu était votre Père, certes vous m’aimeriez: puisque je suis issu de Dieu, et que je viens de lui; car je ne suis point venu de moi-même, mais c’est lui qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Pourquoi n’entendez-vous point mon langage? c’est parce que vous ne pouvez pas écouter ma parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Le père dont vous êtes issus c’est le démon, et vous voulez faire les désirs de votre père. Il a été meurtrier dès le commencement, et il n’a point persévéré dans la vérité, car la vérité n’est point en lui. Toutes les fois qu’il profère le mensonge, il parle de son propre fonds; car il est menteur, et le père du mensonge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Mais pour moi, parce que je dis la vérité, vous ne me croyez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Qui est celui d’entre vous qui me reprendra de péché? Et si je dis la vérité, pourquoi ne me croyez-vous point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Celui qui est de Dieu, entend les paroles de Dieu; mais vous ne les entendez point, parce que vous n’êtes point de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Alors les Juifs répondirent, et lui dirent: ne disons-nous pas bien que tu es un Samaritain, et que tu as un démon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jésus répondit: je n’ai point un démon, mais j’honore mon Père, et vous me déshonorez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Or je ne cherche point ma gloire; il y en a un qui la cherche, et qui en juge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'En vérité, en vérité je vous dis, que si quelqu’un garde ma parole, il ne mourra point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Les Juifs donc lui dirent: maintenant nous connaissons que tu as un démon; Abraham est mort, et les Prophètes aussi, et tu dis: si quelqu’un garde ma parole, il ne mourra point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Es-tu plus grand que notre père Abraham qui est mort? les Prophètes aussi sont morts, qui te fais-tu toi-même?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jésus répondit: si je me glorifie moi-même, ma gloire n’est rien; mon Père est celui qui me glorifie, celui duquel vous dites qu’il est votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'Toutefois vous ne l’avez point connu, mais moi je le connais; et si je dis que je ne le connais point, je serai menteur, semblable à vous; mais je le connais, et je garde sa parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham votre père a tressailli de joie de voir cette mienne journée; et il l’a vue, et s’en est réjoui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Sur cela les Juifs lui dirent: tu n’as pas encore cinquante ans, et tu as vu Abraham!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Et Jésus leur dit: en vérité, en vérité je vous dis, avant qu’Abraham fût, je suis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Alors ils levèrent des pierres pour les jeter contre lui, mais Jésus se cacha, et sortit du Temple, ayant passé au travers d’eux; et ainsi il s’en alla.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Et comme Jésus passait, il vit un homme aveugle dès sa naissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Et ses Disciples l’interrogèrent, disant: Maître, qui a péché, celui- ci, ou son père, ou sa mère, pour être ainsi né aveugle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jésus répondit: ni celui-ci n’a péché, ni son père, ni sa mère; mais c’est afin que les oeuvres de Dieu soient manifestées en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Il me faut faire les oeuvres de celui qui m’a envoyé, tandis qu’il est jour. La nuit vient en laquelle personne ne peut travailler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Pendant que je suis au monde, je suis la lumière du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Ayant dit ces paroles, il cracha en terre, et fit de la boue avec sa salive, et mit de cette boue sur les yeux de l’aveugle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'Et lui dit: va, et te lave au réservoir de Siloé (qui veut dire envoyé); il y alla donc, et se lava, et il revint voyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Or les voisins, et ceux qui auparavant avaient vu qu’il était aveugle, disaient: n’est-ce pas celui qui était assis, et qui mendiait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Les uns disaient: c’est lui: et les autres disaient: il lui ressemble; mais lui, il disait: c’est moi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Ils lui dirent donc: comment ont été ouverts tes yeux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Il répondit, et dit: cet homme qu’on appelle Jésus, a fait de la boue, et il l’a mise sur mes yeux, et m’a dit: va au réservoir de Siloé, et te lave; après donc que j’y suis allé, et que je me suis lavé, j’ai recouvré la vue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Alors ils lui dirent: où est cet homme-là? il dit: je ne sais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Ils amenèrent aux Pharisiens celui qui auparavant avait été aveugle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Or c’était en un jour de Sabbat, que Jésus avait fait de la boue, et qu’il avait ouvert les yeux de l’aveugle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'C’est pourquoi les Pharisiens l’interrogèrent encore, comment il avait reçu la vue; et il leur dit: il a mis de la boue sur mes yeux, et je me suis lavé, et je vois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Sur quoi quelques-uns d’entre les Pharisiens dirent: cet homme n’est point un envoyé de Dieu; car il ne garde point le Sabbat; mais d’autres disaient: comment un méchant homme pourrait-il faire de tels prodiges? et il y avait de la division entre eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Ils dirent encore à l’aveugle: toi que dis-tu de lui, sur ce qu’il t’a ouvert les yeux? il répondit: c’est un Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Mais les Juifs ne crurent point que cet homme eût été aveugle, et qu’il eût recouvré la vue, jusqu’à ce qu’ils eurent appelé le père, et la mère de celui qui avait recouvré la vue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'Et ils les interrogèrent, disant: est-ce ici votre fils, que vous dites être né aveugle? comment donc voit-il maintenant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Son père et sa mère leur répondirent, et dirent: nous savons que c’est ici notre fils, et qu’il est né aveugle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'Mais comment il voit maintenant, ou qui lui a ouvert les yeux, nous ne le savons point; il a de l’âge, interrogez-le, il parlera de ce qui le regarde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Son père et sa mère dirent ces choses, parce qu’ils craignaient les Juifs; car les Juifs avaient déjà arrêté, que si quelqu’un l’avouait être le Christ, il serait chassé de la Synagogue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Pour cette raison son père et sa mère dirent: il a de l’âge, interrogez-le lui-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Ils appelèrent donc pour la seconde fois l’homme qui avait été aveugle, et ils lui dirent: Donne gloire à Dieu; nous savons que cet homme est un méchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Il répondit, et dit: je ne sais point s’il est méchant; mais une chose sais-je bien, c’est que j’étais aveugle, et maintenant je vois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Ils lui dirent donc encore: que t’a-t-il fait? comment a-t-il ouvert tes yeux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Il leur répondit: je vous l’ai déjà dit, et vous ne l’avez point écouté, pourquoi le voulez-vous encore ouïr? voulez-vous aussi être ses disciples?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Alors ils l’injurièrent, et lui dirent: toi sois son disciple; pour nous, nous sommes les disciples de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Nous savons que Dieu a parlé à Moïse; mais pour celui-ci, nous ne savons d’où il est.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'L’homme répondit, et leur dit: certes, c’est une chose étrange, que vous ne sachiez point d’où il est; et toutefois il a ouvert mes yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Or nous savons que Dieu n’exauce point les méchants, mais si quelqu’un est le serviteur de Dieu, et fait sa volonté, Dieu l’exauce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'On n’a jamais ouï dire que personne ait ouvert les yeux d’un aveugle- né.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Si celui-ci n’était point un envoyé de Dieu, il ne pourrait rien faire de semblable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Ils répondirent, et lui dirent: tu es entièrement né dans le péché, et tu nous enseignes! Et ils le chassèrent dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jésus apprit qu’ils l’avaient chassé dehors; et l’ayant rencontré, il lui dit: crois-tu au Fils de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Cet homme lui répondit, et dit: qui est-il, Seigneur, afin que je croie en lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Jésus lui dit: tu l’as vu, et c’est celui qui te parle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'Alors il dit: j’y crois, Seigneur; et il l’adora.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Et Jésus dit: je suis venu en ce monde pour exercer le jugement, afin que ceux qui ne voient point, voient; et que ceux qui voient, deviennent aveugles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Ce que quelques-uns d’entre les Pharisiens qui étaient avec lui, ayant entendu, ils lui dirent: et nous, sommes-nous aussi aveugles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jésus leur répondit: si vous étiez aveugles, vous n’auriez point de péché; mais maintenant vous dites: nous voyons; et c’est à cause de cela que votre péché demeure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'En vérité, en vérité je vous dis, que celui qui n’entre point par la porte dans la bergerie des brebis, mais y monte par ailleurs, est un larron et un voleur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Mais celui qui entre par la porte, est le berger des brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Le portier ouvre à celui-là, et les brebis entendent sa voix, et il appelle ses propres brebis par leur nom, et les mène dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Et quand il a mis ses brebis dehors, il va devant elles, et les brebis le suivent, parce qu’elles connaissent sa voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Mais elles ne suivront point un étranger, au contraire, elles le fuiront; parce qu’elles ne connaissent point la voix des étrangers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Jésus leur dit cette parabole, mais ils ne comprirent point ce qu’il leur disait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Jésus donc leur dit encore: en vérité, en vérité je vous dis, que je suis la Porte par où entrent les brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Tout autant qu’il en est venu avant moi, sont des larrons et des voleurs; mais les brebis ne les ont point écoutés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Je suis la Porte: si quelqu’un entre par moi, il sera sauvé, et il entrera et sortira, et il trouvera de la pâture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Le larron ne vient que pour dérober, et pour tuer et détruire; je suis venu afin qu’elles aient la vie, et qu’elles l’aient même en abondance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Je suis le bon berger: le bon berger met sa vie pour ses brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Mais le mercenaire, et celui qui n’est point berger, à qui n’appartiennent point les brebis, voyant venir le loup, abandonne les brebis, et s’enfuit; et le loup ravit et disperse les brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Ainsi le mercenaire s’enfuit, parce qu’il est mercenaire, et qu’il ne se soucie point des brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Je suis le bon berger, et je connais mes brebis, et mes brebis me connaissent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'Comme le Père me connaît, je connais aussi le Père, et je donne ma vie pour mes brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'J’ai encore d’autres brebis qui ne sont pas de cette bergerie; et il me les faut aussi amener, et elles entendront ma voix, et il y aura un seul troupeau, et un seul berger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'A cause de ceci le Père m’aime, c’est que je laisse ma vie, afin que je la reprenne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Personne ne me l’ôte, mais je la laisse de moi-même; j’ai la puissance de la laisser, et la puissance de la reprendre; j’ai reçu ce commandement de mon Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Il y eut encore de la division parmi les Juifs à cause de ces discours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Car plusieurs disaient: il a un démon, et il est hors du sens; pourquoi l’écoutez-vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Et les autres disaient: ces paroles ne sont point d’un démoniaque; le démon peut-il ouvrir les yeux des aveugles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Or la Fête de la Dédicace se fit à Jérusalem, et c’était en hiver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'Et Jésus se promenait dans le Temple, au portique de Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Et les Juifs l’environnèrent, et lui dirent: jusques à quand tiens-tu notre âme en suspens? si tu es le Christ, dis-le nous franchement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jésus leur répondit: je vous l’ai dit, et vous ne le croyez point; les oeuvres que je fais au Nom de mon Père, rendent témoignage de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Mais vous ne croyez point: parce que vous n’êtes point de mes brebis, comme je vous l’ai dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Mes brebis entendent ma voix, et je les connais, et elles me suivent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'Et moi, je leur donne la vie éternelle, et elles ne périront jamais; et personne ne les ravira de ma main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Mon Père, qui me les a données, est plus grand que tous; et personne ne les peut ravir des mains de mon Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Moi et le Père sommes un.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Alors les Juifs prirent encore des pierres pour le lapider.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Mais Jésus leur répondit: je vous ai fait voir plusieurs bonnes oeuvres de la part de mon Père: pour laquelle donc de ces oeuvres me lapidez-vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Les Juifs répondirent, en lui disant: nous ne te lapidons point pour aucune bonne oeuvre, mais pour un blasphème et parce que n’étant qu’un homme tu te fais Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jésus leur répondit: n’est-il pas écrit en votre Loi: j’ai dit: vous êtes des dieux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Si elle a donc appelé dieux ceux à qui la parole de Dieu est adressée; et cependant l’Ecriture ne peut être anéantie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'Dites-vous que je blasphème, moi que le Père a sanctifié, et qu’il a envoyé au monde, parce que j’ai dit: je suis le Fils de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Si je ne fais pas les oeuvres de mon Père, ne me croyez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Mais si je les fais, et que vous ne vouliez pas me croire, croyez à ces oeuvres; afin que vous connaissiez et que vous croyiez que le Père est en moi, et moi en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'A cause de cela ils cherchaient encore à le saisir; mais il échappa de leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'Et il s’en alla encore au delà du Jourdain, à l’endroit où Jean avait baptisé au commencement, et il demeura là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Et plusieurs vinrent à lui, et ils disaient: quant à Jean, il n’a fait aucun miracle; mais toutes les choses que Jean a dites de celui-ci, étaient véritables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Et plusieurs crurent là en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Or il y avait un certain homme malade, appelé Lazare, qui était de Béthanie, la bourgade de Marie et de Marthe sa soeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Et Marie était celle qui oignit le Seigneur d’une huile odoriférante, et qui essuya ses pieds de ses cheveux; et Lazare qui était malade, était son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Ses soeurs donc envoyèrent vers lui, pour lui dire: Seigneur, voici, celui que tu aimes, est malade.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Et Jésus l’ayant entendu, dit: cette maladie n’est point à la mort, mais pour la gloire de Dieu, afin que le Fils de Dieu soit glorifié par elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Or Jésus aimait Marthe, et sa soeur, et Lazare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Et après qu’il eut entendu que Lazare était malade, il demeura deux jours au même lieu où il était.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Et après cela il dit à ses Disciples: retournons en Judée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Les Disciples lui dirent: Maître, il n’y a que peu de temps, que les Juifs cherchaient à te lapider, et tu y vas encore!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jésus répondit: n’y a-t-il pas douze heures au jour? si quelqu’un marche de jour, il ne bronche point; car il voit la lumière de ce monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Mais si quelqu’un marche de nuit, il bronche; car il n’y a point de lumière avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Il dit ces choses, et puis il leur dit: Lazare notre ami dort; mais j’y vais pour l’éveiller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Et ses Disciples lui dirent: Seigneur, s’il dort il sera guéri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Or Jésus avait dit cela de sa mort; mais ils pensaient qu’il parlât du dormir du sommeil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Jésus leur dit donc alors ouvertement: Lazare est mort,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'Et j’ai de la joie pour l’amour de vous de ce que je n’y étais point; afin que vous croyiez; mais allons vers lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Alors Thomas, appelé Didyme, dit à ses condisciples: allons-y aussi, afin que nous mourions avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Jésus y étant donc arrivé, trouva que Lazare était déjà depuis quatre jours au sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Or Béthanie n’était éloignée de Jérusalem que d’environ quinze stades.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'Et plusieurs des Juifs étaient venus vers Marthe et Marie pour les consoler au sujet de leur frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Et quand Marthe eut ouï dire que Jésus venait, elle alla au-devant de lui; mais Marie se tenait assise à la maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Et Marthe dit à Jésus: Seigneur, si tu eusses été ici mon frère ne fût pas mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Mais maintenant je sais que tout ce que tu demanderas à Dieu, Dieu te le donnera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Jésus lui dit: ton frère ressuscitera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Marthe lui dit: je sais qu’il ressuscitera en la résurrection au dernier jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Jésus lui dit: je suis la résurrection et la vie: celui qui croit en moi, encore qu’il soit mort, il vivra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'Et quiconque vit, et croit en moi, ne mourra jamais; crois-tu cela?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Elle lui dit: oui, Seigneur, je crois que tu es le Christ, le Fils de Dieu, qui devait venir au monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Et quand elle eut dit cela, elle alla appeler secrètement Marie sa soeur, en lui disant: le Maître est ici, et il t’appelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Et aussitôt qu’elle l’eut entendu, elle se leva promptement, et s’en vint à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Or Jésus n’était point encore venu à la bourgade, mais il était au lieu où Marthe l’avait rencontré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Alors les Juifs qui étaient avec Marie à la maison, et qui la consolaient ayant vu qu’elle s’était levée si promptement, et qu’elle était sortie, la suivirent, en disant: elle s’en va au sépulcre, pour y pleurer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Quand donc Marie fut venue où était Jésus, l’ayant vu, elle se jeta à ses pieds, en lui disant: Seigneur, si tu eusses été ici, mon frère ne fût pas mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Et quand Jésus la vit pleurer, de même que les Juifs qui étaient venus là avec elle, il frémit en son esprit, et s’émut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'Et il dit: où l’avez-vous mis? Ils lui répondirent: Seigneur, viens, et vois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Et Jésus pleura.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Sur quoi les Juifs dirent: voyez comme il l’aimait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Et quelques-uns d’entre eux disaient: celui-ci qui a ouvert les yeux de l’aveugle, ne pouvait-il pas faire aussi que cet homme ne mourût point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Alors Jésus frémissant encore en soi même, vint au sépulcre, (or c’était une grotte, et il y avait une pierre mise dessus).');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Jésus dit: levez la pierre. Mais Marthe, la soeur du mort, lui dit: Seigneur, il sent déjà: car il est là depuis quatre jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jésus lui dit: ne t’ai-je pas dit que si tu crois tu verras la gloire de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Ils levèrent donc la pierre de dessus le lieu où le mort était couché. Et Jésus levant ses yeux au ciel, dit: Père, je te rends grâces de ce que tu m’as exaucé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Or je savais bien que tu m’exauces toujours; mais je l’ai dit à cause des troupes qui sont autour de moi, afin qu’elles croient que tu m’as envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Et ayant dit ces choses, il cria à haute voix: Lazare sors dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Alors le mort sortit, ayant les mains et les pieds liés de bandes; et son visage était enveloppé d’un couvre-chef. Jésus leur dit: déliez-le, et laissez-le aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'C’est pourquoi plusieurs des Juifs qui étaient venus vers Marie, et qui avaient vu ce que Jésus avait fait, crurent en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Mais quelques-uns d’entre eux s’en allèrent aux Pharisiens, et leur dirent les choses que Jésus avait faites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Alors les principaux Sacrificateurs et les Pharisiens assemblèrent le Conseil, et ils dirent: que faisons-nous? car cet homme fait beaucoup de miracles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Si nous le laissons faire, chacun croira en lui, et les Romains viendront, qui nous extermineront, nous, et le Lieu, et la Nation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Alors l’un d’eux appelé Caïphe, qui était le souverain Sacrificateur de cette année là, leur dit: vous n’y entendez rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'Et vous ne considérez pas qu’il est de notre intérêt qu’un homme meure pour le peuple, et que toute la Nation ne périsse point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Or il ne dit pas cela de lui-même, mais étant souverain Sacrificateur de cette année-là, il prophétisa que Jésus devait mourir pour la Nation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'Et non pas seulement pour la Nation, mais aussi pour assembler les enfants de Dieu, qui étaient dispersés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Depuis ce jour-là donc ils consultèrent ensemble pour le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'C’est pourquoi Jésus ne marchait plus ouvertement parmi les Juifs, mais il s’en alla de là dans la contrée qui est près du désert, en une ville appelée Ephraïm, et il demeura là avec ses Disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Or la Pâque des Juifs était proche, et plusieurs de ces pays-là montèrent à Jérusalem avant Pâque, afin de se purifier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Et ils cherchaient Jésus, et se disaient l’un à l’autre dans le Temple: que vous semble? croyez-vous qu’il ne viendra point à la Fête?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Or les principaux Sacrificateurs et les Pharisiens avaient donné ordre, que si quelqu’un savait où il était, il le déclarât, afin de se saisir de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Jésus donc six jours avant Pâque vint à Béthanie, où était Lazare qui avait été mort, et qu’il avait ressuscité des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Et on lui fit là un souper, et Marthe servait et Lazare était un de ceux qui étaient à table avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Alors Marie ayant pris une livre de nard pur de grand prix, en oignit les pieds de Jésus, et les essuya avec ses cheveux; et la maison fut remplie de l’odeur du parfum.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Alors Judas Iscariot, fils de Simon, l’un de ses Disciples, celui à qui il devait arriver de le trahir, dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Pourquoi ce parfum n’a-t-il pas été vendu trois cents deniers, et cet argent donné aux pauvres?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Or il dit cela, non point qu’il se souciât des pauvres, mais parce qu’il était larron, et qu’il avait la bourse, et portait ce qu’on y mettait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Mais Jésus lui dit: laisse-la faire; elle l’a gardé pour le jour de l’appareil de ma sépulture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Car vous aurez toujours des pauvres avec vous; mais vous ne m’aurez pas toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Et de grandes troupes des Juifs ayant su qu’il était là, y vinrent, non seulement à cause de Jésus, mais aussi pour voir Lazare, qu’il avait ressuscité des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Sur quoi les principaux Sacrificateurs résolurent de faire mourir aussi Lazare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'Car plusieurs des Juifs se retiraient d’avec eux à cause de lui, et croyaient en Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Le lendemain une grande quantité de peuple qui était venu à la Fête, ayant ouï dire que Jésus venait à Jérusalem,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Prirent des rameaux de palmes, et sortirent au-devant de lui, et ils criaient: Hosanna! béni soit le Roi d’Israël qui vient au Nom du Seigneur!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Et Jésus ayant recouvré un ânon, s’assit dessus, suivant ce qui est écrit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Ne crains point, fille de Sion; voici, ton Roi vient, assis sur le poulain d’une ânesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Or ses Disciples n’entendirent pas d’abord ces choses; mais quand Jésus fut glorifié, ils se souvinrent alors que ces choses étaient écrites de lui, et qu’ils avaient fait ces choses à son égard.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Et la troupe qui était avec lui, rendait témoignage qu’il avait appelé Lazare hors du sépulcre, et qu’il l’avait ressuscité des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'C’est pourquoi aussi le peuple alla au-devant de lui; car ils avaient appris qu’il avait fait ce miracle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Sur quoi les Pharisiens dirent entre eux: ne voyez-vous pas que vous n’avancez rien? voici, le monde va après lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Or il y avait quelques Grecs d’entre ceux qui étaient montés pour adorer Dieu pendant la Fête,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Lesquels vinrent à Philippe, qui était de Bethsaïda de Galilée, et le prièrent, disant: Seigneur! nous désirons de voir Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Philippe vint, et le dit à André, et André et Philippe le dirent à Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Et Jésus leur répondit, disant: l’heure est venue que le Fils de l’homme doit être glorifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'En vérité, en vérité je vous dis: si le grain de froment tombant dans la terre ne meurt point, il demeure seul; mais s’il meurt, il porte beaucoup de fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Celui qui aime sa vie, la perdra; et celui qui hait sa vie en ce monde, la conservera jusque dans la vie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Si quelqu’un me sert, qu’il me suive; et où je serai, là aussi sera celui qui me sert; et si quelqu’un me sert, mon Père l’honorera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Maintenant mon âme est agitée; et que dirai-je? ô Père! délivre-moi de cette heure; mais c’est pour cela que je suis venu à cette heure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Père glorifie ton Nom: Alors une voix vint du ciel, disant: et je l’ai glorifié, et je le glorifierai encore.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Et la troupe qui était là, et qui avait ouï cette voix, disait que c’était un tonnerre qui avait été fait; les autres disaient: un Ange lui a parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Jésus prit la parole, et dit: cette voix n’est point venue pour moi, mais pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Maintenant est venu le jugement de ce monde; maintenant le Prince de ce monde sera jeté dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'Et moi, quand je serai élevé de la terre, je tirerai tous les hommes à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Or il disait cela signifiant de quelle mort il devait mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Les troupes lui répondirent: nous avons appris par la Loi, que le Christ demeure éternellement, comment donc dis-tu qu’il faut que le Fils de l’homme soit élevé? Qui est ce Fils de l’homme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Alors Jésus leur dit: la lumière est encore avec vous pour un peu de temps: marchez pendant que vous avez la lumière, de peur que les ténèbres ne vous surprennent; car celui qui marche dans les ténèbres, ne sait où il va.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Pendant que vous avez la lumière croyez en la lumière, afin que vous soyez enfants de lumière. Jésus dit ces choses, puis il s’en alla, et se cacha de devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Et quoiqu’il eût fait tant de miracles devant eux, ils ne crurent point en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'De sorte que cette parole qui a été dite par Esaïe le Prophète, fut accomplie: Seigneur, qui a cru à notre parole, et à qui a été révélé le bras du Seigneur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'C’est pourquoi ils ne pouvaient croire, à cause qu’Esaïe dit encore:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, 'Il a aveuglé leurs yeux, et il a endurci leur coeur, afin qu’ils ne voient point de leurs yeux, et qu’ils n’entendent du coeur, et qu’ils ne soient convertis, et que je ne les guérisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Esaïe dit ces choses quand il vit sa gloire, et qu’il parla de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Cependant plusieurs des principaux mêmes crurent en lui; mais ils ne le confessaient point à cause des Pharisiens, de peur d’être chassés hors de la Synagogue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Car ils ont mieux aimé la gloire des hommes, que la gloire de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Or Jésus s’écria, et dit: celui qui croit en moi, ne croit point seulement en moi, mais en celui qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'Et celui qui me contemple, contemple celui qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Je suis venu au monde pour en être la lumière, afin que quiconque croit en moi ne demeure point dans les ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Et si quelqu’un entend mes paroles, et ne les croit point, je ne le juge point; car je ne suis point venu pour juger le monde, mais pour sauver le monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Celui qui me rejette, et ne reçoit point mes paroles, il a qui le juge: la parole que j’ai annoncée, sera celle qui le jugera au dernier jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Car je n’ai point parlé de moi-même, mais le Père qui m’a envoyé, m’a prescrit ce que j’ai à dire et de quoi je dois parler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'Et je sais que son commandement est la vie éternelle; les choses donc que je dis, je les dis comme mon Père me les a dites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Or avant la Fête de Pâque, Jésus sachant que son heure était venue pour passer de ce monde au Père, comme il avait aimé les siens, qui étaient au monde, il les aima jusqu’à la fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Et après le souper, le Démon ayant déjà mis au coeur de Judas Iscariot, fils de Simon, de le trahir;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Et Jésus sachant que le Père lui avait donné toutes choses entre les mains, et qu’il était venu de Dieu, et s’en allait à Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Se leva du souper, et ôta sa robe, et ayant pris un linge, il s’en ceignit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Puis il mit de l’eau dans un bassin, et se mit à laver les pieds de ses Disciples, et à les essuyer avec le linge dont il était ceint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Alors il vint à Simon Pierre; mais Pierre lui dit: Seigneur me laves- tu les pieds?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jésus répondit, et lui dit: tu ne sais pas maintenant ce que je fais, mais tu le sauras après ceci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Pierre lui dit: tu ne me laveras jamais les pieds. Jésus lui répondit: si je ne te lave, tu n’auras point de part avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Simon Pierre lui dit: Seigneur, non seulement mes pieds, mais aussi les mains et la tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Jésus lui dit: celui qui est lavé, n’a besoin sinon qu’on lui lave les pieds, et alors il est tout net; or vous êtes nets, mais non pas tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Car il savait qui était celui qui le trahirait; c’est pourquoi il dit: vous n’êtes pas tous nets.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Après donc qu’il eut lavé leurs pieds, il reprit ses vêtements, et s’étant remis à table, il leur dit: savez-vous bien ce que je vous ai fait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Vous m’appelez Maître et Seigneur; et vous dites bien: car je le suis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Si donc moi, qui suis le Seigneur et le Maître, j’ai lavé vos pieds, vous devez aussi vous laver les pieds les uns des autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Car je vous ai donné un exemple, afin que comme je vous ai fait, vous fassiez de même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'En vérité, en vérité je vous dis: que le serviteur n’est point plus grand que son maître, ni l’ambassadeur plus grand que celui qui l’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Si vous savez ces choses, vous êtes bienheureux, si vous les faites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Je ne parle point de vous tous, je sais ceux que j’ai élus, mais il faut que cette Ecriture soit accomplie, qui dit: celui qui mange le pain avec moi, a levé son talon contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Je vous dis ceci dès maintenant, et avant qu’il arrive, afin que quand il sera arrivé, vous croyiez que c’est moi que le Père a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'En vérité, en vérité je vous dis: si j’envoie quelqu’un, celui qui le reçoit, me reçoit; et celui qui me reçoit, reçoit celui qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Quand Jésus eut dit ces choses, il fut ému dans son esprit, et il déclara, et dit: en vérité, en vérité je vous dis, que l’un de vous me trahira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Alors les Disciples se regardaient les uns les autres, étant en perplexité duquel il parlait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Or un des Disciples de Jésus, celui que Jésus aimait, était à table en son sein;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Et Simon Pierre lui fit signe de demander qui était celui dont Jésus parlait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Lui donc étant penché dans le sein de Jésus, lui dit: Seigneur, qui est-ce?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Jésus répondit: c’est celui à qui je donnerai le morceau trempé; et ayant trempé le morceau, il le donna à Judas Iscariot, fils de Simon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Et après le morceau, alors Satan entra en lui; Jésus donc lui dit: fais bientôt ce que tu fais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Mais aucun de ceux qui étaient à table ne comprit pourquoi il lui avait dit cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Car quelques-uns pensaient qu’à cause que Judas avait la bourse, Jésus lui eût dit: achète ce qui nous est nécessaire pour la Fête; ou qu’il donnât quelque chose aux pauvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Après donc que Judas eut pris le morceau, il partit aussitôt; or il était nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Et comme il fut sorti, Jésus dit: maintenant le Fils de l’homme est glorifié; et Dieu est glorifié en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Que si Dieu est glorifié en lui, Dieu aussi le glorifiera en soi-même, et même bientôt il le glorifiera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Mes petits enfants, je suis encore pour un peu de temps avec vous; vous me chercherez, mais comme j’ai dit aux Juifs, que là où je vais ils n’y pouvaient venir, je vous le dis aussi maintenant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Je vous donne un nouveau commandement, que vous vous aimiez l’un l’autre, et que comme je vous ai aimés, vous vous aimiez aussi l’un l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'En ceci tous connaîtront que vous êtes mes Disciples, si vous avez de l’amour l’un pour l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Simon Pierre lui dit: Seigneur! où vas-tu? Jésus lui répondit: là où je vais, tu ne me peux maintenant suivre, mais tu me suivras ci-après.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Pierre lui dit: Seigneur! pourquoi ne te puis-je pas maintenant suivre? j’exposerai ma vie pour toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jésus lui répondit: tu exposeras ta vie pour moi? En vérité, en vérité je te dis, que le coq ne chantera point, que tu ne m’aies renié trois fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Que votre coeur ne soit point alarmé; vous croyez en Dieu, croyez aussi en moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Il y a plusieurs demeures dans la Maison de mon Père; s’il était autrement, je vous l’eusse dit; je vais vous préparer le lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Et quand je m’en serai allé, et que je vous aurai préparé le lieu, je retournerai, et je vous prendrai avec moi; afin que là où je suis, vous y soyez aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Et vous savez où je vais, et vous en savez le chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Thomas lui dit: Seigneur! nous ne savons point où tu vas, comment donc pouvons-nous en savoir le chemin?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jésus lui dit: je suis le chemin, et la vérité, et la vie; nul ne vient au Père que par moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Si vous me connaissiez, vous connaîtriez aussi mon Père; mais dès maintenant vous le connaissez, et vous l’avez vu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Philippe lui dit: Seigneur! montre-nous le Père, et cela nous suffit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jésus lui répondit: je suis depuis si longtemps avec vous, et tu ne m’as point connu? Philippe, celui qui m’a vu, a vu mon Père; et comment dis-tu: montre-nous le Père?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Ne crois-tu pas que je suis en mon Père, et que le Père est en moi? les paroles que je vous dis, je ne les dis pas de moi-même; mais le Père qui demeure en moi, est celui qui fait les oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Croyez-moi que je suis en mon Père, et que le Père est en moi, sinon, croyez-moi à cause de ces oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'En vérité, en vérité je vous dis, celui qui croit en moi, fera les oeuvres que je fais, et il en fera même de plus grandes que celles-ci, parce que je m’en vais à mon Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'Et quoi que vous demandiez en mon Nom, je le ferai; afin que le Père soit glorifié par le Fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Si vous demandez en mon Nom quelque chose, je la ferai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Si vous m’aimez, gardez mes commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Et je prierai le Père, et il vous donnera un autre Consolateur, pour demeurer avec vous éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Savoir l’Esprit de vérité, lequel le monde ne peut point recevoir; parce qu’il ne le voit point, et qu’il ne le connaît point; mais vous le connaissez, car il demeure avec vous, et il sera en vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Je ne vous laisserai point orphelins; je viendrai vers vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Encore un peu de temps, et le monde ne me verra plus, mais vous me verrez; et parce que je vis, vous aussi vous vivrez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'En ce jour-là vous connaîtrez que je suis en mon Père, et vous en moi, et moi en vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Celui qui a mes commandements, et qui les garde, c’est celui qui m’aime; et celui qui m’aime sera aimé de mon Père; je l’aimerai, et je me manifesterai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Jude (non pas Iscariot) lui dit: Seigneur! d’où vient que tu te feras connaître à nous, et non pas au monde?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jésus répondit, et lui dit: si quelqu’un m’aime il gardera ma parole, et mon Père l’aimera, et nous viendrons à lui, et nous ferons notre demeure chez lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Celui qui ne m’aime point, ne garde point mes paroles. Et la parole que vous entendez n’est point ma parole, mais c’est celle du Père qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Je vous ai dit ces choses demeurant avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Mais le Consolateur, qui est le Saint-Esprit, que le Père enverra en mon Nom, vous enseignera toutes choses, et il vous rappellera le souvenir de toutes les choses que je vous ai dites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Je vous laisse la paix, je vous donne ma paix; je ne vous la donne point comme le monde la donne; que votre coeur ne soit point agité ni craintif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Vous avez entendu que je vous ai dit: je m’en vais, et je reviens à vous; si vous m’aimiez, vous seriez certes joyeux de ce que j’ai dit: je m’en vais au Père: car le Père est plus grand que moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Et maintenant je vous l’ai dit avant que cela soit arrivé, afin que quand il sera arrivé, vous croyiez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Je ne parlerai plus guère avec vous; car le Prince de ce monde vient; mais il n’a aucun empire sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Mais afin que le monde connaisse que j’aime le Père, et que je fais ce que le Père m’a commandé. Levez-vous, partons d’ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Je suis le vrai Cep, et mon Père est le Vigneron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Il retranche tout le sarment qui ne porte point de fruit en moi, et il émonde tout celui qui porte du fruit, afin qu’il porte plus de fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Vous êtes déjà nets par la parole que je vous ai enseignée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Demeurez en moi, et moi en vous; comme le sarment ne peut point de lui-même porter de fruit, s’il ne demeure au cep; vous ne le pouvez point aussi, si vous ne demeurez en moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Je suis le Cep, et vous en êtes les sarments; celui qui demeure en moi, et moi en lui, porte beaucoup de fruit; car hors de moi, vous ne pouvez rien produire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Si quelqu’un ne demeure point en moi, il est jeté dehors comme le sarment, et il se sèche; puis on l’amasse, et on le met au feu, et il brûle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Si vous demeurez en moi, et que mes paroles demeurent en vous, demandez tout ce que vous voudrez, et il vous sera fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'En ceci mon Père est glorifié, que vous portiez beaucoup de fruit; et vous serez alors mes disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Comme le Père m’a aimé, ainsi je vous ai aimés, demeurez en mon amour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Si vous gardez mes commandements, vous demeurerez en mon amour; comme j’ai gardé les commandements de mon Père, et je demeure en son amour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Je vous ai dit ces choses afin que ma joie demeure en vous, et que votre joie soit parfaite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'C’est ici mon commandement, que vous vous aimiez l’un l’autre, comme je vous ai aimés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Personne n’a un plus grand amour que celui-ci, savoir, quand quelqu’un expose sa vie pour ses amis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Vous serez mes amis, si vous faites tout ce que je vous commande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Je ne vous appelle plus serviteurs, car le serviteur ne sait point ce que son maître fait; mais je vous ai appelés mes amis, parce que je vous ai fait connaître tout ce que j’ai ouï de mon Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Ce n’est pas vous qui m’avez élu, mais c’est moi qui vous ai élus, et qui vous ai établis, afin que vous alliez partout et que vous produisiez du fruit, et que votre fruit soit permanent; afin que tout ce que vous demanderez au Père en mon Nom, il vous le donne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Je vous commande ces choses, afin que vous vous aimiez l’un l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Si le monde vous hait, sachez que j’en ai été haï avant vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Si vous eussiez été du monde, le monde aimerait ce qui serait sien; mais parce que vous n’êtes pas du monde, et que je vous ai élus du monde, à cause de cela le monde vous hait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Souvenez-vous de la parole que je vous ai dite, que le serviteur n’est pas plus grand que son maître; s’ils m’ont persécuté, ils vous persécuteront aussi; s’ils ont gardé ma parole, ils garderont aussi la vôtre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Mais ils vous feront toutes ces choses à cause de mon Nom, parce qu’ils ne connaissent point celui qui m’a envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Si je ne fusse point venu, et que je ne leur eusse point parlé, ils n’auraient point de péché, mais maintenant ils n’ont point d’excuse de leur péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Celui qui me hait, hait aussi mon Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Si je n’eusse pas fait parmi eux les oeuvres qu’aucun autre n’a faites, ils n’auraient point de péché; mais maintenant ils les ont vues, et toutefois ils ont haï et moi et mon Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Mais c’est afin que soit accomplie la parole qui est écrite en leur Loi: ils m’ont haï sans sujet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Mais quand le Consolateur sera venu, lequel je vous enverrai de la part de mon Père, savoir l’Esprit de vérité, qui procède de mon Père, celui-là rendra témoignage de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'Et vous aussi vous en rendrez témoignage: car vous êtes dès le commencement avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Je vous ai dit ces choses, afin que vous ne soyez point scandalisés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Ils vous chasseront des Synagogues; même le temps vient que quiconque vous fera mourir, croira servir Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Et ils vous feront ces choses, parce qu’ils n’ont point connu le Père, ni moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Mais je vous ai dit ces choses, afin que quand l’heure sera venue, il vous souvienne que je vous les ai dites; et je ne vous ai point dit ces choses dès le commencement, parce que j’étais avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Mais maintenant je m’en vais à celui qui m’a envoyé, et aucun de vous ne me demande: où vas-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Mais parce que je vous ai dit ces choses, la tristesse a rempli votre coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Toutefois je vous dis la vérité, il vous est avantageux que je m’en aille, car si je ne m’en vais, le Consolateur ne viendra point à vous; mais si je m’en vais, je vous l’enverrai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Et quand il sera venu, il convaincra le monde de péché, de justice, et de jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'De péché, parce qu’ils ne croient point en moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'De justice, parce que je m’en vais à mon Père, et que vous ne me verrez plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'De jugement, parce que le Prince de ce monde est déjà jugé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'J’ai à vous dire encore plusieurs choses, mais elles sont encore au- dessus de votre portée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Mais quand celui-là, savoir l’Esprit de vérité, sera venu, il vous conduira en toute vérité; car il ne parlera point de soi-même, mais il dira tout ce qu’il aura ouï, et il vous annoncera les choses à venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Celui-là me glorifiera; car il prendra du mien, et il vous l’annoncera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Tout ce que mon Père a, est mien; c’est pourquoi j’ai dit, qu’il prendra du mien, et qu’il vous l’annoncera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Dans peu de temps, vous ne me verrez point; et après un peu de temps, vous me verrez: car je m’en vais à mon Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Et quelques-uns de ses Disciples dirent entre eux: qu’est-ce qu’il nous dit: dans peu de temps, vous ne me verrez point; et un peu de temps après vous me verrez, car je m’en vais à mon Père?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Ils disaient donc: que signifient ces mots: un peu de temps? nous ne comprenons pas ce qu’il dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Et Jésus connaissant qu’ils le voulaient interroger, leur dit: vous demandez entre vous touchant ce que j’ai dit: dans peu de temps, vous ne me verrez plus, et un peu de temps après vous me verrez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'En vérité, en vérité je vous dis, que vous pleurerez et vous vous lamenterez, et le monde se réjouira; vous serez, dis-je, attristés; mais votre tristesse sera changée en joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Quand une femme accouche, elle sent des douleurs, parce que son terme est venu, mais après qu’elle a fait un petit enfant, il ne lui souvient plus de ses douleurs, à cause de la joie qu’elle a de ce qu’elle a mis un homme au monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Vous avez donc aussi maintenant de la tristesse; mais je vous reverrai encore, et votre coeur se réjouira, et personne ne vous ôtera votre joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'Et en ce jour-là vous ne m’interrogerez de rien. En vérité, en vérité je vous dis, que toutes les choses que vous demanderez au Père en mon Nom, il vous les donnera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Jusqu’à présent vous n’avez rien demandé en mon Nom; demandez, et vous recevrez, afin que votre joie soit parfaite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Je vous ai dit ces choses par des similitudes, mais l’heure vient que je ne vous parlerai plus par des paraboles; mais je vous parlerai ouvertement de mon Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'En ce jour-là vous demanderez des grâces en mon Nom, et je ne vous dis pas que je prierai le Père pour vous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Car le Père lui-même vous aime, parce que vous m’avez aimé, et que vous avez cru, que je suis issu de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Je suis issu du Père, et je suis venu au monde; et encore, je laisse le monde, et je m’en vais au Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Ses Disciples lui dirent: voici, maintenant tu parles ouvertement, et tu n’uses plus de paraboles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Maintenant nous connaissons que tu sais toutes choses, et que tu n’as pas besoin que personne t’interroge; à cause de cela nous croyons que tu es issu de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Jésus leur répondit: croyez vous maintenant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Voici, l’heure vient, et elle est déjà venue, que vous serez dispersés chacun de son côté, et vous me laisserez seul; mais je ne suis point seul, car le Père est avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Je vous ai dit ces choses afin que vous ayez la paix en moi; vous aurez de l’angoisse au monde, mais ayez bon courage, j’ai vaincu le monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Jésus dit ces choses; puis levant ses yeux au ciel, il dit: Père, l’heure est venue, glorifie ton Fils, afin que ton Fils te glorifie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Comme tu lui as donné pouvoir sur tous les hommes; afin qu’il donne la vie éternelle à tous ceux que tu lui as donnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Et c’est ici la vie éternelle, qu’ils te connaissent seul vrai Dieu, et celui que tu as envoyé, Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Je t’ai glorifié sur la terre, j’ai achevé l’oeuvre que tu m’avais donnée à faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'Et maintenant glorifie-moi, toi Père, auprès de toi, de la gloire que j’ai eue chez toi, avant que le monde fût fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'J’ai manifesté ton Nom aux hommes que tu m’as donnés du monde; ils étaient tiens, et tu me les as donnés; et ils ont gardé ta parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Maintenant ils ont connu que tout ce que tu m’as donné, vient de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Car je leur ai donné les paroles que tu m’as données, et ils les ont reçues, et ils ont vraiment connu que je suis issu de toi, et ils ont cru que tu m’as envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Je prie pour eux; je ne prie point pour le monde, mais pour ceux que tu m’as donnés, parce qu’ils sont tiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'Et tout ce qui est mien est tien, et ce qui est tien est mien; et je suis glorifié en eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Et maintenant je ne suis plus au monde, mais ceux-ci sont au monde; et moi je vais à toi, Père saint, garde-les en ton Nom, ceux, dis-je, que tu m’as donnés, afin qu’ils soient un, comme nous sommes un.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Quand j’étais avec eux au monde, je les gardais en ton Nom; j’ai gardé ceux que tu m’as donnés, et pas un d’eux n’est péri, sinon le fils de perdition, afin que l’Ecriture fût accomplie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Et maintenant je viens à toi, et je dis ces choses étant encore au monde, afin qu’ils aient ma joie parfaite en eux-mêmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Je leur ai donné ta parole, et le monde les a haïs, parce qu’ils ne sont point du monde, comme aussi je ne suis point du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Je ne te prie point que tu les ôtes du monde, mais de les préserver du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Ils ne sont point du monde, comme aussi je ne suis point du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Sanctifie-les par ta vérité; ta parole est la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Comme tu m’as envoyé au monde, ainsi je les ai envoyés au monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'Et je me sanctifie moi-même pour eux, afin qu’eux aussi soient sanctifiés dans la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Or je ne prie point seulement pour eux, mais aussi pour ceux qui croiront en moi par leur parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'Afin que tous soient un, ainsi que toi, Père, es en moi, et moi en toi; afin qu’eux aussi soient un en nous; et que le monde croie que c’est toi qui m’as envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Et je leur ai donné la gloire que tu m’as donnée, afin qu’ils soient un comme nous sommes un.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Je suis en eux, et toi en moi, afin qu’ils soient consommés en un, et que le monde connaisse que c’est toi qui m’as envoyé, et que tu les aimes, comme tu m’as aimé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Père, mon désir est touchant ceux que tu m’as donnés, que là où je suis, ils y soient aussi avec moi, afin qu’ils contemplent ma gloire, laquelle tu m’as donnée; parce que tu m’as aimé avant la fondation du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Père juste, le monde ne t’a point connu; mais moi je t’ai connu, et ceux-ci ont connu que c’est toi qui m’as envoyé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Et je leur ai fait connaître ton Nom, et je le leur ferai connaître, afin que l’amour dont tu m’as aimé, soit en eux, et moi en eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Après que Jésus eut dit ces choses, il s’en alla avec ses Disciples au delà du torrent de Cédron, où il y avait un Jardin, dans lequel il entra avec ses Disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Or Judas qui le trahissait, connaissait aussi ce lieu-là, car Jésus s’y était souvent assemblé avec ses Disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Judas donc ayant pris une compagnie de soldats, et des huissiers de la part des principaux Sacrificateurs et des Pharisiens, s’en vint là avec des lanternes et des flambeaux, et des armes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Et Jésus sachant toutes les choses qui lui devaient arriver, s’avança, et leur dit: qui cherchez-vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Ils lui répondirent: Jésus le Nazarien. Jésus leur dit: c’est moi. Et Judas qui le trahissait, était aussi avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Or après que Jésus leur eut dit: c’est moi, ils reculèrent, et tombèrent par terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Il leur demanda une seconde fois: qui cherchez-vous? Et ils répondirent: Jésus le Nazarien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jésus répondit: je vous ai dit que c’est moi; si donc vous me cherchez, laissez aller ceux-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'C’était afin que la parole qu’il avait dite fût accomplie: je n’ai perdu aucun de ceux que tu m’as donnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Or Simon Pierre ayant une épée, la tira, et en frappa un serviteur du souverain sacrificateur, et lui coupa l’oreille droite; et ce serviteur avait nom Malchus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Mais Jésus dit à Pierre: remets ton épée au fourreau: ne boirai-je pas la coupe que le Père m’a donnée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Alors la compagnie, le capitaine, et les huissiers des Juifs se saisirent de Jésus, et le lièrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'Et ils l’emmenèrent premièrement à Anne: car il était beau-père de Caïphe, qui était le souverain Sacrificateur de cette année-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Or Caïphe était celui qui avait donné ce conseil aux Juifs, qu’il était utile qu’un homme mourût pour le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Or Simon Pierre avec un autre Disciple suivait Jésus, et ce Disciple était connu du souverain Sacrificateur, et il entra avec Jésus dans la cour du souverain Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Mais Pierre était dehors à la porte, et l’autre Disciple qui était connu du souverain Sacrificateur, sortit dehors, et parla à la portière, laquelle fit entrer Pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Et la servante qui était la portière, dit à Pierre: n’es-tu point aussi des Disciples de cet homme? Il dit: je n’en suis point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Or les serviteurs et les huissiers ayant fait du feu, étaient là, parce qu’il faisait froid, et ils se chauffaient; Pierre aussi était avec eux, et se chauffait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Et le souverain Sacrificateur interrogea Jésus touchant ses Disciples, et touchant sa doctrine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jésus lui répondit: j’ai ouvertement parlé au monde; j’ai toujours enseigné dans la Synagogue et dans le Temple, où les Juifs s’assemblent toujours, et je n’ai rien dit en secret.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Pourquoi m’interroges-tu? interroge ceux qui ont ouï ce que je leur ai dit; voilà, ils savent ce que j’ai dit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Quand il eut dit ces choses, un des huissiers qui se tenait là, donna un coup de sa verge à Jésus, en lui disant: est-ce ainsi que tu réponds au souverain Sacrificateur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jésus lui répondit: si j’ai mal parlé, rends témoignage du mal; et si j’ai bien parlé, pourquoi me frappes-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Or Anne l’avait envoyé lié à Caïphe, souverain Sacrificateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Et Simon Pierre était là, et se chauffait; et ils lui dirent: n’es- tu pas aussi de ses Disciples; il le nia, et dit: je n’en suis point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Et un des serviteurs du souverain Sacrificateur, parent de celui à qui Pierre avait coupé l’oreille, dit: ne t’ai-je pas vu au jardin avec lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Mais Pierre le nia encore, et incontinent le coq chanta.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Puis ils menèrent Jésus de chez Caïphe au Prétoire (or c’était le matin) mais ils n’entrèrent point au Prétoire, de peur qu’ils ne fussent souillés, et afin de pouvoir manger l’agneau de pâque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'C’est pourquoi Pilate sortit vers eux, et leur dit: quelle accusation portez-vous contre cet homme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Ils répondirent, et lui dirent: si ce n’était pas un criminel, nous ne te l’eussions pas livré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Alors Pilate leur dit: prenez-le vous-mêmes, et jugez-le selon votre Loi. Mais les Juifs lui dirent: il ne nous est pas permis de faire mourir personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'Et cela arriva ainsi afin que la parole que Jésus avait dite, fût accomplie, indiquant de quelle mort il devait mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Pilate donc entra encore au Prétoire, et ayant appelé Jésus, il lui dit: es-tu le Roi des Juifs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jésus lui répondit: dis-tu ceci de toi-même, ou sont-ce les autres qui te l’ont dit de moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilate répondit: suis-je Juif? ta nation et les principaux Sacrificateurs t’ont livré à moi; qu’as-tu fait?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jésus répondit: mon Règne n’est pas de ce monde; si mon Règne était de ce monde, mes gens combattraient afin que je ne fusse point livré aux Juifs; mais maintenant mon Règne n’est point d’ici-bas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Alors Pilate lui dit: es-tu donc Roi? Jésus répondit: tu le dis, que je suis Roi; je suis né pour cela, et c’est pour cela que je suis venu au monde, afin que je rende témoignage à la vérité; quiconque est de la vérité, entend ma voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Pilate lui dit: qu’est-ce que la vérité? Et quand il eut dit cela, il sortit encore vers les Juifs, et il leur dit: je ne trouve aucun crime en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Or vous avez une coutume: qui est que je vous relâche un prisonnier à la fête de Pâque; voulez-vous donc que je vous relâche le Roi des Juifs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Et tous s’écrièrent encore, disant: non pas celui-ci, mais Barrabas; or Barrabas était un brigand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Pilate fit donc alors prendre Jésus, et le fit fouetter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Et les soldats firent une couronne d’épines qu’ils mirent sur sa tête, et le vêtirent d’un vêtement de pourpre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'Puis ils lui disaient: Roi des Juifs, nous te saluons; et ils lui donnaient des coups avec leurs verges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Et Pilate sortit encore dehors, et leur dit: voici, je vous l’amène dehors, afin que vous sachiez que je ne trouve aucun crime en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Jésus donc sortit portant la couronne d’épines, et le vêtement de pourpre; et Pilate leur dit: voici l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Mais quand les principaux Sacrificateurs et leurs huissiers le virent, ils s’écrièrent, en disant: crucifie, crucifie. Pilate leur dit: prenez-le vous-mêmes, et le crucifiez: car je ne trouve point de crime en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Les Juifs lui répondirent: nous avons une loi, et selon notre loi il doit mourir, car il s’est fait Fils de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Or quand Pilate eut ouï cette parole, il craignit encore davantage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'Et il rentra dans le Prétoire, et dit à Jésus: d’où es-tu? Mais Jésus ne lui donna point de réponse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Et Pilate lui dit: ne me parles-tu point? ne sais-tu pas que j’ai le pouvoir de te crucifier, et le pouvoir de te délivrer?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jésus lui répondit: tu n’aurais aucun pouvoir sur moi, s’il ne t’était donné d’en haut; c’est pourquoi celui qui m’a livré à toi, a fait un plus grand péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Depuis cela Pilate tâchait à le délivrer; mais les Juifs criaient, en disant: si tu délivres celui-ci tu n’es point ami de César; car quiconque se fait Roi, est contraire à César.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Quand Pilate eut ouï cette parole, il amena Jésus dehors, et s’assit au Siège judicial, dans le lieu qui est appelé le Pavé, et en Hébreu Gabbatha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Or c’était la préparation de la Pâque, et il était environ six heures; et Pilate dit aux Juifs: voilà votre Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Mais ils criaient: ôte, ôte, crucifie-le. Pilate leur dit: crucifierai-je votre Roi? Les principaux Sacrificateurs répondirent: nous n’avons point d’autre Roi que César.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Alors donc il le leur livra pour être crucifié. Ils prirent donc Jésus, et l’emmenèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Et Jésus portant sa croix, vint au lieu appelé le Calvaire, et en Hébreu Golgotha;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Où ils le crucifièrent, et deux autres avec lui, un de chaque côté, et Jésus au milieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Or Pilate fit un écriteau, qu’il mit sur la croix, où étaient écrits ces mots: JESUS NAZARIEN LE ROI DES JUIFS.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Et plusieurs des Juifs lurent cet écriteau, parce que le lieu où Jésus était crucifié, était près de la ville; et cet écriteau était en Hébreu, en Grec, et en Latin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'C’est pourquoi les principaux Sacrificateurs des Juifs dirent à Pilate: n’écris point, le Roi des Juifs; mais, que celui-ci a dit: je suis le Roi des Juifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilate répondit: ce que j’ai écrit, je l’ai écrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Or quand les soldats eurent crucifié Jésus, ils prirent ses vêtements, et en firent quatre parts, une part pour chaque soldat; ils prirent aussi la tunique; mais elle était sans couture, tissue depuis le haut jusqu’en bas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Et ils dirent entre eux: ne la mettons point en pièces, mais jetons- la au sort, pour savoir à qui elle sera. Et cela arriva ainsi, afin que l’Ecriture fût accomplie, disant: ils ont partagé entre eux mes vêtements, et ils ont jeté au sort ma robe; les soldats donc firent ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Or près de la croix de Jésus étaient sa mère, et la soeur de sa mère, savoir Marie femme de Cléopas, et Marie Magdelaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Et Jésus voyant sa mère, et auprès d’elle le Disciple qu’il aimait, il dit à sa mère: femme, voilà ton Fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Puis il dit au Disciple: voilà ta Mère; et dès cette heure-là ce Disciple la reçut chez lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Après cela Jésus sachant que toutes choses étaient déjà accomplies, il dit, afin que l’Ecriture fût accomplie: j’ai soif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Et il y avait là un vase plein de vinaigre, ils emplirent donc de vinaigre une éponge, et la mirent au bout d’une branche d’hysope, et la lui présentèrent à la bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Et quand Jésus eut pris le vinaigre, il dit: tout est accompli; et ayant baissé la tête, il rendit l’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Alors les Juifs, afin que les corps ne demeurassent point en croix au jour du Sabbat, parce que c’était la préparation, (or c’était un grand jour du Sabbat) prièrent Pilate qu’on leur rompît les jambes, et qu’on les ôtât.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Les soldats donc vinrent, et rompirent les jambes au premier, et de même à l’autre qui était crucifié avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Puis étant venus à Jésus, et voyant qu’il était déjà mort, ils ne lui rompirent point les jambes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'Mais un des soldats lui perça le côté avec une lance, et d’abord il en sortit du sang et de l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Et celui qui l’a vu, l’a témoigné, et son témoignage est digne de foi; et celui-là sait qu’il dit vrai, afin que vous le croyiez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Car ces choses-là sont arrivées afin que cette Ecriture fût accomplie: pas un de ses os ne sera cassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Et encore une autre Ecriture, qui dit: ils verront celui qu’ils ont percé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Or après ces choses, Joseph d’Arimathée, qui était Disciple de Jésus, secret toutefois parce qu’il craignait les Juifs, pria Pilate qu’il lui permît d’ôter le corps de Jésus; et Pilate le lui ayant permis, il vint, et prit le corps de Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Nicodème aussi, celui qui auparavant était allé de nuit à Jésus, y vint apportant une mixtion de myrrhe et d’aloès d’environ cent livres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Et ils prirent le corps de Jésus, et l’enveloppèrent de linges avec des Aromates, comme les Juifs ont coutume d’ensevelir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Or il y avait au lieu où il fut crucifié un jardin, et dans le jardin un sépulcre neuf, où personne n’avait encore été mis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Et ils mirent là Jésus, à cause de la préparation des Juifs, parce que le sépulcre était près.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'Or le premier jour de la semaine Marie Magdelaine vint le matin au sépulcre, comme il faisait encore obscur; et elle vit que la pierre était ôtée du sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Et elle courut, et vint à Simon Pierre, et à l’autre Disciple que Jésus aimait, et elle leur dit: on a enlevé le Seigneur hors du sépulcre, mais nous ne savons pas où on l’a mis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Alors Pierre partit avec l’autre Disciple, et ils s’en allèrent au sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Et ils couraient tous deux ensemble; mais l’autre Disciple courait plus vite que Pierre, et il arriva le premier au sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'Et s’étant baissé, il vit les linges à terre; mais il n’y entra point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Alors Simon Pierre qui le suivait, arriva, et entra dans le sépulcre, et vit les linges à terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'Et le suaire qui avait été sur la tête de Jésus, lequel n’était point mis avec les linges, mais était enveloppé en un lieu à part.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Alors l’autre Disciple, qui était arrivé le premier au sépulcre, y entra aussi, et il vit, et crut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Car ils ne savaient pas encore l’Ecriture, qui porte qu’il devait ressusciter des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Et les Disciples s’en retournèrent chez eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Mais Marie se tenait près du sépulcre dehors, en pleurant; et comme elle pleurait, elle se baissa dans le sépulcre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'Et vit deux Anges vêtus de blanc, assis l’un à la tête, et l’autre aux pieds, là où le corps de Jésus avait été couché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Et ils lui dirent: femme, pourquoi pleures-tu? Elle leur dit: parce qu’on a enlevé mon Seigneur; et je ne sais point où on l’a mis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Et quand elle eut dit cela, se tournant en arrière, elle vit Jésus qui était là; mais elle ne savait pas que ce fût Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Jésus lui dit: femme, pourquoi pleures-tu? Qui cherches-tu? Elle pensant que ce fût le jardinier, lui dit: Seigneur, si tu l’as emporté, dis-moi où tu l’as mis, et je l’ôterai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Jésus lui dit: Marie! Et elle s’étant retournée, lui dit: Rabboni! c’est-à-dire, mon Maître!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Jésus lui dit: ne me touche point; car je ne suis point encore monté vers mon Père; mais va à mes Frères, et leur dis: je monte vers mon Père, et vers votre Père, vers mon Dieu, et vers votre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Marie Magdelaine vint annoncer aux Disciples qu’elle avait vu le Seigneur, et qu’il lui avait dit ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Et quand le soir de ce jour-là, qui était le premier de la semaine, fut venu, et que les portes du lieu où les Disciples étaient assemblés à cause de la crainte qu’ils avaient des Juifs, étaient fermées: Jésus vint, et fut là au milieu d’eux, et il leur dit: que la paix soit avec vous!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Et quand il leur eut dit cela, il leur montra ses mains et son côté; et les Disciples eurent une grande joie, quand ils virent le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Et Jésus leur dit encore: que la paix soit avec vous! comme mon Père m’a envoyé, ainsi je vous envoie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Et quand il eut dit cela, il souffla sur eux, et leur dit: recevez le Saint-Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'A quiconque vous pardonnerez les péchés, ils seront pardonnés; et à quiconque vous les retiendrez, ils seront retenus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Or Thomas, appelé Didyme, qui était l’un des douze, n’était point avec eux quand Jésus vint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Et les autres Disciples lui dirent: nous avons vu le Seigneur. Mais il leur dit: si je ne vois les marques des clous en ses mains, et si je ne mets mon doigt où étaient les clous, et si je ne mets ma main dans son côté, je ne le croirai point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Et huit jours après ses Disciples étant encore dans la maison, et Thomas avec eux, Jésus vint, les portes étant fermées, et fut là au milieu d’eux, et il leur dit: Que la paix soit avec vous!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Puis il dit à Thomas: mets ton doigt ici, et regarde mes mains, avance aussi ta main, et la mets dans mon côté; et ne sois point incrédule, mais fidèle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Et Thomas répondit, et lui dit: Mon Seigneur, et mon Dieu!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Jésus lui dit: parce que tu m’as vu, Thomas, tu as cru; bienheureux sont ceux qui n’ont point vu, et qui ont cru.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Jésus fit aussi en la présence de ses Disciples plusieurs autres miracles, qui ne sont point écrits dans ce Livre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Mais ces choses sont écrites afin que vous croyiez que Jésus est le Christ, le Fils de Dieu, et qu’en croyant vous ayez la vie par son Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Après cela Jésus se fit voir encore à ses Disciples, près de la mer de Tibériade, et il s’y fit voir en cette manière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Simon Pierre et Thomas, appelé Didyme, et Nathanaël, qui était de Cana de Galilée, et les fils de Zébédée, et deux autres de ses Disciples étaient ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Simon Pierre leur dit: je m’en vais pêcher. Ils lui dirent: nous y allons avec toi. Ils partirent donc, et ils montèrent d’abord dans la nacelle; mais ils ne prirent rien cette nuit-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Et le matin étant venu, Jésus se trouva sur le rivage; mais les Disciples ne connurent point que ce fût Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Et Jésus leur dit: mes enfants, avez-vous quelque petit poisson à manger? ils lui répondirent: Non.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Et il leur dit: jetez le filet au côté droit de la nacelle, et vous en trouverez. Ils le jetèrent donc, et ils ne le pouvaient tirer à cause de la multitude des poissons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'C’est pourquoi le Disciple que Jésus aimait, dit à Pierre: c’est le Seigneur. Et quand Simon Pierre eut entendu que c’était le Seigneur, il ceignit sa tunique, parce qu’il était nu, et se jeta dans la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Et les autres Disciples vinrent dans la nacelle, car ils n’étaient pas loin de terre, mais seulement environ deux cents coudées, traînant le filet de poissons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Et quand ils furent descendus à terre, ils virent de la braise, et du poisson mis dessus, et du pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Jésus leur dit: apportez des poissons que vous venez maintenant de prendre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Simon Pierre monta, et tira le filet à terre, plein de cent cinquante- trois grands poissons; et quoiqu’il y en eût tant, le filet ne fut point rompu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Jésus leur dit: venez, et dînez. Et aucun de ses Disciples n’osait lui demander: qui es-tu? voyant bien que c’était le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Jésus donc vint, et prit du pain, et leur en donna, et du poisson aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Ce fut déjà la troisième fois que Jésus se fit voir à ses Disciples, après être ressuscité des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Et après qu’ils eurent dîné, Jésus dit à Simon Pierre: Simon fils de Jonas, m’aimes-tu plus que ne font ceux-ci? Il lui répondit: oui, Seigneur! tu sais que je t’aime. Il lui dit: pais mes agneaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Il lui dit encore: Simon fils de Jonas, m’aimes-tu? Il lui répondit: oui, Seigneur! tu sais que je t’aime. Il lui dit: pais mes brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Il lui dit pour la troisième fois: Simon fils de Jonas, m’aimes-tu? Pierre fut attristé de ce qu’il lui avait dit pour la troisième fois: m’aimes-tu? Et il lui répondit: Seigneur, tu sais toutes choses, tu sais que je t’aime. Jésus lui dit: pais mes brebis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'En vérité, en vérité je te dis, quand tu étais plus jeune tu te ceignais, et tu allais où tu voulais; mais quand tu seras vieux, tu étendras tes mains, et un autre te ceindra, et te mènera où tu ne voudras pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Or il dit cela pour marquer de quelle mort il devait glorifier Dieu; et quand il eut dit ces choses, il lui dit: suis-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Et Pierre se retournant vit venir après eux le Disciple que Jésus aimait, et qui durant le souper s’était penché sur le sein de Jésus, et avait dit: Seigneur, qui est celui à qui il arrivera de te trahir?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Quand donc Pierre le vit, il dit à Jésus: Seigneur, et celui-ci, que lui arrivera-t-il?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Jésus lui dit: si je veux qu’il demeure jusqu’à ce que je vienne que t’importe? toi, suis-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Or cette parole courut entre les Frères, que ce Disciple-là ne mourrait point. Cependant Jésus ne lui avait pas dit: il ne mourra point; mais, si je veux qu’il demeure jusqu’à ce que je vienne; que t’importe?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'C’est ce Disciple-là qui rend témoignage de ces choses, et qui a écrit ces choses, et nous savons que son témoignage est digne de foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Il y a aussi plusieurs autres choses que Jésus a faites, lesquelles étant écrites en détail je ne pense pas que le monde entier pût contenir les livres qu’on en écrirait. AMEN! ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Nous avons rempli le premier traité, Théophile! de toutes les choses que Jésus a faites et enseignées;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'Jusqu’au jour qu’il fut élevé au ciel; après avoir donné par le Saint-Esprit ses ordres aux Apôtres qu’il avait élus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'A qui aussi, après avoir souffert, il se présenta soi-même vivant, avec plusieurs preuves assurées, étant vu par eux durant quarante jours, et leur parlant des choses qui regardent le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Et les ayant assemblés, il leur commanda de ne partir point de Jérusalem, mais d’y attendre l’effet de la promesse du Père, laquelle, dit-il, vous avez ouïe de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Car Jean a baptisé d’eau, mais vous serez baptisés du Saint-Esprit, dans peu de jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Eux donc étant assemblés l’interrogèrent, disant: Seigneur, sera- ce en ce temps-ci que tu rétabliras le Royaume d’Israël?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Mais il leur dit: ce n’est point à vous de connaître les temps ou les moments qui ne dépendent que de mon Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Mais vous recevrez la vertu du Saint-Esprit qui viendra sur vous; et vous me serez témoins tant à Jérusalem qu’en toute la Judée, et dans la Samarie, et jusqu’au bout de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Et quand il eut dit ces choses, il fut élevé au ciel, eux le regardant, et une nuée le soutenant l’emporta de devant leurs yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Et comme ils avaient les yeux arrêtés vers le ciel, à mesure qu’il s’en allait, voici, deux hommes en vêtements blancs se présentèrent devant eux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'Qui leur dirent: hommes Galiléens, pourquoi vous arrêtez-vous à regarder au ciel? Ce Jésus qui a été élevé d’avec vous au ciel en descendra de la même manière que vous l’avez contemplé montant au ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Alors ils s’en retournèrent à Jérusalem de la montagne appelée la montagne des oliviers, qui est près de Jérusalem le chemin d’un Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Et quand ils furent entrés dans la ville, ils montèrent en une chambre haute; où demeuraient Pierre et Jacques, Jean et André, Philippe et Thomas, Barthélemy et Matthieu, Jacques fils d’Alphée, et Simon Zélotes, et Jude frère de Jacques.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Tous ceux-ci persévéraient unanimement en prières et en oraisons avec les femmes, et avec Marie mère de Jésus, et avec ses Frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Et en ces jours-là Pierre se leva au milieu des Disciples, qui étaient là assemblés au nombre d’environ six-vingts personnes, et il leur dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Hommes frères! il fallait que fût accompli ce qui a été écrit, et que le Saint-Esprit a prédit par la bouche de David touchant Judas, qui a été le guide de ceux qui ont pris Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Car il était de notre corps, et il avait reçu sa part de ce ministère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Mais s’étant acquis un champ avec le salaire injuste qui lui avait été donné, et s’étant précipité, son corps s’est crevé par le milieu, et toutes ses entrailles ont été répandues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Ce qui a été connu de tous les habitants de Jérusalem; tellement que ce champ-là a été appelé en leur propre Langue, Haceldama, c’est- à-dire, le champ du sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Car il est écrit au Livre des Psaumes: que sa demeure soit déserte, et qu’il n’y ait personne qui y habite. Et, qu’un autre prenne son emploi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Il faut donc que d’entre ces hommes qui se sont assemblés avec nous pendant tout le temps que le Seigneur Jésus a vécu entre nous,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'En commençant depuis le Baptême de Jean, jusqu’au jour qu’il a été enlevé d’avec nous, quelqu’un d’entre eux soit témoin avec nous de sa résurrection.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Et ils en présentèrent deux, savoir Joseph, appelé Barsabas, qui était surnommé Juste; et Matthias.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Et en priant ils dirent: toi, Seigneur, qui connais les coeurs de tous, montre lequel de ces deux tu as élu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'Afin qu’il prenne sa part de ce ministère et de cet Apostolat, que Judas a abandonné, pour s’en aller en son lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Puis ils les tirèrent au sort; et le sort tomba sur Matthias, qui d’une commune voix fut mis au rang des onze Apôtres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Et comme le jour de la Pentecôte était venu, ils étaient tous ensemble dans un même lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Et il se fit tout à coup un son du ciel, comme est le son d’un vent qui souffle avec véhémence, et il remplit toute la maison où ils étaient assis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Et il leur apparut des langues divisées comme de feu, qui se posèrent sur chacun d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Et ils furent tous remplis du Saint-Esprit, et commencèrent à parler des langues étrangères selon que l’Esprit les faisait parler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Or il y avait à Jérusalem des Juifs qui y séjournaient, hommes dévôts, de toute nation qui est sous le ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Et ce bruit ayant été fait, une multitude vint ensemble, qui fut tout émue de ce que chacun les entendait parler en sa propre langue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Ils en étaient donc tout surpris, et s’en étonnaient, disant l’un à l’autre: voici, tous ceux-ci qui parlent ne sont-ils pas Galiléens?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Comment donc chacun de nous les entendons-nous parler la propre langue du pays où nous sommes nés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Parthes, Mèdes, Elamites, et nous qui habitons, les uns dans la Mésopotamie, les autres en Judée, et en Cappadoce, au pays du Pont, et en Asie,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'En Phrygie, en Pamphylie, en Egypte, et dans ces quartiers de la Libye qui est près de Cyrène, et nous qui demeurons à Rome?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Tant Juifs que Prosélytes; Crétois, et Arabes, nous les entendons parler chacun en notre langue, des merveilles de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Ils étaient donc tout étonnés, et ils ne savaient que penser, disant l’un à l’autre: que veut dire ceci?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Mais les autres se moquant disaient: c’est qu’ils sont pleins de vin doux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Mais Pierre se présentant avec les onze, éleva sa voix, et leur dit: hommes Juifs! et vous tous qui habitez à Jérusalem, apprenez ceci, et faites attention à mes paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Car ceux-ci ne sont point ivres, comme vous pensez, vu que c’est la troisième heure du jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Mais c’est ici ce qui a été dit par le Prophète Joël:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'Et il arrivera aux derniers jours, dit Dieu, que je répandrai de mon Esprit sur toute chair; et vos fils et vos filles prophétiseront, et vos jeunes gens verront des visions, et vos Anciens songeront des songes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Et même en ces jours-là je répandrai de mon Esprit sur mes serviteurs et sur mes servantes, et ils prophétiseront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'Et je ferai des choses merveilleuses dans le ciel en haut, et des prodiges sur la terre en bas, du sang, et du feu, et une vapeur de fumée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Le soleil sera changé en ténèbres, et la lune en sang, avant que ce grand et notable jour du Seigneur vienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'Mais il arrivera que quiconque invoquera le Nom du Seigneur sera sauvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Hommes Israëlites, écoutez ces paroles! Jésus le Nazarien, personnage approuvé de Dieu entre vous par les miracles, les merveilles, et les prodiges que Dieu a faits par lui au milieu de vous, comme aussi vous le savez;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'Ayant été livré par le conseil défini et par la providence de Dieu, vous l’avez pris, et mis en croix, et vous l’avez fait mourir par les mains des iniques;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Mais Dieu l’a ressuscité, ayant brisé les liens de la mort, parce qu’il n’était pas possible qu’il fût retenu par elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Car David dit de lui: je contemplais toujours le Seigneur en ma présence: car il est à ma droite, afin que je ne sois point ébranlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'C’est pourquoi mon coeur s’est réjoui, et ma langue a tressailli de joie; et de plus, ma chair reposera en espérance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'Car tu ne laisseras point mon âme au sépulcre, et tu ne permettras point que ton Saint sente la corruption.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Tu m’as fait connaître le chemin de la vie, tu me rempliras de joie en ta présence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Hommes frères, je puis bien vous dire librement touchant le Patriarche David, qu’il est mort, et qu’il a été enseveli, et que son sépulcre est parmi nous jusques à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Mais comme il était Prophète, et qu’il savait que Dieu lui avait promis avec serment, que du fruit de ses reins il ferait naître selon la chair le Christ, pour le faire asseoir sur son trône;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'Il a dit de la résurrection de Christ, en la prévoyant, que son âme n’a point été laissée au sépulcre, et que sa chair n’a point senti la corruption.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Dieu a ressuscité ce Jésus; de quoi nous sommes tous témoins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Après donc qu’il a été élevé au ciel par la puissance de Dieu, et qu’il a reçu de son Père la promesse du Saint-Esprit, il a répandu ce que maintenant vous voyez et ce que vous entendez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Car David n’est pas monté aux cieux; mais lui-même dit: Le Seigneur a dit à mon Seigneur: assieds-toi à ma droite,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'Jusqu’à ce que j’aie mis tes ennemis pour le marchepied de tes pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Que donc toute la maison d’Israël sache certainement que Dieu l’a fait Seigneur et Christ, ce Jésus, dis-je, que vous avez crucifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Ayant ouï ces choses, ils eurent le coeur touché de componction, et ils dirent à Pierre et aux autres Apôtres: hommes frères, que ferons-nous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Et Pierre leur dit: amendez-vous, et que chacun de vous soit baptisé au Nom de Jésus-Christ, pour obtenir le pardon de vos péchés, et vous recevrez le don du Saint-Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Car à vous et à vos enfants est faite la promesse, et à tous ceux qui sont loin, autant que le Seigneur notre Dieu en appellera à soi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Et par plusieurs autres paroles il les conjurait, et les exhortait, en disant: séparez-vous de cette génération perverse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Ceux donc qui reçurent de bon coeur sa parole, furent baptisés; et en ce jour-là furent ajoutées à l’Eglise environ trois mille âmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Et ils persévéraient tous en la doctrine des Apôtres, et en la communion et la fraction du pain, et dans les prières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Or toute personne avait de la crainte, et beaucoup de miracles et de prodiges se faisaient par les Apôtres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Et tous ceux qui croyaient étaient ensemble en un même lieu, et ils avaient toutes choses communes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'Et ils vendaient leurs possessions et leurs biens, et les distribuaient à tous, selon que chacun en avait besoin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Et tous les jours ils persévéraient tous d’un accord dans le Temple; et rompant le pain de maison en maison, ils prenaient leur repas avec joie et avec simplicité de coeur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'Louant Dieu, et se rendant agréables à tout le peuple. Et le Seigneur ajoutait tous les jours à l’Eglise des gens pour être sauvés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Et comme Pierre et Jean montaient ensemble au Temple à l’heure de la prière, qui était à neuf heures,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Un homme boiteux dès sa naissance, y était porté, lequel on mettait tous les jours à la porte du Temple nommée la Belle, pour demander l’aumône à ceux qui entraient au Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Cet homme voyant Pierre et Jean qui allaient entrer au Temple, les pria de lui donner l’aumône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Mais Pierre ayant, avec Jean, arrêté sa vue sur lui, Pierre lui dit: regarde-nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Et il les regardait attentivement, s’attendant de recevoir quelque chose d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Mais Pierre lui dit: je n’ai ni argent, ni or; mais ce que j’ai, je te le donne: Au Nom de Jésus-Christ le Nazarien, lève-toi et marche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Et l’ayant pris par la main droite, il le leva; et aussitôt les plantes et les chevilles de ses pieds devinrent fermes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'Et faisant un saut, il se tint debout, et marcha; et il entra avec eux au Temple, marchant, sautant, et louant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Et tout le peuple le vit marchant et louant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'Et reconnaissant que c’était celui-là même qui était assis à la Belle porte du Temple, pour avoir l’aumône, ils furent remplis d’admiration et d’étonnement de ce qui lui était arrivé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Et comme le boiteux, qui avait été guéri, tenait par la main Pierre et Jean, tout le peuple étonné courut à eux, au Portique qu’on appelle de Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Mais Pierre voyant cela, dit au peuple: hommes Israélites, pourquoi vous étonnez-vous de ceci? ou pourquoi avez-vous l’oeil arrêté sur nous, comme si par notre puissance, ou par notre sainteté nous avions fait marcher cet homme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Le Dieu d’Abraham, et d’Isaac, et de Jacob, le Dieu de nos pères, a glorifié son Fils Jésus, que vous avez livré, et que vous avez renié devant Pilate, quoiqu’il jugeât qu’il devait être délivré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Mais vous avez renié le Saint et le Juste, et vous avez demandé qu’on vous relâchât un meurtrier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'Vous avez mis à mort le Prince de la vie, lequel Dieu a ressuscité des morts; de quoi nous sommes témoins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Et par la foi en son nom, son Nom a raffermi les pieds de cet homme que vous voyez et que vous connaissez; la foi, dis-je, que nous avons en lui, a donné à celui-ci cette entière disposition de tous ses membres, en la présence de vous tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Et maintenant, mes frères, je sais que vous l’avez fait par ignorance, de même que vos Gouverneurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Mais Dieu a ainsi accompli les choses qu’il avait prédites par la bouche de tous ses Prophètes, que le Christ devait souffrir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Amendez-vous donc, et vous convertissez, afin que vos péchés soient effacés:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'Quand les temps de rafraîchissement seront venus par la présence du Seigneur, et qu’il aura envoyé Jésus-Christ, qui vous a été auparavant annoncé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Et lequel il faut que le ciel contienne, jusqu’au temps du rétablissement de toutes les choses que Dieu a prononcées par la bouche de tous ses saints Prophètes, dès le commencement du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Car Moïse lui-même a dit à nos Pères: le Seigneur votre Dieu, vous suscitera d’entre vos frères un Prophète tel que moi; vous l’écouterez dans tout ce qu’il vous dira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Et il arrivera que toute personne qui n’aura point écouté ce Prophète, sera exterminée d’entre le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Et même tous les Prophètes depuis Samuel, et ceux qui l’ont suivi, tout autant qu’il y en a eu qui ont parlé, ont aussi prédit ces jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Vous êtes les enfants des Prophètes, et de l’alliance que Dieu a traitée avec nos Pères, disant à Abraham: et en ta semence seront bénies toutes les familles de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'C’est pour vous premièrement que Dieu ayant suscité son Fils Jésus, l’a envoyé pour vous bénir, en retirant chacun de vous de vos méchancetés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Mais comme ils parlaient au peuple, les Sacrificateurs, et le Capitaine du Temple, et les Sadducéens, survinrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'Etant en grande peine de ce qu’ils enseignaient le peuple, et qu’ils annonçaient la résurrection des morts au Nom de Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Et les ayant fait arrêter, ils les mirent en prison jusqu’au lendemain, parce qu’il était déjà tard.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Et plusieurs de ceux qui avaient ouï la parole, crurent; et le nombre des personnes fut d’environ cinq mille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Or il arriva que le lendemain leurs Gouverneurs, les Anciens et les Scribes s’assemblèrent à Jérusalem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'Avec Anne souverain Sacrificateur, et Caïphe, et Jean, et Alexandre, et tous ceux qui étaient de la race Sacerdotale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'Et ayant fait comparaître devant eux Pierre et Jean, ils leur demandèrent: par quelle puissance, ou au Nom de qui avez-vous fait cette guérison?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Alors Pierre étant rempli du Saint-Esprit, leur dit: Gouverneurs du peuple, et vous Anciens d’Israël:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Puisque nous sommes recherchés aujourd’hui pour un bien qui a été fait en la personne d’un impotent, pour savoir comment il a été guéri;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'Sachez vous tous et tout le peuple d’Israël, que ç’a été au Nom de Jésus-Christ le Nazarien, que vous avez crucifié, et que Dieu a ressuscité des morts; c’est, dis-je, en son Nom, que cet homme qui parait ici devant vous, a été guéri.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'C’est cette Pierre, rejetée par vous qui bâtissez, qui a été faite la pierre angulaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Et il n’y a point de salut en aucun autre: car aussi il n’y a point sous le ciel d’autre Nom qui soit donné aux hommes par lequel il nous faille être sauvés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Eux voyant la hardiesse de Pierre et de Jean, et sachant aussi qu’ils étaient des hommes sans lettres, et idiots, s’en étonnaient, et ils reconnaissaient bien qu’ils avaient été avec Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Et voyant que l’homme qui avait été guéri, était présent avec eux, ils ne pouvaient contredire en rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Alors leur ayant commandé de sortir hors du Conseil, ils conféraient entre eux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Disant: que ferons-nous à ces gens? car il est connu à tous les habitants de Jérusalem, qu’un miracle a été fait par eux, et cela est si évident, que nous ne le pouvons nier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Mais afin qu’il ne soit plus divulgué parmi le peuple, défendons- leur avec menaces expresses, qu’ils n’aient plus à parler en ce Nom à qui que ce soit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Les ayant donc appelés, ils leur commandèrent de ne parler plus ni d’enseigner en aucune manière au Nom de Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Mais Pierre et Jean répondant, leur dirent: jugez s’il est juste devant Dieu de vous obéir plutôt qu’à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Car nous ne pouvons que nous ne disions les choses que nous avons vues et ouies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Alors ils les relâchèrent avec menaces, ne trouvant point comment ils les pourraient punir, à cause du peuple, parce que tous glorifiaient Dieu de ce qui avait été fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Car l’homme en qui avait été faite cette miraculeuse guérison avait plus de quarante ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Or après qu’on les eut laissés aller, ils vinrent vers les leurs, et leur racontèrent tout ce que les principaux Sacrificateurs et les Anciens leur avaient dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Ce qu’ayant entendu, ils élevèrent tous ensemble la voix à Dieu, et dirent: Seigneur! tu es le Dieu qui as fait le ciel et la terre, la mer, et toutes les choses qui y sont;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Et qui as dit par la bouche de David ton serviteur: pourquoi se sont émues les Nations, et les peuples ont-ils projeté des choses vaines?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Les Rois de la terre se sont trouvés en personne, et les Princes se sont joints ensemble contre le Seigneur, et contre son Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'En effet, contre ton saint Fils Jésus, que tu as oint, se sont assemblés Hérode et Ponce Pilate, avec les Gentils, et les peuples d’Israël,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'Pour faire toutes les choses que ta main et ton conseil avaient auparavant déterminé qui seraient faites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Maintenant donc, Seigneur, fais attention à leurs menaces, et donne à tes serviteurs d’annoncer ta parole avec toute hardiesse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'En étendant ta main afin qu’il se fasse des guérisons, et des prodiges, et des merveilles, par le Nom de ton saint Fils Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Et quand ils eurent prié, le lieu où ils étaient assemblés trembla; et ils furent tous remplis du Saint-Esprit, et ils annonçaient la parole de Dieu avec hardiesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Or la multitude de ceux qui croyaient, n’était qu’un coeur et qu’une âme; et nul ne disait d’aucune des choses qu’il possédait, qu’elle fût à lui; mais toutes choses étaient communes entre eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Aussi les Apôtres rendaient témoignage avec une grande force à la résurrection du Seigneur Jésus; et une grande grâce était sur eux tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Car il n’y avait entre eux aucune personne nécessiteuse; parce que tous ceux qui possédaient des champs ou des maisons, les vendaient, et ils apportaient le prix des choses vendues;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'Et le mettaient aux pieds des Apôtres; et il était distribué à chacun selon qu’il en avait besoin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Or Joses, qui par les Apôtres fut surnommé Barnabas, c’est-à-dire, fils de consolation, Lévite, et Cyprien de nation,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'Ayant une possession, la vendit, et en apporta le prix, et le mit aux pieds des Apôtres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Or un homme nommé Ananias, ayant avec Saphira sa femme, vendu une possession,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'Retint une partie du prix, du consentement de sa femme, et en apporta quelque partie, et la mit aux pieds des Apôtres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Mais Pierre lui dit: Ananias comment satan s’est-il emparé de ton coeur jusques à t’inciter à mentir au Saint-Esprit, et à soustraire une partie du prix de la possession?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Si tu l’eusses gardée, ne te demeurait-elle pas? et étant vendue, n’était-elle pas en ta puissance? Pourquoi as-tu formé un tel dessein dans ton coeur? tu n’as pas menti aux hommes mais à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Et Ananias entendant ces paroles, tomba, et rendit l’esprit; ce qui causa une grande crainte à tous ceux qui en entendirent parler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Et quelques jeunes hommes se levant le prirent, et l’emportèrent dehors, et l’enterrèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Et il arriva environ trois heures après, que sa femme aussi, ne sachant point ce qui était arrivé, entra;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Et Pierre prenant la parole, lui dit: dis-moi, avez-vous autant vendu le champ? et elle dit: oui, autant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Alors Pierre lui dit: pourquoi avez-vous fait un complot entre vous de tenter l’Esprit du Seigneur? voilà à la porte les pieds de ceux qui ont enterré ton mari, et ils t’emporteront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Et au même instant elle tomba à ses pieds, et rendit l’esprit. Et quand les jeunes hommes furent entrés, ils la trouvèrent morte, et ils l’emportèrent dehors, et l’enterrèrent auprès de son mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Et cela donna une grande crainte à toute l’Eglise, et à tous ceux qui entendaient ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Et beaucoup de prodiges et de miracles se faisaient parmi le peuple par les mains des Apôtres; et ils étaient tous d’un accord au portique de Salomon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Cependant nul des autres n’osait se joindre à eux; mais le peuple les louait hautement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Et le nombre de ceux qui croyaient au Seigneur, tant d’hommes que de femmes, se multipliait de plus en plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'Et on apportait les malades dans les rues, et on les mettait sur de petits lits et sur des couchettes, afin que quand Pierre viendrait, au moins son ombre passât sur quelqu’un d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Le peuple aussi des villes voisines s’assemblait à Jérusalem, apportant les malades, et ceux qui étaient tourmentés des esprits immondes; et tous étaient guéris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Alors le souverain Sacrificateur se leva, lui et tous ceux qui étaient avec lui, qui étaient la secte des Sadducéens, et ils furent remplis d’envie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'Et mettant les mains sur les Apôtres, ils les firent conduire dans la prison publique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Mais l’Ange du Seigneur ouvrit de nuit les portes de la prison, et les ayant mis dehors, il leur dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, 'Allez, et vous présentant dans le Temple, annoncez au peuple toutes les paroles de cette vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Ce qu’ayant entendu, ils entrèrent dès le point du jour dans le Temple, et ils enseignaient. Mais le souverain Sacrificateur étant venu, et ceux qui étaient avec lui, ils assemblèrent le Conseil et tous les Anciens des enfants d’Israël, et ils envoyèrent à la prison pour les faire amener.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Mais quand les huissiers y furent venus, ils ne les trouvèrent point dans la prison;ainsi ils s’en retournèrent, et ils rapportèrent,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'Disant: nous avons bien trouvé la prison fermée avec toute sûreté, et les gardes aussi qui étaient devant les portes; mais après l’avoir ouverte, nous n’avons trouvé personne dedans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Et quand le souverain Sacrificateur, et le Capitaine du Temple, et les principaux Sacrificateurs, eurent ouï ces paroles, ils furent fort en peine sur leur sujet, ne sachant ce que cela deviendrait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Mais quelqu’un survint qui leur dit: voilà, les hommes que vous aviez mis en prison, sont au Temple, et se tenant là ils enseignent le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Alors le Capitaine du Temple avec les huissiers s’en alla, et il les amena sans violence: car ils craignaient d’être lapidés par le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'Et les ayant amenés, ils les présentèrent au Conseil. Et le souverain Sacrificateur les interrogea,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'Disant: ne vous avons-nous pas défendu expressément de n’enseigner point en ce Nom? et cependant voici, vous avez rempli Jérusalem de votre doctrine, et vous voulez faire venir sur nous le sang de cet homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Alors Pierre et les autres Apôtres répondant, dirent: il faut plutôt obéir à Dieu qu’aux hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Le Dieu de nos pères a ressuscité Jésus, que vous avez fait mourir, le pendant au bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Et Dieu l’a élevé par sa puissance pour être Prince et Sauveur, afin de donner à Israël la repentance et la rémission des péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'Et nous lui sommes témoins de ce que nous disons, et le Saint- Esprit que Dieu a donné à ceux qui lui obéissent, en est aussi témoin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Mais eux ayant entendu ces choses, grinçaient les dents, et consultaient pour les faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Mais un Pharisien nommé Gamaliel, Docteur de la Loi, honoré de tout le peuple, se levant dans le Conseil, commanda que les Apôtres se retirassent dehors pour un peu de temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'Puis il leur dit: hommes Israélites, prenez garde à ce que vous devrez faire touchant ces gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Car avant ce temps-ci s’éleva Theudas, se disant être quelque chose, auquel se joignit un nombre d’hommes d’environ quatre cents; mais il a été défait, et tous ceux qui s’étaient joints à lui ont été dissipés et réduits à rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Après lui parut Judas le Galiléen aux jours du dénombrement, et il attira à lui un grand peuple; mais celui-ci aussi est péri, et tous ceux qui s’étaient joints à lui ont été dispersés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Maintenant donc je vous dis: ne continuez plus vos poursuites contre ces hommes, et laissez-les: car si cette entreprise ou cette oeuvre est des hommes, elle sera détruite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'Mais si elle est de Dieu, vous ne la pourrez détruire; et prenez garde que même vous ne soyez trouvés faire la guerre à Dieu. Et ils furent de son avis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Puis ayant appelé les Apôtres, ils leur commandèrent, après les avoir fouettés, de ne parler point au Nom de Jésus; après quoi ils les laissèrent aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Et les Apôtres se retirèrent de devant le Conseil, joyeux d’avoir été rendus dignes de souffrir des opprobres pour le Nom de Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'Et ils ne cessaient tous les jours d’enseigner, et d’annoncer Jésus-Christ dans le Temple, et de maison en maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'Et en ces jours-là, comme les disciples se multipliaient, il s’éleva un murmure des Grecs contre les Hébreux, sur ce que leurs veuves étaient méprisées dans le service ordinaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'C’est pourquoi les Douze ayant appelé la multitude des disciples, dirent: il n’est pas raisonnable que nous laissions la parole de Dieu pour servir aux tables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Regardez donc, mes frères, de choisir sept hommes d’entre vous, de qui on ait bon témoignage, pleins du Saint-Esprit et de sagesse, auxquels nous commettions cette affaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Et pour nous, nous continuerons de vaquer à la prière, et à l’administration de la parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Et ce discours plut à toute l’assemblée qui était là présente; et ils élurent Etienne, homme plein de foi et du Saint-Esprit, et Philippe, et Prochore, et Nicanor, et Timon, et Parménas, et Nicolas, prosélyte d’Antioche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Et ils les présentèrent aux Apôtres; qui, après avoir prié, leur imposèrent les mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Et la parole de Dieu croissait, et le nombre des disciples se multipliait beaucoup dans Jérusalem; un grand nombre aussi de Sacrificateurs obéissait à la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Or Etienne plein de foi et de puissance, faisait de grands miracles et de grands prodiges parmi le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Et quelques-uns de la Synagogue appelée la Synagogue des Libertins, et de celle des Cyréniens, et de celle des Alexandrins, et de ceux qui étaient de Cilicie, et d’Asie, se levèrent pour disputer contre Etienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Mais ils ne pouvaient résister à la sagesse et à l’Esprit par lequel il parlait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Alors ils subornèrent des hommes, qui disaient: nous lui avons ouï proférer des paroles blasphématoires contre Moïse et contre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Et ils soulevèrent le peuple, et les Anciens, et les Scribes, et se jetant sur lui, ils l’enlevèrent, et l’amenèrent dans le Conseil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'Et ils présentèrent de faux témoins, qui disaient: cet homme ne cesse de proférer des paroles blasphématoires contre ce saint Lieu et contre la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Car nous lui avons ouï dire que ce Jésus le Nazarien détruira ce Lieu-ci, et qu’il changera les ordonnances que Moïse nous a données.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Et comme tous ceux qui étaient assis dans le Conseil avaient les yeux arrêtés sur lui, ils virent son visage comme le visage d’un Ange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Alors le souverain Sacrificateur lui dit: ces choses sont-elles ainsi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Et Etienne répondit: hommes frères et pères, écoutez -moi: le Dieu de gloire apparut à notre père Abraham, du temps qu’il était en Mésopotamie, avant qu’il demeurât à Carran,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'Et lui dit: sors de ton pays, et d’avec ta parent’, et viens au pays que je te montrerai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Il sortit donc du pays des Caldéens, et alla demeurer à Carran; et de là, après que son père fut mort, Dieu le fit passer en ce pays où vous habitez maintenant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'Et il ne lui donna aucun héritage en ce pays, non pas même d’un pied de terre, quoiqu’il lui eût promis de le lui donner en possession, et à sa postérité après lui, dans un temps où il n’avait point encore d’enfant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Et Dieu lui parla ainsi: ta postérité séjournera quatre cents ans dans une terre étrangère, et là on l’asservira, et on la maltraitera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Mais je jugerai la nation à laquelle ils auront été asservis, dit Dieu; et après cela ils sortiront, et me serviront en ce lieu-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Puis il lui donna l’Alliance de la Circoncision; et après cela Abraham engendra Isaac, lequel il circoncit le huitième jour; et Isaac engendra Jacob, et Jacob les douze Patriarches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Et les Patriarches étant pleins d’envie vendirent Joseph pour être mené en Egypte; mais Dieu était avec lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'Qui le délivra de toutes ses afflictions; et l’ayant rempli de sagesse il le rendit agréable à Pharaon, Roi d’Egypte, qui l’établit Gouverneur sur l’Egypte, et sur toute sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Or il survint dans tout le pays d’Egypte et en Canaan une famine et une grande angoisse; tellement que nos pères ne pouvaient trouver des vivres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Mais quand Jacob eut ouï dire qu’il y avait du blé en Egypte, il y envoya pour la première fois nos pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'Et y étant retournés une seconde fois, Joseph fut reconnu par ses frères, et la famille de Joseph fut déclarée à Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Alors Joseph envoya quérir Jacob son père, et toute sa famille, qui était soixante-quinze personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Jacob donc descendit en Egypte, et il y mourut, lui et nos pères;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'Qui furent transportés à Sichem, et mis dans le sépulcre qu’Abraham avait acheté à prix d’argent des fils d’Emmor, fils de Sichem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Mais comme le temps de la promesse pour laquelle Dieu avait juré à Abraham, s’approchait, le peuple s’augmenta et se multiplia en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'Jusqu’à ce qu’il parût en Egypte un autre Roi, qui n’avait point connu Joseph;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Et qui usant de ruse contre notre nation, maltraita nos pères, jusqu’à leur faire exposer leurs enfants à l’abandon, afin d’en faire périr la race.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'En ce temps-là naquit Moïse, qui fut divinement beau; et il fut nourri trois mois dans la maison de son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'Mais ayant été exposé à l’abandon, la fille de Pharaon l’emporta, et le nourrit pour soi comme son fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Et Moïse fut instruit dans toute la science des Egyptiens; et il était puissant en paroles et en actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Mais quand il fut parvenu à l’âge de quarante ans, il forma le dessein d’aller visiter ses frères, les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'Et voyant un d’eux à qui on faisait tort, il le défendit, et vengea celui qui était outragé, en tuant l’Egyptien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Or il croyait que ses frères comprendraient par là que Dieu les délivrerait par son moyen; mais ils ne le comprirent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Et le jour suivant il se trouva entre eux comme ils se querellaient, et il tâcha de les mettre d’accord, en leur disant: hommes, vous êtes frères, pourquoi vous faites-vous tort l’un à l’autre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Mais celui qui faisait tort à son prochain, le rebuta, lui disant: qui t’a établi Prince et Juge sur nous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Me veux-tu tuer, comme tu tuas hier l’Egyptien?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Alors Moïse s’enfuit sur un tel discours, et fut étranger dans le pays de Madian, où il eut deux fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Et quarante ans étant accomplis, l’Ange du Seigneur lui apparut au désert de la montagne de Sinaï, dans une flamme de feu qui était en un buisson.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Et quand Moïse le vit, il fut étonné de la vision, et comme il approchait pour considérer ce que c’était, la voix du Seigneur lui fut adressée,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'Disant: je suis le Dieu de tes pères, le Dieu d’Abraham, et le Dieu d’Isaac, et le Dieu de Jacob. Et Moïse tout tremblant n’osait considérer ce que c’était.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Et le Seigneur lui dit: déchausse les souliers de tes pieds: car le lieu où tu es, est une terre sainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'J’ai vu, j’ai vu l’affliction de mon peuple qui est en Egypte, et j’ai ouï leur gémissement, et je suis descendu pour les délivrer: maintenant donc viens; je t’enverrai en Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Ce Moïse, lequel ils avaient rejeté, en disant: qui t’a établi Prince et Juge? c’est celui que Dieu envoya pour Prince et pour libérateur par le moyen de l’Ange qui lui était apparu au buisson.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'C’est celui qui les tira dehors, en faisant des miracles et des prodiges dans la mer Rouge, et au désert par quarante ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'C’est ce Moïse qui a dit aux enfants d’Israël: le Seigneur votre Dieu vous suscitera un Prophète tel que moi d’entre vos frères; écoutez-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'C’est celui qui fut en l’assemblée au désert avec l’Ange qui lui parlait sur la montagne de Sinaï, et qui fut avec nos pères, et reçut les paroles de vie pour nous les donner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'Auquel nos pères ne voulurent point obéir, mais ils le rejetèrent, et se détournèrent en leur coeur pour retourner en Egypte,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'Disant à Aaron: fais-nous des dieux qui aillent devant nous; car nous ne savons point ce qui est arrivé à ce Moïse qui nous a amenés hors du pays d’Egypte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'Ils firent donc en ces jours-là un veau, et ils offrirent des sacrifices à l’idole, et se réjouirent dans les oeuvres de leurs mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'C’est pourquoi aussi Dieu se détourna d’eux, et les abandonna à servir l’armée du ciel, ainsi qu’il est écrit au Livre des Prophètes: maison d’Israël, m’avez-vous offert des sacrifices et des oblations pendant quarante ans au désert?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Mais vous avez porté le tabernacle de Moloc, et l’étoile de votre dieu Remphan; qui sont des figures que vous avez faites pour les adorer; c’est pourquoi je vous transporterai au delà de Babylone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Le Tabernacle du témoignage a été avec nos pères au désert, comme avait ordonné celui qui avait dit à Moïse, de le faire selon le modèle qu’il en avait vu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Et nos pères ayant reçu ce Tabernacle, ils le portèrent sous la conduite de Josué au pays qui était possédé par les nations que Dieu chassa de devant nos pères, où il demeura jusqu’aux jours de David;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'Qui trouva grâce devant Dieu et qui demanda de pouvoir dresser un Tabernacle au Dieu de Jacob.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Et Salomon lui bâtit une maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Mais le Souverain n’habite point dans des temples faits de main, selon ces paroles du Prophète:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, 'Le ciel est mon trône, et la terre est le marchepied de mes pieds: quelle maison me bâtirez-vous, dit le Seigneur, ou quel pourrait être le lieu de mon repos?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Ma main n’a-t-elle pas fait toutes ces choses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Gens de cou roide, et incirconcis de coeur et d’oreilles, vous vous obstinez toujours contre le Saint-Esprit; vous faites comme vos pères ont fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Lequel des Prophètes vos pères n’ont-ils point persécuté? ils ont même tué ceux qui ont prédit l’avénement du Juste, duquel maintenant vous avez été les traîtres et les meurtriers,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'Vous qui avez reçu la Loi par la disposition des Anges, et qui ne l’avez point gardée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'En entendant ces choses, leur coeur s’enflamma de colère et ils grinçaient les dents contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Mais lui étant rempli du Saint-Esprit, et ayant les yeux attachés au ciel, vit la gloire de Dieu, et Jésus étant à la droite de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'Et il dit: voici, je vois les cieux ouverts, et le Fils de l’homme étant à la droite de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Alors ils s’écrièrent à haute voix, et bouchèrent leurs oreilles, et tous d’un accord ils se jetèrent sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'Et l’ayant tiré hors de la ville, ils le lapidèrent; et les témoins mirent leurs vêtements aux pieds d’un jeune homme nommé Saul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'Et ils lapidaient Etienne, qui priait et disait: Seigneur Jésus! reçois mon esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Et s’étant mis à genoux, il cria, à haute voix: Seigneur, ne leur impute point ce péché; et quand il eut dit cela, il s’endormit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Or Saul consentait à la mort d’Etienne, et en ce temps-là il se fit une grande persécution contre l’Eglise qui était à Jérusalem, et tous furent dispersés dans les quartiers de la Judée et de la Samarie; excepté les Apôtres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Et quelques hommes craignant Dieu emportèrent Etienne pour l’ensevelir, et menèrent un grand deuil sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Mais Saul ravageait l’Eglise, entrant dans toutes les maisons, et traînant par force hommes et femmes, il les mettait en prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Ceux donc qui furent dispersés allaient çà et là annonçant la parole de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Et Philippe étant descendu en une ville de Samarie, leur prêcha Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Et les troupes étaient toutes ensemble attentives à ce que Philippe disait, l’écoutant, et voyant les miracles qu’il faisait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Car les esprits immondes sortaient, en criant à haute voix, hors de plusieurs qui en étaient possédés, et beaucoup de paralytiques et de boiteux furent guéris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'Ce qui causa une grande joie dans cette ville-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Or il y avait auparavant dans la ville un homme nommé Simon qui exerçait l’art d’enchanteur, et ensorcelait le peup1e de Samarie, se disant être quelque grand personnage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Auquel tous étaient attentifs, depuis le plus petit jusques au plus grand, disant: celui-ci est la grande vertu de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Et ils étaient attachés à lui, parce que depuis longtemps il les avait éblouis par sa magie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Mais quand ils eurent cru ce que Philippe leur annonçait touchant le Royaume de Dieu, et le Nom de Jésus-Christ, et les hommes et les femmes furent baptisés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Et Simon crut aussi lui-même, et après avoir été baptisé, il ne bougeait d’auprès de Philippe; et voyant les prodiges et les grands miracles qui se faisaient, il était comme ravi hors de lui même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Or quand les Apôtres qui étaient à Jérusalem, eurent entendu que la Samarie avaient reçu la parole de Dieu, ils leur envoyèrent Pierre et Jean;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Qui y étant descendus prièrent pour eux, afin qu’ils reçussent le Saint-Esprit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'Car il n’était pas encore descendu sur aucun d’eux, mais seulement ils étaient baptisés au Nom du Seigneur Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Puis ils leur imposèrent les mains, et ils reçurent le Saint- Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Alors Simon ayant vu que le Saint-Esprit était donné, par l’imposition des mains des Apôtres, il leur présenta de l’argent,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'En leur disant: donnez-moi aussi cette puissance, que tous ceux à qui j’imposerai les mains reçoivent le Saint-Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Mais Pierre lui dit: que ton argent périsse avec toi, puisque tu as estimé que le don de Dieu s’acquiert avec de l’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Tu n’as point de part ni d’héritage en cette affaire: car ton coeur n’est point droit devant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Repens-toi donc de cette méchanceté, et prie Dieu, afin que s’il est possible, la pensée de ton coeur te soit pardonnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Car je vois que tu es dans un fiel très amer, et dans un lien d’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Alors Simon répondit, et dit: vous, priez le Seigneur pour moi, afin que rien ne vienne sur moi des choses que vous avez dites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Eux donc après avoir prêché et annoncé la parole du Seigneur, retournèrent à Jérusalem, et annoncèrent l’Evangile en plusieurs bourgades des Samaritains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Puis l’Ange du Seigneur parla à Philippe, en disant: lève-toi, et t’en va vers le Midi, au chemin qui descend de Jérusalem à Gaza, celle qui est déserte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Lui donc se levant, s’en alla; et voici un homme Ethiopien, Eunuque, qui était un des principaux Seigneurs de la Cour de Candace, Reine des Ethiopiens, commis sur toutes ses richesses, et qui était venu pour adorer à Jérusalem;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'S’en retournait, assis dans son chariot; et il lisait le Prophète Esaïe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Et l’Esprit dit à Philippe: approche-toi, et te joins à ce chariot.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Et Philippe y étant accouru, il l’entendit lisant le Prophète Esaïe; et il lui dit: mais comprends-tu ce que tu lis?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Et il lui dit: mais comment le pourrais-je comprendre, si quelqu’un ne me guide? et il pria Philippe de monter et s’asseoir avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Or le passage de l’Ecriture qu’il lisait était celui-ci: il a été mené comme une brebis à la boucherie, et comme un agneau muet devant celui qui le tond; en sorte qu’il n’a point ouvert sa bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'En son abaissement son jugement a été haussé; mais qui racontera sa durée? car sa vie est enlevée de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Et l’Eunuque prenant la parole, dit à Philippe: je te prie, de qui est-ce que le Prophète dit cela: est-ce de lui-même, ou de quelque autre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Alors Philippe ouvrant sa bouche, et commençant par cette Ecriture, lui annonça Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Et comme ils continuaient leur chemin, ils arrivèrent à un lieu où il y avait de l’eau; et l’Eunuque dit: voici de l’eau, qu’est- ce qui empêche que je ne sois baptisé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'Et Philippe dit: si tu crois de tout ton coeur, cela t’est permis; et l’Eunuque répondant, dit: Je crois que Jésus-Christ est le Fils de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Et ayant commandé qu’on arrêtât le chariot, ils descendirent tous deux dans l’eau, Philippe et l’Eunuque; et Philippe le baptisa.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Et quand ils furent remontés hors de l’eau, l’Esprit du Seigneur enleva Philippe, et l’Eunuque ne le vit plus; et tout joyeux il continua son chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Mais Philippe se trouva dans Azote, et en passant il annonça l’Evangile dans toutes les villes, jusqu’à ce qu’il fût arrivé à Césarée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Or Saul ne respirant encore que menaces et carnage contre les disciples du Seigneur, s’étant adressé au souverain Sacrificateur,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'Lui demanda des lettres de sa part pour porter à Damas aux Synagogues, afin que s’il en trouvait quelques-uns de cette secte, soit hommes, soit femmes, il les amenât liés à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Or il arriva qu’en marchant il approcha de Damas, et tout à coup une lumière resplendit du ciel comme un éclair tout autour de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Et étant tombé par terre, il entendit une voix qui lui disait: Saul, Saul, pourquoi me persécutes-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Et il répondit: qui es-tu, Seigneur? Et le Seigneur lui dit: je suis Jésus, que tu persécutes; il t’est dur de regimber contre les aiguillons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Et lui tout tremblant et tout effrayé, dit: Seigneur, que veux-tu que je fasse? Et le Seigneur lui dit: lève-toi, et entre dans la ville, et là il te sera dit ce que tu dois faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Et les hommes qui marchaient avec lui s’arrêtèrent tout épouvantés, entendant bien la voix, mais ne voyant personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Et Saul se leva de terre, et ouvrant ses yeux, il ne voyait personne; c’est pourquoi ils le conduisirent par la main, et le menèrent à Damas;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Où il fut trois jours sans voir, sans manger ni boire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Or il y avait à Damas un disciple, nommé Ananias, à qui le Seigneur dit en vision: Ananias! Et il répondit: me voici, Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Et le Seigneur lui dit: lève-toi, et t’en va en la rue nommée la droite, et cherche dans la maison de Judas un homme appelé Saul, qui est de Tarse: car voilà il prie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'Or Saul avait vu en vision un homme nommé Ananias, entrant, et lui imposant les mains, afin qu’il recouvrât la vue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Et Ananias répondit: Seigneur! j’ai ouï parler à plusieurs de cet homme-là; et combien de maux il a faits à tes Saints dans Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Il a même ici le pouvoir de la part des principaux Sacrificateurs, de lier tous ceux qui invoquent ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Mais le Seigneur lui dit: va; car il m’est un vaisseau que j’ai choisi, pour porter mon Nom devant les Gentils, et les Rois, et les enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Car je lui montrerai combien il aura à souffrir pour mon Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Ananias donc s’en alla, et entra dans la maison; et lui imposant les mains, il lui dit: Saul mon frère, le Seigneur Jésus, qui t’est apparu dans le chemin par où tu venais, m’a envoyé, afin que tu recouvres la vue, et que tu sois rempli du Saint-Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Et aussitôt il tomba de ses yeux comme des écailles; et à l’instant il recouvra la vue; puis il se leva, et fut baptisé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'Et ayant mangé il reprit ses forces. Et Saul fut quelques jours avec les disciples qui étaient à Damas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'Et il prêcha incessamment dans les Synagogues, que Christ était le Fils de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Et tous ceux qui l’entendaient, étaient comme ravis hors d’eux- mêmes, et ils disaient: n’est-ce pas celui-là qui a détruit à Jérusalem ceux qui invoquaient ce Nom, et qui est venu ici exprès pour les amener liés aux principaux Sacrificateurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Mais Saul se fortifiait de plus en plus, et confondait les Juifs qui demeuraient à Damas, prouvant que Jésus était le Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Or longtemps après les Juifs conspirèrent ensemble pour le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Mais leurs embûches vinrent à la connaissance de Saul. Or ils gardaient les portes jour et nuit, afin de le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Mais les disciples le prenant de nuit, le descendirent par la muraille, en le dévalant dans une corbeille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Et quand Saul fut venu à Jérusalem, il tâchait de se joindre aux disciples; mais tous le craignaient, ne croyant pas qu’il fût disciple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Mais Barnabas le prit, et le mena aux Apôtres, et leur raconta comment par le chemin il avait vu le Seigneur, qui lui avait parlé, et comment il avait parlé franchement à Damas au Nom de Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'Et il était avec eux à Jérusalem, se montrant publiquement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'Et parlant sans déguisement au Nom du Seigneur Jésus, il disputait contre les Grecs; mais ils tâchaient de le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Ce que les frères ayant connu ils le menèrent à Césarée, et l’envoyèrent à Tarse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'Ainsi donc les Eglises par toute la Judée, la Galilée, et la Samarie étaient en paix, étant édifiées, et marchant dans la crainte du Seigneur; et elles étaient multipliées par la consolation du Saint-Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Or il arriva que comme Pierre les visitait tous, il vint aussi vers les Saints qui demeuraient à Lydde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Et il trouva là un homme nommé Enée, qui depuis huit ans était couché dans un petit lit; car il était paralytique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'Et Pierre lui dit: Enée, Jésus-Christ te guérisse! lève-toi, et fais ton lit; et sur-le-champ il se leva.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'Et tous ceux qui habitaient à Lydde et à Saron, le virent; et ils furent convertis au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Or il y avait à Joppe une femme disciple, nommée Tabitha, qui signifie en Grec Dorcas, laquelle était pleine de bonnes oeuvres et d’aumônes qu’elle faisait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Et il arriva en ces jours-là qu’elle tomba malade, et mourut; et quand ils l’eurent lavée, ils la mirent dans une chambre haute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Et parce que Lydde était près de Joppe, les disciples ayant appris que Pierre était à Lydde, ils envoyèrent vers lui deux hommes, le priant qu’il ne tardât point de venir chez eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Et Pierre s’étant levé, s’en vint avec eux; et quand il fut arrivé, ils le menèrent en la chambre haute; et toutes les veuves se présentèrent à lui en pleurant, et montrant combien Dorcas faisait de robes et de vêtements, quand elle était avec elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Mais Pierre après les avoir fait tous sortir, se mit à genoux, et pria; puis se tournant vers le corps, il dit: Tabitha, lève-toi. Et elle ouvrit ses yeux, et voyant Pierre, elle se rassit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'Et il lui donna la main, et la leva; puis ayant appelé les Saints et les veuves, il la leur présenta vivante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'Et cela fut connu dans tout Joppe; et plusieurs crurent au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Et il arriva qu’il demeura plusieurs jours à Joppe, chez un certain Simon corroyeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Or il y avait à Césarée un homme, nommé Corneille, Centenier d’une cohorte de la Légion appelée Italique;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Homme dévot et craignant Dieu, avec toute sa famille, faisant aussi beaucoup d’aumônes au peuple, et priant Dieu continuellement;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Lequel vit clairement en vision environ sur les neuf heures du jour, un Ange de Dieu qui vint à lui, et qui lui dit: Corneille!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Et Corneille ayant les yeux arrêtés sur lui, et étant tout effrayé, lui dit: qu’y a-t-il, Seigneur? Et il lui dit: tes prières et tes aumônes sont montées en mémoire devant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Maintenant donc envoie des gens à Joppe, et fais venir Simon, qui est surnommé Pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Il est logé chez un certain Simon corroyeur, qui a sa maison près de la mer; c’est lui qui te dira ce qu’il faut que tu fasses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Et quand l’Ange qui parlait à Corneille s’en fut allé, il appela deux de ses serviteurs, et un soldat craignant Dieu, d’entre ceux qui se tenaient autour de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'Auxquels ayant tout raconté, il les envoya à Joppe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Or le lendemain comme ils marchaient, et qu’ils approchaient de la ville, Pierre monta sur la maison pour prier, environ vers les six heures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Et il arriva qu’ayant faim, il voulut prendre son repas; et comme ceux de la maison lui apprêtaient à manger, il lui survint un ravissement d’esprit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'Et il vit le ciel ouvert, et un vaisseau descendant sur lui comme un grand linceul, lié par les quatre bouts, et descendant en terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'Dans lequel il y avait de toutes sortes d’animaux terrestres à quatre pieds, des bêtes sauvages, des reptiles, et des oiseaux du ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Et une voix lui fut adressée, disant: Pierre, lève-toi, tue, et mange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Mais Pierre répondit: je n’ai garde, Seigneur! car jamais je n’ai mangé aucune chose immonde ou souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Et la voix lui dit encore pour la seconde fois: les choses que Dieu a purifiées, ne les tiens point pour souillées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Et cela arriva jusques à trois fois, et puis le vaisseau se retira au ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Or comme Pierre était en peine en lui-même, pour savoir quel était le sens de cette vision qu’il avait vue, alors voici, les hommes envoyés par Corneille s’enquérant de la maison de Simon, arrivèrent à la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'Et ayant appelé quelqu’un, ils demandèrent si Simon, qui était surnommé Pierre, était logé là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Et comme Pierre pensait à la vision, l’Esprit lui dit: voilà trois hommes qui te demandent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Lève-toi donc, et descends, et t’en va avec eux, sans en faire difficulté: car c’est moi qui les ai envoyés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Pierre donc, étant descendu vers les gens qui lui avaient été envoyés par Corneille leur dit: voici, je suis celui que vous cherchez; quelle est la cause pour laquelle vous êtes venus?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Et ils dirent: Corneille Centenier, homme juste et craignant Dieu, et ayant un bon témoignage de toute la nation des Juifs, a été averti de Dieu par un saint Ange de t’envoyer quérir pour venir en sa maison, et t’ouïr parler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Alors Pierre les ayant fait entrer, les logea; et le lendemain il s’en alla avec eux, et quelques-uns des frères de Joppe lui tinrent compagnie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'Et le lendemain ils entrèrent à Césarée. Or Corneille les attendait, ayant appelé ses parents et ses familiers amis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Et il arriva que comme Pierre entrait, Corneille venant au-devant de lui, et se jetant à ses pieds, l’adora.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Mais Pierre le releva, en lui disant: lève-toi, je suis aussi un homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Puis en parlant avec lui, il entra, et trouva plusieurs personnes qui étaient là assemblées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'Et il leur dit: vous savez comme il n’est pas permis à un homme Juif de se lier avec un étranger, ou d’aller chez lui, mais Dieu m’a montré que je ne devais estimer aucun homme être impur ou souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'C’est pourquoi dès que vous m’avez envoyé quérir, je suis venu sans en faire difficulté. Je vous demande donc pour quel sujet vous m’avez envoyé quérir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Et Corneille lui dit: il y a quatre jours à cette heure-ci, que j’étais en jeûne, et que je faisais la prière à neuf heures dans ma maison; et voici, un homme se présenta devant moi en un vêtement éclatant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'Et il me dit: Corneille, ta prière est exaucée, et Dieu s’est souvenu de tes aumônes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Envoie donc à Joppe, et fais venir de là Simon, surnommé Pierre, qui est logé dans la maison de Simon corroyeur, près de la mer, lequel étant venu, te parlera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'C’est pourquoi j’ai d’abord envoyé vers toi, et tu as bien fait de venir. Or maintenant nous sommes tous présents devant Dieu pour entendre tout ce que Dieu t’a commandé de nous dire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Alors Pierre prenant la parole, dit: en vérité je reconnais que DIeu n’a point d’égard à l’apparence des personnes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'Mais qu’en toute nation celui qui le craint, et qui s’adonne à la justice, lui est agréable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'c’est ce qu’il a envoyé signifier aux enfants d’Israël, en annonçant la paix par Jésus-Christ, qui est le Seigneur de tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Vous savez ce qui est arrivé dans toute la Judée en commençant par la Galilée, après le Baptême que Jean a prêché;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'Savoir, comment Dieu a oint du Saint-Esprit et de force Jésus le Nazarien, qui a passé de lieu en lieu, en faisant du bien, et guérissant tous ceux qui étaient sous le pouvoir du démon: car Dieu était avec Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'Et nous sommes témoins de toutes les choses qu’il a faites, tant au pays des Juifs, qu’à Jérusalem; et comment ils l’ont fait mourir le pendant au bois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Mais Dieu l’a ressuscité le troisième jour, et l’a donné pour être manifesté;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'Non à tout le peuple, mais aux témoins auparavant ordonnés de Dieu, à nous, dis-je, qui avons mangé et bu avec lui après qu’il a été ressuscité des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'Et il nous a commandé de prêcher au peuple, et de témoigner que c’est lui qui est destiné de Dieu pour être le Juge des vivants et des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Tous les Prophètes lui rendent témoignage, que quiconque croira en lui, recevra la rémission de ses péchés par son Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Comme Pierre tenait encore ce discours, le Saint-Esprit descendit sur tous ceux qui écoutaient la parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'Mais les Fidèles de la Circoncision qui étaient venus avec Pierre, s’étonnèrent de ce que le don du Saint-Esprit était aussi répandu sur les Gentils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'Car ils les entendaient parler diverses Langues, et glorifier Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Alors Pierre prenant la parole, dit: qu’est-ce qui pourrait s’opposer à ce que ceux-ci, qui ont reçu comme nous le Saint-Esprit, ne soient baptisés d’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'Il commanda donc qu’ils fussent baptisés au Nom du Seigneur. Alors ils le prièrent de demeurer là quelques jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Or les Apôtres et les frères qui étaient en Judée, apprirent que les Gentils aussi avaient reçu la parole de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Et quand Pierre fut remonté à Jérusalem, ceux de la Circoncision disputaient avec lui,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'Disant: tu es entré chez des hommes incirconcis, et tu as mangé avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Alors Pierre commençant leur exposa le tout par ordre, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'J’étais en prière dans la ville de Joppe, et étant ravi en esprit, je vis une vision, savoir un vaisseau comme un grand linceul, qui descendait du ciel, lié par les quatre bouts, et qui vint jusqu’à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Dans lequel ayant jeté les yeux, j’y aperçus et j y vis des animaux terrestres à quatre pieds, des bêtes sauvages, des reptiles, et des oiseaux du ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'J’ouïs aussi une voix qui me dit: Pierre, lève-toi, tue, et mange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Et je répondis: je n’ai garde, Seigneur! car jamais chose immonde, ou souillée, n’entra dans ma bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Et la voix me répondit encore du ciel: ce que Dieu a purifié, ne le tiens point pour souillé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Et cela se fit jusqu’à trois fois; et puis toutes ces choses furent retirées au ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Et voici, en ce même instant trois hommes, qui avaient été envoyés de Césarée vers moi, se présentèrent à la maison où j’étais;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Et l’Esprit me dit que j’allasse avec eux, sans en faire difficulté; et ces six frères-ci vinrent aussi avec moi, et nous entrâmes dans la maison de cet homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Et il nous raconta comme il avait vu dans sa maison un Ange qui s’était présenté à lui, et qui lui avait dit: envoie des gens à Joppe, et fais venir Simon qui est surnommé Pierre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'Qui te dira des choses par lesquelles tu seras sauvé, toi, et toute ta maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Et quand j’eus commencé à parler, le Saint-Esprit descendit sur eux, comme aussi il était descendu sur nous au commencement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Alors je me souvins de cette parole du Seigneur, et comment il avait dit: Jean a baptisé d’eau, mais vous serez baptisés du Saint- Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Puis donc que Dieu leur a accordé un pareil don qu’à nous qui avons cru au Seigneur Jésus-Christ, qui étais-je moi, qui pusse m’opposer à Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Alors ayant ouï ces choses, ils s’apaisèrent, et ils glorifièrent Dieu, en disant: Dieu a donc donné aussi aux Gentils la repentance pour avoir la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Or quant à ceux qui avaient été dispersés par la persécution excitée à l’occasion d’Etienne, ils passèrent jusqu’en Phénicie, et en Cypre, et à Antioche, sans annoncer la parole à personne qu’aux Juifs seulement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Mais il y en eut quelques-uns d’entre eux, Cypriens, et Cyréniens, qui étant entrés dans Antioche, parlaient aux Grecs, annonçant le Seigneur Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'Et la main du Seigneur était avec eux; tellement qu’un grand nombre ayant cru, fut converti au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Et le bruit en vint aux oreilles de l’Eglise qui était à Jérusalem: c’est pourquoi ils envoyèrent Barnabas pour passer à Antioche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Lequel y étant arrivé, et ayant vu la grâce de Dieu, il s’en réjouit; et il les exhortait tous de demeurer attachés au Seigneur de tout leur coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Car il était homme de bien, et plein du Saint-Esprit, et de foi; et un grand nombre de personnes se joignirent au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Puis Barnabas s’en alla à Tarse, pour chercher Saul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'Et l’ayant trouvé il le mena à Antioche; et il arriva que durant un an tout entier, ils s’assemblèrent avec l’Eglise, et enseignèrent un grand peuple, de sorte que ce fut premièrement à Antioche que les disciples furent nommés Chrétiens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'Or en ces jours-là quelques Prophètes descendirent de Jérusalem à Antioche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Et l’un d’eux, nommé Agabus, se leva, et déclara par l’Esprit, qu’une grande famine devait arriver dans tout le monde; et, en effet, elle arriva sous Claude César.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Et les disciples, chacun selon son pouvoir, déterminèrent d’envoyer quelque chose pour subvenir aux frères qui demeuraient en Judée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'Ce qu’ils firent aussi, l’envoyant aux Anciens par les mains de Barnabas et de Saul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'En ce même temps le Roi Hérode se mit à maltraiter quelques-uns de ceux de l’Eglise;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Et fit mourir par l’épée Jacques, frère de Jean.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Et voyant que cela était agréable aux Juifs, il continua, en faisant prendre aussi Pierre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Or c’étaient les jours des pains sans levain. Et quand il l’eut fait prendre, il le mit en prison, et le donna à garder à quatre bandes, de quatre soldats chacune, le voulant produire au supplice devant le peuple, après la fête de Pâque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Ainsi Pierre était gardé dans la prison; mais l’Eglise faisait sans cesse des prières à Dieu pour lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Or dans le temps qu’Hérode était prêt de l’envoyer au supplice, cette nuit-là même Pierre dormait entre deux soldats, lié de deux chaînes; et les gardes qui étaient devant la porte, gardaient la prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Et voici, un Ange du Seigneur survint, et une lumière resplendit dans la prison, et l’Ange frappant le côté de Pierre, le réveilla, en lui disant: Lève-toi légère- ment. Et les chaînes tombèrent de ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Et l’Ange lui dit: ceins-toi, et chausse tes souliers; ce qu’il fit. Puis il lui dit: jette ta robe sur toi, et me suis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Lui donc sortant, le suivit; mais il ne savait point que ce qui se faisait par l’Ange, fût réel, car il croyait voir quelque vision.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Et quand ils eurent passé la première et la seconde garde, ils vinrent à la porte de fer, par où l’on va à la ville, et cette porte s’ouvrit à eux d’elle-même, et étant sortis, ils passèrent une rue, et subitement l’Ange se retira d’auprès de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Alors Pierre étant revenu à soi dit: je sais à présent pour sûr que le Seigneur a envoyé son Ange, et qu’il m’a délivré de la main d’Hérode, et de toute l’attente du peuple Juif.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Et ayant considéré le tout, il vint à la maison de Marie, mère de Jean surnommé Marc, où plusieurs étaient assemblés, et faisaient des prières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Et quand il eut heurté à la porte du vestibule, une servante, nommée Rhode, vint pour écouter;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'Laquelle ayant connu la voix de Pierre, de joie n’ouvrit point le vestibule, mais elle courut dans la maison, et annonça que Pierre était devant la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Et ils lui dirent: tu es folle. Mais elle assurait que ce qu’elle disait était vrai; et eux disaient: c’est son Ange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Mais Pierre continuait à heurter; et quand ils eurent ouvert, ils le virent, et furent comme ravis hors d’eux-mêmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Et lui leur ayant fait signe de la main qu’ils fissent silence, leur raconta comment le Seigneur l’avait fait sortir de la prison, et il leur dit: annoncez ces choses à Jacques et aux frères. Puis sortant de là il s’en alla en un autre lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Mais le jour étant venu il y eut un grand trouble entre les soldats, pour savoir ce que Pierre était devenu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Et Hérode l’ayant cherché, et ne le trouvant point, après en avoir fait le procès aux gardes, il commanda qu’ils fussent menés au supplice. Puis il descendit de Judée à Césarée, où il séjourna.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Or il était dans le dessein de faire la guerre aux Tyriens et aux Sidoniens; mais ils vinrent à lui d’un commun accord; et ayant gagné Blaste, qui était Chambel- lan du Roi, ils demandèrent la paix, parce que leur pays était nourri de celui du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'Dans un jour marqué, Hérode, revêtu d’une robe royale, s’assit sur son trône, et les haranguait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'Sur quoi le peuple s’écria: Voix d’un Dieu, et non point d’un homme!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Et à l’instant un Ange du Seigneur le frappa, parce qu’il n’avait point donné gloire à Dieu; et il fut rongé des vers, et rendit l’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Mais la parole de Dieu faisait des progrès et se répandait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Barnabas aussi et Saul, après avoir achevé leur commission, s’en retournèrent de Jérusalem, ayant aussi pris avec eux Jean, qui était surnommé Marc.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Or il y avait dans l’Eglise qui était à Antioche, des Prophètes et des Docteurs, savoir Barnabas, Siméon appelé Niger, Lucius le Cyrénien, Manahem, qui avait été nourri avec Hérode le Tétrarque, et Saul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Et comme ils servaient le Seigneur dans leur ministère, et qu’ils jeûnaient, le Saint-Esprit dit: séparez-moi Barnabas et Saul, pour l’oeuvre à laquelle je les ai appelés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Alors ayant jeûné et prié, et leur ayant imposé les mains, ils les laissèrent partir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Eux donc étant envoyés par le Saint-Esprit, descendirent en Séleucie, et de là ils naviguèrent en Cypre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Et quand ils furent à Salamis, ils annoncèrent la parole de Dieu dans les Synagogues des Juifs; et ils avaient aussi Jean pour leur aider.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Puis ayant traversé l’île jusqu’à Paphos, ils trouvèrent là un certain enchanteur, faux-Prophète Juif, nommé Bar-Jésus,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Qui était avec le Proconsul Serge Paul, homme prudent, lequel fit appeler Barnabas et Saul, désirant d’ouïr la parole de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Mais Elymas, c’est-à-dire, l’enchanteur, car c’est ce que signifie ce nom d’Elymas, leur résistait, tâchant de détourner de la foi le Proconsul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Mais Saul, qui est aussi appelé Paul, étant rempli du Saint-Esprit, et ayant les yeux arrêtés sur lui, dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'Ô homme plein de toute fraude et de toute ruse, fils du Démon, ennemi de toute justice, ne cesseras-tu point de renverser les voies du Seigneur qui sont droites?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'C’est pourquoi, voici la main du Seigneur va être sur toi, et tu seras aveugle sans voir le soleil jusqu’à un certain temps. Et à l’instant une obscurité et des ténèbres tombèrent sur lui, et tournant de tous côtés il cherchait quelqu’un qui le conduisît par la main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Alors le Proconsul voyant ce qui était arrivé, crut, étant rempli d’admiration pour la doctrine du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Et quand Paul et ceux qui étaient avec lui furent partis de Paphos, ils vinrent à Perge, ville de Pamphylie; mais Jean s’étant retiré d’avec eux, s’en retourna à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Et eux étant partis de Perge, vinrent à Antioche, ville de Pisidie, et étant entrés dans la Synagogue le jour du Sabbat, ils s’assirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Et après la lecture de la Loi et des Prophètes, les Principaux de la Synagogue leur envoyèrent dire: hommes frères! s’il y a de votre part quelque parole d’exhortation pour le peuple, dites-la.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Alors Paul s’étant levé, et ayant fait signe de la main qu’on fit silence, dit: hommes Israëlites, et vous qui craignez Dieu, écoutez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Le Dieu de ce peuple d’Israël a élu nos pères, et a distingué glorieusement ce peuple du temps qu’ils demeuraient au pays d’Egypte, et il les en fit sortir avec un bras élevé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'Et il les supporta au désert environ quarante ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'Et ayant détruit sept nations au pays de Canaan, il leur en distribua le pays parle sort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'Et environ quatre cent cinquante ans après, il leur donna des Juges, jusqu’ à Samuel le Prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Puis ils demandèrent un Roi, et Dieu leur donna Saül fils de Kis, homme de la Tribu de Benjamin; et ainsi se passèrent quarante ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'Et Dieu l’ayant ôté, leur suscita David pour Roi, duquel aussi il rendit ce témoignage, et dit: j’ai trouvé David fils de Jessé, un homme selon mon coeur, et qui fera toute ma volonté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Ç’a été de sa semence que Dieu, selon sa promesse, a suscité Jésus pour Sauveur à Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Jean ayant auparavant prêché le Baptême de repentance à tout le peuple d’Israël, avant la venue de Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Et comme Jean achevait sa course, il disait: qui pensez-vous que je sois? je ne suis point le Christ, mais voici, il en vient un après moi, dont je ne suis pas digne de délier le soulier de ses pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Hommes frères! enfants qui descendez d’Abraham, et ceux d’entre vous qui craignez Dieu, c’est à vous que la parole de ce salut a été envoyée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Car les habitants de Jérusalem et leurs Gouverneurs ne l’ayant point connu, ont même en le condamnant accompli les paroles des Prophètes, qui se lisent chaque Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'Et quoiqu’ils ne trouvassent rien en lui qui fût digne de mort, ils prièrent Pilate de le faire mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'Et après qu’ils eurent accompli toutes les choses qui avaient été écrites de lui, on l’ôta du bois, et on le mit dans un sépulcre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Mais Dieu l’a ressuscité des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'Et il a été vu durant plusieurs jours par ceux qui étaient montés avec lui de Galilée à Jérusalem, qui sont ses témoins devant le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'Et nous vous annonçons quant à la promesse qui a été faite à nos pères,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'Que Dieu l’a accomplie envers nous qui sommes leurs enfants; ayant suscité Jésus, selon qu’il est écrit au Psaume second: tu es mon Fils, je t’ai aujourd’hui engendré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Et pour montrer qu’il l’a ressuscité des morts, pour ne devoir plus retourner au sépulcre, il a dit ainsi: je vous donnerai les saintetés de David assurées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'C’est pourquoi il a dit aussi dans un autre endroit: tu ne permettras point que ton Saint sente la corruption.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Car certes David, après avoir servi en son temps au conseil de Dieu, s’est endormi, et a été mis avec ses pères, et a senti la corruption.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Mais celui que Dieu a ressuscité n’a point senti de corruption.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Sachez donc, hommes Frères! que c’est par lui que vous est annoncée la rémission des péchés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'Et que de tout ce dont vous n’avez pu être justifiés par la Loi de Moïse, quiconque croit est justifié par lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Prenez donc garde qu’il ne vous arrive ce qui est dit dans les Prophètes:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, 'Voyez, contempteurs, et vous en étonnez, et soyez dissipés: car je m’en vais faire une oeuvre en votre temps, une oeuvre que vous ne croirez point, si quel- qu’un vous la raconte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Puis étant sortis de la Synagogue des Juifs, les Gentils les prièrent qu’au Sabbat suivant ils leur annonçassent ces paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Et quand l’assemblée fut séparée, plusieurs des Juifs et des prosélytes qui servaient Dieu, suivirent Paul et Barnabas, qui en leur parlant les exhortaient à persévérer en la grâce de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'Et le Sabbat suivant, presque toute la ville s’assembla pour ouïr la parole de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Mais les Juifs voyant toute cette multitude, furent remplis d’envie, et contredisaient à ce que Paul disait, contredisant et blasphémant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Alors Paul et Barnabas s’étant enhardis, leur dirent: c’était bien à vous premièrement qu’il fallait annoncer la parole de Dieu, mais puisque vous la rejetez, et que vous vous jugez vous-mêmes indignes de la vie éternelle, voici, nous nous tournons vers les Gentils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Car le Seigneur nous l’a ainsi commandé, disant: je t’ai établi pour être la lumière des Gentils, afin que tu sois en salut jusques aux bouts de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Et les Gentils entendant cela, s’en réjouissaient, et ils glorifiaient la parole du Seigneur; et tous ceux qui étaient destinés à la vie éternelle, crurent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'Ainsi la parole du Seigneur se répandait par tout le pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Mais les Juifs excitèrent quelques femmes dévotes et distinguées, et les principaux de la ville, et ils émurent une persécution contre Paul et Barnabas, et les chassèrent de leurs quartiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Mais eux ayant secoué contre eux la poudre de leurs pieds, s’en vinrent à Iconie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Et les disciples étaient remplis de joie et du Saint-Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Or il arriva qu’étant à Iconie, ils entrèrent ensemble dans la Synagogue des Juifs, et ils parlèrent d’une telle manière, qu’une grande multitude de Juifs et de Grecs crut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Mais ceux d’entre les Juifs qui furent rebelles, émurent et irritèrent les esprits des Gentils contre les frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Ils demeurèrent donc là assez longtemps, parlant hardiment pour le Seigneur, qui rendait témoignage à la parole de sa grâce, faisant en sorte que des prodiges et des miracles s’opérassent par leur moyen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Mais la multitude de la ville fut partagée en deux, et les uns étaient du côté des Juifs, et les autres du côté des Apôtres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Et comme il se fut fait une émeute tant des Gentils que des Juifs, et de leurs Gouverneurs, pour insulter les Apôtres, et pour les lapider,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'Eux l’ayant su, s’enfuirent aux villes de Lycaonie, savoir à Lystre, et à Derbe, et aux quartiers d’alentour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'Et ils y annoncèrent l’Evangile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Or il y avait à Lystre un homme, impotent de ses pieds, perclus dès le ventre de sa mère, qui n’avait jamais marché, et qui se tenait là assis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Cet homme ouït parler Paul, qui ayant arrêté ses yeux sur lui, et voyant qu’il avait la foi pour être guéri,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'Lui dit à haute voix: lève-toi droit sur tes pieds. Et il se leva en sautant, et marcha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Et les gens qui étaient là assemblés, ayant vu ce que Paul avait fait, élevèrent leur voix, disant en Langue Lycaonienne: les dieux s’étant faits semblables aux hommes, sont descendus vers nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Et ils appelaient Barnabas Jupiter, et Paul Mercure, parce que c’était lui qui portait la parole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Et même le Sacrificateur de Jupiter, qui était devant leur ville, ayant amené des taureaux couronnés jusqu’à l’entrée de la porte, voulait leur sacrifier avec la foule.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Mais les Apôtres Barnabas et Paul ayant appris cela, ils déchirèrent leurs vêtements et se jetèrent au milieu de la foule, en s’écriant,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'Et disant: hommes! pourquoi faites-vous ces choses? nous sommes aussi des hommes, sujets aux mêmes passions que vous, et nous vous annonçons que de ces choses vaines vous vous convertissiez au Dieu vivant, qui a fait le ciel et la terre, la mer, et toutes les choses qui y sont.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Lequel dans les siècles passés, a laissé toutes les nations marcher dans leurs voies;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Quoiqu’il ne se soit pas laissé sans témoignage, en faisant du bien, et en nous donnant des pluies du ciel, et des saisons fertiles, et en remplissant nos coeurs de viande et de joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Et en disant ces choses, à peine empêchèrent-ils les troupes de leur sacrifier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Sur quoi quelques Juifs d’Antioche et d’Iconie étant survenus, ils gagnèrent le peuple, de sorte qu’ayant lapidé Paul, ils le traînèrent hors de la ville, croyant qu’il fût mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Mais les disciples s’étant assemblés autour de lui, il se leva, et entra dans la ville; et le lendemain il s’en alla avec Barnabas à Derbe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Et après qu’ils eurent annoncé l’Evangile en cette ville-là, et instruit plusieurs personnes, ils retournèrent à Lystre, à Iconie, et à Antioche;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Fortifiant l’esprit des disciples, et les exhortant à persévérer en la foi, et leur faisant sentir que c’est par plusieurs afflictions qu’il nous faut entrer dans le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Et après que par l’avis des assemblées ils eurent établi des Anciens dans chaque Eglise, ayant prié avec jeûnes, ils les recommandèrent au Seigneur, en qui ils avaient cru.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Puis ayant traversé la Pisidie, ils allèrent en Pamphylie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'Et ayant annoncé la parole à Perge, ils descendirent à Attalie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'Et de là ils naviguèrent à Antioche, d’où ils avaient été recommandés à la grâce de Dieu, pour l’oeuvre qu’ils avaient finie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Et quand ils furent arrivés, et qu’ils eurent assemblé l’Eglise, ils racontèrent toutes les choses que Dieu avait faites par eux, et comment il avait ouvert aux Gentils la porte de la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'Et ils demeurèrent là longtemps avec les disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Or quelques-uns qui étaient descendus de Judée, enseignaient les frères, en disant: si vous n’êtes circoncis selon l’usage de Moïse, vous ne pouvez point être sauvés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Sur quoi une grande contestation et une grande dispute s’étant excitée entre Paul et Barnabas et eux, il fut résolu que Paul et Barnabas, et quelques autres d’entre eux, monteraient à Jérusalem vers les Apôtres et les Anciens, pour cette question.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Eux donc étant envoyés de la part de l’Eglise, traversèrent la Phénicie et la Samarie, racontant la conversion des Gentils; et ils causèrent une grande joie à tous les frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Et étant arrivés à Jérusalem, ils furent reçus de l’Eglise, et des Apôtres, et des Anciens, et ils racontèrent toutes les choses que Dieu avait faites par leur moyen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Mais quelques-uns, disaient-ils, de la secte des Pharisiens qui ont cru, se sont levés, disant qu’il les faut circoncire, et leur commander de garder la Loi de Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Alors les Apôtres et les Anciens s’assemblèrent pour examiner cette affaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Et après une grande discussion Pierre se leva, et leur dit: hommes frères, vous savez que depuis longtemps Dieu m’ a choisi entre nous, afin que les Gentils ouïssent par ma bouche la parole de l’Evangile, et qu’ils crussent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Et Dieu, qui connaît les coeurs, leur a rendu témoignage, en leur donnant le Saint-Esprit, de même qu’à nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'Et il n’a point fait de différence entre nous et eux: ayant purifié leurs coeurs par la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Maintenant donc pourquoi tentez-vous Dieu en voulant imposer aux disciples un joug que ni nos pères ni nous n’avons pu porter?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Mais nous croyons que nous serons sauvés par la grâce du Seigneur Jésus-Christ, comme eux aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Alors toute l’assemblée se tut; et ils écoutaient Barnabas et Paul, qui racontaient quels prodiges et quelles merveilles Dieu avait faits par leur moyen entre les Gentils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Et après qu’ils se furent tus, Jacques prit la parole, et dit: hommes frères, écoutez-moi!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Simon a raconté comment Dieu a premièrement regardé les Gentils pour en tirer un peuple consacré à son Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'Et c’est à cela que s’accordent les paroles des Prophètes, selon qu’il est écrit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, 'Après cela je retournerai et rebâtirai le Tabernacle de David, qui est tombé, je réparerai ses ruines, et je le relèverai,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'Afin que le reste des hommes recherche le Seigneur, et toutes les nations aussi sur lesquelles mon Nom est réclamé, dit le Seigneur, qui fait toutes ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'De tout temps sont connues à Dieu toutes ses oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'C’est pourquoi je suis d’avis de ne point inquiéter ceux des Gentils qui se convertissent à Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'Mais de leur écrire qu’ils aient à s’abstenir des souillures des idoles et de la fornication et des bêtes étouffées, et du sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Car quant à Moïse, il y a de toute ancienneté dans chaque ville des gens gui le prêchent, vu qu’il est lu dans les Synagogues chaque jour de Sabbat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Alors il sembla bon aux Apôtres et aux Anciens avec toute l’Eglise, d’envoyer à Antioche avec Paul et Barnabas des hommes choisis entre eux, savoir Judas, surnommé Barsabas et Silas, qui étaient des principaux entre les frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'Et ils écrivirent par eux en ces termes: Les Apôtres, et les Anciens, et les frères, aux frères d’entre les Gentils à Antioche, et en Syrie, et en Cilicie, salut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Parce que nous avons entendu que quelques-uns étant partis d’entre nous, vous ont troublés par certains discours, agitant vos âmes, en vous commandant d’être circoncis, et de garder la Loi, sans que nous leur en eussions donné aucun ordre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'Nous avons été d’avis, étant assemblés tous d’un commun accord, d’envoyer vers vous, avec nos très chers Barnabas et Paul, des hommes que nous avons choisis;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'Et qui sont des hommes qui ont abandonné leurs vies pour le Nom de notre Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Nous avons donc envoyé Judas et Silas, qui vous feront entendre les mêmes choses de bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Car il a semblé bon au Saint-Esprit et à nous, de ne mettre point de plus grande charge sur vous que ces choses-ci, qui sont nécessaires;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'Savoir, que vous vous absteniez des choses sacrifiées aux idoles, et du sang, et des bêtes étouffées, et de la fornication; desquelles choses si vous vous gardez, vous ferez bien. Bien vous soit!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Après avoir donc pris congé, ils vinrent à Antioche, et ayant assemblé l’Eglise, ils rendirent les Lettres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Et quand ceux d’Antioche les eurent lues, ils furent réjouis par la consolation qu’elles leur donnèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'De même Judas et Silas, qui étaient aussi Prophètes, exhortèrent les frères par plusieurs discours, et les fortifièrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'Et après avoir demeuré là quelque temps, ils furent renvoyés en paix par les frères vers les Apôtres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, 'Mais il sembla bon à Silas de demeurer là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Et Paul et Barnabas demeurèrent aussi à Antioche, enseignant et annonçant, avec plusieurs autres, la parole du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Et quelques jours après, Paul dit à Barnabas: retournons-nous-en, et visitons nos frères par toutes les villes où nous avons annoncé la parole du Seigneur, pour voir quel est leur état.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Or Barnabas conseillait de prendre avec eux Jean, surnommé Marc.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Mais il ne semblait pas raisonnable à Paul, que celui qui s’était séparé d’eux dès la Pamphylie, et qui n’était point allé avec eux pour cette oeuvre-là, leur fût adjoint');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Sur quoi il y eut entre eux une contestation qui fit qu’ils se séparèrent l’un de l’autre, et que Barnabas prenant Marc, navigua en Cypre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Mais Paul ayant choisi Silas pour l’accompagner, partit de là, après avoir été recommandé à la grâce de Dieu par les frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'Et il traversa la Syrie et la Cilicie, fortifiant les Eglises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Et il arriva à Derbe et à Lystre, et voici, il y avait là un disciple, nommé Timothée, fils d’une femme Juive, fidèle; mais d’un père Grec;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Lequel avait un bon témoignage des frères qui étaient à Lystre, et à Iconie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'C’est pourquoi Paul voulut qu’il allât avec lui; et l’ayant pris avec soi, il le circoncit, à cause des Juifs qui étaient en ces lieux-là: car ils savaient tous que son père était Grec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Eux donc passant par les villes les instruisaient de garder les ordonnances décrétées par les Apôtres, et par les Anciens de Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Ainsi les Eglises étaient affermies dans la foi, et croissaient en nombre chaque jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Puis ayant traversé la Phrygie et le pays de Galatie, il leur fut défendu par le Saint-Esprit d’annoncer la parole en Asie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Et étant venus en Mysie, ils essayaient d’aller en Bithynie; mais l’Esprit de Jésus ne le leur permit point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'C’est pourquoi ayant passé la Mysie, ils descendirent à Troas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Et Paul eut de nuit une vision, d’un homme Macédonien qui se présenta devant lui, et le pria, disant: passe en Macédoine, et nous aide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Quand donc il eut vu cette vision, nous tâchâmes aussitôt d’aller en Macédoine, concluant de là que le Seigneur nous avait appelés pour leur évangéliser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Ainsi étant partis de Troas, nous tirâmes droit à Samothrace, et le lendemain à Néapolis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'Et de là à Philippes, qui est la première ville du quartier de Macédoine, et est une colonie; et nous séjournâmes quelque temps dans la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'Et le jour du Sabbat nous sortîmes de la ville, et allâmes au lieu où on avait accoutumé de faire la prière, près du fleuve, et nous étant là assis nous parlâmes aux femmes qui y étaient assemblées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Et une femme, nommée Lydie, marchande de pourpre, qui était de la ville de Thyatire, et qui servait Dieu nous ouit, et le Seigneur lui ouvrit le coeur, afin qu’elle se rendît attentive aux choses que Paul disait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Et après qu’elle eut été baptisée, avec sa famille, elle nous pria, disant: Si vous m’estimez être fidèle au Seigneur, entrez dans ma maison, et y demeurez. Et elle nous y contraignit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Or il arriva que comme nous allions à la prière, nous fûmes rencontrés par une servante qui avait un esprit de Python, et qui apportait un grand profit à ses maîtres en devinant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Et elle se mit à nous suivre, Paul et nous, en criant, et disant: ces hommes sont les serviteurs du Dieu souverain, et ils vous annoncent la voie du salut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Et elle fit cela durant plusieurs jours; mais Paul en étant importuné, se tourna, et dit à l’esprit: je te commande au Nom de Jésus-Christ de sortir de cette fille; et il en sortit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Mais ses maîtres voyant que l’espérance de leur gain était perdue, se saisirent de Paul et de Silas, et les traînèrent dans la place publique devant les Magistrats.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'Et ils les présentèrent aux Gouverneurs, en disant: ces hommes- ci, qui sont Juifs, troublent notre ville:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'Car ils annoncent des maximes qu’il ne nous est pas permis de recevoir, ni de garder, vu que nous sommes Romains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'Le peuple aussi se souleva ensemble contre eux, et les Gouverneurs leur ayant fait déchirer leurs robes, commandèrent qu’ils fussent fouettés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Et après leur avoir donné plusieurs coups de fouet, ils les mirent en prison, en commandant au geôlier de les garder sûrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Et le geôlier ayant reçu cet ordre, les mit au fond de la prison, et leur serra les pieds dans des ceps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Or sur le minuit Paul et Silas priaient, en chantant les louanges de Dieu; en sorte que les prisonniers les entendaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Et tout d’un coup il se fit un si grand tremblement de terre, que les fondements de la prison croulaient; et incontinent toutes les portes s’ouvrirent, et les liens de tous furent détachés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Sur quoi le geôlier s’étant éveillé, et voyant les portes de la prison ouvertes, tira son épée, et se voulait tuer, croyant que les prisonniers s’en fussent fuis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Mals Paul cria à haute voix, en disant: ne te fais point de mal: car nous sommes tous ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Alors ayant demandé de la lumière, il courut dans le cachot, et tout tremblant, se jeta aux pieds de Paul et de Silas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'Et les ayant menés dehors, il leur dit: Seigneurs, que faut-il que je fasse pour être sauvé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Ils dirent: crois au Seigneur Jésus-Christ; et tu seras sauvé, toi et ta maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'Et ils lui annoncèrent la parole du Seigneur, et à tous ceux qui étaient en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'Après cela, les prenant en cette même heure de la nuit, il lava leurs plaies, et aussitôt après il fut baptisé, avec tous ceux de sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Et les ayant amenés en sa maison, il leur servit à manger, et se réjouit, parce qu’avec toute sa maison il avait cru en Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Et quand il fut jour, les Gouverneurs envoyèrent des huissiers pour lui dire: élargis ces gens-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Et le geôlier rapporta ces paroles à Paul, disant: les Gouverneurs ont envoyé dire qu’on vous élargît; sortez donc maintenant, et allez-vous-en en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Mais Paul dit aux huissiers: après nous avoir fouettés publiquement, sans forme de jugement, nous qui sommes Romains, ils nous ont mis en prison; et maintenant ils nous mettent dehors en secret? Il n’en sera pas ainsi, mais qu’ils viennent eux-mêmes, et qu’ils nous mettent dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Et les huissiers rapportèrent ces paroles aux Gouverneurs, qui craignirent, ayant entendu qu’ils étaient Romains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'C’est pourquoi ils vinrent vers eux, et les prièrent; puis les ayant élargis, ils les supplièrent de partir de la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Alors étant sortis de la prison, ils entrèrent chez Lydie, et ayant vu les frères, ils les consolèrent, et ensuite ils partirent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Puis ayant traversé par Amphipolis et par Apollonie, ils vinrent à Thessalonique, où il y avait une Synagogue de Juifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Et Paul selon sa coutume s’y rendit, et durant trois Sabbats il disputait avec eux par les Ecritures;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Expliquant et prouvant qu’il avait fallu que le Christ souffrît, et qu’il ressuscitât des morts, et que ce Jésus, lequel, disait-il, je vous annonce, était le Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Et quelques-uns d’entre eux crurent, et se joignirent à Paul et à Silas, et une grande multitude de Grecs qui servaient Dieu, et des femmes de qualité en assez grand nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Mais les Juifs rebelles étant pleins d’envie, prirent quelques fainéants remplis de malice, qui ayant fait un amas de peuple, firent une émotion dans la ville, et qui ayant forcé la maison de Jason, cherchèrent Paul et Silas pour les amener au peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Mais ne les ayant point trouvés, ils traînèrent Jason et quelques frères devant les Gouverneurs de la ville, en criant: ceux-ci qui ont remué tout le monde, sont aussi venus ici.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'Et Jason les a retirés chez lui; et ils contreviennent tous aux ordonnances de César, en disant qu’il y a un autre Roi, qu’ils nomment Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Ils soulevèrent donc le peuple et les Gouverneurs de la ville, qui entendaient ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Mais après avoir reçu caution de Jason et des autres, ils les laissèrent aller.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Et d’abord les frères mirent de nuit hors de la ville Paul et Silas, pour aller à Bérée, où étant arrivés ils entrèrent dans la Synagogue des Juifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Or ceux-ci furent plus généreux que les Juifs de Thessalonique, car ils reçurent la parole avec toute promptitude, conférant tous les jours les Ecritures, pour savoir si les choses étaient telles qu’on leur disait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Plusieurs donc d’entre eux crurent, et des femmes Grecques de distinction, et des hommes aussi, en assez grand nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Mais quand les Juifs de Thessalonique surent que la parole de Dieu était aussi annoncée par Paul à Bérée, ils y vinrent, et émurent le peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Mais alors les frères firent aussitôt sortir Paul hors de la ville, comme pour aller vers la mer; mais Silas et Timothée demeurèrent encore là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Et ceux qui avaient pris la charge de mettre Paul en sûreté, le menèrent jusqu’à Athènes, et ils en partirent après avoir reçu ordre de Paul de dire à Silas et à Timothée qu’ils le vinssent bientôt rejoindre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Et comme Paul les attendait à Athènes, son esprit s’aigrissait en lui-même, en considérant cette ville entièrement adonnée à l’idolâtrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Il disputait donc dans la Synagogue avec les Juifs et avec les dévots, et tous les jours dans la place publique avec ceux qui s’y rencontraient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Et quelques-uns d’entre les Philosophes Epicuriens et d’entre les Stoïciens, se mirent à parler avec lui, et les uns disaient: que veut dire ce discoureur? et les autres disaient: il semble être annonciateur de dieux étrangers; parce qu’il leur annonçait Jésus et la résurrection.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Et l’ayant pris ils le menèrent dans l’Aréopage, et lui dirent: ne pourrons-nous point savoir quelle est cette nouvelle doctrine dont tu parles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Car tu nous remplis les oreilles de certaines choses étranges; nous voulons donc savoir ce que veulent dire ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Or tous les Athéniens et les étrangers qui demeuraient à Athènes, ne s’occupaient à autre chose qu’à dire ou à ouïr quelque nouvelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Paul étant donc au milieu de l’Aréopage, leur dit: hommes Athéniens! je vous vois comme trop dévots en toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Car en passant et en contemplant vos dévotions, j’ai trouvé même un autel sur lequel était écrit: AU DIEU INCONNU; celui donc que vous honorez sans le connaître, c’est celui que je vous annonce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Le Dieu qui a fait le monde et toutes les choses qui y sont, étant le Seigneur du Ciel et de la terre, n’habite point dans des temples faits de main;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'Et il n’est point servi par les mains des hommes, comme s’il avait besoin de quelque chose, vu que c’est lui qui donne à tous la vie, la respiration, et toutes choses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'Et il a fait d’un seul sang tout le genre humain, pour halbiter sur toute l’étendue de la terre, ayant déterminé les saisons qu’il a établies, et les bornes de leur habitation:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'Afin qu’ils cherchent le Seigneur, pour voir s’ils pourraient en quelque sorte le toucher en tâtonnant, et le trouver; quoiqu’il ne soit pas loin d’un chacun de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Car par lui nous avons la vie, le mouvement et l’être; selon ce que quelques-uns même de vos poëtes ont dit; car aussi nous sommes sa race.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Etant donc la race de Dieu, nous ne devons point estimer que la divinité soit semblable à l’or, ou à l’argent, ou à la pierre taillée par l’art et l’industrie des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Mais Dieu passant par-dessus ces temps de l’ignorance, annonce maintenant à tous les hommes en tous lieux qu’ils se repentent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'Parce qu’il a arrêté un jour auquel il doit juger selon la justice le monde universel, par l’homme qu’il a destiné pour cela; de quoi il a donné une preuve cer- taine à tous, en l’ayant ressuscité d’entre les morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Mais quand ils ouïrent ce mot de la résurrection des morts, les uns s’en moquaient, et les autres disaient: nous t’entendrons encore sur cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'Et Paul sortit ainsi du milieu d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Quelques-uns pourtant se joignirent à lui, et crurent; entre lesquels même était Denis l’Aréopagite, et une femme nommée Damaris, et quelques autres avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Après cela Paul étant parti d’Athènes, vint à Corinthe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Et y ayant trouvé un Juif, nommé Aquile, originaire du pays du Pont, qui un peu auparavant était venu d’Italie, avec Priscille sa femme, parce que Claude avait commandé que tous les Juifs sortissent de Rome, il s’adressa à eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'Et parce qu’il était de même métier, il demeura avec eux, et il travaillait. Or leur métier était de faire des tentes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Et chaque Sabbat il disputait dans la Synagogue, et persuadait tant les Juifs que les Grecs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Et quand Silas et Timothée furent venus de Macédoine, Paul étant poussé par l’Esprit, témoignait aux Juifs que Jésus était le Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Et comme ils le contredisaient, et qu’ils blasphémaient, il secoua ses vêtements, et leur dit: que votre sang soit sur votre tête, j’en suis net! je m’en vais dès à présent vers les Gentils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Et étant sorti de là, il entra dans la maison d’un homme appelé Juste, qui servait Dieu, et duquel la maison tenait à la Synagogue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Mais Crispe, Principal de la Synagogue, crut au Seigneur avec toute sa maison; et plusieurs autres aussi des Corinthiens l’ayant ouï, crurent, et ils furent baptisés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Or le Seigneur dit la nuit à Paul dans une vision: ne crains point, mais parle, et ne te tais point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Parce que je suis avec toi, et personne ne mettra les mains sur toi pour te faire du mal; et j’ai un grand peuple en cette ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Il demeura donc là un an et six mois, enseignant parmi eux la parole de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Mais du temps que Gallion était Proconsul d’Achaïe, les Juifs tous d’un commun accord s’élevèrent contre Paul, et l’amenèrent devant le siège judicial,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'En disant: cet homme persuade les gens de servir Dieu contre la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Et comme Paul voulait ouvrir la bouche, Gallion dit aux Juifs: ô Juifs! s’il était question de quelque injustice, ou de quelque crime, je vous supporterais autant qu’il serait raisonnable;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Mais s’il est question de paroles et de mots, et de votre Loi, vous y mettrez ordre vous-mêmes: car je ne veux point être juge de ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Et il les fit retirer de devant le siège judicial.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Alors tous les Grecs ayant saisi Sosthènes, qui était le Principal de la Synagogue, le battaient devant le siège judicial, sans que Gallion s’en mît en peine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Et quand Paul eut demeuré là encore assez longtemps, il prit congé des frères, et navigua en Syrie, et avec lui Priscille et Aquile, après qu’il se fut fait raser la tête à Cenchrée, parce qu’il avait fait un voeu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Puis il arriva à Ephèse, et les y laissa; mais étant entré dans la Synagogue, il discourut avec les Juifs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Qui le prièrent de demeurer encore plus longtemps avec eux; mais il ne voulut point le leur accorder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'Et il prit congé d’eux, en leur disant: il me faut absolument faire la Fête prochaine à Jérusalem, mais je reviendrai encore vers vous, s’il plaît à Dieu. Ainsi il désancra d’Ephèse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'Et quand il fut descendu à Césarée, il monta à Jérusalem, et après avoir salué l’Eglise, il descendit à Antioche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Et y ayant séjourné quelque temps, il s’en alla, et traversa tout de suite la contrée de Galatie et de Phrygie, fortifiant tous les disciples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Mais il vint à Ephèse un Juif, nommé Apollos, Alexandrin de nation, homme éloquent, et savant dans les Ecritures;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Qui était en quelque manière instruit dans la voie du Seigneur; et comme il avait un grand zèle, il expliquait et enseignait fort exactement les choses qui concernent le Seigneur, quoiqu’il ne connût que le Baptême de Jean.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Il commença donc à parler avec hardiesse dans la Synagogue; et quand Priscille et Aquile l’eurent entendu, ils le prirent avec eux, et lui expliquèrent plus particulièrement la voie de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Et comme il voulut passer en Achaïe, les frères qui l’y avaient exhorté, écrivirent aux disciples de le recevoir, et quand il y fut arrivé, il profita beaucoup à ceux qui avaient cru par la grâce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Car il convainquait publiquement les Juifs avec une grande véhémence, démontrant par les Ecritures que Jésus était le Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Or il arriva comme Apollos était à Corinthe, que Paul après avoir traversé tous les quartiers d’en haut, vint à Ephèse, où ayant trouvé de certains disciples, il leur dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Avez-vous reçu le Saint-Esprit quand vous avez cru? et ils lui répondirent: nous n’avons pas même ouï dire s’il y a un Saint- Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Et il leur dit: de quel Baptême donc avez-vous été baptisés; ils répondirent: du Baptême de Jean.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Alors Paul dit: il est vrai que Jean a baptisé du Baptême de repentance, disant au peuple, qu’ils crussent en celui qui venait après lui, c’est-à-dire, en Jésus- Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Et ayant ouï ces choses, ils furent baptisés au Nom du Seigneur Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'Et après que Paul leur eut imposé les mains, le Saint-Esprit descendit sur eux, et ainsi ils parlèrent divers langages, et prophétisèrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Et tous ces hommes-là étaient environ douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Puis étant entré dans la Synagogue, il parla avec hardiesse l’espace de trois mois, disputant, et persuadant les choses du Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Mais comme quelques-uns s’endurcissaient, et étaient rebelles, parlant mal de la voie du Seigneur devant la multitude, lui s’étant retiré d’avec eux, sépara les disciples; et il disputait tous les jours dans l’école d’un nommé Tyrannus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Et cela continua l’espace de deux ans; de sorte que tous ceux qui demeuraient en Asie, tant Juifs que Grecs, ouïrent la parole du Seigneur Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Et Dieu faisait des prodiges extraordinaires par les mains de Paul:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'De sorte que même on portait de dessus son corps des mouchoirs et des linges sur les malades, et ils étaient guéris de leurs maladies, et les esprits malins sortaient des possédés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Alors quelques-uns d’entre les Juifs exorcistes, qui couraient çà et là, essayèrent d’invoquer le Nom du Seigneur Jésus sur ceux qui étaient possédés des esprits malins, en disant: nous vous conjurons par ce Jésus que Paul prêche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Et ceux qui faisaient cela étaient sept fils de Scéva Juif, principal Sacrificateur');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Mais le malin esprit répondant, dit: je connais Jésus, et je sais qui est Paul; mais vous, qui êtes-vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Et l’homme en qui était le malin esprit, sauta sur eux, et s’en étant rendu le maître, les traita si mal, qu’ils s’enfuirent de cette maison tout nus et blessés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Or cela vint à la connaissance de tous les Juifs et des Grecs qui demeuraient à Ephèse; et ils furent tous saisis de crainte, et le Nom du Seigneur Jésus était glorifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Et plusieurs de ceux qui avaient cru venaient, confessant et déclarant ce qu’ils avaient fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Plusieurs aussi de ceux qui s’étaient adonnés à des pratiques curieuses, apportèrent leurs Livres, et les brûlèrent devant tous, dont ayant supputé le prix, on trouva qu’il montait à cinquante mille pièces d’argent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Ainsi la parole du Seigneur se répandait sensiblement, et produisait de grands effets.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Or après que ces choses furent faites, Paul se proposa par un mouvement de l’Esprit de passer par la Macédoine et par l’Achaïe, et d’aller à Jérusalem, disant: après que j’aurai été là, il me faut aussi voir Rome.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Et ayant envoyé en Macédoine deux de ceux qui l’assistaient, savoir Timothée et Eraste, il demeura quelque temps en Asie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Mais en ce temps-là il arriva un grand trouble, à cause de la doctrine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Car un certain homme, nommé Démétrius, qui travaillait en argenterie, et faisait de petits temples d’argent de Diane, et qui apportait beaucoup de profit aux ouvriers du métier,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Les assembla, avec d’autres qui travaillaient à de semblables ouvrages, et leur dit: Ô hommes! vous savez que tout notre gain vient de cet ouvrage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'Or vous voyez et vous entendez comment non-seulement à Ephèse, mais presque par toute l’Asie, ce Paul-ci par ses persuasions a détourné beaucoup de monde, en disant que ceux-là ne sont point des dieux, qui sont faits de main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Et il n’y a pas seulement de danger pour nous que notre métier ne vienne à être décrié, mais aussi que le Temple de la grande déesse Diane ne soit plus rien estimé, et qu’il n’arrive que sa majesté, laquelle toute l’Asie et le monde universel révère, ne soit anéantie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Et quand ils eurent entendu ces choses, ils furent tous remplis de colère, et s’écrièrent, disant: grande est la Diane des Ephésiens!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Et toute la ville fut remplie de confusion; et ils se jetèrent en foule dans le Théâtre, et enlevèrent Gaïus et Aristarque Macédoniens, compagnons de voyage de Paul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Et comme Paul voulait entrer vers le peuple, les disciples ne le lui permirent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Quelques-uns aussi d’entre les Asiarques, qui étaient ses amis, envoyèrent vers lui, pour le prier de ne se présenter point au Théâtre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Les uns donc criaient d’une façon, et les autres d’une autre, car l’Assemblée était confuse, et plusieurs même ne savaient pas pourquoi ils étaient assemblés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Alors Alexandre fut contraint de sortir hors de la foule, les Juifs le poussant à parler; et Alexandre faisant signe de la main, voulait alléguer quelque excuse au peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Mais quand ils eurent connu qu’il était Juif, il s’éleva une voix de tous, durant l’espace presque de deux heures, en criant: grande est la Diane des Ephésiens!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Mais le Secrétaire de la ville ayant apaisé cette multitude de peuple, dit: hommes Ephésiens, et qui est celui des hommes qui ne sache que la ville des Ephésiens est dédiée au service de la grande déesse Diane, et à son image, descendue de Jupiter?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Ces choses donc étant telles sans contradiction, il faut que vous vous apaisiez, et que vous ne fassiez rien imprudemment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Car ces gens que vous avez amenés, ne sont ni sacrilèges, ni blasphémateurs de votre déesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Mais si Démétrius et les ouvriers qui sont avec lui, ont quelque chose à dire contre quelqu’un, on tient la cour, et il y a des Proconsuls; qu’ils s’y appellent donc les uns les autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Et si vous avez quelque autre chose à demander, cela se pourra décider dans une assemblée dûment convoquée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Car nous sommes en danger d’être accusés de sédition pour ce qui s’est passé aujourd’hui; puisqu’il n’y a aucun sujet que nous puissions alléguer pour rendre raison de cette émeute. Et quand il eut dit ces choses, il congédia l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Or après que le trouble fut cessé, Paul fit venir les disciples, et les ayant embrassés, il partit pour aller en Macédoine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Et quand il eut passé par ces quartiers-là, et qu’il y eut fait plusieurs exhortations, il vint en Grèce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Et après y avoir séjourné trois mois, les Juifs lui ayant dressé des embûches au cas qu’il fût allé s’embarquer pour la Syrie, on fut d’avis de retourner par la Macédoine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Et Sopater Béréen le devait accompagner jusqu’en Asie; et d’entre les Thessaloniciens Aristarque et Second, avec Gaïus Derbien, et Timothée; et de ceux d’Asie, Tychique et Trophime.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Ceux-ci donc étant allés devant, nous attendirent à Troas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Et nous, ayant levé l’ancre à Philippes, après les jours des pains sans levain, nous arrivâmes au bout de cinq jours auprès d’eux à Troas, et nous y séjournâmes sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Et le premier jour de la semaine, les disciples étant assemblés pour rompre le pain, Paul, qui devait partir le lendemain, leur fit un discours, qu’il étendit jusqu’à minuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Or il y avait beaucoup de lampes dans la chambre haute où ils étaient assemblés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Et un jeune homme nommé Eutyche, qui était assis sur une fenêtre, étant abattu d’un profond sommeil pendant le long discours de Paul, emporté du sommeil tomba en bas du troisième étage, et fut levé mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Mais Paul étant descendu, se pencha sur lui, et l’embrassa, et dit: ne vous troublez point, car son âme est en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Et après qu’il fut remonté, et qu’il eut rompu le pain, et mangé, et qu’il eut parlé longtemps jusqu’à l’aube du jour, il partit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Et ils amenèrent là le jeune homme vivant, de quoi ils furent extrêmement consolés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Or étant entrés dans le navire nous fûmes portés à Assos, où nous devions reprendre Paul: car il l’avait ainsi ordonné, ayant résolu de faire ce chemin à pied.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Et lorsqu’il nous eut rejoints à Assos, nous le prîmes avec nous, et nous allâmes à Mitylène.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Puis étant partis de là, le jour suivant nous abordâmes vis-à-vis de Chios; le lendemain nous arrivâmes à Samos; et nous étant arrêtés à Trogyle, nous vînmes le jour d’après à Milet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Car Paul s’était proposé de passer au delà d’Ephèse, afin de ne point séjourner en Asie; parce qu’il se hâtait d’être, s’il lui était possible, le jour de la Pentecôte à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Or il envoya de Milet à Ephèse, pour faire venir les Anciens de l’Eglise;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Qui étant venus vers lui, il leur dit: Vous savez de quelle manière je me suis toujours conduit avec vous dès le premier jour que je suis entré en Asie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'Servant le Seigneur en toute humilité, et avec beaucoup de larmes, et parmi beaucoup d’épreuves, qui me sont arrivées par les embûches des Juifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Et comment je ne me suis épargné en rien de ce qui vous était utile, vous ayant prêché, et ayant enseigné publiquement, et par les maisons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Conjurant les Juifs et les Grecs de se convertir à Dieu, et de croire en Jésus-Christ notre Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Et maintenant voici, étant lié par l’Esprit, je m’en vais à Jérusalem, ignorant les choses qui m’y doivent arriver;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'Sinon que le Saint-Esprit m’avertit de ville en ville, disant que des liens et des tribulations m’attendent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Mais je ne fais cas de rien, et ma vie ne m’est point précieuse, pourvu qu’avec joie j’achève ma course, et le ministère que j’ai reçu du Seigneur Jésus, pour rendre témoignage à l’Evangile de la grâce de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Et maintenant voici, je sais qu’aucun de vous tous, parmi lesquels j’ai passé en prêchant le Royaume de Dieu, ne me verra plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'C’est pourquoi je vous prends aujourd’hui à témoin, que je suis net du sang de tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Car je ne me suis point épargné à vous annoncer tout le conseil de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Prenez donc garde à vous-mêmes, et à tout le troupeau sur lequel le Saint-Esprit vous a établis Evêques, pour paître l’Eglise de Dieu, laquelle il a acquise par son propre sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Car je sais qu’après mon départ il entrera parmi vous des loups très dangereux, qui n’épargneront point le troupeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'Et qu’il se lèvera d’entre vous-mêmes des hommes qui annonceront des doctrines corrompues dans la vue d’attirer des disciples après eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'C’est pourquoi veillez, vous souvenant que durant l’espace de trois ans, je n’ai cessé nuit et jour d’avertir un chacun de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'Et maintenant, mes frères, je vous recommande à Dieu, et à la parole de sa grâce, lequel est puissant pour achever de vous édifier, et pour vous donner l’héritage avec tous les Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Je n’ai convoité ni l’argent, ni l’or, ni la robe de personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Et vous savez vous-mêmes que ces mains m’ont fourni les choses qui m’étaient nécessaires, et à ceux qui étaient avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Je vous ai montré en toutes choses qu’en travaillant ainsi il faut supporter les infirmes, et se souvenir des paroles du Seigneur Jésus, qui a dit qu’on est plus heureux de pouvoir donner que d’être appelé à recevoir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Et quand Paul eut dit ces paroles, il se mit à genoux, et fit la prière avec eux tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Alors tous se fondirent en larmes, et se jetant au cou de Paul, ils le baisaient;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'Etant tristes principalement à cause de cette parole qu’il leur avait dite, qu’ils ne le verraient plus, et ils le conduisirent au navire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Ainsi donc étant partis, et nous étant éloignés d’eux, nous tirâmes droit à Coos, et le jour suivant à Rhodes, et de là à Patara.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Et ayant trouvé là un navire qui traversait en Phénicie, nous montâmes dessus, et partîmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Puis ayant découvert Cypre, nous la laissâmes à main gauche, et tirant vers la Syrie, nous arrivâmes à Tyr: car le navire y devait laisser sa charge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Et ayant trouvé là des disciples, nous y demeurâmes sept jours. Or ils disaient par l’Esprit à Paul qu’il ne montât point à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Mais ces jours-là étant passés, nous partîmes, et nous nous mîmes en chemin, étant conduits de tous avec leurs femmes et leurs enfants, jusque hors de la ville, et ayant mis les genoux en terre sur le rivage, nous fîmes la prière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'Et après nous être embrassés les uns les autres, nous montâmes sur le navire, et les autres retournèrent chez eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Et ainsi achevant notre navigation, nous vînmes de Tyr à Ptolémaïs; et après avoir salué les frères, nous demeurâmes un jour avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Et le lendemain Paul et sa compagnie partant de là, nous vînmes à Césarée; et étant entrés dans la maison de Philippe l’Evangéliste, qui était l’un des sept, nous demeurâmes chez lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Or il avait quatre filles vierges qui prophétisaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Et comme nous fûmes là plusieurs jours, il y arriva de Judée un Prophète, nommé Agabus;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Qui nous étant venu voir, prit la ceinture de Paul, et s’en liant les mains et les pieds, il dit: le Saint-Esprit dit ces choses: Les Juifs lieront ainsi à Jérusalem l’homme à qui est cette ceinture, et ils le livreront entre les mains des Gentils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Quand nous eûmes entendu ces choses, nous, et ceux qui étaient du lieu, nous le priâmes qu’il ne montât point à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Mais Paul répondit: que faites-vous, en pleurant et en affligeant mon coeur? pour moi, je suis tout prêt, non-seulement d’être lié, mais aussi de mourir à Jérusalem pour le Nom du Seigneur Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Ainsi, parce qu’il ne pouvait être persuadé, nous nous tûmes là- dessus, en disant: la volonté du Seigneur soit faite!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Quelques jours après, ayant chargé nos hardes, nous montâmes à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Et quelques-uns des disciples vinrent aussi de Césarée avec nous, amenant avec eux un homme appelé Mnason, Cyprien, qui était un ancien disciple, chez qui nous devions loger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Et quand nous fûmes arrivés à Jérusalem, les frères nous reçurent avec joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Et le jour suivant, Paul vint avec nous chez Jacques, et tous les Anciens y vinrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Et après qu’il les eut embrassés, il raconta en détail les choses que Dieu avait faites parmi les Gentils par son ministère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Ce qu’ayant ouï, ils glorifièrent le Seigneur, et ils dirent à Paul: frère, tu vois combien il y a de milliers de Juifs qui ont cru; et ils sont tous zélés pour la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Or ils ont ouï dire de toi, que tu enseignes tous les Juifs qui sont parmi les Gentils, de renoncer à Moïse, en leur disant qu’ils ne doivent point circoncire leurs enfants, ni vivre selon les ordonnances de la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Que faut-il donc faire? Il faut absolument assembler la multitude des Fidèles, car ils entendront dire que tu es arrivé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Fais donc ce que nous allons te dire: nous avons quatre hommes qui ont fait un voeu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Prends-les avec toi, et te purifie avec eux, et contribue avec eux, afin qu’ils se rasent la tête, et que tous sachent qu’il n’est rien des choses qu’ils ont ouï dire de toi, mais que tu continues aussi de garder la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Mais à l’égard de ceux d’entre les Gentils qui ont cru, nous en avons écrit, ayant ordonné qu’ils n’observent rien de semblable; mais seulement qu’ils s’abstiennent de ce qui est sacrifié aux idoles, du sang, des bêtes étouffées, et de la fornication.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Paul ayant donc pris ces hommes avec lui, et le jour suivant s’étant purifié avec eux, il entra au Temple en dénonçant quel jour leur purification devait s’achever, et continuant ainsi jusqu’à ce que l’oblation fût présentée pour chacun d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Et comme les sept jours s’accomplissaient, quelques Juifs d’Asie ayant vu Paul dans le Temple, soulevèrent tout le peuple, et mirent les mains sur lui,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'En criant: hommes Israélites, aidez- nous! voici cet homme qui partout enseigne tout le monde contre le peuple, contre la Loi, et contre ce Lieu; et qui de plus a aussi amené des Grecs dans le Temple, et a profané ce saint Lieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Car avant cela ils avaient vu avec lui dans la ville Trophime Ephésien, et ils croyaient que Paul l’avait amené dans le Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Et toute la ville fut émue, et le peuple y accourut; et ayant saisi Paul, ils le traînèrent hors du Temple; et on ferma aussitôt les portes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Mais comme ils tâchaient de le tuer, le bruit vint au capitaine de la compagnie de la garnison que tout Jérusalem était en trouble;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Et aussitôt il prit des soldats et des centeniers, et courut vers eux; mais eux voyant le capitaine et les soldats ils cessèrent de battre Paul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Et le capitaine s’étant approché, se saisit de lui, et commanda qu’on le liât de deux chaînes; puis il demanda qui il était, et ce qu’il avait fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'Mais les uns criaient d’une manière, et les autres d’une autre, dans la foule; et parce qu’il ne pouvait en apprendre rien de certain à cause du bruit, il commanda que Paul fût mené dans la forteresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Et quand il fut venu aux degrés, il arriva qu’il fut porté par les soldats, à cause de la violence de la foule;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'Car la multitude du peuple le suivait, en criant: fais-le mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Et comme on allait faire entrer Paul dans la forteresse, il dit au capitaine: m’est-il permis de te dire quelque chose? Et le capitaine lui demanda: Sais-tu parler Grec?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'N’es-tu pas l’Egyptien qui ces jours passés as excité une sédition, et as emmené au désert quatre mille brigands?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Et Paul lui dit: certes je suis Juif, citoyen, natif de Tarse, ville renommée de la Cilicie; mais je te prie, permets-moi de parler au peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Et quand il le lui eut permis, Paul se tenant sur les degrés fit signe de la main au peuple, et s’étant fait un grand silence, il leur parla en Langue Hébraïque, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Hommes frères et pères, écoutez maintenant mon apologie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Et quand ils ouïrent qu’il leur parlait en Langue Hébraïque, ils firent encore plus de silence; et il dit:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Certes je suis Juif, né à Tarse de Cilicie, mais nourri en cette ville aux pieds de Gamaliel, ayant été exactement instruit dans la Loi de nos pères, et étant zélé pour la Loi de Dieu, comme vous l’êtes tous aujourd’hui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Et j’ai persécuté cette doctrine jusques à la mort, liant et mettant dans les prisons, hommes et femmes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Comme le souverain Sacrificateur lui-même, et toute l’assemblée des Anciens m’en sont témoins; desquels aussi ayant reçu des Lettres adressantes aux frères, j’allais à Damas, afin d’amener aussi liés à Jérusalem ceux qui étaient là, pour les faire punir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Or il arriva comme je marchais, et que j’approchais de Damas, environ sur le midi, que tout d’un coup une grande lumière venant du ciel, resplendit comme un éclair autour de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Et je tombai sur la place; et j’entendis une voix qui me dit: Saul, Saul, pourquoi me persécutes-tu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Et je répondis: qui es-tu, Seigneur? et il me dit: je suis Jésus le Nazarien, que tu persécutes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Or ceux qui étaient avec moi virent bien la lumière, et ils en furent tout effrayés, mais ils n’entendirent point la voix de celui qui me parlait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Et je dis: Seigneur, que ferai-je? et le Seigneur me dit: lève- toi, et t’en va à Damas, et là on te dira tout ce que tu dois faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Or parce que je ne voyais rien, à cause de la splendeur de cette lumière, ceux qui étaient avec moi me menèrent par la main, et je vins à Damas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Et un homme nommé Ananias, qui craignait Dieu selon la Loi, et qui avait un bon témoignage de tous les Juifs qui demeuraient là, vint me trouver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'Et étant près de moi, il me dit: Saul mon frère, recouvre la vue: et sur l’heure même je tournai les yeux vers lui, et je le vis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Et il me dit: le Dieu de nos pères t’a préordonné pour connaître sa volonté, et pour voir le Juste, et pour ouïr la voix de sa bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Car tu lui seras témoin envers tous les hommes des choses que tu as vues et ouïes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Et maintenant que tardes-tu? lève-toi, et sois baptisé et purifié de tes péchés, en invoquant le Nom du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Or il arriva qu’après que je fus retourné à Jérusalem, comme je priais dans le Temple, je fus ravi en extase;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'Et je vis le Seigneur qui me dit: hâte-toi, et pars en diligence de Jérusalem: car ils ne recevront point le témoignage que tu leur rendras de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Et je dis: Seigneur! eux-mêmes savent que je mettais en prison, et que je fouettais dans les Synagogues ceux qui croyaient en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'Et lorsque le sang d’Etienne ton martyr fut répandu, j’y étais aussi présent, je consentais à sa mort, et je gardais les vêtements de ceux qui le faisaient mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Mais il me dit: va, car je t’enverrai loin vers les Gentils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Et ils l’écoutèrent jusqu’à ce mot; mais alors ils élevèrent leur voix, en disant: ôte de la terre un tel homme, car il n’est point convenable qu’il vive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Et comme ils criaient à haute voix, et secouaient leurs vêtements, et jetaient de la poussière en l’air,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'le Tribun commanda qu’on le menât dans la forteresse, et il ordonna qu’il fût examiné par le fouet, afin de savoir pour quel sujet ils criaient ainsi contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Et quand ils l’eurent garrotté de courroies, Paul dit au centenier qui était près de lui: vous est-il permis de fouetter un homme Romain, et qui n’est pas même condamné?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Ce que le centenier ayant entendu, il s’en alla au Tribun pour l’avertir, disant: regarde ce que tu as à faire: car cet homme est Romain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Et le Tribun vint à Paul, et lui dit: dis-moi, es-tu Romain? Et il répondit: oui certainement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'Et le Tribun lui dit: J’ai acquis cette bourgeoisie à grand prix d’argent; et Paul dit: mais moi, je l’ai par ma naissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'C’est pourquoi ceux qui le devaient examiner se retirèrent aussitôt d’auprès de lui; et quand le Tribun eut connu qu’il était bourgeois de Rome, il craignit, à cause qu’il l’avait fait lier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Et le lendemain voulant savoir au vrai pour quel sujet il était accusé des Juifs, il le fit délier, et ayant commandé que les principaux Sacrificateurs et tout le conseil s’assemblassent, il fit amener Paul, et il le présenta devant eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Et Paul regardant fixement le Conseil, dit: hommes frères! je me suis conduit en toute bonne conscience devant Dieu jusqu’à ce jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Sur quoi le souverain Sacrificateur Ananias commanda à ceux qui étaient près de lui, de le frapper sur le visage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Alors Paul lui dit: Dieu te frappera, paroi blanchie; puisque étant assis pour me juger selon la Loi, tu commandes, en violant la Loi, que je sois frappé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Et ceux qui étaient présents lui dirent: injuries-tu le souverain Sacrificateur de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Et Paul dit: mes frères, je ne savais pas qu’il fût souverain Sacrificateur: car il est écrit: tu ne médiras point du Prince de ton peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Et Paul sachant qu’une partie d’entre eux était des Sadducéens, et l’autre des Pharisiens, il s’écria dans le conseil: hommes frères! je suis Pharisien, fils de Pharisien, je suis tiré en cause pour l’espérance, et pour la résurrection des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Et quand il eut dit cela, il s’émut une dissension entre les Pharisiens et les Sadducéens; et l’assemblée fut divisée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Car les Sadducéens disent qu’il n’y a point de résurrection, ni d’Ange, ni d’esprit, mais les Pharisiens soutiennent l’un et l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Et il se fit un grand cri. Alors les Scribes du parti des Pharisiens se levèrent et contestèrent, disant: nous ne trouvons aucun mal en cet homme-ci; mais si un esprit ou un Ange lui a parlé, ne combattons point contre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Et comme il se fit une grande division, le Tribun craignant que Paul ne fût mis en pièces par eux, commanda que les soldats descendissent, et qu’ils l’enlevassent du milieu d’eux, et l’amenassent en la forteresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'Et la nuit suivante, le Seigneur se présenta à lui, et lui dit: Paul, aie bon courage: car comme tu as rendu témoignage de moi à Jérusalem, tout de même il faut que tu me rendes aussi témoignage à Rome.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Et quand le jour fut venu, quelques Juifs firent un complot et un serment avec exécration, disant qu’ils ne mangeraient ni ne boiraient jusqu’à ce qu’ils eussent tué Paul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Et ils étaient plus de quarante qui avaient fait cette conjuration.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Et ils s’adressèrent aux principaux Sacrificateurs et aux Anciens, et leur dirent: nous avons fait un voeu, avec exécration de serment, que nous ne goûterions de rien jusqu’à ce que nous ayons tué Paul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Vous donc maintenant faites savoir au Tribun par l’avis du Conseil, qu’il vous l’amène demain, comme si vous vouliez connaître de lui quelque chose plus exactement, et nous serons tous prêts pour le tuer avant qu’il approche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Mais le fils de la soeur de Paul ayant appris cette conjuration, vint et entra dans la forteresse, et le rapporta à Paul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Et Paul ayant appelé un des centeniers, lui dit: mène ce jeune homme au Tribun; car il a quelque chose à lui rapporter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Il le prit donc, et le mena au Tribun, et il lui dit: Paul qui est prisonnier m’a appelé, et m’a prié de t’amener ce jeune homme qui a quelque chose à te dire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Et le Tribun le prenant par la main, se retira à part, et lui demanda: qu’est-ce que tu as à me rapporter?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Et il lui dit: les Juifs ont conspiré de te prier que demain tu envoies Paul au Conseil, comme s’ils voulaient s’enquérir de lui plus exactement de quelque chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Mais n’y consens point: car plus de quarante hommes d’entre eux sont en embûches contre lui, qui ont fait un voeu avec exécration de serment, de ne manger ni boire jusqu’à ce qu’ils l’aient tué; et ils sont maintenant tous prêts, attendant ce que tu leur permettras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Le Tribun donc renvoya le jeune homme, en lui commandant de ne dire à personne qu’il lui eût déclaré ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Puis ayant appelé deux centeniers, il leur dit: tenez prêts à trois heures de la nuit deux cents soldats, et soixante-dix hommes de cheval, et deux cents archers, pour aller à Césarée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'Et ayez soin qu’il y ait des montures prêtes, afin qu’ayant fait monter Paul, ils le mènent sûrement au Gouverneur Félix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Et il lui écrivit une Lettre en ces termes:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Claude Lysias au très-excellent Gouverneur Félix, Salut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Comme cet homme qui avait été saisi par les Juifs, était près d’être tué par eux, je suis survenu avec la garnison, et je le leur ai ôté, après avoir connu qu’il était citoyen Romain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Et voulant savoir de quoi ils l’accusaient, je l’ai mené à leur Conseil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'Où j’ai trouvé qu’il était accusé touchant des questions de leur Loi, n’ayant commis aucun crime digne de mort, ou d’emprisonnement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Et ayant été averti des embûches que les Juifs avaient dressées contre lui, je te l’ai incessamment envoyé; ayant aussi commandé aux accusateurs de dire devant toi les choses qu’ils ont contre lui. Bien te soit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Les soldats donc, selon qu’il leur était enjoint, prirent Paul, et le menèrent de nuit à Antipatris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'Et le lendemain ils s’en retournèrent à la forteresse, ayant laissé Paul sous la conduite des gens de cheval;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Qui étant arrivés à Césarée, rendirent la lettre au Gouverneur, et lui présentèrent aussi Paul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Et quand le Gouverneur eut lu la lettre, et qu’il eut demandé à Paul de quelle Province il était, ayant entendu qu’il était de Cilicie:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'Je t’entendrai, lui dit-il, plus amplement quand tes accusateurs seront aussi venus. Et il commanda qu’il fût gardé au palais d’Hérode.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Or cinq jours après Ananias le souverain Sacrificateur descendit avec les Anciens, et un certain orateur, nommé Tertulle, qui comparurent devant le Gouverneur contre Paul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Et Paul étant appelé, Tertulle commença à l’accuser, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'Très-excellent Félix, nous connaissons en toutes choses et avec toute sorte de remercîment, que nous avons obtenu une grande tranquillité par ton moyen, et par les bons règlements que tu as faits pour ce peuple, selon ta prudence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Mais afin de ne t’arrêter pas longtemps, je te prie de nous entendre, selon ton équité, dans ce que nous allons te dire en peu de paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Nous avons trouvé que c’est ici un homme fort dangereux, qui excite des séditions parmi tous les Juifs dans tout le monde, et qui est le chef de la secte des Nazariens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'Il a même attenté de profaner le Temple; et nous l’avons saisi, et l’avons voulu juger selon notre Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Mais le Tribun Lysias étant survenu, il nous l’a ôté d’entre les mains avec une grande violence,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'Commandant que ses accusateurs vinssent vers toi; et tu pourras toi-même savoir de lui, en l’interrogeant, toutes ces choses desquelles nous l’accusons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Les Juifs acquiescèrent à cela et dirent que les choses étaient ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Et après que le Gouverneur eut fait signe à Paul de parler, il répondit: Sachant qu’il y a déjà plusieurs années que tu es le Juge de cette nation, je réponds pour moi avec plus de courage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Puisque tu peux connaître qu’il n’y a pas plus de douze jours que je suis monté à Jérusalem pour adorer Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'Mais ils ne m’ont point trouvé dans le Temple disputant avec personne, ni faisant un amas de peuple, soit dans les Synagogues, soit dans la ville.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Et ils ne sauraient soutenir les choses dont ils m’accusent présentement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Or je te confesse bien ce point, que selon la voie qu’ils appellent secte, je sers ainsi le Dieu de mes pères, croyant toutes les choses qui sont écrites dans la Loi et dans les Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'Et ayant espérance en Dieu, que la résurrection des morts, tant des justes que des injustes, laquelle ceux-ci attendent aussi eux- mêmes, arrivera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'C’est pourquoi aussi je travaille d’avoir toujours la conscience pure devant Dieu, et devant les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Or après plusieurs années, je suis venu pour faire des aumônes et des oblations dans ma nation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'Et comme je m’occupais à cela, ils m’ont trouvé purifié dans le Temple, sans attroupement et sans tumulte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Et c’étaient de certains Juifs d’Asie,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Qui devaient comparaître devant toi, et m’accuser, s’ils avaient quelque chose contre moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'Ou que ceux-ci eux-mêmes disent, s’ils ont trouvé en moi quelque injustice, quand j’ai été présenté au Conseil;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Sinon cette seule parole que j’ai dite hautement devant eux: aujourd’hui je suis tiré en cause par vous, pour la résurrection des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Et Félix ayant ouï ces choses, le remit à une autre fois, en disant: après que j’aurai plus exactement connu ce que c’est de cette secte, quand le Tribun Lysias sera descendu, je connaîtrai entièrement de vos affaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Et il commanda à un centenier que Paul fût gardé, mais qu’il eût aussi quelque relâche, et qu’on n’empêchât aucun des siens de le servir, ou de venir vers lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Or quelques jours après, Félix vint avec Drusille sa femme, qui était Juive, et il envoya quérir Paul, et l’ouït parler de la foi qui est en Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Et comme il parlait de la justice, et de la tempérance, et du jugement à venir, Félix tout effrayé répondit: pour le présent va- t’en, et quand j’aurai la commodité, je te rappellerai;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Espérant aussi en même temps que Paul lui donnerait quelque argent pour le délivrer, c’est pourquoi il l’envoyait quérir souvent, et s’entretenait avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 28, 'Or après deux ans accomplis Félix eut pour successeur Porcius Festus, qui voulant faire plaisir aux Juifs, laissa Paul en prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Festus donc étant arrivé dans la Province, monta trois jours après de Césarée à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Et le souverain Sacrificateur, et les premiers d’entre les Juifs, comparurent devant lui contre Paul, et ils priaient Festus;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'Et lui demandaient cette grâce contre Paul, qu’il le fît venir à Jérusalem; car ils avaient dressé des embûches pour le tuer par le chemin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Mais Festus leur répondit que Paul était bien gardé à Césarée, où il devait retourner lui-même bientôt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'C’est pourquoi, dit-il, que ceux d’entre vous qui le peuvent faire, y descendent avec moi; et s’il y a quelque crime en cet homme, qu’ils l’accusent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Et n’ayant pas demeuré parmi eux plus de dix jours, il descendit à Césarée; et le lendemain il s’assit au siège judicial, et il commanda que Paul fût amené.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Et comme il fut venu là, les Juifs qui étaient descendus de Jérusalem l’environnèrent, le chargeant de plusieurs grands crimes, lesquels ils ne pouvaient prouver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Paul répondant qu’il n’avait péché en rien, ni contre la Loi des Juifs, ni contre le Temple, ni contre César.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Mais Festus voulant faire plaisir aux Juifs, répondit à Paul, et dit: veux-tu monter à Jérusalem, et y être jugé de ces choses devant moi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Et Paul dit: je comparais devant le siège judicial de César, où il faut que je sois jugé: je n’ai fait aucun tort aux Juifs, comme tu le connais toi-même très bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Que si je leur ai fait tort, ou que j’aie fait quelque chose digne de mort, je ne refuse point de mourir; mais s’il n’est rien de ce dont ils m’accusent, personne ne me peut livrer à eux: j’en appelle à César.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Alors Festus ayant conféré avec le Conseil, lui répondit: en as-tu appelé à César? tu iras à César.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Or quelques jours après, le Roi Agrippa et Bérénice arrivèrent à Césarée pour saluer Festus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Et après avoir demeuré là plusieurs jours, Festus fit mention au Roi de l’affaire de Paul, disant: un certain homme a été laissé prisonnier par Félix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'Sur le sujet duquel, comme j’étais à Jérusalem, les principaux Sacrificateurs et les Anciens des Juifs sont comparus, sollicitant sa condamnation;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Mais je leur ai répondu que ce n’est point l’usage des Romains de livrer quelqu’un à la mort, avant que celui qui est accusé ait ses accusateurs présents, et qu’il ait lieu de se défendre du crime.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Quand donc ils furent venus ici, sans que j’usasse d’aucun délai, le jour suivant étant assis au siège judicial, je commandai que cet homme fût amené;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Et ses accusateurs étant là présents, ils n’alléguèrent aucun des crimes dont je pensais qu’ils l’accuseraient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Mais ils avaient quelques disputes contre lui touchant leurs superstitions, et touchant un certain Jésus mort, que Paul affirmait être vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Or comme j’étais fort en peine pour savoir ce que c’était, je demandai à cet homme s’il voulait aller à Jérusalem, et y être jugé de ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Mais parce qu’il en appela, demandant d’être réservé à la connaissance d’Auguste, je commandai qu’il fût gardé jusqu’à ce que je l’envoyasse à César.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Alors Agrippa dit à Festus: je voudrais bien aussi entendre cet homme. Demain, dit-il, tu l’entendras.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Le lendemain donc Agrippa et Bérénice étant venus avec une grande pompe, et étant entrés dans l’Auditoire avec les Tribuns et les principaux de la ville, Paul fut amené par le commandement de Festus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Et Festus dit: Roi Agrippa, et vous tous qui êtes ici avec nous, vous voyez cet homme contre lequel toute la multitude des Juifs m’est venue solliciter, tant à Jérusalem qu’ici, criant qu’il ne le fallait plus laisser vivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Mais moi, ayant trouvé qu’il n’avait rien fait qui fût digne de mort, et lui-même en ayant appelé à Auguste, j’ai résolu de le lui envoyer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Mais parce que je n’ai rien de certain à en écrire à l’Empereur, je vous l’ai présenté, et principalement à toi, Roi Agrippa, afin qu’après en avoir fait l’examen, j’aie de quoi écrire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Car il me semble qu’il n’est pas raisonnable d’envoyer un prisonnier, sans marquer les faits dont on l’accuse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Et Agrippa dit à Paul: il t’est permis de parler pour toi. Alors Paul ayant étendu la main, parla ainsi pour sa défense.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'Roi Agrippa! je m’estime heureux de ce que je dois répondre aujourd’hui devant toi, de toutes les choses dont je suis accusé par les Juifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'Et surtout parce que je sais que tu as une entière connaissance de toutes les coutumes et questions qui sont entre les Juifs: c’est pourquoi je te prie de m’écouter avec patience.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Pour ce qui est donc de la vie que j’ai menée dès ma jeunesse, telle qu’elle a été du commencement parmi ma nation à Jérusalem, tous les Juifs savent ce qui en est.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Car ils savent depuis longtemps, s’ils en veulent rendre témoignage, que dès mes ancêtres j’ai vécu Pharisien, selon la secte la plus exacte de notre Religion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Et maintenant je comparais en jugement pour l’espérance de la promesse que Dieu a faite à nos pères;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'A laquelle nos douze Tribus, qui servent Dieu continuellement nuit et jour, espèrent de parvenir; et c’est pour cette espérance, ô Roi Agrippa! que je suis accusé par les Juifs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Quoi, tenez-vous pour une chose incroyable que Dieu ressuscite les morts?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Il est vrai que pour moi, j’ai cru qu’il fallait que je fisse de grands efforts contre le Nom de Jésus le Nazarien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'Ce que j’ai aussi exécuté dans Jérusalem, car j’ai fait prisonniers plusieurs des Saints, après en avoir reçu le pouvoir des principaux Sacrificateurs, et quand on les faisait mourir j’y donnais ma voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'Et souvent par toutes les Synagogues en les punissant, je les contraignais de blasphémer, et étant transporté de fureur contre eux, je les persécutais jusque dans les villes étrangères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Et étant occupé à cela, comme j’allais aussi à Damas avec pouvoir et commission des principaux Sacrificateurs,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'Je vis, ô Roi! par le chemin en plein midi, une lumière du ciel, plus grande que la splendeur du soleil, laquelle resplendit autour de moi, et de ceux qui étaient en chemin avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Et étant tous tombés à terre, j’entendis une voix qui me parlait, et qui disait en Langue Hébraïque: Saul, Saul, pourquoi me persécutes-tu? il t’est dur de regimber contre les aiguillons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Alors je dis: qui es-tu, Seigneur? et il répondit: Je suis Jésus que tu persécutes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Mais lève-toi, et te tiens sur tes pieds: car ce que je te suis apparu, c’est pour t’établir ministre et témoin, tant des choses que tu as vues, que de celles pour lesquelles je t’apparaîtrai;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'En te délivrant du peuple, et des Gentils, vers lesquels je t’envoie maintenant,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'Pour ouvrir leurs yeux afin qu’ils soient convertis des ténèbres à la lumière, et de la puissance de satan à Dieu; et qu’ils reçoivent la rémission de leurs péchés, et leur part avec ceux qui sont sanctifiés par la foi qu’ils ont en moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Ainsi, ô Roi Agrippa! je n’ai point été rebelle à la vision céleste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'Mais j’ai annoncé premièrement à ceux qui étaient à Damas, et puis à Jérusalem, et par tout le pays de Judée, et aux Gentils, qu’ils se repentissent, et se convertissent à Dieu, en faisant des oeuvres convenables à la repentance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'C’est pour cela que les Juifs m’ayant pris dans le Temple ont tâché de me tuer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Mais ayant été secouru par l’aide de Dieu, je suis vivant jusqu’à ce jour, rendant témoignage aux petits et aux grands, et ne disant rien que ce que les Prophètes et Moïse ont prédit devoir arriver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'Savoir, qu’il fallait que le Christ souffrît, et qu’il fût le premier des ressuscités pour porter la lumière au peuple et aux Gentils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Et comme il parlait ainsi pour sa défense, Festus dit à haute voix: tu es hors du sens, Paul! ton grand savoir dans les lettres te met hors du sens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Et Paul dit: je ne suis point hors du sens, très-excellent Festus; mais je dis des paroles de vérité et de sens rassis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Car le Roi a la connaissance de ces choses; et je parle hardiment devant lui, parce que j’estime qu’il n’ignore rien de ces choses: car ceci n’a point été fait en secret.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Ô Roi Agrippa! crois-tu aux Prophètes? je sais que tu y crois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Et Agrippa répondit à Paul: tu me persuades à peu près d’être Chrétien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Et Paul lui dit: je souhaiterais devant Dieu que non-seulement toi, mais aussi tous ceux qui m’écoutent aujourd’hui, devinssent non seulement à peu près, mais parfaitement, tels que je suis, hormis ces liens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Paul ayant dit ces choses, le Roi se leva, avec le Gouverneur et Bérénice, et ceux qui étaient assis avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'Et quand ils se furent retirés à part, ils conférèrent entre eux, et ils dirent: cet homme n’a rien commis qui soit digne de mort, ou de prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Et Agrippa dit à Festus: cet homme pouvait être relâché s’il n’avait point appelé à César.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Or après qu’il eut été résolu que nous naviguerions en Italie, ils remirent Paul avec quelques autres prisonniers à un nommé Jule, centenier d’une cohorte de la Légion appelée Auguste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Et étant montés dans un navire d’Adramite, nous partîmes pour tirer vers les quartiers d’Asie, et Aristarque Macédonien de la ville de Thessalonique, était avec nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Le jour suivant nous arrivâmes à Sidon; et Jules traitant humainement Paul, lui permit d’aller vers ses amis, afin qu’ils eussent soin de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Puis étant partis de là, nous tînmes notre route au-dessous de Cypre, parce que les vents étaient contraires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'Et après avoir passé la mer qui est vis-à-vis de la Cilicie et de la Pamphylie, nous vînmes à Myra, ville de Lycie,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Où le centenier trouva un navire d’Alexandrie qui allait en Italie, dans lequel il nous fit monter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Et comme nous naviguions pesamment durant plusieurs jours, en sorte qu’à grande peine pûmes-nous arriver jusques à la vue de Guide, parce que le vent ne nous poussait point, nous passâmes au-dessous de Crète, vers Salmone.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'Et la côtoyant avec peine, nous vînmes en un lieu qui est appelé Beaux-ports, près duquel était la ville de Lasée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Et parce qu’il s’était écoulé beaucoup de temps, et que la navigation était déjà périlleuse, vu que même le jeûne était déjà passé, Paul les exhortait,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'En leur disant: hommes, je vois que la navigation sera périlleuse et que nous serons exposés non seulement à la perte de la charge du vaisseau, mais même de nos propres vies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Mais le centenier croyait plus le Pilote, et le maître du navire, que ce que Paul disait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Et parce que le port n’était pas propre pour y passer l’hiver, la plupart furent d’avis de partir de là, pour tâcher d’aborder à Phénix, qui est un port de Crète, situé contre le vent d’Afrique et du couchant septentrional, afin d’y passer l’hiver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Et le vent du Midi commençant à souffler doucement, ils crurent venir à bout de leur dessein, et étant partis, ils côtoyèrent Crète de plus près.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Mais un peu après un vent orageux du nord-est, qu’on appelle Euroclydon, se leva du côté de l’île.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Et le navire étant emporté par le vent, de telle sorte qu’il ne pouvait point résister, nous fûmes emportés, ayant abandonné le navire au vent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Et ayant passé au-dessous d’une petite île, appelée Clauda, à grande peine pûmes-nous être maîtres de l’esquif;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Mais l’ayant tirée à nous, les matelots cherchaient tous les remèdes possibles, en liant le navire par-dessous; et comme ils craignaient de tomber sur des bancs de sable, ils abattirent les voiles, et ils étaient portés de cette manière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Or parce que nous étions agités d’une grande tempête, le jour suivant ils jetèrent les marchandises dans la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'Puis le troisième jour nous jetâmes de nos propres mains les agrès du navire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Et comme il ne nous parut durant plusieurs jours ni soleil ni étoiles, et qu’une grande tempête nous agitait violemment, toute espérance de nous pouvoir sauver à l’avenir nous fut ôtée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Mais après qu’ils eurent été longtemps sans manger, Paul se tenant alors debout au milieu d’eux, leur dit: ô hommes! certes il fallait me croire, et ne point partir de Crète, afin d’éviter cette tempête et cette perte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Mais maintenant je vous exhorte d’avoir bon courage: car nul de vous ne perdra la vie, et le navire seul périra.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Car en cette propre nuit un Ange du Dieu à qui je suis, et lequel je sers, s’est présenté à moi,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'Me disant: Paul, ne crains point, il faut que tu sois présenté à César; et voici, Dieu t’a donné tous ceux qui naviguent avec toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'C’est pourquoi, ô hommes! ayez bon courage, car j’ai cette confiance en Dieu que la chose arrivera comme elle m’a été dite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Mais il faut que nous soyons jetés contre quelque île.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Quand donc la quatorzième nuit fut venue, comme nous étions portés çà et là sur la mer Adriatique, les matelots eurent opinion environ sur le minuit qu’ils approchaient de quelque contrée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Et ayant jeté la sonde, ils trouvèrent vingt brasses; puis étant passés un peu plus loin, et ayant encore jeté la sonde, ils trouvèrent quinze brasses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Mais craignant de donner contre quelque écueil, ils jetèrent quatre ancres de la poupe, désirant que le jour vînt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Et comme les matelots cherchaient à s’enfuir du navire, ayant descendu l’esquif en mer, sous prétexte d’aller porter loin les ancres du côté de la proue,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Paul dit au centenier et aux soldats: si ceux-ci ne demeurent dans le navire, vous ne pouvez point vous sauver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Alors les soldats coupèrent les cordes de l’esquif, et le laissèrent tomber.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Et jusqu’à ce que le jour vînt, Paul les exhorta tous de prendre quelque nourriture, en leur disant: c’est aujourd’hui le quatorzième jour qu’en attendant, vous êtes demeurés à jeun, et n’avez rien pris;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Je vous exhorte donc à prendre quelque nourriture, vu que cela est nécessaire pour votre conservation: car il ne tombera pas un cheveu de la tête d’aucun de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Et quand il eut dit ces choses, il prit du pain, et rendit grâces à Dieu en présence de tous, et l’ayant rompu il commença a manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Alors ayant tous pris courage, ils commencèrent aussi à manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Or nous étions en tout dans le navire deux cent soixante-seize personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Et quand ils eurent mangé jusqu’à être rassasiés, ils allégèrent le navire, en jetant le blé dans la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Et le jour étant venu ils ne reconnaissaient point le pays; mais ils aperçurent un golfe ayant rivage, et ils résolurent d’y faire échouer le navire, s’il leur était possible.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'C’est pourquoi ayant retiré les ancres, ils abandonnèrent le navire à la mer, lâchant en même temps les attaches des gouvernails; et ayant tendu la voile de l’artimon, ils tirèrent vers le rivage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Mais étant tombés en un lieu où deux courants se rencontraient, ils y heurtèrent le navire, et la proue s’y étant enfoncée demeurait ferme, mais la poupe se rompait par la violence des vagues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Alors le conseil des soldats fut de tuer les prisonniers, de peur que quelqu’un s’étant sauvé à la nage, ne s’enfuît.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Mais le centenier voulant sauver Paul, les empêcha d’exécuter ce conseil, et il commanda que ceux qui pourraient nager se jetassent dehors les premiers, et se sauvassent à terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'Et le reste, les uns sur des planches, et les autres sur quelques pièces du navire; et ainsi il arriva que tous se sauvèrent à terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'S’étant donc sauvés, ils reconnurent alors que l’île s’appelait Malte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Et les Barbares usèrent d’une singulière humanité envers nous, car ils allumèrent un grand feu, et nous reçurent tous, à cause de la pluie qui nous pressait, et à cause du froid.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Et Paul ayant ramassé quelque quantité de sarments, comme il les eut mis au feu, une vipère en sortit à cause de la chaleur, et lui saisit la main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Et quand les Barbares virent cette bête pendant à sa main, ils se dirent l’un à l’autre: certainement cet homme est un meurtrier; puisqu’après être échappé de la mer, la vengeance ne permet pas qu’il vive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Mais Paul ayant secoué la bête dans le feu, il n’en reçut aucun mal;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Au lieu qu’ils s’attendaient qu’il dût enfler, ou tomber subitement mort. Mais quand ils eurent longtemps attendu, et qu’ils eurent vu qu’il ne lui en arrivait aucn mal, ils changèrent de langage, et dirent que c’était un Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Or en cet endroit-là étaient les possesions du principal de l’île, nommé Publius, qui nous reçut et nous logea durant trois jours avec beaucoup de bonté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Et il arriva que le père de Publius était au lit malade de la fièvre et de la dyssenterie, et Paul l’étant allé voir, il fit la prière, lui imposa les mains, et le guérit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Ce qui étant arrivé, tous les autres malades de l’île vinrent à lui, et ils furent guéris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Lesquels aussi nous firent de grands honneurs, et à notre départ nous fournirent ce qui nous était nécessaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Trois mois après nous partîmes sur un navire d’Alexandrie qui avait hiverné dans l’île, et qui avait pour enseigne Castor et Pollux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Et étant arrivés à Syracuse, nous y demeurâmes trois jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'De là en côtoyant, nous arrivâmes à Rhège; et un jour après, le vent du Midi s’étant levé, nous vînmes le deuxième jour à Pouzzoles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Où ayant trouvé des frères, nous fûmes priés de demeurer avec eux sept jours; et ensuite nous arrivâmes à Rome.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Et quand les frères qui y étaient eurent reçu de nos nouvelles, ils vinrent au-devant de nous jusques au Marché d’Appius, et aux Trois-boutiques; et Paul les voyant, rendit grâces à Dieu, et prit courage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Et lorsque nous fûmes arrivés à Rome, le centenier livra les prisonniers au Préfet du Prétoire; mais quant à Paul, il lui fut permis de demeurer à part avec un soldat qui le gardait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Or il arriva trois jours après, que Paul convoqua les principaux des Juifs; et quand ils furent venus, il leur dit: hommes frères! quoique je n’aie rien commis contre le peuple ni contre les coutumes des Pères, toutefois j’ai été arrêté prisonnier à Jérusalem, et livré entre les mains des Romains,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Qui après m’avoir examiné me voulaient relâcher, parce qu’il n’y avait en moi aucun crime digne de mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Mais les Juifs s’y opposant, j’ai été contraint d’en appeler à César; sans que j’aie pourtant dessein d’accuser ma nation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'C’est donc là le sujet pour lequel je vous ai appelés, afin de vous voir et de vous parler; car c’est pour l’espérance d’Israël que je suis chargé de cette chaîne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Mais ils lui répondirent: nous n’avons point reçu de Lettres de Judée qui parlent de toi; ni aucun des frères n’est venu qui ait rapporté ou dit quelque mal de toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Cependant nous entendrons volontiers de toi quel est ton sentiment; car quant à cette secte, il nous est connu qu’on la contredit partout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Et après lui avoir assigné un jour, plusieurs vinrent auprès de lui dans son logis, auxquels il expliquait par plusieurs témoignages le Royaume de Dieu, et depuis le matin jusqu’au soir il les portait à croire ce qui concerne Jésus, tant par la Loi de Moïse que par les Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Et les uns furent persuadés par les choses qu’il disait; et les autres n’y croyaient point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'C’est pourquoi n’étant pas d’accord entre eux, ils se retirèrent, après que Paul leur eut dit cette parole: le Saint-Esprit a bien parlé à nos Pères par Esaïe le Prophète,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'En disant: va vers ce peuple, et lui dis: vous écouterez de vos oreilles, et vous n’entendrez point; et en regardant vous verrez, et vous n’apercevrez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Car le coeur de ce peuple est engraissé; et ils ont ouï dur de leurs oreilles, et ont fermé leurs yeux; de peur qu’ils ne voient des yeux, qu’ils n’entendent des oreilles, qu’ils ne comprennent du coeur, qu’ils ne se convertissent, et que je ne les guérisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Sachez donc que ce salut de Dieu est envoyé aux Gentils, et ils l’entendront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'Quand il eut dit ces choses, les Juifs se retirèrent d’avec lui, y ayant une grande contestation entre eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Mais Paul demeura deux ans entiers dans une maison qu’il avait louée pour lui, où il recevait tous ceux qui le venaient voir,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'Prêchant le Royaume de Dieu, et enseignant les choses qui regardent le Seigneur Jésus-Christ avec toute liberté de parler, et sans aucun empêchement. ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paul serviteur de Jésus-Christ, appelé à être Apôtre, mis à part pour annoncer l’Evangile de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'Lequel il avait auparavant promis par ses Prophètes dans les saintes Ecritures;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'Touchant son Fils, qui est né de la famille de David, selon la chair;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'Et qui a été pleinement déclaré Fils de Dieu en puissance, selon l’esprit de sanctification par sa résurrection d’entre les morts, c’est-à-dire, notre Seigneur Jésus-Christ,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Par lequel nous avons reçu la grâce et la charge d’Apôtre, afin de porter tous les Gentils à croire en son Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Entre lesquels aussi vous êtes, vous qui êtes appelés par Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'A vous tous qui êtes à Rome, bien-aimés de Dieu, appelés à être saints; que la grâce et la paix vous soient données par Dieu notre Père, et par le Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Premièrement je rends grâces touchant vous tous à mon Dieu par Jésus- Christ, de ce que votre foi est renommée par tout le monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Car Dieu, que je sers en mon esprit dans l’Evangile de son Fils, m’est témoin que je fais sans cesse mention de vous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'Demandant continuellement dans mes prières que je puisse enfin trouver par la volonté de Dieu quelque moyen favorable pour aller vers vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Car je désire extrêmement de vous voir, pour vous faire part de quelque don spirituel, afin que vous soyez affermis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'C’est-à-dire, afin qu’étant parmi vous, je sois consolé avec vous par la foi qui nous est commune.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Or mes frères, je ne veux point que vous ignoriez que je me suis souvent proposé d’aller vers vous, afin de recueillir quelque fruit aussi bien parmi vous, que parmi les autres nations; mais j’en ai été empêché jusqu’à présent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Je suis débiteur tant aux Grecs qu’aux Barbares, tant aux sages qu’aux ignorants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Ainsi, en tant qu’en moi est, je suis prêt d’annoncer aussi l’Evangile à vous qui êtes à Rome.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Car je n’ai point honte de l’Evangile de Christ, vu qu’il est la puissance de Dieu en salut à tout croyant: au Juif premièrement, puis aussi au Grec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Car la justice de Dieu se révèle en lui pleinement de foi en foi; selon qu’il est écrit: or le juste vivra de foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Car la colère de Dieu se révèle pleinement du Ciel sur toute impiété et injustice des hommes qui retiennent injustement la vérité captive.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'Parce que ce qui se peut connaître de Dieu est manifesté en eux; car Dieu le leur a manifesté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Car les choses invisibles de Dieu, savoir tant sa puissance éternelle que sa Divinité, se voient comme à l’oeil par la création du monde, étant considérées dans ses ouvrages, de sorte qu’ils sont inexcusables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Parce qu’ayant connu Dieu, ils ne l’ont point glorifié comme Dieu, et ils ne lui ont point rendu grâces, mais ils sont devenus vains en leurs discours, et leur coeur destitué d’intelligence, a été rempli de ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Se disant être sages ils sont devenus fous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'Et ils ont changé la gloire de Dieu incorruptible en la ressemblance de l’image de l’homme corruptible, et des oiseaux, et des bêtes à quatre pieds, et des reptiles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'C’est pourquoi aussi Dieu les a livrés aux convoitises de leurs propres coeurs, de sorte qu’ils se sont abandonnés à l’impureté déshonorant entre eux- mêmes leurs propres corps:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'Eux qui ont changé la vérité de Dieu en fausseté, et qui ont adoré et servi la créature, en abandonnant le Créateur, qui est béni éternellement: Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'C’est pourquoi Dieu les a livrés à leurs affections infâmes; car même les femmes parmi eux ont changé l’usage naturel en celui qui est contre la nature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'Et les hommes tout de même laissant l’usage naturel de la femme, se sont embrasés en leur convoitise l’un envers l’autre, commettant homme avec homme des choses infâmes, et recevant en eux-mêmes la récompense de leur erreur, telle qu’il fallait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Car comme ils ne se sont pas souciés de connaître Dieu, aussi Dieu les a livrés à un esprit dépourvu de tout jugement, pour commettre des choses qui ne sont nullement convenables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'Etant remplis de toute injustice, d’impureté, de méchanceté, d’avarice, de malignité, pleins d’envie, de meurtre, de querelle, de fraude, de mauvaises moeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'Rapporteurs, médisants, haïssant Dieu, outrageux, orgueilleux, vains, inventeurs de maux, rebelles à pères et à mères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'Sans entendement, ne tenant point ce qu’ils ont promis, sans affection naturelle, gens qui jamais ne se rappaisent, sans miséricorde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Et qui, bien qu’ils aient connu le droit de Dieu, savoir, que ceux qui commettent de telles choses sont dignes de mort, ne les commettent pas seulement, mais encore ils favorisent ceux qui les commettent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'C’est pourquoi, ô homme! qui que tu sois qui juges les autres, tu es sans excuse; car en ce que tu juges les autres, tu te condamnes toi-même, puisque toi qui juges, commets les mêmes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Or nous savons que le jugement de Dieu est selon la vérité sur ceux qui commettent de telles choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Et penses-tu, ô homme! qui juges ceux qui commettent de telles choses, et qui les commets, que tu doives échapper au jugement de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Ou méprises-tu les richesses de sa douceur, et de sa patience, et de sa longue attente; ne connaissant pas que la bonté de Dieu te convie à la repentance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Mais par ta dureté, et par ton coeur qui est sans repentance, tu t’amasses la colère pour le jour de la colère, et de la manifestation du juste jugement de Dieu:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'Qui rendra à chacun selon ses oeuvres;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'Savoir la vie éternelle à ceux qui persévérant à bien faire, cherchent la gloire, l’honneur et l’immortalité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'Mais il y aura de l’indignation et de la colère contre ceux qui sont contentieux, et qui se rebellent contre la vérité, et obéissent à l’injustice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Il y aura tribulation et angoisse sur toute âme d’homme qui fait le mal, du Juif premièrement, puis aussi du Grec;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Mais gloire, honneur, et paix à chacun qui fait le bien; au Juif premièrement, puis aussi au Grec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Parce que Dieu n’a point d’égard à l’apparence des personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Car tous ceux qui auront péché sans la Loi, périront aussi sans la Loi; et tous ceux qui auront péché en la Loi, seront jugés par la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, '(Parce que ce ne sont pas ceux qui écoutent la Loi, qui sont justes devant Dieu; mais ce sont ceux qui observent la Loi, qui seront justifiés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Or quand les Gentils, qui n’ont point la Loi, font naturellement les choses qui sont de la Loi, n’ayant point la Loi, ils sont Loi à eux-mêmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Et ils montrent par là que l’oeuvre de la Loi est écrite dans leurs coeurs; leur conscience leur rendant témoignage, et leurs pensées s’accusant entre elles, ou aussi s’excusant.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'Tous, dis-je, donc seront jugés au jour que Dieu jugera les secrets des hommes par Jésus-Christ, selon mon Evangile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Voici, tu portes le nom de Juif, tu te reposes entièrement sur la Loi, et tu te glorifies en Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'Tu connais sa volonté, et tu sais discerner ce qui est contraire, étant instruit par la Loi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'Et tu te crois être le conducteur des aveugles, la lumière de ceux qui sont dans les ténèbres;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'Le docteur des ignorants, le maître des idiots, ayant le modèle de la connaissance et de la vérité dans la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'Toi donc qui enseignes les autres, ne t’enseignes-tu point toi-même? toi qui prêches qu’on ne doit point dérober, tu dérobes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Toi qui dis qu’on ne doit point commettre adultère, tu commets adultère? toi qui as en abomination les idoles, tu commets des sacrilèges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Toi qui te glorifies en la Loi, tu déshonores Dieu par la transgression de la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Car le nom de Dieu est blasphémé à cause de vous parmi les Gentils comme il est écrit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Or il est vrai que la Circoncision est profitable, si tu gardes la Loi; mais si tu es transgresseur de la Loi, ta Circoncision devient prépuce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Mais si celui qui a le prépuce garde les ordonnances de la Loi, son prépuce ne lui sera-t-il point réputé pour Circoncision?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'Et si celui qui a naturellement le prépuce, accomplit la Loi, ne te jugera- t-il pas, toi qui dans la lettre et dans la Circoncision es transgresseur de la Loi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Car celui-là n’est point Juif, qui ne l’est qu’au-dehors, et celle-là n’est point la véritable Circoncision, qui est faite par dehors en la chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'Mais celui-là est Juif, qui l’est au-dedans; et la véritable Circoncision est celle qui est du coeur en esprit, et non pas dans la lettre; et la louange de ce Juif n’est point des hommes, mais de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Quel est donc l’avantage du Juif, ou quel est le profit de la Circoncision?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Il est grand en toute manière; surtout en ce que les oracles de Dieu leur ont été confiés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Car qu’est-ce, si quelques-uns n’ont point cru? leur incrédulité anéantira- t-elle la fidélité de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Non sans doute! mais que Dieu soit véritable, et tout homme menteur; selon ce qui est écrit: afin que tu sois trouvé juste en tes paroles, et que tu aies gain de cause quand tu es jugé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Or si notre injustice recommande la justice de Dieu, que dirons-nous? Dieu est-il injuste quand il punit? (je parle en homme.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Non sans doute! autrement, comment Dieu jugera-t-il le monde?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Et si la vérité de Dieu est par mon mensonge plus abondante pour sa gloire, pourquoi suis-je encore condamné comme pécheur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Mais plutôt, selon que nous sommes blâmés, et que quelques-uns disent que nous disons: pourquoi ne faisons-nous du mal, afin qu’il en arrive du bien? desquels la condamnation est juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Quoi donc! sommes-nous plus excellents? Nullement. Car nous avons ci-devant convaincu que tous, tant Juifs que Grecs, sont assujettis au péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'Selon qu’il est écrit: il n’y a point de juste, non pas même un seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Il n’y a personne qui ait de l’intelligence, il n’y a personne qui recherche Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Ils se sont tous égarés, ils se sont tous ensemble rendus inutiles: il n’y en a aucun qui fasse le bien, non pas même un seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'C’est un sépulcre ouvert que leur gosier; ils ont frauduleusement usé de leurs langues, il y a du venin d’aspic sous leurs lèvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Leur bouche est pleine de malédiction et d’amertume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Leurs pieds sont légers pour répandre le sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'La destruction et la misère sont dans leurs voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'Et ils n’ont point connu la voie de la paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'La crainte de Dieu n’est point devant leurs yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Or nous savons que tout ce que la Loi dit, elle le dit à ceux qui sont sous la Loi, afin que toute bouche soit fermée, et que tout le monde soit coupable devant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'C’est pourquoi nulle chair ne sera justifiée devant lui par les oeuvres de la Loi: car par la Loi est donnée la connaissance du péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Mais maintenant la justice de Dieu est manifestée sans la Loi, lui étant rendu témoignage par la Loi, et par les Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'La justice, dis-je, de Dieu par la foi en Jésus-Christ, s’étend à tous et sur tous ceux qui croient; car il n’y a nulle différence, vu que tous ont péché, et qu’ils sont entièrement privés de la gloire de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Etant justifiés gratuitement par sa grâce, par la rédemption qui est en Jésus-Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'Lequel Dieu a établi de tout temps pour être une victime de propitiation par la foi, en son sang, afin de montrer sa justice, par la rémission des péchés précédents, selon la patience de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Pour montrer, dis-je, sa justice dans le temps présent, afin qu’il soit trouvé juste, et justifiant celui qui est de la foi de Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'Où est donc le sujet de se glorifier? Il est exclu. Par quelle Loi? est- ce par la Loi des oeuvres? Non, mais par la Loi de la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Nous concluons donc que l’homme est justifié par la foi, sans les oeuvres de la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Dieu est-il seulement le Dieu des Juifs? ne l’est-il pas aussi des Gentils? certes il l’est aussi des Gentils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Car il y a un seul Dieu qui justifiera par la foi la Circoncision, et le Prépuce aussi par la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'Anéantissons-nous donc la Loi par la foi? Non sans doute! mais au contraire, nous affermissons la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Que dirons-nous donc qu’Abraham notre père a trouvé selon la chair?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Certes, si Abraham a été justifié par les oeuvres, il a de quoi se glorifier, mais non pas envers Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Car que dit l’Ecriture? qu’Abraham a cru à Dieu, et que cela lui a été imputé à justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Or à celui qui fait les oeuvres, le salaire ne lui est pas imputé comme une grâce, mais comme une chose due.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Mais à celui qui ne fait pas les oeuvres, mais qui croit en celui qui justifie le méchant, sa foi lui est imputée à justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Comme aussi David exprime la béatitude de l’homme à qui Dieu impute la justice sans les oeuvres, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Bienheureux sont ceux à qui les iniquités sont pardonnées, et dont les péchés sont couverts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Bienheureux est l’homme à qui le Seigneur n’aura point imputé son péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Cette déclaration donc de la béatitude, est-elle seulement pour la Circoncision, ou aussi pour le Prépuce? car nous disons que la foi a été imputée à Abraham à justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Comment donc lui a-t-elle été imputée? a-ce été lorsqu’il était déjà circoncis, ou lorsqu’il était encore dans le prépuce? ce n’a point été dans la Circoncision, mais dans le prépuce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'Puis il reçut le signe de la Circoncision pour un sceau de la justice de la foi, laquelle il avait reçue étant dans le prépuce, afin qu’il fût le père de tous ceux qui croient étant dans le prépuce, et que la justice leur fût aussi imputée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'Et qu’il fût aussi le père de la Circoncision, c’est-à-dire, de ceux qui ne sont pas seulement de la Circoncision, mais qui aussi suivent les traces de la foi de notre père Abraham, laquelle il a eue dans le prépuce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Car la promesse d’être héritier du monde, n’a pas été faite à Abraham, ou à sa semence, par la Loi, mais par la justice de la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Or si ceux qui sont de la Loi sont héritiers, la foi est anéantie, et la promesse est abolie:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Vu que la Loi produit la colère; car où il n’y a point de Loi, il n’y a point aussi de transgression.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'C’est donc par la foi, afin que ce soit par la grâce, et afin que la promesse soit assurée à toute la semence; non seulement à celle qui est de la Loi, mais aussi à celle qui est de la foi d’Abraham, qui est le père de nous tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, 'Selon qu’il est écrit: je t’ai établi père de plusieurs nations, devant Dieu, en qui il a cru; lequel fait vivre les morts, et qui appelle les choses qui ne sont point, comme si elles étaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Et Abraham ayant espéré contre espérance, crut qu’il deviendrait le père de plusieurs nations, selon ce qui lui avait été dit: ainsi sera ta postérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Et n’étant pas faible en la foi, il n’eut point égard à son corps qui était déjà amorti; vu qu’il avait environ cent ans, ni à l’âge de Sara qui était hors d’état d’avoir des enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'Et il ne forma point de doute sur la promesse de Dieu par défiance; mais il fut fortifié par la foi, donnant gloire à Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'Etant pleinement persuadé que celui qui lui avait fait la promesse, était puissant aussi pour l’accomplir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'C’est pourquoi cela lui a été imputé à justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Or que cela lui ait été imputé à justice, il n’a point été écrit seulement pour lui,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'Mais aussi pour nous, à qui aussi il sera imputé, à nous, dis-je, qui croyons en celui qui a ressuscité des morts Jésus notre Seigneur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'Lequel a été livré pour nos offenses, et qui est ressuscité pour notre justification.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Etant donc justifiés par la foi, nous avons la paix avec Dieu, par notre Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Par lequel aussi nous avons été amenés par la foi à cette grâce, dans laquelle nous nous tenons fermes; et nous nous glorifions en l’espérance de la gloire de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Et non seulement cela, mais nous nous glorifions même dans les afflictions: sachant que l’affliction produit la patience;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'Et la patience l’épreuve; et l’épreuve l’espérance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'Or l’espérance ne confond point, parce que l’amour de Dieu est répandu dans nos coeurs par le Saint-Esprit qui nous a été donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Car lorsque nous étions encore privés de toute force, Christ est mort en son temps pour nous, qui étions des impies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Or à grande peine arrive-t-il que quelqu’un meure pour un juste; mais encore il pourrait être que quelqu’un voudrait bien mourir pour un bienfaiteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Mais Dieu signale son amour envers nous en ce que lorsque nous n’étions que pécheurs, Christ est mort pour nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Beaucoup plutôt donc, étant maintenant justifiés par son sang, serons-nous sauvés de la colère par lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Car si lorsque nous étions ennemis, nous avons été réconciliés avec Dieu par la mort de son Fils, beaucoup plutôt étant déjà réconciliés, serons-nous sauvés par sa vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Et non seulement cela, mais nous nous glorifions même en Dieu par notre Seigneur Jésus-Christ; par lequel nous avons maintenant obtenu la réconciliation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'C’est pourquoi comme par un seul homme le péché est entré au monde, la mort y est aussi entrée par le péché; et ainsi la mort est parvenue sur tous les hommes, parce que tous ont péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'Car jusqu’à la Loi le péché était au monde; or le péché n’est point imputé quand il n’y a point de Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Mais la mort a régné depuis Adam jusqu’à Moïse, même sur ceux qui n’avaient point péché de la manière en laquelle Adam avait péché, qui est la figure de celui qui devait venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Mais il n’en est pas du don comme de l’offense; car si par l’offense d’un seul plusieurs sont morts, beaucoup plutôt la grâce de Dieu, et le don par la grâce, qui est d’un seul homme, savoir de Jésus-Christ, a abondé sur plusieurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Et il n’en est pas du don comme de ce qui est arrivé par un seul qui a péché; car la condamnation vient d’une seule faute; mais le don de la justification s’étend à plusieurs péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Car si par l’offense d’un seul la mort a régné par un seul, beaucoup plutôt ceux qui reçoivent l’abondance de la grâce, et du don de la justice, régneront en vie par un seul, qui est Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Comme donc par un seul péché les hommes sont assujettis à la condamnation, ainsi par une seule justice justifiante le don est venu sur tous les hommes en justification de vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Car comme par la désobéissance d’un seul homme plusieurs ont été rendus pécheurs, ainsi par l’obéissance d’un seul plusieurs seront rendus justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Or la Loi est intervenue afin que l’offense abondât; mais où le péché a abondé, la grâce y a abondé par-dessus;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'Afin que comme le péché a régné par la mort, ainsi la grâce régnât par la justice pour conduire à la vie éternelle, par Jésus-Christ notre Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Que dirons-nous donc? demeurerons-nous dans le péché, afin que la grâce abonde?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'A Dieu ne plaise! Car nous qui sommes morts au péché, comment y vivrons- nous encore?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Ne savez-vous pas que nous tous qui avons été baptisés en Jésus-Christ, avons été baptisés en sa mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Nous sommes donc ensevelis avec lui en sa mort par le Baptême; afin que comme Christ est ressuscité des morts par la gloire du Père, nous marchions aussi en nouveauté de vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Car si nous avons été faits une même plante avec lui par la conformité de sa mort, nous le serons aussi par la conformité de sa résurrection.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'Sachant ceci, que notre vieil homme a été crucifié avec lui, afin que le corps du péché soit détruit; afin que nous ne servions plus le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Car celui qui est mort, est quitte du péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Or si nous sommes morts avec Christ, nous croyons que nous vivrons aussi avec lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'Sachant que Christ étant ressuscité des morts ne meurt plus, et que la mort n’a plus d’empire sur lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Car ce qu’il est mort, il est mort une fois à cause du péché; mais ce qu’il est vivant, il est vivant à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Vous aussi tout de même faites votre compte que vous êtes morts au péché, mais vivants à Dieu en Jésus-Christ notre Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Que le péché ne règne donc point en votre corps mortel, pour lui obéir en ses convoitises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Et n’appliquez point vos membres pour être des instruments d’iniquité au péché; mais appliquez-vous à Dieu comme de morts étant faits vivants, et appliquez vos membres pour être des instruments de justice à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Car le péché n’aura point d’empire sur vous, parce que vous n’êtes point sous la Loi, mais sous la Grâce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Quoi donc? pécherons-nous parce que nous ne sommes point sous la Loi, mais sous la Grâce? A Dieu ne plaise!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Ne savez-vous pas bien qu’à quiconque vous vous rendez esclaves pour obéir, vous êtes esclaves de celui à qui vous obéissez, soit du péché qui conduit à la mort; soit de l’obéissance qui conduit à la justice?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Or grâces à Dieu de ce qu’ayant été les esclaves du péché, vous avez obéi du coeur à la forme expresse de la doctrine dans laquelle vous avez été élevés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Ayant donc été affranchis du péché, vous avez été asservis à la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, '(Je parle à la façon des hommes, à cause de l’infirmité de votre chair.) Comme donc vous avez appliqué vos membres pour servir à la souillure et à l’iniquité, pour commettre l’iniquité; ainsi appliquez maintenant vos membres pour servir à la justice en sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Car lorsque vous étiez esclaves du péché, vous étiez libres à l’égard de la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Quel fruit donc aviez-vous alors des choses dont maintenant vous avez honte? certes leur fin est la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Mais maintenant que vous êtes affranchis du péché, et asservis à Dieu, vous avez votre fruit dans la sanctification; et pour fin la vie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Car les gages du péché, c’est la mort; mais le don de Dieu, c’est la vie éternelle par Jésus-Christ notre Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Ne savez-vous pas, mes frères (car je parle à ceux qui entendent ce que c’est que la Loi) que la Loi exerce son pouvoir sur l’homme durant tout le temps qu’il est en vie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Car la femme qui est sous la puissance d’un mari, est liée à son mari par la Loi, tandis qu’il est en vie; mais si son mari meurt, elle est délivrée de la loi du mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Le mari donc étant vivant, si elle épouse un autre mari elle sera appelée adultère; mais son mari étant mort, elle est délivrée de la Loi; tellement qu’elle ne sera point adultère si elle épouse un autre mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Ainsi mes frères, vous êtes aussi morts à la Loi par le corps de Christ, pour être à un autre, savoir à celui qui est ressuscité des morts, afin que nous fructifions à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Car quand nous étions en la chair, les affections des péchés étant excitées par la Loi, avaient vigueur en nos membres, pour fructifier à la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Mais maintenant nous sommes délivrés de la Loi, la Loi par laquelle nous étions retenus étant morte; afin que nous servions Dieu en nouveauté d’esprit, et non point en vieillesse de Lettre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Que dirons-nous donc? La Loi est-elle péché? à Dieu ne plaise! au contraire je n’ai point connu le péché, sinon par la Loi: car je n’eusse pas connu la convoitise, si la Loi n’eût dit: tu ne convoiteras point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Mais le péché ayant pris occasion par le commandement, a produit en moi toute sorte de convoitise; parce que sans la Loi le péché est mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Car autrefois que j’étais sans la Loi, je vivais; mais quand le commandement est venu, le péché a commencé à revivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'Et moi je suis mort; et le commandement qui m’était ordonné pour être ma vie, a été trouvé me tourner à mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Car le péché prenant occasion du commandement, m’a séduit, et par lui m’a mis à mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'La Loi donc est sainte, et le commandement est saint, juste, et bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Ce qui est bon, m’est-il devenu mortel? nullement! mais le péché, afin qu’il parût péché, m’a causé la mort par le bien; afin que le péché fût rendu par le commandement excessivement péchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Car nous savons que la Loi est spirituelle; mais je suis charnel, vendu au péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Car je n’approuve point ce que je fais, puisque je ne fais point ce que je veux, mais je fais ce que je hais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Or si ce que je fais je ne le veux point, je reconnais par cela même que la Loi est bonne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Maintenant donc ce n’est plus moi qui fais cela; mais c’est le péché qui habite en moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Car je sais qu’en moi, c’est-à-dire, en ma chair, il n’habite point de bien; vu que le vouloir est bien attaché à moi, mais je ne trouve pas le moyen d’accomplir le bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Car je ne fais pas le bien que je veux, mais je fais le mal que je ne veux point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Or si je fais ce que je ne veux point, ce n’est plus moi qui le fais, mais c’est le péché qui habite en moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Je trouve donc cette Loi au-dedans de moi, que quand je veux faire le bien, le mal est attaché à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Car je prends bien plaisir à la loi de Dieu quant à l’homme intérieur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'Mais je vois dans mes membres une autre loi, qui combat contre la loi de mon entendement, et qui me rend prisonnier à la loi du péché, qui est dans mes membres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Ha! misérable que je suis! qui me délivrera du corps de cette mort?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Je rends grâces à Dieu par Jésus-Christ notre Seigneur. Je sers donc moi- même de l’entendement à la Loi de Dieu, mais de la chair, à la loi du péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Il n’y a donc maintenant aucune condamnation pour ceux qui sont en Jésus- Christ, lesquels ne marchent point selon la chair, mais selon l’Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Parce que la Loi de l’Esprit de vie qui est en Jésus-Christ, m’a affranchi de la Loi du péché et de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Parce que ce qui était impossible à la Loi, à cause qu’elle était faible en la chair, Dieu ayant envoyé son propre Fils en forme de chair de péché, et pour le péché, a condamné le péché en la chair;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'Afin que la justice de la Loi fût accomplie en nous, qui ne marchons point selon la chair, mais selon l’Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Car ceux qui sont selon la chair, sont affectionnés aux choses de la chair; mais ceux qui sont selon l’Esprit, sont affectionnés aux choses de l’Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Or l’affection de la chair est la mort; mais l’affection de l’Esprit est la vie et la paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'Parce que l’affection de la chair est inimitié contre Dieu; car elle ne se rend point sujette à la Loi de Dieu; et aussi ne le peut-elle point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'C’est pourquoi ceux qui sont en la chair ne peuvent point plaire à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Or vous n’êtes point en la chair, mais dans l’Esprit; si toutefois l’Esprit de Dieu habite en vous; mais si quelqu’un n’a point l’Esprit de Christ, celui- là n’est point à lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Et si Christ est en vous, le corps est bien mort à cause du péché; mais l’esprit est vie à cause de la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Or si l’Esprit de celui qui a ressuscité Jésus des morts habite en vous, celui qui a ressuscité Christ des morts, vivifiera aussi vos corps mortels à cause de son Esprit qui habite en vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Ainsi donc, mes frères, nous sommes débiteurs, non point à la chair, pour vivre selon la chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Car si vous vivez selon la chair, vous mourrez; mais si par l’Esprit vous mortifiez les actions du corps, vous vivrez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Or tous ceux qui sont conduits par l’Esprit de Dieu, sont enfants de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Car vous n’avez point reçu un esprit de servitude, pour être encore dans la crainte; mais vous avez reçu l’Esprit d’adoption, par lequel nous crions Abba, c’est-à-dire, Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'C’est ce même Esprit qui rend témoignage avec notre esprit que nous sommes enfants de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Et si nous sommes enfants, nous sommes donc héritiers: héritiers, dis-je, de Dieu, et cohéritiers de Christ; si nous souffrons avec lui, afin que nous soyons aussi glorifiés avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Car tout bien compté, j’estime que les souffrances du temps présent ne sont point comparables à la gloire à venir qui doit être révélée en nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Car le grand et ardent désir des créatures, est qu’elles attendent que les enfants de Dieu soient révélés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, '(Parce que les créatures sont sujettes à la vanité, non de leur volonté; mais à cause de celui qui les y a assujetties) elles l’attendent, dis-je, dans l’espérance qu’elles seront aussi délivrées de la servitude de la corruption, pour être en la liberté de la gloire des enfants de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'Car nous savons que toutes les créatures soupirent et sont en travail ensemble jusques à maintenant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Et non seulement elles, mais nous aussi, qui avons les prémices de l’Esprit, nous-mêmes, dis-je, soupirons en nous-mêmes, en attendant l’adoption, c’est-à- dire, la rédemption de notre corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'Car ce que nous sommes sauvés, c’est en espérance: or l’espérance qu’on voit, n’est point espérance; car pourquoi même quelqu’un espérerait-il ce qu’il voit?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Mais si nous espérons ce que nous ne voyons point, c’est que nous l’attendons par la patience.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'De même aussi l’Esprit soulage de sa part nos faiblesses. Car nous ne savons pas comme il faut ce que nous devons demander; mais l’Esprit lui-même prie pour nous par des soupirs qui ne se peuvent exprimer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Mais celui qui sonde les coeurs, connaît quelle est l’affection de l’Esprit; car il prie pour les Saints, selon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'Or nous savons aussi que toutes choses contribuent au bien de ceux qui aiment Dieu, c’est-à-dire, de ceux qui sont appelés selon son propos arrêté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Car ceux qu’il a préconnus, il les a aussi prédestinés à être conformes à l’image de son Fils, afin qu’il soit le premier-né entre plusieurs frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Et ceux qu’il a prédestinés, il les a aussi appelés; et ceux qu’il a appelés, il les a aussi justifiés; et ceux qu’il a justifiés, il les a aussi glorifiés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'Que dirons-nous donc à ces choses? Si Dieu est pour nous, qui sera contre nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Lui qui n’a point épargné son propre Fils, mais qui l’a livré pour nous tous, comment ne nous donnera-t-il point aussi toutes choses avec lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Qui intentera accusation contre les élus de Dieu? Dieu est celui qui justifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Qui sera celui qui condamnera? Christ est celui qui est mort, et qui plus est, qui est ressuscité, qui aussi est à la droite de Dieu, et qui même prie pour nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Qui est-ce qui nous séparera de l’amour de Christ? sera-ce l’oppression, ou l’angoisse, ou la persécution, ou la famine, ou la nudité, ou le péril, ou l’épée?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Ainsi qu’il est écrit: nous sommes livrés à la mort pour l’amour de toi tous les jours, et nous sommes estimés comme des brebis de la boucherie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Au contraire, en toutes ces choses nous sommes plus que vainqueurs par celui qui nous a aimés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Car je suis assuré que ni la mort, ni la vie, ni les Anges, ni les Principautés, ni les Puissances, ni les choses présentes, ni les choses à venir,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Ni la hauteur, ni la profondeur, ni aucune autre créature, ne nous pourra séparer de l’amour de Dieu, qu’il nous a montré en Jésus-Christ notre Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Je dis la vérité en Christ, je ne mens point, ma conscience me rendant témoignage par le Saint-Esprit,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'Que j’ai une grande tristesse et un continuel tourment en mon coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Car moi-même je souhaiterais d’être séparé de Christ pour mes frères, qui sont mes parents selon la chair;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'Qui sont Israëlites, desquels sont l’adoption, la gloire, les alliances, l’ordonnance de la Loi, le service divin, et les promesses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'Desquels sont les pères, et desquels selon la chair est descendu Christ, qui est Dieu sur toutes choses, béni éternellement; Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Toutefois il ne se peut pas faire que la parole de Dieu soit anéantie; mais tous ceux qui sont d’Israël, ne sont pas pourtant Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'Car pour être de la semence d’Abraham ils ne sont pas tous ses enfants; mais, c’est en Isaac qu’on doit considérer sa postérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'c’est-à-dire, que ce ne sont pas ceux qui sont enfants de la chair, qui sont enfants de Dieu; mais que ce sont les enfants de la promesse, qui sont réputés pour semence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Car voici la parole de la promesse: je viendrai en cette même saison, et Sara aura un fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Et non seulement cela; mais aussi Rebecca, lorsqu’elle conçut d’un, savoir de notre père Isaac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'Car avant que les enfants fussent nés, et qu’ils eussent fait ni bien ni mal, afin que le dessein arrêté selon l’élection de Dieu demeurât, non point par les oeuvres, mais par celui qui appelle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'Il lui fut dit: le plus grand sera asservi au moindre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Ainsi qu’il est écrit: j’ai aimé Jacob, et j’ai haï Esaü.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Que dirons-nous donc: y a-t-il de l’iniquité en Dieu? à Dieu ne plaise!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Car il dit à Moïse: j’aurai compassion de celui de qui j’aurai compassion; et je ferai miséricorde à celui à qui je ferai miséricorde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Ce n’est donc point du voulant, ni du courant: mais de Dieu qui fait miséricorde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Car l’Ecriture dit à Pharaon: je t’ai fait subsister dans le but de démontrer en toi ma puissance, et afin que mon Nom soit publié dans toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Il a donc compassion de celui qu’il veut, et il endurcit celui qu’il veut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Or tu me diras: pourquoi se plaint-il encore? car qui est celui qui peut résister à sa volonté?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Mais plutôt, ô homme, qui es-tu, toi qui contestes contre Dieu? la chose formée dira-t-elle à celui qui l’a formée: pourquoi m’as-tu ainsi faite?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Le potier de terre n’a-t-il pas la puissance de faire d’une même masse de terre un vaisseau à honneur, et un autre à déshonneur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Et qu’est-ce, si Dieu en voulant montrer sa colère, et donner à connaître sa puissance, a toléré avec une grande patience les vaisseaux de colère, préparés pour la perdition?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'Et afin de donner à connaître les richesses de sa gloire dans les vaisseaux de miséricorde, qu’il a préparés pour la gloire;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'Et qu’il a appelés, c’est à savoir nous, non seulement d’entre les Juifs, mais aussi d’entre les Gentils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Selon ce qu’il dit en Osée: j’appellerai mon peuple celui qui n’était point mon peuple; et la bien-aimée, celle qui n’était point la bien-aimée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'Et il arrivera, qu’au lieu où il leur a été dit: vous n’êtes point mon peuple, là ils seront appelés les enfants du Dieu vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Aussi Esaïe s’écrie au sujet d’Israël: quand le nombre des enfants d’Israël serait comme le sable de la mer, il n’y en aura qu’un petit reste de sauvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Car le Seigneur consomme et abrège l’affaire en justice: il fera, dis-je, une affaire abrégée sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'Et comme Esaïe avait dit auparavant: si le Seigneur des armées ne nous eût laissé quelque semence, nous eussions été faits comme Sodome, et eussions été semblables à Gomorrhe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Que dirons-nous donc? que les Gentils qui ne cherchaient point la justice, ont atteint la justice, la justice, dis-je, qui est par la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'Mais Israël cherchant la Loi de la justice, n’est point parvenu à la Loi de la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Pourquoi? parce que ce n’a point été par la foi, mais comme par les oeuvres de la Loi; car ils ont heurté contre la pierre d’achoppement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'Selon ce qui est écrit: voici, je mets en Sion la pierre d’achoppement; et la pierre qui occasionnera des chutes; et quiconque croit en lui ne sera point confus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Mes frères, quant à la bonne affection de mon coeur, et à la prière que je fais à Dieu pour Israël, c’est qu’ils soient sauvés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Car je leur rends témoignage qu’ils ont du zèle pour Dieu, mais sans connaissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Parce que ne connaissant point la justice de Dieu, et cherchant d’établir leur propre justice, ils ne se sont point soumis à la justice de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Car Christ est la fin de la Loi, en justice à tout croyant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Or Moïse décrit ainsi la justice qui est par la Loi, savoir, que l’homme qui fera ces choses, vivra par elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Mais la justice qui est par la foi, s’exprime ainsi: ne dis point en ton coeur: qui montera au Ciel? cela est ramener Christ d’en haut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'Ou: qui descendra dans l’abîme? cela est ramener Christ des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Mais que dit-elle? La parole est près de toi en ta bouche, et en ton coeur. Or c’est là la parole de la foi, laquelle nous prêchons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'C’est pourquoi, si tu confesses le Seigneur Jésus de ta bouche, et que tu croies en ton coeur que Dieu l’a ressuscité des morts, tu seras sauvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Car de coeur on croit à justice, et de bouche on fait confession à salut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Car l’Ecriture dit: quiconque croit en lui ne sera point confus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Parce qu’il n’y a point de différence du Juif et du Grec; car il y a un même Seigneur de tous, qui est riche envers tous ceux qui l’invoquent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Car quiconque invoquera le nom du Seigneur sera sauvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Mais comment invoqueront-ils celui en qui ils n’ont point cru? et comment croiront-ils en celui dont ils n’ont point entendu parler? et comment en entendront-ils parler s’il n’y a quelqu’un qui leur prêche?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Et comment prêchera-t-on sinon qu’il y en ait qui soient envoyés? ainsi qu’il est écrit: ô que les pieds de ceux qui annoncent la paix sont beaux, les pieds, dis-je, de ceux qui annoncent de bonnes choses!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Mais tous n’ont pas obéi à l’Evangile; car Esaïe dit: Seigneur, qui est-ce qui a cru à notre prédication.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'La foi donc est de l’ouïe; et l’ouïe par la parole de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Mais je demande: ne l’ont-ils point ouï? au contraire, leur voix est allée par toute la terre, et leur parole jusques aux bouts du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Mais je demande: Israël ne l’a-t-il point connu? Moïse le premier dit: je vous exciterai à la jalousie par celui qui n’est point peuple; je vous exciterai à la colère par une nation destituée d’intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'Et Esaïe s’enhardit tout à fait, et dit: j’ai été trouvé de ceux qui ne me cherchaient point, et je me suis clairement manifesté à ceux qui ne s’enquéraient point de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Mais quant à Israël, il dit: j’ai tout le jour étendu mes mains vers un peuple rebelle et contredisant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Je demande donc: Dieu a-t-il rejeté son peuple? à Dieu ne plaise! Car je suis aussi Israëlite, de la postérité d’Abraham, de la Tribu de Benjamin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Dieu n’a point rejeté son peuple, lequel il a auparavant connu. Et ne savez- vous pas ce que l’Ecriture dit d’Elie, comment il a fait requête à Dieu contre Israël, disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, 'Seigneur, ils ont tué tes Prophètes, et ils ont démoli tes autels, et je suis demeuré moi seul; et ils tâchent à m’ôter la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Mais que lui fut-il répondu de Dieu? je me suis réservé sept mille hommes, qui n’ont point fléchi le genou devant Bahal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Ainsi donc il y a aussi à présent un résidu selon l’élection de la grâce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Or si c’est par la grâce, ce n’est plus par les oeuvres; autrement la grâce n’est plus la grâce. Mais si c’est par les oeuvres, ce n’est plus par la grâce; autrement l’oeuvre n’est plus une oeuvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Quoi donc? c’est que ce qu’Israël cherchait, il ne l’a point obtenu; mais l’élection l’a obtenu, et les autres ont été endurcis;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'Ainsi qu’il est écrit: Dieu leur a donné un esprit assoupi, et des yeux pour ne point voir, et des oreilles pour ne point ouïr, jusqu’au jour présent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Et David dit: que leur table leur soit un filet, un piège, une occasion de chute, et cela pour leur récompense.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Que leurs yeux soient obscurcis pour ne point voir; et courbe continuellement leur dos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Mais je demande: ont-ils bronché pour tomber? nullement! mais par leur chute le salut est accordé aux Gentils, pour les exciter à la jalousie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Or si leur chute est la richesse du monde, et leur diminution la richesse des Gentils, combien plus le sera leur abondance?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Car je parle à vous, Gentils; certes en tant que je suis Apôtre des Gentils, je rends honorable mon ministère;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'Pour voir si en quelque façon je puis exciter ceux de ma nation à la jalousie, et en sauver quelques-uns.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Car si leur rejection est la réconciliation du monde, quelle sera leur réception sinon une vie d’entre les morts?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Or si les prémices sont saintes, la masse l’est aussi; et si la racine est sainte, les branches le sont aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Que si quelques-unes des branches ont été retranchées, et si toi qui étais un olivier sauvage, as été enté en leur place, et fait participant de la racine et de la graisse de l’olivier;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'Ne te glorifie pas contre les branches; car si tu te glorifies, ce n’est pas toi qui portes la racine, mais c’est la racine qui te porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Mais tu diras: les branches ont été retranchées, afin que j’y fusse enté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'C’est bien dit, elles ont été retranchées à cause de leur incrédulité, et tu es debout par la foi: ne t’élève donc point par orgueil, mais crains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Car si Dieu n’a point épargné les branches naturelles, prends garde qu’il ne t’épargne point aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Considère donc la bonté et la sévérité de Dieu: la sévérité sur ceux qui sont tombés; et la bonté envers toi, si tu persévères en sa bonté: car autrement tu seras aussi coupé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Et eux-mêmes aussi, s’ils ne persistent point dans leur incrédulité, ils seront entés: car Dieu est puissant pour les enter de nouveau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Car si tu as été coupé de l’olivier qui de sa nature était sauvage, et as été enté contre la nature sur l’olivier franc, combien plus ceux qui le sont selon la nature, seront-ils entés sur leur propre olivier?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Car mes frères, je ne veux pas que vous ignoriez ce mystère, afin que vous ne vous en fassiez pas accroire, c’est qu’il est arrivé de l’endurcissement en Israël dans une partie, jusqu’à ce que la plénitude des Gentils soit entrée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'Et ainsi tout Israël sera sauvé; selon ce qui est écrit: le Libérateur viendra de Sion, et il détournera de Jacob les infidélités;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'Et c’est là l’alliance que je ferai avec eux, lorsque j’ôterai leurs péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Ils sont certes ennemis par rapport à l’Evangile, à cause de vous; mais ils sont bien-aimés eu égard à l’élection, à cause des pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Car les dons et la vocation de Dieu sont sans repentance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Or comme vous avez été vous-mêmes autrefois rebelles à Dieu, et que maintenant vous avez obtenu miséricorde par la rébellion de ceux-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'Ceux-ci tout de même sont maintenant devenus rebelles, afin qu’ils obtiennent aussi miséricorde par la miséricorde qui vous a été faite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Car Dieu les a tous renfermés sous la rébellion, afin de faire miséricorde à tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'Ô profondeur des richesses et de la sagesse et de la connaissance de Dieu! que ses jugements sont incompréhensibles, et ses voies impossibles à trouver!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Car qui est-ce qui a connu la pensée du Seigneur? ou qui a été son conseiller?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Ou qui est-ce qui lui a donné le premier, et il lui sera rendu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Car de lui, et par lui, et pour lui sont toutes choses. A lui soit gloire éternellement: Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Je vous exhorte donc, mes frères, par les compassions de Dieu, que vous offriez vos corps en sacrifice vivant, saint, agréable à Dieu, ce qui est votre raisonnable service.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'Et ne vous conformez point à ce présent siècle, mais soyez transformés par le renouvellement de votre entendement, afin que vous éprouviez quelle est la volonté de Dieu, bonne, agréable, et parfaite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Or par la grâce qui m’est donnée je dis à chacun d’entre vous, que nul ne présume d’être plus sage qu’il ne faut; mais que chacun pense modestement de soi-même, selon que Dieu a départi à chacun la mesure de la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Car comme nous avons plusieurs membres en un seul corps, et que tous les membres n’ont pas une même fonction;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'Ainsi nous qui sommes plusieurs, sommes un seul corps en Christ; et chacun réciproquement les membres l’un de l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Or ayant des dons différents, selon la grâce qui nous est donnée: soit de prophétie, prophétisons selon l’analogie de la foi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Soit de ministère, appliquons-nous au ministère; soit que quelqu’un soit appelé à enseigner, qu’il enseigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'Soit que quelqu’un se trouve appelé à exhorter, qu’il exhorte; soit que quelqu’un distribue, qu’il le fasse en simplicité; soit que quelqu’un préside, qu’il le fasse soigneusement; soit que quelqu’un exerce la miséricorde, qu’il le fasse joyeusement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Que la charité soit sincère. Ayez en horreur le mal, vous tenant collés au bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Etant portés par la charité fraternelle à vous aimer mutuellement; vous prévenant l’un l’autre par honneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'N’étant point paresseux à vous employer pour autrui; étant fervents d’esprit; servant le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Soyez joyeux dans l’espérance; patients dans la tribulation; persévérants dans l’oraison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Communiquant aux nécessités des Saints; exerçant l’hospitalité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Bénissez ceux qui vous persécutent; bénissez-les, et ne les maudissez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Soyez en joie avec ceux qui sont en joie; et pleurez avec ceux qui pleurent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Ayant un même sentiment les uns envers les autres, n’affectant point des choses hautes, mais vous accommodant aux choses basses. Ne soyez point sages à votre propre jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Ne rendez à personne mal pour mal. Recherchez les choses honnêtes devant tous les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'S’il se peut faire, et autant que cela dépend de vous, ayez la paix avec tous les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Ne vous vengez point vous-mêmes, mes bien-aimés, mais laissez agir la colère de Dieu, car il est écrit: à moi appartient la vengeance; je le rendrai, dit le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Si donc ton ennemi a faim, donne-lui à manger; s’il a soif, donne-lui à boire: car en faisant cela tu retireras des charbons de feu qui sont sur sa tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Ne sois point surmonté par le mal, mais surmonte le mal par le bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Que toute personne soit soumise aux Puissances supérieures: car il n’y a point de Puissance qui ne vienne de Dieu, et les Puissances qui subsistent, sont ordonnées de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'C’est pourquoi celui qui résiste à la Puissance, résiste à l’ordonnance de Dieu; et ceux qui y résistent, feront venir la condamnation sur eux-mêmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Car les Princes ne sont point à craindre pour de bonnes actions, mais pour de mauvaises. Or veux-tu ne point craindre la Puissance? fais bien, et tu en recevras de la louange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'Car le Prince est le serviteur de Dieu pour ton bien; mais si tu fais le mal, crains; parce qu’il ne porte point vainement l’épée, car il est le serviteur de Dieu, ordonné pour faire justice en punissant celui qui fait le mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'C’est pourquoi il faut être soumis, non seulement à cause de la punition, mais aussi à cause de la conscience.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Car c’est aussi pour cela que vous leur payez les tributs, parce qu’ils sont les ministres de Dieu, s’employant à rendre la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Rendez donc à tous ce qui leur est dû: à qui le tribut, le tribut; à qui le péage, le péage; à qui crainte, la crainte; à qui honneur, l’honneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Ne devez rien à personne, sinon que vous vous aimiez l’un l’autre; car celui qui aime les autres, a accompli la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Parce que ce qui est dit: Tu ne commettras point adultère, Tu ne tueras point, Tu ne déroberas point, Tu ne diras point de faux témoignage, Tu ne convoiteras point, et tel autre commandement, est sommairement compris dans cette parole: Tu aimeras ton Prochain comme toi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'La charité ne fait point de mal au Prochain: l’accomplissement donc de la Loi, c’est la charité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Même vu la saison, parce qu’il est déjà temps de nous réveiller du sommeil; car maintenant le salut est plus près de nous, que lorsque nous avons cru.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'La nuit est passée et le jour est approché; rejetons donc les oeuvres de ténèbres, et soyons revêtus des armes de lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Conduisons-nous honnêtement et comme en plein jour; non point en gourmandises, ni en ivrogneries; non point en couches, ni en insolences; non point en querelles, ni en envie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Mais soyez revêtus du Seigneur Jésus-Christ; et n’ayez point soin de la chair pour accomplir ses convoitises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Or quant à celui qui est faible en la foi, recevez-le, et n’ayez point avec lui des contestations ni des disputes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'L’un croit qu’on peut manger de toutes choses, et l’autre qui est faible mange des herbes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Que celui qui mange de toutes choses, ne méprise pas celui qui n’en mange point; et que celui qui n’en mange point, ne juge point celui qui en mange: car Dieu l’a pris à soi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Qui es-tu toi, qui juges le serviteur d’autrui? s’il se tient ferme ou s’il bronche, c’est pour son propre maître; et même ce Chrétien faible sera affermi; car Dieu est puissant pour l’affermir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'L’un estime un jour plus que l’autre, et l’autre estime tous les jours également, mais que chacun soit pleinement persuadé en son esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Celui qui a égard au jour, y a égard à cause du Seigneur; et celui aussi qui n’a point égard au jour, il n’y a point d’égard à cause du Seigneur; celui qui mange de toutes choses, en mange à cause du Seigneur, et il rend grâces à Dieu; et celui qui n’en mange point, n’en mange point aussi à cause du Seigneur, et il rend grâces à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Car nul de nous ne vit pour soi-même, et nul ne meurt pour soi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Mais soit que nous vivions, nous vivons au Seigneur; ou soit que nous mourions, nous mourons au Seigneur; soit donc que nous vivions, soit que nous mourions, nous sommes au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Car c’est pour cela que Christ est mort, qu’il est ressuscité, et qu’il a repris une nouvelle vie; afin qu’il domine tant sur les morts que sur les vivants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Mais toi pourquoi juges-tu ton frère? ou toi aussi, pourquoi méprises-tu ton frère? certes nous comparaîtrons tous devant le siège judicial de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Car il est écrit: je suis vivant, dit le Seigneur, que tout genou se ploiera devant moi, et que toute langue donnera louange à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Ainsi donc chacun de nous rendra compte pour soi-même à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Ne nous jugeons donc plus l’un l’autre; mais usez plutôt de discernement en ceci, qui est de ne mettre point d’achoppement ou de scandale devant votre frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Je sais et je suis persuadé par le Seigneur Jésus, que rien n’est souillé de soi-même; mais cependant si quelqu’un croit qu’une chose est souillée, elle lui est souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Mais si ton frère est attristé de te voir manger d’une viande, tu ne te conduis point en cela par la charité; ne détruis point par la viande celui pour lequel Christ est mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Que l’avantage dont vous jouissez ne soit point exposé à être blâmé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Car le Royaume de Dieu n’est point viande ni breuvage; mais il est justice, paix, et joie par le Saint-Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Et celui qui sert Christ en ces choses-là, est agréable à Dieu, et il est approuvé des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Recherchons donc les choses qui vont à la paix, et qui sont d’une édification mutuelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Ne ruine point l’oeuvre de Dieu par ta viande. Il est vrai que toutes choses sont pures, mais celui-là fait mal qui mange en donnant du scandale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Il est bon de ne point manger de viande, de ne point boire de vin, et de ne faire aucune autre chose qui puisse faire broncher ton frère, ou dont il soit scandalisé, ou dont il soit blessé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'As-tu la foi? aie-la en toi-même devant Dieu. Car bienheureux est celui qui ne condamne point soi-même en ce qu’il approuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Mais celui qui en fait scrupule, est condamné s’il en mange, parce qu’il n’ en mange point avec foi; or tout ce qui n’est point de la foi, est un péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Or nous devons, nous qui sommes forts, supporter les infirmités des faibles, et non pas nous complaire à nous-mêmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Que chacun de nous donc complaise à son prochain pour son bien, pour son édification.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Car même Jésus-Christ n’a point voulu complaire à soi-même, mais selon ce qui est écrit de lui: les outrages de ceux qui t’outragent sont tombés sur moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Car toutes les choses qui ont été écrites auparavant, ont été écrites pour notre instruction; afin que par la patience et par la consolation des Ecritures nous ayons espérance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Or le Dieu de patience et de consolation vous fasse la grâce d’avoir tous un même sentiment selon Jésus-Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'Afin que tous d’un même coeur, et d’une même bouche vous glorifiiez Dieu, qui est le Père de notre Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'C’est pourquoi recevez-vous l’un l’autre, comme aussi Christ nous a reçus à lui, pour la gloire de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Or je dis que Jésus-Christ a été Ministre de la Circoncision, pour la vérité de Dieu, afin de ratifier les promesses faites aux Pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'Et afin que les Gentils honorent Dieu pour sa miséricorde; selon ce qui est écrit: je célébrerai à cause de cela ta louange parmi les Gentils, et je psalmodierai à ton Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'Et il est dit encore: Gentils, réjouissez-vous avec son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'Et encore: toutes Nations, louez le Seigneur; et vous tous peuples célébrez-le.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'Esaïe a dit aussi: il y aura une Racine de Jessé, et un rejeton s’élèvera pour gouverner les Gentils, et les Gentils auront espérance en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Le Dieu d’espérance donc vous veuille remplir de toute joie et de toute paix, en croyant; afin que vous abondiez en espérance par la puissance du Saint-Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Or mes frères, je suis aussi moi-même persuadé que vous êtes aussi pleins de bonté, remplis de toute connaissance, et que vous pouvez même vous exhorter l’un l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Mais mes frères, je vous ai écrit en quelque sorte plus librement, comme vous faisant ressouvenir de ces choses, à cause de la grâce qui m’a été donnée de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'Afin que je sois ministre de Jésus Christ envers les Gentils, m’employant au sacrifice de l’Evangile de Dieu; afin que l’oblation des Gentils soit agréable, étant sanctifiée par le Saint-Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'J’ai donc de quoi me glorifier en Jésus-Christ dans les choses qui regardent Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Car je ne saurais rien dire que Christ n’ait fait par moi pour amener les Gentils à l’obéissance par la parole, et par les oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'Avec la vertu des prodiges et des miracles, par la puissance de l’Esprit de Dieu; tellement que depuis Jérusalem, et les lieux d’alentour, jusque dans l’Illyrie, j’ai tout rempli de l’Evangile de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'M’attachant ainsi avec affection à annoncer l’Evangile là où Christ n’avait pas encore été prêché, afin que je n’édifiasse point sur un fondement qu’un autre eût déjà posé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'Mais, selon qu’il est écrit: ceux à qui il n’a point été annoncé le verront; et ceux qui n’en ont point ouï parler l’entendront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Et c’est aussi ce qui m’a souvent empêché de vous aller voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Mais maintenant que je n’ai aucun sujet de m’arrêter en ce pays, et que depuis plusieurs années j’ai un grand désir d’aller vers vous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'J’irai vers vous lorsque je partirai pour aller en Espagne; et j’espère que je vous verrai en passant par votre pays, et que vous me conduirez là, après que j’aurai été premièrement rassasié en partie d’avoir été avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Mais pour le présent je m’en vais à Jérusalem pour assister les Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Car il a semblé bon aux Macédoniens et aux Achaïens de faire une contribution pour les pauvres d’entre les Saints qui sont à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Il leur a, dis-je, ainsi semblé bon, et aussi leur sont-ils obligés: car si les Gentils ont été participants de leurs biens spirituels, ils leur doivent aussi faire part des charnels.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Après donc que j’aurai achevé cela, et que j’aurai consigné ce fruit, j’irai en Espagne en passant par vos quartiers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Et je sais que quand j’irai vers vous j’y irai avec une abondance de bénédictions de l’Evangile de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Or je vous exhorte, mes frères, par notre Seigneur Jésus-Christ, et par la charité de l’Esprit, que vous combattiez avec moi dans vos prières à Dieu pour moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'Afin que je sois délivré des rebelles qui sont en Judée, et que mon administration que j’ai à faire à Jérusalem, soit rendue agréable aux Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'Afin que j’aille vers vous avec joie par la volonté de Dieu, et que je me récrée avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Or le Dieu de paix soit avec vous tous: Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Je vous recommande notre soeur Phoebé, qui est Diaconesse de l’Eglise de Cenchrée:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'Afin que vous la receviez selon le Seigneur, comme il faut recevoir les Saints; et que vous l’assistiez en tout ce dont elle aura besoin; car elle a exercé l’hospitalité à l’égard de plusieurs, et même à mon égard.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Saluez Priscille et Aquilas mes Compagnons d’oeuvre en Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'Qui ont soumis leur cou pour ma vie, et auxquels je ne rends pas grâces moi seul, mais aussi toutes les Eglises des Gentils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Saluez aussi l’Eglise qui est dans leur maison. Saluez Epainète mon bien- aimé, qui est les prémices d’Achaïe en Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Saluez Marie, qui a fort travaillé pour nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Saluez Andronique et Junias mes cousins, qui ont été prisonniers avec moi, et qui sont distingués entre les Apôtres, et qui même ont été avant moi en Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Saluez Amplias mon bien-aimé au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Saluez Urbain notre Compagnon d’oeuvre en Christ, et Stachys mon bien aimé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Saluez Apelles approuvé en Christ. Saluez ceux de chez Aristobule.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Saluez Hérodion mon cousin. Saluez ceux de chez Narcisse qui sont en notre Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Saluez Tryphène et Thryphose, lesquelles travaillent en notre Seigneur. Saluez Perside la bien-aimée, qui a beaucoup travaillé en notre Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Saluez Rufus élu au Seigneur, et sa mère, que je regarde comme la mienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Saluez Asyncrite, Phlégon, Hermas, Patrobas, Hermès, et les frères qui sont avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Saluez Philologue, et Julie, Nérée, et sa soeur, et Olympe, et tous les Saints qui sont avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Saluez-vous l’un l’autre par un saint baiser. Les Eglises de Christ vous saluent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Or je vous exhorte, mes frères, de prendre garde à ceux qui causent des divisions et des scandales contre la doctrine que vous avez apprise, et de vous éloigner d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Car ces sortes de gens ne servent point notre Seigneur Jésus-Christ, mais leur propre ventre, et par de douces paroles et des flatteries ils séduisent les coeurs des simples.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Car votre obéissance est venue à la connaissance de tous. Je me réjouis donc de vous; mais je désire que vous soyez prudents quant au bien, et simples quant au mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Or le Dieu de paix brisera bientôt satan sous vos pieds. La grâce de notre Seigneur Jésus-Christ soit avec vous, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Timothée mon Compagnon d’oeuvre vous salue, comme aussi Lucius, et Jason, et Sosipater mes cousins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Moi Tertius qui ai écrit cette Epître, je vous salue en notre Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Gaïus mon hôte, et celui de toute l’Eglise, vous salue. Eraste le Procureur de la ville, vous salue, et Quartus notre frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'La grâce de notre Seigneur Jésus-Christ soit avec vous tous, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Or à celui qui est puissant pour vous affermir selon mon Evangile, et selon la prédication de Jésus-Christ, conformément à la révélation du mystère qui a été tû dans les temps passés,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'Mais qui est maintenant manifesté par les Ecritures des Prophètes, suivant le commandement du Dieu éternel, et qui est annoncé parmi tous les peuples pour les amener à la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'A Dieu, dis-je, seul sage, soit gloire éternellement par Jésus-Christ, Amen! ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paul appelé à être Apôtre de Jésus-Christ, par la volonté de Dieu, et le frère Sosthènes,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'A l’Eglise de Dieu qui est à Corinthe, aux sanctifiés en Jésus- Christ, qui êtes appelés à être saints, avec tous ceux qui en quelque lieu que ce soit invoquent le Nom de notre Seigneur Jésus-Christ, leur Seigneur et le nôtre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Que la grâce et la paix vous soient données par Dieu notre Père, et par le Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Je rends toujours grâces à mon Dieu à cause de vous, pour la grâce de Dieu qui vous a été donnée en Jésus-Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'De ce qu’en toutes choses vous êtes enrichis en lui de tout don de parole, et de toute connaissance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'Selon que le témoignage de Jésus-Christ a été confirmé en vous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'Tellement qu’il ne vous manque aucun don, pendant que vous attendez la manifestation de notre Seigneur Jésus-Christ,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'Qui aussi vous affermira jusqu’à la fin, pour être irrépréhensibles en la journée de notre Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Et Dieu, par qui vous avez été appelés à la communion de son Fils Jésus-Christ notre Seigneur, est fidèle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Or je vous prie, mes frères, par le Nom de notre Seigneur Jésus- Christ, que vous parliez tous un même langage, et qu’il n’y ait point de divisions entre vous, mais que vous soyez bien unis dans un même sentiment, et dans un même avis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Car, mes frères, il m’a été dit de vous par ceux qui sont de chez Chloé, qu’il y a des dissensions parmi vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Voici donc ce que je dis, c’est que chacun de vous dit: pour moi, je suis de Paul; et moi je suis d’Apollos; et moi, de Céphas; et moi, de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Christ est-il divisé? Paul a-t-il été crucifié pour vous? ou avez-vous été baptisés au nom de Paul?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Je rends grâces à Dieu que je n’ai baptisé aucun de vous, sinon Crispus et Gaïus;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'Afin que personne ne dise que j’ai baptisé en mon nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'J’ai bien aussi baptisé la famille de Stéphanas; du reste, je ne sais pas si j’ai baptisé quelque autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Car Christ ne m’a pas envoyé pour baptiser, mais pour évangéliser, non point avec les discours de la sagesse humaine, afin que la croix de Christ ne soit point anéantie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Car la parole de la croix est une folie à ceux qui périssent; mais à nous qui obtenons le salut, elle est la vertu de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Vu qu’il est écrit: j’abolirai la sagesse des sages, et j’anéantirai l’intelligence des hommes intelligents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Où est le sage? où est le Scribe? où est le Disputeur de ce Siècle? Dieu n’a-t-il pas manifesté la folie de la sagesse de ce monde?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Car puisqu’en la sapience de Dieu, le monde n’a point connu Dieu par la sagesse, le bon plaisir de Dieu a été de sauver les croyants par la folie de la prédication.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Car les Juifs demandent des miracles, et les Grecs cherchent la sagesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Mais pour nous, nous prêchons Christ crucifié, qui est un scandale pour les Juifs, et une folie pour les Grecs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'A ceux, dis-je, qui sont appelés tant Juifs que Grecs, nous leur prêchons Christ, la puissance de Dieu, et la sagesse de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Parce que la folie de Dieu est plus sage que les hommes, et la faiblesse de Dieu est plus forte que les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Car, mes frères, vous voyez votre vocation, que vous n’êtes pas beaucoup de sages selon la chair, ni beaucoup de puissants, ni beaucoup de nobles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Mais Dieu a choisi les choses folles de ce monde, pour rendre confuses les sages; et Dieu a choisi les choses faibles de ce monde, pour rendre confuses les fortes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'Et Dieu a choisi les choses viles de ce monde, et les méprisées, même celles qui ne sont point, pour abolir celles qui sont.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'Afin que nulle chair ne se glorifie devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Or c’est par lui que vous êtes en Jésus-Christ, qui vous a été fait de la part de Dieu sagesse, justice, sanctification, et rédemption;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Afin que comme il est écrit, celui qui se glorifie, se glorifie au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Pour moi donc, mes frères, quand je suis venu vers vous, je n’y suis point venu avec des discours pompeux, remplis de la sagesse humaine, en vous annonçant le témoignage de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Parce que je ne me suis proposé de savoir autre chose parmi vous, que Jésus-Christ, et JésusChrist crucifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'Et j’ai même été parmi vous dans la faiblesse, dans la crainte, et dans un grand tremblement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'Et ma parole et ma prédication n’a point été en paroles persuasives de la sagesse humaine: mais en évidence d’Esprit et de puissance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'Afin que votre foi ne soit point l’effet de la sagesse des hommes, mais de la puissance de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Or nous proposons une sagesse entre les parfaits, une sagesse, dis- je, qui n’est point de ce monde, ni des princes de ce siècle, qui vont être anéantis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Mais nous proposons la sagesse de Dieu, qui est en mystère, c’est-à-dire, cachée; laquelle Dieu avait, dès avant les siècles, déterminée à notre gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Et laquelle aucun des princes de ce siècle n’a connue; car s’ils l’eussent connue, jamais ils n’eussent crucifié le Seigneur de gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Mais ainsi qu’il est écrit: ce sont des choses que l’oeil n’a point vues; que l’oreille n’a point ouïes, et qui ne sont point montées au cœur de l’homme, lesquelles Dieu a préparées à ceux qui l’aiment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Mais Dieu nous les a révélées par son Esprit. Car l’Esprit sonde toutes choses, même les choses profondes de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Car qui est-ce des hommes qui sache les choses de l’homme, sinon l’esprit de l’homme qui est en lui? De même aussi nul n’a connu les choses de Dieu, sinon l’Esprit de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Or nous avons reçu non point l’esprit de ce monde, mais l’Esprit qui est de Dieu; afin que nous connaissions les choses qui nous ont été données de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'Lesquelles aussi nous proposons, non point avec les paroles que la sagesse humaine enseigne, mais avec celles qu’enseigne le Saint- Esprit, appropriant les choses spirituelles à ceux qui sont spirituels.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Or l’homme animal ne comprend point les choses qui sont de l’Esprit de Dieu, car elles lui sont une folie; et il ne peut même les entendre, parce qu’elles se discernent spirituellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Mais l’homme spirituel discerne toutes choses, et il n’est jugé de personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Car qui a connu la pensée du Seigneur pour le pouvoir instruire? mais nous, nous avons l’intention de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Et pour moi, mes frères, je n’ai pu vous parler comme à des hommes spirituels, mais comme à des hommes charnels, c’est-à- dire, comme à des enfants en Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Je vous ai donné du lait à boire, et non pas de la viande, parce que vous ne la pouviez pas encore porter; même maintenant vous ne le pouvez pas encore; parce que vous êtes encore charnels.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'Car puisqu’il y a parmi vous de l’envie, et des dissensions, et des divisions, n’êtes-vous pas charnels, et ne vous conduisez-vous pas à la manière des hommes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Car quand l’un dit: pour moi, je suis de Paul; et l’autre: pour moi, je suis d’Apollos; n’êtes-vous pas charnels?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Qui est donc Paul, et qui est Apollos, sinon des Ministres, par lesquels vous avez cru, selon que le Seigneur a donné à chacun?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'J’ai planté; Apollos a arrosé; mais c’est Dieu qui a donné l’accroissement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Or ni celui qui plante, ni celui qui arrose, ne sont rien; mais Dieu, qui donne l’accroissement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Et tant celui qui plante, que celui qui arrose, ne sont qu’une même chose; mais chacun recevra sa récompense selon son travail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Car nous sommes ouvriers avec Dieu; et vous êtes le labourage de Dieu, et l’édifice de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Selon la grâce de Dieu qui m’a été donnée, j’ai posé le fondement comme un sage architecte, et un autre édifie dessus; mais que chacun examine comment il édifie dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Car personne ne peut poser d’autre fondement que celui qui est posé, lequel est Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Que si quelqu’un édifie sur ce fondement, de l’or, de l’argent, des pierres précieuses, du bois, du foin, du chaume;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'L’oeuvre de chacun sera manifestée; car le jour la fera connaître, parce qu’elle sera manifestée par le feu; et le feu éprouvera quelle sera l’oeuvre de chacun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Si l’oeuvre de quelqu’un qui aura édifié dessus, demeure, il en recevra la récompense.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Si 1’oeuvre de quelqu’un brûle, il en fera la perte; mais pour lui, il sera sauvé, toutefois comme par le feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Ne savez-vous pas que vous êtes le Temple de Dieu, et que l’Esprit de Dieu habite en vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Si quelqu’un détruit le Temple de Dieu, Dieu le détruira; car le Temple de Dieu est saint, et vous êtes ce Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Que personne ne s’abuse lui-même; si quelqu’un d’entre vous croit être sage en ce monde, qu’il se rende fou, afin de devenir sage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Parce que la sagesse de ce monde est une folie devant Dieu; car il est écrit: il surprend les sages en leur ruse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'Et encore: le Seigneur connaît que les discours des sages sont vains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Que personne donc ne se glorifie dans les hommes; car toutes choses sont à vous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'Soit Paul, soit Apollos, soit Céphas, soit le monde, soit la vie, soit la mort, soit les choses présentes, soit les choses à venir, toutes choses sont à vous, et vous à Christ, et Christ à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Que chacun nous tienne pour Ministres de Christ, et pour dispensateurs des mystères de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Mais, au reste, il est exigé des dispensateurs que chacun soit trouvé fidèle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Pour moi, je me soucie fort peu d’être jugé de vous, ou de jugement d’homme; et aussi je ne me juge point moi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Car je ne me sens coupable de rien; mais pour cela je ne suis pas justifié; mais celui qui me juge, c’est le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'C’est pourquoi ne jugez de rien avant le temps, jusqu’à ce que le Seigneur vienne, qui aussi mettra en lumière les choses cachées dans les ténèbres, et qui manifestera les conseils des coeurs; et alors Dieu rendra à chacun sa louange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Or, mes frères, j’ai tourné par une façon de parler, ce discours sur moi et sur Apollos, à cause de vous; afin que vous appreniez de nous à ne point présumer au delà de ce qui est écrit, de peur que l’un pour l’autre vous ne vous enfliez contre autrui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Car qui est-ce qui met de la différence entre toi et un autre? et qu’est-ce que tu as, que tu ne l’aies reçu? et si tu l’as reçu, pourquoi t’en glorifies-tu comme si tu ne l’avais point reçu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Vous êtes déjà rassasiés, vous êtes déjà enrichis, vous êtes faits Rois sans nous; et plût à Dieu que vous régnassiez, afin que nous régnassions aussi avec vous!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Car je pense que Dieu nous a exposés publiquement, nous qui sommes les derniers Apôtres, comme des gens condamnés à la mort, vu que nous sommes rendus le spectacle du monde, des Anges et des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Nous sommes fous pour l’amour de Christ, mais vous êtes sages en Christ; nous sommes faibles, et vous êtes forts; vous êtes dans l’estime, et nous sommes dans le mépris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Jusqu’à cette heure nous souffrons la faim et la soif, et nous sommes nus; nous sommes souffletés, et nous sommes errants çà et là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'Et nous nous fatiguons en travaillant de nos propres mains; on dit du mal de nous, et nous bénissons; nous sommes persécutés, et nous le souffrons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'Nous sommes blâmés, et nous prions; nous sommes faits comme les balayures du monde, et comme le rebut de tous, jusqu’à maintenant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Je n’écris point ces choses pour vous faire honte; mais je vous donne des avis comme à mes chers enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Car quand vous auriez dix mille maîtres en Christ, vous n’avez pourtant pas plusieurs pères: car c’est moi qui vous ai engendrés en Jésus-Christ par l’Evangile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Je vous prie donc d’être mes imitateurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'C’est pour cela que je vous ai envoyé Timothée, qui est mon fils bien-aimé, et qui est fidèle en notre Seigneur; afin qu’il vous fasse souvenir de mes voies en Christ, et comment j’enseigne partout dans chaque Eglise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Or quelques-uns se sont glorifiés comme si je ne devais point aller vers vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Mais j’irai bientôt vers vous, si le Seigneur le veut; et je connaîtrai non point la parole de ceux qui se sont glorifiés, mais l’efficace.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Car le Royaume de Dieu ne consiste point en paroles, mais en efficace.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Que voulez-vous? irai-je à vous avec la verge, ou avec charité, et un esprit de douceur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'On entend dire de toutes parts qu’il y a parmi vous de l’impudicité, et même une telle impudicité, qu’entre les Gentils il n’est point fait mention de semblable; c’est que quelqu’un entretient la femme de son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Et cependant vous êtes enflés d’orgueil, et vous n’avez pas plutôt mené deuil, afin que celui qui a commis cette action fût retranché du milieu de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Mais moi, étant absent de corps, mais présent en esprit, j’ai déjà ordonné comme si j’étais présent, touchant celui qui a ainsi commis une telle action.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'Vous et mon esprit étant assemblés au Nom de notre Seigneur Jésus- Christ, j’ai, dis-je, ordonné, par la puissance de notre Seigneur Jésus-Christ,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'Qu’un tel homme soit livré à satan, pour la destruction de la chair; afin que l’esprit soit sauvé au jour du Seigneur Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Votre vanité est mal fondée; ne savez-vous pas qu’un peu de levain fait lever toute la pâte?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Otez donc le vieux levain, afin que vous soyez une nouvelle pâte, comme vous êtes sans levain; car Christ, notre Pâque, a été sacrifié pour nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'C’est pourquoi faisons la fête, non point avec le vieux levain, ni avec un levain de méchanceté et de malice, mais avec les pains sans levain de la sincérité et de la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Je vous ai écrit dans ma Lettre, que vous ne vous mêliez point avec les fornicateurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'Mais non pas absolument avec les fornicateurs de ce monde, ou avec les avares, ou les ravisseurs, ou les idolâtres; car autrement certes, il vous faudrait sortir du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Or maintenant, je vous écris que vous ne vous mêliez point avec eux; c’est-à-dire, que si quelqu’un qui se nomme frère, est fornicateur, ou avare, ou idolâtre, ou médisant, ou ivrogne, ou ravisseur, vous ne mangiez pas même avec un tel homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Car aussi qu’ai-je affaire de juger de ceux qui sont de dehors? ne jugez-vous pas de ceux qui sont de dedans?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Mais Dieu juge ceux qui sont de dehors. Otez donc d’entre vous- mêmes le méchant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Quand quelqu’un d’entre vous a une affaire contre un autre, ose-t- il bien aller en jugement devant les iniques, et il ne va pas devant les Saints?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Ne savez-vous pas que les Saints jugeront le monde? or si le monde doit être jugé par vous, êtes-vous indignes de juger des plus petites choses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Ne savez-vous pas que nous jugerons les Anges? combien plus donc devons-nous juger des choses qui concernent cette vie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Si donc vous avez des procès pour les affaires de cette vie, prenez pour juges ceux qui sont des moins estimés dans l’Eglise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Je le dis à votre honte: n’y a-t-il donc point de sages parmi vous, non pas même un seul qui puisse juger entre ses frères?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Mais un frère a des procès contre son frère, et cela devant les infidèles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'C’est même déjà un grand défaut en vous, que vous ayez des procès entre vous. Pourquoi n’endurez-vous pas plutôt qu’on vous fasse tort? Pourquoi ne souffrez-vous pas plutôt du dommage?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Mais, au contraire, vous faites tort, et vous causez du dommage, et même à vos frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Ne savez-vous pas que les injustes n’hériteront point le Royaume de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'Ne vous trompez point vous-mêmes: ni les fornicateurs, ni les idolâtres, ni les adultères, ni les efféminés, ni ceux qui commettent des péchés contre nature, ni les larrons, ni les avares, ni les ivrognes, ni les médisants, ni les ravisseurs, n’hériteront point le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Et quelques-uns de vous étiez tels; mais vous avez été lavés, mais vous avez été sanctifiés, mais vous avez été justifiés au Nom du Seigneur Jésus, et par l’Esprit de notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Toutes choses me sont permises, mais toutes choses ne conviennent pas; toutes choses me sont permises, mais je ne serai point assujetti sous la puissance d’aucune chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Les viandes sont pour l’estomac, et l’estomac est pour les viandes: mais Dieu détruira l’un et l’autre. Or le corps n’est point pour la fornication, mais pour le Seigneur, et le Seigneur pour le corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Et Dieu qui a ressuscité le Seigneur, nous ressuscitera aussi par sa puissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Ne savez-vous pas que vos corps sont les membres de Christ? Oterai-je donc les membres de Christ, pour en faire les membres d’une prostituée? à Dieu ne plaise!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Ne savez-vous pas que celui qui s’unit avec une prostituée, devient un même corps avec elle? car deux, est-il dit, seront une même chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Mais celui qui est uni au Seigneur, est un même esprit avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Fuyez la fornication; quelque autre péché que l’homme commette, il est hors du corps; mais le fornicateur pèche contre son propre corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Ne savez-vous pas que votre corps est le Temple du Saint-Esprit, qui est en vous, et que vous avez de Dieu? Et vous n’êtes point à vous-mêmes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Car vous avez été achetés par prix; glorifiez donc Dieu en votre corps, et en votre esprit, qui appartiennent à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Or quant aux choses dont vous m’avez écrit: Je vous dis qu’il est bon à l’homme de ne pas se marier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Toutefois pour éviter l’impureté, que chacun ait sa femme, et que chaque femme ait son mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Que le mari rende à sa femme la bienveillance qui lui est due; et que la femme de même la rende à son mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Car la femme n’a pas son propre corps en sa puissance, mais il est en celle du mari; et le mari tout de même n’a pas en sa puissance son propre corps, mais il est en celle de la femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Ne vous privez point l’un de l’autre, si ce n’est par un consentement mutuel, pour un temps, afin que vous vaquiez au jeûne et à la prière, mais après cela retournez ensemble, de peur que satan ne vous tente, par votre incontinence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Or je dis ceci par permission, et non par commandement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Car je voudrais que tous les hommes fussent comme moi; mais chacun a son propre don lequel il a reçu de Dieu, l’un en une manière, et l’autre en une autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Or je dis à ceux qui ne sont point mariés, et aux veuves, qu’il leur est bon de demeurer comme moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Mais s’ils ne sont pas continents, qu’ils se marient; car il vaut mieux se marier que de brûler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Et quant à ceux qui sont mariés, je leur commande, non pas moi, mais le Seigneur, que la femme ne se sépare point du mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'Et si elle s’en sépare, qu’elle demeure sans être mariée, ou qu’elle se réconcilie avec son mari; que le mari aussi ne quitte point sa femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Mais aux autres je leur dis, et non pas le Seigneur: Si quelque frère a une femme infidèle, et qu’elle consente d’habiter avec lui, qu’il ne la quitte point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'Et si quelque femme a un mari infidèle, et qu’il consente d’habiter avec elle, qu’elle ne le quitte point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Car le mari infidèle est sanctifié en la femme, et la femme infidèle est sanctifiée dans le mari; autrement vos enfants seraient impurs; or maintenant ils sont saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Que si l’infidèle se sépare, qu’il se sépare; le frère ou la soeur ne sont point asservis dans ce cas-là; mais Dieu nous a appelés à la paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Car que sais-tu, femme, si tu ne sauveras point ton mari? ou que sais-tu, mari, si tu ne sauveras point ta femme?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Toutefois que chacun se conduise selon le don qu’il a reçu de Dieu, chacun selon que le Seigneur l’y a appelé; et c’est ainsi que j’en ordonne dans toutes les Eglises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Quelqu’un est-il appelé étant circoncis? qu’il ne ramène point le prépuce. Quelqu’un est-il appelé étant dans le prépuce? qu’il ne se fasse point circoncire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'La Circoncision n’est rien, et le prépuce aussi n’est rien, mais l’observation des commandements de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Que chacun demeure dans la condition où il était quand il a été appelé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Es-tu appelé étant esclave? ne t’en mets point en peine; mais aussi si tu peux être mis en liberté, uses en plutôt:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Car celui qui étant esclave est appelé à notre Seigneur, il est l’affranchi du Seigneur; et de même celui qui est appelé étant libre, il est l’esclave de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Vous avez été achetés par prix; ne devenez point les esclaves des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Mes frères, que chacun demeure envers Dieu dans l’état où il était quand il a été appelé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Pour ce qui concerne les vierges, je n’ai point de commandement du Seigneur, mais j’en donne avis comme ayant obtenu miséricorde du Seigneur, pour être fidèle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'J’estime donc que cela est bon pour la nécessité présente, en tant qu’il est bon à l’homme d’être ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Es-tu lié à une femme? ne cherche point d’en être séparé. Es-tu détaché de ta femme? ne cherche point de femme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Que si tu te maries, tu ne pèches point; et si la vierge se marie, elle ne pèche point aussi; mais ceux qui sont mariés auront des afflictions en la chair; or je vous épargne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Mais je vous dis ceci, mes frères, que le temps est court; et ainsi que ceux qui ont une femme, soient comme s’ils n’en avaient point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'Et ceux qui sont dans les pleurs, comme s’ils n’étaient point dans les pleurs; et ceux qui sont dans la joie, comme s’ils n’étaient point dans la joie; et ceux qui achètent, comme s’ils ne possédaient point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'Et ceux qui usent de ce monde, comme n’en abusant point: car la figure de ce monde passe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Or je voudrais que vous fussiez sans inquiétude. Celui qui n’est point marié a soin des choses qui sont du Seigneur, comment il plaira au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Mais celui qui est marié, a soin des choses de ce monde, et comment il plaira à sa femme, et ainsi il est divisé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'La femme qui n’est point mariée, et la vierge, a soin des choses qui sont du Seigneur, pour être sainte de corps et d’esprit; mais celle qui est mariée a soin des choses qui sont du monde, comment elle plaira à son mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Or je dis ceci ayant égard à ce qui vous est utile, non point pour vous tendre un piége, mais pour vous porter à ce qui est bienséant, et propre à vous unir au Seigneur sans aucune distraction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Mais si quelqu’un croit que ce soit un déshonneur à sa fille de passer la fleur de son âge, et qu’il faille la marier, qu’il fasse ce qu’il voudra, il ne pèche point; qu’elle soit mariée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Mais celui qui demeure ferme en son coeur, n’y ayant point de nécessité qu’il marie sa fille, mais étant le maître de sa propre volonté a arrêté en son coeur de garder sa fille, il fait bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Celui donc qui la marie fait bien, mais celui qui ne la marie pas, fait mieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'La femme est liée par la Loi pendant tout le temps que son mari est en vie, mais si son mari meurt, elle est en liberté de se marier à qui elle veut; seulement que ce soit en notre Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Elle est néanmoins plus heureuse si elle demeure ainsi, selon mon avis; or j’estime que j’ai aussi l’Esprit de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Pour ce qui regarde les choses qui sont sacrifiées aux idoles: nous savons que nous avons tous de la connaissance. La science enfle, mais la charité édifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Et si quelqu’un croit savoir quelque chose, il n’a encore rien connu comme il faut connaître;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Mais si quelqu’un aime Dieu, il est connu de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'Pour ce qui regarde donc de manger des choses sacrifiées aux idoles, nous savons que l’idole n’est rien au monde, et qu’il n’y a aucun autre Dieu qu’un seul;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Car encore qu’il y en ait qui soient appelés dieux, soit au ciel, soit en la terre (comme il y a plusieurs dieux, et plusieurs Seigneurs,)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'Nous n’avons pourtant qu’un seul Dieu, qui est le Père; duquel sont toutes choses, et nous en lui; et un seul Seigneur Jésus- Christ, par lequel sont toutes choses, et nous par lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Mais il n’y a pas en tous la même connaissance; car quelques-uns qui jusqu’à présent font conscience à cause de l’idole, de manger des choses qui ont été sacrifiées à l’idole, en mangent pourtant; c’est pourquoi leur conscience étant faible, elle en est souillée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Or la viande ne nous rend pas agréables à Dieu; car si nous mangeons, nous n’en avons rien davantage; et si nous ne mangeons point, nous n’en avons pas moins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Mais prenez garde que cette liberté que vous avez, ne soit en quelque sorte en scandale aux faibles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Car si quelqu’un te voit, toi qui as de la connaissance, être à table au temple des idoles, la conscience de celui qui est faible, ne sera-t-elle pas induite à manger des choses sacrifiées à l’idole?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'Et ainsi ton frère, qui est faible, pour lequel Christ est mort, périra par ta connaissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Or quand vous péchez ainsi contre vos frères, et que vous blessez leur conscience qui est faible, vous péchez contre Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'C’est pourquoi, si la viande scandalise mon frère, je ne mangerai jamais de chair, pour ne point scandaliser mon frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Ne suis-je pas Apôtre? ne suis-je pas libre? n’ai-je pas vu notre Seigneur Jésus-Christ? n’êtes-vous pas mon ouvrage au Seigneur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Si je ne suis pas Apôtre pour les autres, je le suis au moins pour vous; car vous êtes le sceau de mon Apostolat au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'C’est là mon apologie envers ceux qui me condamnent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'N’avons-nous pas le pouvoir de manger et de boire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'N’avons-nous pas le pouvoir de mener avec nous une soeur femme, ainsi que les autres Apôtres, et les frères du Seigneur, et Céphas?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'N’y a-t-il que Barnabas et moi qui n’ayons pas le pouvoir de ne point travailler?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Qui est-ce qui va jamais à la guerre à ses dépens? qui est-ce qui plante la vigne, et ne mange point de son fruit? qui est-ce qui paît le troupeau, et ne mange pas du lait du troupeau?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Dis-je ces choses selon l’homme? la loi ne dit-elle pas aussi la même chose?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Car il est écrit dans la Loi de Moise: tu n’emmuselleras point le boeuf qui foule le grain. Or Dieu a-t-il soin des boeufs?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Et n’est-ce pas entièrement pour nous qu’il a dit ces choses; certes elles sont écrites pour nous; car celui qui laboure, doit labourer avec espérance; et celui qui foule le blé, le foule avec espérance d’en être participant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Si nous avons semé des biens spirituels, est-ce une grande chose que nous recueillions de vos biens charnels?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Et si d’autres usent de ce pouvoir à votre égard, pourquoi n’en userions-nous pas plutôt qu’eux? cependant nous n’avons point usé de ce pouvoir, mais au contraire nous supportons toutes sortes d’incommodités, afin de ne donner aucun empêchement à l’Evangile de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Ne savez-vous pas que ceux qui s’emploient aux choses sacrées, mangent de ce qui est sacré; et que ceux qui servent à l’autel, participent à l’autel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Le Seigneur a ordonné tout de même que ceux qui annoncent l’Evangile, vivent de l’Evangile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Cependant je ne me suis point prévalu d’aucune de ces choses, et je n’écris pas même ceci afin qu’on en use de cette manière envers moi, car j’aimerais mieux mourir, que de voir que quelqu’un anéantît ma gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Car encore que j’évangélise, je n’ai pas de quoi m’en glorifier; parce que la nécessité m’en est imposée; et malheur à moi, si je n’évangélise pas!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Mais si je le fais de bon coeur, j’en aurai la récompense; mais si c’est à regret, je ne fais que m’acquitter de la commission qui m’en a été donnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Quelle récompense en ai-je donc? c’est qu’en prêchant l’Evangile, je prêche l’Evangile de Christ sans apporter aucune dépense, afin que je n’abuse pas de mon pouvoir dans l’Evangile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Car bien que je sois en liberté à l’égard de tous, je me suis pourtant asservi à tous, afin de gagner plus de personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Et je me suis fait aux Juifs comme Juif, afin de gagner les Juifs; à ceux qui sont sous la Loi, comme si j’étais sous la Loi, afin de gagner ceux qui sont sous la Loi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'A ceux qui sont sans Loi, comme si j’étais sans Loi (quoique je ne sois point sans Loi quant à Dieu, mais je suis sous la Loi de Christ,) afin de gagner ceux qui sont sans Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Je me suis fait comme faible aux faibles, afin de gagner les faibles; je me suis fait toutes choses à tous, afin qu’absolument j’en sauve quelques-uns.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Et je fais cela à cause de l’Evangile, afin que j’en sois fait aussi participant avec les autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Ne savez-vous pas que quand on court dans la lice, tous courent bien, mais un seul remporte le prix? courez donc tellement que vous le remportiez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Or quiconque lutte, vit entièrement de régime; et quant à ceux- là, ils le font pour avoir une couronne corruptible; mais nous, pour en avoir une incorruptible.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Je cours donc, mais non pas sans savoir comment; je combats, mais non pas comme battant l’air.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'Mais je mortifie mon corps, et je me le soumets; de peur qu’après avoir prêché aux autres, je ne sois trouvé moi-même en quelque sorte non recevable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Or mes frères, je ne veux pas que vous ignoriez que nos pères ont tous été sous la nuée, et qu’ils ont tous passé par la mer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'Et qu’ils ont tous été baptisés par Moïse en la nuée et en la mer;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'Et qu’ils ont tous mangé d’une même viande spirituelle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'Et qu’ils ont tous bu d’un même breuvage spirituel: car ils buvaient de l’eau de la pierre spirituelle qui les suivait; et la pierre était Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Mais Dieu n’a point pris plaisir en plusieurs d’eux; car ils ont été accablés au désert.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Or ces choses ont été des exemples pour vous, afin que nous ne convoitions point des choses mauvaises, comme eux-mêmes les ont convoitées;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Et que vous ne deveniez point idolâtres, comme quelques-uns d’eux; ainsi qu’il est écrit: le peuple s’est assis pour manger et pour boire; et puis ils se sont levés pour jouer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Et afin que nous ne nous laissions point aller à la fornication, comme quelques-uns d’eux s’y sont abandonnés, et il en est tombé en un jour vingt-trois mille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Et que nous ne tentions point Christ, comme quelques-uns d’eux l’ ont tenté, et ont été détruits par les serpents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Et que vous ne murmuriez point, comme quelques-uns d’eux ont murmurés, et sont péris par le destructeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Or toutes ces choses leur arrivaient en exemple, et elles sont écrites pour notre instruction, comme étant ceux auxquels les derniers temps sont parvenus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Que celui donc qui croit demeurer debout, prenne garde qu’il ne tombe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Aucune tentation ne vous a éprouvés, qui n’ait été une tentation humaine; et Dieu est fidèle, qui ne permettra point que vous soyez tentés au-delà de vos forces, mais avec la tentation il vous en fera trouver l’issue, afin que vous la puissiez soutenir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'C’est pourquoi, mes bien-aimés, fuyez l’idolâtrie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Je vous parle comme à des personnes intelligentes; jugez vous- mêmes de ce que je dis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'La coupe de bénédiction, laquelle nous bénissons, n’est-elle pas la communion du sang de Christ? et le pain que nous rompons, n’est- il pas la communion du corps de Christ?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Parce qu’il n’y a qu’un seul pain, nous qui sommes plusieurs, sommes un seul corps; car nous sommes tous participants du même pain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Voyez l’Israël selon la chair, ceux qui mangent les sacrifices, ne sont-ils pas participants de l’autel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Que dis-je donc? que l’idole soit quelque chose? ou que ce qui est sacrifié à l’idole, soit quelque chose? Non.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Mais je dis que les choses que les Gentils sacrifient, ils les sacrifient aux démons, et non pas à Dieu; or je ne veux pas que vous soyez participants des démons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Vous ne pouvez boire la coupe du Seigneur, et la coupe des démons; vous ne pouvez être participants de la table du Seigneur, et de la table des démons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Voulons-nous inciter le Seigneur à la jalousie? sommes-nous plus forts que lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Toutes choses me sont permises, mais toutes choses ne sont pas convenables; toutes choses me sont permises, mais toutes choses n’édifient pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Que personne ne cherche ce qui lui est propre, mais que chacun cherche ce qui est pour autrui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Mangez de tout ce qui se vend à la boucherie, sans vous en enquérir pour la conscience:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Car la terre est au Seigneur, avec tout ce qu’elle contient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Que si quelqu’un des infidèles vous convie, et que vous y vouliez aller, mangez de tout ce qui est mis devant vous, sans vous en enquérir pour la conscience.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Mais si quelqu’un vous dit: cela est sacrifié aux idoles, n’en mangez point à cause de celui qui vous en a avertis, et à cause de la conscience; car la terre est au Seigneur, avec tout ce qu’elle contient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Or je dis la conscience, non pas la tienne, mais celle de l’autre; car pourquoi ma liberté serait-elle condamnée par la conscience d’un autre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Et si par la grâce j’en suis participant, pourquoi suis-je blâmé pour une chose dont je rends grâces?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Soit donc que vous mangiez, soit que vous buviez, ou que vous fassiez quelque autre chose, faites tout à la gloire de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Soyez tels que vous ne donniez aucun scandale ni aux Juifs, ni aux Grecs, ni à l’Eglise de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'Comme aussi je complais à tous en toutes choses, ne cherchant point ma commodité propre, mais celle de plusieurs, afin qu’ils soient sauvés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Soyez mes imitateurs, comme je le suis moi-même de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Or, mes frères, je vous loue de ce que vous vous souvenez de tout ce qui me concerne, et de ce que vous gardez mes ordonnances, comme je vous les ai données.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Mais je veux que vous sachiez que le Chef de tout homme, c’est Christ; et que le Chef de la femme, c’est l’homme; et que le Chef de Christ, c’est Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Tout homme qui prie, ou qui prophétise, ayant quelque chose sur la tête, déshonore sa tête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Mais toute femme qui prie, ou qui prophétise sans avoir la tête couverte, déshonore sa tête: car c’est la même chose que si elle était rasée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Si donc la femme n’est pas couverte, qu’on lui coupe les cheveux. Or s’il est déshonnête à la femme d’avoir les cheveux coupés, ou d’être rasée, qu’elle soit couverte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Car pour ce qui est de l’homme, il ne doit point couvrir sa tête, vu qu’il est l’image et la gloire de Dieu; mais la femme est la gloire de l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Parce que l’homme n’a point été tiré de la femme, mais la femme a été tirée de l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Et aussi l’homme n’a pas été créé pour la femme, mais la femme pour l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'C’est pourquoi la femme à cause des Anges doit avoir sur la tête une marque qu’elle est sous la puissance de son mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Toutefois ni l’homme n’est point sans la femme, ni la femme sans l’homme en notre Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Car comme la femme est par l’homme, aussi l’homme est par la femme; mais toutes choses procèdent de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Jugez-en entre vous-mêmes: est-il convenable que la femme prie Dieu sans être couverte?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'La nature même ne vous enseigne-t-elle pas que si l’homme nourrit sa chevelure, ce lui est du déshonneur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Mais que si la femme nourrit sa chevelure, ce lui est de la gloire, parce que la chevelure lui est donnée pour couverture.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Que si quelqu’un aime à contester, nous n’avons pas une telle coutume, ni aussi les Eglises de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Or en ce que je vais vous dire, je ne vous loue point: c’est que vos assemblées ne sont pas mieux réglées qu’elles l’étaient; elles le sont moins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Car premièrement, quand vous vous assemblez dans l’Eglise, j’apprends qu’il y a des divisions parmi vous; et j’en crois une partie:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Car il faut qu’il y ait même des hérésies parmi vous, afin que ceux qui sont dignes d’approbation, soient manifestés parmi vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Quand donc vous vous assemblez ainsi tous ensemble, ce n’est pas manger la Cène du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Car lorsqu’il s’agit de prendre le repas, chacun prend par avance son souper particulier, en sorte que l’un a faim, et l’autre fait bonne chère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'N’avez-vous donc pas de maisons pour manger et pour boire? ou méprisez-vous l’Eglise de Dieu? et faites-vous honte à ceux qui n’ont rien? que vous dirai-je? vous louerai-je? je ne vous loue point en ceci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Car j’ai reçu du Seigneur ce qu’aussi je vous ai donné; c’est que le Seigneur Jésus la nuit qu’il fut trahi, prit du pain;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'Et après avoir rendu grâces il le rompit, et dit: prenez, mangez: ceci est mon corps qui est rompu pour vous; faites ceci en mémoire de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'De même aussi après le souper, il prit la coupe, en disant: cette coupe est la nouvelle alliance en mon sang; faites ceci toutes les fois que vous en boirez, en mémoire de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Car toutes les fois que vous mangerez de ce pain, et que vous boirez de cette coupe, vous annoncerez la mort du Seigneur jusques à ce qu’il vienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'C’est pourquoi quiconque mangera de ce pain, ou boira de la coupe du Seigneur indignement, sera coupable du corps et du sang du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Que chacun donc s’éprouve soi-même, et ainsi qu’il mange de ce pain, et qu’il boive de cette coupe;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Car celui qui en mange et qui en boit indignement, mange et boit sa condamnation, ne distinguant point le corps du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Et c’est pour cela que plusieurs sont faibles et malades parmi vous, et que plusieurs dorment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Car si nous nous jugions nous-mêmes, nous ne serions point jugés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Mais quand nous sommes jugés, nous sommes enseignés par le Seigneur, afin que nous ne soyons point condamnés avec le monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'C’est pourquoi, mes frères, quand vous vous assemblez pour manger, attendez-vous l’un l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Et si quelqu’un a faim, qu’il mange en sa maison, afin que vous ne vous assembliez pas pour votre condamnation. Touchant les autres points, j’en ordonnerai quand je serai arrivé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Or pour ce qui regarde les dons spirituels, je ne veux point, mes frères, que vous en soyez ignorants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Vous savez que vous étiez Gentils, entraînés après les idoles muettes, selon que vous étiez menés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'C’est pourquoi je vous fais savoir que nul homme parlant par l’Esprit de Dieu, ne dit que Jésus doit être rejeté; et que nul ne peut dire que par le Saint-Esprit, que Jésus est le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Or il y a diversité de dons, mais il n’y a qu’un même Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'Il y a aussi diversité de ministères, mais il n’y a qu’un même Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'Il y a aussi diversité d’opérations; mais il n’y a qu’un même Dieu, qui opère toutes choses en tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Or à chacun est donnée la lumière de l’Esprit pour procurer l’utilité commune.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Car à l’un est donnée par l’Esprit, la parole de sagesse; et à l’autre par le même Esprit, la parole de connaissance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'Et à un autre, la foi par ce même Esprit; à un autre, les dons de guérison par ce même Esprit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'Et à un autre, les opérations des miracles; à un autre, la prophétie; à un autre, le don de discerner les esprits; à un autre, la diversité de Langues; et à un autre, le don d’interpréter les Langues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Mais un seul et même Esprit fait toutes ces choses, distribuant à chacun ses dons comme il le trouve à propos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Car comme le corps n’est qu’un, et cependant il a plusieurs membres, mais tous les membres de ce corps, qui n’est qu’un, quoiqu’ils soient plusieurs, ne sont qu’un corps, il en est de même de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Car nous avons tous été baptisés d’un même Esprit, pour être un même corps, soit Juifs, soit Grecs, soit esclaves, soit libres, nous avons tous, dis-je, été abreuvés d’un même Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Car aussi le corps n’est pas un seul membre, mais plusieurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Si le pied dit: parce que je ne suis pas la main, je ne suis point du corps; n’est-il pas pourtant du corps?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'Et si l’oreille dit: parce que je ne suis pas l’oeil, je ne suis point du corps; n’est-elle pas pourtant du corps?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Si tout le corps est l’oeil, où sera l’ouïe? si tout est l’ouïe, où sera l’odorat?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Mais maintenant Dieu a placé chaque membre dans le corps, comme il a voulu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Et si tous étaient un seul membre, où serait le corps?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Mais maintenant il y a plusieurs membres, toutefois il n’y a qu’un seul corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Et l’oeil ne peut pas dire à la main: je n’ai que faire de toi; ni aussi la tête aux pieds: je n’ai que faire de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Et qui plus est, les membres du corps qui semblent être les plus faibles, sont beaucoup plus nécessaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'Et ceux que nous estimons être les moins honorables au corps, nous les ornons avec plus de soin, et les parties qui sont en nous les moins belles à voir, sont les plus parées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'Car les parties qui sont belles en nous, n’en ont pas besoin; mais Dieu a apporté ce tempérament dans notre corps, qu’il a donné plus d’honneur à ce qui en manquait;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'Afin qu’il n’y ait point de division dans le corps, mais que les membres aient un soin mutuel les uns des autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Et soit que l’un des membres souffre quelque chose, tous les membres souffrent avec lui; ou soit que l’un des membres soit honoré, tous les membres ensemble s’en réjouissent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Or vous êtes le corps de Christ, et vous êtes chacun un de ses membres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'Et Dieu a mis dans l’Eglise, d’abord des Apôtres, ensuite des Prophètes, en troisième lieu des Docteurs, ensuite les miracles, puis les dons de guérisons, les secours, les gouvernements, les diversités de Langues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Tous sont-ils Apôtres? tous sont-ils Prophètes? tous sont-ils Docteurs? tous ont-ils le don des miracles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Tous ont-ils les dons de guérisons? tous parlent-ils diverses Langues? tous interprètent-ils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Or désirez avec ardeur des dons plus excellents, et je vais vous en montrer un chemin qui surpasse encore de beaucoup.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Quand je parlerais toutes les langues des hommes, et même des Anges, si je n’ai pas la charité, je suis comme l’airain qui résonne, ou comme la cymbale retentissante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Et quand j’aurais le don de prophétie, que je connaîtrais tous les mystères, et que j’aurais toute sorte de science; et quand j’aurais toute la foi qu’on puisse avoir, en sorte que je transportasse les montagnes, si je n’ai pas la charité, je ne suis rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Et quand je distribuerais tout mon bien pour la nourriture des pauvres, et que je livrerais mon corps pour être brûlé, si je n’ai pas la charité: cela ne me sert de rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'La charité est patience; elle est douce; la charité n’est point envieuse; la charité n’use point d’insolence; elle ne s’enorgueillit point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'Elle ne se porte point déshonnêtement; elle ne cherche point son propre profit; elle ne s’aigrit point; elle ne pense point à mal;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Elle ne se réjouit point de l’injustice; mais elle se réjouit de la vérité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Elle endure tout, elle croit tout, elle espère tout, elle supporte tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'La charité ne périt jamais, au lieu que quant aux prophéties, elles seront abolies; et quant aux Langues, elles cesseront; et quant à la connaissance, elle sera abolie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Car nous connaissons en partie, et nous prophétisons en partie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'Mais quand la perfection sera venue, alors ce qui est en partie sera aboli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Quand j’étais enfant, je parlais comme un enfant, je jugeais comme un enfant, je pensais comme un enfant; mais quand je suis devenu homme, j’ai aboli ce qui était de l’enfance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Car nous voyons maintenant par un miroir obscurément, mais alors nous verrons face à face; maintenant je connais en partie, mais alors je connaîtrai selon que j’ai été aussi connu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Or maintenant ces trois choses demeurent, la foi, l’espérance, et la charité; mais la plus excellente de ces vertus c’est la charité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Recherchez la charité. Désirez avec ardeur les dons spirituels, mais surtout de prophétiser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Parce que celui qui parle une Langue inconnue, ne parle point aux hommes, mais à Dieu, car personne ne l’entend, et les mystères qu’il prononce ne sont que pour lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Mais celui qui prophétise, édifie, exhorte et console les hommes qui l’entendent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Celui qui parle une Langue inconnue, s’édifie lui-même; mais celui qui prophétise, édifie l’Eglise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Je désire bien que vous parliez tous diverses Langues, mais beaucoup plus que vous prophétisiez, car celui qui prophétise est plus grand que celui qui parle diverses Langues, si ce n’est qu’il interprète, afin que l’Eglise en reçoive de l’édification.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Maintenant donc, mes frères, si je viens à vous, et que je parle des Langues inconnues, que vous servira cela, si je ne vous parle par révélation, ou par science, ou par prophétie, ou par doctrine?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'De même, si les choses inanimées qui rendent leur son, soit un hautbois, soit une harpe, ne forment des tons différents, comment connaîtra-t-on ce qui est sonné sur le hautbois, ou sur la harpe?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Et si la trompette rend un son qu’on n’entend pas, qui est-ce qui se préparera à la bataille?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'De même si vous ne prononcez dans votre langage une parole qui puisse être entendue, comment entendra-t-on ce qui se dit? car vous parlerez en l’air.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Il y a, selon qu’il se rencontre, tant de divers sons dans le monde, et cependant aucun de ces sons n’est muet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Mais si je ne sais point ce qu’on veut signifier par la parole, je serai barbare à celui qui parle; et celui qui parle me sera barbare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Ainsi puisque vous désirez avec ardeur des dons spirituels, cherchez d’en avoir abondamment pour l’édification de l’Eglise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'C’est pourquoi que celui qui parle une Langue inconnue, prie de telle sorte qu’il interprète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Car si je prie en une Langue inconnue, mon esprit prie, mais l’intelligence que j’en ai, est sans fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Quoi donc? je prierai d’esprit, mais je prierai aussi d’une manière à être entendu; je chanterai d’esprit, mais je chanterai aussi d’une manière à être entendu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Autrement si tu bénis d’esprit, comment celui qui est du simple peuple, dira-t-il Amen à ton action de grâces, puisqu’il ne sait ce que tu dis?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Il est bien vrai que tu rends grâces; mais un autre n’en est pas édifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Je rends grâces à mon Dieu que je parle plus de Langues que vous tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'Mais j’aime mieux prononcer dans l’Eglise cinq paroles d’une manière à être entendu, afin que j’instruise aussi les autres, que dix mille paroles en une Langue inconnue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Mes frères, ne soyez point des enfants en prudence, mais soyez de petits enfants en malice; et par rapport à la prudence, soyez des hommes faits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Il est écrit dans la Loi: je parlerai à ce peuple par des gens d’une autre Langue, et par des lèvres étrangères; et ainsi ils ne m’entendront point, dit le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'C’est pourquoi les Langues sont pour un signe, non point aux croyants, mais aux infidèles; la prophétie, au contraire, est un signe non point aux infidèles, mais aux croyants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Si donc toute l’Eglise s’assemble en un corps, et que tous parlent des Langues étrangères, et qu’il entre des gens du commun, ou des infidèles, ne diront-ils pas que vous êtes hors du sens?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Mais si tous prophétisent, et qu’il entre quelque infidèle, ou quelqu’un du commun, il est convaincu par tous, et il est jugé de tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'Et ainsi les secrets de son coeur sont manifestés, de sorte qu’il se jettera sur sa face, et adorera Dieu, et il publiera que Dieu est véritablement parmi vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Que sera-ce donc, mes frères? c’est que toutes les fois que vous vous assemblerez, selon que chacun de vous aura ou un Psaume, ou une instruction, ou une Langue étrangère, ou une révélation, ou une interprétation, que tout se fasse pour l’édification.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Et si quelqu’un parle une Langue inconnue, que cela se fasse par deux, ou tout au plus par trois, et cela par tour; mais qu’il y en ait un qui interprète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Que s’il n’y a point d’interprète, que cet homme se taise dans l’Eglise, et qu’il parle à soi-même, et à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Et que deux ou trois prophètes parlent, et que les autres en jugent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Et si quelque chose est révélée à un autre qui est assis, que le premier se taise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Car vous pouvez tous prophétiser l’un après l’autre, afin que tous apprennent, et que tous soient consolés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Et les Esprits des Prophètes sont sujets aux Prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Car Dieu n’est point un Dieu de confusion, mais de paix, comme on le voit dans toutes les Eglises des Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Que les femmes qui sont parmi vous se taisent dans les Eglises; car il ne leur est point permis de parler, mais elles doivent être soumises, comme aussi la Loi le dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Et si elles veulent apprendre quelque chose, qu’elles interrogent leurs maris dans la maison; car il est malhonnête que les femmes parlent dans l’Eglise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'La parole de Dieu est-elle procédée de vous? ou est-elle parvenue seulement à vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Si quelqu’un croit être Prophète, ou spirituel, qu’il reconnaisse que les choses que je vous écris sont des commandements du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Et si quelqu’un est ignorant, qu’il soit ignorant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'C’est pourquoi, mes frères, désirez avec ardeur de prophétiser, et n’empêchez point de parler diverses Langues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Que toutes choses se fassent avec bienséance, et avec ordre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Or, mes frères, je vous fais savoir l’Evangile que je vous ai annoncé, et que vous avez reçu, et auquel vous vous tenez fermes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'Et par lequel vous êtes sauvés, si vous le retenez en quelle manière je vous l’ai annoncé; à moins que vous n’ayez cru en vain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Car avant toutes choses, je vous ai donné ce que j’avais aussi reçu, savoir, que Christ est mort pour nos péchés, selon les Ecritures;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'Et qu’il a été enseveli, et qu’il est ressuscité le troisième jour, selon les Ecritures;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'Et qu’il a été vu de Céphas, et ensuite des Douze.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Depuis il a été vu de plus de cinq cents frères à une fois, dont plusieurs sont encore vivants, et quelques-uns sont morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Ensuite il a été vu de Jacques, et puis de tous les Apôtres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'Et après tous, il a été vu aussi de moi, comme d’un avorton.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Car je suis le moindre des Apôtres, qui ne suis pas digne d’être appelé ApÔtre, parce que j’ai persécuté l’Eglise de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Mais par la grâce de Dieu je suis ce que je suis; et sa grâce envers moi n’a point été vaine, mais j’ai travaillé beaucoup plus qu’eux tous; toutefois non point moi, mais la grâce de Dieu qui est avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Soit donc moi, soit eux, nous prêchons ainsi, et vous l’avez cru ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Or si on prêche que Christ est ressuscité des morts, comment disent quelques-uns d’entre vous qu’il n’y a point de résurrection des morts?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Car s’il n’y a point de résurrection des morts, Christ aussi n’est point ressuscité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'Et si Christ n’est point ressuscité, notre prédication est donc vaine, et votre foi aussi est vaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Et même nous sommes de faux témoins de la part de Dieu: car nous avons rendu témoignage de la part de Dieu qu’il a ressuscité Christ; lequel pourtant il n’a pas ressuscité, si les morts ne ressuscitent point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Car si les morts ne ressuscitent point, Christ aussi n’est point ressuscité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'Et si Christ n’est point ressuscité, votre foi est vaine, et vous êtes encore dans vos péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Ceux donc aussi qui dorment en Christ, sont péris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Si nous n’avons d’espérance en Christ que pour cette vie seulement, nous sommes les plus misérables de tous les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Mais maintenant Christ est ressuscité des morts, et il a été fait les prémices de ceux qui dorment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Car puisque la mort est par un seul homme, la résurrection des morts est aussi par un seul homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Car comme tous meurent en Adam, de même aussi tous seront vivifiés en Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Mais chacun en son rang, les prémices, c’est Christ; puis ceux qui sont de Christ seront vivifiés en son avénement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Et après viendra la fin, quand il aura remis le Royaume à Dieu le Père, et quand il aura aboli tout empire, et toute puissance, et toute force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Car il faut qu’il règne jusqu’à ce qu’il ait mis tous ses ennemis sous ses pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'L’ennemi qui sera détruit le dernier, c’est la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Car Dieu a assujetti toutes choses sous ses pieds; or quand il est dit que toutes choses lui sont assujetties, il est évident que celui qui lui a assujetti toutes choses est excepté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Et après que toutes choses lui auront été assujetties, alors aussi le Fils lui-même sera assujetti à celui qui lui a assujetti toutes choses; afin que Dieu soit tout en tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Autrement que feront ceux qui sont baptisés pour les morts, si absolument les morts ne ressuscitent point? pourquoi donc sont-ils baptisés pour les morts?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Pourquoi aussi sommes-nous en danger à toute heure?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Par notre gloire que j’ai en notre Seigneur Jésus-Christ, je meurs de jour en jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Si j’ai combattu contre les bêtes à Ephèse, par des vues humaines, quel profit en ai-je si les morts ne ressuscitent point? mangeons et buvons, car demain nous mourrons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Ne soyez point séduits: les mauvaises compagnies corrompent les bonnes moeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Réveillez-vous pour vivre justement, et ne péchez point; car quelques-uns sont sans la connaissance de Dieu; je vous le dis à votre honte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Mais quelqu’un dira: comment ressuscitent les morts, et en quel corps viendront-ils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Ô fou! ce que tu sèmes n’est point vivifié, s’il ne meurt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'Et quant à ce que tu sèmes, tu ne sèmes point le corps qui naîtra, mais le grain nu, selon qu’il se rencontre, de blé, ou de quelque autre grain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Mais Dieu lui donne le corps comme il veut, et à chacune des semences son propre corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Toute chair n’est pas une même sorte de chair; mais autre est la chair des hommes, et autre la chair des bêtes, et autre celle des poissons, et autre celle des oiseaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'Il y a aussi des corps célestes, et des corps terrestres; mais autre est la gloire des célestes, et autre celle des terrestres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Autre est la gloire du soleil, et autre la gloire de la lune, et autre la gloire des étoiles; car une étoile est différente d’une autre étoile en gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Il en sera aussi de même en la résurrection des morts; le corps est semé en corruption, il ressuscitera incorruptible.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'Il est semé en déshonneur, il ressuscitera en gloire; il est semé en faiblesse, il ressuscitera en force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'Il est semé corps animal, il ressuscitera corps spirituel: il y a un corps animal, et il y a un corps spirituel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'Comme aussi il est écrit: le premier homme Adam a été fait en âme vivante; et le dernier Adam en esprit vivifiant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Or ce qui est spirituel, n’est pas le premier: mais ce qui est animal; et puis ce qui est spirituel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Le premier homme étant de la terre, est tiré de la poussière; mais le second homme savoir le Seigneur, est du Ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Tel qu’est celui qui est tiré de la poussière, tels aussi sont ceux qui sont tirés de la poussière; et tel qu’est le céleste, tels aussi sont les célestes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'Et comme nous avons porté l’image de celui qui est tiré de la poussière, nous porterons aussi l’image du céleste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Voici donc ce que je dis, mes frères, c’est que la chair et le sang ne peuvent point hériter le Royaume de Dieu, et que la corruption n’hérite point l’incorruptibilité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Voici, je vous dis un mystère: nous ne dormirons pas tous, mais nous serons tous transmués;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'En un moment, et en un clin d’oeil, à la dernière trompette, car la trompette sonnera, et les morts ressusciteront incorruptibles, et nous serons transmués.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Car il faut que ce corruptible revête l’incorruptibilité, et que ce mortel revête l’immortalité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Or quand ce corruptible aura revêtu l’incorruptibilité, et que ce mortel aura revêtu l’immortalité, alors cette parole de l’Ecriture sera accomplie: la mort est détruite par la victoire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Où est, ô mort, ton aiguillon? où est, ô sépulcre, ta victoire?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Or l’aiguillon de la mort, c’est le péché; et la puissance du péché, c’est la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Mais grâces à Dieu, qui nous a donné la victoire par notre Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'C’est pourquoi, mes frères bien-aimés, soyez fermes, inébranlables, vous appliquant toujours avec un nouveau zèle à l’oeuvre du Seigneur; sachant que votre travail ne vous sera pas inutile auprès du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Touchant la collecte qui se fait pour les Saints, faites comme j’en ai ordonné aux Eglises de Galatie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'C’est que chaque premier jour de la semaine, chacun de vous mette à part chez soi, ce qu’il pourra assembler suivant la prospérité que Dieu lui accordera, afin que lorsque je viendrai, les collectes ne soient point à faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Puis quand je serai arrivé, j’enverrai ceux que vous approuverez par vos Lettres pour porter votre libéralité à Jérusalem.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'Et s’il est à propos que j’y aille moi-même, ils viendront aussi avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'J’irai donc vers vous, ayant passé par la Macédoine; car je passerai par la Macédoine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'Et peut-être que je séjournerai parmi vous, ou même que j’y passerai l’hiver; afin que vous me conduisiez partout où j’irai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Car je ne vous veux point voir maintenant en passant, mais j’espère que je demeurerai avec vous quelque temps, si le Seigneur le permet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Toutefois je demeurerai à Ephèse jusqu’à la Pentecôte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'Car une grande porte, et de grande efficace m’y est ouverte, mais il y a plusieurs adversaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Que si Timothée vient, prenez garde qu’il soit en sûreté parmi vous; car il s’emploie à l’oeuvre du Seigneur comme moi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Que personne donc ne le méprise; mais conduisez-le en toute sûreté, afin qu’il vienne me trouver; car je l’attends avec les frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Quant à Apollos notre frère, je l’ai beaucoup prié d’aller vers vous avec les frères, mais il n’a nullement eu la volonté d’y aller maintenant: toutefois il y ira quand il en aura la commodité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Veillez, soyez fermes en la foi, portez-vous vaillamment, fortifiez-vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Que toutes vos affaires se fassent en charité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Or, mes frères, vous connaissez la famille de Stéphanas, et vous savez qu’elle est les prémices de l’Achaïe, et qu’ils se sont entièrement appliqués au service des Saints;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'Je vous prie de vous soumettre à eux, et à chacun de ceux qui s’emploient à l’oeuvre du Seigneur, et qui travaillent avec nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Or je me réjouis de la venue de Stéphanas, de Fortunat, et d’Achaïque; parce qu’ils ont suppléé à ce que vous ne pouvez pas faire pour moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'Car ils ont recréé mon esprit et le vôtre: ayez donc de la considération pour de telles personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Les Eglises d’Asie vous saluent. Aquilas et Priscille, avec l’Eglise qui est en leur maison, vous saluent affectueusement en notre Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Tous les frères vous saluent. Saluez-vous l’un l’autre par un saint baiser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'La salutation est de la propre main de moi Paul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'S’il y a quelqu’un qui n’aime point le Seigneur Jésus-Christ, qu’il soit anathème, Maranatha.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Que la grâce de notre Seigneur Jésus-Christ soit avec vous!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Mon amour s’étend à vous tous en Jésus-Christ. Amen. ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paul Apôtre de Jésus-Christ par la volonté de Dieu, et le frère Timothée, à l’Église de Dieu qui est à Corinthe, avec tous les Saints qui sont dans toute l’Achaïe;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Que la grâce et la paix vous soient données par Dieu notre Père et par le Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Béni soit Dieu, qui est le Père de notre Seigneur Jésus-Christ, le Père des miséricordes, et le Dieu de toute consolation;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Qui nous console dans toute notre affliction, afin que par la consolation dont nous sommes nous-mêmes consolés de Dieu, nous puissions consoler ceux qui sont en quelque affliction que ce soit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Car comme les souffrances de Christ abondent en nous, de même notre consolation abonde aussi par Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Et soit que nous soyons affligés, c’est pour votre consolation et pour votre salut, qui se produit en endurant les mêmes souffrances que nous endurons aussi; soit que nous soyons consolés, c’est pour votre consolation et pour votre salut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'Or l’espérance que nous avons de vous est ferme, sachant que comme vous êtes participants des souffrances, de même aussi vous le serez de la consolation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Car mes frères, nous voulons bien que vous sachiez notre affliction, qui nous est arrivée en Asie, c’est que nous avons été chargés excessivement au-delà de ce que nous pouvions porter; tellement que nous avions perdu l’espérance de conserver notre vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Car nous nous sommes vus comme si nous eussions reçu en nous-mêmes la sentence de mort; afin que nous n’eussions point de confiance en nous-mêmes, mais en Dieu qui ressuscite les morts;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Et qui nous a délivrés d’une si grande mort, et qui nous en délivre; et en qui nous espérons qu’il nous en délivrera aussi à l’avenir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Etant aussi aidés par la prière que vous faites pour nous, afin que des actions de grâces soient rendues pour nous par plusieurs personnes, à cause du don qui nous aura été fait en faveur de plusieurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Car c’est ici notre gloire, savoir le témoignage de notre conscience, de ce qu’en simplicité et sincérité de Dieu, et non point avec une sagesse charnelle, mais selon la grâce de Dieu, nous avons conversé dans le monde, et particulièrement avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Car nous ne vous écrivons point d’autres choses que celles que vous lisez, et que même vous connaissez; et j’espère que vous les reconnaîtrez aussi jusqu’à la fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Selon que vous avez reconnu en partie, que nous sommes votre gloire, comme vous êtes aussi la nôtre pour le jour du Seigneur Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Et dans une telle confiance je voulais premièrement aller vers vous, afin que vous eussiez une seconde grâce;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'Et passer de chez vous en Macédoine, puis de Macédoine revenir vers vous, et être conduit par vous en Judée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Or quand je me proposais cela, ai-je usé de légèreté? ou les choses que je pense, les pensé-je selon la chair, en sorte qu’il y ait eu en moi le oui et le non?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Mais Dieu est fidèle, que notre parole de laquelle j’ai usé envers vous, n’a point été oui, et non.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Car le Fils de Dieu Jésus-Christ, qui a été prêché par nous entre vous, savoir par moi, et par Silvain, et par Timothée, n’a point été oui, et non; mais il a été oui en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Car tout autant qu’il y a de promesses de Dieu, elles sont oui en lui, et amen en lui, à la gloire de Dieu par nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Or celui qui nous affermit avec vous en Christ, et qui nous a oints, c’est Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'Qui aussi nous a scellés, et nous a donné les arrhes de l’Esprit en nos coeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Or j’appelle Dieu à témoin sur mon âme, que ç’a été pour vous épargner que je ne suis pas encore allé à Corinthe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Non que nous dominions sur votre foi, mais nous contribuons à votre joie; puisque vous êtes demeurés fermes dans la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Mais j’avais résolu en moi-même de ne revenir point chez vous avec tristesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Car si je vous attriste, qui est-ce qui me réjouira, à moins que ce ne soit celui que j’aurai moi-même affligé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Et je vous ai même écrit ceci, afin que quand j’arriverai, je n’aie point de tristesse de la part de ceux de qui je devais recevoir de la joie, m’assurant de vous tous que ma joie est celle de vous tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'car je vous ai écrit dans une grande affliction et angoisse de coeur, avec beaucoup de larmes; non afin que vous fussiez attristés, mais afin que vous connussiez la charité toute particulière que j’ai pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Que si quelqu’un été cause de cette tristesse, ce n’est pas moi seul qu’il a affligé, mais en quelque sorte (afin que je ne le surcharge point) c’est vous tous qu’il a attristés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'C’est assez pour un tel homme, de cette censure qui lui a été faite par plusieurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'De sorte que vous devez plutôt lui faire grâce, et le consoler; afin qu’un tel homme ne soit point accablé par une trop grande tristesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'C’est pourquoi je vous prie de ratifier envers lui votre charité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Car c’est aussi pour cela que je vous ai écrit, afin de vous éprouver, et de connaître si vous êtes obéissants en toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Or à celui à qui vous pardonnez quelque chose, je pardonne aussi: car de ma part aussi si j’ai pardonné quelque chose à celui à qui j’ai pardonné, je l’ai fait à cause de vous, devant la face de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'Afin que Satan n’ait pas le dessus sur nous: car nous n’ignorons pas ses machinations.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Au reste, étant venu à Troas pour l’Évangile de Christ, quoique la porte m’y fût ouverte par le Seigneur,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'Je n’ai pourtant point eu de relâche en mon esprit, parce que je n’ai pas trouvé Tite mon frère; mais ayant pris congé d’eux, je m’en suis venu en Macédoine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Or grâces soient rendues à Dieu, qui nous fait toujours triompher en Christ, et qui manifeste par nous l’odeur de sa connaissance en tous lieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Car nous sommes la bonne odeur de Christ de la part de Dieu, en ceux qui sont sauvés, et en ceux qui périssent:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'A ceux-ci, une odeur mortelle qui les tue; et à ceux-là, une odeur vivifiante qui les conduit à la vie. Mais qui est suffisant pour ces choses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Car nous ne falsifions pas la parole de Dieu, comme font plusieurs; mais nous parlons de Christ avec sincérité, comme de la part de Dieu, et devant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Commençons-nous de nouveau à nous recommander nous-mêmes? ou avons-nous besoin, comme quelques-uns, de Lettres de recommandation envers vous, ou de Lettres de recommandation de votre part?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Vous êtes vous-mêmes notre Epître, écrite dans nos coeurs, connue et lue de tous les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Car il paraît en vous que vous êtes l’Epître de Christ, dressée par notre ministère, et écrite non avec de l’encre, mais par l’Esprit du Dieu vivant; non sur des tables de pierre, mais sur les tables charnelles du coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Or nous avons une telle confiance en Dieu par Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Non que nous soyons capables de nous-mêmes de penser quelque chose, comme de nous-mêmes, mais notre capacité vient de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'Qui nous a aussi rendus capables d’être les ministres du Nouveau Testament, non de la lettre, mais de l’esprit; car la lettre tue, mais l’Esprit vivifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Or si le ministère de mort, écrit avec des lettres, et gravé sur des pierres, a été glorieux, tellement que les enfants d’Israël ne pouvaient regarder le visage de Moïse, à cause de la gloire de son visage, laquelle devait prendre fin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'Comment le ministère de l’Esprit ne sera-t-il pas plus glorieux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Car si le ministère de la condamnation a été glorieux, le ministère de la justice le surpasse de beaucoup en gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Et même le premier ministère qui a été glorieux, ne l’a pas été autant que le second qui l’emporte de beaucoup en gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Car si ce qui devait prendre fin a été glorieux, ce qui est permanent est beaucoup plus glorieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Ayant donc une telle espérance, nous usons d’une grande hardiesse de parler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'Et nous ne sommes pas comme Moïse, qui mettait un voile sur son visage, afin que les enfants d’Israël ne regardassent point à la consommation de ce qui devait prendre fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Mais leurs entendements sont endurcis; car jusqu’à aujourd’hui ce même voile qui est aboli par Christ, demeure dans la lecture de l’Ancien Testament, sans être ôté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Mais jusqu’à aujourd’hui quand on lit Moïse, le voile demeure sur leur coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Mais quand il se sera converti au Seigneur, le voile sera ôté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Or le Seigneur est cet Esprit-là; et où est l’Esprit du Seigneur, là est la liberté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Ainsi nous tous qui contemplons, comme en un miroir, la gloire du Seigneur à face découverte, nous sommes transformés en la même image de gloire en gloire, comme par l’Esprit du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'C’est pourquoi ayant ce Ministère selon la miséricorde que nous avons reçue, nous ne nous relâchons point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Mais nous avons entièrement rejeté les choses honteuses que l’on cache, ne marchant point avec ruse, et ne falsifiant point la parole de Dieul, mais nous rendant approuvés à toute conscience des hommes devant Dieu, par la manifestation de la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Que si notre Évangile est encore voilé, il ne l’est que pour ceux qui périssent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'Desquels le Dieu de ce siècle a aveuglé les entendements, c’est-à- dire, des incrédules, afin que la lumière de l’Évangile de la gloire de Christ, lequel est l’image de Dieu, ne leur resplendît point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Car nous ne nous prêchons pas nous-mêmes, mais nous prêchons Jésus-Christ le Seigneur; et nous déclarons que nous sommes vos serviteurs pour l’amour de Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Car Dieu qui a dit que la lumière resplendît des ténèbres, est celui qui a relui dans nos coeurs, pour manifester la connaissance de la gloire de Dieu qui se trouve en Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Mais nous avons ce trésor dans des vaisseaux de terre, afin que l’excellence de cette force soit de Dieu, et non pas de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Étant affligés à tous égards, mais non pas réduits entièrement à l’étroit; étant en perplexité, mais non pas sans secours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'Etant persécutés, mais non pas abandonnés; étant abattus, mais non pas perdus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Portant toujours partout en notre corps, la mort du Seigneur Jésus, afin que la vie de Jésus soit aussi manifestée en notre corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Car nous qui vivons, nous sommes toujours livrés à la mort pour l’amour de Jésus, afin que la vie de Jésus soit aussi manifestée en notre chair mortelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'De sorte que la mort se déploie en nous, mais la vie en vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Or ayant un même esprit de foi, selon qu’il est écrit: j’ai cru, c’est pourquoi j’ai parlé; nous croyons aussi, et c’est aussi pourquoi nous parlons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'Sachant que celui qui a ressuscité le Seigneur Jésus, nous ressuscitera aussi par Jésus, et nous fera comparaître en sa présence avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Car toutes choses sont pour vous, afin que cette grande grâce abonde à la gloire de Dieu, par le remerciement de plusieurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'C’est pourquoi nous ne nous relâchons point; mais quoique notre homme extérieur déchée, toutefois l’intérieur est renouvelé de jour en jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Car notre légère affliction, qui ne fait que passer, produit en nous un poids éternel d’une gloire souverainement excellente:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'Quand nous ne regardons point aux choses visibles, mais aux invisibles; car les choses visibles ne sont que pour un temps, mais les invisibles sont éternelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Car nous savons que si notre habitation terrestre de cette tente est détruite, nous avons un édifice de par Dieu, savoir une maison éternelle dans les Cieux, qui n’est point faite de main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Car c’est aussi pour cela que nous gémissons, désirant avec ardeur d’être revêtus de notre domicile, qui est du Ciel:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'Si toutefois nous sommes trouvés vêtus, et non point nus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Car nous qui sommes dans cette tente, nous gémissons étant chargés; vu que nous désirons, non pas d’être dépouillés, mais d’être revêtus; afin que ce qui est mortel, soit absorbé par la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Or celui qui nous a formés à cela même, c’est Dieu; qui aussi nous a donné les arrhes de l’Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Nous avons donc toujours confiance; et nous savons que logeant dans ce corps, nous sommes absents du Seigneur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'Car nous marchons par la foi, et non par la vue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Nous avons, dis-je, de la confiance, et nous aimons mieux être absents de ce corps, et être avec le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'C’est pourquoi aussi nous nous efforçons de lui être agréables, et présents, et absents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Car il nous faut tous comparaître devant le Tribunal de Christ, afin que chacun remporte en son corps selon ce qu’il aura fait, soit bien, soit mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Connaissant donc combien le Seigneur doit être craint, nous sollicitons les hommes à la foi, et nous sommes manifestés à Dieu, et je m’attends aussi que nous sommes manifestés en vos consciences.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Car nous ne nous recommandons pas de nouveau à vous, mais nous vous donnons occasion de vous glorifier de nous; afin que vous ayez de quoi répondre à ceux qui se glorifient de l’apparence, et non pas du coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Car soit que nous soyons dans l’extase nous sommes unis à Dieu; soit que nous soyons de sens rassis, nous le sommes à vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Parce que la charité de Christ nous unit étroitement, tenant ceci pour certain, que si un est mort pour tous, tous aussi sont morts;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'Et qu’il est mort pour tous, afin que ceux qui vivent, ne vivent point dorénavant pour eux-mêmes, mais pour celui qui est mort et ressuscité pour eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'C’est pourquoi dès à présent nous ne connaissons personne selon la chair, même quoique nous ayons connu Christ selon la chair, toutefois nous ne le connaissons plus ainsi maintenant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Si donc quelqu’un est en Christ, il est une nouvelle créature; les choses vieilles sont passées; voici, toutes choses sont faites nouvelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Or tout cela vient de Dieu, qui nous a réconciliés avec lui par Jésus-Christ, et qui nous a donné le Ministère de la réconciliation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Car Dieu était en Christ réconciliant le monde avec soi, en ne leur imputant point leurs péchés, et il a mis en nous la parole de la réconciliation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Nous sommes donc ambassadeurs pour Christ, et c’est comme si Dieu vous exhortait par notre ministère; nous vous supplions donc pour l’amour de Christ, de vous réconcilier avec Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Car il a fait celui qui n’a point connu de péché, être péché pour nous, afin que nous fussions justice de Dieu en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Ainsi donc étant ouvriers avec lui, nous vous prions aussi que vous n’ayez point reçu la grâce de Dieu en vain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Car il dit: je t’ai exaucé au temps favorable et t’ai secouru au jour du salut; voici maintenant le temps favorable, voici maintenant le jour du salut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Ne donnant aucun scandale en quoi que ce soit, afin que notre ministère ne soit point blâmé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Mais nous rendant recommandables, en toutes choses, comme ministres de Dieu, en grande patience, en afflictions, en nécessités, en angoisses,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'En blessures, en prisons, en troubles, en travaux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'En veilles, en jeûnes, en pureté; par la connaissance, par un esprit patient, par la douceur, par le Saint-Esprit, par une charité sincère,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'Par la parole de la vérité, par la puissance de Dieu, par les armes de justice que l’on porte à la main droite et à la main gauche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'Parmi l’honneur et l’ignominie, parmi la calomnie et la bonne réputation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'Comme séducteurs, et toutefois étant véritables; comme inconnus, et toutefois étant reconnus; comme mourants, et voici nous vivons; comme châtiés, et toutefois non mis à mort;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'Comme attristés, et toutefois toujours joyeux; comme pauvres, et toutefois enrichissant plusieurs; comme n’ayant rien, et toutefois possédant toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Ô Corinthiens! notre bouche est ouverte pour vous, notre coeur s’est élargi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Vous n’êtes point à l’étroit au-dedans de nous, mais vous êtes à l’étroit dans vos entrailles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Or pour nous traiter de la même manière (je vous parle comme à mes enfants) élargissez-vous aussi à notre égard.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Ne portez pas un même joug avec les infidèles; car quelle participation y a-t-il de la justice avec l’iniquité? et quelle communication y a-t-il de la lumière avec les ténèbres?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Et quel accord y a-t-il de Christ avec Bélial? ou quelle part a le fidèle avec l’infidèle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Et quelle convenance y a-t-il du Temple de Dieu avec les idoles? car vous êtes le Temple du Dieu vivant, selon ce que Dieu a dit: j’habiterai au milieu d’eux, et j’y marcherai; et je serai leur Dieu, et ils seront mon peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'C’est pourquoi sortez du milieu d’eux, et vous en séparez, dit le Seigneur; et ne touchez à aucune chose souillée et je vous recevrai;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'Et je vous serai pour père, et vous me serez pour fils et pour filles, dit le Seigneur Tout-puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Or donc mes bien-aimés, puisque nous avons de telles promesses, nettoyons-nous de toute souillure de la chair et de l’esprit perfectionnant la sanctification en la crainte de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Recevez-nous, nous n’avons fait tort à personne, nous n’avons corrompu personne, nous n’avons pillé personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Je ne dis point ceci pour vous condamner: car je vous ai déjà dit que vous êtes dans nos coeurs à mourir et à vivre ensemble.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'J’ai une grande liberté envers vous, j’ai grand sujet de me glorifier de vous; je suis rempli de consolation, je suis plein de joie dans toute notre affliction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Car après être venus en Macédoine, notre chair n’a eu aucun relâche, mais nous avons été affligés en toutes manières; ayant eu des combats au dehors, et des craintes au dedans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Mais Dieu qui console les abattus, nous a consolés par la venue de Tite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'Et non seulement par sa venue, mais aussi par la consolation qu’il a reçue de vous; car il nous a raconté votre grand désir, vos larmes, votre affection ardente envers moi; de sorte que je m’en suis extrêmement réjoui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Car bien que je vous aie attristés par mon Epître, je ne m’en repens point, quoique je m’en fusse déjà repenti, parce que je vois que si cette Epître vous a affligés, ce n’a été que pour peu de temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Je me réjouis donc maintenant, non de ce que vous avez été affligés, mais de ce que vous avez été attristés à repentance; car vous avez été attristés selon Dieu, de sorte que vous n’avez reçu aucun dommage de notre part.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Puisque la tristesse qui est selon Dieu, produit une repentance à salut, dont on ne se repent jamais; mais la tristesse de ce monde produit la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Car voici, cela même que vous avez été attristés selon Dieu, quel soin n’a-t-il pas produit en vous? quelle satisfaction? quelle indignation? quelle crainte? quel grand désir? quel zèle? quelle vengeance? vous vous êtes montrés de toutes manières purs dans cette affaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Quoi que je vous aie donc écrit, ce n’a point été à cause de celui qui a commis la faute, ni à cause de celui envers qui elle a été commise, mais pour faire voir parmi vous le soin que j’ai de vous devant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'C’est pourquoi nous avons été consolés de ce que vous avez fait pour notre consolation; mais nous nous sommes encore plus réjouis de la joie qu’a eu Tite, en ce que son esprit a été recréé par vous tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Parce que si en quelque chose je me suis glorifié de vous dans ce que je lui en ai dit, je n’en ai point eu de confusion; mais comme nous vous avons dit toutes choses selon la vérité, ainsi ce dont je m’étais glorifié de vous dans ce que j’en ai dit à Tite, s’est trouvé être la vérité même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'C’est pourquoi quand il se souvient de l’obéissance de vous tous, et comment vous l’avez reçu avec crainte et tremblement; son affection pour vous en est beaucoup plus grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Je me réjouis donc de ce qu’en toutes choses je me puis assurer de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Au reste, mes frères, nous voulons vous faire connaître la grâce que Dieu a faite aux Églises de Macédoine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'C’est qu’au milieu de leur grande épreuve d’affliction, leur joie a été augmentée, et que leur profonde pauvreté s’est répandue en richesses par leur prompte libéralité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Car je suis témoin qu’ils ont été volontaires à donner selon leur pouvoir, et même au delà de leur pouvoir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'Nous pressant avec de grandes prières de recevoir la grâce et la communication de cette contribution en faveur des Saints:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'Et ils n’ont pas fait seulement comme nous l’avions espéré, mais ils se sont donnés premièrement eux-mêmes au Seigneur, et puis à nous, par la volonté de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Afin que nous exhortassions Tite, que comme il avait auparavant commencé, il achevât aussi cette grâce envers vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'C’est pourquoi comme vous abondez en toutes choses, en foi, en parole, en connaissance, en toute diligence, et en la charité que vous avez pour nous, faites que vous abondiez aussi en cette grâce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Je ne le dis point par commandement, mais pour éprouver aussi par la diligence des autres la sincérité de votre charité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Car vous connaissez la grâce de notre Seigneur Jésus-Christ, qui étant riche, s’est rendu pauvre pour vous; afin que par sa pauvreté vous fussiez rendus riches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Et en cela je vous donne cet avis, parce qu’il vous est convenable, qu’ayant non seulement déjà commencé d’agir pour cette Collecte, mais en ayant même eu la volonté dès l’année passée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Vous acheviez maintenant de la faire; afin que comme vous avez été prompts à en avoir la volonté; vous l’accomplissiez aussi selon votre pouvoir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Car si la promptitude de la volonté précède, on est agréable selon ce qu’on a, et non point selon ce qu’on n’a pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Or ce n’est pas afin que les autres soient soulagés, et que vous soyez foulés; mais afin que ce soit par égalité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'Que votre abondance donc supplée maintenant à leur indigence, afin que leur abondance serve aussi à votre indigence, et qu’ainsi il y ait de l’égalité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'Selon ce qui est écrit: celui qui avait beaucoup, n’a rien eu de superflu; et celui qui avait peu, n’en a pas eu moins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Or grâces soient rendues à Dieu qui a mis le même soin pour vous au coeur de Tite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Lequel a fort bien reçu mon exhortation, et étant lui-même fort affectionné, il s’en est allé vers vous de son propre mouvement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Et nous avons aussi envoyé avec lui le frère dont la louange, qu’il s’est acquise dans la prédication de l’Évangile est répandue par toutes les Églises:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, '(Et non seulement cela, mais aussi il a été établi par les Églises notre compagnon de voyage, pour cette grâce qui est administrée par nous à la gloire du Seigneur même, et pour servir à la promptitude de votre zèle.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Nous donnant garde que personne ne nous reprenne dans cette abondance qui est administrée par nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'Et procurant ce qui est bon, non seulement devant le Seigneur, mais aussi devant les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Nous avons envoyé aussi avec eux notre autre frère, que nous avons souvent éprouvé en plusieurs choses être diligent, et maintenant encore beaucoup plus diligent, à cause de la grande confiance qu’il a en vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Ainsi donc quant à Tite, il est mon associé et mon compagnon d’oeuvre envers vous; et quant à nos frères, ils sont les envoyés des Églises, et la gloire de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Montrez donc envers eux et devant les Églises une preuve de votre charité, et du sujet que nous avons de nous glorifier de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Car de vous écrire touchant la collecte qui se fait pour les Saints, ce me serait une chose superflue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Vu que je sais la promptitude de votre zèle, en quoi je me glorifie de vous devant ceux de Macédoine, leur faisant entendre que l’Achaïe est prête dès l’année passée; et votre zèle en a excité plusieurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Or j’ai envoyé ces frères, afin que ce en quoi je me suis glorifié de vous, ne soit pas vain en cette occasion, et que vous soyez prêts, comme j’ai dit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'De peur que ceux de Macédoine venant avec moi, et ne vous trouvant pas prêts, nous n’ayons de la honte, (pour ne pas dire vous-mêmes) de l’assurance avec laquelle nous nous sommes glorifiés de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'C’est pourquoi j’ai estimé qu’il était nécessaire de prier les frères d’aller premièrement vers vous, et d’achever de préparer votre bénéficence que vous avez déjà promise; afin qu’elle soit prête comme une bénéficence, et non pas comme une chicheté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Or je vous dis ceci: que celui qui sème chichement, recueillera aussi chichement; et que celui qui sème libéralement, recueillera aussi libéralement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Mais que chacun contribue selon qu’il se l’est proposé en son coeur, non point à regret, ou par contrainte; car Dieu aime celui qui donne gaiement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Et Dieu est puissant pour faire abonder toute grâce en vous, afin qu’ayant toujours tout ce qui suffit en toute chose, vous soyez abondants en toute bonne oeuvre:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'Selon ce qui est écrit: il a répandu, il a donné aux pauvres; sa justice demeure éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Or celui qui fournit de la semence au semeur, veuille aussi vous donner du pain à manger, et multiplier votre semence, et augmenter les revenus de votre justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'Etant pleinement enrichis pour exercer une parfaite libéralité, laquelle fait que nous en rendons grâces à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Car l’administration de cette oblation n’est pas seulement suffisante pour subvenir aux nécessités des Saints, mais elle abonde aussi de telle sorte, que plusieurs ont de quoi en rendre grâces à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Glorifiant Dieu pour l’épreuve qu’ils font de cette assistance, en ce que vous vous soumettez à l’Évangile de Christ; et de votre prompte et libérale communication envers eux, et envers tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'Ils prient Dieu pour vous, et ils vous aiment très affectueusement à cause de la grâce excellente que Dieu vous a accordée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Or grâces soient rendues à Dieu à cause de son don inexprimable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Au reste, moi Paul, je vous prie par la douceur et la débonnaireté de Christ, moi qui m’humilie lorsque je suis en votre présence, mais qui étant absent suis hardi à votre égard.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'Je vous prie, dis-je, que lorsque je serai présent il ne faille point que j’use de hardiesse, par cette assurance de laquelle je me propose de me porter hardiment envers quelques-uns, qui nous regardent comme marchant selon la chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Mais en marchant en la chair, nous ne combattons pas selon la chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'Car les armes de notre guerre ne sont pas charnelles, mais elles sont puissantes par la vertu de Dieu, pour la destruction des forteresses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'Détruisant les conseils, et toute hauteur qui s’élève contre la connaissance de Dieu, et amenant toute pensée prisonnière à l’obéissance de Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'Et ayant la vengeance toute prête contre toute désobéissance, après que votre obéissance aura été entière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Considérez-vous les choses selon l’apparence? Si quelqu’un se confie en soi-même d’être à Christ; qu’il pense encore cela en soi- même, que comme il est à Christ, nous aussi nous sommes à Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Car si même je veux me glorifier davantage de notre puissance, laquelle le Seigneur nous a donnée pour l’édification, et non pas pour votre destruction, je n’en recevrai point de honte;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'Afin qu’il ne semble pas que je veuille vous épouvanter par mes Lettres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Car mes Lettres (disent-ils) sont bien graves et fortes, mais la présence du corps est faible, et la parole est méprisable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Que celui qui est tel, considère que tels que nous sommes de parole par nos Lettres, étant absents, tels aussi nous sommes de fait, étant présents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Car nous n’osons pas nous joindre ni nous comparer à quelques-uns, qui se recommandent eux-mêmes; mais ils ne comprennent pas qu’ils se mesurent eux-mêmes par eux-mêmes, et qu’ils se comparent eux-mêmes à eux-mêmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Mais pour nous, nous ne nous glorifierons point de ce qui n’est pas de notre mesure; mais selon la mesure réglée, laquelle mesure Dieu nous a départie, nous nous glorifierons d’être parvenus même jusqu’à vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Car nous ne nous étendons pas nous-mêmes plus qu’il ne faut, comme si nous n’étions point parvenus jusqu’à vous; vu que nous sommes parvenus même jusqu’à vous par la prédication de l’Évangile de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'Ne nous glorifiant point dans ce qui n’est point de notre mesure, c’est-à-dire, dans les travaux d’autrui; mais nous avons espérance que votre foi venant à croître en vous, nous serons amplement accrus dans ce qui nous a été départi selon la mesure réglée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'Jusques à évangéliser dans les lieux qui sont au delà de vous; et non pas à nous glorifier dans ce qui a été départi aux autres selon la mesure réglée, dans les choses déjà toutes préparées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Mais que celui qui se glorifie, se glorifie au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Car ce n’est pas celui qui se loue soi-même, qui est approuvé, mais c’est celui que le Seigneur loue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Plût à Dieu que vous me supportassiez un peu dans mon imprudence; mais encore supportez-moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Car je suis jaloux de vous d’une jalousie de Dieu; parce que je vous ai unis à un seul mari, pour vous présenter à Christ comme une vierge chaste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Mais je crains, que comme le serpent séduisit Eve par sa ruse, vos pensées aussi ne se corrompent, en se détournant de la simplicité qui est en Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Car si quelqu’un venait qui vous prêchât un autre Jésus que nous n’avons prêché; ou si vous receviez un autre Esprit que celui que vous avez reçu, ou un autre Evangile que celui que vous avez reçu, feriez-vous bien de l’endurer?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Mais j’estime que je n’ai été en rien moindre que les plus excellents Apôtres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Que si je suis comme quelqu’un du vulgaire par rapport au langage, je ne le suis pourtant pas en connaissance; mais nous avons été entièrement manifestés en toutes choses envers vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Ai-je commis une faute en ce que je me suis abaissé moi-même, afin que vous fussiez élevés, parce que sans rien prendre je vous ai annoncé l’Évangile de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'J’ai dépouillé les autres Églises, prenant de quoi m’entretenir pour vous servir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Et lorsque j’étais avec vous, et que j’ai été en nécessité, je ne me suis point relâché du travail afin de n’être à charge à personne; car les frères qui étaient venus de Macédoine ont suppléé à ce qui me manquait; et je me suis gardé de vous être à charge en aucune chose, et je m’en garderai encore.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'La vérité de Christ est en moi, que cette gloire ne me sera point ravie dans les contrées de l’Achaïe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Pourquoi? est-ce parce que je ne vous aime point? Dieu le sait!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Mais ce que je fais, je le ferai encore, pour retrancher l’occasion à ceux qui cherchent l’occasion; afin qu’en ce de quoi ils se glorifient, ils soient aussi trouvés tout tels que nous sommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Car tels faux Apôtres sont des ouvriers trompeurs, qui se déguisent en Apôtres de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'Et cela n’est pas étonnant: car satan lui-même se déguise en Ange de lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Ce n’est donc pas un grand sujet d’étonnement si ses ministres aussi se déguisent en ministres de justice; mais leur fin sera conforme à leurs oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Je le dis encore, afin que personne ne pense que je sois imprudent; ou bien supportez-moi comme un imprudent, afin que je me glorifie aussi un peu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Ce que je vais dire, en rapportant les sujets que j’aurais de me glorifier, je ne le dirai pas selon le Seigneur, mais comme par imprudence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Puis donc que plusieurs se vantent selon la chair, je me vanterai moi aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Car vous souffrez volontiers les imprudents, parce que vous êtes sages.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Même si quelqu’un vous asservit, si quelqu’un vous mange, si quelqu’un prend votre bien, si quelqu’un s’élève sur vous, si quelqu’un vous frappe au visage, vous le souffrez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Je le dis avec honte, même comme si nous avions été sans aucune force; mais si en quelque chose quelqu’un ose se glorifier (je parle en imprudent) j’ai la même hardiesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Sont-ils Hébreux? je le suis aussi. Sont-ils Israélites? je le suis aussi. Sont-ils de la semence d’Abraham? je le suis aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Sont-ils ministres de Christ? (je parle comme un imprudent) je le suis plus qu’eux; en travaux davantage, en blessures plus qu’eux, en prison davantage, en morts plusieurs fois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'J’ai reçu des Juifs par cinq fois quarante coups, moins un.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'J’ai été battu de verges trois fois; j’ai été lapidé une fois; j’ai fait naufrage trois fois; j’ai passé un jour et une nuit en la profonde mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'En voyages souvent, en périls des fleuves, en périls des brigands, en périls de ma nation, en périls des Gentils, en périls dans les villes, en périls dans les déserts, en périls en mer, en périls parmi de faux frères;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'En peine et en travail, en veilles souvent, en faim et en soif, en jeûnes souvent, dans le froid et dans la nudité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Outre les choses de dehors ce qui me tient assiégé tous les jours, c’est le soin que j’ai de toutes les Églises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Qui est-ce qui est affaibli, que je ne sois aussi affaibli? qui est-ce qui est scandalisé, que je n’en sois aussi brûlé?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'S’il faut se glorifier, je me glorifierai des choses qui sont de mon infirmité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Dieu, qui est le Père de notre Seigneur Jésus-Christ, et qui est béni éternellement, sait que je ne mens point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'A Damas, le Gouverneur pour le roi Arétas avait mis des gardes dans la ville des Damascéniens pour me prendre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'Mais on me descendit de la muraille dans une corbeille par une fenêtre, et ainsi j’échappai de ses mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Certes il ne m’est pas convenable de me glorifier: car je viendrai jusqu’aux visions et aux révélations du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Je connais un homme en Christ il y a quatorze ans passés, (si ce fut en corps je ne sais; si ce fut hors du corps, je ne sais; Dieu le sait), qui a été ravi jusques au troisième Ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'Et je sais qu’un tel homme (si ce fut en corps, ou si ce fut hors du corps, je ne sais; Dieu le sait),');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'A été ravi en paradis, et a ouï des secrets qu’il n’est pas permis à l’homme de révéler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Je ne me glorifierai point d’un tel homme, mais je ne me glorifierai point de moi-même, sinon dans mes infirmités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Or quand je voudrais me glorifier, je ne serais point imprudent, car je dirais la vérité; mais je m’en abstiens, afin que personne ne m’estime au-dessus de ce qu’il me voit être, ou de ce qu’il entend dire de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'Mais de peur que je ne m’élevasse à cause de l’excellence des révélations, il m’a été mis une écharde en la chair, un ange de satan pour me souffleter, ça été, dis-je, afin que je ne m’élevasse point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'C’est pourquoi j’ai prié trois fois le Seigneur, de faire que cet ange de satan se retirât de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Mais le Seigneur m’a dit: ma grâce te suffit: car ma vertu manifeste sa force dans l’infirmité. Je me glorifierai donc très volontiers plutôt dans mes infirmités; afin que la vertu de Christ habite en moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Et à cause de cela je prends plaisir dans les infirmités, dans les injures, dans les nécessités, dans les persécutions, et dans les angoisses pour Christ: car quand je suis faible, c’est alors que je suis fort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'J’ai été imprudent en me glorifiant; mais vous m’y avez contraint, car je devais être recommandé par vous, vu que je n’ai été moindre en aucune chose que les plus excellents Apôtres, quoique je ne sois rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Certainement les marques de mon Apostolat ont été efficaces parmi vous avec toute patience, par des signes, des prodiges et des miracles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Car en quoi avez-vous été inférieurs aux autres Églises, sinon en ce que je ne suis point devenu lâche au travail à votre préjudice? Pardonnez-moi ce tort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Voici pour la troisième fois que je suis prêt d’aller vers vous; et je ne m’épargnerai pas à travailler, pour ne vous être point à charge; car je ne demande pas votre bien, mais c’est vous-mêmes que je demande; aussi ce ne sont pas les enfants qui doivent faire amas pour leurs pères, mais les pères pour leurs enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Et quant à moi, je dépenserai très volontiers, et je serai même dépensé pour vos âmes; bien que vous aimant beaucoup plus, je sois moins aimé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Mais soit, dira-t-on, que je ne vous aie point été à charge, mais qu’étant rusé, je vous aie pris par finesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Ai-je donc fait mon profit de vous par aucun de ceux que je vous ai envoyés?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'J’ai prié Tite, et j’ai envoyé un de nos frères avec lui; mais Tite a-t-il fait son profit de vous? Et n’avons-nous pas lui et moi marché d’un même esprit? N’ avons-nous pas marché sur les mêmes traces?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Avez-vous encore la pensée que nous voulions nous justifier envers vous? Nous parlons devant Dieu en Christ, et le tout, ô très chers! est pour votre édification.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Car je crains qu’il n’arrive que quand je viendrai, je ne vous trouve point tels que je voudrais, et que je sois trouvé de vous tel que vous ne voudriez pas, et qu’il n’y ait en quelque sorte parmi vous des querelles, des envies, des colères, des débats, des médisances, des murmures, des enflures d’orgueil, des désordres et des séditions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Et qu’étant revenu chez vous, mon Dieu ne m’humilie sur votre sujet, en sorte que je sois affligé à l’occasion de plusieurs de ceux qui ont péché auparavant, et qui ne se sont point repentis de l’impureté, de la fornication, et de l’impudicité dont ils se sont rendus coupables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'C’est ici la troisième fois que je viens à vous: en la bouche de deux ou de trois témoins toute parole sera confirmée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Je l’ai déjà dit, et je le dis encore comme si j’étais présent pour la seconde fois, et maintenant étant absent, j’écris à ceux qui ont péché auparavant, et à tous les autres, que si je viens encore une fois, je n’épargnerai personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Puisque vous cherchez la preuve que Christ parle par moi, lequel n’est point faible envers vous, mais qui est puissant en vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Car quoiqu’il ait été crucifié par infirmité, il est néanmoins vivant par la puissance de Dieu; et nous aussi nous souffrons diverses infirmités à cause de lui, mais nous vivrons avec lui par la puissance que Dieu a déployée envers vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Examinez-vous vous-mêmes pour savoir si vous êtes en la foi; éprouvez-vous vous-mêmes; ne reconnaissez-vous point vous-mêmes, savoir que Jésus-Christ est en vous? si ce n’est qu’en quelque sorte vous fussiez réprouvés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Mais j’espère que vous connaîtrez que pour nous, nous ne sommes point réprouvés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Or je prie Dieu que vous ne fassiez aucun mal; non afin que nous soyons trouvés approuvés, mais afin que vous fassiez ce qui est bon, et que nous soyons comme réprouvés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Car nous ne pouvons rien contre la vérité, mais pour la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Or nous nous réjouissons si nous sommes faibles, et que vous soyez forts; et même nous souhaitons ceci, c’est à savoir votre entier accomplissement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'C’est pourquoi j’écris ces choses étant absent, afin que quand je serai présent, je n’use point de rigueur, selon la puissance que le Seigneur m’a donnée, pour l’édification, et non point pour la destruction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Au reste, mes frères, réjouissez-vous, tendez à vous rendre parfaits, soyez consolés, soyez tous d’un consentement, vivez en paix, et le Dieu de charité et de paix sera avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Saluez-vous l’un l’autre par un saint baiser. Tous les Saints vous saluent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Que la grâce du Seigneur Jésus-Christ, et la charité de Dieu, et la communication du Saint-Esprit soit avec vous tous; Amen! ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paul Apôtre, non de la part des hommes, ni de la part d’aucun homme, mais de la part de Jésus-Christ, et de la part de Dieu le Père, qui l’a ressuscité des morts;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'Et tous les frères qui sont avec moi, aux Eglises de Galatie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Que la grâce et la paix vous soient données de la part de Dieu le Père, et de la part de notre Seigneur Jésus-Christ:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'Qui s’est donné lui-même pour nos péchés, afin que selon la volonté de Dieu notre Père, il nous retirât du présent siècle mauvais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'A lui soit gloire aux siècles des siècles; Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Je m’étonne qu’abandonnant Jésus- Christ, qui vous avait appelés par sa grâce, vous ayez été si promptement transportés à un autre Evangile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Qui n’est pas un autre Evangile, mais il y a des gens qui vous troublent, et qui veulent renverser l’Evangile de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Mais quand nous-mêmes vous évangéliserions, ou quand un Ange du Ciel vous évangéliserait outre ce que nous vous avons évangélisé, qu’il soit anathème.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Comme nous l’avons déjà dit, je le dis encore maintenant: si quelqu’un vous évangélise outre ce que vous avez reçu, qu’il soit anathème.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Car maintenant prêché-je les hommes, ou Dieu? ou cherché-je à complaire aux hommes? Certes si je complaisais encore aux hommes, je ne serais pas le serviteur de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Or mes frères, je vous déclare que l’Evangile que j’ai annoncé, n’est point selon l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Parce que je ne l’ai point reçu ni appris d’aucun homme, mais par la révélation de Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Car vous avez appris quelle a été autrefois ma conduite dans le Judaïsme, et comment je persécutais à outrance l’Eglise de Dieu, et la ravageais;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'Et j’avançais dans le Judaïsme plus que plusieurs de mon âge dans ma nation; étant le plus ardent zélateur des traditions de mes pères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Mais quand ç’a été le bon plaisir de Dieu, qui m’avait choisi dès le ventre de ma mère, et qui m’a appelé par sa grâce,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'De révéler son Fils en moi, afin que je l’évangélisasse parmi les Gentils, je ne commençai pas d’abord par prendre conseil de la chair et du sang;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'Et je ne retournai point à Jérusalem vers ceux qui avaient été Apôtres avant moi, mais je m’en allai en Arabie, et je repassai à Damas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Puis je retournai trois ans après à Jérusalem pour visiter Pierre, et je demeurai chez lui quinze jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Et je ne vis aucun des autres Apôtres, sinon Jacques, le frère du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Or dans les choses que je vous écris, voici, je vous dis devant Dieu, que je ne mens point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'J’allai ensuite dans les pays de Syrie et de Cilicie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Or j’étais inconnu de visage aux Eglises de Judée qui étaient en Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Mais elles avaient seulement ouï dire: celui qui autrefois nous persécutait, annonce maintenant la foi qu’il détruisait autrefois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'Et elles glorifiaient Dieu à cause de moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Depuis je montai encore à Jérusalem quatorze ans après, avec Barnabas, et je pris aussi avec moi Tite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Or j’y montai par révélation, et je conférai avec ceux de Jérusalem touchant l’Evangile que je prêche parmi les Gentils, même en particulier avec ceux qui sont en estime, afin qu’en quelque sorte je ne courusse, ou n’eusse couru en vain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Et même on n’obligea point Tite, qui était avec moi, à se faire circoncire, quoiqu’il fût Grec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'Et ce fut à cause des faux frères qui s’étaient introduits dans l’Eglise, et qui y étaient entrés couvertement pour épier notre liberté, que nous avons en Jésus-Christ, afin de nous ramener dans la servitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Et nous ne leur avons point cédé par aucune sorte de soumission, non pas même un moment; afin que la vérité de l’Evangile demeurât parmi vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Et je ne suis en rien différent de ceux qui semblent être quelque chose, quels qu’ils aient été autrefois, (Dieu n’ayant point d’égard à l’apparence extérieure de l’homme) car ceux qui sont en estime ne m’ont rien communiqué de plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Mais, au contraire, quand ils virent que la Prédication de l’Evangile du Prépuce m’était commise, comme celle de la Circoncision l’était à Pierre:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(Car celui qui a opéré avec efficace par Pierre en la charge d’Apôtre envers la Circoncision, a aussi opéré avec efficace par moi envers les Gentils.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'Jacques, dis-je, Céphas, et Jean (qui sont estimés être les Colonnes) ayant reconnu la grâce que j’avais reçue, me donnèrent, à moi et à Barnabas, la main d’association, afin que nous allassions vers les Gentils, et qu’ils allassent eux vers ceux de la Circoncision;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Nous recommandant seulement de nous souvenir des pauvres; ce que je me suis aussi étudié de faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Mais quand Pierre fut venu à Antioche, je lui résistai en face, parce qu’il méritait d’être repris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Car avant que quelques-uns fussent venus de la part de Jacques, il mangeait avec les Gentils; mais quand ceux-là furent venus, il s’en retira, et s’en sépara, craignant ceux qui étaient de la Circoncision.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Les autres Juifs usaient aussi de dissimulation comme lui, tellement que Barnabas lui-même se laissait entraîner par leur dissimulation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Mais quand je vis qu’ils ne marchaient pas de droit pied selon la vérité de l’Evangile, je dis à Pierre devant tous: si toi qui es Juif, vis comme les Gentils, et non pas comme les Juifs, pourquoi contrains-tu les Gentils à Judaïser?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Nous qui sommes Juifs de naissance, et non point pécheurs d’entre les Gentils;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Sachant que l’homme n’est pas justifié par les oeuvres de la Loi, mais seulement par la foi en Jésus- Christ, nous, dis-je, nous avons cru en Jésus-Christ, afin que nous fussions justifiés par la foi de Christ, et non point par les oeuvres de la Loi; parce que personne ne sera justifié par les oeuvres de la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Or si en cherchant d’être justifiés par Christ, nous sommes aussi trouvés pécheurs, Christ est-il pourtant ministre du péché? à Dieu ne plaise!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Car si je rebâtissais les choses que j’ai renversées, je montrerais que j’ai été moi-même un prévaricateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Mais par la Loi je suis mort à la Loi, afin que je vive à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Je suis crucifié avec Christ, et je vis, non pas maintenant moi, mais Christ vit en moi; et ce que je vis maintenant en la chair, je le vis en la foi du Fils de Dieu, qui m’a aimé, et qui s’est donné lui-même pour moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Je n’anéantis point la grâce de Dieu: car si la justice est par la Loi, Christ est donc mort inutilement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Ô Galates insensés! qui est-ce qui vous a ensorcelés pour faire que vous n’obéissiez point à la vérité, vous à qui Jésus-Christ a été auparavant portrait devant les yeux, et crucifié entre vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Je voudrais seulement entendre ceci de vous: avez-vous reçu l’Esprit par les oeuvres de la Loi, ou par la prédication de la foi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Etes-vous si insensés, qu’en ayant commencé par l’Esprit, maintenant vous finissiez par la chair?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Avez-vous tant souffert en vain? si toutefois c’est en vain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Celui donc qui vous donne l’Esprit, et qui produit en vous les dons miraculeux, le fait-il par les oeuvres de la Loi, ou par la prédication de la foi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Comme Abraham a cru à Dieu, et il lui a été imputé à justice;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Sachez aussi que ceux qui sont de la foi, sont enfants d’Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Aussi l’Ecriture prévoyant que Dieu justifierait les Gentils par la foi, a auparavant évangélisé à Abraham, en lui disant: toutes les nations seront bénies en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'C’est pourquoi ceux qui sont de la foi, sont bénis avec le fidèle Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Mais tous ceux qui sont des oeuvres de la Loi, sont sous la malédiction; car il est écrit: maudit est quiconque ne persévère pas dans toutes les choses qui sont écrites au Livre de la Loi pour les faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Or que par la Loi personne ne soit justifié devant Dieu, cela paraît par ce qui est dit: que le juste vivra de la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Or la Loi n’est pas de la foi; mais l’homme qui aura fait ces choses, vivra par elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Christ nous a rachetés de la malédiction de la Loi, quand il a été fait malédiction pour nous; (car il est écrit: maudit est quiconque pend au bois.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'Afin que la bénédiction d’Abraham parvînt aux Gentils par Jésus- Christ, et que nous reçussions par la foi l’Esprit qui avait été promis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Mes frères, je vais vous parler à la manière des hommes. Si une alliance faite par un homme, est confirmée, nul ne la casse, ni n’y ajoute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Or les promesses ont été faites à Abraham, et à sa semence; il n’est pas dit, et aux semences, comme s’il avait parlé de plusieurs, mais comme parlant d’une seule, et à sa semence: qui est Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Voici donc ce que je dis: c’est que quant à l’alliance qui a été auparavant confirmée par Dieu en Christ, la Loi qui est venue quatre cent-trente ans après, ne peut point l’annuler, pour abolir la promesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Car si l’héritage est par la Loi, il n’est point par la promesse; or Dieu l’a donné à Abraham par la promesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'A quoi donc sert la Loi? elle a été ajoutée à cause des transgressions, jusqu’à ce que vînt la semence à l’égard de laquelle la promesse avait été faite; et elle a été ordonnée par les Anges, par le ministère d’un Médiateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Or le Médiateur n’est pas d’un seul: mais Dieu est un seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'La Loi donc a-t-elle été ajoutée contre les promesses de Dieu? nullement. Car si la Loi eût été donnée pour pouvoir vivifier, véritablement la justice serait de la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Mais l’Ecriture a montré que tous les hommes étaient pécheurs, afin que la promesse par la foi en Jésus-Christ fût donnée à ceux qui croient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Or avant que la foi vînt, nous étions gardés sous la Loi, étant renfermés sous l’attente de la foi qui devait être révélée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'La Loi a donc été notre Pédagogue pour nous amener à Christ, afin que nous soyons justifiés par la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Mais la foi étant venue, nous ne sommes plus sous le Pédagogue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Parce que vous êtes tous enfants de Dieu par la foi en Jésus- Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Car vous tous qui avez été baptisés en Christ, vous avez revêtu Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Où il n’y a ni Juif ni Grec; où il n’y a ni esclave ni libre; où il n’y a ni mâle ni femelle; car vous êtes tous un en Jésus- Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Or si vous êtes de Christ, vous êtes donc la semence d’Abraham, et héritiers selon la promesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Or je dis que pendant tout le temps que l’héritier est un enfant, il n’est en rien différent du serviteur, quoiqu’il soit Seigneur de tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'Mais il est sous des tuteurs et des curateurs jusqu’au temps déterminé par le père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Nous aussi, lorsque nous étions des enfants, nous étions asservis sous les rudiments du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Mais quand l’accomplissement du temps est venu, Dieu a envoyé son Fils, né d’une femme, et soumis à la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'Afin qu’il rachetât ceux qui étaient sous la Loi, et que nous reçussions l’adoption des enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Et parce que vous êtes enfants, Dieu a envoyé l’Esprit de son Fils dans vos coeurs, criant Abba, c’est-à-dire Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Maintenant donc tu n’es plus serviteur, mais fils; or si tu es fils, tu es aussi héritier de Dieu par Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Mais lorsque vous ne connaissiez point Dieu, vous serviez ceux qui de leur nature ne sont point Dieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Et maintenant que vous avez connu Dieu, ou plutôt que vous avez été connus de Dieu, comment retournez-vous encore à ces faibles et misérables éléments, auxquels vous voulez encore servir comme auparavant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Vous observez les jours, les mois, les temps et les années.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Je crains pour vous que peut-être je n’aie travaillé en vain parmi vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Soyez comme moi; car je suis aussi comme vous; je vous en prie, mes frères; vous ne m’avez fait aucun tort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Et vous savez comment je vous ai ci-devant évangélisé dans l’infirmité de la chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'Et vous n’avez point méprisé ni rejeté mon épreuve, telle qu’elle était en ma chair; mais vous m’avez reçu comme un Ange de Dieu, et comme Jésus-Christ même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Quelle était donc la déclaration que vous faisiez de votre bonheur? car je vous rends témoignage que, s’il eût été possible, vous eussiez arraché vos yeux, et vous me les eussiez donnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Suis-je donc devenu votre ennemi, en vous disant la vérité?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Ils sont jaloux de vous, mais ce n’est pas comme il faut; au contraire, ils vous veulent exclure, afin que vous soyez jaloux d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Mais il est bon d’être toujours zélé pour le bien, et de ne l’être pas seulement quand je suis présent avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Mes petits enfants, pour lesquels enfanter je travaille de nouveau, jusqu’à ce que Christ soit formé en vous:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'Je voudrais être maintenant avec vous, et changer de langage, car je suis en perplexité sur votre sujet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Dites-moi, vous qui voulez être sous la Loi, n’entendez-vous point la Loi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Car il est écrit qu’Abraham a eu deux fils, l’un de la servante, et l’autre de la femme libre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Mais celui qui était de la servante, naquit selon la chair; et celui qui était de la femme libre, naquit par la promesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Or ces choses doivent être entendues par allégorie: car ce sont les deux alliances; l’une du mont de Sinaï, qui ne produit que des esclaves, et c’est Agar.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Car ce nom d’Agar veut dire Sinaï; qui est une montagne en Arabie, et correspondante à la Jérusalem de maintenant, laquelle sert avec ses enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Mais la Jérusalem d’en haut est la femme libre, et c’est la mère de nous tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Car il est écrit: réjouis-toi, stérile, qui n’enfantais point; efforce-toi, et t’écrie, toi qui n’étais point en travail d’enfant; car il y a beaucoup plus d’enfants de celle qui avait été laissée, que de celle qui avait un mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Or pour nous, mes frères, nous sommes enfants de la promesse, ainsi qu’Isaac.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Mais comme alors celui qui était né selon la chair, persécutait celui qui était né selon l’Esprit, il en est de même aussi maintenant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Mais que dit l’Ecriture? chasse la servante et son fils: car le fils de la servante ne sera point héritier avec le fils de la femme libre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Or mes frères, nous ne sommes point enfants de la servante, mais de la femme libre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Tenez-vous donc fermes dans la liberté à l’égard de laquelle Christ nous a affranchis, et ne vous soumettez plus au joug de la servitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Voici, je vous dis moi Paul, que si vous êtes circoncis, Christ ne vous profitera de rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Et de plus je proteste à tout homme qui se circoncit, qu’il est obligé d’accomplir toute la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Christ devient inutile à l’égard de vous tous qui voulez être justifiés par la Loi; et vous êtes déchus de la grâce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Mais pour nous, nous espérons par l’esprit d’être justifiés par la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Car en Jésus-Christ ni la Circoncision ni le prépuce n’ont aucune efficace, mais la foi opérante par la charité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Vous couriez bien: qui est-ce donc qui vous a empêchés d’obéir à la vérité?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Cette persuasion ne vient pas de celui qui vous appelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Un peu de levain fait lever toute la pâte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Je m’assure de vous en notre Seigneur, que vous n’aurez point d’autre sentiment; mais celui qui vous trouble en portera la condamnation, quel qu’il soit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Et pour moi, mes frères, si je prêche encore la Circoncision, pourquoi est-ce que je souffre encore la persécution? le scandale de la croix est donc aboli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Plût à Dieu que ceux qui vous troublent fussent retranchés!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Car, mes frères, vous avez été appelés à la liberté; seulement ne prenez pas une telle liberté pour une occasion de vivre selon la chair; mais servez-vous l’un l’autre avec charité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Car toute la Loi est accomplie dans cette seule parole: tu aimeras ton Prochain comme toi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Mais si vous vous mordez et vous dévorez les uns les autres, prenez garde que vous ne soyez consumés l’un par l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Je vous dis donc: marchez selon l’Esprit; et vous n’accomplirez point les convoitises de la chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Car la chair convoite contre l’esprit, et l’esprit contre la chair; et ces choses sont opposées l’une à l’autre; tellement que vous ne faites point les choses que vous voudriez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Or si vous êtes conduits par l’Esprit, vous n’êtes point sous la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Car les oeuvres de la chair sont évidentes, lesquelles sont l’adultère, la fornication, la souillure, l’impudicité,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'L’idolâtrie, l’empoisonnement, les inimitiés, les querelles, les jalousies, les colères, les disputes, les divisions, les sectes,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'Les envies, les meurtres, les ivrogneries, les gourmandises, et les choses semblables à celles-là; au sujet desquelles je vous prédis, comme je vous l’ai déjà dit, que ceux qui commettent de telles choses n’hériteront point le Royaume de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Mais le fruit de l’Esprit est la charité, la joie, la paix, un esprit patient, la bonté, la bénéficence, la fidélité, la douceur, la tempérance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'Or la Loi ne condamne point de telles choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Or ceux qui sont de Christ, ont crucifié la chair avec ses affections et ses convoitises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Si nous vivons par l’Esprit, conduisons-nous aussi par l’Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Ne désirons point la vaine gloire, en nous provoquant l’un l’autre, et en nous portant envie l’un à l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Mes frères, lorsqu’un homme est surpris en quelque faute, vous qui êtes spirituels, redressez un tel homme avec un esprit de douceur; et toi, prends garde à toi-même, de peur que tu ne sois aussi tenté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Portez les charges les uns des autres, et accomplissez ainsi la Loi de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Car si quelqu’un s’estime être quelque chose, quoiqu’il ne soit rien, il se séduit lui-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Or que chacun examine ses actions, et alors il aura de quoi se glorifier en lui-même seulement, et non dans les autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Car chacun portera son propre fardeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Que celui qui est enseigné dans la parole, fasse participant de tous ses biens celui qui l’enseigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Ne vous abusez point, Dieu ne peut être moqué; car ce que l’homme aura semé, il le moissonnera aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'C’est pourquoi celui qui sème à sa chair, moissonnera aussi de la chair la corruption; mais celui qui sème à l’Esprit, moissonnera de l’Esprit la vie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Or ne nous relâchons point en faisant le bien; car nous moissonnerons en la propre saison, si nous ne devenons point lâches.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'C’est pourquoi pendant que nous en avons le temps, faisons du bien à tous; mais principalement aux domestiques de la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Vous voyez quelle grande Lettre je vous ai écrite de ma propre main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Tous ceux qui cherchent à se rendre agréables dans ce qui regarde la chair, sont ceux qui vous contraignent d’être circoncis; afin seulement qu’ils ne souffrent point de persécution pour la croix de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Car ceux-là même qui sont circoncis ne gardent point la Loi; mais ils veulent que vous soyez circoncis, afin de se glorifier en votre chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Mais pour moi, à Dieu ne plaise que je me glorifie sinon en la croix de notre Seigneur Jésus-Christ, par lequel le monde m’est crucifié, et moi au monde!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Car en Jésus-Christ ni la Circoncision, ni le prépuce n’ont aucune efficace, mais la nouvelle créature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Et à l’égard de tous ceux qui marcheront selon cette règle, que la paix et la miséricorde soient sur eux, et sur l’Israël de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Au reste, que personne ne me donne du chagrin; car je porte en mon corps les flétrissures du Seigneur Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Mes frères, que la grâce de notre Seigneur Jésus-Christ soit avec votre esprit; Amen! ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paul Apôtre de Jésus-Christ, par la volonté de Dieu, aux Saints et Fidèles en Jésus-Christ qui sont à Ephèse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Que la grâce et la paix vous soient données par Dieu notre Père, et par le Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Béni soit Dieu, qui est le Père de notre Seigneur Jésus-Christ, qui nous a bénis de toute bénédiction spirituelle dans les lieux célestes en Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'Selon qu’il nous avait élus en lui avant la fondation du monde, afin que nous fussions saints et irrépréhensibles devant lui en charité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Nous ayant prédestinés pour nous adopter à soi par Jésus-Christ, selon le bon plaisir de sa volonté;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'A la louange de la gloire de sa grâce, par laquelle il nous a rendus agréables en son Bien-Aimé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'En qui nous avons la rédemption par son sang, savoir la rémission des offenses, selon les richesses de sa grâce,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Laquelle il a fait abonder sur nous en toute sagesse et intelligence;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Nous ayant donné à connaître selon son bon plaisir, le secret de sa volonté, lequel il avait premièrement arrêté en soi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'Afin que dans l’accomplissement des temps qu’il avait réglés, il réunît tout en Christ, tant ce qui est aux cieux, que ce qui est sur la terre, en lui-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'En qui aussi nous sommes faits son héritage, ayant été prédestinés, suivant la résolution de celui qui accomplit avec efficace toutes choses, selon le conseil de sa volonté;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Afin que nous soyons à la louange de sa gloire, nous qui avons les premiers espéré en Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'En qui vous êtes aussi, ayant ouï la parole de la vérité, qui est l’Evangile de votre salut, et auquel ayant cru vous avez été scellés du Saint-Esprit de la promesse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'Lequel est l’arrhe de notre héritage jusqu’à la rédemption de la possession qu’il a acquise, à la louange de sa gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'C’est pourquoi aussi ayant entendu parler de la foi que vous avez au Seigneur Jésus, et de la charité que vous avez envers tous les Saints,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'Je ne cesse point de rendre grâces pour vous dans mes prières;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Afin que le Dieu de notre Seigneur Jésus-Christ, le Père de gloire, vous donne l’Esprit de sagesse, et de révélation, dans ce qui regarde sa connaissance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'Qu’il illumine les yeux de votre entendement, afin que vous sachiez quelle est l’espérance de sa vocation, et quelles sont les richesses de la gloire de son héritage dans les Saints;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'Et quelle est l’excellente grandeur de sa puissance envers nous qui croyons selon l’efficace de la puissance de sa force:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Laquelle il a déployée avec efficace en Christ, quand il l’a ressuscité des morts, et qu’il l’a fait asseoir à sa droite dans les lieux célestes,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'Au-dessus de toute Principauté, de toute Puissance, de toute Dignité et de toute Domination, et au-dessus de tout Nom qui se nomme, non-seulement en ce siècle, mais aussi en celui qui est à venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'Et il a assujetti toutes choses sous ses pieds, et l’a établi sur toutes choses pour être le Chef de l’Eglise;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'Qui est son Corps, et l’accomplissement de celui qui accomplit tout en tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Et lorsque vous étiez morts en vos fautes et en vos péchés,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'Dans lesquels vous avez marché autrefois, suivant le train de ce monde, selon le Prince de la puissance de l’air, qui est l’esprit qui agit maintenant avec efficace dans les enfants rebelles à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Entre lesquels aussi nous avons tous conversé autrefois dans les convoitises de notre chair, accomplissant les désirs de la chair et de nos pensées; et nous étions de notre nature des enfants de colère, comme les autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, '(Mais Dieu, qui est riche en miséricorde, par sa grande charité de laquelle il nous a aimés;)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'Lors, dis-je, que nous étions morts en nos fautes, il nous a vivifiés ensemble avec Christ, par la grâce duquel vous êtes sauvés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'Et il nous a ressuscités ensemble, et nous a fait asseoir ensemble dans les lieux célestes en Jésus-Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'Afin qu’il montrât dans les siècles à venir les immenses richesses de sa grâce par sa bonté envers nous par Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Car vous êtes sauvés par la grâce, par la foi; et cela ne vient point de vous, c’est le don de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Non point par les oeuvres, afin que personne ne se glorifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Car nous sommes son ouvrage, étant créés en Jésus-Christ pour les bonnes oeuvres, que Dieu a préparées afin que nous marchions en elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'C’est pourquoi souvenez-vous que vous qui étiez autrefois Gentils en la chair, et qui étiez appelés Prépuce, par celle qui est appelée la Circoncision, faite de main en la chair,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'Etiez en ce temps-là hors de Christ, n’ayant rien de commun avec la République d’Israël, étant étrangers des alliances de la promesse, n’ayant point d’espérance, et étant sans Dieu, au monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Mais maintenant par Jésus-Christ, vous qui étiez autrefois loin, êtes approchés par le sang de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Car il est notre paix, qui des deux en a fait un, ayant rompu la clôture de la paroi mitoyenne;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'Ayant aboli en sa chair l’inimitié, savoir la Loi des commandements qui consiste en ordonnances; afin qu’il créât les deux en soi-même pour être un homme nouveau, en faisant la paix;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'Et qu’il réunît les uns et les autres pour former un corps devant Dieu, par la croix, ayant détruit en elle l’inimitié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Et étant venu il a évangélisé la paix à vous qui étiez loin, et à ceux qui étaient près.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Car nous avons par lui les uns et les autres accès auprès du Père en un même Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Vous n’êtes donc plus des étrangers ni des gens de dehors; mais les concitoyens des Saints, et les domestiques de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Etant édifiés sur le fondement des Apôtres, et des prophètes, et Jésus-Christ lui-même étant la maîtresse pierre du coin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'En qui tout l’édifice posé et ajusté ensemble, s’élève pour être un Temple saint au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'En qui vous êtes édifiés ensemble, pour être un Tabernacle de Dieu en esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'C’est pour cela que moi Paul je suis prisonnier de Jésus-Christ pour vous Gentils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Si toutefois vous avez entendu quel est le ministère de la grâce de Dieu, qui m’a été donnée pour vous:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'Comment par la révélation le mystère m’a été manifesté (ainsi que je l’ai écrit ci-dessus en peu de mots;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'D’où vous pouvez voir en le lisant, quelle est l’intelligence que j’ai du mystère de Christ).');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Lequel n’a point été manifesté aux enfants des hommes dans les autres âges, comme il a été maintenant révélé par l’Esprit à ses saints Apôtres et à ses Prophètes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'Savoir que les Gentils sont cohéritiers, et d’un même corps, et qu’ils participent ensemble à sa promesse en Christ, par l’Evangile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Duquel j’ai été fait le ministre, selon le don de la grâce de Dieu, qui m’a été donnée suivant l’efficace de sa puissance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Cette grâce, dis-je, m’a été donnée à moi qui suis le moindre de tous les Saints, pour annoncer parmi les Gentils les richesses incompréhensibles de Christ,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'Et pour mettre en évidence devant tous quelle est la communication qui nous a été accordée du mystère qui était caché de tout temps en Dieu, lequel a créé toutes choses par Jésus-Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'Afin que la sagesse de Dieu, qui est diverse en toutes sortes, soit maintenant donnée à connaître aux Principautés et aux Puissances, dans les lieux célestes par l’Eglise;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'Suivant le dessein arrêté dès les siècles, lequel il a établi en Jésus-Christ notre Seigneur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'Par lequel nous avons hardiesse et accès en confiance, par la foi que nous avons en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'C’est pourquoi je vous prie de ne vous point relâcher à cause de mes afflictions que je souffre pour l’amour de vous, ce qui est votre gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'A cause de cela je fléchis mes genoux devant le Père de notre Seigneur Jésus-Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, '(Duquel toute la parenté est nommée dans les Cieux et sur la terre.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Afin que selon les richesses de sa gloire il vous donne d’être puissamment fortifiés par son Esprit, en l’homme intérieur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'Tellement que Christ habite dans vos coeurs par la foi:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'Afin qu’étant enracinés et fondés dans la charité, vous puissiez comprendre avec tous les Saints, quelle est la largeur et la longueur, la profondeur et la hauteur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'Et connaître la charité de Christ, laquelle surpasse toute connaissance; afin que vous soyez remplis de toute plénitude de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Or à celui qui par la puissance qui agit en nous avec efficace, peut faire infiniment plus que tout ce que nous demandons et pensons,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'A lui soit gloire dans l’Eglise, en Jésus-Christ, dans tous les âges du siècle des siècles, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Je vous prie donc, moi qui suis prisonnier pour le Seigneur, de vous conduire d’une manière digne de la vocation à laquelle vous êtes appelés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'Avec toute humilité et douceur, avec un esprit patient, vous supportant l’un l’autre en charité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Etant soigneux de garder l’unité de l’Esprit par le lien de la paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Il y a un seul corps, un seul Esprit, comme aussi vous êtes appelés à une seule espérance de votre vocation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Il y a un seul Seigneur, une seule foi, un seul Baptême;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'Un seul Dieu et Père de tous, qui est sur tous, parmi tous, et en vous tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Mais la grâce est donnée à chacun de nous, selon la mesure du don de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'C’est pourquoi il est dit: étant monté en haut il a amené captive une grande multitude de captifs, et il a donné des dons aux hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Or ce qu’il est monté, qu’est-ce autre chose sinon que premièrement il était descendu dans les parties les plus basses de la terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Celui qui est descendu, c’est le même qui est monté au-dessus de tous les Cieux, afin qu’il remplît toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'Lui-même donc a donné les uns pour être Apôtres, les autres pour être Prophètes, les autres pour être Evangélistes, les autres pour être Pasteurs et Docteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'Pour travailler à la perfection des Saints, pour l’oeuvre du ministère, pour l’édification du corps de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'Jusqu’à ce que nous nous rencontrions tous dans l’unité de la foi, et de la connaissance du Fils de Dieu, dans l’état d’un homme parfait, dans la mesure de la parfaite stature de Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'Afin que nous ne soyons plus des enfants flottants, et emportés çà et là à tous vents de doctrine, par la tromperie des hommes, et par leur ruse à séduire artificieusement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Mais afin que suivant la vérité avec la charité, nous croissions en toutes choses en celui qui est le Chef, c’est-à-dire, Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'Duquel tout le corps bien ajusté et serré ensemble par toutes les jointures du fournissement, prend l’accroissement du corps, selon la vigueur qui est dans la mesure de chaque partie, pour l’édification de soi-même, en charité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Je vous dis donc, et je vous conjure de la part du Seigneur, de ne vous conduire plus comme le reste des Gentils, qui suivent la vanité de leurs pensées;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Ayant leur entendement obscurci de ténèbres, et étant éloignés de la vie de Dieu, à cause de l’ignorance qui est en eux par l’endurcissement de leur coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Lesquels ayant perdu tout sentiment, se sont abandonnés à la dissolution, pour commettre toute souillure, à qui en ferait pis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Mais vous n’avez pas ainsi appris Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'Si toutefois vous l’avez écouté, et si vous avez été enseignés par lui, selon que la vérité est en Jésus;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'Savoir que vous dépouilliez le vieil homme, quant à la conversation précédente, lequel se corrompt par les convoitises qui séduisent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'Et que vous soyez renouvelés dans l’esprit de votre entendement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'Et que vous soyez revêtus du nouvel homme, créé selon Dieu en justice et en vraie sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'C’est pourquoi ayant dépouillé le mensonge, parlez en vérité chacun avec son prochain; car nous sommes les membres les uns des autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Si vous vous mettez en colère, ne péchez point. Que le soleil ne se couche point sur votre colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Et ne donnez point lieu au Démon de vous perdre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Que celui qui dérobait, ne dérobe plus; mais que plutôt il travaille en faisant de ses mains ce qui est bon; afin qu’il ait de quoi donner à celui qui en a besoin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Qu’aucun discours malhonnête ne sorte de votre bouche, mais seulement celui qui est propre à édifier, afin qu’il soit agréable à ceux qui l’écoutent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'Et n’attristez point le Saint-Esprit de Dieu, par lequel vous avez été scellés pour le jour de la Rédemption.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Que toute amertume, colère, irritation, crierie, et médisance, soient ôtées du milieu de vous, avec toute malice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Mais soyez doux les uns envers les autres, pleins de compassion, et vous pardonnant les uns aux autres, ainsi que Dieu vous a pardonné par Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Soyez donc les imitateurs de Dieu, comme ses chers enfants;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'Et marchez dans la charité, ainsi que Christ aussi nous a aimés, et s’est donné lui-même pour nous en oblation et sacrifice à Dieu, en odeur de bonne senteur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Que ni la fornication, ni aucune souillure, ni l’avarice, ne soient pas même nommées parmi vous, ainsi qu’il est convenable à des Saints;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Ni aucune chose déshonnête, ni parole folle, ni plaisanterie; car ce sont là des choses qui ne sont pas bienséantes; mais plutôt des actions de grâces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Car vous savez ceci, que nul fornicateur, ni impur, ni avare, qui est un idolâtre, n’a point d’héritage dans le Royaume de Christ, et de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Que personne ne vous séduise par de vains discours, car à cause de ces choses la colère de Dieu vient sur les rebelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Ne soyez donc point leurs associés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Car vous étiez autrefois ténèbres, mais maintenant vous êtes lumière au Seigneur; conduisez-vous donc comme des enfants de lumière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, 'Car le fruit de l’Esprit consiste en toute débonnaireté, justice et vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'Eprouvant ce qui est agréable au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Et ne communiquez point aux oeuvres infructueuses des ténèbres, mais au contraire reprenez-les.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Car il est même déshonnête de dire les choses qu’ils font en secret.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Mais toutes choses étant mises en évidence par la lumière, sont rendues manifestes; car la lumière est celle qui manifeste tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'C’est pourquoi il est dit: Réveille-toi, toi qui dors, et te relève d’entre les morts, et Christ t’éclairera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Prenez donc garde comment vous vous conduirez soigneusement, non point comme étant dépourvus de sagesse, mais comme étant sages:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Rachetant le temps: car les jours sont mauvais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'C’est pourquoi ne soyez point sans prudence, mais comprenez bien quelle est la volonté du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Et ne vous enivrez point du vin auquel il y a de la dissolution; mais soyez remplis de l’Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Vous entretenant par des Psaumes, des cantiques et des chansons spirituelles; chantant et psalmodiant de votre coeur au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Rendant toujours grâces pour toutes choses au Nom de notre Seigneur Jésus-Christ à notre Dieu, et Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Vous soumettant les uns aux autres, en la crainte de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Femmes soyez soumises à vos maris, comme au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Car le mari est le chef de la femme, comme Christ est le chef de l’Eglise, et il est aussi le Sauveur de son Corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Comme donc l’Eglise est soumise à Christ, que les femmes le soient de même à leurs maris, en toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Et vous maris, aimez vos femmes, comme Christ a aimé l’Eglise, et s’est donné lui-même pour elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'Afin qu’il la sanctifiât, après l’avoir nettoyée dans le baptême d’eau et par sa parole:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'Afin qu’il se la rendît une Eglise glorieuse, n’ayant ni tache, ni ride, ni autre chose semblable, mais afin qu’elle fût sainte et irrépréhensible.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Les maris donc doivent aimer leurs femmes comme leurs propres corps; celui qui aime sa femme s’aime soi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Car personne n’a jamais eu en haine sa propre chair, mais il la nourrit et l’entretient, comme le Seigneur entretient l’Eglise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Car nous sommes membres de son corps, étant de sa chair, et de ses os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'C’est pourquoi l’homme laissera son père et sa mère, et il s’unira à sa femme, et les deux seront une même chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Ce mystère est grand, or je parle de Christ et de l’Eglise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Que chacun de vous aime donc sa femme comme soi-même; et que la femme révère son mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Enfants, obéissez à vos pères et à vos mères, dans ce qui est selon le Seigneur; car cela est juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Honore ton père et ta mère (ce qui est le premier commandement, avec promesse).');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'Afin qu’il te soit bien, et que tu vives longtemps sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Et vous pères, n’irritez point vos enfants, mais nourrissez-les sous la discipline, et en leur donnant les instructions du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Serviteurs obéissez à ceux qui sont vos maîtres selon la chair, avec crainte et tremblement, dans la simplicité de votre coeur, comme à Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Ne les servant point seulement sous leurs yeux, comme cherchant à plaire aux hommes; mais comme serviteurs de Christ, faisant de bon coeur la volonté de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Servant avec affection le Seigneur, et non pas les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'Sachant que chacun, soit esclave, soit libre, recevra du Seigneur le bien qu’il aura fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Et vous maîtres, faites envers eux la même chose, et modérez les menaces, sachant que le Seigneur et d’eux et de vous est au Ciel, et qu’il n’y a point en lui acception de personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Au reste, mes frères, fortifiez-vous en Notre Seigneur, et en la puissance de sa force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Soyez revêtus de toutes les armes de Dieu, afin que vous puissiez résister aux embûches du Démon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Car nous n’avons point à combattre contre le sang et la chair, mais contre les principautés, contre les puissances, contre les Seigneurs du monde, gouverneurs des ténèbres de ce siècle, contre les malices spirituelles qui sont dans les lieux célestes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'C’est pourquoi prenez toutes les armes de Dieu, afin que vous puissiez résister au mauvais jour, et après avoir tout surmonté, demeurer fermes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Soyez donc fermes, ayant vos reins ceints de la vérité, et étant revêtus de la cuirasse de la justice.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'Et ayant les pieds chaussés de la préparation de l’Evangile de paix;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Prenant sur tout le bouclier de la foi, par lequel vous puissiez éteindre tous les dards enflammés du malin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Prenez aussi le casque du salut, et l’épée de l’Esprit, qui est la parole de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'Priant en votre esprit par toutes sortes de prières et de supplications en tout temps, veillant à cela avec une entière persévérance, et priant pour tous les Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'Et pour moi aussi, afin qu’il me soit donné de parler en toute liberté, et avec hardiesse, pour donner à connaître le mystère de l’Evangile,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'Pour lequel je suis ambassadeur quoique chargé de chaînes, afin, dis-je, que je parle librement, ainsi qu’il faut que je parle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Or afin que vous aussi sachiez mon état, et ce que je fais, Tychique, notre frère bien-aimé, et fidèle Ministre du Seigneur, vous fera savoir le tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Car je vous l’ai envoyé tout exprès, afin que vous appreniez par lui quel est notre état, et qu’il console vos coeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Que la paix soit avec les frères, et la charité avec la foi, de la part de Dieu le Père, et du Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Que la grâce soit avec tous ceux qui aiment notre Seigneur Jésus- Christ en pureté; Amen! ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paul et Timothée, Serviteurs de Jésus-Christ, à tous les Saints en Jésus-Christ qui sont à Philippes, avec les Evêques et les Diacres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Que la grâce et la paix vous soient données de par Dieu, notre Père, et de par le Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Je rends grâces à mon Dieu toutes les fois que je fais mention de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'En priant toujours pour vous tous avec joie dans toutes mes prières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'A cause de votre attachement à l’Evangile, depuis le premier jour jusqu’à maintenant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Etant assuré de cela même, que celui qui a commencé cette bonne oeuvre en vous, l’achèvera jusqu’à la journée de Jésus-Christ:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Comme il est juste que je pense ainsi de vous tous, parce que je retiens dans mon coeur que vous avez tous été participants de la grâce avec moi dans mes liens, et dans la défense et la confirmation de l’Evangile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Car Dieu m’est témoin que je vous aime tous tendrement, conformément à la charité de Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Et je lui demande cette grâce, que votre charité abonde encore de plus en plus avec connaissance et toute intelligence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'Afin que vous discerniez les choses contraires, pour être purs et sans achoppement jusqu’à la journée de Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'Etant remplis de fruits de justice, qui sont par Jésus-Christ, à la gloire et à la louange de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Or mes frères, je veux bien que vous sachiez que les choses qui me sont arrivées, sont arrivées pour un plus grand avancement de l’Evangile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'De sorte que mes liens en Christ ont été rendus célèbres dans tout le Prétoire, et partout ailleurs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'Et que plusieurs de nos frères en notre Seigneur étant rassurés par mes liens, osent annoncer la parole plus hardiment, et sans crainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Il est vrai que quelques-uns prêchent Christ par envie et par un esprit de dispute; et que les autres le font, au contraire, par une bonne volonté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Les uns, dis-je, annoncent Christ par un esprit de dispute, et non pas purement; croyant ajouter de l’affliction à mes liens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Mais les autres le font par charité, sachant que je suis établi pour la défense de l’Evangile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Quoi donc? toutefois en quelque manière que ce soit, par ostentation, ou par amour de la vérité, Christ est annoncé; et c’est de quoi je me réjouis, et je me réjouirai.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Or je sais que ceci me tournera à salut par votre prière, et par le secours de l’Esprit de Jésus-Christ:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Selon ma ferme attente et mon espérance, que je ne serai confus en rien; mais qu’en toute assurance, Christ sera maintenant, comme il l’a toujours été, glorifié en mon corps, soit par la vie, soit par la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Car Christ m’est gain à vivre et à mourir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Mais s’il m’est utile de vivre en la chair, et ce que je dois choisir, je n’en sais rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Car je suis pressé des deux côtés: mon désir tendant bien à déloger, et à être avec Christ, ce qui m’est beaucoup meilleur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Mais il est plus nécessaire pour vous que je demeure en la chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Et je sais cela comme tout assuré, que je demeurerai, et que je continuerai d’être avec vous tous pour votre avancement, et pour la joie de votre foi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'Afin que vous ayez en moi un sujet de vous glorifier de plus en plus en Jésus-Christ, par mon retour au milieu de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Seulement conduisez-vous dignement comme il est séant selon l’Evangile de Christ; afin que soit que je vienne, et que je vous voie; soit que je sois absent, j’entende quant à votre état, que vous persistez en un même esprit, combattant ensemble d’un même courage par la foi de l’Evangile, et n’étant en rien épouvantés par les adversaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'Ce qui leur est une démonstration de perdition, mais à vous, de salut; et cela de la part de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Parce qu’il vous a été gratuitement donné dans ce qui a du rapport à Christ, non seulement de croire en lui, mais aussi de souffrir pour lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'Ayant à soutenir le même combat que vous avez vu en moi, et que vous apprenez être maintenant en moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Si donc il y a quelque consolation en Christ, s’il y a quelque soulagement dans la charité, s’il y a quelque communion d’esprit, s’il y a quelques cordiales affections et quelques compassions,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'Rendez ma joie parfaite, étant d’un même sentiment, ayant un même amour, n’étant qu’une même âme, et consentant tous à une même chose.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Que rien ne se fasse par un esprit de dispute, ou par vaine gloire; mais que par humilité de coeur l’un estime l’autre plus excellent que soi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Ne regardez point chacun, à votre intérêt particulier, mais que chacun ait égard aussi à ce qui concerne les autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Qu’il y ait donc en vous un même sentiment qui a été en Jésus- Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'Lequel étant en forme de Dieu, n’a point regardé comme une usurpation d’être égal à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Cependant il s’est anéanti lui-même, ayant pris la forme de serviteur, fait à la ressemblance des hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'Et étant trouvé en figure comme un homme, il s’est abaissé lui- même, et a été obéissant jusques à la mort, à la mort même de la croix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'C’est pourquoi aussi Dieu l’a souverainement élevé, et lui a donné un Nom, qui est au-dessus de tout Nom;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'Afin qu’au Nom de Jésus tout genou se ploie, tant de ceux qui sont aux cieux, que de ceux qui sont en la terre, et au-dessous de la terre,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'Et que toute Langue confesse que Jésus-Christ est le Seigneur, à la gloire de Dieu le Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'C’est pourquoi, mes bien-aimés, ainsi que vous avez toujours obéi, non seulement comme en ma présence, mais beaucoup plus maintenant en mon absence, employez-vous à votre propre salut avec crainte et tremblement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Car c’est Dieu qui produit en vous avec efficace le vouloir, et l’exécution, selon son bon plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Faites toutes choses sans murmures, et sans disputes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'afin que vous soyez sans reproche, et purs, des enfants de Dieu, irrépréhensibles au milieu de la génération corrompue et perverse, parmi lesquels vous reluisez comme des flambeaux au monde, qui portent au devant d’eux la parole de la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Pour me glorifier en la journée de Christ de n’avoir point couru en vain, ni travaillé en vain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Que si même je sers d’aspersion sur le sacrifice et le service de votre foi, j’en suis joyeux; et je m’en réjouis avec vous tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Vous aussi pareillement soyez-en joyeux, et réjouissez-vous-en avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Or j’espère avec la grâce du Seigneur Jésus de vous envoyer bientôt Timothée, afin que j’aie aussi plus de courage quand j’aurai connu votre état.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Car je n’ai personne d’un pareil courage, et qui soit vraiment soigneux de ce qui vous concerne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Parce que tous cherchent leur intérêt particulier, et non les intérêts de Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Mais vous savez l’épreuve que j’ai faite de lui, puisqu’il a servi avec moi en l’Evangile, comme l’enfant sert son père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'J’espère donc de l’envoyer dès que j’aurai pourvu à mes affaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Et je m’assure en notre Seigneur que moi-même aussi je vous irai voir bientôt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Mais j’ai cru nécessaire de vous envoyer Epaphrodite mon frère, mon compagnon d’oeuvre et mon compagnon d’armes, qui aussi m’a été envoyé de votre part pour me fournir ce dont j’ai eu besoin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Car aussi il désirait ardemment de vous voir tous, et il était fort affligé de ce que vous aviez appris qu’il avait été malade.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'En effet il a été malade, et fort proche de la mort; mais Dieu a eu pitié de lui, et non seulement de lui, mais aussi de moi, afin que je n’eusse pas tristesse sur tristesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Je l’ai donc envoyé à cause de cela avec plus de soin, afin qu’en le revoyant vous ayez de la joie, et que j’aie moins de tristesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Recevez-le donc en notre Seigneur, avec toute sorte de joie; et ayez de l’estime pour ceux qui sont tels que lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Car il a été proche de la mort pour l’oeuvre de Christ, n’ayant eu aucun égard à sa propre vie, afin de suppléer au défaut de votre service envers moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Au reste, mes frères, réjouissez-vous en notre Seigneur. Il ne m’est point fâcheux, et c’est votre sûreté, que je vous écrive les mêmes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Prenez garde aux Chiens; prenez garde aux mauvais Ouvriers; prenez garde à la Circoncision.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Car c’est nous qui sommes la Circoncision, nous qui servons Dieu en esprit, et qui nous glorifions en Jésus-Christ, et qui n’avons point de confiance en la chair;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Quoi que je ne pourrais bien aussi avoir confiance en la chair; même si quelqu’un estime qu’il a de quoi se confier en la chair, j’en ai encore davantage;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Moi qui ai été circoncis le huitième jour, qui suis de la race d’Israël, de la Tribu de Benjamin, Hébreu, né d’Hébreux, Pharisien de religion:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'Quant au zèle, persécutant l’Eglise; et quant à la justice qui est de la Loi, étant sans reproche,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Mais ce qui m’était un gain, je l’ai regardé comme m’étant nuisible et cela pour l’amour de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Et certes, je regarde toutes les autres choses comme m’étant nuisibles en comparaison de l’excellence de la connaissance de Jésus- Christ mon Seigneur, pour l’amour duquel je me suis privé de toutes ces choses, et je les estime comme du fumier, afin que je gagne Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'Et que je sois trouvé en lui, ayant non point ma justice qui est de la Loi, mais celle qui est par la foi en Christ, c’est à dire, la justice qui est de Dieu par la foi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Pour connaître Jésus-Christ, et la vertu de sa résurrection, et la communion de ses afflictions, étant rendu conforme à sa mort;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'Essayant si en quelque manière je puis parvenir à la résurrection des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Non que j’aie déjà atteint le but, ou que je sois déjà rendu accompli: mais je poursuis ce but pour tâcher d’y parvenir, c’est pourquoi aussi j’ai été pris par Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Mes frères, pour moi, je ne me persuade pas d’avoir atteint le but;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'Mais je fais une chose, c’est qu’en oubliant les choses qui sont derrière moi, et m’avançant vers celles qui sont devant moi, je cours vers le but, savoir au prix de la céleste vocation, qui est de Dieu en Jésus-Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'C’est pourquoi, nous tous qui sommes parfaits ayons ce même sentiment; et si en quelque chose vous avez un autre sentiment, Dieu vous le révélera aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Cependant marchons suivant une même règle pour les choses auxquelles nous sommes parvenus, et ayons un même sentiment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Soyez tous ensemble mes imitateurs, mes frères, et considérez ceux qui marchent comme vous nous avez pour modèle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Car il y en a plusieurs qui marchent d’une telle manière, que je vous ai souvent dit, et maintenant je vous le dis encore en pleurant, qu’ils sont ennemis de la croix de Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Desquels la fin est la perdition, desquels le Dieu est le ventre, et desquels la gloire est dans leur confusion, n’ayant d’affection que pour les choses de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Mais pour nous, notre bourgeoisie est dans les Cieux, d’où aussi nous attendons le Sauveur, le Seigneur Jésus-Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'Qui transformera notre corps vil, afin qu’il soit rendu conforme à son corps glorieux, selon cette efficace par laquelle il peut même s’assujettir toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'C’est pourquoi, mes très chers frères que j’aime tendrement, vous qui êtes ma joie et ma couronne, demeurez ainsi fermes en notre Seigneur, mes bien-aimés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Je prie Evodie, et je prie aussi Syntiche, d’avoir un même sentiment au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Je te prie aussi, toi mon vrai compagnon, aide-leur, comme à celles qui ont combattu avec moi dans l’Evangile, avec Clément, et mes autres compagnons d’oeuvre, dont les noms sont écrits au Livre de vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Réjouissez-vous en notre Seigneur; je vous le dis encore, réjouissez-vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Que votre douceur soit connue de tous les hommes. Le Seigneur est près.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Ne vous inquiétez de rien, mais en toutes choses présentez vos demandes à Dieu par des prières et des supplications, avec des actions de grâces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Et la paix de Dieu, laquelle surpasse toute intelligence, gardera vos coeurs et vos sentiments en Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Au reste, mes frères, que toutes les choses qui sont véritables, toutes les choses qui sont vénérables, toutes les choses qui sont justes, toutes les choses qui sont pures, toutes les choses qui sont aimables, toutes les choses qui sont de bonne renommée, toutes celles où il y a quelque vertu et quelque louange, pensez à ces choses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Car aussi vous les avez apprises, reçues, entendues et vues en moi. Faites ces choses, et le Dieu de paix sera avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Or je me suis fort réjoui en notre Seigneur, de ce qu’à la fin vous avez fait revivre le soin que vous avez de moi; à quoi aussi vous pensiez, mais vous n’en aviez pas l’occasion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Je ne dis pas ceci ayant égard à quelque indigence: car j’ai appris à être content des choses selon que je me trouve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Je sais être abaissé, je sais aussi être dans l’abondance; partout et en toutes choses je suis instruit tant à être rassasié, qu’à avoir faim; tant à être dans l’abondance, que dans la disette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Je puis toutes choses en Christ qui me fortifie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Néanmoins vous avez bien fait de prendre part à mon affliction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Vous savez aussi, vous Philippiens, qu’au commencement de la prédication de l’Evangile, quand je partis de Macédoine, aucune Eglise ne me communiqua rien en matière de donner et de recevoir, excepté vous seuls.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Et même lorsque j’étais à Thessalonique, vous m’avez envoyé une fois, et même deux fois, ce dont j’avais besoin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Ce n’est pas que je recherche des présents, mais je cherche le fruit qui abonde pour votre compte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'J’ai tout reçu, et je suis dans l’abondance, et j’ai été comblé de biens en recevant d’Epaphrodite ce qui m’a été envoyé de votre part, comme un parfum de bonne odeur, comme un sacrifice que Dieu accepte, et qui lui est agréable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Aussi mon Dieu suppléera selon ses richesses à tout ce dont vous aurez besoin, et vous donnera sa gloire en Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Or à notre Dieu et notre Père, soit gloire aux siècles des siècles; Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Saluez chacun des Saints en Jésus-Christ. Les frères qui sont avec moi vous saluent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Tous les Saints vous saluent, et principalement ceux qui sont de la maison de César.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'La grâce de notre Seigneur Jésus-Christ soit avec vous tous, Amen. ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paul Apôtre de Jésus-Christ, par la volonté de Dieu, et le frère Timothée:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'Aux Saints et frères, fidèles en Christ, qui sont à Colosses: que la grâce et la paix vous soient données de par Dieu notre Père, et de par le Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Nous rendons grâces à Dieu, qui est le Père de notre Seigneur Jésus-Christ, et nous prions toujours pour vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'Ayant ouï parler de votre foi en Jésus-Christ, et de votre charité envers tous les Saints;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'A cause de l’espérance des biens qui vous sont réservés dans les Cieux, et dont vous avez eu ci-devant connaissance par la parole de la vérité, c’est-à-dire, par l’Evangile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Qui est parvenu jusqu’à vous, comme il l’est aussi dans tout le monde; et il y fructifie, de même que parmi vous, depuis le jour que vous avez entendu et connu la grâce de Dieu dans la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Comme vous avez été instruits aussi par Epaphras notre cher compagnon de service, qui est fidèle Ministre de Christ pour vous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'Et qui nous a appris quelle est la charité que vous avez par le Saint- Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'C’est pourquoi depuis le jour que nous avons appris ces choses, nous ne cessons point de prier pour vous, et de demander à Dieu que vous soyez remplis de la connaissance de sa volonté, en toute sagesse et intelligence spirituelle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'Afin que vous vous conduisiez dignement comme il est séant selon le Seigneur, pour lui plaire à tous égards, fructifiant en toute bonne oeuvre, et croissant en la connaissance de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'Etant fortifiés en toute force selon la puissance de sa gloire, en toute patience, et tranquillité d’esprit, avec joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Rendant grâces au Père, qui nous a rendus capables de participer à l’héritage des Saints dans la lumière;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'Qui nous a délivrés de la puissance des ténèbres, et nous a transportés au Royaume de son Fils bien-aimé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'En qui nous avons la rédemption par son sang, savoir, la rémission des péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'Lequel est l’image de Dieu invisible, le premier-né de toutes les créatures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Car par lui ont été créées toutes les choses qui sont aux Cieux et en la terre, les visibles et les invisibles, soit les Trônes, ou les Dominations, ou les Principautés, ou les Puissances, toutes choses ont été créées par lui, et pour lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'Et il est avant toutes choses, et toutes choses subsistent par lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Et c’est lui qui est le Chef du Corps de l’Eglise, et qui est le commencement et le premier-né d’entre les morts, afin qu’il tienne le premier rang en toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Car le bon plaisir du Père a été que toute plénitude habitât en lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'Et de réconcilier par lui toutes choses avec soi, ayant fait la paix par le sang de sa croix, savoir, tant les choses qui sont aux Cieux, que celles qui sont en la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Et vous qui étiez autrefois éloignés de lui, et qui étiez ses ennemis en votre entendement, et en mauvaises oeuvres;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'Il vous a maintenant réconciliés, par le corps de sa chair, en sa mort, pour vous rendre saints, sans tache, et irrépréhensibles devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'Si toutefois vous demeurez en la foi, étant fondés et fermes, et n’étant point transportés hors de l’espérance de l’Evangile que vous avez ouï, lequel est prêché à toute créature qui est sous le ciel, et duquel, moi Paul, j’ai été fait le Ministre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Je me réjouis donc maintenant en mes souffrances pour vous, et j’accomplis le reste des afflictions de Christ en ma chair, pour son corps, qui est l’Eglise;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'De laquelle j’ai été fait le Ministre, selon la dispensation de Dieu qui m’a été donnée envers vous, pour accomplir la parole de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'Savoir le mystère qui avait été caché dans tous les siècles et dans tous les âges, mais qui est maintenant manifesté à ses Saints;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'Auxquels Dieu a voulu donner à connaître quelles sont les richesses de la gloire de ce mystère parmi les Gentils, c’est à savoir Christ, qui a été prêché parmi vous, et qui est l’espérance de la gloire,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'Lequel nous annonçons, en exhortant tout homme, et en enseignant tout homme en toute sagesse, afin que nous rendions tout homme parfait en Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'A quoi aussi je travaille, en combattant selon son efficace, qui agit puissamment en moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Or je veux que vous sachiez combien est grand le combat que j’ai pour vous, et pour ceux qui sont à Laodicée, et pour tous ceux qui n’ont point vu ma présence en la chair;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'Afin que leurs coeurs soient consolés, étant unis ensemble dans la charité, et dans toutes les richesses d’une pleine certitude d’intelligence, pour la connaissance du mystère de notre Dieu et Père, et de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'En qui se trouvent tous les trésors de sagesse et de science.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Or je dis ceci afin que personne ne vous trompe par des discours séduisants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Car quoique je sois absent de corps, toutefois je suis avec vous en esprit, me réjouissant, et voyant votre ordre et la fermeté de votre foi, que vous avez en Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Ainsi donc que vous avez reçu le Seigneur Jésus-Christ, marchez en lui;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'Etant enracinés et édifiés en lui, et fortifiés en la foi, selon que vous avez été enseignés, abondant en elle avec action de grâces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Prenez garde que personne ne vous gagne par la philosophie, et par de vains raisonnements conformes à la tradition des hommes et aux éléments du monde et non point à la doctrine de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Car toute la plénitude de la Divinité habite en lui corporellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'Et vous êtes rendus accomplis en lui; qui est le Chef de toute principauté et puissance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'En qui aussi vous êtes circoncis d’une Circoncision faite sans main, qui consiste à dépouiller le corps des péchés de la chair, ce qui est la Circoncision de Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'Etant ensevelis avec lui par le Baptême; en qui aussi vous êtes ensemble ressuscités par la foi de l’efficace de Dieu, qui l’a ressuscité des morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Et lorsque vous étiez morts dans vos offenses, et dans le prépuce de votre chair, il vous a vivifiés ensemble avec lui, vous ayant gratuitement pardonné toutes vos offenses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'En ayant effacé l’obligation qui était contre nous, laquelle consistait en des ordonnances, et nous était contraire, et laquelle il a entièrement abolie, l’ayant attachée à la croix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Ayant dépouillé les principautés et les puissances, qu’il a produites en public triomphant d’elles en la croix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Que personne donc ne vous condamne pour le manger ou pour le boire, ou pour la distinction d’un jour de Fête, ou pour un jour de nouvelle lune, ou pour les sabbats.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'Lesquelles choses sont l’ombre de celles qui étaient à venir, mais le corps en est en Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Que personne ne vous maîtrise à son plaisir par humilité d’esprit, et par le service des Anges, s’ingérant dans des choses qu’il n’a point vues, étant témérairement enflé du sens de sa chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'Et ne retenant point le Chef, duquel tout le Corps étant fourni et ajusté ensemble par les jointures et les liaisons, croît d’un accroissement de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Si donc vous êtes morts avec Christ, quant aux rudiments du monde, pourquoi vous charge-t-on d’ordonnances, comme si vous viviez au monde?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'Savoir, Ne mange, Ne goûte, Ne touche point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'Qui sont toutes choses périssables par l’usage, et établies suivant les commandements et les doctrines des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Et qui ont pourtant quelque apparence de sagesse en dévotion volontaire, et en humilité d’esprit, et en ce qu’elles n’épargnent nullement le corps, et n’ont aucun égard au rassasiement de la chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Si donc vous êtes ressuscités avec Christ, cherchez les choses qui sont en haut, où Christ est assis à la droite de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Pensez aux choses qui sont en haut, et non point à celles qui sont sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Car vous êtes morts, et votre vie est cachée avec Christ en Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Quand Christ, qui est votre vie, apparaîtra, vous paraîtrez aussi alors avec lui en gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Mortifiez donc vos membres qui sont sur la terre, la fornication, la souillure, les affections déréglées, la mauvaise convoitise, et l’avarice, qui est une idolâtrie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'Pour lesquelles choses la colère de Dieu vient sur les enfants rebelles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'Et dans lesquelles vous avez marché autrefois, quand vous viviez en elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Mais rejetez maintenant toutes ces choses, la colère, l’animosité, la médisance; et qu’aucune parole déshonnête ne sorte de votre bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Ne mentez point l’un à l’autre ayant dépouillé le vieil homme avec ses actions,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'Et ayant revêtu le nouvel homme, qui se renouvelle en connaissance, selon l’image de celui qui l’a créé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'En qui il n’y a ni Grec, ni Juif, ni Circoncision, ni Prépuce, ni Barbare, ni Scythe, ni esclave, ni libre; mais Christ y est tout, et en tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Soyez donc, comme étant des élus de Dieu, saints et bien-aimés, revêtus des entrailles de miséricorde, de bonté, d’humilité, de douceur, d’esprit patient;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Vous supportant les uns les autres, et vous pardonnant les uns aux autres; et si l’un a querelle contre l’autre, comme Christ vous a pardonné, vous aussi faites-en de même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Et outre tout cela, soyez revêtus de la charité, qui est le lien de la perfection.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Et que la paix de Dieu, à laquelle vous êtes appelés pour être un seul corps, tienne le principal lieu dans vos coeurs; et soyez reconnaissants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Que la parole de Christ habite en vous abondamment en toute sagesse, vous enseignant et vous exhortant l’un l’autre par des Psaumes, des hymnes et des cantiques spirituels, avec grâce, chantant de votre coeur au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Et quelque chose que vous fassiez, soit par parole ou par oeuvre, faites tout au Nom du Seigneur Jésus, rendant grâces par lui à notre Dieu et Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Femmes, soyez soumises à vos maris, comme il est convenable selon le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Maris, aimez vos femmes, et ne vous aigrissez point contre elles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Enfants, obéissez à vos pères et à vos mères en toutes choses; car cela est agréable au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Pères, n’irritez point vos enfants, afin qu’ils ne perdent pas courage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Serviteurs, obéissez en toutes choses à ceux qui sont vos maîtres selon la chair, ne servant point seulement sous leurs yeux, comme voulant complaire aux hommes, mais en simplicité de coeur, craignant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Et quelque chose que vous fassiez, faites tout de bon coeur, comme le faisant pour le Seigneur, et non pas pour les hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Sachant que vous recevrez du Seigneur le salaire de l’héritage: car vous servez Christ le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Mais celui qui agit injustement, recevra ce qu’il aura fait injustement; car en Dieu il n’y a point d’égard à l’apparence des personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Maîtres, rendez le droit et l’équité à vos serviteurs, sachant que vous avez aussi un Seigneur dans les Cieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Persévérez dans la prière, veillant dans cet exercice avec des actions de grâces:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Priez aussi tous ensemble pour nous, afin que Dieu nous ouvre la porte de la parole, pour annoncer le mystère de Christ, pour lequel aussi je suis prisonnier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'Afin que je le manifeste selon qu’il faut que j’en parle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Conduisez-vous sagement envers ceux de dehors, rachetant le temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Que votre parole soit toujours assaisonnée de sel avec grâce, afin que vous sachiez comment vous avez à répondre à chacun.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Tychique, notre frère bien-aimé, et fidèle Ministre, et compagnon de service en notre Seigneur, vous fera savoir tout mon état.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Je l’ai envoyé vers vous expressément, afin qu’il connaisse quel est votre état, et qu’il console vos coeurs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Avec Onésime notre fidèle et bien-aimé frère, qui est des vôtres, ils vous avertiront de toutes les affaires de deçà.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Aristarque, qui est prisonnier avec moi, vous salue aussi, et Marc qui est le cousin de Barnabas, touchant lequel vous avez reçu un ordre: s’il vient à vous, recevez-le,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'Et Jésus, appelé Juste, qui sont de la Circoncision; ceux-ci qui sont mes compagnons d’oeuvre au Royaume de Dieu, sont aussi les seuls qui m’ont été en consolation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Epaphras, qui est des vôtres, Serviteur de Christ, vous salue, combattant toujours pour vous par ses prières, afin que vous demeuriez parfaits et accomplis en toute la volonté de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Car je lui rends témoignage qu’il a un grand zèle pour vous, et pour ceux de Laodicée, et pour ceux d’Hiérapolis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Luc, le médecin bien-aimé, vous salue; et Démas aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Saluez les frères qui sont à Laodicée, et Nymphas, avec l’Eglise qui est en sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Et quand cette Lettre aura été lue entre vous, faites qu’elle soit aussi lue dans l’Eglise des Laodiciens; et vous aussi lisez celle qui est venue de Laodicée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Et dites à Archippe: prends garde à l’administration que tu as reçue en notre Seigneur, afin que tu l’accomplisses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'La salutation est de la propre main de moi Paul. Souvenez-vous de mes liens. Que la grâce soit avec vous! Amen! ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paul, et Silvain, et Timothée, à l’Eglise des Thessaloniciens qui est en Dieu le Père, et en notre Seigneur Jésus-Christ: que la grâce et la paix vous soient données par Dieu notre Père, et par le Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Nous rendons toujours grâces à Dieu pour vous tous, faisant mention de vous dans nos prières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'Et nous remettant sans cesse en mémoire l’oeuvre de votre foi; le travail de votre charité, et la patience de votre espérance, que vous avez en notre Seigneur Jésus-Christ, devant notre Dieu et Père;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Sachant, mes frères bien-aimés de Dieu, votre élection.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Car la prédication que nous avons faite de l’Evangile au milieu de vous, n’a pas été en parole seulement, mais aussi en vertu, et en Saint-Esprit, et en preuves convaincantes, ainsi que vous savez quels nous avons été parmi vous pour l’amour de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Aussi avez-vous été nos imitateurs, et du Seigneur, ayant reçu avec la joie du Saint-Esprit la parole, accompagnée de grande affliction;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Tellement que vous avez été pour modèle à tous les fidèles de la Macédoine, et de l’Achaïe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Car la parole du Seigneur a retenti de chez vous, non-seulement dans la Macédoine et dans l’Achaïe, mais aussi en tous lieux; et votre foi envers Dieu est si célèbre, qu’il ne nous est pas besoin d’en rien dire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Car eux-mêmes racontent de nous quel accès nous avons eu auprès de vous, et comment vous avez été convertis des idoles à Dieu, pour servir le Dieu vivant et vrai;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'Et pour attendre des Cieux son Fils Jésus, qu’il a ressuscité des morts, et qui nous délivre de la colère à venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Car, mes frères, vous savez vous-mêmes que notre entrée au milieu de vous n’a point été vaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Mais quoique nous eussions été auparavant affligés et outragés à Philippes, comme vous savez, nous avons eu le courage, appuyés sur notre Dieu de vous annoncer l’Evangile de Dieu au milieu de grands combats.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Car il n’y a eu dans l’exhortation que nous vous avons faite, ni séduction, ni mauvais motif, ni fraude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'Mais comme nous avons été approuvés de Dieu, afin que la prédication de l’Evangile nous fût commise, nous parlons aussi non comme voulant plaire aux hommes, mais à Dieu, qui approuve nos coeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Car aussi nous n’avons jamais été surpris en parole de flatterie, comme vous le savez, ni en prétexte d’avarice; Dieu en est témoin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Et nous n’avons point cherché la gloire de la part des hommes, ni de vous, ni des autres; quoique nous eussions pu montrer de l’autorité comme Apôtres de Christ:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Mais nous avons été doux au milieu de vous, comme une nourrice qui nourrit tendrement ses enfants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Etant donc ainsi affectionnés envers vous, nous souhaitions de vous donner non-seulement l’Evangile de Dieu, mais aussi nos propres âmes, parce que vous étiez fort aimés de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Car, mes frères, vous vous souvenez de notre peine et de notre travail; vu que nous vous avons prêché l’Evangile de Dieu, en travaillant nuit et jour, pour n’être point à charge à aucun de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Vous êtes témoins, et Dieu aussi, comment nous nous sommes conduits saintement et justement, et sans reproche envers vous qui croyez;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Et vous savez que nous avons exhorté chacun de vous, comme un père exhorte ses enfants;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'Et que nous vous avons conjuré de vous conduire dignement, comme il est séant selon Dieu, qui vous appelle à son Royaume et à sa gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'C’est pourquoi nous rendons sans cesse grâces à Dieu, de ce que quand vous avez reçu de nous la parole de la prédication de Dieu, vous l’avez reçue non comme une parole des hommes, mais (ainsi qu’elle est véritablement) comme la parole de Dieu, laquelle aussi agit avec efficace en vous qui croyez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Car, mes frères, vous avez imité les Eglises de Dieu qui sont dans la Judée en Jésus-Christ, parce que vous avez aussi souffert les mêmes choses de ceux de votre propre nation, comme eux aussi de la part des Juifs;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'Qui ont même mis à mort le Seigneur Jésus, et leurs propres Prophètes, et qui nous ont chassés; et qui déplaisent à Dieu, et qui sont ennemis de tous les hommes:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'Nous empêchant de parler aux Gentils afin qu’ils soient sauvés; comblant ainsi toujours la mesure de leurs péchés. Or la colère de Dieu est parvenue sur eux jusqu’au plus haut degré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Et pour nous, mes frères, qui avons été séparés de vous en un moment de temps, de vue, et non de coeur, nous avons d’autant plus tâché de vous aller voir, que nous en avions un fort grand désir:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'C’est pourquoi nous avons voulu aller vers vous, au moins moi Paul, une ou deux fois; mais Satan nous en a empêchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Car quelle est notre espérance, ou notre joie, ou notre couronne de gloire? n’est-ce pas vous qui l’êtes devant notre Seigneur Jésus- Christ au jour de son avènement?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Certes vous êtes notre gloire et notre joie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'C’est pourquoi ne pouvant plus soutenir la privation de vos nouvelles nous avons trouvé bon de demeurer seuls à Athènes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'Et nous avons envoyé Timothée, notre frère, Ministre de Dieu, et notre compagnon d’oeuvre en l’Evangile de Christ, pour vous affermir, et vous exhorter touchant votre foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'Afin que nul ne soit troublé dans ces afflictions, puisque vous savez vous-mêmes que nous sommes destinés à cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Car quand nous étions avec vous, nous vous prédisions que nous aurions à souffrir des afflictions; comme cela est aussi arrivé, et vous le savez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'C’est pourquoi, dis-je, ne pouvant plus soutenir cette inquiétude j’ai envoyé Timothée pour reconnaître l’état de votre foi, de peur que celui qui tente, ne vous eût tentés en quelque sorte, et que notre travail ne fût rendu inutile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Or Timothée étant revenu depuis peu de chez vous, il nous a apporté d’agréables nouvelles de votre foi et de votre charité, et que vous vous souvenez toujours de nous, désirant fort de nous voir, comme nous aussi nous désirons de vous voir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'C’est pourquoi, mes frères, vous nous avez été en grande consolation à cause de votre foi, dans toute notre affliction, et dans notre nécessité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Car maintenant nous vivons, si vous vous tenez fermes au Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Et quelles actions de grâces n’avons-nous point à rendre à Dieu à cause de vous, pour toute la joie que nous recevons de vous, devant notre Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Le priant jour et nuit de plus en plus que nous puissions vous revoir, afin de suppléer à ce qui manque à votre foi?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Or notre Dieu et notre Père, et notre Seigneur Jésus-Christ, veuillent nous ouvrir le chemin pour nous rendre auprès de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Et le Seigneur vous fasse croître et abonder de plus en plus en charité les uns envers les autres, et envers tous, comme nous abondons aussi en charité envers vous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'Pour affermir vos coeurs sans reproche en sainteté, devant Dieu qui est notre Père, à la venue de notre Seigneur Jésus-Christ, accompagné de tous ses Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Au reste, mes frères, nous vous prions donc, et nous vous conjurons par le Seigneur Jésus, que comme vous avez appris de nous de quelle manière on doit se conduire, et plaire à Dieu, vous y fassiez tous les jours de nouveaux progrès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Car vous savez quels préceptes nous vous avons donnés de la part du Seigneur Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Parce que c’est ici la volonté de Dieu; savoir votre sanctification, et que vous vous absteniez de la fornication.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'Afin que chacun de vous sache posséder son vaisseau en sanctification et en honneur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'Et sans se laisser aller aux désirs de la convoitise, comme les Gentils qui ne connaissent point Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'Que personne ne foule son frère, ou ne fasse son profit au dommage de son frère en aucune affaire; parce que le Seigneur est le vengeur de toutes ces choses, comme nous vous l’avons dit auparavant, et comme nous vous l’avons assuré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Car Dieu ne nous a point appelés à la souillure, mais à la sanctification.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'C’est pourquoi celui qui rejette ceci, ne rejette point un homme, mais Dieu, qui a aussi mis son Saint-Esprit en nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Quant à la charité fraternelle, vous n’avez pas besoin que je vous en écrive, parce que vous-mêmes vous êtes enseignés de Dieu à vous aimer l’un l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'Et c’est aussi ce que vous faites à l’égard de tous les frères qui sont par toute la Macédoine; mais, mes frères, nous vous prions de vous perfectionner tous les jours davantage,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'Et de tâcher de vivre paisiblement; de faire vos propres affaires, et de travailler de vos propres mains, ainsi que nous vous l’avons ordonné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'Afin que vous vous conduisiez honnêtement envers ceux de dehors, et que vous n’ayez besoin de rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Or, mes frères, je ne veux point que vous ignoriez ce qui regarde ceux qui dorment, afin que vous ne soyez point attristés comme les autres qui n’ont point d’espérance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Car si nous croyons que Jésus est mort, et qu’il est ressuscité; de même aussi ceux qui dorment en Jésus, Dieu les ramènera avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Car nous vous disons ceci par la parole du Seigneur, que nous qui vivrons et resterons à la venue du Seigneur, ne préviendrons point ceux qui dorment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Car le Seigneur lui-même avec un cri d’exhortation, et une voix d’Archange, et avec la trompette de Dieu descendra du Ciel; et ceux qui sont morts en Christ ressusciteront premièrement;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Puis nous qui vivrons et qui resterons, serons enlevés ensemble avec eux dans les nuées, au-devant du Seigneur, en l’air et ainsi nous serons toujours avec le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'C’est pourquoi consolez-vous l’un l’autre par ces paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Or touchant le temps et le moment, mes frères, vous n’avez pas besoin qu’on vous en écrive;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Puisque vous savez vous-mêmes très-bien que le jour du Seigneur viendra comme le larron en la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Car quand ils diront: nous sommes en paix et en sûreté, alors il leur surviendra une subite destruction, comme le travail à celle qui est enceinte; et ils n’échapperont point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Mais quant à vous, mes frères, vous n’êtes point dans les ténèbres de sorte que ce jour-là vous surprenne comme le larron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Vous êtes tous des enfants de la lumière, et du jour; nous ne sommes point de la nuit, ni des ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Ainsi donc ne dormons point comme les autres, mais veillons, et soyons sobres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Car ceux qui dorment, dorment la nuit; et ceux qui s’enivrent, s’enivrent la nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Mais nous qui sommes enfants du jour, soyons sobres, étant revêtus de la cuirasse de la foi et de la charité, et ayant pour casque l’espérance du salut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Car Dieu ne nous a point destinés à la colère, mais à l’acquisition du salut par notre Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'Qui est mort pour nous, afin que soit que nous veillons, soit que nous dormions, nous vivions avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'C’est pourquoi exhortez-vous l’un l’autre, et édifiez-vous tous l’un l’autre, comme aussi vous le faites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Or, mes frères, nous vous prions de reconnaître ceux qui travaillent parmi vous, et qui président sur vous en notre Seigneur, et qui vous exhortent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'et d’avoir un amour singulier pour eux, à cause de l’oeuvre qu’ils font. Soyez en paix entre vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Nous vous prions aussi, mes frères, de reprendre les déréglés; de consoler ceux qui ont l’esprit abattu; de soulager les faibles, et d’être d’un esprit patient envers tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Prenez garde que nul ne rende à personne le mal pour le mal; mais cherchez toujours ce qui est bon, et entre vous et à l’égard de tous les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Soyez toujours joyeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Priez sans cesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Rendez grâces pour toutes choses, car c’est la volonté de Dieu par Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'N’éteignez point l’Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Ne méprisez point les prophéties.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Eprouvez toutes choses; retenez ce qui est bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Abstenez-vous de toute apparence de mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Or le Dieu de paix vous veuille sanctifier entièrement; et faire que votre esprit entier, et l’âme et le corps soient conservés sans reproche en la venue de notre Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Celui qui vous appelle est fidèle, c’est pourquoi il fera ces choses en vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Mes frères, priez pour nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Saluez tous les frères par un saint baiser.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Je vous conjure par le Seigneur que cette Epître soit lue à tous les saints frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Que la grâce de notre Seigneur Jésus-Christ soit avec vous; Amen! ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paul, et Silvain, et Timothée: à l’Eglise des Thessaloniciens qui est en Dieu notre Père, et en notre Seigneur Jésus-Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Que la grâce et la paix vous soient données de la part de Dieu notre Père, et de la part du Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Mes frères, nous devons toujours rendre grâces à Dieu à cause de vous, comme il est bien raisonnable, parce que votre foi s’augmente beaucoup, et que votre charité mutuelle fait des progrès.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'De sorte que nous-mêmes nous nous glorifions de vous dans les Eglises de Dieu, à cause de votre patience et de votre foi dans toutes vos persécutions, et dans les afflictions que vous soutenez;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Qui sont une manifeste démonstration du juste jugement de Dieu; afin que vous soyez estimés dignes du Royaume de Dieu, pour lequel aussi vous souffrez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Puisque c’est une chose juste devant Dieu, qu’il rende l’affliction à ceux qui vous affligent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'Et qu’il vous donne du relâche à vous qui êtes affligés, de même qu’à nous, lorsque le Seigneur Jésus sera révélé du Ciel avec les Anges de sa puissance;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'Avec des flammes de feu, exerçant la vengeance contre ceux qui ne connaissent point Dieu, et contre ceux qui n’obéissent point à l’Evangile de notre Seigneur Jésus-Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Lesquels seront punis d’une perdition éternelle, par la présence du Seigneur, et par la gloire de sa force;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'Quand il viendra pour être glorifié en ce jour-là dans ses saints, et pour être rendu admirable en tous ceux qui croient; parce que vous avez cru le témoignage que nous vous en avons rendu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'C’est pourquoi nous prions toujours pour vous, que notre Dieu vous rende dignes de sa vocation, et qu’il accomplisse puissamment en vous tout le bon plaisir de sa bonté, et l’oeuvre de la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'Afin que le Nom de notre Seigneur Jésus-Christ soit glorifié en vous, et vous en lui, selon la grâce de notre Dieu, et du Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Or, mes frères, nous vous prions pour ce qui regarde l’avènement de notre Seigneur Jésus-Christ, et notre réunion en lui,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'De ne vous laisser point subitement ébranler de votre sentiment, ni troubler par esprit, ni par parole, ni par épître, comme si c’était une épître que nous eussions écrite, et comme si le jour de Christ était proche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Que personne donc ne vous séduise en quelque manière que ce soit; car ce jour-là ne viendra point que la révolte ne soit arrivée auparavant, et que l’homme de péché, le fils de perdition, ne soit révélé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'Lequel s’oppose et s’élève contre tout ce qui est nommé Dieu, ou qu’on adore, jusqu’à être assis comme Dieu au Temple de Dieu voulant se faire passer pour un Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Ne vous souvient-il pas que quand j’étais encore avec vous, je vous disais ces choses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Mais maintenant vous savez ce qui le retient, afin qu’il soit révélé en son temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Car déjà le mystère d’iniquité se met en train, seulement celui qui obtient maintenant, obtiendra jusqu’à ce qu’il soit aboli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Et alors le méchant sera révélé, mais le Seigneur le détruira par l’Esprit de sa bouche, et l’anéantira par son illustre avènement:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Et quant à l’avènement du méchant, il est selon l’efficace de Satan, en toute puissance, en prodiges et en miracles de mensonge;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'Et en toute séduction d’iniquité, dans ceux qui périssent; parce qu’ils n’ont pas reçu l’amour de la vérité, pour être sauvés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'C’est pourquoi Dieu leur enverra une erreur efficace, de sorte qu’ils croiront au mensonge;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'Afin que tous ceux-là soient jugés qui n’ont point cru à la vérité, mais qui ont pris plaisir à l’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Mais, mes frères, les bien-aimés du Seigneur, nous devons toujours rendre grâces à Dieu pour vous, de ce que Dieu vous a élus dès le commencement pour le salut par la sanctification de l’Esprit, et par la foi de la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'A quoi il vous a appelés par notre Evangile, afin que vous possédiez la gloire qui nous a été acquise par notre Seigneur Jésus- Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'C’est pourquoi, mes frères, demeurez fermes, et retenez les enseignements que vous avez appris, soit par notre parole, soit par notre épître.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Or lui-même Jésus-Christ, notre Seigneur, et notre Dieu et Père, qui nous a aimés, et qui nous a donné une consolation éternelle, et une bonne espérance par sa grâce,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'Veuille consoler vos coeurs, et vous affermir en toute bonne parole, et en toute bonne oeuvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Au reste, mes frères, priez pour nous, afin que la parole du Seigneur ait son cours, et qu’elle soit glorifiée comme elle l’est parmi vous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'Et que nous soyons délivrés des hommes fâcheux et méchants; car la foi n’est point de tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Or le Seigneur est fidèle, qui vous affermira, et vous gardera du mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Aussi nous assurons-nous de vous par le Seigneur, que vous faites, et que vous ferez toutes les choses que nous vous commandons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Or le Seigneur veuille diriger vos coeurs à l’amour de Dieu, et à l’attente de Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Nous vous recommandons aussi, mes frères, au Nom de notre Seigneur Jésus-Christ, de vous retirer de tout frère qui se conduit d’une manière irrégulière, et non pas selon l’enseignement qu’il a reçu de nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Car vous savez vous-mêmes comment il faut que vous nous imitiez; vu qu’il n’y a eu rien d’irrégulier dans la manière dont nous nous sommes conduits parmi vous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'Et que nous n’avons mangé gratuitement le pain de personne, mais dans le travail et dans la peine, travaillant nuit et jour, afin de ne charger aucun de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Non que nous n’en ayons bien le pouvoir, mais afin de nous donner nous-mêmes à vous pour modèle, afin que vous nous imitiez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Car aussi quand nous étions avec vous, nous vous dénoncions ceci: que si quelqu’un ne veut pas travailler, qu’il ne mange point aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Car nous apprenons qu’il y en a quelques-uns parmi vous qui se conduisent d’une manière déréglée, ne faisant rien, mais vivant dans la curiosité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Nous dénonçons donc à ceux qui sont tels, et nous les exhortons par notre Seigneur Jésus-Christ, qu’en travaillant ils mangent leur pain paisiblement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Mais pour vous, mes frères, ne vous lassez point en bien faisant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Et si quelqu’un n’obéit point à notre parole, renfermée dans cette Epître, faites-le connaître; et ne conversez point avec lui, afin qu’il en ait honte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Toutefois ne le tenez point comme un ennemi, mais avertissez-le comme un frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Or le Seigneur de paix vous donne toujours la paix en toute manière! Le Seigneur soit avec vous tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'La salutation qui est de la propre main de moi Paul, et qui est un signe dans toutes mes Epîtres, c’est que j’écris ainsi:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Que la grâce de notre Seigneur Jésus Christ soit avec vous tous, Amen. ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paul Apôtre de Jésus-Christ par le commandement de Dieu notre Sauveur, et du Seigneur Jésus-Christ, notre espérance:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'A Timothée mon vrai fils en la foi; que la grâce, la miséricorde et la paix te soient données de la part de Dieu notre Père, et de la part de Jésus-Christ notre Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Suivant la prière que je te fis de demeurer à Ephèse, lorsque j’allais en Macédoine, je te prie encore d’annoncer à certaines personnes de n’enseigner point une autre doctrine;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'Et de ne s’adonner point aux fables et aux généalogies, qui sont sans fin, et qui produisent plutôt des disputes, que l’édification de Dieu, laquelle consiste en la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Or la fin du Commandement, c’est la charité qui procède d’un coeur pur, et d’une bonne conscience, et d’une foi sincère:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Desquelles choses quelques-uns s’étant écartés, se sont détournés à un vain babil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'Voulant être docteurs de la Loi, mais n’entendant point ni ce qu’ils disent, ni ce qu’ils assurent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Or nous savons que la Loi est bonne, si quelqu’un en use légitimement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'Sachant ceci, que la Loi n’est point donnée pour le juste, mais pour les iniques, et pour ceux qui ne se peuvent point ranger; pour ceux qui sont sans piété, et qui vivent mal; pour des gens sans religion, et pour les profanes; pour les meurtriers de père et de mère, et pour les homicides;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'Pour les fornicateurs, pour ceux qui commettent des péchés contre nature, pour ceux qui dérobent des hommes, pour les menteurs, pour les parjures, et contre telle autre chose qui est contraire à la saine doctrine;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'Suivant l’Evangile de la gloire de Dieu bienheureux, lequel Evangile m’a été commis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Et je rends grâces à celui qui m’a fortifié, c’est-à-dire, à Jésus-Christ notre Seigneur, de ce qu’il m’a estimé fidèle, m’ayant établi dans le Ministère;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Moi qui auparavant étais un blasphémateur, et un persécuteur, et un oppresseur, mais j’ai obtenu miséricorde parce que j’ai agi par ignorance, étant dans l’infidélité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Or la grâce de Notre-Seigneur a surabondé en moi, avec la foi, et avec l’amour qui est en Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Cette parole est certaine, et digne d’être entièrement reçue, que Jésus-Christ est venu au monde pour sauver les pécheurs, desquels je suis le premier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Mais j’ai obtenu grâce, afin que Jésus-Christ montrât en moi le premier toute sa clémence, pour servir d’exemple à ceux qui viendront à croire en lui pour la vie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Or au Roi des siècles, immortel, invisible, à Dieu seul sage soit honneur et gloire aux siècles des siècles, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Mon fils Timothée, je te recommande ce commandement, que conformément aux prophéties qui auparavant ont été faites de toi, tu t’acquittes, selon elles, du devoir de combattre en cette bonne guerre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Gardant la foi avec une bonne conscience, laquelle quelques-uns ayant rejetée, ont fait naufrage quant à la foi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Entre lesquels sont Hyménée et Alexandre, que j’ai livrés à satan, afin qu’ils apprennent par ce châtiment à ne plus blasphémer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'J’exhorte donc qu’avant toutes choses on fasse des requêtes, des prières, des supplications, et des actions de grâces pour tous les hommes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'Pour les Rois, et pour tous ceux qui sont constitués en dignité, afin que nous puissions mener une vie paisible et tranquille, en toute piété et honnêteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Car cela est bon et agréable devant Dieu notre Sauveur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'Qui veut que tous les hommes soient sauvés, et qu’ils viennent à la connaissance de la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Car il y a un seul Dieu, et un seul Médiateur entre Dieu et les hommes, savoir Jésus-Christ homme;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Qui s’est donné soi-même en rançon pour tous, témoignage qui a été rendu en son temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'C’est dans cette vue que j’ai été établi Prédicateur, Apôtre (je dis la vérité en Christ, je ne mens point), et Docteur des Gentils en la foi, et en la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Je veux donc que les hommes prient en tout lieu, levant leurs mains pures, sans colère, et sans dispute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Que les femmes aussi se parent d’un vêtement honnête, avec pudeur et modestie, non point avec des tresses ni avec de l’or, ni des perles, ni des habillements somptueux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'Mais qu’elles soient ornées de bonnes oeuvres, comme il est séant à des femmes qui font profession de servir Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Que la femme apprenne dans le silence en toute soumission.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Car je ne permets point à la femme d’enseigner, ni d’user d’autorité sur le mari; mais elle doit demeurer dans le silence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Car Adam a été formé le premier, et puis Eve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'Et ce n’a point été Adam qui a été séduit, mais la femme ayant été séduite, a été la cause de la transgression.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Elle sera néanmoins sauvée en mettant des enfants au monde, pourvu qu’elle persévère dans la foi, dans la charité, et dans la sanctification, avec modestie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Cette parole est certaine, qui si quelqu’un désire d’être Evêque, il désire une oeuvre excellente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Mais il faut que l’Evêque soit irrépréhensible, mari d’une seule femme, vigilant, modéré, honorable, hospitalier, propre à enseigner;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Non sujet au vin, non batteur, non convoiteux d’un gain déshonnête, mais doux, non querelleur, non avare.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Conduisant honnêtement sa propre maison, tenant ses enfants soumis en toute pureté de moeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'Car si quelqu’un ne sait pas conduire sa propre maison, comment pourra-t-il gouverner l’Eglise de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Qu’il ne soit point nouvellement converti; de peur qu’étant enflé d’orgueil, il ne tombe dans la condamnation du calomniateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Il faut aussi qu’il ait un bon témoignage de ceux de dehors, qu’il ne tombe point dans des fautes qui puissent lui être reprochées, et dans le piége du Démon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Que les Diacres aussi soient graves, non doubles en parole, non sujets à beaucoup de vin, non convoiteux d’un gain déshonnête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Retenant le mystère de la foi dans une conscience pure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Que ceux-ci aussi soient premièrement éprouvés, et qu’ensuite ils servent, après avoir été trouvés sans reproche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'De même, que leurs femmes soient honnêtes, non médisantes, sobres, fidèles en toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Que les Diacres soient maris d’une seule femme, conduisant honnêtement leurs enfants, et leurs propres familles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Car ceux qui auront bien servi, acquièrent un bon degré pour eux, et une grande liberté dans la foi qui est en Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Je t’écris ces choses espérant que j’irai bientôt vers toi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'Mais en cas que je tarde, je t’écris ces choses afin que tu saches comment il faut se conduire dans la Maison de Dieu, qui est l’Eglise du Dieu vivant, la Colonne et l’appui de la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Et sans contredit, le mystère de la piété est grand, savoir, que Dieu a été manifesté en chair, justifié en Esprit, vu des Anges, prêché aux Gentils, cru au monde, et élevé dans la gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Or l’Esprit dit expressément qu’aux derniers temps quelques-uns se révolteront de la foi, s’adonnant aux Esprits séducteurs, et aux doctrines des Démons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'Enseignant des mensonges par hypocrisie, et ayant une conscience cautérisée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Défendant de se marier, commandant de s’abstenir des viandes que Dieu a créées pour les fidèles, et pour ceux qui ont connu la vérité, afin d’en user avec des actions de grâces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Car toute créature de Dieu est bonne, et il n’y en a point qui soit à rejeter, étant prise avec action de grâces.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Parce qu’elle est sanctifiée par la parole de Dieu, et par la prière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Si tu proposes ces choses aux frères, tu seras bon Ministre de Jésus-Christ, nourri dans les paroles de la foi et de la bonne doctrine que tu as soigneusement suivie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Mais rejette les fables profanes, et semblables aux récits des personnes dont l’Esprit est affaibli; et exerce-toi dans la piété.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Car l’exercice corporel est utile à peu de chose, mais la piété est utile à toutes choses, ayant les promesses de la vie présente, et de celle qui est à venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'C’est là une parole certaine, et digne d’être entièrement reçue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Car c’est aussi pour cela que nous travaillons, et que nous sommes en opprobre, vu que nous espérons au Dieu vivant, qui est le conservateur de tous les hommes, mais principalement des fidèles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Annonce ces choses, et les enseigne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Que personne ne méprise ta jeunesse; mais sois le modèle des fidèles en paroles, en conduite, en charité, en esprit, en foi, en pureté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Sois attentif à la lecture, à l’exhortation, et à l’instruction, jusqu’à ce que je vienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Ne néglige point le don qui est en toi, et qui t’a été conféré suivant la prophétie, par l’imposition des mains de la compagnie des Anciens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Pratique ces choses, et y sois attentif, afin qu’il soit connu à tous que tu profites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Prends garde à toi, et à la doctrine, persévère en ces choses, car en faisant cela tu te sauveras, et ceux qui t’écoutent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Ne reprends pas rudement l’homme âgé, mais exhorte-le comme un père; les jeunes gens comme des frères;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'Les femmes âgées, comme des mères; les jeunes, comme des soeurs, en toute pureté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Honore les veuves qui sont vraiment veuves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Mais si quelque veuve a des enfants, ou des enfants de ses enfants, qu’ils apprennent premièrement à montrer leur piété envers leur propre maison, et à rendre la pareille à ceux dont ils sont descendus: car cela est bon et agréable devant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Or celle qui est vraiment veuve, et qui est laissée seule, espère en Dieu, et persévère en prières et en oraisons nuit et jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Mais celle qui vit dans les délices, est morte en vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Avertis-les donc de ces choses, afin qu’elles soient irrépréhensibles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Que si quelqu’un n’a pas soin des siens, et principalement de ceux de sa famille, il a renié la foi, et il est pire qu’un infidèle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Que la veuve soit enregistrée n’ayant pas moins de soixante ans, et n’ayant eu qu’un seul mari;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'Ayant le témoignage d’avoir fait de bonnes oeuvres, comme d’avoir nourri ses propres enfants, d’avoir logé les étrangers, d’avoir lavé les pieds des Saints, d’avoir secouru les affligés, et de s’être ainsi constamment appliquée à toutes sortes de bonnes oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Mais refuse les veuves qui sont plus jeunes; car quand elles sont devenues lascives contre Christ, elles se veulent marier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Ayant leur condamnation, en ce qu’elles ont faussé leur première foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Et avec cela aussi étant oisives, elles apprennent à aller de maison en maison; et sont non-seulement oisives, mais aussi causeuses, et curieuses, discourant de choses malséantes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Je veux donc que les jeunes veuves se marient, qu’elles aient des enfants, qu’elles gouvernent leur ménage, et qu’elles ne donnent aucune occasion à l’adversaire de médire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Car quelques-unes se sont déjà détournées après satan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Que si quelque homme ou quelque femme fidèle a des veuves, qu’ils les assistent, mais que l’Eglise n’en soit point chargée, afin qu’il y ait assez pour celles qui sont vraiment veuves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Que les Anciens qui président dûment, soient réputés dignes d’un double honneur; principalement ceux qui travaillent à la prédication, et à l’instruction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Car l’Ecriture dit: tu n’emmuselleras point le boeuf qui foule le grain; et l’ouvrier est digne de son salaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Ne reçois point d’accusation contre l’Ancien, que sur la déposition de deux ou de trois témoins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Reprends publiquement ceux qui pèchent, afin que les autres aussi en aient de la crainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Je te conjure devant Dieu, et devant le Seigneur Jésus-Christ, et devant les Anges élus, de garder ces choses sans préférer l’un à l’autre, ne faisant rien en penchant d’un côté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'N’impose les mains à personne avec précipitation; et ne participe point aux péchés d’autrui; garde-toi pur toi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Ne bois plus uniquement de l’eau, mais use d’un peu de vin à cause de ton estomac, et des maladies que tu as souvent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Les péchés de quelques-uns se manifestent auparavant, et précèdent pour leur condamnation; mais en d’autres ils suivent après.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Les bonnes oeuvres aussi se manifestent auparavant, et celles qui sont autrement ne peuvent point être cachées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Que tous les esclaves sachent qu’ils doivent à leurs maîtres toute sorte d’honneur, afin qu’on ne blasphème point le Nom de Dieu, et sa doctrine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Que ceux aussi qui ont des maîtres fidèles, ne les méprisent point sous prétexte qu’ils sont leurs frères, mais plutôt qu’ils les servent à cause qu’ils sont fidèles, et bien-aimés de Dieu, étant participants de la grâce; enseigne ces choses, et exhorte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Si quelqu’un enseigne autrement, et ne se soumet point aux saines paroles de notre Seigneur Jésus-Christ, et à la doctrine qui est selon la piété,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'Il est enflé d’orgueil, ne sachant rien, mais il est malade après des questions et des disputes de paroles, d’où naissent des envies, des querelles, des médisances, et de mauvais soupçons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'De vaines disputes d’hommes corrompus d’entendement, et privés de la vérité, qui estiment que la piété est un moyen de gagner: retire- toi de ces sortes de gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Or la piété avec le contentement d’esprit, est un grand gain.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Car nous n’avons rien apporté au monde, et aussi il est évident que nous n’en pouvons rien emporter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Mais ayant la nourriture, et de quoi nous puissions être couverts, cela nous suffira.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Or ceux qui veulent devenir riches, tombent dans la tentation, et dans le piége, et en plusieurs désirs fous et nuisibles, qui plongent les hommes dans le malheur, et dans la perdition.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Car c’est la racine de tous les maux que la convoitise des richesses, de laquelle quelques-uns étant possédés, ils se sont détournés de la foi, et se sont enserrés eux-mêmes dans plusieurs douleurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Mais toi, homme de Dieu! fuis ces choses, et recherche la justice, la piété, la foi, la charité, la patience, la douceur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Combats le bon combat de la foi; saisis la vie éternelle, à laquelle aussi tu es appelé, et dont tu as fait une belle profession devant beaucoup de témoins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Je t’ordonne devant Dieu, qui donne la vie à toutes choses; et devant Jésus-Christ, qui a fait cette belle confession devant Ponce Pilate,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'De garder ce commandement, en te conservant sans tache et irrépréhensible, jusques à l’apparition de notre Seigneur Jésus- Christ,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Laquelle le bienheureux et seul Prince, Roi des Rois, et Seigneur des Seigneurs, montrera en sa propre saison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'Lui qui seul possède l’immortalité, et qui habite une lumière inaccessible, lequel nul des hommes n’a vu, et ne peut voir; et auquel soit l’honneur et la force éternelle, Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Dénonce à ceux qui sont riches en ce monde, qu’ils ne soient point hautains, et qu’ils ne mettent point leur confiance dans l’incertitude des richesses, mais au Dieu vivant, qui nous donne toutes choses abondamment pour en jouir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Qu’ils fassent du bien; qu’ils soient riches en bonnes oeuvres; qu’ils soient prompts à donner, libéraux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'Se faisant un trésor pour l’avenir, appuyé sur un fondement solide, afin qu’ils obtiennent la vie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Timothée, garde le dépôt; en fuyant les disputes vaines et profanes, et les contradictions d’une science faussement ainsi nommée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'De laquelle quelques-uns faisant profession, se sont détournés de la foi. Que la grâce soit avec toi, Amen! ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paul Apôtre de Jésus-Christ, par la volonté de Dieu, selon la promesse de la vie qui est en Jésus-Christ:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'A Timothée, mon fils bien-aimé, que la grâce, la miséricorde et la paix te soient données de la part de Dieu le Père, et de la part de Jésus-Christ notre Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Je rends grâces à Dieu, lequel je sers dès mes ancêtres avec une pure conscience, faisant sans cesse mention de toi dans mes prières nuit et jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Me souvenant de tes larmes, je désire fort de te voir afin que je sois rempli de joie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Et me souvenant de la foi sincère qui est en toi, et qui a premièrement habité en Loïs, ta grand-mère, et en Eunice, ta mère, et je suis persuadé qu’elle habite aussi en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'C’est pourquoi je t’exhorte de ranimer le don de Dieu, qui est en toi par l’imposition de mes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Car Dieu ne nous a pas donné un esprit de timidité, mais de force, de charité et de prudence.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Ne prends donc point à honte le témoignage de notre Seigneur, ni moi, qui suis son prisonnier; mais prends part aux afflictions de l’Evangile, selon la puissance de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Qui nous a sauvés, et qui nous a appelés par une sainte vocation, non selon nos oeuvres, mais selon son propre dessein, et selon la grâce qui nous a été donnée en Jésus-Christ avant les temps éternels;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'Et qui maintenant a été manifestée par l’apparition de notre Sauveur Jésus-Christ, qui a détruit la mort, et qui a mis en lumière la vie et l’immortalité par l’Evangile;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Pour lequel j’ai été établi Prédicateur, Apôtre, et Docteur des Gentils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'C’est pourquoi aussi je souffre ces choses; mais je n’en ai point de honte; car je connais celui en qui j’ai cru, et je suis persuadé qu’il est puissant pour garder mon dépôt jusqu’à cette journée-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Retiens le vrai patron des saines paroles que tu as entendues de moi, dans la foi et dans la charité qui est en Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Garde le bon dépôt par le Saint-Esprit qui habite en nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Tu sais ceci, que tous ceux qui sont en Asie, se sont éloignés de moi; entre lesquels sont Phygelle et Hermogène.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Le Seigneur fasse miséricorde à la maison d’Onésiphore: car souvent il m’a consolé, et il n’a point eu honte de ma chaîne;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Au contraire, quand il a été à Rome, il m’a cherché très soigneusement, et il m’a trouvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Le Seigneur lui fasse trouver miséricorde envers le Seigneur en cette journée-là; et tu sais mieux que personne combien il m’a rendu de services à Ephèse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Toi donc, mon fils, sois fortifié dans la grâce qui est en Jésus- Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Et les choses que tu as entendues de moi devant plusieurs témoins, commets-les à des personnes fidèles, qui soient capables de les enseigner aussi à d’autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Toi donc, endure les travaux, comme un bon soldat de Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Nul qui va à la guerre ne s’embarrasse des affaires de cette vie, afin qu’il plaise à celui qui l’a enrôlé pour la guerre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'De même, si quelqu’un combat dans la lice, il n’est point couronné s’il n’a pas combattu selon les lois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Il faut aussi que le laboureur travaille premièrement, et ensuite il recueille les fruits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Considère ce que je dis; or le Seigneur te donne de l’intelligence en toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Souviens-toi que Jésus-Christ, qui est de la semence de David, est ressuscité des morts, selon mon Evangile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'Pour lequel je souffre beaucoup de maux, jusqu’à être mis dans les chaînes, comme un malfaiteur; mais cependant la parole de Dieu n’est point liée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'C’est pourquoi je souffre tout pour l’amour des élus, afin qu’eux aussi obtiennent le salut qui est en Jésus-Christ, avec la gloire éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Cette parole est certaine, que si nous mourons avec lui, nous vivrons aussi avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'Si nous souffrons avec lui, nous régnerons aussi avec lui; si nous le renions, il nous reniera aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Si nous sommes des perfides, il demeure fidèle: il ne se peut renier soi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Remets ces choses en mémoire, protestant devant le Seigneur qu’on ne dispute point de paroles, qui est une chose dont il ne revient aucun profit, mais elle est la ruine des auditeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Etudie-toi de te rendre approuvé à Dieu, ouvrier sans reproche, enseignant purement la parole de la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Mais réprime les disputes vaines et profanes, car elles passeront plus avant dans l’impiété;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'Et leur parole rongera comme une gangrène, et entre ceux-là sont Hyménée et Philète;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'Qui se sont écartés de la vérité, en disant que la résurrection est déjà arrivée, et qui renversent la foi de quelques-uns.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Toutefois le fondement de Dieu demeure ferme, ayant ce sceau: le Seigneur connaît ceux qui sont siens; et, quiconque invoque le nom de Christ, qu’il se retire de l’iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Or dans une grande maison il n’y a pas seulement des vaisseaux d’or et d’argent, mais il y en a aussi de bois et de terre: les uns à honneur, et les autres à déshonneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Si quelqu’un donc se purifie de ces choses, il sera un vaisseau sanctifié à honneur, et utile au Seigneur, et préparé à toute bonne oeuvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Fuis aussi les désirs de la jeunesse, et recherche la justice, la foi, la charité, et la paix avec ceux qui invoquent d’un coeur pur le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Et rejette les questions folles, et qui sont sans instruction, sachant qu’elles ne font que produire des querelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Or il ne faut pas que le serviteur du Seigneur soit querelleur, mais doux envers tout le monde, propre à enseigner, supportant patiemment les mauvais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'Enseignant avec douceur ceux qui ont un sentiment contraire, afin d’essayer si quelque jour Dieu leur donnera la repentance pour reconnaître la vérité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'Et afin qu’ils se réveillent pour sortir des pièges du Démon, par lequel ils ont été pris pour faire sa volonté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Or sache ceci, qu’aux derniers jours il surviendra des temps fâcheux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Car les hommes seront idolâtres d’eux-mêmes, avares, vains, orgueilleux, blasphémateurs, désobéissants à leurs pères et à leurs mères, ingrats, profanes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'Sans affection naturelle, sans fidélité, calomniateurs, incontinents, cruels, haïssant les gens de bien;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'Traîtres, téméraires, enflés d’orgueil, amateurs des voluptés, plutôt que de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Ayant l’apparence de la piété, mais en ayant renié la force: éloigne-toi donc de telles gens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Or d’entre ceux-ci sont ceux qui se glissent dans les maisons, et qui tiennent captives les femmes chargées de péchés, et agitées de diverses convoitises;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'Qui apprennent toujours, mais qui ne peuvent jamais parvenir à la pleine connaissance de la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Et comme Jannès et Jambrès ont résisté à Moise, ceux-ci de même résistent à la vérité; étant des gens qui ont l’esprit corrompu, et qui sont réprouvés quant à la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Mais ils n’avanceront pas plus avant: car leur folie sera manifestée à tous, comme le fut celle de ceux-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Mais pour toi, tu as pleinement compris ma doctrine, ma conduite, mon intention, ma foi, ma douceur, ma charité, ma patience.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'Et tu sais les persécutions et les afflictions qui me sont arrivées à Antioche, à Iconie, et à Lystre, quelles persécutions, dis-je, j’ai soutenues, et comment le Seigneur m’a délivré de toutes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Or tous ceux aussi qui veulent vivre selon la piété en Jésus- Christ, souffriront persécution.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Mais les hommes méchants et séducteurs iront en empirant, séduisant, et étant séduits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Mais toi, demeure ferme dans les choses que tu as apprises, et qui t’ont été confiées, sachant de qui tu les as apprises;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'Vu même que dès ton enfance tu as la connaissance des saintes Lettres, qui te peuvent rendre sage à salut, par la foi en Jésus- Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Toute l’Ecriture est divinement inspirée, et utile pour enseigner, pour convaincre, pour corriger, et pour instruire selon la justice;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'Afin que l’homme de Dieu soit accompli, et parfaitement instruit pour toute bonne oeuvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Je te somme devant Dieu, et devant le Seigneur Jésus-Christ, qui doit juger les vivants et les morts, en son apparition et en son règne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Prêche la parole, insiste dans toutes les occasions; reprends, censure, exhorte avec toute douceur d’esprit, et avec doctrine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Car le temps viendra auquel ils ne souffriront point la saine doctrine, mais aimant qu’on leur chatouille les oreilles, par des discours agréables ils chercheront des Docteurs qui répondent à leurs désirs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'Et ils détourneront leurs oreilles de la vérité, et se tourneront aux fables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Mais toi, veille en toutes choses, souffre les afflictions, fais l’oeuvre d’un Evangéliste, rends ton Ministère pleinement approuvé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Car pour moi, je m’en vais maintenant être mis pour l’aspersion du sacrifice, et le temps de mon départ est proche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'J’ai combattu le bon combat, j’ai achevé la course, j’ai gardé la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Au reste, la couronne de justice m’est réservée, et le Seigneur, juste juge, me la rendra en cette journée-là, et non seulement à moi, mais aussi à tous ceux qui auront aimé son apparition.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Hâte-toi de venir bientôt vers moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Car Démas m’a abandonné, ayant aimé le présent siècle, et il s’en est allé à Thessalonique; Crescens est allé en Galatie; et Tite en Dalmatie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Luc est seul avec moi; prends Marc, et amène-le avec toi: car il m’est fort utile pour le Ministère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'J’ai aussi envoyé Tychique à Ephèse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Quand tu viendras apporte avec toi le manteau que j’ai laissé à Troas, chez Carpus, et les Livres aussi; mais principalement mes parchemins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Alexandre le forgeron m’a fait beaucoup de maux, le Seigneur lui rendra selon ses oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Garde-toi donc de lui, car il s’est fort opposé à nos paroles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Personne ne m’a assisté dans ma première défense, mais tous m’ont abandonné; toutefois que cela ne leur soit point imputé!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Mais le Seigneur m’a assisté, et fortifié, afin que ma prédication fût rendue pleinement approuvée, et que tous les Gentils l’ouïssent; et j’ai été délivré de la gueule du Lion.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Le Seigneur aussi me délivrera de toute mauvaise oeuvre, et me sauvera dans son Royaume céleste. A lui soit gloire aux siècles des siècles, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Salue Prisce et Aquilas, et la famille d’Onésiphore.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Eraste est demeuré à Corinthe, et j’ai laissé Trophime malade à Milet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Hâte-toi de venir avant l’hiver. Eubulus et Pudens, et Linus, et Claudia, et tous les frères, te saluent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Le Seigneur Jésus-Christ soit avec ton esprit. Que la grâce soit avec vous, Amen! La seconde Epître à Timothée qui a été établi le premier Evêque de l’Eglise des Ephésiens, a été écrite de Rome, quand Paul fut présenté la seconde fois à César Néron. ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paul, Serviteur de Dieu, et Apôtre de Jésus-Christ, selon la foi des élus de Dieu, et la connaissance de la vérité, qui est selon la piété;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'Sous l’espérance de la vie éternelle, laquelle Dieu, qui ne peut mentir, avait promise avant les temps éternels;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'Mais qu’il a manifestée en son propre temps, savoir sa parole, dans la prédication qui m’est commise, par le commandement de Dieu notre Sauveur:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'A Tite mon vrai fils, selon la foi qui nous est commune; que la grâce, la miséricorde, et la paix te soient données de la part de Dieu notre Père, et de la part du Seigneur Jésus-Christ, notre Sauveur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'La raison pour laquelle je t’ai laissé en Crète, c’est afin que tu achèves de mettre en bon ordre les choses qui restent à régler, et que tu établisses des Anciens de ville en ville, suivant ce que je t’ai ordonné;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'Ne choisissant aucun homme qui ne soit irrépréhensible, mari d’une seule femme, et dont les enfants soient fidèles, et non accusés de dissolution, ou qui ne se puissent ranger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Car il faut que l’Evêque soit irrépréhensible, comme étant dispensateur dans la Maison de Dieu, non adonné à son sens, non colère, non sujet au vin, non batteur, non convoiteux d’un gain déshonnête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'Mais hospitalier, aimant les gens de bien, sage, juste, saint, continent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'Retenant ferme la parole de la vérité comme elle lui a été enseignée, afin qu’il soit capable tant d’exhorter par la saine doctrine, que de convaincre les contredisants.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Car il y en a plusieurs qui ne se peuvent ranger, vains discoureurs, et séducteurs d’esprits, principalement ceux qui sont de la Circoncision auxquels il faut fermer la bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Et qui renversent les maisons tout entières enseignant pour un gain déshonnête des choses qu’on ne doit point enseigner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Quelqu’un d’entre eux, qui était leur propre prophète, a dit: Les Crétois sont toujours menteurs, de mauvaises bêtes, des ventres paresseux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Ce témoignage est véritable; c’est pourquoi reprends-les vivement, afin qu’ils soient sains en la foi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'Ne s’adonnant point aux fables Judaïques, et aux commandements des hommes qui se détournent de la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Toutes choses sont bien pures pour ceux qui sont purs, mais rien n’est pur pour les impurs et les infidèles, mais leur entendement et leur conscience sont souillés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Ils font profession de connaître Dieu, mais ils le renoncent par leurs oeuvres; car ils sont abominables, et rebelles, et réprouvés pour toute bonne oeuvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Mais toi, enseigne les choses qui conviennent à la saine doctrine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Que les vieillards soient sobres, graves, prudents, sains en la foi, en la charité, et en la patience.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'De même, que les femmes âgées règlent leur extérieur d’une manière convenable à la sainteté; qu’elles ne soient ni médisantes, ni sujettes à beaucoup de vin, mais qu’elles enseignent de bonnes choses;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'Afin qu’elles instruisent les jeunes femmes à être modestes, à aimer leurs maris, à aimer leurs enfants;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'A être sages, pures, gardant la maison, bonnes, soumises à leurs maris; afin que la parole de Dieu ne soit point blasphémée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Exhorte aussi les jeunes hommes à être modérés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'Te montrant toi-même pour modèle de bonnes oeuvres en toutes choses, en une doctrine exempte de toute altération, en gravité, en intégrité,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'En paroles saines, que l’on ne puisse point condamner, afin que celui qui vous est contraire, soit rendu confus, n’ayant aucun mal à dire de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Que les serviteurs soient soumis à leurs maîtres, leur complaisant en toutes choses, n’étant point contredisants;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'Ne détournant rien de ce qui appartient à leurs maîtres, mais faisant toujours paraître une grande fidélité, afin de rendre honorable en toutes choses la doctrine de Dieu, notre Sauveur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Car la grâce de Dieu salutaire à tous les hommes a été manifestée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'Nous enseignant qu’en renonçant à l’impiété et aux passions mondaines, nous vivions dans ce présent siècle, sobrement, justement et religieusement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'En attendant la bienheureuse espérance, et l’apparition de la gloire du grand Dieu, et notre Sauveur, Jésus-Christ,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'Qui s’est donné soi-même pour nous, afin de nous racheter de toute iniquité, et de nous purifier, pour lui être un peuple qui lui appartienne en propre, et qui soit zélé pour les bonnes oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Enseigne ces choses, exhorte et reprends avec toute autorité de commander. Que personne ne te méprise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Avertis-les d’être soumis aux Principautés et aux Puissances, d’obéir aux Gouverneurs, d’être prêts à faire toute sorte de bonnes actions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'De ne médire de personne; de n’être point querelleurs, mais doux, et montrant toute débonnaireté envers tous les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Car nous étions aussi autrefois insensés, rebelles, abusés, asservis à diverses convoitises et voluptés, vivant dans la malice et dans l’envie, dignes d’être haïs, et nous haïssant l’un l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Mais quand la bonté de Dieu notre Sauveur, et son amour envers les hommes ont été manifestés, il nous a sauvés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'Non par des oeuvres de justice que nous eussions faites, mais selon la miséricorde; par le baptême de la régénération, et le renouvellement du Saint-Esprit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'Lequel il a répandu abondamment en nous par Jésus-Christ notre Sauveur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'Afin qu’ayant été justifiés par sa grâce, nous soyons les héritiers de la vie éternelle selon notre espérance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Cette parole est certaine, et je veux que tu affirmes ces choses, afin que ceux qui ont cru en Dieu, aient soin les premiers de s’appliquer aux bonnes oeuvres; voilà les choses qui sont bonnes et utiles aux hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Mais réprime les folles questions, les généalogies, les contestations et les disputes de la Loi; car elles sont inutiles et vaines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Rejette l’homme hérétique, après le premier et le second avertissement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'Sachant qu’un tel homme est perverti, et qu’il pèche, étant condamné par soi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Quand j’enverrai vers toi Artémas, ou Tychique, hâte-toi de venir vers moi à Nicopolis; car j’ai résolu d’y passer l’hiver.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Accompagne soigneusement Zénas, Docteur de la Loi, et Apollos, afin que rien ne leur manque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Que les nôtres aussi apprennent à être les premiers à s’appliquer aux bonnes oeuvres, pour les usages nécessaires, afin qu’ils ne soient point sans fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Tous ceux qui sont avec moi te saluent. Salue ceux qui nous aiment en la foi. Grâce soit avec vous tous, Amen! Ecrite de Nicopolis en Macédoine à Tite, qui a été établi premier Evêque de l’Eglise de Crête ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paul, prisonnier de Jésus-Christ, et le frère Timothée, à Philémon notre bien-aimé, et Compagnon d’oeuvre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'Et à Apphie notre bien-aimée, et à Archippe notre Compagnon d’armes, et à l’Eglise qui est en ta maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Que la grâce et la paix vous soient données de la part de Dieu notre Père, et de la part du Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Je rends grâces à mon Dieu, faisant toujours mention de toi dans mes prières;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'Apprenant la foi que tu as au Seigneur Jésus, et ta charité envers tous les Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Afin que la communication de ta foi montre son efficace, en se faisant connaître par tout le bien qui est en vous par Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Car, mon frère, nous avons une grande joie et une grande consolation de ta charité, en ce que tu as réjoui les entrailles des Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'C’est pourquoi bien que j’aie une grande liberté en Christ de te commander ce qui est de ton devoir,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'Cependant je te prie plutôt par la charité, bien que je suis ce que je suis, savoir Paul, Ancien, et même maintenant prisonnier de Jésus- Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Je te prie donc pour mon fils Onésime, que j’ai engendré dans mes liens;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'Qui t’a été autrefois inutile, mais qui maintenant est bien utile et à toi et à moi, et lequel je te renvoie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Reçois-le donc, comme mes propres entrailles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Je voulais le retenir auprès de moi, afin qu’il me servît à ta place, dans les liens de l’Evangile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Mais je n’ai rien voulu faire sans ton avis, afin que ce ne fût point comme par contrainte, mais volontairement, que tu me laissasses un bien qui est à toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Car peut-être n’a-t-il été séparé de toi pour un temps, qu’afin que tu le recouvrasses pour toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'Non plus comme un esclave, mais comme étant au-dessus d’un esclave, savoir, comme un frère bien-aimé, principalement de moi; et combien plus de toi, soit selon la chair, soit selon le Seigneur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Si donc tu me tiens pour ton compagnon, reçois-le comme moi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Que s’il t’a fait quelque tort, ou s’il te doit quelque chose, mets-le-moi en compte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Moi Paul j’ai écrit ceci de ma propre main, je te le payerai; pour ne pas te dire que tu te dois toi-même à moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Oui, mon frère, que je reçoive ce plaisir de toi en notre Seigneur; réjouis mes entrailles en notre Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Je t’ai écrit m’assurant de ton obéissance, et sachant que tu feras même plus que je ne te dis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Mais aussi en même temps prépare-moi un logement; car j’espère que je vous serai donné par vos prières.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Epaphras, qui est prisonnier avec moi en Jésus-Christ, te salue;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Marc aussi, et Aristarque, et Démas, et Luc, mes compagnons d’oeuvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Que la grâce de notre Seigneur Jésus-Christ soit avec votre esprit, Amen! ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Dieu ayant anciennement parlé à nos pères par les Prophètes, à plusieurs fois, et en plusieurs manières,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'Nous a parlé en ces derniers jours par son Fils, qu’il a établi héritier de toutes choses; et par lequel il a fait les siècles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Et qui étant la splendeur de sa gloire, et l’empreinte de sa personne, et soutenant toutes choses par sa parole puissante, ayant fait par soi-même la purification de nos péchés, s’est assis à la droite de la Majesté divine dans les lieux très-hauts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'Etant fait d’autant plus excellent que les Anges, qu’il a hérité un Nom plus excellent que le leur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Car auquel des Anges a-t-il jamais dit: tu es mon Fils, je t’ai aujourd’hui engendré? Et ailleurs: je lui serai Père, et il me sera Fils?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Et encore, quand il introduit dans le monde son Fils premier-né, il est dit: et que tous les Anges de Dieu l’adorent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Car quant aux Anges, il est dit: Faisant des vents les Anges, et de la flamme de feu ses Ministres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Mais il est dit quant au Fils: ô Dieu! ton trône demeure aux siècles des siècles, et le sceptre de ton Royaume est un sceptre d’équité:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Tu as aimé la justice, et tu as haï l’iniquité; c’est pourquoi, ô Dieu! ton Dieu t’a oint d’une huile de joie par-dessus tous tes semblables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Et dans un autre endroit: toi, Seigneur, tu as fondé la terre dès le commencement, et les cieux sont les ouvrages de tes mains:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Ils périront, mais tu es permanent; et ils vieilliront tous comme un vêtement;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'Et tu les plieras en rouleau comme un habit, et ils seront changés; mais toi, tu es le même, et tes ans ne finiront point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Et auquel des Anges a-t-il jamais dit: assieds-toi à ma droite, jusqu’à ce que j’aie mis tes ennemis pour le marche-pied de tes pieds?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Ne sont-ils pas tous des esprits administrateurs, envoyés pour servir en faveur de ceux qui doivent recevoir l’héritage du salut?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'C’est pourquoi il nous faut prendre garde de plus près aux choses que nous avons ouïes de peur que nous les laissions écouler.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Car si la parole prononcée par les Anges a été ferme, et si toute transgression et désobéissance a reçu une juste rétribution;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'Comment échapperons-nous, si nous négligeons un si grand salut, qui ayant premièrement commencé d’être annoncé par le Seigneur, nous a été confirmé par ceux qui l’avaient ouï?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Dieu leur rendant aussi témoignage par des prodiges et des miracles, et par plusieurs autres différents effets de sa puissance, et par les distributions du Saint-Esprit, selon sa volonté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Car ce n’est point aux Anges qu’il a assujetti le monde à venir duquel nous parlons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Et quelqu’un a rendu ce témoignage en quelque autre endroit disant: qu’est-ce que de l’homme, que tu te souviennes de lui? ou du fils de l’homme, que tu le visites?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Tu l’as fait un peu moindre que les Anges, tu l’as couronné de gloire et d’honneur, et l’as établi sur les oeuvres de tes mains.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Tu as assujetti toutes choses sous ses pieds. Or en ce qu’il lui a assujetti toutes choses, il n’a rien laissé qui ne lui soit assujetti; mais nous ne voyons pourtant pas encore que toutes choses lui soient assujetties.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Mais nous voyons couronné de gloire et d’honneur celui qui avait été fait un peu moindre que les Anges, c’est à savoir Jésus, par la passion de sa mort, afin que par la grâce de Dieu il souffrît la mort pour tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Car il était convenable que celui pour qui sont toutes choses, et par qui sont toutes choses, puisqu’il amenait plusieurs enfants à la gloire, consacrât le Prince de leur salut par les afflictions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Car et celui qui sanctifie, et ceux qui sont sanctifiés descendent tous d’un même père; c’est pourquoi il ne prend point à honte de les appeler ses frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Disant: j’annoncerai ton Nom à mes frères, et je te louerai au milieu de l’assemblée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'Et ailleurs: je me confierai en lui. Et encore: me voici, moi et les enfants que Dieu m’a donnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Puis donc que les enfants participent à la chair et au sang, lui aussi de même a participé aux mêmes choses, afin que par la mort il détruisît celui qui avait l’empire de la mort, c’est à savoir le Diable;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'Et qu’il en délivrât tous ceux qui pour la crainte de la mort étaient assujettis toute leur vie à la servitude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Car certes il n’a nullement pris les Anges, mais il a pris la semence d’Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'C’est pourquoi il a fallu qu’il fût semblable en toutes choses à ses frères, afin qu’il fût un souverain Sacrificateur miséricordieux, et fidèle dans les choses qui doivent être faites envers Dieu, pour faire la propitiation pour les péchés du peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Car parce qu’il a souffert étant tenté, il est puissant aussi pour secourir ceux qui sont tentés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'C’est pourquoi, mes frères saints, qui êtes participants de la vocation céleste, considérez attentivement Jésus-Christ l’Apôtre et le souverain Sacrificateur de notre profession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Qui est fidèle à celui qui l’a établi comme Moïse aussi était fidèle en toute sa maison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Or Jésus-Christ a été jugé digne d’une gloire d’autant plus grande que celle de Moïse, que celui qui a bâti la maison, est d’une plus grande dignité que la maison même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Car toute maison est bâtie par quelqu’un: or celui qui a bâti toutes ces choses, c’est Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Et quant à Moïse, il a bien été fidèle dans toute la maison de Dieu, comme serviteur, pour témoigner des choses qui devaient être dites;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Mais Christ comme Fils est sur sa maison; et nous sommes sa maison, pourvu que nous retenions ferme jusques à la fin l’assurance, et la gloire de l’espérance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'C’est pourquoi, comme dit le Saint-Esprit: aujourd’hui, si vous entendez sa voix,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'N’endurcissez point vos coeurs, comme il arriva dans le lieu de l’irritation, au jour de la tentation au désert:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Où vos pères m’ont tenté et m’ont éprouvé, et où ils ont vu mes oeuvres durant quarante ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'C’est pourquoi j’ai été ennuyé de cette génération, et j’ai dit: leur coeur s’égare toujours et ils n’ont point connu mes voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Aussi j’ai juré en ma colère: si jamais ils entrent en mon repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Mes frères, prenez garde qu’il n’y ait en quelqu’un de vous un mauvais coeur d’incrédulité, pour se révolter du Dieu vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Mais exhortez-vous l’un l’autre chaque jour, pendant que ce jour nous éclaire; de peur que quelqu’un de vous ne s’endurcisse par la séduction du péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Car nous avons été faits participants de Christ, pourvu que nous retenions ferme jusqu’à la fin le commencement de notre subsistance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Pendant qu’il est dit: aujourd’hui si vous entendez sa voix n’endurcissez point vos coeurs, comme il arriva dans le lieu de l’irritation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Car quelques-uns l’ayant entendue, le provoquèrent à la colère; mais ce ne furent pas tous ceux qui étaient sortis d’Egypte par Moïse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Mais desquels fut-il ennuyé durant quarante ans? ne fut-ce pas de ceux qui péchèrent, et dont les corps tombèrent dans le désert?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Et auxquels jura-t-il qu’ils n’entreraient point en son repos, sinon à ceux qui furent rebelles?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Ainsi nous voyons qu’ils n’y purent entrer à cause de leur incrédulité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Craignons donc que quelqu’un d’entre vous négligeant la promesse d’entrer dans son repos ne s’en trouve privé:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Car il nous a été évangélisé, comme il le fut à ceux-là; mais la parole de la prédication ne leur servit de rien, parce qu’elle n’était point mêlée avec la foi dans ceux qui l’ouïrent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Mais pour nous qui avons cru, nous entrerons dans le repos, suivant ce qui a été dit: c’est pourquoi j’ai juré en ma colère, si jamais ils entrent en mon repos; quoique ses ouvrages fussent déjà achevés dès la fondation du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Car il a été dit ainsi en quelque lieu touchant le septième jour: Et Dieu se reposa de tous ses ouvrages au septième jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'Et encore en ce passage: Si jamais ils entrent en mon repos.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Puis donc qu’il reste que quelques-uns y entrent, et que ceux à qui premièrement il a été évangélisé n’y sont point entrés, à cause de leur incrédulité,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Dieu détermine encore un certain jour, qu’il appelle aujourd’hui, en disant par David si longtemps après, selon ce qui a été dit: aujourd’hui, si vous entendez sa voix, n’endurcissez point vos coeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Car si Josué les eût introduits dans le repos, jamais après cela il n’eût parlé d’un autre jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Il reste donc un repos pour le peuple de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Car celui qui est entré en son repos, s’est reposé aussi de ses oeuvres, comme Dieu s’était reposé des siennes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Etudions-nous donc d’entrer dans ce repos-là, de peur que quelqu’un ne tombe en imitant une semblable incrédulité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Car la Parole de Dieu est vivante et efficace, et plus pénétrante que nulle épée à deux tranchants, et elle atteint jusques à la division de l’âme, de l’esprit, des jointures et des moelles, et elle est juge des pensées et des intentions du coeur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Et il n’y a aucune créature qui soit cachée devant lui: mais toutes choses sont nues et entièrement ouvertes aux yeux de celui devant lequel nous avons affaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Puis donc que nous avons un souverain et grand Sacrificateur, Jésus Fils de Dieu, qui est entré dans les Cieux, tenons ferme notre profession.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Car nous n’avons pas un souverain Sacrificateur qui ne puisse avoir compassion de nos infirmités, mais nous avons celui qui a été tenté comme nous en toutes choses, excepté le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Allons donc avec assurance au trône de la Grâce; afin que nous obtenions miséricorde, et que nous trouvions grâce, pour être aidés dans le besoin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Or tout souverain Sacrificateur se prenant d’entre les hommes, est établi pour les hommes dans les choses qui concernent le service de Dieu, afin qu’il offre des dons et des sacrifices pour les péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Etant propre à avoir suffisamment pitié des ignorants et des errants; parce qu’il est aussi lui-même environné d’infirmité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'Tellement qu’à cause de cette infirmité, il doit offrir pour les péchés, non seulement pour le peuple, mais aussi pour lui-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Or nul ne s’attribue cet honneur, mais celui-là en jouit qui est appelé de Dieu, comme Aaron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'De même aussi Christ ne s’est point glorifié lui-même pour être fait souverain Sacrificateur, mais celui-là l’a glorifié qui lui a dit: c’est toi qui es mon Fils, je t’ai aujourd’hui engendré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Comme il lui dit aussi en un autre endroit: tu es Sacrificateur éternellement selon l’ordre de Melchisédec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Qui durant les jours de sa chair ayant offert avec de grands cris et avec larmes des prières et des supplications à celui qui pouvait le sauver de la mort et ayant été exaucé de ce qu’il craignait,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Quoiqu’il fût le Fils de Dieu, il a pourtant appris l’obéissance par les choses qu’il a souffertes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'Et ayant été consacré, il a été l’auteur du salut éternel pour tous ceux qui lui obéissent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Etant appelé de Dieu à être souverain Sacrificateur selon l’ordre de Melchisédec;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'De qui nous avons beaucoup de choses à dire, mais elles sont difficiles à expliquer, à cause que vous êtes devenus paresseux à écouter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Car au lieu que vous devriez être maîtres, vu le temps, vous avez encore besoin qu’on vous enseigne quels sont les rudiments du commencement des paroles de Dieu; et vous êtes devenus tels, que vous avez encore besoin de lait, et non de viande solide.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Or quiconque use de lait, ne sait point ce que c’est de la parole de la justice; parce qu’il est un enfant;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Mais la viande solide est pour ceux qui sont déjà hommes faits, c’est-à-dire, pour ceux qui pour y être habitués, ont les sens exercés à discerner le bien et le mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'C’est pourquoi laissant la parole qui n’enseigne que les premiers principes du Christianisme, tendons à la perfection, et ne nous arrêtons pas à jeter tout de nouveau le fondement de la repentance des oeuvres mortes, et de la foi en Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'De la doctrine des Baptêmes, et de l’imposition des mains, de la résurrection des morts, et du jugement éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Et c’est ce que nous ferons, si Dieu le permet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Or il est impossible que ceux qui ont été une fois illuminés, et qui ont goûté le don céleste, et qui ont été faits participants du Saint-Esprit,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'Et qui ont goûté la bonne parole de Dieu, et les puissances du siècle à venir;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'S’ils retombent, soient changés de nouveau par la repentance, vu que, quant à eux, ils crucifient de nouveau le Fils de Dieu, et l’exposent à l’opprobre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Car la terre qui boit souvent la pluie qui vient sur elle, et qui produit des herbes propres à ceux par qui elle est labourée, reçoit la bénédiction de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Mais celle qui produit des épines et des chardons, est rejetée, et proche de malédiction; et sa fin est d’être brûlée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Or nous nous sommes persuadés par rapport à vous, mes bien-aimés, de meilleures choses, et convenables au salut, quoique nous parlions ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Car Dieu n’est pas injuste, pour oublier votre oeuvre, et le travail de la charité que vous avez témoigné pour son Nom, en ce que vous avez secouru les Saints, et que vous les secourez encore.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Or nous souhaitons que chacun de vous montre jusqu’à la fin le même soin pour la pleine certitude de l’espérance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'Afin que vous ne vous relâchiez point, mais que vous imitiez ceux qui par la foi et par la patience héritent ce qui leur a été promis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Car lorsque Dieu fit la promesse à Abraham, parce qu’il ne pouvait point jurer par un plus grand, il jura par lui-même,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'En disant: certes je te bénirai abondamment, et je te multiplierai merveilleusement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Et ainsi Abraham ayant attendu patiemment, obtint ce qui lui avait été promis.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Car les hommes jurent par un plus grand qu’eux, et le serment qu’ils font pour confirmer leur parole, met fin à tous leurs différends.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'C’est pourquoi Dieu voulant faire mieux connaître aux héritiers de la promesse la fermeté immuable de son conseil, il y a fait intervenir le serment:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'Afin que par deux choses immuables, dans lesquelles il est impossible que Dieu trompe, nous ayons une ferme consolation, nous qui avons notre refuge à obtenir l’accomplissement de l’espérance qui nous est proposée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Et laquelle nous tenons comme une ancre sûre et ferme de l’âme, et qui pénètre jusqu’au-dedans du voile,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'Où Jésus est entré comme notre précurseur, ayant été fait souverain Sacrificateur éternellement, selon l’ordre de Melchisédec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Car ce Melchisédec, était Roi de Salem, et Sacrificateur du Dieu souverain, qui vint au-devant d’Abraham lorsqu’il retournait de la défaite des Rois, et qui le bénit,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'Et auquel Abraham donna pour sa part la dîme de tout. Son nom signifie premièrement Roi de justice, et puis il a été Roi de Salem, c’est-à-dire, Roi de paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Sans père, sans mère, sans généalogie, n’ayant ni commencement de jours, ni fin de vie, mais étant fait semblable au Fils de Dieu, il demeure Sacrificateur à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Or considérez combien grand était celui à qui même Abraham le Patriarche donna la dîme du butin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Car quant à ceux d’entre les enfants de Lévi qui reçoivent la Sacrificature, ils ont bien une ordonnance de dîmer le peuple selon la Loi, c’est-à-dire, de dîmer leurs frères, bien qu’ils soient sortis des reins d’Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Mais celui qui n’est point compté d’une même race qu’eux a dîmé Abraham, et a béni celui qui avait les promesses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Or sans contredit, celui qui est le moindre est béni par celui qui est le plus grand.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Et ici les hommes qui sont mortels, prennent les dîmes; mais là, celui-là les prend duquel il est rendu témoignage qu’il est vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Et, par manière de parler, Lévi même qui prend des dîmes, a été dîmé en Abraham.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Car il était encore dans les reins de son père, quand Melchisédec vint au-devant de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Si donc la perfection s’était trouvée dans la sacrificature Lévitique, (car c’est sous elle que le peuple a reçu la Loi) quel besoin était-il après cela qu’un autre Sacrificateur se levât selon l’ordre de Melchisédec, et qui ne fût point dit selon l’ordre d’Aaron.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Or la Sacrificature étant changée, il est nécessaire qu’il y ait aussi un changement de Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Car celui à l’égard duquel ces choses sont dites, appartient à une autre Tribu, de laquelle nul n’a assisté à l’autel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Car il est évident que notre Seigneur est descendu de la Tribu de Juda, à l’égard de laquelle Moïse n’a rien dit de la Sacrificature.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Et cela est encore plus incontestable, en ce qu’un autre Sacrificateur, à la ressemblance de Melchisédec, est suscité;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'Qui n’a point été fait Sacrificateur selon la Loi du commandement charnel, mais selon la puissance de la vie impérissable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Car Dieu lui rend ce témoignage: tu es Sacrificateur éternellement, selon l’ordre de Melchisédec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Or il se fait une abolition du commandement qui a précédé, à cause de sa faiblesse, et parce qu’il ne pouvait point profiter.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Car la Loi n’a rien amené à la perfection; mais ce qui a amené à la perfection, c’est ce qui a été introduit par-dessus, savoir une meilleure espérance, par laquelle nous approchons de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'D’autant plus même que ce n’a point été sans serment. Or ceux-là ont été faits Sacrificateurs sans serment;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'Mais celui-ci l’a été avec serment, par celui qui lui a dit: le Seigneur l’a juré, et il ne s’en repentira point: tu es Sacrificateur éternellement selon l’ordre de Melchisédec.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'C’est donc d’une beaucoup plus excellente alliance que la première, que Jésus a été fait le garant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Et quant aux Sacrificateurs, il en a été fait plusieurs, à cause que la mort les empêchait d’être perpétuels.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Mais celui-ci, parce qu’il demeure éternellement, il a une Sacrificature perpétuelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'C’est pourquoi aussi il peut sauver pour toujours ceux qui s’approchent de Dieu par lui, étant toujours vivant pour intercéder pour eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Or il nous était convenable d’avoir un tel souverain Sacrificateur, saint, innocent, sans tache, séparé des pécheurs, et élevé au-dessus des cieux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'Qui n’eût pas besoin, comme les souverains Sacrificateurs, d’offrir tous les jours des sacrifices, premièrement pour ses péchés, et ensuite pour ceux du peuple, vu qu’il a fait cela une fois, s’étant offert lui-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Car la Loi ordonne pour souverains Sacrificateurs des hommes faibles; mais la parole du serment qui a été fait après la Loi, ordonne le Fils, qui est consacré pour toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Or l’abrégé de notre discours, c’est que nous avons un tel souverain Sacrificateur qui est assis à la droite du trône de la Majesté de Dieu dans les Cieux,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'Ministre du Sanctuaire, et du vrai Tabernacle, que le Seigneur a dressé et non pas les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Car tout souverain Sacrificateur est ordonné pour offrir des dons et des sacrifices, c’est pourquoi il est nécessaire que celui-ci aussi ait eu quelque chose pour offrir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Vu même que s’il était sur la terre il ne serait pas Sacrificateur, pendant qu’il y aurait des Sacrificateurs qui offrent des dons selon la Loi;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Lesquels font le service dans le lieu qui n’est que l’image et l’ombre des choses célestes, selon que Dieu le dit à Moïse, quand il devait achever le Tabernacle: Or prends garde, lui dit-il, de faire toutes choses selon le modèle qui t’a été montré sur la montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Mais maintenant notre souverain Sacrificateur a obtenu un ministère d’autant plus excellent, qu’il est Médiateur d’une plus excellente alliance, qui est établie sous de meilleures promesses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Parce que s’il n’y eût eu rien à redire dans la première, il n’eût jamais été cherché de lieu à une seconde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Car en censurant les Juifs, Dieu leur dit: Voici, les jours viendront, dit le Seigneur, que je traiterai avec la maison d’Israël et avec la maison de Juda une Nouvelle alliance:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Non selon l’alliance que je traitai avec leurs pères, le jour que je les pris par la main pour les tirer du pays d’Egypte, car ils n’ont point persévéré dans mon alliance; c’est pourquoi je les ai méprisés, dit le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Mais voici l’alliance que je traiterai après ces jours-là avec la maison d’Israël, dit le Seigneur, c’est que je mettrai mes lois dans leur entendement, et je les écrirai dans leur coeur; et je serai leur Dieu, et ils seront mon peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Et chacun n’enseignera point son prochain, ni chacun son frère, en disant: connais le Seigneur; parce qu’ils me connaîtront tous, depuis le plus petit jusqu’au plus grand d’entre eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Car je serai apaisé par rapport à leurs injustices, et je ne me souviendrai plus de leurs péchés, ni de leurs iniquités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'En disant une nouvelle alliance, il envieillit la première: or, ce qui devient vieux et ancien, est près d’être aboli.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Le premier tabernacle avait donc des ordonnances touchant le culte divin, et un Sanctuaire terrestre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Car il fut construit un premier tabernacle, appelé le Lieu saint, dans lequel étaient le chandelier, et la table, et les pains de proposition.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Et après le second voile était le Tabernacle, qui était appelé le lieu Très-saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Ayant un encensoir d’or, et l’Arche de l’alliance, entièrement couverte d’or tout autour, dans laquelle était la cruche d’or où était la manne; et la verge d’Aaron qui avait fleuri, et les tables de l’alliance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Et au-dessus de l’Arche étaient les Chérubins de gLoire, faisant ombre sur le Propitiatoire, desquelles choses il n’est pas besoin maintenant de parler en détail.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Or ces choses étant ainsi disposées, les Sacrificateurs entrent bien toujours dans le premier Tabernacle pour accomplir le service;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Mais le seul souverain Sacrificateur entre dans le second une fois l’an, mais non sans y porter du sang, lequel il offre pour lui- même, et pour les fautes du peuple;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Le Saint-Esprit faisant connaître par là, que le chemin des lieux Saints n’était pas encore manifesté, tandis que le premier Tabernacle était encore debout, lequel était une figure destinée pour le temps d’alors;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Durant lequel étaient offerts des dons et des sacrifices; qui ne pouvaient point sanctifier la conscience de celui qui faisait le service,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Ordonnés seulement en viandes, en breuvages, en diverses ablutions, et en des cérémonies charnelles, jusqu’au temps que cela serait redressé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Mais Christ étant venu pour être le souverain Sacrificateur des biens à venir, par un plus excellent et plus parfait tabernacle, qui n’est pas un tabernacle fait de main, c’est-à-dire, qui soit de cette structure,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'Il est entré une fois dans les lieux Saints avec son propre sang, et non avec le sang des veaux ou des boucs, après avoir obtenu une rédemption éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Car si le sang des taureaux et des boucs, et la cendre de la génisse, de laquelle on fait aspersion, sanctifie quant à la pureté de la chair, ceux qui sont souillés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'Combien plus le sang de Christ, qui par l’Esprit éternel s’est offert lui-même à Dieu sans nulle tache, purifiera-t-il votre conscience des oeuvres mortes, pour servir le Dieu vivant?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'C’est pourquoi il est Médiateur du Nouveau Testament, afin que la mort intervenant pour la rançon des transgressions qui étaient sous le premier Testament, ceux qui sont appelés reçoivent l’accomplissement de la promesse qui leur a été faite de l’héritage éternel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Car où il y a un testament, il est nécessaire que la mort du testateur intervienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Parce que c’est par la mort du testateur qu’un testament est rendu ferme, vu qu’il n’a point encore de vertu durant que le testateur est en vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'C’est pourquoi le premier testament lui-même n’a point été confirmé sans du sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Car après que Moïse eut récité à tout le peuple tous les commandements selon la Loi, ayant pris le sang des veaux et des boucs, avec de l’eau et de la laine teinte en pourpre, et de l’hysope, il en fit aspersion sur le Livre, et sur tout le peuple;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'En disant: c’est ici le sang du Testament, lequel Dieu vous a ordonné d’observer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Il fit aussi aspersion du sang sur le Tabernacle, et sur tous les vaisseaux du service.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Et presque toutes choses selon la Loi sont purifiées par le sang; et sans effusion de sang il ne se fait point de rémission.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Il a donc fallu que les choses qui représentaient celles qui sont aux cieux, fussent purifiées par de telles choses, mais que les célestes le soient par des sacrifices plus excellents que ceux-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Car Christ n’est point entré dans les lieux Saints faits de main, qui étaient des figures correspondantes aux vrais, mais il est entré au Ciel même, afin de comparaître maintenant pour nous devant la face de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Non qu’il s’offre plusieurs fois lui-même, ainsi que le souverain Sacrificateur entre dans les lieux Saints chaque année avec un autre sang;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, '(Autrement il aurait fallu qu’il eût souffert plusieurs fois depuis la fondation du monde) mais maintenant en la consommation des siècles il a paru une seule fois pour l’abolition du péché, par le sacrifice de soi-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Et comme il est ordonné aux hommes de mourir une seule fois, et qu’après cela suit le jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'De même aussi Christ ayant été offert une seule fois pour ôter les péchés de plusieurs, apparaîtra une seconde fois sans péché à ceux qui l’attendent à salut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Car la Loi ayant l’ombre des biens à venir, et non la vive image des choses, ne peut jamais par les mêmes sacrifices que l’on offre continuellement chaque année, sanctifier ceux qui s’y attachent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Autrement n’eussent-ils pas cessé d’être offerts, puisque les sacrifiants étant une fois purifiés, ils n’eussent plus eu aucune conscience de péché?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Or il y a dans ces sacrifices une commémoration des péchés réitérée d’année en année.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Car il est impossible que le sang des taureaux et des boucs ôte les péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'C’est pourquoi Jésus-Christ en entrant au monde a dit: tu n’as point voulu de sacrifice, ni d’offrande, mais tu m’as approprié un corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Tu n’as point pris plaisir aux holocaustes, ni à l’oblation pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Alors j’ai dit: me voic1, je viens, il est écrit de moi au commencement du Livre: que je fasse, ô Dieu ta volonté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Ayant dit auparavant: tu n’as point voulu de sacrifice, ni d’offrande, ni d’holocaustes, ni d’oblation pour le péché, et tu n’y as point pris plaisir, lesquelles choses sont pourtant offertes selon la Loi, alors il a dit: me voici, je viens afin de faire, ô Dieu! ta volonté!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Il ôte donc le premier, afin d’établir le second.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'Or c’est par cette volonté que nous sommes sanctifiés, savoir par l’oblation qui a été faite une seule fois du corps de Jésus- Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Tout Sacrificateur donc assiste chaque jour, administrant, et offrant souvent les mêmes sacrifices, qui ne peuvent jamais ôter les péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Mais celui-ci ayant offert un seul sacrifice pour les péchés, s’est assis pour toujours à la droite de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'Attendant ce qui reste, savoir que ses ennemis soient mis pour le marchepied de ses pieds.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Car par une seule oblation, il a consacré pour toujours ceux qui sont sanctifiés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Et c’est aussi ce que le Saint-Esprit nous témoigne, car après avoir dit premièrement:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'C’est ici l’alliance que je ferai avec eux après ces jours-là, dit le Seigneur, c’est que je mettrai mes Lois dans leurs coeurs, et je les écrirai dans leurs entendements;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'Et je ne me souviendrai plus de leurs péchés, ni de leurs iniquités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Or où les péchés sont pardonnés, il n’y a plus d’oblation pour le péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Puis donc, mes frères, que nous avons la liberté d’entrer dans les lieux Saints par le sang de Jésus;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'Qui est le chemin nouveau et vivant qu’il nous a consacré; que nous avons, dis-je, la liberté d’y entrer par le voile, c’est-à- dire, par sa propre chair;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'Et que nous avons un grand Sacrificateur établi sur la maison de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'Approchons-nous de lui avec un coeur sincère et une foi inébranlable, ayant les coeurs purifiés de mauvaise conscience, et le corps lavé d’eau nette;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Retenons la profession de notre espérance sans varier, car celui qui nous a fait les promesses, est fidèle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'Et prenons garde l’un à l’autre, afin de nous inciter à la charité et aux bonnes oeuvres;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Ne quittant point notre assemblée, comme quelques-uns ont accoutumé de faire, mais nous exhortant l’un l’autre; et cela d’autant plus que vous voyez approcher le jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Car si nous péchons volontairement après avoir reçu la connaissance de la vérité, il ne reste plus de sacrifice pour les péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'Mais une attente terrible de jugement, et l’ardeur d’un feu qui doit dévorer les adversaires.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Si quelqu’un avait méprisé la Loi de Moïse, il mourait sans miséricorde, sur la déposition de deux ou de trois témoins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'De combien pires tourments pensez-vous donc que sera jugé digne celui qui aura foulé aux pieds le Fils de Dieu, et qui aura tenu pour une chose profane le sang de l’alliance, par lequel il avait été sanctifié, et qui aura outragé l’Esprit de grâce?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Car nous connaissons celui qui a dit: c’est à moi que la vengeance appartient, et je le rendrai, dit le Seigneur. Et en-core: le Seigneur jugera son peuple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'C’est une chose terrible que de tomber entre les mains du Dieu vivant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Or rappelez dans votre mémoire les jours précédents, durant lesquels après avoir été illuminés, vous avez soutenu un grand combat de souffrances;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'Ayant été d’une part exposés à la vue de tout le monde par des opprobres et des afflictions; et de l’autre, ayant participé aux maux de ceux qui ont souffert de semblables indignités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Car vous avez aussi été participants de l’affliction de mes liens, et vous avez reçu avec joie l’enlèvement de vos biens; sachant en vous-mêmes que vous avez dans les Cieux des biens meilleurs et permanents.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Ne perdez point cette fermeté que vous avez fait paraître, et qui sera bien récompensée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Parce que vous avez besoin de patience, afin qu’après avoir fait la volonté de Dieu, vous receviez l’effet de sa promesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Car encore un peu de temps, et celui qui doit venir, viendra, et il ne tardera point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Or le juste vivra de la foi; mais si quelqu’un se retire, mon âme ne prend point de plaisir en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Mais pour nous, nous n’avons garde de nous soustraire à notre Maître; ce serait notre perdition; mais nous persévérons dans la foi, pour le salut de l’âme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Or la foi rend présentes les choses qu’on espère, et elle est une démonstration de celles qu’on ne voit point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Car c’est par elle que les anciens ont obtenu un bon témoignage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Par la foi nous savons que les siècles ont été rangés par la parole de Dieu, de sorte que les choses qui se voient, n’ont point été faites de choses qui apparussent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Par la foi Abel offrit à Dieu un plus excellent sacrifice que Caïn, et par elle il obtint le témoignage d’être juste, à cause que Dieu rendait témoignage de ses dons; et lui étant mort parle encore par elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Par la foi Enoch fut enlevé pour ne point passer par la mort; et il ne fut point trouvé, parce que Dieu l’avait enlevé; car avant qu’il fût enlevé il a obtenu le témoignage d’avoir été agréable à Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Or il est impossible de lui être agréable sans la foi; car il faut que celui qui vient à Dieu, croie que Dieu est, et qu’il est le rémunérateur de ceux qui le cherchent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Par la foi Noé ayant été divinement averti des choses qui ne se voyaient point encore, craignit, et bâtit l’Arche pour la conservation de sa famille, et par cette Arche il condamna le monde, et fut fait héritier de la justice qui est selon la foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Par la foi Abraham étant appelé, obéit, pour aller en la terre, qu’il devait recevoir en héritage, et il partit sans savoir où il allait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Par la foi il demeura comme étranger en la terre, qui lui avait été promise, comme si elle ne lui eût point appartenu, demeurant sous des tentes avec Isaac et Jacob, qui étaient héritiers avec lui de la même promesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Car il attendait la cité qui a des fondements, et de laquelle Dieu est l’architecte, et le fondateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Par la foi aussi Sara reçut la vertu de concevoir un enfant, et elle enfanta hors d’âge, parce qu’elle fut persuadée que celui qui le lui avait promis, était fidèle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'C’est pourquoi d’un seul, et qui même était amorti, sont nés des gens qui égalent en nombre les étoiles du ciel, et le sable qui est sur le rivage de la mer, lequel ne se peut nombrer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Tous ceux-ci sont morts en la foi, sans avoir reçu les choses dont ils avaient eu les promesses, mais ils les ont vues de loin, crues, et saluées, et ils ont fait profession qu’ils étaient étrangers et voyageurs sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Car ceux qui tiennent ces discours montrent clairement qu’ils cherchent encore leur pays.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Et certes, s’ils eussent rappelé dans leur souvenir celui dont ils étaient sortis, ils avaient du temps pour y retourner.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Mais ils en désiraient un meilleur, c’est-à-dire, le céleste; c’est pourquoi Dieu ne prend point à honte d’être appelé leur Dieu, parce qu’il leur avait préparé une Cité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Par la foi, Abraham étant éprouvé, offrit Isaac; celui, dis-je, qui avait reçu les promesses, offrit même son fils unique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'A l’égard duquel il lui avait été dit: les descendants d’Isaac seront ta véritable postérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Ayant estimé que Dieu le pouvait même ressusciter d’entre les morts; c’est pourquoi aussi il le recouvra par une espèce de résurrection.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Par la foi Isaac donna à Jacob et à Esaü une bénédiction qui regardait l’avenir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Par la foi Jacob en mourant bénit chacun des fils de Joseph, et se prosterna devant Dieu étant appuyé sur le bout de son bâton.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Par la foi Joseph en mourant fit mention de la sortie des enfants d’Israël, et donna un ordre touchant ses os.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Par la foi Moïse étant né fut caché trois mois par ses père et mère, parce que c’était un très bel enfant, et ils ne craignirent point l’Edit du Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Par la foi Moïse étant déjà grand, refusa d’être nommé fils de la fille de Pharaon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Choisissant plutôt d’être affligé avec le peuple de Dieu, que de jouir pour un peu de temps des délices du péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Et ayant estimé que l’opprobre de Christ était un plus grand trésor que les richesses de l’Egypte; parce qu’il avait égard à la rémunération.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Par la foi il quitta l’Egypte, n’ayant point craint la fureur du Roi; car il demeura ferme, comme voyant celui qui est invisible.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Par la foi il fit la Pâque et l’aspersion du sang, afin que celui qui tuait les premiers-nés, ne touchât point à ceux des Israélites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Par la foi ils traversèrent la mer Rouge, comme par un lieu sec; ce que les Egyptiens ayant voulu éprouver, ils furent engloutis dans les eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Par la foi les murs de Jéricho tombèrent, après qu’on en eut fait le tour durant sept jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Par la foi Rahab l’hospitalière ne périt point avec les incrédules; ayant reçu les espions et les ayant renvoyés en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Et que dirai-je davantage? car le temps me manquera, si je veux parler de Gédéon, de Barac, de Samson, de Jephté, de David, de Samuel, et des Prophètes,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'Qui par la foi ont combattu les Royaumes, ont exercé la justice, ont obtenu l’effet des promesses, ont fermé les gueules des lions,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'Ont éteint la force du feu, sont échappés du tranchant des épées; de malades sont devenus vigoureux; se sont montrés forts dans la bataille, et ont tourné en fuite les armées des étrangers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Les femmes ont recouvré leurs morts par le moyen de la résurrection; d’autres ont été étendus dans le tourment, ne tenant point compte d’être délivrés, afin d’obtenir la meilleure résurrection.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'Et d’autres ont été éprouvés par des moqueries et par des coups, par des liens, et par la prison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Ils ont été lapidés, ils ont été sciés, ils ont souffert de rudes épreuves, ils ont été mis à mort par le tranchant de l’épée, ils ont été errants çà et là, vêtus de peaux de brebis et de chèvres, réduits à la misère, affligés, tourmentés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, 'Desquels le monde n’était pas digne; errant dans les déserts, et dans les montagnes, dans les cavernes, et dans les trous de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Et quoiqu’ils aient tous été recommandables par leur foi, ils n’ont pourtant point reçu l’effet de la promesse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'Dieu ayant pourvu quelque chose de meilleur pour nous; en sorte qu’ils ne sont point parvenus à la perfection sans nous');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Nous donc aussi, puisque nous sommes environnés d’une si grande nuée de témoins, rejetant tout fardeau, et le péché qui nous enveloppe si aisément, poursuivons constamment la course qui nous est proposée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'Portant les yeux sur Jésus, le chef et le consommateur de la foi, lequel au lieu de la joie dont il jouissait, a souffert la croix, ayant méprisé la honte, et s’est assis à la droite du trône de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'C’est pourquoi, considérez soigneusement celui qui a souffert une telle contradiction de la part des pécheurs contre lui-même, afin que vous ne succombiez point en perdant courage.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Vous n’avez pas encore résisté jusqu’à répandre votre sang en combattant contre le péché;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'Et cependant vous avez oublié l’exhortation qui s’adresse à vous comme à ses enfants, disant: mon enfant ne méprise point le châtiment du Seigneur, et ne perds point courage quand tu es repris de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Car le Seigneur châtie celui qu’il aime, et il fouette tout enfant qu’il avoue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Si vous endurez le châtiment, Dieu se présente à vous comme à ses enfants: car qui est l’enfant que le père ne châtie point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Mais si vous êtes sans châtiment auquel tous participent, vous êtes donc des enfants supposés, et non pas légitimes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Et puisque nos pères selon la chair nous ont châtiés et que malgré cela nous les avons respectés; ne serons-nous pas beaucoup plus soumis au Père des esprits? et nous vivrons.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Car par rapport à ceux-là, ils nous châtiaient pour un peu de temps, suivant leur volonté; mais celui-ci nous châtie pour notre profit, afin que nous soyons participants de sa sainteté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Or tout châtiment ne semble pas sur l’heure être un sujet de joie, mais de tristesse; mais ensuite il produit un fruit paisible de justice à ceux qui sont exercés par ce moyen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Relevez donc vos mains qui sont faibles, et fortifiez vos genoux qui sont déjoints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'Et faites les sentiers droits à vos pieds; afin que celui qui chancelle ne se dévoie point, mais plutôt qu’il soit remis en son entier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Recherchez la paix avec tous; et la sanctification, sans laquelle nul ne verra le Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Prenant garde qu’aucun ne se prive de la grâce de Dieu; que quelque racine d’amertume bourgeonnant en haut ne vous trouble, et que plusieurs ne soient souillés par elle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Que nul de vous ne soit fornicateur, ou profane comme Esaü, qui pour une viande vendit son droit d’aînesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Car vous savez que même désirant ensuite d’hériter la bénédiction, il fut rejeté: car il ne trouva point de lieu à la repentance, quoiqu’il l’eût demandée avec larmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Car vous n’êtes point venus à une montagne qui se puisse toucher à la main, ni au feu brûlant, ni au tourbillon, ni à l’obscurité, ni à la tempête,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'Ni au retentissement de la trompette, ni à la voix des paroles, au sujet de laquelle, ceux qui l’entendaient prièrent que la parole ne leur fût plus adressée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'Car ils ne pouvaient soutenir ce qui était ordonné, savoir, Si même une bête touche la montagne, elle sera lapidée, ou percée d’un dard.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Et Moïse, tant était terrible ce qui paraissait, dit: Je suis épouvanté et j’en tremble tout.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Mais vous êtes venus à la montagne de Sion, et à la Cité du Dieu vivant, à la Jérusalem céleste, et aux milliers d’Anges,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'Et à l’assemblée et à l’Eglise des premiers nés qui sont écrits dans les Cieux, et à Dieu qui est le juge de tous, et aux esprits des justes sanctifiés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'Et à Jésus, le Médiateur de la nouvelle alliance, et au sang de l’aspersion, qui prononce de meilleures choses que celui d’Abel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Prenez garde de ne mépriser point celui qui vous parle; car si ceux qui méprisaient celui qui leur parlait sur la terre, ne sont point échappés, nous serons punis beaucoup plus, si nous nous détournons de celui qui parle des Cieux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Duquel la voix ébranla alors la terre, mais à l’égard du temps présent, il a fait cette promesse, disant: j’ébranlerai encore une fois non seulement la terre, mais aussi le Ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Or ce mot, encore une fois, signifie l’abolition des choses muables, comme ayant été faites de main, afin que celles qui sont immuables demeurent;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'C’est pourquoi saisissant le Royaume qui ne peut point être ébranlé, retenons la grâce par laquelle nous servions Dieu, en sorte que nous lui soyons agréables avec respect et avec crainte,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Car aussi notre Dieu est un feu consumant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Que la charité fraternelle demeure dans vos coeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'N’oubliez point l’hospitalité: car par elle quelques-uns ont logé des Anges, n’en sachant rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Souvenez-vous des prisonniers, comme si vous étiez emprisonnés avec eux; et de ceux qui sont maltraités, comme étant vous-mêmes du même Corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Le mariage est honorable entre tous, et le lit sans souillure; mais Dieu jugera les fornicateurs et les adultères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Que vos moeurs soient sans avarice, étant contents de ce que vous avez présentement; car lui-même a dit: je ne te laisserai point, et je ne t’abandonnerai point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'De sorte que nous pouvons dire avec assurance: le Seigneur m’est en aide; et je ne craindrai point ce que l’homme me pourrait faire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Souvenez-vous de vos Conducteurs, qui vous ont porté la parole de Dieu, et imitez leur foi, en considérant quelle a été l’issue de leur vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jésus-Christ a été le même hier et aujourd’hu1, et il l’est aussi éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Ne soyez point emportés çà et là par des doctrines diverses et étrangères; car il est bon que le coeur soit affermi par la grâce, et non point par les viandes, lesquelles n’ont de rien profité à ceux qui s’y sont attachés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Nous avons un autel dont ceux qui servent dans le Tabernacle n’ont pas le pouvoir de manger.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Car les corps des bêtes dont le sang est porté pour le péché par le souverain Sacrificateur dans le Sanctuaire, sont brûlés hors du camp.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'C’est pourquoi aussi Jésus, afin qu’il sanctifiât le peuple par son propre sang, a souffert hors de la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Sortons donc vers lui hors du camp, en portant son opprobre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Car nous n’avons point ici de cité permanente, mais nous recherchons celle qui est à venir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Offrons donc par lui sans cesse à Dieu un sacrifice de louange, c’est-à-dire, le fruit des lèvres, en confessant son Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Or n’oubliez pas la bénéficence et de faire part de vos biens; car Dieu prend plaisir à de tels sacrifices.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Obéissez à vos Conducteurs, et soyez-leur soumis, car ils veillent pour vos âmes, comme devant en rendre compte; afin que ce qu’ils en font, ils le fassent avec joie, et non pas à regret; car cela ne vous tournerait pas à profit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Priez pour nous; car nous nous assurons que nous avons une bonne conscience, désirant de nous conduire honnêtement parmi tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Et je vous prie encore plus instamment de le faire, afin que je vous sois rendu plus tôt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Or le Dieu de paix, qui a ramené d’entre les morts le grand Pasteur des brebis, par le sang de l’alliance éternelle, savoir notre Seigneur Jésus-Christ:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'Vous rende accomplis en toute bonne oeuvre, pour faire sa volonté, en faisant en vous ce qui lui est agréable par Jésus-Christ; auquel soit gloire aux siècles des siècles, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Aussi, mes frères, je vous prie de supporter la parole d’exhortation; car je vous ai écrit en peu de mots.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Sachez que notre frère Timothée a été mis en liberté; je vous verrai avec lui, s’il vient bientôt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Saluez tous vos Conducteurs, et tous les Saints; ceux d’Italie vous saluent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Que la grâce soit avec vous tous, Amen! ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jacques, serviteur de Dieu, et du Seigneur Jésus-Christ, aux douze Tribus qui êtes dispersées, salut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Mes frères, regardez comme un sujet d’une parfaite joie quand vous serez exposés à diverses épreuves.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'Sachant que l’épreuve de votre foi produit la patience.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Mais il faut que la patience ait une oeuvre parfaite, afin que vous soyez parfaits et accomplis, de sorte que rien ne vous manque.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Que si quelqu’un de vous manque de sagesse, qu’il la demande à Dieu, qui la donne à tous libéralement, et qui ne la reproche point, et elle lui sera donnée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Mais qu’il la demande avec foi, ne doutant nullement; car celui qui doute est semblable au flot de la mer, agité du vent, et jeté çà et là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Or qu’un tel homme ne s’attende point de recevoir aucune chose du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'L’homme double de coeur est inconstant en toutes ses voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Or que le frère qui est de basse condition se glorifie en son élévation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'Et que le riche, au contraire, se glorifie en sa basse condition; car il passera comme la fleur de l’herbe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Car comme le soleil ardent n’est pas plutôt levé, que l’herbe est brûlée, que sa fleur tombe et que sa beauté périt; ainsi le riche se flétrira avec ses entreprises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Bienheureux est l’homme qui endure la tentation; car quand il aura été éprouvé, il recevra la couronne de vie, que Dieu a promise à ceux qui l’aiment.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Quand quelqu’un est tenté, qu’il ne dise point: je suis tenté de Dieu; car Dieu ne peut être tenté par le mal, et aussi ne tente-t-il personne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Mais chacun est tenté quand il est attiré et amorcé par sa propre convoitise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Puis quand la convoitise a conçu, elle enfante le péché, et le péché étant consommé, produit la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Mes frères bien-aimés ne vous abusez point:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Tout le bien qui nous est donné, et tout don parfait vient d’en haut, descendant du Père des lumières, par devers lequel il n’y a point de variation, ni d’ombre de changement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Il nous a de sa propre volonté engendrés par la parole de la vérité, afin que nous fussions comme les prémices de ses créatures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Ainsi, mes frères bien-aimés, que tout homme soit prompt à écouter, lent à parler, et lent à la colère;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Car la colère de l’homme n’acccomplit point la justice de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'C’est pourquoi rejetant toute souillure, et toute superfluité de malice, recevez avec douceur la parole plantée en vous, laquelle peut sauver vos âmes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Et mettez en exécution la parole, et ne l’écoutez pas seulement, en vous décevant vous-mêmes par de vains discours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Car si quelqu’un écoute la parole, et ne la met point en exécution, il est semblable à un homme qui considère dans un miroir sa face naturelle;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Car après s’être considéré soi-même, et s’en être allé, il a aussitôt oublié quel il était.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Mais celui qui aura regardé au-dedans de la Loi parfaite, qui est la Loi de la liberté; et qui aura persévéré, n’étant point un auditeur oublieux, mais s’appliquant à l’oeuvre qui lui est prescrite, celui-là sera heureux dans ce qu’il aura fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Si quelqu’un entre vous pense être religieux, et il ne tient point en bride sa langue, mais séduit son coeur, la religion d’un tel homme est vaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'La Religion pure et sans tache envers notre Dieu et notre Père, c’est de visiter les orphelins et les veuves dans leurs afflictions, et de se conserver pur des souillures de ce monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Mes frères, n’ayez point la foi en notre Seigneur Jésus-Christ glorieux, en ayant égard à l’apparence des personnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Car s’il entre dans votre assemblée un homme qui porte un anneau d’or, et qui soit vêtu de quelque précieux habit; et qu’il y entre aussi quelque pauvre, vêtu de quelque méchant habit;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'Et que vous ayez égard à celui qui porte l’habit précieux, et lui disiez: toi, assieds-toi ici honorablement; et que vous disiez au pauvre: toi, tiens-toi là debout; ou assieds-toi sur mon marche- pied;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'N’avez-vous pas fait différence en vous-mêmes, et n’êtes-vous pas des juges qui avez des pensées injustes?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Ecoutez, mes frères bien-aimés, Dieu n’a-t-il pas choisi les pauvres de ce monde, qui sont riches en la foi, et héritiers du Royaume qu’il a promis à ceux qui l’aiment?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Mais vous avez déshonoré le pauvre. Et cependant les riches ne vous oppriment-ils pas, et ne vous tirent-ils pas devant les Tribunaux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Et ne sont-ce pas eux qui blasphèment le bon Nom, qui a été invoqué sur vous?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Que si vous accomplissez la Loi royale, qui est selon l’Ecriture, tu aimeras ton prochain comme toi-même; vous faites bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Mais si vous avez égard à l’apparence des personnes, vous commettez un péché, et vous êtes convaincus par la Loi comme des transgresseurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Or quiconque aura gardé toute la Loi, s’il vient à pécher en un seul point, il est coupable de tous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Car celui qui a dit: tu ne commettras point adultère, a dit aussi: tu ne tueras point. Si donc tu ne commets point adultère, mais que tu tues, tu es un transgresseur de la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Parlez et agissez comme devant être jugés par la Loi de la liberté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Car il y aura une condamnation sans miséricorde sur celui qui n’aura point usé de miséricorde; mais la miséricorde se met à l’abri de la condamnation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Mes frères, que servira-t-il à quelqu’un s’il dit qu’il a la foi, et qu’il n’ait point les oeuvres? la foi le pourra-t-elle sauver?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Et si le frère ou la soeur sont nus, et manquent de ce qui leur est nécessaire chaque jour pour vivre,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'Et que quelqu’un d’entre vous leur dise: allez en paix, chauffez- vous, et vous rassasiez; et que vous ne leur donniez point les choses nécessaires pour le corps, que leur servira cela?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'De même aussi la foi, si elle n’a pas les oeuvres, elle est morte en elle-même.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Mais quelqu’un dira: tu as la foi, et moi j’ai les oeuvres. Montre-moi donc ta foi sans les oeuvres, et moi je te montrerai ma foi par mes oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Tu crois qu’il n’y a qu’un Dieu; tu fais bien; les Démons le croient aussi, et ils en tremblent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Mais, ô homme vain! veux-tu savoir que la foi qui est sans les oeuvres est morte?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Abraham notre père ne fut-il pas justifié par les oeuvres, quand il offrit son fils Isaac sur l’autel?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Ne vois-tu donc pas que sa foi agissait avec ses oeuvres, et que ce fut par ses oeuvres, que sa foi fut rendue parfaite;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'Et qu’ainsi cette Ecriture fut accomplie, qui dit: Abraham a cru en Dieu, et cela lui a été imputé à justice; et il a été appelé ami de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Vous voyez donc que l’homme est justifié par les oeuvres, et non par la foi seulement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Pareillement Rahab l’hospitalière, ne fut-elle pas justifiée par les oeuvres, quand elle eut reçu les messagers, et qu’elle les eut mis dehors par un autre chemin?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Car comme le corps sans esprit est mort, ainsi la foi qui est sans les oeuvres est morte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Mes frères, ne soyez point plusieurs maîtres; sachant que nous en recevrons une plus grande condamnation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Car nous péchons tous en plusieurs choses; si quelqu’un ne pèche pas en paroles, c’est un homme parfait, et il peut même tenir en bride tout le corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Voilà, nous mettons aux chevaux des mors dans leurs bouches, afin qu’ils nous obéissent, et nous menons çà et là tout le corps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Voilà aussi les navires, quoiqu’ils soient si grands, et qu’ils soient agités par la tempête, ils sont menés partout çà et là avec un petit gouvernail, selon qu’il plaît à celui qui les gouverne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Il en est ainsi de la langue, c’est un petit membre, et cependant elle peut se vanter de grandes choses. Voilà aussi un petit feu, combien de bois allume-t-il?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'La langue aussi est un feu, et un monde d’iniquité; car la langue est telle entre nos membres, qu’elle souille tout le corps, et enflamme tout le monde qui a été créé, étant elle-même enflammée du feu de la géhenne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Car toute espèce de bêtes sauvages, d’oiseaux, de reptiles, et de poissons de la mer, se dompte, et a été domptée par la nature humaine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Mais nul homme ne peut dompter la langue: c’est un mal qui ne se peut réprimer, et elle est pleine d’un venin mortel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Par elle nous bénissons notre Dieu et Père; et par elle nous maudissons les hommes, faits à la ressemblance de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'D’une même bouche procède la bénédiction et la malédiction. Mes frères, il ne faut pas que ces choses aillent ainsi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Une fontaine jette-t-elle par une même ouverture le doux et l’amer?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Mes frères, un figuier peut-il produire des olives? ou une vigne des figues? de même aucune fontaine ne peut jeter de l’eau salée et de l’eau douce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Y a-t-il parmi vous quelque homme sage et intelligent? qu’il fasse voir ses actions par une bonne conduite avec douceur et sagesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Mais si vous avez une envie amère et de l’irritation dans vos coeurs, ne vous glorifiez point, et ne mentez point en déshonorant la vérité de l’Evangile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Car ce n’est pas là la sagesse qui descend d’en haut; mais c’est une sagesse terrestre, sensuelle et diabolique.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Car où il y a de l’envie et de l’irritation, là est le désordre, et toute sorte de mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Mais la sagesse qui vient d’en haut, est premièrement pure, et ensuite pacifique, modérée, traitable, pleine de miséricorde, et de bons fruits, ne faisant point beaucoup de difficultés, et sans hypocrisie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Or le fruit de la justice se sème dans la paix, pour ceux qui s’adonnent à la paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'D’où viennent parmi vous les disputes et les querelles? n’est-ce point de vos voluptés, qui combattent dans vos membres?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Vous convoitez, et vous n’avez point ce que vous désirez; vous avez une envie mortelle, vous êtes jaloux, et vous ne pouvez obtenir ce que vous enviez; vous vous querellez, et vous disputez, et vous n’avez point ce que vous désirez, parce que vous ne le demandez point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Vous demandez, et vous ne recevez point; parce que vous demandez mal, et afin de l’employer dans vos voluptés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Hommes et femmes adultères, ne savez-vous pas que l’amitié du monde est inimitié contre Dieu? celui donc qui voudra être ami du monde, se rend ennemi de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Pensez-vous que l’Ecriture parle en vain; l’Esprit qui a habité en nous, vous inspire-t-il l’envie?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Il vous donne au contraire une plus grande grâce; c’est pourquoi l’Ecriture dit: Dieu résiste aux orgueilleux, mais il fait grâce aux humbles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Soumettez-vous donc à Dieu. Résistez au Démon, et il s’enfuira de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Approchez-vous de Dieu, et il s’approchera de vous; pécheurs, nettoyez vos mains; et vous qui êtes doubles de coeur, purifiez vos coeurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Sentez vos misères, et lamentez, et pleurez; que votre ris se change en pleurs, et votre joie en tristesse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Humiliez-vous en la présence du Seigneur, et il vous élèvera.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Mes frères ne médisez point les uns des autres; celui qui médit de son frère, et qui condamne son frère, médit de la Loi, et condamne la Loi; or si tu condamnes la Loi, tu n’es point l’observateur de la Loi, mais le juge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Il n’y a qu’un seul Législateur, qui peut sauver et qui peut perdre; mais toi qui es-tu, qui condamnes les autres?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Or maintenant, vous qui dites: Allons aujourd’hui ou demain en une telle ville, et demeurons là un an, et y trafiquons et gagnons;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, '(Qui toutefois ne savez pas ce qui arrivera le lendemain car qu’est-ce que votre vie? ce n’est certes qu’une vapeur qui parait pour un peu de temps, et qui ensuite s’évanouit;)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Au lieu que vous deviez dire: si le Seigneur le veut, et si nous vivons, nous ferons ceci, ou cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Mais maintenant vous vous vantez en vos pensées orgueilleuses; toute vanterie de cette nature est mauvaise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Il y a donc du péché en celui qui sait faire le bien, et qui ne le fait pas.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Or maintenant, vous riches, pleurez, et poussez de grands cris à cause des malheurs, qui s’en vont tomber sur vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Vos richesses sont pourries; vos vêtements sont rongés par les vers.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Votre or et votre argent sont rouillés, et leur rouille sera en témoignage contre vous, et dévorera votre chair comme le feu; vous avez amassé un trésor pour les derniers jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Voici, le salaire des ouvriers qui ont moissonné vos champs, et duquel ils ont été frustrés par vous, crie; et les cris de ceux qui ont moissonné, sont parvenus aux oreilles du Seigneur des armées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Vous avez vécu dans les délices sur la terre, vous vous êtes livrés aux voluptés, et vous avez rassasié vos coeurs comme en un jour de sacrifices.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Vous avez condamné, et mis à mort le juste, qui ne vous résiste point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Or donc, mes frères, attendez patiemment jusqu’à la venue du Seigneur; voici, le laboureur attend le fruit précieux de la terre, patientant, jusqu’à ce qu’il reçoive la pluie de la première, et de la dernière saison.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Vous donc aussi attendez patiemment, et affermissez vos coeurs; car la venue du Seigneur est proche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Mes frères, ne vous plaignez point les uns des autres, afin que vous ne soyez point condamnés; voilà, le juge se tient à la porte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Mes frères, prenez pour un exemple d’affliction et de patience les Prophètes qui ont parlé au Nom du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Voici, nous tenons pour bienheureux ceux qui ont souffert; vous avez appris quelle a été la patience de Job, et vous avez vu la fin du Seigneur; car le Seigneur est plein de compassion, et pitoyable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Or sur toutes choses, mes frères, ne jurez ni par le Ciel, ni par la terre, ni par quelque autre serment; mais que votre oui soit Oui, et votre non, Non: afin que vous ne tombiez point dans la condamnation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'y a-t-il quelqu’un parmi vous qui souffre? qu’il prie. Y en a-t- il quelqu’un qui ait l’esprit content? qu’il psalmodie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Y a-t-il quelqu’un parmi vous qui soit malade? qu’il appelle les Anciens de l’Eglise, et qu’ils prient pour lui, et qu’ils l’oignent d’huile au Nom du Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Et la prière faite avec foi sauvera le malade, et le Seigneur le relèvera; et s’il a commis des péchés, ils lui seront pardonnés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Confessez vos fautes l’un à l’autre, et priez l’un pour l’autre; afin que vous soyez guéris; car la prière du juste faite avec véhémence est de grande efficace.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elie était un homme sujet à de semblables infirmités que nous, et cependant ayant prié avec grande instance qu’il ne plût point, il ne tomba point de pluie sur la terre durant trois ans et six mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Et ayant encore prié, le Ciel donna de la pluie, et la terre produisit son fruit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Mes frères, si quelqu’un d’entre vous s’égare de la vérité, et que quelqu’un l’y ramène;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'Qu’il sache que celui qui aura ramené un pécheur de son égarement, sauvera une âme de la mort, et couvrira une multitude de péchés. ===============================================================================');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Pierre, Apôtre de Jésus-Christ, aux étrangers qui êtes dispersés dans le pays du Pont, en Galatie, en Cappadoce, en Asie, et en Bithynie,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Elus selon la prescience de Dieu le Père, par l’Esprit sanctifiant, pour obéir à Jésus-Christ et pour obtenir l’aspersion de son sang: que la grâce et la paix vous soient multipliées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Béni soit Dieu, le Père de notre Seigneur Jésus-Christ, qui par sa grande miséricorde nous a régénérés pour avoir une espérance vive, par la résurrection de Jésus-Christ d’entre les morts;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'D’obtenir l’héritage incorruptible, qui ne se peut souiller, ni flétrir, conservé dans les cieux pour nous,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'Qui sommes gardés par la puissance de Dieu, par la foi, afin que nous obtenions le salut, qui est prêt d’être révélé au dernier temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'En quoi vous vous réjouissez, quoique vous soyez maintenant affligés pour un peu de temps par diverses tentations, vu que cela est convenable;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'Afin que l’épreuve de votre foi, beaucoup plus précieuse que l’or, qui périt, et qui toutefois est éprouvé par le feu, vous tourne à louange, à honneur, et à gloire, quand Jésus-Christ sera révélé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Lequel, quoique vous ne l’ayez point vu, vous aimez; en qui, quoique maintenant vous ne le voyiez point, vous croyez, et vous vous réjouissez d’une joie ineffable et glorieuse;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Remportant la fin de votre foi, savoir le salut des âmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Duquel salut les Prophètes qui ont prophétisé de la grâce qui était réservée pour vous, se sont enquis, et l’ont diligemment recherché;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Recherchant soigneusement quand, et en quel temps, l’Esprit prophétique de Christ qui était en eux, rendant par avance témoignage, déclarait les souffrances qui devaient arriver à Christ, et la gloire qui les devait suivre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Et il leur fut révélé que ce n’était pas pour eux-mêmes, mais pour nous, qu’ils administraient ces choses, lesquelles ceux qui vous ont prêché l’Evangile, par le Saint-Esprit envoyé du Ciel, vous ont maintenant annoncées, et dans lesquelles les Anges désirent de regarder jusqu’au fond.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Vous donc, ayant les reins de votre entendement ceints, et étant sobres, espérez parfaitement en la grâce qui vous est présentée, jusqu’à ce que Jésus-Christ soit révélé;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Comme des enfants obéissants, ne vous conformant point à vos convoitises d’autrefois, pendant votre ignorance.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Mais comme celui qui vous a appelés est saint, vous aussi de même soyez saints dans toute votre conversation;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Parce qu’il est écrit: soyez saints, car je suis saint.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Et si vous invoquez comme votre Père celui qui sans avoir égard à l’apparence des personnes, juge selon l’oeuvre d’un chacun, conduisez-vous avec crainte durant le temps de votre séjour temporel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Sachant que vous avez été rachetés de votre vaine conduite, qui vous avait été enseignée par vos pères, non point par des choses corruptibles, comme par argent, ou par or;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'Mais par le précieux sang de Christ, comme de l’agneau sans défaut et sans tache,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Déjà ordonné avant la fondation du monde, mais manifesté dans les derniers temps pour vous;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Qui par lui croyez en Dieu qui l’a ressuscité des morts, et qui lui a donné la gloire, afin que votre foi et votre espérance fussent en Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Ayant donc purifié vos âmes en obéissant à la vérité par le Saint- Esprit, afin que vous ayez une amitié fraternelle qui soit sans hypocrisie, aimez-vous l’un l’autre tendrement d’un coeur pur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Vu que vous avez été régénérés, non par une semence corruptible, mais par une semence incorruptible, savoir par la parole de Dieu, vivante, et permanente à toujours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Parce que toute chair est comme l’herbe, et toute la gloire de l’homme comme la fleur de l’herbe; l’herbe est séchée, et sa fleur est tombée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'Mais la parole du Seigneur demeure éternellement; et c’est cette parole qui vous a été évangélisée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Vous étant donc dépouillés de toute malice, et de toute fraude, de dissimulations, d’envies et de toutes médisances,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'Désirez ardemment, comme des enfants nouvellement nés, de vous nourrir du lait spirituel et pur afin que vous croissiez par lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Si toutefois vous avez goûté combien le Seigneur est bon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Et vous approchant de lui, qui est la Pierre vive, rejetée des hommes, mais choisie de Dieu, et précieuse,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'Vous aussi comme des pierres vives êtes édifiés pour être une maison spirituelle, et une sainte Sacrificature, afin d’offrir des sacrifices spirituels, agréables à Dieu par Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'C’est pourquoi il est dit dans l’Ecriture: voici, je mets en Sion la maîtresse pierre du coin, élue et précieuse; et celui qui croira en elle, ne sera point confus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Elle est donc précieuse pour vous qui croyez; mais par rapport aux rebelles, il est dit: la pierre que ceux qui bâtissaient ont rejetée est devenue la maîtresse pierre du coin, une pierre d’achoppement, une pierre de scandale.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'Lesquels heurtent contre la parole, et sont rebelles; à quoi aussi ils ont été destinés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Mais vous êtes la race élue, la Sacrificature royale, la nation sainte, le peuple acquis, afin que vous annonciez les vertus de celui qui vous a appelés des ténèbres à sa merveilleuse lumière;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'Vous qui autrefois n’ étiez point son peuple, mais qui maintenant êtes le peuple de Dieu; vous qui n’aviez point obtenu miséricorde, mais qui maintenant avez obtenu miséricorde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Mes bien-aimés, je vous exhorte, que comme étrangers et voyageurs, vous vous absteniez des convoitises charnelles, qui font la guerre à l’âme;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Ayant une conduite honnête avec les Gentils, afin qu’au lieu qu’ils médisent de vous comme de malfaiteurs, ils glorifient Dieu au jour de la visitation, pour vos bonnes oeuvres qu’ils auront vues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Soyez donc soumis à tout établissement humain, pour l’amour de Dieu: soit au Roi, comme à celui qui est par-dessus les autres;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Soit aux Gouverneurs, comme à ceux qui sont envoyés de sa part, pour punir les méchants et pour honorer les gens de bien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Car c’est là la volonté de Dieu, qu’en faisant bien, vous fermiez la bouche à l’ignorance des hommes fous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Comme libres, et non pas comme ayant la liberté pour servir de voile à la méchanceté, mais comme serviteurs de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Portez honneur à tous. Aimez tous vos frères. Craignez Dieu. Honorez le Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Serviteurs, soyez soumis en toute crainte à vos maîtres, non seulement à ceux qui sont bons et équitables, mais aussi à ceux qui sont fâcheux:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Car c’est une chose agréable à Dieu si quelqu’un à cause de la conscience qu’il a envers Dieu, endure des afflictions, souffrant injustement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Autrement, quel honneur en aurez-vous, si recevant des soufflets pour avoir mal fait, vous le souffrez patiemment? mais si en faisant bien vous êtes pourtant affligés, et que vous le souffriez patiemment, voilà où Dieu prend plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Car aussi vous êtes appelés à cela; vu même que Christ a souffert pour nous, nous laissant un modèle, afin que vous suiviez ses traces;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Lui qui n’a point commis de péché, et dans la bouche duquel il n’a point été trouvé de fraude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Qui lorsqu’on lui disait des outrages, n’en rendait point, et quand on lui faisait du mal, n’usait point de menaces; mais il se remettait à celui qui juge justement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'Lequel même a porté nos péchés en son corps sur le bois; afin qu’étant morts au péché, nous vivions à la justice; et par la meurtrissure duquel même vous avez été guéris.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Car vous étiez comme des brebis errantes, mais maintenant vous êtes convertis au Pasteur et à l’Evêque de vos âmes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Que les femmes aussi soient soumises à leurs maris, afin que même s’il y en a qui n’obéissent point à la parole, ils soient gagnés sans la parole, par la conduite de leurs femmes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'Lorsqu’ils auront vu la pureté de votre conduite, accompagnée de crainte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Et que leur ornement ne soit point celui de dehors, qui consiste dans la frisure des cheveux, dans une parure d’or, et dans la magnificence des habits;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'Mais que leur ornement consiste dans l’homme caché dans le coeur, c’est-à-dire dans l’incorruptibilité d’un esprit doux et paisible, qui est d’un grand prix devant Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Car c’est ainsi que se paraient autrefois les saintes femmes qui espéraient en Dieu, et qui demeuraient soumises à leurs maris;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Comme Sara, qui obéissait à Abraham, l’appelant son Seigneur; de laquelle vous êtes les filles en faisant bien, lors même que vous ne craignez rien de ce que vous pourriez avoir à craindre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Vous maris aussi, comportez-vous discrètement avec elles, comme avec un vaisseau plus fragile, c’est-à-dire, féminin, leur portant du respect, comme ceux qui êtes aussi avec elles héritiers de la grâce de vie, afin que vos prières ne soient point interrompues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Enfin soyez tous d’un même sentiment, remplis de compassion l’un envers l’autre, vous entr’aimant fraternellement, miséricordieux, et doux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Ne rendant point mal pour mal, ni outrage pour outrage; mais, au contraire, bénissant; sachant que vous êtes appelés à cela, afin que vous héritiez la bénédiction.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Car celui qui veut aimer sa vie et voir ses jours bienheureux, qu’il garde sa langue de mal, et ses lèvres de prononcer aucune fraude;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Qu’il se détourne du mal, et qu’il fasse le bien; qu’il recherche la paix, et qu’il tâche de se la procurer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Car les yeux du Seigneur sont sur les justes, et ses oreilles sont attentives à leurs prières; mais la face du Seigneur est contre ceux qui se conduisent mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Or qui est-ce qui vous fera du mal, si vous êtes les imitateurs de celui qui est bon?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Que si toutefois vous souffrez quelque chose pour la justice, vous êtes bienheureux; mais ne craignez point les maux dont ils veulent vous faire peur, et n’en soyez point troublés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Mais sanctifiez le Seigneur dans vos coeurs, et soyez toujours prêts à répondre avec douceur et avec respect à chacun qui vous demande raison de l’espérance qui est en vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Ayant une bonne conscience, afin que ceux qui blâment votre bonne conduite en Christ, soient confus en ce qu’ils médisent de vous comme de malfaiteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Car il vaut mieux que vous souffriez en faisant bien, si la volonté de Dieu est que vous souffriez, qu’en faisant mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Car aussi Christ a souffert une fois pour les péchés, lui juste pour les injustes, afin de nous amener à Dieu; étant mort en la chair mais vivifié par l’Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'Par lequel aussi étant allé, il a prêché aux esprits qui sont dans la prison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'Et qui avaient été autrefois incrédules, quand la patience de Dieu les attendait une fois, durant les jours de Noé, tandis que l’Arche se préparait dans laquelle un petit nombre, savoir huit personnes furent sauvées par l’eau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'A quoi aussi maintenant répond la figure qui nous sauve, c’est-à- dire, le Baptême; non point celui par lequel les ordures de la chair sont nettoyées, mais la promesse faite à Dieu d’une conscience pure, par la résurrection de Jésus-Christ;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'Qui est à la droite de Dieu, étant allé au Ciel; et auquel sont assujettis les Anges, et les dominations, et les puissances.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Puis donc que Christ a souffert pour nous en la chair, vous aussi soyez armés de cette même pensée, que celui qui a souffert en la chair, a désisté du péché;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'Afin que durant le temps qui reste en la chair, vous ne viviez plus selon les convoitises des hommes, mais selon la volonté de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Car il nous doit suffire d’avoir accompli la volonté des Gentils, durant le temps de notre vie passée, quand nous nous abandonnions aux impudicités, aux convoitises, à l’ivrognerie, aux excès dans le manger et dans le boire, et aux idolâtries abominables;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Ce que ces Gentils trouvant fort étrange, ils vous blâment de ce que vous ne courez pas avec eux dans un même abandonnement de dissolution.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Mais ils rendront compte à celui qui est prêt à juger les vivants et les morts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Car c’est aussi pour cela qu’il a été évangélisé aux morts, afin qu’ils fussent jugés selon les hommes en la chair, et qu’ils vécussent selon Dieu dans l’esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Or la fin de toutes choses est proche: soyez donc sobres, et vigilants à prier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Mais surtout, ayez entre vous une ardente charité: car la charité couvrira une multitude de péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Soyez hospitaliers les uns envers les autres, sans murmures.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Que chacun selon le don qu’il a reçu, l’emploie pour le service des autres, comme bons dispensateurs de la différente grâce de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Si quelqu’un parle, qu’il parle comme annonçant les paroles de Dieu, si quelqu’un administre, qu’il administre comme par la puissance que Dieu lui en a fournie; afin qu’en toutes choses Dieu soit glorifié par Jésus-Christ, auquel appartient la gloire et la force aux siècles des siècles, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Mes bien-aimés, ne trouvez point étrange quand vous êtes comme dans une fournaise pour votre épreuve, comme s il vous arrivait quelque chose d’extraordinaire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Mais en ce que vous participez aux souffrances de Christ, réjouissez vous; afin qu’aussi à la révélation de sa gloire, vous vous réjouissiez avec allégresse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Si on vous dit des injures pour le Nom de Christ, vous êtes bienheureux: car l’Esprit de gloire et de Dieu repose sur vous, lequel est blasphémé par ceux qui vous noircissent mais pour vous vous le glorifiez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Que nul de vous ne souffre comme meurtrier, ou larron, ou malfaiteur, ou curieux des affaires d’autrui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Mais si quelqu’un souffre comme Chrétien, qu’il n’en ait point de honte, mais qu’il glorifie Dieu en cela.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Car il est temps que le jugement commence par la maison de Dieu; or s’il commence premièrement par nous, quelle sera la fin de ceux qui n’obéissent point à l’Evangile de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Et si le juste est difficilement sauvé, où comparaîtra le méchant et le pécheur?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Que ceux-là donc aussi qui souffrent par la volonté de Dieu, puisqu’ils font ce qui est bon lui recommandent leurs âmes, comme au fidèle Créateur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Je prie les Anciens qui sont parmi vous, moi qui suis Ancien avec eux, et témoin des souffrances de Christ, et participant de la gloire qui doit être révélée, et je leur dis:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Paissez le Troupeau de Christ qui vous est commis, en prenant garde sur lui, non point par contrainte, mais volontairement; non point pour un gain déshonnête, mais par un principe d’affection.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'Et non point comme ayant domination sur les héritages du Seigneur, mais en telle manière que vous soyez pour modèle au Troupeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'Et quand le souverain Pasteur apparaîtra, vous recevrez la couronne incorruptible de gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'De même, vous jeunes gens, soyez soumis aux Anciens, et ayant tous de la soumission l’un pour l’autre, soyez parés par-dedans d’humilité, parce que Dieu résiste aux orgueilleux, mais il fait grâce aux humbles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Humiliez-vous donc sous la puissante main de Dieu, afin qu’il vous élève quand il en sera temps;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Lui remettant tout ce qui peut vous inquiéter: car il a soin de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Soyez sobres, et veillez: car le diable, votre adversaire, tourne autour de vous comme un lion rugissant, cherchant qui il pourra dévorer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Résistez-lui donc en demeurant fermes dans la foi, sachant que les mêmes souffrances s’accomplissent en la compagnie de vos frères, qui sont dans le monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Or le Dieu de toute grâce, qui nous a appelés à sa gloire éternelle en Jésus-Christ, après que vous aurez souffert un peu de temps, vous rende accomplis, vous affermisse, vous fortifie, et vous établisse.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'A lui soit la gloire et la force, aux siècles des siècles, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Je vous ai écrit brièvement par Silvain notre frère, que je crois vous être fidèle, vous déclarant et vous protestant que la grâce de Dieu dans laquelle vous êtes est la véritable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'L’Eglise qui est à Babylone, élue avec vous, et Marc mon fils, vous saluent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Saluez-vous l’un l’autre par un baiser de charité. Que la paix soit à vous tous, qui êtes en Jésus-Christ, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Siméon Pierre, serviteur et Apôtre de Jésus-Christ, à vous qui avez obtenu une foi de pareil prix avec nous, par la justice de notre Dieu et Sauveur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Que la grâce et la paix vous soient multipliées, en la connaissance de Dieu, et de notre Seigneur Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Puisque sa divine puissance nous a donné tout ce qui [appartient] à la vie et à la piété, par la connaissance de celui qui nous a appelés par sa gloire et par sa vertu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Par lesquelles nous sont données les grandes et précieuses promesses, afin que par elles vous soyez faits participants de la nature divine, étant échappés de la corruption qui règne dans le monde par la convoitise;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Vous donc aussi y donnant tous vos soins ajoutez la vertu à votre foi; à la vertu, la science;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'A la science, la tempérance; à la tempérance, la patience; à la patience, la piété;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'A la piété, l\'amour fraternel; et à l\'amour fraternel, la charité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Car si ces choses sont en vous, et y abondent, elles ne vous laisseront point oisifs ni stériles en la connaissance de notre Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Mais celui en qui ces choses ne se trouvent point, est aveugle, et ne voit point de loin, ayant oublié la purification de ses anciens péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'C\'est pourquoi, mes frères, étudiez vous plutôt à affermir votre vocation, et votre élection; car en faisant cela vous ne broncherez jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Car par ce moyen l\'entrée au Royaume éternel de notre Seigneur et Sauveur Jésus-Christ vous sera abondamment donnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'C\'est pourquoi je ne serai point paresseux à vous faire toujours souvenir de ces choses, quoique vous ayez de la connaissance, et que vous soyez fondés en la vérité présente.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Car je crois qu\'il est juste que je vous réveille par des avertissements, tandis que je suis dans cette tente;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Sachant que dans peu de temps je dois en déloger, comme notre Seigneur Jésus- Christ lui-même me l\'a déclaré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Mais j\'aurai soin que vous puissiez aussi après mon départ vous remettre continuellement ces choses dans votre souvenir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Car nous ne vous avons point donné à connaître la puissance et la venue de notre Seigneur Jésus-Christ en suivant des fables artificieusement composées, mais comme ayant vu sa majesté de nos propres yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Car il reçut de Dieu le Père honneur et gloire, quand une telle voix lui fut adressée de la gloire magnifique; celui-ci est mon Fils bien-aimé, en qui j\'ai pris mon bon plaisir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Et nous entendîmes cette voix émanée du Ciel, étant avec lui sur la sainte montagne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Nous avons aussi la parole des Prophètes plus ferme, à laquelle vous faites bien d\'être attentifs, comme à une chandelle qui a éclairé dans un lieu obscur, jusqu\'à ce que le jour ait commencé à luire, et que l\'étoile du matin se soit levée dans vos cœurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Considérant premièrement ceci, qu\'aucune prophétie de l\'Ecriture ne procède d\'aucun mouvement particulier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Car la prophétie n\'a point été autrefois apportée par la volonté humaine, mais les saints hommes de Dieu étant poussés par le Saint-Esprit, ont parlé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Mais [comme] il y a eu de faux prophètes parmi le peuple, il y aura aussi parmi vous de faux docteurs, qui introduiront couvertement des sectes de perdition, et qui renonceront le Seigneur qui les a rachetés, attirant sur eux-mêmes une prompte ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Et plusieurs suivront leurs [sectes] de perdition; et à cause d\'eux la voie de la vérité sera blasphémée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Car ils feront par avarice trafic de vous avec des paroles déguisées; mais desquels la condamnation de longtemps ne tarde point, et la punition desquels ne s\'endort point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Car si Dieu n\'a pas épargné les Anges qui ont péché, mais les ayant précipités dans l\'abîme chargés des chaînes d\'obscurité, les a livrés pour être réservés au jugement;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Et [s\'il] n\'a point épargné le monde ancien, mais a gardé Noé, lui huitième, [qui était] le hérault de la justice; et a fait venir le déluge sur le monde des impies;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'Et [s\'il] a condamné à un renversement total les villes de Sodome et de Gomorrhe, les réduisant en cendre, et les mettant pour être un exemple à ceux qui vivraient dans l\'impiété;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'et [s\'il a] délivré le juste Lot qui avait eu beaucoup à souffrir de ces abominables parleur infâme conduite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Car cet [homme] juste, qui demeurait parmi eux, les voyant et les entendant, affligeait tous les jours son âme juste, à cause de leurs méchantes actions;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Le Seigneur sait [ainsi] délivrer de la tentation ceux qui l\'honorent, et réserver les injustes pour être punis au jour du jugement;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'Principalement ceux qui suivent les mouvements de la chair, dans la passion de l\'impureté, et qui méprisent la domination, [gens] audacieux, adonnés à leurs sens, et qui ne craignent point de blâmer les dignités;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Au lieu que les Anges, quoiqu\'ils soient plus grands en force et en puissance, ne prononcent point contre elles de sentence injurieuse devant le Seigneur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Mais ceux-ci, semblables à des bêtes brutes, qui suivent leur sensualité, et qui sont faites pour être prises et détruites, blâmant ce qu\'ils n\'entendent point, périront par leur propre corruption;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'Et ils recevront la récompense de leur iniquité. Ils aiment à être tous les jours dans les délices. Ce sont des taches et des souillures, et ils font leurs délices de leurs tromperies dans les repas qu\'ils font avec vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Ils ont les yeux pleins d\'adultère; ils ne cessent jamais de pécher; ils attirent les âmes mal assurées; ils ont le cœur exercé dans les rapines, ce sont des enfants de malédiction;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Qui ayant laissé le droit chemin, se sont égarés, et ont suivi le train de Balaam, [fils] de Bosor, qui aima le salaire d\'iniquité; mais il fut repris de son injustice,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, '[Car] une ânesse muette parlant d\'une voix humaine, réprima la folie du prophète.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Ce sont des fontaines sans eau, et des nuées agitées par le tourbillon, et des [gens] à qui l\'obscurité des ténèbres est réservée éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Car en prononçant des discours fort enflés de vanité, ils amorcent par les convoitises de la chair, et par [leurs] impudicités, ceux qui s\'étaient véritablement retirés de ceux qui vivent dans l\'erreur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Leur promettant la liberté, quoiqu\'ils soient eux-mêmes esclaves de la corruption; car on est réduit dans la servitude de celui par qui on est vaincu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Parce que si après s\'être retirés des souillures du monde par la connaissance du Seigneur et Sauveur Jésus-Christ, toutefois étant de nouveau enveloppés par elles, ils en sont surmontés, leur dernière condition est pire que la première.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Car il leur eût mieux valu n\'avoir pas connu la voie de la justice, qu\'après l\'avoir connue se détourner du saint commandement qui leur avait été donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Mais ce qu\'on dit par un proverbe véritable, leur est arrivé: le chien est retourné à ce qu\'il avait vomi; et la truie lavée [est retournée] se vautrer dans le bourbier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Mes bien-aimés, c\'est ici la seconde Lettre que je vous écris, afin de réveiller dans l\'une et dans l\'autre par mes avertissements les sentiments purs [que vous avez].');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, '[Et] afin que vous vous souveniez des paroles qui ont été dites auparavant par les saints Prophètes, et du commandement [que vous avez reçu] de nous, qui sommes Apôtres du Seigneur et Sauveur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Sur toutes choses, sachez qu\'aux derniers jours il viendra des moqueurs, se conduisant selon leurs propres convoitises;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'Et disant: où est la promesse de son avènement? car depuis que les pères sont endormis, toutes choses demeurent comme elles ont été dès le commencement de la création.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Car ils ignorent volontairement ceci, que les cieux ont été [faits] de toute ancienneté, et que la terre [est sortie] de l\'eau, et qu\'elle subsiste parmi l\'eau, par la parole de Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'Et que par ces choses-là le monde d\'alors périt, étant submergé des eaux du déluge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Mais les cieux et la terre qui sont maintenant, sont réservés par la même parole, étant gardés pour le feu au jour du jugement, et de la destruction des hommes impies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Mais, [vous mes] bien-aimés, n\'ignorez pas ceci, qu\'un jour [est] devant le Seigneur comme mille ans, et mille ans comme un jour.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Le Seigneur ne retarde point [l\'exécution de] sa promesse, comme quelques-uns estiment qu\'il y ait du retardement, mais il est patient envers nous, ne voulant point qu\'aucun périsse, mais que tous se repentent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Or le jour du Seigneur viendra comme le larron dans la nuit, et en ce jour-là les cieux passeront avec un bruit sifflant de tempête, et les éléments seront dissous par l\'ardeur [du feu], et la terre, et toutes les œuvres qui [sont] en elle, brûleront entièrement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Puis donc que toutes ces choses se doivent dissoudre, quels vous faut-il être en saintes conversations, et en œuvres de piété?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'En attendant, et en hâtant [par vos désirs] la venue du jour de Dieu, par lequel les cieux étant enflammés seront dissous, et les éléments se fondront par l\'ardeur [du feu].');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Mais nous attendons, selon sa promesse, de nouveaux cieux, et une nouvelle terre, où la justice habite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'C\'est pourquoi, [mes] bien-aimés, en attendant ces choses, étudiez-vous à être trouvés de lui sans tache et sans reproche, en paix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Et regardez la patience du Seigneur comme une preuve qu\'il veut votre salut; comme Paul, notre frère bien-aimé, vous en a écrit selon la sagesse qui lui a été donnée;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Ainsi que dans toutes ses Lettres, il parle de ces points, dans lesquels il y a des choses difficiles à entendre, que les ignorants et les mal-assurés tordent, comme [ils tordent] aussi les autres Ecritures, à leur propre perdition.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Vous donc mes bien-aimés, puisque vous en êtes déjà avertis, prenez garde qu\'étant emportés avec les autres par la séduction des abominables, vous ne veniez à déchoir de votre fermeté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Mais croissez en la grâce et en la connaissance de notre Seigneur et Sauveur Jésus-Christ. A lui soit gloire maintenant, et jusqu\'au jour d\'éternité, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Ce qui était dès le commencement, ce que nous avons ouï, ce que nous avons vu de nos propres yeux, ce que nous avons contemplé, et que nos propres mains ont touché de la Parole de vie,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(Car la vie a été manifestée, et nous l’avons vue, et aussi nous le témoignons, et nous vous annonçons la vie éternelle, qui était avec le Père, et qui nous a été manifestée.)');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'Cela, dis-je, que nous avons vu et ouï, nous vous l’annonçons; afin que vous ayez communion avec nous, et que notre communion soit avec le Père et avec son fils Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Et nous vous écrivons ces choses, afin que votre joie soit parfaite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Or c’est ici la déclaration que nous avons entendue de lui, et que nous vous annonçons, savoir, que Dieu est lumière, et qu’il n’y a en lui nulles ténèbres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Si nous disons que nous avons communion avec lui, et que nous marchions dans les ténèbres, nous mentons, et nous n’agissons pas selon la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Mais si nous marchons dans la lumière, comme Dieu est en la lumière, nous avons communion l’un avec l’autre, et le sang de son Fils Jésus-Christ nous purifie de tout péché.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Si nous disons que nous n’avons point de péché, nous nous séduisons nous-mêmes, et la vérité n’est point en nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Si nous confessons nos péchés, il est fidèle et juste pour nous pardonner nos péchés, et nous nettoyer de toute iniquité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Si nous disons que nous n’avons point de péché, nous le faisons menteur, et sa parole n’est point en nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Mes petits enfants, je vous écris ces choses, afin que vous ne péchiez point; que si quelqu’un a péché, nous avons un avocat envers le Père, savoir Jésus-Christ, le Juste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'Car c’est lui qui est la victime de propitiation pour nos péchés, et non seulement pour les nôtres, mais aussi pour ceux de tout le monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Et par ceci nous savons que nous l’avons connu, savoir, si nous gardons ses commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Celui qui dit: Je l’ai connu, et qui ne garde point ses commandements, il est menteur, et il n’y a point de vérité en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Mais pour celui qui garde sa parole, l’amour de Dieu est véritablement accompli en lui, et c’est par cela que nous savons que nous sommes en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Celui qui dit qu’il demeure en lui, doit vivre comme Jésus-Christ lui-même a vécu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Mes frères, je ne vous écris point un commandement nouveau, mais le commandement ancien, que vous avez eu dès le commencement; et ce commandement ancien c’est la parole que vous avez entendue dès le commencement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Cependant le commandement que je vous écris est un commandement nouveau, et est une chose véritable en lui et en vous, parce que les ténèbres sont passées, et que la vraie lumière luit maintenant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Celui qui dit qu’il est en la lumière, et qui hait son frère, est dans les ténèbres jusqu’à cette heure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Celui qui aime son frère, demeure dans la lumière, et il n’y a rien en lui qui le puisse faire tomber.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Mais celui qui hait son frère, est dans les ténèbres, et il marche dans les ténèbres, et il ne sait où il va; car les ténèbres lui ont aveuglé les yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Mes petits enfants, je vous écris, parce que vos péchés vous sont pardonnés par son Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Pères, je vous écris, parce que vous avez connu celui qui est dès le commencement. Jeunes gens, je vous écris, parce que vous avez vaincu le malin esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Jeunes enfants, je vous écris, parce que vous avez connu le Père. Pères, je vous ai écrit, parce que vous avez connu celui qui est dès le commencement. Jeunes gens, je vous ai écrit, parce que vous êtes forts, et que la parole de Dieu demeure en vous, et que vous avez vaincu le malin esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'N’aimez point le monde, ni les choses qui sont au monde; si quelqu’un aime le monde, l’amour du Père n’est point en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Car tout ce qui est au monde, c’est-à-dire, la convoitise de la chair, la convoitise des yeux, et l’orgueil de la vie, n’est point du Père, mais est du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Et le monde passe, avec sa convoitise; mais celui qui fait la volonté de Dieu, demeure éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Jeunes enfants, c’est ici le dernier temps; et comme vous avez entendu que l’Antechrist viendra, il y a même dès maintenant plusieurs Antechrists; et nous connaissons à cela que c’est le dernier temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Ils sont sortis d’entre nous, mais ils n’étaient point d’entre nous: car s’ils eussent été d’entre nous, ils fussent demeurés avec nous, mais c’est afin qu’il fût manifesté que tous ne sont point d’entre nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Mais vous avez été oints par le Saint esprit, et vous connaissez toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Je ne vous ai pas écrit comme si vous ne connaissiez point la vérité, mais parce que vous la connaissez, et qu’aucun mensonge n’est de la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Qui est le menteur, sinon celui qui nie que Jésus est le Christ? celui-là est l’Antechrist qui nie le Père et le Fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Quiconque nie le Fils, n’a point non plus le Père; quiconque confesse le Fils, a aussi le Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Que donc ce que vous avez entendu dès le commencement demeure en vous, car si ce que vous avez entendu dès le commencement demeure en vous, vous demeurerez aussi au Fils et au Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Et c’est ici la promesse qu’il vous a annoncée, savoir la vie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Je vous ai écrit ces choses touchant ceux qui vous séduisent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Mais l’Onction que vous avez reçue de lui demeure en vous, et vous n’avez pas besoin qu’on vous enseigne; mais comme la même Onction vous enseigne toutes choses, et qu’elle est véritable, et n’est pas un mensonge, et selon qu’elle vous a enseignés, vous demeurerez en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Maintenant donc, mes petits enfants, demeurez en lui; afin que quand il apparaîtra, nous ayons assurance, et que nous ne soyons point confus de sa présence, à sa venue.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Si vous savez qu’il est juste, sachez que quiconque fait ce qui est juste, est né de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Voyez quelle charité le Père a eue pour nous, que nous soyons appelés les enfants de Dieu; mais le monde ne nous connaît point, parce qu’il ne l’a point connu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Mes bien-aimés, nous sommes maintenant les enfants de Dieu, mais ce que nous serons n’est pas encore manifesté; or nous savons que lorsque le fils de Dieu sera apparu, nous lui serons semblables; car nous le verrons tel qu’il est.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Et quiconque a cette espérance en lui, se purifie, comme lui aussi est pur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Quiconque fait un péché, agit contre la Loi; car le péché est ce qui est contre la Loi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Or vous savez qu’il est apparu, afin qu’il ôtât nos péchés; et il n’y a point de péché en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Quiconque demeure en lui, ne pèche point: quiconque pèche, ne l’a point vu, ni ne l’a point connu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Mes petits enfants, que personne ne vous séduise. Celui qui fait ce qui est juste, est une personne juste, comme Jésus-Christ est juste;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Celui qui vit dans le péché est du Diable; car le Diable pèche dès le commencement; or le Fils de Dieu est apparu pour détruire les oeuvres du Diable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Quiconque est né de Dieu ne vit point dans le péché; car la semence de Dieu demeure en lui; et il ne peut pécher, parce qu’il est né de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Et c’est à cela que sont connus les enfants de Dieu, et les enfants du Diable. Quiconque ne fait pas ce qui est juste, et qui n’aime pas son frère n’est point de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Car c’est ici ce que vous avez ouï annoncer dès le commencement; savoir que nous nous aimions l’un l’autre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Et que nous ne soyons point comme Caïn, qui était du malin esprit et qui tua son frère. Mais pour quel sujet le tua-t-il? c’est parce que ses oeuvres étaient mauvaises, et que celles de son frère étaient justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Mes frères, ne vous étonnez point si le monde vous hait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'En ce que nous aimons nos frères, nous savons que nous sommes transférés de la mort à la vie: celui qui n’aime point son frère, demeure en la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Quiconque hait son frère est un meurtrier; et vous savez qu’aucun meurtrier ne possède point la vie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'A ceci nous avons connu la charité, c’est qu’il a exposé sa vie pour nous; nous devons donc aussi exposer nos vies pour nos frères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Or celui qui voyant son frère dans la nécessité, lui fermera ses entrailles, comment est-ce que la charité de Dieu demeure en lui?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Mes petits enfants, n’aimons pas de paroles, ni de langue, mais par des effets, et en vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Car c’est par là que nous connaissons que nous sommes de la vérité; et nous assurons ainsi nos coeurs devant lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Que si notre coeur nous condamne, certes Dieu est plus grand que notre coeur, et il connaît toutes choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Mes bien-aimés, si notre coeur ne nous condamne point, nous avons assurance envers Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'Et quoi que nous demandions, nous le recevons de lui; parce que nous gardons ses commandements, et que nous faisons les choses qui lui sont agréables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Et c’est ici son commandement, que nous croyions au Nom de son Fils Jésus-Christ, et que nous nous aimions l’un l’autre, comme il nous en a donné le commandement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Et celui qui garde ses commandements demeure en Jésus-Christ, et Jésus-Christ demeure en lui; et par ceci nous connaissons qu’il demeure en nous, savoir par l’Esprit qu’il nous a donné.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Mes bien-aimés, ne croyez point à tout esprit; mais éprouvez les esprits, pour savoir s’ils sont de Dieu; car plusieurs faux prophètes sont venus au monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Connaissez à cette marque l’Esprit de Dieu: tout esprit qui confesse que Jésus-Christ est venu en chair, est de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Et tout esprit qui ne confesse point que Jésus-Christ est venu en chair, n’est point de Dieu; or tel est l’esprit de l’Antechrist, duquel vous avez ouï dire qu’il viendra; et il est même déjà maintenant au monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Mes petits enfants, vous êtes de Dieu, et vous les avez vaincus; parce que celui qui est en vous, est plus grand que celui qui est au monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Ils sont du monde, c’est pourquoi ils parlent du monde, et le monde les écoute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Nous sommes de Dieu; celui qui connaît Dieu, nous écoute; mais celui qui n’est point de Dieu, ne nous écoute point; nous connaissons à ceci l’esprit de vérité et l’esprit d’erreur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Mes bien-aimés, aimons-nous l’un l’autre; car la charité est de Dieu; et quiconque aime son prochain est né de Dieu, et connaît Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Celui qui n’aime point son prochain, n’a point connu Dieu; car Dieu est charité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'En ceci est manifestée la charité de Dieu envers nous, que Dieu a envoyé son Fils unique au monde, afin que nous vivions par lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'En ceci est la charité, non que nous ayons aimé Dieu, mais en ce qu’il nous a aimés, et qu’il a envoyé son Fils pour être la propitiation pour nos péchés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Mes bien-aimés, si Dieu nous a ainsi aimés, nous devons aussi nous aimer l’un l’autre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Personne n’a jamais vu Dieu; si nous nous aimons l’un l’autre, Dieu demeure en nous, et sa charité est accomplie en nous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'A ceci nous connaissons que nous demeurons en lui, et lui en nous, c’est qu’il nous a donné de son Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Et nous l’avons vu, et nous témoignons que le Père a envoyé le Fils pour être le sauveur du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Quiconque confessera que Jésus est le Fils de Dieu, Dieu demeure en lui, et lui en Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Et nous avons connu et cru la charité que Dieu a pour nous. Dieu est charité; et celui qui demeure dans la charité, demeure en Dieu, et Dieu en lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'En ceci est accomplie la charité envers nous, afin que nous ayons de la confiance pour le jour du Jugement, si tel qu’il est, nous sommes tels en ce monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Il n’y a point de crainte dans la charité, mais la parfaite charité bannit la crainte; car la crainte cause de la peine; or celui qui craint, n’est pas accompli dans la charité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Nous l’aimons, parce qu’il nous a aimés le premier.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Si quelqu’un dit: j’aime Dieu, et cependant il hait son frère, il est un menteur; car comment celui qui n’aime point son frère, qu’il voit, peut-il aimer Dieu, lequel il ne voit point?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Et nous avons ce commandement de sa part, que celui qui aime Dieu, aime aussi son frère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Quiconque croit que Jésus est le Christ, est né de Dieu; et quiconque aime celui qui l’a engendré, aime aussi celui qui est né de lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Nous connaissons à cette marque que nous aimons les enfants de Dieu, c’est lorsque nous aimons Dieu, et que nous gardons ses commandements.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Car c’est en ceci que consiste notre amour pour Dieu; que nous gardions ses commandements; et ses commandements ne sont point pénibles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Parce que tout ce qui est né de Dieu surmonte le monde; et ce qui nous fait remporter la victoire sur le monde, c’est notre foi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Qui est celui qui surmonte le monde, sinon celui qui croit que Jésus est le Fils de Dieu?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'C’est ce Jésus qui est venu par eau et par sang, et non-seulement par l’eau, mais par l’eau et le sang; et c’est l’Esprit qui en rend témoignage; or l’Esprit est la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Car il y en a trois dans le Ciel qui rendent témoignage, le Père, la Parole, et le Saint-Esprit; et ces trois-là ne sont qu’un.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'Il y en a aussi trois qui rendent témoignage sur la terre, savoir l’Esprit, l’eau, et le Sang; et ces trois-là se rapportent à un.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Si nous recevons le témoignage des hommes, le témoignage de Dieu est plus considérable, or c’est là le témoignage de Dieu, lequel il a rendu de son Fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Celui qui croit au Fils de Dieu, il a au-dedans de lui-même le témoignage de Dieu; mais celui qui ne croit point Dieu, il l’a fait menteur; car il n’a point cru au témoignage que Dieu a rendu de son Fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Et c’est ici le témoignage, savoir que Dieu nous a donné la vie éternelle; et cette vie est en son Fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Celui qui a le Fils, a la vie, celui qui n’a point le Fils de Dieu, n’a point la vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Je vous ai écrit ces choses, à vous qui croyez au Nom du Fils de Dieu, afin que vous sachiez que vous avez la vie éternelle, et afin que vous croyiez au Nom du Fils de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Et c’est ici la confiance que nous avons en Dieu, que si nous demandons quelque chose selon sa volonté, il nous exauce.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Et si nous savons qu’il nous exauce, en quoi que nous demandions, nous le savons parce que nous obtenons les choses que nous lui avons demandées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Si quelqu’un voit son frère pécher d’un péché qui n’est point à la mort, il priera pour lui, et Dieu lui donnera la vie; savoir à ceux qui ne pèchent point à la mort. Il y a un péché à la mort; je ne te dis point de prier pour ce péché-là.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Toute iniquité est un péché; mais il y a quelque péché qui n’est point à la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Nous savons que quiconque est né de Dieu, ne pèche point; mais celui qui est engendré de Dieu, se conserve soi-même, et le malin esprit ne le touche point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Nous savons que nous sommes nés de Dieu; mais tout le monde est plongé dans le mal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Or nous savons que le Fils de Dieu est venu, et il nous a donné l’intelligence pour connaître le Véritable; et nous sommes dans le Véritable, savoir, en son Fils Jésus-Christ; il est le vrai Dieu, et la vie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Mes petits enfants, gardez-vous des idoles. Amen.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'L’Ancien à la Dame élue, et à ses enfants, lesquels j’aime sincèrement, et que je n’aime pas moi seul, mais aussi tous ceux qui ont connu la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'A cause de la vérité qui demeure en nous, et qui sera avec nous à jamais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Que la grâce, la miséricorde, et la paix de la part de Dieu le Père, et de la part du Seigneur Jésus-Christ, le Fils du Père, soient avec vous en vérité et en charité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Je me suis fort réjoui d’avoir trouvé quelques-uns de tes enfants qui marchent dans la vérité; selon le commandement que nous en avons reçu du Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Et maintenant, ô Dame! je te prie, non comme t’écrivant un nouveau commandement, mais celui que nous avons eu dès le commencement, que nous ayons de la charité les uns pour les autres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'Et c’est ici la charité, que nous marchions selon ses commandements; et c’est ici son commandement, comme vous l’avez entendu dès le commencement, afin que vous l’observiez.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Car plusieurs séducteurs sont venus au monde, qui ne confessent point que Jésus-Christ est venu en chair; un tel homme est un séducteur et un Antechrist.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Prenez garde à vous-mêmes, afin que nous ne perdions point ce que nous avons fait, mais que nous en recevions une pleine récompense.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Quiconque transgresse la doctrine de Jésus-Christ et ne lui demeure point fidèle, n’a point Dieu: celui qui demeure en la doctrine de Christ, a le Père et le Fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Si quelqu’un vient à vous, et qu’il n’apporte point cette doctrine, ne le recevez point dans votre maison, et ne le saluez point;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Car celui qui le salue, communique à ses mauvaises oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Quoique j’eusse plusieurs choses à vous écrire, je ne les ai pas voulu écrire avec du papier et de l’encre, mais j’espère d’aller vers vous, et de vous parler bouche à bouche, afin que notre joie soit parfaite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Les enfants de ta soeur élue te saluent, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'L’Ancien à Gaïus le bien-aimé, leque j’aime en vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Bien-aimé, je souhaite que tu prospères en toutes choses, et que tu sois en santé, comme ton âme est en prospérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Car je me suis fort réjoui quand les frères sont venus, et ont rendu témoignage de ta sincérité, et comment tu marches dans la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Je n’ai point de plus grande joie que celle-ci, qui est d’entendre que mes enfants marchent dans la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Bien-aimé, tu agis fidèlement en tout ce que tu fais envers les frères, et envers les étrangers;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Qui en la présence de l’Eglise ont rendu témoignage de ta charité, et tu feras bien de les accompagner dignement, comme il est séant selon Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Car ils sont partis pour son Nom, ne prenant rien des Gentils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Nous devons donc recevoir ceux qui leur ressemblent, afin que nous aidions à la vérité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'J’ai écrit à l’Eglise; mais Diotrèphes, qui aime d’être le premier entre eux, ne nous reçoit point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'C’est pourquoi, si je viens, je représenterai les actions qu’il commet, s’évaporant en mauvais discours contre nous, et n’étant pas content de cela, non seulement il ne reçoit pas les frères, mais il empêche même ceux qui les veulent recevoir, et les chasse de l’Eglise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Bien-aimé, n’imite point le mal, mais le bien; celui qui fait bien, est de Dieu; mais celui qui fait mal, n’a point vu Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Tous rendent témoignage à Démétrius, et la vérité même le lui rend, et nous aussi lui rendons témoignage, et vous savez que notre témoignage est véritable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'J’avais plusieurs choses à écrire, mais je ne veux point t’écrire avec de l’encre et avec la plume;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Mais j’espère de te voir bientôt, et nous parlerons bouche à bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'Que la paix soit avec toi! les amis te saluent; salue les amis nom par nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Jude serviteur de Jésus-Christ, et frère de Jacques, à ceux qui ont été appelés par l’Evangile, que Dieu a sanctifiés et Jésus-Christ a conservés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Que la miséricorde, la paix, et l’amour vous soient multipliés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Mes bien-aimés, comme je m’étudie entièrement à vous écrire du salut qui nous est commun, il m’a été nécessaire de vous écrire pour vous exhorter à soutenir le combat pour la foi qui a été une fois donnée aux Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Car quelques-uns se sont glissés parmi vous, qui dès longtemps auparavant ont été écrits pour une telle condamnation; gens sans piété, qui changent la grâce de notre Dieu en dissolution, et qui renoncent le seul Dominateur Jésus-Christ notre Dieu et Seigneur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Or je veux vous faire souvenir d’une chose que vous savez déjà, c’est que le Seigneur ayant délivré le peuple du pays d’Egypte, il détruisit ensuite ceux qui n’avaient point cru;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Et qu’il a réservé sous l’obscurité, dans des liens éternels, jusqu’au jugement de la grande journée, les Anges qui n’ont pas gardé leur origine, mais qui ont abandonné leur propre demeure;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Et que Sodome et Gomorrhe, et les villes voisines qui s’étaient abandonnées en la même manière que celles-ci, à l’impureté, et qui avaient couru après les péchés contre nature, ont été mises pour servir d’exemple, ayant reçu la punition du feu éternel;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Nonobstant cela ceux-ci tout de même s’étant endormis dans le vice, souillent leur chair, méprisent la domination, et blâment les dignités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Et néanmoins Michel l’Archange, quand il contestait disputant avec le Démon touchant le corps de Moïse, n’osa point prononcer de sentence de malédiction, mais il dit seulement: que le Seigneur te censure fortement!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Mais ceux-ci médisent de tout ce qu’ils n’entendent point, et se corrompent en tout ce qu’ils connaissent naturellement, comme font les bêtes brutes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Malheur à eux, car ils ont suivi le train de Caïn, et ont couru, par un égarement tel que celui de Balaam, après la récompense, et ont péri par une contradiction semblable à celle de Coré.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Ceux-ci sont des taches dans vos repas de charité, en prenant leurs repas avec vous, et se repaissant eux-mêmes sans crainte; ce sont des nuées sans eau, emportées des vents çà et là; des arbres dont le fruit se pourrit, et sans fruit, deux fois morts, et déracinés;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Des vagues impétueuses de la mer, jetant l’écume de leurs impuretés; des étoiles errantes, à qui l’obscurité des ténèbres est réservée éternellement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Desquels aussi Enoch, septième homme après Adam, a prophétisé, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Voici, le Seigneur est venu avec ses Saints, qui sont par millions, pour juger tous les hommes, et pour convaincre tous les méchants d’entre eux de toutes leurs méchantes actions qu’ils ont commises méchamment, et de toutes les paroles injurieuses que les pécheurs impies ont proférées contre lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Ce sont des murmurateurs, des querelleurs, se conduisant selon leurs convoitises, dont la bouche prononce des discours fort enflés, et qui admirent les personnes pour le profit qui leur en revient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Mais vous, mes bien-aimés, souvenez vous des paroles qui ont été dites auparavant par les Apôtres de notre Seigneur Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Et comment ils vous disaient, qu’au dernier temps il y aurait des moqueurs, qui marcheraient selon leurs impies convoitises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Ce sont ceux qui se séparent eux-mêmes, des gens sensuels, n’ayant point l’Esprit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Mais vous, mes bien-aimés, vous appuyant vous-mêmes sur votre très-sainte foi, et priant par le Saint-Esprit,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'Conservez-vous les uns les autres dans l’amour de Dieu, en attendant la miséricorde de notre Seigneur Jésus-Christ, pour obtenir la vie éternelle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Et ayez pitié des uns en usant de discrétion;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'Et sauvez les autres par la frayeur, les arrachant comme hors du feu, et haïssez même la robe souillée par la chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Or à celui qui est puissant pour vous garder sans que vous fassiez aucune chute et vous présenter irrépréhensibles devant sa gloire, avec joie;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'A Dieu, seul sage, notre Sauveur, soit gloire et magnificence, force, et empire dès maintenant et dans tous les siècles, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'La Révélation de Jésus Christ, que Dieu lui a donnée pour découvrir à ses serviteurs les choses qui doivent arriver bientôt, et qui les a fait connaître en les envoyant par son Ange à Jean son serviteur;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Qui a annoncé la parole de Dieu, et le témoignage de Jésus-Christ, et toutes les choses qu’il a vues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Bienheureux est celui qui lit, et ceux qui écoutent les paroles de cette prophétie, et qui gardent les choses qui y sont écrites: car le temps est proche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Jean aux sept Eglises qui sont en Asie, que la grâce et la paix vous soient données de la part de celui QUI EST, QUI ÉTAIT, et QUI EST A VENIR, et de la part des sept Esprits qui sont devant son trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'Et de la part de Jésus-Christ, qui est le témoin fidèle, le premier-né d’entre les morts, et le Prince des Rois de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'A lui dis-je, qui nous a aimés, et qui nous a lavés de nos péchés dans son sang, et nous a faits Rois et Sacrificateurs à Dieu son Père, à lui soit la gloire et la force aux siècles des siècles, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Voici il vient avec les nuées, et tout œil le verra, et ceux même qui l’ont percé; et toutes les Tribus de la terre se lamenteront devant lui; oui, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Je suis l’Alpha et l’Oméga, le commencement et la fin, dit le Seigneur, QUI EST, QUI ÉTAIT, et QUI EST A VENIR, le Tout-Puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Moi Jean, qui suis aussi votre frère et qui participe à l’affliction, au règne, et à la patience de Jésus-Christ, j’étais en l’île appelée Patmos pour la parole de Dieu, et pour le témoignage de Jésus-Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Or je fus ravi en esprit un jour de Dimanche, et j’entendis derrière moi une grande voix, comme est le son d’une trompette,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'Qui disait:Je suis l’Alpha et l’Oméga, le premier et le dernier: Ecris dans un livre ce que tu vois, et envoie-le aux sept Eglises qui sont en Asie; savoir à Ephèse, à Smyrne, à Pergame, à Thyatire, à Sardes, à Philadelphie, et à Laodicée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Alors je me tournai pour voir celui dont la voix m’avait parlé, et m’étant tourné, je vis sept chandeliers d’or;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'Et au milieu des sept chandeliers d’or un personnage semblable à un homme, vêtu d’une longue robe, et ceint d’une ceinture d’or à l’endroit des mamelles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Sa tête et ses cheveux étaient blancs comme de la laine blanche, et comme de la neige, et ses yeux étaient comme une flamme de feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'Ses pieds étaient semblables à de l’airain très-luisant, comme s’ils eussent été embrasés dans une fournaise; et sa voix était comme le bruit des grosses eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'Et il avait en sa main droite sept étoiles, et de sa bouche sortait une épée aiguë à deux tranchants, et son visage était semblable au soleil, quand il luit en sa force.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Et lorsque je l’eus vu, je tombai à ses pieds comme mort, et il mit sa main droite sur moi, en me disant: ne crains point, je suis le premier, et le dernier;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'Et je vis, mais j’ai été mort, et voici, je suis vivant aux siècles des siècles, Amen! Et je tiens les clefs de l’enfer et de la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Ecris les choses que tu as vues, celles qui sont présentement, et celles qui doivent arriver ensuite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Le mystère des sept étoiles que tu as vues en ma main droite, et les sept chandeliers d’or. Les sept étoiles sont les Anges des sept Eglises; et les sept chandeliers que tu as vus sont les sept Eglises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Ecris à l’Ange de l’Eglise d’Ephèse: celui qui tient les sept étoiles en sa main droite, et qui marche au milieu des sept chandeliers d’or, dit ces choses:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Je connais tes œuvres, ton travail et ta patience, et je sais que tu ne peux souffrir les méchants, et que tu as éprouvé ceux qui se disent être apôtres, et ne le sont point, et que tu les as trouvés menteurs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Et que tu as souffert, et que tu as eu patience, et que tu as travaillé pour mon Nom, et que tu ne t’es point lassé.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Mais j’ai quelque chose contre toi, c’est que tu as abandonné ta première charité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'C’est pourquoi souviens-toi d’où tu es déchu, et t’en repens, et fais les premières œuvres; autrement je viendrai à toi bientôt, et j’ôterai ton chandelier de son lieu, si tu ne te repens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Mais pourtant tu as ceci de bon que tu hais les actions des Nicolaïtes, lesquelles je hais moi aussi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Que celui qui a des oreilles, écoute ce que l’Esprit dit aux Eglises. A celui qui vaincra je lui donnerai à manger de l’arbre de vie, qui est au milieu du paradis de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Ecris aussi à l’Ange de l’Eglise de Smyrne: Le premier et le dernier, qui a été mort, et qui est retourné en vie, dit ces choses:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Je connais tes œuvres, ton affliction et ta pauvreté (mais tu es riche), et le blasphème de ceux qui se disent être Juifs, et qui ne le sont point, mais qui sont la Synagogue de satan.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Ne crains rien des choses que tu as à souffrir. Voici, il arrivera que le Démon mettra quelques-uns de vous en prison, afin que vous soyez éprouvés; et vous aurez une affliction de dix jours. Sois fidèle jusques à la mort, et je te donnerai la couronne de vie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Que celui qui a des oreilles, écoute ce que l’Esprit dit aux Eglises. Celui qui vaincra sera mis à couvert de la mort seconde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Ecris aussi à l’Ange de l’Eglise de Pergame: Celui qui a l’épée aiguë à deux tranchants, dit ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Je connais tes œuvres, et où tu habites, savoir là où est le siège de satan, et que cependant tu retiens mon Nom, et que tu n’as point renoncé ma foi, non pas même lorsqu’Antipas, mon fidèle martyr, a été mis à mort entre vous, là où satan habite.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Mais j’ai quelque peu de chose contre toi: c’est que tu en as là qui retiennent la doctrine de Balaam, lequel enseignait Balac à mettre un scandale devant les enfants d’Israël, afin qu’ils mangeassent des choses sacrifiées aux idoles, et qu’ils se livrassent à la fornication.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Ainsi tu en as, toi aussi, qui retiennent la doctrine des Nicolaïtes; ce que je hais.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Repens-toi: autrement je viendrai à toi bientôt; et je combattrai contre eux par l’épée de ma bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Que celui qui a des oreilles, écoute ce que l’Esprit dit aux Eglises. A celui qui vaincra je lui donnerai à manger de la manne qui est cachée, et je lui donnerai un caillou blanc, et sur ce caillou sera écrit un nouveau nom, que nul ne connaît, sinon celui qui le reçoit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Ecris aussi à l’Ange de l’Eglise de Thyatire: Le Fils de Dieu, qui a ses yeux comme une flamme de feu, et dont les pieds sont semblables à de l’airain très luisant, dit ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Je connais tes œuvres, ta charité, ton ministère, ta foi, ta patience, et que tes dernières œuvres surpassent les premières;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Mais j’ai quelque peu de chose contre toi: c’est que tu souffres que cette femme Jézabel, qui se dit prophétesse, enseigne, et qu’elle séduise mes serviteurs, pour les porter à la fornication, et pour leur faire manger des choses sacrifiées aux idoles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Et je lui ai donné du temps, afin qu’elle se repentit de sa prostitution; mais elle ne s’est point repentie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Voici, je vais la réduire au lit, et mettre dans une grande affliction ceux qui commettent adultère avec elle, s’ils ne se repentent de leurs œuvres;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'Et je ferai mourir de mort ses enfants; et toutes les Eglises connaîtront que je suis celui qui sonde les reins et les cœurs; et je rendrai à chacun de vous selon ses œuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Mais je vous dis à vous et aux autres qui sont à Thyatire, à tous ceux qui n’ont point cette doctrine, et qui n’ont point connu les profondeurs de satan, comme ils parlent, que je ne mettrai point sur vous d’autre charge.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Mais retenez ce que vous avez, jusqu’à ce que je vienne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Car à celui qui aura vaincu, et qui aura gardé mes œuvres jusqu’à la fin, je lui donnerai puissance sur les nations:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'Et il les gouvernera avec une verge de fer, et elles seront brisées comme les vaisseaux d’un potier, selon que je l’ai aussi reçu de mon Père.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'Et je lui donnerai l’étoile du matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Que celui qui a des oreilles, écoute ce que l’Esprit dit aux Eglises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Ecris aussi à l’Ange de l’Eglise de Sardes: Celui qui a les sept Esprits de Dieu, et les sept étoiles, dit ces choses: Je connais tes œuvres; c’est que tu as le bruit de vivre, mais tu es mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Sois vigilant, et confirme le reste qui s’en va mourir; car je n’ai point trouvé tes œuvres parfaites devant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Souviens-toi donc des choses que tu as reçues et entendues, et garde-les, et te repens, mais si tu ne veilles pas, je viendrai contre toi comme le larron, et tu ne sauras point à quelle heure je viendrai contre toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Toutefois tu as quelque peu de personnes aussi à Sardes, qui n’ont point souillé leurs vêtements, et qui marcheront avec moi en vêtements blancs, car ils en sont dignes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Celui qui vaincra, sera vêtu de vêtements blancs, et je n’effacerai point son nom du Livre de vie, mais je confesserai son nom devant mon Père, et devant ses Anges.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Que celui qui a des oreilles, écoute ce que l’Esprit dit aux Eglises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Ecris aussi à l’Ange de l’Eglise de Philadelphie: le Saint et le Véritable, qui a la clef de David, qui ouvre, et nul ne ferme; qui ferme, et nul n’ouvre, dit ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Je connais tes œuvres: voici, je t’ai ouvert une porte, et personne ne la peut fermer; parce que tu as un peu de force, que tu as gardé ma parole, et que tu n’as point renoncé mon Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Voici, je ferai venir ceux dela Synagogue de satan qui se disent Juifs, et ne le sont point, mais mentent; voici, dis-je, je les ferai venir et se prosterner à tes pieds, et ils connaîtront que je t’aime.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Parce que tu as gardé la parole de ma patience, je te garderai aussi de l’heure de la tentation qui doit arriver dans tout le monde, pour éprouver ceux qui habitent sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Voici, je viens bientôt; tiens ferme ce que tu as, afin que personne ne t’enlève ta couronne.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Celui qui vaincra, je le ferai être une colonne dans le Temple de mon Dieu, et il n’en sortira plus; et j’écrirai sur lui le Nom de mon Dieu, et le nom de la cité de mon Dieu, qui est la nouvelle Jérusalem, laquelle descend du Ciel de devers mon Dieu, et mon nouveau Nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Que celui qui a des oreilles, écoute ce que l’Esprit dit aux Eglises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Ecris aussi à l’Ange de l’Eglise de Laodicée: l’Amen, le témoin fidèle et véritable, le commencement de la créature de Dieu, dit ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Je connais tes œuvres, c’est que tu n’es ni froid, ni bouillant; ̈ô si tu étais ou froid, ou bouillant!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Parce donc que tu es tiède, et que tu n’es ni froid, ni bouillant, je te vomirai de ma bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Car tu dis: je suis riche, et je suis dans l’abondance, et je n’ai besoin de rien; mais tu ne connais pas que tu es malheureux, misérable, pauvre, aveugle et nu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Je te conseille d’acheter de moi de l’or éprouvé par le feu, afin que tu deviennes riche; et des vêtements blancs, afin que tu sois vêtu, et que la honte de ta nudité ne paraisse point; et d’oindre tes yeux de collyre, afin que tu voies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Je reprends et châtie tous ceux que j’aime; aie du zèle, et te repens.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Voici, je me tiens à la porte, et je frappe: si quelqu’un entend ma voix, et m’ouvre la porte, j’entrerai chez lui, je souperai avec lui, et lui avec moi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Celui qui vaincra, je le ferai asseoir avec moi sur mon trône, ainsi que j’ai vaincu, et je suis assis avec mon Père dans son trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Que celui qui a des oreilles, écoute ce que l’Esprit dit aux Eglises.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Après ces choses je regardai, et voici une porte fut ouverte au Ciel; et la première voix que j’avais ouïe comme d’une trompette, et qui parlait avec moi, me dit: monte ici, et je te montrerai les choses qui doivent arriver à l’avenir.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Et sur-le-champ je fus ravi en esprit: et voici, un trône était posé au Ciel, et quelqu’un était assis sur le trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Et celui qui y était assis, paraissait semblable à une pierre de jaspe, et de sardoine; et autour du trône paraissait un arc-en-ciel, semblable à une émeraude.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Et il y avait autour du trône vingt-quatre sièges; et je vis sur les sièges vingt-quatre Anciens assis, vêtus d’habillements blancs, et ayant sur leurs têtes des couronnes d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Et du trône sortaient des éclairs et des tonnerres, et des voix; et il y avait devant le trône sept lampes de feu ardentes, qui sont les sept Esprits de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Et au devant du trône il y avait une mer de verre, semblable à du cristal; et au milieu du trône et autour du trône quatre animaux, pleins d’yeux devant et derrière.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Et le premier animal était semblable à un lion; le second animal, était semblable à un veau; le troisième animal avait la face comme un homme; et le quatrième animal était semblable à un aigle qui vole.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Et les quatre animaux avaient chacun six ailes à l’entour; et par dedans ils étaient pleins d’yeux; et ils ne cessent point de dire jour et nuit: Saint! Saint! Saint! le Seigneur Dieu Tout- puissant, QUI ÉTAIT, QUI EST, et QUI EST A VENIR.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Or quand les animaux rendaient gloire et honneur et des actions de grâces à celui qui était assis sur le trône, à celui qui est vivant aux siècles des siècles,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Les vingt-quatre Anciens se prosternaient devant celui qui était assis sur le trône, et adoraient celui qui est vivant aux siècles des siècles, et ils jetaient leurs couronnes devant le trône, en disant:');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Seigneur, tu es digne de recevoir gloire, honneur et puissance; car tu as créé toutes choses; c’est par ta volonté qu’elles existent et qu’elles ont été créées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Puis je vis dans la main droite de celui qui était assis sur le trône, un Livre écrit dedans et dehors, scellé de sept sceaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Je vis aussi un Ange remarquable par sa force, qui criait à haute voix: qui est-ce qui est digne d’ouvrir le Livre, et d’en délier les sceaux?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Mais nul ne pouvait ni dans le Ciel, ni sur la terre, ni au-dessous de la terre ouvrir le Livre, ni le regarder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Et je pleurais fort, parce que personne n’était trouvé digne d’ouvrir le Livre, ni de le lire, ni de le regarder.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Et un des Anciens me dit: ne pleure point; voici, le Lion qui est de la Tribu de Juda, la racine de David, a vaincu pour ouvrir le Livre, et pour en délier les sept sceaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Et je regardai, et voici il y avait au milieu du trône et des quatre animaux, et au milieu des Anciens, un agneau qui se tenait là comme mis à mort, ayant sept cornes, et sept yeux, qui sont les sept Esprits de Dieu, envoyés par toute la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Et il vint, et prit le Livre de la main droite de celui qui était assis sur le trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Et quand il eut pris le Livre, les quatre animaux et les vingt- quatre Anciens se prosternèrent devant l’agneau, ayant chacun des harpes et des fioles d’or, pleines de parfums, qui sont les prières des Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Et ils chantaient un nouveau cantique, en disant: tu es digne de prendre le Livre, et d’en ouvrir les sceaux; car tu as été mis à mort, et tu nous as rachetés à Dieu par ton sang, de toute Tribu, Langue, peuple, et nation;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'Et tu nous as faits Rois et Sacrificateurs à notre Dieu; et nous régnerons sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Puis je regardai, et j’entendis la voix de plusieurs Anges autour du trône et des Anciens, et leur nombre était de plusieurs millions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Et ils disaient à haute voix: L’agneau qui a été mis à mort est digne de recevoir puissance, richesses, sagesse, force, honneur, gloire et louange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'J’entendis aussi toutes les créatures qui sont au Ciel, et en la terre, et sous la terre, et dans la mer, et toutes les choses qui y sont, disant: à celui qui est assis sur le trône, et à l’agneau, soit louange, honneur, gloire, et force, aux siècles des siècles!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Et les quatre animaux disaient: Amen! Et les vingt-quatre Anciens se prosternèrent et adorèrent celui qui est vivant aux siècles des siècles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Et quand l’agneau eut ouvert l’un des sceaux, je regardai, et j’entendis l’un des quatre animaux, qui disait, comme avec une voix de tonnerre: Viens, et vois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Et je regardai, et je vis un cheval blanc; et celui qui était monté dessus avait un arc, et il lui fut donné une couronne; et il sortit victorieux, et afin de vaincre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Et quand il eut ouvert le second sceau, j’entendis le second animal, qui disait: Viens, et vois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Et il sortit un autre cheval, qui était roux; et il fut donné à celui qui était monté dessus, de pouvoir ôter la paix de la terre, afin qu’on se tue l’un l’autre; et il lui fut donné une grande épée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Et quand il eut ouvert le troisième sceau, j’entendis le troisième animal qui disait: Viens, et vois; et je regardai, et je vis un cheval noir, et celui qui était monté dessus avait une balance en sa main.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'Et j’entendis au milieu des quatre animaux une voix qui disait: Le chenix de froment pour un denier, et les trois chenix d’orge pour un denier; mais ne nuis point au vin, ni à l’huile.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Et quand il eut ouvert le quatrième sceau, j’entendis la voix du quatrième animal, qui disait: Viens, et vois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Et je regardai, et je vis un cheval fauve; et celui qui était monté dessus avait nom la Mort, et l’Enfer suivait après lui; et il leur fut donné puissance sur la quatrième partie de la terre, pour tuer avec l’épée, par la famine, par la mortalité, et par les bêtes sauvages de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Et quand il eut ouvert le cinquième sceau, je vis sous l’autel les âmes de ceux qui avaient été tués pour la parole de Dieu, et pour le témoignage qu’ils avaient maintenu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Et elles criaient à haute voix, disant: Jusqu’à quand, Seigneur, qui es saint et véritable, ne juges-tu point, et ne venges-tu point notre sang de ceux qui habitent sur la terre?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Et il leur fut donné à chacun des robes blanches, et il leur fut dit qu’ils se reposassent encore un peu de temps, jusqu’à ce que le nombre de leurs compagnons de service, et de leurs frères qui doivent être mis à mort comme eux, soit complet.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Et je regardai quand il eut ouvert le sixième sceau, et voici, il se fit un grand tremblement de terre, et le soleil devint noir comme un sac fait de poil, et la lune devint toute comme du sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'Et les étoiles du ciel tombèrent sur la terre, comme lorsque le figuier étant agité par un grand vent, laisse tomber ses figues encore vertes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Et le ciel se retira comme un Livre qu’on roule; et toutes les montagnes, et les îles furent remuées de leurs places.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Et les Rois de la terre, les Princes, les riches, les capitaines, les puissants, tout esclave, et tout homme libre se cachèrent dans les cavernes, et entre les rochers des montagnes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'Et ils disaient aux montagnes et aux rochers: tombez sur nous, et cachez-nous de devant la face de celui qui est assis sur le trône, et de devant la colère de l’agneau;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Car la grande journée de sa colère est venue; et qui est-ce qui pourra subsister?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Après cela je vis quatre Anges qui se tenaient aux quatre coins de la terre, et qui retenaient les quatre vents de la terre, afin qu’aucun vent ne soufflât sur la terre, ni sur la mer, ni sur aucun arbre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'Puis je vis un autre Ange qui montait du côté de l’Orient, tenant le sceau du Dieu vivant, et il cria à haute voix aux quatre Anges qui avaient eu ordre de nuire à la terre, et à la mer,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'Et leur dit: Ne nuisez point à la terre, ni à la mer, ni aux arbres, jusqu’à ce que nous ayons marqué les serviteurs de notre Dieu sur leurs fronts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Et j’entendis que le nombre des marqués était de cent quarante- quatre mille, qui furent marqués de toutes les Tribus des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'Savoir de la Tribu de Juda, douze mille marqués; de la Tribu de Ruben, douze mille marqués; de la Tribu de Gad, douze mille marqués;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'De la Tribu d’Aser, douze mille marqués; de la Tribu de Nephthali, douze mille marqués; de la Tribu de Manassé, douze mille marqués;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'De la Tribu de Siméon, douze mille marqués; de la Tribu de Lévi, douze mille marqués; de la Tribu d’Issachar, douze mille marqués;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'De la Tribu de Zabulon, douze mille marqués; de la Tribu de Joseph, douze mille marqués; de la Tribu de Benjamin, douze mille marqués.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Après cela, je regardai, et voici une grande multitude de gens, que personne ne pouvait compter, de toutes nations, Tribus, peuples et Langues, lesquels se tenaient devant le trône, et en la présence de l’agneau, vêtus de longues robes blanches, et ayant des palmes en leurs mains;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'Et ils criaient à haute voix, en disant: Le salut est de notre Dieu, qui est assis sur le trône, et de l’agneau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Et tous les Anges se tenaient autour du trône, et des Anciens, et des quatre animaux, et ils se prosternèrent devant le trône sur leurs faces, et adorèrent Dieu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'En disant: Amen! louange, gloire, sagesse, actions de grâces, honneur, puissance et force soient à notre Dieu, aux siècles des siècles, Amen!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Alors un des Anciens prit la parole, et me dit: ceux-ci, qui sont vêtus de longues robes blanches, qui sont-ils, et d’où sont-ils venus?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Et je lui dis: Seigneur, tu le sais. Et il me dit: Ce sont ceux qui sont venus de la grande tribulation, et qui ont lavé et blanchi leurs longues robes dans le sang de l’agneau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'C’est pourquoi ils sont devant le trône de Dieu, et ils le servent jour et nuit dans son Temple; et celui qui est assis sur le trône habitera avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Ils n’auront plus de faim, ni de soif, et le soleil ne frappera plus sur eux, ni aucune chaleur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Car l’agneau qui est au milieu du trône les paîtra, et les conduira aux vives fontaines des eaux; et Dieu essuiera toutes les larmes de leurs yeux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'Et quand il eut ouvert le septième sceau, il se fit un silence au ciel d’environ une demie-heure.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Et je vis les sept Anges qui assistent devant Dieu, auxquels furent données sept trompettes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'Et un autre Ange vint, et se tint devant l’autel, ayant un encensoir d’or, et plusieurs parfums lui furent donnés pour offrir avec les prières de tous les Saints, sur l’autel d’or qui est devant le trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'Et la fumée des parfums avec les prières des Saints monta de la main de l’Ange devant Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Puis l’Ange prit l’encensoir, et l’ayant rempli du feu de l’autel, il le jeta en la terre; et il se fit des tonnerres, des voix, des éclairs, et un tremblement de terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'Alors les sept Anges qui avaient les sept trompettes, se préparèrent pour sonner des trompettes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Et le premier Ange sonna de la trompette, et il se fit de la grêle et du feu, mêlés de sang, qui furent jetés en la terre; et la troisième partie des arbres fut brûlée, et toute herbe verte aussi fut brûlée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Et le second Ange sonna de la trompette; et je vis comme une grande montagne ardente de feu, qui fut jetée en la mer; et la troisième partie de la mer devint du sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'Et la troisième partie des créatures vivantes qui étaient en la mer, mourut; et la troisième partie des navires périt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Et le troisième Ange sonna de la trompette, et il tomba du ciel une grande étoile ardente comme un flambeau, et elle tomba sur la troisième partie des fleuves, et dans les fontaines des eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'Le nom de l’étoile est Absinthe; et la troisième partie des eaux devint absinthe, et plusieurs des hommes moururent par les eaux, à cause qu’elles étaient devenues amères.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Puis le quatrième Ange sonna de la trompette; et la troisième partie du soleil fut frappée, et la troisième partie aussi de la lune, et la troisième partie des étoiles, de sorte que la troisième partie en fut obscurcie; et la troisième partie du jour fut privée de la lumière, et la troisième partie de la nuit fut tout de même sans clarté.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Alors je regardai, et j’entendis un Ange qui volait par le milieu du ciel, et qui disait à haute voix: Malheur! malheur! malheur! aux habitants de la terre à cause du son des trompettes des trois autres Anges qui doivent sonner de la trompette.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Alors le cinquième Ange sonna de la trompette, et je vis une étoile qui tomba du ciel en la terre, et la clef du puits de l’abîme lui fut donnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'Et il ouvrit le puits de l’abîme; et une fumée monta du puits comme la fumée d’une grande fournaise; et le soleil et l’air furent obscurcis de la fumée du puits.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'Et de la fumée du puits il sortit des sauterelles qui se répandirent par la terre, et il leur fut donné une puissance semblable à la puissance qu’ont les scorpions de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'Et il leur fut dit, qu’elles ne nuisissent point à l’herbe de la terre, ni à aucune verdure, ni à aucun arbre, mais seulement aux hommes qui n’ont point la marque de Dieu sur leurs fronts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Et il leur fut permis non de les tuer, mais de les tourmenter durant cinq mois; et leurs tourments sont semblables aux tourments que donne le scorpion quand il frappe l’homme.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Et en ces jours-là les hommes chercheront la mort, mais ils ne la trouveront point; et ils désireront de mourir, mais la mort s’enfuira d’eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Or la forme des sauterelles était semblable à des chevaux préparés pour la bataille, et sur leurs têtes il y avait comme des couronnes semblables à de l’or, et leurs faces étaient comme des faces d’hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'Et elles avaient les cheveux comme des cheveux de femmes; et leurs dents étaient comme des dents de lions.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'Et elles avaient des cuirasses comme des cuirasses de fer; et le bruit de leurs ailes était comme le bruit des chariots, quand plusieurs chevaux courent au combat.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'Et elles avaient des queues semblables à des queues de scorpions, et avaient des aiguillons en leurs queues; et leur puissance était de nuire aux hommes durant cinq mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Et elles avaient pour Roi au-dessus d’elles l’Ange de l’abîme, qui a nom en Hébreu, Abaddon, et dont le nom est en grec Apollyon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Un malheur est passé, et voici venir encore deux malheurs après celui-ci.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Alors le sixième Ange sonna de sa trompette, et j’entendis une voix sortant des quatre cornes de l’autel d’or qui est devant la face de Dieu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'Laquelle dit au sixième Ange qui avait la trompette: Délie les quatre Anges qui sont liés sur le grand fleuve Euphrate.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'On délia donc les quatre Anges qui étaient prêts pour l’heure, le jour, le mois et l’année; afin de tuer la troisième partie des hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'Et le nombre de l’armée à cheval était de deux cents millions: car j’entendis que c’était là leur nombre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Et je vis aussi dans la vision les chevaux, et ceux qui étaient montés dessus, ayant des cuirasses de feu, d’hyacinthe et de soufre; et les têtes des chevaux étaient comme des têtes de lions; et de leur bouche sortait du feu, de la fumée et du soufre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'La troisième partie des hommes fut tuée par ces trois choses, savoir par le feu, par la fumée, et par le soufre qui sortaient de leur bouche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Car leur puissance était dans leur bouche et dans leurs queues; et leurs queues étaient semblables à des serpents, et elles avaient des têtes par lesquelles elles nuisaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Mais le reste des hommes qui ne furent point tués par ces plaies, ne se repentit pas des oeuvres de leurs mains, pour ne point adorer les Démons, les idoles d’or, d’argent, de cuivre, de pierre, et de bois, qui ne peuvent ni voir, ni ouïr, ni marcher.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'Ils ne se repentirent point aussi de leurs meurtres, ni de leurs empoisonnements, ni de leur impudicité, ni de leurs larcins.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Alors je vis un autre Ange puissant, qui descendait du ciel, environné d’une nuée, sur la tête duquel était l’arc-en-ciel; et son visage était comme le soleil, et ses pieds comme des colonnes de feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'Et il avait en sa main un petit Livre ouvert, et il mit son pied droit sur la mer, et le gauche sur la terre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'Et il cria à haute voix, comme lorsqu’un lion rugit; et quand il eut crié, les sept tonnerres firent entendre leurs voix.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Et après que les sept tonnerres eurent fait entendre leurs voix, j’allais les écrire; mais j’entendis une voix du ciel qui me disait: cachette les choses que les sept tonnerres ont fait entendre, et ne les écris point.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Et l’Ange que j’avais vu se tenant sur la mer et sur la terre, leva sa main vers le ciel,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'Et jura par celui qui est vivant aux siècles des siècles, lequel a créé le ciel avec les choses qui y sont, et la terre avec les choses qui y sont, et la mer avec les choses qui y sont, qu’il n’y aurait plus de temps;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'Mais qu’aux jours de la voix du septième Ange, quand il commencera à sonner de la trompette, le mystère de Dieu sera consommé, comme il l’a déclaré à ses serviteurs les prophètes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'Et la voix du ciel que j’avais ouïe, me parla encore, et me dit: va, et prends le petit Livre ouvert, qui est en la main de l’Ange qui se tient sur la mer et sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Je m’en allai donc vers l’Ange, et je lui dis: donne-moi le petit Livre; et il me dit: prends-le, et le dévore; et il remplira tes entrailles d’amertume, mais il sera doux dans ta bouche comme du miel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Je pris donc le petit Livre de la main de l’Ange, et je le dévorai: et il était doux dans ma bouche comme du miel; mais quand je l’eus dévoré, mes entrailles furent remplies d’amertume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Alors il me dit: il faut que tu prophétises encore à plusieurs peuples, et à plusieurs nations, Langues et Rois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Alors il me fut donné un roseau semblable à une verge, et il se présenta un Ange, qui me dit: lève-toi et mesure le temple de Dieu, et l’autel, et ceux qui y adorent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Mais laisse à l’écart le parvis qui est hors du Temple, et ne le mesure point; car il est donné aux Gentils; et ils fouleront aux pieds la sainte Cité durant quarante-deux mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Mais je la donnerai à mes deux Témoins qui prophétiseront durant mille deux cent soixante jours, et ils seront vêtus de sacs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Ceux-ci sont les deux oliviers, et les deux chandeliers, qui se tiennent en la présence du Seigneur de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Et si quelqu’un leur veut nuire, le feu sort de leur bouche, et dévore leurs ennemis; car si quelqu’un leur veut nuire, il faut qu’il soit ainsi tué.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Ceux-ci ont le pouvoir de fermer le ciel, afin qu’il ne pleuve point durant les jours de leur prophétie; ils ont aussi le pouvoir de changer les eaux en sang, et de frapper la terre de toutes sortes de plaies, toutes les fois qu’ils voudront.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Et quand ils auront achevé de rendre leur témoignage, la bête qui monte de l’abîme leur fera la guerre, les vaincra, et les tuera;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'Et leurs corps morts seront étendus dans les places de la grande Cité, qui est appelée spirituellement Sodome, et Egypte; où aussi notre Seigneur a été crucifié.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Et ceux des Tribus, des peuples, des Langues, et des nations verront leurs corps morts durant trois jours et demi, et ils ne permettront point que leurs corps morts soient mis dans des sépulcres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Et les habitants de la terre en seront tout joyeux, ils en feront des réjouissances, ils s’enverront des présents les uns aux autres; parce que ces deux Prophètes auront tourmenté ceux qui habitent sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Mais après ces trois jours et demi, l’Esprit de vie venant de Dieu entra en eux, et ils se tinrent sur leurs pieds, et une grande crainte saisit ceux qui les virent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Après cela ils ouïrent une forte voix du ciel, leur disant: montez ici; et ils montèrent au ciel sur une nuée, et leurs ennemis les virent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'Et à cette même heure-là il se fit un grand tremblement de terre; et la dixième partie de la Cité tomba, et sept mille hommes furent tués par ce tremblement de terre; et les autres furent épouvantés, et donnèrent gloire au Dieu du ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Le second malheur est passé; et voici, le troisième malheur viendra bientôt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Le septième Ange donc sonna de la trompette, et il se fit entendre au ciel de grandes voix, qui disaient: Les Royaumes du monde sont soumis à notre Seigneur, et à son Christ, et il régnera aux siècles des siècles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Alors les vingt-quatre Anciens qui sont assis devant Dieu dans leurs sièges, se prosternèrent sur leurs faces, et adorèrent Dieu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'En disant: Nous te rendons grâces, Seigneur Dieu tout-puissant, QUI ES, QUI ÉTAIS, et QUI ES A VENIR, de ce que tu as fait éclater ta grande puissance, et de ce que tu as agi en Roi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Les nations se sont irritées, mais ta colère est venue, et le temps des morts est venu pour être jugés, et pour donner la récompense à tes serviteurs les Prophètes, et aux Saints, et à ceux qui craignent ton Nom, petits et grands, et pour détruire ceux qui corrompent la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Alors le Temple de Dieu fut ouvert au ciel, et l’Arche de son alliance fut vue dans son Temple; et il y eut des éclairs, des voix, des tonnerres, un tremblement de terre, et une grosse grêle.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Et un grand signe parut au Ciel, savoir, une femme revêtue du soleil, sous les pieds de laquelle était la lune, et sur sa tête une couronne de douze étoiles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Elle était enceinte, et elle criait étant en travail d’enfant, souffrant les grandes douleurs de l’enfantement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Il parut aussi un autre signe au ciel, et voici un grand dragon roux ayant sept têtes et dix cornes, et sur ses têtes sept diadèmes;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'et sa queue traînait la troisième partie des étoiles du ciel, lesquelles il jeta en la terre; puis le dragon s’arrêta devant la femme qui devait accoucher, afin de dévorer son enfant, dès qu’elle l’aurait mis au monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'Et elle accoucha d’un fils, qui doit gouverner toutes les nations avec une verge de fer; et son enfant fut enlevé vers Dieu, et vers son trône.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'Et la femme s’enfuit dans un désert, où elle a un lieu préparé de Dieu, afin qu’on la nourrisse là mille deux cent soixante jours.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Et il y eut une bataille au ciel: Michel et ses Anges combattaient contre le dragon; et le dragon et ses Anges combattaient contre Michel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'Mais ils ne furent pas les plus forts, et ils ne purent plus se maintenir dans le ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'Et le grand dragon, le serpent ancien, appelé le Diable et Satan, qui séduit le monde, fut précipité en la terre, et ses Anges furent précipités avec lui.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'Alors j’ouïs une grande voix dans le ciel, qui disait: Maintenant est le salut, la force, le règne de notre Dieu, et la puissance de son Christ; car l’accusateur de nos frères, qui les accusait devant notre Dieu jour et nuit, a été précipité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Et ils l’ont vaincu à cause du sang de l’Agneau, et à cause de la parole de leur témoignage, et ils n’ont point aimé leurs vies, mais les ont exposées à la mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'C’est pourquoi réjouissez-vous, cieux, et vous qui y habitez. Mais malheur à vous habitants de la terre et de la mer; car le Diable est descendu vers vous en grande fureur, sachant qu’il a peu de temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Or, quand le dragon eut vu qu’il avait été jeté en la terre, il persécuta la femme qui avait accouché d’un fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Mais deux ailes d’une grande aigle furent données à la femme, afin qu’elle s’envolât de devant le serpent en son lieu, où elle est nourrie par un temps, par des temps, et par la moitié d’un temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'Et le serpent jeta de sa gueule de l’eau comme un fleuve après la femme, afin de la faire emporter par le fleuve.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Mais la terre aida à la femme; car la terre ouvrit son sein, et elle engloutit le fleuve que le dragon avait jeté de sa gueule.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Alors le dragon fut irrité contre la femme, et s’en alla faire la guerre contre les autres qui sont de la semence de la femme, qui gardent les commandements de Dieu, et qui ont le témoignage de Jésus- Christ.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 18, 'Et je me tins sur le sable qui borde la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'Et je vis monter de la mer une bête qui avait sept têtes et dix cornes, et sur ses cornes dix diadèmes, et sur ses têtes un nom de blasphème.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Et la bête que je vis était semblable à un léopard, ses pieds étaient comme les pieds d’un ours; sa gueule était comme la gueule d’un lion; et le dragon lui donna sa puissance, son trône, et une grande autorité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'Et je vis l’une de ses têtes comme blessée à mort, mais sa plaie mortelle fut guérie; et toute la terre en étant dans l’admiration alla après la bête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'Et ils adorèrent le dragon qui avait donné le pouvoir à la bête, et ils adorèrent aussi la bête, en disant: qui est semblable à la bête, et qui pourra combattre contre elle?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Et il lui fut donné une bouche qui proférait de grandes choses, et des blasphèmes; et il lui fut aussi donné le pouvoir d’accomplir quarante-deux mois.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Et elle ouvrit sa bouche en blasphèmes contre Dieu, blasphémant son Nom, et son tabernacle, et ceux qui habitent au ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Et il lui fut donné de faire la guerre aux Saints, et de les vaincre. Il lui fut aussi donné puissance sur toute Tribu, Langue et nation.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'De sorte qu’elle sera adorée par tous ceux qui habitent sur la terre, desquels les noms ne sont point écrits au Livre de vie de l’Agneau, immolé dès la fondation du monde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Si quelqu’un a des oreilles, qu’il écoute.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Si quelqu’un mène en captivité, il sera mené en captivité; si quelqu’un tue avec l’épée, il faut qu’il soit lui-même tué avec l’épée. Ici est la patience et la foi des Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Puis je vis une autre bête qui montait de la terre, et qui avait deux cornes semblables à celles de l’Agneau; mais elle parlait comme le dragon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Et elle exerçait toute la puissance de la première bête, en sa présence, et faisait que la terre et ses habitants adorassent la première bête, dont la plaie mortelle avait été guérie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'Et elle faisait de grands prodiges, même jusqu’à faire descendre le feu du ciel sur la terre devant les hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'Et elle séduisait les habitants de la terre, à cause des prodiges qu’il lui était donné de faire devant la bête, commandant aux habitants de la terre de faire une image à la bête qui avait reçu le coup mortel de l’épée, et qui néanmoins était vivante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Et il lui fut permis de donner une âme à l’image de la bête, afin que même l’image de la bête parlât, et qu’elle fît que tous ceux qui n’auraient point adoré l’image de la bête, fussent mis à mort.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Et elle faisait que tous, petits et grands, riches et pauvres, libres et esclaves, prenaient une marque en leur main droite, ou en leurs fronts;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'Et qu’aucun ne pouvait acheter, ni vendre, s’il n’avait la marque ou le nom de la bête, ou le nombre de son nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Ici est la sagesse: que celui qui a de l’intelligence, compte le nombre de la bête; car c’est un nombre d’homme, et son nombre est six cent soixante-six.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Puis je regardai, et voici, l’Agneau se tenait sur la montagne de Sion, et il y avait avec lui cent quarante-quatre mille personnes, qui avaient le Nom de son Père écrit sur leurs fronts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'Et j’entendis une voix du ciel comme le bruit des grandes eaux, et comme le bruit d’un grand tonnerre; et j’entendis une voix de joueurs de harpe, qui jouaient de leurs harpes,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'Et qui chantaient comme un cantique nouveau devant le trône, et devant les quatre animaux, et devant les Anciens; et personne ne pouvait apprendre le cantique, que les cent quarante-quatre mille qui ont été achetés d’entre ceux de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Ce sont ceux qui ne se sont point souillés avec les femmes, car ils sont vierges; ce sont ceux qui suivent l’Agneau quelque part qu’il aille; et ce sont ceux qui ont été achetés d’entre les hommes pour être des prémices à Dieu, et à l’Agneau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'Et il n’a été trouvé aucune fraude en leur bouche; car ils sont sans tache devant le trône de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Puis je vis un autre Ange qui volait par le milieu du ciel, ayant l’Evangile éternel, afin d’évangéliser à ceux qui habitent sur la terre, et à toute nation, Tribu, Langue et peuple;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Disant à haute voix: Craignez Dieu, et lui donnez gloire; car l’heure de son jugement est venue; et adorez celui qui a fait le ciel et la terre, la mer et les fontaines des eaux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Et un autre Ange le suivit, disant: Elle est tombée, elle est tombée Babylone, cette grande Cité, parce qu’elle a abreuvé toutes les nations du vin de la fureur de son impudicité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Et un troisième Ange suivit ceux-là, disant à haute voix: Si quelqu’un adore la bête et son image, et qu’il en prenne la marque sur son front, ou en sa main,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'Celui-là aussi boira du vin de la colère de Dieu, du vin pur versé dans la coupe de sa colère, et il sera tourmenté de feu et de soufre devant les saints Anges, et devant l’Agneau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'Et la fumée de leur tourment montera aux siècles des siècles, et ceux-là n’auront nul repos ni jour ni nuit qui adorent la bête et son image, et quiconque prend la marque de son nom.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Ici est la patience des Saints; ici sont ceux qui gardent les commandements de Dieu, et la foi de Jésus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Alors j’entendis une voix du ciel me disant: écris: Bienheureux sont les morts qui dorénavant meurent au Seigneur; oui pour certain, dit l’Esprit; car ils se reposent de leurs travaux, et leurs oeuvres les suivent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Et je regardai, et voici une nuée blanche, et sur la nuée quelqu’un assis, semblable à un homme, ayant sur sa tête une couronne d’or, et en sa main une faucille tranchante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Et un autre Ange sortit du Temple, criant à haute voix à celui qui était assis sur la nuée: jette ta faucille, et moissonne; car c’est ton heure de moissonner, parce que la moisson de la terre est mûre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Alors celui qui était assis sur la nuée, jeta sa faucille sur la terre, et la terre fut moissonnée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Et un autre Ange sortit du Temple qui est au Ciel, ayant aussi une faucille tranchante.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Et un autre Ange sortit de l’autel, ayant puissance sur le feu; et il cria, jetant un grand cri à celui qui avait la faucille tranchante, disant: jette ta faucille tranchante, et vendange les grappes de la vigne de la terre, car ses raisins sont mûrs.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Et l’Ange jeta en la terre sa faucille tranchante: et vendangea la vigne de la terre, et il jeta la vendange en la grande cuve de la colère de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'Et la cuve fut foulée hors de la Cité; et de la cuve il sortit du sang qui allait jusqu’aux freins des chevaux dans l’étendue de mille six cents stades.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Puis je vis au ciel un autre signe, grand et admirable, savoir sept Anges qui avaient les sept dernières plaies; car c’est par elles que la colère de Dieu est consommée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Je vis aussi comme une mer de verre mêlée de feu, et ceux qui avaient obtenu la victoire sur la bête, sur son image, sur sa marque, et sur le nombre de son nom, se tenant sur la mer qui était comme de verre, et ayant les harpes de Dieu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'Qui chantaient le Cantique de Moïse serviteur de Dieu, et le Cantique de l’Agneau, en disant: que tes oeuvres sont grandes et merveilleuses, ô Seigneur Dieu tout-puissant! tes voies sont justes et véritables, ô Roi des Saints!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Seigneur, qui ne te craindra, et qui ne glorifiera ton Nom? car tu es Saint toi seul, c’est pourquoi toutes les nations viendront et se prosterneront devant toi; car tes jugements sont pleinement manifestés.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Et après ces choses je regardai, et voici le Temple du Tabernacle du témoignage fut ouvert au ciel.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'Et les sept Anges qui avaient les sept plaies sortirent du Temple, vêtus d’un lin pur et blanc, et ceints sur leurs poitrines avec des ceintures d’or.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'Et l’un des quatre animaux donna aux sept Anges sept fioles d’or, pleines de la colère du Dieu vivant aux siècles des siècles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'Et le Temple fut rempli de la fumée qui procédait de la majesté de Dieu et de sa puissance; et personne ne pouvait entrer dans le Temple jusqu’à ce que les sept plaies des sept Anges fussent accomplies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Alors j’ouïs du Temple une voix éclatante, qui disait aux sept Anges: allez, et versez sur la terre les fioles de la colère de Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Ainsi le premier Ange s’en alla, et versa sa fiole sur la terre; et un ulcère malin et dangereux attaqua les hommes qui avaient la marque de la bête, et ceux qui adoraient son image.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Et le second Ange versa sa fiole sur la mer, et elle devint comme le sang d’un corps mort, et toute âme qui vivait dans la mer, mourut.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Et le troisième Ange versa sa fiole sur les fleuves, et sur les fontaines des eaux, et elles devinrent du sang.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Et j’entendis l’Ange des eaux, qui disait: Seigneur, QUI ES, QUI ÉTAIS, et QUI SERAS, tu es juste, parce que tu as fait un tel jugement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'A cause qu’ils ont répandu le sang des Saints et des Prophètes, tu leur as aussi donné du sang à boire; car ils en sont dignes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Et j’en ouïs un autre du Sanctuaire, disant: certainement Seigneur Dieu tout-puissant, tes jugements sont véritables, et justes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Puis le quatrième Ange versa sa fiole sur le soleil, et le pouvoir lui fut donné de brûler les hommes par le feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'De sorte que les hommes furent brûlés par de grandes chaleurs, et ils blasphémèrent le Nom de Dieu qui a puissance sur ces plaies; mais ils ne se repentirent point pour lui donner gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Après cela le cinquième Ange versa sa fiole sur le siège de la bête, et le règne de la bête devint ténébreux, et les hommes se mordaient la langue à cause de la douleur qu’ils ressentaient.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'Et à cause de leurs peines et de leurs plaies ils blasphémèrent le Dieu du Ciel; et ne se repentirent point de leurs oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Puis le sixième Ange versa sa fiole sur le grand fleuve d’Euphrate, et l’eau de ce fleuve tarit, afin que la voie des Rois de devers le soleil levant fût ouverte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'Et je vis sortir de la gueule du dragon, et de la gueule de la bête, et de la bouche du faux prophète, trois esprits immondes, semblables à des grenouilles;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Car ce sont des esprits diaboliques, faisant des prodiges, et qui s’en vont vers les Rois de la terre et du monde universel, pour les assembler pour le combat de ce grand jour du Dieu tout-puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, 'Voici, je viens comme le larron; bienheureux est celui qui veille, et qui garde ses vêtements, afin de ne marcher point nu, et qu’on ne voie point sa honte.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Et il les assembla au lieu qui est appelé en Hébreu Armageddon.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Puis le septième Ange versa sa fiole dans l’air; et il sortit du Temple du Ciel une voix tonnante qui procédait du trône, disant: c’est fait.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'Alors il se fit des éclairs, et des voix, et des tonnerres, et il se fit un grand tremblement de terre, un tel tremblement, dis-je, et si grand, qu’il n’y en eut jamais de semblable depuis que les hommes ont été sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'Et la grande Cité fut divisée en trois parties, et les villes des nations tombèrent; et la grande Babylone vint en mémoire devant Dieu, pour lui donner la coupe du vin de l’indignation de sa colère.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Et toute île s’enfuit, et les montagnes ne furent plus trouvées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'Et il descendit du ciel sur les hommes une grêle prodigieuse du poids d’un talent; et les hommes blasphémèrent Dieu à cause de la plaie de la grêle; car la plaie qu’elle fit fut fort grande.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Alors l’un des sept Anges qui avaient les sept fioles, vint, et il me parla, et me dit: Viens, je te montrerai la condamnation de la grande prostituée, qui est assise sur plusieurs eaux;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'Avec laquelle les Rois de la terre ont commis fornication, et qui a enivré du vin de sa prostitution les habitants de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Ainsi il me transporta en esprit dans un désert; et je vis une femme montée sur une bête de couleur d’écarlate, pleine de noms de blasphème, et qui avait sept têtes et dix cornes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Et la femme était vêtue de pourpre et d’écarlate, et parée d’or, de pierres précieuses, et de perles; et elle tenait à la main une coupe d’or, pleine des abominations de l’impureté de sa prostitution.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'Et il y avait sur son front un nom écrit, mystère, la grande Babylone, la mère des impudicités et des abominations de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Et je vis la femme enivrée du sang des Saints, et du sang des martyrs de Jésus; et quand je la vis je fus saisi d’un grand étonnement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Et l’Ange me dit: pourquoi t’étonnes-tu? je te dirai le mystère de la femme et de la bête qui la porte, laquelle a sept têtes et dix cornes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'La bête que tu as vue, a été, et n’est plus, mais elle doit monter de l’abîme, et puis être détruite; et les habitants de la terre, dont les noms ne sont point écrits au Livre de vie dès la fondation du monde, s’étonneront voyant la bête qui était, qui n’est plus, et qui toutefois est.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'C’est ici qu’est l’intelligence pour quiconque a de la sagesse. Les sept têtes sont sept montagnes sur lesquelles la femme est assise.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'Ce sont aussi sept Rois, les cinq sont tombés; l’un est, et l’autre n’est pas encore venu; et quand il sera venu, il faut qu’il demeure pour un peu de temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Et la bête qui était, et qui n’est plus, c’est aussi un huitième Roi, elle vient des sept, mais elle tend à sa ruine.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Et les dix cornes que tu as vues, sont dix Rois, qui n’ont pas encore commencé à régner, mais ils prendront puissance comme Rois, en même temps avec la bête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Ceux-ci ont un même dessein, et ils donneront leur puissance et leur autorité à la bête.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Ceux-ci combattront contre l’Agneau; mais l’Agneau les vaincra; parce qu’il est le Seigneur des Seigneurs, et le Roi des Rois; et ceux qui sont avec lui, sont du nombre des appelés, des élus et des fidèles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Puis il me dit: Les eaux que tu as vues, et sur lesquelles la prostituée est assise, sont des peuples, des nations et des Langues.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Mais les dix cornes que tu as vues à la bête, sont ceux qui haïront la prostituée, qui la désoleront, la dépouilleront, et mangeront sa chair, et la brûleront au feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Car Dieu a mis dans leurs coeurs de faire ce qu’il lui plaît, et de former un même dessein, et de donner leur Royaume à la bête, jusqu’à ce que les paroles de Dieu soient accomplies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Et la femme que tu as vue, c’est la grande Cité, qui a son règne sur les Rois de la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Après ces choses je vis descendre du ciel un autre Ange, qui avait une grande puissance, et la terre fut illuminée de sa gloire.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Il cria avec force à haute voix, et il dit: Elle est tombée, elle est tombée la grande Babylone, et elle est devenue la demeure des Démons, et la retraite de tout esprit immonde, et le repaire de tout oiseau immonde et exécrable.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Car toutes les nations ont bu du vin de sa prostitution effrénée; et les Rois de la terre ont commis fornication avec elle; et les marchands de la terre sont devenus riches de l’excès de son luxe.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Puis j’entendis une autre voix du ciel, qui disait: Sortez de Babylone mon peuple, afin que vous ne participiez point à ses péchés, et que vous ne receviez point de ses plaies.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Car ses péchés sont montés jusqu’au ciel, et Dieu s’est souvenu de ses iniquités.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Rendez-lui ainsi qu’elle vous a fait, et payez-lui au double selon ses oeuvres; et dans la même coupe où elle vous a versé à boire, versez-lui-en au double.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Autant qu’elle s’est glorifiée, et qu’elle a été dans les délices, donnez-lui autant de tourment et d’affliction; car elle dit en son coeur: je siège en Reine, je ne suis point veuve, et je ne verrai point de deuil.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'C’est pourquoi ses plaies, qui sont la mort, le deuil, et la famine, viendront en un même jour, et elle sera entièrement brûlée au feu; car le Seigneur Dieu qui la jugera, est puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Et les Rois de la terre, qui ont commis fornication avec elle, et qui ont vécu dans les délices, la pleureront, et mèneront deuil sur elle en se battant la poitrine, quand ils verront la fumée de son embrasement;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Et ils se tiendront loin pour la crainte de son tourment, et diront: hélas! hélas! Babylone, la grande Cité, cette Cité si puissante, comment ta condamnation est-elle venue en un moment?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Les marchands de la terre aussi pleureront, et mèneront deuil à cause d’elle, parce que personne n’achète plus de leur marchandise;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'Qui sont des marchandises d’or, d’argent, de pierres précieuses, de perles, de fin lin, de pourpre, de soie, d’écarlate, de toute sorte de bois odoriférant, de toute espèce de meubles d’ivoire, et de toute espèce de vaisseaux de bois très précieux, d’airain, de fer, et de marbre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'Du cinnamome, des parfums, des essences, de l’encens, du vin, de l’huile, de la fine fleur de farine, du blé, des bêtes de charge, des brebis, des chevaux, des chariots, des esclaves, et des âmes d’hommes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Car les fruits du désir de ton âme se sont éloignés de toi; et toutes les choses délicates et excellentes sont péries pour toi; et dorénavant tu ne trouveras plus ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Les marchands, dis-je, de ces choses, qui en sont devenus riches, se tiendront loin d’elle, pour la crainte de son tourment, pleurant et menant deuil;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'Et disant: hélas! hélas! la grande Cité, qui était vêtue de fin lin, de pourpre, d’écarlate, qui était parée d’or, ornée de pierres précieuses, et de perles, comment en un instant ont été dissipées tant de richesses?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'Tout pilote aussi, toute la troupe de ceux qui montent sur les navires, tous les matelots, et tous ceux qui trafiquent sur la mer, se tiendront loin;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'Et voyant la fumée de son embrasement, ils s’écrieront en disant: quelle cité était semblable à cette grande Cité!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'Ils jetteront de la poussière sur leurs têtes, pleurant, et menant deuil, ils crieront en disant: hélas! hélas! la grande Cité, dans laquelle tous ceux qui avaient des navires sur la mer, étaient devenus riches par son opulence; comment a-t-elle été désolée en un moment?');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Ô ciel! réjouis-toi à cause d’elle; et vous aussi, saints Apôtres et Prophètes réjouissez-vous: car Dieu l’a punie à cause de vous.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Puis un Ange d’une grande force prit une pierre, qui était comme une grande meule, et la jeta dans la mer, en disant: Ainsi sera jetée avec impétuosité Babylone, cette grande Cité; et elle ne sera plus trouvée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'Et la voix des joueurs de harpe, des musiciens, des joueurs de hautbois, et de ceux qui sonnent de la trompette, ne sera plus ouïe en toi; et tout ouvrier de quelque métier que ce soit, ne sera plus trouvé en toi; et le bruit de la meule ne sera plus ouï en toi.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'Et la lumière de la chandelle ne luira plus en toi; et la voix de l’époux et de l’épouse ne sera plus ouïe en toi; parce que tes marchands étaient des Princes en la terre; et parce que par tes empoisonnements toutes les nations ont été séduites.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'Et en elle a été trouvé le sang des Prophètes, et des Saints, et de tous ceux qui ont été mis à mort sur la terre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Or après ces choses, j’entendis une voix d’une grande multitude au Ciel, disant: Alleluia! le salut, la gloire, l’honneur et la puissance appartiennent au Seigneur notre Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Car ses jugements sont véritables et justes, parce qu’il a fait justice de la grande prostituée, qui a corrompu la terre par son impudicité; et qu’il a vengé le sang de ses serviteurs versé de la main de la prostituée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'Et ils dirent encore: Alleluia! et sa fumée monte aux siècles des siècles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Et les vingt-quatre Anciens et les quatre animaux se jetèrent sur leurs faces, et adorèrent Dieu, qui était assis sur le trône, en disant: Amen! Alleluia!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Et il sortit du trône une voix qui disait: louez notre Dieu, vous tous ses serviteurs, et vous qui le craignez, tant les petits que les grands.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'J’entendis ensuite comme la voix d’une grande assemblée, et comme le bruit de grandes eaux, et comme l’éclat de grands tonnerres, disant: Alleluia! car le Seigneur notre Dieu tout-puissant a pris possession de son Royaume.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Réjouissons-nous, tressaillons de joie, et donnons-lui gloire; car les noces de l’Agneau sont venues, et son épouse s’est parée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'Et il lui a été donné d’être vêtue de fin lin pur et éclatant. Or ce fin lin désigne la justice des Saints.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'Alors il me dit: Ecris: Bienheureux sont ceux qui sont appelés au banquet des noces de l’Agneau. Il me dit aussi: ces paroles de Dieu sont véritables.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Alors je me jetai à ses pieds pour l’adorer; mais il me dit: garde-toi de le faire; je suis ton compagnon de service, et le compagnon de tes frères qui ont le témoignage de Jésus, adore Dieu; car le témoignage de Jésus est l’Esprit de prophétie.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Puis je vis le Ciel ouvert, et voici un cheval blanc; et celui qui était monté dessus était appelé FIDÈLE et VÉRITABLE, qui juge et combat justement.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Et ses yeux étaient comme une flamme de feu; il y avait sur sa tête plusieurs diadèmes, et il portait un nom écrit que nul n’a connu, que lui seul.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'Il était vêtu d’une robe teinte dans le sang, et son nom s’appelle LA PAROLE DE DIEU.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'Et les armées qui sont au Ciel le suivaient sur des chevaux blancs, vêtues de fin lin blanc, et pur.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'Et il sortait de sa bouche une épée tranchante, pour en frapper les nations; car il les gouvernera avec une verge de fer, et il foulera la cuve du vin de l’indignation et de la colère du Dieu tout- puissant.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Et sur son vêtement et sur sa cuisse étaient écrits ces mots: LE ROI DES ROIS, ET LE SEIGNEUR DES SEIGNEURS.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Puis je vis un Ange se tenant dans le soleil, qui cria à haute voix, et dit à tous les oiseaux qui volaient par le milieu du ciel: venez, et assemblez vous au banquet du grand Dieu;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'Afin que vous mangiez la chair des Rois, la chair des capitaines, la chair des puissants, la chair des chevaux, et de ceux qui sont montés dessus, et la chair de toute sorte de personnes libres, esclaves, petits et grands.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Alors je vis la bête, et les Rois de la terre, et leurs armées assemblées pour faire la guerre contre celui qui était monté sur le cheval, et contre son armée.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Mais la bête fut prise, et avec elle le faux-prophète qui avait fait devant elle les prodiges par lesquels il avait séduit ceux qui avaient la marque de la bête, et qui avaient adoré son image; et ils furent tous deux jetés tout vifs dans l’étang ardent de feu et de soufre;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'Et le reste fut tué par l’épée qui sortait de la bouche de celui qui était monté sur le cheval, et tous les oiseaux furent rassasiés de leur chair.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Après cela je vis descendre du Ciel un Ange, qui avait la clef de l’abîme, et une grande chaîne en sa main;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'Lequel saisit le dragon, c’est-à-dire, le serpent ancien, qui est le Diable et satan, et le lia pour mille ans;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'Et il le jeta dans l’abîme, et l’enferma, et mit le sceau sur lui, afin qu’il ne séduise plus les nations, jusqu’à ce que les mille ans soient accomplis; après quoi il faut qu’il soit délié pour un peu de temps.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Et je vis des trônes, sur lesquels des gens s’assirent, et l’autorité de juger leur fut donnée, et je vis les âmes de ceux qui avaient été décapités pour le témoignage de Jésus, et pour la Parole de Dieu, qui n’avaient point adoré la bête ni son image, et qui n’avaient point pris sa marque en leurs fronts, ou en leurs mains, lesquels devaient vivre et régner avec Christ mille ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Mais le reste des morts ne doit point ressusciter jusqu’à ce que les mille ans soient accomplis; c’est la première résurrection.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Bienheureux et saint est celui qui a part à la première résurrection; la mort seconde n’a point de puissance sur eux, mais ils seront Sacrificateurs de Dieu, et de Christ, et ils régneront avec lui mille ans.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Et quand les mille ans seront accomplis, satan sera délié de sa prison;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'Et il sortira pour séduire les nations qui sont aux quatre coins de la terre, Gog et Magog; pour les assembler en bataille, et leur nombre est comme le sable de la mer.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'Et ils montèrent et se répandirent sur la largeur de la terre, et ils environnèrent le camp des Saints, et la Cité bien-aimée, mais Dieu fit descendre du feu du Ciel, qui les dévora.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'Et le Diable qui les séduisait, fut jeté dans l’étang de feu et de soufre, où est la bête et le faux-prophète; et ils seront tourmentés jour et nuit, aux siècles des siècles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Puis je vis un grand trône blanc, et quelqu’un assis dessus, de devant lequel s’enfuit la terre et le ciel; et il ne se trouva point de lieu pour eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Je vis aussi les morts grands et petits se tenant devant Dieu, et les Livres furent ouverts; et un autre Livre fut ouvert, qui était le Livre de vie; et les morts furent jugés sur les choses qui étaient écrites dans les Livres, c’est-à-dire, selon leurs oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'Et la mer rendit les morts qui étaient en elle, et la mort et l’enfer rendirent les morts qui étaient en eux; et ils furent jugés chacun selon ses oeuvres.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Et la mort et l’enfer furent jetés dans l’étang de feu: c’est la mort seconde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Et quiconque ne fut pas trouvé écrit au Livre de vie, fut jeté dans l’étang de feu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Puis je vis un nouveau Ciel et une nouvelle terre; car le premier ciel et la première terre avaient disparu, et la mer n’était plus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Et moi, Jean, je vis la sainte Cité, la nouvelle Jérusalem, qui descendait du Ciel, de devers Dieu, parée comme une épouse qui s’est ornée pour son mari.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'Et j’entendis une grande voix du ciel, disant: voici le Tabernacle de Dieu avec les hommes, et il habitera avec eux; et ils seront son peuple, et Dieu lui-même sera leur Dieu, et il sera avec eux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'Et Dieu essuiera toutes larmes de leurs yeux, et la mort ne sera plus; et il n’y aura plus ni deuil, ni cri, ni travail; car les premières choses sont passées.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Et celui qui était assis sur le trône, dit: voici, je fais toutes choses nouvelles. Puis il me dit: Ecris, car ces paroles sont véritables et certaines.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Il me dit aussi: tout est accompli; je suis l’Alpha et l’Oméga, le commencement, et la fin. A celui qui aura soif je lui donnerai de la fontaine d’eau vive, sans qu’elle lui coûte rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Celui qui vaincra, héritera toutes choses; et je lui serai Dieu, et il me sera fils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Mais quant aux timides, aux incrédules, aux exécrables, aux meurtriers, aux fornicateurs, aux empoisonneurs, aux idolâtres et à tous menteurs, leur part sera dans l’étang ardent de feu et de soufre, qui est la mort seconde.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Alors un des sept Anges qui avaient eu les sept fioles pleines des sept dernières plaies, s’approcha de moi et me parla en disant: Viens et je te montrerai l’Epouse, qui est la femme de l’Agneau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Et il me transporta en esprit sur une grande et haute montagne, et il me montra la grande Cité, la sainte Jérusalem, qui descendait du Ciel de devers Dieu,');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'Ayant la gloire de Dieu; et sa lumière était semblable à une pierre très précieuse, comme à une pierre de jaspe tirant sur le cristal.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Et elle avait une grande et haute muraille, avec douze portes, et aux portes douze Anges; et des noms écrits sur elles, qui sont les noms des douze Tribus des enfants d’Israël.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'Du côté de l’Orient, trois portes; du côté de l’Aquilon, trois portes; du côté du Midi, trois portes; et du côté de l’Occident, trois portes.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'Et la muraille de la Cité avait douze fondements, et les noms des douze Apôtres de l’Agneau étaient écrits dessus.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'Et celui qui parlait avec moi avait un roseau d’or pour mesurer la Cité, ses portes et sa muraille.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'Et la cité était bâtie en carré, et sa longueur était aussi grande que sa largeur. Il mesura donc la Cité avec le roseau d’or, jusqu’à douze mille stades; la longueur, la largeur et la hauteur étaient égales.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Puis il mesura la muraille, qui fut de cent quarante-quatre coudées, de la mesure du personnage, c’est-à-dire, de l’Ange.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'Et le bâtiment de la muraille était de jaspe, mais la Cité était d’or pur, semblable à du verre fort transparent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Et les fondements de la muraille de la Cité étaient ornés de toute pierre précieuse: le premier fondement était de jaspe; le second, de saphir; le troisième, de calcédoine; le quatrième, d’émeraude;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'Le cinquième, de sardonyx; le sixième, de sardoine; le septième, de chrysolithe; le huitième, de béryl; le neuvième, de topaze; le dixième, de chrysoprase; le onzième, d’hyacinthe; le douzième, d’améthyste.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Et les douze portes étaient douze perles; chacune des portes était d’une perle; et la rue de la cité était d’or pur, comme du verre le plus transparent.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Et je ne vis point de Temple en elle; parce que le Seigneur Dieu Tout-puissant et l’Agneau en sont le Temple.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'Et la Cité n’a pas besoin du soleil ni de la lune, pour luire en elle; car la clarté de Dieu l’a éclairée, et l’Agneau est son flambeau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'Et les nations qui auront été sauvées, marcheront à la faveur de sa lumière; et les Rois de la terre y apporteront ce qu’ils ont de plus magnifique et de plus précieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Et ses portes ne seront point fermées de jour; or il n’y aura point là de nuit.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'Et on y apportera ce que les Gentils ont de plus magnifique et de plus précieux.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'Il n’y entrera aucune chose souillée, ni personne qui s’abandonne à l’abomination et au mensonge; mais seulement ceux qui sont écrits au Livre de vie de l’Agneau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Puis il me montra un fleuve pur d’eau vive, transparent comme du cristal, qui sortait du trône de Dieu et de l’Agneau.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Et au milieu de la place de la Cité, et des deux côtés du fleuve était l’arbre de vie, portant douze fruits, et rendant son fruit chaque mois; et les feuilles de l’arbre sont pour la santé des Gentils.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Et toute chose maudite ne sera plus, mais le trône de Dieu et de l’Agneau sera en elle, et ses serviteurs le serviront;');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'Et ils verront sa face, et son Nom sera sur leurs fronts.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Et il n’y aura plus là de nuit; et il ne sera plus besoin de la lumière de la lampe ni du soleil: car le Seigneur Dieu les éclaire, et ils régneront aux siècles des siècles.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'Puis il me dit: ces paroles sont certaines et véritables, et le Seigneur le Dieu des saints Prophètes a envoyé son Ange, pour manifester à ses serviteurs les choses qui doivent arriver bientôt.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Voici, je viens bientôt; bienheureux est celui qui garde les paroles de la prophétie de ce Livre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Et moi Jean, je suis celui qui ai ouï et vu ces choses; et après les avoir ouïes et vues, je me jetai à terre pour me prosterner aux pieds de l’Ange qui me montrait ces choses.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Mais il me dit: garde-toi de le faire; car je suis ton Compagnon de service, et le Compagnon de tes frères les Prophètes, et de ceux qui gardent les paroles de ce Livre; adore Dieu.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Il me dit aussi: ne cachette point les paroles de la prophétie de ce Livre, parce que le temps est proche.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Que celui qui est injuste, soit injuste encore; et que celui qui est souillé se souille encore; et que celui qui est juste, soit plus juste encore; et que celui qui est saint, soit sanctifié encore.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Or voici, je viens bientôt; et ma récompense est avec moi, pour rendre à chacun selon son oeuvre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Je suis l’Alpha et l’Oméga, le premier et le dernier, le commencement et la fin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Bienheureux sont ceux qui font ses commandements, afin qu’ils aient droit à l’Arbre de vie, et qu’ils entrent par les portes dans la Cité.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Mais les Chiens, les empoisonneurs, les fornicateurs, les meurtriers, les idolâtres, et quiconque aime et commet fausseté seront laissés dehors.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Moi Jésus, j’ai envoyé mon Ange pour vous confirmer ces choses dans les Eglises. Je suis la racine et la postérité de David; l’étoile brillante du matin.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'Et l’Esprit et l’Epouse disent: viens.; que celui aussi qui l’entend, dise: viens; et que celui qui a soif, vienne; et quiconque veut de l’eau vive, en prenne, sans qu’elle lui coûte rien.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Or je proteste à quiconque entend les paroles de la prophétie de ce Livre, que si quelqu’un ajoute à ces choses, Dieu fera tomber sur lui les plaies écrites dans ce Livre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'Et si quelqu’un retranche quelque chose des paroles du Livre de cette prophétie, Dieu lui enlèvera la part qu’il a dans le Livre de vie, dans la sainte Cité, et dans les choses qui sont écrites dans ce Livre.');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Celui qui rend témoignage de ces choses, dit: Certainement je viens bientôt, Amen! Oui, Seigneur Jésus, viens!');
INSERT INTO `FreBDM1744_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Que la grâce de notre Seigneur Jésus-Christ soit avec vous tous, Amen!');
